[RequireComponent(typeof(AudioSource))]
public class AudioSourceClipRandomizer : MonoBehaviour
{
	[SerializeField]
	private AudioClip[] clips;

	private AudioSource source;

	private bool playOnAwake;

	private void Awake()
	{
		source = GetComponent<AudioSource>();
		playOnAwake = source.playOnAwake;
		source.playOnAwake = false;
	}

	public void Play()
	{
		int num = UnityEngine.Random.Range(0, 60);
		if (GorillaComputer.instance != null)
		{
			num = GorillaComputer.instance.GetServerTime().Second;
		}
		source.clip = clips[num % clips.Length];
		source.GTPlay();
	}

	private void OnEnable()
	{
		if (playOnAwake)
		{
			Play();
		}
	}
}
public class AudioSourceEventTargets : MonoBehaviour
{
	private AudioSource audioSource;

	private float fadeVolume;

	private float fadeSpeed;

	[Header("Change Value To Trigger Play (false to true and true to false both work, but value must change the frame you want it played)")]
	public bool ExternalTriggerPlay;

	private bool lastExternalTriggerPlayMatched = true;

	private bool lastValueWhenPlayed;

	[Header("Change Value To Trigger Stop (false to true and true to false both work, but value must change the frame you want it stopped)")]
	public bool ExternalTriggerStop;

	private bool lastExternalTriggerStopMatched = true;

	private bool lastValueWhenStopped;

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
		fadeVolume = audioSource.volume;
	}

	public void SetFadeSpeed(float arg)
	{
		fadeSpeed = Mathf.Max(arg, 0.01f);
	}

	public void StartFade(float arg)
	{
		fadeVolume = Mathf.Clamp01(arg);
	}

	public void Update()
	{
		if (audioSource.volume != fadeVolume)
		{
			audioSource.volume = Mathf.MoveTowards(audioSource.volume, fadeVolume, fadeSpeed * Time.deltaTime);
		}
		if (lastValueWhenPlayed != ExternalTriggerPlay)
		{
			if (!lastExternalTriggerPlayMatched)
			{
				audioSource.Play();
				lastValueWhenPlayed = ExternalTriggerPlay;
				lastExternalTriggerPlayMatched = true;
			}
			else
			{
				ExternalTriggerPlay = lastValueWhenPlayed;
				lastExternalTriggerPlayMatched = false;
			}
		}
		else
		{
			lastExternalTriggerPlayMatched = true;
		}
		if (lastValueWhenStopped != ExternalTriggerStop)
		{
			if (!lastExternalTriggerStopMatched)
			{
				audioSource.Stop();
				lastValueWhenStopped = ExternalTriggerStop;
				lastExternalTriggerStopMatched = true;
			}
			else
			{
				ExternalTriggerStop = lastValueWhenStopped;
				lastExternalTriggerStopMatched = false;
			}
		}
		else
		{
			lastExternalTriggerStopMatched = true;
		}
	}
}
public class ParentedObjectStressTestMain : MonoBehaviour
{
	public GameObject Object;

	public UnityEngine.Vector3 NumObjects;

	public UnityEngine.Vector3 Spacing;

	public void Start()
	{
		for (int i = 0; i < (int)NumObjects.x; i++)
		{
			for (int j = 0; j < (int)NumObjects.y; j++)
			{
				for (int k = 0; k < (int)NumObjects.z; k++)
				{
					UnityEngine.Object.Instantiate(Object).transform.position = new UnityEngine.Vector3(2f * ((float)i / (NumObjects.x - 1f) - 0.5f) * NumObjects.x * Spacing.x, 2f * ((float)j / (NumObjects.y - 1f) - 0.5f) * NumObjects.y * Spacing.y, 2f * ((float)k / (NumObjects.z - 1f) - 0.5f) * NumObjects.z * Spacing.z);
				}
			}
		}
	}
}
public class JellyfishUFOCamera : MonoBehaviour
{
	public Transform Target;

	private BoingKit.Vector3Spring m_spring;

	private void Start()
	{
		if (!(Target == null))
		{
			m_spring.Reset(Target.transform.position);
		}
	}

	private void FixedUpdate()
	{
		if (!(Target == null))
		{
			m_spring.TrackExponential(Target.transform.position, 0.5f, Time.fixedDeltaTime);
			UnityEngine.Vector3 normalized = (m_spring.Value - base.transform.position).normalized;
			base.transform.rotation = UnityEngine.Quaternion.LookRotation(normalized);
		}
	}
}
public class LengthStiffnessComparison : MonoBehaviour
{
	public float Run = 11f;

	public float Tilt = 15f;

	public float Period = 3f;

	public float Rest = 3f;

	public Transform BonesA;

	public Transform BonesB;

	private float m_timer;

	private void Start()
	{
		m_timer = 0f;
	}

	private void FixedUpdate()
	{
		BoingBones[] components = BonesA.GetComponents<BoingBones>();
		BoingBones[] components2 = BonesB.GetComponents<BoingBones>();
		Transform[] array = new Transform[2] { BonesA.transform, BonesB.transform };
		IEnumerable<BoingBones> enumerable = components.Concat(components2);
		float fixedDeltaTime = Time.fixedDeltaTime;
		float num = 0.5f * Run;
		m_timer += fixedDeltaTime;
		Transform[] array2;
		if (m_timer > Period + Rest)
		{
			m_timer = Mathf.Repeat(m_timer, Period + Rest);
			array2 = array;
			foreach (Transform obj in array2)
			{
				UnityEngine.Vector3 position = obj.position;
				position.z = 0f - num;
				obj.position = position;
			}
			foreach (BoingBones item in enumerable)
			{
				item.Reboot();
			}
		}
		float num2 = Mathf.Min(1f, m_timer * BoingKit.MathUtil.InvSafe(Period));
		float num3 = 1f - Mathf.Pow(1f - num2, 6f);
		array2 = array;
		foreach (Transform obj2 in array2)
		{
			UnityEngine.Vector3 position2 = obj2.position;
			position2.z = Mathf.Lerp(0f - num, num, num3);
			obj2.position = position2;
			obj2.rotation = UnityEngine.Quaternion.AngleAxis(Tilt * (1f - num3), UnityEngine.Vector3.right);
		}
	}
}
public class PoseStiffnessComparison : MonoBehaviour
{
	public float Run = 11f;

	public float Tilt = 15f;

	public float Period = 3f;

	public float Rest = 3f;

	public Transform BonesA;

	public Transform BonesB;

