public class OrbitCamera : MonoBehaviour
{
	private static readonly float kOrbitSpeed = 0.01f;

	private float m_phase;

	public void Start()
	{
	}

	public void Update()
	{
		m_phase += kOrbitSpeed * BoingKit.MathUtil.TwoPi * Time.deltaTime;
		base.transform.position = new UnityEngine.Vector3(-4f * Mathf.Cos(m_phase), 6f, 4f * Mathf.Sin(m_phase));
		base.transform.rotation = UnityEngine.Quaternion.LookRotation((new UnityEngine.Vector3(0f, 3f, 0f) - base.transform.position).normalized);
