	private bool m_prevFrameHasFocus;

	private UnityEngine.Vector3 m_prevMousePosition;

	private UnityEngine.Vector3 m_euler;

	private void Start()
	{
		m_currFrameHasFocus = false;
		m_prevFrameHasFocus = false;
	}

	private void Update()
	{
		m_currFrameHasFocus = UnityEngine.Application.isFocused;
		bool prevFrameHasFocus = m_prevFrameHasFocus;
