		if (prevFrameHasFocus || m_currFrameHasFocus)
		{
			UnityEngine.Vector3 mousePosition = Input.mousePosition;
			UnityEngine.Vector3 prevMousePosition = m_prevMousePosition;
			UnityEngine.Vector3 vector = mousePosition - prevMousePosition;
			m_prevMousePosition = mousePosition;
