public class Oscillator : MonoBehaviour
{
	public enum WaveTypeEnum
	{
		Sine,
		Square,
		Triangle
	}

	public WaveTypeEnum WaveType;

	private UnityEngine.Vector3 m_initCenter;

	public bool UseCenter;

	public UnityEngine.Vector3 Center;

	public UnityEngine.Vector3 Radius;

	public UnityEngine.Vector3 Frequency;

	public UnityEngine.Vector3 Phase;

	public void Init(UnityEngine.Vector3 center, UnityEngine.Vector3 radius, UnityEngine.Vector3 frequency, UnityEngine.Vector3 startPhase)
	{
		Center = center;
		Radius = radius;
		Frequency = frequency;
		Phase = startPhase;
	}

	private float SampleWave(float phase)
	{
		switch (WaveType)
		{
		case WaveTypeEnum.Sine:
			return Mathf.Sin(phase);
		case WaveTypeEnum.Square:
			phase = Mathf.Repeat(phase, MathF.PI * 2f);
			if (!(phase < MathF.PI))
			{
				return -1f;
			}
			return 1f;
		case WaveTypeEnum.Triangle:
			phase = Mathf.Repeat(phase, MathF.PI * 2f);
			if (phase < MathF.PI / 2f)
			{
				return phase / (MathF.PI / 2f);
			}
			if (phase < MathF.PI)
			{
				return 1f - (phase - MathF.PI / 2f) / (MathF.PI / 2f);
			}
			if (phase < 4.712389f)
			{
				return (MathF.PI - phase) / (MathF.PI / 2f);
			}
			return (phase - 4.712389f) / (MathF.PI / 2f) - 1f;
		default:
			return 0f;
		}
	}

	public void OnEnable()
	{
		m_initCenter = base.transform.position;
	}

	public void Update()
	{
		Phase += Frequency * 2f * MathF.PI * Time.deltaTime;
		UnityEngine.Vector3 position = (UseCenter ? Center : m_initCenter);
		position.x += Radius.x * SampleWave(Phase.x);
		position.y += Radius.y * SampleWave(Phase.y);
		position.z += Radius.z * SampleWave(Phase.z);
		base.transform.position = position;
	}
}
public class RotationStepper : MonoBehaviour
{
	public enum ModeEnum
	{
		Fixed,
		Random
	}

	public ModeEnum Mode;

	[ConditionalField("Mode", ModeEnum.Fixed, null, null, null, null, null)]
	public float Angle = 25f;

	public float Frequency;

	private float m_phase;

	public void OnEnable()
	{
		m_phase = 0f;
		UnityEngine.Random.InitState(0);
	}

	public void Update()
	{
		m_phase += Frequency * Time.deltaTime;
		switch (Mode)
		{
		default:
			return;
		case ModeEnum.Fixed:
			base.transform.rotation = UnityEngine.Quaternion.Euler(0f, 0f, (Mathf.Repeat(m_phase, 2f) < 1f) ? (-25f) : 25f);
			return;
		case ModeEnum.Random:
			break;
		}
		while (m_phase >= 1f)
		{
			UnityEngine.Random.InitState(Time.frameCount);
			base.transform.rotation = UnityEngine.Random.rotationUniform;
			m_phase -= 1f;
		}
	}
}
