public class WASD : MonoBehaviour
{
	public float Speed = 1f;

	public float Omega = 1f;

	public UnityEngine.Vector3 m_velocity;

	public UnityEngine.Vector3 Velocity => m_velocity;

	public void Update()
	{
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		if (Input.GetKey(KeyCode.W))
		{
			zero.z += 1f;
		}
		if (Input.GetKey(KeyCode.A))
		{
			zero.x -= 1f;
		}
		if (Input.GetKey(KeyCode.S))
		{
			zero.z -= 1f;
		}
		if (Input.GetKey(KeyCode.D))
		{
			zero.x += 1f;
		}
		UnityEngine.Vector3 vector = ((zero.sqrMagnitude > 0f) ? (zero.normalized * Speed * Time.deltaTime) : UnityEngine.Vector3.zero);
		UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.AngleAxis(0f * Omega * 57.29578f * Time.deltaTime, UnityEngine.Vector3.up);
		m_velocity = vector / Time.deltaTime;
		base.transform.position += vector;
		base.transform.rotation = quaternion2 * base.transform.rotation;
	}
}
public class BootscreenPositioner : MonoBehaviour
{
	[SerializeField]
	private Transform _pov;

	[SerializeField]
	private float _distanceThreshold;

	[SerializeField]
	private float _rotationThreshold;

	private void Awake()
	{
		base.transform.position = _pov.position;
		base.transform.rotation = UnityEngine.Quaternion.Euler(0f, _pov.rotation.eulerAngles.y, 0f);
	}

	private void LateUpdate()
	{
		if (UnityEngine.Vector3.Distance(base.transform.position, _pov.position) > _distanceThreshold)
		{
			base.transform.position = _pov.position;
		}
		if (Mathf.Abs(_pov.rotation.eulerAngles.y - base.transform.rotation.eulerAngles.y) > _rotationThreshold)
		{
			base.transform.rotation = UnityEngine.Quaternion.Euler(0f, _pov.rotation.eulerAngles.y, 0f);
		}
	}
}
