{
	private Renderer _renderer;

	[SerializeField]
	private Texture[] textures;

	[SerializeField]
	private UnityEngine.Vector2 minMaxPause;

	[SerializeField]
	private float prePause = 1f;

	private void Awake()
	{
		_renderer = GetComponent<Renderer>();
		_renderer.material.mainTexture = textures[0];
	}

