public class CameraShaker : MonoBehaviour
{
	private bool rumbling;

	private float stopTime;

	private bool rollOff;

	private float magnitude;

	private float duration;

	private UnityEngine.Vector2 freqRange;

	private static event Action<float, float, UnityEngine.Vector2, bool, Transform, float> ShakeRequested;

	private static event Action HaltRequested;

	public static void Shake(float duration, float magnitude)
	{
		if (CameraShaker.ShakeRequested != null)
		{
			CameraShaker.ShakeRequested(duration, magnitude, new UnityEngine.Vector2(0.02f, 0.1f), arg4: true, null, 0f);
		}
	}

	public static void Shake(float duration, float magnitude, UnityEngine.Vector2 freqRange)
	{
		if (CameraShaker.ShakeRequested != null)
		{
			CameraShaker.ShakeRequested(duration, magnitude, freqRange, arg4: true, null, 0f);
		}
	}

	public static void Shake(float duration, float magnitude, UnityEngine.Vector2 freqRange, bool rollOffOverDuration)
	{
		if (CameraShaker.ShakeRequested != null)
		{
			CameraShaker.ShakeRequested(duration, magnitude, freqRange, rollOffOverDuration, null, 0f);
		}
	}

	public static void ShakeInProximity(float duration, float magnitude, UnityEngine.Vector2 freqRange, bool rollOffOverDuration, Transform source, float distance)
	{
		if (CameraShaker.ShakeRequested != null)
		{
			CameraShaker.ShakeRequested(duration, magnitude, freqRange, rollOffOverDuration, source, distance);
		}
	}

	public static void Halt()
	{
		if (CameraShaker.HaltRequested != null)
		{
			CameraShaker.HaltRequested();
		}
	}

	private void OnEnable()
	{
		ShakeRequested += _ShakeRequested;
		HaltRequested += _HaltRequested;
	}

	private void _ShakeRequested(float _duration, float _magnitude, UnityEngine.Vector2 _freqRange, bool _rollOff, Transform source, float distance)
	{
		stopTime = Time.time + _duration;
		duration = _duration;
		magnitude = _magnitude;
		freqRange = _freqRange;
		rollOff = _rollOff;
		if (!rumbling && (source == null || (base.transform.position - source.transform.position).sqrMagnitude < distance * distance))
		{
			StartCoroutine(crRumble());
		}
	}

	private void _HaltRequested()
	{
		stopTime = Time.time;
	}

	private void OnDisable()
	{
		ShakeRequested -= _ShakeRequested;
		HaltRequested -= _HaltRequested;
	}

	private void OnDestroy()
	{
		ShakeRequested -= _ShakeRequested;
		HaltRequested -= _HaltRequested;
	}

	private IEnumerator crRumble()
	{
		rumbling = true;
		while (stopTime > Time.time)
		{
			UnityEngine.Vector3 vector = UnityEngine.Random.insideUnitSphere * magnitude;
			if (rollOff)
			{
				vector *= (stopTime - Time.time) / duration;
			}
			base.transform.localPosition += vector;
			yield return new WaitForSeconds(UnityEngine.Random.Range(freqRange.x, freqRange.y));
		}
		rumbling = false;
	}
}
public class Clock3x3 : ObservableBehavior
{
	[SerializeField]
	private string titleDataKey;

	[SerializeField]
	private TMP_Text display;

	[SerializeField]
	private Gradient color;

	private string formatString;

	private bool initialized;

	[SerializeField]
	private string[] headings;

	protected override void ObservableSliceUpdate()
	{
		DateTime serverTime = GorillaComputer.instance.GetServerTime();
		DateTime now = DateTime.Now;
		if (serverTime.Year >= 2000)
		{
			display.text = string.Format(formatString, headings[0], headings[1], serverTime.ToString("hh:mm:sstt"), DateTime.Now.ToString("hh:mm:sstt"), HexColor(color.Evaluate(((float)serverTime.Hour + (float)serverTime.Minute / 60f) / 24f)), HexColor(color.Evaluate(((float)now.Hour + (float)now.Minute / 60f) / 24f)));
		}
	}

	public string HexColor(Color color)
	{
		return "#" + Mathf.FloorToInt(Mathf.Clamp01(color.r) * 255f).ToString("X2") + Mathf.FloorToInt(Mathf.Clamp01(color.g) * 255f).ToString("X2") + Mathf.FloorToInt(Mathf.Clamp01(color.b) * 255f).ToString("X2");
	}

	protected override void OnBecameObservable()
	{
		display.gameObject.SetActive(value: true);
		Initialize();
	}

	private async void Initialize()
	{
		if (initialized)
		{
			return;
		}
		initialized = true;
		formatString = display.text;
		display.text = string.Empty;
		if (!titleDataKey.IsNullOrEmpty())
		{
			while (PlayFabTitleDataCache.Instance == null)
			{
				await Task.Yield();
			}
			PlayFabTitleDataCache.Instance.GetTitleData(titleDataKey, onTD, onTDError);
		}
	}

	private void onTD(string s)
	{
		headings = s.Split(";");
	}

	private void onTDError(PlayFabError error)
	{
		UnityEngine.Debug.LogError($"Clock3x3 :: onTDError :: {titleDataKey} :: {error}");
	}

	protected override void OnLostObservable()
	{
		display.gameObject.SetActive(value: false);
	}
}
public class ColliderEnabledManager : MonoBehaviour
{
	public static ColliderEnabledManager instance;

	public Collider[] floorCollider;

	public bool floorEnabled;

	public bool wasFloorEnabled;

	public bool floorCollidersEnabled;

	[GorillaSoundLookup]
	public int wallsBeforeMaterial;

	[GorillaSoundLookup]
	public int wallsAfterMaterial;

	public GorillaSurfaceOverride[] walls;

	public float timeDisabled;

	public float disableLength;

	private void Start()
	{
		floorEnabled = true;
		floorCollidersEnabled = true;
		instance = this;
	}

	private void OnDestroy()
	{
		instance = null;
	}

	public void DisableFloorForFrame()
	{
		floorEnabled = false;
	}

	private void LateUpdate()
	{
		if (!floorEnabled && floorCollidersEnabled)
		{
			DisableFloor();
		}
		if (!floorCollidersEnabled && Time.time > timeDisabled + disableLength)
		{
			floorCollidersEnabled = true;
		}
		Collider[] array = floorCollider;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = floorCollidersEnabled;
		}
		if (floorCollidersEnabled)
		{
			GorillaSurfaceOverride[] array2 = walls;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].overrideIndex = wallsBeforeMaterial;
			}
		}
		else
		{
			GorillaSurfaceOverride[] array2 = walls;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].overrideIndex = wallsAfterMaterial;
			}
		}
		floorEnabled = true;
	}

	private void DisableFloor()
	{
		floorCollidersEnabled = false;
		timeDisabled = Time.time;
	}
}
public class ColliderOffsetOverride : MonoBehaviour
{
	public List<Collider> colliders;

	[HideInInspector]
	public bool autoSearch;

	public float targetScale = 1f;

	private void Awake()
	{
		if (autoSearch)
		{
			FindColliders();
		}
		foreach (Collider collider in colliders)
		{
			if (collider != null)
			{
				collider.contactOffset = 0.01f * targetScale;
			}
		}
	}

	public void FindColliders()
	{
		foreach (Collider item in base.gameObject.GetComponents<Collider>().ToList())
		{
			if (!colliders.Contains(item))
			{
				colliders.Add(item);
			}
		}
	}

	public void FindCollidersRecursively()
	{
		foreach (Collider item in base.gameObject.GetComponentsInChildren<Collider>().ToList())
		{
			if (!colliders.Contains(item))
			{
				colliders.Add(item);
			}
		}
	}

	private void AutoDisabled()
	{
		autoSearch = true;
	}

	private void AutoEnabled()
	{
		autoSearch = false;
	}
}
