[Serializable]
public class CritterConfiguration
{
	public enum AnimalType
	{
		Raccoon = 0,
		Cat = 1,
		Bird = 2,
		Goblin = 3,
		Egg = 4,
		UNKNOWN = -1
	}

	[Tooltip("Basic internal description of critter.  Could be role, purpose, player experience, etc.")]
	public string internalDescription;

	public string critterName = "UNNAMED CRITTER";

	public AnimalType animalType;

	public CritterTemplate behaviour;

	public CritterSpawnCriteria spawnCriteria;

	public RealWorldDateTimeWindow dateLimit;

	public CrittersBiome biome = CrittersBiome.Any;

	public float spawnWeight = 1f;

	public Material critterMat;

	public CritterConfiguration()
	{
		animalType = AnimalType.UNKNOWN;
	}

	public int GetIndex()
	{
		return CrittersManager.instance.creatureIndex.critterTypes.IndexOf(this);
	}

	private bool RegionMatches(CrittersRegion region)
	{
		if ((bool)region)
		{
			return (region.Biome & biome) != 0;
		}
		return true;
	}

	private bool SpawnCriteriaMatches()
	{
		if ((bool)spawnCriteria)
		{
			return spawnCriteria.CanSpawn();
		}
		return true;
	}

	public bool CanSpawn()
	{
		return SpawnCriteriaMatches();
	}

	public bool CanSpawn(CrittersRegion region)
	{
		if (RegionMatches(region))
		{
			return SpawnCriteriaMatches();
		}
		return false;
	}

	public bool DateConditionsMet(DateTime utcDate)
	{
		if ((bool)dateLimit)
		{
			return dateLimit.MatchesDate(utcDate);
		}
		return true;
	}

	public bool ShouldDespawn()
	{
		return !SpawnCriteriaMatches();
	}

	public void ApplyToCreature(CrittersPawn crittersPawn)
	{
		behaviour.ApplyToCritter(crittersPawn);
		if (CrittersManager.instance.LocalAuthority())
		{
			ApplyVisualsTo(crittersPawn);
		}
		else
		{
			ApplyVisualsTo(crittersPawn, generateAppearance: false);
		}
	}

	private void ApplyVisualsTo(CrittersPawn critter, bool generateAppearance = true)
	{
		ApplyVisualsTo(critter.visuals, generateAppearance);
	}

	public void ApplyVisualsTo(CritterVisuals visuals, bool generateAppearance = true)
	{
		visuals.critterType = GetIndex();
		visuals.ApplyMesh(CritterIndex.GetMesh(animalType));
		visuals.ApplyMaterial(critterMat);
		if (generateAppearance)
		{
			visuals.SetAppearance(GenerateAppearance());
		}
	}

	public CritterAppearance GenerateAppearance()
	{
		string hatName = "";
		if (UnityEngine.Random.value <= behaviour.GetTemplateValue<float>("hatChance"))
		{
			GameObject[] templateValue = behaviour.GetTemplateValue<GameObject[]>("hats");
			if (!templateValue.IsNullOrEmpty())
			{
				hatName = templateValue[UnityEngine.Random.Range(0, templateValue.Length)].name;
			}
		}
		float templateValue2 = behaviour.GetTemplateValue<float>("minSize");
		float templateValue3 = behaviour.GetTemplateValue<float>("maxSize");
		float size = UnityEngine.Random.Range(templateValue2, templateValue3);
		return new CritterAppearance(hatName, size);
	}

	public override string ToString()
	{
		return $"{critterName} B:{behaviour} C:{spawnCriteria}";
	}
}
public class CritterIndex : ScriptableObject
{
	[Serializable]
	public class AnimalTypeMeshEntry
	{
		public CritterConfiguration.AnimalType animalType;

		public Mesh mesh;
	}

	public List<AnimalTypeMeshEntry> animalMeshes = new List<AnimalTypeMeshEntry>();

	public List<CritterConfiguration> critterTypes;

	private WeightedList<CritterConfiguration> _currentConfigs = new WeightedList<CritterConfiguration>();

	private static CritterIndex _instance;

	public CritterConfiguration this[int index]
	{
		get
		{
			if (index < 0 || index >= critterTypes.Count)
			{
				return null;
			}
			return critterTypes[index];
		}
	}

	private void OnEnable()
	{
		_instance = this;
	}

	public static Mesh GetMesh(CritterConfiguration.AnimalType animalType)
	{
		if (animalType < CritterConfiguration.AnimalType.Raccoon || (int)animalType >= _instance.animalMeshes.Count)
		{
			return null;
		}
		return _instance.animalMeshes[(int)animalType].mesh;
	}

	public int GetRandomCritterType(CrittersRegion region = null)
	{
		return critterTypes.IndexOf(GetRandomConfiguration(region));
	}

	public CritterConfiguration GetRandomConfiguration(CrittersRegion region = null)
	{
		WeightedList<CritterConfiguration> validCritterTypes = GetValidCritterTypes(region);
		if (validCritterTypes.Count == 0)
		{
			return null;
		}
		return validCritterTypes.GetRandomItem();
	}

	public static DateTime GetCritterDateTime()
	{
		if (!GorillaComputer.instance)
		{
			return DateTime.UtcNow;
		}
		return GorillaComputer.instance.GetServerTime();
	}

	private WeightedList<CritterConfiguration> GetValidCritterTypes(CrittersRegion region = null)
	{
		_currentConfigs.Clear();
		DateTime critterDateTime = GetCritterDateTime();
		foreach (CritterConfiguration critterType in critterTypes)
		{
			if (critterType.DateConditionsMet(critterDateTime) && critterType.CanSpawn(region))
			{
				_currentConfigs.Add(critterType, critterType.spawnWeight);
			}
		}
		return _currentConfigs;
	}
}
public class CrittersActor : MonoBehaviour
{
	public enum CrittersActorType
	{
		Creature,
		Food,
		LoudNoise,
		BrightLight,
		Darkness,
		HidingArea,
		Disappear,
		Spawn,
		Player,
		Grabber,
		Cage,
		FoodSpawner,
		AttachPoint,
		StunBomb,
		Bag,
		BodyAttachPoint,
		NoiseMaker,
		StickyTrap,
		StickyGoo
	}

	public CrittersActorType crittersActorType;

	public bool isSceneActor;

	public bool isOnPlayer;

	[NonSerialized]
	protected bool _isOnPlayerDefault;

	public int rigPlayerId;

	public int rigIndex;

	public bool grabbable;

	protected bool isGrabDisabled;

	public int lastGrabbedPlayer;

	public UnityEvent<CrittersActor> ReleasedEvent;

	public Rigidbody rb;

	[NonSerialized]
	public int actorId;

	[NonSerialized]
	protected Transform defaultParentTransform;

	[NonSerialized]
	public int parentActorId = -1;

	[NonSerialized]
	protected int lastParentActorId;

	[NonSerialized]
	public UnityEngine.Vector3 lastImpulsePosition;

	[NonSerialized]
	public UnityEngine.Vector3 lastImpulseVelocity;

	[NonSerialized]
	public UnityEngine.Vector3 lastImpulseAngularVelocity;

	[NonSerialized]
	public UnityEngine.Quaternion lastImpulseQuaternion;

	[NonSerialized]
	public double lastImpulseTime;

	[NonSerialized]
	public bool updatedSinceLastFrame;

	public bool isEnabled = true;

	public bool wasEnabled = true;

	[NonSerialized]
	protected double localLastImpulse;

	[NonSerialized]
	protected Transform parentActor;

	public GameObject[] subObjects;

	public int subObjectIndex = -1;

	public bool usesRB;

	public bool resetPhysicsOnSpawn;

	public bool despawnWhenIdle;

	public bool preventDespawnUntilGrabbed;

	public int despawnDelay;

	public double despawnTime;

	public bool isDespawnBlocked;

	public bool equipmentStorable;

	public bool localCanStore;

	public CrittersActor lastStoredObject;

	public CapsuleCollider storeCollider;

	[NonSerialized]
	public Collider[] colliders;

	[NonSerialized]
	public ConfigurableJoint joint;

	[NonSerialized]
	public float timeLastTouched;

	private JointDrive drive;

	private JointDrive angularDrive;

	private SoftJointLimit linearLimitDrive;

	private SoftJointLimitSpring linearLimitSpringDrive;

	public CapsuleCollider equipmentStoreTriggerCollider;

	public bool disconnectJointFlag;

	public bool forceUpdate;

	public float FearAmount = 1f;

	public AnimationCurve FearCurve = AnimationCurve.Linear(0f, 1f, 1f, 1f);

	public float AttractionAmount = 1f;

	public AnimationCurve AttractionCurve = AnimationCurve.Linear(0f, 1f, 1f, 1f);

	[FormerlySerializedAs("maxDetectionDistance")]
	public float maxRangeOfFearAttraction = 3f;

	protected float[] averageSpeed = new float[6];

	protected int averageSpeedIndex;

	private UnityEngine.Vector3 lastPosition = UnityEngine.Vector3.zero;

	public float GetAverageSpeed => (averageSpeed[0] + averageSpeed[1] + averageSpeed[2] + averageSpeed[3] + averageSpeed[4] + averageSpeed[5]) / 6f;

	public event Action<CrittersActor> OnGrabbedChild;

	public virtual void UpdateAverageSpeed()
	{
		averageSpeed[averageSpeedIndex] = (base.transform.position - lastPosition).magnitude;
		averageSpeedIndex++;
		averageSpeedIndex %= 6;
		lastPosition = base.transform.position;
	}

	protected virtual void Awake()
	{
		_isOnPlayerDefault = isOnPlayer;
	}

	public virtual void Initialize()
	{
		if (defaultParentTransform == null)
		{
			SetDefaultParent(base.transform.parent);
		}
		if (rb == null)
		{
			rb = GetComponent<Rigidbody>();
		}
		if (rb == null)
		{
			UnityEngine.Debug.LogError("I should have a rigidbody, but I don't!", base.gameObject);
		}
		wasEnabled = false;
		isEnabled = true;
		TogglePhysics(usesRB);
		if (!rb.isKinematic)
		{
			rb.linearVelocity = UnityEngine.Vector3.zero;
			rb.angularVelocity = UnityEngine.Vector3.zero;
		}
		if (resetPhysicsOnSpawn)
		{
			rb.linearVelocity = UnityEngine.Vector3.zero;
			rb.angularVelocity = UnityEngine.Vector3.zero;
			lastImpulseVelocity = UnityEngine.Vector3.zero;
		}
		if (subObjectIndex >= 0 && subObjectIndex < subObjects.Length)
		{
			for (int i = 0; i < subObjects.Length; i++)
			{
				subObjects[i].SetActive(i == subObjectIndex);
			}
		}
		colliders = new Collider[50];
		if (preventDespawnUntilGrabbed)
		{
			isDespawnBlocked = true;
			despawnTime = 0.0;
		}
		else
		{
			isDespawnBlocked = false;
			despawnTime = (double)despawnDelay + (PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time));
		}
		rb.includeLayers = 0;
		rb.excludeLayers = CrittersManager.instance.containerLayer;
	}

	public virtual void OnEnable()
	{
		CrittersManager.RegisterActor(this);
		Initialize();
	}

	public virtual void OnDisable()
	{
		CleanupActor();
	}

	public virtual string GetActorSubtype()
	{
		if (subObjectIndex >= 0 && subObjectIndex < subObjects.Length)
		{
			return subObjects[subObjectIndex].name;
		}
		return base.name;
	}

	protected virtual void CleanupActor()
	{
		CrittersManager.DeregisterActor(this);
		if (base.gameObject.activeSelf)
		{
			base.gameObject.SetActive(value: false);
		}
		for (int i = 0; i < subObjects.Length; i++)
		{
			if (subObjects[i].activeSelf)
			{
				subObjects[i].transform.localRotation = UnityEngine.Quaternion.identity;
				subObjects[i].transform.localPosition = UnityEngine.Vector3.zero;
				subObjects[i].SetActive(value: false);
			}
		}
		ReleasedEvent.Invoke(this);
		ReleasedEvent.RemoveAllListeners();
		isEnabled = false;
		wasEnabled = true;
		isOnPlayer = _isOnPlayerDefault;
		rigPlayerId = -1;
		rigIndex = -1;
		despawnTime = 0.0;
		isDespawnBlocked = false;
		rb.isKinematic = false;
		if (parentActorId >= 0)
		{
			AttemptRemoveStoredObjectCollider(parentActorId, playSound: false);
		}
		parentActorId = -1;
		parentActor = null;
		lastParentActorId = -1;
		isGrabDisabled = false;
		lastGrabbedPlayer = -1;
		lastImpulsePosition = UnityEngine.Vector3.zero;
		lastImpulseVelocity = UnityEngine.Vector3.zero;
		lastImpulseQuaternion = UnityEngine.Quaternion.identity;
		lastImpulseTime = -1.0;
		localLastImpulse = -1.0;
		updatedSinceLastFrame = false;
		localCanStore = false;
	}

	public virtual bool ProcessLocal()
	{
		updatedSinceLastFrame |= isEnabled != wasEnabled || parentActorId != lastParentActorId;
		lastParentActorId = parentActorId;
		wasEnabled = isEnabled;
		return updatedSinceLastFrame;
	}

	public virtual void ProcessRemote()
	{
		bool flag = forceUpdate;
		forceUpdate = false;
		if (base.gameObject.activeSelf != isEnabled)
		{
			base.gameObject.SetActive(isEnabled);
		}
		if (!isEnabled)
		{
			return;
		}
		bool flag2 = lastParentActorId == parentActorId || isOnPlayer || isSceneActor;
		bool flag3 = lastImpulseTime == localLastImpulse;
		if (flag2 && flag3 && !flag)
		{
			return;
		}
		if (!flag2)
		{
			if (lastParentActorId >= 0)
			{
				AttemptRemoveStoredObjectCollider(lastParentActorId);
			}
			lastParentActorId = parentActorId;
			if (parentActorId >= 0)
			{
				if (CrittersManager.instance.actorById.TryGetValue(parentActorId, out var value))
				{
					parentActor = value.transform;
					base.transform.SetParent(parentActor, worldPositionStays: true);
					SetImpulse();
					if (value is CrittersBag)
					{
						((CrittersBag)value).AddStoredObjectCollider(this);
					}
					if (value.isOnPlayer)
					{
						lastGrabbedPlayer = value.rigPlayerId;
					}
					value.RemoteGrabbed(this);
				}
			}
			else if (parentActorId == -1)
			{
				parentActor = null;
				SetTransformToDefaultParent();
				HandleRemoteReleased();
				SetImpulse();
			}
		}
		else
		{
			SetImpulse();
		}
	}

	public virtual void SetImpulse()
	{
		if (!isOnPlayer && !isSceneActor)
		{
			localLastImpulse = lastImpulseTime;
			MoveActor(lastImpulsePosition, lastImpulseQuaternion, parentActorId >= 0, updateImpulses: false);
			TogglePhysics(usesRB && parentActorId == -1);
			if (!rb.isKinematic)
			{
				rb.linearVelocity = lastImpulseVelocity;
				rb.angularVelocity = lastImpulseAngularVelocity;
			}
		}
	}

	public virtual void TogglePhysics(bool enable)
	{
		if (enable)
		{
			rb.isKinematic = false;
			rb.interpolation = RigidbodyInterpolation.Interpolate;
			rb.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
		}
		else
		{
			rb.isKinematic = true;
			rb.interpolation = RigidbodyInterpolation.None;
			rb.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
		}
	}

