	public virtual bool CheckStorable()
	{
		if (!localCanStore)
		{
			return false;
		}
		UnityEngine.Vector3 vector = storeCollider.transform.up * MathF.Max(0f, storeCollider.height / 2f - storeCollider.radius);
		int num = Physics.OverlapCapsuleNonAlloc(storeCollider.transform.position + vector, storeCollider.transform.position - vector, storeCollider.radius, colliders, CrittersManager.instance.containerLayer, QueryTriggerInteraction.Collide);
		bool flag = false;
		CrittersBag crittersBag = null;
		bool flag2 = true;
		CrittersActor value = null;
		if (lastGrabbedPlayer == PhotonNetwork.LocalPlayer.ActorNumber && CrittersManager.instance.actorById.TryGetValue(parentActorId, out value) && value.GetAverageSpeed > CrittersManager.instance.MaxAttachSpeed)
		{
			return false;
		}
		if (num > 0)
		{
			for (int i = 0; i < num; i++)
			{
				CrittersActor component = colliders[i].attachedRigidbody.GetComponent<CrittersActor>();
				if (component == null || component == this)
				{
					continue;
				}
				CrittersBag crittersBag2 = component as CrittersBag;
				if (crittersBag2 == null)
				{
					continue;
				}
				if (crittersBag2 == lastStoredObject)
				{
					flag = true;
					flag2 = false;
					break;
				}
				if (!crittersBag2.IsActorValidStore(this))
				{
					continue;
				}
				if (crittersBag2.attachableCollider != colliders[i] && !colliders[i].isTrigger)
				{
					Physics.ComputePenetration(colliders[i], colliders[i].transform.position, colliders[i].transform.rotation, storeCollider, storeCollider.transform.position, storeCollider.transform.rotation, out var _, out var distance);
					if (distance >= CrittersManager.instance.overlapDistanceMax)
					{
						flag2 = false;
						break;
					}
				}
				else
				{
					crittersBag = crittersBag2;
				}
			}
		}
		if (crittersBag.IsNotNull() && flag2)
		{
			if (value.IsNotNull())
			{
				CrittersGrabber crittersGrabber = value as CrittersGrabber;
				if (crittersGrabber.IsNotNull())
				{
					GorillaTagger.Instance.StartVibration(crittersGrabber.isLeft, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration * 0.5f);
				}
			}
			GrabbedBy(crittersBag);
			localCanStore = false;
			lastStoredObject = crittersBag;
			DisconnectJoint();
			return true;
		}
		if (!flag)
		{
			lastStoredObject = null;
		}
		return false;
	}

	public void SetJointRigid(Rigidbody rbToConnect)
	{
		if (!(joint != null))
		{
			UnityEngine.Debug.Log("Critters SetJointRigid " + base.gameObject);
			CreateJoint(rbToConnect, setParentNull: false);
			joint.xMotion = ConfigurableJointMotion.Locked;
			joint.yMotion = ConfigurableJointMotion.Locked;
			joint.zMotion = ConfigurableJointMotion.Locked;
			joint.angularXMotion = ConfigurableJointMotion.Locked;
			joint.angularYMotion = ConfigurableJointMotion.Locked;
			joint.angularZMotion = ConfigurableJointMotion.Locked;
			rb.mass = CrittersManager.instance.heavyMass;
			TogglePhysics(enable: true);
		}
	}

	public void SetJointSoft(Rigidbody rbToConnect)
	{
		if (!(joint != null))
		{
			UnityEngine.Debug.Log("Critters SetJointSoft " + base.gameObject);
			CreateJoint(rbToConnect);
			joint.xMotion = ConfigurableJointMotion.Limited;
			joint.yMotion = ConfigurableJointMotion.Limited;
			joint.zMotion = ConfigurableJointMotion.Limited;
			joint.angularXMotion = ConfigurableJointMotion.Limited;
			joint.angularYMotion = ConfigurableJointMotion.Limited;
			joint.angularZMotion = ConfigurableJointMotion.Limited;
			rb.mass = CrittersManager.instance.lightMass;
			TogglePhysics(enable: true);
		}
	}

	private void CreateJoint(Rigidbody rbToConnect, bool setParentNull = true)
	{
		if (!(joint != null))
		{
			joint = base.gameObject.AddComponent<ConfigurableJoint>();
			drive = new JointDrive
			{
				positionSpring = CrittersManager.instance.springForce,
				positionDamper = CrittersManager.instance.damperForce,
				maximumForce = 10000f
			};
			angularDrive = new JointDrive
			{
				positionSpring = CrittersManager.instance.springAngularForce,
				positionDamper = CrittersManager.instance.damperAngularForce,
				maximumForce = 10000f
			};
			linearLimitDrive = new SoftJointLimit
			{
				limit = CrittersManager.instance.springForce
			};
			linearLimitSpringDrive = new SoftJointLimitSpring
			{
				spring = CrittersManager.instance.springForce
			};
			joint.linearLimit = linearLimitDrive;
			joint.linearLimitSpring = linearLimitSpringDrive;
			joint.angularYLimit = joint.linearLimit;
			joint.angularZLimit = joint.linearLimit;
			joint.angularXDrive = angularDrive;
			joint.angularYZDrive = angularDrive;
			joint.xDrive = drive;
			joint.yDrive = drive;
			joint.zDrive = drive;
			joint.autoConfigureConnectedAnchor = true;
			joint.enableCollision = false;
			joint.connectedBody = rbToConnect;
			rb.excludeLayers = CrittersManager.instance.movementLayers;
			rb.useGravity = false;
			if (setParentNull)
			{
				base.transform.SetParent(null, worldPositionStays: true);
			}
		}
	}

	public void DisconnectJoint()
	{
		rb.excludeLayers = CrittersManager.instance.containerLayer;
		rb.useGravity = true;
		if (joint != null)
		{
			UnityEngine.Object.Destroy(joint);
		}
		joint = null;
		if (parentActorId != -1)
		{
			CrittersManager.instance.actorById.TryGetValue(parentActorId, out var value);
			base.transform.SetParent(value.transform, worldPositionStays: true);
			MoveActor(lastImpulsePosition, lastImpulseQuaternion, local: true, updateImpulses: false);
			TogglePhysics(enable: false);
		}
	}

	public void AttemptRemoveStoredObjectCollider(int oldParentId, bool playSound = true)
	{
		if (CrittersManager.instance.actorById.TryGetValue(oldParentId, out var value) && value is CrittersBag)
		{
			((CrittersBag)value).RemoveStoredObjectCollider(this, playSound);
		}
	}

	public void AttemptAddStoredObjectCollider(CrittersActor actor)
	{
		if (actor is CrittersBag)
		{
			((CrittersBag)actor).AddStoredObjectCollider(this);
		}
	}

	public bool AttemptSetEquipmentStorable()
	{
		if (!equipmentStorable)
		{
			return false;
		}
		localCanStore = true;
		return true;
	}
}
public class CrittersActorDeposit : MonoBehaviour
{
	public CrittersActor attachPoint;

	public CrittersActor.CrittersActorType actorType;

	public bool disableGrabOnAttach;

	public bool allowMultiAttach;

	public bool snapOnAttach;

	private CrittersActor currentAttach;

	public void OnTriggerEnter(Collider other)
	{
		if (other.attachedRigidbody.IsNotNull())
		{
			CrittersActor component = other.attachedRigidbody.GetComponent<CrittersActor>();
			if (CrittersManager.instance.LocalAuthority() && component.IsNotNull() && CanDeposit(component) && IsAttachAvailable())
			{
				HandleDeposit(component);
			}
		}
	}

	protected virtual bool CanDeposit(CrittersActor depositActor)
	{
		if (depositActor.crittersActorType == actorType)
		{
			if (CrittersManager.instance.actorById.TryGetValue(depositActor.parentActorId, out var value))
			{
				return value.crittersActorType == CrittersActor.CrittersActorType.Grabber;
			}
			return depositActor.parentActorId == -1;
		}
		return false;
	}

	private bool IsAttachAvailable()
	{
		if (allowMultiAttach)
		{
			return true;
		}
		return currentAttach == null;
	}

	protected virtual void HandleDeposit(CrittersActor depositedActor)
	{
		currentAttach = depositedActor;
		depositedActor.ReleasedEvent.AddListener(HandleDetach);
		CrittersActor grabbingActor = attachPoint;
		bool positionOverride = snapOnAttach;
		bool disableGrabbing = disableGrabOnAttach;
		depositedActor.GrabbedBy(grabbingActor, positionOverride, default(UnityEngine.Quaternion), default(UnityEngine.Vector3), disableGrabbing);
	}

	protected virtual void HandleDetach(CrittersActor detachingActor)
	{
		currentAttach = null;
	}
}
[DefaultExecutionOrder(9999)]
public class CrittersActorGrabber : MonoBehaviour
{
	public bool isGrabbing;

	public Collider[] colliders = new Collider[50];

	public bool isLeft;

	public float grabRadius = 0.05f;

	public float grabBreakRadius = 0.15f;

	private float grabDetachFromBagDist = 0.05f;

	public Transform transformToFollow;

	public GorillaVelocityEstimator estimator;

	public CrittersGrabber grabber;

	public float vibrationStartDistance;

	public float vibrationEndDistance;

	public CrittersActorGrabber otherHand;

	private bool isHandGrabbingDisabled;

	private float grabDuration = 0.3f;

	private float remainingGrabDuration;

	private bool playingHaptics;

	private AudioClip hapticsClip;

	private float hapticsStrength;

	private float hapticsLength;

	private Coroutine haptics;

	public CapsuleCollider triggerCollider;

	private Rigidbody rb;

	private CrittersActor validGrabTarget;

	private CrittersActor lastHover;

	private UnityEngine.Vector3 localGrabOffset;

	private CrittersActor queuedGrab;

	private UnityEngine.Vector3 queuedRelativeGrabOffset;

	private UnityEngine.Quaternion queuedRelativeGrabRotation;

	public List<CrittersActor> actorsStillPresent;

	private void Awake()
	{
		if (grabber == null)
		{
			grabber = GetComponent<CrittersGrabber>();
		}
		vibrationStartDistance *= vibrationStartDistance;
		vibrationEndDistance *= vibrationEndDistance;
		rb = GetComponent<Rigidbody>();
		CrittersGrabberSharedData.AddActorGrabber(this);
		actorsStillPresent = new List<CrittersActor>();
	}

	private void LateUpdate()
	{
		if (CrittersManager.instance == null || !CrittersManager.instance.LocalInZone)
		{
			return;
		}
		if (isLeft)
		{
			NewJointMethod();
		}
		if ((grabber == null || !grabber.gameObject.activeSelf || grabber.rigPlayerId != PhotonNetwork.LocalPlayer.ActorNumber) && CrittersManager.instance.rigSetupByRig.TryGetValue(GorillaTagger.Instance.offlineVRRig, out var value))
		{
			int num = -1;
			num = (isLeft ? 1 : 3);
			grabber = value.rigActors[num].location.GetComponentInChildren<CrittersGrabber>();
			if (grabber != null)
			{
				grabber.isLeft = isLeft;
			}
		}
		if (grabber != null)
		{
			for (int i = 0; i < grabber.grabbedActors.Count; i++)
			{
				if (grabber.grabbedActors[i].localCanStore)
				{
					grabber.grabbedActors[i].CheckStorable();
				}
			}
		}
		if (transformToFollow != null)
		{
			base.transform.position = transformToFollow.position;
			base.transform.rotation = transformToFollow.rotation;
		}
		if (grabber == null)
		{
			return;
		}
		VerifyExistingGrab();
		validGrabTarget = FindGrabTargets();
		bool flag = ((!isLeft) ? ControllerInputPoller.instance.rightGrab : ControllerInputPoller.instance.leftGrab);
		bool num2 = (isLeft ? (EquipmentInteractor.instance.leftHandHeldEquipment != null) : (EquipmentInteractor.instance.rightHandHeldEquipment != null));
		if (num2)
		{
			flag = false;
		}
		if (!num2)
		{
			if (validGrabTarget.IsNotNull())
			{
				if (validGrabTarget != lastHover)
				{
					lastHover = validGrabTarget;
					DoHover();
				}
			}
			else
			{
				lastHover = null;
			}
		}
		if (!isGrabbing && flag)
		{
			isGrabbing = true;
			remainingGrabDuration = grabDuration;
		}
		else if (isGrabbing)
		{
			if (!flag)
			{
				isGrabbing = false;
				DoRelease();
			}
			else if (queuedGrab != null)
			{
				CheckApplyQueuedGrab();
			}
		}
		if (isGrabbing && remainingGrabDuration > 0f)
		{
			remainingGrabDuration -= Time.deltaTime;
			DoGrab();
		}
	}

	private CrittersActor FindGrabTargets()
	{
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, grabRadius, colliders, (int)CrittersManager.instance.objectLayers | (int)CrittersManager.instance.containerLayer);
		float num2 = 10000f;
		Collider collider = null;
		if (num > 0)
		{
			for (int i = 0; i < num; i++)
			{
				Rigidbody attachedRigidbody = colliders[i].attachedRigidbody;
				if (attachedRigidbody == null)
				{
					continue;
				}
				CrittersActor component = attachedRigidbody.GetComponent<CrittersActor>();
				if (!(component == null) && (!(component is CrittersBag) || !CrittersManager.instance.actorById.TryGetValue(component.parentActorId, out var value) || !(value is CrittersAttachPoint) || (value as CrittersAttachPoint).rigPlayerId != PhotonNetwork.LocalPlayer.ActorNumber || (value as CrittersAttachPoint).anchorLocation != CrittersAttachPoint.AnchoredLocationTypes.Arm || (value as CrittersAttachPoint).isLeft != isLeft) && component.usesRB && component.CanBeGrabbed(grabber))
				{
					float sqrMagnitude = (colliders[i].attachedRigidbody.position - base.transform.position).sqrMagnitude;
					if (sqrMagnitude < num2)
					{
						num2 = sqrMagnitude;
						collider = colliders[i];
					}
				}
			}
			if (collider == null)
			{
				return null;
			}
			return collider.attachedRigidbody.GetComponent<CrittersActor>();
		}
		return null;
	}

	private void DoHover()
	{
		validGrabTarget.OnHover(isLeft);
	}

	private void DoGrab()
	{
		if (!GTExt.IsNull(validGrabTarget))
		{
			grabber.grabbing = true;
			if (isLeft)
			{
				EquipmentInteractor.instance.disableLeftGrab = true;
			}
			else
			{
				EquipmentInteractor.instance.disableRightGrab = true;
			}
			isHandGrabbingDisabled = true;
			remainingGrabDuration = 0f;
			UnityEngine.Vector3 localOffset = grabber.transform.InverseTransformPoint(validGrabTarget.transform.position);
			UnityEngine.Quaternion localRotation = grabber.transform.InverseTransformRotation(validGrabTarget.transform.rotation);
			if (validGrabTarget.IsCurrentlyAttachedToBag())
			{
				queuedGrab = validGrabTarget;
				queuedRelativeGrabOffset = localOffset;
				queuedRelativeGrabRotation = localRotation;
			}
			else if (validGrabTarget.AllowGrabbingActor(grabber))
			{
				ApplyGrab(validGrabTarget, localRotation, localOffset);
			}
		}
	}

	private void ApplyGrab(CrittersActor grabTarget, UnityEngine.Quaternion localRotation, UnityEngine.Vector3 localOffset)
	{
		if (grabTarget.AttemptSetEquipmentStorable())
		{
			RemoveGrabberPhysicsTrigger();
			AddGrabberPhysicsTrigger(grabTarget);
		}
		grabTarget.GrabbedBy(grabber, positionOverride: true, localRotation, localOffset);
		grabber.grabbedActors.Add(grabTarget);
		localGrabOffset = localOffset;
		CrittersPawn crittersPawn = grabTarget as CrittersPawn;
		if (crittersPawn.IsNotNull())
		{
			PlayHaptics(crittersPawn.grabbedHaptics, crittersPawn.grabbedHapticsStrength);
		}
	}

	private void DoRelease()
	{
		queuedGrab = null;
		grabber.grabbing = false;
		StopHaptics();
		for (int num = grabber.grabbedActors.Count - 1; num >= 0; num--)
		{
			CrittersActor crittersActor = grabber.grabbedActors[num];
			float magnitude = estimator.linearVelocity.magnitude;
			float num2 = magnitude + Mathf.Max(0f, magnitude - CrittersManager.instance.fastThrowThreshold) * CrittersManager.instance.fastThrowMultiplier;
			crittersActor.Released(keepWorldPosition: true, crittersActor.transform.rotation, crittersActor.transform.position, estimator.linearVelocity.normalized * num2, estimator.angularVelocity);
			if (num < grabber.grabbedActors.Count)
			{
				grabber.grabbedActors.RemoveAt(num);
			}
		}
		RemoveGrabberPhysicsTrigger();
		if (isHandGrabbingDisabled)
		{
			isHandGrabbingDisabled = false;
			if (isLeft)
			{
				EquipmentInteractor.instance.disableLeftGrab = false;
			}
			else
			{
				EquipmentInteractor.instance.disableRightGrab = false;
			}
		}
	}

	private void CheckApplyQueuedGrab()
	{
		if (UnityEngine.Vector3.Magnitude(grabber.transform.InverseTransformPoint(queuedGrab.transform.position) - queuedRelativeGrabOffset) > grabDetachFromBagDist)
		{
			GorillaTagger.Instance.StartVibration(isLeft, GorillaTagger.Instance.tapHapticStrength / 4f, GorillaTagger.Instance.tapHapticDuration * 0.5f);
			if (queuedGrab.AllowGrabbingActor(grabber))
			{
				ApplyGrab(queuedGrab, queuedRelativeGrabRotation, queuedRelativeGrabOffset);
			}
			queuedGrab = null;
		}
	}

	private void VerifyExistingGrab()
	{
		for (int num = grabber.grabbedActors.Count - 1; num >= 0; num--)
		{
			CrittersActor crittersActor = grabber.grabbedActors[num];
			if (GTExt.IsNull(crittersActor) || crittersActor.parentActorId != grabber.actorId)
			{
				if (grabber.IsNotNull())
				{
					grabber.grabbedActors.Remove(crittersActor);
				}
				RemoveGrabberPhysicsTrigger();
				StopHaptics();
			}
		}
	}

	public void PlayHaptics(AudioClip clip, float strength)
	{
		if (!(clip == null))
		{
			StopHaptics();
			playingHaptics = true;
			hapticsClip = clip;
			hapticsStrength = strength;
			hapticsLength = clip.length;
			haptics = StartCoroutine(PlayHapticsOnLoop());
		}
	}

	public void StopHaptics()
	{
		if (playingHaptics)
		{
			playingHaptics = false;
			StopCoroutine(haptics);
			haptics = null;
			GorillaTagger.Instance.StopHapticClip(isLeft);
		}
	}

	private IEnumerator PlayHapticsOnLoop()
	{
		while (true)
		{
			GorillaTagger.Instance.PlayHapticClip(isLeft, hapticsClip, hapticsStrength);
			yield return new WaitForSeconds(hapticsLength);
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		if (!(other.attachedRigidbody == null))
		{
			CrittersActor component = other.attachedRigidbody.GetComponent<CrittersActor>();
			if (DoesActorActivateJoint(component, out var heldStorableActor))
			{
				ActivateJoints(component, heldStorableActor);
			}
		}
	}

	private void ActivateJoints(CrittersActor rigidJoint, CrittersActor softJoint)
	{
		softJoint.SetJointSoft(grabber.rb);
		if (rigidJoint.parentActorId != -1)
		{
			rigidJoint.SetJointRigid(CrittersManager.instance.actorById[rigidJoint.parentActorId].rb);
		}
		CrittersGrabberSharedData.AddEnteredActor(rigidJoint);
	}

	private bool DoesActorActivateJoint(CrittersActor potentialBagActor, out CrittersActor heldStorableActor)
	{
		heldStorableActor = null;
		for (int i = 0; i < grabber.grabbedActors.Count; i++)
		{
			if (grabber.grabbedActors[i].localCanStore)
			{
				heldStorableActor = grabber.grabbedActors[i];
			}
		}
		if (heldStorableActor == null)
		{
			return false;
		}
		if (!(potentialBagActor is CrittersBag))
		{
			return false;
		}
		if (CrittersManager.instance.actorById.TryGetValue(potentialBagActor.parentActorId, out var value) && value is CrittersAttachPoint && (value as CrittersAttachPoint).rigPlayerId == PhotonNetwork.LocalPlayer.ActorNumber && (value as CrittersAttachPoint).anchorLocation == CrittersAttachPoint.AnchoredLocationTypes.Arm && (value as CrittersAttachPoint).isLeft == isLeft)
		{
			return false;
		}
		return true;
	}

	private void AddGrabberPhysicsTrigger(CrittersActor actor)
	{
		CapsuleCollider capsuleCollider = CrittersManager.DuplicateCapsuleCollider(base.transform, actor.equipmentStoreTriggerCollider);
		capsuleCollider.isTrigger = true;
		triggerCollider = capsuleCollider;
		CrittersGrabberSharedData.AddTrigger(triggerCollider);
		rb.includeLayers = CrittersManager.instance.containerLayer;
	}

	private void RemoveGrabberPhysicsTrigger()
	{
		if (triggerCollider != null)
		{
			CrittersGrabberSharedData.RemoveTrigger(triggerCollider);
			UnityEngine.Object.Destroy(triggerCollider.gameObject);
		}
		triggerCollider = null;
		rb.includeLayers = 0;
	}

	private void NewJointMethod()
	{
		if (CrittersGrabberSharedData.triggerCollidersToCheck.Count == 0 && CrittersGrabberSharedData.enteredCritterActor.Count == 0)
		{
			return;
		}
		for (int i = 0; i < CrittersGrabberSharedData.actorGrabbers.Count; i++)
		{
			CrittersGrabberSharedData.actorGrabbers[i].actorsStillPresent.Clear();
			CapsuleCollider capsuleCollider = CrittersGrabberSharedData.actorGrabbers[i].triggerCollider;
			if (capsuleCollider == null)
			{
				continue;
			}
			UnityEngine.Vector3 vector = capsuleCollider.transform.up * MathF.Max(0f, capsuleCollider.height / 2f - capsuleCollider.radius);
			int num = Physics.OverlapCapsuleNonAlloc(capsuleCollider.transform.position + vector, capsuleCollider.transform.position - vector, capsuleCollider.radius, colliders, CrittersManager.instance.containerLayer, QueryTriggerInteraction.Collide);
			if (num == 0)
			{
				continue;
			}
			for (int j = 0; j < num; j++)
			{
				Rigidbody attachedRigidbody = colliders[j].attachedRigidbody;
				if (!(attachedRigidbody == null))
				{
					CrittersActor component = attachedRigidbody.GetComponent<CrittersActor>();
					if (!(component == null) && !CrittersGrabberSharedData.actorGrabbers[i].actorsStillPresent.Contains(component))
					{
						CrittersGrabberSharedData.actorGrabbers[i].actorsStillPresent.Add(component);
					}
				}
			}
		}
		for (int k = 0; k < CrittersGrabberSharedData.actorGrabbers.Count; k++)
		{
			CrittersActorGrabber crittersActorGrabber = CrittersGrabberSharedData.actorGrabbers[k];
			for (int l = 0; l < CrittersGrabberSharedData.actorGrabbers[k].actorsStillPresent.Count; l++)
			{
				CrittersActor crittersActor = CrittersGrabberSharedData.actorGrabbers[k].actorsStillPresent[l];
				if (crittersActorGrabber.DoesActorActivateJoint(crittersActor, out var heldStorableActor))
				{
					crittersActorGrabber.ActivateJoints(crittersActor, heldStorableActor);
				}
			}
		}
		for (int num2 = CrittersGrabberSharedData.enteredCritterActor.Count - 1; num2 >= 0; num2--)
		{
			CrittersActor crittersActor2 = CrittersGrabberSharedData.enteredCritterActor[num2];
			bool flag = false;
			for (int m = 0; m < CrittersGrabberSharedData.actorGrabbers.Count; m++)
			{
				flag |= CrittersGrabberSharedData.actorGrabbers[m].actorsStillPresent.Contains(crittersActor2);
			}
			if (!flag)
			{
				CrittersGrabberSharedData.RemoveEnteredActor(crittersActor2);
				crittersActor2.DisconnectJoint();
			}
		}
		CrittersGrabberSharedData.DisableEmptyGrabberJoints();
	}
}
public static class CrittersGrabberSharedData
{
	public static List<CrittersActor> enteredCritterActor;

	public static List<CapsuleCollider> triggerCollidersToCheck;

	public static List<CrittersActor> heldActor;

	public static List<CrittersActorGrabber> actorGrabbers;

	private static bool initialized;

	public static void Initialize()
	{
		if (!initialized)
		{
			initialized = true;
			enteredCritterActor = new List<CrittersActor>();
			triggerCollidersToCheck = new List<CapsuleCollider>();
			heldActor = new List<CrittersActor>();
			actorGrabbers = new List<CrittersActorGrabber>();
		}
	}

	public static void AddEnteredActor(CrittersActor actor)
	{
		Initialize();
		if (!enteredCritterActor.Contains(actor))
		{
			enteredCritterActor.Add(actor);
		}
	}

	public static void RemoveEnteredActor(CrittersActor actor)
	{
		Initialize();
		if (enteredCritterActor.Contains(actor))
		{
			enteredCritterActor.Remove(actor);
		}
	}

	public static void AddTrigger(CapsuleCollider trigger)
	{
		Initialize();
		if (!triggerCollidersToCheck.Contains(trigger))
		{
			triggerCollidersToCheck.Add(trigger);
		}
	}

	public static void RemoveTrigger(CapsuleCollider trigger)
	{
		Initialize();
		if (triggerCollidersToCheck.Contains(trigger))
		{
			triggerCollidersToCheck.Remove(trigger);
		}
	}

	public static void AddActorGrabber(CrittersActorGrabber grabber)
	{
		Initialize();
		if (!actorGrabbers.Contains(grabber))
		{
			actorGrabbers.Add(grabber);
		}
	}

	public static void RemoveActorGrabber(CrittersActorGrabber grabber)
	{
		Initialize();
		if (actorGrabbers.Contains(grabber))
		{
			actorGrabbers.Remove(grabber);
		}
	}

	public static void DisableEmptyGrabberJoints()
	{
		Initialize();
		for (int i = 0; i < actorGrabbers.Count; i++)
		{
			if (actorGrabbers[i].grabber != null && actorGrabbers[i].actorsStillPresent.Count == 0)
			{
				for (int j = 0; j < actorGrabbers[i].grabber.grabbedActors.Count; j++)
				{
					actorGrabbers[i].grabber.grabbedActors[j].DisconnectJoint();
				}
			}
		}
	}
}
public class CrittersActorSettings : MonoBehaviour
{
	public CrittersActor parentActor;

	public bool usesRB;

	public bool canBeStored;

	public CapsuleCollider storeCollider;

	public CapsuleCollider equipmentStoreTriggerCollider;

	public virtual void OnEnable()
	{
		UpdateActorSettings();
	}

	public virtual void UpdateActorSettings()
	{
		parentActor.usesRB = usesRB;
		parentActor.rb.isKinematic = !usesRB;
		parentActor.equipmentStorable = canBeStored;
		parentActor.storeCollider = storeCollider;
		parentActor.equipmentStoreTriggerCollider = equipmentStoreTriggerCollider;
	}
}
public class CrittersActorSpawnerPoint : CrittersActor
{
	private CrittersActor spawnedActor;

	private int spawnedActorID = -1;

	public event Action<CrittersActor> OnSpawnChanged;

	public override void Initialize()
	{
		base.Initialize();
		UpdateImpulses();
	}

	public override void OnDisable()
	{
		base.OnDisable();
		spawnedActorID = -1;
		spawnedActor = null;
	}

	public void SetSpawnedActor(CrittersActor actor)
	{
		if (!(spawnedActor == actor))
		{
			spawnedActor = actor;
			if (spawnedActor != null)
			{
				spawnedActorID = spawnedActor.actorId;
			}
			else
			{
				spawnedActorID = -1;
			}
			this.OnSpawnChanged?.Invoke(spawnedActor);
			updatedSinceLastFrame = true;
		}
	}

	private void UpdateSpawnedActor(int newSpawnedActorID)
	{
		if (spawnedActorID == newSpawnedActorID)
		{
			return;
		}
		if (newSpawnedActorID == -1)
		{
			spawnedActorID = newSpawnedActorID;
			spawnedActor = null;
		}
		else
		{
			if (!CrittersManager.instance.actorById.TryGetValue(newSpawnedActorID, out var value))
			{
				return;
			}
			spawnedActorID = newSpawnedActorID;
			spawnedActor = value;
		}
		this.OnSpawnChanged?.Invoke(spawnedActor);
	}

	public override void SendDataByCrittersActorType(PhotonStream stream)
	{
		base.SendDataByCrittersActorType(stream);
		stream.SendNext(spawnedActorID);
	}

	public override bool UpdateSpecificActor(PhotonStream stream)
	{
		if (!base.UpdateSpecificActor(stream))
		{
			return false;
		}
		if (!CrittersManager.ValidateDataType<int>(stream.ReceiveNext(), out var dataAsType))
		{
			return false;
		}
		if (dataAsType < -1 || dataAsType >= CrittersManager.instance.universalActorId)
		{
			return false;
		}
		UpdateSpawnedActor(dataAsType);
		return true;
	}

	public override int AddActorDataToList(ref List<object> objList)
	{
		base.AddActorDataToList(ref objList);
		objList.Add(spawnedActorID);
		return TotalActorDataLength();
	}

	public override int TotalActorDataLength()
	{
		return BaseActorDataLength() + 1;
	}

	public override int UpdateFromRPC(object[] data, int startingIndex)
	{
		startingIndex += base.UpdateFromRPC(data, startingIndex);
		if (!CrittersManager.ValidateDataType<int>(data[startingIndex], out var dataAsType))
		{
			return TotalActorDataLength();
		}
		if (dataAsType >= -1 && dataAsType < CrittersManager.instance.universalActorId)
		{
			return TotalActorDataLength();
		}
		UpdateSpawnedActor(dataAsType);
		return TotalActorDataLength();
	}
}
