public enum CrittersBiome
{
	Forest = 1,
	Mountain = 2,
	Desert = 4,
	Grassland = 8,
	Cave = 0x10,
	IntroArea = 0x40000000,
	Any = -1
}
public static class CrittersBiomeExtensions
{
	private static List<CrittersBiome> _allScannableBiomes;

	private static Dictionary<CrittersBiome, string> _habitatLookup;

	private static List<CrittersBiome> _habitatBiomes;

	static CrittersBiomeExtensions()
	{
		_habitatLookup = new Dictionary<CrittersBiome, string>();
		_allScannableBiomes = new List<CrittersBiome>();
		foreach (CrittersBiome value in Enum.GetValues(typeof(CrittersBiome)))
		{
			if (value != CrittersBiome.Any && value != CrittersBiome.IntroArea)
			{
				_allScannableBiomes.Add(value);
			}
		}
	}

	public static string GetHabitatDescription(this CrittersBiome biome)
	{
		if (!_habitatLookup.TryGetValue(biome, out var value))
		{
			if (biome == CrittersBiome.Any)
			{
				value = "Any";
			}
			else
			{
				if (_habitatBiomes == null)
				{
					_habitatBiomes = new List<CrittersBiome>();
				}
				_habitatBiomes.Clear();
				for (int i = 0; i < _allScannableBiomes.Count; i++)
				{
					if (biome.HasFlag(_allScannableBiomes[i]))
					{
						_habitatBiomes.Add(_allScannableBiomes[i]);
					}
				}
			}
			value = ((_habitatBiomes.Count > 3) ? "Various" : string.Join(", ", _habitatBiomes));
			_habitatLookup[biome] = value;
		}
		return value;
	}
}
public class CrittersCage : CrittersActor
{
	public Transform grabPosition;

	public Transform cagePosition;

	public float grabDistance;

	[SerializeField]
	private UnityEngine.Vector3[] critterScales = new UnityEngine.Vector3[1] { UnityEngine.Vector3.one };

	[SerializeField]
	private float releaseCooldown = 0.25f;

	[SerializeField]
	private AudioSource sound;

	[SerializeField]
	private AudioClip openSound;

	[SerializeField]
	private AudioClip closeSound;

	public GameObject lid;

	[NonSerialized]
	public bool heldByPlayer;

	[NonSerialized]
	private bool hasCritter;

	[NonSerialized]
	public bool inReleasingPosition;

	private float _releaseCooldownEnd;

	private bool _lidActive;

	public UnityEngine.Vector3 critterScale
	{
		get
		{
			if (subObjectIndex < critterScales.Length && subObjectIndex >= 0)
			{
				return critterScales[subObjectIndex];
			}
			return UnityEngine.Vector3.one;
		}
	}

	public bool CanCatch
	{
		get
		{
			if (heldByPlayer && !hasCritter && !inReleasingPosition)
			{
				return _releaseCooldownEnd <= Time.time;
			}
			return false;
		}
	}

	public void SetHasCritter(bool value)
	{
		if (hasCritter != value && !value)
		{
			_releaseCooldownEnd = Time.time + releaseCooldown;
		}
		hasCritter = value;
		UpdateCageVisuals();
	}

	public override void Initialize()
	{
		base.Initialize();
		hasCritter = false;
		heldByPlayer = false;
		inReleasingPosition = false;
		SetLidActive(active: true, playAudio: false);
	}

	private void UpdateCageVisuals()
	{
		SetLidActive(!heldByPlayer || hasCritter);
	}

	private void SetLidActive(bool active, bool playAudio = true)
	{
		if (active != _lidActive && playAudio)
		{
			sound.GTPlayOneShot(active ? openSound : closeSound);
		}
		lid.SetActive(active);
		_lidActive = active;
	}

	protected override void RemoteGrabbedBy(CrittersActor grabbingActor)
	{
		base.RemoteGrabbedBy(grabbingActor);
		heldByPlayer = grabbingActor.isOnPlayer;
		UpdateCageVisuals();
	}

	public override void GrabbedBy(CrittersActor grabbingActor, bool positionOverride = false, UnityEngine.Quaternion localRotation = default(UnityEngine.Quaternion), UnityEngine.Vector3 localOffset = default(UnityEngine.Vector3), bool disableGrabbing = false)
	{
		base.GrabbedBy(grabbingActor, positionOverride, localRotation, localOffset, disableGrabbing);
		heldByPlayer = grabbingActor.isOnPlayer;
		UpdateCageVisuals();
	}

	public override void Released(bool keepWorldPosition, UnityEngine.Quaternion rotation = default(UnityEngine.Quaternion), UnityEngine.Vector3 position = default(UnityEngine.Vector3), UnityEngine.Vector3 impulseVelocity = default(UnityEngine.Vector3), UnityEngine.Vector3 impulseAngularVelocity = default(UnityEngine.Vector3))
	{
		base.Released(keepWorldPosition, rotation, position, impulseVelocity, impulseAngularVelocity);
		heldByPlayer = false;
		UpdateCageVisuals();
	}

	protected override void HandleRemoteReleased()
	{
		base.HandleRemoteReleased();
		heldByPlayer = false;
		UpdateCageVisuals();
	}

	public override bool ShouldDespawn()
	{
		if (base.ShouldDespawn() && !hasCritter)
		{
			return true;
		}
		return false;
	}

	public override void SendDataByCrittersActorType(PhotonStream stream)
	{
		base.SendDataByCrittersActorType(stream);
		stream.SendNext(hasCritter);
	}

	public override bool UpdateSpecificActor(PhotonStream stream)
	{
		if (!base.UpdateSpecificActor(stream))
		{
			return false;
		}
		if (!CrittersManager.ValidateDataType<bool>(stream.ReceiveNext(), out var dataAsType))
		{
			return false;
		}
		SetHasCritter(dataAsType);
		return true;
	}

	public override int AddActorDataToList(ref List<object> objList)
	{
		base.AddActorDataToList(ref objList);
		objList.Add(hasCritter);
		return TotalActorDataLength();
	}

	public override int TotalActorDataLength()
	{
		return BaseActorDataLength() + 1;
	}

	public override int UpdateFromRPC(object[] data, int startingIndex)
	{
		startingIndex += base.UpdateFromRPC(data, startingIndex);
		if (!CrittersManager.ValidateDataType<bool>(data[startingIndex], out var dataAsType))
		{
			return TotalActorDataLength();
		}
		SetHasCritter(dataAsType);
		return TotalActorDataLength();
	}
}
public class CrittersCageDeposit : CrittersActorDeposit
{
	private bool isHandlingDeposit;

	public UnityEngine.Vector3 depositStartLocation;

	public UnityEngine.Vector3 depositEndLocation;

	public float submitDuration = 0.5f;

	public float returnDuration = 1f;

	public AudioSource depositAudio;

	public AudioClip depositStartSound;

	public AudioClip depositEmptySound;

	public AudioClip depositCritterSound;

	private CrittersActor currentCage;

	public event Action<Menagerie.CritterData, int> OnDepositCritter;

	private void Awake()
	{
		attachPoint.OnGrabbedChild += StartProcessCage;
	}

	protected override bool CanDeposit(CrittersActor depositActor)
	{
		if (base.CanDeposit(depositActor))
		{
			return !isHandlingDeposit;
		}
		return false;
	}

	private void StartProcessCage(CrittersActor depositedActor)
	{
		currentCage = depositedActor;
		StartCoroutine(ProcessCage());
	}

	private IEnumerator ProcessCage()
	{
		isHandlingDeposit = true;
		bool isLocalDeposit = currentCage.lastGrabbedPlayer == PhotonNetwork.LocalPlayer.ActorNumber;
		depositAudio.GTPlayOneShot(depositStartSound, isLocalDeposit ? 1f : 0.5f);
		float transition = 0f;
		CrittersPawn crittersPawn = currentCage.GetComponentInChildren<CrittersPawn>();
		int lastGrabbedPlayer = currentCage.lastGrabbedPlayer;
		Menagerie.CritterData critterData = ((!crittersPawn.IsNotNull()) ? new Menagerie.CritterData() : new Menagerie.CritterData(crittersPawn.visuals));
		while (transition < submitDuration)
		{
			transition += Time.deltaTime;
			attachPoint.transform.localPosition = UnityEngine.Vector3.Lerp(depositStartLocation, depositEndLocation, Mathf.Min(transition / submitDuration, 1f));
			yield return null;
		}
		if (crittersPawn.IsNotNull())
		{
			this.OnDepositCritter?.Invoke(critterData, lastGrabbedPlayer);
			UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
			crittersPawn.Released(keepWorldPosition: false, default(UnityEngine.Quaternion), zero);
			crittersPawn.gameObject.SetActive(value: false);
			depositAudio.GTPlayOneShot(depositCritterSound, isLocalDeposit ? 1f : 0.5f);
		}
		else
		{
			depositAudio.GTPlayOneShot(depositEmptySound, isLocalDeposit ? 1f : 0.5f);
		}
		currentCage.transform.position = UnityEngine.Vector3.zero;
		currentCage.gameObject.SetActive(value: false);
		currentCage = null;
		transition = 0f;
		while (transition < returnDuration)
		{
			transition += Time.deltaTime;
			attachPoint.transform.localPosition = UnityEngine.Vector3.Lerp(depositEndLocation, depositStartLocation, Mathf.Min(transition / returnDuration, 1f));
			yield return null;
		}
		isHandlingDeposit = false;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(base.transform.TransformPoint(depositStartLocation), 0.1f);
		Gizmos.DrawLine(base.transform.TransformPoint(depositStartLocation), base.transform.TransformPoint(depositEndLocation));
		Gizmos.DrawWireSphere(base.transform.TransformPoint(depositEndLocation), 0.1f);
	}
}
