public class CritterSpawnCriteria : ScriptableObject
{
	public string[] spawnTimings;

	public bool CanSpawn()
	{
		if (spawnTimings.Length == 0)
		{
			return true;
		}
		string currentTimeOfDay = BetterDayNightManager.instance.currentTimeOfDay;
		string[] array = spawnTimings;
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i] == currentTimeOfDay)
			{
				return true;
			}
		}
		return false;
	}
}
public class CritterSpawnTrigger : MonoBehaviour
{
	[Header("Trigger Settings")]
	[SerializeField]
	private CrittersActor.CrittersActorType triggerActorType;

	[SerializeField]
	private int requiredSubObjectIndex = -1;

	[SerializeField]
	private string triggerActorName;

	[SerializeField]
	private float triggerCooldown = 1f;

	[Header("Spawn Settings")]
	[SerializeField]
	private Transform spawnPoint;

	[SerializeField]
	private int critterType;

	private float _nextSpawnTime;

	private ValueDropdownList<int> GetCritterTypeList()
	{
		return new ValueDropdownList<int>();
	}

	private void OnTriggerEnter(Collider other)
	{
		if (CrittersManager.instance.LocalAuthority() && !(Time.realtimeSinceStartup < _nextSpawnTime))
		{
			CrittersActor componentInParent = other.GetComponentInParent<CrittersActor>();
			if ((bool)componentInParent && componentInParent.crittersActorType == triggerActorType && (requiredSubObjectIndex < 0 || componentInParent.subObjectIndex == requiredSubObjectIndex) && (string.IsNullOrEmpty(triggerActorName) || componentInParent.GetActorSubtype().Contains(triggerActorName)))
			{
				CrittersManager.instance.DespawnActor(componentInParent);
				CrittersManager.instance.SpawnCritter(critterType, spawnPoint.position, spawnPoint.rotation);
				_nextSpawnTime = Time.realtimeSinceStartup + triggerCooldown;
			}
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawLine(base.transform.position, spawnPoint.position);
		Gizmos.DrawWireSphere(spawnPoint.position, 0.1f);
	}
}
public class CrittersPool : MonoBehaviour
{
	[Serializable]
	public class CrittersPoolSettings
	{
		public GameObject poolObject;

		public int poolSize = 20;
	}

	private static CrittersPool instance;

	public CrittersPoolSettings[] eventEffects;

	private Dictionary<GameObject, List<GameObject>> pools;

	public Transform poolParent;

	public static GameObject GetPooled(GameObject prefab)
	{
		return instance?.GetInstance(prefab);
	}

	public static void Return(GameObject pooledGO)
	{
		instance?.ReturnInstance(pooledGO);
	}

	private void Awake()
	{
		if (instance != null)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		instance = this;
		SetupPools();
	}

	private void SetupPools()
	{
		pools = new Dictionary<GameObject, List<GameObject>>();
		GameObject gameObject = new GameObject("CrittersPool");
		gameObject.transform.parent = base.transform;
		poolParent = gameObject.transform;
		for (int i = 0; i < eventEffects.Length; i++)
		{
			CrittersPoolSettings crittersPoolSettings = eventEffects[i];
			if (crittersPoolSettings.poolObject == null || crittersPoolSettings.poolSize <= 0)
			{
				GTDev.Log("CrittersPool.SetupPools Failed. Pool has no poolObject or has size 0.");
				continue;
			}
			List<GameObject> list = new List<GameObject>();
			for (int j = 0; j < crittersPoolSettings.poolSize; j++)
			{
				GameObject gameObject2 = UnityEngine.Object.Instantiate(crittersPoolSettings.poolObject);
				gameObject2.transform.SetParent(poolParent);
				gameObject2.name += j;
				gameObject2.SetActive(value: false);
				list.Add(gameObject2);
			}
			pools.Add(crittersPoolSettings.poolObject, list);
		}
	}

	private GameObject GetInstance(GameObject prefab)
	{
		if (pools.TryGetValue(prefab, out var value))
		{
			for (int i = 0; i < value.Count; i++)
			{
				if (value[i] != null && !value[i].activeSelf)
				{
					value[i].SetActive(value: true);
					return value[i];
				}
			}
			GTDev.Log("CrittersPool.GetInstance Failed. No available instance.");
			return null;
		}
		GTDev.LogError("CrittersPool.GetInstance Failed. Prefab doesn't have a valid pool setup.");
		return null;
	}

	private void ReturnInstance(GameObject instance)
	{
		instance.transform.SetParent(poolParent);
		instance.SetActive(value: false);
	}
}
public class CrittersRegion : MonoBehaviour
{
	private static List<CrittersRegion> _regions = new List<CrittersRegion>();

	private static Dictionary<int, CrittersRegion> _regionLookup = new Dictionary<int, CrittersRegion>();

	public CrittersBiome Biome = CrittersBiome.Any;

	public int maxCritters = 10;

	public float scale = 10f;

	public List<CrittersPawn> _critters = new List<CrittersPawn>();

	public static List<CrittersRegion> Regions => _regions;

	public int CritterCount => _critters.Count;

	[field: SerializeField]
	public int ID { get; private set; }

	private void OnEnable()
	{
		RegisterRegion(this);
	}

	private void OnDisable()
	{
		UnregisterRegion(this);
	}

	private static void RegisterRegion(CrittersRegion region)
	{
		_regionLookup[region.ID] = region;
		_regions.Add(region);
	}

	private static void UnregisterRegion(CrittersRegion region)
	{
		_regionLookup.Remove(region.ID);
		_regions.Remove(region);
	}

	public static void AddCritterToRegion(CrittersPawn critter, int regionId)
	{
		if (_regionLookup.TryGetValue(regionId, out var value))
		{
			value.AddCritter(critter);
		}
		else
		{
			GTDev.LogError($"Attempted to add critter to non-existing region {regionId}.");
		}
	}

	public static void RemoveCritterFromRegion(CrittersPawn critter)
	{
		if (_regionLookup.TryGetValue(critter.regionId, out var value))
		{
			value.RemoveCritter(critter);
		}
		else
		{
			GTDev.LogError($"Couldn't find region with id {critter.regionId}");
		}
	}

	public void AddCritter(CrittersPawn pawn)
	{
		_critters.Add(pawn);
	}

	public void RemoveCritter(CrittersPawn pawn)
	{
		_critters.Remove(pawn);
	}

	public UnityEngine.Vector3 GetSpawnPoint()
	{
		float num = scale / 2f;
		float num2 = base.transform.lossyScale.y * scale;
		UnityEngine.Vector3 vector = base.transform.TransformPoint(new UnityEngine.Vector3(UnityEngine.Random.Range(0f - num, num), num, UnityEngine.Random.Range(0f - num, num)));
		if (Physics.Raycast(vector, -base.transform.up, out var hitInfo, num2, -1, QueryTriggerInteraction.Ignore))
		{
			UnityEngine.Debug.DrawLine(vector, hitInfo.point, Color.green, 5f);
			return hitInfo.point;
		}
		UnityEngine.Debug.DrawLine(vector, vector - base.transform.up * num2, Color.red, 5f);
		return vector;
	}
}
public class CrittersRigActorSetup : MonoBehaviour
{
	[Serializable]
	public struct RigActor
	{
		public Transform location;

		public CrittersActor.CrittersActorType type;

		public int subIndex;

		public CrittersActor actorSet;
	}

	public RigActor[] rigActors;

	public List<object> rigActorData = new List<object>();

	public VRRig myRig;

	public void OnEnable()
	{
		CrittersManager.RegisterRigActorSetup(this);
	}

	public void OnDisable()
	{
		for (int i = 0; i < rigActors.Length; i++)
		{
			rigActors[i].actorSet = null;
		}
	}

	private CrittersActor RefreshActorForIndex(int index)
	{
		RigActor rigActor = rigActors[index];
		if (rigActor.actorSet.IsNotNull())
		{
			rigActor.actorSet.gameObject.SetActive(value: false);
		}
		CrittersActor crittersActor = CrittersManager.instance.SpawnActor(rigActor.type, rigActor.subIndex);
		if (GTExt.IsNull(crittersActor))
		{
			return null;
		}
		crittersActor.isOnPlayer = true;
		crittersActor.rigIndex = index;
		crittersActor.rigPlayerId = myRig.Creator.ActorNumber;
		if (crittersActor.rigPlayerId == -1 && PhotonNetwork.InRoom)
		{
			crittersActor.rigPlayerId = PhotonNetwork.LocalPlayer.ActorNumber;
		}
		crittersActor.PlacePlayerCrittersActor();
		return crittersActor;
	}

	public void CheckUpdate(ref List<object> refActorData, bool forceCheck = false)
	{
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		for (int i = 0; i < rigActors.Length; i++)
		{
			RigActor rigActor = rigActors[i];
			if (forceCheck || rigActor.actorSet == null || (rigActor.actorSet.rigPlayerId != myRig.Creator.ActorNumber && VRRigCache.Instance.TryGetVrrig(myRig.Creator, out var _) && CrittersManager.instance.rigSetupByRig.ContainsKey(myRig)))
			{
				RefreshActorForIndex(i)?.AddPlayerCrittersActorDataToList(ref refActorData);
			}
		}
	}
}
public class CrittersStickyGoo : CrittersActor
{
	[Header("Sticky Goo")]
	public float range = 1f;

	public float slowModifier = 0.3f;

	public float slowDuration = 3f;

	public bool destroyOnApply = true;

	private bool readyToDisable;

	public override void Initialize()
	{
		base.Initialize();
		readyToDisable = false;
	}

	public bool CanAffect(UnityEngine.Vector3 position)
	{
		return (base.transform.position - position).magnitude < range;
	}

	public void EffectApplied(CrittersPawn critter)
	{
		if (destroyOnApply)
		{
			readyToDisable = true;
		}
		CrittersManager.instance.TriggerEvent(CrittersManager.CritterEvent.StickyTriggered, actorId, critter.transform.position, UnityEngine.Quaternion.LookRotation(critter.transform.up));
	}

	public override bool ProcessLocal()
	{
		bool result = base.ProcessLocal();
		if (readyToDisable)
		{
			base.gameObject.SetActive(value: false);
			return true;
		}
		return result;
	}
}
public class CrittersStickyTrap : CrittersToolThrowable
{
	[Header("Sticky Trap")]
	public bool stickOnImpact = true;

	public int subStickyGooIndex = -1;

	private bool isStuck;

	public override void Initialize()
	{
		base.Initialize();
		TogglePhysics(!isStuck);
	}

	public override void OnDisable()
	{
		base.OnDisable();
		isStuck = false;
	}

	public override void SetImpulse()
	{
		if (!isOnPlayer && !isSceneActor)
		{
			localLastImpulse = lastImpulseTime;
			MoveActor(lastImpulsePosition, lastImpulseQuaternion, parentActorId >= 0, updateImpulses: false);
			TogglePhysics(usesRB && parentActorId == -1 && !isStuck);
			if (!rb.isKinematic)
			{
				rb.linearVelocity = lastImpulseVelocity;
				rb.angularVelocity = lastImpulseAngularVelocity;
			}
		}
	}

	protected override void OnImpact(UnityEngine.Vector3 hitPosition, UnityEngine.Vector3 hitNormal)
	{
		if (CrittersManager.instance.LocalAuthority())
		{
			if (stickOnImpact)
			{
				rb.isKinematic = true;
				isStuck = true;
				updatedSinceLastFrame = true;
				UpdateImpulses(local: false, updateTime: true);
			}
			CrittersStickyGoo crittersStickyGoo = (CrittersStickyGoo)CrittersManager.instance.SpawnActor(CrittersActorType.StickyGoo, subStickyGooIndex);
			if (!(crittersStickyGoo == null))
			{
				CrittersManager.instance.TriggerEvent(CrittersManager.CritterEvent.StickyDeployed, actorId, base.transform.position, UnityEngine.Quaternion.LookRotation(hitNormal));
				UnityEngine.Vector3 forward = base.transform.forward;
				forward -= hitNormal * UnityEngine.Vector3.Dot(hitNormal, forward);
				crittersStickyGoo.MoveActor(hitPosition, UnityEngine.Quaternion.LookRotation(forward, hitNormal));
				crittersStickyGoo.SetImpulseVelocity(UnityEngine.Vector3.zero, UnityEngine.Vector3.zero);
				UpdateImpulses(local: true);
			}
		}
	}

	protected override void OnImpactCritter(CrittersPawn impactedCritter)
	{
		OnImpact(impactedCritter.transform.position, impactedCritter.transform.up);
	}

	protected override void OnPickedUp()
	{
		if (isStuck)
		{
			isStuck = false;
			updatedSinceLastFrame = true;
		}
	}

	public override void SendDataByCrittersActorType(PhotonStream stream)
	{
		base.SendDataByCrittersActorType(stream);
		stream.SendNext(isStuck);
	}

	public override bool UpdateSpecificActor(PhotonStream stream)
	{
		if (!(base.UpdateSpecificActor(stream) & CrittersManager.ValidateDataType<bool>(stream.ReceiveNext(), out var dataAsType)))
		{
			return false;
		}
		isStuck = dataAsType;
		TogglePhysics(!isStuck);
		return true;
	}

	public override int AddActorDataToList(ref List<object> objList)
	{
		base.AddActorDataToList(ref objList);
		objList.Add(isStuck);
		return TotalActorDataLength();
	}

	public override int TotalActorDataLength()
	{
		return BaseActorDataLength() + 1;
	}

	public override int UpdateFromRPC(object[] data, int startingIndex)
	{
		startingIndex += base.UpdateFromRPC(data, startingIndex);
		if (!CrittersManager.ValidateDataType<bool>(data[startingIndex], out var dataAsType))
		{
			return TotalActorDataLength();
		}
		isStuck = dataAsType;
		TogglePhysics(!isStuck);
		return TotalActorDataLength();
	}
}
public class CrittersStunBomb : CrittersToolThrowable
{
	[Header("Stun Bomb")]
	public float radius = 1f;

	public float stunDuration = 5f;

	protected override void OnImpact(UnityEngine.Vector3 hitPosition, UnityEngine.Vector3 hitNormal)
	{
		if (!CrittersManager.instance.LocalAuthority())
		{
			return;
		}
		UnityEngine.Vector3 position = base.transform.position;
		List<CrittersPawn> crittersPawns = CrittersManager.instance.crittersPawns;
		for (int i = 0; i < crittersPawns.Count; i++)
		{
			CrittersPawn crittersPawn = crittersPawns[i];
			if (crittersPawn.isActiveAndEnabled && UnityEngine.Vector3.Distance(crittersPawn.transform.position, position) < radius)
			{
				crittersPawn.Stunned(stunDuration);
			}
		}
		CrittersManager.instance.TriggerEvent(CrittersManager.CritterEvent.StunExplosion, actorId, position, UnityEngine.Quaternion.LookRotation(hitNormal));
	}

	protected override void OnImpactCritter(CrittersPawn impactedCritter)
	{
		if (CrittersManager.instance.LocalAuthority())
		{
			impactedCritter.Stunned(stunDuration);
		}
	}
}
public class CrittersToolThrowable : CrittersActor
{
	[Header("Throwable")]
	public bool requiresPlayerGrabBeforeActivate = true;

	public float requiredActivationSpeed = 2f;

	public bool onlyTriggerOnDirectCritterHit;

	public bool destroyOnImpact = true;

	public bool onlyTriggerOncePerGrab = true;

	[Header("Debug")]
	[SerializeField]
	private DelayedDestroyObject debugImpactPrefab;

	private bool hasBeenGrabbedByPlayer;

	protected bool shouldDisable;

	private bool hasTriggeredSinceLastGrab;

	private float _sqrActivationSpeed;

	public override void Initialize()
	{
		base.Initialize();
		hasBeenGrabbedByPlayer = false;
		shouldDisable = false;
		hasTriggeredSinceLastGrab = false;
		_sqrActivationSpeed = requiredActivationSpeed * requiredActivationSpeed;
	}

	public override void GrabbedBy(CrittersActor grabbingActor, bool positionOverride = false, UnityEngine.Quaternion localRotation = default(UnityEngine.Quaternion), UnityEngine.Vector3 localOffset = default(UnityEngine.Vector3), bool disableGrabbing = false)
	{
		base.GrabbedBy(grabbingActor, positionOverride, localRotation, localOffset, disableGrabbing);
		hasBeenGrabbedByPlayer = true;
		hasTriggeredSinceLastGrab = false;
		OnPickedUp();
	}

	public void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (CrittersManager.instance.containerLayer.Contains(collision.gameObject.layer) || (requiresPlayerGrabBeforeActivate && !hasBeenGrabbedByPlayer) || (_sqrActivationSpeed > 0f && collision.relativeVelocity.sqrMagnitude < _sqrActivationSpeed) || (onlyTriggerOncePerGrab && hasTriggeredSinceLastGrab))
		{
			return;
		}
		if (onlyTriggerOnDirectCritterHit)
		{
			CrittersPawn component = collision.gameObject.GetComponent<CrittersPawn>();
			if (component != null && component.isActiveAndEnabled)
			{
				hasTriggeredSinceLastGrab = true;
				OnImpactCritter(component);
			}
		}
		else
		{
			UnityEngine.Vector3 point = collision.contacts[0].point;
			UnityEngine.Vector3 normal = collision.contacts[0].normal;
			hasTriggeredSinceLastGrab = true;
			OnImpact(point, normal);
		}
		if (destroyOnImpact)
		{
			shouldDisable = true;
		}
	}

	protected virtual void OnImpact(UnityEngine.Vector3 hitPosition, UnityEngine.Vector3 hitNormal)
	{
	}

	protected virtual void OnImpactCritter(CrittersPawn impactedCritter)
	{
	}

	protected virtual void OnPickedUp()
	{
	}

	[Conditional("DRAW_DEBUG")]
	protected void ShowDebugVisualization(UnityEngine.Vector3 position, float scale, float duration = 0f)
	{
		if ((bool)debugImpactPrefab)
		{
			DelayedDestroyObject delayedDestroyObject = UnityEngine.Object.Instantiate(debugImpactPrefab, position, UnityEngine.Quaternion.identity);
			delayedDestroyObject.transform.localScale *= scale;
			if (duration != 0f)
			{
				delayedDestroyObject.lifetime = duration;
			}
		}
	}

	public override bool ProcessLocal()
	{
		bool result = base.ProcessLocal();
		if (shouldDisable)
		{
			base.gameObject.SetActive(value: false);
			return true;
		}
		return result;
	}

	public override void TogglePhysics(bool enable)
	{
		if (enable)
		{
			rb.isKinematic = false;
			rb.interpolation = RigidbodyInterpolation.Interpolate;
			rb.collisionDetectionMode = CollisionDetectionMode.Continuous;
		}
		else
		{
			rb.isKinematic = true;
			rb.interpolation = RigidbodyInterpolation.None;
			rb.collisionDetectionMode = CollisionDetectionMode.Continuous;
		}
	}
}
public class CrittersVoiceNoise : MonoBehaviour, IGorillaSliceableSimple
{
	[SerializeField]
	private GorillaSpeakerLoudness speaker;

	[SerializeField]
	private VRRig rig;

	[SerializeField]
	private float minTriggerThreshold = 0.01f;

	[SerializeField]
	private float maxTriggerThreshold = 0.3f;

	[SerializeField]
	private float noiseVolumeMin = 1f;

	[SerializeField]
	private float noisVolumeMax = 9f;

	private void Start()
	{
		speaker = GetComponent<GorillaSpeakerLoudness>();
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void SliceUpdate()
	{
		float num = 0f;
		if (speaker.IsSpeaking)
		{
			num = speaker.Loudness;
		}
		if (num > minTriggerThreshold && CrittersManager.instance.IsNotNull())
		{
			CrittersLoudNoise crittersLoudNoise = (CrittersLoudNoise)CrittersManager.instance.rigSetupByRig[rig].rigActors[4].actorSet;
			if (crittersLoudNoise.IsNotNull() && !crittersLoudNoise.soundEnabled)
			{
				float volume = Mathf.Lerp(noiseVolumeMin, noisVolumeMax, Mathf.Clamp01((num - minTriggerThreshold) / maxTriggerThreshold));
				crittersLoudNoise.PlayVoiceSpeechLocal(PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time), 1f / 60f, volume);
			}
		}
	}
}
