	}

	private void SetMeanStrength(float meanStrength = 1f)
	{
		float rMSMagnitude = grabbedStruggleHaptics.GetRMSMagnitude();
		UnityEngine.Debug.Log($"Clip {grabbedStruggleHaptics} mean strength: {rMSMagnitude}");
		if (meanStrength > 0f)
