public struct CritterAppearance(string hatName, float size = 1f)
{
	public float size = size;

	public string hatName = hatName;

	public object[] WriteToRPCData()
	{
		object[] array = new object[2] { hatName, size };
		if (hatName == null)
		{
			array[0] = string.Empty;
		}
		if (size != 0f)
		{
			array[1] = size;
		}
		return array;
	}

	public static int DataLength()
	{
		return 2;
	}

	public static bool ValidateData(object[] data)
	{
		if (data == null || data.Length != DataLength())
		{
			return false;
		}
		if (!CrittersManager.ValidateDataType<float>(data[1], out var dataAsType))
		{
			return false;
		}
		if (dataAsType < 0f || float.IsNaN(dataAsType) || float.IsInfinity(dataAsType))
		{
			return false;
		}
		return true;
	}

	public static CritterAppearance ReadFromRPCData(object[] data)
	{
		if (!CrittersManager.ValidateDataType<string>(data[0], out var _))
		{
			return new CritterAppearance(string.Empty);
		}
		if (!CrittersManager.ValidateDataType<float>(data[1], out var dataAsType2))
		{
			return new CritterAppearance(string.Empty);
		}
		return new CritterAppearance((string)data[0], dataAsType2.GetFinite());
	}

	public static CritterAppearance ReadFromPhotonStream(PhotonStream data)
	{
		string obj = (string)data.ReceiveNext();
		float num = (float)data.ReceiveNext();
		return new CritterAppearance(obj, num);
	}

	public override string ToString()
	{
		return $"Size: {size} Hat: {hatName}";
	}
}
public class CritterVisuals : MonoBehaviour
{
	public int critterType;

	[Header("Visuals")]
	public Transform bodyRoot;

	public MeshRenderer myRenderer;

	public MeshFilter myMeshFilter;

	public Transform hatRoot;

	public GameObject[] hats;

	private CritterAppearance _appearance;

	public CritterAppearance Appearance => _appearance;

	public void SetAppearance(CritterAppearance appearance)
	{
		_appearance = appearance;
		float num = _appearance.size.ClampSafe(0.25f, 1.5f);
		bodyRoot.localScale = new UnityEngine.Vector3(num, num, num);
		if (!string.IsNullOrEmpty(appearance.hatName))
		{
			GameObject[] array = hats;
			foreach (GameObject obj in array)
			{
				obj.SetActive(obj.name == _appearance.hatName);
			}
			hatRoot.gameObject.SetActive(value: true);
		}
		else
		{
			hatRoot.gameObject.SetActive(value: false);
		}
	}

	public void ApplyMesh(Mesh newMesh)
	{
		myMeshFilter.sharedMesh = newMesh;
	}

	public void ApplyMaterial(Material mat)
	{
		myRenderer.sharedMaterial = mat;
	}
}
public class DebugTestGrabber : MonoBehaviour
{
	public bool isGrabbing;

	public bool setIsGrabbing;

	public bool setRelease;

	public Collider[] colliders = new Collider[50];

	public bool isLeft;

	public float grabRadius = 0.05f;

	public Transform transformToFollow;

	public GorillaVelocityEstimator estimator;

	public CrittersGrabber grabber;

	public CrittersActorGrabber otherHand;

	private bool isHandGrabbingDisabled;

	private float grabDuration = 0.3f;

	private float remainingGrabDuration;

	private void Awake()
	{
		if (grabber == null)
		{
			grabber = GetComponentInChildren<CrittersGrabber>();
		}
	}

	private void LateUpdate()
	{
		if (transformToFollow != null)
		{
			base.transform.rotation = transformToFollow.rotation;
			base.transform.position = transformToFollow.position;
		}
		if (!(grabber == null))
		{
			if (!isGrabbing && setIsGrabbing)
			{
				setIsGrabbing = false;
				isGrabbing = true;
				remainingGrabDuration = grabDuration;
			}
			else if (isGrabbing && setRelease)
			{
				setRelease = false;
				isGrabbing = false;
				DoRelease();
			}
			if (isGrabbing && remainingGrabDuration > 0f)
			{
				remainingGrabDuration -= Time.deltaTime;
				DoGrab();
			}
		}
	}

	private void DoGrab()
	{
		grabber.grabbing = true;
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, grabRadius, colliders, LayerMask.GetMask("GorillaInteractable"));
		if (num <= 0)
		{
			return;
		}
		for (int i = 0; i < num; i++)
		{
			CrittersActor componentInParent = colliders[i].GetComponentInParent<CrittersActor>();
			if (!(componentInParent == null) && componentInParent.usesRB && componentInParent.CanBeGrabbed(grabber))
			{
				isHandGrabbingDisabled = true;
				if (componentInParent.equipmentStorable)
				{
					componentInParent.localCanStore = true;
				}
				componentInParent.GrabbedBy(grabber);
				grabber.grabbedActors.Add(componentInParent);
				remainingGrabDuration = 0f;
				break;
			}
		}
	}

	private void DoRelease()
	{
		grabber.grabbing = false;
		for (int num = grabber.grabbedActors.Count - 1; num >= 0; num--)
		{
			CrittersActor crittersActor = grabber.grabbedActors[num];
			crittersActor.Released(keepWorldPosition: true, crittersActor.transform.rotation, crittersActor.transform.position, estimator.linearVelocity);
			if (num < grabber.grabbedActors.Count)
			{
				grabber.grabbedActors.RemoveAt(num);
			}
		}
		if (isHandGrabbingDisabled)
		{
			isHandGrabbingDisabled = false;
		}
	}
}
public class DelayedDestroyCrittersPooledObject : MonoBehaviour
{
	public float destroyDelay = 1f;

	private float timeToDie = -1f;

	protected void OnEnable()
	{
		if (!(ObjectPools.instance == null) && ObjectPools.instance.initialized)
		{
			timeToDie = Time.time + destroyDelay;
		}
	}

	protected void LateUpdate()
	{
		if (Time.time >= timeToDie)
		{
			CrittersPool.Return(base.gameObject);
		}
	}
}
public class DelayedDestroyObject : MonoBehaviour
{
	public float lifetime = 10f;

	private float _timeToDie;

	private void Start()
	{
		_timeToDie = Time.time + lifetime;
	}

	private void LateUpdate()
	{
		if (Time.time >= _timeToDie)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}
}
public class Menagerie : MonoBehaviour
{
	public class CritterData
	{
		public int critterType;

		public CritterAppearance appearance;

		[NonSerialized]
		public MenagerieCritter instance;

		public CritterConfiguration GetConfiguration()
		{
			return CrittersManager.instance.creatureIndex[critterType];
		}

		public CritterData()
		{
		}

		public CritterData(CritterConfiguration config, CritterAppearance appearance)
		{
			critterType = CrittersManager.instance.creatureIndex.critterTypes.IndexOf(config);
			this.appearance = appearance;
		}

		public CritterData(int critterType, CritterAppearance appearance)
		{
			this.critterType = critterType;
			this.appearance = appearance;
		}

		public CritterData(CritterVisuals visuals)
		{
			critterType = visuals.critterType;
			appearance = visuals.Appearance;
		}

		public CritterData(CritterData source)
		{
			critterType = source.critterType;
			appearance = source.appearance;
		}

		public override string ToString()
		{
			return $"{critterType} {appearance} [instance]";
		}
	}

	[Serializable]
	public class CritterSaveData
	{
		public List<CritterData> newCritters = new List<CritterData>();

		public Dictionary<int, CritterData> collectedCritters = new Dictionary<int, CritterData>();

		public int donatedCritterCount;

		public int favoriteCritter = -1;

		public void Clear()
		{
			newCritters.Clear();
			collectedCritters.Clear();
			donatedCritterCount = 0;
			favoriteCritter = -1;
		}
	}

	[FormerlySerializedAs("creatureIndex")]
	public CritterIndex critterIndex;

	public MenagerieCritter prefab;

	private List<MenagerieCritter> _critters = new List<MenagerieCritter>();

	private CritterSaveData _savedCritters = new CritterSaveData();

	public MenagerieSlot[] collection;

	public MenagerieSlot[] newCritterPen;

	public MenagerieSlot favoriteCritterSlot;

	private int _collectionPageIndex;

	private int _totalPages;

	public MenagerieDepositBox DonationBox;

	public MenagerieDepositBox FavoriteBox;

	public MenagerieDepositBox CollectionBox;

	public TextMeshPro donationCounter;

	public string DonationText = "DONATED:{0}";

	private const string CrittersSavePrefsKey = "_SavedCritters";

	private void Start()
	{
		CrittersCageDeposit[] array = UnityEngine.Object.FindObjectsByType<CrittersCageDeposit>(FindObjectsInactive.Include, FindObjectsSortMode.None);
		for (int i = 0; i < array.Length; i++)
		{
			array[i].OnDepositCritter += OnDepositCritter;
		}
		CrittersManager.CheckInitialize();
		_totalPages = critterIndex.critterTypes.Count / collection.Length + ((critterIndex.critterTypes.Count % collection.Length != 0) ? 1 : 0);
		Load();
		MenagerieDepositBox donationBox = DonationBox;
		donationBox.OnCritterInserted = (Action<MenagerieCritter>)Delegate.Combine(donationBox.OnCritterInserted, new Action<MenagerieCritter>(CritterDepositedInDonationBox));
		MenagerieDepositBox favoriteBox = FavoriteBox;
		favoriteBox.OnCritterInserted = (Action<MenagerieCritter>)Delegate.Combine(favoriteBox.OnCritterInserted, new Action<MenagerieCritter>(CritterDepositedInFavoriteBox));
		MenagerieDepositBox collectionBox = CollectionBox;
		collectionBox.OnCritterInserted = (Action<MenagerieCritter>)Delegate.Combine(collectionBox.OnCritterInserted, new Action<MenagerieCritter>(CritterDepositedInCollectionBox));
	}

	private void CritterDepositedInDonationBox(MenagerieCritter critter)
	{
		if (Enumerable.Contains(newCritterPen, critter.Slot))
		{
			critter.currentState = MenagerieCritter.MenagerieCritterState.Donating;
			DonateCritter(critter.CritterData);
			_savedCritters.newCritters.Remove(critter.CritterData);
			DespawnCritterFromSlot(critter.Slot);
			Save();
			PlayerGameEvents.CritterEvent("Donate" + critterIndex[critter.CritterData.critterType].critterName);
		}
	}

	private void CritterDepositedInFavoriteBox(MenagerieCritter critter)
	{
		if (Enumerable.Contains(collection, critter.Slot))
		{
			_savedCritters.favoriteCritter = critter.CritterData.critterType;
			Save();
			UpdateFavoriteCritter();
			PlayerGameEvents.CritterEvent("Favorite" + critterIndex[critter.CritterData.critterType].critterName);
		}
	}

	private void CritterDepositedInCollectionBox(MenagerieCritter critter)
	{
		if (Enumerable.Contains(newCritterPen, critter.Slot))
		{
			AddCritterToCollection(critter.CritterData);
			_savedCritters.newCritters.Remove(critter.CritterData);
			DespawnCritterFromSlot(critter.Slot);
			Save();
			UpdateFavoriteCritter();
			PlayerGameEvents.CritterEvent("Collect" + critterIndex[critter.CritterData.critterType].critterName);
		}
	}

	private void OnDepositCritter(CritterData depositedCritter, int playerID)
	{
		try
		{
			if (playerID == PhotonNetwork.LocalPlayer.ActorNumber)
			{
				AddCritterToNewCritterPen(depositedCritter);
				Save();
			}
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
	}

	private void AddCritterToNewCritterPen(CritterData critterData)
	{
		if (_savedCritters.newCritters.Count < newCritterPen.Length)
		{
			MenagerieSlot[] array = newCritterPen;
			foreach (MenagerieSlot menagerieSlot in array)
			{
				if (!menagerieSlot.critter)
				{
					SpawnCritterInSlot(menagerieSlot, critterData);
					_savedCritters.newCritters.Add(critterData);
					return;
				}
			}
		}
		DonateCritter(critterData);
		Save();
	}

	private void AddCritterToCollection(CritterData critterData)
	{
		if (_savedCritters.collectedCritters.TryGetValue(critterData.critterType, out var value))
		{
			DonateCritter(value);
		}
		_savedCritters.collectedCritters[critterData.critterType] = critterData;
		SpawnCollectionCritterIfShowing(critterData);
	}

	private void DonateCritter(CritterData critterData)
	{
		_savedCritters.donatedCritterCount++;
		donationCounter.SetText(string.Format(DonationText, _savedCritters.donatedCritterCount));
	}

	private void SpawnCritterInSlot(MenagerieSlot slot, CritterData critterData)
	{
		if (!GTExt.IsNull(slot) && critterData != null)
		{
			DespawnCritterFromSlot(slot);
			MenagerieCritter menagerieCritter = UnityEngine.Object.Instantiate(prefab, slot.critterMountPoint);
			menagerieCritter.Slot = slot;
			menagerieCritter.ApplyCritterData(critterData);
			_critters.Add(menagerieCritter);
			if ((bool)slot.label)
			{
				slot.label.text = critterIndex[critterData.critterType].critterName;
			}
		}
	}

	private void SpawnCollectionCritterIfShowing(CritterData critter)
	{
		int num = critter.critterType - _collectionPageIndex * collection.Length;
		if (num >= 0 && num < collection.Length)
		{
			SpawnCritterInSlot(collection[num], critter);
		}
	}

	private void UpdateMenagerie()
	{
		UpdateNewCritterPen();
		UpdateCollection();
		UpdateFavoriteCritter();
		donationCounter.SetText(string.Format(DonationText, _savedCritters.donatedCritterCount));
	}

	private void UpdateNewCritterPen()
	{
		for (int i = 0; i < newCritterPen.Length; i++)
		{
			if (i < _savedCritters.newCritters.Count)
			{
				SpawnCritterInSlot(newCritterPen[i], _savedCritters.newCritters[i]);
			}
			else
			{
				DespawnCritterFromSlot(newCritterPen[i]);
			}
		}
	}

	private void UpdateCollection()
	{
		int num = _collectionPageIndex * collection.Length;
		for (int i = 0; i < collection.Length; i++)
		{
			int num2 = num + i;
			MenagerieSlot menagerieSlot = collection[i];
			if (_savedCritters.collectedCritters.TryGetValue(num2, out var value))
			{
				SpawnCritterInSlot(menagerieSlot, value);
				continue;
			}
			DespawnCritterFromSlot(menagerieSlot);
			CritterConfiguration critterConfiguration = critterIndex[num2];
			menagerieSlot.label.text = ((critterConfiguration == null) ? "" : "??????");
		}
	}

	private void UpdateFavoriteCritter()
	{
		if (_savedCritters.collectedCritters.TryGetValue(_savedCritters.favoriteCritter, out var value))
		{
			SpawnCritterInSlot(favoriteCritterSlot, value);
		}
		else
		{
			ClearSlot(favoriteCritterSlot);
		}
	}

	public void NextGroupCollectedCritters()
	{
		_collectionPageIndex++;
		if (_collectionPageIndex >= _totalPages)
		{
			_collectionPageIndex = 0;
		}
		UpdateCollection();
	}

	public void PrevGroupCollectedCritters()
	{
		_collectionPageIndex--;
		if (_collectionPageIndex < 0)
		{
			_collectionPageIndex = _totalPages - 1;
		}
		UpdateCollection();
	}

	private void GenerateNewCritters()
	{
		GenerateNewCritterCount(UnityEngine.Random.Range(Mathf.Min(1, newCritterPen.Length), newCritterPen.Length + 1));
	}

	private void GenerateLegalNewCritters()
	{
		ClearNewCritterPen();
		for (int i = 0; i < newCritterPen.Length; i++)
		{
			int randomCritterType = critterIndex.GetRandomCritterType();
			if (randomCritterType < 0)
			{
				UnityEngine.Debug.LogError("Failed to spawn valid critter. No critter configuration found.");
				break;
			}
			CritterData critterData = new CritterData(randomCritterType, critterIndex[randomCritterType].GenerateAppearance());
			AddCritterToNewCritterPen(critterData);
		}
	}

	private void GenerateNewCritterCount(int critterCount)
	{
		ClearNewCritterPen();
		for (int i = 0; i < critterCount; i++)
		{
			int num = UnityEngine.Random.Range(0, critterIndex.critterTypes.Count);
			CritterConfiguration critterConfiguration = critterIndex[num];
			CritterData critterData = new CritterData(num, critterConfiguration.GenerateAppearance());
			AddCritterToNewCritterPen(critterData);
		}
	}

	private void GenerateCollectedCritters(float spawnChance)
	{
		ClearCollection();
		for (int i = 0; i < critterIndex.critterTypes.Count; i++)
		{
			if (UnityEngine.Random.value <= spawnChance)
			{
				CritterConfiguration critterConfiguration = critterIndex[i];
				CritterData critterData = new CritterData(i, critterConfiguration.GenerateAppearance());
				AddCritterToCollection(critterData);
				_ = (bool)critterData.instance;
			}
		}
	}

	private void MoveNewCrittersToCollection()
	{
		MenagerieSlot[] array = newCritterPen;
		foreach (MenagerieSlot menagerieSlot in array)
		{
			if ((bool)menagerieSlot.critter)
			{
				CritterDepositedInCollectionBox(menagerieSlot.critter);
			}
		}
	}

	private void DonateNewCritters()
	{
		MenagerieSlot[] array = newCritterPen;
		foreach (MenagerieSlot menagerieSlot in array)
		{
			if ((bool)menagerieSlot.critter)
			{
				CritterDepositedInDonationBox(menagerieSlot.critter);
			}
		}
	}

	private void ClearSlot(MenagerieSlot slot)
	{
		DespawnCritterFromSlot(slot);
		if ((bool)slot.label)
		{
			slot.label.text = "";
		}
	}

	private void DespawnCritterFromSlot(MenagerieSlot slot)
	{
		if (!GTExt.IsNull(slot) && (bool)slot.critter)
		{
			_critters.Remove(slot.critter);
			UnityEngine.Object.Destroy(slot.critter.gameObject);
			slot.critter = null;
			if ((bool)slot.label)
			{
				slot.label.text = "";
			}
		}
	}

	private void ClearNewCritterPen()
	{
		_savedCritters.newCritters.Clear();
		UpdateNewCritterPen();
	}

	private void ClearCollection()
	{
		_savedCritters.collectedCritters.Clear();
		UpdateCollection();
		UpdateFavoriteCritter();
	}

	private void ClearAll()
	{
		_savedCritters.Clear();
		UpdateMenagerie();
	}

	private void ResetSavedCreatures()
	{
		ClearAll();
		Save();
	}

	private void Load()
	{
		ClearAll();
		string jsonString = PlayerPrefs.GetString("_SavedCritters", string.Empty);
		LoadCrittersFromJson(jsonString);
		UpdateMenagerie();
	}

	private void Save()
	{
		UnityEngine.Debug.Log($"Saving {_critters.Count} critters");
		string value = SaveCrittersToJson();
		PlayerPrefs.SetString("_SavedCritters", value);
	}

	private void LoadCrittersFromJson(string jsonString)
	{
		_savedCritters.Clear();
		if (!string.IsNullOrEmpty(jsonString))
		{
			try
			{
				_savedCritters = JsonConvert.DeserializeObject<CritterSaveData>(jsonString);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogError("Unable to deserialize critters from json: " + jsonString);
				UnityEngine.Debug.LogException(exception);
			}
		}
		ValidateSaveData();
	}

	private string SaveCrittersToJson()
	{
		ValidateSaveData();
		string text = JsonConvert.SerializeObject(_savedCritters, Formatting.Indented);
		UnityEngine.Debug.Log("Critters save to JSON: " + text);
		return text;
	}

	private void ValidateSaveData()
	{
		if (_savedCritters.newCritters.Count > newCritterPen.Length)
		{
			UnityEngine.Debug.LogError($"Too many new critters in CrittersSaveData ({_savedCritters.newCritters.Count} vs {newCritterPen.Length}) - correcting.");
			while (_savedCritters.newCritters.Count > newCritterPen.Length)
			{
				_savedCritters.newCritters.RemoveAt(newCritterPen.Length);
			}
			Save();
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		MenagerieSlot[] array = newCritterPen;
		for (int i = 0; i < array.Length; i++)
		{
			Gizmos.DrawWireSphere(array[i].critterMountPoint.position, 0.1f);
		}
		array = collection;
		for (int i = 0; i < array.Length; i++)
		{
			Gizmos.DrawWireSphere(array[i].critterMountPoint.position, 0.1f);
		}
		Gizmos.DrawWireSphere(favoriteCritterSlot.critterMountPoint.position, 0.1f);
	}
}
public class MenagerieCritter : MonoBehaviour, IHoldableObject, IEyeScannable
{
	public enum MenagerieCritterState
	{
		Donating,
		Displaying
	}

	public CritterVisuals visuals;

	public Collider bodyCollider;

	[Header("Feedback")]
	public CrittersAnim heldAnimation;

	public AudioClip grabbedHaptics;

	public float grabbedHapticsStrength = 1f;

	public GameObject grabbedFX;

	private CrittersAnim _currentAnim;

	private float _currentAnimTime;

	private Transform _animRoot;

	private UnityEngine.Vector3 _bodyScale;

	public MenagerieCritterState currentState = MenagerieCritterState.Displaying;

	private CritterConfiguration _critterConfiguration;

	private Menagerie.CritterData _critterData;

	private MenagerieSlot _slot;

	private List<GorillaGrabber> activeGrabbers = new List<GorillaGrabber>();

	private GameObject heldBy;

	private bool isHeld;

	private bool isHeldLeftHand;

	public Action<MenagerieCritter> OnReleased;

	private KeyValueStringPair[] eyeScanData = new KeyValueStringPair[6];

	public Menagerie.CritterData CritterData => _critterData;

	public MenagerieSlot Slot
	{
		get
		{
			return _slot;
		}
		set
		{
			if (!(value == _slot))
			{
				if ((bool)_slot && _slot.critter == this)
				{
					_slot.critter = null;
				}
				_slot = value;
				if ((bool)_slot)
				{
					_slot.critter = this;
				}
			}
		}
	}

	public bool TwoHanded => false;

	int IEyeScannable.scannableId => base.gameObject.GetInstanceID();

	UnityEngine.Vector3 IEyeScannable.Position => bodyCollider.bounds.center;

	Bounds IEyeScannable.Bounds => bodyCollider.bounds;

	IList<KeyValueStringPair> IEyeScannable.Entries => BuildEyeScannerData();

	public event Action OnDataChange;

	private void Update()
	{
		UpdateAnimation();
	}

	public void ApplyCritterData(Menagerie.CritterData critterData)
	{
		_critterData = critterData;
		_critterConfiguration = _critterData.GetConfiguration();
		_critterData.instance = this;
		_critterData.GetConfiguration().ApplyVisualsTo(visuals, generateAppearance: false);
		visuals.SetAppearance(_critterData.appearance);
		_animRoot = visuals.bodyRoot;
		_bodyScale = _animRoot.localScale;
		PlayAnimation(heldAnimation, UnityEngine.Random.value);
	}

	private void PlayAnimation(CrittersAnim anim, float time = 0f)
	{
		_currentAnim = anim;
		_currentAnimTime = time;
		if (_currentAnim == null)
		{
			_animRoot.localPosition = UnityEngine.Vector3.zero;
			_animRoot.localRotation = UnityEngine.Quaternion.identity;
			_animRoot.localScale = _bodyScale;
		}
	}

	private void UpdateAnimation()
	{
		if (_currentAnim != null)
		{
			_currentAnimTime += Time.deltaTime * _currentAnim.playSpeed;
			_currentAnimTime %= 1f;
			float num = _currentAnim.squashAmount.Evaluate(_currentAnimTime);
			float z = _currentAnim.forwardOffset.Evaluate(_currentAnimTime);
			float x = _currentAnim.horizontalOffset.Evaluate(_currentAnimTime);
			float y = _currentAnim.verticalOffset.Evaluate(_currentAnimTime);
			_animRoot.localPosition = UnityEngine.Vector3.Scale(_bodyScale, new UnityEngine.Vector3(x, y, z));
			float num2 = 1f - num;
			num2 *= 0.5f;
			num2 += 1f;
			_animRoot.localScale = UnityEngine.Vector3.Scale(_bodyScale, new UnityEngine.Vector3(num2, num, num2));
		}
	}

	public void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
	{
	}

	public void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		isHeld = true;
		isHeldLeftHand = grabbingHand == EquipmentInteractor.instance.leftHand;
		if ((bool)grabbedHaptics)
		{
			CrittersManager.PlayHaptics(grabbedHaptics, grabbedHapticsStrength, isHeldLeftHand);
		}
		if ((bool)grabbedFX)
		{
			grabbedFX.SetActive(value: true);
		}
		EquipmentInteractor.instance.UpdateHandEquipment(this, isHeldLeftHand);
		base.transform.parent = grabbingHand.transform;
		isHeld = true;
		heldBy = grabbingHand;
		this.OnDataChange?.Invoke();
	}

	public bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (EquipmentInteractor.instance.rightHandHeldEquipment == this && releasingHand != EquipmentInteractor.instance.rightHand)
		{
			return false;
		}
		if (EquipmentInteractor.instance.leftHandHeldEquipment == this && releasingHand != EquipmentInteractor.instance.leftHand)
		{
			return false;
		}
		if ((bool)grabbedHaptics)
		{
			CrittersManager.StopHaptics(isHeldLeftHand);
		}
		if ((bool)grabbedFX)
		{
			grabbedFX.SetActive(value: false);
		}
		EquipmentInteractor.instance.UpdateHandEquipment(null, isHeldLeftHand);
		isHeld = false;
		isHeldLeftHand = false;
		OnReleased?.Invoke(this);
		this.OnDataChange?.Invoke();
		ResetToTransform();
		return true;
	}

	public void ResetToTransform()
	{
		base.transform.parent = _slot.transform;
		base.transform.localPosition = UnityEngine.Vector3.zero;
		base.transform.localRotation = quaternion.identity;
	}

	public void DropItemCleanup()
	{
	}

	public void OnEnable()
	{
		EyeScannerMono.Register(this);
	}

	public void OnDisable()
	{
		EyeScannerMono.Unregister(this);
	}

	private IList<KeyValueStringPair> BuildEyeScannerData()
	{
		eyeScanData[0] = new KeyValueStringPair("Name", _critterConfiguration.critterName);
		eyeScanData[1] = new KeyValueStringPair("Type", _critterConfiguration.animalType.ToString());
		eyeScanData[2] = new KeyValueStringPair("Temperament", _critterConfiguration.behaviour.temperament);
		eyeScanData[3] = new KeyValueStringPair("Habitat", _critterConfiguration.biome.GetHabitatDescription());
		eyeScanData[4] = new KeyValueStringPair("Size", visuals.Appearance.size.ToString("0.00"));
		eyeScanData[5] = new KeyValueStringPair("State", GetCurrentStateName());
		return eyeScanData;
	}

	private string GetCurrentStateName()
	{
		if (!isHeld)
		{
			return "Content";
		}
		return "Happy";
	}
}
public class MenagerieDepositBox : MonoBehaviour
{
	public Action<MenagerieCritter> OnCritterInserted;

	public void OnTriggerEnter(Collider other)
	{
		MenagerieCritter component = other.transform.parent.parent.GetComponent<MenagerieCritter>();
		if (component.IsNotNull())
		{
			component.OnReleased = (Action<MenagerieCritter>)Delegate.Combine(component.OnReleased, OnCritterInserted);
		}
	}

	public void OnTriggerExit(Collider other)
	{
		MenagerieCritter component = other.transform.parent.GetComponent<MenagerieCritter>();
		if (component.IsNotNull())
		{
			component.OnReleased = (Action<MenagerieCritter>)Delegate.Remove(component.OnReleased, OnCritterInserted);
		}
	}
}
