public class PeriodicFoodTopUpper : MonoBehaviour
{
	private CrittersFood food;

	private float timeFoodEmpty;

	private bool waitingToRefill;

	public float waitToRefill = 10f;

	public GameObject foodObject;

	private void Awake()
	{
		food = GetComponentInParent<CrittersFood>();
	}

	private void Update()
	{
		if (CrittersManager.instance.LocalAuthority())
		{
			if (!waitingToRefill && food.currentFood == 0f)
			{
				waitingToRefill = true;
				timeFoodEmpty = Time.time;
			}
			if (waitingToRefill && Time.time > timeFoodEmpty + waitToRefill)
			{
				waitingToRefill = false;
				food.Initialize();
			}
		}
	}
}
public class PeriodicNoiseGenerator : MonoBehaviour
{
	public float sleepDuration;

	public float randomDuration;

	public float lastTime;

	private CrittersLoudNoise noiseActor;

	public Material transparent;

	public Material solid;

	private MeshRenderer mR;

	private void Awake()
	{
		noiseActor = GetComponentInParent<CrittersLoudNoise>();
		lastTime = Time.time;
		mR = GetComponentInChildren<MeshRenderer>();
	}

	private void Update()
	{
		if (CrittersManager.instance.LocalAuthority())
		{
			if (Time.time > lastTime + sleepDuration)
			{
				lastTime = Time.time + randomDuration * UnityEngine.Random.value;
				noiseActor.SetTimeEnabled();
				noiseActor.soundEnabled = true;
				mR.sharedMaterial = solid;
			}
			if (!noiseActor.soundEnabled && mR.sharedMaterial != transparent)
			{
				mR.sharedMaterial = transparent;
			}
		}
	}
}
