public class WeightedList<T>
{
	private List<T> items = new List<T>();

	private List<float> weights = new List<float>();

	private List<float> cumulativeWeights = new List<float>();

	private float totalWeight;

	public int Count => items.Count;

	public List<T> Items => items;

	public (T Item, float Weight) this[int index]
	{
		get
		{
			if (index < 0 || index >= items.Count)
			{
				throw new IndexOutOfRangeException();
			}
			return (Item: items[index], Weight: weights[index]);
		}
	}

	public void Add(T item, float weight)
	{
		if (weight <= 0f)
		{
			throw new ArgumentException("Weight must be greater than zero.");
		}
		totalWeight += weight;
		items.Add(item);
		weights.Add(weight);
		cumulativeWeights.Add(totalWeight);
	}

	public T GetRandomItem()
	{
		return items[GetRandomIndex()];
	}

	public int GetRandomIndex()
	{
		if (items.Count == 0)
		{
			throw new InvalidOperationException("The list is empty.");
		}
		float item = UnityEngine.Random.value * totalWeight;
		int num = cumulativeWeights.BinarySearch(item);
		if (num < 0)
		{
			num = ~num;
		}
		return num;
	}

	public bool Remove(T item)
	{
		int num = items.IndexOf(item);
		if (num == -1)
		{
			return false;
		}
		RemoveAt(num);
		return true;
	}

	public void RemoveAt(int index)
	{
		if (index < 0 || index >= items.Count)
		{
			throw new ArgumentOutOfRangeException("index");
		}
		totalWeight -= weights[index];
		items.RemoveAt(index);
		weights.RemoveAt(index);
		RecalculateCumulativeWeights();
	}

	private void RecalculateCumulativeWeights()
	{
		cumulativeWeights.Clear();
		float num = 0f;
		foreach (float weight in weights)
		{
			num += weight;
			cumulativeWeights.Add(num);
		}
		totalWeight = num;
	}

	public void Clear()
	{
		items.Clear();
		weights.Clear();
		cumulativeWeights.Clear();
		totalWeight = 0f;
	}
}
public class CyclicalActivator : MonoBehaviour, IGorillaSliceableSimple
{
	[Serializable]
	private class CyclicalActivatorObjectScheduleNode
	{
		public UnityEngine.Vector2 secondsActiveRange;
	}

	[Serializable]
	private class CyclicalActivatorObjectSchedule
	{
		[Range(10f, 3599f)]
		public int totalSeconds = 60;

		public CyclicalActivatorObjectScheduleNode[] schedule;

		public bool CheckTime(float nowSeconds)
		{
			nowSeconds %= (float)totalSeconds;
			for (int i = 0; i < schedule.Length; i++)
			{
				if (schedule[i].secondsActiveRange.x <= nowSeconds && schedule[i].secondsActiveRange.y > nowSeconds)
				{
					return true;
				}
			}
			return false;
		}
	}

	[Serializable]
	private class CyclicalActivatorObject
	{
		public GameObject gameObject;

		public CyclicalActivatorObjectSchedule schedule;
	}

	[SerializeField]
	private CyclicalActivatorObject[] objects;

	private void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	private void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	void IGorillaSliceableSimple.SliceUpdate()
	{
		if (!(GorillaComputer.instance == null) && GorillaComputer.instance.GetServerTime().Year >= 2000)
		{
			DateTime serverTime = GorillaComputer.instance.GetServerTime();
			float nowSeconds = (float)(serverTime.Minute * 60) + ((float)serverTime.Second + (float)serverTime.Millisecond * 0.001f);
			for (int i = 0; i < objects.Length; i++)
			{
				objects[i].gameObject.SetActive(objects[i].schedule.CheckTime(nowSeconds));
			}
		}
	}
}
public static class DebugExtension
{
	public static void DebugPoint(UnityEngine.Vector3 position, Color color, float scale = 1f, float duration = 0f, bool depthTest = true)
	{
		color = ((color == default(Color)) ? Color.white : color);
		UnityEngine.Debug.DrawRay(position + UnityEngine.Vector3.up * (scale * 0.5f), -UnityEngine.Vector3.up * scale, color, duration, depthTest);
		UnityEngine.Debug.DrawRay(position + UnityEngine.Vector3.right * (scale * 0.5f), -UnityEngine.Vector3.right * scale, color, duration, depthTest);
		UnityEngine.Debug.DrawRay(position + UnityEngine.Vector3.forward * (scale * 0.5f), -UnityEngine.Vector3.forward * scale, color, duration, depthTest);
	}

	public static void DebugPoint(UnityEngine.Vector3 position, float scale = 1f, float duration = 0f, bool depthTest = true)
	{
