	public static void DebugCircle(UnityEngine.Vector3 position, UnityEngine.Vector3 up, Color color, float radius = 1f, float duration = 0f, bool depthTest = true)
	{
		UnityEngine.Vector3 vector = up.normalized * radius;
		UnityEngine.Vector3 rhs = UnityEngine.Vector3.Slerp(vector, -vector, 0.5f);
		UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Cross(vector, rhs).normalized * radius;
		UnityEngine.Matrix4x4 matrix4x = new UnityEngine.Matrix4x4
		{
			[0] = vector2.x,
			[1] = vector2.y,
			[2] = vector2.z,
			[4] = vector.x,
			[5] = vector.y,
			[6] = vector.z,
			[8] = rhs.x,
			[9] = rhs.y,
			[10] = rhs.z
		};
		UnityEngine.Vector3 start = position + matrix4x.MultiplyPoint3x4(new UnityEngine.Vector3(Mathf.Cos(0f), 0f, Mathf.Sin(0f)));
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.zero;
		color = ((color == default(Color)) ? Color.white : color);
		for (int i = 0; i < 91; i++)
		{
			vector3.x = Mathf.Cos((float)(i * 4) * (MathF.PI / 180f));
			vector3.z = Mathf.Sin((float)(i * 4) * (MathF.PI / 180f));
			vector3.y = 0f;
			vector3 = position + matrix4x.MultiplyPoint3x4(vector3);
			UnityEngine.Debug.DrawLine(start, vector3, color, duration, depthTest);
			start = vector3;
		}
	}

	public static void DebugCircle(UnityEngine.Vector3 position, Color color, float radius = 1f, float duration = 0f, bool depthTest = true)
	{
		DebugCircle(position, UnityEngine.Vector3.up, color, radius, duration, depthTest);
	}

