		{
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(position.x, position.y + radius * Mathf.Sin(num * (float)i * (MathF.PI / 180f)), position.z + radius * Mathf.Cos(num * (float)i * (MathF.PI / 180f)));
			UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(position.x + radius * Mathf.Cos(num * (float)i * (MathF.PI / 180f)), position.y, position.z + radius * Mathf.Sin(num * (float)i * (MathF.PI / 180f)));
			UnityEngine.Vector3 vector3 = new UnityEngine.Vector3(position.x + radius * Mathf.Cos(num * (float)i * (MathF.PI / 180f)), position.y + radius * Mathf.Sin(num * (float)i * (MathF.PI / 180f)), position.z);
