	public static void DebugCone(UnityEngine.Vector3 position, UnityEngine.Vector3 direction, Color color, float angle = 45f, float duration = 0f, bool depthTest = true)
	{
		float magnitude = direction.magnitude;
		UnityEngine.Vector3 vector = direction;
		UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Slerp(vector, -vector, 0.5f);
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(vector, vector2).normalized * magnitude;
		direction = direction.normalized;
		UnityEngine.Vector3 direction2 = UnityEngine.Vector3.Slerp(vector, vector2, angle / 90f);
		UnityEngine.Plane plane = new UnityEngine.Plane(-direction, position + vector);
		Ray ray = new Ray(position, direction2);
		plane.Raycast(ray, out var enter);
		UnityEngine.Debug.DrawRay(position, direction2.normalized * enter, color);
		UnityEngine.Debug.DrawRay(position, UnityEngine.Vector3.Slerp(vector, -vector2, angle / 90f).normalized * enter, color, duration, depthTest);
		UnityEngine.Debug.DrawRay(position, UnityEngine.Vector3.Slerp(vector, vector3, angle / 90f).normalized * enter, color, duration, depthTest);
		UnityEngine.Debug.DrawRay(position, UnityEngine.Vector3.Slerp(vector, -vector3, angle / 90f).normalized * enter, color, duration, depthTest);
		DebugCircle(position + vector, direction, color, (vector - direction2.normalized * enter).magnitude, duration, depthTest);
		DebugCircle(position + vector * 0.5f, direction, color, (vector * 0.5f - direction2.normalized * (enter * 0.5f)).magnitude, duration, depthTest);
	}

