	public static void DebugCapsule(UnityEngine.Vector3 start, UnityEngine.Vector3 end, Color color, float radius = 1f, float duration = 0f, bool depthTest = true)
	{
		UnityEngine.Vector3 vector = (end - start).normalized * radius;
		UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Slerp(vector, -vector, 0.5f);
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(vector, vector2).normalized * radius;
		float magnitude = (start - end).magnitude;
		float num = Mathf.Max(0f, magnitude * 0.5f - radius);
		UnityEngine.Vector3 vector4 = (end + start) * 0.5f;
		start = vector4 + (start - vector4).normalized * num;
		end = vector4 + (end - vector4).normalized * num;
		DebugCircle(start, vector, color, radius, duration, depthTest);
		DebugCircle(end, -vector, color, radius, duration, depthTest);
		UnityEngine.Debug.DrawLine(start + vector3, end + vector3, color, duration, depthTest);
		UnityEngine.Debug.DrawLine(start - vector3, end - vector3, color, duration, depthTest);
		UnityEngine.Debug.DrawLine(start + vector2, end + vector2, color, duration, depthTest);
		UnityEngine.Debug.DrawLine(start - vector2, end - vector2, color, duration, depthTest);
		for (int i = 1; i < 26; i++)
		{
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(vector3, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(vector3, -vector, (float)(i - 1) / 25f) + start, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(-vector3, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(-vector3, -vector, (float)(i - 1) / 25f) + start, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(vector2, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(vector2, -vector, (float)(i - 1) / 25f) + start, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(-vector2, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(-vector2, -vector, (float)(i - 1) / 25f) + start, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(vector3, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(vector3, vector, (float)(i - 1) / 25f) + end, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(-vector3, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(-vector3, vector, (float)(i - 1) / 25f) + end, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(vector2, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(vector2, vector, (float)(i - 1) / 25f) + end, color, duration, depthTest);
			UnityEngine.Debug.DrawLine(UnityEngine.Vector3.Slerp(-vector2, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(-vector2, vector, (float)(i - 1) / 25f) + end, color, duration, depthTest);
		}
	}

