		Gizmos.DrawLine(vector, vector2);
		Gizmos.DrawLine(vector2, vector3);
		Gizmos.DrawLine(vector3, vector4);
		Gizmos.DrawLine(vector4, vector);
		Gizmos.DrawLine(vector5, vector6);
		Gizmos.DrawLine(vector6, vector7);
		Gizmos.DrawLine(vector7, vector8);
		Gizmos.DrawLine(vector8, vector5);
		Gizmos.DrawLine(vector, vector5);
		Gizmos.DrawLine(vector2, vector6);
		Gizmos.DrawLine(vector3, vector7);
		Gizmos.DrawLine(vector4, vector8);
		Gizmos.color = color2;
	}

	public static void DrawLocalCube(UnityEngine.Matrix4x4 space, UnityEngine.Vector3 size, UnityEngine.Vector3 center = default(UnityEngine.Vector3))
	{
		DrawLocalCube(space, size, Color.white, center);
	}

	public static void DrawCircle(UnityEngine.Vector3 position, UnityEngine.Vector3 up, Color color, float radius = 1f)
	{
		up = ((up == UnityEngine.Vector3.zero) ? UnityEngine.Vector3.up : up).normalized * radius;
		UnityEngine.Vector3 rhs = UnityEngine.Vector3.Slerp(up, -up, 0.5f);
		UnityEngine.Vector3 vector = UnityEngine.Vector3.Cross(up, rhs).normalized * radius;
		UnityEngine.Matrix4x4 matrix4x = new UnityEngine.Matrix4x4
		{
			[0] = vector.x,
			[1] = vector.y,
			[2] = vector.z,
			[4] = up.x,
			[5] = up.y,
			[6] = up.z,
			[8] = rhs.x,
			[9] = rhs.y,
			[10] = rhs.z
		};
		UnityEngine.Vector3 vector2 = position + matrix4x.MultiplyPoint3x4(new UnityEngine.Vector3(Mathf.Cos(0f), 0f, Mathf.Sin(0f)));
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.zero;
		Color color2 = Gizmos.color;
		Gizmos.color = ((color == default(Color)) ? Color.white : color);
		for (int i = 0; i < 91; i++)
		{
			vector3.x = Mathf.Cos((float)(i * 4) * (MathF.PI / 180f));
			vector3.z = Mathf.Sin((float)(i * 4) * (MathF.PI / 180f));
			vector3.y = 0f;
			vector3 = position + matrix4x.MultiplyPoint3x4(vector3);
			Gizmos.DrawLine(vector2, vector3);
			vector2 = vector3;
		}
		Gizmos.color = color2;
	}

	public static void DrawCircle(UnityEngine.Vector3 position, Color color, float radius = 1f)
	{
		DrawCircle(position, UnityEngine.Vector3.up, color, radius);
	}

	public static void DrawCircle(UnityEngine.Vector3 position, UnityEngine.Vector3 up, float radius = 1f)
	{
		DrawCircle(position, position, Color.white, radius);
	}

	public static void DrawCircle(UnityEngine.Vector3 position, float radius = 1f)
	{
		DrawCircle(position, UnityEngine.Vector3.up, Color.white, radius);
	}

	public static void DrawCylinder(UnityEngine.Vector3 start, UnityEngine.Vector3 end, Color color, float radius = 1f)
	{
		UnityEngine.Vector3 vector = (end - start).normalized * radius;
		UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Slerp(vector, -vector, 0.5f);
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(vector, vector2).normalized * radius;
		DrawCircle(start, vector, color, radius);
		DrawCircle(end, -vector, color, radius);
		DrawCircle((start + end) * 0.5f, vector, color, radius);
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		Gizmos.DrawLine(start + vector3, end + vector3);
		Gizmos.DrawLine(start - vector3, end - vector3);
		Gizmos.DrawLine(start + vector2, end + vector2);
		Gizmos.DrawLine(start - vector2, end - vector2);
		Gizmos.DrawLine(start - vector3, start + vector3);
		Gizmos.DrawLine(start - vector2, start + vector2);
		Gizmos.DrawLine(end - vector3, end + vector3);
		Gizmos.DrawLine(end - vector2, end + vector2);
		Gizmos.color = color2;
	}

	public static void DrawCylinder(UnityEngine.Vector3 start, UnityEngine.Vector3 end, float radius = 1f)
	{
		DrawCylinder(start, end, Color.white, radius);
	}

	public static void DrawCone(UnityEngine.Vector3 position, UnityEngine.Vector3 direction, Color color, float angle = 45f)
	{
		float magnitude = direction.magnitude;
		UnityEngine.Vector3 vector = direction;
		UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Slerp(vector, -vector, 0.5f);
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(vector, vector2).normalized * magnitude;
		direction = direction.normalized;
		UnityEngine.Vector3 direction2 = UnityEngine.Vector3.Slerp(vector, vector2, angle / 90f);
		UnityEngine.Plane plane = new UnityEngine.Plane(-direction, position + vector);
		Ray ray = new Ray(position, direction2);
		plane.Raycast(ray, out var enter);
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		Gizmos.DrawRay(position, direction2.normalized * enter);
		Gizmos.DrawRay(position, UnityEngine.Vector3.Slerp(vector, -vector2, angle / 90f).normalized * enter);
		Gizmos.DrawRay(position, UnityEngine.Vector3.Slerp(vector, vector3, angle / 90f).normalized * enter);
		Gizmos.DrawRay(position, UnityEngine.Vector3.Slerp(vector, -vector3, angle / 90f).normalized * enter);
		DrawCircle(position + vector, direction, color, (vector - direction2.normalized * enter).magnitude);
		DrawCircle(position + vector * 0.5f, direction, color, (vector * 0.5f - direction2.normalized * (enter * 0.5f)).magnitude);
		Gizmos.color = color2;
	}

	public static void DrawCone(UnityEngine.Vector3 position, UnityEngine.Vector3 direction, float angle = 45f)
	{
		DrawCone(position, direction, Color.white, angle);
	}

	public static void DrawCone(UnityEngine.Vector3 position, Color color, float angle = 45f)
	{
		DrawCone(position, UnityEngine.Vector3.up, color, angle);
	}

	public static void DrawCone(UnityEngine.Vector3 position, float angle = 45f)
	{
		DrawCone(position, UnityEngine.Vector3.up, Color.white, angle);
	}

	public static void DrawArrow(UnityEngine.Vector3 position, UnityEngine.Vector3 direction, Color color)
	{
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		Gizmos.DrawRay(position, direction);
		DrawCone(position + direction, -direction * 0.333f, color, 15f);
		Gizmos.color = color2;
	}

	public static void DrawArrow(UnityEngine.Vector3 position, UnityEngine.Vector3 direction)
	{
		DrawArrow(position, direction, Color.white);
	}

	public static void DrawCapsule(UnityEngine.Vector3 start, UnityEngine.Vector3 end, Color color, float radius = 1f)
	{
		UnityEngine.Vector3 vector = (end - start).normalized * radius;
		UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Slerp(vector, -vector, 0.5f);
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(vector, vector2).normalized * radius;
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		float magnitude = (start - end).magnitude;
		float num = Mathf.Max(0f, magnitude * 0.5f - radius);
		UnityEngine.Vector3 vector4 = (end + start) * 0.5f;
		start = vector4 + (start - vector4).normalized * num;
		end = vector4 + (end - vector4).normalized * num;
		DrawCircle(start, vector, color, radius);
		DrawCircle(end, -vector, color, radius);
		Gizmos.DrawLine(start + vector3, end + vector3);
		Gizmos.DrawLine(start - vector3, end - vector3);
		Gizmos.DrawLine(start + vector2, end + vector2);
		Gizmos.DrawLine(start - vector2, end - vector2);
		for (int i = 1; i < 26; i++)
		{
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(vector3, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(vector3, -vector, (float)(i - 1) / 25f) + start);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(-vector3, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(-vector3, -vector, (float)(i - 1) / 25f) + start);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(vector2, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(vector2, -vector, (float)(i - 1) / 25f) + start);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(-vector2, -vector, (float)i / 25f) + start, UnityEngine.Vector3.Slerp(-vector2, -vector, (float)(i - 1) / 25f) + start);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(vector3, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(vector3, vector, (float)(i - 1) / 25f) + end);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(-vector3, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(-vector3, vector, (float)(i - 1) / 25f) + end);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(vector2, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(vector2, vector, (float)(i - 1) / 25f) + end);
			Gizmos.DrawLine(UnityEngine.Vector3.Slerp(-vector2, vector, (float)i / 25f) + end, UnityEngine.Vector3.Slerp(-vector2, vector, (float)(i - 1) / 25f) + end);
		}
		Gizmos.color = color2;
	}

	public static void DrawCapsule(UnityEngine.Vector3 start, UnityEngine.Vector3 end, float radius = 1f)
	{
		DrawCapsule(start, end, Color.white, radius);
	}

	public static string MethodsOfObject(object obj, bool includeInfo = false)
	{
		string text = "";
		MethodInfo[] methods = obj.GetType().GetMethods();
		for (int i = 0; i < methods.Length; i++)
		{
			text = ((!includeInfo) ? (text + methods[i].Name + "\n") : (text + methods[i]?.ToString() + "\n"));
		}
		return text;
	}

	public static string MethodsOfType(Type type, bool includeInfo = false)
	{
		string text = "";
		MethodInfo[] methods = type.GetMethods();
		for (int i = 0; i < methods.Length; i++)
		{
			text = ((!includeInfo) ? (text + methods[i].Name + "\n") : (text + methods[i]?.ToString() + "\n"));
		}
		return text;
	}
}
