public class GenericTriggerReactor : MonoBehaviour, IBuildValidation
{
	[SerializeField]
	private string ComponentName = string.Empty;

	[Space]
	[SerializeField]
	private UnityEngine.Vector2 speedRangeEnter;

	[SerializeField]
	private UnityEngine.Vector2 speedRangeExit;

	[Space]
	[SerializeField]
	private Transform idealMotion;

	[SerializeField]
	private UnityEngine.Vector2 idealMotionPlayRangeEnter;

	[SerializeField]
	private UnityEngine.Vector2 idealMotionPlayRangeExit;

	[Space]
	[SerializeField]
	private UnityEvent GTOnTriggerEnter;

	[SerializeField]
	private UnityEvent GTOnTriggerExit;

	private Type componentType;

	private GorillaVelocityEstimator gorillaVelocityEstimator;

	bool IBuildValidation.BuildValidationCheck()
	{
		if (ComponentName.Length == 0)
		{
			return true;
		}
		if (Type.GetType(ComponentName) == null)
		{
			UnityEngine.Debug.LogError("GenericTriggerReactor :: ComponentName must specify a valid Component or be empty.");
			return false;
		}
		return true;
	}

	private void Awake()
	{
		componentType = Type.GetType(ComponentName);
		TryGetComponent<GorillaVelocityEstimator>(out gorillaVelocityEstimator);
	}

	private void OnTriggerEnter(Collider other)
	{
		OnTriggerTest(other, speedRangeEnter, GTOnTriggerEnter, idealMotionPlayRangeEnter);
	}

	private void OnTriggerExit(Collider other)
	{
		OnTriggerTest(other, speedRangeExit, GTOnTriggerExit, idealMotionPlayRangeExit);
	}

	private void OnTriggerTest(Collider other, UnityEngine.Vector2 speedRange, UnityEvent unityEvent, UnityEngine.Vector2 idealMotionPlay)
	{
		if (unityEvent == null || (!(componentType == null) && !other.TryGetComponent(componentType, out var _)))
		{
			return;
		}
		if (gorillaVelocityEstimator != null)
		{
			float magnitude = gorillaVelocityEstimator.linearVelocity.magnitude;
			if (magnitude < speedRange.x || magnitude > speedRange.y)
			{
				return;
			}
			if (idealMotion != null)
			{
				float num = UnityEngine.Vector3.Dot(gorillaVelocityEstimator.linearVelocity.normalized, idealMotion.forward);
				if (num < idealMotionPlay.x || num > idealMotionPlay.y)
				{
					return;
				}
			}
		}
		unityEvent.Invoke();
	}
}
public class DevWatch : MonoBehaviour
{
	public DevWatchButton SearchButton;

	public GameObject Panel1;

	public GameObject Panel2;

	public DevWatchSelectableItem SelectableItemPrefab;

	public List<DevWatchSelectableItem> Items;

	public Transform RayCastStartPos;

	public Transform RayCastDirection;

	public Transform ItemsFoundContainer;

	public Button TakeOwnershipButton;

	public Button DestroyObjectButton;

	public List<NetworkObject> FoundNetworkObjects = new List<NetworkObject>();

	public TextMeshProUGUI SelectedItemName;

	public DevWatchSelectableItem SelectedItem;

	private void Awake()
	{
		SearchButton.SearchEvent.AddListener(SearchItems);
		TakeOwnershipButton.onClick.AddListener(TakeOwneshipOfItem);
		DestroyObjectButton.onClick.AddListener(TryDestroyItem);
	}

	public void SearchItems()
	{
		FoundNetworkObjects.Clear();
		RaycastHit[] array = Physics.SphereCastAll(new Ray(RayCastStartPos.position, RayCastDirection.position - RayCastStartPos.position), 0.3f, 100f);
		if (array.Length == 0)
		{
			return;
		}
		RaycastHit[] array2 = array;
		foreach (RaycastHit raycastHit in array2)
		{
			if (raycastHit.collider.gameObject.TryGetComponent<NetworkObject>(out var component))
			{
				FoundNetworkObjects.Add(component);
			}
		}
	}

	public void Cleanup()
	{
		FoundNetworkObjects.Clear();
		if (Items.Count > 0)
		{
			for (int num = Items.Count - 1; num >= 0; num--)
			{
				UnityEngine.Object.Destroy(Items[num]);
			}
		}
		Items.Clear();
		Panel1.SetActive(value: true);
		Panel2.SetActive(value: false);
	}

	public void ItemSelected(DevWatchSelectableItem item)
	{
		Panel1.SetActive(value: false);
		Panel2.SetActive(value: true);
		SelectedItem = item;
		SelectedItemName.text = item.ItemName.text;
	}

	public void TryDestroyItem()
	{
	}

	public void TakeOwneshipOfItem()
	{
	}
}
