public class GorillaPressableDelayButton : GorillaPressableButton, IGorillaSliceableSimple
{
	private Collider touching;

	private float pressStartTime;

	private float progress;

	[SerializeField]
	[Range(0.01f, 5f)]
	public float delayTime = 1f;

	[SerializeField]
	private Transform fillBar;

	private UnityEngine.Vector3 fillbarStartingScale;

	private UnityEngine.Vector3 fillBarScale;

	public event Action onPressBegin;

	public event Action onPressAbort;

	private void Awake()
	{
		if (!(fillBar == null))
		{
			fillBarScale = (fillbarStartingScale = fillBar.localScale);
			UpdateFillBar();
		}
	}

	private new void OnTriggerEnter(Collider collider)
	{
		if (base.enabled && touchTime + debounceTime < Time.time && !touching && !(collider.GetComponentInParent<GorillaTriggerColliderHandIndicator>() == null))
		{
			touching = collider;
			pressStartTime = Time.unscaledTime;
			progress = 0f;
			UpdateFillBar();
			this.onPressBegin?.Invoke();
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (!(other != touching))
		{
			touching = null;
			progress = 0f;
			UpdateFillBar();
			this.onPressAbort?.Invoke();
		}
	}

	public new void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public new void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void SliceUpdate()
	{
		if (!(touching == null))
		{
			float num = Time.unscaledTime - pressStartTime;
			progress = ((delayTime > 0f) ? Mathf.Clamp01(num / delayTime) : ((num > 0f) ? 1f : 0f));
			if (num > delayTime)
			{
				base.OnTriggerEnter(touching);
				touching = null;
				progress = 0f;
			}
			UpdateFillBar();
		}
	}

	public void SetFillBar(Transform newFillBar)
	{
		fillBar = newFillBar;
		if (!(fillBar == null))
		{
			fillBarScale = (fillbarStartingScale = fillBar.localScale);
			UpdateFillBar();
		}
	}

	private void UpdateFillBar()
	{
		if (!(fillBar == null))
		{
			fillBarScale.x = fillbarStartingScale.x * progress;
			fillBar.localScale = fillBarScale;
		}
	}
}
public class EyeScannableMono : MonoBehaviour, IEyeScannable
{
	[SerializeField]
	private KeyValuePairSet data;

	private Bounds _bounds;

	private UnityEngine.Vector3 _initialPosition;

	int IEyeScannable.scannableId => GetInstanceID();

	UnityEngine.Vector3 IEyeScannable.Position => base.transform.position - _initialPosition + _bounds.center;

	Bounds IEyeScannable.Bounds => _bounds;

	IList<KeyValueStringPair> IEyeScannable.Entries => data.Entries;

	public event Action OnDataChange;

	private void Awake()
	{
		RecalculateBounds();
	}

	public void OnEnable()
	{
		RecalculateBoundsLater();
		EyeScannerMono.Register(this);
	}

	public void OnDisable()
	{
		EyeScannerMono.Unregister(this);
	}

	private async void RecalculateBoundsLater()
	{
		await Task.Delay(100);
		RecalculateBounds();
	}

	private void RecalculateBounds()
	{
		_initialPosition = base.transform.position;
		Collider[] componentsInChildren = GetComponentsInChildren<Collider>();
		_bounds = default(Bounds);
		if (componentsInChildren.Length == 0)
		{
			_bounds.center = base.transform.position;
			_bounds.Expand(1f);
			return;
		}
		_bounds = componentsInChildren[0].bounds;
		for (int i = 1; i < componentsInChildren.Length; i++)
		{
			_bounds.Encapsulate(componentsInChildren[i].bounds);
		}
	}
}
