public class CosmeticCritterShadeFleeing : CosmeticCritter
{
	[Serializable]
	private class ModelSwap
	{
		public float relativeProbability;

		public GameObject gameObject;
	}

	[Tooltip("Randomly selects one of these models when spawned, accounting for relative probabilities. For example, if one model has a probability of 1 and another a probability of 2, the second is twice as likely to be picked (and thus will be picked 67% of the time).")]
	[SerializeField]
	private ModelSwap[] modelSwaps;

	[Space]
	[Tooltip("Despawn the Shade after it has fled (fleed?) this many meters.")]
	[SerializeField]
	private float fleeDistanceToDespawn = 10f;

	[Tooltip("Flee away from the spotter at this many meters per second.")]
	[SerializeField]
	private float fleeSpeed;

	[Tooltip("The maximum strength the shade can move bob around in the horizontal and vertical axes, with final value chosen randomly.")]
	[SerializeField]
	private UnityEngine.Vector2 fleeBobMagnitudeXYMax;

	[Tooltip("The maximum frequency the shade can move bob around in the horizontal and vertical axes, with final value chosen randomly.")]
	[SerializeField]
	private UnityEngine.Vector2 fleeBobFrequencyXYMax;

	[SerializeField]
	private Animator animator;

	[SerializeField]
	private ParticleSystem spawnFX;

	[SerializeField]
	private AudioSource spawnAudioSource;

	[SerializeField]
	private AudioClip[] spawnAudioClips;

	[HideInInspector]
	public UnityEngine.Vector3 pullVector;

	private UnityEngine.Vector3 origin;

	private UnityEngine.Vector3 fleeForward;

	private UnityEngine.Vector3 fleeRight;

	private UnityEngine.Vector3 fleeUp = UnityEngine.Vector3.up;

	private UnityEngine.Vector2 fleeBobFrequencyXY;

	private UnityEngine.Vector2 fleeBobMagnitudeXY;

	private UnityEngine.Vector3 trailingPosition;

	private float closestCatcherDistance;

	private int animatorProperty = Animator.StringToHash("Distance");

	public override void OnSpawn()
	{
		spawnFX.Play();
		spawnAudioSource.clip = spawnAudioClips.GetRandomItem();
		spawnAudioSource.GTPlay();
		pullVector = UnityEngine.Vector3.zero;
	}

	public void SetFleePosition(UnityEngine.Vector3 position, UnityEngine.Vector3 fleeFrom)
	{
		origin = position;
		UnityEngine.Vector3 vector = position - fleeFrom;
		fleeForward = vector.normalized;
		fleeRight = UnityEngine.Vector3.Cross(fleeForward, UnityEngine.Vector3.up);
		fleeUp = UnityEngine.Vector3.Cross(fleeForward, fleeRight);
		trailingPosition = position + vector.normalized * 3f;
	}

	public override void SetRandomVariables()
	{
		float num = 0f;
		for (int i = 0; i < modelSwaps.Length; i++)
		{
			num += modelSwaps[i].relativeProbability;
			modelSwaps[i].gameObject.SetActive(value: false);
		}
		float num2 = UnityEngine.Random.value * num;
		for (int j = 0; j < modelSwaps.Length; j++)
		{
			if (num2 >= modelSwaps[j].relativeProbability)
			{
				num2 -= modelSwaps[j].relativeProbability;
				continue;
			}
			modelSwaps[j].gameObject.SetActive(value: true);
			break;
		}
		fleeBobFrequencyXY = new UnityEngine.Vector2(UnityEngine.Random.Range(-1f, 1f) * fleeBobFrequencyXYMax.x, UnityEngine.Random.Range(-1f, 1f) * fleeBobFrequencyXYMax.y);
		fleeBobMagnitudeXY = new UnityEngine.Vector2(UnityEngine.Random.Range(-1f, 1f) * fleeBobMagnitudeXYMax.x, UnityEngine.Random.Range(-1f, 1f) * fleeBobMagnitudeXYMax.y);
	}

	public override void Tick()
	{
		float num = (float)GetAliveTime();
		UnityEngine.Vector3 vector = origin + num * fleeForward + pullVector + Mathf.Sin(fleeBobFrequencyXY.x * num) * fleeBobMagnitudeXY.x * fleeRight + Mathf.Sin(fleeBobFrequencyXY.y * num) * fleeBobMagnitudeXY.y * fleeUp;
		UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation((vector - trailingPosition).normalized, UnityEngine.Vector3.up);
		trailingPosition = UnityEngine.Vector3.Lerp(trailingPosition, vector, 0.05f);
		base.transform.SetPositionAndRotation(vector, rotation);
		animator.SetFloat(animatorProperty, Mathf.Sin(num * 3f) * 0.5f + 0.5f);
	}
}
public class CosmeticCritterShadeHidden : CosmeticCritter
{
	[Space]
	[Tooltip("How quickly the Shade orbits around the point where it spawned (the spawner's position).")]
	[SerializeField]
	private float orbitDegreesPerSecond;

	[Tooltip("The strength of additional up-and-down motion while orbiting.")]
	[SerializeField]
	private float verticalBobMagnitude;

	[Tooltip("The frequency of additional up-and-down motion while orbiting.")]
	[SerializeField]
	private float verticalBobFrequency;

	private UnityEngine.Vector3 orbitCenter;

	private float initialAngle;

	private float orbitRadius;

	private float orbitDirection;

	public void SetCenterAndRadius(UnityEngine.Vector3 center, float radius)
	{
		orbitCenter = center;
		orbitRadius = radius;
	}

	public override void SetRandomVariables()
	{
		initialAngle = UnityEngine.Random.Range(0f, MathF.PI * 2f);
		orbitDirection = ((UnityEngine.Random.value > 0.5f) ? 1f : (-1f));
	}

	public override void Tick()
	{
		float num = (float)GetAliveTime();
		float f = initialAngle + orbitDegreesPerSecond * num * orbitDirection;
		float y = verticalBobMagnitude * Mathf.Sin(num * verticalBobFrequency);
		base.transform.position = orbitCenter + new UnityEngine.Vector3(orbitRadius * Mathf.Cos(f), y, orbitRadius * Mathf.Sin(f));
	}
}
public class ShadeJumpscare : MonoBehaviour
{
	[SerializeField]
	private Transform shadeTransform;

	[SerializeField]
	private float animationTime;

	[SerializeField]
	private float shadeRotationSpeed = 1f;

	[SerializeField]
	private AnimationCurve shadeHeightFunction;

	[SerializeField]
	private AnimationCurve shadeScaleFunction;

	[SerializeField]
	private AnimationCurve shadeYScaleMultFunction;

	[SerializeField]
	private AnimationCurve soundVolumeFunction;

	[SerializeField]
	private AudioClip[] audioClips;

	private AudioSource audioSource;

	private float startTime;

	private float startAngle;

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
	}

	private void OnEnable()
	{
		startTime = Time.time;
		startAngle = UnityEngine.Random.value * 360f;
		audioSource.clip = audioClips.GetRandomItem();
		audioSource.GTPlay();
	}

	private void Update()
	{
		float num = Time.time - startTime;
		float time = num / animationTime;
		shadeTransform.SetPositionAndRotation(base.transform.position + new UnityEngine.Vector3(0f, shadeHeightFunction.Evaluate(time), 0f), UnityEngine.Quaternion.Euler(0f, startAngle + num * shadeRotationSpeed, 0f));
		float num2 = shadeScaleFunction.Evaluate(time);
		shadeTransform.localScale = new UnityEngine.Vector3(num2, num2 * shadeYScaleMultFunction.Evaluate(time), num2);
		audioSource.volume = soundVolumeFunction.Evaluate(time);
	}
}
public class ShadeRevealer : TransferrableObject
{
	public enum State
	{
		OFF,
		SCANNING,
		TRACKING,
		LOCKED,
		PRIMED
	}

	[SerializeField]
	private AudioSource initialActivationSFX;

	[SerializeField]
	private AudioSource beamSFX;

	[SerializeField]
	private AudioSource catchSFX;

	[SerializeField]
