	[Space]
	[Tooltip("Enable these objects while the beam is in Scanning mode.")]
	[SerializeField]
	private GameObject[] enableWhenScanning;

	[Tooltip("Enable these objects while the beam is in Tracking mode.")]
	[SerializeField]
	private GameObject[] enableWhenTracking;

	[Tooltip("Enable these objects while the beam is in Locked mode.")]
	[SerializeField]
	private GameObject[] enableWhenLocked;

	[Tooltip("Enable these objects while ready to fire.")]
	[SerializeField]
	private GameObject[] enableWhenPrimed;

	[Space]
	[SerializeField]
	private UnityEvent onShadeLaunched;

	private bool isScanning;

	private State currentBeamState;

	private State pendingBeamState;

	private GameObject[] objectsToDisableWhenOff;

	protected override void Awake()
	{
		base.Awake();
		HashSet<GameObject> hashSet = new HashSet<GameObject>();
		for (int i = 0; i < enableWhenScanning.Length; i++)
		{
			hashSet.Add(enableWhenScanning[i]);
		}
		for (int j = 0; j < enableWhenTracking.Length; j++)
		{
			hashSet.Add(enableWhenTracking[j]);
		}
		for (int k = 0; k < enableWhenLocked.Length; k++)
		{
			hashSet.Add(enableWhenLocked[k]);
		}
		for (int l = 0; l < enableWhenPrimed.Length; l++)
		{
			hashSet.Add(enableWhenPrimed[l]);
		}
		objectsToDisableWhenOff = new GameObject[hashSet.Count];
		hashSet.CopyTo(objectsToDisableWhenOff);
	}

	private float GetDistanceToBeamRay(UnityEngine.Vector3 toPosition)
	{
		return UnityEngine.Vector3.Cross(beamForward.forward, toPosition).magnitude;
	}

	public State GetBeamStateForPosition(UnityEngine.Vector3 toPosition, float tolerance)
	{
		if (toPosition.magnitude <= beamLength + tolerance && UnityEngine.Vector3.Dot(toPosition.normalized, beamForward.forward) > 0f)
		{
			float num = GetDistanceToBeamRay(toPosition) - tolerance;
			if (num <= lockThreshold)
			{
				return State.LOCKED;
			}
			if (num <= trackThreshold)
			{
				return State.TRACKING;
			}
		}
		return State.SCANNING;
	}

	public State GetBeamStateForCritter(CosmeticCritter critter, float tolerance)
	{
		return GetBeamStateForPosition(critter.transform.position - beamForward.position, tolerance);
	}

	public bool CritterWithinBeamThreshold(CosmeticCritter critter, State criteria, float tolerance)
	{
		return GetBeamStateForCritter(critter, tolerance) >= criteria;
	}

	public void SetBestBeamState(State state)
	{
		if (state > pendingBeamState)
		{
			pendingBeamState = state;
		}
	}

	private void SetObjectsEnabledFromState(State state)
	{
		for (int i = 0; i < objectsToDisableWhenOff.Length; i++)
		{
			objectsToDisableWhenOff[i].SetActive(value: false);
		}
		GameObject[] array;
		switch (state)
		{
		default:
			return;
		case State.SCANNING:
			array = enableWhenScanning;
			break;
		case State.TRACKING:
			array = enableWhenTracking;
			break;
		case State.LOCKED:
			array = enableWhenLocked;
			break;
		case State.PRIMED:
			array = enableWhenPrimed;
			break;
		}
		for (int j = 0; j < array.Length; j++)
		{
			array[j].SetActive(value: true);
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		if (currentBeamState != pendingBeamState)
		{
			currentBeamState = pendingBeamState;
			SetObjectsEnabledFromState(currentBeamState);
		}
		beamSFX.pitch = 1f + shadeCatcher.GetActionTimeFrac() * 2f;
		if (isScanning)
		{
			pendingBeamState = State.SCANNING;
		}
	}

	public void StartScanning()
	{
		shadeCatcher.enabled = true;
		initialActivationSFX.GTPlay();
		beamSFX.GTPlay();
		isScanning = true;
		currentBeamState = State.OFF;
		pendingBeamState = State.SCANNING;
	}

	public void StopScanning()
	{
		if (currentBeamState == State.PRIMED)
		{
			onShadeLaunched?.Invoke();
		}
		shadeCatcher.enabled = false;
		initialActivationSFX.GTStop();
		beamSFX.GTStop();
		isScanning = false;
		currentBeamState = State.OFF;
		pendingBeamState = State.OFF;
		SetObjectsEnabledFromState(State.OFF);
	}

	public void ShadeCaught()
	{
		shadeCatcher.enabled = false;
		beamSFX.GTStop();
		catchSFX.GTPlay();
		catchFX.Play();
		isScanning = false;
		currentBeamState = State.OFF;
		pendingBeamState = State.PRIMED;
	}
}
public class SteeringWheelCosmetic : MonoBehaviour
{
	[SerializeField]
	private float cooldown = 1.5f;

	[SerializeField]
	private float dramaticTurnThreshold = 35f;

	[SerializeField]
	private UnityEvent onHornHit;

	[SerializeField]
	private UnityEvent onDramaticTurn;

	private float lastHornTime = -999f;

	private float lastZAngle;

	private void Start()
	{
	}

	public void TryHornHit()
	{
		if (Time.time > lastHornTime + cooldown)
		{
			lastHornTime = Time.time;
			onHornHit?.Invoke();
		}
	}

	private void Update()
	{
		float z = base.transform.localEulerAngles.z;
		if (Mathf.Abs(Mathf.DeltaAngle(lastZAngle, z)) >= dramaticTurnThreshold)
		{
			onDramaticTurn?.Invoke();
		}
		lastZAngle = z;
	}
}
public class GhostPal : MonoBehaviour
{
	[SerializeField]
	private float minDistanceFromPlayer = 1f;

	[SerializeField]
	private float orbitRadius = 1f;

	[SerializeField]
	private float orbitHeight = 1f;

	[SerializeField]
	private float orbitSpeed = 0.1f;

	[SerializeField]
	private float faceMovementDirectionStrength = 1f;

	[Space]
	[SerializeField]
	private float lookAtDotProductMin = 0.95f;

	[SerializeField]
	private AnimationCurve rotateTowardsPlayerFromLookTime;

	[SerializeField]
	private float minLookTimeToTrigger = 2f;

	[SerializeField]
	private AnimationCurve bounceOnTrigger;

	[SerializeField]
	private AudioSource triggerAudioSource;

	[SerializeField]
	private UnityEngine.Vector2 triggerAudioPitchMinMax = new UnityEngine.Vector2(0.9f, 1.1f);

	[SerializeField]
	private AudioClip[] triggerAudioClips;

	private VRRig rig;

	private Animator animator;

	private float lookAtTime;

	private bool hasTriggered;

	private Coroutine bounceCoroutine;

	private float bounceHeight;

	private UnityEngine.Vector3 trailingPosition;

	private int triggerAudioClipIndex;

	private int neutralAnimID = Animator.StringToHash("Neutral");

	private int friendlyAnimID = Animator.StringToHash("Friendly");

	private void Awake()
	{
		rig = GetComponentInParent<VRRig>();
		animator = GetComponentInChildren<Animator>();
		trailingPosition = base.transform.position;
		triggerAudioClipIndex = triggerAudioClips.GetRandomIndex();
	}

	private IEnumerator BounceOnTrigger()
	{
		float startTime = Time.time;
		while (Time.time - startTime < bounceOnTrigger[bounceOnTrigger.length - 1].time)
		{
			bounceHeight = bounceOnTrigger.Evaluate(Time.time - startTime);
			yield return null;
		}
		bounceHeight = 0f;
	}

	private void LateUpdate()
	{
		UnityEngine.Vector3 position = rig.bodyTransform.position;
		UnityEngine.Vector3 vector = base.transform.parent.position - position;
		float num = vector.y * 0.5f + orbitHeight;
		vector.y = 0f;
		float num2 = vector.magnitude + minDistanceFromPlayer;
		vector = vector.normalized * num2;
		vector.y = num + bounceHeight;
		double num3 = (double)orbitSpeed * (PhotonNetwork.InRoom ? ((PhotonNetwork.Time - (double)rig.OwningNetPlayer.UserId.GetStaticHash()) * (double)((rig.OwningNetPlayer.ActorNumber % 2 == 0) ? 1 : (-1))) : Time.timeAsDouble);
		UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(orbitRadius * (float)System.Math.Cos(num3), 0f, orbitRadius * (float)System.Math.Sin(num3));
		UnityEngine.Vector3 vector3 = position + vector + vector2;
		UnityEngine.Vector3 vector4 = vector3 - rig.head.rigTarget.position;
		if (UnityEngine.Vector3.Dot(rig.head.rigTarget.forward, vector4.normalized) >= lookAtDotProductMin)
		{
			lookAtTime = Mathf.Min(lookAtTime + Time.deltaTime, Mathf.Max(rotateTowardsPlayerFromLookTime[rotateTowardsPlayerFromLookTime.length - 1].time, minLookTimeToTrigger));
			if (lookAtTime >= minLookTimeToTrigger && !hasTriggered && bounceHeight == 0f)
			{
				animator.SetTrigger(friendlyAnimID);
				bounceCoroutine = StartCoroutine(BounceOnTrigger());
				triggerAudioSource.pitch = UnityEngine.Random.Range(triggerAudioPitchMinMax.x, triggerAudioPitchMinMax.y);
				triggerAudioSource.clip = triggerAudioClips[triggerAudioClipIndex];
				triggerAudioSource.GTPlay();
				triggerAudioClipIndex = (triggerAudioClipIndex + UnityEngine.Random.Range(0, triggerAudioClips.Length - 1)) % triggerAudioClips.Length;
				hasTriggered = true;
			}
		}
		else
		{
			lookAtTime = Mathf.Max(lookAtTime - Time.deltaTime, 0f);
			if (lookAtTime < minLookTimeToTrigger && hasTriggered && bounceHeight == 0f)
			{
				animator.SetTrigger(neutralAnimID);
				hasTriggered = false;
			}
		}
		if ((vector3 - trailingPosition).sqrMagnitude > 0.1f)
		{
			float t = 1f - Mathf.Exp((0f - faceMovementDirectionStrength) * Time.deltaTime);
			trailingPosition = UnityEngine.Vector3.Lerp(trailingPosition, vector3, t);
		}
		UnityEngine.Quaternion rotation = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.LookRotation(vector3 - trailingPosition, UnityEngine.Vector3.up), UnityEngine.Quaternion.LookRotation(-vector4, UnityEngine.Vector3.up), rotateTowardsPlayerFromLookTime.Evaluate(lookAtTime));
		base.transform.SetPositionAndRotation(vector3, rotation);
	}
}
public class GorillaEventAnimation : MonoBehaviour
{
	public Animation _animation;

	public float offsetTime;

	public int animationClipIndex;

	public AnimationClip[] clips;

	[NonSerialized]
	public int _clipIndex;

	private void Awake()
	{
		if (_animation == null)
		{
			_animation = GetComponentInChildren<Animation>();
		}
		_animation.playAutomatically = false;
		for (int i = 0; i < clips.Length; i++)
		{
			clips[i].legacy = true;
		}
	}

	private void OnDisable()
	{
		_animation.enabled = false;
	}

	public void PlayClipByIndex(int index, float startTime)
	{
		if (index >= 0 && index < clips.Length)
		{
			if (!_animation.enabled)
			{
				_animation.enabled = true;
			}
			AnimationClip animationClip = clips[index];
			if (_animation.GetClip(animationClip.name) == null)
			{
				_animation.AddClip(animationClip, animationClip.name);
			}
			_animation.Play(animationClip.name);
			_animation[animationClip.name].time = startTime;
			_clipIndex = index;
		}
	}
}
[RequireComponent(typeof(Animation))]
public class GorillaEventAnimationController : MonoBehaviour
{
	[Serializable]
	public struct AnimToGEAKeyframeData
	{
		public AnimationClip clip;

		public List<GEAKeyframeData> gEAKeyframeData;
	}

	[Serializable]
	public struct GEAKeyframeData
	{
		public GorillaEventAnimation gEA;

		public List<ControlledAnimationKeyframeData> keyframeData;
	}

	[Serializable]
	public struct ControlledAnimationKeyframeData(int _index, float _time, float _startOffset, bool _animEnabled)
	{
		public int animationClipIndex = _index;

		public float startTime = _time;

		public float startOffset = _startOffset;

		public bool animEnabled = _animEnabled;
	}

	public Animation controllingAnimation;

	public bool playAnimation;

	private float lateStart;

	public int animationClipIndex;

	public List<AnimationClip> clips;

	private AnimationClip currentClip;

	private Dictionary<AnimationClip, Dictionary<GorillaEventAnimation, List<ControlledAnimationKeyframeData>>> bakedAnimationData;

	[SerializeField]
	[HideInInspector]
	private List<AnimToGEAKeyframeData> bakedAnimKeyframeData;

	private void Awake()
	{
		bakedAnimationData = new Dictionary<AnimationClip, Dictionary<GorillaEventAnimation, List<ControlledAnimationKeyframeData>>>();
		for (int i = 0; i < bakedAnimKeyframeData.Count; i++)
		{
			AnimationClip clip = bakedAnimKeyframeData[i].clip;
			bakedAnimationData.Add(clip, new Dictionary<GorillaEventAnimation, List<ControlledAnimationKeyframeData>>());
			for (int j = 0; j < bakedAnimKeyframeData[i].gEAKeyframeData.Count; j++)
			{
				bakedAnimationData[clip].Add(bakedAnimKeyframeData[i].gEAKeyframeData[j].gEA, bakedAnimKeyframeData[i].gEAKeyframeData[j].keyframeData);
			}
		}
	}

	private void Update()
	{
		AnimationState animationState = null;
		foreach (AnimationState item in controllingAnimation)
		{
			if (item.weight == 1f)
			{
				animationState = item;
				currentClip = item.clip;
				break;
			}
		}
		if (!playAnimation)
		{
			if (controllingAnimation.isPlaying)
			{
				controllingAnimation.Stop();
			}
			return;
		}
		if (!controllingAnimation.enabled)
		{
			controllingAnimation.enabled = true;
		}
		if (currentClip != clips[animationClipIndex] || animationState == null || !controllingAnimation.isPlaying)
		{
			currentClip = clips[animationClipIndex];
			currentClip.legacy = true;
			while (lateStart > 0f && currentClip.length < lateStart && animationClipIndex < clips.Count - 1)
			{
				lateStart -= currentClip.length;
				currentClip = clips[++animationClipIndex];
				currentClip.legacy = true;
			}
			controllingAnimation.Play(currentClip.name);
			animationState = controllingAnimation[currentClip.name];
			animationState.time = System.Math.Min(lateStart, currentClip.length);
			lateStart = 0f;
		}
		float time = animationState.time;
		if (!bakedAnimationData.ContainsKey(currentClip))
		{
			return;
		}
		foreach (KeyValuePair<GorillaEventAnimation, List<ControlledAnimationKeyframeData>> item2 in bakedAnimationData[currentClip])
		{
			GorillaEventAnimation key = item2.Key;
			List<ControlledAnimationKeyframeData> value = item2.Value;
			for (int i = 0; i < value.Count; i++)
			{
				if (value.Count < 2 || i == value.Count - 1 || !(time >= value[i].startTime) || !(time >= value[i + 1].startTime))
				{
					bool flag = false;
					int num = value[i].animationClipIndex;
					float startTime = time - value[i].startTime + value[i].startOffset;
					if (key.enabled != value[i].animEnabled)
					{
						key.enabled = value[i].animEnabled;
						flag = value[i].animEnabled;
					}
					if (value[i].animEnabled && (key._clipIndex != value[i].animationClipIndex || !key._animation.IsPlaying(key.clips[num].name)))
					{
						flag = true;
					}
					if (flag)
					{
						key.PlayClipByIndex(value[i].animationClipIndex, startTime);
					}
					break;
				}
			}
		}
	}

	public void SetPlayState(bool isPlaying)
	{
		playAnimation = isPlaying;
	}

	public void SetAnimationClip(int clipIndex)
	{
		animationClipIndex = clipIndex;
	}

	public void StartPlaying(float secondsPast)
	{
		lateStart = secondsPast;
		animationClipIndex = 0;
		playAnimation = true;
	}

	public void StartPlaying()
	{
		StartPlaying(0f);
	}
}
