public class SIBlasterSplashProjectile : MonoBehaviour, SIGadgetProjectileType
{
	public float knockbackSpeed;

	public float fullSplashRadius;

	public float splashHitDistance;

	public float upwardsAngle = 30f;

	private SIGadgetBlasterProjectile projectile;

	private List<VRRig> rigList = new List<VRRig>();

	private RaycastHit[] hits = new RaycastHit[20];

	private void OnEnable()
	{
		projectile = GetComponent<SIGadgetBlasterProjectile>();
	}

	public void LocalProjectileHit(SIPlayer player = null)
	{
		if (!projectile.firedByPlayer == (bool)SIPlayer.LocalPlayer)
		{
			SIGadgetBlasterProjectile.SpawnExplosion(projectile.hitEffect, projectile.transform.position, projectile.transform.rotation);
			projectile.DespawnProjectile();
			return;
		}
		rigList.Clear();
		VRRigCache.Instance.GetActiveRigs(rigList);
		UnityEngine.Vector3 position = projectile.transform.position;
		for (int num = rigList.Count - 1; num >= 0; num--)
		{
			if ((rigList[num].transform.position - position).magnitude < splashHitDistance)
			{
				UnityEngine.Vector3 position2 = rigList[num].head.rigTarget.position;
				UnityEngine.Vector3 position3 = rigList[num].bodyTransform.position;
				if (Physics.RaycastNonAlloc(position, position2 - position, hits, splashHitDistance, projectile.parentBlaster.environmentLayerMask, QueryTriggerInteraction.Ignore) != 0 && Physics.RaycastNonAlloc(position, position3 - position, hits, splashHitDistance, projectile.parentBlaster.environmentLayerMask, QueryTriggerInteraction.Ignore) != 0)
				{
					rigList.RemoveAt(num);
				}
			}
			else
			{
				rigList.RemoveAt(num);
			}
		}
		if (rigList.Count <= 0)
		{
			SIGadgetBlasterProjectile.SpawnExplosion(projectile.hitEffect, projectile.transform.position, projectile.transform.rotation);
			projectile.DespawnProjectile();
		}
		else
		{
			SIGadgetBlasterProjectile.SpawnExplosion(projectile.hitEffectPlayer, projectile.transform.position, projectile.transform.rotation);
			TriggerSplashHitPlayers(rigList);
			projectile.DespawnProjectile();
		}
	}

	public void TriggerSplashHitPlayers(List<VRRig> hitPlayers)
	{
		int[] array = new int[hitPlayers.Count];
		UnityEngine.Vector3[] array2 = new UnityEngine.Vector3[hitPlayers.Count];
		for (int i = 0; i < hitPlayers.Count; i++)
		{
			array[i] = ((hitPlayers[i] != null && hitPlayers[i].OwningNetPlayer != null) ? hitPlayers[i].OwningNetPlayer.ActorNumber : (-1));
			UnityEngine.Vector3 vector = hitPlayers[i].transform.position - projectile.transform.position;
			float num = Mathf.Max(0f, 1f - Mathf.Max(0f, vector.magnitude - fullSplashRadius) / (splashHitDistance - fullSplashRadius));
			array2[i] = vector.normalized * knockbackSpeed * num;
			if (hitPlayers[i] != null && hitPlayers[i].isLocal && num > 0f)
			{
				SplashHitLocalPlayer(array2[i]);
			}
		}
		projectile.parentBlaster.SendClientToClientRPC(1, new object[4]
		{
			projectile.projectileId,
			base.transform.position,
			array,
			array2
		});
	}

	public void NetworkedProjectileHit(object[] data)
	{
		if (data == null || data.Length != 4 || !GameEntityManager.ValidateDataType<int>(data[0], out var _) || !GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[1], out var dataAsType2) || !dataAsType2.IsFinite() || !GameEntityManager.ValidateDataType<int[]>(data[2], out var dataAsType3) || !GameEntityManager.ValidateDataType<UnityEngine.Vector3[]>(data[3], out var dataAsType4))
		{
			return;
		}
		for (int i = 0; i < dataAsType4.Length; i++)
		{
			if (!dataAsType4[i].IsFinite())
			{
				return;
			}
		}
		if (dataAsType3.Length > VRRigCache.Instance.GetAllRigs().Length || dataAsType3.Length != dataAsType4.Length || (base.transform.position - dataAsType2).magnitude > projectile.parentBlaster.maxLagDistance)
		{
			return;
		}
		projectile.DespawnProjectile();
		bool flag = false;
		for (int j = 0; j < dataAsType3.Length; j++)
		{
			SIPlayer sIPlayer = SIPlayer.Get(dataAsType3[j]);
			if (sIPlayer != null && sIPlayer == SIPlayer.LocalPlayer)
			{
				flag = true;
				SplashHitLocalPlayer(dataAsType4[j]);
			}
		}
		if (flag)
		{
			SIGadgetBlasterProjectile.SpawnExplosion(projectile.hitEffectPlayer, dataAsType2, base.transform.rotation);
		}
		else
		{
			SIGadgetBlasterProjectile.SpawnExplosion(projectile.hitEffect, dataAsType2, base.transform.rotation);
		}
	}

	public void SplashHitLocalPlayer(UnityEngine.Vector3 directionAndMagnitude)
	{
		if (!(directionAndMagnitude.magnitude > knockbackSpeed * 1.05f))
		{
			SIPlayer.LocalPlayer.NotifyBlasterSplashHit();
			float num = UnityEngine.Vector3.Angle(directionAndMagnitude.normalized, UnityEngine.Vector3.up);
			UnityEngine.Vector3 vector = UnityEngine.Vector3.RotateTowards(directionAndMagnitude.normalized, UnityEngine.Vector3.up, Mathf.Clamp(num - upwardsAngle, 0f, upwardsAngle) * (MathF.PI / 180f), 0f);
			projectile.KnockbackWithHaptics(vector * directionAndMagnitude.magnitude, directionAndMagnitude.magnitude / knockbackSpeed * projectile.hapticHitStrength, projectile.hapticHitDuration);
		}
	}
}
public class SIBlasterSprayProjectile : MonoBehaviour
{
	private SIGadgetBlasterProjectile projectile;

	public float knockbackSpeed;

	public float verticalOffset = -0.133f;

	public float upwardsAngle = 30f;

	private void OnEnable()
	{
		projectile = GetComponent<SIGadgetBlasterProjectile>();
	}

	public void LocalProjectileHit(SIPlayer player = null)
	{
		if (player != null && projectile.hitEffectPlayer != null)
		{
			UnityEngine.Object.Instantiate(projectile.hitEffectPlayer, projectile.transform.position, projectile.transform.rotation);
		}
		if (player == null && projectile.hitEffect != null)
		{
			UnityEngine.Object.Instantiate(projectile.hitEffect, projectile.transform.position, projectile.transform.rotation);
		}
		if (player != null)
		{
			TriggerBlastDirectHitPlayer(player);
		}
		projectile.DespawnProjectile();
	}

	public void TriggerBlastDirectHitPlayer(SIPlayer playerHit)
	{
		if (!(playerHit == SIPlayer.LocalPlayer))
		{
			float num = UnityEngine.Vector3.Angle(base.transform.forward, UnityEngine.Vector3.up);
			UnityEngine.Vector3 vector = UnityEngine.Vector3.RotateTowards(base.transform.forward.normalized, UnityEngine.Vector3.up, Mathf.Clamp(num - upwardsAngle, 0f, upwardsAngle) * (MathF.PI / 180f), 0f);
			projectile.parentBlaster.SendClientToClientRPC(1, new object[4]
			{
				projectile.projectileId,
				base.transform.position,
				vector,
				playerHit.ActorNr
			});
		}
	}

	public void NetworkedProjectileHit(object[] data)
	{
		if (data == null || data.Length != 4 || !GameEntityManager.ValidateDataType<int>(data[0], out var _) || !GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[1], out var dataAsType2) || !GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[2], out var dataAsType3) || !GameEntityManager.ValidateDataType<int>(data[3], out var dataAsType4) || (base.transform.position - dataAsType2).magnitude > projectile.parentBlaster.maxLagDistance)
		{
			return;
		}
		projectile.DespawnProjectile();
		SIPlayer sIPlayer = SIPlayer.Get(dataAsType4);
		if (!(sIPlayer == null))
		{
			if (sIPlayer != SIPlayer.LocalPlayer)
			{
				UnityEngine.Object.Instantiate(projectile.hitEffect, dataAsType2, projectile.transform.rotation);
				return;
			}
			UnityEngine.Object.Instantiate(projectile.hitEffectPlayer, dataAsType2, projectile.transform.rotation);
			GTPlayer.Instance.ApplyKnockback(dataAsType3.normalized, knockbackSpeed, forceOffTheGround: true);
		}
	}
}
[RequireComponent(typeof(GameGrabbable))]
[RequireComponent(typeof(GameSnappable))]
[RequireComponent(typeof(GameButtonActivatable))]
[RequireComponent(typeof(SIGadgetBlasterType))]
public class SIGadgetBlaster : SIGadget, ITickSystemTick
{
	public enum RPCCalls
	{
		FireProjectile,
		ProjectileHitPlayer
	}

	[OnEnterPlay_SetNull]
	public static Dictionary<int, List<GameObject>> blasterProjectilePools;

	[NonSerialized]
	public const float PROJECTILE_MAX_LATENCY = 1f;

	private SIGadgetBlasterType blasterType;

	[NonSerialized]
	public SIGadgetBlasterState currentState;

	[SerializeField]
	private GameButtonActivatable buttonActivatable;

	[SerializeField]
	private float inputActivateThreshold = 0.35f;

	[SerializeField]
	private float inputDeactivateThreshold = 0.25f;

	public int maxProjectileCount = 10;

	public float maxLagDistance = 5f;

	private bool wasActivated;

	[NonSerialized]
	public float lastFired;

	[NonSerialized]
	public int projectileCount;

	private int projectileId;

	[NonSerialized]
	public List<SIGadgetBlasterProjectile> activeProjectiles = new List<SIGadgetBlasterProjectile>();

	[NonSerialized]
	public Queue<SIGadgetBlasterProjectile> projectilesToDespawn = new Queue<SIGadgetBlasterProjectile>();

	[NonSerialized]
	public Queue<float> projectilesToDespawnTimes = new Queue<float>();

	public Transform firingPosition;

	public AudioSource firingSource;

	public AudioSource blasterSource;

	[NonSerialized]
	public LayerMask environmentLayerMask;

	public bool LocalEquippedOrActivated
	{
		get
		{
			if (!IsEquippedLocal())
			{
				return activatedLocally;
			}
			return true;
		}
	}

	public bool TickRunning { get; set; }

	protected override void OnEnable()
	{
		base.OnEnable();
		blasterType = GetComponent<SIGadgetBlasterType>();
		lastFired = 0f;
		environmentLayerMask = GTPlayer.Instance.locomotionEnabledLayers;
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(StartGrabbing));
		GameEntity obj2 = gameEntity;
		obj2.OnSnapped = (Action)Delegate.Combine(obj2.OnSnapped, new Action(StartGrabbing));
		GameEntity obj3 = gameEntity;
		obj3.OnReleased = (Action)Delegate.Combine(obj3.OnReleased, new Action(StopGrabbing));
		GameEntity obj4 = gameEntity;
		obj4.OnUnsnapped = (Action)Delegate.Combine(obj4.OnUnsnapped, new Action(StopGrabbing));
		TickSystem<object>.AddTickCallback(this);
	}

	private new void OnDisable()
	{
		base.OnDisable();
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void Tick()
	{
		if (projectilesToDespawn.Count > 0 && !(Time.time < projectilesToDespawnTimes.Peek() + 1f))
		{
			SIGadgetBlasterProjectile sIGadgetBlasterProjectile = projectilesToDespawn.Dequeue();
			activeProjectiles.RemoveIfContains(sIGadgetBlasterProjectile);
			if (!(sIGadgetBlasterProjectile == null) && !(sIGadgetBlasterProjectile.gameObject == null))
			{
				blasterProjectilePools[sIGadgetBlasterProjectile.poolId].Add(sIGadgetBlasterProjectile.gameObject);
			}
		}
	}

	protected override void OnUpdateAuthority(float dt)
	{
		base.OnUpdateAuthority(dt);
		blasterType.OnUpdateAuthority(dt);
	}

	protected override void OnUpdateRemote(float dt)
	{
		base.OnUpdateRemote(dt);
		SIGadgetBlasterState sIGadgetBlasterState = (SIGadgetBlasterState)gameEntity.GetState();
		if (sIGadgetBlasterState != currentState)
		{
			SetStateShared(sIGadgetBlasterState);
		}
		blasterType.OnUpdateRemote(dt);
	}

	public void SetStateAuthority(SIGadgetBlasterState newState)
	{
		SetStateShared(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetStateShared(SIGadgetBlasterState newState)
	{
		if (newState != currentState && CanChangeState((long)newState))
		{
			_ = currentState;
			currentState = newState;
			blasterType.SetStateShared();
		}
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		blasterType.ApplyUpgradeNodes(withUpgrades);
	}

	public static bool CanChangeState(long newStateIndex)
	{
		if (newStateIndex >= 0)
		{
			return newStateIndex < 4;
		}
		return false;
	}

	public bool CheckInput()
	{
		float sensitivity = (wasActivated ? inputActivateThreshold : inputDeactivateThreshold);
		wasActivated = buttonActivatable.CheckInput(sensitivity);
		return wasActivated;
	}

	public int NextFireId()
	{
		return projectileId++;
	}

	public override void ProcessClientToClientRPC(PhotonMessageInfo info, int rpcID, object[] data)
	{
		switch ((RPCCalls)rpcID)
		{
		case RPCCalls.FireProjectile:
			if (data != null && data.Length != 0 && gameEntity.IsAttachedToPlayer(NetPlayer.Get(info.Sender)))
			{
				blasterType.NetworkFireProjectile(data);
			}
			break;
		case RPCCalls.ProjectileHitPlayer:
		{
			if (data == null || data.Length < 2 || !GameEntityManager.ValidateDataType<int>(data[0], out var dataAsType))
			{
				break;
			}
			SIGadgetBlasterProjectile sIGadgetBlasterProjectile = null;
			for (int i = 0; i < activeProjectiles.Count; i++)
			{
				if (activeProjectiles[i].projectileId == dataAsType)
				{
					sIGadgetBlasterProjectile = activeProjectiles[i];
					break;
				}
			}
			if (!(sIGadgetBlasterProjectile == null) && !(sIGadgetBlasterProjectile.firedByPlayer != SIPlayer.Get(info.Sender.ActorNumber)))
			{
				sIGadgetBlasterProjectile.GetComponent<SIGadgetProjectileType>().NetworkedProjectileHit(data);
			}
			break;
		}
		}
	}

	public void StartGrabbing()
	{
		if (IsEquippedLocal() || activatedLocally)
		{
			SetStateAuthority(SIGadgetBlasterState.Idle);
		}
	}

	public void StopGrabbing()
	{
		SetStateShared(SIGadgetBlasterState.Idle);
	}

	public void DespawnProjectile(SIGadgetBlasterProjectile projectile)
	{
		projectile.gameObject.SetActive(value: false);
		if (!projectilesToDespawn.Contains(projectile))
		{
			projectilesToDespawn.Enqueue(projectile);
			projectilesToDespawnTimes.Enqueue(Time.time);
		}
	}

	public GameObject InstantiateProjectile(SIGadgetBlasterProjectile projectilePrefab, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation, int thisFireId)
	{
		if (blasterProjectilePools == null)
		{
			blasterProjectilePools = new Dictionary<int, List<GameObject>>();
		}
		int instanceID = projectilePrefab.GetInstanceID();
		if (!blasterProjectilePools.ContainsKey(instanceID))
		{
			blasterProjectilePools.Add(instanceID, new List<GameObject>());
		}
		List<GameObject> list = blasterProjectilePools[instanceID];
		GameObject gameObject;
		if (list.Count <= 0)
		{
			gameObject = UnityEngine.Object.Instantiate(projectilePrefab.gameObject, position, rotation);
		}
		else
		{
			gameObject = list[list.Count - 1];
			list.RemoveAt(list.Count - 1);
			gameObject.SetActive(value: true);
		}
		SIGadgetBlasterProjectile component = gameObject.GetComponent<SIGadgetBlasterProjectile>();
		component.transform.position = position;
		component.transform.rotation = rotation;
		component.parentBlaster = this;
		component.projectileId = thisFireId;
		component.firedByPlayer = (gameEntity.IsHeld() ? SIPlayer.Get(gameEntity.heldByActorNumber) : SIPlayer.Get(gameEntity.snappedByActorNumber));
		component.poolId = instanceID;
		activeProjectiles.Add(component);
		lastFired = Time.time;
		component.InitializeProjectile();
		return gameObject;
	}

	public void FireProjectileHaptics(float strength, float duration)
	{
		GorillaTagger.Instance.StartVibration(gameEntity.EquippedHandedness == EHandedness.Left, strength, duration);
	}

	public float CurrentFireRate()
	{
		int count = activeProjectiles.Count;
		if (count <= 1)
		{
			return 0f;
		}
		return (float)(count - 1) / (activeProjectiles[count - 1].timeSpawned - activeProjectiles[0].timeSpawned);
	}
}
public enum SIGadgetBlasterState
{
	Idle,
	Charging,
	Cooldown,
	Pumping,
	Count
}
public interface SIGadgetBlasterType
{
	void OnUpdateAuthority(float dt);

	void OnUpdateRemote(float dt);

	void SetStateShared();

	void NetworkFireProjectile(object[] data);

	void ApplyUpgradeNodes(SIUpgradeSet withUpgrades);
}
[RequireComponent(typeof(SIGadgetProjectileType))]
[RequireComponent(typeof(Rigidbody))]
public class SIGadgetBlasterProjectile : MonoBehaviourTick
{
	[OnEnterPlay_SetNull]
	public static Dictionary<int, List<GameObject>> blasterProjectileExplosionPools;

	[OnEnterPlay_SetNull]
	public static Dictionary<GameObject, int> explosionTypeKey;

	[NonSerialized]
	public int poolId;

	public SIGadgetProjectileType projectileType;

	public Rigidbody rb;

	public GameObject hitEffect;

	public GameObject hitEffectPlayer;

	public float maxLifetime = 10f;

	[NonSerialized]
	public float timeSpawned;

	public float hapticHitStrength = 0.75f;

	public float hapticHitDuration = 0.1f;

	[NonSerialized]
	public SIGadgetBlaster parentBlaster;

	[NonSerialized]
	public int projectileId;

	[NonSerialized]
	public SIPlayer firedByPlayer;

	public float startingVelocity;

	public const float EXCLUSION_ZONE_MINIMUM_LIFETIME = 0.02f;

	public GameObject exclusionZoneDespawnEffect;

	private AudioSource audioSource;

	public override void Tick()
	{
		if (Time.time > timeSpawned + maxLifetime)
		{
			parentBlaster.DespawnProjectile(this);
		}
	}

	public void InitializeProjectile()
	{
		rb.angularVelocity = UnityEngine.Vector3.zero;
		rb.linearVelocity = base.transform.forward * startingVelocity;
		timeSpawned = Time.realtimeSinceStartup;
		if (audioSource == null)
		{
			audioSource = GetComponentInChildren<AudioSource>();
		}
		audioSource.time = 0f;
		projectileType = GetComponent<SIGadgetProjectileType>();
		SIGadgetProjectileModifier[] components = GetComponents<SIGadgetProjectileModifier>();
		for (int i = 0; i < components.Length; i++)
		{
			components[i].ModifyProjectile(this);
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		if (other.GetComponent<SIExclusionZone>() != null && Time.realtimeSinceStartup > timeSpawned + 0.02f)
		{
			if (exclusionZoneDespawnEffect != null)
			{
				SpawnExplosion(exclusionZoneDespawnEffect, base.transform.position, base.transform.rotation);
			}
			DespawnProjectile();
		}
		else
		{
			SIPlayer componentInParent = other.GetComponentInParent<SIPlayer>();
			if (!(componentInParent == null) && !(componentInParent == firedByPlayer) && !(firedByPlayer != SIPlayer.LocalPlayer) && !(componentInParent == SIPlayer.LocalPlayer))
			{
				projectileType.LocalProjectileHit(componentInParent);
			}
		}
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		projectileType.LocalProjectileHit();
		if (collision.collider.gameObject.TryGetComponent<HitTargetNetworkState>(out var component))
		{
			component.TargetHit((Time.time - timeSpawned) * startingVelocity * -base.transform.forward + base.transform.position, base.transform.position);
		}
	}

	public void DespawnProjectile()
	{
		parentBlaster.DespawnProjectile(this);
	}

	public void KnockbackWithHaptics(UnityEngine.Vector3 directionAndMagnitude, bool adjustForDirection = true)
	{
		KnockbackWithHaptics(directionAndMagnitude, hapticHitStrength, hapticHitDuration, adjustForDirection);
	}

	public void KnockbackWithHaptics(UnityEngine.Vector3 directionAndMagnitude, float hapticStrength, float hapticDuration, bool adjustForDirection = true)
	{
		SIPlayer.LocalPlayer.PlayerKnockback(directionAndMagnitude);
		SIPlayer.LocalPlayer.NotifyBlasterHit();
		if (adjustForDirection)
		{
			UnityEngine.Vector3 vector = GorillaTagger.Instance.leftHandTransform.position - GorillaTagger.Instance.bodyCollider.transform.position;
			UnityEngine.Vector3 vector2 = GorillaTagger.Instance.rightHandTransform.position - GorillaTagger.Instance.bodyCollider.transform.position;
			float num = 0.5f;
			float num2 = 45f;
			float num3 = UnityEngine.Vector3.Angle(vector, directionAndMagnitude);
			float num4 = UnityEngine.Vector3.Angle(vector2, directionAndMagnitude);
			float hapticStrength2 = (1f - Mathf.Max(num3 - num2, 0f) / (180f - num2)) * num + (1f - num);
			float hapticStrength3 = (1f - Mathf.Max(num4 - num2, 0f) / (180f - num2)) * num + (1f - num);
			SIPlayer.LocalPlayer.PlayerHandHaptic(isLeft: true, hapticStrength2, hapticDuration);
			SIPlayer.LocalPlayer.PlayerHandHaptic(isLeft: false, hapticStrength3, hapticDuration);
		}
		else
		{
			SIPlayer.LocalPlayer.PlayerHandHaptic(isLeft: true, hapticStrength, hapticDuration);
			SIPlayer.LocalPlayer.PlayerHandHaptic(isLeft: false, hapticStrength, hapticDuration);
		}
	}

	public static GameObject SpawnExplosion(GameObject explosionPrefab, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		if (blasterProjectileExplosionPools == null)
		{
			blasterProjectileExplosionPools = new Dictionary<int, List<GameObject>>();
		}
		if (explosionTypeKey == null)
		{
			explosionTypeKey = new Dictionary<GameObject, int>();
		}
		int instanceID = explosionPrefab.GetInstanceID();
		if (!blasterProjectileExplosionPools.ContainsKey(instanceID))
		{
			blasterProjectileExplosionPools.Add(instanceID, new List<GameObject>());
		}
		List<GameObject> list = blasterProjectileExplosionPools[instanceID];
		GameObject gameObject;
		if (list.Count <= 0)
		{
			gameObject = UnityEngine.Object.Instantiate(explosionPrefab, position, rotation);
			explosionTypeKey.Add(gameObject, instanceID);
		}
		else
		{
			gameObject = list[list.Count - 1];
			list.RemoveAt(list.Count - 1);
			gameObject.SetActive(value: true);
		}
		gameObject.transform.position = position;
		gameObject.transform.rotation = rotation;
		return gameObject;
	}

	public static void DespawnExplosion(GameObject explosion)
	{
		blasterProjectileExplosionPools[explosionTypeKey[explosion]].Add(explosion);
		explosion.SetActive(value: false);
	}
}
public interface SIGadgetProjectileType
{
	void LocalProjectileHit(SIPlayer player = null);

	void NetworkedProjectileHit(object[] data);
}
public interface SIGadgetProjectileModifier
{
	void ModifyProjectile(SIGadgetBlasterProjectile projectile);
}
public class SIGadgetChargeBlaster : MonoBehaviour, SIGadgetBlasterType
{
	[Serializable]
	public struct BlasterChargeLevel
	{
		public float chargeThreshold;

		public float chargingVolume;

		public float firingVolume;

		public float chargingHapticStrength;

		public float firingHapticStrength;

		public float firingHapticDuration;

		public AudioClip firingClip;

		public ParticleSystem fireFX;

		public GameObject chargingFX;

		public SIGadgetBlasterProjectile projectilePrefab;
	}

	[SerializeField]
	private float fireCooldown = 0.2f;

	[SerializeField]
	private float chargeRatePerSecond = 20f;

	public float fireRateGracePercentage = 0.25f;

	public float maxChargeDiff = 5f;

	private float currentCharge;

	public AudioClip chargingClip;

	public BlasterChargeLevel[] chargeLevels;

	private SIGadgetBlaster blaster;

	private bool CheckInput()
	{
		return blaster.CheckInput();
	}

	private void OnEnable()
	{
		blaster = GetComponent<SIGadgetBlaster>();
		currentCharge = 0f;
	}

	public void OnUpdateAuthority(float dt)
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Idle:
			if (CheckInput())
			{
				FireProjectile(0f, blaster.NextFireId(), blaster.firingPosition.position, blaster.firingPosition.rotation);
				blaster.SetStateAuthority(SIGadgetBlasterState.Charging);
			}
			break;
		case SIGadgetBlasterState.Charging:
			currentCharge += chargeRatePerSecond * Time.deltaTime;
			UpdateChargingVisuals();
			if (CheckInput())
			{
				blaster.FireProjectileHaptics(chargeLevels[CurrentBlasterChargeLevel()].chargingHapticStrength, Time.fixedDeltaTime);
			}
			else if (CurrentBlasterChargeLevel() > 0)
			{
				FireProjectile(currentCharge, blaster.NextFireId(), blaster.firingPosition.position, blaster.firingPosition.rotation);
				blaster.SetStateAuthority(SIGadgetBlasterState.Cooldown);
			}
			else
			{
				blaster.SetStateAuthority(SIGadgetBlasterState.Idle);
			}
			break;
		case SIGadgetBlasterState.Cooldown:
			if (!(Time.time < blaster.lastFired + fireCooldown))
			{
				if (CheckInput())
				{
					blaster.SetStateAuthority(SIGadgetBlasterState.Charging);
				}
				else
				{
					blaster.SetStateAuthority(SIGadgetBlasterState.Idle);
				}
			}
			break;
		}
	}

	public void OnUpdateRemote(float dt)
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Charging:
			currentCharge += chargeRatePerSecond * Time.deltaTime;
			UpdateChargingVisuals();
			break;
		case SIGadgetBlasterState.Idle:
		case SIGadgetBlasterState.Cooldown:
			break;
		}
	}

	public void SetStateShared()
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Idle:
			currentCharge = 0f;
			break;
		case SIGadgetBlasterState.Charging:
			currentCharge = 0f;
			blaster.blasterSource.clip = chargingClip;
			blaster.blasterSource.volume = chargeLevels[0].chargingVolume;
			blaster.blasterSource.loop = true;
			blaster.blasterSource.Play();
			break;
		case SIGadgetBlasterState.Cooldown:
			blaster.blasterSource.Stop();
			if (Time.time > blaster.lastFired + fireCooldown)
			{
				blaster.lastFired = Time.time;
			}
			break;
		}
		UpdateChargingVisuals();
	}

	public void FireProjectile(float firedAtChargeLevel, int fireId, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		if (blaster.projectileCount > blaster.maxProjectileCount)
		{
			return;
		}
		if (blaster.LocalEquippedOrActivated)
		{
			if (Time.time < blaster.lastFired + fireCooldown)
			{
				return;
			}
			blaster.SendClientToClientRPC(0, new object[4] { firedAtChargeLevel, fireId, position, rotation });
		}
		if (Mathf.Abs(currentCharge - firedAtChargeLevel) <= maxChargeDiff)
		{
			currentCharge = firedAtChargeLevel;
		}
		SIGadgetBlasterProjectile sIGadgetBlasterProjectile = null;
		int num = CurrentBlasterChargeLevel();
		blaster.firingSource.clip = chargeLevels[num].firingClip;
		blaster.firingSource.volume = chargeLevels[num].firingVolume;
		chargeLevels[num].fireFX.Play();
		sIGadgetBlasterProjectile = chargeLevels[num].projectilePrefab;
		blaster.firingSource.time = 0f;
		blaster.firingSource.Play();
		blaster.firingSource.loop = false;
		if (blaster.LocalEquippedOrActivated)
		{
			blaster.FireProjectileHaptics(chargeLevels[num].firingHapticStrength, chargeLevels[num].firingHapticDuration);
		}
		currentCharge = 0f;
		blaster.InstantiateProjectile(sIGadgetBlasterProjectile, position, rotation, fireId);
	}

	private void UpdateChargingVisuals()
	{
		bool flag = blaster.currentState == SIGadgetBlasterState.Charging;
		int num = CurrentBlasterChargeLevel();
		for (int i = 0; i < chargeLevels.Length; i++)
		{
			bool flag2 = flag && i == num;
			if (chargeLevels[i].chargingFX.activeSelf != flag2)
			{
				chargeLevels[i].chargingFX.SetActive(flag2);
			}
		}
		if (blaster.blasterSource.clip != chargingClip)
		{
			blaster.blasterSource.clip = chargingClip;
		}
		blaster.blasterSource.volume = chargeLevels[num].chargingVolume;
		if (!flag && blaster.blasterSource.isPlaying)
		{
			blaster.blasterSource.Stop();
		}
	}

	public void NetworkFireProjectile(object[] data)
	{
		if (data != null && data.Length == 4 && GameEntityManager.ValidateDataType<float>(data[0], out var dataAsType) && !float.IsNaN(dataAsType) && !float.IsInfinity(dataAsType) && GameEntityManager.ValidateDataType<int>(data[1], out var dataAsType2) && GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[2], out var dataAsType3) && dataAsType3.IsFinite() && GameEntityManager.ValidateDataType<UnityEngine.Quaternion>(data[3], out var dataAsType4) && !((dataAsType3 - blaster.firingPosition.position).magnitude > blaster.maxLagDistance) && !(blaster.CurrentFireRate() > 1f / fireCooldown * (1f + fireRateGracePercentage)))
		{
			FireProjectile(dataAsType, dataAsType2, dataAsType3, dataAsType4);
		}
	}

	public void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
	}

	public int CurrentBlasterChargeLevel()
	{
		int result = -1;
		for (int i = 0; i < chargeLevels.Length; i++)
		{
			if (currentCharge >= chargeLevels[i].chargeThreshold)
			{
				result = i;
				continue;
			}
			return result;
		}
		return result;
	}
}
public class SIGadgetCooldownBlaster : MonoBehaviour, SIGadgetBlasterType
{
	public SIGadgetBlasterProjectile projectilePrefab;

	public float fireCooldown = 0.5f;

	public float fireRateGracePercentage = 0.25f;

	public float availableToFireHapticStrength = 0.1f;

	public float availableToFireHapticDuration = 0.01f;

	public float firingHapticStrength = 0.25f;

	public float firingHapticDuration = 0.01f;

	public AudioClip firingClip;

	public AudioClip cooldownClip;

	public float firingVolume;

	public float cooldownVolume;

	public ParticleSystem fireFX;

	public MeshRenderer cooldownIndicator;

	public Material readyToFireMaterial;

	public Material onCooldownMaterial;

	private bool triggerHeldDown;

	private SIGadgetBlaster blaster;

	private bool CheckInput()
	{
		return blaster.CheckInput();
	}

	private void OnEnable()
	{
		blaster = GetComponent<SIGadgetBlaster>();
		blaster.firingSource.clip = firingClip;
		blaster.firingSource.volume = firingVolume;
		blaster.firingSource.loop = false;
		blaster.blasterSource.clip = cooldownClip;
		blaster.blasterSource.volume = cooldownVolume;
		blaster.blasterSource.loop = false;
	}

	public void OnUpdateAuthority(float dt)
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Idle:
			if (!CheckInput())
			{
				triggerHeldDown = false;
			}
			else if (!triggerHeldDown)
			{
				triggerHeldDown = true;
				FireProjectile(blaster.NextFireId(), blaster.firingPosition.position, blaster.firingPosition.rotation);
				blaster.SetStateAuthority(SIGadgetBlasterState.Cooldown);
			}
			break;
		case SIGadgetBlasterState.Cooldown:
			if (!(Time.time < blaster.lastFired + fireCooldown))
			{
				blaster.FireProjectileHaptics(availableToFireHapticStrength, 0.02f);
				blaster.SetStateAuthority(SIGadgetBlasterState.Idle);
			}
			break;
		}
	}

	public void OnUpdateRemote(float dt)
	{
		if (blaster.currentState != SIGadgetBlasterState.Idle)
		{
			_ = 2;
		}
	}

	public void SetStateShared()
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Idle:
			cooldownIndicator.sharedMaterial = readyToFireMaterial;
			break;
		case SIGadgetBlasterState.Cooldown:
			blaster.lastFired = Time.time;
			cooldownIndicator.sharedMaterial = onCooldownMaterial;
			break;
		}
	}

	public void FireProjectile(int fireId, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		if (blaster.projectileCount > blaster.maxProjectileCount)
		{
			return;
		}
		if (blaster.LocalEquippedOrActivated)
		{
			if (Time.time < blaster.lastFired + fireCooldown)
			{
				return;
			}
			blaster.FireProjectileHaptics(firingHapticStrength, firingHapticDuration);
			blaster.SendClientToClientRPC(0, new object[3] { fireId, position, rotation });
		}
		blaster.firingSource.time = 0f;
		blaster.firingSource.Play();
		blaster.blasterSource.time = 0f;
		blaster.blasterSource.Play();
		blaster.InstantiateProjectile(projectilePrefab, position, rotation, fireId);
	}

	public void NetworkFireProjectile(object[] data)
	{
		if (data != null && data.Length == 3 && GameEntityManager.ValidateDataType<int>(data[0], out var dataAsType) && GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[1], out var dataAsType2) && dataAsType2.IsFinite() && GameEntityManager.ValidateDataType<UnityEngine.Quaternion>(data[2], out var dataAsType3) && !((dataAsType2 - blaster.firingPosition.position).magnitude > blaster.maxLagDistance) && !(blaster.CurrentFireRate() > 1f / fireCooldown * (1f + fireRateGracePercentage)))
		{
			FireProjectile(dataAsType, dataAsType2, dataAsType3);
		}
	}

	public void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
	}
}
[RequireComponent(typeof(SIGadgetBlasterProjectile))]
public class SIGadgetProjectileStretchVisuals : MonoBehaviourTick
{
	private SIGadgetBlasterProjectile projectile;

	public GameObject baseVisuals;

	public Transform frontStretch;

	public Transform rearStretch;

	public float framesPerPosition;

	private float totalLength;

	private float distancePerFrame;

	private float maxStretchRatio;

	private bool maxSizeReached;

	private float frontDistance;

	private float timeSpawned;

	public new void OnEnable()
	{
		base.OnEnable();
		projectile = GetComponent<SIGadgetBlasterProjectile>();
		totalLength = (frontStretch.position - rearStretch.position).magnitude;
		distancePerFrame = projectile.startingVelocity * Time.fixedDeltaTime;
		maxStretchRatio = distancePerFrame / totalLength * framesPerPosition;
		timeSpawned = Time.time;
		maxSizeReached = false;
		baseVisuals.transform.localPosition = new UnityEngine.Vector3(0f, 0f, 0f);
		baseVisuals.transform.localScale = new UnityEngine.Vector3(1f, 1f, 1f);
		frontDistance = (frontStretch.position - base.transform.position).magnitude;
	}

	public override void Tick()
	{
		if (!maxSizeReached)
		{
			float num = (Time.time - timeSpawned) * projectile.startingVelocity / totalLength / 2f + 1f;
			if (num >= maxStretchRatio)
			{
				num = maxStretchRatio;
				maxSizeReached = true;
			}
			baseVisuals.transform.localPosition = new UnityEngine.Vector3(0f, 0f, (0f - (num - 1f)) * frontDistance);
			baseVisuals.transform.localScale = new UnityEngine.Vector3(1f, 1f, num);
		}
	}
}
[RequireComponent(typeof(GameTriggerInteractable))]
public class SIGadgetPumpBlaster : MonoBehaviour, SIGadgetBlasterType
{
	public SIGadgetBlasterProjectile projectilePrefab;

	public AudioClip idleClip;

	public AudioClip cooldownClip;

	public float idleVolume;

	public float cooldownVolume;

	public AudioClip firingClip;

	public float firingVolume;

	public ParticleSystem fireFX;

	public Transform pumpHandlePosition;

	public Transform pumpFullyClosed;

	public Transform pumpFullyOpen;

	private GameTriggerInteractable triggerInteractable;

	private SIGadgetBlaster blaster;

	private Transform pumpingTransform;

	public float currentPumpChargeAmount;

	public float maxPumpCharge = 1f;

	public float remotePumpChargePerSecond = 2f;

	public float maxPumpDiff = 0.5f;

	private float chargePerPump = 1f;

	private bool pumpFullyOpened;

	private float pumpThresholdPercent = 0.1f;

	private float strokeLength;

	private bool CheckInput()
	{
		return blaster.CheckInput();
	}

	private void OnEnable()
	{
		blaster = GetComponent<SIGadgetBlaster>();
		triggerInteractable = GetComponent<GameTriggerInteractable>();
		strokeLength = (pumpFullyClosed.position - pumpFullyOpen.position).magnitude;
	}

	public void OnUpdateAuthority(float dt)
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Idle:
			if (triggerInteractable.triggerInteractionActive)
			{
				blaster.SetStateAuthority(SIGadgetBlasterState.Pumping);
			}
			else if (CheckInput() && currentPumpChargeAmount > 0f)
			{
				AttemptFireProjectile(blaster.NextFireId(), currentPumpChargeAmount, blaster.firingPosition.position, blaster.firingPosition.rotation);
			}
			break;
		case SIGadgetBlasterState.Pumping:
		{
			if (!triggerInteractable.triggerInteractionActive)
			{
				blaster.SetStateAuthority(SIGadgetBlasterState.Idle);
			}
			UnityEngine.Vector3 vector = pumpFullyOpen.position - pumpFullyClosed.position;
			UnityEngine.Vector3 vector2 = pumpingTransform.position - pumpFullyClosed.position;
			if (UnityEngine.Vector3.Dot(vector, vector2) < 0f)
			{
				vector2 = UnityEngine.Vector3.zero;
			}
			UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Project(vector2, vector);
			pumpHandlePosition.position = pumpFullyClosed.position + vector.normalized * Mathf.Clamp(vector3.magnitude, 0f, vector.magnitude);
			if (!pumpFullyOpened && vector3.magnitude > (1f - pumpThresholdPercent) * strokeLength)
			{
				pumpFullyOpened = true;
			}
			else if ((bool)pumpFullyOpen && vector3.magnitude < pumpThresholdPercent * strokeLength)
			{
				pumpFullyOpened = false;
				currentPumpChargeAmount = Mathf.Min(currentPumpChargeAmount + chargePerPump, maxPumpCharge);
			}
			if (CheckInput() && currentPumpChargeAmount > 0f)
			{
				AttemptFireProjectile(blaster.NextFireId(), currentPumpChargeAmount, blaster.firingPosition.position, blaster.firingPosition.rotation);
			}
			break;
		}
		}
	}

	public void OnUpdateRemote(float dt)
	{
		SIGadgetBlasterState currentState = blaster.currentState;
		if (currentState != SIGadgetBlasterState.Idle && currentState == SIGadgetBlasterState.Pumping)
		{
			UnityEngine.Vector3 vector = pumpFullyOpen.position - pumpFullyClosed.position;
			UnityEngine.Vector3 vector2 = pumpingTransform.position - pumpFullyClosed.position;
			if (UnityEngine.Vector3.Dot(vector, vector2) < 0f)
			{
				vector2 = UnityEngine.Vector3.zero;
			}
			UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Project(vector2, vector);
			pumpHandlePosition.position = pumpFullyClosed.position + vector.normalized * Mathf.Clamp(vector3.magnitude, 0f, vector.magnitude);
			currentPumpChargeAmount = Mathf.Min(maxPumpCharge, currentPumpChargeAmount + Time.deltaTime * remotePumpChargePerSecond);
		}
	}

	public void SetStateShared()
	{
		switch (blaster.currentState)
		{
		case SIGadgetBlasterState.Idle:
			blaster.blasterSource.clip = idleClip;
			blaster.blasterSource.volume = idleVolume;
			pumpingTransform = null;
			break;
		case SIGadgetBlasterState.Pumping:
		{
			GameEntity gameEntity = blaster.gameEntity;
			if (GamePlayer.TryGetGamePlayer(gameEntity.AttachedPlayerActorNr, out var out_gamePlayer))
			{
				pumpingTransform = gameEntity.EquippedHandedness switch
				{
					EHandedness.Left => out_gamePlayer.rightHand, 
					EHandedness.Right => out_gamePlayer.leftHand, 
					_ => pumpingTransform, 
				};
			}
			break;
		}
		}
	}

	public void AttemptFireProjectile(int fireId, float pumpChargeAmount, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		if (!(pumpChargeAmount <= 0f) && !(pumpChargeAmount - maxPumpDiff > currentPumpChargeAmount) && blaster.projectileCount <= blaster.maxProjectileCount)
		{
			if (blaster.LocalEquippedOrActivated)
			{
				blaster.SendClientToClientRPC(0, new object[3] { fireId, position, rotation });
			}
			currentPumpChargeAmount = Mathf.Min(maxPumpCharge, pumpChargeAmount);
			blaster.firingSource.time = 0f;
			blaster.firingSource.Play();
			blaster.firingSource.loop = false;
			blaster.InstantiateProjectile(projectilePrefab, position, rotation, fireId);
			currentPumpChargeAmount = 0f;
		}
	}

	public void NetworkFireProjectile(object[] data)
	{
		if (data != null && data.Length == 4 && GameEntityManager.ValidateDataType<int>(data[0], out var dataAsType) && GameEntityManager.ValidateDataType<float>(data[1], out var dataAsType2) && GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[2], out var dataAsType3) && GameEntityManager.ValidateDataType<UnityEngine.Quaternion>(data[3], out var dataAsType4))
		{
			AttemptFireProjectile(dataAsType, dataAsType2, dataAsType3, dataAsType4);
		}
	}

	public void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
	}
}
