	[SerializeField]
	private AudioClip audioReusable;

	[SerializeField]
	private AudioClip audioUsedUp;

	[SerializeField]
	private SoundBankPlayer audioRecharged;

	[Header("Upgrades")]
	[SerializeField]
	private float upgradedSpeedBoost = 5f;

	[SerializeField]
	private float speedBoostVelocityCap = 10f;

	private bool hasActiveCallback;

	private VRRig activeCallbackOnRig;

	private bool wasTriggerPressed;

	private bool isLineBroken;

	private bool wasSlidingUngrounded;

	private UnityEngine.Quaternion activatedAtRotation;

	private UnityEngine.Vector3 activatedAtPoint;

	private UnityEngine.Vector3 ziplineDirection;

	private float coolingDownUntilTimestamp;

	private ResettableUseCounter groundedCooldown;

	private float _speedBoost;

	private static int s_localPlayerVelocityFrame = -1;

	private static UnityEngine.Vector3 s_LocalPlayerAccumulatedVelocity;

	private static int s_LocalPlayerNumAccumulatedVelocities;

	private static int s_LocalPlayerPositionFrame = -1;

	private static UnityEngine.Vector3 s_LocalPlayerAccumulatedPositionOffset;

	private static UnityEngine.Vector3 s_LocalPlayerAppliedPositionOffset;

	private static void AccumulateVelocity(UnityEngine.Vector3 desiredVelocity)
	{
		if (s_localPlayerVelocityFrame != Time.frameCount)
		{
			s_localPlayerVelocityFrame = Time.frameCount;
			s_LocalPlayerAccumulatedVelocity = UnityEngine.Vector3.zero;
			s_LocalPlayerNumAccumulatedVelocities = 0;
		}
		s_LocalPlayerAccumulatedVelocity += desiredVelocity;
		s_LocalPlayerNumAccumulatedVelocities++;
		GTPlayer.Instance.SetVelocity(s_LocalPlayerAccumulatedVelocity / s_LocalPlayerNumAccumulatedVelocities);
	}

	private static void ResetLocalAppliedPositionOffset()
	{
		if (s_LocalPlayerPositionFrame != Time.frameCount)
		{
			s_LocalPlayerPositionFrame = Time.frameCount;
			s_LocalPlayerAccumulatedPositionOffset = UnityEngine.Vector3.zero;
			s_LocalPlayerAppliedPositionOffset = UnityEngine.Vector3.zero;
		}
		else
		{
			GTPlayer.Instance.transform.position -= s_LocalPlayerAppliedPositionOffset;
		}
	}

	private static void ReapplyPositionOffset()
	{
		GTPlayer.Instance.transform.position += s_LocalPlayerAppliedPositionOffset;
	}

	private static void AccumulateAndApplyLocalPositionOffset(UnityEngine.Vector3 offset)
	{
		s_LocalPlayerAccumulatedPositionOffset += offset;
		s_LocalPlayerNumAccumulatedVelocities++;
		s_LocalPlayerAppliedPositionOffset = s_LocalPlayerAccumulatedPositionOffset / s_LocalPlayerNumAccumulatedVelocities;
		GTPlayer.Instance.transform.position += s_LocalPlayerAppliedPositionOffset;
	}

	private void Awake()
	{
		m_buttonActivatable = GetComponent<GameButtonActivatable>();
		laserBeam.SetActive(value: false);
		laserBeam.transform.SetParent(null);
		groundedCooldown = new ResettableUseCounter(1, maxSuperchargeUses, ShowReady);
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(OnGrabbed));
		GameEntity obj2 = gameEntity;
		obj2.OnSnapped = (Action)Delegate.Combine(obj2.OnSnapped, new Action(OnSnapped));
		GameEntity obj3 = gameEntity;
		obj3.OnReleased = (Action)Delegate.Combine(obj3.OnReleased, new Action(OnReleased));
		GameEntity obj4 = gameEntity;
		obj4.OnUnsnapped = (Action)Delegate.Combine(obj4.OnUnsnapped, new Action(OnUnsnapped));
		gameEntity.OnStateChanged += OnEntityStateChanged;
	}

	private void ClearCallback()
	{
		if (hasActiveCallback)
		{
			activeCallbackOnRig.RemoveLateUpdateCallback(this);
			activeCallbackOnRig = null;
			hasActiveCallback = false;
			SIPlayer.LocalPlayer.OnKnockback -= OnKnockback;
		}
	}

	private void ShowReady(bool isReady)
	{
		if (isReady)
		{
			audioRecharged.Play();
		}
	}

	private void OnDestroy()
	{
		ClearCallback();
		laserBeam.gameObject.Destroy();
	}

	private void OnGrabbed()
	{
	}

	private void OnSnapped()
	{
	}

	private void OnReleased()
	{
		wasTriggerPressed = false;
		laserBeam.SetActive(value: false);
		ClearCallback();
	}

	private void OnUnsnapped()
	{
		wasTriggerPressed = false;
		laserBeam.SetActive(value: false);
		ClearCallback();
	}

	protected override void OnUpdateAuthority(float dt)
	{
		bool num = m_buttonActivatable.CheckInput();
		bool flag = GTPlayer.Instance.IsGroundedButt || GTPlayer.Instance.IsGroundedHand || GTPlayer.Instance.IsTentacleActive;
		if (flag)
		{
			groundedCooldown.Reset();
		}
		if (num)
		{
			if (isLineBroken)
			{
				return;
			}
			if (flag)
			{
				if (wasSlidingUngrounded)
				{
					isLineBroken = true;
					laserBeam.SetActive(value: false);
					gameEntity.RequestState(gameEntity.id, GetStateLong());
					return;
				}
			}
			else
			{
				wasSlidingUngrounded = true;
			}
			if (!wasTriggerPressed)
			{
				if (IsBlocked(SIExclusionType.AffectsLocalMovement))
				{
					isLineBroken = true;
					laserBeam.SetActive(value: false);
					return;
				}
				if (Time.time < coolingDownUntilTimestamp)
				{
					isLineBroken = true;
					laserBeam.SetActive(value: false);
					return;
				}
				if (cooldownOnUseUntilTouchGround && !groundedCooldown.TryUse())
				{
					isLineBroken = true;
					laserBeam.SetActive(value: false);
					return;
				}
				SuperInfectionManager activeSuperInfectionManager = SuperInfectionManager.activeSuperInfectionManager;
				if ((object)activeSuperInfectionManager == null || !activeSuperInfectionManager.IsSupercharged)
				{
					onUseAudio.PlayOneShot(audioSingleUse);
				}
				else
				{
					onUseAudio.PlayOneShot(groundedCooldown.IsReady ? audioReusable : audioUsedUp);
				}
				laserBeam.SetActive(value: true);
				laserBeam.transform.localPosition = UnityEngine.Vector3.zero;
				VRRig.LocalRig.AddLateUpdateCallback(this);
				SIPlayer.LocalPlayer.OnKnockback += OnKnockback;
				activeCallbackOnRig = VRRig.LocalRig;
				hasActiveCallback = true;
				activatedAtPoint = zipline.transform.TransformPoint(ziplineAnchorOffset);
				ziplineDirection = zipline.transform.forward;
				UnityEngine.Vector3 up = VRRig.LocalRig.transform.up;
				if (UnityEngine.Vector3.Dot(ziplineDirection, up) > 0f)
				{
					ziplineDirection = -ziplineDirection;
				}
				if (UnityEngine.Vector3.Dot(ziplineDirection, up) > -0.5f)
				{
					ziplineDirection = UnityEngine.Vector3.ProjectOnPlane(ziplineDirection, up);
					ziplineDirection.Normalize();
					ziplineDirection += up * -0.5f;
					ziplineDirection.Normalize();
				}
				activatedAtRotation = UnityEngine.Quaternion.LookRotation(ziplineDirection);
				wasTriggerPressed = true;
				wasSlidingUngrounded = !GTPlayer.Instance.IsGroundedButt && !GTPlayer.Instance.IsGroundedHand;
				gameEntity.RequestState(gameEntity.id, GetStateLong());
			}
			if (IsBlocked(SIExclusionType.AffectsLocalMovement))
			{
				isLineBroken = true;
				laserBeam.SetActive(value: false);
				gameEntity.RequestState(gameEntity.id, GetStateLong());
				return;
			}
			UnityEngine.Vector3 rigidbodyVelocity = GTPlayer.Instance.RigidbodyVelocity;
			GTPlayer.Instance.LaserZiplineActiveAtFrame = Time.frameCount + 1;
			float magnitude = rigidbodyVelocity.magnitude;
			float num2 = UnityEngine.Vector3.Dot(GTPlayer.Instance.RigidbodyVelocity, ziplineDirection);
			if (_speedBoost > 0f && num2 < speedBoostVelocityCap)
			{
				num2 += Time.deltaTime * _speedBoost;
			}
			AccumulateVelocity(ziplineDirection * num2);
			UpdateAudioPitch(magnitude);
			wasTriggerPressed = true;
		}
		else if (wasTriggerPressed)
		{
			laserBeam.SetActive(value: false);
			zipline.transform.localRotation = UnityEngine.Quaternion.identity;
			isLineBroken = false;
			wasTriggerPressed = false;
			wasSlidingUngrounded = false;
			coolingDownUntilTimestamp = Time.time + cooldownDuration;
			float num3 = UnityEngine.Vector3.Dot(GTPlayer.Instance.RigidbodyVelocity, ziplineDirection);
			AccumulateVelocity(ziplineDirection * num3);
			if (FindAttachedHand(out var isLeft))
			{
				GorillaVelocityTracker interactPointVelocityTracker = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeft);
				float scale = GTPlayer.Instance.scale;
				UnityEngine.Vector3 vector = GTPlayer.Instance.turnParent.transform.rotation * -interactPointVelocityTracker.GetAverageVelocity(worldSpace: false, 0.1f, doMagnitudeCheck: true) * scale;
				vector = UnityEngine.Vector3.ClampMagnitude(vector, 5.5f * scale);
				GTPlayer.Instance.AddForce(vector, ForceMode.VelocityChange);
			}
			gameEntity.RequestState(gameEntity.id, GetStateLong());
		}
		else
		{
			isLineBroken = false;
			UnityEngine.Vector3 vector2 = zipline.parent.forward;
			UnityEngine.Vector3 up2 = VRRig.LocalRig.transform.up;
			if (Mathf.Abs(UnityEngine.Vector3.Dot(vector2, up2)) < 0.5f)
			{
				vector2 = UnityEngine.Vector3.ProjectOnPlane(vector2, up2);
				vector2.Normalize();
				vector2 += up2 * -0.5f;
			}
			UnityEngine.Quaternion b = zipline.parent.InverseTransformRotation(UnityEngine.Quaternion.LookRotation(vector2));
			zipline.transform.localRotation = UnityEngine.Quaternion.Lerp(zipline.transform.localRotation, b, Time.deltaTime * 25f);
		}
	}

	private long GetStateLong()
	{
		if (wasTriggerPressed && !isLineBroken)
		{
			return BitPackUtils.PackAnchoredPosRotForNetwork(activatedAtPoint, activatedAtRotation);
		}
		return 0L;
	}

	protected override void OnUpdateRemote(float dt)
	{
		if (laserBeam.activeSelf && activeCallbackOnRig != null)
		{
			UpdateAudioPitch(activeCallbackOnRig.LatestVelocity().magnitude);
		}
	}

	private void OnKnockback(UnityEngine.Vector3 knockbackVector)
	{
		if (wasTriggerPressed)
		{
			isLineBroken = true;
			laserBeam.SetActive(value: false);
		}
	}

	private void OnEntityStateChanged(long oldState, long newState)
	{
		if (IsEquippedLocal() || activatedLocally)
		{
			return;
		}
		if (newState != 0L)
		{
			int attachedPlayerActorNr = gameEntity.AttachedPlayerActorNr;
			if (attachedPlayerActorNr >= 1 && GamePlayer.TryGetGamePlayer(attachedPlayerActorNr, out var out_gamePlayer))
			{
				BitPackUtils.UnpackAnchoredPosRotForNetwork(newState, out_gamePlayer.rig.transform.position, out var pos, out var rot);
				activatedAtPoint = pos;
				activatedAtRotation = rot;
				ziplineDirection = rot * UnityEngine.Vector3.forward;
				laserBeam.SetActive(value: true);
				out_gamePlayer.rig.AddLateUpdateCallback(this);
				activeCallbackOnRig = out_gamePlayer.rig;
				hasActiveCallback = true;
				wasTriggerPressed = true;
				isLineBroken = false;
			}
		}
		else
		{
			wasTriggerPressed = false;
			isLineBroken = false;
			laserBeam.SetActive(value: false);
			ClearCallback();
		}
	}

	public void CallBack()
	{
		if (!wasTriggerPressed || isLineBroken)
		{
			ClearCallback();
			return;
		}
		if (IsEquippedLocal())
		{
			ResetLocalAppliedPositionOffset();
			UnityEngine.Vector3 point = activatedAtPoint - zipline.transform.TransformPoint(ziplineAnchorOffset);
			point = GTExt.ProjectOnPlane(point, UnityEngine.Vector3.zero, ziplineDirection);
			if (point.sqrMagnitude > 1f)
			{
				isLineBroken = true;
				laserBeam.SetActive(value: false);
				ReapplyPositionOffset();
				return;
			}
			AccumulateAndApplyLocalPositionOffset(point);
		}
		zipline.transform.rotation = activatedAtRotation;
		UnityEngine.Vector3 position = activatedAtPoint + UnityEngine.Vector3.Project(zipline.transform.TransformPoint(ziplineAnchorOffset) - activatedAtPoint, ziplineDirection);
		laserBeam.transform.position = position;
		laserBeam.transform.rotation = activatedAtRotation;
	}

	private void UpdateAudioPitch(float playerSpeed)
	{
		laserBeamAudio.pitch = 1f + playerSpeed / 30f;
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		_speedBoost = (withUpgrades.Contains(SIUpgradeType.AirControl_Zipline_Speed) ? upgradedSpeedBoost : 0f);
	}
}
[RequireComponent(typeof(GameGrabbable))]
[RequireComponent(typeof(GameSnappable))]
[RequireComponent(typeof(GameButtonActivatable))]
public class SIGadgetSlipMitt : SIGadget
{
	private enum EState
	{
		Idle,
		Slip,
		DashUsed,
		Count
	}

	private const string preLog = "[SIGadgetSlipMitt]  ";

	private const string preErr = "[SIGadgetSlipMitt]  ERROR!!!  ";

	[SerializeField]
	private GameSnappable m_snappable;

	[SerializeField]
	private Transform m_yoyoDefaultPosXform;

	[SerializeField]
	private GameButtonActivatable m_buttonActivatable;

	[SerializeField]
	private float m_inputActivateThreshold = 0.35f;

	[SerializeField]
	private float m_inputDeactivateThreshold = 0.25f;

	[SerializeField]
	private MeshRenderer m_yoyoRenderer;

	[SerializeField]
	private AudioSource m_audioSource;

	[SerializeField]
	public AudioClip[] m_clips;

	[SerializeField]
	public float[] m_clipVolumes;

	[Tooltip("Yank min/max: How fast you have to be moving your hand for the yank to register and result in a dash.")]
	[SerializeField]
	private float m_yankMinSpeed = 2f;

	[Tooltip("Yank min/max: How fast you have to be moving your hand for the yank to register and result in a dash.")]
	[SerializeField]
	private float m_yankMaxSpeed = 8f;

	[Tooltip("Dash min/max speed: The fastest speed the player will move")]
	[SerializeField]
	private float m_minDashSpeed = 4f;

	private float _maxDashSpeed;

	[SerializeField]
	private float m_maxDashSpeedDefault = 11f;

	[SerializeField]
	private float m_maxDashSpeedUpgraded = 13f;

	[Tooltip("Maps yank speed to dash speed.\nX = Yank Speed (min to max)\nY = Dash Speed (min to max).")]
	[SerializeField]
	private AnimationCurve m_speedMappingCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	[SerializeField]
	private float m_slipperySurfacesTime = 0.25f;

	[SerializeField]
	private float m_maxInfluenceAngleDefault = 10f;

	[SerializeField]
	private float m_maxInfluenceAngleUpgrade = 15f;

	[SerializeField]
	private float m_cooldownDurationDefault = 6f;

	[SerializeField]
	private float m_cooldownDurationUpgrade = 5f;

	[SerializeField]
	private Transform m_airGrabXform;

	private bool _isActivated;

	private bool _wasActivated;

	private float _airGrabTime;

	private float _airReleaseSpeed;

	private UnityEngine.Vector3 _airReleaseVector;

	private VRRig _attachedVRRig;

	private GTPlayer.HandState _attachedHandState;

	private int _lastAttachedPlayerActorNr;

	private int _attachedPlayerActorNr = int.MinValue;

	private bool _isTagged;

	private EState _state;

	private RaycastHit[] _raycastHitResults = new RaycastHit[1];

	private int _HandIndex
	{
		get
		{
			if ((m_snappable.snappedToJoint != null && m_snappable.snappedToJoint.jointType == SnapJointType.HandL) || gameEntity.heldByHandIndex == 0)
			{
				return 0;
			}
			if ((m_snappable.snappedToJoint != null && m_snappable.snappedToJoint.jointType == SnapJointType.HandR) || gameEntity.heldByHandIndex == 1)
			{
				return 1;
			}
			return -1;
		}
	}

	private void Start()
	{
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(_HandleStartInteraction));
		GameEntity obj2 = gameEntity;
		obj2.OnSnapped = (Action)Delegate.Combine(obj2.OnSnapped, new Action(_HandleStartInteraction));
		GameEntity obj3 = gameEntity;
		obj3.OnReleased = (Action)Delegate.Combine(obj3.OnReleased, new Action(_HandleStopInteraction));
		GameEntity obj4 = gameEntity;
		obj4.OnUnsnapped = (Action)Delegate.Combine(obj4.OnUnsnapped, new Action(_HandleStopInteraction));
		AudioClip[] clips = m_clips;
		foreach (AudioClip audioClip in clips)
		{
			if ((bool)audioClip)
			{
				audioClip.LoadAudioData();
			}
		}
	}

	private void OnDestroy()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			GameEntity obj = gameEntity;
			obj.OnGrabbed = (Action)Delegate.Remove(obj.OnGrabbed, new Action(_HandleStartInteraction));
			GameEntity obj2 = gameEntity;
			obj2.OnSnapped = (Action)Delegate.Remove(obj2.OnSnapped, new Action(_HandleStartInteraction));
			GameEntity obj3 = gameEntity;
			obj3.OnReleased = (Action)Delegate.Remove(obj3.OnReleased, new Action(_HandleStopInteraction));
			GameEntity obj4 = gameEntity;
			obj4.OnUnsnapped = (Action)Delegate.Remove(obj4.OnUnsnapped, new Action(_HandleStopInteraction));
		}
	}

	private void _HandleStartInteraction()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			_attachedPlayerActorNr = gameEntity.AttachedPlayerActorNr;
			if (GamePlayer.TryGetGamePlayer(_attachedPlayerActorNr, out var out_gamePlayer))
			{
				_attachedVRRig = out_gamePlayer.rig;
			}
		}
	}

	private void _HandleStopInteraction()
	{
		_attachedPlayerActorNr = -1;
		_attachedVRRig = null;
		if (gameEntity.IsAuthority())
		{
			SetStateAuthority(EState.Idle);
		}
	}

	protected void FixedUpdate()
	{
		if ((!IsEquippedLocal() && !activatedLocally) || ApplicationQuittingState.IsQuitting)
		{
			return;
		}
		_wasActivated = _isActivated;
		_isActivated = _CheckInput();
		if (Time.unscaledTime < _airGrabTime + m_slipperySurfacesTime)
		{
			GTPlayer.Instance.SetMaximumSlipThisFrame();
		}
		switch (_state)
		{
		case EState.Idle:
			if (_isActivated && !IsBlocked(SIExclusionType.AffectsLocalMovement))
			{
				_PlayHaptic(0.1f);
				GTPlayer.Instance.SetGravityOverride(this, _HandleGTPlayerOnUpdateGravity);
				SetStateAuthority(EState.Slip);
			}
			break;
		case EState.Slip:
			if (!_isActivated)
			{
				SetStateAuthority(EState.Idle);
				GTPlayer.Instance.UnsetGravityOverride(this);
				break;
			}
			_airReleaseSpeed = 0f;
			if (_HandIndex == 0)
			{
				GTPlayer.Instance.SetLeftMaximumSlipThisFrame();
				_attachedHandState = GTPlayer.Instance.LeftHand;
			}
			else
			{
				GTPlayer.Instance.SetRightMaximumSlipThisFrame();
				_attachedHandState = GTPlayer.Instance.RightHand;
			}
			break;
		}
	}

	private void _HandleGTPlayerOnUpdateGravity(GTPlayer gtPlayer)
	{
		Transform handFollower = _attachedHandState.handFollower;
		Ray ray = new Ray(handFollower.position, handFollower.forward);
		int value = gtPlayer.locomotionEnabledLayers.value;
		float maxDistance = 1f;
		float num = 20f;
		int num2 = Physics.RaycastNonAlloc(ray, _raycastHitResults, maxDistance, value, QueryTriggerInteraction.Ignore);
		_ = ref _raycastHitResults[0];
		UnityEngine.Vector3 gravity = Physics.gravity;
		UnityEngine.Vector3 vector = ray.direction * num;
		UnityEngine.Vector3 vector2 = ((num2 > 0) ? vector : gravity);
		Draw.ingame.Arrow(ray.origin, ray.origin + ray.direction);
		gtPlayer.AddForce(vector2 * gtPlayer.scale, ForceMode.Acceleration);
	}

	protected override void OnUpdateRemote(float dt)
	{
		base.OnUpdateRemote(dt);
		EState eState = (EState)gameEntity.GetState();
		if (eState != _state)
		{
			_SetStateShared(eState);
		}
	}

	private static bool _CanChangeState(long newStateIndex)
	{
		if (newStateIndex >= 0)
		{
			return newStateIndex < 3;
		}
		return false;
	}

	private void SetStateAuthority(EState newState)
	{
		_SetStateShared(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void _SetStateShared(EState newState)
	{
		if (newState != _state && _CanChangeState((long)newState))
		{
			_state = newState;
			if (_state != EState.Idle)
			{
				_ = 1;
			}
		}
	}

	private bool _CheckInput()
	{
		float sensitivity = (_wasActivated ? m_inputDeactivateThreshold : m_inputActivateThreshold);
		return m_buttonActivatable.CheckInput(sensitivity);
	}

	private void _DoAirGrab()
	{
		_ = GamePlayerLocal.instance.GetHandVelocity(_HandIndex).magnitude;
	}

	private void _DoDash()
	{
		_airGrabTime = Time.unscaledTime;
		UnityEngine.Vector3 handVelocity = GamePlayerLocal.instance.GetHandVelocity(_HandIndex);
		float num = _CalculateDashSpeed(handVelocity.magnitude);
		GTPlayer instance = GTPlayer.Instance;
		instance.SetMaximumSlipThisFrame();
		instance.SetVelocity(handVelocity.normalized * (0f - num));
		_PlayHaptic(2f);
		SetStateAuthority(EState.DashUsed);
	}

	private float _CalculateDashSpeed(float currentYankSpeed)
	{
		float time = Mathf.InverseLerp(m_yankMinSpeed, m_yankMaxSpeed, currentYankSpeed);
		float t = m_speedMappingCurve.Evaluate(time);
		return Mathf.Lerp(m_minDashSpeed, _maxDashSpeed, t);
	}

	private void _PlayHaptic(float strengthMultiplier)
	{
		if (FindAttachedHand(out var isLeft))
		{
			GorillaTagger.Instance.StartVibration(isLeft, GorillaTagger.Instance.tapHapticStrength * strengthMultiplier, GorillaTagger.Instance.tapHapticDuration);
		}
	}

	private void _PlayAudio(int index)
	{
		m_audioSource.clip = m_clips[index];
		m_audioSource.volume = m_clipVolumes[index];
		m_audioSource.GTPlay();
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		_maxDashSpeed = (withUpgrades.Contains(SIUpgradeType.Dash_Yoyo_Speed) ? m_maxDashSpeedUpgraded : m_maxDashSpeedDefault);
	}
}
