{
	private enum State
	{
		Idle,
		Thrown,
		Triggered
	}

	public float disruptTime;

	[SerializeField]
	private float explosionRadius;

	private State state;

	protected override void OnEnable()
	{
		base.OnEnable();
		state = State.Idle;
	}

	protected override void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
