	private void Awake()
	{
		tipDefaultOffset = tip.transform.localPosition;
		hasMotor = motorTransform != null;
		hasEndB = stiltEndB != null;
		hasEndC = stiltEndC != null;
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(OnGrabbed));
		GameEntity obj2 = gameEntity;
		obj2.OnSnapped = (Action)Delegate.Combine(obj2.OnSnapped, new Action(OnSnapped));
		GameEntity obj3 = gameEntity;
		obj3.OnReleased = (Action)Delegate.Combine(obj3.OnReleased, new Action(OnReleased));
		GameEntity obj4 = gameEntity;
		obj4.OnUnsnapped = (Action)Delegate.Combine(obj4.OnUnsnapped, new Action(OnUnsnapped));
		gameEntity.OnStateChanged += OnEntityStateChanged;
	}

	private void DisableCurrentStilt()
	{
		if (currentStiltID != StiltID.None)
		{
			GTPlayer.Instance.DisableStilt(currentStiltID);
			currentStiltID = StiltID.None;
		}
		if (currentStiltIDB != StiltID.None)
		{
			GTPlayer.Instance.DisableStilt(currentStiltIDB);
			currentStiltIDB = StiltID.None;
		}
		if (currentStiltIDC != StiltID.None)
		{
			GTPlayer.Instance.DisableStilt(currentStiltIDC);
			currentStiltIDC = StiltID.None;
		}
	}

	private void OnGrabbed()
	{
		DisableCurrentStilt();
		HandleStartInteraction();
		if (IsEquippedLocal())
		{
			activatedLocally = true;
			if (gameEntity.heldByHandIndex == 0)
			{
				currentStiltID = StiltID.Held_Left;
				GTPlayer.Instance.EnableStilt(currentStiltID, isLeftHand: true, stiltEnd.position, maxArmLength, CanTag, CanStun);
				if (hasEndB)
				{
					currentStiltIDB = StiltID.Held_Left2;
					GTPlayer.Instance.EnableStilt(currentStiltIDB, isLeftHand: true, stiltEndB.position, maxArmLength, CanTag, CanStun);
				}
				if (hasEndC)
				{
					currentStiltIDC = StiltID.Held_Left3;
					GTPlayer.Instance.EnableStilt(currentStiltIDC, isLeftHand: true, stiltEndC.position, maxArmLength, CanTag, CanStun);
				}
			}
			else
			{
				currentStiltID = StiltID.Held_Right;
				GTPlayer.Instance.EnableStilt(currentStiltID, isLeftHand: false, stiltEnd.position, maxArmLength, CanTag, CanStun);
				if (hasEndB)
				{
					currentStiltIDB = StiltID.Held_Right2;
					GTPlayer.Instance.EnableStilt(currentStiltIDB, isLeftHand: false, stiltEndB.position, maxArmLength, CanTag, CanStun);
				}
				if (hasEndC)
				{
					currentStiltIDC = StiltID.Held_Right3;
					GTPlayer.Instance.EnableStilt(currentStiltIDC, isLeftHand: false, stiltEndC.position, maxArmLength, CanTag, CanStun);
				}
			}
		}
		else
		{
			activatedLocally = false;
		}
		wasSnappedByLocalJoint = SnapJointType.None;
	}

	private void OnReleased()
	{
		DisableCurrentStilt();
		HandleStopInteraction();
		if (gameEntity.WasLastHeldByLocalPlayer() && TriggerToExtend && !Mathf.Approximately(targetLength, retractedLength))
		{
			targetLength = retractedLength;
			gameEntity.RequestState(gameEntity.id, PackStateForNetwork());
		}
	}

	private void OnSnapped()
	{
		DisableCurrentStilt();
		HandleStartInteraction();
		if (IsEquippedLocal())
		{
			wasSnappedByLocalJoint = gameEntity.snappedJoint;
			if (wasSnappedByLocalJoint == SnapJointType.HandL)
			{
				currentStiltID = StiltID.Snapped_Left;
				GTPlayer.Instance.EnableStilt(currentStiltID, isLeftHand: true, stiltEnd.position, maxArmLength, CanTag, CanStun);
				if (hasEndB)
				{
					currentStiltIDB = StiltID.Snapped_Left2;
					GTPlayer.Instance.EnableStilt(currentStiltIDB, isLeftHand: true, stiltEndB.position, maxArmLength, CanTag, CanStun);
				}
				if (hasEndC)
				{
					currentStiltIDC = StiltID.Snapped_Left3;
					GTPlayer.Instance.EnableStilt(currentStiltIDC, isLeftHand: true, stiltEndC.position, maxArmLength, CanTag, CanStun);
				}
			}
			else if (wasSnappedByLocalJoint == SnapJointType.HandR)
			{
				currentStiltID = StiltID.Snapped_Right;
				GTPlayer.Instance.EnableStilt(currentStiltID, isLeftHand: false, stiltEnd.position, maxArmLength, CanTag, CanStun);
				if (hasEndB)
				{
					currentStiltIDB = StiltID.Snapped_Right2;
					GTPlayer.Instance.EnableStilt(currentStiltIDB, isLeftHand: false, stiltEndB.position, maxArmLength, CanTag, CanStun);
				}
				if (hasEndC)
				{
					currentStiltIDC = StiltID.Snapped_Right3;
					GTPlayer.Instance.EnableStilt(currentStiltIDC, isLeftHand: false, stiltEndC.position, maxArmLength, CanTag, CanStun);
				}
			}
		}
		else
		{
			wasSnappedByLocalJoint = SnapJointType.None;
		}
	}

	private void OnUnsnapped()
	{
		DisableCurrentStilt();
		HandleStopInteraction();
		if (wasSnappedByLocalJoint == SnapJointType.HandL)
		{
			wasSnappedByLocalJoint = SnapJointType.None;
		}
		else if (wasSnappedByLocalJoint == SnapJointType.HandR)
		{
			wasSnappedByLocalJoint = SnapJointType.None;
		}
	}

	private void OnDestroy()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			DisableCurrentStilt();
			if (attachedVRRig != null)
			{
				VRRig vRRig = attachedVRRig;
				vRRig.OnMaterialIndexChanged = (Action<int, int>)Delegate.Remove(vRRig.OnMaterialIndexChanged, new Action<int, int>(HandleVRRigMaterialIndexChanged));
			}
		}
	}

	protected override void OnUpdateAuthority(float dt)
	{
		if (IsBlocked(SIExclusionType.AffectsLocalMovement))
		{
			DisableCurrentStilt();
			return;
		}
		bool isSpinning = IsSpinning;
		bool flag = false;
		if (currentStiltID != StiltID.None)
		{
			bool num = !TriggerToExtend || CheckInput();
			IsSpinning = hasMotor && CheckInput();
			bool flag2 = false;
			float oldLength = targetLength;
			if (IsSpinning)
			{
				SpinMotor(dt);
				flag = true;
			}
			if (num)
			{
				if (StickToAdjustLength)
				{
					UnityEngine.Vector2 joystickInput = GetJoystickInput();
					if (Mathf.Abs(joystickInput.y) > 0.75f && Mathf.Abs(joystickInput.x) < 0.5f)
					{
						currentExtendedLength = Mathf.Clamp(currentExtendedLength + joystickInput.y * lengthChangeSpeed * Time.deltaTime, retractedLength, maxLength);
					}
				}
				if (!Mathf.Approximately(targetLength, currentExtendedLength))
				{
					targetLength = currentExtendedLength;
				}
				if (!Mathf.Approximately(targetLength, lastSentLength) && Time.time > nextAdjustmentSendTime)
				{
					nextAdjustmentSendTime = Time.time + adjustmentSendRate;
					lastSentLength = targetLength;
					flag2 = true;
				}
			}
			else if (!Mathf.Approximately(targetLength, retractedLength))
			{
				targetLength = retractedLength;
				lastSentLength = targetLength;
				flag2 = true;
			}
			if (flag2 || IsSpinning != isSpinning)
			{
				CheckPlaySounds(oldLength, targetLength);
				gameEntity.RequestState(gameEntity.id, PackStateForNetwork());
			}
		}
		if (hasMotor && !flag && motorAudio.isPlaying)
		{
			motorAudio.Stop();
		}
		isSpinning = IsSpinning;
		UpdateEndPoints(IsSpinning);
	}

	private long PackStateForNetwork()
	{
		long num = 0L;
		if (IsSpinning)
		{
			num |= 1;
		}
		else if (hasMotor)
		{
			long num2 = Mathf.RoundToInt(currentMotorAngle);
			num |= num2 << 1;
		}
		long num3 = Mathf.Clamp(Mathf.RoundToInt(targetLength * 1000f), 0, 3000);
		return num | (num3 << 10);
	}

	private void UnpackStateFromNetwork(long state)
	{
		IsSpinning = (state & 1) != 0;
		if (hasMotor && !IsSpinning)
		{
			currentMotorAngle = (state >> 1) & 0x1FF;
			motorTransform.localRotation = UnityEngine.Quaternion.AngleAxis(currentMotorAngle, UnityEngine.Vector3.right);
		}
		int num = (int)((state >> 10) & 0xFFF);
		targetLength = Mathf.Clamp((float)num * 0.001f, retractedLength, maxLength);
	}

	private void SpinMotor(float dt)
	{
		SuperInfectionManager activeSuperInfectionManager = SuperInfectionManager.activeSuperInfectionManager;
		float num = (((object)activeSuperInfectionManager != null && activeSuperInfectionManager.IsSupercharged) ? 1.5f : 1f);
		currentMotorAngle = (currentMotorAngle + rotateSpeedFactor * num * dt) % 360f;
		motorTransform.localRotation = UnityEngine.Quaternion.AngleAxis(currentMotorAngle, UnityEngine.Vector3.right);
		if (!motorAudio.isPlaying)
		{
			motorAudio.Play();
		}
	}

	protected override void OnUpdateRemote(float dt)
	{
		base.OnUpdateRemote(dt);
		if (hasMotor)
		{
			if (IsSpinning && (gameEntity.heldByActorNumber >= 0 || gameEntity.snappedByActorNumber >= 0))
			{
				SpinMotor(dt);
			}
			else if (motorAudio.isPlaying)
			{
				motorAudio.Stop();
			}
		}
		UpdateEndPoints(force: false);
	}

	private bool CheckInput()
	{
		return buttonActivatable.CheckInput();
	}

	public override SIUpgradeSet FilterUpgradeNodes(SIUpgradeSet upgrades)
	{
		if (restrictedUpgrades.Length == 0)
		{
			return upgrades;
		}
		SIUpgradeSet result = default(SIUpgradeSet);
		SIUpgradeType[] array = restrictedUpgrades;
		foreach (SIUpgradeType upgrade in array)
		{
			if (upgrades.Contains(upgrade))
			{
				result.Add(upgrade);
			}
		}
		return result;
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		CanTag = withUpgrades.Contains(SIUpgradeType.Stilt_Tag_Tip);
		CanStun = withUpgrades.Contains(SIUpgradeType.Stilt_Stun_Tip);
		TriggerToExtend = buttonActivatable != null && withUpgrades.Contains(SIUpgradeType.Stilt_Retractable);
		StickToAdjustLength = TriggerToExtend && withUpgrades.Contains(SIUpgradeType.Stilt_Adjustable_Length);
		extendSpeed = (withUpgrades.Contains(SIUpgradeType.Stilt_Retract_Speed) ? extendSpeedUpgraded : extendSpeedNormal);
		retractSpeed = (withUpgrades.Contains(SIUpgradeType.Stilt_Retract_Speed) ? retractSpeedUpgraded : retractSpeedNormal);
		maxLength = ((TriggerToExtend && withUpgrades.Contains(SIUpgradeType.Stilt_Max_Length)) ? maxLengthUpgraded : maxLengthNormal);
		currentExtendedLength = maxLength;
		targetLength = (TriggerToExtend ? retractedLength : currentExtendedLength);
		currentLength = targetLength;
		ApplyCurrentLength();
	}

	private void UpdateEndPoints(bool force)
	{
		if (force || !Mathf.Approximately(currentLength, targetLength))
		{
			float num = ((targetLength > currentLength) ? extendSpeed : retractSpeed);
			currentLength = Mathf.MoveTowards(currentLength, targetLength, num * Time.deltaTime);
			ApplyCurrentLength();
			if (currentStiltID != StiltID.None)
			{
				GTPlayer.Instance.UpdateStiltOffset(currentStiltID, stiltEnd.position);
			}
			if (currentStiltIDB != StiltID.None)
			{
				GTPlayer.Instance.UpdateStiltOffset(currentStiltIDB, stiltEndB.position);
			}
			if (currentStiltIDC != StiltID.None)
			{
				GTPlayer.Instance.UpdateStiltOffset(currentStiltIDC, stiltEndC.position);
			}
		}
	}

	private void ApplyCurrentLength()
	{
		tip.transform.localPosition = offsetDir * currentLength + tipDefaultOffset;
		UnityEngine.Vector3 localScale = midpoint.transform.localScale;
		localScale.z = currentLength;
		midpoint.transform.localScale = localScale;
	}

	private void OnEntityStateChanged(long oldState, long newState)
	{
		if (!IsEquippedLocal())
		{
			float oldLength = targetLength;
			UnpackStateFromNetwork(newState);
			CheckPlaySounds(oldLength, targetLength);
		}
	}

	private void CheckPlaySounds(float oldLength, float newLength)
	{
		if (!Mathf.Approximately(oldLength, newLength))
		{
			if (Mathf.Approximately(newLength, retractedLength))
			{
				retractSoundBank.Play();
			}
			else if (Mathf.Approximately(oldLength, retractedLength))
			{
				extendSoundBank.Play();
			}
		}
	}

	private void HandleStartInteraction()
	{
		if (ApplicationQuittingState.IsQuitting)
		{
			return;
		}
		attachedPlayerActorNr = gameEntity.AttachedPlayerActorNr;
		attachedNetPlayer = NetworkSystem.Instance.GetPlayer(attachedPlayerActorNr);
		if (GamePlayer.TryGetGamePlayer(attachedPlayerActorNr, out var out_gamePlayer))
		{
			if (attachedVRRig != null)
			{
				VRRig vRRig = attachedVRRig;
				vRRig.OnMaterialIndexChanged = (Action<int, int>)Delegate.Remove(vRRig.OnMaterialIndexChanged, new Action<int, int>(HandleVRRigMaterialIndexChanged));
			}
			attachedVRRig = out_gamePlayer.rig;
			VRRig vRRig2 = attachedVRRig;
			vRRig2.OnMaterialIndexChanged = (Action<int, int>)Delegate.Combine(vRRig2.OnMaterialIndexChanged, new Action<int, int>(HandleVRRigMaterialIndexChanged));
			int num = (isTagged ? 2 : 0);
			if (num != attachedVRRig.setMatIndex)
			{
				HandleVRRigMaterialIndexChanged(num, attachedVRRig.setMatIndex);
			}
		}
	}

	private void HandleStopInteraction()
	{
		attachedPlayerActorNr = -1;
		attachedNetPlayer = null;
		if (attachedVRRig != null)
		{
			VRRig vRRig = attachedVRRig;
			vRRig.OnMaterialIndexChanged = (Action<int, int>)Delegate.Remove(vRRig.OnMaterialIndexChanged, new Action<int, int>(HandleVRRigMaterialIndexChanged));
		}
		attachedVRRig = null;
		if (isTagged)
		{
			HandleVRRigMaterialIndexChanged(2, 0);
		}
	}

	private void HandleVRRigMaterialIndexChanged(int oldMatIndex, int newMatIndex)
	{
		if (attachedPlayerActorNr != -1 && (newMatIndex == 2 || newMatIndex == 1) && CanTag && GorillaGameManager.instance is SuperInfectionGame superInfectionGame)
		{
			isTagged = attachedNetPlayer != null && superInfectionGame.IsInfected(attachedNetPlayer);
			if ((bool)matDest)
			{
				matDest.sharedMaterial = tagActivatedMat;
			}
			if ((bool)skinnedMatDest)
			{
				skinnedMatDest.sharedMaterial = tagActivatedMat;
			}
		}
		else
		{
			isTagged = false;
			if ((bool)matDest)
			{
				matDest.sharedMaterial = defaultMat;
			}
			if ((bool)skinnedMatDest)
			{
				skinnedMatDest.sharedMaterial = defaultMat;
			}
		}
		GameObject[] array = tagActivatedObjects;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetActive(isTagged);
		}
	}
}
public class SIGadgetTapTeleporter : SIGadget
{
	[SerializeField]
	private GameButtonActivatable buttonActivatable;

	[SerializeField]
	private GameObject teleportPointPrefab;

	[SerializeField]
	private SoundBankPlayer blockedSFX;

	[SerializeField]
	private float placementDelay = 0.5f;

	[SerializeField]
	private Renderer identifierColorDisplay;

	[SerializeField]
	private Renderer selectionColorDisplay;

	[SerializeField]
	private Material selectionColor1;

	[SerializeField]
	private Material selectionColor2;

	[SerializeField]
	private float portalDefaultDuration = 30f;

	private float placementCheckDistance = 0.3f;

	private SIGadgetTapTeleporterDeployable _selection1Teleport;

	private SIGadgetTapTeleporterDeployable _selection2Teleport;

	private bool isHandTapSetup;

	private bool isActivated;

	private float nextPlacementDelay;

	private int nextSelectionId;

	private SIUpgradeSet instanceUpgrades;

	private float minBrightness = 0.3f;

	private float maxBrightness = 1f;

	[SerializeField]
	private LayerMask overlapCheckLayers;

	[SerializeField]
	private float nearOffset = 0.11f;

	[SerializeField]
	private float farOffset = 0.664f;

	[SerializeField]
	private float overlapCheckRadius = 0.1f;

	private Collider[] overlapCheckResults = new Collider[1];

	public Color identifierColor { get; private set; }

	public bool useStealthTeleporters { get; private set; }

	public bool isVelocityPreserved { get; private set; }

	public bool hasInfiniteDuration { get; private set; }

	public override void OnEntityInit()
	{
		gameEntity.OnStateChanged += HandleStateChanged;
		gameEntity.onEntityDestroyed += HandleOnDestroyed;
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(HandleHandAttached));
		GameEntity obj2 = gameEntity;
		obj2.OnSnapped = (Action)Delegate.Combine(obj2.OnSnapped, new Action(HandleHandAttached));
		GameEntity obj3 = gameEntity;
		obj3.OnReleased = (Action)Delegate.Combine(obj3.OnReleased, new Action(HandleHandDetach));
		GameEntity obj4 = gameEntity;
		obj4.OnUnsnapped = (Action)Delegate.Combine(obj4.OnUnsnapped, new Action(HandleHandDetach));
		identifierColor = GenerateColor(gameEntity.GetNetId());
		ApplyIdentifierColor();
		UpdateNextSelectionDisplay();
	}

	private void HandleOnDestroyed(GameEntity entity)
	{
		if (gameEntity.IsAuthority())
		{
			if ((bool)_selection1Teleport)
			{
				gameEntity.manager.RequestDestroyItem(_selection1Teleport.gameEntity.id);
			}
			if ((bool)_selection2Teleport)
			{
				gameEntity.manager.RequestDestroyItem(_selection2Teleport.gameEntity.id);
			}
		}
	}

	private new void OnDisable()
	{
		HandleHandDetach();
	}

	private void HandleHandAttached()
	{
		if (IsEquippedLocal())
		{
			isHandTapSetup = true;
			GorillaTagger.Instance.OnHandTap += HandleOnHandTap;
		}
	}

	private void HandleHandDetach()
	{
		if (isHandTapSetup)
		{
			isHandTapSetup = false;
			GorillaTagger.Instance.OnHandTap -= HandleOnHandTap;
		}
		isActivated = false;
	}

	private void HandleOnHandTap(bool isLeft, UnityEngine.Vector3 position, UnityEngine.Vector3 normal)
	{
		if (FindAttachedHand(out var isLeft2) && isLeft == isLeft2 && isActivated)
		{
			PlaceTapTeleporter(position, normal);
		}
	}

	private Color GenerateColor(int seed)
	{
		UnityEngine.Random.InitState(seed);
		float num = Mathf.Lerp(maxBrightness, minBrightness, UnityEngine.Random.value);
		float num2 = Mathf.Lerp(maxBrightness, minBrightness, UnityEngine.Random.value);
		Color black = Color.black;
		switch (UnityEngine.Random.Range(0, 3))
		{
		case 0:
			black.r = num;
			black.g = num2;
			break;
		case 1:
			black.g = num;
			black.b = num2;
			break;
		case 2:
			black.b = num;
			black.r = num2;
			break;
		}
		return black;
	}

	protected override void OnUpdateAuthority(float dt)
	{
		isActivated = buttonActivatable.CheckInput();
		if (nextPlacementDelay > 0f)
		{
			nextPlacementDelay -= dt;
		}
	}

	private void PlaceTapTeleporter(UnityEngine.Vector3 position, UnityEngine.Vector3 normal)
	{
		if (!(nextPlacementDelay > 0f) && CheckValidTeleporterPlacement(position, normal))
		{
			if (IsBlocked())
			{
				blockedSFX.Play();
				return;
			}
			SendClientToAuthorityRPC(0, new object[4]
			{
				position,
				UnityEngine.Quaternion.LookRotation(normal, base.transform.forward),
				nextSelectionId,
				hasInfiniteDuration ? (-1f) : portalDefaultDuration
			});
			CycleSelection();
			nextPlacementDelay = placementDelay;
		}
	}

	private bool CheckValidTeleporterPlacement(UnityEngine.Vector3 position, UnityEngine.Vector3 direction)
	{
		UnityEngine.Vector3 point = position + direction * nearOffset;
		UnityEngine.Vector3 point2 = position + direction * farOffset;
		return Physics.OverlapCapsuleNonAlloc(point, point2, overlapCheckRadius, overlapCheckResults, overlapCheckLayers) == 0;
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		instanceUpgrades = withUpgrades;
		useStealthTeleporters = withUpgrades.Contains(SIUpgradeType.Tapteleport_Stealth);
		isVelocityPreserved = withUpgrades.Contains(SIUpgradeType.Tapteleport_Keep_Velocity);
		hasInfiniteDuration = withUpgrades.Contains(SIUpgradeType.Tapteleport_Infinite_Use);
	}

	public override void ProcessClientToAuthorityRPC(PhotonMessageInfo info, int rpcID, object[] data)
	{
		if (rpcID == 0 && data != null && data.Length == 4 && GameEntityManager.ValidateDataType<UnityEngine.Vector3>(data[0], out var dataAsType) && GameEntityManager.ValidateDataType<UnityEngine.Quaternion>(data[1], out var dataAsType2) && GameEntityManager.ValidateDataType<int>(data[2], out var dataAsType3) && dataAsType3 >= 0 && dataAsType3 <= 100 && GameEntityManager.ValidateDataType<float>(data[3], out var dataAsType4) && gameEntity.IsAttachedToPlayer(NetPlayer.Get(info.Sender)) && !(UnityEngine.Vector3.Distance(dataAsType, base.transform.position) > placementCheckDistance) && CheckValidTeleporterPlacement(dataAsType, dataAsType2 * UnityEngine.Vector3.forward))
		{
			RemoveTeleporter(dataAsType3);
			PlaceNewTapTeleporter(dataAsType, dataAsType2, dataAsType3, dataAsType4);
		}
	}

	public override void ProcessClientToClientRPC(PhotonMessageInfo info, int rpcID, object[] data)
	{
		if (rpcID == 0 && data != null && data.Length == 1 && GameEntityManager.ValidateDataType<int>(data[0], out var dataAsType) && dataAsType >= 0 && dataAsType <= 1 && gameEntity.IsAttachedToPlayer(NetPlayer.Get(info.Sender)))
		{
			nextSelectionId = dataAsType;
			UpdateNextSelectionDisplay();
		}
	}

	private void RemoveTeleporter(int selectId)
	{
		switch (selectId)
		{
		case 0:
			if (_selection1Teleport != null && _selection1Teleport.gameObject.activeSelf)
			{
				gameEntity.manager.RequestDestroyItem(_selection1Teleport.gameEntity.id);
				_selection1Teleport = null;
			}
			break;
		case 1:
			if (_selection2Teleport != null && _selection2Teleport.gameObject.activeSelf)
			{
				gameEntity.manager.RequestDestroyItem(_selection2Teleport.gameEntity.id);
				_selection2Teleport = null;
			}
			break;
		}
	}

	private void PlaceNewTapTeleporter(UnityEngine.Vector3 position, UnityEngine.Quaternion rotation, int selectionId, float duration)
	{
		GameEntityId gameEntityId = gameEntity.manager.RequestCreateItem(teleportPointPrefab.gameObject.name.GetStaticHash(), position, rotation, BitPackUtils.PackIntsIntoLong(selectionId, (int)duration));
		if (!(gameEntityId != GameEntityId.Invalid))
		{
			return;
		}
		SIGadgetTapTeleporterDeployable component = gameEntity.manager.GetGameEntity(gameEntityId).GetComponent<SIGadgetTapTeleporterDeployable>();
		switch (selectionId)
		{
		case 0:
			if (_selection2Teleport != null)
			{
				_selection2Teleport.SetLink(this, component);
			}
			component.SetLink(this, _selection2Teleport);
			_selection1Teleport = component;
			break;
		case 1:
			if (_selection1Teleport != null)
			{
				_selection1Teleport.SetLink(this, component);
			}
			component.SetLink(this, _selection1Teleport);
			_selection2Teleport = component;
			break;
		}
		UpdateNewTeleporters();
	}

	private void UpdateNewTeleporters()
	{
		int value = (_selection1Teleport ? _selection1Teleport.gameEntity.GetNetId() : 0);
		int value2 = (_selection2Teleport ? _selection2Teleport.gameEntity.GetNetId() : 0);
		long newState = BitPackUtils.PackIntsIntoLong(value, value2);
		gameEntity.RequestState(gameEntity.id, newState);
	}

	private void HandleStateChanged(long oldState, long newState)
	{
		if (!gameEntity.IsAuthority())
		{
			BitPackUtils.UnpackIntsFromLong(newState, out var value, out var value2);
			GameEntity gameEntityFromNetId = gameEntity.manager.GetGameEntityFromNetId(value);
			if (gameEntityFromNetId != null)
			{
				_selection1Teleport = gameEntityFromNetId.GetComponent<SIGadgetTapTeleporterDeployable>();
			}
			else
			{
				_selection1Teleport = null;
			}
			GameEntity gameEntityFromNetId2 = gameEntity.manager.GetGameEntityFromNetId(value2);
			if (gameEntityFromNetId2 != null)
			{
				_selection2Teleport = gameEntityFromNetId2.GetComponent<SIGadgetTapTeleporterDeployable>();
			}
			else
			{
				_selection2Teleport = null;
			}
		}
	}

	private void ApplyIdentifierColor()
	{
		identifierColorDisplay.material.color = identifierColor;
	}

	private void UpdateNextSelectionDisplay()
	{
		if (nextSelectionId == 0)
		{
			selectionColorDisplay.material = selectionColor1;
		}
		else if (nextSelectionId == 1)
		{
			selectionColorDisplay.material = selectionColor2;
		}
	}

	public void CycleSelection()
	{
		nextSelectionId = (nextSelectionId + 1) % 2;
		UpdateNextSelectionDisplay();
		SendClientToClientRPC(0, new object[1] { nextSelectionId });
	}
}
public class SIGadgetTapTeleporterDeployable : MonoBehaviour, IGameEntityComponent
{
	public GameEntity gameEntity;

	[SerializeField]
	private Transform destination;

	[SerializeField]
	private Renderer[] identifierColorDisplay;

	[SerializeField]
	private Transform linkDirectionIndicator;

	[SerializeField]
	private Renderer selectionColorDisplay;

	[SerializeField]
	private Material selectionColor1;

	[SerializeField]
	private Material selectionColor2;

	[SerializeField]
	private SoundBankPlayer teleportSoundbank;

	[SerializeField]
	private SIGameEntityStealthVisibility stealth;

	[SerializeField]
	private bool requiresSurfaceTapSinceTeleport;

	private bool maintainVelocity;

	private int selectionId;

	private SIGadgetTapTeleporter _pad;

	private SIGadgetTapTeleporterDeployable linkedPoint;

	private float activateDelay = 0.3f;

	private float activateTime;

	private static float reteleportDelay = 0.3f;

	private static float reteleportTime;

	private Color identifierColor;

	private float timeToDie = -1f;

	private float teleportCheckDistance = 2f;

	private void Awake()
	{
	}

	private void OnEnable()
	{
		activateTime = Time.time + activateDelay;
	}

	private void LateUpdate()
	{
		if (Time.time > timeToDie && gameEntity.IsAuthority())
		{
			if (linkedPoint != null)
			{
				linkedPoint.ClearLink();
			}
			gameEntity.manager.RequestDestroyItem(gameEntity.id);
		}
	}

	public void OnEntityInit()
	{
		BitPackUtils.UnpackIntsFromLong(gameEntity.createData, out selectionId, out var value);
		if ((float)value < 0f)
		{
			timeToDie = float.PositiveInfinity;
		}
		else
		{
			timeToDie = Time.time + (float)value;
		}
		UpdateSelectionDisplay();
	}

	private void UpdateSelectionDisplay()
	{
		if (selectionId == 0)
		{
			selectionColorDisplay.material = selectionColor1;
		}
		else if (selectionId == 1)
		{
			selectionColorDisplay.material = selectionColor2;
		}
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long newState)
	{
		if (gameEntity.IsAuthority())
		{
			return;
		}
		BitPackUtils.UnpackIntsFromLong(newState, out var value, out var value2);
		GameEntity gameEntityFromNetId = gameEntity.manager.GetGameEntityFromNetId(value);
		if (gameEntityFromNetId != null)
		{
			SIGadgetTapTeleporter component = gameEntityFromNetId.GetComponent<SIGadgetTapTeleporter>();
			_pad = component;
			identifierColor = _pad.identifierColor;
		}
		GameEntity gameEntityFromNetId2 = gameEntity.manager.GetGameEntityFromNetId(value2);
		if (gameEntityFromNetId2 != null)
		{
			linkedPoint = gameEntityFromNetId2.GetComponent<SIGadgetTapTeleporterDeployable>();
			if (linkedPoint.linkedPoint == null)
			{
				linkedPoint.linkedPoint = this;
				linkedPoint._pad = _pad;
				linkedPoint.identifierColor = identifierColor;
				linkedPoint.UpdateLinkDisplay();
			}
		}
		else
		{
			linkedPoint = null;
		}
		UpdateLinkDisplay();
	}

	public void SetLink(SIGadgetTapTeleporter newPad, SIGadgetTapTeleporterDeployable newLink)
	{
		_pad = newPad;
		linkedPoint = newLink;
		identifierColor = _pad.identifierColor;
		int value = -1;
		if (linkedPoint != null)
		{
			value = linkedPoint.gameEntity.GetNetId();
		}
		gameEntity.RequestState(gameEntity.id, BitPackUtils.PackIntsIntoLong(_pad.gameEntity.GetNetId(), value));
		UpdateLinkDisplay();
		stealth.enabled = _pad.useStealthTeleporters;
		maintainVelocity = _pad.isVelocityPreserved;
	}

	private void ClearLink()
	{
		linkedPoint = null;
		gameEntity.RequestState(gameEntity.id, BitPackUtils.PackIntsIntoLong(_pad.gameEntity.GetNetId(), -1));
		UpdateLinkDisplay();
	}

	private void UpdateLinkDisplay()
	{
		Renderer[] array = identifierColorDisplay;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].material.color = identifierColor;
		}
		if (linkedPoint != null)
		{
			UnityEngine.Vector3 vector = linkedPoint.transform.position - base.transform.position;
			linkDirectionIndicator.gameObject.SetActive(value: true);
			linkDirectionIndicator.transform.rotation = UnityEngine.Quaternion.LookRotation(base.transform.forward, vector.normalized);
		}
		else
		{
			linkDirectionIndicator.gameObject.SetActive(value: false);
		}
	}

	public void TryTeleport()
	{
		if (activateTime < Time.time && reteleportTime < Time.time && (!requiresSurfaceTapSinceTeleport || GorillaTagger.Instance.hasTappedSurface))
		{
			TeleportToLinked();
		}
	}

	private void ResetRetriggerBlock()
	{
		reteleportTime = Time.time + reteleportDelay;
	}

	private void TeleportToLinked()
	{
		if (linkedPoint == null || !linkedPoint.gameObject.activeSelf)
		{
			return;
		}
		UnityEngine.Vector3 position = destination.position;
		if (!(UnityEngine.Vector3.Distance(GTPlayer.Instance.transform.position, position) > teleportCheckDistance))
		{
			ResetRetriggerBlock();
			if (requiresSurfaceTapSinceTeleport)
			{
				GorillaTagger.Instance.ResetTappedSurfaceCheck();
			}
			UnityEngine.Vector3 position2 = linkedPoint.destination.position;
			UnityEngine.Quaternion rotation = GTPlayer.Instance.transform.rotation;
			GTPlayer.Instance.TeleportTo(position2, rotation, maintainVelocity, center: true);
			linkedPoint.teleportSoundbank.Play();
		}
	}
}
