	private void OnGrabbed()
	{
		isLeftHanded = gameEntity.heldByHandIndex == 0;
		if (GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			hasRigCallback = true;
			rigForCallback = out_gamePlayer.rig;
			rigForCallback.AddLateUpdateCallback(this);
		}
	}

	private void OnSnapped()
	{
		isLeftHanded = gameEntity.snappedJoint == SnapJointType.HandL;
		if (GamePlayer.TryGetGamePlayer(gameEntity.snappedByActorNumber, out var out_gamePlayer))
		{
			hasRigCallback = true;
			rigForCallback = out_gamePlayer.rig;
			rigForCallback.AddLateUpdateCallback(this);
		}
	}

	private void OnReleased()
	{
		ClearClawAnchor();
		if (hasRigCallback)
		{
			hasRigCallback = false;
			rigForCallback.RemoveLateUpdateCallback(this);
		}
	}

	private void OnUnsnapped()
	{
		if (hasRigCallback)
		{
			hasRigCallback = false;
			rigForCallback.RemoveLateUpdateCallback(this);
		}
	}

	private bool CheckInput()
	{
		return buttonActivatable.CheckInput();
	}

	private UnityEngine.Vector3 GetIdealClawPosition(VRRig rig)
	{
		UnityEngine.Vector3 position = rig.bodyTransform.position;
		position.y += 0.05f;
		UnityEngine.Vector3 position2 = base.transform.position;
		UnityEngine.Vector3 vector = position2 - position;
		return position2 + vector * LengthFactor + base.transform.forward * tentacleForwardAdjustment;
	}

	protected override void OnUpdateAuthority(float dt)
	{
		bool flag = CheckInput();
		if (isGripBroken)
		{
			if (flag)
			{
				flag = false;
			}
			else
			{
				isGripBroken = false;
			}
		}
		UnityEngine.Vector3 position = base.transform.position;
		UnityEngine.Vector3 idealClawPosition = GetIdealClawPosition(VRRig.LocalRig);
		UnityEngine.Quaternion rotation = base.transform.rotation;
		float num = 0.15f;
		bool flag2 = isLowFuel;
		if ((knownSafePosition - idealClawPosition).IsLongerThan(1f))
		{
			UnityEngine.Vector3 position2 = GTPlayer.Instance.headCollider.transform.position;
			Ray ray = new Ray(position2, idealClawPosition - position2);
			if (Physics.SphereCast(ray, num, out var hitInfo, (idealClawPosition - position2).magnitude, worldCollisionLayers))
			{
				knownSafePosition = ray.origin + ray.direction * (hitInfo.distance - num * 2.01f);
			}
			else
			{
				knownSafePosition = position;
			}
		}
		if ((isAnchored || isHoldingHand) && !flag)
		{
			GorillaTagger.Instance.StartVibration(isLeftHanded, hapticStrengthOnRelease, hapticDurationOnRelease);
			ClearClawAnchor();
		}
		else
		{
			if (isAnchored)
			{
				currentFuel = Mathf.Max(0f, currentFuel - dt * _current_grab_fps);
				isLowFuel = currentFuel < _lowFuelThreshold;
				if (isLowFuel && !flag2)
				{
					lowFuelSound.Play();
				}
				UpdateFuelGauge();
				if (currentFuel == 0f)
				{
					isGripBroken = true;
					flag = false;
					ClearClawAnchor();
					detachFailSound.Play();
				}
				else
				{
					UnityEngine.Vector3 position3 = GTPlayer.Instance.transform.position;
					clawHoldAdjustment -= position3 - lastRequestedPlayerPosition;
					UnityEngine.Vector3 v = clawAnchorPosition - (idealClawPosition + clawHoldAdjustment);
					v.ClampThisMagnitudeSafe(MaxTentacleJumpSpeed * dt);
					GTPlayer.Instance.RequestTentacleMove(isLeftHanded, v);
					GTPlayer.Instance.TentacleActiveAtFrame = Time.frameCount + 1;
					lastRequestedPlayerPosition = position3 + v;
					if ((clawAnchorPosition - base.transform.position).IsLongerThan(maxTentacleLength))
					{
						isGripBroken = true;
						ClearClawAnchor();
						detachFailSound.Play();
					}
					else
					{
						clawVisualPos = clawAnchorPosition;
						clawVisualRot = clawAnchorRotation;
					}
				}
				wasGrabPressed = flag;
				return;
			}
			if (isHoldingHand)
			{
				TakeMyHand_HandLink takeMyHand_HandLink = (isLeftHanded ? VRRig.LocalRig.leftHandLink : VRRig.LocalRig.rightHandLink);
				if (takeMyHand_HandLink.IsLinkActive())
				{
					UnityEngine.Vector3 position4 = (isLeftHanded ? VRRig.LocalRig.leftHand : VRRig.LocalRig.rightHand).overrideTarget.position;
					takeMyHand_HandLink.TentacleOffset = idealClawPosition - position4;
				}
				else
				{
					isGripBroken = true;
					ClearClawAnchor();
					detachFailSound.Play();
				}
				wasGrabPressed = flag;
				return;
			}
		}
		RaycastHit hitInfo2;
		bool num2 = Physics.SphereCast(new Ray(knownSafePosition, idealClawPosition - knownSafePosition), num, out hitInfo2, (idealClawPosition - knownSafePosition).magnitude, worldCollisionLayers);
		UnityEngine.Vector3 vector = idealClawPosition;
		UnityEngine.Quaternion clawRotation = rotation;
		bool flag3 = false;
		bool flag4 = currentFuel < FuelCost_Grab + FuelPerSecond_Holding;
		if (flag4 && flag)
		{
			isGripBroken = true;
			flag = false;
			attachFailSound.Play();
		}
		if (num2)
		{
			if (!flag4)
			{
				float num3 = UnityEngine.Vector3.Dot(hitInfo2.normal, UnityEngine.Vector3.up);
				if (num3 >= _min_grab_dot)
				{
					_current_grab_fps = ((num3 >= _wall_angle_dot) ? FuelPerSecond_Holding : (FuelPerSecond_Holding * FuelCost_Wall_Multiplier));
					flag3 = true;
					if (GTPlayer.Instance.GetSlidePercentage(hitInfo2) > 0.5f)
					{
						if (!canHoldSlipperyWalls)
						{
							flag3 = false;
							if (flag && !hasFailedToGrab)
							{
								attachFailSound.Play();
								hasFailedToGrab = true;
							}
						}
						else
						{
							_current_grab_fps *= FuelCost_Slippery_Multiplier;
						}
					}
				}
				else if (flag && !hasFailedToGrab)
				{
					attachFailSound.Play();
					hasFailedToGrab = true;
				}
			}
			knownSafePosition += (idealClawPosition - knownSafePosition).normalized * (hitInfo2.distance - num * 2.01f);
			vector = hitInfo2.point + hitInfo2.normal * 0.1f;
		}
		else
		{
			knownSafePosition = idealClawPosition;
		}
		if (flag && flag3)
		{
			vector = hitInfo2.point + hitInfo2.normal * 0.01f;
			clawRotation = UnityEngine.Quaternion.LookRotation(-hitInfo2.normal, rotation * UnityEngine.Vector3.up);
			SetClawAnchor(vector, clawRotation, vector - idealClawPosition);
			GorillaTagger.Instance.StartVibration(isLeftHanded, hapticStrengthOnGrab, hapticDurationOnGrab);
			currentFuel -= FuelCost_Grab;
		}
		else
		{
			if (flag && !wasGrabPressed && (!GorillaComputer.instance.IsPlayerInVirtualStump() || !CustomMapManager.WantsHoldingHandsDisabled()))
			{
				TakeMyHand_HandLink takeMyHand_HandLink2 = (isLeftHanded ? VRRig.LocalRig.leftHandLink : VRRig.LocalRig.rightHandLink);
				UnityEngine.Vector3 position5 = (isLeftHanded ? VRRig.LocalRig.leftHand : VRRig.LocalRig.rightHand).overrideTarget.position;
				foreach (VRRig activeRig in VRRigCache.ActiveRigs)
				{
					if (activeRig.isLocal)
					{
						continue;
					}
					if (activeRig.leftHandLink.interactionPoint.OverlapCheck(vector) && activeRig.leftHandLink.CanBeGrabbed())
					{
						if (takeMyHand_HandLink2.TentacleTryCreateLink(activeRig.leftHandLink))
						{
							isHoldingHand = true;
							clawHoldingVisual.SetActive(value: true);
							clawReleasedVisual.SetActive(value: false);
							takeMyHand_HandLink2.TentacleOffset = idealClawPosition - position5;
							heldPlayerCallback.Register(activeRig, activeRig.leftHandLink);
							gameEntity.RequestState(gameEntity.id, GetStateLong());
							break;
						}
					}
					else if (activeRig.rightHandLink.interactionPoint.OverlapCheck(vector) && activeRig.rightHandLink.CanBeGrabbed() && takeMyHand_HandLink2.TentacleTryCreateLink(activeRig.rightHandLink))
					{
						isHoldingHand = true;
						clawHoldingVisual.SetActive(value: true);
						clawReleasedVisual.SetActive(value: false);
						takeMyHand_HandLink2.TentacleOffset = idealClawPosition - position5;
						heldPlayerCallback.Register(activeRig, activeRig.rightHandLink);
						gameEntity.RequestState(gameEntity.id, GetStateLong());
						break;
					}
				}
			}
			UnityEngine.Vector3 axis = UnityEngine.Quaternion.AngleAxis(Time.time * 180f, UnityEngine.Vector3.forward) * UnityEngine.Vector3.up;
			if (flag3)
			{
				clawRotation = UnityEngine.Quaternion.Lerp(rotation, UnityEngine.Quaternion.LookRotation(-hitInfo2.normal, rotation * UnityEngine.Vector3.up), 0.75f);
				clawRotation *= UnityEngine.Quaternion.AngleAxis(5f, axis);
			}
			else
			{
				clawRotation *= UnityEngine.Quaternion.AngleAxis(20f, axis);
				vector.y += 0.05f * Mathf.Cos(Time.time * 2f);
			}
		}
		clawVisualPos = vector;
		clawVisualRot = clawRotation;
		if (!isAnchored)
		{
			isLowFuel = currentFuel < FuelCost_Grab;
		}
		wasGrabPressed = flag;
		UpdateFuelGauge();
	}

	private void UpdateFuelGauge()
	{
		float value = currentFuel / fuelSize;
		for (int i = 0; i < m_gaugeMatSlots.Length; i++)
		{
			_gaugeMatPropBlock.SetFloat(ShaderProps._EmissionDissolveProgress, value);
			m_gaugeMatSlots[i].renderer.SetPropertyBlock(_gaugeMatPropBlock, m_gaugeMatSlots[i].slot);
		}
	}

	protected override void OnUpdateRemote(float dt)
	{
		if (isAnchored)
		{
			return;
		}
		VRRig attachedPlayerRig = GetAttachedPlayerRig();
		if (attachedPlayerRig == null)
		{
			return;
		}
		UnityEngine.Vector3 idealClawPosition = GetIdealClawPosition(attachedPlayerRig);
		UnityEngine.Quaternion rotation = base.transform.rotation;
		UnityEngine.Vector3 position = base.transform.position;
		if ((knownSafePosition - idealClawPosition).IsLongerThan(1f))
		{
			knownSafePosition = position;
		}
		if (isHoldingHand)
		{
			TakeMyHand_HandLink obj = (isLeftHanded ? attachedPlayerRig.leftHandLink : attachedPlayerRig.rightHandLink);
			UnityEngine.Vector3 position2 = (isLeftHanded ? attachedPlayerRig.leftHand : attachedPlayerRig.rightHand).rigTarget.position;
			obj.TentacleOffset = idealClawPosition - position2;
			return;
		}
		float num = 0.15f;
		RaycastHit hitInfo;
		bool num2 = Physics.SphereCast(new Ray(knownSafePosition, idealClawPosition - knownSafePosition), num, out hitInfo, (idealClawPosition - knownSafePosition).magnitude, worldCollisionLayers);
		UnityEngine.Vector3 axis = UnityEngine.Quaternion.AngleAxis(Time.time * 180f, UnityEngine.Vector3.forward) * UnityEngine.Vector3.up;
		UnityEngine.Vector3 vector = idealClawPosition;
		UnityEngine.Quaternion quaternion2 = rotation;
		if (num2)
		{
			knownSafePosition += (idealClawPosition - knownSafePosition).normalized * (hitInfo.distance - num * 2.01f);
			vector = hitInfo.point + hitInfo.normal * 0.1f;
			quaternion2 *= UnityEngine.Quaternion.AngleAxis(5f, axis);
		}
		else
		{
			knownSafePosition = idealClawPosition;
			quaternion2 *= UnityEngine.Quaternion.AngleAxis(20f, axis);
			vector.y += 0.05f * Mathf.Cos(Time.time * 2f);
		}
		clawVisualPos = vector;
		clawVisualRot = quaternion2;
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		FuelPerSecond_Holding = _fps_holding_base * (withUpgrades.Contains(SIUpgradeType.Tentacle_Efficiency) ? 0.8f : 1f);
		FuelPerSecond_Recharging = _fps_recharging_base * (withUpgrades.Contains(SIUpgradeType.Tentacle_Charge_Rate) ? 1.2f : 1f);
		FuelCost_Grab = _grabCost_base * (withUpgrades.Contains(SIUpgradeType.Tentacle_Efficiency) ? 0.8f : 1f);
		FuelCost_JumpSpeed = _jumpCost_base * (withUpgrades.Contains(SIUpgradeType.Tentacle_Efficiency) ? 0.8f : 1f);
		MaxGrabAngle = (withUpgrades.Contains(SIUpgradeType.Tentacle_Power_Claw) ? 180f : _grabAngle_base);
		MaxTentacleJumpSpeed = _jumpSpeed_base;
		_min_grab_dot = Mathf.Cos(MathF.PI / 180f * MaxGrabAngle);
		_lowFuelThreshold = FuelCost_Grab + FuelPerSecond_Holding;
	}

	private long GetStateLong()
	{
		if (isAnchored)
		{
			return 0x4000000000000000L | BitPackUtils.PackAnchoredPosRotForNetwork(clawAnchorPosition, clawAnchorRotation);
		}
		if (isHoldingHand)
		{
			TakeMyHand_HandLink takeMyHand_HandLink = (isLeftHanded ? VRRig.LocalRig.leftHandLink : VRRig.LocalRig.rightHandLink);
			int num = takeMyHand_HandLink.grabbedPlayer?.ActorNumber ?? 0;
			return long.MinValue | (takeMyHand_HandLink.grabbedHandIsLeft ? 2305843009213693952L : 0) | num;
		}
		return 0L;
	}

	private void SetClawAnchor(UnityEngine.Vector3 clawPosition, UnityEngine.Quaternion clawRotation, UnityEngine.Vector3 adjustment)
	{
		if (!isAnchored)
		{
			attachSound.Play();
		}
		hasFailedToGrab = false;
		isAnchored = true;
		clawHoldAdjustment = adjustment;
		clawAnchorPosition = clawPosition;
		clawAnchorRotation = clawRotation;
		clawHoldingVisual.SetActive(value: true);
		clawReleasedVisual.SetActive(value: false);
		if (IsEquippedLocal())
		{
			lastRequestedPlayerPosition = GTPlayer.Instance.transform.position;
			GTPlayer.Instance.SetGravityOverride(this, GravityOverrideFunction);
			hasGravityOverride = true;
			SIPlayer.LocalPlayer.OnKnockback += OnKnockback;
			gameEntity.RequestState(gameEntity.id, GetStateLong());
		}
	}

	private void ClearClawAnchor()
	{
		if (isAnchored || isHoldingHand)
		{
			detachSound.Play();
		}
		hasFailedToGrab = false;
		isAnchored = false;
		clawHoldingVisual.SetActive(value: false);
		clawReleasedVisual.SetActive(value: true);
		if (isHoldingHand && IsEquippedLocal())
		{
			(isLeftHanded ? VRRig.LocalRig.leftHandLink : VRRig.LocalRig.rightHandLink).BreakLink();
		}
		isHoldingHand = false;
		if (hasGravityOverride)
		{
			GTPlayer.Instance.UnsetGravityOverride(this);
			hasGravityOverride = false;
		}
		if (IsEquippedLocal() && !IsBlocked(SIExclusionType.AffectsLocalMovement))
		{
			UnityEngine.Vector3 averagedVelocity = GTPlayer.Instance.AveragedVelocity;
			float a = averagedVelocity.magnitude;
			if (FuelCost_JumpSpeed > 0f)
			{
				a = Mathf.Min(a, currentFuel / FuelCost_JumpSpeed * MaxTentacleJumpSpeed);
			}
			a = Mathf.Min(a, MaxTentacleJumpSpeed);
			currentFuel -= a / MaxTentacleJumpSpeed * FuelCost_JumpSpeed;
			if (averagedVelocity.IsLongerThan(a))
			{
				GTPlayer.Instance.SetVelocity(averagedVelocity.normalized * a);
			}
			else
			{
				GTPlayer.Instance.SetVelocity(averagedVelocity);
			}
			SIPlayer.LocalPlayer.OnKnockback -= OnKnockback;
			gameEntity.RequestState(gameEntity.id, GetStateLong());
		}
	}

	private void OnKnockback(UnityEngine.Vector3 knockbackVector)
	{
		if (isAnchored)
		{
			isGripBroken = true;
			ClearClawAnchor();
		}
	}

	private void GravityOverrideFunction(GTPlayer player)
	{
	}

	private void OnEntityStateChanged(long oldState, long newState)
	{
		if (IsEquippedLocal() || activatedLocally)
		{
			return;
		}
		if ((newState & long.MinValue) != 0L)
		{
			isHoldingHand = true;
			clawHoldingVisual.SetActive(value: true);
			clawReleasedVisual.SetActive(value: false);
			if (GamePlayer.TryGetGamePlayer((int)newState, out var out_gamePlayer))
			{
				heldPlayerCallback.Register(out_gamePlayer.rig, ((newState & 0x2000000000000000L) != 0L) ? out_gamePlayer.rig.leftHandLink : out_gamePlayer.rig.rightHandLink);
			}
		}
		else if (newState != 0L)
		{
			int attachedPlayerActorNr = gameEntity.AttachedPlayerActorNr;
			if (attachedPlayerActorNr >= 1 && GamePlayer.TryGetGamePlayer(attachedPlayerActorNr, out var out_gamePlayer2))
			{
				BitPackUtils.UnpackAnchoredPosRotForNetwork(newState, out_gamePlayer2.rig.transform.position, out var pos, out var rot);
				SetClawAnchor(pos, rot, UnityEngine.Vector3.zero);
				clawVisualPos = clawAnchorPosition;
				clawVisualRot = clawAnchorRotation;
			}
		}
		else
		{
			ClearClawAnchor();
		}
	}

	public override void OnEntityInit()
	{
		currentFuel = 10f;
	}

	public static UnityEngine.Vector3 GetPlaneIntersection(UnityEngine.Vector3 p1Pos, UnityEngine.Vector3 p1Norm, UnityEngine.Vector3 p2Pos, UnityEngine.Vector3 p2Norm, UnityEngine.Vector3 refPoint)
	{
		UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(p1Norm, p2Norm).normalized;
		float num = UnityEngine.Vector3.Dot(p1Pos, p1Norm);
		float num2 = UnityEngine.Vector3.Dot(p2Pos, p2Norm);
		float num3 = UnityEngine.Vector3.Dot(p1Norm, p2Norm);
		float num4 = 1f - num3 * num3;
		if (Mathf.Abs(num4) < 0.001f)
		{
			return refPoint;
		}
		float num5 = (num - num2 * num3) / num4;
		float num6 = (num2 - num * num3) / num4;
		UnityEngine.Vector3 vector = num5 * p1Norm + num6 * p2Norm;
		return vector + UnityEngine.Vector3.Project(refPoint - vector, normalized);
	}

	public static UnityEngine.Vector3 SplineSample(float theta, UnityEngine.Vector3 startDir, UnityEngine.Vector3 endPos, UnityEngine.Vector3 endDir)
	{
		float num = 1f - theta;
		float t = Mathf.Lerp(theta * theta, 1f - num * num, theta);
		UnityEngine.Vector3 a = startDir * theta;
		UnityEngine.Vector3 b = endPos + endDir * num;
		return UnityEngine.Vector3.Lerp(a, b, t);
	}

	private void UpdateTentacle(Material material, Transform tentacle, Transform anchor)
	{
		UnityEngine.Vector3 vector = UnityEngine.Vector3.forward * LengthFactor;
		material.SetVector(tentacleStartDir_HASH, vector);
		UnityEngine.Vector3 vector2 = tentacle.InverseTransformPoint(anchor.position);
		material.SetVector(tentacleEnd_HASH, vector2);
		UnityEngine.Vector3 vector3 = -tentacle.InverseTransformDirection(anchor.forward) * LengthFactor;
		material.SetVector(tentacleEndDir_HASH, vector3);
		UnityEngine.Vector3 vector4 = SplineSample(0.25f, vector, vector2, vector3);
		UnityEngine.Vector3 vector5 = SplineSample(0.26f, vector, vector2, vector3);
		UnityEngine.Vector3 vector6 = SplineSample(0.75f, vector, vector2, vector3);
		UnityEngine.Vector3 vector7 = SplineSample(0.76f, vector, vector2, vector3);
		UnityEngine.Vector3 planeIntersection = GetPlaneIntersection(vector4, (vector5 - vector4).normalized, vector6, (vector7 - vector6).normalized, UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.forward) * vector2.WithZ(0f).normalized);
		material.SetVector(tentacleRingOrigin_HASH, planeIntersection);
	}

	public void CallBack()
	{
		lastCallbackFrame = Time.frameCount;
		if (!isHoldingHand || lastHeldCallbackFrame == lastCallbackFrame)
		{
			claw.transform.localPosition = UnityEngine.Vector3.MoveTowards(claw.transform.localPosition, claw.transform.parent.InverseTransformPoint(clawVisualPos), ClawMaxBlendSpeed * Time.deltaTime);
			claw.transform.localRotation = UnityEngine.Quaternion.RotateTowards(claw.transform.localRotation, claw.transform.parent.InverseTransformRotation(clawVisualRot), ClawMaxRotBlendSpeed * Time.deltaTime);
			UpdateTentacle(tentacleMat, tentacleRenderer.transform, tentacleAnchor);
			if (hasTentacle2)
			{
				UpdateTentacle(tentacleMat2, tentacleRenderer2.transform, tentacleAnchor2);
			}
		}
	}

	private void UpdateTentacleHoldingHandPos(TakeMyHand_HandLink heldHandLink)
	{
		if (!isHoldingHand)
		{
			heldPlayerCallback.Unregister();
			return;
		}
		lastHeldCallbackFrame = Time.frameCount;
		clawVisualPos = heldHandLink.LinkPosition;
		clawVisualRot = heldHandLink.transform.rotation * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.right);
		if (lastHeldCallbackFrame == lastCallbackFrame)
		{
			CallBack();
		}
	}

	public void UpdateRecharge(float dt)
	{
		if (!isAnchored)
		{
			currentFuel = Mathf.Clamp(currentFuel + dt * FuelPerSecond_Recharging, 0f, fuelSize);
		}
	}
}
[RequireComponent(typeof(GameGrabbable))]
[RequireComponent(typeof(GameSnappable))]
[RequireComponent(typeof(GameButtonActivatable))]
public class SIGadgetWristJet : SIGadget, I_SIDisruptable, IEnergyGadget
{
	private enum State
	{
		Unactive,
		Active,
		OutOfFuel
	}

	public enum WristJetType
	{
		Basic,
		Jet,
		Propellor
	}

	private const string preLog = "[SIGadgetWristJet]  ";

	private const string preErr = "[SIGadgetWristJet]  ERROR!!!  ";

	private const string preErrBeta = "[SIGadgetWristJet]  ERROR!!!  (beta only log)  ";

	[SerializeField]
	private AudioSource m_thrustLoopAudioSource;

	private bool _hasThrustLoopAudioSource;

	[SerializeField]
	private SIUpgradeBasedGeneric<AudioClip> m_thrustLoopSoundByUpgrade;

	[SerializeField]
	private float m_thrustLoopAudioFadeInTime = 0.1f;

	[SerializeField]
	private float m_thrustLoopAudioFadeOutTime = 0.5f;

	[SerializeField]
	private float m_thrustLoopSoundVolume = 0.33f;

	[SerializeField]
	private AudioClip m_warnFuelLowSound;

	[SerializeField]
	private float m_warnFuelLowThreshold = 0.5f;

	[SerializeField]
	private float m_warnFuelLowSoundVolume = 0.05f;

	private bool _warnFuelLowSoundWasPlayed;

	[Tooltip("This renderer's material will have the `_EmissionDissolveProgress` property changed to visually communicate current fuel amount.")]
	[SerializeField]
	private GTRendererMatSlot[] m_gaugeMatSlots;

	public WristJetType jetType;

	public GameButtonActivatable buttonActivatable;

	public GameObject inactiveStateVisual;

	private bool _hasInactiveStateVisual;

	[FormerlySerializedAs("jetFlame")]
	public GameObject activeStateVisual;

	private bool _hasActiveStateVisual;

	public float jetForce;

	public float fuelGainRate;

	public float fuelSpendRate;

	public float emptiedCooldown;

	public float gravityNegationPercent;

	public float maxVerticalSpeed;

	public float maxHorizontalSpeed;

	[SerializeField]
	private bool rechargeRequiresFloorTouch;

	[SerializeField]
	private float throttleChangeSpeed = 2f;

	[SerializeField]
	[Tooltip("Minimum proportion of thrust allowed with throttle control.")]
	[Range(0f, 1f)]
	private float minimumBurnRate = 0.33f;

	[SerializeField]
	private Transform[] m_throttleFlapXforms;

	private UnityEngine.Quaternion[] throttleFlapInitialRots;

	[SerializeField]
	private UnityEngine.Quaternion m_throttleFlapMaxRotOffset = UnityEngine.Quaternion.Euler(45f, 0f, 0f);

	private float fuelSize;

	private float currentFuel;

	private State state;

	private GTPlayer gtPlayer;

	private float emptiedCooldownResetProgress;

	private bool _floorTouched;

	private float _maxSqrHorizontalSpeed;

	private const float kFUEL_CAPACITY = 10f;

	private MaterialPropertyBlock _gaugeMatPropBlock;

	private bool _throttleControl;

	private float _throttle;

	private float _currentBurnRate;

	private float _baseFuelSpendRate;

	private float _baseJetForce;

	private float _baseMaxVerticalSpeed;

	private float _baseMaxHorizontalSpeed;

	private bool CanRecharge
	{
		get
		{
			if (!rechargeRequiresFloorTouch || _floorTouched)
			{
				return state == State.Unactive;
			}
			return false;
		}
	}

	public bool UsesEnergy => true;

	public bool IsFull => currentFuel >= fuelSize;

	private void Awake()
	{
		_maxSqrHorizontalSpeed = maxHorizontalSpeed * maxHorizontalSpeed;
		_hasThrustLoopAudioSource = m_thrustLoopAudioSource != null;
		m_warnFuelLowThreshold = ((m_warnFuelLowSound != null) ? m_warnFuelLowThreshold : (-1f));
		_hasInactiveStateVisual = inactiveStateVisual != null;
		_hasActiveStateVisual = activeStateVisual != null;
		_gaugeMatPropBlock = new MaterialPropertyBlock();
		_baseFuelSpendRate = fuelSpendRate;
		_baseJetForce = jetForce;
		_baseMaxVerticalSpeed = maxVerticalSpeed;
		_baseMaxHorizontalSpeed = maxHorizontalSpeed;
		if (m_gaugeMatSlots == null)
		{
			m_gaugeMatSlots = Array.Empty<GTRendererMatSlot>();
		}
		int num = 0;
		for (int i = 0; i < m_gaugeMatSlots.Length; i++)
		{
			if (m_gaugeMatSlots[i].TryInitialize())
			{
				m_gaugeMatSlots[num] = m_gaugeMatSlots[i];
				num++;
			}
		}
		if (num != m_gaugeMatSlots.Length)
		{
			Array.Resize(ref m_gaugeMatSlots, num);
		}
		throttleFlapInitialRots = ((m_throttleFlapXforms != null) ? new UnityEngine.Quaternion[m_throttleFlapXforms.Length] : Array.Empty<UnityEngine.Quaternion>());
		for (int j = 0; j < throttleFlapInitialRots.Length; j++)
		{
			if (m_throttleFlapXforms[j] == null)
			{
				throttleFlapInitialRots = Array.Empty<UnityEngine.Quaternion>();
				UnityEngine.Debug.LogError("[SIGadgetWristJet]  ERROR!!!  Awake: Throttle indicator flaps will not animate because entry is null in " + string.Format("array at `{0}[{1}]`. Path={2}", "m_throttleFlapXforms", j, base.transform.GetPathQ()), this);
				break;
			}
			throttleFlapInitialRots[j] = m_throttleFlapXforms[j].localRotation;
		}
	}

	private void Start()
	{
		gtPlayer = GTPlayer.Instance;
		gameEntity.OnStateChanged += OnEntityStateChanged;
		GameEntity obj = gameEntity;
		obj.OnReleased = (Action)Delegate.Combine(obj.OnReleased, new Action(HandleStopInteraction));
		GameEntity obj2 = gameEntity;
		obj2.OnUnsnapped = (Action)Delegate.Combine(obj2.OnUnsnapped, new Action(HandleStopInteraction));
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (m_warnFuelLowThreshold > 0f)
		{
			m_warnFuelLowSound.LoadAudioData();
		}
	}

	protected override void OnDisable()
	{
		if (m_warnFuelLowThreshold > 0f && m_warnFuelLowSound.loadState != AudioDataLoadState.Unloaded)
		{
			m_warnFuelLowSound.UnloadAudioData();
		}
	}

	protected override void Update()
	{
		base.Update();
		if (_hasThrustLoopAudioSource)
		{
			float target = ((state == State.Active) ? m_thrustLoopSoundVolume : 0f);
			float num = ((state == State.Active) ? m_thrustLoopAudioFadeInTime : m_thrustLoopAudioFadeOutTime);
			m_thrustLoopAudioSource.volume = Mathf.MoveTowards(m_thrustLoopAudioSource.volume, target, 1f / num * Time.unscaledDeltaTime);
		}
	}

	private void FixedUpdate()
	{
		if ((IsEquippedLocal() || activatedLocally) && state == State.Active && currentFuel > 0f && buttonActivatable.CheckInput() && !IsBlocked(SIExclusionType.AffectsLocalMovement))
		{
			gtPlayer.AddForce(-Physics.gravity * (gtPlayer.scale * gravityNegationPercent), ForceMode.Acceleration);
			_ApplyClampedThrust();
		}
	}

	private void HandleStopInteraction()
	{
		if (gameEntity.IsAuthority())
		{
			SetStateAuthority(State.Unactive);
		}
	}

	protected override void OnUpdateAuthority(float dt)
	{
		base.OnUpdateAuthority(dt);
		bool flag = buttonActivatable.CheckInput();
		if (!_floorTouched)
		{
			_floorTouched = gtPlayer.IsGroundedButt || gtPlayer.IsGroundedHand;
		}
		if (_throttleControl)
		{
			UnityEngine.Vector2 joystickInput = GetJoystickInput();
			if (Mathf.Abs(joystickInput.y) > 0.75f && Mathf.Abs(joystickInput.x) < 0.5f)
			{
				_throttle = Mathf.Clamp01(_throttle + joystickInput.y * throttleChangeSpeed * Time.deltaTime);
				_currentBurnRate = Mathf.Lerp(minimumBurnRate, 1f, _throttle);
				UpdateThrottleIndicator();
			}
		}
		switch (state)
		{
		case State.Unactive:
			if (flag && !IsBlocked(SIExclusionType.AffectsLocalMovement))
			{
				SetStateAuthority(State.Active);
			}
			break;
		case State.Active:
			currentFuel = Mathf.Clamp(currentFuel - dt * fuelSpendRate * _currentBurnRate, 0f, fuelSize);
			_floorTouched = false;
			gtPlayer.ThrusterActiveAtFrame = Time.frameCount;
			if (flag && m_warnFuelLowThreshold > 0f)
			{
				float num = currentFuel / fuelSize;
				if (_warnFuelLowSoundWasPlayed && num > m_warnFuelLowThreshold)
				{
					_warnFuelLowSoundWasPlayed = false;
				}
				else if (!_warnFuelLowSoundWasPlayed && num <= m_warnFuelLowThreshold)
				{
					_warnFuelLowSoundWasPlayed = true;
					gameEntity.audioSource.GTPlayOneShot(m_warnFuelLowSound, m_warnFuelLowSoundVolume);
				}
			}
			if (!flag || currentFuel <= 0f)
			{
				SetStateAuthority(State.OutOfFuel);
			}
			break;
		case State.OutOfFuel:
			if (!flag)
			{
				emptiedCooldownResetProgress += dt;
			}
			else if (currentFuel > 0f)
			{
				SetStateAuthority(State.Active);
			}
			if (emptiedCooldownResetProgress > emptiedCooldown)
			{
				emptiedCooldownResetProgress = 0f;
				SetStateAuthority(State.Unactive);
			}
			break;
		}
		float value = currentFuel / fuelSize;
		for (int i = 0; i < m_gaugeMatSlots.Length; i++)
		{
			_gaugeMatPropBlock.SetFloat(ShaderProps._EmissionDissolveProgress, value);
			m_gaugeMatSlots[i].renderer.SetPropertyBlock(_gaugeMatPropBlock, m_gaugeMatSlots[i].slot);
		}
	}

	private void UpdateThrottleIndicator()
	{
		for (int i = 0; i < throttleFlapInitialRots.Length; i++)
		{
			UnityEngine.Quaternion b = throttleFlapInitialRots[i] * m_throttleFlapMaxRotOffset;
			m_throttleFlapXforms[i].localRotation = UnityEngine.Quaternion.Lerp(throttleFlapInitialRots[i], b, _throttle);
		}
	}

	private void _ApplyClampedThrust()
	{
		UnityEngine.Vector3 rigidbodyVelocity = gtPlayer.RigidbodyVelocity;
		float num = jetForce * _currentBurnRate;
		UnityEngine.Vector3 vector = rigidbodyVelocity + base.transform.forward * (num * Time.fixedDeltaTime);
		UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(vector.x, 0f, vector.z);
		if (vector2.sqrMagnitude > _maxSqrHorizontalSpeed)
		{
			float magnitude = new UnityEngine.Vector3(rigidbodyVelocity.x, 0f, rigidbodyVelocity.z).magnitude;
			vector2 = UnityEngine.Vector3.ClampMagnitude(vector2, Mathf.Max(maxHorizontalSpeed, magnitude));
		}
		UnityEngine.Vector3 vector3 = vector2;
		vector3.y = ((vector.y > maxVerticalSpeed) ? Mathf.Max(maxVerticalSpeed, rigidbodyVelocity.y) : vector.y);
		gtPlayer.AddForce(vector3 - rigidbodyVelocity, ForceMode.VelocityChange);
	}

	private void OnEntityStateChanged(long oldState, long newState)
	{
		int num = (int)oldState;
		State state = (State)newState;
		if (num != (int)state)
		{
			SetState(state);
		}
	}

	private void SetStateAuthority(State newState)
	{
		SetState(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetState(State newState)
	{
		if (state == newState)
		{
			return;
		}
		state = newState;
		switch (state)
		{
		case State.Unactive:
			if (_hasInactiveStateVisual)
			{
				inactiveStateVisual.SetActive(value: true);
			}
			if (_hasActiveStateVisual)
			{
				activeStateVisual.SetActive(value: false);
			}
			break;
		case State.Active:
			if (_hasInactiveStateVisual)
			{
				inactiveStateVisual.SetActive(value: false);
			}
			if (_hasActiveStateVisual)
			{
				activeStateVisual.SetActive(value: true);
			}
			break;
		case State.OutOfFuel:
			if (_hasInactiveStateVisual)
			{
				inactiveStateVisual.SetActive(value: true);
			}
			if (_hasActiveStateVisual)
			{
				activeStateVisual.SetActive(value: false);
			}
			break;
		}
	}

	public override void ApplyUpgradeNodes(SIUpgradeSet withUpgrades)
	{
		_throttleControl = withUpgrades.Contains(SIUpgradeType.Thruster_Throttle_Control);
		if (_throttleControl)
		{
			UpdateThrottleIndicator();
		}
		switch (jetType)
		{
		case WristJetType.Jet:
			fuelSpendRate = _baseFuelSpendRate * (withUpgrades.Contains(SIUpgradeType.Thruster_Jet_Duration) ? 0.8f : 1f);
			jetForce = _baseJetForce * (withUpgrades.Contains(SIUpgradeType.Thruster_Jet_Accel) ? 1.2f : 1f);
			break;
		case WristJetType.Propellor:
			fuelSpendRate = _baseFuelSpendRate * (withUpgrades.Contains(SIUpgradeType.Thruster_Prop_Duration) ? 0.8f : 1f);
			maxVerticalSpeed = _baseMaxVerticalSpeed * (withUpgrades.Contains(SIUpgradeType.Thruster_Prop_Speed) ? 1.2f : 1f);
			maxHorizontalSpeed = _baseMaxHorizontalSpeed * (withUpgrades.Contains(SIUpgradeType.Thruster_Prop_Speed) ? 1.2f : 1f);
			break;
		}
		if (_hasThrustLoopAudioSource && m_thrustLoopSoundByUpgrade.TryGetActiveValue(withUpgrades, out var out_value))
		{
			m_thrustLoopAudioSource.clip = out_value;
			m_thrustLoopAudioSource.Play();
		}
	}

	public void Disrupt(float disruptTime)
	{
		emptiedCooldownResetProgress = 0f - disruptTime;
		SetState(State.OutOfFuel);
	}

	public override void OnEntityInit()
	{
		emptiedCooldownResetProgress = 0f;
		if (_hasInactiveStateVisual)
		{
			inactiveStateVisual.SetActive(value: true);
		}
		if (_hasActiveStateVisual)
		{
			activeStateVisual.SetActive(value: false);
		}
		currentFuel = (fuelSize = 10f);
		_throttle = (_currentBurnRate = 1f);
	}

	public void UpdateRecharge(float dt)
	{
		if (CanRecharge)
		{
			currentFuel = Mathf.Clamp(currentFuel + dt * fuelGainRate, 0f, fuelSize);
		}
	}
}
public class SIGameEntityStealthVisibility : MonoBehaviour
{
	[SerializeField]
	private Renderer[] stealthedComponents;

	[SerializeField]
	private float revealRange = 5f;

	[SerializeField]
	private float hideRange = 8f;

	private bool isStealthed;

	private void OnEnable()
	{
		revealRange = Mathf.Min(revealRange, hideRange);
	}

	private void OnDisable()
	{
		SetVisibility(visible: true);
	}

	private void LateUpdate()
	{
		UnityEngine.Vector3 position = GTPlayer.Instance.transform.position;
		float num = UnityEngine.Vector3.SqrMagnitude(base.transform.position - position);
		if (isStealthed && num < revealRange * revealRange)
		{
			SetVisibility(visible: true);
		}
		else if (!isStealthed && num > hideRange * hideRange)
		{
			SetVisibility(visible: false);
		}
	}

	private void SetVisibility(bool visible)
	{
		isStealthed = !visible;
		for (int i = 0; i < stealthedComponents.Length; i++)
		{
			stealthedComponents[i].enabled = visible;
		}
	}
}
[ExecuteAlways]
public class SIPosedTentacleArm : MonoBehaviour
{
	public float LengthFactor = 1.5f;

	public MeshRenderer tentacleRenderer;

	public MeshRenderer tentacleRenderer2;

	public Transform tentacleAnchor;

	public Transform tentacleAnchor2;

	public Material tentacleSharedMaterial;

	private bool _initialized;

	private bool _hasTentacle2;

	private Material _tentacleMat;

	private Material _tentacleMat2;

	private UnityEngine.Vector3 _lastPos;

	private UnityEngine.Vector3 _lastAnchorPos;

	private ShaderHashId tentacleStartDir_HASH = "_TentacleStartDir";

	private ShaderHashId tentacleEnd_HASH = "_TentacleEndPos";

	private ShaderHashId tentacleEndDir_HASH = "_TentacleEndDir";

	private ShaderHashId tentacleRingOrigin_HASH = "_TentacleRingOrigin";

	public void ConfigureFrom(SIGadgetTentacleArm source, MeshRenderer rend1, MeshRenderer rend2, Transform anchor1, Transform anchor2)
	{
		LengthFactor = source.LengthFactor;
		tentacleRenderer = rend1;
		tentacleRenderer2 = rend2;
		tentacleAnchor = anchor1;
		tentacleAnchor2 = anchor2;
		tentacleSharedMaterial = rend1.sharedMaterial;
	}

	private void Start()
	{
		UpdateTentaclePose();
	}

	private bool CanUpdateTentaclePose()
	{
		return true;
	}

	private void EnsureMaterialsInitialized()
	{
		if (!_initialized)
		{
			_tentacleMat = new Material(tentacleSharedMaterial);
			tentacleRenderer.material = _tentacleMat;
			_hasTentacle2 = tentacleRenderer2;
			if (_hasTentacle2)
			{
				_tentacleMat2 = new Material(tentacleSharedMaterial);
				tentacleRenderer2.material = _tentacleMat2;
			}
			_initialized = true;
		}
	}

	private void UpdateTentaclePose()
	{
		if (CanUpdateTentaclePose())
		{
			EnsureMaterialsInitialized();
			UpdateTentacle(_tentacleMat, tentacleRenderer.transform, tentacleAnchor);
			if (_hasTentacle2)
			{
				UpdateTentacle(_tentacleMat2, tentacleRenderer2.transform, tentacleAnchor2);
			}
		}
	}

	private void UpdateTentacle(Material material, Transform tentacle, Transform anchor)
	{
		UnityEngine.Vector3 vector = UnityEngine.Vector3.forward * LengthFactor;
		material.SetVector(tentacleStartDir_HASH, vector);
		UnityEngine.Vector3 vector2 = tentacle.InverseTransformPoint(anchor.position);
		material.SetVector(tentacleEnd_HASH, vector2);
		UnityEngine.Vector3 vector3 = -tentacle.InverseTransformDirection(anchor.forward) * LengthFactor;
		material.SetVector(tentacleEndDir_HASH, vector3);
		UnityEngine.Vector3 vector4 = SIGadgetTentacleArm.SplineSample(0.25f, vector, vector2, vector3);
		UnityEngine.Vector3 vector5 = SIGadgetTentacleArm.SplineSample(0.26f, vector, vector2, vector3);
		UnityEngine.Vector3 vector6 = SIGadgetTentacleArm.SplineSample(0.75f, vector, vector2, vector3);
		UnityEngine.Vector3 vector7 = SIGadgetTentacleArm.SplineSample(0.76f, vector, vector2, vector3);
		UnityEngine.Vector3 planeIntersection = SIGadgetTentacleArm.GetPlaneIntersection(vector4, (vector5 - vector4).normalized, vector6, (vector7 - vector6).normalized, UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.forward) * vector2.WithZ(0f).normalized);
		material.SetVector(tentacleRingOrigin_HASH, planeIntersection);
	}
}
[Serializable]
internal struct SIUpgradeBasedGeneric<T>
{
	public SIUpgradeBasedGenericEntry<T>[] entries;

	public bool TryGetActiveValue(SIUpgradeSet withUpgrades, out T out_value)
	{
		out_value = default(T);
		bool result = false;
		for (int i = 0; i < entries.Length; i++)
		{
			if (entries[i].IsActive(withUpgrades))
			{
				result = true;
				out_value = entries[i].value;
			}
		}
		return result;
	}
}
[Serializable]
internal struct SIUpgradeBasedGenericEntry<T>
{
	public T value;

	[Tooltip("For the objects to become activated, you must match AT LEAST ONE appearRequirement (if there are any), and not match any disappearRequirements.")]
	public SIUpgradeType[] activeRequirements;

	[Tooltip("For the objects to become deactivated, you must match AT LEAST ONE disappearRequirement (if there are any).")]
	public SIUpgradeType[] inactiveRequirements;

	public bool IsActive(SIUpgradeSet withUpgrades)
	{
		bool flag = true;
		if (activeRequirements.Length != 0)
		{
			flag = false;
			SIUpgradeType[] array = activeRequirements;
			foreach (SIUpgradeType upgrade in array)
			{
				if (withUpgrades.Contains(upgrade))
				{
					flag = true;
					break;
				}
			}
		}
		if (flag)
		{
			SIUpgradeType[] array = inactiveRequirements;
			foreach (SIUpgradeType upgrade2 in array)
			{
				if (withUpgrades.Contains(upgrade2))
				{
					flag = false;
					break;
				}
			}
		}
		return flag;
	}
}
