public static class SIUpgradeTypeSystem
{
	public static int GetPageId(this SIUpgradeType self)
	{
		return (int)self / 100;
	}

	public static int GetNodeId(this SIUpgradeType self)
	{
		return (int)self % 100;
	}

	public static SIUpgradeType GetUpgradeType(int pageId, int nodeId)
	{
		return (SIUpgradeType)(pageId * 100 + nodeId);
	}
}
public struct SIUpgradeSet
{
	private int backingBits;

	public void Clear()
	{
		backingBits = 0;
	}

	public SIUpgradeSet(int bits)
	{
		backingBits = bits;
	}

	public int GetBits()
	{
		return backingBits;
	}

	public void SetBits(int bits)
	{
		backingBits = bits;
	}

	public long GetCreateData(SIPlayer player)
	{
		return ((long)backingBits << 32) | player.ActorNr;
	}

	public void Add(SIUpgradeType upgrade)
	{
		backingBits |= 1 << upgrade.GetNodeId();
	}

	public void Add(int nodeId)
	{
		backingBits |= 1 << nodeId;
	}

	public void Remove(SIUpgradeType upgrade)
	{
		backingBits &= ~(1 << upgrade.GetNodeId());
	}

	public bool Contains(SIUpgradeType upgrade)
	{
		return (backingBits & (1 << upgrade.GetNodeId())) != 0;
	}

	public bool ContainsAny(params SIUpgradeType[] upgrades)
	{
		int num = 0;
		foreach (SIUpgradeType self in upgrades)
		{
			num |= 1 << self.GetNodeId();
		}
		return (backingBits & num) != 0;
	}

	public string GetString(SITechTreePageId pageId)
	{
		string text = "";
		int num = backingBits;
		int num2 = 0;
		bool flag = true;
		while (num > 0)
		{
			if ((num & 1) != 0)
			{
				if (!flag)
				{
					text += "|";
				}
				text += SIUpgradeTypeSystem.GetUpgradeType((int)pageId, num2);
				flag = false;
			}
			num >>= 1;
			num2++;
		}
		return text;
	}
}
public class SIUpgradeXformOffsetter : MonoBehaviour
{
	[Serializable]
	public struct SIUpgradeXformOffsetOp
	{
		public SIUpgradeType upgradeType;

		public Transform xform;

		[FormerlySerializedAs("newParent")]
		public Transform targetXform;
	}

	private const string preLog = "[SIUpgradeXformOffsetter]  ";

	private const string preErr = "[SIUpgradeXformOffsetter]  ERROR!!!  ";

	[SerializeField]
	private SIGadget m_superInfectionGadget;

	[SerializeField]
	private SIUpgradeXformOffsetOp[] m_upgradeXformOffsetOps;

	protected void Awake()
	{
		if (m_superInfectionGadget == null)
		{
			UnityEngine.Debug.LogError("[SIUpgradeXformOffsetter]  ERROR!!!  Awake: Disabling component because `m_superInfectionGadget` is null. Path=" + base.transform.GetPathQ(), this);
			base.enabled = false;
			return;
		}
		SIUpgradeXformOffsetOp[] upgradeXformOffsetOps = m_upgradeXformOffsetOps;
		for (int i = 0; i < upgradeXformOffsetOps.Length; i++)
		{
			SIUpgradeXformOffsetOp sIUpgradeXformOffsetOp = upgradeXformOffsetOps[i];
			if (!(sIUpgradeXformOffsetOp.xform != null) && !(sIUpgradeXformOffsetOp.targetXform != null))
			{
				UnityEngine.Debug.LogError("[SIUpgradeXformOffsetter]  ERROR!!!  Awake: Disabling component because null reference in `m_upgradeXformOffsetOps` array. Path=" + base.transform.GetPathQ(), this);
				base.enabled = false;
				break;
			}
		}
	}

	protected void OnEnable()
	{
		SIGadget superInfectionGadget = m_superInfectionGadget;
		superInfectionGadget.OnPostRefreshVisuals = (Action<SIUpgradeSet>)Delegate.Combine(superInfectionGadget.OnPostRefreshVisuals, new Action<SIUpgradeSet>(_HandleGadgetOnPostRefreshVisuals));
	}

	protected void OnDisable()
	{
		SIGadget superInfectionGadget = m_superInfectionGadget;
		superInfectionGadget.OnPostRefreshVisuals = (Action<SIUpgradeSet>)Delegate.Remove(superInfectionGadget.OnPostRefreshVisuals, new Action<SIUpgradeSet>(_HandleGadgetOnPostRefreshVisuals));
	}

	private void _HandleGadgetOnPostRefreshVisuals(SIUpgradeSet upgradeSet)
	{
		for (int i = 0; i < m_upgradeXformOffsetOps.Length; i++)
		{
			SIUpgradeXformOffsetOp sIUpgradeXformOffsetOp = m_upgradeXformOffsetOps[i];
			if (upgradeSet.Contains(sIUpgradeXformOffsetOp.upgradeType))
			{
				sIUpgradeXformOffsetOp.xform.SetLocalPositionAndRotation(sIUpgradeXformOffsetOp.targetXform.localPosition, sIUpgradeXformOffsetOp.targetXform.localRotation);
				sIUpgradeXformOffsetOp.xform.localScale = sIUpgradeXformOffsetOp.targetXform.localScale;
			}
		}
	}
}
public class ThrownGadget : MonoBehaviour
{
	public GameEntity gameEntity;

	private bool isHeldLocal;

	private bool lastThrowerLocal;

	private bool activationButtonLastInput;

	public event Action OnActivated;

	public event Action OnThrown;

	public event Action OnHitSurface;

	private void OnEnable()
	{
		isHeldLocal = false;
		lastThrowerLocal = false;
	}

	public bool IsHeld()
	{
		return gameEntity.heldByActorNumber != -1;
	}

	public bool IsHeldLocal()
	{
		return gameEntity.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	public bool IsHeldByAnother()
	{
		if (IsHeld())
		{
			return !IsHeldLocal();
		}
		return false;
	}

	private bool IsButtonHeld()
	{
		if (!IsHeldLocal())
		{
			return false;
		}
		if (GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			if (out_gamePlayer == null)
			{
				return false;
			}
			int num = out_gamePlayer.FindHandIndex(gameEntity.id);
			if (num == -1)
			{
				return false;
			}
			return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
		}
		return false;
	}

	public void Update()
	{
		bool flag = IsHeldLocal();
		if (flag)
		{
			lastThrowerLocal = true;
			UpdateActivation();
		}
		else if (isHeldLocal)
		{
			this.OnThrown?.Invoke();
		}
		else if (IsHeldByAnother())
		{
			lastThrowerLocal = false;
		}
		isHeldLocal = flag;
	}

	private void UpdateActivation()
	{
		bool flag = IsButtonHeld();
		if (!activationButtonLastInput && flag)
		{
			this.OnActivated?.Invoke();
		}
		activationButtonLastInput = flag;
	}

	public void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (lastThrowerLocal)
		{
			this.OnHitSurface?.Invoke();
		}
	}
}
public class GadgetNode : TechTreeNodeBase
{
	[Input(ShowBackingValue.Unconnected, ConnectionType.Multiple, TypeConstraint.None, false)]
	public Empty input;

	[Output(ShowBackingValue.Never, ConnectionType.Multiple, TypeConstraint.None, false)]
	public Empty output;

	public SIUpgradeType upgradeType;

	public string nickName;

	[TextArea]
	public string description;

	public SIResource.ResourceCost[] nodeCost;

	public bool costOverride;

	[Header("Prefab")]
	public GameEntity unlockedGadgetPrefab;

	public ESuperGameModes excludedGameModes;

	public EAssetReleaseTier releaseTier = (EAssetReleaseTier)(-1);

	private static bool InEditor => NodeInspectorBridge.InNodeEditor;

	public bool IsValid
	{
		get
		{
			EAssetReleaseTier eAssetReleaseTier = releaseTier;
			if (eAssetReleaseTier != EAssetReleaseTier.Disabled)
			{
				return eAssetReleaseTier <= EAssetReleaseTier.PublicRC;
			}
			return false;
		}
	}

	public bool IsDispensableGadget => unlockedGadgetPrefab;

	private bool ShowGadgetPrefab
	{
		get
		{
			if (InEditor)
			{
				return IsDispensableGadget;
			}
			return true;
		}
	}

	private bool ShowExcludedGameModes
	{
		get
		{
			if (InEditor)
			{
				return excludedGameModes != (ESuperGameModes)0;
			}
			return true;
		}
	}

	private bool ShowReleaseTier
	{
		get
		{
			if (InEditor)
			{
				return releaseTier != EAssetReleaseTier.PublicRC;
			}
			return true;
		}
	}

	public void ConfigureFrom(SITechTreeNode sourceNode)
	{
		releaseTier = sourceNode.EdReleaseTier;
		upgradeType = sourceNode.upgradeType;
		nickName = sourceNode.nickName;
		description = sourceNode.description;
		unlockedGadgetPrefab = sourceNode.unlockedGadgetPrefab;
		excludedGameModes = sourceNode.excludedGameModes;
		nodeCost = sourceNode.nodeCost.ToArray();
		costOverride = sourceNode.costOverride;
		base.name = nickName;
	}

	public void AssignParentUpgrades(SIUpgradeType[] prerequisites)
	{
		NodePort port = GetPort("input");
		port.ClearConnections();
		foreach (SIUpgradeType id in prerequisites)
		{
			GadgetNode gadgetNode = graph.nodes.FirstOrDefault(delegate(Node n)
			{
				GadgetNode obj = n as GadgetNode;
				return (object)obj != null && obj.upgradeType == id;
			}) as GadgetNode;
			if (gadgetNode != null)
			{
				NodePort port2 = gadgetNode.GetPort("output");
				port.Connect(port2);
			}
		}
	}

	public List<SIUpgradeType> GetParentUpgradeTypes()
	{
		List<SIUpgradeType> list = new List<SIUpgradeType>();
		foreach (Node item in from n in GetPort("input").GetConnections()
			select n.node)
		{
			if (item is GadgetNode gadgetNode)
			{
				list.Add(gadgetNode.upgradeType);
			}
		}
		return list;
	}

	public SITechTreeNode GenerateTechTreeNode()
	{
		return new SITechTreeNode
		{
			upgradeType = upgradeType,
			nickName = nickName,
			description = description,
			unlockedGadgetPrefab = unlockedGadgetPrefab,
			nodeCost = nodeCost.ToArray(),
			excludedGameModes = excludedGameModes,
			EdReleaseTier = releaseTier,
			parentUpgrades = GetParentUpgradeTypes().ToArray()
		};
	}

	public int GetDepth()
	{
		int num = 0;
		IEnumerable<NodePort> enumerable = GetInputPort("input")?.GetConnections();
		foreach (NodePort item in enumerable ?? Enumerable.Empty<NodePort>())
		{
			if (item.node is GadgetNode gadgetNode)
			{
				num = Mathf.Max(num, gadgetNode.GetDepth() + 1);
			}
		}
		return num;
	}

	public int GetTreeDepth()
	{
		int num = GetDepth();
		foreach (NodePort connection in GetOutputPort("output").GetConnections())
		{
			if (connection.node is GadgetNode gadgetNode)
			{
				num = Mathf.Max(num, gadgetNode.GetTreeDepth());
			}
		}
		return num;
	}

	public List<GadgetNode> GetTreeNodes()
	{
		List<GadgetNode> list = new List<GadgetNode>();
		GetTreeNodes(list);
		return list;
	}

	public void GetTreeNodes(List<GadgetNode> nodes)
	{
		nodes.Add(this);
		foreach (NodePort connection in GetOutputPort("output").GetConnections())
		{
			if (connection.node is GadgetNode gadgetNode)
			{
				gadgetNode.GetTreeNodes(nodes);
			}
		}
	}

	public List<GadgetNode> GetParentNodes()
	{
		List<GadgetNode> list = new List<GadgetNode>();
		foreach (NodePort connection in GetPort("input").GetConnections())
		{
			if (connection.node is GadgetNode item)
			{
				list.Add(item);
			}
		}
		return list;
	}

	public List<GadgetNode> GetChildNodes()
	{
		List<GadgetNode> list = new List<GadgetNode>();
		foreach (NodePort connection in GetOutputPort("output").GetConnections())
		{
			if (connection.node is GadgetNode item)
			{
				list.Add(item);
			}
		}
		return list;
	}

	public int GetTreeWidth()
	{
		List<GadgetNode> childNodes = GetChildNodes();
		if (childNodes.Count == 0)
		{
			return 1;
		}
		int num = 0;
		foreach (GadgetNode item in childNodes)
		{
			num += item.GetTreeWidth();
		}
		return num;
	}

	public bool CostEquals(SIResource.ResourceCost[] cost)
	{
		if (cost.Length != nodeCost.Length)
		{
			return false;
		}
		for (int i = 0; i < cost.Length; i++)
		{
			if (!cost[i].Equals(nodeCost[i]))
			{
				return false;
			}
		}
		return true;
	}
}
