public class GraphNode<T>
{
	public T Value { get; set; }

	public List<GraphNode<T>> Parents { get; } = new List<GraphNode<T>>();

	public List<GraphNode<T>> Children { get; } = new List<GraphNode<T>>();

	public int ChildCount => Children.Count;

	public GraphNode(T value)
	{
		Value = value;
	}

	public GraphNode(T value, GraphNode<T> parent)
	{
		Value = value;
		Parents.Add(parent);
	}

	public int GetSubtreeWidth(int depthLimit = int.MaxValue)
	{
		if (ChildCount == 0 || depthLimit == 0)
		{
			return 1;
		}
		int num = 0;
		foreach (GraphNode<T> child in Children)
		{
			num += child.GetSubtreeWidth(depthLimit - 1);
		}
		return num;
	}

	public GraphNode<T> AddChild(T value)
	{
		return AddChild(new GraphNode<T>(value));
	}

	public GraphNode<T> AddChild(GraphNode<T> child)
	{
		if (child.Parents.Contains(this))
		{
			throw new InvalidOperationException("Cannot add child more than once");
		}
		Children.Add(child);
		child.Parents.Add(this);
		return child;
	}

	public void RemoveChild(GraphNode<T> child)
	{
		if (Children.Remove(child))
		{
			child.Parents.Remove(this);
		}
	}

	public IEnumerable<GraphNode<T>> TraversePreOrder()
	{
		yield return this;
		foreach (GraphNode<T> child in Children)
		{
			foreach (GraphNode<T> item in child.TraversePreOrder())
			{
				yield return item;
			}
		}
	}

	public IEnumerable<GraphNode<T>> TraversePreOrderDistinct(HashSet<GraphNode<T>> visited = null)
	{
		if (visited == null)
		{
			visited = new HashSet<GraphNode<T>>();
		}
		if (visited.Contains(this))
		{
			yield break;
		}
		yield return this;
		visited.Add(this);
		foreach (GraphNode<T> child in Children)
		{
			foreach (GraphNode<T> item in child.TraversePreOrderDistinct(visited))
			{
				yield return item;
			}
		}
	}

	public IEnumerable<GraphNode<T>> TraverseBreadthFirst()
	{
		Queue<GraphNode<T>> queue = new Queue<GraphNode<T>>();
		queue.Enqueue(this);
		while (queue.Count > 0)
		{
			GraphNode<T> current = queue.Dequeue();
			yield return current;
			foreach (GraphNode<T> child in current.Children)
			{
				queue.Enqueue(child);
			}
		}
	}

	public IEnumerable<GraphNode<T>> TraverseBreadthFirstDistinct()
	{
		Queue<GraphNode<T>> queue = new Queue<GraphNode<T>>();
		HashSet<GraphNode<T>> visited = new HashSet<GraphNode<T>>();
		queue.Enqueue(this);
		while (queue.Count > 0)
		{
			GraphNode<T> current = queue.Dequeue();
			if (visited.Contains(current))
			{
				continue;
			}
			visited.Add(current);
			yield return current;
			foreach (GraphNode<T> child in current.Children)
			{
				queue.Enqueue(child);
			}
		}
	}

	public int GetGraphDepth()
	{
		if (Children.Count == 0)
		{
			return 1;
		}
		int num = 0;
		foreach (GraphNode<T> child in Children)
		{
			num = System.Math.Max(num, child.GetGraphDepth());
		}
		return num + 1;
	}

	public int GetNodeDepth()
	{
		if (Parents.Count == 0)
		{
			return 1;
		}
		int num = 0;
		foreach (GraphNode<T> parent in Parents)
		{
			num = System.Math.Max(num, parent.GetNodeDepth());
		}
		return num + 1;
	}
}
public class GrowOnEnable : MonoBehaviour, ITickSystemTick
{
	[SerializeField]
	private float growDuration = 1f;

	[SerializeField]
	private AnimationCurves.EaseType easeType = AnimationCurves.EaseType.EaseOutBack;

	private AnimationCurve _curve;

	private UnityEngine.Vector3 _targetScale;

	private float _lerpVal;

	public bool TickRunning { get; set; }

	private void Awake()
	{
		_targetScale = base.transform.localScale;
	}

	private void OnEnable()
	{
		_lerpVal = 0f;
		_curve = AnimationCurves.GetCurveForEase(easeType);
		UpdateScale();
		TickSystem<object>.AddTickCallback(this);
	}

	private void OnDisable()
	{
		base.transform.localScale = _targetScale;
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void Tick()
	{
		_lerpVal = Mathf.Clamp01(_lerpVal + Time.deltaTime / growDuration);
		UpdateScale();
		if (_lerpVal >= 1f)
		{
			TickSystem<object>.RemoveTickCallback(this);
		}
	}

	private void UpdateScale()
	{
		base.transform.localScale = _targetScale * _curve.Evaluate(_lerpVal);
	}
}
public class Node<T>
{
	public T Value { get; set; }

	public Node<T> Parent { get; private set; }

	public List<Node<T>> Children { get; } = new List<Node<T>>();

	public Node(T value)
	{
		Value = value;
	}

	public Node<T> AddChild(T value)
	{
		Node<T> node = new Node<T>(value)
		{
			Parent = this
		};
		Children.Add(node);
		return node;
	}

	public Node<T> AddChild(Node<T> child)
	{
		child.Parent?.RemoveChild(child);
		Children.Add(child);
		child.Parent = this;
		return child;
	}

	public void RemoveChild(Node<T> child)
	{
		if (Children.Remove(child))
		{
			child.Parent = null;
		}
	}

	public IEnumerable<Node<T>> TraversePreOrder()
	{
		yield return this;
		foreach (Node<T> child in Children)
		{
			foreach (Node<T> item in child.TraversePreOrder())
			{
				yield return item;
			}
		}
	}

	public IEnumerable<Node<T>> TraverseBreadthFirst()
	{
		Queue<Node<T>> queue = new Queue<Node<T>>();
		queue.Enqueue(this);
		while (queue.Count > 0)
		{
			Node<T> current = queue.Dequeue();
			yield return current;
			foreach (Node<T> child in current.Children)
			{
				queue.Enqueue(child);
			}
		}
	}

	public List<Node<T>> GetPath()
	{
		List<Node<T>> list = new List<Node<T>> { this };
		for (Node<T> parent = Parent; parent != null; parent = parent.Parent)
		{
			list.Insert(0, parent);
		}
		return list;
	}
}
