		initialized = true;
		if (parentTerminal == null)
		{
			parentTerminal = GetComponentInParent<SICombinedTerminal>();
		}
		screenData = new Dictionary<TechTreeStationTerminalState, GameObject>();
		screenData.Add(TechTreeStationTerminalState.WaitingForScan, waitingForScanScreen);
		screenData.Add(TechTreeStationTerminalState.TechTreePagesList, pagesListScreen);
		screenData.Add(TechTreeStationTerminalState.TechTreePage, pageScreen);
		screenData.Add(TechTreeStationTerminalState.TechTreeNodePopup, nodePopupScreen);
		screenData.Add(TechTreeStationTerminalState.HelpScreen, techTreeHelpScreen);
		techTreeSO.EnsureInitialized();
		pageButtons = new List<SIGadgetListEntry>();
		techTreePages = new List<SITechTreeUIPage>();
		spriteByType.Add(SIResource.ResourceType.TechPoint, techPointSprite);
		spriteByType.Add(SIResource.ResourceType.StrangeWood, strangeWoodSprite);
		spriteByType.Add(SIResource.ResourceType.WeirdGear, weirdGearSprite);
		spriteByType.Add(SIResource.ResourceType.VibratingSpring, vibratingSpringSprite);
		spriteByType.Add(SIResource.ResourceType.BouncySand, bouncySandSprite);
		spriteByType.Add(SIResource.ResourceType.FloppyMetal, floppyMetalSprite);
		int count = techTreeSO.TreePages.Count;
		for (int i = 0; i < count; i++)
		{
			SITechTreePage sITechTreePage = techTreeSO.TreePages[i];
			if (sITechTreePage.IsValid)
			{
				techTreeIconById.Add(sITechTreePage.pageId, sITechTreePage.icon);
				SIGadgetListEntry sIGadgetListEntry = UnityEngine.Object.Instantiate(pageListEntryPrefab, pageListParent);
				StaticLodManager.TryAddLateInstantiatedMembers(sIGadgetListEntry.gameObject);
				sIGadgetListEntry.Configure(this, sITechTreePage, parentTerminal.zeroZeroImage, parentTerminal.onePointTwoText, SITouchscreenButton.SITouchscreenButtonType.PageSelect, i, -0.07f, count);
				pageButtons.Add(sIGadgetListEntry);
				SITechTreeUIPage sITechTreeUIPage = UnityEngine.Object.Instantiate(pagePrefab, pageParent);
				StaticLodManager.TryAddLateInstantiatedMembers(sITechTreeUIPage.gameObject);
				sITechTreeUIPage.Configure(this, sITechTreePage, parentTerminal.zeroZeroImage, parentTerminal.onePointTwoText);
				techTreePages.Add(sITechTreeUIPage);
			}
		}
		Reset();
	}

	private void _RefreshButtonsUsableState()
	{
		foreach (SIGadgetListEntry pageButton in pageButtons)
		{
			SITechTreePageId id = (SITechTreePageId)pageButton.Id;
			if (techTreeSO.TryGetTreePage(id, out var treePage))
			{
				pageButton.ButtonContainer.SetUsable(treePage.IsAllowed);
			}
		}
	}

	public void Reset()
	{
		currentState = TechTreeStationTerminalState.WaitingForScan;
		nodePopupState = NodePopupState.Description;
		SetScreenVisibility(currentState, currentState);
	}

	public void WriteDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (ActivePlayer == null || !ActivePlayer.gameObject.activeInHierarchy)
		{
			UpdateState(TechTreeStationTerminalState.WaitingForScan, TechTreeStationTerminalState.WaitingForScan);
		}
		stream.SendNext(currentNodeId);
		stream.SendNext(helpScreenIndex);
		stream.SendNext((int)nodePopupState);
		stream.SendNext((int)currentState);
		stream.SendNext((int)lastState);
	}

	public void ReadDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		currentNodeId = (int)stream.ReceiveNext();
		if (CurrentNode == null)
		{
			currentNodeId = (int)CurrentPage.AllNodes[0].Value.upgradeType;
		}
		helpScreenIndex = Mathf.Clamp((int)stream.ReceiveNext(), 0, helpPopupScreens.Length - 1);
		nodePopupState = (NodePopupState)stream.ReceiveNext();
		if (!Enum.IsDefined(typeof(NodePopupState), nodePopupState))
		{
			nodePopupState = NodePopupState.Description;
		}
		TechTreeStationTerminalState techTreeStationTerminalState = (TechTreeStationTerminalState)stream.ReceiveNext();
		TechTreeStationTerminalState techTreeStationTerminalState2 = (TechTreeStationTerminalState)stream.ReceiveNext();
		if (ActivePlayer == null || !ActivePlayer.gameObject.activeInHierarchy || !Enum.IsDefined(typeof(TechTreeStationTerminalState), techTreeStationTerminalState) || !Enum.IsDefined(typeof(TechTreeStationTerminalState), techTreeStationTerminalState2))
		{
			UpdateState(TechTreeStationTerminalState.WaitingForScan, TechTreeStationTerminalState.WaitingForScan);
		}
		else
		{
			UpdateState(techTreeStationTerminalState, techTreeStationTerminalState2);
		}
	}

	public void ZoneDataSerializeWrite(BinaryWriter writer)
	{
		writer.Write(currentNodeId);
		writer.Write(helpScreenIndex);
		writer.Write((int)nodePopupState);
		writer.Write((int)currentState);
		writer.Write((int)lastState);
	}

	public void ZoneDataSerializeRead(BinaryReader reader)
	{
		currentNodeId = reader.ReadInt32();
		if (CurrentNode == null || !Enum.IsDefined(typeof(SIUpgradeType), CurrentNode.upgradeType))
		{
			GTDev.LogError($"SITechTreeStation.ZoneDataSerializeRead: Invalid currentNodeId {currentNodeId} for page {parentTerminal.ActivePage}. Falling back to first node.");
			currentNodeId = (int)CurrentPage.AllNodes[0].Value.upgradeType;
		}
		helpScreenIndex = Mathf.Clamp(reader.ReadInt32(), 0, helpPopupScreens.Length - 1);
		nodePopupState = (NodePopupState)reader.ReadInt32();
		if (!Enum.IsDefined(typeof(NodePopupState), nodePopupState))
		{
			nodePopupState = NodePopupState.Description;
		}
		TechTreeStationTerminalState techTreeStationTerminalState = (TechTreeStationTerminalState)reader.ReadInt32();
		TechTreeStationTerminalState techTreeStationTerminalState2 = (TechTreeStationTerminalState)reader.ReadInt32();
		if (ActivePlayer == null || !ActivePlayer.gameObject.activeInHierarchy || !Enum.IsDefined(typeof(TechTreeStationTerminalState), techTreeStationTerminalState) || !Enum.IsDefined(typeof(TechTreeStationTerminalState), techTreeStationTerminalState2))
		{
			UpdateState(TechTreeStationTerminalState.WaitingForScan, TechTreeStationTerminalState.WaitingForScan);
		}
		else
		{
			UpdateState(techTreeStationTerminalState, techTreeStationTerminalState2);
		}
	}

	public void UpdateState(TechTreeStationTerminalState newState, TechTreeStationTerminalState newLastState)
	{
		if (!IsPopupState(newLastState))
		{
			currentState = newLastState;
		}
		UpdateState(newState);
	}

	public void UpdateState(TechTreeStationTerminalState newState)
	{
		if (!IsPopupState(currentState))
		{
			lastState = currentState;
		}
		currentState = newState;
		SetScreenVisibility(currentState, lastState);
		switch (currentState)
		{
		case TechTreeStationTerminalState.TechTreePagesList:
			playerNameText.text = ActivePlayerName;
			screenDescriptionText.text = "TECH TREE PAGES";
			break;
		case TechTreeStationTerminalState.TechTreePage:
		{
			playerNameText.text = ActivePlayerName;
			UpdateNodeData(ActivePlayer);
			screenDescriptionText.text = techTreeSO.GetTreePage((SITechTreePageId)parentTerminal.ActivePage)?.nickName;
			foreach (SIGadgetListEntry pageButton in pageButtons)
			{
				pageButton.selectionIndicator.SetActive(pageButton.Id == parentTerminal.ActivePage);
			}
			foreach (SITechTreeUIPage techTreePage in techTreePages)
			{
				techTreePage.gameObject.SetActive(techTreePage.id == (SITechTreePageId)parentTerminal.ActivePage);
			}
			techTreeIconById.TryGetValue((SITechTreePageId)parentTerminal.ActivePage, out var value);
			techTreeIcon.sprite = value;
			break;
		}
		case TechTreeStationTerminalState.TechTreeNodePopup:
			switch (nodePopupState)
			{
			case NodePopupState.Description:
				nodeNameText.text = CurrentNode.nickName;
				nodeDescriptionText.text = CurrentNode.description;
				if (ActivePlayer.NodeResearched(CurrentNode.upgradeType))
				{
					nodeResearched.SetActive(value: true);
					nodeLocked.SetActive(value: false);
					nodeAvailable.SetActive(value: false);
					nodeResearchButton.SetActive(value: false);
					canAffordNode.SetActive(value: false);
					cantAffordNode.SetActive(value: false);
				}
				else if (ActivePlayer.NodeParentsUnlocked(CurrentNode.upgradeType))
				{
					nodeResearched.SetActive(value: false);
					nodeLocked.SetActive(value: false);
					nodeAvailable.SetActive(value: true);
					nodeResearchButton.SetActive(value: true);
					bool flag = ActivePlayer.PlayerCanAffordNode(CurrentNode);
					canAffordNode.SetActive(flag);
					cantAffordNode.SetActive(!flag);
				}
				else
				{
					nodeResearched.SetActive(value: false);
					nodeAvailable.SetActive(value: false);
					nodeLocked.SetActive(value: true);
					nodeResearchButton.SetActive(value: false);
					canAffordNode.SetActive(value: false);
					cantAffordNode.SetActive(value: false);
				}
				nodeResourceTypeText.text = FormattedCurrentResourceTypesForNode(CurrentNode);
				nodeResourceCostText.text = FormattedResearchCost(CurrentNode);
				playerCurrentResourceAmountsText.text = FormattedCurrentResourceAmountsForNode(CurrentNode);
				break;
			case NodePopupState.Loading:
				if (ActivePlayer.NodeResearched(CurrentNode.upgradeType))
				{
					nodePopupState = NodePopupState.Success;
					nodeNameResearchMessageText.text = "SUCCESSFULLY UNLOCKED TECH NODE!";
				}
				else
				{
					nodeNameResearchMessageText.text = "ATTEMPTING TO UNLOCK NODE\n\nLOADING . . .";
				}
				break;
			case NodePopupState.Success:
				nodeNameResearchMessageText.text = "SUCCESSFULLY UNLOCKED TECH NODE!";
				break;
			case NodePopupState.NotEnoughResources:
				nodeNameResearchMessageText.text = "NOT ENOUGH RESOURCES TO UNLOCK NODE! GATHER MORE AND TRY AGAIN!";
				break;
			}
			UpdateNodePopupPage();
			break;
		case TechTreeStationTerminalState.HelpScreen:
			UpdateHelpButtonPage(helpScreenIndex);
			break;
		case TechTreeStationTerminalState.WaitingForScan:
			break;
		}
	}

	public void SetScreenVisibility(TechTreeStationTerminalState currentState, TechTreeStationTerminalState lastState)
	{
		bool flag = IsPopupState(currentState);
		background.color = ((currentState == TechTreeStationTerminalState.WaitingForScan) ? Color.white : ((ActivePlayer != null && ActivePlayer.gamePlayer.IsLocal()) ? active : notActive));
		foreach (TechTreeStationTerminalState key in screenData.Keys)
		{
			if (key == TechTreeStationTerminalState.TechTreePagesList)
			{
				screenData[key].SetActive(currentState != TechTreeStationTerminalState.WaitingForScan);
				continue;
			}
			bool flag2 = key == currentState || (flag && key == lastState);
			if (screenData[key].activeSelf != flag2)
			{
				screenData[key].SetActive(flag2);
			}
		}
		if (popupScreen.activeSelf != flag)
		{
			popupScreen.SetActive(flag);
		}
		bool flag3 = currentState != TechTreeStationTerminalState.WaitingForScan;
		screenDescriptionText.gameObject.SetActive(flag3);
		playerNameText.gameObject.SetActive(flag3);
		SetNonPopupButtonsEnabled(!flag);
	}

	public bool IsPopupState(TechTreeStationTerminalState state)
	{
		if (state != TechTreeStationTerminalState.TechTreeNodePopup)
		{
			return state == TechTreeStationTerminalState.HelpScreen;
		}
		return true;
	}

	public void PlayerHandScanned(int actorNr)
	{
		if (!IsAuthority)
		{
			parentTerminal.PlayerHandScanned(actorNr);
		}
		else
		{
			UpdateState(TechTreeStationTerminalState.TechTreePage);
		}
	}

	public void AddButton(SITouchscreenButton button, bool isPopupButton = false)
	{
		if (!isPopupButton)
		{
			_nonPopupButtonColliders.Add(button.GetComponent<Collider>());
		}
	}

	public void TouchscreenButtonPressed(SITouchscreenButton.SITouchscreenButtonType buttonType, int data, int actorNr)
	{
		if (actorNr == SIPlayer.LocalPlayer.ActorNr && (ActivePlayer == null || ActivePlayer != SIPlayer.LocalPlayer))
		{
			parentTerminal.PlayWrongPlayerBuzz(uiCenter);
		}
		else
		{
			soundBankPlayer.Play();
		}
		if (actorNr == SIPlayer.LocalPlayer.ActorNr && ActivePlayer == SIPlayer.LocalPlayer && currentState == TechTreeStationTerminalState.TechTreeNodePopup && nodePopupState == NodePopupState.Description && buttonType == SITouchscreenButton.SITouchscreenButtonType.Research && !SIPlayer.LocalPlayer.NodeResearched(CurrentNode.upgradeType) && SIPlayer.LocalPlayer.NodeParentsUnlocked(CurrentNode.upgradeType))
		{
			SIProgression.Instance.TryUnlock(CurrentNode.upgradeType);
		}
		if (!IsAuthority)
		{
			parentTerminal.TouchscreenButtonPressed(buttonType, data, actorNr, SICombinedTerminal.TerminalSubFunction.TechTree);
		}
		else
		{
			if (ActivePlayer == null || actorNr != ActivePlayer.ActorNr)
			{
				return;
			}
			soundBankPlayer.Play();
			if (buttonType == SITouchscreenButton.SITouchscreenButtonType.PageSelect)
			{
				parentTerminal.SetActivePage(data);
				UpdateState(TechTreeStationTerminalState.TechTreePage);
				return;
			}
			switch (currentState)
			{
			case TechTreeStationTerminalState.WaitingForScan:
				if (buttonType == SITouchscreenButton.SITouchscreenButtonType.Help)
				{
					UpdateState(TechTreeStationTerminalState.HelpScreen);
				}
				break;
			case TechTreeStationTerminalState.TechTreePagesList:
				if (buttonType == SITouchscreenButton.SITouchscreenButtonType.Help)
				{
					UpdateState(TechTreeStationTerminalState.HelpScreen);
				}
				if (buttonType == SITouchscreenButton.SITouchscreenButtonType.Select)
				{
					parentTerminal.SetActivePage(data);
					UpdateState(TechTreeStationTerminalState.TechTreePage);
				}
				break;
			case TechTreeStationTerminalState.TechTreePage:
				switch (buttonType)
				{
				case SITouchscreenButton.SITouchscreenButtonType.Select:
					currentNodeId = data;
					UpdateState(TechTreeStationTerminalState.TechTreeNodePopup);
					break;
				case SITouchscreenButton.SITouchscreenButtonType.Back:
					UpdateState(TechTreeStationTerminalState.TechTreePagesList);
					break;
				case SITouchscreenButton.SITouchscreenButtonType.Help:
					UpdateState(TechTreeStationTerminalState.HelpScreen);
					break;
				}
				break;
			case TechTreeStationTerminalState.TechTreeNodePopup:
				if (nodePopupState == NodePopupState.Description)
				{
					if (buttonType == SITouchscreenButton.SITouchscreenButtonType.Exit)
					{
						UpdateState(lastState);
					}
					if (buttonType == SITouchscreenButton.SITouchscreenButtonType.Research)
					{
						if (ActivePlayer.PlayerCanAffordNode(CurrentNode))
						{
							nodePopupState = NodePopupState.Loading;
						}
						else
						{
							nodePopupState = NodePopupState.NotEnoughResources;
						}
						UpdateState(TechTreeStationTerminalState.TechTreeNodePopup);
					}
				}
				else if (buttonType == SITouchscreenButton.SITouchscreenButtonType.Back)
				{
					nodePopupState = NodePopupState.Description;
					UpdateState(TechTreeStationTerminalState.TechTreeNodePopup);
				}
				break;
			case TechTreeStationTerminalState.HelpScreen:
				switch (buttonType)
				{
				case SITouchscreenButton.SITouchscreenButtonType.Exit:
					helpScreenIndex = 0;
					UpdateState(lastState);
					break;
				case SITouchscreenButton.SITouchscreenButtonType.Next:
					helpScreenIndex = Mathf.Clamp(helpScreenIndex + 1, 0, helpPopupScreens.Length - 1);
					UpdateHelpButtonPage(helpScreenIndex);
					break;
				case SITouchscreenButton.SITouchscreenButtonType.Back:
					helpScreenIndex = Mathf.Clamp(helpScreenIndex - 1, 0, helpPopupScreens.Length - 1);
					UpdateHelpButtonPage(helpScreenIndex);
					break;
				}
				break;
			}
		}
	}

	public void TouchscreenToggleButtonPressed(SITouchscreenButton.SITouchscreenButtonType buttonType, int data, int actorNr, bool isToggledOn)
	{
	}

	public void UpdateHelpButtonPage(int helpButtonPageIndex)
	{
		for (int i = 0; i < helpPopupScreens.Length; i++)
		{
			helpPopupScreens[i].SetActive(i == helpButtonPageIndex);
		}
	}

	public void UpdateNodePopupPage()
	{
		int num = ((nodePopupState != NodePopupState.Description) ? 1 : 0);
		if (nodePopupScreens[0].activeSelf != (num == 0))
		{
			nodePopupScreens[0].SetActive(num == 0);
		}
		if (nodePopupScreens[1].activeSelf != (num == 1))
		{
			nodePopupScreens[1].SetActive(num == 1);
		}
	}

	public void UpdateNodeData(SIPlayer player)
	{
		if (player == null)
		{
			for (int i = 0; i < techTreePages.Count; i++)
			{
				techTreePages[i].PopulateDefaultNodeData();
			}
		}
		else
		{
			for (int j = 0; j < techTreePages.Count; j++)
			{
				techTreePages[j].PopulatePlayerNodeData(player);
			}
		}
	}

	public string FormattedResearchCost(SITechTreeNode node)
	{
		if (SIProgression.Instance.GetOnlineNode(node.upgradeType, out var node2))
		{
			string text = "";
			text = text + node2.costs[SIResource.ResourceType.TechPoint] + "\n";
			{
				foreach (KeyValuePair<SIResource.ResourceType, int> cost in node2.costs)
				{
					if (cost.Key != SIResource.ResourceType.TechPoint)
					{
						return text + cost.Value;
					}
				}
				return text;
			}
		}
		return string.Join("\n", node.nodeCost.Select((SIResource.ResourceCost c) => c.amount));
	}

	public string FormattedCurrentResourceAmountsForNode(SITechTreeNode node)
	{
		string text = "";
		if (SIProgression.Instance.GetOnlineNode(node.upgradeType, out var node2))
		{
			text = text + ActivePlayer.CurrentProgression.resourceArray[0] + "\n";
			foreach (KeyValuePair<SIResource.ResourceType, int> cost in node2.costs)
			{
				if (cost.Key != SIResource.ResourceType.TechPoint)
				{
					text = text + ActivePlayer.CurrentProgression.resourceArray[(int)cost.Key] + "\n";
				}
			}
		}
		else
		{
			for (int i = 0; i < node.nodeCost.Length; i++)
			{
				text = text + ActivePlayer.CurrentProgression.resourceArray[(int)node.nodeCost[i].type] + "\n";
			}
		}
		return text;
	}

	public string FormattedCurrentResourceTypesForNode(SITechTreeNode node)
	{
		string text = "";
		if (SIProgression.Instance.GetOnlineNode(node.upgradeType, out var node2))
		{
			text = text + SIResource.ResourceType.TechPoint.ToString().ToUpperInvariant() + "\n";
			foreach (KeyValuePair<SIResource.ResourceType, int> cost in node2.costs)
			{
				if (cost.Key != SIResource.ResourceType.TechPoint)
				{
					text = text + cost.Key.ToString().ToUpperInvariant() + "\n";
					resourceCost.sprite = spriteByType[cost.Key];
				}
			}
		}
		else
		{
			for (int i = 0; i < node.nodeCost.Length; i++)
			{
				text = text + node.nodeCost[i].type.ToString().ToUpperInvariant() + "\n";
			}
		}
		return text;
	}

	private void OnProgressionUpdate()
	{
		UpdateNodeData(ActivePlayer);
		UpdateState(currentState);
	}

	private void OnProgressionUpdateNode(SIUpgradeType type)
	{
		OnProgressionUpdate();
	}

	public void SetActivePage()
	{
		if (CurrentNode == null)
		{
			currentNodeId = CurrentPage.AllNodes[0].Value.upgradeType.GetNodeId();
		}
		if (ActivePlayer != null)
		{
			UpdateState(TechTreeStationTerminalState.TechTreePage);
		}
		else
		{
			UpdateState(TechTreeStationTerminalState.WaitingForScan);
		}
	}

	public bool IsValidPage(int pageId)
	{
		if (pageId < 0)
		{
			return false;
		}
		foreach (SITechTreeUIPage techTreePage in techTreePages)
		{
			if (techTreePage.id == (SITechTreePageId)pageId)
			{
				return true;
			}
		}
		return false;
	}
}
public class SITechTreeUINode : MonoBehaviour
{
	public SIUpgradeType upgradeType;

	public TextMeshProUGUI nodeNickName;

	public MeshRenderer circle;

	public MeshRenderer triangle;

	public SITouchscreenButton button;

	public Material greenMat;

	public Material redMat;

	public Material blackMat;

	public ObjectHierarchyFlattener imageFlattener;

	public ObjectHierarchyFlattener textFlattener;

	private GraphNode<SITechTreeNode> _node;

	public List<Image> UpgradeLines { get; } = new List<Image>();

	public List<SITechTreeUINode> Parents { get; } = new List<SITechTreeUINode>();

	public List<SITechTreeUINode> Children { get; } = new List<SITechTreeUINode>();

	public bool IsConfigured => _node != null;

	public void SetTechTreeNode(SITechTreeStation techTreeStation, SIUpgradeType nodeUpgradeType)
	{
		if (!techTreeStation.techTreeSO.TryGetNode(nodeUpgradeType, out _node))
		{
			UnityEngine.Debug.LogError($"Node {nodeUpgradeType} doesn't exist in tree.  Disabling.");
			base.gameObject.SetActive(value: false);
			return;
		}
		upgradeType = nodeUpgradeType;
		float num = Mathf.Min(GetMaxWordLength(_node.Value.nickName), 14) * 4;
		UnityEngine.Vector2 sizeDelta = nodeNickName.rectTransform.sizeDelta;
		if (sizeDelta.x < num)
		{
			sizeDelta.x = num;
			nodeNickName.rectTransform.sizeDelta = sizeDelta;
		}
		string text = (nodeNickName.text = _node.Value.nickName);
		base.name = text;
		button.data = _node.Value.upgradeType.GetNodeId();
		button.buttonPressed.RemoveAllListeners();
		button.buttonPressed.AddListener(techTreeStation.TouchscreenButtonPressed);
		SetGadgetUnlockNode(_node.Value.unlockedGadgetPrefab);
	}

	public void SetNodeLockStateColor(Color color)
	{
		if (color == Color.red)
		{
			circle.sharedMaterial = redMat;
		}
		else if (color == Color.black)
		{
			circle.sharedMaterial = blackMat;
		}
		else if (color == Color.green)
		{
			circle.sharedMaterial = greenMat;
		}
		foreach (Image upgradeLine in UpgradeLines)
		{
			upgradeLine.color = color;
		}
	}

	private void SetGadgetUnlockNode(bool isUnlockNode)
	{
		triangle.gameObject.SetActive(isUnlockNode);
	}

	private int GetMaxWordLength(string text)
	{
		string[] array = text.Split(' ');
		int num = 0;
		string[] array2 = array;
		foreach (string text2 in array2)
		{
			if (text2.Length > num)
			{
				num = text2.Length;
			}
		}
		return num;
	}

	public void AdjustPosition(UnityEngine.Vector3 positionOffset)
	{
		base.transform.localPosition += positionOffset;
		foreach (SITechTreeUINode child in Children)
		{
			child.AdjustPosition(positionOffset);
		}
	}
}
public class SITechTreeUIPage : MonoBehaviour
{
	[SerializeField]
	private SITechTreeUINode nodePrefab;

	[SerializeField]
	private Image upgradeLinePrefab;

	[SerializeField]
	private RectTransform nodeContainer;

	public SITechTreePageId id;

	private readonly List<SITechTreeUINode> _pageNodes = new List<SITechTreeUINode>();

	public void Configure(SITechTreeStation techTreeStation, SITechTreePage treePage, Transform imageTarget, Transform textTarget)
	{
		base.name = treePage.nickName;
		id = treePage.pageId;
		int count = treePage.Roots.Count;
		UnityEngine.Vector3 vector = new UnityEngine.Vector3(0f, nodeContainer.rect.min.y + 20f, 0f);
		if (count < 2)
		{
			float num = treePage.Roots[0].GetSubtreeWidth() * 50 + 100;
			if (num > nodeContainer.rect.width)
			{
				float num2 = (nodeContainer.rect.width - num) / 2f;
				vector.x += num2;
			}
		}
		float num3 = nodeContainer.rect.width / (float)count;
		for (int i = 0; i < count; i++)
		{
			float x = ((count < 2) ? 0f : (-22f + (0f - num3) * (float)(count - 1) / 2f + num3 * (float)i));
			AddNodes(null, treePage.Roots[i], vector + new UnityEngine.Vector3(x, 0f, 0f));
		}
		foreach (SITechTreeUINode pageNode in _pageNodes)
		{
			AddUpgradeLines(pageNode);
			pageNode.SetNodeLockStateColor(Color.black);
			techTreeStation.AddButton(pageNode.button);
		}
		void AddNodes(GraphNode<SITechTreeNode> parent, GraphNode<SITechTreeNode> node, UnityEngine.Vector3 position)
		{
			float num4 = ((parent == null) ? 40 : 25);
			int num5 = ((parent == null) ? 10 : 5);
			List<float> subtreeWidths = new List<float>();
			float num6 = 50f;
			foreach (GraphNode<SITechTreeNode> child in node.Children)
			{
				subtreeWidths.Add(num6 * (float)child.GetSubtreeWidth());
			}
			SITechTreeUINode sITechTreeUINode = GetOrInstantiateUINode(node.Value.upgradeType);
			if (parent != null)
			{
				SITechTreeUINode uINode = GetUINode(parent.Value.upgradeType);
				sITechTreeUINode.Parents.Add(uINode);
				uINode.Children.Add(sITechTreeUINode);
			}
			if (sITechTreeUINode.IsConfigured)
			{
				if (sITechTreeUINode.Parents.Count > 1)
				{
					float num7 = 0f;
					foreach (SITechTreeUINode parent in sITechTreeUINode.Parents)
					{
						num7 += parent.transform.localPosition.x;
					}
					position.x = num7 / (float)sITechTreeUINode.Parents.Count;
				}
				position.y = Mathf.Max(sITechTreeUINode.transform.localPosition.y, position.y);
				sITechTreeUINode.AdjustPosition(position - sITechTreeUINode.transform.localPosition);
			}
			else
			{
				sITechTreeUINode.transform.localPosition = position;
				sITechTreeUINode.SetTechTreeNode(techTreeStation, node.Value.upgradeType);
				_pageNodes.Add(sITechTreeUINode);
				int count2 = node.Children.Count;
				float num8 = 0f;
				if (count2 > 1)
				{
					int index = 0;
					for (int j = 0; j < count2; j++)
					{
						float num9 = subtreeWidths[index];
						float num10 = ((j == 0 || j == count2 - 1) ? (num9 / 2f) : num9);
						num8 -= num10 / 2f;
					}
				}
				for (int k = 0; k < count2; k++)
				{
					float y = num4 + (float)((k + 1) % 2 * num5);
					GraphNode<SITechTreeNode> node2 = node.Children[k];
					UnityEngine.Vector3 position2 = position + new UnityEngine.Vector3(num8, y, 0f);
					AddNodes(node, node2, position2);
					num8 += GetSpacing(k, count2);
				}
				sITechTreeUINode.imageFlattener.overrideParentTransform = imageTarget;
				sITechTreeUINode.textFlattener.overrideParentTransform = textTarget;
				sITechTreeUINode.imageFlattener.enabled = true;
				sITechTreeUINode.textFlattener.enabled = true;
			}
			float GetSpacing(int num12, int childCount)
			{
				int num11 = num12 + 1;
				float num13 = ((num12 >= 0 && num12 < childCount) ? subtreeWidths[num12] : 0f);
				float num14 = ((num11 >= 0 && num11 < childCount) ? subtreeWidths[num11] : 0f);
				return (num13 + num14) / 2f;
			}
		}
		void AddUpgradeLines(SITechTreeUINode uiNode)
		{
			foreach (SITechTreeUINode parent2 in uiNode.Parents)
			{
				UnityEngine.Vector3 localPosition = parent2.transform.localPosition;
				UnityEngine.Vector3 vector2 = uiNode.transform.localPosition - localPosition;
				UnityEngine.Vector3 normalized = vector2.normalized;
				Image image = UnityEngine.Object.Instantiate(upgradeLinePrefab, nodeContainer);
				ObjectHierarchyFlattener component = image.GetComponent<ObjectHierarchyFlattener>();
				image.transform.SetSiblingIndex(0);
				uiNode.UpgradeLines.Add(image);
				RectTransform rectTransform = image.rectTransform;
				rectTransform.localPosition = localPosition + vector2 * 0.5f;
				rectTransform.localRotation = UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.up, normalized);
				UnityEngine.Vector2 sizeDelta = rectTransform.sizeDelta;
				sizeDelta.y = vector2.magnitude - 20f;
				rectTransform.sizeDelta = sizeDelta;
				component.overrideParentTransform = imageTarget;
				component.enabled = true;
			}
		}
		SITechTreeUINode GetOrInstantiateUINode(SIUpgradeType upgradeType)
		{
			SITechTreeUINode uINode = GetUINode(upgradeType);
			if ((bool)uINode)
			{
				return uINode;
			}
			return UnityEngine.Object.Instantiate(nodePrefab, nodeContainer);
		}
	}

	private SITechTreeUINode GetUINode(SIUpgradeType upgradeType)
	{
		foreach (SITechTreeUINode pageNode in _pageNodes)
		{
			if (pageNode.upgradeType == upgradeType)
			{
				return pageNode;
			}
		}
		return null;
	}

	public void PopulateDefaultNodeData()
	{
		foreach (SITechTreeUINode pageNode in _pageNodes)
		{
			pageNode.SetNodeLockStateColor(Color.black);
		}
	}

	public void PopulatePlayerNodeData(SIPlayer player)
	{
		foreach (SITechTreeUINode pageNode in _pageNodes)
		{
			Color nodeLockStateColor = (player.NodeResearched(pageNode.upgradeType) ? Color.green : (player.NodeParentsUnlocked(pageNode.upgradeType) ? Color.red : Color.black));
			pageNode.SetNodeLockStateColor(nodeLockStateColor);
		}
	}
}
public class SITouchscreen : MonoBehaviour
{
	public Transform controllingTransform;

	public float lastTouched;

	public UnityEngine.Vector3 lastPosition;

	private Dictionary<Collider, GorillaTriggerColliderHandIndicator> fingerTouchDict = new Dictionary<Collider, GorillaTriggerColliderHandIndicator>();

	private HashSet<Collider> notFingerTouchDict = new HashSet<Collider>();

	private void OnTriggerEnter(Collider other)
	{
		OnTriggerStay(other);
	}

	private void OnTriggerStay(Collider other)
	{
		Transform indicator = GetIndicator(other);
		if (indicator != null)
		{
			controllingTransform = indicator;
			lastTouched = Time.time;
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (!(controllingTransform == null) && !(GetIndicator(other) != controllingTransform))
		{
			controllingTransform = null;
		}
	}

	private Transform GetIndicator(Collider other)
	{
		if (notFingerTouchDict.Contains(other))
		{
			return null;
		}
		if (!fingerTouchDict.TryGetValue(other, out var value))
		{
			value = other.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
			if (value == null)
			{
				notFingerTouchDict.Add(other);
				return null;
			}
			fingerTouchDict.Add(other, value);
		}
		return value.transform;
	}
}
public class SITouchscreenButton : MonoBehaviour, IClickable
{
	public enum ButtonMode
	{
		Normal,
		Toggle
	}

	public enum SITouchscreenButtonType
	{
		Back,
		Next,
		Exit,
		Help,
		Select,
		Dispense,
		Research,
		Collect,
		Debug,
		PageSelect,
		Purchase,
		Confirm,
		Cancel,
		OverrideFailure,
		None,
		Subscribe
	}

	public ButtonMode buttonMode;

	public SITouchscreenButtonType buttonType;

	public int data;

	[SerializeField]
	private AudioClip _pressSound;

	[SerializeField]
	private float _pressSoundVolume = 0.1f;

	[SerializeField]
	private bool _isToggledOn;

	[SerializeField]
	private bool _startToggledOn;

	public UnityEvent<SITouchscreenButtonType, int, int> buttonPressed;

	public UnityEvent<SITouchscreenButtonType, int, int, bool> buttonToggled;

	private SIScreenRegion _screenRegion;

	private const float DEBOUNCE_TIME = 0.2f;

	private float _enableTime;

	[NonSerialized]
	public bool isUsable = true;

	private bool IsReady
	{
		get
		{
			bool flag = Time.time - _enableTime >= 0.2f;
			if ((bool)_screenRegion)
			{
				flag = flag && !_screenRegion.HasPressedButton;
			}
			return flag;
		}
	}

	public bool IsToggledOn => _isToggledOn;

	private void Awake()
	{
		ITouchScreenStation componentInParent = GetComponentInParent<ITouchScreenStation>();
		if (componentInParent != null)
		{
			_screenRegion = componentInParent.ScreenRegion;
		}
		if (buttonMode == ButtonMode.Toggle)
		{
			_isToggledOn = _startToggledOn;
		}
	}

	private void OnEnable()
	{
		_enableTime = Time.time;
	}

	private void OnTriggerEnter(Collider other)
	{
		GorillaTriggerColliderHandIndicator componentInParent = other.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
		if ((bool)componentInParent)
		{
			PressButton();
			GorillaTagger.Instance.StartVibration(componentInParent.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
		}
	}

	public void PressButton()
	{
		if (IsReady && isUsable)
		{
			if ((bool)_screenRegion)
			{
				_screenRegion.RegisterButtonPress();
			}
			if (buttonMode == ButtonMode.Normal)
			{
				buttonPressed.Invoke(buttonType, data, NetworkSystem.Instance.LocalPlayer.ActorNumber);
			}
			else if (buttonMode == ButtonMode.Toggle)
			{
				bool arg = !_isToggledOn;
				buttonToggled.Invoke(buttonType, data, NetworkSystem.Instance.LocalPlayer.ActorNumber, arg);
			}
			if (_pressSound != null)
			{
				GTAudioOneShot.Play(_pressSound, base.transform.position, _pressSoundVolume);
			}
		}
	}

	public void SetToggleState(bool state, bool invokeEvent = false)
	{
		if (buttonMode == ButtonMode.Toggle)
		{
			bool flag = _isToggledOn != state;
			_isToggledOn = state;
			if (invokeEvent && flag)
			{
				buttonToggled.Invoke(buttonType, data, NetworkSystem.Instance.LocalPlayer.ActorNumber, _isToggledOn);
			}
		}
	}

	public void Click(bool leftHand = false)
	{
		PressButton();
	}
}
public interface ITouchScreenStation
{
	GameObject gameObject { get; }

	SIScreenRegion ScreenRegion { get; }

	void AddButton(SITouchscreenButton button, bool isPopupButton = false);

	void TouchscreenButtonPressed(SITouchscreenButton.SITouchscreenButtonType buttonType, int data, int actorNr);

	void TouchscreenToggleButtonPressed(SITouchscreenButton.SITouchscreenButtonType buttonType, int data, int actorNr, bool isToggledOn);
}
public class SITouchscreenButtonContainer : MonoBehaviour
{
	public SITouchscreenButton.SITouchscreenButtonType type;

	public string buttonTextString;

	public int data;

	public RectTransform backGround;

	public RectTransform backgroundShadow;

	public Image foreGround;

	public TextMeshProUGUI buttonText;

	public ITouchScreenStation station;

	[Header("Toggle Visual Settings")]
	public Color toggleOnColor = new Color(0f, 1f, 0.345098f);

	public Color toggleOffColor = new Color(0.5f, 0.5f, 0.5f);

	[Header("Toggle Text Settings")]
	[Tooltip("Text to display when toggle is ON")]
	public string toggleOnText = "ON";

	[Tooltip("Text to display when toggle is OFF")]
	public string toggleOffText = "OFF";

	public SITouchscreenButton button;

	[SerializeField]
	private bool autoConfigure = true;

	[NonSerialized]
	private Color _cachedForegroundColor = new Color(-1f, -1f, -1f);

	public bool isUsable { get; private set; }

	private void Start()
	{
		if (UnityEngine.Application.isPlaying && button != null && button.buttonMode == SITouchscreenButton.ButtonMode.Toggle)
		{
			button.buttonToggled.AddListener(OnToggleStateChanged);
			UpdateToggleVisual(button.IsToggledOn);
		}
	}

	private void OnToggleStateChanged(SITouchscreenButton.SITouchscreenButtonType type, int data, int actorNr, bool isToggledOn)
	{
		UpdateToggleVisual(isToggledOn);
	}

	public void UpdateToggleVisual()
	{
		UpdateToggleVisual(button.IsToggledOn);
	}

	private void UpdateToggleVisual(bool isToggledOn)
	{
		if (_cachedForegroundColor.r < 0f)
		{
			_cachedForegroundColor = foreGround.color;
		}
		foreGround.color = (isToggledOn ? toggleOnColor : toggleOffColor);
		buttonText.text = (isToggledOn ? toggleOnText : toggleOffText);
	}

	public void SetUsable(bool newIsUsable)
	{
		if (_cachedForegroundColor.r < 0f)
		{
			_cachedForegroundColor = foreGround.color;
		}
		isUsable = newIsUsable;
		if (button.buttonMode == SITouchscreenButton.ButtonMode.Normal)
		{
			foreGround.color = (newIsUsable ? _cachedForegroundColor : Color.gray);
		}
		button.isUsable = newIsUsable;
	}
}
public class SIUIPlayerQuestDisplay : MonoBehaviour, IGorillaSliceableSimple
{
	public TextMeshProUGUI playerName;

	[FormerlySerializedAs("playerTestPoints")]
	public TextMeshProUGUI playerTechPoints;

	public TextMeshProUGUI stashedQuestCount;

	public TextMeshProUGUI stashedBonusPointCount;

	public Image displayBackground;

	public Image smallDisplayBackground;

	public Image monkeIdolIcon;

	public Color localPlayerColor;

	public Color remotePlayerColor;

	public Color noPlayerColor;

	public SIUIPlayerQuestEntry[] questEntries;

	public GameObject collectBonusButton;

	public GameObject bonusPointsInProgress;

	public GameObject bonusPointsCompleted;

	public SIUIProgressBar sharedProgress;

	public GameObject activePlayer;

	public GameObject waitingForPlayer;

	public int activePlayerActorNumber;

	private string lastNickName;

	private int lastStashedQuests = -1;

	private int lastStashedBonusPoints = -1;

	private int lastTechPoints = -1;

	private int lastBonusProgress = -1;

	public void RefreshDisplay()
	{
		SIPlayer sIPlayer = SIPlayer.Get(activePlayerActorNumber);
		bool flag = sIPlayer != null && sIPlayer.gamePlayer != null && sIPlayer.gamePlayer.rig != null && sIPlayer.gamePlayer.rig.Creator != null && activePlayerActorNumber > 0;
		if (!flag || !SIProgression.Instance.ClientReady)
		{
			if (activePlayer.activeSelf)
			{
				activePlayer.SetActive(value: false);
			}
			if (!waitingForPlayer.activeSelf)
			{
				waitingForPlayer.SetActive(value: true);
			}
			displayBackground.color = noPlayerColor;
			smallDisplayBackground.color = noPlayerColor;
			return;
		}
		if (activePlayer.activeSelf != flag)
		{
			activePlayer.SetActive(flag);
		}
		if (waitingForPlayer.activeSelf == flag)
		{
			waitingForPlayer.SetActive(!flag);
		}
		if (!flag)
		{
			displayBackground.color = noPlayerColor;
			smallDisplayBackground.color = noPlayerColor;
			return;
		}
		Color color = ((sIPlayer == SIPlayer.LocalPlayer) ? localPlayerColor : remotePlayerColor);
		displayBackground.color = color;
		smallDisplayBackground.color = color;
		string sanitizedNickName = sIPlayer.gamePlayer.rig.Creator.SanitizedNickName;
		if (lastNickName != sanitizedNickName)
		{
			playerName.text = sanitizedNickName;
		}
		lastNickName = sanitizedNickName;
		int num = sIPlayer.CurrentProgression.resourceArray[0];
		if (lastTechPoints != num)
		{
			playerTechPoints.text = $"TECH POINTS: {num}";
		}
		lastTechPoints = num;
		bool flag2 = sIPlayer.HasLimitedResourceBeenDeposited(SIResource.LimitedDepositType.MonkeIdol);
		if (flag2 != monkeIdolIcon.enabled)
		{
			monkeIdolIcon.enabled = flag2;
		}
		int stashedQuests = sIPlayer.CurrentProgression.stashedQuests;
		if (lastStashedQuests != stashedQuests)
		{
			stashedQuestCount.text = $"STASHED QUESTS: {Mathf.Max(0, stashedQuests - 3)}/{6}";
		}
		lastStashedQuests = stashedQuests;
		int stashedBonusPoints = sIPlayer.CurrentProgression.stashedBonusPoints;
		if (lastStashedBonusPoints != stashedBonusPoints)
		{
			stashedBonusPointCount.text = $"STASHED BONUS: {Mathf.Max(0, stashedBonusPoints - 1)}/{2}";
		}
		lastStashedBonusPoints = stashedBonusPoints;
		int bonusProgress = sIPlayer.CurrentProgression.bonusProgress;
		if (lastBonusProgress != bonusProgress)
		{
			float num2 = Mathf.Clamp01((float)bonusProgress / 4f);
			sharedProgress.UpdateFillPercent(num2);
			sharedProgress.progressText.text = $"{num2 * 100f:F0}%";
		}
		lastBonusProgress = bonusProgress;
		bool flag3 = sIPlayer.CurrentProgression.stashedBonusPoints > 0;
		if (bonusPointsInProgress.activeSelf != flag3)
		{
			bonusPointsInProgress.SetActive(flag3);
		}
		if (bonusPointsCompleted.activeSelf == flag3)
		{
			bonusPointsCompleted.SetActive(!flag3);
		}
		bool flag4 = sIPlayer.CurrentProgression.bonusProgress >= 4;
		if (collectBonusButton.activeSelf != flag4)
		{
			collectBonusButton.SetActive(flag4);
		}
		if (questEntries != null && sIPlayer.CurrentProgression.currentQuestIds != null && sIPlayer.CurrentProgression.currentQuestProgresses != null)
		{
			for (int i = 0; i < questEntries.Length; i++)
			{
				ProcessQuestEntry(questEntries[i], sIPlayer.CurrentProgression.currentQuestIds[i], sIPlayer.CurrentProgression.currentQuestProgresses[i]);
			}
		}
	}

	public void ProcessQuestEntry(SIUIPlayerQuestEntry entry, int questId, int questProgress)
	{
		if (SIProgression.Instance.questSourceList == null)
		{
			if (entry.questInfo.activeSelf)
			{
				entry.questInfo.SetActive(value: false);
			}
			if (!entry.noQuestAvailable.activeSelf)
			{
				entry.noQuestAvailable.SetActive(value: true);
			}
			if (entry.completeOverlay.activeSelf)
			{
				entry.completeOverlay.SetActive(value: false);
			}
			entry.lastQuestId = -1;
			entry.lastQuestProgress = -1;
			return;
		}
		RotatingQuest questById = SIProgression.Instance.questSourceList.GetQuestById(questId);
		bool flag = questId != -1 && questById != null;
		if (entry.completeOverlay.activeSelf && !flag)
		{
			entry.completeOverlay.SetActive(value: false);
		}
		if (entry.questInfo.activeSelf != flag)
		{
			entry.questInfo.SetActive(flag);
		}
		if (entry.noQuestAvailable.activeSelf == flag)
		{
			entry.noQuestAvailable.SetActive(!flag);
		}
		if (!flag)
		{
			entry.lastQuestId = -1;
			return;
		}
		if (questId != entry.lastQuestId)
		{
			entry.questDescription.text = questById.GetTextDescription();
		}
		if (entry.lastQuestProgress != questProgress || questId != entry.lastQuestId)
		{
			entry.progress.UpdateFillPercent((float)questProgress / (float)questById.requiredOccurenceCount);
			entry.progress.progressText.text = questProgress + "/" + questById.requiredOccurenceCount;
		}
		if (entry.lastQuestId != -1 && entry.lastQuestId != questById.questID)
		{
			entry.newQuestTag.SetActive(value: true);
		}
		entry.lastQuestId = questById.questID;
		entry.lastQuestProgress = questProgress;
		bool flag2 = questProgress >= questById.requiredOccurenceCount;
		if (entry.completeOverlay.activeSelf != flag2)
		{
			entry.completeOverlay.SetActive(flag2);
		}
	}

	public void BonusPointCollectButtonPress()
	{
		if (activePlayerActorNumber == SIPlayer.LocalPlayer.ActorNr)
		{
			SIProgression.Instance.AttemptRedeemBonusPoint();
		}
	}

	public void QuestPointCollectButtonPress(int questIndex)
	{
		if (activePlayerActorNumber == SIPlayer.LocalPlayer.ActorNr && SIPlayer.LocalPlayer.QuestAvailableToClaim(questIndex))
		{
			SIProgression.Instance.AttemptRedeemCompletedQuest(questIndex);
		}
	}

	void IGorillaSliceableSimple.SliceUpdate()
	{
		RefreshDisplay();
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}
}
public class SIUIPlayerQuestEntry : MonoBehaviour
{
	public Image background;

	public SIUIProgressBar progress;

	public TextMeshProUGUI questDescription;

	public GameObject completeOverlay;

	public GameObject questInfo;

	public GameObject noQuestAvailable;

	public GameObject newQuestTag;

	public int lastQuestId;

