	internal bool NotifyCrankGrabbed(int crankIndex, bool isLeftHand)
	{
		ref CrankSyncState reference = ref crankIndex == 0 ? ref pitchCrankSync : ref yawCrankSync;
		if (reference.holderActorNr != -1)
		{
			return false;
