public enum ArtilleryCrankType
{
	Pitch,
	Yaw
}
public class ArtilleryCrank : HoldableObject
{
	[SerializeField]
	private ArtilleryCannon cannon;

	[SerializeField]
	private ArtilleryCrankType crankType;

	[SerializeField]
	private float crankHandleX;

	[SerializeField]
	private float crankHandleY;

	[SerializeField]
	private float crankHandleMinZ;

	[SerializeField]
	private float crankHandleMaxZ;

	[SerializeField]
	private float maxHandSnapDistance;

	[SerializeField]
	private Transform rotatingPart;

	private float crankAngleOffset;

	private float crankRadius;

	private float lastAngle;

	private float currentAngle;

	private UnityEngine.Quaternion baseLocalAngle;

	private UnityEngine.Quaternion baseLocalAngleInverse;

	private bool isHeld;

	private bool isHeldLeftHand;

	public bool IsHeld => isHeld;

	public bool IsHeldLeftHand => isHeldLeftHand;

	public float CurrentAngle => currentAngle;

	private int CrankIndex
	{
		get
		{
			if (crankType != ArtilleryCrankType.Pitch)
			{
				return 1;
			}
			return 0;
		}
	}

	private void Awake()
	{
		if (rotatingPart == null)
		{
			rotatingPart = base.transform;
		}
		UnityEngine.Vector3 vector = rotatingPart.parent.InverseTransformPoint(rotatingPart.TransformPoint(UnityEngine.Vector3.right));
		lastAngle = Mathf.Atan2(vector.y, vector.x) * 57.29578f;
		baseLocalAngle = rotatingPart.localRotation;
		baseLocalAngleInverse = UnityEngine.Quaternion.Inverse(baseLocalAngle);
		crankRadius = new UnityEngine.Vector2(crankHandleX, crankHandleY).magnitude;
		crankAngleOffset = Mathf.Atan2(crankHandleY, crankHandleX) * 57.29578f;
		if (crankHandleMaxZ < crankHandleMinZ)
		{
			float num = crankHandleMaxZ;
			float num2 = crankHandleMinZ;
			crankHandleMinZ = num;
			crankHandleMaxZ = num2;
		}
	}

	private void LateUpdate()
	{
		if (!isHeld)
		{
			return;
		}
		if (!cannon.IsCrankHeldLocally(CrankIndex))
		{
			DropItemCleanup();
			return;
		}
		Transform controllerTransform = GTPlayer.Instance.GetControllerTransform(isHeldLeftHand);
		UnityEngine.Vector3 v = rotatingPart.InverseTransformPoint(controllerTransform.position);
		UnityEngine.Vector3 position = (v.xy().normalized * crankRadius).WithZ(Mathf.Clamp(v.z, crankHandleMinZ, crankHandleMaxZ));
		UnityEngine.Vector3 vector = rotatingPart.TransformPoint(position);
		if (maxHandSnapDistance > 0f && (controllerTransform.position - vector).IsLongerThan(maxHandSnapDistance))
		{
			OnRelease(null, isHeldLeftHand ? EquipmentInteractor.instance.leftHand : EquipmentInteractor.instance.rightHand);
			return;
		}
		controllerTransform.position = vector;
		float num = ComputeAngleFromWorldPos(controllerTransform.position);
		float num2 = Mathf.DeltaAngle(lastAngle, num);
		lastAngle = num;
		currentAngle = num;
		if (num2 != 0f)
		{
			cannon.OnCrankInput(CrankIndex, num2);
		}
		ApplyVisualAngle(num);
	}

	public void UpdateFromRemoteHand(VRRig rig, bool leftHand)
	{
		VRMap vRMap = (leftHand ? rig.leftHand : rig.rightHand);
		UnityEngine.Vector3 extrapolatedControllerPosition = vRMap.GetExtrapolatedControllerPosition();
		extrapolatedControllerPosition -= vRMap.rigTarget.rotation * GTPlayer.Instance.GetHandOffset(leftHand) * rig.scaleFactor;
		ApplyVisualAngle(currentAngle = ComputeAngleFromWorldPos(extrapolatedControllerPosition));
	}

	public void SetVisualAngle(float angle)
	{
		if (rotatingPart != null)
		{
			currentAngle = angle;
			ApplyVisualAngle(angle);
		}
	}

	private float ComputeAngleFromWorldPos(UnityEngine.Vector3 worldPos)
	{
		UnityEngine.Vector3 vector = baseLocalAngleInverse * UnityEngine.Quaternion.Inverse(rotatingPart.parent.rotation) * (worldPos - rotatingPart.position);
		return Mathf.Atan2(vector.y, vector.x) * 57.29578f;
	}

	private void ApplyVisualAngle(float angle)
	{
		rotatingPart.localRotation = baseLocalAngle * UnityEngine.Quaternion.AngleAxis(angle - crankAngleOffset, UnityEngine.Vector3.forward);
	}

	public override void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
	{
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		isHeldLeftHand = grabbingHand == EquipmentInteractor.instance.leftHand;
		if (cannon.OnCrankGrabbed(CrankIndex, isHeldLeftHand))
		{
			isHeld = true;
			EquipmentInteractor.instance.UpdateHandEquipment(this, isHeldLeftHand);
			Transform controllerTransform = GTPlayer.Instance.GetControllerTransform(isHeldLeftHand);
			UnityEngine.Vector3 vector = baseLocalAngleInverse * UnityEngine.Quaternion.Inverse(rotatingPart.parent.rotation) * (controllerTransform.position - rotatingPart.position);
			lastAngle = Mathf.Atan2(vector.y, vector.x) * 57.29578f;
		}
	}

	public override void DropItemCleanup()
	{
		if (isHeld)
		{
			isHeld = false;
			cannon.OnCrankReleased(CrankIndex, currentAngle);
		}
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		EquipmentInteractor.instance.UpdateHandEquipment(null, isHeldLeftHand);
		if (isHeld)
		{
			isHeld = false;
			cannon.OnCrankReleased(CrankIndex, currentAngle);
		}
		return true;
	}

	private void OnDrawGizmosSelected()
	{
		Transform transform = ((rotatingPart != null) ? rotatingPart : base.transform);
		Gizmos.color = Color.green;
		Gizmos.DrawLine(transform.TransformPoint(new UnityEngine.Vector3(crankHandleX, crankHandleY, crankHandleMinZ)), transform.TransformPoint(new UnityEngine.Vector3(crankHandleX, crankHandleY, crankHandleMaxZ)));
	}
}
public class BatteryCharger : MonoBehaviour
{
	[Serializable]
	private class EventPhaseObjects
	{
		public string friendlyName;

		public GameObject[] objects;
	}

	[Serializable]
	private class BatteryChargerEvent
	{
		public enum VDirection
		{
			Up,
			Down
		}

		[SerializeField]
		private VDirection direction;

		[SerializeField]
		private float value;

		[SerializeField]
		private UnityEvent action;

		public VDirection Direction => direction;

		public float Value => value;

		public UnityEvent Action => action;
	}

	[Header("Network State")]
	[SerializeField]
	private XSceneRef stateRef;

	[Header("Charge Visuals")]
	[Tooltip("Transform rotated on its local Z axis to show charge level")]
	[SerializeField]
	private Transform chargeFillTransform;

	[Tooltip("Local Z rotation in degrees when fully charged")]
	[SerializeField]
	private float chargeFullRollAngle = -180f;

	[Tooltip("Renderer whose material color lerps with charge")]
	[SerializeField]
	private Renderer chargeFillRenderer;

	[SerializeField]
	private Color emptyColor = Color.red;

	[SerializeField]
	private Color fullColor = Color.green;

	[Header("Audio")]
	[SerializeField]
	private AudioSource chargingLoopSound;

	[SerializeField]
	private AudioSource fullyChargedSound;

	[Header("Event Phases")]
	[SerializeField]
	private EventPhaseObjects[] eventPhases;

	private BatteryChargerState state;

	private BatteryChargerCrank[] cranks = new BatteryChargerCrank[20];

	private int crankCount;

	[SerializeField]
	private BatteryChargerEvent[] actions;

	private float previousCharge;

	public int CurrentEventPhase
	{
		get
		{
			if (!(state != null))
			{
				return -1;
			}
			return state.EventPhase;
		}
	}

	private int LocalActorNr
	{
		get
		{
			if (PhotonNetwork.LocalPlayer == null)
			{
				return -1;
			}
			return PhotonNetwork.LocalPlayer.ActorNumber;
		}
	}

	internal int RegisterCrank(BatteryChargerCrank crank)
	{
		if (crankCount >= 20)
		{
			UnityEngine.Debug.LogError($"BatteryCharger: too many cranks (max {20})", this);
			return -1;
		}
		int num = crankCount;
		cranks[num] = crank;
		crankCount++;
		return num;
	}

	private void OnEnable()
	{
		if (stateRef.TryResolve(out BatteryChargerState result))
		{
			Bind(result);
		}
		else
		{
			stateRef.AddCallbackOnLoad(OnStateSceneLoaded);
		}
	}

	private void OnDisable()
	{
		stateRef.RemoveCallbackOnLoad(OnStateSceneLoaded);
		Unbind();
	}

	private void OnStateSceneLoaded()
	{
		if (stateRef.TryResolve(out BatteryChargerState result))
		{
			Bind(result);
		}
	}

	private void Bind(BatteryChargerState newState)
	{
		if (!(state == newState))
		{
			Unbind();
			state = newState;
			if (!(state == null))
			{
				state.onChargeChanged += OnChargeChanged;
				state.onFullyCharged += OnFullyCharged;
				state.onEventPhaseChanged += OnEventPhaseChanged;
				previousCharge = state.CurrentCharge;
				ApplyChargeVisuals();
				OnEventPhaseChanged(state.EventPhase);
			}
		}
	}

	private void Unbind()
	{
		if (!(state == null))
		{
			state.onChargeChanged -= OnChargeChanged;
			state.onFullyCharged -= OnFullyCharged;
			state.onEventPhaseChanged -= OnEventPhaseChanged;
			state = null;
		}
	}

	private void LateUpdate()
	{
		if (state == null)
		{
			return;
		}
		int localActorNr = LocalActorNr;
		for (int i = 0; i < crankCount; i++)
		{
			if (!(cranks[i] == null))
			{
				if (state.crankSyncs[i].holderActorNr == localActorNr)
				{
					state.UpdateLocalCrankState(i, cranks[i].IsHeldLeftHand, cranks[i].CurrentAngle);
				}
				UpdateRemoteCrankVisual(cranks[i], state.crankSyncs[i], localActorNr);
			}
		}
		if (!(chargingLoopSound != null))
		{
			return;
		}
		bool flag = false;
		for (int j = 0; j < 20; j++)
		{
			if (state.crankSyncs[j].holderActorNr != -1)
			{
				flag = true;
				break;
			}
		}
		if (flag && !chargingLoopSound.isPlaying)
		{
			chargingLoopSound.Play();
		}
		else if (!flag && chargingLoopSound.isPlaying)
		{
			chargingLoopSound.Stop();
		}
	}

	private void UpdateRemoteCrankVisual(BatteryChargerCrank crank, BatteryChargerState.CrankSyncState syncState, int localActor)
	{
		if (crank == null || syncState.holderActorNr == localActor)
		{
			return;
		}
		if (syncState.holderActorNr != -1)
		{
			VRRig vRRig = BatteryChargerState.FindRigForActor(syncState.holderActorNr);
			if (vRRig != null)
			{
				crank.UpdateFromRemoteHand(vRRig, syncState.isLeftHand);
				return;
			}
		}
		crank.SetVisualAngle(syncState.angle);
	}

	internal bool IsCrankHeldLocally(int crankIndex)
	{
		if (state == null || crankIndex < 0 || crankIndex >= 20)
		{
			return false;
		}
		return state.crankSyncs[crankIndex].holderActorNr == LocalActorNr;
	}

	public void SetEventPhase(int phase)
	{
		state.SetEventPhase(phase);
	}

	public void SetChargePerCrankDegree(float chargeRate)
	{
		state.SetChargePerCrankDegree(chargeRate);
	}

	internal bool OnCrankGrabbed(int crankIndex, bool isLeftHand)
	{
		return state.NotifyCrankGrabbed(crankIndex, isLeftHand);
	}

	internal void OnCrankReleased(int crankIndex, float finalAngle)
	{
		state.NotifyCrankReleased(crankIndex, finalAngle);
	}

	internal void OnCrankInput(int crankIndex, float degrees)
	{
		state.NotifyCrankInput(crankIndex, degrees);
		ApplyChargeVisuals();
	}

	private void OnChargeChanged()
	{
		for (int i = 0; i < actions.Length; i++)
		{
			if ((actions[i].Direction == BatteryChargerEvent.VDirection.Up && previousCharge < state.CurrentCharge && previousCharge < actions[i].Value && state.CurrentCharge >= actions[i].Value) || (actions[i].Direction == BatteryChargerEvent.VDirection.Down && previousCharge > state.CurrentCharge && previousCharge > actions[i].Value && state.CurrentCharge <= actions[i].Value))
			{
				actions[i].Action?.Invoke();
			}
		}
		previousCharge = state.CurrentCharge;
		ApplyChargeVisuals();
	}

	private void OnFullyCharged()
	{
		if (fullyChargedSound != null)
		{
			fullyChargedSound.GTPlay();
		}
	}

	private void OnEventPhaseChanged(int phase)
	{
		for (int i = 0; i < eventPhases.Length; i++)
		{
			if (eventPhases[i]?.objects == null)
			{
				continue;
			}
			bool active = i == phase;
			for (int j = 0; j < eventPhases[i].objects.Length; j++)
			{
				if (eventPhases[i].objects[j] != null)
				{
					eventPhases[i].objects[j].SetActive(active);
				}
			}
		}
	}

	private void ApplyChargeVisuals()
	{
		if (!(state == null))
		{
			float chargePercent = state.ChargePercent;
			if (chargeFillTransform != null)
			{
				chargeFillTransform.localRotation = UnityEngine.Quaternion.Euler(0f, 0f, chargePercent * chargeFullRollAngle);
			}
			if (chargeFillRenderer != null)
			{
				chargeFillRenderer.material.color = Color.Lerp(emptyColor, fullColor, chargePercent);
			}
		}
	}
}
public class BatteryChargerCrank : HoldableObject
{
	[SerializeField]
	private BatteryCharger charger;

	[SerializeField]
	private float crankHandleX;

	[SerializeField]
	private float crankHandleY;

	[SerializeField]
	private float crankHandleMinZ;

	[SerializeField]
	private float crankHandleMaxZ;

	[SerializeField]
	private float maxHandSnapDistance;

	[SerializeField]
	private Transform rotatingPart;

	[SerializeField]
	private float vibrationAmplitude = 0.3f;

	[SerializeField]
	private AudioSource crankSound;

	[SerializeField]
	private float crankSoundMinPitch = 0.6f;

	[SerializeField]
	private float crankSoundMaxPitch = 1.4f;

	private float crankAngleOffset;

	private float crankRadius;

	private float lastAngle;

	private float currentAngle;

	private float smoothCrankSpeed;

	private UnityEngine.Quaternion baseLocalAngle;

	private UnityEngine.Quaternion baseLocalAngleInverse;

	private int crankIndex = -1;

	private bool isHeld;

	private bool isHeldLeftHand;

	public bool IsHeld => isHeld;

	public bool IsHeldLeftHand => isHeldLeftHand;

	public float CurrentAngle => currentAngle;

	internal int CrankIndex => crankIndex;

	private void Awake()
	{
		if (rotatingPart == null)
		{
			rotatingPart = base.transform;
		}
		UnityEngine.Vector3 vector = rotatingPart.parent.InverseTransformPoint(rotatingPart.TransformPoint(UnityEngine.Vector3.right));
		lastAngle = Mathf.Atan2(vector.y, vector.x) * 57.29578f;
		baseLocalAngle = rotatingPart.localRotation;
		baseLocalAngleInverse = UnityEngine.Quaternion.Inverse(baseLocalAngle);
		crankRadius = new UnityEngine.Vector2(crankHandleX, crankHandleY).magnitude;
		crankAngleOffset = Mathf.Atan2(crankHandleY, crankHandleX) * 57.29578f;
		if (crankHandleMaxZ < crankHandleMinZ)
		{
			float num = crankHandleMaxZ;
			float num2 = crankHandleMinZ;
			crankHandleMinZ = num;
			crankHandleMaxZ = num2;
		}
	}

	private void Start()
	{
		crankIndex = charger.RegisterCrank(this);
	}

	private void LateUpdate()
	{
		if (!isHeld || crankIndex < 0)
		{
			return;
		}
		if (!charger.IsCrankHeldLocally(crankIndex))
		{
			DropItemCleanup();
			return;
		}
		Transform controllerTransform = GTPlayer.Instance.GetControllerTransform(isHeldLeftHand);
		UnityEngine.Vector3 v = rotatingPart.InverseTransformPoint(controllerTransform.position);
		UnityEngine.Vector3 position = (v.xy().normalized * crankRadius).WithZ(Mathf.Clamp(v.z, crankHandleMinZ, crankHandleMaxZ));
		UnityEngine.Vector3 vector = rotatingPart.TransformPoint(position);
		if (maxHandSnapDistance > 0f && (controllerTransform.position - vector).IsLongerThan(maxHandSnapDistance))
		{
			OnRelease(null, isHeldLeftHand ? EquipmentInteractor.instance.leftHand : EquipmentInteractor.instance.rightHand);
			return;
		}
		controllerTransform.position = vector;
		float num = ComputeAngleFromWorldPos(controllerTransform.position);
		float num2 = Mathf.DeltaAngle(lastAngle, num);
		lastAngle = num;
		currentAngle = num;
		if (num2 != 0f)
		{
			charger.OnCrankInput(crankIndex, num2);
			GorillaTagger.Instance.DoVibration(isHeldLeftHand ? XRNode.LeftHand : XRNode.RightHand, Mathf.Abs(num2 / 30f) * vibrationAmplitude, Time.deltaTime);
		}
		UpdateCrankSound(num2);
		ApplyVisualAngle(num);
	}

	public void UpdateFromRemoteHand(VRRig rig, bool leftHand)
	{
		VRMap vRMap = (leftHand ? rig.leftHand : rig.rightHand);
		UnityEngine.Vector3 extrapolatedControllerPosition = vRMap.GetExtrapolatedControllerPosition();
		extrapolatedControllerPosition -= vRMap.rigTarget.rotation * GTPlayer.Instance.GetHandOffset(leftHand) * rig.scaleFactor;
		ApplyVisualAngle(currentAngle = ComputeAngleFromWorldPos(extrapolatedControllerPosition));
	}

	public void SetVisualAngle(float angle)
	{
		if (rotatingPart != null)
		{
			currentAngle = angle;
			ApplyVisualAngle(angle);
		}
	}

	private float ComputeAngleFromWorldPos(UnityEngine.Vector3 worldPos)
	{
		UnityEngine.Vector3 vector = baseLocalAngleInverse * UnityEngine.Quaternion.Inverse(rotatingPart.parent.rotation) * (worldPos - rotatingPart.position);
		return Mathf.Atan2(vector.y, vector.x) * 57.29578f;
	}

	private void ApplyVisualAngle(float angle)
	{
		rotatingPart.localRotation = baseLocalAngle * UnityEngine.Quaternion.AngleAxis(angle - crankAngleOffset, UnityEngine.Vector3.forward);
	}

	private void UpdateCrankSound(float crankAmount)
	{
		if (crankSound == null)
		{
			return;
		}
		float b = Mathf.Abs(crankAmount / 30f) * vibrationAmplitude;
		smoothCrankSpeed = Mathf.Lerp(smoothCrankSpeed, b, 10f * Time.deltaTime);
		if (smoothCrankSpeed > 0.01f)
		{
			if (!crankSound.isPlaying)
			{
				crankSound.Play();
			}
			float t = Mathf.Clamp01(smoothCrankSpeed);
			crankSound.pitch = Mathf.Lerp(crankSoundMinPitch, crankSoundMaxPitch, t);
		}
		else if (crankSound.isPlaying)
		{
			crankSound.Stop();
			smoothCrankSpeed = 0f;
		}
	}

	private void StopCrankSound()
	{
		if (crankSound != null && crankSound.isPlaying)
		{
			crankSound.Stop();
		}
		smoothCrankSpeed = 0f;
	}

	public override void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
	{
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		if (crankIndex >= 0)
		{
			isHeldLeftHand = grabbingHand == EquipmentInteractor.instance.leftHand;
			if (charger.OnCrankGrabbed(crankIndex, isHeldLeftHand))
			{
				isHeld = true;
				EquipmentInteractor.instance.UpdateHandEquipment(this, isHeldLeftHand);
				Transform controllerTransform = GTPlayer.Instance.GetControllerTransform(isHeldLeftHand);
				UnityEngine.Vector3 vector = baseLocalAngleInverse * UnityEngine.Quaternion.Inverse(rotatingPart.parent.rotation) * (controllerTransform.position - rotatingPart.position);
				lastAngle = Mathf.Atan2(vector.y, vector.x) * 57.29578f;
			}
		}
	}

	public override void DropItemCleanup()
	{
		if (isHeld)
		{
			isHeld = false;
			StopCrankSound();
			charger.OnCrankReleased(crankIndex, currentAngle);
		}
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		EquipmentInteractor.instance.UpdateHandEquipment(null, isHeldLeftHand);
		if (isHeld)
		{
			isHeld = false;
			charger.OnCrankReleased(crankIndex, currentAngle);
		}
		return true;
	}

	private void OnDrawGizmosSelected()
	{
		Transform transform = ((rotatingPart != null) ? rotatingPart : base.transform);
		Gizmos.color = Color.green;
		Gizmos.DrawLine(transform.TransformPoint(new UnityEngine.Vector3(crankHandleX, crankHandleY, crankHandleMinZ)), transform.TransformPoint(new UnityEngine.Vector3(crankHandleX, crankHandleY, crankHandleMaxZ)));
	}
}
[RequireComponent(typeof(XSceneRefTarget))]
[NetworkBehaviourWeaved(62)]
public class BatteryChargerState : NetworkComponent
{
	internal struct CrankSyncState
	{
		public int holderActorNr;

		public bool isLeftHand;

		public float angle;
	}

	private enum BatteryMsg : byte
	{
		CrankGrabLeft,
		CrankGrabRight,
		CrankRelease,
		CrankInput
	}

	[StructLayout(LayoutKind.Explicit, Size = 12)]
	[NetworkStructWeaved(3)]
	private struct FusionCrankData : INetworkStruct
	{
		[FieldOffset(0)]
		public int holderActorNr;

		[FieldOffset(4)]
		public NetworkBool isLeftHand;

		[FieldOffset(8)]
		public float angle;
	}

	[StructLayout(LayoutKind.Explicit, Size = 8)]
	[NetworkStructWeaved(2)]
	private struct FusionSyncState : INetworkStruct
	{
		[FieldOffset(0)]
		public float charge;

		[FieldOffset(4)]
		public int eventPhase;
	}

	internal const int MAX_CRANKS = 20;

	[Header("Charging")]
	[Tooltip("Charge added per degree of crank rotation (across all cranks)")]
	[SerializeField]
	private float chargePerCrankDegree = 0.001f;

	[Tooltip("Charge drains at this rate per second when no one is cranking")]
	[SerializeField]
	private float drainPerSecond = 0.02f;

	[Tooltip("Maximum charge level (0 to 1)")]
	[SerializeField]
	private float maxCharge = 1f;

	private float currentCharge;

	private int activeCrankerCount;

	private int eventPhase = -1;

	internal CrankSyncState[] crankSyncs = new CrankSyncState[20];

	private const float GRAB_GRACE_PERIOD = 1f;

	private float[] pendingGrabTime = new float[20];

	private const float CRANK_RPC_INTERVAL = 1f;

	private float nextCrankRPCTimestamp;

	private float pendingCrankCharge;

	private int pendingCrankIndex = -1;

	private bool m_disableNetworking;

	[WeaverGenerated]
	[DefaultForProperty("FusionData", 0, 2)]
	[DrawIf("IsEditorWritable", true, CompareOperator.Equal, DrawIfMode.ReadOnly)]
	private FusionSyncState _FusionData;

	[WeaverGenerated]
	[DefaultForProperty("FusionCranks", 2, 60)]
	[DrawIf("IsEditorWritable", true, CompareOperator.Equal, DrawIfMode.ReadOnly)]
	private FusionCrankData[] _FusionCranks;

	internal float CurrentCharge => currentCharge;

	internal float MaxCharge => maxCharge;

	internal float ChargePercent
	{
		get
		{
			if (!(maxCharge > 0f))
			{
				return 0f;
			}
			return currentCharge / maxCharge;
		}
	}

	internal float ChargePerCrankDegree => chargePerCrankDegree;

	internal int EventPhase => eventPhase;

	private int LocalActorNr
	{
		get
		{
			if (PhotonNetwork.LocalPlayer == null)
			{
				return -1;
			}
			return PhotonNetwork.LocalPlayer.ActorNumber;
		}
	}

	[Networked]
	[NetworkedWeaved(0, 2)]
	private unsafe FusionSyncState FusionData
	{
		get
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing BatteryChargerState.FusionData. Networked properties can only be accessed when Spawned() has been called.");
			}
			return *(FusionSyncState*)((byte*)((NetworkBehaviour)this).Ptr + 0);
		}
		set
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing BatteryChargerState.FusionData. Networked properties can only be accessed when Spawned() has been called.");
			}
			*(FusionSyncState*)((byte*)((NetworkBehaviour)this).Ptr + 0) = value;
		}
	}

	[Networked]
	[Capacity(20)]
	[NetworkedWeaved(2, 60)]
	[NetworkedWeavedArray(20, 3, typeof(ReaderWriter@BatteryChargerState__FusionCrankData))]
	private unsafe NetworkArray<FusionCrankData> FusionCranks
	{
		get
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing BatteryChargerState.FusionCranks. Networked properties can only be accessed when Spawned() has been called.");
			}
			return new NetworkArray<FusionCrankData>((byte*)((NetworkBehaviour)this).Ptr + 8, 20, ReaderWriter@BatteryChargerState__FusionCrankData.GetInstance());
		}
	}

	internal event Action onChargeChanged;

	internal event Action onFullyCharged;

	internal event Action<int> onEventPhaseChanged;

	public void SetChargePerCrankDegree(float chargeRate)
	{
		chargePerCrankDegree = chargeRate;
	}

	protected override void Awake()
	{
		base.Awake();
		for (int i = 0; i < 20; i++)
		{
			crankSyncs[i].holderActorNr = -1;
		}
	}

	private void Update()
	{
		if (activeCrankerCount <= 0 && currentCharge > 0f)
		{
			currentCharge = Mathf.Max(0f, currentCharge - drainPerSecond * Time.deltaTime);
			this.onChargeChanged?.Invoke();
		}
		activeCrankerCount = 0;
		for (int i = 0; i < 20; i++)
		{
			if (crankSyncs[i].holderActorNr != -1)
			{
				activeCrankerCount++;
			}
		}
	}

	internal void UpdateLocalCrankState(int crankIndex, bool isLeftHand, float angle)
	{
		if (crankIndex >= 0 && crankIndex < 20)
		{
			ref CrankSyncState reference = ref crankSyncs[crankIndex];
			int localActorNr = LocalActorNr;
			if (reference.holderActorNr == localActorNr)
			{
				reference.isLeftHand = isLeftHand;
				reference.angle = angle;
			}
		}
	}

	internal static VRRig FindRigForActor(int actorNr)
	{
		if (VRRigCache.Instance.TryGetVrrig(actorNr, out var playerRig))
		{
			return playerRig.Rig;
		}
		return null;
	}

	internal bool NotifyCrankGrabbed(int crankIndex, bool isLeftHand)
	{
		if (crankIndex < 0 || crankIndex >= 20)
		{
			return false;
		}
		ref CrankSyncState reference = ref crankSyncs[crankIndex];
		if (reference.holderActorNr != -1)
		{
			return false;
		}
		reference.holderActorNr = LocalActorNr;
		pendingGrabTime[crankIndex] = Time.time;
		if (PhotonNetwork.InRoom)
		{
			SendRPC("RPC_BatteryMessage", RpcTarget.MasterClient, (!isLeftHand) ? ((byte)1) : ((byte)0), (byte)crankIndex, 0f);
		}
		return true;
	}

	internal void NotifyCrankReleased(int crankIndex, float finalAngle)
	{
		if (crankIndex >= 0 && crankIndex < 20)
		{
			FlushCrankRPC();
			ref CrankSyncState reference = ref crankSyncs[crankIndex];
			reference.holderActorNr = -1;
			reference.angle = finalAngle;
			pendingGrabTime[crankIndex] = 0f;
			if (PhotonNetwork.InRoom)
			{
				SendRPC("RPC_BatteryMessage", RpcTarget.All, (byte)2, (byte)crankIndex, finalAngle);
			}
		}
	}

	internal void NotifyCrankInput(int crankIndex, float degrees)
	{
		if (crankIndex < 0 || crankIndex >= 20)
		{
			return;
		}
		float num = Mathf.Abs(degrees) * chargePerCrankDegree;
		if (num <= 0f)
		{
			return;
		}
		float num2 = currentCharge;
		currentCharge = Mathf.Clamp(currentCharge + num, 0f, maxCharge);
		this.onChargeChanged?.Invoke();
		if (num2 < maxCharge && currentCharge >= maxCharge)
		{
			this.onFullyCharged?.Invoke();
		}
		if (PhotonNetwork.InRoom)
		{
			pendingCrankCharge = currentCharge;
			pendingCrankIndex = crankIndex;
			if (Time.time >= nextCrankRPCTimestamp)
			{
				FlushCrankRPC();
			}
		}
	}

	private void FlushCrankRPC()
	{
		if (pendingCrankIndex >= 0 && !(pendingCrankCharge <= 0f))
		{
			SendRPC("RPC_BatteryMessage", RpcTarget.MasterClient, (byte)3, (byte)pendingCrankIndex, pendingCrankCharge);
			nextCrankRPCTimestamp = Time.time + 1f;
			pendingCrankIndex = -1;
		}
	}

	public void DisableNetworking()
	{
		m_disableNetworking = true;
	}

	public void EnableNetworking()
	{
		m_disableNetworking = false;
	}

	[PunRPC]
	public void RPC_BatteryMessage(byte msgType, byte crankIndex, float floatParam, PhotonMessageInfo info)
	{
		if (m_disableNetworking)
		{
			return;
		}
		MonkeAgent.IncrementRPCCall(info, "RPC_BatteryMessage");
		if (crankIndex >= 20)
		{
			return;
		}
		switch ((BatteryMsg)msgType)
		{
		case BatteryMsg.CrankGrabLeft:
		case BatteryMsg.CrankGrabRight:
			if (PhotonNetwork.IsMasterClient)
			{
				ref CrankSyncState reference2 = ref crankSyncs[crankIndex];
				if (reference2.holderActorNr == -1)
				{
					reference2.holderActorNr = info.Sender.ActorNumber;
					reference2.isLeftHand = msgType == 0;
				}
			}
			break;
		case BatteryMsg.CrankRelease:
		{
			ref CrankSyncState reference = ref crankSyncs[crankIndex];
			if (reference.holderActorNr == info.Sender.ActorNumber)
			{
				reference.holderActorNr = -1;
				reference.angle = floatParam.ClampSafe(-360f, 360f);
			}
			break;
		}
		case BatteryMsg.CrankInput:
			if (PhotonNetwork.IsMasterClient && crankSyncs[crankIndex].holderActorNr == info.Sender.ActorNumber)
			{
				float num = currentCharge;
				currentCharge = floatParam.ClampSafe(0f, maxCharge);
				this.onChargeChanged?.Invoke();
				if (num < maxCharge && currentCharge >= maxCharge)
				{
					this.onFullyCharged?.Invoke();
				}
			}
