		{
			if (rig == GorillaTagger.Instance.offlineVRRig)
			{
				return "-1";
			}
			UnityEngine.Debug.Log("Not in a room but not targeting offline rig");
			return null;
		}
		if (rig == GorillaTagger.Instance.offlineVRRig)
		{
			return NetworkSystem.Instance.LocalPlayer.UserId;
		}
		if (rig.creator == null)
		{
			return "";
