	private TMP_Text upNext;

	[SerializeField]
	private VODPlayer.VODStream.VODStreamChannel[] channel;

	[SerializeField]
	private GameObject staticScreen;

	public static Action<VODTarget> AlertEnabled;

	public static Action<VODTarget> AlertDisabled;

	private VODPlayer.VODNextStreamData upNextData;

	public VODTargetAudioSettings AudioSettings => audioSettings;

	public Renderer Renderer => targetRenderer;

	public Material StandbyOverride => standbyOverride;

	public VODPlayer.VODStream.VODStreamChannel[] Channel
	{
		get
		{
			if (channel.Length != 0)
			{
				return channel;
			}
			return new VODPlayer.VODStream.VODStreamChannel[1];
		}
	}

	public void SetNext(VODPlayer.VODNextStreamData data)
	{
		upNextData = data;
	}

	public void ClearNext()
	{
		upNextData = default(VODPlayer.VODNextStreamData);
	}

	public bool VerifyChannel(VODPlayer.VODStream.VODStreamChannel ch)
	{
		if (channel.Length == 0 && ch == VODPlayer.VODStream.VODStreamChannel.DEFAULT)
		{
			return true;
		}
		for (int i = 0; i < channel.Length; i++)
		{
			if (channel[i] == ch)
			{
				return true;
			}
		}
		return false;
	}

	protected override void OnLostObservable()
	{
		if (!staticScreen.activeInHierarchy && AlertDisabled != null)
		{
			AlertDisabled(this);
		}
	}

	protected override void OnBecameObservable()
	{
		if (!staticScreen.activeInHierarchy && AlertEnabled != null)
		{
			AlertEnabled(this);
		}
	}

	bool IBuildValidation.BuildValidationCheck()
	{
		if (targetRenderer == null)
		{
			UnityEngine.Debug.LogError("VODTarget " + base.name + " must set a Target Renderer");
			return false;
		}
		return true;
	}

	private void Start()
	{
		targetRenderer.material = ((standbyOverride == null) ? VODPlayer.StandbyMaterial : standbyOverride);
	}

	protected override void UnityOnEnable()
	{
		VODPlayer.OnCrash = (Action)Delegate.Combine(VODPlayer.OnCrash, new Action(VODPlayer_OnCrash));
		if (VODPlayer.state == VODPlayer.State.CRASHED)
		{
			staticScreen.SetActive(value: true);
		}
	}

	protected override void UnityOnDisable()
	{
		VODPlayer.OnCrash = (Action)Delegate.Remove(VODPlayer.OnCrash, new Action(VODPlayer_OnCrash));
	}

	private void OnDestroy()
	{
		VODPlayer.OnCrash = (Action)Delegate.Remove(VODPlayer.OnCrash, new Action(VODPlayer_OnCrash));
	}

	private void VODPlayer_OnCrash()
	{
		staticScreen.SetActive(value: true);
	}

	protected override void ObservableSliceUpdate()
	{
		if (upNextData.Title.IsNullOrEmpty())
		{
			if (upNext.text.Length > 0)
			{
				upNext.text = string.Empty;
			}
		}
		else if (!(GorillaComputer.instance == null))
		{
			TimeSpan timeSpan = upNextData.StartTime - GorillaComputer.instance.GetServerTime();
			upNext.text = $"next: {upNextData.Title} - {timeSpan.Minutes:00}:{timeSpan.Seconds:00}";
		}
	}

	public void ShowStatic(bool on)
	{
		staticScreen.SetActive(on);
		if (on)
		{
			if (observable && AlertDisabled != null)
			{
				AlertDisabled(this);
			}
		}
		else if (observable && AlertEnabled != null)
		{
			AlertEnabled(this);
		}
	}
}
public class SkyboxController : MonoBehaviour
{
	public MeshRenderer skyFront;

	public MeshRenderer skyBack;

	public Material[] skyMaterials = new Material[0];

	[Range(0f, 1f)]
	public float lerpValue;

	[NonSerialized]
	private Material _currentSky;

	[NonSerialized]
	private Material _nextSky;

	private TimeSince lastUpdate = TimeSince.Now();

	[Space]
	private BetterDayNightManager _dayNightManager;

	private double _currentSeconds = -1.0;

	private double _totalSecondsInRange = -1.0;

	private float _currentTime = -1f;

	private void Start()
	{
		if (_dayNightManager.AsNull() == null)
		{
			_dayNightManager = BetterDayNightManager.instance;
		}
		if (!(_dayNightManager.AsNull() == null))
		{
			for (int i = 0; i < _dayNightManager.timeOfDayRange.Length; i++)
			{
				_totalSecondsInRange += _dayNightManager.timeOfDayRange[i] * 3600.0;
			}
			_totalSecondsInRange = System.Math.Floor(_totalSecondsInRange);
		}
	}

	private void Update()
	{
		if (lastUpdate.HasElapsed(1f, resetOnElapsed: true))
		{
			UpdateTime();
			UpdateSky();
		}
	}

	private void OnValidate()
	{
		UpdateSky();
	}

	private void UpdateTime()
	{
		_currentSeconds = ((ITimeOfDaySystem)_dayNightManager).currentTimeInSeconds;
		_currentSeconds = System.Math.Floor(_currentSeconds);
		_currentTime = (float)(_currentSeconds / _totalSecondsInRange);
	}

	private void UpdateSky()
	{
		if (skyMaterials != null && skyMaterials.Length != 0)
		{
			int num = skyMaterials.Length;
			float num2 = Mathf.Clamp(_currentTime, 0f, 1f);
			float num3 = 1f / (float)num;
			int num4 = (int)(num2 / num3);
			float num5 = (num2 - (float)num4 * num3) / num3;
			_currentSky = skyMaterials[num4];
			_nextSky = skyMaterials[(num4 + 1) % num];
			skyFront.sharedMaterial = _currentSky;
			skyBack.sharedMaterial = _nextSky;
			if (_currentSky.renderQueue != 3000)
			{
				SetFrontToTransparent();
			}
			if (_nextSky.renderQueue == 3000)
			{
				SetBackToOpaque();
			}
			_currentSky.SetFloat(ShaderProps._SkyAlpha, 1f - num5);
		}
	}

	private void SetFrontToTransparent()
	{
		bool flag = false;
		bool flag2 = false;
		string val = "Transparent";
		int renderQueue = 3000;
		BlendMode blendMode = BlendMode.SrcAlpha;
		BlendMode blendMode2 = BlendMode.OneMinusSrcAlpha;
		BlendMode blendMode3 = BlendMode.One;
		BlendMode blendMode4 = BlendMode.OneMinusSrcAlpha;
		Material sharedMaterial = skyFront.sharedMaterial;
		sharedMaterial.SetFloat(ShaderProps._ZWrite, flag ? 1f : 0f);
		sharedMaterial.SetShaderPassEnabled("DepthOnly", flag);
		sharedMaterial.SetFloat(ShaderProps._AlphaToMask, flag2 ? 1f : 0f);
		sharedMaterial.SetOverrideTag("RenderType", val);
		sharedMaterial.renderQueue = renderQueue;
		sharedMaterial.SetFloat(ShaderProps._SrcBlend, (float)blendMode);
		sharedMaterial.SetFloat(ShaderProps._DstBlend, (float)blendMode2);
		sharedMaterial.SetFloat(ShaderProps._SrcBlendAlpha, (float)blendMode3);
		sharedMaterial.SetFloat(ShaderProps._DstBlendAlpha, (float)blendMode4);
	}

	private void SetFrontToOpaque()
	{
		bool flag = false;
		bool flag2 = false;
		flag = true;
		string val = "Opaque";
		int renderQueue = 2000;
		BlendMode blendMode = BlendMode.One;
		BlendMode blendMode2 = BlendMode.Zero;
		BlendMode blendMode3 = BlendMode.One;
		BlendMode blendMode4 = BlendMode.Zero;
		Material sharedMaterial = skyFront.sharedMaterial;
		sharedMaterial.SetFloat(ShaderProps._ZWrite, flag ? 1f : 0f);
		sharedMaterial.SetShaderPassEnabled("DepthOnly", flag);
		sharedMaterial.SetFloat(ShaderProps._AlphaToMask, flag2 ? 1f : 0f);
		sharedMaterial.SetOverrideTag("RenderType", val);
		sharedMaterial.renderQueue = renderQueue;
		sharedMaterial.SetFloat(ShaderProps._SrcBlend, (float)blendMode);
		sharedMaterial.SetFloat(ShaderProps._DstBlend, (float)blendMode2);
		sharedMaterial.SetFloat(ShaderProps._SrcBlendAlpha, (float)blendMode3);
		sharedMaterial.SetFloat(ShaderProps._DstBlendAlpha, (float)blendMode4);
	}

	private void SetBackToOpaque()
	{
		bool flag = false;
		bool flag2 = false;
		flag = true;
		string val = "Opaque";
		int renderQueue = 2000;
		BlendMode blendMode = BlendMode.One;
		BlendMode blendMode2 = BlendMode.Zero;
		BlendMode blendMode3 = BlendMode.One;
		BlendMode blendMode4 = BlendMode.Zero;
		Material sharedMaterial = skyBack.sharedMaterial;
		sharedMaterial.SetFloat(ShaderProps._ZWrite, flag ? 1f : 0f);
		sharedMaterial.SetShaderPassEnabled("DepthOnly", flag);
		sharedMaterial.SetFloat(ShaderProps._AlphaToMask, flag2 ? 1f : 0f);
		sharedMaterial.SetOverrideTag("RenderType", val);
		sharedMaterial.renderQueue = renderQueue;
		sharedMaterial.SetFloat(ShaderProps._SrcBlend, (float)blendMode);
		sharedMaterial.SetFloat(ShaderProps._DstBlend, (float)blendMode2);
		sharedMaterial.SetFloat(ShaderProps._SrcBlendAlpha, (float)blendMode3);
		sharedMaterial.SetFloat(ShaderProps._DstBlendAlpha, (float)blendMode4);
	}
}
public class MetroBlimp : MonoBehaviour
{
	public MetroSpotlight spotLightLeft;

	public MetroSpotlight spotLightRight;

	[Space]
	public BoxCollider topCollider;

	public Material blimpMaterial;

	public Renderer blimpRenderer;

	[Space]
	public float ascendSpeed = 1f;

	public float descendSpeed = 0.5f;

	public float descendOffset = -24.1f;

	public float descendReactionTime = 3f;

	[NonSerialized]
	[Space]
	private float _startLocalHeight;

	[NonSerialized]
	private float _topStayTime;

	[NonSerialized]
	private float _numHandsOnBlimp;

	[NonSerialized]
	private bool _lowering;

	private const string _INNER_GLOW = "_INNER_GLOW";

	private void Awake()
	{
		_startLocalHeight = base.transform.localPosition.y;
	}

	public void Tick()
	{
		bool flag = Mathf.Sin(Time.time * 2f) * 0.5f + 0.5f < 0.0001f;
		int num = Mathf.CeilToInt(_numHandsOnBlimp / 2f);
		if (_numHandsOnBlimp == 0f)
		{
			_topStayTime = 0f;
			if (flag)
			{
				blimpRenderer.material.DisableKeyword("_INNER_GLOW");
			}
		}
		else
		{
			_topStayTime += Time.deltaTime;
			if (flag)
			{
				blimpRenderer.material.EnableKeyword("_INNER_GLOW");
			}
		}
		UnityEngine.Vector3 localPosition = base.transform.localPosition;
		UnityEngine.Vector3 b = localPosition;
		float y = b.y;
		float num2 = _startLocalHeight + descendOffset;
		float deltaTime = Time.deltaTime;
		if (num > 0)
		{
			if (y > num2)
			{
				b += UnityEngine.Vector3.down * (descendSpeed * (float)num * deltaTime);
			}
		}
		else if (y < _startLocalHeight)
		{
			b += UnityEngine.Vector3.up * (ascendSpeed * deltaTime);
		}
		base.transform.localPosition = UnityEngine.Vector3.Slerp(localPosition, b, 0.5f);
	}

	private static bool IsPlayerHand(Collider c)
	{
		return c.gameObject.IsOnLayer(UnityLayer.GorillaHand);
	}

	private void OnTriggerEnter(Collider other)
	{
		if (IsPlayerHand(other))
		{
			_numHandsOnBlimp += 1f;
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (IsPlayerHand(other))
		{
			_numHandsOnBlimp -= 1f;
		}
	}
}
