public class RotateXform : MonoBehaviour
{
	public enum Mode
	{
		Local,
		World
	}

	public Transform xform;

	public UnityEngine.Vector3 speed = UnityEngine.Vector3.zero;

	public Mode mode;

	public float speedFactor = 0.0625f;

	private void Update()
	{
		if ((bool)xform)
		{
			UnityEngine.Vector3 vector = ((mode == Mode.Local) ? xform.localEulerAngles : xform.eulerAngles);
			float num = Time.deltaTime * speedFactor;
			vector.x += speed.x * num;
			vector.y += speed.y * num;
			vector.z += speed.z * num;
			if (mode == Mode.Local)
			{
				xform.localEulerAngles = vector;
			}
			else
			{
				xform.eulerAngles = vector;
			}
		}
	}
}
public class TempMask : MonoBehaviour
{
	public int year;

	public int month;

	public int day;

	public DateTime dayOn;

	public MeshRenderer myRenderer;

	private DateTime myDate;

	private VRRig myRig;

	private void Awake()
	{
		dayOn = new DateTime(year, month, day);
		myRig = GetComponentInParent<VRRig>();
		if (myRig != null && myRig.netView.IsMine && !myRig.isOfflineVRRig)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void OnEnable()
	{
		StartCoroutine(MaskOnDuringDate());
	}

	private void OnDisable()
	{
		StopAllCoroutines();
	}

	private IEnumerator MaskOnDuringDate()
	{
		while (true)
		{
			if (GorillaComputer.instance != null && GorillaComputer.instance.startupMillis != 0L)
			{
				myDate = new DateTime(GorillaComputer.instance.startupMillis * 10000 + (long)(Time.realtimeSinceStartup * 1000f * 10000f)).Subtract(TimeSpan.FromHours(7.0));
				if (myDate.DayOfYear == dayOn.DayOfYear)
				{
					if (!myRenderer.enabled)
					{
						myRenderer.enabled = true;
					}
				}
				else if (myRenderer.enabled)
				{
					myRenderer.enabled = false;
				}
			}
			yield return new WaitForSeconds(1f);
		}
	}
}
public class BlinkingText : MonoBehaviour
{
	public float cycleTime;

	public float dutyCycle;

	private bool isOn;

	private float lastTime;

	private Text textComponent;

	private void Awake()
	{
		textComponent = GetComponent<Text>();
	}

	private void Update()
	{
		if (isOn && Time.time > lastTime + cycleTime * dutyCycle)
		{
			isOn = false;
			textComponent.enabled = false;
		}
		else if (!isOn && Time.time > lastTime + cycleTime)
		{
			lastTime = Time.time;
			isOn = true;
			textComponent.enabled = true;
		}
	}
}
