public static class MeshExtensions
{
	[BurstCompile]
	private struct FaceNormalJob : IJobParallelFor
	{
		[Unity.Collections.ReadOnly]
		public NativeArray<float3> Verts;

		[Unity.Collections.ReadOnly]
		public NativeArray<int> Tris;

		[WriteOnly]
		public NativeArray<float3> FaceN;

		public void Execute(int index)
		{
			int num = index * 3;
			float3 float5 = Verts[Tris[num]];
			float3 float6 = Verts[Tris[num + 1]];
			float3 float7 = Verts[Tris[num + 2]];
			FaceN[index] = math.normalize(math.cross(float6 - float5, float7 - float5));
		}
	}

	[BurstCompile]
	private struct SplitJob : IJob
	{
		private struct Bucket
		{
			public int next;

			public int newIdx;

			public float3 repN;
		}

		public float CosThresh;

		[Unity.Collections.ReadOnly]
		public NativeArray<float3> SrcVerts;

		[Unity.Collections.ReadOnly]
		public NativeArray<int> SrcTris;

		[Unity.Collections.ReadOnly]
		public NativeArray<float3> FaceN;

		public NativeList<float3> DstVerts;

		public NativeList<int> DstTris;

		public void Execute()
		{
			int length = SrcVerts.Length;
			int num = SrcTris.Length / 3;
			NativeArray<int> nativeArray = new NativeArray<int>(length, Unity.Collections.Allocator.Temp);
			for (int i = 0; i < length; i++)
			{
				nativeArray[i] = -1;
			}
			NativeList<Bucket> nativeList = new NativeList<Bucket>(length, Unity.Collections.Allocator.Temp);
			DstVerts.Clear();
			DstTris.ResizeUninitialized(SrcTris.Length);
			for (int j = 0; j < num; j++)
			{
				float3 float5 = FaceN[j];
				for (int k = 0; k < 3; k++)
				{
					int index = SrcTris[j * 3 + k];
					int num2 = -1;
					for (int num3 = nativeArray[index]; num3 != -1; num3 = nativeList[num3].next)
					{
						Bucket bucket = nativeList[num3];
						if (math.dot(bucket.repN, float5) >= CosThresh)
						{
							num2 = bucket.newIdx;
							break;
						}
					}
					if (num2 == -1)
					{
						num2 = DstVerts.Length;
						DstVerts.Add(SrcVerts[index]);
						Bucket value = new Bucket
						{
							next = nativeArray[index],
							newIdx = num2,
							repN = float5
						};
						nativeArray[index] = nativeList.Length;
						nativeList.Add(in value);
					}
					DstTris[j * 3 + k] = num2;
				}
			}
			nativeArray.Dispose();
			nativeList.Dispose();
		}
	}

	[BurstCompile]
	private struct TriNormalJob : IJobParallelFor
	{
		[Unity.Collections.ReadOnly]
		public NativeArray<float3> V;

		[Unity.Collections.ReadOnly]
		public NativeArray<int> T;

		[WriteOnly]
		public NativeArray<float3> Out;

		public int AreaWeight;

		public void Execute(int i)
		{
			int num = i * 3;
			float3 float5 = V[T[num]];
			float3 obj = V[T[num + 1]];
			float3 float6 = math.cross(y: V[T[num + 2]] - float5, x: obj - float5);
			Out[i] = ((AreaWeight == 0) ? math.normalize(float6) : float6);
		}
	}

	[BurstCompile]
	private struct BuildAdjJob : IJobParallelFor
	{
		[Unity.Collections.ReadOnly]
		public NativeArray<int> T;

		public NativeParallelMultiHashMap<int, int>.ParallelWriter MapW;

		public void Execute(int triIdx)
		{
			int num = triIdx * 3;
			MapW.Add(T[num], triIdx);
			MapW.Add(T[num + 1], triIdx);
			MapW.Add(T[num + 2], triIdx);
		}
	}

	[BurstCompile]
	private struct VertexNormalJob : IJobParallelFor
	{
		public int AreaWeight;

		[Unity.Collections.ReadOnly]
		public NativeArray<float3> TriN;

		[Unity.Collections.ReadOnly]
		public NativeParallelMultiHashMap<int, int> V2T;

		[WriteOnly]
		public NativeArray<float3> Out;

		public void Execute(int v)
		{
			NativeParallelMultiHashMap<int, int>.Enumerator valuesForKey = V2T.GetValuesForKey(v);
			if (!valuesForKey.MoveNext())
			{
				Out[v] = float3.zero;
				return;
			}
			int current = valuesForKey.Current;
			float3 float5 = TriN[current];
			float3 float6 = ((AreaWeight == 0) ? float5 : math.normalize(float5));
			float3 zero = float3.zero;
			NativeParallelMultiHashMap<int, int>.Enumerator valuesForKey2 = V2T.GetValuesForKey(v);
			while (valuesForKey2.MoveNext())
			{
				float3 float7 = TriN[valuesForKey2.Current];
				if (AreaWeight != 0)
				{
					math.normalize(float7);
				}
				zero += float7;
			}
			Out[v] = ((math.lengthsq(zero) < 1E-09f) ? float6 : math.normalize(zero));
		}
	}

	public static void SplitByAngle(this Mesh mesh, float angleDeg)
	{
		float num = Mathf.Cos(angleDeg * (MathF.PI / 180f));
		UnityEngine.Vector3[] vertices = mesh.vertices;
		int[] triangles = mesh.triangles;
		int num2 = triangles.Length / 3;
		UnityEngine.Vector3[] array = new UnityEngine.Vector3[num2];
		for (int i = 0; i < num2; i++)
		{
			UnityEngine.Vector3 vector = vertices[triangles[i * 3]];
			UnityEngine.Vector3 vector2 = vertices[triangles[i * 3 + 1]];
			UnityEngine.Vector3 vector3 = vertices[triangles[i * 3 + 2]];
			array[i] = UnityEngine.Vector3.Cross(vector2 - vector, vector3 - vector).normalized;
		}
		List<(int, UnityEngine.Vector3)>[] array2 = new List<(int, UnityEngine.Vector3)>[vertices.Length];
		for (int j = 0; j < array2.Length; j++)
		{
			array2[j] = new List<(int, UnityEngine.Vector3)>();
		}
		List<UnityEngine.Vector3> list = new List<UnityEngine.Vector3>(vertices.Length);
		int[] array3 = new int[triangles.Length];
		for (int k = 0; k < num2; k++)
		{
			for (int l = 0; l < 3; l++)
			{
				int num3 = triangles[k * 3 + l];
				UnityEngine.Vector3 vector4 = array[k];
				int num4 = -1;
				foreach (var item in array2[num3])
				{
					var (num5, _) = item;
					if (UnityEngine.Vector3.Dot(item.Item2, vector4) >= num)
					{
						num4 = num5;
						break;
					}
				}
				if (num4 < 0)
				{
					num4 = list.Count;
					list.Add(vertices[num3]);
					array2[num3].Add((num4, vector4));
				}
				array3[k * 3 + l] = num4;
			}
		}
		mesh.Clear();
		mesh.SetVertices(list);
		mesh.triangles = array3;
		mesh.RecalculateNormals();
		mesh.RecalculateBounds();
	}

	public static void SplitByAngleBurst(this Mesh mesh, float angleDeg, bool areaWeight = true, Unity.Collections.Allocator allocator = Unity.Collections.Allocator.TempJob)
	{
		NativeArray<float3> nativeArray = new NativeArray<float3>(mesh.vertexCount, allocator);
		List<UnityEngine.Vector3> list = new List<UnityEngine.Vector3>(mesh.vertexCount);
		mesh.GetVertices(list);
		for (int i = 0; i < list.Count; i++)
		{
			nativeArray[i] = list[i];
		}
		NativeArray<int> nativeArray2 = new NativeArray<int>(mesh.triangles, allocator);
		NativeArray<float3> faceN = new NativeArray<float3>(nativeArray2.Length / 3, allocator);
		IJobParallelForExtensions.Schedule(new FaceNormalJob
		{
			Verts = nativeArray,
			Tris = nativeArray2,
			FaceN = faceN
		}, faceN.Length, 64).Complete();
		NativeList<float3> nativeList = new NativeList<float3>(nativeArray.Length, allocator);
		NativeList<int> nativeList2 = new NativeList<int>(nativeArray2.Length, allocator);
		new SplitJob
		{
			CosThresh = math.cos(math.radians(angleDeg)),
			SrcVerts = nativeArray,
			SrcTris = nativeArray2,
			FaceN = faceN,
			DstVerts = nativeList,
			DstTris = nativeList2
		}.Run();
		NativeArray<float3> outNormals = new NativeArray<float3>(nativeList.Length, allocator);
		RecalcNormalsJobified(nativeList, nativeList2, areaWeight, allocator, ref outNormals);
		mesh.Clear();
		List<UnityEngine.Vector3> list2 = new List<UnityEngine.Vector3>(nativeList.Length);
		for (int j = 0; j < nativeList.Length; j++)
		{
			list2.Add(nativeList[j]);
		}
		mesh.SetVertices(list2);
		mesh.triangles = nativeList2.AsArray().ToArray();
		List<UnityEngine.Vector3> list3 = new List<UnityEngine.Vector3>(outNormals.Length);
		for (int k = 0; k < outNormals.Length; k++)
		{
			list3.Add(outNormals[k]);
		}
		mesh.SetNormals(list3);
		mesh.RecalculateBounds();
		nativeArray.Dispose();
		nativeArray2.Dispose();
		faceN.Dispose();
		nativeList.Dispose();
		nativeList2.Dispose();
		outNormals.Dispose();
	}

	private static void RecalcNormalsJobified(NativeList<float3> verts, NativeList<int> tris, bool areaWeight, Unity.Collections.Allocator alloc, ref NativeArray<float3> outNormals)
	{
		int length = verts.Length;
		int num = tris.Length / 3;
		NativeArray<float3> nativeArray = new NativeArray<float3>(num, alloc);
		IJobParallelForExtensions.Schedule(new TriNormalJob
		{
			V = verts.AsArray(),
			T = tris.AsArray(),
			Out = nativeArray,
			AreaWeight = (areaWeight ? 1 : 0)
		}, num, 64).Complete();
		NativeParallelMultiHashMap<int, int> v2T = new NativeParallelMultiHashMap<int, int>(tris.Length, alloc);
		IJobParallelForExtensions.Schedule(new BuildAdjJob
		{
			T = tris.AsArray(),
			MapW = v2T.AsParallelWriter()
		}, num, 64).Complete();
		IJobParallelForExtensions.Schedule(new VertexNormalJob
		{
			AreaWeight = (areaWeight ? 1 : 0),
			TriN = nativeArray,
			V2T = v2T,
			Out = outNormals
		}, length, 64).Complete();
		nativeArray.Dispose();
		v2T.Dispose();
	}
}
public static class NativeCollectionExtensions
{
	public static T[] ToArray<T>(this NativeList<T> list) where T : unmanaged
	{
		return list.AsArray().ToArray();
	}

	public static List<T> ToList<T>(this NativeList<T> list) where T : unmanaged
	{
		List<T> list2 = new List<T>(list.Length);
		for (int i = 0; i < list.Length; i++)
		{
			list2.Add(list[i]);
		}
		return list2;
	}
}
public static class JamUtil
{
	public static bool IsPlaying => UnityEngine.Application.isPlaying;

	public static void Destroy(UnityEngine.Object obj)
	{
		UnityEngine.Object.Destroy(obj);
	}

	public static RaycastHit ToRaycastHit(this UnityEngine.Collision collision)
	{
		if (!collision.ConvertToRaycast(out var hit))
		{
			GTDev.LogError($"No hit! ({collision})");
		}
		return hit;
	}

	public static bool ConvertToRaycast(this UnityEngine.Collision collision, out RaycastHit hit)
	{
		ContactPoint contact = collision.GetContact(0);
		UnityEngine.Vector3 point = contact.point;
		UnityEngine.Vector3 normal = contact.normal;
		LayerMask layerMask = 1 << collision.gameObject.layer;
		return Physics.Raycast(new Ray(point + normal * 0.1f, -normal), out hit, 0.2f, layerMask, QueryTriggerInteraction.Ignore);
	}
}
public static class MathHelper
{
	public static float RoundTo(this float value, float increment)
	{
		return Mathf.Floor(value / increment + 0.5f) * increment;
	}

	public static UnityEngine.Vector3 RoundTo(this UnityEngine.Vector3 value, float increment)
	{
		value.x = Mathf.Floor(value.x / increment + 0.5f) * increment;
		value.y = Mathf.Floor(value.y / increment + 0.5f) * increment;
		value.z = Mathf.Floor(value.z / increment + 0.5f) * increment;
		return value;
	}

	public static UnityEngine.Vector3 SnapToInt(this UnityEngine.Vector3 value)
	{
		value.x = Mathf.Floor(value.x + 0.5f);
		value.y = Mathf.Floor(value.y + 0.5f);
		value.z = Mathf.Floor(value.z + 0.5f);
		return value;
	}

	public static UnityEngine.Quaternion RoundTo(this UnityEngine.Quaternion value, float increment)
	{
		UnityEngine.Vector3 eulerAngles = value.eulerAngles;
		eulerAngles.x = Mathf.Floor(eulerAngles.x / increment + 0.5f) * increment;
		eulerAngles.y = Mathf.Floor(eulerAngles.y / increment + 0.5f) * increment;
		eulerAngles.z = Mathf.Floor(eulerAngles.z / increment + 0.5f) * increment;
		value.eulerAngles = eulerAngles;
		return value;
	}

	public static UnityEngine.Quaternion SnapToCardinal(this UnityEngine.Quaternion value)
	{
		UnityEngine.Vector3 eulerAngles = value.eulerAngles;
		eulerAngles.x = (eulerAngles.z = 0f);
		eulerAngles.y = Mathf.Floor(eulerAngles.y / 90f + 0.5f) * 90f;
		return UnityEngine.Quaternion.Euler(eulerAngles);
	}

	public static bool IsInBounds(this int3 a, int3 min, int3 max)
	{
		if (min.x <= a.x && max.x >= a.x && min.y <= a.y && max.y >= a.y && min.z <= a.z)
		{
			return max.z >= a.z;
		}
		return false;
	}
}
public class NamedTriggerZone : MonoBehaviour
{
	public string TriggerName = "Trigger";

	private void Reset()
	{
		ConfigureCollider();
	}

	private void ConfigureCollider()
	{
		Collider collider = GetComponent<Collider>();
		if (!collider)
		{
			collider = base.gameObject.AddComponent<BoxCollider>();
		}
		collider.isTrigger = true;
		base.gameObject.layer = LayerMask.NameToLayer("Gorilla Trigger");
	}
}
public static class NativeArrayPool<T> where T : struct
{
	private static Dictionary<int, Stack<NativeArray<T>>> _lookup;

	static NativeArrayPool()
	{
		_lookup = new Dictionary<int, Stack<NativeArray<T>>>();
		UnityEngine.Application.quitting += OnQuit;
	}

	private static void OnQuit()
	{
		Dispose();
	}

	[OnEnterPlay_Run]
	public static void Dispose()
	{
		if (_lookup == null)
		{
			return;
		}
		foreach (Stack<NativeArray<T>> value in _lookup.Values)
		{
			foreach (NativeArray<T> item in value)
			{
				item.Dispose();
			}
		}
		_lookup.Clear();
	}

