	{
		if (a.Contains(b.min))
		{
			return a.Contains(b.max);
		}
		return false;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.BoundsInt Union(this UnityEngine.BoundsInt a, UnityEngine.BoundsInt b)
	{
		return new UnityEngine.BoundsInt(VectorUtilities.Min(a.min, b.min), VectorUtilities.Max(a.max, b.max));
	}

	public static UnityEngine.BoundsInt GetBounds(this VoxelWorld world, float3 point, float radius)
	{
		int3 voxelForLocalPosition = world.GetVoxelForLocalPosition(point);
		int num = Mathf.CeilToInt(radius);
		return new UnityEngine.BoundsInt((voxelForLocalPosition - num).ToVectorInt(), new int3(num * 2).ToVectorInt());
	}

	private static UnityEngine.Vector3 GetTriangleCenter(RaycastHit hit)
	{
		var (vector, vector2, vector3) = GetWorldTriangle(hit);
		return (vector + vector2 + vector3) / 3f;
	}

	private static (UnityEngine.Vector3 v1, UnityEngine.Vector3 v2, UnityEngine.Vector3 v3) GetWorldTriangle(RaycastHit hit)
	{
		if (hit.collider is MeshCollider { sharedMesh: var sharedMesh } meshCollider)
		{
			if (sharedMesh == null || hit.triangleIndex < 0 || hit.triangleIndex >= sharedMesh.triangles.Length / 3)
			{
				UnityEngine.Debug.LogWarning($"Invalid triangle index {hit.triangleIndex} for mesh {sharedMesh?.name}");
				return (v1: UnityEngine.Vector3.zero, v2: UnityEngine.Vector3.zero, v3: UnityEngine.Vector3.zero);
			}
			int[] triangles = sharedMesh.triangles;
			UnityEngine.Vector3[] vertices = sharedMesh.vertices;
			Transform transform = meshCollider.transform;
			UnityEngine.Vector3 item = transform.TransformPoint(vertices[triangles[hit.triangleIndex * 3]]);
			UnityEngine.Vector3 item2 = transform.TransformPoint(vertices[triangles[hit.triangleIndex * 3 + 1]]);
			UnityEngine.Vector3 item3 = transform.TransformPoint(vertices[triangles[hit.triangleIndex * 3 + 2]]);
			return (v1: item, v2: item2, v3: item3);
		}
		return (v1: UnityEngine.Vector3.zero, v2: UnityEngine.Vector3.zero, v3: UnityEngine.Vector3.zero);
	}

	public static string GetFullPath(this UnityEngine.Component component)
	{
		if (!component)
		{
			return "";
		}
		return component.gameObject.GetFullPath() + "/" + component.GetType().Name;
	}

	public static string GetFullPath(this GameObject go)
	{
		if (!go)
		{
			return "";
		}
		string text = go.name;
		Transform parent = go.transform.parent;
		while ((bool)parent)
		{
			text = parent.name + "/" + text;
			parent = parent.parent;
		}
		return go.scene.name + "/" + text;
	}

	public static int GenerateHashcodeFromPath(this UnityEngine.Component component)
	{
		return component.GetFullPath().GetHashCode();
	}

	public static int GenerateHashcodeFromPath(this GameObject go)
	{
		return go.GetFullPath().GetHashCode();
	}
}
public class VoxelInteractor : MonoBehaviour
{
	[SerializeField]
	private LayerMask layerMask = 1;

	[SerializeField]
	private float rayLength = 0.1f;

	[SerializeField]
	private float cooldown = 0.25f;

	[SerializeField]
	private VoxelAction action = new VoxelAction
	{
		strength = 0.5f,
		radius = 0.5f,
		operation = OperationType.Subtract
	};

	private bool _active;

	private Coroutine _actionRoutine;

	private float _nextActionTime;

	[OnEnterPlay_SetNull]
	private static List<VoxelWorld> _hitWorlds;

	[OnEnterPlay_SetNull]
	private static Collider[] _hitColliders;

	private void OnDisable()
	{
		StopOngoingAction();
	}

	public void StartOngoingAction()
	{
		if (!_active)
		{
			if (_actionRoutine != null)
			{
				StopCoroutine(_actionRoutine);
			}
			_active = true;
			_actionRoutine = StartCoroutine(DoContinuousAction());
		}
	}

	public void StopOngoingAction()
	{
		if (_actionRoutine != null)
		{
			StopCoroutine(_actionRoutine);
			_actionRoutine = null;
		}
		_active = false;
	}

	public void PerformAction()
	{
		if (Time.time < _nextActionTime)
		{
			return;
		}
		if (Physics.Linecast(base.transform.position, base.transform.position + base.transform.forward * rayLength, out var hitInfo, layerMask, QueryTriggerInteraction.Ignore))
		{
			ChunkComponent component = hitInfo.collider.GetComponent<ChunkComponent>();
			if ((bool)component)
			{
				component.World.Mine(hitInfo, action);
			}
		}
		_nextActionTime = Time.time + cooldown;
	}

	public void PerformActionOmnidirectional()
	{
		if (Time.time < _nextActionTime)
		{
			return;
		}
		if (_hitWorlds == null)
		{
			_hitWorlds = new List<VoxelWorld>();
		}
		if (_hitColliders == null)
		{
			_hitColliders = new Collider[5];
		}
		_hitWorlds.Clear();
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, action.radius, _hitColliders, layerMask);
		if (num == _hitColliders.Length)
		{
			Array.Resize(ref _hitColliders, _hitColliders.Length * 2);
		}
		for (int i = 0; i < num; i++)
		{
			if (_hitColliders[i].TryGetComponent<ChunkComponent>(out var component) && !_hitWorlds.Contains(component.World))
			{
				_hitWorlds.Add(component.World);
				component.World.PerformAction(base.transform.position, action);
			}
		}
		_nextActionTime = Time.time + cooldown;
	}

	private IEnumerator DoContinuousAction()
	{
		while (_active)
		{
			while (Time.time < _nextActionTime)
			{
				yield return null;
			}
			if (_active)
			{
				PerformAction();
			}
		}
		_actionRoutine = null;
	}

	public bool ApplyVoxelAction(UnityEngine.Collision collision)
	{
		ChunkComponent component = collision.gameObject.GetComponent<ChunkComponent>();
		if ((bool)component)
		{
			component.World.Mine(collision, action);
		}
		return component;
	}

	public bool ApplyVoxelAction(RaycastHit hit)
	{
		ChunkComponent component = hit.collider.GetComponent<ChunkComponent>();
		if ((bool)component)
		{
			component.World.Mine(hit, action);
		}
		return component;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		UnityEngine.Vector3 vector = base.transform.position + base.transform.forward * rayLength;
		Gizmos.DrawLine(base.transform.position, vector);
		Gizmos.DrawWireSphere(base.transform.position, 0.01f);
		Gizmos.DrawWireSphere(vector, 0.01f);
	}
}
public class VoxelMaterialManager : MonoBehaviour
{
	[Serializable]
	public struct LightingProfile
	{
		public Color color;

		public UnityEngine.Vector3 direction;
	}

	public Material[] voxelMats;

	public List<string> lightmapNames;

	public List<LightingProfile> lightingProfiles;

	[Range(0f, 1f)]
	[SerializeField]
	private float shadowBrightness = 0.3f;

	[Range(0f, 1f)]
	[SerializeField]
	private float backlightBrightness = 0.2f;

	[SerializeField]
	private int startingIndex = 2;

	private int _timeOfDayIndex = -1;

	private void OnEnable()
	{
		SetLightingProfile(startingIndex);
	}

	private void Update()
	{
		if (_timeOfDayIndex != BetterDayNightManager.instance.currentTimeIndex)
		{
			UpdateMaterial();
		}
	}

	private void UpdateMaterial()
	{
		string currentTimeOfDay = BetterDayNightManager.instance.currentTimeOfDay;
		if (!string.IsNullOrEmpty(currentTimeOfDay))
		{
			int num = lightmapNames.IndexOf(currentTimeOfDay);
			if (num >= 0 && num < lightingProfiles.Count)
			{
				SetLightingProfile(num);
				_timeOfDayIndex = BetterDayNightManager.instance.currentTimeIndex;
			}
		}
	}

	private void SetLightingProfile(int index)
	{
		index = Mathf.Clamp(index, 0, lightingProfiles.Count - 1);
		LightingProfile lightingProfile = lightingProfiles[index];
		Shader.SetGlobalVector("_Light_Direction", lightingProfile.direction);
		Shader.SetGlobalColor("_Light_Color", lightingProfile.color);
		Shader.SetGlobalColor("_Shadow_Color", lightingProfile.color * shadowBrightness);
		Shader.SetGlobalColor("_Backlight_Color", lightingProfile.color * backlightBrightness);
		_timeOfDayIndex = index;
	}
}
public class Voxel_Pickaxe : MonoBehaviour, IGameEntityComponent
{
	[Serializable]
	public struct InteractionPoint
	{
		public Transform transform;

		public UnityEngine.Vector3 previousPosition;

		public UnityEngine.Vector3 position;
	}

	public VoxelAction mine = new VoxelAction
	{
		strength = 1f,
		radius = 0.5f,
		operation = OperationType.Subtract
	};

	public InteractionPoint[] points;

	public AudioResource goodHit;

	public AudioResource badHit;

	public AudioSource sound;

	public float hitCooldown = 0.5f;

	public float minHitSpeed = 1f;

	public float minMineSpeed = 5f;

	public float alignThreshold = 0.7f;

	private GameEntity _gameEntity;

	private int _layerMask;

	private float _nextHitTime;

	private bool _isLocal;

	public bool Held { get; set; }

	private void Reset()
	{
		_layerMask = LayerMask.GetMask("Default");
	}

	private void Awake()
	{
		_gameEntity = GetComponent<GameEntity>();
		_layerMask = LayerMask.GetMask("Default");
		if (sound.transform == base.transform)
		{
			UnityEngine.Debug.LogError("Audio source for " + base.name + " must be on a separate gameobject!", this);
		}
	}

	private void OnEnable()
	{
		if (_gameEntity != null)
		{
			GameEntity gameEntity = _gameEntity;
			gameEntity.OnGrabbed = (Action)Delegate.Combine(gameEntity.OnGrabbed, new Action(StartGrabbing));
			GameEntity gameEntity2 = _gameEntity;
			gameEntity2.OnReleased = (Action)Delegate.Combine(gameEntity2.OnReleased, new Action(StopGrabbing));
		}
		_isLocal = GetComponentInParent<VRRig>() == VRRig.LocalRig;
		ResetVelocity();
	}

	private void OnDisable()
	{
		if (_gameEntity != null)
		{
			GameEntity gameEntity = _gameEntity;
			gameEntity.OnGrabbed = (Action)Delegate.Remove(gameEntity.OnGrabbed, new Action(StartGrabbing));
			GameEntity gameEntity2 = _gameEntity;
			gameEntity2.OnReleased = (Action)Delegate.Remove(gameEntity2.OnReleased, new Action(StopGrabbing));
		}
	}

	private void FixedUpdate()
	{
		if (Held)
		{
			for (int i = 0; i < points.Length; i++)
			{
				UpdateInteractionPoint(ref points[i]);
			}
		}
	}

	private void StartGrabbing()
	{
		Held = true;
		VRRig componentInParent = GetComponentInParent<VRRig>();
		_isLocal = componentInParent == VRRig.LocalRig;
		ResetVelocity();
	}

	private void StopGrabbing()
	{
		Held = false;
	}

	private void ResetVelocity()
	{
		for (int i = 0; i < points.Length; i++)
		{
			points[i].position = (points[i].previousPosition = points[i].transform.position);
		}
	}

	private void UpdateInteractionPoint(ref InteractionPoint point)
	{
		point.previousPosition = point.position;
		point.position = point.transform.position;
		if (Time.time < _nextHitTime)
		{
			return;
		}
		UnityEngine.Vector3 vector = (point.position - point.previousPosition) / Time.fixedDeltaTime;
		float magnitude = vector.magnitude;
		if (magnitude < minHitSpeed)
		{
			return;
		}
		bool flag = UnityEngine.Vector3.Dot(vector.normalized, point.transform.forward) >= alignThreshold;
		if (!Physics.Linecast(point.previousPosition, point.position, out var hitInfo, _layerMask, QueryTriggerInteraction.Ignore))
		{
			return;
		}
		ChunkComponent component = hitInfo.collider.GetComponent<ChunkComponent>();
		if ((bool)component && flag && magnitude >= minMineSpeed)
		{
			Play(goodHit, hitInfo.point);
			if (_isLocal)
			{
				component.World.Mine(hitInfo, mine);
			}
		}
		else
		{
			Play(badHit, hitInfo.point);
		}
		_nextHitTime = Time.time + hitCooldown;
	}

	private void Play(AudioResource resource, UnityEngine.Vector3 position)
	{
		if ((bool)resource)
		{
			sound.Stop();
			sound.resource = resource;
			sound.transform.position = position;
			sound.Play();
		}
	}

	public void OnEntityInit()
	{
		if (sound != null)
		{
			sound.transform.parent = null;
		}
	}

	public void OnEntityDestroy()
	{
		if (!ApplicationQuittingState.IsQuitting && !(this == null) && !(sound == null) && base.gameObject.scene.isLoaded)
		{
			sound.transform.parent = base.transform;
		}
	}

	public void OnEntityStateChange(long prevState, long newState)
	{
	}

	private void OnDrawGizmosSelected()
	{
		if (points != null)
		{
			Gizmos.color = Color.green;
			InteractionPoint[] array = points;
			for (int i = 0; i < array.Length; i++)
			{
				InteractionPoint interactionPoint = array[i];
				Gizmos.DrawWireSphere(interactionPoint.transform.position, 0.02f);
				Gizmos.DrawLine(interactionPoint.transform.position, interactionPoint.transform.position + interactionPoint.transform.forward * 0.5f);
			}
		}
	}
}
