public class FingerFlagTwirlTest : MonoBehaviour
{
	public UnityEngine.Vector3 rotAnimDurations = new UnityEngine.Vector3(0.2f, 0.1f, 0.5f);

	public UnityEngine.Vector3 rotAnimAmplitudes = UnityEngine.Vector3.one * 360f;

	public AnimationCurve rotXAnimCurve;

	public AnimationCurve rotYAnimCurve;

	public AnimationCurve rotZAnimCurve;

	private UnityEngine.Vector3 animTimes = UnityEngine.Vector3.zero;

	protected void FixedUpdate()
	{
		animTimes += Time.deltaTime * rotAnimDurations;
		animTimes.x %= 1f;
		animTimes.y %= 1f;
		animTimes.z %= 1f;
		base.transform.localRotation = UnityEngine.Quaternion.Euler(rotXAnimCurve.Evaluate(animTimes.x) * rotAnimAmplitudes.x, rotYAnimCurve.Evaluate(animTimes.y) * rotAnimAmplitudes.y, rotZAnimCurve.Evaluate(animTimes.z) * rotAnimAmplitudes.z);
	}
}
public class FingerFlagWearable : MonoBehaviour, ISpawnable
{
	[Header("Wearable Settings")]
	public bool attachedToLeftHand = true;

	[Header("Bones")]
	public Transform pinkyRingBone;

	public Transform thumbRingBone;

	public Transform[] clothBones;

	public Transform[] clothRigidbodies;

	[Header("Animation")]
	public Animator animator;

	public float extendSpeed = 1.5f;

	public float retractSpeed = 2.25f;

	[Header("Audio")]
	public AudioSource audioSource;

	public AudioClip extendAudioClip;

	public AudioClip retractAudioClip;

	[Header("Vibration")]
	public float extendVibrationDuration = 0.05f;

	public float extendVibrationStrength = 0.2f;

	public float retractVibrationDuration = 0.05f;

	public float retractVibrationStrength = 0.2f;

	private readonly int retractExtendTimeAnimParam = Animator.StringToHash("retractExtendTime");

	private bool networkedExtended;

	private bool extended;

	private bool fullyRetracted;

	private float retractExtendTime;

	private UnityEngine.XR.InputDevice inputDevice;

	private VRRig myRig;

	private int stateBitIndex;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = GetComponentInParent<VRRig>(includeInactive: true);
		if (!myRig)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	void ISpawnable.OnDespawn()
	{
	}

	protected void OnEnable()
	{
		int num = (attachedToLeftHand ? 1 : 2);
		stateBitIndex = VRRig.WearablePackedStatesBitWriteInfos[num].index;
		OnExtendStateChanged(playAudio: false);
	}

	private void UpdateLocal()
	{
		int node = (attachedToLeftHand ? 4 : 5);
		bool flag = ControllerInputPoller.GripFloat((XRNode)node) > 0.25f;
		bool flag2 = ControllerInputPoller.PrimaryButtonPress((XRNode)node);
		bool flag3 = ControllerInputPoller.SecondaryButtonPress((XRNode)node);
		bool flag4 = flag && (flag2 || flag3);
		networkedExtended = flag4;
		if (PhotonNetwork.InRoom && (bool)myRig)
		{
			myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, stateBitIndex, networkedExtended);
		}
	}

	private void UpdateShared()
	{
		if (extended != networkedExtended)
		{
			extended = networkedExtended;
			OnExtendStateChanged(playAudio: true);
		}
		bool num = fullyRetracted;
		fullyRetracted = extended && retractExtendTime <= 0f;
		if (num != fullyRetracted)
		{
			Transform[] array = clothRigidbodies;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].gameObject.SetActive(!fullyRetracted);
			}
		}
		UpdateAnimation();
	}

	private void UpdateReplicated()
	{
		if (myRig != null && !myRig.isOfflineVRRig)
		{
			networkedExtended = GTBitOps.ReadBit(myRig.WearablePackedStates, stateBitIndex);
		}
	}

	public bool IsMyItem()
	{
		if (myRig != null)
		{
			return myRig.isOfflineVRRig;
		}
		return false;
	}

	protected void LateUpdate()
	{
		if (IsMyItem())
		{
			UpdateLocal();
		}
		else
		{
			UpdateReplicated();
		}
		UpdateShared();
	}

	private void UpdateAnimation()
	{
		float num = (extended ? extendSpeed : (0f - retractSpeed));
		retractExtendTime = Mathf.Clamp01(retractExtendTime + Time.deltaTime * num);
		animator.SetFloat(retractExtendTimeAnimParam, retractExtendTime);
	}

	private void OnExtendStateChanged(bool playAudio)
	{
		audioSource.clip = (extended ? extendAudioClip : retractAudioClip);
		if (playAudio)
		{
			audioSource.GTPlay();
		}
		if (IsMyItem() && (bool)GorillaTagger.Instance)
		{
			GorillaTagger.Instance.StartVibration(attachedToLeftHand, extended ? extendVibrationDuration : retractVibrationDuration, extended ? extendVibrationStrength : retractVibrationStrength);
		}
	}
}
public class SpiderDangler : MonoBehaviour
{
	public struct RopeSegment(UnityEngine.Vector3 pos)
	{
		public UnityEngine.Vector3 pos = pos;

		public UnityEngine.Vector3 posOld = pos;
	}

	public Transform endTransform;

	public UnityEngine.Vector4 spinSpeeds = new UnityEngine.Vector4(0.1f, 0.2f, 0.3f, 0.4f);

	public UnityEngine.Vector4 spinScales = new UnityEngine.Vector4(180f, 90f, 120f, 180f);

	private LineRenderer lineRenderer;

	private RopeSegment[] ropeSegs;

	private float ropeSegLen;

	private float ropeSegLenScaled;

	private const int kSegmentCount = 6;

	private const float kVelocityDamper = 0.95f;

	private const int kConstraintCalculationIterations = 8;

	protected void Awake()
	{
		lineRenderer = GetComponent<LineRenderer>();
		UnityEngine.Vector3 position = base.transform.position;
		float magnitude = (endTransform.position - position).magnitude;
		ropeSegLen = magnitude / 6f;
		ropeSegs = new RopeSegment[6];
		for (int i = 0; i < 6; i++)
		{
			ropeSegs[i] = new RopeSegment(position);
			position.y -= ropeSegLen;
		}
	}

	protected void FixedUpdate()
	{
		Simulate();
	}

	protected void LateUpdate()
	{
		DrawRope();
		UnityEngine.Vector3 normalized = (ropeSegs[ropeSegs.Length - 2].pos - ropeSegs[ropeSegs.Length - 1].pos).normalized;
		endTransform.position = ropeSegs[ropeSegs.Length - 1].pos;
		endTransform.up = normalized;
		UnityEngine.Vector4 vector = spinSpeeds * Time.time;
		vector = new UnityEngine.Vector4(Mathf.Sin(vector.x), Mathf.Sin(vector.y), Mathf.Sin(vector.z), Mathf.Sin(vector.w));
		vector.Scale(spinScales);
		endTransform.Rotate(UnityEngine.Vector3.up, vector.x + vector.y + vector.z + vector.w);
	}

	private void Simulate()
	{
		ropeSegLenScaled = ropeSegLen * base.transform.lossyScale.x;
		UnityEngine.Vector3 vector = new UnityEngine.Vector3(0f, -0.5f, 0f) * Time.fixedDeltaTime;
		for (int i = 1; i < 6; i++)
		{
			UnityEngine.Vector3 vector2 = ropeSegs[i].pos - ropeSegs[i].posOld;
			ropeSegs[i].posOld = ropeSegs[i].pos;
			ropeSegs[i].pos += vector2 * 0.95f;
			ropeSegs[i].pos += vector;
		}
		for (int j = 0; j < 8; j++)
		{
			ApplyConstraint();
		}
	}

	private void ApplyConstraint()
	{
		ropeSegs[0].pos = base.transform.position;
		ApplyConstraintSegment(ref ropeSegs[0], ref ropeSegs[1], 0f, 1f);
		for (int i = 1; i < 5; i++)
		{
			ApplyConstraintSegment(ref ropeSegs[i], ref ropeSegs[i + 1], 0.5f, 0.5f);
		}
	}

	private void ApplyConstraintSegment(ref RopeSegment segA, ref RopeSegment segB, float dampenA, float dampenB)
	{
		float num = (segA.pos - segB.pos).magnitude - ropeSegLenScaled;
		UnityEngine.Vector3 vector = (segA.pos - segB.pos).normalized * num;
		segA.pos -= vector * dampenA;
		segB.pos += vector * dampenB;
	}

	private void DrawRope()
	{
		UnityEngine.Vector3[] array = new UnityEngine.Vector3[6];
		for (int i = 0; i < 6; i++)
		{
			array[i] = ropeSegs[i].pos;
		}
		lineRenderer.positionCount = array.Length;
		lineRenderer.SetPositions(array);
	}
}
public class CornOnCobCosmetic : MonoBehaviour
{
	[Tooltip("The corn will start popping based on the temperature from this ThermalReceiver.")]
	public ThermalReceiver thermalReceiver;

	[Tooltip("The particle system that will be emitted when the heat source is hot enough.")]
	public ParticleSystem particleSys;

	[Tooltip("The curve that determines how many particles will be emitted based on the heat source's temperature.\n\nThe x-axis is the heat source's temperature and the y-axis is the number of particles to emit.")]
	public AnimationCurve particleEmissionCurve;

	public SoundBankPlayer soundBankPlayer;

	private ParticleSystem.EmissionModule emissionModule;

	private float maxBurstProbability;

	private int previousParticleCount;

	protected void Awake()
	{
		emissionModule = particleSys.emission;
		maxBurstProbability = ((emissionModule.burstCount > 0) ? emissionModule.GetBurst(0).probability : 0.2f);
	}

	protected void LateUpdate()
	{
		for (int i = 0; i < emissionModule.burstCount; i++)
		{
			ParticleSystem.Burst burst = emissionModule.GetBurst(i);
			burst.probability = maxBurstProbability * particleEmissionCurve.Evaluate(thermalReceiver.celsius);
			emissionModule.SetBurst(i, burst);
		}
		int particleCount = particleSys.particleCount;
		if (particleCount > previousParticleCount)
		{
			soundBankPlayer.Play();
		}
		previousParticleCount = particleCount;
	}
}
