public class MagicRingCosmetic : MonoBehaviour
{
	private enum FadeState
	{
		FadedOut,
		FadedIn
	}

	[Tooltip("The ring will fade in the emissive texture based on temperature from this ThermalReceiver.")]
	public ThermalReceiver thermalReceiver;

	public Renderer ringRenderer;

	public float fadeInTemperatureThreshold = 200f;

	public float fadeOutTemperatureThreshold = 190f;

	public float fadeTime = 1.5f;

	public SoundBankPlayer fadeInSounds;

	public SoundBankPlayer fadeOutSounds;

	private FadeState fadeState;

	private Color defaultEmissiveColor;

	private float emissiveAmount;

	private MaterialPropertyBlock materialPropertyBlock;

	protected void Awake()
	{
		materialPropertyBlock = new MaterialPropertyBlock();
		defaultEmissiveColor = ringRenderer.sharedMaterial.GetColor(ShaderProps._EmissionColor);
	}

	protected void LateUpdate()
	{
		float celsius = thermalReceiver.celsius;
		if (celsius >= fadeInTemperatureThreshold && fadeState != FadeState.FadedIn)
		{
			fadeInSounds.Play();
			fadeState = FadeState.FadedIn;
		}
		else if (celsius <= fadeOutTemperatureThreshold && fadeState != FadeState.FadedOut)
		{
			fadeOutSounds.Play();
			fadeState = FadeState.FadedOut;
		}
		emissiveAmount = Mathf.MoveTowards(emissiveAmount, (fadeState == FadeState.FadedIn) ? 1f : 0f, Time.deltaTime / fadeTime);
		ringRenderer.GetPropertyBlock(materialPropertyBlock);
		materialPropertyBlock.SetColor(ShaderProps._EmissionColor, new Color(defaultEmissiveColor.r, defaultEmissiveColor.g, defaultEmissiveColor.b, emissiveAmount));
		ringRenderer.SetPropertyBlock(materialPropertyBlock);
	}
}
public class WizardStaffHoldable : TransferrableObject
{
	[Tooltip("This GameObject will activate when the staff hits the ground with enough force.")]
	public GameObject effectsGameObject;

	[Tooltip("The Transform of the staff's tip which will be used to determine if the staff is being slammed. Up axis (Y) should point along the length of the staff.")]
	public Transform tipTransform;

	public float tipCollisionRadius = 0.05f;

	public LayerMask tipCollisionLayerMask;

	[Tooltip("Used to calculate velocity of the staff.")]
	public GorillaVelocityEstimator velocityEstimator;

	public float cooldown = 5f;

	[Tooltip("The velocity of the staff's tip must be greater than this value to activate the effect.")]
	public float minSlamVelocity = 0.5f;

	[Tooltip("The angle (in degrees) between the staff's tip and the ground must be less than this value to activate the effect.")]
	public float minSlamAngle = 5f;

	[DebugReadout]
	private float cooldownRemaining;

	[DebugReadout]
	private bool hitLastFrame;

	private UnityEngine.Vector3 tipTargetLocalPosition;

	private bool hasEffectsGameObject;

	private bool effectsHaveBeenPlayed;

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		tipTargetLocalPosition = tipTransform.localPosition;
		hasEffectsGameObject = effectsGameObject != null;
		effectsHaveBeenPlayed = false;
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		InitToDefault();
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
		InitToDefault();
	}

	private void InitToDefault()
	{
		cooldownRemaining = 0f;
		if (hasEffectsGameObject && effectsHaveBeenPlayed)
		{
			effectsGameObject.SetActive(value: false);
		}
		effectsHaveBeenPlayed = false;
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		if (InHand() && itemState != ItemStates.State1 && GorillaParent.hasInstance && hitLastFrame && !(velocityEstimator.linearVelocity.magnitude < minSlamVelocity))
		{
			UnityEngine.Vector3 up = tipTransform.up;
			UnityEngine.Vector3 up2 = UnityEngine.Vector3.up;
			if (!(UnityEngine.Vector3.Angle(up, up2) > minSlamAngle))
			{
				itemState = ItemStates.State1;
				cooldownRemaining = cooldown;
			}
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		cooldownRemaining -= Time.deltaTime;
		if (cooldownRemaining <= 0f)
		{
			itemState = ItemStates.State0;
			if (hasEffectsGameObject)
			{
				effectsGameObject.SetActive(value: false);
			}
			effectsHaveBeenPlayed = false;
		}
		if (InHand())
		{
			UnityEngine.Vector3 position = base.transform.position;
			UnityEngine.Vector3 end = base.transform.TransformPoint(tipTargetLocalPosition);
			if (Physics.Linecast(position, end, out var hitInfo, tipCollisionLayerMask))
			{
				tipTransform.position = hitInfo.point;
				hitLastFrame = true;
			}
			else
			{
				tipTransform.localPosition = tipTargetLocalPosition;
				hitLastFrame = false;
			}
			if (itemState == ItemStates.State1 && hasEffectsGameObject && !effectsHaveBeenPlayed)
			{
				effectsGameObject.SetActive(value: true);
				effectsHaveBeenPlayed = true;
			}
		}
	}

	protected override void LateUpdateReplicated()
	{
		base.LateUpdateReplicated();
		if (itemState == ItemStates.State1 && !effectsHaveBeenPlayed)
		{
			cooldownRemaining = cooldown;
		}
	}
}
public static class AprilFools
{
	private const int changeIntervalSeconds = 300;

	private const int lerpIntervalSeconds = 120;

	private const float minRange = 0.5f;

	private const float maxRange = 2f;

	private const float excludeRangeStart = 0.75f;

	private const float excludeRangeEnd = 1.25f;

	public static int mod(int x, int m)
	{
		return (x % m + m) % m;
	}

	public static float GenerateTarget(string username, string roomName, string areaName, int startTime)
	{
		float num = (float)mod($"{username}-{roomName}-{areaName}-{startTime}".GetHashCode(), 10000) / 10000f;
		float num2 = 1.5f;
		float num3 = 0.5f / 2f;
		num = num * num2 + 0.5f;
		if (num > 0.75f && num < 1.25f)
		{
			num = ((!(num < 1f)) ? (1.25f + num3) : (0.75f - num3));
		}
		return num;
	}

	public static float Slerp(float a, float b, float t)
	{
		float num = Mathf.Acos(Mathf.Clamp(UnityEngine.Vector2.Dot(new UnityEngine.Vector2(a, b).normalized, UnityEngine.Vector2.right), -1f, 1f)) * t;
		float num2 = Mathf.Sin(num);
		float num3 = Mathf.Sin((1f - t) * num) / num2;
		float num4 = Mathf.Sin(t * num) / num2;
		return a * num3 + b * num4;
	}

	public static float SmoothSlerp(float a, float b, float t)
	{
		t = Mathf.Clamp01(t);
		float num = 0.00013888889f;
		float num2 = Mathf.Clamp01(t - num);
		float num3 = Mathf.Clamp01(t + num);
		float a2 = 3f * num2 * num2 - 2f * num2 * num2 * num2;
		float b2 = 3f * num3 * num3 - 2f * num3 * num3 * num3;
		return Slerp(a, b, Mathf.Lerp(a2, b2, (t - num2) / (num3 - num2)));
	}

	public static float GenerateSmoothTarget(string username, string roomName, string areaName)
	{
		float num = (float)DateTime.UtcNow.Subtract(new DateTime(2023, 3, 30)).TotalSeconds;
		int num2 = (int)num / 300;
		int num3 = num2 * 300;
		int startTime = (num2 + 1) * 300;
		float a = GenerateTarget(username, roomName, areaName, num3);
		float b = GenerateTarget(username, roomName, areaName, startTime);
		float num4 = (num - (float)num3) / 120f;
		if (num4 > 1f)
		{
			num4 = 1f;
		}
		float num5 = SmoothSlerp(a, b, num4);
		if (float.IsInfinity(num5))
		{
			return 0.5f;
		}
		if (float.IsNaN(num5))
		{
			return 0.5f;
		}
		if (num5 < 0.5f)
		{
			return 0.5f;
		}
		if (num5 > 2f)
		{
			return 2f;
		}
		return num5;
	}
}
public class FeatherDusterHoldable : MonoBehaviour, IGorillaSliceableSimple
{
	public LayerMask collisionLayer;

	public float overlapSphereRadius = 0.08f;

	[Tooltip("Collision is not tested until this speed requirement is met.")]
	private float collideMinSpeed = 1f;

	public ParticleSystem particleFx;

	public SoundBankPlayer soundBankPlayer;

	[SerializeField]
	private float soundCooldown = 0.8f;

	private ParticleSystem.EmissionModule emissionModule;

	private float initialRateOverTime;

	private float timeSinceLastSound;

	private UnityEngine.Vector3 lastWorldPos;

	private float lastSliceTime;

	private Collider[] colliderResult = new Collider[1];

	public void Awake()
	{
		timeSinceLastSound = soundCooldown;
		emissionModule = particleFx.emission;
		initialRateOverTime = emissionModule.rateOverTimeMultiplier;
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
		lastWorldPos = base.transform.position;
		lastSliceTime = Time.unscaledTime;
		emissionModule.rateOverTimeMultiplier = 0f;
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void SliceUpdate()
	{
		float unscaledTime = Time.unscaledTime;
		float num = Mathf.Max(unscaledTime - lastSliceTime, Mathf.Epsilon);
		lastSliceTime = unscaledTime;
		timeSinceLastSound += num;
		Transform transform = base.transform;
		UnityEngine.Vector3 position = transform.position;
		float num2 = (position - lastWorldPos).sqrMagnitude / num;
		emissionModule.rateOverTimeMultiplier = 0f;
		if (num2 >= collideMinSpeed * collideMinSpeed && Physics.OverlapSphereNonAlloc(position, overlapSphereRadius * transform.localScale.x, colliderResult, collisionLayer) > 0)
		{
			emissionModule.rateOverTimeMultiplier = initialRateOverTime;
			if (timeSinceLastSound >= soundCooldown)
			{
				soundBankPlayer.Play();
				timeSinceLastSound = 0f;
			}
		}
		lastWorldPos = position;
	}
}
public class RotationSoundPlayer : MonoBehaviour
{
	[Tooltip("Transforms that will make a noise when they rotate.")]
	[SerializeField]
	private Transform[] transforms;

	[SerializeField]
	private SoundBankPlayer soundBankPlayer;

	[Tooltip("How much the transform must rotate from it's initial rotation before a sound is played.")]
	private float rotationAmountThreshold = 30f;

	[Tooltip("How fast the transform must rotate before a sound is played.")]
	private float rotationSpeedThreshold = 45f;

	private float cooldown = 0.6f;

	private float cooldownTimer;

	private UnityEngine.Vector3[] initialUpAxis;

	private UnityEngine.Vector3[] lastUpAxis;

	private float[] lastRotationSpeeds;

	private void Awake()
	{
		List<Transform> list = new List<Transform>(transforms);
		list.RemoveAll((Transform xform) => xform == null);
		transforms = list.ToArray();
		initialUpAxis = new UnityEngine.Vector3[transforms.Length];
		lastUpAxis = new UnityEngine.Vector3[transforms.Length];
		lastRotationSpeeds = new float[transforms.Length];
		for (int num = 0; num < transforms.Length; num++)
		{
			initialUpAxis[num] = transforms[num].localRotation * UnityEngine.Vector3.up;
			lastUpAxis[num] = initialUpAxis[num];
			lastRotationSpeeds[num] = 0f;
		}
	}

	private void Update()
	{
		cooldownTimer -= Time.deltaTime;
		for (int i = 0; i < transforms.Length; i++)
		{
			UnityEngine.Vector3 vector = transforms[i].localRotation * UnityEngine.Vector3.up;
			float num = UnityEngine.Vector3.Angle(vector, initialUpAxis[i]);
			float num2 = UnityEngine.Vector3.Angle(vector, lastUpAxis[i]);
			float deltaTime = Time.deltaTime;
			float num3 = num2 / deltaTime;
			if (cooldownTimer <= 0f && num > rotationAmountThreshold && num3 > rotationSpeedThreshold && !soundBankPlayer.isPlaying)
			{
				cooldownTimer = cooldown;
				soundBankPlayer.Play();
			}
			lastUpAxis[i] = vector;
			lastRotationSpeeds[i] = num3;
		}
	}
}
public class VacuumHoldable : TransferrableObject
{
	private enum VacuumState
	{
		None = 1,
		Active
	}

	[Tooltip("Emission rate will be increase when the trigger button is pressed.")]
	public ParticleSystem particleFX;

	[Tooltip("Sound will loop and fade in/out volume when trigger pressed.")]
	public AudioSource audioSource;

	private float activationVibrationStartStrength = 0.8f;

	private float activationVibrationStartDuration = 0.05f;

	private float activationVibrationLoopStrength = 0.005f;

	private float activationStartTime;

	private bool hasAudioSource;

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		itemState = ItemStates.State0;
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		itemState = ItemStates.State0;
		hasAudioSource = audioSource != null && audioSource.clip != null;
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		itemState = ItemStates.State0;
		if (particleFX.isPlaying)
		{
			particleFX.Stop();
		}
		if (hasAudioSource && audioSource.isPlaying)
		{
			audioSource.GTStop();
		}
	}

	private void InitToDefault()
	{
		itemState = ItemStates.State0;
		if (particleFX.isPlaying)
		{
			particleFX.Stop();
		}
		if (hasAudioSource && audioSource.isPlaying)
		{
			audioSource.GTStop();
		}
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
		InitToDefault();
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		if (!IsMyItem() && base.myOnlineRig != null && base.myOnlineRig.muted)
		{
			itemState = ItemStates.State0;
		}
		if (itemState == ItemStates.State0)
		{
			if (particleFX.isPlaying)
			{
				particleFX.Stop();
			}
			if (hasAudioSource && audioSource.isPlaying)
			{
				audioSource.GTStop();
			}
			return;
		}
		if (!particleFX.isEmitting)
		{
			particleFX.Play();
		}
		if (hasAudioSource && !audioSource.isPlaying)
		{
			audioSource.GTPlay();
		}
		if (IsMyItem() && Time.time > activationStartTime + activationVibrationStartDuration)
		{
			GorillaTagger.Instance.StartVibration(currentState == PositionState.InLeftHand, activationVibrationLoopStrength, Time.deltaTime);
		}
	}

	public override void OnActivate()
	{
		base.OnActivate();
		itemState = ItemStates.State1;
		if (IsMyItem())
		{
			activationStartTime = Time.time;
			GorillaTagger.Instance.StartVibration(currentState == PositionState.InLeftHand, activationVibrationStartStrength, activationVibrationStartDuration);
		}
	}

	public override void OnDeactivate()
	{
		base.OnDeactivate();
		itemState = ItemStates.State0;
	}
}
public class HorseStickNoiseMaker : MonoBehaviour
{
	[Tooltip("Meters the object should traverse between playing a provided audio clip.")]
	public float metersPerClip = 4f;

	[Tooltip("Number of seconds that must elapse before playing another audio clip.")]
	public float minSecBetweenClips = 1.5f;

	public SoundBankPlayer soundBankPlayer;

	[Tooltip("Transform assigned in Gorilla Player Networked Prefab to the Gorilla Player Networked parent to keep track of distance traveled.")]
	public Transform gorillaPlayerXform;

	[Delayed]
	public string gorillaPlayerXform_path;

	[Tooltip("Optional particle FX to spawn when sound plays")]
	public ParticleSystem particleFX;

	private UnityEngine.Vector3 oldPos;

	private float timeSincePlay;

	private float distElapsed;

	protected void OnEnable()
	{
		if (!gorillaPlayerXform && !base.transform.TryFindByPath(gorillaPlayerXform_path, out gorillaPlayerXform))
		{
			UnityEngine.Debug.LogError("HorseStickNoiseMaker: DEACTIVATING! Could not find gorillaPlayerXform using path: \"" + gorillaPlayerXform_path + "\"\nThis component's transform path: \"" + base.transform.GetPath() + "\"");
			base.gameObject.SetActive(value: false);
		}
		else
		{
			oldPos = gorillaPlayerXform.position;
			distElapsed = 0f;
			timeSincePlay = 0f;
		}
	}

	protected void LateUpdate()
	{
		UnityEngine.Vector3 position = gorillaPlayerXform.position;
		distElapsed += (position - oldPos).magnitude;
		timeSincePlay += Time.deltaTime;
		oldPos = position;
		if (distElapsed >= metersPerClip && timeSincePlay >= minSecBetweenClips)
		{
			soundBankPlayer.Play();
			distElapsed = 0f;
			timeSincePlay = 0f;
			if (particleFX != null)
			{
				particleFX.Play();
			}
		}
	}
}
public class FingerTorch : MonoBehaviour, ISpawnable
{
	[Header("Wearable Settings")]
	public bool attachedToLeftHand = true;

	[Header("Bones")]
	public Transform pinkyRingBone;

	public Transform thumbRingBone;

	[Header("Audio")]
	public AudioSource audioSource;

	public AudioClip extendAudioClip;

	public AudioClip retractAudioClip;

	[Header("Vibration")]
	public float extendVibrationDuration = 0.05f;

	public float extendVibrationStrength = 0.2f;

	public float retractVibrationDuration = 0.05f;

	public float retractVibrationStrength = 0.2f;

	[Header("Particle FX")]
	public GameObject particleFX;

	private bool networkedExtended;

	private bool extended;

	private UnityEngine.XR.InputDevice inputDevice;

	private VRRig myRig;

	private int stateBitIndex;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = rig;
		if (!myRig)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	void ISpawnable.OnDespawn()
	{
	}

	protected void OnEnable()
	{
		int num = (attachedToLeftHand ? 1 : 2);
		stateBitIndex = VRRig.WearablePackedStatesBitWriteInfos[num].index;
		OnExtendStateChanged(playAudio: false);
	}

	protected void OnDisable()
	{
	}

	private void UpdateLocal()
	{
		int node = (attachedToLeftHand ? 4 : 5);
		bool flag = ControllerInputPoller.GripFloat((XRNode)node) > 0.25f;
		bool flag2 = ControllerInputPoller.PrimaryButtonPress((XRNode)node);
		bool flag3 = ControllerInputPoller.SecondaryButtonPress((XRNode)node);
		bool flag4 = flag && (flag2 || flag3);
		networkedExtended = flag4;
		if (PhotonNetwork.InRoom && (bool)myRig)
		{
			myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, stateBitIndex, networkedExtended);
		}
	}

	private void UpdateShared()
	{
		if (extended != networkedExtended)
		{
			extended = networkedExtended;
			OnExtendStateChanged(playAudio: true);
			particleFX.SetActive(extended);
		}
	}

	private void UpdateReplicated()
	{
		if (myRig != null && !myRig.isOfflineVRRig)
		{
			networkedExtended = GTBitOps.ReadBit(myRig.WearablePackedStates, stateBitIndex);
		}
	}

	public bool IsMyItem()
	{
		if (myRig != null)
		{
			return myRig.isOfflineVRRig;
		}
		return false;
	}

	protected void LateUpdate()
	{
		if (IsMyItem())
		{
			UpdateLocal();
		}
		else
		{
			UpdateReplicated();
		}
		UpdateShared();
	}

	private void OnExtendStateChanged(bool playAudio)
	{
		audioSource.clip = (extended ? extendAudioClip : retractAudioClip);
		if (playAudio)
		{
			audioSource.GTPlay();
		}
		if (IsMyItem() && (bool)GorillaTagger.Instance)
		{
			GorillaTagger.Instance.StartVibration(attachedToLeftHand, extended ? extendVibrationDuration : retractVibrationDuration, extended ? extendVibrationStrength : retractVibrationStrength);
		}
	}
}
public class AngryBeeAnimator : MonoBehaviour
{
	[SerializeField]
	private GameObject beePrefab;

	[SerializeField]
	private int numBees;

	[SerializeField]
	private float orbitMinRadius;

	[SerializeField]
	private float orbitMaxRadius;

	[SerializeField]
	private float orbitMaxHeightDisplacement;

	[SerializeField]
	private float orbitMaxCenterDisplacement;

	[SerializeField]
	private float orbitMaxTilt;

	[SerializeField]
	private float orbitSpeed;

	[SerializeField]
	private float beeScale;

	private GameObject[] beeOrbits;

	private GameObject[] bees;

	private UnityEngine.Vector3[] beeOrbitalAxes;

	private float[] beeOrbitalRadii;

	private void Awake()
	{
		bees = new GameObject[numBees];
		beeOrbits = new GameObject[numBees];
		beeOrbitalRadii = new float[numBees];
		beeOrbitalAxes = new UnityEngine.Vector3[numBees];
		for (int i = 0; i < numBees; i++)
		{
			GameObject gameObject = new GameObject();
			gameObject.transform.parent = base.transform;
			UnityEngine.Vector2 vector = UnityEngine.Random.insideUnitCircle * orbitMaxCenterDisplacement;
			gameObject.transform.localPosition = new UnityEngine.Vector3(vector.x, UnityEngine.Random.Range(0f - orbitMaxHeightDisplacement, orbitMaxHeightDisplacement), vector.y);
			gameObject.transform.localRotation = UnityEngine.Quaternion.Euler(UnityEngine.Random.Range(0f - orbitMaxTilt, orbitMaxTilt), UnityEngine.Random.Range(0, 360), 0f);
			beeOrbitalAxes[i] = gameObject.transform.up;
			GameObject gameObject2 = UnityEngine.Object.Instantiate(beePrefab, gameObject.transform);
			float num = UnityEngine.Random.Range(orbitMinRadius, orbitMaxRadius);
			beeOrbitalRadii[i] = num;
			gameObject2.transform.localPosition = UnityEngine.Vector3.forward * num;
			gameObject2.transform.localRotation = UnityEngine.Quaternion.Euler(-90f, 90f, 0f);
			gameObject2.transform.localScale = UnityEngine.Vector3.one * beeScale;
			bees[i] = gameObject2;
			beeOrbits[i] = gameObject;
		}
	}

	private void Update()
	{
		float angle = orbitSpeed * Time.deltaTime;
		for (int i = 0; i < numBees; i++)
		{
			beeOrbits[i].transform.Rotate(beeOrbitalAxes[i], angle);
		}
	}

	public void SetEmergeFraction(float fraction)
	{
		for (int i = 0; i < numBees; i++)
		{
			bees[i].transform.localPosition = UnityEngine.Vector3.forward * fraction * beeOrbitalRadii[i];
		}
	}
}
[NetworkBehaviourWeaved(3)]
public class AngryBeeSwarm : NetworkComponent
{
	public enum ChaseState
	{
		Dormant = 1,
		InitialEmerge = 2,
		Chasing = 4,
		Grabbing = 8
	}

	public static AngryBeeSwarm instance;

	public float heightAboveNavmesh = 0.5f;

	public Transform followTarget;

	[SerializeField]
	private float velocityStep = 1f;

	private float currentSpeed;

	[SerializeField]
	private float velocityIncreaseInterval = 20f;

	public UnityEngine.Vector3 noisyOffset;

	public UnityEngine.Vector3 ghostOffsetGrabbingLocal;

	private float emergeStartedTimestamp;

	private float grabTimestamp;

	private float lastSpeedIncreased;

	[SerializeField]
	private float totalTimeToEmerge;

	[SerializeField]
	private float catchDistance;

	[SerializeField]
	private float grabDuration;

	[SerializeField]
	private float grabSpeed = 1f;

	[SerializeField]
	private float minGrabCooldown;

	[SerializeField]
	private float initialRangeLimit;

	[SerializeField]
	private float finalRangeLimit;

	[SerializeField]
	private float rangeLimitBlendDuration;

	[SerializeField]
	private float boredAfterDuration;

	public NetPlayer targetPlayer;

	public AngryBeeAnimator beeAnimator;

	public ChaseState currentState;

	public ChaseState lastState;

	public NetPlayer grabbedPlayer;

	private bool targetIsOnNavMesh;

	private const float navMeshSampleRange = 5f;

	[Tooltip("Haptic vibration when chased by lucy")]
	public float hapticStrength = 1f;

	public float hapticDuration = 1.5f;

	public float MinHeightAboveWater = 0.5f;

	public float PlayerMinHeightAboveWater = 0.5f;

	public float RefreshClosestPlayerInterval = 1f;

	private float NextRefreshClosestPlayerTimestamp = 1f;

	private float BoredToDeathAtTimestamp = -1f;

	[SerializeField]
	private Transform testEmergeFrom;

	[SerializeField]
	private Transform testEmergeTo;

	private UnityEngine.Vector3 emergeFromPosition;

	private UnityEngine.Vector3 emergeToPosition;

	private NavMeshPath path;

	public List<UnityEngine.Vector3> pathPoints;

	public int currentPathPointIdx;

	private float nextPathTimestamp;

	[WeaverGenerated]
	[SerializeField]
	[DefaultForProperty("Data", 0, 3)]
	[DrawIf("IsEditorWritable", true, CompareOperator.Equal, DrawIfMode.ReadOnly)]
	private BeeSwarmData _Data;

	public bool isDormant => currentState == ChaseState.Dormant;

	[Networked]
	[NetworkedWeaved(0, 3)]
	public unsafe BeeSwarmData Data
	{
		get
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing AngryBeeSwarm.Data. Networked properties can only be accessed when Spawned() has been called.");
			}
			return *(BeeSwarmData*)((byte*)((NetworkBehaviour)this).Ptr + 0);
		}
		set
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing AngryBeeSwarm.Data. Networked properties can only be accessed when Spawned() has been called.");
			}
			*(BeeSwarmData*)((byte*)((NetworkBehaviour)this).Ptr + 0) = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		instance = this;
		targetPlayer = null;
		currentState = ChaseState.Dormant;
		grabTimestamp = 0f - minGrabCooldown;
		RoomSystem.JoinedRoomEvent += new Action(OnJoinedRoom);
	}

	private void InitializeSwarm()
	{
		if (NetworkSystem.Instance.InRoom && base.IsMine)
		{
			beeAnimator.transform.localPosition = UnityEngine.Vector3.zero;
			lastSpeedIncreased = 0f;
			currentSpeed = 0f;
		}
	}

	private void LateUpdate()
	{
		if (!NetworkSystem.Instance.InRoom)
		{
			currentState = ChaseState.Dormant;
			UpdateState();
			return;
		}
		if (base.IsMine)
		{
			switch (currentState)
			{
			case ChaseState.Dormant:
				if (UnityEngine.Application.isEditor && Keyboard.current[Key.Space].wasPressedThisFrame)
				{
					currentState = ChaseState.InitialEmerge;
				}
				break;
			case ChaseState.InitialEmerge:
				if (Time.time > emergeStartedTimestamp + totalTimeToEmerge)
				{
					currentState = ChaseState.Chasing;
				}
				break;
			case ChaseState.Chasing:
				if (followTarget == null || targetPlayer == null || Time.time > NextRefreshClosestPlayerTimestamp)
				{
					ChooseClosestTarget();
					if (followTarget != null)
					{
						BoredToDeathAtTimestamp = -1f;
					}
					else if (BoredToDeathAtTimestamp < 0f)
					{
						BoredToDeathAtTimestamp = Time.time + boredAfterDuration;
					}
				}
				if (BoredToDeathAtTimestamp >= 0f && Time.time > BoredToDeathAtTimestamp)
				{
					currentState = ChaseState.Dormant;
				}
				else if (!(followTarget == null) && (followTarget.position - beeAnimator.transform.position).magnitude < catchDistance)
				{
					float num = ZoneShaderSettings.GetWaterY() + PlayerMinHeightAboveWater;
					if (followTarget.position.y > num)
					{
						currentState = ChaseState.Grabbing;
					}
				}
				break;
			case ChaseState.Grabbing:
				if (Time.time > grabTimestamp + grabDuration)
				{
					currentState = ChaseState.Dormant;
				}
				break;
			}
		}
		if (lastState != currentState)
		{
			OnChangeState(currentState);
			lastState = currentState;
		}
		UpdateState();
	}

	public void UpdateState()
	{
		switch (currentState)
		{
		case ChaseState.InitialEmerge:
			if (NetworkSystem.Instance.InRoom)
			{
				SwarmEmergeUpdateShared();
			}
			break;
		case ChaseState.Chasing:
			if (NetworkSystem.Instance.InRoom)
			{
				if (base.IsMine)
				{
					ChaseHost();
				}
				MoveBodyShared();
			}
			break;
		case ChaseState.Grabbing:
			if (NetworkSystem.Instance.InRoom)
			{
				if (targetPlayer == NetworkSystem.Instance.LocalPlayer)
				{
					RiseGrabbedLocalPlayer();
				}
				GrabBodyShared();
			}
			break;
		}
	}

	public void Emerge(UnityEngine.Vector3 fromPosition, UnityEngine.Vector3 toPosition)
	{
		base.transform.position = fromPosition;
		emergeFromPosition = fromPosition;
		emergeToPosition = toPosition;
		currentState = ChaseState.InitialEmerge;
		emergeStartedTimestamp = Time.time;
	}

	private void OnChangeState(ChaseState newState)
	{
		switch (newState)
		{
		case ChaseState.Dormant:
			if (beeAnimator.gameObject.activeSelf)
			{
				beeAnimator.gameObject.SetActive(value: false);
			}
			if (base.IsMine)
			{
				targetPlayer = null;
				base.transform.position = new UnityEngine.Vector3(0f, -9999f, 0f);
				InitializeSwarm();
			}
			SetInitialRotations();
			break;
		case ChaseState.InitialEmerge:
			emergeStartedTimestamp = Time.time;
			if (!beeAnimator.gameObject.activeSelf)
			{
				beeAnimator.gameObject.SetActive(value: true);
			}
			beeAnimator.SetEmergeFraction(0f);
			if (base.IsMine)
			{
				currentSpeed = 0f;
				ChooseClosestTarget();
			}
			SetInitialRotations();
			break;
		case ChaseState.Chasing:
			if (!beeAnimator.gameObject.activeSelf)
			{
				beeAnimator.gameObject.SetActive(value: true);
			}
			beeAnimator.SetEmergeFraction(1f);
			ResetPath();
			NextRefreshClosestPlayerTimestamp = Time.time + RefreshClosestPlayerInterval;
			BoredToDeathAtTimestamp = -1f;
			break;
		case ChaseState.Grabbing:
		{
			if (!beeAnimator.gameObject.activeSelf)
			{
				beeAnimator.gameObject.SetActive(value: true);
			}
			grabTimestamp = Time.time;
			beeAnimator.transform.localPosition = ghostOffsetGrabbingLocal;
			VRRig vRRig = GorillaGameManager.StaticFindRigForPlayer(targetPlayer);
			if (vRRig != null)
			{
				followTarget = vRRig.transform;
			}
			break;
		}
		}
	}

	private void ChooseClosestTarget()
	{
		float num = Mathf.Lerp(initialRangeLimit, finalRangeLimit, (Time.time + totalTimeToEmerge - emergeStartedTimestamp) / rangeLimitBlendDuration);
		float num2 = num * num;
		VRRig vRRig = null;
		float num3 = ZoneShaderSettings.GetWaterY() + PlayerMinHeightAboveWater;
		foreach (RigContainer activeRigContainer in VRRigCache.ActiveRigContainers)
		{
			VRRig rig = activeRigContainer.Rig;
			if (rig.head != null && !(rig.head.rigTarget == null) && !(rig.head.rigTarget.position.y <= num3))
			{
				float sqrMagnitude = (base.transform.position - rig.head.rigTarget.transform.position).sqrMagnitude;
				if (sqrMagnitude < num2)
				{
					num2 = sqrMagnitude;
					vRRig = rig;
				}
			}
		}
		if (vRRig.IsNotNull())
		{
			targetPlayer = vRRig.creator;
			followTarget = vRRig.head.rigTarget;
			targetIsOnNavMesh = NavMesh.SamplePosition(followTarget.position, out var _, 5f, 1);
		}
		else
		{
			targetPlayer = null;
			followTarget = null;
		}
		NextRefreshClosestPlayerTimestamp = Time.time + RefreshClosestPlayerInterval;
	}

	private void SetInitialRotations()
	{
		beeAnimator.transform.localPosition = UnityEngine.Vector3.zero;
	}

	private void SwarmEmergeUpdateShared()
	{
		if (Time.time < emergeStartedTimestamp + totalTimeToEmerge)
		{
			float emergeFraction = (Time.time - emergeStartedTimestamp) / totalTimeToEmerge;
			if (base.IsMine)
			{
				base.transform.position = UnityEngine.Vector3.Lerp(emergeFromPosition, emergeToPosition, (Time.time - emergeStartedTimestamp) / totalTimeToEmerge);
			}
			beeAnimator.SetEmergeFraction(emergeFraction);
		}
	}

	private void RiseGrabbedLocalPlayer()
	{
		if (Time.time > grabTimestamp + minGrabCooldown)
		{
			grabTimestamp = Time.time;
			GorillaTagger.Instance.ApplyStatusEffect(GorillaTagger.StatusEffect.Frozen, GorillaTagger.Instance.tagCooldown);
			GorillaTagger.Instance.StartVibration(forLeftController: true, hapticStrength, hapticDuration);
			GorillaTagger.Instance.StartVibration(forLeftController: false, hapticStrength, hapticDuration);
		}
		if (Time.time < grabTimestamp + grabDuration)
		{
			GorillaTagger.Instance.rigidbody.linearVelocity = UnityEngine.Vector3.up * grabSpeed;
			EquipmentInteractor.instance.ForceStopClimbing();
		}
	}

	public void UpdateFollowPath(UnityEngine.Vector3 destination, float currentSpeed)
	{
		if (path == null)
		{
			GetNewPath(destination);
		}
		pathPoints[pathPoints.Count - 1] = destination;
		UnityEngine.Vector3 vector = pathPoints[currentPathPointIdx];
		base.transform.position = UnityEngine.Vector3.MoveTowards(base.transform.position, vector, currentSpeed * Time.deltaTime);
		UnityEngine.Vector3 eulerAngles = UnityEngine.Quaternion.LookRotation(vector - base.transform.position).eulerAngles;
		if (Mathf.Abs(eulerAngles.x) > 45f)
		{
			eulerAngles.x = 0f;
		}
		base.transform.rotation = UnityEngine.Quaternion.Euler(eulerAngles);
		if (currentPathPointIdx + 1 < pathPoints.Count && (base.transform.position - vector).sqrMagnitude < 0.1f)
		{
			if (nextPathTimestamp <= Time.time)
			{
				GetNewPath(destination);
			}
			else
			{
				currentPathPointIdx++;
			}
		}
	}

	private void GetNewPath(UnityEngine.Vector3 destination)
	{
		path = new NavMeshPath();
		NavMesh.SamplePosition(base.transform.position, out var hit, 5f, 1);
		targetIsOnNavMesh = NavMesh.SamplePosition(destination, out var hit2, 5f, 1);
		NavMesh.CalculatePath(hit.position, hit2.position, -1, path);
		pathPoints = new List<UnityEngine.Vector3>();
		UnityEngine.Vector3[] corners = path.corners;
		foreach (UnityEngine.Vector3 vector in corners)
		{
			pathPoints.Add(vector + UnityEngine.Vector3.up * heightAboveNavmesh);
		}
		pathPoints.Add(destination);
		currentPathPointIdx = 0;
		nextPathTimestamp = Time.time + 2f;
	}

	public void ResetPath()
	{
		path = null;
	}

	private void ChaseHost()
	{
		if (followTarget != null)
		{
			if (Time.time > lastSpeedIncreased + velocityIncreaseInterval)
			{
				lastSpeedIncreased = Time.time;
				currentSpeed += velocityStep;
			}
			float num = ZoneShaderSettings.GetWaterY() + MinHeightAboveWater;
			UnityEngine.Vector3 position = followTarget.position;
			if (position.y < num)
			{
				position.y = num;
			}
			if (targetIsOnNavMesh)
			{
				UpdateFollowPath(position, currentSpeed);
			}
			else
			{
				base.transform.position = UnityEngine.Vector3.MoveTowards(base.transform.position, position, currentSpeed * Time.deltaTime);
			}
		}
	}

	private void MoveBodyShared()
	{
		noisyOffset = new UnityEngine.Vector3(Mathf.PerlinNoise(Time.time, 0f) - 0.5f, Mathf.PerlinNoise(Time.time, 10f) - 0.5f, Mathf.PerlinNoise(Time.time, 20f) - 0.5f);
		beeAnimator.transform.localPosition = noisyOffset;
	}

	private void GrabBodyShared()
	{
		if (followTarget != null)
		{
			base.transform.rotation = followTarget.rotation;
			base.transform.position = followTarget.position;
		}
	}

	public override void WriteDataFusion()
	{
		Data = new BeeSwarmData(targetPlayer.ActorNumber, (int)currentState, currentSpeed);
	}

	public override void ReadDataFusion()
	{
		targetPlayer = NetworkSystem.Instance.GetPlayer(Data.TargetActorNumber);
		currentState = (ChaseState)Data.CurrentState;
		if (float.IsFinite(Data.CurrentSpeed))
		{
			currentSpeed = Data.CurrentSpeed;
		}
	}

	protected override void WriteDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (info.Sender != null && info.Sender.Equals(PhotonNetwork.MasterClient))
		{
			stream.SendNext(targetPlayer?.ActorNumber ?? (-1));
			stream.SendNext(currentState);
			stream.SendNext(currentSpeed);
		}
	}

	protected override void ReadDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (info.Sender == PhotonNetwork.MasterClient)
		{
			int playerID = (int)stream.ReceiveNext();
			targetPlayer = NetworkSystem.Instance.GetPlayer(playerID);
			currentState = (ChaseState)stream.ReceiveNext();
			float f = (float)stream.ReceiveNext();
			if (float.IsFinite(f))
			{
				currentSpeed = f;
			}
		}
	}

	public override void OnOwnerChange(Player newOwner, Player previousOwner)
	{
		base.OnOwnerChange(newOwner, previousOwner);
		if (newOwner == PhotonNetwork.LocalPlayer)
		{
			OnChangeState(currentState);
		}
	}

	public void OnJoinedRoom()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			InitializeSwarm();
		}
	}

	private void TestEmerge()
	{
		Emerge(testEmergeFrom.transform.position, testEmergeTo.transform.position);
	}

	[WeaverGenerated]
	public override void CopyBackingFieldsToState(bool P_0)
	{
		base.CopyBackingFieldsToState(P_0);
		Data = _Data;
	}

	[WeaverGenerated]
	public override void CopyStateToBackingFields()
	{
		base.CopyStateToBackingFields();
		_Data = Data;
	}
}
[StructLayout(LayoutKind.Explicit, Size = 12)]
[NetworkStructWeaved(3)]
public struct BeeSwarmData : INetworkStruct
{
	[field: FieldOffset(0)]
	public int TargetActorNumber { get; set; }

	[field: FieldOffset(4)]
	public int CurrentState { get; set; }

	[field: FieldOffset(8)]
	public float CurrentSpeed { get; set; }

	public BeeSwarmData(int actorNr, int state, float speed)
	{
		TargetActorNumber = actorNr;
		CurrentState = state;
		CurrentSpeed = speed;
	}
}
public struct AnimatedBee
{
	private struct TimedDestination
	{
		public float syncTime;

		public float syncEndTime;

		public BeePerchPoint destination;
	}

	private List<TimedDestination> destinationCache;

	private TimedDestination destinationA;

	private TimedDestination destinationB;

	private float loopDuration;

	private UnityEngine.Vector3 oldPosition;

	private UnityEngine.Vector3 velocity;

	public MeshRenderer visual;

	private float oldSyncTime;

	private List<BeePerchPoint> route;

	private List<float> holdTimes;

	private float speed;

	private float maxTravelTime;

	public void UpdateVisual(float syncTime, BeeSwarmManager manager)
	{
		if (destinationCache == null)
		{
			return;
		}
		syncTime %= loopDuration;
		if (syncTime < oldSyncTime)
		{
			InitRouteTimestamps();
		}
		GetPositionAndDestinationAtTime(syncTime, out var idealPosition, out var destination);
		UnityEngine.Vector3 target = (destination - oldPosition).normalized * speed;
		velocity = UnityEngine.Vector3.MoveTowards(velocity * manager.BeeJitterDamping, target, manager.BeeAcceleration * Time.deltaTime);
		if ((oldPosition - destination).IsLongerThan(manager.BeeNearDestinationRadius))
		{
			velocity += UnityEngine.Random.insideUnitSphere * manager.BeeJitterStrength * Time.deltaTime;
		}
		UnityEngine.Vector3 vector = oldPosition + velocity * Time.deltaTime;
		if ((vector - idealPosition).IsLongerThan(manager.BeeMaxJitterRadius))
		{
			vector = idealPosition + (vector - idealPosition).normalized * manager.BeeMaxJitterRadius;
			velocity = (vector - oldPosition) / Time.deltaTime;
		}
		foreach (GameObject avoidPoint in BeeSwarmManager.avoidPoints)
		{
			UnityEngine.Vector3 position = avoidPoint.transform.position;
			if ((vector - position).IsShorterThan(manager.AvoidPointRadius))
			{
				UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(position - vector, destination - vector).normalized;
				_ = (destination - position).normalized;
				float num = UnityEngine.Vector3.Dot(vector - position, normalized);
				UnityEngine.Vector3 vector2 = (manager.AvoidPointRadius - num) * normalized;
				vector += vector2;
				velocity += vector2;
			}
		}
		visual.transform.position = vector;
		if ((destination - vector).IsLongerThan(0.01f))
		{
			visual.transform.rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.up, vector - destination);
		}
		oldPosition = vector;
		oldSyncTime = syncTime;
	}

	public void GetPositionAndDestinationAtTime(float syncTime, out UnityEngine.Vector3 idealPosition, out UnityEngine.Vector3 destination)
	{
		if (syncTime > destinationB.syncEndTime || syncTime < destinationA.syncTime)
		{
			int num = 0;
			int num2 = destinationCache.Count - 1;
			while (num + 1 < num2)
			{
				int num3 = (num + num2) / 2;
				float syncTime2 = destinationCache[num3].syncTime;
				float syncEndTime = destinationCache[num3].syncEndTime;
				if (syncTime2 <= syncTime && syncEndTime >= syncTime)
				{
					idealPosition = destinationCache[num3].destination.GetPoint();
					destination = idealPosition;
				}
				if (syncEndTime < syncTime)
				{
					num = num3;
				}
				else
				{
					num2 = num3;
				}
			}
			destinationA = destinationCache[num];
			destinationB = destinationCache[num2];
		}
		float t = Mathf.InverseLerp(destinationA.syncEndTime, destinationB.syncTime, syncTime);
		destination = destinationB.destination.GetPoint();
		idealPosition = UnityEngine.Vector3.Lerp(destinationA.destination.GetPoint(), destination, t);
	}

	public void InitVisual(MeshRenderer prefab, BeeSwarmManager manager)
	{
		visual = UnityEngine.Object.Instantiate(prefab, manager.transform);
	}

	public void InitRouteTimestamps()
	{
		destinationB.syncEndTime = -1f;
		destinationCache.Clear();
		destinationCache.Add(new TimedDestination
		{
			syncTime = 0f,
			destination = route[0]
		});
		float num = 0f;
		for (int i = 1; i < route.Count; i++)
		{
			if (route[i].enabled)
			{
				float a = (route[i].transform.position - route[i - 1].transform.position).magnitude * speed;
				a = Mathf.Min(a, maxTravelTime);
				num += a;
				float num2 = holdTimes[i];
				destinationCache.Add(new TimedDestination
				{
					syncTime = num,
					syncEndTime = num + num2,
					destination = route[i]
				});
				num += num2;
			}
		}
		num += Mathf.Min((route[0].transform.position - route[route.Count - 1].transform.position).magnitude * speed, maxTravelTime);
		float num3 = holdTimes[0];
		destinationCache.Add(new TimedDestination
		{
			syncTime = num,
			syncEndTime = num + num3,
			destination = route[0]
		});
	}

	public void InitRoute(List<BeePerchPoint> route, List<float> holdTimes, BeeSwarmManager manager)
	{
		this.route = route;
		this.holdTimes = holdTimes;
		speed = manager.BeeSpeed;
		maxTravelTime = manager.BeeMaxTravelTime;
		destinationCache = new List<TimedDestination>(route.Count + 1);
		float num = 0f;
		for (int i = 1; i < route.Count; i++)
		{
			num += (route[i].transform.position - route[i - 1].transform.position).magnitude * manager.BeeSpeed + holdTimes[i];
		}
		loopDuration = num + (route[0].transform.position - route[route.Count - 1].transform.position).magnitude * manager.BeeSpeed + holdTimes[0];
	}
}
public struct AnimatedButterfly
{
	private struct TimedDestination
	{
		public float syncTime;

		public float syncEndTime;

		public GameObject destination;
	}

	private List<TimedDestination> destinationCache;

	private TimedDestination destinationA;

	private TimedDestination destinationB;

	private float loopDuration;

	private UnityEngine.Vector3 oldPosition;

	private UnityEngine.Vector3 velocity;

	public MeshRenderer visual;

	private Material material;

	private float speed;

	private float maxTravelTime;

	private UnityEngine.Quaternion travellingLocalRotation;

	private float baseFlapSpeed;

	private bool wasPerched;

	public void UpdateVisual(float syncTime, ButterflySwarmManager manager)
	{
		if (destinationCache == null)
		{
			return;
		}
		syncTime %= loopDuration;
		GetPositionAndDestinationAtTime(syncTime, out var idealPosition, out var destination);
		UnityEngine.Vector3 target = (destination - oldPosition).normalized * speed;
		velocity = UnityEngine.Vector3.MoveTowards(velocity * manager.BeeJitterDamping, target, manager.BeeAcceleration * Time.deltaTime);
		float sqrMagnitude = (oldPosition - destination).sqrMagnitude;
		if (sqrMagnitude < manager.BeeNearDestinationRadius * manager.BeeNearDestinationRadius)
		{
			visual.transform.position = UnityEngine.Vector3.MoveTowards(visual.transform.position, destination, Time.deltaTime);
			visual.transform.rotation = destinationB.destination.transform.rotation;
			if (sqrMagnitude < 1E-07f && !wasPerched)
			{
				material.SetFloat(ShaderProps._VertexFlapSpeed, manager.PerchedFlapSpeed);
				material.SetFloat(ShaderProps._VertexFlapPhaseOffset, manager.PerchedFlapPhase);
				wasPerched = true;
			}
		}
		else
		{
			if (wasPerched)
			{
				material.SetFloat(ShaderProps._VertexFlapSpeed, baseFlapSpeed);
				material.SetFloat(ShaderProps._VertexFlapPhaseOffset, 0f);
				wasPerched = false;
			}
			velocity += UnityEngine.Random.insideUnitSphere * manager.BeeJitterStrength * Time.deltaTime;
			UnityEngine.Vector3 vector = oldPosition + velocity * Time.deltaTime;
			if ((vector - idealPosition).IsLongerThan(manager.BeeMaxJitterRadius))
			{
				vector = idealPosition + (vector - idealPosition).normalized * manager.BeeMaxJitterRadius;
				velocity = (vector - oldPosition) / Time.deltaTime;
			}
			foreach (GameObject avoidPoint in BeeSwarmManager.avoidPoints)
			{
				UnityEngine.Vector3 position = avoidPoint.transform.position;
				if ((vector - position).IsShorterThan(manager.AvoidPointRadius))
				{
					UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(position - vector, destination - vector).normalized;
					_ = (destination - position).normalized;
					float num = UnityEngine.Vector3.Dot(vector - position, normalized);
					UnityEngine.Vector3 vector2 = (manager.AvoidPointRadius - num) * normalized;
					vector += vector2;
					velocity += vector2;
				}
			}
			visual.transform.position = vector;
			if ((destination - vector).IsLongerThan(0.01f))
			{
				visual.transform.rotation = UnityEngine.Quaternion.LookRotation(destination - vector) * travellingLocalRotation;
			}
		}
		oldPosition = visual.transform.position;
	}

	public void GetPositionAndDestinationAtTime(float syncTime, out UnityEngine.Vector3 idealPosition, out UnityEngine.Vector3 destination)
	{
		if (syncTime > destinationB.syncEndTime || syncTime < destinationA.syncTime || (object)destinationA.destination == null || (object)destinationB.destination == null)
		{
			int num = 0;
			int num2 = destinationCache.Count - 1;
			while (num + 1 < num2)
			{
				int num3 = (num + num2) / 2;
				float syncTime2 = destinationCache[num3].syncTime;
				float syncEndTime = destinationCache[num3].syncEndTime;
				if (syncTime2 <= syncTime && syncEndTime >= syncTime)
				{
					idealPosition = destinationCache[num3].destination.transform.position;
					destination = idealPosition;
				}
				if (syncEndTime < syncTime)
				{
					num = num3;
				}
				else
				{
					num2 = num3;
				}
			}
			destinationA = destinationCache[num];
			destinationB = destinationCache[num2];
		}
		float t = Mathf.InverseLerp(destinationA.syncEndTime, destinationB.syncTime, syncTime);
		destination = destinationB.destination.transform.position;
		idealPosition = UnityEngine.Vector3.Lerp(destinationA.destination.transform.position, destination, t);
	}

	public void InitVisual(MeshRenderer prefab, ButterflySwarmManager manager)
	{
		visual = UnityEngine.Object.Instantiate(prefab, manager.transform);
		material = visual.material;
		material.SetFloat(ShaderProps._VertexFlapPhaseOffset, 0f);
	}

	public void SetColor(Color color)
	{
		material.SetColor(ShaderProps._BaseColor, color);
	}

	public void SetFlapSpeed(float flapSpeed)
	{
		material.SetFloat(ShaderProps._VertexFlapSpeed, flapSpeed);
		baseFlapSpeed = flapSpeed;
	}

	public void InitRoute(List<GameObject> route, List<float> holdTimes, ButterflySwarmManager manager)
	{
		speed = manager.BeeSpeed;
		maxTravelTime = manager.BeeMaxTravelTime;
		travellingLocalRotation = manager.TravellingLocalRotation;
		destinationCache = new List<TimedDestination>(route.Count + 1);
		destinationCache.Clear();
		destinationCache.Add(new TimedDestination
		{
			syncTime = 0f,
			syncEndTime = 0f,
			destination = route[0]
		});
		float num = 0f;
		for (int i = 1; i < route.Count; i++)
		{
			float a = (route[i].transform.position - route[i - 1].transform.position).magnitude / speed;
			a = Mathf.Min(a, maxTravelTime);
			num += a;
			float num2 = holdTimes[i];
			destinationCache.Add(new TimedDestination
			{
				syncTime = num,
				syncEndTime = num + num2,
				destination = route[i]
			});
			num += num2;
		}
		num += Mathf.Min((route[0].transform.position - route[route.Count - 1].transform.position).magnitude / speed, maxTravelTime);
		float num3 = holdTimes[0];
		destinationCache.Add(new TimedDestination
		{
			syncTime = num,
			syncEndTime = num + num3,
			destination = route[0]
		});
		loopDuration = num + (route[0].transform.position - route[route.Count - 1].transform.position).magnitude * manager.BeeSpeed + holdTimes[0];
	}
}
public class BeeAvoiderTest : MonoBehaviour
{
	public GameObject[] patrolPoints;

	public GameObject[] avoidancePoints;

	public float speed;

	public float acceleration;

	public float instability;

	public float instabilityOffRadius;

	public float drag;

	public float avoidRadius;

	public float patrolArrivedRadius;

	private int nextPatrolPoint;

	private UnityEngine.Vector3 velocity;

	public void Update()
	{
		UnityEngine.Vector3 position = patrolPoints[nextPatrolPoint].transform.position;
		UnityEngine.Vector3 position2 = base.transform.position;
		UnityEngine.Vector3 target = (position - position2).normalized * speed;
		velocity = UnityEngine.Vector3.MoveTowards(velocity * drag, target, acceleration);
		if ((position2 - position).IsLongerThan(instabilityOffRadius))
		{
			velocity += UnityEngine.Random.insideUnitSphere * instability * Time.deltaTime;
		}
		UnityEngine.Vector3 vector = position2 + velocity * Time.deltaTime;
		GameObject[] array = avoidancePoints;
		for (int i = 0; i < array.Length; i++)
		{
			UnityEngine.Vector3 position3 = array[i].transform.position;
			if ((vector - position3).IsShorterThan(avoidRadius))
			{
				UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(position3 - vector, position - vector).normalized;
				_ = (position - position3).normalized;
				float num = UnityEngine.Vector3.Dot(vector - position3, normalized);
				UnityEngine.Vector3 vector2 = (avoidRadius - num) * normalized;
				vector += vector2;
				velocity += vector2;
			}
		}
		base.transform.position = vector;
		base.transform.rotation = UnityEngine.Quaternion.LookRotation(position - vector);
		if ((vector - position).IsShorterThan(patrolArrivedRadius))
		{
			nextPatrolPoint = (nextPatrolPoint + 1) % patrolPoints.Length;
		}
	}
}
