public class BeeSwarmManager : MonoBehaviour
{
	[SerializeField]
	private XSceneRef[] flowerSections;

	[SerializeField]
	private int loopSizePerBee;

	[SerializeField]
	private int numBees;

	[SerializeField]
	private MeshRenderer beePrefab;

	[SerializeField]
	private AudioSource nearbyBeeBuzz;

	[SerializeField]
	private AudioSource generalBeeBuzz;

	private GameObject[] flowerSectionsResolved;

	private List<AnimatedBee> bees;

	private Transform playerCamera;

	private List<BeePerchPoint> allPerchPoints = new List<BeePerchPoint>();

	public static readonly List<GameObject> avoidPoints = new List<GameObject>();

	[field: SerializeField]
	public BeePerchPoint BeeHive { get; private set; }

	[field: SerializeField]
	public float BeeSpeed { get; private set; }

	[field: SerializeField]
	public float BeeMaxTravelTime { get; private set; }

	[field: SerializeField]
	public float BeeAcceleration { get; private set; }

	[field: SerializeField]
	public float BeeJitterStrength { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Should be 0-1; closer to 1 = less damping")]
	public float BeeJitterDamping { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Limits how far the bee can get off course")]
	public float BeeMaxJitterRadius { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Bees stop jittering when close to their destination")]
	public float BeeNearDestinationRadius { get; private set; }

	[field: SerializeField]
	public float AvoidPointRadius { get; private set; }

	[field: SerializeField]
	public float BeeMinFlowerDuration { get; private set; }

	[field: SerializeField]
	public float BeeMaxFlowerDuration { get; private set; }

	[field: SerializeField]
	public float GeneralBuzzRange { get; private set; }

	private void Awake()
	{
		bees = new List<AnimatedBee>(numBees);
		for (int i = 0; i < numBees; i++)
		{
			AnimatedBee item = default(AnimatedBee);
			item.InitVisual(beePrefab, this);
			bees.Add(item);
		}
		playerCamera = Camera.main.transform;
	}

	private void Start()
	{
		XSceneRef[] array = flowerSections;
		foreach (XSceneRef xSceneRef in array)
		{
			if (xSceneRef.TryResolve(out GameObject result))
			{
				BeePerchPoint[] componentsInChildren = result.GetComponentsInChildren<BeePerchPoint>();
				foreach (BeePerchPoint item in componentsInChildren)
				{
					allPerchPoints.Add(item);
				}
			}
		}
		OnSeedChange();
		RandomTimedSeedManager.instance.AddCallbackOnSeedChanged(OnSeedChange);
	}

	private void OnDestroy()
	{
		RandomTimedSeedManager.instance.RemoveCallbackOnSeedChanged(OnSeedChange);
	}

	private void Update()
	{
		UnityEngine.Vector3 position = playerCamera.transform.position;
		UnityEngine.Vector3 position2 = UnityEngine.Vector3.zero;
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		_ = 1f / (float)bees.Count;
		float num = float.PositiveInfinity;
		float num2 = GeneralBuzzRange * GeneralBuzzRange;
		int num3 = 0;
		for (int i = 0; i < bees.Count; i++)
		{
			AnimatedBee value = bees[i];
			value.UpdateVisual(RandomTimedSeedManager.instance.currentSyncTime, this);
			UnityEngine.Vector3 position3 = value.visual.transform.position;
			float sqrMagnitude = (position3 - position).sqrMagnitude;
			if (sqrMagnitude < num)
			{
				position2 = position3;
				num = sqrMagnitude;
			}
			if (sqrMagnitude < num2)
			{
				zero += position3;
				num3++;
			}
			bees[i] = value;
		}
		nearbyBeeBuzz.transform.position = position2;
		if (num3 > 0)
		{
			generalBeeBuzz.transform.position = zero / num3;
			generalBeeBuzz.enabled = true;
		}
		else
		{
			generalBeeBuzz.enabled = false;
		}
	}

	private void OnSeedChange()
	{
		SRand rand = new SRand(RandomTimedSeedManager.instance.seed);
		List<BeePerchPoint> pickBuffer = new List<BeePerchPoint>(allPerchPoints.Count);
		List<BeePerchPoint> list = new List<BeePerchPoint>(loopSizePerBee);
		List<float> list2 = new List<float>(loopSizePerBee);
		for (int i = 0; i < bees.Count; i++)
		{
			AnimatedBee value = bees[i];
			list = new List<BeePerchPoint>(loopSizePerBee);
			list2 = new List<float>(loopSizePerBee);
			PickPoints(loopSizePerBee, pickBuffer, allPerchPoints, ref rand, list);
			for (int j = 0; j < list.Count; j++)
			{
				list2.Add(rand.NextFloat(BeeMinFlowerDuration, BeeMaxFlowerDuration));
			}
			value.InitRoute(list, list2, this);
			value.InitRouteTimestamps();
			bees[i] = value;
		}
	}

	private void PickPoints(int n, List<BeePerchPoint> pickBuffer, List<BeePerchPoint> allPerchPoints, ref SRand rand, List<BeePerchPoint> resultBuffer)
	{
		resultBuffer.Add(BeeHive);
		n--;
		int num = 100;
		while (pickBuffer.Count < n && num-- > 0)
		{
			n -= pickBuffer.Count;
			resultBuffer.AddRange(pickBuffer);
			pickBuffer.Clear();
			pickBuffer.AddRange(allPerchPoints);
			rand.Shuffle(pickBuffer);
		}
		resultBuffer.AddRange(pickBuffer.GetRange(pickBuffer.Count - n, n));
		pickBuffer.RemoveRange(pickBuffer.Count - n, n);
	}

	public static void RegisterAvoidPoint(GameObject obj)
	{
		avoidPoints.Add(obj);
	}

	public static void UnregisterAvoidPoint(GameObject obj)
	{
		avoidPoints.Remove(obj);
	}
}
public class ButterflySwarmManager : MonoBehaviour
{
	[SerializeField]
	private XSceneRef[] perchSections;

	[SerializeField]
	private int loopSizePerBee;

	[SerializeField]
	private int numBees;

	[SerializeField]
	private MeshRenderer beePrefab;

	[SerializeField]
	private float maxFlapSpeed;

	[SerializeField]
	private float minFlapSpeed;

	private List<AnimatedButterfly> butterflies;

	private List<List<GameObject>> allPerchZones = new List<List<GameObject>>();

	[field: SerializeField]
	public float PerchedFlapSpeed { get; private set; }

	[field: SerializeField]
	public float PerchedFlapPhase { get; private set; }

	[field: SerializeField]
	public float BeeSpeed { get; private set; }

	[field: SerializeField]
	public float BeeMaxTravelTime { get; private set; }

	[field: SerializeField]
	public float BeeAcceleration { get; private set; }

	[field: SerializeField]
	public float BeeJitterStrength { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Should be 0-1; closer to 1 = less damping")]
	public float BeeJitterDamping { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Limits how far the bee can get off course")]
	public float BeeMaxJitterRadius { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Bees stop jittering when close to their destination")]
	public float BeeNearDestinationRadius { get; private set; }

	[field: SerializeField]
	[field: Tooltip(">0 to get butterflies to align to their destination rotation as they land")]
	public float DestRotationAlignmentSpeed { get; private set; }

	[field: SerializeField]
	[field: Tooltip("Model orientation relative to the direction vector while flying")]
	public UnityEngine.Vector3 TravellingLocalRotationEuler { get; private set; }

	public UnityEngine.Quaternion TravellingLocalRotation { get; private set; }

	[field: SerializeField]
	public float AvoidPointRadius { get; private set; }

	[field: SerializeField]
	public float BeeMinFlowerDuration { get; private set; }

	[field: SerializeField]
	public float BeeMaxFlowerDuration { get; private set; }

	[field: SerializeField]
	public Color[] BeeColors { get; private set; }

	private void Awake()
	{
		TravellingLocalRotation = UnityEngine.Quaternion.Euler(TravellingLocalRotationEuler);
		butterflies = new List<AnimatedButterfly>(numBees);
		for (int i = 0; i < numBees; i++)
		{
			AnimatedButterfly item = default(AnimatedButterfly);
			item.InitVisual(beePrefab, this);
			if (BeeColors.Length != 0)
			{
				item.SetColor(BeeColors[i % BeeColors.Length]);
			}
			butterflies.Add(item);
		}
	}

	private void Start()
	{
		XSceneRef[] array = perchSections;
		foreach (XSceneRef xSceneRef in array)
		{
			if (!xSceneRef.TryResolve(out GameObject result))
			{
				continue;
			}
			List<GameObject> list = new List<GameObject>();
			allPerchZones.Add(list);
			foreach (Transform item in result.transform)
			{
				list.Add(item.gameObject);
			}
		}
		OnSeedChange();
		RandomTimedSeedManager.instance.AddCallbackOnSeedChanged(OnSeedChange);
	}

	private void OnDestroy()
	{
		RandomTimedSeedManager.instance.RemoveCallbackOnSeedChanged(OnSeedChange);
	}

	private void Update()
	{
		for (int i = 0; i < butterflies.Count; i++)
		{
			AnimatedButterfly value = butterflies[i];
			value.UpdateVisual(RandomTimedSeedManager.instance.currentSyncTime, this);
			butterflies[i] = value;
		}
	}

	private void OnSeedChange()
	{
		SRand rand = new SRand(RandomTimedSeedManager.instance.seed);
		List<List<GameObject>> list = new List<List<GameObject>>(allPerchZones.Count);
		for (int i = 0; i < allPerchZones.Count; i++)
		{
			List<GameObject> list2 = new List<GameObject>();
			list2.AddRange(allPerchZones[i]);
			list.Add(list2);
		}
		List<GameObject> list3 = new List<GameObject>(loopSizePerBee);
		List<float> list4 = new List<float>(loopSizePerBee);
		for (int j = 0; j < butterflies.Count; j++)
		{
			AnimatedButterfly value = butterflies[j];
			value.SetFlapSpeed(rand.NextFloat(minFlapSpeed, maxFlapSpeed));
			list3.Clear();
			list4.Clear();
			PickPoints(loopSizePerBee, list, ref rand, list3);
			for (int k = 0; k < list3.Count; k++)
			{
				list4.Add(rand.NextFloat(BeeMinFlowerDuration, BeeMaxFlowerDuration));
			}
			if (list3.Count == 0)
			{
				butterflies.Clear();
				break;
			}
			value.InitRoute(list3, list4, this);
			butterflies[j] = value;
		}
	}

	private void PickPoints(int n, List<List<GameObject>> pickBuffer, ref SRand rand, List<GameObject> resultBuffer)
	{
		int exclude = rand.NextInt(0, pickBuffer.Count);
		int num = -1;
		int num2 = n - 2;
		while (resultBuffer.Count < n)
		{
			int num3 = ((resultBuffer.Count >= num2) ? rand.NextIntWithExclusion2(0, pickBuffer.Count, num, exclude) : rand.NextIntWithExclusion(0, pickBuffer.Count, num));
			int num4 = 10;
			while (num3 == num || pickBuffer[num3].Count == 0)
			{
				num3 = (num3 + 1) % pickBuffer.Count;
				num4--;
				if (num4 <= 0)
				{
					return;
				}
			}
			num = num3;
			List<GameObject> list = pickBuffer[num];
			while (list.Count == 0)
			{
				num = (num + 1) % pickBuffer.Count;
				list = pickBuffer[num];
			}
			resultBuffer.Add(list[list.Count - 1]);
			list.RemoveAt(list.Count - 1);
		}
	}
}
