public class D20_ShaderManager : MonoBehaviour
{
	private Rigidbody rb;

	private UnityEngine.Vector3 lastPosition;

	public float updateInterval = 0.1f;

	public UnityEngine.Vector3 velocity;

	private Material material;

	private void Start()
	{
		rb = GetComponent<Rigidbody>();
		lastPosition = base.transform.position;
		Renderer component = GetComponent<Renderer>();
		material = component.material;
		material.SetVector("_Velocity", velocity);
		StartCoroutine(UpdateVelocityCoroutine());
	}

	private IEnumerator UpdateVelocityCoroutine()
	{
		while (true)
		{
			UnityEngine.Vector3 position = base.transform.position;
			velocity = (position - lastPosition) / updateInterval;
			lastPosition = position;
			material.SetVector("_Velocity", velocity);
			yield return new WaitForSeconds(updateInterval);
		}
	}
}
public class MicrophoneCosmetic : MonoBehaviour
{
	[SerializeField]
	private Transform mouthTransform;

	[SerializeField]
	private UnityEngine.Vector2 mouthProximityRampRange = new UnityEngine.Vector2(0.6f, 0.3f);

	private AudioSource audioSource;

	private float[] zero = new float[1];

	private void Awake()
	{
		audioSource = GetComponent<AudioSource>();
		if (!UnityEngine.Application.isEditor && UnityEngine.Application.platform == RuntimePlatform.Android && Microphone.devices.Length != 0)
		{
			audioSource.clip = Microphone.Start(Microphone.devices[0], loop: true, 10, 16000);
		}
		else
		{
			int sampleRate = AudioSettings.GetConfiguration().sampleRate;
			audioSource.clip = Microphone.Start(null, loop: true, 10, sampleRate);
		}
		audioSource.loop = true;
	}

	private void OnEnable()
	{
		int num = ((UnityEngine.Application.platform == RuntimePlatform.Android && Microphone.devices.Length != 0) ? Microphone.GetPosition(Microphone.devices[0]) : Microphone.GetPosition(null));
		num -= 10;
		if ((float)num < 0f)
		{
			num = audioSource.clip.samples + num - 1;
		}
		audioSource.GTPlay();
		audioSource.timeSamples = num;
	}

	private void OnDisable()
	{
		audioSource.GTStop();
	}

	private void Update()
	{
		UnityEngine.Vector3 vector = mouthTransform.position - base.transform.position;
		float sqrMagnitude = vector.sqrMagnitude;
		float num = 0f;
		if (sqrMagnitude < mouthProximityRampRange.x * mouthProximityRampRange.x)
		{
			float magnitude = vector.magnitude;
			num = Mathf.InverseLerp(mouthProximityRampRange.x, mouthProximityRampRange.y, magnitude);
		}
		if (num != audioSource.volume)
		{
			audioSource.volume = num;
		}
		int num2 = (audioSource.timeSamples -= 10);
		if ((float)num2 < 0f)
		{
			num2 = audioSource.clip.samples + num2 - 1;
		}
		audioSource.clip.SetData(zero, num2);
	}

	private void OnAudioFilterRead(float[] data, int channels)
	{
	}
}
public class RCHoverboard : RCVehicle
{
	private enum _EInputSource
	{
		None,
		StickX,
		StickForward,
		StickBack,
		Trigger,
		PrimaryFaceButton
	}

	[Serializable]
	private struct _SingleInputOption(_EInputSource source, AnimationCurve remapCurve)
	{
		public GTOption<StringEnum<_EInputSource>> source = new GTOption<StringEnum<_EInputSource>>(source);

		public GTOption<AnimationCurve> remapCurve = new GTOption<AnimationCurve>(remapCurve);

		public float Get(RCRemoteHoldable.RCInput input)
		{
			float x = source.ResolvedValue.Value switch
			{
				_EInputSource.Trigger => input.trigger, 
				_EInputSource.PrimaryFaceButton => (int)input.buttons, 
				_EInputSource.StickX => input.joystick.x, 
				_EInputSource.StickForward => math.saturate(input.joystick.y), 
				_EInputSource.StickBack => math.saturate(0f - input.joystick.y), 
				_EInputSource.None => 0f, 
				_ => 0f, 
			};
			return remapCurve.ResolvedValue.Evaluate(math.abs(x)) * math.sign(x);
		}
	}

	[SerializeField]
	private _SingleInputOption m_inputTurn = new _SingleInputOption(_EInputSource.StickX, new AnimationCurve(new Keyframe(0f, 0f, 0f, 0f, 0f, 0f), new Keyframe(0.1f, 0f, 0f, 1.25f, 0f, 0f), new Keyframe(0.9f, 1f, 1.25f, 0f, 0f, 0f), new Keyframe(1f, 1f, 0f, 0f, 0f, 0f)));

	[SerializeField]
	private _SingleInputOption m_inputThrustForward = new _SingleInputOption(_EInputSource.Trigger, AnimationCurves.EaseInCirc);

	[SerializeField]
	private _SingleInputOption m_inputThrustBack = new _SingleInputOption(_EInputSource.StickBack, new AnimationCurve(new Keyframe(0f, 0f, 0f, 0f, 0f, 0f), new Keyframe(0.9f, 0f, 0f, 9.9999f, 0.5825f, 0.3767f), new Keyframe(1f, 1f, 9.9999f, 1f, 0f, 0f)));

	[SerializeField]
	private _SingleInputOption m_inputJump = new _SingleInputOption(_EInputSource.PrimaryFaceButton, AnimationCurves.Linear);

	[Tooltip("Desired hover height above ground from this transform's position.")]
	[SerializeField]
	private float m_hoverHeight = 0.2f;

	[Tooltip("Upward force to maintain hover when below hoverHeight.")]
	[SerializeField]
	private float m_hoverForce = 200f;

	[Tooltip("Damping factor to smooth out vertical movement.")]
	[SerializeField]
	private float m_hoverDamp = 5f;

	[SerializeField]
	private LayerMask raycastLayers = -1;

	[SerializeField]
	private bool enableJumpInput = true;

	[Tooltip("Upward impulse force for jump.")]
	[SerializeField]
	private float m_jumpForce = 3.5f;

	private bool _hasJumped;

	[SerializeField]
	[HideInInspector]
	private float m_maxForwardSpeed = 6f;

	[SerializeField]
	[Tooltip("Time (seconds) to reach max forward speed from zero.")]
	private float m_forwardAccelTime = 2f;

	[SerializeField]
	[HideInInspector]
	private float m_maxTurnRate = 720f;

	[Tooltip("Time (seconds) to reach max turning rate.")]
	[SerializeField]
	private float m_turnAccelTime = 0.75f;

	[SerializeField]
	[HideInInspector]
	private float m_maxTiltAngle = 30f;

	[Tooltip("Time (seconds) to reach max tilt angle.")]
	[SerializeField]
	private float m_tiltTime = 0.1f;

	[Tooltip("Audio source for any motor or hover sound.")]
	[SerializeField]
	private AudioSource m_audioSource;

	[Tooltip("Looping motor/hover sound clip.")]
	[SerializeField]
	private AudioClip m_hoverSound;

	[Tooltip("Volume range for the hover sound (x = min, y = max).")]
	[SerializeField]
	private float2 m_hoverSoundVolumeMinMax = new float2(0.1f, 0.5f);

	[Tooltip("Time it takes for the volume to reach max value.")]
	[SerializeField]
	private float m_hoverSoundVolumeRampTime = 1f;

	private bool _hasAudioSource;

	private bool _hasHoverSound;

	private float _forwardAccel;

	private float _turnAccel;

	private float _tiltAccel;

	private float _currentTurnRate;

	private float _currentTurnAngle;

	private float _currentTiltAngle;

	private float _motorLevel;

	private float _MaxForwardSpeed
	{
		get
		{
			return m_maxForwardSpeed;
		}
		set
		{
			m_maxForwardSpeed = value;
			_forwardAccel = value / math.max(0.01f, m_forwardAccelTime);
		}
	}

	private float _MaxTurnRate
	{
		get
		{
			return m_maxTurnRate;
		}
		set
		{
			m_maxTurnRate = value;
			_turnAccel = value / math.max(1E-06f, m_turnAccelTime);
		}
	}

	private float _MaxTiltAngle
	{
		get
		{
			return m_maxTiltAngle;
		}
		set
		{
			m_maxTiltAngle = value;
			_tiltAccel = value / math.max(1E-06f, m_tiltTime);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_hasAudioSource = m_audioSource != null;
		_hasHoverSound = m_hoverSound != null;
		_MaxForwardSpeed = m_maxForwardSpeed;
		_MaxTurnRate = m_maxTurnRate;
		_MaxTiltAngle = m_maxTiltAngle;
	}

	protected override void AuthorityBeginDocked()
	{
		base.AuthorityBeginDocked();
		_currentTurnRate = 0f;
		_currentTiltAngle = 0f;
		float3 to = _ProjectOnPlane(base.transform.forward, math.up());
		_currentTurnAngle = _SignedAngle(new float3(0f, 0f, 1f), to, new float3(0f, 1f, 0f));
		_motorLevel = 0f;
		if (_hasAudioSource)
		{
			m_audioSource.Stop();
			m_audioSource.volume = 0f;
		}
		if (connectedRemote == null)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	protected override void AuthorityUpdate(float dt)
	{
		base.AuthorityUpdate(dt);
		if (localState == State.Mobilized)
		{
			float x = math.length(activeInput.joystick);
			_motorLevel = math.saturate(x);
			if (hasNetworkSync)
			{
				networkSync.syncedState.dataA = (byte)(uint)(_motorLevel * 255f);
			}
		}
		else
		{
			_motorLevel = 0f;
		}
	}

	protected override void RemoteUpdate(float dt)
	{
		base.RemoteUpdate(dt);
		if (localState == State.Mobilized && hasNetworkSync)
		{
			_motorLevel = (float)(int)networkSync.syncedState.dataA / 255f;
		}
		else
		{
			_motorLevel = 0f;
		}
	}

	protected override void SharedUpdate(float dt)
	{
		base.SharedUpdate(dt);
		switch (localState)
		{
		case State.Mobilized:
			if (_hasAudioSource && _hasHoverSound)
			{
				if (localStatePrev != State.Mobilized)
				{
					m_audioSource.volume = 0f;
					m_audioSource.clip = m_hoverSound;
					m_audioSource.loop = true;
					m_audioSource.GTPlay();
				}
				else
				{
					float target = math.lerp(m_hoverSoundVolumeMinMax.x, m_hoverSoundVolumeMinMax.y, _motorLevel);
					float maxDelta = m_hoverSoundVolumeMinMax.y / m_hoverSoundVolumeRampTime * dt;
					m_audioSource.volume = _MoveTowards(m_audioSource.volume, target, maxDelta);
				}
			}
			break;
		case State.Disabled:
		case State.DockedLeft:
		case State.DockedRight:
		case State.Crashed:
			break;
		}
	}

	protected void FixedUpdate()
	{
		if (base.HasLocalAuthority && localState == State.Mobilized)
		{
			float fixedDeltaTime = Time.fixedDeltaTime;
			float num = m_inputThrustForward.Get(activeInput) - m_inputThrustBack.Get(activeInput);
			float num2 = m_inputTurn.Get(activeInput);
			float num3 = m_inputJump.Get(activeInput);
			RaycastHit hitInfo;
			bool flag = Physics.Raycast(base.transform.position, UnityEngine.Vector3.down, out hitInfo, 10f, raycastLayers, QueryTriggerInteraction.Collide);
			bool flag2 = flag && hitInfo.distance <= m_hoverHeight + 0.1f;
			if (enableJumpInput && num3 > 0.001f && flag2 && !_hasJumped)
			{
				rb.AddForce(UnityEngine.Vector3.up * m_jumpForce, ForceMode.Impulse);
				_hasJumped = true;
			}
			else if (num3 <= 0.001f)
			{
				_hasJumped = false;
			}
			float target = num2 * _MaxTurnRate;
			_currentTurnRate = _MoveTowards(_currentTurnRate, target, _turnAccel * fixedDeltaTime);
			_currentTurnAngle += _currentTurnRate * fixedDeltaTime;
			float target2 = math.lerp(0f - m_maxTiltAngle, m_maxTiltAngle, math.unlerp(-1f, 1f, num));
			_currentTiltAngle = _MoveTowards(_currentTiltAngle, target2, _tiltAccel * fixedDeltaTime);
			base.transform.rotation = quaternion.EulerXYZ(math.radians(new float3(_currentTiltAngle, _currentTurnAngle, 0f)));
			float3 float5 = base.transform.forward;
			float num4 = math.dot(float5, rb.linearVelocity);
			float num5 = num * m_maxForwardSpeed;
			float num6 = ((math.abs(num5) > 0.001f && ((num5 > 0f && num4 < num5) || (num5 < 0f && num4 > num5))) ? math.sign(num5) : 0f);
			rb.AddForce(float5 * _forwardAccel * num6 * rb.mass, ForceMode.Force);
			if (flag)
			{
				float num7 = math.saturate(m_hoverHeight - hitInfo.distance);
				float num8 = math.dot(rb.linearVelocity, UnityEngine.Vector3.up);
				float num9 = num7 * m_hoverForce - num8 * m_hoverDamp;
				rb.AddForce(math.up() * num9, ForceMode.Force);
			}
		}
	}

	protected void OnCollisionEnter(UnityEngine.Collision collision)
	{
		GameObject gameObject = collision.collider.gameObject;
		bool flag = gameObject.IsOnLayer(UnityLayer.GorillaThrowable);
		bool flag2 = gameObject.IsOnLayer(UnityLayer.GorillaHand);
		if (!(flag || flag2) || localState != State.Mobilized)
		{
			return;
		}
		UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
		if (flag2)
		{
			GorillaHandClimber component = gameObject.GetComponent<GorillaHandClimber>();
			if (component != null)
			{
				vector = GTPlayer.Instance.GetHandVelocityTracker(component.xrNode == XRNode.LeftHand).GetAverageVelocity(worldSpace: true);
			}
		}
		else if (collision.rigidbody != null)
		{
			vector = collision.rigidbody.linearVelocity;
		}
		if ((flag || vector.sqrMagnitude > 0.01f) && base.HasLocalAuthority)
		{
			AuthorityApplyImpact(vector, flag);
			if (networkSync != null)
			{
				networkSync.photonView.RPC("HitRCVehicleRPC", RpcTarget.Others, vector, flag);
			}
		}
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private float _MoveTowards(float current, float target, float maxDelta)
	{
		if (!(math.abs(target - current) <= maxDelta))
		{
			return current + math.sign(target - current) * maxDelta;
		}
		return target;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private float _SignedAngle(float3 from, float3 to, float3 axis)
	{
		float3 x = math.normalize(from);
		float3 y = math.normalize(to);
		float x2 = math.acos(math.dot(x, y));
		float num = math.sign(math.dot(math.cross(x, y), axis));
		return math.degrees(x2) * num;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private float3 _ProjectOnPlane(float3 vector, float3 planeNormal)
	{
		return vector - math.dot(vector, planeNormal) * planeNormal;
	}
}
public class RCShip : RCHoverboard
{
	[Header("RCShip - Events")]
	public UnityEvent OnFire;

	public UnityEvent<bool> OnCannonSideChanged;

	public UnityEvent OnMoveStarted;

	public UnityEvent OnMoveStopped;

	[Header("RCShip - Cannon Rotation")]
	[SerializeField]
	private Transform cannonTransform;

	[SerializeField]
	private float leftYaw = -45f;

	[SerializeField]
	private float rightYaw = 45f;

	[SerializeField]
	private float cannonYawSpeed = 240f;

	[Header("RCShip - Input")]
	[Range(0f, 1f)]
	[SerializeField]
	private float triggerPressThreshold = 0.6f;

	[Range(0f, 1f)]
	[SerializeField]
	private float triggerReleaseThreshold = 0.1f;

	[Range(0f, 1f)]
	[SerializeField]
	private float facePressThreshold = 0.6f;

	[Range(0f, 1f)]
	[SerializeField]
	private float faceReleaseThreshold = 0.1f;

	[Header("RCShip - Movement Detection")]
	[Tooltip("Minimum speed to consider the ship moving")]
	[SerializeField]
	private float movingSpeedThreshold = 0.05f;

	private bool prevTriggerDown;

	private bool prevFaceDown;

	private bool faceIsDown;

	private bool triggerIsDown;

	private bool armedAfterMobilize;

	private bool cannonToLeft;

	private const byte CannonLeftBit = 1;

	private const byte FireFlipBit = 2;

	private const byte MovingBit = 4;

	private bool lastFireFlip;

	private bool lastCannonToLeft;

	private bool lastIsMoving;

	private bool isMovingShared;

	private byte GetDataB()
	{
		if (!hasNetworkSync)
		{
			return 0;
		}
		return networkSync.syncedState.dataB;
	}

	private void SetDataB(byte b)
	{
		if (hasNetworkSync)
		{
			networkSync.syncedState.dataB = b;
		}
	}

	private void WriteCannonBit(bool toLeft)
	{
		if (hasNetworkSync)
		{
			byte dataB = GetDataB();
			dataB = (toLeft ? ((byte)(dataB | 1)) : ((byte)(dataB & -2)));
			SetDataB(dataB);
		}
	}

	private bool ReadCannonBit()
	{
		if (!hasNetworkSync)
		{
			return cannonToLeft;
		}
		return (GetDataB() & 1) != 0;
	}

	private bool ReadFireFlip()
	{
		return (GetDataB() & 2) != 0;
	}

	protected override void AuthorityUpdate(float dt)
	{
		base.AuthorityUpdate(dt);
		float trigger = activeInput.trigger;
		float num = (int)activeInput.buttons;
		if (localState == State.Mobilized && localStatePrev != State.Mobilized)
		{
			armedAfterMobilize = false;
			if (trigger >= triggerReleaseThreshold)
			{
				triggerIsDown = true;
			}
		}
		if (localState == State.Mobilized)
		{
			if (!armedAfterMobilize && trigger <= triggerReleaseThreshold)
			{
				armedAfterMobilize = true;
				triggerIsDown = false;
			}
			if (armedAfterMobilize)
			{
				if (!triggerIsDown && trigger >= triggerPressThreshold)
				{
					triggerIsDown = true;
					OnFire?.Invoke();
					if (hasNetworkSync)
					{
						byte dataB = GetDataB();
						dataB ^= 2;
						SetDataB(dataB);
						lastFireFlip = (dataB & 2) != 0;
					}
				}
				else if (triggerIsDown && trigger <= triggerReleaseThreshold)
				{
					triggerIsDown = false;
				}
			}
			if (!faceIsDown && num >= facePressThreshold)
			{
				faceIsDown = true;
				cannonToLeft = !cannonToLeft;
				WriteCannonBit(cannonToLeft);
			}
			else if (faceIsDown && num <= faceReleaseThreshold)
			{
				faceIsDown = false;
			}
		}
		else
		{
			if (faceIsDown && num <= faceReleaseThreshold)
			{
				faceIsDown = false;
			}
			armedAfterMobilize = false;
			if (triggerIsDown && trigger <= triggerReleaseThreshold)
			{
				triggerIsDown = false;
			}
		}
		if (hasNetworkSync)
		{
			byte dataB2 = GetDataB();
			if (localState == State.Mobilized && rb != null && rb.linearVelocity.sqrMagnitude >= movingSpeedThreshold * movingSpeedThreshold)
			{
				dataB2 |= 4;
				isMovingShared = true;
			}
			else
			{
				dataB2 = (byte)(dataB2 & -5);
				isMovingShared = false;
			}
			SetDataB(dataB2);
		}
		else
		{
			isMovingShared = localState == State.Mobilized && rb != null && rb.linearVelocity.sqrMagnitude >= movingSpeedThreshold * movingSpeedThreshold;
		}
	}

	protected override void RemoteUpdate(float dt)
	{
		base.RemoteUpdate(dt);
		if (!hasNetworkSync)
		{
			return;
		}
		cannonToLeft = ReadCannonBit();
		bool flag = ReadFireFlip();
		if (!base.HasLocalAuthority)
		{
			if (flag != lastFireFlip)
			{
				lastFireFlip = flag;
				OnFire?.Invoke();
			}
			byte dataB = GetDataB();
			isMovingShared = (dataB & 4) != 0;
		}
		else
		{
			lastFireFlip = flag;
			isMovingShared = localState == State.Mobilized && rb != null && rb.linearVelocity.sqrMagnitude >= movingSpeedThreshold * movingSpeedThreshold;
		}
	}

	protected override void SharedUpdate(float dt)
	{
		base.SharedUpdate(dt);
		if (cannonTransform != null)
		{
			float target = (cannonToLeft ? leftYaw : rightYaw);
			UnityEngine.Vector3 localEulerAngles = cannonTransform.localEulerAngles;
			localEulerAngles.z = Mathf.MoveTowardsAngle(localEulerAngles.z, target, cannonYawSpeed * dt);
			cannonTransform.localEulerAngles = localEulerAngles;
		}
		if (cannonToLeft != lastCannonToLeft)
		{
			lastCannonToLeft = cannonToLeft;
			OnCannonSideChanged?.Invoke(cannonToLeft);
		}
		bool flag = localState == State.Mobilized && isMovingShared;
		if (flag != lastIsMoving)
		{
			lastIsMoving = flag;
			if (flag)
			{
				OnMoveStarted?.Invoke();
			}
			else
			{
				OnMoveStopped?.Invoke();
			}
		}
	}
}
public class MoonController : MonoBehaviour
{
	public enum Scenes
	{
		Forest,
		Bayou,
		Beach,
		Canyon,
		Clouds,
		City,
		Metropolis,
		Mountain
	}

	[Serializable]
	public struct SceneData
	{
		public Scenes scene;

		public Transform referencePoint;

		public bool overridePlacement;

		public Placement PlacementOverride;
	}

	[Serializable]
	public struct Placement
	{
		public UnityEngine.Vector2 radiusRange;

		public UnityEngine.Vector2 heightRange;

		public UnityEngine.Vector2 scaleRange;

		public float restAngle;
	}

	[SerializeField]
	private List<SceneData> scenes = new List<SceneData>();

	[SerializeField]
	private Scenes activeScene;

	[SerializeField]
	private Placement defaultPlacement;

	[SerializeField]
	[Range(0f, 1f)]
	private float distance;

	[SerializeField]
	private bool alwaysInTheSky;

	[Header("Model Swap")]
	[SerializeField]
	private Transform defaultMoon;

	[SerializeField]
	private Transform openMoon;

	[Header("Animation")]
	[SerializeField]
	private Animator openMoonAnimator;

	[SerializeField]
	private float eyeOpenDistThreshold = 0.9f;

	[SerializeField]
	private float eyeCloseDistThreshold = 0.05f;

	[Header("Debug")]
	[SerializeField]
	private bool debugOverrideTimeOfDay;

	[SerializeField]
	[Range(0f, 4f)]
	private float timeOfDayOverride;

	[SerializeField]
	private bool debugOverrideCrackProgress;

	[SerializeField]
	[Range(0f, 1f)]
	private float crackProgress;

	[SerializeField]
	private bool debugOverrideCrackDayInOctober;

	[SerializeField]
	[Range(1f, 31f)]
	private int crackDayInOctoberOverride = 4;

	[SerializeField]
	private MeshRenderer crackRenderer;

	private int crackStartDayOfYear;

	private int crackEndDayOfYear;

	private float orbitAngle;

	private int eyeOpenHash;

	private bool openEyeModelEnabled;

	private float currentlySetCrackProgress;

	private MaterialPropertyBlock crackMaterialPropertyBlock;

	private bool debugDrawOrbit;

	private Dictionary<GTZone, Scenes> zoneToSceneMapping = new Dictionary<GTZone, Scenes>();

	private const float moonFallStart = 13f / 150f;

	private const float moonFallEnd = 0.22f;

	private const float moonRiseStart = 0.53999996f;

	private const float moonRiseEnd = 0.6733333f;

	public float Distance => distance;

	private float TimeOfDay
	{
		get
		{
			if (debugOverrideTimeOfDay)
			{
				return Mathf.Repeat(timeOfDayOverride, 1f);
			}
			if (!(BetterDayNightManager.instance != null))
			{
				return 1f;
			}
			return BetterDayNightManager.instance.NormalizedTimeOfDay;
		}
	}

	public void SetEyeOpenAnimation()
	{
		openMoonAnimator.SetBool(eyeOpenHash, value: true);
	}

	public void StartEyeCloseAnimation()
	{
		openMoonAnimator.SetBool(eyeOpenHash, value: false);
	}

	private void Start()
	{
		eyeOpenHash = Animator.StringToHash("EyeOpen");
		zoneToSceneMapping.Add(GTZone.forest, Scenes.Forest);
		zoneToSceneMapping.Add(GTZone.city, Scenes.City);
		zoneToSceneMapping.Add(GTZone.basement, Scenes.City);
		zoneToSceneMapping.Add(GTZone.canyon, Scenes.Canyon);
		zoneToSceneMapping.Add(GTZone.beach, Scenes.Beach);
		zoneToSceneMapping.Add(GTZone.mountain, Scenes.Mountain);
		zoneToSceneMapping.Add(GTZone.skyJungle, Scenes.Clouds);
		zoneToSceneMapping.Add(GTZone.cave, Scenes.Forest);
		zoneToSceneMapping.Add(GTZone.cityWithSkyJungle, Scenes.City);
		zoneToSceneMapping.Add(GTZone.tutorial, Scenes.Forest);
		zoneToSceneMapping.Add(GTZone.rotating, Scenes.Forest);
		zoneToSceneMapping.Add(GTZone.none, Scenes.Forest);
		zoneToSceneMapping.Add(GTZone.Metropolis, Scenes.Metropolis);
		zoneToSceneMapping.Add(GTZone.cityNoBuildings, Scenes.City);
		zoneToSceneMapping.Add(GTZone.attic, Scenes.Forest);
		zoneToSceneMapping.Add(GTZone.arcade, Scenes.City);
		zoneToSceneMapping.Add(GTZone.bayou, Scenes.Bayou);
		if (ZoneManagement.instance != null)
		{
			ZoneManagement instance = ZoneManagement.instance;
			instance.onZoneChanged = (Action)Delegate.Combine(instance.onZoneChanged, new Action(OnZoneChanged));
		}
		if (GreyZoneManager.Instance != null)
		{
			GreyZoneManager.Instance.RegisterMoon(this);
		}
		crackStartDayOfYear = new DateTime(2024, 10, 4).DayOfYear;
		crackEndDayOfYear = new DateTime(2024, 10, 25).DayOfYear;
		if (crackRenderer != null)
		{
			currentlySetCrackProgress = 1f;
			crackMaterialPropertyBlock = new MaterialPropertyBlock();
			crackRenderer.GetPropertyBlock(crackMaterialPropertyBlock);
			crackMaterialPropertyBlock.SetFloat(ShaderProps._Progress, currentlySetCrackProgress);
			crackRenderer.SetPropertyBlock(crackMaterialPropertyBlock);
		}
		orbitAngle = 0f;
		UpdateCrack();
		UpdatePlacement();
	}

	private void OnDestroy()
	{
		if (GreyZoneManager.Instance != null)
		{
			GreyZoneManager.Instance.UnregisterMoon(this);
		}
	}

	private void OnZoneChanged()
	{
		ZoneManagement instance = ZoneManagement.instance;
		Scenes scenes = Scenes.Forest;
		for (int i = 0; i < instance.activeZones.Count; i++)
		{
			if (zoneToSceneMapping.TryGetValue(instance.activeZones[i], out var value) && value > scenes)
			{
				scenes = value;
			}
		}
		UpdateActiveScene(scenes);
	}

	private void UpdateActiveScene(Scenes nextScene)
	{
		activeScene = nextScene;
		UpdateCrack();
		UpdatePlacement();
	}

	private void Update()
	{
		UpdateCrack();
		if (!alwaysInTheSky)
		{
			float timeOfDay = TimeOfDay;
			bool num = timeOfDay > 0.53999996f && timeOfDay < 0.6733333f;
			bool flag = timeOfDay > 13f / 150f && timeOfDay < 0.22f;
			bool flag2 = timeOfDay <= 13f / 150f || timeOfDay >= 0.6733333f;
			float num2 = orbitAngle;
			num2 = (num ? Mathf.Lerp(MathF.PI, 0f, (timeOfDay - 0.53999996f) / 0.13333333f) : (flag ? Mathf.Lerp(0f, -MathF.PI, (timeOfDay - 13f / 150f) / 0.13333333f) : ((!flag2) ? MathF.PI : 0f)));
			if (orbitAngle != num2)
			{
				orbitAngle = num2;
				UpdateCrack();
				UpdatePlacement();
			}
		}
	}

	public void UpdateDistance(float nextDistance)
	{
		distance = nextDistance;
		UpdateVisualState();
		UpdatePlacement();
	}

	public void UpdateVisualState()
	{
		bool flag = false;
		if (GreyZoneManager.Instance != null)
		{
			flag = GreyZoneManager.Instance.GreyZoneActive;
		}
		if (flag && openEyeModelEnabled && distance < eyeOpenDistThreshold && !openMoonAnimator.GetBool(eyeOpenHash))
		{
			openMoonAnimator.SetBool(eyeOpenHash, value: true);
		}
		else if (!flag && distance > eyeCloseDistThreshold && openMoonAnimator.GetBool(eyeOpenHash))
		{
			openMoonAnimator.SetBool(eyeOpenHash, value: false);
		}
	}

	public void UpdatePlacement()
	{
		if (alwaysInTheSky)
		{
			UpdatePlacementSimple();
		}
		else
		{
			UpdatePlacementOrbit();
		}
	}

	private void UpdatePlacementSimple()
	{
		SceneData sceneData = scenes[(int)activeScene];
		Transform referencePoint = sceneData.referencePoint;
		Placement placement = (sceneData.overridePlacement ? sceneData.PlacementOverride : defaultPlacement);
		float num = Mathf.Lerp(placement.heightRange.x, placement.heightRange.y, distance);
		float num2 = Mathf.Lerp(placement.radiusRange.x, placement.radiusRange.y, distance);
		float num3 = Mathf.Lerp(placement.scaleRange.x, placement.scaleRange.y, distance);
		float restAngle = placement.restAngle;
		UnityEngine.Vector3 position = referencePoint.position;
		position.y += num;
		position.x += num2 * Mathf.Cos(restAngle * (MathF.PI / 180f));
		position.z += num2 * Mathf.Sin(restAngle * (MathF.PI / 180f));
		base.transform.position = position;
		base.transform.rotation = UnityEngine.Quaternion.LookRotation(referencePoint.position - base.transform.position);
		base.transform.localScale = UnityEngine.Vector3.one * num3;
	}

	public void UpdatePlacementOrbit()
	{
		SceneData sceneData = scenes[(int)activeScene];
		Transform referencePoint = sceneData.referencePoint;
		Placement placement = (sceneData.overridePlacement ? sceneData.PlacementOverride : defaultPlacement);
		float y = placement.heightRange.y;
		float y2 = placement.radiusRange.y;
		UnityEngine.Vector3 position = referencePoint.position;
		position.y += y;
		position.x += y2 * Mathf.Cos(placement.restAngle * (MathF.PI / 180f));
		position.z += y2 * Mathf.Sin(placement.restAngle * (MathF.PI / 180f));
		float num = Mathf.Sqrt(y * y + y2 * y2);
		float num2 = Mathf.Atan2(y, y2);
		UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.AngleAxis(57.29578f * num2, UnityEngine.Vector3.Cross(position - referencePoint.position, UnityEngine.Vector3.up));
		float f = placement.restAngle * (MathF.PI / 180f) + orbitAngle;
		UnityEngine.Vector3 vector = referencePoint.position + quaternion2 * new UnityEngine.Vector3(Mathf.Cos(f), 0f, Mathf.Sin(f)) * num;
		if (distance < 1f)
		{
			UnityEngine.Vector3 position2 = referencePoint.position;
			position2.y += placement.heightRange.x;
			position2.x += placement.radiusRange.x * Mathf.Cos(placement.restAngle * (MathF.PI / 180f));
			position2.z += placement.radiusRange.x * Mathf.Sin(placement.restAngle * (MathF.PI / 180f));
			vector = ((!(Mathf.Abs(orbitAngle) < 0.9424779f)) ? UnityEngine.Vector3.Lerp(position2, position, distance) : UnityEngine.Vector3.Lerp(position2, vector, distance));
		}
		base.transform.position = vector;
		base.transform.rotation = UnityEngine.Quaternion.LookRotation(referencePoint.position - base.transform.position);
		base.transform.localScale = UnityEngine.Vector3.one * Mathf.Lerp(placement.scaleRange.x, placement.scaleRange.y, distance);
		if (debugDrawOrbit)
		{
			int num3 = 32;
			float timeOfDay = TimeOfDay;
			float num4 = 13f / 150f;
			float num5 = 37f / 150f;
			float num6 = 19f / 30f;
			float num7 = 0.76f;
			bool flag = timeOfDay > num4 && timeOfDay < num5;
			bool num8 = timeOfDay > num6 && timeOfDay < num7;
			bool flag2 = timeOfDay <= num4 || timeOfDay >= num7;
			Color color = (num8 ? Color.red : (flag2 ? Color.green : (flag ? Color.yellow : Color.blue)));
			UnityEngine.Vector3 v = referencePoint.position + quaternion2 * new UnityEngine.Vector3(Mathf.Cos(0f), 0f, Mathf.Sin(0f)) * num;
			for (int i = 1; i <= num3; i++)
			{
				float num9 = (float)i / (float)num3;
				UnityEngine.Vector3 vector2 = referencePoint.position + quaternion2 * new UnityEngine.Vector3(Mathf.Cos(MathF.PI * 2f * num9), 0f, Mathf.Sin(MathF.PI * 2f * num9)) * num;
				DebugUtil.DrawLine(v, vector2, color, depthTest: false);
				v = vector2;
			}
		}
	}

	private void UpdateCrack()
	{
		bool flag = GreyZoneManager.Instance != null && GreyZoneManager.Instance.GreyZoneAvailable;
		if (flag && !openEyeModelEnabled)
		{
			openEyeModelEnabled = true;
			defaultMoon.gameObject.SetActive(value: false);
			openMoon.gameObject.SetActive(value: true);
		}
		else if (!flag && openEyeModelEnabled)
		{
			openEyeModelEnabled = false;
			defaultMoon.gameObject.SetActive(value: true);
			openMoon.gameObject.SetActive(value: false);
		}
		if (!flag && GorillaComputer.instance != null)
		{
			DateTime dateTime = GorillaComputer.instance.GetServerTime();
			if (debugOverrideCrackDayInOctober)
			{
				dateTime = new DateTime(2024, 10, Mathf.Clamp(crackDayInOctoberOverride, 1, 31));
			}
			float value = Mathf.InverseLerp(crackStartDayOfYear, crackEndDayOfYear, dateTime.DayOfYear);
			if (debugOverrideCrackProgress)
			{
				value = crackProgress;
			}
			float num = 1f - Mathf.Clamp01(value);
			if (crackRenderer != null && Mathf.Abs(num - currentlySetCrackProgress) > Mathf.Epsilon)
			{
				currentlySetCrackProgress = num;
				crackMaterialPropertyBlock.SetFloat(ShaderProps._Progress, currentlySetCrackProgress);
				crackRenderer.SetPropertyBlock(crackMaterialPropertyBlock);
			}
		}
	}
}
public class GreyZoneManager : MonoBehaviourPun, IPunObservable, IInRoomCallbacks
