	public void DeregisterSummoner(GreyZoneSummoner summoner)
	{
		if (activeSummoners.Contains(summoner))
		{
			activeSummoners.Remove(summoner);
		}
	}

	public void RegisterMoon(MoonController moon)
	{
		moonController = moon;
	}

	public void UnregisterMoon(MoonController moon)
	{
		if (moonController == moon)
		{
			moonController = null;
		}
	}

	public void ActivateGreyZoneAuthority()
	{
		greyZoneActive = true;
		photonConnectedDuringActivation = PhotonNetwork.InRoom;
		greyZoneActivationTime = (photonConnectedDuringActivation ? PhotonNetwork.Time : ((double)Time.time));
		ActivateGreyZoneLocal();
	}

	private void ActivateGreyZoneLocal()
	{
		Shader.SetGlobalInt(_GreyZoneActive, 1);
		GTPlayer instance = GTPlayer.Instance;
		if (instance != null)
		{
			instance.SetGravityOverride(this, GravityOverrideFunction);
			gravityOverrideSet = true;
		}
		if (MusicManager.Instance != null)
		{
			MusicManager.Instance.FadeOutMusic(2f);
		}
		if (audioFadeCoroutine != null)
		{
			StopCoroutine(audioFadeCoroutine);
		}
		audioFadeCoroutine = StartCoroutine(FadeAudioIn(greyZoneAmbience, greyZoneAmbienceVolume, ambienceFadeTime));
		if (greyZoneAmbience != null)
		{
			greyZoneAmbience.GTPlay();
		}
		greyZoneParticles.gameObject.SetActive(value: true);
		summoningProgress = 1f;
		UpdateSummonerVisuals();
		for (int i = 0; i < activeSummoners.Count; i++)
		{
			activeSummoners[i].OnGreyZoneActivated();
		}
		if (OnGreyZoneActivated != null)
		{
			OnGreyZoneActivated();
		}
	}

	public void LocalSimpleActivation(bool onOff, float gravityFactor)
	{
		GTPlayer instance = GTPlayer.Instance;
		if (!(instance == null) && PlayerPrefs.GetString("didTutorial", "nope") == "done")
		{
			simpleGravityFactor = Mathf.Clamp(gravityFactor, 0f, 5f);
			Shader.SetGlobalInt(_GreyZoneActive, onOff ? 1 : 0);
			if (onOff)
			{
				instance.SetGravityOverride(this, SimpleGravityOverrideFunction);
			}
			else
			{
				instance.UnsetGravityOverride(this);
			}
			gravityOverrideSet = onOff;
			greyZoneParticles.gameObject.SetActive(onOff);
		}
	}

	public void DeactivateGreyZoneAuthority()
	{
		greyZoneActive = false;
		foreach (KeyValuePair<int, (VRRig, GreyZoneSummoner)> summoningPlayer in summoningPlayers)
		{
			summoningPlayerProgress[summoningPlayer.Key] = 0f;
		}
		DeactivateGreyZoneLocal();
	}

	private void DeactivateGreyZoneLocal()
	{
		Shader.SetGlobalInt(_GreyZoneActive, 0);
		if (MusicManager.Instance != null)
		{
			MusicManager.Instance.FadeInMusic(4f);
		}
		if (audioFadeCoroutine != null)
		{
			StopCoroutine(audioFadeCoroutine);
		}
		audioFadeCoroutine = StartCoroutine(FadeAudioOut(greyZoneAmbience, ambienceFadeTime));
		greyZoneParticles.gameObject.SetActive(value: false);
		summoningProgress = 0f;
		UpdateSummonerVisuals();
		if (OnGreyZoneDeactivated != null)
		{
			OnGreyZoneDeactivated();
		}
	}

	public void ForceStopGreyZone()
	{
		greyZoneActive = false;
		Shader.SetGlobalInt(_GreyZoneActive, 0);
		GTPlayer instance = GTPlayer.Instance;
		if (instance != null)
		{
			instance.UnsetGravityOverride(this);
		}
		gravityOverrideSet = false;
		if (moonController != null)
		{
			moonController.UpdateDistance(1f);
		}
		if (MusicManager.Instance != null)
		{
			MusicManager.Instance.FadeInMusic(0f);
		}
		if (greyZoneAmbience != null)
		{
			greyZoneAmbience.volume = 0f;
			greyZoneAmbience.GTStop();
		}
		greyZoneParticles.gameObject.SetActive(value: false);
		summoningProgress = 0f;
		UpdateSummonerVisuals();
		if (OnGreyZoneDeactivated != null)
		{
			OnGreyZoneDeactivated();
		}
	}

	public void GravityOverrideFunction(GTPlayer player)
	{
		gravityReductionAmount = 0f;
		if (moonController != null)
		{
			gravityReductionAmount = Mathf.InverseLerp(1f - skyMonsterDistGravityRampBuffer, skyMonsterDistGravityRampBuffer, moonController.Distance);
		}
		float num = Mathf.Lerp(1f, gravityFactorOptions[gravityFactorOptionSelection], gravityReductionAmount);
		player.AddForce(Physics.gravity * num * player.scale, ForceMode.Acceleration);
	}

	public void SimpleGravityOverrideFunction(GTPlayer player)
	{
		player.AddForce(Physics.gravity * simpleGravityFactor * player.scale, ForceMode.Acceleration);
	}

	private IEnumerator FadeAudioIn(AudioSource source, float maxVolume, float duration)
	{
		if (source != null)
		{
			float startingVolume = source.volume;
			float startTime = Time.time;
			source.GTPlay();
			for (float num = 0f; num < 1f; num = (Time.time - startTime) / duration)
			{
				source.volume = Mathf.Lerp(startingVolume, maxVolume, num);
				yield return null;
			}
			source.volume = maxVolume;
		}
	}

	private IEnumerator FadeAudioOut(AudioSource source, float duration)
	{
		if (source != null)
		{
			float startingVolume = source.volume;
			float startTime = Time.time;
			for (float num = 0f; num < 1f; num = (Time.time - startTime) / duration)
			{
				source.volume = Mathf.Lerp(startingVolume, 0f, num);
				yield return null;
			}
			source.volume = 0f;
			source.Stop();
		}
	}

	public void VRRigEnteredSummonerProximity(VRRig rig, GreyZoneSummoner summoner)
	{
		if (!summoningPlayers.ContainsKey(rig.Creator.ActorNumber))
		{
			summoningPlayers.Add(rig.Creator.ActorNumber, (rig, summoner));
			summoningPlayerProgress.Add(rig.Creator.ActorNumber, 0f);
		}
	}

	public void VRRigExitedSummonerProximity(VRRig rig, GreyZoneSummoner summoner)
	{
		if (summoningPlayers.ContainsKey(rig.Creator.ActorNumber))
		{
			summoningPlayers.Remove(rig.Creator.ActorNumber);
			summoningPlayerProgress.Remove(rig.Creator.ActorNumber);
		}
	}

	private void UpdateSummonerVisuals()
	{
		bool greyZoneAvailable = GreyZoneAvailable;
		for (int i = 0; i < activeSummoners.Count; i++)
		{
			activeSummoners[i].UpdateProgressFeedback(greyZoneAvailable);
		}
	}

	private void ValidateSummoningPlayers()
	{
		invalidSummoners.Clear();
		foreach (KeyValuePair<int, (VRRig, GreyZoneSummoner)> summoningPlayer in summoningPlayers)
		{
			VRRig item = summoningPlayer.Value.Item1;
			GreyZoneSummoner item2 = summoningPlayer.Value.Item2;
			if (item.Creator.ActorNumber != summoningPlayer.Key || (item.head.rigTarget.position - item2.SummoningFocusPoint).sqrMagnitude > item2.SummonerMaxDistance * item2.SummonerMaxDistance)
			{
				invalidSummoners.Add(summoningPlayer.Key);
			}
		}
		foreach (int invalidSummoner in invalidSummoners)
		{
			summoningPlayers.Remove(invalidSummoner);
			summoningPlayerProgress.Remove(invalidSummoner);
		}
	}

	private int DayNightOverrideFunction(int inputIndex)
	{
		int num = 0;
		int num2 = 8;
		int num3 = inputIndex - num;
		int num4 = num2 - inputIndex;
		if (num3 <= 0 || num4 <= 0)
		{
			return inputIndex;
		}
		if (num4 > num3)
		{
			return num2;
		}
		return num;
	}

	private void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
			greyZoneAmbienceVolume = greyZoneAmbience.volume;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void OnEnable()
	{
		if (forceTimeOfDayToNight)
		{
			BetterDayNightManager instance = BetterDayNightManager.instance;
			if (instance != null)
			{
				instance.SetTimeIndexOverrideFunction(DayNightOverrideFunction);
			}
		}
	}

	private void OnDisable()
	{
		ForceStopGreyZone();
		if (forceTimeOfDayToNight)
		{
			BetterDayNightManager instance = BetterDayNightManager.instance;
			if (instance != null)
			{
				instance.UnsetTimeIndexOverrideFunction();
			}
		}
	}

	private void Update()
	{
		if (HasAuthority)
		{
			AuthorityUpdate();
		}
		SharedUpdate();
	}

	private void AuthorityUpdate()
	{
		float deltaTime = Time.deltaTime;
		if (greyZoneActive)
		{
			summoningProgress = 1f;
			double num = ((photonConnectedDuringActivation && PhotonNetwork.InRoom) ? PhotonNetwork.Time : ((photonConnectedDuringActivation || PhotonNetwork.InRoom) ? (-100.0) : ((double)Time.time)));
			if (num > greyZoneActivationTime + (double)greyZoneActiveDuration || num < greyZoneActivationTime - 10.0)
			{
				DeactivateGreyZoneAuthority();
			}
		}
		else
		{
			if (!GreyZoneAvailable)
			{
				return;
			}
			roomPlayerList = PhotonNetwork.PlayerList;
			int num2 = 1;
			if (roomPlayerList != null && roomPlayerList.Length != 0)
			{
				num2 = Mathf.Max((roomPlayerList.Length + 1) / 2, 1);
			}
			float num3 = 0f;
			float num4 = 1f / summoningActivationTime;
			foreach (KeyValuePair<int, (VRRig, GreyZoneSummoner)> summoningPlayer in summoningPlayers)
			{
				VRRig item = summoningPlayer.Value.Item1;
				GreyZoneSummoner item2 = summoningPlayer.Value.Item2;
				float current2 = summoningPlayerProgress[summoningPlayer.Key];
				UnityEngine.Vector3 lhs = item2.SummoningFocusPoint - item.leftHand.rigTarget.position;
				UnityEngine.Vector3 rhs = -item.leftHand.rigTarget.right;
				bool flag = UnityEngine.Vector3.Dot(lhs, rhs) > 0f;
				UnityEngine.Vector3 lhs2 = item2.SummoningFocusPoint - item.rightHand.rigTarget.position;
				UnityEngine.Vector3 right = item.rightHand.rigTarget.right;
				bool flag2 = UnityEngine.Vector3.Dot(lhs2, right) > 0f;
				current2 = ((!(flag && flag2)) ? Mathf.MoveTowards(current2, 0f, num4 * deltaTime) : Mathf.MoveTowards(current2, 1f, num4 * deltaTime));
				num3 += current2;
				summoningPlayerProgress[summoningPlayer.Key] = current2;
			}
			float num5 = 0.95f;
			summoningProgress = Mathf.Clamp01(num3 / num5 / (float)num2);
			UpdateSummonerVisuals();
			if (summoningProgress > 0.99f)
			{
				ActivateGreyZoneAuthority();
			}
		}
	}

	private void SharedUpdate()
	{
		GTPlayer instance = GTPlayer.Instance;
		if (greyZoneActive)
		{
			UnityEngine.Vector3 vector = UnityEngine.Vector3.ClampMagnitude(instance.InstantaneousVelocity * particlePredictiveSpawnVelocityFactor, particlePredictiveSpawnMaxDist);
			greyZoneParticles.transform.position = instance.HeadCenterPosition + UnityEngine.Vector3.down * 0.5f + vector;
		}
		else if (gravityOverrideSet && gravityReductionAmount < 0.01f)
		{
			instance.UnsetGravityOverride(this);
			gravityOverrideSet = false;
		}
		float num = (greyZoneActive ? 0f : 1f);
		float smoothTime = (greyZoneActive ? skyMonsterMovementEnterTime : skyMonsterMovementExitTime);
		if (moonController != null && moonController.Distance != num)
		{
			float num2 = Mathf.SmoothDamp(moonController.Distance, num, ref skyMonsterMovementVelocity, smoothTime);
			if ((double)Mathf.Abs(num2 - num) < 0.001)
			{
				num2 = num;
			}
			moonController.UpdateDistance(num2);
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.IsWriting)
		{
			stream.SendNext(greyZoneActive);
			stream.SendNext(greyZoneActivationTime);
			stream.SendNext(photonConnectedDuringActivation);
			stream.SendNext(gravityFactorOptionSelection);
			stream.SendNext(summoningProgress);
		}
		else if (stream.IsReading && info.Sender.IsMasterClient)
		{
			bool flag = greyZoneActive;
			greyZoneActive = (bool)stream.ReceiveNext();
			greyZoneActivationTime = ((double)stream.ReceiveNext()).GetFinite();
			photonConnectedDuringActivation = (bool)stream.ReceiveNext();
			gravityFactorOptionSelection = (int)stream.ReceiveNext();
			gravityFactorOptionSelection = Mathf.Clamp(gravityFactorOptionSelection, 0, gravityFactorOptions.Length - 1);
			summoningProgress = ((float)stream.ReceiveNext()).ClampSafe(0f, 1f);
			UpdateSummonerVisuals();
			if (greyZoneActive && !flag)
			{
				ActivateGreyZoneLocal();
			}
			else if (!greyZoneActive && flag)
			{
				DeactivateGreyZoneLocal();
			}
		}
	}

	public void OnPlayerEnteredRoom(Player newPlayer)
	{
	}

	public void OnPlayerLeftRoom(Player otherPlayer)
	{
		ValidateSummoningPlayers();
	}

	public void OnRoomPropertiesUpdate(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
	}

	public void OnPlayerPropertiesUpdate(Player targetPlayer, ExitGames.Client.Photon.Hashtable changedProps)
	{
	}

	public void OnMasterClientSwitched(Player newMasterClient)
	{
		ValidateSummoningPlayers();
	}
}
public class GreyZoneSummoner : MonoBehaviour
{
	[SerializeField]
	private Transform summoningFocusPoint;

	[SerializeField]
	private Transform candlesParent;

	[SerializeField]
	private PlayableDirector candlesTimeline;

	[SerializeField]
	private TriggerEventNotifier areaTriggerNotifier;

	[SerializeField]
	private SphereCollider areaTriggerCollider;

	[SerializeField]
	private GorillaPressableButton greyZoneActivationButton;

	[SerializeField]
	private List<AudioSource> summoningTones = new List<AudioSource>();

	[SerializeField]
	private float summoningTonesMaxVolume = 1f;

	[SerializeField]
	private float summoningTonesFadeOverlap = 0.5f;

	[SerializeField]
	private float summoningTonesFadeTime = 4f;

	[SerializeField]
	private List<GorillaPressableButton> greyZoneGravityFactorButtons = new List<GorillaPressableButton>();

	private GreyZoneManager greyZoneManager;

	public UnityEngine.Vector3 SummoningFocusPoint => summoningFocusPoint.position;

	public float SummonerMaxDistance => areaTriggerCollider.radius + 1f;

	private void OnEnable()
	{
		greyZoneManager = GreyZoneManager.Instance;
		if (!(greyZoneManager == null))
		{
			greyZoneManager.RegisterSummoner(this);
			areaTriggerNotifier.TriggerEnterEvent += ColliderEnteredArea;
			areaTriggerNotifier.TriggerExitEvent += ColliderExitedArea;
		}
	}

	private void OnDisable()
	{
		if (GreyZoneManager.Instance != null)
		{
			GreyZoneManager.Instance.DeregisterSummoner(this);
		}
		areaTriggerNotifier.TriggerEnterEvent -= ColliderEnteredArea;
		areaTriggerNotifier.TriggerExitEvent -= ColliderExitedArea;
	}

	public void UpdateProgressFeedback(bool greyZoneAvailable)
	{
		if (greyZoneManager == null)
		{
			return;
		}
		if (greyZoneAvailable && !candlesParent.gameObject.activeSelf)
		{
			candlesParent.gameObject.SetActive(value: true);
		}
		candlesTimeline.time = (double)Mathf.Clamp01(greyZoneManager.SummoningProgress) * candlesTimeline.duration;
		candlesTimeline.Evaluate();
		if (!greyZoneManager.GreyZoneActive)
		{
			float value = (float)summoningTones.Count * greyZoneManager.SummoningProgress;
			for (int i = 0; i < summoningTones.Count; i++)
			{
				float num = Mathf.InverseLerp(i, (float)i + 1f + summoningTonesFadeOverlap, value);
				summoningTones[i].volume = num * summoningTonesMaxVolume;
			}
		}
		greyZoneActivationButton.isOn = greyZoneManager.GreyZoneActive;
		greyZoneActivationButton.UpdateColor();
		for (int j = 0; j < greyZoneGravityFactorButtons.Count; j++)
		{
			greyZoneGravityFactorButtons[j].isOn = greyZoneManager.GravityFactorSelection == j;
			greyZoneGravityFactorButtons[j].UpdateColor();
		}
	}

	public void OnGreyZoneActivated()
	{
		StopAllCoroutines();
		StartCoroutine(FadeOutSummoningTones());
	}

	private IEnumerator FadeOutSummoningTones()
	{
		float fadeStartTime = Time.time;
		float fadeRate = 1f / summoningTonesFadeTime;
		while (Time.time < fadeStartTime + summoningTonesFadeTime)
		{
			for (int i = 0; i < summoningTones.Count; i++)
			{
				summoningTones[i].volume = Mathf.MoveTowards(summoningTones[i].volume, 0f, summoningTonesMaxVolume * fadeRate * Time.deltaTime);
			}
			yield return null;
		}
		for (int j = 0; j < summoningTones.Count; j++)
		{
			summoningTones[j].volume = 0f;
		}
	}

	public void ColliderEnteredArea(TriggerEventNotifier notifier, Collider other)
	{
		ZoneEntityBSP component = other.GetComponent<ZoneEntityBSP>();
		VRRig vRRig = ((component != null) ? component.entityRig : null);
		if (vRRig != null && greyZoneManager != null)
		{
			greyZoneManager.VRRigEnteredSummonerProximity(vRRig, this);
		}
	}

	public void ColliderExitedArea(TriggerEventNotifier notifier, Collider other)
	{
		ZoneEntityBSP component = other.GetComponent<ZoneEntityBSP>();
		VRRig vRRig = ((component != null) ? component.entityRig : null);
		if (vRRig != null && greyZoneManager != null)
		{
			greyZoneManager.VRRigExitedSummonerProximity(vRRig, this);
		}
	}
}
public class MonkeVoteController : MonoBehaviour, IGorillaSliceableSimple
{
	[Serializable]
	private class FetchPollsRequest
	{
		public string TitleId;

		public string PlayFabId;

		public string PlayFabTicket;

		public bool IncludeInactive;
	}

	[Serializable]
	public class FetchPollsResponse
	{
		public int PollId;

		public string Question;

		public List<string> VoteOptions;

		public List<int> VoteCount;

		public List<int> PredictionCount;

		public DateTime StartTime;

		public DateTime EndTime;

		public bool isActive;
	}

	[Serializable]
	private class VoteRequest
	{
		public int PollId;

		public string TitleId;

		public string PlayFabId;

		public string OculusId;

		public string UserNonce;

		public string UserPlatform;

		public int OptionIndex;

		public bool IsPrediction;

		public string PlayFabTicket;
	}

	[Serializable]
	public class VoteResponse
	{
		public int PollId { get; set; }

		public string TitleId { get; set; }

		public List<string> VoteOptions { get; set; }

		public List<int> VoteCount { get; set; }

		public List<int> PredictionCount { get; set; }
	}

	private string Nonce = "";

	private bool includeInactive = true;

	private int fetchPollsRetryCount;

	private int maxRetriesOnFail = 3;

	private int voteRetryCount;

	private FetchPollsResponse lastPollData;

	private FetchPollsResponse currentPollData;

	private VoteResponse lastVoteData;

	private bool isFetchingPoll;

	private bool hasPoll;

	private bool isCurrentPollActive;

	private bool hasCurrentPollCompleted;

	private DateTime currentPollCompletionTime;

	private bool isSendingVote;

	private int pollId = -1;

	private int option;

	private bool isPrediction;

	public static MonkeVoteController instance { get; private set; }

	public event Action OnPollsUpdated;

	public event Action OnVoteAccepted;

	public event Action OnVoteFailed;

	public event Action OnCurrentPollEnded;

	public void Awake()
	{
		if (instance == null)
		{
			instance = this;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	public void SliceUpdate()
	{
		if (isCurrentPollActive && !hasCurrentPollCompleted && currentPollCompletionTime < DateTime.UtcNow)
		{
			GTDev.Log("Active vote poll completed.");
			hasCurrentPollCompleted = true;
			this.OnCurrentPollEnded?.Invoke();
		}
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public async void RequestPolls()
	{
		if (!isFetchingPoll && (!hasPoll || (isCurrentPollActive && hasCurrentPollCompleted)))
		{
			isFetchingPoll = true;
			await WaitForSessionToken();
			FetchPolls();
		}
		else
		{
			this.OnPollsUpdated?.Invoke();
		}
	}

	private async Task WaitForSessionToken()
	{
		while (!PlayFabAuthenticator.instance || PlayFabAuthenticator.instance.GetPlayFabPlayerId().IsNullOrEmpty() || PlayFabAuthenticator.instance.GetPlayFabSessionTicket().IsNullOrEmpty() || PlayFabAuthenticator.instance.userID.IsNullOrEmpty())
		{
			await Task.Yield();
			await Task.Delay(1000);
		}
	}

	private void FetchPolls()
	{
		StartCoroutine(DoFetchPolls(new FetchPollsRequest
		{
			TitleId = PlayFabAuthenticatorSettings.TitleId,
			PlayFabId = PlayFabAuthenticator.instance.GetPlayFabPlayerId(),
			PlayFabTicket = PlayFabAuthenticator.instance.GetPlayFabSessionTicket(),
			IncludeInactive = includeInactive
		}, OnFetchPollsResponse));
	}

	private IEnumerator DoFetchPolls(FetchPollsRequest data, Action<List<FetchPollsResponse>> callback)
	{
		UnityWebRequest request = new UnityWebRequest(PlayFabAuthenticatorSettings.VotingApiBaseUrl + "/api/FetchPoll", "POST");
		byte[] bytes = Encoding.UTF8.GetBytes(JsonUtility.ToJson(data));
		bool retry = false;
		request.uploadHandler = new UploadHandlerRaw(bytes);
		request.downloadHandler = new DownloadHandlerBuffer();
		request.SetRequestHeader("Content-Type", "application/json");
		yield return request.SendWebRequest();
		if (request.result == UnityWebRequest.Result.Success)
		{
			List<FetchPollsResponse> obj = JsonConvert.DeserializeObject<List<FetchPollsResponse>>(request.downloadHandler.text);
			callback(obj);
		}
		else
		{
			long responseCode = request.responseCode;
			if (responseCode >= 500 && responseCode < 600)
			{
				retry = true;
			}
			else if (request.result == UnityWebRequest.Result.ConnectionError)
			{
				retry = true;
			}
		}
		if (retry)
		{
			if (fetchPollsRetryCount < maxRetriesOnFail)
			{
				int num = (int)Mathf.Pow(2f, fetchPollsRetryCount + 1);
				fetchPollsRetryCount++;
				yield return new WaitForSecondsRealtime(num);
				FetchPolls();
			}
			else
			{
				GTDev.LogError("Maximum FetchPolls retries attempted. Please check your network connection.");
				fetchPollsRetryCount = 0;
				callback(null);
			}
		}
	}

	private void OnFetchPollsResponse([CanBeNull] List<FetchPollsResponse> response)
	{
		isFetchingPoll = false;
		hasPoll = false;
		lastPollData = null;
		currentPollData = null;
		isCurrentPollActive = false;
		hasCurrentPollCompleted = false;
		if (response != null)
		{
			DateTime minValue = DateTime.MinValue;
			foreach (FetchPollsResponse item in response)
			{
				if (item.isActive)
				{
					hasPoll = true;
					currentPollData = item;
					if (currentPollData.EndTime > DateTime.UtcNow)
					{
						isCurrentPollActive = true;
						hasCurrentPollCompleted = false;
						currentPollCompletionTime = currentPollData.EndTime;
						currentPollCompletionTime = currentPollCompletionTime.AddMinutes(1.0);
					}
				}
				if (!item.isActive && item.EndTime > minValue && item.EndTime < DateTime.UtcNow)
				{
					lastPollData = item;
				}
			}
		}
		else
		{
			GTDev.LogError("Error: Could not fetch polls!");
		}
		this.OnPollsUpdated?.Invoke();
	}

	public void Vote(int pollId, int option, bool isPrediction)
	{
		if (hasPoll && !isSendingVote)
		{
			isSendingVote = true;
			this.pollId = pollId;
			this.option = option;
			this.isPrediction = isPrediction;
			SendVote();
		}
	}

	private void SendVote()
	{
		GetNonceForVotingCallback(null);
	}

	private void GetNonceForVotingCallback([CanBeNull] Message<UserProof> message)
	{
		if (message != null)
		{
			Nonce = message.Data?.Value;
		}
		StartCoroutine(DoVote(new VoteRequest
		{
			PollId = pollId,
			TitleId = PlayFabAuthenticatorSettings.TitleId,
			PlayFabId = PlayFabAuthenticator.instance.GetPlayFabPlayerId(),
			OculusId = PlayFabAuthenticator.instance.userID,
			UserPlatform = PlayFabAuthenticator.instance.platform.ToString(),
			UserNonce = Nonce,
			PlayFabTicket = PlayFabAuthenticator.instance.GetPlayFabSessionTicket(),
			OptionIndex = option,
			IsPrediction = isPrediction
		}, OnVoteSuccess));
	}

	private IEnumerator DoVote(VoteRequest data, Action<VoteResponse> callback)
	{
		UnityWebRequest request = new UnityWebRequest(PlayFabAuthenticatorSettings.VotingApiBaseUrl + "/api/Vote", "POST");
		byte[] bytes = Encoding.UTF8.GetBytes(JsonUtility.ToJson(data));
		bool retry = false;
		request.uploadHandler = new UploadHandlerRaw(bytes);
		request.downloadHandler = new DownloadHandlerBuffer();
		request.SetRequestHeader("Content-Type", "application/json");
		yield return request.SendWebRequest();
		if (request.result == UnityWebRequest.Result.Success)
		{
			VoteResponse obj = JsonConvert.DeserializeObject<VoteResponse>(request.downloadHandler.text);
			callback(obj);
		}
		else
		{
			long responseCode = request.responseCode;
			if (responseCode >= 500 && responseCode < 600)
			{
				retry = true;
			}
			else if (request.responseCode == 429)
			{
				GTDev.LogWarning("User already voted on this poll!");
				callback(null);
			}
			else if (request.result == UnityWebRequest.Result.ConnectionError)
			{
				retry = true;
			}
		}
		if (retry)
		{
			if (voteRetryCount < maxRetriesOnFail)
			{
				int num = (int)Mathf.Pow(2f, voteRetryCount + 1);
				voteRetryCount++;
				yield return new WaitForSecondsRealtime(num);
				SendVote();
			}
			else
			{
				GTDev.LogError("Maximum Vote retries attempted. Please check your network connection.");
				voteRetryCount = 0;
				callback(null);
			}
		}
		else
		{
			isSendingVote = false;
		}
	}

	private void OnVoteSuccess([CanBeNull] VoteResponse response)
	{
		isSendingVote = false;
		if (response != null)
		{
			lastVoteData = response;
			this.OnVoteAccepted?.Invoke();
		}
		else
		{
			this.OnVoteFailed?.Invoke();
		}
	}

	public FetchPollsResponse GetLastPollData()
	{
		return lastPollData;
	}

	public FetchPollsResponse GetCurrentPollData()
	{
		return currentPollData;
	}

	public VoteResponse GetVoteData()
	{
		return lastVoteData;
	}

	public int GetLastVotePollId()
	{
		return pollId;
	}

	public int GetLastVoteSelectedOption()
	{
		return option;
	}

	public bool GetLastVoteWasPrediction()
	{
		return isPrediction;
	}

	public DateTime GetCurrentPollCompletionTime()
	{
		return currentPollCompletionTime;
	}
}
public class MonkeVoteMachine : MonoBehaviour
{
	public enum VotingState
	{
		None,
		Voting,
		Predicting,
		Complete
	}

	public class PollEntry
	{
		public int PollId;

		public string Question;

		public string[] VoteOptions;

		public int[] VoteCount;

		public int[] PredictionCount;

		public DateTime StartTime;

		public DateTime EndTime;

		public bool IsValid
		{
			get
			{
				string[] voteOptions = VoteOptions;
				if (voteOptions != null)
				{
					return voteOptions.Length == 2;
				}
				return false;
			}
		}

		public PollEntry(int pollId, string question, string[] voteOptions)
		{
			PollId = pollId;
			Question = question;
			VoteOptions = voteOptions;
			VoteCount = new int[2];
			VoteCount[0] = UnityEngine.Random.Range(0, 50000);
			VoteCount[1] = UnityEngine.Random.Range(0, 50000);
			PredictionCount = new int[2];
			PredictionCount[0] = UnityEngine.Random.Range(0, 50000);
			PredictionCount[1] = UnityEngine.Random.Range(0, 50000);
			StartTime = DateTime.Now;
			EndTime = DateTime.Now + TimeSpan.FromSeconds(20.0);
		}

		public PollEntry(MonkeVoteController.FetchPollsResponse poll)
		{
			PollId = poll.PollId;
			Question = poll.Question;
			VoteOptions = poll.VoteOptions.ToArray();
			VoteCount = poll.VoteCount.ToArray();
			PredictionCount = poll.PredictionCount.ToArray();
			StartTime = poll.StartTime;
			EndTime = poll.EndTime;
		}

		public int GetWinner()
		{
			if (VoteCount == null || VoteCount.Length == 0)
			{
				return -1;
			}
			int num = int.MinValue;
			int result = -1;
			for (int i = 0; i < VoteCount.Length; i++)
			{
				if (VoteCount[i] > num)
				{
					num = VoteCount[i];
					result = i;
				}
			}
			return result;
		}
	}

	private const string kVoteCurrentIdKey = "Vote_Current_Id";

	private const string kVoteCurrentOptionKey = "Vote_Current_Option";

	private const string kVoteCurrentPredictionKey = "Vote_Current_Prediction";

	private const string kVoteCurrentStreak = "Vote_Current_Streak";

	private const string kVotePreviousIdKey = "Vote_Previous_Id";

	private const string kVotePreviousOptionKey = "Vote_Previous_Option";

	private const string kVotePreviousPredictionKey = "Vote_Previous_Prediction";

	private const string kVotePreviousStreak = "Vote_Previous_Streak";

	[SerializeField]
	private MonkeVoteProximityTrigger _proximityTrigger;

	[Header("VOTING")]
	[SerializeField]
	private string _pollsClosedText = "POLLS CLOSED";

	[SerializeField]
	private string _defaultTitle = "MONKE VOTE";

	[SerializeField]
	private string _voteTitle = "VOTE";

	[SerializeField]
	private string _predictTitle = "GUESS";

	[SerializeField]
	private string _completeTitle = "VOTING COMPLETE";

	[SerializeField]
	private string _defaultQuestion = "COME BACK LATER";

	[SerializeField]
	private string _predictQuestion = "WHICH WILL BE MORE POPULAR?";

	[Tooltip("Must be in the format \"STREAK: {0}\"")]
	[SerializeField]
	private string _streakBlurb = "PREDICTION STREAK: {0}";

	[Tooltip("Must be in the format \"LOST {0} PREDICTION STREAK! STREAK: {1}\"")]
	[SerializeField]
	private string _streakLostBlurb = "<color=red>{0} POLL STREAK LOST!</color>  STREAK: {1}";

	[SerializeField]
	private float _voteCooldown = 1f;

	[SerializeField]
	private MonkeVoteOption[] _votingOptions;

	[SerializeField]
	private CountdownText _timerText;

	[SerializeField]
	private TMP_Text _titleText;

	[SerializeField]
	private TMP_Text _questionText;

	[Header("RESULTS")]
	[SerializeField]
	private string _defaultResultsTitle = "PREVIOUS QUESTION";

	[SerializeField]
	private TMP_Text _resultsTitleText;

	[SerializeField]
	private TMP_Text _resultsQuestionText;

	[SerializeField]
	private TMP_Text _resultsStreakText;

	[SerializeField]
	private MonkeVoteResult[] _results;

	[FormerlySerializedAs("_sound")]
	[Header("FX")]
	[SerializeField]
	private AudioSource _audio;

	[FormerlySerializedAs("_voteProcessingAudio")]
	[SerializeField]
	private AudioSource _voteTubeAudio;

	[SerializeField]
	private AudioClip[] _voteFailSound;

	[SerializeField]
	private AudioClip[] _voteSuccessDing;

	[FormerlySerializedAs("_voteSuccessSound")]
	[SerializeField]
	private AudioClip[] _voteProcessingSound;

	private VotingState _state;

	private float _voteCooldownEnd;

	private bool _waitingOnVote;

	private PollEntry _currentPoll;

	private PollEntry _previousPoll;

	private DateTime _nextPollUpdate;

	private bool _isTestingPoll;

	private void Reset()
	{
		Configure();
	}

	private void Awake()
	{
		_proximityTrigger.OnEnter += OnPlayerEnteredVoteProximity;
	}

	private void Start()
	{
		MonkeVoteController.instance.OnPollsUpdated += HandleOnPollsUpdated;
		MonkeVoteController.instance.OnVoteAccepted += HandleOnVoteAccepted;
		MonkeVoteController.instance.OnVoteFailed += HandleOnVoteFailed;
		MonkeVoteController.instance.OnCurrentPollEnded += HandleCurrentPollEnded;
		Init();
	}

	private void OnDestroy()
	{
		_proximityTrigger.OnEnter -= OnPlayerEnteredVoteProximity;
		MonkeVoteController.instance.OnPollsUpdated -= HandleOnPollsUpdated;
		MonkeVoteController.instance.OnVoteAccepted -= HandleOnVoteAccepted;
		MonkeVoteController.instance.OnVoteFailed -= HandleOnVoteFailed;
		MonkeVoteController.instance.OnCurrentPollEnded -= HandleCurrentPollEnded;
	}

	public void Init()
	{
		_isTestingPoll = false;
		_previousPoll = (_currentPoll = null);
		_waitingOnVote = false;
		MonkeVoteOption[] votingOptions = _votingOptions;
		foreach (MonkeVoteOption obj in votingOptions)
		{
			obj.ResetState();
			obj.OnVote += OnVoteEntered;
		}
		UpdatePollDisplays();
	}

	private void OnPlayerEnteredVoteProximity()
	{
		MonkeVoteController.instance.RequestPolls();
	}

	private void HandleOnPollsUpdated()
	{
		UpdatePollDisplays();
	}

	private void UpdatePollDisplays()
	{
		if (MonkeVoteController.instance == null)
		{
			SetState(VotingState.None);
			ShowResults(null);
			return;
		}
		MonkeVoteController.FetchPollsResponse lastPollData = MonkeVoteController.instance.GetLastPollData();
		if (lastPollData != null)
		{
			_previousPoll = new PollEntry(lastPollData);
			ShowResults(_previousPoll);
		}
		else
		{
			ShowResults(null);
		}
		MonkeVoteController.FetchPollsResponse currentPollData = MonkeVoteController.instance.GetCurrentPollData();
		if (currentPollData != null)
		{
			_nextPollUpdate = MonkeVoteController.instance.GetCurrentPollCompletionTime();
			_currentPoll = new PollEntry(currentPollData);
			PollEntry currentPoll = _currentPoll;
			if (currentPoll != null && currentPoll.IsValid)
			{
				(int voteOption, int predictionOption) vote = GetVote(_currentPoll.PollId);
				int item = vote.voteOption;
				int item2 = vote.predictionOption;
				VotingState newState = ((item < 0) ? VotingState.Voting : ((item2 < 0) ? VotingState.Predicting : VotingState.Complete));
				SetState(newState);
			}
			else
			{
				SetState(VotingState.None);
			}
		}
		else
		{
			SetState(VotingState.None);
		}
	}

	private void HandleOnVoteAccepted()
	{
		int lastVotePollId = MonkeVoteController.instance.GetLastVotePollId();
		int lastVoteSelectedOption = MonkeVoteController.instance.GetLastVoteSelectedOption();
		bool lastVoteWasPrediction = MonkeVoteController.instance.GetLastVoteWasPrediction();
		OnVoteResponseReceived(lastVotePollId, lastVoteSelectedOption, lastVoteWasPrediction, success: true);
	}

	private void HandleOnVoteFailed()
	{
		_waitingOnVote = false;
		int lastVotePollId = MonkeVoteController.instance.GetLastVotePollId();
		int lastVoteSelectedOption = MonkeVoteController.instance.GetLastVoteSelectedOption();
		bool lastVoteWasPrediction = MonkeVoteController.instance.GetLastVoteWasPrediction();
		OnVoteResponseReceived(lastVotePollId, lastVoteSelectedOption, lastVoteWasPrediction, success: false);
	}

	private void HandleCurrentPollEnded()
	{
		if (_proximityTrigger.isPlayerNearby)
		{
			MonkeVoteController.instance.RequestPolls();
		}
	}

	[Tooltip("Hide dynamic child meshes to avoid them getting combined into the parent mesh on awake")]
	private void HideDynamicMeshes()
	{
		SetDynamicMeshesVisible(enabled: false);
	}

	[Tooltip("Show dynamic child meshes to allow easy visualization")]
	private void ShowDynamicMeshes()
	{
		SetDynamicMeshesVisible(enabled: true);
	}

	private void SetDynamicMeshesVisible(bool enabled)
	{
		MonkeVoteOption[] votingOptions = _votingOptions;
		for (int i = 0; i < votingOptions.Length; i++)
		{
			votingOptions[i].SetDynamicMeshesVisible(enabled);
		}
		MonkeVoteResult[] results = _results;
		for (int i = 0; i < results.Length; i++)
		{
			results[i].SetDynamicMeshesVisible(enabled);
		}
	}

