	{
		_audio = GetComponentInChildren<AudioSource>();
		_audio.spatialBlend = 1f;
		_votingOptions = GetComponentsInChildren<MonkeVoteOption>();
		_results = GetComponentsInChildren<MonkeVoteResult>();
