public class RockPiles : MonoBehaviour
{
	[Serializable]
	public struct RockPile
	{
		public GameObject visual;

		public int threshold;
	}

	[SerializeField]
	private RockPile[] _rocks;

	public void Show(int visiblePercentage)
	{
		if (visiblePercentage <= 0)
		{
			ShowRock(-1);
			return;
		}
		int rockToShow = -1;
		int num = -1;
		for (int i = 0; i < _rocks.Length; i++)
		{
			RockPile rockPile = _rocks[i];
			if (visiblePercentage >= rockPile.threshold && num < rockPile.threshold)
			{
				rockToShow = i;
				num = rockPile.threshold;
			}
		}
		ShowRock(rockToShow);
	}

	private void ShowRock(int rockToShow)
	{
		for (int i = 0; i < _rocks.Length; i++)
		{
			_rocks[i].visual.SetActive(i == rockToShow);
		}
	}
}
public class VotingCard : MonoBehaviour
{
	[SerializeField]
	private GameObject _card;

	[SerializeField]
	private Transform _offPosition;

	[SerializeField]
	private Transform _onPosition;

	[SerializeField]
	private float activationTime = 0.5f;

	private bool _isVisible;

	private void MoveToOffPosition()
	{
		_card.transform.position = _offPosition.position;
	}

	private void MoveToOnPosition()
	{
		_card.transform.position = _onPosition.position;
	}

	public void SetVisible(bool showVote, bool instant)
	{
		if (_isVisible != showVote)
		{
			StopAllCoroutines();
		}
		if (instant)
		{
			_card.transform.position = (showVote ? _onPosition.position : _offPosition.position);
			_card.SetActive(showVote);
		}
		else if (showVote)
		{
			if (_isVisible != showVote)
			{
				StartCoroutine(DoActivate());
			}
		}
		else
		{
			_card.SetActive(value: false);
			_card.transform.position = _offPosition.position;
		}
		_isVisible = showVote;
	}

	private IEnumerator DoActivate()
	{
		UnityEngine.Vector3 from = _offPosition.position;
		UnityEngine.Vector3 to = _onPosition.position;
		_card.transform.position = from;
		_card.SetActive(value: true);
		float lerpVal = 0f;
		while (lerpVal < 1f)
		{
			lerpVal += Time.deltaTime / activationTime;
			_card.transform.position = UnityEngine.Vector3.Lerp(from, to, lerpVal);
			yield return null;
		}
	}
}
