public class ProgressDisplay : MonoBehaviour
{
	[SerializeField]
	private GameObject root;

	[SerializeField]
	private TMP_Text text;

	[SerializeField]
	private Image progressImage;

	[SerializeField]
	private int largestNumberToShow = 99;

	private void Reset()
	{
		root = base.gameObject;
	}

	public void SetVisible(bool visible)
	{
		root.SetActive(visible);
	}

	public void SetProgress(int progress, int total)
	{
		if ((bool)text)
		{
			if (total < largestNumberToShow)
			{
				text.text = ((progress >= total) ? $"{total}" : $"{progress}/{total}");
				SetTextVisible(visible: true);
			}
			else
			{
				SetTextVisible(visible: false);
			}
		}
		progressImage.fillAmount = (float)progress / (float)total;
	}

	public void SetProgress(float progress)
	{
		progressImage.fillAmount = progress;
	}

	private void SetTextVisible(bool visible)
	{
		if (text.gameObject.activeSelf != visible)
		{
			text.gameObject.SetActive(visible);
		}
	}
}
public class ProgressionController : MonoBehaviour
{
	[Serializable]
	private class GetQuestsStatusRequest
	{
		public string PlayFabId;

		public string PlayFabTicket;

		public string MothershipId;

		public string MothershipToken;
	}

	[Serializable]
	public class GetQuestStatusResponse
	{
		public UserQuestsStatus result;
	}

	public class UserQuestsStatus
	{
		public Dictionary<string, int> dailyPoints;

		public Dictionary<int, int> weeklyPoints;

		public int userPointsTotal;

		public int GetWeeklyPoints()
		{
			int num = 0;
			if (dailyPoints != null)
			{
				foreach (KeyValuePair<string, int> dailyPoint in dailyPoints)
				{
					num += dailyPoint.Value;
				}
			}
			if (weeklyPoints != null)
			{
				foreach (KeyValuePair<int, int> weeklyPoint in weeklyPoints)
				{
					num += weeklyPoint.Value;
				}
			}
			return Mathf.Min(num, WeeklyCap);
		}
	}

	[Serializable]
	private class SetQuestCompleteRequest
	{
		public string PlayFabId;

		public string PlayFabTicket;

		public string MothershipId;

		public string MothershipToken;

		public int QuestId;

		public string ClientVersion;
	}

	[Serializable]
	public class SetQuestCompleteResponse
	{
		public UserQuestsStatus result;
	}

	private static ProgressionController _gInstance;

	[SerializeField]
	private RotatingQuestsManager _questManager;

	private int weeklyPoints;

	private int totalPointsRaw;

	private int unclaimedPoints;

	private bool _progressReportPending;

	private (int weeklyPoints, int unclaimedPoints, int totalPointsRaw) _lastProgressReport;

	private bool _isFetchingStatus;

	private bool _statusReceived;

	private bool _isSendingQuestComplete;

	private int _fetchStatusRetryCount;

	private int _sendQuestCompleteRetryCount;

	private int _maxRetriesOnFail = 3;

	private List<int> _queuedDailyCompletedQuests = new List<int>();

	private List<int> _queuedWeeklyCompletedQuests = new List<int>();

	private int _currentlyProcessingQuest = -1;

	private const string kUnclaimedPointKey = "Claimed_Points_Key";

	private const string kQueuedDailyQuestSetIDKey = "Queued_Quest_Daily_SetID_Key";

	private const string kQueuedDailyQuestSaveCountKey = "Queued_Quest_Daily_SaveCount_Key";

	private const string kQueuedDailyQuestIDKey = "Queued_Quest_Daily_ID_Key";

	private const string kQueuedWeeklyQuestSetIDKey = "Queued_Quest_Weekly_SetID_Key";

	private const string kQueuedWeeklyQuestSaveCountKey = "Queued_Quest_Weekly_SaveCount_Key";

	private const string kQueuedWeeklyQuestIDKey = "Queued_Quest_Weekly_ID_Key";

	public static int WeeklyCap { get; private set; } = 25;

	public static int TotalPoints => _gInstance.totalPointsRaw - _gInstance.unclaimedPoints;

	public static event Action OnQuestSelectionChanged;

	public static event Action OnProgressEvent;

	public static void ReportQuestChanged(bool initialLoad)
	{
		_gInstance.OnQuestProgressChanged(initialLoad);
	}

	public static void ReportQuestSelectionChanged()
	{
		_gInstance.LoadCompletedQuestQueue();
		ProgressionController.OnQuestSelectionChanged?.Invoke();
	}

	public static void ReportQuestComplete(int questId, bool isDaily)
	{
		_gInstance.OnQuestComplete(questId, isDaily);
	}

	public static void RedeemProgress()
	{
		_gInstance.RequestProgressRedemption(_gInstance.OnProgressRedeemed);
	}

	public static (int weekly, int unclaimed, int total) GetProgressionData()
	{
		return _gInstance.GetProgress();
	}

	public static void RequestProgressUpdate()
	{
		_gInstance?.ReportProgress();
	}

	private void Awake()
	{
		if ((bool)_gInstance)
		{
			UnityEngine.Debug.LogError("Duplicate ProgressionController detected. Destroying self.", base.gameObject);
			UnityEngine.Object.Destroy(this);
			return;
		}
		_gInstance = this;
		unclaimedPoints = PlayerPrefs.GetInt("Claimed_Points_Key", 0);
		RequestStatus();
		LoadCompletedQuestQueue();
	}

	private async void RequestStatus()
	{
		if (ShouldFetchStatus())
		{
			_isFetchingStatus = true;
			await WaitForSessionToken();
			FetchStatus();
		}
		else
		{
			UnityEngine.Debug.LogError("RequestStatus triggered multiple times.  That's probably not good.");
		}
		bool ShouldFetchStatus()
		{
			if (!_isFetchingStatus)
			{
				return !_statusReceived;
			}
			return false;
		}
	}

	private async Task WaitForSessionToken()
	{
		while (!PlayFabAuthenticator.instance || PlayFabAuthenticator.instance.GetPlayFabPlayerId().IsNullOrEmpty() || PlayFabAuthenticator.instance.GetPlayFabSessionTicket().IsNullOrEmpty())
		{
			await Task.Yield();
			await Task.Delay(1000);
		}
	}

	private void FetchStatus()
	{
		StartCoroutine(DoFetchStatus(new GetQuestsStatusRequest
		{
			PlayFabId = PlayFabAuthenticator.instance.GetPlayFabPlayerId(),
			PlayFabTicket = PlayFabAuthenticator.instance.GetPlayFabSessionTicket(),
			MothershipId = "",
			MothershipToken = ""
		}, OnFetchStatusResponse));
	}

	private IEnumerator DoFetchStatus(GetQuestsStatusRequest data, Action<GetQuestStatusResponse> callback)
	{
		UnityWebRequest request = new UnityWebRequest(PlayFabAuthenticatorSettings.DailyQuestsApiBaseUrl + "/api/GetQuestStatus", "POST");
		byte[] bytes = Encoding.UTF8.GetBytes(JsonUtility.ToJson(data));
		bool retry = false;
		request.uploadHandler = new UploadHandlerRaw(bytes);
		request.downloadHandler = new DownloadHandlerBuffer();
		request.SetRequestHeader("Content-Type", "application/json");
		yield return request.SendWebRequest();
		if (request.result == UnityWebRequest.Result.Success)
		{
			GetQuestStatusResponse obj = JsonConvert.DeserializeObject<GetQuestStatusResponse>(request.downloadHandler.text);
			callback(obj);
		}
		else
		{
			long responseCode = request.responseCode;
			if (responseCode >= 500 && responseCode < 600)
			{
				retry = true;
			}
			else if (request.result == UnityWebRequest.Result.ConnectionError)
			{
				retry = true;
			}
		}
		if (retry)
		{
			if (_fetchStatusRetryCount < _maxRetriesOnFail)
			{
				int num = (int)Mathf.Pow(2f, _fetchStatusRetryCount + 1);
				_fetchStatusRetryCount++;
				yield return new WaitForSecondsRealtime(num);
				FetchStatus();
			}
			else
			{
				GTDev.LogError("Maximum FetchStatus retries attempted. Please check your network connection.");
				_fetchStatusRetryCount = 0;
				callback(null);
			}
		}
	}

	private void OnFetchStatusResponse([CanBeNull] GetQuestStatusResponse response)
	{
		_isFetchingStatus = false;
		_statusReceived = false;
		if (response != null)
		{
			SetProgressionValues(response.result.GetWeeklyPoints(), unclaimedPoints, response.result.userPointsTotal);
			ReportProgress();
		}
		else
		{
			GTDev.LogError("Error: Could not fetch status!");
		}
	}

	private void SendQuestCompleted(int questId)
	{
		if (!_isSendingQuestComplete)
		{
			_isSendingQuestComplete = true;
			StartSendQuestComplete(questId);
		}
	}

	private void StartSendQuestComplete(int questId)
	{
		StartCoroutine(DoSendQuestComplete(new SetQuestCompleteRequest
		{
			PlayFabId = PlayFabAuthenticator.instance.GetPlayFabPlayerId(),
			PlayFabTicket = PlayFabAuthenticator.instance.GetPlayFabSessionTicket(),
			MothershipId = "",
			MothershipToken = "",
			QuestId = questId,
			ClientVersion = MothershipClientApiUnity.DeploymentId
		}, OnSendQuestCompleteSuccess));
	}

	private IEnumerator DoSendQuestComplete(SetQuestCompleteRequest data, Action<SetQuestCompleteResponse> callback)
	{
		UnityWebRequest request = new UnityWebRequest(PlayFabAuthenticatorSettings.DailyQuestsApiBaseUrl + "/api/SetQuestComplete", "POST");
		byte[] bytes = Encoding.UTF8.GetBytes(JsonUtility.ToJson(data));
		bool retry = false;
		request.uploadHandler = new UploadHandlerRaw(bytes);
		request.downloadHandler = new DownloadHandlerBuffer();
		request.SetRequestHeader("Content-Type", "application/json");
		yield return request.SendWebRequest();
		if (request.result == UnityWebRequest.Result.Success)
		{
			SetQuestCompleteResponse obj = JsonConvert.DeserializeObject<SetQuestCompleteResponse>(request.downloadHandler.text);
			callback(obj);
			ProcessQuestSubmittedSuccess();
		}
		else
		{
			long responseCode = request.responseCode;
			if (responseCode >= 500 && responseCode < 600)
			{
				retry = true;
			}
			else if (request.responseCode == 403)
			{
				GTDev.LogWarning("User already reached the max number of completion points for this time period!");
				callback(null);
				ClearQuestQueue();
			}
			else if (request.result == UnityWebRequest.Result.ConnectionError)
			{
				retry = true;
			}
		}
		if (retry)
		{
			if (_sendQuestCompleteRetryCount < _maxRetriesOnFail)
			{
				int num = (int)Mathf.Pow(2f, _sendQuestCompleteRetryCount + 1);
				_sendQuestCompleteRetryCount++;
				yield return new WaitForSecondsRealtime(num);
				StartSendQuestComplete(data.QuestId);
			}
			else
			{
				GTDev.LogError("Maximum SendQuestComplete retries attempted. Please check your network connection.");
				_sendQuestCompleteRetryCount = 0;
				callback(null);
				ProcessQuestSubmittedFail();
			}
		}
		else
		{
			_isSendingQuestComplete = false;
		}
	}

	private void OnSendQuestCompleteSuccess([CanBeNull] SetQuestCompleteResponse response)
	{
		_isSendingQuestComplete = false;
		if (response != null)
		{
			UpdateProgressionValues(response.result.GetWeeklyPoints(), response.result.userPointsTotal);
			ReportProgress();
		}
	}

	private void OnQuestProgressChanged(bool initialLoad)
	{
		ReportProgress();
	}

	private void OnQuestComplete(int questId, bool isDaily)
	{
		QueueQuestCompletion(questId, isDaily);
	}

	private void QueueQuestCompletion(int questId, bool isDaily)
	{
		if (isDaily)
		{
			_queuedDailyCompletedQuests.Add(questId);
		}
		else
		{
			_queuedWeeklyCompletedQuests.Add(questId);
		}
		SaveCompletedQuestQueue();
		SubmitNextQuestInQueue();
	}

	private void SubmitNextQuestInQueue()
	{
		if (_currentlyProcessingQuest == -1 && AreCompletedQuestsQueued())
		{
			int num = -1;
			if (_queuedWeeklyCompletedQuests.Count > 0)
			{
				num = _queuedWeeklyCompletedQuests[0];
			}
			else if (_queuedDailyCompletedQuests.Count > 0)
			{
				num = _queuedDailyCompletedQuests[0];
			}
			_currentlyProcessingQuest = num;
			SendQuestCompleted(num);
		}
	}

	private void ClearQuestQueue()
	{
		_currentlyProcessingQuest = -1;
		_queuedDailyCompletedQuests.Clear();
		_queuedWeeklyCompletedQuests.Clear();
		SaveCompletedQuestQueue();
	}

	private void ProcessQuestSubmittedSuccess()
	{
		if (_currentlyProcessingQuest == -1)
		{
			return;
		}
		if (AreCompletedQuestsQueued())
		{
			if (_queuedWeeklyCompletedQuests.Remove(_currentlyProcessingQuest))
			{
				SaveCompletedQuestQueue();
			}
			else if (_queuedDailyCompletedQuests.Remove(_currentlyProcessingQuest))
			{
				SaveCompletedQuestQueue();
			}
		}
		_currentlyProcessingQuest = -1;
		SubmitNextQuestInQueue();
	}

	private void ProcessQuestSubmittedFail()
	{
		_currentlyProcessingQuest = -1;
	}

	private bool AreCompletedQuestsQueued()
	{
		if (_queuedDailyCompletedQuests.Count <= 0)
		{
			return _queuedWeeklyCompletedQuests.Count > 0;
		}
		return true;
	}

	private void SaveCompletedQuestQueue()
	{
		int num = 0;
		for (int i = 0; i < _queuedDailyCompletedQuests.Count; i++)
		{
			PlayerPrefs.SetInt(string.Format("{0}{1}", "Queued_Quest_Daily_ID_Key", num), _queuedDailyCompletedQuests[i]);
			num++;
		}
		int dailyQuestSetID = _questManager.dailyQuestSetID;
		PlayerPrefs.SetInt("Queued_Quest_Daily_SetID_Key", dailyQuestSetID);
		PlayerPrefs.SetInt("Queued_Quest_Daily_SaveCount_Key", num);
		int num2 = 0;
		for (int j = 0; j < _queuedWeeklyCompletedQuests.Count; j++)
		{
			PlayerPrefs.SetInt(string.Format("{0}{1}", "Queued_Quest_Weekly_ID_Key", num2), _queuedWeeklyCompletedQuests[j]);
			num2++;
		}
		int weeklyQuestSetID = _questManager.weeklyQuestSetID;
		PlayerPrefs.SetInt("Queued_Quest_Weekly_SetID_Key", weeklyQuestSetID);
		PlayerPrefs.SetInt("Queued_Quest_Weekly_SaveCount_Key", num2);
	}

	private void LoadCompletedQuestQueue()
	{
		_queuedDailyCompletedQuests.Clear();
		int num = PlayerPrefs.GetInt("Queued_Quest_Daily_SetID_Key", -1);
		int num2 = PlayerPrefs.GetInt("Queued_Quest_Daily_SaveCount_Key", -1);
		int dailyQuestSetID = _questManager.dailyQuestSetID;
		if (num == dailyQuestSetID)
		{
			for (int i = 0; i < num2; i++)
			{
				int num3 = PlayerPrefs.GetInt(string.Format("{0}{1}", "Queued_Quest_Daily_ID_Key", i), -1);
				if (num3 != -1)
				{
					_queuedDailyCompletedQuests.Add(num3);
				}
			}
		}
		_queuedWeeklyCompletedQuests.Clear();
		int num4 = PlayerPrefs.GetInt("Queued_Quest_Weekly_SetID_Key", -1);
		int num5 = PlayerPrefs.GetInt("Queued_Quest_Weekly_SaveCount_Key", -1);
		int weeklyQuestSetID = _questManager.weeklyQuestSetID;
		if (num4 == weeklyQuestSetID)
		{
			for (int j = 0; j < num5; j++)
			{
				int num6 = PlayerPrefs.GetInt(string.Format("{0}{1}", "Queued_Quest_Weekly_ID_Key", j), -1);
				if (num6 != -1)
				{
					_queuedWeeklyCompletedQuests.Add(num6);
				}
			}
		}
		SubmitNextQuestInQueue();
	}

	private async void RequestProgressRedemption(Action onComplete)
	{
		await Task.Yield();
		onComplete?.Invoke();
	}

	private void OnProgressRedeemed()
	{
		unclaimedPoints = 0;
		PlayerPrefs.SetInt("Claimed_Points_Key", unclaimedPoints);
		ReportProgress();
	}

	private void AddPoints(int points)
	{
		if (weeklyPoints < WeeklyCap)
		{
			int num = Mathf.Clamp(points, 0, WeeklyCap - weeklyPoints);
			SetProgressionValues(weeklyPoints + num, unclaimedPoints + num, totalPointsRaw + num);
		}
	}

	private void UpdateProgressionValues(int weekly, int totalRaw)
	{
		int num = totalRaw - totalPointsRaw;
		unclaimedPoints += num;
		SetProgressionValues(weekly, unclaimedPoints, totalRaw);
	}

	private void SetProgressionValues(int weekly, int unclaimed, int totalRaw)
	{
		weeklyPoints = weekly;
		unclaimedPoints = unclaimed;
		totalPointsRaw = totalRaw;
		ReportScoreChange();
		PlayerPrefs.SetInt("Claimed_Points_Key", unclaimed);
	}

	private async void ReportProgress()
	{
		try
		{
			if (!_progressReportPending)
			{
				_progressReportPending = true;
				await Task.Yield();
				_progressReportPending = false;
				ProgressionController.OnProgressEvent?.Invoke();
				ReportScoreChange();
			}
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
	}

	private void ReportScoreChange()
	{
		(int, int, int) tuple = (weeklyPoints, unclaimedPoints, totalPointsRaw);
		(int, int, int) lastProgressReport = _lastProgressReport;
		(int, int, int) tuple2 = tuple;
		if (lastProgressReport.Item1 != tuple2.Item1 || lastProgressReport.Item2 != tuple2.Item2 || lastProgressReport.Item3 != tuple2.Item3)
		{
			if ((bool)VRRig.LocalRig)
			{
				VRRig.LocalRig.SetQuestScore(TotalPoints);
			}
			_lastProgressReport = tuple;
		}
	}

	private (int weekly, int unclaimed, int total) GetProgress()
	{
		return (weekly: weeklyPoints, unclaimed: unclaimedPoints, total: totalPointsRaw - unclaimedPoints);
	}
}
public class QuestDisplay : MonoBehaviour
{
	[SerializeField]
	private ProgressDisplay progressDisplay;

	[SerializeField]
	private TMP_Text text;

	[SerializeField]
	private TMP_Text statusText;

	[SerializeField]
	private GameObject dailyIncompleteIndicator;

	[SerializeField]
	private GameObject dailyCompleteIndicator;

	[SerializeField]
	private GameObject weeklyIncompleteIndicator;

	[SerializeField]
	private GameObject weeklyCompleteIndicator;

	[NonSerialized]
	public RotatingQuest quest;

	private int _lastUpdate = -1;

	public bool IsChanged => quest.lastChange > _lastUpdate;

	public void UpdateDisplay()
	{
		text.text = quest.GetTextDescription();
		if (quest.isQuestComplete)
		{
			progressDisplay.SetVisible(visible: false);
		}
		else if (quest.requiredOccurenceCount > 1)
		{
			progressDisplay.SetProgress(quest.occurenceCount, quest.requiredOccurenceCount);
			progressDisplay.SetVisible(visible: true);
		}
		else
		{
			progressDisplay.SetVisible(visible: false);
		}
		UpdateCompletionIndicator();
		_lastUpdate = Time.frameCount;
	}

	private void UpdateCompletionIndicator()
	{
		bool isQuestComplete = quest.isQuestComplete;
		bool flag = !isQuestComplete && quest.requiredOccurenceCount == 1;
		dailyIncompleteIndicator.SetActive(quest.isDailyQuest && flag);
		dailyCompleteIndicator.SetActive(quest.isDailyQuest && isQuestComplete);
		weeklyIncompleteIndicator.SetActive(!quest.isDailyQuest && flag);
		weeklyCompleteIndicator.SetActive(!quest.isDailyQuest && isQuestComplete);
	}
}
public class RotatingQuestBadge : MonoBehaviour, ISpawnable
{
	[Serializable]
	public struct BadgeLevel
	{
		public GameObject badge;

		public int requiredPoints;
	}

	[SerializeField]
	private TextMeshPro displayField;

	[SerializeField]
	private bool forWardrobe;

	[SerializeField]
	private VRRig myRig;

	[SerializeField]
	private BadgeLevel[] badgeLevels;

	public bool IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	public void OnSpawn(VRRig rig)
	{
		if (forWardrobe && !myRig)
		{
			TryGetRig();
			return;
		}
		myRig = rig;
		myRig.OnQuestScoreChanged += OnProgressScoreChanged;
		OnProgressScoreChanged(myRig.GetCurrentQuestScore());
	}

	public void OnDespawn()
	{
	}

	private void OnEnable()
	{
		if (forWardrobe)
		{
			SetBadgeLevel(-1);
			if (!TryGetRig())
			{
				StartCoroutine(DoFindRig());
			}
		}
	}

	private void OnDisable()
	{
		if (forWardrobe && (bool)myRig)
		{
			myRig.OnQuestScoreChanged -= OnProgressScoreChanged;
			myRig = null;
		}
	}

	private IEnumerator DoFindRig()
	{
		WaitForSeconds intervalWait = new WaitForSeconds(0.1f);
		while (!TryGetRig())
		{
			yield return intervalWait;
		}
	}

	private bool TryGetRig()
	{
		myRig = GorillaTagger.Instance?.offlineVRRig;
		if ((bool)myRig)
		{
			myRig.OnQuestScoreChanged += OnProgressScoreChanged;
			OnProgressScoreChanged(myRig.GetCurrentQuestScore());
			return true;
		}
		return false;
	}

	private void OnProgressScoreChanged(int score)
	{
		score = Mathf.Clamp(score, 0, 99999);
		displayField.text = score.ToString();
		UpdateBadge(score);
	}

	private void UpdateBadge(int score)
	{
		int num = -1;
		int badgeLevel = -1;
		for (int i = 0; i < badgeLevels.Length; i++)
		{
			if (badgeLevels[i].requiredPoints <= score && badgeLevels[i].requiredPoints > num)
			{
				num = badgeLevels[i].requiredPoints;
				badgeLevel = i;
			}
		}
		SetBadgeLevel(badgeLevel);
	}

	private void SetBadgeLevel(int level)
	{
		level = Mathf.Clamp(level, 0, badgeLevels.Length - 1);
		for (int i = 0; i < badgeLevels.Length; i++)
		{
			badgeLevels[i].badge.SetActive(i == level);
		}
	}
}
public interface GorillaQuestManager
{
	void LoadQuestsFromJson(string jsonString);

	void LoadQuestProgress();

	void SaveQuestProgress();

	void SetupAllQuestEventListeners();

	void ClearAllQuestEventListeners();

	void HandleQuestProgressChanged(bool initialLoad);

	void HandleQuestCompleted(int questID);
}
[Serializable]
[JsonConverter(typeof(StringEnumConverter))]
public enum QuestType
{
	none,
	gameModeObjective,
	gameModeRound,
	grabObject,
	dropObject,
	eatObject,
	tapObject,
	launchedProjectile,
	moveDistance,
	swimDistance,
	triggerHandEffect,
	enterLocation,
	misc,
	critter,
	fetchObject,
	playerInteraction
}
[Serializable]
[JsonConverter(typeof(StringEnumConverter))]
public enum QuestCategory
{
	NONE,
	Social,
	Exploration,
	Gameplay,
	GameRound,
	Tag
}
[Serializable]
public class RotatingQuest
{
	public bool disable;

	public int questID;

	public float weight = 1f;

	public QuestCategory category;

	public string questName = "UNNAMED QUEST";

	public QuestType questType;

	public string questOccurenceFilter;

	public int requiredOccurenceCount = 1;

	[JsonPropertyAttribute(ItemConverterType = typeof(StringEnumConverter))]
	public List<GTZone> requiredZones;

	[NonSerialized]
	[Space]
	public bool isQuestActive;

	[NonSerialized]
	public bool isQuestComplete;

	[NonSerialized]
	public bool isDailyQuest;

	[NonSerialized]
	public int lastChange;

	[NonSerialized]
	public int occurenceCount;

	private float moveDistance;

	[NonSerialized]
	public GorillaQuestManager questManager;

	[JsonIgnore]
	public bool IsMovementQuest
	{
		get
		{
			if (questType != QuestType.moveDistance)
			{
				return questType == QuestType.swimDistance;
			}
			return true;
		}
	}

	[JsonIgnore]
	public GTZone RequiredZone { get; private set; } = GTZone.none;

	public void SetRequiredZone()
	{
		RequiredZone = ((requiredZones.Count > 0) ? requiredZones[UnityEngine.Random.Range(0, requiredZones.Count)] : GTZone.none);
	}

	public void AddEventListener()
	{
		if (!isQuestComplete)
		{
			switch (questType)
			{
			case QuestType.gameModeObjective:
				PlayerGameEvents.OnGameModeObjectiveTrigger += OnGameEventOccurence;
				break;
			case QuestType.gameModeRound:
				PlayerGameEvents.OnGameModeCompleteRound += OnGameEventOccurence;
				break;
			case QuestType.grabObject:
				PlayerGameEvents.OnGrabbedObject += OnGameEventOccurence;
				break;
			case QuestType.dropObject:
				PlayerGameEvents.OnDroppedObject += OnGameEventOccurence;
				break;
			case QuestType.eatObject:
				PlayerGameEvents.OnEatObject += OnGameEventOccurence;
				break;
			case QuestType.tapObject:
				PlayerGameEvents.OnTapObject += OnGameEventOccurence;
				break;
			case QuestType.launchedProjectile:
				PlayerGameEvents.OnLaunchedProjectile += OnGameEventOccurence;
				break;
			case QuestType.moveDistance:
				PlayerGameEvents.OnPlayerMoved += OnGameMoveEvent;
				break;
			case QuestType.swimDistance:
				PlayerGameEvents.OnPlayerSwam += OnGameMoveEvent;
				break;
			case QuestType.triggerHandEffect:
				PlayerGameEvents.OnTriggerHandEffect += OnGameEventOccurence;
				break;
			case QuestType.enterLocation:
				PlayerGameEvents.OnEnterLocation += OnGameEventOccurence;
				break;
			case QuestType.misc:
				PlayerGameEvents.OnMiscEvent += OnGameEventOccurence;
				break;
			case QuestType.critter:
				PlayerGameEvents.OnCritterEvent += OnGameEventOccurence;
				break;
			}
		}
	}

	public void RemoveEventListener()
	{
		switch (questType)
		{
		case QuestType.gameModeObjective:
			PlayerGameEvents.OnGameModeObjectiveTrigger -= OnGameEventOccurence;
			break;
		case QuestType.gameModeRound:
			PlayerGameEvents.OnGameModeCompleteRound -= OnGameEventOccurence;
			break;
		case QuestType.grabObject:
			PlayerGameEvents.OnGrabbedObject -= OnGameEventOccurence;
			break;
		case QuestType.dropObject:
			PlayerGameEvents.OnDroppedObject -= OnGameEventOccurence;
			break;
		case QuestType.eatObject:
			PlayerGameEvents.OnEatObject -= OnGameEventOccurence;
			break;
		case QuestType.tapObject:
			PlayerGameEvents.OnTapObject -= OnGameEventOccurence;
			break;
		case QuestType.launchedProjectile:
			PlayerGameEvents.OnLaunchedProjectile -= OnGameEventOccurence;
			break;
		case QuestType.moveDistance:
			PlayerGameEvents.OnPlayerMoved -= OnGameMoveEvent;
			break;
		case QuestType.swimDistance:
			PlayerGameEvents.OnPlayerSwam -= OnGameMoveEvent;
			break;
		case QuestType.triggerHandEffect:
			PlayerGameEvents.OnTriggerHandEffect -= OnGameEventOccurence;
			break;
		case QuestType.enterLocation:
			PlayerGameEvents.OnEnterLocation -= OnGameEventOccurence;
			break;
		case QuestType.misc:
			PlayerGameEvents.OnMiscEvent -= OnGameEventOccurence;
			break;
		case QuestType.critter:
			PlayerGameEvents.OnCritterEvent -= OnGameEventOccurence;
			break;
		}
	}

	public void ApplySavedProgress(int progress)
	{
		if (questType == QuestType.moveDistance || questType == QuestType.swimDistance)
		{
			moveDistance = progress;
			occurenceCount = Mathf.FloorToInt(moveDistance);
			isQuestComplete = occurenceCount >= requiredOccurenceCount;
		}
		else
		{
			occurenceCount = progress;
			isQuestComplete = occurenceCount >= requiredOccurenceCount;
		}
	}

	public int GetProgress()
	{
		if (questType == QuestType.moveDistance || questType == QuestType.swimDistance)
		{
			return Mathf.FloorToInt(moveDistance);
		}
		return occurenceCount;
	}

	private void OnGameEventOccurence(string eventName)
	{
		OnGameEventOccurence(eventName, 1);
	}

	private void OnGameEventOccurence(string eventName, int count)
	{
		if (RequiredZone == GTZone.none || ZoneManagement.IsInZone(RequiredZone))
		{
			string.IsNullOrEmpty(questOccurenceFilter);
			if (eventName.StartsWith(questOccurenceFilter))
			{
				SetProgress(occurenceCount + count);
			}
		}
	}

	private void OnGameMoveEvent(float distance, float speed)
	{
		if (RequiredZone != GTZone.none && !ZoneManagement.IsInZone(RequiredZone))
		{
			return;
		}
		if (questOccurenceFilter == "maxSpeed")
		{
			if (!(speed <= moveDistance))
			{
				moveDistance = speed;
				SetProgress(Mathf.FloorToInt(moveDistance));
			}
		}
		else
		{
			moveDistance += distance;
			SetProgress(Mathf.FloorToInt(moveDistance));
		}
	}

	private void SetProgress(int progress)
	{
		if (!isQuestComplete && occurenceCount != progress)
		{
			lastChange = Time.frameCount;
			occurenceCount = progress;
			if (questType == QuestType.moveDistance || questType == QuestType.swimDistance)
			{
				moveDistance = progress;
			}
			if (occurenceCount >= requiredOccurenceCount)
			{
				Complete();
			}
			questManager.HandleQuestProgressChanged(initialLoad: false);
		}
	}

	private void Complete()
	{
		if (!isQuestComplete)
		{
			isQuestComplete = true;
			RemoveEventListener();
			questManager.HandleQuestCompleted(questID);
		}
	}

	public string GetTextDescription()
	{
		return GetActionName().ToUpper() + GetLocationText().ToUpper();
		string GetActionName()
		{
			return questType switch
			{
				QuestType.none => "[UNDEFINED]", 
				QuestType.gameModeObjective => questName, 
				QuestType.gameModeRound => questName, 
				QuestType.grabObject => questName, 
				QuestType.dropObject => questName, 
				QuestType.eatObject => questName, 
				QuestType.launchedProjectile => questName, 
				QuestType.moveDistance => questName, 
				QuestType.swimDistance => questName, 
				QuestType.triggerHandEffect => questName, 
				QuestType.enterLocation => questName, 
				QuestType.misc => questName, 
				_ => questName, 
			};
		}
		string GetLocationText()
		{
			if (RequiredZone == GTZone.none)
			{
				return "";
			}
			return $" IN {RequiredZone}";
		}
	}

	public string GetProgressText()
	{
		if (!isQuestComplete)
		{
			return $"{occurenceCount}/{requiredOccurenceCount}";
		}
		return "[DONE]";
	}
}
public class RotatingQuestsManager : MonoBehaviour, ITickSystemTick, GorillaQuestManager
{
	[Serializable]
	public class RotatingQuestGroup
	{
		public int selectCount;

		public string name;

		public List<RotatingQuest> quests;
	}

	[Serializable]
	public class RotatingQuestList
	{
		public List<RotatingQuestGroup> DailyQuests;

		public List<RotatingQuestGroup> WeeklyQuests;

		public void Init()
		{
			SetIsDaily(DailyQuests, isDaily: true);
			SetIsDaily(WeeklyQuests, isDaily: false);
			static void SetIsDaily(List<RotatingQuestGroup> questList, bool isDaily)
			{
				foreach (RotatingQuestGroup quest in questList)
				{
					foreach (RotatingQuest quest2 in quest.quests)
					{
						quest2.isDailyQuest = isDaily;
					}
				}
			}
		}

		public RotatingQuest GetQuest(int questID)
		{
			RotatingQuest rotatingQuest = null;
			rotatingQuest = GetQuestFrom(DailyQuests);
			if (rotatingQuest == null)
			{
				rotatingQuest = GetQuestFrom(WeeklyQuests);
			}
			return rotatingQuest;
			RotatingQuest GetQuestFrom(List<RotatingQuestGroup> list)
			{
				foreach (RotatingQuestGroup item in list)
				{
					foreach (RotatingQuest quest in item.quests)
					{
						if (quest.questID == questID)
						{
							return quest;
						}
					}
				}
				return null;
			}
		}
	}

	private bool hasQuest;

	[SerializeField]
	private bool useTestLocalQuests;

	[SerializeField]
	private string localQuestPath = "TestingRotatingQuests";

	public static int LastQuestChange;

	public static int LastQuestDailyID;

	public RotatingQuestList quests;

	public int dailyQuestSetID;

	public int weeklyQuestSetID;

	[SerializeField]
	private bool _playQuestSounds;

	private AudioSource _questAudio;

	private DateTime nextQuestUpdateTime;

	private const string kDailyQuestSetIDKey = "Rotating_Quest_Daily_SetID_Key";

	private const string kDailyQuestSaveCountKey = "Rotating_Quest_Daily_SaveCount_Key";

	private const string kDailyQuestIDKey = "Rotating_Quest_Daily_ID_Key";

	private const string kDailyQuestProgressKey = "Rotating_Quest_Daily_Progress_Key";

	private const string kWeeklyQuestSetIDKey = "Rotating_Quest_Weekly_SetID_Key";

	private const string kWeeklyQuestSaveCountKey = "Rotating_Quest_Weekly_SaveCount_Key";

	private const string kWeeklyQuestIDKey = "Rotating_Quest_Weekly_ID_Key";

	private const string kWeeklyQuestProgressKey = "Rotating_Quest_Weekly_Progress_Key";

	public bool TickRunning { get; set; }

	public DateTime DailyQuestCountdown { get; private set; }

	public DateTime WeeklyQuestCountdown { get; private set; }

	private void Start()
	{
		_questAudio = GetComponent<AudioSource>();
		RequestQuestsFromTitleData();
	}

	private void OnEnable()
	{
		TickSystem<object>.AddTickCallback(this);
	}

	private void OnDisable()
	{
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void Tick()
	{
		if (hasQuest && nextQuestUpdateTime < DateTime.UtcNow)
		{
			SetupQuests();
		}
	}

	private void ProcessAllQuests(Action<RotatingQuest> action)
	{
		ProcessAllQuestsInList(quests.DailyQuests);
		ProcessAllQuestsInList(quests.WeeklyQuests);
		void ProcessAllQuestsInList(List<RotatingQuestGroup> questGroups)
		{
			foreach (RotatingQuestGroup questGroup in questGroups)
			{
				foreach (RotatingQuest quest in questGroup.quests)
				{
					action(quest);
				}
			}
		}
	}

	private void QuestLoadPostProcess(RotatingQuest quest)
	{
		if (quest.requiredZones.Count == 1 && quest.requiredZones[0] == GTZone.none)
		{
			quest.requiredZones.Clear();
		}
	}

	private void QuestSavePreProcess(RotatingQuest quest)
	{
		if (quest.requiredZones.Count == 0)
		{
			quest.requiredZones.Add(GTZone.none);
		}
	}

	public void LoadTestQuestsFromFile()
	{
		TextAsset textAsset = Resources.Load<TextAsset>(localQuestPath);
		LoadQuestsFromJson(textAsset.text);
	}

	public void RequestQuestsFromTitleData()
	{
		PlayFabTitleDataCache.Instance.GetTitleData("AllActiveQuests", delegate(string data)
		{
			LoadQuestsFromJson(data);
		}, delegate(PlayFabError e)
		{
			UnityEngine.Debug.LogError($"Error getting AllActiveQuests data: {e}");
		});
	}

	public void LoadQuestsFromJson(string jsonString)
	{
		quests = JsonConvert.DeserializeObject<RotatingQuestList>(jsonString);
		ProcessAllQuests(QuestLoadPostProcess);
		if (quests == null)
		{
			UnityEngine.Debug.LogError("Error: Quests failed to parse!");
			return;
		}
		hasQuest = true;
		quests.Init();
		if (UnityEngine.Application.isPlaying)
		{
			SetupQuests();
		}
	}

	private void SetupQuests()
	{
		ClearAllQuestEventListeners();
		SelectActiveQuests();
		LoadQuestProgress();
		HandleQuestProgressChanged(initialLoad: true);
		SetupAllQuestEventListeners();
		nextQuestUpdateTime = DailyQuestCountdown;
		nextQuestUpdateTime = nextQuestUpdateTime.AddMinutes(1.0);
	}

	private void SelectActiveQuests()
	{
		DateTime dateTime = new DateTime(2025, 1, 10, 18, 0, 0, DateTimeKind.Utc);
		TimeSpan timeSpan = TimeSpan.FromHours(-8.0);
		DateTime dateStart = new DateTime(1, 1, 1, 0, 0, 0);
		DateTime dateEnd = new DateTime(2006, 12, 31, 0, 0, 0);
		TimeSpan daylightDelta = TimeSpan.FromHours(1.0);
		TimeZoneInfo.TransitionTime daylightTransitionStart = TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new DateTime(1, 1, 1, 2, 0, 0), 4, 1, DayOfWeek.Sunday);
		TimeZoneInfo.TransitionTime daylightTransitionEnd = TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new DateTime(1, 1, 1, 2, 0, 0), 10, 5, DayOfWeek.Sunday);
		DateTime dateStart2 = new DateTime(2007, 1, 1, 0, 0, 0);
		DateTime dateEnd2 = new DateTime(9999, 12, 31, 0, 0, 0);
		TimeSpan daylightDelta2 = TimeSpan.FromHours(1.0);
		TimeZoneInfo.TransitionTime daylightTransitionStart2 = TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new DateTime(1, 1, 1, 2, 0, 0), 3, 2, DayOfWeek.Sunday);
		TimeZoneInfo.TransitionTime daylightTransitionEnd2 = TimeZoneInfo.TransitionTime.CreateFloatingDateRule(new DateTime(1, 1, 1, 2, 0, 0), 11, 1, DayOfWeek.Sunday);
		TimeZoneInfo timeZoneInfo = TimeZoneInfo.CreateCustomTimeZone("Pacific Standard Time", timeSpan, "Pacific Standard Time", "Pacific Standard Time", "Pacific Standard Time", new TimeZoneInfo.AdjustmentRule[2]
		{
			TimeZoneInfo.AdjustmentRule.CreateAdjustmentRule(dateStart, dateEnd, daylightDelta, daylightTransitionStart, daylightTransitionEnd),
			TimeZoneInfo.AdjustmentRule.CreateAdjustmentRule(dateStart2, dateEnd2, daylightDelta2, daylightTransitionStart2, daylightTransitionEnd2)
		});
		if (timeZoneInfo != null && timeZoneInfo.IsDaylightSavingTime(DateTime.UtcNow - timeSpan))
		{
			dateTime -= TimeSpan.FromHours(1.0);
		}
		TimeSpan timeSpan2 = DateTime.UtcNow - dateTime;
		RemoveDisabledQuests();
		weeklyQuestSetID = (dailyQuestSetID = timeSpan2.Days) / 7;
		LastQuestDailyID = dailyQuestSetID;
		DailyQuestCountdown = dateTime + TimeSpan.FromDays(dailyQuestSetID + 1);
		WeeklyQuestCountdown = dateTime + TimeSpan.FromDays((weeklyQuestSetID + 1) * 7);
		UnityEngine.Random.InitState(dailyQuestSetID);
		foreach (RotatingQuestGroup dailyQuest in quests.DailyQuests)
		{
			int num = System.Math.Min(dailyQuest.selectCount, dailyQuest.quests.Count);
			float num2 = 0f;
			List<(int, float)> list = new List<(int, float)>(dailyQuest.quests.Count);
			for (int i = 0; i < dailyQuest.quests.Count; i++)
			{
				dailyQuest.quests[i].isQuestActive = false;
				num2 += dailyQuest.quests[i].weight;
				list.Add((i, dailyQuest.quests[i].weight));
			}
			for (int j = 0; j < num; j++)
			{
				float num3 = UnityEngine.Random.Range(0f, num2);
				for (int k = 0; k < list.Count; k++)
				{
					float item = list[k].Item2;
					if (num3 <= item || k == list.Count - 1)
					{
						num2 -= item;
						int item2 = list[k].Item1;
						list.RemoveAt(k);
						dailyQuest.quests[item2].isQuestActive = true;
						dailyQuest.quests[item2].SetRequiredZone();
						break;
					}
					num3 -= item;
				}
			}
		}
		UnityEngine.Random.InitState(weeklyQuestSetID);
		foreach (RotatingQuestGroup weeklyQuest in quests.WeeklyQuests)
		{
			int num4 = System.Math.Min(weeklyQuest.selectCount, weeklyQuest.quests.Count);
			float num5 = 0f;
			List<(int, float)> list2 = new List<(int, float)>(weeklyQuest.quests.Count);
			for (int l = 0; l < weeklyQuest.quests.Count; l++)
			{
				weeklyQuest.quests[l].isQuestActive = false;
				num5 += weeklyQuest.quests[l].weight;
				list2.Add((l, weeklyQuest.quests[l].weight));
			}
			for (int m = 0; m < num4; m++)
			{
				float num6 = UnityEngine.Random.Range(0f, num5);
				for (int n = 0; n < list2.Count; n++)
				{
					float item3 = list2[n].Item2;
					if (num6 <= item3 || n == list2.Count - 1)
					{
						num5 -= item3;
						int item4 = list2[n].Item1;
						list2.RemoveAt(n);
						weeklyQuest.quests[item4].isQuestActive = true;
						weeklyQuest.quests[item4].SetRequiredZone();
						break;
					}
					num6 -= item3;
				}
			}
		}
		ProgressionController.ReportQuestSelectionChanged();
	}

	private void RemoveDisabledQuests()
	{
		RemoveDisabledQuestsFromGroupList(quests.DailyQuests);
		RemoveDisabledQuestsFromGroupList(quests.WeeklyQuests);
		static void RemoveDisabledQuestsFromGroupList(List<RotatingQuestGroup> questList)
		{
			foreach (RotatingQuestGroup quest in questList)
			{
				for (int num = quest.quests.Count - 1; num >= 0; num--)
				{
					if (quest.quests[num].disable)
					{
						quest.quests.RemoveAt(num);
					}
				}
			}
		}
	}

	public void LoadQuestProgress()
	{
		int num = PlayerPrefs.GetInt("Rotating_Quest_Daily_SetID_Key", -1);
		int num2 = PlayerPrefs.GetInt("Rotating_Quest_Daily_SaveCount_Key", -1);
		if (num == dailyQuestSetID)
		{
			for (int i = 0; i < num2; i++)
			{
				int num3 = PlayerPrefs.GetInt(string.Format("{0}{1}", "Rotating_Quest_Daily_ID_Key", i), -1);
				int progress = PlayerPrefs.GetInt(string.Format("{0}{1}", "Rotating_Quest_Daily_Progress_Key", i), -1);
				if (num3 == -1)
				{
					continue;
				}
				for (int j = 0; j < quests.DailyQuests.Count; j++)
				{
					for (int k = 0; k < quests.DailyQuests[j].quests.Count; k++)
					{
						RotatingQuest rotatingQuest = quests.DailyQuests[j].quests[k];
						if (rotatingQuest.questID == num3)
						{
							rotatingQuest.ApplySavedProgress(progress);
							break;
						}
					}
				}
			}
		}
		int num4 = PlayerPrefs.GetInt("Rotating_Quest_Weekly_SetID_Key", -1);
		int num5 = PlayerPrefs.GetInt("Rotating_Quest_Weekly_SaveCount_Key", -1);
		if (num4 != weeklyQuestSetID)
		{
			return;
		}
		for (int l = 0; l < num5; l++)
		{
			int num6 = PlayerPrefs.GetInt(string.Format("{0}{1}", "Rotating_Quest_Weekly_ID_Key", l), -1);
			int progress2 = PlayerPrefs.GetInt(string.Format("{0}{1}", "Rotating_Quest_Weekly_Progress_Key", l), -1);
			if (num6 == -1)
			{
				continue;
			}
			for (int m = 0; m < quests.WeeklyQuests.Count; m++)
			{
				for (int n = 0; n < quests.WeeklyQuests[m].quests.Count; n++)
				{
					RotatingQuest rotatingQuest2 = quests.WeeklyQuests[m].quests[n];
					if (rotatingQuest2.questID == num6)
					{
						rotatingQuest2.ApplySavedProgress(progress2);
						break;
					}
				}
			}
		}
	}

	public void SaveQuestProgress()
	{
		int num = 0;
		for (int i = 0; i < quests.DailyQuests.Count; i++)
		{
			for (int j = 0; j < quests.DailyQuests[i].quests.Count; j++)
			{
				RotatingQuest rotatingQuest = quests.DailyQuests[i].quests[j];
				int progress = rotatingQuest.GetProgress();
				if (progress > 0)
				{
					PlayerPrefs.SetInt(string.Format("{0}{1}", "Rotating_Quest_Daily_ID_Key", num), rotatingQuest.questID);
					PlayerPrefs.SetInt(string.Format("{0}{1}", "Rotating_Quest_Daily_Progress_Key", num), progress);
					num++;
				}
			}
		}
		if (num > 0)
		{
			PlayerPrefs.SetInt("Rotating_Quest_Daily_SetID_Key", dailyQuestSetID);
			PlayerPrefs.SetInt("Rotating_Quest_Daily_SaveCount_Key", num);
		}
		int num2 = 0;
		for (int k = 0; k < quests.WeeklyQuests.Count; k++)
		{
			for (int l = 0; l < quests.WeeklyQuests[k].quests.Count; l++)
			{
				RotatingQuest rotatingQuest2 = quests.WeeklyQuests[k].quests[l];
				int progress2 = rotatingQuest2.GetProgress();
				if (progress2 > 0)
				{
					PlayerPrefs.SetInt(string.Format("{0}{1}", "Rotating_Quest_Weekly_ID_Key", num2), rotatingQuest2.questID);
					PlayerPrefs.SetInt(string.Format("{0}{1}", "Rotating_Quest_Weekly_Progress_Key", num2), progress2);
					num2++;
				}
			}
		}
		if (num2 > 0)
		{
			PlayerPrefs.SetInt("Rotating_Quest_Weekly_SetID_Key", weeklyQuestSetID);
			PlayerPrefs.SetInt("Rotating_Quest_Weekly_SaveCount_Key", num2);
		}
		PlayerPrefs.Save();
	}

	public void SetupAllQuestEventListeners()
	{
		foreach (RotatingQuestGroup dailyQuest in quests.DailyQuests)
		{
			foreach (RotatingQuest quest in dailyQuest.quests)
			{
				quest.questManager = this;
				if (quest.isQuestActive && !quest.isQuestComplete)
				{
					quest.AddEventListener();
				}
			}
		}
		foreach (RotatingQuestGroup weeklyQuest in quests.WeeklyQuests)
		{
			foreach (RotatingQuest quest2 in weeklyQuest.quests)
			{
				quest2.questManager = this;
				if (quest2.isQuestActive && !quest2.isQuestComplete)
				{
					quest2.AddEventListener();
				}
			}
		}
	}

	public void ClearAllQuestEventListeners()
	{
		foreach (RotatingQuestGroup dailyQuest in quests.DailyQuests)
		{
			foreach (RotatingQuest quest in dailyQuest.quests)
			{
				quest.RemoveEventListener();
			}
		}
		foreach (RotatingQuestGroup weeklyQuest in quests.WeeklyQuests)
		{
			foreach (RotatingQuest quest2 in weeklyQuest.quests)
			{
				quest2.RemoveEventListener();
			}
		}
	}

	public void HandleQuestCompleted(int questID)
	{
		RotatingQuest quest = quests.GetQuest(questID);
		if (quest != null)
		{
			ProgressionController.ReportQuestComplete(questID, quest.isDailyQuest);
			if (_playQuestSounds)
			{
				_questAudio?.GTPlay();
			}
		}
	}

	public void HandleQuestProgressChanged(bool initialLoad)
	{
		if (!initialLoad)
		{
			SaveQuestProgress();
		}
		LastQuestChange = Time.frameCount;
		ProgressionController.ReportQuestChanged(initialLoad);
	}
}
