		else if (PropHuntPools.TryGetTaggableProp(cosmeticId, out out_prop2))
		{
			_taggableProp = out_prop2;
			_grabbableProp = null;
			_prop = out_prop2.gameObject;
			_propOffset = out_prop2.offset;
			out_prop2.ownerRig = attachedToRig;
