	private static void _ResetPool<T>(Dictionary<string, T> cosmeticId_to_propTemplate, Dictionary<string, Queue<T>> cosmeticId_to_inactiveProps, Dictionary<T, string> activeProp_to_cosmeticId) where T : UnityEngine.Component
	{
		foreach (T value in cosmeticId_to_propTemplate.Values)
		{
			if (value != null)
			{
				UnityEngine.Object.Destroy(value);
			}
		}
		cosmeticId_to_propTemplate.Clear();
		foreach (Queue<T> value2 in cosmeticId_to_inactiveProps.Values)
		{
			foreach (T item in value2)
			{
				if (item != null)
				{
					UnityEngine.Object.Destroy(item.gameObject);
				}
			}
		}
		cosmeticId_to_inactiveProps.Clear();
		foreach (T key in activeProp_to_cosmeticId.Keys)
		{
			if (key != null)
			{
				UnityEngine.Object.Destroy(key.gameObject);
			}
		}
		activeProp_to_cosmeticId.Clear();
	}

	private static void _CreateInactivePropsParent(ref Transform _inactivePropsParent, string name)
	{
		if (_inactivePropsParent != null)
		{
			UnityEngine.Object.Destroy(_inactivePropsParent.gameObject);
		}
		_inactivePropsParent = new GameObject("__PropHunt_-_" + name + "__").transform;
		_inactivePropsParent.gameObject.SetActive(value: false);
		UnityEngine.Object.DontDestroyOnLoad(_inactivePropsParent);
		_inactivePropsParent.gameObject.isStatic = true;
	}

	private static void _HandleOnTitleDataPropsListLoaded(string titleDataPropsString)
	{
		_allPropCosmeticIds = titleDataPropsString.Split(_g_ph_titleDataSeparators, StringSplitOptions.RemoveEmptyEntries);
		_propCosmeticIdsWaitingToLoad.UnionWith(_allPropCosmeticIds);
		string playFabID = _fallbackProp_cosmeticSO.info.playFabID;
		_propCosmeticIdsWaitingToLoad.Add(playFabID);
		int num = 0;
		_propCosmeticIds_uniqueArray = new string[_propCosmeticIdsWaitingToLoad.Count];
		foreach (string item in _propCosmeticIdsWaitingToLoad)
		{
			int num2 = 0;
			for (int i = 0; i < _allPropCosmeticIds.Length; i++)
			{
				num2 += ((item == _allPropCosmeticIds[i]) ? 1 : 0);
			}
			_cosmeticId_to_decoyInitialCount[item] = num2 * 10;
			_propCosmeticIds_uniqueArray[num] = item;
			num++;
		}
		AsyncOperationHandle<GameObject> handle = _fallbackProp_cosmeticSO.info.wardrobeParts[0].prefabAssetRef.InstantiateAsync(_decoyTemplatesParent);
		handle.WaitForCompletion();
		_HandleOnPropTemplateLoaded(handle, playFabID, _fallbackProp_cosmeticSO);
		_state_isTitleDataLoaded = true;
		_state_hasLocalPlayerVisitedBayou |= VRRigCache.Instance != null && VRRigCache.Instance.localRig != null && VRRigCache.Instance.localRig.Rig.zoneEntity.currentZone == GTZone.bayou;
		if (_state_hasLocalPlayerVisitedBayou)
		{
			StartCreatingPools();
		}
		else
		{
			_state = EState.WaitingForLocalPlayerToVisitBayou;
		}
	}

	internal static void OnLocalPlayerEnteredBayou()
	{
		if (!_state_hasLocalPlayerVisitedBayou)
		{
			_state_hasLocalPlayerVisitedBayou = true;
			if (_state_isTitleDataLoaded)
			{
				StartCreatingPools();
			}
		}
	}

	internal static void StartCreatingPools()
	{
		_state = EState.SpawningProps;
		for (int i = 0; i < _propCosmeticIds_uniqueArray.Length; i++)
		{
			string cosmeticId = _propCosmeticIds_uniqueArray[i];
			CosmeticSO cosmeticSO = _allCosmeticsArraySO.SearchForCosmeticSO(cosmeticId);
			propCosmeticId_to_cosmeticSO[cosmeticId] = cosmeticSO;
			if (cosmeticSO == null)
			{
				UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: CosmeticId \"" + cosmeticId + "\" from title data does not exist in AllCosmeticsArraySO. Using backup \"" + _fallbackProp_cosmeticSO.name + "\" instead.");
				cosmeticSO = _fallbackProp_cosmeticSO;
			}
			else
			{
				CosmeticPart[] wardrobeParts = cosmeticSO.info.wardrobeParts;
				if (wardrobeParts == null || wardrobeParts.Length <= 0)
				{
					UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: Prop \"" + cosmeticSO.name + "\" has no wardrobeParts. Using backup \"" + _fallbackProp_cosmeticSO.name + "\" instead.");
					cosmeticSO = _fallbackProp_cosmeticSO;
				}
			}
			GTAssetRef<GameObject> prefabAssetRef = cosmeticSO.info.wardrobeParts[0].prefabAssetRef;
			if (!_cosmeticId_to_inactiveDecoys.TryGetValue(cosmeticId, out var value))
			{
				value = new Queue<PropPlacementRB>(10);
				_cosmeticId_to_inactiveDecoys[cosmeticId] = value;
				AsyncOperationHandle<GameObject> asyncOperationHandle = prefabAssetRef.InstantiateAsync(_taggableTemplatesParent);
				asyncOperationHandle.Completed += delegate(AsyncOperationHandle<GameObject> handle)
				{
					_HandleOnPropTemplateLoaded(handle, cosmeticId, cosmeticSO);
				};
			}
		}
	}

	private static void _HandleOnPropTemplateLoaded(AsyncOperationHandle<GameObject> handle, string cosmeticId, CosmeticSO cosmeticSO)
	{
		bool flag = cosmeticSO == _fallbackProp_cosmeticSO;
		if (handle.Status != AsyncOperationStatus.Succeeded)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: " + $"Failed to load asset for pooling: {cosmeticSO.name} with error: {handle.OperationException}", cosmeticSO);
			return;
		}
		GameObject gameObject = handle.Result;
		if (gameObject == null)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: (should never happen) Failed to load asset prop from CosmeticSO \"" + cosmeticSO.name + "\" for pooling but while async op was successful, the resulting GameObject was null!", cosmeticSO);
			return;
		}
		gameObject.SetActive(value: false);
		gameObject.name = "PropHunt_Prop" + cosmeticSO.name;
		gameObject.layer = 14;
		_temp_meshFilters.Clear();
		UnityEngine.Component[] componentsInChildren = gameObject.GetComponentsInChildren<UnityEngine.Component>(includeInactive: true);
		foreach (UnityEngine.Component component in componentsInChildren)
		{
			if (component is Transform transform)
			{
				transform.gameObject.isStatic = false;
			}
			else if (component is MeshRenderer meshRenderer)
			{
				if (meshRenderer.enabled)
				{
					MeshFilter component2 = meshRenderer.GetComponent<MeshFilter>();
					if ((object)component2 != null)
					{
						_temp_meshFilters.Add(component2);
					}
				}
				else
				{
					UnityEngine.Object.Destroy(meshRenderer);
				}
			}
			else
			{
				UnityEngine.Object.Destroy(component);
			}
		}
		if (_temp_meshFilters.Count == 0)
		{
			gameObject = _fallbackPrefabInstance;
		}
		List<Transform> list = new List<Transform>(gameObject.GetComponentsInChildren<Transform>(includeInactive: true));
		list.Sort((Transform a, Transform b) => -a.GetDepth().CompareTo(b.GetDepth()));
		Transform transform2 = gameObject.transform;
		for (int num = 0; num < list.Count; num++)
		{
			Transform transform3 = list[num];
			if (transform3.childCount == 0 && !(transform3 == transform2))
			{
				UnityEngine.Component[] components = transform3.GetComponents<UnityEngine.Component>();
				int num2 = 0;
				for (int num3 = 0; num3 < components.Length; num3++)
				{
					int num4 = num2;
					UnityEngine.Component component3 = components[num3];
					num2 = num4 + ((!(component3 is Transform) && !(component3 is MeshRenderer) && !(component3 is MeshFilter)) ? 1 : 0);
				}
				if (num2 == 0)
				{
					UnityEngine.Object.Destroy(transform3.gameObject);
				}
			}
		}
		if (flag && _fallbackPrefabInstance == null)
		{
			_fallbackPrefabInstance = UnityEngine.Object.Instantiate(gameObject);
		}
		if (!_cosmeticId_to_decoyTemplate.ContainsKey(cosmeticId))
		{
			PropPlacementRB propPlacementRB = UnityEngine.Object.Instantiate(GorillaPropHuntGameManager.instance.PropDecoyPrefab, _decoyTemplatesParent);
			GameObject gameObject2 = UnityEngine.Object.Instantiate(gameObject, _decoyTemplatesParent);
			propPlacementRB.name = "__PropHuntPoolProp_Decoy_TEMPLATE__" + cosmeticSO.name + "__";
			PropPlacementRB.TryPrepPropTemplate(propPlacementRB, gameObject2, cosmeticSO);
			propPlacementRB.gameObject.SetActive(value: false);
			gameObject2.transform.SetParent(propPlacementRB.transform);
			_cosmeticId_to_decoyTemplate[cosmeticId] = propPlacementRB;
			int num5 = _cosmeticId_to_decoyInitialCount[cosmeticId];
			Queue<PropPlacementRB> queue = new Queue<PropPlacementRB>(num5);
			string name = "__PropHuntPoolProp_Decoy__" + cosmeticSO.name + "__";
			for (int num6 = 0; num6 < num5; num6++)
			{
				PropPlacementRB propPlacementRB2 = UnityEngine.Object.Instantiate(propPlacementRB, _decoyInactivePropsParent);
				propPlacementRB2.name = name;
				queue.Enqueue(propPlacementRB2);
			}
			_cosmeticId_to_inactiveDecoys[cosmeticId] = queue;
		}
		if (!_cosmeticId_to_grabbableTemplate.ContainsKey(cosmeticId))
		{
			GameObject prop = UnityEngine.Object.Instantiate(gameObject, _grabbableTemplatesParent);
			List<MeshCollider> colliders = new List<MeshCollider>();
			List<InteractionPoint> ref_interactionPoints = new List<InteractionPoint>();
			PropHuntHandFollower.TryPrepPropTemplate(prop, _isLocal: true, cosmeticSO, colliders, ref_interactionPoints, out var grabbableProp, out var _);
			grabbableProp.name = "GrabbableProp_Template_" + cosmeticSO.name;
			_cosmeticId_to_grabbableTemplate[cosmeticId] = grabbableProp;
			Queue<PropHuntGrabbableProp> queue2 = new Queue<PropHuntGrabbableProp>(1);
			string name2 = "__PropHuntPoolProp_Grabbable__" + cosmeticSO.name + "__";
			for (int num7 = 0; num7 < 1; num7++)
			{
				GameObject gameObject3 = UnityEngine.Object.Instantiate(grabbableProp.gameObject, _grabbableInactivePropsParent);
				gameObject3.name = name2;
				queue2.Enqueue(gameObject3.GetComponent<PropHuntGrabbableProp>());
			}
			_cosmeticId_to_inactiveGrabbables[cosmeticId] = queue2;
		}
		if (!_cosmeticId_to_taggableTemplate.ContainsKey(cosmeticId))
		{
			GameObject prop2 = gameObject;
			gameObject = null;
			List<MeshCollider> colliders2 = new List<MeshCollider>();
			List<InteractionPoint> ref_interactionPoints2 = new List<InteractionPoint>();
			PropHuntHandFollower.TryPrepPropTemplate(prop2, _isLocal: false, cosmeticSO, colliders2, ref_interactionPoints2, out var _, out var taggableProp2);
			taggableProp2.name = "__PropHuntPoolProp_Taggable_TEMPLATE__" + cosmeticSO.name + "__";
			_cosmeticId_to_taggableTemplate[cosmeticId] = taggableProp2;
			Queue<PropHuntTaggableProp> queue3 = new Queue<PropHuntTaggableProp>(2);
			string name3 = "__PropHuntPoolProp_Taggable__" + cosmeticSO.name + "__";
			for (int num8 = 0; num8 < 2; num8++)
			{
				GameObject gameObject4 = UnityEngine.Object.Instantiate(taggableProp2.gameObject, _taggableInactivePropsParent);
				gameObject4.name = name3;
				queue3.Enqueue(gameObject4.GetComponent<PropHuntTaggableProp>());
			}
			_cosmeticId_to_inactiveTaggables[cosmeticId] = queue3;
		}
		_propCosmeticIdsWaitingToLoad.Remove(cosmeticId);
		if (_propCosmeticIdsWaitingToLoad.Count == 0)
		{
			_state = EState.Ready;
			OnReady?.Invoke();
		}
	}

	public static bool TryGetDecoyProp(string cosmeticId, out PropPlacementRB out_prop)
	{
		if (!IsReady)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools:  TryGetDecoyProp: Cannot get because `PropHuntPools.IsReady` is not true yet!");
			out_prop = null;
			return false;
		}
		if (_cosmeticId_to_inactiveDecoys.TryGetValue(cosmeticId, out var value))
		{
			if (value.Count > 0)
			{
				out_prop = value.Dequeue();
				out_prop.transform.SetParent(null);
				out_prop.gameObject.SetActive(value: true);
				_activeDecoy_to_cosmeticId[out_prop] = cosmeticId;
				return true;
			}
			if (_cosmeticId_to_decoyTemplate.TryGetValue(cosmeticId, out var value2))
			{
				int b = ++_cosmeticId_to_decoyInitialCount[cosmeticId];
				_debug_decoyMaxCountPerProp = Mathf.Max(_debug_decoyMaxCountPerProp, b);
				out_prop = UnityEngine.Object.Instantiate(value2);
				_activeDecoy_to_cosmeticId[out_prop] = cosmeticId;
				return true;
			}
			out_prop = null;
			return false;
		}
		UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: (should never happen) Prop does not exist with cosmeticId \"" + cosmeticId + "\"!");
		out_prop = null;
		return false;
	}

	public static bool TryGetTaggableProp(string cosmeticId, out PropHuntTaggableProp out_prop)
	{
		if (!IsReady)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: TryGetTaggableProp: Cannot get because `PropHuntPools.IsReady` is not true yet!");
			out_prop = null;
			return false;
		}
		if (_cosmeticId_to_inactiveTaggables.TryGetValue(cosmeticId, out var value))
		{
			if (value.Count > 0)
			{
				out_prop = value.Dequeue();
				out_prop.transform.SetParent(null);
				out_prop.gameObject.SetActive(value: true);
				_activeTaggable_to_cosmeticId[out_prop] = cosmeticId;
				return true;
			}
			if (_cosmeticId_to_taggableTemplate.TryGetValue(cosmeticId, out var value2))
			{
				_debug_decoyMaxCountPerProp = ((_debug_decoyMaxCountPerProp >= value.Count + 1) ? _debug_decoyMaxCountPerProp : ((int)((double)value.Count * 1.5)));
				out_prop = UnityEngine.Object.Instantiate(value2);
				_activeTaggable_to_cosmeticId[out_prop] = cosmeticId;
				return true;
			}
		}
		UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: Prop does not exist with cosmeticId \"" + cosmeticId + "\"!");
		out_prop = null;
		return false;
	}

	public static bool TryGetGrabbableProp(string cosmeticId, out PropHuntGrabbableProp out_prop)
	{
		if (!IsReady)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools:  TryGetGrabbableProp: Called before pools are ready.");
			out_prop = null;
			return false;
		}
		if (_cosmeticId_to_inactiveGrabbables.TryGetValue(cosmeticId, out var value) && value.Count > 0)
		{
			out_prop = value.Dequeue();
			out_prop.transform.SetParent(null);
			out_prop.gameObject.SetActive(value: true);
			_activeGrabbable_to_cosmeticId[out_prop] = cosmeticId;
			return true;
		}
		if (_cosmeticId_to_grabbableTemplate.TryGetValue(cosmeticId, out var value2))
		{
			out_prop = UnityEngine.Object.Instantiate(value2);
			_activeGrabbable_to_cosmeticId[out_prop] = cosmeticId;
			return true;
		}
		UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: Prop does not exist with cosmeticId \"" + cosmeticId + "\"!");
		out_prop = null;
		return false;
	}

	public static void ReturnDecoyProp(PropPlacementRB prop)
	{
		string value;
		Queue<PropPlacementRB> value2;
		if (prop == null)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: Tried to return a prop but it was null!");
		}
		else if (_activeDecoy_to_cosmeticId.TryGetValue(prop, out value) && _cosmeticId_to_inactiveDecoys.TryGetValue(value, out value2))
		{
			prop.gameObject.SetActive(value: false);
			prop.transform.SetParent(_grabbableInactivePropsParent);
			value2.Enqueue(prop);
			_activeDecoy_to_cosmeticId.Remove(prop);
		}
	}

	public static void ReturnTaggableProp(PropHuntTaggableProp prop)
	{
		string value;
		Queue<PropHuntTaggableProp> value2;
		if (prop == null)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPools: Tried to return a prop but it was null!");
		}
		else if (_activeTaggable_to_cosmeticId.TryGetValue(prop, out value) && _cosmeticId_to_inactiveTaggables.TryGetValue(value, out value2))
		{
			prop.gameObject.SetActive(value: false);
			prop.transform.SetParent(_grabbableInactivePropsParent);
			value2.Enqueue(prop);
			_activeTaggable_to_cosmeticId.Remove(prop);
		}
	}

	public static void ReturnGrabbableProp(PropHuntGrabbableProp prop)
	{
		if (!(prop == null) && _activeGrabbable_to_cosmeticId.TryGetValue(prop, out var value) && _cosmeticId_to_inactiveGrabbables.TryGetValue(value, out var value2))
		{
			prop.gameObject.SetActive(value: false);
			prop.transform.SetParent(_grabbableInactivePropsParent);
			value2.Enqueue(prop);
			_activeGrabbable_to_cosmeticId.Remove(prop);
		}
	}
}
internal class PropHuntPools_Callbacks
{
	private const string preLog = "PropHuntPools_Callbacks: ";

	private const string preLogEd = "(editor only log) PropHuntPools_Callbacks: ";

	private const string preLogBeta = "(beta only log) PropHuntPools_Callbacks: ";

	private const string preErr = "ERROR!!!  PropHuntPools_Callbacks: ";

	private const string preErrEd = "ERROR!!!  (editor only log) PropHuntPools_Callbacks: ";

	private const string preErrBeta = "ERROR!!!  (beta only log) PropHuntPools_Callbacks: ";

	internal static readonly PropHuntPools_Callbacks instance;

	private static bool _isListeningForZoneChanged;

	static PropHuntPools_Callbacks()
	{
		instance = new PropHuntPools_Callbacks();
	}

	internal void ListenForZoneChanged()
	{
		if (!_isListeningForZoneChanged)
		{
			ZoneManagement.OnZoneChange += _OnZoneChanged;
		}
	}

	private void _OnZoneChanged(ZoneData[] zoneDatas)
	{
		if (!(VRRigCache.Instance == null) && !(VRRigCache.Instance.localRig == null) && !(VRRigCache.Instance.localRig.Rig == null) && VRRigCache.Instance.localRig.Rig.zoneEntity.currentZone == GTZone.bayou)
		{
			_isListeningForZoneChanged = false;
			ZoneManagement.OnZoneChange -= _OnZoneChanged;
			PropHuntPools.OnLocalPlayerEnteredBayou();
		}
	}
}
public class PropHuntPropZone : MonoBehaviour, IDelayedExecListener
{
	private const string preLog = "PropHuntPropZone: ";

	private const string preLogEd = "(editor only log) PropHuntPropZone: ";

	private const string preLogBeta = "(beta only log) PropHuntPropZone: ";

	private const string preErr = "ERROR!!!  PropHuntPropZone: ";

	private const string preErrEd = "ERROR!!!  (editor only log) PropHuntPropZone: ";

	private const string preErrBeta = "ERROR!!!  (beta only log) PropHuntPropZone: ";

	private const bool _k__GT_PROP_HUNT__USE_POOLING__ = true;

	[SerializeField]
	private PropPlacementRB propPlacementPrefab;

	[SerializeField]
	private int seedOffset;

	[SerializeField]
	private float radius = 1f;

	[SerializeField]
	private int numProps = 10;

	[SerializeField]
	private float m_simDurationBeforeFreeze = 2f;

	private BoxCollider boxCollider;

	private bool hasBoxCollider;

	private int nextUnusedPropPlacement;

	private readonly List<PropPlacementRB> propPlacementRBs = new List<PropPlacementRB>(64);

	private void Awake()
	{
		hasBoxCollider = TryGetComponent<BoxCollider>(out boxCollider);
	}

	private void OnEnable()
	{
		GorillaPropHuntGameManager.RegisterPropZone(this);
	}

	private void OnDisable()
	{
		DestroyDecoys();
		GorillaPropHuntGameManager.UnregisterPropZone(this);
	}

	public void DestroyDecoys()
	{
		foreach (PropPlacementRB propPlacementRB in propPlacementRBs)
		{
			if (propPlacementRB != null)
			{
				PropHuntPools.ReturnDecoyProp(propPlacementRB);
			}
		}
		propPlacementRBs.Clear();
	}

	public void OnRoundStart()
	{
		if (!PropHuntPools.IsReady)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropHuntPropZone: (this should never happen) props not ready to be spawned so aborting. you should only be calling this if `PropHuntPools.IsReady` is true or from the callback `PropHuntPools.OnReady`.");
		}
		CreateDecoys(GorillaPropHuntGameManager.instance.GetSeed());
	}

	public void CreateDecoys(int seed)
	{
		DestroyDecoys();
		SRand sRand = new SRand(seed + seedOffset);
		for (int i = 0; i < numProps; i++)
		{
			if (!PropHuntPools.TryGetDecoyProp(GorillaPropHuntGameManager.instance.GetCosmeticId(sRand.NextUInt()), out var out_prop))
			{
				return;
			}
			UnityEngine.Vector3 position2;
			if (hasBoxCollider)
			{
				UnityEngine.Vector3 position = new UnityEngine.Vector3(sRand.NextFloat(0f - boxCollider.size.x, boxCollider.size.x) / 2f, sRand.NextFloat(0f - boxCollider.size.y, boxCollider.size.y) / 2f, sRand.NextFloat(0f - boxCollider.size.z, boxCollider.size.z) / 2f);
				position2 = base.transform.TransformPoint(position);
			}
			else
			{
				position2 = base.transform.position + sRand.NextPointInsideSphere(radius);
			}
			out_prop.gameObject.SetActive(value: false);
			out_prop.transform.SetParent(null, worldPositionStays: false);
			out_prop.transform.position = position2;
			out_prop.transform.rotation = UnityEngine.Quaternion.Euler(sRand.NextFloat(360f), sRand.NextFloat(360f), sRand.NextFloat(360f));
			out_prop._placingProp.SetActive(value: false);
			out_prop._placingProp.transform.SetParent(null, worldPositionStays: false);
			propPlacementRBs.Add(out_prop);
		}
		for (int j = 0; j < propPlacementRBs.Count; j++)
		{
			propPlacementRBs[j].gameObject.SetActive(value: true);
		}
		GTDelayedExec.Add(this, m_simDurationBeforeFreeze, 0);
	}

	public void OnDelayedAction(int contextId)
	{
		for (int i = 0; i < propPlacementRBs.Count; i++)
		{
			PropPlacementRB propPlacementRB = propPlacementRBs[i];
			propPlacementRB.gameObject.SetActive(value: false);
			Transform transform = propPlacementRB.transform;
			GameObject placingProp = propPlacementRB._placingProp;
			placingProp.transform.SetPositionAndRotation(transform.position, transform.rotation);
			placingProp.SetActive(value: true);
		}
	}

	private PropPlacementRB _GetOrCreatePropPlacementObj_NoPool()
	{
		PropPlacementRB propPlacementRB;
		if (nextUnusedPropPlacement < propPlacementRBs.Count)
		{
			propPlacementRB = propPlacementRBs[nextUnusedPropPlacement];
		}
		else
		{
			propPlacementRB = UnityEngine.Object.Instantiate(propPlacementPrefab, base.transform);
			propPlacementRBs.Add(propPlacementRB);
		}
		nextUnusedPropPlacement++;
		return propPlacementRB;
	}

	private void SpawnProp_NoPool(GTAssetRef<GameObject> item, UnityEngine.Vector3 pos, UnityEngine.Quaternion rot, CosmeticSO debugCosmeticSO)
	{
		_GetOrCreatePropPlacementObj_NoPool().PlaceProp_NoPool(this, item, pos, rot, debugCosmeticSO);
	}
}
public class PropHuntTaggableProp : MonoBehaviour
{
	public VRRig ownerRig;

	public UnityEngine.Vector3 offset;
}
public class PropPlacementRB : MonoBehaviour, IDelayedExecListener
{
	[FormerlySerializedAs("rb")]
	[SerializeField]
	private Rigidbody m_rb;

	[FormerlySerializedAs("simDurationBeforeFreeze")]
	[SerializeField]
	private float m_simDurationBeforeFreeze;

	private PropHuntPropZone _parentZone;

	[SerializeField]
	internal GameObject _placingProp;

	[SerializeField]
	private MeshCollider[] _colliders;

	private bool _isInstantiatingAsync;

	protected void OnDestroy()
	{
		if (_placingProp != null)
		{
			UnityEngine.Object.Destroy(_placingProp);
		}
	}

	public void PlaceProp_NoPool(PropHuntPropZone parentZone, GTAssetRef<GameObject> propRef, UnityEngine.Vector3 pos, UnityEngine.Quaternion rot, CosmeticSO debugCosmeticSO)
	{
		if (_isInstantiatingAsync)
		{
			UnityEngine.Debug.LogError("ERROR!!!  PropPlacementRB: Tried to place (spawn) prop while one was already being placed.");
			return;
		}
		_parentZone = parentZone;
		MeshCollider[] colliders = _colliders;
		for (int i = 0; i < colliders.Length; i++)
		{
			colliders[i].gameObject.SetActive(value: false);
		}
		base.transform.position = pos;
		base.transform.rotation = rot;
		base.gameObject.SetActive(value: false);
		_isInstantiatingAsync = true;
		AsyncOperationHandle<GameObject> asyncOperationHandle = propRef.InstantiateAsync();
		asyncOperationHandle.Completed += OnPropLoaded_NoPool;
	}

	public void OnPropLoaded_NoPool(AsyncOperationHandle<GameObject> handle)
	{
		_isInstantiatingAsync = false;
		_placingProp = handle.Result;
		_placingProp.transform.position = base.transform.position;
		_placingProp.transform.rotation = base.transform.rotation;
		m_rb.linearVelocity = UnityEngine.Vector3.zero;
		m_rb.angularVelocity = UnityEngine.Vector3.zero;
		CosmeticSO debugCosmeticSO = null;
		if (!TryPrepPropTemplate(this, _placingProp, debugCosmeticSO))
		{
			DestroyProp_NoPool();
			return;
		}
		_placingProp.SetActive(value: false);
		base.gameObject.SetActive(value: true);
		GTDelayedExec.Add(this, 2f, 0);
	}

	public static bool TryPrepPropTemplate(PropPlacementRB rb, GameObject rendererGobj, CosmeticSO _debugCosmeticSO)
	{
		rb._isInstantiatingAsync = false;
		rb._placingProp = rendererGobj;
		rb._placingProp.transform.position = rb.transform.position;
		rb._placingProp.transform.rotation = rb.transform.rotation;
		rb.m_rb.linearVelocity = UnityEngine.Vector3.zero;
		rb.m_rb.angularVelocity = UnityEngine.Vector3.zero;
		bool flag = false;
		MeshFilter[] componentsInChildren = rendererGobj.GetComponentsInChildren<MeshFilter>(includeInactive: true);
		List<MeshCollider> value;
		using (UnityEngine.Rendering.ListPool<MeshCollider>.Get(out value))
		{
			value.Capacity = math.max(value.Capacity, 8);
			foreach (MeshFilter meshFilter in componentsInChildren)
			{
				Mesh sharedMesh = meshFilter.sharedMesh;
				if (!(sharedMesh == null) && sharedMesh.isReadable)
				{
					flag = true;
					GameObject obj = new GameObject(meshFilter.name + "__PropHuntDecoy_Collider");
					obj.transform.parent = rb.transform;
					obj.layer = 30;
					MeshCollider meshCollider = obj.AddComponent<MeshCollider>();
					meshCollider.convex = true;
					meshCollider.transform.position = meshFilter.transform.position;
					meshCollider.transform.rotation = meshFilter.transform.rotation;
					meshCollider.sharedMesh = meshFilter.sharedMesh;
					value.Add(meshCollider);
				}
			}
			rb._colliders = value.ToArray();
			if (!flag)
			{
				return false;
			}
			Transform[] componentsInChildren2 = rendererGobj.GetComponentsInChildren<Transform>(includeInactive: true);
			for (int j = 0; j < componentsInChildren2.Length; j++)
			{
				componentsInChildren2[j].gameObject.isStatic = true;
			}
			return true;
		}
	}

	void IDelayedExecListener.OnDelayedAction(int contextId)
