public class GrabbyTentacleController : MonoBehaviour
{
	[SerializeField]
	private TentacleTracker[] tentacles;

	[SerializeField]
	private BoxCollider grabRegion;

	[SerializeField]
	private float minRetryDelay = 1f;

	[SerializeField]
	private float maxRetryDelay = 2f;

	private float nextAttemptTimestamp;

	private readonly HashSet<int> grabbedBefore = new HashSet<int>();

	private readonly List<VRRig> candidateBuffer = new List<VRRig>(16);

	private readonly List<VRRig> freshCandidates = new List<VRRig>(16);

	private void OnEnable()
	{
		if (tentacles != null)
		{
			_ = tentacles.Length;
		}
		nextAttemptTimestamp = 0f;
		grabbedBefore.Clear();
		if (GrabbyTentacleNetworking.Instance != null)
		{
			GrabbyTentacleNetworking.Instance.Register(this);
		}
		else
		{
			UnityEngine.Debug.LogError("[GrabbyTentacleController] No GrabbyTentacleNetworking.Instance at OnEnable - is the main scene loaded?");
		}
	}

	private void OnDisable()
	{
		if (GrabbyTentacleNetworking.Instance != null)
		{
			GrabbyTentacleNetworking.Instance.Unregister(this);
		}
	}

	private void Update()
	{
		if ((PhotonNetwork.InRoom && (!PhotonNetwork.IsMasterClient || GrabbyTentacleNetworking.Instance == null)) || tentacles == null || tentacles.Length == 0 || grabRegion == null)
		{
			return;
		}
		for (int i = 0; i < tentacles.Length; i++)
		{
			if (nextAttemptTimestamp > Time.time)
			{
				break;
			}
			TentacleTracker tentacleTracker = tentacles[i];
			if (tentacleTracker == null || tentacleTracker.gameObject.activeSelf)
			{
				continue;
			}
			nextAttemptTimestamp = Time.time + UnityEngine.Random.Range(minRetryDelay, maxRetryDelay);
			Player player = PickTarget();
			if (player != null)
			{
				grabbedBefore.Add(player.ActorNumber);
				if (PhotonNetwork.InRoom)
				{
					GrabbyTentacleNetworking.Instance.SendGrab(i, player);
				}
				else
				{
					OnGrabReceived(i, VRRig.LocalRig, isLocalPlayer: true);
				}
			}
		}
	}

	private Player PickTarget()
	{
		candidateBuffer.Clear();
		freshCandidates.Clear();
		IReadOnlyList<VRRig> activeRigs = VRRigCache.ActiveRigs;
		for (int i = 0; i < activeRigs.Count; i++)
		{
			VRRig vRRig = activeRigs[i];
			if (vRRig == null || vRRig.Creator == null || vRRig.Creator.IsNull || IsRigCurrentlyGrabbed(vRRig))
			{
				continue;
			}
			UnityEngine.Vector3 vector = ((vRRig.head != null && vRRig.head.rigTarget != null) ? vRRig.head.rigTarget.position : vRRig.transform.position);
			if (!(grabRegion.ClosestPoint(vector) != vector))
			{
				candidateBuffer.Add(vRRig);
				if (!grabbedBefore.Contains(vRRig.Creator.ActorNumber))
				{
					freshCandidates.Add(vRRig);
				}
			}
		}
		List<VRRig> list = ((freshCandidates.Count > 0) ? freshCandidates : candidateBuffer);
		if (list.Count == 0)
		{
			return null;
		}
		VRRig vRRig2 = list[UnityEngine.Random.Range(0, list.Count)];
		return PhotonNetwork.CurrentRoom?.GetPlayer(vRRig2.Creator.ActorNumber);
	}

	private bool IsRigCurrentlyGrabbed(VRRig rig)
	{
		for (int i = 0; i < tentacles.Length; i++)
		{
			TentacleTracker tentacleTracker = tentacles[i];
			if (tentacleTracker != null && tentacleTracker.gameObject.activeSelf && tentacleTracker.currentTargetRig == rig)
			{
				return true;
			}
		}
		return false;
	}

	public void OnGrabReceived(int tentacleIndex, VRRig targetRig, bool isLocalPlayer)
	{
		if (tentacles != null && tentacleIndex >= 0 && tentacleIndex < tentacles.Length)
		{
			TentacleTracker tentacleTracker = tentacles[tentacleIndex];
			if (!(tentacleTracker == null))
			{
				tentacleTracker.BeginGrab(targetRig, isLocalPlayer);
			}
		}
	}
}
public class GrabbyTentacleNetworking : MonoBehaviourPunCallbacks
{
	[SerializeField]
	private PhotonView tablePhotonView;

	private GrabbyTentacleController registeredController;

	public static GrabbyTentacleNetworking Instance { get; private set; }

	private void Awake()
	{
		if (Instance != null && Instance != this)
		{
			UnityEngine.Debug.LogWarning("[GrabbyTentacleNetworking] duplicate instance on " + base.name);
			return;
		}
		Instance = this;
		if (tablePhotonView == null)
		{
			tablePhotonView = GetComponent<PhotonView>();
		}
	}

	private void OnDestroy()
	{
		if (Instance == this)
		{
			Instance = null;
		}
	}

	public void Register(GrabbyTentacleController controller)
	{
		registeredController = controller;
	}

	public void Unregister(GrabbyTentacleController controller)
	{
		if (registeredController == controller)
		{
			registeredController = null;
		}
	}

	public void SendGrab(int tentacleIndex, Player targetPlayer)
	{
		if (PhotonNetwork.IsMasterClient && !(tablePhotonView == null) && targetPlayer != null)
		{
			tablePhotonView.RPC("ApplyTargetRPC", RpcTarget.All, tentacleIndex, targetPlayer);
		}
	}

	[PunRPC]
	public void ApplyTargetRPC(int tentacleIndex, Player targetPlayer, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "ApplyTargetRPC");
		if (info.Sender != null && info.Sender.IsMasterClient && targetPlayer != null && !(registeredController == null) && VRRigCache.Instance.TryGetVrrig(targetPlayer, out var playerRig) && !(playerRig == null))
		{
			bool isLocalPlayer = targetPlayer.ActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
			registeredController.OnGrabReceived(tentacleIndex, playerRig.Rig, isLocalPlayer);
		}
	}
}
public class TentacleTracker : MonoBehaviour
{
	[SerializeField]
	private Transform anchorPoint;

	[SerializeField]
	private Transform anchorRefPoint;

	[SerializeField]
	private Transform playerRefPoint;

	[SerializeField]
	private Animator animator;

	[SerializeField]
	private GorillaClimbable climbable;

	[SerializeField]
	private string[] testTriggers;

	private List<string> testTriggersRemaining = new List<string>();

	private bool tracking = true;

	private bool currentTargetIsLocal;

	public VRRig currentTargetRig { get; private set; }

	private void OnEnable()
	{
		tracking = true;
		testTriggersRemaining.Clear();
		testTriggersRemaining.AddRange(testTriggers);
		currentTargetRig = null;
		currentTargetIsLocal = false;
	}

	public void BeginGrab(VRRig targetRig, bool isLocalPlayer)
	{
		if (!(targetRig == null))
		{
			base.gameObject.SetActive(value: true);
			tracking = true;
			currentTargetRig = targetRig;
			currentTargetIsLocal = isLocalPlayer;
			testTriggersRemaining.Clear();
			testTriggersRemaining.AddRange(testTriggers);
		}
	}

	public void Anim_OnReachEnded()
	{
		animator.SetTrigger(testTriggersRemaining[0]);
		testTriggersRemaining.RemoveAt(0);
		if (currentTargetIsLocal)
		{
			GTPlayer.Instance.BeginClimbing(climbable, EquipmentInteractor.instance.BodyClimber);
			EquipmentInteractor.instance.BodyClimber.SetCanRelease(canRelease: false);
			tracking = false;
		}
	}

	private void Update()
	{
		if (tracking)
		{
			UnityEngine.Vector3 vector = ((currentTargetRig != null && !currentTargetIsLocal) ? currentTargetRig.head.rigTarget.position : GTPlayer.Instance.mainCamera.transform.position);
			UnityEngine.Vector3 vector2 = vector - anchorPoint.position;
			float magnitude = vector2.magnitude;
			if (!(magnitude < 0.001f))
			{
				UnityEngine.Vector3 forward = vector2 / magnitude;
				UnityEngine.Vector3 normalized = (playerRefPoint.localPosition - anchorRefPoint.localPosition).normalized;
				base.transform.rotation = UnityEngine.Quaternion.LookRotation(forward) * UnityEngine.Quaternion.Inverse(UnityEngine.Quaternion.LookRotation(normalized));
				base.transform.position += vector - playerRefPoint.position;
			}
		}
	}

	public void TestDrop()
	{
		if (currentTargetRig == null || currentTargetIsLocal)
		{
			EquipmentInteractor.instance.BodyClimber.SetCanRelease(canRelease: true);
			GTPlayer.Instance.EndClimbing(EquipmentInteractor.instance.BodyClimber, startingNewClimb: false);
		}
		currentTargetRig = null;
		currentTargetIsLocal = false;
		tracking = true;
	}

	public void TestDisappear()
	{
		base.gameObject.SetActive(value: false);
	}
}
