public class AudioAnimator : MonoBehaviour
{
	[Serializable]
	private struct AudioTarget
	{
		public AudioSource audioSource;

		public AnimationCurve pitchCurve;

		public AnimationCurve volumeCurve;

		[NonSerialized]
		public float baseVolume;

		public float riseSmoothing;

		public float lowerSmoothing;
	}

	private bool didInitBaseVolume;

	[SerializeField]
	private AudioTarget[] targets;

	private void Start()
	{
		if (!didInitBaseVolume)
		{
			InitBaseVolume();
		}
	}

	private void InitBaseVolume()
	{
		for (int i = 0; i < targets.Length; i++)
		{
			targets[i].baseVolume = targets[i].audioSource.volume;
		}
		didInitBaseVolume = true;
	}

	public void UpdateValue(float value, bool ignoreSmoothing = false)
	{
		UpdatePitchAndVolume(value, value, ignoreSmoothing);
	}

	public void UpdatePitchAndVolume(float pitchValue, float volumeValue, bool ignoreSmoothing = false)
	{
		if (!didInitBaseVolume)
		{
			InitBaseVolume();
		}
		for (int i = 0; i < targets.Length; i++)
		{
			AudioTarget audioTarget = targets[i];
			float p = audioTarget.pitchCurve.Evaluate(pitchValue);
			float pitch = Mathf.Pow(1.05946f, p);
			audioTarget.audioSource.pitch = pitch;
			float num = audioTarget.volumeCurve.Evaluate(volumeValue);
			float volume = audioTarget.audioSource.volume;
			float num2 = audioTarget.baseVolume * num;
			if (ignoreSmoothing)
			{
				audioTarget.audioSource.volume = num2;
			}
			else if (volume > num2)
			{
				audioTarget.audioSource.volume = Mathf.MoveTowards(audioTarget.audioSource.volume, audioTarget.baseVolume * num, (1f - audioTarget.lowerSmoothing) * audioTarget.baseVolume * Time.deltaTime * 90f);
			}
			else
			{
				audioTarget.audioSource.volume = Mathf.MoveTowards(audioTarget.audioSource.volume, audioTarget.baseVolume * num, (1f - audioTarget.riseSmoothing) * audioTarget.baseVolume * Time.deltaTime * 90f);
			}
		}
	}
}
public class PlayerSpeedBasedAudio : MonoBehaviour
{
	[SerializeField]
	private float minVolumeSpeed;

	[SerializeField]
	private float fullVolumeSpeed;

	[SerializeField]
	private float fadeTime;

	[SerializeField]
	private AudioSource audioSource;

	[SerializeField]
	private XSceneRef localPlayerVelocityEstimator;

	private GorillaVelocityEstimator velocityEstimator;

	private float baseVolume;

	private float fadeRate;

	private float currentFadeLevel;

	private void Start()
	{
		fadeRate = 1f / fadeTime;
		baseVolume = audioSource.volume;
		localPlayerVelocityEstimator.TryResolve(out velocityEstimator);
	}

	private void Update()
	{
		currentFadeLevel = Mathf.MoveTowards(currentFadeLevel, Mathf.InverseLerp(minVolumeSpeed, fullVolumeSpeed, velocityEstimator.linearVelocity.magnitude), fadeRate * Time.deltaTime);
		if (baseVolume == 0f || currentFadeLevel == 0f)
		{
			audioSource.volume = 0.0001f;
		}
		else
		{
			audioSource.volume = baseVolume * currentFadeLevel;
		}
	}
}
public class PlaySoundOnEnable : MonoBehaviour
{
	[SerializeField]
	private AudioSource _source;

	[SerializeField]
	private AudioClip[] _clips;

	[SerializeField]
	private bool _loop;

	[SerializeField]
	private UnityEngine.Vector2 _loopDelay;

	private void Reset()
	{
		_source = GetComponent<AudioSource>();
		if ((bool)_source)
		{
			_source.playOnAwake = false;
		}
	}

	private void OnEnable()
	{
		Play();
	}

	private void OnDisable()
	{
		Stop();
	}

	public void Play()
	{
		if (_loop && _clips.Length == 1 && _loopDelay == UnityEngine.Vector2.zero)
		{
			_source.clip = _clips[0];
			_source.loop = true;
			_source.GTPlay();
			return;
		}
		_source.loop = false;
		if (_loop)
		{
			StartCoroutine(DoLoop());
			return;
		}
		_source.clip = _clips[UnityEngine.Random.Range(0, _clips.Length)];
		_source.GTPlay();
	}

	private IEnumerator DoLoop()
	{
		while (base.enabled)
		{
			_source.clip = _clips[UnityEngine.Random.Range(0, _clips.Length)];
			_source.GTPlay();
			while (_source.isPlaying)
			{
				yield return null;
			}
			float num = UnityEngine.Random.Range(_loopDelay.x, _loopDelay.y);
			if (num > 0f)
			{
				float waitEndTime = Time.time + num;
				while (Time.time < waitEndTime)
				{
					yield return null;
				}
			}
		}
	}

	public void Stop()
	{
		_source.GTStop();
		_source.loop = false;
	}
}
public class ArcingProjectileLauncher : ElfLauncher
{
	[SerializeField]
	private UnityEngine.Vector2 fireAngleLimits = new UnityEngine.Vector3(-75f, 75f);

	[SerializeField]
	private AnimationCurve angleVelocityMultiplier;

	protected override void ShootShared(UnityEngine.Vector3 origin, UnityEngine.Vector3 direction)
	{
		shootAudio.Play();
		UnityEngine.Vector3 lossyScale = base.transform.lossyScale;
		float num = UnityEngine.Vector3.Dot(direction, UnityEngine.Vector3.up);
		UnityEngine.Vector3 vector = ((!((double)num > 0.99999) && !((double)num < -0.99999)) ? UnityEngine.Vector3.ProjectOnPlane(direction, UnityEngine.Vector3.up) : ((!(parentHoldable.myRig != null)) ? UnityEngine.Vector3.forward : parentHoldable.myRig.transform.forward));
		vector.Normalize();
		UnityEngine.Vector3 axis = UnityEngine.Vector3.Cross(vector, UnityEngine.Vector3.up);
		float num2 = UnityEngine.Vector3.SignedAngle(vector, direction, axis);
		float num3 = angleVelocityMultiplier.Evaluate(num2);
		float num4 = Mathf.Clamp(num2, fireAngleLimits.x, fireAngleLimits.y);
		float num5 = Mathf.Sin(num4 * (MathF.PI / 180f));
		float num6 = Mathf.Cos(num4 * (MathF.PI / 180f));
		UnityEngine.Vector3 vector2 = num5 * UnityEngine.Vector3.up + num6 * vector;
		vector2.Normalize();
		UnityEngine.Vector3 vector3 = vector2 * (muzzleVelocity * lossyScale.x * num3);
		GameObject gameObject = ObjectPools.instance.Instantiate(elfProjectileHash);
		IProjectile component = gameObject.GetComponent<IProjectile>();
		if (component != null)
		{
			component.Launch(origin, UnityEngine.Quaternion.LookRotation(vector, UnityEngine.Vector3.up), vector3, 1f, parentHoldable.myRig);
			return;
		}
		gameObject.transform.position = origin;
		gameObject.transform.rotation = UnityEngine.Quaternion.LookRotation(direction);
		gameObject.transform.localScale = lossyScale;
		gameObject.GetComponent<Rigidbody>().linearVelocity = vector3;
	}
}
public class AudioFader : MonoBehaviour
{
	[SerializeField]
	private AudioSource audioToFade;

	[SerializeField]
	private AudioSource outro;

	[SerializeField]
	private float fadeInDuration = 0.3f;

	[SerializeField]
	private float fadeOutDuration = 0.3f;

	[SerializeField]
	private float maxVolume = 1f;

	private float currentVolume;

	private float targetVolume;

	private float currentFadeSpeed;

	private float fadeInSpeed;

	private float fadeOutSpeed;

	private void Start()
	{
		fadeInSpeed = maxVolume / fadeInDuration;
		fadeOutSpeed = maxVolume / fadeOutDuration;
	}

	public void FadeIn()
	{
		targetVolume = maxVolume;
		if (fadeInDuration > 0f)
		{
			base.enabled = true;
			currentFadeSpeed = fadeInSpeed;
		}
		else
		{
			currentVolume = maxVolume;
		}
		audioToFade.volume = currentVolume;
		if (!audioToFade.isPlaying)
		{
			audioToFade.GTPlay();
		}
	}

	public void FadeOut()
	{
		targetVolume = 0f;
		if (fadeOutDuration > 0f)
		{
			base.enabled = true;
			currentFadeSpeed = fadeOutSpeed;
		}
		else
		{
			currentVolume = 0f;
			if (audioToFade.isPlaying)
			{
				audioToFade.Stop();
			}
		}
		if (outro != null && currentVolume > 0f)
		{
			outro.volume = currentVolume;
			outro.GTPlay();
		}
	}

	private void Update()
	{
		currentVolume = Mathf.MoveTowards(currentVolume, targetVolume, currentFadeSpeed * Time.deltaTime);
		audioToFade.volume = currentVolume;
		if (currentVolume == targetVolume)
		{
			base.enabled = false;
			if (currentVolume == 0f && audioToFade.isPlaying)
			{
				audioToFade.Stop();
			}
		}
	}
}
public class ClackerCosmetic : MonoBehaviour
{
	private struct PerArmData
	{
		public ClackerCosmetic parent;

		public Transform transform;

		public UnityEngine.Vector3 velocity;

		public UnityEngine.Vector3 lastWorldPosition;

		public void UpdateArm()
		{
			UnityEngine.Vector3 target = transform.TransformPoint(parent.LocalCenterOfMass);
			UnityEngine.Vector3 vector = lastWorldPosition + velocity * Time.deltaTime * parent.drag;
			UnityEngine.Vector3 vector2 = transform.parent.TransformDirection(parent.LocalRotationAxis);
			UnityEngine.Vector3 current = transform.position + (vector - transform.position).ProjectOntoPlane(vector2).normalized * parent.centerOfMassRadius;
			current = UnityEngine.Vector3.MoveTowards(current, target, parent.localFriction * Time.deltaTime);
			velocity = (current - lastWorldPosition) / Time.deltaTime;
			velocity += UnityEngine.Vector3.down * parent.gravity * Time.deltaTime;
			lastWorldPosition = current;
			transform.rotation = UnityEngine.Quaternion.LookRotation(vector2, current - transform.position) * parent.RotationCorrection;
			lastWorldPosition = transform.TransformPoint(parent.LocalCenterOfMass);
		}

		public void SetPosition(UnityEngine.Vector3 newPosition)
		{
			UnityEngine.Vector3 forward = transform.parent.TransformDirection(parent.LocalRotationAxis);
			transform.rotation = UnityEngine.Quaternion.LookRotation(forward, newPosition - transform.position) * parent.RotationCorrection;
			lastWorldPosition = transform.TransformPoint(parent.LocalCenterOfMass);
		}
	}

	[SerializeField]
	private TransferrableObject parentHoldable;

	[SerializeField]
	private Transform clackerArm1;

	[SerializeField]
	private Transform clackerArm2;

	[SerializeField]
	private UnityEngine.Vector3 LocalCenterOfMass;

	[SerializeField]
	private UnityEngine.Vector3 LocalRotationAxis;

	[SerializeField]
	private UnityEngine.Vector3 RotationCorrectionEuler;

	[SerializeField]
	private float drag;

	[SerializeField]
	private float gravity;

	[SerializeField]
	private float localFriction;

	[SerializeField]
	private float minimumClackSpeed;

	[SerializeField]
	private SoundBankPlayer lightClackAudio;

	[SerializeField]
	private float mediumClackSpeed;

	[SerializeField]
	private SoundBankPlayer mediumClackAudio;

	[SerializeField]
	private float heavyClackSpeed;

	[SerializeField]
	private SoundBankPlayer heavyClackAudio;

	[SerializeField]
	private float collisionDistance;

	private float centerOfMassRadius;

	[SerializeField]
	private float pushApartStrength;

	private PerArmData arm1;

	private PerArmData arm2;

	private UnityEngine.Quaternion RotationCorrection;

	private void Start()
	{
		LocalRotationAxis = LocalRotationAxis.normalized;
		arm1.parent = this;
		arm2.parent = this;
		arm1.transform = clackerArm1;
		arm2.transform = clackerArm2;
		arm1.lastWorldPosition = clackerArm1.transform.TransformPoint(LocalCenterOfMass);
		arm2.lastWorldPosition = clackerArm2.transform.TransformPoint(LocalCenterOfMass);
		centerOfMassRadius = LocalCenterOfMass.magnitude;
		RotationCorrection = UnityEngine.Quaternion.Euler(RotationCorrectionEuler);
	}

	private void Update()
	{
		UnityEngine.Vector3 lastWorldPosition = arm1.lastWorldPosition;
		arm1.UpdateArm();
		arm2.UpdateArm();
		UnityEngine.Vector3 eulerAngles = clackerArm1.transform.eulerAngles;
		UnityEngine.Vector3 eulerAngles2 = clackerArm2.transform.eulerAngles;
		Mathf.DeltaAngle(eulerAngles.y, eulerAngles2.y);
		if (!(arm1.lastWorldPosition - arm2.lastWorldPosition).IsShorterThan(collisionDistance))
		{
			return;
		}
		float sqrMagnitude = (arm1.velocity - arm2.velocity).sqrMagnitude;
		if (parentHoldable.InHand())
		{
			if (sqrMagnitude > heavyClackSpeed * heavyClackSpeed)
			{
				heavyClackAudio.Play();
			}
			else if (sqrMagnitude > mediumClackSpeed * mediumClackSpeed)
			{
				mediumClackAudio.Play();
			}
			else if (sqrMagnitude > minimumClackSpeed * minimumClackSpeed)
			{
				lightClackAudio.Play();
			}
		}
		UnityEngine.Vector3 vector = (arm1.lastWorldPosition + arm2.lastWorldPosition) / 2f;
		UnityEngine.Vector3 vector2 = (arm1.lastWorldPosition - arm2.lastWorldPosition).normalized * (collisionDistance + 0.001f) / 2f;
		UnityEngine.Vector3 vector3 = vector + vector2;
		UnityEngine.Vector3 vector4 = vector - vector2;
		if ((lastWorldPosition - vector3).IsLongerThan(lastWorldPosition - vector4))
		{
			vector2 = -vector2;
		}
		arm1.SetPosition(vector + vector2);
		arm2.SetPosition(vector - vector2);
		ref UnityEngine.Vector3 velocity = ref arm1.velocity;
		ref UnityEngine.Vector3 velocity2 = ref arm2.velocity;
		UnityEngine.Vector3 velocity3 = arm2.velocity;
		UnityEngine.Vector3 velocity4 = arm1.velocity;
		velocity = velocity3;
		velocity2 = velocity4;
		UnityEngine.Vector3 vector5 = (arm1.lastWorldPosition - arm2.lastWorldPosition).normalized * pushApartStrength * Mathf.Sqrt(sqrMagnitude);
		arm1.velocity += vector5;
		arm2.velocity -= vector5;
	}
}
public class CosmeticFan : MonoBehaviour
{
	[SerializeField]
	private UnityEngine.Vector3 axis;

	[SerializeField]
	private float spinUpDuration = 0.3f;

	[SerializeField]
	private float spinDownDuration = 0.3f;

	[SerializeField]
	private float maxSpeed = 360f;

	private float currentSpeed;

	private float targetSpeed;

	private float currentAccelRate;

	private float spinUpRate;

	private float spinDownRate;

	private void Start()
	{
		spinUpRate = maxSpeed / spinUpDuration;
		spinDownRate = maxSpeed / spinDownDuration;
	}

	public void Run()
	{
		targetSpeed = maxSpeed;
		if (spinUpDuration > 0f)
		{
			base.enabled = true;
			currentAccelRate = spinUpRate;
		}
		else
		{
			currentSpeed = maxSpeed;
		}
		base.enabled = true;
	}

	public void Stop()
	{
		targetSpeed = 0f;
		if (spinDownDuration > 0f)
		{
			base.enabled = true;
			currentAccelRate = spinDownRate;
		}
		else
		{
			currentSpeed = 0f;
		}
	}

	public void InstantStop()
	{
		targetSpeed = 0f;
		currentSpeed = 0f;
		base.enabled = false;
	}

	private void Update()
	{
		currentSpeed = Mathf.MoveTowards(currentSpeed, targetSpeed, currentAccelRate * Time.deltaTime);
		base.transform.localRotation = base.transform.localRotation * UnityEngine.Quaternion.AngleAxis(currentSpeed * Time.deltaTime, axis);
		if (currentSpeed == 0f && targetSpeed == 0f)
		{
			base.enabled = false;
		}
	}
}
