public class CrankableToyCarDeployed : MonoBehaviour
{
	[SerializeField]
	private Rigidbody rb;

	[SerializeField]
	private FakeWheelDriver wheelDriver;

	[SerializeField]
	private UnityEngine.Vector3 maxThrust;

	[SerializeField]
	private AnimationCurve thrustCurve;

	private float startedAtTimestamp;

	private float expiresAtTimestamp;

	private CrankableToyCarHoldable holdable;

	[SerializeField]
	private AudioSource drivingAudio;

	[SerializeField]
	private AudioSource offGroundDrivingAudio;

	private bool isRemote;

	public void Deploy(CrankableToyCarHoldable holdable, UnityEngine.Vector3 launchPos, UnityEngine.Quaternion launchRot, UnityEngine.Vector3 releaseVel, float lifetime, bool isRemote = false)
	{
		this.holdable = holdable;
		holdable.OnCarDeployed();
		base.transform.position = launchPos;
		base.transform.rotation = launchRot;
		base.transform.localScale = holdable.transform.lossyScale;
		rb.linearVelocity = releaseVel;
		startedAtTimestamp = Time.time;
		expiresAtTimestamp = Time.time + lifetime;
		this.isRemote = isRemote;
	}

	private void Update()
	{
		if (!isRemote && Time.time > expiresAtTimestamp)
		{
			if (holdable != null)
			{
				holdable.OnCarReturned();
			}
			return;
		}
		if (!wheelDriver.hasCollision)
		{
			expiresAtTimestamp -= Time.deltaTime;
			if (!offGroundDrivingAudio.isPlaying)
			{
				offGroundDrivingAudio.GTPlay();
				drivingAudio.Stop();
			}
		}
		else if (!drivingAudio.isPlaying)
		{
			drivingAudio.GTPlay();
			offGroundDrivingAudio.Stop();
		}
		float time = Mathf.InverseLerp(startedAtTimestamp, expiresAtTimestamp, Time.time);
		float num = thrustCurve.Evaluate(time);
		wheelDriver.SetThrust(maxThrust * num);
	}
}
public class CrankableToyCarHoldable : TransferrableObject
{
	[SerializeField]
	private TransferrableObjectHoldablePart_Crank crank;

	[SerializeField]
	private CrankableToyCarDeployed deployedCar;

	[SerializeField]
	private GameObject deployablePart;

	[SerializeField]
	private GameObject disabledWhileDeployed;

	[SerializeField]
	private float crankAnglePerClick;

	[SerializeField]
	private float maxCrankStrength;

	[SerializeField]
	private float minClickPitch;

	[SerializeField]
	private float maxClickPitch;

	[SerializeField]
	private float minLifetime;

	[SerializeField]
	private float maxLifetime;

	[SerializeField]
	private SoundBankPlayer clickSound;

	[SerializeField]
	private SoundBankPlayer overCrankedSound;

	[SerializeField]
	private float crankHapticStrength = 0.1f;

	[SerializeField]
	private float crankHapticDuration = 0.05f;

	[SerializeField]
	private float overcrankHapticStrength = 0.8f;

	[SerializeField]
	private float overcrankHapticDuration = 0.05f;

	private float currentCrankStrength;

	private float currentCrankClickAmount;

	private RubberDuckEvents _events;

	protected override void Start()
	{
		base.Start();
		crank.SetOnCrankedCallback(OnCranked);
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		if (base.gameObject.activeInHierarchy)
		{
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			}
			NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
			if (netPlayer != null && _events != null)
			{
				_events.Init(netPlayer);
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnDeployRPC);
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
			}
			itemState &= (ItemStates)(-2);
		}
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		if (_events != null)
		{
			_events.Dispose();
		}
	}

	protected override void LateUpdateReplicated()
	{
		base.LateUpdateReplicated();
		if (itemState.HasFlag(ItemStates.State0))
		{
			if (!deployablePart.activeSelf)
			{
				OnCarDeployed();
			}
		}
		else if (deployablePart.activeSelf)
		{
			OnCarReturned();
		}
	}

	private void OnCranked(float deltaAngle)
	{
		currentCrankStrength += Mathf.Abs(deltaAngle);
		currentCrankClickAmount += deltaAngle;
		if (!(Mathf.Abs(currentCrankClickAmount) > crankAnglePerClick))
		{
			return;
		}
		if (currentCrankStrength >= maxCrankStrength)
		{
			overCrankedSound.Play();
			VRRig vRRig = ownerRig;
			if ((object)vRRig != null && vRRig.isLocal)
			{
				GorillaTagger.Instance.StartVibration(InRightHand(), overcrankHapticStrength, overcrankHapticDuration);
			}
		}
		else
		{
			float value = Mathf.Lerp(minClickPitch, maxClickPitch, Mathf.InverseLerp(0f, maxCrankStrength, currentCrankStrength));
			SoundBankPlayer soundBankPlayer = clickSound;
			float? pitchOverride = value;
			soundBankPlayer.Play(null, pitchOverride);
			VRRig vRRig2 = ownerRig;
			if ((object)vRRig2 != null && vRRig2.isLocal)
			{
				GorillaTagger.Instance.StartVibration(InRightHand(), crankHapticStrength, crankHapticDuration);
			}
		}
		currentCrankClickAmount = 0f;
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (VRRigCache.Instance.localRig.Rig != ownerRig)
		{
			return false;
		}
		if (currentCrankStrength == 0f)
		{
			return true;
		}
		bool isLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
		GorillaVelocityTracker interactPointVelocityTracker = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeftHand);
		UnityEngine.Vector3 vector = base.transform.TransformPoint(UnityEngine.Vector3.zero);
		UnityEngine.Quaternion rotation = base.transform.rotation;
		UnityEngine.Vector3 averageVelocity = interactPointVelocityTracker.GetAverageVelocity(worldSpace: true);
		float num = Mathf.Lerp(minLifetime, maxLifetime, Mathf.Clamp01(Mathf.InverseLerp(0f, maxCrankStrength, currentCrankStrength)));
		DeployCarLocal(vector, rotation, averageVelocity, num);
		if (PhotonNetwork.InRoom)
		{
			_events.Activate.RaiseOthers(BitPackUtils.PackWorldPosForNetwork(vector), BitPackUtils.PackQuaternionForNetwork(rotation), BitPackUtils.PackWorldPosForNetwork(averageVelocity * 100f), num);
		}
		currentCrankStrength = 0f;
		return true;
	}

	private void DeployCarLocal(UnityEngine.Vector3 launchPos, UnityEngine.Quaternion launchRot, UnityEngine.Vector3 releaseVel, float lifetime, bool isRemote = false)
	{
		if (disabledWhileDeployed.activeSelf)
		{
			deployedCar.Deploy(this, launchPos, launchRot, releaseVel, lifetime, isRemote);
		}
	}

	private void OnDeployRPC(int sender, int receiver, object[] args, PhotonMessageInfoWrapped info)
	{
		if ((bool)this && sender == receiver && info.senderID == ownerRig.creator.ActorNumber)
		{
			MonkeAgent.IncrementRPCCall(info, "OnDeployRPC");
			UnityEngine.Vector3 v = BitPackUtils.UnpackWorldPosFromNetwork((long)args[0]);
			UnityEngine.Quaternion q = BitPackUtils.UnpackQuaternionFromNetwork((int)args[1]);
			UnityEngine.Vector3 v2 = BitPackUtils.UnpackWorldPosFromNetwork((long)args[2]) / 100f;
			float lifetime = (float)args[3];
			if (v.IsValid(10000f) && q.IsValid() && v2.IsValid(10000f))
			{
				DeployCarLocal(v, q, v2, lifetime, isRemote: true);
			}
		}
	}

	public void OnCarDeployed()
	{
		itemState |= ItemStates.State0;
		deployablePart.SetActive(value: true);
		disabledWhileDeployed.SetActive(value: false);
	}

	public void OnCarReturned()
	{
		itemState &= (ItemStates)(-2);
		deployablePart.SetActive(value: false);
		disabledWhileDeployed.SetActive(value: true);
		clickSound.RestartSequence();
	}
}
public class Crossbow : ProjectileWeapon
{
	[SerializeField]
	private Transform launchPosition;

	[SerializeField]
	private float launchSpeed;

	[SerializeField]
	private Animator animator;

	[SerializeField]
	private float crankTotalDegreesToReload;

	[SerializeField]
	private TransferrableObjectHoldablePart_Crank[] cranks;

	[SerializeField]
	private MeshRenderer dummyProjectile;

	[SerializeField]
	private AudioSource reloadAudio;

	[SerializeField]
	private AudioClip reloadComplete_audioClip;

	[SerializeField]
	private float crankSoundContinueDuration = 0.1f;

	[SerializeField]
	private float crankSoundDegreesThreshold = 0.1f;

	private AnimHashId FireHashID = "Fire";

	private AnimHashId ReloadFractionHashID = "ReloadFraction";

	private float totalCrankDegrees;

	private float loadFraction;

	private float playingCrankSoundUntilTimestamp;

	private float crankSoundDegrees;

	private bool wasPressingTrigger;

	protected override void Awake()
	{
		base.Awake();
		TransferrableObjectHoldablePart_Crank[] array = cranks;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetOnCrankedCallback(OnCrank);
		}
		SetReloadFraction(0f);
	}

	public void SetReloadFraction(float newFraction)
	{
		loadFraction = Mathf.Clamp01(newFraction);
		animator.SetFloat(ReloadFractionHashID, loadFraction);
		if (loadFraction == 1f && !dummyProjectile.enabled)
		{
			shootSfx.GTPlayOneShot(reloadComplete_audioClip);
			dummyProjectile.enabled = true;
		}
		else if (loadFraction < 1f && dummyProjectile.enabled)
		{
			dummyProjectile.enabled = false;
		}
	}

	private void OnCrank(float degrees)
	{
		if (loadFraction != 1f)
		{
			totalCrankDegrees += degrees;
			crankSoundDegrees += degrees;
			if (Mathf.Abs(crankSoundDegrees) > crankSoundDegreesThreshold)
			{
				playingCrankSoundUntilTimestamp = Time.time + crankSoundContinueDuration;
				crankSoundDegrees = 0f;
			}
			if (!reloadAudio.isPlaying && Time.time < playingCrankSoundUntilTimestamp)
			{
				reloadAudio.GTPlay();
			}
			SetReloadFraction(Mathf.Abs(totalCrankDegrees / crankTotalDegreesToReload));
			if (loadFraction >= 1f)
			{
				totalCrankDegrees = 0f;
			}
		}
	}

	protected override UnityEngine.Vector3 GetLaunchPosition()
	{
		return launchPosition.position;
	}

	protected override UnityEngine.Vector3 GetLaunchVelocity()
	{
		return launchPosition.forward * launchSpeed * base.myRig.scaleFactor;
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		if (!InHand())
		{
			wasPressingTrigger = false;
			return;
		}
		if ((InLeftHand() ? base.myRig.leftIndex.calcT : base.myRig.rightIndex.calcT) > 0.5f)
		{
			if (loadFraction == 1f && !wasPressingTrigger)
			{
				SetReloadFraction(0f);
				animator.SetTrigger(FireHashID);
				LaunchProjectile();
			}
			wasPressingTrigger = true;
		}
		else
		{
			wasPressingTrigger = false;
		}
		if (itemState.HasFlag(ItemStates.State0))
		{
			if (loadFraction < 1f)
			{
				itemState &= (ItemStates)(-2);
			}
		}
		else if (loadFraction == 1f)
		{
			itemState |= ItemStates.State0;
		}
	}

	protected override void LateUpdateReplicated()
	{
		base.LateUpdateReplicated();
		if (InHand())
		{
			if (itemState.HasFlag(ItemStates.State0))
			{
				SetReloadFraction(1f);
			}
			else if (loadFraction == 1f)
			{
				SetReloadFraction(0f);
			}
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		if (reloadAudio.isPlaying && Time.time > playingCrankSoundUntilTimestamp)
		{
			reloadAudio.GTStop();
		}
	}
}
public class DeployableObject : TransferrableObject
{
	[SerializeField]
	private GameObject _objectToDeploy;

	[SerializeField]
	private DeployedChild _child;

	[SerializeField]
	private GameObject[] _disabledWhileDeployed = new GameObject[0];

	[SerializeField]
	private SoundBankPlayer deploySound;

	[SerializeField]
	private PhotonSignal<long, int, long> _deploySignal = "_deploySignal";

	[SerializeField]
	private float _maxDeployDistance = 4f;

	[SerializeField]
	private float _maxThrowVelocity = 50f;

	[SerializeField]
	private UnityEvent _onDeploy;

	[SerializeField]
	private UnityEvent _onReturn;

	[SerializeField]
	private UnityEngine.Component[] _rigAwareObjects = new UnityEngine.Component[0];

	[SerializeField]
	private CallLimiter m_spamChecker = new CallLimiter(2, 1f);

	private VRRig m_VRRig;

	protected override void Awake()
	{
		_deploySignal.OnSignal += DeployRPC;
		base.Awake();
	}

	internal override void OnEnable()
	{
		_deploySignal.Enable();
		VRRig componentInParent = GetComponentInParent<VRRig>();
		for (int i = 0; i < _rigAwareObjects.Length; i++)
		{
			if (_rigAwareObjects[i] is IRigAware rigAware)
			{
				rigAware.SetRig(componentInParent);
			}
		}
		m_VRRig = componentInParent;
		m_VRRig.rigContainer.RigEvents.disableEvent.Add(new Action<RigContainer>(OnRigPreDisable));
		base.OnEnable();
		if (base.gameObject.activeInHierarchy)
		{
			itemState &= (ItemStates)(-2);
		}
	}

	internal override void OnDisable()
	{
		m_VRRig = null;
		_deploySignal.Disable();
		if (_objectToDeploy.activeSelf)
		{
			ReturnChild();
		}
		base.OnDisable();
	}

	private void OnRigPreDisable(RigContainer rc)
	{
		m_spamChecker.Reset();
		rc.RigEvents.disableEvent.Remove(new Action<RigContainer>(OnRigPreDisable));
	}

	protected override void OnDestroy()
	{
		_deploySignal.Dispose();
		base.OnDestroy();
	}

	protected override void LateUpdateReplicated()
	{
		base.LateUpdateReplicated();
		if (itemState.HasFlag(ItemStates.State0))
		{
			if (!_objectToDeploy.activeSelf)
			{
				DeployChild();
			}
		}
		else if (_objectToDeploy.activeSelf)
		{
			ReturnChild();
		}
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (VRRig.LocalRig != ownerRig)
		{
			return false;
		}
		bool isLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
		GorillaVelocityTracker interactPointVelocityTracker = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeftHand);
		Transform obj = base.transform;
		UnityEngine.Vector3 vector = obj.TransformPoint(UnityEngine.Vector3.zero);
		UnityEngine.Quaternion rotation = obj.rotation;
		UnityEngine.Vector3 averageVelocity = interactPointVelocityTracker.GetAverageVelocity(worldSpace: true);
		DeployLocal(vector, rotation, averageVelocity);
		_deploySignal.Raise(ReceiverGroup.Others, BitPackUtils.PackWorldPosForNetwork(vector), BitPackUtils.PackQuaternionForNetwork(rotation), BitPackUtils.PackWorldPosForNetwork(averageVelocity * 100f));
		return true;
	}

	protected virtual void DeployLocal(UnityEngine.Vector3 launchPos, UnityEngine.Quaternion launchRot, UnityEngine.Vector3 releaseVel, bool isRemote = false)
	{
		DisableWhileDeployed(active: true);
		_child.Deploy(this, launchPos, launchRot, releaseVel, isRemote);
	}

	private void DeployRPC(long packedPos, int packedRot, long packedVel, PhotonSignalInfo info)
	{
		if (info.sender != OwningPlayer())
		{
			return;
		}
		MonkeAgent.IncrementRPCCall(info, "DeployRPC");
		if (m_spamChecker.CheckCallTime(Time.unscaledTime))
		{
			UnityEngine.Vector3 v = BitPackUtils.UnpackWorldPosFromNetwork(packedPos);
			UnityEngine.Quaternion q = BitPackUtils.UnpackQuaternionFromNetwork(packedRot);
			UnityEngine.Vector3 inVel = BitPackUtils.UnpackWorldPosFromNetwork(packedVel) / 100f;
			if (v.IsValid(10000f) && q.IsValid() && m_VRRig.IsPositionInRange(v, _maxDeployDistance))
			{
				DeployLocal(v, q, m_VRRig.ClampVelocityRelativeToPlayerSafe(inVel, _maxThrowVelocity), isRemote: true);
			}
		}
	}

	private void DisableWhileDeployed(bool active)
	{
		if (!_disabledWhileDeployed.IsNullOrEmpty())
		{
			for (int i = 0; i < _disabledWhileDeployed.Length; i++)
			{
				_disabledWhileDeployed[i].SetActive(!active);
			}
		}
	}

	public void DeployChild()
	{
		itemState |= ItemStates.State0;
		_objectToDeploy.SetActive(value: true);
		DisableWhileDeployed(active: true);
		_onDeploy?.Invoke();
	}

	public void ReturnChild()
	{
		itemState &= (ItemStates)(-2);
		_objectToDeploy.SetActive(value: false);
		DisableWhileDeployed(active: false);
		_onReturn?.Invoke();
	}
}
public class DeployedChild : MonoBehaviour
{
	[SerializeField]
	private Rigidbody _rigidbody;

	[SerializeReference]
	private DeployableObject _parent;

	private bool _isRemote;

	public void Deploy(DeployableObject parent, UnityEngine.Vector3 launchPos, UnityEngine.Quaternion launchRot, UnityEngine.Vector3 releaseVel, bool isRemote = false)
	{
		_parent = parent;
		_parent.DeployChild();
		Transform obj = base.transform;
		obj.position = launchPos;
		obj.rotation = launchRot;
		obj.localScale = _parent.transform.lossyScale;
		_rigidbody.linearVelocity = releaseVel;
		_isRemote = isRemote;
	}

	public void ReturnToParent(float delay)
	{
		if (delay > 0f)
		{
			StartCoroutine(ReturnToParentDelayed(delay));
		}
		else if (_parent != null)
		{
			_parent.ReturnChild();
		}
	}

	private IEnumerator ReturnToParentDelayed(float delay)
	{
		float start = Time.time;
		while (Time.time < start + delay)
		{
			yield return null;
		}
		if (_parent != null)
		{
			_parent.ReturnChild();
		}
	}
}
public class DJDeckEqualizer : MonoBehaviour
{
	[SerializeField]
	private MeshRenderer display;

	[SerializeField]
	private AnimationCurve[] redTrackCurves;

	[SerializeField]
	private AnimationCurve[] greenTrackCurves;

	[SerializeField]
	private AudioSource[] redTracks;

	[SerializeField]
	private AudioSource[] greenTracks;

	private Material material;

	[SerializeField]
	private string inputColorProperty;

	private ShaderHashId inputColorHash;

	private void Start()
	{
		inputColorHash = inputColorProperty;
		material = display.material;
	}

	private void Update()
	{
		Color value = new Color
		{
			r = 0.25f,
			g = 0.25f,
			b = 0.5f
		};
		for (int i = 0; i < redTracks.Length; i++)
		{
			AudioSource audioSource = redTracks[i];
			if (audioSource.isPlaying)
			{
				value.r = Mathf.Lerp(0.25f, 1f, redTrackCurves[i].Evaluate(audioSource.time));
				break;
			}
		}
		for (int j = 0; j < greenTracks.Length; j++)
		{
			AudioSource audioSource2 = greenTracks[j];
			if (audioSource2.isPlaying)
			{
				value.g = Mathf.Lerp(0.25f, 1f, greenTrackCurves[j].Evaluate(audioSource2.time));
				break;
			}
		}
		material.SetColor(inputColorHash, value);
	}
}
public enum ScratchSoundType
{
	Pause,
	Resume,
	Forward,
	Back
}
public class DJScratchSoundPlayer : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private SoundBankPlayer scratchForward;

	[SerializeField]
	private SoundBankPlayer scratchBack;

	[SerializeField]
	private SoundBankPlayer scratchPause;

	[SerializeField]
	private SoundBankPlayer scratchResume;

	[SerializeField]
	private DJScratchtable scratchTableLeft;

	[SerializeField]
	private DJScratchtable scratchTableRight;

	private RubberDuckEvents _events;

	private VRRig myRig;

	public bool IsSpawned { get; set; }

	public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

	public void OnDespawn()
	{
	}

	private void OnEnable()
	{
		if (GTExt.IsNull(_events))
		{
			_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			NetPlayer netPlayer = ((!(myRig != null)) ? null : ((myRig.creator != null) ? myRig.creator : NetworkSystem.Instance.LocalPlayer));
			if (netPlayer != null)
			{
				_events.Init(netPlayer);
			}
		}
		_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnPlayEvent);
	}

	private void OnDisable()
	{
		if (_events.IsNotNull())
		{
			_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnPlayEvent);
			_events.Dispose();
			_events = null;
		}
	}

	public void OnSpawn(VRRig rig)
	{
		myRig = rig;
		if (!rig.isLocal)
		{
			scratchTableLeft.enabled = false;
			scratchTableRight.enabled = false;
		}
	}

	public void Play(ScratchSoundType type, bool isLeft)
	{
		if (myRig.isLocal)
		{
			PlayLocal(type, isLeft);
			_events.Activate.RaiseOthers((int)(type + (isLeft ? 100 : 0)));
		}
	}

	public void OnPlayEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		if (sender != target || info.senderID != myRig.creator.ActorNumber)
		{
			return;
		}
		if (args.Length != 1)
		{
			UnityEngine.Debug.LogError($"Invalid DJ Scratch Event - expected 1 arg, got {args.Length}");
			return;
		}
		int num = (int)args[0];
		bool flag = num >= 100;
		if (flag)
		{
			num -= 100;
		}
		ScratchSoundType scratchSoundType = (ScratchSoundType)num;
		if (scratchSoundType >= ScratchSoundType.Pause && scratchSoundType <= ScratchSoundType.Back)
		{
			PlayLocal(scratchSoundType, flag);
		}
	}

	public void PlayLocal(ScratchSoundType type, bool isLeft)
	{
		switch (type)
		{
		case ScratchSoundType.Pause:
			(isLeft ? scratchTableLeft : scratchTableRight).PauseTrack();
			scratchPause.Play();
			break;
		case ScratchSoundType.Resume:
			(isLeft ? scratchTableLeft : scratchTableRight).ResumeTrack();
			scratchResume.Play();
			break;
		case ScratchSoundType.Forward:
			scratchForward.Play();
			(isLeft ? scratchTableLeft : scratchTableRight).PauseTrack();
			break;
		case ScratchSoundType.Back:
			scratchBack.Play();
			(isLeft ? scratchTableLeft : scratchTableRight).PauseTrack();
			break;
		}
	}
}
public class DJScratchtable : MonoBehaviour
{
	[SerializeField]
	private bool isLeft;

	[SerializeField]
	private DJScratchSoundPlayer scratchPlayer;

	[SerializeField]
	private float scratchCooldown;

	[SerializeField]
	private float scratchMinAngle;

	[SerializeField]
	private AudioSource[] tracks;

	[SerializeField]
	private CosmeticFan turntableVisual;

	[SerializeField]
	private float trackDuration;

	[SerializeField]
	private float hapticStrength;

	[SerializeField]
	private float hapticDuration;

	private int lastSelectedTrack;

	private bool isPlaying;

	private bool isTouching;

	private UnityEngine.Quaternion firstTouchRotation;

	private float lastScratchSoundAngle;

	private float cantForwardScratchUntilTimestamp;

	private float cantBackScratchUntilTimestamp;

	private float pausedUntilTimestamp;

	public void SetPlaying(bool playing)
	{
		isPlaying = playing;
	}

	private void OnTriggerStay(Collider collider)
	{
		if (!base.enabled)
		{
			return;
		}
		GorillaTriggerColliderHandIndicator componentInParent = collider.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
		if (componentInParent == null)
		{
			return;
		}
		UnityEngine.Vector3 forward = (base.transform.parent.InverseTransformPoint(collider.transform.position) - base.transform.localPosition).WithY(0f);
		float target = Mathf.Atan2(forward.z, forward.x) * 57.29578f;
		if (isTouching)
		{
			base.transform.localRotation = UnityEngine.Quaternion.LookRotation(forward) * firstTouchRotation;
			if (isPlaying)
			{
				float num = Mathf.DeltaAngle(lastScratchSoundAngle, target);
				if (num > scratchMinAngle)
				{
					if (Time.time > cantForwardScratchUntilTimestamp)
					{
						scratchPlayer.Play(ScratchSoundType.Forward, isLeft);
						cantForwardScratchUntilTimestamp = Time.time + scratchCooldown;
						lastScratchSoundAngle = target;
						GorillaTagger.Instance.StartVibration(componentInParent.isLeftHand, hapticStrength, hapticDuration);
					}
				}
				else if (num < 0f - scratchMinAngle && Time.time > cantBackScratchUntilTimestamp)
				{
					scratchPlayer.Play(ScratchSoundType.Back, isLeft);
					cantBackScratchUntilTimestamp = Time.time + scratchCooldown;
					lastScratchSoundAngle = target;
					GorillaTagger.Instance.StartVibration(componentInParent.isLeftHand, hapticStrength, hapticDuration);
				}
			}
		}
		else
		{
			firstTouchRotation = UnityEngine.Quaternion.Inverse(UnityEngine.Quaternion.LookRotation(base.transform.InverseTransformPoint(collider.transform.position).WithY(0f)));
			if (isPlaying)
			{
				PauseTrack();
				scratchPlayer.Play(ScratchSoundType.Pause, isLeft);
				lastScratchSoundAngle = target;
				cantForwardScratchUntilTimestamp = Time.time + scratchCooldown;
				cantBackScratchUntilTimestamp = Time.time + scratchCooldown;
			}
		}
		isTouching = true;
	}

	private void OnTriggerExit(Collider collider)
	{
		if (base.enabled && !(collider.GetComponentInParent<GorillaTriggerColliderHandIndicator>() == null))
		{
			if (isPlaying)
			{
				ResumeTrack();
				scratchPlayer.Play(ScratchSoundType.Resume, isLeft);
			}
			isTouching = false;
		}
	}

	public void SelectTrack(int track)
	{
		lastSelectedTrack = track;
		if (track == 0)
		{
			turntableVisual.Stop();
			isPlaying = false;
		}
		else
		{
			turntableVisual.Run();
			isPlaying = true;
		}
		int num = track - 1;
		for (int i = 0; i < tracks.Length; i++)
		{
			if (num == i)
			{
				float time = (float)(PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time)) % trackDuration;
				tracks[i].Play();
				tracks[i].time = time;
			}
			else
			{
				tracks[i].Stop();
			}
		}
	}

	public void PauseTrack()
	{
		for (int i = 0; i < tracks.Length; i++)
		{
			tracks[i].Stop();
		}
		pausedUntilTimestamp = Time.time + 1f;
	}

	public void ResumeTrack()
	{
		SelectTrack(lastSelectedTrack);
		pausedUntilTimestamp = 0f;
	}
}
public class ElfLauncher : MonoBehaviour
{
	[SerializeField]
	protected TransferrableObject parentHoldable;

	[SerializeField]
	private TransferrableObjectHoldablePart_Crank[] cranks;

	[SerializeField]
	private float crankShootThreshold = 360f;

	[SerializeField]
	private float crankClickThreshold = 30f;

	[SerializeField]
	private Transform muzzle;

	[SerializeField]
	private GameObject elfProjectilePrefab;

	protected int elfProjectileHash;

	[SerializeField]
	protected float muzzleVelocity = 10f;

	[SerializeField]
	private SoundBankPlayer crankClickAudio;

	[SerializeField]
	protected SoundBankPlayer shootAudio;

	[SerializeField]
	private float shootHapticStrength;

	[SerializeField]
	private float shootHapticDuration;

	private RubberDuckEvents _events;

	private float currentShootCrankAmount;

	private float currentClickCrankAmount;

	private NetPlayer m_player;

	private void OnEnable()
	{
		if (_events == null)
		{
			_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			NetPlayer netPlayer = ((parentHoldable.myOnlineRig != null) ? parentHoldable.myOnlineRig.creator : ((!(parentHoldable.myRig != null)) ? null : ((parentHoldable.myRig.creator != null) ? parentHoldable.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
			if (netPlayer != null)
			{
				m_player = netPlayer;
				_events.Init(netPlayer);
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
			}
		}
		if (_events != null)
		{
			_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(ShootShared);
		}
	}

	private void OnDisable()
	{
		if (_events != null)
		{
			_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(ShootShared);
			_events.Dispose();
			_events = null;
			m_player = null;
		}
	}

	private void Awake()
	{
		_events = GetComponent<RubberDuckEvents>();
		elfProjectileHash = PoolUtils.GameObjHashCode(elfProjectilePrefab);
		TransferrableObjectHoldablePart_Crank[] array = cranks;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetOnCrankedCallback(OnCranked);
		}
	}

	private void OnCranked(float deltaAngle)
	{
		currentShootCrankAmount += deltaAngle;
		if (Mathf.Abs(currentShootCrankAmount) > crankShootThreshold)
		{
			currentShootCrankAmount = 0f;
			Shoot();
		}
		currentClickCrankAmount += deltaAngle;
		if (Mathf.Abs(currentClickCrankAmount) > crankClickThreshold)
		{
			currentClickCrankAmount = 0f;
			crankClickAudio.Play();
		}
	}

	private void Shoot()
	{
		if (parentHoldable.IsLocalObject())
		{
			GorillaTagger.Instance.StartVibration(forLeftController: true, shootHapticStrength, shootHapticDuration);
			GorillaTagger.Instance.StartVibration(forLeftController: false, shootHapticStrength, shootHapticDuration);
			if (PhotonNetwork.InRoom)
			{
				_events.Activate.RaiseAll(muzzle.transform.position, muzzle.transform.forward);
			}
			else
			{
				ShootShared(muzzle.transform.position, muzzle.transform.forward);
			}
		}
	}

	private void ShootShared(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		if (args.Length == 2 && sender == target)
		{
			VRRig ownerRig = parentHoldable.ownerRig;
			if (info.senderID == ownerRig.creator.ActorNumber && args.Length == 2 && args[0] is UnityEngine.Vector3 v && args[1] is UnityEngine.Vector3 v2 && v.IsValid(10000f) && v2.IsValid(10000f) && FXSystem.CheckCallSpam(ownerRig.fxSettings, 4, info.SentServerTime) && ownerRig.IsPositionInRange(v, 6f))
			{
				ShootShared(v, v2);
			}
		}
	}

	protected virtual void ShootShared(UnityEngine.Vector3 origin, UnityEngine.Vector3 direction)
	{
		shootAudio.Play();
		UnityEngine.Vector3 lossyScale = base.transform.lossyScale;
		GameObject obj = ObjectPools.instance.Instantiate(elfProjectileHash);
		obj.transform.position = origin;
		obj.transform.rotation = UnityEngine.Quaternion.LookRotation(direction);
		obj.transform.localScale = lossyScale;
		obj.GetComponent<Rigidbody>().linearVelocity = direction * muzzleVelocity * lossyScale.x;
	}
}
public class ElfLauncherElf : MonoBehaviour
