public class EqualizerAnim : MonoBehaviour
{
	[SerializeField]
	private AnimationCurve redCurve;

	[SerializeField]
	private AnimationCurve greenCurve;

	[SerializeField]
	private AnimationCurve blueCurve;

	[SerializeField]
	private float loopDuration;

	[SerializeField]
	private Material material;

	[SerializeField]
	private string inputColorProperty;

	private int inputColorHash;

	private static int thisFrame;

	private static HashSet<Material> materialsUpdatedThisFrame = new HashSet<Material>();

	private void Start()
	{
		inputColorHash = Shader.PropertyToID(inputColorProperty);
	}

	private void Update()
	{
		if (thisFrame == Time.frameCount)
		{
			if (materialsUpdatedThisFrame.Contains(material))
			{
				return;
			}
		}
		else
		{
			thisFrame = Time.frameCount;
			materialsUpdatedThisFrame.Clear();
		}
		float time = Time.time % loopDuration;
		material.SetColor(inputColorHash, new Color(redCurve.Evaluate(time), greenCurve.Evaluate(time), blueCurve.Evaluate(time)));
		materialsUpdatedThisFrame.Add(material);
	}
}
public class FakeWheelDriver : MonoBehaviour
{
	[SerializeField]
	private Rigidbody myRigidBody;

	[SerializeField]
	private UnityEngine.Vector3 thrust;

	[SerializeField]
	private Collider wheelCollider;

	[SerializeField]
	private float maxSpeed;

	[SerializeField]
	private float lateralFrictionForce;

	private UnityEngine.Vector3 collisionPoint;

	private UnityEngine.Vector3 collisionNormal;

	public bool hasCollision { get; private set; }

	public void SetThrust(UnityEngine.Vector3 thrust)
	{
		this.thrust = thrust;
	}

	private void OnCollisionStay(UnityEngine.Collision collision)
	{
		int num = 0;
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		ContactPoint[] contacts = collision.contacts;
		for (int i = 0; i < contacts.Length; i++)
		{
			ContactPoint contactPoint = contacts[i];
			if (contactPoint.thisCollider == wheelCollider)
			{
				zero += contactPoint.point;
				num++;
			}
		}
		if (num > 0)
		{
			collisionNormal = collision.contacts[0].normal;
			collisionPoint = zero / num;
			hasCollision = true;
		}
	}

	private void FixedUpdate()
	{
		if (hasCollision)
		{
			UnityEngine.Vector3 vector = base.transform.rotation * thrust;
			if (myRigidBody.linearVelocity.IsShorterThan(maxSpeed))
			{
				vector = vector.ProjectOntoPlane(collisionNormal).normalized * thrust.magnitude;
				myRigidBody.AddForceAtPosition(vector, collisionPoint);
			}
			UnityEngine.Vector3 vector2 = myRigidBody.linearVelocity.ProjectOntoPlane(collisionNormal).ProjectOntoPlane(vector.normalized);
			if (vector2.IsLongerThan(lateralFrictionForce))
			{
				myRigidBody.AddForceAtPosition(-vector2.normalized * lateralFrictionForce, collisionPoint);
			}
			else
			{
				myRigidBody.AddForceAtPosition(-vector2, collisionPoint);
			}
		}
		hasCollision = false;
	}
}
