[Flags]
public enum GestureNodeFlags : uint
{
	None = 0u,
	HandLeft = 1u,
	HandRight = 2u,
	HandOpen = 4u,
	HandClosed = 8u,
	DigitOpen = 0x10u,
	DigitClosed = 0x20u,
	DigitBent = 0x40u,
	TowardFace = 0x80u,
	AwayFromFace = 0x100u,
	AxisWorldUp = 0x200u,
	AxisWorldDown = 0x400u
}
[Flags]
public enum GestureHandState : uint
{
	None = 0u,
	IsLeft = 1u,
	IsRight = 2u,
	Open = 4u,
	Closed = 8u
}
[Flags]
public enum GestureDigitFlexion : uint
{
	None = 0u,
	Open = 0x10u,
	Closed = 0x20u,
	Bent = 0x40u
}
[Flags]
public enum GestureAlignment : uint
{
	None = 0u,
	TowardFace = 0x80u,
	AwayFromFace = 0x100u,
	WorldUp = 0x200u,
	WorldDown = 0x400u
}
