[Flags]
internal enum GorillaSkinMaterials
{
	Body = 1,
	Face = 2,
	Chest = 4,
	Scoreboard = 8
}
public class GorillaSkinToggle : MonoBehaviour, ISpawnable
{
	[Serializable]
	private struct ColoringRule
	{
		public GorillaSkinMaterials colorMaterials;

		public string shaderColorProperty;

		private ShaderHashId shaderHashId;

		public void Init()
		{
			if (string.IsNullOrEmpty(shaderColorProperty))
			{
				shaderColorProperty = "_BaseColor";
			}
			shaderHashId = new ShaderHashId(shaderColorProperty);
		}

		public void Apply(GorillaSkin skin, Color color)
		{
			if (colorMaterials.HasFlag(GorillaSkinMaterials.Body))
			{
				skin.bodyMaterial.SetColor(shaderHashId, color);
			}
			if (colorMaterials.HasFlag(GorillaSkinMaterials.Chest))
			{
				skin.chestMaterial.SetColor(shaderHashId, color);
			}
			if (colorMaterials.HasFlag(GorillaSkinMaterials.Scoreboard))
			{
				skin.scoreboardMaterial.SetColor(shaderHashId, color);
			}
		}
	}

	private VRRig _rig;

	[SerializeField]
	private GorillaSkin _skin;

	private GorillaSkin _activeSkin;

	[SerializeField]
	private ColoringRule[] coloringRules;

	[Space]
	[SerializeField]
	private bool _applied;

	public bool applied => _applied;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnSpawn(VRRig rig)
	{
		_rig = GetComponentInParent<VRRig>(includeInactive: true);
		if (coloringRules.Length != 0)
		{
			_activeSkin = GorillaSkin.CopyWithInstancedMaterials(_skin);
			for (int i = 0; i < coloringRules.Length; i++)
			{
				coloringRules[i].Init();
			}
		}
		else
		{
			_activeSkin = _skin;
		}
	}

	void ISpawnable.OnDespawn()
	{
	}

	private void OnPlayerColorChanged(Color playerColor)
	{
		ColoringRule[] array = coloringRules;
		foreach (ColoringRule coloringRule in array)
		{
			coloringRule.Apply(_activeSkin, playerColor);
		}
	}

	private void OnEnable()
	{
		if (coloringRules.Length != 0)
		{
			_rig.OnColorChanged += OnPlayerColorChanged;
			OnPlayerColorChanged(_rig.playerColor);
		}
		Apply();
	}

	private void OnDisable()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			Remove();
			if (coloringRules.Length != 0)
			{
				_rig.OnColorChanged -= OnPlayerColorChanged;
			}
		}
	}

	public void Apply()
	{
		GorillaSkin.ApplyToRig(_rig, _activeSkin, GorillaSkin.SkinType.cosmetic);
		_applied = true;
	}

	public void ApplyToMannequin(GameObject mannequin, bool swapMesh = false)
	{
		if (GTExt.IsNull(_skin))
		{
			UnityEngine.Debug.LogError("No skin set on GorillaSkinToggle");
		}
		else if (GTExt.IsNull(mannequin))
		{
			UnityEngine.Debug.LogError("No mannequin set on GorillaSkinToggle");
		}
		else
		{
			_skin.ApplySkinToMannequin(mannequin, swapMesh);
		}
	}

	public void Remove()
	{
		GorillaSkin.ApplyToRig(_rig, null, GorillaSkin.SkinType.cosmetic);
		float red = PlayerPrefs.GetFloat("redValue", 0f);
		float green = PlayerPrefs.GetFloat("greenValue", 0f);
		float blue = PlayerPrefs.GetFloat("blueValue", 0f);
		GorillaTagger.Instance.UpdateColor(red, green, blue);
		_applied = false;
	}
}
public class GragerHoldable : MonoBehaviour
{
	[SerializeField]
	private UnityEngine.Vector3 LocalCenterOfMass;

	[SerializeField]
	private UnityEngine.Vector3 LocalRotationAxis;

	[SerializeField]
	private UnityEngine.Vector3 RotationCorrectionEuler;

	[SerializeField]
	private float drag;

	[SerializeField]
	private float gravity;

	[SerializeField]
	private float localFriction;

	[SerializeField]
	private float distancePerClack;

	[SerializeField]
	private AudioSource clackAudio;

	[SerializeField]
	private AudioClip[] allClacks;

	private float centerOfMassRadius;

	private UnityEngine.Vector3 velocity;

	private UnityEngine.Vector3 lastWorldPosition;

	private UnityEngine.Vector3 lastClackParentLocalPosition;

	private UnityEngine.Quaternion RotationCorrection;

	private void Start()
	{
		LocalRotationAxis = LocalRotationAxis.normalized;
		lastWorldPosition = base.transform.TransformPoint(LocalCenterOfMass);
		lastClackParentLocalPosition = base.transform.parent.InverseTransformPoint(lastWorldPosition);
		centerOfMassRadius = LocalCenterOfMass.magnitude;
		RotationCorrection = UnityEngine.Quaternion.Euler(RotationCorrectionEuler);
	}

	private void Update()
	{
		UnityEngine.Vector3 target = base.transform.TransformPoint(LocalCenterOfMass);
		UnityEngine.Vector3 vector = lastWorldPosition + velocity * Time.deltaTime * drag;
		UnityEngine.Vector3 vector2 = base.transform.parent.TransformDirection(LocalRotationAxis);
		UnityEngine.Vector3 current = base.transform.position + (vector - base.transform.position).ProjectOntoPlane(vector2).normalized * centerOfMassRadius;
		current = UnityEngine.Vector3.MoveTowards(current, target, localFriction * Time.deltaTime);
		velocity = (current - lastWorldPosition) / Time.deltaTime;
		velocity += UnityEngine.Vector3.down * gravity * Time.deltaTime;
		lastWorldPosition = current;
		base.transform.rotation = UnityEngine.Quaternion.LookRotation(current - base.transform.position, vector2) * RotationCorrection;
		UnityEngine.Vector3 vector3 = base.transform.parent.InverseTransformPoint(base.transform.TransformPoint(LocalCenterOfMass));
		if ((vector3 - lastClackParentLocalPosition).IsLongerThan(distancePerClack))
		{
			clackAudio.GTPlayOneShot(allClacks[UnityEngine.Random.Range(0, allClacks.Length)]);
			lastClackParentLocalPosition = vector3;
		}
	}
}
