public class HandTapEffect : MonoBehaviour
{
	[Serializable]
	public class HandTapEffectDownUp
	{
		public HandTapBehaviour[] onTapBehaviours;

		public UnityEvent onTapUnityEvents;

		[Tooltip("Must be in the global object pool and have a tag.\n\nPrefabs can have an FXModifier component to be adjusted after creation.")]
		public HashWrapper onTapPrefabToSpawn;

		public HandTapOverrides overrides;

		public bool HasOverrides
		{
			get
			{
				if (!overrides.overrideSurfacePrefab && !overrides.overrideGamemodePrefab)
				{
					return overrides.overrideSound;
				}
				return true;
			}
		}

		internal void OnTap(HandEffectContext handContext)
		{
			onTapUnityEvents?.Invoke();
			for (int i = 0; i < onTapBehaviours.Length; i++)
			{
				onTapBehaviours[i].OnTap(handContext);
			}
		}
	}

	[Serializable]
	public class HandTapEffectLeftRight
	{
		public bool separateUpTapCooldown;

		public HandTapEffectDownUp downTapEffect;

		public HandTapEffectDownUp upTapEffect;

		internal HandEffectContext handContext;

		public void OnEnable()
		{
			if (separateUpTapCooldown)
			{
				handContext.SeparateUpTapCooldown = true;
			}
			if ((int)downTapEffect.onTapPrefabToSpawn != -1)
			{
				handContext.AddFXPrefab(downTapEffect.onTapPrefabToSpawn);
			}
			if (downTapEffect.HasOverrides)
			{
				handContext.DownTapOverrides = downTapEffect.overrides;
			}
			if (upTapEffect.HasOverrides)
			{
				handContext.UpTapOverrides = upTapEffect.overrides;
			}
			handContext.handTapDown += downTapEffect.OnTap;
			handContext.handTapUp += upTapEffect.OnTap;
		}

		public void OnDisable()
		{
			if (separateUpTapCooldown)
			{
				handContext.SeparateUpTapCooldown = false;
			}
			if ((int)downTapEffect.onTapPrefabToSpawn != -1)
			{
				handContext.RemoveFXPrefab(downTapEffect.onTapPrefabToSpawn);
			}
			if (downTapEffect.HasOverrides && handContext.DownTapOverrides == downTapEffect.overrides)
			{
				handContext.DownTapOverrides = null;
			}
			if (upTapEffect.HasOverrides && handContext.UpTapOverrides == upTapEffect.overrides)
			{
				handContext.UpTapOverrides = null;
			}
			handContext.handTapDown -= downTapEffect.OnTap;
			handContext.handTapUp -= upTapEffect.OnTap;
		}
	}

	public HandTapEffectLeftRight leftHandEffect;

	public HandTapEffectLeftRight rightHandEffect;

	private void Awake()
	{
		VRRig componentInParent = GetComponentInParent<VRRig>();
		leftHandEffect.handContext = componentInParent.LeftHandEffect;
		rightHandEffect.handContext = componentInParent.RightHandEffect;
	}

	private void OnEnable()
	{
		leftHandEffect.OnEnable();
		rightHandEffect.OnEnable();
	}

	private void OnDisable()
	{
		leftHandEffect.OnDisable();
		rightHandEffect.OnDisable();
	}
}
public class HandTapReactor : MonoBehaviour
{
	[Flags]
	private enum TapType
	{
		None = 0,
		LeftDown = 1,
		LeftUp = 2,
		LeftHighFive = 4,
		LeftFistBump = 8,
		LeftTagFirstPerson = 0x10,
		LeftTagThirdPerson = 0x20,
		AllLeft = 0x3F,
		RightDown = 0x40,
		RightUp = 0x80,
		RightHighFive = 0x100,
		RightFistBump = 0x200,
		RightTagFirstPerson = 0x400,
		RightTagThirdPerson = 0x800,
		AllRight = 0xFC0,
		All = -1
	}

	[SerializeField]
	private FlagEvents<TapType> handTapEvents;

	private VRRig myRig;

	private IHandEffectsTrigger leftHandTrigger;

	private IHandEffectsTrigger rightHandTrigger;

	private void LeftDown(HandEffectContext ctx)
	{
		handTapEvents.InvokeAll(TapType.LeftDown);
	}

	private void LeftUp(HandEffectContext ctx)
	{
		handTapEvents.InvokeAll(TapType.LeftUp);
	}

	private void LeftGesture(IHandEffectsTrigger.Mode mode)
	{
		FlagEvents<TapType> flagEvents = handTapEvents;
		TapType test = default(TapType);
		switch (mode)
		{
		case IHandEffectsTrigger.Mode.HighFive:
			test = TapType.LeftHighFive;
			break;
		case IHandEffectsTrigger.Mode.FistBump:
			test = TapType.LeftFistBump;
			break;
		case IHandEffectsTrigger.Mode.Tag1P:
			test = TapType.LeftTagFirstPerson;
			break;
		case IHandEffectsTrigger.Mode.Tag3P:
			test = TapType.LeftTagThirdPerson;
			break;
		default:
			global::<PrivateImplementationDetails>.ThrowSwitchExpressionException(mode);
			break;
		}
		flagEvents.InvokeAll(test);
	}

	private void RightDown(HandEffectContext ctx)
	{
		handTapEvents.InvokeAll(TapType.RightDown);
	}

	private void RightUp(HandEffectContext ctx)
	{
		handTapEvents.InvokeAll(TapType.RightUp);
	}

	private void RightGesture(IHandEffectsTrigger.Mode mode)
	{
		FlagEvents<TapType> flagEvents = handTapEvents;
		TapType test = default(TapType);
		switch (mode)
		{
		case IHandEffectsTrigger.Mode.HighFive:
			test = TapType.RightHighFive;
			break;
		case IHandEffectsTrigger.Mode.FistBump:
			test = TapType.RightFistBump;
			break;
		case IHandEffectsTrigger.Mode.Tag1P:
			test = TapType.RightTagFirstPerson;
			break;
		case IHandEffectsTrigger.Mode.Tag3P:
			test = TapType.RightTagThirdPerson;
			break;
		default:
			global::<PrivateImplementationDetails>.ThrowSwitchExpressionException(mode);
			break;
		}
		flagEvents.InvokeAll(test);
	}

	private void OnEnable()
	{
		if (myRig == null)
		{
			myRig = GetComponentInParent<VRRig>();
			IHandEffectsTrigger[] componentsInChildren = myRig.GetComponentsInChildren<IHandEffectsTrigger>();
			if (componentsInChildren[0].RightHand)
			{
				rightHandTrigger = componentsInChildren[0];
				leftHandTrigger = componentsInChildren[1];
			}
			else
			{
				rightHandTrigger = componentsInChildren[1];
				leftHandTrigger = componentsInChildren[0];
			}
		}
		if (myRig != null)
		{
			myRig.LeftHandEffect.handTapDown += LeftDown;
			myRig.LeftHandEffect.handTapUp += LeftUp;
			IHandEffectsTrigger handEffectsTrigger = leftHandTrigger;
			handEffectsTrigger.OnTrigger = (Action<IHandEffectsTrigger.Mode>)Delegate.Combine(handEffectsTrigger.OnTrigger, new Action<IHandEffectsTrigger.Mode>(LeftGesture));
			myRig.RightHandEffect.handTapDown += RightDown;
			myRig.RightHandEffect.handTapUp += RightUp;
			IHandEffectsTrigger handEffectsTrigger2 = rightHandTrigger;
			handEffectsTrigger2.OnTrigger = (Action<IHandEffectsTrigger.Mode>)Delegate.Combine(handEffectsTrigger2.OnTrigger, new Action<IHandEffectsTrigger.Mode>(RightGesture));
		}
	}

	private void OnDisable()
	{
		if (myRig != null)
		{
			myRig.LeftHandEffect.handTapDown -= LeftDown;
			myRig.LeftHandEffect.handTapUp -= LeftUp;
			IHandEffectsTrigger handEffectsTrigger = leftHandTrigger;
			handEffectsTrigger.OnTrigger = (Action<IHandEffectsTrigger.Mode>)Delegate.Remove(handEffectsTrigger.OnTrigger, new Action<IHandEffectsTrigger.Mode>(LeftGesture));
			myRig.RightHandEffect.handTapDown -= RightDown;
			myRig.RightHandEffect.handTapUp -= RightUp;
			IHandEffectsTrigger handEffectsTrigger2 = rightHandTrigger;
			handEffectsTrigger2.OnTrigger = (Action<IHandEffectsTrigger.Mode>)Delegate.Remove(handEffectsTrigger2.OnTrigger, new Action<IHandEffectsTrigger.Mode>(RightGesture));
		}
	}
}
public class HoseSimulator : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private SkinnedMeshRenderer skinnedMeshRenderer;

	[SerializeField]
	private UnityEngine.Vector3 localBoundsOverride;

	[SerializeField]
	private Transform[] miscBones;

	[SerializeField]
	private Transform[] hoseBones;

	[SerializeField]
	private float[] hoseBoneMaxDisplacement;

	[SerializeField]
	private CosmeticRefID startAnchorRef;

	private Transform startAnchor;

	[SerializeField]
	private float startStiffness = 0.5f;

	[SerializeField]
	private Transform endAnchor;

	[SerializeField]
	private float endStiffness = 0.5f;

	private UnityEngine.Vector3[] hoseBonePositions;

	private UnityEngine.Vector3[] hoseBoneVelocities;

	[SerializeField]
	private float damping = 0.97f;

	private float[] hoseSectionLengths;

	private float totalHoseLength;

	private bool firstUpdate = true;

	private HoseSimulatorAnchors anchors;

	[SerializeField]
	private TransferrableObject myHoldable;

	private bool isLeftHanded;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnDespawn()
	{
	}

	void ISpawnable.OnSpawn(VRRig rig)
	{
		anchors = rig.cosmeticReferences.Get(startAnchorRef).GetComponent<HoseSimulatorAnchors>();
		if (skinnedMeshRenderer != null)
		{
			Bounds localBounds = skinnedMeshRenderer.localBounds;
			localBounds.extents = localBoundsOverride;
			skinnedMeshRenderer.localBounds = localBounds;
		}
		hoseSectionLengths = new float[hoseBones.Length - 1];
		hoseBonePositions = new UnityEngine.Vector3[hoseBones.Length];
		hoseBoneVelocities = new UnityEngine.Vector3[hoseBones.Length];
		for (int i = 0; i < hoseSectionLengths.Length; i++)
		{
			float num = 1f;
			hoseSectionLengths[i] = num;
			totalHoseLength += num;
		}
	}

	private void LateUpdate()
	{
		if (myHoldable.InLeftHand())
		{
			isLeftHanded = true;
		}
		else if (myHoldable.InRightHand())
		{
			isLeftHanded = false;
		}
		for (int i = 0; i < miscBones.Length; i++)
		{
			Transform transform = (isLeftHanded ? anchors.miscAnchorsLeft[i] : anchors.miscAnchorsRight[i]);
			miscBones[i].transform.position = transform.position;
			miscBones[i].transform.rotation = transform.rotation;
		}
		startAnchor = (isLeftHanded ? anchors.leftAnchorPoint : anchors.rightAnchorPoint);
		float x = myHoldable.transform.lossyScale.x;
		float num = 0f;
		UnityEngine.Vector3 position = startAnchor.position;
		UnityEngine.Vector3 ctrl = position + startAnchor.forward * startStiffness * x;
		UnityEngine.Vector3 position2 = endAnchor.position;
		UnityEngine.Vector3 ctrl2 = position2 - endAnchor.forward * endStiffness * x;
		for (int j = 0; j < hoseBones.Length; j++)
		{
			float num2 = num / totalHoseLength;
			UnityEngine.Vector3 vector = BezierUtils.BezierSolve(num2, position, ctrl, ctrl2, position2);
			UnityEngine.Vector3 vector2 = BezierUtils.BezierSolve(num2 + 0.1f, position, ctrl, ctrl2, position2);
			if (firstUpdate)
			{
				hoseBones[j].transform.position = vector;
				hoseBonePositions[j] = vector;
				hoseBoneVelocities[j] = UnityEngine.Vector3.zero;
			}
			else
			{
				hoseBoneVelocities[j] *= damping;
				hoseBonePositions[j] += hoseBoneVelocities[j] * Time.deltaTime;
				float num3 = hoseBoneMaxDisplacement[j] * x;
				if ((vector - hoseBonePositions[j]).IsLongerThan(num3))
				{
					UnityEngine.Vector3 vector3 = vector + (hoseBonePositions[j] - vector).normalized * num3;
					hoseBoneVelocities[j] += (vector3 - hoseBonePositions[j]) / Time.deltaTime;
					hoseBonePositions[j] = vector3;
				}
				hoseBones[j].transform.position = hoseBonePositions[j];
			}
			hoseBones[j].transform.rotation = UnityEngine.Quaternion.LookRotation(vector2 - vector, endAnchor.transform.up);
			if (j < hoseSectionLengths.Length)
			{
				num += hoseSectionLengths[j];
			}
		}
		firstUpdate = false;
	}

	private void OnDrawGizmosSelected()
	{
		if (hoseBonePositions != null)
		{
			Gizmos.color = Color.yellow;
			Gizmos.DrawLineStrip(hoseBonePositions, looped: false);
		}
	}
}
