	public void StartFan()
	{
		fan.Run();
	}

	public void StopFan()
	{
		fan.Stop();
	}

	public void UpdateEffects()
	{
		ProjectParticles();
		BlowFaces();
	}

	public void ProjectParticles()
	{
		if (Physics.Raycast(gunBarrel.transform.position, gunBarrel.transform.forward, out var hitInfo, projectionRange, raycastLayers))
		{
			SpawnOnEnter component = hitInfo.collider.GetComponent<SpawnOnEnter>();
			if (component != null)
			{
				component.OnTriggerEnter(hitInfo.collider);
			}
			if (UnityEngine.Vector3.Dot(hitInfo.normal, gunBarrel.transform.forward) < 0f - squareHitAngleCos)
			{
				squareHitParticleSystem.transform.position = hitInfo.point;
				squareHitParticleSystem.transform.rotation = UnityEngine.Quaternion.LookRotation(hitInfo.normal, gunBarrel.transform.forward);
				if (angledHitParticleSystem != squareHitParticleSystem && angledHitParticleSystem.isPlaying)
				{
					angledHitParticleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				}
				if (!squareHitParticleSystem.isPlaying)
				{
					squareHitParticleSystem.Play(withChildren: true);
				}
			}
			else
			{
				angledHitParticleSystem.transform.position = hitInfo.point;
				angledHitParticleSystem.transform.rotation = UnityEngine.Quaternion.LookRotation(hitInfo.normal, gunBarrel.transform.forward);
				if (angledHitParticleSystem != squareHitParticleSystem && squareHitParticleSystem.isPlaying)
				{
					squareHitParticleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				}
				if (!angledHitParticleSystem.isPlaying)
				{
					angledHitParticleSystem.Play(withChildren: true);
				}
			}
		}
		else
		{
			StopEffects();
		}
	}

	public void StopEffects()
	{
		angledHitParticleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		squareHitParticleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
	}

	public void BlowFaces()
	{
		UnityEngine.Vector3 position = gunBarrel.transform.position;
		UnityEngine.Vector3 forward = gunBarrel.transform.forward;
		if (NetworkSystem.Instance.InRoom)
		{
			foreach (RigContainer activeRigContainer in VRRigCache.ActiveRigContainers)
			{
				TryBlowFace(activeRigContainer.Rig, position, forward);
			}
			return;
		}
		TryBlowFace(VRRig.LocalRig, position, forward);
	}

	private void TryBlowFace(VRRig rig, UnityEngine.Vector3 origin, UnityEngine.Vector3 directionNormalized)
	{
		Transform rigTarget = rig.head.rigTarget;
		UnityEngine.Vector3 vector = rigTarget.position - origin;
		float num = UnityEngine.Vector3.Dot(vector, directionNormalized);
		if (!(num < 0f) && !(num > projectionRange) && !(vector - num * directionNormalized).IsLongerThan(projectionWidth) && !(UnityEngine.Vector3.Dot(-rigTarget.forward, vector.normalized) < headToleranceAngleCos))
		{
			rig.GetComponent<GorillaMouthFlap>().EnableLeafBlower();
		}
	}
}
public class LongScarfSim : MonoBehaviour
{
	[SerializeField]
	private GameObject[] gameObjects;

	[SerializeField]
	private float speedThreshold = 1f;

	[SerializeField]
	private float blendAmountPerSecond = 1f;

	private GorillaVelocityEstimator velocityEstimator;

	private UnityEngine.Quaternion[] baseLocalRotations;

	private float currentBlend;

	[SerializeField]
	private float centerOfMassLength;

	[SerializeField]
	private float gravityStrength;

	[SerializeField]
	private float drag;

	[SerializeField]
	private UnityEngine.Vector3 clampToPlane;

	private UnityEngine.Vector3 lastCenterPos;

	private UnityEngine.Vector3 velocity;

	private void Start()
	{
		clampToPlane.Normalize();
		velocityEstimator = GetComponent<GorillaVelocityEstimator>();
		baseLocalRotations = new UnityEngine.Quaternion[gameObjects.Length];
		for (int i = 0; i < gameObjects.Length; i++)
		{
			baseLocalRotations[i] = gameObjects[i].transform.localRotation;
		}
	}

	private void LateUpdate()
	{
		velocity *= drag;
		velocity.y -= gravityStrength * Time.deltaTime;
		UnityEngine.Vector3 position = base.transform.position;
		UnityEngine.Vector3 vector = lastCenterPos + velocity * Time.deltaTime;
		UnityEngine.Vector3 vector2 = position + (vector - position).normalized * centerOfMassLength;
		UnityEngine.Vector3 vector3 = base.transform.InverseTransformPoint(vector2);
		float num = UnityEngine.Vector3.Dot(vector3, clampToPlane);
		if (num < 0f)
		{
			vector3 -= clampToPlane * num;
			vector2 = base.transform.TransformPoint(vector3);
		}
		UnityEngine.Vector3 vector4 = vector2;
		velocity = (vector4 - lastCenterPos) / Time.deltaTime;
		lastCenterPos = vector4;
		float target = (velocityEstimator.linearVelocity.IsLongerThan(speedThreshold) ? 1 : 0);
		currentBlend = Mathf.MoveTowards(currentBlend, target, blendAmountPerSecond * Time.deltaTime);
		UnityEngine.Quaternion b = UnityEngine.Quaternion.LookRotation(vector4 - position);
		for (int i = 0; i < gameObjects.Length; i++)
		{
			UnityEngine.Quaternion a = gameObjects[i].transform.parent.rotation * baseLocalRotations[i];
			gameObjects[i].transform.rotation = UnityEngine.Quaternion.Lerp(a, b, currentBlend);
		}
	}
}
public class LookDirectionStabilizer : MonoBehaviour, ISpawnable
{
	private VRRig myRig;

	public bool IsSpawned { get; set; }

	public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = rig;
	}

	void ISpawnable.OnDespawn()
	{
	}

	private void Update()
	{
		Transform rigTarget = myRig.head.rigTarget;
		UnityEngine.Vector3 up = myRig.transform.up;
		if (UnityEngine.Vector3.Dot(rigTarget.forward, up) < 0f)
		{
			UnityEngine.Quaternion b = UnityEngine.Quaternion.LookRotation(rigTarget.up.ProjectOntoPlane(up), up);
			UnityEngine.Quaternion rotation = base.transform.parent.rotation;
			float value = UnityEngine.Vector3.Dot(rigTarget.up, up);
			base.transform.rotation = UnityEngine.Quaternion.Lerp(rotation, b, Mathf.InverseLerp(1f, 0.7f, value));
		}
		else
		{
			base.transform.localRotation = UnityEngine.Quaternion.identity;
		}
	}
}
public class OnSqueezeTrigger : MonoBehaviour
{
	[SerializeField]
	private TransferrableObject myHoldable;

	[SerializeField]
	private UnityEvent onPress;

	[SerializeField]
	private UnityEvent onRelease;

	[SerializeField]
	private UnityEvent updateWhilePressed;

	private VRRig myRig;

	private bool indexFinger = true;

	private bool triggerWasDown;

	private void Start()
	{
		myRig = GetComponentInParent<VRRig>();
	}

	private void Update()
	{
		bool flag = (myHoldable.InLeftHand() ? ((indexFinger ? myRig.leftIndex.calcT : myRig.leftMiddle.calcT) > 0.5f) : (myHoldable.InRightHand() && (indexFinger ? myRig.rightIndex.calcT : myRig.rightMiddle.calcT) > 0.5f));
		if (flag != triggerWasDown)
		{
			if (flag)
			{
				onPress.Invoke();
				updateWhilePressed.Invoke();
			}
			else
			{
				onRelease.Invoke();
			}
		}
		else if (flag)
		{
			updateWhilePressed.Invoke();
		}
		triggerWasDown = flag;
	}
}
public class ParachuteProjectile : MonoBehaviour, IProjectile, ITickSystemTick
{
	[SerializeField]
	private MeshFilter monkeMeshFilter;

	[SerializeField]
	private GameObject parachute;

	[SerializeField]
	private Mesh launchMesh;

	[SerializeField]
	private Mesh parachutingMesh;

	[SerializeField]
	private Mesh landedMesh;

	[Tooltip("time to wait after launch before deploying the parachute")]
	[SerializeField]
	private float parachuteDeployDelay = 1f;

	[Tooltip("time to wait after landing before destroying")]
	[SerializeField]
	private float destroyOnLandDelay = 3f;

	[Tooltip("How far from the collision point should the projectile sit when landed")]
	[SerializeField]
	private float groundOffset;

	[Tooltip("Acceptable angle in degrees of surface from world up to be considered the ground")]
	[SerializeField]
	private float groudUpThreshold = 45f;

	[Tooltip("Drag before the parachute is deployed.")]
	[SerializeField]
	private float initialDrag;

	[Tooltip("Drag before the parachute is deployed.")]
	[SerializeField]
	private float initialAngularDrag = 0.05f;

	[Tooltip("Drag after the parachute is deployed.")]
	[SerializeField]
	private float parachuteDrag = 5f;

	[Tooltip("Drag after the parachute is deployed.")]
	[SerializeField]
	private float parachuteAngularDrag = 10f;

	[SerializeField]
	private GameObject impactEffect;

	[SerializeField]
	private float impactEffectScaleMultiplier = 1f;

	[Tooltip("Distance from the surface that the particle should spawn.")]
	[SerializeField]
	private float impactEffectOffset;

	private Rigidbody rb;

	private bool launched;

	private float launchedTime;

	private float landTime;

	private float peakTime = float.MaxValue;

	private bool parachuteDeployed;

	private bool landed;

	public bool TickRunning { get; set; }

	private void Awake()
	{
		rb = GetComponent<Rigidbody>();
	}

	private void OnEnable()
	{
		launched = false;
		landTime = 0f;
		launchedTime = 0f;
		peakTime = float.MaxValue;
		monkeMeshFilter.mesh = launchMesh;
		parachute.SetActive(value: false);
		if (!TickRunning)
		{
			TickSystem<object>.AddCallbackTarget(this);
		}
	}

	private void OnDisable()
	{
		launched = false;
		if (TickRunning)
		{
			TickSystem<object>.RemoveCallbackTarget(this);
		}
	}

	public void Launch(UnityEngine.Vector3 startPosition, UnityEngine.Quaternion startRotation, UnityEngine.Vector3 velocity, float chargeFrac, VRRig ownerRig, int progress)
	{
		parachuteDeployed = false;
		landed = false;
		if (rb == null)
		{
			rb = GetComponent<Rigidbody>();
		}
		rb.position = startPosition;
		rb.rotation = startRotation;
		ChangeUp(UnityEngine.Vector3.up);
		rb.freezeRotation = true;
		if (ownerRig == null)
		{
			base.transform.localScale = UnityEngine.Vector3.one;
		}
		else
		{
			base.transform.localScale = UnityEngine.Vector3.one * ownerRig.scaleFactor;
		}
		rb.isKinematic = false;
		rb.linearVelocity = velocity;
		rb.linearDamping = initialDrag;
		rb.angularDamping = initialAngularDrag;
		launchedTime = Time.time;
		monkeMeshFilter.mesh = launchMesh;
		parachute.SetActive(value: false);
		if (velocity.y > 0f)
		{
			peakTime = velocity.y / (-1f * Physics.gravity.y);
		}
		else
		{
			peakTime = 0f;
		}
		launched = true;
	}

	private void OnPeakReached()
	{
		parachuteDeployed = true;
		parachute.SetActive(value: true);
		monkeMeshFilter.mesh = parachutingMesh;
		ChangeUp(UnityEngine.Vector3.up);
		rb.linearDamping = parachuteDrag;
		rb.angularDamping = parachuteAngularDrag;
	}

	private void OnLanded(UnityEngine.Collision collision)
	{
		landTime = Time.time;
		landed = true;
		ContactPoint contact = collision.GetContact(0);
		rb.isKinematic = true;
		rb.position = contact.point + contact.normal * (groundOffset * base.transform.localScale.x);
		ChangeUp(contact.normal);
		monkeMeshFilter.mesh = landedMesh;
		parachute.SetActive(value: false);
	}

	private void ChangeUp(UnityEngine.Vector3 newUp)
	{
		UnityEngine.Vector3 forward = UnityEngine.Vector3.Cross(rb.transform.right, newUp);
		if (forward.sqrMagnitude < float.Epsilon)
		{
			forward = UnityEngine.Vector3.Cross(UnityEngine.Vector3.Cross(newUp, rb.transform.forward), newUp);
		}
		rb.rotation = UnityEngine.Quaternion.LookRotation(forward, newUp);
	}

	private void PlayImpactEffects(UnityEngine.Vector3 position, UnityEngine.Vector3 normal)
	{
		if (impactEffect != null)
		{
			UnityEngine.Vector3 position2 = position + impactEffectOffset * normal;
			GameObject obj = ObjectPools.instance.Instantiate(impactEffect, position2);
			obj.transform.localScale = base.transform.localScale * impactEffectScaleMultiplier;
			obj.transform.up = normal;
		}
		ObjectPools.instance.Destroy(base.gameObject);
	}

	public void OnTriggerEvent(bool isLeft, Collider col)
	{
		if (parachuteDeployed)
		{
			PlayImpactEffects(base.transform.position, UnityEngine.Vector3.up);
			GorillaTriggerColliderHandIndicator componentInParent = col.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
			if (componentInParent != null)
			{
				float amplitude = GorillaTagger.Instance.tapHapticStrength / 2f;
				float fixedDeltaTime = Time.fixedDeltaTime;
				GorillaTagger.Instance.StartVibration(componentInParent.isLeftHand, amplitude, fixedDeltaTime);
			}
		}
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (launched && !landed)
		{
			ContactPoint contact = collision.GetContact(0);
			if (collision.collider.attachedRigidbody != null)
			{
				PlayImpactEffects(contact.point, contact.normal);
			}
			else if (collision.collider.gameObject.IsOnLayer(UnityLayer.GorillaThrowable))
			{
				PlayImpactEffects(contact.point, contact.normal);
			}
			else if (!parachuteDeployed)
			{
				PlayImpactEffects(contact.point, contact.normal);
			}
			else if (UnityEngine.Vector3.Angle(contact.normal, UnityEngine.Vector3.up) < groudUpThreshold)
			{
				OnLanded(collision);
			}
			else
			{
				PlayImpactEffects(contact.point, contact.normal);
			}
		}
	}

	public void Tick()
	{
		if (!parachuteDeployed && Time.time > launchedTime + parachuteDeployDelay && Time.time >= launchedTime + peakTime)
		{
			OnPeakReached();
		}
		if (landed && Time.time > landTime + destroyOnLandDelay)
		{
			PlayImpactEffects(base.transform.position, base.transform.up);
		}
	}
}
