public class ParticleEffectsPool : MonoBehaviour
{
	public ParticleEffect[] effects = new ParticleEffect[0];

	[Space]
	public int poolSize = 10;

	[Space]
	private RingBuffer<ParticleEffect>[] _pools = new RingBuffer<ParticleEffect>[0];

	private Dictionary<long, int> _effectToPool = new Dictionary<long, int>();

	public void Awake()
	{
		OnPoolAwake();
		Setup();
	}

	protected virtual void OnPoolAwake()
	{
	}

	private void Setup()
	{
		MoveToSceneWorldRoot();
		_pools = new RingBuffer<ParticleEffect>[effects.Length];
		_effectToPool = new Dictionary<long, int>(effects.Length);
		for (int i = 0; i < effects.Length; i++)
		{
			ParticleEffect particleEffect = effects[i];
			_pools[i] = InitPoolForPrefab(i, effects[i]);
			_effectToPool.TryAdd(particleEffect.effectID, i);
		}
	}

	private void MoveToSceneWorldRoot()
	{
		Transform obj = base.transform;
		obj.parent = null;
		obj.position = UnityEngine.Vector3.zero;
		obj.rotation = UnityEngine.Quaternion.identity;
		obj.localScale = UnityEngine.Vector3.one;
	}

	private RingBuffer<ParticleEffect> InitPoolForPrefab(int index, ParticleEffect prefab)
	{
		RingBuffer<ParticleEffect> ringBuffer = new RingBuffer<ParticleEffect>(poolSize);
		string arg = prefab.name.Trim();
		for (int i = 0; i < poolSize; i++)
		{
			ParticleEffect particleEffect = UnityEngine.Object.Instantiate(prefab, base.transform);
			particleEffect.gameObject.SetActive(value: false);
			particleEffect.pool = this;
			particleEffect.poolIndex = index;
			particleEffect.name = ZString.Concat(arg, "*", i);
			ringBuffer.Push(particleEffect);
		}
		return ringBuffer;
	}

	public void PlayEffect(ParticleEffect effect, UnityEngine.Vector3 worldPos)
	{
		PlayEffect(effect.effectID, worldPos);
	}

	public void PlayEffect(ParticleEffect effect, UnityEngine.Vector3 worldPos, float delay)
	{
		PlayEffect(effect.effectID, worldPos, delay);
	}

	public void PlayEffect(long effectID, UnityEngine.Vector3 worldPos)
	{
		PlayEffect(GetPoolIndex(effectID), worldPos);
	}

	public void PlayEffect(long effectID, UnityEngine.Vector3 worldPos, float delay)
	{
		PlayEffect(GetPoolIndex(effectID), worldPos, delay);
	}

	public void PlayEffect(int index, UnityEngine.Vector3 worldPos)
	{
		if (index != -1 && _pools[index].TryPop(out var item))
		{
			item.transform.localPosition = worldPos;
			item.Play();
		}
	}

	public void PlayEffect(int index, UnityEngine.Vector3 worldPos, float delay)
	{
		if (delay.Approx(0f))
		{
			PlayEffect(index, worldPos);
		}
		else
		{
			StartCoroutine(PlayDelayed(index, worldPos, delay));
		}
	}

	private IEnumerator PlayDelayed(int index, UnityEngine.Vector3 worldPos, float delay)
	{
		yield return new WaitForSeconds(delay);
		PlayEffect(index, worldPos);
	}

	public void Return(ParticleEffect effect)
	{
		_pools[effect.poolIndex].Push(effect);
	}

	public int GetPoolIndex(long effectID)
	{
		if (_effectToPool.TryGetValue(effectID, out var value))
		{
			return value;
		}
		return -1;
	}
}
public class ParticleEffectsPoolStatic<T> : ParticleEffectsPool where T : ParticleEffectsPool
{
	protected static T gInstance;

	public static T Instance => gInstance;

	protected override void OnPoolAwake()
	{
		if ((bool)gInstance && gInstance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			gInstance = this as T;
		}
	}
}
public class PartyInABox : MonoBehaviour
{
	[Serializable]
	private struct ForceTransform
	{
		public Transform transform;

		public UnityEngine.Vector3 localPosition;

		public UnityEngine.Quaternion localRotation;

		public void Apply()
		{
			transform.localPosition = localPosition;
			transform.localRotation = localRotation;
		}
	}

	[SerializeField]
	private TransferrableObject parentHoldable;

	[SerializeField]
	private ParticleSystem particles;

	[SerializeField]
	private Animation anim;

	[SerializeField]
	private SpringyWobbler spring;

	[SerializeField]
	private AudioSource partyAudio;

	[SerializeField]
	private float partyHapticStrength;

	[SerializeField]
	private float partyHapticDuration;

	private bool isReleased;

	[SerializeField]
	private ForceTransform[] forceTransforms;

	private void Awake()
	{
		Reset();
	}

	private void OnEnable()
	{
		Reset();
	}

	public void Cranked_ReleaseParty()
	{
		if (parentHoldable.IsLocalObject())
		{
			ReleaseParty();
		}
	}

	public void ReleaseParty()
	{
		if (!isReleased)
		{
			if (parentHoldable.IsLocalObject())
			{
				parentHoldable.itemState |= TransferrableObject.ItemStates.State0;
				GorillaTagger.Instance.StartVibration(forLeftController: true, partyHapticStrength, partyHapticDuration);
				GorillaTagger.Instance.StartVibration(forLeftController: false, partyHapticStrength, partyHapticDuration);
			}
			isReleased = true;
			spring.enabled = true;
			anim.Play();
			particles.Play();
			partyAudio.Play();
		}
	}

	private void Update()
	{
		if (parentHoldable.IsLocalObject())
		{
			return;
		}
		if (parentHoldable.itemState.HasFlag(TransferrableObject.ItemStates.State0))
		{
			if (!isReleased)
			{
				ReleaseParty();
			}
		}
		else if (isReleased)
		{
			Reset();
		}
	}

	public void Reset()
	{
		isReleased = false;
		parentHoldable.itemState &= (TransferrableObject.ItemStates)(-2);
		spring.enabled = false;
		anim.Stop();
		ForceTransform[] array = forceTransforms;
		foreach (ForceTransform forceTransform in array)
		{
			forceTransform.Apply();
		}
	}
}
public abstract class ProjectileWeapon : TransferrableObject
{
	[SerializeField]
	protected GameObject projectilePrefab;

	[SerializeField]
	private GameObject projectileTrail;

	public AudioClip[] shootSfxClips;

	public AudioSource shootSfx;

	protected abstract UnityEngine.Vector3 GetLaunchPosition();

	protected abstract UnityEngine.Vector3 GetLaunchVelocity();

	internal override void OnEnable()
	{
		base.OnEnable();
		if (base.myOnlineRig != null)
		{
			base.myOnlineRig.projectileWeapon = this;
		}
		if (base.myRig != null)
		{
			base.myRig.projectileWeapon = this;
		}
	}

	protected void LaunchProjectile()
	{
		int hash = PoolUtils.GameObjHashCode(projectilePrefab);
		int trailHash = PoolUtils.GameObjHashCode(projectileTrail);
		GameObject gameObject = ObjectPools.instance.Instantiate(hash);
		float num = Mathf.Abs(base.transform.lossyScale.x);
		gameObject.transform.localScale = UnityEngine.Vector3.one * num;
		UnityEngine.Vector3 launchPosition = GetLaunchPosition();
		UnityEngine.Vector3 launchVelocity = GetLaunchVelocity();
		GetIsOnTeams(out var blueTeam, out var orangeTeam, out var shouldUsePlayerColor);
		AttachTrail(trailHash, gameObject, launchPosition, blueTeam, orangeTeam, shouldUsePlayerColor && (bool)targetRig, targetRig ? targetRig.playerColor : default(Color));
		SlingshotProjectile component = gameObject.GetComponent<SlingshotProjectile>();
		if (NetworkSystem.Instance.InRoom)
		{
			int projectileCount = ProjectileTracker.AddAndIncrementLocalProjectile(component, launchVelocity, launchPosition, num);
			component.Launch(launchPosition, launchVelocity, NetworkSystem.Instance.LocalPlayer, blueTeam, orangeTeam, projectileCount, num, shouldUsePlayerColor, base.myRig.playerColor);
			_ = currentState;
			RoomSystem.SendLaunchProjectile(launchPosition, launchVelocity, RoomSystem.ProjectileSource.ProjectileWeapon, projectileCount, randomColour: false, byte.MaxValue, byte.MaxValue, byte.MaxValue, byte.MaxValue);
			PlayLaunchSfx();
		}
		else
		{
			component.Launch(launchPosition, launchVelocity, NetworkSystem.Instance.LocalPlayer, blueTeam, orangeTeam, 0, num, shouldUsePlayerColor, base.myRig.playerColor);
			PlayLaunchSfx();
		}
		PlayerGameEvents.LaunchedProjectile(projectilePrefab.name);
	}

	internal virtual SlingshotProjectile LaunchNetworkedProjectile(UnityEngine.Vector3 location, UnityEngine.Vector3 velocity, RoomSystem.ProjectileSource projectileSource, int projectileCounter, float scale, bool shouldOverrideColor, Color color, PhotonMessageInfoWrapped info)
	{
		GameObject gameObject = null;
		SlingshotProjectile slingshotProjectile = null;
		NetPlayer player = NetworkSystem.Instance.GetPlayer(info.senderID);
		try
		{
			int hash = -1;
			int num = -1;
			if (projectileSource == RoomSystem.ProjectileSource.ProjectileWeapon)
			{
				if (currentState == PositionState.OnChest || currentState == PositionState.None)
				{
					return null;
				}
				hash = PoolUtils.GameObjHashCode(projectilePrefab);
				num = PoolUtils.GameObjHashCode(projectileTrail);
			}
			gameObject = ObjectPools.instance.Instantiate(hash);
			slingshotProjectile = gameObject.GetComponent<SlingshotProjectile>();
			GetIsOnTeams(out var blueTeam, out var orangeTeam, out var shouldUsePlayerColor);
			if (shouldUsePlayerColor && !shouldOverrideColor && (bool)targetRig)
			{
				shouldOverrideColor = true;
				color = targetRig.playerColor;
			}
			if (num != -1)
			{
				AttachTrail(num, slingshotProjectile.gameObject, location, blueTeam, orangeTeam, shouldOverrideColor, color);
			}
			slingshotProjectile.Launch(location, velocity, player, blueTeam, orangeTeam, projectileCounter, scale, shouldOverrideColor, color);
			PlayLaunchSfx();
		}
		catch
		{
			MonkeAgent.instance.SendReport("projectile error", player.UserId, player.NickName);
			if ((object)slingshotProjectile != null && (bool)slingshotProjectile)
			{
				slingshotProjectile.transform.position = UnityEngine.Vector3.zero;
				slingshotProjectile.Deactivate();
				slingshotProjectile = null;
			}
			else if (gameObject.IsNotNull())
			{
				ObjectPools.instance.Destroy(gameObject);
			}
		}
		return slingshotProjectile;
	}

	protected void GetIsOnTeams(out bool blueTeam, out bool orangeTeam, out bool shouldUsePlayerColor)
	{
		NetPlayer player = OwningPlayer();
		blueTeam = false;
		orangeTeam = false;
		shouldUsePlayerColor = false;
		if (GorillaGameManager.instance != null)
		{
			GorillaPaintbrawlManager component = GorillaGameManager.instance.GetComponent<GorillaPaintbrawlManager>();
			if (component != null)
			{
				blueTeam = component.OnBlueTeam(player);
				orangeTeam = component.OnRedTeam(player);
				shouldUsePlayerColor = !blueTeam && !orangeTeam;
			}
		}
	}

	private void AttachTrail(int trailHash, GameObject newProjectile, UnityEngine.Vector3 location, bool blueTeam, bool orangeTeam, bool shouldOverrideColor = false, Color overrideColor = default(Color))
	{
		GameObject gameObject = ObjectPools.instance.Instantiate(trailHash);
		SlingshotProjectileTrail component = gameObject.GetComponent<SlingshotProjectileTrail>();
		if (GTExt.IsNull(component))
		{
			ObjectPools.instance.Destroy(gameObject);
		}
		newProjectile.transform.position = location;
		component.AttachTrail(newProjectile, blueTeam, orangeTeam, shouldOverrideColor, overrideColor);
	}

	private void PlayLaunchSfx()
	{
		if (shootSfx != null && shootSfxClips != null && shootSfxClips.Length != 0)
		{
			shootSfx.GTPlayOneShot(shootSfxClips[UnityEngine.Random.Range(0, shootSfxClips.Length)]);
		}
	}
}
public interface IProximityEffectReceiver
{
	void OnProximityCalculated(float distance, float alignment, float parallel);
}
public class ProximityEffect : MonoBehaviour, ITickSystemTick
{
	[Serializable]
	private class ProximityEvent
	{
		[SerializeField]
		[Range(0f, 1f)]
		[Tooltip("High-threshold events will only fire if the alignment score is above this value.")]
		private float highThreshold = 0.5f;

		[SerializeField]
		[Tooltip("Wait this many seconds before activating the high-threshold events.")]
		private float highThresholdBufferTime;

		[SerializeField]
		[Range(0f, 1f)]
		[Tooltip("Low-threshold events will only fire if the alignment score is below this value.")]
		private float lowThreshold = 0.3f;

		[SerializeField]
		[Tooltip("Wait this many seconds before activating the low-threshold events.")]
		private float lowThresholdBufferTime;

		public UnityEvent onThresholdHigh;

		public UnityEvent onThresholdLow;

		private bool wasAboveThreshold;

		private bool wasBelowThreshold = true;

		private float lastThresholdTime = -100f;

		public bool Evaluate(float score)
		{
			if (score >= highThreshold)
			{
				if (!wasAboveThreshold && Time.time - lastThresholdTime >= highThresholdBufferTime)
				{
					onThresholdHigh?.Invoke();
					wasAboveThreshold = true;
					wasBelowThreshold = false;
				}
				if (wasAboveThreshold)
				{
					lastThresholdTime = Time.time;
				}
				return true;
			}
			if (score < lowThreshold)
			{
				if (!wasBelowThreshold && Time.time - lastThresholdTime >= lowThresholdBufferTime)
				{
					onThresholdLow?.Invoke();
					wasAboveThreshold = false;
					wasBelowThreshold = true;
				}
				if (wasBelowThreshold)
				{
					lastThresholdTime = Time.time;
				}
			}
			return false;
		}

		public void ResetAllEvents()
		{
			wasAboveThreshold = false;
			wasBelowThreshold = true;
		}
	}

	[SerializeField]
	private Transform leftTransform;

	[SerializeField]
	private Transform rightTransform;

	[SerializeField]
	[Tooltip("How many times AddTrigger() needs to be called before the events are allowed to be invoked. Used for pausing events until certain actions are performed (like squeezing the triggers of both controllers).")]
	private int triggersToActivate;

	[Space]
	[SerializeField]
	[Tooltip("The transform that moves to follow the midpoint of the left and right transforms.")]
	private Transform centerTransform;

	private const string SHOW_CONDITION = "@centerTransform != null";

	[SerializeField]
	private float positionCTLerpSpeed = 10f;

	[SerializeField]
	private bool rotateCT;

	private const string SHOW_ROTATE_CONDITION = "@centerTransform != null && rotateCT";

	[SerializeField]
	private float rotationCTLerpSpeed = 10f;

	[SerializeField]
	private bool scaleCT;

	private const string SHOW_SCALE_CONDITION = "@centerTransform != null && scaleCT";

	[SerializeField]
	private float scaleCTLerpSpeed = 10f;

	[SerializeField]
	private float scaleCTMult = 1f;

	[Space]
	[SerializeField]
	[Tooltip("The curves that get evaluated to determine the alignment score. They get multiplied together, so their Y values should all range from 0-1. The result is compared against the thresholds of the ProximityEvents.")]
	private ProximityEffectScoreCurvesSO scoreCurves;

	[Space]
	[SerializeField]
	private ContinuousPropertyArray continuousProperties;

	[SerializeField]
	private UnityEvent<float> onScoreCalculated;

	[SerializeField]
	private ProximityEvent[] events;

	[Header("Editor Only")]
	[SerializeField]
	private UnityEngine.Vector3 defaultLeftHandLocalPosition = new UnityEngine.Vector3(-0.0568f, 0.04311f, 0.00249f);

	[SerializeField]
	private UnityEngine.Vector3 defaultLeftHandLocalEuler = new UnityEngine.Vector3(173.176f, 80.201f, 3.615f);

	[Header("Visualization is currently NOT WORKING IN PLAY MODE due to tick optimization")]
	[SerializeField]
	private bool enableVisualization = true;

	[SerializeField]
	private Material visualizationMaterial;

	[SerializeField]
	[Range(0f, 1f)]
	private float visualizationLineThickness = 0.01f;

	[SerializeField]
	[HideInInspector]
	private LineRenderer visualizer;

	private List<IProximityEffectReceiver> receivers;

	private VRRig rig;

	private bool anyAboveThreshold;

	private int numTriggers;

	public bool TickRunning { get; set; }

	private void Awake()
	{
		rig = GetComponentInParent<VRRig>();
		enableVisualization = false;
		if ((bool)visualizer)
		{
			UnityEngine.Object.Destroy(visualizer);
		}
	}

	public void AddReceiver(IProximityEffectReceiver receiver)
	{
		if (receivers == null)
		{
			receivers = new List<IProximityEffectReceiver> { receiver };
		}
		else if (!receivers.Contains(receiver))
		{
			receivers.Add(receiver);
		}
	}

	public void RemoveReceiver(IProximityEffectReceiver receiver)
	{
		receivers.Remove(receiver);
	}

	private void StartCalculating()
	{
		centerTransform.position = (leftTransform.position + rightTransform.position) / 2f;
		TickSystem<object>.AddTickCallback(this);
	}

	private void StopCalculating()
	{
		ProximityEvent[] array = events;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].ResetAllEvents();
		}
		continuousProperties?.ApplyAll(0f);
		onScoreCalculated?.Invoke(0f);
		TickSystem<object>.RemoveTickCallback(this);
	}

	private void OnEnable()
	{
		if (triggersToActivate == 0)
		{
			StartCalculating();
		}
	}

	private void OnDisable()
	{
		if (triggersToActivate == 0)
		{
			StopCalculating();
		}
	}

	public void AddTrigger()
	{
		if (numTriggers < triggersToActivate)
		{
			numTriggers++;
			if (numTriggers == triggersToActivate)
			{
				StartCalculating();
			}
		}
	}

	public void RemoveTrigger()
	{
		if (numTriggers > 0)
		{
			if (numTriggers == triggersToActivate)
			{
				StopCalculating();
			}
			numTriggers--;
		}
	}

	private void CalculateProximityScores()
	{
		CalculateProximityScores(drawGizmos: true, out var _, out var _, out var _, out var _);
	}

	private void CalculateProximityScores(out float distance, out float alignment, out float parallel, out UnityEngine.Vector3 midpoint)
	{
		CalculateProximityScores(drawGizmos: false, out distance, out alignment, out parallel, out midpoint);
	}

	private void CalculateProximityScores(bool drawGizmos, out float distance, out float alignment, out float parallel, out UnityEngine.Vector3 midpoint)
	{
		float num = ((rig != null) ? rig.scaleFactor : 1f);
		UnityEngine.Vector3 position = leftTransform.position;
		UnityEngine.Vector3 position2 = rightTransform.position;
		UnityEngine.Vector3 forward = leftTransform.forward;
		UnityEngine.Vector3 forward2 = rightTransform.forward;
		UnityEngine.Vector3 vector = (position2 - position) / num;
		float magnitude = vector.magnitude;
		UnityEngine.Vector3 vector2 = vector / magnitude;
		distance = scoreCurves.distanceModifierCurve.Evaluate(magnitude);
		alignment = scoreCurves.alignmentModifierCurve.Evaluate(0f - UnityEngine.Vector3.Dot(forward, forward2));
		parallel = scoreCurves.parallelModifierCurve.Evaluate((UnityEngine.Vector3.Dot(forward, vector2) + UnityEngine.Vector3.Dot(forward2, -vector2)) / 2f);
		midpoint = position + 0.5f * vector;
	}

	private void MoveTransform(Transform target, float score, UnityEngine.Vector3 midpoint)
	{
		target.GetPositionAndRotation(out var position, out var rotation);
		UnityEngine.Vector3 vector = UnityEngine.Vector3.Lerp(position, midpoint, ExpT(positionCTLerpSpeed));
		if (rotateCT)
		{
			UnityEngine.Vector3 vector2 = (vector - position) / Time.deltaTime;
			if (vector2 != UnityEngine.Vector3.zero)
			{
				UnityEngine.Quaternion b = UnityEngine.Quaternion.LookRotation(vector2);
				UnityEngine.Quaternion a = UnityEngine.Quaternion.LookRotation(vector - rig.syncPos);
				UnityEngine.Quaternion rotation2 = UnityEngine.Quaternion.Slerp(rotation, UnityEngine.Quaternion.Slerp(a, b, vector2.magnitude), ExpT(rotationCTLerpSpeed));
				target.SetPositionAndRotation(vector, rotation2);
			}
		}
		else
		{
			target.position = vector;
		}
		if (scaleCT)
		{
			target.localScale = UnityEngine.Vector3.Lerp(target.localScale, score * scaleCTMult * UnityEngine.Vector3.one, ExpT(scaleCTLerpSpeed));
		}
		static float ExpT(float speed)
		{
			return 1f - Mathf.Exp((0f - speed) * Time.deltaTime);
		}
	}

	public void Tick()
	{
		CalculateProximityScores(out var distance, out var alignment, out var parallel, out var midpoint);
		if (receivers != null)
		{
			for (int i = 0; i < receivers.Count; i++)
			{
				receivers[i].OnProximityCalculated(distance, alignment, parallel);
			}
		}
		float num = distance * alignment * parallel;
		continuousProperties?.ApplyAll(num);
		onScoreCalculated?.Invoke(num);
		if (centerTransform != null)
		{
			MoveTransform(centerTransform, num, midpoint);
		}
		anyAboveThreshold = false;
		ProximityEvent[] array = events;
		foreach (ProximityEvent proximityEvent in array)
		{
			anyAboveThreshold = proximityEvent.Evaluate(num) || anyAboveThreshold;
		}
	}
}
public class ProximityEffectScoreCurvesSO : ScriptableObject
{
	[Tooltip("How far apart the transforms are. A distance. Contributes 'red' to the debug line. Y value should be in the range 0-1.")]
	public AnimationCurve distanceModifierCurve;

	[Tooltip("How closely the transforms' Z vectors are pointed towards each other. A dot product. Contributes 'green' to the debug line. Y value should be in the range 0-1.")]
	public AnimationCurve alignmentModifierCurve;

	[Tooltip("Whether each transform is in front of the other transform. The average of two dot products. Contributes 'blue' to the debug line. Y value should be in the range 0-1.")]
	public AnimationCurve parallelModifierCurve;
}
public class RadioButtonGroupWearable : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private bool AllowSelectNone = true;

	[SerializeField]
	private GorillaPressableButton[] buttons;

	[SerializeField]
	private UnityEvent<int> OnSelectionChanged;

	[Tooltip("This is to determine what bit to change in VRRig.WearablesPackedStates.")]
	[SerializeField]
	private VRRig.WearablePackedStateSlots assignedSlot = VRRig.WearablePackedStateSlots.Pants1;

	private int lastReportedState;

	private VRRig ownerRig;

	private GTBitOps.BitWriteInfo stateBitsWriteInfo;

	public bool IsSpawned { get; set; }

	public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

	private void Start()
	{
		stateBitsWriteInfo = VRRig.WearablePackedStatesBitWriteInfos[(int)assignedSlot];
		if (ownerRig.isLocal)
		{
			return;
		}
		GorillaPressableButton[] array = buttons;
		for (int i = 0; i < array.Length; i++)
		{
			Collider component = array[i].GetComponent<Collider>();
			if (component != null)
			{
				component.enabled = false;
			}
		}
	}

	private void OnEnable()
	{
		SharedRefreshState();
	}

	private int GetCurrentState()
	{
		return GTBitOps.ReadBits(ownerRig.WearablePackedStates, stateBitsWriteInfo.index, stateBitsWriteInfo.valueMask);
	}

	private void Update()
	{
		if (!ownerRig.isLocal && lastReportedState != GetCurrentState())
		{
			SharedRefreshState();
		}
	}

	public void SharedRefreshState()
	{
		int currentState = GetCurrentState();
		int num = (AllowSelectNone ? (currentState - 1) : currentState);
		for (int i = 0; i < buttons.Length; i++)
		{
			buttons[i].isOn = num == i;
			buttons[i].UpdateColor();
		}
		if (lastReportedState != currentState)
		{
			lastReportedState = currentState;
			OnSelectionChanged.Invoke(currentState);
		}
	}

	public void OnPress(GorillaPressableButton button)
	{
		int currentState = GetCurrentState();
		int num = Array.IndexOf(buttons, button);
		if (AllowSelectNone)
		{
			num++;
		}
		int value = num;
		if (AllowSelectNone && num == currentState)
		{
			value = 0;
		}
		ownerRig.WearablePackedStates = GTBitOps.WriteBits(ownerRig.WearablePackedStates, stateBitsWriteInfo, value);
		SharedRefreshState();
	}

	public void OnSpawn(VRRig rig)
	{
		ownerRig = rig;
	}

	public void OnDespawn()
	{
	}
}
public class SimpleSpeedTracker : MonoBehaviour, IGorillaSliceableSimple
{
	private enum AxisFilter
	{
		None,
		X,
		Y,
		Z
	}

	[Header("Settings")]
	[Tooltip("Transform whose movement speed is tracked. If left empty, uses this object's transform.")]
	[SerializeField]
	private Transform target;

	[Tooltip("If enabled, speed and direction calculations use world (global) space, otherwise local space.\nUse Local Space when you want speed relative to the object's facing direction (e.g., how fast a sword swings forward)")]
	[SerializeField]
	private bool useWorldAxes;

	[Tooltip("Optional transform defining a custom world reference.\nIf set, that transform's Right/Up/Forward axes are treated as world axes.\nIf left empty, Unity's global world axes are used.")]
	[SerializeField]
	private Transform worldSpace;

	[Tooltip("If true, uses raw instantaneous speed without smoothing.\nIf false, smooths speed using the Responsiveness setting below.")]
	[SerializeField]
	private bool useRawSpeed;

	[SerializeField]
	private float responsiveness = 10f;

	[SerializeField]
	private AnimationCurve postprocessCurve = AnimationCurve.Linear(0f, 0f, 10f, 10f);

	[Header("Axis Filter")]
	[Tooltip("Optionally restrict speed tracking to a single axis.\nWhen set, speed is signed: positive = moving along the axis, negative = moving against it.\nAxes are resolved using the Space settings above (Local vs World).")]
	[SerializeField]
	private AxisFilter trackAxis;

	[Header("Property Output")]
	[SerializeField]
	private ContinuousPropertyArray continuousProperties;

	[Header("Events")]
	[Tooltip("Speed threshold used to trigger the Above/Below events.\nWhen an axis filter is set, this compares against absolute speed on that axis.")]
	[SerializeField]
	private float eventThreshold = 1f;

	public UnityEvent<float> onSpeedUpdated;

	public UnityEvent onSpeedAboveThreshold;

	public UnityEvent onSpeedBelowThreshold;

	[Tooltip("Signed speed along the positive axis direction required to fire onAbovePositiveThreshold / onBelowPositiveThreshold.")]
	[SerializeField]
	private float positiveThreshold = 2f;

	public UnityEvent onAbovePositiveThreshold;

	public UnityEvent onBelowPositiveThreshold;

	[Tooltip("Signed speed threshold for the negative axis direction. Enter as a negative number.\nFires onAboveNegativeThreshold / onBelowNegativeThreshold when signed speed crosses this value.")]
	[SerializeField]
	private float negativeThreshold = -2f;

	public UnityEvent onAboveNegativeThreshold;

	public UnityEvent onBelowNegativeThreshold;

	[Header("Debug")]
	[Tooltip("Current displayed speed value (raw or smoothed). Signed when Axis Filter is set.")]
	public float debugCurrentSpeed;

	private float lastSpeed;

	private float lastRawSpeed;

	private UnityEngine.Vector3 lastVelocity;

	private UnityEngine.Vector3 lastPos;

	private float lastSliceTime;

	private bool wasAboveThreshold;

	private bool wasMovingPositive;

	private bool wasMovingNegative;

	private bool HasAxisFilter => trackAxis != AxisFilter.None;

	public void OnEnable()
	{
		if (target == null)
		{
			target = base.transform;
		}
		lastPos = target.position;
		lastSliceTime = Time.time;
		lastVelocity = UnityEngine.Vector3.zero;
		lastRawSpeed = 0f;
		lastSpeed = 0f;
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void SliceUpdate()
	{
		float num = Mathf.Max(1E-06f, Time.time - lastSliceTime);
		UnityEngine.Vector3 position = target.position;
		UnityEngine.Vector3 lhs = (position - lastPos) / num;
		float num2 = trackAxis switch
		{
			AxisFilter.X => UnityEngine.Vector3.Dot(lhs, ResolveAxisRight()), 
			AxisFilter.Y => UnityEngine.Vector3.Dot(lhs, ResolveAxisUp()), 
			AxisFilter.Z => UnityEngine.Vector3.Dot(lhs, ResolveAxisForward()), 
			_ => lhs.magnitude, 
		};
		lastSpeed = (useRawSpeed ? num2 : Mathf.Lerp(lastSpeed, num2, 1f - Mathf.Exp((0f - responsiveness) * num)));
		float time = Mathf.Abs(lastSpeed);
		float f = postprocessCurve.Evaluate(time);
		continuousProperties.ApplyAll(f);
		float num3 = (useRawSpeed ? num2 : lastSpeed);
		onSpeedUpdated?.Invoke(num3);
		debugCurrentSpeed = num3;
		bool flag = Mathf.Abs(num3) >= eventThreshold;
		if (flag && !wasAboveThreshold)
		{
			onSpeedAboveThreshold?.Invoke();
		}
		else if (!flag && wasAboveThreshold)
		{
			onSpeedBelowThreshold?.Invoke();
		}
		wasAboveThreshold = flag;
		if (HasAxisFilter)
		{
			bool flag2 = num3 >= positiveThreshold;
			if (flag2 && !wasMovingPositive)
			{
				onAbovePositiveThreshold?.Invoke();
			}
			else if (!flag2 && wasMovingPositive)
			{
				onBelowPositiveThreshold?.Invoke();
			}
			wasMovingPositive = flag2;
			bool flag3 = num3 <= negativeThreshold;
			if (flag3 && !wasMovingNegative)
			{
				onAboveNegativeThreshold?.Invoke();
			}
			else if (!flag3 && wasMovingNegative)
			{
				onBelowNegativeThreshold?.Invoke();
			}
			wasMovingNegative = flag3;
		}
		lastVelocity = lhs;
		lastRawSpeed = num2;
		lastPos = position;
		lastSliceTime = Time.time;
	}

	public float GetPostProcessSpeed()
	{
		return postprocessCurve.Evaluate(Mathf.Abs(lastSpeed));
	}

	public float GetRawSpeed()
	{
		return lastRawSpeed;
	}

	public UnityEngine.Vector3 GetWorldVelocity()
	{
		return lastVelocity;
	}

	public UnityEngine.Vector3 GetLocalVelocity()
	{
		if (useWorldAxes)
		{
			return lastVelocity;
		}
		if (target != null)
		{
			return target.InverseTransformDirection(lastVelocity);
		}
		return base.transform.InverseTransformDirection(lastVelocity);
	}

	public float GetSignedSpeedAlongForward(Transform reference)
	{
		if (reference == null)
		{
			return 0f;
		}
		return UnityEngine.Vector3.Dot(lastVelocity, reference.forward);
	}

	public float GetSignedSpeedX()
	{
		return UnityEngine.Vector3.Dot(lastVelocity, ResolveAxisRight());
	}

	public float GetSignedSpeedY()
	{
		return UnityEngine.Vector3.Dot(lastVelocity, ResolveAxisUp());
	}

	public float GetSignedSpeedZ()
	{
		return UnityEngine.Vector3.Dot(lastVelocity, ResolveAxisForward());
	}

	public UnityEngine.Vector3 GetVelocityInAxisSpace()
	{
		UnityEngine.Vector3 rhs = ResolveAxisRight();
		UnityEngine.Vector3 rhs2 = ResolveAxisUp();
		UnityEngine.Vector3 rhs3 = ResolveAxisForward();
		return new UnityEngine.Vector3(UnityEngine.Vector3.Dot(lastVelocity, rhs), UnityEngine.Vector3.Dot(lastVelocity, rhs2), UnityEngine.Vector3.Dot(lastVelocity, rhs3));
	}

	private UnityEngine.Vector3 ResolveAxisRight()
	{
		if (useWorldAxes)
		{
			if (worldSpace != null)
			{
				return worldSpace.right;
			}
			return UnityEngine.Vector3.right;
		}
		if (!(target != null))
		{
			return base.transform.right;
		}
		return target.right;
	}

	private UnityEngine.Vector3 ResolveAxisUp()
	{
		if (useWorldAxes)
		{
			if (worldSpace != null)
			{
				return worldSpace.up;
			}
			return UnityEngine.Vector3.up;
		}
		if (!(target != null))
		{
			return base.transform.up;
		}
		return target.up;
	}

	private UnityEngine.Vector3 ResolveAxisForward()
	{
		if (useWorldAxes)
		{
			if (worldSpace != null)
			{
				return worldSpace.forward;
			}
			return UnityEngine.Vector3.forward;
		}
		if (!(target != null))
		{
			return base.transform.forward;
		}
		return target.forward;
	}
}
public class SpeedDrivenAnim : MonoBehaviour
{
	[SerializeField]
	private float speed0;

	[SerializeField]
	private float speed1 = 1f;

	[SerializeField]
	private float maxChangePerSecond = 1f;

	[SerializeField]
	private string animKey = "speed";

	private GorillaVelocityEstimator velocityEstimator;

	private Animator animator;

	private int keyHash;

	private float currentBlend;

	private void Start()
	{
		velocityEstimator = GetComponent<GorillaVelocityEstimator>();
		animator = GetComponent<Animator>();
		keyHash = Animator.StringToHash(animKey);
	}

	private void Update()
	{
		float target = Mathf.InverseLerp(speed0, speed1, velocityEstimator.linearVelocity.magnitude);
		currentBlend = Mathf.MoveTowards(currentBlend, target, maxChangePerSecond * Time.deltaTime);
		animator.SetFloat(keyHash, currentBlend);
	}
}
