public class SpinWithGorillaSpeed : MonoBehaviour
{
	[Tooltip("Get the velocity from this component when determining the spin speed. If this is unset, it will use the unsmoothed velocity of the parent VRRig component.")]
	[SerializeField]
	private GorillaVelocityEstimator optionalVelocityEstimator;

	[SerializeField]
	private UnityEngine.Quaternion axisOfRotation = UnityEngine.Quaternion.identity;

	[SerializeField]
	private UnityEngine.Vector3 centerOfRotation = UnityEngine.Vector3.zero;

	[Tooltip("The reported speed will be divided by this value before being used to sample AnimationCurves, to allow them to be in the range 0-1.")]
	[SerializeField]
	private float maxSpeed;

	[SerializeField]
	private AnimationCurve degreesPerSecondAtSpeed;

	[SerializeField]
	private bool clockwise;

	[Tooltip("The Y component of the reported speed will be multiplied by this value. At 0, falling will have no effect on the rotation speed.")]
	[SerializeField]
	private float verticalSpeedInfluence = 1f;

	[Header("Ticking sound")]
	[Tooltip("After this many degrees of rotation, a \"tick\" sound will play.")]
	[SerializeField]
	private float tickSoundDegrees = 360f;

	[SerializeField]
	private AnimationCurve tickVolumeAtSpeed;

	[SerializeField]
	private AnimationCurve tickPitchAtSpeed;

	[SerializeField]
	private AudioSource tickSound;

	[SerializeField]
	private AudioClip[] tickClips;

	private VRRig rig;

	private UnityEngine.Quaternion initialRotation;

	private UnityEngine.Vector3 spinAxis;

	private float currentAngle;

	private float tickAngle;

	private void Awake()
	{
		rig = GetComponentInParent<VRRig>();
		initialRotation = base.transform.localRotation;
		spinAxis = initialRotation * axisOfRotation * UnityEngine.Vector3.forward;
	}

	private void Update()
	{
		UnityEngine.Vector3 vector = ((optionalVelocityEstimator != null) ? optionalVelocityEstimator.linearVelocity : rig.LatestVelocity());
		vector.y *= verticalSpeedInfluence;
		float time = vector.magnitude / maxSpeed;
		float num = Time.deltaTime * degreesPerSecondAtSpeed.Evaluate(time) * (clockwise ? (-1f) : 1f);
		currentAngle = Mathf.Repeat(currentAngle + num, 360f);
		UnityEngine.Quaternion quaternion2 = initialRotation * UnityEngine.Quaternion.AngleAxis(currentAngle, spinAxis);
		base.transform.SetLocalPositionAndRotation(quaternion2 * centerOfRotation, quaternion2);
		if (tickSound != null && tickClips.Length != 0)
		{
			tickAngle += num;
			if (tickAngle >= tickSoundDegrees)
			{
				tickSound.pitch = tickPitchAtSpeed.Evaluate(time);
				tickSound.volume = tickVolumeAtSpeed.Evaluate(time);
				tickSound.clip = tickClips.GetRandomItem();
				tickSound.GTPlay();
				tickAngle = Mathf.Repeat(tickAngle, tickSoundDegrees);
			}
		}
	}

	private void OnDisable()
	{
		currentAngle = 0f;
		tickAngle = 0f;
	}
}
public class SpringyWobbler : MonoBehaviour
{
	[SerializeField]
	private float stabilizingForce;

	[SerializeField]
	private float drag;

	[SerializeField]
	private float maxDisplacement;

	private Transform[] children;

	[SerializeField]
	private UnityEngine.Vector3 idealEndpointLocalPos;

	[SerializeField]
	private UnityEngine.Vector3 rotateToFaceLocalPos;

	[SerializeField]
	private float startStiffness;

	[SerializeField]
	private float endStiffness;

	private UnityEngine.Vector3 lastIdealEndpointWorldPos;

	private UnityEngine.Vector3 lastEndpointWorldPos;

	private UnityEngine.Vector3 endpointVelocity;

	private void Start()
	{
		int num = 1;
		Transform child = base.transform;
		while (child.childCount > 0)
		{
			child = child.GetChild(0);
			num++;
		}
		children = new Transform[num];
		child = base.transform;
		children[0] = child;
		int num2 = 1;
		while (child.childCount > 0)
		{
			child = child.GetChild(0);
			children[num2] = child;
			num2++;
		}
		lastEndpointWorldPos = children[children.Length - 1].transform.position;
	}

	private void Update()
	{
		float x = base.transform.lossyScale.x;
		UnityEngine.Vector3 vector = base.transform.TransformPoint(idealEndpointLocalPos);
		endpointVelocity += (vector - lastEndpointWorldPos) * stabilizingForce * x * Time.deltaTime;
		UnityEngine.Vector3 vector2 = lastEndpointWorldPos + endpointVelocity * Time.deltaTime;
		float num = maxDisplacement * x;
		if ((vector2 - vector).IsLongerThan(num))
		{
			vector2 = vector + (vector2 - vector).normalized * num;
		}
		endpointVelocity = (vector2 - lastEndpointWorldPos) * (1f - drag) / Time.deltaTime;
		UnityEngine.Vector3 vector3 = base.transform.TransformPoint(rotateToFaceLocalPos);
		UnityEngine.Vector3 upwards = base.transform.TransformDirection(UnityEngine.Vector3.up);
		UnityEngine.Vector3 position = base.transform.position;
		UnityEngine.Vector3 ctrl = position + base.transform.TransformDirection(idealEndpointLocalPos) * startStiffness * x;
		UnityEngine.Vector3 vector4 = vector2;
		UnityEngine.Vector3 ctrl2 = vector4 + (vector3 - vector4).normalized * endStiffness * x;
		for (int i = 1; i < children.Length; i++)
		{
			float num2 = (float)i / (float)(children.Length - 1);
			UnityEngine.Vector3 vector5 = BezierUtils.BezierSolve(num2, position, ctrl, ctrl2, vector4);
			UnityEngine.Vector3 vector6 = BezierUtils.BezierSolve(num2 + 0.1f, position, ctrl, ctrl2, vector4);
			children[i].transform.position = vector5;
			children[i].transform.rotation = UnityEngine.Quaternion.LookRotation(vector6 - vector5, upwards);
		}
		lastIdealEndpointWorldPos = vector;
		lastEndpointWorldPos = vector2;
	}
}
public class StickyHand : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private MeshRenderer flatHand;

	[SerializeField]
	private MeshRenderer regularHand;

	[SerializeField]
	private Rigidbody rb;

	[SerializeField]
	private GameObject stringParent;

	[SerializeField]
	private float surfaceOffsetDistance;

	[SerializeField]
	private float stringMaxAttachLength;

	[SerializeField]
	private float stringDetachLength;

	[SerializeField]
	private float stringTeleportLength;

	[SerializeField]
	private SoundBankPlayer thwackSound;

	[SerializeField]
	private SoundBankPlayer schlupSound;

	private VRRig myRig;

	private bool isLocal;

	private int stateBitIndex;

	private UnityEngine.Vector3 defaultLocalPosition;

	bool ISpawnable.IsSpawned { get; set; }

	public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = rig;
		isLocal = rig.isLocal;
		flatHand.enabled = false;
		defaultLocalPosition = stringParent.transform.InverseTransformPoint(rb.transform.position);
		int num = ((CosmeticSelectedSide == ECosmeticSelectSide.Left) ? 1 : 2);
		stateBitIndex = VRRig.WearablePackedStatesBitWriteInfos[num].index;
	}

	void ISpawnable.OnDespawn()
	{
	}

	private void Update()
	{
		if (isLocal)
		{
			if (rb.isKinematic && (rb.transform.position - stringParent.transform.position).IsLongerThan(stringDetachLength))
			{
				Unstick();
			}
			else if (!rb.isKinematic && (rb.transform.position - stringParent.transform.position).IsLongerThan(stringTeleportLength))
			{
				rb.transform.position = stringParent.transform.TransformPoint(defaultLocalPosition);
			}
			myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, stateBitIndex, rb.isKinematic);
		}
		else if (GTBitOps.ReadBit(myRig.WearablePackedStates, stateBitIndex) != rb.isKinematic)
		{
			if (rb.isKinematic)
			{
				Unstick();
			}
			else
			{
				Stick();
			}
		}
	}

	private void Stick()
	{
		thwackSound.Play();
		flatHand.enabled = true;
		regularHand.enabled = false;
		rb.isKinematic = true;
	}

	private void Unstick()
	{
		schlupSound.Play();
		rb.isKinematic = false;
		flatHand.enabled = false;
		regularHand.enabled = true;
	}

	private void OnCollisionStay(UnityEngine.Collision collision)
	{
		if (isLocal && !rb.isKinematic && !(rb.transform.position - stringParent.transform.position).IsLongerThan(stringMaxAttachLength))
		{
			Stick();
			UnityEngine.Vector3 point = collision.contacts[0].point;
			UnityEngine.Vector3 normal = collision.contacts[0].normal;
			rb.transform.rotation = UnityEngine.Quaternion.LookRotation(normal, rb.transform.up);
			UnityEngine.Vector3 vector = rb.transform.position - point;
			vector -= UnityEngine.Vector3.Dot(vector, normal) * normal;
			rb.transform.position = point + vector + surfaceOffsetDistance * normal;
		}
	}
}
