public class TasselPhysics : MonoBehaviour
{
	[SerializeField]
	private GameObject[] tasselInstances;

	[SerializeField]
	private UnityEngine.Vector3 localCenterOfMass;

	[SerializeField]
	private float gravityStrength;

	[SerializeField]
	private float drag;

	[SerializeField]
	private bool LockXAxis;

	private UnityEngine.Vector3 lastCenterPos;

	private UnityEngine.Vector3 velocity;

	private float centerOfMassLength;

	private UnityEngine.Quaternion rotCorrection;

	private void Awake()
	{
		centerOfMassLength = localCenterOfMass.magnitude;
		if (LockXAxis)
		{
			rotCorrection = UnityEngine.Quaternion.Inverse(UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.right, localCenterOfMass));
		}
		else
		{
			rotCorrection = UnityEngine.Quaternion.Inverse(UnityEngine.Quaternion.LookRotation(localCenterOfMass));
		}
	}

	private void Update()
	{
		float y = base.transform.lossyScale.y;
		velocity *= drag;
		velocity.y -= gravityStrength * y * Time.deltaTime;
		UnityEngine.Vector3 position = base.transform.position;
		UnityEngine.Vector3 vector = lastCenterPos + velocity * Time.deltaTime;
		UnityEngine.Vector3 vector2 = position + (vector - position).normalized * centerOfMassLength * y;
		velocity = (vector2 - lastCenterPos) / Time.deltaTime;
		lastCenterPos = vector2;
		if (LockXAxis)
		{
			GameObject[] array = tasselInstances;
			foreach (GameObject gameObject in array)
			{
				gameObject.transform.rotation = UnityEngine.Quaternion.LookRotation(gameObject.transform.right, vector2 - position) * rotCorrection;
			}
		}
		else
		{
			GameObject[] array = tasselInstances;
			foreach (GameObject gameObject2 in array)
			{
				gameObject2.transform.rotation = UnityEngine.Quaternion.LookRotation(vector2 - position, gameObject2.transform.position - position) * rotCorrection;
			}
		}
	}
}
public class TriggerOnJump : MonoBehaviour, ITickSystemTick
{
	[SerializeField]
	private float minJumpStrength = 1f;

	[SerializeField]
	private float minJumpVertical = 1f;

	[SerializeField]
	private float cooldownTime = 1f;

	[SerializeField]
	private UnityEvent onJumping;

	private RubberDuckEvents _events;

	private bool playerOnGround;

	private float minJumpTime = 0.05f;

	private bool waitingForGrounding;

	private float jumpStartTime;

	private float lastActivationTime;

	private VRRig myRig;

	public bool TickRunning { get; set; }

	private void OnEnable()
	{
		if (GTExt.IsNull(myRig))
		{
			myRig = GetComponentInParent<VRRig>();
		}
		if (_events == null && myRig != null && myRig.Creator != null)
		{
			_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			_events.Init(myRig.creator);
		}
		if (_events != null)
		{
			_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnActivate);
		}
		bool num = !PhotonNetwork.InRoom && myRig != null && myRig.isOfflineVRRig;
		RigContainer playerRig;
		bool flag = PhotonNetwork.InRoom && myRig != null && VRRigCache.Instance.TryGetVrrig(PhotonNetwork.LocalPlayer, out playerRig) && playerRig != null && playerRig.Rig != null && playerRig.Rig == myRig;
		if (num || flag)
		{
			TickSystem<object>.AddCallbackTarget(this);
		}
	}

	private void OnDisable()
	{
		TickSystem<object>.RemoveCallbackTarget(this);
		playerOnGround = false;
		jumpStartTime = 0f;
		lastActivationTime = 0f;
		waitingForGrounding = false;
		if (_events != null)
		{
			_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnActivate);
			UnityEngine.Object.Destroy(_events);
			_events = null;
		}
	}

	private void OnActivate(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		MonkeAgent.IncrementRPCCall(info, "OnJumpActivate");
		if (info.senderID == myRig.creator.ActorNumber && sender == target)
		{
			onJumping.Invoke();
		}
	}

	public void Tick()
	{
		GTPlayer instance = GTPlayer.Instance;
		if (!(instance != null))
		{
			return;
		}
		bool flag = playerOnGround;
		playerOnGround = instance.BodyOnGround || instance.IsHandTouching(isLeftHand: true) || instance.IsHandTouching(isLeftHand: false);
		float time = Time.time;
		if (playerOnGround)
		{
			waitingForGrounding = false;
		}
		if (!playerOnGround && flag)
		{
			jumpStartTime = time;
		}
		if (playerOnGround || waitingForGrounding || !(instance.RigidbodyVelocity.sqrMagnitude > minJumpStrength * minJumpStrength) || !(instance.RigidbodyVelocity.y > minJumpVertical) || !(time > jumpStartTime + minJumpTime))
		{
			return;
		}
		waitingForGrounding = true;
		if (time > lastActivationTime + cooldownTime)
		{
			lastActivationTime = time;
			if (PhotonNetwork.InRoom)
			{
				_events.Activate.RaiseAll();
			}
			else
			{
				onJumping.Invoke();
			}
		}
	}
}
public class TriggerOnSpeed : MonoBehaviour, ITickSystemTick
{
	[SerializeField]
	private float speedThreshold;

	[SerializeField]
	private UnityEvent onFaster;

	[SerializeField]
	private UnityEvent onSlower;

