	{
		TickSystem<object>.RemoveCallbackTarget(this);
	}

	public void Tick()
	{
		bool flag = velocityEstimator.linearVelocity.IsLongerThan(speedThreshold);
		if (flag != wasFaster)
		{
			if (flag)
			{
				onFaster.Invoke();
			}
			else
			{
				onSlower.Invoke();
			}
			wasFaster = flag;
		}
	}
}
public class VoiceShiftCosmetic : MonoBehaviour
{
	private const float PITCH_MIN = 2f / 3f;

	private const float PITCH_MAX = 1.5f;

	private const float VOLUME_MIN = 0f;

	private const float VOLUME_MAX = 1f;

	[SerializeField]
	private bool modifyPitch = true;

	[SerializeField]
	private bool modifyVolume = true;

	[Range(2f / 3f, 1.5f)]
	[SerializeField]
	private float shiftedPitch = 1.5f;

	[Range(0f, 1f)]
	[SerializeField]
	private float shiftedVolume = 1f;

	private float pitch = 1f;

	private float volume = 1f;

	private bool isShifted;

	private VRRig myRig;

	public bool ModifyPitch => modifyPitch;

	public bool ModifyVolume => modifyVolume;

	public bool IsShifted => isShifted;

	public float Pitch
	{
		get
		{
			return pitch;
		}
		set
		{
			if (modifyPitch)
			{
				float num = Mathf.Clamp(value, 2f / 3f, 1.5f);
				pitch = num;
				myRig?.SetVoiceShiftCosmeticsDirty();
			}
		}
	}

	public float Volume
	{
		get
		{
			return volume;
		}
		set
		{
			if (modifyVolume)
			{
				float num = Mathf.Clamp(value, 0f, 1f);
				volume = num;
				myRig?.SetVoiceShiftCosmeticsDirty();
			}
		}
	}

	private void OnEnable()
	{
		if ((object)myRig == null)
		{
			myRig = GetComponentInParent<VRRig>();
		}
		if (!(myRig == null))
		{
			myRig.VoiceShiftCosmetics.Add(this);
			myRig.SetVoiceShiftCosmeticsDirty();
		}
	}

	private void OnDisable()
	{
		if (!(myRig == null))
		{
			myRig.VoiceShiftCosmetics.Remove(this);
			myRig.SetVoiceShiftCosmeticsDirty();
		}
	}

	public void StartVoiceShift()
	{
		if (!isShifted)
		{
			isShifted = true;
			if (modifyPitch)
			{
				Pitch = shiftedPitch;
			}
			if (modifyVolume)
			{
				Volume = shiftedVolume;
			}
		}
	}

	public void StopVoiceShift()
	{
		if (isShifted)
		{
			isShifted = false;
			myRig?.SetVoiceShiftCosmeticsDirty();
		}
	}

	public void ToggleVoiceShift()
	{
		if (isShifted)
		{
			StopVoiceShift();
		}
		else
		{
			StartVoiceShift();
		}
	}
}
public static class CosmeticIDUtils
{
	public static int PlayFabIdToIndexInCategory(string playFabIdString)
	{
		return _PlayFabIdToInt(playFabIdString, 2);
	}

	public static int PlayFabIdToInt(string playFabIdString)
	{
		return _PlayFabIdToInt(playFabIdString, 1);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private static int _PlayFabIdToInt(string playFabIdString, int start)
	{
		if (playFabIdString == null)
		{
			throw new ArgumentException("_PlayFabIdToInt: playFabId cannot be null.");
		}
		if (playFabIdString.Length < 6)
		{
			throw new ArgumentException("_PlayFabIdToInt: playFabId \"" + playFabIdString + "\" cannot be less than 6 chars.");
		}
		if (playFabIdString.Length > 8)
		{
			throw new ArgumentException("_PlayFabIdToInt: playFabId \"" + playFabIdString + "\" cannot be greater than 8 chars.");
		}
		if (playFabIdString[0] == 'L')
		{
			if (playFabIdString[playFabIdString.Length - 1] == '.')
			{
				int num = playFabIdString.Length - 2;
				int num2 = 0;
				for (int i = start; i <= num; i++)
				{
					char c = playFabIdString[i];
					if (c < 'A' || c > 'Z')
					{
						throw new ArgumentException("String must contain only uppercase letters A-Z.");
					}
					int num3 = playFabIdString[i] - 65;
					num2 += num3 * (int)math.pow(26f, num - i);
				}
				return num2;
			}
		}
		throw new ArgumentException("PlayFabIdToIndexInCategory: playFabId must start with 'L' and end with '.', instead got " + playFabIdString + ".");
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static string IntToPlayFabId(int id)
	{
		if (id < 0)
		{
			throw new ArgumentException("Input integer cannot be negative.", "id");
		}
		StringBuilder stringBuilder = new StringBuilder();
		if (id == 0)
		{
			stringBuilder.Append('A');
		}
		else
		{
			for (int num = id; num > 0; num /= 26)
			{
				int num2 = num % 26;
				char value = (char)(65 + num2);
				stringBuilder.Insert(0, value);
			}
		}
		stringBuilder.Insert(0, 'L');
		stringBuilder.Append('.');
		return stringBuilder.ToString();
	}
}
