public class CounterRotator : MonoBehaviour
{
	[SerializeField]
	private GameObject stabilizedObject;

	[SerializeField]
	private ChangingBasicGravityZone gravityCompensator;

	private UnityEngine.Vector3 startingPosition;

	private UnityEngine.Quaternion startingRotation;

	private void Start()
	{
		startingPosition = stabilizedObject.transform.position;
		startingRotation = stabilizedObject.transform.rotation;
	}

	private void LateUpdate()
	{
		UnityEngine.Quaternion quaternion2 = startingRotation * UnityEngine.Quaternion.Inverse(stabilizedObject.transform.rotation);
		base.transform.rotation = quaternion2 * base.transform.rotation;
		UnityEngine.Vector3 vector = startingPosition - stabilizedObject.transform.position;
		base.transform.position += vector;
		if (gravityCompensator != null)
		{
			gravityCompensator.SetGravityDirection(-base.transform.up);
		}
	}
}
