public static class GTVector3Extensions
{
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3 X_Z(this UnityEngine.Vector3 vector)
	{
		return new UnityEngine.Vector3(vector.x, 0f, vector.z);
	}

	public static UnityEngine.Vector3 Sum(this IList<UnityEngine.Vector3> vecs)
	{
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		for (int i = 0; i < vecs.Count; i++)
		{
			zero += vecs[i];
		}
		return zero;
	}

	public static UnityEngine.Vector3 Average(this IList<UnityEngine.Vector3> vecs)
	{
		int count = vecs.Count;
		if (count == 0)
		{
			return UnityEngine.Vector3.zero;
		}
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		for (int i = 0; i < count; i++)
		{
			zero += vecs[i];
		}
		return zero / count;
	}

	public static UnityEngine.Vector3 Sum(this IEnumerable<UnityEngine.Vector3> vecs)
	{
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		foreach (UnityEngine.Vector3 vec in vecs)
		{
			zero += vec;
		}
		return zero;
	}

	public static UnityEngine.Vector3 Average(this IEnumerable<UnityEngine.Vector3> vecs)
	{
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		int num = 0;
		foreach (UnityEngine.Vector3 vec in vecs)
		{
			zero += vec;
			num++;
		}
		if (num == 0)
		{
			return UnityEngine.Vector3.zero;
		}
		return zero / num;
	}
}
