public class GTContactManager : MonoBehaviour
{
	public const int MAX_CONTACTS = 32;

	public static UnityEngine.Matrix4x4[] ShaderData = new UnityEngine.Matrix4x4[32];

	private static GTContactPoint[] _gContactPoints = InitContactPoints(32);

	private static int gNextFree = 0;

	private static SRand gRND = new SRand(DateTime.UtcNow);

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void InitializeOnLoad()
	{
	}

	private static GTContactPoint[] InitContactPoints(int count)
	{
		GTContactPoint[] array = new GTContactPoint[count];
		for (int i = 0; i < count; i++)
		{
			array[i] = new GTContactPoint();
		}
		return array;
	}

	public static void RaiseContact(UnityEngine.Vector3 point, UnityEngine.Vector3 normal)
	{
		if (gNextFree != -1)
		{
			float time = GTShaderGlobals.Time;
			GTContactPoint obj = _gContactPoints[gNextFree];
			obj.contactPoint = point;
			obj.radius = 0.04f;
			obj.counterVelocity = normal;
			obj.timestamp = time;
			obj.lifetime = 2f;
			obj.color = gRND.NextColor();
			obj.free = 0u;
		}
	}

	public static void ProcessContacts()
	{
		UnityEngine.Matrix4x4[] shaderData = ShaderData;
		GTContactPoint[] gContactPoints = _gContactPoints;
		_ = GTShaderGlobals.Frame;
		for (int i = 0; i < 32; i++)
		{
			Transfer(ref gContactPoints[i].data, ref shaderData[i]);
		}
	}

	private static void Transfer(ref UnityEngine.Matrix4x4 from, ref UnityEngine.Matrix4x4 to)
	{
		to.m00 = from.m00;
		to.m01 = from.m01;
		to.m02 = from.m02;
		to.m03 = from.m03;
		to.m10 = from.m10;
		to.m11 = from.m11;
		to.m12 = from.m12;
		to.m13 = from.m13;
		to.m20 = from.m20;
		to.m21 = from.m21;
		to.m22 = from.m22;
		to.m23 = from.m23;
		to.m30 = from.m30;
		to.m31 = from.m31;
		to.m32 = from.m32;
		to.m33 = from.m33;
	}
}
public class GTShaderGlobals : MonoBehaviour, IGorillaSliceableSimple
{
	private static Camera gMainCamera;

	private static Transform gMainCameraXform;

	private static UnityEngine.Vector3 gMainCameraWorldPos;

	[Space]
	private static int gIFrame;

	private static float gTime;

	[Space]
	private static Texture2D gBlueNoiseTex;

	private static UnityEngine.Vector4 gBlueNoiseTexWH;

	[Space]
	private static int gActivePawns;

	[Space]
	private static DateTime gStartTime = DateTime.Today.AddDays(-1.0).ToUniversalTime();

	private static UnityEngine.Matrix4x4[] gPawnData = GorillaPawn.ShaderData;

	private static ShaderHashId _GT_WorldSpaceCameraPos = "_GT_WorldSpaceCameraPos";

	private static ShaderHashId _GT_BlueNoiseTex = "_GT_BlueNoiseTex";

	private static ShaderHashId _GT_BlueNoiseTex_WH = "_GT_BlueNoiseTex_WH";

	private static ShaderHashId _GT_iFrame = "_GT_iFrame";

	private static ShaderHashId _GT_Time = "_GT_Time";

	private static ShaderHashId _GT_PawnData = "_GT_PawnData";

	private static ShaderHashId _GT_PawnActiveCount = "_GT_PawnActiveCount";

	public static UnityEngine.Vector3 WorldSpaceCameraPos => gMainCameraWorldPos;

	public static float Time => gTime;

	public static int Frame => gIFrame;

	private void Awake()
	{
		gMainCamera = Camera.main;
		if ((bool)gMainCamera)
		{
			gMainCameraXform = gMainCamera.transform;
			gMainCameraWorldPos = gMainCameraXform.position;
		}
		SliceUpdate();
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void Initialize()
	{
		InitBlueNoiseTex();
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void SliceUpdate()
	{
		UpdateTime();
		UpdateFrame();
		UpdateCamera();
	}

	private static void UpdateFrame()
	{
		gIFrame = UnityEngine.Time.frameCount;
		Shader.SetGlobalInteger(_GT_iFrame, gIFrame);
	}

	private static void UpdateCamera()
	{
		if ((bool)gMainCameraXform)
		{
			gMainCameraWorldPos = gMainCameraXform.position;
			Shader.SetGlobalVector(_GT_WorldSpaceCameraPos, gMainCameraWorldPos);
		}
	}

	private static void UpdateTime()
	{
		gTime = (float)(DateTime.UtcNow - gStartTime).TotalSeconds;
		Shader.SetGlobalFloat(_GT_Time, gTime);
	}

	private static void UpdatePawns()
	{
		gActivePawns = GorillaPawn.ActiveCount;
		GorillaPawn.SyncPawnData();
		Shader.SetGlobalMatrixArray(_GT_PawnData, gPawnData);
		Shader.SetGlobalInteger(_GT_PawnActiveCount, gActivePawns);
	}

	private static void InitBlueNoiseTex()
	{
		gBlueNoiseTex = Resources.Load<Texture2D>("Graphics/Textures/noise_blue_rgba_128");
		gBlueNoiseTexWH = gBlueNoiseTex.GetTexelSize();
		Shader.SetGlobalTexture(_GT_BlueNoiseTex, gBlueNoiseTex);
		Shader.SetGlobalVector(_GT_BlueNoiseTex_WH, gBlueNoiseTexWH);
	}
}
