	public static GTPosRotConstraintManager instance;

	public static bool hasInstance = false;

	private const int _kComponentsCapacity = 256;

	private const int _kConstraintsCapacity = 1024;

	[NonSerialized]
	public Dictionary<Transform, Transform> originalParent;

	[NonSerialized]
	public Dictionary<Transform, UnityEngine.Vector3> originalOffset;

	[NonSerialized]
	public Dictionary<Transform, UnityEngine.Vector3> originalScale;

	[NonSerialized]
	public Dictionary<Transform, UnityEngine.Quaternion> originalRot;

	[NonSerialized]
	public List<GTPosRotConstraints> constraintsToDisable;

	[OnEnterPlay_Clear]
	private static readonly List<GorillaPosRotConstraint> constraints = new List<GorillaPosRotConstraint>(1024);

	[OnEnterPlay_Clear]
	public static readonly Dictionary<int, Range> componentRanges = new Dictionary<int, Range>(256);

	protected void Awake()
	{
		if (hasInstance && instance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			SetInstance(this);
		}
	}

	protected void OnDestroy()
	{
		if (instance == this)
		{
			hasInstance = false;
			instance = null;
		}
	}

	public void InvokeConstraint(GorillaPosRotConstraint constraint, int index)
	{
		Transform source = constraint.source;
		Transform follower = constraint.follower;
		UnityEngine.Vector3 position = source.position + source.TransformVector(constraint.positionOffset);
		UnityEngine.Quaternion rotation = source.rotation * constraint.rotationOffset;
		follower.SetPositionAndRotation(position, rotation);
	}

	protected void LateUpdate()
	{
		if (constraintsToDisable.Count <= 0)
		{
			return;
		}
		for (int num = constraintsToDisable.Count - 1; num >= 0; num--)
		{
			for (int i = 0; i < constraintsToDisable[num].constraints.Length; i++)
			{
				Transform follower = constraintsToDisable[num].constraints[i].follower;
				if (originalParent.TryGetValue(follower, out var value) && !(follower == null) && !(value == null))
				{
					follower.SetParent(originalParent[follower], worldPositionStays: true);
					follower.localRotation = originalRot[follower];
					follower.localPosition = originalOffset[follower];
					follower.localScale = originalScale[follower];
					InvokeConstraint(constraintsToDisable[num].constraints[i], num);
				}
			}
			constraintsToDisable.RemoveAt(num);
		}
	}

	public static void CreateManager()
	{
		GTPosRotConstraintManager gTPosRotConstraintManager = new GameObject("GTPosRotConstraintManager").AddComponent<GTPosRotConstraintManager>();
		constraints.Clear();
		componentRanges.Clear();
		SetInstance(gTPosRotConstraintManager);
	}

	private static void SetInstance(GTPosRotConstraintManager manager)
	{
		instance = manager;
		hasInstance = true;
		instance.originalParent = new Dictionary<Transform, Transform>();
		instance.originalOffset = new Dictionary<Transform, UnityEngine.Vector3>();
		instance.originalScale = new Dictionary<Transform, UnityEngine.Vector3>();
		instance.originalRot = new Dictionary<Transform, UnityEngine.Quaternion>();
		instance.constraintsToDisable = new List<GTPosRotConstraints>();
		if (UnityEngine.Application.isPlaying)
		{
			manager.transform.SetParent(null, worldPositionStays: false);
			UnityEngine.Object.DontDestroyOnLoad(manager);
		}
	}

	public static void Register(GTPosRotConstraints component)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		int instanceID = component.GetInstanceID();
		if (componentRanges.ContainsKey(instanceID))
		{
			return;
		}
		for (int i = 0; i < component.constraints.Length; i++)
		{
			if (!component.constraints[i].follower)
			{
				UnityEngine.Debug.LogError("Cannot add constraints for GTPosRotConstraints component because the `follower` Transform is null " + $"at index {i}. Path in scene: {component.transform.GetPathQ()}", component);
				return;
			}
			if (!component.constraints[i].source)
			{
				UnityEngine.Debug.LogError("Cannot add constraints for GTPosRotConstraints component because the `source` Transform is null " + $"at index {i}. Path in scene: {component.transform.GetPathQ()}", component);
				return;
			}
		}
		Range value = new Range
		{
			start = constraints.Count,
			end = constraints.Count + component.constraints.Length - 1
		};
		componentRanges.Add(instanceID, value);
		constraints.AddRange(component.constraints);
		if (instance.constraintsToDisable.Contains(component))
		{
			instance.constraintsToDisable.Remove(component);
		}
		for (int j = 0; j < component.constraints.Length; j++)
		{
			Transform follower = component.constraints[j].follower;
			if (instance.originalParent.ContainsKey(follower))
			{
				component.constraints[j].follower.SetParent(instance.originalParent[follower], worldPositionStays: true);
				follower.localRotation = instance.originalRot[follower];
				follower.localPosition = instance.originalOffset[follower];
				follower.localScale = instance.originalScale[follower];
			}
			else
			{
				instance.originalParent[follower] = follower.parent;
				instance.originalRot[follower] = follower.localRotation;
				instance.originalOffset[follower] = follower.localPosition;
				instance.originalScale[follower] = follower.localScale;
			}
			instance.InvokeConstraint(component.constraints[j], j);
			component.constraints[j].follower.SetParent(component.constraints[j].source);
		}
	}

	public static void Unregister(GTPosRotConstraints component)
	{
		int instanceID = component.GetInstanceID();
		if (!hasInstance || !componentRanges.TryGetValue(instanceID, out var value))
		{
			return;
		}
		constraints.RemoveRange(value.start, 1 + value.end - value.start);
		componentRanges.Remove(instanceID);
		int[] array = componentRanges.Keys.ToArray();
		foreach (int key in array)
		{
			Range range = componentRanges[key];
			if (range.start > value.end)
			{
				componentRanges[key] = new Range
				{
					start = range.start - value.end + value.start - 1,
					end = range.end - value.end + value.start - 1
				};
			}
		}
		if (!instance.constraintsToDisable.Contains(component))
		{
			instance.constraintsToDisable.Add(component);
		}
	}
}
public class GTPosRotConstraints : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private bool _shouldCallOnSpawnDuringAwake;

	[Tooltip("Used for actors that get disabled and re-enabled")]
	[SerializeField]
	private bool _registerOnEnable;

	public GorillaPosRotConstraint[] constraints;

	public bool IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	public void Awake()
	{
		if (_shouldCallOnSpawnDuringAwake)
		{
			VRRig componentInParent = GetComponentInParent<VRRig>(includeInactive: true);
			if (!(componentInParent == null))
			{
				((ISpawnable)this).OnSpawn(componentInParent);
			}
		}
	}

	void ISpawnable.OnSpawn(VRRig rig)
	{
		Transform[] outBoneXforms = Array.Empty<Transform>();
		if ((object)rig != null && !GTHardCodedBones.TryGetBoneXforms(rig, out outBoneXforms, out var outErrorMsg))
		{
			UnityEngine.Debug.LogError("GTPosRotConstraints: Error getting bone Transforms: " + outErrorMsg, this);
			return;
		}
		for (int i = 0; i < constraints.Length; i++)
		{
			GorillaPosRotConstraint gorillaPosRotConstraint = constraints[i];
			if (Mathf.Approximately(gorillaPosRotConstraint.rotationOffset.x, 0f) && Mathf.Approximately(gorillaPosRotConstraint.rotationOffset.y, 0f) && Mathf.Approximately(gorillaPosRotConstraint.rotationOffset.z, 0f) && Mathf.Approximately(gorillaPosRotConstraint.rotationOffset.w, 0f))
			{
				gorillaPosRotConstraint.rotationOffset = UnityEngine.Quaternion.identity;
			}
			if (!gorillaPosRotConstraint.follower)
			{
				UnityEngine.Debug.LogError(string.Format("{0}: Disabling component! At index {1}, Transform `follower` is ", "GTPosRotConstraints", i) + "null. Affected component path: " + base.transform.GetPathQ() + "\n- Affected component path: " + base.transform.GetPathQ(), this);
				base.enabled = false;
				return;
			}
			if ((GTHardCodedBones.EBone)gorillaPosRotConstraint.sourceGorillaBone == GTHardCodedBones.EBone.None)
			{
				if (!gorillaPosRotConstraint.source)
				{
					if (string.IsNullOrEmpty(gorillaPosRotConstraint.sourceRelativePath))
					{
						UnityEngine.Debug.LogError(string.Format("{0}: Disabling component! At index {1} Transform `source` is ", "GTPosRotConstraints", i) + "null, not EBone, and `sourceRelativePath` is null or empty.\n- Affected component path: " + base.transform.GetPathQ(), this);
						base.enabled = false;
						return;
					}
					if (!base.transform.TryFindByPath(gorillaPosRotConstraint.sourceRelativePath, out gorillaPosRotConstraint.source))
					{
						UnityEngine.Debug.LogError(string.Format("{0}: Disabling component! At index {1} Transform `source` is ", "GTPosRotConstraints", i) + "null, not EBone, and could not find by path: \"" + gorillaPosRotConstraint.sourceRelativePath + "\"\n- Affected component path: " + base.transform.GetPathQ(), this);
						base.enabled = false;
						return;
					}
				}
				constraints[i] = gorillaPosRotConstraint;
				continue;
			}
			if ((object)rig == null)
			{
				UnityEngine.Debug.LogError("GTPosRotConstraints: Disabling component! `VRRig` could not be found in parents, but " + $"bone at index {i} is set to use EBone `{gorillaPosRotConstraint.sourceGorillaBone}` but without `VRRig` it cannot " + "be resolved.\n- Affected component path: " + base.transform.GetPathQ(), this);
				base.enabled = false;
				return;
			}
			int boneIndex = GTHardCodedBones.GetBoneIndex(gorillaPosRotConstraint.sourceGorillaBone);
			if (boneIndex <= 0)
			{
				UnityEngine.Debug.LogError(string.Format("{0}: (should never happen) Disabling component! At index {1}, could ", "GTPosRotConstraints", i) + $"not find EBone `{gorillaPosRotConstraint.sourceGorillaBone}`.\n" + "- Affected component path: " + base.transform.GetPathQ(), this);
				base.enabled = false;
				return;
			}
			gorillaPosRotConstraint.source = outBoneXforms[boneIndex];
			if (!gorillaPosRotConstraint.source)
			{
				UnityEngine.Debug.LogError(string.Format("{0}: Disabling component! At index {1}, bone {2} was ", "GTPosRotConstraints", i, gorillaPosRotConstraint.sourceGorillaBone) + "not present in `VRRig` path: " + rig.transform.GetPathQ() + "\n- Affected component path: " + base.transform.GetPathQ(), this);
				base.enabled = false;
				return;
			}
			constraints[i] = gorillaPosRotConstraint;
		}
		if (base.isActiveAndEnabled && !_registerOnEnable)
		{
			GTPosRotConstraintManager.Register(this);
		}
	}

	void ISpawnable.OnDespawn()
	{
	}

	protected void OnEnable()
	{
		if (IsSpawned || _registerOnEnable)
		{
			GTPosRotConstraintManager.Register(this);
		}
	}

	protected void OnDisable()
	{
		GTPosRotConstraintManager.Unregister(this);
	}
}
