		_m_serializedEntries.Sort(delegate(GTSerializableKeyValue<TKey, TValue> entry1, GTSerializableKeyValue<TKey, TValue> entry2)
		{
			ref TKey k = ref entry1.k;
			TKey k2 = entry2.k;
