[RequireComponent(typeof(Speaker))]
public class SpeakerVoiceToLoudness : MonoBehaviour
{
	[SerializeField]
	private PlaybackDelaySettings playbackDelaySettings = new PlaybackDelaySettings
	{
		MinDelaySoft = 200,
		MaxDelaySoft = 400,
		MaxDelayHard = 1000
	};

	public float loudness;

	private void Awake()
	{
		Speaker component = GetComponent<Speaker>();
		component.CustomAudioOutFactory = GetVolumeTracking(component);
	}

	private Func<IAudioOut<float>> GetVolumeTracking(Speaker speaker)
	{
		AudioOutDelayControl.PlayDelayConfig pdc = new AudioOutDelayControl.PlayDelayConfig
		{
			Low = playbackDelaySettings.MinDelaySoft,
			High = playbackDelaySettings.MaxDelaySoft,
			Max = playbackDelaySettings.MaxDelayHard
		};
		return () => new SpeakerVoiceLoudnessAudioOut(this, speaker.GetComponent<AudioSource>(), pdc, speaker.Logger, string.Empty, speaker.Logger.IsDebugEnabled);
	}
}
public class SpeakerVoiceLoudnessAudioOut : UnityAudioOut
{
	private SpeakerVoiceToLoudness voiceToLoudness;

	public SpeakerVoiceLoudnessAudioOut(SpeakerVoiceToLoudness speaker, AudioSource audioSource, PlayDelayConfig playDelayConfig, Photon.Voice.ILogger logger, string logPrefix, bool debugInfo)
		: base(audioSource, playDelayConfig, logger, logPrefix, debugInfo)
	{
		voiceToLoudness = speaker;
	}

	public override void OutWrite(float[] data, int offsetSamples)
	{
		float num = 0f;
		for (int i = 0; i < data.Length; i++)
		{
			float num2 = data[i];
			if (!float.IsFinite(num2))
			{
				num2 = (data[i] = 0f);
			}
			else if (num2 > 1f)
			{
				num2 = (data[i] = 1f);
			}
			else if (num2 < -1f)
			{
				num2 = (data[i] = -1f);
			}
			num += Mathf.Abs(num2);
		}
		if (num > 0f)
		{
			float num3 = num / (float)data.Length;
			voiceToLoudness.loudness = num3;
			if (SpeakerVoiceToLoudnessConfig.EnableLoudnessLimit && num3 > SpeakerVoiceToLoudnessConfig.LoudnessLimitThreshold)
			{
				data = SpeakerVoiceToLoudnessConfig.StaticArrays.GetStaticArray(data.Length);
			}
		}
		base.OutWrite(data, offsetSamples);
	}
}
public class SpinParametricAnimation : MonoBehaviour
{
	[Tooltip("Axis to rotate around.")]
	public UnityEngine.Vector3 axis = UnityEngine.Vector3.up;

	[Tooltip("Whether rotation is in World Space or Local Space")]
	public bool WorldSpaceRotation = true;

	[FormerlySerializedAs("speed")]
	[Tooltip("Speed of rotation.")]
	public float revolutionsPerSecond = 0.25f;

	[Tooltip("Affects the progress of the animation over time.")]
	public AnimationCurve timeCurve;

	private float _animationProgress;

	private float _oldAngle;

	protected void OnEnable()
	{
		axis = axis.normalized;
	}

	protected void LateUpdate()
	{
		Transform transform = base.transform;
		_animationProgress = (_animationProgress + Time.deltaTime * revolutionsPerSecond) % 1f;
		float num = timeCurve.Evaluate(_animationProgress) * 360f;
		float angle = num - _oldAngle;
		_oldAngle = num;
		if (WorldSpaceRotation)
		{
			transform.rotation = UnityEngine.Quaternion.AngleAxis(angle, axis) * transform.rotation;
		}
		else
		{
			transform.localRotation = UnityEngine.Quaternion.AngleAxis(angle, axis) * transform.localRotation;
		}
	}
}
public class StringFormatter
{
	private static StringBuilder builder = new StringBuilder();

	private string[] spans;

	private int[] indices;

	public StringFormatter(string[] spans, int[] indices)
	{
		this.spans = spans;
		this.indices = indices;
	}

	public string Format(string term1)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			builder.Append(term1);
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(Func<string> term1)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			builder.Append(term1());
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(string term1, string term2)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			builder.Append((indices[i - 1] == 0) ? term1 : term2);
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(string term1, string term2, string term3)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			switch (indices[i - 1])
			{
			case 0:
				builder.Append(term1);
				break;
			case 1:
				builder.Append(term2);
				break;
			default:
				builder.Append(term3);
				break;
			}
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(Func<string> term1, Func<string> term2)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			if (indices[i - 1] == 0)
			{
				builder.Append(term1());
			}
			else
			{
				builder.Append(term2());
			}
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(Func<string> term1, Func<string> term2, Func<string> term3)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			switch (indices[i - 1])
			{
			case 0:
				builder.Append(term1());
				break;
			case 1:
				builder.Append(term2());
				break;
			default:
				builder.Append(term3());
				break;
			}
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(Func<string> term1, Func<string> term2, Func<string> term3, Func<string> term4)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			switch (indices[i - 1])
			{
			case 0:
				builder.Append(term1());
				break;
			case 1:
				builder.Append(term2());
				break;
			case 2:
				builder.Append(term3());
				break;
			default:
				builder.Append(term4());
				break;
			}
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(params string[] terms)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			builder.Append(terms[indices[i - 1]]);
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public string Format(params Func<string>[] terms)
	{
		builder.Clear();
		builder.Append(spans[0]);
		for (int i = 1; i < spans.Length; i++)
		{
			builder.Append(terms[indices[i - 1]]());
			builder.Append(spans[i]);
		}
		return builder.ToString();
	}

	public static StringFormatter Parse(string input)
	{
		int num = 0;
		List<string> list = new List<string>();
		List<int> list2 = new List<int>();
		while (true)
		{
			int num2 = input.IndexOf('%', num);
			if (num2 == -1)
			{
				break;
			}
			list.Add(input.Substring(num, num2 - num));
			list2.Add(input[num2 + 1] - 48);
			num = num2 + 2;
		}
		list.Add(input.Substring(num));
		return new StringFormatter(list.ToArray(), list2.ToArray());
	}
}
public static class GTPosRotScaleToString
{
	public const string k_LocalPRSLabel = "LocalPRS";

	public const string k_WorldPRSLabel = "WorldPRS";

	public static string ToString(UnityEngine.Vector3 pos, UnityEngine.Vector3 rot, UnityEngine.Vector3 scale, bool isWorldSpace, string parentPath = null)
	{
		string text = (isWorldSpace ? "WorldPRS" : "LocalPRS");
		string text2 = text + " { p=" + ValToStr(pos) + ", r=" + ValToStr(rot) + ", s=" + ValToStr(scale);
		if (!string.IsNullOrEmpty(parentPath))
		{
			text2 = text2 + " parent=\"" + parentPath + "\"";
		}
		return text2 + " }";
	}

	private static string ValToStr(UnityEngine.Vector3 v)
	{
		return $"({v.x:R}, {v.y:R}, {v.z:R})";
	}

	public static bool ParseIsWorldSpace(string input)
	{
		return input.Contains("WorldPRS");
	}

	public static string ParseParentPath(string input)
	{
		MatchCollection matchCollection = Regex.Matches(input, "parent\\s*=\\s*\"(?<parent>.*?)\"");
		if (matchCollection.Count <= 0)
		{
			return null;
		}
		return matchCollection[0].Groups["parent"].Value;
	}

	public static bool TryParsePos(string input, out UnityEngine.Vector3 v)
	{
		return TryParseVec3_internal(GTRegex.k_Pos, input, out v);
	}

	public static bool TryParseRot(string input, out UnityEngine.Vector3 v)
	{
		return TryParseVec3_internal(GTRegex.k_Rot, input, out v);
	}

	public static bool TryParseScale(string input, out UnityEngine.Vector3 v)
	{
		if (!TryParseVec3_internal(GTRegex.k_Scale, input, out v))
		{
			return TryParseVec3_internal(GTRegex.k_Vec3, input, out v);
		}
		return true;
	}

	public static bool TryParseVec3(string input, out UnityEngine.Vector3 v)
	{
		return TryParseVec3_internal(GTRegex.k_Vec3, input, out v);
	}

	private static bool TryParseVec3_internal(Regex regex, string input, out UnityEngine.Vector3 v)
	{
		v = UnityEngine.Vector3.zero;
		MatchCollection matchCollection = regex.Matches(input);
		if (matchCollection.Count <= 0)
		{
			return false;
		}
		v = StringToVector3(matchCollection[0]);
		return true;
	}

	private static UnityEngine.Vector3 StringToVector3(Match match)
	{
		float x = float.Parse(match.Groups["x"].Value);
		float y = float.Parse(match.Groups["y"].Value);
		float z = float.Parse(match.Groups["z"].Value);
		return new UnityEngine.Vector3(x, y, z);
	}
}
