	public static readonly Regex k_Rot = new Regex("\\br\\s*=\\s*\\(\\s*(?<x>(?<=^|[\\s,;()\\[\\]{}\"\"'])-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?(?=$|[\\s,;()\\[\\]{}\"\"']))\\s*,\\s*(?<y>(?<=^|[\\s,;()\\[\\]{}\"\"'])-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?(?=$|[\\s,;()\\[\\]{}\"\"']))\\s*(?:,\\s*(?<z>(?<=^|[\\s,;()\\[\\]{}\"\"'])-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?(?=$|[\\s,;()\\[\\]{}\"\"']))\\s*)?(?:,\\s*(?<w>(?<=^|[\\s,;()\\[\\]{}\"\"'])-?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?(?=$|[\\s,;()\\[\\]{}\"\"']))\\s*)?,?\\)");

