public class TimeOfDayDependentAudio : MonoBehaviour, IGorillaSliceableSimple, IBuildValidation
{
	public AudioSource[] audioSources;

	public float[] volumes;

	public float currentVolume;

	public float stepTime;

	public BetterDayNightManager.WeatherType myWeather;

	public GameObject dependentStuff;

	public GameObject timeOfDayDependent;

	public bool includesAudio;

	public ParticleSystem myParticleSystem;

	private float startingEmissionRate;

	private ParticleSystem.MinMaxCurve newCurve;

	private ParticleSystem.EmissionModule myEmissionModule;

	private float newRate;

	public float positionMultiplierSet;

	public float positionMultiplier = 1f;

	public bool isModified;

	private void Awake()
	{
		stepTime = 1f;
		if (myParticleSystem != null)
		{
			myEmissionModule = myParticleSystem.emission;
			startingEmissionRate = myEmissionModule.rateOverTime.constant;
		}
		if (isModified)
		{
			positionMultiplier = positionMultiplierSet;
		}
		else
		{
			positionMultiplier = 1f;
		}
		if (volumes == null)
		{
			volumes = new float[10];
		}
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.FixedUpdate);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.FixedUpdate);
	}

	public void SliceUpdate()
	{
		isModified = false;
		UpdateTimeOfDay();
	}

	private void UpdateTimeOfDay()
	{
		if (BetterDayNightManager.instance == null)
		{
			return;
		}
		BetterDayNightManager.WeatherType weatherType = BetterDayNightManager.instance.CurrentWeather();
		BetterDayNightManager.WeatherType weatherType2 = BetterDayNightManager.instance.NextWeather();
		bool num = myWeather == BetterDayNightManager.WeatherType.All || myWeather == weatherType || myWeather == weatherType2;
		bool flag = myWeather != BetterDayNightManager.WeatherType.All && weatherType != weatherType2;
		int currentTimeIndex = BetterDayNightManager.instance.currentTimeIndex;
		int num2 = (currentTimeIndex + 1) % BetterDayNightManager.instance.timeOfDayRange.Length;
		int num3 = (currentTimeIndex - 1) % BetterDayNightManager.instance.timeOfDayRange.Length;
		if (num3 < 0)
		{
			num3 = BetterDayNightManager.instance.timeOfDayRange.Length - 1;
		}
		float currentLerp = BetterDayNightManager.instance.currentLerp;
		if (!num)
		{
			if (dependentStuff.activeSelf)
			{
				dependentStuff.SetActive(value: false);
			}
			return;
		}
		if (!dependentStuff.activeSelf && (!includesAudio || dependentStuff != timeOfDayDependent))
		{
			dependentStuff.SetActive(value: true);
		}
		if (includesAudio && timeOfDayDependent != null)
		{
			bool flag2 = volumes[currentTimeIndex] != 0f;
			if (timeOfDayDependent.activeSelf != flag2)
			{
				timeOfDayDependent.SetActive(flag2);
			}
		}
		if (!flag)
		{
			newRate = startingEmissionRate;
			currentVolume = Mathf.Lerp(volumes[num3], volumes[currentTimeIndex], Mathf.Clamp(currentLerp * 20f, 0f, 1f));
		}
		else if (myWeather == weatherType2)
		{
			float t = Mathf.Clamp(currentLerp * 2f - 1f, 0f, 1f);
			newRate = Mathf.Lerp(0f, startingEmissionRate, t);
			currentVolume = Mathf.Lerp(0f, volumes[num2], currentLerp);
		}
		else
		{
			float t2 = Mathf.Clamp(currentLerp * 2f, 0f, 1f);
			newRate = Mathf.Lerp(startingEmissionRate, 0f, t2);
			currentVolume = Mathf.Lerp(volumes[currentTimeIndex], 0f, currentLerp);
		}
		if (myParticleSystem != null)
		{
			myEmissionModule = myParticleSystem.emission;
			myEmissionModule.rateOverTime = newRate;
			bool flag3 = newRate != 0f;
			if (myParticleSystem.gameObject.activeSelf != flag3)
			{
				myParticleSystem.gameObject.SetActive(flag3);
			}
		}
		if (!includesAudio)
		{
			return;
		}
		for (int i = 0; i < audioSources.Length; i++)
		{
			MusicSource component = audioSources[i].gameObject.GetComponent<MusicSource>();
			if (!(component != null) || !component.VolumeOverridden)
			{
				audioSources[i].volume = currentVolume * positionMultiplier;
				audioSources[i].enabled = currentVolume != 0f;
			}
		}
	}

	public bool BuildValidationCheck()
	{
		for (int i = 0; i < audioSources.Length; i++)
		{
			if (audioSources[i] == null)
			{
				UnityEngine.Debug.LogError("audio source array contains null references", this);
				return false;
			}
		}
		if (volumes.Length != 10)
		{
			UnityEngine.Debug.LogError("volumes array is the wrong length! you'll pay for this!", this);
			return false;
		}
		return true;
	}
}
public class ToggleableWearable : MonoBehaviour
{
	public Renderer[] renderers;

	public Animator[] animators;

	public float animationTransitionDuration = 1f;

	[Tooltip("Whether the wearable state is toggled on by default.")]
	public bool startOn;

	[Tooltip("AudioSource to play toggle sounds.")]
	public AudioSource audioSource;

	[Tooltip("Sound to play when toggled on.")]
	public AudioClip toggleOnSound;

	[Tooltip("Sound to play when toggled off.")]
	public AudioClip toggleOffSound;

	[Tooltip("Layer to check for trigger sphere collisions.")]
	public LayerMask layerMask;

	[Tooltip("Radius of the trigger sphere.")]
	public float triggerRadius = 0.2f;

	[Tooltip("Position in local space to move the trigger sphere.")]
	public UnityEngine.Vector3 triggerOffset = UnityEngine.Vector3.zero;

	[Tooltip("This is to determine what bit to change in VRRig.WearablesPackedStates.")]
	public VRRig.WearablePackedStateSlots assignedSlot;

	[Header("Vibration")]
	public float turnOnVibrationDuration = 0.05f;

	public float turnOnVibrationStrength = 0.2f;

	public float turnOffVibrationDuration = 0.05f;

	public float turnOffVibrationStrength = 0.2f;

	private VRRig ownerRig;

	private bool ownerIsLocal;

	private bool isOn;

	[SerializeField]
	private UnityEngine.Vector2 toggleCooldownRange = new UnityEngine.Vector2(0.2f, 0.2f);

	private bool hasAudioSource;

	private readonly Collider[] colliders = new Collider[1];

	private int framesSinceCooldownAndExitingVolume;

	private float toggleCooldownTimer;

	private int assignedSlotBitIndex;

	private static readonly int animParam_Progress = Animator.StringToHash("Progress");

	private float progress;

	[SerializeField]
	private bool oneShot;

	[SerializeField]
	[Tooltip("Seconds before reverting to its default state, as defined by 'Start On.' A value of 0 or less means never.")]
	private float resetTimer;

	private float toggleTimer;

	protected void Awake()
	{
		ownerRig = GetComponentInParent<VRRig>();
		if (ownerRig == null)
		{
			GorillaTagger componentInParent = GetComponentInParent<GorillaTagger>();
			if (componentInParent != null)
			{
				ownerRig = componentInParent.offlineVRRig;
				ownerIsLocal = ownerRig != null;
			}
		}
		if (ownerRig == null)
		{
			UnityEngine.Debug.LogError("TriggerToggler: Disabling cannot find VRRig.");
			base.enabled = false;
			return;
		}
		Renderer[] array = renderers;
		foreach (Renderer renderer in array)
		{
			if (renderer == null)
			{
				UnityEngine.Debug.LogError("TriggerToggler: Disabling because a renderer is null.");
				base.enabled = false;
				break;
			}
			renderer.enabled = startOn;
		}
		hasAudioSource = audioSource != null;
		assignedSlotBitIndex = (int)assignedSlot;
		if (oneShot)
		{
			toggleCooldownRange.x += animationTransitionDuration;
			toggleCooldownRange.y += animationTransitionDuration;
		}
	}

	protected void LateUpdate()
	{
		if (ownerIsLocal)
		{
			toggleCooldownTimer -= Time.deltaTime;
			Transform transform = base.transform;
			if (Physics.OverlapSphereNonAlloc(transform.TransformPoint(triggerOffset), triggerRadius * transform.lossyScale.x, colliders, layerMask) > 0 && toggleCooldownTimer < 0f)
			{
				XRController componentInParent = colliders[0].GetComponentInParent<XRController>();
				if (componentInParent != null)
				{
					LocalToggle(componentInParent.controllerNode == XRNode.LeftHand, playAudio: true, playHaptics: true);
				}
				toggleCooldownTimer = UnityEngine.Random.Range(toggleCooldownRange.x, toggleCooldownRange.y);
				toggleTimer = 0f;
			}
			if (resetTimer > 0f)
			{
				toggleTimer += Time.deltaTime;
				if (toggleTimer > resetTimer && startOn != isOn)
				{
					LocalToggle(isLeftHand: false, playAudio: true, playHaptics: false);
					toggleTimer = 0f;
				}
			}
		}
		else
		{
			bool flag = (ownerRig.WearablePackedStates & (1 << assignedSlotBitIndex)) != 0;
			if (isOn != flag)
			{
				SharedSetState(flag, playAudio: true);
			}
		}
		if (oneShot)
		{
			if (isOn)
			{
				progress = Mathf.MoveTowards(progress, 1f, Time.deltaTime / animationTransitionDuration);
				if (progress == 1f)
				{
					if (ownerIsLocal)
					{
						LocalToggle(isLeftHand: false, playAudio: false, playHaptics: false);
					}
					else
					{
						SharedSetState(state: false, playAudio: false);
					}
					progress = 0f;
				}
			}
		}
		else
		{
			progress = Mathf.MoveTowards(progress, isOn ? 1f : 0f, Time.deltaTime / animationTransitionDuration);
		}
		Animator[] array = animators;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetFloat(animParam_Progress, progress);
		}
	}

	private void LocalToggle(bool isLeftHand, bool playAudio, bool playHaptics)
	{
		ownerRig.WearablePackedStates ^= 1 << assignedSlotBitIndex;
		SharedSetState((ownerRig.WearablePackedStates & (1 << assignedSlotBitIndex)) != 0, playAudio);
		if (playHaptics && (bool)GorillaTagger.Instance)
		{
			GorillaTagger.Instance.StartVibration(isLeftHand, isOn ? turnOnVibrationDuration : turnOffVibrationDuration, isOn ? turnOnVibrationStrength : turnOffVibrationStrength);
		}
	}

	private void SharedSetState(bool state, bool playAudio)
	{
		isOn = state;
		Renderer[] array = renderers;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = isOn;
		}
		if (!playAudio || !hasAudioSource)
		{
			return;
		}
		AudioClip audioClip = (isOn ? toggleOnSound : toggleOffSound);
		if (!(audioClip == null))
		{
			if (oneShot)
			{
				audioSource.clip = audioClip;
				audioSource.GTPlay();
			}
			else
			{
				audioSource.GTPlayOneShot(audioClip);
			}
		}
	}
}
