public static class XSceneRefGlobalHub
{
	private static List<Dictionary<int, XSceneRefTarget>> registry = new List<Dictionary<int, XSceneRefTarget>>
	{
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } },
		new Dictionary<int, XSceneRefTarget> { { 0, null } }
	};

	public static void Register(int ID, XSceneRefTarget obj)
	{
		if (ID > 0)
		{
			int sceneIndex = (int)obj.GetSceneIndex();
			if (sceneIndex >= 0)
			{
				registry[sceneIndex][ID] = obj;
			}
		}
	}

	public static void Unregister(int ID, XSceneRefTarget obj)
	{
		int sceneIndex = (int)obj.GetSceneIndex();
		if (ID > 0 && sceneIndex >= 0)
		{
			if (sceneIndex < 0 || sceneIndex >= registry.Count)
			{
				UnityEngine.Debug.LogErrorFormat(obj, "Invalid scene index {0} cannot remove ID {1}", sceneIndex, ID);
			}
			registry[sceneIndex].Remove(ID);
		}
	}

	public static bool TryResolve(SceneIndex sceneIndex, int ID, out XSceneRefTarget result)
	{
		return registry[(int)sceneIndex].TryGetValue(ID, out result);
	}
}
public class XSceneRefTarget : MonoBehaviour
{
	public int UniqueID;

	[NonSerialized]
	private int lastRegisteredID = -1;

	private static DateTime epoch = new DateTime(2024, 1, 1);

	private static int lastAssignedID;

	private void Awake()
	{
		Register();
	}

	private void Reset()
	{
		UniqueID = CreateNewID();
	}

	private void OnValidate()
	{
		if (!UnityEngine.Application.isPlaying)
		{
			Register();
		}
	}

	public void Register(bool force = false)
	{
		if (UniqueID != lastRegisteredID || force)
		{
			if (lastRegisteredID != -1)
			{
				XSceneRefGlobalHub.Unregister(lastRegisteredID, this);
			}
			XSceneRefGlobalHub.Register(UniqueID, this);
			lastRegisteredID = UniqueID;
		}
	}

	private void OnDestroy()
	{
		XSceneRefGlobalHub.Unregister(UniqueID, this);
	}

	private void AssignNewID()
	{
		UniqueID = CreateNewID();
		Register();
	}

	public static int CreateNewID()
	{
		int num = (int)((DateTime.Now - epoch).TotalSeconds * 8.0 % 2147483646.0) + 1;
		if (num <= lastAssignedID)
		{
			lastAssignedID++;
			return lastAssignedID;
		}
		lastAssignedID = num;
		return num;
	}
}
