[RequireComponent(typeof(Collider))]
public class HandEffectsTester : MonoBehaviour, IHandEffectsTrigger
{
	[SerializeField]
	private TagEffectPack cosmeticEffectPack;

	private Collider triggerZone;

	public IHandEffectsTrigger.Mode mode;

	[SerializeField]
	private float triggerRadius = 0.07f;

	[SerializeField]
	private bool isStatic = true;

	public bool Static => isStatic;

	Transform IHandEffectsTrigger.Transform => base.transform;

	VRRig IHandEffectsTrigger.Rig => null;

	IHandEffectsTrigger.Mode IHandEffectsTrigger.EffectMode => mode;

	bool IHandEffectsTrigger.FingersDown
	{
		get
		{
			if (mode == IHandEffectsTrigger.Mode.FistBump || mode == IHandEffectsTrigger.Mode.HighFive_And_FistBump)
			{
				return true;
			}
			return false;
		}
	}

	bool IHandEffectsTrigger.FingersUp
	{
		get
		{
			if (mode == IHandEffectsTrigger.Mode.HighFive || mode == IHandEffectsTrigger.Mode.HighFive_And_FistBump)
			{
				return true;
			}
			return false;
		}
	}

	public Action<IHandEffectsTrigger.Mode> OnTrigger { get; set; }

	public bool RightHand { get; }

	UnityEngine.Vector3 IHandEffectsTrigger.Velocity
	{
		get
		{
			if (mode == IHandEffectsTrigger.Mode.HighFive)
			{
				return UnityEngine.Vector3.zero;
			}
			_ = mode;
			_ = 1;
			return UnityEngine.Vector3.zero;
		}
	}

	TagEffectPack IHandEffectsTrigger.CosmeticEffectPack => cosmeticEffectPack;

	private void Awake()
	{
		triggerZone = GetComponent<Collider>();
	}

	private void OnEnable()
	{
		if (!HandEffectsTriggerRegistry.HasInstance)
		{
			HandEffectsTriggerRegistry.FindInstance();
		}
		HandEffectsTriggerRegistry.Instance.Register(this);
	}

	private void OnDisable()
	{
		HandEffectsTriggerRegistry.Instance.Unregister(this);
	}

	public void OnTriggerEntered(IHandEffectsTrigger other)
	{
	}

	public bool InTriggerZone(IHandEffectsTrigger t)
	{
		if (!(base.transform.position - t.Transform.position).IsShorterThan(triggerZone.bounds.size))
		{
			return false;
		}
		RaycastHit hitInfo;
		switch (mode)
		{
		case IHandEffectsTrigger.Mode.HighFive_And_FistBump:
			if (!t.FingersUp || !triggerZone.Raycast(new Ray(t.Transform.position, t.Transform.right), out hitInfo, triggerRadius))
			{
				if (t.FingersDown)
				{
					return triggerZone.Raycast(new Ray(t.Transform.position, t.Transform.up), out hitInfo, triggerRadius);
				}
				return false;
			}
			return true;
		case IHandEffectsTrigger.Mode.FistBump:
			if (t.FingersDown)
			{
				return triggerZone.Raycast(new Ray(t.Transform.position, t.Transform.up), out hitInfo, triggerRadius);
			}
			return false;
		case IHandEffectsTrigger.Mode.HighFive:
			if (t.FingersUp)
			{
				return triggerZone.Raycast(new Ray(t.Transform.position, t.Transform.right), out hitInfo, triggerRadius);
			}
			return false;
		default:
			return triggerZone.Raycast(new Ray(t.Transform.position, triggerZone.bounds.center - t.Transform.position), out hitInfo, triggerRadius);
		}
	}
}
[DefaultExecutionOrder(10000)]
public class HandEffectsTriggerRegistry : MonoBehaviour, ITickSystemTick, ITickSystemPost
{
	[BurstCompile]
	private struct HandEffectsJob : IJobParallelFor, IDisposable
	{
		[NativeDisableParallelForRestriction]
		public NativeArray<UnityEngine.Vector3> positionInput;

		[NativeDisableParallelForRestriction]
		public NativeArray<bool> closeOutput;

		public int actualListSize;

		public void Execute(int i)
		{
			for (int j = i + 1; j < actualListSize; j++)
			{
				closeOutput[i * 50 + j] = (positionInput[i] - positionInput[j]).IsShorterThan(0.5f);
			}
		}

		public void Dispose()
		{
			positionInput.Dispose();
			closeOutput.Dispose();
		}
	}

	private const int MAX_TRIGGERS = 50;

	private const int BIT_ARRAY_SIZE = 2500;

	private const float COOLDOWN_TIME = 0.5f;

	private const float DEFAULT_RADIUS = 0.5f;

	private readonly List<IHandEffectsTrigger> triggers = new List<IHandEffectsTrigger>();

	private readonly float[] triggerTimes = new float[50];

	private readonly GTBitArray existingCollisionBits = new GTBitArray(2500);

	private readonly GTBitArray newCollisionBits = new GTBitArray(2500);

	private int actualListSz;

	private JobHandle jobHandle;

	private HandEffectsJob job;

	public bool TickRunning { get; set; }

	public bool PostTickRunning { get; set; }

	[field: OnEnterPlay_SetNull]
	public static HandEffectsTriggerRegistry Instance { get; private set; }

	[field: OnEnterPlay_Set(false)]
	public static bool HasInstance { get; private set; }

	public static void FindInstance()
	{
		Instance = UnityEngine.Object.FindAnyObjectByType<HandEffectsTriggerRegistry>();
		HasInstance = true;
	}

	private void Awake()
	{
		Instance = this;
		HasInstance = true;
		job = new HandEffectsJob
		{
			positionInput = new NativeArray<UnityEngine.Vector3>(50, Unity.Collections.Allocator.Persistent),
			closeOutput = new NativeArray<bool>(2500, Unity.Collections.Allocator.Persistent),
			actualListSize = actualListSz
		};
	}

	private void OnEnable()
	{
		TickSystem<object>.AddCallbackTarget(this);
		TickSystem<object>.AddPostTickCallback(this);
	}

	private void OnDisable()
	{
		TickSystem<object>.RemoveCallbackTarget(this);
		TickSystem<object>.RemovePostTickCallback(this);
	}

	public void Register(IHandEffectsTrigger trigger)
	{
		if (triggers.Count < 50)
		{
			actualListSz++;
			triggers.Add(trigger);
		}
	}

	public void Unregister(IHandEffectsTrigger trigger)
	{
		int num = triggers.IndexOf(trigger);
		if (num >= 0)
		{
			actualListSz--;
			triggers.RemoveAt(num);
		}
	}

	private void OnDestroy()
	{
		if (!jobHandle.IsCompleted)
		{
			jobHandle.Complete();
		}
		job.Dispose();
	}

	public void Tick()
	{
		CopyInput();
		jobHandle = IJobParallelForExtensions.Schedule(job, actualListSz, 20);
	}

	public void PostTick()
	{
		jobHandle.Complete();
		CheckForHandEffectOnProcessedOutput();
	}

	public void CheckForHandEffectOnProcessedOutput()
	{
		newCollisionBits.Clear();
		for (int i = 0; i < triggers.Count; i++)
		{
			IHandEffectsTrigger handEffectsTrigger = triggers[i];
			int num = i * 50;
			for (int j = i + 1; j < triggers.Count; j++)
			{
				if (!job.closeOutput[i * 50 + j])
				{
					continue;
				}
				IHandEffectsTrigger handEffectsTrigger2 = triggers[j];
				if (handEffectsTrigger.InTriggerZone(handEffectsTrigger2) || handEffectsTrigger2.InTriggerZone(handEffectsTrigger))
				{
					int idx = num + j;
					newCollisionBits[idx] = true;
					if (!existingCollisionBits[idx] && Time.time - triggerTimes[i] > 0.5f && Time.time - triggerTimes[j] > 0.5f)
					{
						handEffectsTrigger.OnTriggerEntered(handEffectsTrigger2);
						handEffectsTrigger2.OnTriggerEntered(handEffectsTrigger);
						triggerTimes[i] = (triggerTimes[j] = Time.time);
					}
				}
			}
		}
		existingCollisionBits.CopyFrom(newCollisionBits);
	}

	private void CopyInput()
	{
		for (int i = 0; i < actualListSz; i++)
		{
			job.positionInput[i] = triggers[i].Transform.position;
		}
		if (job.actualListSize != actualListSz)
		{
			job.actualListSize = actualListSz;
		}
	}
}
public class HandHoldBehaviourActivation : Tappable
{
	[SerializeField]
	private UnityEvent ActivationStart;

	[SerializeField]
	private UnityEvent ActivationStop;

	private int grabs;

	private readonly Dictionary<int, byte> m_playerGrabCounts = new Dictionary<int, byte>(20);

	protected override void OnEnable()
	{
		base.OnEnable();
		RoomSystem.PlayerLeftEvent += new Action<NetPlayer>(OnPlayerLeftRoom);
		RoomSystem.LeftRoomEvent += new Action(OnLeftRoom);
	}

	public override void OnGrabLocal(float tapTime, PhotonMessageInfoWrapped sender)
	{
		byte valueOrDefault = m_playerGrabCounts.GetValueOrDefault<int, byte>(sender.Sender.ActorNumber, 0);
		valueOrDefault++;
		if (valueOrDefault <= 2)
		{
			m_playerGrabCounts[sender.Sender.ActorNumber] = valueOrDefault;
			grabs++;
			if (grabs < 2)
			{
				ActivationStart.Invoke();
			}
		}
	}

	public override void OnReleaseLocal(float tapTime, PhotonMessageInfoWrapped sender)
	{
		if (m_playerGrabCounts.TryGetValue(sender.Sender.ActorNumber, out var value) && value >= 1)
		{
			value--;
			m_playerGrabCounts[sender.Sender.ActorNumber] = value;
			bool num = grabs > 0;
			grabs = Mathf.Max(0, grabs - 1);
			if (num && grabs < 1)
			{
				ActivationStop.Invoke();
			}
		}
	}

	private void OnPlayerLeftRoom(NetPlayer player)
	{
		if (m_playerGrabCounts.TryGetValue(player.ActorNumber, out var value))
		{
			bool num = grabs > 0;
			grabs = Mathf.Max(0, grabs - value);
			m_playerGrabCounts.Remove(player.ActorNumber);
			if (num && grabs < 1)
			{
				ActivationStop.Invoke();
			}
		}
	}

	private void OnLeftRoom()
	{
		byte valueOrDefault = m_playerGrabCounts.GetValueOrDefault<int, byte>(NetworkSystem.Instance.LocalPlayer.ActorNumber, 0);
		if (grabs > 0 && valueOrDefault < 1)
		{
			ActivationStop.Invoke();
		}
		grabs = valueOrDefault;
		m_playerGrabCounts.Clear();
		m_playerGrabCounts[NetworkSystem.Instance.LocalPlayer.ActorNumber] = valueOrDefault;
	}
}
