	[SerializeField]
	private string CCUEndpoint;

	public static float RecheckDelay => Mathf.Max((float)recheckDelay / 1000f, 1f);

	public async void Start()
	{
		state = State.READY;
		await Task.Delay(1000);
		UnityEngine.Debug.Log("[GT/HowManyMonke]  " + $"Checking NetworkSystem.Instance: {NetworkSystem.Instance}");
		while (NetworkSystem.Instance == null)
		{
			await Task.Delay(1000);
			UnityEngine.Debug.Log("[GT/HowManyMonke]  " + $"Re-Checking NetworkSystem.Instance: {NetworkSystem.Instance}");
		}
		ThisMany = await FetchThisMany();
		if (OnCheck != null)
		{
			OnCheck(ThisMany);
		}
		UnityEngine.Debug.Log("[GT/HowManyMonke]  " + $"Fetch Complete: {ThisMany}");
		await FetchRecheckDelay();
		while (UnityEngine.Application.isPlaying && recheckDelay > 0)
		{
			await Task.Delay(recheckDelay);
			if (OnCheck != null)
			{
				ThisMany = await FetchThisMany();
				OnCheck(ThisMany);
				await FetchRecheckDelay();
			}
		}
	}

	private async Task FetchRecheckDelay()
	{
		state = State.TD_LOOKUP;
		PlayFabTitleDataCache.Instance.GetTitleData(titleDataKey, onTD, onTDError);
		while (state != State.READY)
		{
			await Task.Yield();
		}
	}

	private void onTDError(PlayFabError error)
	{
		state = State.READY;
		recheckDelay = 0;
	}

	private void onTD(string obj)
	{
		state = State.READY;
		if (int.TryParse(obj, out recheckDelay))
		{
			recheckDelay *= 1000;
		}
		else
		{
			recheckDelay = 0;
		}
	}

	private async Task<int> FetchThisMany()
	{
		if (recheckDelay < 0)
		{
			return NetworkSystem.Instance.GlobalPlayerCount();
		}
		UnityWebRequest request = new UnityWebRequest(PlayFabAuthenticatorSettings.ModerationApiBaseUrl + CCUEndpoint, "POST")
		{
			downloadHandler = new DownloadHandlerBuffer()
		};
		await request.SendWebRequest();
		if (request.result == UnityWebRequest.Result.Success)
		{
			return JsonConvert.DeserializeObject<CCUResponse>(request.downloadHandler.text).CCUTotal;
		}
		return NetworkSystem.Instance.GlobalPlayerCount();
	}
}
public class HowManyMonkeDisplay : MonoBehaviour, IGorillaSliceableSimple
{
	[SerializeField]
	private TMP_Text text;

	[SerializeField]
	private float observableDistance = 100f;

	[SerializeField]
	private GameObject observableActive;

	[SerializeField]
	private ParticleSystem particleSystem;

	[SerializeField]
	private AnimationCurve particleSystemRateToCount;

	private bool observable;

	private int currValue;

	private int nextValue;

	private float checkTime;

	public void OnEnable()
	{
		currValue = (nextValue = HowManyMonke.ThisMany);
		text.text = currValue.ToString("N0");
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void OnDisable()
	{
		HowManyMonke.OnCheck = (Action<int>)Delegate.Remove(HowManyMonke.OnCheck, new Action<int>(HowManyMonke_OnCheck));
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	private void OnDestroy()
	{
		HowManyMonke.OnCheck = (Action<int>)Delegate.Remove(HowManyMonke.OnCheck, new Action<int>(HowManyMonke_OnCheck));
	}

	private void HowManyMonke_OnCheck(int thisMany)
	{
		currValue = nextValue;
		nextValue = thisMany;
		checkTime = Time.time;
	}

	public void SliceUpdate()
	{
		float time = Mathf.Lerp(currValue, nextValue, (Time.time - checkTime) / HowManyMonke.RecheckDelay);
		text.text = time.ToString("N0");
		ParticleSystem.EmissionModule emission = particleSystem.emission;
		emission.rateOverTime = particleSystemRateToCount.Evaluate(time);
		float sqrMagnitude = (VRRig.LocalRig.transform.position - base.transform.position).sqrMagnitude;
		if (observable && sqrMagnitude > observableDistance)
		{
			observable = false;
			HowManyMonke.OnCheck = (Action<int>)Delegate.Remove(HowManyMonke.OnCheck, new Action<int>(HowManyMonke_OnCheck));
			if ((bool)observableActive)
			{
				observableActive.SetActive(observable);
			}
		}
		else if (!observable && sqrMagnitude < observableDistance)
		{
			observable = true;
			HowManyMonke.OnCheck = (Action<int>)Delegate.Combine(HowManyMonke.OnCheck, new Action<int>(HowManyMonke_OnCheck));
			if ((bool)observableActive)
			{
				observableActive.SetActive(observable);
			}
		}
	}
}
