public class LckDirectGrabbable : MonoBehaviour, IGorillaGrabable
{
	public UnityEvent OnTabletGrabbed = new UnityEvent();

	public UnityEvent OnTabletReleased = new UnityEvent();

	[SerializeField]
	private Transform _originalTargetParent;

	public Transform target;

	[SerializeField]
	private bool _precise;

	private GorillaGrabber _grabber;

	public GorillaGrabber grabber => _grabber;

	public bool isGrabbed => _grabber != null;

	public event Action onGrabbed;

	public event Action onReleased;

	public UnityEngine.Vector3 GetLocalGrabbedPosition(GorillaGrabber grabber)
	{
		if (grabber == null)
		{
			return UnityEngine.Vector3.zero;
		}
		return base.transform.InverseTransformPoint(grabber.transform.position);
	}

	public bool CanBeGrabbed(GorillaGrabber grabber)
	{
		if (!(_grabber == null))
		{
			return grabber == _grabber;
		}
		return true;
	}

	public void OnGrabbed(GorillaGrabber grabber, out Transform grabbedTransform, out UnityEngine.Vector3 localGrabbedPosition)
	{
		if (!base.isActiveAndEnabled)
		{
			_grabber = null;
			grabbedTransform = grabber.transform;
			localGrabbedPosition = UnityEngine.Vector3.zero;
			return;
		}
		if (_grabber != null && _grabber != grabber)
		{
			ForceRelease();
		}
		if (_precise && IsSlingshotHeldInHand(out var leftHand, out var rightHand) && ((grabber.XrNode == XRNode.LeftHand && leftHand) || (grabber.XrNode == XRNode.RightHand && rightHand)))
		{
			_grabber = null;
			grabbedTransform = grabber.transform;
			localGrabbedPosition = UnityEngine.Vector3.zero;
			return;
		}
		_grabber = grabber;
		GtColliderTriggerProcessor.CurrentGrabbedHand = grabber.XrNode;
		GtColliderTriggerProcessor.IsGrabbingTablet = true;
		grabbedTransform = base.transform;
		localGrabbedPosition = GetLocalGrabbedPosition(_grabber);
		target.SetParent(grabber.transform, worldPositionStays: true);
		this.onGrabbed?.Invoke();
		OnTabletGrabbed?.Invoke();
	}

	public void OnGrabReleased(GorillaGrabber grabber)
	{
		target.transform.SetParent(_originalTargetParent, worldPositionStays: true);
		_grabber = null;
		GtColliderTriggerProcessor.IsGrabbingTablet = false;
		this.onReleased?.Invoke();
		OnTabletReleased?.Invoke();
	}

	public void ForceGrab(GorillaGrabber grabber)
	{
		grabber.Inject(base.transform, GetLocalGrabbedPosition(grabber));
	}

	public void ForceRelease()
	{
		if (!(_grabber == null))
		{
			_grabber.Inject(null, UnityEngine.Vector3.zero);
		}
	}

	private bool IsSlingshotHeldInHand(out bool leftHand, out bool rightHand)
	{
		VRRig rig = VRRigCache.Instance.localRig.Rig;
		if (rig == null || rig.projectileWeapon == null)
		{
			leftHand = false;
			rightHand = false;
			return false;
		}
		leftHand = rig.projectileWeapon.InLeftHand();
		rightHand = rig.projectileWeapon.InRightHand();
		return rig.projectileWeapon.InHand();
	}

	public void SetOriginalTargetParent(Transform parent)
	{
		_originalTargetParent = parent;
	}

	public bool MomentaryGrabOnly()
	{
		return true;
	}
}
public class LckEntitlementsManager : MonoBehaviour
{
	private class PlayerProcessRecord
	{
		public int AttemptCount;

		public float TimeoutUntilTimestamp;

		public float LastSeenTimestamp;
	}

	private enum FeatureState
	{
		Checking,
		Enabled,
		Disabled
	}

	[InjectLck]
	private ILckCosmeticsCoordinator _lckCosmeticsCoordinator;

	[InjectLck]
	private ILckCosmeticsFeatureFlagManager _featureFlagManager;

	private const int MAX_API_CALL_ATTEMPTS = 2;

	private const int MAX_CONSECUTIVE_ATTEMPTS = 3;

	private const float ABUSE_TIMEOUT_MINUTES = 1f;

	private const float BATCH_GET_ENTITLEMENTS_INTERVAL_SECONDS = 15f;

	private const float STALE_PLAYER_TIMEOUT_MINUTES = 5f;

	private const string DEFAULT_SESSION_ID = "DefaultSessionId";

	private FeatureState _currentState;

	private readonly HashSet<string> _remotePlayersToGetEntitlementsFor = new HashSet<string>();

	private Coroutine _getEntitlementsBatchingCoroutine;

	private readonly Dictionary<string, PlayerProcessRecord> _processedPlayers = new Dictionary<string, PlayerProcessRecord>();

	private Coroutine _cleanupProcessedPlayersCoroutine;

	private bool _isProcessingBatch;

	public static bool LckEntitlementsEnabled { get; private set; }

	public static LckEntitlementsManager Instance { get; private set; }

	private void Awake()
	{
		if (Instance != null && Instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			Instance = this;
		}
	}

	private void OnEnable()
	{
		InitializeFeatureAsync();
		_cleanupProcessedPlayersCoroutine = StartCoroutine(CleanupProcessedPlayersCoroutine());
		_getEntitlementsBatchingCoroutine = StartCoroutine(ProcessBatchedRemotePlayersCoroutine());
	}

	private void OnDisable()
	{
		if (_cleanupProcessedPlayersCoroutine != null)
		{
			StopCoroutine(_cleanupProcessedPlayersCoroutine);
			_cleanupProcessedPlayersCoroutine = null;
		}
		if (_getEntitlementsBatchingCoroutine != null)
		{
			StopCoroutine(_getEntitlementsBatchingCoroutine);
			_getEntitlementsBatchingCoroutine = null;
		}
	}

	private async Task InitializeFeatureAsync()
	{
		_currentState = FeatureState.Checking;
		bool flag = await _featureFlagManager.IsEnabledAsync();
		if (!(this == null))
		{
			_currentState = (flag ? FeatureState.Enabled : FeatureState.Disabled);
			LckEntitlementsEnabled = flag;
		}
	}

	public void OnLocalPlayerSpawned(string localUserId)
	{
		if (ShouldProcessPlayer(localUserId))
		{
			StartCoroutine(ProcessLocalPlayerSpawn(localUserId));
		}
	}

	public void OnRemotePlayerSpawned(string remoteUserId)
	{
		if (_currentState == FeatureState.Disabled || !ShouldProcessPlayer(remoteUserId))
		{
			return;
		}
		lock (_remotePlayersToGetEntitlementsFor)
		{
			_remotePlayersToGetEntitlementsFor.Add(remoteUserId);
		}
	}

	private IEnumerator ProcessLocalPlayerSpawn(string userId)
	{
		yield return new WaitUntil(() => _currentState != FeatureState.Checking);
		if (_currentState != FeatureState.Disabled)
		{
			StartCoroutine(AnnouncePlayerPresenceForSession(userId));
		}
	}

	private bool ShouldProcessPlayer(string userId)
	{
		if (!_processedPlayers.TryGetValue(userId, out var value))
		{
			value = new PlayerProcessRecord();
			_processedPlayers[userId] = value;
		}
		value.LastSeenTimestamp = Time.time;
		if (Time.time < value.TimeoutUntilTimestamp)
		{
			return false;
		}
		if (value.AttemptCount > 3)
		{
			value.AttemptCount = 0;
		}
		value.AttemptCount++;
		if (value.AttemptCount > 3)
		{
			value.TimeoutUntilTimestamp = Time.time + 60f;
			return false;
		}
		return true;
	}

	private IEnumerator ProcessBatchedRemotePlayersCoroutine()
	{
		while (true)
		{
			yield return new WaitForSeconds(15f);
			if (_isProcessingBatch)
			{
				continue;
			}
			List<string> list;
			lock (_remotePlayersToGetEntitlementsFor)
			{
				if (_remotePlayersToGetEntitlementsFor.Count == 0)
				{
					continue;
				}
				list = _remotePlayersToGetEntitlementsFor.ToList();
				_remotePlayersToGetEntitlementsFor.Clear();
				goto IL_008b;
			}
			IL_008b:
			if (list.Count > 0)
			{
				_isProcessingBatch = true;
				GetCosmeticsForPlayersAsync(list, "ProcessBatchedRemotePlayers");
			}
		}
	}

	private IEnumerator AnnouncePlayerPresenceForSession(string localPlayerId)
	{
		if (PhotonNetwork.CurrentRoom == null)
		{
			UnityEngine.Debug.LogError("LCK: Called AnnouncePlayerPresenceForSession() but no room was found. Player not announced.");
			yield break;
		}
		string sessionId = "DefaultSessionId";
		for (int attempt = 1; attempt <= 2; attempt++)
		{
			Task<Result<bool>> announcementAsync = _lckCosmeticsCoordinator.AnnouncePlayerPresenceForSessionAsync(localPlayerId, sessionId);
			yield return new WaitUntil(() => announcementAsync.IsCompleted);
			if (announcementAsync.IsFaulted || !announcementAsync.Result.IsOk)
			{
				string arg = (announcementAsync.IsFaulted ? announcementAsync.Exception.ToString() : announcementAsync.Result.Message.ToString());
				UnityEngine.Debug.LogError($"LCK: Error setting session entitlement (Attempt {attempt}/{2}): {arg}");
				continue;
			}
			yield break;
		}
		UnityEngine.Debug.LogError("LCK: All attempts to set session entitlement failed.");
	}

	private async Task GetCosmeticsForPlayersAsync(List<string> userIdList, string methodNameForLogging)
	{
		try
		{
			if (userIdList == null || userIdList.Count == 0)
			{
				return;
			}
			if (PhotonNetwork.CurrentRoom == null)
			{
				UnityEngine.Debug.LogError("LCK: Called " + methodNameForLogging + " but no room was found.");
				return;
			}
			string sessionId = "DefaultSessionId";
			await Task.Run(async delegate
			{
				for (int attempt = 1; attempt <= 2; attempt++)
				{
					Result<bool> result = await _lckCosmeticsCoordinator.GetUserCosmeticsForSessionAsync(userIdList, sessionId);
					if (result.IsOk)
					{
						return;
					}
					UnityEngine.Debug.LogError($"LCK: Error in {methodNameForLogging} (Attempt {attempt}/{2}): {result.Message}");
				}
				UnityEngine.Debug.LogError("LCK: All attempts to call " + methodNameForLogging + " failed.");
			});
		}
		catch (Exception arg)
		{
			UnityEngine.Debug.LogError($"LCK: An exception occurred in GetCosmeticsForPlayersAsync: {arg}");
		}
		finally
		{
			_isProcessingBatch = false;
		}
	}

	private IEnumerator CleanupProcessedPlayersCoroutine()
	{
		List<string> playersToRemove = new List<string>();
		while (true)
		{
			yield return new WaitForSeconds(60f);
			playersToRemove.Clear();
			float time = Time.time;
			foreach (KeyValuePair<string, PlayerProcessRecord> processedPlayer in _processedPlayers)
			{
				if (time > processedPlayer.Value.LastSeenTimestamp + 300f)
				{
					playersToRemove.Add(processedPlayer.Key);
				}
			}
			if (playersToRemove.Count <= 0)
			{
				continue;
			}
			foreach (string item in playersToRemove)
			{
				_processedPlayers.Remove(item);
			}
		}
	}
}
public class LckEntitlementsNetworked : MonoBehaviour
{
	[SerializeField]
	private VRRigSerializer m_rigNetworkController;

	public void Awake()
	{
		if (GTExt.IsNull(m_rigNetworkController))
		{
			m_rigNetworkController = GetComponentInParent<VRRigSerializer>();
		}
		if (GTExt.IsNull(m_rigNetworkController))
		{
			UnityEngine.Debug.LogError("LCK: Unable to find VRRigSerializer for LckEntitlementsNetworked.");
		}
		else
		{
			m_rigNetworkController.SuccesfullSpawnEvent?.Add(new InAction<RigContainer, PhotonMessageInfoWrapped>(OnSuccessfulSpawn));
		}
	}

	private void OnSuccessfulSpawn(in RigContainer rig, in PhotonMessageInfoWrapped info)
	{
		if (LckEntitlementsManager.Instance == null)
		{
			UnityEngine.Debug.LogError("LCK: LckEntitlementsManager.Instance is not available in the scene!");
			return;
		}
		string userId = m_rigNetworkController.VRRig.OwningNetPlayer.UserId;
		if (userId.IsNullOrEmpty())
		{
			UnityEngine.Debug.LogError("LCK: owningUserId is null on spawn. Cannot process entitlements.");
		}
		else if (rig.Rig.isLocal)
		{
			LckEntitlementsManager.Instance.OnLocalPlayerSpawned(userId);
		}
		else
		{
			LckEntitlementsManager.Instance.OnRemotePlayerSpawned(userId);
		}
	}

	private void OnDestroy()
	{
		if (m_rigNetworkController != null && m_rigNetworkController.SuccesfullSpawnEvent != null)
		{
			m_rigNetworkController.SuccesfullSpawnEvent.Remove(new InAction<RigContainer, PhotonMessageInfoWrapped>(OnSuccessfulSpawn));
		}
	}
}
[UnityEngine.Scripting.Preserve]
public class LckCosmeticsFeatureFlagManagerPlayFab : ILckCosmeticsFeatureFlagManager
{
	private const string TitleDataKey = "EnableLckCosmetics";

	private const int MaxRetries = 2;

	private const int RetryDelayMilliseconds = 5000;

	private Task<bool> _initializationTask;

	private readonly object _lock = new object();

	[UnityEngine.Scripting.Preserve]
	public LckCosmeticsFeatureFlagManagerPlayFab()
	{
	}

	public Task<bool> IsEnabledAsync()
	{
		if (_initializationTask != null)
		{
			return _initializationTask;
		}
		lock (_lock)
		{
			return _initializationTask ?? (_initializationTask = GetEnabledStateWithRetryAsync());
		}
	}

	private async Task<bool> GetEnabledStateWithRetryAsync()
	{
		for (int i = 0; i < 2; i++)
		{
			if (PlayFabTitleDataCache.Instance == null)
			{
				UnityEngine.Debug.LogWarning("LCK: PlayFabTitleDataCache instance is not available. " + $"Retrying feature flag check in {5} seconds... (Attempt {i + 1}/{2})");
				await Task.Delay(5000);
				continue;
			}
			TaskCompletionSource<bool> tcs = new TaskCompletionSource<bool>();
			PlayFabTitleDataCache.Instance.GetTitleData("EnableLckCosmetics", delegate(string data)
			{
				if (bool.TryParse(data, out var result))
				{
					UnityEngine.Debug.Log(string.Format("LCK: Feature flag '{0}' is set to '{1}'.", "EnableLckCosmetics", result));
					tcs.TrySetResult(result);
				}
				else
				{
					UnityEngine.Debug.LogError("LCK: Failed to parse feature flag 'EnableLckCosmetics' from value '" + data + "'. Defaulting to 'true'.");
					tcs.TrySetResult(result: true);
				}
			}, delegate(PlayFabError error)
			{
				UnityEngine.Debug.LogError("LCK: Error fetching feature flag 'EnableLckCosmetics': " + error.ErrorMessage + ". Defaulting to 'true'.");
				tcs.TrySetResult(result: true);
			});
			return await tcs.Task;
		}
		UnityEngine.Debug.LogError(string.Format("LCK: {0} instance was not available after {1} attempts. ", "PlayFabTitleDataCache", 2) + "Cosmetics feature will be enabled by default as a fallback measure.");
		return true;
	}
}
[ExecuteInEditMode]
public class LckRawImageFillCanvas : UIBehaviour
{
	private enum ScaleType
	{
		Fill,
		Inset,
		Stretch
	}

	[SerializeField]
	private RawImage _rawImage;

	[SerializeField]
	private ScaleType _scaleType;

	private new void OnEnable()
	{
		UpdateSizeDelta();
	}

	private void Update()
	{
		UpdateSizeDelta();
	}

	private void UpdateSizeDelta()
	{
		if (!(_rawImage == null) && !(_rawImage.texture == null))
		{
			RectTransform rectTransform = _rawImage.rectTransform;
			UnityEngine.Vector2 sizeDelta = ((RectTransform)rectTransform.parent).sizeDelta;
			UnityEngine.Vector2 vector = new UnityEngine.Vector2(_rawImage.texture.width, _rawImage.texture.height);
			float num = sizeDelta.x / sizeDelta.y;
			float num2 = vector.x / vector.y;
			float num3 = num / num2;
			UnityEngine.Vector2 vector2 = new UnityEngine.Vector2(sizeDelta.x, sizeDelta.x / num2);
			UnityEngine.Vector2 vector3 = new UnityEngine.Vector2(sizeDelta.y * num2, sizeDelta.y);
			switch (_scaleType)
			{
			case ScaleType.Fill:
				rectTransform.sizeDelta = ((num3 > 1f) ? vector2 : vector3);
				break;
			case ScaleType.Inset:
				rectTransform.sizeDelta = ((num3 < 1f) ? vector2 : vector3);
				break;
			case ScaleType.Stretch:
				rectTransform.sizeDelta = sizeDelta;
				break;
			}
		}
	}
}
