	private void ApplyVisualState(CameraState newState)
	{
		if (m_isCorrupted)
		{
			return;
		}
		bool flag = GetFlag(newState, CameraState.Visible);
		bool flag2 = GetFlag(newState, CameraState.Recording);
		bool flag3 = GetFlag(newState, CameraState.OnNeck);
