			lCKSocialCameraFollower.SetNetworkController(this);
		}
	}

	public void SliceUpdate()
	{
		if (GTExt.IsNull(_vrrig))
		{
			return;
		}
		if (m_cameraType == CameraType.Tablet)
		{
			if (IsOnNeck)
			{
				SocialCameraFollower.transform.localScale = UnityEngine.Vector3.one * 0.3f;
			}
			else
			{
				SocialCameraFollower.transform.localScale = UnityEngine.Vector3.one * 0.3f * _vrrig.scaleFactor;
			}
		}
		else if (m_cameraType == CameraType.Cococam)
		{
			SocialCameraFollower.transform.localScale = UnityEngine.Vector3.one * _vrrig.scaleFactor;
		}
	}

	public new void OnEnable()
	{
		NetworkBehaviourUtils.InternalOnEnable(this);
		base.OnEnable();
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

