	public override void CopyBackingFieldsToState(bool P_0)
	{
		base.CopyBackingFieldsToState(P_0);
		_networkedData = __networkedData;
	}

	[WeaverGenerated]
	public override void CopyStateToBackingFields()
	{
		base.CopyStateToBackingFields();
		__networkedData = _networkedData;
	}
}
public class LCKSocialCameraFollower : MonoBehaviour, ITickSystemTick
{
	[SerializeField]
	private Transform _scaleTransform;

	[FormerlySerializedAs("_coconutCamera")]
	[SerializeField]
	private GameObject _cameraVisualsRoot;

	[SerializeField]
	private List<GameObject> _visualObjects;

	[SerializeField]
	private RigContainer m_rigContainer;

	private Transform m_transformToFollow;

	private LckSocialCamera m_networkController;

	private IGtCameraVisuals m_gtCameraVisuals;

	private bool isParentedToRig;

	public Transform ScaleTransform => _scaleTransform;

	public GameObject CameraVisualsRoot => _cameraVisualsRoot;

	public List<GameObject> VisualObjects => _visualObjects;

	bool ITickSystemTick.TickRunning { get; set; }

	private void Awake()
	{
		m_gtCameraVisuals = _cameraVisualsRoot.GetComponent<IGtCameraVisuals>();
		if (m_rigContainer.Rig.isOfflineVRRig)
		{
			base.gameObject.SetActive(value: false);
			return;
		}
		m_rigContainer.RigEvents.disableEvent.Add(new Action<RigContainer>(PreRigDisable));
		m_rigContainer.RigEvents.enableEvent.Add(new Action<RigContainer>(PostRigEnable));
	}

	private void Start()
	{
		if (!isParentedToRig)
		{
			base.transform.parent = null;
		}
	}

	public void SetParentToRig()
	{
		isParentedToRig = true;
		base.transform.parent = m_rigContainer.transform;
		base.transform.localPosition = new UnityEngine.Vector3(0f, -0.2f, 0.132f);
		base.transform.localRotation = UnityEngine.Quaternion.identity;
	}

	public void SetParentNull()
	{
		isParentedToRig = false;
		base.transform.parent = null;
	}

	private void PostRigEnable(RigContainer _)
	{
		base.gameObject.SetActive(value: true);
		m_gtCameraVisuals.SetNetworkedVisualsActive(active: false);
		m_gtCameraVisuals.SetRecordingState(isRecording: false);
	}

	private void PreRigDisable(RigContainer _)
	{
		base.gameObject.SetActive(value: false);
	}

	public void SetNetworkController(LckSocialCamera networkController)
	{
		if (m_networkController.IsNotNull() && m_networkController != networkController)
		{
			m_networkController.TurnOff();
		}
		m_networkController = networkController;
		m_transformToFollow = m_networkController.transform;
		TickSystem<object>.AddTickCallback(this);
	}

	public void RemoveNetworkController(LckSocialCamera networkController)
	{
		if (!(m_networkController != networkController))
		{
			m_transformToFollow = null;
			m_networkController = null;
			TickSystem<object>.RemoveTickCallback(this);
		}
	}

	void ITickSystemTick.Tick()
	{
		if (!isParentedToRig && !(m_transformToFollow == null))
		{
			base.transform.position = m_transformToFollow.position;
			base.transform.root.rotation = m_transformToFollow.rotation;
		}
	}
}
public class LckSocialCameraManager : MonoBehaviour
{
	[SerializeField]
	private GameObject _localUi;

	[SerializeField]
	private GameObject _localCameras;

	[SerializeField]
	private GTLckController _gtLckController;

	[SerializeField]
	private LckDirectGrabbable _lckDirectGrabbable;

	[SerializeField]
	public CoconutCamera CoconutCamera;

	private LckSocialCamera _networkedCococam;

	private LckSocialCamera _networkedTablet;

	private Camera _lckCamera;

	private CameraMode _cameraMode;

	private LckBodyCameraSpawner.CameraState _cameraState;

	[OnEnterPlay_SetNull]
	private static LckSocialCameraManager _instance;

	public static Action<LckSocialCameraManager> OnManagerSpawned;

	private bool _isRecording;

	private bool _isForceHidden;

	private bool _needsUpdate = true;

	private UnityEngine.Vector3 _tabletPositionOffset = new UnityEngine.Vector3(0f, 0.11f, -0.08f);

	public LckDirectGrabbable lckDirectGrabbable => _lckDirectGrabbable;

	public static LckSocialCameraManager Instance => _instance;

	public bool cameraActive
	{
		get
		{
			return _localCameras.activeSelf;
		}
		set
		{
			if (_localCameras.activeSelf != value)
			{
				_localCameras.SetActive(value);
				_needsUpdate = true;
			}
		}
	}

	public bool uiVisible
	{
		get
		{
			return _localUi.activeSelf;
		}
		set
		{
			_localUi.SetActive(value);
		}
	}

	private void Awake()
	{
		SetManagerInstance();
		_lckCamera = _gtLckController.GetActiveCamera();
	}

	private void OnEnable()
	{
		LckResult<LckService> service = LckService.GetService();
		if (service.Result != null)
		{
			service.Result.OnRecordingStarted += OnRecordingStarted;
			service.Result.OnStreamingStarted += OnRecordingStarted;
			service.Result.OnRecordingStopped += OnRecordingStopped;
			service.Result.OnStreamingStopped += OnRecordingStopped;
		}
		LckBodyCameraSpawner.OnCameraStateChange += OnBodyCameraStateChanged;
		_gtLckController.OnCameraModeChanged += OnCameraModeChanged;
		_cameraMode = _gtLckController.CurrentCameraMode;
	}

	private void Update()
	{
		if (_lckCamera != null)
		{
			Transform transform = _lckCamera.transform;
			if (_networkedCococam != null)
			{
				_networkedCococam.transform.position = transform.position;
				_networkedCococam.transform.rotation = transform.rotation;
			}
			if (_networkedTablet != null)
			{
				if (_networkedTablet.IsOnNeck)
				{
					_networkedTablet.transform.position = base.transform.position;
				}
				else
				{
					_networkedTablet.transform.position = base.transform.position + _tabletPositionOffset * _networkedTablet.VrRig.scaleFactor;
				}
				_networkedTablet.transform.rotation = base.transform.rotation;
			}
		}
		if (_needsUpdate)
		{
			UpdateCococamVisibility(_cameraState, _cameraMode, _isForceHidden, cameraActive);
			UpdateTabletVisibility(_cameraState, _isForceHidden, cameraActive);
			UpdateCococamRecording(_isRecording);
			UpdateTabletRecording(_isRecording);
			_needsUpdate = false;
		}
	}

	private void OnDisable()
	{
		LckResult<LckService> service = LckService.GetService();
		if (service.Result != null)
		{
			service.Result.OnRecordingStarted -= OnRecordingStarted;
			service.Result.OnStreamingStarted -= OnRecordingStarted;
			service.Result.OnRecordingStopped -= OnRecordingStopped;
			service.Result.OnStreamingStopped -= OnRecordingStopped;
		}
		LckBodyCameraSpawner.OnCameraStateChange -= OnBodyCameraStateChanged;
		_gtLckController.OnCameraModeChanged -= OnCameraModeChanged;
	}

	public void SetForceHidden(bool hidden)
	{
		if (_isForceHidden != hidden)
		{
			_isForceHidden = hidden;
			_needsUpdate = true;
		}
	}

	public void SetLckSocialCococamCamera(LckSocialCamera socialCamera)
	{
		if (!(_networkedCococam == socialCamera))
		{
			_networkedCococam = socialCamera;
			_needsUpdate = true;
		}
	}

	public void SetLckSocialTabletCamera(LckSocialCamera socialCameraTablet)
	{
		if (!(_networkedTablet == socialCameraTablet))
		{
			_networkedTablet = socialCameraTablet;
			_needsUpdate = true;
		}
	}

	private void SetManagerInstance()
	{
		_instance = this;
		OnManagerSpawned?.Invoke(this);
	}

	private void OnBodyCameraStateChanged(LckBodyCameraSpawner.CameraState state)
	{
		if (_cameraState != state)
		{
			_cameraState = state;
			_needsUpdate = true;
		}
	}

	private void OnCameraModeChanged(CameraMode mode, ILckCamera lckCamera)
	{
		_lckCamera = lckCamera.GetCameraComponent();
		if (_cameraMode != mode)
		{
			_cameraMode = mode;
			_needsUpdate = true;
		}
	}

	private void OnRecordingStarted(LckResult result)
	{
		if (_isRecording != result.Success)
		{
			_isRecording = result.Success;
			_needsUpdate = true;
		}
	}

	private void OnRecordingStopped(LckResult result)
	{
		if (_isRecording)
		{
			_isRecording = false;
			_needsUpdate = true;
		}
	}

	private void UpdateCococamRecording(bool recording)
	{
		CoconutCamera.SetRecordingState(recording);
		if (!(_networkedCococam == null))
		{
			_networkedCococam.recording = recording;
		}
	}

	private void UpdateCococamVisibility(LckBodyCameraSpawner.CameraState cameraState, CameraMode cameraMode, bool forceHidden, bool cameraActive)
	{
		if (cameraMode == CameraMode.ThirdPerson || cameraMode == CameraMode.Drone)
		{
			CoconutCamera.SetVisualsActive(cameraActive);
		}
		else
		{
			CoconutCamera.SetVisualsActive(active: false);
		}
		if (!(_networkedCococam == null))
		{
			if (cameraState == LckBodyCameraSpawner.CameraState.CameraDisabled || forceHidden || !cameraActive)
			{
				_networkedCococam.visible = false;
			}
			else
			{
				_networkedCococam.visible = cameraMode == CameraMode.ThirdPerson || cameraMode == CameraMode.Drone;
			}
		}
	}

	private void UpdateTabletRecording(bool recording)
	{
		if (!(_networkedTablet == null))
		{
			_networkedTablet.recording = recording;
		}
	}

	private void UpdateTabletVisibility(LckBodyCameraSpawner.CameraState cameraState, bool forceHidden, bool cameraActive)
	{
		if (!(_networkedTablet == null))
		{
			if (cameraState == LckBodyCameraSpawner.CameraState.CameraDisabled || forceHidden)
			{
				_networkedTablet.visible = false;
				_networkedTablet.IsOnNeck = false;
			}
			else
			{
				_networkedTablet.visible = cameraActive;
				_networkedTablet.IsOnNeck = cameraState == LckBodyCameraSpawner.CameraState.CameraOnNeck;
			}
		}
	}
}
public class LckTabletSizeManager : MonoBehaviour
{
	[SerializeField]
	private GTLckController _controller;

	[SerializeField]
	private LckDirectGrabbable _lckDirectGrabbable;

	[SerializeField]
	private GtTabletFollower _tabletFollower;

	[SerializeField]
	private Camera _firstPersonCamera;

	[SerializeField]
	private Camera _selfieCamera;

	private UnityEngine.Vector3 _firstPersonCamShrinkPosition = new UnityEngine.Vector3(0f, 0f, -0.78f);

	private UnityEngine.Vector3 _firstPersonCamDefaultPosition = UnityEngine.Vector3.zero;

	private float _shrinkSize = 0.06f;

	private UnityEngine.Vector3 _shrinkVector = new UnityEngine.Vector3(0.06f, 0.06f, 0.06f);

	private float _customNearClip = 0.0006f;

	private bool _isDefaultScale = true;

	private void Start()
	{
		GTLckController controller = _controller;
		controller.OnFOVUpdated = (Action<CameraMode>)Delegate.Combine(controller.OnFOVUpdated, new Action<CameraMode>(UpdateCustomNearClip));
		_controller.OnHorizontalModeChanged += OnHorizontalModeChanged;
	}

	private void OnDestroy()
	{
		_controller.OnHorizontalModeChanged -= OnHorizontalModeChanged;
		GTLckController controller = _controller;
		controller.OnFOVUpdated = (Action<CameraMode>)Delegate.Remove(controller.OnFOVUpdated, new Action<CameraMode>(UpdateCustomNearClip));
	}

	private void OnHorizontalModeChanged(bool mode)
	{
		UpdateCustomNearClip(CameraMode.Selfie);
		UpdateCustomNearClip(CameraMode.FirstPerson);
	}

	private void UpdateCustomNearClip(CameraMode mode)
	{
		if (!GTPlayer.Instance.IsDefaultScale)
		{
			switch (mode)
			{
			case CameraMode.Selfie:
				SetCustomNearClip(_selfieCamera);
				break;
			case CameraMode.FirstPerson:
				SetCustomNearClip(_firstPersonCamera);
				break;
			case CameraMode.ThirdPerson:
			case CameraMode.Headset:
			case CameraMode.Drone:
				break;
			}
		}
	}

	private void SetCustomNearClip(Camera cam)
	{
		if (!GTPlayer.Instance.IsDefaultScale)
		{
			UnityEngine.Matrix4x4 projectionMatrix = ((!_controller.HorizontalMode) ? UnityEngine.Matrix4x4.Perspective(cam.fieldOfView, 0.5625f, _customNearClip, cam.farClipPlane) : UnityEngine.Matrix4x4.Perspective(cam.fieldOfView, 1.777778f, _customNearClip, cam.farClipPlane));
			cam.projectionMatrix = projectionMatrix;
		}
	}

	private void ClearCustomNearClip()
	{
		_selfieCamera.ResetProjectionMatrix();
		_firstPersonCamera.ResetProjectionMatrix();
	}

	private void PlayerBecameSmall()
	{
		_firstPersonCamera.transform.localPosition = _firstPersonCamShrinkPosition;
		_tabletFollower.SetPlayerSizeModifier(isDefaultScale: false, _shrinkSize);
		if (!_lckDirectGrabbable.isGrabbed)
		{
			SetCameraOnNeck();
		}
		SetCustomNearClip(_selfieCamera);
		SetCustomNearClip(_firstPersonCamera);
	}

	private void PlayerBecameDefaultSize()
	{
		_firstPersonCamera.transform.localPosition = _firstPersonCamDefaultPosition;
		_tabletFollower.SetPlayerSizeModifier(isDefaultScale: true, 1f);
		if (!_lckDirectGrabbable.isGrabbed)
		{
			SetCameraOnNeck();
			base.transform.localScale = UnityEngine.Vector3.one;
		}
		ClearCustomNearClip();
	}

	private void SetCameraOnNeck()
	{
		GTPlayer instance = GTPlayer.Instance;
		if (instance == null)
		{
			UnityEngine.Debug.LogError("Unable to find playerInstance!");
			return;
		}
		LckBodyCameraSpawner componentInChildren = instance.GetComponentInChildren<LckBodyCameraSpawner>(includeInactive: true);
		if (componentInChildren == null)
		{
			UnityEngine.Debug.LogError("Unable to find bodyCameraSpawner!");
		}
		else
		{
			componentInChildren.ManuallySetCameraOnNeck();
		}
	}

	private void Update()
	{
		if (!GTPlayer.Instance.IsDefaultScale && _isDefaultScale != GTPlayer.Instance.IsDefaultScale)
		{
			_isDefaultScale = false;
			PlayerBecameSmall();
		}
		else if (GTPlayer.Instance.IsDefaultScale && _isDefaultScale != GTPlayer.Instance.IsDefaultScale)
		{
			_isDefaultScale = true;
			PlayerBecameDefaultSize();
		}
	}
}
public class LckWallCameraSpawner : MonoBehaviour
{
	public enum WallSpawnerState
	{
		CameraOnHook,
		CameraDragging,
		CameraOffHook
	}

	[SerializeField]
	private GameObject _lckBodySpawnerPrefab;

	[SerializeField]
	private LckDirectGrabbable _cameraHandleGrabbable;

	[SerializeField]
	private Transform _cameraModelOriginTransform;

	[SerializeField]
	private Transform _cameraModelTransform;

	[SerializeField]
	private LineRenderer _cameraStrapRenderer;

	[SerializeField]
	private float _activateDistance = 0.25f;

	[SerializeField]
	private Transform[] _cameraStrapPoints;

	private UnityEngine.Vector3[] _cameraStrapPositions;

	private float _spawnRotationOffsetAndroid = -80f;

	private float _spawnRotationOffsetWindows = -55f;

	[SerializeField]
	private Color _normalColor = Color.red;

	[Header("Cosmetics References")]
	[SerializeField]
	private GtDummyTablet _dummyTablet;

	[SerializeField]
	private LckGameObjectSwapCosmetic _swapTablet;

	[SerializeField]
	private LckGameObjectSwapCosmetic _swapEmobi;

	private static LckBodyCameraSpawner _bodySpawner;

	private static Camera _prewarmCamera;

	private WallSpawnerState _wallSpawnerState;

	public WallSpawnerState wallSpawnerState
	{
		get
		{
			return _wallSpawnerState;
		}
		set
		{
			switch (value)
			{
			case WallSpawnerState.CameraOnHook:
				ResetCameraModel();
				UpdateCameraStrap();
				cameraVisible = true;
				break;
			case WallSpawnerState.CameraOffHook:
				ResetCameraModel();
				UpdateCameraStrap();
				cameraVisible = true;
				break;
			}
			_wallSpawnerState = value;
		}
	}

	private bool cameraVisible
	{
		get
		{
			return _cameraModelTransform.gameObject.activeSelf;
		}
		set
		{
			_cameraModelTransform.gameObject.SetActive(value);
			_cameraStrapRenderer.gameObject.SetActive(value);
		}
	}

	private LckBodyCameraSpawner GetOrCreateBodyCameraSpawner()
	{
		if (_bodySpawner != null)
		{
			return _bodySpawner;
		}
		GTPlayer instance = GTPlayer.Instance;
		if (instance == null)
		{
			UnityEngine.Debug.LogError("Unable to find Player!");
			return null;
		}
		AddGTag(Camera.main.gameObject, GtTagType.HMD);
		AddGTag(instance.gameObject, GtTagType.Player);
		Transform transform = instance.bodyCollider.transform;
		GameObject obj = UnityEngine.Object.Instantiate(_lckBodySpawnerPrefab, transform.parent);
		Transform obj2 = obj.transform;
		obj2.localPosition = UnityEngine.Vector3.zero;
		obj2.localRotation = UnityEngine.Quaternion.identity;
		obj2.localScale = UnityEngine.Vector3.one;
		_bodySpawner = obj.GetComponent<LckBodyCameraSpawner>();
		_bodySpawner.SetFollowTransform(transform);
		GorillaTagger instance2 = GorillaTagger.Instance;
		if (instance2 != null)
		{
			AddGTag(instance2.leftHandTriggerCollider, GtTagType.LeftHand);
			AddGTag(instance2.rightHandTriggerCollider, GtTagType.RightHand);
		}
		else
		{
			UnityEngine.Debug.LogError("Unable to find GorillaTagger!");
		}
		return _bodySpawner;
	}

	private static void AddGTag(GameObject go, GtTagType gtTagType)
	{
		if (!go.GetComponent<GtTag>())
		{
			GtTag gtTag = go.AddComponent<GtTag>();
			gtTag.gtTagType = gtTagType;
			gtTag.enabled = true;
		}
	}

	private void Awake()
	{
		InitCameraStrap();
	}

	private void OnEnable()
	{
		if (_swapTablet != null && _swapEmobi != null && _dummyTablet != null)
		{
			LckGameObjectSwapCosmetic swapTablet = _swapTablet;
			swapTablet.OnCosmeticSpawned = (Action<GameObject>)Delegate.Combine(swapTablet.OnCosmeticSpawned, new Action<GameObject>(_dummyTablet.OnTabletCosmeticSpawned));
			LckGameObjectSwapCosmetic swapEmobi = _swapEmobi;
			swapEmobi.OnCosmeticSpawned = (Action<GameObject>)Delegate.Combine(swapEmobi.OnCosmeticSpawned, new Action<GameObject>(_dummyTablet.OnEmobiCosmeticSpawned));
		}
		_cameraHandleGrabbable.onGrabbed += OnGrabbed;
		_cameraHandleGrabbable.onReleased += OnReleased;
		wallSpawnerState = WallSpawnerState.CameraOnHook;
	}

	private void Start()
	{
		CreatePrewarmCamera();
	}

	private void Update()
	{
		switch (_wallSpawnerState)
		{
		case WallSpawnerState.CameraOnHook:
			if (GetOrCreateBodyCameraSpawner() == null)
			{
				UnityEngine.Debug.LogError("Lck, Unable to find LckBodyCameraSpawner");
				base.gameObject.SetActive(value: false);
			}
			else if (_bodySpawner.cameraState == LckBodyCameraSpawner.CameraState.CameraSpawned && _bodySpawner.tabletSpawnInstance.isSpawned && _bodySpawner.tabletSpawnInstance.directGrabbable.isGrabbed)
			{
				LckDirectGrabbable directGrabbable = _bodySpawner.tabletSpawnInstance.directGrabbable;
				GorillaGrabber grabber = directGrabbable.grabber;
				if (!ShouldSpawnCamera(grabber.transform))
				{
					directGrabbable.ForceRelease();
					_bodySpawner.cameraState = LckBodyCameraSpawner.CameraState.CameraDisabled;
					_cameraHandleGrabbable.target.SetPositionAndRotation(grabber.transform.position, grabber.transform.rotation * UnityEngine.Quaternion.Euler(_spawnRotationOffsetWindows, 180f, 0f));
					_cameraHandleGrabbable.ForceGrab(grabber);
				}
			}
			break;
		case WallSpawnerState.CameraDragging:
			UpdateCameraStrap();
			if (ShouldSpawnCamera(_cameraHandleGrabbable.grabber.transform))
			{
				SpawnCamera(_cameraHandleGrabbable.grabber);
			}
			break;
		}
	}

	private void OnDisable()
	{
		if (_swapTablet != null && _swapEmobi != null && _dummyTablet != null)
		{
			LckGameObjectSwapCosmetic swapTablet = _swapTablet;
			swapTablet.OnCosmeticSpawned = (Action<GameObject>)Delegate.Remove(swapTablet.OnCosmeticSpawned, new Action<GameObject>(_dummyTablet.OnTabletCosmeticSpawned));
			LckGameObjectSwapCosmetic swapEmobi = _swapEmobi;
			swapEmobi.OnCosmeticSpawned = (Action<GameObject>)Delegate.Remove(swapEmobi.OnCosmeticSpawned, new Action<GameObject>(_dummyTablet.OnEmobiCosmeticSpawned));
		}
		_cameraHandleGrabbable.onGrabbed -= OnGrabbed;
		_cameraHandleGrabbable.onReleased -= OnReleased;
	}

	private void SpawnCamera(GorillaGrabber lastGorillaGrabber)
	{
		if (_bodySpawner == null)
		{
			UnityEngine.Debug.LogError("Lck, unable to spawn camera, body spawner is null!");
			return;
		}
		if (_bodySpawner.tabletSpawnInstance != null && _bodySpawner.tabletSpawnInstance.Controller != null && _bodySpawner.tabletSpawnInstance.Controller.GtColliderTriggerProcessorsGroup != null && (bool)_bodySpawner.tabletSpawnInstance.Controller.GtColliderTriggerProcessorsGroup.GetCurrentTriggerProcessor())
		{
			_bodySpawner.tabletSpawnInstance.Controller.GtColliderTriggerProcessorsGroup.GetCurrentTriggerProcessor().ResetToDefaultAndTriggerButton();
			_bodySpawner.tabletSpawnInstance.Controller.GtColliderTriggerProcessorsGroup.ClearAllTriggers();
		}
		cameraVisible = false;
		_cameraHandleGrabbable.ForceRelease();
		_bodySpawner.SpawnCamera(lastGorillaGrabber, lastGorillaGrabber.transform);
	}

	private void InitCameraStrap()
	{
		_cameraStrapRenderer.positionCount = _cameraStrapPoints.Length;
		_cameraStrapPositions = new UnityEngine.Vector3[_cameraStrapPoints.Length];
	}

	private void UpdateCameraStrap()
	{
		for (int i = 0; i < _cameraStrapPoints.Length; i++)
		{
			_cameraStrapPositions[i] = _cameraStrapPoints[i].position;
		}
		_cameraStrapRenderer.SetPositions(_cameraStrapPositions);
		UnityEngine.Vector3 lossyScale = base.transform.lossyScale;
		float num = (lossyScale.x + lossyScale.y + lossyScale.z) * 0.3333333f;
		_cameraStrapRenderer.widthMultiplier = num * 0.02f;
		LineRenderer cameraStrapRenderer = _cameraStrapRenderer;
		Color startColor = (_cameraStrapRenderer.endColor = _normalColor);
		cameraStrapRenderer.startColor = startColor;
	}

	private void ResetCameraModel()
	{
		_cameraModelTransform.localPosition = UnityEngine.Vector3.zero;
		_cameraModelTransform.localRotation = UnityEngine.Quaternion.identity;
	}

	private bool ShouldSpawnCamera(Transform gorillaGrabberTransform)
	{
		UnityEngine.Matrix4x4 worldToLocalMatrix = base.transform.worldToLocalMatrix;
		UnityEngine.Vector3 vector = worldToLocalMatrix.MultiplyPoint(_cameraModelOriginTransform.position);
		UnityEngine.Vector3 vector2 = worldToLocalMatrix.MultiplyPoint(gorillaGrabberTransform.position);
		return UnityEngine.Vector3.SqrMagnitude(vector - vector2) >= _activateDistance * _activateDistance;
	}

	private void OnGrabbed()
	{
		wallSpawnerState = WallSpawnerState.CameraDragging;
	}

	private void OnReleased()
	{
		wallSpawnerState = WallSpawnerState.CameraOnHook;
	}

	private void CreatePrewarmCamera()
	{
		if (!(_prewarmCamera != null))
		{
			GameObject obj = new GameObject("prewarm camera");
			obj.transform.SetParent(base.transform);
			_prewarmCamera = obj.AddComponent<Camera>();
			Camera main = Camera.main;
			_prewarmCamera.clearFlags = main.clearFlags;
			_prewarmCamera.fieldOfView = main.fieldOfView;
			_prewarmCamera.nearClipPlane = main.nearClipPlane;
			_prewarmCamera.farClipPlane = main.farClipPlane;
			_prewarmCamera.cullingMask = main.cullingMask;
			_prewarmCamera.tag = "Untagged";
			_prewarmCamera.stereoTargetEye = StereoTargetEyeMask.None;
			_prewarmCamera.targetTexture = new RenderTexture(32, 32, GraphicsFormat.R8G8B8A8_UNorm, GraphicsFormat.D32_SFloat_S8_UInt);
			_prewarmCamera.transform.SetPositionAndRotation(main.transform.position, main.transform.rotation);
			StartCoroutine(DestroyPrewarmCameraDelayed());
		}
	}

	private IEnumerator DestroyPrewarmCameraDelayed()
	{
		yield return new WaitForSeconds(1f);
		DestroyPrewarmCamera();
	}

	private void DestroyPrewarmCamera()
	{
		if (!(_prewarmCamera == null))
		{
			RenderTexture targetTexture = _prewarmCamera.targetTexture;
			_prewarmCamera.targetTexture = null;
			targetTexture.Release();
			UnityEngine.Object.Destroy(_prewarmCamera.gameObject);
			_prewarmCamera = null;
		}
	}
}
public class MonitorOutputController : MonoBehaviour
{
	[SerializeField]
	private GTLckController _gtLckController;

	private Camera _lckCamera;

	private CameraMode _lckActiveCameraMode;

	private Camera _shoulderCamera;

	private float _shoulderCameraFov;

	private void Awake()
	{
		_lckCamera = _gtLckController.GetActiveCamera();
	}

	private void OnEnable()
	{
		_gtLckController.OnCameraModeChanged += OnCameraModeChanged;
		LckBodyCameraSpawner.OnCameraStateChange += CameraStateChanged;
	}

	private void Update()
	{
		if (UnityEngine.Application.platform == RuntimePlatform.Android)
		{
			UnityEngine.Object.Destroy(this);
		}
		if (_shoulderCamera == null)
		{
			FindShoulderCamera();
		}
		if (_lckCamera != null)
		{
			_shoulderCamera.transform.position = _lckCamera.transform.position;
			_shoulderCamera.transform.rotation = _lckCamera.transform.rotation;
			_shoulderCamera.fieldOfView = _lckCamera.fieldOfView;
		}
		else
		{
			_lckCamera = _gtLckController.GetActiveCamera();
		}
	}

	private void CameraStateChanged(LckBodyCameraSpawner.CameraState state)
	{
		switch (state)
		{
		case LckBodyCameraSpawner.CameraState.CameraDisabled:
			RestoreShoulderCamera();
			break;
		case LckBodyCameraSpawner.CameraState.CameraOnNeck:
			TakeOverShoulderCamera();
			break;
		case LckBodyCameraSpawner.CameraState.CameraSpawned:
			TakeOverShoulderCamera();
			break;
		}
	}

	private void OnDisable()
	{
		_gtLckController.OnCameraModeChanged -= OnCameraModeChanged;
		_shoulderCamera.gameObject.GetComponentInChildren<CinemachineBrain>().enabled = true;
		LckBodyCameraSpawner.OnCameraStateChange -= CameraStateChanged;
	}

	private void OnCameraModeChanged(CameraMode mode, ILckCamera lckCamera)
	{
		_lckCamera = lckCamera.GetCameraComponent();
		_lckActiveCameraMode = mode;
	}

	private void TakeOverShoulderCamera()
	{
		FindShoulderCamera();
		_shoulderCamera.gameObject.GetComponentInChildren<CinemachineBrain>().enabled = false;
		_shoulderCamera.cullingMask &= ~(1 << LayerMask.NameToLayer("LCKHide"));
	}

	private void RestoreShoulderCamera()
	{
		FindShoulderCamera();
		_shoulderCamera.gameObject.GetComponentInChildren<CinemachineBrain>().enabled = true;
		_shoulderCamera.cullingMask |= 1 << LayerMask.NameToLayer("LCKHide");
		_shoulderCamera.fieldOfView = _shoulderCameraFov;
	}

	private void FindShoulderCamera()
	{
		if (!(_shoulderCamera != null) && GorillaTagger.hasInstance && base.isActiveAndEnabled)
		{
			_shoulderCamera = GorillaTagger.Instance.thirdPersonCamera.GetComponentInChildren<Camera>();
			_shoulderCameraFov = _shoulderCamera.fieldOfView;
		}
	}
}
public class LightArray : MonoBehaviour
{
	[SerializeField]
	private LightArrayPresets presets;

	[SerializeField]
	private GameLight[] lights;

	[SerializeField]
	private LightArray[] subArrays;

	[SerializeField]
	private int cascadeTime;

	[SerializeField]
	private float setLightHue = -1f;

	[NonSerialized]
	private float preLightHue = -1f;

	[SerializeField]
	private float setLightSat = -1f;

	[NonSerialized]
	private float preLightSat = -1f;

	[SerializeField]
	private float setLightVal = -1f;

	[NonSerialized]
	private float preLightVal = -1f;

	[SerializeField]
	private float setLightIntensity = -1f;

	[NonSerialized]
	private float preLightIntensity = -1f;

	private void ToggleDynamicLighting()
	{
		GameLightingManager.instance.ToggleCustomDynamicLightingEnabled();
	}

	public void SetCascadeTime(int ct)
	{
		cascadeTime = ct;
	}

	public void SetSubArraysCascadeTime(int ct)
	{
		for (int i = 0; i < subArrays.Length; i++)
		{
			subArrays[i].cascadeTime = ct;
		}
	}

	public void SetPreset(int i)
	{
		if (!(presets == null))
		{
			LightArrayPresets.LightArrayPreset preset = presets.GetPreset(i);
			if (preset != null)
			{
				SetColorAndIntensity(preset.color, preset.intensity);
			}
		}
	}

	public void SetPreset(string n)
	{
		if (!(presets == null))
		{
			LightArrayPresets.LightArrayPreset preset = presets.GetPreset(n);
			if (preset != null)
			{
				SetColorAndIntensity(preset.color, preset.intensity);
			}
		}
	}

	public void SetColorAndIntensity(string RRGGBBF)
	{
		SetColorAndIntensity(GetColor(RRGGBBF), float.Parse(RRGGBBF.Substring(6).ToString()));
	}

	private async void SetColorAndIntensity(Color c, float intensity)
	{
		if (cascadeTime < 0)
		{
			for (int i = subArrays.Length - 1; i >= 0; i--)
			{
				subArrays[i].SetColorAndIntensity(c, intensity);
				await Task.Delay(Mathf.Abs(cascadeTime));
			}
		}
		else
		{
			for (int i = 0; i < subArrays.Length; i++)
			{
				subArrays[i].SetColorAndIntensity(c, intensity);
				await Task.Delay(Mathf.Abs(cascadeTime));
			}
		}
		if (cascadeTime < 0)
		{
			for (int i = lights.Length - 1; i >= 0; i--)
			{
				await SetLightColorAndIntensity(c, intensity, i);
			}
		}
		else
		{
			for (int i = 0; i < lights.Length; i++)
			{
				await SetLightColorAndIntensity(c, intensity, i);
			}
		}
	}

	public void SetColor(string RRGGBB)
	{
		SetColor(GetColor(RRGGBB));
	}

	private async void SetColor(Color c)
	{
		if (cascadeTime < 0)
		{
			for (int i = subArrays.Length - 1; i >= 0; i--)
			{
				subArrays[i].SetColor(c);
				await Task.Delay(Mathf.Abs(cascadeTime));
			}
		}
		else
		{
			for (int i = 0; i < subArrays.Length; i++)
			{
				subArrays[i].SetColor(c);
				await Task.Delay(Mathf.Abs(cascadeTime));
			}
		}
		if (cascadeTime < 0)
		{
			for (int i = lights.Length - 1; i >= 0; i--)
			{
				await SetLightColor(c, i);
			}
		}
		else
		{
			for (int i = 0; i < lights.Length; i++)
			{
				await SetLightColor(c, i);
			}
		}
	}

	public async void SetIntensity(float intensity)
	{
		if (cascadeTime < 0)
		{
			for (int i = subArrays.Length - 1; i >= 0; i--)
			{
				subArrays[i].SetIntensity(intensity);
				await Task.Delay(Mathf.Abs(cascadeTime));
			}
		}
		else
		{
			for (int i = 0; i < subArrays.Length; i++)
			{
				subArrays[i].SetIntensity(intensity);
				await Task.Delay(Mathf.Abs(cascadeTime));
			}
		}
		if (cascadeTime < 0)
		{
			for (int i = lights.Length - 1; i >= 0; i--)
			{
				await SetLightIntensity(intensity, i);
			}
		}
		else
		{
			for (int i = 0; i < lights.Length; i++)
			{
				await SetLightIntensity(intensity, i);
			}
		}
	}

	private async Task SetLightColorAndIntensity(Color c, float intensity, int i)
	{
		lights[i].light.color = c;
		lights[i].light.intensity = intensity;
		lights[i].UpdateCachedLightColorAndIntensity();
		if (cascadeTime != 0)
		{
			await Task.Delay(Mathf.Abs(cascadeTime));
		}
	}

	private async Task SetLightColor(Color c, int i)
	{
		lights[i].light.color = c;
		lights[i].UpdateCachedLightColorAndIntensity();
		if (cascadeTime != 0)
		{
			await Task.Delay(Mathf.Abs(cascadeTime));
		}
	}

	private async Task SetLightIntensity(float intensity, int i)
	{
		lights[i].light.intensity = intensity;
		lights[i].UpdateCachedLightColorAndIntensity();
		if (cascadeTime != 0)
		{
			await Task.Delay(Mathf.Abs(cascadeTime));
		}
	}

	private Color GetColor(string RRGGBB)
	{
		return new Color((float)int.Parse(RRGGBB.Substring(0, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBB.Substring(2, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBB.Substring(4, 2), NumberStyles.HexNumber) / 255f);
	}

	private void LateUpdate()
	{
		bool flag = false;
		bool flag2 = false;
		if (preLightHue != setLightHue)
		{
			flag = true;
			preLightHue = setLightHue;
		}
		if (preLightSat != setLightSat)
		{
			flag = true;
			preLightSat = setLightSat;
		}
		if (preLightVal != setLightVal)
		{
			flag = true;
			preLightVal = setLightVal;
		}
		if (preLightIntensity != setLightIntensity)
		{
			flag2 = true;
			preLightIntensity = setLightIntensity;
		}
		if (flag && flag2)
		{
			SetColorAndIntensity(Color.HSVToRGB(setLightHue, setLightSat, setLightVal), setLightIntensity);
		}
		else if (flag)
		{
			SetColor(Color.HSVToRGB(setLightHue, setLightSat, setLightVal));
		}
		else if (flag2)
		{
			SetIntensity(setLightIntensity);
		}
	}
}
