public class MaterialCycler : MonoBehaviour
{
	[Serializable]
	private class MaterialPack
	{
		[SerializeField]
		private Material[] materials;

		public Material[] Materials => materials;
	}

	[SerializeField]
	private MaterialPack[] materials;

	[SerializeField]
	private Renderer[] renderers;

	private int index;

	[SerializeField]
	private string setColorTarget = "_BaseColor";

	[SerializeField]
	private UnityEvent<UnityEngine.Vector3> reset;

	private Coroutine crDirty;

	private float synchTime;

	private MaterialCyclerNetworked materialCyclerNetworked;

	private void Awake()
	{
		materialCyclerNetworked = GetComponent<MaterialCyclerNetworked>();
		SetMaterials();
	}

	private void OnEnable()
	{
		if (materialCyclerNetworked != null)
		{
			materialCyclerNetworked.OnSynchronize += MaterialCyclerNetworked_OnSynchronize;
		}
	}

	private void OnDisable()
	{
		if (materialCyclerNetworked != null)
		{
			materialCyclerNetworked.OnSynchronize -= MaterialCyclerNetworked_OnSynchronize;
		}
	}

	private void MaterialCyclerNetworked_OnSynchronize(int idx, int3 rgb)
	{
		if (idx >= 0 && idx < materials.Length)
		{
			index = idx;
			for (int i = 0; i < renderers.Length; i++)
			{
				renderers[i].material = materials[index].Materials[i];
				renderers[i].material.SetColor(setColorTarget, new Color((float)rgb.x / 9f, (float)rgb.y / 9f, (float)rgb.z / 9f));
			}
			reset.Invoke(new UnityEngine.Vector3(renderers[0].material.color.r, renderers[0].material.color.g, renderers[0].material.color.b));
		}
	}

	private void SetMaterials()
	{
		for (int i = 0; i < renderers.Length; i++)
		{
			if (materials[index].Materials.Length > i)
			{
				renderers[i].material = materials[index].Materials[i];
			}
			else
			{
				renderers[i].material = null;
			}
		}
		reset.Invoke(new UnityEngine.Vector3(renderers[0].material.color.r, renderers[0].material.color.g, renderers[0].material.color.b));
	}

	public void NextMaterial()
	{
		index = (index + 1) % materials.Length;
		SetMaterials();
		SetDirty();
	}

	private void SetDirty()
	{
		if (!(materialCyclerNetworked == null))
		{
			synchTime = Time.time + materialCyclerNetworked.SyncTimeOut;
			if (crDirty == null)
			{
				crDirty = StartCoroutine(timeOutDirty());
			}
		}
	}

	private IEnumerator timeOutDirty()
	{
		while (synchTime > Time.time)
		{
			yield return null;
		}
		synchronize();
		crDirty = null;
	}

	private void synchronize()
	{
		materialCyclerNetworked.Synchronize(index, renderers[0].material.color);
	}

	public void SetColor(UnityEngine.Vector3 rgb)
	{
		for (int i = 0; i < renderers.Length; i++)
		{
			renderers[i].material.SetColor(setColorTarget, new Color(rgb.x, rgb.y, rgb.z));
		}
		SetDirty();
	}
}
[RequireComponent(typeof(PhotonView))]
public class MaterialCyclerNetworked : MonoBehaviour
{
	[SerializeField]
	private float syncTimeOut = 1f;

	private PhotonView photonView;

	[SerializeField]
	private bool masterClientOnly;

	public float SyncTimeOut => syncTimeOut;

	public event Action<int, int3> OnSynchronize;

	private void Awake()
	{
		photonView = GetComponent<PhotonView>();
	}

	public void Synchronize(int materialIndex, Color c)
	{
		if (!masterClientOnly || PhotonNetwork.IsMasterClient)
		{
			int num = Mathf.CeilToInt(c.r * 9f);
			int num2 = Mathf.CeilToInt(c.g * 9f);
			int num3 = Mathf.CeilToInt(c.b * 9f);
			int num4 = num | (num2 << 8) | (num3 << 16);
			photonView.RPC("RPC_SynchronizePacked", RpcTarget.Others, materialIndex, num4);
		}
	}

	[PunRPC]
	public void RPC_SynchronizePacked(int index, int colourPacked, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "RPC_SynchronizePacked");
		if (this.OnSynchronize != null && (!masterClientOnly || info.Sender.IsMasterClient) && VRRigCache.Instance.TryGetVrrig(info.Sender, out var playerRig) && playerRig.Rig.IsPositionInRange(base.transform.position, 5f) && FXSystem.CheckCallSpam(playerRig.Rig.fxSettings, 21, info.SentServerTime))
		{
			int value = colourPacked & 0xFF;
			int value2 = (colourPacked >> 8) & 0xFF;
			int value3 = (colourPacked >> 16) & 0xFF;
			value = Mathf.Clamp(value, 0, 9);
			value2 = Mathf.Clamp(value2, 0, 9);
			value3 = Mathf.Clamp(value3, 0, 9);
			this.OnSynchronize(index, new int3(value, value2, value3));
		}
	}
}
