public class RoomConfig
{
	public const string Room_GameModePropKey = "gameMode";

	public const string Room_PlatformPropKey = "platform";

	public bool isPublic;

	public bool isJoinable;

	public byte MaxPlayers;

	public ExitGames.Client.Photon.Hashtable CustomProps = new ExitGames.Client.Photon.Hashtable();

	public bool createIfMissing;

	public string[] joinFriendIDs;

	public bool IsJoiningWithFriends
	{
		get
		{
			if (joinFriendIDs != null)
			{
				return joinFriendIDs.Length != 0;
			}
			return false;
		}
	}

	public void SetFriendIDs(List<string> friendIDs)
	{
		for (int i = 0; i < friendIDs.Count; i++)
		{
			if (friendIDs[i] == NetworkSystem.Instance.GetMyNickName())
			{
				friendIDs.RemoveAt(i);
				i--;
			}
		}
		joinFriendIDs = new string[friendIDs.Count];
		for (int j = 0; j < friendIDs.Count; j++)
		{
			joinFriendIDs[j] = friendIDs[j];
		}
	}

	public void ClearExpectedUsers()
	{
		if (joinFriendIDs != null && joinFriendIDs.Length != 0)
		{
			joinFriendIDs = new string[0];
		}
	}

	public RoomOptions ToPUNOpts()
	{
		return new RoomOptions
		{
			IsVisible = isPublic,
			IsOpen = isJoinable,
			MaxPlayers = MaxPlayers,
			CustomRoomProperties = CustomProps,
			PublishUserId = true,
			CustomRoomPropertiesForLobby = AutoCustomLobbyProps()
		};
	}

	public void SetFusionOpts(NetworkRunner runnerInst)
	{
		runnerInst.SessionInfo.IsVisible = isPublic;
		runnerInst.SessionInfo.IsOpen = isJoinable;
	}

	public static RoomConfig SPConfig()
	{
		return new RoomConfig
		{
			isPublic = false,
			isJoinable = false,
			MaxPlayers = 1
		};
	}

	public static RoomConfig AnyPublicConfig()
	{
		return new RoomConfig
		{
			isPublic = true,
			isJoinable = true,
			createIfMissing = true,
			MaxPlayers = 10
		};
	}

	private string[] AutoCustomLobbyProps()
	{
		string[] array = new string[CustomProps.Count];
		int num = 0;
		foreach (DictionaryEntry customProp in CustomProps)
		{
			array[num] = (string)customProp.Key;
			num++;
		}
		return array;
	}
}
public class NetworkWrapper : MonoBehaviour
{
	[HideInInspector]
	public NetworkSystem activeNetworkSystem;

	public Text titleRef;

	[Header("NetSys settings")]
	public NetworkSystemConfig netSysConfig;

	public string[] networkRegionNames;

	public string[] devNetworkRegionNames;

	[Header("Debug output refs")]
	public Text stateTextRef;

	public Text playerCountTextRef;

	[SerializeField]
	private SO_NetworkVoiceSettings VoiceSettings;

	private const string WrapperResourcePath = "P_NetworkWrapper";

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	public static void AutoInstantiate()
	{
		UnityEngine.Object.DontDestroyOnLoad(UnityEngine.Object.Instantiate(Resources.Load<GameObject>("P_NetworkWrapper")));
	}

	private void Awake()
	{
		if (titleRef != null)
		{
			titleRef.text = "PUN";
		}
		activeNetworkSystem = base.gameObject.AddComponent<NetworkSystemPUN>();
		activeNetworkSystem.AddVoiceSettings(VoiceSettings);
		activeNetworkSystem.config = netSysConfig;
		activeNetworkSystem.regionNames = networkRegionNames;
		activeNetworkSystem.OnPlayerJoined += new Action<NetPlayer>(UpdatePlayerCountWrapper);
		activeNetworkSystem.OnPlayerLeft += new Action<NetPlayer>(UpdatePlayerCountWrapper);
		activeNetworkSystem.OnMultiplayerStarted += new Action(UpdatePlayerCount);
		activeNetworkSystem.OnReturnedToSinglePlayer += new Action(UpdatePlayerCount);
		UnityEngine.Debug.Log("<color=green>initialize Network System</color>");
		activeNetworkSystem.Initialise();
	}

	private void UpdatePlayerCountWrapper(NetPlayer player)
	{
		UpdatePlayerCount();
	}

	private void UpdatePlayerCount()
	{
		if (!(playerCountTextRef == null))
		{
			if (!activeNetworkSystem.IsOnline)
			{
				playerCountTextRef.text = $"0/{netSysConfig.MaxPlayerCount}";
				UnityEngine.Debug.Log("Player count updated");
			}
			else
			{
				UnityEngine.Debug.Log("Player count not updated");
				playerCountTextRef.text = $"{activeNetworkSystem.AllNetPlayers.Length}/{netSysConfig.MaxPlayerCount}";
			}
		}
	}
}
public class NetworkRegionInfo
