	private int lowestPingRegionIndex
	{
		get
		{
			int num = 9999;
			int result = -1;
			for (int i = 0; i < regionData.Length; i++)
			{
				if (regionData[i].pingToRegion < num)
				{
					num = regionData[i].pingToRegion;
					result = i;
				}
			}
			return result;
		}
	}

