	{
		localScale = base.transform.localScale;
		ps = GetComponentsInChildren<ParticleSystem>();
		List<ParticleSystem.MainModule> list = new List<ParticleSystem.MainModule>();
		List<ParticleSystem.EmissionModule> list2 = new List<ParticleSystem.EmissionModule>();
		skipSet = new HashSet<ParticleSystem.MainModule>();
		for (int i = 0; i < ps.Length; i++)
		{
			list.Add(ps[i].main);
			list2.Add(ps[i].emission);
		}
		for (int j = 0; j < skipForSimulationSpeed.Length; j++)
		{
			skipSet.Add(skipForSimulationSpeed[j].GetComponent<ParticleSystem>().main);
		}
		psMains = list.ToArray();
		psEmits = list2.ToArray();
		SetPlayBackSpeed(0f);
	}

	public void SetFadeRate(float rate)
	{
		if (rate > 0f)
		{
			fadeRate = rate;
		}
	}

	public void SetPlayBackSpeed(float target)
	{
		for (int i = 0; i < psMains.Length; i++)
		{
			if (!skipSet.Contains(psMains[i]))
			{
				psMains[i].simulationSpeed = target;
			}
		}
	}

	public async void FadePlayBackSpeed(float target)
	{
		loop = fadeRate > 0f;
		while (loop)
		{
			for (int i = 0; i < psMains.Length; i++)
			{
				if (!skipSet.Contains(psMains[i]))
				{
					psMains[i].simulationSpeed = Mathf.MoveTowards(psMains[i].simulationSpeed, target, Time.deltaTime * fadeRate);
					loop = psMains[i].simulationSpeed != target;
				}
			}
			await Task.Yield();
		}
	}

	public void SetColor(string RRGGBB)
	{
		Color color = new Color((float)int.Parse(RRGGBB.Substring(0, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBB.Substring(2, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBB.Substring(4, 2), NumberStyles.HexNumber) / 255f);
		Color.RGBToHSV(color, out var H, out var S, out var V);
		Color max = Color.HSVToRGB(H, S, V / 4f);
		for (int i = 0; i < psMains.Length; i++)
		{
			psMains[i].startColor = new ParticleSystem.MinMaxGradient(color, max);
		}
	}

	public void SetColors(string RRGGBBRRGGBB)
	{
		Color min = new Color((float)int.Parse(RRGGBBRRGGBB.Substring(0, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBBRRGGBB.Substring(2, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBBRRGGBB.Substring(4, 2), NumberStyles.HexNumber) / 255f);
		Color max = new Color((float)int.Parse(RRGGBBRRGGBB.Substring(6, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBBRRGGBB.Substring(8, 2), NumberStyles.HexNumber) / 255f, (float)int.Parse(RRGGBBRRGGBB.Substring(10, 2), NumberStyles.HexNumber) / 255f);
		for (int i = 0; i < psMains.Length; i++)
		{
			psMains[i].startColor = new ParticleSystem.MinMaxGradient(min, max);
		}
	}

	public void Pause()
	{
		for (int i = 0; i < ps.Length; i++)
		{
			ps[i].Pause();
		}
	}

	public void StartEmission()
	{
		for (int i = 0; i < ps.Length; i++)
		{
			psMains[i].prewarm = false;
			ps[i].Play();
		}
		for (int j = 0; j < ActiveDuringEmission.Length; j++)
		{
			ActiveDuringEmission[j].SetActive(value: true);
		}
	}

	public void StopEmission()
	{
		for (int i = 0; i < ps.Length; i++)
		{
			ps[i].Stop();
		}
		for (int j = 0; j < ActiveDuringEmission.Length; j++)
		{
			ActiveDuringEmission[j].SetActive(value: false);
		}
	}

	public void Clear()
	{
		for (int i = 0; i < ps.Length; i++)
		{
			ps[i].Clear();
		}
	}

	public void SetScaleXZ(float scaler)
	{
		base.transform.localScale = new UnityEngine.Vector3(localScale.x * scaler, localScale.y, localScale.z * scaler);
	}

	public async void FadeScaleXZ(float scaler)
	{
		UnityEngine.Vector3 targetScale = new UnityEngine.Vector3(localScale.x * scaler, localScale.y, localScale.z * scaler);
		loop = fadeRate > 0f;
		while (loop)
		{
			for (int i = 0; i < psMains.Length; i++)
			{
				base.transform.localScale = UnityEngine.Vector3.MoveTowards(base.transform.localScale, targetScale, Time.deltaTime * fadeRate);
			}
			loop = base.transform.localScale != targetScale;
			await Task.Yield();
		}
	}
}
public class PersistLog : MonoBehaviour
{
	private static StreamWriter sr;

	private string plog;

	private bool dup;

	private List<Tuple<string, string>> earlyQ;

	private async void OnEnable()
	{
		earlyQ = new List<Tuple<string, string>>();
		UnityEngine.Application.logMessageReceived += LogMessageEnqueue;
		while (GorillaComputer.instance == null)
		{
			await Task.Yield();
		}
		string text = UnityEngine.Application.persistentDataPath + System.IO.Path.DirectorySeparatorChar;
		string text2 = text + "gt.log";
		string text3 = text + "gt-old.log";
		string destFileName = text + "gt-older.log";
		try
		{
			if (File.Exists(text3))
			{
				File.Copy(text3, destFileName, overwrite: true);
			}
		}
		catch (IOException)
		{
		}
		try
		{
			if (File.Exists(text2))
			{
				File.Copy(text2, text3, overwrite: true);
			}
		}
		catch (IOException)
		{
		}
		string path = text2;
		for (int i = 1; i <= 10; i++)
		{
			try
			{
				sr = File.CreateText(path);
			}
			catch (IOException) when (i < 10)
			{
				path = text + "gt_" + (i + 1) + ".log";
				continue;
			}
			break;
		}
		if (sr == null)
		{
			UnityEngine.Debug.LogError("[PersistLog] Failed to create log file after 10 attempts.");
			UnityEngine.Application.logMessageReceived -= LogMessageEnqueue;
			return;
		}
		sr.Write($"{DateTime.Now:U}\r\n\r\n                           MONKE WUZ HERE!\r\n               _______    /\r\n              /       \\\r\n             /  _____  \\\r\n            / / _   _ \\ \\\r\n           [ | (O) (O) | ]\r\n            | \\  . .  / |\r\n     _______|  | _._ |  |_______\r\n    /        \\  \\___/  /        \\\r\n\r\nApp Id:        {UnityEngine.Application.identifier}\r\nApp Ver:       {UnityEngine.Application.version}\r\nPlatform:      {UnityEngine.Application.platform}\r\nSys Lang:      {UnityEngine.Application.systemLanguage}\r\nGC Version:    {GorillaComputer.instance.version}\r\nGC Build Code: {GorillaComputer.instance.buildCode}\r\nGC Build Date: {GorillaComputer.instance.buildDate}\r\n\r\n");
		UnityEngine.Application.logMessageReceived -= LogMessageEnqueue;
		for (int j = 0; j < earlyQ.Count; j++)
		{
			sr.Write($"T+{Time.time} >> {earlyQ[j].Item1}\n==========================\n{earlyQ[j].Item2}\n\n");
		}
		sr.Flush();
		UnityEngine.Application.logMessageReceived += LogMessageReceived;
	}

	private void OnDisable()
	{
		OnDestroy();
	}

	private void OnDestroy()
	{
		UnityEngine.Application.logMessageReceived -= LogMessageEnqueue;
		UnityEngine.Application.logMessageReceived -= LogMessageReceived;
		if (sr != null)
		{
			sr.Close();
			sr = null;
		}
	}

	private void LogMessageEnqueue(string msg, string strace, UnityEngine.LogType type)
	{
		if (type == UnityEngine.LogType.Error || type == UnityEngine.LogType.Assert || type == UnityEngine.LogType.Exception)
		{
			earlyQ.Add(Tuple.Create(msg, strace));
		}
	}

	private void LogMessageReceived(string msg, string strace, UnityEngine.LogType type)
	{
		if (type == UnityEngine.LogType.Error || type == UnityEngine.LogType.Assert || type == UnityEngine.LogType.Exception)
		{
			if (plog == msg + strace)
			{
				if (!dup)
				{
					sr.Write($"T+{Time.time} >> Duplicate log entry... Supressing further\n\n");
					dup = true;
				}
			}
			else
			{
				sr.Write($"T+{Time.time} >> {msg}\n==========================\n{strace}\n\n");
				dup = false;
			}
			sr.Flush();
		}
		plog = msg + strace;
	}

	public static void Log(string msg)
	{
		msg = $"T+{Time.time} >[DEV MSG]> {msg}\n\n";
		UnityEngine.Debug.Log(msg);
		if (sr != null)
		{
			sr.Write(msg);
			sr.Flush();
		}
	}
}
public class PhotoBoothCamera : MonoBehaviour
{
	[SerializeField]
	private Camera cam;

	[SerializeField]
	private RenderTexture renderTexture;

	[SerializeField]
	private TMP_Text imageLabel;

	[SerializeField]
	private Image imageImage;

	[SerializeField]
	private string saveName = "img";

	[SerializeField]
	private bool appendDateToFile;

	[SerializeField]
	private string imageDescription = "";

	private List<RenderTexture> rt = new List<RenderTexture>();

	public Action<Texture, int> OnCapture;

	private bool saveImageToDevice;

	public void SetSaveImageToDevice(bool b)
	{
		saveImageToDevice = b;
	}

	public void Clear()
	{
		rt.Clear();
	}

	public void Capture(float FOV)
	{
		cam.fieldOfView = FOV;
		cam.Render();
		rt.Add(new RenderTexture(renderTexture.width, renderTexture.height, 1));
		Graphics.Blit(renderTexture, rt[rt.Count - 1]);
		OnCapture(rt[rt.Count - 1], rt.Count - 1);
	}

	public void Print()
	{
		if (!saveImageToDevice)
		{
			return;
		}
		string fileName = saveName;
		if (appendDateToFile)
		{
			DateTime dateTime = DateTime.UtcNow;
			if (GorillaComputer.instance != null)
			{
				dateTime = GorillaComputer.instance.GetServerTime();
			}
			fileName += dateTime.ToString("yyyyMMddHHmmss");
		}
		RenderTexture print = new RenderTexture(renderTexture.width, renderTexture.height * rt.Count, 1);
		for (int i = 0; i < rt.Count; i++)
		{
			Graphics.CopyTexture(rt[i], 0, 0, 0, 0, rt[i].width, rt[i].height, print, 0, 0, 0, rt[i].height * i);
		}
		NativeArray<byte> narray = new NativeArray<byte>(print.width * print.height * 4, Unity.Collections.Allocator.Persistent, NativeArrayOptions.UninitializedMemory);
		AsyncGPUReadback.RequestIntoNativeArray(ref narray, print, 0, delegate(AsyncGPUReadbackRequest request)
		{
			if (!request.hasError)
			{
				SaveImage(print, narray, fileName, imageDescription);
			}
			narray.Dispose();
		});
	}

	private void SaveImage(RenderTexture rt, NativeArray<byte> narray, string fileName, string desc)
	{
		NativeArray<byte> nativeArray = ImageConversion.EncodeNativeArrayToJPG(narray, rt.graphicsFormat, (uint)rt.width, (uint)rt.height);
		File.WriteAllBytes(System.IO.Path.Combine(UnityEngine.Application.persistentDataPath, fileName + ".jpg"), nativeArray.ToArray());
		nativeArray.Dispose();
	}
}
