public class GorillaMetaReport : MonoBehaviour
{
	[SerializeField]
	private GameObject occluder;

	[SerializeField]
	private GameObject reportScoreboard;

	[SerializeField]
	private GameObject ReportText;

	[SerializeField]
	private LayerMask visibleLayers;

	[SerializeField]
	private GorillaReportButton closeButton;

	[SerializeField]
	private GameObject leftHandObject;

	[SerializeField]
	private GameObject rightHandObject;

	[SerializeField]
	private UnityEngine.Vector3 playerLocalScreenPosition;

	private float blockButtonsUntilTimestamp;

	[SerializeField]
	private GorillaScoreBoard currentScoreboard;

	private int savedCullingLayers;

	private bool hasSavedCullingMask;

	public bool testPress;

	public bool isMoving;

	private float movementTime;

	private GTPlayer localPlayer => GTPlayer.Instance;

	private void Start()
	{
		localPlayer.inOverlay = false;
		MothershipClientApiUnity.OnMessageNotificationSocket += new Action<NotificationsMessageResponse, IntPtr>(OnNotification);
		base.gameObject.SetActive(value: false);
	}

	private void OnDisable()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			localPlayer.inOverlay = false;
			StopAllCoroutines();
		}
	}

	private void OnReportButtonIntentNotif(Message<string> message)
	{
		if (message.IsError)
		{
			AbuseReport.ReportRequestHandled(ReportRequestResponse.Unhandled);
		}
		else if (!PhotonNetwork.InRoom)
		{
			ReportText.SetActive(value: true);
			AbuseReport.ReportRequestHandled(ReportRequestResponse.Handled);
			StartOverlay();
		}
		else if (!message.IsError)
		{
			AbuseReport.ReportRequestHandled(ReportRequestResponse.Handled);
			StartOverlay();
		}
	}

	private void OnNotification(NotificationsMessageResponse notification, nint _)
	{
		switch (notification.Title)
		{
		case "Warning":
			OnWarning(notification.Body);
			GorillaTelemetry.PostNotificationEvent("Warning");
			break;
		case "Mute":
			OnMuteSanction(notification.Body);
			GorillaTelemetry.PostNotificationEvent("Mute");
			break;
		case "Unmute":
			if (GorillaTagger.hasInstance)
			{
				GorillaTagger.moderationMutedTime = -1f;
			}
			GorillaTelemetry.PostNotificationEvent("Unmute");
			break;
		}
	}

	private void OnWarning(string warningNotification)
	{
		string[] array = warningNotification.Split('|');
		if (array.Length != 2)
		{
			UnityEngine.Debug.LogError("Invalid warning notification");
			return;
		}
		string text = array[0];
		string[] list = array[1].Split(',');
		if (list.Length == 0)
		{
			UnityEngine.Debug.LogError("Missing warning notification reasons");
			return;
		}
		string text2 = FormatListToString(in list);
		ReportText.GetComponent<Text>().text = text.ToUpper() + " WARNING FOR " + text2.ToUpper();
		StartOverlay(isSanction: true);
	}

	private void OnMuteSanction(string muteNotification)
	{
		string[] array = muteNotification.Split('|');
		if (array.Length != 3)
		{
			UnityEngine.Debug.LogError("Invalid mute notification");
		}
		else
		{
			if (!array[0].Equals("voice", StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
			if (array[2].Length > 0 && int.TryParse(array[2], out var result))
			{
				int num = result / 60;
				ReportText.GetComponent<Text>().text = $"MUTED FOR {num} MINUTES\nBAD MONKE";
				if (GorillaTagger.hasInstance)
				{
					GorillaTagger.moderationMutedTime = result;
				}
			}
			else
			{
				ReportText.GetComponent<Text>().text = "MUTED FOREVER";
				if (GorillaTagger.hasInstance)
				{
					GorillaTagger.moderationMutedTime = float.PositiveInfinity;
				}
			}
			StartOverlay(isSanction: true);
		}
	}

	private static string FormatListToString(in string[] list)
	{
		return list.Length switch
		{
			1 => list[0], 
			2 => list[0] + " AND " + list[1], 
			_ => list[..^1].Join(", ") + ", AND " + list[^1], 
		};
	}

	private IEnumerator Submitted()
	{
		yield return new WaitForSeconds(1.5f);
		Teardown();
	}

	private void DuplicateScoreboard()
	{
		currentScoreboard.gameObject.SetActive(value: true);
		if (GorillaScoreboardTotalUpdater.instance != null)
		{
			GorillaScoreboardTotalUpdater.instance.UpdateScoreboard(currentScoreboard);
		}
		GetIdealScreenPositionRotation(out var position, out var rotation, out var _);
		currentScoreboard.transform.SetPositionAndRotation(position, rotation);
		reportScoreboard.transform.SetPositionAndRotation(position, rotation);
	}

	private void ToggleLevelVisibility(bool state)
	{
		Camera component = GorillaTagger.Instance.mainCamera.GetComponent<Camera>();
		if (state)
		{
			if (hasSavedCullingMask)
			{
				component.cullingMask = savedCullingLayers;
				hasSavedCullingMask = false;
			}
			return;
		}
		if (!hasSavedCullingMask)
		{
			savedCullingLayers = component.cullingMask;
			hasSavedCullingMask = true;
		}
		component.cullingMask = visibleLayers;
	}

	private void Teardown()
	{
		ReportText.GetComponent<Text>().text = "NOT CURRENTLY CONNECTED TO A ROOM";
		ReportText.SetActive(value: false);
		localPlayer.inOverlay = false;
		localPlayer.disableMovement = false;
		closeButton.selected = false;
		closeButton.isOn = false;
		closeButton.UpdateColor();
		localPlayer.InReportMenu = false;
		ToggleLevelVisibility(state: true);
		base.gameObject.SetActive(value: false);
		foreach (GorillaPlayerScoreboardLine line in currentScoreboard.lines)
		{
			line.doneReporting = false;
		}
		GorillaScoreboardTotalUpdater.instance.UpdateActiveScoreboards();
	}

	private void CheckReportSubmit()
	{
		if (currentScoreboard == null)
		{
			return;
		}
		foreach (GorillaPlayerScoreboardLine line in currentScoreboard.lines)
		{
			if (line.doneReporting)
			{
				ReportText.SetActive(value: true);
				ReportText.GetComponent<Text>().text = "REPORTED " + line.playerNameVisible;
				currentScoreboard.gameObject.SetActive(value: false);
				StartCoroutine(Submitted());
			}
		}
	}

	private void GetIdealScreenPositionRotation(out UnityEngine.Vector3 position, out UnityEngine.Quaternion rotation, out UnityEngine.Vector3 scale)
	{
		GameObject mainCamera = GorillaTagger.Instance.mainCamera;
		rotation = UnityEngine.Quaternion.Euler(0f, mainCamera.transform.eulerAngles.y, 0f);
		scale = localPlayer.turnParent.transform.localScale;
		position = mainCamera.transform.position + rotation * playerLocalScreenPosition * scale.x;
	}

	private void StartOverlay(bool isSanction = false)
	{
		if (localPlayer.InReportMenu)
		{
			return;
		}
		GetIdealScreenPositionRotation(out var position, out var rotation, out var scale);
		currentScoreboard.transform.localScale = scale * 2f;
		reportScoreboard.transform.localScale = scale;
		leftHandObject.transform.localScale = scale;
		rightHandObject.transform.localScale = scale;
		occluder.transform.localScale = scale;
		if (PhotonNetwork.InRoom)
		{
			localPlayer.InReportMenu = true;
			localPlayer.disableMovement = true;
			localPlayer.inOverlay = true;
			base.gameObject.SetActive(value: true);
			if (PhotonNetwork.InRoom && !isSanction)
			{
				DuplicateScoreboard();
			}
			else
			{
				ReportText.SetActive(value: true);
				reportScoreboard.transform.SetPositionAndRotation(position, rotation);
				currentScoreboard.transform.SetPositionAndRotation(position, rotation);
			}
			ToggleLevelVisibility(state: false);
			Transform controllerTransform = localPlayer.GetControllerTransform(isLeftHand: true);
			Transform controllerTransform2 = localPlayer.GetControllerTransform(isLeftHand: false);
			rightHandObject.transform.SetPositionAndRotation(controllerTransform2.position, controllerTransform2.rotation);
			leftHandObject.transform.SetPositionAndRotation(controllerTransform.position, controllerTransform.rotation);
			if (isSanction)
			{
				currentScoreboard.gameObject.SetActive(value: false);
			}
			else
			{
				currentScoreboard.gameObject.SetActive(value: true);
			}
		}
	}

	private void CheckDistance()
	{
		GetIdealScreenPositionRotation(out var position, out var rotation, out var _);
		float num = UnityEngine.Vector3.Distance(reportScoreboard.transform.position, position);
		float num2 = 1f;
		if (num > num2 && !isMoving)
		{
			isMoving = true;
			movementTime = 0f;
		}
		if (isMoving)
		{
			movementTime += Time.deltaTime;
			float num3 = movementTime;
			reportScoreboard.transform.SetPositionAndRotation(UnityEngine.Vector3.Lerp(reportScoreboard.transform.position, position, num3), UnityEngine.Quaternion.Lerp(reportScoreboard.transform.rotation, rotation, num3));
			if (currentScoreboard != null)
			{
				currentScoreboard.transform.SetPositionAndRotation(UnityEngine.Vector3.Lerp(currentScoreboard.transform.position, position, num3), UnityEngine.Quaternion.Lerp(currentScoreboard.transform.rotation, rotation, num3));
			}
			if (num3 >= 1f)
			{
				isMoving = false;
				movementTime = 0f;
			}
		}
	}

	private void Update()
	{
		if (!(blockButtonsUntilTimestamp > Time.time))
		{
			if (SteamVR_Actions.gorillaTag_System.GetState(SteamVR_Input_Sources.LeftHand) && localPlayer.InReportMenu)
			{
				Teardown();
				blockButtonsUntilTimestamp = Time.time + 0.75f;
			}
			if (localPlayer.InReportMenu)
			{
				localPlayer.inOverlay = true;
				occluder.transform.position = GorillaTagger.Instance.mainCamera.transform.position;
				Transform controllerTransform = localPlayer.GetControllerTransform(isLeftHand: true);
				Transform controllerTransform2 = localPlayer.GetControllerTransform(isLeftHand: false);
				rightHandObject.transform.SetPositionAndRotation(controllerTransform2.position, controllerTransform2.rotation);
				leftHandObject.transform.SetPositionAndRotation(controllerTransform.position, controllerTransform.rotation);
				CheckDistance();
				CheckReportSubmit();
			}
			if (closeButton.selected)
			{
				Teardown();
			}
			if (testPress)
			{
				testPress = false;
				StartOverlay();
			}
		}
	}
}
public class GorillaReportButton : MonoBehaviour
{
	[SerializeField]
	public enum MetaReportReason
	{
		HateSpeech,
		Cheating,
		Toxicity,
		Bullying,
		Doxing,
		Impersonation,
		Submit,
		Cancel
	}

	public MetaReportReason metaReportType;

	public GorillaPlayerLineButton.ButtonType buttonType;

	public GorillaPlayerScoreboardLine parentLine;

	public bool isOn;

	public Material offMaterial;

	public Material onMaterial;

	public string offText;

	public string onText;

	public Text myText;

	public float debounceTime = 0.25f;

	public float touchTime;

	public bool testPress;

	public bool selected;

	public void AssignParentLine(GorillaPlayerScoreboardLine parent)
	{
		parentLine = parent;
	}

	private void OnTriggerEnter(Collider collider)
	{
		if (base.enabled && touchTime + debounceTime < Time.time)
		{
			isOn = !isOn;
			UpdateColor();
			selected = !selected;
			touchTime = Time.time;
			GorillaTagger.Instance.StartVibration(forLeftController: false, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(67, isLeftHand: false, 0.05f);
			if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
			{
				GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, false, 0.05f);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (metaReportType != MetaReportReason.Cancel)
		{
			_ = other.GetComponentInParent<GorillaTriggerColliderHandIndicator>() != null;
		}
	}

	public void UpdateColor()
	{
		if (isOn)
		{
			GetComponent<MeshRenderer>().material = onMaterial;
		}
		else
		{
			GetComponent<MeshRenderer>().material = offMaterial;
		}
	}
}
public class PrivateUIRoom : MonoBehaviourTick
{
	[Flags]
	public enum OverlaySource
	{
		KID = 1,
		ModIO = 2,
		CustomMap = 4,
		AlarmClock = 8
	}

	[SerializeField]
	private TextMeshPro _text;

	[SerializeField]
	private float _textDistance = 4f;

	[SerializeField]
	private GameObject occluder;

	[SerializeField]
	private LayerMask visibleLayers;

	[SerializeField]
	private GameObject leftHandObject;

	[SerializeField]
	private GameObject rightHandObject;

	[SerializeField]
	private MeshRenderer backgroundRenderer;

	[SerializeField]
	private string backgroundDirectionPropertyName = "_SpotDirection";

	private int backgroundDirectionPropertyID;

	private int savedCullingLayers;

	private Transform _uiRoot;

	private Transform focusTransform;

	private List<Transform> ui;

	private Dictionary<Transform, Transform> uiParents;

	private float _initialAudioVolume;

	private bool inOverlay;

	private OverlaySource overlayForcedSources;

	private static PrivateUIRoom instance;

	private UnityEngine.Vector3 lastStablePosition;

	private UnityEngine.Quaternion lastStableRotation;

	[SerializeField]
	private float verticalPlay = 0.1f;

	[SerializeField]
	private float lateralPlay = 0.5f;

	[SerializeField]
	private float rotationalPlay = 45f;

	private int? savedCullingLayersShoudlerCam;

	private static Camera _shoulderCameraReference;

	private static CinemachineVirtualCamera _virtualCameraReference;

	private bool overlayForcedActive => overlayForcedSources != (OverlaySource)0;

	private GTPlayer localPlayer => GTPlayer.Instance;

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
			occluder.SetActive(value: false);
			leftHandObject.SetActive(value: false);
			rightHandObject.SetActive(value: false);
			ui = new List<Transform>();
			uiParents = new Dictionary<Transform, Transform>();
			backgroundDirectionPropertyID = Shader.PropertyToID(backgroundDirectionPropertyName);
			_uiRoot = new GameObject("UIRoot").transform;
			_uiRoot.parent = base.transform;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private new void OnEnable()
	{
		base.OnEnable();
		SteamVR_Events.System(EVREventType.VREvent_InputFocusChanged).Listen(ToggleHands);
	}

	private new void OnDisable()
	{
		base.OnDisable();
		SteamVR_Events.System(EVREventType.VREvent_InputFocusChanged).Remove(ToggleHands);
	}

	private static bool FindShoulderCamera()
	{
		if (_shoulderCameraReference.IsNotNull())
		{
			return true;
		}
		if (GTExt.IsNull(GorillaTagger.Instance))
		{
			return false;
		}
		_shoulderCameraReference = GorillaTagger.Instance.thirdPersonCamera.GetComponentInChildren<Camera>(includeInactive: true);
		if (_shoulderCameraReference == null)
		{
			UnityEngine.Debug.LogError("[PRIVATE_UI_ROOMS] Could not find Shoulder Camera");
			return false;
		}
		_virtualCameraReference = _shoulderCameraReference.GetComponentInChildren<CinemachineVirtualCamera>();
		return true;
	}

	private void ToggleHands(VREvent_t ev)
	{
		UnityEngine.Debug.Log($"[PrivateUIRoom::ToggleHands] Toggling hands visibility. Event: {ev.eventType} ({(EVREventType)ev.eventType})");
		UnityEngine.Debug.Log($"[PrivateUIRoom::ToggleHands] _handsShowing: {instance.rightHandObject.activeSelf}");
		if (instance.rightHandObject.activeSelf)
		{
			HideHands();
		}
		else
		{
			ShowHands();
		}
	}

	private void HideHands()
	{
		UnityEngine.Debug.Log("[PrivateUIRoom::OnSteamMenuShown] Steam menu shown, disabling hands.");
		instance.leftHandObject.SetActive(value: false);
		instance.rightHandObject.SetActive(value: false);
	}

	private void ShowHands()
	{
		UnityEngine.Debug.Log("[PrivateUIRoom::OnSteamMenuShown] Steam menu hidden, re-enabling hands.");
		instance.leftHandObject.SetActive(value: true);
		instance.rightHandObject.SetActive(value: true);
	}

	private void ToggleLevelVisibility(bool levelShouldBeVisible)
	{
		Camera component = GorillaTagger.Instance.mainCamera.GetComponent<Camera>();
		if (levelShouldBeVisible)
		{
			component.cullingMask = savedCullingLayers;
			if (savedCullingLayersShoudlerCam.HasValue)
			{
				_shoulderCameraReference.cullingMask = savedCullingLayersShoudlerCam.Value;
				savedCullingLayersShoudlerCam = null;
			}
			return;
		}
		savedCullingLayers = component.cullingMask;
		component.cullingMask = visibleLayers;
		if (FindShoulderCamera())
		{
			savedCullingLayersShoudlerCam = _shoulderCameraReference.cullingMask;
			_shoulderCameraReference.cullingMask = visibleLayers;
			_virtualCameraReference.enabled = false;
		}
	}

	private static void StopOverlay()
	{
		instance.localPlayer.inOverlay = false;
		instance.inOverlay = false;
		instance.localPlayer.disableMovement = false;
		instance.localPlayer.InReportMenu = false;
		instance.ToggleLevelVisibility(levelShouldBeVisible: true);
		instance.occluder.SetActive(value: false);
		instance.leftHandObject.SetActive(value: false);
		instance.rightHandObject.SetActive(value: false);
		_virtualCameraReference.enabled = true;
		KIDAudioManager.Instance.SetKIDUIAudioActive(active: false);
		UnityEngine.Debug.Log("[PrivateUIRoom::StopOverlay] Re-enabling Game Audio");
	}

	private void GetIdealScreenPositionRotation(out UnityEngine.Vector3 position, out UnityEngine.Quaternion rotation, out UnityEngine.Vector3 scale)
	{
		GameObject mainCamera = GorillaTagger.Instance.mainCamera;
		rotation = UnityEngine.Quaternion.Euler(0f, mainCamera.transform.eulerAngles.y, 0f);
		scale = localPlayer.turnParent.transform.localScale;
		position = mainCamera.transform.position + rotation * UnityEngine.Vector3.zero * scale.x;
	}

	private static void AssignShoulderCameraToCanvases(Transform focus)
	{
		UnityEngine.Debug.Log("[KID::PrivateUIRoom::CanvasCameraAssigner] setting up canvases with shoulder camera.");
		if (FindShoulderCamera())
		{
			Canvas componentInChildren = focus.GetComponentInChildren<Canvas>(includeInactive: true);
			if (componentInChildren != null)
			{
				componentInChildren.worldCamera = _shoulderCameraReference;
				UnityEngine.Debug.Log("[KID::PrivateUIRoom::CanvasCameraAssigner] Assigned shoulder camera to Canvas: " + componentInChildren.name);
			}
			else
			{
				UnityEngine.Debug.LogError("[KID::PrivateUIRoom::CanvasCameraAssigner] No Canvas component found on this GameObject.");
			}
		}
	}

	public static void AddUI(Transform focus)
	{
		if (instance.ui.Contains(focus))
		{
			return;
		}
		instance._text.text = "";
		AssignShoulderCameraToCanvases(focus);
		instance.uiParents.Add(focus, focus.parent);
		focus.gameObject.SetActive(value: false);
		focus.parent = instance._uiRoot;
		focus.localPosition = UnityEngine.Vector3.zero;
		focus.localRotation = UnityEngine.Quaternion.identity;
		instance.ui.Add(focus);
		if (instance.ui.Count == 1 && instance.focusTransform == null)
		{
			instance.focusTransform = instance.ui[0];
			instance.focusTransform.gameObject.SetActive(value: true);
			if (!instance.inOverlay)
			{
				StartOverlay();
			}
		}
		instance.UpdateUIPositionAndRotation();
	}

	public static void RemoveUI(Transform focus)
	{
		if (instance.ui.Contains(focus))
		{
			focus.gameObject.SetActive(value: false);
			instance.ui.Remove(focus);
			if (instance.focusTransform == focus)
			{
				instance.focusTransform = null;
			}
			if (instance.uiParents[focus] != null)
			{
				focus.parent = instance.uiParents[focus];
				instance.uiParents.Remove(focus);
			}
			else
			{
				UnityEngine.Object.Destroy(focus.gameObject);
			}
			if (instance.ui.Count > 0)
			{
				instance.focusTransform = instance.ui[0];
				instance.focusTransform.gameObject.SetActive(value: true);
			}
			else if (!instance.overlayForcedActive)
			{
				StopOverlay();
			}
		}
	}

	public static void ForceStartOverlay(OverlaySource source, string text = "")
	{
		if (!(instance == null))
		{
			instance.overlayForcedSources |= source;
			if (!instance.inOverlay)
			{
				instance._text.text = text;
				StartOverlay();
			}
		}
	}

	public static void StopForcedOverlay(OverlaySource source)
	{
		if (!(instance == null))
		{
			instance.overlayForcedSources &= ~source;
			if (!instance.overlayForcedActive && instance.ui.Count == 0 && instance.inOverlay)
			{
				StopOverlay();
			}
		}
	}

	private static void StartOverlay()
	{
		instance.GetIdealScreenPositionRotation(out var _, out var _, out var scale);
		instance.leftHandObject.transform.localScale = scale;
		instance.rightHandObject.transform.localScale = scale;
		instance.occluder.transform.localScale = scale;
		instance.localPlayer.InReportMenu = true;
		instance.localPlayer.disableMovement = true;
		instance.occluder.SetActive(value: true);
		instance.rightHandObject.SetActive(value: true);
		instance.leftHandObject.SetActive(value: true);
		instance.ToggleLevelVisibility(levelShouldBeVisible: false);
		instance.localPlayer.inOverlay = true;
		instance.inOverlay = true;
		KIDAudioManager.Instance.SetKIDUIAudioActive(active: true);
		UnityEngine.Debug.Log("[PrivateUIRoom::StartOverlay] Muting Game Audio");
	}

	public override void Tick()
	{
		if (localPlayer.InReportMenu)
		{
			occluder.transform.position = GorillaTagger.Instance.mainCamera.transform.position;
			Transform controllerTransform = localPlayer.GetControllerTransform(isLeftHand: true);
			Transform controllerTransform2 = localPlayer.GetControllerTransform(isLeftHand: false);
			rightHandObject.transform.SetPositionAndRotation(controllerTransform2.position, controllerTransform2.rotation);
			leftHandObject.transform.SetPositionAndRotation(controllerTransform.position, controllerTransform.rotation);
			if (ShouldUpdateRotation())
			{
				UpdateUIPositionAndRotation();
			}
			else if (ShouldUpdatePosition())
			{
				UpdateUIPosition();
			}
		}
	}

	private bool ShouldUpdateRotation()
	{
		float magnitude = (GorillaTagger.Instance.mainCamera.transform.position - lastStablePosition).X_Z().magnitude;
		float num = UnityEngine.Quaternion.Angle(b: UnityEngine.Quaternion.Euler(0f, GorillaTagger.Instance.mainCamera.transform.rotation.eulerAngles.y, 0f), a: lastStableRotation);
		if (!(magnitude > lateralPlay))
		{
			return num >= rotationalPlay;
		}
		return true;
	}

	private bool ShouldUpdatePosition()
	{
		return Mathf.Abs(GorillaTagger.Instance.mainCamera.transform.position.y - lastStablePosition.y) > verticalPlay;
	}

	private void UpdateUIPositionAndRotation()
	{
		Transform transform = GorillaTagger.Instance.mainCamera.transform;
		lastStablePosition = transform.position;
		lastStableRotation = transform.rotation;
		UnityEngine.Vector3 normalized = transform.forward.X_Z().normalized;
		_uiRoot.SetPositionAndRotation(lastStablePosition + normalized * 0.02f, UnityEngine.Quaternion.LookRotation(normalized));
		_shoulderCameraReference.transform.position = _uiRoot.position;
		_shoulderCameraReference.transform.rotation = _uiRoot.rotation;
		backgroundRenderer.material.SetVector(backgroundDirectionPropertyID, backgroundRenderer.transform.InverseTransformDirection(normalized));
		SetTextPositionAndRotation(transform);
	}

	private void SetTextPositionAndRotation(Transform pov)
	{
		if (_text.enabled && !string.IsNullOrEmpty(_text.text))
		{
			_text.transform.position = pov.position + _textDistance * (pov.rotation * UnityEngine.Vector3.forward);
			_text.transform.rotation = UnityEngine.Quaternion.LookRotation(pov.rotation * UnityEngine.Vector3.forward, UnityEngine.Vector3.up);
		}
	}

	private void UpdateUIPosition()
	{
		Transform transform = GorillaTagger.Instance.mainCamera.transform;
		lastStablePosition = transform.position;
		_uiRoot.position = lastStablePosition + lastStableRotation * new UnityEngine.Vector3(0f, 0f, 0.02f);
		_shoulderCameraReference.transform.position = _uiRoot.position;
		SetTextPositionAndRotation(transform);
	}

	public static bool GetInOverlay()
	{
		if (instance == null)
		{
			return false;
		}
		return instance.inOverlay;
	}
}
public class BalloonDynamics : MonoBehaviour, ITetheredObjectBehavior
{
	private Rigidbody rb;

	private Collider balloonCollider;

	private Bounds bounds;

	public float bouyancyForce = 1f;

	public float bouyancyMinHeight = 10f;

	public float bouyancyMaxHeight = 20f;

	private float bouyancyActualHeight = 20f;

	public float varianceMaxheight = 5f;

	public float airResistance = 0.01f;

	public GameObject knot;

	private Rigidbody knotRb;

	public Transform grabPt;

	private Transform grabPtInitParent;

	public float stringLength = 2f;

	public float stringStrength = 0.9f;

	public float stringStretch = 0.1f;

	public float maximumVelocity = 2f;

	public float upRightTorque = 1f;

	public float antiSpinTorque;

	private bool enableDynamics;

	private bool enableDistanceConstraints;

	public float balloonScale = 1f;

	public float bopSpeed = 1f;

	public float bopSpeedCap;

	[SerializeField]
	private AudioSource balloonBopSource;

	public bool ColliderEnabled
	{
		get
		{
			if ((bool)balloonCollider)
			{
				return balloonCollider.enabled;
			}
			return false;
		}
	}

	private void Awake()
	{
		rb = GetComponent<Rigidbody>();
		knotRb = knot.GetComponent<Rigidbody>();
		balloonCollider = GetComponent<Collider>();
		grabPtInitParent = grabPt.transform.parent;
	}

	private void Start()
	{
		airResistance = Mathf.Clamp(airResistance, 0f, 1f);
		balloonCollider.enabled = false;
	}

	public void ReParent()
	{
		if (grabPt != null)
		{
			grabPt.transform.parent = grabPtInitParent.transform;
		}
		bouyancyActualHeight = UnityEngine.Random.Range(bouyancyMinHeight, bouyancyMaxHeight);
	}

	private void ApplyBouyancyForce()
	{
		float num = bouyancyActualHeight + Mathf.Sin(Time.time) * varianceMaxheight;
		float num2 = (num - base.transform.position.y) / num;
		float y = bouyancyForce * num2 * balloonScale;
		rb.AddForce(new UnityEngine.Vector3(0f, y, 0f) * rb.mass, ForceMode.Force);
	}

	private void ApplyUpRightForce()
	{
		UnityEngine.Vector3 torque = UnityEngine.Vector3.Cross(base.transform.up, UnityEngine.Vector3.up) * upRightTorque * balloonScale;
		rb.AddTorque(torque);
	}

	private void ApplyAntiSpinForce()
	{
		UnityEngine.Vector3 vector = rb.transform.InverseTransformDirection(rb.angularVelocity);
		rb.AddRelativeTorque(0f, (0f - vector.y) * antiSpinTorque, 0f);
	}

	private void ApplyAirResistance()
	{
		rb.linearVelocity *= 1f - airResistance;
	}

	private void ApplyDistanceConstraint()
	{
		_ = knot.transform.position - base.transform.position;
		UnityEngine.Vector3 vector = grabPt.transform.position - knot.transform.position;
		UnityEngine.Vector3 normalized = vector.normalized;
		float magnitude = vector.magnitude;
		float num = stringLength * balloonScale;
		if (magnitude > num)
		{
			UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Dot(knotRb.linearVelocity, normalized) * normalized;
			float num2 = magnitude - num;
			float num3 = num2 / Time.fixedDeltaTime;
			if (vector2.magnitude < num3)
			{
				float b = num3 - vector2.magnitude;
				float num4 = Mathf.Clamp01(num2 / stringStretch);
				UnityEngine.Vector3 vector3 = Mathf.Lerp(0f, b, num4 * num4) * normalized * stringStrength;
				rb.AddForceAtPosition(vector3 * rb.mass, knot.transform.position, ForceMode.Impulse);
			}
		}
	}

	public void EnableDynamics(bool enable, bool collider, bool kinematic)
	{
		bool flag = !enableDynamics && enable;
		enableDynamics = enable;
		if ((bool)balloonCollider)
		{
			balloonCollider.enabled = collider;
		}
		if (rb != null)
		{
			rb.isKinematic = kinematic;
			if (!kinematic && flag)
			{
				rb.linearVelocity = UnityEngine.Vector3.zero;
				rb.angularVelocity = UnityEngine.Vector3.zero;
			}
		}
	}

	public void EnableDistanceConstraints(bool enable, float scale = 1f)
	{
		enableDistanceConstraints = enable;
		balloonScale = scale;
	}

	private void FixedUpdate()
	{
		if (enableDynamics && !rb.isKinematic)
		{
			ApplyBouyancyForce();
			if (antiSpinTorque > 0f)
			{
				ApplyAntiSpinForce();
			}
			ApplyUpRightForce();
			ApplyAirResistance();
			if (enableDistanceConstraints)
			{
				ApplyDistanceConstraint();
			}
			UnityEngine.Vector3 linearVelocity = rb.linearVelocity;
			float magnitude = linearVelocity.magnitude;
			rb.linearVelocity = linearVelocity.normalized * Mathf.Min(magnitude, maximumVelocity * balloonScale);
		}
	}

	void ITetheredObjectBehavior.DbgClear()
	{
		throw new NotImplementedException();
	}

	bool ITetheredObjectBehavior.IsEnabled()
	{
		return base.enabled;
	}

	void ITetheredObjectBehavior.TriggerEnter(Collider other, ref UnityEngine.Vector3 force, ref UnityEngine.Vector3 collisionPt, ref bool transferOwnership)
	{
		if (!other.gameObject.IsOnLayer(UnityLayer.GorillaHand) || !rb)
		{
			return;
		}
		transferOwnership = true;
		TransformFollow component = other.gameObject.GetComponent<TransformFollow>();
		if ((bool)component)
		{
			UnityEngine.Vector3 vector = (component.transform.position - component.prevPos) / Time.deltaTime;
			force = vector * bopSpeed;
			force = Mathf.Min(maximumVelocity, force.magnitude) * force.normalized * balloonScale;
			if (bopSpeedCap > 0f && force.IsLongerThan(bopSpeedCap))
			{
				force = force.normalized * bopSpeedCap;
			}
			collisionPt = other.ClosestPointOnBounds(base.transform.position);
			rb.AddForceAtPosition(force * rb.mass, collisionPt, ForceMode.Impulse);
			if (balloonBopSource != null)
			{
				balloonBopSource.GTPlay();
			}
			GorillaTriggerColliderHandIndicator component2 = other.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (component2 != null)
			{
				float amplitude = GorillaTagger.Instance.tapHapticStrength / 4f;
				float fixedDeltaTime = Time.fixedDeltaTime;
				GorillaTagger.Instance.StartVibration(component2.isLeftHand, amplitude, fixedDeltaTime);
			}
		}
	}

	public bool ReturnStep()
	{
		return true;
	}
}
public class BalloonHoldable : TransferrableObject, IFXContext
{
	private enum BalloonStates
	{
		Normal,
		Pop,
		Waiting,
		WaitForOwnershipTransfer,
		WaitForReDock,
		Refilling,
		Returning
	}

	private ITetheredObjectBehavior balloonDynamics;

	[SerializeField]
	private Renderer mesh;

	private LineRenderer lineRenderer;

	private Rigidbody rb;

	private NetPlayer originalOwner;

	public GameObject balloonPopFXPrefab;

	public Color balloonPopFXColor;

	private float timer;

	public float scaleTimerLength = 2f;

	public float poppedTimerLength = 2.5f;

	public float beginScale = 0.1f;

	public float bopSpeed = 1f;

	private UnityEngine.Vector3 fullyInflatedScale;

	public AudioSource balloonBopSource;

	public AudioSource balloonInflatSource;

	private UnityEngine.Vector3 forceAppliedAsRemote;

	private UnityEngine.Vector3 collisionPtAsRemote;

	private WaterVolume waterVolume;

	[DebugReadout]
	private BalloonStates balloonState;

	private float returnTimer;

	[SerializeField]
	private float maxDistanceFromOwner;

	public float lastOwnershipRequest;

	[SerializeField]
	private bool disableCollisionHandling;

	[SerializeField]
	private bool disableRelease;

	FXSystemSettings IFXContext.settings => ownerRig.fxSettings;

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		balloonDynamics = GetComponent<ITetheredObjectBehavior>();
		if (mesh == null)
		{
			mesh = GetComponent<Renderer>();
		}
		lineRenderer = GetComponent<LineRenderer>();
		itemState = (ItemStates)0;
		rb = GetComponent<Rigidbody>();
	}

	protected override void Start()
	{
		base.Start();
		EnableDynamics(enable: false, collider: false);
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		EnableDynamics(enable: false, collider: false);
		mesh.enabled = true;
		lineRenderer.enabled = false;
		if (NetworkSystem.Instance.InRoom)
		{
			if (worldShareableInstance != null)
			{
				return;
			}
			SpawnTransferableObjectViews();
		}
		if (InHand())
		{
			Grab();
		}
		else if (Dropped())
		{
			Release();
		}
	}

	public override void OnJoinedRoom()
	{
		base.OnJoinedRoom();
		if (!(worldShareableInstance != null))
		{
			SpawnTransferableObjectViews();
		}
	}

	private bool ShouldSimulate()
	{
		if (!Attached())
		{
			return balloonState == BalloonStates.Normal;
		}
		return false;
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		lineRenderer.enabled = false;
		EnableDynamics(enable: false, collider: false);
	}

	public override void PreDisable()
	{
		originalOwner = null;
		base.PreDisable();
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
		balloonState = BalloonStates.Normal;
		base.transform.localScale = UnityEngine.Vector3.one;
	}

	protected override void OnWorldShareableItemSpawn()
	{
		WorldShareableItem worldShareableItem = worldShareableInstance;
		if (worldShareableItem != null)
		{
			worldShareableItem.rpcCallBack = PopBalloonRemote;
			worldShareableItem.onOwnerChangeCb = OnOwnerChangeCb;
			worldShareableItem.EnableRemoteSync = ShouldSimulate();
		}
		originalOwner = worldShareableItem.target.owner;
	}

	public override void ResetToHome()
	{
		if (IsLocalObject() && worldShareableInstance != null && !worldShareableInstance.guard.isTrulyMine)
		{
			PhotonView photonView = PhotonView.Get(worldShareableInstance);
			if (photonView != null)
			{
				photonView.RPC("RPCWorldShareable", RpcTarget.Others);
			}
			worldShareableInstance.guard.RequestOwnershipImmediatelyWithGuaranteedAuthority();
		}
		PopBalloon();
		balloonState = BalloonStates.WaitForReDock;
		base.ResetToHome();
	}

	protected override void PlayDestroyedOrDisabledEffect()
	{
		base.PlayDestroyedOrDisabledEffect();
		PlayPopBalloonFX();
	}

	protected override void OnItemDestroyedOrDisabled()
	{
		PlayPopBalloonFX();
		if (balloonDynamics != null)
		{
			balloonDynamics.ReParent();
		}
		base.transform.parent = DefaultAnchor();
		base.OnItemDestroyedOrDisabled();
	}

	private void PlayPopBalloonFX()
	{
		FXSystem.PlayFXForRig(FXType.BalloonPop, this);
	}

	private void EnableDynamics(bool enable, bool collider, bool forceKinematicOn = false)
	{
		bool kinematic = false;
		if (forceKinematicOn)
		{
			kinematic = true;
		}
		else if (NetworkSystem.Instance.InRoom && worldShareableInstance != null)
		{
			PhotonView photonView = PhotonView.Get(worldShareableInstance.gameObject);
			if (photonView != null && !photonView.IsMine)
			{
				kinematic = true;
			}
		}
		if (balloonDynamics != null)
		{
			balloonDynamics.EnableDynamics(enable, collider, kinematic);
		}
	}

	private void PopBalloon()
	{
		PlayPopBalloonFX();
		EnableDynamics(enable: false, collider: false);
		mesh.enabled = false;
		lineRenderer.enabled = false;
		if (gripInteractor != null)
		{
			gripInteractor.gameObject.SetActive(value: false);
		}
		if ((object.Equals(originalOwner, PhotonNetwork.LocalPlayer) || !NetworkSystem.Instance.InRoom) && NetworkSystem.Instance.InRoom && worldShareableInstance != null && !worldShareableInstance.guard.isTrulyMine)
		{
			worldShareableInstance.guard.RequestOwnershipImmediatelyWithGuaranteedAuthority();
		}
		if (balloonDynamics != null)
		{
			balloonDynamics.ReParent();
			EnableDynamics(enable: false, collider: false);
		}
		if (IsMyItem())
		{
			if (InLeftHand())
			{
				EquipmentInteractor.instance.ReleaseLeftHand();
			}
			if (InRightHand())
			{
				EquipmentInteractor.instance.ReleaseRightHand();
			}
		}
	}

	public void PopBalloonRemote()
	{
		if (ShouldSimulate())
		{
			balloonState = BalloonStates.Pop;
		}
	}

	public void OnOwnerChangeCb(NetPlayer newOwner, NetPlayer prevOwner)
	{
	}

	public override void OnOwnershipTransferred(NetPlayer newOwner, NetPlayer prevOwner)
	{
		base.OnOwnershipTransferred(newOwner, prevOwner);
		if (object.Equals(prevOwner, NetworkSystem.Instance.LocalPlayer) && newOwner == null)
		{
			return;
		}
		if (!object.Equals(newOwner, NetworkSystem.Instance.LocalPlayer))
		{
			EnableDynamics(enable: false, collider: true, forceKinematicOn: true);
			return;
		}
		if (ShouldSimulate() && balloonDynamics != null)
		{
			balloonDynamics.EnableDynamics(enable: true, collider: true, kinematic: false);
		}
		if ((bool)rb)
		{
			if (!rb.isKinematic)
			{
				rb.AddForceAtPosition(forceAppliedAsRemote * rb.mass, collisionPtAsRemote, ForceMode.Impulse);
			}
			forceAppliedAsRemote = UnityEngine.Vector3.zero;
			collisionPtAsRemote = UnityEngine.Vector3.zero;
		}
	}

	private void OwnerPopBalloon()
	{
		if (worldShareableInstance != null)
		{
			PhotonView photonView = PhotonView.Get(worldShareableInstance);
			if (photonView != null)
			{
				photonView.RPC("RPCWorldShareable", RpcTarget.Others);
			}
		}
		balloonState = BalloonStates.Pop;
	}

	private void RunLocalPopSM()
	{
		switch (balloonState)
		{
		case BalloonStates.Pop:
			timer = Time.time;
			PopBalloon();
			balloonState = BalloonStates.WaitForOwnershipTransfer;
			lastOwnershipRequest = Time.time;
			break;
		case BalloonStates.WaitForOwnershipTransfer:
			if (!NetworkSystem.Instance.InRoom)
			{
				balloonState = BalloonStates.WaitForReDock;
				ReDock();
			}
			else if (worldShareableInstance != null)
			{
				WorldShareableItem worldShareableItem = worldShareableInstance;
				NetPlayer owner = worldShareableItem.Owner;
				if (worldShareableItem != null && owner == originalOwner)
				{
					balloonState = BalloonStates.WaitForReDock;
					ReDock();
				}
				if (IsLocalObject() && lastOwnershipRequest + 5f < Time.time)
				{
					worldShareableInstance.guard.RequestOwnershipImmediatelyWithGuaranteedAuthority();
					lastOwnershipRequest = Time.time;
				}
			}
			break;
		case BalloonStates.WaitForReDock:
			if (Attached())
			{
				fullyInflatedScale = base.transform.localScale;
				ReDock();
				balloonState = BalloonStates.Waiting;
			}
			break;
		case BalloonStates.Waiting:
			if (Time.time - timer >= poppedTimerLength)
			{
				timer = Time.time;
				mesh.enabled = true;
				balloonInflatSource.GTPlay();
				balloonState = BalloonStates.Refilling;
			}
			else
			{
				base.transform.localScale = new UnityEngine.Vector3(beginScale, beginScale, beginScale);
			}
			break;
		case BalloonStates.Refilling:
		{
			float num = Time.time - timer;
			if (num >= scaleTimerLength)
			{
				base.transform.localScale = fullyInflatedScale;
				balloonState = BalloonStates.Normal;
				if (gripInteractor != null)
				{
					gripInteractor.gameObject.SetActive(value: true);
				}
			}
			num = Mathf.Clamp01(num / scaleTimerLength);
			float num2 = Mathf.Lerp(beginScale, 1f, num);
			base.transform.localScale = fullyInflatedScale * num2;
			break;
		}
		case BalloonStates.Returning:
			if (balloonDynamics.ReturnStep())
			{
				balloonState = BalloonStates.Normal;
				ReDock();
			}
			break;
		case BalloonStates.Normal:
			break;
		}
	}

	protected override void OnStateChanged()
	{
		if (InHand())
		{
			Grab();
		}
		else if (Dropped())
		{
			Release();
		}
		else if (OnShoulder())
		{
			if (balloonDynamics != null && balloonDynamics.IsEnabled())
			{
				EnableDynamics(enable: false, collider: false);
			}
			lineRenderer.enabled = false;
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		if (Time.frameCount == enabledOnFrame)
		{
			OnStateChanged();
		}
		if (InHand() && detatchOnGrab)
		{
			float num = ((targetRig != null) ? targetRig.transform.localScale.x : 1f);
			base.transform.localScale = UnityEngine.Vector3.one * num;
		}
		if (Dropped() && balloonState == BalloonStates.Normal && maxDistanceFromOwner > 0f && (!NetworkSystem.Instance.InRoom || originalOwner.IsLocal) && (VRRig.LocalRig.transform.position - base.transform.position).IsLongerThan(maxDistanceFromOwner * base.transform.localScale.x))
		{
			OwnerPopBalloon();
		}
		if ((object)worldShareableInstance != null && !worldShareableInstance.guard.isMine)
		{
			worldShareableInstance.EnableRemoteSync = ShouldSimulate();
		}
		if (balloonState != BalloonStates.Normal)
		{
			RunLocalPopSM();
		}
	}

	protected override void LateUpdateReplicated()
	{
		base.LateUpdateReplicated();
	}

	private void Grab()
	{
		if (balloonDynamics != null)
		{
			if (detatchOnGrab)
			{
				float num = ((targetRig != null) ? targetRig.transform.localScale.x : 1f);
				base.transform.localScale = UnityEngine.Vector3.one * num;
				EnableDynamics(enable: true, collider: true);
				balloonDynamics.EnableDistanceConstraints(v: true, num);
				lineRenderer.enabled = true;
			}
			else
			{
				base.transform.localScale = UnityEngine.Vector3.one;
			}
		}
	}

	private void Release()
	{
		if (disableRelease)
		{
			balloonState = BalloonStates.Returning;
		}
		else if (balloonDynamics != null)
		{
			float num = ((targetRig != null) ? targetRig.transform.localScale.x : 1f);
			base.transform.localScale = UnityEngine.Vector3.one * num;
			EnableDynamics(enable: true, collider: true);
			balloonDynamics.EnableDistanceConstraints(v: false, num);
			lineRenderer.enabled = false;
		}
	}

	public void OnTriggerEnter(Collider other)
	{
		if (!ShouldSimulate())
		{
			return;
		}
		UnityEngine.Vector3 force = UnityEngine.Vector3.zero;
		UnityEngine.Vector3 collisionPt = UnityEngine.Vector3.zero;
		bool transferOwnership = false;
		if (balloonDynamics != null)
		{
			balloonDynamics.TriggerEnter(other, ref force, ref collisionPt, ref transferOwnership);
		}
		if (!NetworkSystem.Instance.InRoom || worldShareableInstance == null || !transferOwnership)
		{
			return;
		}
		RequestableOwnershipGuard component = PhotonView.Get(worldShareableInstance.gameObject).GetComponent<RequestableOwnershipGuard>();
		if (!component.isTrulyMine)
		{
			if (force.magnitude > forceAppliedAsRemote.magnitude)
			{
				forceAppliedAsRemote = force;
				collisionPtAsRemote = collisionPt;
			}
			component.RequestOwnershipImmediately(delegate
			{
			});
		}
	}

	public void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (!ShouldSimulate() || disableCollisionHandling)
		{
			return;
		}
		balloonBopSource.GTPlay();
		if (collision.gameObject.IsOnLayer(UnityLayer.GorillaThrowable))
		{
			if (!NetworkSystem.Instance.InRoom)
			{
				OwnerPopBalloon();
			}
			else if (!(worldShareableInstance == null) && PhotonView.Get(worldShareableInstance.gameObject).IsMine)
			{
				OwnerPopBalloon();
			}
		}
	}

	void IFXContext.OnPlayFX()
	{
		GameObject obj = ObjectPools.instance.Instantiate(balloonPopFXPrefab);
		obj.transform.SetPositionAndRotation(base.transform.position, base.transform.rotation);
		GorillaColorizableBase componentInChildren = obj.GetComponentInChildren<GorillaColorizableBase>();
		if (componentInChildren != null)
		{
			componentInChildren.SetColor(balloonPopFXColor);
		}
	}
}
