public class EquipmentInteractor : MonoBehaviour
{
	[OnEnterPlay_SetNull]
	public static volatile EquipmentInteractor instance;

	[OnEnterPlay_Set(false)]
	public static bool hasInstance;

	public IHoldableObject leftHandHeldEquipment;

	public IHoldableObject rightHandHeldEquipment;

	public BuilderPieceInteractor builderPieceInteractor;

	public GameObject rightHand;

	public GameObject leftHand;

	public UnityEngine.XR.InputDevice leftHandDevice;

	public UnityEngine.XR.InputDevice rightHandDevice;

	public List<InteractionPoint> overlapInteractionPointsLeft = new List<InteractionPoint>();

	public List<InteractionPoint> overlapInteractionPointsRight = new List<InteractionPoint>();

	public float grabRadius;

	public float grabThreshold = 0.7f;

	public float grabHysteresis = 0.05f;

	public bool wasLeftGrabPressed;

	public bool wasRightGrabPressed;

	public bool isLeftGrabbing;

	public bool isRightGrabbing;

	public bool justReleased;

	public bool justGrabbed;

	public bool disableLeftGrab;

	public bool disableRightGrab;

	public bool autoGrabLeft;

	public bool autoGrabRight;

	private float grabValue;

	private float tempValue;

	private DropZone tempZone;

	private bool iteratingInteractionPoints;

	private List<InteractionPoint> interactionPointsToRemove = new List<InteractionPoint>();

	[SerializeField]
	private GorillaHandClimber bodyClimber;

	[SerializeField]
	private GorillaHandClimber leftClimber;

	[SerializeField]
	private GorillaHandClimber rightClimber;

	public GorillaHandClimber BodyClimber => bodyClimber;

	public GorillaHandClimber LeftClimber => leftClimber;

	public GorillaHandClimber RightClimber => rightClimber;

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
			hasInstance = true;
		}
		else if (instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		autoGrabLeft = true;
		autoGrabRight = true;
	}

	private void OnDestroy()
	{
		if (instance == this)
		{
			hasInstance = false;
			instance = null;
		}
	}

	public void ReleaseRightHand()
	{
		if (rightHandHeldEquipment != null)
		{
			rightHandHeldEquipment.OnRelease(null, rightHand);
		}
		if (leftHandHeldEquipment != null)
		{
			leftHandHeldEquipment.OnRelease(null, rightHand);
		}
		autoGrabRight = true;
	}

	public void ReleaseLeftHand()
	{
		if (rightHandHeldEquipment != null)
		{
			rightHandHeldEquipment.OnRelease(null, leftHand);
		}
		if (leftHandHeldEquipment != null)
		{
			leftHandHeldEquipment.OnRelease(null, leftHand);
		}
		autoGrabLeft = true;
	}

	public void ForceStopClimbing()
	{
		bodyClimber.ForceStopClimbing();
		leftClimber.ForceStopClimbing();
		rightClimber.ForceStopClimbing();
	}

	public bool GetIsHolding(XRNode node)
	{
		if (node == XRNode.LeftHand)
		{
			return leftHandHeldEquipment != null;
		}
		return rightHandHeldEquipment != null;
	}

	public bool IsGrabDisabled(XRNode node)
	{
		if (node == XRNode.LeftHand)
		{
			return disableLeftGrab;
		}
		return disableRightGrab;
	}

	public void InteractionPointDisabled(InteractionPoint interactionPoint)
	{
		if (iteratingInteractionPoints)
		{
			interactionPointsToRemove.Add(interactionPoint);
			return;
		}
		if (overlapInteractionPointsLeft != null)
		{
			overlapInteractionPointsLeft.Remove(interactionPoint);
		}
		if (overlapInteractionPointsRight != null)
		{
			overlapInteractionPointsRight.Remove(interactionPoint);
		}
	}

	public bool CanGrabLeft()
	{
		if (!disableLeftGrab && leftHandHeldEquipment == null)
		{
			return builderPieceInteractor.heldPiece[0] == null;
		}
		return false;
	}

	public bool CanGrabRight()
	{
		if (!disableRightGrab && rightHandHeldEquipment == null)
		{
			return builderPieceInteractor.heldPiece[1] == null;
		}
		return false;
	}

	private void LateUpdate()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			leftClimber.CheckHandClimber();
			rightClimber.CheckHandClimber();
			CheckInputValue(isLeftHand: true);
			isLeftGrabbing = (wasLeftGrabPressed && grabValue > grabThreshold - grabHysteresis) || (!wasLeftGrabPressed && grabValue > grabThreshold + grabHysteresis);
			if ((bool)leftClimber && leftClimber.isClimbingOrGrabbing)
			{
				isLeftGrabbing = false;
			}
			CheckInputValue(isLeftHand: false);
			isRightGrabbing = (wasRightGrabPressed && grabValue > grabThreshold - grabHysteresis) || (!wasRightGrabPressed && grabValue > grabThreshold + grabHysteresis);
			if ((bool)rightClimber && rightClimber.isClimbingOrGrabbing)
			{
				isRightGrabbing = false;
			}
			BuilderPiece builderPiece = null;
			BuilderPiece builderPiece2 = null;
			builderPiece = builderPieceInteractor.heldPiece[0];
			builderPiece2 = builderPieceInteractor.heldPiece[1];
			FireHandInteractions(leftHand, isLeftHand: true, builderPiece);
			FireHandInteractions(rightHand, isLeftHand: false, builderPiece2);
			if (!isRightGrabbing && wasRightGrabPressed)
			{
				ReleaseRightHand();
			}
			if (!isLeftGrabbing && wasLeftGrabPressed)
			{
				ReleaseLeftHand();
			}
			builderPieceInteractor.OnLateUpdate();
			if (GameBallPlayerLocal.instance != null)
			{
				GameBallPlayerLocal.instance.OnUpdateInteract();
			}
			if (GamePlayerLocal.instance != null)
			{
				GamePlayerLocal.instance.OnUpdateInteract();
			}
			wasLeftGrabPressed = isLeftGrabbing;
			wasRightGrabPressed = isRightGrabbing;
		}
	}

	private void FireHandInteractions(GameObject interactingHand, bool isLeftHand, BuilderPiece pieceInHand)
	{
		if (isLeftHand)
		{
			justGrabbed = (isLeftGrabbing && !wasLeftGrabPressed) || (isLeftGrabbing && autoGrabLeft);
			justReleased = leftHandHeldEquipment != null && !isLeftGrabbing && wasLeftGrabPressed;
		}
		else
		{
			justGrabbed = (isRightGrabbing && !wasRightGrabPressed) || (isRightGrabbing && autoGrabRight);
			justReleased = rightHandHeldEquipment != null && !isRightGrabbing && wasRightGrabPressed;
		}
		List<InteractionPoint> obj = (isLeftHand ? overlapInteractionPointsLeft : overlapInteractionPointsRight);
		bool num = (isLeftHand ? (leftHandHeldEquipment != null) : (rightHandHeldEquipment != null));
		bool flag = pieceInHand != null;
		bool flag2 = (isLeftHand ? disableLeftGrab : disableRightGrab);
		bool flag3 = !num && !flag && !flag2;
		iteratingInteractionPoints = true;
		foreach (InteractionPoint item in obj)
		{
			if (flag3 && item != null)
			{
				if (justGrabbed)
				{
					item.Holdable.OnGrab(item, interactingHand);
				}
				else
				{
					item.Holdable.OnHover(item, interactingHand);
				}
			}
			if (!justReleased)
			{
				continue;
			}
			tempZone = item.GetComponent<DropZone>();
			if (!(tempZone != null))
			{
				continue;
			}
			if (interactingHand == leftHand)
			{
				if (leftHandHeldEquipment != null)
				{
					leftHandHeldEquipment.OnRelease(tempZone, interactingHand);
				}
			}
			else if (rightHandHeldEquipment != null)
			{
				rightHandHeldEquipment.OnRelease(tempZone, interactingHand);
			}
		}
		iteratingInteractionPoints = false;
		foreach (InteractionPoint item2 in interactionPointsToRemove)
		{
			if (overlapInteractionPointsLeft != null)
			{
				overlapInteractionPointsLeft.Remove(item2);
			}
			if (overlapInteractionPointsRight != null)
			{
				overlapInteractionPointsRight.Remove(item2);
			}
		}
		interactionPointsToRemove.Clear();
	}

	public void UpdateHandEquipment(IHoldableObject newEquipment, bool forLeftHand)
	{
		if (forLeftHand)
		{
			if (newEquipment != null && newEquipment == rightHandHeldEquipment && !newEquipment.TwoHanded)
			{
				rightHandHeldEquipment = null;
			}
			if (leftHandHeldEquipment != null)
			{
				leftHandHeldEquipment.DropItemCleanup();
			}
			leftHandHeldEquipment = newEquipment;
			autoGrabLeft = false;
		}
		else
		{
			if (newEquipment != null && newEquipment == leftHandHeldEquipment && !newEquipment.TwoHanded)
			{
				leftHandHeldEquipment = null;
			}
			if (rightHandHeldEquipment != null)
			{
				rightHandHeldEquipment.DropItemCleanup();
			}
			rightHandHeldEquipment = newEquipment;
			autoGrabRight = false;
		}
	}

	public void CheckInputValue(bool isLeftHand)
	{
		if (isLeftHand)
		{
			grabValue = ControllerInputPoller.GripFloat(XRNode.LeftHand);
			tempValue = ControllerInputPoller.TriggerFloat(XRNode.LeftHand);
		}
		else
		{
			grabValue = ControllerInputPoller.GripFloat(XRNode.RightHand);
			tempValue = ControllerInputPoller.TriggerFloat(XRNode.RightHand);
		}
		grabValue = Mathf.Max(grabValue, tempValue);
	}

	public void ForceDropEquipment(IHoldableObject equipment)
	{
		if (rightHandHeldEquipment == equipment)
		{
			rightHandHeldEquipment = null;
		}
		if (leftHandHeldEquipment == equipment)
		{
			leftHandHeldEquipment = null;
		}
	}

	public void ForceDropAnyEquipment()
	{
		rightHandHeldEquipment = null;
		leftHandHeldEquipment = null;
	}

	public void ForceDropManipulatableObject(HoldableObject manipulatableObject)
	{
		if ((HoldableObject)rightHandHeldEquipment == manipulatableObject)
		{
			rightHandHeldEquipment.OnRelease(null, rightHand);
			rightHandHeldEquipment = null;
			autoGrabRight = false;
		}
		if ((HoldableObject)leftHandHeldEquipment == manipulatableObject)
		{
			leftHandHeldEquipment.OnRelease(null, leftHand);
			leftHandHeldEquipment = null;
			autoGrabLeft = false;
		}
	}
}
[NetworkBehaviourWeaved(1)]
public class HitTargetNetworkState : NetworkComponent
{
	[SerializeField]
	private WatchableIntSO networkedScore;

	[SerializeField]
	private int hitCooldownTime = 1;

	[SerializeField]
	private bool testPress;

	[SerializeField]
	private AudioClip[] audioClips;

	[SerializeField]
	private bool scoreIsDistance;

	[SerializeField]
	private float resetAfterDuration;

	private AudioSource audioPlayer;

	private float nextHittableTimestamp;

	private float resetAtTimestamp;

	private Coroutine resetCoroutine;

	[WeaverGenerated]
	[SerializeField]
	[DefaultForProperty("Data", 0, 1)]
	[DrawIf("IsEditorWritable", true, CompareOperator.Equal, DrawIfMode.ReadOnly)]
	private int _Data;

	[Networked]
	[NetworkedWeaved(0, 1)]
	public unsafe int Data
	{
		get
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing HitTargetNetworkState.Data. Networked properties can only be accessed when Spawned() has been called.");
			}
			return *(int*)((byte*)((NetworkBehaviour)this).Ptr + 0);
		}
		set
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing HitTargetNetworkState.Data. Networked properties can only be accessed when Spawned() has been called.");
			}
			*(int*)((byte*)((NetworkBehaviour)this).Ptr + 0) = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		audioPlayer = GetComponent<AudioSource>();
		SlingshotProjectileHitNotifier component = GetComponent<SlingshotProjectileHitNotifier>();
		if (component != null)
		{
			component.OnProjectileHit += ProjectileHitReciever;
			component.OnProjectileCollisionStay += ProjectileHitReciever;
		}
		else
		{
			UnityEngine.Debug.LogError("Needs SlingshotProjectileHitNotifier added to this GameObject to increment score");
		}
	}

	protected override void Start()
	{
		base.Start();
		RoomSystem.LeftRoomEvent += new Action(OnLeftRoom);
	}

	private void SetInitialState()
	{
		networkedScore.Value = 0;
		nextHittableTimestamp = 0f;
		audioPlayer.GTStop();
	}

	public void OnLeftRoom()
	{
		SetInitialState();
	}

	internal override void OnEnable()
	{
		NetworkBehaviourUtils.InternalOnEnable(this);
		base.OnEnable();
		if (UnityEngine.Application.isEditor)
		{
			StartCoroutine(TestPressCheck());
		}
		SetInitialState();
	}

	private IEnumerator TestPressCheck()
	{
		while (true)
		{
			if (testPress)
			{
				testPress = false;
				TargetHit(UnityEngine.Vector3.zero, UnityEngine.Vector3.one);
			}
			yield return new WaitForSeconds(1f);
		}
	}

	private void ProjectileHitReciever(SlingshotProjectile projectile, UnityEngine.Collision collision)
	{
		TargetHit(projectile.launchPosition, collision.contacts[0].point);
	}

	public void TargetHit(UnityEngine.Vector3 launchPoint, UnityEngine.Vector3 impactPoint)
	{
		if (!NetworkSystem.Instance.IsMasterClient || Time.time <= nextHittableTimestamp)
		{
			return;
		}
		int value = networkedScore.Value;
		if (scoreIsDistance)
		{
			int num = Mathf.RoundToInt((launchPoint - impactPoint).magnitude * 3.28f);
			if (num <= value)
			{
				return;
			}
			value = num;
		}
		else
		{
			value++;
			if (value >= 1000)
			{
				value = 0;
			}
		}
		if (resetAfterDuration > 0f && resetCoroutine == null)
		{
			resetAtTimestamp = Time.time + resetAfterDuration;
			resetCoroutine = StartCoroutine(ResetCo());
		}
		PlayAudio(networkedScore.Value, value);
		networkedScore.Value = value;
		nextHittableTimestamp = Time.time + (float)hitCooldownTime;
	}

	public override void WriteDataFusion()
	{
		Data = networkedScore.Value;
	}

	public override void ReadDataFusion()
	{
		int data = Data;
		if (data != networkedScore.Value)
		{
			PlayAudio(networkedScore.Value, data);
		}
		networkedScore.Value = data;
	}

	protected override void WriteDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (info.Sender.IsMasterClient)
		{
			stream.SendNext(networkedScore.Value);
		}
	}

	protected override void ReadDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (info.Sender.IsMasterClient)
		{
			int num = (int)stream.ReceiveNext();
			if (num != networkedScore.Value)
			{
				PlayAudio(networkedScore.Value, num);
			}
			networkedScore.Value = num;
		}
	}

	public void PlayAudio(int oldScore, int newScore)
	{
		if (oldScore > newScore && !scoreIsDistance)
		{
			audioPlayer.GTPlayOneShot(audioClips[1]);
		}
		else
		{
			audioPlayer.GTPlayOneShot(audioClips[0]);
		}
	}

	private IEnumerator ResetCo()
	{
		while (Time.time < resetAtTimestamp)
		{
			yield return new WaitForSeconds(resetAtTimestamp - Time.time);
		}
		networkedScore.Value = 0;
		PlayAudio(networkedScore.Value, 0);
		resetCoroutine = null;
	}

	[WeaverGenerated]
	public override void CopyBackingFieldsToState(bool P_0)
	{
		base.CopyBackingFieldsToState(P_0);
		Data = _Data;
	}

	[WeaverGenerated]
	public override void CopyStateToBackingFields()
	{
		base.CopyStateToBackingFields();
		_Data = Data;
	}
}
public class HitTargetScoreDisplay : MonoBehaviour
{
	[SerializeField]
	private WatchableIntSO networkedScore;

	private int currentScore;

	private int tensOld;

	private int hundredsOld;

	private float rotateTimeTotal;

	private MaterialPropertyBlock matPropBlock;

	private readonly UnityEngine.Vector4[] numberSheet = new UnityEngine.Vector4[10]
	{
		new UnityEngine.Vector4(1f, 1f, 0.8f, -0.5f),
		new UnityEngine.Vector4(1f, 1f, 0f, 0f),
		new UnityEngine.Vector4(1f, 1f, 0.2f, 0f),
		new UnityEngine.Vector4(1f, 1f, 0.4f, 0f),
		new UnityEngine.Vector4(1f, 1f, 0.6f, 0f),
		new UnityEngine.Vector4(1f, 1f, 0.8f, 0f),
		new UnityEngine.Vector4(1f, 1f, 0f, -0.5f),
		new UnityEngine.Vector4(1f, 1f, 0.2f, -0.5f),
		new UnityEngine.Vector4(1f, 1f, 0.4f, -0.5f),
		new UnityEngine.Vector4(1f, 1f, 0.6f, -0.5f)
	};

	public int rotateSpeed = 180;

	public Transform singlesCard;

	public Transform tensCard;

	public Transform hundredsCard;

	public Renderer singlesRend;

	public Renderer tensRend;

	public Renderer hundredsRend;

	private Coroutine currentRotationCoroutine;

	protected void Awake()
	{
		rotateTimeTotal = 180f / (float)rotateSpeed;
		matPropBlock = new MaterialPropertyBlock();
		networkedScore.AddCallback(OnScoreChanged, shouldCallbackNow: true);
		ResetRotation();
		tensOld = 0;
		hundredsOld = 0;
		matPropBlock.SetVector(ShaderProps._BaseMap_ST, numberSheet[0]);
		singlesRend.SetPropertyBlock(matPropBlock);
		tensRend.SetPropertyBlock(matPropBlock);
		hundredsRend.SetPropertyBlock(matPropBlock);
	}

	private void OnDestroy()
	{
		networkedScore.RemoveCallback(OnScoreChanged);
	}

	private void ResetRotation()
	{
		UnityEngine.Quaternion rotation = base.transform.rotation;
		singlesCard.rotation = rotation;
		tensCard.rotation = rotation;
		hundredsCard.rotation = rotation;
	}

	private IEnumerator RotatingCo()
	{
		float timeElapsedSinceHit = 0f;
		int singlesPlace = currentScore % 10;
		int tensPlace = currentScore / 10 % 10;
		bool tensChange = tensOld != tensPlace;
		tensOld = tensPlace;
		int hundredsPlace = currentScore / 100 % 10;
		bool hundredsChange = hundredsOld != hundredsPlace;
		hundredsOld = hundredsPlace;
		bool digitsChange = true;
		for (; !(timeElapsedSinceHit >= rotateTimeTotal); timeElapsedSinceHit += Time.deltaTime)
		{
			singlesCard.Rotate((float)rotateSpeed * Time.deltaTime, 0f, 0f, Space.Self);
			UnityEngine.Vector3 localEulerAngles = singlesCard.localEulerAngles;
			localEulerAngles.x = Mathf.Clamp(localEulerAngles.x, 0f, 180f);
			singlesCard.localEulerAngles = localEulerAngles;
			if (tensChange)
			{
				tensCard.Rotate((float)rotateSpeed * Time.deltaTime, 0f, 0f, Space.Self);
				UnityEngine.Vector3 localEulerAngles2 = tensCard.localEulerAngles;
				localEulerAngles2.x = Mathf.Clamp(localEulerAngles2.x, 0f, 180f);
				tensCard.localEulerAngles = localEulerAngles2;
			}
			if (hundredsChange)
			{
				hundredsCard.Rotate((float)rotateSpeed * Time.deltaTime, 0f, 0f, Space.Self);
				UnityEngine.Vector3 localEulerAngles3 = hundredsCard.localEulerAngles;
				localEulerAngles3.x = Mathf.Clamp(localEulerAngles3.x, 0f, 180f);
				hundredsCard.localEulerAngles = localEulerAngles3;
			}
			if (digitsChange && timeElapsedSinceHit >= rotateTimeTotal / 2f)
			{
				matPropBlock.SetVector(ShaderProps._BaseMap_ST, numberSheet[singlesPlace]);
				singlesRend.SetPropertyBlock(matPropBlock);
				if (tensChange)
				{
					matPropBlock.SetVector(ShaderProps._BaseMap_ST, numberSheet[tensPlace]);
					tensRend.SetPropertyBlock(matPropBlock);
				}
				if (hundredsChange)
				{
					matPropBlock.SetVector(ShaderProps._BaseMap_ST, numberSheet[hundredsPlace]);
					hundredsRend.SetPropertyBlock(matPropBlock);
				}
				digitsChange = false;
			}
			yield return null;
		}
		ResetRotation();
	}

	private void OnScoreChanged(int newScore)
	{
		if (newScore != currentScore)
		{
			if (currentRotationCoroutine != null)
			{
				StopCoroutine(currentRotationCoroutine);
			}
			currentScore = newScore;
			if (base.gameObject.activeInHierarchy)
			{
				currentRotationCoroutine = StartCoroutine(RotatingCo());
			}
		}
	}
}
public class InteractionPoint : MonoBehaviour, ISpawnable, IBuildValidation
{
	[SerializeField]
	[FormerlySerializedAs("parentTransferrableObject")]
	public GameObject parentHoldableObject;

	private IHoldableObject parentHoldable;

	[SerializeField]
	private bool isNonSpawnedObject;

	[SerializeField]
	private float interactionRadius;

	public Collider myCollider;

	public EquipmentInteractor interactor;

	public bool wasInLeft;

	public bool wasInRight;

	public bool forLocalPlayer;

	[field: SerializeField]
	public bool ignoreLeftHand { get; private set; }

	[field: SerializeField]
	public bool ignoreRightHand { get; private set; }

	public IHoldableObject Holdable => parentHoldable;

	public bool IsSpawned { get; set; }

	public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

	public void OnSpawn(VRRig rig)
	{
		if (!IsSpawned)
		{
			IsSpawned = true;
		}
		interactor = EquipmentInteractor.instance;
		myCollider = GetComponent<Collider>();
		if (parentHoldableObject != null)
		{
			parentHoldable = parentHoldableObject.GetComponent<IHoldableObject>();
		}
		else
		{
			parentHoldable = GetComponentInParent<IHoldableObject>(includeInactive: true);
			parentHoldableObject = parentHoldable.gameObject;
		}
		if (parentHoldable == null)
		{
			if (parentHoldableObject == null)
			{
				UnityEngine.Debug.LogError("InteractionPoint: Disabling because expected field `parentHoldableObject` is null. Path=" + base.transform.GetPathQ());
				base.enabled = false;
				return;
			}
			UnityEngine.Debug.LogError("InteractionPoint: Disabling because `parentHoldableObject` does not have a IHoldableObject component. Path=" + base.transform.GetPathQ());
		}
		TransferrableObject transferrableObject = parentHoldable as TransferrableObject;
		forLocalPlayer = transferrableObject == null || transferrableObject.IsLocalObject() || transferrableObject.isSceneObject || transferrableObject.canDrop;
	}

	void ISpawnable.OnDespawn()
	{
	}

	private void Awake()
	{
		if (isNonSpawnedObject)
		{
			OnSpawn(null);
		}
	}

	private void OnEnable()
	{
		wasInLeft = false;
		wasInRight = false;
	}

	public void OnDisable()
	{
		if (forLocalPlayer && !(interactor == null))
		{
			interactor.InteractionPointDisabled(this);
		}
	}

	protected void LateUpdate()
	{
		if (!IsSpawned)
		{
			return;
		}
		if (!forLocalPlayer)
		{
			base.enabled = false;
			if (myCollider.IsNotNull())
			{
				myCollider.enabled = false;
			}
		}
		else if (interactor == null)
		{
			interactor = EquipmentInteractor.instance;
		}
		else
		{
			if (!(interactionRadius > 0f) && !(myCollider != null))
			{
				return;
			}
			if (!ignoreLeftHand && OverlapCheck(interactor.leftHand.transform.position) != wasInLeft)
			{
				if (!wasInLeft && !interactor.overlapInteractionPointsLeft.Contains(this))
				{
					interactor.overlapInteractionPointsLeft.Add(this);
					wasInLeft = true;
				}
				else if (wasInLeft && interactor.overlapInteractionPointsLeft.Contains(this))
				{
					interactor.overlapInteractionPointsLeft.Remove(this);
					wasInLeft = false;
				}
			}
			if (!ignoreRightHand && OverlapCheck(interactor.rightHand.transform.position) != wasInRight)
			{
				if (!wasInRight && !interactor.overlapInteractionPointsRight.Contains(this))
				{
					interactor.overlapInteractionPointsRight.Add(this);
					wasInRight = true;
				}
				else if (wasInRight && interactor.overlapInteractionPointsRight.Contains(this))
				{
					interactor.overlapInteractionPointsRight.Remove(this);
					wasInRight = false;
				}
			}
		}
	}

	public bool OverlapCheck(UnityEngine.Vector3 point)
	{
		if (interactionRadius > 0f)
		{
			return (base.transform.position - point).IsShorterThan(interactionRadius * base.transform.lossyScale);
		}
		if (myCollider != null)
		{
			return myCollider.bounds.Contains(point);
		}
		return false;
	}

	public bool BuildValidationCheck()
	{
		return true;
	}
}
