public class TransferrableObjectHoldablePart : HoldableObject, ITickSystemTick
{
	[SerializeField]
	protected TransferrableObject transferrableParentObject;

	[SerializeField]
	private TransferrableObject.ItemStates heldBit = TransferrableObject.ItemStates.Part0Held;

	private bool isHeld;

	protected bool isHeldLeftHand;

	public UnityEvent onGrab;

	public UnityEvent onRelease;

	public UnityEvent onDrop;

	public bool TickRunning { get; set; }

	private void OnEnable()
	{
		TickSystem<object>.AddTickCallback(this);
	}

	private void OnDisable()
	{
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void Tick()
	{
		VRRig rig;
		if (!transferrableParentObject.IsLocalObject())
		{
			rig = transferrableParentObject.myOnlineRig;
			isHeld = (transferrableParentObject.itemState & heldBit) != 0;
			TransferrableObject.PositionState currentState = transferrableParentObject.currentState;
			if (currentState == TransferrableObject.PositionState.OnRightArm || currentState == TransferrableObject.PositionState.InRightHand)
			{
				isHeldLeftHand = isHeld;
			}
			else
			{
				isHeldLeftHand = false;
			}
		}
		else
		{
			rig = VRRig.LocalRig;
		}
		if (isHeld)
		{
			if (transferrableParentObject.InHand())
			{
				UpdateHeld(rig, isHeldLeftHand);
			}
			else if (transferrableParentObject.IsLocalObject())
			{
				OnRelease(null, isHeldLeftHand ? EquipmentInteractor.instance.leftHand : EquipmentInteractor.instance.rightHand);
			}
		}
	}

	protected virtual void UpdateHeld(VRRig rig, bool isHeldLeftHand)
	{
	}

	public override void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
	{
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		if (!transferrableParentObject.ownerRig || transferrableParentObject.ownerRig.isLocal)
		{
			isHeld = true;
			isHeldLeftHand = grabbingHand == EquipmentInteractor.instance.leftHand;
			transferrableParentObject.itemState |= heldBit;
			EquipmentInteractor.instance.UpdateHandEquipment(this, isHeldLeftHand);
			onGrab?.Invoke();
		}
	}

	public override void DropItemCleanup()
	{
		isHeld = false;
		isHeldLeftHand = false;
		transferrableParentObject.itemState &= ~heldBit;
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (EquipmentInteractor.instance.rightHandHeldEquipment == this && releasingHand != EquipmentInteractor.instance.rightHand)
		{
			return false;
		}
		if (EquipmentInteractor.instance.leftHandHeldEquipment == this && releasingHand != EquipmentInteractor.instance.leftHand)
		{
			return false;
		}
		EquipmentInteractor.instance.UpdateHandEquipment(null, isHeldLeftHand);
		isHeld = false;
		isHeldLeftHand = false;
		transferrableParentObject.itemState &= ~heldBit;
		onRelease?.Invoke();
		return true;
	}
}
public class TransferrableObjectHoldablePart_Crank : TransferrableObjectHoldablePart
{
	[Serializable]
	private struct CrankThreshold
	{
		public float angleThreshold;

		public UnityEvent onReached;

		[HideInInspector]
		public float currentAngle;

		public void OnCranked(float deltaAngle)
		{
			currentAngle += deltaAngle;
			if (Mathf.Abs(currentAngle) > angleThreshold)
			{
				currentAngle = 0f;
				onReached.Invoke();
			}
		}
	}

	[SerializeField]
	private float crankHandleX;

	[SerializeField]
	private float crankHandleY;

	[SerializeField]
	private float crankHandleMinZ;

	[SerializeField]
	private float crankHandleMaxZ;

	[SerializeField]
	private float maxHandSnapDistance;

	private float crankAngleOffset;

	private float crankRadius;

	[SerializeField]
	private Transform rotatingPart;

	private float lastAngle;

	private UnityEngine.Quaternion baseLocalAngle;

	private UnityEngine.Quaternion baseLocalAngleInverse;

	private Action<float> onCrankedCallback;

	[SerializeField]
	private CrankThreshold[] thresholds;

	public void SetOnCrankedCallback(Action<float> onCrankedCallback)
	{
		this.onCrankedCallback = onCrankedCallback;
	}

	private void Awake()
	{
		if (rotatingPart == null)
		{
			rotatingPart = base.transform;
		}
		UnityEngine.Vector3 vector = rotatingPart.parent.InverseTransformPoint(rotatingPart.TransformPoint(UnityEngine.Vector3.right));
		lastAngle = Mathf.Atan2(vector.y, vector.x);
		baseLocalAngle = rotatingPart.localRotation;
		baseLocalAngleInverse = UnityEngine.Quaternion.Inverse(baseLocalAngle);
		crankRadius = new UnityEngine.Vector2(crankHandleX, crankHandleY).magnitude;
		crankAngleOffset = Mathf.Atan2(crankHandleY, crankHandleX) * 57.29578f;
		if (crankHandleMaxZ < crankHandleMinZ)
		{
			float num = crankHandleMaxZ;
			float num2 = crankHandleMinZ;
			crankHandleMinZ = num;
			crankHandleMaxZ = num2;
		}
	}

	protected override void UpdateHeld(VRRig rig, bool isHeldLeftHand)
	{
		UnityEngine.Vector3 vector2;
		if (rig.isOfflineVRRig)
		{
			Transform controllerTransform = GTPlayer.Instance.GetControllerTransform(isHeldLeftHand);
			UnityEngine.Vector3 v = rotatingPart.InverseTransformPoint(controllerTransform.position);
			UnityEngine.Vector3 position = (v.xy().normalized * crankRadius).WithZ(Mathf.Clamp(v.z, crankHandleMinZ, crankHandleMaxZ));
			UnityEngine.Vector3 vector = rotatingPart.TransformPoint(position);
			if (maxHandSnapDistance > 0f && (controllerTransform.position - vector).IsLongerThan(maxHandSnapDistance))
			{
				OnRelease(null, isHeldLeftHand ? EquipmentInteractor.instance.leftHand : EquipmentInteractor.instance.rightHand);
				return;
			}
			controllerTransform.position = vector;
			vector2 = controllerTransform.position;
		}
		else
		{
			VRMap vRMap = (isHeldLeftHand ? rig.leftHand : rig.rightHand);
			vector2 = vRMap.GetExtrapolatedControllerPosition();
			vector2 -= vRMap.rigTarget.rotation * GTPlayer.Instance.GetHandOffset(isHeldLeftHand) * rig.scaleFactor;
		}
		UnityEngine.Vector3 vector3 = baseLocalAngleInverse * UnityEngine.Quaternion.Inverse(rotatingPart.parent.rotation) * (vector2 - rotatingPart.position);
		float num = Mathf.Atan2(vector3.y, vector3.x) * 57.29578f;
		float num2 = Mathf.DeltaAngle(lastAngle, num);
		lastAngle = num;
		if (num2 != 0f)
		{
			if (onCrankedCallback != null)
			{
				onCrankedCallback(num2);
			}
			for (int i = 0; i < thresholds.Length; i++)
			{
				thresholds[i].OnCranked(num2);
			}
		}
		rotatingPart.localRotation = baseLocalAngle * UnityEngine.Quaternion.AngleAxis(num - crankAngleOffset, UnityEngine.Vector3.forward);
	}

	private void OnDrawGizmosSelected()
	{
		Transform transform = ((rotatingPart != null) ? rotatingPart : base.transform);
		Gizmos.color = Color.green;
		Gizmos.DrawLine(transform.TransformPoint(new UnityEngine.Vector3(crankHandleX, crankHandleY, crankHandleMinZ)), transform.TransformPoint(new UnityEngine.Vector3(crankHandleX, crankHandleY, crankHandleMaxZ)));
	}
}
public class TransferrableObjectHoldablePart_Slide : TransferrableObjectHoldablePart
{
	[SerializeField]
	private float _maxHandSnapDistance;

	[SerializeField]
	private SnapXformToLine _snapToLine;

	private const int LEFT = 0;

	private const int RIGHT = 1;

	protected override void UpdateHeld(VRRig rig, bool isHeldLeftHand)
	{
		int num = ((!isHeldLeftHand) ? 1 : 0);
		GTPlayer instance = GTPlayer.Instance;
		if (rig.isOfflineVRRig)
		{
			Transform controllerTransform = instance.GetControllerTransform(num == 0);
			UnityEngine.Vector3 position = controllerTransform.position;
			UnityEngine.Vector3 snappedPoint = _snapToLine.GetSnappedPoint(position);
			if (_maxHandSnapDistance > 0f && (controllerTransform.position - snappedPoint).IsLongerThan(_maxHandSnapDistance))
			{
				OnRelease(null, isHeldLeftHand ? EquipmentInteractor.instance.leftHand : EquipmentInteractor.instance.rightHand);
				return;
			}
			controllerTransform.position = snappedPoint;
			_snapToLine.target.position = snappedPoint;
		}
		else
		{
			UnityEngine.Vector3 vector = instance.GetHandOffset(isHeldLeftHand) * rig.scaleFactor;
			VRMap vRMap = (isHeldLeftHand ? rig.leftHand : rig.rightHand);
			_snapToLine.target.position = vRMap.GetExtrapolatedControllerPosition() - vector;
		}
	}
}
public class WorldTargetItem
{
	public readonly NetPlayer owner;

	public readonly int itemIdx;

	public readonly Transform targetObject;

	public readonly TransferrableObject transferrableObject;

	public bool IsValid()
	{
		if (itemIdx != -1)
		{
			return owner != null;
		}
		return false;
	}

	[CanBeNull]
	public static WorldTargetItem GenerateTargetFromPlayerAndID(NetPlayer owner, int itemIdx)
	{
		VRRig vRRig = GorillaGameManager.StaticFindRigForPlayer(owner);
		if (vRRig == null)
		{
			UnityEngine.Debug.LogError("Tried to setup a sharable object but the target rig is null...");
			return null;
		}
		Transform component = vRRig.myBodyDockPositions.TransferrableItem(itemIdx).gameObject.GetComponent<Transform>();
		return new WorldTargetItem(owner, itemIdx, component);
	}

	public static WorldTargetItem GenerateTargetFromWorldSharableItem(NetPlayer owner, int itemIdx, Transform transform)
	{
		return new WorldTargetItem(owner, itemIdx, transform);
	}

	private WorldTargetItem(NetPlayer owner, int itemIdx, Transform transform)
	{
		this.owner = owner;
		this.itemIdx = itemIdx;
		targetObject = transform;
		transferrableObject = transform.GetComponent<TransferrableObject>();
	}

	public override string ToString()
	{
		return $"Id: {itemIdx} ({owner})";
	}
}
