public class RigDuplicationZone : MonoBehaviour
{
	public delegate void RigDuplicationZoneAction(RigDuplicationZone z);

	private RigDuplicationZone otherZone;

	[SerializeField]
	private string id;

	private bool playerInZone;

	private UnityEngine.Vector3 offsetToOtherZone;

	public string Id => id;

	public bool IsApplyingDisplacement => otherZone.playerInZone;

	public static event RigDuplicationZoneAction OnEnabled;

	private void OnEnable()
	{
		OnEnabled += RigDuplicationZone_OnEnabled;
		if (RigDuplicationZone.OnEnabled != null)
		{
			RigDuplicationZone.OnEnabled(this);
		}
	}

	private void OnDisable()
	{
		OnEnabled -= RigDuplicationZone_OnEnabled;
	}

	private void RigDuplicationZone_OnEnabled(RigDuplicationZone z)
	{
		if (!(z == this) && !(z.id != id))
		{
			SetOtherZone(z);
			z.SetOtherZone(this);
		}
	}

	private void SetOtherZone(RigDuplicationZone z)
	{
		otherZone = z;
		offsetToOtherZone = z.transform.position - base.transform.position;
	}

	private void OnTriggerEnter(Collider other)
	{
		VRRig component = other.GetComponent<VRRig>();
		if (!(component == null))
		{
			if (component.isLocal)
			{
				playerInZone = true;
			}
			else
			{
				component.SetDuplicationZone(this);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		VRRig component = other.GetComponent<VRRig>();
		if (!(component == null))
		{
			if (component.isLocal)
			{
				playerInZone = false;
			}
			else
			{
				component.ClearDuplicationZone(this);
			}
		}
	}

	public UnityEngine.Vector3 GetVisualOffsetForRigs(UnityEngine.Vector3 cachedOffset)
	{
		if (otherZone == null)
		{
			UnityEngine.Debug.LogError("RigDuplicationZone doesn't have an other zone!", base.gameObject);
			return cachedOffset;
		}
		if (!otherZone.playerInZone)
		{
			return cachedOffset;
		}
		return offsetToOtherZone + cachedOffset;
	}
}
public class RigEventGate : MonoBehaviour, IBuildValidation
{
	private enum Mode
	{
		RELATIVE,
		ABSOLUTE
	}

	private List<RigEventVolumeTrigger> gameObjects = new List<RigEventVolumeTrigger>();

	[SerializeField]
	private Mode mode = Mode.ABSOLUTE;

	[Range(0.05f, 1f)]
	[SerializeField]
	private float relThreshold = 0.05f;

	[SerializeField]
	private VRRigCollection rigCollection;

	[Range(1f, 20f)]
	[SerializeField]
	private int absThreshold = 1;

	[SerializeField]
	private UnityEvent<VRRig> RigExits;

	[SerializeField]
	private UnityEvent GoesOverThreshold;

	private void OnEnable()
	{
		if (!(rigCollection == null))
		{
			VRRigCollection vRRigCollection = rigCollection;
			vRRigCollection.playerEnteredCollection = (Action<RigContainer>)Delegate.Combine(vRRigCollection.playerEnteredCollection, new Action<RigContainer>(OnJoined));
			VRRigCollection vRRigCollection2 = rigCollection;
			vRRigCollection2.playerLeftCollection = (Action<RigContainer>)Delegate.Combine(vRRigCollection2.playerLeftCollection, new Action<RigContainer>(OnLeft));
		}
	}

	private void OnDisable()
	{
		if (!(rigCollection == null))
		{
			VRRigCollection vRRigCollection = rigCollection;
			vRRigCollection.playerEnteredCollection = (Action<RigContainer>)Delegate.Remove(vRRigCollection.playerEnteredCollection, new Action<RigContainer>(OnJoined));
			VRRigCollection vRRigCollection2 = rigCollection;
			vRRigCollection2.playerLeftCollection = (Action<RigContainer>)Delegate.Remove(vRRigCollection2.playerLeftCollection, new Action<RigContainer>(OnLeft));
		}
	}

	private void OnDestroy()
	{
		if (!(rigCollection == null))
		{
			VRRigCollection vRRigCollection = rigCollection;
			vRRigCollection.playerEnteredCollection = (Action<RigContainer>)Delegate.Remove(vRRigCollection.playerEnteredCollection, new Action<RigContainer>(OnJoined));
			VRRigCollection vRRigCollection2 = rigCollection;
			vRRigCollection2.playerLeftCollection = (Action<RigContainer>)Delegate.Remove(vRRigCollection2.playerLeftCollection, new Action<RigContainer>(OnLeft));
		}
	}

	private void OnJoined(RigContainer rc)
	{
		int num = ((rigCollection == null) ? 1 : rigCollection.Rigs.Count);
		countChanged(gameObjects.Count, gameObjects.Count, num - 1, num, null);
	}

	private void OnLeft(RigContainer rc)
	{
		RigEventVolumeTrigger rigEventVolumeTrigger = null;
		for (int i = 0; i < gameObjects.Count; i++)
		{
			if (gameObjects[i].Rig == rc.Rig)
			{
				rigEventVolumeTrigger = gameObjects[i];
			}
		}
		int num = ((rigCollection == null) ? 1 : rigCollection.Rigs.Count);
		if (rigEventVolumeTrigger != null)
		{
			gameObjects.Remove(rigEventVolumeTrigger);
			countChanged(gameObjects.Count + 1, gameObjects.Count, num + 1, num, null);
		}
		else
		{
			countChanged(gameObjects.Count, gameObjects.Count, num + 1, num, null);
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		if (other.gameObject.TryGetComponent<RigEventVolumeTrigger>(out var component) && !(base.transform.InverseTransformPoint(component.transform.position).z < 0f) && gameObjects.Contains(component))
		{
			int num = ((rigCollection == null) ? 1 : rigCollection.Rigs.Count);
			int count = gameObjects.Count;
			gameObjects.Remove(component);
			countChanged(count, gameObjects.Count, num, num, component);
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (other.gameObject.TryGetComponent<RigEventVolumeTrigger>(out var component) && !(base.transform.InverseTransformPoint(component.transform.position).z < 0f) && !gameObjects.Contains(component))
		{
			int num = ((rigCollection == null) ? 1 : rigCollection.Rigs.Count);
			int count = gameObjects.Count;
			gameObjects.Add(component);
			countChanged(count, gameObjects.Count, num, num, component);
		}
	}

	private void countChanged(int oldValue, int newValue, int oldPlayerCount, int newPlayerCount, RigEventVolumeTrigger rig)
	{
		if (newValue > oldValue)
		{
			if (rig != null)
			{
				RigExits?.Invoke(rig.Rig);
			}
			if ((mode == Mode.RELATIVE && (float)newValue / (float)newPlayerCount >= relThreshold && (float)oldValue / (float)oldPlayerCount < relThreshold) || (mode == Mode.ABSOLUTE && newValue >= absThreshold && oldValue < absThreshold))
			{
				GoesOverThreshold?.Invoke();
			}
		}
	}

	bool IBuildValidation.BuildValidationCheck()
	{
		if (mode == Mode.RELATIVE && rigCollection == null)
		{
			UnityEngine.Debug.Log("RigEventGate on " + base.name + " is set to RELATIVE mode but has no Player Count Source. This will crash!");
			return false;
		}
		return true;
	}
}
public class RigEventVolume : MonoBehaviour
{
	private enum Mode
	{
		RELATIVE,
		ABSOLUTE,
		NONE
	}

	private Dictionary<RigEventVolumeTrigger, int> gameObjects = new Dictionary<RigEventVolumeTrigger, int>();

	[SerializeField]
	private Mode mode = Mode.ABSOLUTE;

	[Range(0.05f, 1f)]
	[SerializeField]
	private float relThreshold = 0.05f;

	[SerializeField]
	private VRRigCollection rigCollection;

	[Range(1f, 20f)]
	[SerializeField]
	private int absThreshold = 1;

	[SerializeField]
	private UnityEvent<VRRig> RigEnters;

	[SerializeField]
	private UnityEvent<VRRig> RigExits;

	[SerializeField]
	private UnityEvent GoesOverThreshold;

	[SerializeField]
	private UnityEvent GoesUnderThreshold;

	[SerializeField]
	private UnityEvent<VRRig> LocalRigEnters;

	[SerializeField]
	private UnityEvent<VRRig> LocalRigExits;

	private List<VRRig> rigs = new List<VRRig>();

	private bool localRigPresent;

	public VRRig[] Rigs => rigs.ToArray();

	public int RigCount => gameObjects.Keys.Count;

	public bool LocalRigPresent => localRigPresent;

	public event Action OnCountChanged;

	private void OnEnable()
	{
		if (mode == Mode.RELATIVE)
		{
			if (rigCollection != null)
			{
				VRRigCollection vRRigCollection = rigCollection;
				vRRigCollection.playerEnteredCollection = (Action<RigContainer>)Delegate.Combine(vRRigCollection.playerEnteredCollection, new Action<RigContainer>(OnJoined));
				VRRigCollection vRRigCollection2 = rigCollection;
				vRRigCollection2.playerLeftCollection = (Action<RigContainer>)Delegate.Combine(vRRigCollection2.playerLeftCollection, new Action<RigContainer>(OnLeft));
			}
			else
			{
				NetworkSystem.Instance.OnPlayerJoined += new Action<NetPlayer>(OnNetJoined);
				NetworkSystem.Instance.OnPlayerLeft += new Action<NetPlayer>(OnNetLeft);
			}
		}
	}

	private void OnDisable()
	{
		OnDestroy();
	}

	private void OnDestroy()
	{
		if (mode == Mode.RELATIVE)
		{
			if (rigCollection != null)
			{
				VRRigCollection vRRigCollection = rigCollection;
				vRRigCollection.playerEnteredCollection = (Action<RigContainer>)Delegate.Remove(vRRigCollection.playerEnteredCollection, new Action<RigContainer>(OnJoined));
				VRRigCollection vRRigCollection2 = rigCollection;
				vRRigCollection2.playerLeftCollection = (Action<RigContainer>)Delegate.Remove(vRRigCollection2.playerLeftCollection, new Action<RigContainer>(OnLeft));
			}
			else
			{
				NetworkSystem.Instance.OnPlayerJoined -= new Action<NetPlayer>(OnNetJoined);
				NetworkSystem.Instance.OnPlayerLeft -= new Action<NetPlayer>(OnNetLeft);
			}
		}
	}

	private void OnNetJoined(NetPlayer np)
	{
		int num = ((PhotonNetwork.CurrentRoom == null) ? 1 : PhotonNetwork.CurrentRoom.PlayerCount);
		countChanged(gameObjects.Count, gameObjects.Count, num - 1, num);
	}

	private void OnNetLeft(NetPlayer np)
	{
		int num = ((PhotonNetwork.CurrentRoom == null) ? 1 : PhotonNetwork.CurrentRoom.PlayerCount);
		countChanged(gameObjects.Count, gameObjects.Count, num + 1, num);
	}

	private void OnJoined(RigContainer rc)
	{
		int num = ((rigCollection == null) ? 1 : rigCollection.Rigs.Count);
		countChanged(gameObjects.Count, gameObjects.Count, num - 1, num);
	}

	private void OnLeft(RigContainer rc)
	{
		int num = ((rigCollection == null) ? 1 : rigCollection.Rigs.Count);
		countChanged(gameObjects.Count, gameObjects.Count, num + 1, num);
	}

	private void OnTriggerEnter(Collider other)
	{
		if (!other.gameObject.TryGetComponent<RigEventVolumeTrigger>(out var component))
		{
			return;
		}
		if (!gameObjects.ContainsKey(component))
		{
			gameObjects.Add(component, 0);
			rigs.Add(component.Rig);
			RigEnters?.Invoke(component.Rig);
			if (component.Rig == VRRig.LocalRig)
			{
				LocalRigEnters?.Invoke(component.Rig);
				localRigPresent = true;
			}
			if (mode != Mode.NONE)
			{
				int num = ((!(rigCollection == null)) ? rigCollection.Rigs.Count : ((PhotonNetwork.CurrentRoom == null) ? 1 : PhotonNetwork.CurrentRoom.PlayerCount));
				countChanged(gameObjects.Count - 1, gameObjects.Count, num, num);
			}
		}
		else
		{
			gameObjects[component]++;
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (!other.gameObject.TryGetComponent<RigEventVolumeTrigger>(out var component))
		{
			return;
		}
		gameObjects[component]--;
		if (gameObjects[component] < 0)
		{
			gameObjects.Remove(component);
			rigs.Remove(component.Rig);
			RigExits?.Invoke(component.Rig);
			if (component.Rig == VRRig.LocalRig)
			{
				LocalRigExits?.Invoke(component.Rig);
				localRigPresent = false;
			}
			if (mode != Mode.NONE)
			{
				int num = ((!(rigCollection == null)) ? rigCollection.Rigs.Count : ((PhotonNetwork.CurrentRoom == null) ? 1 : PhotonNetwork.CurrentRoom.PlayerCount));
				countChanged(gameObjects.Count + 1, gameObjects.Count, num, num);
			}
		}
	}

	private void countChanged(int oldValue, int newValue, int oldPlayerCount, int newPlayerCount)
	{
		if (newValue > oldValue)
		{
			if ((mode == Mode.RELATIVE && (float)newValue / (float)newPlayerCount >= relThreshold && (float)oldValue / (float)oldPlayerCount < relThreshold) || (mode == Mode.ABSOLUTE && newValue >= absThreshold && oldValue < absThreshold))
			{
				GoesOverThreshold?.Invoke();
			}
		}
		else if (newValue < oldValue && ((mode == Mode.RELATIVE && (float)newValue / (float)newPlayerCount < relThreshold && (float)oldValue / (float)oldPlayerCount >= relThreshold) || (mode == Mode.ABSOLUTE && newValue < absThreshold && oldValue >= absThreshold)))
		{
			GoesUnderThreshold?.Invoke();
		}
		this.OnCountChanged?.Invoke();
	}
}
public class RigEventVolumeObserver : MonoBehaviour
{
	[Serializable]
	private class RigEventVolumeObserverGameObject
	{
		public enum Comparison
		{
			EQ,
			LT,
			GT,
			LT_EQ,
			GT_EQ,
			NEQ
		}

		[SerializeField]
		private GameObject gameObject;

		[SerializeField]
		public Comparison comparison;

		[SerializeField]
		public int value;

		public bool Check(RigEventVolume rev)
		{
			return comparison switch
			{
				Comparison.EQ => rev.RigCount == value, 
				Comparison.LT => rev.RigCount < value, 
				Comparison.GT => rev.RigCount > value, 
				Comparison.LT_EQ => rev.RigCount <= value, 
				Comparison.GT_EQ => rev.RigCount >= value, 
				Comparison.NEQ => rev.RigCount != value, 
				_ => false, 
			};
		}

		public void ApplyActiveState(RigEventVolume rev)
		{
			gameObject.SetActive(Check(rev));
		}
	}

	[SerializeField]
	private RigEventVolume observed;

	[SerializeField]
	private RigEventVolumeObserverGameObject[] gameObjects;

	[SerializeField]
	private TMP_Text[] tMP_Texts;

	private List<string> formats = new List<string>();

	private void Awake()
	{
		for (int i = 0; i < tMP_Texts.Length; i++)
		{
			formats.Add(tMP_Texts[i].text);
		}
	}

	private void OnEnable()
	{
		Observed_OnCountChanged();
		observed.OnCountChanged += Observed_OnCountChanged;
	}

	private void OnDisable()
	{
		observed.OnCountChanged -= Observed_OnCountChanged;
	}

	private void Observed_OnCountChanged()
	{
		for (int i = 0; i < gameObjects.Length; i++)
		{
			gameObjects[i].ApplyActiveState(observed);
		}
		for (int j = 0; j < tMP_Texts.Length; j++)
		{
			tMP_Texts[j].text = Format(formats[j]);
		}
	}

	private string Format(string s)
	{
		return s.Replace("\\c", observed.RigCount.ToString());
	}
}
