	public VRMap GetMakingFist(bool debug, out bool isLeftHand)
	{
		if (IsMakingFistRight())
		{
			isLeftHand = false;
			return rightHand;
		}
		if (IsMakingFistLeft())
		{
			isLeftHand = true;
			return leftHand;
		}
		isLeftHand = false;
		return null;
	}

