	public void GetCosmeticsPlayFabCatalogData()
	{
		if (CosmeticsController.instance != null)
		{
			PlayFabClientAPI.GetUserInventory(new GetUserInventoryRequest(), delegate(GetUserInventoryResult result)
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				foreach (ItemInstance item in result.Inventory)
				{
					if (!dictionary.ContainsKey(item.ItemId))
					{
						dictionary[item.ItemId] = item.ItemId;
						if (item.CatalogVersion == CosmeticsController.instance.catalog)
						{
							AddCosmetic(item.ItemId);
							if (item.PurchaseDate.HasValue)
							{
								_playerOwnedCosmeticsAge[item.ItemId] = (int)(DateTime.UtcNow - item.PurchaseDate.Value).TotalDays;
							}
						}
					}
				}
			}, delegate
			{
				initializedCosmetics = true;
			});
		}
		AddCosmetic("Slingshot");
		foreach (BuilderPieceSet startPieceSet in BuilderSetManager.instance.StartPieceSets)
		{
			AddCosmetic(startPieceSet.playfabID);
		}
	}

	public void GenerateFingerAngleLookupTables()
	{
		GenerateTableIndex(ref leftIndex);
		GenerateTableIndex(ref rightIndex);
		GenerateTableMiddle(ref leftMiddle);
		GenerateTableMiddle(ref rightMiddle);
		GenerateTableThumb(ref leftThumb);
		GenerateTableThumb(ref rightThumb);
	}

	private void GenerateTableThumb(ref VRMapThumb thumb)
	{
		thumb.angle1Table = new UnityEngine.Quaternion[11];
		thumb.angle2Table = new UnityEngine.Quaternion[11];
		for (int i = 0; i < thumb.angle1Table.Length; i++)
		{
			thumb.angle1Table[i] = UnityEngine.Quaternion.Lerp(thumb.startingAngle1Quat, thumb.closedAngle1Quat, (float)i / 10f);
			thumb.angle2Table[i] = UnityEngine.Quaternion.Lerp(thumb.startingAngle2Quat, thumb.closedAngle2Quat, (float)i / 10f);
		}
	}

	private void GenerateTableIndex(ref VRMapIndex index)
	{
		index.angle1Table = new UnityEngine.Quaternion[11];
		index.angle2Table = new UnityEngine.Quaternion[11];
		index.angle3Table = new UnityEngine.Quaternion[11];
		for (int i = 0; i < index.angle1Table.Length; i++)
		{
			index.angle1Table[i] = UnityEngine.Quaternion.Lerp(index.startingAngle1Quat, index.closedAngle1Quat, (float)i / 10f);
			index.angle2Table[i] = UnityEngine.Quaternion.Lerp(index.startingAngle2Quat, index.closedAngle2Quat, (float)i / 10f);
			index.angle3Table[i] = UnityEngine.Quaternion.Lerp(index.startingAngle3Quat, index.closedAngle3Quat, (float)i / 10f);
		}
	}

	private void GenerateTableMiddle(ref VRMapMiddle middle)
	{
		middle.angle1Table = new UnityEngine.Quaternion[11];
		middle.angle2Table = new UnityEngine.Quaternion[11];
		middle.angle3Table = new UnityEngine.Quaternion[11];
		for (int i = 0; i < middle.angle1Table.Length; i++)
		{
			middle.angle1Table[i] = UnityEngine.Quaternion.Lerp(middle.startingAngle1Quat, middle.closedAngle1Quat, (float)i / 10f);
			middle.angle2Table[i] = UnityEngine.Quaternion.Lerp(middle.startingAngle2Quat, middle.closedAngle2Quat, (float)i / 10f);
			middle.angle3Table[i] = UnityEngine.Quaternion.Lerp(middle.startingAngle3Quat, middle.closedAngle3Quat, (float)i / 10f);
		}
	}

	private UnityEngine.Quaternion SanitizeQuaternion(UnityEngine.Quaternion quat)
	{
		if (float.IsNaN(quat.w) || float.IsNaN(quat.x) || float.IsNaN(quat.y) || float.IsNaN(quat.z) || float.IsInfinity(quat.w) || float.IsInfinity(quat.x) || float.IsInfinity(quat.y) || float.IsInfinity(quat.z))
		{
			return UnityEngine.Quaternion.identity;
		}
		return quat;
	}

	private UnityEngine.Vector3 SanitizeVector3(UnityEngine.Vector3 vec)
	{
		if (float.IsNaN(vec.x) || float.IsNaN(vec.y) || float.IsNaN(vec.z) || float.IsInfinity(vec.x) || float.IsInfinity(vec.y) || float.IsInfinity(vec.z))
		{
			return UnityEngine.Vector3.zero;
		}
		return UnityEngine.Vector3.ClampMagnitude(vec, 5000f);
	}

