	private void AddVelocityToQueue(UnityEngine.Vector3 position, double serverTime)
	{
		UnityEngine.Vector3 velocity = UnityEngine.Vector3.zero;
		if (velocityHistoryList.Count > 0)
		{
			double num = Utils.CalculateNetworkDeltaTime(velocityHistoryList[0].time, serverTime);
			if (num == 0.0)
			{
				return;
			}
			velocity = (position - lastPosition) / (float)num;
		}
		velocityHistoryList.Add(new VelocityTime(velocity, serverTime));
		lastPosition = position;
	}

	private UnityEngine.Vector3 ReturnVelocityAtTime(double timeToReturn)
	{
		if (velocityHistoryList.Count <= 1)
		{
			return UnityEngine.Vector3.zero;
		}
		int num = 0;
		int num2 = velocityHistoryList.Count - 1;
		int num3 = 0;
		if (num2 == num)
		{
			return velocityHistoryList[num].vel;
		}
		while (num2 - num > 1 && num3 < 1000)
		{
			num3++;
			int num4 = (num2 - num) / 2;
			if (velocityHistoryList[num4].time > timeToReturn)
			{
				num2 = num4;
			}
			else
			{
				num = num4;
			}
		}
		float num5 = (float)(velocityHistoryList[num].time - timeToReturn);
		double num6 = velocityHistoryList[num].time - velocityHistoryList[num2].time;
		if (num6 == 0.0)
		{
			num6 = 0.001;
		}
		num5 /= (float)num6;
		num5 = Mathf.Clamp(num5, 0f, 1f);
		return UnityEngine.Vector3.Lerp(velocityHistoryList[num].vel, velocityHistoryList[num2].vel, num5);
	}

	public UnityEngine.Vector3 LatestVelocity()
	{
		if (velocityHistoryList.Count > 0)
		{
			return velocityHistoryList[0].vel;
		}
		return UnityEngine.Vector3.zero;
	}

	public bool IsPositionInRange(UnityEngine.Vector3 position, float range)
	{
		return (syncPos - position).IsShorterThan(range * scaleFactor);
	}

	public bool CheckTagDistanceRollback(VRRig otherRig, float max, float timeInterval)
	{
		GorillaMath.LineSegClosestPoints(syncPos, -LatestVelocity() * timeInterval, otherRig.syncPos, -otherRig.LatestVelocity() * timeInterval, out var lineAPoint, out var lineBPoint);
		return UnityEngine.Vector3.SqrMagnitude(lineAPoint - lineBPoint) < max * max * scaleFactor;
	}

	public UnityEngine.Vector3 ClampVelocityRelativeToPlayerSafe(UnityEngine.Vector3 inVel, float max, float teleportSpeedThreshold = 100f)
	{
		max *= scaleFactor;
		UnityEngine.Vector3 v = UnityEngine.Vector3.zero;
		v.SetValueSafe(in inVel);
		UnityEngine.Vector3 vector = ((velocityHistoryList.Count > 0) ? velocityHistoryList[0].vel : UnityEngine.Vector3.zero);
		if (vector.sqrMagnitude > teleportSpeedThreshold * teleportSpeedThreshold)
		{
			vector = UnityEngine.Vector3.zero;
		}
		UnityEngine.Vector3 vector2 = v - vector;
		vector2 = UnityEngine.Vector3.ClampMagnitude(vector2, max);
		return vector + vector2;
	}

