	bool IUserCosmeticsCallback.OnGetUserCosmetics(string cosmeticsString)
	{
		if (cosmeticsString == "BANNED")
		{
			_playerOwnedCosmetics.Clear();
			_playerOwnedCosmeticsAge.Clear();
			return true;
		}
		Dictionary<string, ItemInstance> dictionary;
		try
		{
			dictionary = JsonConvert.DeserializeObject<Dictionary<string, ItemInstance>>(cosmeticsString);
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("Failed to deserialize cosmetics for " + creator?.NickName + ": " + ex.Message);
			dictionary = null;
		}
		if (currentCosmeticTries < cosmeticRetries && (dictionary == null || _playerOwnedCosmetics.SetEquals(dictionary.Keys)))
		{
			currentCosmeticTries++;
			return false;
		}
		if (dictionary == null)
		{
			dictionary = new Dictionary<string, ItemInstance>();
		}
		currentCosmeticTries = 0;
		SaveOwnedCosmetics(dictionary);
		InitializedCosmetics = true;
		SetCosmeticsActive(playfx: false);
		myBodyDockPositions.RefreshTransferrableItems();
		netView?.SendRPC("RPC_RequestCosmetics", creator);
		return true;
	}

	private void SaveOwnedCosmetics(Dictionary<string, ItemInstance> cosmetics)
	{
		if (cosmetics.Count == 0)
		{
			return;
		}
		_playerOwnedCosmetics.Clear();
		_playerOwnedCosmeticsAge.Clear();
		foreach (var (text2, itemInstance2) in cosmetics)
		{
			_playerOwnedCosmetics.Add(text2);
			if (itemInstance2 != null && itemInstance2.PurchaseDate.HasValue)
			{
				_playerOwnedCosmeticsAge[text2] = (int)(DateTime.UtcNow - itemInstance2.PurchaseDate.Value).TotalDays;
			}
		}
		CheckForEarlyAccess();
	}

	internal void AddCosmetic(string cosmeticId)
	{
		_playerOwnedCosmetics.Add(cosmeticId);
	}

	internal bool HasCosmetic(string cosmeticId)
	{
		return _playerOwnedCosmetics.Contains(cosmeticId);
	}

	private short PackCompetitiveData()
	{
		if (!turningCompInitialized)
		{
			GorillaSnapTurningComp = GorillaTagger.Instance.GetComponent<GorillaSnapTurn>();
			turningCompInitialized = true;
		}
		fps = Mathf.Min(Mathf.RoundToInt(1f / Time.smoothDeltaTime), 255);
		int num = 0;
		if (GorillaSnapTurningComp != null)
		{
			turnFactor = GorillaSnapTurningComp.turnFactor;
			turnType = GorillaSnapTurningComp.turnType;
			string text = turnType;
			if (!(text == "SNAP"))
			{
				if (text == "SMOOTH")
				{
					num = 2;
				}
			}
			else
			{
				num = 1;
			}
			num *= 10;
			num += turnFactor;
		}
		return (short)(fps + (num << 8));
	}

	private void UnpackCompetitiveData(short packed)
	{
		int num = 255;
		fps = packed & num;
		int num2 = 31;
		int num3 = (packed >> 8) & num2;
		turnFactor = num3 % 10;
		switch (num3 / 10)
		{
		case 1:
			turnType = "SNAP";
			break;
		case 2:
			turnType = "SMOOTH";
			break;
		default:
			turnType = "NONE";
			break;
		}
	}

	private void OnKIDSessionUpdated(bool showCustomNames, KID.Model.Permission.ManagedByEnum managedBy)
	{
		bool flag = (showCustomNames || managedBy == KID.Model.Permission.ManagedByEnum.PLAYER) && managedBy != KID.Model.Permission.ManagedByEnum.PROHIBITED;
		GorillaComputer.instance.SetComputerSettingsBySafety(!flag, new GorillaComputer.ComputerState[1] { GorillaComputer.ComputerState.Name }, shouldHide: false);
		bool flag2 = PlayerPrefs.GetInt("nameTagsOn", -1) > 0;
		switch (managedBy)
		{
		case KID.Model.Permission.ManagedByEnum.PLAYER:
			flag = GorillaComputer.instance.NametagsEnabled;
			break;
		case KID.Model.Permission.ManagedByEnum.PROHIBITED:
			flag = false;
			break;
		case KID.Model.Permission.ManagedByEnum.GUARDIAN:
			flag = showCustomNames && flag2;
			break;
		}
		UpdateName(flag);
		UnityEngine.Debug.Log("[KID] On Session Update - Custom Names Permission changed - Has enabled customNames? [" + flag + "]");
	}

	private IList<KeyValueStringPair> buildEntries()
	{
		return new KeyValueStringPair[2]
		{
			new KeyValueStringPair("Name", playerNameVisible),
			new KeyValueStringPair("Color", $"{Mathf.RoundToInt(playerColor.r * 9f)}, {Mathf.RoundToInt(playerColor.g * 9f)}, {Mathf.RoundToInt(playerColor.b * 9f)}")
		};
	}
}
[Serializable]
public class VRMap
{
	public XRNode vrTargetNode;

	public Transform overrideTarget;

	public Transform rigTarget;

	public UnityEngine.Vector3 trackingPositionOffset;

	public UnityEngine.Vector3 trackingRotationOffset;

	internal NetworkVector3 netSyncPos = new NetworkVector3();

	public UnityEngine.Quaternion syncRotation;

	public float calcT;

	private UnityEngine.XR.InputDevice myInputDevice;

	private bool hasInputDevice;

	public Transform handholdOverrideTarget;

	public UnityEngine.Vector3 handholdOverrideTargetOffset;

	public UnityEngine.Vector3 syncPos
	{
		get
		{
			return netSyncPos.CurrentSyncTarget;
		}
		set
		{
			netSyncPos.SetNewSyncTarget(value);
		}
	}

	public virtual void Initialize()
	{
	}

	public void MapOther(float lerpValue)
	{
		rigTarget.GetLocalPositionAndRotation(out var localPosition, out var localRotation);
		rigTarget.SetLocalPositionAndRotation(UnityEngine.Vector3.Lerp(localPosition, syncPos, lerpValue), UnityEngine.Quaternion.Lerp(localRotation, syncRotation, lerpValue));
	}

	public void MapMine(float ratio, Transform playerOffsetTransform)
	{
		rigTarget.GetPositionAndRotation(out var position, out var rotation);
		if (overrideTarget != null)
		{
			overrideTarget.GetPositionAndRotation(out var position2, out var rotation2);
			rigTarget.SetPositionAndRotation(position2 + rotation * trackingPositionOffset * ratio, rotation2 * UnityEngine.Quaternion.Euler(trackingRotationOffset));
		}
		else
		{
			if (!hasInputDevice && ConnectedControllerHandler.Instance.GetValidForXRNode(vrTargetNode))
			{
				myInputDevice = InputDevices.GetDeviceAtXRNode(vrTargetNode);
				hasInputDevice = true;
				if (vrTargetNode != XRNode.LeftHand && vrTargetNode != XRNode.RightHand)
				{
					hasInputDevice = myInputDevice.isValid;
				}
			}
			if (hasInputDevice && myInputDevice.TryGetFeatureValue(UnityEngine.XR.CommonUsages.deviceRotation, out var value) && myInputDevice.TryGetFeatureValue(UnityEngine.XR.CommonUsages.devicePosition, out var value2))
			{
				UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.identity;
				Transform parent = playerOffsetTransform.parent;
				if (parent.IsNotNull())
				{
					quaternion2 = parent.rotation;
				}
				rigTarget.SetPositionAndRotation(value2 + rotation * trackingPositionOffset * ratio + playerOffsetTransform.position, quaternion2 * value * UnityEngine.Quaternion.Euler(trackingRotationOffset));
				rigTarget.RotateAround(playerOffsetTransform.position, playerOffsetTransform.up, playerOffsetTransform.localEulerAngles.y);
			}
		}
		if (handholdOverrideTarget != null)
		{
			rigTarget.position = UnityEngine.Vector3.MoveTowards(position, handholdOverrideTarget.position - handholdOverrideTargetOffset + rotation * trackingPositionOffset * ratio, Time.deltaTime * 2f);
		}
	}

	public UnityEngine.Vector3 GetExtrapolatedControllerPosition()
	{
		rigTarget.GetPositionAndRotation(out var position, out var rotation);
		return position - rotation * trackingPositionOffset * rigTarget.lossyScale.x;
	}

	public virtual void MapOtherFinger(float handSync, float lerpValue)
	{
		calcT = handSync;
		LerpFinger(lerpValue, isOther: true);
	}

	public virtual void MapMyFinger(float lerpValue)
	{
	}

	public virtual void LerpFinger(float lerpValue, bool isOther)
	{
	}
}
[Serializable]
public class VRMapIndex : VRMap
{
	public InputFeatureUsage inputAxis;

	public float triggerTouch;

	public float triggerValue;

	public Transform fingerBone1;

	public Transform fingerBone2;

	public Transform fingerBone3;

	public UnityEngine.Vector3 closedAngle1;

	public UnityEngine.Vector3 closedAngle2;

	public UnityEngine.Vector3 closedAngle3;

	public UnityEngine.Vector3 startingAngle1;

	public UnityEngine.Vector3 startingAngle2;

	public UnityEngine.Vector3 startingAngle3;

	public UnityEngine.Quaternion closedAngle1Quat;

	public UnityEngine.Quaternion closedAngle2Quat;

	public UnityEngine.Quaternion closedAngle3Quat;

	public UnityEngine.Quaternion startingAngle1Quat;

	public UnityEngine.Quaternion startingAngle2Quat;

	public UnityEngine.Quaternion startingAngle3Quat;

	private int lastAngle1;

	private int lastAngle2;

	private int lastAngle3;

	private UnityEngine.XR.InputDevice myInputDevice;

	public UnityEngine.Quaternion[] angle1Table;

	public UnityEngine.Quaternion[] angle2Table;

	public UnityEngine.Quaternion[] angle3Table;

	private float currentAngle1;

	private float currentAngle2;

	private float currentAngle3;

	private int myTempInt;

	public override void Initialize()
	{
		closedAngle1Quat = UnityEngine.Quaternion.Euler(closedAngle1);
		closedAngle2Quat = UnityEngine.Quaternion.Euler(closedAngle2);
		closedAngle3Quat = UnityEngine.Quaternion.Euler(closedAngle3);
		startingAngle1Quat = UnityEngine.Quaternion.Euler(startingAngle1);
		startingAngle2Quat = UnityEngine.Quaternion.Euler(startingAngle2);
		startingAngle3Quat = UnityEngine.Quaternion.Euler(startingAngle3);
	}

	public override void MapMyFinger(float lerpValue)
	{
		calcT = 0f;
		triggerValue = ControllerInputPoller.TriggerFloat(vrTargetNode);
		triggerTouch = ControllerInputPoller.TriggerTouch(vrTargetNode);
		calcT = 0.1f * triggerTouch;
		calcT += 0.9f * triggerValue;
		LerpFinger(lerpValue, isOther: false);
	}

	public override void LerpFinger(float lerpValue, bool isOther)
	{
		if (isOther)
		{
			currentAngle1 = Mathf.Lerp(currentAngle1, calcT, lerpValue);
			currentAngle2 = Mathf.Lerp(currentAngle2, calcT, lerpValue);
			currentAngle3 = Mathf.Lerp(currentAngle3, calcT, lerpValue);
			myTempInt = (int)(currentAngle1 * 10.1f);
			if (myTempInt != lastAngle1)
			{
				lastAngle1 = myTempInt;
				fingerBone1.localRotation = angle1Table[lastAngle1];
			}
			myTempInt = (int)(currentAngle2 * 10.1f);
			if (myTempInt != lastAngle2)
			{
				lastAngle2 = myTempInt;
				fingerBone2.localRotation = angle2Table[lastAngle2];
			}
			myTempInt = (int)(currentAngle3 * 10.1f);
			if (myTempInt != lastAngle3)
			{
				lastAngle3 = myTempInt;
				fingerBone3.localRotation = angle3Table[lastAngle3];
			}
		}
		else
		{
			fingerBone1.localRotation = UnityEngine.Quaternion.Lerp(fingerBone1.localRotation, UnityEngine.Quaternion.Lerp(startingAngle1Quat, closedAngle1Quat, calcT), lerpValue);
			fingerBone2.localRotation = UnityEngine.Quaternion.Lerp(fingerBone2.localRotation, UnityEngine.Quaternion.Lerp(startingAngle2Quat, closedAngle2Quat, calcT), lerpValue);
			fingerBone3.localRotation = UnityEngine.Quaternion.Lerp(fingerBone3.localRotation, UnityEngine.Quaternion.Lerp(startingAngle3Quat, closedAngle3Quat, calcT), lerpValue);
		}
	}
}
