public class CosmeticBoundaryTrigger : GorillaTriggerBox
{
	public VRRig rigRef;

	private static TimeSince sinceLastTryOnEvent = 0f;

	public void OnTriggerEnter(Collider other)
	{
		if (other.attachedRigidbody == null)
		{
			return;
		}
		rigRef = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
		if (!(rigRef == null))
		{
			if (sinceLastTryOnEvent.HasElapsed(0.5f, resetOnElapsed: true))
			{
				GorillaTelemetry.PostShopEvent(rigRef, GTShopEventType.item_try_on, rigRef.tryOnSet.items);
			}
			rigRef.inTryOnRoom = true;
			rigRef.LocalUpdateCosmeticsWithTryon(rigRef.cosmeticSet, rigRef.tryOnSet, playfx: false);
			rigRef.myBodyDockPositions.RefreshTransferrableItems();
		}
	}

	public void OnTriggerExit(Collider other)
	{
		if (other.attachedRigidbody == null)
		{
			return;
		}
		rigRef = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
		if (!(rigRef == null))
		{
			rigRef.inTryOnRoom = false;
			if (rigRef.isOfflineVRRig)
			{
				rigRef.tryOnSet.ClearSet(CosmeticsController.instance.nullItem);
				CosmeticsController.instance.ClearCheckout(sendEvent: false);
				CosmeticsController.instance.UpdateShoppingCart();
				CosmeticsController.instance.UpdateWornCosmetics(sync: true);
				CosmeticsController.ClearTryOnCollectable();
			}
			rigRef.LocalUpdateCosmeticsWithTryon(rigRef.cosmeticSet, rigRef.tryOnSet, playfx: false);
			rigRef.myBodyDockPositions.RefreshTransferrableItems();
		}
	}
}
public static class JSonHelper
{
	[Serializable]
	private class Wrapper<T>
	{
		public T[] Items;
	}

	public static T[] FromJson<T>(string json)
	{
		return JsonUtility.FromJson<Wrapper<T>>(json).Items;
	}

	public static string ToJson<T>(T[] array)
	{
		return JsonUtility.ToJson(new Wrapper<T>
		{
			Items = array
		});
	}

	public static string ToJson<T>(T[] array, bool prettyPrint)
	{
		return JsonUtility.ToJson(new Wrapper<T>
		{
			Items = array
		}, prettyPrint);
	}
}
[Serializable]
internal struct BundleData
{
	public string skuName;

	public string playFabItemName;

	public int shinyRocks;

	public int majorVersion;

	public int minorVersion;

	public int minorVersion2;

	public bool isActive;
}
internal class BundleList
{
	private int activeBundleIdx;

	public BundleData[] data;

	public void FromJson(string jsonString)
	{
		data = JSonHelper.FromJson<BundleData>(jsonString);
		if (data.Length == 0)
		{
			return;
		}
		activeBundleIdx = 0;
		int majorVersion = data[0].majorVersion;
		int minorVersion = data[0].minorVersion;
		int minorVersion2 = data[0].minorVersion2;
		int gameMajorVersion = NetworkSystemConfig.GameMajorVersion;
		int gameMinorVersion = NetworkSystemConfig.GameMinorVersion;
		int gameMinorVersion2 = NetworkSystemConfig.GameMinorVersion2;
		for (int i = 1; i < data.Length; i++)
		{
			data[i].isActive = false;
			int num = gameMajorVersion * 1000000 + gameMinorVersion * 1000 + gameMinorVersion2;
			int num2 = data[i].majorVersion * 1000000 + data[i].minorVersion * 1000 + data[i].minorVersion2;
			if (num >= num2 && data[i].majorVersion >= majorVersion && data[i].minorVersion >= minorVersion && data[i].minorVersion2 >= minorVersion2)
			{
				activeBundleIdx = i;
				majorVersion = data[i].majorVersion;
				minorVersion = data[i].minorVersion;
				minorVersion2 = data[i].minorVersion2;
				break;
			}
		}
		data[activeBundleIdx].isActive = true;
	}

	public bool HasSku(string skuName, out int idx)
	{
		if (data == null)
		{
			idx = -1;
			return false;
		}
		for (int i = 0; i < data.Length; i++)
		{
			if (data[i].skuName == skuName)
			{
				idx = i;
				return true;
			}
		}
		idx = -1;
		return false;
	}

	public BundleData ActiveBundle()
	{
		return data[activeBundleIdx];
	}
}
