	private float sphereRadius;

	private UnityEngine.Vector3 spherecastSweep;

	private int collidersHitCount;

	private List<RaycastHit> hitList = new List<RaycastHit>(20);

	private Drum tempDrum;

	private bool drumHit;

	private RaycastHit nullHit;

	public int onlineOffset;

	[Tooltip("VRRig object of the player, used to determine if it is an offline rig.")]
	private VRRig myRig;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = rig;
		leftHandIndicator = GorillaTagger.Instance.leftHandTriggerCollider.GetComponent<GorillaTriggerColliderHandIndicator>();
		rightHandIndicator = GorillaTagger.Instance.rightHandTriggerCollider.GetComponent<GorillaTriggerColliderHandIndicator>();
		sphereRadius = leftHandIndicator.GetComponent<SphereCollider>().radius;
		for (int i = 0; i < collidersForThisDrum.Length; i++)
		{
			collidersForThisDrumList.Add(collidersForThisDrum[i]);
		}
		for (int j = 0; j < drumsAS.Length; j++)
		{
			myRig.AssignDrumToMusicDrums(j + onlineOffset, drumsAS[j]);
		}
	}

	void ISpawnable.OnDespawn()
	{
	}

	private void LateUpdate()
	{
		CheckHandHit(ref leftHandIn, ref leftHandIndicator, isLeftHand: true);
		CheckHandHit(ref rightHandIn, ref rightHandIndicator, isLeftHand: false);
	}

	private void CheckHandHit(ref bool handIn, ref GorillaTriggerColliderHandIndicator handIndicator, bool isLeftHand)
	{
		spherecastSweep = handIndicator.transform.position - handIndicator.lastPosition;
		if (spherecastSweep.magnitude < 0.0001f)
		{
			spherecastSweep = UnityEngine.Vector3.up * 0.0001f;
		}
		for (int i = 0; i < collidersHit.Length; i++)
		{
			collidersHit[i] = nullHit;
		}
		collidersHitCount = Physics.SphereCastNonAlloc(handIndicator.lastPosition, sphereRadius, spherecastSweep.normalized, collidersHit, spherecastSweep.magnitude, drumsTouchable, QueryTriggerInteraction.Collide);
		drumHit = false;
		if (collidersHitCount > 0)
		{
			hitList.Clear();
			for (int j = 0; j < collidersHit.Length; j++)
			{
				if (collidersHit[j].collider != null && collidersForThisDrumList.Contains(collidersHit[j].collider) && collidersHit[j].collider.gameObject.activeSelf)
				{
					hitList.Add(collidersHit[j]);
				}
			}
			hitList.Sort(RayCastHitCompare);
			for (int k = 0; k < hitList.Count; k++)
			{
				tempDrum = hitList[k].collider.GetComponent<Drum>();
				if (tempDrum != null)
				{
					drumHit = true;
					if (!handIn && !tempDrum.disabler)
					{
						DrumHit(tempDrum, isLeftHand, handIndicator.currentVelocity.magnitude);
					}
					break;
				}
			}
		}
		if (!drumHit & handIn)
		{
			GorillaTagger.Instance.StartVibration(isLeftHand, GorillaTagger.Instance.tapHapticStrength / 8f, GorillaTagger.Instance.tapHapticDuration);
		}
		handIn = drumHit;
	}

	private int RayCastHitCompare(RaycastHit a, RaycastHit b)
	{
		if (a.distance < b.distance)
		{
			return -1;
		}
		if (a.distance == b.distance)
		{
			return 0;
		}
		return 1;
	}

	public void DrumHit(Drum tempDrumInner, bool isLeftHand, float hitVelocity)
	{
		if (isLeftHand)
		{
			if (leftHandIn)
			{
				return;
			}
			leftHandIn = true;
		}
		else
		{
			if (rightHandIn)
			{
				return;
			}
			rightHandIn = true;
		}
		volToPlay = Mathf.Max(Mathf.Min(1f, hitVelocity / maxDrumVolumeVelocity) * maxDrumVolume, minDrumVolume);
		if (NetworkSystem.Instance.InRoom)
		{
			if (!myRig.isOfflineVRRig)
			{
				myRig.netView?.SendRPC("RPC_PlayDrum", RpcTarget.Others, tempDrumInner.myIndex + onlineOffset, volToPlay);
			}
			else
			{
				GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayDrum", RpcTarget.Others, tempDrumInner.myIndex + onlineOffset, volToPlay);
			}
		}
		GorillaTagger.Instance.StartVibration(isLeftHand, GorillaTagger.Instance.tapHapticStrength / 4f, GorillaTagger.Instance.tapHapticDuration);
		drumsAS[tempDrumInner.myIndex].volume = maxDrumVolume;
		drumsAS[tempDrumInner.myIndex].GTPlayOneShot(drumsAS[tempDrumInner.myIndex].clip, volToPlay);
	}
}
public class EdibleHoldable : TransferrableObject
{
	private enum EdibleHoldableStates
	{
		EatingState0 = 1,
		EatingState1 = 2,
		EatingState2 = 4,
		EatingState3 = 8
	}

	[Serializable]
	public class BiteEvent : UnityEvent<VRRig, int>
	{
	}

	public AudioClip[] eatSounds;

	public GameObject[] edibleMeshObjects;

	public BiteEvent onBiteView;

	public BiteEvent onBiteWorld;

	[DebugReadout]
	public float lastEatTime;

	[DebugReadout]
	public float lastFullyEatenTime;

	public float eatMinimumCooldown = 1f;

	public float respawnTime = 7f;

	public float biteDistance = 0.1666667f;

	public UnityEngine.Vector3 biteOffset = new UnityEngine.Vector3(0f, 0.0208f, 0.171f);

	public Transform biteSpot;

	public bool inBiteZone;

	public AudioSource eatSoundSource;

	private EdibleHoldableStates previousEdibleState;

	private IResettableItem[] iResettableItems;

	[field: NonSerialized]
	public int lastBiterActorID { get; private set; } = -1;

	protected override void Start()
	{
		base.Start();
		itemState = ItemStates.State0;
		previousEdibleState = (EdibleHoldableStates)itemState;
		lastFullyEatenTime = 0f - respawnTime;
		iResettableItems = GetComponentsInChildren<IResettableItem>(includeInactive: true);
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		base.OnGrab(pointGrabbed, grabbingHand);
		lastEatTime = Time.time - eatMinimumCooldown;
	}

	public override void OnActivate()
	{
		base.OnActivate();
	}

	internal override void OnEnable()
	{
		base.OnEnable();
	}

	internal override void OnDisable()
	{
		base.OnDisable();
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (InHand())
		{
			return false;
		}
		return true;
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		if (itemState == ItemStates.State3)
		{
			if (Time.time > lastFullyEatenTime + respawnTime)
			{
				itemState = ItemStates.State0;
			}
		}
		else
		{
			if (!(Time.time > lastEatTime + eatMinimumCooldown))
			{
				return;
			}
			bool flag = false;
			bool flag2 = false;
			float num = biteDistance * biteDistance;
			if (!GorillaParent.hasInstance)
			{
				return;
			}
			VRRig vRRig = null;
			VRRig vRRig2 = null;
			for (int i = 0; i < VRRigCache.ActiveRigContainers.Count; i++)
			{
				VRRig rig = VRRigCache.ActiveRigContainers[i].Rig;
				if (!rig.isOfflineVRRig)
				{
					if (rig.head == null || GTExt.IsNull(rig.head.rigTarget))
					{
						break;
					}
					Transform transform = rig.head.rigTarget.transform;
					if ((transform.position + transform.rotation * biteOffset - biteSpot.position).sqrMagnitude < num)
					{
						flag = true;
						vRRig2 = rig;
					}
				}
			}
			Transform transform2 = GorillaTagger.Instance.offlineVRRig.head.rigTarget.transform;
			if ((transform2.position + transform2.rotation * biteOffset - biteSpot.position).sqrMagnitude < num)
			{
				flag = true;
				flag2 = true;
				vRRig = GorillaTagger.Instance.offlineVRRig;
			}
			if (flag && !inBiteZone && (!flag2 || InHand()) && itemState != ItemStates.State3)
			{
				if (itemState == ItemStates.State0)
				{
					itemState = ItemStates.State1;
				}
				else if (itemState == ItemStates.State1)
				{
					itemState = ItemStates.State2;
				}
				else if (itemState == ItemStates.State2)
				{
					itemState = ItemStates.State3;
				}
				lastEatTime = Time.time;
				lastFullyEatenTime = Time.time;
			}
			if (flag)
			{
				if (flag2)
				{
					lastBiterActorID = ((!vRRig) ? (-1) : (vRRig.OwningNetPlayer?.ActorNumber ?? (-1)));
					onBiteView?.Invoke(vRRig, (int)itemState);
				}
				else
				{
					lastBiterActorID = ((!vRRig2) ? (-1) : (vRRig2.OwningNetPlayer?.ActorNumber ?? (-1)));
					onBiteWorld?.Invoke(vRRig2, (int)itemState);
				}
			}
			inBiteZone = flag;
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		EdibleHoldableStates edibleHoldableStates = (EdibleHoldableStates)itemState;
		if (edibleHoldableStates != previousEdibleState)
		{
			OnEdibleHoldableStateChange();
		}
		previousEdibleState = edibleHoldableStates;
	}

	protected virtual void OnEdibleHoldableStateChange()
	{
		float amplitude = GorillaTagger.Instance.tapHapticStrength / 4f;
		float fixedDeltaTime = Time.fixedDeltaTime;
		float volumeScale = 0.08f;
		int num = 0;
		if (itemState == ItemStates.State0)
		{
			num = 0;
			if (iResettableItems != null)
			{
				IResettableItem[] array = iResettableItems;
				for (int i = 0; i < array.Length; i++)
				{
					array[i]?.ResetToDefaultState();
				}
			}
		}
		else if (itemState == ItemStates.State1)
		{
			num = 1;
		}
		else if (itemState == ItemStates.State2)
		{
			num = 2;
		}
		else if (itemState == ItemStates.State3)
		{
			num = 3;
		}
		int num2 = num - 1;
		if (num2 < 0)
		{
			num2 = edibleMeshObjects.Length - 1;
		}
		edibleMeshObjects[num2].SetActive(value: false);
		edibleMeshObjects[num].SetActive(value: true);
		if ((itemState != ItemStates.State0 && onBiteView != null) || onBiteWorld != null)
		{
			VRRig vRRig = null;
			float num3 = float.PositiveInfinity;
			for (int j = 0; j < VRRigCache.ActiveRigContainers.Count; j++)
			{
				VRRig rig = VRRigCache.ActiveRigContainers[j].Rig;
				if (rig.head == null || GTExt.IsNull(rig.head.rigTarget))
				{
					break;
				}
				Transform transform = rig.head.rigTarget.transform;
				float sqrMagnitude = (transform.position + transform.rotation * biteOffset - biteSpot.position).sqrMagnitude;
				if (sqrMagnitude < num3)
				{
					num3 = sqrMagnitude;
					vRRig = rig;
				}
			}
			if (vRRig.IsNotNull())
			{
				(vRRig.isOfflineVRRig ? onBiteView : onBiteWorld)?.Invoke(vRRig, (int)itemState);
				if (vRRig.isOfflineVRRig && itemState != ItemStates.State0)
				{
					PlayerGameEvents.EatObject(interactEventName);
				}
			}
		}
		eatSoundSource.GTPlayOneShot(eatSounds[num], volumeScale);
		if (IsMyItem())
		{
			if (InHand())
			{
				GorillaTagger.Instance.StartVibration(InLeftHand(), amplitude, fixedDeltaTime);
				return;
			}
			GorillaTagger.Instance.StartVibration(forLeftController: false, amplitude, fixedDeltaTime);
			GorillaTagger.Instance.StartVibration(forLeftController: true, amplitude, fixedDeltaTime);
		}
	}

	public override bool CanActivate()
	{
		return true;
	}

	public override bool CanDeactivate()
	{
		return true;
	}
}
public class GeodeItem : TransferrableObject
{
	[Tooltip("This GameObject will activate when the geode hits the ground with enough force.")]
	public GameObject effectsGameObject;

	public LayerMask collisionLayerMask;

	[Tooltip("Used to calculate velocity of the geode.")]
	public GorillaVelocityEstimator velocityEstimator;

	public float cooldown = 5f;

	[Tooltip("The velocity of the geode must be greater than this value to activate the effect.")]
	public float minHitVelocity = 0.2f;

	[Tooltip("Geode's full mesh before cracking")]
	public GameObject geodeFullMesh;

	[Tooltip("Geode's cracked open half different meshes, picked randomly")]
	public GameObject[] geodeCrackedMeshes;

	[Tooltip("The distance between te geode and the layer mask to detect whether it hits it")]
	public float rayCastMaxDistance = 0.2f;

	[FormerlySerializedAs("collisionRadius")]
	public float sphereRayRadius = 0.05f;

	[DebugReadout]
	private float cooldownRemaining;

	[DebugReadout]
	private bool hitLastFrame;

	[SerializeField]
	private AudioSource audioSource;

	public bool randomizeGeode = true;

	public UnityEvent<GeodeItem> OnGeodeCracked;

	public UnityEvent<GeodeItem> OnGeodeGrabbed;

	private bool hasEffectsGameObject;

	private bool effectsHaveBeenPlayed;

	private RaycastHit hit;

	private RaycastHit[] collidersHit = new RaycastHit[20];

	private ItemStates currentItemState;

	private ItemStates prevItemState;

	private int index;

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		hasEffectsGameObject = effectsGameObject != null;
		effectsHaveBeenPlayed = false;
	}

	protected override void Start()
	{
		base.Start();
		itemState = ItemStates.State0;
		prevItemState = ItemStates.State0;
		InitToDefault();
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
		InitToDefault();
		itemState = ItemStates.State0;
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (itemState == ItemStates.State0)
		{
			return false;
		}
		if (InHand())
		{
			return false;
		}
		return true;
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		base.OnGrab(pointGrabbed, grabbingHand);
		OnGeodeGrabbed?.Invoke(this);
	}

	private void InitToDefault()
	{
		cooldownRemaining = 0f;
		effectsHaveBeenPlayed = false;
		if (hasEffectsGameObject)
		{
			effectsGameObject.SetActive(value: false);
		}
		geodeFullMesh.SetActive(value: true);
		for (int i = 0; i < geodeCrackedMeshes.Length; i++)
		{
			geodeCrackedMeshes[i].SetActive(value: false);
		}
		hitLastFrame = false;
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		if (itemState == ItemStates.State1)
		{
			cooldownRemaining -= Time.deltaTime;
			if (cooldownRemaining <= 0f)
			{
				itemState = ItemStates.State0;
				OnItemStateChanged();
			}
		}
		else if (!(velocityEstimator.linearVelocity.magnitude < minHitVelocity))
		{
			if (InHand())
			{
				int num = Physics.SphereCastNonAlloc(geodeFullMesh.transform.position, sphereRayRadius * Mathf.Abs(geodeFullMesh.transform.lossyScale.x), geodeFullMesh.transform.TransformDirection(UnityEngine.Vector3.forward), collidersHit, rayCastMaxDistance, collisionLayerMask, QueryTriggerInteraction.Collide);
				hitLastFrame = num > 0;
			}
			if (hitLastFrame && GorillaParent.hasInstance)
			{
				OnGeodeCracked?.Invoke(this);
				itemState = ItemStates.State1;
				cooldownRemaining = cooldown;
				index = (randomizeGeode ? RandomPickCrackedGeode() : 0);
			}
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		currentItemState = itemState;
		if (currentItemState != prevItemState)
		{
			OnItemStateChanged();
		}
		prevItemState = currentItemState;
	}

	private void OnItemStateChanged()
	{
		if (itemState == ItemStates.State0)
		{
			InitToDefault();
			return;
		}
		geodeFullMesh.SetActive(value: false);
		for (int i = 0; i < geodeCrackedMeshes.Length; i++)
		{
			geodeCrackedMeshes[i].SetActive(i == index);
		}
		if (NetworkSystem.Instance.InRoom && GorillaGameManager.instance != null && !effectsHaveBeenPlayed && VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.LocalPlayer, out var playerRig))
		{
			playerRig.Rig.netView.SendRPC("RPC_PlayGeodeEffect", RpcTarget.All, geodeFullMesh.transform.position);
			effectsHaveBeenPlayed = true;
		}
		if (!NetworkSystem.Instance.InRoom && !effectsHaveBeenPlayed)
		{
			if ((bool)audioSource)
			{
				audioSource.GTPlay();
			}
			effectsHaveBeenPlayed = true;
		}
	}

	private int RandomPickCrackedGeode()
	{
		return UnityEngine.Random.Range(0, geodeCrackedMeshes.Length);
	}
}
public class HitChecker : MonoBehaviour
{
	public static void CheckHandHit(ref int collidersHitCount, LayerMask layerMask, float sphereRadius, ref RaycastHit nullHit, ref RaycastHit[] raycastHits, ref List<RaycastHit> raycastHitList, ref UnityEngine.Vector3 spherecastSweep, ref GorillaTriggerColliderHandIndicator handIndicator)
	{
		spherecastSweep = handIndicator.transform.position - handIndicator.lastPosition;
		if (spherecastSweep.magnitude < 0.0001f)
		{
			spherecastSweep = UnityEngine.Vector3.up * 0.0001f;
		}
		for (int i = 0; i < raycastHits.Length; i++)
		{
			raycastHits[i] = nullHit;
		}
		collidersHitCount = Physics.SphereCastNonAlloc(handIndicator.lastPosition, sphereRadius, spherecastSweep.normalized, raycastHits, spherecastSweep.magnitude, layerMask, QueryTriggerInteraction.Collide);
		if (collidersHitCount <= 0)
		{
			return;
		}
		raycastHitList.Clear();
		for (int j = 0; j < raycastHits.Length; j++)
		{
			if (raycastHits[j].collider != null)
			{
				raycastHitList.Add(raycastHits[j]);
			}
		}
	}

	public static bool CheckHandIn(ref bool anyHit, ref Collider[] colliderHit, float sphereRadius, int layerMask, ref GorillaTriggerColliderHandIndicator handIndicator, ref List<Collider> collidersToBeIn)
	{
		anyHit = Physics.OverlapSphereNonAlloc(handIndicator.transform.position, sphereRadius, colliderHit, layerMask, QueryTriggerInteraction.Collide) > 0;
		if (anyHit)
		{
			anyHit = false;
			for (int i = 0; i < colliderHit.Length; i++)
			{
				if (collidersToBeIn.Contains(colliderHit[i]))
				{
					anyHit = true;
					break;
				}
			}
		}
		return anyHit;
	}

	public static int RayCastHitCompare(RaycastHit a, RaycastHit b)
	{
		if (a.distance < b.distance)
		{
			return -1;
		}
		if (a.distance == b.distance)
		{
			return 0;
		}
		return 1;
	}
}
