public class OwlLook : MonoBehaviour
{
	public Transform head;

	public Transform lookTarget;

	public Transform neck;

	public float lookRadius = 0.5f;

	public Collider[] overlapColliders;

	public VRRig[] rigs = new VRRig[20];

	public VRRig[] overlapRigs;

	public float rotSpeed = 1f;

	public float lookAtAngleDegrees = 60f;

	public float maxNeckY;

	public float minNeckY;

	public VRRig myRig;

	private void Awake()
	{
		overlapRigs = new VRRig[20];
		if (myRig == null)
		{
			myRig = GetComponentInParent<VRRig>();
		}
	}

	private void LateUpdate()
	{
		if (NetworkSystem.Instance.InRoom)
		{
			if (rigs.Length != NetworkSystem.Instance.RoomPlayerCount)
			{
				rigs = VRRigCache.Instance.GetAllRigs();
			}
		}
		else if (rigs.Length != 1)
		{
			rigs = new VRRig[1];
			rigs[0] = VRRig.LocalRig;
		}
		float num = -1f;
		float num2 = Mathf.Cos(lookAtAngleDegrees / 180f * MathF.PI);
		int num3 = 0;
		for (int i = 0; i < rigs.Length; i++)
		{
			if (rigs[i] == myRig)
			{
				continue;
			}
			UnityEngine.Vector3 vector = rigs[i].tagSound.transform.position - base.transform.position;
			if (!(vector.magnitude > lookRadius))
			{
				float num4 = UnityEngine.Vector3.Dot(-base.transform.up, vector.normalized);
				if (num4 > num2)
				{
					overlapRigs[num3++] = rigs[i];
				}
			}
		}
		lookTarget = null;
		for (int j = 0; j < num3; j++)
		{
			UnityEngine.Vector3 vector = (overlapRigs[j].tagSound.transform.position - base.transform.position).normalized;
			float num4 = UnityEngine.Vector3.Dot(base.transform.forward, vector);
			if (num4 > num)
			{
				num = num4;
				lookTarget = overlapRigs[j].tagSound.transform;
			}
		}
		UnityEngine.Vector3 direction = neck.forward;
		if (lookTarget != null)
		{
			direction = (lookTarget.position - head.position).normalized;
		}
		UnityEngine.Vector3 vector2 = neck.InverseTransformDirection(direction);
		vector2.y = Mathf.Clamp(vector2.y, minNeckY, maxNeckY);
		direction = neck.TransformDirection(vector2.normalized);
		UnityEngine.Vector3 forward = UnityEngine.Vector3.RotateTowards(head.forward, direction, rotSpeed * (MathF.PI / 180f) * Time.deltaTime, 0f);
		head.rotation = UnityEngine.Quaternion.LookRotation(forward, neck.up);
	}
}
public class PlantableObject : TransferrableObject
{
	public enum AppliedColors
	{
		None,
		Red,
		Green,
		Blue,
		Black
	}

	public PlantablePoint point;

	public float respawnAfterDuration;

	private float respawnAtTimestamp;

	public SkinnedMeshRenderer flagRenderer;

	private MaterialPropertyBlock materialPropertyBlock;

	[HideInInspector]
	[SerializeReference]
	private Color _colorR;

	[HideInInspector]
	[SerializeReference]
	private Color _colorG;

	public Transform flagTip;

	public AppliedColors[] dippedColors = new AppliedColors[20];

	public int currentDipIndex;

	public Color colorR
	{
		get
		{
			return _colorR;
		}
		set
		{
			_colorR = value;
			AssureShaderStuff();
		}
	}

	public Color colorG
	{
		get
		{
			return _colorG;
		}
		set
		{
			_colorG = value;
			AssureShaderStuff();
		}
	}

	public bool planted { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		materialPropertyBlock = new MaterialPropertyBlock();
	}

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		materialPropertyBlock.SetColor(ShaderProps._ColorR, _colorR);
		flagRenderer.material = flagRenderer.sharedMaterial;
		flagRenderer.SetPropertyBlock(materialPropertyBlock);
		dippedColors = new AppliedColors[20];
	}

	private void AssureShaderStuff()
	{
		if ((bool)flagRenderer)
		{
			if (materialPropertyBlock == null)
			{
				materialPropertyBlock = new MaterialPropertyBlock();
			}
			try
			{
				materialPropertyBlock.SetColor(ShaderProps._ColorR, _colorR);
				materialPropertyBlock.SetColor(ShaderProps._ColorG, _colorG);
			}
			catch
			{
				materialPropertyBlock = new MaterialPropertyBlock();
				materialPropertyBlock.SetColor(ShaderProps._ColorR, _colorR);
				materialPropertyBlock.SetColor(ShaderProps._ColorG, _colorG);
			}
			flagRenderer.material = flagRenderer.sharedMaterial;
			flagRenderer.SetPropertyBlock(materialPropertyBlock);
		}
	}

	public void SetPlanted(bool newPlanted)
	{
		if (planted == newPlanted)
		{
			return;
		}
		if (newPlanted)
		{
			if (!rigidbodyInstance.isKinematic)
			{
				rigidbodyInstance.isKinematic = true;
			}
			respawnAtTimestamp = Time.time + respawnAfterDuration;
		}
		else
		{
			respawnAtTimestamp = 0f;
		}
		planted = newPlanted;
	}

	private void AddRed()
	{
		AddColor(AppliedColors.Red);
	}

	private void AddGreen()
	{
		AddColor(AppliedColors.Blue);
	}

	private void AddBlue()
	{
		AddColor(AppliedColors.Green);
	}

	private void AddBlack()
	{
		AddColor(AppliedColors.Black);
	}

	public void AddColor(AppliedColors color)
	{
		dippedColors[currentDipIndex] = color;
		currentDipIndex++;
		if (currentDipIndex >= dippedColors.Length)
		{
			currentDipIndex = 0;
		}
		UpdateDisplayedDippedColor();
	}

	public void ClearColors()
	{
		for (int i = 0; i < dippedColors.Length; i++)
		{
			dippedColors[i] = AppliedColors.None;
		}
		currentDipIndex = 0;
		UpdateDisplayedDippedColor();
	}

	public Color CalculateOutputColor()
	{
		Color black = Color.black;
		int num = 0;
		int num2 = 0;
		AppliedColors[] array = dippedColors;
		for (int i = 0; i < array.Length; i++)
		{
			switch (array[i])
			{
			case AppliedColors.Red:
				black += Color.red;
				num2++;
				continue;
			case AppliedColors.Green:
				black += Color.green;
				num2++;
				continue;
			case AppliedColors.Blue:
				black += Color.blue;
				num2++;
				continue;
			case AppliedColors.Black:
				num++;
				num2++;
				continue;
			default:
				continue;
			case AppliedColors.None:
				break;
			}
			break;
		}
		if (black == Color.black && num == 0)
		{
			return Color.white;
		}
		float num3 = Mathf.Max(black.r, black.g, black.b);
		if (num3 == 0f)
		{
			return Color.black;
		}
		black /= num3;
		float num4 = (float)num / (float)num2;
		if (num4 > 0f)
		{
			black *= 1f - num4;
		}
		return black;
	}

	public void UpdateDisplayedDippedColor()
	{
		colorR = CalculateOutputColor();
	}

	public override void DropItem()
	{
		base.DropItem();
		if (itemState == ItemStates.State1 && !rigidbodyInstance.isKinematic)
		{
			rigidbodyInstance.isKinematic = true;
		}
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		itemState = ((!planted) ? ItemStates.State0 : ItemStates.State1);
		if (respawnAtTimestamp != 0f && Time.time > respawnAtTimestamp)
		{
			respawnAtTimestamp = 0f;
			ResetToHome();
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		if (itemState == ItemStates.State1 && !rigidbodyInstance.isKinematic)
		{
			rigidbodyInstance.isKinematic = true;
		}
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		base.OnGrab(pointGrabbed, grabbingHand);
	}

	public override bool ShouldBeKinematic()
	{
		if (base.ShouldBeKinematic())
		{
			return true;
		}
		if (itemState == ItemStates.State1)
		{
			return true;
		}
		return false;
	}

	public override void OnOwnershipTransferred(NetPlayer toPlayer, NetPlayer fromPlayer)
	{
		base.OnOwnershipTransferred(toPlayer, fromPlayer);
		if (toPlayer == null)
		{
			return;
		}
		if (toPlayer.IsLocal && itemState == ItemStates.State1)
		{
			respawnAtTimestamp = Time.time + respawnAfterDuration;
		}
		GorillaGameManager.OnInstanceReady(delegate
		{
			VRRig vRRig = GorillaGameManager.instance.FindPlayerVRRig(toPlayer);
			if (!(vRRig == null))
			{
				vRRig.OnColorInitialized(delegate(Color color1)
				{
					colorG = color1;
				});
			}
		});
	}
}
public class TransferrableBall : TransferrableObject
{
	[Header("Transferrable Ball")]
	public float ballRadius = 0.1f;

	public float depenetrationSpeed = 5f;

	[Range(0f, 1f)]
	public float hitSpeedThreshold = 0.8f;

	public float maxHitSpeed = 10f;

	public UnityEngine.Vector2 hitSpeedToHitMultiplierMinMax = UnityEngine.Vector2.one;

	public AnimationCurve hitMultiplierCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	public float hitTorqueMultiplier = 0.5f;

	public float reflectOffHandAmount = 0.5f;

	public float minHitSpeedThreshold = 0.2f;

	public float surfaceGripDistance = 0.02f;

	public UnityEngine.Vector2 reflectOffHandSpeedInputMinMax = UnityEngine.Vector2.one;

	public UnityEngine.Vector2 reflectOffHandAmountOutputMinMax = UnityEngine.Vector2.one;

	public SoundBankPlayer hitSoundBank;

	public UnityEngine.Vector2 hitSpeedToAudioMinMax = UnityEngine.Vector2.one;

	public float handHitAudioMultiplier = 2f;

	public UnityEngine.Vector2 hitSoundPitchMinMax = UnityEngine.Vector2.one;

	public UnityEngine.Vector2 hitSoundVolumeMinMax = UnityEngine.Vector2.one;

	public bool allowHeadButting = true;

	public float headButtRadius = 0.1f;

	public float headButtHitMultiplier = 1.5f;

	public float gravityCounterAmount;

	public bool debugDraw;

	private Dictionary<GorillaHandClimber, int> handClimberMap = new Dictionary<GorillaHandClimber, int>();

	private SphereCollider playerHeadCollider;

	private ContactPoint[] collisionContacts = new ContactPoint[8];

	private int collisionContactsCount;

	private float handRadius = 0.1f;

	private float depenetrationBias = 1f;

	private bool leftHandOverlapping;

	private bool rightHandOverlapping;

	private bool headOverlapping;

	private bool onGround;

	private ContactPoint groundContact;

	private bool applyFrictionHolding;

	private UnityEngine.Vector3 frictionHoldLocalPosLeft;

	private UnityEngine.Quaternion frictionHoldLocalRotLeft;

	private UnityEngine.Vector3 frictionHoldLocalPosRight;

	private UnityEngine.Quaternion frictionHoldLocalRotRight;

	private float hitSoundSpamLastHitTime;

	private int hitSoundSpamCount;

	private int hitSoundSpamLimit = 5;

	private float hitSoundSpamCooldownResetTime = 0.2f;

	private string gorillaHeadTriggerTag = "PlayerHeadTrigger";

	public override void TriggeredLateUpdate()
	{
		base.TriggeredLateUpdate();
		if (Time.time - hitSoundSpamLastHitTime > hitSoundSpamCooldownResetTime)
		{
			hitSoundSpamCount = 0;
		}
		bool flag = false;
		bool flag2 = false;
		float num = 1f;
		bool flag3 = leftHandOverlapping;
		bool flag4 = rightHandOverlapping;
		GTPlayer instance = GTPlayer.Instance;
		bool flag5 = false;
		foreach (KeyValuePair<GorillaHandClimber, int> item in handClimberMap)
		{
			if (item.Value <= 0)
			{
				continue;
			}
			flag2 = true;
			UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
			bool flag6 = item.Key.xrNode == XRNode.LeftHand;
			UnityEngine.Vector3 position = instance.GetHandFollower(flag6).position;
			UnityEngine.Quaternion rotation = instance.GetHandFollower(flag6).rotation;
			Transform handFollower = instance.GetHandFollower(flag6);
			UnityEngine.Vector3 hitPoint;
			UnityEngine.Vector3 hitNormal;
			float penetrationDist;
			if (flag6)
			{
				leftHandOverlapping = CheckCollisionWithHand(position, rotation, rotation * UnityEngine.Vector3.right, out hitPoint, out hitNormal, out penetrationDist);
				if (leftHandOverlapping)
				{
					vector = instance.GetHandVelocityTracker(flag6).GetAverageVelocity(worldSpace: true);
				}
				else if ((position - base.transform.position).sqrMagnitude > num * num)
				{
					handClimberMap[item.Key] = 0;
					continue;
				}
			}
			else
			{
				rightHandOverlapping = CheckCollisionWithHand(position, rotation, rotation * -UnityEngine.Vector3.right, out hitPoint, out hitNormal, out penetrationDist);
				if (rightHandOverlapping)
				{
					vector = instance.GetHandVelocityTracker(flag6).GetAverageVelocity(worldSpace: true);
				}
				else if ((position - base.transform.position).sqrMagnitude > num * num)
				{
					handClimberMap[item.Key] = 0;
					continue;
				}
			}
			if ((leftHandOverlapping || rightHandOverlapping) && (currentState == PositionState.None || currentState == PositionState.Dropped))
			{
				if (applyFrictionHolding)
				{
					if (flag6 && leftHandOverlapping)
					{
						if (!flag3)
						{
							UnityEngine.Vector3 normalized = (handFollower.position - base.transform.position).normalized;
							UnityEngine.Vector3 position2 = normalized * ballRadius + base.transform.position;
							frictionHoldLocalPosLeft = base.transform.InverseTransformPoint(position2);
							frictionHoldLocalRotLeft = UnityEngine.Quaternion.LookRotation(normalized, handFollower.forward);
						}
						UnityEngine.Vector3 vector2 = base.transform.TransformPoint(frictionHoldLocalPosLeft);
						frictionHoldLocalRotLeft = UnityEngine.Quaternion.LookRotation(vector2 - base.transform.position, handFollower.forward);
						if (debugDraw)
						{
							UnityEngine.Quaternion rotation2 = frictionHoldLocalRotLeft * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.right);
							DebugUtil.DrawRect(vector2, rotation2, new UnityEngine.Vector2(0.08f, 0.15f), Color.green, depthTest: false);
							UnityEngine.Vector3 normalized2 = (instance.GetHandFollower(flag6).position - base.transform.position).normalized;
							UnityEngine.Vector3 center = normalized2 * ballRadius + base.transform.position;
							UnityEngine.Quaternion rotation3 = UnityEngine.Quaternion.LookRotation(normalized2, handFollower.forward) * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.right);
							DebugUtil.DrawRect(center, rotation3, new UnityEngine.Vector2(0.08f, 0.15f), Color.yellow, depthTest: false);
						}
					}
					else if (!flag6 && rightHandOverlapping)
					{
						if (!flag4)
						{
							UnityEngine.Vector3 normalized3 = (handFollower.position - base.transform.position).normalized;
							UnityEngine.Vector3 position3 = normalized3 * ballRadius + base.transform.position;
							frictionHoldLocalPosRight = base.transform.InverseTransformPoint(position3);
							frictionHoldLocalRotRight = UnityEngine.Quaternion.LookRotation(normalized3, handFollower.forward);
						}
						UnityEngine.Vector3 vector3 = base.transform.TransformPoint(frictionHoldLocalPosRight);
						frictionHoldLocalRotRight = UnityEngine.Quaternion.LookRotation(vector3 - base.transform.position, handFollower.forward);
						if (debugDraw)
						{
							UnityEngine.Quaternion rotation4 = frictionHoldLocalRotRight * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.right);
							DebugUtil.DrawRect(vector3, rotation4, new UnityEngine.Vector2(0.08f, 0.15f), Color.green, depthTest: false);
							UnityEngine.Vector3 normalized4 = (handFollower.position - base.transform.position).normalized;
							UnityEngine.Vector3 center2 = normalized4 * ballRadius + base.transform.position;
							UnityEngine.Quaternion rotation5 = UnityEngine.Quaternion.LookRotation(normalized4, handFollower.forward) * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.right);
							DebugUtil.DrawRect(center2, rotation5, new UnityEngine.Vector2(0.08f, 0.15f), Color.yellow, depthTest: false);
						}
					}
				}
				bool flag7 = (flag6 && leftHandOverlapping && !flag3) || (!flag6 && rightHandOverlapping && !flag4);
				if (!flag5 && flag7)
				{
					UnityEngine.Vector3 position4 = handFollower.position;
					float magnitude = vector.magnitude;
					UnityEngine.Vector3 vector4 = vector / magnitude;
					UnityEngine.Vector3 vector5 = -(position4 - base.transform.position).normalized;
					UnityEngine.Vector3 hitDir = (vector4 + vector5) * 0.5f;
					flag5 = ApplyHit(position4, hitDir, magnitude);
				}
				if (!flag5)
				{
					UnityEngine.Vector3 position5 = handFollower.position;
					UnityEngine.Vector3 vector6 = position5 - base.transform.position;
					float magnitude2 = vector6.magnitude;
					float num2 = ballRadius - vector6.magnitude;
					if (num2 > 0f)
					{
						UnityEngine.Vector3 vector7 = -(vector6 / magnitude2) * num2;
						rigidbodyInstance.AddForce(-(vector6 / magnitude2) * depenetrationSpeed * Time.deltaTime * rigidbodyInstance.mass, ForceMode.Impulse);
						if (collisionContactsCount == 0)
						{
							rigidbodyInstance.MovePosition(base.transform.position + vector7 * depenetrationBias);
						}
						if (debugDraw)
						{
							DebugUtil.DrawLine(position5, position5 - vector7, Color.magenta, depthTest: false);
						}
					}
				}
				if (debugDraw)
				{
					DebugUtil.DrawSphere(hitPoint, 0.01f, 6, 6, Color.green, depthTest: true, DebugUtil.Style.SolidColor);
					DebugUtil.DrawArrow(hitPoint, hitPoint - hitNormal * 0.05f, 0.01f, Color.green);
				}
			}
			flag = flag || leftHandOverlapping || rightHandOverlapping;
		}
		bool flag8 = headOverlapping;
		headOverlapping = false;
		if (allowHeadButting && !flag5 && playerHeadCollider != null)
		{
			headOverlapping = CheckCollisionWithHead(playerHeadCollider, out var hitPoint2, out var _, out var _);
			UnityEngine.Vector3 averagedVelocity = instance.AveragedVelocity;
			float magnitude3 = averagedVelocity.magnitude;
			if (headOverlapping && !flag8 && (double)magnitude3 > 0.0001)
			{
				UnityEngine.Vector3 hitDir2 = averagedVelocity / magnitude3;
				flag5 = ApplyHit(hitPoint2, hitDir2, magnitude3 * headButtHitMultiplier);
			}
			else if ((playerHeadCollider.transform.position - base.transform.position).sqrMagnitude > num * num)
			{
				playerHeadCollider = null;
			}
		}
		if (debugDraw && onGround)
		{
			DebugUtil.DrawLine(groundContact.point, groundContact.point + groundContact.normal * 0.2f, Color.yellow, depthTest: false);
			DebugUtil.DrawRect(groundContact.point, UnityEngine.Quaternion.LookRotation(groundContact.normal) * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.right), UnityEngine.Vector2.one * 0.2f, Color.yellow, depthTest: false);
		}
		if (flag2 && debugDraw)
		{
			DebugUtil.DrawSphereTripleCircles(base.transform.position, ballRadius, 16, flag ? Color.green : Color.white);
			for (int i = 0; i < collisionContactsCount; i++)
			{
				ContactPoint contactPoint = collisionContacts[i];
				DebugUtil.DrawArrow(contactPoint.point, contactPoint.point + contactPoint.normal * 0.2f, 0.02f, Color.red, depthTest: false);
			}
		}
	}

	private void TakeOwnershipAndEnablePhysics()
	{
		currentState = PositionState.Dropped;
		rigidbodyInstance.isKinematic = false;
		if (worldShareableInstance != null)
		{
			if (!worldShareableInstance.guard.isTrulyMine)
			{
				worldShareableInstance.guard.RequestOwnershipImmediately(delegate
				{
				});
			}
			worldShareableInstance.transferableObjectState = currentState;
		}
	}

	private bool CheckCollisionWithHand(UnityEngine.Vector3 handCenter, UnityEngine.Quaternion handRotation, UnityEngine.Vector3 palmForward, out UnityEngine.Vector3 hitPoint, out UnityEngine.Vector3 hitNormal, out float penetrationDist)
	{
		UnityEngine.Vector3 position = base.transform.position;
		bool flag = false;
		hitPoint = position;
		hitNormal = UnityEngine.Vector3.forward;
		penetrationDist = 0f;
		UnityEngine.Vector3 lhs = position - handCenter;
		UnityEngine.Vector3 vector = position - UnityEngine.Vector3.Dot(lhs, palmForward) * palmForward;
		UnityEngine.Vector3 vector2 = vector;
		if ((vector - handCenter).sqrMagnitude > handRadius * handRadius)
		{
			vector2 = handCenter + (vector - handCenter).normalized * handRadius;
		}
		if ((vector2 - position).sqrMagnitude < ballRadius * ballRadius)
		{
			flag = true;
			hitNormal = (position - vector2).normalized;
			hitPoint = position - hitNormal * ballRadius;
			penetrationDist = ballRadius - (vector2 - position).magnitude;
		}
		if (debugDraw)
		{
			Color color = (flag ? Color.green : Color.white);
			DebugUtil.DrawCircle(handCenter, handRotation * UnityEngine.Quaternion.AngleAxis(90f, UnityEngine.Vector3.forward), handRadius, 16, color);
			DebugUtil.DrawArrow(handCenter, handCenter + palmForward * 0.05f, 0.01f, color);
		}
		return flag;
	}

	private bool CheckCollisionWithHead(SphereCollider headCollider, out UnityEngine.Vector3 hitPoint, out UnityEngine.Vector3 hitNormal, out float penetrationDist)
	{
		UnityEngine.Vector3 vector = base.transform.position - headCollider.transform.position;
		float sqrMagnitude = vector.sqrMagnitude;
		float num = ballRadius + headButtRadius;
		if (sqrMagnitude < num * num)
		{
			float num2 = Mathf.Sqrt(sqrMagnitude);
			hitNormal = vector / num2;
			penetrationDist = num - num2;
			hitPoint = headCollider.transform.position + hitNormal * headButtRadius;
			return true;
		}
		hitNormal = UnityEngine.Vector3.forward;
		hitPoint = UnityEngine.Vector3.zero;
		penetrationDist = 0f;
		return false;
	}

	private bool ApplyHit(UnityEngine.Vector3 hitPoint, UnityEngine.Vector3 hitDir, float hitSpeed)
	{
		bool result = false;
		TakeOwnershipAndEnablePhysics();
		float num = 0f;
		UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
		if (hitSpeed > 0.0001f)
		{
			float num2 = UnityEngine.Vector3.Dot(rigidbodyInstance.linearVelocity, hitDir);
			float num3 = hitSpeed - num2;
			if (num3 > 0f)
			{
				num = num3;
				vector = num * hitDir;
			}
		}
		UnityEngine.Vector3 normalized = (hitPoint - base.transform.position).normalized;
		float num4 = UnityEngine.Vector3.Dot(rigidbodyInstance.linearVelocity, -normalized);
		if (num4 < 0f)
		{
			float num5 = Mathf.Lerp(reflectOffHandAmountOutputMinMax.x, reflectOffHandAmountOutputMinMax.y, Mathf.InverseLerp(reflectOffHandSpeedInputMinMax.x, reflectOffHandSpeedInputMinMax.y, num4));
			rigidbodyInstance.linearVelocity = num5 * UnityEngine.Vector3.Reflect(rigidbodyInstance.linearVelocity, -normalized);
		}
		if (num > hitSpeedThreshold)
		{
			result = true;
			float num6 = hitMultiplierCurve.Evaluate(Mathf.InverseLerp(hitSpeedToHitMultiplierMinMax.x, hitSpeedToHitMultiplierMinMax.y, num));
			if (onGround)
			{
				if (UnityEngine.Vector3.Dot(vector, groundContact.normal) < 0f)
				{
					vector = UnityEngine.Vector3.Reflect(vector, groundContact.normal);
				}
				UnityEngine.Vector3 vector2 = vector / num;
				if (UnityEngine.Vector3.Dot(vector2, groundContact.normal) < 0.707f)
				{
					vector = num * (vector2 + groundContact.normal) * 0.5f;
				}
			}
			rigidbodyInstance.AddForce(UnityEngine.Vector3.ClampMagnitude(vector * num6, maxHitSpeed) * rigidbodyInstance.mass, ForceMode.Impulse);
			UnityEngine.Vector3 rhs = hitDir * hitSpeed - UnityEngine.Vector3.Dot(hitDir * hitSpeed, normalized) * normalized;
			UnityEngine.Vector3 normalized2 = UnityEngine.Vector3.Cross(normalized, rhs).normalized;
			float num7 = UnityEngine.Vector3.Dot(rigidbodyInstance.angularVelocity, normalized2);
			float num8 = rhs.magnitude / ballRadius - num7;
			if (num8 > 0f)
			{
				rigidbodyInstance.AddTorque(num6 * hitTorqueMultiplier * num8 * normalized2, ForceMode.VelocityChange);
			}
		}
		PlayHitSound(num * handHitAudioMultiplier);
		return result;
	}

	private void PlayHitSound(float hitSpeed)
	{
		float t = Mathf.InverseLerp(hitSpeedToAudioMinMax.x, hitSpeedToAudioMinMax.y, hitSpeed);
		float value = Mathf.Lerp(hitSoundVolumeMinMax.x, hitSoundVolumeMinMax.y, t);
		float value2 = Mathf.Lerp(hitSoundPitchMinMax.x, hitSoundPitchMinMax.y, t);
		if (hitSoundBank != null && hitSoundSpamCount < hitSoundSpamLimit)
		{
			hitSoundSpamLastHitTime = Time.time;
			hitSoundSpamCount++;
			hitSoundBank.Play(value, value2);
		}
	}

	private void FixedUpdate()
	{
		collisionContactsCount = 0;
		onGround = false;
		rigidbodyInstance.AddForce(-Physics.gravity * gravityCounterAmount * rigidbodyInstance.mass, ForceMode.Force);
	}

	private void OnTriggerEnter(Collider other)
	{
		GorillaHandClimber component = other.GetComponent<GorillaHandClimber>();
		if (component != null)
		{
			if (handClimberMap.TryGetValue(component, out var value))
			{
				handClimberMap[component] = Mathf.Min(value + 1, 2);
			}
			else
			{
				handClimberMap.Add(component, 1);
			}
		}
		else if (other.CompareTag(gorillaHeadTriggerTag))
		{
			playerHeadCollider = other as SphereCollider;
		}
	}

	private void OnTriggerExit(Collider other)
	{
		GorillaHandClimber component = other.GetComponent<GorillaHandClimber>();
		if (component != null)
		{
			if (handClimberMap.TryGetValue(component, out var value))
			{
				handClimberMap[component] = Mathf.Max(value - 1, 0);
			}
		}
		else if (other.CompareTag(gorillaHeadTriggerTag))
		{
			playerHeadCollider = null;
		}
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		PlayHitSound(collision.relativeVelocity.magnitude);
	}

	private void OnCollisionStay(UnityEngine.Collision collision)
	{
		collisionContactsCount = collision.GetContacts(collisionContacts);
		float num = -1f;
		for (int i = 0; i < collisionContactsCount; i++)
		{
			float num2 = UnityEngine.Vector3.Dot(collisionContacts[i].normal, UnityEngine.Vector3.up);
			if (num2 > num)
			{
				groundContact = collisionContacts[i];
				num = num2;
			}
		}
		float num3 = 0.5f;
		onGround = num > num3;
	}
}
[Serializable]
public class AdvancedItemState
{
	[Serializable]
	public class PreData
	{
		public float distAlongLine;

		public PointType pointType;
	}

	public enum PointType
	{
		Standard,
		DistanceBased
	}

	private int _encodedValue;

	public UnityEngine.Vector2 angleVectorWhereUpIsStandard;

	public UnityEngine.Quaternion deltaRotation;

	public int index;

	public PreData preData;

	public LimitAxis limitAxis;

	public bool reverseGrip;

	public float angle;

	private float EncodedDeltaRotation => GetEncodedDeltaRotation();

	public void Encode()
	{
		_encodedValue = EncodeData();
	}

	public void Decode()
	{
		AdvancedItemState advancedItemState = DecodeData(_encodedValue);
		index = advancedItemState.index;
		preData = advancedItemState.preData;
		limitAxis = advancedItemState.limitAxis;
		reverseGrip = advancedItemState.reverseGrip;
		angle = advancedItemState.angle;
	}

	public UnityEngine.Quaternion GetQuaternion()
	{
		_ = UnityEngine.Vector3.one;
		if (reverseGrip)
		{
			switch (limitAxis)
			{
			case LimitAxis.NoMovement:
				return UnityEngine.Quaternion.identity;
			case LimitAxis.YAxis:
				return UnityEngine.Quaternion.identity;
			default:
				throw new ArgumentOutOfRangeException();
			case LimitAxis.XAxis:
			case LimitAxis.ZAxis:
				break;
			}
		}
		return UnityEngine.Quaternion.identity;
	}

	public (int grabPointIndex, float YRotation, float XRotation, float ZRotation) DecodeAdvancedItemState(int encodedValue)
	{
		int item = (encodedValue >> 21) & 0xFF;
		float item2 = (float)((encodedValue >> 14) & 0x7F) / 128f * 360f;
		float item3 = (float)((encodedValue >> 7) & 0x7F) / 128f * 360f;
		float item4 = (float)(encodedValue & 0x7F) / 128f * 360f;
		return (grabPointIndex: item, YRotation: item2, XRotation: item3, ZRotation: item4);
	}

	public float GetEncodedDeltaRotation()
	{
		return Mathf.Abs(Mathf.Atan2(angleVectorWhereUpIsStandard.x, angleVectorWhereUpIsStandard.y)) / MathF.PI;
	}

	public void DecodeDeltaRotation(float encodedDelta, bool isFlipped)
	{
		float f = encodedDelta * MathF.PI;
		if (isFlipped)
		{
			angleVectorWhereUpIsStandard = new UnityEngine.Vector2(0f - Mathf.Sin(f), Mathf.Cos(f));
		}
		else
		{
			angleVectorWhereUpIsStandard = new UnityEngine.Vector2(Mathf.Sin(f), Mathf.Cos(f));
		}
		switch (limitAxis)
		{
		case LimitAxis.YAxis:
		{
			UnityEngine.Vector3 forward = new UnityEngine.Vector3(angleVectorWhereUpIsStandard.x, 0f, angleVectorWhereUpIsStandard.y);
			UnityEngine.Vector3 upwards = (reverseGrip ? UnityEngine.Vector3.down : UnityEngine.Vector3.up);
			deltaRotation = UnityEngine.Quaternion.LookRotation(forward, upwards);
			break;
		}
		default:
			throw new ArgumentOutOfRangeException();
		case LimitAxis.NoMovement:
		case LimitAxis.XAxis:
		case LimitAxis.ZAxis:
			break;
		}
	}

	public int EncodeData()
	{
		int num = 0;
		if ((index >= 32) | (index < 0))
		{
			throw new ArgumentOutOfRangeException($"Index is invalid {index}");
		}
		num |= index << 25;
		PointType pointType = preData.pointType;
		num |= (int)(pointType & (PointType)7) << 22;
		num |= (int)limitAxis << 19;
		num |= (reverseGrip ? 1 : 0) << 18;
		bool flag = angleVectorWhereUpIsStandard.x < 0f;
		switch (pointType)
		{
		case PointType.Standard:
		{
			int num4 = (int)(GetEncodedDeltaRotation() * 65536f) & 0xFFFF;
			num |= (flag ? 1 : 0) << 17;
			return num | (num4 << 1);
		}
		case PointType.DistanceBased:
		{
			int num2 = (int)(GetEncodedDeltaRotation() * 512f) & 0x1FF;
			num |= (flag ? 1 : 0) << 17;
			num |= num2 << 9;
			int num3 = (int)(preData.distAlongLine * 256f) & 0xFF;
			return num | num3;
		}
		default:
			throw new ArgumentOutOfRangeException();
		}
	}

	public AdvancedItemState DecodeData(int encoded)
	{
		AdvancedItemState advancedItemState = new AdvancedItemState();
		advancedItemState.index = (encoded >> 25) & 0x1F;
		advancedItemState.limitAxis = (LimitAxis)((encoded >> 19) & 7);
		advancedItemState.reverseGrip = ((encoded >> 18) & 1) == 1;
		PointType pointType = (PointType)((encoded >> 22) & 7);
		switch (pointType)
		{
		case PointType.Standard:
			advancedItemState.preData = new PreData
			{
				pointType = pointType
			};
			DecodeDeltaRotation((float)((encoded >> 1) & 0xFFFF) / 65536f, ((encoded >> 17) & 1) > 0);
			break;
		case PointType.DistanceBased:
			advancedItemState.preData = new PreData
			{
				pointType = pointType,
				distAlongLine = (float)(encoded & 0xFF) / 256f
			};
			DecodeDeltaRotation((float)((encoded >> 9) & 0x1FF) / 512f, ((encoded >> 17) & 1) > 0);
			break;
		default:
			throw new ArgumentOutOfRangeException();
		}
		return advancedItemState;
	}
}
public enum GrabPointType
{
	SinglePoint,
	Line
}
public enum LimitAxis
{
	NoMovement,
	YAxis,
	XAxis,
	ZAxis
}
[Serializable]
public class SubGrabPoint
{
	[FormerlySerializedAs("transform")]
	public Transform gripPoint;

	public LimitAxis limitAxis;

	public bool allowReverseGrip;

	private UnityEngine.Vector3 gripPoint_AdvOriginLocal;

	private UnityEngine.Vector3 gripPointOffset_AdvOriginLocal;

	public UnityEngine.Quaternion gripRotation_AdvOriginLocal;

	public UnityEngine.Quaternion advAnchor_ParentAnchorLocal;

	public UnityEngine.Quaternion gripRotation_ParentAnchorLocal;

	public UnityEngine.Matrix4x4 gripPointLocalToAdvOriginLocal;

	public virtual UnityEngine.Matrix4x4 GetTransformation_GripPointLocalToAdvOriginLocal(AdvancedItemState.PreData advancedItemState, SlotTransformOverride slotTransformOverride)
	{
		return gripPointLocalToAdvOriginLocal;
	}

	public virtual UnityEngine.Quaternion GetRotationRelativeToObjectAnchor(AdvancedItemState advancedItemState, SlotTransformOverride slotTransformOverride)
	{
		return gripRotation_ParentAnchorLocal;
	}

	public virtual UnityEngine.Vector3 GetGrabPositionRelativeToGrabPointOrigin(AdvancedItemState advancedItemState, SlotTransformOverride slotTransformOverride)
	{
		return gripPoint_AdvOriginLocal;
	}

	public virtual void InitializePoints(Transform anchor, Transform grabPointAnchor, Transform advancedGrabPointOrigin)
	{
		if (!(gripPoint == null))
		{
			gripPoint_AdvOriginLocal = advancedGrabPointOrigin.InverseTransformPoint(gripPoint.position);
			gripRotation_AdvOriginLocal = UnityEngine.Quaternion.Inverse(advancedGrabPointOrigin.rotation) * gripPoint.rotation;
			advAnchor_ParentAnchorLocal = UnityEngine.Quaternion.Inverse(anchor.rotation) * grabPointAnchor.rotation;
			gripRotation_ParentAnchorLocal = UnityEngine.Quaternion.Inverse(anchor.rotation) * gripPoint.rotation;
			gripPointLocalToAdvOriginLocal = advancedGrabPointOrigin.worldToLocalMatrix * gripPoint.localToWorldMatrix;
		}
	}

	public UnityEngine.Vector3 GetPositionOnObject(Transform transferableObject, SlotTransformOverride slotTransformOverride)
	{
		return transferableObject.TransformPoint(gripPoint_AdvOriginLocal);
	}

	public virtual UnityEngine.Matrix4x4 GetTransformFromPositionState(AdvancedItemState advancedItemState, SlotTransformOverride slotTransformOverride, Transform targetDockXf)
	{
		UnityEngine.Quaternion q = advancedItemState.deltaRotation;
		if (!q.IsValid())
		{
			q = UnityEngine.Quaternion.identity;
		}
		UnityEngine.Matrix4x4 matrix4x = UnityEngine.Matrix4x4.TRS(UnityEngine.Vector3.zero, q, UnityEngine.Vector3.one);
		UnityEngine.Matrix4x4 matrix4x2 = GetTransformation_GripPointLocalToAdvOriginLocal(advancedItemState.preData, slotTransformOverride) * matrix4x.inverse;
		UnityEngine.Matrix4x4 matrix4x3 = slotTransformOverride.AdvAnchorLocalToAdvOriginLocal * matrix4x2.inverse;
		return slotTransformOverride.AdvOriginLocalToParentAnchorLocal * matrix4x3;
	}

	public AdvancedItemState GetAdvancedItemStateFromHand(Transform objectTransform, Transform handTransform, Transform targetDock, SlotTransformOverride slotTransformOverride)
	{
		AdvancedItemState.PreData preData = GetPreData(objectTransform, handTransform, targetDock, slotTransformOverride);
		UnityEngine.Matrix4x4 matrix4x = targetDock.localToWorldMatrix * slotTransformOverride.AdvOriginLocalToParentAnchorLocal * slotTransformOverride.AdvAnchorLocalToAdvOriginLocal;
		UnityEngine.Matrix4x4 matrix4x2 = objectTransform.localToWorldMatrix * GetTransformation_GripPointLocalToAdvOriginLocal(preData, slotTransformOverride);
		UnityEngine.Quaternion quaternion2 = (matrix4x.inverse * matrix4x2).rotation;
		UnityEngine.Vector3 vector = quaternion2 * UnityEngine.Vector3.up;
		UnityEngine.Vector3 vector2 = quaternion2 * UnityEngine.Vector3.right;
		UnityEngine.Vector3 rhs = quaternion2 * UnityEngine.Vector3.forward;
		bool reverseGrip = false;
		UnityEngine.Vector2 angleVectorWhereUpIsStandard = UnityEngine.Vector2.up;
		float angle = 0f;
		switch (limitAxis)
		{
		case LimitAxis.NoMovement:
			quaternion2 = UnityEngine.Quaternion.identity;
			break;
		case LimitAxis.YAxis:
			if (allowReverseGrip)
			{
				if (UnityEngine.Vector3.Dot(vector, UnityEngine.Vector3.up) < 0f)
				{
					UnityEngine.Debug.Log("Using Reverse Grip");
					reverseGrip = true;
					vector = UnityEngine.Vector3.down;
				}
				else
				{
					vector = UnityEngine.Vector3.up;
				}
			}
			else
			{
				vector = UnityEngine.Vector3.up;
			}
			vector2 = UnityEngine.Vector3.Cross(vector, rhs);
			rhs = UnityEngine.Vector3.Cross(vector2, vector);
			angleVectorWhereUpIsStandard = new UnityEngine.Vector2(rhs.z, rhs.x);
			quaternion2 = UnityEngine.Quaternion.LookRotation(rhs, vector);
			break;
		case LimitAxis.XAxis:
			vector2 = UnityEngine.Vector3.right;
			rhs = UnityEngine.Vector3.Cross(vector2, vector);
			vector = UnityEngine.Vector3.Cross(rhs, vector2);
			break;
		case LimitAxis.ZAxis:
			rhs = UnityEngine.Vector3.forward;
			vector2 = UnityEngine.Vector3.Cross(vector, rhs);
			vector = UnityEngine.Vector3.Cross(rhs, vector2);
			break;
		default:
			throw new ArgumentOutOfRangeException();
		}
		return new AdvancedItemState
		{
			preData = preData,
			limitAxis = limitAxis,
			angle = angle,
			reverseGrip = reverseGrip,
			angleVectorWhereUpIsStandard = angleVectorWhereUpIsStandard,
			deltaRotation = quaternion2
		};
	}

	public virtual AdvancedItemState.PreData GetPreData(Transform objectTransform, Transform handTransform, Transform targetDock, SlotTransformOverride slotTransformOverride)
	{
		return new AdvancedItemState.PreData
		{
			pointType = AdvancedItemState.PointType.Standard
		};
	}

	public virtual float EvaluateScore(Transform objectTransform, Transform handTransform, Transform targetDock)
	{
		UnityEngine.Vector3 vector = objectTransform.InverseTransformPoint(handTransform.position);
		float num = UnityEngine.Vector3.SqrMagnitude(gripPoint_AdvOriginLocal - vector);
		(UnityEngine.Quaternion.Inverse(objectTransform.rotation * gripRotation_AdvOriginLocal) * targetDock.rotation * advAnchor_ParentAnchorLocal).ToAngleAxis(out var angle, out var _);
		return num + Mathf.Abs(angle) * 0.0001f;
	}
}
[Serializable]
public class SubLineGrabPoint : SubGrabPoint
{
	public Transform startPoint;

	public Transform endPoint;

	public UnityEngine.Vector3 startPointRelativeToGrabPointOrigin;

	public UnityEngine.Vector3 endPointRelativeToGrabPointOrigin;

	public UnityEngine.Matrix4x4 startPointRelativeTransformToGrabPointOrigin;

	public UnityEngine.Matrix4x4 endPointRelativeTransformToGrabPointOrigin;

	public override UnityEngine.Matrix4x4 GetTransformation_GripPointLocalToAdvOriginLocal(AdvancedItemState.PreData advancedItemState, SlotTransformOverride slotTransformOverride)
	{
		float distAlongLine = advancedItemState.distAlongLine;
		UnityEngine.Vector3 pos = UnityEngine.Vector3.Lerp(startPointRelativeTransformToGrabPointOrigin.Position(), endPointRelativeTransformToGrabPointOrigin.Position(), distAlongLine);
		UnityEngine.Quaternion q = UnityEngine.Quaternion.Slerp(startPointRelativeTransformToGrabPointOrigin.rotation, endPointRelativeTransformToGrabPointOrigin.rotation, distAlongLine);
		return UnityEngine.Matrix4x4.TRS(pos, q, UnityEngine.Vector3.one);
	}

	public override void InitializePoints(Transform anchor, Transform grabPointAnchor, Transform advancedGrabPointOrigin)
	{
		base.InitializePoints(anchor, grabPointAnchor, advancedGrabPointOrigin);
		if (!(startPoint == null) && !(endPoint == null))
		{
			startPointRelativeToGrabPointOrigin = advancedGrabPointOrigin.InverseTransformPoint(startPoint.position);
			endPointRelativeToGrabPointOrigin = advancedGrabPointOrigin.InverseTransformPoint(endPoint.position);
			endPointRelativeTransformToGrabPointOrigin = advancedGrabPointOrigin.worldToLocalMatrix * endPoint.localToWorldMatrix;
			startPointRelativeTransformToGrabPointOrigin = advancedGrabPointOrigin.worldToLocalMatrix * startPoint.localToWorldMatrix;
		}
	}

	public override AdvancedItemState.PreData GetPreData(Transform objectTransform, Transform handTransform, Transform targetDock, SlotTransformOverride slotTransformOverride)
	{
		return new AdvancedItemState.PreData
		{
			distAlongLine = FindNearestFractionOnLine(objectTransform.TransformPoint(startPointRelativeToGrabPointOrigin), objectTransform.TransformPoint(endPointRelativeToGrabPointOrigin), handTransform.position),
			pointType = AdvancedItemState.PointType.DistanceBased
		};
		static float FindNearestFractionOnLine(UnityEngine.Vector3 origin, UnityEngine.Vector3 end, UnityEngine.Vector3 point)
		{
			UnityEngine.Vector3 rhs = end - origin;
			float magnitude = rhs.magnitude;
			rhs /= magnitude;
			return Mathf.Clamp01(UnityEngine.Vector3.Dot(point - origin, rhs) / magnitude);
		}
	}

	public override float EvaluateScore(Transform objectTransform, Transform handTransform, Transform targetDock)
	{
		float t = FindNearestFractionOnLine(objectTransform.TransformPoint(startPointRelativeToGrabPointOrigin), objectTransform.TransformPoint(endPointRelativeToGrabPointOrigin), handTransform.position);
		UnityEngine.Vector3 vector = UnityEngine.Vector3.Lerp(startPointRelativeTransformToGrabPointOrigin.Position(), endPointRelativeTransformToGrabPointOrigin.Position(), t);
		UnityEngine.Vector3 vector2 = objectTransform.InverseTransformPoint(handTransform.position);
		return UnityEngine.Vector3.SqrMagnitude(vector - vector2);
		static float FindNearestFractionOnLine(UnityEngine.Vector3 origin, UnityEngine.Vector3 end, UnityEngine.Vector3 point)
		{
			UnityEngine.Vector3 rhs = end - origin;
			float magnitude = rhs.magnitude;
			rhs /= magnitude;
			return Mathf.Clamp01(UnityEngine.Vector3.Dot(point - origin, rhs) / magnitude);
		}
	}
}
[Serializable]
public class SubSplineGrabPoint : SubLineGrabPoint
{
	public CatmullRomSpline spline;

	public List<UnityEngine.Vector3> controlPointsRelativeToGrabOrigin = new List<UnityEngine.Vector3>();

	public List<UnityEngine.Matrix4x4> controlPointsTransformsRelativeToGrabOrigin = new List<UnityEngine.Matrix4x4>();

	public override UnityEngine.Matrix4x4 GetTransformation_GripPointLocalToAdvOriginLocal(AdvancedItemState.PreData advancedItemState, SlotTransformOverride slotTransformOverride)
	{
		return CatmullRomSpline.Evaluate(controlPointsTransformsRelativeToGrabOrigin, advancedItemState.distAlongLine);
	}

	public override void InitializePoints(Transform anchor, Transform grabPointAnchor, Transform advancedGrabPointOrigin)
	{
		base.InitializePoints(anchor, grabPointAnchor, advancedGrabPointOrigin);
		controlPointsRelativeToGrabOrigin = new List<UnityEngine.Vector3>();
		Transform[] controlPointTransforms = spline.controlPointTransforms;
		foreach (Transform transform in controlPointTransforms)
		{
			controlPointsRelativeToGrabOrigin.Add(advancedGrabPointOrigin.InverseTransformPoint(transform.position));
			controlPointsTransformsRelativeToGrabOrigin.Add(advancedGrabPointOrigin.worldToLocalMatrix * transform.localToWorldMatrix);
		}
	}

	public override AdvancedItemState.PreData GetPreData(Transform objectTransform, Transform handTransform, Transform targetDock, SlotTransformOverride slotTransformOverride)
	{
		UnityEngine.Vector3 worldPoint = objectTransform.InverseTransformPoint(handTransform.position);
		UnityEngine.Vector3 linePoint;
		return new AdvancedItemState.PreData
		{
			distAlongLine = CatmullRomSpline.GetClosestEvaluationOnSpline(controlPointsRelativeToGrabOrigin, worldPoint, out linePoint),
			pointType = AdvancedItemState.PointType.DistanceBased
		};
	}

	public override float EvaluateScore(Transform objectTransform, Transform handTransform, Transform targetDock)
	{
		UnityEngine.Vector3 vector = objectTransform.InverseTransformPoint(handTransform.position);
		CatmullRomSpline.GetClosestEvaluationOnSpline(controlPointsRelativeToGrabOrigin, vector, out var linePoint);
		return UnityEngine.Vector3.SqrMagnitude(linePoint - vector);
	}
}
