[DefaultExecutionOrder(1549)]
public class TransferrableObjectManager : MonoBehaviour
{
	public static TransferrableObjectManager instance;

	public static bool hasInstance = false;

	public static readonly List<TransferrableObject> transObs = new List<TransferrableObject>(1024);

	protected void Awake()
	{
		if (hasInstance && instance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			SetInstance(this);
		}
	}

	protected void OnDestroy()
	{
		if (instance == this)
		{
			hasInstance = false;
			instance = null;
		}
	}

	protected void LateUpdate()
	{
		for (int i = 0; i < transObs.Count; i++)
		{
			transObs[i].TriggeredLateUpdate();
		}
	}

	private static void CreateManager()
	{
		if (!ApplicationQuittingState.IsQuitting)
		{
			SetInstance(new GameObject("TransferrableObjectManager").AddComponent<TransferrableObjectManager>());
		}
	}

	private static void SetInstance(TransferrableObjectManager manager)
	{
		instance = manager;
		hasInstance = true;
		if (UnityEngine.Application.isPlaying)
		{
			UnityEngine.Object.DontDestroyOnLoad(manager);
		}
	}

	public static void Register(TransferrableObject transOb)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (!transObs.Contains(transOb))
		{
			transObs.Add(transOb);
		}
	}

	public static void Unregister(TransferrableObject transOb)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (transObs.Contains(transOb))
		{
			transObs.Remove(transOb);
		}
	}
}
public class TransferrableObjectSyncedBool : TransferrableObject
{
	[SerializeField]
	private bool deprecatedWarning = true;

	[SerializeField]
	private UnityEvent OnItemStateSetTrue;

	[SerializeField]
	private UnityEvent OnItemStateSetFalse;

	internal override void OnEnable()
	{
		base.OnEnable();
		OnItemStateBoolFalse.AddListener(OnItemStateChanged);
		OnItemStateBoolTrue.AddListener(OnItemStateChanged);
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		OnItemStateBoolFalse.RemoveListener(OnItemStateChanged);
		OnItemStateBoolTrue.RemoveListener(OnItemStateChanged);
	}

	public void SetItemState(bool state)
	{
		SetItemStateBool(state);
	}

	public void ToggleItemState()
	{
		ToggleNetworkedItemStateBool();
	}

	private void OnItemStateChanged()
	{
		if (itemState == ItemStates.State0)
		{
			OnItemStateSetFalse?.Invoke();
		}
		else
		{
			OnItemStateSetTrue?.Invoke();
		}
	}
}
public class UmbrellaItem : TransferrableObject
{
	private enum UmbrellaStates
	{
		UmbrellaOpen = 1,
		UmbrellaClosed
	}

	[AssignInCorePrefab]
	public Transform[] umbrellaBones;

	[AssignInCorePrefab]
	public UnityEngine.Quaternion[] startingAngles;

	[AssignInCorePrefab]
	public UnityEngine.Quaternion[] endingAngles;

	[AssignInCorePrefab]
	[Tooltip("Assign to use the 'Generate Angles' button")]
	private UmbrellaItem umbrellaToCopy;

	[AssignInCorePrefab]
	public float lerpValue = 0.25f;

	[AssignInCorePrefab]
	public Collider umbrellaRainDestroyTrigger;

	[AssignInCorePrefab]
	public GameObject[] gameObjectsActivatedOnOpen;

	[AssignInCorePrefab]
	public ParticleSystem[] particlesEmitOnOpen;

	[GorillaSoundLookup]
	public int SoundIdOpen = 64;

	[GorillaSoundLookup]
	public int SoundIdClose = 65;

	private UmbrellaStates previousUmbrellaState = UmbrellaStates.UmbrellaOpen;

	protected override void Start()
	{
		base.Start();
		itemState = ItemStates.State1;
	}

	public override void OnActivate()
	{
		base.OnActivate();
		float hapticStrength = GorillaTagger.Instance.tapHapticStrength / 4f;
		float fixedDeltaTime = Time.fixedDeltaTime;
		float soundVolume = 0.08f;
		int num = -1;
		if (itemState == ItemStates.State1)
		{
			num = SoundIdOpen;
			itemState = ItemStates.State0;
			BetterDayNightManager.instance.collidersToAddToWeatherSystems.Add(umbrellaRainDestroyTrigger);
		}
		else
		{
			num = SoundIdClose;
			itemState = ItemStates.State1;
			BetterDayNightManager.instance.collidersToAddToWeatherSystems.Remove(umbrellaRainDestroyTrigger);
		}
		ActivateItemFX(hapticStrength, fixedDeltaTime, num, soundVolume);
		OnUmbrellaStateChanged();
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		OnUmbrellaStateChanged();
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		BetterDayNightManager.instance.collidersToAddToWeatherSystems.Remove(umbrellaRainDestroyTrigger);
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
		BetterDayNightManager.instance.collidersToAddToWeatherSystems.Remove(umbrellaRainDestroyTrigger);
		itemState = ItemStates.State1;
		OnUmbrellaStateChanged();
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (InHand())
		{
			return false;
		}
		if (itemState == ItemStates.State0)
		{
			OnActivate();
		}
		return true;
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		UmbrellaStates umbrellaStates = (UmbrellaStates)itemState;
		if (umbrellaStates != previousUmbrellaState)
		{
			OnUmbrellaStateChanged();
		}
		UpdateAngles((umbrellaStates == UmbrellaStates.UmbrellaOpen) ? startingAngles : endingAngles, lerpValue);
		previousUmbrellaState = umbrellaStates;
	}

	protected virtual void OnUmbrellaStateChanged()
	{
		bool flag = itemState == ItemStates.State0;
		GameObject[] array = gameObjectsActivatedOnOpen;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetActive(flag);
		}
		if (flag)
		{
			ParticleSystem[] array2 = particlesEmitOnOpen;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].Play();
			}
		}
		else
		{
			ParticleSystem[] array2 = particlesEmitOnOpen;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].Stop();
			}
		}
	}

	protected virtual void UpdateAngles(UnityEngine.Quaternion[] toAngles, float t)
	{
		for (int i = 0; i < umbrellaBones.Length; i++)
		{
			umbrellaBones[i].localRotation = UnityEngine.Quaternion.Lerp(umbrellaBones[i].localRotation, toAngles[i], t);
		}
	}

	protected void GenerateAngles()
	{
		startingAngles = new UnityEngine.Quaternion[umbrellaBones.Length];
		for (int i = 0; i < endingAngles.Length; i++)
		{
			startingAngles[i] = umbrellaToCopy.startingAngles[i];
		}
		endingAngles = new UnityEngine.Quaternion[umbrellaBones.Length];
		for (int j = 0; j < endingAngles.Length; j++)
		{
			endingAngles[j] = umbrellaToCopy.endingAngles[j];
		}
	}

	public override bool CanActivate()
	{
		return true;
	}

	public override bool CanDeactivate()
	{
		return true;
	}
}
