[Serializable]
public class FlagEvents<T> where T : Enum
{
	[Serializable]
	private class FlagEvent : ISerializationCallbackReceiver
	{
		public string debugName = "Any flag true";

		[Tooltip("Check this box if only the local player is supposed to run this event.")]
		public bool runOnlyLocally;

		private T flags;

		[HideInInspector]
		public int flagsAsInt;

		public UnityEvent anyFlagTrue;

		private string FlagsLabel => typeof(T).Name;

		public void OnBeforeSerialize()
		{
			flagsAsInt = Convert.ToInt32(flags);
		}

		public void OnAfterDeserialize()
		{
			flags = (T)(object)flagsAsInt;
		}
	}

	[SerializeField]
	private FlagEvent[] list;

	public void InvokeAll(T test, bool isLocal = false)
	{
		int num = Convert.ToInt32(test);
		for (int i = 0; i < list.Length; i++)
		{
			if ((num & list[i].flagsAsInt) != 0 && (!list[i].runOnlyLocally || isLocal))
			{
				list[i].anyFlagTrue?.Invoke();
			}
		}
	}
}
public class GumBubble : LerpComponent
{
	public Transform target;

	public UnityEngine.Vector3 targetScale = UnityEngine.Vector3.one;

	[SerializeField]
	private AnimationCurve _lerpCurve;

	public AudioSource audioSource;

	[SerializeField]
	private AudioClip _sfxInflate;

	[SerializeField]
	private AudioClip _sfxPop;

	[SerializeField]
	private float _delayInflate = 1.16f;

	[FormerlySerializedAs("_popDelay")]
	[SerializeField]
	private float _delayPop = 0.5f;

	[SerializeField]
	private bool _animating;

	public UnityEvent onPop;

	public UnityEvent onInflate;

	[NonSerialized]
	private bool _done;

	[NonSerialized]
	private TimeSince _sinceInflate;

	private void Awake()
	{
		base.enabled = false;
		base.gameObject.SetActive(value: false);
	}

	public void InflateDelayed()
	{
		InflateDelayed(_delayInflate);
	}

	public void InflateDelayed(float delay)
	{
		if (delay < 0f)
		{
			delay = 0f;
		}
		Invoke("Inflate", delay);
	}

	public void Inflate()
	{
		base.gameObject.SetActive(value: true);
		base.enabled = true;
		if (!_animating)
		{
			_animating = true;
			_sinceInflate = 0f;
			if (audioSource != null && _sfxInflate != null)
			{
				audioSource.GTPlayOneShot(_sfxInflate);
			}
			onInflate?.Invoke();
		}
	}

	public void Pop()
	{
		_lerp = 0f;
		RenderLerp();
		if (audioSource != null && _sfxPop != null)
		{
			audioSource.GTPlayOneShot(_sfxPop);
		}
		onPop?.Invoke();
		_done = false;
		_animating = false;
		base.enabled = false;
		base.gameObject.SetActive(value: false);
	}

	private void Update()
	{
		float t = Mathf.Clamp01((float)_sinceInflate / _lerpLength);
		_lerp = Mathf.Lerp(0f, 1f, t);
		if (_lerp <= 1f && !_done)
		{
			RenderLerp();
			if (Mathf.Approximately(_lerp, 1f))
			{
				_done = true;
			}
		}
		float num = _lerpLength + _delayPop;
		if ((float)_sinceInflate >= num)
		{
			Pop();
		}
	}

	protected override void OnLerp(float t)
	{
		if ((bool)target)
		{
			if (_lerpCurve == null)
			{
				GTDev.LogError("[GumBubble] Missing lerp curve", this);
			}
			else
			{
				target.localScale = targetScale * _lerpCurve.Evaluate(t);
			}
		}
	}
}
[RequireComponent(typeof(SphereCollider))]
public class HapticsWithDistance : MonoBehaviour, ITickSystemTick
{
	[SerializeField]
	[Tooltip("X is the normalized distance and should start at 0 and end at 1. Y is the vibration amplitude and can be anywhere from 0-1.")]
	private AnimationCurve vibrationIntensityByDistance;

	private float inverseColliderRadius;

	private float vibrationMult = 1f;

	private Transform leftOfflineHand;

	private Transform rightOfflineHand;

	public bool TickRunning { get; set; }

	private bool OnWrongLayer()
	{
		return base.gameObject.layer != 18;
	}

	public void SetVibrationMult(float mult)
	{
		vibrationMult = mult;
	}

	public void FingerFlexVibrationMult(bool dummy, float mult)
	{
		SetVibrationMult(mult);
	}

	private void Awake()
	{
		inverseColliderRadius = 1f / GetComponent<SphereCollider>().radius;
	}

	private void OnTriggerEnter(Collider other)
	{
		if (other.TryGetComponent<GorillaGrabber>(out var component) && component.enabled)
		{
			if (component.IsLeftHand)
			{
				leftOfflineHand = component.transform;
				TickSystem<object>.AddTickCallback(this);
			}
			else if (component.IsRightHand)
			{
				rightOfflineHand = component.transform;
				TickSystem<object>.AddTickCallback(this);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (leftOfflineHand == other.transform)
		{
			leftOfflineHand = null;
			if (!rightOfflineHand)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
		}
		else if (rightOfflineHand == other.transform)
		{
			rightOfflineHand = null;
			if (!leftOfflineHand)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
		}
	}

	private void OnDisable()
	{
		leftOfflineHand = null;
		rightOfflineHand = null;
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void Tick()
	{
		UnityEngine.Vector3 position = base.transform.position;
		if ((bool)leftOfflineHand)
		{
			GorillaTagger.Instance.StartVibration(forLeftController: true, vibrationMult * vibrationIntensityByDistance.Evaluate(UnityEngine.Vector3.Distance(leftOfflineHand.position, position) * inverseColliderRadius), Time.deltaTime);
		}
		if ((bool)rightOfflineHand)
		{
			GorillaTagger.Instance.StartVibration(forLeftController: false, vibrationMult * vibrationIntensityByDistance.Evaluate(UnityEngine.Vector3.Distance(rightOfflineHand.position, position) * inverseColliderRadius), Time.deltaTime);
		}
	}
}
