public class HypnoRing : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private bool attachedToLeftHand;

	private VRRig myRig;

	[SerializeField]
	private float rotationSpeed;

	[SerializeField]
	private AudioSource audioSource;

	[SerializeField]
	private float maxVolume = 1f;

	[SerializeField]
	private float fadeInDuration;

	[SerializeField]
	private float fadeOutDuration;

	private float currentVolume;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnDespawn()
	{
	}

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = rig;
	}

	private void Update()
	{
		if ((attachedToLeftHand ? myRig.leftIndex.calcT : myRig.rightIndex.calcT) > 0.5f)
		{
			base.transform.localRotation *= UnityEngine.Quaternion.AngleAxis(Time.deltaTime * rotationSpeed, UnityEngine.Vector3.up);
			currentVolume = Mathf.MoveTowards(currentVolume, maxVolume, Time.deltaTime / fadeInDuration);
			audioSource.volume = currentVolume;
			if (!audioSource.isPlaying)
			{
				audioSource.GTPlay();
			}
			return;
		}
		currentVolume = Mathf.MoveTowards(currentVolume, 0f, Time.deltaTime / fadeOutDuration);
		if (audioSource.isPlaying)
		{
			if (currentVolume == 0f)
			{
				audioSource.GTStop();
			}
			else
			{
				audioSource.volume = currentVolume;
			}
		}
	}
}
public class MoodRing : MonoBehaviour, ISpawnable
{
	[SerializeField]
	private bool attachedToLeftHand;

	private VRRig myRig;

	[SerializeField]
	private float rotationSpeed;

	[SerializeField]
	private float furCycleSpeed;

	private float nextFurCycleTimestamp;

	private float animRedValue;

	private float animGreenValue;

	private float animBlueValue;

	private bool isCycling;

	bool ISpawnable.IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	void ISpawnable.OnDespawn()
	{
	}

	void ISpawnable.OnSpawn(VRRig rig)
	{
		myRig = rig;
	}

	private void Update()
	{
		if ((attachedToLeftHand ? myRig.leftIndex.calcT : myRig.rightIndex.calcT) > 0.5f)
		{
			if (!isCycling)
			{
				animRedValue = myRig.playerColor.r;
				animGreenValue = myRig.playerColor.g;
				animBlueValue = myRig.playerColor.b;
			}
			isCycling = true;
			RainbowCycle(ref animRedValue, ref animGreenValue, ref animBlueValue);
			myRig.InitializeNoobMaterialLocal(animRedValue, animGreenValue, animBlueValue);
		}
		else
		{
			if (!isCycling)
			{
				return;
			}
			isCycling = false;
			if (myRig.isOfflineVRRig)
			{
				animRedValue = Mathf.Round(animRedValue * 9f) / 9f;
				animGreenValue = Mathf.Round(animGreenValue * 9f) / 9f;
				animBlueValue = Mathf.Round(animBlueValue * 9f) / 9f;
				GorillaTagger.Instance.UpdateColor(animRedValue, animGreenValue, animBlueValue);
				if (NetworkSystem.Instance.InRoom)
				{
					GorillaTagger.Instance.myVRRig.SendRPC("RPC_InitializeNoobMaterial", RpcTarget.All, animRedValue, animGreenValue, animBlueValue);
				}
				PlayerPrefs.SetFloat("redValue", animRedValue);
				PlayerPrefs.SetFloat("greenValue", animGreenValue);
				PlayerPrefs.SetFloat("blueValue", animBlueValue);
				PlayerPrefs.Save();
			}
		}
	}

	private void RainbowCycle(ref float r, ref float g, ref float b)
	{
		float num = furCycleSpeed * Time.deltaTime;
		if (r == 1f)
		{
			if (b > 0f)
			{
				b = Mathf.Clamp01(b - num);
			}
			else if (g < 1f)
			{
				g = Mathf.Clamp01(g + num);
			}
			else
			{
				r = Mathf.Clamp01(r - num);
			}
		}
		else if (g == 1f)
		{
			if (r > 0f)
			{
				r = Mathf.Clamp01(r - num);
			}
			else if (b < 1f)
			{
				b = Mathf.Clamp01(b + num);
			}
			else
			{
				g = Mathf.Clamp01(g - num);
			}
		}
		else if (b == 1f)
		{
			if (g > 0f)
			{
				g = Mathf.Clamp01(g - num);
			}
			else if (r < 1f)
			{
				r = Mathf.Clamp01(r + num);
			}
			else
			{
				b = Mathf.Clamp01(b - num);
			}
		}
		else
		{
			r = Mathf.Clamp01(r + num);
		}
	}
}
public class PaperPlaneProjectile : MonoBehaviour
{
	public delegate void PaperPlaneHit(UnityEngine.Vector3 endPoint);

	private const float speedScaleRatio = 0.7f;

	[NonSerialized]
	[Space]
	private float _timeElapsed;

	[NonSerialized]
	private float _speed;

	[NonSerialized]
	private UnityEngine.Vector3 _direction;

	[NonSerialized]
	private bool _stopped;

	private Transform _tCached;

	private SpawnWorldEffects spawnWorldEffects;

	private UnityEngine.Vector3 nextPos;

	private RaycastHit[] results = new RaycastHit[1];

	[Tooltip("Maximum lifetime in seconds for the projectile")]
	[SerializeField]
	private float maxFlightTime = 7.5f;

	[Tooltip("Collisions are ignored for minFlightTime seconds after launch")]
	[SerializeField]
	private float minFlightTime = 0.5f;

	[Tooltip("Hand speed to projectile launch Speed")]
	[SerializeField]
	private AnimationCurve speedCurve = new AnimationCurve(new Keyframe(0f, 0f, 0f, 0f), new Keyframe(6.324555f, 20f, 6.324555f, 6.324555f));

	[Tooltip("maximum speed of launched projectile (clamped after applying speed curve)")]
	[SerializeField]
	private float maxSpeed = 10f;

	[Tooltip("minimum speed of launched projectile (clamped after applying speed curve)")]
	[SerializeField]
	private float minSpeed = 1f;

	[SerializeField]
	private bool enableRotation;

	[Tooltip("Objects enabled when launched and disabled on Hit")]
	[SerializeField]
	private GameObject flyingObject;

	[Tooltip("Objects disabled when launched and enabled on Hit")]
	[SerializeField]
	private GameObject crashingObject;

	[Tooltip("Layers the projectile collides with")]
	[SerializeField]
	private LayerMask layerMask;

	[SerializeField]
	private bool useTransferrableObjectState;

	[SerializeField]
	protected UnityEvent OnResetProjectileState;

	[SerializeField]
	protected string boolADebugName;

	[SerializeField]
	protected UnityEvent OnItemStateBoolATrue;

	[SerializeField]
	protected UnityEvent OnItemStateBoolAFalse;

	[SerializeField]
	protected string boolBDebugName;

	[SerializeField]
	protected UnityEvent OnItemStateBoolBTrue;

	[SerializeField]
	protected UnityEvent OnItemStateBoolBFalse;

	[SerializeField]
	protected string boolCDebugName;

	[SerializeField]
	protected UnityEvent OnItemStateBoolCTrue;

	[SerializeField]
	protected UnityEvent OnItemStateBoolCFalse;

	[SerializeField]
	protected string boolDDebugName;

	[SerializeField]
	protected UnityEvent OnItemStateBoolDTrue;

	[SerializeField]
	protected UnityEvent OnItemStateBoolDFalse;

	[SerializeField]
	protected UnityEvent<int> OnItemStateIntChanged;

	private VRRig myRig;

	private float scaleFactor;

	public new Transform transform => _tCached;

	public VRRig MyRig => myRig;

	public event PaperPlaneHit OnHit;

	private void Awake()
	{
		_tCached = base.transform;
		spawnWorldEffects = GetComponent<SpawnWorldEffects>();
	}

	private void Start()
	{
		ResetProjectile();
	}

	public void ResetProjectile()
	{
		_timeElapsed = 0f;
		flyingObject.SetActive(value: true);
		crashingObject.SetActive(value: false);
	}

	internal void SetTransferrableState(TransferrableObject.SyncOptions syncType, int state)
	{
		if (!useTransferrableObjectState)
		{
			return;
		}
		switch (syncType)
		{
		case TransferrableObject.SyncOptions.Bool:
		{
			bool num = (state & 1) != 0;
			bool flag = (state & 2) != 0;
			bool flag2 = (state & 4) != 0;
			bool flag3 = (state & 8) != 0;
			if (num)
			{
				OnItemStateBoolATrue?.Invoke();
			}
			else
			{
				OnItemStateBoolAFalse?.Invoke();
			}
			if (flag)
			{
				OnItemStateBoolBTrue?.Invoke();
			}
			else
			{
				OnItemStateBoolBFalse?.Invoke();
			}
			if (flag2)
			{
				OnItemStateBoolCTrue?.Invoke();
			}
			else
			{
				OnItemStateBoolCFalse?.Invoke();
			}
			if (flag3)
			{
				OnItemStateBoolDTrue?.Invoke();
			}
			else
			{
				OnItemStateBoolDFalse?.Invoke();
			}
			break;
		}
		case TransferrableObject.SyncOptions.Int:
			OnItemStateIntChanged?.Invoke(state);
			break;
		}
	}

	public void Launch(UnityEngine.Vector3 startPos, UnityEngine.Quaternion startRot, UnityEngine.Vector3 vel)
	{
		base.gameObject.SetActive(value: true);
		ResetProjectile();
		transform.position = startPos;
		if (enableRotation)
		{
			transform.rotation = startRot;
		}
		else
		{
			transform.LookAt(transform.position + vel.normalized);
		}
		_direction = vel.normalized;
		_speed = Mathf.Clamp(speedCurve.Evaluate(vel.magnitude), minSpeed, maxSpeed);
		_stopped = false;
		scaleFactor = 0.7f * (transform.lossyScale.x - 1f + 1.4285715f);
	}

	private void Update()
	{
		if (_stopped)
		{
			if (!crashingObject.gameObject.activeSelf)
			{
				if ((bool)ObjectPools.instance)
				{
					ObjectPools.instance.Destroy(base.gameObject);
				}
				else
				{
					base.gameObject.SetActive(value: false);
				}
			}
			return;
		}
		_timeElapsed += Time.deltaTime;
		nextPos = transform.position + _direction * _speed * Time.deltaTime * scaleFactor;
		if (_timeElapsed < maxFlightTime && (_timeElapsed < minFlightTime || Physics.RaycastNonAlloc(transform.position, nextPos - transform.position, results, UnityEngine.Vector3.Distance(transform.position, nextPos), layerMask.value) == 0))
		{
			transform.position = nextPos;
			transform.Rotate(Mathf.Sin(_timeElapsed) * 10f * Time.deltaTime, 0f, 0f);
			return;
		}
		if (_timeElapsed < maxFlightTime)
		{
			if (results[0].collider.TryGetComponent<SlingshotProjectileHitNotifier>(out var component))
			{
				component.InvokeHit(this, results[0].collider);
			}
			if (spawnWorldEffects != null)
			{
				spawnWorldEffects.RequestSpawn(nextPos);
			}
		}
		_stopped = true;
		_timeElapsed = 0f;
		this.OnHit?.Invoke(nextPos);
		this.OnHit = null;
		flyingObject.SetActive(value: false);
		crashingObject.SetActive(value: true);
	}

	internal void SetVRRig(VRRig rig)
	{
		myRig = rig;
	}

	private void OnDisable()
	{
		if (useTransferrableObjectState)
		{
			OnResetProjectileState?.Invoke();
		}
	}
}
public class PaperPlaneThrowable : TransferrableObject
{
	[Tooltip("Renderer on the body to disable when spawning the projectile")]
	[SerializeField]
	private Renderer _renderer;

	[Tooltip("Prefab in the Global object pool to spawn when throwing")]
	[SerializeField]
	private GameObject _projectilePrefab;

	[Tooltip("Minimum velocity of the hand required to launch the projectile")]
	[SerializeField]
	private float minThrowSpeed;

	private static Camera _playerView;

	private static PhotonEvent gLaunchRPC;

	private CallLimiterWithCooldown m_spamCheck = new CallLimiterWithCooldown(5f, 4, 1f);

	private static readonly int kProjectileEvent = StaticHash.Compute("PaperPlaneThrowable".GetStaticHash(), "LaunchProjectileLocal".GetStaticHash());

	private static object[] gEventArgs = new object[5];

	private static RaiseEventOptions gRaiseOpts;

	[SerializeField]
	private string _throwableID;

	private int? _throwableIdHash;

	[Space]
	private UnityEngine.Vector3 _lastWorldPos;

	private UnityEngine.Quaternion _lastWorldRot;

	[Space]
	private UnityEngine.Vector3 _itemWorldVel;

	private UnityEngine.Vector3 _itemWorldAngVel;

	private void OnLaunchRPC(int sender, int receiver, object[] args, PhotonMessageInfoWrapped info)
	{
		if (info.senderID != ownerRig.creator.ActorNumber)
		{
			return;
		}
		MonkeAgent.IncrementRPCCall(info, "OnLaunchRPC");
		if (sender != receiver || !this)
		{
			return;
		}
		int num = FetchViewID(this);
		int num2 = (int)args[0];
		if (num == -1 || num2 == -1 || num != num2)
		{
			return;
		}
		int num3 = (int)args[1];
		int throwableId = GetThrowableId();
		if (num3 == throwableId)
		{
			UnityEngine.Vector3 v = (UnityEngine.Vector3)args[2];
			UnityEngine.Quaternion q = (UnityEngine.Quaternion)args[3];
			UnityEngine.Vector3 v2 = (UnityEngine.Vector3)args[4];
			if (v.IsValid(10000f) && q.IsValid() && v2.IsValid(10000f) && !_renderer.forceRenderingOff)
			{
				LaunchProjectileLocal(v, q, v2);
			}
		}
	}

	internal override void OnEnable()
	{
		PhotonNetwork.NetworkingClient.EventReceived += OnPhotonEvent;
		_lastWorldPos = base.transform.position;
		_renderer.forceRenderingOff = false;
		base.OnEnable();
	}

	internal override void OnDisable()
	{
		PhotonNetwork.NetworkingClient.EventReceived -= OnPhotonEvent;
		base.OnDisable();
	}

	private void OnPhotonEvent(EventData evData)
	{
		if (evData.Code != 176)
		{
			return;
		}
		object[] array = (object[])evData.CustomData;
		if (!(array[0] is int num) || num != kProjectileEvent)
		{
			return;
		}
		NetPlayer player = NetworkSystem.Instance.GetPlayer(evData.Sender);
		NetPlayer netPlayer = OwningPlayer();
		if (player != netPlayer)
		{
			return;
		}
		MonkeAgent.IncrementRPCCall(new PhotonMessageInfo(netPlayer.GetPlayerRef(), PhotonNetwork.ServerTimestamp, null), "OnPhotonEvent");
		if (!m_spamCheck.CheckCallTime(Time.unscaledTime))
		{
			return;
		}
		PositionState positionState = (PositionState)array[1];
		UnityEngine.Vector3 v = (UnityEngine.Vector3)array[2];
		UnityEngine.Quaternion q = (UnityEngine.Quaternion)array[3];
		UnityEngine.Vector3 v2 = (UnityEngine.Vector3)array[4];
		switch (positionState)
		{
		case PositionState.InLeftHand:
			if (InLeftHand())
			{
				break;
			}
			return;
		case PositionState.InRightHand:
			if (!InRightHand())
			{
				return;
			}
			break;
		}
		if (v.IsValid(10000f) && q.IsValid() && v2.IsValid(10000f) && !_renderer.forceRenderingOff && !GTExt.IsNull(base.myOnlineRig) && base.myOnlineRig.IsPositionInRange(v, 4f))
		{
			LaunchProjectileLocal(v, q, v2);
		}
	}

	protected override void Start()
	{
		base.Start();
		if (_playerView == null)
		{
			_playerView = Camera.main;
		}
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		if (!_renderer.forceRenderingOff)
		{
			base.OnGrab(pointGrabbed, grabbingHand);
		}
	}

	private static int FetchViewID(PaperPlaneThrowable ppt)
	{
		NetPlayer netPlayer = ((ppt.myOnlineRig != null) ? ppt.myOnlineRig.creator : ((!(ppt.myRig != null)) ? null : ((ppt.myRig.creator != null) ? ppt.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
		if (netPlayer == null)
		{
			return -1;
		}
		if (VRRigCache.Instance.TryGetVrrig(netPlayer, out var playerRig))
		{
			if (playerRig.Rig.netView == null)
			{
				return -1;
			}
			return playerRig.Rig.netView.ViewID;
		}
		return -1;
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		PositionState positionState = currentState;
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (VRRigCache.Instance.localRig.Rig != ownerRig)
		{
			return false;
		}
		if (_renderer.forceRenderingOff)
		{
			return false;
		}
		bool isLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
		GorillaVelocityTracker interactPointVelocityTracker = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeftHand);
		UnityEngine.Vector3 vector = base.transform.TransformPoint(UnityEngine.Vector3.zero);
		UnityEngine.Quaternion rotation = base.transform.rotation;
		UnityEngine.Vector3 averageVelocity = interactPointVelocityTracker.GetAverageVelocity(worldSpace: true);
		FetchViewID(this);
		GetThrowableId();
		LaunchProjectileLocal(vector, rotation, averageVelocity);
		if (gRaiseOpts == null)
		{
			gRaiseOpts = RaiseEventOptions.Default;
			gRaiseOpts.Receivers = ReceiverGroup.Others;
		}
		gEventArgs[0] = kProjectileEvent;
		gEventArgs[1] = positionState;
		gEventArgs[2] = vector;
		gEventArgs[3] = rotation;
		gEventArgs[4] = averageVelocity;
		PhotonNetwork.RaiseEvent(176, gEventArgs, gRaiseOpts, SendOptions.SendReliable);
		return true;
	}

	private int GetThrowableId()
	{
		int valueOrDefault = _throwableIdHash.GetValueOrDefault();
		if (!_throwableIdHash.HasValue)
		{
			valueOrDefault = StaticHash.Compute(_throwableID);
			_throwableIdHash = valueOrDefault;
			return valueOrDefault;
		}
		return valueOrDefault;
	}

	private void LaunchProjectileLocal(UnityEngine.Vector3 launchPos, UnityEngine.Quaternion launchRot, UnityEngine.Vector3 releaseVel)
	{
		if (!(releaseVel.sqrMagnitude <= minThrowSpeed * base.transform.lossyScale.z * base.transform.lossyScale.z))
		{
			GameObject obj = ObjectPools.instance.Instantiate(_projectilePrefab.gameObject, launchPos);
			obj.transform.localScale = base.transform.lossyScale;
			PaperPlaneProjectile component = obj.GetComponent<PaperPlaneProjectile>();
			component.OnHit += OnProjectileHit;
			if (networkedStateEvents != SyncOptions.None)
			{
				int state = (int)(itemState & (ItemStates)(-65));
				component.SetTransferrableState(networkedStateEvents, state);
			}
			component.ResetProjectile();
			component.SetVRRig(base.myRig);
			component.Launch(launchPos, launchRot, releaseVel);
			_renderer.forceRenderingOff = true;
		}
	}

	private void OnProjectileHit(UnityEngine.Vector3 endPoint)
	{
		_renderer.forceRenderingOff = false;
		if (IsLocalObject() && networkedStateEvents != SyncOptions.None && resetOnDocked)
		{
			switch (networkedStateEvents)
			{
			case SyncOptions.Bool:
				ResetStateBools();
				break;
			case SyncOptions.Int:
				SetItemStateInt(0);
				break;
			}
		}
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		Transform obj = base.transform;
		UnityEngine.Vector3 position = obj.position;
		_itemWorldVel = (position - _lastWorldPos) / Time.deltaTime;
		UnityEngine.Quaternion localRotation = obj.localRotation;
		_itemWorldAngVel = CalcAngularVelocity(_lastWorldRot, localRotation, Time.deltaTime);
		_lastWorldRot = localRotation;
		_lastWorldPos = position;
	}

	private static UnityEngine.Vector3 CalcAngularVelocity(UnityEngine.Quaternion from, UnityEngine.Quaternion to, float dt)
	{
		UnityEngine.Vector3 eulerAngles = (to * UnityEngine.Quaternion.Inverse(from)).eulerAngles;
		if (eulerAngles.x > 180f)
		{
			eulerAngles.x -= 360f;
		}
		if (eulerAngles.y > 180f)
		{
			eulerAngles.y -= 360f;
		}
		if (eulerAngles.z > 180f)
		{
			eulerAngles.z -= 360f;
		}
		return eulerAngles * (MathF.PI / 180f / dt);
	}

	public override void DropItem()
	{
		base.DropItem();
	}
}
