public class StickyProjectile : MonoBehaviour, IProjectile, ITickSystemTick
{
	[Flags]
	public enum StickFlags
	{
		Wall = 1,
		LocalPlayer = 2,
		RemotePlayer = 4,
		LocalHeadZone = 8,
		RemoteHeadZone = 0x10
	}

	[SerializeField]
	private Transform stickyPart;

	[Tooltip("Align the positive Z direction of this object to the rigidbody's velocity.")]
	[SerializeField]
	private bool faceVelocityWhileAirborne;

	[Tooltip("Set the rigidbody's angular velocity to a random unit Vector3, multiplied by a random value in this range.")]
	[SerializeField]
	private UnityEngine.Vector2 launchRandomSpinSpeedMinMax = new UnityEngine.Vector2(90f, 360f);

	[Tooltip("When enabled, the positive Z direction will face away from whatever surface the projectile hit. When disabled, it will keep its original rotation.")]
	[SerializeField]
	private bool alignToHitNormal = true;

	[Space]
	[SerializeField]
	public UnityEvent OnReset;

	[SerializeField]
	public UnityEvent OnLaunch;

	[Tooltip("Scale the 'Sticky Part' by this value when hitting the local player's head. Usually used to prevent things from obscuring your vision too much.")]
	[SerializeField]
	private float scaleOnLocalHead = 0.7f;

	[Tooltip("The radius of the head zone. Can be set to 0 to disable head zone functionality.")]
	[SerializeField]
	private float headZoneRadius = 0.15f;

	[Tooltip("The local origin of the head zone, relative to the player rig's head transform. When a shot hits inside the zone, the 'Sticky Part' will be moved to this position relative to the hit player's head.")]
	[SerializeField]
	private UnityEngine.Vector3 headZonePosition = new UnityEngine.Vector3(0f, 0.02f, 0.17f);

	[Tooltip("Scale the 'Sticky Part' by this value when hitting the local player's head zone. Can override 'Scale On Local Head' in case you want it to appear larger for emphasis.")]
	[SerializeField]
	private float scaleOnLocalHeadZone = 1f;

	[Tooltip("When a shot hits inside a remote player's head zone, it will be moved to the 'Head Zone Relative Position'. For the local player, it will instead be moved here. This DOES NOT AFFECT the actual origin of the head zone for hit-detection purposes, it is purely visual after-the-fact.")]
	[SerializeField]
	private UnityEngine.Vector3 localHeadZonePosition = new UnityEngine.Vector3(0f, 0.05f, 0.2f);

	[SerializeField]
	private FlagEvents<StickFlags> stickEvents;

	private readonly UnityEngine.Quaternion INVERSE_HEAD_ROTATION = UnityEngine.Quaternion.Inverse(UnityEngine.Quaternion.Euler(0f, 270f, 252.3229f));

	private UnityEngine.Vector3 headZoneInversePosition;

	private UnityEngine.Vector3 headZoneInverseLocalPosition;

	private UnityEngine.Vector3 stickyPartLocalPosition;

	private UnityEngine.Quaternion stickyPartLocalRotation;

	private UnityEngine.Vector3 stickyPartLocalScale;

	private Rigidbody rb;

	private RigidbodyWaterInteraction rbwi;

	private Collider collider;

	private PlayerColoredCosmetic pcc;

	private int triggerLayer;

	public bool TickRunning { get; set; }

	private void Awake()
	{
		stickyPart.GetLocalPositionAndRotation(out stickyPartLocalPosition, out stickyPartLocalRotation);
		stickyPartLocalScale = stickyPart.localScale;
		headZoneInversePosition = INVERSE_HEAD_ROTATION * headZonePosition;
		headZoneInverseLocalPosition = INVERSE_HEAD_ROTATION * localHeadZonePosition;
		rb = GetComponent<Rigidbody>();
		rbwi = GetComponent<RigidbodyWaterInteraction>();
		collider = GetComponent<Collider>();
		pcc = GetComponent<PlayerColoredCosmetic>();
		triggerLayer = LayerMask.NameToLayer("Gorilla Tag Collider");
		OnReset?.Invoke();
	}

	public void Launch(UnityEngine.Vector3 startPosition, UnityEngine.Quaternion startRotation, UnityEngine.Vector3 velocity, float chargeFrac, VRRig ownerRig, int progress)
	{
		OnLaunch?.Invoke();
		stickyPart.SetParent(base.transform, worldPositionStays: false);
		stickyPart.SetLocalPositionAndRotation(stickyPartLocalPosition, stickyPartLocalRotation);
		stickyPart.localScale = stickyPartLocalScale;
		base.transform.SetPositionAndRotation(startPosition, startRotation);
		base.transform.localScale = UnityEngine.Vector3.one * ownerRig.scaleFactor;
		rb.isKinematic = false;
		rb.position = startPosition;
		rb.rotation = startRotation;
		rb.linearVelocity = velocity;
		if (faceVelocityWhileAirborne)
		{
			TickSystem<object>.AddTickCallback(this);
			rb.angularVelocity = UnityEngine.Vector3.zero;
		}
		else
		{
			rb.angularVelocity = UnityEngine.Random.onUnitSphere * UnityEngine.Random.Range(launchRandomSpinSpeedMinMax.x, launchRandomSpinSpeedMinMax.y);
		}
		rbwi.enabled = true;
		collider.enabled = true;
		if (pcc != null)
		{
			pcc.UpdateColor(ownerRig.playerColor);
		}
	}

	private void StickTo(Transform otherTransform, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		stickyPart.parent = otherTransform;
		stickyPart.SetPositionAndRotation(position + rotation * stickyPartLocalPosition, rotation * stickyPartLocalRotation);
		rb.isKinematic = true;
		rbwi.enabled = false;
		collider.enabled = false;
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		TickSystem<object>.RemoveTickCallback(this);
		ContactPoint contact = collision.GetContact(0);
		StickTo(collision.transform, contact.point, alignToHitNormal ? UnityEngine.Quaternion.LookRotation(contact.normal, UnityEngine.Random.onUnitSphere) : base.transform.rotation);
		stickEvents.InvokeAll(StickFlags.Wall);
	}

	private void OnTriggerEnter(Collider other)
	{
		if (other.gameObject.layer != triggerLayer)
		{
			return;
		}
		TickSystem<object>.RemoveTickCallback(this);
		UnityEngine.Vector3 vector = Time.fixedDeltaTime * 2f * rb.linearVelocity;
		UnityEngine.Vector3 vector2 = base.transform.position - vector;
		UnityEngine.Vector3 vector3;
		UnityEngine.Quaternion rotation;
		if (alignToHitNormal)
		{
			float magnitude = vector.magnitude;
			other.Raycast(new Ray(vector2, vector / magnitude), out var hitInfo, 2f * magnitude);
			vector3 = hitInfo.point;
			rotation = UnityEngine.Quaternion.LookRotation(hitInfo.normal, UnityEngine.Random.onUnitSphere);
		}
		else
		{
			vector3 = other.ClosestPoint(vector2);
			rotation = base.transform.rotation;
		}
		VRRig componentInParent = other.GetComponentInParent<VRRig>();
		if (componentInParent != null)
		{
			if (headZoneRadius > 0f && string.Equals(other.name, "SpeakerHeadCollider"))
			{
				other.transform.GetPositionAndRotation(out var position, out var rotation2);
				UnityEngine.Vector3 vector4 = rotation2 * headZoneInversePosition + position;
				if ((vector3 - vector4).magnitude <= headZoneRadius * componentInParent.scaleFactor)
				{
					if (componentInParent.isOfflineVRRig)
					{
						StickTo(other.transform, rotation2 * headZoneInverseLocalPosition + position, rotation2 * INVERSE_HEAD_ROTATION);
						stickyPart.localScale *= scaleOnLocalHeadZone;
						stickEvents.InvokeAll(StickFlags.LocalHeadZone);
					}
					else
					{
						StickTo(other.transform, vector4, rotation2 * INVERSE_HEAD_ROTATION);
						stickEvents.InvokeAll(StickFlags.RemoteHeadZone);
					}
					return;
				}
				if (componentInParent.isOfflineVRRig)
				{
					stickyPart.localScale *= scaleOnLocalHead;
				}
			}
			stickEvents.InvokeAll(componentInParent.isOfflineVRRig ? StickFlags.LocalPlayer : StickFlags.RemotePlayer);
		}
		else
		{
			stickEvents.InvokeAll(StickFlags.Wall);
		}
		StickTo(other.transform, vector3, rotation);
	}

	private void OnEnable()
	{
		stickyPart.gameObject.SetActive(value: true);
	}

	private void OnDisable()
	{
		stickyPart.gameObject.SetActive(value: false);
		OnReset?.Invoke();
	}

	public void Tick()
	{
		rb.rotation = UnityEngine.Quaternion.LookRotation(rb.linearVelocity);
	}
}
public class StopwatchCosmetic : TransferrableObject
{
	[SerializeField]
	private StopwatchFace _watchFace;

	[NonSerialized]
	[Space]
	private bool _isActivating;

	[NonSerialized]
	private float _activeTimeElapsed;

	[NonSerialized]
	private bool _activated;

	[NonSerialized]
	[Space]
	private int _photonID = -1;

	private static PhotonEvent gWatchToggleRPC;

	private static PhotonEvent gWatchResetRPC;

	private Action<int, int, object[], PhotonMessageInfoWrapped> _watchToggle;

	private Action<int, int, object[], PhotonMessageInfoWrapped> _watchReset;

	[DebugOption]
	public bool disableActivation;

	[DebugOption]
	public bool disableDeactivation;

	public bool isActivating => _isActivating;

	public float activeTimeElapsed => _activeTimeElapsed;

	protected override void Awake()
	{
		base.Awake();
		if (gWatchToggleRPC == null)
		{
			gWatchToggleRPC = new PhotonEvent(StaticHash.Compute("StopwatchCosmetic", "WatchToggle"));
		}
		if (gWatchResetRPC == null)
		{
			gWatchResetRPC = new PhotonEvent(StaticHash.Compute("StopwatchCosmetic", "WatchReset"));
		}
		_watchToggle = OnWatchToggle;
		_watchReset = OnWatchReset;
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		if (!FetchMyViewID(out var viewID))
		{
			_photonID = -1;
			return;
		}
		gWatchResetRPC += _watchReset;
		gWatchToggleRPC += _watchToggle;
		_photonID = viewID.GetStaticHash();
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		gWatchResetRPC -= _watchReset;
		gWatchToggleRPC -= _watchToggle;
	}

	private void OnWatchToggle(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		if (_photonID != -1 && info.senderID == ownerRig.creator.ActorNumber && sender == target)
		{
			MonkeAgent.IncrementRPCCall(info, "OnWatchToggle");
			if ((int)args[0] == _photonID)
			{
				_ = (bool)args[1];
				int millis = (int)args[2];
				_watchFace.SetMillisElapsed(millis);
				_watchFace.WatchToggle();
			}
		}
	}

	private void OnWatchReset(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		if (_photonID != -1 && info.senderID == ownerRig.creator.ActorNumber && sender == target)
		{
			MonkeAgent.IncrementRPCCall(info, "OnWatchReset");
			if ((int)args[0] == _photonID)
			{
				_watchFace.WatchReset();
			}
		}
	}

	private bool FetchMyViewID(out int viewID)
	{
		viewID = -1;
		NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
		if (netPlayer == null)
		{
			return false;
		}
		if (!VRRigCache.Instance.TryGetVrrig(netPlayer, out var playerRig))
		{
			return false;
		}
		if (playerRig.Rig.netView == null)
		{
			return false;
		}
		viewID = playerRig.Rig.netView.ViewID;
		return true;
	}

	public bool PollActivated()
	{
		if (!_activated)
		{
			return false;
		}
		_activated = false;
		return true;
	}

	public override void TriggeredLateUpdate()
	{
		base.TriggeredLateUpdate();
		if (_isActivating)
		{
			_activeTimeElapsed += Time.deltaTime;
		}
		if (_isActivating && _activeTimeElapsed > 1f)
		{
			_isActivating = false;
			_watchFace.WatchReset(doLerp: true);
			gWatchResetRPC.RaiseOthers(_photonID);
		}
	}

	public override void OnActivate()
	{
		if (CanActivate())
		{
			base.OnActivate();
			if (IsMyItem())
			{
				_activeTimeElapsed = 0f;
				_isActivating = true;
			}
		}
	}

	public override void OnDeactivate()
	{
		if (CanDeactivate())
		{
			base.OnDeactivate();
			if (IsMyItem())
			{
				_isActivating = false;
				_activated = true;
				_watchFace.WatchToggle();
				gWatchToggleRPC.RaiseOthers(_photonID, _watchFace.watchActive, _watchFace.millisElapsed);
				_activated = false;
			}
		}
	}

	public override bool CanActivate()
	{
		return !disableActivation;
	}

	public override bool CanDeactivate()
	{
		return !disableDeactivation;
	}
}
public class Bubbler : TransferrableObject
{
	private enum BubblerState
	{
		None = 1,
		Bubbling
	}

	[SerializeField]
	private bool _worksInWater = true;

	public ParticleSystem bubbleParticleSystem;

	private ParticleSystem.Particle[] bubbleParticleArray;

	public AudioSource bubblerAudio;

	public AudioSource popBubbleAudio;

	private List<uint> currentParticles = new List<uint>();

	private Dictionary<uint, UnityEngine.Vector3> particleInfoDict = new Dictionary<uint, UnityEngine.Vector3>();

	private UnityEngine.Vector3 outPosition;

	private bool allBubblesPopped;

	public bool disableActivation;

	public bool disableDeactivation;

	public float rotationSpeed = 5f;

	public GameObject fan;

	public bool fanYaxisinstead;

	public float ongoingStrength = 0.005f;

	public float triggerStrength = 0.2f;

	private float initialTriggerPull;

	private float initialTriggerDuration;

	private bool hasBubblerAudio;

	private bool hasPopBubbleAudio;

	public GameObject gameObjectActiveOnlyWhileTriggerDown;

	public UnityEngine.Behaviour[] behavioursToEnableWhenTriggerPressed;

	private bool hasParticleSystem;

	private bool hasFan;

	private bool hasActiveOnlyComponent;

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		hasParticleSystem = bubbleParticleSystem != null;
		if (hasParticleSystem)
		{
			bubbleParticleArray = new ParticleSystem.Particle[bubbleParticleSystem.main.maxParticles];
			bubbleParticleSystem.trigger.SetCollider(0, GorillaTagger.Instance.leftHandTriggerCollider.GetComponent<SphereCollider>());
			bubbleParticleSystem.trigger.SetCollider(1, GorillaTagger.Instance.rightHandTriggerCollider.GetComponent<SphereCollider>());
		}
		initialTriggerDuration = 0.05f;
		itemState = ItemStates.State0;
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		itemState = ItemStates.State0;
		hasBubblerAudio = bubblerAudio != null && bubblerAudio.clip != null;
		hasPopBubbleAudio = popBubbleAudio != null && popBubbleAudio.clip != null;
		hasFan = fan != null;
		hasActiveOnlyComponent = gameObjectActiveOnlyWhileTriggerDown != null;
	}

	private void InitToDefault()
	{
		itemState = ItemStates.State0;
		if (hasParticleSystem && bubbleParticleSystem.isPlaying)
		{
			bubbleParticleSystem.Stop();
		}
		if (hasBubblerAudio && bubblerAudio.isPlaying)
		{
			bubblerAudio.GTStop();
		}
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		itemState = ItemStates.State0;
		if (hasParticleSystem && bubbleParticleSystem.isPlaying)
		{
			bubbleParticleSystem.Stop();
		}
		if (hasBubblerAudio && bubblerAudio.isPlaying)
		{
			bubblerAudio.GTStop();
		}
		currentParticles.Clear();
		particleInfoDict.Clear();
	}

	public override void ResetToDefaultState()
	{
		base.ResetToDefaultState();
		InitToDefault();
	}

	protected override void LateUpdateLocal()
	{
		base.LateUpdateLocal();
		if (!_worksInWater && GTPlayer.Instance.InWater)
		{
			itemState = ItemStates.State0;
		}
	}

	protected override void LateUpdateShared()
	{
		base.LateUpdateShared();
		if (!IsMyItem() && base.myOnlineRig != null && base.myOnlineRig.muted)
		{
			itemState = ItemStates.State0;
		}
		bool forLeftController = currentState == PositionState.InLeftHand;
		bool flag = itemState != ItemStates.State0;
		UnityEngine.Behaviour[] array = behavioursToEnableWhenTriggerPressed;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = flag;
		}
		if (itemState == ItemStates.State0)
		{
			if (hasParticleSystem && bubbleParticleSystem.isPlaying)
			{
				bubbleParticleSystem.Stop();
			}
			if (hasBubblerAudio && bubblerAudio.isPlaying)
			{
				bubblerAudio.GTStop();
			}
			if (hasActiveOnlyComponent)
			{
				gameObjectActiveOnlyWhileTriggerDown.SetActive(value: false);
			}
		}
		else
		{
			if (hasParticleSystem && !bubbleParticleSystem.isEmitting)
			{
				bubbleParticleSystem.Play();
			}
			if (hasBubblerAudio && !bubblerAudio.isPlaying)
			{
				bubblerAudio.GTPlay();
			}
			if (hasActiveOnlyComponent && !gameObjectActiveOnlyWhileTriggerDown.activeSelf)
			{
				gameObjectActiveOnlyWhileTriggerDown.SetActive(value: true);
			}
			if (IsMyItem())
			{
				initialTriggerPull = Time.time;
				GorillaTagger.Instance.StartVibration(forLeftController, triggerStrength, initialTriggerDuration);
				if (Time.time > initialTriggerPull + initialTriggerDuration)
				{
					GorillaTagger.Instance.StartVibration(forLeftController, ongoingStrength, Time.deltaTime);
				}
			}
			if (hasFan)
			{
				if (!fanYaxisinstead)
				{
					float z = fan.transform.localEulerAngles.z + rotationSpeed * Time.fixedDeltaTime;
					fan.transform.localEulerAngles = new UnityEngine.Vector3(0f, 0f, z);
				}
				else
				{
					float y = fan.transform.localEulerAngles.y + rotationSpeed * Time.fixedDeltaTime;
					fan.transform.localEulerAngles = new UnityEngine.Vector3(0f, y, 0f);
				}
			}
		}
		if (!hasParticleSystem || (allBubblesPopped && itemState != ItemStates.State1))
		{
			return;
		}
		int particles = bubbleParticleSystem.GetParticles(bubbleParticleArray);
		allBubblesPopped = particles <= 0;
		if (allBubblesPopped)
		{
			return;
		}
		for (int j = 0; j < particles; j++)
		{
			if (currentParticles.Contains(bubbleParticleArray[j].randomSeed))
			{
				currentParticles.Remove(bubbleParticleArray[j].randomSeed);
			}
		}
		foreach (uint currentParticle in currentParticles)
		{
			if (particleInfoDict.TryGetValue(currentParticle, out outPosition))
			{
				if (hasPopBubbleAudio)
				{
					GTAudioSourceExtensions.GTPlayClipAtPoint(popBubbleAudio.clip, outPosition);
				}
				particleInfoDict.Remove(currentParticle);
			}
		}
		currentParticles.Clear();
		for (int k = 0; k < particles; k++)
		{
			if (particleInfoDict.TryGetValue(bubbleParticleArray[k].randomSeed, out outPosition))
			{
				particleInfoDict[bubbleParticleArray[k].randomSeed] = bubbleParticleArray[k].position;
			}
			else
			{
				particleInfoDict.Add(bubbleParticleArray[k].randomSeed, bubbleParticleArray[k].position);
			}
			currentParticles.Add(bubbleParticleArray[k].randomSeed);
		}
	}

	public override void OnActivate()
	{
		base.OnActivate();
		itemState = ItemStates.State1;
	}

	public override void OnDeactivate()
	{
		base.OnDeactivate();
		itemState = ItemStates.State0;
	}

	public override bool CanActivate()
	{
		return !disableActivation;
	}

	public override bool CanDeactivate()
	{
		return !disableDeactivation;
	}
}
public class KinematicWhenTargetInactive : MonoBehaviour
{
	public Rigidbody[] rigidBodies;

	public GameObject target;

	private void LateUpdate()
	{
		Rigidbody[] array;
		if (!target.activeSelf)
		{
			array = rigidBodies;
			foreach (Rigidbody rigidbody in array)
			{
				if (!rigidbody.isKinematic)
				{
					rigidbody.isKinematic = true;
				}
			}
			return;
		}
		array = rigidBodies;
		foreach (Rigidbody rigidbody2 in array)
		{
			if (rigidbody2.isKinematic)
			{
				rigidbody2.isKinematic = false;
			}
		}
	}
}
public class MonkeCandle : RubberDuck
{
	private ParticleSystem.Particle[] fxParticleArray = new ParticleSystem.Particle[20];

	public AudioSource movingFxAudio;

	public AudioSource fxExplodeAudio;

	private List<uint> currentParticles = new List<uint>();

	private Dictionary<uint, UnityEngine.Vector3> particleInfoDict = new Dictionary<uint, UnityEngine.Vector3>();

	private UnityEngine.Vector3 outPosition;

	protected override void Start()
	{
		base.Start();
		if (!IsMyItem())
		{
			movingFxAudio.volume *= 0.5f;
			fxExplodeAudio.volume *= 0.5f;
		}
	}

	public override void TriggeredLateUpdate()
	{
		base.TriggeredLateUpdate();
		if (!particleFX.isPlaying)
		{
			return;
		}
		int particles = particleFX.GetParticles(fxParticleArray);
		if (particles <= 0)
		{
			movingFxAudio.GTStop();
			if (currentParticles.Count == 0)
			{
				return;
			}
		}
		for (int i = 0; i < particles; i++)
		{
			if (currentParticles.Contains(fxParticleArray[i].randomSeed))
			{
				currentParticles.Remove(fxParticleArray[i].randomSeed);
			}
		}
		foreach (uint currentParticle in currentParticles)
		{
			if (particleInfoDict.TryGetValue(currentParticle, out outPosition))
			{
				fxExplodeAudio.transform.position = outPosition;
				fxExplodeAudio.GTPlayOneShot(fxExplodeAudio.clip);
				particleInfoDict.Remove(currentParticle);
			}
		}
		currentParticles.Clear();
		for (int j = 0; j < particles; j++)
		{
			if (j == 0)
			{
				movingFxAudio.transform.position = fxParticleArray[j].position;
			}
			if (particleInfoDict.TryGetValue(fxParticleArray[j].randomSeed, out outPosition))
			{
				particleInfoDict[fxParticleArray[j].randomSeed] = fxParticleArray[j].position;
			}
			else
			{
				particleInfoDict.Add(fxParticleArray[j].randomSeed, fxParticleArray[j].position);
				if (j == 0 && !movingFxAudio.isPlaying)
				{
					movingFxAudio.GTPlay();
				}
			}
			currentParticles.Add(fxParticleArray[j].randomSeed);
		}
	}
}
public class RubberDuck : TransferrableObject
{
	[DebugOption]
	public bool disableActivation;

	[DebugOption]
	public bool disableDeactivation;

	private SkinnedMeshRenderer skinRenderer;

	[FormerlySerializedAs("duckieLerp")]
	public float blendShapeMaxWeight = 1f;

	private int tempHandPos;

	[GorillaSoundLookup]
	[SerializeField]
	private int squeezeSound = 75;

	[GorillaSoundLookup]
	[SerializeField]
	private int squeezeReleaseSound = 76;

	[GorillaSoundLookup]
	public int[] squeezeSoundBank;

	[GorillaSoundLookup]
	public int[] squeezeReleaseSoundBank;

	public float squeezeStrength = 0.05f;

	public float releaseStrength = 0.03f;

	public ParticleSystem particleFX;

	[Tooltip("The emission rate of the particle effect when not squeezed.")]
	public float particleFXEmissionIdle = 0.8f;

	[Tooltip("The emission rate of the particle effect when squeezed.")]
	public float particleFXEmissionSqueeze = 10f;

	[Tooltip("The animation of the particle effect returning to the idle emission rate. X axis is time, Y axis is the emission lerp value where 0 is idle, 1 is squeezed.")]
	public AnimationCurve particleFXEmissionCooldownCurve;

	private bool hasSkinRenderer;

	private ParticleSystem.EmissionModule pFXEmissionModule;

	private bool hasParticleFX;

	private float squeezeTimeElapsed;

	[SerializeField]
	private RubberDuckEvents _events;

	[SerializeField]
	private bool _raiseActivate = true;

	[SerializeField]
	private bool _raiseDeactivate = true;

	[SerializeField]
	private SoundEffects _sfxActivate;

	[SerializeField]
	private bool _fxActive;

	public bool fxActive
	{
		get
		{
			if (hasParticleFX)
			{
				return _fxActive;
			}
			return false;
		}
		set
		{
			if (hasParticleFX)
			{
				pFXEmissionModule.enabled = value;
				_fxActive = value;
			}
		}
	}

	public int SqueezeSound
	{
		get
		{
			if (squeezeSoundBank.Length > 1)
			{
				return squeezeSoundBank[UnityEngine.Random.Range(0, squeezeSoundBank.Length)];
			}
			if (squeezeSoundBank.Length == 1)
			{
				return squeezeSoundBank[0];
			}
			return squeezeSound;
		}
	}

	public int SqueezeReleaseSound
	{
		get
		{
			if (squeezeReleaseSoundBank.Length > 1)
			{
				return squeezeReleaseSoundBank[UnityEngine.Random.Range(0, squeezeReleaseSoundBank.Length)];
			}
			if (squeezeReleaseSoundBank.Length == 1)
			{
				return squeezeReleaseSoundBank[0];
			}
			return squeezeReleaseSound;
		}
	}

	public override void OnSpawn(VRRig rig)
	{
		base.OnSpawn(rig);
		if (skinRenderer == null)
		{
			skinRenderer = GetComponentInChildren<SkinnedMeshRenderer>(includeInactive: true);
		}
		hasSkinRenderer = skinRenderer != null;
		myThreshold = 0.7f;
		hysterisis = 0.3f;
		hasParticleFX = particleFX != null;
		if (hasParticleFX)
		{
			pFXEmissionModule = particleFX.emission;
			pFXEmissionModule.rateOverTime = particleFXEmissionIdle;
		}
		fxActive = false;
	}

	internal override void OnEnable()
	{
		base.OnEnable();
		if (_events == null)
		{
			_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
			if (netPlayer != null)
			{
				_events.Init(netPlayer);
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
			}
		}
		if (_events != null)
		{
			_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnSqueezeActivate);
			_events.Deactivate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnSqueezeDeactivate);
		}
	}

	internal override void OnDisable()
	{
		base.OnDisable();
		if (_events != null)
		{
			_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnSqueezeActivate);
			_events.Deactivate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnSqueezeDeactivate);
			_events.Dispose();
			_events = null;
		}
	}

	private void OnSqueezeActivate(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		if (sender == target && info.senderID == ownerRig.creator.ActorNumber)
		{
			SqueezeActivateLocal();
		}
	}

	private void SqueezeActivateLocal()
	{
		PlayParticleFX(particleFXEmissionSqueeze);
		if ((bool)_sfxActivate && !_sfxActivate.isPlaying)
		{
			_sfxActivate.PlayNext();
		}
	}

	private void OnSqueezeDeactivate(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
	{
		if (sender == target)
		{
			MonkeAgent.IncrementRPCCall(info, "OnSqueezeDeactivate");
			if (info.senderID == ownerRig.creator.ActorNumber)
			{
				SqueezeDeactivateLocal();
			}
		}
	}

	private void SqueezeDeactivateLocal()
	{
		PlayParticleFX(particleFXEmissionIdle);
	}

	public override void TriggeredLateUpdate()
	{
		base.TriggeredLateUpdate();
		float num = 0f;
		if (InHand())
		{
			tempHandPos = ((base.myOnlineRig != null) ? base.myOnlineRig.ReturnHandPosition() : base.myRig.ReturnHandPosition());
			num = ((currentState != PositionState.InLeftHand) ? ((float)Mathf.FloorToInt((float)(tempHandPos % 10) / 1f)) : ((float)Mathf.FloorToInt((float)(tempHandPos % 10000) / 1000f)));
		}
		if (hasSkinRenderer)
		{
			skinRenderer.SetBlendShapeWeight(0, Mathf.Lerp(skinRenderer.GetBlendShapeWeight(0), num * 11.1f, blendShapeMaxWeight));
		}
		if (fxActive)
		{
			squeezeTimeElapsed += Time.deltaTime;
			pFXEmissionModule.rateOverTime = Mathf.Lerp(particleFXEmissionIdle, particleFXEmissionSqueeze, particleFXEmissionCooldownCurve.Evaluate(squeezeTimeElapsed));
			if (squeezeTimeElapsed > particleFXEmissionSqueeze)
			{
				fxActive = false;
			}
		}
	}

	public override void OnActivate()
	{
		base.OnActivate();
		if (IsMyItem())
		{
			bool flag = currentState == PositionState.InLeftHand;
			RigContainer localRig = VRRigCache.Instance.localRig;
			int num = SqueezeSound;
			localRig.Rig.PlayHandTapLocal(num, flag, 0.33f);
			if ((bool)localRig.netView)
			{
				localRig.netView.SendRPC("RPC_PlayHandTap", RpcTarget.Others, num, flag, 0.33f);
			}
			GorillaTagger.Instance.StartVibration(flag, squeezeStrength, Time.deltaTime);
		}
		if (_raiseActivate)
		{
			if (RoomSystem.JoinedRoom)
			{
				_events?.Activate?.RaiseAll();
			}
			else
			{
				SqueezeActivateLocal();
			}
		}
	}

	public override void OnDeactivate()
	{
		base.OnDeactivate();
		if (IsMyItem())
		{
			bool flag = currentState == PositionState.InLeftHand;
			int num = SqueezeReleaseSound;
			UnityEngine.Debug.Log("Squeezy Deactivate: " + num);
			VRRigCache.Instance.localRig.Rig.PlayHandTapLocal(num, flag, 0.33f);
			if ((bool)GorillaGameManager.instance && VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.LocalPlayer, out var playerRig))
			{
				playerRig.Rig.netView.SendRPC("RPC_PlayHandTap", RpcTarget.Others, num, flag, 0.33f);
			}
			GorillaTagger.Instance.StartVibration(flag, releaseStrength, Time.deltaTime);
		}
		if (_raiseDeactivate)
		{
			if (RoomSystem.JoinedRoom)
			{
				_events?.Deactivate?.RaiseAll();
			}
			else
			{
				SqueezeDeactivateLocal();
			}
		}
	}

	public void PlayParticleFX(float rate)
	{
		if (hasParticleFX && (currentState == PositionState.InLeftHand || currentState == PositionState.InRightHand))
		{
			if (!fxActive)
			{
				fxActive = true;
			}
			squeezeTimeElapsed = 0f;
			pFXEmissionModule.rateOverTime = rate;
		}
	}

	public override bool CanActivate()
	{
		return !disableActivation;
	}

	public override bool CanDeactivate()
	{
		return !disableDeactivation;
	}
}
