public class GorillaWalkingGrab : MonoBehaviour
{
	public GameObject handToStickTo;

	public float ratioToUse;

	public float forceMultiplier;

	public int historySteps;

	public Rigidbody playspaceRigidbody;

	private Rigidbody thisRigidbody;

	private UnityEngine.Vector3 lastPosition;

	private UnityEngine.Vector3 maybeLastPositionIDK;

	private UnityEngine.Vector3[] positionHistory;

	private int historyIndex;

	private void Start()
	{
		thisRigidbody = base.gameObject.GetComponent<Rigidbody>();
		positionHistory = new UnityEngine.Vector3[historySteps];
		historyIndex = 0;
	}

	private void FixedUpdate()
	{
		historyIndex++;
		if (historyIndex >= historySteps)
		{
			historyIndex = 0;
		}
		positionHistory[historyIndex] = handToStickTo.transform.position;
		thisRigidbody.MovePosition(handToStickTo.transform.position);
		base.transform.rotation = handToStickTo.transform.rotation;
	}

	private bool MakeJump()
	{
		return false;
	}

	private void OnCollisionStay(UnityEngine.Collision collision)
	{
		if (!MakeJump())
		{
			UnityEngine.Vector3 vector = UnityEngine.Vector3.ProjectOnPlane(positionHistory[(historyIndex != 0) ? (historyIndex - 1) : (historySteps - 1)] - handToStickTo.transform.position, collision.GetContact(0).normal);
			UnityEngine.Vector3 vector2 = thisRigidbody.transform.position - handToStickTo.transform.position;
			playspaceRigidbody.MovePosition(playspaceRigidbody.transform.position + vector - vector2);
		}
	}
}
public class GravityOverrideVolume : MonoBehaviour
{
	public enum GravityType
	{
		Directional,
		Radial
	}

	[SerializeField]
	private GravityType gravityType;

	[SerializeField]
	private float strength = 9.8f;

	[SerializeField]
	[Tooltip("In Radial: the center point of gravity, In Directional: the forward vector of this transform defines the direction")]
	private Transform referenceTransform;

	[SerializeField]
	private CompositeTriggerEvents triggerEvents;

	private void OnEnable()
	{
		if (triggerEvents != null)
		{
			triggerEvents.CompositeTriggerEnter += OnColliderEnteredVolume;
			triggerEvents.CompositeTriggerExit += OnColliderExitedVolume;
		}
	}

	private void OnDisable()
	{
		if (triggerEvents != null)
		{
			triggerEvents.CompositeTriggerEnter -= OnColliderEnteredVolume;
			triggerEvents.CompositeTriggerExit -= OnColliderExitedVolume;
		}
	}

	private void OnColliderEnteredVolume(Collider collider)
	{
		GTPlayer instance = GTPlayer.Instance;
		if (instance != null && collider == instance.headCollider)
		{
			instance.SetGravityOverride(this, GravityOverrideFunction);
		}
	}

	private void OnColliderExitedVolume(Collider collider)
	{
		GTPlayer instance = GTPlayer.Instance;
		if (instance != null && collider == instance.headCollider)
		{
			instance.UnsetGravityOverride(this);
		}
	}

	public void GravityOverrideFunction(GTPlayer player)
	{
		switch (gravityType)
		{
		case GravityType.Directional:
		{
			UnityEngine.Vector3 forward = referenceTransform.forward;
			player.AddForce(forward * strength, ForceMode.Acceleration);
			break;
		}
		case GravityType.Radial:
		{
			UnityEngine.Vector3 normalized = (referenceTransform.position - player.headCollider.transform.position).normalized;
			player.AddForce(normalized * strength, ForceMode.Acceleration);
			break;
		}
		}
	}
}
