public class PrimaryButtonWatcher : MonoBehaviour
{
	public PrimaryButtonEvent primaryButtonPress;

	private bool lastButtonState;

	private List<UnityEngine.XR.InputDevice> devicesWithPrimaryButton;

	private void Awake()
	{
		if (primaryButtonPress == null)
		{
			primaryButtonPress = new PrimaryButtonEvent();
		}
		devicesWithPrimaryButton = new List<UnityEngine.XR.InputDevice>();
	}

	private void OnEnable()
	{
		List<UnityEngine.XR.InputDevice> list = new List<UnityEngine.XR.InputDevice>();
		InputDevices.GetDevices(list);
		foreach (UnityEngine.XR.InputDevice item in list)
		{
			InputDevices_deviceConnected(item);
		}
		InputDevices.deviceConnected += InputDevices_deviceConnected;
		InputDevices.deviceDisconnected += InputDevices_deviceDisconnected;
	}

	private void OnDisable()
	{
		InputDevices.deviceConnected -= InputDevices_deviceConnected;
		InputDevices.deviceDisconnected -= InputDevices_deviceDisconnected;
		devicesWithPrimaryButton.Clear();
	}

	private void InputDevices_deviceConnected(UnityEngine.XR.InputDevice device)
	{
		if (device.TryGetFeatureValue(UnityEngine.XR.CommonUsages.primaryButton, out var _))
		{
			devicesWithPrimaryButton.Add(device);
		}
	}

	private void InputDevices_deviceDisconnected(UnityEngine.XR.InputDevice device)
	{
		if (devicesWithPrimaryButton.Contains(device))
		{
			devicesWithPrimaryButton.Remove(device);
		}
	}

	private void Update()
	{
		bool flag = false;
		foreach (UnityEngine.XR.InputDevice item in devicesWithPrimaryButton)
		{
			bool value = false;
			flag = (item.TryGetFeatureValue(UnityEngine.XR.CommonUsages.primaryButton, out value) && value) || flag;
		}
		if (flag != lastButtonState)
		{
			primaryButtonPress.Invoke(flag);
			lastButtonState = flag;
		}
	}
}
public class AddCollidersToParticleSystemTriggers : MonoBehaviour
{
	public Collider[] collidersToAdd;

	public ParticleSystem particleSystemToUpdate;

	private int count;

	private int index;

	private void Update()
	{
		for (count = 0; count < 6; count++)
		{
			index++;
			if (index >= collidersToAdd.Length)
			{
				if (BetterDayNightManager.instance.collidersToAddToWeatherSystems.Count >= index - collidersToAdd.Length)
				{
					index = 0;
				}
				else
				{
					particleSystemToUpdate.trigger.SetCollider(count, BetterDayNightManager.instance.collidersToAddToWeatherSystems[index - collidersToAdd.Length]);
				}
			}
			if (index < collidersToAdd.Length)
			{
				particleSystemToUpdate.trigger.SetCollider(count, collidersToAdd[index]);
			}
		}
	}
}
