public class GameBallPlayer : MonoBehaviour
{
	private struct HandData
	{
		public GameBallId grabbedGameBallId;
	}

	public VRRig rig;

	public int teamId;

	private HandData[] hands;

	public const int MAX_HANDS = 2;

	public const int LEFT_HAND = 0;

	public const int RIGHT_HAND = 1;

	private int inGoalZone;

	private void Awake()
	{
		hands = new HandData[2];
		for (int i = 0; i < 2; i++)
		{
			ClearGrabbed(i);
		}
		teamId = -1;
	}

	public void CleanupPlayer()
	{
		MonkeBallPlayer component = GetComponent<MonkeBallPlayer>();
		if (component != null)
		{
			component.currGoalZone = null;
			for (int i = 0; i < MonkeBallGame.Instance.goalZones.Count; i++)
			{
				MonkeBallGame.Instance.goalZones[i].CleanupPlayer(component);
			}
		}
	}

	public void SetGrabbed(GameBallId gameBallId, int handIndex)
	{
		if (gameBallId.IsValid())
		{
			ClearGrabbedIfHeld(gameBallId);
		}
		HandData handData = hands[handIndex];
		handData.grabbedGameBallId = gameBallId;
		hands[handIndex] = handData;
	}

	public void ClearGrabbedIfHeld(GameBallId gameBallId)
	{
		for (int i = 0; i < 2; i++)
		{
			if (hands[i].grabbedGameBallId == gameBallId)
			{
				ClearGrabbed(i);
			}
		}
	}

	public void ClearGrabbed(int handIndex)
	{
		SetGrabbed(GameBallId.Invalid, handIndex);
	}

	public void ClearAllGrabbed()
	{
		for (int i = 0; i < hands.Length; i++)
		{
			ClearGrabbed(i);
		}
	}

	public void SetInGoalZone(bool inZone)
	{
		if (inZone)
		{
			inGoalZone++;
		}
		else
		{
			inGoalZone--;
		}
	}

	public bool IsHoldingBall()
	{
		return GetGameBallId().IsValid();
	}

	public GameBallId GetGameBallId(int handIndex)
	{
		return hands[handIndex].grabbedGameBallId;
	}

	public int FindHandIndex(GameBallId gameBallId)
	{
		for (int i = 0; i < hands.Length; i++)
		{
			if (hands[i].grabbedGameBallId == gameBallId)
			{
				return i;
			}
		}
		return -1;
	}

	public GameBallId GetGameBallId()
	{
		for (int i = 0; i < hands.Length; i++)
		{
			if (hands[i].grabbedGameBallId.IsValid())
			{
				return hands[i].grabbedGameBallId;
			}
		}
		return GameBallId.Invalid;
	}

	public bool IsLocalPlayer()
	{
		return VRRigCache.Instance.localRig.Creator.ActorNumber == rig.OwningNetPlayer.ActorNumber;
	}

	public static bool IsLeftHand(int handIndex)
	{
		return handIndex == 0;
	}

	public static int GetHandIndex(bool leftHand)
	{
		if (!leftHand)
		{
			return 1;
		}
		return 0;
	}

	public static VRRig GetRig(int actorNumber)
	{
		NetPlayer player = NetworkSystem.Instance.GetPlayer(actorNumber);
		if (player == null || player.IsNull || !VRRigCache.Instance.TryGetVrrig(player, out var playerRig))
		{
			return null;
		}
		return playerRig.Rig;
	}

	public static GameBallPlayer GetGamePlayer(int actorNumber)
	{
		if (actorNumber < 0)
		{
			return null;
		}
		VRRig vRRig = GetRig(actorNumber);
		if (vRRig == null)
		{
			return null;
		}
		return vRRig.GetComponent<GameBallPlayer>();
	}

	public static GameBallPlayer GetGamePlayer(Collider collider, bool bodyOnly = false)
	{
		Transform parent = collider.transform;
		while (parent != null)
		{
			GameBallPlayer component = parent.GetComponent<GameBallPlayer>();
			if (component != null)
			{
				return component;
			}
			if (bodyOnly)
			{
				break;
			}
			parent = parent.parent;
		}
		return null;
	}
}
public class GameBallPlayerLocal : MonoBehaviour
{
	private enum HandGrabState
	{
		Empty,
		Holding
	}

	private struct HandData
	{
		public HandGrabState grabState;

		public bool gripWasHeld;

		public double gripPressedTime;

		public GameBallId grabbedGameBallId;
	}

	public struct InputDataMotion
	{
		public double time;

		public UnityEngine.Vector3 position;

		public UnityEngine.Quaternion rotation;

		public UnityEngine.Vector3 velocity;

		public UnityEngine.Vector3 angVelocity;
	}

	public class InputData
	{
		public int maxInputs;

		public List<InputDataMotion> inputMotionHistory;

		public InputData(int maxInputs)
		{
			this.maxInputs = maxInputs;
			inputMotionHistory = new List<InputDataMotion>(maxInputs);
		}

		public void AddInput(InputDataMotion data)
		{
			if (inputMotionHistory.Count >= maxInputs)
			{
				inputMotionHistory.RemoveAt(0);
			}
			inputMotionHistory.Add(data);
		}

		public float GetMaxSpeed(float ignoreRecent, float window)
		{
			double timeAsDouble = Time.timeAsDouble;
			double num = timeAsDouble - (double)ignoreRecent - (double)window;
			double num2 = timeAsDouble - (double)ignoreRecent;
			float num3 = 0f;
			for (int num4 = inputMotionHistory.Count - 1; num4 >= 0; num4--)
			{
				InputDataMotion inputDataMotion = inputMotionHistory[num4];
				if (!(inputDataMotion.time > num2))
				{
					if (inputDataMotion.time < num)
					{
						break;
					}
					float sqrMagnitude = inputDataMotion.velocity.sqrMagnitude;
					if (sqrMagnitude > num3)
					{
						num3 = sqrMagnitude;
					}
				}
			}
			return Mathf.Sqrt(num3);
		}

		public UnityEngine.Vector3 GetAvgVel(float ignoreRecent, float window)
		{
			double timeAsDouble = Time.timeAsDouble;
			double num = timeAsDouble - (double)ignoreRecent - (double)window;
			double num2 = timeAsDouble - (double)ignoreRecent;
			UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
			int num3 = 0;
			for (int num4 = inputMotionHistory.Count - 1; num4 >= 0; num4--)
			{
				InputDataMotion inputDataMotion = inputMotionHistory[num4];
				if (!(inputDataMotion.time > num2))
				{
					if (inputDataMotion.time < num)
					{
						break;
					}
					zero += inputDataMotion.velocity;
					num3++;
				}
			}
			if (num3 == 0)
			{
				return UnityEngine.Vector3.zero;
			}
			return zero / num3;
		}
	}

	public GameBallPlayer gamePlayer;

	private const int MAX_INPUT_HISTORY = 32;

	private HandData[] hands;

	private InputData[] inputData;

	[OnEnterPlay_SetNull]
	public static volatile GameBallPlayerLocal instance;

	private void Awake()
	{
		instance = this;
		hands = new HandData[2];
		inputData = new InputData[2];
		for (int i = 0; i < inputData.Length; i++)
		{
			inputData[i] = new InputData(32);
		}
		UnityEngine.Application.quitting += _OnApplicationQuit;
	}

	private static void _OnApplicationQuit()
	{
		if (MonkeBallGame.Instance != null)
		{
			MonkeBallGame.Instance.OnPlayerDestroy();
		}
	}

	private void OnApplicationPause(bool pause)
	{
		if (pause && MonkeBallGame.Instance != null)
		{
			MonkeBallGame.Instance.OnPlayerDestroy();
		}
	}

	private void OnDestroy()
	{
		if (!ApplicationQuittingState.IsQuitting && MonkeBallGame.Instance != null)
		{
			MonkeBallGame.Instance.OnPlayerDestroy();
		}
	}

	public void OnUpdateInteract()
	{
		if (ZoneManagement.IsInZone(GTZone.arena))
		{
			for (int i = 0; i < inputData.Length; i++)
			{
				UpdateInput(i);
			}
			for (int j = 0; j < hands.Length; j++)
			{
				UpdateHand(j);
			}
		}
	}

	private void UpdateInput(int handIndex)
	{
		XRNode xRNode = GetXRNode(handIndex);
		InputDataMotion data = default(InputDataMotion);
		UnityEngine.XR.InputDevice deviceAtXRNode = InputDevices.GetDeviceAtXRNode(xRNode);
		deviceAtXRNode.TryGetFeatureValue(UnityEngine.XR.CommonUsages.devicePosition, out data.position);
		deviceAtXRNode.TryGetFeatureValue(UnityEngine.XR.CommonUsages.deviceRotation, out data.rotation);
		deviceAtXRNode.TryGetFeatureValue(UnityEngine.XR.CommonUsages.deviceVelocity, out data.velocity);
		deviceAtXRNode.TryGetFeatureValue(UnityEngine.XR.CommonUsages.deviceAngularVelocity, out data.angVelocity);
		data.time = Time.timeAsDouble;
		inputData[handIndex].AddInput(data);
	}

	private void UpdateHand(int handIndex)
	{
		if (!(GameBallManager.Instance == null))
		{
			if (!gamePlayer.GetGameBallId(handIndex).IsValid())
			{
				UpdateHandEmpty(handIndex);
			}
			else
			{
				UpdateHandHolding(handIndex);
			}
		}
	}

	public void SetGrabbed(GameBallId gameBallId, int handIndex)
	{
		HandData handData = hands[handIndex];
		handData.gripPressedTime = 0.0;
		hands[handIndex] = handData;
		UpdateStuckState();
	}

	public void ClearGrabbed(int handIndex)
	{
		SetGrabbed(GameBallId.Invalid, handIndex);
	}

	public void ClearAllGrabbed()
	{
		for (int i = 0; i < hands.Length; i++)
		{
			ClearGrabbed(i);
		}
	}

	private void UpdateStuckState()
	{
		bool disableMovement = false;
		for (int i = 0; i < hands.Length; i++)
		{
			if (gamePlayer.GetGameBallId(i).IsValid())
			{
				disableMovement = true;
				break;
			}
		}
		GTPlayer.Instance.disableMovement = disableMovement;
	}

	private void UpdateHandEmpty(int handIndex)
	{
		HandData handData = hands[handIndex];
		bool flag = ControllerInputPoller.GripFloat(GetXRNode(handIndex)) > 0.7f;
		double timeAsDouble = Time.timeAsDouble;
		if (flag && !handData.gripWasHeld)
		{
			handData.gripPressedTime = timeAsDouble;
		}
		double num = timeAsDouble - handData.gripPressedTime;
		handData.gripWasHeld = flag;
		hands[handIndex] = handData;
		if (!flag || !(num < 0.15000000596046448))
		{
			return;
		}
		UnityEngine.Vector3 position = GetHandTransform(handIndex).position;
		GameBallId gameBallId = GameBallManager.Instance.TryGrabLocal(position, gamePlayer.teamId);
		float num2 = 0.15f;
		if (gameBallId.IsValid())
		{
			bool flag2 = IsLeftHand(handIndex);
			BodyDockPositions myBodyDockPositions = GorillaTagger.Instance.offlineVRRig.myBodyDockPositions;
			Transform obj = (flag2 ? myBodyDockPositions.leftHandTransform : myBodyDockPositions.rightHandTransform);
			GameBall gameBall = GameBallManager.Instance.GetGameBall(gameBallId);
			UnityEngine.Vector3 position2 = gameBall.transform.position;
			UnityEngine.Vector3 vector = gameBall.transform.position - position;
			if (vector.sqrMagnitude > num2 * num2)
			{
				position2 = position + vector.normalized * num2;
			}
			UnityEngine.Vector3 localPosition = obj.InverseTransformPoint(position2);
			UnityEngine.Quaternion localRotation = UnityEngine.Quaternion.Inverse(obj.rotation) * gameBall.transform.rotation;
			obj.InverseTransformPoint(gameBall.transform.position);
			GameBallManager.Instance.RequestGrabBall(gameBallId, flag2, localPosition, localRotation);
		}
	}

	private void UpdateHandHolding(int handIndex)
	{
		XRNode xRNode = GetXRNode(handIndex);
		if (ControllerInputPoller.GripFloat(xRNode) > 0.7f)
		{
			return;
		}
		UnityEngine.XR.InputDevice deviceAtXRNode = InputDevices.GetDeviceAtXRNode(xRNode);
		deviceAtXRNode.TryGetFeatureValue(UnityEngine.XR.CommonUsages.deviceAngularVelocity, out var value);
		deviceAtXRNode.TryGetFeatureValue(UnityEngine.XR.CommonUsages.deviceRotation, out var value2);
		Transform transform = GorillaTagger.Instance.offlineVRRig.transform;
		UnityEngine.Quaternion rotation = GTPlayer.Instance.turnParent.transform.rotation;
		InputData inputData = this.inputData[handIndex];
		UnityEngine.Vector3 vector = inputData.GetMaxSpeed(0f, 0.05f) * inputData.GetAvgVel(0f, 0.05f).normalized;
		vector = rotation * vector;
		vector *= transform.localScale.x;
		value = rotation * -(UnityEngine.Quaternion.Inverse(value2) * value);
		GameBallId gameBallId = gamePlayer.GetGameBallId(handIndex);
		GameBall gameBall = GameBallManager.Instance.GetGameBall(gameBallId);
		if (!(gameBall == null) && !gameBall.IsLaunched)
		{
			if (gameBall.disc)
			{
				UnityEngine.Vector3 vector2 = gameBall.transform.rotation * gameBall.localDiscUp;
				vector2.Normalize();
				float num = UnityEngine.Vector3.Dot(vector2, value);
				value = vector2 * num;
				value *= 1.25f;
				vector *= 1.25f;
			}
			else
			{
				vector *= 1.5f;
			}
			GorillaVelocityTracker bodyVelocityTracker = GTPlayer.Instance.bodyVelocityTracker;
			vector += bodyVelocityTracker.GetAverageVelocity(worldSpace: true, 0.05f);
			GameBallManager.Instance.RequestThrowBall(gameBallId, IsLeftHand(handIndex), vector, value);
		}
	}

	private XRNode GetXRNode(int handIndex)
	{
		if (handIndex != 0)
		{
			return XRNode.RightHand;
		}
		return XRNode.LeftHand;
	}

	private Transform GetHandTransform(int handIndex)
	{
		BodyDockPositions myBodyDockPositions = GorillaTagger.Instance.offlineVRRig.myBodyDockPositions;
		return ((handIndex == 0) ? myBodyDockPositions.leftHandTransform : myBodyDockPositions.rightHandTransform).parent;
	}

	public static bool IsLeftHand(int handIndex)
	{
		return handIndex == 0;
	}

	public static int GetHandIndex(bool leftHand)
	{
		if (!leftHand)
		{
			return 1;
		}
		return 0;
	}

	public void PlayCatchFx(bool isLeftHand)
	{
		GorillaTagger.Instance.StartVibration(isLeftHand, GorillaTagger.Instance.tapHapticStrength, 0.1f);
	}

	public void PlayThrowFx(bool isLeftHand)
	{
		GorillaTagger.Instance.StartVibration(isLeftHand, GorillaTagger.Instance.tapHapticStrength * 0.15f, 0.1f);
	}
}
public class MonkeBall : MonoBehaviourTick
{
	public GameBall gameBall;

	public MeshRenderer mainRenderer;

	public Material defaultMaterial;

	public Material[] teamMaterial;

	public double restrictTeamGrabEndTime;

	public bool alreadyDropped;

	private bool _justGrabbed;

	private float _justGrabbedTimer;

	private bool _launchAfterScore;

	private float _droppedTimer;

	private bool _resyncPosition;

	private float _resyncDelay;

	private bool _visualOffset;

	private float _offsetThreshold = 0.05f;

	private float _timeOffset;

	public float maxLerpTime = 0.5f;

	public float offsetLerp = 0.2f;

	private bool _positionFailsafe = true;

	private float _positionFailsafeTimer;

	public UnityEngine.Vector3 lastVisiblePosition;

	[SerializeField]
	private Rigidbody _rigidBody;

	private void Start()
	{
		Refresh();
	}

	public override void Tick()
	{
		UpdateVisualOffset();
		if (!PhotonNetwork.IsMasterClient)
		{
			if (_resyncPosition)
			{
				_resyncDelay -= Time.deltaTime;
				if (_resyncDelay <= 0f)
				{
					_resyncPosition = false;
					GameBallManager.Instance.RequestSetBallPosition(gameBall.id);
				}
			}
			if (_positionFailsafe)
			{
				if (base.transform.position.y < -500f || (GameBallManager.Instance.transform.position - base.transform.position).sqrMagnitude > 6400f)
				{
					if (PhotonNetwork.IsConnected)
					{
						GameBallManager.Instance.RequestSetBallPosition(gameBall.id);
					}
					else
					{
						base.transform.position = GameBallManager.Instance.transform.position;
					}
					_positionFailsafe = false;
					_positionFailsafeTimer = 3f;
				}
			}
			else
			{
				_positionFailsafeTimer -= Time.deltaTime;
				if (_positionFailsafeTimer <= 0f)
				{
					_positionFailsafe = true;
				}
			}
			return;
		}
		if (gameBall.onlyGrabTeamId != -1 && Time.timeAsDouble >= restrictTeamGrabEndTime)
		{
			MonkeBallGame.Instance.RequestRestrictBallToTeam(gameBall.id, -1);
		}
		if (AlreadyDropped())
		{
			_droppedTimer += Time.deltaTime;
			if (_droppedTimer >= 7.5f)
			{
				_droppedTimer = 0f;
				GameBallManager.Instance.RequestTeleportBall(gameBall.id, base.transform.position, base.transform.rotation, _rigidBody.linearVelocity, _rigidBody.angularVelocity);
			}
		}
		if (_justGrabbed)
		{
			_justGrabbedTimer -= Time.deltaTime;
			if (_justGrabbedTimer <= 0f)
			{
				_justGrabbed = false;
			}
		}
		if (_resyncPosition)
		{
			_resyncDelay -= Time.deltaTime;
			if (_resyncDelay <= 0f)
			{
				_resyncPosition = false;
				GameBallManager.Instance.RequestTeleportBall(gameBall.id, base.transform.position, base.transform.rotation, _rigidBody.linearVelocity, _rigidBody.angularVelocity);
			}
		}
		if (_positionFailsafe)
		{
			if (base.transform.position.y < -250f || (GameBallManager.Instance.transform.position - base.transform.position).sqrMagnitude > 6400f)
			{
				MonkeBallGame.Instance.LaunchBallNeutral(gameBall.id);
				_positionFailsafe = false;
				_positionFailsafeTimer = 3f;
			}
		}
		else
		{
			_positionFailsafeTimer -= Time.deltaTime;
			if (_positionFailsafeTimer <= 0f)
			{
				_positionFailsafe = true;
			}
		}
	}

	public void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (AlreadyDropped() || _justGrabbed || IsGamePlayer(collision.collider))
		{
			return;
		}
		alreadyDropped = true;
		_droppedTimer = 0f;
		gameBall.PlayBounceFX();
		if (PhotonNetwork.IsMasterClient)
		{
			if (_rigidBody.linearVelocity.sqrMagnitude > 1f)
			{
				_resyncPosition = true;
				_resyncDelay = 0.5f;
			}
			if (_launchAfterScore)
			{
				_launchAfterScore = false;
				MonkeBallGame.Instance.RequestRestrictBallToTeamOnScore(gameBall.id, MonkeBallGame.Instance.GetOtherTeam(gameBall.lastHeldByTeamId));
			}
			else
			{
				MonkeBallGame.Instance.RequestRestrictBallToTeam(gameBall.id, MonkeBallGame.Instance.GetOtherTeam(gameBall.lastHeldByTeamId));
			}
		}
		else
		{
			if (_rigidBody.linearVelocity.sqrMagnitude > 1f)
			{
				_resyncPosition = true;
				_resyncDelay = 1.5f;
			}
			_ = gameBall.lastHeldByActorNumber;
			_ = PhotonNetwork.LocalPlayer.ActorNumber;
		}
	}

	public void TriggerDelayedResync()
	{
		_resyncPosition = true;
		if (PhotonNetwork.IsMasterClient)
		{
			_resyncDelay = 0.5f;
		}
		else
		{
			_resyncDelay = 1.5f;
		}
	}

	public void SetRigidbodyDiscrete()
	{
		_rigidBody.collisionDetectionMode = CollisionDetectionMode.Discrete;
	}

	public void SetRigidbodyContinuous()
	{
		_rigidBody.collisionDetectionMode = CollisionDetectionMode.ContinuousSpeculative;
	}

	public static MonkeBall Get(GameBall ball)
	{
		if (ball == null)
		{
			return null;
		}
		return ball.GetComponent<MonkeBall>();
	}

	public bool AlreadyDropped()
	{
		return alreadyDropped;
	}

	public void OnGrabbed()
	{
		alreadyDropped = false;
		_justGrabbed = true;
		_justGrabbedTimer = 0.1f;
		_resyncPosition = false;
	}

	public void OnSwitchHeldByTeam(int teamId)
	{
		if (PhotonNetwork.IsMasterClient)
		{
			MonkeBallGame.Instance.RequestRestrictBallToTeam(gameBall.id, teamId);
		}
	}

	public void ClearCannotGrabTeamId()
	{
		gameBall.onlyGrabTeamId = -1;
		restrictTeamGrabEndTime = -1.0;
		Refresh();
	}

	public bool RestrictBallToTeam(int teamId, float duration)
	{
		if (teamId == gameBall.onlyGrabTeamId && Time.timeAsDouble + (double)duration < restrictTeamGrabEndTime)
		{
			return false;
		}
		gameBall.onlyGrabTeamId = teamId;
		restrictTeamGrabEndTime = Time.timeAsDouble + (double)duration;
		Refresh();
		return true;
	}

	private void Refresh()
	{
		if (gameBall.onlyGrabTeamId == -1)
		{
			mainRenderer.material = defaultMaterial;
		}
		else
		{
			mainRenderer.material = teamMaterial[gameBall.onlyGrabTeamId];
		}
	}

	private static bool IsGamePlayer(Collider collider)
	{
		return GameBallPlayer.GetGamePlayer(collider) != null;
	}

	public void SetVisualOffset(bool detach)
	{
		if (detach)
		{
			lastVisiblePosition = mainRenderer.transform.position;
			_visualOffset = true;
			_timeOffset = Time.time;
			mainRenderer.transform.SetParent(null, worldPositionStays: true);
		}
		else
		{
			ReattachVisuals();
		}
	}

	private void ReattachVisuals()
	{
		if (_visualOffset)
		{
			mainRenderer.transform.SetParent(base.transform);
			mainRenderer.transform.localPosition = UnityEngine.Vector3.zero;
			mainRenderer.transform.localRotation = UnityEngine.Quaternion.identity;
			_visualOffset = false;
		}
	}

	private void UpdateVisualOffset()
	{
		if (_visualOffset)
		{
			mainRenderer.transform.position = UnityEngine.Vector3.Lerp(mainRenderer.transform.position, _rigidBody.position, Mathf.Clamp((Time.time - _timeOffset) / maxLerpTime, offsetLerp, 1f));
			if ((mainRenderer.transform.position - _rigidBody.position).sqrMagnitude < _offsetThreshold)
			{
				ReattachVisuals();
			}
		}
	}
}
public class MonkeBallBallEjectZone : MonoBehaviour
{
	public Transform target;

	public float ejectVelocity = 15f;

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		GameBall component = collision.gameObject.GetComponent<GameBall>();
		if (component != null && collision.contacts.Length != 0)
		{
			component.SetVelocity(collision.contacts[0].impulse.normalized * ejectVelocity);
		}
	}
}
public class MonkeBallBallKillZone : MonoBehaviour
{
	private void OnTriggerEnter(Collider other)
	{
		GameBall component = other.transform.GetComponent<GameBall>();
		if (component != null)
		{
			if (!PhotonNetwork.IsMasterClient)
			{
				MonkeBallGame.Instance.RequestResetBall(component.id, -1);
			}
			else
			{
				GameBallManager.Instance.RequestSetBallPosition(component.id);
			}
		}
	}
}
public class MonkeBallBallResetTrigger : MonoBehaviour
{
	public Renderer trigger;

	public Material[] teamMaterials;

	public Material neutralMaterial;

	private GameBall _lastBall;

	private void OnTriggerEnter(Collider other)
	{
		GameBall component = other.transform.GetComponent<GameBall>();
		if (!(component != null))
		{
			return;
		}
		GameBallPlayer gameBallPlayer = ((component.heldByActorNumber < 0) ? null : GameBallPlayer.GetGamePlayer(component.heldByActorNumber));
		if (gameBallPlayer == null)
		{
			gameBallPlayer = ((component.lastHeldByActorNumber < 0) ? null : GameBallPlayer.GetGamePlayer(component.lastHeldByActorNumber));
			if (gameBallPlayer == null)
			{
				return;
			}
		}
		_lastBall = component;
		int num = gameBallPlayer.teamId;
		if (num == -1)
		{
			num = component.lastHeldByTeamId;
		}
		if (num >= 0 && num < teamMaterials.Length)
		{
			trigger.sharedMaterial = teamMaterials[num];
		}
		if (PhotonNetwork.IsMasterClient)
		{
			MonkeBallGame.Instance.ToggleResetButton(toggle: true, num);
		}
	}

	private void OnTriggerExit(Collider other)
	{
		GameBall component = other.transform.GetComponent<GameBall>();
		if (component != null)
		{
			if (component == _lastBall)
			{
				trigger.sharedMaterial = neutralMaterial;
				_lastBall = null;
			}
			if (PhotonNetwork.IsMasterClient)
			{
				MonkeBallGame.Instance.ToggleResetButton(toggle: false, -1);
			}
		}
	}
}
