	{
		if (IsMasterClient() && teamId >= 0 && teamId < team.Count)
		{
			photonView.RPC("SetScoreRPC", RpcTarget.All, teamId, team[teamId].score + 1);
			RequestGameState(GameState.PostScore);
		}
