	private void RestrictBallToTeam(GameBallId gameBallId, int teamId, float restrictDuration)
	{
		if (IsMasterClient())
		{
			photonView.RPC("SetRestrictBallToTeam", RpcTarget.All, gameBallId.index, teamId, restrictDuration);
		}
