	private BuilderPiece piece;

	[SerializeField]
	private GameObject waterVolume;

	[SerializeField]
	private GameObject waterMesh;

	[FormerlySerializedAs("lillyPads")]
	[SerializeField]
	private Transform floatingObjects;

