public class BuilderConveyor : MonoBehaviour
{
	[Header("Set Selection")]
	[SerializeField]
	private BuilderSetSelector setSelector;

	public List<BuilderPieceSet.BuilderPieceCategory> _includeCategories;

	[HideInInspector]
	public BuilderTable table;

	public int shelfID = -1;

	[Header("Conveyor Properties")]
	[SerializeField]
	private Transform spawnTransform;

	[SerializeField]
	private SplineContainer spline;

	private float conveyorMoveSpeed = 0.2f;

	private float spawnDelay = 1.5f;

	private double nextSpawnTime;

	private int nextPieceToSpawn;

	private BuilderPieceSet.BuilderDisplayGroup currentDisplayGroup;

	private int loopCount;

	private List<BuilderPieceSet.PieceInfo> piecesInSet = new List<BuilderPieceSet.PieceInfo>(10);

	private Queue<int> grabbedPieceTypes;

	private Queue<int> grabbedPieceMaterials;

	private List<BuilderPiece> piecesOnConveyor = new List<BuilderPiece>(10);

	private UnityEngine.Vector3 moveDirection;

	private bool waitForResourceChange;

	private bool initialized;

	private float splineLength = 1f;

	private int maxItemsOnSpline;

	private UnityEngine.Splines.BezierCurve _evaluateCurve;

	public NativeSpline nativeSpline;

	private bool shouldVerifySetSelection;

	private void Start()
	{
		InitIfNeeded();
	}

	public void Setup()
	{
		InitIfNeeded();
	}

	private void InitIfNeeded()
	{
		if (initialized)
		{
			return;
		}
		nextPieceToSpawn = 0;
		grabbedPieceTypes = new Queue<int>(10);
		grabbedPieceMaterials = new Queue<int>(10);
		setSelector.Setup(_includeCategories);
		currentDisplayGroup = setSelector.GetSelectedGroup();
		piecesInSet.Clear();
		foreach (BuilderPieceSet.BuilderPieceSubset pieceSubset in currentDisplayGroup.pieceSubsets)
		{
			if (_includeCategories.Contains(pieceSubset.pieceCategory))
			{
				piecesInSet.AddRange(pieceSubset.pieceInfos);
			}
		}
		double timeAsDouble = Time.timeAsDouble;
		nextSpawnTime = timeAsDouble + (double)spawnDelay;
		setSelector.OnSelectedGroup.AddListener(OnSelectedSetChange);
		initialized = true;
		splineLength = spline.Splines[0].GetLength();
		maxItemsOnSpline = Mathf.RoundToInt(splineLength / (conveyorMoveSpeed * spawnDelay)) + 5;
		nativeSpline = new NativeSpline(spline.Splines[0], spline.transform.localToWorldMatrix, Unity.Collections.Allocator.Persistent);
	}

	public int GetMaxItemsOnConveyor()
	{
		return Mathf.RoundToInt(splineLength / (conveyorMoveSpeed * spawnDelay)) + 5;
	}

	public float GetFrameMovement()
	{
		return conveyorMoveSpeed / splineLength;
	}

	private void OnDestroy()
	{
		if (setSelector != null)
		{
			setSelector.OnSelectedGroup.RemoveListener(OnSelectedSetChange);
		}
		nativeSpline.Dispose();
	}

	public void OnSelectedSetChange(int displayGroupID)
	{
		if (table.GetTableState() == BuilderTable.TableState.Ready)
		{
			table.RequestShelfSelection(shelfID, displayGroupID, isConveyor: true);
		}
	}

	public void SetSelection(int displayGroupID)
	{
		setSelector.SetSelection(displayGroupID);
		currentDisplayGroup = setSelector.GetSelectedGroup();
		piecesInSet.Clear();
		foreach (BuilderPieceSet.BuilderPieceSubset pieceSubset in currentDisplayGroup.pieceSubsets)
		{
			if (_includeCategories.Contains(pieceSubset.pieceCategory))
			{
				piecesInSet.AddRange(pieceSubset.pieceInfos);
			}
		}
		nextPieceToSpawn = 0;
		loopCount = 0;
	}

	public int GetSelectedDisplayGroupID()
	{
		return setSelector.GetSelectedGroup().GetDisplayGroupIdentifier();
	}

	public void UpdateConveyor()
	{
		if (!initialized)
		{
			Setup();
		}
		for (int num = piecesOnConveyor.Count - 1; num >= 0; num--)
		{
			BuilderPiece builderPiece = piecesOnConveyor[num];
			if (builderPiece.state != BuilderPiece.State.OnConveyor)
			{
				if (PhotonNetwork.LocalPlayer.IsMasterClient && builderPiece.state != BuilderPiece.State.None)
				{
					grabbedPieceTypes.Enqueue(builderPiece.pieceType);
					grabbedPieceMaterials.Enqueue(builderPiece.materialType);
				}
				builderPiece.shelfOwner = -1;
				piecesOnConveyor.RemoveAt(num);
				table.conveyorManager.RemovePieceFromJob(builderPiece);
			}
		}
	}

	public void RemovePieceFromConveyor(Transform pieceTransform)
	{
		foreach (BuilderPiece item in piecesOnConveyor)
		{
			if (item.transform == pieceTransform)
			{
				piecesOnConveyor.Remove(item);
				item.shelfOwner = -1;
				table.RequestRecyclePiece(item, playFX: false, -1);
				break;
			}
		}
	}

	private UnityEngine.Vector3 EvaluateSpline(float t)
	{
		_evaluateCurve = nativeSpline.GetCurve(nativeSpline.SplineToCurveT(t, out var curveT));
		return CurveUtility.EvaluatePosition(_evaluateCurve, curveT);
	}

	public void UpdateShelfSliced()
	{
		if (!PhotonNetwork.LocalPlayer.IsMasterClient)
		{
			return;
		}
		if (shouldVerifySetSelection)
		{
			BuilderPieceSet.BuilderDisplayGroup selectedGroup = setSelector.GetSelectedGroup();
			if (selectedGroup == null || !BuilderSetManager.instance.DoesAnyPlayerInRoomOwnPieceSet(selectedGroup.setID))
			{
				int defaultGroupID = setSelector.GetDefaultGroupID();
				if (defaultGroupID != -1)
				{
					OnSelectedSetChange(defaultGroupID);
				}
			}
			shouldVerifySetSelection = false;
		}
		if (!waitForResourceChange)
		{
			double timeAsDouble = Time.timeAsDouble;
			if (timeAsDouble >= nextSpawnTime)
			{
				SpawnNextPiece();
				nextSpawnTime = timeAsDouble + (double)spawnDelay;
			}
		}
	}

	public void VerifySetSelection()
	{
		shouldVerifySetSelection = true;
	}

	public void OnAvailableResourcesChange()
	{
		waitForResourceChange = false;
	}

	public Transform GetSpawnTransform()
	{
		return spawnTransform;
	}

	public void OnShelfPieceCreated(BuilderPiece piece, float timeOffset)
	{
		float num = timeOffset * conveyorMoveSpeed / splineLength;
		if (num > 1f)
		{
			UnityEngine.Debug.LogWarningFormat("Piece {0} add to shelf time {1}", piece.pieceId, num);
		}
		_ = piecesOnConveyor.Count;
		piecesOnConveyor.Add(piece);
		float num2 = Mathf.Clamp(num, 0f, 1f);
		UnityEngine.Vector3 vector = EvaluateSpline(num2);
		UnityEngine.Quaternion rotation = spawnTransform.rotation * UnityEngine.Quaternion.Euler(piece.desiredShelfRotationOffset);
		UnityEngine.Vector3 position = vector + spawnTransform.rotation * piece.desiredShelfOffset;
		piece.transform.SetPositionAndRotation(position, rotation);
		if (num <= 1f)
		{
			table.conveyorManager.AddPieceToJob(piece, num2, shelfID);
		}
	}

	public void OnShelfPieceRecycled(BuilderPiece piece)
	{
		piecesOnConveyor.Remove(piece);
		if (piece != null)
		{
			table.conveyorManager.RemovePieceFromJob(piece);
		}
	}

	public void OnClearTable()
	{
		piecesOnConveyor.Clear();
		grabbedPieceTypes.Clear();
		grabbedPieceMaterials.Clear();
	}

	public void ResetConveyorState()
	{
		for (int num = piecesOnConveyor.Count - 1; num >= 0; num--)
		{
			BuilderPiece builderPiece = piecesOnConveyor[num];
			if (!(builderPiece == null))
			{
				BuilderTable.BuilderCommand cmd = new BuilderTable.BuilderCommand
				{
					type = BuilderTable.BuilderCommandType.Recycle,
					pieceId = builderPiece.pieceId,
					localPosition = builderPiece.transform.position,
					localRotation = builderPiece.transform.rotation,
					player = NetworkSystem.Instance.LocalPlayer,
					isLeft = false,
					parentPieceId = -1
				};
				table.ExecutePieceRecycled(cmd);
			}
		}
		OnClearTable();
	}

	private void SpawnNextPiece()
	{
		FindNextAffordablePieceType(out var pieceType, out var materialType);
		if (pieceType != -1)
		{
			table.RequestCreateConveyorPiece(pieceType, materialType, shelfID);
		}
	}

	private void FindNextAffordablePieceType(out int pieceType, out int materialType)
	{
		if (grabbedPieceTypes.Count > 0)
		{
			pieceType = grabbedPieceTypes.Dequeue();
			materialType = grabbedPieceMaterials.Dequeue();
			return;
		}
		pieceType = -1;
		materialType = -1;
		if (piecesInSet.Count <= 0)
		{
			return;
		}
		for (int i = nextPieceToSpawn; i < piecesInSet.Count; i++)
		{
			BuilderPiece piecePrefab = piecesInSet[i].piecePrefab;
			if (table.HasEnoughResources(piecePrefab))
			{
				if (i + 1 >= piecesInSet.Count)
				{
					loopCount++;
					loopCount = Mathf.Max(0, loopCount);
				}
				nextPieceToSpawn = (i + 1) % piecesInSet.Count;
				pieceType = piecePrefab.name.GetStaticHash();
				materialType = GetMaterialType(piecesInSet[i]);
				return;
			}
		}
		loopCount++;
		loopCount = Mathf.Max(0, loopCount);
		for (int j = 0; j < nextPieceToSpawn; j++)
		{
			BuilderPiece piecePrefab2 = piecesInSet[j].piecePrefab;
			if (table.HasEnoughResources(piecePrefab2))
			{
				nextPieceToSpawn = (j + 1) % piecesInSet.Count;
				pieceType = piecePrefab2.name.GetStaticHash();
				materialType = GetMaterialType(piecesInSet[j]);
				return;
			}
		}
		waitForResourceChange = true;
	}

	private int GetMaterialType(BuilderPieceSet.PieceInfo info)
	{
		if (info.piecePrefab.materialOptions != null && info.overrideSetMaterial && info.pieceMaterialTypes.Length != 0)
		{
			int num = loopCount % info.pieceMaterialTypes.Length;
			string text = info.pieceMaterialTypes[num];
			if (string.IsNullOrEmpty(text))
			{
				UnityEngine.Debug.LogErrorFormat("Empty Material Override for piece {0} in set {1}", info.piecePrefab.name, currentDisplayGroup.displayName);
				return -1;
			}
			return text.GetHashCode();
		}
		if (string.IsNullOrEmpty(currentDisplayGroup.defaultMaterial))
		{
			return -1;
		}
		return currentDisplayGroup.defaultMaterial.GetHashCode();
	}
}
public class BuilderDispenser : MonoBehaviour
{
	public Transform displayTransform;

	public Transform spawnTransform;

	public Animation animateParent;

	public AnimationClip dispenseDefaultAnimation;

	public GameObject dispenserFX;

	private AnimationClip currentAnimation;

	[HideInInspector]
	public BuilderTable table;

	[HideInInspector]
	public int shelfID;

	private BuilderPieceSet.PieceInfo pieceToSpawn;

	private BuilderPiece spawnedPieceInstance;

	private int materialType = -1;

	private BuilderPieceSet.PieceInfo nullPiece;

	private int spawnCount;

	private double nextSpawnTime;

	private bool hasPiece;

	private float OnGrabSpawnDelay = 0.5f;

	private float spawnRetryDelay = 2f;

	private bool playFX;

	private void Awake()
	{
		nullPiece = new BuilderPieceSet.PieceInfo
		{
			piecePrefab = null,
			overrideSetMaterial = false
		};
	}

	public void UpdateDispenser()
	{
		if (!PhotonNetwork.IsMasterClient)
		{
			return;
		}
		if (!hasPiece && Time.timeAsDouble > nextSpawnTime && pieceToSpawn.piecePrefab != null)
		{
			TrySpawnPiece();
			nextSpawnTime = Time.timeAsDouble + (double)spawnRetryDelay;
		}
		else if (hasPiece && (spawnedPieceInstance == null || (spawnedPieceInstance.state != BuilderPiece.State.OnShelf && spawnedPieceInstance.state != BuilderPiece.State.Displayed)))
		{
			StopAllCoroutines();
			if (spawnedPieceInstance != null)
			{
				spawnedPieceInstance.shelfOwner = -1;
			}
			nextSpawnTime = Time.timeAsDouble + (double)OnGrabSpawnDelay;
			spawnedPieceInstance = null;
			hasPiece = false;
		}
	}

	public bool DoesPieceMatchSpawnInfo(BuilderPiece piece)
	{
		if (piece == null || pieceToSpawn.piecePrefab == null)
		{
			return false;
		}
		if (piece.pieceType != pieceToSpawn.piecePrefab.name.GetStaticHash())
		{
			return false;
		}
		if (!(piece.materialOptions != null))
		{
			return true;
		}
		int num = piece.materialType;
		piece.materialOptions.GetDefaultMaterial(out var num2, out var _, out var _);
		if (pieceToSpawn.overrideSetMaterial)
		{
			for (int i = 0; i < pieceToSpawn.pieceMaterialTypes.Length; i++)
			{
				string text = pieceToSpawn.pieceMaterialTypes[i];
				if (!string.IsNullOrEmpty(text))
				{
					int hashCode = text.GetHashCode();
					if (hashCode == num)
					{
						return true;
					}
					if (hashCode == num2 && num == -1)
					{
						return true;
					}
				}
				else if (num == -1 || num == num2)
				{
					return true;
				}
			}
		}
		else if (num == materialType || (materialType == num2 && num == -1) || (num == num2 && materialType == -1))
		{
			return true;
		}
		return false;
	}

	public void ShelfPieceCreated(BuilderPiece piece, bool playAnimation)
	{
		if (!DoesPieceMatchSpawnInfo(piece))
		{
			return;
		}
		if (hasPiece && spawnedPieceInstance != null)
		{
			spawnedPieceInstance.shelfOwner = -1;
		}
		spawnedPieceInstance = piece;
		hasPiece = true;
		spawnCount++;
		spawnCount = Mathf.Max(0, spawnCount);
		if (table.GetTableState() == BuilderTable.TableState.Ready && playAnimation)
		{
			StartCoroutine(PlayAnimation());
			if (playFX)
			{
				ObjectPools.instance.Instantiate(dispenserFX, spawnTransform.position, spawnTransform.rotation);
			}
			else
			{
				playFX = true;
			}
		}
		else
		{
			UnityEngine.Vector3 desiredShelfOffset = pieceToSpawn.piecePrefab.desiredShelfOffset;
			UnityEngine.Vector3 position = displayTransform.position + displayTransform.rotation * desiredShelfOffset;
			UnityEngine.Quaternion rotation = displayTransform.rotation * UnityEngine.Quaternion.Euler(pieceToSpawn.piecePrefab.desiredShelfRotationOffset);
			spawnedPieceInstance.transform.SetPositionAndRotation(position, rotation);
			spawnedPieceInstance.SetState(BuilderPiece.State.OnShelf);
			playFX = true;
		}
	}

	private IEnumerator PlayAnimation()
	{
		spawnedPieceInstance.SetState(BuilderPiece.State.Displayed);
		animateParent.Rewind();
		spawnedPieceInstance.transform.SetParent(animateParent.transform);
		spawnedPieceInstance.transform.SetLocalPositionAndRotation(pieceToSpawn.piecePrefab.desiredShelfOffset, UnityEngine.Quaternion.Euler(pieceToSpawn.piecePrefab.desiredShelfRotationOffset));
		animateParent.Play();
		yield return new WaitForSeconds(animateParent.clip.length);
		if (spawnedPieceInstance != null && spawnedPieceInstance.state == BuilderPiece.State.Displayed)
		{
			spawnedPieceInstance.transform.SetParent(null);
			UnityEngine.Vector3 desiredShelfOffset = pieceToSpawn.piecePrefab.desiredShelfOffset;
			UnityEngine.Vector3 position = displayTransform.position + displayTransform.rotation * desiredShelfOffset;
			UnityEngine.Quaternion rotation = displayTransform.rotation * UnityEngine.Quaternion.Euler(pieceToSpawn.piecePrefab.desiredShelfRotationOffset);
			spawnedPieceInstance.transform.SetPositionAndRotation(position, rotation);
			spawnedPieceInstance.SetState(BuilderPiece.State.OnShelf);
		}
	}

	public void ShelfPieceRecycled(BuilderPiece piece)
	{
		if (piece != null && spawnedPieceInstance != null && piece.Equals(spawnedPieceInstance))
		{
			piece.shelfOwner = -1;
			spawnedPieceInstance = null;
			hasPiece = false;
			nextSpawnTime = Time.timeAsDouble + (double)OnGrabSpawnDelay;
		}
	}

	public void AssignPieceType(BuilderPieceSet.PieceInfo piece, int inMaterialType)
	{
		playFX = false;
		pieceToSpawn = piece;
		materialType = inMaterialType;
		nextSpawnTime = Time.timeAsDouble + (double)OnGrabSpawnDelay;
		currentAnimation = dispenseDefaultAnimation;
		animateParent.clip = currentAnimation;
		spawnCount = 0;
	}

	private void TrySpawnPiece()
	{
		if ((!(spawnedPieceInstance != null) || spawnedPieceInstance.state != BuilderPiece.State.OnShelf) && !(pieceToSpawn.piecePrefab == null) && table.HasEnoughResources(pieceToSpawn.piecePrefab))
		{
			UnityEngine.Vector3 desiredShelfOffset = pieceToSpawn.piecePrefab.desiredShelfOffset;
			UnityEngine.Vector3 position = spawnTransform.position + spawnTransform.rotation * desiredShelfOffset;
			UnityEngine.Quaternion rotation = spawnTransform.rotation * UnityEngine.Quaternion.Euler(pieceToSpawn.piecePrefab.desiredShelfRotationOffset);
			int num = materialType;
			if (pieceToSpawn.overrideSetMaterial && pieceToSpawn.pieceMaterialTypes.Length != 0)
			{
				int num2 = spawnCount % pieceToSpawn.pieceMaterialTypes.Length;
				string text = pieceToSpawn.pieceMaterialTypes[num2];
				num = ((!string.IsNullOrEmpty(text)) ? text.GetHashCode() : (-1));
			}
			table.RequestCreateDispenserShelfPiece(pieceToSpawn.piecePrefab.name.GetStaticHash(), position, rotation, num, shelfID);
		}
	}

	public void ParentPieceToShelf(Transform shelfTransform)
	{
		if (!(spawnedPieceInstance != null))
		{
			return;
		}
		if (spawnedPieceInstance.state != BuilderPiece.State.OnShelf && spawnedPieceInstance.state != BuilderPiece.State.Displayed)
		{
			StopAllCoroutines();
			if (spawnedPieceInstance != null)
			{
				spawnedPieceInstance.shelfOwner = -1;
			}
			nextSpawnTime = Time.timeAsDouble + (double)OnGrabSpawnDelay;
			spawnedPieceInstance = null;
			hasPiece = false;
		}
		else
		{
			spawnedPieceInstance.SetState(BuilderPiece.State.Displayed);
			spawnedPieceInstance.transform.SetParent(shelfTransform);
		}
	}

	public void ClearDispenser()
	{
		if (!PhotonNetwork.IsMasterClient)
		{
			return;
		}
		pieceToSpawn = nullPiece;
		hasPiece = false;
		if (spawnedPieceInstance != null)
		{
			if (spawnedPieceInstance.state != BuilderPiece.State.OnShelf && spawnedPieceInstance.state != BuilderPiece.State.Displayed)
			{
				spawnedPieceInstance.shelfOwner = -1;
				nextSpawnTime = Time.timeAsDouble + (double)OnGrabSpawnDelay;
				spawnedPieceInstance = null;
			}
			else
			{
				table.RequestRecyclePiece(spawnedPieceInstance, playFX: false, -1);
			}
		}
	}

	public void OnClearTable()
	{
		playFX = false;
		nextSpawnTime = 0.0;
		hasPiece = false;
		spawnedPieceInstance = null;
	}
}
public class BuilderDispenserShelf : MonoBehaviour
{
	[Header("Set Selection")]
	[SerializeField]
	private BuilderSetSelector setSelector;

	public List<BuilderPieceSet.BuilderPieceCategory> _includedCategories;

	[Header("Dispenser Shelf Properties")]
	public Transform shelfCenter;

	public float shelfWidth = 1.4f;

	public Animation resetAnimation;

	[SerializeField]
	private SoundBankPlayer resetSoundBank;

	[SerializeField]
	private AudioClip spawnNewSetSound;

	[SerializeField]
	private AudioSource audioSource;

	private bool playSpawnSetSound;

	[HideInInspector]
	public BuilderTable table;

	public int shelfID = -1;

	private BuilderPieceSet.BuilderDisplayGroup currentGroup;

	private bool initialized;

	public BuilderDispenser dispenserPrefab;

	private List<BuilderDispenser> dispenserPool;

	private List<BuilderDispenser> activeDispensers;

	private List<BuilderPieceSet.PieceInfo> piecesInSet = new List<BuilderPieceSet.PieceInfo>(10);

	private bool animatingShelf;

	private double timeToClearShelf = double.MaxValue;

	private int dispenserToClear;

	private int dispenserToUpdate;

	private bool shouldVerifySetSelection;

	private void BuildDispenserPool()
	{
		dispenserPool = new List<BuilderDispenser>(12);
		activeDispensers = new List<BuilderDispenser>(6);
		AddToDispenserPool(6);
	}

	private void AddToDispenserPool(int count)
	{
		if (!(dispenserPrefab == null))
		{
			for (int i = 0; i < count; i++)
			{
				BuilderDispenser builderDispenser = UnityEngine.Object.Instantiate(dispenserPrefab, shelfCenter);
				builderDispenser.gameObject.SetActive(value: false);
				builderDispenser.table = table;
				builderDispenser.shelfID = shelfID;
				dispenserPool.Add(builderDispenser);
			}
		}
	}

	private void ActivateDispensers()
	{
		piecesInSet.Clear();
		foreach (BuilderPieceSet.BuilderPieceSubset pieceSubset in currentGroup.pieceSubsets)
		{
			if (_includedCategories.Contains(pieceSubset.pieceCategory))
			{
				piecesInSet.AddRange(pieceSubset.pieceInfos);
			}
		}
		if (piecesInSet.Count <= 0)
		{
			return;
		}
		int count = piecesInSet.Count;
		if (dispenserPool.Count < count)
		{
			AddToDispenserPool(count - dispenserPool.Count);
		}
		activeDispensers.Clear();
		for (int i = 0; i < dispenserPool.Count; i++)
		{
			if (i < count)
			{
				BuilderDispenser builderDispenser = dispenserPool[i];
				builderDispenser.gameObject.SetActive(value: true);
				float x = shelfWidth / -2f + shelfWidth / (float)(count * 2) + shelfWidth / (float)count * (float)i;
				builderDispenser.transform.localPosition = new UnityEngine.Vector3(x, 0f, 0f);
				builderDispenser.AssignPieceType(piecesInSet[i], currentGroup.defaultMaterial.GetHashCode());
				activeDispensers.Add(builderDispenser);
			}
			else
			{
				dispenserPool[i].ClearDispenser();
				dispenserPool[i].gameObject.SetActive(value: false);
			}
		}
		dispenserToUpdate = 0;
	}

	public void Setup()
	{
		InitIfNeeded();
		foreach (BuilderDispenser item in dispenserPool)
		{
			item.table = table;
			item.shelfID = shelfID;
		}
	}

	private void InitIfNeeded()
	{
		if (!initialized)
		{
			setSelector.Setup(_includedCategories);
			currentGroup = setSelector.GetSelectedGroup();
			setSelector.OnSelectedGroup.AddListener(OnSelectedSetChange);
			BuildDispenserPool();
			ActivateDispensers();
			initialized = true;
		}
	}

	private void OnDestroy()
	{
		if (setSelector != null)
		{
			setSelector.OnSelectedGroup.RemoveListener(OnSelectedSetChange);
		}
	}

	public void OnSelectedSetChange(int displayGroupID)
	{
		if (table.GetTableState() == BuilderTable.TableState.Ready)
		{
			table.RequestShelfSelection(shelfID, displayGroupID, isConveyor: false);
		}
	}

	public void SetSelection(int displayGroupID)
	{
		setSelector.SetSelection(displayGroupID);
		BuilderPieceSet.BuilderDisplayGroup selectedGroup = setSelector.GetSelectedGroup();
		if ((!initialized || currentGroup != null) && !(selectedGroup.displayName != currentGroup.displayName))
		{
			return;
		}
		currentGroup = selectedGroup;
		if (table.GetTableState() == BuilderTable.TableState.Ready)
		{
			if (!animatingShelf)
			{
				StartShelfSwap();
			}
		}
		else
		{
			animatingShelf = false;
			ImmediateShelfSwap();
		}
	}

	public int GetSelectedDisplayGroupID()
	{
		return setSelector.GetSelectedGroup().GetDisplayGroupIdentifier();
	}

	private void ImmediateShelfSwap()
	{
		foreach (BuilderDispenser activeDispenser in activeDispensers)
		{
			activeDispenser.ClearDispenser();
		}
		ActivateDispensers();
	}

	private void StartShelfSwap()
	{
		dispenserToClear = 0;
		timeToClearShelf = Time.time + 0.15f;
		resetAnimation.Rewind();
		foreach (BuilderDispenser activeDispenser in activeDispensers)
		{
			activeDispenser.ParentPieceToShelf(resetAnimation.transform);
		}
		resetAnimation.Play();
		animatingShelf = true;
	}

	public void UpdateShelf()
	{
		if (!animatingShelf || !((double)Time.time > timeToClearShelf))
		{
			return;
		}
		if (dispenserToClear < activeDispensers.Count)
		{
			if (dispenserToClear == 0)
			{
				resetSoundBank.Play();
			}
			activeDispensers[dispenserToClear].ClearDispenser();
			dispenserToClear++;
		}
		else if (!resetAnimation.isPlaying)
		{
			playSpawnSetSound = true;
			ActivateDispensers();
			animatingShelf = false;
		}
	}

	public void UpdateShelfSliced()
	{
		if (!PhotonNetwork.LocalPlayer.IsMasterClient || !initialized || animatingShelf)
		{
			return;
		}
		if (shouldVerifySetSelection)
		{
			BuilderPieceSet.BuilderDisplayGroup selectedGroup = setSelector.GetSelectedGroup();
			if (selectedGroup == null || !BuilderSetManager.instance.DoesAnyPlayerInRoomOwnPieceSet(selectedGroup.setID))
			{
				int defaultGroupID = setSelector.GetDefaultGroupID();
				if (defaultGroupID != -1)
				{
					OnSelectedSetChange(defaultGroupID);
				}
			}
			shouldVerifySetSelection = false;
		}
		if (activeDispensers.Count > 0)
		{
			activeDispensers[dispenserToUpdate].UpdateDispenser();
			dispenserToUpdate = (dispenserToUpdate + 1) % activeDispensers.Count;
		}
	}

	public void VerifySetSelection()
	{
		shouldVerifySetSelection = true;
	}

	public void OnShelfPieceCreated(BuilderPiece piece, bool playfx)
	{
		if (playSpawnSetSound && playfx)
		{
			audioSource.GTPlayOneShot(spawnNewSetSound);
			playSpawnSetSound = false;
		}
		foreach (BuilderDispenser activeDispenser in activeDispensers)
		{
			activeDispenser.ShelfPieceCreated(piece, playfx);
		}
	}

	public void OnShelfPieceRecycled(BuilderPiece piece)
	{
		foreach (BuilderDispenser activeDispenser in activeDispensers)
		{
			activeDispenser.ShelfPieceRecycled(piece);
		}
	}

	public void OnClearTable()
	{
		if (!initialized)
		{
			return;
		}
		foreach (BuilderDispenser activeDispenser in activeDispensers)
		{
			activeDispenser.OnClearTable();
		}
		StopAllCoroutines();
		if (animatingShelf)
		{
			resetAnimation.Rewind();
			animatingShelf = false;
		}
	}

	public void ClearShelf()
	{
		foreach (BuilderDispenser activeDispenser in activeDispensers)
		{
			activeDispenser.ClearDispenser();
		}
	}
}
public class BuilderDropZone : MonoBehaviour
{
	public enum DropType
	{
		Invalid = -1,
		Repel,
		ReturnToShelf,
		BreakApart,
		Recycle
	}

	[SerializeField]
	private DropType dropType;

	[SerializeField]
	private bool onEnter = true;

	[SerializeField]
	private GameObject vfxRoot;

	[SerializeField]
	private GameObject sfxPrefab;

	public float effectDuration = 1f;

	private bool playingEffect;

	public bool overrideDirection;

	[SerializeField]
	private UnityEngine.Vector3 repelDirectionLocal = UnityEngine.Vector3.up;

	private UnityEngine.Vector3 repelDirectionWorld = UnityEngine.Vector3.up;

	[HideInInspector]
	public int dropZoneID = -1;

	internal BuilderTable table;

	private void Awake()
	{
		repelDirectionWorld = base.transform.TransformDirection(repelDirectionLocal.normalized);
	}

	private void OnTriggerEnter(Collider other)
	{
		if (!onEnter || !PhotonNetwork.IsMasterClient)
		{
			return;
		}
		BuilderPieceCollider component = other.GetComponent<BuilderPieceCollider>();
		if (!(component != null))
		{
			return;
		}
		BuilderPiece piece = component.piece;
		if (!(table != null) || !(table.builderNetworking != null) || piece == null)
		{
			return;
		}
		if (dropType == DropType.Recycle)
		{
			bool flag = piece.state != BuilderPiece.State.Displayed && piece.state != BuilderPiece.State.OnShelf && piece.state != BuilderPiece.State.AttachedAndPlaced;
			if (!piece.isBuiltIntoTable && flag)
			{
				table.builderNetworking.RequestRecyclePiece(piece.pieceId, piece.transform.position, piece.transform.rotation, playFX: true, -1);
			}
		}
		else
		{
			table.builderNetworking.PieceEnteredDropZone(piece, dropType, dropZoneID);
		}
	}

	public UnityEngine.Vector3 GetRepelDirectionWorld()
	{
		return repelDirectionWorld;
	}

	public void PlayEffect()
	{
		if (vfxRoot != null && !playingEffect)
		{
			vfxRoot.SetActive(value: true);
			playingEffect = true;
			if (sfxPrefab != null)
			{
				ObjectPools.instance.Instantiate(sfxPrefab, base.transform.position, base.transform.rotation);
			}
			StartCoroutine(DelayedStopEffect());
		}
	}

	private IEnumerator DelayedStopEffect()
	{
		yield return new WaitForSeconds(effectDuration);
		vfxRoot.SetActive(value: false);
		playingEffect = false;
	}

	private void OnTriggerExit(Collider other)
	{
		if (onEnter || !PhotonNetwork.IsMasterClient)
		{
			return;
		}
		BuilderPieceCollider component = other.GetComponent<BuilderPieceCollider>();
		if (!(component != null))
		{
			return;
		}
		BuilderPiece piece = component.piece;
		if (!(table != null) || !(table.builderNetworking != null) || piece == null)
		{
			return;
		}
		if (dropType == DropType.Recycle)
		{
			bool flag = piece.state != BuilderPiece.State.Displayed && piece.state != BuilderPiece.State.OnShelf && piece.state != BuilderPiece.State.AttachedAndPlaced;
			if (!piece.isBuiltIntoTable && flag)
			{
				table.builderNetworking.RequestRecyclePiece(piece.pieceId, piece.transform.position, piece.transform.rotation, playFX: true, -1);
			}
		}
		else
		{
			table.builderNetworking.PieceEnteredDropZone(piece, dropType, dropZoneID);
		}
	}
}
public class BuilderEnv : MonoBehaviour
{
