	public bool BlockSnowballCreation()
	{
		if (GorillaTagger.Instance == null)
		{
			return false;
		}
		if (!BuilderTable.TryGetBuilderTableForZone(GorillaTagger.Instance.offlineVRRig.zoneEntity.currentZone, out var table))
		{
			return false;
