	private List<Texture2D> serializeTextureToIndexKeys;

	[SerializeField]
	[HideInInspector]
	private List<int> serializeTextureToIndexValues;

	[SerializeField]
	[HideInInspector]
	private List<Texture2D> serializeTextures;

