	private int attempts;

	private static List<int> pieceTypes;

	[HideInInspector]
	public static List<BuilderPiece> pieceList;

	private static Dictionary<int, int> pieceTypeToIndex;

	private bool hasPieceDictionary;

	internal List<BuilderPieceSet> StartPieceSets => _starterPieceSets;

	public static bool hasInstance { get; private set; }

	public string GetStarterSetsConcat()
	{
		if (concatStarterSets.Length > 0)
		{
			return concatStarterSets;
		}
		concatStarterSets = string.Empty;
		foreach (BuilderPieceSet starterPieceSet in _starterPieceSets)
		{
			concatStarterSets += starterPieceSet.playfabID;
		}
		return concatStarterSets;
	}

	public string GetAllSetsConcat()
	{
		if (concatAllSets.Length > 0)
		{
			return concatAllSets;
		}
		concatAllSets = string.Empty;
		foreach (BuilderPieceSet allPieceSet in _allPieceSets)
		{
			concatAllSets += allPieceSet.playfabID;
		}
		return concatAllSets;
	}

	public void Awake()
	{
		if (instance == null)
		{
			instance = this;
			hasInstance = true;
		}
		else if (instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		Init();
		if (monitor == null)
		{
			monitor = StartCoroutine(MonitorTime());
		}
	}

	private void Init()
	{
		InitPieceDictionary();
		catalog = "DLC";
		currencyName = "SR";
		pulledStoreItems = false;
		_setIdToStoreItem = new Dictionary<int, BuilderSetStoreItem>(_allPieceSets.Count);
		_setIdToStoreItem.Clear();
		pieceSetInfos = new List<BuilderPieceSetInfo>(_allPieceSets.Count * 45);
		pieceSetInfoMap = new Dictionary<int, int>(_allPieceSets.Count * 45);
		livePieceSets = new List<BuilderPieceSet>(_allPieceSets.Count);
		scheduledPieceSets = new List<BuilderPieceSet>(_allPieceSets.Count);
		displayGroups = new List<BuilderPieceSet.BuilderDisplayGroup>(_allPieceSets.Count * 2);
		displayGroupMap = new Dictionary<int, int>(_allPieceSets.Count * 2);
		liveDisplayGroups = new List<BuilderPieceSet.BuilderDisplayGroup>();
		Dictionary<string, int> dictionary = new Dictionary<string, int>(5);
		foreach (BuilderPieceSet allPieceSet in _allPieceSets)
		{
			dictionary.Clear();
			int num = 0;
			BuilderSetStoreItem value = new BuilderSetStoreItem
			{
				displayName = allPieceSet.SetName,
				playfabID = allPieceSet.playfabID,
				setID = allPieceSet.GetIntIdentifier(),
				cost = 0u,
				setRef = allPieceSet,
				displayModel = allPieceSet.displayModel,
				isNullItem = false
			};
			_setIdToStoreItem.TryAdd(allPieceSet.GetIntIdentifier(), value);
			int num2 = -1;
			if (!string.IsNullOrEmpty(allPieceSet.materialId))
			{
				num2 = allPieceSet.materialId.GetHashCode();
			}
			for (int i = 0; i < allPieceSet.subsets.Count; i++)
			{
				BuilderPieceSet.BuilderPieceSubset builderPieceSubset = allPieceSet.subsets[i];
				if (!allPieceSet.setName.Equals("HIDDEN"))
				{
					string text = allPieceSet.subsets[i].GetShelfButtonName();
					if (text.IsNullOrEmpty())
					{
						text = allPieceSet.setName;
					}
					text = text.ToUpper();
					if (dictionary.TryGetValue(text, out var value2))
					{
						displayGroupMap.TryGetValue(value2, out var value3);
						BuilderPieceSet.BuilderDisplayGroup builderDisplayGroup = displayGroups[value3];
						builderDisplayGroup.pieceSubsets.Add(allPieceSet.subsets[i]);
						displayGroups[value3] = builderDisplayGroup;
					}
					else
					{
						string groupUniqueID = GetGroupUniqueID(allPieceSet.playfabID, num);
						num++;
						BuilderPieceSet.BuilderDisplayGroup builderDisplayGroup2 = new BuilderPieceSet.BuilderDisplayGroup(text, allPieceSet.materialId, allPieceSet.GetIntIdentifier(), groupUniqueID);
						builderDisplayGroup2.pieceSubsets.Add(allPieceSet.subsets[i]);
						dictionary.Add(text, builderDisplayGroup2.GetDisplayGroupIdentifier());
						displayGroupMap.Add(builderDisplayGroup2.GetDisplayGroupIdentifier(), displayGroups.Count);
						displayGroups.Add(builderDisplayGroup2);
						if (!allPieceSet.isScheduled)
						{
							liveDisplayGroups.Add(builderDisplayGroup2);
						}
					}
				}
				for (int j = 0; j < builderPieceSubset.pieceInfos.Count; j++)
				{
					BuilderPiece piecePrefab = builderPieceSubset.pieceInfos[j].piecePrefab;
					_ = piecePrefab == null;
					int staticHash = piecePrefab.name.GetStaticHash();
					int pieceMaterial = num2;
					if (piecePrefab.materialOptions == null)
					{
						pieceMaterial = -1;
						AddPieceToInfoMap(staticHash, pieceMaterial, allPieceSet.GetIntIdentifier());
					}
					else if (builderPieceSubset.pieceInfos[j].overrideSetMaterial)
					{
						if (builderPieceSubset.pieceInfos[j].pieceMaterialTypes.Length == 0)
						{
							UnityEngine.Debug.LogErrorFormat("Material List for piece {0} in set {1} is empty", piecePrefab.name, allPieceSet.SetName);
						}
						string[] pieceMaterialTypes = builderPieceSubset.pieceInfos[j].pieceMaterialTypes;
						foreach (string text2 in pieceMaterialTypes)
						{
							if (string.IsNullOrEmpty(text2))
							{
								UnityEngine.Debug.LogErrorFormat("Material List Entry for piece {0} in set {1} is empty", piecePrefab.name, allPieceSet.SetName);
							}
							else
							{
								pieceMaterial = text2.GetHashCode();
								AddPieceToInfoMap(staticHash, pieceMaterial, allPieceSet.GetIntIdentifier());
							}
						}
					}
					else
					{
						piecePrefab.materialOptions.GetMaterialFromType(num2, out var material, out var _);
						if (material == null)
						{
							pieceMaterial = -1;
						}
						AddPieceToInfoMap(staticHash, pieceMaterial, allPieceSet.GetIntIdentifier());
					}
				}
			}
			if (!allPieceSet.isScheduled)
			{
				livePieceSets.Add(allPieceSet);
			}
			else
			{
				scheduledPieceSets.Add(allPieceSet);
			}
		}
		_unlockedPieceSets = new List<BuilderPieceSet>(_allPieceSets.Count);
		_unlockedPieceSets.AddRange(_starterPieceSets);
	}

	private string GetGroupUniqueID(string setPlayfabID, int groupNumber)
	{
		return setPlayfabID.Trim('.') + (char)(65 + groupNumber);
	}

	public void InitPieceDictionary()
	{
		if (hasPieceDictionary)
		{
			return;
		}
		pieceTypes = new List<int>(256);
		pieceList = new List<BuilderPiece>(256);
		pieceTypeToIndex = new Dictionary<int, int>(256);
		int num = 0;
		for (int i = 0; i < _allPieceSets.Count; i++)
		{
			BuilderPieceSet builderPieceSet = _allPieceSets[i];
			if (builderPieceSet == null)
			{
				continue;
			}
			for (int j = 0; j < builderPieceSet.subsets.Count; j++)
			{
				BuilderPieceSet.BuilderPieceSubset builderPieceSubset = builderPieceSet.subsets[j];
				if (builderPieceSet == null)
				{
					continue;
				}
				for (int k = 0; k < builderPieceSubset.pieceInfos.Count; k++)
				{
					BuilderPieceSet.PieceInfo pieceInfo = builderPieceSubset.pieceInfos[k];
					if (!(pieceInfo.piecePrefab == null))
					{
						int staticHash = pieceInfo.piecePrefab.name.GetStaticHash();
						if (!pieceTypeToIndex.ContainsKey(staticHash))
						{
							pieceList.Add(pieceInfo.piecePrefab);
							pieceTypes.Add(staticHash);
							pieceTypeToIndex.Add(staticHash, num);
							num++;
						}
					}
				}
			}
		}
		hasPieceDictionary = true;
	}

	public BuilderPiece GetPiecePrefab(int pieceType)
	{
		if (pieceTypeToIndex.TryGetValue(pieceType, out var value))
		{
			return pieceList[value];
		}
		UnityEngine.Debug.LogErrorFormat("No Prefab found for type {0}", pieceType);
		return null;
	}

	private void OnEnable()
	{
		if (monitor == null && scheduledPieceSets.Count > 0)
		{
			monitor = StartCoroutine(MonitorTime());
		}
	}

	private void OnDisable()
	{
		if (monitor != null)
		{
			StopCoroutine(monitor);
		}
		monitor = null;
	}

	private IEnumerator MonitorTime()
	{
		while (GorillaComputer.instance == null || GorillaComputer.instance.startupMillis == 0L)
		{
			yield return null;
		}
		while (scheduledPieceSets.Count > 0)
		{
			bool flag = false;
			for (int num = scheduledPieceSets.Count - 1; num >= 0; num--)
			{
				BuilderPieceSet builderPieceSet = scheduledPieceSets[num];
				if (GorillaComputer.instance.GetServerTime() > builderPieceSet.GetScheduleDateTime())
				{
					flag = true;
					livePieceSets.Add(builderPieceSet);
					scheduledPieceSets.RemoveAt(num);
					int intIdentifier = builderPieceSet.GetIntIdentifier();
					foreach (BuilderPieceSet.BuilderDisplayGroup displayGroup in displayGroups)
					{
						if (displayGroup != null && displayGroup.setID == intIdentifier && !liveDisplayGroups.Contains(displayGroup))
						{
							liveDisplayGroups.Add(displayGroup);
						}
					}
				}
			}
			if (flag)
			{
				OnLiveSetsUpdated.Invoke();
			}
			yield return new WaitForSecondsRealtime(60f);
		}
		monitor = null;
	}

	private void AddPieceToInfoMap(int pieceType, int pieceMaterial, int setID)
	{
		if (pieceSetInfoMap.TryGetValue(HashCode.Combine(pieceType, pieceMaterial), out var value))
		{
			BuilderPieceSetInfo value2 = pieceSetInfos[value];
			if (!value2.setIds.Contains(setID))
			{
				value2.setIds.Add(setID);
			}
			pieceSetInfos[value] = value2;
		}
		else
		{
			BuilderPieceSetInfo item = new BuilderPieceSetInfo
			{
				pieceType = pieceType,
				materialType = pieceMaterial,
				setIds = new List<int> { setID }
			};
			pieceSetInfoMap.Add(HashCode.Combine(pieceType, pieceMaterial), pieceSetInfos.Count);
			pieceSetInfos.Add(item);
		}
	}

	public static bool IsItemIDBuilderItem(string playfabID)
	{
		return instance.GetAllSetsConcat().Contains(playfabID);
	}

	public void OnGotInventoryItems(GetUserInventoryResult inventoryResult, GetCatalogItemsResult catalogResult)
	{
		CosmeticsController.instance.concatStringCosmeticsAllowed += GetStarterSetsConcat();
		_unlockedPieceSets.Clear();
		_unlockedPieceSets.AddRange(_starterPieceSets);
		foreach (CatalogItem item in catalogResult.Catalog)
		{
			if (IsItemIDBuilderItem(item.ItemId) && _setIdToStoreItem.TryGetValue(item.ItemId.GetStaticHash(), out var value))
			{
				bool hasPrice = false;
				uint value2 = 0u;
				if (item.VirtualCurrencyPrices.TryGetValue(currencyName, out value2))
				{
					hasPrice = true;
				}
				value.playfabID = item.ItemId;
				value.cost = value2;
				value.hasPrice = hasPrice;
				_setIdToStoreItem[value.setRef.GetIntIdentifier()] = value;
			}
		}
		foreach (ItemInstance item2 in inventoryResult.Inventory)
		{
			if (IsItemIDBuilderItem(item2.ItemId) && _setIdToStoreItem.TryGetValue(item2.ItemId.GetStaticHash(), out var value3))
			{
				_unlockedPieceSets.Add(value3.setRef);
				CosmeticsController.instance.concatStringCosmeticsAllowed += item2.ItemId;
			}
		}
		pulledStoreItems = true;
		OnOwnedSetsUpdated?.Invoke();
	}

	public BuilderSetStoreItem GetStoreItemFromSetID(int setID)
	{
		return _setIdToStoreItem.GetValueOrDefault(setID, BuilderKiosk.nullItem);
	}

	public BuilderPieceSet GetPieceSetFromID(int setID)
	{
		if (_setIdToStoreItem.TryGetValue(setID, out var value))
		{
			return value.setRef;
		}
		return null;
	}

	public BuilderPieceSet.BuilderDisplayGroup GetDisplayGroupFromIndex(int groupID)
	{
		if (displayGroupMap.TryGetValue(groupID, out var value))
		{
			return displayGroups[value];
		}
		return null;
	}

	public List<BuilderPieceSet> GetAllPieceSets()
	{
		return _allPieceSets;
	}

	public List<BuilderPieceSet> GetLivePieceSets()
	{
		return livePieceSets;
	}

	public List<BuilderPieceSet.BuilderDisplayGroup> GetLiveDisplayGroups()
	{
		return liveDisplayGroups;
	}

	public List<BuilderPieceSet> GetUnlockedPieceSets()
	{
		return _unlockedPieceSets;
	}

	public List<BuilderPieceSet> GetPermanentSetsForSale()
	{
		return _setsAlwaysForSale;
	}

	public List<BuilderPieceSet> GetSeasonalSetsForSale()
	{
		return _seasonalSetsForSale;
	}

	public bool IsSetSeasonal(string playfabID)
	{
		if (_seasonalSetsForSale.IsNullOrEmpty())
		{
			return false;
		}
		return _seasonalSetsForSale.FindIndex((BuilderPieceSet x) => x.playfabID.Equals(playfabID)) >= 0;
	}

	public bool DoesPlayerOwnDisplayGroup(Player player, int groupID)
	{
		if (player == null)
		{
			return false;
		}
		if (displayGroupMap.TryGetValue(groupID, out var value))
		{
			if (value < 0 || value >= displayGroups.Count)
			{
				return false;
			}
			BuilderPieceSet.BuilderDisplayGroup builderDisplayGroup = displayGroups[value];
			if (builderDisplayGroup != null)
			{
				return DoesPlayerOwnPieceSet(player, builderDisplayGroup.setID);
			}
			return false;
		}
		return false;
	}

	public bool DoesPlayerOwnPieceSet(Player player, int setID)
	{
		BuilderPieceSet pieceSetFromID = GetPieceSetFromID(setID);
		if (pieceSetFromID == null)
		{
			return false;
		}
		if (VRRigCache.Instance.TryGetVrrig(player, out var playerRig))
		{
			bool flag = playerRig.Rig.IsItemAllowed(pieceSetFromID.playfabID);
			UnityEngine.Debug.LogFormat("BuilderSetManager: does player {0} own set {1} {2}", player.ActorNumber, pieceSetFromID.SetName, flag);
			return flag;
		}
		UnityEngine.Debug.LogFormat("BuilderSetManager: could not get rig for player {0}", player.ActorNumber);
		return false;
	}

	public bool DoesAnyPlayerInRoomOwnPieceSet(int setID)
	{
		BuilderPieceSet pieceSetFromID = GetPieceSetFromID(setID);
		if (pieceSetFromID == null)
		{
			return false;
		}
		if (GetStarterSetsConcat().Contains(pieceSetFromID.setName))
		{
			return true;
		}
		foreach (NetPlayer item in RoomSystem.PlayersInRoom)
		{
			if (VRRigCache.Instance.TryGetVrrig(item, out var playerRig) && playerRig.Rig.IsItemAllowed(pieceSetFromID.playfabID))
			{
				return true;
			}
		}
		return false;
	}

	public bool IsPieceOwnedByRoom(int pieceType, int materialType)
	{
		if (pieceSetInfoMap.TryGetValue(HashCode.Combine(pieceType, materialType), out var value))
		{
			foreach (int setId in pieceSetInfos[value].setIds)
			{
				if (DoesAnyPlayerInRoomOwnPieceSet(setId))
				{
					return true;
				}
			}
			return false;
		}
		return false;
	}

	public bool IsPieceOwnedLocally(int pieceType, int materialType)
	{
		if (pieceSetInfoMap.TryGetValue(HashCode.Combine(pieceType, materialType), out var value))
		{
			foreach (int setId in pieceSetInfos[value].setIds)
			{
				if (IsPieceSetOwnedLocally(setId))
				{
					return true;
				}
			}
			return false;
		}
		return false;
	}

	public bool IsPieceSetOwnedLocally(int setID)
	{
		return _unlockedPieceSets.FindIndex((BuilderPieceSet x) => setID == x.GetIntIdentifier()) >= 0;
	}

	public void UnlockSet(int setID)
	{
		int num = _allPieceSets.FindIndex((BuilderPieceSet x) => setID == x.GetIntIdentifier());
		if (num >= 0 && !_unlockedPieceSets.Contains(_allPieceSets[num]))
		{
			_unlockedPieceSets.Add(_allPieceSets[num]);
		}
		OnOwnedSetsUpdated?.Invoke();
	}

	public void TryPurchaseItem(int setID, Action<bool> resultCallback)
	{
		if (!_setIdToStoreItem.TryGetValue(setID, out var storeItem))
		{
			UnityEngine.Debug.Log("BuilderSetManager: no store Item for set " + setID);
			resultCallback?.Invoke(obj: false);
			return;
		}
		if (IsPieceSetOwnedLocally(setID))
		{
			UnityEngine.Debug.Log("BuilderSetManager: set already owned " + setID);
			resultCallback?.Invoke(obj: false);
			return;
		}
		PlayFabClientAPI.PurchaseItem(new PurchaseItemRequest
		{
			ItemId = storeItem.playfabID,
			Price = (int)storeItem.cost,
			VirtualCurrency = currencyName,
			CatalogVersion = catalog
		}, delegate(PurchaseItemResult result)
		{
			if (result.Items.Count > 0)
			{
				foreach (ItemInstance item in result.Items)
				{
					UnityEngine.Debug.Log("BuilderSetManager: unlocking set " + item.ItemId);
					UnlockSet(item.ItemId.GetStaticHash());
				}
				CosmeticsController.instance.UpdateMyCosmetics();
				if (PhotonNetwork.InRoom)
				{
					StartCoroutine(CheckIfMyCosmeticsUpdated(storeItem.playfabID));
				}
				resultCallback?.Invoke(obj: true);
			}
			else
			{
				UnityEngine.Debug.Log("BuilderSetManager: no items purchased ");
				resultCallback?.Invoke(obj: false);
			}
		}, delegate(PlayFabError error)
		{
			UnityEngine.Debug.LogErrorFormat("BuilderSetManager: purchase {0} Error {1}", setID, error.ErrorMessage);
			resultCallback?.Invoke(obj: false);
		});
	}

	private IEnumerator CheckIfMyCosmeticsUpdated(string itemToBuyID)
	{
		yield return new WaitForSecondsRealtime(1f);
		foundCosmetic = false;
		attempts = 0;
		while (!foundCosmetic && attempts < 10 && PhotonNetwork.InRoom)
		{
			PlayFabClientAPI.GetSharedGroupData(new PlayFab.ClientModels.GetSharedGroupDataRequest
			{
				Keys = new List<string> { "Inventory" },
				SharedGroupId = PhotonNetwork.LocalPlayer.UserId + "Inventory"
			}, delegate(GetSharedGroupDataResult result)
			{
				attempts++;
				foreach (KeyValuePair<string, PlayFab.ClientModels.SharedGroupDataRecord> datum in result.Data)
				{
					if (datum.Value.Value.Contains(itemToBuyID))
					{
						PhotonNetwork.RaiseEvent(199, null, new RaiseEventOptions
						{
							Receivers = ReceiverGroup.Others
						}, SendOptions.SendReliable);
						foundCosmetic = true;
					}
				}
				_ = foundCosmetic;
			}, delegate(PlayFabError error)
			{
				attempts++;
				CosmeticsController.instance.ReauthOrBan(error);
			});
			yield return new WaitForSecondsRealtime(1f);
		}
		UnityEngine.Debug.Log("BuilderSetManager: done!");
	}
}
public class BuilderSetSelector : MonoBehaviour
{
	private List<BuilderPieceSet.BuilderDisplayGroup> includedGroups;

	private int numLiveDisplayGroups;

	[SerializeField]
	private Material disabledMaterial;

	[Header("UI")]
	[FormerlySerializedAs("setLabels")]
	[SerializeField]
	private Text[] groupLabels;

	[Header("Buttons")]
	[FormerlySerializedAs("setButtons")]
	[SerializeField]
	private GorillaPressableButton[] groupButtons;

	[SerializeField]
	private GorillaPressableButton previousPageButton;

	[SerializeField]
	private GorillaPressableButton nextPageButton;

	private List<BuilderPieceSet.BuilderPieceCategory> _includedCategories;

	private int includedGroupIndex;

	private BuilderPieceSet.BuilderDisplayGroup currentGroup;

	private int pageIndex;

	private int groupsPerPage = 3;

	private int totalPages = 1;

	private List<Renderer> zoneRenderers = new List<Renderer>(10);

	private bool inBuilderZone;

	[HideInInspector]
	public UnityEvent<int> OnSelectedGroup;

	private void Start()
	{
		zoneRenderers.Clear();
		GorillaPressableButton[] array = groupButtons;
		foreach (GorillaPressableButton gorillaPressableButton in array)
		{
			zoneRenderers.Add(gorillaPressableButton.buttonRenderer);
			Renderer renderer = gorillaPressableButton.myTmpText?.GetComponent<Renderer>();
			if (renderer != null)
			{
				zoneRenderers.Add(renderer);
			}
		}
		zoneRenderers.Add(previousPageButton.buttonRenderer);
		zoneRenderers.Add(nextPageButton.buttonRenderer);
		Renderer renderer2 = previousPageButton.myTmpText?.GetComponent<Renderer>();
		if (renderer2 != null)
		{
			zoneRenderers.Add(renderer2);
		}
		renderer2 = nextPageButton.myTmpText?.GetComponent<Renderer>();
		if (renderer2 != null)
		{
			zoneRenderers.Add(renderer2);
		}
		foreach (Renderer zoneRenderer in zoneRenderers)
		{
			zoneRenderer.enabled = false;
		}
		inBuilderZone = false;
		ZoneManagement instance = ZoneManagement.instance;
		instance.onZoneChanged = (Action)Delegate.Combine(instance.onZoneChanged, new Action(OnZoneChanged));
		OnZoneChanged();
	}

	public void Setup(List<BuilderPieceSet.BuilderPieceCategory> categories)
	{
		List<BuilderPieceSet.BuilderDisplayGroup> liveDisplayGroups = BuilderSetManager.instance.GetLiveDisplayGroups();
		numLiveDisplayGroups = liveDisplayGroups.Count;
		includedGroups = new List<BuilderPieceSet.BuilderDisplayGroup>(liveDisplayGroups.Count);
		_includedCategories = categories;
		foreach (BuilderPieceSet.BuilderDisplayGroup item in liveDisplayGroups)
		{
			if (DoesDisplayGroupHaveIncludedCategories(item))
			{
				includedGroups.Add(item);
			}
		}
		BuilderSetManager.instance.OnOwnedSetsUpdated.AddListener(RefreshUnlockedGroups);
		BuilderSetManager.instance.OnLiveSetsUpdated.AddListener(RefreshUnlockedGroups);
		groupsPerPage = groupButtons.Length;
		totalPages = includedGroups.Count / groupsPerPage;
		if (includedGroups.Count % groupsPerPage > 0)
		{
			totalPages++;
		}
		previousPageButton.gameObject.SetActive(totalPages > 1);
		nextPageButton.gameObject.SetActive(totalPages > 1);
		previousPageButton.myTmpText.enabled = totalPages > 1;
		nextPageButton.myTmpText.enabled = totalPages > 1;
		pageIndex = 0;
		currentGroup = includedGroups[includedGroupIndex];
		previousPageButton.onPressButton.AddListener(OnPreviousPageClicked);
		nextPageButton.onPressButton.AddListener(OnNextPageClicked);
		GorillaPressableButton[] array = groupButtons;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].onPressed += OnSetButtonPressed;
		}
		UpdateLabels();
	}

	private void OnDestroy()
	{
		if (previousPageButton != null)
		{
			previousPageButton.onPressButton.RemoveListener(OnPreviousPageClicked);
		}
		if (nextPageButton != null)
		{
			nextPageButton.onPressButton.RemoveListener(OnNextPageClicked);
		}
		if (BuilderSetManager.instance != null)
		{
			BuilderSetManager.instance.OnOwnedSetsUpdated.RemoveListener(RefreshUnlockedGroups);
			BuilderSetManager.instance.OnLiveSetsUpdated.RemoveListener(RefreshUnlockedGroups);
		}
		GorillaPressableButton[] array = groupButtons;
		foreach (GorillaPressableButton gorillaPressableButton in array)
		{
			if (!(gorillaPressableButton == null))
			{
				gorillaPressableButton.onPressed -= OnSetButtonPressed;
			}
		}
		if (ZoneManagement.instance != null)
		{
			ZoneManagement instance = ZoneManagement.instance;
			instance.onZoneChanged = (Action)Delegate.Remove(instance.onZoneChanged, new Action(OnZoneChanged));
		}
	}

	private void OnZoneChanged()
	{
		bool flag = ZoneManagement.instance.IsZoneActive(GTZone.monkeBlocks);
		if (flag && !inBuilderZone)
		{
			foreach (Renderer zoneRenderer in zoneRenderers)
			{
				zoneRenderer.enabled = true;
			}
		}
		else if (!flag && inBuilderZone)
		{
			foreach (Renderer zoneRenderer2 in zoneRenderers)
			{
				zoneRenderer2.enabled = false;
			}
		}
		inBuilderZone = flag;
	}

	private void OnSetButtonPressed(GorillaPressableButton button, bool isLeft)
	{
		int num = 0;
		for (int i = 0; i < groupButtons.Length; i++)
		{
			if (button.Equals(groupButtons[i]))
			{
				num = i;
				break;
			}
		}
		int num2 = pageIndex * groupsPerPage + num;
		if (num2 < includedGroups.Count)
		{
			BuilderPieceSet.BuilderDisplayGroup builderDisplayGroup = includedGroups[num2];
			if (currentGroup == null || builderDisplayGroup.displayName != currentGroup.displayName)
			{
				OnSelectedGroup?.Invoke(builderDisplayGroup.GetDisplayGroupIdentifier());
			}
		}
	}

	private void RefreshUnlockedGroups()
	{
		List<BuilderPieceSet.BuilderDisplayGroup> liveDisplayGroups = BuilderSetManager.instance.GetLiveDisplayGroups();
		if (liveDisplayGroups.Count != numLiveDisplayGroups)
		{
			string value = ((currentGroup != null) ? currentGroup.displayName : "");
			numLiveDisplayGroups = liveDisplayGroups.Count;
			includedGroups.EnsureCapacity(numLiveDisplayGroups);
			includedGroups.Clear();
			int num = 0;
			foreach (BuilderPieceSet.BuilderDisplayGroup item in liveDisplayGroups)
			{
				if (DoesDisplayGroupHaveIncludedCategories(item))
				{
					if (item.displayName.Equals(value))
					{
						num = includedGroups.Count;
					}
					includedGroups.Add(item);
				}
			}
			if (includedGroups.Count < 1)
			{
				currentGroup = null;
			}
			else
			{
				includedGroupIndex = num;
				currentGroup = includedGroups[includedGroupIndex];
			}
			totalPages = includedGroups.Count / groupsPerPage;
			if (includedGroups.Count % groupsPerPage > 0)
			{
				totalPages++;
			}
			previousPageButton.gameObject.SetActive(totalPages > 1);
			nextPageButton.gameObject.SetActive(totalPages > 1);
			previousPageButton.myTmpText.enabled = totalPages > 1;
			nextPageButton.myTmpText.enabled = totalPages > 1;
		}
		UpdateLabels();
	}

	private void OnPreviousPageClicked()
	{
		RefreshUnlockedGroups();
		int num = Mathf.Clamp(pageIndex - 1, 0, totalPages - 1);
		if (num != pageIndex)
		{
			pageIndex = num;
			UpdateLabels();
		}
	}

	private void OnNextPageClicked()
	{
		RefreshUnlockedGroups();
		int num = Mathf.Clamp(pageIndex + 1, 0, totalPages - 1);
		if (num != pageIndex)
		{
			pageIndex = num;
			UpdateLabels();
		}
	}

	public void SetSelection(int groupID)
	{
		if (BuilderSetManager.instance == null)
		{
			return;
		}
		BuilderPieceSet.BuilderDisplayGroup newGroup = BuilderSetManager.instance.GetDisplayGroupFromIndex(groupID);
		if (newGroup != null)
		{
			currentGroup = newGroup;
			includedGroupIndex = includedGroups.FindIndex((BuilderPieceSet.BuilderDisplayGroup x) => x.displayName == newGroup.displayName);
			UpdateLabels();
		}
	}

	private void UpdateLabels()
	{
		for (int i = 0; i < groupLabels.Length; i++)
		{
			int num = pageIndex * groupsPerPage + i;
			if (num < includedGroups.Count && includedGroups[num] != null)
			{
				if (!groupButtons[i].gameObject.activeSelf)
				{
					groupButtons[i].gameObject.SetActive(value: true);
					groupButtons[i].myTmpText.gameObject.SetActive(value: true);
				}
				if (groupButtons[i].myTmpText.text != includedGroups[num].displayName)
				{
					groupButtons[i].myTmpText.text = includedGroups[num].displayName;
				}
				if (BuilderSetManager.instance.IsPieceSetOwnedLocally(includedGroups[num].setID))
				{
					bool flag = currentGroup != null && includedGroups[num].displayName == currentGroup.displayName;
					if (flag != groupButtons[i].isOn || !groupButtons[i].enabled)
					{
						groupButtons[i].isOn = flag;
						groupButtons[i].buttonRenderer.material = (flag ? groupButtons[i].pressedMaterial : groupButtons[i].unpressedMaterial);
					}
					groupButtons[i].enabled = true;
				}
				else
				{
					if (groupButtons[i].enabled)
					{
						groupButtons[i].buttonRenderer.material = disabledMaterial;
					}
					groupButtons[i].enabled = false;
				}
			}
			else
			{
				if (groupButtons[i].gameObject.activeSelf)
				{
					groupButtons[i].gameObject.SetActive(value: false);
					groupButtons[i].myTmpText.gameObject.SetActive(value: false);
				}
				if (groupButtons[i].isOn || groupButtons[i].enabled)
				{
					groupButtons[i].isOn = false;
					groupButtons[i].enabled = false;
				}
			}
		}
		bool flag2 = pageIndex > 0 && totalPages > 1;
		bool flag3 = pageIndex < totalPages - 1 && totalPages > 1;
		if (previousPageButton.myTmpText.enabled != flag2)
		{
			previousPageButton.myTmpText.enabled = flag2;
		}
		if (nextPageButton.myTmpText.enabled != flag3)
		{
			nextPageButton.myTmpText.enabled = flag3;
		}
	}

	public bool DoesDisplayGroupHaveIncludedCategories(BuilderPieceSet.BuilderDisplayGroup set)
	{
		foreach (BuilderPieceSet.BuilderPieceSubset pieceSubset in set.pieceSubsets)
		{
			if (_includedCategories.Contains(pieceSubset.pieceCategory))
			{
				return true;
			}
		}
		return false;
	}

	public BuilderPieceSet.BuilderDisplayGroup GetSelectedGroup()
	{
		return currentGroup;
	}

	public int GetDefaultGroupID()
	{
		if (includedGroups == null || includedGroups.Count < 1)
		{
			return -1;
		}
		BuilderPieceSet.BuilderDisplayGroup builderDisplayGroup = includedGroups[0];
		if (!BuilderSetManager.instance.IsPieceSetOwnedLocally(builderDisplayGroup.setID))
		{
			foreach (BuilderPieceSet.BuilderDisplayGroup includedGroup in includedGroups)
			{
				if (BuilderSetManager.instance.IsPieceSetOwnedLocally(includedGroup.setID))
				{
					return includedGroup.GetDisplayGroupIdentifier();
				}
			}
			UnityEngine.Debug.LogWarning("No default group available for shelf");
			return -1;
		}
		return builderDisplayGroup.GetDisplayGroupIdentifier();
	}
}
public class BuilderShelf : MonoBehaviour
{
	[Serializable]
	public class BuildPieceSpawn
	{
		public GameObject buildPiecePrefab;

		public string materialID;

		public int count = 1;

		public UnityEngine.Vector3 localAxis = UnityEngine.Vector3.right;

		[Tooltip("Optional Editor Visual")]
		public Mesh previewMesh;
	}

	private int count;

	public float separation;

	public Transform center;

	public List<BuildPieceSpawn> buildPieceSpawns;

	private List<BuilderResources> spawnCosts;

	private int shelfSlot;

	private int buildPieceSpawnIndex;

	private int spawnCount;

	public void Init()
	{
		shelfSlot = 0;
		buildPieceSpawnIndex = 0;
		spawnCount = 0;
		count = 0;
		spawnCosts = new List<BuilderResources>(buildPieceSpawns.Count);
		for (int i = 0; i < buildPieceSpawns.Count; i++)
		{
			count += buildPieceSpawns[i].count;
			BuilderPiece component = buildPieceSpawns[i].buildPiecePrefab.GetComponent<BuilderPiece>();
			spawnCosts.Add(component.cost);
		}
	}

	public bool HasOpenSlot()
	{
		return shelfSlot < count;
	}

	public void BuildNextPiece(BuilderTable table)
	{
		if (!HasOpenSlot())
		{
			return;
		}
		BuildPieceSpawn buildPieceSpawn = buildPieceSpawns[buildPieceSpawnIndex];
		BuilderResources resources = spawnCosts[buildPieceSpawnIndex];
		while (!table.HasEnoughUnreservedResources(resources) && buildPieceSpawnIndex < buildPieceSpawns.Count - 1)
		{
			int num = buildPieceSpawn.count - spawnCount;
			shelfSlot += num;
			spawnCount = 0;
			buildPieceSpawnIndex++;
			buildPieceSpawn = buildPieceSpawns[buildPieceSpawnIndex];
			resources = spawnCosts[buildPieceSpawnIndex];
		}
		if (!table.HasEnoughUnreservedResources(resources))
		{
			int num2 = buildPieceSpawn.count - spawnCount;
			shelfSlot += num2;
			spawnCount = 0;
			return;
		}
		int staticHash = buildPieceSpawn.buildPiecePrefab.name.GetStaticHash();
		int materialType = (string.IsNullOrEmpty(buildPieceSpawn.materialID) ? (-1) : buildPieceSpawn.materialID.GetHashCode());
		GetSpawnLocation(shelfSlot, buildPieceSpawn, out var spawnPosition, out var spawnRotation);
		int pieceId = table.CreatePieceId();
		table.CreatePiece(staticHash, pieceId, spawnPosition, spawnRotation, materialType, BuilderPiece.State.OnShelf, PhotonNetwork.LocalPlayer);
		spawnCount++;
		shelfSlot++;
		if (spawnCount >= buildPieceSpawn.count)
		{
			buildPieceSpawnIndex++;
			spawnCount = 0;
		}
	}

	public void InitCount()
	{
		count = 0;
		for (int i = 0; i < buildPieceSpawns.Count; i++)
		{
			count += buildPieceSpawns[i].count;
		}
	}

	public void BuildItems(BuilderTable table)
	{
		int num = 0;
		InitCount();
		for (int i = 0; i < buildPieceSpawns.Count; i++)
		{
			BuildPieceSpawn buildPieceSpawn = buildPieceSpawns[i];
			if (buildPieceSpawn == null || buildPieceSpawn.count == 0)
			{
				continue;
			}
			int staticHash = buildPieceSpawn.buildPiecePrefab.name.GetStaticHash();
			int materialType = (string.IsNullOrEmpty(buildPieceSpawn.materialID) ? (-1) : buildPieceSpawn.materialID.GetHashCode());
			for (int j = 0; j < buildPieceSpawn.count; j++)
			{
				if (num >= count)
				{
					break;
				}
				GetSpawnLocation(num, buildPieceSpawn, out var spawnPosition, out var spawnRotation);
				int pieceId = table.CreatePieceId();
				table.CreatePiece(staticHash, pieceId, spawnPosition, spawnRotation, materialType, BuilderPiece.State.OnShelf, PhotonNetwork.LocalPlayer);
				num++;
			}
		}
	}

	public void GetSpawnLocation(int slot, BuildPieceSpawn spawn, out UnityEngine.Vector3 spawnPosition, out UnityEngine.Quaternion spawnRotation)
	{
		if (center == null)
		{
			center = base.transform;
		}
		UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
		UnityEngine.Vector3 euler = UnityEngine.Vector3.zero;
		BuilderPiece component = spawn.buildPiecePrefab.GetComponent<BuilderPiece>();
		if (component != null)
		{
			vector = component.desiredShelfOffset;
			euler = component.desiredShelfRotationOffset;
		}
		spawnRotation = center.rotation * UnityEngine.Quaternion.Euler(euler);
		float num = (float)slot * separation - (float)(count - 1) * separation / 2f;
		spawnPosition = center.position + center.rotation * (spawn.localAxis * num + vector);
	}
}
public class BuilderTriggerEnable : MonoBehaviour
{
	public List<GameObject> activateOnEnter;

	public List<GameObject> deactivateOnEnter;

	public List<GameObject> activateOnExit;

	public List<GameObject> deactivateOnExit;

	private void OnTriggerEnter(Collider other)
	{
		if (other.attachedRigidbody == null)
		{
			return;
		}
		VRRig component = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
		if (component == null || component.OwningNetPlayer == null || !component.OwningNetPlayer.IsLocal)
		{
			return;
		}
		if (activateOnEnter != null)
		{
			for (int i = 0; i < activateOnEnter.Count; i++)
			{
				if (activateOnEnter[i] != null)
				{
					activateOnEnter[i].SetActive(value: true);
				}
			}
		}
		if (deactivateOnEnter == null)
		{
			return;
		}
		for (int j = 0; j < deactivateOnEnter.Count; j++)
		{
			if (deactivateOnEnter[j] != null)
			{
				deactivateOnEnter[j].SetActive(value: false);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (other.attachedRigidbody == null)
		{
			return;
		}
		VRRig component = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
		if (component == null || component.OwningNetPlayer == null || !component.OwningNetPlayer.IsLocal)
		{
			return;
		}
		if (activateOnExit != null)
		{
			for (int i = 0; i < activateOnExit.Count; i++)
			{
				if (activateOnExit[i] != null)
				{
					activateOnExit[i].SetActive(value: true);
				}
			}
		}
		if (deactivateOnExit == null)
		{
			return;
		}
		for (int j = 0; j < deactivateOnExit.Count; j++)
		{
			if (deactivateOnExit[j] != null)
			{
				deactivateOnExit[j].SetActive(value: false);
			}
		}
	}
}
