			XRNode.LeftHand => instance.leftControllerSecondaryButtonTouch, 
			XRNode.RightHand => instance.rightControllerSecondaryButtonTouch, 
			_ => false, 
		};
	}

	public static float GripFloat(XRNode node)
	{
		return node switch
		{
