			XRNode.Head => instance.headDevice.isValid, 
			XRNode.LeftHand => instance.leftControllerDevice.isValid, 
			XRNode.RightHand => instance.rightControllerDevice.isValid, 
			_ => false, 
		};
	}

	public static bool HasPressFlags(XRNode node, EControllerInputPressFlags inputStateFlags)
	{
		EControllerInputPressFlags inputStateFlags2 = GetInputStateFlags(node);
		if (inputStateFlags != EControllerInputPressFlags.None)
		{
			return (inputStateFlags2 & inputStateFlags) == inputStateFlags;
		}
		return false;
	}

	public static EControllerInputPressFlags GetInputStateFlags(XRNode node)
	{
		return node switch
		{
			XRNode.RightHand => instance.rightPressFlags, 
			XRNode.LeftHand => instance.leftPressFlags, 
			_ => EControllerInputPressFlags.None, 
		};
	}

	public static void AddCallbackOnPressStart(EControllerInputPressFlags flags, Action<EHandednessFlags> callback)
	{
		_AddInputStateCallback(ref _g_callbacks_onPressStart, flags, callback);
	}

	public static void AddCallbackOnPressEnd(EControllerInputPressFlags flags, Action<EHandednessFlags> callback)
	{
		_AddInputStateCallback(ref _g_callbacks_onPressEnd, flags, callback);
	}

	public static void AddCallbackOnPressUpdate(EControllerInputPressFlags flags, Action<EHandednessFlags> callback)
	{
		_AddInputStateCallback(ref _g_callbacks_onPressUpdate, flags, callback);
	}

	private static void _AddInputStateCallback(ref _InputCallbacksCadenceInfo ref_callbacksInfo, EControllerInputPressFlags flags, Action<EHandednessFlags> callback)
	{
		if (callback != null && flags != EControllerInputPressFlags.None)
		{
			if (ref_callbacksInfo.list.Capacity <= ref_callbacksInfo.list.Count)
			{
				ref_callbacksInfo.list.Capacity = ref_callbacksInfo.list.Count * 2;
			}
			ref_callbacksInfo.list.Add(new _InputCallback(flags, callback));
		}
	}

	public static void RemoveCallbackOnPressStart(Action<EHandednessFlags> callback)
	{
		_RemoveInputStateCallback(ref _g_callbacks_onPressStart, callback);
	}

	public static void RemoveCallbackOnPressEnd(Action<EHandednessFlags> callback)
	{
		_RemoveInputStateCallback(ref _g_callbacks_onPressEnd, callback);
	}

	public static void RemoveCallbackOnPressUpdate(Action<EHandednessFlags> callback)
	{
		_RemoveInputStateCallback(ref _g_callbacks_onPressUpdate, callback);
	}

	private static void _RemoveInputStateCallback(ref _InputCallbacksCadenceInfo ref_callbacksInfo, Action<EHandednessFlags> callback)
	{
		if (callback != null)
		{
			ref_callbacksInfo.list.RemoveAll((_InputCallback sub) => sub.callback == callback);
		}
	}

	private void _UpdatePressFlags()
	{
		leftPressFlagsLastFrame = leftPressFlags;
		leftPressFlags = (EControllerInputPressFlags)((leftIndexPressed ? 1 : 0) | (leftGrab ? 2 : 0) | (leftControllerPrimaryButton ? 4 : 0) | (leftControllerSecondaryButton ? 8 : 0));
		rightPressFlagsLastFrame = rightPressFlags;
		rightPressFlags = (EControllerInputPressFlags)((rightIndexPressed ? 1 : 0) | (rightGrab ? 2 : 0) | (rightControllerPrimaryButton ? 4 : 0) | (rightControllerSecondaryButton ? 8 : 0));
		_UpdatePressFlags_Callbacks(ref _g_callbacks_onPressStart, _EPressCadence.Start, leftPressFlags, leftPressFlagsLastFrame, rightPressFlags, rightPressFlagsLastFrame);
		_UpdatePressFlags_Callbacks(ref _g_callbacks_onPressEnd, _EPressCadence.End, leftPressFlags, leftPressFlagsLastFrame, rightPressFlags, rightPressFlagsLastFrame);
		_UpdatePressFlags_Callbacks(ref _g_callbacks_onPressUpdate, _EPressCadence.Held, leftPressFlags, leftPressFlagsLastFrame, rightPressFlags, rightPressFlagsLastFrame);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private static void _UpdatePressFlags_Callbacks(ref _InputCallbacksCadenceInfo callbacksInfo, _EPressCadence cadence, EControllerInputPressFlags lFlags_now, EControllerInputPressFlags lFlags_old, EControllerInputPressFlags rFlags_now, EControllerInputPressFlags rFlags_old)
	{
		for (int i = 0; i < callbacksInfo.list.Count; i++)
		{
			EControllerInputPressFlags flags = callbacksInfo.list[i].flags;
			Action<EHandednessFlags> callback = callbacksInfo.list[i].callback;
			EHandednessFlags eHandednessFlags = _IsHandContributingToPressCadence(EHandednessFlags.Left, cadence, flags, lFlags_now, lFlags_old) | _IsHandContributingToPressCadence(EHandednessFlags.Right, cadence, flags, rFlags_now, rFlags_old);
			if (eHandednessFlags != EHandednessFlags.None && callback != null)
			{
				try
				{
					callbacksInfo.list[i].callback(eHandednessFlags);
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
		}
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private static EHandednessFlags _IsHandContributingToPressCadence(EHandednessFlags hand, _EPressCadence pressCadence, EControllerInputPressFlags cbFlags, EControllerInputPressFlags flags_now, EControllerInputPressFlags flags_old)
	{
		if ((pressCadence != _EPressCadence.Held || (cbFlags & flags_now) != cbFlags) && (pressCadence != _EPressCadence.Start || (cbFlags & flags_now) != cbFlags || (cbFlags & flags_old) == cbFlags) && (pressCadence != _EPressCadence.End || (cbFlags & flags_now) == cbFlags || (cbFlags & flags_old) != cbFlags))
		{
			return EHandednessFlags.None;
		}
		return hand;
	}
}
public class ChestHeartbeat : MonoBehaviour
{
	public int millisToWait;

	public int millisMin = 300;

	public int lastShot;

	public AudioSource audioSource;

	public Transform scaleTransform;

	private float deltaTime;

	private float heartMinSize = 0.9f;

	private float heartMaxSize = 1.2f;

	private float minTime = 0.05f;

	private float maxTime = 0.1f;

	private float endtime = 0.25f;

	private float currentTime;

	public void Update()
	{
		if (PhotonNetwork.InRoom)
		{
			if ((PhotonNetwork.ServerTimestamp > lastShot + millisMin || Mathf.Abs(PhotonNetwork.ServerTimestamp - lastShot) > 10000) && PhotonNetwork.ServerTimestamp % 1500 <= 10)
			{
				lastShot = PhotonNetwork.ServerTimestamp;
				audioSource.GTPlayOneShot(audioSource.clip);
				StartCoroutine(HeartBeat());
			}
		}
		else if ((Time.time * 1000f > (float)(lastShot + millisMin) || Mathf.Abs(Time.time * 1000f - (float)lastShot) > 10000f) && Time.time * 1000f % 1500f <= 10f)
		{
			lastShot = PhotonNetwork.ServerTimestamp;
			audioSource.GTPlayOneShot(audioSource.clip);
			StartCoroutine(HeartBeat());
		}
	}

	private IEnumerator HeartBeat()
	{
		float startTime = Time.time;
		while (Time.time < startTime + endtime)
		{
			if (Time.time < startTime + minTime)
			{
				deltaTime = Time.time - startTime;
				scaleTransform.localScale = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.one, UnityEngine.Vector3.one * heartMinSize, deltaTime / minTime);
			}
			else if (Time.time < startTime + maxTime)
			{
				deltaTime = Time.time - startTime - minTime;
				scaleTransform.localScale = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.one * heartMinSize, UnityEngine.Vector3.one * heartMaxSize, deltaTime / (maxTime - minTime));
			}
			else if (Time.time < startTime + endtime)
			{
				deltaTime = Time.time - startTime - maxTime;
				scaleTransform.localScale = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.one * heartMaxSize, UnityEngine.Vector3.one, deltaTime / (endtime - maxTime));
			}
			yield return new WaitForFixedUpdate();
		}
	}
}
public abstract class CosmeticCritter : MonoBehaviour
{
	[Tooltip("After this many seconds the critter will forcibly despawn.")]
	[SerializeField]
	protected float lifetime;

	[Tooltip("The maximum number of this kind of critter that can be in the room at any given time.")]
	[SerializeField]
	private int globalMaxCritters;

	protected double startTime;

	public int Seed { get; protected set; }

	public CosmeticCritterSpawner Spawner { get; protected set; }

	public Type CachedType { get; private set; }

	public int GetGlobalMaxCritters()
	{
		return globalMaxCritters;
	}

	public void SetSeedSpawnerTypeAndTime(int seed, CosmeticCritterSpawner spawner, Type type, double time)
	{
		Seed = seed;
		Spawner = spawner;
		CachedType = type;
		startTime = time;
	}

	public virtual void OnSpawn()
	{
	}

	public virtual void OnDespawn()
	{
	}

	public virtual void SetRandomVariables()
	{
	}

	public abstract void Tick();

	protected double GetAliveTime()
	{
		if (!PhotonNetwork.InRoom)
		{
			return Time.timeAsDouble - startTime;
		}
		return PhotonNetwork.Time - startTime;
	}

	public virtual bool Expired()
	{
		if (!(GetAliveTime() > (double)lifetime))
		{
			return GetAliveTime() < 0.0;
		}
		return true;
	}
}
public abstract class CosmeticCritterCatcher : CosmeticCritterHoldable
{
	[SerializeField]
	[Tooltip("If this catcher is capable of spawning immediately after catching, the linked spawner must be assigned here.")]
	protected CosmeticCritterSpawner optionalLinkedSpawner;

	public CosmeticCritterSpawner GetLinkedSpawner()
	{
		return optionalLinkedSpawner;
	}

	public abstract CosmeticCritterAction GetLocalCatchAction(CosmeticCritter critter);

	public virtual bool ValidateRemoteCatchAction(CosmeticCritter critter, CosmeticCritterAction catchAction, double serverTime)
	{
		return callLimiter.CheckCallServerTime(serverTime);
	}

	public abstract void OnCatch(CosmeticCritter critter, CosmeticCritterAction catchAction, double serverTime);

	protected override void OnEnable()
	{
		base.OnEnable();
		CosmeticCritterManager.Instance.RegisterCatcher(this);
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		CosmeticCritterManager.Instance.UnregisterCatcher(this);
	}
}
public abstract class CosmeticCritterHoldable : MonoBehaviour
{
	protected TransferrableObject transferrableObject;

	protected CallLimiter callLimiter;

	public int OwnerID { get; private set; }

	public bool IsLocal => transferrableObject.IsLocalObject();

	public bool OwningPlayerMatches(PhotonMessageInfoWrapped info)
	{
		return transferrableObject.targetRig.creator == info.Sender;
	}

	protected virtual CallLimiter CreateCallLimiter()
	{
		return new CallLimiter(10, 2f);
	}

	public void ResetCallLimiter()
	{
		callLimiter.Reset();
	}

	private void TrySetID()
	{
		if (IsLocal)
		{
			PlayFabAuthenticator instance = PlayFabAuthenticator.instance;
			if (instance != null)
			{
				OwnerID = (instance.GetPlayFabPlayerId() + GetType()).GetStaticHash();
			}
		}
		else if (transferrableObject.targetRig != null && transferrableObject.targetRig.creator != null)
		{
			OwnerID = (transferrableObject.targetRig.creator.UserId + GetType()).GetStaticHash();
		}
	}

	protected virtual void Awake()
	{
		transferrableObject = GetComponentInParent<TransferrableObject>();
		callLimiter = CreateCallLimiter();
		if (IsLocal)
		{
			CosmeticCritterManager.Instance.RegisterLocalHoldable(this);
		}
	}

	protected virtual void OnEnable()
	{
		TrySetID();
	}

	protected virtual void OnDisable()
	{
	}
}
[Flags]
public enum CosmeticCritterAction
{
	None = 0,
	RPC = 1,
	Spawn = 2,
	Despawn = 4,
	SpawnLinked = 8,
	ShadeHeartbeat = 0x10
}
public class CosmeticCritterManager : NetworkSceneObject, ITickSystemTick
{
	private List<CosmeticCritterHoldable> localHoldables;

	private List<CosmeticCritterSpawnerIndependent> localCritterSpawners;

	private List<CosmeticCritterSpawnerIndependent> remoteCritterSpawners;

	private List<CosmeticCritterCatcher> localCritterCatchers;

	private List<CosmeticCritterCatcher> remoteCritterCatchers;

	private List<CosmeticCritter> activeCritters;

	private Dictionary<Type, int> activeCrittersPerType;

	private Dictionary<int, CosmeticCritter> activeCrittersBySeed;

	private Dictionary<Type, Stack<CosmeticCritter>> inactiveCrittersByType;

	private Dictionary<Type, List<ICosmeticCritterTickForEach>> tickForEachCritterOfType;

	public static CosmeticCritterManager Instance { get; private set; }

	public bool TickRunning { get; set; }

	private new void OnEnable()
	{
		NetworkBehaviourUtils.InternalOnEnable(this);
		base.OnEnable();
		TickSystem<object>.AddTickCallback(this);
	}

	private new void OnDisable()
	{
		NetworkBehaviourUtils.InternalOnDisable(this);
		base.OnDisable();
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void RegisterLocalHoldable(CosmeticCritterHoldable holdable)
	{
		localHoldables.Add(holdable);
	}

	public void RegisterIndependentSpawner(CosmeticCritterSpawnerIndependent spawner)
	{
		if (spawner.IsLocal)
		{
			localCritterSpawners.AddIfNew(spawner);
		}
		else
		{
			remoteCritterSpawners.AddIfNew(spawner);
		}
	}

	public void UnregisterIndependentSpawner(CosmeticCritterSpawnerIndependent spawner)
	{
		if (spawner.IsLocal)
		{
			localCritterSpawners.Remove(spawner);
		}
		else
		{
			remoteCritterSpawners.Remove(spawner);
		}
	}

	public void RegisterCatcher(CosmeticCritterCatcher catcher)
	{
		if (catcher.IsLocal)
		{
			localCritterCatchers.AddIfNew(catcher);
		}
		else
		{
			remoteCritterCatchers.AddIfNew(catcher);
		}
	}

	public void UnregisterCatcher(CosmeticCritterCatcher catcher)
	{
		if (catcher.IsLocal)
		{
			localCritterCatchers.Remove(catcher);
		}
		else
		{
			remoteCritterCatchers.Remove(catcher);
		}
	}

	public void RegisterTickForEachCritter(Type type, ICosmeticCritterTickForEach target)
	{
		if (!tickForEachCritterOfType.TryGetValue(type, out var value) || value == null)
		{
			value = new List<ICosmeticCritterTickForEach>();
			tickForEachCritterOfType.Add(type, value);
		}
		value.AddIfNew(target);
	}

	public void UnregisterTickForEachCritter(Type type, ICosmeticCritterTickForEach target)
	{
		if (tickForEachCritterOfType.TryGetValue(type, out var value))
		{
			value?.Remove(target);
		}
	}

	private void ResetLocalCallLimiters()
	{
		int num = 0;
		while (num < localHoldables.Count)
		{
			if (localHoldables[num] == null)
			{
				localHoldables.RemoveAt(num);
				continue;
			}
			localHoldables[num].ResetCallLimiter();
			num++;
		}
	}

	private void ResetCosmeticCritters(NetPlayer player)
	{
		if (NetworkSystem.Instance.LocalPlayer == player)
		{
			ResetLocalCallLimiters();
			for (int i = 0; i < activeCritters.Count; i++)
			{
				FreeCritter(activeCritters[i]);
			}
		}
	}

	private void Awake()
	{
		if (Instance != null && Instance != this)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		Instance = this;
		localHoldables = new List<CosmeticCritterHoldable>();
		localCritterSpawners = new List<CosmeticCritterSpawnerIndependent>();
		remoteCritterSpawners = new List<CosmeticCritterSpawnerIndependent>();
		localCritterCatchers = new List<CosmeticCritterCatcher>();
		remoteCritterCatchers = new List<CosmeticCritterCatcher>();
		activeCritters = new List<CosmeticCritter>();
		activeCrittersPerType = new Dictionary<Type, int>();
		activeCrittersBySeed = new Dictionary<int, CosmeticCritter>();
		inactiveCrittersByType = new Dictionary<Type, Stack<CosmeticCritter>>();
		tickForEachCritterOfType = new Dictionary<Type, List<ICosmeticCritterTickForEach>>();
		NetworkSystem.Instance.OnPlayerJoined += new Action<NetPlayer>(ResetCosmeticCritters);
		NetworkSystem.Instance.OnPlayerLeft += new Action<NetPlayer>(ResetCosmeticCritters);
	}

	private void ReuseOrSpawnNewCritter(CosmeticCritterSpawner spawner, int seed, double time)
	{
		Type critterType = spawner.GetCritterType();
		CosmeticCritter result;
		if (!inactiveCrittersByType.TryGetValue(critterType, out var value))
		{
			value = new Stack<CosmeticCritter>();
			inactiveCrittersByType.Add(critterType, value);
			result = UnityEngine.Object.Instantiate(spawner.GetCritterPrefab(), base.transform).GetComponent<CosmeticCritter>();
		}
		else if (value.TryPop(out result))
		{
			result.gameObject.SetActive(value: true);
		}
		else
		{
			result = UnityEngine.Object.Instantiate(spawner.GetCritterPrefab(), base.transform).GetComponent<CosmeticCritter>();
		}
		result.SetSeedSpawnerTypeAndTime(seed, spawner, critterType, time);
		activeCritters.Add(result);
		if (!activeCrittersPerType.ContainsKey(critterType))
		{
			activeCrittersPerType.Add(critterType, 1);
		}
		else
		{
			activeCrittersPerType[critterType]++;
		}
		activeCrittersBySeed.Add(seed, result);
		UnityEngine.Random.State state = UnityEngine.Random.state;
		UnityEngine.Random.InitState(seed);
		spawner.SetRandomVariables(result);
		result.SetRandomVariables();
		UnityEngine.Random.state = state;
		spawner.OnSpawn(result);
		result.OnSpawn();
	}

	private void FreeCritter(CosmeticCritter critter)
	{
		critter.OnDespawn();
		if (critter.Spawner != null)
		{
			critter.Spawner.OnDespawn(critter);
		}
		critter.gameObject.SetActive(value: false);
		Type cachedType = critter.CachedType;
		if (!inactiveCrittersByType.TryGetValue(cachedType, out var value))
		{
			value = new Stack<CosmeticCritter>();
			inactiveCrittersByType.Add(cachedType, value);
		}
		value.Push(critter);
		activeCritters.Remove(critter);
		if (activeCrittersPerType.TryGetValue(cachedType, out var value2))
		{
			activeCrittersPerType[cachedType] = System.Math.Max(value2 - 1, 0);
		}
		activeCrittersBySeed.Remove(critter.Seed);
	}

	public void Tick()
	{
		for (int i = 0; i < activeCritters.Count; i++)
		{
			CosmeticCritter cosmeticCritter = activeCritters[i];
			if (cosmeticCritter.Expired())
			{
				FreeCritter(cosmeticCritter);
				continue;
			}
			cosmeticCritter.Tick();
			if (tickForEachCritterOfType.TryGetValue(cosmeticCritter.CachedType, out var value))
			{
				for (int j = 0; j < value.Count; j++)
				{
					value[j].TickForEachCritter(cosmeticCritter);
				}
			}
			for (int k = 0; k < localCritterCatchers.Count; k++)
			{
				CosmeticCritterCatcher cosmeticCritterCatcher = localCritterCatchers[k];
				CosmeticCritterAction localCatchAction = cosmeticCritterCatcher.GetLocalCatchAction(cosmeticCritter);
				if (localCatchAction != CosmeticCritterAction.None)
				{
					double num = (PhotonNetwork.InRoom ? PhotonNetwork.Time : Time.timeAsDouble);
					cosmeticCritterCatcher.OnCatch(cosmeticCritter, localCatchAction, num);
					if ((localCatchAction & CosmeticCritterAction.Despawn) != CosmeticCritterAction.None)
					{
						FreeCritter(cosmeticCritter);
						i--;
					}
					if ((localCatchAction & CosmeticCritterAction.SpawnLinked) != CosmeticCritterAction.None && cosmeticCritterCatcher.GetLinkedSpawner() != null)
					{
						ReuseOrSpawnNewCritter(cosmeticCritterCatcher.GetLinkedSpawner(), cosmeticCritter.Seed + 1, num);
					}
					if (PhotonNetwork.InRoom && (localCatchAction & CosmeticCritterAction.RPC) != CosmeticCritterAction.None)
					{
						photonView.RPC("CosmeticCritterRPC", RpcTarget.Others, localCatchAction, cosmeticCritterCatcher.OwnerID, cosmeticCritter.Seed);
					}
					break;
				}
			}
		}
		for (int l = 0; l < localCritterSpawners.Count; l++)
		{
			CosmeticCritterSpawnerIndependent cosmeticCritterSpawnerIndependent = localCritterSpawners[l];
			if ((activeCrittersPerType.TryGetValue(cosmeticCritterSpawnerIndependent.GetCritterType(), out var value2) && value2 >= cosmeticCritterSpawnerIndependent.GetCritter().GetGlobalMaxCritters()) || !cosmeticCritterSpawnerIndependent.CanSpawnLocal())
			{
				continue;
			}
			int num2 = UnityEngine.Random.Range(0, int.MaxValue);
			if (!activeCrittersBySeed.ContainsKey(num2))
			{
				ReuseOrSpawnNewCritter(cosmeticCritterSpawnerIndependent, num2, PhotonNetwork.InRoom ? PhotonNetwork.Time : Time.timeAsDouble);
				if (PhotonNetwork.InRoom)
				{
					photonView.RPC("CosmeticCritterRPC", RpcTarget.Others, CosmeticCritterAction.RPC | CosmeticCritterAction.Spawn, cosmeticCritterSpawnerIndependent.OwnerID, num2);
				}
			}
		}
	}

	[PunRPC]
	private void CosmeticCritterRPC(CosmeticCritterAction action, int holdableID, int seed, PhotonMessageInfo info)
	{
		PhotonMessageInfoWrapped photonMessageInfoWrapped = new PhotonMessageInfoWrapped(info);
		MonkeAgent.IncrementRPCCall(photonMessageInfoWrapped, "CosmeticCritterRPC");
		if ((action & CosmeticCritterAction.RPC) != CosmeticCritterAction.None)
		{
			if (action == (CosmeticCritterAction.RPC | CosmeticCritterAction.Spawn))
			{
				SpawnCosmeticCritterRPC(holdableID, seed, photonMessageInfoWrapped);
			}
			else
			{
				CatchCosmeticCritterRPC(action, holdableID, seed, photonMessageInfoWrapped);
			}
		}
	}

	private void CatchCosmeticCritterRPC(CosmeticCritterAction catchAction, int catcherID, int seed, PhotonMessageInfoWrapped info)
	{
		if (!activeCrittersBySeed.TryGetValue(seed, out var value))
		{
			return;
		}
		for (int i = 0; i < remoteCritterCatchers.Count; i++)
		{
			CosmeticCritterCatcher cosmeticCritterCatcher = remoteCritterCatchers[i];
			if (cosmeticCritterCatcher.OwnerID != catcherID)
			{
				continue;
			}
			if (cosmeticCritterCatcher.OwningPlayerMatches(info) && cosmeticCritterCatcher.ValidateRemoteCatchAction(value, catchAction, info.SentServerTime))
			{
				cosmeticCritterCatcher.OnCatch(value, catchAction, info.SentServerTime);
				if ((catchAction & CosmeticCritterAction.Despawn) != CosmeticCritterAction.None)
				{
					FreeCritter(value);
				}
				if ((catchAction & CosmeticCritterAction.SpawnLinked) != CosmeticCritterAction.None && cosmeticCritterCatcher.GetLinkedSpawner() != null && (!activeCrittersPerType.TryGetValue(cosmeticCritterCatcher.GetLinkedSpawner().GetCritterType(), out var value2) || value2 < cosmeticCritterCatcher.GetLinkedSpawner().GetCritter().GetGlobalMaxCritters() + 1))
				{
					ReuseOrSpawnNewCritter(cosmeticCritterCatcher.GetLinkedSpawner(), seed + 1, info.SentServerTime);
				}
			}
			break;
		}
	}

	private void SpawnCosmeticCritterRPC(int spawnerID, int seed, PhotonMessageInfoWrapped info)
	{
		if (activeCrittersBySeed.ContainsKey(seed))
		{
			return;
		}
		for (int i = 0; i < remoteCritterSpawners.Count; i++)
		{
			CosmeticCritterSpawnerIndependent cosmeticCritterSpawnerIndependent = remoteCritterSpawners[i];
			if (cosmeticCritterSpawnerIndependent.OwnerID == spawnerID)
			{
				if (cosmeticCritterSpawnerIndependent.OwningPlayerMatches(info) && (!activeCrittersPerType.TryGetValue(cosmeticCritterSpawnerIndependent.GetCritterType(), out var value) || value < cosmeticCritterSpawnerIndependent.GetCritter().GetGlobalMaxCritters()) && cosmeticCritterSpawnerIndependent.CanSpawnRemote(info.SentServerTime))
				{
					ReuseOrSpawnNewCritter(cosmeticCritterSpawnerIndependent, seed, info.SentServerTime);
				}
				break;
			}
		}
	}
}
public abstract class CosmeticCritterSpawner : CosmeticCritterHoldable
{
	[Tooltip("The critter prefab to spawn.")]
	[SerializeField]
	protected GameObject critterPrefab;

	[Tooltip("The maximum number of critters that this spawner can have active at once.")]
	[SerializeField]
	protected int maxCritters;

	protected CosmeticCritter cachedCritter;

	protected Type cachedType;

	protected int numCritters;

	protected float nextLocalSpawnTime;

	public GameObject GetCritterPrefab()
	{
		return critterPrefab;
	}

	public CosmeticCritter GetCritter()
	{
		return cachedCritter;
	}

	public Type GetCritterType()
	{
		return cachedType;
	}

	public virtual void SetRandomVariables(CosmeticCritter critter)
	{
	}

	public virtual void OnSpawn(CosmeticCritter critter)
	{
		numCritters++;
	}

	public virtual void OnDespawn(CosmeticCritter critter)
	{
		numCritters = System.Math.Max(numCritters - 1, 0);
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (cachedCritter == null)
		{
			cachedCritter = critterPrefab.GetComponent<CosmeticCritter>();
			cachedType = cachedCritter.GetType();
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
	}
}
public class CosmeticCritterSpawnerIndependent : CosmeticCritterSpawner
{
	public virtual bool CanSpawnLocal()
	{
		return numCritters < maxCritters;
	}

	public virtual bool CanSpawnRemote(double serverTime)
	{
		if (numCritters < maxCritters)
		{
			return callLimiter.CheckCallServerTime(serverTime);
		}
		return false;
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		CosmeticCritterManager.Instance.RegisterIndependentSpawner(this);
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		CosmeticCritterManager.Instance.UnregisterIndependentSpawner(this);
	}
}
public abstract class CosmeticCritterSpawnerTimed : CosmeticCritterSpawnerIndependent
{
	[Tooltip("The minimum and maximum time to wait between spawn attempts.")]
	[SerializeField]
	private UnityEngine.Vector2 spawnIntervalMinMax = new UnityEngine.Vector2(2f, 5f);

	[Tooltip("Currently does nothing.")]
	[SerializeField]
	[Range(0f, 1f)]
	private float spawnChance = 1f;

	protected override CallLimiter CreateCallLimiter()
	{
		return new CallLimiter(5, spawnIntervalMinMax.x);
	}

	public override bool CanSpawnLocal()
	{
		if (Time.time >= nextLocalSpawnTime)
		{
			nextLocalSpawnTime = Time.time + UnityEngine.Random.Range(spawnIntervalMinMax.x, spawnIntervalMinMax.y);
			return base.CanSpawnLocal();
		}
		return false;
	}

	public override bool CanSpawnRemote(double serverTime)
	{
		return base.CanSpawnRemote(serverTime);
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (base.IsLocal)
		{
			nextLocalSpawnTime = Time.time + UnityEngine.Random.Range(spawnIntervalMinMax.x, spawnIntervalMinMax.y);
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
	}
}
