	private void Setup()
	{
		_rig = GetComponentInParent<VRRig>();
		if ((bool)_rig)
		{
			_fingers = new VRMap[6] { _rig.leftThumb, _rig.leftIndex, _rig.leftMiddle, _rig.rightThumb, _rig.rightIndex, _rig.rightMiddle };
		}
	}

