			}
			int sourceFinger = (int)blendShapeTarget.sourceFinger;
			if (sourceFinger != -1)
			{
				SkinnedMeshRenderer targetRenderer = blendShapeTarget.targetRenderer;
				if ((bool)targetRenderer)
