		{
			_bobFloatPlaneY = bobRigidbody.position.y;
			_bobFloating = enable;
		}
	}

	private void QuickReel()
	{
		if (!_lineResizing)
		{
			bobCollider.enabled = false;
			ReelIn();
		}
	}

	public bool IsFreeHandGripping()
	{
		bool flag = InLeftHand();
		Transform transform = (flag ? rig.rightHandTransform : rig.leftHandTransform);
		float magnitude = (reelToSync.position - transform.position).magnitude;
		if (!(disableStealing = (bool)_grippingHand || magnitude <= 0.16f))
		{
			return false;
		}
		VRMapThumb vRMapThumb = (flag ? rig.rightThumb : rig.leftThumb);
		VRMapIndex vRMapIndex = (flag ? rig.rightIndex : rig.leftIndex);
		VRMapMiddle obj = (flag ? rig.rightMiddle : rig.leftMiddle);
		float calcT = vRMapThumb.calcT;
		float calcT2 = vRMapIndex.calcT;
		float calcT3 = obj.calcT;
		bool flag2 = calcT >= 0.1f && calcT2 >= 0.2f && calcT3 >= 0.2f;
		_grippingHand = (flag2 ? transform : null);
		return flag2;
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if ((bool)_grippingHand)
		{
			_grippingHand = null;
		}
		ResetLineLength(lineLengthMin * 1.32f);
		return true;
	}

	public void ReelIn()
	{
		_manualReeling = false;
		SetHandleMotorUse(useMotor: true, reelSpinRate, handleJoint, reverse: true);
		_lineResizing = true;
		_lineExpanding = false;
		float num = (float)line.segmentNumber + 0.0001f;
		line.segmentMinLength = (_targetSegmentMin = lineLengthMin / num);
		line.segmentMaxLength = (_targetSegmentMax = lineLengthMax / num);
	}

	public void ReelOut()
	{
		_manualReeling = false;
		SetHandleMotorUse(useMotor: true, reelSpinRate, handleJoint, reverse: false);
		_lineResizing = true;
		_lineExpanding = true;
		float num = (float)line.segmentNumber + 0.0001f;
		line.segmentMinLength = (_targetSegmentMin = lineLengthMin / num);
		line.segmentMaxLength = (_targetSegmentMax = lineLengthMax / num);
	}

	public void ReelStop()
	{
		if (_manualReeling)
		{
			_localRotDelta = 0f;
		}
		else
		{
			SetHandleMotorUse(useMotor: false, 0f, handleJoint, reverse: false);
		}
		bobCollider.enabled = true;
		if ((bool)line)
		{
			line.resizeScale = 1f;
		}
		_lineResizing = false;
		_lineExpanding = false;
	}

	private static void SetHandleMotorUse(bool useMotor, float spinRate, HingeJoint handleJoint, bool reverse)
	{
		JointMotor motor = handleJoint.motor;
		motor.force = (useMotor ? 1f : 0f) * spinRate;
		motor.targetVelocity = 16384f * (reverse ? (-1f) : 1f);
		handleJoint.motor = motor;
	}

	public override void TriggeredLateUpdate()
	{
		base.TriggeredLateUpdate();
		_manualReeling = (_isGrippingHandle = IsFreeHandGripping());
		if ((bool)ControllerInputPoller.instance && ControllerInputPoller.PrimaryButtonPress(InLeftHand() ? XRNode.LeftHand : XRNode.RightHand))
		{
			QuickReel();
		}
		if (_lineResetting && _sinceReset.HasElapsed(line.resizeSpeed))
		{
			bobCollider.enabled = true;
			_lineResetting = false;
		}
		handleTransform.localPosition = reelFreezeLocalPosition;
	}

	private void ResetLineLength(float length)
	{
		if ((bool)line)
		{
			_lineResetting = true;
			bobCollider.enabled = false;
			line.ForceTotalLength(length);
			_sinceReset = TimeSince.Now();
		}
	}

	private void FixedUpdate()
	{
		Transform transform = base.transform;
		handleRigidbody.useGravity = !_manualReeling;
		if (_bobFloating && (bool)bobRigidbody)
		{
			float y = bobRigidbody.position.y;
			float num = bobFloatForce * bobRigidbody.mass;
			float num2 = num * Mathf.Clamp01(_bobFloatPlaneY - y);
			num += num2;
			if (y <= _bobFloatPlaneY)
			{
				bobRigidbody.AddForce(0f, num, 0f);
			}
		}
		if (_manualReeling)
		{
			if (_isGrippingHandle && (bool)_grippingHand)
			{
				reelTo.position = _grippingHand.position;
			}
			UnityEngine.Vector3 toDirection = reelFrom.InverseTransformPoint(reelTo.position);
			toDirection.x = 0f;
			toDirection.Normalize();
			toDirection *= 2f;
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.forward, toDirection);
			quaternion2 = (InRightHand() ? quaternion2 : UnityEngine.Quaternion.Inverse(quaternion2));
			_localRotDelta = GetSignedDeltaYZ(ref _lastLocalRot, ref quaternion2);
			_lastLocalRot = quaternion2;
			UnityEngine.Quaternion rot = transform.rotation * quaternion2;
			handleRigidbody.MoveRotation(rot);
		}
		else
		{
			reelTo.localPosition = transform.InverseTransformPoint(reelToSync.position);
		}
		if (!line)
		{
			return;
		}
		if (_manualReeling)
		{
			_lineResizing = Mathf.Abs(_localRotDelta) >= 0.001f;
			_lineExpanding = Mathf.Sign(_localRotDelta) >= 0f;
		}
		if (!_lineResizing)
		{
			return;
		}
		float num3 = (_manualReeling ? (Mathf.Abs(_localRotDelta) * 0.66f * Time.fixedDeltaTime) : (lineResizeRate * lineCastFactor));
		line.resizeScale = lineCastFactor;
		float num4 = num3 * Time.fixedDeltaTime;
		float num5 = line.segmentTargetLength;
		if (_manualReeling)
		{
			float num6 = 1f / ((float)line.segmentNumber + 0.0001f);
			float num7 = lineLengthMin * num6;
			float num8 = lineLengthMax * num6;
			num4 *= (_lineExpanding ? 1f : (-1f));
			num4 *= (InRightHand() ? (-1f) : 1f);
			float num9 = num5 + num4;
			if (num9 > num7 && num9 < num8)
			{
				num5 += num4;
			}
		}
		else if (_lineExpanding)
		{
			if (num5 < _targetSegmentMax)
			{
				num5 += num4;
			}
			else
			{
				_lineResizing = false;
			}
		}
		else if (num5 > _targetSegmentMin)
		{
			num5 -= num4;
		}
		else
		{
			_lineResizing = false;
		}
		if (_lineResizing)
		{
			line.segmentTargetLength = num5;
		}
		else
		{
			ReelStop();
		}
	}

	private static float GetSignedDeltaYZ(ref UnityEngine.Quaternion a, ref UnityEngine.Quaternion b)
	{
		UnityEngine.Vector3 forward = UnityEngine.Vector3.forward;
		UnityEngine.Vector3 vector = a * forward;
		UnityEngine.Vector3 vector2 = b * forward;
		float current = Mathf.Atan2(vector.y, vector.z) * 57.29578f;
		float target = Mathf.Atan2(vector2.y, vector2.z) * 57.29578f;
		return Mathf.DeltaAngle(current, target);
	}
}
[RequireComponent(typeof(LineRenderer))]
public class FixedSizeTrail : MonoBehaviour
{
	[SerializeField]
	private Transform _transform;

	[SerializeField]
	private LineRenderer _lineRenderer;

	[SerializeField]
	[Range(1f, 128f)]
	private int _segments = 8;

	[SerializeField]
	private float _length = 8f;

	public bool manualUpdate;

	[Space]
	public bool applyPhysics;

	public UnityEngine.Vector3 gravity = new UnityEngine.Vector3(0f, -9.8f, 0f);

	public AnimationCurve gravityCurve = AnimationCurves.EaseInCubic;

	[Space]
	private UnityEngine.Vector3[] _points = new UnityEngine.Vector3[8];

	public LineRenderer renderer => _lineRenderer;

	public float length
	{
		get
		{
			return _length;
		}
		set
		{
			_length = System.Math.Clamp(value, 0f, 128f);
		}
	}

	public UnityEngine.Vector3[] points => _points;

	private void Reset()
	{
		Setup();
	}

	private void Awake()
	{
		Setup();
	}

	private void OnEnable()
	{
		Setup();
	}

	public void Setup()
	{
		_transform = base.transform;
		if (_lineRenderer == null)
		{
			_lineRenderer = GetComponent<LineRenderer>();
		}
		if ((bool)_lineRenderer)
		{
			_lineRenderer.useWorldSpace = true;
			UnityEngine.Vector3 position = _transform.position;
			UnityEngine.Vector3 forward = _transform.forward;
			int num = _segments + 1;
			_points = new UnityEngine.Vector3[num];
			float num2 = _length / (float)_segments;
			for (int i = 0; i < num; i++)
			{
				_points[i] = position - forward * num2 * i;
			}
			_lineRenderer.positionCount = num;
			_lineRenderer.SetPositions(_points);
			Update();
		}
	}

	private void Update()
	{
		if (!manualUpdate)
		{
			Update(Time.deltaTime);
		}
	}

	private void FixedUpdate()
	{
		if (applyPhysics)
		{
			float deltaTime = Time.deltaTime;
			int num = _points.Length - 1;
			_ = _length / (float)num;
			for (int i = 1; i < num; i++)
			{
				float time = (float)(i - 1) / (float)num;
				float num2 = gravityCurve.Evaluate(time);
				UnityEngine.Vector3 vector = gravity * (num2 * deltaTime);
				_points[i] += vector;
				_points[i + 1] += vector;
			}
		}
	}

	public void Update(float dt)
	{
		float num = _length / (float)(_segments - 1);
		UnityEngine.Vector3 position = _transform.position;
		_points[0] = position;
		float num2 = UnityEngine.Vector3.Distance(_points[0], _points[1]);
		float num3 = num - num2;
		if (num2 > num)
		{
			Array.Copy(_points, 0, _points, 1, _points.Length - 1);
		}
		for (int i = 0; i < _points.Length - 1; i++)
		{
			UnityEngine.Vector3 vector = _points[i];
			UnityEngine.Vector3 vector2 = _points[i + 1] - vector;
			if (vector2.sqrMagnitude > num * num)
			{
				_points[i + 1] = vector + vector2.normalized * num;
			}
		}
		if (num3 > 0f)
		{
			int num4 = _points.Length - 1;
			int num5 = num4 - 1;
			UnityEngine.Vector3 vector3 = _points[num4] - _points[num5];
			UnityEngine.Vector3 vector4 = vector3.normalized;
			if (applyPhysics)
			{
				UnityEngine.Vector3 normalized = (_points[num5] - _points[num5 - 1]).normalized;
				vector4 = UnityEngine.Vector3.Lerp(vector4, normalized, 0.5f);
			}
			_points[num4] = _points[num5] + vector4 * System.Math.Min(vector3.magnitude, num3);
		}
		_lineRenderer.SetPositions(_points);
	}

	private static float CalcLength(in UnityEngine.Vector3[] positions)
	{
		float num = 0f;
		for (int i = 0; i < positions.Length - 1; i++)
		{
			num += UnityEngine.Vector3.Distance(positions[i], positions[i + 1]);
		}
		return num;
	}
}
public class FixedSizeTrailAdjustBySpeed : MonoBehaviour
{
	[Serializable]
	public struct GradientKey(Color color, float time)
	{
		public Color color = color;

		public float time = time;
	}

	public FixedSizeTrail trail;

	public bool adjustPhysics = true;

	private UnityEngine.Vector3 _rawVelocity;

	private float _rawSpeed;

	private float _speed;

	private float _lastSpeed;

	private UnityEngine.Vector3 _lastPosition;

	private UnityEngine.Vector3 _initGravity;

	public UnityEngine.Vector3 gravityOffset = UnityEngine.Vector3.zero;

	[Space]
	public float retractMin = 0.5f;

	[Space]
	[FormerlySerializedAs("sizeIncreaseSpeed")]
	public float expandSpeed = 16f;

	[FormerlySerializedAs("sizeDecreaseSpeed")]
	public float retractSpeed = 4f;

	[Space]
	public float minSpeed;

	public float minLength = 1f;

	public Gradient minColors = GradientHelper.FromColor(new Color(0f, 1f, 1f, 1f));

	[Space]
	public float maxSpeed = 10f;

	public float maxLength = 8f;

	public Gradient maxColors = GradientHelper.FromColor(new Color(1f, 1f, 0f, 1f));

	[Space]
	[SerializeField]
	private Gradient _mixGradient = new Gradient
	{
		colorKeys = new GradientColorKey[8],
		alphaKeys = Array.Empty<GradientAlphaKey>()
	};

	private void Start()
	{
		Setup();
	}

	private void OnEnable()
	{
		ResetTrailState();
	}

	private void OnDisable()
	{
		ResetTrailState();
	}

	private void ResetTrailState()
	{
		_rawVelocity = UnityEngine.Vector3.zero;
		_rawSpeed = 0f;
		_speed = 0f;
		_lastSpeed = 0f;
		_lastPosition = base.transform.position;
		if ((bool)trail)
		{
			trail.length = minLength;
			trail.Setup();
			LerpTrailColors(0f);
		}
	}

	private void Setup()
	{
		_lastPosition = base.transform.position;
		_rawVelocity = UnityEngine.Vector3.zero;
		_rawSpeed = 0f;
		_speed = 0f;
		if ((bool)trail)
		{
			_initGravity = trail.gravity;
			trail.applyPhysics = adjustPhysics;
		}
		LerpTrailColors();
	}

	private void LerpTrailColors(float t = 0.5f)
	{
		GradientColorKey[] colorKeys = _mixGradient.colorKeys;
		int num = colorKeys.Length;
		for (int i = 0; i < num; i++)
		{
			float time = (float)i / (float)(num - 1);
			Color a = minColors.Evaluate(time);
			Color b = maxColors.Evaluate(time);
			Color color = Color.Lerp(a, b, t);
			colorKeys[i].color = color;
			colorKeys[i].time = time;
		}
		_mixGradient.colorKeys = colorKeys;
		if ((bool)trail)
		{
			trail.renderer.colorGradient = _mixGradient;
		}
	}

	private void Update()
	{
		float deltaTime = Time.deltaTime;
		UnityEngine.Vector3 position = base.transform.position;
		_rawVelocity = (position - _lastPosition) / deltaTime;
		_rawSpeed = _rawVelocity.magnitude;
		if (_rawSpeed > retractMin)
		{
			_speed += expandSpeed * deltaTime;
		}
		if (_rawSpeed <= retractMin)
		{
			_speed -= retractSpeed * deltaTime;
		}
		if (_speed > maxSpeed)
		{
			_speed = maxSpeed;
		}
		_speed = Mathf.Lerp(_lastSpeed, _speed, 0.5f);
		if (_speed < 0.01f)
		{
			_speed = 0f;
		}
		AdjustTrail();
		_lastSpeed = _speed;
		_lastPosition = position;
	}

	private void AdjustTrail()
	{
		if ((bool)trail)
		{
			float num = MathUtils.Linear(_speed, minSpeed, maxSpeed, 0f, 1f);
			float length = MathUtils.Linear(num, 0f, 1f, minLength, maxLength);
			trail.length = length;
			LerpTrailColors(num);
			if (adjustPhysics)
			{
				Transform transform = base.transform;
				UnityEngine.Vector3 vector = transform.forward * gravityOffset.z + transform.right * gravityOffset.x + transform.up * gravityOffset.y;
				UnityEngine.Vector3 b = (_initGravity + vector) * (1f - num);
				trail.gravity = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.zero, b, 0.5f);
			}
		}
	}
}
