	}

	public void InvokeUpdate()
	{
		if (manager == null)
		{
			manager = GetComponentInParent<FlockingManager>();
		}
		AvoidPlayerHands();
		MaybeTurn();
		switch (fishState)
		{
		case FishState.patrol:
			if (UnityEngine.Random.Range(0, 10) < 2)
			{
				SwitchState(FishState.flock);
			}
			break;
		case FishState.flock:
			Flock(FishArea.nextWaypoint);
			SwitchState(FishState.patrol);
			break;
		case FishState.followFood:
			if (isTurning)
			{
				return;
			}
			if (isRealFood)
			{
				if ((double)UnityEngine.Vector3.Distance(base.transform.position, projectileGameObject.transform.position) > FollowFoodStopDistance)
				{
					FollowFood();
					break;
				}
				followingFood = false;
				Flock(projectileGameObject.transform.position);
				feedingTimeStarted += Time.deltaTime;
				if (feedingTimeStarted > eatFoodDuration)
				{
					SwitchState(FishState.patrol);
				}
			}
			else if (UnityEngine.Vector3.Distance(base.transform.position, projectileGameObject.transform.position) > FollowFakeFoodStopDistance)
			{
				FollowFood();
			}
			else
			{
				followingFood = false;
				SwitchState(FishState.patrol);
			}
			break;
		}
		if (!followingFood)
		{
			base.transform.Translate(0f, 0f, speed * Time.deltaTime);
		}
		pos = base.transform.position;
		rot = base.transform.rotation;
	}

	private void MaybeTurn()
	{
		if (!manager.IsInside(base.transform.position, FishArea))
		{
			Turn(FishArea.colliderCenter);
			if (UnityEngine.Vector3.Angle(FishArea.colliderCenter - base.transform.position, UnityEngine.Vector3.forward) > 5f)
			{
				isTurning = true;
			}
		}
		else
		{
			isTurning = false;
		}
	}

	private void Turn(UnityEngine.Vector3 towardPoint)
	{
		isTurning = true;
		UnityEngine.Quaternion to = UnityEngine.Quaternion.LookRotation(towardPoint - base.transform.position);
		base.transform.rotation = UnityEngine.Quaternion.RotateTowards(base.transform.rotation, to, rotationSpeed * Time.deltaTime);
	}

	private void SwitchState(FishState state)
	{
		fishState = state;
	}

	private void Flock(UnityEngine.Vector3 nextGoal)
	{
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		UnityEngine.Vector3 zero2 = UnityEngine.Vector3.zero;
		float num = 1f;
		int num2 = 0;
		foreach (Flocking fish in FishArea.fishList)
		{
			if (!(fish.gameObject != base.gameObject))
			{
				continue;
			}
			float num3 = UnityEngine.Vector3.Distance(fish.transform.position, base.transform.position);
			if (num3 <= maxNeighbourDistance)
			{
				zero += fish.transform.position;
				num2++;
				if (num3 < flockingAvoidanceDistance)
				{
					zero2 += base.transform.position - fish.transform.position;
				}
				num += fish.speed;
			}
		}
		if (num2 > 0)
		{
			fishState = FishState.flock;
			zero = zero / num2 + (nextGoal - base.transform.position);
			speed = num / (float)num2;
			speed = Mathf.Clamp(speed, minSpeed, maxSpeed);
			UnityEngine.Vector3 vector = zero + zero2 - base.transform.position;
			if (vector != UnityEngine.Vector3.zero)
			{
				UnityEngine.Quaternion to = UnityEngine.Quaternion.LookRotation(vector);
				base.transform.rotation = UnityEngine.Quaternion.RotateTowards(base.transform.rotation, to, rotationSpeed * Time.deltaTime);
			}
		}
	}

	private void HandleOnFoodDetected(FlockingManager.FishFood fishFood)
	{
		bool flag = false;
		BoxCollider[] colliders = FishArea.colliders;
		foreach (BoxCollider boxCollider in colliders)
		{
			if (fishFood.collider == boxCollider)
			{
				flag = true;
			}
		}
		if (flag)
		{
			SwitchState(FishState.followFood);
			feedingTimeStarted = 0f;
			projectileGameObject = fishFood.slingshotProjectile.gameObject;
			isRealFood = fishFood.isRealFood;
		}
	}

	private void HandleOnFoodDestroyed(BoxCollider collider)
	{
		bool flag = false;
		BoxCollider[] colliders = FishArea.colliders;
		foreach (BoxCollider boxCollider in colliders)
		{
			if (collider == boxCollider)
			{
				flag = true;
			}
		}
		if (flag)
		{
			SwitchState(FishState.patrol);
			projectileGameObject = null;
			followingFood = false;
		}
	}

	private void FollowFood()
	{
		followingFood = true;
		UnityEngine.Quaternion to = UnityEngine.Quaternion.LookRotation(projectileGameObject.transform.position - base.transform.position);
		base.transform.rotation = UnityEngine.Quaternion.RotateTowards(base.transform.rotation, to, rotationSpeed * Time.deltaTime);
		base.transform.position = UnityEngine.Vector3.MoveTowards(base.transform.position, projectileGameObject.transform.position, speed * followFoodSpeedMult * Time.deltaTime);
	}

	private void AvoidPlayerHands()
	{
		foreach (GameObject avoidPoint in FlockingManager.avoidPoints)
		{
			UnityEngine.Vector3 position = avoidPoint.transform.position;
			if ((base.transform.position - position).IsShorterThan(avointPointRadius))
			{
