		{
			manager = GetComponentInParent<FlockingManager>();
		}
		if (FishArea == null)
		{
			UnityEngine.Debug.LogError("FISH AREA NULL");
		}
		if (syncRot.IsValid())
		{
			rot = syncRot;
		}
		if (syncPos.IsValid(10000f))
		{
			pos = manager.RestrictPointToArea(syncPos, FishArea);
		}
	}

	private void OnEnable()
	{
		if (manager == null)
		{
			manager = GetComponentInParent<FlockingManager>();
		}
		FlockingManager flockingManager = manager;
		flockingManager.onFoodDetected = (UnityAction<FlockingManager.FishFood>)Delegate.Combine(flockingManager.onFoodDetected, new UnityAction<FlockingManager.FishFood>(HandleOnFoodDetected));
		FlockingManager flockingManager2 = manager;
		flockingManager2.onFoodDestroyed = (UnityAction<BoxCollider>)Delegate.Combine(flockingManager2.onFoodDestroyed, new UnityAction<BoxCollider>(HandleOnFoodDestroyed));
		FlockingUpdateManager.RegisterFlocking(this);
	}
}
public class FlockingUpdateManager : MonoBehaviour
{
	public static FlockingUpdateManager instance;

	public static bool hasInstance = false;

	public static List<Flocking> allFlockings = new List<Flocking>();

	protected void Awake()
	{
		if (hasInstance && instance != null && instance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			SetInstance(this);
		}
	}

	public static void CreateManager()
	{
		SetInstance(new GameObject("FlockingUpdateManager").AddComponent<FlockingUpdateManager>());
	}

	private static void SetInstance(FlockingUpdateManager manager)
	{
		instance = manager;
		hasInstance = true;
		if (UnityEngine.Application.isPlaying)
		{
			UnityEngine.Object.DontDestroyOnLoad(manager);
		}
	}

	public static void RegisterFlocking(Flocking flocking)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (!allFlockings.Contains(flocking))
		{
			allFlockings.Add(flocking);
		}
	}

	public static void UnregisterFlocking(Flocking flocking)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (allFlockings.Contains(flocking))
		{
			allFlockings.Remove(flocking);
		}
	}

	public void Update()
	{
		for (int i = 0; i < allFlockings.Count; i++)
		{
			allFlockings[i].InvokeUpdate();
		}
	}
}
