[Serializable]
public struct GroupJoinZoneAB
{
	public GroupJoinZoneA a;

	public GroupJoinZoneB b;

	public static GroupJoinZoneAB operator &(GroupJoinZoneAB one, GroupJoinZoneAB two)
	{
		return new GroupJoinZoneAB
		{
			a = (one.a & two.a),
			b = (one.b & two.b)
		};
	}

	public static GroupJoinZoneAB operator |(GroupJoinZoneAB one, GroupJoinZoneAB two)
	{
		return new GroupJoinZoneAB
		{
			a = (one.a | two.a),
			b = (one.b | two.b)
		};
	}

	public static GroupJoinZoneAB operator ~(GroupJoinZoneAB z)
	{
		return new GroupJoinZoneAB
		{
			a = ~z.a,
			b = ~z.b
		};
	}

	public static bool operator ==(GroupJoinZoneAB one, GroupJoinZoneAB two)
	{
		if (one.a == two.a)
		{
			return one.b == two.b;
		}
		return false;
	}

	public static bool operator !=(GroupJoinZoneAB one, GroupJoinZoneAB two)
	{
		if (one.a == two.a)
		{
			return one.b != two.b;
		}
		return true;
	}

	public bool HasAnyFlag(GroupJoinZoneAB other)
	{
		if ((a & other.a) == 0)
		{
			return (b & other.b) != 0;
		}
		return true;
	}

	public override bool Equals(object other)
	{
		return this == (GroupJoinZoneAB)other;
	}

	public override int GetHashCode()
	{
		return a.GetHashCode() ^ b.GetHashCode();
	}

	public static implicit operator GroupJoinZoneAB(int d)
	{
		return new GroupJoinZoneAB
		{
			a = (GroupJoinZoneA)d
		};
	}

	public override string ToString()
	{
		if (b != 0)
		{
			if (a != 0)
			{
				return a.ToString() + "," + b;
			}
			return b.ToString();
		}
		return a.ToString();
	}
}
public interface IGameAgentComponent
{
	void OnEntityThink(float dt);
}
public class GameAgent : MonoBehaviour, IGameEntityComponent
{
	public delegate void StateChangedEvent(byte newState);

	public delegate void NavigationLinkReachedEvent(OffMeshLinkData linkData);

	public delegate void JumpRequestedEvent(UnityEngine.Vector3 start, UnityEngine.Vector3 end, float heightScale, float speedScale);

	public delegate void NavigationFailedEvent(NavMeshPathStatus status, UnityEngine.Vector3 destination, float remainingDistance);

	public GameEntity entity;

	public NavMeshAgent navAgent;

	public Rigidbody rigidBody;

	public float networkPositionCorrectionDist = 2.5f;

	[Unity.XR.CoreUtils.ReadOnly]
	public NetPlayer targetPlayer;

	private bool disableNetworkSync;

	private UnityEngine.Vector3 lastPosOnNavMesh;

	private UnityEngine.Vector3 lastRequestedDest;

	private UnityEngine.Vector3 lastReceivedDest;

	private bool hasNotifiedNavigationFailure;

	private List<IGameAgentComponent> agentComponents;

	private bool wasOnOffMeshNavLink;

	public bool navAgentless;

	[Unity.XR.CoreUtils.ReadOnly]
	public bool pauseEntityThink;

	public event StateChangedEvent onBodyStateChanged;

	public event StateChangedEvent onBehaviorStateChanged;

	public event NavigationLinkReachedEvent onReachedNavigationLink;

	public event JumpRequestedEvent onJumpRequested;

	public event NavigationFailedEvent onNavigationFailed;

	public GameAgentManager GetGameAgentManager()
	{
		return entity.manager.gameAgentManager;
	}

	private void Awake()
	{
		agentComponents = new List<IGameAgentComponent>(1);
		GetComponentsInChildren(agentComponents);
	}

	public void OnEntityInit()
	{
		GetGameAgentManager().AddGameAgent(this);
	}

	public void OnEntityDestroy()
	{
		GetGameAgentManager().RemoveGameAgent(this);
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	public void OnBehaviorStateChanged(byte newState)
	{
		this.onBehaviorStateChanged?.Invoke(newState);
	}

	public void OnBodyStateChanged(byte newState)
	{
		this.onBodyStateChanged?.Invoke(newState);
	}

	public void OnThink(float deltaTime)
	{
		if (!pauseEntityThink)
		{
			for (int i = 0; i < agentComponents.Count; i++)
			{
				agentComponents[i].OnEntityThink(deltaTime);
			}
		}
	}

	public void OnUpdate()
	{
		if (navAgent == null)
		{
			return;
		}
		if (navAgent.isOnNavMesh)
		{
			lastPosOnNavMesh = navAgent.transform.position;
		}
		if (!navAgent.autoTraverseOffMeshLink && !wasOnOffMeshNavLink && navAgent.isOnOffMeshLink)
		{
			if (entity.IsAuthority())
			{
				if ((navAgent.transform.position - navAgent.currentOffMeshLinkData.startPos).sqrMagnitude < (navAgent.transform.position - navAgent.currentOffMeshLinkData.endPos).sqrMagnitude)
				{
					GetGameAgentManager().RequestJump(this, navAgent.transform.position, navAgent.currentOffMeshLinkData.endPos, 1f, 1f);
				}
				else
				{
					GetGameAgentManager().RequestJump(this, navAgent.transform.position, navAgent.currentOffMeshLinkData.startPos, 1f, 1f);
				}
			}
			this.onReachedNavigationLink?.Invoke(navAgent.currentOffMeshLinkData);
		}
		wasOnOffMeshNavLink = navAgent.isOnOffMeshLink;
		if (!hasNotifiedNavigationFailure && !navAgent.pathPending && (navAgent.pathStatus == NavMeshPathStatus.PathPartial || navAgent.pathStatus == NavMeshPathStatus.PathInvalid))
		{
			this.onNavigationFailed?.Invoke(navAgent.pathStatus, navAgent.destination, navAgent.remainingDistance);
			hasNotifiedNavigationFailure = true;
		}
	}

	public void OnJumpRequested(UnityEngine.Vector3 start, UnityEngine.Vector3 end, float heightScale, float speedScale)
	{
		this.onJumpRequested?.Invoke(start, end, heightScale, speedScale);
	}

	public bool IsOnNavMesh()
	{
		if (navAgent != null)
		{
			return navAgent.isOnNavMesh;
		}
		return false;
	}

	public UnityEngine.Vector3 GetLastPosOnNavMesh()
	{
		return lastPosOnNavMesh;
	}

	public void RequestDestination(UnityEngine.Vector3 dest)
	{
		if (!entity.IsAuthority())
		{
			return;
		}
		if (!IsOnNavMesh())
		{
			dest = lastPosOnNavMesh;
		}
		if (!(UnityEngine.Vector3.Distance(lastRequestedDest, dest) < 0.5f))
		{
			lastRequestedDest = dest;
			if (entity.IsAuthority())
			{
				GetGameAgentManager().RequestDestination(this, dest);
			}
		}
	}

	public void RequestBehaviorChange(byte behavior)
	{
		GetGameAgentManager().RequestBehavior(this, behavior);
	}

	public void RequestStateChange(byte state)
	{
		GetGameAgentManager().RequestState(this, state);
	}

	public void RequestTarget(NetPlayer targetPlayer)
	{
		GetGameAgentManager().RequestTarget(this, targetPlayer);
	}

	public void ApplyDestination(UnityEngine.Vector3 dest)
	{
		if (NavMesh.SamplePosition(dest, out var hit, 1.5f, -1))
		{
			dest = hit.position;
			lastReceivedDest = dest;
			hasNotifiedNavigationFailure = false;
			if (navAgent != null && navAgent.isOnNavMesh)
			{
				navAgent.destination = dest;
			}
		}
	}

	public void SetDisableNetworkSync(bool disable)
	{
		disableNetworkSync = disable;
	}

	public void SetIsPathing(bool isPathing, bool ignoreRigiBody = false)
	{
		if (navAgent != null)
		{
			navAgent.enabled = isPathing;
		}
		if (!ignoreRigiBody && rigidBody != null)
		{
			rigidBody.isKinematic = isPathing;
		}
	}

	public void SetStopped(bool stopMovement)
	{
		if (navAgent != null)
		{
			navAgent.isStopped = stopMovement;
		}
	}

	public void SetSpeed(float speed)
	{
		if (navAgent != null)
		{
			navAgent.speed = speed;
		}
	}

	public void SetVelocity(UnityEngine.Vector3 vel)
	{
		if (navAgent != null)
		{
			navAgent.velocity = vel;
		}
	}

	public void ClearLastRequestedDestination()
	{
		lastRequestedDest = UnityEngine.Vector3.one * 10000f;
	}

	public void ApplyNetworkUpdate(UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		if (!disableNetworkSync)
		{
			if ((base.transform.position - position).sqrMagnitude > networkPositionCorrectionDist * networkPositionCorrectionDist && navAgent != null)
			{
				navAgent.Warp(position);
				navAgent.destination = lastReceivedDest;
			}
			base.transform.rotation = rotation;
			if (rigidBody != null)
			{
				rigidBody.rotation = rotation;
			}
		}
	}

	public static void UpdateFacing(Transform transform, NavMeshAgent navAgent, NetPlayer targetPlayer, float turnspeed = 3600f)
	{
		Transform target = null;
		_ = transform.forward;
		if (targetPlayer != null)
		{
			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
			}
		}
		UpdateFacingTarget(transform, navAgent, target, turnspeed);
	}

	public static void UpdateFacingTarget(Transform transform, NavMeshAgent navAgent, Transform target, float turnspeed = 3600f)
	{
		UnityEngine.Vector3 forward = transform.forward;
		if (target != null)
		{
			UnityEngine.Vector3 position = target.position;
			UnityEngine.Vector3 position2 = transform.position;
			UnityEngine.Vector3 vector = position - position2;
			vector.y = 0f;
			float magnitude = vector.magnitude;
			if (magnitude > 0f)
			{
				forward = vector / magnitude;
			}
		}
		else
		{
			UnityEngine.Vector3 vector2 = ((navAgent == null) ? UnityEngine.Vector3.zero : navAgent.desiredVelocity);
			vector2.y = 0f;
			float magnitude2 = vector2.magnitude;
			if (magnitude2 > 0f)
			{
				forward = vector2 / magnitude2;
			}
		}
		UnityEngine.Quaternion b = UnityEngine.Quaternion.LookRotation(forward);
		if (navAgent != null && navAgent.speed > 0f)
		{
			transform.rotation = UnityEngine.Quaternion.Lerp(transform.rotation, b, Mathf.Clamp(turnspeed * navAgent.speed / UnityEngine.Quaternion.Angle(transform.rotation, b) * Time.deltaTime, 0f, 1f));
		}
		else
		{
			transform.rotation = UnityEngine.Quaternion.Lerp(transform.rotation, b, Mathf.Clamp(turnspeed / UnityEngine.Quaternion.Angle(transform.rotation, b) * Time.deltaTime, 0f, 1f));
		}
	}

	public static void UpdateFacingForward(Transform transform, NavMeshAgent navAgent, float turnspeed = 3600f)
	{
		UnityEngine.Vector3 vector = ((navAgent == null) ? UnityEngine.Vector3.zero : navAgent.desiredVelocity);
		vector.y = 0f;
		float magnitude = vector.magnitude;
		if (!(magnitude <= 0f))
		{
			UnityEngine.Vector3 facingDir = vector / magnitude;
			UpdateFacingDir(transform, navAgent, facingDir, turnspeed);
		}
	}

	public static void UpdateFacingPos(Transform transform, NavMeshAgent navAgent, UnityEngine.Vector3 facingPos, float turnspeed = 3600f)
	{
		UnityEngine.Vector3 facingDir = facingPos - transform.position;
		facingDir.y = 0f;
		facingDir.Normalize();
		UpdateFacingDir(transform, navAgent, facingDir, turnspeed);
	}

	public static void UpdateFacingDir(Transform transform, NavMeshAgent navAgent, UnityEngine.Vector3 facingDir, float turnspeed = 3600f)
	{
		float num = ((navAgent == null) ? 0f : navAgent.speed);
		UnityEngine.Quaternion b = UnityEngine.Quaternion.LookRotation(facingDir);
		transform.rotation = UnityEngine.Quaternion.Lerp(transform.rotation, b, Mathf.Clamp(turnspeed * num / UnityEngine.Quaternion.Angle(transform.rotation, b) * Time.deltaTime, 0f, 1f));
	}
}
[NetworkBehaviourWeaved(0)]
public class GameAgentManager : NetworkComponent, ITickSystemTick
{
	public enum RPC
	{
		ApplyDestination,
		ApplyState,
		ApplyBehaviour,
		ApplyImpact,
		ApplyTarget
	}

	public const float MAX_JUMP_DISTANCE = 25f;

	public GameEntityManager entityManager;

	public PhotonView photonView;

	private List<GameAgent> agents;

	private float lastDestinationSentTime;

	private float destinationCooldown;

	private List<int> netIdsForDestination;

	private List<UnityEngine.Vector3> destinationsForDestination;

	private List<int> netIdsForState;

	private List<byte> statesForState;

	private float lastStateSentTime;

	private float stateCooldown;

	private List<int> netIdsForBehavior;

	private List<byte> behaviorsForBehavior;

	private float lastBehaviorSentTime;

	private float behaviorCooldown = 0.25f;

	private const int MAX_UPDATES_PER_FRAME = 4;

	private int nextAgentIndexUpdate;

	private const int MAX_THINK_PER_FRAME = 1;

	private int nextAgentIndexThink;

	public CallLimitersList<CallLimiter, RPC> m_RpcSpamChecks = new CallLimitersList<CallLimiter, RPC>();

	public bool TickRunning { get; set; }

	protected override void Awake()
	{
		agents = new List<GameAgent>(128);
		netIdsForDestination = new List<int>();
		destinationsForDestination = new List<UnityEngine.Vector3>();
		netIdsForState = new List<int>();
		statesForState = new List<byte>();
		netIdsForBehavior = new List<int>();
		behaviorsForBehavior = new List<byte>();
		nextAgentIndexUpdate = 0;
		nextAgentIndexThink = 0;
	}

	private new void OnEnable()
	{
		NetworkBehaviourUtils.InternalOnEnable(this);
		TickSystem<object>.AddCallbackTarget(this);
	}

	private new void OnDisable()
	{
		NetworkBehaviourUtils.InternalOnDisable(this);
		TickSystem<object>.RemoveCallbackTarget(this);
	}

	public static GameAgentManager Get(GameEntity gameEntity)
	{
		if (!(gameEntity == null) && !(gameEntity.manager == null))
		{
			return gameEntity.manager.gameAgentManager;
		}
		return null;
	}

	public List<GameAgent> GetAgents()
	{
		return agents;
	}

	public int GetGameAgentCount()
	{
		return agents.Count;
	}

	public void AddGameAgent(GameAgent gameAgent)
	{
		agents.Add(gameAgent);
	}

	public void RemoveGameAgent(GameAgent gameAgent)
	{
		agents.Remove(gameAgent);
	}

	public GameAgent GetGameAgent(GameEntityId id)
	{
		return entityManager.GetGameEntity(id).GetComponent<GameAgent>();
	}

	public void Tick()
	{
		if (IsAuthority())
		{
			int num = Mathf.Min(1, agents.Count);
			for (int i = 0; i < num; i++)
			{
				if (nextAgentIndexThink >= agents.Count)
				{
					nextAgentIndexThink = 0;
				}
				agents[nextAgentIndexThink].OnThink(Time.deltaTime);
				nextAgentIndexThink++;
			}
		}
		for (int j = 0; j < agents.Count; j++)
		{
			if (agents[j] != null)
			{
				agents[j].OnUpdate();
			}
		}
		if (IsAuthority())
		{
			if (netIdsForDestination.Count > 0 && Time.time > lastDestinationSentTime + destinationCooldown)
			{
				lastDestinationSentTime = Time.time;
				SendRPC("ApplyDestinationRPC", RpcTarget.All, netIdsForDestination.ToArray(), destinationsForDestination.ToArray());
				netIdsForDestination.Clear();
				destinationsForDestination.Clear();
			}
			if (netIdsForState.Count > 0 && Time.time > lastStateSentTime + stateCooldown)
			{
				lastStateSentTime = Time.time;
				SendRPC("ApplyStateRPC", RpcTarget.All, netIdsForState.ToArray(), statesForState.ToArray());
				netIdsForState.Clear();
				statesForState.Clear();
			}
			if (netIdsForBehavior.Count > 0 && Time.time > lastBehaviorSentTime + behaviorCooldown)
			{
				lastBehaviorSentTime = Time.time;
				SendRPC("ApplyBehaviorRPC", RpcTarget.All, netIdsForBehavior.ToArray(), behaviorsForBehavior.ToArray());
				netIdsForBehavior.Clear();
				behaviorsForBehavior.Clear();
			}
		}
	}

