public interface IGameActivatable
{
}
public class GameButtonActivatable : MonoBehaviour, IGameActivatable
{
	public enum InputButton
	{
		Trigger,
		ButtonA,
		ButtonB,
		Grip,
		Joystick
	}

	[SerializeField]
	public InputButton inputButton;

	public GameEntity gameEntity;

	public bool CheckInput(XRNode xrNode, float sensitivity = 0.25f)
	{
		return inputButton switch
		{
			InputButton.Trigger => ControllerInputPoller.TriggerFloat(xrNode) > sensitivity, 
			InputButton.ButtonA => ControllerInputPoller.PrimaryButtonPress(xrNode), 
			InputButton.ButtonB => ControllerInputPoller.SecondaryButtonPress(xrNode), 
			InputButton.Grip => ControllerInputPoller.GripFloat(xrNode) > sensitivity, 
			InputButton.Joystick => ControllerInputPoller.TriggerFloat(xrNode) > sensitivity, 
			_ => false, 
		};
	}

	public bool CheckInput(float sensitivity = 0.25f)
	{
		int equippedSlotIndex = gameEntity.EquippedSlotIndex;
		if (equippedSlotIndex == -1 || !gameEntity.IsHeldOrSnappedByLocalPlayer)
		{
			return false;
		}
		GamePlayer gamePlayer = GamePlayerLocal.instance.gamePlayer;
		if (gameEntity.IsSnappedToHand)
		{
			int num = equippedSlotIndex switch
			{
				2 => 0, 
				3 => 1, 
				_ => -1, 
			};
			if (gamePlayer.TryGetSlotEntity(num, out var out_entity) && out_entity.TryGetComponent<IGameActivatable>(out var _))
			{
				return false;
			}
			if (inputButton == InputButton.Trigger && GameTriggerInteractable.LocalInteractableTriggers.Count > 0)
			{
				UnityEngine.Vector3 position = gamePlayer.GetHandTransform(num).position;
				for (int i = 0; i < GameTriggerInteractable.LocalInteractableTriggers.Count; i++)
				{
					if (GameTriggerInteractable.LocalInteractableTriggers[i].PointWithinInteractableArea(position))
					{
						return false;
					}
				}
			}
		}
		return CheckInput(gameEntity.EquippedHandXRNode, sensitivity);
	}
}
public enum GameDockType
{
	GRToolDock
}
public class GameDock : MonoBehaviour
{
	public GameEntity gameEntity;

	public GameDockType dockType;

	public float dockRadius = 0.15f;

	public AbilitySound dockSound;

	public AbilitySound undockSound;

	public AbilityHaptic dockHaptic;

	public Transform dockMarker;

	private List<GameEntity> docked;

	private void Awake()
	{
		docked = new List<GameEntity>(1);
		if (dockMarker == null)
		{
			dockMarker = base.transform;
		}
	}

	private void OnEnable()
	{
	}

	public bool CanDock(GameDockable dockable)
	{
		if (dockable == null)
		{
			return false;
		}
		if (dockType == GameDockType.GRToolDock)
		{
			return GetDockedCount() <= 0;
		}
		return true;
	}

	public int GetDockedCount()
	{
		return docked.Count;
	}

	public void OnDock(GameEntity attachedGameEntity, GameEntity attachedToGameEntity)
	{
		dockSound.Play(null);
		docked.Add(attachedGameEntity);
		dockHaptic.PlayIfSnappedLocal(attachedToGameEntity);
	}

	public void OnUndock(GameEntity gameEntity, GameEntity attachedToGameEntity)
	{
		undockSound.Play(null);
		docked.Remove(gameEntity);
	}
}
public class GameDockable : MonoBehaviour
{
	public GameEntity gameEntity;

	public float dockableRadius = 0.15f;

	public Transform dockablePoint;

	private void Awake()
	{
	}

	public GameEntityId BestDock()
	{
		int heldByHandIndex = gameEntity.heldByHandIndex;
		if (heldByHandIndex < 0)
		{
			return GameEntityId.Invalid;
		}
		SnapJointType snapJointType = (GamePlayer.IsLeftHand(heldByHandIndex) ? SnapJointType.HandL : SnapJointType.HandR);
		SnapJointType snapJointType2 = (GamePlayer.IsLeftHand(heldByHandIndex) ? SnapJointType.ForearmL : SnapJointType.ForearmR);
		GamePlayer gamePlayer = GamePlayerLocal.instance.gamePlayer;
		List<SuperInfectionSnapPoint> snapPoints = gamePlayer.snapPointManager.SnapPoints;
		float num = float.MaxValue;
		GameDock gameDock = null;
		for (int i = 0; i < snapPoints.Count; i++)
		{
			if (snapPoints[i].jointType == snapJointType || snapPoints[i].jointType == snapJointType2)
			{
				continue;
			}
			GameEntity snappedEntity = snapPoints[i].GetSnappedEntity();
			if (snappedEntity == null)
			{
				continue;
			}
			GameDock component = snappedEntity.GetComponent<GameDock>();
			if (!(component == null) && component.CanDock(this))
			{
				Transform obj = component.dockMarker.transform;
				UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
				UnityEngine.Quaternion identity = UnityEngine.Quaternion.identity;
				float num2 = UnityEngine.Vector3.Distance(obj.TransformPoint(identity * zero), base.transform.position);
				float num3 = dockableRadius + component.dockRadius;
				if (num2 < num && num2 < num3)
				{
					num = num2;
					gameDock = component;
				}
			}
		}
		for (int j = 0; j < 2; j++)
		{
			GameEntity grabbedGameEntity = gamePlayer.GetGrabbedGameEntity(j);
			if (grabbedGameEntity == null)
			{
				continue;
			}
			GameDock component2 = grabbedGameEntity.GetComponent<GameDock>();
			if (!(component2 == null) && component2.CanDock(this))
			{
				Transform obj2 = component2.dockMarker.transform;
				UnityEngine.Vector3 zero2 = UnityEngine.Vector3.zero;
				UnityEngine.Quaternion identity2 = UnityEngine.Quaternion.identity;
				float num2 = UnityEngine.Vector3.Distance(obj2.TransformPoint(identity2 * zero2), base.transform.position);
				float num4 = dockableRadius + component2.dockRadius;
				if (num2 < num && num2 < num4)
				{
					num = num2;
					gameDock = component2;
				}
			}
		}
		if (gameDock == null)
		{
			return GameEntityId.Invalid;
		}
		return gameDock.gameEntity.id;
	}

	public Transform GetDockablePoint()
	{
		if (!(dockablePoint == null))
		{
			return dockablePoint;
		}
		return base.transform;
	}

	public void OnDock(GameEntity gameEntity, GameEntity attachedToGameEntity)
	{
	}

	public void OnUndock(GameEntity gameEntity, GameEntity attachedToGameEntity)
	{
	}
}
