	[DebugReadout]
	public GameEntityId id { get; internal set; }

	[DebugReadout]
	public int typeId { get; internal set; }

	[DebugReadout]
	public long createData { get; set; }

	[DebugReadout]
	public GameEntityId createdByEntityId { get; set; }

	[DebugReadout]
	public int heldByActorNumber { get; internal set; }

	[DebugReadout]
	public int snappedByActorNumber { get; internal set; }

	[DebugReadout]
	public int slotIndex
	{
		get
		{
			if (heldByHandIndex == -1)
			{
				return GameSnappable.GetJointToSnapIndex(snappedJoint);
			}
			return heldByHandIndex;
		}
	}

	[DebugReadout]
	public SnapJointType snappedJoint { get; internal set; }

	[DebugReadout]
	public int heldByHandIndex { get; internal set; }

	[DebugReadout]
	public int lastHeldByActorNumber { get; internal set; }

	[DebugReadout]
	public int onlyGrabActorNumber { get; internal set; }

	[DebugReadout]
	public GameEntityId attachedToEntityId { get; internal set; }

	public bool IsScenePlaced { get; internal set; }

	public bool IsHeldOrSnappedByLocalPlayer => AttachedPlayerActorNr == NetworkSystem.Instance.LocalPlayer.ActorNumber;

	public bool IsSnappedToHand => (snappedJoint & (SnapJointType.HandL | SnapJointType.HandR)) != 0;

	public int AttachedPlayerActorNr
	{
		get
		{
			if (heldByActorNumber == -1)
			{
				return snappedByActorNumber;
			}
			return heldByActorNumber;
		}
	}

	public int EquippedSlotIndex
	{
		get
		{
			if (heldByHandIndex == -1)
			{
				if ((snappedJoint & SnapJointType.HandL) == 0)
				{
					if ((snappedJoint & SnapJointType.HandR) == 0)
					{
						return -1;
					}
					return 3;
				}
				return 2;
			}
			return heldByHandIndex;
		}
	}

	public EHandedness EquippedHandedness
	{
		get
		{
			if (heldByHandIndex != 0 && (snappedJoint & SnapJointType.HandL) == 0)
			{
				if (heldByHandIndex != 1 && (snappedJoint & SnapJointType.HandR) == 0)
				{
					return EHandedness.None;
				}
				return EHandedness.Right;
			}
			return EHandedness.Left;
		}
	}

	public XRNode EquippedHandXRNode
	{
		get
		{
			if (heldByHandIndex != 0 && (snappedJoint & SnapJointType.HandL) == 0)
			{
				if (heldByHandIndex != 1 && (snappedJoint & SnapJointType.HandR) == 0)
				{
					return (XRNode)(-1);
				}
				return XRNode.RightHand;
			}
			return XRNode.LeftHand;
		}
	}

	public event StateChangedEvent OnStateChanged;

	public event EntityDestroyedEvent onEntityDestroyed;

	private void Awake()
	{
		id = GameEntityId.Invalid;
		rigidBody = GetComponent<Rigidbody>();
		if (gravityController == null)
		{
			gravityController = GetComponent<MonkeGravityController>();
			if (gravityController == null)
			{
				gravityController = base.gameObject.AddComponent<MonkeGravityController>();
			}
		}
		heldByActorNumber = -1;
		heldByHandIndex = -1;
		onlyGrabActorNumber = -1;
		snappedByActorNumber = -1;
		attachedToEntityId = GameEntityId.Invalid;
		entityComponents = new List<IGameEntityComponent>(1);
		GetComponentsInChildren(entityComponents);
		entitySerialize = new List<IGameEntitySerialize>(1);
		GetComponentsInChildren(entitySerialize);
		if (builtInEntities != null)
		{
			for (int i = 0; i < builtInEntities.Count; i++)
			{
				builtInEntities[i].isBuiltIn = true;
			}
		}
		if (TryGetComponent<XSceneRefTarget>(out var component) && component.UniqueID > 0)
		{
			IsScenePlaced = true;
			GameEntityManager.RegisterScenePlacedEntity(this);
		}
	}

	private void Start()
	{
		if (IsScenePlaced && !PhotonNetwork.InRoom)
		{
			base.gameObject.SetActive(value: false);
		}
	}

	public void Create(GameEntityManager manager, int netId, int typeId)
	{
		this.manager = manager;
		this.typeId = typeId;
		if (builtInEntities != null)
		{
			bool flag = netId < -1 && netId != int.MinValue;
			for (int i = 0; i < builtInEntities.Count; i++)
			{
				int netId2 = (flag ? (netId - 1 - i) : (netId + 1 + i));
				manager.AddGameEntity(netId2, builtInEntities[i]);
				builtInEntities[i].Create(manager, netId2, -1);
			}
		}
	}

	public void Init(long createData, int createdByEntityNetId)
	{
		this.createData = createData;
		createdByEntityId = manager.GetEntityIdFromNetId(createdByEntityNetId);
		for (int i = 0; i < entityComponents.Count; i++)
		{
			entityComponents[i].OnEntityInit();
		}
		for (int j = 0; j < builtInEntities.Count; j++)
		{
			builtInEntities[j].Init(0L, -1);
		}
	}

	public void OnDestroy()
	{
		if (!GTAppState.isQuitting)
		{
			for (int i = 0; i < entityComponents.Count; i++)
			{
				entityComponents[i].OnEntityDestroy();
			}
			this.onEntityDestroyed?.Invoke(this);
			if (IsScenePlaced)
			{
				GameEntityManager.UnregisterScenePlacedEntity(this);
			}
		}
	}

	public RendererSet GetGrabbableRenderers()
	{
		if (_grabbableRenderers == null)
		{
			_grabbableRenderers = new RendererSet();
			_meshFilters = new List<MeshFilter>();
			GetComponentsInChildren(includeInactive: true, _meshFilters);
			GetComponentsInChildren(includeInactive: true, _grabbableRenderers.skinnedRenderers);
			List<SkinnedMeshRenderer> skinnedRenderers = _grabbableRenderers.skinnedRenderers;
			RemoveNotOwnedComponents<MeshFilter>(_meshFilters);
			RemoveNotOwnedComponents<SkinnedMeshRenderer>(skinnedRenderers);
			GameObject[] array = ignoreObjectGrabRenderers;
			foreach (GameObject gameObject in array)
			{
				for (int j = 0; j < _meshFilters.Count; j++)
				{
					if (_meshFilters[j].gameObject == gameObject)
					{
						_meshFilters.RemoveAtSwapBack(j--);
					}
				}
				for (int k = 0; k < skinnedRenderers.Count; k++)
				{
					if (skinnedRenderers[k].gameObject == gameObject)
					{
						skinnedRenderers.RemoveAtSwapBack(k--);
					}
				}
			}
			foreach (MeshFilter meshFilter in _meshFilters)
			{
				MeshRenderer component = meshFilter.GetComponent<MeshRenderer>();
				if ((object)component != null)
				{
					_grabbableRenderers.renderers.Add((meshFilter, component));
				}
			}
		}
		return _grabbableRenderers;
		void RemoveNotOwnedComponents<T>(List<T> components) where T : UnityEngine.Component
		{
			for (int l = 0; l < components.Count; l++)
			{
				if (manager.GetParentEntity<GameEntity>(components[l].transform) != this)
				{
					components.RemoveAtSwapBack(l--);
				}
			}
		}
	}

	public UnityEngine.Vector3 GetVelocity()
	{
		if (rigidBody == null)
		{
			return UnityEngine.Vector3.zero;
		}
		return rigidBody.linearVelocity;
	}

	public void PlayCatchFx()
	{
		if (audioSource != null && audioSource.isActiveAndEnabled)
		{
			audioSource.volume = catchSoundVolume;
			audioSource.GTPlayOneShot(catchSound);
		}
	}

	public void PlayThrowFx()
	{
		if (audioSource != null && audioSource.isActiveAndEnabled)
		{
			audioSource.volume = throwSoundVolume;
			audioSource.GTPlayOneShot(throwSound);
		}
	}

	public void PlaySnapFx()
	{
		if (audioSource != null && audioSource.isActiveAndEnabled)
		{
			audioSource.volume = snapSoundVolume;
			audioSource.GTPlayOneShot(snapSound);
		}
	}

	private bool IsGamePlayer(Collider collider)
	{
		return GamePlayer.GetGamePlayer(collider) != null;
	}

	public long GetState()
	{
		return state;
	}

	public void RequestState(GameEntityId id, long newState)
	{
		manager.RequestState(id, newState);
	}

	public bool IsAuthority()
	{
		return manager.IsAuthority();
	}

	public bool IsValidToMigrate()
	{
		return manager.IsEntityValidToMigrate(this);
	}

	public void SetState(long newState)
	{
		if (state != newState)
		{
			long prevState = state;
			state = newState;
			this.OnStateChanged?.Invoke(prevState, newState);
			for (int i = 0; i < entityComponents.Count; i++)
			{
				entityComponents[i].OnEntityStateChange(prevState, newState);
			}
		}
	}

	public GameEntityId MigrateToEntityManager(GameEntityManager newManager)
	{
		if (IsScenePlaced)
		{
			if (manager != null)
			{
				manager.ReleaseScenePlacedHold(this);
			}
			return id;
		}
		manager.RemoveGameEntity(this);
		manager = newManager;
		GameEntityId result = (id = newManager.AddGameEntity(this));
		manager.InitItemLocal(this, createData, -1);
		return result;
	}

	public void MigrateHeldBy(int actorNumber)
	{
		if (heldByActorNumber >= 0)
		{
			heldByActorNumber = actorNumber;
		}
	}

	public void MigrateSnappedBy(int actorNumber)
	{
		if (snappedByActorNumber >= 0)
		{
			snappedByActorNumber = actorNumber;
		}
	}

	public int GetNetId(GameEntityId gameEntityId)
	{
		return manager.GetNetIdFromEntityId(gameEntityId);
	}

	public int GetNetId()
	{
		return manager.GetNetIdFromEntityId(id);
	}

	public static GameEntity Get(Collider collider)
	{
		if (collider == null)
		{
			return null;
		}
		Transform parent = collider.transform;
		while (parent != null)
		{
			GameEntity component = parent.GetComponent<GameEntity>();
			if (component != null)
			{
				return component;
			}
			parent = parent.parent;
		}
		return null;
	}

	public bool IsHeldByLocalPlayer()
	{
		return heldByActorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber;
	}

	public bool IsSnappedByLocalPlayer()
	{
		return snappedByActorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber;
	}

	public bool IsHeld()
	{
		return heldByActorNumber != -1;
	}

	public int GetLastHeldByPlayerForEntityID(GameEntityId gameEntityId)
	{
		GameEntity gameEntity = manager.GetGameEntity(gameEntityId);
		if (gameEntity != null)
		{
			return gameEntity.lastHeldByActorNumber;
		}
		return 0;
	}

	public bool WasLastHeldByLocalPlayer()
	{
		return lastHeldByActorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber;
	}

	public bool IsAttachedToPlayer(NetPlayer player)
	{
		if (player != null)
		{
			if (heldByActorNumber != player.ActorNumber)
			{
				return snappedByActorNumber == player.ActorNumber;
			}
			return true;
		}
		return false;
	}
}
public class GameEntityDelayedDestroy : MonoBehaviour, IDelayedExecListener
{
	[Serializable]
	public struct Options
	{
		public float delay;

		[Tooltip("Optional. If not set then a sound will be played at the transforms position. Which if it is a long clip on a transform that moves a lot then it will feel wrong without this set.")]
		public AudioSource audioSource;

		public AudioClip explosionSound;

		public float explosionVolume;

		public GameObject pooledExplosionPrefab;

		public AudioClip beepSound;

		public float beepVolume;

		[Tooltip("Beep phases keyed by seconds remaining. Must be ordered from most to least time remaining.")]
		public BeepPhase[] beepPhases;
	}

	[Serializable]
	public struct BeepPhase
	{
		[Tooltip("Beeping starts when this many seconds remain.")]
		public float timeRemaining;

		[Tooltip("Seconds between beeps during this phase.")]
		public float interval;
	}

	[SerializeField]
	private Options m_options = new Options
	{
		delay = 3f,
		audioSource = null,
		explosionSound = null,
		explosionVolume = 1f,
		pooledExplosionPrefab = null,
		beepSound = null,
		beepVolume = 1f,
		beepPhases = null
	};

	private GameEntity _entity;

	private int _callGenerationId;

	private int _delayedExplosionAudioIndex = -1;

	private int _delayedExplosionPoolIndex = -1;

	private const int k_contextId_deferredStart = 0;

	internal void Configure(Options options)
	{
		m_options = options;
		if ((m_options.beepSound != null || m_options.explosionSound != null) && m_options.audioSource == null)
		{
			m_options.audioSource = GetComponentInChildren<AudioSource>();
		}
	}

	protected void OnDestroy()
	{
		if (_delayedExplosionAudioIndex >= 0)
		{
			GTAudioOneShot.CancelDelayed(_delayedExplosionAudioIndex);
			_delayedExplosionAudioIndex = -1;
		}
		if (_delayedExplosionPoolIndex >= 0)
		{
			ObjectPools.CancelDelayedInstantiate(_delayedExplosionPoolIndex);
			_delayedExplosionPoolIndex = -1;
		}
	}

	protected void Start()
	{
		_entity = GetComponent<GameEntity>();
		if (_entity == null)
		{
			UnityEngine.Debug.LogError("GameEntityDelayedDestroy: No GameEntity found. Must be added to the same GameObject of the GameEntity you are trying to destroy with a delay.");
		}
		else
		{
			GTDelayedExec.Add(this, 0f, 0);
		}
	}

	internal void ResetTimer()
	{
		_callGenerationId++;
		int callGenerationId = _callGenerationId;
		int contextId = (callGenerationId << 1) | 1;
		Options options = m_options;
		GTDelayedExec.Add(this, options.delay, contextId);
		if (options.explosionSound != null)
		{
			_delayedExplosionAudioIndex = GTAudioOneShot.PlayDelayed(options.explosionSound, base.transform.parent, base.transform.localPosition, options.delay, options.explosionVolume);
		}
		else
		{
			_delayedExplosionAudioIndex = -1;
		}
		if (options.pooledExplosionPrefab != null)
		{
			_delayedExplosionPoolIndex = ObjectPools.InstantiateDelayed(options.pooledExplosionPrefab, base.transform.parent, base.transform.localPosition, options.delay);
		}
		else
		{
			_delayedExplosionPoolIndex = -1;
		}
		if (options.beepSound == null || options.beepPhases == null || options.beepPhases.Length == 0)
		{
			return;
		}
		int contextId2 = callGenerationId << 1;
		for (int i = 0; i < options.beepPhases.Length; i++)
		{
			float interval = options.beepPhases[i].interval;
			if (interval <= 0f)
			{
				continue;
			}
			float num = ((i + 1 < options.beepPhases.Length) ? options.beepPhases[i + 1].timeRemaining : 0f);
			float num2 = Mathf.Min(options.beepPhases[i].timeRemaining, options.delay);
			if (!(num2 <= num))
			{
				float num3 = options.delay - num2;
				float num4 = options.delay - num;
				for (float num5 = num3; num5 < num4; num5 += interval)
				{
					GTDelayedExec.Add(this, num5, contextId2);
				}
			}
		}
	}

	void IDelayedExecListener.OnDelayedAction(int contextId)
	{
		if (contextId == 0)
		{
			if (_callGenerationId == 0 && _entity != null)
			{
				ResetTimer();
			}
		}
		else
		{
			if (contextId >> 1 != _callGenerationId || _entity == null)
			{
				return;
			}
			Options options = m_options;
			if ((contextId & 1) != 0)
			{
				_entity.manager.RequestDestroyItem(_entity.id);
				return;
			}
			if (_delayedExplosionAudioIndex >= 0)
			{
				GTAudioOneShot.UpdateDelayed(_delayedExplosionAudioIndex, base.transform.parent, base.transform.localPosition);
			}
			if (_delayedExplosionPoolIndex >= 0)
			{
				ObjectPools.UpdateDelayedInstantiate(_delayedExplosionPoolIndex, base.transform.parent, base.transform.localPosition);
			}
			if (options.beepSound != null)
			{
				if (options.audioSource != null && options.audioSource.isActiveAndEnabled)
				{
					options.audioSource.GTPlayOneShot(options.beepSound, options.beepVolume);
				}
				else
				{
					GTAudioOneShot.Play(options.beepSound, base.transform.position, options.beepVolume);
				}
			}
		}
	}
}
public class GameEntityDelayedReturn : MonoBehaviour, IGameEntityComponent, IDelayedExecListener
{
	[Serializable]
	public struct Options
	{
		public float delay;

		[Tooltip("Seconds the entity stays hidden between disappear and reappear.")]
		public float reappearDelay;

		public AudioClip disappearSound;

		public float disappearVolume;

		public GameObject pooledDisappearPrefab;

		public AudioClip reappearSound;

		public float reappearVolume;

		public GameObject pooledReappearPrefab;

		public AudioClip beepSound;

		public float beepVolume;

		[Tooltip("Beep phases keyed by seconds remaining. Must be ordered from most to least time remaining.")]
		public BeepPhase[] beepPhases;
	}

	[Serializable]
	public struct BeepPhase
	{
		[Tooltip("Beeping starts when this many seconds remain.")]
		public float timeRemaining;

		[Tooltip("Seconds between beeps during this phase.")]
		public float interval;
	}

	private const int k_actionBits = 2;

	private const int k_actionMask = 3;

	private const int k_actionBeep = 0;

	private const int k_actionDisappear = 1;

	private const int k_actionReappear = 2;

	public GameEntity gameEntity;

	[SerializeField]
	private Options m_options = new Options
	{
		delay = 30f,
		reappearDelay = 0.5f,
		disappearSound = null,
		disappearVolume = 1f,
		pooledDisappearPrefab = null,
		reappearSound = null,
		reappearVolume = 1f,
		pooledReappearPrefab = null,
		beepSound = null,
		beepVolume = 1f,
		beepPhases = null
	};

	[Tooltip("If set, the entity teleports here instead of its initial position.")]
	public Transform resetTarget;

	[Tooltip("If true, the Rigidbody is forced kinematic after return regardless of its initial state.")]
	public bool forceKinematicOnReset;

	private UnityEngine.Vector3 initialPosition;

	private UnityEngine.Quaternion initialRotation;

	private UnityEngine.Vector3 initialScale;

	private bool initialIsKinematic;

	private bool initialized;

	private int _callGenerationId;

	private int _delayedDisappearAudioIndex = -1;

	private int _delayedDisappearPoolIndex = -1;

	private bool _timerRunning;

	public void OnEntityInit()
	{
		Transform transform = base.transform;
		initialPosition = transform.position;
		initialRotation = transform.rotation;
		initialScale = transform.localScale;
		Rigidbody componentInParent = GetComponentInParent<Rigidbody>();
		initialIsKinematic = componentInParent != null && componentInParent.isKinematic;
		initialized = true;
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(OnInteractionStarted));
		GameEntity obj2 = gameEntity;
		obj2.OnSnapped = (Action)Delegate.Combine(obj2.OnSnapped, new Action(OnInteractionStarted));
		GameEntity obj3 = gameEntity;
		obj3.OnAttached = (Action)Delegate.Combine(obj3.OnAttached, new Action(OnInteractionStarted));
		GameEntity obj4 = gameEntity;
		obj4.OnReleased = (Action)Delegate.Combine(obj4.OnReleased, new Action(OnInteractionEnded));
		GameEntity obj5 = gameEntity;
		obj5.OnUnsnapped = (Action)Delegate.Combine(obj5.OnUnsnapped, new Action(OnInteractionEnded));
		GameEntity obj6 = gameEntity;
		obj6.OnDetached = (Action)Delegate.Combine(obj6.OnDetached, new Action(OnInteractionEnded));
		if (!IsCurrentlyInteracting())
		{
			StartTimer();
		}
	}

	public void OnEntityDestroy()
	{
		if (initialized)
		{
			GameEntity obj = gameEntity;
			obj.OnGrabbed = (Action)Delegate.Remove(obj.OnGrabbed, new Action(OnInteractionStarted));
			GameEntity obj2 = gameEntity;
			obj2.OnSnapped = (Action)Delegate.Remove(obj2.OnSnapped, new Action(OnInteractionStarted));
			GameEntity obj3 = gameEntity;
			obj3.OnAttached = (Action)Delegate.Remove(obj3.OnAttached, new Action(OnInteractionStarted));
			GameEntity obj4 = gameEntity;
			obj4.OnReleased = (Action)Delegate.Remove(obj4.OnReleased, new Action(OnInteractionEnded));
			GameEntity obj5 = gameEntity;
			obj5.OnUnsnapped = (Action)Delegate.Remove(obj5.OnUnsnapped, new Action(OnInteractionEnded));
			GameEntity obj6 = gameEntity;
			obj6.OnDetached = (Action)Delegate.Remove(obj6.OnDetached, new Action(OnInteractionEnded));
			CancelTimer();
		}
	}

	public void OnEntityStateChange(long prevState, long newState)
	{
		RestartTimer();
	}

	private void OnDestroy()
	{
		CancelDelayedFx();
	}

	private void OnInteractionStarted()
	{
		CancelTimer();
	}

	private void OnInteractionEnded()
	{
		if (!IsCurrentlyInteracting())
		{
			StartTimer();
		}
	}

	public void StartTimer()
	{
		CancelDelayedFx();
		_callGenerationId++;
		int callGenerationId = _callGenerationId;
		Options options = m_options;
		GTDelayedExec.Add(this, options.delay, (callGenerationId << 2) | 1);
		GTDelayedExec.Add(this, options.delay + options.reappearDelay, (callGenerationId << 2) | 2);
		_timerRunning = true;
		if (options.disappearSound != null)
		{
			_delayedDisappearAudioIndex = GTAudioOneShot.PlayDelayed(options.disappearSound, base.transform.parent, base.transform.localPosition, options.delay, options.disappearVolume);
		}
		else
		{
			_delayedDisappearAudioIndex = -1;
		}
		if (options.pooledDisappearPrefab != null)
		{
			_delayedDisappearPoolIndex = ObjectPools.InstantiateDelayed(options.pooledDisappearPrefab, base.transform.parent, base.transform.localPosition, options.delay);
		}
		else
		{
			_delayedDisappearPoolIndex = -1;
		}
		if (options.beepSound == null || options.beepPhases == null || options.beepPhases.Length == 0)
		{
			return;
		}
		int contextId = (callGenerationId << 2) | 0;
		for (int i = 0; i < options.beepPhases.Length; i++)
		{
			float interval = options.beepPhases[i].interval;
			if (interval <= 0f)
			{
				continue;
			}
			float num = ((i + 1 < options.beepPhases.Length) ? options.beepPhases[i + 1].timeRemaining : 0f);
			float num2 = Mathf.Min(options.beepPhases[i].timeRemaining, options.delay);
			if (!(num2 <= num))
			{
				float num3 = options.delay - num2;
				float num4 = options.delay - num;
				for (float num5 = num3; num5 < num4; num5 += interval)
				{
					GTDelayedExec.Add(this, num5, contextId);
				}
			}
		}
	}

	public void RestartTimer()
	{
		if (!IsCurrentlyInteracting())
		{
			StartTimer();
		}
	}

	public void CancelTimer()
	{
		if (_timerRunning)
		{
			_callGenerationId++;
			_timerRunning = false;
			CancelDelayedFx();
			if (!gameEntity.gameObject.activeSelf)
			{
				gameEntity.gameObject.SetActive(value: true);
			}
		}
	}

	private void CancelDelayedFx()
	{
		if (_delayedDisappearAudioIndex >= 0)
		{
			GTAudioOneShot.CancelDelayed(_delayedDisappearAudioIndex);
			_delayedDisappearAudioIndex = -1;
		}
		if (_delayedDisappearPoolIndex >= 0)
		{
			ObjectPools.CancelDelayedInstantiate(_delayedDisappearPoolIndex);
			_delayedDisappearPoolIndex = -1;
		}
	}

	void IDelayedExecListener.OnDelayedAction(int contextId)
	{
		if (contextId >> 2 != _callGenerationId || gameEntity == null)
		{
			return;
		}
		int num = contextId & 3;
		Options options = m_options;
		switch (num)
		{
		case 0:
			if (_delayedDisappearAudioIndex >= 0)
			{
				GTAudioOneShot.UpdateDelayed(_delayedDisappearAudioIndex, base.transform.parent, base.transform.localPosition);
			}
			if (_delayedDisappearPoolIndex >= 0)
			{
				ObjectPools.UpdateDelayedInstantiate(_delayedDisappearPoolIndex, base.transform.parent, base.transform.localPosition);
			}
			if (options.beepSound != null)
			{
				GTAudioOneShot.Play(options.beepSound, base.transform.position, options.beepVolume);
			}
			break;
		case 1:
			Disappear();
			break;
		case 2:
			Reappear();
			break;
		}
	}

	private bool IsCurrentlyInteracting()
	{
		if (!gameEntity.IsHeld() && gameEntity.snappedByActorNumber == -1)
		{
			return gameEntity.attachedToEntityId != GameEntityId.Invalid;
		}
		return true;
	}

	private void Disappear()
	{
		gameEntity.gameObject.SetActive(value: false);
	}

	private void Reappear()
	{
		_timerRunning = false;
		if (resetTarget != null)
		{
			base.transform.SetPositionAndRotation(resetTarget.position, resetTarget.rotation);
			base.transform.localScale = resetTarget.localScale;
		}
		else
		{
			base.transform.SetPositionAndRotation(initialPosition, initialRotation);
			base.transform.localScale = initialScale;
		}
		Rigidbody componentInParent = GetComponentInParent<Rigidbody>();
		if (componentInParent != null)
		{
			componentInParent.linearVelocity = UnityEngine.Vector3.zero;
			componentInParent.angularVelocity = UnityEngine.Vector3.zero;
			componentInParent.isKinematic = forceKinematicOnReset || initialIsKinematic;
		}
		gameEntity.gameObject.SetActive(value: true);
		UnityEngine.Vector3 position = base.transform.position;
		Options options = m_options;
		if (options.reappearSound != null)
		{
			GTAudioOneShot.Play(options.reappearSound, position, options.reappearVolume);
		}
		if (options.pooledReappearPrefab != null)
		{
			ObjectPools.instance.Instantiate(options.pooledReappearPrefab, position);
		}
	}

	public void ReturnNow()
	{
		CancelTimer();
		Disappear();
		Reappear();
	}

	public void SetResetTarget(Transform target)
	{
		resetTarget = target;
	}

	internal void Configure(Options options)
	{
		m_options = options;
	}
}
