		ZoneGraphBSP instance = ZoneGraphBSP.Instance;
		if (instance != null && instance.HasCompiledTree())
		{
			ZoneDef zoneDef = instance.FindZoneAtPoint(pos);
			return zoneDef != null && zoneDef.zoneId == zone;
		}
		return true;
	}

