	private void OnNetworkLeftRoom()
	{
		for (int i = 0; i < entities.Count; i++)
		{
		}
		zoneClearReason = ZoneClearReason.Disconnect;
		if (zoneStateData.state != ZoneState.WaitingToEnterZone)
