public class GameGrabbable : MonoBehaviour
{
	[Serializable]
	public class SnapGrabPoints
	{
		public bool isLeftHand;

		public Transform handTransform;
	}

	public GameEntity gameEntity;

	public List<SnapGrabPoints> snapGrabPoints;

	private static readonly UnityEngine.Vector3 GRAB_UP = new UnityEngine.Vector3(0f, 0f, 1f);

	private static readonly UnityEngine.Vector3 GRAB_PALM = new UnityEngine.Vector3(1f, 0f, 0f);

	private void Awake()
	{
	}

	public bool GetBestGrabPoint(UnityEngine.Vector3 handPos, UnityEngine.Quaternion handRot, int handIndex, out GameGrab grab)
	{
		float num = 0.15f;
		bool flag = false;
		grab = default(GameGrab);
		grab.position = base.transform.position;
		grab.rotation = base.transform.rotation;
		bool flag2 = GamePlayer.IsLeftHand(handIndex);
		if (this.snapGrabPoints != null)
		{
			for (int i = 0; i < this.snapGrabPoints.Count; i++)
			{
				SnapGrabPoints snapGrabPoints = this.snapGrabPoints[i];
				if (snapGrabPoints.isLeftHand == flag2 && !(UnityEngine.Vector3.Dot(snapGrabPoints.handTransform.rotation * GRAB_UP, handRot * GRAB_UP) < 0f) && !(UnityEngine.Vector3.Dot(snapGrabPoints.handTransform.rotation * GRAB_PALM, handRot * GRAB_PALM) < 0f) && !((double)(handPos - snapGrabPoints.handTransform.position).sqrMagnitude > 0.0225))
				{
					grab.position = handPos + handRot * UnityEngine.Quaternion.Inverse(snapGrabPoints.handTransform.localRotation) * -snapGrabPoints.handTransform.localPosition;
					grab.rotation = handRot * UnityEngine.Quaternion.Inverse(snapGrabPoints.handTransform.localRotation);
					flag = true;
				}
			}
		}
		if (!flag)
		{
			return false;
		}
		UnityEngine.Vector3 vector = grab.position - handPos;
		if (vector.sqrMagnitude > num * num)
		{
			grab.position = handPos + vector.normalized * num;
		}
		return true;
	}
}
