	public void OnEntityInit()
	{
		GRTool component = GetComponent<GRTool>();
		if (component != null)
		{
			component.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(component);
		}
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	private void OnToolUpgraded(GRTool tool)
	{
		if (attributes.HasValueForAttribute(GRAttributeType.KnockbackMultiplier))
		{
			knockbackMultiplier = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.KnockbackMultiplier);
		}
	}

	public void ApplyHit(GameHitData hitData)
	{
		if (hitFx.hitSound != null)
		{
			hitFx.hitSound.Play(null);
		}
		if (hitFx.hitEffect != null)
		{
			hitFx.hitEffect.Stop();
			hitFx.hitEffect.Play();
		}
		for (int i = 0; i < components.Count; i++)
		{
			components[i].OnSuccessfulHit(hitData);
		}
		if (gameEntity.IsHeldByLocalPlayer())
		{
			PlayVibration(GorillaTagger.Instance.tapHapticStrength, 0.2f);
			GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
			if (gamePlayer != null)
			{
				int num = gamePlayer.FindHandIndex(gameEntity.id);
				if (num != -1)
				{
					GTPlayer.Instance.TempFreezeHand(GamePlayer.IsLeftHand(num), 0.15f);
				}
			}
		}
		if (GRNoiseEventManager.instance != null)
		{
			GRNoiseEventManager.instance.AddNoiseEvent(hitData.hitPosition);
		}
	}

	public void ApplyHitToPlayer(GRPlayer player, UnityEngine.Vector3 hitPosition)
	{
		hitFx.hitSound.Play(null);
		if (hitFx.hitEffect != null)
		{
			hitFx.hitEffect.Play();
		}
		for (int i = 0; i < components.Count; i++)
		{
			components[i].OnSuccessfulHitPlayer(player, hitPosition);
		}
	}

	private void PlayVibration(float strength, float duration)
	{
		if (!gameEntity.IsHeldByLocalPlayer())
		{
			return;
		}
		GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
		if (!(gamePlayer == null))
		{
			int num = gamePlayer.FindHandIndex(gameEntity.id);
			if (num != -1)
			{
				GorillaTagger.Instance.StartVibration(GamePlayer.IsLeftHand(num), strength, duration);
			}
		}
	}

	private T GetParentEnemy<T>(Collider collider) where T : MonoBehaviour
	{
		Transform parent = collider.transform;
		while (parent != null)
		{
			T component = parent.GetComponent<T>();
			if (component != null)
			{
				return component;
			}
			parent = parent.parent;
		}
		return null;
	}

	public int CalcHitAmount(GameHitType hitType, GameHittable hittable, GameEntity hitByEntity)
	{
		int result = 0;
		if (hitByEntity != null)
		{
			GRAttributes component = hitByEntity.GetComponent<GRAttributes>();
			if (component != null)
			{
				switch (hitType)
				{
				case GameHitType.Club:
					result = component.CalculateFinalValueForAttribute(damageAttribute);
					break;
				case GameHitType.Flash:
					result = component.CalculateFinalValueForAttribute(flashDamageAttribute);
					break;
				case GameHitType.Shield:
					result = component.CalculateFinalValueForAttribute(shieldDamageAttribute);
					break;
				}
			}
		}
		return result;
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (!hitOnCollision)
		{
			return;
		}
		float num = gameEntity.GetVelocity().sqrMagnitude;
		if (gameEntity.lastHeldByActorNumber != PhotonNetwork.LocalPlayer.ActorNumber)
		{
			return;
		}
		bool flag = false;
		GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
		if (gamePlayer != null)
		{
			float handSpeed = GamePlayerLocal.instance.GetHandSpeed(gamePlayer.FindHandIndex(gameEntity.id));
			num = handSpeed * handSpeed;
		}
		if (num < minSwingSpeed * minSwingSpeed)
		{
			return;
		}
		double timeAsDouble = Time.timeAsDouble;
		if (timeAsDouble < hitCooldownEnd)
		{
			return;
		}
		Collider collider = collision.collider;
		GameHittable parentEnemy = GetParentEnemy<GameHittable>(collider);
		if (parentEnemy != null && parentEnemy.IsColliderValid(collision.collider))
		{
			UnityEngine.Vector3 vector = parentEnemy.transform.position - base.transform.position;
			vector.Normalize();
			if (!flag && gamePlayer != null)
			{
				vector = GamePlayerLocal.instance.GetHandVelocity(gamePlayer.FindHandIndex(gameEntity.id)).normalized;
			}
			float a = Mathf.Sqrt(num);
			a = Mathf.Min(a, maxImpulseSpeed);
			vector *= a;
			UnityEngine.Vector3 position = parentEnemy.transform.position;
			GameHitData hitData = new GameHitData
			{
				hitTypeId = (int)hitType,
				hitEntityId = parentEnemy.gameEntity.id,
				hitByEntityId = gameEntity.id,
				hitEntityPosition = position,
				hitImpulse = vector * knockbackMultiplier,
				hitPosition = collision.GetContact(0).point,
				hitAmount = CalcHitAmount(hitType, parentEnemy, gameEntity),
				hittablePoint = parentEnemy.FindHittablePoint(collider)
			};
			if (parentEnemy.IsHitValid(hitData))
			{
				parentEnemy.RequestHit(hitData);
				hitCooldownEnd = timeAsDouble + 0.25;
			}
		}
	}
}
public class GameLight : MonoBehaviour
{
	public Light light;

	public bool negativeLight;

	public bool isHighPriorityPlayerLight;

	public UnityEngine.Vector3 cachedPosition;

	public UnityEngine.Vector4 cachedColorAndIntensity;

	public int lightId = -1;

	public int intensityMult = 1;

	private bool initialized;

	public bool IsRegistered => lightId != -1;

	public float InitialIntensity { get; private set; }

	public void Awake()
	{
		intensityMult = 1;
		lightId = -1;
	}

	protected void OnEnable()
	{
		if (initialized)
		{
			lightId = GameLightingManager.instance.AddGameLight(this);
		}
	}

	protected void Start()
	{
		lightId = GameLightingManager.instance.AddGameLight(this);
		initialized = true;
	}

	protected void OnDisable()
	{
		if (initialized)
		{
			GameLightingManager.instance.RemoveGameLight(this);
		}
	}

	public void UpdateCachedLightColorAndIntensity()
	{
		cachedColorAndIntensity = (float)intensityMult * light.intensity * (negativeLight ? (-1f) : 1f) * light.color;
	}
}
public class GameLightingManager : MonoBehaviourTick, IGorillaSliceableSimple
{
	private struct LightInput
	{
		public Color color;

		public float intensity;

		public float intensityMult;
	}

	private struct LightDataPacked
	{
		public uint posXY;

		public uint posZW;

		public uint colorRG;

		public uint colorBA;
	}

	private struct LightDataLegacy
	{
		public float4 position;

		public float4 color;

		public float4 direction;
	}

	[OnEnterPlay_SetNull]
	public static volatile GameLightingManager instance;

	public const int MAX_VERTEX_LIGHTS = 50;

	public const int USE_MAX_VERTEX_LIGHTS = 20;

	public const int MAX_UPDATE_LIGHTS_PER_FRAME = 10;

	public Transform testLightsCenter;

	[ColorUsage(true, true)]
	public Color testAmbience = Color.black;

	[ColorUsage(true, true)]
	public Color testLightColor = Color.white;

	public float testLightBrightness = 10f;

	public float testLightRadius = 2f;

	public int maxUseTestLights = 1;

	[Unity.Collections.ReadOnly]
	[SerializeField]
	private List<GameLight> gameLights;

	private bool customVertexLightingEnabled;

	private bool desaturateAndTintEnabled;

	private Transform mainCameraTransform;

	private int zoneDynamicLightingEnableCount;

	private float[] sortKeys;

	private GameLight[] sortValues;

	private NativeArray<LightDataPacked> lightData;

	private NativeArray<LightDataLegacy> lightDataLegacy;

	private GraphicsBuffer lightDataBuffer;

	private GraphicsBuffer lightDataBufferLegacy;

	private bool skipNextSlice;

	private bool immediateSort;

	private int nextLightUpdate;

	private int nextLightCacheUpdate;

	[SerializeField]
	private Light _GR_NearsightedDimLight;

	private static readonly int _shaderPropId_GameLight_UseMaxLights = Shader.PropertyToID("_GT_GameLight_UseMaxLights");

	private static readonly int _shaderPropId_DesaturateAndTint_TintColor = Shader.PropertyToID("_GT_DesaturateAndTint_TintColor");

	private static readonly int _shaderPropId_DesaturateAndTint_TintAmount = Shader.PropertyToID("_GT_DesaturateAndTint_TintAmount");

	private static readonly int _shaderPropId_GameLight_Ambient_Color = Shader.PropertyToID("_GT_GameLight_Ambient_Color");

	private static readonly int _shaderPropId_GameLight_Lights = Shader.PropertyToID("_GT_GameLight_Lights");

	private static readonly int _shaderPropId_GameLight_LightsPacked = Shader.PropertyToID("_GT_GameLight_LightsPacked");

	public bool IsDynamicLightingEnabled => customVertexLightingEnabled;

	public Light GR_NearsightedDimLight => _GR_NearsightedDimLight;

	private static uint PackHalf2(float a, float b)
	{
		return (uint)(Mathf.FloatToHalf(a) | (Mathf.FloatToHalf(b) << 16));
	}

	private void Awake()
	{
		InitData();
	}

	private void InitData()
	{
		instance = this;
		gameLights = new List<GameLight>(512);
		sortKeys = new float[512];
		sortValues = new GameLight[512];
		lightDataBuffer = new GraphicsBuffer(GraphicsBuffer.Target.Structured, 50, UnsafeUtility.SizeOf<LightDataPacked>());
		lightData = new NativeArray<LightDataPacked>(50, Unity.Collections.Allocator.Persistent);
		lightDataBufferLegacy = new GraphicsBuffer(GraphicsBuffer.Target.Structured, 50, UnsafeUtility.SizeOf<LightDataLegacy>());
		lightDataLegacy = new NativeArray<LightDataLegacy>(50, Unity.Collections.Allocator.Persistent);
		nextLightUpdate = 0;
		ClearGameLights();
		SetDesaturateAndTintEnabled(enable: false, Color.black);
		SetAmbientLightDynamic(Color.black);
		SetCustomDynamicLightingEnabled(enable: false);
		SetMaxLights(20);
	}

	private void OnDestroy()
	{
		ClearGameLights();
		SetDesaturateAndTintEnabled(enable: false, Color.black);
		SetAmbientLightDynamic(Color.black);
		SetCustomDynamicLightingEnabled(enable: false);
		lightDataBuffer?.Dispose();
		if (lightData.IsCreated)
		{
			lightData.Dispose();
		}
		lightDataBufferLegacy?.Dispose();
		if (lightDataLegacy.IsCreated)
		{
			lightDataLegacy.Dispose();
		}
	}

	public new void OnEnable()
	{
		base.OnEnable();
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public new void OnDisable()
	{
		base.OnDisable();
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void ZoneEnableCustomDynamicLighting(bool enable)
	{
		if (enable)
		{
			if (zoneDynamicLightingEnableCount == 0)
			{
				SetCustomDynamicLightingEnabled(enable: true);
			}
			zoneDynamicLightingEnableCount++;
			return;
		}
		zoneDynamicLightingEnableCount--;
		if (zoneDynamicLightingEnableCount == 0)
		{
			SetCustomDynamicLightingEnabled(enable: false);
		}
		if (zoneDynamicLightingEnableCount < 0)
		{
			UnityEngine.Debug.LogErrorFormat("Zone Dynamic Lighting Ref count is {0} and should never be less that 0", zoneDynamicLightingEnableCount);
			zoneDynamicLightingEnableCount = 0;
		}
	}

	public void SetCustomDynamicLightingEnabled(bool enable)
	{
		customVertexLightingEnabled = enable;
		if (customVertexLightingEnabled)
		{
			Shader.EnableKeyword("_ZONE_DYNAMIC_LIGHTS__CUSTOMVERTEX");
		}
		else
		{
			Shader.DisableKeyword("_ZONE_DYNAMIC_LIGHTS__CUSTOMVERTEX");
		}
	}

	public void ToggleCustomDynamicLightingEnabled()
	{
		SetCustomDynamicLightingEnabled(!customVertexLightingEnabled);
	}

	public void SetAmbientLightDynamic(Color color)
	{
		Shader.SetGlobalColor(_shaderPropId_GameLight_Ambient_Color, color);
	}

	public void SetMaxLights(int maxLights)
	{
		maxLights = Mathf.Min(maxLights, 50);
		maxUseTestLights = maxLights;
		Shader.SetGlobalInteger(_shaderPropId_GameLight_UseMaxLights, maxLights);
	}

	public void SetDesaturateAndTintEnabled(bool enable, Color tint)
	{
		Shader.SetGlobalColor(_shaderPropId_DesaturateAndTint_TintColor, tint);
		Shader.SetGlobalFloat(_shaderPropId_DesaturateAndTint_TintAmount, enable ? 1f : 0f);
		desaturateAndTintEnabled = enable;
	}

	public void SliceUpdate()
	{
		if (skipNextSlice)
		{
			skipNextSlice = false;
			return;
		}
		immediateSort = false;
		SortLights();
	}

	public void SortLights()
	{
		int count = gameLights.Count;
		if (count <= maxUseTestLights)
		{
			return;
		}
		if (mainCameraTransform == null)
		{
			mainCameraTransform = Camera.main.transform;
		}
		UnityEngine.Vector3 position = mainCameraTransform.position;
		if (sortKeys == null || sortKeys.Length < count)
		{
			int num = Mathf.Max(count, (sortKeys != null) ? (sortKeys.Length * 2) : 64);
			sortKeys = new float[num];
			sortValues = new GameLight[num];
		}
		for (int i = 0; i < count; i++)
		{
			GameLight gameLight = gameLights[i];
			if (gameLight == null || gameLight.light == null)
			{
				sortKeys[i] = float.MaxValue;
			}
			else
			{
				float num2 = Mathf.Clamp(gameLight.cachedColorAndIntensity.x + gameLight.cachedColorAndIntensity.y + gameLight.cachedColorAndIntensity.z, 0.01f, 6f);
				UnityEngine.Vector3 vector = position - gameLight.cachedPosition;
				sortKeys[i] = (vector.x * vector.x + vector.y * vector.y + vector.z * vector.z) / num2;
			}
			sortValues[i] = gameLight;
		}
		Array.Sort(sortKeys, sortValues, 0, count);
		for (int j = 0; j < count; j++)
		{
			gameLights[j] = sortValues[j];
		}
	}

	public override void Tick()
	{
		RefreshLightData();
	}

	private void RefreshLightData()
	{
		if (lightDataBuffer == null || !customVertexLightingEnabled)
		{
			return;
		}
		int numLightsToPull = 10;
		if (immediateSort)
		{
			immediateSort = false;
			skipNextSlice = true;
			CacheAllLightData();
			SortLights();
			numLightsToPull = maxUseTestLights;
		}
		else
		{
			int numLightsToUpdateCache = 5;
			CacheLightDataForNonCloseLights(numLightsToUpdateCache);
		}
		PullLightData(numLightsToPull);
		int num = Mathf.Min(gameLights.Count, maxUseTestLights);
		if (num > 0)
		{
			bool num2 = CustomMapLoader.IsMapLoaded();
			lightDataBuffer.SetData(lightData, 0, 0, num);
			if (num2)
			{
				lightDataBufferLegacy.SetData(lightDataLegacy);
			}
			Shader.SetGlobalBuffer(_shaderPropId_GameLight_LightsPacked, lightDataBuffer);
			if (num2)
			{
				Shader.SetGlobalBuffer(_shaderPropId_GameLight_Lights, lightDataBufferLegacy);
			}
			Shader.SetGlobalInteger(_shaderPropId_GameLight_UseMaxLights, num);
		}
	}

	public void CacheAllLightData()
	{
		for (int i = 0; i < gameLights.Count; i++)
		{
			GameLight gameLight = gameLights[i];
			if (gameLight != null && gameLight.light != null)
			{
				gameLight.cachedPosition = gameLight.transform.position;
				gameLight.cachedColorAndIntensity = (float)gameLight.intensityMult * gameLight.light.intensity * (gameLight.negativeLight ? (-1f) : 1f) * gameLight.light.color;
			}
		}
	}

	public void CacheLightDataForNonCloseLights(int numLightsToUpdateCache)
	{
		int num = gameLights.Count - maxUseTestLights;
		if (num <= 0)
		{
			return;
		}
		for (int i = 0; i < numLightsToUpdateCache; i++)
		{
			nextLightCacheUpdate = (nextLightCacheUpdate + 1) % num;
			GameLight gameLight = gameLights[maxUseTestLights + nextLightCacheUpdate];
			if (gameLight != null && gameLight.light != null)
			{
				gameLight.cachedPosition = gameLight.transform.position;
				gameLight.cachedColorAndIntensity = (float)gameLight.intensityMult * gameLight.light.intensity * (gameLight.negativeLight ? (-1f) : 1f) * gameLight.light.color;
			}
		}
	}

	public void PullLightData(int numLightsToPull)
	{
		for (int i = 0; i < maxUseTestLights; i++)
		{
			if (i < gameLights.Count && gameLights[i] != null && gameLights[i].isHighPriorityPlayerLight)
			{
				GetFromLight(i, i);
			}
		}
		for (int j = 0; j < numLightsToPull; j++)
		{
			nextLightUpdate = (nextLightUpdate + 1) % maxUseTestLights;
			if (nextLightUpdate < gameLights.Count)
			{
				GetFromLight(nextLightUpdate, nextLightUpdate);
				if (gameLights[nextLightUpdate] != null && !gameLights[nextLightUpdate].isHighPriorityPlayerLight)
				{
				}
			}
			else
			{
				ResetLight(nextLightUpdate);
			}
		}
	}

	public int AddGameLight(GameLight light, bool ignoreUnityLightDisable = false)
	{
		if (light == null || !light.gameObject.activeInHierarchy || light.light == null || !light.light.enabled)
		{
			return -1;
		}
		if (light.IsRegistered)
		{
			return -1;
		}
		if (!ignoreUnityLightDisable)
		{
			light.light.enabled = false;
		}
		gameLights.Add(light);
		immediateSort = true;
		return gameLights.Count - 1;
	}

	public void RemoveGameLight(GameLight light)
	{
		if (light != null && light.light != null)
		{
			light.light.enabled = true;
		}
		if (light != null)
		{
			light.lightId = -1;
		}
		int num = gameLights.IndexOf(light);
		if (num < 0)
		{
			return;
		}
		gameLights.RemoveAt(num);
		if (CustomMapLoader.IsMapLoaded())
		{
			int count = gameLights.Count;
			if (count < 50)
			{
				lightDataLegacy[count] = default(LightDataLegacy);
			}
		}
	}

	public void ClearGameLights()
	{
		if (gameLights != null)
		{
			gameLights.Clear();
		}
		if (lightDataBuffer != null)
		{
			for (int i = 0; i < 50; i++)
			{
				ResetLight(i);
			}
			lightDataBuffer.SetData(lightData);
			Shader.SetGlobalBuffer(_shaderPropId_GameLight_LightsPacked, lightDataBuffer);
			if (CustomMapLoader.IsMapLoaded())
			{
				lightDataBufferLegacy.SetData(lightDataLegacy);
				Shader.SetGlobalBuffer(_shaderPropId_GameLight_Lights, lightDataBufferLegacy);
			}
		}
	}

	public void GetFromLight(int lightIndex, int gameLightIndex)
	{
		if (lightDataBuffer != null)
		{
			GameLight gameLight = null;
			if (gameLightIndex >= 0 && gameLightIndex < gameLights.Count)
			{
				gameLight = gameLights[gameLightIndex];
			}
			if (!(gameLight == null) && !(gameLight.light == null))
			{
				gameLight.cachedPosition = gameLight.transform.position;
				gameLight.cachedColorAndIntensity = (float)gameLight.intensityMult * gameLight.light.intensity * (gameLight.negativeLight ? (-1f) : 1f) * gameLight.light.color;
				UnityEngine.Vector3 cachedPosition = gameLight.cachedPosition;
				UnityEngine.Vector4 cachedColorAndIntensity = gameLight.cachedColorAndIntensity;
				lightData[lightIndex] = new LightDataPacked
				{
					posXY = PackHalf2(cachedPosition.x, cachedPosition.y),
					posZW = PackHalf2(cachedPosition.z, 1f),
					colorRG = PackHalf2(cachedColorAndIntensity.x, cachedColorAndIntensity.y),
					colorBA = PackHalf2(cachedColorAndIntensity.z, cachedColorAndIntensity.w)
				};
				lightDataLegacy[lightIndex] = new LightDataLegacy
				{
					position = new float4(cachedPosition.x, cachedPosition.y, cachedPosition.z, 1f),
					color = new float4(cachedColorAndIntensity.x, cachedColorAndIntensity.y, cachedColorAndIntensity.z, cachedColorAndIntensity.w),
					direction = float4.zero
				};
			}
		}
	}

	private void ResetLight(int lightIndex)
	{
		lightData[lightIndex] = default(LightDataPacked);
		lightDataLegacy[lightIndex] = default(LightDataLegacy);
	}
}
public class GameLightOverride : MonoBehaviour
{
	public void MaxGameLightOverride(int newMaxLights)
	{
		GameLightingManager.instance.SetMaxLights(newMaxLights);
	}

	private void OnDisable()
	{
		GameLightingManager.instance.SetMaxLights(20);
	}
}
public class GameLightPulse : GameLight, IGorillaSliceableSimple
{
	private float startingIntensity;

	public float frequency;

	private float offsetTime;

	public new void Awake()
	{
		base.Awake();
		startingIntensity = light.intensity;
		offsetTime = UnityEngine.Random.value / frequency;
	}

	protected new void OnEnable()
	{
		base.OnEnable();
		GorillaSlicerSimpleManager.RegisterSliceable(this);
	}

	protected new void OnDisable()
	{
		base.OnDisable();
		GorillaSlicerSimpleManager.UnregisterSliceable(this);
	}

	public void SliceUpdate()
	{
		light.intensity = startingIntensity / 2f * Mathf.Sin((Time.time + offsetTime) * frequency * 2f * MathF.PI % (MathF.PI * 2f)) + startingIntensity / 2f;
	}
}
public class GameMirrorWhenEquipped : MonoBehaviour
{
	[SerializeField]
	private GameEntity m_gameEntity;

	[SerializeField]
	private Transform[] m_xformsToMirror;

	[SerializeField]
	private bool m_shouldOnlyMirrorWhenSnapped = true;

	[Tooltip("Set the X axis scale to -1 if the gadget is attached (held or snapped) to the selected side.")]
	[SerializeField]
	private EHandedness m_handednessToMirror = EHandedness.Right;

	private void Awake()
	{
		if (m_gameEntity == null)
		{
			m_gameEntity = GetComponent<GameEntity>();
		}
		if (m_xformsToMirror == null)
		{
			m_xformsToMirror = Array.Empty<Transform>();
		}
	}

	protected void OnEnable()
	{
		GameEntity gameEntity = m_gameEntity;
		gameEntity.OnGrabbed = (Action)Delegate.Combine(gameEntity.OnGrabbed, new Action(_HandleGameEntityOnEquipChanged));
		GameEntity gameEntity2 = m_gameEntity;
		gameEntity2.OnSnapped = (Action)Delegate.Combine(gameEntity2.OnSnapped, new Action(_HandleGameEntityOnEquipChanged));
		GameEntity gameEntity3 = m_gameEntity;
		gameEntity3.OnReleased = (Action)Delegate.Combine(gameEntity3.OnReleased, new Action(_HandleGameEntityOnEquipChanged));
		GameEntity gameEntity4 = m_gameEntity;
		gameEntity4.OnUnsnapped = (Action)Delegate.Combine(gameEntity4.OnUnsnapped, new Action(_HandleGameEntityOnEquipChanged));
	}

	protected void OnDisable()
	{
		GameEntity gameEntity = m_gameEntity;
		gameEntity.OnGrabbed = (Action)Delegate.Remove(gameEntity.OnGrabbed, new Action(_HandleGameEntityOnEquipChanged));
		GameEntity gameEntity2 = m_gameEntity;
		gameEntity2.OnSnapped = (Action)Delegate.Remove(gameEntity2.OnSnapped, new Action(_HandleGameEntityOnEquipChanged));
		GameEntity gameEntity3 = m_gameEntity;
		gameEntity3.OnReleased = (Action)Delegate.Remove(gameEntity3.OnReleased, new Action(_HandleGameEntityOnEquipChanged));
		GameEntity gameEntity4 = m_gameEntity;
		gameEntity4.OnUnsnapped = (Action)Delegate.Remove(gameEntity4.OnUnsnapped, new Action(_HandleGameEntityOnEquipChanged));
	}

	private void _HandleGameEntityOnEquipChanged()
	{
		if (!m_shouldOnlyMirrorWhenSnapped || m_gameEntity.snappedJoint != SnapJointType.None)
		{
			UnityEngine.Vector3 localScale = ((m_gameEntity.EquippedHandedness == m_handednessToMirror) ? new UnityEngine.Vector3(-1f, 1f, 1f) : UnityEngine.Vector3.one);
			for (int i = 0; i < m_xformsToMirror.Length; i++)
			{
				m_xformsToMirror[i].localScale = localScale;
			}
		}
	}
}
public class GamePlayer : MonoBehaviour
{
	public struct SlotData
