			if (Time.frameCount != _lastSubscriptionCheck)
			{
				_isSubscribed = SubscriptionManager.IsPlayerSubscribed(rig);
				_lastSubscriptionCheck = Time.frameCount;
			}
			return _isSubscribed;
		}
