	public IEnumerable<GameEntityId> IterateHeldAndSnappedItems(GameEntityManager manager)
	{
		int i = 0;
		while (i < 4)
		{
			if (slots[i].entityId != GameEntityId.Invalid && slots[i].entityManager == manager)
			{
				yield return slots[i].entityId;
			}
			int num = i + 1;
			i = num;
		}
