	public static GamePlayer GetGamePlayer(Collider collider, bool bodyOnly = false)
	{
		Transform parent = collider.transform;
		while (parent != null)
		{
			GamePlayer component = parent.GetComponent<GamePlayer>();
			if (component != null)
			{
				return component;
			}
			if (bodyOnly)
			{
				break;
			}
			parent = parent.parent;
		}
		return null;
	}

