	public void DebugSlotsReport(string header)
	{
		try
		{
			string text = $"[SlotsReport] {header} | currManager={currGameEntityManager?.zone} localActor={PhotonNetwork.LocalPlayer?.ActorNumber ?? (-1)} | slots: ";
			for (int i = 0; i < 4; i++)
