[RequireComponent(typeof(GameEntity))]
public class GameTriggerInteractable : MonoBehaviour
{
	public GameEntity gameEntity;

	public Transform interactableCenter;

	public float interactableRadius;

	public bool interactableWhileGrabbed;

	public bool interactableWhileSnapped;

	public bool interactablePermanently;

	public bool interactableOnOthers;

	public bool triggerInteractionActive;

	public int handIndex = -1;

	public static List<GameTriggerInteractable> LocalInteractableTriggers = new List<GameTriggerInteractable>();

	private void OnEnable()
	{
		if (gameEntity == null)
		{
			gameEntity = GetComponent<GameEntity>();
		}
		if (interactableWhileGrabbed)
		{
			GameEntity obj = gameEntity;
			obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(StartHolding));
			GameEntity obj2 = gameEntity;
			obj2.OnReleased = (Action)Delegate.Combine(obj2.OnReleased, new Action(StopHolding));
		}
		if (interactableWhileSnapped)
		{
			GameEntity obj3 = gameEntity;
			obj3.OnSnapped = (Action)Delegate.Combine(obj3.OnSnapped, new Action(StartHolding));
			GameEntity obj4 = gameEntity;
			obj4.OnUnsnapped = (Action)Delegate.Combine(obj4.OnUnsnapped, new Action(StopHolding));
		}
	}

	public void StartHolding()
	{
		LocalInteractableTriggers.AddIfNew(this);
	}

	public void StopHolding()
	{
		LocalInteractableTriggers.RemoveIfContains(this);
	}

	public bool PointWithinInteractableArea(UnityEngine.Vector3 point)
	{
		return (interactableCenter.position - point).magnitude < interactableRadius;
	}

	public void BeginTriggerInteraction(int _handIndex)
	{
		triggerInteractionActive = true;
		handIndex = _handIndex;
	}

	public void EndTriggerInteraction()
	{
		triggerInteractionActive = false;
		handIndex = -1;
	}
}
public class SuperInfectionSnapPoint : MonoBehaviour
{
	private const string preLog = "[SuperInfectionSnapPoint]  ";

	private const string preErr = "[SuperInfectionSnapPoint]  ERROR!!!  ";

	public GamePlayer playerForPoint;

	public SnapJointType jointType;

	public GTHardCodedBones.SturdyEBone parentBone;

	public Transform overrideParentTransform;

	private Transform parentTransform;

	public bool canSnapOverride;

	public float snapPointRadius;

	private GameEntity snappedEntity;

	public void Initialize()
	{
		VRRig componentInParent = GetComponentInParent<VRRig>(includeInactive: true);
		if (componentInParent == null)
		{
			throw new NullReferenceException("[SuperInfectionSnapPoint]  ERROR!!!  Expected a VRRig to be in parent hierarchy. Path=\"" + base.transform.GetPathQ() + "\"");
		}
		if (!GTHardCodedBones.TryGetBoneXforms(componentInParent, out var outBoneXforms, out var outErrorMsg))
		{
			throw new NullReferenceException("[SuperInfectionSnapPoint]  ERROR!!!  Could not get bone transforms: " + outErrorMsg);
		}
		if (overrideParentTransform != null)
		{
			parentTransform = overrideParentTransform;
		}
		else if (!GTHardCodedBones.TryGetBoneXform(outBoneXforms, parentBone.Bone, out parentTransform))
		{
			throw new NullReferenceException("[SuperInfectionSnapPoint]  ERROR!!!  " + $"Could not find bone Transform `{parentBone}`.");
		}
		UnityEngine.Vector3 localPosition = base.transform.localPosition;
		UnityEngine.Vector3 localEulerAngles = base.transform.localEulerAngles;
		if (parentTransform != null)
		{
			base.transform.SetParent(parentTransform, worldPositionStays: false);
		}
		base.transform.localPosition = localPosition;
		base.transform.localEulerAngles = localEulerAngles;
	}

	public void Clear()
	{
		Unsnapped();
	}

	public void Snapped(GameEntity entity)
	{
		snappedEntity = entity;
		if (snappedEntity.TryGetComponent<GameSnappable>(out var component))
		{
			component.snappedToJoint = this;
		}
		else
		{
			UnityEngine.Debug.LogError($"Snapped: entity {snappedEntity} has no GameSnappable!?");
		}
	}

	public void Unsnapped()
	{
		if ((bool)snappedEntity && snappedEntity.TryGetComponent<GameSnappable>(out var component))
		{
			component.snappedToJoint = null;
		}
		else
		{
			UnityEngine.Debug.LogError($"Unsnapped: entity {snappedEntity} has no GameSnappable!?");
		}
		snappedEntity = null;
	}

	public bool HasSnapped()
	{
		return snappedEntity != null;
	}

	public GameEntity GetSnappedEntity()
	{
		return snappedEntity;
	}
}
public class SuperInfectionSnapPointManager : MonoBehaviour
{
	public List<SuperInfectionSnapPoint> SnapPoints;

	private Dictionary<SnapJointType, SuperInfectionSnapPoint> snapPointDict = new Dictionary<SnapJointType, SuperInfectionSnapPoint>();

	public void Awake()
	{
		VRRig componentInParent = GetComponentInParent<VRRig>(includeInactive: true);
		ISpawnable[] componentsInChildren = GetComponentsInChildren<ISpawnable>(includeInactive: true);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].OnSpawn(componentInParent);
		}
	}

	public void Start()
	{
		foreach (SuperInfectionSnapPoint snapPoint in SnapPoints)
		{
			snapPoint.Initialize();
			snapPointDict[snapPoint.jointType] = snapPoint;
		}
	}

	public void Clear()
	{
		foreach (SuperInfectionSnapPoint snapPoint in SnapPoints)
		{
			snapPoint.Clear();
		}
		snapPointDict.Clear();
	}

	public SuperInfectionSnapPoint FindSnapPoint(SnapJointType jointType)
	{
		if (jointType == SnapJointType.None)
		{
			return null;
		}
		if (snapPointDict.ContainsKey(jointType))
		{
			return snapPointDict[jointType];
		}
		return null;
	}

	public static SuperInfectionSnapPoint FindSnapPoint(GamePlayer player, SnapJointType jointType)
	{
		if (player == null)
		{
			return null;
		}
		return player.snapPointManager.FindSnapPoint(jointType);
	}

	public void DropAllSnappedAuthority()
	{
		for (int i = 0; i < SnapPoints.Count; i++)
		{
			GameEntity snappedEntity = SnapPoints[i].GetSnappedEntity();
			if (!(snappedEntity == null))
			{
				UnityEngine.Vector3 position = snappedEntity.transform.position;
				snappedEntity.manager.RequestGrabEntity(snappedEntity.id, isLeftHand: false, UnityEngine.Vector3.zero, UnityEngine.Quaternion.identity);
				snappedEntity.manager.RequestThrowEntity(snappedEntity.id, isLeftHand: false, position, UnityEngine.Vector3.zero, UnityEngine.Vector3.zero);
			}
		}
	}
}
public class GhostReactor : MonoBehaviourTick, IBuildValidation
{
	[Serializable]
	public class TempEnemySpawnInfo
	{
		public GameEntity prefab;

		public Transform spawnMarker;

		public int patrolPath;
	}

	public class EntityTypeRespawnTracker
	{
		public int entityTypeID;

		public long entityCreateData;

		public float entityNextRespawnTime;
	}

	public enum EntityGroupTypes
	{
		EnemyChaser,
		EnemyChaserArmored,
		EnemyRanged,
		EnemyRangedArmored,
		CollectibleFlower,
		BarrierEnergyCostGate,
		BarrierSpectralWall,
		HazardSpectralLiquid
	}

	public enum EnemyType
	{
		Chaser,
		Ranged,
		Phantom,
		Environment,
		CustomMapsEnemy
	}

	public struct EnemyEntityCreateData
	{
		public int respawnCount;

		public int sectionIndex;

		public int patrolIndex;

		private static long PackData(int value, int nbits, int shift)
		{
			return (long)(((ulong)value & (ulong)((1 << nbits) - 1)) << shift);
		}

		private static int UnpackData(long createData, int nbits, int shift)
		{
			return (int)((createData >> shift) & ((1 << nbits) - 1));
		}

		public static EnemyEntityCreateData Unpack(long bits)
		{
			return new EnemyEntityCreateData
			{
				respawnCount = UnpackData(bits, 8, 16),
				sectionIndex = UnpackData(bits, 8, 8),
				patrolIndex = UnpackData(bits, 8, 0)
			};
		}

		public long Pack()
		{
			return PackData(respawnCount, 8, 16) | PackData(sectionIndex, 8, 8) | PackData(patrolIndex, 8, 0);
		}
	}

	public struct ToolEntityCreateData
	{
		public int stationIndex;

		public float decayTime;

		private static long PackData(int value, int nbits, int shift)
		{
			return (long)(((ulong)value & (ulong)((1 << nbits) - 1)) << shift);
		}

		private static int UnpackData(long createData, int nbits, int shift)
		{
			return (int)((createData >> shift) & ((1 << nbits) - 1));
		}

		public static ToolEntityCreateData Unpack(long bits)
		{
			ToolEntityCreateData result = new ToolEntityCreateData
			{
				stationIndex = UnpackData(bits, 8, 0) - 1
			};
			int num = UnpackData(bits, 8, 8);
			result.decayTime = 5f * (float)num;
			return result;
		}

		public long Pack()
		{
			long result = PackData(stationIndex + 1, 8, 0);
			PackData((int)(decayTime / 5f), 8, 8);
			return result;
		}
	}

