public class GhostReactorLevelGenerator : MonoBehaviourTick
{
	public enum NodeType
	{
		Hub,
		EndCap,
		Blocker
	}

	public class Node
	{
		public NodeType type;

		public int configIndex;

		public int parentAnchorIndex;

		public int attachAnchorIndex;

		public int anchorCount;

		public List<int> anchorOrder;

		public GhostReactorLevelSection sectionInstance;

		public GhostReactorLevelSectionConnector connectorInstance;

		public Node[] children;
	}

	public List<GhostReactorLevelDepthConfig> depthConfigs;

	[SerializeField]
	private GhostReactorLevelSection mainHub = new GhostReactorLevelSection();

	[SerializeField]
	private List<GhostReactorSpawnConfig> mainHubSpawnConfigs;

	[SerializeField]
	private List<Collider> nonOverlapZones = new List<Collider>();

	public int seed = 2343;

	private List<List<Node>> nodeTree = new List<List<Node>>();

	private List<Node> nodeList = new List<Node>();

	private HashSet<string> spawnedHubHashSet = new HashSet<string>();

	private List<int> hubOrder = new List<int>();

	private List<int> connectorOrder = new List<int>();

	private List<int> endCapOrder = new List<int>();

	private List<int> blockerOrder = new List<int>();

	private List<int> entryAnchorOrder = new List<int>();

	private List<Transform> treeParents = new List<Transform>();

	private string generationOutput = "";

	private SRand randomGenerator;

	private BoxCollider testColliderA;

	private BoxCollider testColliderB;

	private GhostReactor reactor;

	[NonSerialized]
	public int depthConfigIndex;

	private UnityEngine.Quaternion flip180 = UnityEngine.Quaternion.AngleAxis(180f, UnityEngine.Vector3.up);

	private const int MAX_VIS_CHECKS_PER_FRAME = 1;

	public int nextVisCheckNodeIndex;

	public List<GhostReactorLevelGeneratorV2.TreeLevelConfig> TreeLevels => GetTreeLevels();

	private void Awake()
	{
		GameObject gameObject = new GameObject("TestColliderA");
		testColliderA = gameObject.AddComponent<BoxCollider>();
		testColliderA.isTrigger = true;
		gameObject.transform.SetParent(base.transform);
		gameObject.gameObject.SetActive(value: false);
		GameObject gameObject2 = new GameObject("TestColliderB");
		testColliderB = gameObject2.AddComponent<BoxCollider>();
		testColliderB.isTrigger = true;
		gameObject2.transform.SetParent(base.transform);
		gameObject2.gameObject.SetActive(value: false);
		nextVisCheckNodeIndex = 0;
	}

	public void Init(GhostReactor reactor)
	{
		this.reactor = reactor;
	}

	public override void Tick()
	{
		UnityEngine.Vector3 position = VRRig.LocalRig.transform.position;
		int num = Mathf.Min(1, nodeList.Count);
		for (int i = 0; i < num; i++)
		{
			if (nextVisCheckNodeIndex >= nodeList.Count)
			{
				nextVisCheckNodeIndex = 0;
			}
			if (nodeList[nextVisCheckNodeIndex] == null)
			{
				continue;
			}
			if (nodeList[nextVisCheckNodeIndex].sectionInstance != null)
			{
				nodeList[nextVisCheckNodeIndex].sectionInstance.UpdateDisable(position);
			}
			if (nodeList[nextVisCheckNodeIndex].connectorInstance != null)
			{
				nodeList[nextVisCheckNodeIndex].connectorInstance.UpdateDisable(position);
			}
			Node[] children = nodeList[nextVisCheckNodeIndex].children;
			for (int j = 0; j < children.Length; j++)
			{
				if (children[j] != null)
				{
					if (children[j].sectionInstance != null)
					{
						children[j].sectionInstance.UpdateDisable(position);
					}
					if (children[j].connectorInstance != null)
					{
						children[j].connectorInstance.UpdateDisable(position);
					}
				}
			}
			nextVisCheckNodeIndex++;
		}
	}

	private List<GhostReactorLevelGeneratorV2.TreeLevelConfig> GetTreeLevels()
	{
		if (depthConfigs == null || depthConfigs.Count == 0)
		{
			return null;
		}
		List<GhostReactorLevelGeneratorV2.TreeLevelConfig> treeLevels = depthConfigs[Mathf.Clamp(reactor.GetDepthLevel(), 0, depthConfigs.Count - 1)].options[reactor.GetDepthConfigIndex()].levelConfig.treeLevels;
		List<GhostReactorLevelGeneratorV2.TreeLevelConfig> list = new List<GhostReactorLevelGeneratorV2.TreeLevelConfig>();
		foreach (GhostReactorLevelGeneratorV2.TreeLevelConfig item in treeLevels)
		{
			if (TreeLevelIsEnabledNow(item))
			{
				list.Add(item);
			}
		}
		return list;
	}

	private static bool TreeLevelIsEnabledNow(GhostReactorLevelGeneratorV2.TreeLevelConfig treeLevel)
	{
		if (string.IsNullOrEmpty(treeLevel.EnableAfterDatetime) && string.IsNullOrEmpty(treeLevel.DisableAfterDatetime))
		{
			return true;
		}
		if (!string.IsNullOrEmpty(treeLevel.EnableAfterDatetime) && !string.IsNullOrEmpty(treeLevel.DisableAfterDatetime))
		{
			throw new ArgumentException("Both enable and disable after datetime are set--this should never happen!");
		}
		DateTime dateTime = GorillaComputer.instance.GetServerTime().ToUniversalTime();
		if (!string.IsNullOrEmpty(treeLevel.EnableAfterDatetime))
		{
			DateTime dateTime2 = DateTime.Parse(treeLevel.EnableAfterDatetime).ToUniversalTime();
			return dateTime > dateTime2;
		}
		DateTime dateTime3 = DateTime.Parse(treeLevel.DisableAfterDatetime).ToUniversalTime();
		return dateTime < dateTime3;
	}

	private bool TestForCollision(GhostReactorLevelSection section, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation, int selfi, int selfj, int selfk)
	{
		testColliderA.gameObject.SetActive(value: true);
		testColliderB.gameObject.SetActive(value: true);
		testColliderA.transform.position = position + rotation * section.BoundingCollider.transform.localPosition;
		testColliderA.transform.rotation = rotation * section.BoundingCollider.transform.localRotation;
		testColliderA.transform.localScale = section.BoundingCollider.transform.localScale;
		testColliderA.size = section.BoundingCollider.size;
		testColliderA.center = section.BoundingCollider.center;
		for (int i = 0; i < nonOverlapZones.Count; i++)
		{
			if (testColliderA.bounds.Intersects(nonOverlapZones[i].bounds) && Physics.ComputePenetration(testColliderA, testColliderA.transform.position, testColliderA.transform.rotation, nonOverlapZones[i], nonOverlapZones[i].transform.position, nonOverlapZones[i].transform.rotation, out var _, out var _))
			{
				testColliderA.gameObject.SetActive(value: false);
				testColliderB.gameObject.SetActive(value: false);
				return true;
			}
		}
		for (int j = 0; j < nodeTree.Count; j++)
		{
			for (int k = 0; k < nodeTree[j].Count; k++)
			{
				if (j == selfi && k == selfj && selfk == -1)
				{
					continue;
				}
				Node node = nodeTree[j][k];
				for (int l = 0; l < node.children.Length; l++)
				{
					if (j == selfi && k == selfj && l == selfk)
					{
						continue;
					}
					Node node2 = node.children[l];
					if (node2 != null && node2.sectionInstance != null && node2.sectionInstance.BoundingCollider != null && (node2.type == NodeType.Blocker || node2.type == NodeType.EndCap))
					{
						GhostReactorLevelSection sectionInstance = node2.sectionInstance;
						testColliderB.transform.position = sectionInstance.transform.position + sectionInstance.transform.rotation * sectionInstance.BoundingCollider.transform.localPosition;
						testColliderB.transform.rotation = sectionInstance.transform.rotation * sectionInstance.BoundingCollider.transform.localRotation;
						testColliderB.transform.localScale = sectionInstance.BoundingCollider.transform.localScale;
						testColliderB.size = sectionInstance.BoundingCollider.size;
						testColliderB.center = sectionInstance.BoundingCollider.center;
						if (testColliderA.bounds.Intersects(testColliderB.bounds) && Physics.ComputePenetration(testColliderA, testColliderA.transform.position, testColliderA.transform.rotation, testColliderB, testColliderB.transform.position, testColliderB.transform.rotation, out var _, out var _))
						{
							testColliderA.gameObject.SetActive(value: false);
							testColliderB.gameObject.SetActive(value: false);
							return true;
						}
					}
				}
				if ((j != selfi || k != selfj) && node.sectionInstance != null && node.sectionInstance.BoundingCollider != null)
				{
					GhostReactorLevelSection sectionInstance2 = node.sectionInstance;
					testColliderB.transform.position = sectionInstance2.transform.position + sectionInstance2.transform.rotation * sectionInstance2.BoundingCollider.transform.localPosition;
					testColliderB.transform.rotation = sectionInstance2.transform.rotation * sectionInstance2.BoundingCollider.transform.localRotation;
					testColliderB.transform.localScale = sectionInstance2.BoundingCollider.transform.localScale;
					testColliderB.size = sectionInstance2.BoundingCollider.size;
					testColliderB.center = sectionInstance2.BoundingCollider.center;
					if (testColliderA.bounds.Intersects(testColliderB.bounds) && Physics.ComputePenetration(testColliderA, testColliderA.transform.position, testColliderA.transform.rotation, testColliderB, testColliderB.transform.position, testColliderB.transform.rotation, out var _, out var _))
					{
						testColliderA.gameObject.SetActive(value: false);
						testColliderB.gameObject.SetActive(value: false);
						return true;
					}
				}
			}
		}
		testColliderA.gameObject.SetActive(value: false);
		testColliderB.gameObject.SetActive(value: false);
		return false;
	}

	private void DebugGenerate()
	{
		Generate(seed);
	}

	public void Generate(int inputSeed)
	{
		ClearLevelSections();
		if (!UnityEngine.Application.isPlaying)
		{
			return;
		}
		seed = inputSeed;
		randomGenerator = new SRand(seed);
		if (TreeLevels.Count < 1)
		{
			return;
		}
		spawnedHubHashSet.Clear();
		for (int i = 0; i < TreeLevels.Count; i++)
		{
			nodeTree.Add(new List<Node>());
			GameObject gameObject = new GameObject($"Tree Level {i}");
			gameObject.transform.parent = base.transform;
			gameObject.transform.SetLocalPositionAndRotation(UnityEngine.Vector3.zero, UnityEngine.Quaternion.identity);
			treeParents.Add(gameObject.transform);
		}
		Node node = new Node();
		node.type = NodeType.Hub;
		node.configIndex = -1;
		node.attachAnchorIndex = -1;
		node.parentAnchorIndex = -1;
		node.children = new Node[mainHub.Anchors.Count];
		node.sectionInstance = mainHub;
		node.anchorCount = mainHub.Anchors.Count;
		node.anchorOrder = new List<int>();
		RandomizeIndices(ref node.anchorOrder, node.anchorCount);
		nodeTree[0].Add(node);
		nodeList.Add(node);
		for (int j = 0; j < TreeLevels.Count; j++)
		{
			List<GhostReactorLevelSection> hubs = TreeLevels[j].hubs;
			List<GhostReactorLevelSectionConnector> connectors = TreeLevels[j].connectors;
			if (hubs.Count < 1 || connectors.Count < 1)
			{
				continue;
			}
			RandomizeIndices(ref hubOrder, hubs.Count);
			RandomizeIndices(ref connectorOrder, connectors.Count);
			int num = 0;
			int num2 = 0;
			int num3 = Mathf.Max(TreeLevels[j].maxHubs - TreeLevels[j].minHubs, 0);
			int num4 = Mathf.Max(TreeLevels[j].minHubs, 0) + randomGenerator.NextInt(num3 + 1);
			for (int k = 0; k < num4; k++)
			{
				if (j > 0 && nodeTree[j].Count < 1)
				{
					continue;
				}
				int num5 = hubOrder[num % hubOrder.Count];
				num++;
				int index = connectorOrder[num2 % connectorOrder.Count];
				num2++;
				int num6 = ((j == 0) ? (-1) : (k % nodeTree[j].Count));
				Node node2 = ((num6 != -1) ? nodeTree[j][num6] : node);
				for (int l = 0; l < node2.anchorOrder.Count; l++)
				{
					int num7 = node2.anchorOrder[l];
					bool flag = spawnedHubHashSet.Contains(hubs[num5].gameObject.name);
					if (node2.children[num7] != null || node2.attachAnchorIndex == num7 || flag)
					{
						continue;
					}
					UnityEngine.Quaternion quaternion2 = node2.sectionInstance.Anchors[num7].rotation * flip180;
					UnityEngine.Vector3 position = node2.sectionInstance.Anchors[num7].position;
					GhostReactorLevelSectionConnector ghostReactorLevelSectionConnector = connectors[index];
					UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.Inverse(ghostReactorLevelSectionConnector.hubAnchor.localRotation) * quaternion2;
					UnityEngine.Vector3 vector = quaternion3 * -ghostReactorLevelSectionConnector.hubAnchor.localPosition + position;
					UnityEngine.Vector3 vector2 = quaternion3 * ghostReactorLevelSectionConnector.sectionAnchor.localPosition + vector;
					UnityEngine.Quaternion quaternion4 = quaternion3 * ghostReactorLevelSectionConnector.sectionAnchor.localRotation;
					GhostReactorLevelSection ghostReactorLevelSection = hubs[num5];
					bool flag2 = false;
					if (ghostReactorLevelSection.Anchors.Count > 0)
					{
						RandomizeIndices(ref entryAnchorOrder, ghostReactorLevelSection.Anchors.Count);
						for (int m = 0; m < entryAnchorOrder.Count; m++)
						{
							int num8 = entryAnchorOrder[m];
							Transform transform = ghostReactorLevelSection.Anchors[num8];
							UnityEngine.Quaternion quaternion5 = UnityEngine.Quaternion.Inverse(transform.localRotation) * quaternion4;
							UnityEngine.Vector3 position2 = quaternion5 * -transform.localPosition + vector2;
							if (!TestForCollision(ghostReactorLevelSection, position2, quaternion5, j, k, num7))
							{
								Node node3 = new Node();
								node3.type = NodeType.Hub;
								node3.configIndex = num5;
								node3.children = new Node[ghostReactorLevelSection.Anchors.Count];
								node3.parentAnchorIndex = num7;
								node3.attachAnchorIndex = num8;
								node3.anchorCount = ghostReactorLevelSection.Anchors.Count;
								node3.anchorOrder = new List<int>();
								RandomizeIndices(ref node3.anchorOrder, node3.anchorCount);
								GhostReactorLevelSectionConnector component = UnityEngine.Object.Instantiate(ghostReactorLevelSectionConnector.gameObject, vector, quaternion3, treeParents[j]).GetComponent<GhostReactorLevelSectionConnector>();
								node3.connectorInstance = component;
								GhostReactorLevelSection component2 = UnityEngine.Object.Instantiate(ghostReactorLevelSection.gameObject, position2, quaternion5, treeParents[j]).GetComponent<GhostReactorLevelSection>();
								node3.sectionInstance = component2;
								node2.children[node3.parentAnchorIndex] = node3;
								nodeTree[j + 1].Add(node3);
								nodeList.Add(node3);
								spawnedHubHashSet.Add(ghostReactorLevelSection.gameObject.name);
								flag2 = true;
								break;
							}
						}
					}
					if (flag2)
					{
						break;
					}
				}
			}
		}
		for (int n = 0; n < nodeTree.Count; n++)
		{
			List<GhostReactorLevelSection> endCaps = TreeLevels[n].endCaps;
			List<GhostReactorLevelSection> blockers = TreeLevels[n].blockers;
			RandomizeIndices(ref blockerOrder, blockers.Count);
			RandomizeIndices(ref endCapOrder, endCaps.Count);
			int num9 = 0;
			int num10 = 0;
			for (int num11 = 0; num11 < nodeTree[n].Count; num11++)
			{
				Node node4 = nodeTree[n][num11];
				int num12 = Mathf.Max(TreeLevels[n].maxCaps - TreeLevels[n].minCaps, 0);
				int num13 = Mathf.Max(TreeLevels[n].minCaps, 0) + randomGenerator.NextInt(num12 + 1);
				for (int num14 = 0; num14 < node4.children.Length; num14++)
				{
					if (node4.children[num14] != null || node4.attachAnchorIndex == num14)
					{
						continue;
					}
					bool flag3 = false;
					if (num13 > 0 && endCapOrder.Count > 0)
					{
						int num15 = endCapOrder[num10 % endCapOrder.Count];
						num10++;
						num13--;
						UnityEngine.Quaternion quaternion6 = node4.sectionInstance.Anchors[num14].rotation * flip180;
						UnityEngine.Vector3 position3 = node4.sectionInstance.Anchors[num14].position;
						GhostReactorLevelSection ghostReactorLevelSection2 = endCaps[num15];
						UnityEngine.Quaternion quaternion7 = UnityEngine.Quaternion.Inverse(ghostReactorLevelSection2.Anchor.localRotation) * quaternion6;
						UnityEngine.Vector3 position4 = quaternion7 * -ghostReactorLevelSection2.Anchor.localPosition + position3;
						if (!TestForCollision(ghostReactorLevelSection2, position4, quaternion7, n, num11, num14))
						{
							Node node5 = new Node();
							node5.type = NodeType.EndCap;
							node5.configIndex = num15;
							node5.parentAnchorIndex = num14;
							GhostReactorLevelSection component3 = UnityEngine.Object.Instantiate(ghostReactorLevelSection2.gameObject, position4, quaternion7, treeParents[n]).GetComponent<GhostReactorLevelSection>();
							node5.sectionInstance = component3;
							node4.children[num14] = node5;
							flag3 = true;
						}
					}
					if (!flag3 && blockerOrder.Count > 0)
					{
						int configIndex = blockerOrder[num9 % blockerOrder.Count];
						num9++;
						Node node6 = new Node();
						node6.type = NodeType.Blocker;
						node6.configIndex = configIndex;
						node6.parentAnchorIndex = num14;
						UnityEngine.Quaternion quaternion8 = node4.sectionInstance.Anchors[num14].rotation * flip180;
						UnityEngine.Vector3 position5 = node4.sectionInstance.Anchors[num14].position;
						GhostReactorLevelSection ghostReactorLevelSection3 = blockers[node6.configIndex];
						UnityEngine.Quaternion quaternion9 = UnityEngine.Quaternion.Inverse(ghostReactorLevelSection3.Anchor.localRotation) * quaternion8;
						UnityEngine.Vector3 position6 = quaternion9 * -ghostReactorLevelSection3.Anchor.localPosition + position5;
						GhostReactorLevelSection component4 = UnityEngine.Object.Instantiate(ghostReactorLevelSection3.gameObject, position6, quaternion9, treeParents[n]).GetComponent<GhostReactorLevelSection>();
						node6.sectionInstance = component4;
						node4.children[num14] = node6;
					}
				}
			}
		}
		for (int num16 = 0; num16 < nodeList.Count; num16++)
		{
			if (nodeList[num16].connectorInstance != null)
			{
				nodeList[num16].connectorInstance.Init(reactor.grManager);
			}
			nodeList[num16].sectionInstance.InitLevelSection(num16, reactor);
		}
	}

	private void DebugClear()
	{
		ClearLevelSections();
	}

	public void ClearLevelSections()
	{
		for (int i = 0; i < nodeList.Count; i++)
		{
			if (!(nodeList[i].sectionInstance == mainHub))
			{
				if (nodeList[i].connectorInstance != null)
				{
					UnityEngine.Object.Destroy(nodeList[i].connectorInstance.gameObject);
				}
				UnityEngine.Object.Destroy(nodeList[i].sectionInstance.gameObject);
			}
		}
		nodeList.Clear();
		for (int j = 0; j < nodeTree.Count; j++)
		{
			nodeTree[j].Clear();
		}
		nodeTree.Clear();
		for (int k = 0; k < treeParents.Count; k++)
		{
			UnityEngine.Object.Destroy(treeParents[k].gameObject);
		}
		treeParents.Clear();
	}

	public void SpawnEntitiesInEachSection(float respawnCount)
	{
		for (int i = 0; i < nodeTree.Count; i++)
		{
			List<GhostReactorSpawnConfig> spawnConfigs = ((i < 1) ? mainHubSpawnConfigs : TreeLevels[i - 1].sectionSpawnConfigs);
			List<GhostReactorSpawnConfig> endCapSpawnConfigs = TreeLevels[i].endCapSpawnConfigs;
			for (int j = 0; j < nodeTree[i].Count; j++)
			{
				Node node = nodeTree[i][j];
				if (node != null && node.sectionInstance != null && node.type == NodeType.Hub)
				{
					node.sectionInstance.SpawnSectionEntities(ref randomGenerator, reactor.grManager.gameEntityManager, reactor, spawnConfigs, respawnCount);
				}
				for (int k = 0; k < node.children.Length; k++)
				{
					Node node2 = node.children[k];
					if (node2 != null && node2.sectionInstance != null && node2.type == NodeType.EndCap)
					{
						node2.sectionInstance.SpawnSectionEntities(ref randomGenerator, reactor.grManager.gameEntityManager, reactor, endCapSpawnConfigs, respawnCount);
					}
				}
			}
		}
		if (GhostReactorLevelSection.tempCreateEntitiesList.Count > 0)
		{
			reactor.grManager.gameEntityManager.RequestCreateItems(GhostReactorLevelSection.tempCreateEntitiesList);
			GhostReactorLevelSection.tempCreateEntitiesList.Clear();
		}
	}

	public void RespawnEntity(int entityId, long entityCreateData, GameEntityId createdByEntityId)
	{
		int sectionIndex = GhostReactor.EnemyEntityCreateData.Unpack(entityCreateData).sectionIndex;
		if (sectionIndex >= 0 && sectionIndex < nodeList.Count)
		{
			nodeList[sectionIndex].sectionInstance.RespawnEntity(ref randomGenerator, reactor.grManager.gameEntityManager, entityId, entityCreateData, createdByEntityId);
		}
	}

	public GRPatrolPath GetPatrolPath(long createData)
	{
		GhostReactor.EnemyEntityCreateData enemyEntityCreateData = GhostReactor.EnemyEntityCreateData.Unpack(createData);
		int sectionIndex = enemyEntityCreateData.sectionIndex;
		int patrolIndex = enemyEntityCreateData.patrolIndex;
		if (sectionIndex < 0 || sectionIndex >= nodeList.Count)
		{
			return null;
		}
		return nodeList[sectionIndex].sectionInstance.GetPatrolPath(patrolIndex);
	}

	private void RandomizeIndices(ref List<int> list, int count)
	{
		list.Clear();
		for (int i = 0; i < count; i++)
		{
			list.Add(i);
		}
		randomGenerator.Shuffle(list);
	}

	public bool GetExitFromCurrentSection(UnityEngine.Vector3 pos, out UnityEngine.Vector3 exitPos, out UnityEngine.Quaternion exitRot, List<UnityEngine.Vector3> connectorCorners)
	{
		exitPos = UnityEngine.Vector3.zero;
		exitRot = UnityEngine.Quaternion.identity;
		Node currentNode = GetCurrentNode(pos);
		if (currentNode == null || currentNode.parentAnchorIndex < 0)
		{
			return false;
		}
		Transform anchor = currentNode.sectionInstance.GetAnchor(currentNode.attachAnchorIndex);
		exitPos = anchor.transform.position;
		exitRot = anchor.transform.rotation;
		GRLevelAnchor component = anchor.GetComponent<GRLevelAnchor>();
		if (component != null && component.navigablePoint != null)
		{
			exitPos = component.navigablePoint.position;
			exitRot = component.navigablePoint.rotation;
		}
		connectorCorners.Clear();
		if (currentNode.connectorInstance != null)
		{
			for (int i = 0; i < currentNode.connectorInstance.pathNodes.Count; i++)
			{
				connectorCorners.Add(currentNode.connectorInstance.pathNodes[i].position);
			}
		}
		return true;
	}

	private Node GetCurrentNode(UnityEngine.Vector3 pos)
	{
		float num = float.MaxValue;
		Node result = null;
		for (int i = 0; i < nodeTree.Count; i++)
		{
			List<Node> list = nodeTree[i];
			for (int j = 0; j < list.Count; j++)
			{
				Node node = list[j];
				if (!(node.sectionInstance == null))
				{
					float distSq = node.sectionInstance.GetDistSq(pos);
					if (distSq < num)
					{
						num = distSq;
						result = node;
					}
				}
			}
		}
		return result;
	}
}
public class GhostReactorLevelSection : MonoBehaviour
{
	public enum SectionType
	{
		Hub,
		EndCap,
		Blocker
	}

	[Serializable]
	public class SpawnPointGroup
	{
		public GhostReactorSpawnConfig.SpawnPointType type;

		public List<GREntitySpawnPoint> spawnPoints;

		private List<int> spawnPointIndexes;

		private bool needsRandomization;

		private int currentIndex;

		public bool NeedsRandomization
		{
			get
			{
				return needsRandomization;
			}
			set
			{
				needsRandomization = value;
			}
		}

		public int CurrentIndex
		{
			get
			{
				return currentIndex;
			}
			set
			{
				currentIndex = value;
			}
		}

		public List<int> SpawnPointIndexes
		{
			get
			{
				return spawnPointIndexes;
			}
			set
			{
				spawnPointIndexes = value;
			}
		}

		public GREntitySpawnPoint GetNextSpawnPoint()
		{
			GREntitySpawnPoint result = spawnPoints[spawnPointIndexes[currentIndex]];
			currentIndex = (currentIndex + 1) % spawnPointIndexes.Count;
			return result;
		}
	}

	private const float SHOW_DIST = 32f;

	private const float HIDE_DIST = 36f;

	private const int MAX_CREATE_PER_RPC = 25;

	[SerializeField]
	private SectionType sectionType;

	[SerializeField]
	[Tooltip("Single Anchor Transform used for End Caps and Blockers")]
	private Transform anchorTransform;

	[SerializeField]
	[Tooltip("A List of Anchors used as in and out connections for Hubs")]
	private List<Transform> anchors = new List<Transform>();

	[SerializeField]
	private List<SpawnPointGroup> spawnPointGroups;

	[SerializeField]
	private List<GhostReactorSpawnConfig> spawnConfigs;

	[SerializeField]
	private List<GRPatrolPath> patrolPaths;

	[SerializeField]
	private BoxCollider boundingCollider;

	private List<Renderer> renderers;

	private bool hidden;

	private List<GRHazardousMaterial> hazardousMaterials;

	[HideInInspector]
	public GhostReactorLevelSectionConnector sectionConnector;

	[HideInInspector]
	public int hubAnchorIndex;

	private int index;

	private SpawnPointGroup[] spawnPointGroupLookup;

	private List<GameEntity> prePlacedGameEntities;

	public static List<GameEntityCreateData> tempCreateEntitiesList = new List<GameEntityCreateData>(32);

	private int rotatingIndexForRespawn;

	public Transform Anchor => anchorTransform;

	public List<Transform> Anchors => anchors;

	public SectionType Type => sectionType;

	public BoxCollider BoundingCollider => boundingCollider;

	private void Awake()
	{
		spawnPointGroupLookup = new SpawnPointGroup[11];
		for (int i = 0; i < spawnPointGroups.Count; i++)
		{
			spawnPointGroups[i].SpawnPointIndexes = new List<int>();
			int type = (int)spawnPointGroups[i].type;
			if (type < spawnPointGroupLookup.Length)
			{
				spawnPointGroupLookup[type] = spawnPointGroups[i];
			}
		}
		hazardousMaterials = new List<GRHazardousMaterial>(32);
		GetComponentsInChildren(hazardousMaterials);
		for (int j = 0; j < patrolPaths.Count; j++)
		{
			if (patrolPaths[j] == null)
			{
				UnityEngine.Debug.LogErrorFormat("Why does {0} have a null patrol path at index {1}", base.gameObject.name, j);
			}
			else
			{
				patrolPaths[j].index = j;
			}
		}
		prePlacedGameEntities = new List<GameEntity>(128);
		GetComponentsInChildren(prePlacedGameEntities);
		for (int k = 0; k < prePlacedGameEntities.Count; k++)
		{
			prePlacedGameEntities[k].gameObject.SetActive(value: false);
		}
		renderers = new List<Renderer>(512);
		hidden = false;
		GetComponentsInChildren(includeInactive: false, renderers);
		for (int num = renderers.Count - 1; num >= 0; num--)
		{
			if (renderers[num] == null || !renderers[num].enabled)
			{
				renderers.RemoveAt(num);
			}
		}
		if (boundingCollider == null)
		{
			UnityEngine.Debug.LogWarningFormat("Missing Bounding Collider for section {0}", base.gameObject.name);
		}
	}

	public static void RandomizeIndices(List<int> list, int count, ref SRand randomGenerator)
	{
		list.Clear();
		for (int i = 0; i < count; i++)
		{
			list.Add(i);
		}
		randomGenerator.Shuffle(list);
	}

	public void InitLevelSection(int sectionIndex, GhostReactor reactor)
	{
		index = sectionIndex;
		for (int i = 0; i < hazardousMaterials.Count; i++)
		{
			hazardousMaterials[i].Init(reactor);
		}
	}

	public void SpawnSectionEntities(ref SRand randomGenerator, GameEntityManager gameEntityManager, GhostReactor reactor, List<GhostReactorSpawnConfig> spawnConfigs, float respawnCount)
	{
		if (spawnConfigs == null)
		{
			spawnConfigs = this.spawnConfigs;
		}
		if (spawnConfigs == null || spawnConfigs.Count <= 0)
		{
			return;
		}
		GhostReactorSpawnConfig ghostReactorSpawnConfig = spawnConfigs[randomGenerator.NextInt(spawnConfigs.Count)];
		UnityEngine.Debug.LogFormat("Spawn Ghost Reactor Level Section {0} {1}", base.gameObject.name, ghostReactorSpawnConfig.name);
		for (int i = 0; i < spawnPointGroups.Count; i++)
		{
			spawnPointGroups[i].CurrentIndex = 0;
			spawnPointGroups[i].NeedsRandomization = true;
		}
		GhostReactor.EnemyEntityCreateData enemyEntityCreateData = default(GhostReactor.EnemyEntityCreateData);
		for (int j = 0; j < ghostReactorSpawnConfig.entitySpawnGroups.Count; j++)
		{
			int spawnCount = ghostReactorSpawnConfig.entitySpawnGroups[j].spawnCount;
			if (spawnCount <= 0)
			{
				continue;
			}
			int spawnPointType = (int)ghostReactorSpawnConfig.entitySpawnGroups[j].spawnPointType;
			if (spawnPointType >= spawnPointGroupLookup.Length)
			{
				continue;
			}
			SpawnPointGroup spawnPointGroup = spawnPointGroupLookup[spawnPointType];
			if (spawnPointGroup == null)
			{
				continue;
			}
			if (spawnPointGroup.NeedsRandomization)
			{
				spawnPointGroup.NeedsRandomization = false;
				RandomizeIndices(spawnPointGroup.SpawnPointIndexes, spawnPointGroup.spawnPoints.Count, ref randomGenerator);
			}
			spawnCount = Mathf.Min(spawnCount, spawnPointGroup.spawnPoints.Count);
			for (int k = 0; k < spawnCount; k++)
			{
				_ = spawnPointGroup.CurrentIndex;
				GREntitySpawnPoint nextSpawnPoint = spawnPointGroup.GetNextSpawnPoint();
				_ = nextSpawnPoint == null;
				GameEntity entity = ghostReactorSpawnConfig.entitySpawnGroups[j].entity;
				if (ghostReactorSpawnConfig.entitySpawnGroups[j].randomEntity != null)
				{
					ghostReactorSpawnConfig.entitySpawnGroups[j].randomEntity.TryForRandomItem(reactor, ref randomGenerator, out entity);
				}
				if (entity == null)
				{
					continue;
				}
				int staticHash = entity.name.GetStaticHash();
				long createData = -1L;
				if (nextSpawnPoint.applyScale)
				{
					createData = BitPackUtils.PackWorldPosForNetwork(nextSpawnPoint.transform.localScale);
				}
				else if (spawnPointGroup.type == GhostReactorSpawnConfig.SpawnPointType.Enemy || spawnPointGroup.type == GhostReactorSpawnConfig.SpawnPointType.Pest || nextSpawnPoint.patrolPath != null)
				{
					int patrolIndex = 255;
					if (nextSpawnPoint.patrolPath != null)
					{
						patrolIndex = nextSpawnPoint.patrolPath.index;
					}
					int num = (int)respawnCount;
					if (randomGenerator.NextFloat() < respawnCount - (float)num)
					{
						num++;
					}
					enemyEntityCreateData.respawnCount = num;
					enemyEntityCreateData.sectionIndex = index;
					enemyEntityCreateData.patrolIndex = patrolIndex;
					createData = enemyEntityCreateData.Pack();
				}
				GameEntityCreateData item = new GameEntityCreateData
				{
					entityTypeId = staticHash,
					position = nextSpawnPoint.transform.position,
					rotation = nextSpawnPoint.transform.rotation,
					createData = createData,
					createdByEntityId = -1,
					slotIndex = -1
				};
				tempCreateEntitiesList.Add(item);
				if (tempCreateEntitiesList.Count > 25)
				{
					gameEntityManager.RequestCreateItems(tempCreateEntitiesList);
					tempCreateEntitiesList.Clear();
				}
			}
		}
		for (int l = 0; l < prePlacedGameEntities.Count; l++)
		{
			if (prePlacedGameEntities[l].isBuiltIn)
			{
				continue;
			}
			int staticHash2 = prePlacedGameEntities[l].gameObject.name.GetStaticHash();
			if (!gameEntityManager.FactoryHasEntity(staticHash2))
			{
				UnityEngine.Debug.LogErrorFormat("Cannot Find Entity in Factory {0} {1} Trying to spawn in {2}", prePlacedGameEntities[l].gameObject.name, staticHash2, base.gameObject.name);
				continue;
			}
			GameEntityCreateData item2 = new GameEntityCreateData
			{
				entityTypeId = staticHash2,
				position = prePlacedGameEntities[l].transform.position,
				rotation = prePlacedGameEntities[l].transform.rotation,
				createData = 0L,
				createdByEntityId = -1,
				slotIndex = -1
			};
			tempCreateEntitiesList.Add(item2);
			if (tempCreateEntitiesList.Count > 25)
			{
				gameEntityManager.RequestCreateItems(tempCreateEntitiesList);
				tempCreateEntitiesList.Clear();
			}
		}
	}

	public void RespawnEntity(ref SRand randomGenerator, GameEntityManager gameEntityManager, int entityId, long entityCreateData, GameEntityId createdByEntityId)
	{
		if (0 <= spawnPointGroupLookup.Length)
		{
			SpawnPointGroup spawnPointGroup = spawnPointGroupLookup[0];
			int count = spawnPointGroup.spawnPoints.Count;
			if (count > 3)
			{
				rotatingIndexForRespawn = (rotatingIndexForRespawn + randomGenerator.NextInt(1, 1 + spawnPointGroup.spawnPoints.Count / 2)) % spawnPointGroup.spawnPoints.Count;
			}
			else if (count > 1)
			{
				rotatingIndexForRespawn = (rotatingIndexForRespawn + 1) % count;
			}
			else
			{
				rotatingIndexForRespawn = 0;
			}
			GREntitySpawnPoint gREntitySpawnPoint = spawnPointGroup.spawnPoints[rotatingIndexForRespawn];
			GhostReactor.EnemyEntityCreateData enemyEntityCreateData = GhostReactor.EnemyEntityCreateData.Unpack(entityCreateData);
			enemyEntityCreateData.patrolIndex = ((gREntitySpawnPoint.patrolPath != null) ? gREntitySpawnPoint.patrolPath.index : 255);
			long createData = enemyEntityCreateData.Pack();
			gameEntityManager.RequestCreateItem(entityId, gREntitySpawnPoint.transform.position, gREntitySpawnPoint.transform.rotation, createData, createdByEntityId);
		}
	}

	public GRPatrolPath GetPatrolPath(int patrolPathIndex)
	{
		if (patrolPathIndex >= 0 && patrolPathIndex < patrolPaths.Count)
		{
			return patrolPaths[patrolPathIndex];
		}
		return null;
	}

	public void Hide(bool hide)
	{
		for (int i = 0; i < renderers.Count; i++)
		{
			if (!(renderers[i] == null))
			{
				renderers[i].enabled = !hide;
			}
		}
	}

	public void UpdateDisable(UnityEngine.Vector3 playerPos)
	{
		if (!(boundingCollider == null))
		{
			float distSq = GetDistSq(playerPos);
			float num = 1024f;
			float num2 = 1296f;
			if (hidden && distSq < num)
			{
				hidden = false;
				Hide(hide: false);
			}
			else if (!hidden && distSq > num2)
			{
				hidden = true;
				Hide(hide: true);
			}
		}
	}

	public float GetDistSq(UnityEngine.Vector3 pos)
	{
		return (boundingCollider.ClosestPoint(pos) - pos).sqrMagnitude;
	}

	public Transform GetAnchor(int anchorIndex)
	{
		return anchors[anchorIndex];
	}
}
public class GhostReactorLevelSectionConnector : MonoBehaviour
{
	public enum Direction
	{
		Down = -1,
		Forward,
		Up
	}

	public Transform hubAnchor;

	public Transform sectionAnchor;

	public Transform gateSpawnPoint;

	public GameEntity gateEntity;

	public Direction direction;

	public BoxCollider boundingCollider;

	public List<Transform> pathNodes;

	private const float SHOW_DIST = 18f;

	private const float HIDE_DIST = 22f;

	private List<GameEntity> prePlacedGameEntities;

	private List<Renderer> renderers;

	private bool hidden;

	private void Awake()
	{
		prePlacedGameEntities = new List<GameEntity>(128);
		GetComponentsInChildren(prePlacedGameEntities);
		for (int i = 0; i < prePlacedGameEntities.Count; i++)
		{
			prePlacedGameEntities[i].gameObject.SetActive(value: false);
		}
		renderers = new List<Renderer>(512);
		hidden = false;
		GetComponentsInChildren(renderers);
		if (boundingCollider == null)
		{
			UnityEngine.Debug.LogWarningFormat("Missing Bounding Collider for section {0}", base.gameObject.name);
		}
	}

	public void Init(GhostReactorManager grManager)
	{
		if (!grManager.IsAuthority())
		{
			return;
		}
		if (gateEntity != null)
		{
			grManager.gameEntityManager.RequestCreateItem(gateEntity.name.GetStaticHash(), gateSpawnPoint.position, gateSpawnPoint.rotation, 0L);
		}
		for (int i = 0; i < prePlacedGameEntities.Count; i++)
		{
			if (!prePlacedGameEntities[i].isBuiltIn)
			{
				int staticHash = prePlacedGameEntities[i].gameObject.name.GetStaticHash();
				if (!grManager.gameEntityManager.FactoryHasEntity(staticHash))
				{
					UnityEngine.Debug.LogErrorFormat("Cannot Find Entity in Factory {0} {1}", prePlacedGameEntities[i].gameObject.name, staticHash);
					continue;
				}
				GameEntityCreateData item = new GameEntityCreateData
				{
					entityTypeId = staticHash,
					position = prePlacedGameEntities[i].transform.position,
					rotation = prePlacedGameEntities[i].transform.rotation,
					createData = 0L,
					createdByEntityId = -1,
					slotIndex = -1
				};
				GhostReactorLevelSection.tempCreateEntitiesList.Add(item);
			}
		}
		grManager.gameEntityManager.RequestCreateItems(GhostReactorLevelSection.tempCreateEntitiesList);
		GhostReactorLevelSection.tempCreateEntitiesList.Clear();
	}

	public void Hide(bool hide)
	{
		for (int i = 0; i < renderers.Count; i++)
		{
			if (!(renderers[i] == null))
			{
				renderers[i].enabled = !hide;
			}
		}
	}

	public void UpdateDisable(UnityEngine.Vector3 playerPos)
	{
		if (!(boundingCollider == null))
		{
			float sqrMagnitude = (boundingCollider.ClosestPoint(playerPos) - playerPos).sqrMagnitude;
			float num = 324f;
			float num2 = 484f;
			if (hidden && sqrMagnitude < num)
			{
				hidden = false;
				Hide(hide: false);
			}
			else if (!hidden && sqrMagnitude > num2)
			{
				hidden = true;
				Hide(hide: true);
			}
		}
	}
}
