public static class AbilityHelperFunctions
{
	private static int navMeshWalkableArea = -1;

	public static float EaseOutPower(float t, float power)
	{
		return 1f - Mathf.Pow(1f - t, power);
	}

	public static int RandomRangeUnique(int minInclusive, int maxExclusive, int lastValue)
	{
		int num = maxExclusive - minInclusive;
		if (num <= 1)
		{
			return minInclusive;
		}
		int num2 = UnityEngine.Random.Range(minInclusive, maxExclusive);
		if (num2 != lastValue)
		{
			return num2;
		}
		return (num2 + 1) % num;
	}

	public static int GetNavMeshWalkableArea()
	{
		if (navMeshWalkableArea == -1)
		{
			navMeshWalkableArea = NavMesh.GetAreaFromName("walkable");
		}
		return navMeshWalkableArea;
	}

	public static UnityEngine.Vector3? GetLocationToInvestigate(UnityEngine.Vector3 listenerLocation, float hearingRadius, UnityEngine.Vector3? currentInvestigationLocation)
	{
		if (GRNoiseEventManager.instance.GetMostRecentNoiseEventInRadius(listenerLocation, hearingRadius, out var outEvent) && NavMesh.SamplePosition(outEvent.position, out var hit, 1f, GetNavMeshWalkableArea()))
		{
			return hit.position;
		}
		return currentInvestigationLocation ?? ((UnityEngine.Vector3?)null);
	}
}
[Serializable]
public class AbilitySound
{
	public enum SoundSelectMode
	{
		Sequential,
		Random
	}

	public float volume = 1f;

	public float pitch = 1f;

	public bool loop;

	public float delay;

	public List<AudioClip> sounds;

	private AudioClip currentSound;

	public AudioSource audioSource;

	private AudioSource usedAudioSource;

	private int nextSound = -1;

	public SoundSelectMode soundSelectMode;

	public bool IsValid()
	{
		if (sounds != null)
		{
			return sounds.Count > 0;
		}
		return false;
	}

	public void UpdateNextSound()
	{
		switch (soundSelectMode)
		{
		case SoundSelectMode.Sequential:
			nextSound = (nextSound + 1) % sounds.Count;
			break;
		case SoundSelectMode.Random:
			nextSound = UnityEngine.Random.Range(0, sounds.Count);
			break;
		}
	}

	public void Play(AudioSource audioSourceIn)
	{
		usedAudioSource = ((audioSourceIn != null) ? audioSourceIn : audioSource);
		if (sounds == null || sounds.Count <= 0 || !(usedAudioSource != null))
		{
			return;
		}
		if (nextSound < 0)
		{
			UpdateNextSound();
		}
		AudioClip audioClip = sounds[nextSound];
		UpdateNextSound();
		if (audioClip != null)
		{
			usedAudioSource.clip = audioClip;
			usedAudioSource.volume = volume;
			usedAudioSource.pitch = pitch;
			usedAudioSource.loop = loop;
			if (delay <= 0f)
			{
				usedAudioSource.Play();
			}
			else
			{
				usedAudioSource.PlayDelayed(delay);
			}
			currentSound = audioClip;
		}
	}

	public void Stop()
	{
		if (usedAudioSource != null && usedAudioSource.clip == currentSound)
		{
			usedAudioSource.Stop();
			currentSound = null;
			usedAudioSource = null;
		}
	}
}
[Serializable]
public class AbilityHaptic
{
	public float strength = 0.2f;

	public float duration = 0.1f;

	public void PlayIfHeldLocal(GameEntity gameEntity)
	{
		if (gameEntity == null || !gameEntity.IsHeldByLocalPlayer())
		{
			return;
		}
		GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
		if (!(gamePlayer == null))
		{
			int num = gamePlayer.FindHandIndex(gameEntity.id);
			if (num != -1)
			{
				GorillaTagger.Instance.StartVibration(GamePlayer.IsLeftHand(num), strength, duration);
			}
		}
	}

	public void PlayIfSnappedLocal(GameEntity gameEntity)
	{
		if (gameEntity == null || !gameEntity.IsSnappedByLocalPlayer())
		{
			return;
		}
		GameSnappable component = gameEntity.GetComponent<GameSnappable>();
		if (component == null)
		{
			return;
		}
		if (component.IsSnappedToLeftArm())
		{
			GorillaTagger.Instance.StartVibration(forLeftController: true, strength, duration);
		}
		if (component.IsSnappedToRightArm())
		{
			GorillaTagger.Instance.StartVibration(forLeftController: false, strength, duration);
		}
		GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
		if (!(gamePlayer == null))
		{
			int num = gamePlayer.FindHandIndex(gameEntity.id);
			if (num != -1)
			{
				GorillaTagger.Instance.StartVibration(GamePlayer.IsLeftHand(num), strength, duration);
			}
		}
	}
}
[Serializable]
public class GameAbilityEvent
{
	public float time;

	public AbilitySound sound;

	public List<UnityEvent> triggerEvent;

	[NonSerialized]
	public bool played;

	public void Reset()
	{
		played = false;
	}

	public void TryPlay(float abilityTime, AudioSource audioSource)
	{
		if (!(abilityTime < time) && !played)
		{
			played = true;
			if (sound.IsValid())
			{
				sound.Play(audioSource);
			}
			for (int i = 0; i < triggerEvent.Count; i++)
			{
				triggerEvent[i].Invoke();
			}
		}
	}
}
[Serializable]
public class GameAbilityEvents
{
	public GameAbilityEvent startEvent;

	public GameAbilityEvent stopEvent;

	public List<GameAbilityEvent> events;

	public void Reset()
	{
		for (int i = 0; i < events.Count; i++)
		{
			events[i].Reset();
		}
	}

	public void OnAbilityStart(float abilityTime, AudioSource audioSource)
	{
		startEvent.TryPlay(abilityTime, (startEvent.sound.audioSource == null) ? audioSource : startEvent.sound.audioSource);
	}

	public void OnAbilityStop(float abilityTime, AudioSource audioSource)
	{
		stopEvent.TryPlay(abilityTime, (stopEvent.sound.audioSource == null) ? audioSource : stopEvent.sound.audioSource);
	}

	public void TryPlay(float abilityTime, AudioSource audioSource)
	{
		for (int i = 0; i < events.Count; i++)
		{
			events[i].TryPlay(abilityTime, (events[i].sound.audioSource == null) ? audioSource : events[i].sound.audioSource);
		}
	}
}
public class GRAbilityBase
{
	protected GameAgent agent;

	protected GameEntity entity;

	protected Animation anim;

	protected Animator animator;

	protected Transform root;

	protected Transform head;

	protected AudioSource audioSource;

	protected GRSenseLineOfSight lineOfSight;

	protected Rigidbody rb;

	protected GRAttributes attributes;

	[Unity.XR.CoreUtils.ReadOnly]
	public double startTime;

	[Unity.XR.CoreUtils.ReadOnly]
	public double stopTime;

	protected int walkableArea = -1;

	protected virtual void OnStart()
	{
	}

	protected virtual void OnStop()
	{
	}

	protected virtual void OnThink(float dt)
	{
	}

	protected virtual void OnUpdateShared(float dt)
	{
	}

	protected virtual void OnUpdateRemote(float dt)
	{
	}

	protected virtual void OnUpdateAuthority(float dt)
	{
	}

	public virtual bool IsCoolDownOver()
	{
		return true;
	}

	public virtual void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		this.root = root;
		this.anim = anim;
		if (anim == null)
		{
			animator = null;
		}
		this.agent = agent;
		this.head = head;
		this.audioSource = audioSource;
		this.lineOfSight = lineOfSight;
		rb = agent.GetComponent<Rigidbody>();
		entity = agent.GetComponent<GameEntity>();
		attributes = agent.GetComponent<GRAttributes>();
		walkableArea = NavMesh.GetAreaFromName("walkable");
	}

	public void Start()
	{
		startTime = Time.timeAsDouble;
		OnStart();
	}

	public void Stop()
	{
		stopTime = Time.timeAsDouble;
		OnStop();
	}

	public float GetAbilityTime(double currTime)
	{
		return (float)(currTime - startTime);
	}

	public virtual bool IsDone()
	{
		return false;
	}

	public void Think(float dt)
	{
		OnThink(dt);
	}

	public void UpdateAuthority(float dt)
	{
		OnUpdateShared(dt);
		OnUpdateAuthority(dt);
	}

	public void UpdateRemote(float dt)
	{
		OnUpdateShared(dt);
		OnUpdateRemote(dt);
	}

	protected virtual void PlayAnim(string animName, float blendTime, float speed)
	{
		if (anim != null && !string.IsNullOrEmpty(animName))
		{
			if (anim.GetClip(animName) == null)
			{
				UnityEngine.Debug.LogErrorFormat("Anim Clip {0} does not exist in (1)", animName, anim);
			}
			else
			{
				anim[animName].speed = speed;
				anim.CrossFade(animName, blendTime);
			}
		}
	}

	public bool IsCoolDownOver(float coolDown)
	{
		return (float)(Time.timeAsDouble - stopTime) > coolDown;
	}

	public virtual float GetRange()
	{
		return 0f;
	}
}
[Serializable]
public class GRAbilityIdle : GRAbilityBase
{
	public float duration;

	public string animName;

	public float animSpeed;

	public float coolDown;

	public float range;

	private float cachedDuration;

	private float cachedAnimSpeed;

	public GameAbilityEvents events;

	[Unity.XR.CoreUtils.ReadOnly]
	public int animLoops;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		animLoops = 0;
		cachedDuration = duration;
		cachedAnimSpeed = animSpeed;
	}

	protected override void OnStart()
	{
		agent.SetStopped(stopMovement: true);
		PlayAnim(animName, 0.3f, animSpeed);
		animLoops = 0;
		events.Reset();
		events.OnAbilityStart(GetAbilityTime(Time.timeAsDouble), audioSource);
	}

	protected override void OnStop()
	{
		events.OnAbilityStop(GetAbilityTime(Time.timeAsDouble), audioSource);
		agent.SetStopped(stopMovement: false);
	}

	protected override void OnUpdateShared(float dt)
	{
		float abilityTime = (float)(Time.timeAsDouble - startTime);
		if (anim != null && anim[animName] != null)
		{
			if ((int)anim[animName].normalizedTime > animLoops)
			{
				events.Reset();
				animLoops = (int)anim[animName].normalizedTime;
			}
			abilityTime = anim[animName].time - anim[animName].length * (float)animLoops;
		}
		events.TryPlay(abilityTime, audioSource);
	}

	public override bool IsDone()
	{
		if ((double)duration > 0.0)
		{
			return Time.timeAsDouble >= startTime + (double)duration;
		}
		return false;
	}

	public override bool IsCoolDownOver()
	{
		return IsCoolDownOver(coolDown);
	}

	public override float GetRange()
	{
		return range;
	}

	public void SpeedUp(float mult)
	{
		duration = cachedDuration / mult;
		animSpeed = cachedAnimSpeed * mult;
	}
}
[Serializable]
public class GRAbilityInterpolatedMovement
{
	public enum InterpType
	{
		Linear,
		EaseOut
	}

	public UnityEngine.Vector3 velocity = UnityEngine.Vector3.zero;

	private UnityEngine.Vector3 startPos;

	private UnityEngine.Vector3 endPos;

	public float duration;

	public double endTime;

	public float maxVelocityMagnitude = 2f;

	private Transform root;

	private Rigidbody rb;

	public InterpType interpolationType;

	private int walkableArea = -1;

	public void Setup(Transform root)
	{
		this.root = root;
		rb = root.gameObject.GetComponent<Rigidbody>();
		walkableArea = NavMesh.GetAreaFromName("walkable");
	}

	public void InitFromVelocityAndDuration(UnityEngine.Vector3 velocity, float duration)
	{
		this.velocity = velocity;
		this.duration = duration;
		_ = velocity.magnitude;
	}

	public void Start()
	{
		startPos = root.position;
		endPos = startPos + velocity * duration;
		endTime = Time.timeAsDouble + (double)duration;
		if (NavMesh.SamplePosition(endPos, out var hit, 5f, walkableArea))
		{
			endPos = hit.position;
		}
	}

	public void Stop()
	{
	}

	public bool IsDone()
	{
		return Time.timeAsDouble >= endTime;
	}

	public void Update(float dt)
	{
		UnityEngine.Vector3 position = root.position;
		float num = Mathf.Clamp01(1f - (float)((endTime - Time.timeAsDouble) / (double)duration));
		InterpType interpType = interpolationType;
		UnityEngine.Vector3 vector = ((interpType == InterpType.Linear || interpType != InterpType.EaseOut) ? UnityEngine.Vector3.Lerp(startPos, endPos, num) : UnityEngine.Vector3.Lerp(startPos, endPos, AbilityHelperFunctions.EaseOutPower(num, 2.5f)));
		vector.y = Mathf.Lerp(startPos.y, endPos.y, num * num);
		if (NavMesh.Raycast(position, vector, out var hit, walkableArea))
		{
			vector = hit.position;
		}
		root.position = vector;
		if (rb != null)
		{
			rb.position = vector;
		}
	}
}
[Serializable]
public class GRAbilityJump : GRAbilityBase
{
	private UnityEngine.Vector3 startPos;

	private UnityEngine.Vector3 endPos;

	private UnityEngine.Vector3 controlPoint;

	[Unity.XR.CoreUtils.ReadOnly]
	public float jumpTime;

	[Unity.XR.CoreUtils.ReadOnly]
	public float elapsedTime;

	private bool isActive;

	public AnimationData animationData;

	public float jumpSpeed = 3f;

	public AbilitySound soundJump;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		isActive = false;
	}

	public void SetupJump(UnityEngine.Vector3 start, UnityEngine.Vector3 end, float heightScale = 1f, float speedScale = 1f)
	{
		elapsedTime = 0f;
		startPos = start;
		endPos = end;
		float magnitude = (endPos - startPos).magnitude;
		controlPoint = (startPos + endPos) / 2f + new UnityEngine.Vector3(0f, magnitude * heightScale, 0f);
		jumpTime = magnitude / (jumpSpeed * speedScale);
	}

	public void SetupJumpFromLinkData(OffMeshLinkData linkData)
	{
		if ((root.position - linkData.startPos).sqrMagnitude < (root.position - linkData.endPos).sqrMagnitude)
		{
			SetupJump(linkData.startPos, linkData.endPos);
		}
		else
		{
			SetupJump(linkData.endPos, linkData.startPos);
		}
	}

	protected override void OnStart()
	{
		elapsedTime = 0f;
		isActive = true;
		PlayAnim(animationData.animName, 0.05f, animationData.speed);
		agent.SetStopped(stopMovement: true);
		agent.SetDisableNetworkSync(disable: true);
		agent.pauseEntityThink = true;
		soundJump.Play(audioSource);
	}

	protected override void OnStop()
	{
		agent.navAgent.Warp(endPos);
		agent.navAgent.CompleteOffMeshLink();
		agent.SetStopped(stopMovement: false);
		isActive = false;
		agent.SetDisableNetworkSync(disable: false);
		agent.pauseEntityThink = false;
	}

	public override bool IsDone()
	{
		return elapsedTime >= jumpTime;
	}

	public bool IsActive()
	{
		return isActive;
	}

	protected override void OnUpdateShared(float dt)
	{
		if (GhostReactorManager.entityDebugEnabled)
		{
			DebugUtil.DrawLine(startPos, controlPoint, Color.green);
			DebugUtil.DrawLine(endPos, controlPoint, Color.green);
		}
		float t = ((jumpTime > 0f) ? System.Math.Clamp(elapsedTime / jumpTime, 0f, 1f) : 1f);
		UnityEngine.Vector3 position = EvaluateQuadratic(startPos, controlPoint, endPos, t);
		root.position = position;
		if (rb != null)
		{
			rb.position = position;
		}
		elapsedTime += dt;
	}

	public static UnityEngine.Vector3 EvaluateQuadratic(UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, float t)
	{
		UnityEngine.Vector3 a = UnityEngine.Vector3.Lerp(p0, p1, t);
		UnityEngine.Vector3 b = UnityEngine.Vector3.Lerp(p1, p2, t);
		return UnityEngine.Vector3.Lerp(a, b, t);
	}
}
[Serializable]
public class GRAbilityWatch : GRAbilityBase
{
	public float duration;

	public string animName;

	public float animSpeed;

	public float maxTurnSpeed;

	private Transform target;

	[Unity.XR.CoreUtils.ReadOnly]
	public double endTime;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		target = null;
	}

	protected override void OnStart()
	{
		PlayAnim(animName, 0.1f, animSpeed);
		endTime = -1.0;
		if (duration > 0f)
		{
			endTime = Time.timeAsDouble + (double)duration;
		}
		agent.SetStopped(stopMovement: true);
	}

	protected override void OnStop()
	{
		agent.SetStopped(stopMovement: false);
	}

	public override bool IsDone()
	{
		if (endTime > 0.0)
		{
			return Time.timeAsDouble >= endTime;
		}
		return false;
	}

	protected override void OnUpdateShared(float dt)
	{
		GameAgent.UpdateFacingTarget(root, agent.navAgent, target, maxTurnSpeed);
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
		target = null;
		if (targetPlayer != null)
		{
			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
			}
		}
	}
}
[Serializable]
public class GRAbilityMoveToTarget : GRAbilityBase
{
	public float moveSpeed;

	public string animName;

	public float animSpeed = 1f;

	public float maxTurnSpeed = 360f;

	public AbilitySound movementSound;

	private UnityEngine.Vector3 targetPos;

	private Transform target;

	private Transform lookAtTarget;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		target = null;
		targetPos = agent.transform.position;
	}

	protected override void OnStart()
	{
		PlayAnim(animName, 0.3f, animSpeed);
		if ((bool)attributes && moveSpeed == 0f)
		{
			moveSpeed = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.PatrolSpeed);
		}
		agent.navAgent.speed = moveSpeed;
		targetPos = agent.transform.position;
		movementSound.Play(null);
	}

	protected override void OnStop()
	{
		movementSound.Stop();
	}

	public override bool IsDone()
	{
		return (targetPos - root.position).sqrMagnitude < 0.25f;
	}

	protected override void OnUpdateShared(float dt)
	{
		if (target != null)
		{
			targetPos = target.position;
			agent.RequestDestination(targetPos);
		}
		Transform transform = ((lookAtTarget != null) ? lookAtTarget : target);
		GameAgent.UpdateFacingTarget(root, agent.navAgent, transform, maxTurnSpeed);
	}

	public void SetTarget(Transform transform)
	{
		target = transform;
	}

	public void SetTargetPos(UnityEngine.Vector3 targetPos)
	{
		this.targetPos = targetPos;
		agent.RequestDestination(targetPos);
	}

	public UnityEngine.Vector3 GetTargetPos()
	{
		return targetPos;
	}

	public void SetLookAtTarget(Transform transform)
	{
		lookAtTarget = transform;
	}
}
[Serializable]
public class GRAbilityChase : GRAbilityBase
{
	public float chaseSpeed;

	public string animName;

	public float animSpeed;

	public float maxTurnSpeed;

	public float loseVisibilityDelay;

	public float giveUpDelay;

	public AbilitySound movementSound;

	private NetPlayer targetPlayer;

	private double lastSeenTargetTime;

	private UnityEngine.Vector3 lastSeenTargetPosition;

	private static List<UnityEngine.Vector3> targetOffsets;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		targetPlayer = null;
		lastSeenTargetTime = 0.0;
		lastSeenTargetPosition = UnityEngine.Vector3.zero;
		if (targetOffsets == null)
		{
			int num = 8;
			targetOffsets = new List<UnityEngine.Vector3>(num);
			float x = 1f;
			for (int i = 0; i < num; i++)
			{
				UnityEngine.Vector3 vector = new UnityEngine.Vector3(x, 0f, 0f);
				vector = UnityEngine.Quaternion.Euler(0f, (float)i / (float)num * 360f, 0f) * vector;
				targetOffsets.Add(vector);
			}
			System.Random random = new System.Random();
			List<UnityEngine.Vector3> collection = targetOffsets.OrderBy((UnityEngine.Vector3 vector2) => random.Next()).ToList();
			targetOffsets.Clear();
			targetOffsets.AddRange(collection);
		}
		if ((bool)attributes && chaseSpeed == 0f)
		{
			chaseSpeed = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.ChaseSpeed);
		}
	}

	protected override void OnStart()
	{
		PlayAnim(animName, 0.1f, animSpeed);
		agent.SetSpeed(chaseSpeed);
		lastSeenTargetTime = Time.timeAsDouble;
		movementSound.Play(null);
		agent.ClearLastRequestedDestination();
	}

	protected override void OnStop()
	{
	}

	public override bool IsDone()
	{
		if (targetPlayer != null)
		{
			return Time.timeAsDouble - lastSeenTargetTime >= (double)giveUpDelay;
		}
		return true;
	}

	protected override void OnThink(float dt)
	{
		GRPlayer gRPlayer = GRPlayer.Get(targetPlayer);
		if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
		{
			UnityEngine.Vector3 position = gRPlayer.transform.position;
			position += GetMoveTargetOffset(position, entity);
			if (lineOfSight.HasLineOfSight(head.position, position))
			{
				lastSeenTargetTime = Time.timeAsDouble;
			}
			if (!((float)(Time.timeAsDouble - lastSeenTargetTime) > loseVisibilityDelay))
			{
				lastSeenTargetPosition = position;
			}
		}
		agent.RequestDestination(lastSeenTargetPosition);
	}

	protected override void OnUpdateShared(float dt)
	{
		GameAgent.UpdateFacing(root, agent.navAgent, targetPlayer, maxTurnSpeed);
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
		this.targetPlayer = targetPlayer;
	}

	public static UnityEngine.Vector3 GetMoveTargetOffset(UnityEngine.Vector3 targetPos, GameEntity attackingEntity)
	{
		int index = attackingEntity.id.index % targetOffsets.Count;
		return targetOffsets[index];
	}
}
[Serializable]
public class GRAbilityStagger : GRAbilityBase
{
	private float duration;

	public List<AnimationData> animData;

	private int lastAnimIndex = -1;

	private string animNameString;

	public GRAbilityInterpolatedMovement staggerMovement;

	private float stunTime;

	public void SetStunTime(float time)
	{
		stunTime = time;
	}

	public void SetStaggerVelocity(UnityEngine.Vector3 vel)
	{
		float magnitude = vel.magnitude;
		if (magnitude > 0f)
		{
			UnityEngine.Vector3 vector = vel / magnitude;
			vector.y = 0f;
			vel = vector * magnitude;
		}
		staggerMovement.InitFromVelocityAndDuration(vel, duration);
	}

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		staggerMovement.Setup(root);
		staggerMovement.interpolationType = GRAbilityInterpolatedMovement.InterpType.EaseOut;
	}

	protected override void OnStart()
	{
		if (animData.Count > 0)
		{
			lastAnimIndex = AbilityHelperFunctions.RandomRangeUnique(0, animData.Count, lastAnimIndex);
			duration = animData[lastAnimIndex].duration + stunTime;
			PlayAnim(animData[lastAnimIndex].animName, 0.1f, animData[lastAnimIndex].speed);
			animNameString = animData[lastAnimIndex].animName;
		}
		else
		{
			duration = 0.5f + stunTime;
		}
		agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: true);
		staggerMovement.InitFromVelocityAndDuration(staggerMovement.velocity, duration);
		staggerMovement.Start();
	}

	protected override void OnStop()
	{
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: false);
	}

	public override bool IsDone()
	{
		return staggerMovement.IsDone();
	}

	protected override void OnUpdateShared(float dt)
	{
		staggerMovement.Update(dt);
	}

	public string GetAnimName()
	{
		return animNameString;
	}
}
[Serializable]
public class GRAbilityDie : GRAbilityBase
{
	public float delayDeath;

	public float delayRespawn = -1f;

	public List<Renderer> hideWhenDead;

	public List<Collider> disableCollidersWhenDead;

	public bool disableAllCollidersWhenDead;

	public bool disableAllRenderersWhenDead;

	public GameObject fxDeath;

	public AbilitySound soundDeath;

	public AbilitySound soundOnHide;

	public float destroyDelay = 3f;

	public bool doKnockback = true;

	public GRBreakableItemSpawnConfig lootTable;

	public bool spawnOnGround;

	public LayerMask groundLayerMask;

	public Transform lootSpawnMarker;

	public List<AnimationData> animData;

	private int instigatingActorNumber;

	private bool isDead;

	private float totalDeathDelay;

	public GRAbilityInterpolatedMovement staggerMovement;

	public GameAbilityEvents events;

	private bool reported;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		if (disableAllCollidersWhenDead)
		{
			agent.GetComponentsInChildren(disableCollidersWhenDead);
		}
		if (disableAllRenderersWhenDead)
		{
			agent.GetComponentsInChildren(hideWhenDead);
		}
		Disable(disableCollidersWhenDead, disable: false);
		staggerMovement.Setup(root);
	}

	protected override void OnStart()
	{
		totalDeathDelay = delayDeath;
		if (animData.Count > 0)
		{
			int index = UnityEngine.Random.Range(0, animData.Count);
			totalDeathDelay += animData[index].duration;
			staggerMovement.InitFromVelocityAndDuration(staggerMovement.velocity, totalDeathDelay);
			PlayAnim(animData[index].animName, 0.1f, animData[index].speed);
		}
		agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: true);
		isDead = false;
		if (doKnockback)
		{
			staggerMovement.Start();
		}
		soundDeath.soundSelectMode = AbilitySound.SoundSelectMode.Random;
		soundOnHide.soundSelectMode = AbilitySound.SoundSelectMode.Random;
		soundDeath.Play(null);
		Disable(disableCollidersWhenDead, disable: true);
		if (fxDeath != null)
		{
			fxDeath.SetActive(value: false);
		}
		events.Reset();
		events.OnAbilityStart(GetAbilityTime(Time.timeAsDouble), audioSource);
	}

	protected override void OnStop()
	{
		staggerMovement.Stop();
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: false);
		Hide(hideWhenDead, hide: false);
		Disable(disableCollidersWhenDead, disable: false);
		events.OnAbilityStop(GetAbilityTime(Time.timeAsDouble), audioSource);
	}

	public void SetStaggerVelocity(UnityEngine.Vector3 vel)
	{
		float magnitude = vel.magnitude;
		if (magnitude > 0f)
		{
			UnityEngine.Vector3 vector = vel / magnitude;
			vector.y = 0f;
			vel = vector * magnitude;
		}
		staggerMovement.InitFromVelocityAndDuration(vel, totalDeathDelay);
	}

	public void SetInstigatingPlayerIndex(int actorNumber)
	{
		UnityEngine.Debug.Log($"SetInstigatingPlayerIndex {actorNumber}");
		instigatingActorNumber = actorNumber;
	}

	private void Die()
	{
		soundOnHide.Play(null);
		if (fxDeath != null)
		{
			fxDeath.SetActive(value: false);
			fxDeath.SetActive(value: true);
		}
		Hide(hideWhenDead, hide: true);
		Disable(disableCollidersWhenDead, disable: true);
		GameEntity gameEntity = agent.entity;
		if (lootTable != null && gameEntity.IsAuthority() && lootTable.TryForRandomItem(gameEntity, out var gameEntity2))
		{
			Transform transform = lootSpawnMarker;
			if (transform == null)
			{
				transform = agent.transform;
			}
			UnityEngine.Vector3 vector = transform.position;
			if (transform == null)
			{
				vector.y += 0.33f;
			}
			if (spawnOnGround && Physics.Raycast(new Ray(vector + UnityEngine.Vector3.up * 0.5f, -UnityEngine.Vector3.up), out var hitInfo, 5f, groundLayerMask.value, QueryTriggerInteraction.Ignore))
			{
				vector = hitInfo.point;
			}
			gameEntity.manager.RequestCreateItem(gameEntity2.gameObject.name.GetStaticHash(), vector, transform.rotation, 0L);
		}
		GREnemy component = gameEntity.GetComponent<GREnemy>();
		if (component != null && component.damageFlash != null)
		{
			component.damageFlash.Play();
		}
	}

	public void DestroySelf()
	{
		UnityEngine.Debug.Log("DESTROY SELF");
		ReportDeathStat();
		if (agent.entity.IsAuthority())
		{
			agent.entity.manager.RequestDestroyItem(agent.entity.id);
		}
	}

	public void ReportDeathStat()
	{
		if (!reported)
		{
			reported = true;
			GameEntity gameEntity = agent.entity;
			GRPlayer gRPlayer = GRPlayer.Get(instigatingActorNumber);
			if (gRPlayer != null)
			{
				gRPlayer.IncrementSynchronizedSessionStat(GRPlayer.SynchronizedSessionStat.Kills, 1f);
			}
			GhostReactor.instance.shiftManager.shiftStats.IncrementEnemyKills(gameEntity.GetEnemyType());
		}
	}

	public override bool IsDone()
	{
		return false;
	}

	protected override void OnUpdateShared(float dt)
	{
		if (startTime >= 0.0)
		{
			if (doKnockback)
			{
				staggerMovement.Update(dt);
			}
			double num = Time.timeAsDouble - startTime;
			if (!isDead && num > (double)totalDeathDelay)
			{
				isDead = true;
				Die();
			}
			else if (isDead && num > (double)(totalDeathDelay + destroyDelay))
			{
				GhostReactorManager.Get(entity).OnAbilityDie(entity, delayRespawn);
				DestroySelf();
				startTime = -1.0;
			}
			events.TryPlay((float)num, audioSource);
		}
	}

	public static void Hide(List<Renderer> renderers, bool hide)
	{
		if (renderers == null)
		{
			return;
		}
		for (int i = 0; i < renderers.Count; i++)
		{
			if (renderers[i] != null)
			{
				renderers[i].enabled = !hide;
			}
		}
	}

	public static void Disable(List<Collider> colliders, bool disable)
	{
		if (colliders == null)
		{
			return;
		}
		for (int i = 0; i < colliders.Count; i++)
		{
			if (colliders[i] != null)
			{
				colliders[i].enabled = !disable;
			}
		}
	}
}
[Serializable]
public class GRAbilityWander : GRAbilityBase
{
	public GRAbilityMoveToTarget moveAbility;

	private static UnityEngine.Quaternion[] rotations = new UnityEngine.Quaternion[8]
	{
		UnityEngine.Quaternion.Euler(0f, 0f, 0f),
		UnityEngine.Quaternion.Euler(0f, 45f, 0f),
		UnityEngine.Quaternion.Euler(0f, -45f, 0f),
		UnityEngine.Quaternion.Euler(0f, 90f, 0f),
		UnityEngine.Quaternion.Euler(0f, -90f, 0f),
		UnityEngine.Quaternion.Euler(0f, 135f, 0f),
		UnityEngine.Quaternion.Euler(0f, -135f, 0f),
		UnityEngine.Quaternion.Euler(0f, 180f, 0f)
	};

	private static float[] rotationWeight = new float[8] { 1f, 0.75f, 0.75f, 0.5f, 0.5f, 0.2f, 0.2f, 0.2f };

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		moveAbility.Setup(agent, anim, audioSource, root, head, lineOfSight);
	}

	protected override void OnStart()
	{
		moveAbility.Start();
		UnityEngine.Vector3 targetPos = PickRandomDestination();
		moveAbility.SetTargetPos(targetPos);
	}

	protected override void OnStop()
	{
		moveAbility.Stop();
	}

	public override bool IsDone()
	{
		return false;
	}

	protected override void OnThink(float dt)
	{
		if (moveAbility.IsDone())
		{
			UnityEngine.Vector3 targetPos = PickRandomDestination();
			moveAbility.SetTargetPos(targetPos);
		}
	}

	private UnityEngine.Vector3 PickRandomDestination()
	{
		UnityEngine.Vector3 position = agent.transform.position;
		if (NavMesh.SamplePosition(position, out var hit, 1f, walkableArea))
		{
			UnityEngine.Vector3 position2 = hit.position;
			UnityEngine.Vector3 forward = agent.transform.forward;
			float num = 0f;
			for (int i = 0; i < rotations.Length; i++)
			{
				UnityEngine.Vector3 vector = rotations[i] * forward;
				float num2 = 8f;
				if (NavMesh.Raycast(position2, position2 + vector * num2, out hit, walkableArea))
				{
					num2 = hit.distance * 0.95f;
				}
				float num3 = num2 * rotationWeight[i];
				if (num3 > num && NavMesh.SamplePosition(position2 + vector * num2, out hit, 1f, walkableArea))
				{
					num = num3;
					position = hit.position;
				}
			}
		}
		return position;
	}

	protected override void OnUpdateAuthority(float dt)
	{
		moveAbility.UpdateAuthority(dt);
	}

	protected override void OnUpdateRemote(float dt)
	{
		moveAbility.UpdateRemote(dt);
	}
}
