[Serializable]
public class GRAbilityKeepDistance : GRAbilityBase
{
	private NavMeshAgent navMeshAgent;

	private Transform target;

	public GRAbilityMoveToTarget moveAbility;

	public string idleAnimName;

	public AbilitySound idleSound;

	public float minBackupSpaceRequired = 0.5f;

	public float maxDistanceFromTarget = -1f;

	private bool defaultUpdateRotation;

	private static UnityEngine.Quaternion[] rotations = new UnityEngine.Quaternion[10]
	{
		UnityEngine.Quaternion.Euler(0f, 0f, 0f),
		UnityEngine.Quaternion.Euler(0f, 30f, 0f),
		UnityEngine.Quaternion.Euler(0f, -30f, 0f),
		UnityEngine.Quaternion.Euler(0f, 60f, 0f),
		UnityEngine.Quaternion.Euler(0f, -60f, 0f),
		UnityEngine.Quaternion.Euler(0f, 90f, 0f),
		UnityEngine.Quaternion.Euler(0f, -90f, 0f),
		UnityEngine.Quaternion.Euler(0f, 135f, 0f),
		UnityEngine.Quaternion.Euler(0f, -135f, 0f),
		UnityEngine.Quaternion.Euler(0f, 180f, 0f)
	};

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		navMeshAgent = agent.GetComponent<NavMeshAgent>();
		moveAbility.Setup(agent, anim, audioSource, root, head, lineOfSight);
		if ((bool)attributes && moveAbility.moveSpeed == 0f)
		{
			moveAbility.moveSpeed = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.BackupSpeed);
		}
	}

	protected override void OnStart()
	{
		if (target != null)
		{
			UnityEngine.Vector3 vector = agent.transform.position - target.position;
			if (maxDistanceFromTarget > 0f && vector.magnitude > maxDistanceFromTarget)
			{
				agent.SetStopped(stopMovement: true);
				PlayAnim(idleAnimName, 0.5f, 1f);
				idleSound.Play(null);
			}
			else
			{
				moveAbility.Start();
			}
		}
		else
		{
			moveAbility.Start();
		}
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		UnityEngine.Vector3 targetPos = PickBackupDestination();
		moveAbility.SetTargetPos(targetPos);
		if (navMeshAgent != null)
		{
			defaultUpdateRotation = navMeshAgent.updateRotation;
			navMeshAgent.updateRotation = false;
		}
	}

	protected override void OnStop()
	{
		moveAbility.Stop();
		idleSound.Stop();
		if (navMeshAgent != null)
		{
			navMeshAgent.updateRotation = defaultUpdateRotation;
		}
		agent.SetStopped(stopMovement: false);
	}

	public override bool IsDone()
	{
		return false;
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
		target = null;
		if (targetPlayer != null)
		{
			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
				moveAbility.SetLookAtTarget(target);
			}
		}
	}

	protected override void OnThink(float dt)
	{
		UnityEngine.Vector3 vector = agent.transform.position - target.position;
		if (moveAbility.IsDone())
		{
			if (maxDistanceFromTarget < 0f || vector.magnitude < maxDistanceFromTarget)
			{
				if (navMeshAgent != null && navMeshAgent.isOnNavMesh && navMeshAgent.isStopped)
				{
					idleSound.Stop();
					moveAbility.Start();
				}
				UnityEngine.Vector3 targetPos = PickBackupDestination();
				moveAbility.SetTargetPos(targetPos);
			}
		}
		else if (maxDistanceFromTarget > 0f && vector.magnitude > maxDistanceFromTarget)
		{
			moveAbility.SetTargetPos(root.position);
			moveAbility.Stop();
			agent.SetStopped(stopMovement: true);
			PlayAnim(idleAnimName, 0.5f, 1f);
			idleSound.Play(null);
		}
	}

	private UnityEngine.Vector3 PickBackupDestination()
	{
		UnityEngine.Vector3 position = agent.transform.position;
		if (target == null)
		{
			return position;
		}
		if (NavMesh.SamplePosition(position, out var hit, 1f, walkableArea))
		{
			UnityEngine.Vector3 position2 = hit.position;
			UnityEngine.Vector3 vector = agent.transform.position - target.position;
			vector.y = 0f;
			UnityEngine.Vector3 normalized = vector.normalized;
			for (int i = 0; i < rotations.Length; i++)
			{
				UnityEngine.Vector3 vector2 = rotations[i] * normalized;
				float num = 2f;
				UnityEngine.Vector3 vector3 = position2 + vector2 * num;
				if (NavMesh.Raycast(position2, vector3, out var hit2, walkableArea))
				{
					if (hit2.distance < minBackupSpaceRequired)
					{
						continue;
					}
					vector3 = hit2.position;
				}
				if (NavMesh.SamplePosition(vector3, out var hit3, 1f, walkableArea))
				{
					UnityEngine.Vector3 position3 = hit3.position;
					UnityEngine.Vector3 vector4 = position3 - target.position;
					vector4.y = 0f;
					if (vector4.sqrMagnitude > vector.sqrMagnitude)
					{
						return position3;
					}
				}
			}
		}
		return position;
	}

	protected override void OnUpdateShared(float dt)
	{
		if (GhostReactorManager.entityDebugEnabled)
		{
			DebugUtil.DrawLine(root.position, moveAbility.GetTargetPos(), Color.magenta);
		}
	}

	protected override void OnUpdateAuthority(float dt)
	{
		moveAbility.UpdateAuthority(dt);
	}

	protected override void OnUpdateRemote(float dt)
	{
		moveAbility.UpdateRemote(dt);
	}
}
[Serializable]
public class GRAbilityPatrol : GRAbilityBase
{
	private NavMeshAgent navMeshAgent;

	public GRAbilityMoveToTarget moveAbility;

	private GRPatrolPath patrolPath;

	public double lastStateChange;

	public float ambientSoundVolume = 0.5f;

	public double ambientSoundDelayMin = 5.0;

	public double ambientSoundDelayMax = 10.0;

	public AudioClip[] ambientPatrolSounds;

	private double lastPartrolAmbientSoundTime;

	private double nextPatrolGroanTime;

	private Unity.Mathematics.Random patrolGroanSoundDelayRandom;

	private Unity.Mathematics.Random patrolGroanSoundRandom;

	[Unity.XR.CoreUtils.ReadOnly]
	public int nextPatrolNode;

	public bool HasValidPatrolPath()
	{
		if (patrolPath != null)
		{
			return patrolPath.patrolNodes.Count > 1;
		}
		return false;
	}

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		moveAbility.Setup(agent, anim, audioSource, root, head, lineOfSight);
		if ((bool)attributes && moveAbility.moveSpeed == 0f)
		{
			moveAbility.moveSpeed = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.PatrolSpeed);
		}
		navMeshAgent = agent.GetComponent<NavMeshAgent>();
		InitializeRandoms();
		nextPatrolNode = 0;
	}

	private void InitializeRandoms()
	{
		patrolGroanSoundDelayRandom = new Unity.Mathematics.Random((uint)entity.GetNetId());
		patrolGroanSoundRandom = new Unity.Mathematics.Random((uint)entity.GetNetId());
	}

	protected override void OnStart()
	{
		moveAbility.Start();
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		if (patrolPath != null)
		{
			moveAbility.SetTarget(patrolPath.patrolNodes[nextPatrolNode]);
		}
		else
		{
			UnityEngine.Debug.LogError("Starting patrol ability with no patrol path");
		}
		CalculateNextPatrolGroan();
	}

	protected override void OnStop()
	{
		moveAbility.Stop();
	}

	public override bool IsDone()
	{
		return false;
	}

	public void SetPatrolPath(GRPatrolPath patrolPath)
	{
		this.patrolPath = patrolPath;
	}

	public GRPatrolPath GetPatrolPath()
	{
		return patrolPath;
	}

	public void SetNextPatrolNode(int nextPatrolNode)
	{
		this.nextPatrolNode = nextPatrolNode;
	}

	public void CalculateNextPatrolGroan()
	{
		nextPatrolGroanTime = patrolGroanSoundDelayRandom.NextDouble(ambientSoundDelayMin, ambientSoundDelayMax) + PhotonNetwork.Time;
	}

	private void PlayPatrolGroan()
	{
		audioSource.clip = ambientPatrolSounds[patrolGroanSoundRandom.NextInt(ambientPatrolSounds.Length - 1)];
		audioSource.volume = ambientSoundVolume;
		audioSource.Play();
		CalculateNextPatrolGroan();
	}

	protected override void OnUpdateAuthority(float dt)
	{
		moveAbility.UpdateAuthority(dt);
		if (GhostReactorManager.entityDebugEnabled)
		{
			DebugUtil.DrawLine(root.position, moveAbility.GetTargetPos(), Color.green);
		}
		if (moveAbility.IsDone())
		{
			nextPatrolNode = (nextPatrolNode + 1) % patrolPath.patrolNodes.Count;
			moveAbility.SetTarget(patrolPath.patrolNodes[nextPatrolNode]);
		}
		if (PhotonNetwork.Time >= nextPatrolGroanTime)
		{
			PlayPatrolGroan();
		}
	}

	protected override void OnUpdateRemote(float dt)
	{
		moveAbility.SetTarget(null);
		moveAbility.SetTargetPos(agent.navAgent.destination);
		moveAbility.UpdateRemote(dt);
		if (GhostReactorManager.entityDebugEnabled)
		{
			DebugUtil.DrawLine(root.position, moveAbility.GetTargetPos(), Color.green);
		}
		if (PhotonNetwork.Time >= nextPatrolGroanTime)
		{
			PlayPatrolGroan();
		}
	}
}
