[Serializable]
public class GRAbilityAttackSwipe : GRAbilityBase
{
	private enum State
	{
		Tell,
		Attack,
		FollowThrough,
		Done
	}

	public float duration;

	public float tellDuration;

	public float attackDuration;

	public float coolDown;

	public float attackMoveSpeed;

	public List<AnimationData> animData;

	public AbilitySound soundAttack;

	private State state;

	public float maxTurnSpeed;

	public GameObject damageTrigger;

	private Transform target;

	private string animNameString;

	private int lastAnimIndex = -1;

	public UnityEngine.Vector3 targetPos;

	public UnityEngine.Vector3 initialPos;

	public UnityEngine.Vector3 initialVel;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		target = null;
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	protected override void OnStart()
	{
		if (animData.Count > 0)
		{
			lastAnimIndex = AbilityHelperFunctions.RandomRangeUnique(0, animData.Count, lastAnimIndex);
			duration = animData[lastAnimIndex].duration;
			PlayAnim(animData[lastAnimIndex].animName, 0.1f, animData[lastAnimIndex].speed);
			animNameString = animData[lastAnimIndex].animName;
		}
		else
		{
			duration = 0.5f;
		}
		soundAttack.soundSelectMode = AbilitySound.SoundSelectMode.Random;
		soundAttack.Play(null);
		agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: true);
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
		state = State.Tell;
	}

	protected override void OnStop()
	{
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: false);
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	public override bool IsDone()
	{
		return state == State.Done;
	}

	protected override void OnUpdateShared(float dt)
	{
		float num = (float)(Time.timeAsDouble - startTime);
		switch (state)
		{
		case State.Tell:
			targetPos = root.position + root.transform.forward;
			if (target != null)
			{
				targetPos = target.position;
			}
			GameAgent.UpdateFacingTarget(root, agent.navAgent, target, maxTurnSpeed);
			if (num > tellDuration)
			{
				state = State.Attack;
				if (damageTrigger != null)
				{
					damageTrigger.SetActive(value: true);
				}
				initialPos = root.position;
				initialVel = (targetPos - initialPos).normalized * attackMoveSpeed;
			}
			break;
		case State.Attack:
		{
			float num2 = num - tellDuration;
			UnityEngine.Vector3 sourcePosition = initialPos + initialVel * num2;
			if (NavMesh.SamplePosition(sourcePosition, out var hit, 0.5f, walkableArea))
			{
				sourcePosition = hit.position;
				if (NavMesh.Raycast(initialPos, sourcePosition, out hit, walkableArea))
				{
					sourcePosition = hit.position;
				}
				root.position = sourcePosition;
			}
			if (num > tellDuration + attackDuration)
			{
				if (damageTrigger != null)
				{
					damageTrigger.SetActive(value: false);
				}
				state = State.FollowThrough;
			}
			break;
		}
		case State.FollowThrough:
			if (num >= duration)
			{
				state = State.Done;
			}
			break;
		}
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
		target = null;
		if (targetPlayer != null)
		{
			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
			}
		}
	}

	public string GetAnimName()
	{
		return animNameString;
	}

	public override bool IsCoolDownOver()
	{
		return IsCoolDownOver(coolDown);
	}
}
[Serializable]
public class GRAbilityAttackSimple : GRAbilityBase
{
	private enum State
	{
		Tell,
		Attack,
		FollowThrough,
		Done
	}

	public float duration;

	public float tellDuration;

	public float attackDuration;

	public float coolDown;

	public float range;

	public bool allowMovement;

	public AnimationData tellAnimData;

	public AnimationData attackAnimData;

	public AnimationData outroAnimData;

	public AbilitySound soundTell;

	public AbilitySound soundAttack;

	public AbilitySound soundOutro;

	private float timeMult = 1f;

	private State state;

	public float maxTurnSpeed;

	public List<GameObject> damageTrigger;

	private string animNameString;

	public GameAbilityEvents events;

	public bool adjustByAnimationSpeed;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		EnableList(damageTrigger, enable: false);
	}

	protected override void OnStart()
	{
		if ((double)(tellDuration * timeMult) > 0.0)
		{
			PlayState(State.Tell, tellAnimData, soundTell, damageEnabled: false);
		}
		else
		{
			PlayState(State.Attack, attackAnimData, soundAttack, damageEnabled: true);
		}
		if (!allowMovement)
		{
			agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
			agent.SetDisableNetworkSync(disable: true);
		}
		events.Reset();
		events.OnAbilityStart(GetAbilityTime(Time.timeAsDouble), audioSource);
	}

	protected override void OnStop()
	{
		if (!allowMovement)
		{
			agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
			agent.SetDisableNetworkSync(disable: false);
		}
		EnableList(damageTrigger, enable: false);
		events.OnAbilityStop(GetAbilityTime(Time.timeAsDouble), audioSource);
	}

	private void PlayState(State newState, AnimationData animData, AbilitySound sound, bool damageEnabled)
	{
		if (!string.IsNullOrEmpty(animData.animName))
		{
			PlayAnim(animData.animName, 0.1f, animData.speed);
			animNameString = animData.animName;
			timeMult = ((adjustByAnimationSpeed && !Mathf.Approximately(animData.speed, 0f)) ? (1f / animData.speed) : 1f);
		}
		sound.soundSelectMode = AbilitySound.SoundSelectMode.Random;
		sound.Play(null);
		EnableList(damageTrigger, damageEnabled);
		state = newState;
	}

	public override bool IsDone()
	{
		return state == State.Done;
	}

	protected override void OnUpdateShared(float dt)
	{
		float num = (float)(Time.timeAsDouble - startTime);
		switch (state)
		{
		case State.Tell:
			if (num > tellDuration * timeMult)
			{
				PlayState(State.Attack, attackAnimData, soundAttack, damageEnabled: true);
			}
			break;
		case State.Attack:
			if (num > (tellDuration + attackDuration) * timeMult)
			{
				PlayState(State.FollowThrough, outroAnimData, soundOutro, damageEnabled: false);
			}
			break;
		case State.FollowThrough:
			if (num >= duration * timeMult)
			{
				state = State.Done;
			}
			break;
		}
		events.TryPlay(num / timeMult, audioSource);
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
	}

	public string GetAnimName()
	{
		return animNameString;
	}

	public void EnableList(List<GameObject> objs, bool enable)
	{
		for (int i = 0; i < objs.Count; i++)
		{
			if (objs[i] != null)
			{
				objs[i].SetActive(enable);
			}
		}
	}

	public override bool IsCoolDownOver()
	{
		return IsCoolDownOver(coolDown);
	}

	public override float GetRange()
	{
		return range;
	}
}
[Serializable]
public class GRAbilityAttackLatchOn : GRAbilityBase
{
	public float duration;

	public float attackMoveSpeed;

	public float tellDuration;

	public float tellMoveSpeed;

	public string animName;

	public float animSpeed;

	public float maxTurnSpeed;

	public Transform target;

	public GameObject damageTrigger;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		target = null;
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	protected override void OnStart()
	{
		PlayAnim(animName, 0.1f, animSpeed);
		agent.SetSpeed(tellMoveSpeed);
		startTime = Time.timeAsDouble;
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	protected override void OnStop()
	{
		agent.transform.SetParent(null);
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	public override bool IsDone()
	{
		return Time.timeAsDouble - startTime >= (double)duration;
	}

	protected override void OnUpdateAuthority(float dt)
	{
		UpdateNavSpeed();
		GameAgent.UpdateFacingTarget(root, agent.navAgent, target, maxTurnSpeed);
	}

	protected override void OnUpdateRemote(float dt)
	{
		UpdateNavSpeed();
	}

	private void UpdateNavSpeed()
	{
		if (Time.timeAsDouble - startTime > (double)tellDuration)
		{
			agent.SetSpeed(attackMoveSpeed);
			agent.SetVelocity(agent.navAgent.velocity.normalized * attackMoveSpeed);
			if (damageTrigger != null)
			{
				damageTrigger.SetActive(value: true);
			}
		}
	}

