			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
				agent.transform.SetParent(gRPlayer.attachEnemy);
				agent.transform.localPosition = UnityEngine.Vector3.zero;
				agent.transform.localRotation = UnityEngine.Quaternion.identity;
				agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
			}
		}
	}
}
[Serializable]
public class GRAbilityAttackJump : GRAbilityBase
{
	private enum State
	{
		Tell,
		Jump,
		Return,
		Done
	}

	public float duration;

	public float jumpTime;

	public float attackLandTime;

	public float attackReturnTime;

	public bool doReturnPhase = true;

	public float jumpLengthScale = 1f;

	public string animName;

	public float animSpeed;

	public float maxTurnSpeed;

	public string jumpAnimName;

	public AbilitySound jumpSound;

	public GameObject damageTrigger;

	private Transform target;

	private State state;

	public UnityEngine.Vector3 targetPos;

	public UnityEngine.Vector3 initialPos;

	public UnityEngine.Vector3 initialVel;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		target = null;
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	protected override void OnStart()
	{
		PlayAnim(animName, 0.1f, animSpeed);
		startTime = Time.timeAsDouble;
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
		agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: true);
		state = State.Tell;
	}

	protected override void OnStop()
	{
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: false);
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	public override bool IsDone()
	{
		return Time.timeAsDouble - startTime >= (double)duration;
	}

	protected override void OnUpdateShared(float dt)
	{
		double num = (double)(float)Time.timeAsDouble - startTime;
		switch (state)
		{
		case State.Tell:
			if (num > (double)jumpTime)
			{
				targetPos = agent.transform.position + agent.transform.forward * 0.5f;
				if (target != null)
				{
					UnityEngine.Vector3 vector = target.transform.position - agent.transform.position;
					targetPos = agent.transform.position + vector * jumpLengthScale;
					targetPos.y = target.transform.position.y;
				}
				float b = attackLandTime - jumpTime;
				b = Mathf.Max(0.1f, b);
				initialPos = agent.transform.position;
				UnityEngine.Vector3 vector2 = targetPos - initialPos;
				float y = vector2.y;
				vector2.y = 0f;
				float num3 = b;
				float y2 = 0f;
				if (num3 > 0f)
				{
					y2 = (y - 0.5f * Physics.gravity.y * num3 * num3) / num3;
				}
				initialVel = vector2 / b;
				initialVel.y = y2;
				if (damageTrigger != null)
				{
					damageTrigger.SetActive(value: true);
				}
				PlayAnim(jumpAnimName, 0.1f, animSpeed);
				jumpSound.Play(null);
				state = State.Jump;
			}
			break;
		case State.Jump:
		{
			float num4 = (float)(num - (double)jumpTime);
			UnityEngine.Vector3 position2 = initialPos + initialVel * num4 + 0.5f * Physics.gravity * num4 * num4;
			root.position = position2;
			if (num > (double)attackLandTime)
			{
				if (damageTrigger != null)
				{
					damageTrigger.SetActive(value: false);
				}
				if (doReturnPhase)
				{
					float b2 = attackReturnTime - attackLandTime;
					b2 = Mathf.Max(0.1f, b2);
					UnityEngine.Vector3 vector3 = initialPos;
					initialPos = agent.transform.position;
					initialVel = (vector3 - initialPos) / b2;
					state = State.Return;
				}
				else
				{
					state = State.Done;
				}
			}
			break;
		}
		case State.Return:
		{
			float num2 = (float)(num - (double)attackLandTime);
			UnityEngine.Vector3 position = initialPos + initialVel * num2;
			root.position = position;
			if (num > (double)attackReturnTime)
			{
				state = State.Done;
			}
			break;
		}
		}
		GameAgent.UpdateFacingTarget(root, agent.navAgent, target, maxTurnSpeed);
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
		target = null;
		if (targetPlayer != null)
		{
			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
			}
		}
	}
}
[Serializable]
public class GRAbilityAttackLaser : GRAbilityBase
{
	private enum State
	{
		Tell,
		Attack,
		FollowThrough,
		Done
	}

	public float duration;

	public float tellDuration;

	public float attackDuration;

	public float coolDown;

	public float range;

	public float attackMoveSpeed;

	public bool doNotFaceTarget;

	public List<AnimationData> animData;

	public AbilitySound soundAttack;

	public float maxLaserRange;

	public Transform[] laserOrigins;

	public Monkeye_LazerFX tellLaserFx;

	public Monkeye_LazerFX laserFx;

	private State state;

	public float maxTurnSpeed;

	public GameObject damageTrigger;

	public CapsuleCollider damageCollider;

	private Transform target;

	private string animNameString;

	private int lastAnimIndex = -1;

	public UnityEngine.Vector3 targetPos;

	public UnityEngine.Vector3 initialPos;

	public UnityEngine.Vector3 initialVel;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
		target = null;
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
	}

	protected override void OnStart()
	{
		if (animData.Count > 0)
		{
			lastAnimIndex = AbilityHelperFunctions.RandomRangeUnique(0, animData.Count, lastAnimIndex);
			duration = animData[lastAnimIndex].duration;
			PlayAnim(animData[lastAnimIndex].animName, 0.1f, animData[lastAnimIndex].speed);
			animNameString = animData[lastAnimIndex].animName;
		}
		else
		{
			duration = 0.5f;
		}
		soundAttack.soundSelectMode = AbilitySound.SoundSelectMode.Random;
		soundAttack.Play(null);
		agent.SetIsPathing(isPathing: false, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: true);
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
		state = State.Tell;
	}

	protected override void OnStop()
	{
		agent.SetIsPathing(isPathing: true, ignoreRigiBody: true);
		agent.SetDisableNetworkSync(disable: false);
		if (damageTrigger != null)
		{
			damageTrigger.SetActive(value: false);
		}
		if (laserFx != null)
		{
			laserFx.DisableLazer();
		}
		if (tellLaserFx != null)
		{
			tellLaserFx.DisableLazer();
		}
	}

	public override bool IsDone()
	{
		return state == State.Done;
	}

	protected override void OnUpdateShared(float dt)
	{
		float num = (float)(Time.timeAsDouble - startTime);
		switch (state)
		{
		case State.Tell:
		{
			targetPos = root.position + root.transform.forward;
			if (target != null)
			{
				targetPos = target.position;
			}
			UnityEngine.Vector3 position = head.position;
			UnityEngine.Vector3 vector = targetPos - position;
			float num2 = vector.magnitude;
			if (num2 > 0f)
			{
				UnityEngine.Vector3 vector2 = vector / num2;
				num2 = Mathf.Min(maxLaserRange, num2);
				targetPos = position + vector2 * num2;
			}
			if (!doNotFaceTarget)
			{
				GameAgent.UpdateFacingTarget(root, agent.navAgent, target, maxTurnSpeed);
			}
			if (num > tellDuration)
			{
				state = State.Attack;
				if (damageCollider != null && laserOrigins.Length != 0)
				{
					damageCollider.transform.position = (position + targetPos) / 2f;
					damageCollider.height = num2;
					damageCollider.direction = 2;
					if (num2 > 0f)
					{
						damageCollider.transform.rotation = UnityEngine.Quaternion.LookRotation(vector / num2);
					}
				}
				if (damageTrigger != null)
				{
					damageTrigger.SetActive(value: true);
				}
				if (tellLaserFx != null)
				{
					tellLaserFx.DisableLazer();
				}
				if (laserFx != null && target != null)
				{
					GamePlayer component = target.GetComponent<GamePlayer>();
					if (component != null && component.rig != null)
					{
						laserFx.EnableLazer(laserOrigins, targetPos);
					}
				}
				initialPos = root.position;
				initialVel = (targetPos - initialPos).normalized * attackMoveSpeed;
			}
			else if (tellLaserFx != null)
			{
				tellLaserFx.EnableLazer(laserOrigins, targetPos);
			}
			break;
		}
		case State.Attack:
		{
			float num3 = num - tellDuration;
			UnityEngine.Vector3 sourcePosition = initialPos + initialVel * num3;
			if (NavMesh.SamplePosition(sourcePosition, out var hit, 0.5f, walkableArea))
			{
				sourcePosition = hit.position;
				if (NavMesh.Raycast(initialPos, sourcePosition, out hit, walkableArea))
				{
					sourcePosition = hit.position;
				}
				root.position = sourcePosition;
			}
			if (num > tellDuration + attackDuration)
			{
				if (damageTrigger != null)
				{
					damageTrigger.SetActive(value: false);
				}
				if (laserFx != null)
				{
					laserFx.DisableLazer();
				}
				state = State.FollowThrough;
			}
			break;
		}
		case State.FollowThrough:
			if (num >= duration)
			{
				state = State.Done;
			}
			break;
		}
	}

	public void SetTargetPlayer(NetPlayer targetPlayer)
	{
		target = null;
		if (targetPlayer != null)
		{
			GRPlayer gRPlayer = GRPlayer.Get(targetPlayer.ActorNumber);
			if (gRPlayer != null && gRPlayer.State == GRPlayer.GRPlayerState.Alive)
			{
				target = gRPlayer.transform;
			}
		}
	}

	public string GetAnimName()
	{
		return animNameString;
	}

	public override bool IsCoolDownOver()
	{
		return IsCoolDownOver(coolDown);
	}

	public override float GetRange()
	{
		return range;
	}
}
[Serializable]
public class GRAbilitySummon : GRAbilityBase
{
	[Serializable]
	public class SummonMarker
	{
		public Transform transform;
	}

	private enum State
	{
		Charge,
		Spawn,
		Done
	}

	private int lastAnimIndex = -1;

	public GameEntity entityPrefabToSpawn;

	public List<AnimationData> animData;

	private float animSpeed = 1f;

	public float coolDown;

	public float range;

	public float chargeTime = 3f;

	public float duration = 3f;

	public float desiredSpawnDistance = 3f;

	public float minSpawnDistance = 1f;

	public float spawnHeight = 1f;

	public float summonConeAngle = 120f;

	private bool spawned;

	public AudioClip summonSpawnAudioClip;

	public GameObject fxStartSummon;

	public GameObject fxOnSpawn;

	public AbilitySound summonSound;

	private int spawnedCount;

	public Transform lookAtTarget;

	public List<SummonMarker> summonMarkers;

	private State state;

	public override void Setup(GameAgent agent, Animation anim, AudioSource audioSource, Transform root, Transform head, GRSenseLineOfSight lineOfSight)
	{
		base.Setup(agent, anim, audioSource, root, head, lineOfSight);
	}

	protected override void OnStart()
	{
		lastAnimIndex = AbilityHelperFunctions.RandomRangeUnique(0, animData.Count, lastAnimIndex);
		duration = animData[lastAnimIndex].duration;
		chargeTime = animData[lastAnimIndex].eventTime;
		PlayAnim(animData[lastAnimIndex].animName, 0.1f, animSpeed);
		state = State.Charge;
		summonSound.Play(audioSource);
		spawnedCount = 0;
		agent.SetStopped(stopMovement: true);
		agent.SetSpeed(1f);
		if (fxStartSummon != null)
		{
			fxStartSummon.SetActive(value: false);
			fxStartSummon.SetActive(value: true);
		}
	}

	protected override void OnStop()
	{
		lookAtTarget = null;
		agent.SetStopped(stopMovement: false);
	}

	public void SetLookAtTarget(Transform transform)
	{
		lookAtTarget = transform;
	}

	protected override void OnThink(float dt)
	{
		UpdateState(dt);
	}

	protected override void OnUpdateShared(float dt)
	{
		if (lookAtTarget != null)
		{
			GameAgent.UpdateFacingTarget(root, agent.navAgent, lookAtTarget, 360f);
		}
	}

	private void UpdateState(float dt)
	{
		double num = Time.timeAsDouble - startTime;
		switch (state)
		{
		case State.Charge:
			if (num > (double)chargeTime)
			{
				SetState(State.Spawn);
			}
			break;
		case State.Spawn:
			if (!spawned)
			{
				spawned = DoSpawn();
			}
			if (spawned && num > (double)duration)
			{
				SetState(State.Done);
				spawned = false;
			}
			break;
		case State.Done:
			break;
		}
	}

	private void SetState(State newState)
	{
		_ = state;
		state = newState;
		switch (newState)
		{
		}
	}

	private UnityEngine.Vector3? GetSpawnLocation()
	{
		if (summonMarkers != null && summonMarkers.Count > 0)
		{
			int index = UnityEngine.Random.Range(0, summonMarkers.Count);
			if (summonMarkers[index] != null)
			{
				return summonMarkers[index].transform.position;
			}
		}
		UnityEngine.Vector3 position = root.position;
		float num = UnityEngine.Random.Range((0f - summonConeAngle) / 2f, summonConeAngle / 2f);
		for (int i = 0; i < 5; i++)
		{
			UnityEngine.Vector3 vector = UnityEngine.Quaternion.Euler(0f, num, 0f) * root.forward;
			UnityEngine.Vector3 vector2 = position + vector * desiredSpawnDistance;
			if (NavMesh.Raycast(position, vector2, out var hit, walkableArea))
			{
				if (hit.distance < minSpawnDistance)
				{
					num += 15f;
					if (num > summonConeAngle / 2f)
					{
						summonConeAngle = (0f - summonConeAngle) / 2f;
					}
					continue;
				}
				vector2 = hit.position + UnityEngine.Vector3.up * spawnHeight;
			}
			if (!Physics.Raycast(vector2, UnityEngine.Vector3.down, out var hitInfo) || (object)hitInfo.collider.gameObject.GetComponent<GRHazardousMaterial>() == null)
			{
				return vector2;
			}
		}
		return null;
	}

	public bool ForceSpawn()
	{
		return DoSpawn();
	}

	private bool DoSpawn()
	{
		UnityEngine.Vector3? spawnLocation = GetSpawnLocation();
		if (spawnLocation.HasValue)
		{
			if (entity.IsAuthority())
			{
				UnityEngine.Quaternion identity = UnityEngine.Quaternion.identity;
				GhostReactorManager.Get(entity).gameEntityManager.RequestCreateItem(entityPrefabToSpawn.name.GetStaticHash(), spawnLocation.Value, identity, 0L, entity.id);
				spawnedCount++;
			}
			if (audioSource != null)
			{
				audioSource.PlayOneShot(summonSpawnAudioClip);
			}
			if (fxOnSpawn != null)
			{
				fxOnSpawn.SetActive(value: false);
				fxOnSpawn.SetActive(value: true);
			}
			return true;
		}
		return false;
	}

	public override bool IsDone()
	{
		return state == State.Done;
	}

	public override bool IsCoolDownOver()
	{
		return IsCoolDownOver(coolDown);
	}

	public override float GetRange()
	{
		return range;
	}
}
[Serializable]
public class GRAbilityAttackSimpleWander : GRAbilityBase
{
	public GRAbilityWander wander;

	public GRAbilityAttackSimple attack;

