public class GRAttributes : MonoBehaviour
{
	[Serializable]
	public struct GRAttributePair
	{
		public GRAttributeType type;

		public float value;
	}

	[SerializeField]
	private List<GRAttributePair> startingAttributes;

	[NonSerialized]
	private GRBonusSystem bonusSystem = new GRBonusSystem();

	public Dictionary<GRAttributeType, int> defaultAttributes = new Dictionary<GRAttributeType, int>();

	private void Awake()
	{
		foreach (GRAttributePair startingAttribute in startingAttributes)
		{
			defaultAttributes[startingAttribute.type] = (int)(startingAttribute.value * 100f);
		}
		bonusSystem.Init(this);
	}

	public bool HasBeenInitialized()
	{
		return bonusSystem.GetDefaultAttributes() != null;
	}

	public void AddAttribute(GRAttributeType type, float value)
	{
		defaultAttributes[type] = (int)(value * 100f);
	}

	public void AddBonus(GRBonusEntry entry)
	{
		bonusSystem.AddBonus(entry);
	}

	public void RemoveBonus(GRBonusEntry entry)
	{
		bonusSystem.RemoveBonus(entry);
	}

	public float CalculateFinalFloatValueForAttribute(GRAttributeType attributeType)
	{
		int num = bonusSystem.CalculateFinalValueForAttribute(attributeType);
		float result = 0f;
		if (num > 0)
		{
			result = (float)num / 100f;
		}
		return result;
	}

	public int CalculateFinalValueForAttribute(GRAttributeType attributeType)
	{
		int num = bonusSystem.CalculateFinalValueForAttribute(attributeType);
		if (num > 0)
		{
			num /= 100;
		}
		return num;
	}

	public bool HasValueForAttribute(GRAttributeType attributeType)
	{
		return bonusSystem.HasValueForAttribute(attributeType);
	}
}
public class GRBadge : MonoBehaviour, IGameEntityComponent
{
	public enum BadgeState
	{
		AtDispenser,
		WithPlayer
	}

	private const float RESTORE_BADGE_TO_DOCK_WINDOW = 60f;

	[SerializeField]
	private GameEntity gameEntity;

	[SerializeField]
	public TMP_Text playerName;

	[SerializeField]
	public TMP_Text playerTitle;

	[SerializeField]
	public TMP_Text playerLevel;

	[SerializeField]
	private MeshRenderer badgeMesh;

	[SerializeField]
	private AudioSource audioSource;

	[SerializeField]
	private float retractSpeed = 4f;

	[SerializeField]
	private AudioClip badgeAttachSound;

	[SerializeField]
	private float badgeAttachSoundVolume;

	[SerializeField]
	public int dispenserIndex;

	public int actorNr;

	private Coroutine retractCoroutine;

	private int lastRedeemedPoints = -1;

	public void OnEntityInit()
	{
		gameEntity.manager.ghostReactorManager.reactor.employeeBadges.LinkBadgeToDispenser(this, (int)gameEntity.createData);
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	private void OnDestroy()
	{
		GhostReactor ghostReactor = GhostReactor.Get(gameEntity);
		if (ghostReactor != null && ghostReactor.employeeBadges != null)
		{
			ghostReactor.employeeBadges.RemoveBadge(this);
		}
	}

	public void Setup(NetPlayer player, int index)
	{
		gameEntity.onlyGrabActorNumber = player.ActorNumber;
		dispenserIndex = index;
		actorNr = player.ActorNumber;
		GRPlayer gRPlayer = GRPlayer.Get(player.ActorNumber);
		bool flag = (int)gameEntity.GetState() == 1;
		if (player.IsLocal)
		{
			flag |= Time.timeAsDouble < gRPlayer.lastLeftWithBadgeAttachedTime + 60.0;
		}
		if (gRPlayer != null && flag)
		{
			base.transform.position = gRPlayer.badgeBodyAnchor.position;
			gRPlayer.AttachBadge(this);
		}
		RefreshText(player);
	}

	public void RefreshText(NetPlayer player)
	{
		playerName.text = player.SanitizedNickName;
		GRPlayer gRPlayer = GRPlayer.Get(player.ActorNumber);
		if (gRPlayer != null && lastRedeemedPoints != gRPlayer.CurrentProgression.redeemedPoints)
		{
			lastRedeemedPoints = gRPlayer.CurrentProgression.redeemedPoints;
			playerTitle.text = GhostReactorProgression.GetTitleName(gRPlayer.CurrentProgression.redeemedPoints);
			playerLevel.text = GhostReactorProgression.GetGrade(gRPlayer.CurrentProgression.redeemedPoints).ToString();
		}
	}

	public void Hide()
	{
		badgeMesh.enabled = false;
		playerName.gameObject.SetActive(value: false);
		playerTitle.gameObject.SetActive(value: false);
		playerLevel.gameObject.SetActive(value: false);
	}

	public void UnHide()
	{
		badgeMesh.enabled = true;
		playerName.gameObject.SetActive(value: true);
		playerTitle.gameObject.SetActive(value: true);
		playerLevel.gameObject.SetActive(value: true);
	}

	public bool IsAttachedToPlayer()
	{
		return (int)gameEntity.GetState() == 1;
	}

	public void StartRetracting()
	{
		gameEntity.RequestState(gameEntity.id, 1L);
		PlayAttachFx();
		if (retractCoroutine != null)
		{
			StopCoroutine(retractCoroutine);
		}
		retractCoroutine = StartCoroutine(RetractCoroutine());
	}

	private IEnumerator RetractCoroutine()
	{
		base.transform.localRotation = UnityEngine.Quaternion.identity;
		UnityEngine.Vector3 localPosition = base.transform.localPosition;
		for (float sqrMagnitude = localPosition.sqrMagnitude; sqrMagnitude > 1E-05f; sqrMagnitude = localPosition.sqrMagnitude)
		{
			localPosition = UnityEngine.Vector3.MoveTowards(localPosition, UnityEngine.Vector3.zero, retractSpeed * Time.deltaTime);
			base.transform.localPosition = localPosition;
			yield return null;
			localPosition = base.transform.localPosition;
		}
		base.transform.localPosition = UnityEngine.Vector3.zero;
	}

	private void PlayAttachFx()
	{
		if (audioSource != null)
		{
			audioSource.volume = badgeAttachSoundVolume;
			audioSource.clip = badgeAttachSound;
			audioSource.Play();
		}
	}
}
public class GRBarrierOverloadable : MonoBehaviour
{
	public enum State
	{
		Active,
		Destroyed
	}

	public GRTool tool;

	public GameEntity gameEntity;

	public AudioSource audioSource;

	public MeshRenderer meshRenderer;

	public Collider collider;

	private State state;

	private void OnEnable()
	{
		tool.OnEnergyChange += OnEnergyChange;
		gameEntity.OnStateChanged += OnEntityStateChanged;
	}

	private void OnEnergyChange(GRTool tool, int energyChange, GameEntityId chargingEntityId)
	{
		if (state == State.Active && tool.energy >= tool.GetEnergyMax())
		{
			SetState(State.Destroyed);
			if (gameEntity.IsAuthority())
			{
				gameEntity.RequestState(gameEntity.id, 1L);
			}
		}
	}

	private void OnEntityStateChanged(long prevState, long nextState)
	{
		if (!gameEntity.IsAuthority())
		{
			SetState((State)nextState);
		}
	}

	public void SetState(State newState)
	{
		if (state != newState)
		{
			state = newState;
			switch (state)
			{
			case State.Active:
				meshRenderer.enabled = true;
				collider.enabled = true;
				break;
			case State.Destroyed:
				audioSource.Play();
				meshRenderer.enabled = false;
				collider.enabled = false;
				break;
			}
		}
	}
}
public class GRBarrierSpectral : MonoBehaviour, IGameEntityComponent, IGameHittable
{
	public GameEntity entity;

	public MeshRenderer visualMesh;

	public Collider collider;

	public AudioSource audioSource;

	public AudioClip onDamageClip;

	public float onDamageVolume;

	public AudioClip onDestroyedClip;

	public float onDestroyedVolume;

	[SerializeField]
	private GameObject hitFx;

	[SerializeField]
	private GameObject destroyedFx;

	public int maxHealth = 3;

	[Unity.XR.CoreUtils.ReadOnly]
	public int health = 3;

	private int lastVisualUpdateHealth = -1;

	public void Awake()
	{
		hitFx.SetActive(value: false);
		destroyedFx.SetActive(value: false);
	}

	public void OnEntityInit()
	{
		entity.SetState(health);
		UnityEngine.Vector3 localScale = BitPackUtils.UnpackWorldPosFromNetwork(entity.createData);
		base.transform.localScale = localScale;
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long newState)
	{
		int nextHealth = (int)newState;
		ChangeHealth(nextHealth);
	}

	public void OnImpact(GameHitType hitType)
	{
		if (hitType == GameHitType.Flash)
		{
			int nextHealth = Mathf.Max(health - 1, 0);
			ChangeHealth(nextHealth);
			if (entity.IsAuthority())
			{
				entity.RequestState(entity.id, health);
			}
		}
	}

	private void ChangeHealth(int nextHealth)
	{
		if (health != nextHealth)
		{
			health = nextHealth;
			if (health == 0)
			{
				collider.enabled = false;
				visualMesh.enabled = false;
				audioSource.PlayOneShot(onDestroyedClip, onDestroyedVolume);
				destroyedFx.SetActive(value: false);
				destroyedFx.SetActive(value: true);
			}
			else
			{
				audioSource.PlayOneShot(onDamageClip, onDamageVolume);
				hitFx.SetActive(value: false);
				hitFx.SetActive(value: true);
			}
			RefreshVisuals();
		}
	}

	public bool IsHitValid(GameHitData hit)
	{
		return true;
	}

	public void OnHit(GameHitData hit)
	{
		GameHitType hitTypeId = (GameHitType)hit.hitTypeId;
		if (entity.manager.GetGameComponent<GRTool>(hit.hitByEntityId) != null)
		{
			OnImpact(hitTypeId);
		}
	}

	public void RefreshVisuals()
	{
		if (lastVisualUpdateHealth != health)
		{
			lastVisualUpdateHealth = health;
			Color color = visualMesh.material.GetColor("_BaseColor");
			color.a = (float)health / (float)maxHealth;
			visualMesh.material.SetColor("_BaseColor", color);
		}
	}
}
public class GRBay : MonoBehaviour
{
	public List<GameObject> hideWhenOpen;

	public List<GameObject> hideWhenClosed;

	public Animation bayDoorAnimation;

	private bool isOpen;

	public TMP_Text playerName;

	public TMP_Text maxDropText;

	public List<GameObject> showWhenOwned;

	public List<GameObject> showWhenNotOwned;

	public int unlockByDrillLevel = -1;

	public GRShuttleGroupLoc shuttleLoc = GRShuttleGroupLoc.Invalid;

	public int shuttleIndex = -1;

	[NonSerialized]
	public bool debugForceUnlockedByLevel;

	private GRShuttle unlockShuttle;

	private GhostReactor reactor;

	private void Awake()
	{
		if (playerName != null)
		{
			playerName.text = null;
		}
		if (maxDropText != null)
		{
			maxDropText.text = null;
		}
	}

	public void Setup(GhostReactor reactor)
	{
		this.reactor = reactor;
		if (shuttleLoc != GRShuttleGroupLoc.Invalid && shuttleIndex >= 0 && shuttleIndex < 10)
		{
			unlockShuttle = GRElevatorManager._instance.GetPlayerShuttle(shuttleLoc, shuttleIndex);
			if (unlockShuttle != null)
			{
				unlockShuttle.SetBay(this);
			}
		}
		Refresh();
	}

	public void SetOpen(bool open)
	{
		if (hideWhenOpen != null)
		{
			for (int i = 0; i < hideWhenOpen.Count; i++)
			{
				if (hideWhenOpen[i] != null)
				{
					hideWhenOpen[i].SetActive(!open);
					continue;
				}
				UnityEngine.Debug.LogErrorFormat("Why is hideWhenOpen null {0} at {1}", base.gameObject.name, i);
			}
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Why is hideWhenOpen null {0}", base.gameObject.name);
		}
		if (hideWhenClosed != null)
		{
			for (int j = 0; j < hideWhenClosed.Count; j++)
			{
				if (hideWhenClosed[j] != null)
				{
					hideWhenClosed[j].SetActive(open);
					continue;
				}
				UnityEngine.Debug.LogErrorFormat("Why is hideWhenClosed null {0} at {1} ", base.gameObject.name, j);
			}
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Why is hideWhenClosed null {0}", base.gameObject.name);
		}
		if (bayDoorAnimation != null && isOpen != open)
		{
			if (open)
			{
				bayDoorAnimation.Play("BayDoor_Open");
				bayDoorAnimation.PlayQueued("BayDoor_Open_Idle");
			}
			else
			{
				bayDoorAnimation.Play("BayDoor_Close");
				bayDoorAnimation.PlayQueued("BayDoor_Close_Idle");
			}
		}
		isOpen = open;
	}

	public void Refresh()
	{
		bool open = true;
		if (unlockShuttle != null)
		{
			NetPlayer owner = unlockShuttle.GetOwner();
			bool flag = owner != null && unlockShuttle.IsPodUnlocked();
			open = unlockShuttle.GetState() == GRShuttleState.Docked && flag;
			if (playerName != null)
			{
				playerName.text = ((!flag) ? null : owner.SanitizedNickName);
			}
			if (maxDropText != null)
			{
				int num = unlockShuttle.GetMaxDropFloor() + 1;
				maxDropText.text = ((!flag) ? null : num.ToString());
			}
			for (int i = 0; i < showWhenOwned.Count; i++)
			{
				showWhenOwned[i].SetActive(flag);
			}
			for (int j = 0; j < showWhenNotOwned.Count; j++)
			{
				showWhenNotOwned[j].SetActive(!flag);
			}
		}
		else if (unlockByDrillLevel > 0)
		{
			open = (reactor != null && reactor.GetDepthLevel() >= unlockByDrillLevel) || GhostReactorManager.bayUnlockEnabled;
		}
		SetOpen(open);
	}
}
[Serializable]
public class GRBonusEntry
{
	public enum GRBonusType
	{
		None,
		Additive,
		Multiplicative
	}

	private static int idCounter;

	public GRBonusType bonusType;

	public GRAttributeType attributeType;

	[SerializeField]
	private float bonusValue;

	public Func<int, GRBonusEntry, int> customBonus;

	public int id { get; private set; }

	private GRBonusEntry()
	{
		idCounter++;
		id = idCounter;
	}

	public int GetBonusValue()
	{
		return (int)(bonusValue * 100f);
	}

	public override string ToString()
	{
