		return $"GRBonusEntry BonusType {bonusType} AttributeType {attributeType} BonusValue {bonusValue} Id {id} CustomBonusSet {flag}";
	}
}
public class GRBonusSystem
{
	private GRAttributes defaultAttributes;

	private Dictionary<GRAttributeType, List<GRBonusEntry>> currentAdditiveBonuses = new Dictionary<GRAttributeType, List<GRBonusEntry>>();

	private Dictionary<GRAttributeType, List<GRBonusEntry>> currentMultiplicativeBonuses = new Dictionary<GRAttributeType, List<GRBonusEntry>>();

	public void Init(GRAttributes attributes)
	{
		defaultAttributes = attributes;
	}

	public GRAttributes GetDefaultAttributes()
	{
		return defaultAttributes;
	}

	public void AddBonus(GRBonusEntry entry)
	{
		if (entry.bonusType != GRBonusEntry.GRBonusType.None)
		{
			if (!currentAdditiveBonuses.ContainsKey(entry.attributeType))
			{
				currentAdditiveBonuses[entry.attributeType] = new List<GRBonusEntry>();
			}
			if (!currentMultiplicativeBonuses.ContainsKey(entry.attributeType))
			{
				currentMultiplicativeBonuses[entry.attributeType] = new List<GRBonusEntry>();
			}
			if (entry.bonusType == GRBonusEntry.GRBonusType.Additive)
			{
				currentAdditiveBonuses[entry.attributeType].Add(entry);
			}
			else if (entry.bonusType == GRBonusEntry.GRBonusType.Multiplicative)
			{
				currentMultiplicativeBonuses[entry.attributeType].Add(entry);
			}
		}
	}

	public void RemoveBonus(GRBonusEntry entry)
	{
		foreach (List<GRBonusEntry> value in currentAdditiveBonuses.Values)
		{
			value.Remove(entry);
		}
		foreach (List<GRBonusEntry> value2 in currentMultiplicativeBonuses.Values)
		{
			value2.Remove(entry);
		}
	}

	public bool HasValueForAttribute(GRAttributeType attributeType)
	{
		if (defaultAttributes != null)
		{
			return defaultAttributes.defaultAttributes.ContainsKey(attributeType);
		}
		return false;
	}

	public int CalculateFinalValueForAttribute(GRAttributeType attributeType)
	{
		if (defaultAttributes == null)
		{
			UnityEngine.Debug.LogErrorFormat("CalculateFinalValueForAttribute DefaultAttributes null.  Please fix configuration.");
			return 0;
		}
		if (!defaultAttributes.defaultAttributes.ContainsKey(attributeType))
		{
			UnityEngine.Debug.LogErrorFormat("CalculateFinalValueForAttribute DefaultAttributes Does not have entry for {0}.  Please fix configuration.", attributeType);
			return 0;
		}
		int num = defaultAttributes.defaultAttributes[attributeType];
		if (currentAdditiveBonuses.ContainsKey(attributeType))
		{
			foreach (GRBonusEntry item in currentAdditiveBonuses[attributeType])
			{
				num = ((item.customBonus == null) ? (num + item.GetBonusValue()) : item.customBonus(num, item));
			}
		}
		if (currentMultiplicativeBonuses.ContainsKey(attributeType))
		{
			foreach (GRBonusEntry item2 in currentMultiplicativeBonuses[attributeType])
			{
				if (item2.customBonus != null)
				{
					num = item2.customBonus(num, item2);
					continue;
				}
				float num2 = (float)item2.GetBonusValue() / 100f;
				num = (int)((float)num * num2);
			}
		}
		return num;
	}
}
public class GRBossEyeStare : MonoBehaviour, IGorillaSliceableSimple
{
	private UnityEngine.Vector3 lastLocalRot;

	private List<GRAbilityBase> noUpdateAbilities = new List<GRAbilityBase>();

	private GREnemyBossMoon boss;

	private GRAbilityBase lastAbility;

	private float lastCheck;

	private float checkForClosestPlayerCooldown = 1f;

	private Transform closestPlayer;

	private List<VRRig> rigs = new List<VRRig>();

	public float lerpAmount = 0.3f;

	public UnityEngine.Vector3 rotOffset;

	private void Awake()
	{
		boss = GetComponentInParent<GREnemyBossMoon>();
	}

	private void OnEnable()
	{
		lastLocalRot = base.transform.localEulerAngles;
		GorillaSlicerSimpleManager.RegisterSliceable(this);
	}

	private void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this);
	}

	public void SliceUpdate()
	{
		if (boss.CurrAbility != lastAbility)
		{
			lastLocalRot = base.transform.localEulerAngles;
		}
		if (noUpdateAbilities.Contains(boss.CurrAbility))
		{
			lastLocalRot = base.transform.localEulerAngles;
			lastAbility = boss.CurrAbility;
			return;
		}
		if (base.transform.localEulerAngles != lastLocalRot)
		{
			lastLocalRot = base.transform.localEulerAngles;
			if (!noUpdateAbilities.Contains(boss.CurrAbility))
			{
				noUpdateAbilities.Add(boss.CurrAbility);
			}
			lastAbility = boss.CurrAbility;
			return;
		}
		if (closestPlayer == null || Time.time > lastCheck + checkForClosestPlayerCooldown)
		{
			VRRigCache.Instance.GetActiveRigs(rigs);
			float num = float.MaxValue;
			for (int i = 0; i < rigs.Count; i++)
			{
				float sqrMagnitude = (base.transform.position - rigs[i].transform.position).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					closestPlayer = rigs[i].transform;
				}
			}
			lastCheck = Time.time;
		}
		lastAbility = boss.CurrAbility;
		if (!(closestPlayer == null))
		{
			base.transform.rotation = UnityEngine.Quaternion.Slerp(base.transform.rotation, UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.up, (closestPlayer.position - base.transform.position).normalized) * UnityEngine.Quaternion.Euler(rotOffset), lerpAmount);
			lastLocalRot = base.transform.localEulerAngles;
		}
	}
}
public class GRBreakable : MonoBehaviour, IGameHittable
{
	public enum BreakableState
	{
		Unbroken,
		Broken
	}

	public GameEntity gameEntity;

	public List<Transform> enableWhenBroken;

	public List<Transform> disableWhenBroken;

	public Collider breakableCollider;

	public bool holdsRandomItem = true;

	public Transform itemSpawnLocation;

	public GRBreakableItemSpawnConfig itemSpawnProbability;

	public AudioSource audioSource;

	public AudioClip breakSound;

	public float breakSoundVolume;

	private bool brokenLocal;

	public bool BrokenLocal => brokenLocal;

	private void OnEnable()
	{
		gameEntity.OnStateChanged += OnEntityStateChanged;
	}

	private void OnDisable()
	{
		if (gameEntity != null)
		{
			gameEntity.OnStateChanged -= OnEntityStateChanged;
		}
	}

	private void OnEntityStateChanged(long prevState, long nextState)
	{
		switch ((BreakableState)nextState)
		{
		case BreakableState.Broken:
			BreakLocal();
			break;
		case BreakableState.Unbroken:
			RestoreLocal();
			break;
		}
	}

	public void BreakLocal()
	{
		if (!brokenLocal)
		{
			brokenLocal = true;
			if (breakableCollider != null)
			{
				breakableCollider.enabled = false;
			}
			for (int i = 0; i < disableWhenBroken.Count; i++)
			{
				disableWhenBroken[i].gameObject.SetActive(value: false);
			}
			for (int j = 0; j < enableWhenBroken.Count; j++)
			{
				enableWhenBroken[j].gameObject.SetActive(value: true);
			}
			if (audioSource != null)
			{
				audioSource.PlayOneShot(breakSound, breakSoundVolume);
			}
			if (gameEntity.IsAuthority() && holdsRandomItem && itemSpawnProbability.TryForRandomItem(gameEntity, out var entity))
			{
				gameEntity.manager.RequestCreateItem(entity.gameObject.name.GetStaticHash(), itemSpawnLocation.position, itemSpawnLocation.rotation, 0L);
			}
		}
	}

	public void RestoreLocal()
	{
		if (brokenLocal)
		{
			brokenLocal = false;
			if (breakableCollider != null)
			{
				breakableCollider.enabled = true;
			}
			for (int i = 0; i < disableWhenBroken.Count; i++)
			{
				disableWhenBroken[i].gameObject.SetActive(value: true);
			}
			for (int j = 0; j < enableWhenBroken.Count; j++)
			{
				enableWhenBroken[j].gameObject.SetActive(value: false);
			}
		}
	}

	public bool IsHitValid(GameHitData hit)
	{
		if (!brokenLocal)
		{
			return hit.hitTypeId == 0;
		}
		return false;
	}

	public void OnHit(GameHitData hit)
	{
		if (hit.hitTypeId == 0 && (int)this.gameEntity.GetState() != 1)
		{
			this.gameEntity.RequestState(this.gameEntity.id, 1L);
			GameEntity gameEntity = this.gameEntity.manager.GetGameEntity(hit.hitByEntityId);
			if (gameEntity != null && gameEntity.IsHeldByLocalPlayer())
			{
				PlayerGameEvents.MiscEvent("GRSmashBreakable");
			}
		}
	}
}
[CreateAssetMenu(fileName = "GhostReactorBreakableItemSpawnConfig", menuName = "ScriptableObjects/GhostReactorBreakableItemSpawnConfig")]
public class GRBreakableItemSpawnConfig : ScriptableObject
{
	[Serializable]
	public struct ItemProbability
	{
		public GameEntity entity;

		public float probability;
	}

	[SerializeField]
	[Range(0f, 1f)]
	public float spawnAnythingProbability = 0.2f;

	public List<ItemProbability> perItemProbabilities = new List<ItemProbability>();

	[SerializeField]
	[Unity.XR.CoreUtils.ReadOnly]
	private float precomputedItemTotalWeight;

	public bool TryForRandomItem(GameEntity spawnFromEntity, out GameEntity entity, int sanity = 0)
	{
		GRBreakableItemSpawnConfig gRBreakableItemSpawnConfig = GetOverride(spawnFromEntity);
		if (sanity <= 5 && gRBreakableItemSpawnConfig != null)
		{
			return gRBreakableItemSpawnConfig.TryForRandomItem(spawnFromEntity, out entity, sanity + 1);
		}
		if (sanity > 5)
		{
			UnityEngine.Debug.LogError("Circular override loop");
		}
		if (UnityEngine.Random.Range(0f, 1f) < spawnAnythingProbability)
		{
			float num = UnityEngine.Random.Range(0f, precomputedItemTotalWeight);
			float num2 = 0f;
			for (int i = 0; i < perItemProbabilities.Count; i++)
			{
				num2 += perItemProbabilities[i].probability;
				if (num2 > num || i == perItemProbabilities.Count - 1)
				{
					entity = perItemProbabilities[i].entity;
					return true;
				}
			}
		}
		entity = null;
		return false;
	}

	public bool TryForRandomItem(GhostReactor reactor, ref SRand srand, out GameEntity entity, int sanity = 0)
	{
		GRBreakableItemSpawnConfig gRBreakableItemSpawnConfig = GetOverride(reactor);
		if (sanity <= 5 && gRBreakableItemSpawnConfig != null)
		{
			return gRBreakableItemSpawnConfig.TryForRandomItem(reactor, ref srand, out entity, sanity + 1);
		}
		if (sanity > 5)
		{
			UnityEngine.Debug.LogError("Circular override loop");
		}
		if (srand.NextFloat(0f, 1f) < spawnAnythingProbability)
		{
			float num = srand.NextFloat(0f, precomputedItemTotalWeight);
			float num2 = 0f;
			for (int i = 0; i < perItemProbabilities.Count; i++)
			{
				num2 += perItemProbabilities[i].probability;
				if (num2 > num || i == perItemProbabilities.Count - 1)
				{
					entity = perItemProbabilities[i].entity;
					return true;
				}
			}
		}
		entity = null;
		return false;
	}

	private GRBreakableItemSpawnConfig GetOverride(GameEntity entity)
	{
		GhostReactorManager ghostReactorManager = GhostReactorManager.Get(entity);
		if (ghostReactorManager == null)
		{
			return null;
		}
		return GetOverride(ghostReactorManager.reactor);
	}

	private GRBreakableItemSpawnConfig GetOverride(GhostReactor reactor)
	{
		if (reactor == null)
		{
			return null;
		}
		GhostReactorLevelGenConfig currLevelGenConfig = reactor.GetCurrLevelGenConfig();
		if (currLevelGenConfig == null || currLevelGenConfig.dropTableOverrides == null)
		{
			return null;
		}
		return currLevelGenConfig.dropTableOverrides.GetOverride(this);
	}

	private void OnValidate()
	{
		precomputedItemTotalWeight = 0f;
		for (int i = 0; i < perItemProbabilities.Count; i++)
		{
			precomputedItemTotalWeight += perItemProbabilities[i].probability;
		}
	}
}
