public class GRGameEntityInteractionPoint : MonoBehaviour
{
	public GameEntity gameEntity;

	public float autoReleaseDistance = 0.1f;

	public Action OnGrabStart;

	public Action OnGrabContinue;

	public Action OnGrabEnd;

	public Transform targetParent;

	public void Start()
	{
		base.transform.parent = targetParent;
	}

	public void OnEnable()
	{
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(OnGrabbed));
		GameEntity obj2 = gameEntity;
		obj2.OnReleased = (Action)Delegate.Combine(obj2.OnReleased, new Action(OnReleased));
	}

	public void OnDisable()
	{
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Remove(obj.OnGrabbed, new Action(OnGrabbed));
		GameEntity obj2 = gameEntity;
		obj2.OnReleased = (Action)Delegate.Remove(obj2.OnReleased, new Action(OnReleased));
	}

	public void OnGrabbed()
	{
		GameEntity obj = gameEntity;
		obj.OnTick = (Action)Delegate.Combine(obj.OnTick, new Action(TickWhileHeld));
		OnGrabStart?.Invoke();
	}

	public void OnReleased()
	{
		GameEntity obj = gameEntity;
		obj.OnTick = (Action)Delegate.Remove(obj.OnTick, new Action(TickWhileHeld));
		gameEntity.transform.parent = targetParent;
		gameEntity.transform.localRotation = UnityEngine.Quaternion.identity;
		gameEntity.transform.localPosition = UnityEngine.Vector3.zero;
		OnGrabEnd();
	}

	public void TickWhileHeld()
	{
		if (targetParent != null)
		{
			UnityEngine.Vector3 position = targetParent.transform.position;
			UnityEngine.Vector3 position2 = base.transform.position;
			if (UnityEngine.Vector3.Magnitude(position - position2) > autoReleaseDistance)
			{
				GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
				if (gamePlayer != null)
				{
					gamePlayer.ClearGrabbedIfHeld(gameEntity.id, gameEntity.manager);
				}
				if (gamePlayer != null && GamePlayerLocal.instance.gamePlayer == gamePlayer)
				{
					GamePlayerLocal.instance.ClearGrabbedIfHeld(gameEntity.id, gameEntity.manager);
				}
				OnReleased();
				return;
			}
		}
		OnGrabContinue?.Invoke();
	}
}
public class GRGuide : MonoBehaviourTick
{
	public Transform tempTarget;

	public List<GameObject> show;

	public AudioSource audioSource;

	private bool showing;

	private bool hasPath;

	private NavMeshPath path;

	private int numPathCorners;

	private UnityEngine.Vector3[] pathCorners;

	private List<UnityEngine.Vector3> connectorCorners;

	private void Awake()
	{
		path = new NavMeshPath();
		showing = false;
		for (int i = 0; i < show.Count; i++)
		{
			show[i].SetActive(value: false);
		}
		hasPath = false;
		numPathCorners = 0;
		pathCorners = new UnityEngine.Vector3[512];
		connectorCorners = new List<UnityEngine.Vector3>(64);
	}

	public override void Tick()
	{
		bool flag = GRPlayer.Get(VRRig.LocalRig).State == GRPlayer.GRPlayerState.Ghost;
		UnityEngine.Vector3 position = VRRig.LocalRig.transform.position;
		float sqrMagnitude = (position - base.transform.position).sqrMagnitude;
		if (flag && (!hasPath || sqrMagnitude > 36f))
		{
			hasPath = false;
			if (GhostReactor.instance.levelGenerator.GetExitFromCurrentSection(position, out var exitPos, out var _, connectorCorners) && NavMesh.SamplePosition(position, out var hit, 5f, -1) && NavMesh.SamplePosition(exitPos, out var hit2, 5f, -1) && NavMesh.CalculatePath(hit.position, hit2.position, -1, path) && path.status == NavMeshPathStatus.PathComplete)
			{
				numPathCorners = path.GetCornersNonAlloc(pathCorners);
				for (int num = connectorCorners.Count - 1; num >= 0; num--)
				{
					pathCorners[numPathCorners] = connectorCorners[num];
					numPathCorners++;
				}
				if (numPathCorners > 0)
				{
					base.transform.position = pathCorners[0];
					hasPath = true;
				}
			}
		}
		if (!flag)
		{
			hasPath = false;
		}
		if (showing != hasPath)
		{
			showing = hasPath;
			for (int i = 0; i < show.Count; i++)
			{
				show[i].SetActive(showing);
			}
			if (audioSource != null)
			{
				if (showing)
				{
					audioSource.Play();
				}
				else
				{
					audioSource.Stop();
				}
			}
		}
		if (!hasPath)
		{
			return;
		}
		int nextCorner;
		UnityEngine.Vector3 closestPointOnPath = GetClosestPointOnPath(position, pathCorners, numPathCorners, out nextCorner);
		float num2 = 2.5f;
		UnityEngine.Vector3 vector = closestPointOnPath;
		for (int j = nextCorner; j < numPathCorners; j++)
		{
			UnityEngine.Vector3 vector2 = pathCorners[j] - vector;
			float magnitude = vector2.magnitude;
			if (num2 <= magnitude)
			{
				vector += vector2 * (num2 / magnitude);
				break;
			}
			num2 -= magnitude;
			vector = pathCorners[j];
		}
		base.transform.position = vector;
	}

	private static UnityEngine.Vector3 GetClosestPointOnPath(UnityEngine.Vector3 pos, UnityEngine.Vector3[] pathCorners, int numPathCorners, out int nextCorner)
	{
		nextCorner = 0;
		switch (numPathCorners)
		{
		case 0:
			return pos;
		case 1:
			return pathCorners[0];
		default:
		{
			float num = float.MaxValue;
			UnityEngine.Vector3 result = UnityEngine.Vector3.zero;
			for (int i = 0; i < numPathCorners - 1; i++)
			{
				UnityEngine.Vector3 vA = pathCorners[i];
				UnityEngine.Vector3 vB = pathCorners[i + 1];
				UnityEngine.Vector3 vector = ClosestPointOnLine(vA, vB, pos);
				float sqrMagnitude = (vector - pos).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					result = vector;
					nextCorner = i + 1;
				}
			}
			return result;
		}
		}
	}

	public static UnityEngine.Vector3 ClosestPointOnLine(UnityEngine.Vector3 vA, UnityEngine.Vector3 vB, UnityEngine.Vector3 vPoint)
	{
		UnityEngine.Vector3 rhs = vPoint - vA;
		UnityEngine.Vector3 normalized = (vB - vA).normalized;
		float num = UnityEngine.Vector3.Distance(vA, vB);
		float num2 = UnityEngine.Vector3.Dot(normalized, rhs);
		if (num2 <= 0f)
		{
			return vA;
		}
		if (num2 >= num)
		{
			return vB;
		}
		UnityEngine.Vector3 vector = normalized * num2;
		return vA + vector;
	}
}
[RequireComponent(typeof(LineRenderer))]
public class HangingClaw : MonoBehaviourPostTick
{
	public struct RopeSegment(UnityEngine.Vector3 p)
	{
		public UnityEngine.Vector3 pos = p;

		public UnityEngine.Vector3 posOld = p;
	}

	public Transform endTransform;

	public Transform heightCap;

	private int segmentCount = 6;

	public float segmentMassKg = 1f;

	public float endMassKg = 5f;

	public float ropeStiffness = 0.9f;

	public float slackFraction = 0.02f;

	public UnityEngine.Vector3 gravity = new UnityEngine.Vector3(0f, -9.8f, 0f);

	public float velocityDamping = 0.98f;

	private float maxY;

	private LineRenderer lineRenderer;

	private RopeSegment[] ropeSegs;

	private float baseSegLen;

	private float targetSegLenScaled;

	private float[] invMass;

	protected void Awake()
	{
		lineRenderer = GetComponent<LineRenderer>();
		UnityEngine.Vector3 position = base.transform.position;
		segmentCount = 4;
		float magnitude = (endTransform.position - position).magnitude;
		segmentCount = Mathf.Max(2, segmentCount);
		baseSegLen = magnitude / (float)segmentCount;
		ropeSegs = new RopeSegment[segmentCount];
		invMass = new float[segmentCount];
		for (int i = 0; i < segmentCount; i++)
		{
			UnityEngine.Vector3 p = UnityEngine.Vector3.Lerp(position, endTransform.position, (float)i / (float)(segmentCount - 1));
			ropeSegs[i] = new RopeSegment(p);
		}
		invMass[0] = 0f;
		for (int j = 1; j < segmentCount - 1; j++)
		{
			invMass[j] = 1f / Mathf.Max(0.0001f, segmentMassKg);
		}
		invMass[segmentCount - 1] = 1f / Mathf.Max(0.0001f, endMassKg);
	}

	public override void PostTick()
	{
		Simulate();
		DrawRope();
		int num = segmentCount - 1;
		_ = segmentCount;
		endTransform.position = ropeSegs[num].pos;
	}

	private void Simulate()
	{
		float num = baseSegLen;
		targetSegLenScaled = num * (1f + slackFraction);
		float num2 = 0.01111f;
		float f = Time.time * 0.5f;
		UnityEngine.Vector3 vector = gravity * num2 * num2;
		UnityEngine.Vector3 topPos = base.transform.position + new UnityEngine.Vector3(0f, 0.012f * Mathf.Sin(f), 0.02f * Mathf.Cos(f));
		for (int i = 1; i < segmentCount; i++)
		{
			UnityEngine.Vector3 vector2 = ropeSegs[i].pos - ropeSegs[i].posOld;
			ropeSegs[i].posOld = ropeSegs[i].pos;
			ropeSegs[i].pos += vector2 * velocityDamping + vector;
		}
		int num3 = 3;
		for (int j = 0; j < num3; j++)
		{
			ApplyConstraints(topPos);
		}
	}

	private void ApplyConstraints(UnityEngine.Vector3 topPos)
	{
		ropeSegs[0].pos = topPos;
		ropeSegs[0].posOld = topPos;
		float stiffness = Mathf.Clamp01(ropeStiffness);
		for (int i = 0; i < segmentCount - 1; i++)
		{
			ApplyConstraintSegment(ref ropeSegs[i], ref ropeSegs[i + 1], invMass[i], invMass[i + 1], stiffness);
		}
	}

	private void ApplyConstraintSegment(ref RopeSegment a, ref RopeSegment b, float wA, float wB, float stiffness)
	{
		UnityEngine.Vector3 vector = b.pos - a.pos;
		float magnitude = vector.magnitude;
		if (magnitude < 1E-06f)
		{
			return;
		}
		float num = magnitude - targetSegLenScaled;
		if (!(Mathf.Abs(num) < 1E-06f))
		{
			UnityEngine.Vector3 vector2 = vector / magnitude;
			float num2 = wA + wB;
			if (!(num2 <= 0f))
			{
				UnityEngine.Vector3 vector3 = vector2 * (num * stiffness);
				a.pos += vector3 * (wA / num2);
				b.pos += -vector3 * (wB / num2);
			}
		}
	}

	private void DrawRope()
	{
		if (lineRenderer == null)
		{
			return;
		}
		lineRenderer.positionCount = segmentCount;
		for (int i = 0; i < segmentCount; i++)
		{
			UnityEngine.Vector3 pos = ropeSegs[i].pos;
			if ((bool)heightCap && pos.y > heightCap.position.y)
			{
				pos.y = heightCap.position.y;
			}
			lineRenderer.SetPosition(i, ropeSegs[i].pos);
		}
	}
}
