public struct GameNoiseEvent
{
	public UnityEngine.Vector3 position;

	public double eventTime;

	public float duration;

	public float magnitude;

	public bool IsValid()
	{
		return (float)(Time.timeAsDouble - eventTime) <= duration;
	}
}
public class GRNoiseEventManager : MonoBehaviourTick
{
	private List<GameNoiseEvent> noiseEvents = new List<GameNoiseEvent>();

	public static GRNoiseEventManager instance;

	public float debugMeshScale = 1f;

	public void Awake()
	{
		instance = this;
	}

	private void Start()
	{
	}

	public override void Tick()
	{
		RemoveExpiredEvents();
		if (GhostReactorManager.noiseDebugEnabled)
		{
			RenderDebug();
		}
	}

	private int FindUnusedEventEntry()
	{
		return -1;
	}

	public void AddNoiseEvent(UnityEngine.Vector3 position, float magnitude = 1f, float duration = 1f)
	{
		GameNoiseEvent gameNoiseEvent = new GameNoiseEvent
		{
			position = position,
			eventTime = Time.timeAsDouble,
			duration = duration,
			magnitude = magnitude
		};
		int num = FindUnusedEventEntry();
		if (num == -1)
		{
			noiseEvents.Add(gameNoiseEvent);
		}
		else
		{
			noiseEvents[num] = gameNoiseEvent;
		}
	}

	public List<GameNoiseEvent> GetNoiseEventsInRadius(UnityEngine.Vector3 origin, float radius)
	{
		List<GameNoiseEvent> list = new List<GameNoiseEvent>();
		float num = radius * radius;
		foreach (GameNoiseEvent noiseEvent in noiseEvents)
		{
			if (noiseEvent.IsValid())
			{
				float sqrMagnitude = (noiseEvent.position - origin).sqrMagnitude;
				float num2 = noiseEvent.magnitude * noiseEvent.magnitude;
				if (sqrMagnitude < num * num2)
				{
					list.Add(noiseEvent);
				}
			}
		}
		return list;
	}

	public bool GetMostRecentNoiseEventInRadius(UnityEngine.Vector3 origin, float radius, out GameNoiseEvent outEvent)
	{
		double timeAsDouble = Time.timeAsDouble;
		float num = radius * radius;
		double num2 = -1.0;
		int num3 = -1;
		for (int i = 0; i < noiseEvents.Count; i++)
		{
			GameNoiseEvent gameNoiseEvent = noiseEvents[i];
			if (!gameNoiseEvent.IsValid())
			{
				continue;
			}
			float sqrMagnitude = (gameNoiseEvent.position - origin).sqrMagnitude;
			float num4 = gameNoiseEvent.magnitude * gameNoiseEvent.magnitude;
			if (sqrMagnitude < num * num4)
			{
				double num5 = timeAsDouble - gameNoiseEvent.eventTime;
				if (num3 < 0 || num5 < num2)
				{
					num3 = i;
					num2 = num5;
				}
			}
		}
		if (num3 < 0)
		{
			outEvent = default(GameNoiseEvent);
			return false;
		}
		outEvent = noiseEvents[num3];
		return true;
	}

	public void RenderDebug()
	{
		int num = 0;
		float num2 = 5f;
		for (int i = 0; i < noiseEvents.Count; i++)
		{
			GameNoiseEvent gameNoiseEvent = noiseEvents[i];
			if (gameNoiseEvent.IsValid())
			{
				float radius = debugMeshScale * gameNoiseEvent.magnitude * num2;
				DebugUtil.DrawSphere(gameNoiseEvent.position, radius, 8, 6, Color.green);
				num++;
			}
		}
	}

	private void RemoveExpiredEvents()
	{
		for (int i = 0; i < noiseEvents.Count; i++)
		{
			if (!noiseEvents[i].IsValid())
			{
				noiseEvents.RemoveAtSwapBack(i);
				i--;
			}
		}
	}
}
public class GROneTimeEntitySpawner : MonoBehaviour
{
	public GhostReactor reactor;

	public GameEntity EntityPrefab;

	private bool bHasSpawned;

	private float SpawnDelay = 3f;

	private void Start()
	{
		if (EntityPrefab == null)
		{
			UnityEngine.Debug.Log("Can't  spawn null entity", this);
		}
		Invoke("TrySpawn", SpawnDelay);
	}

	private void Update()
	{
	}

	private void TrySpawn()
	{
		if (bHasSpawned || !(EntityPrefab != null))
		{
			return;
		}
		UnityEngine.Debug.Log("trying to spawn entity" + EntityPrefab.name, this);
		GameEntityManager gameEntityManager = reactor.grManager.gameEntityManager;
		if (gameEntityManager.IsAuthority())
		{
			if (!gameEntityManager.IsZoneActive())
			{
				UnityEngine.Debug.Log("delaying spawn attempt because zone not active", this);
				Invoke("TrySpawn", 0.2f);
			}
			else
			{
				UnityEngine.Debug.Log("trying to spawn entity", this);
				gameEntityManager.RequestCreateItem(EntityPrefab.name.GetStaticHash(), base.transform.position + new UnityEngine.Vector3(0f, 0f, 0f), base.transform.rotation, 0L);
				bHasSpawned = true;
			}
		}
	}
}
public class GRPatrolPath : MonoBehaviour
{
	[NonSerialized]
	public List<Transform> patrolNodes;

	public int index;

	private void Awake()
	{
		patrolNodes = new List<Transform>(base.transform.childCount);
		for (int i = 0; i < base.transform.childCount; i++)
		{
			patrolNodes.Add(base.transform.GetChild(i));
		}
	}

	public void OnDrawGizmosSelected()
	{
		if (patrolNodes == null || base.transform.childCount != patrolNodes.Count)
		{
			patrolNodes = new List<Transform>(base.transform.childCount);
			for (int i = 0; i < base.transform.childCount; i++)
			{
				patrolNodes.Add(base.transform.GetChild(i));
			}
		}
		if (patrolNodes == null)
		{
			return;
		}
		for (int j = 0; j < patrolNodes.Count; j++)
		{
			Gizmos.color = Color.magenta;
			Gizmos.DrawCube(patrolNodes[j].transform.position, UnityEngine.Vector3.one * 0.5f);
			if (j < patrolNodes.Count - 1)
			{
				Gizmos.DrawLine(patrolNodes[j].transform.position, patrolNodes[j + 1].transform.position);
			}
		}
	}
}
public class GRPatrolPathNode : MonoBehaviour
{
	public void OnDrawGizmosSelected()
	{
		if (!(base.transform.parent == null))
		{
			GRPatrolPath component = base.transform.parent.GetComponent<GRPatrolPath>();
			if (!(component == null))
			{
				component.OnDrawGizmosSelected();
			}
		}
	}
}
