	public void TryDepositSeed(int playerActorNumber, int seedNetId)
	{
		NetPlayer player = NetworkSystem.Instance.GetPlayer(playerActorNumber);
		GameEntityManager managerForZone = GameEntityManager.GetManagerForZone(zone);
		if (player == null || managerForZone == null)
		{
			return;
		}
		depositorAudioSource.PlayOneShot(seedDepositAttemptAudio, seedDepositAttemptVolume);
		if (player.ActorNumber != NetworkSystem.Instance.LocalPlayer.ActorNumber)
		{
			return;
		}
		bool flag = false;
		float time = Time.time;
		for (int num = seedDepositsPending.Count - 1; num >= 0; num--)
		{
			if (time - seedDepositsPending[num].Item3 > 5f || managerForZone.GetGameEntityFromNetId(seedDepositsPending[num].Item1) == null || NetworkSystem.Instance.GetPlayer(seedDepositsPending[num].Item2) == null)
			{
				seedDepositsPending.RemoveAt(num);
			}
			else if (seedDepositsPending[num].Item1 == seedNetId)
			{
				flag = true;
				if (seedDepositsPending[num].Item2 == NetworkSystem.Instance.LocalPlayer.ActorNumber && !seedDepositsPending[num].Item4)
				{
					(int, int, float, bool) value = seedDepositsPending[num];
					value.Item4 = true;
					seedDepositsPending[num] = value;
					ProgressionManager.Instance.DepositCore(ProgressionManager.CoreType.ChaosSeed);
				}
			}
		}
		if (!flag)
		{
			seedDepositsPending.Add((seedNetId, playerActorNumber, Time.time, true));
			ProgressionManager.Instance.DepositCore(ProgressionManager.CoreType.ChaosSeed);
		}
	}

	public bool ValidateSeedDepositSucceeded(int playerActorNumber, int entityNetId)
	{
		if (ghostReactor.grManager.IsAuthority())
		{
			bool result = false;
			for (int i = 0; i < seedDepositsPending.Count; i++)
			{
				if (seedDepositsPending[i].Item1 == entityNetId && seedDepositsPending[i].Item2 == playerActorNumber)
				{
					result = true;
				}
			}
			return result;
		}
		return false;
	}

	public void SeedDepositSucceeded(int playerActorNumber, int entityNetId)
	{
		if (NetworkSystem.Instance.InRoom)
		{
			depositorParticles.Play();
			depositorAudioSource.PlayOneShot(seedDepositAudio, seedDepositVolume);
			RemovePendingSeedDeposit(entityNetId);
			if (playerActorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber)
			{
				ProgressionManager.Instance.GetJuicerStatus();
			}
			if (!stationOpen && ghostReactor.grManager.IsAuthority())
			{
				ghostReactor.grManager.RequestPlayerAction(GhostReactorManager.GRPlayerAction.SeedExtractorOpenStation, playerActorNumber, 0);
			}
		}
	}

	public void SeedDepositFailed(int playerActorNumber, int entityNetId)
	{
		depositorAudioSource.PlayOneShot(seedDepositFailedAudio, seedDepositFailedVolume);
		RemovePendingSeedDeposit(entityNetId);
	}

	private void RemovePendingSeedDeposit(int entityId)
	{
		for (int num = seedDepositsPending.Count - 1; num >= 0; num--)
		{
			if (seedDepositsPending[num].Item1 == entityId)
			{
				seedDepositsPending.RemoveAt(num);
			}
		}
	}

	public void ApplyState(int playerActorNumber, int coreCount, int coresProcessedByOverdrive, int researchPoints, float coreProcessingPercentage, float overdriveSupply)
	{
		if (playerActorNumber == currentPlayerActorNumber)
		{
			if (currentPlayerData.actorNumber != playerActorNumber)
			{
				currentPlayerData = default(PlayerData);
			}
			coreCount = Mathf.Clamp(coreCount, 0, maxVisualChaosSeedCount);
			coresProcessedByOverdrive = Mathf.Clamp(coresProcessedByOverdrive, 0, MAX_OVERDRIVE_USES);
			coreProcessingPercentage = Mathf.Clamp(coreProcessingPercentage, 0f, 1f);
			overdriveSupply = Mathf.Clamp(overdriveSupply, 0f, 1f);
			bool flag = overdriveSupply < currentPlayerData.overdriveSupply;
			bool flag2 = currentPlayerData.overdriveSupply == 0f && currentPlayerData.coreCount > coreCount;
			if (playerActorNumber != NetworkSystem.Instance.LocalPlayer.ActorNumber && coresProcessedByOverdrive > 0 && (flag || flag2))
			{
				currentPlayerData.coresPendingOverdriveProcessing += coresProcessedByOverdrive;
			}
			currentPlayerData.actorNumber = playerActorNumber;
			currentPlayerData.coreCount = coreCount;
			currentPlayerData.coresProcessedByOverdrive = coresProcessedByOverdrive;
			currentPlayerData.coreProcessingPercentage = coreProcessingPercentage;
			currentPlayerData.overdriveSupply = overdriveSupply;
			currentPlayerData.latestRefreshTime = Time.time;
			currentPlayerData.researchPoints = researchPoints;
			OnStateUpdated();
		}
	}

	public void OpenStation(int playerActorNumber)
	{
		if (NetworkSystem.Instance.GetPlayer(playerActorNumber) != null)
		{
			if (!stationOpen)
			{
				doorAudioSource.PlayOneShot(doorOpenAudio, doorOpenVolume);
			}
			base.enabled = true;
			currentPlayerActorNumber = playerActorNumber;
			stationOpen = true;
			stationOpenRequestTime = Time.time;
			UpdateOverdrivePurchaseButtons();
		}
	}

	public void CloseStation()
	{
		if (stationOpen)
		{
			doorAudioSource.PlayOneShot(doorCloseAudio, doorCloseVolume);
		}
		currentPlayerActorNumber = -1;
		stationOpen = false;
		UpdateOverdrivePurchaseButtons();
	}

	private void UpdateOverdrivePurchaseButtons()
	{
		if (LocalPlayerCanPurchaseOverdrive())
		{
			if (overdrivePurchasePending)
			{
				overdrivePurchaseButton.myTmpText.text = "CANCEL";
				overdrivePurchaseButton.buttonRenderer.material = redButtonMaterial;
				overdriveConfirmButton.myTmpText.text = "CONFIRM";
				overdriveConfirmButton.buttonRenderer.material = greenButtonMaterial;
			}
			else
			{
				overdrivePurchaseButton.myTmpText.text = "BUY";
				overdrivePurchaseButton.buttonRenderer.material = defaultButtonMaterial;
				overdriveConfirmButton.myTmpText.text = "";
				overdriveConfirmButton.buttonRenderer.material = defaultButtonMaterial;
			}
		}
		else
		{
			overdrivePurchaseButton.myTmpText.text = "";
			overdrivePurchaseButton.buttonRenderer.material = defaultButtonMaterial;
			overdriveConfirmButton.myTmpText.text = "";
			overdriveConfirmButton.buttonRenderer.material = defaultButtonMaterial;
		}
	}

	public void OnStateUpdated()
	{
		NetPlayer player = NetworkSystem.Instance.GetPlayer(currentPlayerActorNumber);
		if (player == null)
		{
			CloseStation();
		}
		UpdateOverdrivePurchaseButtons();
		if (stationOpen && player != null)
		{
			if (overdriveActive)
			{
				return;
			}
			if (currentPlayerData.coresPendingOverdriveProcessing > 0)
			{
				int coresPendingOverdriveProcessing = currentPlayerData.coresPendingOverdriveProcessing;
				currentPlayerData.coresPendingOverdriveProcessing = 0;
				if (StationOpenForLocalPlayer)
				{
					localPlayerData.coresPendingOverdriveProcessing = 0;
				}
				overdrivePurchaseAnimationRoutine = StartCoroutine(OverdrivePurchaseAnimationVisual(coresPendingOverdriveProcessing));
				return;
			}
			processingAmount = currentPlayerData.coreProcessingPercentage;
			overdriveAmount = currentPlayerData.overdriveSupply;
			int num = Mathf.Clamp(currentPlayerData.coreCount, 0, maxVisualChaosSeedCount) - seedProcessingStates.Count;
			if (num > 0)
			{
				for (int i = 0; i < num; i++)
				{
					DepositSeedVisual();
				}
			}
			else if (num < 0)
			{
				for (int num2 = 0; num2 > num; num2--)
				{
					CompleteSeedVisual();
				}
			}
		}
		else
		{
			screenText.text = "Player Data Lookup Failed.";
			overdriveAmount = 0f;
			processingAmount = 0f;
		}
	}

	private void DepositSeedVisual()
	{
		for (int i = 0; i < chaosSeedVisuals.Count; i++)
		{
			if (!chaosSeedVisuals[i].activeSelf)
			{
				SeedProcessingVisualState item = new SeedProcessingVisualState
				{
					poolIndex = i,
					rollAngle = 0f,
					speed = 0f,
					rampProgress = 0f,
					dropProgress = 0f
				};
				seedProcessingStates.Add(item);
				chaosSeedVisuals[i].SetActive(value: true);
				chaosSeedVisuals[i].transform.localPosition = seedTubeStart.localPosition;
				chaosSeedVisuals[i].transform.localRotation = UnityEngine.Quaternion.identity;
				chaosSeedVisuals[i].transform.localScale = UnityEngine.Vector3.one * seedVisualScaleRange.y;
				seedTubeAudioSource.PlayOneShot(seedMovementAudio, seedMovementVolume);
				break;
			}
		}
	}

	private void CompleteSeedVisual()
	{
		if (seedProcessingStates.Count > 0)
		{
			SeedProcessingVisualState seedProcessingVisualState = seedProcessingStates[0];
			chaosSeedVisuals[seedProcessingVisualState.poolIndex].SetActive(value: false);
			seedProcessingStates.RemoveAt(0);
		}
	}

	private void ClearSeedVisuals()
	{
		int count = seedProcessingStates.Count;
		for (int i = 0; i < count; i++)
		{
			CompleteSeedVisual();
		}
	}

	private void UpdateScreenDisplay()
	{
		NetPlayer player = NetworkSystem.Instance.GetPlayer(currentPlayerActorNumber);
		if (player == null || !stationOpen)
		{
			return;
		}
		int num = (int)estimatedJuiceTimeRemaining;
		if (currentPlayerActorNumber == currentDisplayData.playerActorNumber && currentPlayerData.coreCount == currentDisplayData.coreCount && currentPlayerData.overdriveSupply == currentDisplayData.overdriveSupply && currentPlayerData.researchPoints == currentDisplayData.researchPoints && num == currentDisplayData.juiceSecondsLeft)
		{
			return;
		}
		currentDisplayData.playerActorNumber = currentPlayerActorNumber;
		currentDisplayData.coreCount = currentPlayerData.coreCount;
		currentDisplayData.overdriveSupply = currentPlayerData.overdriveSupply;
		currentDisplayData.researchPoints = currentPlayerData.researchPoints;
		currentDisplayData.juiceSecondsLeft = num;
		UpdateScreenSB.Clear();
		UpdateScreenSB.Append(player.SanitizedNickName + "\n");
		UpdateScreenSB.Append($"JUICE: <color=purple>? {currentDisplayData.researchPoints}</color>\n\n");
		if (currentDisplayData.coreCount > 0)
		{
			UpdateScreenSB.Append($"Processing {currentDisplayData.coreCount} Seeds");
			switch (currentDisplayData.juiceSecondsLeft % 3)
			{
			case 2:
				UpdateScreenSB.Append(".");
				break;
			case 1:
				UpdateScreenSB.Append("..");
				break;
			default:
				UpdateScreenSB.Append("...");
				break;
			}
			int num2 = num / 3600;
			int num3 = num / 60 % 60;
			int num4 = num % 60;
			if (num2 > 0)
			{
				UpdateScreenSB.Append($"\nNext <color=purple>?</color> in {num2}:{num3:00}:{num4:00}\n");
			}
			else
			{
				UpdateScreenSB.Append($"\nNext <color=purple>?</color> in {num3}:{num4:00}\n");
			}
		}
		else
		{
			UpdateScreenSB.Append("Deposit Chaos Seed\nFor Juice Processing\n");
		}
		screenText.text = UpdateScreenSB.ToString();
	}

	private void StepSeedVisualAnimation(float dt)
	{
		float magnitude = (seedTubeStart.position - seedTubeEnd.position).magnitude;
		float num = magnitude / seedVisualRollTime;
		for (int i = 0; i < seedProcessingStates.Count; i++)
		{
			SeedProcessingVisualState value = seedProcessingStates[i];
			float num2 = 2f;
			if (i > 0)
			{
				num2 = seedProcessingStates[i - 1].rampProgress - 2f * visualChaosSeedRadius / magnitude;
			}
			if (value.rampProgress < 1f)
			{
				GameObject obj = chaosSeedVisuals[value.poolIndex];
				value.speed = Mathf.MoveTowards(value.speed, num, num * dt);
				float num3 = value.speed * dt;
				float num4 = num3 / magnitude;
				value.rampProgress = Mathf.Clamp01(value.rampProgress + num4);
				if (value.rampProgress >= num2)
				{
					value.rampProgress = num2;
					value.speed = 0f;
					num3 = (num4 = 0f);
				}
				obj.transform.localPosition = UnityEngine.Vector3.Lerp(seedTubeStart.localPosition, seedTubeEnd.localPosition, value.rampProgress);
				value.rollAngle += num3 / visualChaosSeedRadius;
				obj.transform.localRotation = UnityEngine.Quaternion.AngleAxis(value.rollAngle * 57.29578f, UnityEngine.Vector3.forward);
			}
			if (i == 0 && value.rampProgress >= 1f)
			{
				GameObject gameObject = chaosSeedVisuals[value.poolIndex];
				if (value.dropProgress < 1f)
				{
					value.dropProgress += 1f / seedVisualDropTime * dt;
					value.rampProgress = 1f + value.dropProgress;
					float t = tubeEndToProcessingPathY.Evaluate(value.dropProgress);
					float t2 = tubeEndToProcessingPathX.Evaluate(value.dropProgress);
					UnityEngine.Vector3 localPosition = gameObject.transform.localPosition;
					localPosition.y = Mathf.Lerp(seedTubeEnd.localPosition.y, seedProcessingPosition.localPosition.y, t);
					localPosition.x = Mathf.Lerp(seedTubeEnd.localPosition.x, seedProcessingPosition.localPosition.x, t2);
					gameObject.transform.localPosition = localPosition;
					float num5 = value.speed * dt;
					value.rollAngle += num5 / visualChaosSeedRadius;
					gameObject.transform.localRotation = UnityEngine.Quaternion.AngleAxis(value.rollAngle * 57.29578f, UnityEngine.Vector3.forward);
					if (value.dropProgress >= 1f)
					{
						juicerAudioSource.PlayOneShot(seedDropAudio, seedDropVolume);
					}
				}
				if (value.dropProgress >= 1f && !drainingProcessingBeaker)
				{
					gameObject.transform.localScale = UnityEngine.Vector3.one * Mathf.Lerp(seedVisualScaleRange.y, seedVisualScaleRange.x, processingAmountVisual);
				}
			}
			seedProcessingStates[i] = value;
		}
	}

	private IEnumerator OverdrivePurchaseAnimationVisual(int coresToProcess)
	{
		overdriveActive = true;
		overdriveBeepAudioSource.loop = true;
		overdriveBeepAudioSource.volume = overdriveBeepingVolume;
		overdriveBeepAudioSource.clip = overdriveBeepingAudio;
		overdriveBeepAudioSource.Play();
		int num = System.Math.Min(coresToProcess + currentPlayerData.coreCount, maxVisualChaosSeedCount);
		while (seedProcessingStates.Count < num)
		{
			DepositSeedVisual();
		}
		for (int i = 0; i < disableDuringOverdrive.Count; i++)
		{
			disableDuringOverdrive[i].gameObject.SetActive(value: false);
		}
		for (int j = 0; j < enableDuringOverdrive.Count; j++)
		{
			enableDuringOverdrive[j].gameObject.SetActive(value: true);
		}
		overdriveMeterAudioSource.PlayOneShot(overdriveFillAudio, overdriveFillVolume);
		float overdriveFillRate = 1f / overdriveFillTime;
		float maxOverdriveFill = Mathf.Clamp01(currentPlayerData.overdriveSupply + (float)coresToProcess / (float)MAX_OVERDRIVE_USES);
		while (overdriveAmount < maxOverdriveFill)
		{
			overdriveAmount = Mathf.MoveTowards(overdriveAmount, maxOverdriveFill, overdriveFillRate * Time.deltaTime);
			yield return null;
		}
		overdriveMeterAudioSource.Stop();
		int i2 = 0;
		while (i2 < coresToProcess)
		{
			float waitForSeedDepositStartTime = Time.time;
			bool flag = seedProcessingStates.Count > 0 && seedProcessingStates[0].dropProgress >= 1f;
			while (!flag && Time.time - waitForSeedDepositStartTime < 3f)
			{
				yield return null;
				flag = seedProcessingStates.Count > 0 && seedProcessingStates[0].dropProgress >= 1f;
			}
			juicerAudioSource.PlayOneShot(seedJuicingAudio, seedJuicingVolume);
			juicerOverdriveParticles.gameObject.SetActive(value: true);
			float num2 = Mathf.Clamp01(1f - processingAmount);
			float timeToProcess = num2 * overdriveProcessTime;
			float startingProcessingAmount = processingAmount;
			float num3 = num2 / (float)MAX_OVERDRIVE_USES;
			float startingOverdrive = overdriveAmount;
			float resultingOverdrive = Mathf.Clamp01(overdriveAmount - num3);
			float timeProcessing = 0f;
			while (timeProcessing < timeToProcess)
			{
				timeProcessing += Time.deltaTime;
				float t = timeProcessing / timeToProcess;
				overdriveAmount = Mathf.Lerp(startingOverdrive, resultingOverdrive, t);
				processingAmount = Mathf.Lerp(startingProcessingAmount, 1f, t);
				estimatedJuiceTimeRemaining = timeToProcess - timeProcessing;
				yield return null;
			}
			CompleteSeedVisual();
			juicerOverdriveParticles.gameObject.SetActive(value: false);
			drainingProcessingBeaker = true;
			float timeDepositing = 0f;
			while (timeDepositing < juiceDepositTime)
			{
				timeDepositing += Time.deltaTime;
				float t2 = timeDepositing / juiceDepositTime;
				processingAmount = Mathf.Lerp(1f, 0f, t2);
				yield return null;
			}
			drainingProcessingBeaker = false;
			int num4 = i2 + 1;
			i2 = num4;
		}
		if (currentPlayerData.coresPendingOverdriveProcessing == 0 && currentPlayerData.coreCount == 1)
		{
			if (seedProcessingStates.Count == 0)
			{
				DepositSeedVisual();
			}
			float timeDepositing = Time.time;
			bool flag2 = seedProcessingStates.Count > 0 && seedProcessingStates[0].dropProgress >= 1f;
			while (!flag2 && Time.time - timeDepositing < 3f)
			{
				yield return null;
				flag2 = seedProcessingStates.Count > 0 && seedProcessingStates[0].dropProgress >= 1f;
			}
			float timeProcessing = 0f;
			float resultingOverdrive = processingAmount;
			float startingOverdrive = overdriveAmount;
			float startingProcessingAmount = Mathf.Clamp01(currentPlayerData.coreProcessingPercentage - resultingOverdrive) * overdriveProcessTime;
			while (timeProcessing < startingProcessingAmount)
			{
				timeProcessing += Time.deltaTime;
				float t3 = timeProcessing / startingProcessingAmount;
				processingAmount = Mathf.Clamp01(Mathf.Lerp(resultingOverdrive, currentPlayerData.coreProcessingPercentage, t3));
				overdriveAmount = Mathf.Clamp01(Mathf.Lerp(startingOverdrive, currentPlayerData.overdriveSupply, t3));
				yield return null;
			}
		}
		for (int k = 0; k < disableDuringOverdrive.Count; k++)
		{
			disableDuringOverdrive[k].gameObject.SetActive(value: true);
		}
		for (int l = 0; l < enableDuringOverdrive.Count; l++)
		{
			enableDuringOverdrive[l].gameObject.SetActive(value: false);
		}
		overdriveLightSpinnerOff.localRotation = overdriveLightSpinnerOn.localRotation;
		overdriveBeepAudioSource.Stop();
		overdriveActive = false;
		if (StationOpenForLocalPlayer)
		{
			ProgressionManager.Instance.GetJuicerStatus();
		}
		OnStateUpdated();
	}

	public void OnResearchPointsUpdated()
	{
		int numberOfResearchPoints = toolProgressionManager.GetNumberOfResearchPoints();
		if (numberOfResearchPoints > localPlayerData.researchPoints)
		{
			GRPlayer.GetLocal().SendJuiceCollectedTelemetry(numberOfResearchPoints - localPlayerData.researchPoints, localPlayerData.coresProcessedByOverdrive);
		}
		localPlayerData.researchPoints = numberOfResearchPoints;
		if (StationOpenForLocalPlayer)
		{
			bool num = currentPlayerData.researchPoints != localPlayerData.researchPoints;
			currentPlayerData.researchPoints = localPlayerData.researchPoints;
			if (num)
			{
				ghostReactor.grManager.RequestApplySeedExtractorState(localPlayerData.coreCount, localPlayerData.coresProcessedByOverdrive, localPlayerData.researchPoints, localPlayerData.coreProcessingPercentage, localPlayerData.overdriveSupply);
				OnStateUpdated();
			}
		}
	}

	public void OnPurchaseOverdrive(bool success)
	{
		overdriveServerConfirmationPending = false;
		if (success)
		{
			GRPlayer.GetLocal().SendOverdrivePurchasedTelemetry(250, localPlayerData.coreCount);
		}
	}
}
public class GRSelectionWheel : MonoBehaviour, ITickSystemTick
{
	private List<TMP_Text> shelfNames = new List<TMP_Text>();

	public TMP_Text templateText;

	public float deltaAngle;

	public float pointerOffsetAngle;

	public float wheelTextRadius;

	public float textHorizOffset = -0.0375f;

	public float rotSpeed = 60f;

	public bool isBeingDrivenRemotely;

	public AudioSource audioSource;

	public int lastPlayedAudioTickPage = -1;

	public float wheelTextPairOffset = 0.0025f;

	public Transform rotationWheel;

	public float lastAngle = -1000f;

	[NonSerialized]
	public int targetPage;

	[NonSerialized]
	public float currentAngle;

	private float rotSpeedMult;

	public bool TickRunning { get; set; }

	public void Start()
	{
		targetPage = 0;
	}

	private void OnEnable()
	{
		TickSystem<object>.AddTickCallback(this);
	}

	private void OnDisable()
	{
		TickSystem<object>.RemoveTickCallback(this);
	}

	public void ShowText(bool showText)
	{
		foreach (TMP_Text shelfName in shelfNames)
		{
			shelfName.enabled = showText;
		}
	}

	public void InitFromNameList(List<string> shelves)
	{
		shelfNames.Clear();
		for (int i = 0; i < shelves.Count; i++)
		{
			TMP_Text tMP_Text = UnityEngine.Object.Instantiate(templateText);
			tMP_Text.text = shelves[i];
			shelfNames.Add(tMP_Text);
			tMP_Text.transform.SetParent(base.transform, worldPositionStays: false);
		}
		UpdateVisuals();
	}

	public void Tick()
	{
		if (!isBeingDrivenRemotely)
		{
			float num = deltaAngle * (float)shelfNames.Count;
			float num2 = currentAngle / deltaAngle;
			int num3 = (int)(num2 + 0.5f);
			if (rotSpeedMult == 0f)
			{
				float num4 = ((float)num3 - num2) * deltaAngle;
				currentAngle += num4 * (1f - Mathf.Exp(-20f * Time.deltaTime));
				targetPage = num3;
			}
			else
			{
				currentAngle += rotSpeedMult * Time.deltaTime * rotSpeed;
				currentAngle = Mathf.Clamp(currentAngle, (0f - deltaAngle) * 0.4f, num - deltaAngle + deltaAngle * 0.4f);
			}
		}
		int num5 = (int)(currentAngle / deltaAngle + 0.5f);
		if (lastPlayedAudioTickPage != num5)
		{
			lastPlayedAudioTickPage = num5;
			audioSource.GTPlay();
		}
		float num6 = 0.005f;
		if (System.Math.Abs(lastAngle - currentAngle) > num6)
		{
			UpdateVisuals();
		}
		lastAngle = currentAngle;
	}

	public void SetRotationSpeed(float speed)
	{
		rotSpeedMult = Mathf.Sign(speed) * Mathf.Pow(Mathf.Abs(speed), 2f);
	}

	public void SetTargetShelf(int shelf)
	{
		currentAngle += (float)(shelf - targetPage) * deltaAngle;
		targetPage = shelf;
	}

	public void SetTargetAngle(float angle)
	{
		currentAngle = angle;
	}

	public void UpdateVisuals()
	{
		rotationWheel.localRotation = UnityEngine.Quaternion.Euler(0f - currentAngle + 7.5f, 0f, 0f);
		_ = deltaAngle;
		_ = shelfNames.Count;
		float num = currentAngle / deltaAngle;
		for (int i = 0; i < shelfNames.Count; i++)
		{
			float num2 = ((float)i - num) * deltaAngle + pointerOffsetAngle;
			float f = num2 * MathF.PI / 180f;
			float num3 = Mathf.Cos(f);
			float num4 = Mathf.Sin(f);
			UnityEngine.Quaternion localRotation = UnityEngine.Quaternion.Euler(90f - num2, 180f, 0f);
			UnityEngine.Vector3 position = new UnityEngine.Vector3(textHorizOffset, num3 * wheelTextRadius, num4 * wheelTextRadius);
			shelfNames[i].transform.rotation = base.transform.TransformRotation(localRotation);
			shelfNames[i].transform.position = base.transform.TransformPoint(position);
			shelfNames[i].color = ((System.Math.Abs(num - (float)i) < 0.5f) ? Color.green : Color.white);
		}
	}
}
[Serializable]
public class GRSenseNearby
{
	public float range;

	public float hearingRange;

	public float exitRange;

	public float fov;

	[Unity.XR.CoreUtils.ReadOnly]
	public List<VRRig> rigsNearby;

	private Transform headTransform;

	private GameEntity _entity;

	private bool BossEntityPresent => GhostReactorManager.Get(_entity).GetBossEntity() != null;

	public void Setup(Transform headTransform, GameEntity entity)
	{
		rigsNearby = new List<VRRig>();
		this.headTransform = headTransform;
		_entity = entity;
	}

	public void OnHitByPlayer(int hitByActorId)
	{
		GRPlayer gRPlayer = GRPlayer.Get(hitByActorId);
		if (gRPlayer != null)
		{
			VRRig rig = gRPlayer.gamePlayer.rig;
			if (!rigsNearby.Contains(rig))
			{
				rigsNearby.Add(rig);
			}
		}
	}

	public void UpdateNearby(List<VRRig> allRigs, GRSenseLineOfSight senseLineOfSight)
	{
		UnityEngine.Vector3 position = headTransform.position;
		UnityEngine.Vector3 forward = headTransform.rotation * UnityEngine.Vector3.forward;
		RemoveNotNearby(position);
		AddNearby(position, forward, allRigs);
		RemoveNoLineOfSight(position, senseLineOfSight);
	}

	public bool IsAnyoneNearby()
	{
		if (!GhostReactorManager.AggroDisabled && rigsNearby != null)
		{
			return rigsNearby.Count > 0;
		}
		return false;
	}

	public bool IsAnyoneNearby(float range, bool ignoreBossEntity = false)
	{
		if (!ignoreBossEntity && BossEntityPresent && rigsNearby.Count > 0)
		{
			return true;
		}
		if (!IsAnyoneNearby())
		{
			return false;
		}
		UnityEngine.Vector3 position = headTransform.position;
		float num = range * range;
		for (int i = 0; i < rigsNearby.Count; i++)
		{
			if (!(rigsNearby[i] == null) && (GetRigTestLocation(rigsNearby[i]) - position).sqrMagnitude <= num)
			{
				return true;
			}
		}
		return false;
	}

	public static UnityEngine.Vector3 GetRigTestLocation(VRRig rig)
	{
		return rig.transform.position;
	}

	public void AddNearby(UnityEngine.Vector3 position, UnityEngine.Vector3 forward, List<VRRig> allRigs)
	{
		if (BossEntityPresent)
		{
			foreach (VRRig allRig in allRigs)
			{
				if (!rigsNearby.Contains(allRig))
				{
					rigsNearby.Add(allRig);
				}
			}
			return;
		}
		float num = range * range;
		float num2 = Mathf.Cos(fov * (MathF.PI / 180f));
		for (int i = 0; i < allRigs.Count; i++)
		{
			VRRig vRRig = allRigs[i];
			GRPlayer component = vRRig.GetComponent<GRPlayer>();
			if (component.State == GRPlayer.GRPlayerState.Ghost || component.InStealthMode || rigsNearby.Contains(vRRig))
			{
				continue;
			}
			UnityEngine.Vector3 vector = GetRigTestLocation(vRRig) - position;
			float sqrMagnitude = vector.sqrMagnitude;
			float num3 = hearingRange * hearingRange;
			if (!(sqrMagnitude < num3))
			{
				if (!(sqrMagnitude < num))
				{
					continue;
				}
				if (sqrMagnitude > 0f)
				{
					float num4 = Mathf.Sqrt(sqrMagnitude);
					if (UnityEngine.Vector3.Dot(vector / num4, forward) < num2)
					{
						continue;
					}
				}
			}
			rigsNearby.Add(vRRig);
		}
	}

	public void RemoveNotNearby(UnityEngine.Vector3 position)
	{
		if (BossEntityPresent)
		{
			return;
		}
		float num = exitRange * exitRange;
		for (int i = 0; i < rigsNearby.Count; i++)
		{
			VRRig vRRig = rigsNearby[i];
			if (vRRig != null)
			{
				GRPlayer component = vRRig.GetComponent<GRPlayer>();
				if ((GetRigTestLocation(vRRig) - position).sqrMagnitude <= num && component.State != GRPlayer.GRPlayerState.Ghost && !component.InStealthMode)
				{
					continue;
				}
			}
			rigsNearby.RemoveAt(i);
			i--;
		}
	}

	public void RemoveNoLineOfSight(UnityEngine.Vector3 headPos, GRSenseLineOfSight senseLineOfSight)
	{
		if (BossEntityPresent)
		{
			return;
		}
		for (int i = 0; i < rigsNearby.Count; i++)
		{
			UnityEngine.Vector3 rigTestLocation = GetRigTestLocation(rigsNearby[i]);
			if (!senseLineOfSight.HasLineOfSight(headPos, rigTestLocation))
			{
				rigsNearby.RemoveAt(i);
				i--;
			}
		}
	}

	public VRRig PickClosest(out float outDistanceSq)
	{
		UnityEngine.Vector3 position = headTransform.position;
		float num = float.MaxValue;
		VRRig result = null;
		for (int i = 0; i < rigsNearby.Count; i++)
		{
			float sqrMagnitude = (GetRigTestLocation(rigsNearby[i]) - position).sqrMagnitude;
			if (sqrMagnitude < num)
			{
				num = sqrMagnitude;
				result = rigsNearby[i];
			}
		}
		outDistanceSq = num;
		return result;
	}
}
[Serializable]
public class GRSenseLineOfSight
{
	public enum RaycastMode
	{
		Geometry,
		Navmesh,
		GeometryAndNavMesh,
		GeometryOrNavMesh
	}

	public float sightDist;

	public LayerMask visibilityMask;

	public RaycastMode rayCastMode;

	public static RaycastHit[] visibilityHits = new RaycastHit[16];

	public bool HasLineOfSight(UnityEngine.Vector3 headPos, UnityEngine.Vector3 targetPos)
	{
		return HasLineOfSight(headPos, targetPos, sightDist, visibilityMask.value, rayCastMode);
	}

	public static bool HasLineOfSight(UnityEngine.Vector3 headPos, UnityEngine.Vector3 targetPos, float sightDist, int layerMask, RaycastMode rayCastMode = RaycastMode.Geometry)
	{
		switch (rayCastMode)
		{
		case RaycastMode.Geometry:
			return HasGeoLineOfSight(headPos, targetPos, sightDist, layerMask);
		case RaycastMode.Navmesh:
			return HasNavmeshLineOfSight(headPos, targetPos, sightDist);
		case RaycastMode.GeometryAndNavMesh:
			if (HasGeoLineOfSight(headPos, targetPos, sightDist, layerMask))
			{
				return HasNavmeshLineOfSight(headPos, targetPos, sightDist);
			}
			return false;
		case RaycastMode.GeometryOrNavMesh:
			if (!HasNavmeshLineOfSight(headPos, targetPos, sightDist))
			{
				return HasGeoLineOfSight(headPos, targetPos, sightDist, layerMask);
			}
			return true;
		default:
			return false;
		}
	}

	public static bool HasGeoLineOfSight(UnityEngine.Vector3 headPos, UnityEngine.Vector3 targetPos, float sightDist, int layerMask)
	{
		float num = UnityEngine.Vector3.Distance(targetPos, headPos);
		if (num > sightDist)
		{
			return false;
		}
		return Physics.RaycastNonAlloc(new Ray(headPos, targetPos - headPos), visibilityHits, Mathf.Min(num, sightDist), layerMask, QueryTriggerInteraction.Ignore) < 1;
	}

	public static bool HasNavmeshLineOfSight(UnityEngine.Vector3 headPos, UnityEngine.Vector3 targetPos, float sightDist)
	{
		if ((targetPos - headPos).sqrMagnitude > sightDist * sightDist)
		{
			return false;
		}
		NavMeshHit hit2;
		if (NavMesh.SamplePosition(headPos, out var hit, 1f, -1))
		{
			return !NavMesh.Raycast(hit.position, targetPos, out hit2, -1);
		}
		return false;
	}
}
public class GRSentientCore : MonoBehaviour, IGRSleepableEntity
{
	public enum SentientCoreState
	{
		Asleep,
		Awake,
		JumpInitiated,
		JumpAnticipation,
		Jumping,
		Held,
		HeldAlert,
		AttachedToPlayer,
		Dropped
	}

	public GameEntity gameEntity;

	public UnityEngine.Vector2 jumpAngleMinMax = new UnityEngine.Vector2(30f, 60f);

	public float jumpSpeed = 3f;

	public float jumpGravityAccel = 10f;

	public float maxSpeed = 5f;

	public float radius = 0.14f;

	public float jumpAnticipationTime = 1f;

	public float jumpCooldownTime = 2f;

	public bool useSurfaceNormalForGravityDirection = true;

	public UnityEngine.Vector2 timeRangeBetweenAlerts = new UnityEngine.Vector2(7f, 12f);

	public float timeUntilFirstAlert = 0.5f;

	public float alertNoiseEventMagnitude = 1f;

	public AbilitySound jumpSound;

	public AbilitySound landSound;

	public AbilitySound alertEnemiesSound;

	public float wakeupRadius = 3f;

	public bool debugDraw;

	public Transform visualCore;

	public ParticleSystem trailFX;

	private UnityEngine.Vector3 surfaceNormal = UnityEngine.Vector3.up;

	private UnityEngine.Vector3 jumpDirection = UnityEngine.Vector3.up;

	private UnityEngine.Vector3 jumpStartPosition;

	private UnityEngine.Vector3 jumpVelocity;

	private float jumpStartTime;

	private Rigidbody rb;

	private float timeUntilNextAlert = 7f;

	private float enemyAlertDuration = 1f;

	private bool isPlayingAlert;

	private bool sleepRequested;

	[Unity.XR.CoreUtils.ReadOnly]
	public SentientCoreState localState = SentientCoreState.Awake;

	private float localStateStartTime;

	public UnityEngine.Vector3 Position => base.transform.position;

	public float WakeUpRadius => wakeupRadius;

	private void Start()
	{
		rb = GetComponent<Rigidbody>();
		GhostReactor.instance.sleepableEntities.Add(this);
		gameEntity.OnStateChanged += OnStateChanged;
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(OnGrabbed));
		GameEntity obj2 = gameEntity;
		obj2.OnReleased = (Action)Delegate.Combine(obj2.OnReleased, new Action(OnReleased));
		GameEntity obj3 = gameEntity;
		obj3.OnSnapped = (Action)Delegate.Combine(obj3.OnSnapped, new Action(OnSnapped));
		GameEntity obj4 = gameEntity;
		obj4.OnDetached = (Action)Delegate.Combine(obj4.OnDetached, new Action(OnDetached));
		Sleep();
	}

	private void OnDestroy()
	{
		if (GhostReactor.instance != null)
		{
			GhostReactor.instance.sleepableEntities.Remove(this);
		}
		if (gameEntity != null)
		{
			gameEntity.OnStateChanged -= OnStateChanged;
			GameEntity obj = gameEntity;
			obj.OnGrabbed = (Action)Delegate.Remove(obj.OnGrabbed, new Action(OnGrabbed));
			GameEntity obj2 = gameEntity;
			obj2.OnReleased = (Action)Delegate.Remove(obj2.OnReleased, new Action(OnReleased));
			GameEntity obj3 = gameEntity;
			obj3.OnSnapped = (Action)Delegate.Remove(obj3.OnSnapped, new Action(OnSnapped));
			GameEntity obj4 = gameEntity;
			obj4.OnDetached = (Action)Delegate.Remove(obj4.OnDetached, new Action(OnDetached));
		}
	}

	public bool IsSleeping()
	{
		return gameEntity.GetState() == 0;
	}

	public void WakeUp()
	{
		if (gameEntity.IsAuthority() && IsSleeping())
		{
			gameEntity.RequestState(gameEntity.id, 1L);
		}
		if (localState == SentientCoreState.Asleep)
		{
			localState = SentientCoreState.Awake;
			localStateStartTime = Time.time;
		}
		sleepRequested = false;
		base.enabled = true;
	}

	public void Sleep()
	{
		sleepRequested = true;
	}

	private void OnStateChanged(long prevState, long nextState)
	{
		if ((int)nextState == 0)
		{
			sleepRequested = false;
		}
		else if (!base.enabled)
		{
			WakeUp();
		}
		SetState((SentientCoreState)nextState);
	}

	private void OnGrabbed()
	{
		WakeUp();
		SetState(SentientCoreState.Held);
		timeUntilNextAlert = Mathf.Min(timeUntilFirstAlert, timeUntilNextAlert);
	}

	private void OnReleased()
	{
		SetState(SentientCoreState.Dropped);
	}

	private void OnSnapped()
	{
		SetState(SentientCoreState.AttachedToPlayer);
	}

	private void OnDetached()
	{
		SetState(SentientCoreState.Dropped);
	}

	private void Update()
	{
		if (debugDraw)
		{
			DebugUtil.DrawSphere(base.transform.position, 0.15f, 12, 12, Color.cyan);
		}
		if (gameEntity.IsAuthority())
		{
			AuthorityUpdate();
		}
		SharedUpdate();
	}

	private void AuthorityUpdate()
	{
		if (trailFX != null)
		{
			if (gameEntity.snappedByActorNumber != -1 || gameEntity.heldByActorNumber != -1)
			{
				if (trailFX.isPlaying)
				{
					trailFX.Stop();
				}
			}
			else if (!trailFX.isPlaying)
			{
				trailFX.Play();
			}
		}
		switch (localState)
		{
		case SentientCoreState.Awake:
			if (sleepRequested)
			{
				sleepRequested = false;
				SetState(SentientCoreState.Asleep);
			}
			if (gameEntity.heldByActorNumber != -1)
			{
				SetState(SentientCoreState.Held);
			}
			else if (!sleepRequested && Time.time > localStateStartTime + jumpCooldownTime)
			{
				AuthorityInitiateJump();
			}
			break;
		case SentientCoreState.JumpInitiated:
			if (sleepRequested)
			{
				sleepRequested = false;
				SetState(SentientCoreState.Asleep);
			}
			break;
		case SentientCoreState.Held:
			timeUntilNextAlert -= Time.deltaTime;
			if (timeUntilNextAlert < 0f)
			{
				timeUntilNextAlert = UnityEngine.Random.Range(timeRangeBetweenAlerts.x, timeRangeBetweenAlerts.y);
				SetState(SentientCoreState.HeldAlert);
			}
			break;
		case SentientCoreState.AttachedToPlayer:
			timeUntilNextAlert -= Time.deltaTime;
			if (timeUntilNextAlert < 0f)
			{
				timeUntilNextAlert = UnityEngine.Random.Range(timeRangeBetweenAlerts.x, timeRangeBetweenAlerts.y);
				alertEnemiesSound.Play(null);
				GRNoiseEventManager.instance.AddNoiseEvent(base.transform.position, alertNoiseEventMagnitude, enemyAlertDuration);
			}
			break;
		case SentientCoreState.Asleep:
		case SentientCoreState.JumpAnticipation:
		case SentientCoreState.Jumping:
		case SentientCoreState.HeldAlert:
		case SentientCoreState.Dropped:
			break;
		}
	}

	private void SharedUpdate()
	{
		switch (localState)
		{
		default:
			base.enabled = false;
			break;
		case SentientCoreState.Awake:
			if (visualCore != null && visualCore.transform.localScale != UnityEngine.Vector3.one)
			{
				visualCore.transform.localScale = UnityEngine.Vector3.one;
				visualCore.transform.localPosition = UnityEngine.Vector3.zero;
				visualCore.transform.localRotation = UnityEngine.Quaternion.identity;
			}
			break;
		case SentientCoreState.JumpAnticipation:
			if (debugDraw)
			{
				DrawJumpPath(Color.yellow);
			}
			if (Time.time > jumpStartTime)
			{
				SetState(SentientCoreState.Jumping);
				jumpSound.Play(null);
				if (visualCore != null)
				{
					visualCore.transform.localScale = UnityEngine.Vector3.one;
					visualCore.transform.localPosition = UnityEngine.Vector3.zero;
					visualCore.transform.localRotation = UnityEngine.Quaternion.identity;
				}
			}
			else
			{
				UnityEngine.Vector3 normalized = (surfaceNormal + jumpDirection).normalized;
				float num = (jumpStartTime - Time.time) / jumpAnticipationTime * 0.25f + 0.75f;
				float num2 = Mathf.Sqrt(1f / num);
				visualCore.transform.localScale = new UnityEngine.Vector3(num2, num, num2);
				visualCore.transform.position = visualCore.parent.position - normalized * (1f - num) * radius;
				visualCore.transform.rotation = UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.up, normalized);
			}
			break;
		case SentientCoreState.Jumping:
		{
			if (debugDraw)
			{
				DrawJumpPath(Color.yellow);
			}
			float deltaTime2 = Time.deltaTime;
			UnityEngine.Vector3 vector3 = base.transform.position + jumpVelocity * deltaTime2;
			UnityEngine.Vector3 vector4 = (useSurfaceNormalForGravityDirection ? (-surfaceNormal) : UnityEngine.Vector3.down);
			jumpVelocity += vector4 * (jumpGravityAccel * deltaTime2);
			float magnitude2 = jumpVelocity.magnitude;
			if (magnitude2 > maxSpeed && maxSpeed > 0f)
			{
				jumpVelocity *= maxSpeed / magnitude2;
			}
			float magnitude3 = (vector3 - base.transform.position).magnitude;
			UnityEngine.Vector3 vector5 = ((magnitude3 > 0.001f) ? ((vector3 - base.transform.position) / magnitude3) : UnityEngine.Vector3.zero);
			if (Physics.SphereCast(new Ray(base.transform.position, vector5), radius, out var hitInfo2, magnitude3, GTPlayer.Instance.locomotionEnabledLayers.value, QueryTriggerInteraction.Ignore))
			{
				vector3 = base.transform.position + vector5 * hitInfo2.distance;
				surfaceNormal = hitInfo2.normal;
				SetState(SentientCoreState.Awake);
				landSound.Play(null);
			}
			base.transform.position = vector3;
			break;
		}
		case SentientCoreState.Held:
		{
			GRPlayer gRPlayer = GRPlayer.Get(gameEntity.heldByActorNumber);
			if (gRPlayer != null)
			{
				gRPlayer.IncrementSynchronizedSessionStat(GRPlayer.SynchronizedSessionStat.TimeChaosExposure, Time.deltaTime);
			}
			isPlayingAlert = false;
			break;
		}
		case SentientCoreState.HeldAlert:
			if (!isPlayingAlert)
			{
				isPlayingAlert = true;
				alertEnemiesSound.Play(null);
				GRNoiseEventManager.instance.AddNoiseEvent(base.transform.position, alertNoiseEventMagnitude, enemyAlertDuration);
			}
			if (Time.time - localStateStartTime > enemyAlertDuration)
			{
				SetState(SentientCoreState.Held);
			}
			break;
		case SentientCoreState.AttachedToPlayer:
		{
			GRPlayer gRPlayer2 = GRPlayer.Get(gameEntity.snappedByActorNumber);
			if (gRPlayer2 != null)
			{
				gRPlayer2.IncrementSynchronizedSessionStat(GRPlayer.SynchronizedSessionStat.TimeChaosExposure, Time.deltaTime);
			}
			break;
		}
		case SentientCoreState.Dropped:
		{
			float deltaTime = Time.deltaTime;
			UnityEngine.Vector3 vector = base.transform.position + rb.linearVelocity * deltaTime;
			float magnitude = (vector - base.transform.position).magnitude;
			UnityEngine.Vector3 vector2 = ((magnitude > 0.001f) ? ((vector - base.transform.position) / magnitude) : UnityEngine.Vector3.zero);
			if (Physics.SphereCast(new Ray(base.transform.position, vector2), radius, out var hitInfo, magnitude, GTPlayer.Instance.locomotionEnabledLayers.value, QueryTriggerInteraction.Ignore))
			{
				vector = base.transform.position + vector2 * hitInfo.distance;
				surfaceNormal = hitInfo.normal;
				base.transform.position = vector;
				rb.isKinematic = true;
				SetState(SentientCoreState.Awake);
			}
			break;
		}
		}
	}

	private void SetState(SentientCoreState nextState)
	{
		if (localState != nextState)
		{
			localState = nextState;
			localStateStartTime = Time.time;
			if (gameEntity.IsAuthority())
			{
				gameEntity.RequestState(gameEntity.id, (long)nextState);
			}
		}
	}

	public void PerformJump(UnityEngine.Vector3 startPos, UnityEngine.Vector3 normal, UnityEngine.Vector3 direction, double jumpNetworkTime)
	{
		if (PhotonNetwork.InRoom)
		{
			if (!base.enabled || IsSleeping())
			{
				WakeUp();
			}
			base.transform.position = startPos;
			float num = Mathf.Clamp((float)(jumpNetworkTime - PhotonNetwork.Time), 0f, jumpAnticipationTime);
			jumpStartTime = Time.time + num;
			jumpDirection = direction;
			jumpDirection.Normalize();
			jumpStartPosition = startPos;
			surfaceNormal = normal;
			jumpVelocity = jumpDirection * jumpSpeed;
			SetState(SentientCoreState.JumpAnticipation);
		}
	}

	private void DrawJumpPath(Color pathColor)
	{
		DebugUtil.DrawLine(jumpStartPosition, jumpStartPosition + surfaceNormal * 0.15f, Color.cyan);
		float num = 0.016666f;
		int num2 = 100;
		UnityEngine.Vector3 vector = jumpStartPosition;
		UnityEngine.Vector3 vector2 = jumpDirection * jumpSpeed;
		for (int i = 0; i < num2; i++)
		{
			UnityEngine.Vector3 vector3 = vector + vector2 * num;
			vector2 += -surfaceNormal * (jumpGravityAccel * num);
			float magnitude = (vector3 - vector).magnitude;
			UnityEngine.Vector3 direction = ((magnitude > 0.001f) ? ((vector3 - vector) / magnitude) : UnityEngine.Vector3.zero);
			if (Physics.SphereCast(new Ray(vector, direction), radius, out var hitInfo, magnitude, GTPlayer.Instance.locomotionEnabledLayers.value, QueryTriggerInteraction.Ignore))
			{
				vector3 = hitInfo.point;
				DebugUtil.DrawLine(vector, vector3, pathColor);
				DebugUtil.DrawLine(vector3, vector3 + hitInfo.normal * 0.15f, Color.cyan);
				DebugUtil.DrawSphere(hitInfo.point, 0.1f, 12, 12, pathColor);
				break;
			}
			DebugUtil.DrawLine(vector, vector3, pathColor);
			vector = vector3;
		}
	}

	public void AuthorityInitiateJump()
	{
		if (gameEntity.IsAuthority())
		{
			UnityEngine.Vector3 vector = UnityEngine.Random.insideUnitSphere;
			if (UnityEngine.Vector3.Dot(vector, surfaceNormal) > 0.99f)
			{
				vector = new UnityEngine.Vector3(surfaceNormal.y, surfaceNormal.z, surfaceNormal.x);
			}
			float num = UnityEngine.Random.Range(jumpAngleMinMax.x, jumpAngleMinMax.y);
			UnityEngine.Vector3 direction = UnityEngine.Quaternion.AngleAxis(90f - num, UnityEngine.Vector3.Cross(surfaceNormal, vector)) * surfaceNormal;
			direction.Normalize();
			SetState(SentientCoreState.JumpInitiated);
			gameEntity.manager.ghostReactorManager.RequestSentientCorePerformJump(gameEntity, base.transform.position, surfaceNormal, direction, jumpAnticipationTime);
		}
	}
}
