public class GRSummonerEgg : MonoBehaviour
{
	public GameEntity entity;

	public AudioSource hatchAudio;

	public AbilitySound hatchSound;

	public GameEntity entityPrefabToSpawn;

	public GRBreakableItemSpawnConfig lootTableToSpawn;

	public UnityEngine.Vector3 spawnOffset = new UnityEngine.Vector3(0f, 0f, 0.3f);

	public float minHatchTime = 3f;

	public float maxHatchTime = 6f;

	private float hatchTime = 2f;

	private GRSummonedEntity summonedEntity;

	private void Awake()
	{
		summonedEntity = GetComponent<GRSummonedEntity>();
	}

	private void Start()
	{
		hatchTime = UnityEngine.Random.Range(minHatchTime, maxHatchTime);
		Rigidbody component = GetComponent<Rigidbody>();
		if (component != null)
		{
			component.isKinematic = false;
			component.position = base.transform.position;
			component.rotation = base.transform.rotation;
			component.linearVelocity = UnityEngine.Vector3.up * 2f;
			component.angularVelocity = UnityEngine.Vector3.zero;
			component.constraints |= (RigidbodyConstraints)10;
		}
		Invoke("HatchEgg", hatchTime);
	}

	public void HatchEgg()
	{
		GRBreakable component = GetComponent<GRBreakable>();
		if ((bool)component)
		{
			component.BreakLocal();
		}
		if (entity.IsAuthority())
		{
			UnityEngine.Vector3 position = entity.transform.position + spawnOffset;
			UnityEngine.Quaternion identity = UnityEngine.Quaternion.identity;
			GameEntityManager gameEntityManager = GhostReactorManager.Get(entity).gameEntityManager;
			GameEntity gameEntity = entityPrefabToSpawn;
			if (lootTableToSpawn != null)
			{
				lootTableToSpawn.TryForRandomItem(entity, out gameEntity);
			}
			gameEntityManager.RequestCreateItem(gameEntity.name.GetStaticHash(), position, identity, 0L, (summonedEntity != null) ? summonedEntity.GetSummonerID() : GameEntityId.Invalid);
		}
		Invoke("DestroySelf", 2f);
		hatchSound.Play(hatchAudio);
	}

	public void DestroySelf()
	{
		if (entity.IsAuthority())
		{
			entity.manager.RequestDestroyItem(entity.id);
		}
	}
}
public static class MaterialUtils
{
	public static string GetTrimmedMaterialName(Material material)
	{
		return material.name.Replace(" (Instance)", "").Trim();
	}

	public static void SwapMaterial(MeshAndMaterials meshAndMaterial, bool isOnToOff)
	{
		List<Material> value;
		using (UnityEngine.Rendering.ListPool<Material>.Get(out value))
		{
			meshAndMaterial.meshRenderer.GetSharedMaterials(value);
			for (int i = 0; i < value.Count; i++)
			{
				string trimmedMaterialName = GetTrimmedMaterialName(value[i]);
				string text = ((!isOnToOff) ? ((meshAndMaterial.offMaterial != null) ? GetTrimmedMaterialName(meshAndMaterial.offMaterial) : null) : ((meshAndMaterial.onMaterial != null) ? GetTrimmedMaterialName(meshAndMaterial.onMaterial) : null));
				if (text != null && trimmedMaterialName == text)
				{
					value[i] = (isOnToOff ? meshAndMaterial.offMaterial : meshAndMaterial.onMaterial);
				}
			}
			meshAndMaterial.meshRenderer.SetSharedMaterials(value);
		}
	}
}
