public class GRTool : MonoBehaviour, IGameEntitySerialize, IGameEntityComponent, IGameEntityDebugComponent
{
	public enum GRToolType
	{
		None,
		Club,
		Collector,
		Flash,
		Lantern,
		Revive,
		ShieldGun,
		DirectionalShield,
		DockWrist,
		EnergyEfficiency,
		DropPod,
		HockeyStick,
		StatusWatch,
		RattyBackpack
	}

	[Serializable]
	public class Upgrade
	{
		public GRToolProgressionManager.ToolParts UpgradeType;

		public int Slot;

		public List<GameObject> VisibleItem;

		public List<GRBonusEntry> bonusEffects;
	}

	[Serializable]
	public class UpgradeSlot
	{
		public List<GameObject> DefaultVisibleItems;

		[NonSerialized]
		public Upgrade installedItem;
	}

	public delegate void EnergyChangeEvent(GRTool tool, int energyChange, GameEntityId chargingEntityId);

	public delegate void ToolUpgradedEvent(GRTool tool);

	public GRAttributes attributes;

	public List<Upgrade> upgrades;

	public List<UpgradeSlot> upgradeSlots = new List<UpgradeSlot>();

	public List<GRMeterEnergy> energyMeters;

	public GameEntity gameEntity;

	public GRToolType toolType;

	[Unity.Collections.ReadOnly]
	public int energy;

	public GameObject UpgradeFXNode;

	private List<MeshFilter> reservedMeshFilterSearchList = new List<MeshFilter>(32);

	private List<SkinnedMeshRenderer> reservedMeshFilterSearchListSkinned = new List<SkinnedMeshRenderer>(32);

	private Upgrade upgradeListsAreValidFor;

	public event EnergyChangeEvent OnEnergyChange;

	public event ToolUpgradedEvent onToolUpgraded;

	private void Awake()
	{
	}

	private void Start()
	{
		if (gameEntity == null)
		{
			gameEntity = GetComponent<GameEntity>();
		}
		RefreshMeters();
	}

	public void OnEntityInit()
	{
		energy = GetEnergyStart();
		GhostReactor.ToolEntityCreateData toolEntityCreateData = GhostReactor.ToolEntityCreateData.Unpack(gameEntity.createData);
		GhostReactorManager ghostReactorManager = GhostReactorManager.Get(gameEntity);
		if (ghostReactorManager != null)
		{
			GRToolUpgradePurchaseStationFull toolUpgradeStationFullForIndex = ghostReactorManager.GetToolUpgradeStationFullForIndex(toolEntityCreateData.stationIndex);
			if (toolUpgradeStationFullForIndex != null)
			{
				toolUpgradeStationFullForIndex.InitLinkedEntity(gameEntity);
			}
		}
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	public int GetEnergyMax()
	{
		return attributes.CalculateFinalValueForAttribute(GRAttributeType.EnergyMax);
	}

	public int GetEnergyUseCost()
	{
		return attributes.CalculateFinalValueForAttribute(GRAttributeType.EnergyUseCost);
	}

	public int GetEnergyStart()
	{
		if (!attributes.HasValueForAttribute(GRAttributeType.EnergyStart))
		{
			return 0;
		}
		return attributes.CalculateFinalValueForAttribute(GRAttributeType.EnergyStart);
	}

	private void OnEnable()
	{
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(GrabbedByPlayer));
	}

	private void OnDisable()
	{
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Remove(obj.OnGrabbed, new Action(GrabbedByPlayer));
	}

	public void RefillEnergy(int count, GameEntityId chargingEntityId)
	{
		SetEnergyInternal(energy + count, chargingEntityId);
	}

	public void RefillEnergy()
	{
		SetEnergyInternal(GetEnergyMax(), GameEntityId.Invalid);
	}

	public void UseEnergy()
	{
		SetEnergyInternal(energy - GetEnergyUseCost(), GameEntityId.Invalid);
	}

	public bool HasEnoughEnergy()
	{
		return energy >= GetEnergyUseCost();
	}

	public void SetEnergy(int newEnergy)
	{
		SetEnergyInternal(newEnergy, GameEntityId.Invalid);
	}

	public bool IsEnergyFull()
	{
		return energy >= GetEnergyMax();
	}

	private void SetEnergyInternal(int value, GameEntityId chargingEntityId)
	{
		int num = energy;
		energy = Mathf.Clamp(value, 0, GetEnergyMax());
		int energyChange = energy - num;
		this.OnEnergyChange?.Invoke(this, energyChange, chargingEntityId);
		RefreshMeters();
	}

	public void RefreshMeters()
	{
		for (int i = 0; i < energyMeters.Count; i++)
		{
			energyMeters[i].Refresh();
		}
	}

	public bool HasUpgradeInstalled(GRToolProgressionManager.ToolParts upgradeID)
	{
		for (int i = 0; i < upgradeSlots.Count; i++)
		{
			if (upgradeSlots[i].installedItem != null && upgradeSlots[i].installedItem.UpgradeType == upgradeID)
			{
				return true;
			}
		}
		return false;
	}

	public Upgrade FindMatchingUpgrade(GRToolProgressionManager.ToolParts upgradeID)
	{
		for (int i = 0; i < upgrades.Count; i++)
		{
			if (upgrades[i].UpgradeType == upgradeID)
			{
				return upgrades[i];
			}
		}
		return null;
	}

	public float GetPointDistanceToUpgrade(UnityEngine.Vector3 point, Upgrade upgrade)
	{
		if (upgrade.VisibleItem.Count < 1)
		{
			return -1f;
		}
		if (upgradeListsAreValidFor != upgrade)
		{
			reservedMeshFilterSearchList.Clear();
			upgrade.VisibleItem[0].GetComponentsInChildren(reservedMeshFilterSearchList);
			reservedMeshFilterSearchListSkinned.Clear();
			upgrade.VisibleItem[0].GetComponentsInChildren(includeInactive: false, reservedMeshFilterSearchListSkinned);
			upgradeListsAreValidFor = upgrade;
		}
		float num = float.MaxValue;
		foreach (MeshFilter reservedMeshFilterSearch in reservedMeshFilterSearchList)
		{
			UnityEngine.Vector3 vector = reservedMeshFilterSearch.transform.InverseTransformPoint(point);
			Bounds bounds = reservedMeshFilterSearch.sharedMesh.bounds;
			UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(Mathf.Clamp(vector.x, bounds.min.x, bounds.max.x), Mathf.Clamp(vector.y, bounds.min.y, bounds.max.y), Mathf.Clamp(vector.z, bounds.min.z, bounds.max.z));
			UnityEngine.Vector3 vector3 = vector - vector2;
			float sqrMagnitude = reservedMeshFilterSearch.transform.TransformVector(vector3).sqrMagnitude;
			if (sqrMagnitude < num)
			{
				num = sqrMagnitude;
			}
		}
		if (reservedMeshFilterSearchListSkinned != null)
		{
			foreach (SkinnedMeshRenderer item in reservedMeshFilterSearchListSkinned)
			{
				UnityEngine.Vector3 vector4 = item.transform.InverseTransformPoint(point);
				Bounds localBounds = item.localBounds;
				UnityEngine.Vector3 vector5 = new UnityEngine.Vector3(Mathf.Clamp(vector4.x, localBounds.min.x, localBounds.max.x), Mathf.Clamp(vector4.y, localBounds.min.y, localBounds.max.y), Mathf.Clamp(vector4.z, localBounds.min.z, localBounds.max.z));
				UnityEngine.Vector3 vector6 = vector4 - vector5;
				float sqrMagnitude2 = item.transform.TransformVector(vector6).sqrMagnitude;
				if (sqrMagnitude2 < num)
				{
					num = sqrMagnitude2;
				}
			}
		}
		if (num == float.MaxValue)
		{
			return UnityEngine.Vector3.Distance(point, upgrade.VisibleItem[0].transform.position);
		}
		return Mathf.Sqrt(num);
	}

	public Transform GetUpgradeAttachTransform(Upgrade upgrade)
	{
		if (upgrade.VisibleItem.Count < 1)
		{
			return null;
		}
		return upgrade.VisibleItem[0].transform;
	}

	public void UpgradeTool(GRToolProgressionManager.ToolParts upgradeID)
	{
		for (int i = 0; i < upgrades.Count; i++)
		{
			if (upgrades[i].UpgradeType != upgradeID)
			{
				continue;
			}
			ClearUpgradeSlot(upgrades[i].Slot);
			for (int j = 0; j < upgrades[i].VisibleItem.Count; j++)
			{
				upgrades[i].VisibleItem[j].SetActive(value: true);
			}
			for (int k = 0; k < upgradeSlots[upgrades[i].Slot].DefaultVisibleItems.Count; k++)
			{
				upgradeSlots[upgrades[i].Slot].DefaultVisibleItems[k].SetActive(value: false);
			}
			foreach (GRBonusEntry bonusEffect in upgrades[i].bonusEffects)
			{
				attributes.AddBonus(bonusEffect);
			}
			upgradeSlots[upgrades[i].Slot].installedItem = upgrades[i];
			if (UpgradeFXNode != null && upgrades[i].VisibleItem.Count > 0)
			{
				UpgradeFXNode.transform.position = upgrades[i].VisibleItem[0].transform.position;
				UpgradeFXNode.transform.rotation = upgrades[i].VisibleItem[0].transform.rotation;
				ParticleSystem componentInChildren = UpgradeFXNode.GetComponentInChildren<ParticleSystem>();
				AudioSource componentInChildren2 = UpgradeFXNode.GetComponentInChildren<AudioSource>();
				if (componentInChildren != null)
				{
					componentInChildren.Play();
				}
				if (componentInChildren2 != null)
				{
					componentInChildren2.Play();
				}
			}
		}
		this.onToolUpgraded?.Invoke(this);
	}

	public void ClearUpgradeSlot(int slot)
	{
		if (upgradeSlots[slot].installedItem == null)
		{
			return;
		}
		for (int i = 0; i < upgradeSlots[slot].installedItem.VisibleItem.Count; i++)
		{
			upgradeSlots[slot].installedItem.VisibleItem[i].SetActive(value: false);
		}
		foreach (GRBonusEntry bonusEffect in upgradeSlots[slot].installedItem.bonusEffects)
		{
			attributes.RemoveBonus(bonusEffect);
		}
		for (int j = 0; j < upgradeSlots[slot].DefaultVisibleItems.Count; j++)
		{
			upgradeSlots[slot].DefaultVisibleItems[j].SetActive(value: true);
		}
	}

	public void OnGameEntitySerialize(BinaryWriter writer)
	{
		writer.Write(upgradeSlots.Count);
		for (int i = 0; i < upgradeSlots.Count; i++)
		{
			if (upgradeSlots[i] != null)
			{
				if (upgradeSlots[i].installedItem != null)
				{
					writer.Write(upgradeSlots[i].installedItem.UpgradeType.ToString());
				}
				else
				{
					writer.Write("");
				}
			}
			else
			{
				writer.Write("");
			}
		}
		writer.Write(energy);
	}

	public void OnGameEntityDeserialize(BinaryReader reader)
	{
		int num = reader.ReadInt32();
		for (int i = 0; i < num; i++)
		{
			GRToolProgressionManager.ToolParts result = GRToolProgressionManager.ToolParts.None;
			if (Enum.TryParse<GRToolProgressionManager.ToolParts>(reader.ReadString(), out result))
			{
				UpgradeTool(result);
			}
		}
		int num2 = reader.ReadInt32();
		SetEnergy(num2);
	}

	public void GrabbedByPlayer()
	{
		if (gameEntity.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber)
		{
			GRPlayer gRPlayer = GRPlayer.Get(gameEntity.heldByActorNumber);
			if ((bool)gRPlayer)
			{
				gRPlayer.GrabbedItem(gameEntity.id, base.gameObject.name);
			}
		}
	}

	public void GetDebugTextLines(out List<string> strings)
	{
		strings = new List<string>();
		strings.Add($"Tool Energy: <color=\"yellow\">{energy}<color=\"white\"> ");
	}
}
public class GRToolClub : MonoBehaviourTick, IGameHitter, IGameEntityDebugComponent, IGameEntityComponent
{
	private enum State
	{
		Idle,
		Extended
	}

	public GameEntity gameEntity;

	public GameHitter gameHitter;

	public GRTool tool;

	public Rigidbody rigidBody;

	public AudioSource audioSource;

	public AudioSource humAudioSource;

	public List<ParticleSystem> humParticleEffects = new List<ParticleSystem>();

	public GRAttributes attributes;

	public AudioClip extendAudio;

	public float extendVolume = 0.5f;

	public AudioClip retractAudio;

	public float retractVolume = 0.5f;

	public GameHitFx noPowerFx;

	public GameHitFx poweredImpactFx;

	public GameHitFx upgrade1ImpactVFX;

	public GameHitFx upgrade2ImpactVFX;

	public GameHitFx upgrade3ImpactVFX;

	public GRAttributeType noPowerAttribute;

	public GRAttributeType poweredAttribute;

	public float minHitSpeed = 2.25f;

	public GameObject dullLight;

	public List<MeshAndMaterials> meshAndMaterials;

	public Transform retractableSection;

	public Collider idleCollider;

	public Collider extendedCollider;

	public float retractableSectionMin = -0.31f;

	public float retractableSectionMax;

	public float extensionTime = 0.15f;

	[Header("Haptic")]
	public AbilityHaptic openHaptic;

	public AbilityHaptic closeHaptic;

	private float extendedAmount;

	private State state;

	private void Awake()
	{
		retractableSection.localPosition = new UnityEngine.Vector3(0f, 0f, 0f);
	}

	public new void OnEnable()
	{
		base.OnEnable();
		SetExtendedAmount(0f);
		gameHitter.hitFx = noPowerFx;
		gameHitter.damageAttribute = noPowerAttribute;
		SetState(State.Idle);
	}

	public void OnEntityInit()
	{
		if (tool != null)
		{
			tool.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(tool);
		}
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	private void OnToolUpgraded(GRTool tool)
	{
	}

	private void EnableImpactVFXForCurrentUpgradeLevel()
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.BatonDamage1))
		{
			gameHitter.hitFx = upgrade1ImpactVFX;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.BatonDamage2))
		{
			gameHitter.hitFx = upgrade2ImpactVFX;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.BatonDamage3))
		{
			gameHitter.hitFx = upgrade3ImpactVFX;
		}
		else
		{
			gameHitter.hitFx = poweredImpactFx;
		}
	}

	public override void Tick()
	{
		float deltaTime = Time.deltaTime;
		if (gameEntity.IsHeld())
		{
			if (gameEntity.IsHeldByLocalPlayer())
			{
				OnUpdateAuthority(deltaTime);
			}
			else
			{
				OnUpdateRemote(deltaTime);
			}
		}
		else
		{
			SetState(State.Idle);
		}
		OnUpdateShared(deltaTime);
	}

	private void OnUpdateAuthority(float dt)
	{
		switch (state)
		{
		case State.Idle:
			if (IsButtonHeld() && tool.HasEnoughEnergy())
			{
				SetState(State.Extended);
			}
			break;
		case State.Extended:
			if (!IsButtonHeld() || !tool.HasEnoughEnergy())
			{
				SetState(State.Idle);
			}
			break;
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state != this.state)
		{
			SetState(state);
		}
	}

	private void OnUpdateShared(float dt)
	{
		switch (state)
		{
		case State.Idle:
			if (extendedAmount > 0f)
			{
				float num2 = Mathf.MoveTowards(extendedAmount, 0f, 1f / extensionTime * Time.deltaTime);
				SetExtendedAmount(num2);
			}
			break;
		case State.Extended:
			if (extendedAmount < 1f)
			{
				float num = Mathf.MoveTowards(extendedAmount, 1f, 1f / extensionTime * Time.deltaTime);
				SetExtendedAmount(num);
			}
			break;
		}
	}

	private void SetExtendedAmount(float newExtendedAmount)
	{
		extendedAmount = newExtendedAmount;
		float y = Mathf.Lerp(retractableSectionMin, retractableSectionMax, extendedAmount);
		retractableSection.localPosition = new UnityEngine.Vector3(0f, y, 0f);
	}

	private void SetState(State newState)
	{
		if (state == newState)
		{
			return;
		}
		if (state != State.Idle)
		{
			_ = 1;
		}
		state = newState;
		switch (state)
		{
		case State.Idle:
		{
			extendedCollider.enabled = false;
			idleCollider.enabled = true;
			for (int k = 0; k < meshAndMaterials.Count; k++)
			{
				MaterialUtils.SwapMaterial(meshAndMaterials[k], isOnToOff: true);
			}
			humAudioSource.Stop();
			dullLight.SetActive(value: false);
			audioSource.PlayOneShot(retractAudio, retractVolume);
			for (int l = 0; l < humParticleEffects.Count; l++)
			{
				humParticleEffects[l].gameObject.SetActive(value: false);
			}
			gameHitter.hitFx = noPowerFx;
			gameHitter.damageAttribute = noPowerAttribute;
			closeHaptic.PlayIfHeldLocal(gameEntity);
			break;
		}
		case State.Extended:
		{
			idleCollider.enabled = false;
			extendedCollider.enabled = true;
			for (int i = 0; i < meshAndMaterials.Count; i++)
			{
				MaterialUtils.SwapMaterial(meshAndMaterials[i], isOnToOff: false);
			}
			humAudioSource.Play();
			dullLight.SetActive(value: true);
			audioSource.PlayOneShot(extendAudio, extendVolume);
			for (int j = 0; j < humParticleEffects.Count; j++)
			{
				humParticleEffects[j].gameObject.SetActive(value: true);
			}
			EnableImpactVFXForCurrentUpgradeLevel();
			gameHitter.damageAttribute = poweredAttribute;
			openHaptic.PlayIfHeldLocal(gameEntity);
			break;
		}
		}
		if (gameEntity.IsHeldByLocalPlayer())
		{
			gameEntity.RequestState(gameEntity.id, (long)newState);
		}
	}

	private bool IsButtonHeld()
	{
		if (!gameEntity.IsHeldByLocalPlayer())
		{
			return false;
		}
		if (!GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			return false;
		}
		int num = out_gamePlayer.FindHandIndex(gameEntity.id);
		if (num == -1)
		{
			return false;
		}
		return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
	}

	public void OnSuccessfulHit(GameHitData hitData)
	{
		if (state == State.Extended)
		{
			tool.UseEnergy();
		}
	}

	public void GetDebugTextLines(out List<string> strings)
	{
		strings = new List<string>();
		strings.Add($"Knockback: <color=\"yellow\">x{gameHitter.knockbackMultiplier}<color=\"white\">");
	}
}
public class GRToolCollector : MonoBehaviour, IGameEntityDebugComponent, IGameEntityComponent
{
	private enum State
	{
		Idle,
		Vacuuming,
		Collect,
		Cooldown
	}

	public GameEntity gameEntity;

	public GRTool tool;

	public GRAttributes attributes;

	public int energyDepositPerUse = 100;

	public Transform shootFrom;

	public LayerMask collectibleLayerMask;

	public ParticleSystem vacuumParticleEffect;

	public ParticleSystem upgrade1VacuumParticleEffect;

	public ParticleSystem upgrade2VacuumParticleEffect;

	public ParticleSystem upgrade3VacuumParticleEffect;

	public ParticleSystem passiveChargeParticleEffect;

	public AudioSource vacuumAudioSource;

	public AudioClip vacuumSound;

	public AudioClip upgrade1vacuumSound;

	public AudioClip upgrade2vacuumSound;

	public AudioClip upgrade3vacuumSound;

	public float vacuumSoundVolume = 0.2f;

	public AudioSource collectAudioSource;

	[FormerlySerializedAs("flashSound")]
	public AudioClip collectSound;

	[FormerlySerializedAs("flashSoundVolume")]
	public float collectSoundVolume = 1f;

	public AudioClip chargeBeamSound;

	public float chargeBeamVolume = 0.2f;

	public LightningDispatcher lightningDispatcher;

	public float chargeDuration = 0.75f;

	[FormerlySerializedAs("flashDuration")]
	public float collectDuration = 0.1f;

	public float cooldownDuration;

	public AbilityHaptic collectHaptic;

	[NonSerialized]
	public GhostReactorManager grManager;

	private float rechargeRate;

	public float rechargeInterval = 1f;

	private double lastRechargeTime;

	public float level3ChargeRadius = 4f;

	private State state;

	private float stateTimeRemaining;

	private bool activatedLocally;

	private bool waitingForButtonRelease;

	private RaycastHit[] tempHitResults = new RaycastHit[128];

	private void Awake()
	{
		state = State.Idle;
		stateTimeRemaining = -1f;
	}

	private void OnEnable()
	{
		SetState(State.Idle);
	}

	public void OnEntityInit()
	{
		if (tool != null)
		{
			tool.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(tool);
		}
		lastRechargeTime = Time.time;
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	private void OnToolUpgraded(GRTool tool)
	{
		rechargeRate = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.RechargeRate);
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.CollectorBonus1))
		{
			vacuumSound = upgrade1vacuumSound;
			vacuumParticleEffect = upgrade1VacuumParticleEffect;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.CollectorBonus2))
		{
			vacuumSound = upgrade2vacuumSound;
			vacuumParticleEffect = upgrade2VacuumParticleEffect;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.CollectorBonus3))
		{
			vacuumSound = upgrade3vacuumSound;
			vacuumParticleEffect = upgrade3VacuumParticleEffect;
		}
	}

	private bool IsHeldLocal()
	{
		return gameEntity.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	public void OnUpdate(float dt)
	{
		if (IsHeldLocal() || activatedLocally)
		{
			OnUpdateAuthority(dt);
		}
		else
		{
			OnUpdateRemote(dt);
		}
	}

	public void Update()
	{
		float deltaTime = Time.deltaTime;
		if (IsHeldLocal() || activatedLocally)
		{
			OnUpdateAuthority(deltaTime);
		}
		else
		{
			OnUpdateRemote(deltaTime);
		}
	}

	private void OnUpdateAuthority(float dt)
	{
		switch (state)
		{
		case State.Idle:
		{
			bool flag2 = IsButtonHeld();
			waitingForButtonRelease &= flag2;
			if (flag2 && !waitingForButtonRelease)
			{
				SetStateAuthority(State.Vacuuming);
				activatedLocally = true;
			}
			if (rechargeRate > 0f && Time.timeAsDouble > lastRechargeTime + (double)rechargeInterval)
			{
				gameEntity.manager.ghostReactorManager.RequestChargeTool(gameEntity.id, gameEntity.id, (int)(rechargeRate * rechargeInterval), useCollectorEnergy: false);
				lastRechargeTime = Time.timeAsDouble;
				if (passiveChargeParticleEffect != null)
				{
					passiveChargeParticleEffect.Play();
				}
			}
			break;
		}
		case State.Vacuuming:
		{
			bool flag = IsButtonHeld();
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Collect);
			}
			else if (!flag)
			{
				SetStateAuthority(State.Idle);
				activatedLocally = false;
			}
			break;
		}
		case State.Collect:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Cooldown);
			}
			break;
		case State.Cooldown:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				activatedLocally = false;
				waitingForButtonRelease = true;
				SetStateAuthority(State.Idle);
			}
			break;
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state != this.state)
		{
			SetState(state);
		}
	}

	private void SetStateAuthority(State newState)
	{
		SetState(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetState(State newState)
	{
		state = newState;
		switch (state)
		{
		case State.Vacuuming:
			StartVacuum();
			stateTimeRemaining = chargeDuration;
			break;
		case State.Collect:
			TryCollect();
			stateTimeRemaining = collectDuration;
			break;
		case State.Cooldown:
			stateTimeRemaining = cooldownDuration;
			break;
		case State.Idle:
			StopVacuum();
			stateTimeRemaining = -1f;
			lastRechargeTime = Time.time;
			break;
		}
	}

	private void StartVacuum()
	{
		vacuumAudioSource.clip = vacuumSound;
		vacuumAudioSource.volume = vacuumSoundVolume;
		vacuumAudioSource.loop = true;
		vacuumAudioSource.Play();
		vacuumParticleEffect.Play();
		if (IsHeldLocal())
		{
			PlayVibration(GorillaTagger.Instance.tapHapticStrength, chargeDuration);
		}
	}

	private void StopVacuum()
	{
		vacuumAudioSource.loop = false;
		vacuumAudioSource.Stop();
		vacuumParticleEffect.Stop();
	}

	private void TryCollect()
	{
		if (!IsHeldLocal())
		{
			return;
		}
		int num = Physics.SphereCastNonAlloc(shootFrom.position, 0.2f, shootFrom.rotation * UnityEngine.Vector3.forward, tempHitResults, 1f, collectibleLayerMask);
		for (int i = 0; i < num; i++)
		{
			RaycastHit raycastHit = tempHitResults[i];
			GameObject gameObject = null;
			Rigidbody attachedRigidbody = raycastHit.collider.attachedRigidbody;
			if (attachedRigidbody != null)
			{
				gameObject = attachedRigidbody.gameObject;
			}
			else
			{
				GameEntity gameEntity = GameEntity.Get(raycastHit.collider);
				if (gameEntity != null)
				{
					gameObject = gameEntity.gameObject;
				}
			}
			if (gameObject != null)
			{
				GRCollectible component = gameObject.GetComponent<GRCollectible>();
				if (component != null && component.type != ProgressionManager.CoreType.ChaosSeed && tool.energy < tool.GetEnergyMax())
				{
					GhostReactorManager.Get(this.gameEntity).RequestCollectItem(component.entity.id, this.gameEntity.id);
					return;
				}
			}
		}
		for (int j = 0; j < num; j++)
		{
			RaycastHit raycastHit2 = tempHitResults[j];
			GameObject gameObject2 = null;
			Rigidbody attachedRigidbody2 = raycastHit2.collider.attachedRigidbody;
			if (attachedRigidbody2 != null)
			{
				gameObject2 = attachedRigidbody2.gameObject;
			}
			else
			{
				GameEntity gameEntity2 = GameEntity.Get(raycastHit2.collider);
				if (gameEntity2 != null)
				{
					gameObject2 = gameEntity2.gameObject;
				}
			}
			if (!(gameObject2 != null))
			{
				continue;
			}
			if (gameObject2.GetComponent<GRCurrencyDepositor>() != null)
			{
				if (tool.energy > 0)
				{
					GhostReactorManager.Get(this.gameEntity).RequestDepositCurrency(this.gameEntity.id);
				}
				break;
			}
			GRTool component2 = gameObject2.GetComponent<GRTool>();
			if (component2 == null || component2 == tool)
			{
				continue;
			}
			GameEntity component3 = gameObject2.GetComponent<GameEntity>();
			if (!(component2 != null) || !(component3 != null))
			{
				continue;
			}
			GhostReactorManager.Get(this.gameEntity).RequestChargeTool(this.gameEntity.id, component3.id);
			if (!tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.CollectorBonus3) || tool.energy <= 50)
			{
				break;
			}
			List<GRTool> list = new List<GRTool>();
			this.gameEntity.manager.GetEntitiesWithComponentInRadius(base.transform.position, level3ChargeRadius, checkRootOnly: true, list);
			for (int k = 0; k < list.Count; k++)
			{
				GRTool gRTool = list[k];
				if (!(gRTool.GetComponent<GRToolCollector>() != null) && !(gRTool.gameEntity == this.gameEntity) && !(gRTool.gameEntity == component3))
				{
					GhostReactorManager.Get(this.gameEntity).RequestChargeTool(this.gameEntity.id, gRTool.gameEntity.id, 0, useCollectorEnergy: false);
				}
			}
			break;
		}
	}

	public void PerformCollection(GRCollectible collectible)
	{
		tool.RefillEnergy(collectible.energyValue + attributes.CalculateFinalValueForAttribute(GRAttributeType.HarvestGain), collectible.entity.id);
		collectAudioSource.volume = collectSoundVolume;
		collectAudioSource.PlayOneShot(collectSound);
	}

	public void PlayChargeEffect(GRTool targetTool)
	{
		if (targetTool == null || targetTool == tool)
		{
			return;
		}
		collectAudioSource.volume = chargeBeamVolume;
		collectAudioSource.PlayOneShot(chargeBeamSound);
		for (int i = 0; i < targetTool.energyMeters.Count; i++)
		{
			if (targetTool.energyMeters[i].chargePoint != null)
			{
				lightningDispatcher.DispatchLightning(lightningDispatcher.transform.position, targetTool.energyMeters[i].chargePoint.position);
			}
			else
			{
				lightningDispatcher.DispatchLightning(lightningDispatcher.transform.position, targetTool.energyMeters[i].transform.position);
			}
		}
	}

	public void PlayChargeEffect(GRCurrencyDepositor targetDepositor)
	{
		if (!(targetDepositor == null))
		{
			collectAudioSource.volume = chargeBeamVolume;
			collectAudioSource.PlayOneShot(chargeBeamSound);
			lightningDispatcher.DispatchLightning(lightningDispatcher.transform.position, targetDepositor.depositingChargePoint.position);
		}
	}

	private bool IsButtonHeld()
	{
		if (!IsHeldLocal())
		{
			return false;
		}
		if (!GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			return false;
		}
		int num = out_gamePlayer.FindHandIndex(gameEntity.id);
		if (num == -1)
		{
			return false;
		}
		return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
	}

	private void PlayVibration(float strength, float duration)
	{
		if (IsHeldLocal() && GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			int num = out_gamePlayer.FindHandIndex(gameEntity.id);
			if (num != -1)
			{
				GorillaTagger.Instance.StartVibration(GamePlayer.IsLeftHand(num), strength, duration);
			}
		}
	}

	public void GetDebugTextLines(out List<string> strings)
	{
		strings = new List<string>();
		strings.Add($"Recharge Rate: <color=\"yellow\">{rechargeRate}<color=\"white\">");
	}
}
public class GRToolDirectionalShield : MonoBehaviour, IGameHitter
{
	private enum State
	{
		Closed,
		Open
	}

	[Header("References")]
	public GameEntity gameEntity;

	public GRTool tool;

	public Rigidbody rigidBody;

	public AudioSource audioSource;

	public List<Animator> shieldAnimators;

	public Transform openCollidersParent;

	private GameHitter hitter;

	private GRAttributes attributes;

	[Header("Audio")]
	public AudioClip openAudio;

	public float openVolume = 0.5f;

	public AudioClip closeAudio;

	public float closeVolume = 0.5f;

	public AudioClip deflectAudio;

	public AudioClip upgrade1DeflectAudio;

	public AudioClip upgrade2DeflectAudio;

	public AudioClip upgrade3DeflectAudio;

	public float deflectVolume = 0.5f;

	[Header("VFX")]
	public ParticleSystem shieldDeflectVFX;

	public ParticleSystem upgrade1ShieldDeflectVFX;

	public ParticleSystem upgrade2ShieldDeflectVFX;

	public ParticleSystem upgrade3ShieldDeflectVFX;

	public ParticleSystem shieldDeflectImpactPointVFX;

	public Transform shieldArcCenterReferencePoint;

	public float shieldArcCenterRadius = 1f;

	[Header("Haptic")]
	public AbilityHaptic openHaptic;

	public AbilityHaptic closeHaptic;

	public bool reflectsProjectiles;

	private State state;

	private void Awake()
	{
		hitter = GetComponent<GameHitter>();
		attributes = GetComponent<GRAttributes>();
		if (tool != null)
		{
			tool.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(tool);
		}
	}

	private void OnToolUpgraded(GRTool tool)
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.DirectionalShieldSize1))
		{
			deflectAudio = upgrade1DeflectAudio;
			shieldDeflectVFX = upgrade1ShieldDeflectVFX;
			reflectsProjectiles = true;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.DirectionalShieldSize2))
		{
			deflectAudio = upgrade2DeflectAudio;
			shieldDeflectVFX = upgrade2ShieldDeflectVFX;
			reflectsProjectiles = false;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.DirectionalShieldSize3))
		{
			deflectAudio = upgrade3DeflectAudio;
			shieldDeflectVFX = upgrade3ShieldDeflectVFX;
			reflectsProjectiles = true;
		}
		else
		{
			reflectsProjectiles = false;
		}
	}

	public void OnEnable()
	{
		SetState(State.Closed);
	}

	private bool IsHeldLocal()
	{
		return gameEntity.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	private bool IsHeld()
	{
		return gameEntity.heldByActorNumber != -1;
	}

	public void BlockHittable(UnityEngine.Vector3 enemyPosition, UnityEngine.Vector3 enemyAttackDirection, GameHittable hittable, GRShieldCollider shieldCollider)
	{
		if (!IsHeldLocal())
		{
			return;
		}
		float num = 1f;
		if (attributes != null && attributes.HasValueForAttribute(GRAttributeType.KnockbackMultiplier))
		{
			num = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.KnockbackMultiplier);
		}
		UnityEngine.Vector3 hitImpulse = -enemyAttackDirection * shieldCollider.KnockbackVelocity * num;
		if (reflectsProjectiles)
		{
			GRRangedEnemyProjectile component = hittable.GetComponent<GRRangedEnemyProjectile>();
			if (component != null && component.owningEntity != null && GREnemyRanged.CalculateLaunchDirection(enemyPosition, component.owningEntity.transform.position + new UnityEngine.Vector3(0f, 0.5f, 0f), component.projectileSpeed, out var direction))
			{
				hitImpulse = direction * component.projectileSpeed;
			}
		}
		GameHitData hitData = new GameHitData
		{
			hitTypeId = 2,
			hitEntityId = hittable.gameEntity.id,
			hitByEntityId = gameEntity.id,
			hitEntityPosition = enemyPosition,
			hitImpulse = hitImpulse,
			hitPosition = enemyPosition,
			hitAmount = hitter.CalcHitAmount(GameHitType.Shield, hittable, gameEntity)
		};
		if (hittable.IsHitValid(hitData))
		{
			hittable.RequestHit(hitData);
		}
	}

	public void OnEnemyBlocked(UnityEngine.Vector3 enemyPosition)
	{
		tool.UseEnergy();
		PlayBlockEffects(enemyPosition);
	}

	private void PlayBlockEffects(UnityEngine.Vector3 enemyPosition)
	{
		audioSource.PlayOneShot(deflectAudio, deflectVolume);
		shieldDeflectVFX.Play();
		UnityEngine.Vector3 vector = UnityEngine.Vector3.ClampMagnitude(enemyPosition - shieldArcCenterReferencePoint.position, shieldArcCenterRadius);
		UnityEngine.Vector3 position = shieldArcCenterReferencePoint.position + vector;
		shieldDeflectImpactPointVFX.transform.position = position;
		shieldDeflectImpactPointVFX.Play();
	}

	public void OnSuccessfulHit(GameHitData hitData)
	{
		tool.UseEnergy();
		PlayBlockEffects(hitData.hitEntityPosition);
	}

	public void Update()
	{
		float deltaTime = Time.deltaTime;
		if (IsHeld())
		{
			if (IsHeldLocal())
			{
				OnUpdateAuthority(deltaTime);
			}
			else
			{
				OnUpdateRemote(deltaTime);
			}
		}
		else
		{
			SetState(State.Closed);
		}
	}

	private void OnUpdateAuthority(float dt)
	{
		switch (state)
		{
		case State.Closed:
			if (IsButtonHeld() && tool.HasEnoughEnergy())
			{
				SetStateAuthority(State.Open);
			}
			break;
		case State.Open:
			if (!IsButtonHeld() || !tool.HasEnoughEnergy())
			{
				SetStateAuthority(State.Closed);
			}
			break;
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state != this.state)
		{
			SetState(state);
		}
	}

	private void SetStateAuthority(State newState)
	{
		SetState(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetState(State newState)
	{
		if (state == newState)
		{
			return;
		}
		if (state != State.Closed)
		{
			_ = 1;
		}
		state = newState;
		switch (state)
		{
		case State.Closed:
		{
			openCollidersParent.gameObject.SetActive(value: false);
			for (int j = 0; j < shieldAnimators.Count; j++)
			{
				shieldAnimators[j].SetBool("Activated", value: false);
			}
			audioSource.PlayOneShot(closeAudio, closeVolume);
			closeHaptic.PlayIfHeldLocal(gameEntity);
			_ = hitter != null;
			break;
		}
		case State.Open:
		{
			openCollidersParent.gameObject.SetActive(value: true);
			for (int i = 0; i < shieldAnimators.Count; i++)
			{
				shieldAnimators[i].SetBool("Activated", value: true);
			}
			audioSource.PlayOneShot(openAudio, openVolume);
			openHaptic.PlayIfHeldLocal(gameEntity);
			_ = hitter != null;
			break;
		}
		}
	}

	private bool IsButtonHeld()
	{
		if (!IsHeldLocal())
		{
			return false;
		}
		GamePlayer gamePlayer = GamePlayer.GetGamePlayer(gameEntity.heldByActorNumber);
		if (gamePlayer == null)
		{
			return false;
		}
		int num = gamePlayer.FindHandIndex(gameEntity.id);
		if (num == -1)
		{
			return false;
		}
		return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
	}
}
public class GRToolFlash : MonoBehaviour, IGameEntityDebugComponent, IGameEntityComponent
{
	[Flags]
	public enum UpgradeTypes
	{
		None = 1,
		UpagredA = 2,
		UpagredB = 4,
		UpagredC = 8
	}

	private enum State
	{
		Idle,
		Charging,
		Flash,
		Cooldown,
		Count
	}

	public GameEntity gameEntity;

	public GRTool tool;

	public GRAttributes attributes;

	public GameObject flash;

	public Transform shootFrom;

	public LayerMask enemyLayerMask;

	public AudioSource audioSource;

	public AudioClip chargeSound;

	public float chargeSoundVolume = 0.2f;

	public AudioClip flashSound;

	public AudioClip upgrade1FlashSound;

	public AudioClip upgrade2FlashSound;

	public AudioClip upgrade3FlashSound;

	public GameObject upgrade1FlashCone;

	public GameObject upgrade2FlashCone;

	public GameObject upgrade3FlashCone;

	public float flashSoundVolume = 1f;

	public float stunDuration;

	public UpgradeTypes upgradesApplied;

	public float chargeDuration = 0.75f;

	public float flashDuration = 0.1f;

	public float cooldownDuration;

	private float timeLastFlashed;

	private float cooldownMinimum = 0.35f;

	private bool activatedLocally;

	public GameEntity item;

	private GameHitter gameHitter;

	private State state;

	private float stateTimeRemaining;

	private RaycastHit[] tempHitResults = new RaycastHit[128];

	private void Awake()
	{
		state = State.Idle;
		stateTimeRemaining = -1f;
		gameHitter = GetComponent<GameHitter>();
	}

	private void OnEnable()
	{
		StopFlash();
		SetState(State.Idle);
	}

	public void OnEntityInit()
	{
		if (tool != null)
		{
			tool.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(tool);
		}
	}

	public void OnEntityDestroy()
	{
	}

	public void OnEntityStateChange(long prevState, long nextState)
	{
	}

	private void OnToolUpgraded(GRTool tool)
	{
		stunDuration = attributes.CalculateFinalFloatValueForAttribute(GRAttributeType.FlashStunDuration);
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.FlashDamage1))
		{
			flashSound = upgrade1FlashSound;
			flash = upgrade1FlashCone;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.FlashDamage2))
		{
			flashSound = upgrade2FlashSound;
			flash = upgrade2FlashCone;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.FlashDamage3))
		{
			flashSound = upgrade3FlashSound;
			flash = upgrade3FlashCone;
		}
	}

	private bool IsHeldLocal()
	{
		return item.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	public void OnUpdate(float dt)
	{
		if (IsHeldLocal())
		{
			OnUpdateAuthority(dt);
		}
		else
		{
			OnUpdateRemote(dt);
		}
	}

	public void Update()
	{
		float deltaTime = Time.deltaTime;
		if (IsHeldLocal() || activatedLocally)
		{
			OnUpdateAuthority(deltaTime);
		}
		else
		{
			OnUpdateRemote(deltaTime);
		}
	}

	private void OnUpdateAuthority(float dt)
	{
		switch (state)
		{
		case State.Idle:
			if (tool.HasEnoughEnergy() && IsButtonHeld())
			{
				SetStateAuthority(State.Charging);
				activatedLocally = true;
			}
			break;
		case State.Charging:
		{
			bool flag = IsButtonHeld();
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Flash);
			}
			else if (!flag)
			{
				SetStateAuthority(State.Idle);
				activatedLocally = false;
			}
			break;
		}
		case State.Flash:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Cooldown);
			}
			break;
		case State.Cooldown:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f && !IsButtonHeld())
			{
				SetStateAuthority(State.Idle);
				activatedLocally = false;
			}
			break;
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state == this.state)
		{
			return;
		}
		if (this.state == State.Charging && state == State.Cooldown)
		{
			SetState(State.Flash);
		}
		else if (this.state == State.Flash && state == State.Cooldown)
		{
			if (Time.time > timeLastFlashed + flashDuration)
			{
				SetState(State.Cooldown);
			}
		}
		else
		{
			SetState(state);
		}
	}

	private void SetStateAuthority(State newState)
	{
		SetState(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetState(State newState)
	{
		if (CanChangeState((long)newState))
		{
			state = newState;
			switch (state)
			{
			case State.Charging:
				StartCharge();
				stateTimeRemaining = chargeDuration;
				break;
			case State.Flash:
				StartFlash();
				stateTimeRemaining = flashDuration;
				break;
			case State.Cooldown:
				StopFlash();
				stateTimeRemaining = cooldownDuration;
				break;
			case State.Idle:
				stateTimeRemaining = -1f;
				break;
			}
		}
	}

	private void StartCharge()
	{
		audioSource.volume = chargeSoundVolume;
		audioSource.clip = chargeSound;
		audioSource.Play();
		if (IsHeldLocal())
		{
			PlayVibration(GorillaTagger.Instance.tapHapticStrength, chargeDuration);
		}
	}

	private void StartFlash()
	{
		flash.SetActive(value: true);
		audioSource.volume = flashSoundVolume;
		audioSource.clip = flashSound;
		audioSource.Play();
		tool.UseEnergy();
		timeLastFlashed = Time.time;
		if (!IsHeldLocal())
		{
			return;
		}
		int num = Physics.SphereCastNonAlloc(shootFrom.position, 1f, shootFrom.rotation * UnityEngine.Vector3.forward, tempHitResults, 5f, enemyLayerMask);
		for (int i = 0; i < num; i++)
		{
			RaycastHit raycastHit = tempHitResults[i];
			Rigidbody attachedRigidbody = raycastHit.collider.attachedRigidbody;
			if (attachedRigidbody != null)
			{
				GameHittable component = attachedRigidbody.GetComponent<GameHittable>();
				if (component != null && gameHitter != null)
				{
					GameHitData hitData = new GameHitData
					{
						hitTypeId = 1,
						hitEntityId = component.gameEntity.id,
						hitByEntityId = gameEntity.id,
						hitEntityPosition = component.gameEntity.transform.position,
						hitPosition = ((raycastHit.distance == 0f) ? shootFrom.position : raycastHit.point),
						hitImpulse = UnityEngine.Vector3.zero,
						hitAmount = gameHitter.CalcHitAmount(GameHitType.Flash, component, gameEntity),
						hittablePoint = component.FindHittablePoint(raycastHit.collider)
					};
					component.RequestHit(hitData);
				}
			}
		}
	}

	private void StopFlash()
	{
		flash.SetActive(value: false);
	}

	private bool IsButtonHeld()
	{
		if (!IsHeldLocal())
		{
			return false;
		}
		if (!GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			return false;
		}
		int num = out_gamePlayer.FindHandIndex(item.id);
		if (num == -1)
		{
			return false;
		}
		return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
	}

	private void PlayVibration(float strength, float duration)
	{
		if (IsHeldLocal() && GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			int num = out_gamePlayer.FindHandIndex(item.id);
			if (num != -1)
			{
				GorillaTagger.Instance.StartVibration(GamePlayer.IsLeftHand(num), strength, duration);
			}
		}
	}

	public bool CanChangeState(long newStateIndex)
	{
		if (newStateIndex < 0 || newStateIndex >= 4)
		{
			return false;
		}
		if ((int)newStateIndex == 2)
		{
			return Time.time > timeLastFlashed + cooldownMinimum;
		}
		return true;
	}

	public void GetDebugTextLines(out List<string> strings)
	{
		strings = new List<string>();
		strings.Add($"Stun Duration: <color=\"yellow\">{stunDuration}<color=\"white\">");
	}
}
[RequireComponent(typeof(GameEntity))]
public class GRToolLantern : MonoBehaviour, IGRSummoningEntity
{
	private enum State
	{
		Off,
		On,
		Count
	}

	public GameEntity gameEntity;

	public GRTool tool;

	public GameLight gameLight;

	public GRAttributes attributes;

	[SerializeField]
	private float timeOnPerEnergyUseDurationSeconds = 2f;

	[SerializeField]
	private int minEnergyPerUse = 1;

	[SerializeField]
	private float turnOnSoundVolume;

	[SerializeField]
	private AudioClip turnOnSound;

	[SerializeField]
	private AudioClip upgrade1TurnOnSound;

	[SerializeField]
	private AudioClip upgrade2TurnOnSound;

	[SerializeField]
	private AudioClip upgrade3TurnOnSound;

	[SerializeField]
	private AudioSource audioSource;

	public List<MeshAndMaterials> meshAndMaterials;

	[Header("Haptic")]
	public AbilityHaptic onHaptic;

	private float timeOnSpentEnergy;

	private float timeLastTurnedOn;

	private float minOnDuration = 0.5f;

	private State state;

	private List<int> trackedEntities;

	private double lastFlareDropTime;

	public double minFlareDropInterval = 1.0;

	public GameEntity lanternFlarePrefab;

	public int maxSpawnedFlares = 10;

	private bool providingXRay;

	public UnityEngine.Vector3 flareSpawnoffset = UnityEngine.Vector3.zero;

	private void Awake()
	{
		trackedEntities = new List<int>();
		state = State.Off;
		gameEntity.OnStateChanged += OnStateChanged;
		GameEntity obj = gameEntity;
		obj.OnGrabbed = (Action)Delegate.Combine(obj.OnGrabbed, new Action(OnGrabbed));
		GameEntity obj2 = gameEntity;
		obj2.OnReleased = (Action)Delegate.Combine(obj2.OnReleased, new Action(OnReleased));
		if (tool != null)
		{
			tool.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(tool);
		}
	}

	private void OnEnable()
	{
		TurnOff();
		state = State.Off;
	}

	private void OnDestroy()
	{
		if (providingXRay && tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			DisableXRay();
		}
	}

	private void OnToolUpgraded(GRTool tool)
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity1))
		{
			turnOnSound = upgrade1TurnOnSound;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity2))
		{
			turnOnSound = upgrade2TurnOnSound;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			turnOnSound = upgrade3TurnOnSound;
		}
	}

	public void OnGrabbed()
	{
	}

	public void OnReleased()
	{
		if (WasLastHeldLocal())
		{
			DisableXRay();
		}
	}

	private void EnableXRay()
	{
		if (!providingXRay && tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			GRPlayer.GetLocal().xRayVisionRefCount++;
			providingXRay = true;
		}
	}

	private void DisableXRay()
	{
		if (providingXRay && tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			GRPlayer.GetLocal().xRayVisionRefCount--;
			providingXRay = false;
		}
	}

	public void Update()
	{
		float deltaTime = Time.deltaTime;
		if (IsHeldLocal() || tool.energy > 0)
		{
			OnUpdateAuthority(deltaTime);
		}
		else
		{
			OnUpdateRemote(deltaTime);
		}
	}

	private void OnUpdateAuthority(float dt)
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			bool isOn = IsHeld();
			EnableLights(isOn);
		}
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity2))
		{
			SetState(State.On);
			if (Time.timeAsDouble > lastFlareDropTime + minFlareDropInterval && IsButtonHeld() && tool.HasEnoughEnergy() && trackedEntities.Count < maxSpawnedFlares && lanternFlarePrefab != null)
			{
				if (gameEntity.IsAuthority())
				{
					UnityEngine.Vector3 vector = base.transform.rotation * flareSpawnoffset;
					gameEntity.manager.RequestCreateItem(lanternFlarePrefab.name.GetStaticHash(), base.transform.position + vector, base.transform.rotation * UnityEngine.Quaternion.Euler(10f, 0f, 10f), gameEntity.GetNetId());
				}
				lastFlareDropTime = Time.timeAsDouble;
				tool.UseEnergy();
				audioSource.PlayOneShot(turnOnSound, turnOnSoundVolume);
			}
			return;
		}
		switch (state)
		{
		case State.Off:
			if (IsButtonHeld() && tool.HasEnoughEnergy())
			{
				SetState(State.On);
				gameEntity.RequestState(gameEntity.id, 1L);
			}
			break;
		case State.On:
			timeOnSpentEnergy -= dt;
			if ((!IsButtonHeld() && timeOnSpentEnergy <= 0f) || tool.energy <= 0)
			{
				SetState(State.Off);
				gameEntity.RequestState(gameEntity.id, 0L);
			}
			else if (IsButtonHeld() && timeOnSpentEnergy <= 0f)
			{
				TryConsumeEnergy();
			}
			break;
		}
	}

	private void TryConsumeEnergy()
	{
		if (tool.HasEnoughEnergy())
		{
			tool.UseEnergy();
			timeOnSpentEnergy = timeOnPerEnergyUseDurationSeconds * 10f * (float)tool.GetEnergyUseCost() / (float)tool.GetEnergyMax();
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state != this.state)
		{
			SetState(state);
		}
	}

	private void SetState(State newState)
	{
		if (state != newState && CanChangeState((long)newState))
		{
			state = newState;
			switch (state)
			{
			case State.On:
				TurnOn();
				break;
			case State.Off:
				TurnOff();
				break;
			}
		}
	}

	private void TurnOn()
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			EnableXRay();
		}
		else
		{
			EnableLights(isOn: true);
		}
		audioSource.PlayOneShot(turnOnSound, turnOnSoundVolume);
		onHaptic.PlayIfHeldLocal(gameEntity);
		timeLastTurnedOn = Time.time;
	}

	private void EnableLights(bool isOn)
	{
		if (gameLight.gameObject.activeSelf != isOn)
		{
			if (attributes.HasBeenInitialized())
			{
				gameLight.light.intensity = attributes.CalculateFinalValueForAttribute(GRAttributeType.LightIntensity);
			}
			gameLight.gameObject.SetActive(isOn);
			for (int i = 0; i < meshAndMaterials.Count; i++)
			{
				MaterialUtils.SwapMaterial(meshAndMaterials[i], !isOn);
			}
		}
	}

	private void TurnOff()
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.LanternIntensity3))
		{
			DisableXRay();
		}
		else
		{
			EnableLights(isOn: false);
		}
	}

	private bool IsHeld()
	{
		return gameEntity.IsHeld();
	}

	private bool IsHeldLocal()
	{
		return gameEntity.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	private bool WasLastHeldLocal()
	{
		return gameEntity.lastHeldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	private bool IsButtonHeld()
	{
		if (!GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			return false;
		}
		int num = out_gamePlayer.FindHandIndex(gameEntity.id);
		if (num == -1)
		{
			return false;
		}
		if (!GamePlayer.IsLeftHand(num))
		{
			return out_gamePlayer.rig.rightIndex.calcT > 0.25f;
		}
		return out_gamePlayer.rig.leftIndex.calcT > 0.25f;
	}

	private void OnStateChanged(long prevState, long nextState)
	{
	}

	public bool CanChangeState(long newStateIndex)
	{
		if (newStateIndex < 0 || newStateIndex >= 2)
		{
			return false;
		}
		switch ((State)newStateIndex)
		{
		case State.On:
			return tool.energy > 0;
		case State.Off:
			if (!(Time.time > timeLastTurnedOn + minOnDuration))
			{
				return tool.energy <= 0;
			}
			return true;
		default:
			return false;
		}
	}

	public void AddTrackedEntity(GameEntity entityToTrack)
	{
		int netId = entityToTrack.GetNetId();
		trackedEntities.AddIfNew(netId);
	}

	public void RemoveTrackedEntity(GameEntity entityToRemove)
	{
		int netId = entityToRemove.GetNetId();
		if (trackedEntities.Contains(netId))
		{
			trackedEntities.Remove(netId);
		}
	}

	public void OnSummonedEntityInit(GameEntity entity)
	{
		AddTrackedEntity(entity);
	}

	public void OnSummonedEntityDestroy(GameEntity entity)
	{
		RemoveTrackedEntity(entity);
	}
}
