	private GhostReactorManager grManager;

	private GhostReactor reactor;

	public int ActiveEntryIndex => activeEntryIndex;

	public void Init(GhostReactorManager grManager, GhostReactor reactor)
	{
		this.grManager = grManager;
		this.reactor = reactor;
	}

	public void RequestPurchaseButton(int actorNumber)
	{
		if (actorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber)
		{
			grManager.ToolPurchaseStationRequest(PurchaseStationId, GhostReactorManager.ToolPurchaseStationAction.TryPurchase);
		}
	}

	public void ShiftRightButton()
	{
		grManager.ToolPurchaseStationRequest(PurchaseStationId, GhostReactorManager.ToolPurchaseStationAction.ShiftRight);
	}

	public void ShiftLeftButton()
	{
		grManager.ToolPurchaseStationRequest(PurchaseStationId, GhostReactorManager.ToolPurchaseStationAction.ShiftLeft);
	}

	public void ShiftRightAuthority()
	{
		activeEntryIndex = (activeEntryIndex + 1) % toolEntries.Count;
	}

	public void ShiftLeftAuthority()
	{
		activeEntryIndex = ((activeEntryIndex > 0) ? (activeEntryIndex - 1) : (toolEntries.Count - 1));
	}

	public void DebugPurchase()
	{
		int entityTypeId = toolEntries[activeEntryIndex].GetEntityTypeId();
		UnityEngine.Vector3 localPosition = toolEntries[activeEntryIndex].displayToolParent.GetChild(0).localPosition;
		UnityEngine.Quaternion localRotation = toolEntries[activeEntryIndex].displayToolParent.GetChild(0).localRotation;
		UnityEngine.Quaternion rotation = depositTransform.rotation * localRotation;
		UnityEngine.Vector3 position = depositTransform.position + depositTransform.rotation * localPosition;
		grManager.gameEntityManager.RequestCreateItem(entityTypeId, position, rotation, 0L);
		OnPurchaseSucceeded();
	}

	public bool TryPurchaseAuthority(GRPlayer player, out int itemCost)
	{
		int entityTypeId = toolEntries[activeEntryIndex].GetEntityTypeId();
		itemCost = reactor.GetItemCost(entityTypeId);
		if (debugIgnoreToolCost || player.ShiftCredits >= itemCost)
		{
			UnityEngine.Vector3 localPosition = toolEntries[activeEntryIndex].displayToolParent.GetChild(0).localPosition;
			UnityEngine.Quaternion localRotation = toolEntries[activeEntryIndex].displayToolParent.GetChild(0).localRotation;
			UnityEngine.Quaternion rotation = depositTransform.rotation * localRotation;
			UnityEngine.Vector3 position = depositTransform.position + depositTransform.rotation * localPosition;
			grManager.gameEntityManager.RequestCreateItem(entityTypeId, position, rotation, 0L);
			return true;
		}
		return false;
	}

	public void OnSelectionUpdate(int newSelectedIndex)
	{
		activeEntryIndex = Mathf.Clamp(newSelectedIndex % toolEntries.Count, 0, toolEntries.Count - 1);
		audioSource.PlayOneShot(nextItemAudio, nextItemVolume);
		displayItemNameText.text = toolEntries[activeEntryIndex].toolName;
		displayItemCostText.text = toolEntries[activeEntryIndex].toolCost.ToString();
	}

	public void OnPurchaseSucceeded()
	{
		animatingDeposit = true;
		animationStartTime = Time.time;
		audioSource.PlayOneShot(purchaseAudio, purchaseVolume);
		idCardScanner.onSucceeded?.Invoke();
		if (displayedEntryIndex < 0 || displayedEntryIndex >= toolEntries.Count)
		{
			displayedEntryIndex = activeEntryIndex;
		}
	}

	public void OnPurchaseFailed()
	{
		audioSource.PlayOneShot(purchaseFailedAudio, purchaseFailedVolume);
		idCardScanner.onFailed?.Invoke();
	}

	public Transform GetSpawnMarker()
	{
		return toolSpawnLocation;
	}

	public string GetCurrentToolName()
	{
		return toolEntries[activeEntryIndex].toolName;
	}

	private void Awake()
	{
		depositLidOpenRot = UnityEngine.Quaternion.Euler(depositLidOpenEuler);
		toolEntryRot = UnityEngine.Quaternion.Euler(toolEntryRotEuler);
		toolExitRot = UnityEngine.Quaternion.Euler(toolExitRotEuler);
	}

	private void Update()
	{
		if (!animatingSwap && !animatingDeposit && activeEntryIndex != displayedEntryIndex)
		{
			animatingSwap = true;
			animationStartTime = Time.time;
			animPrevToolIndex = displayedEntryIndex;
			animNextToolIndex = activeEntryIndex;
			toolEntryRot = UnityEngine.Quaternion.AngleAxis(toolEntryRotDegrees, UnityEngine.Random.onUnitSphere);
		}
		if (animatingSwap)
		{
			float num = (Time.time - animationStartTime) / nextToolAnimationTime;
			Transform transform = null;
			if (animPrevToolIndex >= 0 && animPrevToolIndex < toolEntries.Count)
			{
				transform = toolEntries[animPrevToolIndex].displayToolParent;
				transform.localRotation = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.identity, toolExitRot, toolExitRotTimingCurve.Evaluate(num));
				transform.localPosition = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.zero, toolExitPosOffset, toolExitPosTimingCurve.Evaluate(num));
			}
			Transform displayToolParent = toolEntries[animNextToolIndex].displayToolParent;
			displayToolParent.localRotation = UnityEngine.Quaternion.Slerp(toolEntryRot, UnityEngine.Quaternion.identity, toolEntryRotTimingCurve.Evaluate(num));
			displayToolParent.localPosition = UnityEngine.Vector3.Lerp(toolEntryPosOffset, UnityEngine.Vector3.zero, toolEntryPosTimingCurve.Evaluate(num));
			displayToolParent.gameObject.SetActive(value: true);
			if (num >= 1f)
			{
				if (transform != null)
				{
					transform.gameObject.SetActive(value: false);
				}
				displayedEntryIndex = animNextToolIndex;
				animatingSwap = false;
			}
		}
		else if (animatingDeposit)
		{
			float num2 = (Time.time - animationStartTime) / toolDepositAnimationTime;
			Transform displayToolParent2 = toolEntries[displayedEntryIndex].displayToolParent;
			UnityEngine.Vector3 localPosition = displayToolParent2.localPosition;
			localPosition.y = Mathf.Lerp(0f, depositTransform.localPosition.y, toolDepositMotionCurveY.Evaluate(toolDepositTimingCurve.Evaluate(num2)));
			localPosition.z = Mathf.Lerp(0f, depositTransform.localPosition.z, toolDepositMotionCurveZ.Evaluate(toolDepositTimingCurve.Evaluate(num2)));
			displayToolParent2.localPosition = localPosition;
			depositLidTransform.localRotation = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.identity, depositLidOpenRot, depositLidTimingCurve.Evaluate(num2));
			if (num2 >= 1f)
			{
				depositLidTransform.localRotation = UnityEngine.Quaternion.identity;
				displayToolParent2.gameObject.SetActive(value: false);
				displayedEntryIndex = -1;
				animatingDeposit = false;
			}
		}
	}
}
[RequireComponent(typeof(GameEntity))]
public class GRToolRevive : MonoBehaviour
{
	private enum State
	{
		Idle,
		Reviving,
		Cooldown
	}

	public GameEntity gameEntity;

	public GRTool tool;

	[SerializeField]
	private Transform shootFrom;

	[SerializeField]
	private LayerMask playerLayerMask;

	[SerializeField]
	private float reviveDistance = 1.5f;

	[SerializeField]
	private GameObject reviveFx;

	[SerializeField]
	private float reviveSoundVolume;

	[SerializeField]
	private AudioClip reviveSound;

	[SerializeField]
	private float reviveDuration = 0.75f;

	[SerializeField]
	private AudioSource audioSource;

	[Header("Haptic")]
	public AbilityHaptic onHaptic;

	private State state;

	private float stateTimeRemaining;

	private RaycastHit[] tempHitResults = new RaycastHit[128];

	private void Awake()
	{
		state = State.Idle;
	}

	private void OnEnable()
	{
		StopRevive();
		state = State.Idle;
	}

	private void OnDestroy()
	{
	}

	public void Update()
	{
		float deltaTime = Time.deltaTime;
		if (gameEntity.IsHeldByLocalPlayer())
		{
			OnUpdateAuthority(deltaTime);
		}
		else
		{
			OnUpdateRemote(deltaTime);
		}
	}

	private void OnUpdateAuthority(float dt)
	{
		switch (state)
		{
		case State.Idle:
			if (tool.HasEnoughEnergy() && IsButtonHeld())
			{
				SetStateAuthority(State.Reviving);
			}
			break;
		case State.Reviving:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Cooldown);
			}
			break;
		case State.Cooldown:
			if (!IsButtonHeld())
			{
				SetStateAuthority(State.Idle);
			}
			break;
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state != this.state)
		{
			SetState(state);
		}
	}

	private void SetStateAuthority(State newState)
	{
		SetState(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetState(State newState)
	{
		if (state != newState)
		{
			if (state == State.Reviving)
			{
				StopRevive();
			}
			state = newState;
			switch (state)
			{
			case State.Reviving:
				StartRevive();
				stateTimeRemaining = reviveDuration;
				break;
			case State.Idle:
				stateTimeRemaining = -1f;
				break;
			}
		}
	}

	private void StartRevive()
	{
		reviveFx.SetActive(value: true);
		audioSource.volume = reviveSoundVolume;
		audioSource.clip = reviveSound;
		audioSource.Play();
		tool.UseEnergy();
		onHaptic.PlayIfHeldLocal(gameEntity);
		if (!gameEntity.IsAuthority())
		{
			return;
		}
		int num = Physics.SphereCastNonAlloc(shootFrom.position, 0.5f, shootFrom.rotation * UnityEngine.Vector3.forward, tempHitResults, reviveDistance, playerLayerMask);
		for (int i = 0; i < num; i++)
		{
			RaycastHit raycastHit = tempHitResults[i];
			Rigidbody attachedRigidbody = raycastHit.collider.attachedRigidbody;
			if (!(attachedRigidbody == null))
			{
				GRPlayer component = attachedRigidbody.GetComponent<GRPlayer>();
				if (component != null && component.State != GRPlayer.GRPlayerState.Alive)
				{
					GhostReactorManager.Get(gameEntity).RequestPlayerStateChange(component, GRPlayer.GRPlayerState.Alive);
					break;
				}
			}
		}
	}

	private void StopRevive()
	{
		reviveFx.SetActive(value: false);
		audioSource.Stop();
	}

	private bool IsButtonHeld()
	{
		if (!gameEntity.IsHeldByLocalPlayer())
		{
			return false;
		}
		if (!GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			return false;
		}
		int num = out_gamePlayer.FindHandIndex(gameEntity.id);
		if (num == -1)
		{
			return false;
		}
		return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
	}
}
public class GRToolScannable : GRScannable
{
	private GRTool tool;

	private GRToolUpgradePiece upgradePiece;

	private GRToolProgressionManager.ToolProgressionMetaData metadata;

	public override void Start()
	{
		base.Start();
		if (gameEntity != null)
		{
			tool = gameEntity.GetComponent<GRTool>();
			upgradePiece = gameEntity.GetComponent<GRToolUpgradePiece>();
		}
	}

	private void FetchMetadata(GhostReactor reactor)
	{
		if (metadata == null)
		{
			GRToolProgressionManager.ToolParts toolParts = GRToolProgressionManager.ToolParts.None;
			if (tool != null)
			{
				toolParts = GRUtils.GetToolPart(tool.toolType);
			}
			else if (upgradePiece != null)
			{
				toolParts = upgradePiece.matchingUpgrade;
			}
			if (toolParts != GRToolProgressionManager.ToolParts.None)
			{
				metadata = reactor.toolProgression.GetPartMetadata(toolParts);
			}
		}
	}

	public override string GetTitleText(GhostReactor reactor)
	{
		FetchMetadata(reactor);
		if (metadata == null)
		{
			return "Unknown";
		}
		return metadata.name;
	}

	public override string GetBodyText(GhostReactor reactor)
	{
		FetchMetadata(reactor);
		if (metadata == null)
		{
			return "Unknown";
		}
		return metadata.description;
	}

	public override string GetAnnotationText(GhostReactor reactor)
	{
		FetchMetadata(reactor);
		if (metadata == null)
		{
			return "Unknown";
		}
		return metadata.annotation;
	}
}
public class GRToolShieldGun : MonoBehaviour
{
	private enum State
	{
		Idle,
		Charging,
		Firing,
		Cooldown,
		Count
	}

	public GameEntity gameEntity;

	public GRTool tool;

	public GRAttributes attributes;

	public GameObject projectilePrefab;

	public GameObject projectileTrailPrefab;

	public Transform firingTransform;

	public List<Collider> colliders;

	public float projectileSpeed = 25f;

	public Color projectileColor = new Color(0.25f, 0.25f, 1f);

	public bool allowAoeHits;

	public float aeoHitRadius = 0.5f;

	public float chargeDuration = 0.75f;

	public float flashDuration = 0.1f;

	public float cooldownDuration;

	public AudioSource audioSource;

	public AudioClip chargeSound;

	public float chargeSoundVolume = 0.5f;

	public AudioClip firingSound;

	public float firingSoundVolume = 0.5f;

	public AudioClip upgrade1FiringSound;

	public AudioClip upgrade2FiringSound;

	public AudioClip upgrade3FiringSound;

	[Header("Haptic")]
	public AbilityHaptic onHaptic;

	private State state;

	private float stateTimeRemaining;

	private bool activatedLocally;

	private bool waitingForButtonRelease;

	private float timeLastFired;

	private float cooldownMinimum = 0.35f;

	private SlingshotProjectile firedProjectile;

	private static List<VRRig> vrRigs = new List<VRRig>(10);

	private void Awake()
	{
		if (tool != null)
		{
			tool.onToolUpgraded += OnToolUpgraded;
			OnToolUpgraded(tool);
		}
	}

	private void OnToolUpgraded(GRTool tool)
	{
		if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.ShieldGunStrength1))
		{
			firingSound = upgrade1FiringSound;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.ShieldGunStrength2))
		{
			firingSound = upgrade2FiringSound;
		}
		else if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.ShieldGunStrength3))
		{
			firingSound = upgrade3FiringSound;
		}
	}

	private bool IsHeldLocal()
	{
		return gameEntity.heldByActorNumber == PhotonNetwork.LocalPlayer.ActorNumber;
	}

	public void Update()
	{
		float deltaTime = Time.deltaTime;
		if (IsHeldLocal() || activatedLocally)
		{
			OnUpdateAuthority(deltaTime);
		}
		else
		{
			OnUpdateRemote(deltaTime);
		}
	}

	private void OnUpdateAuthority(float dt)
	{
		switch (state)
		{
		case State.Idle:
			if (tool.HasEnoughEnergy() && IsButtonHeld())
			{
				SetStateAuthority(State.Charging);
				activatedLocally = true;
			}
			break;
		case State.Charging:
		{
			bool flag = IsButtonHeld();
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Firing);
			}
			else if (!flag)
			{
				SetStateAuthority(State.Idle);
				activatedLocally = false;
			}
			break;
		}
		case State.Firing:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f)
			{
				SetStateAuthority(State.Cooldown);
			}
			break;
		case State.Cooldown:
			stateTimeRemaining -= dt;
			if (stateTimeRemaining <= 0f && !IsButtonHeld())
			{
				SetStateAuthority(State.Idle);
				activatedLocally = false;
			}
			break;
		}
	}

	private void OnUpdateRemote(float dt)
	{
		State state = (State)gameEntity.GetState();
		if (state != this.state)
		{
			SetStateAuthority(state);
		}
	}

	private void SetStateAuthority(State newState)
	{
		SetState(newState);
		gameEntity.RequestState(gameEntity.id, (long)newState);
	}

	private void SetState(State newState)
	{
		if (newState != state && CanChangeState((long)newState))
		{
			state = newState;
			switch (state)
			{
			case State.Charging:
				StartCharge();
				stateTimeRemaining = chargeDuration;
				break;
			case State.Firing:
				StartFiring();
				stateTimeRemaining = flashDuration;
				break;
			case State.Cooldown:
				stateTimeRemaining = cooldownDuration;
				break;
			case State.Idle:
				stateTimeRemaining = -1f;
				break;
			}
		}
	}

	private void StartCharge()
	{
		if (chargeSound != null)
		{
			audioSource.PlayOneShot(chargeSound, chargeSoundVolume);
		}
		if (IsHeldLocal())
		{
			PlayVibration(GorillaTagger.Instance.tapHapticStrength, chargeDuration);
		}
	}

	private void StartFiring()
	{
		if (firingSound != null)
		{
			audioSource.PlayOneShot(firingSound, firingSoundVolume);
		}
		timeLastFired = Time.time;
		tool.UseEnergy();
		UnityEngine.Vector3 position = firingTransform.position;
		UnityEngine.Vector3 velocity = firingTransform.forward * projectileSpeed;
		float scale = GTPlayer.Instance.scale;
		int hash = PoolUtils.GameObjHashCode(projectilePrefab);
		firedProjectile = ObjectPools.instance.Instantiate(hash).GetComponent<SlingshotProjectile>();
		firedProjectile.transform.localScale = UnityEngine.Vector3.one * scale;
		if (projectileTrailPrefab != null)
		{
			int trailHash = PoolUtils.GameObjHashCode(projectileTrailPrefab);
			AttachTrail(trailHash, firedProjectile.gameObject, position, blueTeam: false, orangeTeam: false);
		}
		Collider component = firedProjectile.gameObject.GetComponent<Collider>();
		if (component != null)
		{
			for (int i = 0; i < colliders.Count; i++)
			{
				Physics.IgnoreCollision(colliders[i], component);
			}
		}
		if (IsHeldLocal())
		{
			firedProjectile.OnImpact += OnProjectileImpact;
		}
		onHaptic.PlayIfHeldLocal(gameEntity);
		firedProjectile.Launch(position, velocity, NetworkSystem.Instance.LocalPlayer, blueTeam: false, orangeTeam: false, 1, scale, shouldOverrideColor: true, projectileColor);
	}

	private void AttachTrail(int trailHash, GameObject newProjectile, UnityEngine.Vector3 location, bool blueTeam, bool orangeTeam)
	{
		GameObject gameObject = ObjectPools.instance.Instantiate(trailHash);
		SlingshotProjectileTrail component = gameObject.GetComponent<SlingshotProjectileTrail>();
		if (GTExt.IsNull(component))
		{
			ObjectPools.instance.Destroy(gameObject);
		}
		newProjectile.transform.position = location;
		component.AttachTrail(newProjectile, blueTeam, orangeTeam);
	}

	private void OnProjectileImpact(SlingshotProjectile projectile, UnityEngine.Vector3 impactPos, NetPlayer hitPlayer)
	{
		projectile.OnImpact -= OnProjectileImpact;
		GRPlayer gRPlayer = null;
		if (hitPlayer != null && VRRigCache.Instance.TryGetVrrig(hitPlayer, out var playerRig) && playerRig.Rig != null)
		{
			gRPlayer = playerRig.Rig.GetComponent<GRPlayer>();
		}
		else if (allowAoeHits)
		{
			vrRigs.Clear();
			vrRigs.Add(VRRig.LocalRig);
			VRRigCache.Instance.GetAllUsedRigs(vrRigs);
			VRRig vRRig = null;
			float num = float.MaxValue;
			for (int i = 0; i < vrRigs.Count; i++)
			{
				float sqrMagnitude = (vrRigs[i].bodyTransform.position - impactPos).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					vRRig = vrRigs[i];
				}
			}
			if (vRRig != null)
			{
				gRPlayer = vRRig.GetComponent<GRPlayer>();
			}
		}
		if (gRPlayer != null)
		{
			int num2 = 0;
			if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.ShieldGunStrength1))
			{
				num2 |= 1;
			}
			if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.ShieldGunStrength2))
			{
				num2 |= 2;
			}
			if (tool.HasUpgradeInstalled(GRToolProgressionManager.ToolParts.ShieldGunStrength3))
			{
				num2 |= 4;
			}
			gameEntity.manager.ghostReactorManager.RequestGrantPlayerShield(gRPlayer, attributes.CalculateFinalValueForAttribute(GRAttributeType.ShieldSize), num2);
		}
	}

	private bool IsButtonHeld()
	{
		if (!IsHeldLocal())
		{
			return false;
		}
		if (!GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			return false;
		}
		int num = out_gamePlayer.FindHandIndex(gameEntity.id);
		if (num == -1)
		{
			return false;
		}
		return ControllerInputPoller.TriggerFloat(GamePlayer.IsLeftHand(num) ? XRNode.LeftHand : XRNode.RightHand) > 0.25f;
	}

	private void PlayVibration(float strength, float duration)
	{
		if (IsHeldLocal() && GamePlayer.TryGetGamePlayer(gameEntity.heldByActorNumber, out var out_gamePlayer))
		{
			int num = out_gamePlayer.FindHandIndex(gameEntity.id);
			if (num != -1)
			{
				GorillaTagger.Instance.StartVibration(GamePlayer.IsLeftHand(num), strength, duration);
			}
		}
	}

	public bool CanChangeState(long newStateIndex)
	{
		if (newStateIndex < 0 || newStateIndex >= 4)
		{
			return false;
		}
		if ((int)newStateIndex == 2)
		{
			return Time.time > timeLastFired + cooldownMinimum;
		}
		return true;
	}
}
