	{
	}

	public override void OnSerializeRead(PhotonStream stream, PhotonMessageInfo info)
	{
	}

	public override GameModeType GameType()
	{
		return GameModeType.Guardian;
	}

	public override string GameModeName()
	{
		return "GUARDIAN";
	}

	public override string GameModeNameRoomLabel()
	{
		if (!LocalisationManager.TryGetKeyForCurrentLocale("GAME_MODE_GUARDIAN_ROOM_LABEL", out var result, "(GUARDIAN GAME)"))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::GORILLA_GAME_MANAGER] Failed to get key for Game Mode [GAME_MODE_GUARDIAN_ROOM_LABEL]");
		}
		return result;
	}

