	private void LocalPlaySlamEffect(UnityEngine.Vector3 location, UnityEngine.Vector3 direction)
	{
		ObjectPools.instance.Instantiate(slamImpactPrefab, location, UnityEngine.Quaternion.LookRotation(direction));
	}
