[Obsolete]
public class GorillaPawn : MonoBehaviour
{
	[SerializeField]
	private Transform _transform;

	[SerializeField]
	private Transform _handLeft;

	[SerializeField]
	private Transform _handRight;

	[SerializeField]
	private Transform _head;

	[Space]
	[SerializeField]
	private VRRig _rig;

	[SerializeField]
	private ZoneEntityBSP _zoneEntity;

	[Space]
	[SerializeField]
	private XformNode _handLeftXform;

	[SerializeField]
	private XformNode _handRightXform;

	[SerializeField]
	private XformNode _bodyXform;

	[SerializeField]
	private XformNode _headXform;

	[Space]
	private int _id;

	private int _index;

	private bool _invalid;

	public const int MAX_PAWNS = 10;

	private static GorillaPawn[] _gPawns = new GorillaPawn[10];

	private static int _gPawnActiveCount = 0;

	private static UnityEngine.Matrix4x4[] _gShaderData = new UnityEngine.Matrix4x4[10];

	public VRRig rig => _rig;

	public ZoneEntityBSP zoneEntity => _zoneEntity;

	public new Transform transform => _transform;

	public XformNode handLeft => _handLeftXform;

	public XformNode handRight => _handRightXform;

	public XformNode body => _bodyXform;

	public XformNode head => _headXform;

	public static GorillaPawn[] AllPawns => _gPawns;

	public static int ActiveCount => _gPawnActiveCount;

	public static UnityEngine.Matrix4x4[] ShaderData => _gShaderData;

	private void Awake()
	{
		Setup(force: false);
	}

	private void Setup(bool force)
	{
		_transform = base.transform;
		_rig = GetComponentInChildren<VRRig>();
		if (!_rig)
		{
			return;
		}
		_zoneEntity = _rig.zoneEntity;
		bool flag = force || _handLeft.AsNull() == null;
		bool flag2 = force || _handRight.AsNull() == null;
		bool flag3 = force || _head.AsNull() == null;
		if (!flag && !flag2 && !flag3)
		{
			return;
		}
		Transform[] bones = _rig.mainSkin.bones;
		foreach (Transform transform in bones)
		{
			string text = transform.name;
			if (flag3 && text.StartsWith("head", StringComparison.OrdinalIgnoreCase))
			{
				_head = transform;
				_headXform = new XformNode();
				_headXform.localPosition = new UnityEngine.Vector3(0f, 0.13f, 0.015f);
				_headXform.radius = 0.12f;
				_headXform.parent = transform;
			}
			else if (flag && text.StartsWith("hand.L", StringComparison.OrdinalIgnoreCase))
			{
				_handLeft = transform;
				_handLeftXform = new XformNode();
				_handLeftXform.localPosition = new UnityEngine.Vector3(-0.014f, 0.034f, 0f);
				_handLeftXform.radius = 0.044f;
				_handLeftXform.parent = transform;
			}
			else if (flag2 && text.StartsWith("hand.R", StringComparison.OrdinalIgnoreCase))
			{
				_handRight = transform;
				_handRightXform = new XformNode();
				_handRightXform.localPosition = new UnityEngine.Vector3(0.014f, 0.034f, 0f);
				_handRightXform.radius = 0.044f;
				_handRightXform.parent = transform;
			}
		}
	}

	private bool CanRun()
	{
		if (_gPawnActiveCount > 10)
		{
			UnityEngine.Debug.LogError($"Cannot register more than {10} pawns.");
			return false;
		}
		return true;
	}

	private void OnEnable()
	{
		if (CanRun())
		{
			_id = -1;
			if ((bool)_rig && _rig.OwningNetPlayer != null)
			{
				_id = _rig.OwningNetPlayer.ActorNumber;
			}
			_index = _gPawnActiveCount++;
			_gPawns[_index] = this;
		}
	}

	private void OnDisable()
	{
		_id = -1;
		if (CanRun() && _index >= 0 && _index < _gPawnActiveCount - 1)
		{
			int num = --_gPawnActiveCount;
			_gPawns.Swap(_index, num);
			_index = num;
		}
	}

	private void OnDestroy()
	{
		int num = _gPawns.IndexOfRef(this);
		_gPawns[num] = null;
		Array.Sort(_gPawns, ComparePawns);
		int i;
		for (i = 0; i < _gPawns.Length && (bool)_gPawns[i]; i++)
		{
		}
		_gPawnActiveCount = i;
	}

	private static int ComparePawns(GorillaPawn x, GorillaPawn y)
	{
		bool flag = x.AsNull() == null;
		bool flag2 = y.AsNull() == null;
		if (flag && flag2)
		{
			return 0;
		}
		if (flag)
		{
			return 1;
		}
		if (flag2)
		{
			return -1;
		}
		return x._index.CompareTo(y._index);
	}

	public static void SyncPawnData()
	{
		UnityEngine.Matrix4x4[] gShaderData = _gShaderData;
		m4x4 m4x5 = default(m4x4);
		for (int i = 0; i < _gPawnActiveCount; i++)
		{
			GorillaPawn obj = _gPawns[i];
			UnityEngine.Vector4 v = obj._headXform.worldPosition;
			UnityEngine.Vector4 v2 = obj._bodyXform.worldPosition;
			UnityEngine.Vector4 v3 = obj._handLeftXform.worldPosition;
			UnityEngine.Vector4 v4 = obj._handRightXform.worldPosition;
			m4x5.SetRow0(ref v);
			m4x5.SetRow1(ref v2);
			m4x5.SetRow2(ref v3);
			m4x5.SetRow3(ref v4);
			m4x5.Push(ref gShaderData[i]);
		}
		for (int j = _gPawnActiveCount; j < 10; j++)
		{
			MatrixUtils.Clear(ref gShaderData[j]);
		}
	}
}
public class GorillaScoreBoard : MonoBehaviour
{
	public GameObject scoreBoardLinePrefab;

	public int startingYValue;

	public int lineHeight;

	public bool includeMMR;

	public bool isActive;

	public GameObject linesParent;

	public float bigRoomYOffset = 32.5f;

	[SerializeField]
	public List<GorillaPlayerScoreboardLine> lines;

	private List<RectTransform> linesRTs = new List<RectTransform>();

	public GameObject textsParent;

	public TextMeshPro boardText;

	public TextMeshPro buttonText;

	public bool needsUpdate;

	public TextMeshPro notInRoomText;

	public string initialGameMode;

	private string tempGmName;

	private string gmName;

	private const string error = "ERROR";

	private List<string> gmNames;

	private bool _isDirty = true;

	private StringBuilder stringBuilder = new StringBuilder(220);

	private StringBuilder buttonStringBuilder = new StringBuilder(720);

	public bool IsDirty
	{
		get
		{
			if (!_isDirty)
			{
				return string.IsNullOrEmpty(initialGameMode);
			}
			return true;
		}
		set
		{
			_isDirty = value;
		}
	}

	public void SetSleepState(bool awake)
	{
		boardText.enabled = awake;
		buttonText.enabled = awake;
		if (linesParent != null)
		{
			linesParent.SetActive(awake);
		}
	}

	private string GetBeginningString()
	{
		string text = $" ({10})";
		if (NetworkSystem.Instance.SessionIsSubscription)
		{
			text = $" ({20})";
		}
		return "ROOM ID: " + (NetworkSystem.Instance.SessionIsPrivate ? "-PRIVATE- GAME: " : (NetworkSystem.Instance.RoomName + "   GAME: ")) + RoomType() + text + "\n  PLAYER     COLOR  MUTE   REPORT";
	}

	private string RoomType()
	{
		initialGameMode = RoomSystem.RoomGameMode;
		gmNames = GorillaGameModes.GameMode.gameModeNames;
		gmName = "ERROR";
		int count = gmNames.Count;
		int num = initialGameMode.LastIndexOf('|');
		if (num >= 0)
		{
			tempGmName = initialGameMode.Substring(num + 1);
			for (int i = 0; i < count; i++)
			{
				if (tempGmName == gmNames[i])
				{
					gmName = tempGmName;
					break;
				}
			}
		}
		else
		{
			for (int j = 0; j < count; j++)
			{
				tempGmName = gmNames[j];
				if (initialGameMode.Contains(tempGmName))
				{
					gmName = tempGmName;
					break;
				}
			}
		}
		return gmName;
	}

	public void RedrawPlayerLines()
	{
		stringBuilder.Clear();
		stringBuilder.Append(GetBeginningString());
		buttonStringBuilder.Clear();
		bool flag = KIDManager.HasPermissionToUseFeature(EKIDFeatures.Custom_Nametags);
		int num = 0;
		for (int i = 0; i < lines.Count; i++)
		{
			if (lines[i].gameObject.activeInHierarchy)
			{
				num++;
			}
		}
		if (num > 10)
		{
			linesParent.transform.localScale = new UnityEngine.Vector3(1f, 0.5f, 1f);
			linesParent.transform.localPosition = new UnityEngine.Vector3(0f, bigRoomYOffset, 0f);
			textsParent.transform.localScale = new UnityEngine.Vector3(1f, 0.5f, 1f);
		}
		else
		{
			linesParent.transform.localScale = UnityEngine.Vector3.one;
			linesParent.transform.localPosition = UnityEngine.Vector3.zero;
			textsParent.transform.localScale = UnityEngine.Vector3.one;
		}
		for (int j = 0; j < lines.Count; j++)
		{
			try
			{
				if (!lines[j].gameObject.activeInHierarchy)
				{
					continue;
				}
				linesRTs[j].localPosition = new UnityEngine.Vector3(0f, startingYValue - lineHeight * j, 0f);
				if (lines[j].linePlayer == null || !lines[j].linePlayer.InRoom)
				{
					continue;
				}
				stringBuilder.Append("\n ");
				SubscriptionManager.SubscriptionDetails subscriptionDetails = SubscriptionManager.GetSubscriptionDetails(lines[j].linePlayer);
				if (subscriptionDetails.active && subscriptionDetails.tier > 0)
				{
					stringBuilder.Append("<color=#ffc600>");
				}
				else
				{
					stringBuilder.Append("<color=#ffffff>");
				}
				stringBuilder.Append(flag ? lines[j].playerNameVisible : lines[j].linePlayer.DefaultName);
				stringBuilder.Append("</color>");
				if (lines[j].linePlayer != NetworkSystem.Instance.LocalPlayer)
				{
					if (lines[j].reportButton.isActiveAndEnabled)
					{
						buttonStringBuilder.Append("MUTE                                REPORT\n");
					}
					else
					{
						buttonStringBuilder.Append("MUTE                HATE SPEECH    TOXICITY     CHEATING       CANCEL\n");
					}
				}
				else
				{
					buttonStringBuilder.Append("\n");
				}
			}
			catch
			{
			}
		}
		boardText.text = stringBuilder.ToString();
		buttonText.text = buttonStringBuilder.ToString();
		_isDirty = false;
	}

	public string NormalizeName(bool doIt, string text)
	{
		if (doIt)
		{
			text = new string(Array.FindAll(text.ToCharArray(), (char c) => Utils.IsASCIILetterOrDigit(c)));
			if (text.Length > 12)
			{
				text = text.Substring(0, 12);
			}
			text = text.ToUpper();
		}
		return text;
	}

	private void Start()
	{
		linesRTs.Clear();
		for (int i = 0; i < lines.Count; i++)
		{
			linesRTs.Add(lines[i].GetComponent<RectTransform>());
		}
		GorillaScoreboardTotalUpdater.RegisterScoreboard(this);
	}

	private void OnEnable()
	{
		GorillaScoreboardTotalUpdater.RegisterScoreboard(this);
		_isDirty = true;
		SubscriptionManager.OnSubscriptionData = (Action)Delegate.Remove(SubscriptionManager.OnSubscriptionData, new Action(SetDirty));
		SubscriptionManager.OnSubscriptionData = (Action)Delegate.Combine(SubscriptionManager.OnSubscriptionData, new Action(SetDirty));
	}

	private void OnDisable()
	{
		GorillaScoreboardTotalUpdater.UnregisterScoreboard(this);
		SubscriptionManager.OnSubscriptionData = (Action)Delegate.Remove(SubscriptionManager.OnSubscriptionData, new Action(SetDirty));
	}

	private void SetDirty()
	{
		_isDirty = true;
	}
}
public class GorillaSimpleBackgroundWorkerManager : MonoBehaviour
{
	private static GorillaSimpleBackgroundWorkerManager _instance;

	private static bool hasInstance = false;

	private static long MINIMUM_TICKS_OF_WORK = 10000L;

	public Queue<IGorillaSimpleBackgroundWorker> workerSignups = new Queue<IGorillaSimpleBackgroundWorker>();

	private Stopwatch stopwatch = new Stopwatch();

	protected void Awake()
	{
		if (hasInstance && _instance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			SetInstance(this);
		}
	}

	private static void SetInstance(GorillaSimpleBackgroundWorkerManager manager)
	{
		_instance = manager;
		hasInstance = true;
		if (UnityEngine.Application.isPlaying)
		{
			UnityEngine.Object.DontDestroyOnLoad(manager);
		}
	}

	public static void CreateManager()
	{
		GameObject obj = new GameObject("GorillaSimpleBackgroundWorkerManager");
		GorillaSimpleBackgroundWorkerManager instance = obj.AddComponent<GorillaSimpleBackgroundWorkerManager>();
		UnityEngine.Object.DontDestroyOnLoad(obj);
		SetInstance(instance);
	}

	public static long DoWork(long ticksOfWork)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		return _instance._DoWork(ticksOfWork);
	}

	public long _DoWork(long ticksOfWork)
	{
		stopwatch.Restart();
		if (ticksOfWork < MINIMUM_TICKS_OF_WORK)
		{
			ticksOfWork = MINIMUM_TICKS_OF_WORK;
		}
		while (stopwatch.ElapsedTicks < ticksOfWork && workerSignups.Count > 0)
		{
			workerSignups.Dequeue()?.SimpleWork();
		}
		return stopwatch.ElapsedTicks;
	}

	public static void WorkerSignup(IGorillaSimpleBackgroundWorker worker)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		_instance.workerSignups.Enqueue(worker);
	}
}
public interface IGorillaSimpleBackgroundWorker
{
	void SimpleWork();
}
public class GorillaSlicerSimpleManager : MonoBehaviour
{
	public enum UpdateStep
	{
		FixedUpdate,
		Update,
		LateUpdate
	}

	public static GorillaSlicerSimpleManager instance;

	public static bool hasInstance;

	public List<IGorillaSliceableSimple> fixedUpdateSlice;

	public List<IGorillaSliceableSimple> updateSlice;

	public List<IGorillaSliceableSimple> lateUpdateSlice;

	public long ticksPerFrame = 1000L;

	public long ticksThisFrame;

	public int updateIndex = -1;

	public int startingIndex = -1;

	public Stopwatch sW;

	public Dictionary<IGorillaSliceableSimple, long> lastRunTicks = new Dictionary<IGorillaSliceableSimple, long>();

	protected void Awake()
	{
		if (hasInstance && instance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			SetInstance(this);
		}
	}

	public static void CreateManager()
	{
		GorillaSlicerSimpleManager gorillaSlicerSimpleManager = new GameObject("GorillaSlicerSimpleManager").AddComponent<GorillaSlicerSimpleManager>();
		gorillaSlicerSimpleManager.fixedUpdateSlice = new List<IGorillaSliceableSimple>();
		gorillaSlicerSimpleManager.updateSlice = new List<IGorillaSliceableSimple>();
		gorillaSlicerSimpleManager.lateUpdateSlice = new List<IGorillaSliceableSimple>();
		gorillaSlicerSimpleManager.sW = new Stopwatch();
		SetInstance(gorillaSlicerSimpleManager);
	}

	private static void SetInstance(GorillaSlicerSimpleManager manager)
	{
		instance = manager;
		hasInstance = true;
		if (UnityEngine.Application.isPlaying)
		{
			UnityEngine.Object.DontDestroyOnLoad(manager);
		}
	}

	public static void RegisterSliceable(IGorillaSliceableSimple gSS)
	{
		RegisterSliceable(gSS, UpdateStep.Update);
	}

	public static void RegisterSliceable(IGorillaSliceableSimple gSS, UpdateStep step)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		instance.lastRunTicks.TryAdd(gSS, 0L);
		switch (step)
		{
		case UpdateStep.FixedUpdate:
			if (!instance.fixedUpdateSlice.Contains(gSS))
			{
				instance.fixedUpdateSlice.Add(gSS);
			}
			break;
		case UpdateStep.Update:
			if (!instance.updateSlice.Contains(gSS))
			{
				instance.updateSlice.Add(gSS);
			}
			break;
		case UpdateStep.LateUpdate:
			if (!instance.lateUpdateSlice.Contains(gSS))
			{
				instance.lateUpdateSlice.Add(gSS);
			}
			break;
		}
	}

	public static bool UnregisterSliceable(IGorillaSliceableSimple gSS)
	{
		if (UnregisterSliceable(gSS, UpdateStep.Update))
		{
			return true;
		}
		if (UnregisterSliceable(gSS, UpdateStep.LateUpdate))
		{
			return true;
		}
		return UnregisterSliceable(gSS, UpdateStep.FixedUpdate);
	}

	public static bool UnregisterSliceable(IGorillaSliceableSimple gSS, UpdateStep step)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		switch (step)
		{
		case UpdateStep.FixedUpdate:
			if (instance.fixedUpdateSlice.Contains(gSS))
			{
				instance.fixedUpdateSlice.Remove(gSS);
				return true;
			}
			break;
		case UpdateStep.Update:
			if (instance.updateSlice.Contains(gSS))
			{
				instance.updateSlice.Remove(gSS);
				return true;
			}
			break;
		case UpdateStep.LateUpdate:
			if (instance.lateUpdateSlice.Contains(gSS))
			{
				instance.lateUpdateSlice.Remove(gSS);
				return true;
			}
			break;
		}
		return false;
	}

	public void FixedUpdate()
	{
		startingIndex = updateIndex;
		if (updateIndex < 0 || updateIndex >= fixedUpdateSlice.Count + updateSlice.Count + lateUpdateSlice.Count)
		{
			updateIndex = 0;
		}
		sW.Restart();
		while (ticksThisFrame + sW.ElapsedTicks < ticksPerFrame && updateIndex < fixedUpdateSlice.Count)
		{
			IGorillaSliceableSimple gorillaSliceableSimple = fixedUpdateSlice[updateIndex];
			if (startingIndex != updateIndex && ticksThisFrame + sW.ElapsedTicks + lastRunTicks[gorillaSliceableSimple] >= ticksPerFrame)
			{
				ticksThisFrame = ticksPerFrame;
				break;
			}
			long elapsedTicks = sW.ElapsedTicks;
			if (0 <= updateIndex && updateIndex < fixedUpdateSlice.Count && !(gorillaSliceableSimple is MonoBehaviour { isActiveAndEnabled: false }))
			{
				try
				{
					gorillaSliceableSimple.SliceUpdate();
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
			lastRunTicks[gorillaSliceableSimple] = sW.ElapsedTicks - elapsedTicks;
			updateIndex++;
		}
		ticksThisFrame += sW.ElapsedTicks;
		sW.Stop();
	}

	public void Update()
	{
		int count = fixedUpdateSlice.Count;
		int count2 = updateSlice.Count;
		int num = count + count2;
		sW.Restart();
		while (ticksThisFrame + sW.ElapsedTicks < ticksPerFrame && count <= updateIndex && updateIndex < num)
		{
			IGorillaSliceableSimple gorillaSliceableSimple = updateSlice[updateIndex - count];
			if (startingIndex != updateIndex && ticksThisFrame + sW.ElapsedTicks + lastRunTicks[gorillaSliceableSimple] >= ticksPerFrame)
			{
				ticksThisFrame = ticksPerFrame;
				break;
			}
			long elapsedTicks = sW.ElapsedTicks;
			if (0 <= updateIndex - count && updateIndex - count < updateSlice.Count && !(gorillaSliceableSimple is MonoBehaviour { isActiveAndEnabled: false }))
			{
				try
				{
					gorillaSliceableSimple.SliceUpdate();
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
			lastRunTicks[gorillaSliceableSimple] = sW.ElapsedTicks - elapsedTicks;
			updateIndex++;
		}
		ticksThisFrame += sW.ElapsedTicks;
		sW.Stop();
	}

	public void LateUpdate()
	{
		int count = fixedUpdateSlice.Count;
		int count2 = updateSlice.Count;
		int count3 = lateUpdateSlice.Count;
		int num = count + count2;
		int num2 = num + count3;
		sW.Restart();
		while (ticksThisFrame + sW.ElapsedTicks < ticksPerFrame && num <= updateIndex && updateIndex < num2)
		{
			IGorillaSliceableSimple gorillaSliceableSimple = lateUpdateSlice[updateIndex - num];
			if (startingIndex != updateIndex && ticksThisFrame + sW.ElapsedTicks + lastRunTicks[gorillaSliceableSimple] >= ticksPerFrame)
			{
				ticksThisFrame = ticksPerFrame;
				break;
			}
			long elapsedTicks = sW.ElapsedTicks;
			if (0 <= updateIndex - num && updateIndex - num < lateUpdateSlice.Count && !(gorillaSliceableSimple is MonoBehaviour { isActiveAndEnabled: false }))
			{
				try
				{
					gorillaSliceableSimple.SliceUpdate();
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
			lastRunTicks[gorillaSliceableSimple] = sW.ElapsedTicks - elapsedTicks;
			updateIndex++;
		}
		sW.Stop();
		if (updateIndex >= num2)
		{
			updateIndex = -1;
		}
		ticksThisFrame = 0L;
	}
}
public class GorillaSpeakerLoudness : MonoBehaviour, IGorillaSliceableSimple, IDynamicFloat
{
	private bool isSpeaking;

	private float loudness;

	[SerializeField]
	private float normalizedMax = 0.175f;

	private bool isMicEnabled;

	private RigContainer rigContainer;

	private Speaker speaker;

	private SpeakerVoiceToLoudness speakerVoiceToLoudness;

	private Recorder recorder;

	private VoiceToLoudness voiceToLoudness;

	private float smoothedLoudness;

	private float lastLoudness;

	private float timeSinceLoudnessChange;

	private float loudnessUpdateCheckRate = 0.2f;

	private float loudnessBlendStrength = 2f;

	private bool permission;

	private bool micConnected;

	private float timeLastUpdated;

	private float deltaTime;

	private AudioClip offlineMic;

	private float[] voiceSampleBuffer = new float[128];

	public bool IsSpeaking => isSpeaking;

	public float Loudness => loudness;

	public float LoudnessNormalized => Mathf.Min(loudness / normalizedMax, 1f);

	public float floatValue => LoudnessNormalized;

	public bool IsMicEnabled => isMicEnabled;

	public float SmoothedLoudness => smoothedLoudness;

	private void Start()
	{
		rigContainer = GetComponent<RigContainer>();
		timeLastUpdated = Time.time;
		deltaTime = Time.deltaTime;
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void SliceUpdate()
	{
		deltaTime = Time.time - timeLastUpdated;
		timeLastUpdated = Time.time;
		UpdateMicEnabled();
		UpdateLoudness();
		UpdateSmoothedLoudness();
	}

	private void UpdateMicEnabled()
	{
		if (!(rigContainer == null))
		{
			VRRig rig = rigContainer.Rig;
			if (rig.isOfflineVRRig)
			{
				isMicEnabled = CheckMicConnection();
				rig.IsMicEnabled = isMicEnabled;
			}
			else
			{
				isMicEnabled = rig.IsMicEnabled;
			}
		}
	}

	private bool CheckMicConnection()
	{
		permission = permission || MicPermissionsManager.HasMicPermission();
		if (permission && !micConnected && Microphone.devices != null)
		{
			micConnected = Microphone.devices.Length != 0;
		}
		if (permission)
		{
			return micConnected;
		}
		return false;
	}

	private void UpdateLoudness()
	{
		if (rigContainer == null)
		{
			return;
		}
		PhotonVoiceView voice = rigContainer.Voice;
		if (voice != null && speaker == null)
		{
			speaker = voice.SpeakerInUse;
		}
		if (recorder == null)
		{
			recorder = voice?.RecorderInUse;
		}
		if (recorder != null && offlineMic != null)
		{
			Microphone.End(UnityMicrophone.devices[0]);
			UnityEngine.Object.Destroy(offlineMic);
			offlineMic = null;
			recorder.RestartRecording(force: true);
		}
		VRRig rig = rigContainer.Rig;
		if (rig.isOfflineVRRig && recorder == null && isMicEnabled && !Microphone.IsRecording(UnityMicrophone.devices[0]))
		{
			offlineMic = Microphone.Start(UnityMicrophone.devices[0], loop: true, 1, 16000);
		}
		if ((rig.remoteUseReplacementVoice || rig.localUseReplacementVoice || GorillaComputer.instance.voiceChatOn == "FALSE") && rig.SpeakingLoudness > 0f && !rigContainer.ForceMute && !rigContainer.Muted)
		{
			isSpeaking = true;
			loudness = rig.SpeakingLoudness;
		}
		else if (voice != null && voice.IsSpeaking)
		{
			isSpeaking = true;
			if (speaker != null)
			{
				if (speakerVoiceToLoudness == null)
				{
					speakerVoiceToLoudness = speaker.GetComponent<SpeakerVoiceToLoudness>();
				}
				if (speakerVoiceToLoudness != null)
				{
					loudness = speakerVoiceToLoudness.loudness;
				}
			}
			else
			{
				loudness = 0f;
			}
		}
		else if (voice != null && recorder != null && NetworkSystem.Instance.IsObjectLocallyOwned(voice.gameObject) && recorder.IsCurrentlyTransmitting)
		{
			if (voiceToLoudness == null)
			{
				voiceToLoudness = recorder.GetComponent<VoiceToLoudness>();
				if (voiceToLoudness == null)
				{
					recorder.AddComponent<VoiceToLoudness>();
				}
			}
			isSpeaking = true;
			if (voiceToLoudness != null)
			{
				loudness = voiceToLoudness.Loudness;
			}
			else
			{
				loudness = 0f;
			}
		}
		else if (offlineMic != null && recorder == null && isMicEnabled && Microphone.IsRecording(UnityMicrophone.devices[0]))
		{
			isSpeaking = true;
			int num = Mathf.Min(Mathf.CeilToInt(deltaTime * 16000f), 16000);
			if (num > voiceSampleBuffer.Length)
			{
				Array.Resize(ref voiceSampleBuffer, num);
			}
			if (offlineMic.samples >= num && offlineMic.GetData(voiceSampleBuffer, offlineMic.samples - num))
			{
				float num2 = 0f;
				for (int i = 0; i < voiceSampleBuffer.Length; i++)
				{
					num2 += Mathf.Abs(voiceSampleBuffer[i]);
				}
				loudness = num2 / (float)voiceSampleBuffer.Length;
			}
		}
		else
		{
			isSpeaking = false;
			loudness = 0f;
		}
	}

	private void UpdateSmoothedLoudness()
	{
		if (!isSpeaking)
		{
			smoothedLoudness = 0f;
		}
		else if (Mathf.Approximately(loudness, lastLoudness))
		{
			if (timeSinceLoudnessChange > loudnessUpdateCheckRate)
			{
				smoothedLoudness = 0.001f;
				return;
			}
			smoothedLoudness = Mathf.Lerp(smoothedLoudness, loudness, Mathf.Clamp01(loudnessBlendStrength * deltaTime));
			timeSinceLoudnessChange += deltaTime;
		}
		else
		{
			timeSinceLoudnessChange = 0f;
			smoothedLoudness = Mathf.Lerp(smoothedLoudness, loudness, Mathf.Clamp01(loudnessBlendStrength * deltaTime));
			lastLoudness = loudness;
		}
	}
}
public class GorillaTagCompetitiveForcedLeaveRoomVolume : MonoBehaviour
{
	private GorillaTagCompetitiveManager CompetitiveManager;

	private Collider VolumeCollider;

	private void Start()
	{
		VolumeCollider = GetComponent<Collider>();
		CompetitiveManager = GorillaGameModes.GameMode.GetGameModeInstance(GameModeType.InfectionCompetitive) as GorillaTagCompetitiveManager;
		if (CompetitiveManager != null)
		{
			CompetitiveManager.RegisterForcedLeaveVolume(this);
		}
	}

	private void OnDestroy()
	{
		if (CompetitiveManager != null)
		{
			CompetitiveManager.UnregisterForcedLeaveVolume(this);
		}
	}

	public bool ContainsPoint(UnityEngine.Vector3 position)
	{
		if (VolumeCollider is SphereCollider sphereCollider)
		{
			return UnityEngine.Vector3.SqrMagnitude(position - (sphereCollider.transform.position + sphereCollider.center)) <= sphereCollider.radius * sphereCollider.radius;
		}
		if (VolumeCollider is BoxCollider { bounds: var bounds })
		{
			return bounds.Contains(position);
		}
		return false;
	}
}
public class GorillaTagCompetitiveManager : GorillaTagManager
{
	public enum GameState
	{
		None,
		WaitingForPlayers,
		StartingCountdown,
		Playing,
		PostRound
	}

	[SerializeField]
	private float startCountdownDuration = 3f;

	[SerializeField]
	private float roundDuration = 300f;

	[SerializeField]
	private float postRoundDuration = 15f;

	[SerializeField]
	private float waitingForPlayerPingRoomDuration = 60f;

	private GameState gameState;

	private float stateRemainingTime;

	private float lastActiveTime;

	private float lastWaitingForPlayerPingRoomTime;

	private RankedMultiplayerScore scoring;

	private List<GorillaTagCompetitiveForcedLeaveRoomVolume> forceLeaveRoomVolumes = new List<GorillaTagCompetitiveForcedLeaveRoomVolume>();

	private static List<GorillaTagCompetitiveScoreboard> scoreboards = new List<GorillaTagCompetitiveScoreboard>();

	public bool ShowDebugPing { get; set; }

	public static event Action<GameState> onStateChanged;

	public static event Action<float> onUpdateRemainingTime;

	public static event Action<NetPlayer> onPlayerJoined;

	public static event Action<NetPlayer> onPlayerLeft;

	public static event Action onRoundStart;

	public static event Action onRoundEnd;

	public static event Action<NetPlayer, NetPlayer> onTagOccurred;

	public float GetRoundDuration()
	{
		return roundDuration;
	}

	public GameState GetCurrentGameState()
	{
		return gameState;
	}

	public bool IsMatchActive()
	{
		return gameState == GameState.Playing;
	}

	public static void RegisterScoreboard(GorillaTagCompetitiveScoreboard scoreboard)
	{
		scoreboards.Add(scoreboard);
	}

	public static void DeregisterScoreboard(GorillaTagCompetitiveScoreboard scoreboard)
	{
		scoreboards.Remove(scoreboard);
	}

	public override void StartPlaying()
	{
		base.StartPlaying();
		scoring = GetComponentInChildren<RankedMultiplayerScore>();
		if (scoring != null)
		{
			scoring.Initialize();
		}
		VRRig.LocalRig.EnableRankedTimerWatch(on: true);
		for (int i = 0; i < currentNetPlayerArray.Length; i++)
		{
			if (VRRigCache.Instance.TryGetVrrig(currentNetPlayerArray[i], out var playerRig))
			{
				playerRig.Rig.EnableRankedTimerWatch(on: true);
			}
		}
	}

	public override void StopPlaying()
	{
		base.StopPlaying();
		VRRig.LocalRig.EnableRankedTimerWatch(on: false);
		if (scoring != null)
		{
			scoring.ResetMatch();
			scoring.Unsubscribe();
		}
		for (int i = 0; i < scoreboards.Count; i++)
		{
			scoreboards[i].UpdateScores(gameState, lastActiveTime, null, scoring.PlayerRankedTiers, scoring.ProjectedEloDeltas, currentInfected, scoring.Progression);
		}
	}

	public override void ResetGame()
	{
		base.ResetGame();
		gameState = GameState.None;
	}

	internal override void NetworkLinkSetup(GameModeSerializer netSerializer)
	{
		base.NetworkLinkSetup(netSerializer);
		netSerializer.AddRPCComponent<GorillaTagCompetitiveRPCs>();
	}

	public override void Tick()
	{
		if (stateRemainingTime > 0f)
		{
			stateRemainingTime -= Time.deltaTime;
			if (stateRemainingTime <= 0f)
			{
				UpdateState();
			}
			GorillaTagCompetitiveManager.onUpdateRemainingTime?.Invoke(stateRemainingTime);
		}
		base.Tick();
		if (NetworkSystem.Instance.IsMasterClient)
		{
			if (Time.time - lastWaitingForPlayerPingRoomTime > waitingForPlayerPingRoomDuration)
			{
				PingRoom();
				lastWaitingForPlayerPingRoomTime = Time.time;
			}
			if (Time.time - lastWaitingForPlayerPingRoomTime > 3f)
			{
				ShowDebugPing = false;
			}
		}
		UpdateScoreboards();
	}

	public override void OnMasterClientSwitched(Player newMasterClient)
	{
		base.OnMasterClientSwitched(newMasterClient);
		if (NetworkSystem.Instance.IsMasterClient)
		{
			PingRoom();
			lastWaitingForPlayerPingRoomTime = Time.time;
		}
	}

	public override void OnPlayerEnteredRoom(NetPlayer newPlayer)
	{
		base.OnPlayerEnteredRoom(newPlayer);
		if (newPlayer == NetworkSystem.Instance.LocalPlayer)
		{
			foreach (GorillaTagCompetitiveForcedLeaveRoomVolume forceLeaveRoomVolume in forceLeaveRoomVolumes)
			{
				if (forceLeaveRoomVolume.ContainsPoint(VRRig.LocalRig.transform.position))
				{
					NetworkSystem.Instance.ReturnToSinglePlayer();
					return;
				}
			}
			object value;
			if (NetworkSystem.Instance.IsMasterClient)
			{
				GorillaTagCompetitiveServerApi.Instance.RequestCreateMatchId(delegate(string id)
				{
					ExitGames.Client.Photon.Hashtable propertiesToSet = new ExitGames.Client.Photon.Hashtable { { "matchId", id } };
					PhotonNetwork.CurrentRoom.SetCustomProperties(propertiesToSet);
				});
			}
			else if (PhotonNetwork.CurrentRoom.CustomProperties.TryGetValue("matchId", out value))
			{
				GorillaTagCompetitiveServerApi.Instance.RequestValidateMatchJoin((string)value, delegate(bool valid)
				{
					if (!valid)
					{
						UnityEngine.Debug.LogError("ValidateMatchJoin failed. Leaving room!");
						NetworkSystem.Instance.ReturnToSinglePlayer();
					}
				});
			}
		}
		GorillaTagCompetitiveManager.onPlayerJoined?.Invoke(newPlayer);
		if (VRRigCache.Instance.TryGetVrrig(newPlayer, out var playerRig))
		{
			playerRig.Rig.EnableRankedTimerWatch(on: true);
		}
	}

	public override void OnPlayerLeftRoom(NetPlayer otherPlayer)
	{
		base.OnPlayerLeftRoom(otherPlayer);
		GorillaTagCompetitiveManager.onPlayerLeft?.Invoke(otherPlayer);
		if (VRRigCache.Instance.TryGetVrrig(otherPlayer, out var playerRig))
		{
			playerRig.Rig.EnableRankedTimerWatch(on: false);
		}
	}

	public RankedMultiplayerScore GetScoring()
	{
		return scoring;
	}

	public override bool LocalCanTag(NetPlayer myPlayer, NetPlayer otherPlayer)
	{
		if (base.LocalCanTag(myPlayer, otherPlayer) && gameState != GameState.StartingCountdown)
		{
			return gameState != GameState.PostRound;
		}
		return false;
	}

	public override bool LocalIsTagged(NetPlayer player)
	{
		if (gameState == GameState.StartingCountdown || gameState == GameState.PostRound)
		{
			return false;
		}
		return base.LocalIsTagged(player);
	}

	public override void ReportTag(NetPlayer taggedPlayer, NetPlayer taggingPlayer)
	{
		base.ReportTag(taggedPlayer, taggingPlayer);
	}

	public override GameModeType GameType()
	{
		return GameModeType.InfectionCompetitive;
	}

	public override string GameModeName()
	{
		return "COMP-INFECT";
	}

	public override string GameModeNameRoomLabel()
	{
		if (!LocalisationManager.TryGetKeyForCurrentLocale("GAME_MODE_COMP_INF_ROOM_LABEL", out var result, "(COMP-INFECT GAME)"))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::GORILLA_GAME_MANAGER] Failed to get key for Game Mode [GAME_MODE_COMP_INF_ROOM_LABEL]");
		}
		return result;
	}

	public override bool CanJoinFrienship(NetPlayer player)
	{
		return false;
	}

	public override void UpdateInfectionState()
	{
		if (NetworkSystem.Instance.IsMasterClient && gameState == GameState.Playing && IsEveryoneTagged())
		{
			HandleInfectionRoundComplete();
		}
	}

	public override void HandleTagBroadcast(NetPlayer taggedPlayer, NetPlayer taggingPlayer)
	{
		if (!currentInfected.Contains(taggingPlayer) || !VRRigCache.Instance.TryGetVrrig(taggedPlayer, out var playerRig) || !VRRigCache.Instance.TryGetVrrig(taggingPlayer, out var playerRig2))
		{
			return;
		}
		VRRig rig = playerRig2.Rig;
		VRRig rig2 = playerRig.Rig;
		if (rig.IsPositionInRange(rig2.transform.position, 6f) || rig.CheckTagDistanceRollback(rig2, 6f, 0.2f))
		{
			if (!NetworkSystem.Instance.IsMasterClient && gameState == GameState.Playing && !currentInfected.Contains(taggedPlayer))
			{
				AddLastTagged(taggedPlayer, taggingPlayer);
				currentInfected.Add(taggedPlayer);
			}
			GorillaTagCompetitiveManager.onTagOccurred?.Invoke(taggedPlayer, taggingPlayer);
		}
	}

	private void SetState(GameState newState)
	{
		if (newState != this.gameState)
		{
			GameState gameState = this.gameState;
			this.gameState = newState;
			switch (this.gameState)
			{
			case GameState.WaitingForPlayers:
				EnterStateWaitingForPlayers();
				break;
			case GameState.StartingCountdown:
				EnterStateStartingCountdown();
				break;
			case GameState.Playing:
				EnterStatePlaying();
				break;
			case GameState.PostRound:
				EnterStatePostRound();
				break;
			}
			GorillaTagCompetitiveManager.onStateChanged?.Invoke(this.gameState);
			GorillaTagCompetitiveManager.onUpdateRemainingTime?.Invoke(stateRemainingTime);
			if (this.gameState == GameState.Playing)
			{
				GorillaTagCompetitiveManager.onRoundStart?.Invoke();
			}
			else if (gameState == GameState.Playing)
			{
				GorillaTagCompetitiveManager.onRoundEnd?.Invoke();
			}
			GTDev.Log($"!! Competitive SetState: {this.gameState} at: {Time.time}");
		}
	}

	private void EnterStateWaitingForPlayers()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			SetisCurrentlyTag(newTagSetting: true);
			ClearInfectionState();
		}
	}

	private void EnterStateStartingCountdown()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			if (isCurrentlyTag)
			{
				SetisCurrentlyTag(newTagSetting: false);
			}
			currentIt = null;
			ClearInfectionState();
			GorillaGameModes.GameMode.RefreshPlayers();
			CheckForInfected();
			stateRemainingTime = startCountdownDuration;
		}
	}

	private void EnterStatePlaying()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			if (isCurrentlyTag)
			{
				SetisCurrentlyTag(newTagSetting: false);
			}
			currentIt = null;
			stateRemainingTime = roundDuration;
			PingRoom();
		}
		DisplayScoreboardPredictedResults(bShow: false);
	}

	private void EnterStatePostRound()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			if (isCurrentlyTag)
			{
				SetisCurrentlyTag(newTagSetting: false);
			}
			currentIt = null;
			stateRemainingTime = postRoundDuration;
		}
		DisplayScoreboardPredictedResults(bShow: true);
	}

	public override void UpdateState()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			switch (gameState)
			{
			case GameState.None:
				SetState(GameState.WaitingForPlayers);
				break;
			case GameState.WaitingForPlayers:
				UpdateStateWaitingForPlayers();
				break;
			case GameState.StartingCountdown:
				UpdateStateStartingCountdown();
				break;
			case GameState.Playing:
				UpdateStatePlaying();
				break;
			case GameState.PostRound:
				UpdateStatePostRound();
				break;
			}
		}
	}

	private void UpdateStateWaitingForPlayers()
	{
		if (IsInfectionPossible())
		{
			SetState(GameState.StartingCountdown);
		}
		else if (isCurrentlyTag && currentIt == null)
		{
			int index = UnityEngine.Random.Range(0, GorillaGameModes.GameMode.ParticipatingPlayers.Count);
			ChangeCurrentIt(GorillaGameModes.GameMode.ParticipatingPlayers[index], withTagFreeze: false);
		}
	}

	private void UpdateStateStartingCountdown()
	{
		if (!IsInfectionPossible())
		{
			SetState(GameState.WaitingForPlayers);
		}
		else if (stateRemainingTime < 0f)
		{
			SetState(GameState.Playing);
		}
		else
		{
			CheckForInfected();
		}
	}

	private void UpdateStatePlaying()
	{
		if (IsGameInvalid())
		{
			SetState(GameState.WaitingForPlayers);
		}
		else if (stateRemainingTime < 0f)
		{
			HandleInfectionRoundComplete();
		}
		else if (IsEveryoneTagged())
		{
			HandleInfectionRoundComplete();
		}
		else
		{
			CheckForInfected();
		}
	}

	private void HandleInfectionRoundComplete()
	{
		foreach (NetPlayer participatingPlayer in GorillaGameModes.GameMode.ParticipatingPlayers)
		{
			RoomSystem.SendSoundEffectToPlayer(2, 0.25f, participatingPlayer, stopCurrentAudio: true);
		}
		PlayerGameEvents.GameModeCompleteRound();
		GorillaGameModes.GameMode.BroadcastRoundComplete();
		lastTaggedActorNr.Clear();
		waitingToStartNextInfectionGame = true;
		timeInfectedGameEnded = Time.time;
		SetState(GameState.PostRound);
	}

	private void UpdateStatePostRound()
	{
		if (stateRemainingTime < 0f)
		{
			if (IsInfectionPossible())
			{
				SetState(GameState.StartingCountdown);
			}
			else
			{
				SetState(GameState.WaitingForPlayers);
			}
		}
	}

	private void PingRoom()
	{
		if (PhotonNetwork.CurrentRoom.CustomProperties.TryGetValue("matchId", out var value))
		{
			GorillaTagCompetitiveServerApi.Instance.RequestPingRoom((string)value, delegate
			{
				ShowDebugPing = true;
			});
		}
	}

	private bool IsGameInvalid()
	{
		return GorillaGameModes.GameMode.ParticipatingPlayers.Count <= 1;
	}

	private bool IsInfectionPossible()
	{
		return GorillaGameModes.GameMode.ParticipatingPlayers.Count >= infectedModeThreshold;
	}

	private bool IsEveryoneTagged()
	{
		bool result = true;
		foreach (NetPlayer participatingPlayer in GorillaGameModes.GameMode.ParticipatingPlayers)
		{
			if (!currentInfected.Contains(participatingPlayer))
			{
				result = false;
				break;
			}
		}
		return result;
	}

	private void CheckForInfected()
	{
		if (currentInfected.Count == 0)
		{
			int index = UnityEngine.Random.Range(0, GorillaGameModes.GameMode.ParticipatingPlayers.Count);
			AddInfectedPlayer(GorillaGameModes.GameMode.ParticipatingPlayers[index]);
		}
	}

	public override void OnSerializeWrite(PhotonStream stream, PhotonMessageInfo info)
	{
		base.OnSerializeWrite(stream, info);
		stream.SendNext(gameState);
		stream.SendNext(stateRemainingTime);
	}

	public override void OnSerializeRead(PhotonStream stream, PhotonMessageInfo info)
	{
		NetworkSystem.Instance.GetPlayer(info.Sender);
		base.OnSerializeRead(stream, info);
		GameState state = (GameState)stream.ReceiveNext();
		stateRemainingTime = (float)stream.ReceiveNext();
		SetState(state);
	}

	public void UpdateScoreboards()
	{
		List<RankedMultiplayerScore.PlayerScoreInRound> sortedScores = scoring.GetSortedScores();
		if (gameState == GameState.Playing)
		{
			lastActiveTime = Time.time;
		}
		for (int i = 0; i < scoreboards.Count; i++)
		{
			scoreboards[i].UpdateScores(gameState, lastActiveTime, sortedScores, scoring.PlayerRankedTiers, scoring.ProjectedEloDeltas, currentInfected, scoring.Progression);
		}
	}

	public void DisplayScoreboardPredictedResults(bool bShow)
	{
		for (int i = 0; i < scoreboards.Count; i++)
		{
			scoreboards[i].DisplayPredictedResults(bShow);
		}
	}

	public void RegisterForcedLeaveVolume(GorillaTagCompetitiveForcedLeaveRoomVolume volume)
	{
		if (!forceLeaveRoomVolumes.Contains(volume))
		{
			forceLeaveRoomVolumes.Add(volume);
		}
	}

	public void UnregisterForcedLeaveVolume(GorillaTagCompetitiveForcedLeaveRoomVolume volume)
	{
		forceLeaveRoomVolumes.Remove(volume);
	}
}
