public class GorillaTagCompetitiveRankCosmetic : MonoBehaviour, ISpawnable
{
	[Tooltip("If enabled, display PC rank. Otherwise, display Quest rank")]
	[SerializeField]
	private bool usePCELO;

	[SerializeField]
	private bool forWardrobe;

	[SerializeField]
	private VRRig myRig;

	[SerializeField]
	private GameObject[] rankCosmetics;

	public bool IsSpawned { get; set; }

	ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

	public void OnSpawn(VRRig rig)
	{
		if (forWardrobe && !myRig)
		{
			TryGetRig();
			return;
		}
		myRig = rig;
		myRig.OnRankedSubtierChanged += OnRankedScoreChanged;
		OnRankedScoreChanged(myRig.GetCurrentRankedSubTier(getPC: false), myRig.GetCurrentRankedSubTier(getPC: true));
	}

	public void OnDespawn()
	{
	}

	private void OnEnable()
	{
		if (forWardrobe)
		{
			UpdateDisplayedCosmetic(-1, -1);
			if (!TryGetRig())
			{
				StartCoroutine(DoFindRig());
			}
		}
	}

	private void OnDisable()
	{
		if (forWardrobe && (bool)myRig)
		{
			myRig.OnRankedSubtierChanged -= OnRankedScoreChanged;
			myRig = null;
		}
	}

	private IEnumerator DoFindRig()
	{
		WaitForSeconds intervalWait = new WaitForSeconds(0.1f);
		while (!TryGetRig())
		{
			yield return intervalWait;
		}
	}

	private bool TryGetRig()
	{
		myRig = GorillaTagger.Instance?.offlineVRRig;
		if ((bool)myRig)
		{
			myRig.OnRankedSubtierChanged += OnRankedScoreChanged;
			OnRankedScoreChanged(myRig.GetCurrentRankedSubTier(getPC: false), myRig.GetCurrentRankedSubTier(getPC: true));
			return true;
		}
		return false;
	}

	private void OnRankedScoreChanged(int questRank, int pcRank)
	{
		UpdateDisplayedCosmetic(questRank, pcRank);
	}

	private void UpdateDisplayedCosmetic(int questRank, int pcRank)
	{
		if (rankCosmetics != null)
		{
			int num = (usePCELO ? pcRank : questRank);
			if (num <= 0)
			{
				num = 0;
			}
			for (int i = 0; i < rankCosmetics.Length; i++)
			{
				rankCosmetics[i].SetActive(i == num);
			}
		}
	}
}
public class GorillaTagCompetitiveRankDisplay : MonoBehaviour
{
	[SerializeField]
	private SpriteRenderer progressBar;

	[SerializeField]
	private float progressBarSize = 100f;

	[SerializeField]
	private SpriteRenderer currentRankSprite;

	[SerializeField]
	private SpriteRenderer prevRankSprite;

	[SerializeField]
	private SpriteRenderer nextRankSprite;

	[SerializeField]
	private TextMeshPro currentRank_Name;

	[SerializeField]
	private TextMeshPro prevText;

	[SerializeField]
	private TextMeshPro nextText;

	[SerializeField]
	private TextMeshPro prevRank_Name;

	[SerializeField]
	private TextMeshPro nextRank_Name;

	private void OnEnable()
	{
		VRRig.LocalRig.OnRankedSubtierChanged += HandleRankedSubtierChanged;
		HandleRankedSubtierChanged(0, 0);
	}

	private void OnDisable()
	{
		VRRig.LocalRig.OnRankedSubtierChanged -= HandleRankedSubtierChanged;
	}

	public void HandleRankedSubtierChanged(int questSubTier, int pcSubTier)
	{
		float currentELO = RankedProgressionManager.Instance.GetCurrentELO();
		int progressionRankIndex = RankedProgressionManager.Instance.GetProgressionRankIndex(currentELO);
		UpdateRankIcons(progressionRankIndex);
		UpdateRankProgress(RankedProgressionManager.Instance.GetProgressionRankProgress());
	}

	private void UpdateRankIcons(int currentRank)
	{
		currentRankSprite.sprite = RankedProgressionManager.Instance.GetProgressionRankIcon(currentRank);
		currentRank_Name.text = RankedProgressionManager.Instance.GetProgressionRankName().ToUpper();
		bool flag = currentRank < RankedProgressionManager.Instance.MaxRank;
		bool flag2 = currentRank > 0;
		nextRankSprite.gameObject.SetActive(flag);
		nextText.gameObject.SetActive(flag);
		nextRank_Name.gameObject.SetActive(flag);
		if (flag)
		{
			nextRankSprite.sprite = RankedProgressionManager.Instance.GetNextProgressionRankIcon(currentRank);
			nextRank_Name.text = RankedProgressionManager.Instance.GetNextProgressionRankName(currentRank).ToUpper();
		}
		prevRankSprite.gameObject.SetActive(flag2);
		prevText.gameObject.SetActive(flag2);
		prevRank_Name.gameObject.SetActive(flag2);
		if (flag2)
		{
			prevRankSprite.sprite = RankedProgressionManager.Instance.GetPrevProgressionRankIcon(currentRank);
			prevRank_Name.text = RankedProgressionManager.Instance.GetPrevProgressionRankName(currentRank).ToUpper();
		}
	}

	private void UpdateRankProgress(float percent)
	{
		percent = Mathf.Clamp01(percent);
		UnityEngine.Vector2 size = progressBar.size;
		size.x = progressBarSize * percent;
		progressBar.size = size;
	}
}
public class GorillaTagCompetitiveRoundBuzzer : MonoBehaviour
{
	public AudioSource audioSource;

	public AudioClip roundCountdownClip;

	public AudioClip roundStartClip;

	public AudioClip roundEndingCountdownClip;

	public int roundEndCountdownDuration = 5;

	public AudioClip roundEndClip;

	public AudioClip needMorePlayerClip;

	private GorillaTagCompetitiveManager.GameState lastState;

	private float lastStateRemainingTime = -1f;

	private void OnEnable()
	{
		GorillaTagCompetitiveManager.onStateChanged += OnStateChanged;
		GorillaTagCompetitiveManager.onUpdateRemainingTime += OnUpdateRemainingTime;
	}

	private void OnDisable()
	{
		GorillaTagCompetitiveManager.onStateChanged -= OnStateChanged;
		GorillaTagCompetitiveManager.onUpdateRemainingTime -= OnUpdateRemainingTime;
	}

	private void OnStateChanged(GorillaTagCompetitiveManager.GameState newState)
	{
		switch (newState)
		{
		case GorillaTagCompetitiveManager.GameState.Playing:
			PlaySFX(roundStartClip);
			break;
		case GorillaTagCompetitiveManager.GameState.PostRound:
			PlaySFX(roundEndClip);
			break;
		case GorillaTagCompetitiveManager.GameState.WaitingForPlayers:
			PlaySFX(needMorePlayerClip);
			break;
		}
		lastState = newState;
	}

	private void OnUpdateRemainingTime(float remainingTime)
	{
		int num = Mathf.CeilToInt(remainingTime);
		int num2 = Mathf.CeilToInt(lastStateRemainingTime);
		if (num != num2)
		{
			switch (lastState)
			{
			case GorillaTagCompetitiveManager.GameState.StartingCountdown:
				if (num > 0)
				{
					PlaySFX(roundCountdownClip);
				}
				break;
			case GorillaTagCompetitiveManager.GameState.Playing:
				if (num > 0 && num <= roundEndCountdownDuration)
				{
					PlaySFX(roundEndingCountdownClip);
				}
				break;
			}
		}
		lastStateRemainingTime = remainingTime;
	}

	private void PlaySFX(AudioClip clip)
	{
		PlaySFX(clip, 1f);
	}

	private void PlaySFX(AudioClip clip, float volume)
	{
		audioSource.PlayOneShot(clip, volume);
	}
}
public class GorillaTagCompetitiveScoreboard : MonoBehaviour
{
	public enum PredictedResult
	{
		Great,
		Good,
		Even,
		Bad,
		Poor
	}

	public GorillaTagCompetitiveScoreboardLine[] lines;

	public GameObject waitingForPlayers;

	public float smallEloDelta = 10f;

	public float largeEloDelta = 25f;

	private void Awake()
	{
		GorillaTagCompetitiveManager.RegisterScoreboard(this);
		for (int i = 0; i < lines.Length; i++)
		{
			lines[i].gameObject.SetActive(value: false);
		}
	}

	private void OnDestroy()
	{
		GorillaTagCompetitiveManager.DeregisterScoreboard(this);
	}

	public void UpdateScores(GorillaTagCompetitiveManager.GameState gameState, float activeRoundTime, List<RankedMultiplayerScore.PlayerScoreInRound> scores, Dictionary<int, int> PlayerRankedTiers, Dictionary<int, float> PlayerPredictedEloDeltas, List<NetPlayer> infectedPlayers, RankedProgressionManager progressionManager)
	{
		waitingForPlayers.SetActive(gameState == GorillaTagCompetitiveManager.GameState.WaitingForPlayers);
		for (int i = 0; i < lines.Length; i++)
		{
			if (gameState != GorillaTagCompetitiveManager.GameState.WaitingForPlayers && scores != null && scores.Count > i)
			{
				RankedMultiplayerScore.PlayerScoreInRound playerScoreInRound = scores[i];
				NetPlayer netPlayerByID = NetworkSystem.Instance.GetNetPlayerByID(playerScoreInRound.PlayerId);
				if (netPlayerByID == null)
				{
					continue;
				}
				lines[i].gameObject.SetActive(value: true);
				if (PlayerRankedTiers == null || !PlayerRankedTiers.ContainsKey(playerScoreInRound.PlayerId))
				{
					lines[i].SetPlayer(netPlayerByID.SanitizedNickName, null);
				}
				else
				{
					lines[i].SetPlayer(netPlayerByID.SanitizedNickName, progressionManager.GetProgressionRankIcon(PlayerRankedTiers[playerScoreInRound.PlayerId]));
				}
				if (playerScoreInRound.TaggedTime.Approx(0f))
				{
					lines[i].SetScore(Mathf.Max(activeRoundTime - playerScoreInRound.JoinTime, 0f), playerScoreInRound.NumTags);
				}
				else
				{
					lines[i].SetScore(Mathf.Max(playerScoreInRound.TaggedTime - playerScoreInRound.JoinTime, 0f), playerScoreInRound.NumTags);
				}
				if (PlayerPredictedEloDeltas.ContainsKey(playerScoreInRound.PlayerId))
				{
					float num = PlayerPredictedEloDeltas[playerScoreInRound.PlayerId];
					PredictedResult predictedResult = PredictedResult.Even;
					if (num > largeEloDelta)
					{
						predictedResult = PredictedResult.Great;
					}
					else if (num > smallEloDelta)
					{
						predictedResult = PredictedResult.Good;
					}
					else if (num < 0f - largeEloDelta)
					{
						predictedResult = PredictedResult.Poor;
					}
					else if (num < 0f - smallEloDelta)
					{
						predictedResult = PredictedResult.Bad;
					}
					lines[i].SetPredictedResult(predictedResult);
				}
				lines[i].SetInfected(gameState == GorillaTagCompetitiveManager.GameState.Playing && infectedPlayers.Contains(netPlayerByID));
			}
			else
			{
				lines[i].gameObject.SetActive(value: false);
			}
		}
	}

	public void DisplayPredictedResults(bool bShow)
	{
		for (int i = 0; i < lines.Length; i++)
		{
			lines[i].DisplayPredictedResults(bShow);
		}
	}
}
