	private async void IsXRSubsystemActive()
	{
		loadedDeviceName = XRSettings.loadedDeviceName;
		while (!xrSubsystemIsActive)
		{
			List<XRDisplaySubsystem> list = new List<XRDisplaySubsystem>();
			SubsystemManager.GetSubsystems(list);
			foreach (XRDisplaySubsystem item in list)
			{
				if (item.running)
				{
					xrSubsystemIsActive = true;
					activeXRDisplay = item;
					return;
				}
			}
			await Awaitable.WaitForSecondsAsync(0.1f);
		}
	}

	public bool IsOculusQuest2()
	{
		if (UnityEngine.Application.platform == RuntimePlatform.Android)
		{
			return OVRPlugin.GetSystemHeadsetType() == OVRPlugin.SystemHeadset.Oculus_Quest_2;
		}
		return false;
	}

	protected void Start()
	{
		IsXRSubsystemActive();
		if (loadedDeviceName == "OpenVR Display")
		{
			UnityEngine.Quaternion rotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(-90f, 180f, -20f));
			UnityEngine.Quaternion rotation2 = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(-90f, 180f, 20f));
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(-141f, 204f, -27f));
			UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(-141f, 156f, 27f));
			GTPlayer.Instance.SetHandOffsets(isLeftHand: true, new UnityEngine.Vector3(-0.02f, 0f, -0.07f), quaternion2 * UnityEngine.Quaternion.Inverse(rotation));
			GTPlayer.Instance.SetHandOffsets(isLeftHand: false, new UnityEngine.Vector3(0.02f, 0f, -0.07f), quaternion3 * UnityEngine.Quaternion.Inverse(rotation2));
		}
		bodyVector = new UnityEngine.Vector3(0f, bodyCollider.height / 2f - bodyCollider.radius, 0f);
		if (SteamManager.Initialized)
		{
			gameOverlayActivatedCb = Callback<GameOverlayActivated_t>.Create(OnGameOverlayActivated);
		}
	}

	private void OnGameOverlayActivated(GameOverlayActivated_t pCallback)
	{
		isGameOverlayActive = pCallback.m_bActive != 0;
	}

