	private class BatchRunner : MonoBehaviour
	{
		private IEnumerator Start()
		{
			while (true)
			{
				float start = Time.realtimeSinceStartup;
				while (Time.realtimeSinceStartup < start + TELEMETRY_FLUSH_SEC)
				{
					yield return null;
				}
				FlushMothershipTelemetry();
			}
		}
	}

