		}
	}

	protected override void Awake()
	{
		base.Awake();
		spawnIndex = 0;
		targetPlayer = null;
		currentState = ChaseState.Dormant;
		grabTime = 0f - minGrabCooldown;
		possibleTarget = new List<NetPlayer>();
	}

	private new void Start()
	{
		NetworkSystem.Instance.RegisterSceneNetworkItem(base.gameObject);
		RoomSystem.JoinedRoomEvent += new Action(OnJoinedRoom);
	}

	private void InitializeGhost()
	{
		if (NetworkSystem.Instance.InRoom && base.IsMine)
		{
			lastHeadAngleTime = 0f;
			nextHeadAngleTime = lastHeadAngleTime + UnityEngine.Random.value * maxTimeToNextHeadAngle;
			nextTimeToChasePlayer = Time.time + UnityEngine.Random.Range(minGrabCooldown, maxNextTimeToChasePlayer);
			ghostBody.transform.localPosition = UnityEngine.Vector3.zero;
			base.transform.eulerAngles = UnityEngine.Vector3.zero;
			lastSpeedIncreased = 0f;
			currentSpeed = 0f;
		}
	}

	private void LateUpdate()
	{
		if (!NetworkSystem.Instance.InRoom)
		{
			currentState = ChaseState.Dormant;
			UpdateState();
			return;
		}
		if (base.IsMine)
		{
			switch (currentState)
			{
			case ChaseState.Dormant:
			{
				if (Time.time >= nextTimeToChasePlayer)
				{
					currentState = ChaseState.InitialRise;
				}
				if (!(Time.time >= lastSummonCheck + summoningDuration))
				{
					break;
				}
				lastSummonCheck = Time.time;
				possibleTarget.Clear();
				int num = 0;
				for (int i = 0; i < spawnTransforms.Length; i++)
				{
					int num2 = 0;
					for (int j = 0; j < VRRigCache.ActiveRigContainers.Count; j++)
					{
						if ((VRRigCache.ActiveRigContainers[j].transform.position - spawnTransforms[i].position).magnitude < summonDistance)
						{
							possibleTarget.Add(VRRigCache.ActiveRigContainers[j].Creator);
							num2++;
							if (num2 >= summonCount)
							{
								break;
							}
						}
					}
					if (num2 >= summonCount)
					{
						if (!wasSurroundedLastCheck)
						{
							wasSurroundedLastCheck = true;
							break;
						}
						wasSurroundedLastCheck = false;
						isSummoned = true;
						currentState = ChaseState.Gong;
						break;
					}
					num++;
				}
				if (num == spawnTransforms.Length)
				{
					wasSurroundedLastCheck = false;
				}
				break;
			}
			case ChaseState.Gong:
				if (Time.time > timeGongStarted + gongDuration)
				{
					currentState = ChaseState.InitialRise;
				}
				break;
			case ChaseState.InitialRise:
				if (Time.time > timeRiseStarted + totalTimeToRise)
				{
					currentState = ChaseState.Chasing;
				}
				break;
			case ChaseState.Chasing:
				if (followTarget == null || targetPlayer == null)
				{
					ChooseRandomTarget();
				}
				if (!(followTarget == null) && (followTarget.position - ghostBody.transform.position).magnitude < catchDistance)
				{
					currentState = ChaseState.Grabbing;
				}
				break;
			case ChaseState.Grabbing:
				if (Time.time > grabTime + grabDuration)
				{
					currentState = ChaseState.Dormant;
				}
				break;
			}
		}
		if (lastState != currentState)
		{
			OnChangeState(currentState);
			lastState = currentState;
		}
		UpdateState();
	}

	public void UpdateState()
	{
		switch (currentState)
		{
		case ChaseState.Dormant:
			isSummoned = false;
			if (ghostMaterial.color == summonedColor)
			{
				ghostMaterial.color = defaultColor;
			}
			break;
		case ChaseState.InitialRise:
			if (NetworkSystem.Instance.InRoom)
			{
				if (base.IsMine)
				{
					RiseHost();
				}
				MoveHead();
			}
			break;
		case ChaseState.Chasing:
			if (NetworkSystem.Instance.InRoom)
			{
				if (base.IsMine)
				{
					ChaseHost();
				}
				MoveBodyShared();
				MoveHead();
			}
			break;
		case ChaseState.Grabbing:
			if (NetworkSystem.Instance.InRoom)
			{
				if (targetPlayer == NetworkSystem.Instance.LocalPlayer)
				{
					RiseGrabbedLocalPlayer();
				}
				GrabBodyShared();
				MoveHead();
			}
			break;
		}
	}

	private void OnChangeState(ChaseState newState)
	{
		switch (newState)
		{
		case ChaseState.Dormant:
			if (ghostBody.activeSelf)
			{
				ghostBody.SetActive(value: false);
			}
			if (base.IsMine)
			{
				targetPlayer = null;
				InitializeGhost();
			}
			else
			{
				nextTimeToChasePlayer = Time.time + UnityEngine.Random.Range(minGrabCooldown, maxNextTimeToChasePlayer);
			}
			SetInitialRotations();
			break;
		case ChaseState.Gong:
			if (!ghostBody.activeSelf)
			{
				ghostBody.SetActive(value: true);
			}
			if (base.IsMine)
			{
				ChooseRandomTarget();
				SetInitialSpawnPoint();
				base.transform.position = spawnTransforms[spawnIndex].position;
			}
			timeGongStarted = Time.time;
			laugh.volume = 1f;
			laugh.GTPlayOneShot(gong);
			isSummoned = true;
			break;
		case ChaseState.InitialRise:
			timeRiseStarted = Time.time;
			if (!ghostBody.activeSelf)
			{
				ghostBody.SetActive(value: true);
			}
			if (base.IsMine)
			{
				if (!isSummoned)
				{
					currentSpeed = 0f;
					ChooseRandomTarget();
					SetInitialSpawnPoint();
				}
				else
				{
					currentSpeed = 3f;
				}
			}
			if (isSummoned)
			{
				laugh.volume = 0.25f;
				laugh.GTPlayOneShot(deepLaugh);
				ghostMaterial.color = summonedColor;
			}
			else
			{
				laugh.volume = 0.25f;
				laugh.GTPlay();
				ghostMaterial.color = defaultColor;
			}
			SetInitialRotations();
			break;
		case ChaseState.Grabbing:
		{
			if (!ghostBody.activeSelf)
			{
				ghostBody.SetActive(value: true);
			}
			grabTime = Time.time;
			if (isSummoned)
			{
				laugh.volume = 0.25f;
				laugh.GTPlayOneShot(deepLaugh);
			}
			else
			{
				laugh.volume = 0.25f;
				laugh.GTPlay();
			}
			leftArm.localEulerAngles = leftArmGrabbingLocal;
			rightArm.localEulerAngles = rightArmGrabbingLocal;
			leftHand.localEulerAngles = leftHandGrabbingLocal;
			rightHand.localEulerAngles = rightHandGrabbingLocal;
			ghostBody.transform.localPosition = ghostOffsetGrabbingLocal;
			ghostBody.transform.localEulerAngles = ghostGrabbingEulerRotation;
			VRRig vRRig = GorillaGameManager.StaticFindRigForPlayer(targetPlayer);
			if (vRRig != null)
			{
				followTarget = vRRig.transform;
			}
			break;
		}
		case ChaseState.Chasing:
			if (!ghostBody.activeSelf)
			{
				ghostBody.SetActive(value: true);
			}
			ResetPath();
			break;
		}
	}

	private void SetInitialSpawnPoint()
	{
		float num = 1000f;
		spawnIndex = 0;
		if (followTarget == null)
		{
			return;
		}
		for (int i = 0; i < spawnTransforms.Length; i++)
		{
			float magnitude = (followTarget.position - spawnTransformOffsets[i].position).magnitude;
			if (magnitude < num)
			{
				num = magnitude;
				spawnIndex = i;
			}
		}
	}

	private void ChooseRandomTarget()
	{
		int num = -1;
		if (possibleTarget.Count >= summonCount)
		{
			int randomTarget = UnityEngine.Random.Range(0, possibleTarget.Count);
			num = VRRigCache.ActiveRigContainers.FindIndex((RigContainer x) => x.Creator != null && x.Creator == possibleTarget[randomTarget]);
			currentSpeed = 3f;
		}
		if (num == -1)
		{
			num = UnityEngine.Random.Range(0, VRRigCache.ActiveRigContainers.Count);
		}
		possibleTarget.Clear();
		if (num < VRRigCache.ActiveRigContainers.Count)
		{
			VRRig rig = VRRigCache.ActiveRigContainers[num].Rig;
			targetPlayer = rig.creator;
			followTarget = rig.head.rigTarget;
			targetIsOnNavMesh = NavMesh.SamplePosition(followTarget.position, out var _, 5f, 1);
		}
		else
		{
			targetPlayer = null;
			followTarget = null;
		}
	}

	private void SetInitialRotations()
	{
		leftArm.localEulerAngles = UnityEngine.Vector3.zero;
		rightArm.localEulerAngles = UnityEngine.Vector3.zero;
		leftHand.localEulerAngles = leftHandStartingLocal;
		rightHand.localEulerAngles = rightHandStartingLocal;
		ghostBody.transform.localPosition = UnityEngine.Vector3.zero;
		ghostBody.transform.localEulerAngles = ghostStartingEulerRotation;
	}

	private void MoveHead()
	{
		if (Time.time > nextHeadAngleTime)
		{
			skullTransform.localEulerAngles = headEulerAngles[UnityEngine.Random.Range(0, headEulerAngles.Length)];
			lastHeadAngleTime = Time.time;
			nextHeadAngleTime = lastHeadAngleTime + Mathf.Max(UnityEngine.Random.value * maxTimeToNextHeadAngle, 0.05f);
		}
	}

	private void RiseHost()
	{
		if (Time.time < timeRiseStarted + totalTimeToRise)
		{
			if (spawnIndex == -1)
			{
				spawnIndex = 0;
			}
			base.transform.position = spawnTransforms[spawnIndex].position + UnityEngine.Vector3.up * (Time.time - timeRiseStarted) / totalTimeToRise * riseDistance;
			base.transform.rotation = spawnTransforms[spawnIndex].rotation;
		}
	}

	private void RiseGrabbedLocalPlayer()
	{
		if (Time.time > grabTime + minGrabCooldown)
		{
			grabTime = Time.time;
			GorillaTagger.Instance.ApplyStatusEffect(GorillaTagger.StatusEffect.Frozen, GorillaTagger.Instance.tagCooldown);
			GorillaTagger.Instance.StartVibration(forLeftController: true, hapticStrength, hapticDuration);
			GorillaTagger.Instance.StartVibration(forLeftController: false, hapticStrength, hapticDuration);
		}
		if (Time.time < grabTime + grabDuration)
		{
			GorillaTagger.Instance.rigidbody.linearVelocity = UnityEngine.Vector3.up * grabSpeed;
			EquipmentInteractor.instance.ForceStopClimbing();
		}
	}

	public void UpdateFollowPath(UnityEngine.Vector3 destination, float currentSpeed)
	{
		if (path == null)
		{
			GetNewPath(destination);
		}
		points[points.Count - 1] = destination;
		UnityEngine.Vector3 vector = points[currentTargetIdx];
		base.transform.position = UnityEngine.Vector3.MoveTowards(base.transform.position, vector, currentSpeed * Time.deltaTime);
		UnityEngine.Vector3 eulerAngles = UnityEngine.Quaternion.LookRotation(vector - base.transform.position).eulerAngles;
		if (Mathf.Abs(eulerAngles.x) > 45f)
		{
			eulerAngles.x = 0f;
		}
		base.transform.rotation = UnityEngine.Quaternion.Euler(eulerAngles);
		if (currentTargetIdx + 1 < points.Count && (base.transform.position - vector).sqrMagnitude < 0.1f)
		{
			if (nextPathTimestamp <= Time.time)
			{
				GetNewPath(destination);
			}
			else
			{
				currentTargetIdx++;
			}
		}
	}

	private void GetNewPath(UnityEngine.Vector3 destination)
	{
		path = new NavMeshPath();
		NavMesh.SamplePosition(base.transform.position, out var hit, 5f, 1);
		targetIsOnNavMesh = NavMesh.SamplePosition(destination, out var hit2, 5f, 1);
		NavMesh.CalculatePath(hit.position, hit2.position, -1, path);
		points = new List<UnityEngine.Vector3>();
		UnityEngine.Vector3[] corners = path.corners;
		foreach (UnityEngine.Vector3 vector in corners)
		{
			points.Add(vector + UnityEngine.Vector3.up * heightAboveNavmesh);
		}
		points.Add(destination);
		currentTargetIdx = 0;
		nextPathTimestamp = Time.time + 2f;
	}

	public void ResetPath()
	{
		path = null;
	}

	private void ChaseHost()
	{
		if (followTarget != null)
		{
			if (Time.time > lastSpeedIncreased + velocityIncreaseTime)
			{
				lastSpeedIncreased = Time.time;
				currentSpeed += velocityStep;
			}
			if (targetIsOnNavMesh)
			{
				UpdateFollowPath(followTarget.position, currentSpeed);
				return;
			}
			base.transform.position = UnityEngine.Vector3.MoveTowards(base.transform.position, followTarget.position, currentSpeed * Time.deltaTime);
			base.transform.rotation = UnityEngine.Quaternion.LookRotation(followTarget.position - base.transform.position, UnityEngine.Vector3.up);
		}
	}

	private void MoveBodyShared()
	{
		noisyOffset = new UnityEngine.Vector3(Mathf.PerlinNoise(Time.time, 0f) - 0.5f, Mathf.PerlinNoise(Time.time, 10f) - 0.5f, Mathf.PerlinNoise(Time.time, 20f) - 0.5f);
		childGhost.localPosition = noisyOffset;
		leftArm.localEulerAngles = noisyOffset * 20f;
		rightArm.localEulerAngles = noisyOffset * -20f;
	}

	private void GrabBodyShared()
	{
		if (followTarget != null)
		{
			base.transform.rotation = followTarget.rotation;
			base.transform.position = followTarget.position;
		}
	}

	public override void WriteDataFusion()
	{
		Data = new GhostData
		{
			TargetActorNumber = (targetPlayer?.ActorNumber ?? (-1)),
			CurrentState = (int)currentState,
			SpawnIndex = spawnIndex,
			CurrentSpeed = currentSpeed,
			IsSummoned = isSummoned
		};
	}

	public override void ReadDataFusion()
	{
		int targetActorNumber = Data.TargetActorNumber;
		targetPlayer = NetworkSystem.Instance.GetPlayer(targetActorNumber);
		currentState = (ChaseState)Data.CurrentState;
		spawnIndex = Data.SpawnIndex;
		float f = Data.CurrentSpeed;
		isSummoned = Data.IsSummoned;
		if (float.IsFinite(f))
		{
			currentSpeed = f;
		}
	}

	protected override void WriteDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (NetworkSystem.Instance.GetPlayer(info.Sender) == NetworkSystem.Instance.MasterClient)
		{
			if (targetPlayer == null)
			{
				stream.SendNext(-1);
			}
			else
			{
				stream.SendNext(targetPlayer.ActorNumber);
			}
			stream.SendNext(currentState);
			stream.SendNext(spawnIndex);
			stream.SendNext(currentSpeed);
			stream.SendNext(isSummoned);
		}
	}

	protected override void ReadDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (NetworkSystem.Instance.GetPlayer(info.Sender) == NetworkSystem.Instance.MasterClient)
		{
			int playerID = (int)stream.ReceiveNext();
			targetPlayer = NetworkSystem.Instance.GetPlayer(playerID);
			currentState = (ChaseState)stream.ReceiveNext();
			spawnIndex = (int)stream.ReceiveNext();
			float f = (float)stream.ReceiveNext();
			isSummoned = (bool)stream.ReceiveNext();
			if (float.IsFinite(f))
			{
				currentSpeed = f;
			}
		}
	}

	public override void OnOwnerChange(Player newOwner, Player previousOwner)
	{
		base.OnOwnerChange(newOwner, previousOwner);
		if (newOwner == PhotonNetwork.LocalPlayer)
		{
			OnChangeState(currentState);
		}
	}

	public void OnJoinedRoom()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			InitializeGhost();
		}
		else
		{
			nextTimeToChasePlayer = Time.time + UnityEngine.Random.Range(minGrabCooldown, maxNextTimeToChasePlayer);
		}
	}

	[WeaverGenerated]
	public override void CopyBackingFieldsToState(bool P_0)
	{
		base.CopyBackingFieldsToState(P_0);
		Data = _Data;
	}

	[WeaverGenerated]
	public override void CopyStateToBackingFields()
	{
		base.CopyStateToBackingFields();
		_Data = Data;
	}
}
[RequireComponent(typeof(Collider))]
public class HandHold : MonoBehaviour, IGorillaGrabable
{
	private enum HandSnapMethod
	{
		None,
		SnapToCenterPoint,
		SnapToNearestEdge,
		SnapToXAxisPoint,
		SnapToYAxisPoint,
		SnapToZAxisPoint
	}

	public delegate void HandHoldPositionEvent(HandHold hh, bool lh, UnityEngine.Vector3 pos);

	public delegate void HandHoldEvent(HandHold hh, bool lh);

	private Dictionary<Transform, Transform> attached = new Dictionary<Transform, Transform>();

	[SerializeField]
	private HandSnapMethod handSnapMethod;

	[SerializeField]
	private bool rotatePlayerWhenHeld;

	[SerializeField]
	private UnityEvent<UnityEngine.Vector3> OnGrab;

	[SerializeField]
	private UnityEvent<HandHold> OnGrabHandHold;

	[SerializeField]
	private UnityEvent<bool> OnGrabHanded;

	[SerializeField]
	private UnityEvent OnRelease;

	[SerializeField]
	private UnityEvent<HandHold> OnReleaseHandHold;

	private bool initialized;

	private Collider myCollider;

	private Tappable myTappable;

	[Tooltip("Turning this on disables \"pregrabbing\". Use pregrabbing to allow players to catch a handhold even if they have squeezed the trigger too soon. Useful if you're anticipating jumping players needed to grab while airborne")]
	[SerializeField]
	private bool forceMomentary = true;

	private List<GorillaGrabber> currentGrabbers = new List<GorillaGrabber>();

	public static event HandHoldPositionEvent HandPositionRequestOverride;

	public static event HandHoldEvent HandPositionReleaseOverride;

	public void OnDisable()
	{
		for (int i = 0; i < currentGrabbers.Count; i++)
		{
			if (currentGrabbers[i].IsNotNull())
			{
				currentGrabbers[i].Ungrab(this);
			}
		}
	}

	private void Initialize()
	{
		if (!initialized)
		{
			myTappable = GetComponent<Tappable>();
			myCollider = GetComponent<Collider>();
			initialized = true;
		}
	}

	public virtual bool CanBeGrabbed(GorillaGrabber grabber)
	{
		return true;
	}

	void IGorillaGrabable.OnGrabbed(GorillaGrabber g, out Transform grabbedTransform, out UnityEngine.Vector3 localGrabbedPosition)
	{
		Initialize();
		grabbedTransform = base.transform;
		UnityEngine.Vector3 position = g.transform.position;
		localGrabbedPosition = base.transform.InverseTransformPoint(position);
		g.Player.AddHandHold(base.transform, localGrabbedPosition, g, g.IsLeftHand, rotatePlayerWhenHeld, out var grabbedVelocity);
		currentGrabbers.AddIfNew(g);
		if (handSnapMethod != HandSnapMethod.None && HandHold.HandPositionRequestOverride != null)
		{
			HandHold.HandPositionRequestOverride(this, g.IsLeftHand, CalculateOffset(position));
		}
		OnGrab?.Invoke(grabbedVelocity);
		OnGrabHandHold?.Invoke(this);
		OnGrabHanded?.Invoke(g.IsLeftHand);
		if (myTappable != null)
		{
			myTappable.OnGrab();
		}
	}

	void IGorillaGrabable.OnGrabReleased(GorillaGrabber g)
	{
		Initialize();
		g.Player.RemoveHandHold(g, g.IsLeftHand);
		currentGrabbers.Remove(g);
		if (handSnapMethod != HandSnapMethod.None && HandHold.HandPositionReleaseOverride != null)
		{
			HandHold.HandPositionReleaseOverride(this, g.IsLeftHand);
		}
		OnRelease?.Invoke();
		OnReleaseHandHold?.Invoke(this);
		if (myTappable != null)
		{
			myTappable.OnRelease();
		}
	}

	private UnityEngine.Vector3 CalculateOffset(UnityEngine.Vector3 position)
	{
		switch (handSnapMethod)
		{
		case HandSnapMethod.SnapToNearestEdge:
			if (myCollider == null)
			{
				myCollider = GetComponent<Collider>();
				if (myCollider is MeshCollider && !(myCollider as MeshCollider).convex)
				{
					handSnapMethod = HandSnapMethod.None;
					return UnityEngine.Vector3.zero;
				}
			}
			return base.transform.position - myCollider.ClosestPoint(position);
		case HandSnapMethod.SnapToXAxisPoint:
			return base.transform.position - base.transform.TransformPoint(UnityEngine.Vector3.right * base.transform.InverseTransformPoint(position).x);
		case HandSnapMethod.SnapToYAxisPoint:
			return base.transform.position - base.transform.TransformPoint(UnityEngine.Vector3.up * base.transform.InverseTransformPoint(position).y);
		case HandSnapMethod.SnapToZAxisPoint:
			return base.transform.position - base.transform.TransformPoint(UnityEngine.Vector3.forward * base.transform.InverseTransformPoint(position).z);
		default:
			return UnityEngine.Vector3.zero;
		}
	}

	public bool MomentaryGrabOnly()
	{
		return forceMomentary;
	}

	public void CopyProperties(HandHoldSettings handHoldSettings)
	{
		handSnapMethod = (HandSnapMethod)handHoldSettings.handSnapMethod;
		rotatePlayerWhenHeld = handHoldSettings.rotatePlayerWhenHeld;
		forceMomentary = !handHoldSettings.allowPreGrab;
	}
}
public class HandTrackingFingerCurl : MonoBehaviour
{
	[SerializeField]
	private OVRSkeleton skeleton;

	public float ActivationStart = 5f;

	public float ActivationEnd = 95f;

	public float CurlMultiplier = 1.2f;

	private Transform[] boneXforms;

	public static HandTrackingFingerCurl leftCurl;

	public static HandTrackingFingerCurl rightCurl;

	[SerializeField]
	private bool isLeft;

	public float ThumbCurl { get; private set; }

	public float TriggerCurl { get; private set; }

	public float GripCurl { get; private set; }

	private void Awake()
	{
		if (isLeft)
		{
			leftCurl = this;
		}
		else
		{
			rightCurl = this;
		}
		if (skeleton == null)
		{
			skeleton = GetComponent<OVRSkeleton>();
		}
		boneXforms = new Transform[84];
	}

	private void LateUpdate()
	{
		if (skeleton == null || skeleton.Bones == null || skeleton.Bones.Count == 0 || !SubscriptionManager.IsLocalSubscribed() || !SubscriptionManager.GetSubscriptionSettingBool(SubscriptionManager.SubscriptionFeatures.HandTracking))
		{
			return;
		}
		if (boneXforms[0] == null)
		{
			foreach (OVRBone bone in skeleton.Bones)
			{
				boneXforms[(int)bone.Id] = bone.Transform;
			}
		}
		ThumbCurl = CalcFingerCurl(OVRSkeleton.BoneId.Hand_Thumb3, OVRSkeleton.BoneId.Hand_Thumb2, OVRSkeleton.BoneId.Hand_Thumb1, OVRSkeleton.BoneId.Hand_Thumb0);
		TriggerCurl = CalcFingerCurl(OVRSkeleton.BoneId.Hand_Middle1, OVRSkeleton.BoneId.Hand_Index3, OVRSkeleton.BoneId.Hand_Index2, OVRSkeleton.BoneId.Hand_Index1);
		GripCurl = CalcFingerCurl(OVRSkeleton.BoneId.Hand_Ring3, OVRSkeleton.BoneId.Hand_Ring2, OVRSkeleton.BoneId.Hand_Ring1, OVRSkeleton.BoneId.Hand_Middle3);
	}

	private float CalcFingerCurl(OVRSkeleton.BoneId distal, OVRSkeleton.BoneId intermediate, OVRSkeleton.BoneId proximal, OVRSkeleton.BoneId metacarpal)
	{
		Transform transform = boneXforms[(int)distal];
		Transform transform2 = boneXforms[(int)intermediate];
		Transform transform3 = boneXforms[(int)proximal];
		Transform transform4 = boneXforms[(int)metacarpal];
		if (transform == null || transform2 == null || transform3 == null || transform4 == null)
		{
			return 0f;
		}
		UnityEngine.Vector3 vector = transform.position - transform2.position;
		UnityEngine.Vector3 vector2 = transform2.position - transform3.position;
		UnityEngine.Vector3 to = transform3.position - transform4.position;
		float num = UnityEngine.Vector3.Angle(vector, vector2);
		float num2 = UnityEngine.Vector3.Angle(vector2, to);
		float num3 = (num + num2) * 0.5f;
		num3 *= CurlMultiplier;
		num3 = Mathf.InverseLerp(ActivationStart, ActivationEnd, num3);
		return Mathf.Clamp01(num3);
	}
}
public class HauntedObject : MonoBehaviour
{
	private static readonly int _animHaunted = Animator.StringToHash("Haunted");

	private const string _lurkerGhost = "LurkerGhost";

	private const string _wanderingGhost = "WanderingGhost";

	[Tooltip("If this box is checked, then object will rattle when hunted")]
	public bool rattle;

	public float speed = 60f;

	public float amount = 0.01f;

	public float duration = 1f;

	[FormerlySerializedAs("FBX")]
	public GameObject FBXprefab;

	[Tooltip("Use to turn off a game object like candle flames when hunted")]
	public GameObject TurnOffLight;

	public float TurnOffDuration = 2f;

	private UnityEngine.Vector3 initialPos;

	private float passedTime;

	private float lightPassedTime;

	private GameObject lurkerGhost;

	private GameObject wanderingGhost;

	private Animator[] animators;

	[SerializeField]
	private AudioSource audioSource;

	[FormerlySerializedAs("rattlingSound")]
	public AudioClip hauntedSound;

	private void Awake()
	{
		lurkerGhost = GameObject.FindGameObjectWithTag("LurkerGhost");
		if (lurkerGhost != null && lurkerGhost.TryGetComponent<LurkerGhost>(out var component))
		{
			LurkerGhost obj = component;
			obj.TriggerHauntedObjects = (UnityAction<GameObject>)Delegate.Combine(obj.TriggerHauntedObjects, new UnityAction<GameObject>(TriggerEffects));
		}
		wanderingGhost = GameObject.FindGameObjectWithTag("WanderingGhost");
		if (wanderingGhost != null && wanderingGhost.TryGetComponent<WanderingGhost>(out var component2))
		{
			WanderingGhost obj2 = component2;
			obj2.TriggerHauntedObjects = (UnityAction<GameObject>)Delegate.Combine(obj2.TriggerHauntedObjects, new UnityAction<GameObject>(TriggerEffects));
		}
		animators = base.transform.GetComponentsInChildren<Animator>();
	}

	private void OnDestroy()
	{
		if (lurkerGhost != null && lurkerGhost.TryGetComponent<LurkerGhost>(out var component))
		{
			LurkerGhost obj = component;
			obj.TriggerHauntedObjects = (UnityAction<GameObject>)Delegate.Remove(obj.TriggerHauntedObjects, new UnityAction<GameObject>(TriggerEffects));
		}
		if (wanderingGhost != null && wanderingGhost.TryGetComponent<WanderingGhost>(out var component2))
		{
			WanderingGhost obj2 = component2;
			obj2.TriggerHauntedObjects = (UnityAction<GameObject>)Delegate.Remove(obj2.TriggerHauntedObjects, new UnityAction<GameObject>(TriggerEffects));
		}
	}

	private void Start()
	{
		initialPos = base.transform.position;
		passedTime = 0f;
		lightPassedTime = 0f;
	}

	private void TriggerEffects(GameObject go)
	{
		if (base.gameObject != go)
		{
			return;
		}
		if (rattle)
		{
			StartCoroutine(Shake());
		}
		if ((bool)audioSource && (bool)hauntedSound)
		{
			audioSource.GTPlayOneShot(hauntedSound);
		}
		if ((bool)FBXprefab)
		{
			ObjectPools.instance.Instantiate(FBXprefab, base.transform.position);
		}
		if (TurnOffLight != null)
		{
			StartCoroutine(TurnOff());
		}
		Animator[] array = animators;
		foreach (Animator animator in array)
		{
			if ((bool)animator)
			{
				animator.SetTrigger(_animHaunted);
			}
		}
	}

	private IEnumerator Shake()
	{
		while (passedTime < duration)
		{
			passedTime += Time.deltaTime;
			base.transform.position = new UnityEngine.Vector3(initialPos.x + Mathf.Sin(Time.time * speed) * amount, initialPos.y + Mathf.Sin(Time.time * speed) * amount, initialPos.z);
			yield return null;
		}
		passedTime = 0f;
	}

	private IEnumerator TurnOff()
	{
		TurnOffLight.gameObject.SetActive(value: false);
		while (lightPassedTime < TurnOffDuration)
		{
			lightPassedTime += Time.deltaTime;
			yield return null;
		}
		TurnOffLight.SetActive(value: true);
		lightPassedTime = 0f;
	}
}
public class HeightVolume : MonoBehaviour
{
	public Transform heightTop;

	public Transform heightBottom;

	public AudioSource audioSource;

	public float baseVolume;

	public float minVolume;

	public Transform targetTransform;

	public bool invertHeightVol;

	private MusicSource musicSource;

	private void Awake()
	{
		if (targetTransform == null)
		{
			targetTransform = Camera.main.transform;
		}
		musicSource = audioSource.gameObject.GetComponent<MusicSource>();
	}

	private void Update()
	{
		if (audioSource.gameObject.activeSelf && (!(musicSource != null) || !musicSource.VolumeOverridden))
		{
			if (targetTransform.position.y > heightTop.position.y)
			{
				audioSource.volume = ((!invertHeightVol) ? baseVolume : minVolume);
			}
			else if (targetTransform.position.y < heightBottom.position.y)
			{
				audioSource.volume = ((!invertHeightVol) ? minVolume : baseVolume);
			}
			else
			{
				audioSource.volume = ((!invertHeightVol) ? ((targetTransform.position.y - heightBottom.position.y) / (heightTop.position.y - heightBottom.position.y) * (baseVolume - minVolume) + minVolume) : ((heightTop.position.y - targetTransform.position.y) / (heightTop.position.y - heightBottom.position.y) * (baseVolume - minVolume) + minVolume));
			}
		}
	}
}
public class HeldButton : MonoBehaviour
{
	public Material pressedMaterial;

	public Material unpressedMaterial;

	public MeshRenderer buttonRenderer;

	private bool isOn;

	public float debounceTime = 0.25f;

	public bool leftHandPressable;

	public bool rightHandPressable = true;

	public float pressDuration = 0.5f;

	public UnityEvent onStartPressingButton;

	public UnityEvent onStopPressingButton;

	public UnityEvent onPressButton;

	[TextArea]
	public string offText;

	[TextArea]
	public string onText;

	public Text myText;

	private float touchTime;

	private float releaseTime;

	private bool pendingPress;

	private Collider pendingPressCollider;

	private GorillaTriggerColliderHandIndicator pressingHand;

	private void OnTriggerEnter(Collider other)
	{
		if (base.enabled)
		{
			GorillaTriggerColliderHandIndicator componentInParent = other.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
			if (!(componentInParent == null) && (!componentInParent.isLeftHand || leftHandPressable) && (componentInParent.isLeftHand || rightHandPressable) && (!pendingPress || other != pendingPressCollider))
			{
				onStartPressingButton?.Invoke();
				touchTime = Time.time;
				pendingPressCollider = other;
				pressingHand = componentInParent;
				pendingPress = true;
				SetOn(inOn: true);
				GorillaTagger.Instance.StartVibration(componentInParent.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			}
		}
	}

	private void LateUpdate()
	{
		if (!pendingPress)
		{
			return;
		}
		if (touchTime < releaseTime && releaseTime + debounceTime < Time.time)
		{
			onStopPressingButton?.Invoke();
			pendingPress = false;
			pendingPressCollider = null;
			pressingHand = null;
			SetOn(inOn: false);
		}
		else if (touchTime + pressDuration < Time.time)
		{
			onPressButton.Invoke();
			if (pressingHand != null)
			{
				GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(67, pressingHand.isLeftHand, 0.1f);
				GorillaTagger.Instance.StartVibration(pressingHand.isLeftHand, GorillaTagger.Instance.tapHapticStrength, GorillaTagger.Instance.tapHapticDuration);
			}
			onStopPressingButton?.Invoke();
			pendingPress = false;
			pendingPressCollider = null;
			pressingHand = null;
			releaseTime = Time.time;
			SetOn(inOn: false);
		}
		else if (touchTime > releaseTime && pressingHand != null)
		{
			GorillaTagger.Instance.StartVibration(pressingHand.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 4f, Time.fixedDeltaTime);
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (pendingPress && pendingPressCollider == other)
		{
			releaseTime = Time.time;
			onStopPressingButton?.Invoke();
		}
	}

	public void SetOn(bool inOn)
	{
		if (inOn == isOn)
		{
			return;
		}
		isOn = inOn;
		if (isOn)
		{
			buttonRenderer.material = pressedMaterial;
			if (myText != null)
			{
				myText.text = onText;
			}
		}
		else
		{
			buttonRenderer.material = unpressedMaterial;
			if (myText != null)
			{
				myText.text = offText;
			}
		}
	}
}
public class HoldableHand : HoldableObject, IGorillaSliceableSimple
{
	[SerializeField]
	private VRRig myPlayer;

	[SerializeField]
	private bool isBody;

	[SerializeField]
	private bool isLeftHand;

	public InteractionPoint interactionPoint;

	public VRRig Rig => myPlayer;

	private void Start()
	{
		if (myPlayer.isOfflineVRRig)
		{
			base.gameObject.SetActive(value: false);
		}
		if (interactionPoint == null)
		{
			interactionPoint = GetComponent<InteractionPoint>();
		}
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void SliceUpdate()
	{
		interactionPoint.enabled = GorillaGameModes.GameMode.ActiveGameMode is GorillaGuardianManager;
	}

	public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
	{
		if (GorillaGameModes.GameMode.ActiveGameMode is GorillaGuardianManager gorillaGuardianManager && !myPlayer.creator.IsLocal && gorillaGuardianManager.IsPlayerGuardian(NetworkSystem.Instance.LocalPlayer))
		{
			bool flag = grabbingHand == EquipmentInteractor.instance.leftHand;
			myPlayer.netView.SendRPC("GrabbedByPlayer", myPlayer.Creator, isBody, isLeftHand, flag);
			myPlayer.ApplyLocalGrabOverride(isBody, isLeftHand, grabbingHand.transform);
			EquipmentInteractor.instance.UpdateHandEquipment(this, flag);
			ClearOtherGrabs(flag);
		}
	}

	public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
	{
		if (!base.OnRelease(zoneReleased, releasingHand))
		{
			return false;
		}
		if (GorillaGameModes.GameMode.ActiveGameMode is GorillaGuardianManager gorillaGuardianManager && !myPlayer.creator.IsLocal)
		{
			bool forLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
			UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
			if (gorillaGuardianManager.IsPlayerGuardian(NetworkSystem.Instance.LocalPlayer))
			{
				vector = GTPlayer.Instance.GetHandVelocityTracker(forLeftHand).GetAverageVelocity(worldSpace: true);
			}
			vector = UnityEngine.Vector3.ClampMagnitude(vector, 20f);
			myPlayer.netView.SendRPC("DroppedByPlayer", myPlayer.Creator, vector);
			myPlayer.ClearLocalGrabOverride();
			myPlayer.ApplyLocalTrajectoryOverride(vector);
			EquipmentInteractor.instance.UpdateHandEquipment(null, forLeftHand);
		}
		return true;
	}

	public override void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
	{
	}

	public override void DropItemCleanup()
	{
		myPlayer.ClearLocalGrabOverride();
	}

	private void ClearOtherGrabs(bool grabbedLeft)
	{
		IHoldableObject holdableObject = (grabbedLeft ? EquipmentInteractor.instance.rightHandHeldEquipment : EquipmentInteractor.instance.leftHandHeldEquipment);
		if (isBody)
		{
			if (holdableObject == myPlayer.leftHolds || holdableObject == myPlayer.rightHolds)
			{
				EquipmentInteractor.instance.UpdateHandEquipment(null, !grabbedLeft);
			}
		}
		else if (isLeftHand)
		{
			if (holdableObject == myPlayer.rightHolds || holdableObject == myPlayer.bodyHolds)
			{
				EquipmentInteractor.instance.UpdateHandEquipment(null, !grabbedLeft);
			}
		}
		else if (holdableObject == myPlayer.leftHolds || holdableObject == myPlayer.bodyHolds)
		{
			EquipmentInteractor.instance.UpdateHandEquipment(null, !grabbedLeft);
		}
	}
}
