public class GorillaGrabber : MonoBehaviour
{
	private GTPlayer player;

	[SerializeField]
	private XRNode xrNode = XRNode.LeftHand;

	private AudioSource audioSource;

	private Transform currentGrabbedTransform;

	private UnityEngine.Vector3 localGrabbedPosition;

	private IGorillaGrabable currentGrabbable;

	[SerializeField]
	private float grabRadius = 0.015f;

	[SerializeField]
	private float breakDistance = 0.3f;

	[SerializeField]
	private float hapticStrength = 0.2f;

	private float hapticStrengthActual = 0.2f;

	[SerializeField]
	private float hapticDecay;

	[SerializeField]
	private ParticleSystem gripEffects;

	private Collider[] grabCastResults = new Collider[32];

	private float grabTimeStamp;

	[SerializeField]
	private float coyoteTimeDuration = 0.25f;

	public bool isGrabbing => currentGrabbable != null;

	public XRNode XrNode => xrNode;

	public bool IsLeftHand => XrNode == XRNode.LeftHand;

	public bool IsRightHand => XrNode == XRNode.RightHand;

	public GTPlayer Player => player;

	private void Start()
	{
		hapticStrengthActual = hapticStrength;
		audioSource = GetComponent<AudioSource>();
		player = GetComponentInParent<GTPlayer>();
		if (!player)
		{
			UnityEngine.Debug.LogWarning("Gorilla Grabber Component has no player in hierarchy. Disabling this Gorilla Grabber");
			GetComponent<GorillaGrabber>().enabled = false;
		}
	}

	public void CheckGrabber(bool initiateGrab)
	{
		bool grabMomentary = ControllerInputPoller.GetGrabMomentary(xrNode);
		bool grabRelease = ControllerInputPoller.GetGrabRelease(xrNode);
		if (currentGrabbable != null && (grabRelease || GrabDistanceOverCheck()))
		{
			Ungrab();
		}
		if (grabMomentary)
		{
			grabTimeStamp = Time.time;
		}
		if (initiateGrab && currentGrabbable == null)
		{
			currentGrabbable = TryGrab(Time.time - grabTimeStamp < coyoteTimeDuration);
		}
		if (currentGrabbable != null && hapticStrengthActual > 0f)
		{
			GorillaTagger.Instance.DoVibration(xrNode, hapticStrengthActual, Time.deltaTime);
			hapticStrengthActual -= hapticDecay * Time.deltaTime;
		}
	}

	private bool GrabDistanceOverCheck()
	{
		if (!(currentGrabbedTransform == null))
		{
			return UnityEngine.Vector3.Distance(base.transform.position, currentGrabbedTransform.TransformPoint(localGrabbedPosition)) > breakDistance;
		}
		return true;
	}

	internal void Ungrab(IGorillaGrabable specificGrabbable = null)
	{
		if (specificGrabbable == null || specificGrabbable == currentGrabbable)
		{
			currentGrabbable.OnGrabReleased(this);
			PlayerGameEvents.DroppedObject(currentGrabbable.name);
			currentGrabbable = null;
			gripEffects.Stop();
			hapticStrengthActual = hapticStrength;
		}
	}

	private IGorillaGrabable TryGrab(bool momentary)
	{
		IGorillaGrabable gorillaGrabable = null;
		UnityEngine.Debug.DrawRay(base.transform.position, base.transform.forward * (grabRadius * player.scale), Color.blue, 1f);
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, grabRadius * player.scale, grabCastResults);
		float num2 = float.MaxValue;
		for (int i = 0; i < num; i++)
		{
			if (grabCastResults[i].TryGetComponent<IGorillaGrabable>(out var component))
			{
				float num3 = UnityEngine.Vector3.Distance(base.transform.position, FindClosestPoint(grabCastResults[i], base.transform.position));
				if (num3 < num2)
				{
					num2 = num3;
					gorillaGrabable = component;
				}
			}
		}
		if (gorillaGrabable != null && (!gorillaGrabable.MomentaryGrabOnly() || momentary) && gorillaGrabable.CanBeGrabbed(this))
		{
			gorillaGrabable.OnGrabbed(this, out currentGrabbedTransform, out localGrabbedPosition);
			PlayerGameEvents.GrabbedObject(gorillaGrabable.name);
		}
		if (gorillaGrabable != null && !gorillaGrabable.CanBeGrabbed(this))
		{
			gorillaGrabable = null;
		}
		return gorillaGrabable;
	}

	private UnityEngine.Vector3 FindClosestPoint(Collider collider, UnityEngine.Vector3 position)
	{
		if (collider is MeshCollider && !(collider as MeshCollider).convex)
		{
			return position;
		}
		return collider.ClosestPoint(position);
	}

	public void Inject(Transform currentGrabbableTransform, UnityEngine.Vector3 localGrabbedPosition)
	{
		if (currentGrabbable != null)
		{
			Ungrab();
		}
		if (currentGrabbableTransform != null)
		{
			currentGrabbable = currentGrabbableTransform.GetComponent<IGorillaGrabable>();
			currentGrabbedTransform = currentGrabbableTransform;
			this.localGrabbedPosition = localGrabbedPosition;
			currentGrabbable.OnGrabbed(this, out currentGrabbedTransform, out localGrabbedPosition);
		}
	}
}
[DisallowMultipleComponent]
public abstract class GTSystem<T> : MonoBehaviour, IReadOnlyList<T>, IEnumerable<T>, IEnumerable, IReadOnlyCollection<T> where T : MonoBehaviour
{
	[SerializeField]
	protected List<T> _instances = new List<T>();

	[SerializeField]
	private bool _networked;

	[SerializeField]
	private PhotonView _photonView;

	private static GTSystem<T> gSingleton;

	private static bool gInitializing = false;

	private static bool gAppQuitting = false;

	private static HashSet<T> gQueueRegister = new HashSet<T>();

	public PhotonView photonView => _photonView;

	int IReadOnlyCollection<T>.Count => _instances.Count;

	T IReadOnlyList<T>.this[int index] => _instances[index];

	public static PhotonView PhotonView => gSingleton._photonView;

	protected virtual void Awake()
	{
		SetSingleton(this);
	}

	protected virtual void Tick()
	{
		float deltaTime = Time.deltaTime;
		for (int i = 0; i < _instances.Count; i++)
		{
			T val = _instances[i];
			if ((bool)val)
			{
				OnTick(deltaTime, val);
			}
		}
	}

	protected virtual void OnApplicationQuit()
	{
		gAppQuitting = true;
	}

	protected virtual void OnTick(float dt, T instance)
	{
	}

	private bool RegisterInstance(T instance)
	{
		if (instance == null)
		{
			GTDev.LogError("[" + GetType().Name + "::Register] Instance is null.");
			return false;
		}
		if (_instances.Contains(instance))
		{
			return false;
		}
		_instances.Add(instance);
		OnRegister(instance);
		return true;
	}

	protected virtual void OnRegister(T instance)
	{
	}

	private bool UnregisterInstance(T instance)
	{
		if (instance == null)
		{
			GTDev.LogError("[" + GetType().Name + "::Unregister] Instance is null.");
			return false;
		}
		if (!_instances.Contains(instance))
		{
			return false;
		}
		_instances.Remove(instance);
		OnUnregister(instance);
		return true;
	}

	protected virtual void OnUnregister(T instance)
	{
	}

	IEnumerator<T> IEnumerable<T>.GetEnumerator()
	{
		return ((IEnumerable<T>)_instances).GetEnumerator();
	}

	IEnumerator IEnumerable.GetEnumerator()
	{
		return ((IEnumerable<T>)_instances).GetEnumerator();
	}

	protected static void SetSingleton(GTSystem<T> system)
	{
		if (gAppQuitting)
		{
			return;
		}
		if (gSingleton != null && gSingleton != system)
		{
			UnityEngine.Object.Destroy(system);
			GTDev.LogWarning("Singleton of type " + gSingleton.GetType().Name + " already exists.");
			return;
		}
		gSingleton = system;
		if (gInitializing)
		{
			gSingleton._instances.Clear();
			T[] collection = gQueueRegister.Where((T x) => x != null).ToArray();
			gSingleton._instances.AddRange(collection);
			gQueueRegister.Clear();
			PhotonView component = gSingleton.GetComponent<PhotonView>();
			if (component != null)
			{
				gSingleton._photonView = component;
				gSingleton._networked = true;
			}
			gInitializing = false;
		}
	}

	public static void Register(T instance)
	{
		if (!gAppQuitting && !(instance == null))
		{
			if (gInitializing)
			{
				gQueueRegister.Add(instance);
			}
			else if (gSingleton == null && !gInitializing)
			{
				gInitializing = true;
				gQueueRegister.Add(instance);
			}
			else
			{
				gSingleton.RegisterInstance(instance);
			}
		}
	}

	public static void Unregister(T instance)
	{
		if (!gAppQuitting && !(instance == null))
		{
			if (gInitializing)
			{
				gQueueRegister.Remove(instance);
			}
			else if (gSingleton == null && !gInitializing)
			{
				gInitializing = true;
				gQueueRegister.Remove(instance);
			}
			else
			{
				gSingleton.UnregisterInstance(instance);
			}
		}
	}
}
public class MovingPlatform : BasePlatform
{
	public enum PlatformType
	{
		PointToPoint,
		Arc,
		Rotation,
		Child,
		ContinuousRotation
	}

	public PlatformType platformType;

	public float cycleLength;

	public float smoothingHalflife = 0.1f;

	public float rotateStartAmt;

	public float rotateAmt;

	public bool reverseDirOnCycle = true;

	public bool reverseDir;

	private CriticalSpringDamper springCD = new CriticalSpringDamper();

	private Rigidbody rb;

	public Transform startXf;

	public Transform endXf;

	public UnityEngine.Vector3 platformInitLocalPos;

	private UnityEngine.Vector3 startPos;

	private UnityEngine.Vector3 endPos;

	private UnityEngine.Quaternion startRot;

	private UnityEngine.Quaternion endRot;

	public float startPercentage;

	public float startDelay;

	public bool startNextCycle;

	public Transform pivot;

	private UnityEngine.Quaternion initLocalRotation;

	private UnityEngine.Vector3 initOffset;

	private float currT;

	private float percent;

	private float smoothedPercent = -1f;

	private bool currForward;

	private float dtSinceServerUpdate;

	private double lastServerTime;

	public UnityEngine.Vector3 currentVelocity;

	public UnityEngine.Vector3 rotationalAxis;

	public float angularVelocity;

	public UnityEngine.Vector3 rotationPivot;

	public UnityEngine.Vector3 lastPos;

	public UnityEngine.Quaternion lastRot;

	public UnityEngine.Vector3 deltaPosition;

	public bool debugMovement;

	private double lastNT;

	private float lastT;

	public float InitTimeOffset()
	{
		return startPercentage * cycleLength;
	}

	private long InitTimeOffsetMs()
	{
		return (long)(InitTimeOffset() * 1000f);
	}

	private long NetworkTimeMs()
	{
		if (PhotonNetwork.InRoom)
		{
			return (uint)(PhotonNetwork.ServerTimestamp + int.MinValue) + InitTimeOffsetMs();
		}
		return (long)(Time.time * 1000f);
	}

	private long CycleLengthMs()
	{
		return (long)(cycleLength * 1000f);
	}

	public double PlatformTime()
	{
		long num = NetworkTimeMs();
		long num2 = CycleLengthMs();
		return (double)(num - num / num2 * num2) / 1000.0;
	}

	public int CycleCount()
	{
		return (int)(NetworkTimeMs() / CycleLengthMs());
	}

	public float CycleCompletionPercent()
	{
		float value = (float)(PlatformTime() / (double)cycleLength);
		value = Mathf.Clamp(value, 0f, 1f);
		if (startDelay > 0f)
		{
			float num = startDelay / cycleLength;
			value = ((!(value <= num)) ? ((value - num) / (1f - num)) : 0f);
		}
		return value;
	}

	public bool CycleForward()
	{
		return (CycleCount() + (startNextCycle ? 1 : 0)) % 2 == 0;
	}

	private void Awake()
	{
		if (platformType != PlatformType.Child)
		{
			rb = GetComponent<Rigidbody>();
			initLocalRotation = base.transform.localRotation;
			if (pivot != null)
			{
				initOffset = pivot.transform.position - startXf.transform.position;
			}
			startPos = startXf.position;
			endPos = endXf.position;
			startRot = startXf.rotation;
			endRot = endXf.rotation;
			platformInitLocalPos = base.transform.localPosition;
			currT = startPercentage;
		}
	}

	private void OnEnable()
	{
		if (platformType != PlatformType.Child)
		{
			base.transform.localRotation = initLocalRotation;
			startPos = startXf.position;
			endPos = endXf.position;
			startRot = startXf.rotation;
			endRot = endXf.rotation;
			platformInitLocalPos = base.transform.localPosition;
			currT = startPercentage;
		}
	}

	private UnityEngine.Vector3 UpdatePointToPoint()
	{
		return UnityEngine.Vector3.Lerp(startPos, endPos, smoothedPercent);
	}

	private UnityEngine.Vector3 UpdateArc()
	{
		float angle = Mathf.Lerp(rotateStartAmt, rotateStartAmt + rotateAmt, smoothedPercent);
		_ = initLocalRotation;
		UnityEngine.Vector3 vector = UnityEngine.Quaternion.AngleAxis(angle, UnityEngine.Vector3.forward) * initOffset;
		return pivot.transform.position + vector;
	}

	private UnityEngine.Quaternion UpdateRotation()
	{
		return UnityEngine.Quaternion.Slerp(startRot, endRot, smoothedPercent);
	}

	private UnityEngine.Quaternion UpdateContinuousRotation()
	{
		return UnityEngine.Quaternion.AngleAxis(smoothedPercent * 360f, UnityEngine.Vector3.up) * base.transform.parent.rotation;
	}

	private void SetupContext()
	{
		double time = PhotonNetwork.Time;
		if (lastServerTime == time)
		{
			dtSinceServerUpdate += Time.fixedDeltaTime;
		}
		else
		{
			dtSinceServerUpdate = 0f;
			lastServerTime = time;
		}
		_ = currT;
		currT = CycleCompletionPercent();
		currForward = CycleForward();
		percent = currT;
		if (reverseDirOnCycle)
		{
			percent = (currForward ? currT : (1f - currT));
		}
		if (reverseDir)
		{
			percent = 1f - percent;
		}
		smoothedPercent = percent;
		lastNT = time;
		lastT = Time.time;
	}

	private void Update()
	{
		if (platformType == PlatformType.Child)
		{
			return;
		}
		SetupContext();
		UnityEngine.Vector3 vector = base.transform.position;
		UnityEngine.Quaternion quaternion2 = base.transform.rotation;
		bool flag = false;
		switch (platformType)
		{
		case PlatformType.PointToPoint:
			vector = UpdatePointToPoint();
			break;
		case PlatformType.Arc:
			vector = UpdateArc();
			flag = true;
			break;
		case PlatformType.Rotation:
			quaternion2 = UpdateRotation();
			flag = true;
			break;
		case PlatformType.ContinuousRotation:
			quaternion2 = UpdateContinuousRotation();
			flag = true;
			break;
		}
		if (!debugMovement)
		{
			lastPos = rb.position;
			lastRot = rb.rotation;
			if (platformType != PlatformType.Rotation)
			{
				rb.MovePosition(vector);
			}
			if (flag)
			{
				rb.MoveRotation(quaternion2);
			}
		}
		else
		{
			lastPos = base.transform.position;
			lastRot = base.transform.rotation;
			base.transform.position = vector;
			if (flag)
			{
				base.transform.rotation = quaternion2;
			}
		}
		deltaPosition = vector - lastPos;
	}

	public UnityEngine.Vector3 ThisFrameMovement()
	{
		return deltaPosition;
	}
}
public class SizeChanger : GorillaTriggerBox
