		if ((bool)trigger)
		{
			trigger.OnEnter -= OnTriggerExit;
		}
	}

	public void OnTriggerEnter(Collider other)
	{
		if ((bool)other.GetComponent<SphereCollider>())
		{
			VRRig component = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
			if (!(component == null))
			{
				acceptRig(component);
			}
		}
	}

	public void acceptRig(VRRig rig)
	{
		if (!rig.sizeManager.touchingChangers.Contains(this))
		{
			rig.sizeManager.touchingChangers.Add(this);
		}
		OnEnter?.Invoke();
	}

	public void OnTriggerExit(Collider other)
	{
		if ((bool)other.GetComponent<SphereCollider>())
		{
			VRRig component = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
			if (!(component == null))
			{
				unacceptRig(component);
			}
		}
	}

	public void unacceptRig(VRRig rig)
	{
		rig.sizeManager.touchingChangers.Remove(this);
		OnExit?.Invoke();
	}

	public UnityEngine.Vector3 ClosestPoint(UnityEngine.Vector3 position)
	{
		if ((bool)enterTrigger && (bool)exitTrigger)
		{
			UnityEngine.Vector3 vector = enterTrigger.ClosestPoint(position);
			UnityEngine.Vector3 vector2 = exitTrigger.ClosestPoint(position);
			if (!(UnityEngine.Vector3.Distance(position, vector) < UnityEngine.Vector3.Distance(position, vector2)))
			{
				return vector2;
			}
			return vector;
		}
		if ((bool)myCollider)
		{
			return myCollider.ClosestPoint(position);
		}
		return position;
	}

	public void SetScaleCenterPoint(Transform centerPoint)
	{
		scaleAwayFromPoint = centerPoint;
	}

	public bool TryGetScaleCenterPoint(out UnityEngine.Vector3 centerPoint)
	{
		if (scaleAwayFromPoint != null)
		{
			centerPoint = scaleAwayFromPoint.position;
			return true;
		}
		centerPoint = UnityEngine.Vector3.zero;
		return false;
	}
}
