public class Tappable : MonoBehaviour
{
	public int tappableId;

	public string staticId;

	public bool useStaticId;

	[Tooltip("If true, tap cooldown will be ignored.  Tapping will be allowed/disallowed based on result of CanTap()")]
	public bool overrideTapCooldown;

	[Space]
	public TappableManager manager;

	public RpcTarget rpcTarget;

	public void Validate()
	{
		CalculateId(force: true);
	}

	protected virtual void OnEnable()
	{
		if (!useStaticId)
		{
			CalculateId();
		}
		TappableManager.Register(this);
	}

	protected virtual void OnDisable()
	{
		TappableManager.Unregister(this);
	}

	public virtual bool CanTap(bool isLeftHand)
	{
		return true;
	}

	public void OnTap()
	{
		OnTap(1f);
	}

	public void OnTap(float tapStrength)
	{
		if (!NetworkSystem.Instance.InRoom)
		{
			OnTapLocal(tapStrength, Time.time, default(PhotonMessageInfoWrapped));
		}
		else if ((bool)manager)
		{
			manager.photonView.RPC("SendOnTapRPC", RpcTarget.All, tappableId, tapStrength);
		}
	}

	public void OnGrab()
	{
		if (!NetworkSystem.Instance.InRoom)
		{
			OnGrabLocal(Time.time, default(PhotonMessageInfoWrapped));
		}
		else if ((bool)manager)
		{
			manager.photonView.RPC("SendOnGrabRPC", RpcTarget.All, tappableId);
		}
	}

	public void OnRelease()
	{
		if (!NetworkSystem.Instance.InRoom)
		{
			OnReleaseLocal(Time.time, default(PhotonMessageInfoWrapped));
		}
		else if ((bool)manager)
		{
			manager.photonView.RPC("SendOnReleaseRPC", RpcTarget.All, tappableId);
		}
	}

	public virtual void OnTapLocal(float tapStrength, float tapTime, PhotonMessageInfoWrapped sender)
	{
	}

	public virtual void OnGrabLocal(float tapTime, PhotonMessageInfoWrapped sender)
	{
	}

	public virtual void OnReleaseLocal(float tapTime, PhotonMessageInfoWrapped sender)
	{
	}

	private void EdRecalculateId()
	{
		CalculateId(force: true);
	}

	private void CalculateId(bool force = false)
	{
		Transform transform = base.transform;
		int hashCode = TransformUtils.ComputePathHash(transform).ToId128().GetHashCode();
		int staticHash = GetType().Name.GetStaticHash();
		int hashCode2 = transform.position.QuantizedId128().GetHashCode();
		int num = StaticHash.Compute(hashCode, staticHash, hashCode2);
		if (useStaticId)
		{
			if (string.IsNullOrEmpty(staticId) || force)
			{
				int instanceID = transform.GetInstanceID();
				int num2 = StaticHash.Compute(num, instanceID);
				staticId = $"#ID_{num2:X8}";
			}
			tappableId = staticId.GetStaticHash();
		}
		else
		{
			tappableId = (UnityEngine.Application.isPlaying ? num : 0);
		}
	}

	[Conditional("UNITY_EDITOR")]
	private void OnValidate()
	{
		CalculateId();
	}
}
public class TappableManager : NetworkSceneObject
{
	private static TappableManager gManager;

	[SerializeField]
	private List<Tappable> tappables = new List<Tappable>();

	private HashSet<int> idSet = new HashSet<int>();

	private static HashSet<Tappable> gRegistry = new HashSet<Tappable>();

	private void Awake()
	{
		if (gManager != null && gManager != this)
		{
			GTDev.LogWarning("Instance of TappableManager already exists. Destroying.");
			UnityEngine.Object.Destroy(this);
			return;
		}
		if (gManager == null)
		{
			gManager = this;
		}
		if (gRegistry.Count == 0)
		{
			return;
		}
		Tappable[] array = gRegistry.ToArray();
		for (int i = 0; i < array.Length; i++)
		{
			if (!(array[i] == null))
			{
				RegisterInstance(array[i]);
			}
		}
		gRegistry.Clear();
	}

	private void RegisterInstance(Tappable t)
	{
		if (t == null)
		{
			GTDev.LogError("Tappable is null.");
			return;
		}
		t.manager = this;
		if (idSet.Add(t.tappableId))
		{
			tappables.Add(t);
		}
	}

	private void UnregisterInstance(Tappable t)
	{
		if (!(t == null) && idSet.Remove(t.tappableId))
		{
			tappables.Remove(t);
			t.manager = null;
		}
	}

	public static void Register(Tappable t)
	{
		if (gManager != null)
		{
			gManager.RegisterInstance(t);
		}
		else
		{
			gRegistry.Add(t);
		}
	}

	public static void Unregister(Tappable t)
	{
		if (gManager != null)
		{
			gManager.UnregisterInstance(t);
		}
		else
		{
			gRegistry.Remove(t);
		}
	}

	[Conditional("QATESTING")]
	public void DebugTestTap()
	{
		if (tappables.Count > 0)
		{
			int index = UnityEngine.Random.Range(0, tappables.Count);
			UnityEngine.Debug.Log("Send TestTap to tappable index: " + index + "/" + tappables.Count);
			tappables[index].OnTap(10f);
		}
		else
		{
			UnityEngine.Debug.Log("TappableManager: tappables array is empty.");
		}
	}

	[PunRPC]
	public void SendOnTapRPC(int key, float tapStrength, PhotonMessageInfo info)
	{
		SendOnTapShared(key, tapStrength, new PhotonMessageInfoWrapped(info));
	}

	[Rpc]
	public unsafe static void RPC_SendOnTap(NetworkRunner runner, int key, float tapStrength, RpcInfo info = default(RpcInfo))
	{
		if (NetworkBehaviourUtils.InvokeRpc)
		{
			NetworkBehaviourUtils.InvokeRpc = false;
		}
		else
		{
			if ((object)runner == null)
			{
				throw new ArgumentNullException("runner");
