	}

	void IRigAware.SetRig(VRRig rig)
	{
		_rig = rig;
	}

	public static implicit operator bool(OwnerRig or)
	{
		if ((object)or == null)
		{
			return false;
		}
		if (or == null)
		{
			return false;
		}
		if ((object)or._rig == null)
		{
			return false;
		}
		if (or._rig == null)
		{
			return false;
		}
		return true;
	}

