public class RadialBoundsTrigger : MonoBehaviour
{
	[SerializeField]
	private Id32 _triggerID;

	[Space]
	public RadialBounds object1 = new RadialBounds();

	[Space]
	public RadialBounds object2 = new RadialBounds();

	[Space]
	public float hysteresis = 0.5f;

	[SerializeField]
	private bool _raiseEvents = true;

	[Space]
	private bool _overlapping;

	private float _timeSpentInOverlap;

	[Space]
	private float _timeOverlapStarted;

	private float _timeOverlapStopped;

	public void TestOverlap()
	{
		TestOverlap(_raiseEvents);
	}

	public void TestOverlap(bool raiseEvents)
	{
		if (!object1 || !object2)
		{
			_overlapping = false;
			_timeOverlapStarted = -1f;
			_timeOverlapStopped = -1f;
			_timeSpentInOverlap = 0f;
			return;
		}
		float time = Time.time;
		float num = object1.radius + object2.radius;
		bool flag = (object2.center - object1.center).sqrMagnitude <= num * num;
		if (_overlapping && flag)
		{
			_overlapping = true;
			_timeSpentInOverlap = time - _timeOverlapStarted;
			if (raiseEvents)
			{
				object1.onOverlapStay?.Invoke(object2, _timeSpentInOverlap);
				object2.onOverlapStay?.Invoke(object1, _timeSpentInOverlap);
			}
		}
		else if (!_overlapping && flag)
		{
			if (!(time - _timeOverlapStopped < hysteresis))
			{
				_overlapping = true;
				_timeOverlapStarted = time;
				_timeOverlapStopped = -1f;
				_timeSpentInOverlap = 0f;
				if (raiseEvents)
				{
					object1.onOverlapEnter?.Invoke(object2);
					object2.onOverlapEnter?.Invoke(object1);
				}
			}
		}
		else if (!flag && _overlapping)
		{
			_overlapping = false;
			_timeOverlapStarted = -1f;
			_timeOverlapStopped = time;
			_timeSpentInOverlap = 0f;
			if (raiseEvents)
			{
				object1.onOverlapExit?.Invoke(object2);
				object2.onOverlapExit?.Invoke(object1);
			}
		}
	}

	private void FixedUpdate()
	{
		TestOverlap();
	}

	private void OnDisable()
	{
		if (_raiseEvents && (bool)object1 && (bool)object2 && _overlapping)
		{
			object1.onOverlapExit?.Invoke(object2);
			object2.onOverlapExit?.Invoke(object1);
		}
		_timeOverlapStarted = -1f;
		_timeSpentInOverlap = 0f;
		_overlapping = false;
	}
}
public class RadialMaterialFade : MonoBehaviour
{
	[SerializeField]
	private Material material;

	[SerializeField]
	private Transform target;

	[Header("Distance")]
	[SerializeField]
	private float minDistance = 1f;

	[SerializeField]
	private float maxDistance = 10f;

	[Header("Alpha")]
	[SerializeField]
	[Range(0f, 1f)]
	private float alphaAtMinDistance;

	[SerializeField]
	[Range(0f, 1f)]
	private float alphaAtMaxDistance = 1f;

	private static readonly int colorID = Shader.PropertyToID("_Color");

	private void Update()
	{
		if (!(material == null) && !(target == null))
		{
			Camera mainCamera = GTPlayer.Instance.mainCamera;
			if (!(mainCamera == null))
			{
				float value = UnityEngine.Vector3.Distance(mainCamera.transform.position, target.position);
				float t = Mathf.InverseLerp(minDistance, maxDistance, value);
				float a = Mathf.Lerp(alphaAtMinDistance, alphaAtMaxDistance, t);
				Color color = material.GetColor(colorID);
				color.a = a;
				material.SetColor(colorID, color);
			}
		}
	}
}
public class RandomizeTest : MonoBehaviour
{
	public List<int> testList = new List<int>();

	public int[] testListArray = new int[10];

	public int randomIterator;

	public int tempRandIndex;

	public int tempRandValue;

	private void Start()
	{
		for (int i = 0; i < 10; i++)
		{
			testList.Add(i);
		}
		for (int j = 0; j < 10; j++)
		{
			testListArray[j] = 0;
		}
		for (int k = 0; k < testList.Count; k++)
		{
			testListArray[k] = testList[k];
		}
		RandomizeList(ref testList);
		for (int l = 0; l < 10; l++)
		{
			testListArray[l] = 0;
		}
		for (int m = 0; m < testList.Count; m++)
		{
			testListArray[m] = testList[m];
		}
	}

	public void RandomizeList(ref List<int> listToRandomize)
	{
		for (randomIterator = 0; randomIterator < listToRandomize.Count; randomIterator++)
		{
			tempRandIndex = UnityEngine.Random.Range(randomIterator, listToRandomize.Count);
			tempRandValue = listToRandomize[randomIterator];
			listToRandomize[randomIterator] = listToRandomize[tempRandIndex];
			listToRandomize[tempRandIndex] = tempRandValue;
		}
	}
}
public class RangedFloat : MonoBehaviour, IRangedVariable<float>, IVariable<float>, IVariable
{
	[SerializeField]
	private float _value = 0.5f;

	[SerializeField]
	private float _min;

	[SerializeField]
	private float _max = 1f;

	[SerializeField]
	private AnimationCurve _curve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	public AnimationCurve Curve => _curve;

	public float Range => _max - _min;

	public float Min
	{
		get
		{
			return _min;
		}
		set
		{
			_min = value;
		}
	}

	public float Max
	{
		get
		{
			return _max;
		}
		set
		{
			_max = value;
		}
	}

	public float normalized
	{
		get
		{
			if (!Range.Approx0())
			{
				return (_value - _min) / (_max - Min);
			}
			return 0f;
		}
		set
		{
			_value = _min + Mathf.Clamp01(value) * (_max - _min);
		}
	}

	public float curved => _min + _curve.Evaluate(normalized) * (_max - _min);

	public float Get()
	{
		return _value;
	}

	public void Set(float f)
	{
		_value = Mathf.Clamp(f, _min, _max);
	}
}
[Serializable]
public class Ref<T> where T : class
{
	[SerializeField]
	private UnityEngine.Object _target;

	public T AsT
	{
		get
		{
			return this;
		}
		set
		{
			_target = value as UnityEngine.Object;
		}
	}

	public static implicit operator bool(Ref<T> r)
	{
		UnityEngine.Object obj = r?._target;
		if ((object)obj == null)
		{
			return false;
		}
		return obj != null;
	}

	public static implicit operator T(Ref<T> r)
	{
		UnityEngine.Object obj = r?._target;
		if ((object)obj == null)
		{
			return null;
		}
		if (obj == null)
		{
			return null;
		}
		return obj as T;
	}

	public static implicit operator UnityEngine.Object(Ref<T> r)
	{
		UnityEngine.Object obj = r?._target;
		if ((object)obj == null)
		{
			return null;
		}
		if (obj == null)
		{
			return null;
		}
		return obj;
	}
}
public class ReplacementVoice : MonoBehaviour, IGorillaSliceableSimple
{
	public AudioSource replacementVoiceSource;

	public AudioClip[] replacementVoiceClips;

	public AudioClip[] replacementVoiceClipsLoud;

	public float loudReplacementVoiceThreshold = 0.1f;

	public VRRig myVRRig;

	public float normalVolume = 0.5f;

	public float loudVolume = 0.8f;

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	public void SliceUpdate()
	{
		CosmeticEffectsOnPlayers.CosmeticEffect value;
		if (!replacementVoiceSource.isPlaying && myVRRig.ShouldPlayReplacementVoice())
		{
			if (!Mathf.Approximately(myVRRig.voiceAudio.pitch, replacementVoiceSource.pitch))
			{
				replacementVoiceSource.pitch = myVRRig.voiceAudio.pitch;
			}
			if (myVRRig.SpeakingLoudness < loudReplacementVoiceThreshold)
			{
				replacementVoiceSource.clip = replacementVoiceClips[UnityEngine.Random.Range(0, replacementVoiceClips.Length - 1)];
				replacementVoiceSource.volume = normalVolume;
			}
			else
			{
				replacementVoiceSource.clip = replacementVoiceClipsLoud[UnityEngine.Random.Range(0, replacementVoiceClipsLoud.Length - 1)];
				replacementVoiceSource.volume = loudVolume;
			}
			replacementVoiceSource.GTPlay();
		}
		else if (!replacementVoiceSource.isPlaying && myVRRig.TryGetCosmeticVoiceOverride(CosmeticEffectsOnPlayers.EFFECTTYPE.VoiceOverride, out value) && !(myVRRig.SpeakingLoudness < myVRRig.replacementVoiceLoudnessThreshold))
		{
			if (!Mathf.Approximately(myVRRig.voiceAudio.pitch, replacementVoiceSource.pitch))
			{
				replacementVoiceSource.pitch = myVRRig.voiceAudio.pitch;
			}
			if (myVRRig.SpeakingLoudness < value.voiceOverrideLoudThreshold)
			{
				replacementVoiceSource.clip = value.voiceOverrideNormalClips[UnityEngine.Random.Range(0, value.voiceOverrideNormalClips.Length - 1)];
				replacementVoiceSource.volume = value.voiceOverrideNormalVolume;
			}
			else
			{
				replacementVoiceSource.clip = value.voiceOverrideLoudClips[UnityEngine.Random.Range(0, value.voiceOverrideLoudClips.Length - 1)];
				replacementVoiceSource.volume = value.voiceOverrideLoudVolume;
			}
			replacementVoiceSource.GTPlay();
		}
	}
}
