public class SlowCameraUpdate : MonoBehaviour
{
	private Camera myCamera;

	private float frameRate;

	private float timeToNextFrame;

	public void Awake()
	{
		frameRate = 30f;
		timeToNextFrame = 1f / frameRate;
		myCamera = GetComponent<Camera>();
	}

	public void OnEnable()
	{
		StartCoroutine(UpdateMirror());
	}

	public void OnDisable()
	{
		StopAllCoroutines();
	}

	public IEnumerator UpdateMirror()
	{
		while (true)
		{
			if (base.gameObject.activeSelf)
			{
				UnityEngine.Debug.Log("rendering camera!");
				myCamera.Render();
			}
			yield return new WaitForSeconds(timeToNextFrame);
		}
	}
}
public class SnapXformToLine : MonoBehaviour
{
	public bool apply = true;

	public bool snapOrientation = true;

	public bool resetOnDisable = true;

	[Space]
	public Transform target;

	[Space]
	public Transform from;

	public Transform to;

	private UnityEngine.Vector3 _closest;

	private float _linear;

	public Ref<IRangedVariable<float>> output;

	public UnityEvent<float> onLinearDistanceChanged;

	public UnityEvent<UnityEngine.Vector3> onPositionChanged;

	public UnityEngine.Vector3 linePoint => _closest;

	public float linearDistance => _linear;

	public void SnapTarget(bool applyToXform = true)
	{
		Snap(target);
	}

	public void SnapTarget(UnityEngine.Vector3 point)
	{
		if ((bool)target)
		{
			target.position = GetSnappedPoint(target.position);
		}
	}

	public void SnapTargetLinear(float t)
	{
		if ((bool)target && (bool)from && (bool)to)
		{
			target.position = UnityEngine.Vector3.Lerp(from.position, to.position, t);
		}
	}

	public UnityEngine.Vector3 GetSnappedPoint(Transform t)
	{
		return GetSnappedPoint(t.position);
	}

	public UnityEngine.Vector3 GetSnappedPoint(UnityEngine.Vector3 point)
	{
		if (!apply)
		{
			return point;
		}
		if (!from || !to)
		{
			return point;
		}
		return GetClosestPointOnLine(point, from.position, to.position);
	}

	public void Snap(Transform xform, bool applyToXform = true)
	{
		if (!apply || !xform || !from || !to)
		{
			return;
		}
		UnityEngine.Vector3 position = xform.position;
		UnityEngine.Vector3 position2 = from.position;
		UnityEngine.Vector3 position3 = to.position;
		UnityEngine.Vector3 closestPointOnLine = GetClosestPointOnLine(position, position2, position3);
		float num = UnityEngine.Vector3.Distance(position2, position3);
		float num2 = UnityEngine.Vector3.Distance(closestPointOnLine, position2);
		UnityEngine.Vector3 closest = _closest;
		UnityEngine.Vector3 closest2 = closestPointOnLine;
		float linear = _linear;
		float num3 = (Mathf.Approximately(num, 0f) ? 0f : (num2 / (num + Mathf.Epsilon)));
		_closest = closest2;
		_linear = num3;
		if ((bool)output)
		{
			IRangedVariable<float> asT = output.AsT;
			asT.Set(asT.Min + _linear * asT.Range);
		}
		if (applyToXform)
		{
			xform.position = _closest;
			if (!Mathf.Approximately(closest.x, closest2.x) || !Mathf.Approximately(closest.y, closest2.y) || !Mathf.Approximately(closest.z, closest2.z))
			{
				onPositionChanged?.Invoke(_closest);
			}
			if (!Mathf.Approximately(linear, num3))
			{
				onLinearDistanceChanged?.Invoke(_linear);
			}
			if (snapOrientation)
			{
				xform.forward = (position3 - position2).normalized;
				xform.up = UnityEngine.Vector3.Lerp(from.up.normalized, to.up.normalized, _linear);
			}
		}
	}

	private void OnDisable()
	{
		if (resetOnDisable)
		{
			SnapTargetLinear(0f);
		}
	}

	private void LateUpdate()
	{
		SnapTarget();
	}

	private static UnityEngine.Vector3 GetClosestPointOnLine(UnityEngine.Vector3 p, UnityEngine.Vector3 a, UnityEngine.Vector3 b)
	{
		UnityEngine.Vector3 lhs = p - a;
		UnityEngine.Vector3 vector = b - a;
		float sqrMagnitude = vector.sqrMagnitude;
		float num = Mathf.Clamp(UnityEngine.Vector3.Dot(lhs, vector) / sqrMagnitude, 0f, 1f);
		return a + vector * num;
	}
}
public class SpawnPooledObject : MonoBehaviour
{
	[SerializeField]
	private Transform _spawnLocation;

	[SerializeField]
	private GameObject _pooledObject;

	[FormerlySerializedAs("_offset")]
	public UnityEngine.Vector3 offset;

	[FormerlySerializedAs("_upright")]
	public bool upright;

	[FormerlySerializedAs("_facePlayer")]
	public bool facePlayer;

	[FormerlySerializedAs("_chanceToSpawn")]
	[Range(0f, 100f)]
	public int chanceToSpawn = 100;

	private int _pooledObjectHash;

	private void Awake()
	{
		if (!(_pooledObject == null))
		{
			_pooledObjectHash = PoolUtils.GameObjHashCode(_pooledObject);
		}
	}

	public void SpawnObject()
	{
		if (ShouldSpawn() && !(_pooledObject == null) && !(_spawnLocation == null))
		{
			GameObject obj = ObjectPools.instance.Instantiate(_pooledObjectHash);
			obj.transform.position = SpawnLocation();
			obj.transform.rotation = SpawnRotation();
			obj.transform.localScale = base.transform.lossyScale;
		}
	}

	private UnityEngine.Vector3 SpawnLocation()
	{
		return _spawnLocation.transform.position + offset;
	}

	private UnityEngine.Quaternion SpawnRotation()
	{
		UnityEngine.Quaternion result = _spawnLocation.transform.rotation;
		if (facePlayer)
		{
			result = UnityEngine.Quaternion.LookRotation(GTPlayer.Instance.headCollider.transform.position - _spawnLocation.transform.position);
		}
		if (upright)
		{
			result.eulerAngles = new UnityEngine.Vector3(0f, result.eulerAngles.y, 0f);
		}
		return result;
	}

	private bool ShouldSpawn()
	{
		return UnityEngine.Random.Range(0, 100) < chanceToSpawn;
	}
}
