[DefaultExecutionOrder(100)]
public class TransformFollow : MonoBehaviour
{
	public Transform transformToFollow;

	public UnityEngine.Vector3 offset;

	public UnityEngine.Vector3 prevPos;

	public bool rotationOnly;

	private bool forRigRecording;

	private TransformFollow parentFollow;

	private void Awake()
	{
		prevPos = base.transform.position;
		if (rotationOnly && base.transform.parent != null && base.transform.parent.GetComponent<TransformFollow>() != null)
		{
			forRigRecording = true;
		}
		if (forRigRecording)
		{
			parentFollow = base.transform.parent.GetComponent<TransformFollow>();
		}
	}

	private void LateUpdate()
	{
		prevPos = base.transform.position;
		if (rotationOnly)
		{
			if (forRigRecording)
			{
				base.transform.localRotation = UnityEngine.Quaternion.Inverse(parentFollow.transformToFollow.rotation) * transformToFollow.rotation;
			}
			else
			{
				base.transform.rotation = transformToFollow.rotation;
			}
		}
		else
		{
			transformToFollow.GetPositionAndRotation(out var position, out var rotation);
			base.transform.SetPositionAndRotation(position + rotation * offset, rotation);
		}
	}
}
public class TransformFollowXScene : MonoBehaviour
{
	public XSceneRef refToFollow;

	private Transform transformToFollow;

	public UnityEngine.Vector3 offset;

	public UnityEngine.Vector3 prevPos;

	private void Awake()
	{
		prevPos = base.transform.position;
	}

	private void Start()
	{
		refToFollow.TryResolve(out transformToFollow);
	}

	private void LateUpdate()
	{
		prevPos = base.transform.position;
		base.transform.rotation = transformToFollow.rotation;
		base.transform.position = transformToFollow.position + transformToFollow.rotation * offset;
	}
}
