public enum HeldItemButtonConsumeMode
{
	None,
	Destroy,
	Disable
}
public enum HeldItemButtonMode
{
	OneShot,
	ResetAfterDelay,
	Toggle
}
public class GorillaHeldItemPressableButton : MonoBehaviour, IDelayedExecListener
{
	public int pressButtonSoundIndex = 67;

	public bool isOn;

	public float delayBetweenSuccessfulPresses = 0.25f;

	private float touchTime;

	public HeldItemButtonMode mode;

	public List<TransferrableObject> acceptedHoldables;

	private List<Type> acceptedTypes;

	public bool acceptAnyHoldableThatMatchesType = true;

	public HeldItemButtonConsumeMode consumeItem;

	[Space]
	public UnityEvent<TransferrableObject> onPressButton;

	[Space]
	public UnityEvent<TransferrableObject> onReleaseButton;

	public event Action<GorillaHeldItemPressableButton, TransferrableObject, bool> onPressed;

	public event Action<GorillaHeldItemPressableButton, TransferrableObject, bool> onReleased;

	private void Start()
	{
		if (!acceptAnyHoldableThatMatchesType)
		{
			return;
		}
		acceptedTypes = new List<Type>();
		foreach (TransferrableObject acceptedHoldable in acceptedHoldables)
		{
			acceptedTypes.Add(acceptedHoldable.GetType());
		}
	}

	protected void OnTriggerEnter(Collider collider)
	{
		if (!base.enabled || !(touchTime + delayBetweenSuccessfulPresses < Time.time))
		{
			return;
		}
		TransferrableObject componentInParent = collider.GetComponentInParent<TransferrableObject>();
		if (componentInParent == null)
		{
			componentInParent = collider.transform.parent.GetComponentInParent<TransferrableObject>();
		}
		if (componentInParent == null || !componentInParent.InHand())
		{
			return;
		}
		if (acceptAnyHoldableThatMatchesType)
		{
			if (!acceptedTypes.Contains(componentInParent.GetType()))
			{
				return;
			}
		}
		else if (!acceptedHoldables.Contains(componentInParent))
		{
			return;
		}
		touchTime = Time.time;
		switch (mode)
		{
		case HeldItemButtonMode.OneShot:
			onPressButton?.Invoke(componentInParent);
			this.onPressed?.Invoke(this, componentInParent, componentInParent.InLeftHand());
			ButtonActivation(componentInParent);
			ButtonActivationWithHand(componentInParent, componentInParent.InLeftHand());
			break;
		case HeldItemButtonMode.ResetAfterDelay:
			isOn = true;
			onPressButton?.Invoke(componentInParent);
			this.onPressed?.Invoke(this, componentInParent, componentInParent.InLeftHand());
			ButtonActivation(componentInParent);
			ButtonActivationWithHand(componentInParent, componentInParent.InLeftHand());
			GTDelayedExec.Add(this, delayBetweenSuccessfulPresses, 0);
			break;
		case HeldItemButtonMode.Toggle:
			isOn = !isOn;
			if (isOn)
			{
				onPressButton?.Invoke(componentInParent);
				this.onPressed?.Invoke(this, componentInParent, componentInParent.InLeftHand());
				ButtonActivation(componentInParent);
				ButtonActivationWithHand(componentInParent, componentInParent.InLeftHand());
			}
			else
			{
				onReleaseButton?.Invoke(componentInParent);
				this.onReleased?.Invoke(this, componentInParent, componentInParent.InLeftHand());
			}
			break;
		}
		GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(pressButtonSoundIndex, componentInParent.InLeftHand(), 0.05f);
		GorillaTagger.Instance.StartVibration(componentInParent.InLeftHand(), GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
		if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
		{
			GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, componentInParent.InLeftHand(), 0.05f);
		}
		switch (consumeItem)
		{
		case HeldItemButtonConsumeMode.Destroy:
			componentInParent.OnMyCreatorLeft();
			break;
		case HeldItemButtonConsumeMode.Disable:
			componentInParent.gameObject.SetActive(value: false);
			break;
		case HeldItemButtonConsumeMode.None:
			break;
		}
	}

	public virtual void ButtonActivation(TransferrableObject holdable)
	{
	}

	public virtual void ButtonActivationWithHand(TransferrableObject holdable, bool isLeftHand)
	{
	}

	public virtual void ResetState()
	{
		isOn = false;
		onReleaseButton?.Invoke(null);
		this.onReleased?.Invoke(this, null, arg3: false);
	}

	public void OnDelayedAction(int contextIndex)
	{
		ResetState();
	}
}
public abstract class GorillaKeyButton<TBinding> : MonoBehaviour where TBinding : Enum
{
	public string characterString;

	public TBinding Binding;

	public bool functionKey;

	public Renderer ButtonRenderer;

	public ButtonColorSettings ButtonColorSettings;

	[Tooltip("These GameObjects will be Activated/Deactivated when this button is Activated/Deactivated")]
	public GameObject[] linkedObjects;

	[Tooltip("Intended for use with GorillaKeyWrapper")]
	public UnityEvent<TBinding> OnKeyButtonPressed = new UnityEvent<TBinding>();

	public bool testClick;

	public bool repeatTestClick;

	public float repeatCooldown = 2f;

	private float pressTime;

	private float lastTestClick;

	protected MaterialPropertyBlock propBlock;

	private void Awake()
	{
		if (ButtonRenderer == null)
		{
			ButtonRenderer = GetComponent<Renderer>();
		}
		propBlock = new MaterialPropertyBlock();
		pressTime = 0f;
	}

	private void OnEnable()
	{
		for (int i = 0; i < linkedObjects.Length; i++)
		{
			if (linkedObjects[i].IsNotNull())
			{
				linkedObjects[i].SetActive(value: true);
			}
		}
		OnEnableEvents();
	}

	private void OnDisable()
	{
		for (int i = 0; i < linkedObjects.Length; i++)
		{
			if (linkedObjects[i].IsNotNull())
			{
				linkedObjects[i].SetActive(value: false);
			}
		}
		OnDisableEvents();
	}

	private void OnTriggerEnter(Collider collider)
	{
		GorillaTriggerColliderHandIndicator componentInParent = collider.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
		if ((bool)componentInParent)
		{
			PressButton(componentInParent.isLeftHand);
		}
	}

	private void PressButton(bool isLeftHand)
	{
		OnButtonPressedEvent();
		OnKeyButtonPressed?.Invoke(Binding);
		PressButtonColourUpdate();
		GorillaTagger.Instance.StartVibration(isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
		GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(66, isLeftHand, 0.1f);
		if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
		{
			GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 66, isLeftHand, 0.1f);
		}
	}

	protected virtual void OnEnableEvents()
	{
	}

	protected virtual void OnDisableEvents()
	{
	}

	public void Click(bool leftHand = false)
	{
		PressButton(leftHand);
	}

	public virtual void PressButtonColourUpdate()
	{
		if (base.gameObject.activeInHierarchy)
		{
			propBlock.SetColor(ShaderProps._BaseColor, ButtonColorSettings.PressedColor);
			propBlock.SetColor(ShaderProps._Color, ButtonColorSettings.PressedColor);
			ButtonRenderer.SetPropertyBlock(propBlock);
			pressTime = Time.time;
			StartCoroutine(ButtonColorUpdate_Local());
		}
		IEnumerator ButtonColorUpdate_Local()
		{
			yield return new WaitForSeconds(ButtonColorSettings.PressedTime);
			if (pressTime != 0f && Time.time > ButtonColorSettings.PressedTime + pressTime)
			{
				propBlock.SetColor(ShaderProps._BaseColor, ButtonColorSettings.UnpressedColor);
				propBlock.SetColor(ShaderProps._Color, ButtonColorSettings.UnpressedColor);
				ButtonRenderer.SetPropertyBlock(propBlock);
				pressTime = 0f;
			}
		}
	}

	protected abstract void OnButtonPressedEvent();
}
public class GorillaNameManager : MonoBehaviour
{
}
public class GorillaPhysicalButton : MonoBehaviour
{
	public Material pressedMaterial;

	public Material unpressedMaterial;

	public MeshRenderer buttonRenderer;

	public int pressButtonSoundIndex = 67;

	[SerializeField]
	public bool canToggleOn;

	public bool canToggleOff;

	private bool waitingForReleaseAfterStateChange;

	public bool isOn;

	public bool testPress;

	public bool testHandLeft;

	[SerializeField]
	protected float buttonPushDepth = 0.0125f;

	[SerializeField]
	protected float buttonDepthForTrigger = 0.01f;

	[SerializeField]
	public List<Transform> moveableChildren;

	[NonSerialized]
	public List<UnityEngine.Vector3> moveableChildrenStartPositions;

	private UnityEngine.Vector3 startButtonPosition;

	[TextArea]
	public string offText = "OFF";

	[TextArea]
	public string onText = "ON";

	[SerializeField]
	public TMP_Text textField;

	[Space]
	public UnityEvent onPressButtonOn;

	public UnityEvent onPressButtonToggleOff;

	private Collider recentFingerCollider;

	protected float currentButtonDepthFromPressing;

	private Coroutine buttonTestCoroutine;

	public event Action<GorillaPhysicalButton, bool> onPressedOn;

	public event Action<GorillaPhysicalButton, bool> onToggledOff;

	public virtual void Start()
	{
		if (moveableChildren != null)
		{
			moveableChildrenStartPositions = new List<UnityEngine.Vector3>(moveableChildren.Count);
			for (int i = 0; i < moveableChildren.Count; i++)
			{
				moveableChildrenStartPositions.Add(moveableChildren[i].position);
			}
		}
		startButtonPosition = base.transform.position;
		base.enabled = true;
	}

	private void OnEnable()
	{
	}

	private void OnDisable()
	{
	}

	private float GetSurfaceDistanceFromKeyToCollider(Collider collider)
	{
		if (collider == null)
		{
			return 1f;
		}
		SphereCollider sphereCollider = collider as SphereCollider;
		float num = (sphereCollider ? sphereCollider.radius : 0f);
		float num2 = base.transform.localScale.z * 0.5f;
		if (UnityEngine.Vector3.Distance(collider.transform.position, base.transform.position) > (base.transform.localScale.magnitude * 0.5f + num) * 1.5f)
		{
			return 1f;
		}
		return UnityEngine.Vector3.Dot(base.transform.position - collider.transform.position, -base.transform.forward) - num - num2;
	}

	protected void OnTriggerEnter(Collider other)
	{
		if (base.enabled && !(other.GetComponentInParent<GorillaTriggerColliderHandIndicator>() == null))
		{
			recentFingerCollider = other;
			if (buttonTestCoroutine == null)
			{
				buttonTestCoroutine = StartCoroutine(ButtonUpdate());
			}
		}
	}

	protected IEnumerator ButtonUpdate()
	{
		while (true)
		{
			UpdateButtonFromCollider();
			if (!base.enabled || recentFingerCollider == null)
			{
				break;
			}
			yield return null;
		}
		buttonTestCoroutine = null;
	}

	protected void UpdateButtonFromCollider()
	{
		if (recentFingerCollider != null)
		{
			float surfaceDistanceFromKeyToCollider = GetSurfaceDistanceFromKeyToCollider(recentFingerCollider);
			currentButtonDepthFromPressing -= surfaceDistanceFromKeyToCollider;
			currentButtonDepthFromPressing = Mathf.Clamp(currentButtonDepthFromPressing, 0f, buttonPushDepth);
		}
		else
		{
			currentButtonDepthFromPressing = 0f;
		}
		if (currentButtonDepthFromPressing == 0f)
		{
			if (!canToggleOn && !canToggleOff)
			{
				isOn = false;
			}
			recentFingerCollider = null;
			waitingForReleaseAfterStateChange = false;
		}
		TestForButtonStateChange();
		UpdateButtonVisuals();
	}

	protected void TestForButtonStateChange()
	{
		if (waitingForReleaseAfterStateChange)
		{
			return;
		}
		if (currentButtonDepthFromPressing > buttonDepthForTrigger && !isOn && recentFingerCollider != null)
		{
			isOn = true;
			waitingForReleaseAfterStateChange = true;
			GorillaTriggerColliderHandIndicator component = recentFingerCollider.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (!(component == null))
			{
				onPressButtonOn?.Invoke();
				this.onPressedOn?.Invoke(this, component.isLeftHand);
				ButtonPressedOn();
				ButtonPressedOnWithHand(component.isLeftHand);
				GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(pressButtonSoundIndex, component.isLeftHand, 0.05f);
				GorillaTagger.Instance.StartVibration(component.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
				if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
				{
					GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, component.isLeftHand, 0.05f);
				}
			}
		}
		else
		{
			if (!(currentButtonDepthFromPressing > buttonDepthForTrigger) || !canToggleOff || !isOn || !(recentFingerCollider != null))
			{
				return;
			}
			isOn = false;
			waitingForReleaseAfterStateChange = true;
			GorillaTriggerColliderHandIndicator component2 = recentFingerCollider.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (!(component2 == null))
			{
				onPressButtonToggleOff?.Invoke();
				this.onToggledOff?.Invoke(this, component2.isLeftHand);
				ButtonToggledOff();
				ButtonToggledOffWithHand(component2.isLeftHand);
				GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(pressButtonSoundIndex, component2.isLeftHand, 0.05f);
				GorillaTagger.Instance.StartVibration(component2.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
				if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
				{
					GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, component2.isLeftHand, 0.05f);
				}
			}
		}
	}

	protected void UpdateButtonVisuals()
	{
		float num = currentButtonDepthFromPressing;
		if ((canToggleOff || canToggleOn) && isOn)
		{
			num = Mathf.Max(buttonDepthForTrigger, num);
		}
		base.transform.position = startButtonPosition - base.transform.forward * num;
		if (moveableChildren != null)
		{
			for (int i = 0; i < moveableChildren.Count; i++)
			{
				moveableChildren[i].position = moveableChildrenStartPositions[i] - base.transform.forward * num;
			}
		}
		UpdateColorWithState(isOn);
	}

	protected void UpdateColorWithState(bool state)
	{
		if (state)
		{
			buttonRenderer.material = pressedMaterial;
			if ((!string.IsNullOrEmpty(onText) || !string.IsNullOrEmpty(offText)) && textField != null)
			{
				textField.text = onText;
			}
		}
		else
		{
			buttonRenderer.material = unpressedMaterial;
			if ((!string.IsNullOrEmpty(offText) || !string.IsNullOrEmpty(onText)) && textField != null)
			{
				textField.text = offText;
			}
		}
	}

	public virtual void ButtonPressedOn()
	{
	}

	public virtual void ButtonPressedOnWithHand(bool isLeftHand)
	{
	}

	public virtual void ButtonToggledOff()
	{
	}

	public virtual void ButtonToggledOffWithHand(bool isLeftHand)
	{
	}

	public virtual void ResetState()
	{
		isOn = false;
		currentButtonDepthFromPressing = 0f;
		waitingForReleaseAfterStateChange = false;
		UpdateButtonVisuals();
	}

	public void SetText(string newText)
	{
		if (textField != null)
		{
			textField.text = offText;
		}
	}

	public virtual void SetButtonState(bool setToOn)
	{
		if (!canToggleOn && !canToggleOff)
		{
			return;
		}
		if (isOn != setToOn)
		{
			isOn = setToOn;
			if (isOn)
			{
				onPressButtonOn?.Invoke();
				ButtonPressedOn();
			}
			else
			{
				onPressButtonToggleOff?.Invoke();
				ButtonToggledOff();
			}
		}
		UpdateButtonVisuals();
	}
}
public class GorillaPlayerLineButton : MonoBehaviour
{
	public enum ButtonType
	{
		HateSpeech,
		Cheating,
		Toxicity,
		Mute,
		Report,
		Cancel
	}

	public GorillaPlayerScoreboardLine parentLine;

	public ButtonType buttonType;

	public bool isOn;

	public bool isAutoOn;

	public Material offMaterial;

	public Material onMaterial;

	public Material autoOnMaterial;

	public string offText;

	public string onText;

	public string autoOnText;

	public Text myText;

	public float debounceTime = 0.25f;

	public float touchTime;

	public bool testPress;

	private void OnEnable()
	{
		if (UnityEngine.Application.isEditor)
		{
			StartCoroutine(TestPressCheck());
		}
	}

	private void OnDisable()
	{
		if (UnityEngine.Application.isEditor)
		{
			StopAllCoroutines();
		}
	}

	private IEnumerator TestPressCheck()
	{
		while (true)
		{
			if (testPress)
			{
				testPress = false;
				if (buttonType == ButtonType.Mute)
				{
					isOn = !isOn;
				}
				parentLine.PressButton(isOn, buttonType);
			}
			yield return new WaitForSeconds(1f);
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		if (!base.enabled || !(touchTime + debounceTime < Time.time) || !(collider.GetComponentInParent<GorillaTriggerColliderHandIndicator>() != null))
		{
			return;
		}
		touchTime = Time.time;
		GorillaTriggerColliderHandIndicator component = collider.GetComponent<GorillaTriggerColliderHandIndicator>();
		if (buttonType == ButtonType.Mute)
		{
			if (isAutoOn)
			{
				isOn = false;
			}
			else
			{
				isOn = !isOn;
			}
		}
		if (buttonType != ButtonType.Mute && buttonType != ButtonType.HateSpeech && buttonType != ButtonType.Cheating && buttonType != ButtonType.Cancel && !parentLine.canPressNextReportButton)
		{
			return;
		}
		parentLine.PressButton(isOn, buttonType);
		if (component != null)
		{
			GorillaTagger.Instance.StartVibration(component.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(67, component.isLeftHand, 0.05f);
			if (PhotonNetwork.InRoom && GorillaTagger.Instance.myVRRig != null)
			{
				GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, component.isLeftHand, 0.05f);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (buttonType != ButtonType.Mute && other.GetComponentInParent<GorillaTriggerColliderHandIndicator>() != null)
		{
			parentLine.canPressNextReportButton = true;
		}
	}

	public void UpdateColor()
	{
		if (isOn)
		{
			GetComponent<MeshRenderer>().material = onMaterial;
			myText.text = onText;
		}
		else if (isAutoOn)
		{
			GetComponent<MeshRenderer>().material = autoOnMaterial;
			myText.text = autoOnText;
		}
		else
		{
			GetComponent<MeshRenderer>().material = offMaterial;
			myText.text = offText;
		}
	}
}
public class GorillaPlayerScoreboardLine : MonoBehaviour
{
	private static int[] targetActors = new int[1] { -1 };

	public Text playerName;

	public Text playerLevel;

	public Text playerMMR;

	public Image playerSwatch;

	public Texture infectedTexture;

	public NetPlayer linePlayer;

	public VRRig playerVRRig;

	public string playerLevelValue;

	public string playerMMRValue;

	public string playerNameValue;

	public string playerNameVisible;

	public int playerActorNumber;

	public GorillaPlayerLineButton muteButton;

	public GorillaPlayerLineButton reportButton;

	public GameObject hateSpeechButton;

	public GameObject toxicityButton;

	public GameObject cheatingButton;

	public GameObject cancelButton;

	public SpriteRenderer speakerIcon;

	public bool canPressNextReportButton = true;

	public Text[] texts;

	public SpriteRenderer[] sprites;

	public MeshRenderer[] meshes;

	public Image[] images;

	private Recorder myRecorder;

	private bool isMuteManual;

	private int mute;

	private int emptyRigCount;

	public GameObject myRig;

	public bool reportedCheating;

	public bool reportedToxicity;

	public bool reportedHateSpeech;

	public bool reportInProgress;

	private string currentNickname;

	public bool doneReporting;

	public bool lastVisible = true;

	public GorillaScoreBoard parentScoreboard;

	public float initTime;

	public float emptyRigCooldown = 10f;

	internal RigContainer rigContainer;

	public void Start()
	{
		emptyRigCount = 0;
		reportedCheating = false;
		reportedHateSpeech = false;
		reportedToxicity = false;
	}

	public void InitializeLine()
	{
		currentNickname = string.Empty;
		UpdatePlayerText();
		if (linePlayer == NetworkSystem.Instance.LocalPlayer)
		{
			muteButton.gameObject.SetActive(value: false);
			reportButton.gameObject.SetActive(value: false);
			hateSpeechButton.SetActive(value: false);
			toxicityButton.SetActive(value: false);
			cheatingButton.SetActive(value: false);
			cancelButton.SetActive(value: false);
			return;
		}
		muteButton.gameObject.SetActive(value: true);
		if (GorillaScoreboardTotalUpdater.instance != null && GorillaScoreboardTotalUpdater.instance.reportDict.ContainsKey(playerActorNumber))
		{
			GorillaScoreboardTotalUpdater.PlayerReports playerReports = GorillaScoreboardTotalUpdater.instance.reportDict[playerActorNumber];
			reportedCheating = playerReports.cheating;
			reportedHateSpeech = playerReports.hateSpeech;
			reportedToxicity = playerReports.toxicity;
			reportInProgress = playerReports.pressedReport;
		}
		else
		{
			reportedCheating = false;
			reportedHateSpeech = false;
			reportedToxicity = false;
			reportInProgress = false;
		}
		reportButton.isOn = reportedCheating || reportedHateSpeech || reportedToxicity;
		reportButton.UpdateColor();
		SwapToReportState(reportInProgress);
		muteButton.gameObject.SetActive(value: true);
		isMuteManual = PlayerPrefs.HasKey(linePlayer.UserId);
		mute = PlayerPrefs.GetInt(linePlayer.UserId, 0);
		muteButton.isOn = ((mute != 0) ? true : false);
		muteButton.isAutoOn = false;
		muteButton.UpdateColor();
		if (rigContainer != null)
		{
			rigContainer.hasManualMute = isMuteManual;
			rigContainer.Muted = ((mute != 0) ? true : false);
		}
	}

	public void SetLineData(NetPlayer netPlayer)
	{
		if (netPlayer.InRoom && netPlayer != linePlayer)
		{
			if (playerActorNumber != netPlayer.ActorNumber)
			{
				initTime = Time.time;
			}
			playerActorNumber = netPlayer.ActorNumber;
			linePlayer = netPlayer;
			playerNameValue = netPlayer.NickName ?? "";
			if (VRRigCache.Instance.TryGetVrrig(netPlayer, out var playerRig))
			{
				rigContainer = playerRig;
				playerVRRig = playerRig.Rig;
			}
			InitializeLine();
		}
	}

	public void UpdateLine()
	{
		if (linePlayer == null)
		{
			return;
		}
		if (playerNameVisible != playerVRRig.playerNameVisible)
		{
			UpdatePlayerText();
			parentScoreboard.IsDirty = true;
			if (playerVRRig.creator.IsMasterClient && GorillaComputer.instance.IsPlayerInVirtualStump())
			{
				CustomMapModeSelector.RefreshHostName();
			}
		}
		if (!(rigContainer != null))
		{
			return;
		}
		if (Time.time > initTime + emptyRigCooldown)
		{
			if (playerVRRig.netView != null)
			{
				emptyRigCount = 0;
			}
			else
			{
				emptyRigCount++;
				if (emptyRigCount > 30)
				{
					MonkeAgent.instance.SendReport("empty rig", linePlayer.UserId, linePlayer.NickName);
				}
			}
		}
		Material material = ((playerVRRig.setMatIndex != 0) ? playerVRRig.materialsToChangeTo[playerVRRig.setMatIndex] : playerVRRig.scoreboardMaterial);
		if (playerSwatch.material != material)
		{
			playerSwatch.material = material;
		}
		if (playerSwatch.color != playerVRRig.materialsToChangeTo[0].color)
		{
			playerSwatch.color = playerVRRig.materialsToChangeTo[0].color;
		}
		if (myRecorder == null)
		{
			myRecorder = NetworkSystem.Instance.LocalRecorder;
		}
		if (playerVRRig != null)
		{
			if (playerVRRig.remoteUseReplacementVoice || playerVRRig.localUseReplacementVoice || GorillaComputer.instance.voiceChatOn == "FALSE")
			{
				if (playerVRRig.SpeakingLoudness > playerVRRig.replacementVoiceLoudnessThreshold && !rigContainer.ForceMute && !rigContainer.Muted)
				{
					speakerIcon.enabled = true;
				}
				else
				{
					speakerIcon.enabled = false;
				}
			}
			else if ((rigContainer.Voice != null && rigContainer.Voice.IsSpeaking) || (playerVRRig.rigSerializer != null && playerVRRig.rigSerializer.IsLocallyOwned && myRecorder != null && myRecorder.IsCurrentlyTransmitting))
			{
				speakerIcon.enabled = true;
			}
			else
			{
				speakerIcon.enabled = false;
			}
		}
		else
		{
			speakerIcon.enabled = false;
		}
		if (!isMuteManual)
		{
			bool isPlayerAutoMuted = rigContainer.GetIsPlayerAutoMuted();
			if (muteButton.isAutoOn != isPlayerAutoMuted)
			{
				muteButton.isAutoOn = isPlayerAutoMuted;
				muteButton.UpdateColor();
			}
		}
	}

	private void UpdatePlayerText()
	{
		try
		{
			if (GTExt.IsNull(rigContainer) || GTExt.IsNull(playerVRRig))
			{
				playerNameVisible = NormalizeName(linePlayer.NickName != currentNickname, linePlayer.NickName);
				currentNickname = linePlayer.NickName;
			}
			else if (rigContainer.Initialized)
			{
				playerNameVisible = playerVRRig.playerNameVisible;
			}
			else if (currentNickname.IsNullOrEmpty() || GorillaComputer.instance.friendJoinCollider.playerIDsCurrentlyTouching.Contains(linePlayer.UserId))
			{
				playerNameVisible = NormalizeName(linePlayer.NickName != currentNickname, linePlayer.NickName);
			}
			bool flag = KIDManager.HasPermissionToUseFeature(EKIDFeatures.Custom_Nametags);
			currentNickname = linePlayer.NickName;
			playerName.text = (flag ? playerNameVisible : linePlayer.DefaultName);
		}
		catch (Exception)
		{
			playerNameVisible = linePlayer.DefaultName;
			MonkeAgent.instance.SendReport("NmError", linePlayer.UserId, linePlayer.NickName);
		}
	}

	public void PressButton(bool isOn, GorillaPlayerLineButton.ButtonType buttonType)
	{
		switch (buttonType)
		{
		case GorillaPlayerLineButton.ButtonType.Mute:
			if (linePlayer != null && playerVRRig != null)
			{
				isMuteManual = true;
				muteButton.isAutoOn = false;
				mute = (isOn ? 1 : 0);
				PlayerPrefs.SetInt(linePlayer.UserId, mute);
				if (rigContainer != null)
				{
					rigContainer.hasManualMute = isMuteManual;
					rigContainer.Muted = ((mute != 0) ? true : false);
				}
				PlayerPrefs.Save();
				muteButton.UpdateColor();
				GorillaScoreboardTotalUpdater.ReportMute(linePlayer, mute);
			}
			break;
		case GorillaPlayerLineButton.ButtonType.Report:
			SetReportState(reportState: true, buttonType);
			break;
		default:
			SetReportState(reportState: false, buttonType);
			break;
		}
	}

	public void SetReportState(bool reportState, GorillaPlayerLineButton.ButtonType buttonType)
	{
		canPressNextReportButton = buttonType != GorillaPlayerLineButton.ButtonType.Toxicity && buttonType != GorillaPlayerLineButton.ButtonType.Report;
		reportInProgress = reportState;
		if (reportState)
		{
			SwapToReportState(reportInProgress: true);
		}
		else
		{
			SwapToReportState(reportInProgress: false);
			if (linePlayer != null && buttonType != GorillaPlayerLineButton.ButtonType.Cancel)
			{
				if ((!reportedHateSpeech && buttonType == GorillaPlayerLineButton.ButtonType.HateSpeech) || (!reportedToxicity && buttonType == GorillaPlayerLineButton.ButtonType.Toxicity) || (!reportedCheating && buttonType == GorillaPlayerLineButton.ButtonType.Cheating))
				{
					ReportPlayer(linePlayer.UserId, buttonType, playerNameVisible);
					doneReporting = true;
				}
				reportedCheating = reportedCheating || buttonType == GorillaPlayerLineButton.ButtonType.Cheating;
				reportedToxicity = reportedToxicity || buttonType == GorillaPlayerLineButton.ButtonType.Toxicity;
				reportedHateSpeech = reportedHateSpeech || buttonType == GorillaPlayerLineButton.ButtonType.HateSpeech;
				reportButton.isOn = true;
				reportButton.UpdateColor();
			}
		}
		if (GorillaScoreboardTotalUpdater.instance != null)
		{
			GorillaScoreboardTotalUpdater.instance.UpdateLineState(this);
		}
		parentScoreboard.RedrawPlayerLines();
	}

	public static void ReportPlayer(string PlayerID, GorillaPlayerLineButton.ButtonType buttonType, string OtherPlayerNickName)
	{
		if (OtherPlayerNickName.Length > 12)
		{
			OtherPlayerNickName.Remove(12);
		}
		WebFlags flags = new WebFlags(3);
		NetEventOptions options = new NetEventOptions
		{
			Flags = flags,
			TargetActors = targetActors
		};
		byte code = 50;
		object[] data = new object[6]
		{
			PlayerID,
			buttonType,
			OtherPlayerNickName,
			NetworkSystem.Instance.LocalPlayer.NickName,
			!NetworkSystem.Instance.SessionIsPrivate,
			NetworkSystem.Instance.RoomStringStripped()
		};
		NetworkSystemRaiseEvent.RaiseEvent(code, data, options, reliable: true);
	}

	public string NormalizeName(bool doIt, string text)
	{
		if (doIt)
		{
			int length = text.Length;
			text = new string(Array.FindAll(text.ToCharArray(), (char c) => Utils.IsASCIILetterOrDigit(c)));
			int length2 = text.Length;
			if (length2 > 0 && length == length2 && GorillaComputer.instance.CheckAutoBanListForName(text))
			{
				if (text.Length > 12)
				{
					text = text.Substring(0, 12);
				}
				text = text.ToUpper();
			}
			else
			{
				text = "BADGORILLA";
				MonkeAgent.instance.SendReport("evading the name ban", linePlayer.UserId, linePlayer.NickName);
			}
		}
		return text;
	}

	public void ResetData()
	{
		emptyRigCount = 0;
		playerActorNumber = -1;
		linePlayer = null;
		playerNameValue = string.Empty;
		currentNickname = string.Empty;
	}

	private void OnEnable()
	{
		GorillaScoreboardTotalUpdater.RegisterSL(this);
	}

	private void OnDisable()
	{
		GorillaScoreboardTotalUpdater.UnregisterSL(this);
	}

	private void SwapToReportState(bool reportInProgress)
	{
		reportButton.gameObject.SetActive(!reportInProgress);
		hateSpeechButton.SetActive(reportInProgress);
		toxicityButton.SetActive(reportInProgress);
		cheatingButton.SetActive(reportInProgress);
		cancelButton.SetActive(reportInProgress);
	}
}
public class GorillaPressableButton : MonoBehaviour, IClickable
{
	public Material pressedMaterial;

	public Material unpressedMaterial;

	public MeshRenderer buttonRenderer;

	public int pressButtonSoundIndex = 67;

	public bool isOn;

	public float debounceTime = 0.25f;

	public float touchTime;

	public bool testPress;

	public bool testHandLeft;

	[SerializeField]
	private bool _useOnOffText = true;

	[TextArea]
	public string offText;

	[SerializeField]
	private LocalizedString _offLocalizedText;

	[TextArea]
	public string onText;

	[SerializeField]
	private LocalizedString _onLocalizedText;

	[SerializeField]
	[Tooltip("Use this one when you can. Don't use MyText if you can help it!")]
	public TMP_Text myTmpText;

	[SerializeField]
	[Tooltip("Use this one when you can. Don't use MyText if you can help it!")]
	public TMP_Text myTmpText2;

	public Text myText;

	public bool isSubscriberOnlyButton;

	public Material nonSubscriberMaterial;

	private bool _localPlayerSubscribed;

	private bool _subscriptionChecked;

	[Space]
	public UnityEvent onPressButton;

	protected bool _myTxtSet;

	protected bool _myTmpTxtSet;

	protected bool _myTmpTxt2Set;

	public event Action<GorillaPressableButton, bool> onPressed;

	public virtual void Start()
	{
	}

	protected virtual void OnEnable()
	{
		LocalisationManager.RegisterOnLanguageChanged(RefreshText);
		if (isSubscriberOnlyButton)
		{
			SubscriptionManager.OnLocalSubscriptionData = (Action)Delegate.Combine(SubscriptionManager.OnLocalSubscriptionData, new Action(CheckSubscription));
			CheckSubscription();
		}
		RefreshText();
	}

	protected virtual void OnDisable()
	{
		LocalisationManager.UnregisterOnLanguageChanged(RefreshText);
		if (isSubscriberOnlyButton)
		{
			SubscriptionManager.OnLocalSubscriptionData = (Action)Delegate.Remove(SubscriptionManager.OnLocalSubscriptionData, new Action(CheckSubscription));
		}
	}

	private void CheckSubscription()
	{
		bool flag = SubscriptionManager.IsLocalSubscribed();
		if (!_subscriptionChecked || flag != _localPlayerSubscribed)
		{
			UpdateSubscriptionState(flag);
		}
	}

	private void UpdateSubscriptionState(bool subscribed)
	{
		_localPlayerSubscribed = subscribed;
		UpdateColor();
		_subscriptionChecked = true;
	}

	protected virtual void RefreshText()
	{
		if (_offLocalizedText == null || _offLocalizedText.IsEmpty || _onLocalizedText == null || _onLocalizedText.IsEmpty || !_useOnOffText)
		{
			return;
		}
		string text = "";
		if (!isOn)
		{
			text = offText;
			text = _offLocalizedText.GetLocalizedString();
			if (string.IsNullOrEmpty(text))
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::GORILLA_PRESSABLE_BUTTON] Null or empty string returned for OFF localized text", this);
				text = offText;
			}
		}
		else
		{
			text = onText;
			text = _onLocalizedText.GetLocalizedString();
			if (string.IsNullOrEmpty(text))
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::GORILLA_PRESSABLE_BUTTON] Null or empty string returned for ON localized text", this);
				text = onText;
			}
		}
		if (_myTxtSet || myText.IsNotNull())
		{
			myText.text = text;
		}
		if (_myTmpTxtSet || myTmpText.IsNotNull())
		{
			myTmpText.text = text;
		}
		if (_myTmpTxt2Set || myTmpText2.IsNotNull())
		{
			myTmpText2.text = text;
		}
	}

	protected virtual void SetOffText(bool setMyText, bool setMyTmpText = false, bool setMyTmpText2 = false)
	{
		if (!_useOnOffText)
		{
			return;
		}
		string localizedString = offText;
		if (_offLocalizedText != null && !_offLocalizedText.IsEmpty)
		{
			localizedString = _offLocalizedText.GetLocalizedString();
			if (string.IsNullOrEmpty(localizedString))
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::GORILLA_PRESSABLE_BUTTON] Null or empty string returned for OFF localized text", this);
				localizedString = offText;
			}
		}
		_myTxtSet = setMyText;
		_myTmpTxtSet = setMyTmpText;
		_myTmpTxt2Set = setMyTmpText2;
		if (setMyText)
		{
			myText.text = localizedString;
		}
		if (setMyTmpText)
		{
			myTmpText.text = localizedString;
		}
		if (setMyTmpText2)
		{
			myTmpText2.text = localizedString;
		}
	}

	protected virtual void SetOnText(bool setMyText, bool setMyTmpText = false, bool setMyTmpText2 = false)
	{
		if (!_useOnOffText)
		{
			return;
		}
		string localizedString = onText;
		if (_onLocalizedText != null && !_onLocalizedText.IsEmpty)
		{
			localizedString = _onLocalizedText.GetLocalizedString();
			if (string.IsNullOrEmpty(localizedString))
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::GORILLA_PRESSABLE_BUTTON] Null or empty string returned for ON localized text", this);
				localizedString = onText;
			}
		}
		_myTxtSet = setMyText;
		_myTmpTxtSet = setMyTmpText;
		_myTmpTxt2Set = setMyTmpText2;
		if (setMyText)
		{
			myText.text = localizedString;
		}
		if (setMyTmpText)
		{
			myTmpText.text = localizedString;
		}
		if (setMyTmpText2)
		{
			myTmpText2.text = localizedString;
		}
	}

	protected void OnTriggerEnter(Collider collider)
	{
		if (base.enabled && touchTime + debounceTime < Time.time)
		{
			GorillaTriggerColliderHandIndicator component = collider.gameObject.GetComponent<GorillaTriggerColliderHandIndicator>();
			if ((bool)component)
			{
				PressButton(component.isLeftHand);
			}
		}
	}

	private void PressButton(bool isLeftHand)
	{
		if (!isSubscriberOnlyButton || _localPlayerSubscribed)
		{
			touchTime = Time.time;
			onPressButton?.Invoke();
			this.onPressed?.Invoke(this, isLeftHand);
			ButtonActivation();
			ButtonActivationWithHand(isLeftHand);
			GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(pressButtonSoundIndex, isLeftHand, 0.05f);
			GorillaTagger.Instance.StartVibration(isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
			{
				GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, isLeftHand, 0.05f);
			}
		}
	}

	public void Click(bool leftHand = false)
	{
		PressButton(leftHand);
	}

	public virtual void UpdateColor()
	{
		UpdateColorWithState(isOn);
	}

	protected void UpdateColorWithState(bool state)
	{
		if (isSubscriberOnlyButton && !_localPlayerSubscribed)
		{
			SetUnsubscribedMaterial();
			SetOffText(myText.IsNotNull(), myTmpText.IsNotNull(), myTmpText2.IsNotNull());
		}
		else if (state)
		{
			SetPressedMaterial();
			SetOnText(myText.IsNotNull(), myTmpText.IsNotNull(), myTmpText2.IsNotNull());
		}
		else
		{
			SetUnpressedMaterial();
			SetOffText(myText.IsNotNull(), myTmpText.IsNotNull(), myTmpText2.IsNotNull());
		}
	}

	public void SetRendererMaterial(Material mat)
	{
		if ((bool)buttonRenderer)
		{
			buttonRenderer.material = mat;
		}
	}

	public void SetPressedMaterial()
	{
		SetRendererMaterial(pressedMaterial);
	}

	public void SetUnpressedMaterial()
	{
		SetRendererMaterial(unpressedMaterial);
	}

	public void SetUnsubscribedMaterial()
	{
		SetRendererMaterial(nonSubscriberMaterial ? nonSubscriberMaterial : unpressedMaterial);
	}

	public virtual void ButtonActivation()
	{
	}

	public virtual void ButtonActivationWithHand(bool isLeftHand)
	{
	}

	public virtual void ResetState()
	{
		isOn = false;
		UpdateColor();
	}

	public void SetText(string newText)
	{
		if (myTmpText != null)
		{
			myTmpText.text = newText;
		}
		if (myTmpText2 != null)
		{
			myTmpText2.text = newText;
		}
		if (myText != null)
		{
			myText.text = newText;
		}
	}
}
public class GorillaPressableReleaseButton : GorillaPressableButton
{
	public UnityEvent onReleaseButton;

	private Collider touchingCollider;

	private new void OnTriggerEnter(Collider other)
	{
		if (!base.enabled || !(touchTime + debounceTime < Time.time) || (bool)touchingCollider)
		{
			return;
		}
		GorillaTriggerColliderHandIndicator component = other.GetComponent<GorillaTriggerColliderHandIndicator>();
		if (!(component == null))
		{
			touchTime = Time.time;
			touchingCollider = other;
			onPressButton?.Invoke();
			ButtonActivation();
			ButtonActivationWithHand(component.isLeftHand);
			GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(pressButtonSoundIndex, component.isLeftHand, 0.05f);
			GorillaTagger.Instance.StartVibration(component.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
			{
				GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, component.isLeftHand, 0.05f);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (!base.enabled || other != touchingCollider)
		{
			return;
		}
		touchingCollider = null;
		GorillaTriggerColliderHandIndicator component = other.GetComponent<GorillaTriggerColliderHandIndicator>();
		if (!(component == null))
		{
			onReleaseButton?.Invoke();
			ButtonDeactivation();
			ButtonDeactivationWithHand(component.isLeftHand);
			GorillaTagger.Instance.offlineVRRig.PlayHandTapLocal(pressButtonSoundIndex, component.isLeftHand, 0.05f);
			GorillaTagger.Instance.StartVibration(component.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			if (NetworkSystem.Instance.InRoom && GorillaTagger.Instance.myVRRig != null)
			{
				GorillaTagger.Instance.myVRRig.SendRPC("RPC_PlayHandTap", RpcTarget.Others, 67, component.isLeftHand, 0.05f);
			}
		}
	}

	public override void ResetState()
	{
		base.ResetState();
		touchingCollider = null;
	}

	public virtual void ButtonDeactivation()
	{
	}

	public virtual void ButtonDeactivationWithHand(bool isLeftHand)
	{
	}
}
public class GorillaScoreboardSpawner : MonoBehaviour
{
	public string gameType;

	public bool includeMMR;

	public GameObject scoreboardPrefab;

	public GameObject notInRoomText;

	public GameObject controllingParentGameObject;

	public bool isActive = true;

	public GorillaScoreBoard currentScoreboard;

	public bool lastVisible;

	public bool forOverlay;

	public void Awake()
	{
		StartCoroutine(UpdateBoard());
	}

	private void Start()
	{
		RoomSystem.JoinedRoomEvent += new Action(OnJoinedRoom);
		RoomSystem.LeftRoomEvent += new Action(OnLeftRoom);
	}

	public bool IsCurrentScoreboard()
	{
		return base.gameObject.activeInHierarchy;
	}

	public void OnJoinedRoom()
	{
		UnityEngine.Debug.Log("SCOREBOARD JOIN ROOM");
		if (IsCurrentScoreboard())
		{
			notInRoomText.SetActive(value: false);
			currentScoreboard = UnityEngine.Object.Instantiate(scoreboardPrefab, base.transform).GetComponent<GorillaScoreBoard>();
			currentScoreboard.transform.rotation = base.transform.rotation;
			if (includeMMR)
			{
				currentScoreboard.GetComponent<GorillaScoreBoard>().includeMMR = true;
				currentScoreboard.GetComponent<Text>().text = "Player                     Color         Level        MMR";
			}
		}
	}

	public bool IsVisible()
	{
		if (!forOverlay)
		{
			return controllingParentGameObject.activeSelf;
		}
		return GTPlayer.Instance.inOverlay;
	}

	private IEnumerator UpdateBoard()
	{
		while (true)
		{
			try
			{
				if (currentScoreboard != null)
				{
					bool flag = IsVisible();
					foreach (GorillaPlayerScoreboardLine line in currentScoreboard.lines)
					{
						if (flag != line.lastVisible)
						{
							line.lastVisible = flag;
						}
					}
					if (currentScoreboard.boardText.enabled != flag)
					{
						currentScoreboard.boardText.enabled = flag;
					}
					if (currentScoreboard.buttonText.enabled != flag)
					{
						currentScoreboard.buttonText.enabled = flag;
					}
				}
			}
			catch
			{
			}
			yield return new WaitForSeconds(1f);
		}
	}

	public void OnLeftRoom()
	{
		Cleanup();
		if ((bool)notInRoomText)
		{
			notInRoomText.SetActive(value: true);
		}
	}

	public void Cleanup()
	{
		if (currentScoreboard != null)
		{
			UnityEngine.Object.Destroy(currentScoreboard.gameObject);
			currentScoreboard = null;
		}
	}
}
public class GorillaScoreboardTotalUpdater : MonoBehaviour, IGorillaSliceableSimple
{
	public struct PlayerReports
	{
		public bool cheating;

		public bool toxicity;

		public bool hateSpeech;

		public bool pressedReport;

		public PlayerReports(PlayerReports reportToUpdate, GorillaPlayerScoreboardLine lineToUpdate)
		{
			cheating = reportToUpdate.cheating || lineToUpdate.reportedCheating;
			toxicity = reportToUpdate.toxicity || lineToUpdate.reportedToxicity;
			hateSpeech = reportToUpdate.hateSpeech || lineToUpdate.reportedHateSpeech;
			pressedReport = lineToUpdate.reportInProgress;
		}

		public PlayerReports(GorillaPlayerScoreboardLine lineToUpdate)
		{
			cheating = lineToUpdate.reportedCheating;
			toxicity = lineToUpdate.reportedToxicity;
			hateSpeech = lineToUpdate.reportedHateSpeech;
			pressedReport = lineToUpdate.reportInProgress;
		}
	}

	public static GorillaScoreboardTotalUpdater instance;

	[OnEnterPlay_Set(false)]
	public static bool hasInstance = false;

	public static List<GorillaPlayerScoreboardLine> allScoreboardLines = new List<GorillaPlayerScoreboardLine>();

	public static int lineIndex = 0;

	private static int linesPerFrame = 2;

	public static List<GorillaScoreBoard> allScoreboards = new List<GorillaScoreBoard>();

	public static int boardIndex = 0;

	private List<NetPlayer> playersInRoom = new List<NetPlayer>();

	private bool joinedRoom;

	private bool wasGameManagerNull;

	public bool forOverlay;

	public string offlineTextErrorString;

	public Dictionary<int, PlayerReports> reportDict = new Dictionary<int, PlayerReports>();

	private static readonly Dictionary<int, ReportMuteTimer> m_reportMuteTimerDict = new Dictionary<int, ReportMuteTimer>(20);

	private static readonly GorillaTag.ObjectPool<ReportMuteTimer> m_reportMuteTimerPool = new GorillaTag.ObjectPool<ReportMuteTimer>(20);

	public void UpdateLineState(GorillaPlayerScoreboardLine line)
	{
		if (line.playerActorNumber != -1)
		{
			if (reportDict.ContainsKey(line.playerActorNumber))
			{
				reportDict[line.playerActorNumber] = new PlayerReports(reportDict[line.playerActorNumber], line);
			}
			else
			{
				reportDict.Add(line.playerActorNumber, new PlayerReports(line));
			}
		}
	}

	protected void Awake()
	{
		if (hasInstance && instance != this)
		{
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			SetInstance(this);
		}
	}

	private void Start()
	{
		RoomSystem.JoinedRoomEvent += new Action(JoinedRoom);
		RoomSystem.LeftRoomEvent += new Action(OnLeftRoom);
		RoomSystem.PlayerJoinedEvent += new Action<NetPlayer>(OnPlayerEnteredRoom);
		RoomSystem.PlayerLeftEvent += new Action<NetPlayer>(OnPlayerLeftRoom);
	}

	public static void CreateManager()
	{
		SetInstance(new GameObject("GorillaScoreboardTotalUpdater").AddComponent<GorillaScoreboardTotalUpdater>());
	}

	private static void SetInstance(GorillaScoreboardTotalUpdater manager)
	{
		instance = manager;
		hasInstance = true;
		if (UnityEngine.Application.isPlaying)
		{
			UnityEngine.Object.DontDestroyOnLoad(manager);
		}
	}

	public static void RegisterSL(GorillaPlayerScoreboardLine sL)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (!allScoreboardLines.Contains(sL))
		{
			allScoreboardLines.Add(sL);
		}
	}

	public static void UnregisterSL(GorillaPlayerScoreboardLine sL)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (allScoreboardLines.Contains(sL))
		{
			allScoreboardLines.Remove(sL);
		}
	}

	public static void RegisterScoreboard(GorillaScoreBoard sB)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (!allScoreboards.Contains(sB))
		{
			allScoreboards.Add(sB);
			instance.UpdateScoreboard(sB);
		}
	}

	public static void UnregisterScoreboard(GorillaScoreBoard sB)
	{
		if (!hasInstance)
		{
			CreateManager();
		}
		if (allScoreboards.Contains(sB))
		{
			allScoreboards.Remove(sB);
		}
	}

	public void UpdateActiveScoreboards()
	{
		for (int i = 0; i < allScoreboards.Count; i++)
		{
			UpdateScoreboard(allScoreboards[i]);
		}
	}

	public void SetOfflineFailureText(string failureText)
	{
		offlineTextErrorString = failureText;
		UpdateActiveScoreboards();
	}

	public void ClearOfflineFailureText()
	{
		offlineTextErrorString = null;
		UpdateActiveScoreboards();
	}

	public void UpdateScoreboard(GorillaScoreBoard sB)
	{
		sB.SetSleepState(joinedRoom);
		if (GorillaComputer.instance == null)
		{
			return;
		}
		if (!joinedRoom)
		{
			if (sB.notInRoomText != null)
			{
				sB.notInRoomText.gameObject.SetActive(value: true);
				sB.notInRoomText.text = ((offlineTextErrorString != null) ? offlineTextErrorString : GorillaComputer.instance.offlineTextInitialString);
			}
			for (int i = 0; i < sB.lines.Count; i++)
			{
				sB.lines[i].ResetData();
			}
			return;
		}
		if (sB.notInRoomText != null)
		{
			sB.notInRoomText.gameObject.SetActive(value: false);
		}
		for (int j = 0; j < sB.lines.Count; j++)
		{
			GorillaPlayerScoreboardLine gorillaPlayerScoreboardLine = sB.lines[j];
			if (j < playersInRoom.Count)
			{
				gorillaPlayerScoreboardLine.gameObject.SetActive(value: true);
				gorillaPlayerScoreboardLine.SetLineData(playersInRoom[j]);
			}
			else
			{
				gorillaPlayerScoreboardLine.ResetData();
				gorillaPlayerScoreboardLine.gameObject.SetActive(value: false);
			}
		}
		sB.RedrawPlayerLines();
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void SliceUpdate()
	{
		if (allScoreboardLines.Count == 0)
		{
			return;
		}
		for (int i = 0; i < linesPerFrame; i++)
		{
			if (lineIndex >= allScoreboardLines.Count)
			{
				lineIndex = 0;
			}
			allScoreboardLines[lineIndex].UpdateLine();
			lineIndex++;
		}
		for (int j = 0; j < allScoreboards.Count; j++)
		{
			if (allScoreboards[j].IsDirty)
			{
				UpdateScoreboard(allScoreboards[j]);
			}
		}
	}

	private void OnPlayerEnteredRoom(NetPlayer netPlayer)
	{
		if (netPlayer == null)
		{
			UnityEngine.Debug.LogError("Null netplayer");
		}
		if (!playersInRoom.Contains(netPlayer))
		{
			playersInRoom.Add(netPlayer);
		}
		UpdateActiveScoreboards();
	}

	private void OnPlayerLeftRoom(NetPlayer netPlayer)
	{
		if (netPlayer == null)
		{
			UnityEngine.Debug.LogError("Null netplayer");
		}
		playersInRoom.Remove(netPlayer);
		UpdateActiveScoreboards();
		if (m_reportMuteTimerDict.TryGetValue(netPlayer.ActorNumber, out var value))
		{
			m_reportMuteTimerDict.Remove(netPlayer.ActorNumber);
			m_reportMuteTimerPool.Return(value);
		}
	}

	internal void JoinedRoom()
	{
		joinedRoom = true;
		NetPlayer[] allNetPlayers = NetworkSystem.Instance.AllNetPlayers;
		foreach (NetPlayer item in allNetPlayers)
		{
			playersInRoom.Add(item);
		}
		playersInRoom.Sort((NetPlayer x, NetPlayer y) => x.ActorNumber.CompareTo(y.ActorNumber));
		foreach (GorillaScoreBoard allScoreboard in allScoreboards)
		{
			UpdateScoreboard(allScoreboard);
		}
	}

	private void OnLeftRoom()
	{
		joinedRoom = false;
		playersInRoom.Clear();
		reportDict.Clear();
		foreach (GorillaScoreBoard allScoreboard in allScoreboards)
		{
			UpdateScoreboard(allScoreboard);
		}
		foreach (KeyValuePair<int, ReportMuteTimer> item in m_reportMuteTimerDict)
		{
			m_reportMuteTimerPool.Return(item.Value);
		}
		m_reportMuteTimerDict.Clear();
	}

	public static void ReportMute(NetPlayer player, int muted)
	{
		if (m_reportMuteTimerDict.TryGetValue(player.ActorNumber, out var value))
		{
			value.Muted = muted;
			if (!value.Running)
			{
				value.Start();
			}
		}
		else
		{
			value = m_reportMuteTimerPool.Take();
			value.SetReportData(player.UserId, player.NickName, muted);
			value.coolDown = 5f;
			value.Start();
			m_reportMuteTimerDict[player.ActorNumber] = value;
		}
	}
}
public class GorillaThrowableController : MonoBehaviour
{
	public Transform leftHandController;

	public Transform rightHandController;

	public bool leftHandIsGrabbing;

	public bool rightHandIsGrabbing;

	public GorillaThrowable leftHandGrabbedObject;

	public GorillaThrowable rightHandGrabbedObject;

	public float hoverVibrationStrength = 0.25f;

	public float hoverVibrationDuration = 0.05f;

	public float handRadius = 0.05f;

	private UnityEngine.XR.InputDevice rightDevice;

	private UnityEngine.XR.InputDevice leftDevice;

	private UnityEngine.XR.InputDevice inputDevice;

	private float triggerValue;

	private bool boolVar;

	private Collider[] colliders = new Collider[10];

	private Collider minCollider;

	private Collider returnCollider;

	private float magnitude;

	public bool testCanGrab;

	private int gorillaThrowableLayerMask;

	protected void Awake()
	{
		gorillaThrowableLayerMask = LayerMask.GetMask("GorillaThrowable");
	}

	private void LateUpdate()
	{
		if (testCanGrab)
		{
			testCanGrab = false;
			CanGrabAnObject(rightHandController, out returnCollider);
			UnityEngine.Debug.Log(returnCollider.gameObject, returnCollider.gameObject);
		}
		if (leftHandIsGrabbing)
		{
			if (CheckIfHandHasReleased(XRNode.LeftHand))
			{
				if (leftHandGrabbedObject != null)
				{
					leftHandGrabbedObject.ThrowThisThingo();
					leftHandGrabbedObject = null;
				}
				leftHandIsGrabbing = false;
			}
		}
		else if (CheckIfHandHasGrabbed(XRNode.LeftHand))
		{
			leftHandIsGrabbing = true;
			if (CanGrabAnObject(leftHandController, out returnCollider))
			{
				leftHandGrabbedObject = returnCollider.GetComponent<GorillaThrowable>();
				leftHandGrabbedObject.Grabbed(leftHandController);
			}
		}
		if (rightHandIsGrabbing)
		{
			if (CheckIfHandHasReleased(XRNode.RightHand))
			{
				if (rightHandGrabbedObject != null)
				{
					rightHandGrabbedObject.ThrowThisThingo();
					rightHandGrabbedObject = null;
				}
				rightHandIsGrabbing = false;
			}
		}
		else if (CheckIfHandHasGrabbed(XRNode.RightHand))
		{
			rightHandIsGrabbing = true;
			if (CanGrabAnObject(rightHandController, out returnCollider))
			{
				rightHandGrabbedObject = returnCollider.GetComponent<GorillaThrowable>();
				rightHandGrabbedObject.Grabbed(rightHandController);
			}
		}
	}

	private bool CheckIfHandHasReleased(XRNode node)
	{
		inputDevice = InputDevices.GetDeviceAtXRNode(node);
		triggerValue = ((node == XRNode.LeftHand) ? SteamVR_Actions.gorillaTag_LeftTriggerFloat.GetAxis(SteamVR_Input_Sources.LeftHand) : SteamVR_Actions.gorillaTag_RightTriggerFloat.GetAxis(SteamVR_Input_Sources.RightHand));
		if (triggerValue < 0.75f)
		{
			triggerValue = ((node == XRNode.LeftHand) ? SteamVR_Actions.gorillaTag_LeftGripFloat.GetAxis(SteamVR_Input_Sources.LeftHand) : SteamVR_Actions.gorillaTag_RightGripFloat.GetAxis(SteamVR_Input_Sources.RightHand));
			if (triggerValue < 0.75f)
			{
				return true;
			}
		}
		return false;
	}

	private bool CheckIfHandHasGrabbed(XRNode node)
	{
		inputDevice = InputDevices.GetDeviceAtXRNode(node);
		triggerValue = ((node == XRNode.LeftHand) ? SteamVR_Actions.gorillaTag_LeftTriggerFloat.GetAxis(SteamVR_Input_Sources.LeftHand) : SteamVR_Actions.gorillaTag_RightTriggerFloat.GetAxis(SteamVR_Input_Sources.RightHand));
		if (triggerValue > 0.75f)
		{
			return true;
		}
		triggerValue = ((node == XRNode.LeftHand) ? SteamVR_Actions.gorillaTag_LeftGripFloat.GetAxis(SteamVR_Input_Sources.LeftHand) : SteamVR_Actions.gorillaTag_RightGripFloat.GetAxis(SteamVR_Input_Sources.RightHand));
		if (triggerValue > 0.75f)
		{
			return true;
		}
		return false;
	}

	private bool CanGrabAnObject(Transform handTransform, out Collider returnCollider)
	{
		magnitude = 100f;
		returnCollider = null;
		UnityEngine.Debug.Log("trying:");
		if (Physics.OverlapSphereNonAlloc(handTransform.position, handRadius, colliders, gorillaThrowableLayerMask) > 0)
		{
			UnityEngine.Debug.Log("found something!");
			minCollider = colliders[0];
			Collider[] array = colliders;
			foreach (Collider collider in array)
			{
				if (collider != null)
				{
					UnityEngine.Debug.Log("found this", collider);
					if ((collider.transform.position - handTransform.position).magnitude < magnitude)
					{
						minCollider = collider;
						magnitude = (collider.transform.position - handTransform.position).magnitude;
					}
				}
			}
			returnCollider = minCollider;
			return true;
		}
		return false;
	}

	public void GrabbableObjectHover(bool isLeft)
	{
		GorillaTagger.Instance.StartVibration(isLeft, hoverVibrationStrength, hoverVibrationDuration);
	}
}
[Serializable]
public sealed class ComponentFunctionReference<TResult>
{
	[Serializable]
	private struct MethodRef(UnityEngine.Object obj, MethodInfo m)
	{
		public UnityEngine.Object component = obj;

		public string methodName = m.Name;
	}

	[SerializeField]
	private GameObject _target;

	[SerializeField]
	private MethodRef _selection;

	private Func<TResult> _cached;

	public bool IsValid
	{
		get
		{
			if (!_selection.component)
			{
				return !string.IsNullOrEmpty(_selection.methodName);
			}
			return true;
		}
	}

	private IEnumerable<ValueDropdownItem<MethodRef>> GetMethodOptions()
	{
		if (_target == null)
		{
			yield break;
		}
		yield return new ValueDropdownItem<MethodRef>("NONE", default(MethodRef));
		Type type = typeof(GameObject);
		BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
		MethodInfo[] methods = type.GetMethods(flags);
		foreach (MethodInfo methodInfo in methods)
		{
			if (methodInfo.GetParameters().Length == 0 && methodInfo.ReturnType == typeof(TResult))
			{
				string text = type.Name + "/" + methodInfo.Name;
				yield return new ValueDropdownItem<MethodRef>(text, new MethodRef(_target, methodInfo));
			}
		}
		UnityEngine.Component[] components = _target.GetComponents<UnityEngine.Component>();
		foreach (UnityEngine.Component comp in components)
		{
			type = comp.GetType();
			methods = type.GetMethods(flags);
			foreach (MethodInfo methodInfo2 in methods)
			{
				if (methodInfo2.GetParameters().Length == 0 && methodInfo2.ReturnType == typeof(TResult))
				{
					string text2 = type.Name + "/" + methodInfo2.Name;
					yield return new ValueDropdownItem<MethodRef>(text2, new MethodRef(comp, methodInfo2));
				}
			}
		}
	}

	public TResult Invoke()
	{
		if (_cached == null)
		{
			Cache();
		}
		if (_cached == null)
		{
			return default(TResult);
		}
		return _cached();
	}

	public void Cache()
	{
		_cached = null;
		if (!(_selection.component == null) && !string.IsNullOrEmpty(_selection.methodName))
		{
			MethodInfo method = _selection.component.GetType().GetMethod(_selection.methodName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic, null, Type.EmptyTypes, null);
			if (method != null)
			{
				_cached = (Func<TResult>)Delegate.CreateDelegate(typeof(Func<TResult>), _selection.component, method);
			}
		}
	}
}
