public class GorillaTurnSlider : MonoBehaviour
{
	public float zRange;

	public float maxValue;

	public float minValue;

	public GorillaTurning gorillaTurn;

	private float startingZ;

	public UnityEngine.Vector3 startingLocation;

	private void Awake()
	{
		startingLocation = base.transform.position;
		SetPosition(gorillaTurn.currentSpeed);
	}

	private void FixedUpdate()
	{
	}

	public void SetPosition(float speed)
	{
		float num = startingLocation.x - zRange / 2f;
		float num2 = startingLocation.x + zRange / 2f;
		float x = (speed - minValue) * (num2 - num) / (maxValue - minValue) + num;
		base.transform.position = new UnityEngine.Vector3(x, startingLocation.y, startingLocation.z);
	}

	public float InterpolateValue(float value)
	{
		float num = startingLocation.x - zRange / 2f;
		float num2 = startingLocation.x + zRange / 2f;
		return (value - num) / (num2 - num) * (maxValue - minValue) + minValue;
	}

	public void OnSliderRelease()
	{
		if (zRange != 0f && (base.transform.position - startingLocation).magnitude > zRange / 2f)
		{
			if (base.transform.position.x > startingLocation.x)
			{
				base.transform.position = new UnityEngine.Vector3(startingLocation.x + zRange / 2f, startingLocation.y, startingLocation.z);
			}
			else
			{
				base.transform.position = new UnityEngine.Vector3(startingLocation.x - zRange / 2f, startingLocation.y, startingLocation.z);
			}
		}
	}
}
public class PlayFabTitleDataTextDisplay : MonoBehaviour, IBuildValidation
{
	[SerializeField]
	private TextMeshPro textBox;

	[SerializeField]
	private Color newUpdateColor = Color.magenta;

	[SerializeField]
	private Color defaultTextColor = Color.white;

	[Tooltip("PlayFab Title Data key from where to pull display text")]
	[SerializeField]
	private string playfabKey;

	[Tooltip("Text to display when error occurs during fetch")]
	[TextArea(3, 5)]
	[SerializeField]
	private string fallbackText;

	[SerializeField]
	private LocalizedString _fallbackLocalizedText;

	private bool _hasRegisteredCallback;

	private string _cachedText = string.Empty;

	public string playFabKeyValue => playfabKey;

	private void Start()
	{
		if (textBox != null)
		{
			textBox.color = defaultTextColor;
		}
		else
		{
			UnityEngine.Debug.LogError("The TextBox is null on this PlayFabTitleDataTextDisplay component");
		}
		PlayFabTitleDataCache.Instance.OnTitleDataUpdate.AddListener(OnNewTitleDataAdded);
		PlayFabTitleDataCache.Instance.GetTitleData(playfabKey, OnTitleDataRequestComplete, OnPlayFabError);
		if (!_hasRegisteredCallback)
		{
			LocalisationManager.RegisterOnLanguageChanged(OnLanguageChanged);
		}
	}

	private void OnEnable()
	{
		if (!(LocalisationManager.Instance == null))
		{
			LocalisationManager.RegisterOnLanguageChanged(OnLanguageChanged);
			_hasRegisteredCallback = true;
		}
	}

	private void OnDisable()
	{
		LocalisationManager.UnregisterOnLanguageChanged(OnLanguageChanged);
		_hasRegisteredCallback = false;
	}

	private void OnPlayFabError(PlayFabError error)
	{
		if (!(textBox != null))
		{
			return;
		}
		UnityEngine.Debug.LogError("PlayFabTitleDataTextDisplay: PlayFab error retrieving title data for key '" + playfabKey + "' displayed '" + fallbackText + "': " + error.GenerateErrorReport());
		if (_fallbackLocalizedText == null || _fallbackLocalizedText.IsEmpty)
		{
			textBox.text = fallbackText;
			return;
		}
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(_fallbackLocalizedText, out var result, fallbackText))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::PLAYFAB_TITLEDATA_TEXT_DISPLAY] Failed to get key for PlayFab Title Data Text [_fallbackLocalizedText]");
		}
		textBox.text = result;
	}

	private void OnLanguageChanged()
	{
		if (string.IsNullOrEmpty(_cachedText))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::PLAY_FAB_TITLE_DATA_TEXT_DISPLAY] [_cachedText] is not set yet, is this being called before title data has been obtained?");
		}
		else
		{
			PlayFabTitleDataCache.Instance.GetTitleData(playfabKey, OnTitleDataRequestComplete, OnPlayFabError);
		}
	}

	private void OnTitleDataRequestComplete(string titleDataResult)
	{
		if (textBox != null)
		{
			_cachedText = titleDataResult;
			string text = titleDataResult.Replace("\\r", "\r").Replace("\\n", "\n");
			if (text[0] == '"' && text[text.Length - 1] == '"')
			{
				text = text.Substring(1, text.Length - 2);
			}
			textBox.text = text;
		}
	}

	private void OnNewTitleDataAdded(string key)
	{
		if (key == playfabKey && textBox != null)
		{
			textBox.color = newUpdateColor;
		}
	}

	private void OnDestroy()
	{
		PlayFabTitleDataCache.Instance.OnTitleDataUpdate.RemoveListener(OnNewTitleDataAdded);
	}

	public bool BuildValidationCheck()
	{
		if (textBox == null)
		{
			UnityEngine.Debug.LogError("text reference is null! sign text will be broken");
			return false;
		}
		return true;
	}

	public void ChangeTitleDataAtRuntime(string newTitleDataKey)
	{
		playfabKey = newTitleDataKey;
		if (textBox != null)
		{
			textBox.color = defaultTextColor;
		}
		else
		{
			UnityEngine.Debug.LogError("The TextBox is null on this PlayFabTitleDataTextDisplay component");
		}
		PlayFabTitleDataCache.Instance.OnTitleDataUpdate.AddListener(OnNewTitleDataAdded);
		PlayFabTitleDataCache.Instance.GetTitleData(playfabKey, OnTitleDataRequestComplete, OnPlayFabError);
	}
}
[RequireComponent(typeof(NavMeshAgent))]
[RequireComponent(typeof(Rigidbody))]
public class GorillaEnemyAI : MonoBehaviourPun, IPunObservable, IInRoomCallbacks
{
	public Transform playerTransform;

	private NavMeshAgent agent;

	private Rigidbody r;

	private UnityEngine.Vector3 targetPosition;

	private UnityEngine.Vector3 targetRotation;

	public float lerpValue;

	private void Start()
	{
		agent = GetComponent<NavMeshAgent>();
		r = GetComponent<Rigidbody>();
		r.useGravity = true;
		if (!base.photonView.IsMine)
		{
			agent.enabled = false;
			r.isKinematic = true;
		}
	}

	void IPunObservable.OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.IsWriting)
		{
			stream.SendNext(base.transform.position);
			stream.SendNext(base.transform.eulerAngles);
		}
		else
		{
			targetPosition.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
			targetRotation.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
		}
	}

	private void Update()
	{
		if (PhotonNetwork.IsMasterClient)
		{
			FindClosestPlayer();
			if (playerTransform != null)
			{
				agent.destination = playerTransform.position;
			}
			base.transform.LookAt(new UnityEngine.Vector3(playerTransform.transform.position.x, base.transform.position.y, playerTransform.position.z));
			r.linearVelocity *= 0.99f;
		}
		else
		{
			base.transform.position = UnityEngine.Vector3.Lerp(base.transform.position, targetPosition, lerpValue);
			base.transform.eulerAngles = UnityEngine.Vector3.Lerp(base.transform.eulerAngles, targetRotation, lerpValue);
		}
	}

	private void FindClosestPlayer()
	{
		VRRig[] array = UnityEngine.Object.FindObjectsByType<VRRig>(FindObjectsSortMode.None);
		VRRig vRRig = null;
		float num = 100000f;
		VRRig[] array2 = array;
		foreach (VRRig vRRig2 in array2)
		{
			UnityEngine.Vector3 vector = vRRig2.transform.position - base.transform.position;
			if (vector.magnitude < num)
			{
				vRRig = vRRig2;
				num = vector.magnitude;
			}
		}
		playerTransform = vRRig.transform;
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (collision.gameObject.layer == 19)
		{
			PhotonNetwork.Destroy(base.photonView);
		}
	}

	void IInRoomCallbacks.OnMasterClientSwitched(Player newMasterClient)
	{
		if (PhotonNetwork.IsMasterClient)
		{
			agent.enabled = true;
			r.isKinematic = false;
		}
	}

	void IInRoomCallbacks.OnPlayerEnteredRoom(Player newPlayer)
	{
	}

	void IInRoomCallbacks.OnPlayerLeftRoom(Player otherPlayer)
	{
	}

	void IInRoomCallbacks.OnRoomPropertiesUpdate(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
	}

	void IInRoomCallbacks.OnPlayerPropertiesUpdate(Player targetPlayer, ExitGames.Client.Photon.Hashtable changedProps)
	{
	}
}
