public class GorillaFireball : GorillaThrowable, IPunInstantiateMagicCallback
{
	public float maxExplosionScale;

	public float totalExplosionTime;

	public float gravityStrength;

	private bool canExplode;

	private float explosionStartTime;

	public override void Start()
	{
		base.Start();
		canExplode = false;
		explosionStartTime = 0f;
	}

	private void Update()
	{
		if (explosionStartTime != 0f)
		{
			float num = (Time.time - explosionStartTime) / totalExplosionTime * (maxExplosionScale - 0.25f) + 0.25f;
			base.gameObject.transform.localScale = new UnityEngine.Vector3(num, num, num);
			if (base.photonView.IsMine && Time.time > explosionStartTime + totalExplosionTime)
			{
				PhotonNetwork.Destroy(PhotonView.Get(this));
			}
		}
	}

	public override void LateUpdate()
	{
		base.LateUpdate();
		if (rigidbody.useGravity)
		{
			rigidbody.AddForce(Physics.gravity * (0f - gravityStrength) * rigidbody.mass);
		}
	}

	public override void ThrowThisThingo()
	{
		base.ThrowThisThingo();
		canExplode = true;
	}

	private new void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (base.photonView.IsMine && canExplode)
		{
			base.photonView.RPC("Explode", RpcTarget.All, null);
		}
	}

	public void LocalExplode()
	{
		rigidbody.isKinematic = true;
		canExplode = false;
		explosionStartTime = Time.time;
	}

	public void OnPhotonInstantiate(PhotonMessageInfo info)
	{
		if (base.photonView.IsMine)
		{
			if ((bool)base.photonView.InstantiationData[0])
			{
				base.transform.parent = GorillaPlaySpace.Instance.myVRRig.leftHandTransform;
			}
			else
			{
				base.transform.parent = GorillaPlaySpace.Instance.myVRRig.rightHandTransform;
			}
		}
	}

	public void Explode()
	{
		LocalExplode();
	}
}
public class GorillaFireballControllerManager : MonoBehaviour
{
	public UnityEngine.XR.InputDevice leftHand;

	public UnityEngine.XR.InputDevice rightHand;

	public bool hasInitialized;

	public float leftHandLastState;

	public float rightHandLastState;

	public float throwingThreshold = 0.9f;

	private void Update()
	{
		if (!hasInitialized)
		{
			hasInitialized = true;
			List<UnityEngine.XR.InputDevice> list = new List<UnityEngine.XR.InputDevice>();
			List<UnityEngine.XR.InputDevice> list2 = new List<UnityEngine.XR.InputDevice>();
			InputDevices.GetDevicesAtXRNode(XRNode.LeftHand, list);
			InputDevices.GetDevicesAtXRNode(XRNode.RightHand, list2);
			if (list.Count == 1)
			{
				leftHand = list[0];
			}
			if (list2.Count == 1)
			{
				rightHand = list2[0];
			}
		}
		float axis = SteamVR_Actions.gorillaTag_LeftTriggerFloat.GetAxis(SteamVR_Input_Sources.LeftHand);
		if (leftHandLastState <= throwingThreshold && axis > throwingThreshold)
		{
			CreateFireball(isLeftHand: true);
		}
		else if (leftHandLastState >= throwingThreshold && axis < throwingThreshold)
		{
			TryThrowFireball(isLeftHand: true);
		}
		leftHandLastState = axis;
		axis = SteamVR_Actions.gorillaTag_RightTriggerFloat.GetAxis(SteamVR_Input_Sources.RightHand);
		if (rightHandLastState <= throwingThreshold && axis > throwingThreshold)
		{
			CreateFireball(isLeftHand: false);
		}
		else if (rightHandLastState >= throwingThreshold && axis < throwingThreshold)
		{
			TryThrowFireball(isLeftHand: false);
		}
		rightHandLastState = axis;
	}

	public void TryThrowFireball(bool isLeftHand)
	{
		if (isLeftHand && GorillaPlaySpace.Instance.myVRRig.leftHandTransform.GetComponentInChildren<GorillaFireball>() != null)
		{
			GorillaPlaySpace.Instance.myVRRig.leftHandTransform.GetComponentInChildren<GorillaFireball>().ThrowThisThingo();
		}
		else if (!isLeftHand && GorillaPlaySpace.Instance.myVRRig.rightHandTransform.GetComponentInChildren<GorillaFireball>() != null)
		{
			GorillaPlaySpace.Instance.myVRRig.rightHandTransform.GetComponentInChildren<GorillaFireball>().ThrowThisThingo();
		}
	}

	public void CreateFireball(bool isLeftHand)
	{
		object[] array = new object[1];
		UnityEngine.Vector3 position;
		if (isLeftHand)
		{
			array[0] = true;
			position = GorillaPlaySpace.Instance.myVRRig.leftHandTransform.position;
		}
		else
		{
			array[0] = false;
			position = GorillaPlaySpace.Instance.myVRRig.rightHandTransform.position;
		}
		PhotonNetwork.Instantiate("GorillaPrefabs/GorillaFireball", position, UnityEngine.Quaternion.identity, 0, array);
	}
}
public class GorillaThrowable : MonoBehaviourPun, IPunObservable, IPhotonViewCallback
{
	public int trackingHistorySize;

	public float throwMultiplier;

	public float throwMagnitudeLimit;

	private UnityEngine.Vector3[] velocityHistory;

	private UnityEngine.Vector3[] headsetVelocityHistory;

	private UnityEngine.Vector3[] positionHistory;

	private UnityEngine.Vector3[] headsetPositionHistory;

	private UnityEngine.Vector3[] rotationHistory;

	private UnityEngine.Vector3[] rotationalVelocityHistory;

	private UnityEngine.Vector3 previousPosition;

	private UnityEngine.Vector3 previousRotation;

	private UnityEngine.Vector3 previousHeadsetPosition;

	private int currentIndex;

	private UnityEngine.Vector3 currentVelocity;

	private UnityEngine.Vector3 currentHeadsetVelocity;

	private UnityEngine.Vector3 currentRotationalVelocity;

	public UnityEngine.Vector3 denormalizedVelocityAverage;

	private UnityEngine.Vector3 denormalizedHeadsetVelocityAverage;

	private UnityEngine.Vector3 denormalizedRotationalVelocityAverage;

	private Transform headsetTransform;

	private UnityEngine.Vector3 targetPosition;

	private UnityEngine.Quaternion targetRotation;

	public bool initialLerp;

	public float lerpValue = 0.4f;

	public float lerpDistanceLimit = 0.01f;

	public bool isHeld;

	public Rigidbody rigidbody;

	private int loopIndex;

	private Transform transformToFollow;

	private UnityEngine.Vector3 offset;

	private UnityEngine.Quaternion offsetRotation;

	public AudioSource audioSource;

	public int timeLastReceived;

	public bool synchThrow;

	public float tempFloat;

	public Transform grabbingTransform;

	public float pickupLerp;

	public float minVelocity;

	public float maxVelocity;

	public float minVolume;

	public float maxVolume;

	public bool isLinear;

	public float linearMax;

	public float exponThrowMultMax;

	public int bounceAudioClip;

	public virtual void Start()
	{
		offset = UnityEngine.Vector3.zero;
		headsetTransform = GTPlayer.Instance.headCollider.transform;
		velocityHistory = new UnityEngine.Vector3[trackingHistorySize];
		positionHistory = new UnityEngine.Vector3[trackingHistorySize];
		headsetPositionHistory = new UnityEngine.Vector3[trackingHistorySize];
		rotationHistory = new UnityEngine.Vector3[trackingHistorySize];
		rotationalVelocityHistory = new UnityEngine.Vector3[trackingHistorySize];
		for (int i = 0; i < trackingHistorySize; i++)
		{
			velocityHistory[i] = UnityEngine.Vector3.zero;
			positionHistory[i] = base.transform.position - headsetTransform.position;
			headsetPositionHistory[i] = headsetTransform.position;
			rotationHistory[i] = base.transform.eulerAngles;
			rotationalVelocityHistory[i] = UnityEngine.Vector3.zero;
		}
		currentIndex = 0;
		rigidbody = GetComponentInChildren<Rigidbody>();
	}

	public virtual void LateUpdate()
	{
		if (isHeld && base.photonView.IsMine)
		{
			base.transform.rotation = transformToFollow.rotation * offsetRotation;
			if (!initialLerp && (base.transform.position - transformToFollow.position).magnitude > lerpDistanceLimit)
			{
				base.transform.position = UnityEngine.Vector3.Lerp(base.transform.position, transformToFollow.position + transformToFollow.rotation * offset, pickupLerp);
			}
			else
			{
				initialLerp = true;
				base.transform.position = transformToFollow.position + transformToFollow.rotation * offset;
			}
		}
		if (!base.photonView.IsMine)
		{
			rigidbody.isKinematic = true;
			base.transform.position = UnityEngine.Vector3.Lerp(base.transform.position, targetPosition, lerpValue);
			base.transform.rotation = UnityEngine.Quaternion.Lerp(base.transform.rotation, targetRotation, lerpValue);
		}
		StoreHistories();
	}

	private void IsHandPushing(XRNode node)
	{
	}

	private void StoreHistories()
	{
		previousPosition = positionHistory[currentIndex];
		previousRotation = rotationHistory[currentIndex];
		previousHeadsetPosition = headsetPositionHistory[currentIndex];
		currentIndex = (currentIndex + 1) % trackingHistorySize;
		currentVelocity = (base.transform.position - headsetTransform.position - previousPosition) / Time.deltaTime;
		currentHeadsetVelocity = (headsetTransform.position - previousHeadsetPosition) / Time.deltaTime;
		currentRotationalVelocity = (base.transform.eulerAngles - previousRotation) / Time.deltaTime;
		denormalizedVelocityAverage = UnityEngine.Vector3.zero;
		denormalizedRotationalVelocityAverage = UnityEngine.Vector3.zero;
		for (loopIndex = 0; loopIndex < trackingHistorySize; loopIndex++)
		{
			denormalizedVelocityAverage += velocityHistory[loopIndex];
			denormalizedRotationalVelocityAverage += rotationalVelocityHistory[loopIndex];
		}
		denormalizedVelocityAverage /= (float)trackingHistorySize;
		denormalizedRotationalVelocityAverage /= (float)trackingHistorySize;
		velocityHistory[currentIndex] = currentVelocity;
		positionHistory[currentIndex] = base.transform.position - headsetTransform.position;
		headsetPositionHistory[currentIndex] = headsetTransform.position;
		rotationHistory[currentIndex] = base.transform.eulerAngles;
		rotationalVelocityHistory[currentIndex] = currentRotationalVelocity;
	}

	public virtual void Grabbed(Transform grabTransform)
	{
		grabbingTransform = grabTransform;
		isHeld = true;
		transformToFollow = grabbingTransform;
		offsetRotation = base.transform.rotation * UnityEngine.Quaternion.Inverse(transformToFollow.rotation);
		initialLerp = false;
		rigidbody.isKinematic = true;
		rigidbody.useGravity = false;
		base.photonView.RequestOwnership();
	}

	public virtual void ThrowThisThingo()
	{
		transformToFollow = null;
		isHeld = false;
		synchThrow = true;
		rigidbody.interpolation = RigidbodyInterpolation.Interpolate;
		rigidbody.isKinematic = false;
		rigidbody.useGravity = true;
		if (isLinear || denormalizedVelocityAverage.magnitude < linearMax)
		{
			if (denormalizedVelocityAverage.magnitude * throwMultiplier < throwMagnitudeLimit)
			{
				rigidbody.linearVelocity = denormalizedVelocityAverage * throwMultiplier + currentHeadsetVelocity;
			}
			else
			{
				rigidbody.linearVelocity = denormalizedVelocityAverage.normalized * throwMagnitudeLimit + currentHeadsetVelocity;
			}
		}
		else
		{
			rigidbody.linearVelocity = denormalizedVelocityAverage.normalized * Mathf.Max(Mathf.Min(Mathf.Pow(throwMultiplier * denormalizedVelocityAverage.magnitude / linearMax, exponThrowMultMax), 0.1f) * denormalizedHeadsetVelocityAverage.magnitude, throwMagnitudeLimit) + currentHeadsetVelocity;
		}
		rigidbody.angularVelocity = denormalizedRotationalVelocityAverage * MathF.PI / 180f;
		rigidbody.MovePosition(rigidbody.transform.position + rigidbody.linearVelocity * Time.deltaTime);
	}

	void IPunObservable.OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.IsWriting)
		{
			stream.SendNext(base.transform.position);
			stream.SendNext(base.transform.rotation);
			stream.SendNext(rigidbody.linearVelocity);
		}
		else
		{
			targetPosition.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
			targetRotation.SetValueSafe((UnityEngine.Quaternion)stream.ReceiveNext());
			UnityEngine.Vector3 v = rigidbody.linearVelocity;
			v.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
			rigidbody.linearVelocity = v;
		}
	}

	public virtual void OnCollisionEnter(UnityEngine.Collision collision)
	{
		if (collision.collider.GetComponent<GorillaSurfaceOverride>() != null)
		{
			if (NetworkSystem.Instance.InRoom)
			{
				base.photonView.RPC("PlaySurfaceHit", RpcTarget.Others, bounceAudioClip, InterpolateVolume());
			}
			PlaySurfaceHit(collision.collider.GetComponent<GorillaSurfaceOverride>().overrideIndex, InterpolateVolume());
		}
	}

	public void PlaySurfaceHit(int soundIndex, float tapVolume)
	{
		if (soundIndex > -1 && soundIndex < GTPlayer.Instance.materialData.Count)
		{
			audioSource.volume = tapVolume;
			audioSource.clip = (GTPlayer.Instance.materialData[soundIndex].overrideAudio ? GTPlayer.Instance.materialData[soundIndex].audio : GTPlayer.Instance.materialData[0].audio);
			audioSource.GTPlayOneShot(audioSource.clip);
		}
	}

	public float InterpolateVolume()
	{
		return (Mathf.Clamp(rigidbody.linearVelocity.magnitude, minVelocity, maxVelocity) - minVelocity) / (maxVelocity - minVelocity) * (maxVolume - minVolume) + minVolume;
	}
}
