public class CustomMapsGorillaRopeSwing : GorillaRopeSwing
{
	[SerializeField]
	private GameObject partiallyUnderwaterPrefab;

	private bool isRopeLengthSet;

	private List<RopeSwingSegment> preExistingSegments;

	private GTObjectPlaceholder ropePlaceholder;

	private UnityEngine.Vector3 ropeScale = UnityEngine.Vector3.one;

	public bool snapX;

	public bool snapY;

	public bool snapZ;

	public float maxDistanceSnap = 0.05f;

	public AudioClip onGrabSFX;

	public AudioClip OnReleaseSFX;

	protected override void Awake()
	{
		CalculateId(force: true);
		StartCoroutine(WaitForRopeLength());
	}

	protected override void Start()
	{
	}

	protected override void OnEnable()
	{
		if (isRopeLengthSet)
		{
			base.OnEnable();
		}
	}

	public void SetRopeLength(int length)
	{
		ropeLength = length;
		isRopeLengthSet = true;
	}

	public void SetRopeProperties(GTObjectPlaceholder placeholder)
	{
		ropePlaceholder = placeholder;
		ropeLength = ropePlaceholder.ropeLength;
		ropeBitGenOffset = ropePlaceholder.ropeSegmentGenerationOffset;
		preExistingSegments = ropePlaceholder.ropeSwingSegments;
		ropeScale = ropePlaceholder.transform.localScale;
		base.transform.localScale = UnityEngine.Vector3.one;
		isRopeLengthSet = true;
	}

	private IEnumerator WaitForRopeLength()
	{
		while (!isRopeLengthSet)
		{
			yield return null;
		}
		RopeGeneration();
		base.Awake();
		base.OnEnable();
		base.Start();
	}

	private void RopeGeneration()
	{
		List<Transform> list = new List<Transform>();
		if (preExistingSegments != null && preExistingSegments.Count > 0)
		{
			for (int i = 0; i < preExistingSegments.Count; i++)
			{
				preExistingSegments[i].transform.SetParent(base.transform);
				GorillaClimbable gorillaClimbable = preExistingSegments[i].AddComponent<GorillaClimbable>();
				gorillaClimbable.snapX = snapX;
				gorillaClimbable.snapY = snapY;
				gorillaClimbable.snapZ = snapZ;
				gorillaClimbable.maxDistanceSnap = maxDistanceSnap;
				gorillaClimbable.clip = onGrabSFX;
				gorillaClimbable.clipOnFullRelease = OnReleaseSFX;
				GorillaRopeSegment gorillaRopeSegment = preExistingSegments[i].AddComponent<GorillaRopeSegment>();
				gorillaRopeSegment.swing = this;
				gorillaRopeSegment.boneIndex = preExistingSegments[i].boneIndex;
				list.Add(preExistingSegments[i].transform);
			}
			base.transform.localScale = ropeScale;
			ropePlaceholder.transform.localScale = UnityEngine.Vector3.one;
		}
		else
		{
			UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
			float y = prefabRopeBit.GetComponentInChildren<Renderer>().bounds.size.y;
			WaterVolume[] array = UnityEngine.Object.FindObjectsByType<WaterVolume>(FindObjectsSortMode.None);
			List<Collider> list2 = new List<Collider>(array.Length);
			WaterVolume[] array2 = array;
			for (int j = 0; j < array2.Length; j++)
			{
				foreach (Collider volumeCollider in array2[j].volumeColliders)
				{
					if (!(volumeCollider == null))
					{
						list2.Add(volumeCollider);
					}
				}
			}
			for (int k = 0; k < ropeLength + 1; k++)
			{
				bool flag = false;
				if (list2.Count > 0)
				{
					Collider collider = list2[0];
					if (collider != null)
					{
						UnityEngine.Vector3 vector = base.transform.position + zero;
						UnityEngine.Vector3 point = vector + new UnityEngine.Vector3(0f, 0f - y, 0f);
						flag = collider.bounds.Contains(vector) || collider.bounds.Contains(point);
					}
				}
				GameObject gameObject = UnityEngine.Object.Instantiate(flag ? partiallyUnderwaterPrefab : prefabRopeBit, base.transform);
				gameObject.name = $"RopeBone_{k:00}";
				gameObject.transform.localPosition = zero;
				gameObject.transform.localRotation = UnityEngine.Quaternion.identity;
				zero += new UnityEngine.Vector3(0f, 0f - ropeBitGenOffset, 0f);
				GorillaRopeSegment component = gameObject.GetComponent<GorillaRopeSegment>();
				component.swing = this;
				component.boneIndex = k;
				list.Add(gameObject.transform);
			}
			list[0].GetComponent<BoxCollider>().center = new UnityEngine.Vector3(0f, -0.65f, 0f);
			list[0].GetComponent<BoxCollider>().size = new UnityEngine.Vector3(0.3f, 0.65f, 0.3f);
		}
		if (list.Count > 0)
		{
			list.Last().gameObject.SetActive(value: false);
		}
		nodes = list.ToArray();
	}
}
public class CustomMapsGorillaZipline : GorillaZipline
{
	public bool GenerateZipline(CustomMapSupport.BezierSpline splineRef)
	{
		spline = GetComponent<BezierSpline>();
		if (GTExt.IsNull(spline))
		{
			return false;
		}
		spline.BuildSplineFromPoints(splineRef.GetControlPoints(), ConvertControlPointModes(splineRef.GetControlPointModes()), splineRef.Loop);
		if (segmentsRoot == null)
		{
			return false;
		}
		ziplineDistance = 0f;
		float t = 0f;
		int num = 0;
		Transform transform = null;
		while (t < 1f)
		{
			float num2 = segmentDistance;
			if (num == 0)
			{
				num2 /= 2f;
			}
			FindTFromDistance(ref t, num2, 5000);
			if (t < 1f || spline.Loop)
			{
				UnityEngine.Vector3 point = spline.GetPoint(t);
				GameObject gameObject = UnityEngine.Object.Instantiate(segmentPrefab);
				gameObject.transform.SetParent(segmentsRoot);
				gameObject.transform.position = point;
				gameObject.transform.LookAt(point + spline.GetDirection(t));
				gameObject.transform.position -= gameObject.transform.forward * 0.5f;
				if (num > 0)
				{
					transform.LookAt(gameObject.transform);
				}
				gameObject.GetComponent<GorillaClimbableRef>().climb = slideHelper;
				ziplineDistance += segmentDistance;
				transform = gameObject.transform;
			}
			num++;
		}
		return true;
	}

	protected override void OnBeforeClimb(GorillaHandClimber hand, GorillaClimbableRef climbRef)
	{
		slideHelper.gameObject.SetActive(value: true);
		base.OnBeforeClimb(hand, climbRef);
	}

	private BezierControlPointMode[] ConvertControlPointModes(CustomMapSupport.BezierControlPointMode[] refModes)
	{
		BezierControlPointMode[] array = new BezierControlPointMode[refModes.Length];
		for (int i = 0; i < refModes.Length; i++)
		{
			switch (refModes[i])
			{
			case CustomMapSupport.BezierControlPointMode.Free:
				array[i] = BezierControlPointMode.Free;
				break;
			case CustomMapSupport.BezierControlPointMode.Aligned:
				array[i] = BezierControlPointMode.Aligned;
				break;
			case CustomMapSupport.BezierControlPointMode.Mirrored:
				array[i] = BezierControlPointMode.Mirrored;
				break;
			}
		}
		return array;
	}

	protected override void Start()
	{
		GorillaClimbable gorillaClimbable = slideHelper;
		gorillaClimbable.onBeforeClimb = (Action<GorillaHandClimber, GorillaClimbableRef>)Delegate.Combine(gorillaClimbable.onBeforeClimb, new Action<GorillaHandClimber, GorillaClimbableRef>(OnBeforeClimb));
	}

	public void Init(GTObjectPlaceholder ziplinePlaceholder)
	{
		if (ziplinePlaceholder.PlaceholderObject == GTObject.ZipLine)
		{
			segmentDistance = ziplinePlaceholder.ziplineSegmentGenerationOffset;
			spline = base.gameObject.GetComponent<BezierSpline>();
			if (spline == null)
			{
				spline = base.gameObject.AddComponent<BezierSpline>();
			}
			spline.BuildSplineFromPoints(ziplinePlaceholder.spline.GetControlPoints(), ConvertControlPointModes(ziplinePlaceholder.spline.GetControlPointModes()), ziplinePlaceholder.spline.Loop);
			for (int i = 0; i < ziplinePlaceholder.ziplineSegments.Count; i++)
			{
				ziplinePlaceholder.ziplineSegments[i].transform.SetParent(segmentsRoot, worldPositionStays: true);
				ziplinePlaceholder.ziplineSegments[i].AddComponent<GorillaClimbableRef>().climb = slideHelper;
				ziplineDistance += segmentDistance;
			}
		}
	}
}
