	public static bool LoadedMapWantsHoldingHandsDisabled()
	{
		if (!IsMapLoaded())
		{
			return false;
		}
		if (disableHoldingHandsAllModes)
		{
			return true;
		}
		if (disableHoldingHandsCustomMode && GorillaGameManager.instance.IsNotNull() && GorillaGameManager.instance.GameType() == GameModeType.Custom)
		{
			return true;
		}
		return false;
	}

	bool IBuildValidation.BuildValidationCheck()
	{
		if (defaultNexusGroupId == null)
		{
			UnityEngine.Debug.LogError("You have to set defaultNexusGroupId in " + base.name + " or things will not work!");
			return false;
		}
		return true;
	}
}
public class CustomMapTelemetry : MonoBehaviour
{
	[OnEnterPlay_SetNull]
	private static volatile CustomMapTelemetry instance;

	private static string mapName;

	private static long mapModId;

	private static string mapCreatorUsername;

	private static bool metricsCaptureStarted;

	private static float mapEnterTime;

	private static int runningPlayerCount;

	private static int minPlayersInMap;

	private static int maxPlayersInMap;

	private static bool inPrivateRoom;

	private const int minimumPlaytimeForTracking = 30;

	private static int LowestFPS = int.MaxValue;

	private static int LowestFPSDrawCalls;

	private static int LowestFPSPlayerCount;

	private static int AverageFPS;

	private static int AverageDrawCalls;

	private static int AveragePlayerCount;

	private static int HighestFPS = int.MinValue;

	private static int HighestFPSDrawCalls;

	private static int HighestFPSPlayerCount;

	private static int totalFPS;

	private static int totalDrawCalls;

	private static int totalPlayerCount;

	private static int frameCounter;

	private Coroutine perfCaptureCoroutine;

	private static ProfilerRecorder drawCallsRecorder;

	private static bool perfCaptureStarted;

	public static bool IsActive
	{
		get
		{
			if (!metricsCaptureStarted)
			{
				return perfCaptureStarted;
			}
			return true;
		}
	}

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
		}
		else if (instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private static void OnPlayerJoinedRoom(NetPlayer obj)
	{
		runningPlayerCount++;
		maxPlayersInMap = System.Math.Max(runningPlayerCount, maxPlayersInMap);
	}

	private static void OnPlayerLeftRoom(NetPlayer obj)
	{
		runningPlayerCount--;
		minPlayersInMap = System.Math.Min(runningPlayerCount, minPlayersInMap);
	}

	public static void StartMapTracking()
	{
		if (!metricsCaptureStarted && !perfCaptureStarted)
		{
			mapEnterTime = Time.realtimeSinceStartup;
			float value = UnityEngine.Random.value;
			if (value <= 0.01f)
			{
				StartMetricsCapture();
			}
			else if (value >= 0.99f)
			{
				StartPerfCapture();
			}
			if (!metricsCaptureStarted)
			{
				_ = perfCaptureStarted;
			}
		}
	}

	public static void EndMapTracking()
	{
		EndMetricsCapture();
		EndPerfCapture();
		mapName = "NULL";
		mapCreatorUsername = "NULL";
		mapEnterTime = -1f;
		mapModId = 0L;
	}

	private static void StartMetricsCapture()
	{
		if (!metricsCaptureStarted)
		{
			metricsCaptureStarted = true;
			NetworkSystem.Instance.OnPlayerJoined -= new Action<NetPlayer>(OnPlayerJoinedRoom);
			NetworkSystem.Instance.OnPlayerJoined += new Action<NetPlayer>(OnPlayerJoinedRoom);
			NetworkSystem.Instance.OnPlayerLeft -= new Action<NetPlayer>(OnPlayerLeftRoom);
			NetworkSystem.Instance.OnPlayerLeft += new Action<NetPlayer>(OnPlayerLeftRoom);
			runningPlayerCount = NetworkSystem.Instance.RoomPlayerCount;
			minPlayersInMap = runningPlayerCount;
			maxPlayersInMap = runningPlayerCount;
		}
	}

	private static void EndMetricsCapture()
	{
		if (!metricsCaptureStarted)
		{
			return;
		}
		metricsCaptureStarted = false;
		NetworkSystem.Instance.OnPlayerJoined -= new Action<NetPlayer>(OnPlayerJoinedRoom);
		NetworkSystem.Instance.OnPlayerLeft -= new Action<NetPlayer>(OnPlayerLeftRoom);
		inPrivateRoom = NetworkSystem.Instance.InRoom && NetworkSystem.Instance.SessionIsPrivate;
		int num = Mathf.RoundToInt(Time.realtimeSinceStartup - mapEnterTime);
		if (num >= 30)
		{
			if (mapName.Equals("NULL") || mapModId == 0L)
			{
				UnityEngine.Debug.LogError("[CustomMapTelemetry::EndMetricsCapture] mapName or mapModID is invalid, throwing out this capture data...");
			}
			else
			{
				GorillaTelemetry.PostCustomMapTracking(mapName, mapModId, mapCreatorUsername, minPlayersInMap, maxPlayersInMap, num, inPrivateRoom);
			}
		}
	}

	private static void StartPerfCapture()
	{
		if (!perfCaptureStarted)
		{
			perfCaptureStarted = true;
			if (instance.perfCaptureCoroutine != null)
			{
				EndPerfCapture();
			}
			drawCallsRecorder = ProfilerRecorder.StartNew(ProfilerCategory.Render, "Draw Calls Count");
			LowestFPS = int.MaxValue;
			HighestFPS = int.MinValue;
			totalFPS = 0;
			totalDrawCalls = 0;
			totalPlayerCount = 0;
			frameCounter = 0;
			instance.perfCaptureCoroutine = instance.StartCoroutine(instance.CaptureMapPerformance());
		}
	}

	private static void EndPerfCapture()
	{
		if (!perfCaptureStarted)
		{
			return;
		}
		perfCaptureStarted = false;
		if (instance.perfCaptureCoroutine != null)
		{
			instance.StopAllCoroutines();
			instance.perfCaptureCoroutine = null;
		}
		drawCallsRecorder.Dispose();
		if (frameCounter == 0)
		{
			return;
		}
		int num = Mathf.RoundToInt(Time.realtimeSinceStartup - mapEnterTime);
		AverageFPS = totalFPS / frameCounter;
		AverageDrawCalls = totalDrawCalls / frameCounter;
		AveragePlayerCount = totalPlayerCount / frameCounter;
		if (num >= 30)
		{
			if (mapName.Equals("NULL") || mapModId == 0L)
			{
				UnityEngine.Debug.LogError("[CustomMapTelemetry::EndPerfCapture] mapName or mapModID is invalid, throwing out this capture data...");
			}
			else
			{
				GorillaTelemetry.PostCustomMapPerformance(mapName, mapModId, LowestFPS, LowestFPSDrawCalls, LowestFPSPlayerCount, AverageFPS, AverageDrawCalls, AveragePlayerCount, HighestFPS, HighestFPSDrawCalls, HighestFPSPlayerCount, num);
			}
		}
	}

	private IEnumerator CaptureMapPerformance()
	{
		while (true)
		{
			int num = Mathf.RoundToInt(1f / Time.unscaledDeltaTime);
			int num2 = Mathf.RoundToInt(drawCallsRecorder.LastValue);
			int roomPlayerCount = NetworkSystem.Instance.RoomPlayerCount;
			totalFPS += num;
			totalDrawCalls += num2;
			totalPlayerCount += roomPlayerCount;
			if (num > HighestFPS)
			{
				HighestFPS = num;
				HighestFPSDrawCalls = num2;
				HighestFPSPlayerCount = roomPlayerCount;
			}
			if (num < LowestFPS)
			{
				LowestFPS = num;
				LowestFPSDrawCalls = num2;
				LowestFPSPlayerCount = roomPlayerCount;
			}
			frameCounter++;
			yield return null;
		}
	}

	private void OnDestroy()
	{
		if (perfCaptureCoroutine != null)
		{
			EndMapTracking();
		}
	}
}
public class CustomMapTelemetryTrigger : MonoBehaviour
{
	public void OnTriggerEnter(Collider other)
	{
		if (other == GTPlayer.Instance.headCollider && CustomMapTelemetry.IsActive)
		{
			CustomMapTelemetry.EndMapTracking();
		}
	}

	public void OnTriggerExit(Collider other)
	{
		if (other == GTPlayer.Instance.headCollider && GorillaComputer.instance.IsPlayerInVirtualStump() && !CustomMapTelemetry.IsActive)
		{
			CustomMapTelemetry.StartMapTracking();
		}
	}
}
public class CustomMapsAttackBehaviour : CustomMapsBehaviourBase
{
	private enum State
	{
		Idle,
		Attacking
	}

	private CustomMapsAIBehaviourController controller;

	private State state;

	private AttackType attackType;

	private float attackDist;

	private float attackDistSq;

	private bool stopMovingToAttack;

	private bool useColliders;

	private float damageAmount;

	private UnityEngine.Vector3 sightOffset;

	private float sightFOV;

	private float sightMinDot;

	private string attackAnimName;

	private float timeBetweenAttacks;

	private float damageDelayAfterPlayingAnimation;

	private float animBlendTime;

	private float startTime;

	private float turnSpeed;

	private float lastAttackTime;

	public CustomMapsAttackBehaviour(CustomMapsAIBehaviourController AIController, AIAgent agentSettings)
	{
		attackType = agentSettings.attackType;
		attackDist = agentSettings.attackDist;
		attackDistSq = attackDist * attackDist;
		stopMovingToAttack = agentSettings.stopMovingToAttack;
		useColliders = agentSettings.useColliders;
		damageDelayAfterPlayingAnimation = agentSettings.damageDelayAfterPlayingAnim;
		damageAmount = agentSettings.damageAmount;
		attackAnimName = agentSettings.attackAnimName;
		sightOffset = agentSettings.sightOffset;
		sightFOV = agentSettings.sightFOV;
		sightMinDot = Mathf.Cos(sightFOV / 2f * (MathF.PI / 180f));
		controller = AIController;
		animBlendTime = agentSettings.animBlendTime;
		turnSpeed = agentSettings.turnSpeed * 10f;
		timeBetweenAttacks = agentSettings.timeBetweenAttacks;
		controller.attributes.AddAttribute(GRAttributeType.PlayerDamage, damageAmount);
		state = State.Idle;
	}

	public override bool CanExecute()
	{
		if (GTExt.IsNull(controller) || GTExt.IsNull(controller.TargetPlayer))
		{
			return false;
		}
		if (!IsTargetInAttackRange())
		{
			return false;
		}
		if (!IsTargetVisible())
		{
			return false;
		}
		return true;
	}

	private bool IsTargetVisible()
	{
		UnityEngine.Vector3 startPos = controller.transform.position + controller.transform.TransformVector(sightOffset);
		return controller.IsTargetVisible(startPos, controller.TargetPlayer, attackDist);
	}

	private bool IsTargetInAttackRange(GRPlayer target = null)
	{
		if (GTExt.IsNull(target) && GTExt.IsNull(controller.TargetPlayer))
		{
			return false;
		}
		UnityEngine.Vector3 toTarget;
		if (target.IsNotNull())
		{
			return controller.IsTargetInRange(controller.transform.position, target, attackDistSq, out toTarget);
		}
		UnityEngine.Vector3 toTarget2;
		return controller.IsTargetInRange(controller.transform.position, controller.TargetPlayer, attackDistSq, out toTarget2);
	}

	public override bool CanContinueExecuting()
	{
		if (state != State.Idle && controller.IsAnimationPlaying(attackAnimName))
		{
			return true;
		}
		if (GTExt.IsNull(controller) || GTExt.IsNull(controller.TargetPlayer))
		{
			return false;
		}
		if (!controller.IsTargetable(controller.TargetPlayer))
		{
			controller.ClearTarget();
			return false;
		}
		return CanExecute();
	}

	public override void Execute()
	{
		if (!GTExt.IsNull(controller))
		{
			if (stopMovingToAttack)
			{
				controller.StopMoving();
			}
			FaceTarget();
			controller.agent.RequestBehaviorChange(2);
		}
	}

	public override void NetExecute()
	{
		if (GTExt.IsNull(controller))
		{
			return;
		}
		if (state == State.Attacking && !useColliders && startTime > lastAttackTime && Time.time > startTime + damageDelayAfterPlayingAnimation)
		{
			TriggerAttack();
		}
		if (controller.IsAnimationPlaying(attackAnimName))
		{
			return;
		}
		switch (state)
		{
		case State.Attacking:
			if (Time.time < startTime + timeBetweenAttacks)
			{
				state = State.Idle;
				break;
			}
			startTime = Time.time;
			controller.PlayAnimation(attackAnimName, animBlendTime);
			break;
		case State.Idle:
			if (!(Time.time < startTime + timeBetweenAttacks))
			{
				startTime = Time.time;
				state = State.Attacking;
				controller.PlayAnimation(attackAnimName, animBlendTime);
			}
			break;
		}
	}

	public override void ResetBehavior()
	{
		state = State.Idle;
	}

	private void FaceTarget()
	{
		if (!GTExt.IsNull(controller.TargetPlayer))
		{
			GameAgent.UpdateFacingTarget(controller.transform, controller.agent.navAgent, controller.TargetPlayer.transform, turnSpeed);
		}
	}

	public override void OnTriggerEnter(Collider otherCollider)
	{
		if (useColliders && !(Time.time < lastAttackTime + timeBetweenAttacks) && state == State.Attacking)
		{
			GRPlayer componentInParent = otherCollider.GetComponentInParent<GRPlayer>();
			if (!GTExt.IsNull(componentInParent) && (!componentInParent.MyRig.IsNotNull() || componentInParent.MyRig.isLocal) && componentInParent.State != GRPlayer.GRPlayerState.Ghost)
			{
				TriggerAttack(componentInParent);
			}
		}
	}

	private void TriggerAttack(GRPlayer targetPlayer = null)
	{
		lastAttackTime = Time.time;
		GRPlayer gRPlayer = ((targetPlayer != null) ? targetPlayer : (controller.entity.IsAuthority() ? controller.TargetPlayer : null));
		if (!controller.entity.IsAuthority() && gRPlayer == null)
		{
			UnityEngine.Vector3 sourcePos = controller.transform.position + controller.transform.TransformVector(sightOffset);
			gRPlayer = controller.FindBestTarget(sourcePos, attackDist, attackDistSq, sightMinDot);
		}
		if (gRPlayer == null || !gRPlayer.MyRig.isLocal || (controller.entity.IsAuthority() && !IsTargetInAttackRange(gRPlayer)))
		{
			return;
		}
		switch (attackType)
		{
		case AttackType.Tag:
			if (GorillaGameModes.GameMode.ActiveGameMode.GameType() != GameModeType.Custom)
			{
				GorillaGameModes.GameMode.ReportHit();
			}
			else
			{
				CustomGameMode.TaggedByAI(controller.entity, gRPlayer.MyRig.OwningNetPlayer.ActorNumber);
			}
			break;
		case AttackType.UseGT:
			CustomMapsGameManager.instance.OnPlayerHit(controller.entity.id, gRPlayer, controller.transform.position);
			break;
		case AttackType.UseLuau:
			CustomGameMode.OnPlayerHit(controller.entity, gRPlayer.MyRig.OwningNetPlayer.ActorNumber, damageAmount);
			break;
		}
	}
}
public class CustomMapsChaseBehaviour : CustomMapsBehaviourBase
{
	private NavMeshAgent navMeshAgent;

	private CustomMapsAIBehaviourController controller;

	private float loseSightDist;

	private float loseSightDistSq;

	private UnityEngine.Vector3 sightOffset;

	private bool rememberLoseSightPos;

	private float stopDistSq;

	private bool isChasing;

	public CustomMapsChaseBehaviour(CustomMapsAIBehaviourController AIController, AIAgent agentSettings)
	{
		sightOffset = agentSettings.sightOffset;
		rememberLoseSightPos = agentSettings.rememberLoseSightPosition;
		loseSightDist = agentSettings.loseSightDist;
		loseSightDistSq = loseSightDist * loseSightDist;
		stopDistSq = agentSettings.stopDist * agentSettings.stopDist;
		controller = AIController;
	}

	public override bool CanExecute()
	{
		if (GTExt.IsNull(controller))
		{
			return false;
		}
		if (GTExt.IsNull(controller.TargetPlayer))
		{
			return false;
		}
		return true;
	}

	public override bool CanContinueExecuting()
	{
		if (!CanExecute())
		{
			return false;
		}
		if (IsTargetInChaseRange(out var withinStopDist))
		{
			if (withinStopDist)
			{
				return false;
			}
			return true;
		}
		if (!controller.IsTargetable(controller.TargetPlayer))
		{
			controller.StopMoving();
		}
		controller.ClearTarget();
		return false;
	}

	public override void Execute()
	{
		if (!IsTargetInChaseRange(out var withinStopDist))
		{
			controller.ClearTarget();
			isChasing = false;
			if (!rememberLoseSightPos)
			{
				controller.StopMoving();
			}
		}
		else if (!IsTargetVisible())
		{
			controller.ClearTarget();
			isChasing = false;
			if (!rememberLoseSightPos)
			{
				controller.StopMoving();
			}
		}
		else if (withinStopDist && isChasing)
		{
			isChasing = false;
			controller.StopMoving();
		}
		else
		{
			isChasing = true;
			controller.RequestDestination(controller.TargetPlayer.transform.position);
		}
	}

	private bool IsTargetVisible()
	{
		UnityEngine.Vector3 startPos = controller.transform.position + controller.transform.TransformVector(sightOffset);
		return controller.IsTargetVisible(startPos, controller.TargetPlayer, loseSightDist);
	}

	private bool IsTargetInChaseRange(out bool withinStopDist)
	{
		withinStopDist = false;
		if (!controller.IsTargetInRange(controller.transform.position, controller.TargetPlayer, loseSightDistSq, out var toTarget))
		{
			return false;
		}
		if (toTarget.sqrMagnitude < stopDistSq)
		{
			withinStopDist = true;
		}
		return true;
	}

	public override void NetExecute()
	{
	}

	public override void ResetBehavior()
	{
		isChasing = false;
	}

	public override void OnTriggerEnter(Collider otherCollider)
	{
	}
}
public class CustomMapsSearchBehaviour : CustomMapsBehaviourBase
{
	private const float SEARCH_COOLDOWN = 0.1f;

	private CustomMapsAIBehaviourController controller;

	private float sightDist;

	private float sightDistSq;

	private UnityEngine.Vector3 sightOffset;

	private float sightFOV;

	private float sightMinDot;

	private float lastSearchTime;

	public CustomMapsSearchBehaviour(CustomMapsAIBehaviourController AIcontroller, AIAgent agentSettings)
	{
		sightOffset = agentSettings.sightOffset;
		sightDist = agentSettings.sightDist;
		sightDistSq = sightDist * sightDist;
		sightFOV = agentSettings.sightFOV;
		sightMinDot = Mathf.Cos(sightFOV / 2f * (MathF.PI / 180f));
		controller = AIcontroller;
	}

	public override bool CanExecute()
	{
		if (GTExt.IsNull(controller))
		{
			return false;
		}
		return true;
	}

	public override bool CanContinueExecuting()
	{
		if (!CanExecute())
		{
			return false;
		}
		return controller.TargetPlayer == null;
	}

	public override void Execute()
	{
		if (!(Time.time < lastSearchTime + 0.1f))
		{
			lastSearchTime = Time.time;
			UnityEngine.Vector3 sourcePos = controller.transform.position + controller.transform.TransformVector(sightOffset);
			controller.SetTarget(controller.FindBestTarget(sourcePos, sightDist, sightDistSq, sightMinDot));
		}
	}

	public override void NetExecute()
	{
	}

	public override void ResetBehavior()
	{
	}

	public override void OnTriggerEnter(Collider otherCollider)
	{
	}
}
public class CustomMapsAIBehaviourController : MonoBehaviour, IGameEntityComponent
{
	public enum CustomMapsAIBehaviour
	{
		Search,
		Chase,
		Attack
	}

	private static readonly int movementSpeedParamIndex = Animator.StringToHash("MovementSpeed");

	public GameEntity entity;

	public GameAgent agent;

	public GRAttributes attributes;

	private Animator[] animators;

	public short luaAgentID;

	private List<VRRig> tempRigs = new List<VRRig>(20);

	private static RaycastHit[] visibilityHits = new RaycastHit[10];

	private LayerMask visibilityLayerMask;

	private bool allowTargetingTaggedPlayers;

	private Dictionary<AgentBehaviours, CustomMapsBehaviourBase> behaviourDict = new Dictionary<AgentBehaviours, CustomMapsBehaviourBase>(8);

	private List<AgentBehaviours> usedBehaviours = new List<AgentBehaviours>(8);

	private AgentBehaviours currentBehaviour;

	private int currentBehaviourIndex;

	private const int BEHAVIOUR_COUNT = 3;

	public GRPlayer TargetPlayer { get; private set; }

	private void Awake()
	{
		TargetPlayer = null;
		visibilityLayerMask = LayerMask.GetMask("Default", "Gorilla Object");
		agent.onBehaviorStateChanged += OnNetworkBehaviourStateChanged;
	}

	private void OnDestroy()
	{
		agent.onBehaviorStateChanged -= OnNetworkBehaviourStateChanged;
	}

	public void SetTarget(GRPlayer newTarget)
	{
		if (GTExt.IsNull(newTarget))
		{
			ClearTarget();
		}
		else
		{
			TargetPlayer = newTarget;
		}
	}

	public void ClearTarget()
	{
		TargetPlayer = null;
	}

	private void Update()
	{
		OnThink();
		UpdateAnimators();
	}

	private void OnTriggerEnter(Collider collider)
	{
		behaviourDict[currentBehaviour]?.OnTriggerEnter(collider);
	}

	private void InitAnimators()
	{
		animators = base.gameObject.GetComponentsInChildren<Animator>();
	}

	private void UpdateAnimators()
	{
		if (!animators.IsNullOrEmpty())
		{
			float magnitude = agent.navAgent.velocity.magnitude;
			for (int i = 0; i < animators.Length; i++)
			{
				animators[i].SetFloat(movementSpeedParamIndex, magnitude);
			}
		}
	}

	public void PlayAnimation(string stateName, float blendTime = 0f)
	{
		for (int i = 0; i < animators.Length; i++)
		{
			animators[i].CrossFadeInFixedTime(stateName, blendTime);
		}
	}

	public bool IsAnimationPlaying(string stateName)
	{
		int num = 0;
		if (num < animators.Length)
		{
			Animator animator = animators[num];
			AnimatorStateInfo currentAnimatorStateInfo = animator.GetCurrentAnimatorStateInfo(0);
			if (currentAnimatorStateInfo.IsName(stateName) && currentAnimatorStateInfo.normalizedTime < 1f)
			{
				return true;
			}
			if (animator.GetNextAnimatorStateInfo(0).IsName(stateName))
			{
				return true;
			}
			return false;
		}
		return false;
	}

	public void SetupBehaviours(AIAgent aiAgent)
	{
		allowTargetingTaggedPlayers = aiAgent.allowTargetingTaggedPlayers;
		for (int i = 0; i < aiAgent.agentBehaviours.Count; i++)
		{
			if (!usedBehaviours.Contains(aiAgent.agentBehaviours[i]))
			{
				switch (aiAgent.agentBehaviours[i])
				{
				case AgentBehaviours.Chase:
					behaviourDict[AgentBehaviours.Chase] = new CustomMapsChaseBehaviour(this, aiAgent);
					break;
				case AgentBehaviours.Search:
					behaviourDict[AgentBehaviours.Search] = new CustomMapsSearchBehaviour(this, aiAgent);
					break;
				case AgentBehaviours.Attack:
					behaviourDict[AgentBehaviours.Attack] = new CustomMapsAttackBehaviour(this, aiAgent);
					break;
				default:
					continue;
				}
				usedBehaviours.Add(aiAgent.agentBehaviours[i]);
			}
		}
	}

	public void StopMoving()
	{
		RequestDestination(base.transform.position);
	}

	public void RequestDestination(UnityEngine.Vector3 destination)
	{
		if (entity.IsAuthority())
		{
			agent.RequestDestination(destination);
		}
	}

	private void OnThink()
	{
		if (!entity.IsAuthority() || behaviourDict == null || behaviourDict.Count == 0)
		{
			return;
		}
		int num = -1;
		if (currentBehaviourIndex != -1 && behaviourDict[usedBehaviours[currentBehaviourIndex]].CanContinueExecuting())
		{
			num = currentBehaviourIndex;
		}
		else
		{
			for (int i = 0; i < usedBehaviours.Count; i++)
			{
				if (i != currentBehaviourIndex && behaviourDict[usedBehaviours[i]].CanExecute())
				{
					num = i;
					break;
				}
			}
		}
		if (num != -1)
		{
			if (currentBehaviourIndex != num)
			{
				currentBehaviourIndex = num;
				currentBehaviour = usedBehaviours[num];
				agent.RequestBehaviorChange((byte)currentBehaviour);
			}
			behaviourDict[currentBehaviour].Execute();
		}
	}

	private void OnNetworkBehaviourStateChanged(byte newstate)
	{
		if (newstate < 0 || newstate >= 3)
		{
			return;
		}
		if (behaviourDict.ContainsKey((AgentBehaviours)newstate))
		{
			if (currentBehaviour != (AgentBehaviours)newstate && behaviourDict.ContainsKey(currentBehaviour))
			{
				behaviourDict[currentBehaviour].ResetBehavior();
			}
			currentBehaviour = (AgentBehaviours)newstate;
			behaviourDict[currentBehaviour].NetExecute();
		}
	}

	public void OnEntityInit()
	{
		bool flag = AISpawnManager.HasInstance && AISpawnManager.instance != null;
		if (flag || !(MapSpawnManager.instance == null))
		{
			entity.transform.parent = (flag ? AISpawnManager.instance.transform : MapSpawnManager.instance.transform);
			AIAgent.UnpackCreateData(entity.createData, out var entityTypeID, out luaAgentID);
			if (flag && AISpawnManager.instance.SpawnEnemy(entityTypeID, out AIAgent newEnemy))
			{
				SetupNewEnemy(newEnemy);
				return;
			}
			if (!flag && MapSpawnManager.instance.SpawnEntity(entityTypeID, out MapEntity newEnemy2))
			{
				SetupNewEnemy((AIAgent)newEnemy2);
				return;
			}
			GTDev.LogError("CustomMapsAIBehaviourController::OnEntityInit could not spawn enemy");
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void SetupNewEnemy(AIAgent newEnemy)
	{
		newEnemy.gameObject.SetActive(value: true);
		newEnemy.transform.parent = entity.transform;
		newEnemy.transform.localPosition = UnityEngine.Vector3.zero;
		newEnemy.transform.localRotation = UnityEngine.Quaternion.identity;
		InitAnimators();
		NavMeshAgent component = entity.gameObject.GetComponent<NavMeshAgent>();
		if (GTExt.IsNull(component))
		{
			GTDev.LogError("nav mesh agent is null");
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		component.agentTypeID = GetNavAgentType(newEnemy.navAgentType);
		component.speed = newEnemy.movementSpeed;
		component.angularSpeed = newEnemy.turnSpeed;
		component.acceleration = newEnemy.acceleration;
		SetupBehaviours(newEnemy);
	}

	private int GetNavAgentType(NavAgentType navType)
	{
		int settingsCount = NavMesh.GetSettingsCount();
		int agentTypeID = NavMesh.GetSettingsByIndex(0).agentTypeID;
		for (int i = 0; i < settingsCount; i++)
		{
			NavMeshBuildSettings settingsByIndex = NavMesh.GetSettingsByIndex(i);
			if (NavMesh.GetSettingsNameFromID(settingsByIndex.agentTypeID) == navType.ToString())
			{
				agentTypeID = settingsByIndex.agentTypeID;
				break;
			}
		}
		return agentTypeID;
	}

