	{
	}

	public GRPlayer FindBestTarget(UnityEngine.Vector3 sourcePos, float maxRange, float maxRangeSq, float minDotVal)
	{
		float num = 0f;
		GRPlayer result = null;
		tempRigs.Clear();
		tempRigs.Add(VRRig.LocalRig);
		VRRigCache.Instance.GetAllUsedRigs(tempRigs);
		UnityEngine.Vector3 rhs = base.transform.rotation * UnityEngine.Vector3.forward;
		for (int i = 0; i < tempRigs.Count; i++)
		{
			GRPlayer component = tempRigs[i].GetComponent<GRPlayer>();
			if (!IsTargetInRange(sourcePos, component, maxRangeSq, out var toTarget))
			{
				continue;
			}
			float num2 = 0f;
			if (toTarget.sqrMagnitude > 0f)
			{
				num2 = Mathf.Sqrt(toTarget.magnitude);
			}
			float num3 = UnityEngine.Vector3.Dot(toTarget.normalized, rhs);
			if (!(num3 < minDotVal))
			{
				float num4 = Mathf.Lerp(0f, 0.5f, 1f - num2 / maxRange);
				float num5 = Mathf.Lerp(0f, 0.5f, (1f - minDotVal - (1f - num3)) / (1f - minDotVal));
				if (num4 + num5 > num && IsTargetVisible(sourcePos, component, maxRange))
				{
					num = num4 + num5;
					result = component;
				}
			}
		}
		return result;
	}

	public bool IsTargetVisible(UnityEngine.Vector3 startPos, GRPlayer target, float maxDist)
	{
		if (!IsTargetable(target))
		{
			return false;
		}
		int num = Physics.RaycastNonAlloc(new Ray(startPos, target.transform.position - startPos), visibilityHits, Mathf.Min(UnityEngine.Vector3.Distance(target.transform.position, startPos), maxDist), visibilityLayerMask.value, QueryTriggerInteraction.Ignore);
		for (int i = 0; i < num; i++)
		{
			if (visibilityHits[i].transform != base.transform && !visibilityHits[i].transform.IsChildOf(base.transform))
			{
				return false;
			}
		}
		return true;
	}

	public bool IsTargetInRange(UnityEngine.Vector3 startPos, GRPlayer target, float maxRangeSq, out UnityEngine.Vector3 toTarget)
	{
		toTarget = UnityEngine.Vector3.zero;
		if (!IsTargetable(target))
		{
			return false;
		}
		UnityEngine.Vector3 position = target.transform.position;
		toTarget = position - startPos;
		return toTarget.sqrMagnitude <= maxRangeSq;
	}

	public bool IsTargetable(GRPlayer potentialTarget)
	{
		if (GTExt.IsNull(potentialTarget))
		{
			return false;
		}
		if (potentialTarget.State == GRPlayer.GRPlayerState.Ghost)
		{
			return false;
		}
		if (potentialTarget.MyRig.isLocal)
		{
			if (CustomMapManager.IsLocalPlayerInVirtualStump())
			{
				return false;
			}
		}
		else if (CustomMapManager.IsRemotePlayerInVirtualStump(potentialTarget.MyRig.OwningNetPlayer.UserId))
		{
			return false;
		}
		if (!allowTargetingTaggedPlayers && GorillaGameModes.GameMode.ActiveGameMode.GameType() != GameModeType.Custom && GorillaGameModes.GameMode.LocalIsTagged(potentialTarget.MyRig.OwningNetPlayer))
		{
			return false;
		}
		return true;
	}
}
