public struct ModIORequestResult
{
	public bool success;

	public string message;

	public static ModIORequestResult CreateFailureResult(string inMessage)
	{
		ModIORequestResult result = default(ModIORequestResult);
		result.success = false;
		result.message = inMessage;
		return result;
	}

	public static ModIORequestResult CreateSuccessResult()
	{
		ModIORequestResult result = default(ModIORequestResult);
		result.success = true;
		result.message = "";
		return result;
	}

	public static ModIORequestResult CreateFromError(Modio.Error error)
	{
		ModIORequestResult result = default(ModIORequestResult);
		if ((bool)error)
		{
			result.success = false;
			result.message = error.GetMessage();
		}
		else
		{
			result.success = true;
			result.message = "";
		}
		return result;
	}
}
public struct ModIORequestResultAnd<T>
{
	public ModIORequestResult result;

	public T data;

	public static ModIORequestResultAnd<T> CreateFailureResult(string inMessage)
	{
		return new ModIORequestResultAnd<T>
		{
			result = ModIORequestResult.CreateFailureResult(inMessage)
		};
	}

	public static ModIORequestResultAnd<T> CreateSuccessResult(T payload)
	{
		return new ModIORequestResultAnd<T>
		{
			result = ModIORequestResult.CreateSuccessResult(),
			data = payload
		};
	}
}
public class ModIOManager : MonoBehaviour, ISteamCredentialProvider, IOculusCredentialProvider
{
	public enum ModIOAuthMethod
	{
		Invalid,
		LinkedAccount,
		Steam,
		Oculus
	}

	private const string MODIO_ACCEPTED_TERMS_KEY = "modIOAcceptedTermsHash";

	private const string MODIO_ACCEPTED_TERMS_OF_USE_ID_KEY = "modIOAcceptedTermsOfUseId";

