public class ModIOTermsOfUse_v1 : MonoBehaviour
{
	[SerializeField]
	private Transform uiParent;

	[SerializeField]
	private string title;

	[SerializeField]
	private TMP_Text tmpBody;

	[SerializeField]
	private TMP_Text tmpTitle;

	[SerializeField]
	private TMP_Text tmpPage;

	[SerializeField]
	public GameObject yesNoButtons;

	[SerializeField]
	public GameObject nextButton;

	[SerializeField]
	public GameObject prevButton;

	private bool hasTermsOfUse;

	private Action<bool> termsAcknowledgedCallback;

	private string cachedTermsText;

	private bool waitingForAcknowledge;

	private bool accepted;

	private bool acceptButtonDown;

	[SerializeField]
	private float holdTime = 5f;

	[SerializeField]
	private LineRenderer progressBar;

	private void OnEnable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction += PostUpdate;
		}
	}

	private void OnDisable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction -= PostUpdate;
		}
	}

	private void PostUpdate()
	{
		if (ControllerBehaviour.Instance.IsLeftStick)
		{
			TurnPage(-1);
		}
		if (ControllerBehaviour.Instance.IsRightStick)
		{
			TurnPage(1);
		}
		if (waitingForAcknowledge)
		{
			acceptButtonDown = ControllerBehaviour.Instance.ButtonDown;
		}
	}

	private async void Start()
	{
		while (!hasTermsOfUse)
		{
			await Task.Yield();
		}
		PrivateUIRoom.AddUI(uiParent);
		if (!(await UpdateTextFromTerms()))
		{
			while (true)
			{
				await Task.Yield();
			}
		}
		await WaitForAcknowledgement();
		termsAcknowledgedCallback?.Invoke(accepted);
		PrivateUIRoom.RemoveUI(uiParent);
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private async Task<bool> UpdateTextFromTerms()
	{
		tmpTitle.text = title;
		tmpBody.text = "Loading...";
		bool num = await UpdateTextWithFullTerms();
		if (!num)
		{
			tmpBody.text = "Failed to retrieve full Terms of Use text from mod.io.\n\nPlease restart the game and try again.";
			tmpBody.pageToDisplay = 1;
			tmpPage.text = string.Empty;
		}
		return num;
	}

	public async Task<bool> UpdateTextWithFullTerms()
	{
		return true;
	}

	private string GetStringForListItemIdx_LowerAlpha(int idx)
	{
		return idx switch
		{
			0 => "  a. <indent=5%>", 
			1 => "  b. <indent=5%>", 
			2 => "  c. <indent=5%>", 
			3 => "  d. <indent=5%>", 
			4 => "  e. <indent=5%>", 
			5 => "  f. <indent=5%>", 
			6 => "  g. <indent=5%>", 
			7 => "  h. <indent=5%>", 
			8 => "  i. <indent=5%>", 
			9 => "  j. <indent=5%>", 
			10 => "  k. <indent=5%>", 
			11 => "  l. <indent=5%>", 
			12 => "  m. <indent=5%>", 
			13 => "  n. <indent=5%>", 
			14 => "  o. <indent=5%>", 
			15 => "  p. <indent=5%>", 
			16 => "  q. <indent=5%>", 
			17 => "  r. <indent=5%>", 
			18 => "  s. <indent=5%>", 
			19 => "  t. <indent=5%>", 
			20 => "  u. <indent=5%>", 
			21 => "  v. <indent=5%>", 
			22 => "  w. <indent=5%>", 
			23 => "  x. <indent=5%>", 
			24 => "  y. <indent=5%>", 
			25 => "  z. <indent=5%>", 
			_ => "", 
		};
	}

	private async Task WaitForAcknowledgement()
	{
		accepted = false;
		float progress = 0f;
		progressBar.transform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
		while (progress < 1f)
		{
			progress = ((!acceptButtonDown) ? 0f : (progress + Time.deltaTime / holdTime));
			progressBar.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
			progressBar.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
			await Task.Yield();
		}
		if (progress >= 1f)
		{
			Acknowledge(acceptButtonDown);
		}
	}

	public void TurnPage(int i)
	{
		tmpBody.pageToDisplay = Mathf.Clamp(tmpBody.pageToDisplay + i, 1, tmpBody.textInfo.pageCount);
		tmpPage.text = $"page {tmpBody.pageToDisplay} of {tmpBody.textInfo.pageCount}";
		nextButton.SetActive(tmpBody.pageToDisplay < tmpBody.textInfo.pageCount);
		prevButton.SetActive(tmpBody.pageToDisplay > 1);
		ActivateAcceptButtonGroup();
	}

	private void ActivateAcceptButtonGroup()
	{
		bool active = tmpBody.pageToDisplay == tmpBody.textInfo.pageCount;
		yesNoButtons.SetActive(active);
		waitingForAcknowledge = active;
	}

	public void Acknowledge(bool didAccept)
	{
		accepted = didAccept;
	}
}
public class NewMapsDisplay : MonoBehaviour
{
	private struct NewMapData
	{
		public Texture2D image;

		public string info;
	}

	[SerializeField]
	private SpriteRenderer mapImage;

	[SerializeField]
	private TMP_Text loadingText;

	[Tooltip("DEPRECATED")]
	[SerializeField]
	private TMP_Text modNameText;

	[Tooltip("DEPRECATED")]
	[SerializeField]
	private TMP_Text modCreatorLabelText;

	[Tooltip("DEPRECATED")]
	[SerializeField]
	private TMP_Text modCreatorText;

	[SerializeField]
	private TMP_Text mapInfoTMP;

	[SerializeField]
	private float slideshowUpdateInterval = 1f;

	[SerializeField]
	private string loadingString = "LOADING...";

	[SerializeField]
	private string ugcDisabledString = "UGC DISABLED BY K-ID SETTINGS";

	private ModId newMapsModId = ModId.Null;

	private Mod newMapsModProfile;

	private List<NewMapData> newMapDatas = new List<NewMapData>();

	private bool slideshowActive;

	private int slideshowIndex;

	private float lastSlideshowUpdate;

	private bool requestingNewMapsModProfile;

	private LazyImage<Texture2D> lazyImage;

	private bool downloadingImages;

	private bool downloadingImage;

	private Texture2D lastDownloadedImage;

	private Coroutine initCoroutine;

	private Dictionary<Texture2D, Sprite> cachedTextures = new Dictionary<Texture2D, Sprite>();

	public void OnEnable()
	{
		mapImage.gameObject.SetActive(value: false);
		mapInfoTMP.text = "";
		mapInfoTMP.gameObject.SetActive(value: false);
		UGCPermissionManager.SubscribeToUGCEnabled(OnUGCEnabled);
		UGCPermissionManager.SubscribeToUGCDisabled(OnUGCDisabled);
		if (!UGCPermissionManager.IsUGCDisabled)
		{
			if (!ModIOManager.IsInitialized() || !ModIOManager.TryGetNewMapsModId(out newMapsModId))
			{
				initCoroutine = StartCoroutine(DelayedInitialize());
			}
			else
			{
				if (newMapsModId == ModId.Null)
				{
					return;
				}
				Initialize();
			}
		}
		loadingText.gameObject.SetActive(value: true);
	}

	public void OnDisable()
	{
		if (initCoroutine != null)
		{
			StopCoroutine(initCoroutine);
			initCoroutine = null;
		}
		newMapsModProfile = null;
		newMapDatas.Clear();
		slideshowActive = false;
		slideshowIndex = 0;
		lastSlideshowUpdate = 0f;
		mapImage.gameObject.SetActive(value: false);
		mapInfoTMP.text = "";
		mapInfoTMP.gameObject.SetActive(value: false);
		loadingText.text = loadingString;
		loadingText.gameObject.SetActive(value: false);
		UGCPermissionManager.UnsubscribeFromUGCEnabled(OnUGCEnabled);
		UGCPermissionManager.UnsubscribeFromUGCDisabled(OnUGCDisabled);
	}

	private void OnUGCEnabled()
	{
		if (newMapDatas.IsNullOrEmpty())
		{
			if (!ModIOManager.IsInitialized() || !ModIOManager.TryGetNewMapsModId(out newMapsModId))
			{
				initCoroutine = StartCoroutine(DelayedInitialize());
			}
			else if (!(newMapsModId == ModId.Null))
			{
				Initialize();
			}
		}
	}

	private void OnUGCDisabled()
	{
		mapImage.gameObject.SetActive(value: false);
		mapInfoTMP.text = "";
		mapInfoTMP.gameObject.SetActive(value: false);
		loadingText.text = ugcDisabledString;
		loadingText.gameObject.SetActive(value: true);
	}

	private IEnumerator DelayedInitialize()
	{
		while (!ModIOManager.TryGetNewMapsModId(out newMapsModId))
		{
			yield return new WaitForSecondsRealtime(1f);
		}
		initCoroutine = null;
		if (!(newMapsModId == ModId.Null))
		{
			Initialize();
		}
	}

	private async Task<Modio.Error> Initialize()
	{
		if (!requestingNewMapsModProfile && !downloadingImages)
		{
			requestingNewMapsModProfile = true;
			loadingText.text = loadingString;
			Modio.Error error = await ModIOManager.Initialize();
			if ((bool)error)
			{
				return error;
			}
			if (!base.isActiveAndEnabled)
			{
				return Modio.Error.None;
			}
			(error, newMapsModProfile) = await ModIOManager.GetMod(newMapsModId);
			if ((bool)error)
			{
				GTDev.LogWarning("[NewMapsDisplay::OnGetNewMapsModProfile] Failed to get NewMaps ModProfile " + $"from mod.io: {error}");
				return error;
			}
			newMapDatas.Clear();
			string[] array = newMapsModProfile.MetadataBlob.Split(';');
			string text = "";
			string[] array2 = array;
			foreach (string text2 in array2)
			{
				if (text2.StartsWith("mapInfo:"))
				{
					text = text2.Substring(8);
					break;
				}
			}
			string[] mapInfoList = (text.IsNullOrEmpty() ? null : text.Split(','));
			lazyImage = new LazyImage<Texture2D>(ImageCacheTexture2D.Instance, delegate(Texture2D loadedImage)
			{
				downloadingImage = false;
				lastDownloadedImage = loadedImage;
			});
			downloadingImages = true;
			int i;
			for (int i2 = 0; i2 < newMapsModProfile.Gallery.Length; i2 = i)
			{
				downloadingImage = true;
				lazyImage.SetImage(newMapsModProfile.Gallery[i2], Mod.GalleryResolution.X320_Y180);
				while (downloadingImage)
				{
					await Task.Yield();
				}
				string info = ((mapInfoList != null && mapInfoList.Length > i2) ? mapInfoList[i2] : "");
				NewMapData item = new NewMapData
				{
					image = lastDownloadedImage,
					info = info
				};
				newMapDatas.Add(item);
				lastDownloadedImage = null;
				i = i2 + 1;
			}
			downloadingImages = false;
			if (!base.isActiveAndEnabled)
			{
				return Modio.Error.None;
			}
			StartSlideshow();
			requestingNewMapsModProfile = false;
			return Modio.Error.None;
		}
		return new Modio.Error(Modio.Errors.ErrorCode.UNKNOWN, "Initialization already in progress.");
	}

	private void StartSlideshow()
	{
		if (!newMapDatas.IsNullOrEmpty())
		{
			slideshowIndex = 0;
			slideshowActive = true;
			UpdateSlideshow();
		}
	}

	public void Update()
	{
		if (slideshowActive && !(Time.time - lastSlideshowUpdate < slideshowUpdateInterval))
		{
			UpdateSlideshow();
		}
	}

	private void UpdateSlideshow()
	{
		loadingText.gameObject.SetActive(value: false);
		lastSlideshowUpdate = Time.time;
		Texture2D image = newMapDatas[slideshowIndex].image;
		if (image != null)
		{
			if (!cachedTextures.TryGetValue(image, out var value))
			{
				value = Sprite.Create(image, new Rect(0f, 0f, image.width, image.height), new UnityEngine.Vector2(0.5f, 0.5f));
				cachedTextures.Add(image, value);
			}
			mapImage.sprite = value;
			mapImage.gameObject.SetActive(value: true);
		}
		else
		{
			mapImage.gameObject.SetActive(value: false);
		}
		mapInfoTMP.text = newMapDatas[slideshowIndex].info;
		mapInfoTMP.gameObject.SetActive(value: true);
		slideshowIndex++;
		if (slideshowIndex >= newMapDatas.Count)
		{
			slideshowIndex = 0;
		}
	}
}
public class CustomMapsAccessScreen : CustomMapsTerminalScreen
{
	[SerializeField]
	private TMP_Text errorText;

	[SerializeField]
	private TMP_Text terminalControlPromptText;

	[SerializeField]
	private bool isControlScreen = true;

	[SerializeField]
	private string defaultText = "PRESS THE 'TERMINAL AVAILABLE' BUTTON TO PROCEED.";

	private string detailsScreenText = "\nMAP DETAILS WILL APPEAR HERE WHEN A MAP IS SELECTED.";

	private string displayedText = string.Empty;

	private bool useNametags;

	private void LateUpdate()
	{
		if (CustomMapsTerminal.GetDriverID() != -2 && !CustomMapsTerminal.IsDriver && !(GorillaComputer.instance == null) && useNametags != GorillaComputer.instance.NametagsEnabled)
		{
			useNametags = GorillaComputer.instance.NametagsEnabled;
			SetDriverName();
		}
	}

	public override void Initialize()
	{
	}

	public override void Show()
	{
		base.Show();
		if (displayedText == string.Empty)
		{
			displayedText = defaultText;
		}
		errorText.gameObject.SetActive(value: false);
		terminalControlPromptText.gameObject.SetActive(value: true);
		terminalControlPromptText.text = displayedText;
	}

	public override void Hide()
	{
		errorText.gameObject.SetActive(value: false);
		terminalControlPromptText.gameObject.SetActive(value: false);
		base.Hide();
	}

	public void Reset()
	{
		errorText.gameObject.SetActive(value: false);
		terminalControlPromptText.gameObject.SetActive(value: true);
		displayedText = defaultText;
	}

	public void SetDetailsScreenForDriver()
	{
		displayedText = detailsScreenText;
	}

	public void SetDriverName()
	{
		bool flag = KIDManager.HasPermissionToUseFeature(EKIDFeatures.Custom_Nametags);
		string text;
		if (NetworkSystem.Instance.InRoom)
		{
			NetPlayer netPlayerByID = NetworkSystem.Instance.GetNetPlayerByID(CustomMapsTerminal.GetDriverID());
			text = netPlayerByID.DefaultName;
			if (useNametags && flag)
			{
				RigContainer playerRig;
				if (netPlayerByID.IsLocal)
				{
					text = netPlayerByID.NickName;
				}
				else if (VRRigCache.Instance.TryGetVrrig(netPlayerByID, out playerRig))
				{
					text = playerRig.Rig.playerNameVisible;
				}
			}
		}
		else
		{
			text = ((useNametags && flag) ? NetworkSystem.Instance.LocalPlayer.NickName : NetworkSystem.Instance.LocalPlayer.DefaultName);
		}
		displayedText = "TERMINAL CONTROLLED BY: " + text;
		if (!isControlScreen)
		{
			displayedText += detailsScreenText;
		}
		terminalControlPromptText.text = displayedText;
	}

	public void DisplayError(string errorMessage)
	{
		terminalControlPromptText.gameObject.SetActive(value: false);
		errorText.text = errorMessage;
		errorText.gameObject.SetActive(value: true);
	}
}
