	private void OnModIOLoggedIn()
	{
		if (currentMapMod.Creator == null)
		{
			RefreshCurrentMapMod();
		}
		else if (currentMapMod.IsHidden())
		{
			UpdateMapDetails();
		}
		else
		{
			UpdateStatus();
		}
	}

