public abstract class CustomMapsScreenTouchPoint : MonoBehaviour, IClickable
{
	public enum TouchPointDirections
	{
		Forward,
		Backward,
		Left,
		Right,
		Up,
		Down
	}

	[SerializeField]
	private CustomMapsTerminalScreen screen;

	[SerializeField]
	private CustomMapKeyboardBinding keyBinding;

	[SerializeField]
	private TouchPointDirections forwardDirection;

	[SerializeField]
	protected SpriteRenderer touchPointRenderer;

	[SerializeField]
	protected ButtonColorSettings buttonColorSettings;

	private static float pressedTime = 0.25f;

	protected static float pressTime;

	private Coroutine colorUpdateCoroutine;

	protected virtual void Awake()
	{
	}

	protected virtual void OnDisable()
	{
		if (colorUpdateCoroutine != null)
		{
			StopCoroutine(colorUpdateCoroutine);
		}
		if (buttonColorSettings != null)
		{
			touchPointRenderer.color = buttonColorSettings.UnpressedColor;
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		GTDev.Log($"trigger {base.gameObject.name} pressTime={pressTime} time={Time.time}");
		if (Time.time < pressTime + pressedTime || !(collider.GetComponentInParent<GorillaTriggerColliderHandIndicator>() != null))
		{
			return;
		}
		UnityEngine.Vector3 rhs = GetForwardDirection();
		if (!(UnityEngine.Vector3.Dot((collider.transform.position - base.transform.position).normalized, rhs) < 0f))
		{
			GTDev.Log($"trigger {base.gameObject.name} collider {collider.gameObject.name} postion {collider.transform.position}");
			GorillaTriggerColliderHandIndicator component = collider.GetComponent<GorillaTriggerColliderHandIndicator>();
			pressTime = Time.time;
			OnButtonPressedEvent();
			PressButtonColourUpdate();
			if (screen != null)
			{
				screen.PressButton(keyBinding);
			}
			if (component != null)
			{
				GorillaTagger.Instance.StartVibration(component.isLeftHand, GorillaTagger.Instance.tapHapticStrength / 2f, GorillaTagger.Instance.tapHapticDuration);
			}
		}
	}

	public virtual void PressButtonColourUpdate()
	{
		if (base.gameObject.activeInHierarchy)
		{
			touchPointRenderer.color = buttonColorSettings.PressedColor;
			colorUpdateCoroutine = StartCoroutine(ButtonColorUpdate_Local());
		}
		IEnumerator ButtonColorUpdate_Local()
		{
			yield return new WaitForSeconds(pressedTime);
			if (pressTime != 0f && Time.time > pressedTime + pressTime)
			{
				touchPointRenderer.color = buttonColorSettings.UnpressedColor;
				pressTime = 0f;
			}
		}
	}

	private UnityEngine.Vector3 GetForwardDirection()
	{
		return forwardDirection switch
		{
			TouchPointDirections.Forward => base.transform.forward, 
			TouchPointDirections.Backward => -base.transform.forward, 
			TouchPointDirections.Left => -base.transform.right, 
			TouchPointDirections.Right => base.transform.right, 
			TouchPointDirections.Up => base.transform.up, 
			TouchPointDirections.Down => -base.transform.up, 
			_ => base.transform.forward, 
		};
	}

	protected abstract void OnButtonPressedEvent();

	public void Click(bool leftHand = false)
	{
	}
}
public class CustomMapsSearchScreen : CustomMapsTerminalScreen
{
	[SerializeField]
	private TMP_Text searchPhraseText;

	[SerializeField]
	private TMP_Text searchMessageText;

	[SerializeField]
	private CustomMapsGalleryView customMapsGalleryView;

	[SerializeField]
	private GameObject leftPageButton;

	[SerializeField]
	private GameObject rightPageButton;

	[SerializeField]
	private string defaultSearchString = "SEARCH PHRASE";

	[SerializeField]
	private string noMapsFoundString = "NO RESULTS FOUND";

	[SerializeField]
	private string searchingString = "SEARCHING";

	[SerializeField]
	private int numModsPerRequest = 60;

	[SerializeField]
	private int modsPerPage = 6;

	private string searchPhrase = "";

	private List<Mod> searchedMods = new List<Mod>();

	private List<Mod> filteredSearchedMods = new List<Mod>();

	private List<Mod> displayedMods = new List<Mod>();

	private int currentSearchModsRequestPage;

	private bool loadingSearchMods;

	private bool errorLoadingSearchMods;

	private int totalSearchMods;

	private int currentModPage;

	private string errorMessage = "";

	public override void Show()
	{
		base.Show();
		searchPhraseText.gameObject.SetActive(value: true);
		customMapsGalleryView.gameObject.SetActive(value: false);
		searchMessageText.gameObject.SetActive(value: false);
		leftPageButton.gameObject.SetActive(value: false);
		rightPageButton.gameObject.SetActive(value: false);
		searchedMods.Clear();
		filteredSearchedMods.Clear();
		displayedMods.Clear();
		searchPhraseText.text = defaultSearchString;
		searchPhrase = string.Empty;
		currentSearchModsRequestPage = 0;
		currentModPage = 0;
	}

	public override void Hide()
	{
		base.Hide();
		customMapsGalleryView.ShowTileText(show: false, useMapName: true);
	}

	public override void Initialize()
	{
	}

	public void ReturnFromDetailsScreen()
	{
		base.Show();
		customMapsGalleryView.ShowTileText(show: true, useMapName: true);
	}

	public override void PressButton(CustomMapKeyboardBinding pressedButton)
	{
		if (Time.time < showTime + activationTime || !CustomMapsTerminal.IsDriver)
		{
			return;
		}
		if (CustomMapKeyboardBinding.tile1 <= pressedButton && pressedButton <= CustomMapKeyboardBinding.tile6 && !GTExt.IsNull(customMapsGalleryView))
		{
			customMapsGalleryView.ShowDetailsForEntry((int)(pressedButton - 62));
		}
		if (pressedButton < CustomMapKeyboardBinding.up)
		{
			string text = searchPhrase;
			int num = (int)pressedButton;
			searchPhrase = text + num;
			RefreshSearchText();
			return;
		}
		if (pressedButton > CustomMapKeyboardBinding.option3 && pressedButton < CustomMapKeyboardBinding.at)
		{
			searchPhrase += pressedButton;
			RefreshSearchText();
			return;
		}
		switch (pressedButton)
		{
		case CustomMapKeyboardBinding.goback:
			if (loadingSearchMods)
			{
				return;
			}
			CustomMapsTerminal.ReturnFromSearchScreen();
			break;
		case CustomMapKeyboardBinding.enter:
			if (loadingSearchMods)
			{
				return;
			}
			searchedMods.Clear();
			filteredSearchedMods.Clear();
			currentSearchModsRequestPage = 0;
			searchMessageText.gameObject.SetActive(value: true);
			searchMessageText.text = searchingString;
			RetrieveMods();
			break;
		case CustomMapKeyboardBinding.delete:
			if (!searchPhrase.IsNullOrEmpty())
			{
				searchPhrase = searchPhrase.Remove(searchPhrase.Length - 1);
			}
			break;
		case CustomMapKeyboardBinding.right:
			currentModPage++;
			RefreshScreenState();
			break;
		case CustomMapKeyboardBinding.left:
			currentModPage--;
			RefreshScreenState();
			break;
		}
		RefreshSearchText();
	}

	private void RefreshSearchText()
	{
		if (searchPhrase.IsNullOrEmpty())
		{
			searchPhraseText.text = defaultSearchString;
		}
		else
		{
			searchPhraseText.text = searchPhrase;
		}
	}

	private async Task RetrieveMods()
	{
		if (!loadingSearchMods)
		{
			loadingSearchMods = true;
			ModSearchFilter modSearchFilter = new ModSearchFilter(currentSearchModsRequestPage++, numModsPerRequest);
			Filtering filtering = Filtering.Like;
			modSearchFilter.ClearSearchPhrases(filtering);
			if (!searchPhrase.IsNullOrEmpty())
			{
				modSearchFilter.AddSearchPhrase(searchPhrase, filtering);
			}
			(Modio.Error, ModioPage<Mod>) obj = await ModIOManager.GetMods(modSearchFilter.GetModsFilter());
			Modio.Error item = obj.Item1;
			ModioPage<Mod> item2 = obj.Item2;
			loadingSearchMods = false;
			if ((bool)item)
			{
				errorLoadingSearchMods = true;
				errorMessage = item.GetMessage();
				GTDev.LogError("[CustomMapsListScreen::OnAvailableModsRetrieved] Failed to retrieve mods. Error: " + item.GetMessage());
			}
			else
			{
				totalSearchMods = (int)item2.TotalSearchResults;
				searchedMods.AddRange(item2.Data);
				FilterSearchMods();
			}
			RefreshScreenState();
		}
	}

	private void FilterSearchMods()
	{
		if (searchedMods.IsNullOrEmpty())
		{
			return;
		}
		filteredSearchedMods.Clear();
		foreach (Mod searchedMod in searchedMods)
		{
			if (ModIOManager.TryGetNewMapsModId(out var newMapsModId) && searchedMod.Id == newMapsModId)
			{
				totalSearchMods = Mathf.Max(0, totalSearchMods - 1);
			}
			else
			{
				filteredSearchedMods.Add(searchedMod);
			}
		}
	}

	private void RefreshScreenState()
	{
		searchMessageText.gameObject.SetActive(value: false);
		customMapsGalleryView.ResetGallery();
		customMapsGalleryView.gameObject.SetActive(value: false);
		displayedMods.Clear();
		if (errorLoadingSearchMods)
		{
			searchMessageText.gameObject.SetActive(value: true);
			searchMessageText.text = errorMessage;
			leftPageButton.SetActive(value: false);
			rightPageButton.SetActive(value: false);
			return;
		}
		if (filteredSearchedMods.IsNullOrEmpty())
		{
			searchMessageText.gameObject.SetActive(value: true);
			searchMessageText.text = noMapsFoundString;
			leftPageButton.SetActive(value: false);
			rightPageButton.SetActive(value: false);
			return;
		}
		int num = 0;
		int num2 = modsPerPage - 1;
		if (!IsOnFirstPage())
		{
			num = currentModPage * modsPerPage;
			num2 = num + modsPerPage - 1;
			leftPageButton.gameObject.SetActive(value: true);
		}
		else
		{
			leftPageButton.gameObject.SetActive(value: false);
		}
		if (!IsOnLastPage())
		{
			rightPageButton.gameObject.SetActive(value: true);
		}
		else
		{
			rightPageButton.gameObject.SetActive(value: false);
		}
		if (filteredSearchedMods.Count <= num2 && totalSearchMods > searchedMods.Count)
		{
			RetrieveMods();
			return;
		}
		for (int i = num; i <= num2 && filteredSearchedMods.Count > i; i++)
		{
			displayedMods.Add(filteredSearchedMods[i]);
		}
		customMapsGalleryView.gameObject.SetActive(value: true);
		if (!customMapsGalleryView.DisplayGallery(displayedMods, useMapName: true, out var error))
		{
			searchMessageText.gameObject.SetActive(value: true);
			searchMessageText.text = error;
			customMapsGalleryView.gameObject.SetActive(value: false);
			leftPageButton.SetActive(value: false);
			rightPageButton.SetActive(value: false);
		}
	}

	private int GetNumPages()
	{
		int num = totalSearchMods % modsPerPage;
		int num2 = totalSearchMods / modsPerPage;
		if (num > 0)
		{
			num2++;
		}
		return num2;
	}

	private bool IsOnFirstPage()
	{
		return currentModPage == 0;
	}

	private bool IsOnLastPage()
	{
		long num = GetNumPages();
		if (currentModPage + 1 == num)
		{
			return true;
		}
		return false;
	}
}
public class CustomMapsTerminal : MonoBehaviour
{
	public enum ScreenType
	{
		Invalid = -1,
		TerminalControlPrompt,
		AvailableMods,
		InstalledMods,
		FavoriteMods,
		SubscribedMods,
		SearchMods,
		ModDetails
	}

	[SerializeField]
	private CustomMapsAccessScreen controlAccessScreen;

	[SerializeField]
	private CustomMapsAccessScreen detailsAccessScreen;

	[SerializeField]
	private CustomMapsListScreen modListScreen;

	[SerializeField]
	private CustomMapsDetailsScreen modDetailsScreen;

	[SerializeField]
	private CustomMapsDisplayScreen modDisplayScreen;

	[SerializeField]
	private CustomMapsSearchScreen modSearchScreen;

	[SerializeField]
	private VirtualStumpSerializer mapTerminalNetworkObject;

	[SerializeField]
	private CustomMapsTerminalControlButton terminalControlButton;

	[SerializeField]
	private TMP_Text terminalControllerLabelText;

	[SerializeField]
	private TMP_Text terminalControllerText;

	public const int NO_DRIVER_ID = -2;

	private static CustomMapsTerminal instance;

	private static bool hasInstance;

	private static long localModDetailsID = -1L;

	private static long cachedModDetailsID = -1L;

	private static int localDriverID = -1;

	private static int cachedLocalPlayerID = -1;

	private static ScreenType localCurrentScreen = ScreenType.Invalid;

	private static ScreenType cachedCurrentScreen = ScreenType.Invalid;

	private static ScreenType previousScreen = ScreenType.Invalid;

	public static int LocalPlayerID => NetworkSystem.Instance.LocalPlayer.ActorNumber;

	public static long LocalModDetailsID => localModDetailsID;

	public static int CurrentScreen => (int)localCurrentScreen;

	public static bool IsDriver => localDriverID == LocalPlayerID;

	private void Awake()
	{
		instance = this;
		hasInstance = true;
	}

	private void Start()
	{
		localDriverID = -2;
		localCurrentScreen = ScreenType.TerminalControlPrompt;
		previousScreen = ScreenType.TerminalControlPrompt;
		controlAccessScreen.Show();
		detailsAccessScreen.Show();
		modListScreen.Hide();
		modDetailsScreen.Hide();
		ModIOManager.OnModIOLoggedIn.AddListener(OnModIOLoggedIn);
		ModIOManager.OnModIOLoggedOut.AddListener(OnModIOLoggedOut);
		NetworkSystem.Instance.OnMultiplayerStarted += new Action(OnJoinedRoom);
		NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(OnReturnedToSinglePlayer);
	}

	private void OnDestroy()
	{
		ModIOManager.OnModIOLoggedIn.RemoveListener(OnModIOLoggedIn);
		ModIOManager.OnModIOLoggedOut.RemoveListener(OnModIOLoggedOut);
		NetworkSystem.Instance.OnMultiplayerStarted -= new Action(OnJoinedRoom);
		NetworkSystem.Instance.OnReturnedToSinglePlayer -= new Action(OnReturnedToSinglePlayer);
	}

	public static void ShowDetailsScreen(Mod mod)
	{
		previousScreen = localCurrentScreen;
		localCurrentScreen = ScreenType.ModDetails;
		localModDetailsID = mod.Id;
		instance.modListScreen.Hide();
		instance.controlAccessScreen.Hide();
		instance.detailsAccessScreen.Hide();
		instance.modDetailsScreen.Show();
		instance.modDetailsScreen.SetModProfile(mod);
		instance.modDisplayScreen.Show();
		instance.modDisplayScreen.SetModProfile(mod);
		instance.modSearchScreen.Hide();
		SendTerminalStatus();
	}

	public static void ReturnFromDetailsScreen()
	{
		ScreenType screenType = previousScreen;
		if (screenType == ScreenType.ModDetails || screenType == ScreenType.Invalid || screenType == ScreenType.TerminalControlPrompt)
		{
			localCurrentScreen = ScreenType.AvailableMods;
			previousScreen = ScreenType.AvailableMods;
		}
		else
		{
			localCurrentScreen = previousScreen;
		}
		switch (localCurrentScreen)
		{
		case ScreenType.TerminalControlPrompt:
			instance.modListScreen.Hide();
			instance.modDetailsScreen.Hide();
			instance.modDisplayScreen.Hide();
			instance.modSearchScreen.Hide();
			instance.controlAccessScreen.Show();
			instance.detailsAccessScreen.Show();
			break;
		case ScreenType.AvailableMods:
		case ScreenType.InstalledMods:
		case ScreenType.FavoriteMods:
		case ScreenType.SubscribedMods:
			instance.modListScreen.Show();
			instance.modSearchScreen.Hide();
			instance.modDetailsScreen.Hide();
			instance.modDisplayScreen.Hide();
			instance.controlAccessScreen.Hide();
			instance.detailsAccessScreen.Show();
			break;
		case ScreenType.SearchMods:
			instance.modListScreen.Hide();
			instance.modSearchScreen.ReturnFromDetailsScreen();
			instance.modDetailsScreen.Hide();
			instance.modDisplayScreen.Hide();
			instance.controlAccessScreen.Hide();
			instance.detailsAccessScreen.Show();
			break;
		}
		SendTerminalStatus();
	}

	public static void ShowSearchScreen()
	{
		previousScreen = localCurrentScreen;
		localCurrentScreen = ScreenType.SearchMods;
		instance.modListScreen.Hide();
		instance.controlAccessScreen.Hide();
		instance.detailsAccessScreen.SetDetailsScreenForDriver();
		instance.detailsAccessScreen.Show();
		instance.modDetailsScreen.Hide();
		instance.modDisplayScreen.Hide();
		instance.modSearchScreen.Show();
		SendTerminalStatus();
	}

	public static void ReturnFromSearchScreen()
	{
		ScreenType screenType = previousScreen;
		if (screenType == ScreenType.ModDetails || screenType == ScreenType.Invalid || screenType == ScreenType.TerminalControlPrompt || screenType == ScreenType.SearchMods)
		{
			localCurrentScreen = ScreenType.AvailableMods;
			previousScreen = ScreenType.AvailableMods;
		}
		else
		{
			localCurrentScreen = previousScreen;
		}
		switch (localCurrentScreen)
		{
		case ScreenType.TerminalControlPrompt:
			instance.modListScreen.Hide();
			instance.modSearchScreen.Hide();
			instance.modDetailsScreen.Hide();
			instance.modDisplayScreen.Hide();
			instance.controlAccessScreen.Show();
			instance.detailsAccessScreen.Show();
			break;
		case ScreenType.AvailableMods:
		case ScreenType.InstalledMods:
		case ScreenType.FavoriteMods:
		case ScreenType.SubscribedMods:
			instance.modListScreen.Show();
			instance.modSearchScreen.Hide();
			instance.modDetailsScreen.Hide();
			instance.modDisplayScreen.Hide();
			instance.controlAccessScreen.Hide();
			instance.detailsAccessScreen.Show();
			break;
		}
		SendTerminalStatus();
	}

	public static void SendTerminalStatus()
	{
		if (hasInstance)
		{
			instance.mapTerminalNetworkObject.SendTerminalStatus();
		}
	}

	public static void ResetTerminalControl()
	{
		localDriverID = -2;
		instance.terminalControlButton.UnlockTerminalControl();
		ShowTerminalControlScreen();
	}

	public static void HandleTerminalControlStatusChangeRequest(bool lockedStatus, int playerID)
	{
		if (lockedStatus && playerID == -2)
		{
			return;
		}
		if (localDriverID == -2)
		{
			if (!lockedStatus)
			{
				return;
			}
		}
		else if (localDriverID != playerID)
		{
			return;
		}
		SetTerminalControlStatus(lockedStatus, playerID, sendRPC: true);
	}

	public static void SetTerminalControlStatus(bool isLocked, int driverID = -2, bool sendRPC = false)
	{
		GTDev.Log($"[CustomMapsTerminal::SetTerminalControlStatus] isLocked: {isLocked} | driverID: {driverID} | playerId {LocalPlayerID} | sendRPC: {sendRPC}");
		if (isLocked)
		{
			localDriverID = driverID;
			instance.terminalControlButton.LockTerminalControl();
			if (IsDriver)
			{
				HideTerminalControlScreens();
			}
			else
			{
				ShowTerminalControlScreen();
			}
		}
		else
		{
			localDriverID = -2;
			instance.terminalControlButton.UnlockTerminalControl();
			ShowTerminalControlScreen();
		}
		if (sendRPC && NetworkSystem.Instance.IsMasterClient)
		{
			instance.mapTerminalNetworkObject.SetTerminalControlStatus(isLocked, localDriverID);
		}
	}

	public static void UpdateFromDriver(int currentScreen, long modDetailsID, int driverID)
	{
		if (!hasInstance)
		{
			return;
		}
		localDriverID = driverID;
		cachedModDetailsID = modDetailsID;
		localModDetailsID = modDetailsID;
		cachedCurrentScreen = (ScreenType)currentScreen;
		localCurrentScreen = (ScreenType)currentScreen;
		UnityEngine.Debug.Log($"[CustomMapsTerminal::UpdateFromDriver] currentScreen {localCurrentScreen} modDetailsID {localModDetailsID}");
		if (localDriverID != -2)
		{
			RefreshDriverNickName();
		}
		switch (localCurrentScreen)
		{
		case ScreenType.TerminalControlPrompt:
		case ScreenType.AvailableMods:
		case ScreenType.InstalledMods:
		case ScreenType.FavoriteMods:
		case ScreenType.SubscribedMods:
		case ScreenType.SearchMods:
			ShowTerminalControlScreen();
			break;
		case ScreenType.ModDetails:
			ShowTerminalControlScreen();
			if (localModDetailsID > 0)
			{
				instance.detailsAccessScreen.Hide();
				instance.modDisplayScreen.Show();
				instance.modDisplayScreen.RetrieveModFromModIO(localModDetailsID);
			}
			break;
		}
	}

	private void UpdateControlScreenForDriver()
	{
		GTDev.Log($"[CustomMapsTerminal::UpdateScreenToMatchStatus] driverID: {localDriverID} " + $"| currentScreen: {localCurrentScreen} " + $"| previousScreen: {previousScreen} ");
		switch (localCurrentScreen)
		{
		case ScreenType.TerminalControlPrompt:
			break;
		case ScreenType.AvailableMods:
		case ScreenType.InstalledMods:
		case ScreenType.FavoriteMods:
		case ScreenType.SubscribedMods:
			controlAccessScreen.Hide();
			modSearchScreen.Hide();
			detailsAccessScreen.SetDetailsScreenForDriver();
			detailsAccessScreen.Show();
			modListScreen.Show();
			modDetailsScreen.Hide();
			modDisplayScreen.Hide();
			break;
		case ScreenType.ModDetails:
			controlAccessScreen.Hide();
			modSearchScreen.Hide();
			detailsAccessScreen.Hide();
			modListScreen.Hide();
			modDetailsScreen.Show();
			modDetailsScreen.RetrieveModFromModIO(localModDetailsID);
			modDisplayScreen.Show();
			modDisplayScreen.RetrieveModFromModIO(localModDetailsID);
			break;
		case ScreenType.SearchMods:
			controlAccessScreen.Hide();
			modSearchScreen.Show();
			detailsAccessScreen.SetDetailsScreenForDriver();
			detailsAccessScreen.Show();
			modListScreen.Hide();
			modDetailsScreen.Hide();
			modDisplayScreen.Hide();
			break;
		}
	}

	private void ValidateLocalStatus()
	{
		if (localDriverID != -2)
		{
			if (CustomMapLoader.IsMapLoaded())
			{
				localCurrentScreen = ScreenType.ModDetails;
				localModDetailsID = CustomMapLoader.LoadedMapModId;
				SendTerminalStatus();
			}
			else if (CustomMapManager.IsLoading())
			{
				localCurrentScreen = ScreenType.ModDetails;
				localModDetailsID = CustomMapManager.LoadingMapId;
				SendTerminalStatus();
			}
			else if (CustomMapManager.GetRoomMapId() != ModId.Null)
			{
				localCurrentScreen = ScreenType.ModDetails;
				localModDetailsID = CustomMapManager.GetRoomMapId()._id;
				SendTerminalStatus();
			}
		}
	}

	private void OnModIOLoggedIn()
	{
	}

	private void OnModIOLoggedOut()
	{
		if (localCurrentScreen == ScreenType.SubscribedMods)
		{
			if (modListScreen.isActiveAndEnabled)
			{
				modListScreen.SwapListDisplay(CustomMapsListScreen.ListScreenState.AvailableMods);
			}
			else
			{
				localCurrentScreen = ScreenType.AvailableMods;
			}
		}
		if (previousScreen == ScreenType.SubscribedMods)
		{
			previousScreen = ScreenType.AvailableMods;
		}
	}

	public void HandleTerminalControlButtonPressed()
	{
		if (NetworkSystem.Instance.InRoom)
		{
			if (localDriverID == -2 || IsDriver)
			{
				if (mapTerminalNetworkObject.HasAuthority)
				{
					HandleTerminalControlStatusChangeRequest(!terminalControlButton.IsLocked, LocalPlayerID);
				}
				else
				{
					mapTerminalNetworkObject.RequestTerminalControlStatusChange(!terminalControlButton.IsLocked);
				}
			}
		}
		else
		{
			SetTerminalControlStatus(!terminalControlButton.IsLocked, LocalPlayerID);
		}
	}

	private static void ShowTerminalControlScreen()
	{
		if (hasInstance)
		{
			if (localDriverID == -2)
			{
				instance.controlAccessScreen.Reset();
				instance.detailsAccessScreen.Reset();
			}
			else
			{
				instance.controlAccessScreen.SetDriverName();
				instance.detailsAccessScreen.SetDriverName();
			}
			instance.modListScreen.Hide();
			instance.modDetailsScreen.Hide();
			instance.modDisplayScreen.Hide();
			instance.controlAccessScreen.Show();
			instance.detailsAccessScreen.Show();
			instance.modSearchScreen.Hide();
			previousScreen = localCurrentScreen;
			localCurrentScreen = ScreenType.TerminalControlPrompt;
		}
	}

	private static void HideTerminalControlScreens()
	{
		if (!hasInstance || localCurrentScreen != ScreenType.TerminalControlPrompt)
		{
			return;
		}
		if (previousScreen > ScreenType.TerminalControlPrompt)
		{
			localCurrentScreen = previousScreen;
			if ((localCurrentScreen == ScreenType.SubscribedMods || localCurrentScreen == ScreenType.FavoriteMods) && !ModIOManager.IsLoggedIn())
			{
				localCurrentScreen = ScreenType.AvailableMods;
			}
		}
		else if (CustomMapLoader.IsMapLoaded() || CustomMapManager.IsLoading() || CustomMapManager.GetRoomMapId() != ModId.Null)
		{
			localCurrentScreen = ScreenType.ModDetails;
		}
		else
		{
			localCurrentScreen = ScreenType.AvailableMods;
		}
		instance.UpdateControlScreenForDriver();
	}

	public static void RequestDriverNickNameRefresh()
	{
		if (hasInstance && IsDriver)
		{
			RefreshDriverNickName();
			instance.mapTerminalNetworkObject.RefreshDriverNickName();
		}
	}

	public static void RefreshDriverNickName()
	{
		if (!hasInstance)
		{
			return;
		}
		bool flag = KIDManager.HasPermissionToUseFeature(EKIDFeatures.Custom_Nametags);
		instance.terminalControllerLabelText.gameObject.SetActive(value: true);
		if (NetworkSystem.Instance.InRoom)
		{
			NetPlayer netPlayerByID = NetworkSystem.Instance.GetNetPlayerByID(localDriverID);
			instance.terminalControllerText.text = netPlayerByID.DefaultName;
			if (GorillaComputer.instance.NametagsEnabled && flag)
			{
				RigContainer playerRig;
				if (netPlayerByID.IsLocal)
				{
					instance.terminalControllerText.text = netPlayerByID.NickName;
				}
				else if (VRRigCache.Instance.TryGetVrrig(netPlayerByID, out playerRig))
				{
					instance.terminalControllerText.text = playerRig.Rig.playerNameVisible;
				}
			}
		}
		else
		{
			instance.terminalControllerText.text = ((GorillaComputer.instance.NametagsEnabled && flag) ? NetworkSystem.Instance.LocalPlayer.NickName : NetworkSystem.Instance.LocalPlayer.DefaultName);
		}
		instance.terminalControllerText.gameObject.SetActive(value: true);
		instance.modListScreen.RefreshDriverNickname(instance.terminalControllerText.text);
	}

	private void OnReturnedToSinglePlayer()
	{
		if (localDriverID != cachedLocalPlayerID)
		{
			ResetTerminalControl();
		}
		else
		{
			localDriverID = LocalPlayerID;
		}
		cachedLocalPlayerID = -1;
	}

	private void OnJoinedRoom()
	{
		cachedLocalPlayerID = LocalPlayerID;
		ResetTerminalControl();
	}

	public static bool IsLocked()
	{
		if (localDriverID == -2)
		{
			return false;
		}
		return true;
	}

	public static int GetDriverID()
	{
		return localDriverID;
	}

	public static string GetDriverNickname()
	{
		if (!hasInstance)
		{
			return "";
		}
		return instance.terminalControllerText.text;
	}
}
public class CustomMapsTerminalButton : GorillaPressableButton
{
}
public abstract class CustomMapsTerminalScreen : MonoBehaviour
{
	public CustomMapsKeyboard terminalKeyboard;

	[SerializeField]
	protected float activationTime = 0.25f;

	protected float showTime;

	public abstract void Initialize();

	public virtual void Show()
	{
		if (!base.gameObject.activeSelf)
		{
			base.gameObject.SetActive(value: true);
			terminalKeyboard?.OnKeyPressed.AddListener(PressButton);
		}
		showTime = Time.time;
	}

	public virtual void Hide()
	{
		if (base.gameObject.activeSelf)
		{
			base.gameObject.SetActive(value: false);
			terminalKeyboard?.OnKeyPressed.RemoveListener(PressButton);
		}
		showTime = 0f;
	}

	public virtual void PressButton(CustomMapKeyboardBinding pressedButton)
	{
	}
}
public class VirtualStumpOptionsTerminal : MonoBehaviour, IWssAuthPrompter
{
	private enum ETerminalState
	{
		MODIO_ACCOUNT,
		ROOM_SIZE,
		NUM_STATES
	}

	[SerializeField]
	private TMP_Text optionList;

	[SerializeField]
	private TMP_Text mainScreenText;

	[SerializeField]
	private CustomMapsKeyboard keyboard;

	[SerializeField]
	private List<string> optionStrings = new List<string> { "MOD.IO", "ROOM SIZE" };

	[SerializeField]
	private string loggedInAsString = "LOGGED INTO MOD.IO AS: ";

	[SerializeField]
	private string notLoggedInString = "LOGGED OUT OF MOD.IO";

	[SerializeField]
	private string loginPromptString = "PRESS THE 'PLATFORM LOGIN' OR 'LINK MOD.IO ACCOUNT' BUTTON TO LOGIN";

	[SerializeField]
	private string loggingInString = "LOGGING IN TO MOD.IO...";

	[SerializeField]
	private string loggingOutString = "LOGGING OUT OF MOD.IO...";

	[SerializeField]
	private string linkAccountPromptString = "IF YOU HAVE AN EXISTING MOD.IO ACCOUNT, YOU CAN LINK IT BY PRESSING THE 'LINK MOD.IO ACCOUNT' BUTTON.";

	[SerializeField]
	private string alreadyLinkedAccountString = "YOU'VE ALREADY LINKED YOUR MOD.IO ACCOUNT.";

	[SerializeField]
	private string accountLinkingPromptString = "PLEASE GO TO THIS URL IN YOUR BROWSER AND LOG IN TO YOUR MOD.IO ACCOUNT. ONCE LOGGED IN, ENTER THE FOLLOWING CODE TO PROCEED: ";

	[SerializeField]
	private string urlLabelString = "URL: ";

	[SerializeField]
	private string linkCodeLabelString = "CODE: ";

	[SerializeField]
	private string roomSizeDescriptionString = "THIS SETTING WILL CHANGE THE MAXIMUM AMOUNT OF PLAYERS ALLOWED IN PRIVATE ROOMS YOU CREATE. WHEN JOINING A PUBLIC ROOM, THE MAP YOU'VE LOADED WILL CONTROL THE ROOM SIZE.";

	[SerializeField]
	private string roomSizeLabelString = "MAX PLAYERS: ";

	[SerializeField]
	private GameObject OKButton;

	[SerializeField]
	private List<GameObject> contextualButtons = new List<GameObject>();

	[SerializeField]
	private List<GameObject> buttonsToShow_MODIO = new List<GameObject>();

	[SerializeField]
	private List<GameObject> buttonsToShow_ROOMSIZE = new List<GameObject>();

	private bool processingAccountLink;

	private string cachedLinkURL = "";

	private string cachedLinkCode = "";

	private string cachedError;

	private ETerminalState currentState;

	public void Start()
	{
		optionList.gameObject.SetActive(value: true);
		mainScreenText.gameObject.SetActive(value: true);
		RefreshButtonState();
		UpdateOptionListForCurrentState();
		UpdateScreen();
		keyboard?.OnKeyPressed.AddListener(OnKeyPressed);
		ModIOManager.OnModIOLoggedIn.AddListener(OnModIOLoggedIn);
		ModIOManager.OnModIOLoginStarted.AddListener(OnModIOLoginStarted);
		ModIOManager.OnModIOLoginFailed.AddListener(OnModIOLoginFailed);
		ModIOManager.OnModIOUserChanged.AddListener(OnModIOUserChanged);
	}

	public void OnDestroy()
	{
		keyboard?.OnKeyPressed.RemoveListener(OnKeyPressed);
		ModIOManager.OnModIOLoggedIn.RemoveListener(OnModIOLoggedIn);
		ModIOManager.OnModIOLoggedOut.RemoveListener(OnModIOLoggedOut);
		ModIOManager.OnModIOLoginStarted.RemoveListener(OnModIOLoginStarted);
		ModIOManager.OnModIOLoginFailed.RemoveListener(OnModIOLoginFailed);
		ModIOManager.OnModIOUserChanged.RemoveListener(OnModIOUserChanged);
	}

	public void OnEnable()
	{
		RefreshButtonState();
		UpdateOptionListForCurrentState();
		UpdateScreen();
	}

	private void OnKeyPressed(CustomMapKeyboardBinding pressedButton)
	{
		if (!cachedError.IsNullOrEmpty())
		{
			cachedError = null;
			RefreshButtonState();
			UpdateScreen();
			return;
		}
		switch (pressedButton)
		{
		case CustomMapKeyboardBinding.up:
		{
			int num2 = (int)(currentState - 1);
			if (num2 < 0)
			{
				num2 = 1;
			}
			ChangeState((ETerminalState)num2);
			UpdateOptionListForCurrentState();
			UpdateScreen();
			break;
		}
		case CustomMapKeyboardBinding.down:
		{
			int num = (int)(currentState + 1);
			if (num >= 2)
			{
				num = 0;
			}
			ChangeState((ETerminalState)num);
			UpdateOptionListForCurrentState();
			UpdateScreen();
			break;
		}
		default:
			switch (currentState)
			{
			case ETerminalState.MODIO_ACCOUNT:
				OnKeyPressed_ModIOAccount(pressedButton);
				break;
			case ETerminalState.ROOM_SIZE:
				OnKeyPressed_RoomSize(pressedButton);
				break;
			}
			break;
		}
	}

	private void ChangeState(ETerminalState newState)
	{
		if (newState != currentState)
		{
			currentState = newState;
			RefreshButtonState();
		}
	}

	private void RefreshButtonState()
	{
		for (int i = 0; i < contextualButtons.Count; i++)
		{
			if (contextualButtons[i].IsNotNull())
			{
				contextualButtons[i].SetActive(value: false);
			}
		}
		if (!cachedError.IsNullOrEmpty())
		{
			OKButton.SetActive(value: true);
			return;
		}
		switch (currentState)
		{
		case ETerminalState.MODIO_ACCOUNT:
		{
			for (int k = 0; k < buttonsToShow_MODIO.Count; k++)
			{
				if (buttonsToShow_MODIO[k].IsNotNull())
				{
					buttonsToShow_MODIO[k].SetActive(value: true);
				}
			}
			break;
		}
		case ETerminalState.ROOM_SIZE:
		{
			for (int j = 0; j < buttonsToShow_ROOMSIZE.Count; j++)
			{
				if (buttonsToShow_ROOMSIZE[j].IsNotNull())
				{
					buttonsToShow_ROOMSIZE[j].SetActive(value: true);
				}
			}
			break;
		}
		}
	}

	private void UpdateOptionListForCurrentState()
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < 2; i++)
		{
			stringBuilder.Append(optionStrings[i]);
			if (i == (int)currentState)
			{
				stringBuilder.Append(" <-");
			}
			stringBuilder.Append("\n");
		}
		optionList.text = stringBuilder.ToString();
	}

	private void UpdateScreen()
	{
		mainScreenText.text = "";
		if (!cachedError.IsNullOrEmpty())
		{
			RefreshButtonState();
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(cachedError);
			mainScreenText.text = "<color=\"red\">" + stringBuilder;
			return;
		}
		switch (currentState)
		{
		case ETerminalState.MODIO_ACCOUNT:
			mainScreenText.text = UpdateScreen_ModIOAccount();
			break;
		case ETerminalState.ROOM_SIZE:
			mainScreenText.text = UpdateScreen_RoomSize();
			break;
		}
	}

	private void OnModIOLoginStarted()
	{
		UpdateScreen();
	}

	private void OnModIOLoggedIn()
	{
		ModIOManager.OnModIOLoggedOut.RemoveListener(OnModIOLoggedOut);
		ModIOManager.OnModIOLoggedOut.AddListener(OnModIOLoggedOut);
		processingAccountLink = false;
		UpdateScreen();
		StartCoroutine(ModIOManager.AssociateMothershipAndModIOAccounts(new AssociateMotherhsipAndModIOAccountsRequest
		{
			ModIOId = ModIOManager.GetCurrentUserId(),
			ModIOToken = ModIOManager.GetCurrentAuthToken(),
			MothershipEnvId = MothershipClientApiUnity.EnvironmentId,
			MothershipPlayerId = MothershipClientContext.MothershipId,
			MothershipToken = MothershipClientContext.Token
		}, delegate
		{
		}));
	}

	private void OnModIOLoggedOut()
	{
		ModIOManager.OnModIOLoggedOut.RemoveListener(OnModIOLoggedOut);
		processingAccountLink = false;
		UpdateScreen();
	}

	private void OnModIOLoginFailed(string error)
	{
		processingAccountLink = false;
		cachedError = error;
		UpdateScreen();
	}

	private void OnModIOUserChanged(Modio.Users.User user)
	{
		UpdateScreen();
	}

	private void OnKeyPressed_ModIOAccount(CustomMapKeyboardBinding pressedButton)
	{
		if (pressedButton == CustomMapKeyboardBinding.option1)
		{
			StartAccountLinkingProcess();
		}
		if (pressedButton == CustomMapKeyboardBinding.option2)
		{
			GTDev.Log($"[VirtualStumpOptionsTerminal::OnKeyPressed_ModIOAccount] logout {ModIOManager.IsLoggedIn()}");
			if (ModIOManager.IsLoggedIn())
			{
				ModIOManager.LogoutFromModIO();
			}
		}
		if (pressedButton != CustomMapKeyboardBinding.option3)
		{
			return;
		}
		GTDev.Log($"[VirtualStumpOptionsTerminal::OnKeyPressed_ModIOAccount] login {ModIOManager.IsLoggedIn()}");
		if (!ModIOManager.IsLoggedIn())
		{
			ModIOManager.CancelExternalAuthentication();
			try
			{
				ModIOManager.RequestPlatformLogin();
			}
			catch (Exception arg)
			{
				GTDev.Log($"VirtualStumpOptionsTerminal::OnKeyPressed_ModIOAccount platform login error: {arg}");
				throw;
			}
		}
	}

	private async Task StartAccountLinkingProcess()
	{
		if (!processingAccountLink)
		{
			processingAccountLink = true;
			if (ModIOManager.IsAuthenticated())
			{
				if (ModIOManager.GetLastAuthMethod() == ModIOManager.ModIOAuthMethod.LinkedAccount)
				{
					ModIOManager.OnModIOLoggedIn.RemoveListener(OnModIOLoggedIn);
					ModIOManager.OnModIOLoggedIn.AddListener(OnModIOLoggedIn);
					ModIOManager.OnModIOUserChanged.RemoveListener(OnModIOUserChanged);
					ModIOManager.OnModIOUserChanged.AddListener(OnModIOUserChanged);
					processingAccountLink = false;
					return;
				}
				ModIOManager.OnModIOLoggedOut.RemoveListener(OnModIOLoggedOut);
				ModIOManager.LogoutFromModIO();
				ModIOManager.OnModIOLoggedIn.RemoveListener(OnModIOLoggedIn);
				ModIOManager.OnModIOLoggedIn.AddListener(OnModIOLoggedIn);
				ModIOManager.OnModIOUserChanged.RemoveListener(OnModIOUserChanged);
				ModIOManager.OnModIOUserChanged.AddListener(OnModIOUserChanged);
			}
			ModIOManager.SetAccountLinkPrompter(this);
			Modio.Error error = await ModIOManager.RequestAccountLinkCode();
			if ((bool)error)
			{
				UnityEngine.Debug.LogError("[ModIOAccountLinkingTerminal::StartAccountLinkingProcess] Failed to log in to mod.io: " + error.GetMessage());
				cachedError = error.GetMessage() + "\n\nPRESS THE 'LINK MOD.IO ACCOUNT' BUTTON TO RETRY.";
				processingAccountLink = false;
				UpdateScreen();
			}
		}
		else
		{
			UpdateScreen();
		}
	}

	public void ShowPrompt(string url, string code)
	{
		cachedLinkURL = url;
		cachedLinkCode = code;
		UpdateScreen();
	}

	private string UpdateScreen_ModIOAccount()
	{
		StringBuilder stringBuilder = new StringBuilder();
		if (ModIOManager.IsLoggedIn())
		{
			stringBuilder.Append(loggedInAsString + "\n");
			stringBuilder.Append("   " + ModIOManager.GetCurrentUsername() + "\n\n");
			if (ModIOManager.GetLastAuthMethod() != ModIOManager.ModIOAuthMethod.LinkedAccount)
			{
				stringBuilder.Append(linkAccountPromptString + "\n");
			}
			else
			{
				stringBuilder.Append(alreadyLinkedAccountString + "\n");
			}
		}
		else if (ModIOManager.IsLoggingIn() && !processingAccountLink)
		{
			stringBuilder.Append(loggingInString);
		}
		else if (ModIOManager.IsLoggingOut())
		{
			stringBuilder.Append(loggingOutString);
		}
		else if (processingAccountLink)
		{
			stringBuilder.Append(linkAccountPromptString + "\n\n");
			stringBuilder.Append(urlLabelString + cachedLinkURL + "\n");
			stringBuilder.Append(linkCodeLabelString + cachedLinkCode + "\n");
		}
		else
		{
			stringBuilder.Append(notLoggedInString + "\n\n");
			stringBuilder.Append(loginPromptString);
		}
		return stringBuilder.ToString();
	}

	private void OnKeyPressed_RoomSize(CustomMapKeyboardBinding pressedButton)
	{
		if (pressedButton == CustomMapKeyboardBinding.left)
		{
			DecrementRoomSize();
		}
		if (pressedButton == CustomMapKeyboardBinding.right)
		{
			IncrementRoomSize();
		}
		UpdateScreen();
	}

	private void DecrementRoomSize()
	{
		RoomSystem.OverrideRoomSize((byte)(RoomSystem.GetOverridenRoomSize() - 1));
		UpdateScreen();
	}

	private void IncrementRoomSize()
	{
		RoomSystem.OverrideRoomSize((byte)(RoomSystem.GetOverridenRoomSize() + 1));
		UpdateScreen();
	}

	private string UpdateScreen_RoomSize()
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append(roomSizeDescriptionString + "\n\n");
		stringBuilder.Append(roomSizeLabelString + RoomSystem.GetOverridenRoomSize());
		return stringBuilder.ToString();
	}
}
public class VirtualStumpBarrierSFX : MonoBehaviour
{
	[SerializeField]
	private AudioSource barrierAudioSource;

	[FormerlySerializedAs("teleportingPlayerSoundClips")]
	[SerializeField]
	private List<AudioClip> PassThroughBarrierSoundClips = new List<AudioClip>();

	private Dictionary<GameObject, bool> trackedGameObjects = new Dictionary<GameObject, bool>();

	public void OnTriggerEnter(Collider other)
	{
		VRRig component;
		if (other.gameObject == GorillaTagger.Instance.headCollider.gameObject)
		{
			PlaySFX();
		}
		else if (other.gameObject.TryGetComponent<VRRig>(out component) && !component.isLocal)
		{
			bool value = other.gameObject.transform.position.z < base.gameObject.transform.position.z;
			trackedGameObjects.Add(other.gameObject, value);
			OnTriggerStay(other);
		}
	}

	public void OnTriggerStay(Collider other)
	{
		if (trackedGameObjects.TryGetValue(other.gameObject, out var value))
		{
			bool flag = other.gameObject.transform.position.z < base.gameObject.transform.position.z;
			if (value != flag)
			{
				PlaySFX();
				trackedGameObjects.Remove(other.gameObject);
			}
		}
	}

	public void OnTriggerExit(Collider other)
	{
		if (trackedGameObjects.TryGetValue(other.gameObject, out var value))
		{
			bool flag = other.gameObject.transform.position.z < base.gameObject.transform.position.z;
			if (value != flag)
			{
				PlaySFX();
			}
			trackedGameObjects.Remove(other.gameObject);
		}
	}

	public void PlaySFX()
	{
		if (!GTExt.IsNull(barrierAudioSource) && !PassThroughBarrierSoundClips.IsNullOrEmpty())
		{
			barrierAudioSource.clip = PassThroughBarrierSoundClips[UnityEngine.Random.Range(0, PassThroughBarrierSoundClips.Count)];
			barrierAudioSource.Play();
		}
	}
}
public class VirtualStumpRevivePlayer : MonoBehaviour
{
	[SerializeField]
	private GhostReactorManager ghostReactorManager;

	[SerializeField]
	private GRReviveStation defaultReviveStation;

	private void OnTriggerEnter(Collider collider)
	{
		Rigidbody attachedRigidbody = collider.attachedRigidbody;
		if (!(attachedRigidbody != null))
		{
			return;
		}
		VRRig component = attachedRigidbody.GetComponent<VRRig>();
		if (!(component != null))
		{
			return;
		}
		GRPlayer component2 = component.GetComponent<GRPlayer>();
		if (component2 != null && (component2.State != GRPlayer.GRPlayerState.Alive || component2.Hp < component2.MaxHp))
		{
			if (!NetworkSystem.Instance.InRoom && component == VRRig.LocalRig)
			{
				defaultReviveStation.RevivePlayer(component2);
			}
			if (ghostReactorManager.IsAuthority())
			{
				ghostReactorManager.RequestPlayerRevive(defaultReviveStation, component2);
			}
		}
	}
}
internal class VirtualStumpSerializer : GorillaSerializer
{
	[SerializeField]
	private VirtualStumpBarrierSFX barrierSFX;

	[SerializeField]
	private CustomMapsDisplayScreen detailsScreen;

	private static bool waitingForRoomInitialization;

	private static bool roomInitialized;

	private bool sendModList;

	private bool forceNewSearch;

	private bool waitToSendStatus;

	private bool sendNewStatus;

	private const float STATUS_UPDATE_INTERVAL = 0.5f;

	private Coroutine statusUpdateCoroutine;

	internal bool HasAuthority => photonView.IsMine;

	protected void Start()
	{
		NetworkSystem.Instance.OnMultiplayerStarted += new Action(OnJoinedRoom);
		NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(OnLeftRoom);
		NetworkSystem.Instance.OnPlayerLeft += new Action<NetPlayer>(OnPlayerLeftRoom);
	}

	private void OnPlayerLeftRoom(NetPlayer leavingPlayer)
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			int driverID = CustomMapsTerminal.GetDriverID();
			if (leavingPlayer.ActorNumber == driverID)
			{
				CustomMapsTerminal.SetTerminalControlStatus(isLocked: false, -2, sendRPC: true);
			}
		}
	}

	private void OnJoinedRoom()
	{
		if (NetworkSystem.Instance.IsMasterClient)
		{
			roomInitialized = true;
			return;
		}
		UnityEngine.Debug.Log("[VirtualStumpSerializer::OnJoinedRoom] Requesting Room Initialization...");
		waitingForRoomInitialization = true;
		SendRPC("RequestRoomInitialization_RPC", false);
	}

	private void OnLeftRoom()
	{
		UnityEngine.Debug.Log("[VirtualStumpSerializer::OnLeftRoom]...");
		roomInitialized = false;
	}

	public static bool IsWaitingForRoomInit()
	{
		if (!waitingForRoomInitialization)
		{
			return !roomInitialized;
		}
		return true;
	}

	[PunRPC]
	private void RequestRoomInitialization_RPC(PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "RequestRoomInitialization_RPC");
		if (NetworkSystem.Instance.IsMasterClient)
		{
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (!player.CheckSingleCallRPC(NetPlayer.SingleCallRPC.CMS_RequestRoomInitialization))
			{
				player.ReceivedSingleCallRPC(NetPlayer.SingleCallRPC.CMS_RequestRoomInitialization);
				long id = CustomMapManager.GetRoomMapId()._id;
				SendRPC("InitializeRoom_RPC", info.Sender, CustomMapsTerminal.CurrentScreen, CustomMapsTerminal.GetDriverID(), CustomMapsTerminal.LocalModDetailsID, id);
			}
		}
	}

	[PunRPC]
	private void InitializeRoom_RPC(int currentScreen, int driverID, long modDetailsID, long loadedMapModID, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "InitializeRoom_RPC");
		if (info.Sender.IsMasterClient && waitingForRoomInitialization && (driverID == -2 || NetworkSystem.Instance.GetPlayer(driverID) != null))
		{
			CustomMapsTerminal.UpdateFromDriver(currentScreen, modDetailsID, driverID);
			if (loadedMapModID > 0)
			{
				CustomMapManager.SetRoomMap(loadedMapModID);
			}
			roomInitialized = true;
			waitingForRoomInitialization = false;
			UnityEngine.Debug.Log("[VStumpSerializer.InitializeRPC] Room initialization finished.");
		}
	}

	public void LoadMapSynced(long modId)
	{
		CustomMapManager.SetRoomMap(modId);
		CustomMapManager.LoadMap(new ModId(modId));
		if (NetworkSystem.Instance.InRoom && NetworkSystem.Instance.SessionIsPrivate)
		{
			SendRPC("SetRoomMap_RPC", true, modId);
		}
	}

	public void UnloadMapSynced()
	{
		CustomMapManager.UnloadMap();
		if (NetworkSystem.Instance.InRoom && NetworkSystem.Instance.SessionIsPrivate)
		{
			SendRPC("UnloadMap_RPC", true);
		}
	}

	[PunRPC]
	private void SetRoomMap_RPC(long modId, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "SetRoomMap_RPC");
		if (modId > 0 && (info.Sender.ActorNumber == photonView.OwnerActorNr || info.Sender.ActorNumber == CustomMapsTerminal.GetDriverID()) && modId == detailsScreen.currentMapMod.Id._id)
		{
			CustomMapManager.SetRoomMap(modId);
		}
	}

	[PunRPC]
	private void UnloadMap_RPC(PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "UnloadMap_RPC");
		if (info.Sender.ActorNumber == CustomMapsTerminal.GetDriverID() && CustomMapManager.AreAllPlayersInVirtualStump())
		{
			CustomMapManager.UnloadMap();
		}
	}

	public void RequestTerminalControlStatusChange(bool lockedStatus)
	{
		if (NetworkSystem.Instance.InRoom)
		{
			SendRPC("RequestTerminalControlStatusChange_RPC", false, lockedStatus);
		}
	}

	[PunRPC]
	private void RequestTerminalControlStatusChange_RPC(bool lockedStatus, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "RequestTerminalControlStatusChange_RPC");
		if (NetworkSystem.Instance.IsMasterClient)
		{
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (VRRigCache.Instance.TryGetVrrig(player, out var playerRig) && playerRig.Rig.fxSettings.callSettings[19].CallLimitSettings.CheckCallTime(Time.unscaledTime) && !player.IsNull && CustomMapManager.IsRemotePlayerInVirtualStump(info.Sender.UserId))
			{
				CustomMapsTerminal.HandleTerminalControlStatusChangeRequest(lockedStatus, info.Sender.ActorNumber);
			}
		}
	}

	public void SetTerminalControlStatus(bool locked, int playerID)
	{
		if (NetworkSystem.Instance.InRoom && NetworkSystem.Instance.IsMasterClient)
		{
			SendRPC("SetTerminalControlStatus_RPC", true, locked, playerID);
		}
	}

	[PunRPC]
	private void SetTerminalControlStatus_RPC(bool locked, int driverID, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "SetTerminalControlStatus_RPC");
		if (info.Sender.IsMasterClient && (driverID == -2 || NetworkSystem.Instance.GetPlayer(driverID) != null))
		{
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (VRRigCache.Instance.TryGetVrrig(player, out var playerRig) && playerRig.Rig.fxSettings.callSettings[16].CallLimitSettings.CheckCallTime(Time.unscaledTime))
			{
				CustomMapsTerminal.SetTerminalControlStatus(locked, driverID);
			}
		}
	}

	public void SendTerminalStatus()
	{
		if (NetworkSystem.Instance.InRoom && CustomMapsTerminal.IsDriver)
		{
			if (statusUpdateCoroutine != null)
			{
				StopCoroutine(statusUpdateCoroutine);
			}
			statusUpdateCoroutine = StartCoroutine(WaitToSendStatus());
		}
	}

	private IEnumerator WaitToSendStatus()
	{
		yield return new WaitForSeconds(0.5f);
		SendRPC("UpdateScreen_RPC", true, CustomMapsTerminal.CurrentScreen, CustomMapsTerminal.LocalModDetailsID, CustomMapsTerminal.GetDriverID());
	}

	[PunRPC]
	private void UpdateScreen_RPC(int currentScreen, long modDetailsID, int driverID, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "UpdateScreen_RPC");
		if (info.Sender.ActorNumber == CustomMapsTerminal.GetDriverID() && CustomMapManager.IsRemotePlayerInVirtualStump(info.Sender.UserId) && currentScreen >= -1 && currentScreen <= 6 && NetworkSystem.Instance.GetPlayer(driverID) != null)
		{
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (VRRigCache.Instance.TryGetVrrig(player, out var playerRig) && playerRig.Rig.fxSettings.callSettings[17].CallLimitSettings.CheckCallTime(Time.unscaledTime))
			{
				CustomMapsTerminal.UpdateFromDriver(currentScreen, modDetailsID, driverID);
			}
		}
	}

	public void RefreshDriverNickName()
	{
		if (NetworkSystem.Instance.InRoom)
		{
			SendRPC("RefreshDriverNickName_RPC", true);
		}
	}

	[PunRPC]
	private void RefreshDriverNickName_RPC(PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "RefreshDriverNickName_RPC");
		if (info.Sender.ActorNumber == CustomMapsTerminal.GetDriverID())
		{
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (VRRigCache.Instance.TryGetVrrig(player, out var playerRig) && playerRig.Rig.fxSettings.callSettings[18].CallLimitSettings.CheckCallTime(Time.unscaledTime))
			{
				CustomMapsTerminal.RefreshDriverNickName();
			}
		}
	}
}
public class VirtualStumpTeleporter : MonoBehaviour, IBuildValidation, IGorillaSliceableSimple
{
	[SerializeField]
	private float stayInTriggerDuration = 3f;

	[SerializeField]
	private TMP_Text[] countdownTexts;

	[SerializeField]
	private GameObject[] handHoldObjects;

	[SerializeField]
	private List<GameObject> accessDeniedDisabledObjects = new List<GameObject>();

	[SerializeField]
	private List<GameObject> accessDeniedEnabledObjects = new List<GameObject>();

	[SerializeField]
	private Transform returnLocation;

	[SerializeField]
	private GTZone entranceZone = GTZone.arcade;

	[SerializeField]
	private GorillaNetworkJoinTrigger exitVStumpJoinTrigger;

	[SerializeField]
	private long autoLoadMapModId = ModId.Null;

	[SerializeField]
	private GameModeType autoLoadGamemode = GameModeType.None;

	[SerializeField]
	private GameModeType forcedGamemodeUponReturn = GameModeType.None;

	[SerializeField]
	private ParticleSystem teleportToVStumpVFX;

	[SerializeField]
	private ParticleSystem returnFromVStumpVFX;

	[SerializeField]
	private AudioSource teleporterSFXAudioSource;

	[SerializeField]
	private List<AudioClip> teleportingPlayerSoundClips = new List<AudioClip>();

	[SerializeField]
	private List<AudioClip> observerSoundClips = new List<AudioClip>();

	[SerializeField]
	private VirtualStumpTeleporterSerializer netSerializer;

	private VirtualStumpTeleporterSerializer mySerializer;

	private bool accessDenied;

	private bool teleporting;

	private float triggerEntryTime = -1f;

	[OnEnterPlay_Set(0)]
	private static ushort lastLoggingHandsMsgId;

	public bool BuildValidationCheck()
	{
		if (GTExt.IsNull(netSerializer))
		{
			UnityEngine.Debug.LogError("VStump Teleporter \"" + base.gameObject.GetPath() + "\" needs a reference to a VirtualStumpTeleporterSerializer for networked FX to function. Check out the teleporter prefabs in arcade or the stump", this);
			return false;
		}
		return true;
	}

	public void SliceUpdate()
	{
		if (!accessDenied && NetworkSystem.Instance.netState != NetSystemState.Idle && NetworkSystem.Instance.netState != NetSystemState.InGame)
		{
			DenyAccess();
		}
		if (accessDenied && (NetworkSystem.Instance.netState == NetSystemState.Idle || NetworkSystem.Instance.netState == NetSystemState.InGame) && !UGCPermissionManager.IsUGCDisabled)
		{
			AllowAccess();
		}
	}

	public void OnEnable()
	{
		if (GTExt.IsNull(netSerializer))
		{
			UnityEngine.Debug.LogWarning("[VStumpTeleporter.OnEnable] Net Serializer is null for \"" + base.gameObject.GetPath() + "\", networked teleport FX will not function.");
		}
		if (UGCPermissionManager.IsUGCDisabled || (NetworkSystem.Instance.netState != NetSystemState.Idle && NetworkSystem.Instance.netState != NetSystemState.InGame))
		{
			_ = lastLoggingHandsMsgId;
			_ = 1;
			lastLoggingHandsMsgId = 1;
			DenyAccess();
		}
		else
		{
			_ = lastLoggingHandsMsgId;
			_ = 2;
			lastLoggingHandsMsgId = 2;
			AllowAccess();
		}
		UGCPermissionManager.SubscribeToUGCEnabled(OnUGCEnabled);
		UGCPermissionManager.SubscribeToUGCDisabled(OnUGCDisabled);
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		AllowAccess();
		UGCPermissionManager.UnsubscribeFromUGCEnabled(OnUGCEnabled);
		UGCPermissionManager.UnsubscribeFromUGCDisabled(OnUGCDisabled);
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	private void OnUGCEnabled()
	{
		AllowAccess();
		_ = lastLoggingHandsMsgId;
		_ = 3;
		lastLoggingHandsMsgId = 3;
	}

	private void OnUGCDisabled()
	{
		DenyAccess();
		_ = lastLoggingHandsMsgId;
		_ = 4;
		lastLoggingHandsMsgId = 4;
	}

	public void OnTriggerEnter(Collider other)
	{
		if (!UGCPermissionManager.IsUGCDisabled && !accessDenied && !teleporting && !CustomMapManager.WaitingForRoomJoin && !CustomMapManager.WaitingForDisconnect && other.gameObject == GorillaTagger.Instance.headCollider.gameObject)
		{
			triggerEntryTime = Time.time;
			ShowCountdownText();
		}
	}

	public void OnTriggerStay(Collider other)
	{
		if (!UGCPermissionManager.IsUGCDisabled && !accessDenied && other.gameObject == GorillaTagger.Instance.headCollider.gameObject && triggerEntryTime >= 0f)
		{
			UpdateCountdownText();
			if (!teleporting && triggerEntryTime + stayInTriggerDuration <= Time.time)
			{
				TeleportPlayer();
				HideCountdownText();
			}
		}
	}

	public void OnTriggerExit(Collider other)
	{
		if (!UGCPermissionManager.IsUGCDisabled && !accessDenied && other.gameObject == GorillaTagger.Instance.headCollider.gameObject)
		{
			triggerEntryTime = -1f;
			HideCountdownText();
		}
	}

	private void ShowCountdownText()
	{
		if (UGCPermissionManager.IsUGCDisabled || accessDenied || countdownTexts.IsNullOrEmpty())
		{
			return;
		}
		int num = 1 + Mathf.FloorToInt(stayInTriggerDuration);
		for (int i = 0; i < countdownTexts.Length; i++)
		{
			if (!GTExt.IsNull(countdownTexts[i]))
			{
				countdownTexts[i].text = num.ToString();
				countdownTexts[i].gameObject.SetActive(value: true);
			}
		}
	}

	private void HideCountdownText()
	{
		if (countdownTexts.IsNullOrEmpty())
		{
			return;
		}
		for (int i = 0; i < countdownTexts.Length; i++)
		{
			if (!GTExt.IsNull(countdownTexts[i]))
			{
				countdownTexts[i].text = "";
				countdownTexts[i].gameObject.SetActive(value: false);
			}
		}
	}

	private void UpdateCountdownText()
	{
		if (UGCPermissionManager.IsUGCDisabled || accessDenied || countdownTexts.IsNullOrEmpty())
		{
			return;
		}
		float f = stayInTriggerDuration - (Time.time - triggerEntryTime);
		int num = 1 + Mathf.FloorToInt(f);
		for (int i = 0; i < countdownTexts.Length; i++)
		{
			if (!GTExt.IsNull(countdownTexts[i]))
			{
				countdownTexts[i].text = num.ToString();
			}
		}
	}

	public void TeleportPlayer()
	{
		if (!UGCPermissionManager.IsUGCDisabled && !accessDenied && !teleporting)
		{
			teleporting = true;
			CustomMapManager.TeleportToVirtualStump(this, FinishTeleport);
		}
	}

	private void FinishTeleport(bool success = true)
	{
		if (teleporting)
		{
			teleporting = false;
			triggerEntryTime = -1f;
		}
	}

	private void DenyAccess()
	{
		accessDenied = true;
		foreach (GameObject accessDeniedEnabledObject in accessDeniedEnabledObjects)
		{
			accessDeniedEnabledObject.SetActive(value: true);
		}
		foreach (GameObject accessDeniedDisabledObject in accessDeniedDisabledObjects)
		{
			accessDeniedDisabledObject.SetActive(value: false);
		}
	}

	private void AllowAccess()
	{
		if (UGCPermissionManager.IsUGCDisabled)
		{
			return;
		}
		accessDenied = false;
		foreach (GameObject accessDeniedEnabledObject in accessDeniedEnabledObjects)
		{
			accessDeniedEnabledObject.SetActive(value: false);
		}
		foreach (GameObject accessDeniedDisabledObject in accessDeniedDisabledObjects)
		{
			accessDeniedDisabledObject.SetActive(value: true);
		}
	}

	private short GetIndex()
	{
		if (!netSerializer.IsNotNull())
		{
			return -1;
		}
		return netSerializer.GetTeleporterIndex(this);
	}

	public GTZone GetZone()
	{
		return entranceZone;
	}

	public GorillaNetworkJoinTrigger GetExitVStumpJoinTrigger()
	{
		return exitVStumpJoinTrigger;
	}

	public Transform GetReturnTransform()
	{
		return returnLocation;
	}

	public long GetAutoLoadMapModId()
	{
		return autoLoadMapModId;
	}

	public GameModeType GetAutoLoadGamemode()
	{
		return autoLoadGamemode;
	}

	public GameModeType GetReturnGamemode()
	{
		return forcedGamemodeUponReturn;
	}

	public void PlayTeleportEffects(bool forLocalPlayer, bool toVStump, AudioSource vStumpSFXAudioSource = null, bool sendRPC = false)
	{
		if (sendRPC && netSerializer.IsNotNull())
		{
			netSerializer.NotifyPlayerTeleporting(GetIndex(), vStumpSFXAudioSource);
		}
		ParticleSystem particleSystem;
		if (toVStump)
		{
			particleSystem = teleportToVStumpVFX;
			if (forLocalPlayer && vStumpSFXAudioSource.IsNotNull() && !teleportingPlayerSoundClips.IsNullOrEmpty())
			{
				vStumpSFXAudioSource.clip = teleportingPlayerSoundClips[UnityEngine.Random.Range(0, teleportingPlayerSoundClips.Count)];
				vStumpSFXAudioSource.Play();
			}
			if (!forLocalPlayer && teleporterSFXAudioSource.IsNotNull() && !observerSoundClips.IsNullOrEmpty())
			{
				teleporterSFXAudioSource.clip = observerSoundClips[UnityEngine.Random.Range(0, observerSoundClips.Count)];
				teleporterSFXAudioSource.Play();
			}
		}
		else
		{
			particleSystem = returnFromVStumpVFX;
			if (teleporterSFXAudioSource.IsNotNull())
			{
				if (forLocalPlayer && !teleportingPlayerSoundClips.IsNullOrEmpty())
				{
					teleporterSFXAudioSource.clip = teleportingPlayerSoundClips[UnityEngine.Random.Range(0, teleportingPlayerSoundClips.Count)];
				}
				else if (!forLocalPlayer && !observerSoundClips.IsNullOrEmpty())
				{
					teleporterSFXAudioSource.clip = observerSoundClips[UnityEngine.Random.Range(0, observerSoundClips.Count)];
				}
				teleporterSFXAudioSource.Play();
			}
		}
		if (particleSystem.IsNotNull())
		{
			particleSystem.Play();
		}
	}
}
internal class VirtualStumpTeleporterSerializer : GorillaSerializer
{
	[SerializeField]
	public List<VirtualStumpTeleporter> teleporters = new List<VirtualStumpTeleporter>();

	[SerializeField]
	public List<ParticleSystem> teleporterVFX = new List<ParticleSystem>();

	[SerializeField]
	public List<ParticleSystem> returnVFX = new List<ParticleSystem>();

	[SerializeField]
	public List<AudioSource> teleportAudioSource = new List<AudioSource>();

	[SerializeField]
	public List<AudioClip> teleportingPlayerSoundClips = new List<AudioClip>();

	[SerializeField]
	public List<AudioClip> observerSoundClips = new List<AudioClip>();

	public void NotifyPlayerTeleporting(short teleporterIdx, AudioSource localPlayerTeleporterAudioSource)
	{
		if (teleporterIdx < teleporters.Count && PhotonNetwork.InRoom)
		{
			SendRPC("ActivateTeleportVFX", true, false, teleporterIdx);
		}
	}

	public void NotifyPlayerReturning(short teleporterIdx)
	{
		if (teleporterIdx < teleporters.Count)
		{
			UnityEngine.Debug.Log($"[VRTeleporterSerializer::NotifyPlayerReturning] Sending RPC to activate VFX at idx: {teleporterIdx}");
			if (PhotonNetwork.InRoom)
			{
				SendRPC("ActivateTeleportVFX", true, true, teleporterIdx);
			}
		}
	}

	[PunRPC]
	private void ActivateTeleportVFX(bool returning, short teleporterIdx, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "ActivateTeleportVFX");
		if (teleporterIdx >= teleporters.Count)
		{
			return;
		}
		NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
		if (VRRigCache.Instance.TryGetVrrig(player, out var playerRig) && playerRig.Rig.fxSettings.callSettings[13].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			VirtualStumpTeleporter virtualStumpTeleporter = teleporters[teleporterIdx];
			if (virtualStumpTeleporter.IsNotNull())
			{
				virtualStumpTeleporter.PlayTeleportEffects(forLocalPlayer: false, !returning);
			}
		}
	}

	public short GetTeleporterIndex(VirtualStumpTeleporter teleporter)
	{
		for (short num = 0; num < teleporters.Count; num++)
		{
			if (teleporters[num] == teleporter)
			{
				return num;
			}
		}
		return -1;
	}
}
[DefaultExecutionOrder(0)]
public class VRRigJobManager : MonoBehaviour
{
	private struct VRRigTransformInput
	{
		public UnityEngine.Vector3 rigPosition;

		public UnityEngine.Quaternion rigRotaton;
	}

	[BurstCompile]
	private struct VRRigTransformJob : IJobParallelForTransform
	{
		[Unity.Collections.ReadOnly]
		public NativeArray<VRRigTransformInput> input;

		public void Execute(int i, TransformAccess tA)
		{
			if (i < input.Length)
			{
				tA.position = input[i].rigPosition;
				tA.rotation = input[i].rigRotaton;
			}
		}
	}

	[OnEnterPlay_SetNull]
	private static VRRigJobManager _instance;

	private const int MaxSize = 19;

	private const int questJobThreads = 2;

	private List<VRRig> rigList = new List<VRRig>(19);

	private NativeArray<VRRigTransformInput> cachedInput;

	private TransformAccessArray tAA;

	private int actualListSz;

	private JobHandle jobHandle;

	private VRRigTransformJob job;

	public static VRRigJobManager Instance => _instance;

	private void Awake()
	{
		_instance = this;
		cachedInput = new NativeArray<VRRigTransformInput>(19, Unity.Collections.Allocator.Persistent);
		tAA = new TransformAccessArray(19, 2);
		job = default(VRRigTransformJob);
	}

	private void OnDestroy()
	{
		jobHandle.Complete();
		cachedInput.Dispose();
		tAA.Dispose();
	}

	public void RegisterVRRig(VRRig rig)
	{
		rigList.Add(rig);
		tAA.Add(rig.transform);
		actualListSz++;
	}

	public void DeregisterVRRig(VRRig rig)
	{
		if (ApplicationQuittingState.IsQuitting)
		{
			return;
		}
		rigList.Remove(rig);
		for (int num = actualListSz - 1; num >= 0; num--)
		{
			if (tAA[num] == rig.transform)
			{
				tAA.RemoveAtSwapBack(num);
				break;
			}
		}
		actualListSz--;
	}

	private void CopyInput()
	{
		for (int i = 0; i < actualListSz; i++)
		{
			cachedInput[i] = new VRRigTransformInput
			{
				rigPosition = rigList[i].jobPos,
				rigRotaton = rigList[i].jobRotation
			};
			tAA[i] = rigList[i].transform;
		}
	}

	public void Update()
	{
		jobHandle.Complete();
		for (int i = 0; i < rigList.Count; i++)
		{
			rigList[i].RemoteRigUpdate();
		}
		CopyInput();
		job.input = cachedInput;
		jobHandle = job.Schedule(tAA);
	}
}
