[NetworkBehaviourWeaved(1)]
public class WanderingGhost : NetworkComponent
{
	[Serializable]
	public struct Waypoint(bool visible, Transform tr)
	{
		[Tooltip("The ghost will be visible when its reached to this waypoint")]
		public bool _visible = visible;

		public Transform _transform = tr;
	}

	private enum ghostState
	{
		patrol,
		idle
	}

	public float patrolSpeed = 3f;

	public float idleStayDuration = 5f;

	public float sphereColliderRadius = 2f;

	public ThrowableSetDressing[] allFlowers;

	public UnityEngine.Vector3 flowerDisabledPosition;

	public float flowerSpawnRadius;

	public float flowerSpawnDuration;

	public LayerMask flowerGroundMask;

	public MeshRenderer mrenderer;

	public Material visibleMaterial;

	public Material scryableMaterial;

	public GameObject waypointsContainer;

	private ZoneBasedObject[] waypointRegions;

	private ZoneBasedObject lastWaypointRegion;

	private List<Waypoint> waypoints = new List<Waypoint>();

	private Waypoint currentWaypoint;

	public string debugForceWaypointRegion;

	[SerializeField]
	private AudioSource audioSource;

	public AudioClip[] appearAudio;

	public float idleVolume;

	public AudioClip patrolAudio;

	public float patrolVolume;

	private ghostState currentState;

	private float idlePassedTime;

	public UnityAction<GameObject> TriggerHauntedObjects;

	private UnityEngine.Vector3 hoverVelocity;

	public float hoverRectifyForce;

	public float hoverRandomForce;

	public float hoverDrag;

	private const int maxColliders = 10;

	private Collider[] hitColliders = new Collider[10];

	[WeaverGenerated]
	[DefaultForProperty("Data", 0, 1)]
	[DrawIf("IsEditorWritable", true, CompareOperator.Equal, DrawIfMode.ReadOnly)]
	private ghostState _Data;

	[Networked]
	[NetworkedWeaved(0, 1)]
	private unsafe ghostState Data
	{
		get
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing WanderingGhost.Data. Networked properties can only be accessed when Spawned() has been called.");
			}
			return *(ghostState*)((byte*)((NetworkBehaviour)this).Ptr + 0);
		}
		set
		{
			if (((NetworkBehaviour)this).Ptr == null)
			{
				throw new InvalidOperationException("Error when accessing WanderingGhost.Data. Networked properties can only be accessed when Spawned() has been called.");
			}
			*(ghostState*)((byte*)((NetworkBehaviour)this).Ptr + 0) = value;
		}
	}

	protected override void Start()
	{
		base.Start();
		waypointRegions = waypointsContainer.GetComponentsInChildren<ZoneBasedObject>();
		idlePassedTime = 0f;
		ThrowableSetDressing[] array = allFlowers;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].anchor.position = flowerDisabledPosition;
		}
		Invoke("DelayedStart", 0.5f);
	}

	private void DelayedStart()
	{
		PickNextWaypoint();
		base.transform.position = currentWaypoint._transform.position;
		PickNextWaypoint();
		ChangeState(ghostState.patrol);
	}

	private void LateUpdate()
	{
		UpdateState();
		hoverVelocity -= mrenderer.transform.localPosition * hoverRectifyForce * Time.deltaTime;
		hoverVelocity += UnityEngine.Random.insideUnitSphere * hoverRandomForce * Time.deltaTime;
		hoverVelocity = UnityEngine.Vector3.MoveTowards(hoverVelocity, UnityEngine.Vector3.zero, hoverDrag * Time.deltaTime);
		mrenderer.transform.localPosition += hoverVelocity * Time.deltaTime;
	}

	private void PickNextWaypoint()
	{
		if (waypoints.Count == 0 || lastWaypointRegion == null || !lastWaypointRegion.IsLocalPlayerInZone())
		{
			ZoneBasedObject zoneBasedObject = ZoneBasedObject.SelectRandomEligible(waypointRegions, debugForceWaypointRegion);
			if (zoneBasedObject == null)
			{
				zoneBasedObject = lastWaypointRegion;
			}
			if (zoneBasedObject == null)
			{
				return;
			}
			lastWaypointRegion = zoneBasedObject;
			waypoints.Clear();
			foreach (Transform item in zoneBasedObject.transform)
			{
				waypoints.Add(new Waypoint(item.name.Contains("_v_"), item));
			}
		}
		int index = UnityEngine.Random.Range(0, waypoints.Count);
		currentWaypoint = waypoints[index];
		waypoints.RemoveAt(index);
	}

	private void Patrol()
	{
		idlePassedTime = 0f;
		mrenderer.sharedMaterial = scryableMaterial;
		Transform transform = currentWaypoint._transform;
		base.transform.position = UnityEngine.Vector3.MoveTowards(base.transform.position, transform.position, patrolSpeed * Time.deltaTime);
		base.transform.rotation = UnityEngine.Quaternion.RotateTowards(base.transform.rotation, UnityEngine.Quaternion.LookRotation(transform.position - base.transform.position), 360f * Time.deltaTime);
	}

	private bool MaybeHideGhost()
	{
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, sphereColliderRadius, hitColliders);
		for (int i = 0; i < num; i++)
		{
			if (hitColliders[i].gameObject.IsOnLayer(UnityLayer.GorillaHand) || hitColliders[i].gameObject.IsOnLayer(UnityLayer.GorillaBodyCollider))
			{
				ChangeState(ghostState.patrol);
				return true;
			}
		}
		return false;
	}

	private void ChangeState(ghostState newState)
	{
		currentState = newState;
		mrenderer.sharedMaterial = ((newState == ghostState.idle) ? visibleMaterial : scryableMaterial);
		switch (newState)
		{
		case ghostState.patrol:
			audioSource.GTStop();
			audioSource.volume = patrolVolume;
			audioSource.clip = patrolAudio;
			audioSource.GTPlay();
			break;
		case ghostState.idle:
			audioSource.GTStop();
			audioSource.volume = idleVolume;
			audioSource.GTPlayOneShot(appearAudio.GetRandomItem());
			if (NetworkSystem.Instance.IsMasterClient)
			{
				SpawnFlowerNearby();
			}
			break;
		}
	}

	private void UpdateState()
	{
		if (!NetworkSystem.Instance.IsMasterClient)
		{
			return;
		}
		switch (currentState)
		{
		case ghostState.patrol:
			if (currentWaypoint._transform == null)
			{
				PickNextWaypoint();
				break;
			}
			Patrol();
			if (UnityEngine.Vector3.Distance(base.transform.position, currentWaypoint._transform.position) < 0.2f)
			{
				if (currentWaypoint._visible)
				{
					ChangeState(ghostState.idle);
				}
				else
				{
					PickNextWaypoint();
				}
			}
			break;
		case ghostState.idle:
			idlePassedTime += Time.deltaTime;
			if (idlePassedTime >= idleStayDuration || MaybeHideGhost())
			{
				PickNextWaypoint();
				ChangeState(ghostState.patrol);
			}
			break;
		}
	}

	private void HauntObjects()
	{
		Collider[] array = new Collider[20];
		int num = Physics.OverlapSphereNonAlloc(base.transform.position, sphereColliderRadius, array);
		for (int i = 0; i < num; i++)
		{
			if (array[i].CompareTag("HauntedObject"))
			{
				TriggerHauntedObjects?.Invoke(array[i].gameObject);
			}
		}
	}

	public override void WriteDataFusion()
	{
		Data = currentState;
	}

	public override void ReadDataFusion()
	{
		ReadDataShared(Data);
	}

	protected override void WriteDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (info.Sender == PhotonNetwork.MasterClient)
		{
			stream.SendNext(currentState);
		}
	}

	protected override void ReadDataPUN(PhotonStream stream, PhotonMessageInfo info)
	{
		if (info.Sender == PhotonNetwork.MasterClient)
		{
			ghostState state = (ghostState)stream.ReceiveNext();
			ReadDataShared(state);
		}
	}

	private void ReadDataShared(ghostState state)
	{
		ghostState num = currentState;
		currentState = state;
		if (num != currentState)
		{
			ChangeState(currentState);
		}
	}

	public override void OnOwnerChange(Player newOwner, Player previousOwner)
	{
		base.OnOwnerChange(newOwner, previousOwner);
		if (newOwner == PhotonNetwork.LocalPlayer)
		{
			ChangeState(currentState);
		}
	}

	private void SpawnFlowerNearby()
	{
		UnityEngine.Vector3 position = base.transform.position + UnityEngine.Vector3.down * 0.25f;
		if (Physics.Raycast(new Ray(base.transform.position + UnityEngine.Random.insideUnitCircle.x0y() * flowerSpawnRadius, UnityEngine.Vector3.down), out var hitInfo, 3f, flowerGroundMask))
		{
			position = hitInfo.point;
		}
		ThrowableSetDressing throwableSetDressing = null;
		int num = 0;
		ThrowableSetDressing[] array = allFlowers;
		foreach (ThrowableSetDressing throwableSetDressing2 in array)
		{
			if (!throwableSetDressing2.InHand())
			{
				num++;
				if (UnityEngine.Random.Range(0, num) == 0)
				{
					throwableSetDressing = throwableSetDressing2;
				}
			}
		}
		if (throwableSetDressing != null)
		{
			if (!throwableSetDressing.IsLocalOwnedWorldShareable)
			{
				throwableSetDressing.WorldShareableRequestOwnership();
			}
			throwableSetDressing.SetWillTeleport();
			throwableSetDressing.transform.position = position;
			throwableSetDressing.StartRespawnTimer(flowerSpawnDuration);
		}
	}

	[WeaverGenerated]
	public override void CopyBackingFieldsToState(bool P_0)
	{
		base.CopyBackingFieldsToState(P_0);
		Data = _Data;
	}

	[WeaverGenerated]
	public override void CopyStateToBackingFields()
	{
		base.CopyStateToBackingFields();
		_Data = Data;
	}
}
public class ZoneBasedObject : MonoBehaviour
{
	public GTZone[] zones;

	public bool IsLocalPlayerInZone()
	{
		GTZone[] array = zones;
		for (int i = 0; i < array.Length; i++)
		{
			if (ZoneManagement.IsInZone(array[i]))
			{
				return true;
			}
		}
		return false;
	}

	public static ZoneBasedObject SelectRandomEligible(ZoneBasedObject[] objects, string overrideChoice = "")
	{
		ZoneBasedObject[] array;
		if (overrideChoice != "")
		{
			array = objects;
			foreach (ZoneBasedObject zoneBasedObject in array)
			{
				if (zoneBasedObject.gameObject.name == overrideChoice)
				{
					return zoneBasedObject;
				}
			}
		}
		ZoneBasedObject result = null;
		int num = 0;
		array = objects;
		foreach (ZoneBasedObject zoneBasedObject2 in array)
		{
			if (!zoneBasedObject2.gameObject.activeInHierarchy)
			{
				continue;
			}
			GTZone[] array2 = zoneBasedObject2.zones;
			for (int j = 0; j < array2.Length; j++)
			{
				if (ZoneManagement.IsInZone(array2[j]))
				{
					if (UnityEngine.Random.Range(0, num) == 0)
					{
						result = zoneBasedObject2;
					}
					num++;
					break;
				}
			}
		}
		return result;
	}
}
public class HalloweenWatcherEyes : MonoBehaviour
{
	public float timeBetweenUpdates = 5f;

	public float watchRange;

	public float watchMaxAngle;

	public float lerpDuration = 1f;

	public float playersViewCenterAngle = 30f;

	public float durationToBeNormalWhenPlayerLooks = 3f;

	public GameObject leftEye;

	public GameObject rightEye;

	private float playersViewCenterCosAngle;

	private float watchMinCosAngle;

	private float pretendingToBeNormalUntilTimestamp;

	private float lerpValue;

	private void Start()
	{
		playersViewCenterCosAngle = Mathf.Cos(playersViewCenterAngle * (MathF.PI / 180f));
		watchMinCosAngle = Mathf.Cos(watchMaxAngle * (MathF.PI / 180f));
		StartCoroutine(CheckIfNearPlayer(UnityEngine.Random.Range(0f, timeBetweenUpdates)));
		base.enabled = false;
	}

	private IEnumerator CheckIfNearPlayer(float initialSleep)
	{
		yield return new WaitForSeconds(initialSleep);
		while (true)
		{
			base.enabled = (base.transform.position - GTPlayer.Instance.transform.position).sqrMagnitude < watchRange * watchRange;
			if (!base.enabled)
			{
				LookNormal();
			}
			yield return new WaitForSeconds(timeBetweenUpdates);
		}
	}

	private void Update()
	{
		UnityEngine.Vector3 normalized = (GTPlayer.Instance.headCollider.transform.position - base.transform.position).normalized;
		if (UnityEngine.Vector3.Dot(GTPlayer.Instance.headCollider.transform.forward, -normalized) > playersViewCenterCosAngle)
		{
			LookNormal();
			pretendingToBeNormalUntilTimestamp = Time.time + durationToBeNormalWhenPlayerLooks;
		}
		if (pretendingToBeNormalUntilTimestamp > Time.time)
		{
			return;
		}
		if (UnityEngine.Vector3.Dot(base.transform.forward, normalized) < watchMinCosAngle)
		{
			LookNormal();
			return;
		}
		UnityEngine.Quaternion b = UnityEngine.Quaternion.LookRotation(normalized, base.transform.up);
		UnityEngine.Quaternion rotation = UnityEngine.Quaternion.Lerp(base.transform.rotation, b, lerpValue);
		leftEye.transform.rotation = rotation;
		rightEye.transform.rotation = rotation;
		if (lerpDuration > 0f)
		{
			lerpValue = Mathf.MoveTowards(lerpValue, 1f, Time.deltaTime / lerpDuration);
		}
		else
		{
			lerpValue = 1f;
		}
	}

	private void LookNormal()
	{
		leftEye.transform.localRotation = UnityEngine.Quaternion.identity;
		rightEye.transform.localRotation = UnityEngine.Quaternion.identity;
		lerpValue = 0f;
	}
}
public static class AESHMAC
{
	private static readonly RandomNumberGenerator gRNG = RandomNumberGenerator.Create();

	public const int BlockBitSize = 128;

	public const int KeyBitSize = 256;

	public const int SaltBitSize = 64;

	public const int Iterations = 10000;

	public const int MinPasswordLength = 12;

	public static byte[] NewKey()
	{
		byte[] array = new byte[32];
		gRNG.GetBytes(array);
		return array;
	}

	public static string SimpleEncrypt(string plaintext, byte[] key, byte[] auth, byte[] salt = null)
	{
		if (string.IsNullOrEmpty(plaintext))
		{
			throw new ArgumentNullException("plaintext");
		}
		return Convert.ToBase64String(SimpleEncrypt(Encoding.UTF8.GetBytes(plaintext), key, auth, salt));
	}

	public static string SimpleDecrypt(string ciphertext, byte[] key, byte[] auth, int saltLength = 0)
	{
		if (string.IsNullOrWhiteSpace(ciphertext))
		{
			throw new ArgumentNullException("ciphertext");
		}
		byte[] array = SimpleDecrypt(Convert.FromBase64String(ciphertext), key, auth, saltLength);
		if (array != null)
		{
			return Encoding.UTF8.GetString(array);
		}
		return null;
	}

	public static string SimpleEncryptWithKey(string plaintext, string key, byte[] salt = null)
	{
		if (string.IsNullOrEmpty(plaintext))
		{
			throw new ArgumentNullException("plaintext");
		}
		return Convert.ToBase64String(SimpleEncryptWithKey(Encoding.UTF8.GetBytes(plaintext), key, salt));
	}

	public static string SimpleDecryptWithKey(string ciphertext, string key, int saltLength = 0)
	{
		if (string.IsNullOrWhiteSpace(ciphertext))
		{
			throw new ArgumentNullException("ciphertext");
		}
		byte[] array = SimpleDecryptWithKey(Convert.FromBase64String(ciphertext), key, saltLength);
		if (array != null)
		{
			return Encoding.UTF8.GetString(array);
		}
		return null;
	}

	public static byte[] SimpleEncrypt(byte[] plaintext, byte[] key, byte[] auth, byte[] salt = null)
	{
		if (key == null || key.Length != 32)
		{
			throw new ArgumentException($"Key must be {256} bits", "key");
		}
		if (auth == null || auth.Length != 32)
		{
			throw new ArgumentException($"Auth must be {256} bits", "auth");
		}
		if (plaintext == null || plaintext.Length < 1)
		{
			throw new ArgumentNullException("plaintext");
		}
		if (salt == null)
		{
			salt = new byte[0];
		}
		byte[] iV;
		byte[] buffer;
		using (AesManaged aesManaged = new AesManaged
		{
			KeySize = 256,
			BlockSize = 128,
			Mode = CipherMode.CBC,
			Padding = PaddingMode.PKCS7
		})
		{
			aesManaged.GenerateIV();
			iV = aesManaged.IV;
			using ICryptoTransform transform = aesManaged.CreateEncryptor(key, iV);
			using MemoryStream memoryStream = new MemoryStream();
			using (CryptoStream output = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write))
			{
				using BinaryWriter binaryWriter = new BinaryWriter(output);
				binaryWriter.Write(plaintext);
			}
			buffer = memoryStream.ToArray();
		}
		using HMACSHA256 hMACSHA = new HMACSHA256(auth);
		using MemoryStream memoryStream2 = new MemoryStream();
		using (BinaryWriter binaryWriter2 = new BinaryWriter(memoryStream2))
		{
			binaryWriter2.Write(salt);
			binaryWriter2.Write(iV);
			binaryWriter2.Write(buffer);
			binaryWriter2.Flush();
			byte[] buffer2 = hMACSHA.ComputeHash(memoryStream2.ToArray());
			binaryWriter2.Write(buffer2);
		}
		return memoryStream2.ToArray();
	}

	public static byte[] SimpleDecrypt(byte[] ciphertext, byte[] key, byte[] auth, int saltLength = 0)
	{
		if (key == null || key.Length != 32)
		{
			throw new ArgumentException($"Key must be {256} bits", "key");
		}
		if (auth == null || auth.Length != 32)
		{
			throw new ArgumentException($"Auth must be {256} bits", "auth");
		}
		if (ciphertext == null || ciphertext.Length == 0)
		{
			throw new ArgumentNullException("ciphertext");
		}
		using HMACSHA256 hMACSHA = new HMACSHA256(auth);
		byte[] array = new byte[hMACSHA.HashSize / 8];
		byte[] array2 = hMACSHA.ComputeHash(ciphertext, 0, ciphertext.Length - array.Length);
		int num = 16;
		if (ciphertext.Length < array.Length + saltLength + num)
		{
			return null;
		}
		Array.Copy(ciphertext, ciphertext.Length - array.Length, array, 0, array.Length);
		int num2 = 0;
		for (int i = 0; i < array.Length; i++)
		{
			num2 |= array[i] ^ array2[i];
		}
		if (num2 != 0)
		{
			return null;
		}
		using AesManaged aesManaged = new AesManaged
		{
			KeySize = 256,
			BlockSize = 128,
			Mode = CipherMode.CBC,
			Padding = PaddingMode.PKCS7
		};
		byte[] array3 = new byte[num];
		Array.Copy(ciphertext, saltLength, array3, 0, array3.Length);
		using ICryptoTransform transform = aesManaged.CreateDecryptor(key, array3);
		using MemoryStream memoryStream = new MemoryStream();
		using (CryptoStream output = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write))
		{
			using BinaryWriter binaryWriter = new BinaryWriter(output);
			binaryWriter.Write(ciphertext, saltLength + array3.Length, ciphertext.Length - saltLength - array3.Length - array.Length);
		}
		return memoryStream.ToArray();
	}

	public static byte[] SimpleEncryptWithKey(byte[] plaintext, string key, byte[] salt = null)
	{
		if (salt == null)
		{
			salt = new byte[0];
		}
		if (string.IsNullOrWhiteSpace(key) || key.Length < 12)
		{
			throw new ArgumentException($"Key must be at least {12} characters", "key");
		}
		if (plaintext == null || plaintext.Length == 0)
		{
			throw new ArgumentNullException("plaintext");
		}
		byte[] array = new byte[16 + salt.Length];
		Array.Copy(salt, array, salt.Length);
		int num = salt.Length;
		byte[] bytes;
		using (Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(key, 8, 10000))
		{
			byte[] salt2 = rfc2898DeriveBytes.Salt;
			bytes = rfc2898DeriveBytes.GetBytes(32);
			Array.Copy(salt2, 0, array, num, salt2.Length);
			num += salt2.Length;
		}
		byte[] bytes2;
		using (Rfc2898DeriveBytes rfc2898DeriveBytes2 = new Rfc2898DeriveBytes(key, 8, 10000))
		{
			byte[] salt3 = rfc2898DeriveBytes2.Salt;
			bytes2 = rfc2898DeriveBytes2.GetBytes(32);
			Array.Copy(salt3, 0, array, num, salt3.Length);
		}
		return SimpleEncrypt(plaintext, bytes, bytes2, array);
	}

	public static byte[] SimpleDecryptWithKey(byte[] ciphertext, string key, int saltLength = 0)
	{
		if (string.IsNullOrWhiteSpace(key) || key.Length < 12)
		{
			throw new ArgumentException($"Key must be at least {12} characters", "key");
		}
		if (ciphertext == null || ciphertext.Length == 0)
		{
			throw new ArgumentNullException("ciphertext");
		}
		byte[] array = new byte[8];
		byte[] array2 = new byte[8];
		Array.Copy(ciphertext, saltLength, array, 0, array.Length);
		Array.Copy(ciphertext, saltLength + array.Length, array2, 0, array2.Length);
		byte[] key2 = Rfc2898DeriveBytes(key, array, 10000, 32);
		byte[] auth = Rfc2898DeriveBytes(key, array2, 10000, 32);
		return SimpleDecrypt(ciphertext, key2, auth, array.Length + array2.Length + saltLength);
	}

	private static byte[] Rfc2898DeriveBytes(string password, byte[] salt, int iterations, int numBytes)
	{
		using Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(password, salt, iterations);
		return rfc2898DeriveBytes.GetBytes(numBytes);
	}
}
