	{
		return new AnimStateHash
		{
			_hash = Animator.StringToHash(s)
		};
	}

	public static implicit operator int(AnimStateHash ash)
	{
		return ash._hash;
	}
}
[Serializable]
public struct Arc
{
	public UnityEngine.Vector3 start;

	public UnityEngine.Vector3 end;

	public UnityEngine.Vector3 control;

	public UnityEngine.Vector3[] GetArcPoints(int count = 12)
	{
		return ComputeArcPoints(start, end, control, count);
	}

	[Conditional("UNITY_EDITOR")]
	public void DrawGizmo()
	{
	}

	public static Arc From(UnityEngine.Vector3 start, UnityEngine.Vector3 end)
	{
		UnityEngine.Vector3 vector = DeriveArcControlPoint(start, end);
		return new Arc
		{
			start = start,
			end = end,
			control = vector
		};
	}

	public static UnityEngine.Vector3[] ComputeArcPoints(UnityEngine.Vector3 a, UnityEngine.Vector3 b, UnityEngine.Vector3? c = null, int count = 12)
	{
		UnityEngine.Vector3[] array = new UnityEngine.Vector3[count];
		float num = 1f / (float)count;
		UnityEngine.Vector3 valueOrDefault = c.GetValueOrDefault();
		if (!c.HasValue)
		{
			valueOrDefault = DeriveArcControlPoint(a, b);
			c = valueOrDefault;
		}
		for (int i = 0; i < count; i++)
		{
			float t = ((i != 0) ? ((i != count - 1) ? (num * (float)i) : 1f) : 0f);
			array[i] = BezierLerp(a, b, c.Value, t);
		}
		return array;
	}

	public static UnityEngine.Vector3 BezierLerp(UnityEngine.Vector3 a, UnityEngine.Vector3 b, UnityEngine.Vector3 c, float t)
	{
		UnityEngine.Vector3 a2 = UnityEngine.Vector3.Lerp(a, c, t);
		UnityEngine.Vector3 b2 = UnityEngine.Vector3.Lerp(c, b, t);
		return UnityEngine.Vector3.Lerp(a2, b2, t);
	}

	public static UnityEngine.Vector3 DeriveArcControlPoint(UnityEngine.Vector3 a, UnityEngine.Vector3 b, UnityEngine.Vector3? dir = null, float? height = null)
	{
		UnityEngine.Vector3 vector = (b - a) * 0.5f;
		UnityEngine.Vector3 normalized = vector.normalized;
		float valueOrDefault = height.GetValueOrDefault();
		if (!height.HasValue)
		{
			valueOrDefault = vector.magnitude;
			height = valueOrDefault;
		}
		if (!dir.HasValue)
		{
			UnityEngine.Vector3 rhs = UnityEngine.Vector3.Cross(normalized, UnityEngine.Vector3.up);
			dir = UnityEngine.Vector3.Cross(normalized, rhs);
		}
		UnityEngine.Vector3 vector2 = dir.Value * (0f - height.Value);
		return a + vector + vector2;
	}
}
public class ComputePenetration : MonoBehaviour
{
	public Collider colliderA;

	public Collider colliderB;

	public bool overlapped;

	public UnityEngine.Vector3 direction;

	public float distance;

	private TimeSince lastUpdate = TimeSince.Now();

	public void Compute()
	{
		if (!(colliderA == null))
		{
			_ = colliderB == null;
		}
	}

	public void OnDrawGizmos()
	{
		if (!(colliderA.AsNull() == null) && !(colliderB.AsNull() == null))
		{
			Transform transform = colliderA.transform;
			Transform transform2 = colliderB.transform;
			if (lastUpdate.HasElapsed(0.5f, resetOnElapsed: true))
			{
				overlapped = Physics.ComputePenetration(colliderA, transform.position, transform.rotation, colliderB, transform2.position, transform2.rotation, out direction, out distance);
			}
			Color color = (overlapped ? Color.red : Color.green);
			DrawCollider(colliderA, color);
			DrawCollider(colliderB, color);
			if (overlapped)
			{
				UnityEngine.Vector3 position = colliderB.transform.position;
				UnityEngine.Vector3 to = position + direction * distance;
				Gizmos.DrawLine(position, to);
			}
		}
	}

	private void DrawCollider(Collider c, Color color)
	{
		CommandBuilder ingame = Draw.ingame;
		using (ingame.WithMatrix(c.transform.localToWorldMatrix))
		{
			ingame.PushColor(color);
			if (!(c is BoxCollider boxCollider))
			{
				if (!(c is SphereCollider sphereCollider))
				{
					if (c is CapsuleCollider capsuleCollider)
					{
						ingame.WireCapsule(capsuleCollider.center, UnityEngine.Vector3.up, capsuleCollider.height, capsuleCollider.radius);
					}
				}
				else
				{
					ingame.WireSphere(sphereCollider.center, sphereCollider.radius);
				}
			}
			else
			{
				ingame.WireBox(boxCollider.center, boxCollider.size);
			}
			ingame.PopColor();
		}
	}
}
public static class ContextLog
{
	public static void Log<T0, T1>(this T0 ctx, T1 arg1)
	{
		UnityEngine.Debug.Log(ZString.Concat(GetPrefix(ref ctx), arg1));
	}

	public static void LogCall<T0, T1>(this T0 ctx, T1 arg1, [CallerMemberName] string call = null)
	{
		string prefix = GetPrefix(ref ctx);
		string arg2 = ZString.Concat("{.", call, "()} ");
		UnityEngine.Debug.Log(ZString.Concat(prefix, arg2, arg1));
	}

	private static string GetPrefix<T>(ref T ctx)
	{
		if (ctx == null)
		{
			return string.Empty;
		}
		string arg = ((!(ctx is Type type)) ? ((!(ctx is string text)) ? ctx.GetType().Name : text) : type.Name);
		return ZString.Concat("[", arg, "] ");
	}
}
