public class LerpScale : LerpComponent
{
	[Space]
	public Transform target;

	[Space]
	public UnityEngine.Vector3 start = UnityEngine.Vector3.one;

	public UnityEngine.Vector3 end = UnityEngine.Vector3.one;

	public UnityEngine.Vector3 current;

	[SerializeField]
	private AnimationCurve scaleCurve = AnimationCurves.EaseInOutBounce;

	protected override void OnLerp(float t)
	{
		current = UnityEngine.Vector3.Lerp(start, end, scaleCurve.Evaluate(t));
		if ((bool)target)
		{
			target.localScale = current;
		}
	}
}
