			return NextIntWithExclusion(min, max, exclude);
		}
		int num = max - min - 2;
		if (num <= 0)
		{
			return min;
		}
		int num2 = min + 2 + NextInt(num);
		int num5;
		int num6;
		if (exclude >= exclude2)
		{
			int num3 = exclude2 + 1;
			int num4 = exclude;
			num5 = num3;
			num6 = num4;
		}
		else
