		float num4 = MathF.Pow(NextFloat(), 1f / 3f);
		float num5 = 1f / MathF.Sqrt(num * num + num2 * num2 + num3 * num3);
		return new UnityEngine.Vector3(num * num5 * num4 * radius, num2 * num5 * num4 * radius, num3 * num5 * num4 * radius);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public UnityEngine.Vector3 NextPointOnSphere(float radius)
