		while (num > 1)
		{
			int num2 = NextInt(num--);
			int num3 = num;
			int num4 = num2;
			T val = array[num2];
			T val2 = array[num];
			array[num3] = val;
			array[num4] = val2;
		}
	}

	public void Shuffle<T>(List<T> list)
	{
		int count = list.Count;
		while (count > 1)
		{
			int num = NextInt(count--);
			int index = count;
			int index2 = num;
			T val = list[num];
			T val2 = list[count];
			T val3 = (list[index] = val);
			val3 = (list[index2] = val2);
		}
	}

