public static class StringExts
{
	private static char[] _escapeChars;

	public static string EscapeCsv(this string field)
	{
		if (_escapeChars == null)
		{
			_escapeChars = new char[4] { ',', '"', '\n', '\r' };
		}
		if (field.IndexOfAny(_escapeChars) != -1)
		{
			return field.Replace("\"", "\"\"");
		}
		return field;
	}
}
public class SubEmitterListener : MonoBehaviour
{
	public ParticleSystem target;

	public ParticleSystem subEmitter;

	public int subEmitterIndex;

	public UnityEvent onSubEmit;

	public float intervalScale = 1f;

	public float interval;

	[NonSerialized]
	private bool _canListen;

	[NonSerialized]
	private bool _listening;

	[NonSerialized]
	private bool _listenOnce;

	[NonSerialized]
	private TimeSince _sinceLastEmit;

	private void OnEnable()
	{
		if (target == null)
		{
			Disable();
			return;
		}
		ParticleSystem.SubEmittersModule subEmitters = target.subEmitters;
		if (subEmitterIndex < 0)
		{
			subEmitterIndex = 0;
		}
		_canListen = subEmitters.subEmittersCount > 0 && subEmitterIndex <= subEmitters.subEmittersCount - 1;
		if (!_canListen)
		{
			Disable();
			return;
		}
		subEmitter = target.subEmitters.GetSubEmitterSystem(subEmitterIndex);
		ParticleSystem.MainModule main = subEmitter.main;
		interval = main.startLifetime.constantMax * main.startLifetimeMultiplier;
	}

	private void OnDisable()
	{
		_listenOnce = false;
		_listening = false;
	}

	public void ListenStart()
	{
		if (!_listening && _canListen)
		{
			Enable();
			_listening = true;
		}
	}

	public void ListenStop()
	{
		Disable();
	}

	public void ListenOnce()
	{
		if (!_listening)
		{
			Enable();
			if (_canListen)
			{
				Enable();
				_listenOnce = true;
				_listening = true;
			}
		}
	}

	private void Update()
	{
		if (_canListen && _listening && subEmitter.particleCount > 0 && (float)_sinceLastEmit >= interval * intervalScale)
		{
			_sinceLastEmit = 0f;
			OnSubEmit();
			if (_listenOnce)
			{
				Disable();
			}
		}
	}

	protected virtual void OnSubEmit()
	{
		onSubEmit?.Invoke();
	}

	public void Enable()
	{
		if (!base.enabled)
		{
			base.enabled = true;
		}
	}

	public void Disable()
	{
		if (base.enabled)
		{
			base.enabled = false;
		}
	}
}
public class TaggedColliderTrigger : MonoBehaviour
{
	public new UnityTag tag;

	public UnityEvent<Collider> onEnter = new UnityEvent<Collider>();

	public UnityEvent<Collider> onExit = new UnityEvent<Collider>();

	public float enterHysteresis = 0.125f;

	public float exitHysteresis = 0.125f;

	private TimeSince _sinceLastEnter;

	private TimeSince _sinceLastExit;

	private void OnTriggerEnter(Collider other)
	{
		if (other.CompareTag(tag) && _sinceLastEnter.HasElapsed(enterHysteresis, resetOnElapsed: true))
		{
			onEnter?.Invoke(other);
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (other.CompareTag(tag) && _sinceLastExit.HasElapsed(exitHysteresis, resetOnElapsed: true))
		{
			onExit?.Invoke(other);
		}
	}
}
public struct TimeSince
{
	private DateTime _dt;

	private const double INT32_MAX = 2147483647.0;

	public double secondsElapsed
	{
		get
		{
			double totalSeconds = (DateTime.UtcNow - _dt).TotalSeconds;
			if (!(totalSeconds > 2147483647.0))
			{
				return totalSeconds;
			}
			return 2147483647.0;
		}
	}

	public float secondsElapsedFloat => (float)secondsElapsed;

	public int secondsElapsedInt => (int)secondsElapsed;

	public uint secondsElapsedUint => (uint)secondsElapsed;

	public long secondsElapsedLong => (long)secondsElapsed;

	public TimeSpan secondsElapsedSpan => TimeSpan.FromSeconds(secondsElapsed);

	public TimeSince(DateTime dt)
	{
		_dt = dt;
	}

	public TimeSince(int elapsed)
	{
		_dt = DateTime.UtcNow.AddSeconds(-elapsed);
	}

	public TimeSince(uint elapsed)
	{
		_dt = DateTime.UtcNow.AddSeconds(-1.0 * (double)elapsed);
	}

	public TimeSince(float elapsed)
	{
		_dt = DateTime.UtcNow.AddSeconds(0f - elapsed);
	}

	public TimeSince(double elapsed)
	{
		_dt = DateTime.UtcNow.AddSeconds(0.0 - elapsed);
	}

	public TimeSince(long elapsed)
	{
		_dt = DateTime.UtcNow.AddSeconds(-elapsed);
	}

	public TimeSince(TimeSpan elapsed)
	{
		_dt = DateTime.UtcNow.Add(-elapsed);
	}

	public bool HasElapsed(int seconds)
	{
		return secondsElapsedInt >= seconds;
	}

	public bool HasElapsed(uint seconds)
	{
		return secondsElapsedUint >= seconds;
	}

	public bool HasElapsed(float seconds)
	{
		return secondsElapsedFloat >= seconds;
	}

	public bool HasElapsed(double seconds)
	{
		return secondsElapsed >= seconds;
	}

	public bool HasElapsed(long seconds)
	{
		return secondsElapsedLong >= seconds;
	}

	public bool HasElapsed(TimeSpan seconds)
	{
		return secondsElapsedSpan >= seconds;
	}

	public void Reset()
	{
		_dt = DateTime.UtcNow;
	}

	public bool HasElapsed(int seconds, bool resetOnElapsed)
	{
		if (!resetOnElapsed)
		{
			return secondsElapsedInt >= seconds;
		}
		if (secondsElapsedInt < seconds)
		{
			return false;
		}
		Reset();
		return true;
	}

	public bool HasElapsed(uint seconds, bool resetOnElapsed)
	{
		if (!resetOnElapsed)
		{
			return secondsElapsedUint >= seconds;
		}
		if (secondsElapsedUint < seconds)
		{
			return false;
		}
		Reset();
		return true;
	}

	public bool HasElapsed(float seconds, bool resetOnElapsed)
	{
		if (!resetOnElapsed)
		{
			return secondsElapsedFloat >= seconds;
		}
		if (secondsElapsedFloat < seconds)
		{
			return false;
		}
		Reset();
		return true;
	}

	public bool HasElapsed(double seconds, bool resetOnElapsed)
	{
		if (!resetOnElapsed)
		{
			return secondsElapsed >= seconds;
		}
		if (secondsElapsed < seconds)
		{
			return false;
		}
		Reset();
		return true;
	}

	public bool HasElapsed(long seconds, bool resetOnElapsed)
	{
		if (!resetOnElapsed)
		{
			return secondsElapsedLong >= seconds;
		}
		if (secondsElapsedLong < seconds)
		{
			return false;
		}
		Reset();
		return true;
	}

	public bool HasElapsed(TimeSpan seconds, bool resetOnElapsed)
	{
		if (!resetOnElapsed)
		{
			return secondsElapsedSpan >= seconds;
		}
		if (secondsElapsedSpan < seconds)
		{
			return false;
		}
		Reset();
		return true;
	}

	public override string ToString()
	{
		return $"{secondsElapsed:F3} seconds since {{{_dt:s}";
	}

