[Serializable]
public class VelocityHelper
{
	private float[] _samples;

	private int _latest;

	private int _size;

	private bool _initialized;

	public VelocityHelper(int historySize = 12)
	{
		_size = historySize;
		_samples = new float[historySize * 4];
	}

	public void SamplePosition(Transform target, float dt)
	{
		UnityEngine.Vector3 position = target.position;
		if (!_initialized)
		{
			_InitSamples(position, dt);
		}
		_SetSample(_latest, position, dt);
		_latest = (_latest + 1) % _size;
	}

	private void _InitSamples(UnityEngine.Vector3 position, float dt)
	{
		for (int i = 0; i < _size; i++)
		{
			_SetSample(i, position, dt);
		}
		_initialized = true;
	}

	private void _SetSample(int i, UnityEngine.Vector3 position, float dt)
	{
		_samples[i] = position.x;
		_samples[i + 1] = position.y;
		_samples[i + 2] = position.z;
		_samples[i + 3] = dt;
	}
}
public class VelocityHelperTest : MonoBehaviour
{
	public UnityEngine.Vector3 velocity;

	public float speed;

	[Space]
	public UnityEngine.Vector3 lastVelocity;

	public UnityEngine.Vector3 lastPosition;

	[Space]
	[SerializeField]
	private float[] _deltaTimes = new float[5];

	private void Setup()
	{
		lastPosition = base.transform.position;
		lastVelocity = UnityEngine.Vector3.zero;
		velocity = UnityEngine.Vector3.zero;
		speed = 0f;
	}

	private void Start()
	{
		Setup();
	}

	private void FixedUpdate()
	{
		float deltaTime = Time.deltaTime;
		UnityEngine.Vector3 position = base.transform.position;
		UnityEngine.Vector3 b = (position - lastPosition) / deltaTime;
		velocity = UnityEngine.Vector3.Lerp(lastVelocity, b, deltaTime);
		speed = velocity.magnitude;
		lastPosition = position;
		lastVelocity = b;
	}

	private void Update()
	{
	}
}
