		int num = (int)physicsMask;
		QueryTriggerInteraction queryTriggerInteraction = ((!includeTriggers) ? QueryTriggerInteraction.Ignore : QueryTriggerInteraction.Collide);
		GetEndsAndRadius(transform, center, height, radius, out var a, out var b, out var r);
		UnityEngine.Vector3 vector;
		UnityEngine.Vector3 halfExtents;
		switch (shape)
		{
		case VolumeShape.Box:
			vector = transform.TransformPoint(center);
			halfExtents = UnityEngine.Vector3.Scale(lossyScale, size * 0.5f).Abs();
			break;
		case VolumeShape.Cylinder:
			vector = (a + b) * 0.5f;
			halfExtents = new UnityEngine.Vector3(r, UnityEngine.Vector3.Distance(a, b) * 0.5f, r);
			break;
		default:
			return false;
		}
		Array.Clear(_boxOverlaps, 0, 8);
		_boxHits = Physics.OverlapBoxNonAlloc(vector, halfExtents, _boxOverlaps, rotation, num, queryTriggerInteraction);
		if (shape != VolumeShape.Cylinder)
		{
			return _colliding = _boxHits > 0;
		}
		_hits = 0;
		Array.Clear(_capOverlaps, 0, 8);
		Array.Clear(_overlaps, 0, 8);
		_capHits = Physics.OverlapCapsuleNonAlloc(a, b, r, _capOverlaps, num, queryTriggerInteraction);
		_set.Clear();
		int num2 = System.Math.Max(_capHits, _boxHits);
		Collider[] array = ((_capHits < _boxHits) ? _capOverlaps : _boxOverlaps);
		Collider[] array2 = ((_capHits < _boxHits) ? _boxOverlaps : _capOverlaps);
		for (int i = 0; i < num2; i++)
		{
			Collider collider = array[i];
			if ((bool)collider && !_set.Add(collider))
			{
				_overlaps[_hits++] = collider;
			}
			Collider collider2 = array2[i];
			if ((bool)collider2 && !_set.Add(collider2))
			{
				_overlaps[_hits++] = collider2;
			}
		}
		return _colliding = _hits > 0;
	}

	private static void GetEndsAndRadius(Transform t, UnityEngine.Vector3 center, float height, float radius, out UnityEngine.Vector3 a, out UnityEngine.Vector3 b, out float r)
	{
		float num = height * 0.5f;
		UnityEngine.Vector3 lossyScale = t.lossyScale;
		a = t.TransformPoint(center + UnityEngine.Vector3.down * num);
		b = t.TransformPoint(center + UnityEngine.Vector3.up * num);
		r = System.Math.Max(System.Math.Abs(lossyScale.x), System.Math.Abs(lossyScale.z)) * radius;
	}
}
[ExecuteAlways]
public class Xform : MonoBehaviour
{
	public Transform parent;

	[Space]
	public Color displayColor = SRand.New().NextColor();

	[Space]
	public float3 localPosition = float3.zero;

	public float3 localScale = UnityEngine.Vector3.one;

	public UnityEngine.Quaternion localRotation = quaternion.identity;

	private static readonly float3 F3_ONE = 1f;

	private static readonly float2 F2_ONE = 1f;

	private static readonly float3 AXIS_ZB_FW = new float3(0f, 0f, 1f);

	private static readonly float3 AXIS_YG_UP = new float3(0f, 1f, 0f);

	private static readonly float3 AXIS_XR_RT = new float3(1f, 0f, 0f);

	private static readonly Color CR = new Color(1f, 0f, 0f, 0.24f);

	private static readonly Color CG = new Color(0f, 1f, 0f, 0.24f);

	private static readonly Color CB = new Color(0f, 0f, 1f, 0.24f);

	public float3 localExtents => localScale * 0.5f;

	public UnityEngine.Matrix4x4 LocalTRS()
	{
		return UnityEngine.Matrix4x4.TRS(localPosition, localRotation, localScale);
	}

	public UnityEngine.Matrix4x4 TRS()
	{
		if (parent.AsNull() == null)
		{
			return LocalTRS();
		}
		return parent.localToWorldMatrix * LocalTRS();
	}

	private void Update()
	{
		UnityEngine.Matrix4x4 matrix = TRS();
		CommandBuilder ingame = Draw.ingame;
		using (ingame.WithMatrix(matrix))
		{
			using (ingame.WithLineWidth(2f))
			{
				ingame.PlaneWithNormal(AXIS_XR_RT * 0.5f, AXIS_XR_RT, F2_ONE, CR);
				ingame.PlaneWithNormal(AXIS_YG_UP * 0.5f, AXIS_YG_UP, F2_ONE, CG);
				ingame.PlaneWithNormal(AXIS_ZB_FW * 0.5f, AXIS_ZB_FW, F2_ONE, CB);
				ingame.WireBox(float3.zero, quaternion.identity, 1f, displayColor);
			}
		}
	}
}
[Serializable]
public class XformNode
{
	public UnityEngine.Vector4 localPosition;

	public Transform parent;

	public UnityEngine.Vector4 worldPosition
	{
		get
		{
			if (!parent)
			{
				return localPosition;
			}
			UnityEngine.Matrix4x4 m = parent.localToWorldMatrix;
			UnityEngine.Vector4 point = localPosition;
			MatrixUtils.MultiplyXYZ3x4(ref m, ref point);
			return point;
		}
	}

	public float radius
	{
		get
		{
			return localPosition.w;
		}
		set
		{
			localPosition.w = value;
		}
	}

	public UnityEngine.Matrix4x4 LocalTRS()
	{
		return UnityEngine.Matrix4x4.TRS(localPosition, UnityEngine.Quaternion.identity, UnityEngine.Vector3.one);
	}
}
public class AgeSlider : MonoBehaviour, IBuildValidation
{
	[Serializable]
	public class SliderHeldEvent : UnityEvent<int>
	{
	}

	private const int MIN_AGE = 13;

	[SerializeField]
	private SliderHeldEvent m_OnHoldComplete = new SliderHeldEvent();

	[SerializeField]
	private int _maxAge = 99;

	[SerializeField]
	private TMP_Text _ageValueTxt;

	[SerializeField]
	private GameObject _confirmButton;

	[SerializeField]
	private float holdTime = 5f;

	[SerializeField]
	private LineRenderer progressBar;

	private int _currentAge;

	private static bool _ageGateActive;

	private float progress;

	public SliderHeldEvent onHoldComplete
	{
		get
		{
			return m_OnHoldComplete;
		}
		set
		{
			m_OnHoldComplete = value;
		}
	}

	private void OnEnable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction += PostUpdate;
		}
	}

	private void OnDisable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction -= PostUpdate;
		}
	}

	protected void Update()
	{
		if (!_ageGateActive)
		{
			return;
		}
		if (ControllerBehaviour.Instance.ButtonDown && _confirmButton.activeInHierarchy)
		{
			progress += Time.deltaTime / holdTime;
			progressBar.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
			progressBar.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
			if (progress >= 1f)
			{
				m_OnHoldComplete.Invoke(_currentAge);
			}
		}
		else
		{
			progress = 0f;
			progressBar.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
			progressBar.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
		}
	}

	private void PostUpdate()
	{
		if (_ageGateActive)
		{
			if (ControllerBehaviour.Instance.IsLeftStick || ControllerBehaviour.Instance.IsUpStick)
			{
				_currentAge = Mathf.Clamp(_currentAge - 1, 0, _maxAge);
				_ageValueTxt.text = ((_currentAge > 0) ? _currentAge.ToString() : "?");
				_confirmButton.SetActive(_currentAge > 0);
			}
			if (ControllerBehaviour.Instance.IsRightStick || ControllerBehaviour.Instance.IsDownStick)
			{
				_currentAge = Mathf.Clamp(_currentAge + 1, 0, _maxAge);
				_ageValueTxt.text = ((_currentAge > 0) ? _currentAge.ToString() : "?");
				_confirmButton.SetActive(_currentAge > 0);
			}
		}
	}

	public static void ToggleAgeGate(bool state)
	{
		_ageGateActive = state;
	}

	public bool BuildValidationCheck()
	{
		if (_confirmButton == null)
		{
			UnityEngine.Debug.LogError("[KID] Object [_confirmButton] is NULL. Must be assigned in editor");
			return false;
		}
		return true;
	}
}
public class AgeSliderWithProgressBar : MonoBehaviourTick
{
	[Serializable]
	public class SliderHeldEvent : UnityEvent<int>
	{
	}

	private const int MIN_AGE = 13;

	[SerializeField]
	private SliderHeldEvent m_OnHoldComplete = new SliderHeldEvent();

	[SerializeField]
	private bool _adjustAge;

	[SerializeField]
	private int _maxAge = 25;

	[SerializeField]
	private TMP_Text _ageValueTxt;

	[Tooltip("Optional game object that should hold the Progress Bar Fill. Disables Hold functionality if null.")]
	[SerializeField]
	private GameObject _progressBarContainer;

	[SerializeField]
	private float holdTime = 2.5f;

	[SerializeField]
	private Image progressBarFill;

	[SerializeField]
	private TMP_Text _messageText;

	[SerializeField]
	private float _stickVibrationStrength = 0.1f;

	[SerializeField]
	private float _stickVibrationDuration = 0.05f;

	[SerializeField]
	private KIDUIButton _confirmButton;

	private bool _ageSlidable = true;

	private bool _incrementButtonsLockingSlider;

	private bool controllerActive;

	[SerializeField]
	private string _lockMessage;

	private string _originalText;

	private int _currentAge;

	private float progress;

	public SliderHeldEvent onHoldComplete
	{
		get
		{
			return m_OnHoldComplete;
		}
		set
		{
			m_OnHoldComplete = value;
		}
	}

	public bool AdjustAge => _adjustAge;

	public bool ControllerActive
	{
		get
		{
			return controllerActive;
		}
		set
		{
			if (value)
			{
				ControllerBehaviour.Instance.OnAction += PostUpdate;
			}
			else
			{
				ControllerBehaviour.Instance.OnAction -= PostUpdate;
			}
			controllerActive = value;
		}
	}

	public string LockMessage
	{
		get
		{
			return _lockMessage;
		}
		set
		{
			_lockMessage = value;
		}
	}

	public int CurrentAge => _currentAge;

	private void Awake()
	{
		if ((bool)_messageText)
		{
			_originalText = _messageText.text;
		}
	}

	public void SetOriginalText(string text)
	{
		_originalText = text;
	}

	private new void OnEnable()
	{
		base.OnEnable();
		if (_progressBarContainer != null && progressBarFill != null)
		{
			progressBarFill.rectTransform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
		}
		if ((bool)_ageValueTxt)
		{
			_ageValueTxt.text = ((_currentAge > 0) ? _currentAge.ToString() : "?");
		}
	}

	public override void Tick()
	{
		if (!_progressBarContainer || !ControllerActive)
		{
			return;
		}
		if (!_lockMessage.IsNullOrEmpty())
		{
			progress = 0f;
			if ((bool)_messageText)
			{
				_messageText.text = LockMessage;
			}
		}
		else
		{
			if ((bool)_messageText)
			{
				_messageText.text = _originalText;
			}
			if ((double)progress == 1.0)
			{
				m_OnHoldComplete.Invoke(_currentAge);
				progress = 0f;
			}
			if (ControllerBehaviour.Instance.ButtonDown && _progressBarContainer != null && (_currentAge > 0 || !AdjustAge))
			{
				progress += Time.deltaTime / holdTime;
				progress = Mathf.Clamp01(progress);
			}
			else
			{
				progress = 0f;
			}
		}
		if (_progressBarContainer != null)
		{
			progressBarFill.rectTransform.localScale = new UnityEngine.Vector3(progress, 1f, 1f);
		}
	}

	private void PostUpdate()
	{
		if (ControllerActive && (bool)_ageValueTxt && _ageSlidable && !_incrementButtonsLockingSlider)
		{
			if (ControllerBehaviour.Instance.IsLeftStick)
			{
				_currentAge = Mathf.Clamp(_currentAge - 1, 0, _maxAge);
				if (_currentAge > 0 && _currentAge < _maxAge)
				{
					HandRayController.Instance.PulseActiveHandray(_stickVibrationStrength, _stickVibrationDuration);
				}
			}
			if (ControllerBehaviour.Instance.IsRightStick)
			{
				_currentAge = Mathf.Clamp(_currentAge + 1, 0, _maxAge);
				if (_currentAge > 0 && _currentAge < _maxAge)
				{
					HandRayController.Instance.PulseActiveHandray(_stickVibrationStrength, _stickVibrationDuration);
				}
			}
		}
		if ((bool)_ageValueTxt)
		{
			_ageValueTxt.text = GetAgeString();
			if (_progressBarContainer != null)
			{
				_progressBarContainer.SetActive(_currentAge > 0);
			}
		}
	}

	public void EnableEditing()
	{
		_ageSlidable = true;
	}

	public void DisableEditing()
	{
		_ageSlidable = false;
	}

	public string GetAgeString()
	{
		if ((bool)_confirmButton)
		{
			_confirmButton.interactable = true;
		}
		if (_currentAge == 0)
		{
			if ((bool)_confirmButton)
			{
				_confirmButton.interactable = false;
			}
			return "?";
		}
		if (_currentAge == _maxAge)
		{
			return _maxAge + "+";
		}
		return _currentAge.ToString();
	}

	public void ForceAddAge(int number)
	{
		_incrementButtonsLockingSlider = true;
		_currentAge = System.Math.Min(_currentAge + number, _maxAge);
	}

	public void ForceSubtractAge(int number)
	{
		_incrementButtonsLockingSlider = true;
		_currentAge = System.Math.Max(_currentAge - number, 1);
	}
}
[Serializable]
public struct SAnnouncementData
{
	public string ShowAnnouncement;

	public string AnnouncementID;

	public string AnnouncementTitle;

	public string Message;
}
public class AnnouncementManager : MonoBehaviour
{
	private const string ANNOUNCEMENT_ID_PLAYERPREF_PREFIX = "announcement-id-";

	private const string ANNOUNCEMENT_TITLE_DATA_KEY = "AnnouncementData";

	private const string ANNOUNCEMENT_HEADING = "Announcement!";

	private const string ANNOUNCEMENT_BUTTON_TEXT = "Continue";

	[SerializeField]
	private MessageBox _announcementMessageBox;

	private string _announcementString = string.Empty;

	private SAnnouncementData _announcementData;

	private bool _showAnnouncement;

	private static AnnouncementManager _instance;

	private static string _announcementIDPref = "";

	public bool _completedSetup { get; private set; }

	public bool _announcementActive { get; private set; }

	public static AnnouncementManager Instance
	{
		get
		{
			if (_instance == null)
			{
				UnityEngine.Debug.LogError("[KID::ANNOUNCEMENT] [_instance] is NULL, does it exist in the scene?");
			}
			return _instance;
		}
	}

	private static string AnnouncementDPlayerPref
	{
		get
		{
			if (string.IsNullOrEmpty(_announcementIDPref))
			{
				_announcementIDPref = "announcement-id-" + PlayFabAuthenticator.instance.GetPlayFabPlayerId();
			}
			return _announcementIDPref;
		}
	}

	public bool ShowAnnouncement()
	{
		return _showAnnouncement;
	}

	private void Awake()
	{
		if (_instance != null)
		{
			UnityEngine.Debug.LogError("[KID::ANNOUNCEMENT] [AnnouncementManager] has already been setup, does another already exist in the scene?");
			return;
		}
		_instance = this;
		if (_announcementMessageBox == null)
		{
			UnityEngine.Debug.LogError("[ANNOUNCEMENT] Announcement Message Box has not been set. Announcement system will not work without it");
		}
	}

	private void Start()
	{
		if (!(_announcementMessageBox == null))
		{
			_announcementMessageBox.RightButton = "";
			_announcementMessageBox.LeftButton = "Continue";
			PlayFabTitleDataCache.Instance.GetTitleData("AnnouncementData", ConfigureAnnouncement, OnError);
		}
	}

	public void OnContinuePressed()
	{
		HandRayController.Instance.DisableHandRays();
		if (_announcementMessageBox == null)
		{
			UnityEngine.Debug.LogError("[ANNOUNCEMENT] Message Box is null, Continue Button cannot work");
			return;
		}
		PrivateUIRoom.RemoveUI(_announcementMessageBox.transform);
		_announcementActive = false;
		PlayerPrefs.SetString(AnnouncementDPlayerPref, _announcementData.AnnouncementID);
		PlayerPrefs.Save();
	}

	private void OnError(PlayFabError error)
	{
		UnityEngine.Debug.LogError("[ANNOUNCEMENT] Failed to Get Title Data for key [AnnouncementData]. Error:\n[" + error.ErrorMessage);
		_completedSetup = true;
	}

	private void ConfigureAnnouncement(string data)
	{
		_announcementString = data;
		_announcementData = JsonMapper.ToObject<SAnnouncementData>(_announcementString);
		if (!bool.TryParse(_announcementData.ShowAnnouncement, out _showAnnouncement))
		{
			_completedSetup = true;
			UnityEngine.Debug.LogError("[ANNOUNCEMENT] Failed to parse [ShowAnnouncement] with value [" + _announcementData.ShowAnnouncement + "] to a bool, assuming false");
			return;
		}
		if (!ShowAnnouncement())
		{
			_completedSetup = true;
			return;
		}
		if (string.IsNullOrEmpty(_announcementData.AnnouncementID))
		{
			_completedSetup = true;
			UnityEngine.Debug.LogError("[ANNOUNCEMENT] Announcement Version is empty or null. Will not show announcement");
			return;
		}
		string text = PlayerPrefs.GetString(AnnouncementDPlayerPref, "");
		if (_announcementData.AnnouncementID == text)
		{
			_completedSetup = true;
			return;
		}
		PrivateUIRoom.ForceStartOverlay(PrivateUIRoom.OverlaySource.KID);
		HandRayController.Instance.EnableHandRays();
		_announcementMessageBox.Header = _announcementData.AnnouncementTitle;
		_announcementMessageBox.Body = _announcementData.Message;
		_announcementActive = true;
		PrivateUIRoom.AddUI(_announcementMessageBox.transform);
		_completedSetup = true;
	}
}
