	public static bool TryGetAgeStatusTypeFromAge(int age, out AgeStatusType ageType)
	{
		if (_ageGateRequirements == null)
		{
			UnityEngine.Debug.LogError("[KID::MANAGER] [_ageGateRequirements] is not set - need to Get AgeGate Requirements first");
			ageType = AgeStatusType.DIGITALMINOR;
			return false;
		}
		if (age < _ageGateRequirements.AgeGateRequirements.DigitalConsentAge)
		{
			ageType = AgeStatusType.DIGITALMINOR;
			return true;
		}
		if (age < _ageGateRequirements.AgeGateRequirements.CivilAge)
		{
			ageType = AgeStatusType.DIGITALYOUTH;
			return true;
		}
		ageType = AgeStatusType.LEGALADULT;
		return true;
	}

	public static (bool requiresOptIn, bool hasOptedInPreviously) CheckFeatureOptIn(EKIDFeatures feature, KID.Model.Permission permissionData = null)
	{
		if (permissionData == null)
		{
			permissionData = GetPermissionDataByFeature(feature);
			if (permissionData == null)
			{
				UnityEngine.Debug.LogError("[KID::MANAGER] Unable to retrieve permission data for feature [" + feature.ToStandardisedString() + "]");
				return (requiresOptIn: false, hasOptedInPreviously: false);
			}
		}
		if (permissionData.ManagedBy == KID.Model.Permission.ManagedByEnum.PROHIBITED)
		{
			return (requiresOptIn: false, hasOptedInPreviously: false);
		}
		bool item = true;
		if (CurrentSession != null)
		{
			item = CurrentSession.HasOptedInToPermission(feature);
		}
		if (permissionData.ManagedBy == KID.Model.Permission.ManagedByEnum.GUARDIAN)
		{
			return (requiresOptIn: false, hasOptedInPreviously: item);
		}
		if (permissionData.ManagedBy == KID.Model.Permission.ManagedByEnum.PLAYER && permissionData.Enabled)
		{
			return (requiresOptIn: false, hasOptedInPreviously: true);
		}
		return (requiresOptIn: true, hasOptedInPreviously: item);
	}

	public static void SetFeatureOptIn(EKIDFeatures feature, bool optedIn)
	{
		KID.Model.Permission permissionDataByFeature = GetPermissionDataByFeature(feature);
		if (permissionDataByFeature == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID] Trying to set Feature Opt in for feature [" + feature.ToStandardisedString() + "] but permission data could not be found. Assumed is opt-in");
			return;
		}
		if (CurrentSession == null)
		{
			UnityEngine.Debug.Log("[KID::MANAGER] CurrentSession is null, cannot set feature opt-in. Returning.");
			return;
		}
		switch (permissionDataByFeature.ManagedBy)
		{
		case KID.Model.Permission.ManagedByEnum.GUARDIAN:
			CurrentSession.OptInToPermission(feature, permissionDataByFeature.Enabled);
			break;
		case KID.Model.Permission.ManagedByEnum.PLAYER:
			CurrentSession.OptInToPermission(feature, optedIn);
			break;
		case KID.Model.Permission.ManagedByEnum.PROHIBITED:
			CurrentSession.OptInToPermission(feature, optIn: false);
			break;
		}
	}

	public static bool CheckFeatureSettingEnabled(EKIDFeatures feature)
	{
		KID.Model.Permission permissionDataByFeature = GetPermissionDataByFeature(feature);
		if (permissionDataByFeature == null)
		{
			UnityEngine.Debug.LogError("[KID::MANAGER] Unable to permissions for feature [" + feature.ToStandardisedString() + "]");
			return false;
		}
		if (permissionDataByFeature.ManagedBy == KID.Model.Permission.ManagedByEnum.PROHIBITED)
		{
			return false;
		}
		bool item = CheckFeatureOptIn(feature).hasOptedInPreviously;
		switch (feature)
		{
		case EKIDFeatures.Groups:
			if (permissionDataByFeature.ManagedBy == KID.Model.Permission.ManagedByEnum.GUARDIAN)
			{
				return permissionDataByFeature.Enabled;
			}
			return true;
		case EKIDFeatures.Multiplayer:
		case EKIDFeatures.Mods:
			return item;
		case EKIDFeatures.Custom_Nametags:
			if (item)
			{
				return GorillaComputer.instance.NametagsEnabled;
			}
			return false;
		case EKIDFeatures.Voice_Chat:
			if (item)
			{
				return GorillaComputer.instance.CheckVoiceChatEnabled();
			}
			return false;
		default:
			UnityEngine.Debug.LogError("[KID::MANAGER] Tried finding feature setting for [" + feature.ToStandardisedString() + "] but failed.");
			return false;
		}
	}

