	public static KID.Model.Permission GetPermissionDataByFeature(EKIDFeatures feature)
	{
		if (CurrentSession == null)
		{
			if (!PlayFabAuthenticator.instance.GetSafety())
			{
				return new KID.Model.Permission(feature.ToStandardisedString(), enabled: true, KID.Model.Permission.ManagedByEnum.PLAYER);
			}
			return new KID.Model.Permission(feature.ToStandardisedString(), enabled: false, KID.Model.Permission.ManagedByEnum.GUARDIAN);
		}
		if (!CurrentSession.TryGetPermission(feature, out var permission))
		{
			UnityEngine.Debug.LogError("[KID::MANAGER] Failed to retreive permission from session for [" + feature.ToStandardisedString() + "]. Assuming disabled permission");
			return new KID.Model.Permission(feature.ToStandardisedString(), enabled: false, KID.Model.Permission.ManagedByEnum.GUARDIAN);
		}
		return permission;
	}

