			}
			goto IL_0369;
			IL_0369:
			if (!flag)
			{
				goto IL_04f1;
			}
			if (retryCount < maxRetries)
			{
				int num = retryCount + 1;
				retryCount = num;
				float num2 = UnityEngine.Random.Range(0.5f, Mathf.Pow(2f, num));
				UnityEngine.Debug.LogWarning("[KID::SERVER_ROUTER] Tried sending request [" + operationType + " - " + endpoint + "] but it failed:\n" + unityWebRequest.error + "\n\nRequest:\n" + json);
				UnityEngine.Debug.LogWarning($"[KID::SERVER_ROUTER] Retrying {endpoint}... Retry attempt #{retryCount}, waiting for {num2} seconds");
