			}
			else if (request.result == UnityWebRequest.Result.ConnectionError)
			{
				UnityEngine.Debug.LogError("[KID::SERVER_ROUTER] NETWORK ERROR: " + request.error + "\nMessage: " + request.downloadHandler.text);
