public class PreGameMessage : MonoBehaviour
{
	[SerializeField]
	private GameObject _uiParent;

	[SerializeField]
	private TMP_Text _messageTitleTxt;

	[SerializeField]
	private TMP_Text _messageBodyTxt;

	[SerializeField]
	private GameObject _confirmButtonRoot;

	[SerializeField]
	private GameObject _multiButtonRoot;

	[SerializeField]
	private TMP_Text _messageConfirmationTxt;

	[SerializeField]
	private TMP_Text _messageAlternativeConfirmationTxt;

	[SerializeField]
	private TMP_Text _messageAlternativeButtonTxt;

	private Action _confirmationAction;

	private Action _alternativeAction;

	private bool _hasCompleted;

	private float progress;

	[SerializeField]
	private float holdTime;

	[SerializeField]
	private LineRenderer progressBar;

	[SerializeField]
	private LineRenderer progressBarL;

	[SerializeField]
	private LineRenderer progressBarR;

	private void OnEnable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction += PostUpdate;
		}
	}

	private void OnDisable()
	{
		KIDAudioManager.Instance?.PlaySoundWithDelay(KIDAudioManager.KIDSoundType.PageTransition);
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction -= PostUpdate;
		}
	}

	public void ShowMessage(string messageTitle, string messageBody, string messageConfirmation, Action onConfirmationAction, float bodyFontSize = 0.5f, float buttonHideTimer = 0f)
	{
		_alternativeAction = null;
		_multiButtonRoot.SetActive(value: false);
		_messageTitleTxt.text = messageTitle;
		_messageBodyTxt.text = messageBody;
		_messageConfirmationTxt.text = messageConfirmation;
		_confirmationAction = onConfirmationAction;
		_messageBodyTxt.fontSize = bodyFontSize;
		_hasCompleted = false;
		if (_confirmationAction == null)
		{
			_confirmButtonRoot.SetActive(value: false);
		}
		else if (!string.IsNullOrEmpty(_messageConfirmationTxt.text))
		{
			_confirmButtonRoot.SetActive(value: true);
		}
		PrivateUIRoom.AddUI(_uiParent.transform);
	}

	public void ShowMessage(string messageTitle, string messageBody, string messageConfirmationButton, string messageAlternativeButton, Action onConfirmationAction, Action onAlternativeAction, float bodyFontSize = 0.5f)
	{
		_confirmButtonRoot.SetActive(value: false);
		_messageTitleTxt.text = messageTitle;
		_messageBodyTxt.text = messageBody;
		_messageAlternativeConfirmationTxt.text = messageConfirmationButton;
		_messageAlternativeButtonTxt.text = messageAlternativeButton;
		_confirmationAction = onConfirmationAction;
		_alternativeAction = onAlternativeAction;
		_messageBodyTxt.fontSize = bodyFontSize;
		_hasCompleted = false;
		if (_confirmationAction == null || _alternativeAction == null)
		{
			UnityEngine.Debug.LogError("[KID] Trying to show a mesasge with multiple buttons, but one or both callbacks are null");
			_multiButtonRoot.SetActive(value: false);
		}
		else if (!string.IsNullOrEmpty(_messageAlternativeConfirmationTxt.text) && !string.IsNullOrEmpty(_messageAlternativeButtonTxt.text))
		{
			_multiButtonRoot.SetActive(value: true);
		}
		PrivateUIRoom.AddUI(_uiParent.transform);
	}

	public async Task ShowMessageWithAwait(string messageTitle, string messageBody, string messageConfirmation, Action onConfirmationAction, float bodyFontSize = 0.5f, float buttonHideTimer = 0f)
	{
		_alternativeAction = null;
		_multiButtonRoot.SetActive(value: false);
		_messageTitleTxt.text = messageTitle;
		_messageBodyTxt.text = messageBody;
		_messageConfirmationTxt.text = messageConfirmation;
		_confirmationAction = onConfirmationAction;
		_messageBodyTxt.fontSize = bodyFontSize;
		_hasCompleted = false;
		if (_confirmationAction == null)
		{
			_confirmButtonRoot.SetActive(value: false);
		}
		else if (!string.IsNullOrEmpty(_messageConfirmationTxt.text))
		{
			_confirmButtonRoot.SetActive(value: true);
		}
		PrivateUIRoom.AddUI(_uiParent.transform);
		await WaitForCompletion();
	}

	public void UpdateMessage(string newMessageBody, string newConfirmButton)
	{
		_messageBodyTxt.text = newMessageBody;
		_messageConfirmationTxt.text = newConfirmButton;
		if (string.IsNullOrEmpty(_messageConfirmationTxt.text))
		{
			_confirmButtonRoot.SetActive(value: false);
		}
		else if (_confirmationAction != null)
		{
			_confirmButtonRoot.SetActive(value: true);
		}
	}

	public void CloseMessage()
	{
		PrivateUIRoom.RemoveUI(_uiParent.transform);
	}

	private async Task WaitForCompletion()
	{
		do
		{
			await Task.Yield();
		}
		while (!_hasCompleted);
	}

	private void PostUpdate()
	{
		bool isLeftStick = ControllerBehaviour.Instance.IsLeftStick;
		bool isRightStick = ControllerBehaviour.Instance.IsRightStick;
		bool buttonDown = ControllerBehaviour.Instance.ButtonDown;
		if (_multiButtonRoot.activeInHierarchy)
		{
			if (isLeftStick)
			{
				progress += Time.deltaTime / holdTime;
				progressBarL.transform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
				progressBarR.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
				progressBarR.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
				if (progress >= 1f)
				{
					OnConfirmedPressed();
				}
			}
			else if (isRightStick)
			{
				progress += Time.deltaTime / holdTime;
				progressBarR.transform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
				progressBarL.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
				progressBarL.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
				if (progress >= 1f)
				{
					OnAlternativePressed();
				}
			}
			else
			{
				progress = 0f;
				progressBarR.transform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
				progressBarL.transform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
				progressBarL.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
			}
		}
		else
		{
			if (!_confirmButtonRoot.activeInHierarchy)
			{
				return;
			}
			if (buttonDown)
			{
				progress += Time.deltaTime / holdTime;
				progressBar.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
				progressBar.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
				if (progress >= 1f)
				{
					OnConfirmedPressed();
				}
			}
			else
			{
				progress = 0f;
				progressBar.transform.localScale = new UnityEngine.Vector3(Mathf.Clamp01(progress), 1f, 1f);
				progressBar.textureScale = new UnityEngine.Vector2(Mathf.Clamp01(progress), -1f);
			}
		}
	}

	private void OnConfirmedPressed()
	{
		PrivateUIRoom.RemoveUI(_uiParent.transform);
		_hasCompleted = true;
		_confirmationAction?.Invoke();
	}

	private void OnAlternativePressed()
	{
		PrivateUIRoom.RemoveUI(_uiParent.transform);
		_hasCompleted = true;
		_alternativeAction?.Invoke();
	}
}
internal class UGCPermissionManager : MonoBehaviour
{
	private interface IUGCPermissions
	{
		void Initialize();

		void CheckPermissions();
	}

	private class PlayFabPermissions : IUGCPermissions
	{
		private Action<bool> setUGCEnabled;

		public PlayFabPermissions(Action<bool> setUGCEnabled)
		{
			this.setUGCEnabled = setUGCEnabled;
		}

		public void Initialize()
		{
			bool safety = PlayFabAuthenticator.instance.GetSafety();
			setUGCEnabled?.Invoke(!safety);
		}

		public void CheckPermissions()
		{
		}
	}

	private class KIDPermissions : IUGCPermissions
	{
		private Action<bool> setUGCEnabled;

		public KIDPermissions(Action<bool> setUGCEnabled)
		{
			this.setUGCEnabled = setUGCEnabled;
		}

		private void SetUGCEnabled(bool enabled)
		{
			setUGCEnabled?.Invoke(enabled);
		}

		public void Initialize()
		{
			UnityEngine.Debug.Log("[UGCPermissionManager][KID] Initializing with KID");
			CheckPermissions();
			KIDManager.RegisterSessionUpdatedCallback_UGC(OnKIDSessionUpdate);
		}

		public void CheckPermissions()
		{
			KID.Model.Permission permissionDataByFeature = KIDManager.GetPermissionDataByFeature(EKIDFeatures.Mods);
			bool item = KIDManager.CheckFeatureOptIn(EKIDFeatures.Mods).hasOptedInPreviously;
			ProcessPermissionKID(item, permissionDataByFeature.Enabled, permissionDataByFeature.ManagedBy);
		}

		private void OnKIDSessionUpdate(bool isEnabled, KID.Model.Permission.ManagedByEnum managedBy)
		{
			UnityEngine.Debug.Log("[UGCPermissionManager][KID] KID session update.");
			bool item = KIDManager.CheckFeatureOptIn(EKIDFeatures.Mods).hasOptedInPreviously;
			ProcessPermissionKID(item, isEnabled, managedBy);
		}

		private void ProcessPermissionKID(bool hasOptedIn, bool isEnabled, KID.Model.Permission.ManagedByEnum managedBy)
		{
			UnityEngine.Debug.LogFormat("[UGCPermissionManager][KID] Process KID permissions - opted in: [{0}], enabled: [{1}], managedBy: [{2}].", hasOptedIn, isEnabled, managedBy);
			switch (managedBy)
			{
			case KID.Model.Permission.ManagedByEnum.PROHIBITED:
				UnityEngine.Debug.Log("[UGCPermissionManager][KID] KID UGC prohibited.");
				SetUGCEnabled(enabled: false);
				break;
			case KID.Model.Permission.ManagedByEnum.PLAYER:
				if (isEnabled)
				{
					UnityEngine.Debug.Log("[UGCPermissionManager][KID] KID UGC managed by player and enabled - opting in and enabling UGC.");
					if (!hasOptedIn)
					{
						KIDManager.SetFeatureOptIn(EKIDFeatures.Mods, optedIn: true);
					}
					SetUGCEnabled(enabled: true);
				}
				else
				{
					UnityEngine.Debug.LogFormat("[UGCPermissionManager][KID] KID UGC managed by player and disabled by default - using opt in status. (opted in: [{0}])", hasOptedIn);
					SetUGCEnabled(hasOptedIn);
				}
				break;
			case KID.Model.Permission.ManagedByEnum.GUARDIAN:
				UnityEngine.Debug.LogFormat("[UGCPermissionManager][KID] KID UGC managed by guardian. (opted in: [{0}], enabled: [{1}])", hasOptedIn, isEnabled);
				SetUGCEnabled(isEnabled);
				break;
			}
		}
	}

	[OnEnterPlay_SetNull]
	private static IUGCPermissions permissions;

	[OnEnterPlay_SetNull]
	private static Action onUGCEnabled;

	[OnEnterPlay_SetNull]
	private static Action onUGCDisabled;

	private static bool? isUGCEnabled;

	public static bool IsUGCDisabled => isUGCEnabled != true;

	public static void UsePlayFabSafety()
	{
		permissions = new PlayFabPermissions(SetUGCEnabled);
		permissions.Initialize();
	}

	public static void UseKID()
	{
		permissions = new KIDPermissions(SetUGCEnabled);
		permissions.Initialize();
	}

	public static void CheckPermissions()
	{
		permissions?.CheckPermissions();
	}

	public static void SubscribeToUGCEnabled(Action callback)
	{
		onUGCEnabled = (Action)Delegate.Combine(onUGCEnabled, callback);
	}

	public static void UnsubscribeFromUGCEnabled(Action callback)
	{
		onUGCEnabled = (Action)Delegate.Remove(onUGCEnabled, callback);
	}

	public static void SubscribeToUGCDisabled(Action callback)
	{
		onUGCDisabled = (Action)Delegate.Combine(onUGCDisabled, callback);
	}

	public static void UnsubscribeFromUGCDisabled(Action callback)
	{
		onUGCDisabled = (Action)Delegate.Remove(onUGCDisabled, callback);
	}

	private static void SetUGCEnabled(bool enabled)
	{
		if (enabled != isUGCEnabled)
		{
			isUGCEnabled = enabled;
			if (enabled)
			{
				onUGCEnabled?.Invoke();
			}
			else
			{
				onUGCDisabled?.Invoke();
			}
		}
	}
}
public class AnimationPauser : StateMachineBehaviour
{
