public class KIDMessagingController : MonoBehaviour
{
	private const string SHOWN_CONFIRMATION_SCREEN_PREFIX = "hasShownKIDConfirmationScreen-";

	private const string CONFIRMATION_HEADER = "Thank you";

	private const string CONFIRMATION_BODY = "k-ID setup is now complete. Thanks and have fun in Gorilla World!";

	private const string CONFIRMATION_BUTTON = "Continue";

	private const string KID_SETUP_CONFIRMATION_TITLE_KEY = "KID_SETUP_CONFIRMATION_TITLE";

	private const string KID_SETUP_CONFIRMATION_BODY_KEY = "KID_SETUP_CONFIRMATION_BODY";

	private const string KID_SETUP_CONFIRMATION_BUTTON_KEY = "KID_SETUP_CONFIRMATION_BUTTON";

	private static KIDMessagingController instance;

	[SerializeField]
	private MessageBox messageBox;

	private const string CONNECTION_ERROR_HEADER = "Connection Error";

	private const string CONNECTION_ERROR_BODY = "Unable to connect to the internet. Please restart the game and try again.";

	private const string CONNECTION_ERROR_BUTTON = "Quit";

	private bool _closeMessageBox;

	private static string HasShownConfirmationScreenPlayerPref => "hasShownKIDConfirmationScreen-" + PlayFabAuthenticator.instance.GetPlayFabPlayerId();

	public void OnConfirmPressed()
	{
		_closeMessageBox = true;
	}

	private void Awake()
	{
		if (instance != null)
		{
			UnityEngine.Debug.LogError("[KID::MESSAGING_CONTROLLER] Trying to start a new [KIDMessagingController] but one already exists");
			UnityEngine.Object.Destroy(this);
		}
		else
		{
			instance = this;
		}
	}

	private bool ShouldShowConfirmationScreen()
	{
		if (KIDManager.CurrentSession.IsDefault)
		{
			return false;
		}
		return true;
	}

	private async Task StartKIDConfirmationScreenInternal(CancellationToken token)
	{
		if (messageBox == null)
		{
			UnityEngine.Debug.LogError("[KID::MESSAGING_CONTROLLER] Trying to show confirmation screen but [messageBox] is null");
			return;
		}
		string text = await GetSetupConfirmationMessage();
		if (string.IsNullOrEmpty(text))
		{
			text = "k-ID setup is now complete. Thanks and have fun in Gorilla World!";
		}
		if (!LocalisationManager.TryGetKeyForCurrentLocale("KID_SETUP_CONFIRMATION_TITLE", out var result, "Thank you"))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::KID_MESSAGING_CONTROLLER] Failed to get key for k-ID localization [KID_SETUP_CONFIRMATION_TITLE]");
		}
		messageBox.Header = result;
		if (!LocalisationManager.TryGetKeyForCurrentLocale("KID_SETUP_CONFIRMATION_BODY", out result, text))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::KID_MESSAGING_CONTROLLER] Failed to get key for k-ID localization [KID_SETUP_CONFIRMATION_BODY]");
		}
		messageBox.Body = result;
		messageBox.LeftButton = string.Empty;
		if (!LocalisationManager.TryGetKeyForCurrentLocale("KID_SETUP_CONFIRMATION_BUTTON", out result, "Continue"))
		{
			UnityEngine.Debug.LogError("[LOCALIZATION::KID_MESSAGING_CONTROLLER] Failed to get key for k-ID localization [KID_SETUP_CONFIRMATION_BUTTON]");
		}
		messageBox.RightButton = result;
		messageBox.gameObject.SetActive(value: true);
		HandRayController.Instance.EnableHandRays();
		PrivateUIRoom.AddUI(base.transform);
		do
		{
			if (token.IsCancellationRequested)
			{
				return;
			}
			await Task.Yield();
		}
		while (!_closeMessageBox);
		PrivateUIRoom.RemoveUI(base.transform);
		HandRayController.Instance.DisableHandRays();
		messageBox.gameObject.SetActive(value: false);
		await KIDManager.TrySetHasConfirmedStatus();
	}

	public void OnDisable()
	{
		KIDAudioManager.Instance?.PlaySoundWithDelay(KIDAudioManager.KIDSoundType.PageTransition);
	}

	public static async Task StartKIDConfirmationScreen(CancellationToken token)
	{
		KIDMessagingController kIDMessagingController = instance;
		if ((object)kIDMessagingController == null || kIDMessagingController.ShouldShowConfirmationScreen())
		{
			await instance.StartKIDConfirmationScreenInternal(token);
			TelemetryData telemetryData = new TelemetryData
			{
				EventName = "kid_screen_shown",
				CustomTags = new string[3]
				{
					"kid_setup",
					KIDTelemetry.GameVersionCustomTag,
					KIDTelemetry.GameEnvironment
				},
				BodyData = new Dictionary<string, string>
				{
					{ "screen", "setup_complete" },
					{
						"saw_game_settings",
						KIDUI_MainScreen.ShownSettingsScreen.ToString().ToLower() ?? ""
					}
				}
			};
			GorillaTelemetry.EnqueueTelemetryEvent(telemetryData.EventName, telemetryData.BodyData, telemetryData.CustomTags);
		}
	}

	private static async Task<string> GetSetupConfirmationMessage()
	{
		int state = 0;
		string bodyText = string.Empty;
		PlayFabTitleDataCache.Instance.GetTitleData("KIDData", delegate(string res)
		{
			state = 1;
			bodyText = GetConfirmMessageFromTitleDataJson(res);
		}, delegate(PlayFabError err)
		{
			state = -1;
			UnityEngine.Debug.LogError("[KID_MANAGER] Something went wrong trying to get title data for key: [KIDData]. Error:\n" + err.ErrorMessage);
		});
		do
		{
			await Task.Yield();
		}
		while (state == 0);
		return bodyText;
	}

	private static string GetConfirmMessageFromTitleDataJson(string jsonTxt)
	{
		if (string.IsNullOrEmpty(jsonTxt))
		{
			UnityEngine.Debug.LogError("[KID_MANAGER] Cannot get Confirmation Message. JSON is null or empty!");
			return null;
		}
		KIDMessagingTitleData kIDMessagingTitleData = JsonConvert.DeserializeObject<KIDMessagingTitleData>(jsonTxt);
		if (kIDMessagingTitleData == null)
		{
			UnityEngine.Debug.LogError("[KID_MANAGER] Failed to parse json to [KIDMessagingTitleData]. Json: \n" + jsonTxt);
			return null;
		}
		if (string.IsNullOrEmpty(kIDMessagingTitleData.KIDSetupConfirmation))
		{
			UnityEngine.Debug.LogError("[KID_MANAGER] Failed to parse json to [KIDMessagingTitleData] - [KIDSetupConfirmation] is null or empty. Json: \n" + jsonTxt);
			return null;
		}
		return kIDMessagingTitleData.KIDSetupConfirmation;
	}

	public static void ShowConnectionErrorScreen()
	{
		if (instance == null || instance.messageBox == null)
		{
			UnityEngine.Debug.LogError("[KID::MESSAGING_CONTROLLER] No message box");
			return;
		}
		instance._closeMessageBox = false;
		instance.messageBox.Header = "Connection Error";
		instance.messageBox.Body = "Unable to connect to the internet. Please restart the game and try again.";
		instance.messageBox.RightButton = "Quit";
		instance.messageBox.ShowQuitButtonAsPrimary();
		instance.messageBox.RightButtonCallback.RemoveAllListeners();
		instance.messageBox.RightButtonCallback.AddListener(UnityEngine.Application.Quit);
		instance.messageBox.gameObject.SetActive(value: true);
		HandRayController.Instance.EnableHandRays();
		PrivateUIRoom.AddUI(instance.transform);
	}
}
public class KIDUIButton : Button, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler
{
	[SerializeField]
	private Image _borderImage;

	[SerializeField]
	private RectTransform _fillImageRef;

	[SerializeField]
	private TMP_Text _buttonText;

	[Header("Transition States")]
	[Header("Normal")]
	[SerializeField]
	[ColorUsage(true, false)]
	private Color _normalBorderColor;

	[SerializeField]
	[ColorUsage(true, false)]
	private Color _normalTextColor;

	[SerializeField]
	private float _normalBorderSize;

	[Header("Highlighted")]
	[SerializeField]
	[ColorUsage(true, false)]
	private Color _highlightedBorderColor;

	[SerializeField]
	[ColorUsage(true, false)]
	private Color _highlightedTextColor;

	[SerializeField]
	private float _highlightedBorderSize;

	[SerializeField]
	private float _highlightedVibrationStrength = 0.1f;

	[SerializeField]
	private float _highlightedVibrationDuration = 0.1f;

	[Header("Pressed")]
	[SerializeField]
	[ColorUsage(true, false)]
	private Color _pressedBorderColor;

	[SerializeField]
	[ColorUsage(true, false)]
	private Color _pressedTextColor;

	[SerializeField]
	private float _pressedBorderSize;

	[SerializeField]
	private float _pressedVibrationStrength = 0.5f;

	[SerializeField]
	private float _pressedVibrationDuration = 0.1f;

	[Header("Selected")]
	[SerializeField]
	[ColorUsage(true, false)]
	private Color _selectedBorderColor;

	[SerializeField]
	[ColorUsage(true, false)]
	private Color _selectedTextColor;

	[SerializeField]
	private float _selectedBorderSize;

	[Header("Disabled")]
	[SerializeField]
	[ColorUsage(true, false)]
	private Color _disabledBorderColor;

	[SerializeField]
	[ColorUsage(true, false)]
	private Color _disabledTextColor;

	[SerializeField]
	private float _disabledBorderSize;

	[Header("Audio")]
	[SerializeField]
	private KIDAudioManager.KIDSoundType onClickSound;

	[Header("Icon Swap Settings")]
	[SerializeField]
	private GameObject _normalIcon;

	[SerializeField]
	private GameObject _highlightedIcon;

	[Header("Steam Settings")]
	[SerializeField]
	private UXSettings _cbUXSettings;

	private bool inside;

	private static bool _triggeredThisFrame = false;

	private static bool _canTrigger = true;

	private XRUIInputModule InputModule => EventSystem.current.currentInputModule as XRUIInputModule;

	protected override void OnEnable()
	{
		base.OnEnable();
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction += PostUpdate;
		}
	}

	private void PostUpdate()
	{
		if (!_canTrigger)
		{
			_canTrigger = !ControllerBehaviour.Instance.TriggerDown;
		}
		if (base.interactable && inside && _canTrigger && (bool)ControllerBehaviour.Instance && ControllerBehaviour.Instance.TriggerDown && !_triggeredThisFrame)
		{
			string text = "[" + base.transform.parent.parent.parent.name + "." + base.transform.parent.parent.name + "." + base.transform.parent.name + "." + base.transform.name + "]";
			UnityEngine.Debug.Log("[KID::UIBUTTON::DEBUG] " + text + " - STEAM - OnClick is pressed. Time: [" + Time.time + "]", this);
			base.onClick?.Invoke();
			_triggeredThisFrame = true;
			_canTrigger = false;
		}
	}

	private void LateUpdate()
	{
		if (_triggeredThisFrame)
		{
			string text = "[" + base.transform.parent.parent.parent.name + "." + base.transform.parent.parent.name + "." + base.transform.parent.name + "." + base.transform.name + "]";
			UnityEngine.Debug.Log("[KID::UIBUTTON::DEBUG] " + text + " - STEAM - OnLateUpdate triggered and Triggered Frame Reset. Time: [" + Time.time + "]", this);
		}
		_triggeredThisFrame = false;
	}

	public override void OnPointerExit(PointerEventData eventData)
	{
		base.OnPointerExit(eventData);
		inside = false;
	}

	public void ResetButton()
	{
		inside = false;
		_triggeredThisFrame = false;
	}

	protected override void OnDisable()
	{
		FixStuckPressedState();
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction -= PostUpdate;
		}
	}

	private void FixStuckPressedState()
	{
		InstantClearState();
		_buttonText.color = (base.interactable ? _normalTextColor : _disabledTextColor);
		inside = false;
		_triggeredThisFrame = false;
	}

	protected override void DoStateTransition(SelectionState state, bool instant)
	{
		base.DoStateTransition(state, instant);
		switch (state)
		{
		default:
			_buttonText.color = _normalTextColor;
			SetIcons(normalEnabled: true, highlightedEnabled: false);
			break;
		case SelectionState.Disabled:
			_buttonText.color = _disabledTextColor;
			SetIcons(normalEnabled: true, highlightedEnabled: false);
			break;
		case SelectionState.Highlighted:
			_buttonText.color = _highlightedTextColor;
			SetIcons(normalEnabled: false, highlightedEnabled: true);
			break;
		case SelectionState.Pressed:
			_buttonText.color = _pressedTextColor;
			SetIcons(normalEnabled: true, highlightedEnabled: false);
			break;
		case SelectionState.Selected:
			_buttonText.color = _selectedTextColor;
			SetIcons(normalEnabled: true, highlightedEnabled: false);
			break;
		}
	}

	private void SetIcons(bool normalEnabled, bool highlightedEnabled)
	{
		if (!(_normalIcon == null) && !(_highlightedIcon == null))
		{
			_normalIcon?.SetActive(normalEnabled);
			_highlightedIcon?.SetActive(highlightedEnabled);
		}
	}

	public override void OnPointerEnter(PointerEventData eventData)
	{
		base.OnPointerEnter(eventData);
		inside = true;
		if (IsInteractable() && IsActive())
		{
			KIDAudioManager.Instance?.PlaySound(KIDAudioManager.KIDSoundType.Hover);
			UnityEngine.Debug.Log("[KID::UIBUTTON::KIDAudioManager] Hover played");
			XRRayInteractor xRRayInteractor = InputModule.GetInteractor(eventData.pointerId) as XRRayInteractor;
			if ((bool)xRRayInteractor)
			{
				xRRayInteractor.xrController.SendHapticImpulse(_highlightedVibrationStrength, _highlightedVibrationDuration);
			}
		}
	}

	public override void OnPointerDown(PointerEventData eventData)
	{
		base.OnPointerDown(eventData);
		inside = false;
		if (IsInteractable() && IsActive())
		{
			KIDAudioManager.Instance?.PlaySound(onClickSound);
			XRRayInteractor xRRayInteractor = InputModule.GetInteractor(eventData.pointerId) as XRRayInteractor;
			if ((bool)xRRayInteractor)
			{
				xRRayInteractor.xrController.SendHapticImpulse(_pressedVibrationStrength, _pressedVibrationDuration);
			}
		}
	}

	public void SetText(string text)
	{
		_buttonText.SetText(text);
	}

	public void SetFont(TMP_FontAsset font)
	{
		_buttonText.font = font;
	}

	public string GetText()
	{
		return _buttonText.text;
	}

	public void SetBorderImage(Sprite newImg)
	{
		_borderImage.sprite = newImg;
	}
}
public class KIDUIFeatureSetting : MonoBehaviour
{
	[SerializeField]
	private TMP_Text _featureNameTxt;

	[SerializeField]
	private TMP_Text _featureStatusTxt;

	[SerializeField]
	private KIDUIToggle _featureToggle;

	[SerializeField]
	private GameObject _tickIcon;

	[SerializeField]
	private GameObject _crossIcon;

	[SerializeField]
	private GameObject _guardianManagedLocked;

	[SerializeField]
	private GameObject _guardianManagedEnabled;

	private bool _hasToggle;

	private string _featureName;

	private string _permissionName;

	private string _enabledTextStr;

	private string _disabledTextStr;

	private EKIDFeatures _featureType;

	private Action<EKIDFeatures> _onChangeCallback;

	private KIDUI_MainScreen.FeatureToggleSetup _feature;

	public bool AlwaysCheckFeatureSetting { get; private set; }

	public void CreateNewFeatureSettingGuardianManaged(KIDUI_MainScreen.FeatureToggleSetup feature, bool isEnabled)
	{
		CreateNewFeatureSettingWithoutToggle(feature);
		_guardianManagedEnabled.SetActive(isEnabled);
		_guardianManagedLocked.SetActive(!isEnabled);
	}

	public KIDUIToggle CreateNewFeatureSettingWithToggle(KIDUI_MainScreen.FeatureToggleSetup feature, bool initialState = false, bool alwaysCheckFeatureSetting = false)
	{
		SetFeatureData(feature, alwaysCheckFeatureSetting, featureToggleEnabled: true);
		_featureToggle.SetValue(initialState);
		_featureToggle?.RegisterOnChangeEvent(SetFeatureName);
		return _featureToggle;
	}

	public void CreateNewFeatureSettingWithoutToggle(KIDUI_MainScreen.FeatureToggleSetup feature, bool alwaysCheckFeatureSetting = false)
	{
		SetFeatureData(feature, alwaysCheckFeatureSetting, featureToggleEnabled: false);
	}

	private void SetFeatureData(KIDUI_MainScreen.FeatureToggleSetup feature, bool alwaysCheckFeatureSetting, bool featureToggleEnabled)
	{
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(feature.enabledText, out var result, "ON"))
		{
			UnityEngine.Debug.LogError($"[LOCALIZATION::FEATURE_SETTING] Failed to get key for  k-ID Feature [{feature.featureName}]\n[{feature.enabledText}]", this);
		}
		_enabledTextStr = result;
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(feature.disabledText, out result, "OFF"))
		{
			UnityEngine.Debug.LogError($"[LOCALIZATION::FEATURE_SETTING] Failed to get key for  k-ID Feature [{feature.featureName}]\n[{feature.disabledText}]", this);
		}
		_disabledTextStr = result;
		_hasToggle = featureToggleEnabled;
		_featureType = feature.linkedFeature;
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(feature.featureName, out result, feature.permissionName))
		{
			UnityEngine.Debug.LogError($"[LOCALIZATION::FeatureSetting] Failed to get key for k-ID Feature [{feature.featureName}]\n[{feature.disabledText}]", this);
		}
		_featureName = result;
		SetFeatureName();
		GameObject obj = base.gameObject;
		obj.name = obj.name + "_" + feature.featureName;
		_permissionName = feature.permissionName;
		_featureToggle.gameObject.SetActive(featureToggleEnabled);
		AlwaysCheckFeatureSetting = alwaysCheckFeatureSetting;
		_feature = feature;
	}

	public void RefreshTextOnLanguageChanged()
	{
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(_feature.enabledText, out var result, "ON"))
		{
			UnityEngine.Debug.LogError($"[LOCALIZATION::FeatureSetting] Failed to get key for Game Mode [{_feature.enabledText}]");
		}
		_enabledTextStr = result;
		UnityEngine.Debug.Log("[KIDUIFeatureSetting::Language] Refreshed enabled text: " + _enabledTextStr);
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(_feature.disabledText, out result, "OFF"))
		{
			UnityEngine.Debug.LogError($"[LOCALIZATION::FeatureSetting] Failed to get key for Game Mode [{_feature.disabledText}]");
		}
		_disabledTextStr = result;
		UnityEngine.Debug.Log("[KIDUIFeatureSetting::Language] Refreshed disabled text: " + _disabledTextStr);
		if (!LocalisationManager.TryGetTranslationForCurrentLocaleWithLocString(_feature.featureName, out result, _feature.permissionName))
		{
			UnityEngine.Debug.LogError($"[LOCALIZATION::FeatureSetting] Failed to get key for Game Mode [{_feature.disabledText}]");
		}
		_featureName = result;
		UnityEngine.Debug.Log("[KIDUIFeatureSetting::Language] Refreshed feature name text: " + _featureName);
		SetFeatureName();
	}

	public void UnregisterOnToggleChangeEvent(Action action)
	{
		_featureToggle.UnregisterOnChangeEvent(action);
	}

	public void RegisterToggleOnEvent(Action action)
	{
		_featureToggle.RegisterToggleOnEvent(action);
	}

	public void UnregisterToggleOnEvent(Action action)
	{
		_featureToggle.UnregisterToggleOnEvent(action);
	}

	public void RegisterToggleOffEvent(Action action)
	{
		_featureToggle.RegisterToggleOffEvent(action);
	}

	public void UnregisterToggleOffEvent(Action action)
	{
		_featureToggle.UnregisterToggleOffEvent(action);
	}

	public bool GetFeatureToggleState()
	{
		if (_hasToggle)
		{
			return _featureToggle.IsOn;
		}
		KID.Model.Permission permissionDataByFeature = KIDManager.GetPermissionDataByFeature(_featureType);
		if (permissionDataByFeature.ManagedBy != KID.Model.Permission.ManagedByEnum.GUARDIAN)
		{
			UnityEngine.Debug.LogError("[KID::FeatureSetting] GetToggleState: feature has no toggle AND is not managed by Guardian");
		}
		return permissionDataByFeature.Enabled;
	}

	public bool GetHasToggle()
	{
		return _hasToggle;
	}

	public void SetFeatureSettingVisible(bool visible)
	{
		base.gameObject.SetActive(visible);
	}

	public void SetFeatureToggle(bool enableToggle)
	{
		_featureToggle.interactable = enableToggle;
	}

	public void SetGuardianManagedState(bool isEnabled)
	{
		_featureToggle.gameObject.SetActive(value: false);
		_guardianManagedEnabled.SetActive(isEnabled);
		_guardianManagedLocked.SetActive(!isEnabled);
		SetupGuardianManagedClickHandlers();
		SetFeatureName();
	}

	public void SetPlayerManagedState(bool isInteractable, bool isOptedIn)
	{
		_featureToggle.gameObject.SetActive(value: true);
		_guardianManagedEnabled.SetActive(value: false);
		_guardianManagedLocked.SetActive(value: false);
		_featureToggle.interactable = isInteractable;
		_featureToggle.SetValue(isOptedIn);
	}

	private void SetFeatureName()
	{
		string text = (GetFeatureToggleState() ? ("<b>(" + _enabledTextStr + ")</b>") : ("<b>(" + _disabledTextStr + ")</b>"));
		_featureNameTxt.text = "<b>" + _featureName + "</b>";
		_featureStatusTxt.text = text ?? "";
	}

	private void SetupGuardianManagedClickHandlers()
	{
		AddDeniedSoundHandler(_guardianManagedEnabled);
		AddDeniedSoundHandler(_guardianManagedLocked);
	}

	private void AddDeniedSoundHandler(GameObject obj)
	{
		if (!(obj == null))
		{
			EventTrigger component = obj.GetComponent<EventTrigger>();
			if (component != null)
			{
				UnityEngine.Object.DestroyImmediate(component);
			}
			EventTrigger eventTrigger = obj.AddComponent<EventTrigger>();
			EventTrigger.Entry entry = new EventTrigger.Entry();
			entry.eventID = EventTriggerType.PointerDown;
			entry.callback.AddListener(delegate
			{
				UnityEngine.Debug.Log("[KIDUIFeatureSetting] Guardian-managed feature clicked - playing denied sound");
				KIDAudioManager.Instance?.PlaySound(KIDAudioManager.KIDSoundType.Denied);
			});
			eventTrigger.triggers.Add(entry);
			EnsureRaycastTarget(obj);
		}
	}

	private void EnsureRaycastTarget(GameObject obj)
	{
		Graphic component = obj.GetComponent<Graphic>();
		if (component != null)
		{
			component.raycastTarget = true;
			return;
		}
		Image image = obj.GetComponent<Image>();
		if (image == null)
		{
			image = obj.AddComponent<Image>();
		}
		image.color = new Color(0f, 0f, 0f, 0f);
		image.raycastTarget = true;
	}
}
public class KIDUIHoldableButton : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IPointerUpHandler, IPointerEnterHandler, IPointerExitHandler
{
	[Serializable]
	public class ButtonHoldCompleteEvent : UnityEvent
	{
	}

	[Serializable]
	public class ButtonHoldStartEvent : UnityEvent
	{
	}

	[Serializable]
	public class ButtonHoldReleaseEvent : UnityEvent
	{
	}

	public KIDUIButton _button;

	[SerializeField]
	private float _holdDuration;

	[SerializeField]
	private Image _holdProgressFill;

	[Header("Steam Settings")]
	[SerializeField]
	private UXSettings _cbUXSettings;

	[SerializeField]
	private ButtonHoldCompleteEvent m_OnHoldComplete = new ButtonHoldCompleteEvent();

	[SerializeField]
	private ButtonHoldStartEvent m_OnHoldStart = new ButtonHoldStartEvent();

	[SerializeField]
	private ButtonHoldReleaseEvent m_OnHoldRelease = new ButtonHoldReleaseEvent();

	private bool _isHoldingButton;

	private float _elapsedTime;

	private bool inside;

	private bool _isHoldingMouse;

	private static bool _triggeredThisFrame = false;

	private static bool _canTrigger = true;

	public ButtonHoldCompleteEvent onHoldComplete
	{
		get
		{
			return m_OnHoldComplete;
		}
		set
		{
			m_OnHoldComplete = value;
		}
	}

	public float HoldPercentage => _elapsedTime / _holdDuration;

	private void OnEnable()
	{
		_holdProgressFill.rectTransform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction += PostUpdate;
		}
	}

	private void Update()
	{
		ManageButtonInteraction();
	}

	public void OnPointerDown(PointerEventData eventData)
	{
		_isHoldingMouse = true;
		ToggleHoldingButton(isPointerDown: true);
	}

	public void OnPointerUp(PointerEventData eventData)
	{
		_isHoldingMouse = false;
		ManageButtonInteraction(isPointerUp: true);
		ToggleHoldingButton(isPointerDown: false);
	}

	private void ToggleHoldingButton(bool isPointerDown)
	{
		_isHoldingButton = isPointerDown && _button.interactable;
		_holdProgressFill.rectTransform.localScale = new UnityEngine.Vector3(0f, 1f, 1f);
		if (isPointerDown)
		{
			_elapsedTime = 0f;
			m_OnHoldStart?.Invoke();
			KIDAudioManager.Instance.StartButtonHeldSound();
		}
		else
		{
			m_OnHoldRelease?.Invoke();
			KIDAudioManager.Instance.StopButtonHeldSound();
		}
	}

	private void ManageButtonInteraction(bool isPointerUp = false)
	{
		if (!_isHoldingButton || isPointerUp)
		{
			return;
		}
		if (_holdDuration <= 0f)
		{
			HoldComplete();
			return;
		}
		_elapsedTime += Time.deltaTime;
		bool num = _elapsedTime > _holdDuration;
		float num2 = _elapsedTime / _holdDuration;
		_holdProgressFill.rectTransform.localScale = new UnityEngine.Vector3(num2, 1f, 1f);
		HandRayController.Instance.PulseActiveHandray(num2, 0.1f);
		if (num)
		{
			HoldComplete();
		}
	}

	private void HoldComplete()
	{
		ToggleHoldingButton(isPointerDown: false);
		m_OnHoldComplete?.Invoke();
		UnityEngine.Debug.Log("[HOLD_BUTTON " + base.name + " ]: Hold Complete");
		ResetButton();
	}

	private void ResetButton()
	{
		_elapsedTime = 0f;
		inside = false;
		_triggeredThisFrame = false;
		_button.ResetButton();
	}

	protected void Awake()
	{
		if (!(_button != null))
		{
			_button = GetComponentInChildren<KIDUIButton>();
			if (_button == null)
			{
				UnityEngine.Debug.LogError("[KID::UI_BUTTON] Could not find [KIDUIButton] in children, trying to create a new one.");
			}
		}
	}

	private void PostUpdate()
	{
		if (!_canTrigger)
		{
			_canTrigger = !ControllerBehaviour.Instance.TriggerDown;
		}
		if (!_button.interactable || !_canTrigger || !ControllerBehaviour.Instance)
		{
			return;
		}
		if (ControllerBehaviour.Instance.TriggerDown && inside)
		{
			if (!_isHoldingButton)
			{
				string text = "[" + base.transform.parent.parent.parent.name + "." + base.transform.parent.parent.name + "." + base.transform.parent.name + "." + base.transform.name + "]";
				UnityEngine.Debug.Log("[KID::UIBUTTON::DEBUG] " + text + " - STEAM - OnClick is pressed. Time: [" + Time.time + "]", this);
				ToggleHoldingButton(isPointerDown: true);
				_triggeredThisFrame = true;
				_canTrigger = false;
			}
		}
		else if (_isHoldingButton && !_isHoldingMouse)
		{
			ToggleHoldingButton(isPointerDown: false);
		}
	}

	private void LateUpdate()
	{
		if (_triggeredThisFrame)
		{
			string text = "[" + base.transform.parent.parent.parent.name + "." + base.transform.parent.parent.name + "." + base.transform.parent.name + "." + base.transform.name + "]";
			UnityEngine.Debug.Log("[KID::UIBUTTON::DEBUG] " + text + " - STEAM - OnLateUpdate triggered and Triggered Frame Reset. Time: [" + Time.time + "]", this);
		}
		_triggeredThisFrame = false;
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		inside = true;
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		inside = false;
	}

	protected void OnDisable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction -= PostUpdate;
		}
		inside = false;
	}
}
public class KIDUIToggle : Slider
{
	[Header("Toggle Setup")]
	[SerializeField]
	[Range(0f, 1f)]
	private float _initValue;

	[SerializeField]
	private Image _borderImg;

	[SerializeField]
	private float _borderHeightRatio = 2f;

	[SerializeField]
	private Image _fillImg;

	[SerializeField]
	private Image _fillInactiveImg;

	[SerializeField]
	private Image _handleImg;

	[SerializeField]
	private Image _lockIcon;

	[SerializeField]
	private Image _unlockIcon;

	[SerializeField]
	private Image _handleLockIcon;

	[SerializeField]
	private Image _handleUnlockIcon;

	[SerializeField]
	private Color _lockActiveColor;

	[SerializeField]
	private Color _lockInactiveColor;

	[SerializeField]
	private RectTransform _borderImgRef;

	[Header("Steam Settings")]
	[SerializeField]
	private UXSettings _cbUXSettings;

	[Header("Animation")]
	[SerializeField]
	private float _animationDuration = 0.15f;

	[SerializeField]
	private AnimationCurve _toggleEase = AnimationCurve.Linear(0f, 0f, 1f, 1f);

	[Header("Fill Colors")]
	[SerializeField]
	private ColorBlock _fillColors;

	[Header("Border Colors")]
	[SerializeField]
	private ColorBlock _borderColors;

	[Header("Borders")]
	[SerializeField]
	private float _normalBorderSize = 1f;

	[SerializeField]
	private float _disabledBorderSize = 1f;

	[SerializeField]
	private float _highlightedBorderSize = 1f;

	[SerializeField]
	private float _pressedBorderSize = 1f;

	[SerializeField]
	private float _selectedBorderSize = 1f;

	[Header("Handle Colors")]
	[SerializeField]
	private ColorBlock _handleColors;

	[Header("Events")]
	[SerializeField]
	private UnityEvent _onToggleOn;

	[SerializeField]
	private UnityEvent _onToggleOff;

	[SerializeField]
	private UnityEvent _onToggleChanged;

	private bool _previousValue;

	private bool _isDisabled;

	private Coroutine _animationCoroutine;

	private bool inside;

	private static bool _triggeredThisFrame = false;

	private static bool _canTrigger = true;

	public bool CurrentValue { get; private set; }

	public bool IsOn => CurrentValue;

	protected override void Awake()
	{
		base.Awake();
		SetupToggleComponent();
	}

	protected override void Start()
	{
		base.Start();
		base.interactable = false;
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		base.interactable = false;
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction += PostUpdate;
		}
	}

	public override void OnPointerDown(PointerEventData eventData)
	{
		base.OnPointerDown(eventData);
		Toggle();
	}

	public override void OnPointerEnter(PointerEventData pointerEventData)
	{
		SetHighlighted();
		inside = true;
	}

	public override void OnPointerExit(PointerEventData pointerEventData)
	{
		SetNormal();
		inside = false;
	}

	protected virtual void SetupToggleComponent()
	{
		SetupSliderComponent();
		base.handleRect.anchorMin = new UnityEngine.Vector2(0f, 0.5f);
		base.handleRect.anchorMax = new UnityEngine.Vector3(0f, 0.5f);
		base.handleRect.pivot = new UnityEngine.Vector2(0f, 0.5f);
		base.handleRect.sizeDelta = new UnityEngine.Vector2(base.handleRect.sizeDelta.x, base.handleRect.sizeDelta.x);
	}

	protected virtual void SetupSliderComponent()
	{
		base.interactable = false;
		ColorBlock colorBlock = base.colors;
		colorBlock.disabledColor = Color.white;
		SetColors();
		base.transition = Transition.None;
	}

	public void RegisterOnChangeEvent(Action onChange)
	{
		_onToggleChanged.AddListener(delegate
		{
			onChange?.Invoke();
		});
	}

	public void UnregisterOnChangeEvent(Action onChange)
	{
		_onToggleChanged.RemoveListener(delegate
		{
			onChange?.Invoke();
		});
	}

	public void RegisterToggleOnEvent(Action onToggle)
	{
		_onToggleOn.AddListener(delegate
		{
			onToggle?.Invoke();
		});
	}

	public void UnregisterToggleOnEvent(Action onToggle)
	{
		_onToggleOn.RemoveListener(delegate
		{
			onToggle?.Invoke();
		});
	}

	public void RegisterToggleOffEvent(Action onToggle)
	{
		_onToggleOff.AddListener(delegate
		{
			onToggle?.Invoke();
		});
	}

	public void UnregisterToggleOffEvent(Action onToggle)
	{
		_onToggleOff.RemoveListener(delegate
		{
			onToggle?.Invoke();
		});
	}

	private void SetColors()
	{
		base.colors = _fillColors;
	}

	private void Toggle()
	{
		if (!_isDisabled)
		{
			SetStateAndStartAnimation(!CurrentValue);
		}
	}

	public void SetValue(bool newValue)
	{
		if (newValue != CurrentValue)
		{
			SetStateAndStartAnimation(newValue);
		}
	}

	private void SetStateAndStartAnimation(bool state, bool skipAnim = false)
	{
		if (CurrentValue == state)
		{
			UnityEngine.Debug.Log("IS SAME STATE, WILL NOT CHANGE");
			return;
		}
		CurrentValue = state;
		_onToggleChanged?.Invoke();
		if (CurrentValue)
		{
			_onToggleOn?.Invoke();
			KIDAudioManager.Instance.PlaySound(KIDAudioManager.KIDSoundType.Success);
		}
		else
		{
			_onToggleOff?.Invoke();
			KIDAudioManager.Instance.PlaySound(KIDAudioManager.KIDSoundType.TurnOffPermission);
		}
		if (_animationCoroutine != null)
		{
			StopCoroutine(_animationCoroutine);
		}
		_handleUnlockIcon.gameObject.SetActive(CurrentValue);
		_handleLockIcon.gameObject.SetActive(!CurrentValue);
		if (_animationDuration == 0f || skipAnim)
		{
			UnityEngine.Debug.Log("[KID::UI::SetStateAndStartAnimation] Skipping animation. Setting value to " + (CurrentValue ? "1f" : "0f"));
			value = (CurrentValue ? 1f : 0f);
		}
		else
		{
			_animationCoroutine = StartCoroutine(AnimateSlider());
		}
	}

	private IEnumerator AnimateSlider()
	{
		UnityEngine.Debug.Log($"[KID::UI::TOGGLE] Toggle: [{base.name}] is {CurrentValue}");
		float startValue = (CurrentValue ? 0f : 1f);
		float endValue = (CurrentValue ? 1f : 0f);
		UnityEngine.Debug.Log($"[KID::UI::TOGGLE] Toggle: [{base.name}] Start: {startValue}, End: {endValue}, Value: {value}");
		float time = 0f;
		while (time < _animationDuration)
		{
			time += Time.deltaTime;
			float t = _toggleEase.Evaluate(time / _animationDuration);
			value = Mathf.Lerp(startValue, endValue, t);
			yield return null;
		}
		value = endValue;
	}

	private void PostUpdate()
	{
		if (inside && (bool)ControllerBehaviour.Instance)
		{
			if (ControllerBehaviour.Instance.TriggerDown && _canTrigger)
			{
				string text = "[" + base.transform.parent.parent.parent.name + "." + base.transform.parent.parent.name + "." + base.transform.parent.name + "." + base.transform.name + "]";
				UnityEngine.Debug.Log("[KID::UIBUTTON::DEBUG] " + text + " - STEAM - OnClick is pressed. Time: [" + Time.time + "]", this);
				Toggle();
				_triggeredThisFrame = true;
				_canTrigger = false;
			}
			else if (!ControllerBehaviour.Instance.TriggerDown)
			{
				_canTrigger = true;
			}
		}
	}

	private void LateUpdate()
	{
		if (_triggeredThisFrame)
		{
			string text = "[" + base.transform.parent.parent.parent.name + "." + base.transform.parent.parent.name + "." + base.transform.parent.name + "." + base.transform.name + "]";
			UnityEngine.Debug.Log("[KID::UIBUTTON::DEBUG] " + text + " - STEAM - OnLateUpdate triggered and Triggered Frame Reset. Time: [" + Time.time + "]", this);
		}
		_triggeredThisFrame = false;
	}

	protected new void OnDisable()
	{
		if ((bool)ControllerBehaviour.Instance)
		{
			ControllerBehaviour.Instance.OnAction -= PostUpdate;
		}
		inside = false;
	}

	private void SetDisabled(bool isLockedButEnabled)
	{
		SetSwitchColors(_borderColors.disabledColor, _handleColors.disabledColor, _fillColors.disabledColor);
		SetBorderSize(_disabledBorderSize);
		SetBackgroundActive(isActive: false);
	}

	private void SetNormal()
	{
		if (!_isDisabled)
		{
			SetSwitchColors(_borderColors.normalColor, _handleColors.normalColor, _fillColors.normalColor);
			SetBorderSize(_normalBorderSize);
			SetBackgroundActive(isActive: false);
		}
	}

	private void SetSelected()
	{
		if (!_isDisabled)
		{
			SetSwitchColors(_borderColors.selectedColor, _handleColors.selectedColor, _fillColors.selectedColor);
			SetBorderSize(_selectedBorderSize);
			SetBackgroundActive(isActive: true);
		}
	}

	private void SetHighlighted()
	{
		if (!_isDisabled)
		{
			SetSwitchColors(_borderColors.highlightedColor, _handleColors.highlightedColor, _fillColors.highlightedColor);
			SetBorderSize(_highlightedBorderSize);
			SetBackgroundActive(isActive: true);
		}
	}

	private void SetPressed()
	{
		if (!_isDisabled)
		{
			SetSwitchColors(_borderColors.pressedColor, _handleColors.pressedColor, _fillColors.pressedColor);
			SetBorderSize(_pressedBorderSize);
			SetBackgroundActive(isActive: true);
		}
	}

	private void SetSwitchColors(Color borderColor, Color handleColor, Color fillColor)
	{
		_borderImg.color = borderColor;
		_handleImg.color = handleColor;
	}

	private void SetBorderSize(float borderScale)
	{
		_borderImgRef.offsetMin = new UnityEngine.Vector2(0f - borderScale, (0f - borderScale) * _borderHeightRatio);
		_borderImgRef.offsetMax = new UnityEngine.Vector2(borderScale, borderScale * _borderHeightRatio);
	}

	private void SetBackgroundActive(bool isActive)
	{
		_fillImg.gameObject.SetActive(isActive);
		_fillInactiveImg.gameObject.SetActive(!isActive);
		SetBackgroundLocksActive(isActive);
	}

	private void SetBackgroundLocksActive(bool isActive)
	{
		Color color = (isActive ? _lockActiveColor : _lockInactiveColor);
		_lockIcon.color = color;
		_unlockIcon.color = color;
	}
}
public class KIDUIToggleGroupManager : MonoBehaviour
{
