{
	public float startingSize;
}
public class KIDUI_AnimatedEllipsis : MonoBehaviour
{
	[Header("Ellipsis Spawning")]
	[SerializeField]
	private bool _animateOnStart = true;

	[SerializeField]
	private int _ellipsisCount = 3;

	[SerializeField]
	private GameObject _ellipsisPrefab;

	[SerializeField]
	private GameObject _ellipsisRoot;

	[SerializeField]
	private List<float> _ellipsisStartingValues = new List<float>();

	[Header("Animation Settings")]
	[SerializeField]
	private bool _shouldLerp;

	[SerializeField]
	private AnimationCurve _ellipsisAnimationCurve;

	[SerializeField]
	private float _animationSpeedMultiplier = 0.25f;

	[SerializeField]
	private float _startingScale = 0.33f;

	[SerializeField]
	private float _intermediaryScale = 0.66f;

	[SerializeField]
	private float _endScale = 1f;

	[SerializeField]
	private float _scaleDuration = 0.25f;

	[SerializeField]
	private float _pauseBetweenScale = 0.25f;

	[SerializeField]
	private float _pauseBetweenCycles = 0.5f;

	private bool _runAnimation;

	private float _nextChange;

	private (GameObject ellipsis, float startingScale, float currentScale, float lerpT)[] _ellipsisObjects;

	private Coroutine _animationCoroutine;

	private void Awake()
	{
		if (_ellipsisObjects == null)
		{
			SetupEllipsis();
		}
	}

	private void Start()
	{
	}

	private void OnDisable()
	{
		StopAnimation();
	}

	private void SetupEllipsis()
	{
		if (_ellipsisRoot == null)
		{
			_ellipsisRoot = base.gameObject;
		}
		_ellipsisObjects = new(GameObject, float, float, float)[_ellipsisStartingValues.Count];
		for (int i = 0; i < _ellipsisStartingValues.Count; i++)
		{
			float num = _ellipsisStartingValues[i];
			_ellipsisObjects[i].ellipsis = UnityEngine.Object.Instantiate(_ellipsisPrefab, _ellipsisRoot.transform);
			_ellipsisObjects[i].ellipsis.transform.localScale = new UnityEngine.Vector3(num, num, num);
			_ellipsisObjects[i].startingScale = (_ellipsisObjects[i].currentScale = num);
		}
	}

	private IEnumerator EllipsisAnimation()
	{
		int currIndex = 0;
		while (_runAnimation)
		{
			for (int i = 0; i < _ellipsisObjects.Length; i++)
			{
				int num = i - currIndex;
				if (num < 0)
				{
					num = _ellipsisStartingValues.Count + num;
				}
				float num2 = _ellipsisStartingValues[num];
				_ellipsisObjects[i].ellipsis.transform.localScale = UnityEngine.Vector3.one * num2;
			}
			currIndex++;
			if (currIndex >= _ellipsisObjects.Length)
			{
				currIndex = 0;
			}
			yield return new WaitForSeconds(_pauseBetweenScale);
		}
	}

	private IEnumerator EllipsisAnimation2()
	{
		float time = 0f;
		while (_runAnimation)
		{
			for (int i = 0; i < _ellipsisObjects.Length; i++)
			{
				float offsetTime = _scaleDuration / (float)(_ellipsisObjects.Length + 1) * (float)i;
				float num = LerpLoop(_startingScale, _endScale, time, offsetTime, _scaleDuration);
				_ellipsisObjects[i].ellipsis.transform.localScale = new UnityEngine.Vector3(num, num, num);
			}
			time += Time.deltaTime * _animationSpeedMultiplier;
			yield return null;
		}
	}

	public async Task StartAnimation()
	{
		if (_ellipsisObjects == null)
		{
			SetupEllipsis();
		}
		if (_animationCoroutine != null)
		{
			UnityEngine.Debug.LogWarningFormat("[KID::UI::ELLIPSIS] Animation is already running.");
			await StopAnimation();
		}
		for (int i = 0; i < _ellipsisCount; i++)
		{
			_ellipsisObjects[i].ellipsis.transform.localScale = new UnityEngine.Vector3(_ellipsisObjects[i].startingScale, _ellipsisObjects[i].startingScale, _ellipsisObjects[i].startingScale);
		}
		_ellipsisRoot.SetActive(value: true);
		_runAnimation = true;
		if (_shouldLerp)
		{
			_animationCoroutine = StartCoroutine(EllipsisAnimation2());
		}
		else
		{
			_animationCoroutine = StartCoroutine(EllipsisAnimation());
		}
	}

	public async Task StopAnimation()
	{
		_runAnimation = false;
		StopAllCoroutines();
		await Task.Delay(100);
		_animationCoroutine = null;
		_ellipsisRoot.SetActive(value: false);
	}

	public float LerpLoop(float start, float end, float time, float offsetTime, float duration)
	{
		float time2 = (offsetTime - time) % duration / duration;
		float t = _ellipsisAnimationCurve.Evaluate(time2);
		return Mathf.Lerp(start, end, t);
	}
}
public class KIDUI_ConfirmScreen : MonoBehaviour
{
	[SerializeField]
	private TMP_Text _emailToConfirmTxt;

	[SerializeField]
	private KIDUI_MainScreen _mainScreen;

	[SerializeField]
	private KIDUI_SetupScreen _setupScreen;

	[SerializeField]
	private KIDUI_ErrorScreen _errorScreen;

	[SerializeField]
	private KIDUI_EmailSuccess _successScreen;

	[SerializeField]
	private KIDUI_AnimatedEllipsis _animatedEllipsis;

	[SerializeField]
	private KIDUIButton _confirmButton;

	[SerializeField]
	private KIDUIButton _backButton;

	[SerializeField]
	private int _minimumDelay = 1000;

	private string _submittedEmailAddress;

	private CancellationTokenSource _cancellationTokenSource;

	private bool _hasCompletedSendEmailRequest;

	private bool _emailRequestResult;

	private void Awake()
	{
		if (_emailToConfirmTxt == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] Email To Confirm Field is NULL");
		}
		else if (_setupScreen == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] Setup K-ID Screen is NULL");
		}
		else if (_mainScreen == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] Main Screen is NULL");
		}
		else
		{
			_cancellationTokenSource = new CancellationTokenSource();
		}
	}

	private void OnEnable()
	{
		_confirmButton.interactable = true;
		_backButton.interactable = true;
	}

	public void OnEmailSubmitted(string emailAddress)
	{
		_submittedEmailAddress = emailAddress;
		_emailToConfirmTxt.text = _submittedEmailAddress;
		base.gameObject.SetActive(value: true);
	}

	public async void OnConfirmPressed()
	{
		TelemetryData telemetryData = new TelemetryData
		{
			EventName = "kid_email_confirm",
			CustomTags = new string[3]
			{
				"kid_setup",
				KIDTelemetry.GameVersionCustomTag,
				KIDTelemetry.GameEnvironment
			},
			BodyData = new Dictionary<string, string> { { "button_pressed", "confirm" } }
		};
		GorillaTelemetry.EnqueueTelemetryEvent(telemetryData.EventName, telemetryData.BodyData, telemetryData.CustomTags);
		_confirmButton.interactable = false;
		_backButton.interactable = false;
		await _animatedEllipsis.StartAnimation();
		UnityEngine.Debug.Log("[KID::UI::CONFIRM_EMAIL] Ellipsis Animation Complete, proceeding to send email");
		(bool success, string message) result = await KIDManager.SetAndSendEmail(_submittedEmailAddress);
		do
		{
			await Task.Yield();
		}
		while (!_hasCompletedSendEmailRequest);
		UnityEngine.Debug.Log($"[KID::UI::CONFIRM_EMAIL] Email has been sent, awaiting minimum duration {_minimumDelay}");
		if (_minimumDelay > 0)
		{
			await Task.Delay(_minimumDelay);
		}
		base.gameObject.SetActive(value: false);
		if (!result.success)
		{
			ShowErrorScreen(result.message);
			return;
		}
		UnityEngine.Debug.Log("[KID::UI::CONFIRM_EMAIL] Minimum duration passed, result is successful. Proceeding to Success screen");
		KIDAudioManager.Instance?.PlaySoundWithDelay(KIDAudioManager.KIDSoundType.PageTransition);
		_mainScreen.OnConfirmedEmailAddress(_submittedEmailAddress);
		_successScreen.ShowSuccessScreen(_submittedEmailAddress);
	}

	public async void OnBackPressed()
	{
		TelemetryData telemetryData = new TelemetryData
		{
			EventName = "kid_email_confirm",
			CustomTags = new string[3]
			{
				"kid_setup",
				KIDTelemetry.GameVersionCustomTag,
				KIDTelemetry.GameEnvironment
			},
			BodyData = new Dictionary<string, string> { { "button_pressed", "go_back" } }
		};
		GorillaTelemetry.EnqueueTelemetryEvent(telemetryData.EventName, telemetryData.BodyData, telemetryData.CustomTags);
		_cancellationTokenSource.Cancel();
		await _animatedEllipsis.StopAnimation();
		base.gameObject.SetActive(value: false);
		_setupScreen.OnStartSetup();
	}

	public void NotifyOfResult(bool success)
	{
		_hasCompletedSendEmailRequest = true;
		_emailRequestResult = success;
	}

	private async void ShowErrorScreen(string errorMessage)
	{
		UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] K-ID Confirmation Failed - Failed to send email");
		_cancellationTokenSource.Cancel();
		await _animatedEllipsis.StopAnimation();
		base.gameObject.SetActive(value: false);
		_errorScreen.ShowErrorScreen("Confirmation Error", _submittedEmailAddress, errorMessage);
	}

	public void OnDisable()
	{
		KIDAudioManager.Instance?.PlaySoundWithDelay(KIDAudioManager.KIDSoundType.PageTransition);
	}
}
public class KIDUI_Controller : MonoBehaviour
{
	public enum Metrics_ShowReason
	{
		None,
		Inaccessible,
		Guardian_Disabled,
		Permissions_Changed,
		Default_Session,
		No_Session
	}

	private const string CLOSE_BLACK_SCREEN_ETAG_PLAYER_PREF_PREFIX = "closeBlackScreen-";

	private const string FIRST_TIME_POST_CHANGE_PLAYER_PREF = "hasShownFirstTimePostChange-";

	private static KIDUI_Controller _instance;

	[SerializeField]
	private KIDUI_MainScreen _mainKIDScreen;

	[SerializeField]
	private KIDUI_ConfirmScreen _confirmScreen;

	[SerializeField]
	private List<string> _PermissionsWithToggles = new List<string>();

	[SerializeField]
	private List<EKIDFeatures> _inaccessibleSettings = new List<EKIDFeatures>
	{
		EKIDFeatures.Multiplayer,
		EKIDFeatures.Mods
	};

	private Metrics_ShowReason _showReason;

	private bool _isKidUIActive;

	private static string etagOnCloseBlackScreenPlayerPrefStr;

	private string _lastEtagOnClose;

	public static KIDUI_Controller Instance => _instance;

	public static bool IsKIDUIActive
	{
		get
		{
			if (Instance == null)
			{
				return false;
			}
			return Instance._isKidUIActive;
		}
	}

	private static string EtagOnCloseBlackScreenPlayerPrefRef
	{
		get
		{
			if (string.IsNullOrEmpty(etagOnCloseBlackScreenPlayerPrefStr))
			{
				etagOnCloseBlackScreenPlayerPrefStr = "closeBlackScreen-" + PlayFabAuthenticator.instance.GetPlayFabPlayerId();
			}
			return etagOnCloseBlackScreenPlayerPrefStr;
		}
	}

	private void Awake()
	{
		_instance = this;
		UnityEngine.Debug.LogFormat("[KID::UI::CONTROLLER] Controller Initialised");
	}

	private void OnDestroy()
	{
		KIDManager.onEmailResultReceived = (KIDManager.OnEmailResultReceived)Delegate.Remove(KIDManager.onEmailResultReceived, new KIDManager.OnEmailResultReceived(NotifyOfEmailResult));
	}

	public async Task StartKIDScreens(CancellationToken cancellationToken)
	{
		UnityEngine.Debug.LogFormat("[KID::UI::CONTROLLER] Starting k-ID Screens");
		bool flag = await ShouldShowKIDScreen(cancellationToken);
		if (cancellationToken.IsCancellationRequested)
		{
			return;
		}
		if (!flag)
		{
			UnityEngine.Debug.LogFormat("[KID::UI::CONTROLLER] Should NOT Show k-ID Screens");
			return;
		}
		PrivateUIRoom.ForceStartOverlay(PrivateUIRoom.OverlaySource.KID);
		UnityEngine.Debug.LogFormat("[KID::UI::CONTROLLER] Showing k-ID Screens");
		while (HandRayController.Instance == null)
		{
			await Task.Yield();
		}
		HandRayController.Instance.EnableHandRays();
		PrivateUIRoom.AddUI(base.transform);
		EMainScreenStatus screenStatusFromSession = GetScreenStatusFromSession();
		_mainKIDScreen.ShowMainScreen(screenStatusFromSession, _showReason);
		_isKidUIActive = true;
		KIDManager.onEmailResultReceived = (KIDManager.OnEmailResultReceived)Delegate.Combine(KIDManager.onEmailResultReceived, new KIDManager.OnEmailResultReceived(NotifyOfEmailResult));
	}

	public void CloseKIDScreens()
	{
		SaveEtagOnCloseScreen();
		_isKidUIActive = false;
		_mainKIDScreen.HideMainScreen();
		KIDAudioManager.Instance?.PlaySoundWithDelay(KIDAudioManager.KIDSoundType.PageTransition);
		PrivateUIRoom.RemoveUI(base.transform);
		HandRayController.Instance.DisableHandRays();
		UnityEngine.Object.DestroyImmediate(base.gameObject);
		KIDManager.onEmailResultReceived = (KIDManager.OnEmailResultReceived)Delegate.Remove(KIDManager.onEmailResultReceived, new KIDManager.OnEmailResultReceived(NotifyOfEmailResult));
	}

	public void UpdateScreenStatus()
	{
		EMainScreenStatus screenStatusFromSession = GetScreenStatusFromSession();
		_mainKIDScreen?.UpdateScreenStatus(screenStatusFromSession, sendMetrics: true);
	}

	public void NotifyOfEmailResult(bool success)
	{
		if (_confirmScreen == null)
		{
			UnityEngine.Debug.LogError("[KID::UI_CONTROLLER] _confirmScreen has not been set yet and is NULL. Cannot inform of result");
			return;
		}
		if (success)
		{
			PlayerPrefs.SetInt(KIDManager.GetChallengedBeforePlayerPrefRef, 1);
			PlayerPrefs.Save();
		}
		UnityEngine.Debug.Log("[KID::UI_CONTROLLER] Notifying user about email result. Showing confirm screen.");
		_confirmScreen.NotifyOfResult(success);
	}

	private EMainScreenStatus GetScreenStatusFromSession()
	{
		EMainScreenStatus eMainScreenStatus = EMainScreenStatus.None;
		switch (KIDManager.CurrentSession.SessionStatus)
		{
		case SessionStatus.CHALLENGE:
		case SessionStatus.CHALLENGE_SESSION_UPGRADE:
		case SessionStatus.PENDING_AGE_APPEAL:
			if (string.IsNullOrEmpty(PlayerPrefs.GetString(KIDManager.GetEmailForUserPlayerPrefRef, "")))
			{
				return EMainScreenStatus.Setup;
			}
			return EMainScreenStatus.Pending;
		case SessionStatus.PASS:
			if (ShouldShowScreenOnPermissionChange())
			{
				return EMainScreenStatus.Updated;
			}
			if (KIDManager.PreviousStatus == SessionStatus.CHALLENGE_SESSION_UPGRADE)
			{
				return EMainScreenStatus.Declined;
			}
			return EMainScreenStatus.Missing;
		case SessionStatus.PROHIBITED:
			UnityEngine.Debug.LogError("[KID::KIDUI_CONTROLLER] Status is PROHIBITED but is trying to show k-ID screens");
			return EMainScreenStatus.Declined;
		default:
			UnityEngine.Debug.LogError("[KID::KIDUI_CONTROLLER] Unknown status");
			return EMainScreenStatus.None;
		}
	}

	private async Task<bool> ShouldShowKIDScreen(CancellationToken cancellationToken)
	{
		if (KIDManager.CurrentSession == null)
		{
			_showReason = Metrics_ShowReason.No_Session;
			return true;
		}
		if (!KIDManager.CurrentSession.IsValidSession)
		{
			while (!KIDManager.CurrentSession.IsValidSession)
			{
				UnityEngine.Debug.Log("[KID::UI::CONTROLLER] K-ID Session not found yet");
				await Task.Delay(100, cancellationToken);
			}
		}
		UnityEngine.Debug.Log("[KID::UI::CONTROLLER] K-ID Session has been found and is proceeding ");
		if (KIDManager.HasAllPermissions())
		{
			return false;
		}
		for (int i = 0; i < _inaccessibleSettings.Count; i++)
		{
			KID.Model.Permission permissionDataByFeature = KIDManager.GetPermissionDataByFeature(_inaccessibleSettings[i]);
			if (permissionDataByFeature == null)
			{
				UnityEngine.Debug.LogErrorFormat($"[KID::UI::CONTROLLER] Failed to get Permission with name [{_inaccessibleSettings[i]}]");
				return true;
			}
			if (permissionDataByFeature.ManagedBy != KID.Model.Permission.ManagedByEnum.PROHIBITED && !KIDManager.CheckFeatureSettingEnabled(_inaccessibleSettings[i]))
			{
				_showReason = Metrics_ShowReason.Inaccessible;
				if (KIDManager.CurrentSession.IsDefault)
				{
					_showReason = Metrics_ShowReason.Default_Session;
				}
				return true;
			}
		}
		List<KID.Model.Permission> allPermissionsData = KIDManager.GetAllPermissionsData();
		for (int j = 0; j < allPermissionsData.Count; j++)
		{
			if (allPermissionsData[j].ManagedBy == KID.Model.Permission.ManagedByEnum.GUARDIAN && !allPermissionsData[j].Enabled)
			{
				_showReason = Metrics_ShowReason.Guardian_Disabled;
				if (KIDManager.CurrentSession.IsDefault)
				{
					_showReason = Metrics_ShowReason.Default_Session;
				}
				return true;
			}
		}
		_mainKIDScreen.InitialiseMainScreen();
		if (_mainKIDScreen.GetFeatureListingCount() == 0)
		{
			UnityEngine.Debug.Log("[KID::CONTROLLER] Nothing to show on k-ID UI. Skipping");
			return false;
		}
		if (ShouldShowScreenOnPermissionChange())
		{
			_showReason = Metrics_ShowReason.Permissions_Changed;
			return true;
		}
		return false;
	}

	private bool ShouldShowScreenOnPermissionChange()
	{
		_lastEtagOnClose = GetLastBlackScreenEtag();
		return _lastEtagOnClose != (KIDManager.CurrentSession?.Etag ?? string.Empty);
	}

	private string GetLastBlackScreenEtag()
	{
		return PlayerPrefs.GetString(EtagOnCloseBlackScreenPlayerPrefRef, "");
	}

	private void SaveEtagOnCloseScreen()
	{
		if (KIDManager.CurrentSession == null)
		{
			UnityEngine.Debug.Log("[KID::MANAGER] Trying to save Pre-Game Screen ETAG, but [CurrentSession] is null");
			return;
		}
		PlayerPrefs.SetString(EtagOnCloseBlackScreenPlayerPrefRef, KIDManager.CurrentSession.Etag);
		PlayerPrefs.Save();
	}

	public void OnDisable()
	{
		KIDAudioManager.Instance?.PlaySoundWithDelay(KIDAudioManager.KIDSoundType.PageTransition);
	}
}
