	private void Awake()
	{
		if (_emailInputField == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] Email Input Field is NULL");
		}
		else if (_confirmScreen == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] Confirm Screen is NULL");
		}
		else if (_mainScreen == null)
		{
			UnityEngine.Debug.LogErrorFormat("[KID::UI::Setup] Main Screen is NULL");
		}
	}

	private void OnEnable()
	{
		string text = PlayerPrefs.GetString(KIDManager.GetEmailForUserPlayerPrefRef, "");
		_emailInputField.text = text;
		_confirmButton.ResetButton();
		OnInputChanged(text);
