public class LocalisationManager : MonoBehaviour
{
	public const string ENGLISH_IDENTIFIER = "en";

	public const string FRENCH_IDENTIFIER = "fr";

	public const string GERMAN_IDENTIFIER = "de";

	public const string ITALIAN_IDENTIFIER = "it";

	public const string SPANISH_IDENTIFIER = "es";

	public const string JAPENESE_IDENTIFIER = "ja";

	private static LocalisationManager _instance;

	[SerializeField]
	private List<LocalisationFontPair> _localisationFonts = new List<LocalisationFontPair>();

	private bool _cachedHasInitialised;

	private static bool _hasInitialised = false;

	private const string LANGUAGE_SET_PLAYER_PREF = "has-set-language";

	private const string LOC_SYSTEM_PLAYER_PREF = "selected-locale";

	private static Locale _initLocale;

	private static Action _onLanguageChanged;

	private Coroutine _updateLangCoroutine;

	private static CancellationTokenSource _requestCancellationSource;

	private static Dictionary<int, Locale> _localeDisplayBinding = new Dictionary<int, Locale>();

	private static Dictionary<string, UnityEngine.Localization.Tables.StringTable> _localeTablePairs = new Dictionary<string, UnityEngine.Localization.Tables.StringTable>();

	private static Dictionary<string, LocalisationFontPair> _localisationFontDict = new Dictionary<string, LocalisationFontPair>();

	public static LocalisationManager Instance => _instance;

	public static bool IsReady
	{
		get
		{
			if (Instance != null)
			{
				return _localeTablePairs.Count != 0;
			}
			return false;
		}
	}

	public static bool LanguageSet => PlayerPrefs.GetInt("has-set-language", 0) == 1;

	public static Locale CurrentLanguage => LocalizationSettings.SelectedLocale;

	private static string LanugageSetPlayerPrefKey => "selected-locale";

	public static bool ApplicationRunning
	{
		get
		{
			if (UnityEngine.Application.isPlaying)
			{
				return !ApplicationQuittingState.IsQuitting;
			}
			return false;
		}
	}

	private void Awake()
	{
		if (_instance != null)
		{
			UnityEngine.Object.DestroyImmediate(this);
			return;
		}
		_instance = this;
		base.transform.SetParent(null);
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		_localisationFontDict.Clear();
		for (int i = 0; i < _localisationFonts.Count; i++)
		{
			for (int j = 0; j < _localisationFonts[i].locales.Count; j++)
			{
				if (!(_localisationFonts[i].locales[j] == null) && !_localisationFontDict.ContainsKey(_localisationFonts[i].locales[j].Identifier.Code) && !(_localisationFonts[i].fontAsset == null))
				{
					_localisationFontDict.Add(_localisationFonts[i].locales[j].Identifier.Code, _localisationFonts[i]);
					UnityEngine.Debug.Log("[LOCALIZATION::MANAGER] Added new Locale-Font pair to Dictionary: [" + _localisationFonts[i].locales[j].LocaleName + "]");
				}
			}
		}
		_requestCancellationSource = new CancellationTokenSource();
	}

	private async void Start()
	{
		TryUpdateLanguage(_initLocale, saveLanguage: false);
		if (!LanguageSet)
		{
			HandRayController.Instance.EnableHandRays();
			PrivateUIRoom.AddUI(LocalisationUI.GetUITransform());
		}
	}

	private void OnDestroy()
	{
		_requestCancellationSource.Cancel();
		_onLanguageChanged = null;
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSplashScreen)]
	private static void InitialiseLocTables()
	{
		CultureInfo.CurrentCulture = new CultureInfo("en");
		CacheLocTables();
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void InitialiseLanguage()
	{
		_hasInitialised = false;
		string text = PlayerPrefs.GetString(LanugageSetPlayerPrefKey, "");
		Locale result = null;
		if (!string.IsNullOrEmpty(text) && LanguageSet)
		{
			LoadPreviousLanguage(text, out result);
		}
		else
		{
			DefaultLocaleFallback(out result);
		}
		MothershipClientApiUnity.SetLanguage(result.Identifier.Code);
		_initLocale = result;
		_hasInitialised = true;
	}

	private static void CacheLocTables()
	{
		_localeTablePairs.Clear();
		_ = Time.time;
		foreach (Locale locale in LocalizationSettings.AvailableLocales.Locales)
		{
			AsyncOperationHandle<IList<UnityEngine.Localization.Tables.StringTable>> allTables = LocalizationSettings.StringDatabase.GetAllTables(locale);
			allTables.WaitForCompletion();
			IList<UnityEngine.Localization.Tables.StringTable> result = allTables.Result;
			if (result.Count != 0)
			{
				_ = result.Count;
				_ = 1;
				_localeTablePairs.Add(locale.Identifier.Code, result[0]);
			}
		}
	}

	public void OnLanguageButtonPressed(string langCode, bool saveLanguage)
	{
		if (TryGetLocaleFromCode(langCode, out var result))
		{
			TryUpdateLanguage(result, saveLanguage);
		}
	}

	private void ReconstructBindings()
	{
		int num = 1;
		_localeDisplayBinding.Clear();
		foreach (Locale locale in LocalizationSettings.AvailableLocales.Locales)
		{
			_localeDisplayBinding.Add(num, locale);
			num++;
		}
	}

	private static void LoadPreviousLanguage(string languageCode, out Locale result)
	{
		if (!TryGetLocaleFromCode(languageCode, out result))
		{
			DefaultLocaleFallback(out result);
			return;
		}
		PlayerPrefs.SetString(LanugageSetPlayerPrefKey, result.Identifier.Code);
		PlayerPrefs.SetInt("has-set-language", 1);
		PlayerPrefs.Save();
	}

	private static void DefaultLocaleFallback(out Locale result)
	{
		if (SysLangToLoc(UnityEngine.Application.systemLanguage, out result))
		{
			PlayerPrefs.SetString(LanugageSetPlayerPrefKey, result.Identifier.Code);
			PlayerPrefs.SetInt("has-set-language", 1);
			PlayerPrefs.Save();
		}
	}

	private static bool SysLangToLoc(SystemLanguage sysLanguage, out Locale language)
	{
		switch (sysLanguage)
		{
		default:
			language = LocalizationSettings.Instance.GetAvailableLocales().GetLocale("en");
			_ = language == null;
			return false;
		case SystemLanguage.English:
			language = LocalizationSettings.Instance.GetAvailableLocales().GetLocale("en");
			return language != null;
		case SystemLanguage.French:
			language = LocalizationSettings.Instance.GetAvailableLocales().GetLocale("fr");
			return language != null;
		case SystemLanguage.German:
			language = LocalizationSettings.Instance.GetAvailableLocales().GetLocale("de");
			return language != null;
		case SystemLanguage.Spanish:
			language = LocalizationSettings.Instance.GetAvailableLocales().GetLocale("es");
			return language != null;
		}
	}

	private void TryUpdateLanguage(Locale newLocale, bool saveLanguage = true)
	{
		if (_updateLangCoroutine != null)
		{
			StopCoroutine(_updateLangCoroutine);
		}
		_updateLangCoroutine = StartCoroutine(UpdateLanguage(newLocale, saveLanguage));
	}

	private IEnumerator UpdateLanguage(Locale newLocale, bool saveLanguage)
	{
		if (!_cachedHasInitialised)
		{
			yield return LocalizationSettings.InitializationOperation;
		}
		_cachedHasInitialised = true;
		if (!(CurrentLanguage.Identifier.Code == newLocale.Identifier.Code))
		{
			TelemetryData telemetryData = new TelemetryData
			{
				EventName = "language_changed",
				CustomTags = new string[1] { LocalizationTelemetry.GameVersionCustomTag },
				BodyData = new Dictionary<string, string>
				{
					{
						"starting_language",
						CurrentLanguage.Identifier.Code
					},
					{
						"new_language",
						newLocale.Identifier.Code
					}
				}
			};
			MothershipClientApiUnity.SetLanguage(newLocale.Identifier.Code);
			GorillaTelemetry.EnqueueTelemetryEvent(telemetryData.EventName, telemetryData.BodyData, telemetryData.CustomTags);
			LocalizationSettings.SelectedLocale = newLocale;
			GameEvents.LanguageEvent?.Invoke();
			_onLanguageChanged?.Invoke();
			if (saveLanguage)
			{
				OnSaveLanguage();
			}
		}
	}

	public static bool TryGetLocaleFromCode(string code, out Locale result)
	{
		result = LocalizationSettings.AvailableLocales.GetLocale(code);
		return result != null;
	}

	public static void RegisterOnLanguageChanged(Action callback)
	{
		_onLanguageChanged = (Action)Delegate.Combine(_onLanguageChanged, callback);
	}

	public static void UnregisterOnLanguageChanged(Action callback)
	{
		_onLanguageChanged = (Action)Delegate.Remove(_onLanguageChanged, callback);
	}

	public static bool GetFontAssetForCurrentLocale(out LocalisationFontPair result)
	{
		result = default(LocalisationFontPair);
		if (Instance == null)
		{
			_ = ApplicationRunning;
			return false;
		}
		if (!_localisationFontDict.ContainsKey(CurrentLanguage.Identifier.Code))
		{
			_ = Time.time;
			_ = 10f;
			return false;
		}
		result = _localisationFontDict[CurrentLanguage.Identifier.Code];
		return true;
	}

	public static void OnSaveLanguage()
	{
		PlayerPrefs.SetString(LanugageSetPlayerPrefKey, CurrentLanguage.Identifier.Code);
		PlayerPrefs.SetInt("has-set-language", 1);
		PlayerPrefs.Save();
	}

	public static bool TryGetLocaleBinding(int binding, out Locale loc)
	{
		loc = null;
		if (Instance == null)
		{
			return false;
		}
		if (_localeDisplayBinding.Count != LocalizationSettings.AvailableLocales.Locales.Count)
		{
			Instance.ReconstructBindings();
		}
		return _localeDisplayBinding.TryGetValue(binding, out loc);
	}

	public static Dictionary<int, Locale> GetAllBindings()
	{
		if (_localeDisplayBinding.Count != LocalizationSettings.AvailableLocales.Locales.Count)
		{
			Instance.ReconstructBindings();
		}
		return _localeDisplayBinding;
	}

	public static bool TryGetKeyForCurrentLocale(string key, out string result, string defaultResult = "")
	{
		result = defaultResult;
		if (ApplicationQuittingState.IsQuitting)
		{
			return false;
		}
		if (_localeTablePairs.Count == 0)
		{
			return false;
		}
		if (!_localeTablePairs.TryGetValue(CurrentLanguage.Identifier.Code, out var value))
		{
			return false;
		}
		TableEntry entry = value.GetEntry(key);
		if (entry == null)
		{
			return false;
		}
		if (string.IsNullOrEmpty(entry.LocalizedValue))
		{
			result = defaultResult;
			return true;
		}
		result = entry.LocalizedValue;
		return true;
	}

	public static bool TryGetKeyForEnglishString(string englishString, out string result)
	{
		result = "";
		if (_localeTablePairs.Count == 0)
		{
			return false;
		}
		if (!_localeTablePairs.TryGetValue("en", out var value))
		{
			return false;
		}
		foreach (StringTableEntry value2 in value.Values)
		{
			if (!englishString.Contains(value2.LocalizedValue))
			{
				result = value2.LocalizedValue;
				return true;
			}
		}
		return false;
	}

	public static bool TryGetTranslationForCurrentLocaleWithLocString(LocalizedString key, out string result, string defaultResult = "", UnityEngine.Object context = null)
	{
		result = defaultResult;
		_ = (string)key.TableReference;
		UnityEngine.Localization.Tables.StringTable table = LocalizationSettings.StringDatabase.GetTable(key.TableReference);
		if (table == null)
		{
			return false;
		}
		TableEntry entryFromReference = table.GetEntryFromReference(key.TableEntryReference);
		if (entryFromReference == null)
		{
			return false;
		}
		result = entryFromReference.LocalizedValue;
		return true;
	}

	public static string LocaleToFriendlyString(Locale locale = null, bool forceEnglishChars = false)
	{
		if (locale == null)
		{
			locale = CurrentLanguage;
		}
		switch (locale.Identifier.Code)
		{
		default:
			return "English";
		case "en":
			return "English";
		case "fr":
			return "Français";
		case "de":
			return "Deutsch";
		case "es":
			return "Español";
		case "ja":
			if (forceEnglishChars)
			{
				return "Nihongo";
			}
			return "???";
		}
	}

	public static string LocaleDisplayNameToFriendlyString(string locTextName, bool forceEnglishChar = false)
	{
		switch (locTextName)
		{
		default:
			return "English";
		case "ENGLISH":
			return "English";
		case "FRANÇAIS":
		case "FRANCAIS":
			return "Français";
		case "DEUTSCH":
			return "Deutsch";
		case "ESPANOL":
		case "ESPAÑOL":
			return "Español";
		case "JAPANESE":
		case "NIHONGO":
		case "???":
			if (forceEnglishChar)
			{
				return "Nihongo";
			}
			return "???";
		}
	}
}
public class LocalisationUI : MonoBehaviour
{
	private static LocalisationUI _instance;

	[Header("Text Components")]
	[SerializeField]
	private TMP_Text _titleTxt;

	[SerializeField]
	private TMP_Text _confirmBtnTxt;

	[Header("UI Setup")]
	[SerializeField]
	private KIDUIButton _languageButtonPrefab;

	[SerializeField]
	private Transform _languageButtonGridTransform;

	[SerializeField]
	private Sprite _activeSprite;

	[SerializeField]
	private Sprite _inactiveSprite;

	[SerializeField]
	private TMP_FontAsset _defaultFont;

	[SerializeField]
	private TMP_FontAsset _japaneseFont;

	private Transform _uiTransform;

	private KIDUIButton _activeButton;

	private List<KIDUIButton> _languageButtons = new List<KIDUIButton>();

	private bool _hasConstructedUI;

	public static LocalisationUI Instance => _instance;

	private void Awake()
	{
		if (_instance != null)
		{
			UnityEngine.Object.DestroyImmediate(this);
		}
		else
		{
			_instance = this;
		}
	}

	private void Start()
	{
		ConstructLocalisationUI();
		CheckSelectedLanguage();
	}

	private void OnEnable()
	{
		LocalisationManager.RegisterOnLanguageChanged(OnLanguageChanged);
		if (_hasConstructedUI)
		{
			CheckSelectedLanguage();
		}
	}

	private void OnDisable()
	{
		LocalisationManager.UnregisterOnLanguageChanged(OnLanguageChanged);
	}

	public void OnLanguageButtonPressed(KIDUIButton objRef, int languageIndex)
	{
		if (objRef != _activeButton)
		{
			_activeButton?.SetBorderImage(_inactiveSprite);
			objRef.SetBorderImage(_activeSprite);
			_activeButton = objRef;
		}
		if (LocalisationManager.TryGetLocaleBinding(languageIndex, out var loc))
		{
			LocalisationManager.Instance.OnLanguageButtonPressed(loc.Identifier.Code, saveLanguage: false);
		}
	}

	public void OnContinueButtonPressed()
	{
		HandRayController.Instance.DisableHandRays();
		PrivateUIRoom.RemoveUI(GetUITransform());
		LocalisationManager.OnSaveLanguage();
	}

	private void ConstructLocalisationUI()
	{
		foreach (KeyValuePair<int, Locale> item in LocalisationManager.GetAllBindings())
		{
			KIDUIButton newButton = UnityEngine.Object.Instantiate(_languageButtonPrefab, _languageButtonGridTransform);
			bool forceEnglishChars = LocalisationManager.CurrentLanguage.Identifier.Code.ToLower() != "ja";
			newButton.SetText(LocalisationManager.LocaleToFriendlyString(item.Value, forceEnglishChars).ToUpper());
			newButton.onClick.AddListener(delegate
			{
				OnLanguageButtonPressed(newButton, item.Key);
			});
			_languageButtons.Add(newButton);
		}
		_hasConstructedUI = true;
	}

	private void CheckSelectedLanguage()
	{
		KIDUIButton kIDUIButton = null;
		for (int i = 0; i < _languageButtons.Count; i++)
		{
			bool forceEnglishChars = LocalisationManager.CurrentLanguage.Identifier.Code.ToLower() != "ja";
			if (!(_languageButtons[i].GetText() != LocalisationManager.LocaleToFriendlyString(LocalisationManager.CurrentLanguage, forceEnglishChars).ToUpper()))
			{
				kIDUIButton = _languageButtons[i];
				break;
			}
		}
		if (!(kIDUIButton == null))
		{
			if (_activeButton != null)
			{
				_activeButton.SetBorderImage(_inactiveSprite);
			}
			kIDUIButton.SetBorderImage(_activeSprite);
			_activeButton = kIDUIButton;
		}
	}

	private void OnLanguageChanged()
	{
		for (int i = 0; i < _languageButtons.Count; i++)
		{
			bool forceEnglishChar = LocalisationManager.CurrentLanguage.Identifier.Code.ToLower() != "ja";
			_languageButtons[i].SetText(LocalisationManager.LocaleDisplayNameToFriendlyString(_languageButtons[i].GetText(), forceEnglishChar).ToUpper());
			if (!(LocalisationManager.CurrentLanguage.Identifier.Code == "ja"))
			{
				_languageButtons[i].SetFont(_defaultFont);
			}
			else
			{
				_languageButtons[i].SetFont(_japaneseFont);
			}
		}
	}

	public static Transform GetUITransform()
	{
		if (Instance == null)
		{
			return null;
		}
		if (Instance._uiTransform == null)
		{
			Instance._uiTransform = Instance.transform.GetChild(0);
		}
		return Instance._uiTransform;
	}
}
public static class LocalizationEditorManager
{
}
public static class LocalizationTelemetry
{
	public const string LANGUAGE_CHANGED_EVENT_NAME = "language_changed";

	private const string GAME_VERSION_CUSTOM_TAG_PREFIX = "game_version_";

	public const string STARTING_LANGUAGE_BODY_DATA = "starting_language";

	public const string NEW_LANGUAGE_BODY_DATA = "new_language";

	public static string GameVersionCustomTag => "game_version_" + UnityEngine.Application.version;
}
public struct LocalizationTelemetryData
{
	public string EventName;

	public string[] CustomTags;

	public Dictionary<string, string> BodyData;
}
public class LocalizationTextSyncer : MonoBehaviour
{
	[Serializable]
	public struct TextCompSyncData
	{
		public TMP_Text textComponent;

		public bool overrideLanguageSettings;

		public List<LocalisationFontPair> _fontOverrides;

		public bool GetOverrideForLanguage(out LocalisationFontPair fontData)
		{
			fontData = default(LocalisationFontPair);
			for (int i = 0; i < _fontOverrides.Count; i++)
			{
				if (_fontOverrides[i].ContainsLocale(LocalisationManager.CurrentLanguage))
				{
					fontData = _fontOverrides[i];
					return true;
				}
			}
			return false;
		}
	}

	[SerializeField]
	[Tooltip("List of all the Text Components - and optional overrides - that will be updated when langauge changes")]
	private List<TextCompSyncData> _textComponentsToSync = new List<TextCompSyncData>();

	[SerializeField]
	[Tooltip("List of optional overrides that will be applied to ALL Text Components on this object")]
	private List<LocalisationFontPair> _universalFontOverrides = new List<LocalisationFontPair>();

	private void Start()
	{
		OnLanguageChanged();
	}

	private void OnEnable()
	{
		LocalisationManager.RegisterOnLanguageChanged(OnLanguageChanged);
		if (!(LocalisationManager.Instance == null))
		{
			OnLanguageChanged();
		}
	}

	private void OnDisable()
	{
		LocalisationManager.UnregisterOnLanguageChanged(OnLanguageChanged);
	}

	private void OnDestroy()
	{
		LocalisationManager.UnregisterOnLanguageChanged(OnLanguageChanged);
	}

	private void OnLanguageChanged()
	{
		LocalisationManager.GetFontAssetForCurrentLocale(out var result);
		LocalisationFontPair fontDataOverride;
		bool flag = TryGetFontDataOverride(out fontDataOverride);
		if (!flag && !LocalisationManager.GetFontAssetForCurrentLocale(out fontDataOverride))
		{
			return;
		}
		foreach (TextCompSyncData item in _textComponentsToSync)
		{
			if (item.textComponent == null)
			{
				continue;
			}
			if (item.overrideLanguageSettings && item.GetOverrideForLanguage(out var fontData))
			{
				fontDataOverride = fontData;
			}
			if (fontDataOverride.fontAsset != null)
			{
				item.textComponent.font = fontDataOverride.fontAsset;
			}
			else
			{
				item.textComponent.font = result.fontAsset;
			}
			if (flag)
			{
				item.textComponent.characterSpacing = fontDataOverride.charSpacing;
				item.textComponent.lineSpacing = fontDataOverride.lineSpacing;
				if (fontDataOverride.fontSize != 0f)
				{
					TMP_Text textComponent = item.textComponent;
					float fontSize = (item.textComponent.fontSizeMax = fontDataOverride.fontSize);
					textComponent.fontSize = fontSize;
				}
			}
		}
	}

	private bool TryGetFontDataOverride(out LocalisationFontPair fontDataOverride)
	{
		fontDataOverride = default(LocalisationFontPair);
		for (int i = 0; i < _universalFontOverrides.Count; i++)
		{
			if (_universalFontOverrides[i].ContainsLocale(LocalisationManager.CurrentLanguage))
			{
				fontDataOverride = _universalFontOverrides[i];
				return true;
			}
		}
		return false;
	}
}
