	[SerializeField]
	private int gridDimension = 3;

	[SerializeField]
	private TriggerEventNotifier triggerNotifier;

	[FormerlySerializedAs("_joinButtons")]
	[Header("Buttons")]
	[SerializeField]
	private GorillaPressableDelayButton[] _friendCardButtons;

	[SerializeField]
	private TextMeshProUGUI[] _friendCardButtonText;

	[SerializeField]
	private MeshRenderer _localPlayerFullyVisibleButton;

	[SerializeField]
	private MeshRenderer _localPlayerPublicOnlyButton;

	[SerializeField]
	private MeshRenderer _localPlayerFullyHiddenButton;

	[SerializeField]
	private MeshRenderer _removeFriendButton;

	[SerializeField]
	private FriendCard _localPlayerCard;

	[SerializeField]
	private MeshRenderer[] PageButtons;

	[SerializeField]
	private Material[] _buttonDefaultMaterials;

	[SerializeField]
	private Material[] _buttonActiveMaterials;

	[SerializeField]
	private Material[] _buttonAlertMaterials;

	[SerializeField]
	private Material[] _pageButtonDefaultMaterials;

	[SerializeField]
	private Material[] _pageButtonActiveMaterials;

	[SerializeField]
	private Material[] _pageButtonAlerttMaterials;

	public const int PageCapacity = 9;

	public const int VIMPageCapacity = 9;

	[SerializeField]
	private int freeExtraPageCount = 1;

	[SerializeField]
	private int vimPageCount;

	private int cardsPerPage = 9;

	[SerializeField]
	private float pageButtonInactiveZPos;

	[SerializeField]
	private float pageButtonActiveZPos;

	private MeshRenderer[] _joinButtonRenderers;

	private bool inRemoveMode;

	private bool localPlayerAtDisplay;

	private int _currentPage;

	public static int ConfiguredVimPageCount { get; private set; } = 0;

	public static int ConfiguredFreeExtraPageCount { get; private set; } = 1;

	private int totalPages => 1 + freeExtraPageCount + vimPageCount;

	public int TotalCapacity => 9 + (freeExtraPageCount + vimPageCount) * 9;

	public int VIMTotalCapacity => vimPageCount * 9;

	public int FreeExtraTotalCapacity => freeExtraPageCount * 9;

	public int VimPageCount => vimPageCount;

	public bool InRemoveMode => inRemoveMode;

	private void Awake()
	{
		ConfiguredVimPageCount = vimPageCount;
		ConfiguredFreeExtraPageCount = freeExtraPageCount;
	}

	private void Start()
	{
		InitFriendCards();
		InitLocalPlayerCard();
		UpdateLocalPlayerPrivacyButtons();
		triggerNotifier.TriggerEnterEvent += TriggerEntered;
		triggerNotifier.TriggerExitEvent += TriggerExited;
		NetworkSystem.Instance.OnJoinedRoomEvent += new Action(OnJoinedRoom);
		SubscriptionManager.OnLocalSubscriptionData = (Action)Delegate.Combine(SubscriptionManager.OnLocalSubscriptionData, new Action(OnLocalSubscriptionChanged));
	}

	private void OnDestroy()
	{
		if (NetworkSystem.Instance != null)
		{
			NetworkSystem.Instance.OnJoinedRoomEvent -= new Action(OnJoinedRoom);
		}
		if (triggerNotifier != null)
		{
			triggerNotifier.TriggerEnterEvent -= TriggerEntered;
			triggerNotifier.TriggerExitEvent -= TriggerExited;
		}
		SubscriptionManager.OnLocalSubscriptionData = (Action)Delegate.Remove(SubscriptionManager.OnLocalSubscriptionData, new Action(OnLocalSubscriptionChanged));
	}

	private void OnLocalSubscriptionChanged()
	{
		if (localPlayerAtDisplay)
		{
			GoToFriendPage(_currentPage);
		}
	}

	public void TriggerEntered(TriggerEventNotifier notifier, Collider other)
	{
		if (other == GTPlayer.Instance.headCollider)
		{
			FriendSystem.Instance.OnFriendListRefresh += OnGetFriendsReceived;
			FriendSystem.Instance.RefreshFriendsList();
			PopulateLocalPlayerCard();
			localPlayerAtDisplay = true;
			if (InRemoveMode)
			{
				ToggleRemoveFriendMode();
			}
		}
	}

	public void TriggerExited(TriggerEventNotifier notifier, Collider other)
	{
		if (other == GTPlayer.Instance.headCollider)
		{
			FriendSystem.Instance.OnFriendListRefresh -= OnGetFriendsReceived;
			ClearFriendCards();
			ClearLocalPlayerCard();
			ClearPageButtons();
			localPlayerAtDisplay = false;
			if (InRemoveMode)
			{
				ToggleRemoveFriendMode();
			}
		}
	}

	private void OnJoinedRoom()
	{
		Refresh();
	}

	private void Refresh()
	{
		if (localPlayerAtDisplay)
		{
			FriendSystem.Instance.RefreshFriendsList();
			PopulateLocalPlayerCard();
		}
	}

	public void LocalPlayerFullyVisiblePress()
	{
		FriendSystem.Instance.SetLocalPlayerPrivacy(FriendSystem.PlayerPrivacy.Visible);
		UpdateLocalPlayerPrivacyButtons();
		PopulateLocalPlayerCard();
	}

	public void LocalPlayerPublicOnlyPress()
	{
		FriendSystem.Instance.SetLocalPlayerPrivacy(FriendSystem.PlayerPrivacy.PublicOnly);
		UpdateLocalPlayerPrivacyButtons();
		PopulateLocalPlayerCard();
	}

	public void LocalPlayerFullyHiddenPress()
	{
		FriendSystem.Instance.SetLocalPlayerPrivacy(FriendSystem.PlayerPrivacy.Hidden);
		UpdateLocalPlayerPrivacyButtons();
		PopulateLocalPlayerCard();
	}

	private void UpdateLocalPlayerPrivacyButtons()
	{
		FriendSystem.PlayerPrivacy localPlayerPrivacy = FriendSystem.Instance.LocalPlayerPrivacy;
		SetButtonAppearance(_localPlayerFullyVisibleButton, localPlayerPrivacy == FriendSystem.PlayerPrivacy.Visible);
		SetButtonAppearance(_localPlayerPublicOnlyButton, localPlayerPrivacy == FriendSystem.PlayerPrivacy.PublicOnly);
		SetButtonAppearance(_localPlayerFullyHiddenButton, localPlayerPrivacy == FriendSystem.PlayerPrivacy.Hidden);
	}

	private void UpdatePageButtons(int selectedPage)
	{
		int count = FriendBackendController.Instance.FriendsList.Count;
		bool flag = SubscriptionManager.IsLocalSubscribed();
		int num = 1 + freeExtraPageCount;
		int num2 = 9 + freeExtraPageCount * 9;
		bool flag2 = freeExtraPageCount > 0;
		int num3 = Mathf.Min(totalPages, PageButtons.Length);
		if (!flag2)
		{
			for (int i = num; i < num3; i++)
			{
				int num4 = i - num;
				bool flag3 = count > num2 + num4 * 9;
				if (flag || flag3)
				{
					flag2 = true;
					break;
				}
			}
		}
		for (int j = 0; j < PageButtons.Length; j++)
		{
			bool flag4;
			if (j >= num3)
			{
				flag4 = false;
			}
			else if (j == 0)
			{
				flag4 = flag2;
			}
			else if (j < num)
			{
				flag4 = true;
			}
			else
			{
				int num5 = j - num;
				bool flag5 = count > num2 + num5 * 9;
				flag4 = flag || flag5;
			}
			if (flag4)
			{
				SetPageButtonAppearance(PageButtons[j], (j == selectedPage) ? ButtonState.Active : ButtonState.Default);
			}
			else
			{
				HidePageButton(PageButtons[j]);
			}
		}
	}

	private void SetButtonAppearance(MeshRenderer buttonRenderer, bool active)
	{
		SetButtonAppearance(buttonRenderer, active ? ButtonState.Active : ButtonState.Default);
	}

	private void SetButtonAppearance(MeshRenderer buttonRenderer, ButtonState state)
	{
		buttonRenderer.sharedMaterials = state switch
		{
			ButtonState.Default => _buttonDefaultMaterials, 
			ButtonState.Active => _buttonActiveMaterials, 
			ButtonState.Alert => _buttonAlertMaterials, 
			_ => throw new ArgumentOutOfRangeException("state", state, null), 
		};
	}

	private void ClearPageButtons()
	{
		for (int i = 0; i < PageButtons.Length; i++)
		{
			HidePageButton(PageButtons[i]);
		}
	}

	private void HidePageButton(MeshRenderer buttonRenderer)
	{
		buttonRenderer.enabled = false;
		buttonRenderer.GetComponent<BoxCollider>().enabled = false;
		buttonRenderer.transform.localPosition = new UnityEngine.Vector3(buttonRenderer.transform.localPosition.x, buttonRenderer.transform.localPosition.y, pageButtonInactiveZPos);
	}

	private void SetPageButtonAppearance(MeshRenderer buttonRenderer, ButtonState state)
	{
		buttonRenderer.enabled = true;
		buttonRenderer.GetComponent<BoxCollider>().enabled = true;
		buttonRenderer.sharedMaterials = state switch
		{
			ButtonState.Default => _pageButtonDefaultMaterials, 
			ButtonState.Active => _pageButtonActiveMaterials, 
			ButtonState.Alert => _pageButtonAlerttMaterials, 
			_ => throw new ArgumentOutOfRangeException("state", state, null), 
		};
		UnityEngine.Vector3 localPosition = buttonRenderer.transform.localPosition;
		buttonRenderer.transform.localPosition = new UnityEngine.Vector3(localPosition.x, localPosition.y, pageButtonActiveZPos);
	}

	public void ToggleRemoveFriendMode()
	{
		inRemoveMode = !inRemoveMode;
		FriendCard[] array = friendCards;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].SetRemoveEnabled(inRemoveMode);
		}
		SetButtonAppearance(_removeFriendButton, inRemoveMode ? ButtonState.Alert : ButtonState.Default);
	}

	private void InitFriendCards()
	{
		float num = gridWidth / (float)gridDimension;
		float num2 = gridHeight / (float)gridDimension;
		UnityEngine.Vector3 right = gridRoot.right;
		UnityEngine.Vector3 vector = -gridRoot.up;
		UnityEngine.Vector3 vector2 = gridRoot.position - right * (gridWidth * 0.5f - num * 0.5f) - vector * (gridHeight * 0.5f - num2 * 0.5f);
		int num3 = 0;
		int num4 = 0;
		for (int i = 0; i < gridDimension; i++)
		{
			for (int j = 0; j < gridDimension; j++)
			{
				FriendCard friendCard = friendCards[num4];
				friendCard.gameObject.SetActive(value: true);
				friendCard.transform.localScale = UnityEngine.Vector3.one * (num / friendCard.Width);
				friendCard.transform.position = vector2 + right * num * j + vector * num2 * i;
				friendCard.transform.rotation = gridRoot.transform.rotation;
				friendCard.Init(this);
				friendCard.SetButton(_friendCardButtons[num3++], _buttonDefaultMaterials, _buttonActiveMaterials, _buttonAlertMaterials, _friendCardButtonText[num4]);
				friendCard.SetEmpty();
				num4++;
			}
		}
	}

	public void RandomizeFriendCards()
	{
		for (int i = 0; i < friendCards.Length; i++)
		{
			friendCards[i].Randomize();
		}
	}

	private void ClearFriendCards()
	{
		for (int i = 0; i < friendCards.Length; i++)
		{
			friendCards[i].SetEmpty();
		}
	}

	public void OnGetFriendsReceived(List<FriendBackendController.Friend> friendsList)
	{
		UpdateLocalPlayerPrivacyButtons();
		PopulateLocalPlayerCard();
		GoToFriendPage(_currentPage);
	}

	public void GoToFriendPage(int currentPage)
	{
		int num = Mathf.Min(totalPages, PageButtons.Length);
		if (currentPage < 0 || currentPage >= num)
		{
			currentPage = 0;
		}
		_currentPage = currentPage;
		UpdatePageButtons(currentPage);
		for (int i = 0; i < friendCards.Length; i++)
		{
			friendCards[i].SetEmpty();
		}
		List<FriendBackendController.Friend> friendsList = FriendBackendController.Instance.FriendsList;
		int num2 = currentPage * cardsPerPage;
		int num3 = 9 + freeExtraPageCount * 9;
		for (int j = 0; j < friendCards.Length; j++)
		{
			int num4 = num2 + j;
			bool flag = num4 >= num3;
			if (num4 < friendsList.Count)
			{
				friendCards[j].Populate(friendsList[num4], flag);
			}
			else
			{
				friendCards[j].SetEmpty(flag);
			}
		}
	}

	private void InitLocalPlayerCard()
	{
		_localPlayerCard.Init(this);
		ClearLocalPlayerCard();
	}

	private void PopulateLocalPlayerCard()
	{
		string zone = PhotonNetworkController.Instance.CurrentRoomZone.GetName().ToUpper();
		_localPlayerCard.SetName(NetworkSystem.Instance.LocalPlayer.NickName.ToUpper());
		if (PhotonNetwork.InRoom && !string.IsNullOrEmpty(NetworkSystem.Instance.RoomName) && NetworkSystem.Instance.RoomName.Length > 0)
		{
			bool flag = NetworkSystem.Instance.RoomName[0] == '@';
			bool flag2 = !NetworkSystem.Instance.SessionIsPrivate;
			if (FriendSystem.Instance.LocalPlayerPrivacy == FriendSystem.PlayerPrivacy.Hidden || (FriendSystem.Instance.LocalPlayerPrivacy == FriendSystem.PlayerPrivacy.PublicOnly && !flag2))
			{
				_localPlayerCard.SetRoom("OFFLINE");
				_localPlayerCard.SetZone("");
			}
			else if (flag)
			{
				_localPlayerCard.SetRoom(NetworkSystem.Instance.RoomName.Substring(1).ToUpper());
				_localPlayerCard.SetZone("CUSTOM");
			}
			else if (!flag2)
			{
				_localPlayerCard.SetRoom(NetworkSystem.Instance.RoomName.ToUpper());
				_localPlayerCard.SetZone("PRIVATE");
			}
			else
			{
				_localPlayerCard.SetRoom(NetworkSystem.Instance.RoomName.ToUpper());
				_localPlayerCard.SetZone(zone);
			}
		}
		else
		{
			_localPlayerCard.SetRoom("OFFLINE");
			_localPlayerCard.SetZone("");
		}
	}

	private void ClearLocalPlayerCard()
	{
		_localPlayerCard.SetEmpty();
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.white;
		float num = gridWidth * 0.5f;
		float num2 = gridHeight * 0.5f;
		float num3 = num;
		float num4 = num2;
		UnityEngine.Vector3 a = gridRoot.position + gridRoot.rotation * new UnityEngine.Vector3(0f - num3, num4, 0f);
		UnityEngine.Vector3 vector = gridRoot.position + gridRoot.rotation * new UnityEngine.Vector3(num3, num4, 0f);
		UnityEngine.Vector3 vector2 = gridRoot.position + gridRoot.rotation * new UnityEngine.Vector3(0f - num3, 0f - num4, 0f);
		UnityEngine.Vector3 b = gridRoot.position + gridRoot.rotation * new UnityEngine.Vector3(num3, 0f - num4, 0f);
		for (int i = 0; i <= gridDimension; i++)
		{
			float t = (float)i / (float)gridDimension;
			UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Lerp(a, vector, t);
			UnityEngine.Vector3 to = UnityEngine.Vector3.Lerp(vector2, b, t);
			Gizmos.DrawLine(vector3, to);
			UnityEngine.Vector3 vector4 = UnityEngine.Vector3.Lerp(a, vector2, t);
			UnityEngine.Vector3 to2 = UnityEngine.Vector3.Lerp(vector, b, t);
			Gizmos.DrawLine(vector4, to2);
		}
	}
}
public class FriendingManager : MonoBehaviourPun, IPunObservable, IGorillaSliceableSimple
{
	public enum FriendStationState
	{
		NotInRoom,
		WaitingForPlayers,
		WaitingOnFriendStatusBoth,
		WaitingOnFriendStatusPlayerA,
		WaitingOnFriendStatusPlayerB,
		WaitingOnButtonBoth,
		WaitingOnButtonPlayerA,
		WaitingOnButtonPlayerB,
		ButtonConfirmationTimer0,
		ButtonConfirmationTimer1,
		ButtonConfirmationTimer2,
		ButtonConfirmationTimer3,
		ButtonConfirmationTimer4,
		WaitingOnRequestBoth,
		WaitingOnRequestPlayerA,
		WaitingOnRequestPlayerB,
		RequestFailed,
		Friends,
		AlreadyFriends
	}

	public struct FriendStationData
	{
		public GTZone zone;

		public int actorNumberA;

		public int actorNumberB;

		public FriendStationState state;

		public float progressBarStartTime;
	}

	[OnEnterPlay_SetNull]
	public static volatile FriendingManager Instance;

	[SerializeField]
	private float progressBarDuration = 3f;

	[SerializeField]
	private float requiredProximityToStation = 3f;

	private List<FriendStationData> activeFriendStationData = new List<FriendStationData>(10);

	private Dictionary<GTZone, FriendingStation> friendingStations = new Dictionary<GTZone, FriendingStation>();

	private GTZone localPlayerZone = GTZone.none;

	private void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
			PhotonNetwork.AddCallbackTarget(this);
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void Start()
	{
		NetworkSystem.Instance.OnPlayerLeft += new Action<NetPlayer>(OnPlayerLeftRoom);
		NetworkSystem.Instance.OnMultiplayerStarted += new Action(ValidateState);
		NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(ValidateState);
	}

	private void OnDestroy()
	{
		if (NetworkSystem.Instance != null)
		{
			NetworkSystem.Instance.OnPlayerLeft -= new Action<NetPlayer>(OnPlayerLeftRoom);
			NetworkSystem.Instance.OnMultiplayerStarted -= new Action(ValidateState);
			NetworkSystem.Instance.OnReturnedToSinglePlayer -= new Action(ValidateState);
		}
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void SliceUpdate()
	{
		AuthorityUpdate();
	}

	private void AuthorityUpdate()
	{
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].state >= FriendStationState.ButtonConfirmationTimer0 && activeFriendStationData[i].state <= FriendStationState.ButtonConfirmationTimer4)
			{
				FriendStationData value = activeFriendStationData[i];
				int num = 4;
				float num2 = (Time.time - value.progressBarStartTime) / progressBarDuration;
				if (num2 < 1f)
				{
					int num3 = Mathf.RoundToInt(num2 * (float)num);
					value.state = (FriendStationState)(num3 + 8);
				}
				else
				{
					base.photonView.RPC("NotifyClientsFriendRequestReadyRPC", RpcTarget.All, value.zone);
					value.state = FriendStationState.WaitingOnRequestBoth;
				}
				activeFriendStationData[i] = value;
			}
		}
	}

	private void OnPlayerLeftRoom(NetPlayer player)
	{
		ValidateState();
	}

	private void ValidateState()
	{
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			FriendStationData value = activeFriendStationData[i];
			if (value.actorNumberA != -1 && NetworkSystem.Instance.GetNetPlayerByID(value.actorNumberA) == null)
			{
				value.actorNumberA = -1;
			}
			if (value.actorNumberB != -1 && NetworkSystem.Instance.GetNetPlayerByID(value.actorNumberB) == null)
			{
				value.actorNumberB = -1;
			}
			if (value.actorNumberA == -1 || value.actorNumberB == -1)
			{
				value.state = FriendStationState.WaitingForPlayers;
			}
			activeFriendStationData[i] = value;
		}
		UpdateFriendingStations();
	}

	private void UpdateFriendingStations()
	{
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (friendingStations.TryGetValue(activeFriendStationData[i].zone, out var value))
			{
				value.UpdateState(activeFriendStationData[i]);
			}
		}
	}

	public void RegisterFriendingStation(FriendingStation friendingStation)
	{
		if (!friendingStations.ContainsKey(friendingStation.Zone))
		{
			friendingStations.Add(friendingStation.Zone, friendingStation);
		}
	}

	public void UnregisterFriendingStation(FriendingStation friendingStation)
	{
		friendingStations.Remove(friendingStation.Zone);
	}

	private void DebugLogFriendingStations()
	{
		string text = $"Friending Stations: Count: {friendingStations.Count} ";
		foreach (KeyValuePair<GTZone, FriendingStation> friendingStation in friendingStations)
		{
			text += $"Station Zone {friendingStation.Key}";
		}
		UnityEngine.Debug.Log(text);
	}

	public void PlayerEnteredStation(GTZone zone, NetPlayer netPlayer)
	{
		if (netPlayer != null && netPlayer.ActorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber)
		{
			localPlayerZone = zone;
		}
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		int num = -1;
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone != zone)
			{
				continue;
			}
			num = i;
			if (activeFriendStationData[i].actorNumberA == -1 && activeFriendStationData[i].actorNumberB != netPlayer.ActorNumber)
			{
				FriendStationData value = activeFriendStationData[i];
				value.actorNumberA = netPlayer.ActorNumber;
				if (value.actorNumberA != -1 && value.actorNumberB != -1)
				{
					value.state = FriendStationState.WaitingOnFriendStatusBoth;
				}
				else
				{
					value.state = FriendStationState.WaitingForPlayers;
				}
				activeFriendStationData[i] = value;
			}
			else if (activeFriendStationData[i].actorNumberA != -1 && activeFriendStationData[i].actorNumberA != netPlayer.ActorNumber && activeFriendStationData[i].actorNumberB == -1)
			{
				FriendStationData value2 = activeFriendStationData[i];
				value2.actorNumberB = netPlayer.ActorNumber;
				if (value2.actorNumberA != -1 && value2.actorNumberB != -1)
				{
					value2.state = FriendStationState.WaitingOnFriendStatusBoth;
				}
				else
				{
					value2.state = FriendStationState.WaitingForPlayers;
				}
				activeFriendStationData[i] = value2;
			}
			if (activeFriendStationData[i].state == FriendStationState.WaitingOnFriendStatusBoth)
			{
				base.photonView.RPC("CheckFriendStatusRequestRPC", RpcTarget.All, activeFriendStationData[i].zone, activeFriendStationData[i].actorNumberA, activeFriendStationData[i].actorNumberB);
			}
			break;
		}
		if (num < 0)
		{
			activeFriendStationData.Add(new FriendStationData
			{
				zone = zone,
				actorNumberA = netPlayer.ActorNumber,
				actorNumberB = -1,
				state = FriendStationState.WaitingForPlayers
			});
		}
		UpdateFriendingStations();
	}

	public void PlayerExitedStation(GTZone zone, NetPlayer netPlayer)
	{
		if (netPlayer != null && netPlayer.ActorNumber == NetworkSystem.Instance.LocalPlayer.ActorNumber)
		{
			localPlayerZone = GTZone.none;
		}
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		int num = -1;
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone == zone)
			{
				if ((activeFriendStationData[i].actorNumberA == netPlayer.ActorNumber && activeFriendStationData[i].actorNumberB == -1) || (activeFriendStationData[i].actorNumberA == -1 && activeFriendStationData[i].actorNumberB == netPlayer.ActorNumber))
				{
					FriendStationData value = activeFriendStationData[i];
					value.actorNumberA = -1;
					value.actorNumberB = -1;
					value.state = FriendStationState.WaitingForPlayers;
					activeFriendStationData[i] = value;
					num = i;
				}
				else if (activeFriendStationData[i].actorNumberA != -1 && activeFriendStationData[i].actorNumberA != netPlayer.ActorNumber && activeFriendStationData[i].actorNumberB == netPlayer.ActorNumber)
				{
					FriendStationData value2 = activeFriendStationData[i];
					value2.actorNumberB = -1;
					value2.state = FriendStationState.WaitingForPlayers;
					activeFriendStationData[i] = value2;
				}
				else if (activeFriendStationData[i].actorNumberB != -1 && activeFriendStationData[i].actorNumberB != netPlayer.ActorNumber && activeFriendStationData[i].actorNumberA == netPlayer.ActorNumber)
				{
					FriendStationData value3 = activeFriendStationData[i];
					value3.actorNumberA = -1;
					value3.state = FriendStationState.WaitingForPlayers;
					activeFriendStationData[i] = value3;
				}
				break;
			}
		}
		UpdateFriendingStations();
		if (num >= 0)
		{
			base.photonView.RPC("StationNoLongerActiveRPC", RpcTarget.Others, activeFriendStationData[num].zone);
			activeFriendStationData.RemoveAt(num);
		}
	}

	private void PlayerPressedButton(GTZone zone, int playerId)
	{
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone != zone)
			{
				continue;
			}
			if (activeFriendStationData[i].actorNumberA != -1 && activeFriendStationData[i].actorNumberB != -1)
			{
				if ((activeFriendStationData[i].state == FriendStationState.WaitingOnButtonPlayerA && activeFriendStationData[i].actorNumberA == playerId) || (activeFriendStationData[i].state == FriendStationState.WaitingOnButtonPlayerB && activeFriendStationData[i].actorNumberB == playerId))
				{
					FriendStationData value = activeFriendStationData[i];
					value.state = FriendStationState.ButtonConfirmationTimer0;
					value.progressBarStartTime = Time.time;
					activeFriendStationData[i] = value;
				}
				else if (activeFriendStationData[i].state == FriendStationState.WaitingOnButtonBoth && activeFriendStationData[i].actorNumberA == playerId)
				{
					FriendStationData value2 = activeFriendStationData[i];
					value2.state = FriendStationState.WaitingOnButtonPlayerB;
					activeFriendStationData[i] = value2;
				}
				else if (activeFriendStationData[i].state == FriendStationState.WaitingOnButtonBoth && activeFriendStationData[i].actorNumberB == playerId)
				{
					FriendStationData value3 = activeFriendStationData[i];
					value3.state = FriendStationState.WaitingOnButtonPlayerA;
					activeFriendStationData[i] = value3;
				}
			}
			break;
		}
	}

	private void PlayerUnpressedButton(GTZone zone, int playerId)
	{
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone != zone)
			{
				continue;
			}
			if (activeFriendStationData[i].actorNumberA != -1 && activeFriendStationData[i].actorNumberB != -1)
			{
				bool flag = activeFriendStationData[i].state >= FriendStationState.ButtonConfirmationTimer0 && activeFriendStationData[i].state <= FriendStationState.ButtonConfirmationTimer4;
				if (flag && activeFriendStationData[i].actorNumberA == playerId)
				{
					FriendStationData value = activeFriendStationData[i];
					value.state = FriendStationState.WaitingOnButtonPlayerA;
					activeFriendStationData[i] = value;
				}
				else if (flag && activeFriendStationData[i].actorNumberB == playerId)
				{
					FriendStationData value2 = activeFriendStationData[i];
					value2.state = FriendStationState.WaitingOnButtonPlayerB;
					activeFriendStationData[i] = value2;
				}
				else if ((activeFriendStationData[i].state == FriendStationState.WaitingOnButtonPlayerA && activeFriendStationData[i].actorNumberB == playerId) || (activeFriendStationData[i].state == FriendStationState.WaitingOnButtonPlayerB && activeFriendStationData[i].actorNumberA == playerId))
				{
					FriendStationData value3 = activeFriendStationData[i];
					value3.state = FriendStationState.WaitingOnButtonBoth;
					activeFriendStationData[i] = value3;
				}
			}
			break;
		}
	}

	private void CheckFriendStatusRequest(GTZone zone, int actorNumberA, int actorNumberB)
	{
		FriendSystem.Instance.OnFriendListRefresh -= CheckFriendStatusOnFriendListRefresh;
		FriendSystem.Instance.OnFriendListRefresh += CheckFriendStatusOnFriendListRefresh;
		FriendSystem.Instance.RefreshFriendsList();
	}

	private void CheckFriendStatusOnFriendListRefresh(List<FriendBackendController.Friend> friendList)
	{
		FriendSystem.Instance.OnFriendListRefresh -= CheckFriendStatusOnFriendListRefresh;
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone == localPlayerZone)
			{
				int actorNumber = NetworkSystem.Instance.LocalPlayer.ActorNumber;
				int num = -1;
				if (activeFriendStationData[i].actorNumberA == actorNumber)
				{
					num = activeFriendStationData[i].actorNumberB;
				}
				else if (activeFriendStationData[i].actorNumberB == actorNumber)
				{
					num = activeFriendStationData[i].actorNumberA;
				}
				if (num != -1 && FriendSystem.Instance.CheckFriendshipWithPlayer(num))
				{
					base.photonView.RPC("CheckFriendStatusResponseRPC", RpcTarget.MasterClient, localPlayerZone, num, true);
				}
				else
				{
					base.photonView.RPC("CheckFriendStatusResponseRPC", RpcTarget.MasterClient, localPlayerZone, num, false);
				}
				break;
			}
		}
	}

	private void CheckFriendStatusResponse(GTZone zone, int responderActorNumber, int friendTargetActorNumber, bool friends)
	{
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone != zone)
			{
				continue;
			}
			if (activeFriendStationData[i].actorNumberA == -1 || activeFriendStationData[i].actorNumberB == -1)
			{
				break;
			}
			if ((activeFriendStationData[i].state == FriendStationState.WaitingOnFriendStatusPlayerA && activeFriendStationData[i].actorNumberA == responderActorNumber) || (activeFriendStationData[i].state == FriendStationState.WaitingOnFriendStatusPlayerB && activeFriendStationData[i].actorNumberB == responderActorNumber))
			{
				FriendStationData value = activeFriendStationData[i];
				if (friends)
				{
					value.state = FriendStationState.AlreadyFriends;
				}
				else
				{
					value.state = FriendStationState.WaitingOnButtonBoth;
				}
				activeFriendStationData[i] = value;
			}
			else if (activeFriendStationData[i].state == FriendStationState.WaitingOnFriendStatusBoth && activeFriendStationData[i].actorNumberA == responderActorNumber)
			{
				FriendStationData value2 = activeFriendStationData[i];
				if (friends)
				{
					value2.state = FriendStationState.WaitingOnFriendStatusPlayerB;
				}
				else
				{
					value2.state = FriendStationState.WaitingOnButtonBoth;
				}
				activeFriendStationData[i] = value2;
			}
			else if (activeFriendStationData[i].state == FriendStationState.WaitingOnFriendStatusBoth && activeFriendStationData[i].actorNumberB == responderActorNumber)
			{
				FriendStationData value3 = activeFriendStationData[i];
				if (friends)
				{
					value3.state = FriendStationState.WaitingOnFriendStatusPlayerA;
				}
				else
				{
					value3.state = FriendStationState.WaitingOnButtonBoth;
				}
				activeFriendStationData[i] = value3;
			}
			break;
		}
	}

	private void SendFriendRequestIfApplicable(GTZone zone)
	{
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone == zone)
			{
				FriendStationData friendStationData = activeFriendStationData[i];
				int actorNumber = PhotonNetwork.LocalPlayer.ActorNumber;
				NetPlayer netPlayer = null;
				if (friendStationData.actorNumberA == actorNumber)
				{
					netPlayer = NetworkSystem.Instance.GetNetPlayerByID(friendStationData.actorNumberB);
				}
				else if (friendStationData.actorNumberB == actorNumber)
				{
					netPlayer = NetworkSystem.Instance.GetNetPlayerByID(friendStationData.actorNumberA);
				}
				if (netPlayer != null && friendingStations.TryGetValue(friendStationData.zone, out var value) && (GTPlayer.Instance.HeadCenterPosition - value.transform.position).sqrMagnitude < requiredProximityToStation * requiredProximityToStation)
				{
					FriendSystem.Instance.SendFriendRequest(netPlayer, friendStationData.zone, FriendRequestCallback);
				}
				break;
			}
		}
	}

	private void FriendRequestCompletedAuthority(GTZone zone, int playerId, bool succeeded)
	{
		if (!PhotonNetwork.InRoom || !base.photonView.IsMine)
		{
			return;
		}
		for (int i = 0; i < activeFriendStationData.Count; i++)
		{
			if (activeFriendStationData[i].zone != zone)
			{
				continue;
			}
			if (succeeded)
			{
				if ((activeFriendStationData[i].state == FriendStationState.WaitingOnRequestPlayerA && activeFriendStationData[i].actorNumberA == playerId) || (activeFriendStationData[i].state == FriendStationState.WaitingOnRequestPlayerB && activeFriendStationData[i].actorNumberB == playerId))
				{
					FriendStationData value = activeFriendStationData[i];
					value.state = FriendStationState.Friends;
					activeFriendStationData[i] = value;
				}
				else if (activeFriendStationData[i].state == FriendStationState.WaitingOnRequestBoth && activeFriendStationData[i].actorNumberA == playerId)
				{
					FriendStationData value2 = activeFriendStationData[i];
					value2.state = FriendStationState.WaitingOnRequestPlayerB;
					activeFriendStationData[i] = value2;
				}
				else if (activeFriendStationData[i].state == FriendStationState.WaitingOnRequestBoth && activeFriendStationData[i].actorNumberB == playerId)
				{
					FriendStationData value3 = activeFriendStationData[i];
					value3.state = FriendStationState.WaitingOnRequestPlayerA;
					activeFriendStationData[i] = value3;
				}
			}
			else
			{
				FriendStationData value4 = activeFriendStationData[i];
				value4.state = FriendStationState.RequestFailed;
				activeFriendStationData[i] = value4;
			}
			break;
		}
	}

	private void FriendRequestCallback(GTZone zone, int localId, int friendId, bool success)
	{
		if (base.photonView.IsMine)
		{
			FriendRequestCompletedAuthority(zone, PhotonNetwork.LocalPlayer.ActorNumber, success);
			return;
		}
		base.photonView.RPC("FriendRequestCompletedRPC", RpcTarget.MasterClient, zone, success);
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.IsWriting)
		{
			stream.SendNext(activeFriendStationData.Count);
			for (int i = 0; i < activeFriendStationData.Count; i++)
			{
				SendFriendStationData(stream, activeFriendStationData[i]);
			}
		}
		else if (stream.IsReading && info.Sender.IsMasterClient)
		{
			int num = (int)stream.ReceiveNext();
			if (num >= 0 && num <= 10)
			{
				activeFriendStationData.Clear();
				for (int j = 0; j < num; j++)
				{
					activeFriendStationData.Add(ReceiveFriendStationData(stream));
				}
			}
		}
		UpdateFriendingStations();
		static FriendStationData ReceiveFriendStationData(PhotonStream photonStream)
		{
			return new FriendStationData
			{
				zone = (GTZone)(int)photonStream.ReceiveNext(),
				actorNumberA = (int)photonStream.ReceiveNext(),
				actorNumberB = (int)photonStream.ReceiveNext(),
				state = (FriendStationState)(int)photonStream.ReceiveNext()
			};
		}
		static void SendFriendStationData(PhotonStream photonStream, FriendStationData data)
		{
			photonStream.SendNext((int)data.zone);
			photonStream.SendNext(data.actorNumberA);
			photonStream.SendNext(data.actorNumberB);
			photonStream.SendNext((int)data.state);
		}
	}

	[PunRPC]
	public void CheckFriendStatusRequestRPC(GTZone zone, int actorNumberA, int actorNumberB, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "CheckFriendStatusRequestRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			CheckFriendStatusRequest(zone, actorNumberA, actorNumberB);
		}
	}

	[PunRPC]
	public void CheckFriendStatusResponseRPC(GTZone zone, int friendTargetActorNumber, bool friends, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "CheckFriendStatusRequestRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			CheckFriendStatusResponse(zone, info.Sender.ActorNumber, friendTargetActorNumber, friends);
		}
	}

	[PunRPC]
	public void FriendButtonPressedRPC(GTZone zone, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "FriendButtonPressedRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			PlayerPressedButton(zone, info.Sender.ActorNumber);
		}
	}

	[PunRPC]
	public void FriendButtonUnpressedRPC(GTZone zone, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "FriendButtonUnpressedRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			PlayerUnpressedButton(zone, info.Sender.ActorNumber);
		}
	}

	[PunRPC]
	public void StationNoLongerActiveRPC(GTZone zone, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "StationNoLongerActiveRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime) && info.Sender.IsMasterClient && friendingStations.TryGetValue(zone, out var value))
		{
			value.UpdateState(new FriendStationData
			{
				zone = zone,
				actorNumberA = -1,
				actorNumberB = -1,
				state = FriendStationState.WaitingForPlayers
			});
		}
	}

	[PunRPC]
	public void NotifyClientsFriendRequestReadyRPC(GTZone zone, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "NotifyClientsFriendRequestReadyRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			SendFriendRequestIfApplicable(zone);
		}
	}

	[PunRPC]
	public void FriendRequestCompletedRPC(GTZone zone, bool succeeded, PhotonMessageInfo info)
	{
		MonkeAgent.IncrementRPCCall(info, "FriendRequestCompletedRPC");
		if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender), out var playerRig) && playerRig.Rig.fxSettings.callSettings[12].CallLimitSettings.CheckCallTime(Time.unscaledTime))
		{
			FriendRequestCompletedAuthority(zone, info.Sender.ActorNumber, succeeded);
		}
	}
}
public class FriendingStation : MonoBehaviour
{
	[SerializeField]
	private TriggerEventNotifier triggerNotifier;

	[SerializeField]
	private TextMeshProUGUI player1Text;

	[SerializeField]
	private TextMeshProUGUI player2Text;

	[SerializeField]
	private TextMeshProUGUI statusText;

	[SerializeField]
	private GTZone zone;

	[SerializeField]
	private GorillaPressableButton addFriendButton;

	private FriendingManager.FriendStationData displayedData;

	public TextMeshProUGUI Player1Text => player1Text;

	public TextMeshProUGUI Player2Text => player2Text;

	public TextMeshProUGUI StatusText => statusText;

	public GTZone Zone => zone;

	private void Awake()
	{
		triggerNotifier.TriggerEnterEvent += TriggerEntered;
		triggerNotifier.TriggerExitEvent += TriggerExited;
	}

	private void OnEnable()
	{
		FriendingManager.Instance.RegisterFriendingStation(this);
		if (PhotonNetwork.InRoom)
		{
			displayedData.actorNumberA = -1;
			displayedData.actorNumberB = -1;
			displayedData.state = FriendingManager.FriendStationState.WaitingForPlayers;
		}
		else
		{
			displayedData.actorNumberA = -2;
			displayedData.actorNumberB = -2;
			displayedData.state = FriendingManager.FriendStationState.NotInRoom;
		}
		UpdatePlayerText(player1Text, displayedData.actorNumberA);
		UpdatePlayerText(player2Text, displayedData.actorNumberB);
		UpdateDisplayedState(displayedData.state);
	}

	private void OnDisable()
	{
		FriendingManager.Instance.UnregisterFriendingStation(this);
	}

	private void UpdatePlayerText(TextMeshProUGUI playerText, int playerId)
	{
		switch (playerId)
		{
		case -2:
			playerText.text = "";
			return;
		case -1:
			playerText.text = "PLAYER:\nNONE";
			return;
		}
		NetPlayer netPlayerByID = NetworkSystem.Instance.GetNetPlayerByID(playerId);
		if (netPlayerByID != null)
		{
			playerText.text = "PLAYER:\n" + netPlayerByID.SanitizedNickName;
		}
		else
		{
			playerText.text = "PLAYER:\nNONE";
		}
	}

	private void UpdateDisplayedState(FriendingManager.FriendStationState state)
	{
		switch (state)
		{
		case FriendingManager.FriendStationState.NotInRoom:
			statusText.text = "JOIN A ROOM TO USE";
			break;
		case FriendingManager.FriendStationState.WaitingForPlayers:
			statusText.text = "";
			break;
		case FriendingManager.FriendStationState.WaitingOnFriendStatusBoth:
			statusText.text = "LOADING";
			break;
		case FriendingManager.FriendStationState.WaitingOnFriendStatusPlayerA:
			statusText.text = "LOADING";
			break;
		case FriendingManager.FriendStationState.WaitingOnFriendStatusPlayerB:
			statusText.text = "LOADING";
			break;
		case FriendingManager.FriendStationState.WaitingOnButtonBoth:
			statusText.text = "PRESS [       ] PRESS";
			break;
		case FriendingManager.FriendStationState.WaitingOnButtonPlayerA:
			statusText.text = "PRESS [       ] READY";
			break;
		case FriendingManager.FriendStationState.WaitingOnButtonPlayerB:
			statusText.text = "READY [       ] PRESS";
			break;
		case FriendingManager.FriendStationState.ButtonConfirmationTimer0:
			statusText.text = "READY [       ] READY";
			break;
		case FriendingManager.FriendStationState.ButtonConfirmationTimer1:
			statusText.text = "READY [-     -] READY";
			break;
		case FriendingManager.FriendStationState.ButtonConfirmationTimer2:
			statusText.text = "READY [--   --] READY";
			break;
		case FriendingManager.FriendStationState.ButtonConfirmationTimer3:
			statusText.text = "READY [--- ---] READY";
			break;
		case FriendingManager.FriendStationState.ButtonConfirmationTimer4:
			statusText.text = "READY [-------] READY";
			break;
		case FriendingManager.FriendStationState.WaitingOnRequestBoth:
			statusText.text = " SENT [-------] SENT ";
			break;
		case FriendingManager.FriendStationState.WaitingOnRequestPlayerA:
			statusText.text = " SENT [-------] DONE ";
			break;
		case FriendingManager.FriendStationState.WaitingOnRequestPlayerB:
			statusText.text = " DONE [-------] SENT ";
			break;
		case FriendingManager.FriendStationState.RequestFailed:
			statusText.text = "FRIEND REQUEST FAILED";
			break;
		case FriendingManager.FriendStationState.Friends:
			statusText.text = "\\O/ FRIENDS \\O/";
			break;
		case FriendingManager.FriendStationState.AlreadyFriends:
			statusText.text = "ALREADY FRIENDS";
			break;
		}
	}

	private void UpdateAddFriendButton()
	{
		int actorNumber = NetworkSystem.Instance.LocalPlayer.ActorNumber;
		if ((displayedData.state >= FriendingManager.FriendStationState.ButtonConfirmationTimer0 && displayedData.state <= FriendingManager.FriendStationState.ButtonConfirmationTimer4) || (displayedData.actorNumberA == actorNumber && displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonPlayerB) || (displayedData.actorNumberB == actorNumber && displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonPlayerA))
		{
			addFriendButton.isOn = true;
		}
		else
		{
			addFriendButton.isOn = false;
		}
		addFriendButton.UpdateColor();
	}

	private void UpdateDisplay(ref FriendingManager.FriendStationData data)
	{
		if (displayedData.actorNumberA != data.actorNumberA)
		{
			UpdatePlayerText(player1Text, data.actorNumberA);
		}
		if (displayedData.actorNumberB != data.actorNumberB)
		{
			UpdatePlayerText(player2Text, data.actorNumberB);
		}
		if (displayedData.state != data.state)
		{
			UpdateDisplayedState(data.state);
		}
		displayedData = data;
		UpdateAddFriendButton();
	}

	public void UpdateState(FriendingManager.FriendStationData data)
	{
		UpdateDisplay(ref data);
	}

	public void TriggerEntered(TriggerEventNotifier notifier, Collider other)
	{
		if (PhotonNetwork.InRoom)
		{
			VRRig component = other.GetComponent<VRRig>();
			if (component != null && component.OwningNetPlayer != null)
			{
				addFriendButton.ResetState();
				FriendingManager.Instance.PlayerEnteredStation(zone, component.OwningNetPlayer);
			}
		}
		else if (other == GTPlayer.Instance.headCollider)
		{
			displayedData.state = FriendingManager.FriendStationState.NotInRoom;
			displayedData.actorNumberA = -2;
			displayedData.actorNumberB = -2;
			UpdateDisplayedState(displayedData.state);
			UpdatePlayerText(player1Text, displayedData.actorNumberA);
			UpdatePlayerText(player2Text, displayedData.actorNumberB);
			addFriendButton.ResetState();
		}
	}

	public void TriggerExited(TriggerEventNotifier notifier, Collider other)
	{
		if (PhotonNetwork.InRoom)
		{
			VRRig component = other.GetComponent<VRRig>();
			if (component != null)
			{
				addFriendButton.ResetState();
				FriendingManager.Instance.PlayerExitedStation(zone, component.OwningNetPlayer);
			}
		}
		else if (other == GTPlayer.Instance.headCollider)
		{
			displayedData.state = FriendingManager.FriendStationState.NotInRoom;
			displayedData.actorNumberA = -2;
			displayedData.actorNumberB = -2;
			UpdateDisplayedState(displayedData.state);
			UpdatePlayerText(player1Text, displayedData.actorNumberA);
			UpdatePlayerText(player2Text, displayedData.actorNumberB);
			addFriendButton.ResetState();
		}
	}

	public void FriendButtonPressed()
	{
		if (displayedData.state == FriendingManager.FriendStationState.WaitingForPlayers || displayedData.state == FriendingManager.FriendStationState.Friends)
		{
			return;
		}
		if (LocalPlayerIsAtCapacity(out var fullMessage))
		{
			statusText.text = fullMessage;
		}
		else if (!addFriendButton.isOn)
		{
			FriendingManager.Instance.photonView.RPC("FriendButtonPressedRPC", RpcTarget.MasterClient, zone);
			int actorNumber = NetworkSystem.Instance.LocalPlayer.ActorNumber;
			if (displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonBoth || (displayedData.actorNumberA == actorNumber && displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonPlayerA) || (displayedData.actorNumberB == actorNumber && displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonPlayerB))
			{
				addFriendButton.isOn = true;
				addFriendButton.UpdateColor();
			}
		}
	}

	private bool LocalPlayerIsAtCapacity(out string fullMessage)
	{
		fullMessage = null;
		FriendBackendController instance = FriendBackendController.Instance;
		if (instance == null || instance.FriendsList == null)
		{
			return false;
		}
		int configuredFreeExtraPageCount = FriendDisplay.ConfiguredFreeExtraPageCount;
		int configuredVimPageCount = FriendDisplay.ConfiguredVimPageCount;
		int num = 9 * configuredVimPageCount;
		int num2 = 9 + 9 * configuredFreeExtraPageCount;
		int num3 = num2 + num;
		int count = instance.FriendsList.Count;
		if (count < num2)
		{
			return false;
		}
		if (SubscriptionManager.IsLocalSubscribed() || configuredVimPageCount == 0)
		{
			if (count >= num3)
			{
				fullMessage = "CANNOT ADD FRIEND! ALL FRIEND SLOTS FILLED!";
				return true;
			}
			return false;
		}
		int num4 = Mathf.Clamp(count - num2, 0, num);
		if (num4 <= 0)
		{
			fullMessage = ZString.Format("FRIEND SLOTS ARE FULL! SUBSCRIBE FOR {0} ADDITIONAL SLOTS!", num);
		}
		else
		{
			int arg = num - num4;
			fullMessage = ZString.Format("RENEW GTFC SUBSCRIPTION TO UNLOCK YOUR REMAINING {0} SLOTS.", arg);
		}
		return true;
	}

	public void FriendButtonReleased()
	{
		if (displayedData.state != FriendingManager.FriendStationState.WaitingForPlayers && displayedData.state != FriendingManager.FriendStationState.Friends && addFriendButton.isOn)
		{
			FriendingManager.Instance.photonView.RPC("FriendButtonUnpressedRPC", RpcTarget.MasterClient, zone);
			int actorNumber = NetworkSystem.Instance.LocalPlayer.ActorNumber;
			if ((displayedData.state >= FriendingManager.FriendStationState.ButtonConfirmationTimer0 && displayedData.state <= FriendingManager.FriendStationState.ButtonConfirmationTimer4) || (displayedData.actorNumberA == actorNumber && displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonPlayerB) || (displayedData.actorNumberB == actorNumber && displayedData.state == FriendingManager.FriendStationState.WaitingOnButtonPlayerA))
			{
				addFriendButton.isOn = false;
				addFriendButton.UpdateColor();
			}
		}
	}
}
public class FriendSystem : MonoBehaviour
{
	public delegate void FriendRequestCallback(GTZone zone, int localId, int friendId, bool success);

	private struct FriendRequestData
	{
		public GTZone zone;

		public int sendingPlayerId;

		public int targetPlayerId;

		public float localTimeSent;

		public FriendRequestCallback completionCallback;
	}

	public delegate void FriendRemovalCallback(int friendId, bool success);

	private struct FriendRemovalData
	{
		public int targetPlayerId;

		public float localTimeSent;

		public FriendRemovalCallback completionCallback;
	}

	private enum FriendRequestStatus
	{
		Pending,
		Succeeded,
		Failed
	}

	public enum PlayerPrivacy
	{
		Visible,
		PublicOnly,
		Hidden
	}

	[OnEnterPlay_SetNull]
	public static volatile FriendSystem Instance;

	[SerializeField]
	private float friendRequestExpirationTime = 10f;

	private PlayerPrivacy localPlayerPrivacy;

	private List<FriendRequestData> pendingFriendRequests = new List<FriendRequestData>();

	private List<FriendRemovalData> pendingFriendRemovals = new List<FriendRemovalData>();

	private List<int> indexesToRemove = new List<int>();

	private float lastFriendsListRefresh;

	public PlayerPrivacy LocalPlayerPrivacy => localPlayerPrivacy;

	public event Action<List<FriendBackendController.Friend>> OnFriendListRefresh;

	public void SetLocalPlayerPrivacy(PlayerPrivacy privacyState)
	{
		localPlayerPrivacy = privacyState;
		FriendBackendController.Instance.SetPrivacyState(privacyState switch
		{
			PlayerPrivacy.PublicOnly => FriendBackendController.PrivacyState.PUBLIC_ONLY, 
			PlayerPrivacy.Hidden => FriendBackendController.PrivacyState.HIDDEN, 
			_ => FriendBackendController.PrivacyState.VISIBLE, 
		});
	}

	public void RefreshFriendsList()
	{
		FriendBackendController.Instance.GetFriends();
	}

	public void SendFriendRequest(NetPlayer targetPlayer, GTZone stationZone, FriendRequestCallback callback)
	{
		FriendRequestData item = new FriendRequestData
		{
			completionCallback = callback,
			sendingPlayerId = NetworkSystem.Instance.LocalPlayer.UserId.GetHashCode(),
			targetPlayerId = targetPlayer.UserId.GetHashCode(),
			localTimeSent = Time.realtimeSinceStartup,
			zone = stationZone
		};
		pendingFriendRequests.Add(item);
		FriendBackendController.Instance.AddFriend(targetPlayer);
	}

	public void RemoveFriend(FriendBackendController.Friend friend, FriendRemovalCallback callback = null)
	{
		pendingFriendRemovals.Add(new FriendRemovalData
		{
			completionCallback = callback,
			targetPlayerId = friend.Presence.FriendLinkId.GetHashCode(),
			localTimeSent = Time.realtimeSinceStartup
		});
		FriendBackendController.Instance.RemoveFriend(friend);
	}

	public bool HasPendingFriendRequest(GTZone zone, int senderId)
	{
		for (int i = 0; i < pendingFriendRequests.Count; i++)
		{
			if (pendingFriendRequests[i].zone == zone && pendingFriendRequests[i].sendingPlayerId == senderId)
			{
				return true;
			}
		}
		return false;
	}

	public bool CheckFriendshipWithPlayer(int targetActorNumber)
	{
		NetPlayer player = NetworkSystem.Instance.GetPlayer(targetActorNumber);
		if (player != null)
		{
			int hashCode = player.UserId.GetHashCode();
			List<FriendBackendController.Friend> friendsList = FriendBackendController.Instance.FriendsList;
			for (int i = 0; i < friendsList.Count; i++)
			{
				if (friendsList[i] != null && friendsList[i].Presence != null && friendsList[i].Presence.FriendLinkId.GetHashCode() == hashCode)
				{
					return true;
				}
			}
		}
		return false;
	}

	private void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void Start()
	{
		FriendBackendController.Instance.OnGetFriendsComplete += OnGetFriendsReturned;
		FriendBackendController.Instance.OnAddFriendComplete += OnAddFriendReturned;
		FriendBackendController.Instance.OnRemoveFriendComplete += OnRemoveFriendReturned;
	}

	private void OnDestroy()
	{
		if (FriendBackendController.Instance != null)
		{
			FriendBackendController.Instance.OnGetFriendsComplete -= OnGetFriendsReturned;
			FriendBackendController.Instance.OnAddFriendComplete -= OnAddFriendReturned;
			FriendBackendController.Instance.OnRemoveFriendComplete -= OnRemoveFriendReturned;
		}
	}

	private void OnGetFriendsReturned(bool succeeded)
	{
		if (succeeded)
		{
			lastFriendsListRefresh = Time.realtimeSinceStartup;
			switch (FriendBackendController.Instance.MyPrivacyState)
			{
			default:
				localPlayerPrivacy = PlayerPrivacy.Visible;
				break;
			case FriendBackendController.PrivacyState.PUBLIC_ONLY:
				localPlayerPrivacy = PlayerPrivacy.PublicOnly;
				break;
			case FriendBackendController.PrivacyState.HIDDEN:
				localPlayerPrivacy = PlayerPrivacy.Hidden;
				break;
			}
			this.OnFriendListRefresh?.Invoke(FriendBackendController.Instance.FriendsList);
		}
	}

	private void OnAddFriendReturned(NetPlayer targetPlayer, bool succeeded)
	{
		int hashCode = targetPlayer.UserId.GetHashCode();
		indexesToRemove.Clear();
		for (int i = 0; i < pendingFriendRequests.Count; i++)
		{
			if (pendingFriendRequests[i].targetPlayerId == hashCode)
			{
				pendingFriendRequests[i].completionCallback?.Invoke(pendingFriendRequests[i].zone, pendingFriendRequests[i].sendingPlayerId, pendingFriendRequests[i].targetPlayerId, succeeded);
				indexesToRemove.Add(i);
			}
			else if (pendingFriendRequests[i].localTimeSent + friendRequestExpirationTime < Time.realtimeSinceStartup)
			{
				indexesToRemove.Add(i);
			}
		}
		for (int num = indexesToRemove.Count - 1; num >= 0; num--)
		{
			pendingFriendRequests.RemoveAt(indexesToRemove[num]);
		}
	}

	private void OnRemoveFriendReturned(FriendBackendController.Friend friend, bool succeeded)
	{
		if (friend == null || friend.Presence == null)
		{
			return;
		}
		int hashCode = friend.Presence.FriendLinkId.GetHashCode();
		indexesToRemove.Clear();
		for (int i = 0; i < pendingFriendRemovals.Count; i++)
		{
			if (pendingFriendRemovals[i].targetPlayerId == hashCode)
			{
				pendingFriendRemovals[i].completionCallback?.Invoke(hashCode, succeeded);
				indexesToRemove.Add(i);
			}
			else if (pendingFriendRemovals[i].localTimeSent + friendRequestExpirationTime < Time.realtimeSinceStartup)
			{
				indexesToRemove.Add(i);
			}
		}
		for (int num = indexesToRemove.Count - 1; num >= 0; num--)
		{
			pendingFriendRemovals.RemoveAt(indexesToRemove[num]);
		}
	}
}
public class GorillaFriendCollider : MonoBehaviour, IGorillaSliceableSimple
{
	public List<string> playerIDsCurrentlyTouching = new List<string>();

	private CapsuleCollider thisCapsule;

	private BoxCollider thisBox;

	[Tooltip("If using a capsule collider, the player position can be checked against these minimum and maximum Y limits (world position) to make it behave more like a cylinder check")]
	public bool applyCapsuleYLimits;

	[Tooltip("If the player's Y world position is lower than Limits.x or higher than Limits.y, they will not be considered \"Inside\" the friend collider")]
	public UnityEngine.Vector2 capsuleColliderYLimits = UnityEngine.Vector2.zero;

	public bool runCheckWhileNotInRoom;

	public string[] myAllowedMapsToJoin;

	private readonly Collider[] overlapColliders = new Collider[20];

	public bool manualRefreshOnly;

	private float _nextUpdateTime = -1f;

	private static List<VRRig> playerRigs = new List<VRRig>();

	private static bool updateAdded = false;

	private static readonly ProfilerMarker profiler_SliceUpdate = new ProfilerMarker("GT/FriendCollider.SliceUpdate");

	public void Awake()
	{
		thisCapsule = GetComponent<CapsuleCollider>();
		thisBox = GetComponent<BoxCollider>();
		if (!updateAdded)
		{
			updateAdded = true;
			VRRigCache.OnActiveRigsChanged += UpdateActiveRigs;
			UpdateActiveRigs();
		}
	}

	private static void UpdateActiveRigs()
	{
		VRRigCache.Instance.GetActiveRigs(playerRigs);
	}

	public void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	public void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
	}

	private void AddUserID(in string userID)
	{
		if (!playerIDsCurrentlyTouching.Contains(userID))
		{
			playerIDsCurrentlyTouching.Add(userID);
		}
	}

	public void SliceUpdate()
	{
		using (profiler_SliceUpdate.Auto())
		{
			if (NetworkSystem.Instance.InRoom || runCheckWhileNotInRoom)
			{
				RefreshPlayersWithinBounds();
			}
		}
	}

	public void RefreshPlayersWithinBounds()
	{
		playerIDsCurrentlyTouching.Clear();
		for (int i = 0; i < playerRigs.Count; i++)
		{
			float y = playerRigs[i].bodyTransform.transform.position.y;
			bool num = !applyCapsuleYLimits || (y >= capsuleColliderYLimits.x && y <= capsuleColliderYLimits.y);
			bool flag = (thisBox != null && WithinBounds.PointWithinBoxColliderBounds(playerRigs[i].rigContainer.SpeakerHead.position, thisBox)) || (thisBox == null && thisCapsule != null && WithinBounds.PointWithinCapsuleColliderBounds(playerRigs[i].rigContainer.SpeakerHead.position, thisCapsule));
			if (num && flag)
			{
				playerIDsCurrentlyTouching.Add(playerRigs[i].isLocal ? NetworkSystem.Instance.LocalPlayer.UserId : playerRigs[i].creator.UserId);
			}
		}
		if (NetworkSystem.Instance.InRoom && NetworkSystem.Instance.LocalPlayer != null && playerIDsCurrentlyTouching.Contains(NetworkSystem.Instance.LocalPlayer.UserId) && GorillaComputer.instance.friendJoinCollider != this)
		{
			GorillaComputer.instance.allowedMapsToJoin = myAllowedMapsToJoin;
			GorillaComputer.instance.friendJoinCollider = this;
			GorillaComputer.instance.UpdateScreen();
		}
	}
}
