public class MothershipAuthenticator : MonoBehaviour, IGorillaSliceableSimple
{
	public static volatile MothershipAuthenticator Instance;

	public MetaAuthenticator MetaAuthenticator;

	public SteamAuthenticator SteamAuthenticator;

	public string TestNickname;

	public string TestAccountId;

	public bool UseConstantTestAccountId;

	private int loginAttempts;

	public int MaxLoginAttempts = 5;

	public Action OnLoginSuccess;

	public Action<string, string, string> OnLoginFailure;

	public Action<int> OnLoginAttemptFailure;

	private double lastSliceUpdateTime;

	[RuntimeInitializeOnLoadMethod]
	private static void Init()
	{
		if (Instance == null)
		{
			Instance = null;
		}
	}

	public void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
		}
		else if (Instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		if (!MothershipClientApiUnity.IsEnabled())
		{
			UnityEngine.Debug.Log("Mothership is not enabled.");
			return;
		}
		if (Instance.SteamAuthenticator == null)
		{
			Instance.SteamAuthenticator = Instance.gameObject.GetOrAddComponent<SteamAuthenticator>();
		}
		MothershipClientApiUnity.SetAuthRefreshedCallback(delegate
		{
			BeginLoginFlow();
		});
	}

	public void BeginLoginFlow()
	{
		UnityEngine.Debug.Log("making login call");
		LogInWithSteam();
	}

	private void LogInWithInsecure()
	{
		MothershipClientApiUnity.LogInWithInsecure1(TestNickname, TestAccountId, delegate(LoginResponse LoginResponse)
		{
			UnityEngine.Debug.Log("Logged in with Mothership Id " + LoginResponse.MothershipPlayerId);
			MothershipClientApiUnity.OpenNotificationsSocket();
			OnLoginSuccess?.Invoke();
		}, delegate(MothershipError MothershipError, int errorCode)
		{
			UnityEngine.Debug.LogError($"Failed to log in, error {MothershipError.Message} trace ID: {MothershipError.TraceId} status: {errorCode} Mothership error code: {MothershipError.MothershipErrorCode}");
			OnLoginAttemptFailure?.Invoke(1);
			OnLoginFailure?.Invoke(MothershipError.Message, MothershipError.MothershipErrorCode, MothershipError.TraceId);
		});
	}

	private void LogInWithSteam()
	{
		MothershipClientApiUnity.StartLoginWithSteam(delegate(PlayerSteamBeginLoginResponse resp)
		{
			UnityEngine.Debug.Log($"Mothership: Steam Login started at {DateTime.Now}");
			string nonce = resp.Nonce;
			SteamAuthTicket ticketHandle = HAuthTicket.Invalid;
			ticketHandle = SteamAuthenticator.GetAuthTicketForWebApi(nonce, delegate(string ticket)
			{
				UnityEngine.Debug.Log($"Mothership: Attempting to complete login at {DateTime.Now}");
				MothershipClientApiUnity.CompleteLoginWithSteam(nonce, ticket, delegate
				{
					ticketHandle.Dispose();
					UnityEngine.Debug.Log("Logged in to Mothership with Steam");
					MothershipClientApiUnity.OpenNotificationsSocket();
					OnLoginSuccess?.Invoke();
				}, delegate(MothershipError MothershipError, int errorCode)
				{
					ticketHandle.Dispose();
					UnityEngine.Debug.LogError($"Couldn't log into Mothership with Steam error {MothershipError.Message} trace ID: {MothershipError.TraceId} status: {errorCode} Mothership error code: {MothershipError.MothershipErrorCode}");
					loginAttempts++;
					OnLoginAttemptFailure?.Invoke(loginAttempts);
					if (loginAttempts >= MaxLoginAttempts)
					{
						OnLoginFailure?.Invoke(MothershipError.Message, MothershipError.MothershipErrorCode, MothershipError.TraceId);
					}
					else
					{
						LogInWithSteam();
					}
				});
			}, delegate(EResult error)
			{
				string text = $"Couldn't get an auth ticket for logging into Mothership with Steam: {error}";
				UnityEngine.Debug.LogError(text);
				OnLoginAttemptFailure?.Invoke(1);
				OnLoginFailure?.Invoke(text, "", "");
			});
		}, delegate(MothershipError MothershipError, int errorCode)
		{
			UnityEngine.Debug.LogError($"Couldn't start Mothership auth for Steam error {MothershipError.Message} trace ID: {MothershipError.TraceId} status: {errorCode} Mothership error code: {MothershipError.MothershipErrorCode}");
			OnLoginAttemptFailure?.Invoke(1);
			OnLoginFailure?.Invoke(MothershipError.Message, MothershipError.MothershipErrorCode, MothershipError.TraceId);
		});
	}

	public void OnEnable()
	{
		if (MothershipClientApiUnity.IsEnabled())
		{
			GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
			lastSliceUpdateTime = Time.unscaledTimeAsDouble;
		}
	}

	public void OnDisable()
	{
		if (MothershipClientApiUnity.IsEnabled())
		{
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
		}
	}

	public void SliceUpdate()
	{
		double unscaledTimeAsDouble = Time.unscaledTimeAsDouble;
		float deltaTime = (float)(unscaledTimeAsDouble - lastSliceUpdateTime);
		lastSliceUpdateTime = unscaledTimeAsDouble;
		MothershipClientApiUnity.Tick(deltaTime);
	}
}
internal class OwnershipGuardHandler : IPunOwnershipCallbacks
{
	private static HashSet<PhotonView> guardedViews;

	private static readonly OwnershipGuardHandler callbackInstance;

	static OwnershipGuardHandler()
	{
		guardedViews = new HashSet<PhotonView>();
		callbackInstance = new OwnershipGuardHandler();
		PhotonNetwork.AddCallbackTarget(callbackInstance);
	}

	internal static void RegisterView(PhotonView view)
	{
		if (!(view == null) && !guardedViews.Contains(view))
		{
			guardedViews.Add(view);
		}
	}

	internal static void RegisterViews(PhotonView[] photonViews)
	{
		for (int i = 0; i < photonViews.Length; i++)
		{
			RegisterView(photonViews[i]);
		}
	}

	internal static void RemoveView(PhotonView view)
	{
		if (!(view == null))
		{
			guardedViews.Remove(view);
		}
	}

	internal static void RemoveViews(PhotonView[] photonViews)
	{
		for (int i = 0; i < photonViews.Length; i++)
		{
			RemoveView(photonViews[i]);
		}
	}

	void IPunOwnershipCallbacks.OnOwnershipTransfered(PhotonView targetView, Player previousOwner)
	{
		if (!guardedViews.Contains(targetView))
		{
			return;
		}
		if (targetView.IsRoomView)
		{
			if (targetView.Owner != PhotonNetwork.MasterClient)
			{
				targetView.OwnerActorNr = 0;
				targetView.ControllerActorNr = 0;
			}
		}
		else if (targetView.OwnerActorNr != targetView.CreatorActorNr || targetView.ControllerActorNr != targetView.CreatorActorNr)
		{
			targetView.OwnerActorNr = targetView.CreatorActorNr;
			targetView.ControllerActorNr = targetView.CreatorActorNr;
		}
	}

	void IPunOwnershipCallbacks.OnOwnershipRequest(PhotonView targetView, Player requestingPlayer)
	{
	}

	void IPunOwnershipCallbacks.OnOwnershipTransferFailed(PhotonView targetView, Player senderOfFailedRequest)
	{
	}
}
