	public static ref readonly T[] FetchDelegatesNonAlloc<T>(T @delegate) where T : MulticastDelegate
	{
		if (@delegate == null)
		{
			return ref EmptyArray<T>.Ref();
		}
		return ref @delegate.GetInvocationListUnsafe();
	}

	public static object[] FetchScratchArray(int size)
	{
		if (size < 0)
		{
			throw new Exception("Size cannot be less than 0.");
		}
		if (!gLengthToArgsArray.TryGetValue(size, out var value))
		{
			value = new object[size];
			gLengthToArgsArray.Add(size, value);
		}
		return value;
	}

	public static NetPlayer GetNetPlayer(int actorNumber)
	{
		if (!TryGetNetSystem(out var ns))
		{
			return null;
		}
		return ns.GetPlayer(actorNumber);
	}

	private static bool TryGetNetSystem(out NetworkSystem ns)
	{
		if (!gNetSystem)
		{
			gNetSystem = NetworkSystem.Instance;
		}
		if (!gNetSystem)
		{
			ns = null;
			return false;
		}
		ns = gNetSystem;
		return true;
	}

	static PhotonUtils()
	{
		gLengthToArgsArray = new Dictionary<int, object[]>(16);
		for (int i = 0; i <= 16; i++)
		{
			gLengthToArgsArray.Add(i, new object[i]);
		}
	}
}
public class RigOwnedPhysicsBody : MonoBehaviour
{
	private VRRig rig;

	public RigOwnedTransformView transformView;

	private bool hasTransformView;

	public RigOwnedRigidbodyView rigidbodyView;

	private bool hasRigidbodyView;

	public MonoBehaviourPun[] otherComponents;

	private bool hasRig;

	[Tooltip("To make a rigidbody unaffected by the movement of the holdable part, put this script on the holdable, make the RigOwnedRigidbodyView a child of it, and check this box")]
	[SerializeField]
	private bool detachTransform;

	private void Awake()
	{
		hasTransformView = transformView != null;
		hasRigidbodyView = rigidbodyView != null;
		if (!hasTransformView && !hasRigidbodyView && otherComponents.Length == 0)
		{
			GTDev.LogError("RigOwnedPhysicsBody has nothing to do! No TransformView, RigidbodyView, or otherComponents");
		}
		if (detachTransform)
		{
			if (hasTransformView)
			{
				transformView.transform.parent = null;
			}
			else if (hasRigidbodyView)
			{
				rigidbodyView.transform.parent = null;
			}
		}
	}

	private void OnEnable()
	{
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		NetworkSystem.Instance.OnJoinedRoomEvent += new Action(OnNetConnect);
		NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(OnNetDisconnect);
		if (!hasRig)
		{
			rig = GetComponentInParent<VRRig>();
			hasRig = rig != null;
		}
		if (detachTransform)
		{
			if (hasTransformView)
			{
				transformView.gameObject.SetActive(value: true);
			}
			else if (hasRigidbodyView)
			{
				rigidbodyView.gameObject.SetActive(value: true);
			}
		}
		if (NetworkSystem.Instance.InRoom)
		{
			OnNetConnect();
		}
		else
		{
			OnNetDisconnect();
		}
	}

	private void OnDisable()
	{
		NetworkSystem.Instance.OnJoinedRoomEvent -= new Action(OnNetConnect);
		NetworkSystem.Instance.OnReturnedToSinglePlayer -= new Action(OnNetDisconnect);
		if (detachTransform)
		{
			if (hasTransformView)
			{
				transformView.gameObject.SetActive(value: false);
			}
			else if (hasRigidbodyView)
			{
				rigidbodyView.gameObject.SetActive(value: false);
			}
		}
		OnNetDisconnect();
	}

	private void OnNetConnect()
	{
		if (hasTransformView)
		{
			transformView.enabled = hasRig;
		}
		if (hasRigidbodyView)
		{
			rigidbodyView.enabled = hasRig;
		}
		MonoBehaviourPun[] array = otherComponents;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = hasRig;
		}
		if (!hasRig)
		{
			return;
		}
		PhotonView getView = rig.netView.GetView;
		List<UnityEngine.Component> observedComponents = getView.ObservedComponents;
		if (hasTransformView)
		{
			transformView.SetIsMine(getView.IsMine);
			if (!observedComponents.Contains(transformView))
			{
				observedComponents.Add(transformView);
			}
		}
		if (hasRigidbodyView)
		{
			rigidbodyView.SetIsMine(getView.IsMine);
			if (!observedComponents.Contains(rigidbodyView))
			{
				observedComponents.Add(rigidbodyView);
			}
		}
		array = otherComponents;
		foreach (MonoBehaviourPun item in array)
		{
			if (!observedComponents.Contains(item))
			{
				observedComponents.Add(item);
			}
		}
	}

	private void OnNetDisconnect()
	{
		if (ApplicationQuittingState.IsQuitting)
		{
			return;
		}
		if (hasTransformView)
		{
			transformView.enabled = false;
		}
		if (hasRigidbodyView)
		{
			rigidbodyView.enabled = false;
		}
		MonoBehaviourPun[] array = otherComponents;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].enabled = false;
		}
		if (hasRig && NetworkSystem.Instance.InRoom)
		{
			List<UnityEngine.Component> observedComponents = rig.netView.GetView.ObservedComponents;
			if (hasTransformView)
			{
				observedComponents.Remove(transformView);
			}
			if (hasRigidbodyView)
			{
				observedComponents.Remove(rigidbodyView);
			}
			array = otherComponents;
			foreach (MonoBehaviourPun item in array)
			{
				observedComponents.Remove(item);
			}
		}
	}
}
public class PUNErrorLogging : MonoBehaviour
{
	[Flags]
	private enum LogFlags
	{
		SerializeView = 1,
		OwnershipTransfer = 2,
		OwnershipRequest = 4,
		OwnershipUpdate = 8,
		RPC = 0x10,
		Instantiate = 0x20,
		Destroy = 0x40,
		DestroyPlayer = 0x80
	}

	[SerializeField]
	private bool m_logSerializeView = true;

	[SerializeField]
	private bool m_logOwnershipTransfer = true;

	[SerializeField]
	private bool m_logOwnershipRequest = true;

	[SerializeField]
	private bool m_logOwnershipUpdate = true;

	[SerializeField]
	private bool m_logRPC = true;

	[SerializeField]
	private bool m_logInstantiate = true;

	[SerializeField]
	private bool m_logDestroy = true;

	[SerializeField]
	private bool m_logDestroyPlayer = true;

	private void Start()
	{
		PhotonNetwork.InternalEventError = (Action<EventData, Exception>)Delegate.Combine(PhotonNetwork.InternalEventError, new Action<EventData, Exception>(PUNError));
		PlayFabTitleDataCache.Instance.GetTitleData("PUNErrorLogging", delegate(string data)
		{
			if (int.TryParse(data, out var result))
			{
				LogFlags logFlags = (LogFlags)result;
				m_logSerializeView = logFlags.HasFlag(LogFlags.SerializeView);
				m_logOwnershipTransfer = logFlags.HasFlag(LogFlags.OwnershipTransfer);
				m_logOwnershipRequest = logFlags.HasFlag(LogFlags.OwnershipRequest);
				m_logOwnershipUpdate = logFlags.HasFlag(LogFlags.OwnershipUpdate);
				m_logRPC = logFlags.HasFlag(LogFlags.RPC);
				m_logInstantiate = logFlags.HasFlag(LogFlags.Instantiate);
				m_logDestroy = logFlags.HasFlag(LogFlags.Destroy);
				m_logDestroyPlayer = logFlags.HasFlag(LogFlags.DestroyPlayer);
			}
		}, delegate
		{
		});
	}

	private void PUNError(EventData data, Exception exception)
	{
		NetworkSystem.Instance.GetPlayer(data.Sender);
		switch (data.Code)
		{
		case 254:
			PrintException(exception, print: true);
			break;
		case 201:
		case 206:
			PrintException(exception, m_logSerializeView);
			break;
		case 210:
			PrintException(exception, m_logOwnershipTransfer);
			break;
		case 209:
			PrintException(exception, m_logOwnershipRequest);
			break;
		case 212:
			PrintException(exception, m_logOwnershipUpdate);
			break;
		case 200:
			PrintException(exception, m_logRPC);
			break;
		case 202:
			PrintException(exception, m_logInstantiate);
			break;
		case 204:
			PrintException(exception, m_logDestroy);
			break;
		case 207:
			PrintException(exception, m_logDestroyPlayer);
			break;
		default:
			PrintException(exception, print: true);
			break;
		}
	}

	private void PrintException(Exception e, bool print)
	{
		if (print)
		{
			UnityEngine.Debug.LogException(e);
		}
	}
}
public abstract class RandomComponent<T> : MonoBehaviour
{
	public T[] items = new T[0];

	public int seed;

	public bool staticSeed;

	public bool distinct = true;

	[NonSerialized]
	[Space]
	private int _seed;

	[NonSerialized]
	private T _lastItem;

	[NonSerialized]
	private int _lastItemIndex = -1;

	[NonSerialized]
	private SRand _rnd;

	public UnityEvent<T> onNextItem;

	public T lastItem => _lastItem;

	public int lastItemIndex => _lastItemIndex;

	public void ResetRandom(int? seedValue = null)
	{
		if (!staticSeed)
		{
			_seed = seedValue ?? StaticHash.Compute(DateTime.UtcNow.Ticks);
		}
		else
		{
			_seed = seed;
		}
		_rnd = new SRand(_seed);
	}

	public void Reset()
	{
		ResetRandom();
		_lastItem = default(T);
		_lastItemIndex = -1;
	}

	private void Awake()
	{
		Reset();
	}

	protected virtual void OnNextItem(T item)
	{
	}

	public virtual T GetItem(int index)
	{
		return items[index];
	}

	public virtual T NextItem()
	{
		_lastItemIndex = (distinct ? _rnd.NextIntWithExclusion(0, items.Length, _lastItemIndex) : _rnd.NextInt(0, items.Length));
		T val = (_lastItem = items[_lastItemIndex]);
		OnNextItem(val);
		onNextItem?.Invoke(val);
		return val;
	}
}
public abstract class RandomContainer<T> : ScriptableObject
{
	public T[] items = new T[0];

	public int seed;

	public bool staticSeed;

	public bool distinct = true;

	[NonSerialized]
	[Space]
	private int _seed;

	[NonSerialized]
	private T _lastItem;

	[NonSerialized]
	private int _lastItemIndex = -1;

	[NonSerialized]
	private SRand _rnd;

	public T lastItem => _lastItem;

	public int lastItemIndex => _lastItemIndex;

	public void ResetRandom(int? seedValue = null)
	{
		if (!staticSeed)
		{
			_seed = seedValue ?? StaticHash.Compute(DateTime.UtcNow.Ticks);
		}
		else
		{
			_seed = seed;
		}
		_rnd = new SRand(_seed);
	}

	public void Reset()
	{
		ResetRandom();
		_lastItem = default(T);
		_lastItemIndex = -1;
	}

	private void Awake()
	{
		Reset();
	}

	public virtual T GetItem(int index)
	{
		return items[index];
	}

	public virtual T NextItem()
	{
		_lastItemIndex = (distinct ? _rnd.NextIntWithExclusion(0, items.Length, _lastItemIndex) : _rnd.NextInt(0, items.Length));
		return _lastItem = items[_lastItemIndex];
	}
}
