[DisallowMultipleComponent]
public class SteamManager : MonoBehaviour
{
	protected static bool s_EverInitialized;

	protected static SteamManager s_instance;

	protected bool m_bInitialized;

	protected SteamAPIWarningMessageHook_t m_SteamAPIWarningMessageHook;

	protected static SteamManager Instance
	{
		get
		{
			if (s_instance == null)
			{
				return new GameObject("SteamManager").AddComponent<SteamManager>();
			}
			return s_instance;
		}
	}

	public static bool Initialized => Instance.m_bInitialized;

	[MonoPInvokeCallback(typeof(SteamAPIWarningMessageHook_t))]
	protected static void SteamAPIDebugTextHook(int nSeverity, StringBuilder pchDebugText)
	{
		UnityEngine.Debug.LogWarning(pchDebugText);
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
	private static void InitOnPlayMode()
	{
		s_EverInitialized = false;
		s_instance = null;
	}

	protected virtual void Awake()
	{
		if (s_instance != null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		s_instance = this;
		if (s_EverInitialized)
		{
			throw new Exception("Tried to Initialize the SteamAPI twice in one session!");
		}
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(AppId_t.Invalid))
			{
				UnityEngine.Debug.Log("[Steamworks.NET] Shutting down because RestartAppIfNecessary returned true. Steam will restart the application.");
				UnityEngine.Application.Quit();
				return;
			}
		}
		catch (DllNotFoundException ex)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			UnityEngine.Application.Quit();
			return;
		}
		m_bInitialized = SteamAPI.Init();
		if (!m_bInitialized)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] SteamAPI_Init() failed. Refer to Valve's documentation or the comment above this line for more information.", this);
		}
		else
		{
			s_EverInitialized = true;
		}
	}

	protected virtual void OnEnable()
	{
		if (s_instance == null)
		{
			s_instance = this;
		}
		if (m_bInitialized && m_SteamAPIWarningMessageHook == null)
		{
			m_SteamAPIWarningMessageHook = SteamAPIDebugTextHook;
			SteamClient.SetWarningMessageHook(m_SteamAPIWarningMessageHook);
		}
	}

	protected virtual void OnDestroy()
	{
		if (!(s_instance != this))
		{
			s_instance = null;
			if (m_bInitialized)
			{
				SteamAPI.Shutdown();
			}
		}
	}

	protected virtual void Update()
	{
		if (m_bInitialized)
		{
			SteamAPI.RunCallbacks();
		}
	}
}
[Serializable]
public class CallLimiter
{
	protected const double k_serverMaxTime = 4294967.295;

	[SerializeField]
	protected float[] callTimeHistory;

	[Space]
	[SerializeField]
	protected int callHistoryLength;

	[SerializeField]
	protected float timeCooldown;

	[SerializeField]
	protected double maxLatency;

	private int oldTimeIndex;

	protected bool blockCall;

	protected float blockStartTime;

	public CallLimiter()
	{
	}

	public CallLimiter(int historyLength, float coolDown, float latencyMax = 0.5f)
	{
		callTimeHistory = new float[historyLength];
		callHistoryLength = historyLength;
		for (int i = 0; i < historyLength; i++)
		{
			callTimeHistory[i] = float.MinValue;
		}
		timeCooldown = coolDown;
		maxLatency = latencyMax;
	}

	public bool CheckCallServerTime(double time)
	{
		double currentTime = PhotonNetwork.CurrentTime;
		double num = maxLatency;
		double num2 = 4294967.295 - maxLatency;
		double num3;
		if (currentTime > num || time < num)
		{
			if (time > currentTime + 0.05)
			{
				return false;
			}
			num3 = currentTime - time;
		}
		else
		{
			double num4 = num2 + currentTime;
			if (time > currentTime + 0.5 && time < num4)
			{
				return false;
			}
			num3 = currentTime + (4294967.295 - time);
		}
		if (num3 > maxLatency)
		{
			return false;
		}
		int num5 = ((oldTimeIndex > 0) ? (oldTimeIndex - 1) : (callHistoryLength - 1));
		double num6 = callTimeHistory[num5];
		if (num6 > num2 && time < num6)
		{
			Reset();
		}
		else if (time < num6)
		{
			return false;
		}
		return CheckCallTime((float)time);
	}

	public virtual bool CheckCallTime(float time)
	{
		if (callTimeHistory[oldTimeIndex] > time)
		{
			blockCall = true;
			blockStartTime = time;
			return false;
		}
		callTimeHistory[oldTimeIndex] = time + timeCooldown;
		oldTimeIndex = ++oldTimeIndex % callHistoryLength;
		blockCall = false;
		return true;
	}

	public virtual void Reset()
	{
		if (callTimeHistory != null)
		{
			for (int i = 0; i < callHistoryLength; i++)
			{
				callTimeHistory[i] = float.MinValue;
			}
			oldTimeIndex = 0;
			blockStartTime = 0f;
			blockCall = false;
		}
	}
}
[Serializable]
public class CallLimiterWithCooldown : CallLimiter
{
	[SerializeField]
	private float spamCoolDown;

	public CallLimiterWithCooldown(float coolDownSpam, int historyLength, float coolDown)
		: base(historyLength, coolDown)
	{
		spamCoolDown = coolDownSpam;
	}

	public CallLimiterWithCooldown(float coolDownSpam, int historyLength, float coolDown, float latencyMax)
		: base(historyLength, coolDown, latencyMax)
	{
		spamCoolDown = coolDownSpam;
	}

	public override bool CheckCallTime(float time)
	{
		if (blockCall && time < blockStartTime + spamCoolDown)
		{
			blockStartTime = time;
			return false;
		}
		return base.CheckCallTime(time);
	}
}
[Serializable]
public class CallLimitersList<Titem, Tenum> where Titem : CallLimiter, new() where Tenum : Enum
{
	[RequiredListLength("GetMaxLength")]
