	private static void DeserializePlayerLaunched(object[] data, PhotonMessageInfoWrapped info)
	{
		MonkeAgent.IncrementRPCCall(info, "DeserializePlayerLaunched");
		GorillaGameManager activeGameMode = GorillaGameModes.GameMode.ActiveGameMode;
		if ((object)activeGameMode != null && activeGameMode.GameType() == GameModeType.Guardian && info.Sender == NetworkSystem.Instance.MasterClient && data[0] is UnityEngine.Vector3 v && v.IsValid(10000f) && !(v.magnitude > 20f) && playerLaunchedCallLimiter.CheckCallTime(Time.time))
		{
			GTPlayer.Instance.DoLaunch(v);
		}
	}

	internal static void HitPlayer(NetPlayer player, UnityEngine.Vector3 direction, float strength)
	{
