public class AutoCatchThrowBall : MonoBehaviour
{
	private struct HeldBall
	{
		public bool held;

		public float catchTime;

		public float throwTime;

		public TransferrableObject transferrable;
	}

	public GameObject ballPrefab;

	public float throwPitch = 20f;

	public float throwSpeed = 5f;

	public float throwWaitTime = 1f;

	public float catchWaitTime = 0.2f;

	public LayerMask ballLayer;

	private VRRig vrRig;

	private Collider[] overlapResults = new Collider[32];

	private List<HeldBall> heldBalls = new List<HeldBall>();

	private void Start()
	{
		vrRig = GetComponent<VRRig>();
	}

	private void Update()
	{
		float time = Time.time;
		UnityEngine.Vector3 vector = vrRig.transform.position + vrRig.transform.forward * 0.5f;
		UnityEngine.Quaternion quaternion2 = vrRig.transform.rotation * UnityEngine.Quaternion.AngleAxis(0f - throwPitch, UnityEngine.Vector3.right);
		UnityEngine.Vector3 center = vector - quaternion2 * UnityEngine.Vector3.forward * 0.5f;
		int num = Physics.OverlapBoxNonAlloc(center, UnityEngine.Vector3.one * 0.5f, overlapResults, quaternion2);
		DebugUtil.DrawBox(center, quaternion2, UnityEngine.Vector3.one, Color.green);
		for (int i = 0; i < num; i++)
		{
			Collider collider = overlapResults[i];
			TransferrableObject componentInParent = collider.gameObject.GetComponentInParent<TransferrableObject>();
			if (!(componentInParent != null))
			{
				continue;
			}
			bool flag = false;
			for (int j = 0; j < heldBalls.Count; j++)
			{
				if (componentInParent == heldBalls[j].transferrable)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.Log($"Catching {componentInParent.gameObject.name} in from collider {collider.gameObject.name} at position {componentInParent.transform.position}");
				for (int k = 0; k < heldBalls.Count; k++)
				{
				}
				heldBalls.Add(new HeldBall
				{
					held = true,
					catchTime = time,
					transferrable = componentInParent
				});
				componentInParent.OnGrab(null, null);
				componentInParent.currentState = TransferrableObject.PositionState.InRightHand;
			}
		}
		for (int num2 = heldBalls.Count - 1; num2 >= 0; num2--)
		{
			HeldBall value = heldBalls[num2];
			if (value.held)
			{
				value.transferrable.transform.position = vector;
				if (time > value.catchTime + throwWaitTime)
				{
					Throw(value.transferrable, quaternion2 * UnityEngine.Vector3.forward);
					value.held = false;
					value.throwTime = time;
					heldBalls[num2] = value;
				}
			}
			else if (time > value.throwTime + catchWaitTime)
			{
				UnityEngine.Debug.Log("Removing " + value.transferrable.gameObject.name);
				heldBalls.RemoveAt(num2);
				for (int l = 0; l < heldBalls.Count; l++)
				{
				}
			}
		}
		if (!TestScript.IsUIOpen && Keyboard.current.tKey.wasPressedThisFrame && ballPrefab != null)
		{
			TransferrableObject componentInChildren = UnityEngine.Object.Instantiate(ballPrefab, vector, UnityEngine.Quaternion.identity, null).GetComponentInChildren<TransferrableObject>();
			componentInChildren.OnGrab(null, null);
			componentInChildren.currentState = TransferrableObject.PositionState.InRightHand;
			Throw(componentInChildren, quaternion2 * UnityEngine.Vector3.forward);
		}
		DebugUtil.DrawRect(vector, quaternion2 * UnityEngine.Quaternion.AngleAxis(-90f, UnityEngine.Vector3.right), UnityEngine.Vector2.one, Color.green);
	}

	private void Throw(TransferrableObject transferrable, UnityEngine.Vector3 throwDir)
	{
		Rigidbody componentInChildren = transferrable.GetComponentInChildren<Rigidbody>();
		transferrable.OnRelease(null, null);
		transferrable.currentState = TransferrableObject.PositionState.Dropped;
		componentInChildren.isKinematic = false;
		componentInChildren.linearVelocity = throwDir * throwSpeed;
		UnityEngine.Debug.Log($"Throwing {transferrable.gameObject.name} in direction {throwDir} at position {transferrable.transform.position}");
	}
}
