[RequireComponent(typeof(AudioSource))]
public class AudioLooper : MonoBehaviour
{
	private AudioSource audioSource;

	[SerializeField]
	private AudioClip loopClip;

	[SerializeField]
	private AudioClip[] interjectionClips;

	[SerializeField]
	private float interjectionLikelyhood = 0.5f;

	protected virtual void Awake()
	{
		audioSource = GetComponent<AudioSource>();
	}

	private void Update()
	{
		if (!audioSource.isPlaying)
		{
			if (audioSource.clip == loopClip && interjectionClips.Length != 0 && UnityEngine.Random.value < interjectionLikelyhood)
			{
				audioSource.clip = interjectionClips[UnityEngine.Random.Range(0, interjectionClips.Length)];
			}
			else
			{
				audioSource.clip = loopClip;
			}
			audioSource.GTPlay();
		}
	}
}
public class AverageVector3
{
	public struct Sample
	{
		public float timeStamp;

		public UnityEngine.Vector3 value;
	}

	private List<Sample> samples = new List<Sample>();

	private float timeWindow = 0.1f;

	public AverageVector3(float averagingWindow = 0.1f)
	{
		timeWindow = averagingWindow;
	}

	public void AddSample(UnityEngine.Vector3 sample, float time)
	{
		samples.Add(new Sample
		{
			timeStamp = time,
			value = sample
		});
		RefreshSamples();
	}

	public UnityEngine.Vector3 GetAverage()
	{
		RefreshSamples();
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		for (int i = 0; i < samples.Count; i++)
		{
			zero += samples[i].value;
		}
		return zero / samples.Count;
	}

	public void Clear()
	{
		samples.Clear();
	}

	private void RefreshSamples()
	{
		float num = Time.time - timeWindow;
		for (int num2 = samples.Count - 1; num2 >= 0; num2--)
		{
			if (samples[num2].timeStamp < num)
			{
				samples.RemoveAt(num2);
			}
		}
	}
}
