public class BezierUtils
{
	public static UnityEngine.Vector3 BezierSolve(float t, UnityEngine.Vector3 startPos, UnityEngine.Vector3 ctrl1, UnityEngine.Vector3 ctrl2, UnityEngine.Vector3 endPos)
	{
		float num = 1f - t;
		float num2 = num * num * num;
		float num3 = 3f * num * num * t;
		float num4 = 3f * num * t * t;
		float num5 = t * t * t;
		return startPos * num2 + ctrl1 * num3 + ctrl2 * num4 + endPos * num5;
	}
}
