public interface ICallBack
{
	void CallBack();
}
internal class CallbackContainer<T> : ListProcessorAbstract<T> where T : ICallBack
{
	public CallbackContainer()
		: base(100)
	{
	}

	public CallbackContainer(int capacity)
		: base(capacity)
	{
	}

	public void TryRunCallbacks()
	{
		ProcessListSafe();
	}

	public void RunCallbacks()
	{
		ProcessList();
	}

	protected override void ProcessItem(in T item)
	{
		item.CallBack();
	}
}
public interface ICallbackUnique : ICallBack
{
	bool Registered { get; set; }
}
internal class CallbackContainerUnique<T> : CallbackContainer<T> where T : class, ICallbackUnique
{
	public CallbackContainerUnique()
		: base(10)
	{
	}

	public CallbackContainerUnique(int capacity)
		: base(capacity)
	{
	}

	public override void Add(in T item)
	{
		T val = item;
		if (!val.Registered)
		{
			base.Add(in item);
			val = item;
			val.Registered = true;
		}
	}

	public override bool Remove(in T item)
	{
		T val = item;
		if (!val.Registered)
		{
			return false;
		}
		base.Remove(in item);
		val = item;
		val.Registered = false;
		return true;
	}
}
internal class CircularBuffer<T>
{
	private T[] backingArray;

	private int nextWriteIdx;

	private int lastWriteIdx;

	public int Count { get; private set; }

	public int Capacity { get; private set; }

	public T this[int logicalIdx]
	{
		get
		{
			if (logicalIdx < 0 || logicalIdx >= Count)
			{
				throw new ArgumentOutOfRangeException("logicalIdx", logicalIdx, $"Out of bounds index {logicalIdx} into CircularBuffer with length {Count}");
			}
			int num = (lastWriteIdx + Capacity - logicalIdx) % Capacity;
			return backingArray[num];
		}
	}

	public CircularBuffer(int capacity)
	{
		backingArray = new T[capacity];
		Capacity = capacity;
		Count = 0;
	}

	public void Add(T value)
	{
		backingArray[nextWriteIdx] = value;
		lastWriteIdx = nextWriteIdx;
		nextWriteIdx = (nextWriteIdx + 1) % Capacity;
		if (Count < Capacity)
		{
			Count++;
		}
	}

	public void Clear()
	{
		Count = 0;
	}

	public T Last()
	{
		return backingArray[lastWriteIdx];
	}
}
public class CollisionEventNotifier : MonoBehaviour
{
	public delegate void CollisionEvent(CollisionEventNotifier notifier, UnityEngine.Collision collision);

	public event CollisionEvent CollisionEnterEvent;

	public event CollisionEvent CollisionExitEvent;

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		this.CollisionEnterEvent?.Invoke(this, collision);
	}

	private void OnCollisionExit(UnityEngine.Collision collision)
	{
		this.CollisionExitEvent?.Invoke(this, collision);
	}
}
public static class ColorUtils
{
	private const byte kMaxByteForOverexposedColor = 191;

	public static Color WithAlpha(this Color c, float alpha)
	{
		c.a = System.Math.Clamp(alpha, 0f, 1f);
		return c;
	}

	public static Color32 WithAlpha(this Color32 c, byte alpha)
	{
		c.a = alpha;
		return c;
	}

	public static Color ComposeHDR(Color baseColor, float intensity)
	{
		intensity = Mathf.Clamp(intensity, -10f, 10f);
		Color result = baseColor;
		if (baseColor.maxColorComponent > 1f)
		{
			result = DecomposeHDR(baseColor).baseColor;
		}
		float num = Mathf.Pow(2f, intensity);
		if (QualitySettings.activeColorSpace == ColorSpace.Linear)
		{
			num = Mathf.GammaToLinearSpace(intensity);
		}
		result *= num;
		result.a = baseColor.a;
		return result;
	}

	public static (Color baseColor, float intensity) DecomposeHDR(Color hdrColor)
	{
		Color32 color = default(Color32);
		float item = 0f;
		float maxColorComponent = hdrColor.maxColorComponent;
		if (maxColorComponent == 0f || (maxColorComponent <= 1f && maxColorComponent >= 0.003921569f))
		{
			color.r = (byte)Mathf.RoundToInt(hdrColor.r * 255f);
			color.g = (byte)Mathf.RoundToInt(hdrColor.g * 255f);
			color.b = (byte)Mathf.RoundToInt(hdrColor.b * 255f);
		}
		else
		{
			float num = 191f / maxColorComponent;
			item = Mathf.Log(255f / num) / Mathf.Log(2f);
			color.r = System.Math.Min((byte)191, (byte)Mathf.CeilToInt(num * hdrColor.r));
			color.g = System.Math.Min((byte)191, (byte)Mathf.CeilToInt(num * hdrColor.g));
			color.b = System.Math.Min((byte)191, (byte)Mathf.CeilToInt(num * hdrColor.b));
		}
		return (baseColor: color, intensity: item);
	}
}
public static class ComponentUtils
{
	private static readonly uint[] kHashBits = new uint[4];

	public static T EnsureComponent<T>(this UnityEngine.Component ctx, ref T target) where T : UnityEngine.Component
	{
		if (ctx.AsNull() == null)
		{
			return null;
		}
		if (target.AsNull() != null)
		{
			return target;
		}
		return target = ctx.GetComponent<T>();
	}

	public static bool TryEnsureComponent<T>(this UnityEngine.Component ctx, ref T target) where T : UnityEngine.Component
	{
		if (ctx.AsNull() == null)
		{
			return false;
		}
		if (target.AsNull() != null)
		{
			return true;
		}
		target = ctx.GetComponent<T>();
		return true;
	}

	public static T AddComponent<T>(this UnityEngine.Component c) where T : UnityEngine.Component
	{
		return c.gameObject.AddComponent<T>();
	}

	public static void GetOrAddComponent<T>(this UnityEngine.Component c, out T result) where T : UnityEngine.Component
	{
		if (!c.TryGetComponent<T>(out result))
		{
			result = c.gameObject.AddComponent<T>();
		}
	}

	public static bool GetComponentAndSetFieldIfNullElseLogAndDisable<T>(this UnityEngine.Behaviour c, ref T fieldRef, string fieldName, string fieldTypeName, string msgSuffix = "Disabling.", [CallerMemberName] string caller = "__UNKNOWN_CALLER__") where T : UnityEngine.Component
	{
		if (c.GetComponentAndSetFieldIfNullElseLog(ref fieldRef, fieldName, fieldTypeName, msgSuffix, caller))
		{
			return true;
		}
		c.enabled = false;
		return false;
	}

	public static bool GetComponentAndSetFieldIfNullElseLog<T>(this UnityEngine.Behaviour c, ref T fieldRef, string fieldName, string fieldTypeName, string msgSuffix = "", [CallerMemberName] string caller = "__UNKNOWN_CALLER__") where T : UnityEngine.Component
	{
		if (fieldRef != null)
		{
			return true;
		}
		fieldRef = c.GetComponent<T>();
		if (fieldRef != null)
		{
			return true;
		}
		UnityEngine.Debug.LogError(caller + ": Could not find " + fieldTypeName + " \"" + fieldName + "\" on \"" + c.name + "\". " + msgSuffix, c);
		return false;
	}

	public static bool DisableIfNull<T>(this UnityEngine.Behaviour c, T fieldRef, string fieldName, string fieldTypeName, [CallerMemberName] string caller = "__UNKNOWN_CALLER__") where T : UnityEngine.Object
	{
		if (fieldRef != null)
		{
			return true;
		}
		c.enabled = false;
		return false;
	}

	public static Hash128 ComputeStaticHash128(UnityEngine.Component c, string k)
	{
		return ComputeStaticHash128(c, StaticHash.Compute(k));
	}

	public static Hash128 ComputeStaticHash128(UnityEngine.Component c, int k = 0)
	{
		if (c == null)
		{
			return default(Hash128);
		}
		Transform transform = c.transform;
		UnityEngine.Component[] components = c.gameObject.GetComponents(typeof(UnityEngine.Component));
		uint[] array = kHashBits;
		int siblingIndex = transform.GetSiblingIndex();
		int num = components.Length;
		int i;
		for (i = 0; i < num && (object)c != components[i]; i++)
		{
		}
		int num2 = StaticHash.Compute(k + 2, 1);
		int num3 = StaticHash.Compute(siblingIndex + 4, num2);
		int num4 = StaticHash.Compute(num + 8, num3);
		int num5 = StaticHash.Compute(i + 16, num4);
		array[0] = (uint)num2;
		array[1] = (uint)num3;
		array[2] = (uint)num4;
		array[3] = (uint)num5;
		new SRand(StaticHash.Compute(num2, num3, num4, num5)).Shuffle(array);
		Hash128 outHash = new Hash128(array[0], array[1], array[2], array[3]);
		Hash128 inHash = Hash128.Compute(c.GetType().FullName);
		Hash128 inHash2 = TransformUtils.ComputePathHash(transform);
		Hash128 inHash3 = transform.localToWorldMatrix.QuantizedHash128();
		HashUtilities.AppendHash(ref inHash, ref outHash);
		HashUtilities.AppendHash(ref inHash2, ref outHash);
		HashUtilities.AppendHash(ref inHash3, ref outHash);
		return outHash;
	}
}
public class CompositeTriggerEvents : MonoBehaviour
{
	public delegate void TriggerEvent(Collider collider);

	[SerializeField]
	private List<Collider> individualTriggerColliders = new List<Collider>();

	private List<TriggerEventNotifier> triggerEventNotifiers = new List<TriggerEventNotifier>();

	private Dictionary<Collider, int> overlapMask = new Dictionary<Collider, int>();

	private Dictionary<Collider, int> CollderMasks => overlapMask;

	public event TriggerEvent CompositeTriggerEnter;

	public event TriggerEvent CompositeTriggerExit;

	private void Awake()
	{
		if (individualTriggerColliders.Count > 32)
		{
			UnityEngine.Debug.LogError("The max number of triggers was exceeded in this composite trigger event sender on GameObject: " + base.gameObject.name + ".");
		}
		for (int i = 0; i < individualTriggerColliders.Count; i++)
		{
			TriggerEventNotifier triggerEventNotifier = individualTriggerColliders[i].gameObject.AddComponent<TriggerEventNotifier>();
			triggerEventNotifier.maskIndex = i;
			triggerEventNotifier.TriggerEnterEvent += TriggerEnterReceiver;
			triggerEventNotifier.TriggerExitEvent += TriggerExitReceiver;
			triggerEventNotifiers.Add(triggerEventNotifier);
		}
	}

	public void AddCollider(Collider colliderToAdd)
	{
		if (individualTriggerColliders.Count >= 32)
		{
			UnityEngine.Debug.LogError("The max number of triggers are already present in this composite trigger event sender on GameObject: " + base.gameObject.name + ".");
			return;
		}
		individualTriggerColliders.Add(colliderToAdd);
		TriggerEventNotifier triggerEventNotifier = colliderToAdd.gameObject.AddComponent<TriggerEventNotifier>();
		triggerEventNotifier.maskIndex = GetNextMaskIndex();
		triggerEventNotifier.TriggerEnterEvent += TriggerEnterReceiver;
		triggerEventNotifier.TriggerExitEvent += TriggerExitReceiver;
		triggerEventNotifiers.Add(triggerEventNotifier);
		triggerEventNotifiers.Sort((TriggerEventNotifier a, TriggerEventNotifier b) => a.maskIndex.CompareTo(b.maskIndex));
	}

	public void RemoveCollider(Collider colliderToRemove)
	{
		TriggerEventNotifier component = colliderToRemove.gameObject.GetComponent<TriggerEventNotifier>();
		if (component.IsNotNull())
		{
			foreach (KeyValuePair<Collider, int> item in new Dictionary<Collider, int>(overlapMask))
			{
				TriggerExitReceiver(component, item.Key);
			}
			component.maskIndex = -1;
			component.TriggerEnterEvent -= TriggerEnterReceiver;
			component.TriggerExitEvent -= TriggerExitReceiver;
			triggerEventNotifiers.Remove(component);
		}
		individualTriggerColliders.Remove(colliderToRemove);
	}

	public void ResetColliders(bool sendExitEvent = true)
	{
		individualTriggerColliders.Clear();
		for (int num = triggerEventNotifiers.Count - 1; num >= 0; num--)
		{
			if (GTExt.IsNull(triggerEventNotifiers[num]))
			{
				triggerEventNotifiers.RemoveAt(num);
			}
			else
			{
				triggerEventNotifiers[num].maskIndex = -1;
				triggerEventNotifiers[num].TriggerEnterEvent -= TriggerEnterReceiver;
				triggerEventNotifiers[num].TriggerExitEvent -= TriggerExitReceiver;
				triggerEventNotifiers.RemoveAt(num);
			}
		}
		if (sendExitEvent)
		{
			foreach (KeyValuePair<Collider, int> item in overlapMask)
			{
				this.CompositeTriggerExit?.Invoke(item.Key);
			}
		}
		overlapMask.Clear();
	}

	public int GetNumColliders()
	{
		return individualTriggerColliders.Count;
	}

	public int GetNextMaskIndex()
	{
		if (individualTriggerColliders.Count >= 32)
		{
			UnityEngine.Debug.LogError("The max number of triggers are already present in this composite trigger event sender on GameObject: " + base.gameObject.name + ".");
			return -1;
		}
		int num = 0;
		for (int i = 0; i < triggerEventNotifiers.Count && triggerEventNotifiers[i].maskIndex == num; i++)
		{
			num++;
		}
		return num;
	}

	private void OnDestroy()
	{
		for (int i = 0; i < triggerEventNotifiers.Count; i++)
		{
			if (triggerEventNotifiers[i] != null)
			{
				triggerEventNotifiers[i].TriggerEnterEvent -= TriggerEnterReceiver;
				triggerEventNotifiers[i].TriggerExitEvent -= TriggerExitReceiver;
			}
		}
	}

	public void TriggerEnterReceiver(TriggerEventNotifier notifier, Collider other)
	{
		if (overlapMask.TryGetValue(other, out var value))
		{
			value = SetMaskIndexTrue(value, notifier.maskIndex);
			overlapMask[other] = value;
		}
		else
		{
			int value2 = SetMaskIndexTrue(0, notifier.maskIndex);
			overlapMask.Add(other, value2);
			this.CompositeTriggerEnter?.Invoke(other);
		}
	}

	public void TriggerExitReceiver(TriggerEventNotifier notifier, Collider other)
	{
		if (overlapMask.TryGetValue(other, out var value))
		{
			value = SetMaskIndexFalse(value, notifier.maskIndex);
			if (value == 0)
			{
				overlapMask.Remove(other);
				this.CompositeTriggerExit?.Invoke(other);
			}
			else
			{
				overlapMask[other] = value;
			}
		}
	}

	public void ResetColliderMask(Collider other)
	{
		if (overlapMask.TryGetValue(other, out var value))
		{
			if (value != 0)
			{
				this.CompositeTriggerExit?.Invoke(other);
			}
			overlapMask.Remove(other);
		}
	}

	public void CompositeTriggerEnterReceiver(Collider other)
	{
		this.CompositeTriggerEnter?.Invoke(other);
	}

	public void CompositeTriggerExitReceiver(Collider other)
	{
		this.CompositeTriggerExit?.Invoke(other);
	}

	private bool TestMaskIndex(int mask, int index)
	{
		return (mask & (1 << index)) != 0;
	}

	private int SetMaskIndexTrue(int mask, int index)
	{
		return mask | (1 << index);
	}

	private int SetMaskIndexFalse(int mask, int index)
	{
		return mask & ~(1 << index);
	}

	private string MaskToString(int mask)
	{
		string text = "";
		for (int num = 31; num >= 0; num--)
		{
			text += (TestMaskIndex(mask, num) ? "1" : "0");
		}
		return text;
	}
}
public class DebugHudStats : MonoBehaviour
{
	private enum State
	{
		Inactive,
		Active,
		ShowLog,
		ShowError,
		ShowStats,
		ShowRBs,
		timeAdjust,
		RecordingMode,
		TitleDataMonitor
	}

	public static int FPS_THRESHOLD = 89;

	private static DebugHudStats _instance;

	[SerializeField]
	public TMP_Text text;

	[SerializeField]
	public TMP_Text logging;

	[SerializeField]
	public TMP_Text logPage;

	[SerializeField]
	private TMP_Text fpsWarning;

	[SerializeField]
	private float delayUpdateRate = 0.25f;

	private float updateTimer;

	public float sessionAnytrackingLost;

	public float last30SecondsTrackingLost;

	private float firstAwake;

	private bool leftHandTracked;

	private bool rightHandTracked;

	private StringBuilder builder;

	private UnityEngine.Vector3 averagedVelocity;

	private UnityEngine.Vector3 groundVelocity;

	private UnityEngine.Vector3 centerHeadPos;

	private float distanceMoved;

	private float distanceSwam;

	private List<string> logMessage = new List<string>();

	private List<string> logError = new List<string>();

	private List<string> logTD = new List<string>();

	private bool buttonDown;

	private bool buttonDownBack;

	private bool spoofIds;

	private int lowFps;

	private string zones;

	private GroupJoinZoneAB lastGroupJoinZone;

	private State currentState = State.Active;

	private ProfilerRecorder drawCallsRecorder;

	private ProfilerRecorder trisRecorder;

	private string pLog;

	private bool button1Down;

	private bool button2Down;

	private bool button3Down;

	private bool button5Down;

	private bool button6Down;

	private bool button7Down;

	private bool button8Down;

	[SerializeField]
	private GorillaUtil.StringTable betaTitleDataOveride;

	private Array fixedWeathers;

	private int fixedWeatherIndex;

	public static DebugHudStats Instance => _instance;

	private void Awake()
	{
		if (_instance != null && _instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			_instance = this;
			fixedWeathers = Enum.GetValues(typeof(BetterDayNightManager.WeatherType));
		}
		base.gameObject.SetActive(value: false);
	}

	private void OnDestroy()
	{
		if (_instance == this)
		{
			_instance = null;
			if (drawCallsRecorder.Valid)
			{
				drawCallsRecorder.Dispose();
			}
			if (trisRecorder.Valid)
			{
				trisRecorder.Dispose();
			}
		}
	}

	private void LateUpdate()
	{
		if (GTPlayerTransform.Instance != null)
		{
			base.transform.LookAt(Camera.main.transform.position, GTPlayerTransform.Instance.GravityUp);
		}
		else
		{
			base.transform.LookAt(Camera.main.transform.position, UnityEngine.Vector3.up);
		}
		if (currentState == State.timeAdjust)
		{
			bool flag = ControllerInputPoller.PrimaryButtonPress(XRNode.RightHand);
			bool flag2 = ControllerInputPoller.SecondaryButtonPress(XRNode.RightHand);
			bool flag3 = ControllerInputPoller.TriggerFloat(XRNode.RightHand) > 0.5f;
			bool flag4 = ControllerInputPoller.GripFloat(XRNode.RightHand) > 0.5f;
			bool flag5 = ControllerInputPoller.Primary2DAxis(XRNode.LeftHand).x > 0.5f;
			bool flag6 = ControllerInputPoller.Primary2DAxis(XRNode.LeftHand).x < -0.5f;
			bool flag7 = ControllerInputPoller.Primary2DAxis(XRNode.LeftHand).y > 0.5f;
			bool flag8 = ControllerInputPoller.Primary2DAxis(XRNode.LeftHand).y < -0.5f;
			if (button1Down && !flag)
			{
				GorillaComputer.instance.AddSeverTime(flag4 ? (-60) : 60);
			}
			if (button2Down && !flag2)
			{
				GorillaComputer.instance.AddSeverTime(flag4 ? (-1) : 5);
			}
			if (button3Down && !flag3)
			{
				GorillaComputer.instance.AddSeverTime(flag4 ? (-1440) : 1440);
			}
			if (!button5Down && flag5)
			{
				ChangeTOD(1);
			}
			if (!button6Down && flag6)
			{
				ChangeTOD(-1);
			}
			if (!button7Down && flag7)
			{
				ChangeWeather(1);
			}
			if (!button8Down && flag8)
			{
				ChangeWeather(-1);
			}
			button1Down = flag;
			button2Down = flag2;
			button3Down = flag3;
			button5Down = flag5;
			button6Down = flag6;
			button7Down = flag7;
			button8Down = flag8;
		}
		if (currentState == State.TitleDataMonitor || currentState == State.ShowLog || currentState == State.ShowError)
		{
			bool flag9 = ControllerInputPoller.PrimaryButtonPress(XRNode.RightHand);
			bool flag10 = ControllerInputPoller.SecondaryButtonPress(XRNode.RightHand);
			if (button1Down && !flag9)
			{
				logging.pageToDisplay = ((logging.pageToDisplay >= logging.textInfo.pageCount) ? 1 : (logging.pageToDisplay + 1));
				updateLogTitle();
			}
			if (button2Down && !flag10)
			{
				logging.pageToDisplay = ((logging.pageToDisplay > 1) ? (logging.pageToDisplay - 1) : logging.textInfo.pageCount);
				updateLogTitle();
			}
			button1Down = flag9;
			button2Down = flag10;
		}
		bool flag11 = ControllerInputPoller.SecondaryButtonPress(XRNode.LeftHand);
		bool flag12 = ControllerInputPoller.PrimaryButtonPress(XRNode.LeftHand);
		if ((buttonDown && !flag11) || (buttonDownBack && !flag12))
		{
			NextState(buttonDown);
			if (currentState == State.ShowStats)
			{
				distanceMoved = (distanceSwam = 0f);
				PlayerGameEvents.OnPlayerMoved += OnPlayerMoved;
				PlayerGameEvents.OnPlayerSwam += OnPlayerSwam;
			}
			text.gameObject.SetActive(currentState != State.Inactive);
			if (RigidbodyHighlighter.Instance != null)
			{
				RigidbodyHighlighter.Instance.Active = currentState == State.ShowRBs;
			}
		}
		buttonDown = flag11;
		buttonDownBack = flag12;
		if (firstAwake == 0f)
		{
			firstAwake = Time.time;
		}
		if (updateTimer < delayUpdateRate)
		{
			updateTimer += Time.deltaTime;
			return;
		}
		int num = Mathf.RoundToInt(1f / Time.smoothDeltaTime);
		if (num < FPS_THRESHOLD)
		{
			lowFps++;
		}
		else
		{
			lowFps = 0;
		}
		fpsWarning.gameObject.SetActive(lowFps > 5 && currentState == State.Inactive);
		if (currentState != State.Inactive)
		{
			builder.Clear();
			builder.Append("gt: ");
			builder.Append(GorillaComputer.instance.version);
			builder.Append(":");
			builder.Append(GorillaComputer.instance.buildCode);
			builder.AppendLine(spoofIds ? " <color=\"red\">*Spoofing IDs*</color>" : string.Empty);
			num = Mathf.Min(num, 90);
			builder.Append((num < FPS_THRESHOLD) ? "<color=\"red\">" : "<color=\"white\">");
			builder.Append(num);
			builder.Append($" fps / {FPS_THRESHOLD + 1} fps</color> ");
			builder.AppendLine($"sfps: {GorillaTagger.Instance.SmoothedFramerate} (Health: {GorillaTagger.Instance.FramerateHealth})");
			float eyeTextureResolutionScale = XRSettings.eyeTextureResolutionScale;
			float renderViewportScale = XRSettings.renderViewportScale;
			float renderScale = (GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset).renderScale;
			builder.AppendLine($"draw calls: {drawCallsRecorder.LastValue} tris: {trisRecorder.LastValue} " + $"rs: {eyeTextureResolutionScale}/{renderViewportScale}/{renderScale} ");
			if (GorillaComputer.instance != null)
			{
				DateTime serverTime = GorillaComputer.instance.GetServerTime();
				builder.AppendLine(string.Format("<color={0}>{1}</color>", (serverTime.Year > 2020) ? "#00FFAA" : "#FF3333", serverTime));
			}
			else
			{
				builder.AppendLine("<color=#FF3333>Server Time Unavailable</color>");
			}
			ZoneDef currentNode = GorillaTagger.Instance.offlineVRRig.zoneEntity.currentNode;
			if (currentNode != null)
			{
				zones = $"{currentNode.gameObject.name.ToUpperInvariant()}/{currentNode.zoneId}/{currentNode.subZoneId}";
			}
			if (NetworkSystem.Instance.IsMasterClient)
			{
				builder.Append("H");
			}
			if (NetworkSystem.Instance.InRoom)
			{
				if (NetworkSystem.Instance.SessionIsPrivate)
				{
					builder.Append("Pri ");
				}
				else
				{
					builder.Append("Pub ");
				}
			}
			else
			{
				builder.Append("DC ");
			}
			builder.Append("z: <color=\"green\">");
			builder.Append(zones);
			builder.AppendLine("</color>");
			if (NetworkSystem.Instance.InRoom)
			{
				GorillaGameManager instance = GorillaGameManager.instance;
				if (instance != null)
				{
					GorillaTagCompetitiveManager gorillaTagCompetitiveManager = instance as GorillaTagCompetitiveManager;
					if (gorillaTagCompetitiveManager != null)
					{
						builder.Append("Ranked Mode ELO: ");
						builder.Append(gorillaTagCompetitiveManager.GetScoring().Progression.GetEloScore().ToString());
						builder.Append("  Tier: ");
						builder.AppendLine(gorillaTagCompetitiveManager.GetScoring().Progression.GetRankedProgressionTierName());
						RankedMultiplayerScore.PlayerScoreInRound inGameScoreForSelf = gorillaTagCompetitiveManager.GetScoring().GetInGameScoreForSelf();
						builder.Append("Tags: ");
						builder.Append(inGameScoreForSelf.NumTags.ToString());
						builder.Append("  Defense: ");
						builder.Append(Mathf.RoundToInt(inGameScoreForSelf.PointsOnDefense).ToString());
						builder.Append("  Score: ");
						builder.AppendLine(Mathf.RoundToInt(gorillaTagCompetitiveManager.GetScoring().ComputeGameScore(inGameScoreForSelf.NumTags, inGameScoreForSelf.PointsOnDefense)).ToString());
						if (gorillaTagCompetitiveManager.ShowDebugPing)
						{
							builder.AppendLine("Server MatchID Ping!");
						}
					}
				}
			}
			switch (currentState)
			{
			case State.ShowStats:
			{
				builder.AppendLine("\nStats:\n");
				UnityEngine.Vector3 vector = GTPlayer.Instance.AveragedVelocity;
				UnityEngine.Vector3 headCenterPosition = GTPlayer.Instance.HeadCenterPosition;
				float magnitude = vector.magnitude;
				groundVelocity = vector;
				groundVelocity.y = 0f;
				builder.AppendLine($"v: {magnitude:F1} m/s\t\todo: {distanceMoved:F2}m\tswam: {distanceSwam:F2}m");
				builder.AppendLine($"ground: {groundVelocity.magnitude:F1} m/s\thead: {headCenterPosition:F2}");
				break;
			}
			case State.timeAdjust:
				builder.AppendLine("\nAdjust Time\n");
				builder.AppendLine("Press [A] to advance one hour [+ R Grip to go back one hour]");
				builder.AppendLine("Press [B] to advance five minutes [+ R Grip to go back one minute]");
				builder.AppendLine("Press [R] Trigger to advance one day [+ R Grip to go back one day]");
				builder.AppendLine($"\nAdjust Environment {BetterDayNightManager.instance.currentTimeIndex + 1}/{BetterDayNightManager.instance.timeOfDayRange.Length} : {BetterDayNightManager.instance.CurrentWeather()} \n");
				builder.AppendLine("[L STICK L/R] to change Time Of Day. [L STICK U/D] to change Weather.");
				break;
			case State.RecordingMode:
				builder.AppendLine("\nMo-Cap Recording:\n");
				break;
			case State.ShowRBs:
				builder.AppendLine("\nRigid Body Locator\n");
				break;
			}
			text.text = builder.ToString();
		}
		updateTimer = 0f;
	}

	private void ChangeTOD(int v)
	{
		int num = (BetterDayNightManager.instance.currentTimeIndex + BetterDayNightManager.instance.timeOfDayRange.Length + v) % BetterDayNightManager.instance.timeOfDayRange.Length;
		BetterDayNightManager.instance.SetTimeOfDay(num);
		BetterDayNightManager.instance.SetOverrideIndex(num);
		BetterDayNightManager.instance.SetFixedWeather((BetterDayNightManager.WeatherType)fixedWeathers.GetValue(fixedWeatherIndex));
	}

	private void ChangeWeather(int v)
	{
		fixedWeatherIndex = (fixedWeatherIndex + fixedWeathers.Length + v) % fixedWeathers.Length;
		BetterDayNightManager.instance.SetFixedWeather((BetterDayNightManager.WeatherType)fixedWeathers.GetValue(fixedWeatherIndex));
	}

	private void NextState(bool fwd)
	{
		PlayerGameEvents.OnPlayerMoved -= OnPlayerMoved;
		PlayerGameEvents.OnPlayerSwam -= OnPlayerSwam;
		logging.gameObject.SetActive(value: false);
		logging.pageToDisplay = 1;
		if (currentState == State.timeAdjust)
		{
			BetterDayNightManager.instance.ClearFixedWeather();
		}
		switch (currentState)
		{
		case State.Inactive:
			currentState = (fwd ? State.Active : State.timeAdjust);
			break;
		case State.Active:
			currentState = (fwd ? State.ShowLog : State.Inactive);
			break;
		case State.ShowLog:
			currentState = ((!fwd) ? State.Active : State.ShowError);
			break;
		case State.ShowError:
			currentState = (fwd ? State.ShowStats : State.ShowLog);
			break;
		case State.ShowStats:
			currentState = (fwd ? State.ShowRBs : State.ShowError);
			break;
		case State.ShowRBs:
			currentState = (fwd ? State.TitleDataMonitor : State.ShowStats);
			break;
		case State.TitleDataMonitor:
			currentState = (fwd ? State.timeAdjust : State.ShowRBs);
			break;
		case State.timeAdjust:
			currentState = ((!fwd) ? State.TitleDataMonitor : State.Inactive);
			break;
		case State.RecordingMode:
			currentState = ((!fwd) ? State.timeAdjust : State.Inactive);
			break;
		}
		if (currentState == State.timeAdjust)
		{
			BetterDayNightManager.instance.SetFixedWeather((BetterDayNightManager.WeatherType)fixedWeathers.GetValue(fixedWeatherIndex));
		}
		UpdateLog();
	}

	private void DisplayLog(List<string> log)
	{
		logging.gameObject.SetActive(value: true);
		logging.text = string.Empty;
		for (int num = log.Count - 1; num >= 0; num--)
		{
			TMP_Text tMP_Text = logging;
			tMP_Text.text = tMP_Text.text + log[num] + "\n";
		}
		updateLogTitle();
	}

	private async void updateLogTitle()
	{
		await Task.Yield();
		logPage.text = $"{logTitleFromState(currentState)} <<[B] turn page [A]>> ({logging.pageToDisplay}/{logging.textInfo.pageCount})";
	}

	private string logTitleFromState(State s)
	{
		return s switch
		{
			State.ShowLog => "Debug Log", 
			State.ShowError => "Error Log", 
			State.TitleDataMonitor => "Title Data Log", 
			_ => string.Empty, 
		};
	}

	private string colorFromState(State s)
	{
		return s switch
		{
			State.ShowStats => "\"green\"", 
			State.ShowLog => "\"yellow\"", 
			State.ShowError => "\"orange\"", 
			State.ShowRBs => "\"red\"", 
			State.RecordingMode => "\"purple\"", 
			State.TitleDataMonitor => "#00ffff", 
			_ => "#ffffff", 
		};
	}

	private void OnPlayerSwam(float distance, float speed)
	{
		if (distance > 0.005f)
		{
			distanceSwam += distance;
		}
	}

	private void OnPlayerMoved(float distance, float speed)
	{
		if (distance > 0.005f)
		{
			distanceMoved += distance;
		}
	}

	private void OnEnable()
	{
		UnityEngine.Application.logMessageReceived += LogMessageReceived;
		PlayFabTitleDataCache.OnValueRetieved = (Action<string, string>)Delegate.Combine(PlayFabTitleDataCache.OnValueRetieved, new Action<string, string>(TDValueRetrieved));
		PlayFabTitleDataCache.OnCachedValueRetieved = (Action<string, string>)Delegate.Combine(PlayFabTitleDataCache.OnCachedValueRetieved, new Action<string, string>(TDCachedValueRetrieved));
	}

	private void TDValueRetrieved(string arg1, string arg2)
	{
		logTD.Add($" >{Time.realtimeSinceStartup:F2}> TitleData[ <color=#ffaaff>{arg1}</color> ] = {arg2}");
		if (logTD.Count > 1000)
		{
			logTD.RemoveAt(0);
		}
		UpdateLog();
	}

	private void TDCachedValueRetrieved(string arg1, string arg2)
	{
		logTD.Add($" >{Time.realtimeSinceStartup:F2}> TitleData[ <color=#00ffff>{arg1}</color> ] = {arg2}");
		if (logTD.Count > 1000)
		{
			logTD.RemoveAt(0);
		}
		UpdateLog();
	}

	private void OnDisable()
	{
		PlayFabTitleDataCache.OnValueRetieved = (Action<string, string>)Delegate.Remove(PlayFabTitleDataCache.OnValueRetieved, new Action<string, string>(TDValueRetrieved));
		PlayFabTitleDataCache.OnCachedValueRetieved = (Action<string, string>)Delegate.Remove(PlayFabTitleDataCache.OnCachedValueRetieved, new Action<string, string>(TDCachedValueRetrieved));
		UnityEngine.Application.logMessageReceived -= LogMessageReceived;
	}

	private void LogMessageReceived(string condition, string stackTrace, UnityEngine.LogType type)
	{
		string text = $" >{Time.realtimeSinceStartup:F2}> {getColorStringFromLogType(type)}{condition}</color>";
		if (pLog != condition)
		{
			logMessage.Add(text);
		}
		else
		{
			logMessage[logMessage.Count - 1] = text;
		}
		pLog = condition;
		if (logMessage.Count > 100)
		{
			logMessage.RemoveAt(0);
		}
		if (type == UnityEngine.LogType.Error || type == UnityEngine.LogType.Assert || type == UnityEngine.LogType.Exception)
		{
			logError.Add(text + "\n" + stackTrace);
			if (logError.Count > 100)
			{
				logError.RemoveAt(0);
			}
		}
		UpdateLog();
	}

	private void UpdateLog()
	{
		switch (currentState)
		{
		case State.ShowLog:
			DisplayLog(logMessage);
			break;
		case State.ShowError:
			DisplayLog(logError);
			break;
		case State.TitleDataMonitor:
			DisplayLog(logTD);
			break;
		}
	}

	private string getColorStringFromLogType(UnityEngine.LogType type)
	{
		switch (type)
		{
		case UnityEngine.LogType.Error:
		case UnityEngine.LogType.Assert:
		case UnityEngine.LogType.Exception:
			return "<color=\"red\">";
		case UnityEngine.LogType.Warning:
			return "<color=\"yellow\">";
		default:
			return "<color=\"white\">";
		}
	}

	private void OnZoneChanged(ZoneData[] zoneData)
	{
		zones = string.Empty;
		for (int i = 0; i < zoneData.Length; i++)
		{
			if (zoneData[i].active)
			{
				zones = zones + zoneData[i].zone.ToString().ToUpper() + "; ";
			}
		}
	}
}
