public static class DictRefTypeUtils
{
	public static void TryGetOrAdd<TKey, TValue>(this Dictionary<TKey, TValue> dict, TKey key, out TValue value) where TValue : class, new()
	{
		if (!dict.TryGetValue(key, out value) || value == null)
		{
			value = new TValue();
			dict.Add(key, value);
		}
	}
}
public static class DictValueTypeUtils
{
	public static void TryGetOrAdd<TKey, TValue>(this Dictionary<TKey, TValue> dict, TKey key, out TValue value) where TValue : struct
	{
		if (!dict.TryGetValue(key, out value))
		{
			value = default(TValue);
			dict.Add(key, value);
		}
	}
}
public static class DictArrayUtils
{
	public static void TryGetOrAddList<TKey, TValue>(this Dictionary<TKey, List<TValue>> dict, TKey key, out List<TValue> list, int capacity)
	{
		if (!dict.TryGetValue(key, out list) || list == null)
		{
			list = new List<TValue>(capacity);
			dict.Add(key, list);
		}
	}

	public static void TryGetOrAddArray<TKey, TValue>(this Dictionary<TKey, TValue[]> dict, TKey key, out TValue[] array, int size)
	{
		if (!dict.TryGetValue(key, out array) || array == null)
		{
			array = new TValue[size];
			dict.Add(key, array);
		}
	}
}
