public static class JsonUtils
{
	public static string ToJson<T>(this T obj, bool indent = true)
	{
		return JsonConvert.SerializeObject(obj, indent ? Formatting.Indented : Formatting.None);
	}

	public static T FromJson<T>(this string s)
	{
		return JsonConvert.DeserializeObject<T>(s);
	}

	public static string JsonSerializeEventData<T>(this T obj)
	{
		JsonSerializerSettings jsonSerializerSettings = new JsonSerializerSettings
		{
			TypeNameHandling = TypeNameHandling.All,
			CheckAdditionalContent = true,
			Formatting = Formatting.None
		};
		jsonSerializerSettings.Converters.Add(new Vector3Converter());
		return JsonConvert.SerializeObject(obj, jsonSerializerSettings);
	}

	public static T JsonDeserializeEventData<T>(this string s)
	{
		JsonSerializerSettings jsonSerializerSettings = new JsonSerializerSettings
		{
			TypeNameHandling = TypeNameHandling.All
		};
		jsonSerializerSettings.Converters.Add(new Vector3Converter());
		return JsonConvert.DeserializeObject<T>(s, jsonSerializerSettings);
	}
}
public class Vector3Converter : JsonConverter
{
	public override void WriteJson(Newtonsoft.Json.JsonWriter writer, object value, JsonSerializer serializer)
	{
		UnityEngine.Vector3 vector = (UnityEngine.Vector3)value;
		writer.WriteStartObject();
		writer.WritePropertyName("x");
		writer.WriteValue(vector.x);
		writer.WritePropertyName("y");
		writer.WriteValue(vector.y);
		writer.WritePropertyName("z");
		writer.WriteValue(vector.z);
		writer.WriteEndObject();
	}

	public override object ReadJson(Newtonsoft.Json.JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer)
	{
		JObject jObject = JObject.Load(reader);
		return new UnityEngine.Vector3((float)jObject["x"], (float)jObject["y"], (float)jObject["z"]);
	}

	public override bool CanConvert(Type objectType)
	{
		return objectType == typeof(UnityEngine.Vector3);
	}
}
public static class LinqUtils
{
	public static IEnumerable<TResult> SelectManyNullSafe<TSource, TResult>(this IEnumerable<TSource> sources, Func<TSource, IEnumerable<TResult>> selector)
	{
		if (sources == null || selector == null)
		{
			yield break;
		}
		foreach (TSource source in sources)
		{
			if (source == null)
			{
				continue;
			}
			IEnumerable<TResult> enumerable = selector(source);
			foreach (TResult item in enumerable)
			{
				if (item != null)
				{
					yield return item;
				}
			}
		}
	}

	public static IEnumerable<TSource> DistinctBy<TSource, TResult>(this IEnumerable<TSource> source, Func<TSource, TResult> selector)
	{
		HashSet<TResult> set = new HashSet<TResult>();
		foreach (TSource item2 in source)
		{
			TResult item = selector(item2);
			if (set.Add(item))
			{
				yield return item2;
			}
		}
	}

	public static IEnumerable<T> ForEach<T>(this IEnumerable<T> source, Action<T> action)
	{
		foreach (T item in source)
		{
			action(item);
		}
		return source;
	}

	public static T[] AsArray<T>(this IEnumerable<T> source)
	{
		return (T[])source;
	}

	public static List<T> AsList<T>(this IEnumerable<T> source)
	{
		return (List<T>)source;
	}

	public static IList<T> Transform<T>(this IList<T> list, Func<T, T> action)
	{
		for (int i = 0; i < list.Count; i++)
		{
			list[i] = action(list[i]);
		}
		return list;
	}

	public static IEnumerable<T> Self<T>(this T value)
	{
		yield return value;
	}
}
