public class LoopingArray<T> : ObjectPoolEvents
{
	public class Pool : GorillaTag.ObjectPool<LoopingArray<T>>
	{
		private readonly int m_size;

		private Pool(int amount)
			: base(amount)
		{
		}

		public Pool(int size, int amount)
			: this(size, amount, amount)
		{
		}

		public Pool(int size, int initialAmount, int maxAmount)
		{
			m_size = size;
			InitializePool(initialAmount, maxAmount);
		}

		public override LoopingArray<T> CreateInstance()
		{
			return new LoopingArray<T>(m_size);
		}
	}

	private int m_length;

	private int m_currentIndex;

	private T[] m_array;

	public int Length => m_length;

	public int CurrentIndex => m_currentIndex;

	public T this[int index]
	{
		get
		{
			return m_array[index];
		}
		set
		{
			m_array[index] = value;
		}
	}

	public LoopingArray()
		: this(0)
	{
	}

	public LoopingArray(int capicity)
	{
		m_length = capicity;
		m_array = new T[capicity];
		Clear();
	}

	public int AddAndIncrement(in T value)
	{
		int currentIndex = m_currentIndex;
		m_array[m_currentIndex] = value;
		m_currentIndex = (m_currentIndex + 1) % m_length;
		return currentIndex;
	}

	public int IncrementAndAdd(in T value)
	{
		m_currentIndex = (m_currentIndex + 1) % m_length;
		m_array[m_currentIndex] = value;
		return m_currentIndex;
	}

	public void Clear()
	{
		m_currentIndex = 0;
		for (int i = 0; i < m_array.Length; i++)
		{
			m_array[i] = default(T);
		}
	}

	void ObjectPoolEvents.OnTaken()
	{
		Clear();
	}

	void ObjectPoolEvents.OnReturned()
	{
	}
}
[RequireComponent(typeof(MeshRenderer))]
public class MaterialUVOffsetListSetter : MonoBehaviour, IBuildValidation
{
	[SerializeField]
	private List<UnityEngine.Vector2> uvOffsetList = new List<UnityEngine.Vector2>();

	private MeshRenderer meshRenderer;

	private MaterialPropertyBlock matPropertyBlock;

	private void Awake()
	{
		matPropertyBlock = new MaterialPropertyBlock();
		meshRenderer = GetComponent<MeshRenderer>();
		meshRenderer.GetPropertyBlock(matPropertyBlock);
	}

	public void SetUVOffset(int listIndex)
	{
		if (listIndex >= uvOffsetList.Count || listIndex < 0)
		{
			UnityEngine.Debug.LogError("Invalid uv offset list index provided.");
		}
		else if (matPropertyBlock == null || meshRenderer == null)
		{
			UnityEngine.Debug.LogError("MaterialUVOffsetListSetter settings are incorrect somehow, please fix", base.gameObject);
			Awake();
		}
		else
		{
			UnityEngine.Vector2 vector = uvOffsetList[listIndex];
			matPropertyBlock.SetVector(ShaderProps._BaseMap_ST, new UnityEngine.Vector4(1f, 1f, vector.x, vector.y));
			meshRenderer.SetPropertyBlock(matPropertyBlock);
		}
	}

	public bool BuildValidationCheck()
	{
		if (GetComponent<MeshRenderer>() == null)
		{
			UnityEngine.Debug.LogError("missing a mesh renderer for the materialuvoffsetlistsetter", base.gameObject);
			return false;
		}
		if (GetComponentInParent<EdMeshCombinerMono>() != null && GetComponentInParent<EdDoNotMeshCombine>() == null)
		{
			UnityEngine.Debug.LogError("the meshrenderer is going to getcombined, that will likely cause issues for the materialuvoffsetlistsetter", base.gameObject);
			return false;
		}
		return true;
	}
}
public static class MathUtils
{
	private const float kDecay = 16f;

	public const float kFloatEpsilon = 1E-06f;

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float Xlerp(float a, float b, float dt, float decay = 16f)
	{
		return b + (a - b) * Mathf.Exp((0f - decay) * dt);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3 Xlerp(UnityEngine.Vector3 a, UnityEngine.Vector3 b, float dt, float decay = 16f)
	{
		return b + (a - b) * Mathf.Exp((0f - decay) * dt);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float SafeDivide(this float f, float d, float eps = 1E-06f)
	{
		if (System.Math.Abs(d) < eps)
		{
			return 0f;
		}
		if (float.IsNaN(f))
		{
			return 0f;
		}
		return f / d;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3 SafeDivide(this UnityEngine.Vector3 v, float d)
	{
		v.x = v.x.SafeDivide(d, 1E-05f);
		v.y = v.y.SafeDivide(d, 1E-05f);
		v.z = v.z.SafeDivide(d, 1E-05f);
		return v;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3 SafeDivide(this UnityEngine.Vector3 v, UnityEngine.Vector3 d)
	{
		v.x = v.x.SafeDivide(d.x, 1E-05f);
		v.y = v.y.SafeDivide(d.y, 1E-05f);
		v.z = v.z.SafeDivide(d.z, 1E-05f);
		return v;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float Saturate(this float f, float eps = 1E-06f)
	{
		return System.Math.Min(System.Math.Max(f, 0f), 1f - eps);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3 Sin(this UnityEngine.Vector3 v)
	{
		v.x = Mathf.Sin(v.x);
		v.y = Mathf.Sin(v.y);
		v.z = Mathf.Sin(v.z);
		return v;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float Quantize(this float f, float step)
	{
		return MathF.Round(f / step) * step;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approx(this UnityEngine.Quaternion a, UnityEngine.Quaternion b, float epsilon = 1E-06f)
	{
		return System.Math.Abs(UnityEngine.Quaternion.Dot(a, b)) > 1f - epsilon;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3[] BoxCorners(UnityEngine.Vector3 center, UnityEngine.Vector3 size)
	{
		UnityEngine.Vector3 vector = new UnityEngine.Vector3(size.x * 0.5f, 0f, 0f);
		UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(0f, size.y * 0.5f, 0f);
		UnityEngine.Vector3 vector3 = new UnityEngine.Vector3(0f, 0f, size.z * 0.5f);
		return new UnityEngine.Vector3[8]
		{
			center + vector + vector2 + vector3,
			center + vector + vector2 - vector3,
			center - vector + vector2 - vector3,
			center - vector + vector2 + vector3,
			center + vector - vector2 + vector3,
			center + vector - vector2 - vector3,
			center - vector - vector2 - vector3,
			center - vector - vector2 + vector3
		};
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static void BoxCornersNonAlloc(UnityEngine.Vector3 center, UnityEngine.Vector3 size, UnityEngine.Vector3[] array, int index = 0)
	{
		UnityEngine.Vector3 vector = new UnityEngine.Vector3(size.x * 0.5f, 0f, 0f);
		UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(0f, size.y * 0.5f, 0f);
		UnityEngine.Vector3 vector3 = new UnityEngine.Vector3(0f, 0f, size.z * 0.5f);
		array[index] = center + vector + vector2 + vector3;
		array[index + 1] = center + vector + vector2 - vector3;
		array[index + 2] = center - vector + vector2 - vector3;
		array[index + 3] = center - vector + vector2 + vector3;
		array[index + 4] = center + vector - vector2 + vector3;
		array[index + 5] = center + vector - vector2 - vector3;
		array[index + 6] = center - vector - vector2 - vector3;
		array[index + 7] = center - vector - vector2 + vector3;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3[] OrientedBoxCorners(UnityEngine.Vector3 center, UnityEngine.Vector3 size, UnityEngine.Quaternion angles)
	{
		UnityEngine.Vector3 vector = angles * new UnityEngine.Vector3(size.x * 0.5f, 0f, 0f);
		UnityEngine.Vector3 vector2 = angles * new UnityEngine.Vector3(0f, size.y * 0.5f, 0f);
		UnityEngine.Vector3 vector3 = angles * new UnityEngine.Vector3(0f, 0f, size.z * 0.5f);
		return new UnityEngine.Vector3[8]
		{
			center + vector + vector2 + vector3,
			center + vector + vector2 - vector3,
			center - vector + vector2 - vector3,
			center - vector + vector2 + vector3,
			center + vector - vector2 + vector3,
			center + vector - vector2 - vector3,
			center - vector - vector2 - vector3,
			center - vector - vector2 + vector3
		};
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static void OrientedBoxCornersNonAlloc(UnityEngine.Vector3 center, UnityEngine.Vector3 size, UnityEngine.Quaternion angles, UnityEngine.Vector3[] array, int index = 0)
	{
		UnityEngine.Vector3 vector = angles * new UnityEngine.Vector3(size.x * 0.5f, 0f, 0f);
		UnityEngine.Vector3 vector2 = angles * new UnityEngine.Vector3(0f, size.y * 0.5f, 0f);
		UnityEngine.Vector3 vector3 = angles * new UnityEngine.Vector3(0f, 0f, size.z * 0.5f);
		array[index] = center + vector + vector2 + vector3;
		array[index + 1] = center + vector + vector2 - vector3;
		array[index + 2] = center - vector + vector2 - vector3;
		array[index + 3] = center - vector + vector2 + vector3;
		array[index + 4] = center + vector - vector2 + vector3;
		array[index + 5] = center + vector - vector2 - vector3;
		array[index + 6] = center - vector - vector2 - vector3;
		array[index + 7] = center - vector - vector2 + vector3;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool OrientedBoxContains(UnityEngine.Vector3 point, UnityEngine.Vector3 boxCenter, UnityEngine.Vector3 boxSize, UnityEngine.Quaternion boxAngles)
	{
		UnityEngine.Vector3 vector = UnityEngine.Matrix4x4.TRS(boxCenter, boxAngles, UnityEngine.Vector3.one).inverse.MultiplyPoint3x4(point);
		UnityEngine.Vector3 vector2 = boxSize * 0.5f;
		vector.x = Mathf.Abs(vector.x);
		vector.y = Mathf.Abs(vector.y);
		vector.z = Mathf.Abs(vector.z);
		if (Mathf.Approximately(vector.x, vector2.x) && Mathf.Approximately(vector.y, vector2.y) && Mathf.Approximately(vector.z, vector2.z))
		{
			return true;
		}
		if (vector.x < vector2.x && vector.y < vector2.y && vector.z < vector2.z)
		{
			return true;
		}
		return false;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int OrientedBoxSphereOverlap(UnityEngine.Vector3 center, float radius, UnityEngine.Vector3 boxCenter, UnityEngine.Vector3 boxSize, UnityEngine.Quaternion boxAngles)
	{
		UnityEngine.Matrix4x4 matrix4x = UnityEngine.Matrix4x4.Inverse(UnityEngine.Matrix4x4.TRS(boxCenter, boxAngles, UnityEngine.Vector3.one));
		UnityEngine.Vector3 vector = boxSize * 0.5f;
		UnityEngine.Vector3 vector2 = matrix4x.MultiplyPoint3x4(center);
		UnityEngine.Vector3 vector3 = UnityEngine.Vector3.right * radius;
		float magnitude = matrix4x.MultiplyVector(vector3).magnitude;
		UnityEngine.Vector3 min = -vector;
		UnityEngine.Vector3 vector4 = vector2.Clamped(min, vector);
		if ((vector2 - vector4).sqrMagnitude > magnitude * magnitude)
		{
			return -1;
		}
		if (min.x + magnitude <= vector2.x && vector2.x <= vector.x - magnitude && vector.x - min.x > magnitude && min.y + magnitude <= vector2.y && vector2.y <= vector.y - magnitude && vector.y - min.y > magnitude && min.z + magnitude <= vector2.z && vector2.z <= vector.z - magnitude && vector.z - min.z > magnitude)
		{
			return 1;
		}
		return 0;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3 Clamp(ref UnityEngine.Vector3 v, ref UnityEngine.Vector3 min, ref UnityEngine.Vector3 max)
	{
		float x = v.x;
		x = ((x > max.x) ? max.x : x);
		x = ((x < min.x) ? min.x : x);
		float y = v.y;
		y = ((y > max.y) ? max.y : y);
		y = ((y < min.y) ? min.y : y);
		float z = v.z;
		z = ((z > max.z) ? max.z : z);
		z = ((z < min.z) ? min.z : z);
		return new UnityEngine.Vector3(x, y, z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static Bounds[] Subdivide(Bounds b, int x = 1, int y = 1, int z = 1)
	{
		if (x < 1)
		{
			x = 1;
		}
		if (y < 1)
		{
			y = 1;
		}
		if (z < 1)
		{
			z = 1;
		}
		int num = x * y * z;
		if (num == 1)
		{
			return new Bounds[1] { b };
		}
		UnityEngine.Vector3 size = b.size;
		float num2 = size.x * 0.5f;
		float num3 = size.y * 0.5f;
		float num4 = size.z * 0.5f;
		float num5 = size.x / (float)x;
		float num6 = size.y / (float)y;
		float num7 = size.z / (float)z;
		UnityEngine.Vector3 size2 = new UnityEngine.Vector3(num5, num6, num7);
		Bounds[] array = new Bounds[num];
		for (int i = 0; i < num; i++)
		{
			SpatialUtils.FlatIndexToXYZ(i, x, y, out var x2, out var y2, out var z2);
			float num8 = num5 * (float)x2;
			float num9 = num5 * (float)(x2 + 1);
			float x3 = (num8 + num9) * 0.5f - num2;
			float num10 = num6 * (float)y2;
			float num11 = num6 * (float)(y2 + 1);
			float y3 = (num10 + num11) * 0.5f - num3;
			float num12 = num7 * (float)z2;
			float num13 = num7 * (float)(z2 + 1);
			float z3 = (num12 + num13) * 0.5f - num4;
			array[i].center = new UnityEngine.Vector3(x3, y3, z3);
			array[i].size = size2;
		}
		return array;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float ClampToReal(this float f, float min, float max, float epsilon = 1E-06f)
	{
		if (float.IsNaN(f))
		{
			f = 0f;
		}
		if (float.IsNegativeInfinity(min))
		{
			min = float.MinValue;
		}
		if (float.IsPositiveInfinity(max))
		{
			max = float.MaxValue;
		}
		return f.ClampApprox(min, max, epsilon);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float ClampApprox(this float f, float min, float max, float epsilon = 1E-06f)
	{
		if (f < min || f.Approx(min, epsilon))
		{
			return min;
		}
		if (f > max || f.Approx(max, epsilon))
		{
			return max;
		}
		return f;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approx(this float a, float b, float epsilon = 1E-06f)
	{
		return System.Math.Abs(a - b) < epsilon;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approx1(this float a, float epsilon = 1E-06f)
	{
		return System.Math.Abs(a - 1f) < epsilon;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approx0(this float a, float epsilon = 1E-06f)
	{
		return System.Math.Abs(a) < epsilon;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float GetScaledRadius(float radius, UnityEngine.Vector3 scale)
	{
		float val = System.Math.Abs(scale.x);
		float val2 = System.Math.Abs(scale.y);
		float val3 = System.Math.Abs(scale.z);
		return System.Math.Max(System.Math.Abs(System.Math.Max(val, System.Math.Max(val2, val3)) * radius), 0f);
	}

	public static float Linear(float value, float min, float max, float newMin, float newMax)
	{
		float num = (value - min) / (max - min) * (newMax - newMin) + newMin;
		if (num < newMin)
		{
			return newMin;
		}
		if (num > newMax)
		{
			return newMax;
		}
		return num;
	}

	public static float LinearUnclamped(float value, float min, float max, float newMin, float newMax)
	{
		return (value - min) / (max - min) * (newMax - newMin) + newMin;
	}

	public static float GetCircleValue(float degrees)
	{
		if (degrees > 90f)
		{
			degrees -= 180f;
		}
		else if (degrees < -90f)
		{
			degrees += 180f;
		}
		if (degrees > 180f)
		{
			degrees -= 270f;
		}
		else if (degrees < -180f)
		{
			degrees += 270f;
		}
		return degrees / 90f;
	}

	public static UnityEngine.Vector3 WeightedMaxVector(UnityEngine.Vector3 a, UnityEngine.Vector3 b, float eps = 0.0001f)
	{
		float magnitude = a.magnitude;
		float magnitude2 = b.magnitude;
		if (magnitude < eps || magnitude2 < eps)
		{
			return UnityEngine.Vector3.zero;
		}
		_ = a / magnitude;
		_ = b / magnitude2;
		UnityEngine.Vector3 vector = a * (magnitude / (magnitude + magnitude2)) + b * (magnitude2 / (magnitude + magnitude2));
		float num = Mathf.Max(magnitude, magnitude2);
		return vector * num;
	}

	public static UnityEngine.Vector3 MatchMagnitudeInDirection(UnityEngine.Vector3 input, UnityEngine.Vector3 target, float eps = 0.0001f)
	{
		UnityEngine.Vector3 result = input;
		float magnitude = target.magnitude;
		if (magnitude > eps)
		{
			UnityEngine.Vector3 vector = target / magnitude;
			float num = UnityEngine.Vector3.Dot(input, vector);
			float num2 = magnitude - num;
			if (num2 > 0f)
			{
				result = input + num2 * vector;
			}
		}
		return result;
	}

	public static int CalculateAgeFromDateTime(DateTime Dob)
	{
		return new DateTime(DateTime.Now.Subtract(Dob).Ticks).Year - 1;
	}

	public static int PositiveModulo(this int x, int m)
	{
		int num = x % m;
		if (num >= 0)
		{
			return num;
		}
		return num + m;
	}

	public static float PositiveModulo(this float x, float m)
	{
		float num = x % m;
		if ((num < 0f && m > 0f) || (num > 0f && m < 0f))
		{
			num += m;
		}
		return num;
	}
}
public static class MatrixUtils
{
	public static void MultiplyXYZ3x4(ref UnityEngine.Matrix4x4 m, ref UnityEngine.Vector4 point)
	{
		float x = point.x;
		float y = point.y;
		float z = point.z;
		point.x = (float)((double)m.m00 * (double)x + (double)m.m01 * (double)y + (double)m.m02 * (double)z) + m.m03;
		point.y = (float)((double)m.m10 * (double)x + (double)m.m11 * (double)y + (double)m.m12 * (double)z) + m.m13;
		point.z = (float)((double)m.m20 * (double)x + (double)m.m21 * (double)y + (double)m.m22 * (double)z) + m.m23;
	}

	public static void MultiplyXYZ(ref UnityEngine.Matrix4x4 m, ref UnityEngine.Vector4 point)
	{
		float x = point.x;
		float y = point.y;
		float z = point.z;
		point.x = (float)((double)m.m00 * (double)x + (double)m.m01 * (double)y + (double)m.m02 * (double)z) + m.m03;
		point.y = (float)((double)m.m10 * (double)x + (double)m.m11 * (double)y + (double)m.m12 * (double)z) + m.m13;
		point.z = (float)((double)m.m20 * (double)x + (double)m.m21 * (double)y + (double)m.m22 * (double)z) + m.m23;
		float num = 1f / ((float)((double)m.m30 * (double)point.x + (double)m.m31 * (double)point.y + (double)m.m32 * (double)point.z) + m.m33);
		point.x *= num;
		point.y *= num;
		point.z *= num;
	}

	public static void Clear(ref UnityEngine.Matrix4x4 m)
	{
		m.m00 = 0f;
		m.m01 = 0f;
		m.m02 = 0f;
		m.m03 = 0f;
		m.m10 = 0f;
		m.m11 = 0f;
		m.m12 = 0f;
		m.m13 = 0f;
		m.m20 = 0f;
		m.m21 = 0f;
		m.m22 = 0f;
		m.m23 = 0f;
		m.m30 = 0f;
		m.m31 = 0f;
		m.m32 = 0f;
		m.m33 = 0f;
	}

	public static void Copy(ref UnityEngine.Matrix4x4 from, ref UnityEngine.Matrix4x4 to)
	{
		to.m00 = from.m00;
		to.m01 = from.m01;
		to.m02 = from.m02;
		to.m03 = from.m03;
		to.m10 = from.m10;
		to.m11 = from.m11;
		to.m12 = from.m12;
		to.m13 = from.m13;
		to.m20 = from.m20;
		to.m21 = from.m21;
		to.m22 = from.m22;
		to.m23 = from.m23;
		to.m30 = from.m30;
		to.m31 = from.m31;
		to.m32 = from.m32;
		to.m33 = from.m33;
	}
}
public static class MeshUtils
{
	public static Mesh CreateReadableMeshCopy(this Mesh sourceMesh)
	{
		Mesh mesh = new Mesh();
		mesh.indexFormat = sourceMesh.indexFormat;
		GraphicsBuffer vertexBuffer = sourceMesh.GetVertexBuffer(0);
		int num = vertexBuffer.stride * vertexBuffer.count;
		byte[] data = new byte[num];
		vertexBuffer.GetData(data);
		mesh.SetVertexBufferParams(sourceMesh.vertexCount, sourceMesh.GetVertexAttributes());
		mesh.SetVertexBufferData(data, 0, 0, num);
		vertexBuffer.Release();
		mesh.subMeshCount = sourceMesh.subMeshCount;
		GraphicsBuffer indexBuffer = sourceMesh.GetIndexBuffer();
		int num2 = indexBuffer.stride * indexBuffer.count;
		byte[] data2 = new byte[num2];
		indexBuffer.GetData(data2);
		mesh.SetIndexBufferParams(indexBuffer.count, sourceMesh.indexFormat);
		mesh.SetIndexBufferData(data2, 0, 0, num2);
		indexBuffer.Release();
		uint num3 = 0u;
		for (int i = 0; i < mesh.subMeshCount; i++)
		{
			uint indexCount = sourceMesh.GetIndexCount(i);
			mesh.SetSubMesh(i, new SubMeshDescriptor((int)num3, (int)indexCount));
			num3 += indexCount;
		}
		mesh.RecalculateNormals();
		mesh.RecalculateBounds();
		return mesh;
	}
}
internal class NetworkVector3
{
	private double lastSetNetTime;

	private UnityEngine.Vector3 _currentSyncTarget = UnityEngine.Vector3.zero;

	private UnityEngine.Vector3 distanceTraveled = UnityEngine.Vector3.zero;

	public UnityEngine.Vector3 CurrentSyncTarget => _currentSyncTarget;

	public void SetNewSyncTarget(UnityEngine.Vector3 newTarget)
	{
		UnityEngine.Vector3 v = CurrentSyncTarget;
		v.SetValueSafe(in newTarget);
		distanceTraveled = v - _currentSyncTarget;
		_currentSyncTarget = v;
		lastSetNetTime = PhotonNetwork.Time;
	}

	public UnityEngine.Vector3 GetPredictedFuture()
	{
		float num = (float)(PhotonNetwork.Time - lastSetNetTime) * (float)PhotonNetwork.SerializationRate;
		UnityEngine.Vector3 vector = distanceTraveled * num;
		return _currentSyncTarget + vector;
	}

	public void Reset()
	{
		_currentSyncTarget = UnityEngine.Vector3.zero;
		distanceTraveled = UnityEngine.Vector3.zero;
		lastSetNetTime = 0.0;
	}
}
