		Collider collider = null;
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			Collider collider2 = colliders[i];
			if (collider == null)
			{
				collider = collider2;
				if (collider != null)
				{
					result = collider.bounds;
					num++;
				}
			}
			else if (!(collider2 == null))
			{
				Bounds bounds = collider2.bounds;
				if (!(bounds.size == UnityEngine.Vector3.zero))
				{
					result.Encapsulate(bounds);
					num++;
				}
			}
		}
		return num > 0;
	}

	public static bool TryGetBounds(Transform x, out Bounds result, bool includeRenderers = true, bool includeColliders = true, bool fallbackToXforms = false)
	{
		result = default(Bounds);
		if (x == null)
		{
			return false;
		}
		bool flag = false;
		bool flag2 = false;
		if (includeRenderers)
		{
			flag = TryGetBounds(x.GetComponentsInChildren<Renderer>(), out var result2);
			if (flag)
			{
				result = result2;
			}
		}
		if (includeColliders)
		{
			flag2 = TryGetBounds(x.GetComponentsInChildren<Collider>(), out var result3);
			if (flag2)
			{
				if (flag)
				{
					result.Encapsulate(result3);
				}
				else
				{
					result = result3;
				}
			}
		}
		bool flag3 = flag || flag2;
		if (flag3 || !fallbackToXforms)
		{
			return flag3;
		}
		Transform[] componentsInChildren = x.GetComponentsInChildren<Transform>();
		result.center = componentsInChildren[0].position;
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			result.Encapsulate(componentsInChildren[i].position);
		}
		return true;
	}

	public static BoundingSphere GetRadialBounds(ref Bounds bounds, ref UnityEngine.Matrix4x4 xform)
	{
		UnityEngine.Vector3 center = bounds.center;
		UnityEngine.Vector3 extents = bounds.extents;
		UnityEngine.Vector3 vector = new UnityEngine.Vector3(extents.x, 0f, 0f);
		UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(0f, extents.y, 0f);
		UnityEngine.Vector3 vector3 = new UnityEngine.Vector3(0f, 0f, extents.z);
		UnityEngine.Vector3 vector4 = xform.MultiplyPoint(center + vector + vector2 + vector3);
		UnityEngine.Vector3 vector5 = xform.MultiplyPoint(center + vector + vector2 - vector3);
		UnityEngine.Vector3 vector6 = xform.MultiplyPoint(center - vector + vector2 - vector3);
		UnityEngine.Vector3 vector7 = xform.MultiplyPoint(center - vector + vector2 + vector3);
		UnityEngine.Vector3 vector8 = xform.MultiplyPoint(center + vector - vector2 + vector3);
		UnityEngine.Vector3 vector9 = xform.MultiplyPoint(center + vector - vector2 - vector3);
		UnityEngine.Vector3 vector10 = xform.MultiplyPoint(center - vector - vector2 - vector3);
		UnityEngine.Vector3 vector11 = xform.MultiplyPoint(center - vector - vector2 + vector3);
		UnityEngine.Vector3 vector12 = (vector4 + vector5 + vector6 + vector7 + vector8 + vector9 + vector10 + vector11) * 0.125f;
		float num = 0f;
		float num2 = 0f;
		num2 = DistSq(vector4, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector5, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector6, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector7, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector8, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector9, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector10, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		num2 = DistSq(vector11, vector12);
		if (num2 > num)
		{
			num = num2;
		}
		return new BoundingSphere(vector12, Mathf.Sqrt(num));
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private static float DistSq(UnityEngine.Vector3 a, UnityEngine.Vector3 b)
	{
		float num = b.x - a.x;
		float num2 = b.y - a.y;
		float num3 = b.z - a.z;
		return num * num + num2 * num2 + num3 * num3;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3[] GetCorners(this Bounds b)
	{
		return GetCorners(b.min, b.max);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3[] GetCorners(UnityEngine.Vector3 min, UnityEngine.Vector3 max)
	{
		return new UnityEngine.Vector3[8]
		{
			new UnityEngine.Vector3(min.x, max.y, max.z),
			new UnityEngine.Vector3(max.x, max.y, max.z),
			new UnityEngine.Vector3(max.x, min.y, max.z),
			new UnityEngine.Vector3(min.x, min.y, max.z),
			new UnityEngine.Vector3(min.x, max.y, min.z),
			new UnityEngine.Vector3(max.x, max.y, min.z),
			new UnityEngine.Vector3(max.x, min.y, min.z),
			new UnityEngine.Vector3(min.x, min.y, min.z)
		};
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static UnityEngine.Vector3[] GetCorners(this Bounds b, UnityEngine.Matrix4x4 transform)
	{
		UnityEngine.Vector3[] corners = b.GetCorners();
		for (int i = 0; i < corners.Length; i++)
		{
			corners[i] = transform.MultiplyPoint(corners[i]);
		}
		return corners;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static Bounds TransformedBy(this Bounds b, UnityEngine.Matrix4x4 transform)
	{
		UnityEngine.Vector3 position = transform.GetPosition();
		UnityEngine.Vector3 vector = transform.MultiplyVector(UnityEngine.Vector3.right);
		UnityEngine.Vector3 vector2 = transform.MultiplyVector(UnityEngine.Vector3.up);
		UnityEngine.Vector3 vector3 = transform.MultiplyVector(UnityEngine.Vector3.forward);
		UnityEngine.Vector3 min = b.min;
		UnityEngine.Vector3 max = b.max;
		UnityEngine.Vector3 lhs = vector * min.x;
		UnityEngine.Vector3 rhs = vector * max.x;
		UnityEngine.Vector3 lhs2 = vector2 * min.y;
		UnityEngine.Vector3 rhs2 = vector2 * max.y;
		UnityEngine.Vector3 lhs3 = vector3 * min.z;
		UnityEngine.Vector3 rhs3 = vector3 * max.z;
		b.SetMinMax(UnityEngine.Vector3.Min(lhs, rhs) + UnityEngine.Vector3.Min(lhs2, rhs2) + UnityEngine.Vector3.Min(lhs3, rhs3) + position, UnityEngine.Vector3.Max(lhs, rhs) + UnityEngine.Vector3.Max(lhs2, rhs2) + UnityEngine.Vector3.Max(lhs3, rhs3) + position);
		return b;
	}

	public static bool BoxIntersectsBox(ref Bounds a, ref Bounds b)
	{
		UnityEngine.Vector3 min = a.min;
		UnityEngine.Vector3 max = a.max;
		UnityEngine.Vector3 min2 = b.min;
		UnityEngine.Vector3 max2 = b.max;
		if (min.x > max2.x || min2.x > max.x)
		{
			return false;
		}
		if (min.y > max2.y || min2.y > max.y)
		{
			return false;
		}
		if (min.z > max2.z || min2.z > max.z)
		{
			return false;
		}
		return true;
	}

	public static void ComputeBoundingSphere2Pass(UnityEngine.Vector3[] points, out UnityEngine.Vector3 center, out float radius)
	{
		center = default(UnityEngine.Vector3);
		radius = 0f;
		if (!points.IsNullOrEmpty())
		{
			Bounds bounds = GeometryUtility.CalculateBounds(points, UnityEngine.Matrix4x4.identity);
			UnityEngine.Vector3 center2 = bounds.center;
			float num = (bounds.max - bounds.min).magnitude * 0.5f;
			if (num.Approx0())
			{
				num = 0f;
			}
			ComputeBoundingSphereRitter(points, out var center3, out var radius2);
			bool flag = num < radius2;
			center = (flag ? center2 : center3);
			radius = (flag ? num : radius2);
		}
	}

	public static void ComputeBoundingSphereRitter(UnityEngine.Vector3[] points, out UnityEngine.Vector3 center, out float radius)
	{
		center = default(UnityEngine.Vector3);
		radius = 0f;
		if (points.IsNullOrEmpty())
		{
			return;
		}
		UnityEngine.Vector3 vector = kMinVector;
		UnityEngine.Vector3 vector2 = kMinVector;
		UnityEngine.Vector3 vector3 = kMinVector;
		UnityEngine.Vector3 vector4 = kMaxVector;
		UnityEngine.Vector3 vector5 = kMaxVector;
		UnityEngine.Vector3 vector6 = kMaxVector;
		for (int i = 0; i < points.Length; i++)
		{
			UnityEngine.Vector3 vector7 = points[i];
			if (vector7.x < vector.x)
			{
				vector = vector7;
			}
			if (vector7.x > vector4.x)
			{
				vector4 = vector7;
			}
			if (vector7.y < vector2.y)
			{
				vector2 = vector7;
			}
			if (vector7.y > vector5.y)
			{
				vector5 = vector7;
			}
			if (vector7.z < vector3.z)
			{
				vector3 = vector7;
			}
			if (vector7.z > vector6.z)
			{
				vector6 = vector7;
			}
		}
		float num = vector4.x - vector.x;
		float num2 = vector4.y - vector.y;
		float num3 = vector4.z - vector.z;
		float num4 = num * num + num2 * num2 + num3 * num3;
		float num5 = vector5.x - vector2.x;
		num2 = vector5.y - vector2.y;
		num3 = vector5.z - vector2.z;
		float num6 = num5 * num5 + num2 * num2 + num3 * num3;
		float num7 = vector6.x - vector3.x;
		num2 = vector6.y - vector3.y;
		num3 = vector6.z - vector3.z;
		float num8 = num7 * num7 + num2 * num2 + num3 * num3;
		UnityEngine.Vector3 vector8 = vector;
		UnityEngine.Vector3 vector9 = vector4;
		float num9 = num4;
		if (num6 > num9)
		{
			num9 = num6;
			vector8 = vector2;
			vector9 = vector5;
		}
		if (num8 > num9)
		{
			vector8 = vector3;
			vector9 = vector6;
		}
		center = new UnityEngine.Vector3((vector8.x + vector9.x) * 0.5f, (vector8.y + vector9.y) * 0.5f, (vector8.z + vector9.z) * 0.5f);
		float num10 = vector9.x - center.x;
		num2 = vector9.y - center.y;
		num3 = vector9.z - center.z;
		float num11 = num10 * num10 + num2 * num2 + num3 * num3;
		radius = Mathf.Sqrt(num11);
		for (int j = 0; j < points.Length; j++)
		{
			UnityEngine.Vector3 vector10 = points[j];
			float num12 = vector10.x - center.x;
			num2 = vector10.y - center.y;
			num3 = vector10.z - center.z;
			float num13 = num12 * num12 + num2 * num2 + num3 * num3;
			if (!(num13 <= num11))
			{
				float num14 = Mathf.Sqrt(num13);
				radius = (radius + num14) * 0.5f;
				num11 = radius * radius;
				float num15 = num14 - radius;
				center.x = (radius * center.x + num15 * vector10.x) / num14;
				center.y = (radius * center.y + num15 * vector10.y) / num14;
				center.z = (radius * center.z + num15 * vector10.z) / num14;
			}
		}
	}
}
public static class Bezier
{
	public static UnityEngine.Vector3 GetPoint(UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, float t)
	{
		t = Mathf.Clamp01(t);
		float num = 1f - t;
		return num * num * p0 + 2f * num * t * p1 + t * t * p2;
	}

	public static UnityEngine.Vector3 GetFirstDerivative(UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, float t)
	{
		return 2f * (1f - t) * (p1 - p0) + 2f * t * (p2 - p1);
	}

	public static UnityEngine.Vector3 GetPoint(UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, UnityEngine.Vector3 p3, float t)
	{
		t = Mathf.Clamp01(t);
		float num = 1f - t;
		return num * num * num * p0 + 3f * num * num * t * p1 + 3f * num * t * t * p2 + t * t * t * p3;
	}

	public static UnityEngine.Vector3 GetFirstDerivative(UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, UnityEngine.Vector3 p3, float t)
	{
		t = Mathf.Clamp01(t);
		float num = 1f - t;
		return 3f * num * num * (p1 - p0) + 6f * num * t * (p2 - p1) + 3f * t * t * (p3 - p2);
	}
}
public enum BezierControlPointMode
{
	Free,
	Aligned,
	Mirrored
}
public class BezierCurve : MonoBehaviour
{
	public Transform referenceTransform;

	public UnityEngine.Vector3[] points;

	public UnityEngine.Vector3 GetPoint(float t)
	{
		UnityEngine.Vector3 vector = ((points.Length == 3) ? Bezier.GetPoint(points[0], points[1], points[2], t) : Bezier.GetPoint(points[0], points[1], points[2], points[3], t));
		if (!referenceTransform)
		{
			return vector;
		}
		return referenceTransform.TransformPoint(vector);
	}

	public UnityEngine.Vector3 GetVelocity(float t)
	{
		UnityEngine.Vector3 vector = ((points.Length == 3) ? Bezier.GetFirstDerivative(points[0], points[1], points[2], t) : Bezier.GetFirstDerivative(points[0], points[1], points[2], points[3], t));
		if (!referenceTransform)
		{
			return vector;
		}
		return referenceTransform.TransformPoint(vector) - referenceTransform.position;
	}

	public UnityEngine.Vector3 GetDirection(float t)
	{
		return GetVelocity(t).normalized;
	}

	public void Reset()
	{
		referenceTransform = base.transform;
		points = new UnityEngine.Vector3[4]
		{
			new UnityEngine.Vector3(1f, 0f, 0f),
			new UnityEngine.Vector3(2f, 0f, 0f),
			new UnityEngine.Vector3(3f, 0f, 0f),
			new UnityEngine.Vector3(4f, 0f, 0f)
		};
	}
}
public class BezierSpline : MonoBehaviour
{
	[SerializeField]
	private UnityEngine.Vector3[] points;

	[SerializeField]
	private BezierControlPointMode[] modes;

	[SerializeField]
	private bool loop;

	private float _totalArcLength;

	private float[] _timesTable;

	private float[] _lengthsTable;

	public bool Loop
	{
		get
		{
			return loop;
		}
		set
		{
			loop = value;
			if (value)
			{
				modes[modes.Length - 1] = modes[0];
				SetControlPoint(0, points[0]);
			}
		}
	}

	public int ControlPointCount => points.Length;

	public int CurveCount => (points.Length - 1) / 3;

	private void Awake()
	{
		float num = 0f;
		for (int i = 1; i < points.Length; i++)
		{
			num += (points[i] - points[i - 1]).magnitude;
		}
		int subdivisions = Mathf.RoundToInt(num / 0.1f);
		buildTimesLenghtsTables(subdivisions);
	}

	private void buildTimesLenghtsTables(int subdivisions)
	{
		_totalArcLength = 0f;
		float num = 1f / (float)subdivisions;
		_timesTable = new float[subdivisions];
		_lengthsTable = new float[subdivisions];
		UnityEngine.Vector3 b = GetPoint(0f);
		for (int i = 1; i <= subdivisions; i++)
		{
			float num2 = num * (float)i;
			UnityEngine.Vector3 point = GetPoint(num2);
			_totalArcLength += UnityEngine.Vector3.Distance(point, b);
			b = point;
			_timesTable[i - 1] = num2;
			_lengthsTable[i - 1] = _totalArcLength;
		}
	}

	private float getPathFromTime(float t)
	{
		if (float.IsNaN(_totalArcLength) || _totalArcLength == 0f)
		{
			return t;
		}
		if (t > 0f && t < 1f)
		{
			float num = _totalArcLength * t;
			float num2 = 0f;
			float num3 = 0f;
			float num4 = 0f;
			float num5 = 0f;
			int num6 = _lengthsTable.Length;
			for (int i = 0; i < num6; i++)
			{
				if (_lengthsTable[i] > num)
				{
					num4 = _timesTable[i];
					num5 = _lengthsTable[i];
					if (i > 0)
					{
						num3 = _lengthsTable[i - 1];
					}
					break;
				}
				num2 = _timesTable[i];
			}
			t = num2 + (num - num3) / (num5 - num3) * (num4 - num2);
		}
		if (t > 1f)
		{
			t = 1f;
		}
		else if (t < 0f)
		{
			t = 0f;
		}
		return t;
	}

	public void BuildSplineFromPoints(UnityEngine.Vector3[] newPoints, BezierControlPointMode[] newModes, bool isLoop)
	{
		points = newPoints;
		modes = newModes;
		loop = isLoop;
		float num = 0f;
		for (int i = 1; i < points.Length; i++)
		{
			num += (points[i] - points[i - 1]).magnitude;
		}
		int subdivisions = Mathf.RoundToInt(num / 0.1f);
		buildTimesLenghtsTables(subdivisions);
	}

	public UnityEngine.Vector3 GetControlPoint(int index)
	{
		return points[index];
	}

	public void SetControlPoint(int index, UnityEngine.Vector3 point)
	{
		if (index % 3 == 0)
		{
			UnityEngine.Vector3 vector = point - points[index];
			if (loop)
			{
				if (index == 0)
				{
					points[1] += vector;
					points[points.Length - 2] += vector;
					points[points.Length - 1] = point;
				}
				else if (index == points.Length - 1)
				{
					points[0] = point;
					points[1] += vector;
					points[index - 1] += vector;
				}
				else
				{
					points[index - 1] += vector;
					points[index + 1] += vector;
				}
			}
			else
			{
				if (index > 0)
				{
					points[index - 1] += vector;
				}
				if (index + 1 < points.Length)
				{
					points[index + 1] += vector;
				}
			}
		}
		points[index] = point;
		EnforceMode(index);
	}

	public BezierControlPointMode GetControlPointMode(int index)
	{
		return modes[(index + 1) / 3];
	}

	public void SetControlPointMode(int index, BezierControlPointMode mode)
	{
		int num = (index + 1) / 3;
		modes[num] = mode;
		if (loop)
		{
			if (num == 0)
			{
				modes[modes.Length - 1] = mode;
			}
			else if (num == modes.Length - 1)
			{
				modes[0] = mode;
			}
		}
		EnforceMode(index);
	}

	private void EnforceMode(int index)
	{
		int num = (index + 1) / 3;
		BezierControlPointMode bezierControlPointMode = modes[num];
		if (bezierControlPointMode == BezierControlPointMode.Free || (!loop && (num == 0 || num == modes.Length - 1)))
		{
			return;
		}
		int num2 = num * 3;
		int num3;
		int num4;
		if (index <= num2)
		{
			num3 = num2 - 1;
			if (num3 < 0)
			{
				num3 = points.Length - 2;
			}
			num4 = num2 + 1;
			if (num4 >= points.Length)
			{
				num4 = 1;
			}
		}
		else
		{
			num3 = num2 + 1;
			if (num3 >= points.Length)
			{
				num3 = 1;
			}
			num4 = num2 - 1;
			if (num4 < 0)
			{
				num4 = points.Length - 2;
			}
		}
		UnityEngine.Vector3 vector = points[num2];
		UnityEngine.Vector3 vector2 = vector - points[num3];
		if (bezierControlPointMode == BezierControlPointMode.Aligned)
		{
			vector2 = vector2.normalized * UnityEngine.Vector3.Distance(vector, points[num4]);
		}
		points[num4] = vector + vector2;
	}

	public UnityEngine.Vector3 GetPoint(float t, bool ConstantVelocity)
	{
		if (ConstantVelocity)
		{
			return GetPoint(getPathFromTime(t));
		}
		return GetPoint(t);
	}

	public UnityEngine.Vector3 GetPoint(float t)
	{
		int num;
		if (t >= 1f)
		{
			t = 1f;
			num = points.Length - 4;
		}
		else
		{
			t = Mathf.Clamp01(t) * (float)CurveCount;
			num = (int)t;
			t -= (float)num;
			num *= 3;
		}
		return base.transform.TransformPoint(Bezier.GetPoint(points[num], points[num + 1], points[num + 2], points[num + 3], t));
	}

	public UnityEngine.Vector3 GetPointLocal(float t)
	{
		int num;
		if (t >= 1f)
		{
			t = 1f;
			num = points.Length - 4;
		}
		else
		{
			t = Mathf.Clamp01(t) * (float)CurveCount;
			num = (int)t;
			t -= (float)num;
			num *= 3;
		}
		return Bezier.GetPoint(points[num], points[num + 1], points[num + 2], points[num + 3], t);
	}

	public UnityEngine.Vector3 GetVelocity(float t)
	{
		int num;
		if (t >= 1f)
		{
			t = 1f;
			num = points.Length - 4;
		}
		else
		{
			t = Mathf.Clamp01(t) * (float)CurveCount;
			num = (int)t;
			t -= (float)num;
			num *= 3;
		}
		return base.transform.TransformPoint(Bezier.GetFirstDerivative(points[num], points[num + 1], points[num + 2], points[num + 3], t)) - base.transform.position;
	}

	public UnityEngine.Vector3 GetDirection(float t, bool ConstantVelocity)
	{
		if (ConstantVelocity)
		{
			return GetDirection(getPathFromTime(t));
		}
		return GetDirection(t);
	}

	public UnityEngine.Vector3 GetDirection(float t)
	{
		return GetVelocity(t).normalized;
	}

	public void AddCurve()
	{
		UnityEngine.Vector3 vector = points[points.Length - 1];
		Array.Resize(ref points, points.Length + 3);
		vector.x += 1f;
		points[points.Length - 3] = vector;
		vector.x += 1f;
		points[points.Length - 2] = vector;
		vector.x += 1f;
		points[points.Length - 1] = vector;
		Array.Resize(ref modes, modes.Length + 1);
		modes[modes.Length - 1] = modes[modes.Length - 2];
		EnforceMode(points.Length - 4);
		if (loop)
		{
			points[points.Length - 1] = points[0];
			modes[modes.Length - 1] = modes[0];
			EnforceMode(0);
		}
	}

	public void RemoveLastCurve()
	{
		if (points.Length > 4)
		{
			Array.Resize(ref points, points.Length - 3);
			Array.Resize(ref modes, modes.Length - 1);
		}
	}

	public void RemoveCurve(int index)
	{
		if (points.Length > 4)
		{
			List<UnityEngine.Vector3> list = points.ToList();
			int i;
			for (i = 4; i < points.Length && index - 3 > i; i += 3)
			{
			}
			for (int j = 0; j < 3; j++)
			{
				list.RemoveAt(i);
			}
			points = list.ToArray();
			int index2 = (i - 4) / 3;
			List<BezierControlPointMode> list2 = modes.ToList();
			list2.RemoveAt(index2);
			modes = list2.ToArray();
		}
	}

	public void Reset()
	{
		points = new UnityEngine.Vector3[4]
		{
			new UnityEngine.Vector3(0f, -1f, 0f),
			new UnityEngine.Vector3(0f, -1f, 2f),
			new UnityEngine.Vector3(0f, -1f, 4f),
			new UnityEngine.Vector3(0f, -1f, 6f)
		};
		modes = new BezierControlPointMode[2];
	}
}
public class CatmullRomSpline : MonoBehaviour
{
	public Transform[] controlPointTransforms = new Transform[0];

	public Transform debugTransform;

	public List<UnityEngine.Vector3> controlPoints = new List<UnityEngine.Vector3>();

	public List<UnityEngine.Matrix4x4> controlPointsTransformationMatricies = new List<UnityEngine.Matrix4x4>();

	public float testFloat;

	private void RefreshControlPoints()
	{
		controlPoints.Clear();
		controlPointsTransformationMatricies.Clear();
		for (int i = 0; i < controlPointTransforms.Length; i++)
		{
			controlPoints.Add(controlPointTransforms[i].position);
			controlPointsTransformationMatricies.Add(controlPointTransforms[i].localToWorldMatrix);
		}
	}

	private void Awake()
	{
		RefreshControlPoints();
	}

	public static UnityEngine.Vector3 Evaluate(List<UnityEngine.Vector3> controlPoints, float t)
	{
		if (controlPoints.Count < 1)
		{
			return UnityEngine.Vector3.zero;
		}
		if (controlPoints.Count < 2)
		{
			return controlPoints[0];
		}
		if (controlPoints.Count < 3)
		{
			return UnityEngine.Vector3.Lerp(controlPoints[0], controlPoints[1], t);
		}
		if (controlPoints.Count < 4)
		{
			if (t < 0.5f)
			{
				return UnityEngine.Vector3.Lerp(controlPoints[0], controlPoints[1], t * 2f);
			}
			return UnityEngine.Vector3.Lerp(controlPoints[1], controlPoints[2], (t - 0.5f) * 2f);
		}
		float num = t * (float)(controlPoints.Count - 3);
		int num2 = Mathf.FloorToInt(num);
		float t2 = num - (float)num2;
		int num3 = num2;
		if (num3 >= controlPoints.Count - 3)
		{
			num3 = controlPoints.Count - 4;
			t2 = 1f;
		}
		return CatmullRom(t2, controlPoints[num3], controlPoints[num3 + 1], controlPoints[num3 + 2], controlPoints[num3 + 3]);
	}

	public UnityEngine.Vector3 Evaluate(float t)
	{
		return Evaluate(controlPoints, t);
	}

	public static float GetClosestEvaluationOnSpline(List<UnityEngine.Vector3> controlPoints, UnityEngine.Vector3 worldPoint, out UnityEngine.Vector3 linePoint)
	{
		float num = float.MaxValue;
		float num2 = 0f;
		int num3 = 0;
		linePoint = worldPoint;
		for (int i = 1; i < controlPoints.Count - 2; i++)
		{
			UnityEngine.Vector3 vector = controlPoints[i];
			UnityEngine.Vector3 vector2 = controlPoints[i + 1];
			UnityEngine.Vector3 vector3 = vector2 - vector;
			float magnitude = vector3.magnitude;
			if ((double)magnitude > 1E-05)
			{
				UnityEngine.Vector3 vector4 = vector3 / magnitude;
				float num4 = UnityEngine.Vector3.Dot(worldPoint - vector, vector4);
				float sqrMagnitude;
				float num5;
				UnityEngine.Vector3 vector5;
				if (num4 <= 0f)
				{
					sqrMagnitude = (worldPoint - vector).sqrMagnitude;
					num5 = 0f;
					vector5 = vector;
				}
				else if (num4 >= magnitude)
				{
					sqrMagnitude = (worldPoint - vector2).sqrMagnitude;
					num5 = 1f;
					vector5 = vector2;
				}
				else
				{
					sqrMagnitude = (worldPoint - (vector + vector4 * num4)).sqrMagnitude;
					num5 = num4 / magnitude;
					vector5 = vector + vector4 * num4;
				}
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					num2 = num5;
					num3 = i;
					linePoint = vector5;
				}
			}
		}
		return Mathf.Clamp01(((float)(num3 - 1) + num2) / (float)(controlPoints.Count - 3));
	}

	public float GetClosestEvaluationOnSpline(UnityEngine.Vector3 worldPoint, out UnityEngine.Vector3 linePoint)
	{
		return GetClosestEvaluationOnSpline(controlPoints, worldPoint, out linePoint);
	}

	public static UnityEngine.Vector3 GetForwardTangent(List<UnityEngine.Vector3> controlPoints, float t, float step = 0.01f)
	{
		t = Mathf.Clamp(t, 0f, 1f - step - Mathf.Epsilon);
		UnityEngine.Vector3 vector = Evaluate(controlPoints, t);
		return (Evaluate(controlPoints, t + step) - vector).normalized;
	}

	public UnityEngine.Vector3 GetForwardTangent(float t, float step = 0.01f)
	{
		t = Mathf.Clamp(t, 0f, 1f - step - Mathf.Epsilon);
		UnityEngine.Vector3 vector = Evaluate(t);
		return (Evaluate(t + step) - vector).normalized;
	}

	private static UnityEngine.Vector3 CatmullRom(float t, UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, UnityEngine.Vector3 p3)
	{
		UnityEngine.Vector3 vector = 2f * p1;
		UnityEngine.Vector3 vector2 = p2 - p0;
		UnityEngine.Vector3 vector3 = 2f * p0 - 5f * p1 + 4f * p2 - p3;
		UnityEngine.Vector3 vector4 = -p0 + 3f * p1 - 3f * p2 + p3;
		return 0.5f * (vector + vector2 * t + vector3 * t * t + vector4 * t * t * t);
	}

	private void OnDrawGizmosSelected()
	{
		if (testFloat > 0f)
		{
			UnityEngine.Vector3 vector = Evaluate(testFloat);
			UnityEngine.Matrix4x4 matrix4x = Evaluate(controlPointsTransformationMatricies, testFloat);
			Gizmos.color = Color.green;
			Gizmos.DrawRay(vector, matrix4x.rotation * UnityEngine.Vector3.up * 0.2f);
			Gizmos.color = Color.blue;
			Gizmos.DrawRay(vector, matrix4x.rotation * UnityEngine.Vector3.forward * 0.2f);
			Gizmos.color = Color.red;
			Gizmos.DrawRay(vector, matrix4x.rotation * UnityEngine.Vector3.right * 0.2f);
			Gizmos.color = Color.yellow;
			Gizmos.DrawWireSphere(vector, 0.01f);
			Gizmos.DrawRay(vector, GetForwardTangent(testFloat));
		}
		RefreshControlPoints();
		Gizmos.color = Color.yellow;
		int num = 128;
		UnityEngine.Vector3 vector2 = Evaluate(0f);
		for (int i = 1; i <= num; i++)
		{
			float t = (float)i / (float)num;
			UnityEngine.Vector3 vector3 = Evaluate(t);
			Gizmos.DrawLine(vector2, vector3);
			vector2 = vector3;
		}
		if (!(debugTransform != null))
		{
			return;
		}
		UnityEngine.Vector3 linePoint;
		float closestEvaluationOnSpline = GetClosestEvaluationOnSpline(debugTransform.position, out linePoint);
		Gizmos.color = Color.red;
		Gizmos.DrawWireSphere(Evaluate(closestEvaluationOnSpline), 0.2f);
		Gizmos.color = Color.yellow;
		Gizmos.DrawWireSphere(linePoint, 0.25f);
		if (controlPoints.Count > 3)
		{
			Gizmos.color = Color.green;
			vector2 = controlPoints[1];
			for (int j = 2; j < controlPoints.Count - 2; j++)
			{
				UnityEngine.Vector3 vector4 = controlPoints[j];
				Gizmos.DrawLine(vector2, vector4);
				vector2 = vector4;
			}
		}
	}

	public static UnityEngine.Matrix4x4 CatmullRom(float t, UnityEngine.Matrix4x4 p0, UnityEngine.Matrix4x4 p1, UnityEngine.Matrix4x4 p2, UnityEngine.Matrix4x4 p3)
	{
		UnityEngine.Vector3 pos = CatmullRom(t, p0.GetColumn(3), p1.GetColumn(3), p2.GetColumn(3), p3.GetColumn(3));
		UnityEngine.Quaternion q = UnityEngine.Quaternion.Slerp(p1.rotation, p2.rotation, t);
		UnityEngine.Vector3 s = UnityEngine.Vector3.Lerp(p1.lossyScale, p2.lossyScale, t);
		return UnityEngine.Matrix4x4.TRS(pos, q, s);
	}

	public static UnityEngine.Matrix4x4 Evaluate(List<UnityEngine.Matrix4x4> controlPoints, float t)
	{
		if (controlPoints.Count < 1)
		{
			return UnityEngine.Matrix4x4.identity;
		}
		if (controlPoints.Count < 2)
		{
			return controlPoints[0];
		}
		if (controlPoints.Count < 4)
		{
			return controlPoints[0];
		}
		float num = t * (float)(controlPoints.Count - 3);
		int num2 = Mathf.FloorToInt(num);
		float t2 = num - (float)num2;
		int num3 = num2;
		if (num3 >= controlPoints.Count - 3)
		{
			num3 = controlPoints.Count - 4;
			t2 = 1f;
		}
		return CatmullRom(t2, controlPoints[num3], controlPoints[num3 + 1], controlPoints[num3 + 2], controlPoints[num3 + 3]);
	}
}
