public class LinearSpline : MonoBehaviour
{
	public struct CurveBoundary
	{
		public UnityEngine.Vector3 start;

		public UnityEngine.Vector3 end;
	}

	public Transform[] controlPointTransforms = new Transform[0];

	public Transform debugTransform;

	public List<UnityEngine.Vector3> controlPoints = new List<UnityEngine.Vector3>();

	public List<float> distances = new List<float>();

	public List<CurveBoundary> curveBoundaries = new List<CurveBoundary>();

	public bool roundCorners;

	public float cornerRadius = 1f;

	public bool looping;

	public float testFloat;

	public int gizmoResolution = 128;

	public float totalDistance;

	private void RefreshControlPoints()
	{
		controlPoints.Clear();
		for (int i = 0; i < controlPointTransforms.Length; i++)
		{
			controlPoints.Add(controlPointTransforms[i].position);
		}
		totalDistance = 0f;
		distances.Clear();
		for (int j = 1; j < controlPoints.Count; j++)
		{
			float num = UnityEngine.Vector3.Distance(controlPoints[j - 1], controlPoints[j]);
			distances.Add(num);
			totalDistance += num;
		}
		float num2 = UnityEngine.Vector3.Distance(controlPoints[controlPoints.Count - 1], controlPoints[0]);
		distances.Add(num2);
		if (looping)
		{
			totalDistance += num2;
		}
		curveBoundaries.Clear();
		if (roundCorners)
		{
			for (int k = 0; k < controlPoints.Count; k++)
			{
				int num3 = ((k > 0) ? (k - 1) : (controlPoints.Count - 1));
				int index = (k + 1) % controlPoints.Count;
				float num4 = Mathf.Min(Mathf.Min(cornerRadius, distances[num3 % distances.Count] * 0.5f), distances[k % distances.Count] * 0.5f);
				curveBoundaries.Add(new CurveBoundary
				{
					start = UnityEngine.Vector3.Lerp(controlPoints[num3], controlPoints[k], 1f - num4 / distances[num3 % distances.Count]),
					end = UnityEngine.Vector3.Lerp(controlPoints[k], controlPoints[index], num4 / distances[k])
				});
			}
		}
	}

	private void Awake()
	{
		RefreshControlPoints();
	}

	public UnityEngine.Vector3 Evaluate(float t)
	{
		if (controlPoints.Count < 1)
		{
			return UnityEngine.Vector3.zero;
		}
		if (controlPoints.Count < 2)
		{
			return controlPoints[0];
		}
		if (controlPoints.Count < 3)
		{
			return UnityEngine.Vector3.Lerp(controlPoints[0], controlPoints[1], t);
		}
		float num = Mathf.Clamp01(t) * totalDistance;
		int num2 = 0;
		float num3 = 0f;
		float num4 = 0f;
		for (int i = 0; i < distances.Count; i++)
		{
			if (looping || i != distances.Count - 1)
			{
				num2 = i;
				if (num - num4 <= distances[i])
				{
					num3 = Mathf.Clamp01((num - num4) / distances[i]);
					break;
				}
				num3 = 1f;
				num4 += distances[i];
			}
		}
		num2 %= controlPoints.Count;
		int num5 = (num2 + 1) % controlPoints.Count;
		if (roundCorners)
		{
			if (num3 > 0.5f && (looping || num2 < controlPoints.Count - 2))
			{
				_ = (num5 + 1) % controlPoints.Count;
				float num6 = Mathf.Min(Mathf.Min(cornerRadius, distances[num2] * 0.5f), distances[num5 % distances.Count] * 0.5f);
				float num7 = 1f - num6 / distances[num2];
				if (num3 > num7)
				{
					UnityEngine.Vector3 start = curveBoundaries[num5].start;
					UnityEngine.Vector3 end = curveBoundaries[num5].end;
					float t2 = 0.5f * Mathf.Clamp01((num3 - num7) / (1f - num7));
					UnityEngine.Vector3 a = UnityEngine.Vector3.Lerp(start, controlPoints[num5], t2);
					UnityEngine.Vector3 b = UnityEngine.Vector3.Lerp(controlPoints[num5], end, t2);
					return UnityEngine.Vector3.Lerp(a, b, t2);
				}
			}
			else if (num3 <= 0.5f && (looping || num2 > 0))
			{
				int num8 = ((num2 > 0) ? (num2 - 1) : (controlPoints.Count - 1));
				float num9 = Mathf.Min(Mathf.Min(cornerRadius, distances[num2] * 0.5f), distances[num8 % distances.Count] * 0.5f) / distances[num2];
				if (num3 < num9)
				{
					UnityEngine.Vector3 start2 = curveBoundaries[num2].start;
					UnityEngine.Vector3 end2 = curveBoundaries[num2].end;
					float t3 = 0.5f + 0.5f * Mathf.Clamp01(num3 / num9);
					UnityEngine.Vector3 a2 = UnityEngine.Vector3.Lerp(start2, controlPoints[num2], t3);
					UnityEngine.Vector3 b2 = UnityEngine.Vector3.Lerp(controlPoints[num2], end2, t3);
					return UnityEngine.Vector3.Lerp(a2, b2, t3);
				}
			}
		}
		return UnityEngine.Vector3.Lerp(controlPoints[num2], controlPoints[num5], num3);
	}

	public UnityEngine.Vector3 GetForwardTangent(float t, float step = 0.01f)
	{
		t = Mathf.Clamp(t, 0f, 1f - step - Mathf.Epsilon);
		UnityEngine.Vector3 vector = Evaluate(t);
		return (Evaluate(t + step) - vector).normalized;
	}

	private void OnDrawGizmosSelected()
	{
		RefreshControlPoints();
		Gizmos.color = Color.yellow;
		int num = gizmoResolution;
		UnityEngine.Vector3 vector = Evaluate(0f);
		for (int i = 1; i <= num; i++)
		{
			float t = (float)i / (float)num;
			UnityEngine.Vector3 vector2 = Evaluate(t);
			Gizmos.DrawLine(vector, vector2);
			vector = vector2;
		}
		UnityEngine.Vector3 to = Evaluate(1f);
		Gizmos.DrawLine(vector, to);
	}
}
public class SplineDecorator : MonoBehaviour
{
	public BezierSpline spline;

	public int frequency;

	public bool lookForward;

	public Transform[] items;

	private void Awake()
	{
		if (frequency <= 0 || items == null || items.Length == 0)
		{
			return;
		}
		float num = frequency * items.Length;
		num = ((!spline.Loop && num != 1f) ? (1f / (num - 1f)) : (1f / num));
		int num2 = 0;
		for (int i = 0; i < frequency; i++)
		{
			int num3 = 0;
			while (num3 < items.Length)
			{
				Transform transform = UnityEngine.Object.Instantiate(items[num3]);
				UnityEngine.Vector3 point = spline.GetPoint((float)num2 * num);
				transform.transform.localPosition = point;
				if (lookForward)
				{
					transform.transform.LookAt(point + spline.GetDirection((float)num2 * num));
				}
				transform.transform.parent = base.transform;
				num3++;
				num2++;
			}
		}
	}
}
public class SplineWalker : MonoBehaviour, IPunObservable
{
	public BezierSpline spline;

	public LinearSpline linearSpline;

	public float duration;

	public bool lookForward;

	public SplineWalkerMode mode;

	public bool walkLinearPath;

	public bool useWorldPosition;

	public float progress;

	private bool goingForward = true;

	public bool DoNetworkSync = true;

	private PhotonView _view;

	private void Awake()
	{
		_view = GetComponent<PhotonView>();
	}

	private void Update()
	{
		if (goingForward)
		{
			progress += Time.deltaTime / duration;
			if (progress > 1f)
			{
				if (mode == SplineWalkerMode.Once)
				{
					progress = 1f;
				}
				else if (mode == SplineWalkerMode.Loop)
				{
					progress -= 1f;
				}
				else
				{
					progress = 2f - progress;
					goingForward = false;
				}
			}
		}
		else
		{
			progress -= Time.deltaTime / duration;
			if (progress < 0f)
			{
				progress = 0f - progress;
				goingForward = true;
			}
		}
		if (linearSpline != null && walkLinearPath)
		{
			UnityEngine.Vector3 vector = linearSpline.Evaluate(progress);
			if (useWorldPosition)
			{
				base.transform.position = vector;
			}
			else
			{
				base.transform.localPosition = vector;
			}
			if (lookForward)
			{
				base.transform.LookAt(vector + linearSpline.GetForwardTangent(progress));
			}
		}
		else if (spline != null)
		{
			UnityEngine.Vector3 point = spline.GetPoint(progress);
			if (useWorldPosition)
			{
				base.transform.position = point;
			}
			else
			{
				base.transform.localPosition = point;
			}
			if (lookForward)
			{
				base.transform.LookAt(point + spline.GetDirection(progress));
			}
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		stream.Serialize(ref progress);
	}
}
public enum SplineWalkerMode
{
	Once,
	Loop,
	PingPong
}
public class StaticArrayBag<T>
{
	private Dictionary<int, T[]> m_bag = new Dictionary<int, T[]>(1);

	public T[] GetStaticArray(int size)
	{
		T[] array;
		if (!m_bag.ContainsKey(size))
		{
			array = new T[size];
			m_bag[size] = array;
		}
		else
		{
			array = m_bag[size];
		}
		return array;
	}
}
public static class StaticHash
{
	[StructLayout(LayoutKind.Explicit)]
	private struct SingleInt32
	{
		[FieldOffset(0)]
		public float single;

		[FieldOffset(0)]
		public int int32;
	}

	[StructLayout(LayoutKind.Explicit)]
	private struct DoubleInt64
	{
		[FieldOffset(0)]
		public double @double;

		[FieldOffset(0)]
		public long int64;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint ComputeU(uint u)
	{
		uint num = u;
		num = num + 2127912214 + (num << 12);
		num = num ^ 0xC761C23Cu ^ (num >> 19);
		num = num + 374761393 + (num << 5);
		num = (uint)((int)num + -744332180) ^ (num << 9);
		num = (uint)((int)num + -42973499) + (num << 3);
		return num ^ 0xB55A4F09u ^ (num >> 16);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint ComputeU(int i)
	{
		return ComputeU((uint)i);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(int i)
	{
		return (int)ComputeU(i);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(uint u)
	{
		return (int)ComputeU(u);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(float f)
	{
		return Compute(System.Runtime.CompilerServices.Unsafe.As<float, uint>(ref f));
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(float f1, float f2)
	{
		int i = Compute(f1);
		int i2 = Compute(f2);
		return Compute(i, i2);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(float f1, float f2, float f3)
	{
		int i = Compute(f1);
		int i2 = Compute(f2);
		int i3 = Compute(f3);
		return Compute(i, i2, i3);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(float f1, float f2, float f3, float f4)
	{
		int i = Compute(f1);
		int i2 = Compute(f2);
		int i3 = Compute(f3);
		int i4 = Compute(f4);
		return Compute(i, i2, i3, i4);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	private static ulong ComputeUL(ulong h)
	{
		h = ~h + (h << 18);
		h ^= h >> 31;
		h *= 21;
		h ^= h >> 11;
		h += h << 6;
		h ^= h >> 22;
		return h;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(long l)
	{
		return (int)ComputeUL((ulong)l);
