public static class StringUtils
{
	public const string kForwardSlash = "/";

	public const string kBackSlash = "/";

	public const string kBackTick = "`";

	public const string kMinusDash = "-";

	public const string kPeriod = ".";

	public const string kUnderScore = "_";

	public const string kColon = ":";

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool IsNullOrEmpty(this string s)
	{
		return string.IsNullOrEmpty(s);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool IsNullOrWhiteSpace(this string s)
	{
		return string.IsNullOrWhiteSpace(s);
	}

	public static string ToAlphaNumeric(this string s)
	{
		if (string.IsNullOrWhiteSpace(s))
		{
			return string.Empty;
		}
		using Utf16ValueStringBuilder utf16ValueStringBuilder = ZString.CreateStringBuilder();
		foreach (char c in s)
		{
			if (char.IsLetterOrDigit(c))
			{
				utf16ValueStringBuilder.Append(c);
			}
		}
		return utf16ValueStringBuilder.ToString();
	}

	public static string Capitalize(this string s)
	{
		if (string.IsNullOrWhiteSpace(s))
		{
			return s;
		}
		char[] array = s.ToCharArray();
		array[0] = char.ToUpperInvariant(array[0]);
		return new string(array);
	}

	public static string Concat(this IEnumerable<string> source)
	{
		return string.Concat(source);
	}

	public static string Join(this IEnumerable<string> source, string separator)
	{
		return string.Join(separator, source);
	}

	public static string Join(this IEnumerable<string> source, char separator)
	{
		return string.Join(separator, source);
	}

	public static string RemoveAll(this string s, string value, StringComparison mode = StringComparison.OrdinalIgnoreCase)
	{
		if (string.IsNullOrEmpty(s))
		{
			return s;
		}
		return s.Replace(value, string.Empty, mode);
	}

	public static string RemoveAll(this string s, char value, StringComparison mode = StringComparison.OrdinalIgnoreCase)
	{
		return s.RemoveAll(value.ToString(), mode);
	}

	public static byte[] ToBytesASCII(this string s)
	{
		return Encoding.ASCII.GetBytes(s);
	}

	public static byte[] ToBytesUTF8(this string s)
	{
		return Encoding.UTF8.GetBytes(s);
	}

	public static byte[] ToBytesUnicode(this string s)
	{
		return Encoding.Unicode.GetBytes(s);
	}

	public static string ComputeSHV2(this string s)
	{
		return Hash128.Compute(s).ToString();
	}

	public static string ToQueryString(this Dictionary<string, string> d)
	{
		if (d == null)
		{
			return null;
		}
		return "?" + string.Join("&", d.Select((KeyValuePair<string, string> x) => x.Key + "=" + x.Value));
	}

	public static string Combine(string separator, params string[] values)
	{
		if (values == null || values.Length == 0)
		{
			return null;
		}
		StringBuilder stringBuilder = new StringBuilder();
		bool flag = !string.IsNullOrEmpty(separator);
		for (int i = 0; i < values.Length; i++)
		{
			if (flag)
			{
				stringBuilder.Append(separator);
			}
			stringBuilder.Append(values);
		}
		return stringBuilder.ToString();
	}

	public static string ToUpperCamelCase(this string input)
	{
		if (string.IsNullOrWhiteSpace(input))
		{
			return string.Empty;
		}
		string[] array = Regex.Split(input, "[^A-Za-z0-9]+");
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].Length > 0)
			{
				int num = i;
				string text = char.ToUpper(array[i][0]).ToString();
				object obj;
				if (array[i].Length <= 1)
				{
					obj = "";
				}
				else
				{
					string text2 = array[i];
					obj = text2.Substring(1, text2.Length - 1).ToLower();
				}
				array[num] = text + (string)obj;
			}
		}
		return string.Join("", array);
	}

	public static string ToUpperCaseFromCamelCase(this string input)
	{
		if (string.IsNullOrEmpty(input))
		{
			return input;
		}
		input = input.Trim();
		using Utf16ValueStringBuilder utf16ValueStringBuilder = ZString.CreateStringBuilder();
		bool flag = true;
		foreach (char c in input)
		{
			if (char.IsUpper(c) && !flag)
			{
				utf16ValueStringBuilder.Append(' ');
			}
			utf16ValueStringBuilder.Append(char.ToUpper(c));
			flag = char.IsUpper(c);
		}
		return utf16ValueStringBuilder.ToString().Trim();
	}

	public static string RemoveStart(this string s, string value, StringComparison comparison = StringComparison.CurrentCultureIgnoreCase)
	{
		if (string.IsNullOrEmpty(s) || !s.StartsWith(value, comparison))
		{
			return s;
		}
		return s.Substring(value.Length);
	}

	public static string RemoveEnd(this string s, string value, StringComparison comparison = StringComparison.CurrentCultureIgnoreCase)
	{
		if (string.IsNullOrEmpty(s) || !s.EndsWith(value, comparison))
		{
			return s;
		}
		return s.Substring(0, s.Length - value.Length);
	}

	public static string RemoveBothEnds(this string s, string value, StringComparison comparison = StringComparison.CurrentCultureIgnoreCase)
	{
		return s.RemoveEnd(value, comparison).RemoveStart(value, comparison);
	}

	public static string TrailingSpace(this string s)
	{
		if (string.IsNullOrEmpty(s))
		{
			UnityEngine.Debug.LogError("[STRING::UTILS] Trying to add Space, but string is null or empty");
			return s;
		}
		if (s[s.Length - 1] == ' ')
		{
			return s;
		}
		return s + " ";
	}
}
public enum SaveTextureFileFormat
{
	EXR,
	JPG,
	PNG,
	TGA
}
public static class TextureUtils
{
	public static UnityEngine.Vector4 GetTexelSize(this Texture tex)
	{
		if (tex.AsNull() == null)
		{
			return UnityEngine.Vector4.zero;
		}
		UnityEngine.Vector2 texelSize = tex.texelSize;
		float num = Mathf.Max(texelSize.x, 1f / texelSize.x);
		float num2 = Mathf.Max(texelSize.y, 1f / texelSize.y);
		return new UnityEngine.Vector4(1f / num, 1f / num2, num, num2);
	}

	public static Color32 CalcAverageColor(Texture2D tex)
	{
		if (tex == null)
		{
			return default(Color32);
		}
		Color32[] pixels = tex.GetPixels32();
		int num = pixels.Length;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		for (int i = 0; i < num; i++)
		{
			num2 += pixels[i].r;
			num3 += pixels[i].g;
			num4 += pixels[i].b;
		}
		return new Color32((byte)(num2 / num), (byte)(num3 / num), (byte)(num4 / num), byte.MaxValue);
	}

	public static void SaveToFile(Texture source, string filePath, int width, int height, SaveTextureFileFormat fileFormat = SaveTextureFileFormat.PNG, int jpgQuality = 95, bool asynchronous = true, Action<bool> done = null)
	{
		if (!(source is Texture2D) && !(source is RenderTexture))
		{
			done?.Invoke(obj: false);
			return;
		}
		if (width < 0 || height < 0)
		{
			width = source.width;
			height = source.height;
		}
		RenderTexture resizeRT = RenderTexture.GetTemporary(width, height, 0);
		Graphics.Blit(source, resizeRT);
		NativeArray<byte> narray = new NativeArray<byte>(width * height * 4, Unity.Collections.Allocator.Persistent, NativeArrayOptions.UninitializedMemory);
		AsyncGPUReadbackRequest asyncGPUReadbackRequest = AsyncGPUReadback.RequestIntoNativeArray(ref narray, resizeRT, 0, delegate(AsyncGPUReadbackRequest request)
		{
			if (!request.hasError)
			{
				NativeArray<byte> nativeArray = fileFormat switch
				{
					SaveTextureFileFormat.EXR => ImageConversion.EncodeNativeArrayToEXR(narray, resizeRT.graphicsFormat, (uint)width, (uint)height), 
					SaveTextureFileFormat.JPG => ImageConversion.EncodeNativeArrayToJPG(narray, resizeRT.graphicsFormat, (uint)width, (uint)height, 0u, jpgQuality), 
					SaveTextureFileFormat.TGA => ImageConversion.EncodeNativeArrayToTGA(narray, resizeRT.graphicsFormat, (uint)width, (uint)height), 
					_ => ImageConversion.EncodeNativeArrayToPNG(narray, resizeRT.graphicsFormat, (uint)width, (uint)height), 
				};
				File.WriteAllBytes(filePath, nativeArray.ToArray());
				nativeArray.Dispose();
			}
			narray.Dispose();
			done?.Invoke(!request.hasError);
		});
		if (!asynchronous)
		{
			asyncGPUReadbackRequest.WaitForCompletion();
		}
	}

	public static Texture2D CreateCopy(Texture2D tex)
	{
		if (tex == null)
		{
			throw new ArgumentNullException("tex");
		}
		RenderTexture temporary = RenderTexture.GetTemporary(tex.width, tex.height, 0, RenderTextureFormat.Default, RenderTextureReadWrite.Linear);
		Graphics.Blit(tex, temporary);
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = temporary;
		Texture2D texture2D = new Texture2D(tex.width, tex.height);
		texture2D.ReadPixels(new Rect(0f, 0f, temporary.width, temporary.height), 0, 0);
		texture2D.Apply();
		RenderTexture.active = active;
		RenderTexture.ReleaseTemporary(temporary);
		return texture2D;
	}
}
public static class TransformUtils
{
	private const string kFwdSlash = "/";

	public static int ComputePathHashByInstance(Transform t)
	{
		if (t == null)
		{
			return 0;
		}
		int num = 0;
		Transform transform = t;
		while (transform != null)
		{
			num = StaticHash.Compute(num, transform.GetHashCode());
			transform = transform.parent;
		}
		return num;
	}

	public static Hash128 ComputePathHash(Transform t)
	{
		if (t == null)
		{
			return default(Hash128);
		}
		Hash128 outHash = default(Hash128);
		Transform transform = t;
		while (transform != null)
		{
			Hash128 inHash = Hash128.Compute(transform.name);
			HashUtilities.AppendHash(ref inHash, ref outHash);
			transform = transform.parent;
		}
		return outHash;
	}

	public static string GetScenePath(Transform t)
	{
		if (t == null)
		{
			return null;
		}
		string text = t.name;
		Transform parent = t.parent;
		while (parent != null)
		{
			text = parent.name + "/" + text;
			parent = parent.parent;
		}
		return text;
	}

	public static string GetScenePathReverse(Transform t)
	{
		if (t == null)
		{
			return null;
		}
		string text = t.name;
		Transform parent = t.parent;
		Queue<string> queue = new Queue<string>(16);
		while (parent != null)
		{
			queue.Enqueue(parent.name);
			parent = parent.parent;
		}
		while (queue.Count > 0)
		{
			text = text + "/" + queue.Dequeue();
		}
		return text;
	}
}
