public class UIMatchRotation : MonoBehaviour
{
	private enum State
	{
		Ready,
		Rotating
	}

	[SerializeField]
	private Transform referenceTransform;

	[SerializeField]
	private float threshold = 0.35f;

	[SerializeField]
	private float lerpSpeed = 5f;

	private State state;

	private void Start()
	{
		referenceTransform = Camera.main.transform;
		base.transform.forward = x0z(referenceTransform.forward);
	}

	private void Update()
	{
		UnityEngine.Vector3 lhs = x0z(base.transform.forward);
		UnityEngine.Vector3 vector = x0z(referenceTransform.forward);
		float num = UnityEngine.Vector3.Dot(lhs, vector);
		switch (state)
		{
		case State.Ready:
			if (num < 1f - threshold)
			{
				state = State.Rotating;
			}
			break;
		case State.Rotating:
			base.transform.forward = UnityEngine.Vector3.Lerp(base.transform.forward, vector, Time.deltaTime * lerpSpeed);
			if (UnityEngine.Vector3.Dot(base.transform.forward, vector) > 0.995f)
			{
				state = State.Ready;
			}
			break;
		}
	}

	private UnityEngine.Vector3 x0z(UnityEngine.Vector3 vector)
	{
		vector.y = 0f;
		return vector.normalized;
	}
}
public class UniqueQueue<T> : IEnumerable<T>, IEnumerable
{
	private HashSet<T> queuedItems;

	private Queue<T> queue;

	public int Count => queue.Count;

	public UniqueQueue()
	{
		queuedItems = new HashSet<T>();
		queue = new Queue<T>();
	}

	public UniqueQueue(int capacity)
	{
		queuedItems = new HashSet<T>(capacity);
		queue = new Queue<T>(capacity);
	}

	public void Clear()
	{
		queuedItems.Clear();
		queue.Clear();
	}

	public bool Enqueue(T item)
	{
		if (!queuedItems.Add(item))
		{
			return false;
		}
		queue.Enqueue(item);
		return true;
	}

	public T Dequeue()
	{
		T val = queue.Dequeue();
		queuedItems.Remove(val);
		return val;
	}

	public bool TryDequeue(out T item)
	{
		if (queue.Count < 1)
		{
			item = default(T);
			return false;
		}
		item = Dequeue();
		return true;
	}

	public T Peek()
	{
		return queue.Peek();
	}

	public bool Contains(T item)
	{
		return queuedItems.Contains(item);
	}

	IEnumerator<T> IEnumerable<T>.GetEnumerator()
	{
		return queue.GetEnumerator();
	}

	IEnumerator IEnumerable.GetEnumerator()
	{
		return queue.GetEnumerator();
	}
}
