public static class XXHash32
{
	private const uint Prime32_1 = 2654435761u;

	private const uint Prime32_2 = 2246822519u;

	private const uint Prime32_3 = 3266489917u;

	private const uint Prime32_4 = 668265263u;

	private const uint Prime32_5 = 374761393u;

	private const int StripeSize = 16;

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int Compute(string s, uint seed = 0u)
	{
		return (int)Compute(Encoding.Unicode.GetBytes(s), seed);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint Compute(ReadOnlySpan<byte> input, uint seed = 0u)
	{
		int length = input.Length;
		uint num9;
		if (length >= 16)
		{
			uint num = seed + 606290984;
			uint num2 = seed + 2246822519u;
			uint num3 = seed;
			uint num4 = seed - 2654435761u;
			do
			{
				uint num5 = BinaryPrimitives.ReadUInt32LittleEndian(input);
				uint num6 = BinaryPrimitives.ReadUInt32LittleEndian(input.Slice(4));
				uint num7 = BinaryPrimitives.ReadUInt32LittleEndian(input.Slice(8));
				uint num8 = BinaryPrimitives.ReadUInt32LittleEndian(input.Slice(12));
				num += (uint)((int)num5 * -2048144777);
				num = BitOperations.RotateLeft(num, 13);
				num *= 2654435761u;
				num2 += (uint)((int)num6 * -2048144777);
				num2 = BitOperations.RotateLeft(num2, 13);
				num2 *= 2654435761u;
				num3 += (uint)((int)num7 * -2048144777);
				num3 = BitOperations.RotateLeft(num3, 13);
				num3 *= 2654435761u;
				num4 += (uint)((int)num8 * -2048144777);
				num4 = BitOperations.RotateLeft(num4, 13);
				num4 *= 2654435761u;
				input = input.Slice(16);
			}
			while (input.Length >= 16);
			num9 = BitOperations.RotateLeft(num, 1) + BitOperations.RotateLeft(num2, 7) + BitOperations.RotateLeft(num3, 12) + BitOperations.RotateLeft(num4, 18);
		}
		else
		{
			num9 = seed + 374761393;
		}
		num9 += (uint)length;
		while (input.Length >= 4)
		{
			num9 += (uint)((int)BinaryPrimitives.ReadUInt32LittleEndian(input) * -1028477379);
			num9 = BitOperations.RotateLeft(num9, 17) * 668265263;
			input = input.Slice(4);
		}
		for (int i = 0; i < input.Length; i++)
		{
			num9 += (uint)(input[i] * 374761393);
			num9 = BitOperations.RotateLeft(num9, 11) * 2654435761u;
		}
		num9 ^= num9 >> 15;
		num9 *= 2246822519u;
		num9 ^= num9 >> 13;
		num9 *= 3266489917u;
		return num9 ^ (num9 >> 16);
	}
}
[CreateAssetMenu(fileName = "ServerTimeSyncRule", menuName = "Scriptable Objects/ServerTimeSyncRule")]
public class ServerTimeSyncRule : ScriptableObject
{
	private enum Unit
	{
		Hours,
		Minutes,
		Seconds
	}

	[SerializeField]
	private Unit unit;

	[SerializeField]
	private int value;

	public DateTime GetPrevious(DateTime dt)
	{
		DateTime result = DateTime.MinValue;
		switch (unit)
		{
		case Unit.Hours:
			result = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, 0, 0).AddHours(-(dt.Hour % value));
			break;
		case Unit.Minutes:
			result = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, dt.Minute, 0).AddMinutes(-(dt.Minute % value));
			break;
		case Unit.Seconds:
			result = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, dt.Minute, dt.Second).AddSeconds(-(dt.Second % value));
			break;
		}
		return result;
	}

	public DateTime GetNext(DateTime dt)
	{
		DateTime result = DateTime.MaxValue;
		switch (unit)
		{
		case Unit.Hours:
			result = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, 0, 0).AddHours(value - dt.Hour % value);
			break;
		case Unit.Minutes:
			result = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, dt.Minute, 0).AddMinutes(value - dt.Minute % value);
			break;
		case Unit.Seconds:
			result = new DateTime(dt.Year, dt.Month, dt.Day, dt.Hour, dt.Minute, dt.Second).AddSeconds(value - dt.Second % value);
			break;
		}
		return result;
	}
}
public class GraphicsStateCollectionManager : MonoBehaviour
{
	public enum Mode
	{
		Tracing,
		WarmUp
	}

	public Mode mode;

	public static GraphicsStateCollectionManager Instance;

	public GraphicsStateCollection[] collections;

	private const string k_CollectionFolderPath = "SharedAssets/GraphicsStateCollections/";

	private string m_OutputCollectionName;

	private GraphicsStateCollection m_GraphicsStateCollection;

	private Coroutine _autoSaveRoutine;

	private GraphicsStateCollection FindExistingCollection()
	{
		for (int i = 0; i < collections.Length; i++)
		{
			if (collections[i] != null && collections[i].runtimePlatform == UnityEngine.Application.platform && collections[i].graphicsDeviceType == SystemInfo.graphicsDeviceType && collections[i].qualityLevelName == QualitySettings.names[QualitySettings.GetQualityLevel()])
			{
				return collections[i];
			}
		}
		return null;
	}

	private void Awake()
	{
		if (Instance != null && Instance != this)
		{
			UnityEngine.Debug.LogError("Only one instance of GraphicsStateCollectionManager is allowed!");
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			Instance = this;
			UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		}
	}

	private void Start()
	{
		if (mode == Mode.Tracing)
		{
			m_GraphicsStateCollection = FindExistingCollection();
			if (m_GraphicsStateCollection != null)
			{
				m_OutputCollectionName = "SharedAssets/GraphicsStateCollections/" + m_GraphicsStateCollection.name;
			}
			else
			{
				int qualityLevel = QualitySettings.GetQualityLevel();
				string text = QualitySettings.names[qualityLevel];
				text = text.Replace(" ", "");
				m_OutputCollectionName = string.Concat("SharedAssets/GraphicsStateCollections/", "GfxState_", UnityEngine.Application.platform, "_", SystemInfo.graphicsDeviceType.ToString(), "_", text);
				m_GraphicsStateCollection = new GraphicsStateCollection();
			}
			UnityEngine.Debug.Log("Tracing started for GraphicsStateCollection by Scene '" + SceneManager.GetActiveScene().name + "'.");
			m_GraphicsStateCollection.BeginTrace();
			_autoSaveRoutine = StartCoroutine(AutoSaveRoutine());
		}
		else
		{
			GraphicsStateCollection graphicsStateCollection = FindExistingCollection();
			if (graphicsStateCollection != null)
			{
				Scene activeScene = SceneManager.GetActiveScene();
				UnityEngine.Debug.Log("Scene '" + activeScene.name + "' started warming up " + graphicsStateCollection.totalGraphicsStateCount + " GraphicsState entries.");
				graphicsStateCollection.WarmUp();
			}
		}
	}

	private void OnApplicationFocus(bool focus)
	{
		if (!focus && mode == Mode.Tracing && m_GraphicsStateCollection != null)
		{
			UnityEngine.Debug.Log("Focus changed. Sending collection to Editor with " + m_GraphicsStateCollection.totalGraphicsStateCount + " GraphicsState entries.");
			m_GraphicsStateCollection.SendToEditor(m_OutputCollectionName);
		}
	}

	private void OnDestroy()
	{
		if (_autoSaveRoutine != null)
		{
			StopCoroutine(_autoSaveRoutine);
		}
		if (mode == Mode.Tracing && m_GraphicsStateCollection != null)
		{
			m_GraphicsStateCollection.EndTrace();
			UnityEngine.Debug.Log("Sending collection to Editor with " + m_GraphicsStateCollection.totalGraphicsStateCount + " GraphicsState entries.");
			m_GraphicsStateCollection.SendToEditor(m_OutputCollectionName);
		}
	}

	private IEnumerator AutoSaveRoutine()
	{
		while (true)
		{
			yield return new WaitForSeconds(5f);
			if (mode == Mode.Tracing && m_GraphicsStateCollection != null)
			{
				UnityEngine.Debug.Log("Auto-saving collection with " + m_GraphicsStateCollection.totalGraphicsStateCount + " GraphicsState entries.");
				m_GraphicsStateCollection.SendToEditor(m_OutputCollectionName);
			}
		}
	}
}
public class SimpleEventSequencer : MonoBehaviour, IGorillaSliceableSimple
{
	[Serializable]
	private class SimpleEventSequencerNode
	{
		[Tooltip("Uncheck to skip this node")]
		[SerializeField]
		private bool enabled = true;

		[Tooltip("Seconds after the previous node's events are dispatched")]
		[SerializeField]
		private float time;

		[Tooltip("This is just for legibilty. Doesn't matter what you name it.")]
		[SerializeField]
		private string name = "New Node";

		[SerializeField]
		private UnityEvent unityEvent;

		[SerializeField]
		[TextArea(5, 10)]
		private string notes = "Notes";

		private string fancyName = "New Node";

		private float totalTime;

		private string nameTrim
		{
			get
			{
				if (name.Length <= 33)
				{
					return name;
				}
				return name.Substring(0, 30) + "...";
			}
		}

		private string notesTrim
		{
			get
			{
				if (notes.Length <= 50)
				{
					return notes;
				}
				return notes.Substring(0, 47) + "...";
			}
		}

		public float Time => time;

		public UnityEvent UnityEvent => unityEvent;

		public string Name => name;

		public float TotalTime
		{
			set
			{
				totalTime = value;
			}
		}

		public bool Enabled => enabled;

		public void onValueChanged()
		{
			if (enabled)
			{
				fancyName = $"T+{totalTime} ({time}) : {nameTrim}";
			}
			else
			{
				fancyName = $"Skip ({time}) : {nameTrim}";
			}
		}
	}

	private enum OnCompleteAction
	{
		None,
		Disable,
		Repeat
	}

	[SerializeField]
	private SimpleEventSequencerNode[] nodes;

	[SerializeField]
	private bool startOnEnable = true;

	[SerializeField]
	private OnCompleteAction onComplete = OnCompleteAction.Disable;

	[SerializeField]
	private ServerTimeSyncRule serverTimeSync;

	private float startTime;

	private int idx = -1;

	private List<SimpleEventSequencerNode> enabledNodes = new List<SimpleEventSequencerNode>();

	private SimpleEventSequencerNode activeNode;

	private void StartSequence()
	{
		StartSequenceDelayed(0f);
	}

	public async void StartSequenceDelayed(float delay)
	{
		startTime = Time.time + delay;
		if (serverTimeSync != null)
		{
			while (GorillaComputer.instance == null || GorillaComputer.instance.GetServerTime().Year < 2000)
			{
				await Task.Yield();
			}
			DateTime serverTime = GorillaComputer.instance.GetServerTime();
			serverTime.AddSeconds(delay);
			DateTime next = serverTimeSync.GetNext(serverTime);
			startTime += (float)(next - serverTime).TotalSeconds;
		}
		idx = 0;
	}

	private void startSequenceImmediate()
	{
		startTime = Time.time;
		idx = 0;
	}

	private void startSequenceFrom(int i)
	{
		startTime = Time.time;
		idx = i;
	}

	private void stop(int i)
	{
		idx = -1;
	}

	private void Awake()
	{
		enabledNodes.Clear();
		for (int i = 0; i < nodes.Length; i++)
		{
			if (nodes[i].Enabled)
			{
				enabledNodes.Add(nodes[i]);
			}
		}
	}

	private void OnEnable()
	{
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
		if (startOnEnable)
		{
			StartSequence();
		}
	}

	private void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	void IGorillaSliceableSimple.SliceUpdate()
	{
		if (idx < 0 || idx == enabledNodes.Count || !(Time.time >= startTime + enabledNodes[idx].Time))
		{
			return;
		}
		enabledNodes[idx].UnityEvent?.Invoke();
		startTime = Time.time;
		idx++;
		if (idx == enabledNodes.Count)
		{
			switch (onComplete)
			{
			case OnCompleteAction.Repeat:
				StartSequenceDelayed(enabledNodes[idx - 1].Time);
				break;
			case OnCompleteAction.Disable:
				base.gameObject.SetActive(value: false);
				break;
			}
		}
	}

	private void onValueChanged()
	{
		float num = 0f;
		for (int i = 0; i < nodes.Length; i++)
		{
			if (nodes[i].Enabled)
			{
				num += nodes[i].Time;
			}
			nodes[i].TotalTime = num;
			nodes[i].onValueChanged();
		}
	}

	public void SetOnCompleteActionDisable()
	{
		onComplete = OnCompleteAction.Disable;
	}

	public void SetOnCompleteActionRepeat()
	{
		onComplete = OnCompleteAction.Repeat;
	}

	public void ClearOnCompleteAction()
	{
		onComplete = OnCompleteAction.None;
	}

	public void TempAudio(string text)
	{
		UnityEngine.Debug.Log("SimpleEventSequencer :: " + base.name + " :: TempAudio :: " + text);
	}

	public void TempVFX(string text)
	{
		UnityEngine.Debug.Log("SimpleEventSequencer :: " + base.name + " :: TempVFX :: " + text);
	}

	public void Temp(string text)
	{
		UnityEngine.Debug.Log("SimpleEventSequencer :: " + base.name + " :: Temp :: " + text);
	}

	public void DebugLog(string text)
	{
		UnityEngine.Debug.Log("SimpleEventSequencer :: " + base.name + " :: DEBUG :: " + text);
	}
}
