public class TeleportNode : GorillaTriggerBox
{
	[SerializeField]
	private XSceneRef teleportFromRef;

	[SerializeField]
	private XSceneRef teleportToRef;

	[SerializeField]
	private bool seamless = true;

	[SerializeField]
	private bool keepVelocity = true;

	[SerializeField]
	private bool subsOnly;

	private float teleportTime;

	public override void OnBoxTriggered()
	{
		if ((subsOnly && !SubscriptionManager.IsLocalSubscribed()) || Time.time - teleportTime < 0.1f)
		{
			return;
		}
		base.OnBoxTriggered();
		if (!teleportFromRef.TryResolve(out Transform result))
		{
			UnityEngine.Debug.LogError("[TeleportNode] Failed to resolve teleportFromRef.");
			return;
		}
		if (!teleportToRef.TryResolve(out Transform result2))
		{
			UnityEngine.Debug.LogError("[TeleportNode] Failed to resolve teleportToRef.");
			return;
		}
		GTPlayer instance = GTPlayer.Instance;
		if (instance == null)
		{
			UnityEngine.Debug.LogError("[TeleportNode] GTPlayer.Instance is null.");
			return;
		}
		Physics.SyncTransforms();
		UnityEngine.Vector3 position = result2.transform.position;
		if (seamless)
		{
			position = result2.TransformPoint(result.InverseTransformPoint(instance.transform.position));
		}
		UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Inverse(result.rotation) * instance.transform.rotation;
		UnityEngine.Quaternion rotation = result2.rotation * quaternion2;
		StartCoroutine(DelayedTeleport(instance, position, rotation));
		teleportTime = Time.time;
	}

	private IEnumerator DelayedTeleport(GTPlayer p, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
	{
		yield return null;
		p.TeleportTo(position, rotation, keepVelocity, !seamless);
	}
}
