public class GrowUntilCollision : MonoBehaviour
{
	[SerializeField]
	private float maxSize = 10f;

	[SerializeField]
	private float initialRadius = 1f;

	[SerializeField]
	private float minRetriggerTime = 1f;

	[SerializeField]
	private LightningDispatcherEvent colliderFound;

	private AudioSource audioSource;

	private float maxVolume;

	private float maxPitch;

	private float timeSinceTrigger;

	private void Start()
	{
		audioSource = GetComponent<AudioSource>();
		if (audioSource != null)
		{
			maxVolume = audioSource.volume;
			maxPitch = audioSource.pitch;
		}
		zero();
	}

	private void zero()
	{
		base.transform.localScale = UnityEngine.Vector3.one * initialRadius;
		if (audioSource != null)
		{
			audioSource.volume = 0f;
			audioSource.pitch = 1f;
		}
		timeSinceTrigger = 0f;
	}

	private void OnTriggerEnter(Collider other)
	{
		tryToTrigger(base.transform.position, other.transform.position);
	}

	private void OnTriggerExit(Collider other)
	{
		tryToTrigger(base.transform.position, other.transform.position);
	}

	private void OnCollisionEnter(UnityEngine.Collision collision)
	{
		tryToTrigger(base.transform.position, collision.GetContact(0).point);
	}

	private void OnCollisionExit(UnityEngine.Collision collision)
	{
		tryToTrigger(base.transform.position, collision.GetContact(0).point);
	}

	private void tryToTrigger(UnityEngine.Vector3 p1, UnityEngine.Vector3 p2)
	{
		if (timeSinceTrigger > minRetriggerTime)
		{
			if (colliderFound != null)
			{
				colliderFound.Invoke(p1, p2);
			}
			zero();
		}
	}

	private void Update()
	{
		float num = Mathf.Max(base.transform.lossyScale.x, base.transform.lossyScale.y, base.transform.lossyScale.z);
		if (base.transform.localScale.x < maxSize * num)
		{
			base.transform.localScale += UnityEngine.Vector3.one * Time.deltaTime * num;
			if (audioSource != null)
			{
				audioSource.volume = maxVolume * (base.transform.localScale.x / maxSize);
				audioSource.pitch = 1f + maxPitch * (base.transform.localScale.x / maxSize);
			}
		}
		timeSinceTrigger += Time.deltaTime;
	}
}
public class LightningDispatcher : MonoBehaviour
{
	public delegate LightningStrike DispatchLightningEvent(UnityEngine.Vector3 p1, UnityEngine.Vector3 p2);

	[SerializeField]
	private float beamWidthCM = 1f;

	[SerializeField]
	private float soundVolumeMultiplier = 1f;

	[SerializeField]
	private float minDuration = 0.05f;

	[SerializeField]
	private float maxDuration = 0.12f;

	[SerializeField]
	private Gradient colorOverLifetime;

	public static event DispatchLightningEvent RequestLightningStrike;

	public void DispatchLightning(UnityEngine.Vector3 p1, UnityEngine.Vector3 p2)
	{
		if (LightningDispatcher.RequestLightningStrike != null)
		{
			LightningStrike lightningStrike = LightningDispatcher.RequestLightningStrike(p1, p2);
			float num = Mathf.Max(base.transform.lossyScale.x, base.transform.lossyScale.y, base.transform.lossyScale.z);
			lightningStrike.Play(p1, p2, beamWidthCM * 0.01f * num, soundVolumeMultiplier / num, LightningStrike.rand.NextFloat(minDuration, maxDuration), colorOverLifetime);
		}
	}
}
