[RequireComponent(typeof(ParticleSystem))]
[RequireComponent(typeof(AudioSource))]
public class LightningStrike : MonoBehaviour
{
	public static SRand rand = new SRand("LightningStrike");

	private ParticleSystem ps;

	private ParticleSystem.MainModule psMain;

	private ParticleSystem.ShapeModule psShape;

	private ParticleSystem.TrailModule psTrails;

	private AudioSource audioSource;

	private void Initialize()
	{
		ps = GetComponent<ParticleSystem>();
		psMain = ps.main;
		psMain.playOnAwake = true;
		psMain.stopAction = ParticleSystemStopAction.Disable;
		psShape = ps.shape;
		psTrails = ps.trails;
		audioSource = GetComponent<AudioSource>();
		audioSource.playOnAwake = true;
	}

	public void Play(UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, float beamWidthMultiplier, float audioVolume, float duration, Gradient colorOverLifetime)
	{
		if (ps == null)
		{
			Initialize();
		}
		base.transform.position = p1;
		base.transform.rotation = UnityEngine.Quaternion.LookRotation(p1 - p2);
		psShape.radius = UnityEngine.Vector3.Distance(p1, p2) * 0.5f;
		psShape.position = new UnityEngine.Vector3(0f, 0f, 0f - psShape.radius);
		psShape.randomPositionAmount = Mathf.Clamp(psShape.radius / 50f, 0f, 1f);
		psTrails.widthOverTrail = new ParticleSystem.MinMaxCurve(beamWidthMultiplier * 0.1f, beamWidthMultiplier);
		psTrails.colorOverLifetime = colorOverLifetime;
		psMain.duration = duration;
		audioSource.volume = Mathf.Clamp(psShape.radius / 5f, 0f, 1f) * audioVolume;
		base.gameObject.SetActive(value: true);
	}
}
public class RandomLocalColliders : MonoBehaviour
{
	private static SRand rand = new SRand("RandomLocalColliders");

	[SerializeField]
	private float minseekFreq = 3f;

	[SerializeField]
	private float maxseekFreq = 6f;

	[SerializeField]
	private float minRadias = 1f;

	[SerializeField]
	private float maxRadias = 10f;

	[SerializeField]
	private LightningDispatcherEvent colliderFound;

	private float timeSinceSeek;

	private float seekFreq;

	private RaycastHit[] raycastHits = new RaycastHit[100];

	private void Start()
	{
		seekFreq = rand.NextFloat(minseekFreq, maxseekFreq);
	}

	private void Update()
	{
		if (colliderFound != null)
		{
			timeSinceSeek += Time.deltaTime;
			if (timeSinceSeek > seekFreq)
			{
				seek();
				timeSinceSeek = 0f;
				seekFreq = rand.NextFloat(minseekFreq, maxseekFreq);
			}
		}
	}

	private void seek()
	{
		float num = Mathf.Max(base.transform.lossyScale.x, base.transform.lossyScale.y, base.transform.lossyScale.z);
		int num2 = Physics.RaycastNonAlloc(base.transform.position, rand.NextPointOnSphere(1f), raycastHits, maxRadias * num);
		if (num2 <= 0)
		{
			return;
		}
		int num3 = rand.NextInt(num2);
		for (int i = 0; i < num2; i++)
		{
			if (!(raycastHits[(i + num3) % num2].distance < minRadias * num))
			{
				colliderFound.Invoke(base.transform.position, raycastHits[(i + num3) % num2].point);
				break;
			}
		}
	}
}
public class ReportForwardHit : MonoBehaviour
{
	private static SRand rand = new SRand("ReportForwardHit");

	[SerializeField]
	private float minseekFreq = 3f;

	[SerializeField]
	private float maxseekFreq = 6f;

	[SerializeField]
	private float maxRadias = 10f;

	[SerializeField]
	private LightningDispatcherEvent colliderFound;

	[SerializeField]
	private RandomDispatcher nsRand;

	private float timeSinceSeek;

	private float seekFreq;

	[SerializeField]
	private bool seekOnEnable;

	private void Start()
	{
		seekFreq = rand.NextFloat(minseekFreq, maxseekFreq);
	}

	private void OnEnable()
	{
		if (seekOnEnable)
		{
			seek();
		}
		if (nsRand != null)
		{
			nsRand.Dispatch += NsRand_Dispatch;
		}
	}

	private void OnDisable()
	{
		if (nsRand != null)
		{
			nsRand.Dispatch -= NsRand_Dispatch;
		}
	}

	private void NsRand_Dispatch(RandomDispatcher randomDispatcher)
	{
		seek();
	}

	private void Update()
	{
		if (!(nsRand != null))
		{
			timeSinceSeek += Time.deltaTime;
			if (timeSinceSeek > seekFreq)
			{
				seek();
				timeSinceSeek = 0f;
				seekFreq = rand.NextFloat(minseekFreq, maxseekFreq);
			}
		}
	}

	private void seek()
	{
		float num = Mathf.Max(base.transform.lossyScale.x, base.transform.lossyScale.y, base.transform.lossyScale.z);
		if (Physics.Raycast(base.transform.position, base.transform.forward, out var hitInfo, maxRadias * num) && colliderFound != null)
		{
			colliderFound.Invoke(base.transform.position, hitInfo.point);
		}
	}
}
public class ReportTargetHit : MonoBehaviour
{
	private static SRand rand = new SRand("ReportForwardHit");

	[SerializeField]
	private float minseekFreq = 3f;

	[SerializeField]
	private float maxseekFreq = 6f;

	[SerializeField]
	private Transform[] targets;

	[SerializeField]
	private LightningDispatcherEvent colliderFound;

	private float timeSinceSeek;

	private float seekFreq;

	[SerializeField]
	private RandomDispatcher nsRand;

	private void Start()
	{
		seekFreq = rand.NextFloat(minseekFreq, maxseekFreq);
	}

	private void OnEnable()
	{
		if (nsRand != null)
		{
			nsRand.Dispatch += NsRand_Dispatch;
		}
	}

	private void OnDisable()
	{
		if (nsRand != null)
		{
			nsRand.Dispatch -= NsRand_Dispatch;
		}
	}

	private void NsRand_Dispatch(RandomDispatcher randomDispatcher)
	{
		seek();
	}

	private void Update()
	{
		if (!(nsRand != null))
		{
			timeSinceSeek += Time.deltaTime;
			if (timeSinceSeek > seekFreq)
			{
				seek();
				timeSinceSeek = 0f;
				seekFreq = rand.NextFloat(minseekFreq, maxseekFreq);
