	[Serializable]
	public struct RelativeDateTime
	{
		public int DaysPast;

		public int Hours;

		public int Minutes;

		public int Seconds;
	}

	public static DateTime ReferenceDate = DateTime.Parse("1/1/2001");

	public static bool UpdatedReferenceDateFromTitleData = false;

	[SerializeField]
	private string titleDataKey;

	[SerializeField]
	private string titleDataObjectID;

	private TitleDataObjectActivationData activationData;

	private GameObject[] gameObjects;

	private bool initialized;

	private bool onOffState;

	[RuntimeInitializeOnLoadMethod]
	private static async void RuntimeInit()
	{
		ReferenceDate = DateTime.Parse("1/1/2001");
		UpdatedReferenceDateFromTitleData = false;
		while (PlayFabTitleDataCache.Instance == null)
		{
			await Task.Yield();
		}
		PlayFabTitleDataCache.Instance.GetTitleData("ActivationReferenceDate", onTDReferenceDate, onTDReferenceDateError);
	}

	private static void onTDReferenceDate(string s)
	{
		if (!DateTime.TryParse(s, out ReferenceDate))
		{
			UnityEngine.Debug.LogError("TitleDataActivation :: onTDReferenceDate :: No Reference Date Set!!");
		}
		else
		{
			UpdatedReferenceDateFromTitleData = true;
		}
	}

	private static void onTDReferenceDateError(PlayFabError error)
	{
		UnityEngine.Debug.LogError("TitleDataActivation :: onTDReferenceDateError :: No Reference Date Set!! :: " + error.ErrorMessage);
	}

	private async void Initialize()
	{
		if (initialized)
		{
			return;
		}
		List<GameObject> list = new List<GameObject>();
		for (int i = 0; i < base.transform.childCount; i++)
		{
			GameObject gameObject = base.transform.GetChild(i).gameObject;
			gameObject.SetActive(value: false);
			list.Add(gameObject);
		}
		gameObjects = list.ToArray();
		initialized = true;
		if (!titleDataKey.IsNullOrEmpty())
		{
			while (PlayFabTitleDataCache.Instance == null || !UpdatedReferenceDateFromTitleData)
			{
				await Task.Yield();
			}
			PlayFabTitleDataCache.Instance.GetTitleData(titleDataKey, onTD, onTDError);
		}
	}

	private void onTD(string s)
	{
		TitleDataActivationData titleDataActivationData = null;
		try
		{
			titleDataActivationData = JsonConvert.DeserializeObject<TitleDataActivationData>(s);
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("TitleDataActivation :: onTD ::" + ex.Message + " string was " + s);
			return;
		}
		for (int i = 0; i < titleDataActivationData.Data.Length; i++)
		{
			if (titleDataActivationData.Data[i].TitleDataObjectID == titleDataObjectID)
			{
				activationData = titleDataActivationData.Data[i];
				break;
			}
		}
	}

	private void onTDError(PlayFabError error)
	{
		UnityEngine.Debug.LogError($"TitleDataActivation on {AssetUtils.GetGameObjectPath(base.gameObject)} :: onTDError :: {titleDataKey} :: {error}");
	}

	private void OnEnable()
	{
		Initialize();
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	private void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	void IGorillaSliceableSimple.SliceUpdate()
	{
		if (activationData == null)
		{
			return;
		}
		DateTime serverTime = GorillaComputer.instance.GetServerTime();
		if (serverTime.Year >= 2000)
		{
			bool inRange = false;
			float delay = 0f;
			int num = 0;
			while (activationData.AbsoluteDateTimeWindow != null && num < activationData.AbsoluteDateTimeWindow.Length && !inRange)
			{
				activationData.AbsoluteDateTimeWindow[num].IsInWindow(serverTime, out inRange, out delay);
				num++;
			}
			int num2 = 0;
			while (activationData.RelativeDateTimeWindow != null && num2 < activationData.RelativeDateTimeWindow.Length && !inRange)
			{
				activationData.RelativeDateTimeWindow[num2].IsInWindow(serverTime, out inRange, out delay);
				num2++;
			}
			if (inRange != onOffState)
			{
				SetState(inRange, delay);
				onOffState = inRange;
			}
		}
	}

	private void SetState(bool onOff, float delayedActivation)
	{
		for (int i = 0; i < gameObjects.Length; i++)
		{
			gameObjects[i].SetActive(onOff);
			if (onOff && delayedActivation > 0f)
			{
				Animator[] componentsInChildren = gameObjects[i].GetComponentsInChildren<Animator>();
				for (int j = 0; j < componentsInChildren.Length; j++)
				{
					int fullPathHash = componentsInChildren[j].GetCurrentAnimatorStateInfo(0).fullPathHash;
					componentsInChildren[j].PlayInFixedTime(fullPathHash, 0, delayedActivation);
				}
			}
		}
	}

	public float GetDelayedActivationTime()
	{
		DateTime serverTime = GorillaComputer.instance.GetServerTime();
		if (serverTime.Year < 2000)
		{
			return 0f;
		}
		bool inRange = false;
		float delay = 0f;
		int num = 0;
		while (activationData.AbsoluteDateTimeWindow != null && num < activationData.AbsoluteDateTimeWindow.Length && !inRange)
		{
			activationData.AbsoluteDateTimeWindow[num].IsInWindow(serverTime, out inRange, out delay);
			num++;
		}
		int num2 = 0;
		while (activationData.RelativeDateTimeWindow != null && num2 < activationData.RelativeDateTimeWindow.Length && !inRange)
		{
			activationData.RelativeDateTimeWindow[num2].IsInWindow(serverTime, out inRange, out delay);
			num2++;
		}
		return Mathf.Max(0f, delay);
	}

	public void PlayAnimatorAtScheduledTime(Animator animator)
	{
		float delayedActivationTime = GetDelayedActivationTime();
		int fullPathHash = animator.GetCurrentAnimatorStateInfo(0).fullPathHash;
		animator.PlayInFixedTime(fullPathHash, 0, GetDelayedActivationTime());
		AudioSource[] componentsInChildren = animator.GetComponentsInChildren<AudioSource>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (componentsInChildren[i].playOnAwake && componentsInChildren[i].clip != null && componentsInChildren[i].clip.length > delayedActivationTime)
			{
				componentsInChildren[i].time = delayedActivationTime;
			}
		}
	}
}
public class TitleDataDateRefActivation : MonoBehaviour, IGorillaSliceableSimple
{
	private enum ReadyState
	{
		None,
		Initializing,
		Ready,
		Crashed
	}

	[Serializable]
	private class TitleDataDateRefActivationTarget : IComparable<TitleDataDateRefActivationTarget>
	{
		[SerializeField]
		private bool activationState;

		[SerializeField]
		private GameObject gameObject;

		[SerializeField]
		private int hrs;

		[SerializeField]
		private int min;

		[SerializeField]
		private int sec;

		[SerializeField]
		private UnityEvent payload;

		[SerializeField]
		private UnityEvent<float> persistantPayload;

		private DateTime dateTime = DateTime.MaxValue;

		public GameObject GameObject => gameObject;

		public DateTime ActivationTime => dateTime;

		public void Initialize(DateTime refTime)
		{
			dateTime = refTime.AddHours(hrs).AddMinutes(min).AddSeconds(sec);
		}

		public void Activate(DateTime now)
		{
			float late = (float)(now - dateTime).TotalSeconds;
			Activate(late);
		}

		public void Activate()
		{
			Activate(0f);
		}

		private void Activate(float late)
		{
			if (gameObject != null)
			{
				gameObject.SetActive(activationState);
			}
			if (late < 1f)
			{
				payload?.Invoke();
			}
			persistantPayload?.Invoke(late);
		}

		int IComparable<TitleDataDateRefActivationTarget>.CompareTo(TitleDataDateRefActivationTarget other)
		{
			return (hrs * 3600 + min * 60 + sec).CompareTo(other.hrs * 3600 + other.min * 60 + other.sec);
		}
	}

	[SerializeField]
	private string titleDataKey;

	[SerializeField]
	private TitleDataDateRefActivationTarget[] nodes;

	[SerializeField]
	private TMP_Text tmpStatus;

	private ReadyState readyState;

	private List<TitleDataDateRefActivationTarget> nodeList = new List<TitleDataDateRefActivationTarget>();

	private int activations;

	private async void Initialize()
	{
		if (readyState == ReadyState.Initializing || readyState == ReadyState.Ready)
		{
			return;
		}
		readyState = ReadyState.Initializing;
		if (titleDataKey.IsNullOrEmpty())
		{
			onTD("1/1/3001");
			return;
		}
		while (PlayFabTitleDataCache.Instance == null)
		{
			await Task.Yield();
		}
		PlayFabTitleDataCache.Instance.GetTitleData(titleDataKey, onTD, onTDError);
	}

	private void onTD(string s)
	{
		try
		{
			setStartDate(DateTime.Parse(s));
			readyState = ReadyState.Ready;
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.Log("TitleDataDateRefActivation :: onTD :: " + ex.Message + " :: " + ex.StackTrace);
			readyState = ReadyState.Crashed;
		}
	}

	public void StartNow(float delay)
	{
		setStartDate(GorillaComputer.instance.GetServerTime().AddSeconds(delay));
	}

	private void setStartDate(DateTime d)
	{
		nodeList.Clear();
		for (int i = 0; i < nodes.Length; i++)
		{
			nodes[i].Initialize(d);
			nodeList.Add(nodes[i]);
		}
		nodeList.Sort();
		activations = 0;
	}

	private void onTDError(PlayFabError error)
	{
		UnityEngine.Debug.Log($"TitleDataDateRefActivation :: onTDError :: {error}");
		readyState = ReadyState.Crashed;
	}

	private void OnEnable()
	{
		Initialize();
		GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	private void OnDisable()
	{
		GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
	}

	void IGorillaSliceableSimple.SliceUpdate()
	{
		if (readyState != ReadyState.Ready || nodeList.Count == 0)
		{
			return;
		}
		DateTime serverTime = GorillaComputer.instance.GetServerTime();
		if (serverTime.Year >= 2000)
		{
			if (tmpStatus != null)
			{
				tmpStatus.text = $"action {activations + 1} of {nodes.Length} in {nodeList[0].ActivationTime - GorillaComputer.instance.GetServerTime():g} s";
			}
			if (nodeList[0].ActivationTime <= serverTime)
			{
				nodeList[0].Activate(serverTime);
				nodeList.RemoveAt(0);
				activations++;
			}
		}
	}
}
public class TransformOrbiter : MonoBehaviour
{
	[SerializeField]
	private Transform barycenter;

	[SerializeField]
	private UnityEngine.Vector3 orbit;

	[SerializeField]
	private UnityEngine.Vector3 translation;

	[SerializeField]
	[Range(0.01f, 5f)]
	private double speed = 1.0;

	private DateTime anchor = new DateTime(2026, 4, 1);

	private async void Start()
	{
		base.gameObject.SetActive(value: false);
		if (!(barycenter == null))
		{
			while (((bool)base.gameObject && GorillaComputer.instance == null) || GorillaComputer.instance.GetServerTime().Year < 2000)
			{
				await Task.Yield();
			}
			if ((bool)base.gameObject)
			{
				base.gameObject.SetActive(value: true);
			}
		}
	}

	private void LateUpdate()
	{
		double totalSeconds = (GorillaComputer.instance.GetServerTime() - anchor).TotalSeconds;
		double num = (double)orbit.x * System.Math.Sin(totalSeconds * speed);
		double num2 = (double)orbit.y * System.Math.Cos(totalSeconds * speed);
		double num3 = (double)orbit.z * System.Math.Cos(totalSeconds * speed);
		base.transform.position = barycenter.position + translation + new UnityEngine.Vector3((float)num, (float)num2, (float)num3);
	}

	private bool validateBarycenter()
	{
		return validateBarycenter(base.transform);
	}

	private bool validateBarycenter(Transform t)
	{
		if (barycenter == null)
		{
			UnityEngine.Debug.LogError("The Barycenter cannot be null!");
			return false;
		}
		if (barycenter == t)
		{
			UnityEngine.Debug.LogError("You cannot use the TransformOrbiter's own transform, or one nested below it, as its Barycenter!");
			return false;
		}
		for (int i = 0; i < t.childCount; i++)
		{
			if (!validateBarycenter(t.GetChild(i)))
			{
				return false;
			}
		}
		return true;
	}
}
public class TransformOscillation : MonoBehaviour
{
	[SerializeField]
	private UnityEngine.Vector3 PosAmp;

	[SerializeField]
	private UnityEngine.Vector3 PosFreq;

	[SerializeField]
	private UnityEngine.Vector3 RotAmp;

	[SerializeField]
	private UnityEngine.Vector3 RotFreq;

	[SerializeField]
	private bool useServerTime;

	[Header("Rigidbody Motion (optional)")]
	[Tooltip("If true and a Rigidbody is present, applies motion using Rigidbody.MovePosition/MoveRotation in FixedUpdate.")]
	[SerializeField]
	private bool useRigidbodyMotion;

	[SerializeField]
	private Rigidbody targetRigidbody;

	[Header("Activation Timer (optional)")]
	[Tooltip("If true, oscillation only runs for 'activeDurationSeconds' after OnEnable; otherwise it runs indefinitely.")]
	[SerializeField]
	private bool useTimeLimit;

	[SerializeField]
	private float timer = 2f;

	[Header("Start Behavior (optional)")]
	[Tooltip("If true, oscillation starts automatically on OnEnable(). If false, call StartOscillation() manually.")]
	[SerializeField]
	private bool startOnEnable = true;

	private UnityEngine.Vector3 lastPosOffs = UnityEngine.Vector3.zero;

	private UnityEngine.Quaternion lastRotOffs = UnityEngine.Quaternion.identity;

	private UnityEngine.Vector3 offsPos;

	private UnityEngine.Vector3 offsRot;

	private DateTime dt;

	private float startTime;

	private bool isRunning;

	private void Awake()
	{
		if (useRigidbodyMotion && !targetRigidbody)
		{
			targetRigidbody = GetComponent<Rigidbody>();
		}
		lastRotOffs = UnityEngine.Quaternion.identity;
		startTime = Time.time;
		isRunning = false;
	}

	private void OnEnable()
	{
		lastPosOffs = UnityEngine.Vector3.zero;
		lastRotOffs = UnityEngine.Quaternion.identity;
		if (startOnEnable)
		{
			StartOscillation();
		}
		else
		{
			isRunning = false;
		}
	}

	public void StartOscillation()
	{
		startTime = Time.time;
		isRunning = true;
	}

	private float GetTimeSeconds()
	{
		if (!useServerTime)
		{
			return Time.timeSinceLevelLoad;
		}
		if (GorillaComputer.instance == null)
		{
			return Time.timeSinceLevelLoad;
		}
		dt = GorillaComputer.instance.GetServerTime();
		return (float)dt.Minute * 60f + (float)dt.Second + (float)dt.Millisecond / 1000f;
	}

	private void ComputeOffsets(float t)
	{
		offsPos.x = PosAmp.x * Mathf.Sin(t * PosFreq.x);
		offsPos.y = PosAmp.y * Mathf.Sin(t * PosFreq.y);
		offsPos.z = PosAmp.z * Mathf.Sin(t * PosFreq.z);
		offsRot.x = RotAmp.x * Mathf.Sin(t * RotFreq.x);
		offsRot.y = RotAmp.y * Mathf.Sin(t * RotFreq.y);
		offsRot.z = RotAmp.z * Mathf.Sin(t * RotFreq.z);
	}

	private void LateUpdate()
	{
		if (isRunning && (!useTimeLimit || !(Time.time - startTime >= timer)) && (!useRigidbodyMotion || !targetRigidbody))
		{
			float timeSeconds = GetTimeSeconds();
			ComputeOffsets(timeSeconds);
			Transform obj = base.transform;
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Euler(offsRot);
			UnityEngine.Vector3 vector = obj.localPosition - lastPosOffs;
			UnityEngine.Quaternion quaternion3 = obj.localRotation * UnityEngine.Quaternion.Inverse(lastRotOffs);
			obj.localPosition = vector + offsPos;
			obj.localRotation = quaternion3 * quaternion2;
			lastPosOffs = offsPos;
			lastRotOffs = quaternion2;
		}
	}

	private void FixedUpdate()
	{
		if (isRunning && (!useTimeLimit || !(Time.time - startTime >= timer)) && useRigidbodyMotion && (bool)targetRigidbody)
		{
			float timeSeconds = GetTimeSeconds();
			ComputeOffsets(timeSeconds);
			Transform obj = base.transform;
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Euler(offsRot);
			Transform parent = obj.parent;
			UnityEngine.Vector3 vector = (parent ? parent.TransformVector(lastPosOffs) : lastPosOffs);
			UnityEngine.Quaternion rotation = (parent ? (parent.rotation * lastRotOffs * UnityEngine.Quaternion.Inverse(parent.rotation)) : lastRotOffs);
			UnityEngine.Vector3 vector2 = obj.position - vector;
			UnityEngine.Quaternion quaternion3 = obj.rotation * UnityEngine.Quaternion.Inverse(rotation);
			UnityEngine.Vector3 vector3 = (parent ? parent.TransformVector(offsPos) : offsPos);
			UnityEngine.Quaternion quaternion4 = (parent ? (parent.rotation * quaternion2 * UnityEngine.Quaternion.Inverse(parent.rotation)) : quaternion2);
			targetRigidbody.MovePosition(vector2 + vector3);
			targetRigidbody.MoveRotation(quaternion3 * quaternion4);
			lastPosOffs = offsPos;
			lastRotOffs = quaternion2;
		}
	}
}
public class GTMeshData
{
	public Mesh mesh;

	public UnityEngine.Vector3[] vertices;

	public UnityEngine.Vector3[] normals;

	public UnityEngine.Vector4[] tangents;

	public Color32[] colors32;

	public int[] triangles;

	public BoneWeight[] boneWeights;

	public UnityEngine.Vector2[] uv;

	public UnityEngine.Vector2[] uv2;

	public UnityEngine.Vector2[] uv3;

	public UnityEngine.Vector2[] uv4;

	public UnityEngine.Vector2[] uv5;

	public UnityEngine.Vector2[] uv6;

	public UnityEngine.Vector2[] uv7;

	public UnityEngine.Vector2[] uv8;

	public int subMeshCount;

	public GTMeshData(Mesh m)
	{
		mesh = m;
		subMeshCount = m.subMeshCount;
		vertices = m.vertices;
		triangles = m.triangles;
		normals = m.normals;
		tangents = m.tangents;
		colors32 = m.colors32;
		boneWeights = m.boneWeights;
		uv = m.uv;
		uv2 = m.uv2;
		uv3 = m.uv3;
		uv4 = m.uv4;
		uv5 = m.uv5;
		uv6 = m.uv6;
		uv7 = m.uv7;
		uv8 = m.uv8;
	}

	public Mesh ExtractSubmesh(int subMeshIndex, bool optimize = false)
	{
		if (subMeshIndex < 0 || subMeshIndex >= subMeshCount)
		{
			throw new IndexOutOfRangeException("subMeshIndex");
		}
		SubMeshDescriptor subMesh = this.mesh.GetSubMesh(subMeshIndex);
		int firstVertex = subMesh.firstVertex;
		int vertexCount = subMesh.vertexCount;
		MeshTopology topology = subMesh.topology;
		int[] indices = this.mesh.GetIndices(subMeshIndex, applyBaseVertex: false);
		for (int i = 0; i < indices.Length; i++)
		{
			indices[i] -= firstVertex;
		}
		Mesh mesh = new Mesh();
		mesh.indexFormat = ((vertexCount > 65535) ? IndexFormat.UInt32 : IndexFormat.UInt16);
		mesh.SetVertices(vertices, firstVertex, vertexCount);
		mesh.SetIndices(indices, topology, 0);
		mesh.SetNormals(normals, firstVertex, vertexCount);
		mesh.SetTangents(tangents, firstVertex, vertexCount);
		if (!uv.IsNullOrEmpty())
		{
			mesh.SetUVs(0, uv, firstVertex, vertexCount);
		}
		if (!uv2.IsNullOrEmpty())
		{
			mesh.SetUVs(1, uv2, firstVertex, vertexCount);
		}
		if (!uv3.IsNullOrEmpty())
		{
			mesh.SetUVs(2, uv3, firstVertex, vertexCount);
		}
		if (!uv4.IsNullOrEmpty())
		{
			mesh.SetUVs(3, uv4, firstVertex, vertexCount);
		}
		if (!uv5.IsNullOrEmpty())
		{
			mesh.SetUVs(4, uv5, firstVertex, vertexCount);
		}
		if (!uv6.IsNullOrEmpty())
		{
			mesh.SetUVs(5, uv6, firstVertex, vertexCount);
		}
		if (!uv7.IsNullOrEmpty())
		{
			mesh.SetUVs(6, uv7, firstVertex, vertexCount);
		}
		if (!uv8.IsNullOrEmpty())
		{
			mesh.SetUVs(7, uv8, firstVertex, vertexCount);
		}
		if (optimize)
		{
			mesh.Optimize();
			mesh.OptimizeIndexBuffers();
		}
		mesh.RecalculateBounds();
		return mesh;
	}

	public static GTMeshData Parse(Mesh mesh)
	{
		if (mesh == null)
		{
			throw new ArgumentNullException("mesh");
		}
		return new GTMeshData(mesh);
	}
}
[RequireComponent(typeof(RuntimeMeshCombiner))]
public class UberCombiner : MonoBehaviour
{
	[SerializeField]
	private RuntimeMeshCombiner _combiner;

	[Space]
	public GameObject[] meshSources = new GameObject[0];

	[Space]
	public GameObject[] objectsToIgnore = new GameObject[0];

	[NonSerialized]
	[Space]
	private MeshRenderer[] renderersToCombine = new MeshRenderer[0];

	[NonSerialized]
	[Space]
	private List<GameObject> invalidObjects = new List<GameObject>();

	public bool includeInactive;

	private static ShaderHashId _BaseMap = "_BaseMap";

	private void CollectRenderers()
	{
		$"Found {(renderersToCombine = FilterRenderers(meshSources.SelectMany((GameObject g) => g.GetComponentsInChildren<MeshRenderer>(includeInactive)).ToArray()).DistinctBy((MeshRenderer mr) => mr.GetInstanceID()).ToArray()).Length} renderers to combine.".Echo();
	}

	private void ValidateRenderers()
	{
		List<GameObject> list = new List<GameObject>(16);
		for (int i = 0; i < renderersToCombine.Length; i++)
		{
			MeshRenderer meshRenderer = renderersToCombine[i];
			GameObject gameObject = meshRenderer.gameObject;
			string text = gameObject.name;
			MeshFilter component = gameObject.GetComponent<MeshFilter>();
			if (meshRenderer == null || component == null)
			{
				UnityEngine.Debug.LogError("Ojbect '" + text + "' is missing a MeshRenderer, MeshFilter, or both.", gameObject);
				list.Add(gameObject);
				continue;
			}
			Mesh sharedMesh = component.sharedMesh;
			if (sharedMesh == null)
			{
				UnityEngine.Debug.LogError("MeshFilter for '" + text + "' has no shared mesh.", gameObject);
				list.Add(gameObject);
				continue;
			}
			int subMeshCount = sharedMesh.subMeshCount;
			if (subMeshCount == 0)
			{
				UnityEngine.Debug.LogError("Shared mesh for '" + text + "' has 0 submeshes.", gameObject);
				list.Add(gameObject);
				continue;
			}
			if (sharedMesh.vertexCount < 3)
			{
				UnityEngine.Debug.LogError("Shared mesh for '" + text + "' has less than 3 vertices.", gameObject);
				list.Add(gameObject);
				continue;
			}
			Material[] sharedMaterials = meshRenderer.sharedMaterials;
			if (sharedMaterials.IsNullOrEmpty())
			{
				UnityEngine.Debug.LogError("Object '" + text + "' has null or empty shared materials array.", gameObject);
				list.Add(gameObject);
				continue;
			}
			foreach (Material material in sharedMaterials)
			{
				string text2 = material.name;
				Texture mainTexture = material.mainTexture;
				if (!(mainTexture == null) && mainTexture is RenderTexture)
				{
					UnityEngine.Debug.LogError("Object '" + text + "' has material (" + text2 + ") that uses a RenderTexture", gameObject);
					list.Add(gameObject);
					break;
				}
				if (material.HasProperty(_BaseMap))
				{
					Texture texture = material.GetTexture(_BaseMap);
					if (!(texture == null) && texture is RenderTexture)
					{
						UnityEngine.Debug.LogError("Object '" + text + "' has material (" + text2 + ") that uses a RenderTexture", gameObject);
						list.Add(gameObject);
						break;
					}
				}
				if (UberShader.IsAnimated(material))
				{
					UnityEngine.Debug.LogError("Object '" + text + "' has a material (" + text2 + ") that's animated", gameObject);
					list.Add(gameObject);
					break;
				}
			}
			if (subMeshCount != sharedMaterials.Length)
			{
				UnityEngine.Debug.LogError("Object '" + text + "' has mismatched number of materials/submeshes" + $" Submeshes: {subMeshCount} Materials: {sharedMaterials.Length}", gameObject);
				list.Add(gameObject);
			}
		}
		invalidObjects = list.DistinctBy((GameObject g) => g.GetHashCode()).ToList();
	}

	private void SendToCombiner()
	{
		List<GameObject> targetMeshes = (from r in renderersToCombine
			select r.gameObject into g
			where !(g == null)
			where !Enumerable.Contains(objectsToIgnore, g)
			where !invalidObjects.Contains(g)
			select g).DistinctBy((GameObject g) => g.GetInstanceID()).ToList();
		_combiner.targetMeshes = targetMeshes;
	}

	private void MergeMeshes()
	{
		_combiner.CombineMeshes();
	}

	private void UndoMerge()
	{
		_combiner.UndoMerge();
	}

	private void MergeAndExtractPerMaterialMeshes()
	{
		_combiner.onDoneMerge.AddListener(OnPostMerge);
		_combiner.CombineMeshes();
	}

	private void QuickMerge()
	{
		CollectRenderers();
		ValidateRenderers();
		SendToCombiner();
		MergeAndExtractPerMaterialMeshes();
	}

	private void OnPostMerge()
	{
		MeshFilter component = GetComponent<MeshFilter>();
		MeshRenderer component2 = GetComponent<MeshRenderer>();
		Mesh sharedMesh = component.sharedMesh;
		int subMeshCount = sharedMesh.subMeshCount;
		string text = component2.name;
		Material[] sharedMaterials = component2.sharedMaterials;
		GameObject gameObject = new GameObject(text + "_PerMaterialMeshes");
		this.GetOrAddComponent<UberCombinerPerMaterialMeshes>(out var result);
		result.rootObject = gameObject;
		result.objects = new GameObject[subMeshCount];
		result.filters = new MeshFilter[subMeshCount];
		result.renderers = new MeshRenderer[subMeshCount];
		result.materials = new Material[subMeshCount];
		GTMeshData gTMeshData = GTMeshData.Parse(sharedMesh);
		for (int i = 0; i < subMeshCount; i++)
		{
			GameObject gameObject2 = new GameObject($"{i}_{sharedMaterials[i].name}");
			gameObject2.transform.parent = gameObject.transform;
			gameObject2.isStatic = true;
			MeshFilter meshFilter = gameObject2.AddComponent<MeshFilter>();
			MeshRenderer meshRenderer = gameObject2.AddComponent<MeshRenderer>();
			Mesh sharedMesh2 = gTMeshData.ExtractSubmesh(i);
			meshFilter.sharedMesh = sharedMesh2;
			meshRenderer.sharedMaterial = sharedMaterials[i];
			meshRenderer.lightProbeUsage = LightProbeUsage.Off;
			meshRenderer.motionVectorGenerationMode = MotionVectorGenerationMode.ForceNoMotion;
			result.objects[i] = gameObject2;
			result.filters[i] = meshFilter;
			result.renderers[i] = meshRenderer;
			result.materials[i] = sharedMaterials[i];
		}
	}

	private void OnValidate()
	{
		if (!base.transform.position.Approx0())
		{
			base.transform.position = UnityEngine.Vector3.zero;
		}
		if (_combiner == null)
		{
			_combiner = GetComponent<RuntimeMeshCombiner>();
			_combiner.recalculateNormals = false;
			_combiner.recalculateTangents = false;
			_combiner.combineInactives = false;
			_combiner.garbageCollectorAfterUndo = true;
			_combiner.afterMerge = RuntimeMeshCombiner.AfterMerge.DoNothing;
		}
	}

	private static IEnumerable<MeshRenderer> FilterRenderers(IList<MeshRenderer> renderers)
	{
		Shader uberShader = UberShader.ReferenceShader;
		Shader uberShaderNonSRP = UberShader.ReferenceShaderNonSRP;
		RenderQueueRange transQueue = RenderQueueRange.transparent;
		int i = 0;
		while (i < renderers.Count)
		{
			MeshRenderer mr = renderers[i];
			int num;
			if (!(mr == null) && mr.enabled && mr.gameObject.isStatic && !mr.GetComponent<EdDoNotMeshCombine>())
			{
				MeshFilter component = mr.GetComponent<MeshFilter>();
				if (!(component == null))
				{
					Mesh sharedMesh = component.sharedMesh;
					if (!(sharedMesh == null) && sharedMesh.vertexCount >= 3)
					{
						Material[] sharedMats = mr.sharedMaterials;
						if (!sharedMats.IsNullOrEmpty())
						{
							for (int j = 0; j < sharedMats.Length; j = num)
							{
								Material material = sharedMats[j];
								if (!(material == null))
								{
									int renderQueue = material.renderQueue;
									if ((renderQueue < transQueue.lowerBound || renderQueue > transQueue.upperBound) && (renderQueue < 2450 || renderQueue > 2500))
									{
										Shader shader = material.shader;
										if (shader == uberShader)
										{
											yield return mr;
										}
										else if (shader == uberShaderNonSRP)
										{
											yield return mr;
										}
									}
								}
								num = j + 1;
							}
						}
					}
				}
			}
			num = i + 1;
			i = num;
		}
	}
}
