public class ZoneBasedGameObjectActivator : MonoBehaviour
{
	[SerializeField]
	private GTZone[] zones;

	[SerializeField]
	private GameObject[] gameObjects;

	private void OnEnable()
	{
		ZoneManagement.OnZoneChange += ZoneManagement_OnZoneChange;
	}

	private void OnDisable()
	{
		ZoneManagement.OnZoneChange -= ZoneManagement_OnZoneChange;
	}

	private void ZoneManagement_OnZoneChange(ZoneData[] zoneData)
	{
		HashSet<GTZone> hashSet = new HashSet<GTZone>(zones);
		bool flag = false;
		for (int i = 0; i < zoneData.Length; i++)
		{
			flag |= zoneData[i].active && hashSet.Contains(zoneData[i].zone);
		}
		for (int j = 0; j < gameObjects.Length; j++)
		{
			gameObjects[j].SetActive(flag);
		}
	}
}
public class BoundsCalcs : MonoBehaviour
{
	public MeshFilter[] optionalTargets = new MeshFilter[0];

	public bool useRootMeshOnly;

	[Space]
	public List<BoundsInfo> elements = new List<BoundsInfo>();

	[Space]
	public BoundsInfo composite;

	[Space]
	private StateHash _state;

	private static MeshFilter[] singleMesh = new MeshFilter[1];

	public void Compute()
	{
		MeshFilter[] array;
		if (!useRootMeshOnly)
		{
			array = ((optionalTargets == null || optionalTargets.Length == 0) ? GetComponentsInChildren<MeshFilter>() : GetComponentsInChildren<MeshFilter>().Concat(optionalTargets).ToArray());
		}
		else
		{
			singleMesh[0] = GetComponent<MeshFilter>();
			array = singleMesh;
		}
		List<Mesh> list = new List<Mesh>((array.Length + 1) / 2);
		List<UnityEngine.Vector3> list2 = new List<UnityEngine.Vector3>(array.Length * 512);
		elements.Clear();
		for (int i = 0; i < array.Length; i++)
		{
			UnityEngine.Matrix4x4 localToWorldMatrix = array[i].transform.localToWorldMatrix;
			Mesh mesh = array[i].sharedMesh;
			if (!mesh.isReadable)
			{
				Mesh mesh2 = mesh.CreateReadableMeshCopy();
				list.Add(mesh2);
				mesh = mesh2;
			}
			UnityEngine.Vector3[] vertices = mesh.vertices;
			for (int j = 0; j < vertices.Length; j++)
			{
				vertices[j] = localToWorldMatrix.MultiplyPoint3x4(vertices[j]);
			}
			BoundsInfo item = BoundsInfo.ComputeBounds(vertices);
			elements.Add(item);
			list2.AddRange(vertices);
		}
		composite = BoundsInfo.ComputeBounds(list2.ToArray());
		list.ForEach(UnityEngine.Object.DestroyImmediate);
	}
}
[Serializable]
public struct BoundsInfo
{
	public UnityEngine.Vector3 center;

	public UnityEngine.Vector3 size;

	public UnityEngine.Quaternion rotation;

	public UnityEngine.Vector3 scale;

	public float inflate;

	[Space]
	public UnityEngine.Vector3 centerAA;

	public UnityEngine.Vector3 sizeAA;

	public UnityEngine.Vector3 scaleAA;

	public float inflateAA;

	public UnityEngine.Vector3 sizeComputed => UnityEngine.Vector3.Scale(size, scale) * inflate;

	public UnityEngine.Vector3 sizeComputedAA => UnityEngine.Vector3.Scale(sizeAA, scaleAA) * inflateAA;

	public static BoundsInfo ComputeBounds(UnityEngine.Vector3[] vertices)
	{
		if (vertices.Length == 0)
		{
			return default(BoundsInfo);
		}
		OrientedBoundingBox orientedBoundingBox = OrientedBoundingBox.BruteEnclosing(vertices);
		UnityEngine.Vector4 column = orientedBoundingBox.Axis1;
		UnityEngine.Vector4 column2 = orientedBoundingBox.Axis2;
		UnityEngine.Vector4 column3 = orientedBoundingBox.Axis3;
		UnityEngine.Vector4 column4 = new UnityEngine.Vector4(0f, 0f, 0f, 1f);
		BoundsInfo result = new BoundsInfo
		{
			center = orientedBoundingBox.Center,
			size = orientedBoundingBox.Extent * 2f,
			rotation = new UnityEngine.Matrix4x4(column, column2, column3, column4).rotation,
			scale = UnityEngine.Vector3.one,
			inflate = 1f
		};
		Bounds bounds = GeometryUtility.CalculateBounds(vertices, UnityEngine.Matrix4x4.identity);
		result.centerAA = bounds.center;
		result.sizeAA = bounds.size;
		result.scaleAA = UnityEngine.Vector3.one;
		result.inflateAA = 1f;
		return result;
	}

	public static BoxCollider CreateBoxCollider(BoundsInfo bounds)
	{
		int hashCode = bounds.center.QuantizedId128().GetHashCode();
		int hashCode2 = bounds.size.QuantizedId128().GetHashCode();
		int hashCode3 = bounds.rotation.QuantizedId128().GetHashCode();
		int num = StaticHash.Compute(hashCode, hashCode2, hashCode3);
		Transform transform = new GameObject($"BoxCollider_{num:X8}").transform;
		transform.position = bounds.center;
		transform.rotation = bounds.rotation;
		BoxCollider boxCollider = transform.gameObject.AddComponent<BoxCollider>();
		boxCollider.size = bounds.sizeComputed;
		return boxCollider;
	}

	public static BoxCollider CreateBoxColliderAA(BoundsInfo bounds)
	{
		int hashCode = bounds.center.QuantizedId128().GetHashCode();
		int hashCode2 = bounds.size.QuantizedId128().GetHashCode();
		int num = StaticHash.Compute(hashCode, hashCode2);
		Transform transform = new GameObject($"BoxCollider_{num:X8}").transform;
		transform.position = bounds.centerAA;
		BoxCollider boxCollider = transform.gameObject.AddComponent<BoxCollider>();
		boxCollider.size = bounds.sizeComputedAA;
		return boxCollider;
	}
}
