[Serializable]
public struct BoundsInt
{
	private const int SCALE_FACTOR = 1000;

	public Vector3Int min;

	public Vector3Int max;

	public Vector3Int center => (min + max) / 2;

	public Vector3Int size => max - min;

	public UnityEngine.Vector3 centerFloat => IntToFloat(center);

	public UnityEngine.Vector3 sizeFloat => IntToFloat(size);

	public BoundsInt(Vector3Int min, Vector3Int max)
	{
		this.min = min;
		this.max = max;
	}

	public BoundsInt(UnityEngine.Vector3 center, UnityEngine.Vector3 size)
	{
		UnityEngine.Vector3 vector = size * 0.5f;
		min = FloatToInt(center - vector);
		max = FloatToInt(center + vector);
	}

	public static Vector3Int FloatToInt(UnityEngine.Vector3 v)
	{
		return new Vector3Int(Mathf.RoundToInt(v.x * 1000f), Mathf.RoundToInt(v.y * 1000f), Mathf.RoundToInt(v.z * 1000f));
	}

	public static UnityEngine.Vector3 IntToFloat(Vector3Int v)
	{
		return new UnityEngine.Vector3((float)v.x / 1000f, (float)v.y / 1000f, (float)v.z / 1000f);
	}

	public static BoundsInt FromBounds(Bounds bounds)
	{
		return new BoundsInt(bounds.center, bounds.size);
	}

	public Bounds ToBounds()
	{
		return new Bounds(centerFloat, sizeFloat);
	}

	public void SetMinMax(Vector3Int min, Vector3Int max)
	{
		this.min = min;
		this.max = max;
	}

	public void SetMinMax(UnityEngine.Vector3 min, UnityEngine.Vector3 max)
	{
		this.min = FloatToInt(min);
		this.max = FloatToInt(max);
	}

	public void Encapsulate(BoundsInt other)
	{
		min = new Vector3Int(Mathf.Min(min.x, other.min.x), Mathf.Min(min.y, other.min.y), Mathf.Min(min.z, other.min.z));
		max = new Vector3Int(Mathf.Max(max.x, other.max.x), Mathf.Max(max.y, other.max.y), Mathf.Max(max.z, other.max.z));
	}

	public void Expand(float amount)
	{
		int num = Mathf.RoundToInt(amount * 1000f);
		Vector3Int vector3Int = new Vector3Int(num, num, num);
		min -= vector3Int;
		max += vector3Int;
	}

	public bool Intersects(BoundsInt other)
	{
		if (min.x < other.max.x && max.x > other.min.x && min.y < other.max.y && max.y > other.min.y)
		{
			if (min.z < other.max.z)
			{
				return max.z > other.min.z;
			}
			return false;
		}
		return false;
	}

	public bool Contains(BoundsInt other)
	{
		if (min.x <= other.min.x && min.y <= other.min.y && min.z <= other.min.z && max.x >= other.max.x && max.y >= other.max.y)
		{
			return max.z >= other.max.z;
		}
		return false;
	}

	public bool Contains(UnityEngine.Vector3 point)
	{
		Vector3Int vector3Int = FloatToInt(point);
		if (vector3Int.x >= min.x && vector3Int.x <= max.x && vector3Int.y >= min.y && vector3Int.y <= max.y && vector3Int.z >= min.z)
		{
			return vector3Int.z <= max.z;
		}
		return false;
	}

	public BoundsInt GetIntersection(BoundsInt other)
	{
		Vector3Int vector3Int = new Vector3Int(Mathf.Max(min.x, other.min.x), Mathf.Max(min.y, other.min.y), Mathf.Max(min.z, other.min.z));
		Vector3Int vector3Int2 = new Vector3Int(Mathf.Min(max.x, other.max.x), Mathf.Min(max.y, other.max.y), Mathf.Min(max.z, other.max.z));
		if (vector3Int.x > vector3Int2.x || vector3Int.y > vector3Int2.y || vector3Int.z > vector3Int2.z)
		{
			return new BoundsInt(Vector3Int.zero, Vector3Int.zero);
		}
		return new BoundsInt(vector3Int, vector3Int2);
	}

	public long Volume()
	{
		Vector3Int vector3Int = size;
		return (long)vector3Int.x * (long)vector3Int.y * vector3Int.z;
	}

	public float VolumeFloat()
	{
		return (float)Volume() / 1E+09f;
	}

	public static bool operator ==(BoundsInt a, BoundsInt b)
	{
		if (a.min == b.min)
		{
			return a.max == b.max;
		}
		return false;
	}

	public static bool operator !=(BoundsInt a, BoundsInt b)
	{
		return !(a == b);
	}

	public override bool Equals(object obj)
	{
		if (obj is BoundsInt boundsInt)
		{
			return this == boundsInt;
		}
		return false;
	}

	public override int GetHashCode()
	{
		return min.GetHashCode() ^ (max.GetHashCode() << 2);
	}

	public override string ToString()
	{
		return $"BoundsInt(min: {min}, max: {max})";
	}
}
public static class BoxColliderUtils
{
	public static UnityEngine.Matrix4x4 GetWorldToNormalizedBoxMatrix(BoxCollider boxCollider)
	{
		Transform transform = boxCollider.transform;
		UnityEngine.Vector3 center = boxCollider.center;
		UnityEngine.Vector3 size = boxCollider.size;
		UnityEngine.Matrix4x4 worldToLocalMatrix = transform.worldToLocalMatrix;
		UnityEngine.Matrix4x4 matrix4x = UnityEngine.Matrix4x4.Translate(-center);
		return UnityEngine.Matrix4x4.Scale(new UnityEngine.Vector3((size.x != 0f) ? (2f / size.x) : 1f, (size.y != 0f) ? (2f / size.y) : 1f, (size.z != 0f) ? (2f / size.z) : 1f)) * matrix4x * worldToLocalMatrix;
	}

	public static bool DoesBoxContainPoint(BoxCollider boxCollider, UnityEngine.Vector3 worldPoint)
	{
		UnityEngine.Vector3 vector = GetWorldToNormalizedBoxMatrix(boxCollider).MultiplyPoint3x4(worldPoint);
		if (Mathf.Abs(vector.x) <= 1f && Mathf.Abs(vector.y) <= 1f)
		{
			return Mathf.Abs(vector.z) <= 1f;
		}
		return false;
	}

	public static bool DoesBoxContainBox(BoxCollider containerBox, BoxCollider containedBox)
	{
		Transform transform = containedBox.transform;
		UnityEngine.Vector3 vector = transform.TransformPoint(containedBox.center);
		UnityEngine.Vector3 vector2 = containedBox.size * 0.5f;
		UnityEngine.Vector3 vector3 = transform.TransformVector(new UnityEngine.Vector3(vector2.x, 0f, 0f));
		UnityEngine.Vector3 vector4 = transform.TransformVector(new UnityEngine.Vector3(0f, vector2.y, 0f));
		UnityEngine.Vector3 vector5 = transform.TransformVector(new UnityEngine.Vector3(0f, 0f, vector2.z));
		if (!DoesBoxContainPoint(containerBox, vector - vector3 - vector4 - vector5) || !DoesBoxContainPoint(containerBox, vector + vector3 - vector4 - vector5) || !DoesBoxContainPoint(containerBox, vector - vector3 + vector4 - vector5) || !DoesBoxContainPoint(containerBox, vector + vector3 + vector4 - vector5) || !DoesBoxContainPoint(containerBox, vector - vector3 - vector4 + vector5) || !DoesBoxContainPoint(containerBox, vector + vector3 - vector4 + vector5) || !DoesBoxContainPoint(containerBox, vector - vector3 + vector4 + vector5) || !DoesBoxContainPoint(containerBox, vector + vector3 + vector4 + vector5))
		{
			return false;
		}
		return true;
	}

	public static bool DoesBoxContainRegion(BoxCollider box, BoundsInt regionBounds)
	{
		UnityEngine.Matrix4x4 worldToNormalizedBoxMatrix = GetWorldToNormalizedBoxMatrix(box);
		UnityEngine.Vector3 vector = BoundsInt.IntToFloat(regionBounds.min);
		UnityEngine.Vector3 vector2 = BoundsInt.IntToFloat(regionBounds.max);
		UnityEngine.Vector3[] array = new UnityEngine.Vector3[8]
		{
			new UnityEngine.Vector3(vector.x, vector.y, vector.z),
			new UnityEngine.Vector3(vector2.x, vector.y, vector.z),
			new UnityEngine.Vector3(vector.x, vector2.y, vector.z),
			new UnityEngine.Vector3(vector2.x, vector2.y, vector.z),
			new UnityEngine.Vector3(vector.x, vector.y, vector2.z),
			new UnityEngine.Vector3(vector2.x, vector.y, vector2.z),
			new UnityEngine.Vector3(vector.x, vector2.y, vector2.z),
			new UnityEngine.Vector3(vector2.x, vector2.y, vector2.z)
		};
		foreach (UnityEngine.Vector3 point in array)
		{
			UnityEngine.Vector3 vector3 = worldToNormalizedBoxMatrix.MultiplyPoint3x4(point);
			if (Mathf.Abs(vector3.x) > 1f || Mathf.Abs(vector3.y) > 1f || Mathf.Abs(vector3.z) > 1f)
			{
				return false;
			}
		}
		return true;
	}
}
public class BspTestPlayer : MonoBehaviour
{
	[Header("Movement")]
	[SerializeField]
	private float moveSpeed = 5f;

	[SerializeField]
	private bool use3DMovement;

	[Header("UI")]
	[SerializeField]
	private TextMeshPro zoneDisplayText;

	[SerializeField]
	private TextMeshPro positionDisplayText;

	[Header("BSP")]
	[SerializeField]
	private ZoneGraphBSP bspSystem;

	private string currentZoneName = "None";

	private ZoneDef currentZone;

	private void Start()
	{
		if (bspSystem == null)
		{
			bspSystem = UnityEngine.Object.FindObjectOfType<ZoneGraphBSP>();
		}
		if (zoneDisplayText == null)
		{
			CreateUI();
		}
	}

	private void Update()
	{
		HandleMovement();
		UpdateZoneInfo();
		UpdateUI();
	}

	private void HandleMovement()
	{
		UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
		if (Input.GetKey(KeyCode.LeftArrow) || Input.GetKey(KeyCode.A))
		{
			zero.x -= 1f;
		}
		if (Input.GetKey(KeyCode.RightArrow) || Input.GetKey(KeyCode.D))
		{
			zero.x += 1f;
		}
		if (Input.GetKey(KeyCode.UpArrow) || Input.GetKey(KeyCode.W))
		{
			if (use3DMovement)
			{
				zero.z += 1f;
			}
			else
			{
				zero.y += 1f;
			}
		}
		if (Input.GetKey(KeyCode.DownArrow) || Input.GetKey(KeyCode.S))
		{
			if (use3DMovement)
			{
				zero.z -= 1f;
			}
			else
			{
				zero.y -= 1f;
			}
		}
		if (use3DMovement)
		{
			if (Input.GetKey(KeyCode.Q))
			{
				zero.y += 1f;
			}
			if (Input.GetKey(KeyCode.E))
			{
				zero.y -= 1f;
			}
		}
		if (zero != UnityEngine.Vector3.zero)
		{
			zero = zero.normalized * moveSpeed * Time.deltaTime;
			base.transform.position += zero;
		}
	}

	private void UpdateZoneInfo()
	{
		if (bspSystem == null)
		{
			return;
		}
		ZoneDef zoneDef = bspSystem.FindZoneAtPoint(base.transform.position);
		if (zoneDef != currentZone)
		{
			currentZone = zoneDef;
			currentZoneName = ((zoneDef != null) ? zoneDef.gameObject.name : "None");
			if (zoneDef != null)
			{
				UnityEngine.Debug.Log("Player entered zone: " + currentZoneName);
			}
			else
			{
				UnityEngine.Debug.Log("Player left all zones");
			}
		}
	}

	private void UpdateUI()
	{
		if (zoneDisplayText != null)
		{
			zoneDisplayText.text = "Current Zone: " + currentZoneName;
		}
		if (positionDisplayText != null)
		{
			UnityEngine.Vector3 position = base.transform.position;
			positionDisplayText.text = $"Position: ({position.x:F1}, {position.y:F1}, {position.z:F1})";
		}
	}

	private void CreateUI()
	{
		GameObject gameObject = new GameObject("Zone Display");
		zoneDisplayText = gameObject.AddComponent<TextMeshPro>();
		zoneDisplayText.text = "Current Zone: None";
		zoneDisplayText.fontSize = 24f;
		zoneDisplayText.color = Color.white;
		zoneDisplayText.autoSizeTextContainer = true;
		gameObject.transform.position = Camera.main.transform.position + Camera.main.transform.forward * 5f + UnityEngine.Vector3.up * 3f + UnityEngine.Vector3.left * 2f;
		gameObject.transform.LookAt(Camera.main.transform);
		gameObject.transform.Rotate(0f, 180f, 0f);
		GameObject gameObject2 = new GameObject("Position Display");
		positionDisplayText = gameObject2.AddComponent<TextMeshPro>();
		positionDisplayText.text = "Position: (0, 0, 0)";
		positionDisplayText.fontSize = 18f;
		positionDisplayText.color = Color.yellow;
		positionDisplayText.autoSizeTextContainer = true;
		gameObject2.transform.position = Camera.main.transform.position + Camera.main.transform.forward * 5f + UnityEngine.Vector3.up * 2.5f + UnityEngine.Vector3.left * 2f;
		gameObject2.transform.LookAt(Camera.main.transform);
		gameObject2.transform.Rotate(0f, 180f, 0f);
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = ((currentZone != null) ? Color.green : Color.red);
		Gizmos.DrawWireSphere(base.transform.position, 0.5f);
		if (currentZone != null)
		{
			Gizmos.color = Color.cyan;
			Gizmos.DrawWireCube(base.transform.position + UnityEngine.Vector3.up * 2f, UnityEngine.Vector3.one * 0.3f);
		}
		if (bspSystem != null && bspSystem.HasCompiledTree())
		{
			DrawBSPSplits();
		}
	}

	private void DrawBSPSplits()
	{
		SerializableBSPTree bSPTree = bspSystem.GetBSPTree();
		if (bSPTree?.nodes == null)
		{
			return;
		}
		BoxCollider[] array = UnityEngine.Object.FindObjectsOfType<BoxCollider>();
		if (array.Length != 0)
		{
			Bounds bounds = new Bounds(array[0].bounds.center, array[0].bounds.size);
			BoxCollider[] array2 = array;
			foreach (BoxCollider boxCollider in array2)
			{
				bounds.Encapsulate(boxCollider.bounds);
			}
			bounds.Expand(2f);
			DrawPlayerPath(bSPTree, base.transform.position, bSPTree.rootIndex, bounds, 0);
		}
	}

	private void DrawPlayerPath(SerializableBSPTree tree, UnityEngine.Vector3 playerPos, int nodeIndex, Bounds bounds, int depth)
	{
		if (nodeIndex >= tree.nodes.Length || depth >= tree.nodes.Length)
		{
			return;
		}
		SerializableBSPNode serializableBSPNode = tree.nodes[nodeIndex];
		Gizmos.color = GetAxisColor(serializableBSPNode.axis, depth);
		if (serializableBSPNode.axis == SerializableBSPNode.Axis.Zone)
		{
			Gizmos.color = new Color(0f, 1f, 0f, 0.5f);
			Gizmos.DrawWireCube(bounds.center, bounds.size);
			return;
		}
		MatrixZonePair matrixZonePair;
		int num;
		Color color;
		if (serializableBSPNode.axis == SerializableBSPNode.Axis.MatrixChain || serializableBSPNode.axis == SerializableBSPNode.Axis.MatrixFinal)
		{
			if (serializableBSPNode.matrixIndex >= 0 && serializableBSPNode.matrixIndex < tree.matrices.Length)
			{
				matrixZonePair = tree.matrices[serializableBSPNode.matrixIndex];
				UnityEngine.Vector3 vector = matrixZonePair.matrix.MultiplyPoint3x4(playerPos);
				if (Mathf.Abs(vector.x) <= 1f && Mathf.Abs(vector.y) <= 1f)
				{
					num = ((Mathf.Abs(vector.z) <= 1f) ? 1 : 0);
					if (num != 0)
					{
						color = Color.yellow;
						goto IL_0119;
					}
				}
				else
				{
					num = 0;
				}
				color = Color.red;
				goto IL_0119;
			}
			Gizmos.color = new Color(1f, 0f, 1f, 0.5f);
			Gizmos.DrawWireCube(bounds.center, bounds.size);
			return;
		}
		DrawSplitPlane(serializableBSPNode.axis, serializableBSPNode.splitValue, bounds);
		Bounds bounds2 = bounds;
		Bounds bounds3 = bounds;
		switch (serializableBSPNode.axis)
		{
		case SerializableBSPNode.Axis.X:
			bounds2.SetMinMax(bounds.min, new UnityEngine.Vector3(serializableBSPNode.splitValue, bounds.max.y, bounds.max.z));
			bounds3.SetMinMax(new UnityEngine.Vector3(serializableBSPNode.splitValue, bounds.min.y, bounds.min.z), bounds.max);
			break;
		case SerializableBSPNode.Axis.Y:
			bounds2.SetMinMax(bounds.min, new UnityEngine.Vector3(bounds.max.x, serializableBSPNode.splitValue, bounds.max.z));
			bounds3.SetMinMax(new UnityEngine.Vector3(bounds.min.x, serializableBSPNode.splitValue, bounds.min.z), bounds.max);
			break;
		case SerializableBSPNode.Axis.Z:
			bounds2.SetMinMax(bounds.min, new UnityEngine.Vector3(bounds.max.x, bounds.max.y, serializableBSPNode.splitValue));
			bounds3.SetMinMax(new UnityEngine.Vector3(bounds.min.x, bounds.min.y, serializableBSPNode.splitValue), bounds.max);
			break;
		}
		if (GetAxisValue(playerPos, serializableBSPNode.axis) < serializableBSPNode.splitValue)
		{
			DrawPlayerPath(tree, playerPos, serializableBSPNode.leftChildIndex, bounds2, depth + 1);
		}
		else
		{
			DrawPlayerPath(tree, playerPos, serializableBSPNode.rightChildIndex, bounds3, depth + 1);
		}
		return;
		IL_0119:
		Gizmos.color = color;
		UnityEngine.Matrix4x4 matrix = Gizmos.matrix;
		Gizmos.matrix = matrixZonePair.matrix.inverse;
		Gizmos.DrawWireCube(UnityEngine.Vector3.zero, UnityEngine.Vector3.one * 2f);
		Gizmos.matrix = matrix;
		if (num == 0 && serializableBSPNode.axis == SerializableBSPNode.Axis.MatrixChain)
		{
			DrawPlayerPath(tree, playerPos, serializableBSPNode.outsideChildIndex, bounds, depth + 1);
		}
	}

	private float GetAxisValue(UnityEngine.Vector3 point, SerializableBSPNode.Axis axis)
	{
		return axis switch
		{
			SerializableBSPNode.Axis.X => point.x, 
			SerializableBSPNode.Axis.Y => point.y, 
			SerializableBSPNode.Axis.Z => point.z, 
			SerializableBSPNode.Axis.MatrixChain => 0f, 
			SerializableBSPNode.Axis.MatrixFinal => 0f, 
			SerializableBSPNode.Axis.Zone => 0f, 
			_ => 0f, 
		};
	}

	private void DrawSplitPlane(SerializableBSPNode.Axis axis, float splitValue, Bounds bounds)
	{
		UnityEngine.Vector3 center = bounds.center;
		_ = bounds.size;
		switch (axis)
		{
		case SerializableBSPNode.Axis.X:
			center.x = splitValue;
			Gizmos.DrawLine(new UnityEngine.Vector3(splitValue, bounds.min.y, bounds.min.z), new UnityEngine.Vector3(splitValue, bounds.max.y, bounds.max.z));
			Gizmos.DrawLine(new UnityEngine.Vector3(splitValue, bounds.max.y, bounds.min.z), new UnityEngine.Vector3(splitValue, bounds.min.y, bounds.max.z));
			break;
		case SerializableBSPNode.Axis.Y:
			center.y = splitValue;
			Gizmos.DrawLine(new UnityEngine.Vector3(bounds.min.x, splitValue, bounds.min.z), new UnityEngine.Vector3(bounds.max.x, splitValue, bounds.max.z));
			Gizmos.DrawLine(new UnityEngine.Vector3(bounds.max.x, splitValue, bounds.min.z), new UnityEngine.Vector3(bounds.min.x, splitValue, bounds.max.z));
			break;
		case SerializableBSPNode.Axis.Z:
			center.z = splitValue;
			Gizmos.DrawLine(new UnityEngine.Vector3(bounds.min.x, bounds.min.y, splitValue), new UnityEngine.Vector3(bounds.max.x, bounds.max.y, splitValue));
			Gizmos.DrawLine(new UnityEngine.Vector3(bounds.max.x, bounds.min.y, splitValue), new UnityEngine.Vector3(bounds.min.x, bounds.max.y, splitValue));
			break;
		}
	}

	private Color GetAxisColor(SerializableBSPNode.Axis axis, int depth)
	{
		float a = 1f - (float)depth * 0.15f;
		a = Mathf.Max(a, 0.3f);
		return axis switch
		{
			SerializableBSPNode.Axis.X => new Color(1f, 0f, 0f, a), 
			SerializableBSPNode.Axis.Y => new Color(0f, 1f, 0f, a), 
			SerializableBSPNode.Axis.Z => new Color(0f, 0f, 1f, a), 
			SerializableBSPNode.Axis.MatrixChain => new Color(1f, 0f, 1f, a), 
			SerializableBSPNode.Axis.MatrixFinal => new Color(0.5f, 0f, 1f, a), 
			SerializableBSPNode.Axis.Zone => new Color(0f, 1f, 0f, a), 
			_ => new Color(1f, 1f, 1f, a), 
		};
	}
}
public static class BSPTreeBuilder
{
	public class BoxMetadata
	{
		public BoxCollider box;

		public ZoneDef zone;

		public int matrixIndex;

		public int priority;

		public readonly BoundsInt bounds;

		public BoxMetadata(BoxCollider boxCollider, ZoneDef zoneData, int matrixIdx, int priority)
		{
			box = boxCollider;
			zone = zoneData;
			matrixIndex = matrixIdx;
			bounds = BoundsInt.FromBounds(boxCollider.bounds);
			this.priority = priority;
		}

		public bool ContainsPoint(UnityEngine.Vector3 worldPoint)
		{
			UnityEngine.Vector3 vector = box.transform.InverseTransformPoint(worldPoint);
			UnityEngine.Vector3 size = box.size;
			UnityEngine.Vector3 center = box.center;
			UnityEngine.Vector3 vector2 = center - size * 0.5f;
			UnityEngine.Vector3 vector3 = center + size * 0.5f;
			if (vector.x >= vector2.x && vector.x <= vector3.x && vector.y >= vector2.y && vector.y <= vector3.y && vector.z >= vector2.z)
			{
				return vector.z <= vector3.z;
			}
			return false;
		}

		public BoundsInt GetWorldBounds()
		{
			return bounds;
		}
	}

	private const int MAX_ZONES_PER_LEAF = 10;

	private const int MAX_DEPTH = 15;

	private const int MAX_NODES = 650;

	private static UnityEngine.Vector3 testPoint = new UnityEngine.Vector3(60f, 49f, -98f);

	public static SerializableBSPTree BuildTree(ZoneDef[] zones)
	{
		List<BoxMetadata> list = new List<BoxMetadata>();
		List<MatrixZonePair> list2 = new List<MatrixZonePair>();
		new List<BoxCollider>();
		for (int i = 0; i < zones.Length; i++)
		{
			ZoneDef zoneDef = zones[i];
			List<BoxCollider> list3 = new List<BoxCollider>();
			zoneDef.GetComponents(list3);
			list3.AddRange(zoneDef.transform.GetComponentsInChildren<BoxCollider>());
			UnityEngine.Debug.Log($"SerializableBSPTree zone {zoneDef.zoneId}/{zoneDef.subZoneId} box count {list3.Count}");
			foreach (BoxCollider item3 in list3)
			{
				int count = list2.Count;
				int zoneIndex = Array.IndexOf(zones.ToArray(), zoneDef);
				list2.Add(new MatrixZonePair
				{
					matrix = BoxColliderUtils.GetWorldToNormalizedBoxMatrix(item3),
					zoneIndex = zoneIndex
				});
				list.Add(new BoxMetadata(item3, zoneDef, count, zones.Length - i));
			}
		}
		if (list.Count == 0)
		{
			return null;
		}
		List<SerializableBSPNode> list4 = new List<SerializableBSPNode>();
		List<MatrixBSPNode> list5 = new List<MatrixBSPNode>();
		Dictionary<(int, int), int> matrixNodeCache = new Dictionary<(int, int), int>();
		int matrixNodeCacheHits = 0;
		list5.Add(new MatrixBSPNode
		{
			matrixIndex = -1,
			outsideChildIndex = 0
		});
		BoundsInt bounds = CalculateWorldBounds(list);
		int num = BuildTreeRecursive(zones.ToArray(), list, bounds, 0, SerializableBSPNode.Axis.X, list4, list5, matrixNodeCache, ref matrixNodeCacheHits);
		CleanupUnreferencedMatrices(list5, list2);
		List<SerializableBSPNode> list6 = new List<SerializableBSPNode>(list4);
		int count2 = list6.Count;
		for (int j = 0; j < list5.Count; j++)
		{
			MatrixBSPNode matrixBSPNode = list5[j];
			if (matrixBSPNode.matrixIndex < 0)
			{
				SerializableBSPNode item = new SerializableBSPNode
				{
					axis = SerializableBSPNode.Axis.Zone,
					splitValue = 0f,
					leftChildIndex = (short)matrixBSPNode.outsideChildIndex,
					rightChildIndex = 0
				};
				list6.Add(item);
			}
			else
			{
				bool flag = matrixBSPNode.outsideChildIndex >= 0;
				SerializableBSPNode item2 = new SerializableBSPNode
				{
					axis = (flag ? SerializableBSPNode.Axis.MatrixFinal : SerializableBSPNode.Axis.MatrixChain),
					splitValue = 0f,
					leftChildIndex = (short)matrixBSPNode.matrixIndex,
					rightChildIndex = (short)(flag ? matrixBSPNode.outsideChildIndex : (count2 - matrixBSPNode.outsideChildIndex))
				};
				list6.Add(item2);
			}
		}
		for (int k = 0; k < list6.Count; k++)
		{
			SerializableBSPNode value = list6[k];
			bool flag2 = false;
			SerializableBSPNode.Axis axis = value.axis;
			if ((uint)axis <= 2u)
			{
				if (value.leftChildIndex < 0)
				{
					value.leftChildIndex = (short)(count2 - value.leftChildIndex);
					flag2 = true;
				}
				if (value.rightChildIndex < 0)
				{
					value.rightChildIndex = (short)(count2 - value.rightChildIndex);
					flag2 = true;
				}
			}
			if (flag2)
			{
				list6[k] = value;
			}
		}
		if (num < 0)
		{
			num = count2 - num;
		}
		SerializableBSPTree serializableBSPTree = new SerializableBSPTree();
		serializableBSPTree.nodes = list6.ToArray();
		serializableBSPTree.matrices = list2.ToArray();
		serializableBSPTree.zones = zones.ToArray();
		serializableBSPTree.rootIndex = num;
		int num2 = serializableBSPTree.nodes.Length * 12;
		int num3 = serializableBSPTree.matrices.Length * 68;
		int num4 = num2 + num3;
		UnityEngine.Debug.Log($"Unified BSP Tree generated: {serializableBSPTree.nodes.Length} total nodes ({list4.Count} spatial + {list5.Count} matrix) ({num2} bytes), {serializableBSPTree.matrices.Length} matrix-zone pairs ({num3} bytes). Matrix nodes deduplicated: {matrixNodeCacheHits}. Total: {num4} bytes");
		return serializableBSPTree;
	}

	private static int BuildTreeRecursive(ZoneDef[] zones, List<BoxMetadata> boxes, BoundsInt bounds, int depth, SerializableBSPNode.Axis axis, List<SerializableBSPNode> nodeList, List<MatrixBSPNode> matrixNodeList, Dictionary<(int matrixIndex, int outsideIndex), int> matrixNodeCache, ref int matrixNodeCacheHits)
	{
		UnityEngine.Debug.Log($"Building node at depth {depth} with {boxes.Count} boxes, total nodes so far: {nodeList.Count}");
		int count = nodeList.Count;
		if (bounds.Contains(testPoint))
		{
			_ = 1;
		}
		List<BoxMetadata> list = new List<BoxMetadata>();
		int num = -1;
		foreach (BoxMetadata box in boxes)
		{
			if (box.bounds.GetIntersection(bounds) == bounds && BoxColliderUtils.DoesBoxContainRegion(box.box, bounds))
			{
				list.Add(box);
				num = Mathf.Max(box.priority);
			}
		}
		if (list.Count > 1)
		{
			foreach (BoxMetadata item in list)
			{
				if (item.priority < num)
				{
					boxes.Remove(item);
				}
				else if (item.priority == num)
				{
					num++;
				}
			}
		}
		bool flag = true;
		for (int i = 1; i < boxes.Count; i++)
		{
			BoxMetadata boxMetadata = boxes[i];
			if (boxMetadata.zone != boxes[0].zone)
			{
				flag = false;
				break;
			}
			if (boxMetadata.bounds.GetIntersection(bounds) == bounds)
			{
				list.Add(boxMetadata);
			}
		}
		if (flag || boxes.Count == 1)
		{
			return CreateMatrixNodeTree(zones, boxes, matrixNodeList, bounds, matrixNodeCache, ref matrixNodeCacheHits);
		}
		if (depth >= 15)
		{
			UnityEngine.Debug.LogWarning($"Maximum depth {15} reached with {boxes.Count} boxes, creating matrix node tree");
			return CreateMatrixNodeTree(zones, boxes, matrixNodeList, bounds, matrixNodeCache, ref matrixNodeCacheHits);
		}
		if (nodeList.Count >= 650)
		{
			UnityEngine.Debug.LogWarning($"Maximum nodes {650} reached, creating matrix node tree");
			return CreateMatrixNodeTree(zones, boxes, matrixNodeList, bounds, matrixNodeCache, ref matrixNodeCacheHits);
		}
		if (boxes.Count <= 10)
		{
			UnityEngine.Debug.Log($"Creating matrix node tree with {boxes.Count} boxes at depth {depth}");
			return CreateMatrixNodeTree(zones, boxes, matrixNodeList, bounds, matrixNodeCache, ref matrixNodeCacheHits);
		}
		SerializableBSPNode serializableBSPNode = new SerializableBSPNode
		{
			axis = axis,
			leftChildIndex = -1,
			rightChildIndex = -1
		};
		nodeList.Add(serializableBSPNode);
		int bestSplitValue;
		SerializableBSPNode.Axis axis2 = (serializableBSPNode.axis = FindBestAxis(boxes, bounds, axis, out bestSplitValue));
		serializableBSPNode.splitValue = (float)bestSplitValue / 1000f;
		UnityEngine.Debug.Log($"Best axis: {axis2}, split value: {bestSplitValue}");
		BoundsInt boundsInt = bounds;
		BoundsInt boundsInt2 = bounds;
		switch (axis2)
		{
		case SerializableBSPNode.Axis.X:
			boundsInt.SetMinMax(bounds.min, new Vector3Int(bestSplitValue, bounds.max.y, bounds.max.z));
			boundsInt2.SetMinMax(new Vector3Int(bestSplitValue, bounds.min.y, bounds.min.z), bounds.max);
			break;
		case SerializableBSPNode.Axis.Y:
			boundsInt.SetMinMax(bounds.min, new Vector3Int(bounds.max.x, bestSplitValue, bounds.max.z));
			boundsInt2.SetMinMax(new Vector3Int(bounds.min.x, bestSplitValue, bounds.min.z), bounds.max);
			break;
		case SerializableBSPNode.Axis.Z:
			boundsInt.SetMinMax(bounds.min, new Vector3Int(bounds.max.x, bounds.max.y, bestSplitValue));
			boundsInt2.SetMinMax(new Vector3Int(bounds.min.x, bounds.min.y, bestSplitValue), bounds.max);
			break;
		}
		List<BoxMetadata> effectiveBoxes = GetEffectiveBoxes(boxes, boundsInt);
		List<BoxMetadata> effectiveBoxes2 = GetEffectiveBoxes(boxes, boundsInt2);
		List<BoxMetadata> list2 = new List<BoxMetadata>(effectiveBoxes);
		List<BoxMetadata> list3 = new List<BoxMetadata>(effectiveBoxes2);
		UnityEngine.Debug.Log($"Split result: leftBoxes={list2.Count}, rightBoxes={list3.Count}");
		if (list2.Count == 0 || list3.Count == 0)
		{
			UnityEngine.Debug.Log($"No valid split found, creating matrix node tree with {boxes.Count} boxes");
			return CreateMatrixNodeTree(zones, boxes, matrixNodeList, bounds, matrixNodeCache, ref matrixNodeCacheHits);
		}
		SerializableBSPNode.Axis nextAxis = GetNextAxis(axis);
		serializableBSPNode.leftChildIndex = (short)BuildTreeRecursive(zones, list2, boundsInt, depth + 1, nextAxis, nodeList, matrixNodeList, matrixNodeCache, ref matrixNodeCacheHits);
		serializableBSPNode.rightChildIndex = (short)BuildTreeRecursive(zones, list3, boundsInt2, depth + 1, nextAxis, nodeList, matrixNodeList, matrixNodeCache, ref matrixNodeCacheHits);
		nodeList[count] = serializableBSPNode;
		return count;
	}

	private static SerializableBSPNode.Axis FindBestAxis(List<BoxMetadata> boxes, BoundsInt bounds, SerializableBSPNode.Axis preferredAxis, out int bestSplitValue)
	{
		SerializableBSPNode.Axis[] obj = new SerializableBSPNode.Axis[3]
		{
			preferredAxis,
			GetNextAxis(preferredAxis),
			GetNextAxis(GetNextAxis(preferredAxis))
		};
		SerializableBSPNode.Axis axis = preferredAxis;
		int num = int.MaxValue;
		bestSplitValue = GetFallbackSplit(bounds, preferredAxis);
		SerializableBSPNode.Axis[] array = obj;
		foreach (SerializableBSPNode.Axis axis2 in array)
		{
			int bestScore;
			int num2 = FindOptimalSplit(boxes, bounds, axis2, out bestScore);
			UnityEngine.Debug.Log($"Axis {axis2}: split={num2:F3}, score={bestScore}");
			if (bestScore < num)
			{
				num = bestScore;
				axis = axis2;
				bestSplitValue = num2;
			}
		}
		UnityEngine.Debug.Log($"Selected axis {axis} with score {num}");
		return axis;
	}

	private static int EvaluateBestSplit(List<BoxMetadata> boxes, BoundsInt bounds, SerializableBSPNode.Axis axis, int splitValue)
	{
		BoundsInt boundsInt = bounds;
		BoundsInt boundsInt2 = bounds;
		switch (axis)
		{
		case SerializableBSPNode.Axis.X:
			boundsInt.SetMinMax(bounds.min, new Vector3Int(splitValue, bounds.max.y, bounds.max.z));
			boundsInt2.SetMinMax(new Vector3Int(splitValue, bounds.min.y, bounds.min.z), bounds.max);
			break;
		case SerializableBSPNode.Axis.Y:
			boundsInt.SetMinMax(bounds.min, new Vector3Int(bounds.max.x, splitValue, bounds.max.z));
			boundsInt2.SetMinMax(new Vector3Int(bounds.min.x, splitValue, bounds.min.z), bounds.max);
			break;
		case SerializableBSPNode.Axis.Z:
			boundsInt.SetMinMax(bounds.min, new Vector3Int(bounds.max.x, bounds.max.y, splitValue));
			boundsInt2.SetMinMax(new Vector3Int(bounds.min.x, bounds.min.y, splitValue), bounds.max);
			break;
		}
		return EvaluateSplit(boxes, splitValue, axis, bounds);
	}

	private static int FindOptimalSplit(List<BoxMetadata> boxes, BoundsInt bounds, SerializableBSPNode.Axis axis, out int bestScore)
	{
		List<int> list = new List<int>();
		foreach (BoxMetadata box in boxes)
		{
			BoundsInt bounds2 = box.bounds;
			switch (axis)
			{
			case SerializableBSPNode.Axis.X:
				list.Add(bounds2.min.x);
				list.Add(bounds2.max.x);
				break;
			case SerializableBSPNode.Axis.Y:
				list.Add(bounds2.min.y);
				list.Add(bounds2.max.y);
				break;
			case SerializableBSPNode.Axis.Z:
				list.Add(bounds2.min.z);
				list.Add(bounds2.max.z);
				break;
			}
		}
		list = (from x in list.Distinct()
			orderby x
			select x).ToList();
		int num = GetFallbackSplit(bounds, axis);
		bestScore = int.MaxValue;
		UnityEngine.Debug.Log($"Evaluating {list.Count} split candidates for {axis} axis");
		int axisValue = GetAxisValue(bounds.min, axis);
		int axisValue2 = GetAxisValue(bounds.max, axis);
		foreach (int item in list)
		{
			if (item > axisValue && item < axisValue2)
			{
				int num2 = EvaluateSplit(boxes, item, axis, bounds);
				if (num2 < bestScore)
				{
					bestScore = num2;
					num = item;
				}
			}
		}
		UnityEngine.Debug.Log($"Best split: {num} with score {bestScore}");
		return num;
	}

	private static int GetFallbackSplit(BoundsInt bounds, SerializableBSPNode.Axis axis)
	{
		return axis switch
		{
			SerializableBSPNode.Axis.X => bounds.center.x, 
			SerializableBSPNode.Axis.Y => bounds.center.y, 
			SerializableBSPNode.Axis.Z => bounds.center.z, 
			_ => 0, 
		};
	}

	private static int EvaluateSplit(List<BoxMetadata> boxes, int splitValue, SerializableBSPNode.Axis axis, BoundsInt bounds)
	{
		BoundsInt region = bounds;
		BoundsInt region2 = bounds;
		switch (axis)
		{
