namespace Viveport.Core
{
	public class Logger
	{
		private const string LoggerTypeNameUnity = "UnityEngine.Debug";

		private static bool _hasDetected;

		private static bool _usingUnityLog = true;

		private static Type _unityLogType;

		public static void Log(string message)
		{
			if (!_hasDetected || _usingUnityLog)
			{
				UnityLog(message);
			}
			else
			{
				ConsoleLog(message);
			}
		}

		private static void ConsoleLog(string message)
		{
			Console.WriteLine(message);
			_hasDetected = true;
		}

		private static void UnityLog(string message)
		{
			try
			{
				if (_unityLogType == null)
				{
					_unityLogType = GetType("UnityEngine.Debug");
				}
				_unityLogType.GetMethod("Log", new Type[1] { typeof(string) }).Invoke(null, new object[1] { message });
				_usingUnityLog = true;
			}
			catch (Exception)
			{
				ConsoleLog(message);
				_usingUnityLog = false;
			}
			_hasDetected = true;
		}

		private static Type GetType(string typeName)
		{
			Type type = Type.GetType(typeName);
			if (type != null)
			{
				return type;
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			for (int i = 0; i < assemblies.Length; i++)
			{
				type = assemblies[i].GetType(typeName);
				if (type != null)
				{
					return type;
				}
			}
			return null;
		}
	}
}
namespace LitJson
{
	public enum JsonType
	{
		None,
		Object,
		Array,
		String,
		Int,
		Long,
		Double,
		Boolean
	}
	public interface IJsonWrapper : IList, ICollection, IEnumerable, IOrderedDictionary, IDictionary
	{
		bool IsArray { get; }

		bool IsBoolean { get; }

		bool IsDouble { get; }

		bool IsInt { get; }

		bool IsLong { get; }

		bool IsObject { get; }

		bool IsString { get; }

		bool GetBoolean();

		double GetDouble();

		int GetInt();

		JsonType GetJsonType();

		long GetLong();

		string GetString();

		void SetBoolean(bool val);

		void SetDouble(double val);

		void SetInt(int val);

		void SetJsonType(JsonType type);

		void SetLong(long val);

		void SetString(string val);

		string ToJson();

		void ToJson(JsonWriter writer);
	}
	public class JsonData : IJsonWrapper, IList, ICollection, IEnumerable, IOrderedDictionary, IDictionary, IEquatable<JsonData>
	{
		private IList<JsonData> inst_array;

		private bool inst_boolean;

		private double inst_double;

		private int inst_int;

		private long inst_long;

		private IDictionary<string, JsonData> inst_object;

		private string inst_string;

		private string json;

		private JsonType type;

		private IList<KeyValuePair<string, JsonData>> object_list;

