	public enum TimeUnit
	{
		None,
		Milliseconds,
		Seconds,
		Minutes,
		Hours,
		Days
	}
	public static class TimeUnitExtensions
	{
		public delegate TimeSpan WithUnitValueDelegate(TimeSpan timeSpan, TimeUnit timeUnit, double value);

		public delegate double GetUnitValueDelegate(TimeSpan timeSpan, TimeUnit timeUnit);

		public static string ToShortString(this TimeUnit timeUnit)
		{
			return timeUnit switch
			{
				TimeUnit.Milliseconds => "ms", 
				TimeUnit.Seconds => "s", 
				TimeUnit.Minutes => "m", 
				TimeUnit.Hours => "h", 
				TimeUnit.Days => "D", 
				TimeUnit.None => "", 
				_ => throw new ArgumentOutOfRangeException("timeUnit", timeUnit, null), 
			};
		}

		public static string ToSeparatorString(this TimeUnit timeUnit)
		{
			return timeUnit switch
			{
				TimeUnit.Milliseconds => "", 
				TimeUnit.Seconds => ".", 
				TimeUnit.Minutes => ":", 
				TimeUnit.Hours => ":", 
				TimeUnit.Days => ".", 
				TimeUnit.None => "", 
				_ => throw new ArgumentOutOfRangeException("timeUnit", timeUnit, null), 
			};
		}

		public static double GetUnitValue(this TimeSpan timeSpan, TimeUnit timeUnit)
		{
			return timeUnit switch
			{
				TimeUnit.Milliseconds => timeSpan.Milliseconds, 
				TimeUnit.Seconds => timeSpan.Seconds, 
				TimeUnit.Minutes => timeSpan.Minutes, 
				TimeUnit.Hours => timeSpan.Hours, 
				TimeUnit.Days => timeSpan.Days, 
				TimeUnit.None => 0, 
				_ => throw new ArgumentOutOfRangeException("timeUnit", timeUnit, null), 
			};
		}

		public static TimeSpan WithUnitValue(this TimeSpan timeSpan, TimeUnit timeUnit, double value)
		{
			return timeUnit switch
			{
				TimeUnit.Milliseconds => timeSpan.Add(TimeSpan.FromMilliseconds(value - (double)timeSpan.Milliseconds)), 
				TimeUnit.Seconds => timeSpan.Add(TimeSpan.FromSeconds(value - (double)timeSpan.Seconds)), 
				TimeUnit.Minutes => timeSpan.Add(TimeSpan.FromMinutes(value - (double)timeSpan.Minutes)), 
				TimeUnit.Hours => timeSpan.Add(TimeSpan.FromHours(value - (double)timeSpan.Hours)), 
				TimeUnit.Days => timeSpan.Add(TimeSpan.FromDays(value - (double)timeSpan.Days)), 
				TimeUnit.None => timeSpan, 
				_ => throw new ArgumentOutOfRangeException("timeUnit", timeUnit, null), 
			};
		}

		public static double GetLowestUnitValue(this TimeSpan timeSpan, TimeUnit timeUnit)
		{
			return timeUnit switch
			{
				TimeUnit.Milliseconds => timeSpan.Milliseconds, 
				TimeUnit.Seconds => new TimeSpan(0, 0, 0, timeSpan.Seconds, timeSpan.Milliseconds).TotalSeconds, 
				TimeUnit.Minutes => new TimeSpan(0, 0, timeSpan.Minutes, timeSpan.Seconds, timeSpan.Milliseconds).TotalMinutes, 
				TimeUnit.Hours => new TimeSpan(0, timeSpan.Hours, timeSpan.Minutes, timeSpan.Seconds, timeSpan.Milliseconds).TotalHours, 
				TimeUnit.Days => timeSpan.TotalDays, 
				TimeUnit.None => 0.0, 
				_ => throw new ArgumentOutOfRangeException("timeUnit", timeUnit, null), 
			};
		}

		public static TimeSpan WithLowestUnitValue(this TimeSpan timeSpan, TimeUnit timeUnit, double value)
		{
			return timeUnit switch
			{
				TimeUnit.Milliseconds => new TimeSpan(timeSpan.Days, timeSpan.Hours, timeSpan.Minutes, timeSpan.Seconds, (int)value), 
				TimeUnit.Seconds => new TimeSpan(timeSpan.Days, timeSpan.Hours, timeSpan.Minutes, 0).Add(TimeSpan.FromSeconds(value)), 
				TimeUnit.Minutes => new TimeSpan(timeSpan.Days, timeSpan.Hours, 0, 0).Add(TimeSpan.FromMinutes(value)), 
				TimeUnit.Hours => new TimeSpan(timeSpan.Days, 0, 0, 0).Add(TimeSpan.FromHours(value)), 
				TimeUnit.Days => TimeSpan.FromDays(value), 
				TimeUnit.None => timeSpan, 
				_ => throw new ArgumentOutOfRangeException("timeUnit", timeUnit, null), 
			};
		}

