namespace Photon.Pun
{
	[RequireComponent(typeof(Rigidbody))]
	public class RigOwnedRigidbodyView : MonoBehaviourPun, IPunObservable
	{
		private float m_Distance;

		private float m_Angle;

		private Rigidbody m_Body;

		private UnityEngine.Vector3 m_NetworkPosition;

		private UnityEngine.Quaternion m_NetworkRotation;

		public bool m_SynchronizeVelocity = true;

		public bool m_SynchronizeAngularVelocity;

		public bool m_TeleportEnabled;

		public float m_TeleportIfDistanceGreaterThan = 3f;

		public bool IsMine { get; private set; }

		public void SetIsMine(bool isMine)
		{
			IsMine = isMine;
		}

		public void Awake()
		{
			m_Body = GetComponent<Rigidbody>();
			m_NetworkPosition = default(UnityEngine.Vector3);
			m_NetworkRotation = default(UnityEngine.Quaternion);
		}

		public void FixedUpdate()
		{
			if (!IsMine)
			{
				m_Body.position = UnityEngine.Vector3.MoveTowards(m_Body.position, m_NetworkPosition, m_Distance * (1f / (float)PhotonNetwork.SerializationRate));
				m_Body.rotation = UnityEngine.Quaternion.RotateTowards(m_Body.rotation, m_NetworkRotation, m_Angle * (1f / (float)PhotonNetwork.SerializationRate));
			}
		}

		public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
		{
			if (info.Sender != info.photonView.Owner)
			{
				return;
			}
			try
			{
				if (stream.IsWriting)
				{
					stream.SendNext(m_Body.position);
					stream.SendNext(m_Body.rotation);
					if (m_SynchronizeVelocity)
					{
						stream.SendNext(m_Body.linearVelocity);
					}
					if (m_SynchronizeAngularVelocity)
					{
						stream.SendNext(m_Body.angularVelocity);
					}
					stream.SendNext(m_Body.IsSleeping());
					return;
				}
				m_NetworkPosition.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
				m_NetworkRotation.SetValueSafe((UnityEngine.Quaternion)stream.ReceiveNext());
				if (m_TeleportEnabled && UnityEngine.Vector3.Distance(m_Body.position, m_NetworkPosition) > m_TeleportIfDistanceGreaterThan)
				{
					m_Body.position = m_NetworkPosition;
				}
				if (m_SynchronizeVelocity || m_SynchronizeAngularVelocity)
				{
					float num = Mathf.Abs((float)(PhotonNetwork.Time - info.SentServerTime));
					if (m_SynchronizeVelocity)
					{
						UnityEngine.Vector3 v = (UnityEngine.Vector3)stream.ReceiveNext();
						if (!v.IsValid(10000f))
						{
							v = UnityEngine.Vector3.zero;
						}
						if (!m_Body.isKinematic)
						{
							m_Body.linearVelocity = v;
						}
						m_NetworkPosition += m_Body.linearVelocity * num;
						m_Distance = UnityEngine.Vector3.Distance(m_Body.position, m_NetworkPosition);
					}
					if (m_SynchronizeAngularVelocity)
					{
						UnityEngine.Vector3 v2 = (UnityEngine.Vector3)stream.ReceiveNext();
						if (!v2.IsValid(10000f))
						{
							v2 = UnityEngine.Vector3.zero;
						}
						m_Body.angularVelocity = v2;
						m_NetworkRotation = UnityEngine.Quaternion.Euler(m_Body.angularVelocity * num) * m_NetworkRotation;
						m_Angle = UnityEngine.Quaternion.Angle(m_Body.rotation, m_NetworkRotation);
					}
				}
				if ((bool)stream.ReceiveNext())
				{
					m_Body.Sleep();
				}
			}
			catch
			{
			}
		}
	}
	[HelpURL("https://doc.photonengine.com/en-us/pun/v2/gameplay/synchronization-and-state")]
	public class RigOwnedTransformView : MonoBehaviourPun, IPunObservable
	{
		private float m_Distance;

		private float m_Angle;

		private UnityEngine.Vector3 m_Direction;

		private UnityEngine.Vector3 m_NetworkPosition;

		private UnityEngine.Vector3 m_StoredPosition;

		private UnityEngine.Vector3 m_networkScale;

		private UnityEngine.Quaternion m_NetworkRotation;

		public bool m_SynchronizePosition = true;

		public bool m_SynchronizeRotation = true;

		public bool m_SynchronizeScale;

		[Tooltip("Indicates if localPosition and localRotation should be used. Scale ignores this setting, and always uses localScale to avoid issues with lossyScale.")]
		public bool m_UseLocal;

		private bool m_firstTake;

		public bool IsMine { get; private set; }

		public void SetIsMine(bool isMine)
		{
			IsMine = isMine;
		}

		public void Awake()
		{
			m_StoredPosition = base.transform.localPosition;
			m_NetworkPosition = UnityEngine.Vector3.zero;
			m_networkScale = UnityEngine.Vector3.one;
			m_NetworkRotation = UnityEngine.Quaternion.identity;
		}

		private void Reset()
		{
			m_UseLocal = true;
		}

		private void OnEnable()
		{
			m_firstTake = true;
		}

		public void Update()
		{
			Transform transform = base.transform;
			if (!IsMine && IsValid(m_NetworkPosition) && IsValid(m_NetworkRotation))
			{
				if (m_UseLocal)
				{
					transform.localPosition = UnityEngine.Vector3.MoveTowards(transform.localPosition, m_NetworkPosition, m_Distance * Time.deltaTime * (float)PhotonNetwork.SerializationRate);
					transform.localRotation = UnityEngine.Quaternion.RotateTowards(transform.localRotation, m_NetworkRotation, m_Angle * Time.deltaTime * (float)PhotonNetwork.SerializationRate);
				}
				else
				{
					transform.position = UnityEngine.Vector3.MoveTowards(transform.position, m_NetworkPosition, m_Distance * Time.deltaTime * (float)PhotonNetwork.SerializationRate);
					transform.rotation = UnityEngine.Quaternion.RotateTowards(transform.rotation, m_NetworkRotation, m_Angle * Time.deltaTime * (float)PhotonNetwork.SerializationRate);
				}
			}
		}

		private bool IsValid(UnityEngine.Vector3 v)
		{
			if (!float.IsNaN(v.x) && !float.IsNaN(v.y) && !float.IsNaN(v.z) && !float.IsInfinity(v.x) && !float.IsInfinity(v.y))
			{
				return !float.IsInfinity(v.z);
			}
			return false;
		}

		private bool IsValid(UnityEngine.Quaternion q)
		{
			if (!float.IsNaN(q.x) && !float.IsNaN(q.y) && !float.IsNaN(q.z) && !float.IsNaN(q.w) && !float.IsInfinity(q.x) && !float.IsInfinity(q.y) && !float.IsInfinity(q.z))
			{
				return !float.IsInfinity(q.w);
			}
			return false;
		}

		public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
		{
			if (info.Sender != info.photonView.Owner)
			{
				return;
			}
			try
			{
				Transform transform = base.transform;
				if (stream.IsWriting)
				{
					if (m_SynchronizePosition)
					{
						if (m_UseLocal)
						{
							m_Direction = transform.localPosition - m_StoredPosition;
							m_StoredPosition = transform.localPosition;
							stream.SendNext(transform.localPosition);
							stream.SendNext(m_Direction);
						}
						else
						{
							m_Direction = transform.position - m_StoredPosition;
							m_StoredPosition = transform.position;
							stream.SendNext(transform.position);
							stream.SendNext(m_Direction);
						}
					}
					if (m_SynchronizeRotation)
					{
						if (m_UseLocal)
						{
							stream.SendNext(transform.localRotation);
						}
						else
						{
							stream.SendNext(transform.rotation);
						}
					}
					if (m_SynchronizeScale)
					{
						stream.SendNext(transform.localScale);
					}
					return;
				}
				if (m_SynchronizePosition)
				{
					m_NetworkPosition.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
					m_Direction.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
					if (m_firstTake)
					{
						if (m_UseLocal)
						{
							transform.localPosition = m_NetworkPosition;
						}
						else
						{
							transform.position = m_NetworkPosition;
						}
						m_Distance = 0f;
					}
					else
					{
						float num = Mathf.Abs((float)(PhotonNetwork.Time - info.SentServerTime));
						m_NetworkPosition += m_Direction * num;
						if (m_UseLocal)
						{
							m_Distance = UnityEngine.Vector3.Distance(transform.localPosition, m_NetworkPosition);
						}
						else
						{
							m_Distance = UnityEngine.Vector3.Distance(transform.position, m_NetworkPosition);
						}
					}
				}
				if (m_SynchronizeRotation)
				{
					m_NetworkRotation.SetValueSafe((UnityEngine.Quaternion)stream.ReceiveNext());
					if (m_firstTake)
					{
						m_Angle = 0f;
						if (m_UseLocal)
						{
							transform.localRotation = m_NetworkRotation;
						}
						else
						{
							transform.rotation = m_NetworkRotation;
						}
					}
					else if (m_UseLocal)
					{
						m_Angle = UnityEngine.Quaternion.Angle(transform.localRotation, m_NetworkRotation);
					}
					else
					{
						m_Angle = UnityEngine.Quaternion.Angle(transform.rotation, m_NetworkRotation);
					}
				}
				if (m_SynchronizeScale)
				{
					m_networkScale.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
					transform.localScale = m_networkScale;
				}
				if (m_firstTake)
				{
					m_firstTake = false;
				}
			}
			catch
			{
			}
		}

		public void GTAddition_DoTeleport()
		{
			m_firstTake = true;
		}
	}
}
namespace GTMathUtil
{
	internal class CriticalSpringDamper
	{
		public float x;

		public float xGoal;

		public float halfLife = 0.1f;

		private float curVel;

		private static float halflife_to_damping(float halflife, float eps = 1E-05f)
		{
			return 2.7725887f / (halflife + eps);
		}

		private static float fast_negexp(float x)
		{
			return 1f / (1f + x + 0.48f * x * x + 0.235f * x * x * x);
		}

		public float Update(float dt)
		{
			float num = halflife_to_damping(halfLife) / 2f;
			float num2 = x - xGoal;
			float num3 = curVel + num2 * num;
			float num4 = fast_negexp(num * dt);
			x = num4 * (num2 + num3 * dt) + xGoal;
			curVel = num4 * (curVel - num3 * num * dt);
			return x;
		}
	}
	internal class WithinBounds
	{
		public static bool PointWithinBoxColliderBounds(UnityEngine.Vector3 point, BoxCollider boxCollider)
		{
			UnityEngine.Vector3 vector = boxCollider.transform.InverseTransformPoint(point);
			UnityEngine.Vector3 vector2 = boxCollider.size / 2f;
			UnityEngine.Vector3 center = boxCollider.center;
			if (vector.x < vector2.x + center.x && vector.x > 0f - vector2.x + center.x && vector.y < vector2.y + center.y && vector.y > 0f - vector2.y + center.y && vector.z < vector2.z + center.z)
			{
				return vector.z > 0f - vector2.z + center.z;
			}
			return false;
		}

		public static bool PointWithinCapsuleColliderBounds(UnityEngine.Vector3 point, CapsuleCollider capsuleCollider)
		{
			UnityEngine.Vector3 vector = capsuleCollider.transform.InverseTransformPoint(point);
			UnityEngine.Vector3 center = capsuleCollider.center;
			float radius = capsuleCollider.radius;
			float height = capsuleCollider.height;
			UnityEngine.Vector3 vector2 = UnityEngine.Vector3.up;
			switch (capsuleCollider.direction)
			{
			case 0:
				vector2 = UnityEngine.Vector3.right;
				break;
			case 1:
				vector2 = UnityEngine.Vector3.up;
				break;
			case 2:
				vector2 = UnityEngine.Vector3.forward;
				break;
			}
			float num = UnityEngine.Vector3.Dot(vector, vector2);
			UnityEngine.Vector3 vector3 = num * vector2 + center;
			UnityEngine.Vector3 vector4 = vector3 - center;
			if ((!((vector - vector3).magnitude < radius) || !(vector4.magnitude <= height)) && (!(num >= 0f) || !((vector - (center + vector2 * height / 2f)).magnitude < radius)))
			{
				if (num < 0f)
				{
					return (vector - (center - vector2 * height / 2f)).magnitude < radius;
				}
				return false;
			}
			return true;
		}

		public static bool PointWithinSphereColliderBounds(UnityEngine.Vector3 point, SphereCollider sphereCollider)
		{
			UnityEngine.Vector3 vector = sphereCollider.transform.InverseTransformPoint(point);
			UnityEngine.Vector3 center = sphereCollider.center;
			float radius = sphereCollider.radius;
			return (vector - center).magnitude < radius;
		}
	}
}
