					_cachedReference = Object.FindAnyObjectByType<GorillaSnapTurn>();
				}
				return _cachedReference;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (_cachedReference != null)
			{
				Debug.LogError("[SNAP_TURN] A [GorillaSnapTurn] component already exists in the scene");
				return;
			}
			_cachedReference = this;
			TickSystem<object>.AddTickCallback(this);
		}

		public void Tick()
		{
			ValidateTurningOverriders();
			if (m_Controllers.Count > 0)
			{
				EnsureControllerDataListSize();
				for (int i = 0; i < m_Controllers.Count; i++)
				{
					XRController xRController = m_Controllers[i];
					if (!(xRController == null) && xRController.enableInputActions)
					{
						float num = 0f;
						if (xRController.controllerNode == XRNode.RightHand)
						{
							num = ControllerInputPoller.instance.rightControllerPrimary2DAxis.x;
						}
						else if (xRController.controllerNode == XRNode.LeftHand)
						{
							num = ControllerInputPoller.instance.leftControllerPrimary2DAxis.x;
						}
						if (num > deadZone)
						{
							StartTurn(m_TurnAmount);
						}
						else if (num < 0f - deadZone)
						{
							StartTurn(0f - m_TurnAmount);
						}
						else
						{
							m_AxisReset = true;
						}
					}
				}
			}
			if (Mathf.Abs(m_CurrentTurnAmount) > 0f && TryPrepareLocomotion())
			{
				if (xrOrigin != null)
				{
					GTPlayer.Instance.Turn(m_CurrentTurnAmount);
				}
				m_CurrentTurnAmount = 0f;
				TryEndLocomotion();
			}
		}

		private void EnsureControllerDataListSize()
		{
			if (m_Controllers.Count != m_ControllersWereActive.Count)
			{
				while (m_ControllersWereActive.Count < m_Controllers.Count)
				{
					m_ControllersWereActive.Add(item: false);
				}
				while (m_ControllersWereActive.Count < m_Controllers.Count)
				{
					m_ControllersWereActive.RemoveAt(m_ControllersWereActive.Count - 1);
				}
			}
		}

		internal void FakeStartTurn(bool isLeft)
		{
			StartTurn(isLeft ? (0f - m_TurnAmount) : m_TurnAmount);
		}

		private void StartTurn(float amount)
		{
			if ((!(m_TimeStarted + m_DebounceTime > Time.time) || m_AxisReset) && !base.isLocomotionActive && turningOverriders.Count <= 0)
			{
				m_TimeStarted = Time.time;
				m_CurrentTurnAmount = amount;
				m_AxisReset = false;
			}
		}

		public void ChangeTurnMode(string turnMode, int turnSpeedFactor)
		{
			turnType = turnMode;
			turnFactor = turnSpeedFactor;
			if (!(turnMode == "SNAP"))
			{
				if (turnMode == "SMOOTH")
				{
					m_DebounceTime = 0f;
					m_TurnAmount = 360f * Time.fixedDeltaTime * ConvertedTurnFactor(turnSpeedFactor);
				}
				else
				{
					m_DebounceTime = 0f;
					m_TurnAmount = 0f;
				}
			}
			else
			{
				m_DebounceTime = 0.5f;
				m_TurnAmount = 60f * ConvertedTurnFactor(turnSpeedFactor);
			}
		}

		public float ConvertedTurnFactor(float newTurnSpeed)
		{
			return Mathf.Max(0.75f, 0.5f + newTurnSpeed / 10f * 1.5f);
		}

		public void SetTurningOverride(ISnapTurnOverride caller)
		{
			if (!turningOverriders.Contains(caller))
			{
				turningOverriders.Add(caller);
			}
		}

		public void UnsetTurningOverride(ISnapTurnOverride caller)
		{
			if (turningOverriders.Contains(caller))
			{
				turningOverriders.Remove(caller);
			}
		}

		public void ValidateTurningOverriders()
		{
			foreach (ISnapTurnOverride turningOverrider in turningOverriders)
			{
				if (turningOverrider == null || !turningOverrider.TurnOverrideActive())
				{
					turningOverriders.Remove(turningOverrider);
				}
			}
		}

		public static void DisableSnapTurn()
		{
			Debug.Log("[SNAP_TURN] Disabling Snap Turn");
			if (!(CachedSnapTurnRef == null))
			{
				_cachedTurnFactor = PlayerPrefs.GetInt("turnFactor");
				_cachedTurnType = PlayerPrefs.GetString("stickTurning");
				CachedSnapTurnRef.ChangeTurnMode("NONE", 0);
			}
		}

		public static void UpdateAndSaveTurnType(string mode)
		{
			if (CachedSnapTurnRef == null)
			{
				Debug.LogError("[SNAP_TURN] Failed to Update, [CachedSnapTurnRef] is NULL");
				return;
			}
			PlayerPrefs.SetString("stickTurning", mode);
			PlayerPrefs.Save();
			CachedSnapTurnRef.ChangeTurnMode(mode, CachedSnapTurnRef.turnFactor);
		}

		public static void UpdateAndSaveTurnFactor(int factor)
		{
			if (CachedSnapTurnRef == null)
			{
				Debug.LogError("[SNAP_TURN] Failed to Update, [CachedSnapTurnRef] is NULL");
				return;
			}
			PlayerPrefs.SetInt("turnFactor", factor);
			PlayerPrefs.Save();
			CachedSnapTurnRef.ChangeTurnMode(CachedSnapTurnRef.turnType, factor);
		}

		public static void LoadSettingsFromPlayerPrefs()
		{
			if (!(CachedSnapTurnRef == null))
			{
				string defaultValue = ((Application.platform == RuntimePlatform.Android) ? "NONE" : "SNAP");
				string turnMode = PlayerPrefs.GetString("stickTurning", defaultValue);
				int turnSpeedFactor = PlayerPrefs.GetInt("turnFactor", 4);
				CachedSnapTurnRef.ChangeTurnMode(turnMode, turnSpeedFactor);
			}
		}

		public static void LoadSettingsFromCache()
		{
			if (!(CachedSnapTurnRef == null))
			{
				if (string.IsNullOrEmpty(_cachedTurnType))
				{
					_cachedTurnType = ((Application.platform == RuntimePlatform.Android) ? "NONE" : "SNAP");
				}
				string cachedTurnType = _cachedTurnType;
				int cachedTurnFactor = _cachedTurnFactor;
				CachedSnapTurnRef.ChangeTurnMode(cachedTurnType, cachedTurnFactor);
			}
		}
	}
}
namespace GorillaTagScripts
{
	public class GorillaIntervalTimer : MonoBehaviourPun
	{
		private enum TimeUnit
		{
			Seconds,
			Minutes,
			Hours
		}

		private enum RandomDistribution
		{
			Uniform,
			Normal,
			Exponential
		}

		private enum IntervalSource
		{
			LocalRandom,
			NetworkedRandom
		}

		private enum RunLength
		{
			Infinite,
			Finite
		}

		[Header("Scheduling")]
		[Tooltip("If true, the timer will automatically start when this component is enabled.")]
		[SerializeField]
		private bool runOnEnable = true;

		[Tooltip("If true, apply an initial delay before the first interval is fired.")]
		[SerializeField]
		private bool useInitialDelay;

		[Tooltip("Delay (in seconds or minutes depending on Unit) before the first fire if 'Use Initial Delay' is enabled.")]
		[SerializeField]
		private float initialDelay;

		[Header("Interval")]
		[Tooltip("Unit of time for Fixed Interval, Min and Max values.")]
		[SerializeField]
		private TimeUnit unit;

		[Tooltip("Distribution type used for generating random intervals when Interval Source = LocalRandom.")]
		[SerializeField]
		private RandomDistribution distribution;

		[Tooltip("Fixed interval duration (interpreted by Unit) when Use Random Duration = false.")]
		[SerializeField]
		private float fixedInterval = 1f;

		[Space]
		[Tooltip("If false, 'Fixed Interval' is used. If true, a random interval is sampled each cycle.")]
		[SerializeField]
		private bool useRandomDuration;

		[Tooltip("Minimum interval time (in selected Unit).")]
		[SerializeField]
		private float randTimeMin = 0.5f;

		[Tooltip("Maximum interval time (in selected Unit).")]
		[SerializeField]
		private float randTimeMax = 2f;

		[Tooltip("Determines whether to use a local random generator or a networked random source.")]
		[SerializeField]
		private IntervalSource intervalSource;

		[Header("Networked Interval (optional)")]
		[Tooltip("If Interval Source = NetworkedRandom, the timer queries this component for the next interval")]
		[SerializeField]
		private NetworkedRandomProvider networkProvider;

		[Space]
		[Tooltip("If true, wait this additional delay after onIntervalFired() before starting the next interval.")]
		[SerializeField]
		private bool usePostIntervalDelay;

		[Tooltip("Additional delay (in selected Unit) to wait after onIntervalFired(), before the next interval begins.")]
		[SerializeField]
		private float postIntervalDelay;

		[Header("Run Length")]
		[Tooltip("Infinite runs forever. Finite stops after Max Fires Per Run.")]
		[SerializeField]
		private RunLength runLength;

		[Tooltip("Number of times the timer fires before the run completes (when Run Length = Finite).")]
		[SerializeField]
		private int maxFiresPerRun = 3;

		[Tooltip("If true, the timer stops at the end of a finite run and requires ResetRun() / StartTimer() to continue. If false, the run counter auto-resets and continues.")]
		[SerializeField]
		private bool requireManualReset = true;

		[Header("Events")]
		public UnityEvent onIntervalFired;

		public UnityEvent onTimerStarted;

		public UnityEvent onTimerStopped;

		private const float minIntervalEpsilon = 0.001f;

		private float currentIntervalSeconds = 1f;

		private float elapsed;

		private bool isRunning;

		private bool isPaused;

		private bool isRegistered;

		private int runFiredSoFar;

		private bool isInPostFireDelay;

		private void Awake()
		{
			if (networkProvider == null)
			{
				networkProvider = GetComponentInParent<NetworkedRandomProvider>();
			}
			ResetElapsed();
			ResetRun();
		}

		private void OnEnable()
		{
			if (runOnEnable)
			{
				if (!isRegistered)
				{
					GorillaIntervalTimerManager.RegisterGorillaTimer(this);
					isRegistered = true;
				}
				StartTimer();
			}
		}

		private void OnDisable()
		{
			if (isRegistered)
			{
				GorillaIntervalTimerManager.UnregisterGorillaTimer(this);
				isRegistered = false;
			}
			StopTimer();
		}

		public void StartTimer()
		{
			if (!isRegistered)
			{
				GorillaIntervalTimerManager.RegisterGorillaTimer(this);
				isRegistered = true;
			}
			ResetRun();
			elapsed = 0f;
			isInPostFireDelay = false;
			if (useInitialDelay && initialDelay > 0f)
			{
				currentIntervalSeconds = Mathf.Max(0.001f, ToSeconds(initialDelay));
			}
			else
			{
				RollNextInterval();
			}
			isRunning = true;
			isPaused = false;
			onTimerStarted?.Invoke();
		}

		public void StopTimer()
		{
			isRunning = false;
			isPaused = false;
			elapsed = 0f;
			isInPostFireDelay = false;
			onTimerStopped?.Invoke();
			if (isRegistered)
			{
				GorillaIntervalTimerManager.UnregisterGorillaTimer(this);
				isRegistered = false;
			}
		}

		public void Pause()
		{
			isPaused = true;
		}

		public void Resume()
		{
			isPaused = false;
		}

		public void SetFixedIntervalSeconds(float seconds)
		{
			useRandomDuration = false;
			fixedInterval = Mathf.Max(0f, seconds);
			currentIntervalSeconds = Mathf.Max(0.001f, ToSeconds(fixedInterval));
			elapsed = 0f;
		}

		public void OverrideNextIntervalSeconds(float seconds)
		{
			currentIntervalSeconds = Mathf.Max(0.001f, seconds);
			elapsed = 0f;
		}

		public void ResetRun()
		{
			runFiredSoFar = 0;
		}

		public void InvokeUpdate()
		{
			if (!isRunning || isPaused)
			{
				return;
			}
			elapsed += Time.deltaTime;
			if (!(elapsed >= currentIntervalSeconds))
			{
				return;
			}
			if (isInPostFireDelay)
			{
				isInPostFireDelay = false;
				elapsed = 0f;
				RollNextInterval();
				return;
			}
			onIntervalFired?.Invoke();
			runFiredSoFar++;
			if (runLength == RunLength.Finite && runFiredSoFar >= Mathf.Max(1, maxFiresPerRun))
			{
				if (requireManualReset)
				{
					StopTimer();
					return;
				}
				runFiredSoFar = 0;
			}
			if (usePostIntervalDelay && postIntervalDelay > 0f)
			{
				isInPostFireDelay = true;
				elapsed = 0f;
				currentIntervalSeconds = Mathf.Max(0.001f, ToSeconds(postIntervalDelay));
			}
			else
			{
				elapsed = 0f;
				RollNextInterval();
			}
		}

		private void ResetElapsed()
		{
			elapsed = 0f;
		}

		private void RollNextInterval()
		{
			if (!useRandomDuration)
			{
				currentIntervalSeconds = Mathf.Max(0.001f, ToSeconds(fixedInterval));
				return;
			}
			float num = Mathf.Max(0f, ToSeconds(randTimeMin));
			float num2 = Mathf.Max(num, ToSeconds(randTimeMax));
			if (intervalSource == IntervalSource.NetworkedRandom && networkProvider != null)
			{
				float b;
				switch (distribution)
				{
				default:
					b = networkProvider.NextFloat(num, num2);
					break;
				case RandomDistribution.Normal:
				{
					double d2 = System.Math.Max(double.Epsilon, 1.0 - networkProvider.NextDouble(0.0, 1.0));
					double num5 = System.Math.Max(double.Epsilon, 1.0 - (double)networkProvider.NextFloat01());
					double num6 = System.Math.Sqrt(-2.0 * System.Math.Log(d2)) * System.Math.Sin(System.Math.PI * 2.0 * num5);
					float num7 = 0.5f * (num + num2);
					float num8 = (num2 - num) / 6f;
					b = Mathf.Clamp(num7 + (float)(num6 * (double)num8), num, num2);
					break;
				}
				case RandomDistribution.Exponential:
				{
					double d = System.Math.Max(double.Epsilon, 1.0 - networkProvider.NextDouble(0.0, 1.0));
					double num3 = 0.5 * (double)(num + num2);
					double num4 = ((num3 > 0.0) ? (1.0 / num3) : 1.0);
					b = Mathf.Clamp((float)((0.0 - System.Math.Log(d)) / num4), num, num2);
					break;
				}
				}
				currentIntervalSeconds = Mathf.Max(0.001f, b);
			}
			else
			{
				float b;
				switch (distribution)
				{
				default:
					b = UnityEngine.Random.Range(num, num2);
					break;
				case RandomDistribution.Normal:
				{
					float f = Mathf.Max(float.Epsilon, 1f - UnityEngine.Random.value);
					float num11 = 1f - UnityEngine.Random.value;
					float num12 = Mathf.Sqrt(-2f * Mathf.Log(f)) * Mathf.Sin(MathF.PI * 2f * num11);
					float num13 = 0.5f * (num + num2);
					float num14 = (num2 - num) / 6f;
					b = Mathf.Clamp(num13 + num12 * num14, num, num2);
					break;
				}
				case RandomDistribution.Exponential:
				{
					float num9 = 0.5f * (num + num2);
					float num10 = ((num9 > 0f) ? (1f / num9) : 1f);
					b = Mathf.Clamp((0f - Mathf.Log(Mathf.Max(float.Epsilon, 1f - UnityEngine.Random.value))) / num10, num, num2);
					break;
				}
				}
				currentIntervalSeconds = Mathf.Max(0.001f, b);
			}
		}

		private float ToSeconds(float value)
		{
			return unit switch
			{
				TimeUnit.Minutes => value * 60f, 
				TimeUnit.Hours => value * 3600f, 
				_ => value, 
			};
		}

		public void RestartTimer()
		{
			ResetElapsed();
			RollNextInterval();
			StartTimer();
		}

		public float GetPassedTime()
		{
			return elapsed;
		}

		public float GetRemainingTime()
		{
			return Mathf.Max(0f, currentIntervalSeconds - elapsed);
		}
	}
	public class Mole : Tappable
	{
		public delegate void MoleTapEvent(MoleTypes moleType, UnityEngine.Vector3 position, bool isLocalTap, bool isLeft);

		public enum MoleState
		{
			Reset,
			Ready,
			TransitionToVisible,
			Visible,
			TransitionToHidden,
			Hidden
		}

		public float positionOffset = 0.2f;

		public MoleTypes[] moleTypes;

		private float showMoleDuration;

		private UnityEngine.Vector3 visiblePosition;

		private UnityEngine.Vector3 hiddenPosition;

		private float currentTime;

		private float animStartTime;

		private float travelTime;

		private float normalTravelTime = 0.3f;

		private float hitTravelTime = 0.2f;

		private AnimationCurve animCurve;

		private AnimationCurve normalAnimCurve;

		private AnimationCurve hitAnimCurve;

		private MoleState currentState;

		private UnityEngine.Vector3 origin;

		private UnityEngine.Vector3 target;

		private int randomMolePickedIndex;

		public CallLimiter rpcCooldown;

		private int moleScore;

		private List<int> safeMoles = new List<int>();

		private List<int> hazardMoles = new List<int>();

		public bool IsLeftSideMole { get; set; }

		public event MoleTapEvent OnTapped;

		private void Awake()
		{
			currentState = MoleState.Hidden;
			UnityEngine.Vector3 position = base.transform.position;
			origin = (target = position);
			visiblePosition = new UnityEngine.Vector3(position.x, position.y + positionOffset, position.z);
			hiddenPosition = new UnityEngine.Vector3(position.x, position.y - positionOffset, position.z);
			travelTime = normalTravelTime;
			animCurve = (normalAnimCurve = AnimationCurves.EaseInOutQuad);
			hitAnimCurve = AnimationCurves.EaseOutBack;
			for (int i = 0; i < moleTypes.Length; i++)
			{
				if (moleTypes[i].isHazard)
				{
					hazardMoles.Add(i);
				}
				else
				{
					safeMoles.Add(i);
				}
			}
			randomMolePickedIndex = -1;
		}

		public void InvokeUpdate()
		{
			if (currentState == MoleState.Ready)
			{
				return;
			}
			switch (currentState)
			{
			case MoleState.TransitionToVisible:
			case MoleState.TransitionToHidden:
			{
				float num = animCurve.Evaluate(Mathf.Clamp01((Time.time - animStartTime) / travelTime));
				base.transform.position = UnityEngine.Vector3.Lerp(origin, target, num);
				if (num >= 1f)
				{
					currentState++;
				}
				break;
			}
			case MoleState.Reset:
			case MoleState.Hidden:
				currentState = MoleState.Ready;
				break;
			}
			if (Time.time - currentTime >= showMoleDuration && currentState > MoleState.Ready && currentState < MoleState.TransitionToHidden)
			{
				HideMole();
			}
		}

		public bool CanPickMole()
		{
			return currentState == MoleState.Ready;
		}

		public void ShowMole(float _showMoleDuration, int randomMoleTypeIndex)
		{
			if (randomMoleTypeIndex >= moleTypes.Length || randomMoleTypeIndex < 0)
			{
				return;
			}
			randomMolePickedIndex = randomMoleTypeIndex;
			for (int i = 0; i < moleTypes.Length; i++)
			{
				moleTypes[i].gameObject.SetActive(i == randomMoleTypeIndex);
				if (moleTypes[i].monkeMoleDefaultMaterial != null)
				{
					moleTypes[i].MeshRenderer.material = moleTypes[i].monkeMoleDefaultMaterial;
				}
			}
			showMoleDuration = _showMoleDuration;
			origin = base.transform.position;
			target = visiblePosition;
			animCurve = normalAnimCurve;
			currentState = MoleState.TransitionToVisible;
			animStartTime = (currentTime = Time.time);
			travelTime = normalTravelTime;
		}

		public void HideMole(bool isHit = false)
		{
			if (currentState >= MoleState.TransitionToVisible && currentState <= MoleState.Visible)
			{
				origin = base.transform.position;
				target = hiddenPosition;
				animCurve = (isHit ? hitAnimCurve : normalAnimCurve);
				animStartTime = Time.time;
				travelTime = (isHit ? hitTravelTime : normalTravelTime);
				currentState = MoleState.TransitionToHidden;
			}
		}

		public bool CanTap()
		{
			MoleState moleState = currentState;
			return moleState == MoleState.TransitionToVisible || moleState == MoleState.Visible;
		}

		public override bool CanTap(bool isLeftHand)
		{
			return CanTap();
		}

		public override void OnTapLocal(float tapStrength, float tapTime, PhotonMessageInfoWrapped info)
		{
			if (CanTap())
			{
				bool flag = info.Sender.ActorNumber == NetworkSystem.Instance.LocalPlayerID;
				bool isLeft = flag && GorillaTagger.Instance.lastLeftTap >= GorillaTagger.Instance.lastRightTap;
				MoleTypes moleTypes = null;
				if (randomMolePickedIndex >= 0 && randomMolePickedIndex < this.moleTypes.Length)
				{
					moleTypes = this.moleTypes[randomMolePickedIndex];
				}
				if (moleTypes != null)
				{
					this.OnTapped?.Invoke(moleTypes, base.transform.position, flag, isLeft);
				}
			}
		}

		public void ResetPosition()
		{
			base.transform.position = hiddenPosition;
			currentState = MoleState.Reset;
		}

		public int GetMoleTypeIndex(bool useHazardMole)
		{
			if (!useHazardMole)
			{
				return safeMoles[UnityEngine.Random.Range(0, safeMoles.Count)];
			}
			return hazardMoles[UnityEngine.Random.Range(0, hazardMoles.Count)];
		}
	}
	public class MoleTypes : MonoBehaviour
	{
		public bool isHazard;

		public int scorePoint = 1;

		public MeshRenderer MeshRenderer;

		public Material monkeMoleDefaultMaterial;

		public Material monkeMoleHitMaterial;

		public bool IsLeftSideMoleType { get; set; }

		public Mole MoleContainerParent { get; set; }

		private void Start()
		{
			MoleContainerParent = GetComponentInParent<Mole>();
			if ((bool)MoleContainerParent)
			{
				IsLeftSideMoleType = MoleContainerParent.IsLeftSideMole;
			}
		}
	}
	[NetworkBehaviourWeaved(210)]
	public class WhackAMole : NetworkComponent
	{
		public enum GameState
