	public class BuilderFactory : MonoBehaviour
	{
		public Transform spawnLocation;

		private List<int> pieceTypes;

		public List<GameObject> itemList;

		[HideInInspector]
		public List<BuilderPiece> pieceList;

		public BuilderOptionButton buildItemButton;

		public TextMeshPro itemLabel;

		public BuilderOptionButton prevItemButton;

		public BuilderOptionButton nextItemButton;

		public TextMeshPro materialLabel;

		public BuilderOptionButton prevMaterialButton;

		public BuilderOptionButton nextMaterialButton;

		public AudioSource audioSource;

		public AudioClip buildPieceSound;

		public Transform previewMarker;

		public List<BuilderUIResource> resourceCostUIs;

		private BuilderPiece previewPiece;

		private int currPieceTypeIndex;

		private int currPieceMaterialIndex;

		private Dictionary<int, int> pieceTypeToIndex;

		private BuilderTable table;

		private bool initialized;

		private void Awake()
		{
			InitIfNeeded();
		}

		public void InitIfNeeded()
		{
			if (initialized)
			{
				return;
			}
			buildItemButton.Setup(OnBuildItem);
			currPieceTypeIndex = 0;
			prevItemButton.Setup(OnPrevItem);
			nextItemButton.Setup(OnNextItem);
			currPieceMaterialIndex = 0;
			prevMaterialButton.Setup(OnPrevMaterial);
			nextMaterialButton.Setup(OnNextMaterial);
			pieceTypeToIndex = new Dictionary<int, int>(256);
			initialized = true;
			if (resourceCostUIs == null)
			{
				return;
			}
			for (int i = 0; i < resourceCostUIs.Count; i++)
			{
				if (resourceCostUIs[i] != null)
				{
					resourceCostUIs[i].gameObject.SetActive(value: false);
				}
			}
		}

		public void Setup(BuilderTable tableOwner)
		{
			table = tableOwner;
			InitIfNeeded();
			List<BuilderPiece> list = pieceList;
			pieceTypes = new List<int>(list.Count);
			for (int i = 0; i < list.Count; i++)
			{
				string text = list[i].name;
				int staticHash = text.GetStaticHash();
				int value;
				if (pieceTypeToIndex.TryAdd(staticHash, i))
				{
					pieceTypes.Add(staticHash);
				}
				else if (pieceTypeToIndex.TryGetValue(staticHash, out value))
				{
					string text2 = "BuilderFactory: ERROR!! " + $"Could not add pieceType \"{text}\" with hash {staticHash} " + "to 'pieceTypeToIndex' Dictionary because because it was already added!";
					if (value < 0 || value >= list.Count)
					{
						text2 += " Also the index to the conflicting piece is out of range of the pieceList!";
					}
					else
					{
						BuilderPiece builderPiece = list[value];
						text2 = ((!(builderPiece != null)) ? (text2 + "And (should never happen) the piece at that slot is null!") : ((!(text == builderPiece.name)) ? (text2 + "Also the conflicting pieceType has the same hash but different name \"" + builderPiece.name + "\"!") : (text2 + "The conflicting piece has the same name (as expected).")));
					}
					UnityEngine.Debug.LogError(text2, this);
				}
			}
			int num = pieceTypes.Count;
			foreach (BuilderPieceSet allPieceSet in BuilderSetManager.instance.GetAllPieceSets())
			{
				foreach (BuilderPieceSet.BuilderPieceSubset subset in allPieceSet.subsets)
				{
					foreach (BuilderPieceSet.PieceInfo pieceInfo in subset.pieceInfos)
					{
						int staticHash2 = pieceInfo.piecePrefab.name.GetStaticHash();
						if (!pieceTypeToIndex.ContainsKey(staticHash2))
						{
							pieceList.Add(pieceInfo.piecePrefab);
							pieceTypes.Add(staticHash2);
							pieceTypeToIndex.Add(staticHash2, num);
							num++;
						}
					}
				}
			}
		}

		public void Show()
		{
			RefreshUI();
		}

		public BuilderPiece GetPiecePrefab(int pieceType)
		{
			if (pieceTypeToIndex.TryGetValue(pieceType, out var value))
			{
				return pieceList[value];
			}
			UnityEngine.Debug.LogErrorFormat("No Prefab found for type {0}", pieceType);
			return null;
		}

		public void OnBuildItem(BuilderOptionButton button, bool isLeftHand)
		{
			if (pieceTypes != null && pieceTypes.Count > currPieceTypeIndex)
			{
				int selectedMaterialType = GetSelectedMaterialType();
				table.RequestCreatePiece(pieceTypes[currPieceTypeIndex], spawnLocation.position, spawnLocation.rotation, selectedMaterialType);
				if (audioSource != null && buildPieceSound != null)
				{
					audioSource.GTPlayOneShot(buildPieceSound);
				}
			}
		}

		public void OnPrevItem(BuilderOptionButton button, bool isLeftHand)
		{
			if (pieceTypes == null || pieceTypes.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < pieceTypes.Count; i++)
			{
				currPieceTypeIndex = (currPieceTypeIndex - 1 + pieceTypes.Count) % pieceTypes.Count;
				if (CanBuildPieceType(pieceTypes[currPieceTypeIndex]))
				{
					break;
				}
			}
			RefreshUI();
		}

		public void OnNextItem(BuilderOptionButton button, bool isLeftHand)
		{
			if (pieceTypes == null || pieceTypes.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < pieceTypes.Count; i++)
			{
				currPieceTypeIndex = (currPieceTypeIndex + 1 + pieceTypes.Count) % pieceTypes.Count;
				if (CanBuildPieceType(pieceTypes[currPieceTypeIndex]))
				{
					break;
				}
			}
			RefreshUI();
		}

		public void OnPrevMaterial(BuilderOptionButton button, bool isLeftHand)
		{
			if (pieceTypes == null || pieceTypes.Count <= 0)
			{
				return;
			}
			BuilderPiece piecePrefab = GetPiecePrefab(pieceTypes[currPieceTypeIndex]);
			if (!(piecePrefab != null))
			{
				return;
			}
			BuilderMaterialOptions materialOptions = piecePrefab.materialOptions;
			if (materialOptions != null && materialOptions.options.Count > 0)
			{
				for (int i = 0; i < materialOptions.options.Count; i++)
				{
					currPieceMaterialIndex = (currPieceMaterialIndex - 1 + materialOptions.options.Count) % materialOptions.options.Count;
					if (CanUseMaterialType(materialOptions.options[currPieceMaterialIndex].materialId.GetHashCode()))
					{
						break;
					}
				}
			}
			RefreshUI();
		}

		public void OnNextMaterial(BuilderOptionButton button, bool isLeftHand)
		{
			if (pieceTypes == null || pieceTypes.Count <= 0)
			{
				return;
			}
			BuilderPiece piecePrefab = GetPiecePrefab(pieceTypes[currPieceTypeIndex]);
			if (!(piecePrefab != null))
			{
				return;
			}
			BuilderMaterialOptions materialOptions = piecePrefab.materialOptions;
			if (materialOptions != null && materialOptions.options.Count > 0)
			{
				for (int i = 0; i < materialOptions.options.Count; i++)
				{
					currPieceMaterialIndex = (currPieceMaterialIndex + 1 + materialOptions.options.Count) % materialOptions.options.Count;
					if (CanUseMaterialType(materialOptions.options[currPieceMaterialIndex].materialId.GetHashCode()))
					{
						break;
					}
				}
			}
			RefreshUI();
		}

		private int GetSelectedMaterialType()
		{
			int result = -1;
			BuilderPiece piecePrefab = GetPiecePrefab(pieceTypes[currPieceTypeIndex]);
			if (piecePrefab != null)
			{
				BuilderMaterialOptions materialOptions = piecePrefab.materialOptions;
				if (materialOptions != null && materialOptions.options != null && currPieceMaterialIndex >= 0 && currPieceMaterialIndex < materialOptions.options.Count)
				{
					result = materialOptions.options[currPieceMaterialIndex].materialId.GetHashCode();
				}
			}
			return result;
		}

		private string GetSelectedMaterialName()
		{
			string result = "DEFAULT";
			BuilderPiece piecePrefab = GetPiecePrefab(pieceTypes[currPieceTypeIndex]);
			if (piecePrefab != null)
			{
				BuilderMaterialOptions materialOptions = piecePrefab.materialOptions;
				if (materialOptions != null && materialOptions.options != null && currPieceMaterialIndex >= 0 && currPieceMaterialIndex < materialOptions.options.Count)
				{
					result = materialOptions.options[currPieceMaterialIndex].materialId;
				}
			}
			return result;
		}

		public bool CanBuildPieceType(int pieceType)
		{
			BuilderPiece piecePrefab = GetPiecePrefab(pieceType);
			if (piecePrefab == null || piecePrefab.isBuiltIntoTable)
			{
				return false;
			}
			return true;
		}

		public bool CanUseMaterialType(int materalType)
		{
			return true;
		}

		public void RefreshUI()
		{
			if (pieceList != null && pieceList.Count > currPieceTypeIndex)
			{
				itemLabel.SetText(pieceList[currPieceTypeIndex].displayName);
			}
			else
			{
				itemLabel.SetText("No Items");
			}
			if (previewPiece != null)
			{
				table.builderPool.DestroyPiece(previewPiece);
				previewPiece = null;
			}
			if (currPieceTypeIndex >= 0 && currPieceTypeIndex < pieceTypes.Count)
			{
				int pieceType = pieceTypes[currPieceTypeIndex];
				previewPiece = table.builderPool.CreatePiece(pieceType, assertNotEmpty: false);
				previewPiece.SetTable(table);
				previewPiece.pieceType = pieceType;
				string selectedMaterialName = GetSelectedMaterialName();
				materialLabel.SetText(selectedMaterialName);
				previewPiece.SetScale(table.pieceScale * 0.75f);
				previewPiece.SetupPiece(table.gridSize);
				int selectedMaterialType = GetSelectedMaterialType();
				previewPiece.SetMaterial(selectedMaterialType, force: true);
				previewPiece.transform.SetPositionAndRotation(previewMarker.position, previewMarker.rotation);
				previewPiece.SetState(BuilderPiece.State.Displayed);
				previewPiece.enabled = false;
				RefreshCostUI();
			}
		}

		private void RefreshCostUI()
		{
			List<BuilderResourceQuantity> list = null;
			if (previewPiece != null)
			{
				list = previewPiece.cost.quantities;
			}
			for (int i = 0; i < resourceCostUIs.Count; i++)
			{
				if (!(resourceCostUIs[i] == null))
				{
					bool flag = list != null && i < list.Count;
					resourceCostUIs[i].gameObject.SetActive(flag);
					if (flag)
					{
						resourceCostUIs[i].SetResourceCost(list[i], table);
					}
				}
			}
		}

		public void OnAvailableResourcesChange()
		{
			RefreshCostUI();
		}

		public void CreateRandomPiece()
		{
			UnityEngine.Debug.LogError("Create Random Piece No longer implemented");
		}
	}
	public class BuilderItem : TransferrableObject
	{
		private enum BuilderItemState
		{
			isHeld = 1,
			dropped = 2,
			placed = 4,
			unused0 = 8,
			none = 0x10
		}

		public BuilderItemReliableState reliableState;

		public string builtItemPath;

		public GameObject itemRoot;

		private bool enableCollidersWhenReady;

		private float handsFreeOfCollidersTime;

		[NonSerialized]
		public BuilderPiece attachedPiece;

		public List<UnityEngine.Behaviour> onlyWhenPlacedBehaviours;

		[NonSerialized]
		public BuilderItem parentItem;

		public List<BuilderAttachGridPlane> gridPlanes;

		public List<BuilderAttachEdge> edges;

		private List<Collider> colliders;

		private Transform parent;

		private UnityEngine.Vector3 initialPosition;

		private UnityEngine.Quaternion initialRotation;

		private UnityEngine.Vector3 initialGrabInteractorScale;

		private BuilderTable currTable;

		[SerializeField]
		private AudioSource audioSource;

		public AudioClip snapAudio;

		public AudioClip placeAudio;

		public GameObject placeVFX;

		private new BuilderItemState previousItemState = BuilderItemState.dropped;

		public override bool ShouldBeKinematic()
		{
			if (itemState != ItemStates.State2 && itemState != ItemStates.State4)
			{
				return base.ShouldBeKinematic();
			}
			return true;
		}

		protected override void Awake()
		{
			base.Awake();
			parent = base.transform.parent;
			currTable = null;
			initialPosition = base.transform.position;
			initialRotation = base.transform.rotation;
			initialGrabInteractorScale = gripInteractor.transform.localScale;
		}

		internal override void OnEnable()
		{
			base.OnEnable();
		}

		internal override void OnDisable()
		{
			base.OnDisable();
		}

		protected override void Start()
		{
			base.Start();
			itemState = ItemStates.State4;
			currentState = PositionState.Dropped;
		}

		public void AttachPiece(BuilderPiece piece)
		{
			base.transform.SetPositionAndRotation(piece.transform.position, piece.transform.rotation);
			piece.transform.localScale = UnityEngine.Vector3.one;
			piece.transform.SetParent(itemRoot.transform);
			UnityEngine.Debug.LogFormat(piece.gameObject, "Attach Piece {0} to container {1}", piece.gameObject.GetInstanceID(), base.gameObject.GetInstanceID());
			attachedPiece = piece;
		}

		public void DetachPiece(BuilderPiece piece)
		{
			if (piece != attachedPiece)
			{
				UnityEngine.Debug.LogErrorFormat("Trying to detach piece {0} from a container containing {1}", piece.pieceId, attachedPiece.pieceId);
			}
			else
			{
				piece.transform.SetParent(null);
				UnityEngine.Debug.LogFormat(attachedPiece.gameObject, "Detach Piece {0} from container {1}", attachedPiece.gameObject.GetInstanceID(), base.gameObject.GetInstanceID());
				attachedPiece = null;
			}
		}

		private new void OnStateChanged()
		{
			if (itemState == ItemStates.State2)
			{
				enableCollidersWhenReady = true;
				gripInteractor.transform.localScale = initialGrabInteractorScale * 2f;
				handsFreeOfCollidersTime = 0f;
			}
			else
			{
				enableCollidersWhenReady = false;
				gripInteractor.transform.localScale = initialGrabInteractorScale;
				handsFreeOfCollidersTime = 0f;
			}
		}

		public override UnityEngine.Matrix4x4 GetDefaultTransformationMatrix()
		{
			if (reliableState.dirty)
			{
				SetupHandMatrix(reliableState.leftHandAttachPos, reliableState.leftHandAttachRot, reliableState.rightHandAttachPos, reliableState.rightHandAttachRot);
				reliableState.dirty = false;
			}
			return base.GetDefaultTransformationMatrix();
		}

		protected override void LateUpdateShared()
		{
			base.LateUpdateShared();
			if (InHand())
			{
				itemState = ItemStates.State0;
			}
			BuilderItemState builderItemState = (BuilderItemState)itemState;
			if (builderItemState != previousItemState)
			{
				OnStateChanged();
			}
			previousItemState = builderItemState;
			if (enableCollidersWhenReady)
			{
				bool flag = IsOverlapping(EquipmentInteractor.instance.overlapInteractionPointsRight) || IsOverlapping(EquipmentInteractor.instance.overlapInteractionPointsLeft);
				handsFreeOfCollidersTime += (flag ? 0f : Time.deltaTime);
				if (handsFreeOfCollidersTime > 0.1f)
				{
					gripInteractor.transform.localScale = initialGrabInteractorScale;
					enableCollidersWhenReady = false;
				}
			}
		}

		private bool IsOverlapping(List<InteractionPoint> interactionPoints)
		{
			if (interactionPoints == null)
			{
				return false;
			}
			for (int i = 0; i < interactionPoints.Count; i++)
			{
				if (interactionPoints[i] == gripInteractor)
				{
					return true;
				}
			}
			return false;
		}

		protected override void LateUpdateLocal()
		{
			base.LateUpdateLocal();
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			if (!(GorillaTagger.Instance.offlineVRRig.scaleFactor < 1f))
			{
				base.OnGrab(pointGrabbed, grabbingHand);
				itemState = ItemStates.State0;
			}
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			itemState = ItemStates.State1;
			Reparent(null);
			parentItem = null;
			gripInteractor.transform.localScale = initialGrabInteractorScale;
			return true;
		}

		public void OnHoverOverTableStart(BuilderTable table)
		{
			currTable = table;
		}

		public void OnHoverOverTableEnd(BuilderTable table)
		{
			currTable = null;
		}

		public override void OnJoinedRoom()
		{
			base.OnJoinedRoom();
		}

		public override void OnLeftRoom()
		{
			base.OnLeftRoom();
			base.transform.position = initialPosition;
			base.transform.rotation = initialRotation;
			if (worldShareableInstance != null)
			{
				worldShareableInstance.transform.position = initialPosition;
				worldShareableInstance.transform.rotation = initialRotation;
			}
			itemState = ItemStates.State4;
			currentState = PositionState.Dropped;
		}

		private void PlayVFX(GameObject vfx)
		{
			ObjectPools.instance.Instantiate(vfx, base.transform.position);
		}

		private bool Reparent(Transform _transform)
		{
			if (!allowReparenting)
			{
				return false;
			}
			if ((bool)parent)
			{
				parent.SetParent(_transform);
				base.transform.SetParent(parent);
				return true;
			}
			return false;
		}

		private bool ShouldPlayFX()
		{
			if (previousItemState == BuilderItemState.isHeld || previousItemState == BuilderItemState.dropped)
			{
				return true;
			}
			return false;
		}

		public static GameObject BuildEnvItem(int prefabHash, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation)
		{
			GameObject obj = ObjectPools.instance.Instantiate(prefabHash);
			obj.transform.SetPositionAndRotation(position, rotation);
			return obj;
		}

		protected override void OnHandMatrixUpdate(UnityEngine.Vector3 localPosition, UnityEngine.Quaternion localRotation, bool leftHand)
		{
			if (leftHand)
			{
				reliableState.leftHandAttachPos = localPosition;
				reliableState.leftHandAttachRot = localRotation;
			}
			else
			{
				reliableState.rightHandAttachPos = localPosition;
				reliableState.rightHandAttachRot = localRotation;
			}
			reliableState.dirty = true;
		}

		public int GetPhotonViewId()
		{
			if (worldShareableInstance == null)
			{
				return -1;
			}
			return worldShareableInstance.ViewID;
		}
	}
	public class BuilderItemReliableState : MonoBehaviour, IPunObservable
	{
		public UnityEngine.Vector3 rightHandAttachPos = UnityEngine.Vector3.zero;

		public UnityEngine.Quaternion rightHandAttachRot = UnityEngine.Quaternion.identity;

		public UnityEngine.Vector3 leftHandAttachPos = UnityEngine.Vector3.zero;

		public UnityEngine.Quaternion leftHandAttachRot = UnityEngine.Quaternion.identity;

		public bool dirty;

		public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
		{
			if (stream.IsWriting)
			{
				stream.SendNext(rightHandAttachPos);
				stream.SendNext(rightHandAttachRot);
				stream.SendNext(leftHandAttachPos);
				stream.SendNext(leftHandAttachRot);
				return;
			}
			rightHandAttachPos = (UnityEngine.Vector3)stream.ReceiveNext();
			rightHandAttachRot = (UnityEngine.Quaternion)stream.ReceiveNext();
			leftHandAttachPos = (UnityEngine.Vector3)stream.ReceiveNext();
			leftHandAttachRot = (UnityEngine.Quaternion)stream.ReceiveNext();
			if (!rightHandAttachPos.IsValid(10000f))
			{
				rightHandAttachPos = UnityEngine.Vector3.zero;
			}
			if (!rightHandAttachRot.IsValid())
			{
				rightHandAttachRot = quaternion.identity;
			}
			if (!leftHandAttachPos.IsValid(10000f))
			{
				leftHandAttachPos = UnityEngine.Vector3.zero;
			}
			if (!leftHandAttachRot.IsValid())
			{
				leftHandAttachRot = quaternion.identity;
			}
			dirty = true;
		}
	}
