			}

			public bool Equals(SnapOverlapKey other)
			{
				if (piece == other.piece)
				{
					return otherPiece == other.otherPiece;
				}
				return false;
			}

			public override bool Equals(object o)
			{
				if (!(o is SnapOverlapKey))
				{
					return false;
				}
				return Equals((SnapOverlapKey)o);
			}
		}

