		public void RemoveRollBackActions(int localCommandId)
		{
			for (int num = rollBackActions.Count - 1; num >= 0; num--)
			{
				if (localCommandId == -1 || rollBackActions[num].localCommandId == localCommandId)
				{
					rollBackActions.RemoveAt(num);
				}
			}
		}

