		public void BuildPiecesOnShelves()
		{
			if (!isTableMutable || shelves == null)
			{
				return;
			}
			for (int i = 0; i < shelves.Count; i++)
			{
				if (shelves[i] != null)
				{
					shelves[i].Init();
				}
			}
			bool flag = true;
			while (flag)
			{
				flag = false;
				for (int j = 0; j < shelves.Count; j++)
				{
					if (shelves[j].HasOpenSlot())
					{
						shelves[j].BuildNextPiece(this);
						if (shelves[j].HasOpenSlot())
						{
							flag = true;
						}
					}
				}
			}
		}

