		public void PieceDroppedInternal(int localCommandId, int pieceId, UnityEngine.Vector3 position, UnityEngine.Quaternion rotation, UnityEngine.Vector3 velocity, UnityEngine.Vector3 angVelocity, NetPlayer droppedByPlayer, bool force)
		{
			if (force || droppedByPlayer != NetworkSystem.Instance.LocalPlayer || !HasRollForwardCommand(localCommandId) || !TryRollbackAndReExecute(localCommandId))
			{
				BuilderCommand cmd = new BuilderCommand
				{
					type = BuilderCommandType.Drop,
					pieceId = pieceId,
					parentPieceId = pieceId,
					localPosition = position,
					localRotation = rotation,
					velocity = velocity,
					angVelocity = angVelocity,
