	public struct BuilderPotentialPlacementData
	{
		public int pieceId;

		public int parentPieceId;

		public float score;

		public UnityEngine.Vector3 localPosition;

		public UnityEngine.Quaternion localRotation;

		public int attachIndex;

		public int parentAttachIndex;

		public float attachDistance;

		public UnityEngine.Vector3 attachPlaneNormal;

		public SnapBounds attachBounds;

		public SnapBounds parentAttachBounds;

		public byte twist;

		public sbyte bumpOffsetX;

		public sbyte bumpOffsetZ;

		public BuilderPotentialPlacement ToPotentialPlacement(BuilderTable table)
		{
			BuilderPotentialPlacement result = new BuilderPotentialPlacement
			{
				attachPiece = table.GetPiece(pieceId),
				parentPiece = table.GetPiece(parentPieceId),
				score = score,
				localPosition = localPosition,
				localRotation = localRotation,
				attachIndex = attachIndex,
				parentAttachIndex = parentAttachIndex,
				attachDistance = attachDistance,
				attachPlaneNormal = attachPlaneNormal,
				attachBounds = attachBounds,
				parentAttachBounds = parentAttachBounds,
				twist = twist,
				bumpOffsetX = bumpOffsetX,
				bumpOffsetZ = bumpOffsetZ
			};
			if (result.parentPiece != null)
			{
				BuilderAttachGridPlane builderAttachGridPlane = result.parentPiece.gridPlanes[result.parentAttachIndex];
				result.localPosition = builderAttachGridPlane.transform.InverseTransformPoint(result.localPosition);
				result.localRotation = UnityEngine.Quaternion.Inverse(builderAttachGridPlane.transform.rotation) * result.localRotation;
			}
			return result;
		}
	}
	[BurstCompile]
	public struct BuilderFindPotentialSnaps : IJobParallelFor
	{
		[Unity.Collections.ReadOnly]
		public float gridSize;

		[Unity.Collections.ReadOnly]
		public BuilderTable.SnapParams currSnapParams;

		[Unity.Collections.ReadOnly]
		public NativeList<BuilderGridPlaneData> gridPlanes;

		[Unity.Collections.ReadOnly]
		public NativeList<BuilderGridPlaneData> checkGridPlanes;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Vector3 worldToLocalPos;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Quaternion worldToLocalRot;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Vector3 localToWorldPos;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Quaternion localToWorldRot;

		public NativeQueue<BuilderPotentialPlacementData>.ParallelWriter potentialPlacements;

		public void Execute(int index)
		{
			BuilderGridPlaneData gridPlane = gridPlanes[index];
			for (int i = 0; i < checkGridPlanes.Length; i++)
			{
				BuilderGridPlaneData checkGridPlane = checkGridPlanes[i];
				BuilderPotentialPlacementData potentialPlacement = default(BuilderPotentialPlacementData);
				if (TryPlaceGridPlaneOnGridPlane(ref gridPlane, ref checkGridPlane, ref potentialPlacement))
				{
					potentialPlacements.Enqueue(potentialPlacement);
				}
			}
		}

		public bool TryPlaceGridPlaneOnGridPlane(ref BuilderGridPlaneData gridPlane, ref BuilderGridPlaneData checkGridPlane, ref BuilderPotentialPlacementData potentialPlacement)
		{
			if (checkGridPlane.male == gridPlane.male)
			{
				return false;
			}
			if (checkGridPlane.pieceId == gridPlane.pieceId)
			{
				return false;
			}
			UnityEngine.Vector3 position = gridPlane.position;
			UnityEngine.Quaternion rotation = gridPlane.rotation;
			UnityEngine.Vector3 vector = worldToLocalRot * (position + worldToLocalPos);
			UnityEngine.Quaternion quaternion2 = worldToLocalRot * rotation;
			position = localToWorldPos + localToWorldRot * vector;
			rotation = localToWorldRot * quaternion2;
			UnityEngine.Vector3 position2 = checkGridPlane.position;
			float sqrMagnitude = (position2 - position).sqrMagnitude;
			float num = checkGridPlane.boundingRadius + gridPlane.boundingRadius;
			if (sqrMagnitude > num * num)
			{
				return false;
			}
			UnityEngine.Quaternion rotation2 = checkGridPlane.rotation;
			UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.Inverse(rotation2);
			UnityEngine.Quaternion quaternion4 = quaternion3 * rotation;
			float num2 = UnityEngine.Vector3.Dot(UnityEngine.Vector3.up, quaternion4 * UnityEngine.Vector3.up);
			if (num2 < currSnapParams.maxUpDotProduct)
			{
				return false;
			}
			UnityEngine.Vector3 vector2 = quaternion3 * (position - position2);
			float y = vector2.y;
			if (Mathf.Abs(y) > 1f)
			{
				return false;
			}
			if ((gridPlane.male && y > currSnapParams.minOffsetY) || (!gridPlane.male && y < 0f - currSnapParams.minOffsetY))
			{
				return false;
			}
			if (Mathf.Abs(y) > currSnapParams.maxOffsetY)
			{
				return false;
			}
			UnityEngine.Quaternion twist = UnityEngine.Quaternion.identity;
			if (new UnityEngine.Vector3(quaternion4.x, quaternion4.y, quaternion4.z).sqrMagnitude > BoingKit.MathUtil.Epsilon)
			{
				BoingKit.QuaternionUtil.DecomposeSwingTwist(quaternion4, UnityEngine.Vector3.up, out var _, out twist);
			}
			float maxTwistDotProduct = currSnapParams.maxTwistDotProduct;
			UnityEngine.Vector3 lhs = twist * UnityEngine.Vector3.forward;
			float num3 = UnityEngine.Vector3.Dot(lhs, UnityEngine.Vector3.forward);
			float num4 = UnityEngine.Vector3.Dot(lhs, UnityEngine.Vector3.right);
			bool flag = Mathf.Abs(num3) > maxTwistDotProduct;
			bool flag2 = Mathf.Abs(num4) > maxTwistDotProduct;
			if (!(flag || flag2))
			{
				return false;
			}
			uint num5 = 0u;
			float y2;
			if (flag)
			{
				y2 = ((num3 > 0f) ? 0f : 180f);
				num5 = ((!(num3 > 0f)) ? 2u : 0u);
			}
			else
			{
				y2 = ((num4 > 0f) ? 90f : 270f);
				num5 = ((num4 > 0f) ? 1u : 3u);
			}
			int num6 = (flag2 ? gridPlane.width : gridPlane.length);
			int num7 = (flag2 ? gridPlane.length : gridPlane.width);
			float num8 = ((num7 % 2 == 0) ? (gridSize / 2f) : 0f);
			float num9 = ((num6 % 2 == 0) ? (gridSize / 2f) : 0f);
			float num10 = ((checkGridPlane.width % 2 == 0) ? (gridSize / 2f) : 0f);
			float num11 = ((checkGridPlane.length % 2 == 0) ? (gridSize / 2f) : 0f);
			float num12 = num8 - num10;
			float num13 = num9 - num11;
			int num14 = Mathf.RoundToInt((vector2.x - num12) / gridSize);
			int num15 = Mathf.RoundToInt((vector2.z - num13) / gridSize);
			int num16 = num14 + Mathf.FloorToInt((float)num7 / 2f);
			int num17 = num15 + Mathf.FloorToInt((float)num6 / 2f);
			int num18 = num16 - (num7 - 1);
			int num19 = num17 - (num6 - 1);
			int num20 = Mathf.FloorToInt((float)checkGridPlane.width / 2f);
			int num21 = Mathf.FloorToInt((float)checkGridPlane.length / 2f);
			int num22 = num20 - (checkGridPlane.width - 1);
			int num23 = num21 - (checkGridPlane.length - 1);
			if (num18 > num20 || num16 < num22 || num19 > num21 || num17 < num23)
			{
				return false;
			}
			UnityEngine.Quaternion quaternion5 = UnityEngine.Quaternion.Euler(0f, y2, 0f);
			UnityEngine.Quaternion quaternion6 = rotation2 * quaternion5;
			float x = (float)num14 * gridSize + num12;
			float z = (float)num15 * gridSize + num13;
			UnityEngine.Vector3 vector3 = new UnityEngine.Vector3(x, 0f, z);
			UnityEngine.Vector3 vector4 = position2 + rotation2 * vector3;
			UnityEngine.Quaternion quaternion7 = quaternion6 * UnityEngine.Quaternion.Inverse(gridPlane.localRotation);
			UnityEngine.Vector3 localPosition = vector4 - quaternion7 * gridPlane.localPosition;
			potentialPlacement.localPosition = localPosition;
			potentialPlacement.localRotation = quaternion7;
			float num24 = 0.025f;
			float score = 0f - Mathf.Abs(y) + num2 * num24;
			potentialPlacement.score = score;
			potentialPlacement.pieceId = gridPlane.pieceId;
			potentialPlacement.attachIndex = gridPlane.attachIndex;
			potentialPlacement.parentPieceId = checkGridPlane.pieceId;
			potentialPlacement.parentAttachIndex = checkGridPlane.attachIndex;
			potentialPlacement.attachDistance = Mathf.Abs(y);
			potentialPlacement.attachPlaneNormal = UnityEngine.Vector3.up;
			if (!checkGridPlane.male)
			{
				potentialPlacement.attachPlaneNormal *= -1f;
			}
			potentialPlacement.parentAttachBounds.min.x = Mathf.Max(num22, num18);
			potentialPlacement.parentAttachBounds.min.y = Mathf.Max(num23, num19);
			potentialPlacement.parentAttachBounds.max.x = Mathf.Min(num20, num16);
			potentialPlacement.parentAttachBounds.max.y = Mathf.Min(num21, num17);
			potentialPlacement.twist = (byte)num5;
			potentialPlacement.bumpOffsetX = (sbyte)num14;
			potentialPlacement.bumpOffsetZ = (sbyte)num15;
			Vector2Int v = Vector2Int.zero;
			Vector2Int v2 = Vector2Int.zero;
			v.x = potentialPlacement.parentAttachBounds.min.x - num14;
			v2.x = potentialPlacement.parentAttachBounds.max.x - num14;
			v.y = potentialPlacement.parentAttachBounds.min.y - num15;
			v2.y = potentialPlacement.parentAttachBounds.max.y - num15;
			int offsetX = ((num7 % 2 == 0) ? 1 : 0);
			int offsetY = ((num6 % 2 == 0) ? 1 : 0);
			if (flag && num3 <= 0f)
			{
				v = Rotate180(v, offsetX, offsetY);
				v2 = Rotate180(v2, offsetX, offsetY);
			}
			else if (flag2 && num4 <= 0f)
			{
				v = Rotate270(v, offsetX, offsetY);
				v2 = Rotate270(v2, offsetX, offsetY);
			}
			else if (flag2 && num4 >= 0f)
			{
				v = Rotate90(v, offsetX, offsetY);
				v2 = Rotate90(v2, offsetX, offsetY);
			}
			potentialPlacement.attachBounds.min.x = Mathf.Min(v.x, v2.x);
			potentialPlacement.attachBounds.min.y = Mathf.Min(v.y, v2.y);
			potentialPlacement.attachBounds.max.x = Mathf.Max(v.x, v2.x);
			potentialPlacement.attachBounds.max.y = Mathf.Max(v.y, v2.y);
			return true;
		}

		private Vector2Int Rotate90(Vector2Int v, int offsetX, int offsetY)
		{
			return new Vector2Int(v.y * -1 + offsetY, v.x);
		}

		private Vector2Int Rotate270(Vector2Int v, int offsetX, int offsetY)
		{
			return new Vector2Int(v.y, v.x * -1 + offsetX);
		}

		private Vector2Int Rotate180(Vector2Int v, int offsetX, int offsetY)
		{
			return new Vector2Int(v.x * -1 + offsetX, v.y * -1 + offsetY);
		}
	}
	public class BuilderTableJobs
	{
		public static void BuildTestPieceListForJob(BuilderPiece testPiece, NativeList<BuilderPieceData> testPieceList, NativeList<BuilderGridPlaneData> testGridPlaneList)
		{
			if (!(testPiece == null))
			{
				int length = testPieceList.Length;
				testPieceList.Add(new BuilderPieceData(testPiece));
				for (int i = 0; i < testPiece.gridPlanes.Count; i++)
				{
					testGridPlaneList.Add(new BuilderGridPlaneData(testPiece.gridPlanes[i], length));
				}
				BuilderPiece builderPiece = testPiece.firstChildPiece;
				while (builderPiece != null)
				{
					BuildTestPieceListForJob(builderPiece, testPieceList, testGridPlaneList);
					builderPiece = builderPiece.nextSiblingPiece;
				}
			}
		}

		public static void BuildTestPieceListForJob(BuilderPiece testPiece, NativeList<BuilderGridPlaneData> testGridPlaneList)
		{
			if (!(testPiece == null))
			{
				for (int i = 0; i < testPiece.gridPlanes.Count; i++)
				{
					testGridPlaneList.Add(new BuilderGridPlaneData(testPiece.gridPlanes[i], -1));
				}
				BuilderPiece builderPiece = testPiece.firstChildPiece;
				while (builderPiece != null)
				{
					BuildTestPieceListForJob(builderPiece, testGridPlaneList);
					builderPiece = builderPiece.nextSiblingPiece;
				}
			}
		}
	}
	[BurstCompile]
	internal struct FindNearbyPiecesJob : IJobParallelForTransform
	{
		[Unity.Collections.ReadOnly]
		public float distanceThreshSq;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Vector3 leftHandPos;

		[Unity.Collections.ReadOnly]
		public int leftPieceInHandIndex;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Vector3 rightHandPos;

		[Unity.Collections.ReadOnly]
		public int rightPieceInHandIndex;

		[Unity.Collections.ReadOnly]
		public int localPlayerPlotIndex;

		[Unity.Collections.ReadOnly]
		public int localPlayerActorNumber;

		[Unity.Collections.ReadOnly]
		public NativeArray<BuilderPieceData> pieceData;

		[Unity.Collections.ReadOnly]
		public NativeArray<BuilderGridPlaneData> gridPlaneData;

		[Unity.Collections.ReadOnly]
		public NativeArray<BuilderPrivatePlotData> privatePlotData;

		[Unity.Collections.ReadOnly]
		public NativeArray<BuilderPlayerData> playerData;

		public NativeList<BuilderGridPlaneData>.ParallelWriter leftHandGridPlanes;

		public NativeList<BuilderGridPlaneData>.ParallelWriter rightHandGridPlanes;

		public void Execute(int index, TransformAccess transform)
		{
			if (transform.isValid)
			{
				CheckGridPlane(index, leftPieceInHandIndex, transform, leftHandPos, isLeft: true, leftHandGridPlanes);
				CheckGridPlane(index, rightPieceInHandIndex, transform, rightHandPos, isLeft: false, rightHandGridPlanes);
			}
		}

		private void CheckGridPlane(int gridPlaneIndex, int handPieceIndex, TransformAccess transform, UnityEngine.Vector3 handPos, bool isLeft, NativeList<BuilderGridPlaneData>.ParallelWriter checkGridPlanes)
		{
			if (handPieceIndex >= 0 && !((transform.position - handPos).sqrMagnitude > distanceThreshSq))
			{
				BuilderGridPlaneData value = gridPlaneData[gridPlaneIndex];
				int pieceIndex = value.pieceIndex;
				int rootPieceIndex = GetRootPieceIndex(pieceIndex);
				if (rootPieceIndex != handPieceIndex && CanPiecesPotentiallySnap(localPlayerActorNumber, handPieceIndex, pieceIndex, rootPieceIndex, pieceData[pieceIndex].requestedParentPieceIndex, isLeft))
				{
					transform.GetPositionAndRotation(out value.position, out value.rotation);
					checkGridPlanes.AddNoResize(value);
				}
			}
		}

		public bool CanPiecesPotentiallySnap(int localActorNumber, int pieceInHandIndex, int attachToPieceIndex, int attachToPieceRootIndex, int requestedParentPieceIndex, bool isLeft)
		{
			if (!CanPlayerAttachToRootPiece(localActorNumber, attachToPieceRootIndex, isLeft))
			{
				return false;
			}
			if (requestedParentPieceIndex != -1 && pieceInHandIndex == GetRootPieceIndex(requestedParentPieceIndex))
			{
				return false;
			}
			return true;
		}

		public bool CanPlayerAttachToRootPiece(int playerActorNumber, int attachToPieceRootIndex, bool isLeft)
		{
			BuilderPieceData builderPieceData = pieceData[attachToPieceRootIndex];
			if (builderPieceData.state != BuilderPiece.State.AttachedAndPlaced && builderPieceData.privatePlotIndex < 0 && builderPieceData.state != BuilderPiece.State.AttachedToArm)
			{
				return true;
			}
			int attachedBuiltInPiece = GetAttachedBuiltInPiece(attachToPieceRootIndex);
			if (attachedBuiltInPiece == -1)
			{
				return true;
			}
			BuilderPieceData builderPieceData2 = pieceData[attachedBuiltInPiece];
			if (builderPieceData2.privatePlotIndex < 0 && !builderPieceData2.isArmPiece)
			{
				return true;
			}
			if (builderPieceData2.isArmPiece)
			{
				if (builderPieceData2.heldByActorNumber == playerActorNumber)
				{
					int playerIndex = GetPlayerIndex(playerActorNumber);
					if (playerIndex < 0)
					{
						return false;
					}
					return playerData[playerIndex].scale >= 1f;
				}
				return false;
			}
			if (builderPieceData2.privatePlotIndex >= 0)
			{
				if (CanPlayerAttachToPlot(builderPieceData2.privatePlotIndex, playerActorNumber))
				{
					if (!isLeft)
					{
						return privatePlotData[builderPieceData2.privatePlotIndex].isUnderCapacityRight;
					}
					return privatePlotData[builderPieceData2.privatePlotIndex].isUnderCapacityLeft;
				}
				return false;
			}
			return true;
		}

		public bool CanPlayerAttachToPlot(int privatePlotIndex, int actorNumber)
		{
			BuilderPrivatePlotData builderPrivatePlotData = privatePlotData[privatePlotIndex];
			if (builderPrivatePlotData.plotState != BuilderPiecePrivatePlot.PlotState.Occupied || builderPrivatePlotData.ownerActorNumber != actorNumber)
			{
				if (builderPrivatePlotData.plotState == BuilderPiecePrivatePlot.PlotState.Vacant)
				{
					return localPlayerPlotIndex < 0;
				}
				return false;
			}
			return true;
		}

		private int GetPlayerIndex(int playerActorNumber)
		{
			for (int i = 0; i < playerData.Length; i++)
			{
				if (playerData[i].playerActorNumber == playerActorNumber)
				{
					return i;
				}
			}
			return -1;
		}

		public int GetAttachedBuiltInPiece(int pieceIndex)
		{
			BuilderPieceData builderPieceData = pieceData[pieceIndex];
			if (builderPieceData.isBuiltIntoTable)
			{
				return pieceIndex;
			}
			if (builderPieceData.state != BuilderPiece.State.AttachedAndPlaced)
			{
				return -1;
			}
			int num = GetRootPieceIndex(pieceIndex);
			int parentPieceIndex = pieceData[num].parentPieceIndex;
			if (parentPieceIndex != -1)
			{
				num = parentPieceIndex;
			}
			if (pieceData[num].isBuiltIntoTable)
			{
				return num;
			}
			return -1;
		}

		private int GetRootPieceIndex(int pieceIndex)
		{
			int num = pieceIndex;
			while (num != -1 && pieceData[num].parentPieceIndex != -1 && !pieceData[pieceData[num].parentPieceIndex].isBuiltIntoTable)
			{
				num = pieceData[num].parentPieceIndex;
			}
			return num;
		}
	}
