			snapPosition = (UnityEngine.Vector3)stream.ReceiveNext();
			respawnPosition = (UnityEngine.Vector3)stream.ReceiveNext();
			respawnRotation = (UnityEngine.Quaternion)stream.ReceiveNext();
			if (!snapPosition.IsValid(10000f))
			{
				snapPosition = UnityEngine.Vector3.zero;
			}
			if (!respawnPosition.IsValid(10000f))
			{
				respawnPosition = UnityEngine.Vector3.zero;
			}
			if (!respawnRotation.IsValid())
			{
				respawnRotation = quaternion.identity;
			}
		}
	}
