	internal class CMSSerializer : GorillaSerializer
	{
		[OnEnterPlay_SetNull]
		private static volatile CMSSerializer instance;

		[OnEnterPlay_Set(false)]
		private static bool hasInstance;

		private static Dictionary<string, Dictionary<byte, CMSTrigger>> registeredTriggersPerScene = new Dictionary<string, Dictionary<byte, CMSTrigger>>();

		private static List<byte> triggerHistory = new List<byte>();

		private static Dictionary<byte, byte> triggerCounts = new Dictionary<byte, byte>();

		private static bool waitingForTriggerHistory;

		private static List<string> scenesWaitingForTriggerHistory = new List<string>();

		private static bool waitingForTriggerCounts;

		private static List<string> scenesWaitingForTriggerCounts = new List<string>();

		private static CallLimiter ActivateTriggerCallLimiter = new CallLimiter(50, 1f);

		public static UnityEvent<string> OnTriggerHistoryProcessedForScene = new UnityEvent<string>();

		public void Awake()
		{
			if (instance != null)
			{
				UnityEngine.Object.Destroy(this);
			}
			instance = this;
			hasInstance = true;
		}

		public void OnEnable()
		{
			CustomMapManager.OnMapLoadComplete.RemoveListener(OnCustomMapLoaded);
			CustomMapManager.OnMapLoadComplete.AddListener(OnCustomMapLoaded);
		}

		public void OnDisable()
		{
			CustomMapManager.OnMapLoadComplete.RemoveListener(OnCustomMapLoaded);
		}

		private void OnCustomMapLoaded(bool success)
		{
			if (success)
			{
				RequestSyncTriggerHistory();
			}
		}

		public static void ResetSyncedMapObjects()
		{
			triggerHistory.Clear();
			triggerCounts.Clear();
			registeredTriggersPerScene.Clear();
			waitingForTriggerHistory = false;
			waitingForTriggerCounts = false;
		}

		public static void RegisterTrigger(string sceneName, CMSTrigger trigger)
		{
			if (registeredTriggersPerScene.TryGetValue(sceneName, out var value))
			{
				if (!value.ContainsKey(trigger.GetID()))
				{
					value.Add(trigger.GetID(), trigger);
				}
			}
			else
			{
				registeredTriggersPerScene.Add(sceneName, new Dictionary<byte, CMSTrigger> { 
				{
					trigger.GetID(),
					trigger
				} });
			}
		}

		private static bool TryGetRegisteredTrigger(byte triggerID, out CMSTrigger trigger)
		{
			trigger = null;
			foreach (KeyValuePair<string, Dictionary<byte, CMSTrigger>> item in registeredTriggersPerScene)
			{
				if (item.Value.TryGetValue(triggerID, out trigger))
				{
					return true;
				}
			}
			return false;
		}

		public static void UnregisterTriggers(string forScene)
		{
			registeredTriggersPerScene.Remove(forScene);
		}

		public static void ResetTrigger(byte triggerID)
		{
			triggerCounts.Remove(triggerID);
		}

		private static void RequestSyncTriggerHistory()
		{
			if (hasInstance && NetworkSystem.Instance.InRoom && !NetworkSystem.Instance.IsMasterClient)
			{
				waitingForTriggerHistory = true;
				waitingForTriggerCounts = true;
				instance.SendRPC("RequestSyncTriggerHistory_RPC", false);
			}
		}

		[PunRPC]
		private void RequestSyncTriggerHistory_RPC(PhotonMessageInfo info)
		{
			MonkeAgent.IncrementRPCCall(info, "RequestSyncTriggerHistory_RPC");
			if (NetworkSystem.Instance.InRoom && NetworkSystem.Instance.IsMasterClient)
			{
				NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
				if (!player.CheckSingleCallRPC(NetPlayer.SingleCallRPC.CMS_RequestTriggerHistory))
				{
					player.ReceivedSingleCallRPC(NetPlayer.SingleCallRPC.CMS_RequestTriggerHistory);
					byte[] array = triggerHistory.ToArray();
					SendRPC("SyncTriggerHistory_RPC", info.Sender, array);
					SendRPC("SyncTriggerCounts_RPC", info.Sender, triggerCounts);
				}
			}
		}

		[PunRPC]
		private void SyncTriggerHistory_RPC(byte[] syncedTriggerHistory, PhotonMessageInfo info)
		{
			MonkeAgent.IncrementRPCCall(info, "SyncTriggerHistory_RPC");
			if (!NetworkSystem.Instance.InRoom || !info.Sender.IsMasterClient)
			{
				return;
			}
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (player.CheckSingleCallRPC(NetPlayer.SingleCallRPC.CMS_SyncTriggerHistory))
			{
				return;
			}
			player.ReceivedSingleCallRPC(NetPlayer.SingleCallRPC.CMS_SyncTriggerHistory);
			if (!waitingForTriggerHistory)
			{
				return;
			}
			triggerHistory.Clear();
			if (!syncedTriggerHistory.IsNullOrEmpty())
			{
				triggerHistory.AddRange(syncedTriggerHistory);
			}
			waitingForTriggerHistory = false;
			foreach (string item in scenesWaitingForTriggerHistory)
			{
				ProcessTriggerHistory(item);
			}
			scenesWaitingForTriggerHistory.Clear();
		}

		[PunRPC]
		private void SyncTriggerCounts_RPC(Dictionary<byte, byte> syncedTriggerCounts, PhotonMessageInfo info)
		{
			MonkeAgent.IncrementRPCCall(info, "SyncTriggerCounts_RPC");
			if (!NetworkSystem.Instance.InRoom || !info.Sender.IsMasterClient)
			{
				return;
			}
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (player.CheckSingleCallRPC(NetPlayer.SingleCallRPC.CMS_SyncTriggerCounts))
			{
				return;
			}
			player.ReceivedSingleCallRPC(NetPlayer.SingleCallRPC.CMS_SyncTriggerCounts);
			if (!waitingForTriggerCounts)
			{
				return;
			}
			triggerCounts.Clear();
			if (syncedTriggerCounts != null && syncedTriggerCounts.Count > 0)
			{
				triggerCounts = syncedTriggerCounts;
			}
			waitingForTriggerCounts = false;
			foreach (string scenesWaitingForTriggerCount in scenesWaitingForTriggerCounts)
			{
				ProcessTriggerCounts(scenesWaitingForTriggerCount);
			}
			scenesWaitingForTriggerCounts.Clear();
		}

		public static void ProcessSceneLoad(string sceneName)
		{
			if (waitingForTriggerHistory)
			{
				scenesWaitingForTriggerHistory.Add(sceneName);
			}
			else
			{
				ProcessTriggerHistory(sceneName);
			}
			if (waitingForTriggerCounts)
			{
				scenesWaitingForTriggerCounts.Add(sceneName);
			}
			else
			{
				ProcessTriggerCounts(sceneName);
			}
		}

		private static void ProcessTriggerHistory(string forScene)
		{
			if (registeredTriggersPerScene.TryGetValue(forScene, out var value))
			{
				foreach (byte item in triggerHistory)
				{
					if (value.TryGetValue(item, out var value2))
					{
						value2.Trigger(1.0, originatedLocally: false, ignoreTriggerCount: true);
					}
				}
			}
			OnTriggerHistoryProcessedForScene?.Invoke(forScene);
		}

		private static void ProcessTriggerCounts(string forScene)
		{
			if (!registeredTriggersPerScene.TryGetValue(forScene, out var value))
			{
				return;
			}
			List<byte> list = new List<byte>();
			foreach (KeyValuePair<byte, byte> triggerCount in triggerCounts)
			{
				if (value.TryGetValue(triggerCount.Key, out var value2))
				{
					if (value2.numAllowedTriggers > 0)
					{
						value2.SetTriggerCount(triggerCount.Value);
					}
					else
					{
						list.Add(triggerCount.Key);
					}
				}
			}
			foreach (byte item in list)
			{
				triggerCounts.Remove(item);
			}
		}

		public static void RequestTrigger(byte triggerID)
		{
			if (!hasInstance)
			{
				return;
			}
			if (!NetworkSystem.Instance.InRoom || NetworkSystem.Instance.IsMasterClient)
			{
				double triggerTime = Time.time;
				if (NetworkSystem.Instance.InRoom)
				{
					triggerTime = PhotonNetwork.Time;
					instance.SendRPC("ActivateTrigger_RPC", true, triggerID, NetworkSystem.Instance.LocalPlayer.ActorNumber);
				}
				instance.ActivateTrigger(triggerID, triggerTime, originatedLocally: true);
			}
			else
			{
				instance.SendRPC("RequestTrigger_RPC", false, triggerID);
			}
		}

		[PunRPC]
		private void RequestTrigger_RPC(byte triggerID, PhotonMessageInfo info)
		{
			MonkeAgent.IncrementRPCCall(info, "RequestTrigger_RPC");
			if (!NetworkSystem.Instance.InRoom || !NetworkSystem.Instance.IsMasterClient)
			{
				return;
			}
			NetPlayer player = NetworkSystem.Instance.GetPlayer(info.Sender);
			if (!VRRigCache.Instance.TryGetVrrig(player, out var playerRig) || !playerRig.Rig.fxSettings.callSettings[11].CallLimitSettings.CheckCallTime(Time.unscaledTime))
			{
				return;
			}
			if (TryGetRegisteredTrigger(triggerID, out var trigger))
			{
				if (!trigger.CanTrigger())
				{
					return;
				}
				UnityEngine.Vector3 position = trigger.gameObject.transform.position;
				if (!VRRigCache.Instance.TryGetVrrig(info.Sender, out var playerRig2) || (playerRig2.Rig.bodyTransform.position - position).sqrMagnitude > trigger.validationDistanceSquared)
				{
					return;
				}
			}
			SendRPC("ActivateTrigger_RPC", true, triggerID, info.Sender.ActorNumber);
			ActivateTrigger(triggerID, info.SentServerTime);
		}

		[PunRPC]
		private void ActivateTrigger_RPC(byte triggerID, int originatingPlayer, PhotonMessageInfo info)
		{
			MonkeAgent.IncrementRPCCall(info, "ActivateTrigger_RPC");
			if (NetworkSystem.Instance.InRoom && info.Sender.IsMasterClient && !(info.SentServerTime < 0.0) && !(info.SentServerTime > 4294967.295))
			{
				double num = (double)PhotonNetwork.GetPing() / 1000.0;
				if (Utils.ValidateServerTime(info.SentServerTime, System.Math.Max(10.0, num * 2.0)) && ActivateTriggerCallLimiter.CheckCallTime(Time.unscaledTime))
				{
					ActivateTrigger(triggerID, info.SentServerTime, NetworkSystem.Instance.LocalPlayer.ActorNumber == originatingPlayer);
				}
			}
		}

		private void ActivateTrigger(byte triggerID, double triggerTime = -1.0, bool originatedLocally = false)
		{
			CMSTrigger trigger;
			bool flag = TryGetRegisteredTrigger(triggerID, out trigger);
			if (!double.IsFinite(triggerTime))
			{
				triggerTime = -1.0;
			}
			byte value;
			bool num = triggerCounts.TryGetValue(triggerID, out value);
			bool flag2 = !flag || trigger.numAllowedTriggers > 0;
			if (num)
			{
				triggerCounts[triggerID] = ((value == byte.MaxValue) ? byte.MaxValue : (++value));
			}
			else if (flag2)
			{
				triggerCounts.Add(triggerID, 1);
			}
			triggerHistory.Remove(triggerID);
			triggerHistory.Add(triggerID);
			if (flag)
			{
				trigger.Trigger(triggerTime, originatedLocally);
			}
		}
	}
	public class CMSTagZone : CMSTrigger
	{
		public override void Trigger(double triggerTime = -1.0, bool originatedLocally = false, bool ignoreTriggerCount = false)
		{
			base.Trigger(triggerTime, originatedLocally, ignoreTriggerCount);
			if (originatedLocally)
			{
				GorillaGameModes.GameMode.ReportHit();
			}
		}
	}
	public class CMSTeleporter : CMSTrigger
	{
		[Tooltip("Teleport points used to return the player to the map. Chosen at random.")]
		[SerializeField]
		[JetBrains.Annotations.NotNull]
		public List<Transform> TeleportPoints = new List<Transform>();

		public bool matchTeleportPointRotation;

		public bool maintainVelocity;

		public override void CopyTriggerSettings(TriggerSettings settings)
		{
			if (settings.GetType() == typeof(TeleporterSettings))
			{
				TeleporterSettings teleporterSettings = (TeleporterSettings)settings;
				TeleportPoints = teleporterSettings.TeleportPoints;
				matchTeleportPointRotation = teleporterSettings.matchTeleportPointRotation;
				maintainVelocity = teleporterSettings.maintainVelocity;
			}
			for (int num = TeleportPoints.Count - 1; num >= 0; num--)
			{
				if (TeleportPoints[num] == null)
				{
					TeleportPoints.RemoveAt(num);
				}
			}
			base.CopyTriggerSettings(settings);
		}

		public override void Trigger(double triggerTime = -1.0, bool originatedLocally = false, bool ignoreTriggerCount = false)
		{
			base.Trigger(triggerTime, originatedLocally, ignoreTriggerCount);
			if (!originatedLocally || !GTPlayer.hasInstance)
			{
				return;
			}
			GTPlayer instance = GTPlayer.Instance;
			if (TeleportPoints.Count != 0)
			{
				Transform transform = TeleportPoints[UnityEngine.Random.Range(0, TeleportPoints.Count)];
				if (transform != null)
				{
					instance.TeleportTo(transform, matchTeleportPointRotation, maintainVelocity);
				}
			}
		}
	}
	public class CMSTrigger : MonoBehaviour
	{
		public const byte INVALID_TRIGGER_ID = byte.MaxValue;

		public const double MAX_PHOTON_SERVER_TIME = 4294967.295;

		public const float MINIMUM_VALIDATION_DISTANCE = 2f;

		public bool syncedToAllPlayers;

		public float validationDistanceSquared;

		public TriggerSource triggeredBy = TriggerSource.HeadOrBody;

		public double onEnableTriggerDelay;

		public double generalRetriggerDelay;

		public bool retriggerAfterDuration;

		public double retriggerStayDuration = 2.0;

		public byte numAllowedTriggers;

		private byte numTimesTriggered;

		private double lastTriggerTime = -1.0;

		private double enabledTime = -1.0;

		public byte id = byte.MaxValue;

		public void OnEnable()
		{
			if (onEnableTriggerDelay > 0.0)
			{
				enabledTime = Time.time;
			}
		}

		public byte GetID()
		{
			return id;
		}

		public virtual void CopyTriggerSettings(TriggerSettings settings)
		{
			id = settings.triggerId;
			triggeredBy = settings.triggeredBy;
			float num = System.Math.Max(settings.validationDistance, 2f);
			validationDistanceSquared = num * num;
			if (triggeredBy == TriggerSource.None)
			{
				if (settings.triggeredByHead && !settings.triggeredByBody)
				{
					triggeredBy = TriggerSource.Head;
				}
				else if (settings.triggeredByBody && !settings.triggeredByHead)
				{
					triggeredBy = TriggerSource.Body;
				}
				else if (settings.triggeredByHands && !settings.triggeredByHead && !settings.triggeredByBody)
				{
					triggeredBy = TriggerSource.Hands;
				}
				else
				{
					triggeredBy = TriggerSource.HeadOrBody;
				}
			}
			switch (triggeredBy)
			{
			case TriggerSource.Head:
			case TriggerSource.Body:
			case TriggerSource.HeadOrBody:
				base.gameObject.layer = UnityLayer.GorillaTrigger.ToLayerIndex();
				break;
			case TriggerSource.Hands:
				base.gameObject.layer = UnityLayer.GorillaInteractable.ToLayerIndex();
				break;
			}
			onEnableTriggerDelay = settings.onEnableTriggerDelay;
			generalRetriggerDelay = settings.generalRetriggerDelay;
			retriggerAfterDuration = settings.retriggerAfterDuration;
			if (System.Math.Abs(settings.retriggerDelay - 2f) > 0.001f && System.Math.Abs(settings.retriggerStayDuration - 2.0) < 0.001)
			{
				settings.retriggerStayDuration = settings.retriggerDelay;
			}
			retriggerStayDuration = System.Math.Max(generalRetriggerDelay, settings.retriggerStayDuration);
			if (retriggerStayDuration <= 0.0)
			{
				retriggerAfterDuration = false;
			}
			numAllowedTriggers = settings.numAllowedTriggers;
			syncedToAllPlayers = settings.syncedToAllPlayers_private;
			if (syncedToAllPlayers)
			{
				CMSSerializer.RegisterTrigger(base.gameObject.scene.name, this);
			}
			Collider[] components = base.gameObject.GetComponents<Collider>();
			for (int i = 0; i < components.Length; i++)
			{
				components[i].isTrigger = true;
			}
		}

		public void OnTriggerEnter(Collider triggeringCollider)
		{
			if (ValidateCollider(triggeringCollider) && CanTrigger())
			{
				OnTriggerActivation(triggeringCollider);
			}
		}

		private void OnTriggerStay(Collider other)
		{
			if (retriggerAfterDuration && ValidateCollider(other) && CanTrigger())
			{
				double num = Time.time;
				if (NetworkSystem.Instance.InRoom)
				{
					num = PhotonNetwork.Time;
				}
				if (lastTriggerTime + retriggerStayDuration <= num)
				{
					OnTriggerActivation(other);
				}
			}
		}

		private bool ValidateCollider(Collider other)
		{
			GameObject gameObject = other.gameObject;
			bool num = gameObject == GorillaTagger.Instance.headCollider.gameObject && (triggeredBy == TriggerSource.Head || triggeredBy == TriggerSource.HeadOrBody);
			bool flag = false;
			flag = ((!GorillaTagger.Instance.bodyCollider.enabled) ? (gameObject == VRRig.LocalRig.gameObject && (triggeredBy == TriggerSource.Body || triggeredBy == TriggerSource.HeadOrBody)) : (gameObject == GorillaTagger.Instance.bodyCollider.gameObject && (triggeredBy == TriggerSource.Body || triggeredBy == TriggerSource.HeadOrBody)));
			bool flag2 = (gameObject == GorillaTagger.Instance.leftHandTriggerCollider.gameObject || gameObject == GorillaTagger.Instance.rightHandTriggerCollider.gameObject) && triggeredBy == TriggerSource.Hands;
			return num || flag || flag2;
		}

		private void OnTriggerActivation(Collider activatingCollider)
		{
			if (syncedToAllPlayers)
			{
				CMSSerializer.RequestTrigger(id);
			}
			else
			{
				Trigger(-1.0, originatedLocally: true);
			}
		}

		public bool CanTrigger()
		{
			if (numAllowedTriggers > 0 && numTimesTriggered >= numAllowedTriggers)
			{
				return false;
			}
			if (onEnableTriggerDelay > 0.0 && (double)Time.time - enabledTime < onEnableTriggerDelay)
			{
				return false;
			}
			if (generalRetriggerDelay <= 0.0)
			{
				return true;
			}
			if (NetworkSystem.Instance.InRoom)
			{
				if (PhotonNetwork.Time - lastTriggerTime < -1.0)
				{
					lastTriggerTime = 0.0 - (4294967.295 - lastTriggerTime);
				}
				if (lastTriggerTime + generalRetriggerDelay <= PhotonNetwork.Time)
				{
					return true;
				}
			}
			else if (lastTriggerTime + generalRetriggerDelay <= (double)Time.time)
			{
				return true;
			}
			return false;
		}

		public virtual void Trigger(double triggerTime = -1.0, bool originatedLocally = false, bool ignoreTriggerCount = false)
		{
			if (!ignoreTriggerCount)
			{
				if (numAllowedTriggers > 0 && numTimesTriggered >= numAllowedTriggers)
				{
					return;
				}
				numTimesTriggered++;
			}
			if (NetworkSystem.Instance.InRoom)
			{
				if (triggerTime < 0.0)
				{
					triggerTime = PhotonNetwork.Time;
				}
			}
			else if (originatedLocally)
			{
				triggerTime = Time.time;
			}
			lastTriggerTime = triggerTime;
			if (numAllowedTriggers > 0 && numTimesTriggered >= numAllowedTriggers)
			{
				Collider[] components = base.gameObject.GetComponents<Collider>();
				for (int i = 0; i < components.Length; i++)
				{
					components[i].enabled = false;
				}
			}
		}

		public void ResetTrigger(bool onlyResetTriggerCount = false)
		{
			if (!onlyResetTriggerCount)
			{
				lastTriggerTime = -1.0;
			}
			numTimesTriggered = 0;
			Collider[] components = base.gameObject.GetComponents<Collider>();
			for (int i = 0; i < components.Length; i++)
			{
				components[i].enabled = true;
			}
			CMSSerializer.ResetTrigger(id);
		}

		public void SetTriggerCount(byte value)
		{
			numTimesTriggered = System.Math.Min(value, numAllowedTriggers);
			if (numTimesTriggered >= numAllowedTriggers)
			{
				Collider[] components = base.gameObject.GetComponents<Collider>();
				for (int i = 0; i < components.Length; i++)
				{
					components[i].enabled = false;
				}
			}
		}

		public void SetLastTriggerTime(double value)
		{
			lastTriggerTime = value;
		}
	}
	public class CMSTryOnArea : MonoBehaviour
	{
		private Scene originalScene;

		public BoxCollider tryOnAreaCollider;

		public void InitializeForCustomMap(CompositeTriggerEvents customMapTryOnArea, Scene customMapScene)
		{
			originalScene = customMapScene;
			if (!GTExt.IsNull(tryOnAreaCollider))
			{
				customMapTryOnArea.AddCollider(tryOnAreaCollider);
			}
		}

		public void RemoveFromCustomMap(CompositeTriggerEvents customMapTryOnArea)
		{
			if (!GTExt.IsNull(tryOnAreaCollider))
			{
				customMapTryOnArea.RemoveCollider(tryOnAreaCollider);
			}
		}

		public bool IsFromScene(Scene unloadingScene)
		{
			return unloadingScene == originalScene;
		}
	}
