		public static void LoadZoneTriggered(int[] scenesToLoad, int[] scenesToUnload)
		{
			CustomMapLoader.LoadZoneTriggered(scenesToLoad, scenesToUnload, OnSceneLoaded, OnSceneUnloaded);
		}

		private static void OnSceneLoaded(string sceneName)
		{
			CMSSerializer.ProcessSceneLoad(sceneName);
			ProcessZoneShaderSettings(sceneName);
		}

		private static void OnSceneUnloaded(string sceneName)
		{
			CMSSerializer.UnregisterTriggers(sceneName);
			for (int num = allCustomMapZoneShaderSettings.Count - 1; num >= 0; num--)
			{
				if (GTExt.IsNull(allCustomMapZoneShaderSettings[num]))
				{
					allCustomMapZoneShaderSettings.RemoveAt(num);
				}
			}
		}

		private static void OnSceneTriggerHistoryProcessed(string sceneName)
		{
			CapsuleCollider bodyCollider = GTPlayer.Instance.bodyCollider;
			SphereCollider headCollider = GTPlayer.Instance.headCollider;
			UnityEngine.Vector3 position = bodyCollider.transform.TransformPoint(bodyCollider.center);
			float radius = Mathf.Max(bodyCollider.height, bodyCollider.radius) * GTPlayer.Instance.scale;
			Collider[] array = new Collider[100];
			Physics.OverlapSphereNonAlloc(position, radius, array);
			foreach (Collider collider in array)
			{
				if (!(collider != null) || !collider.gameObject.scene.name.Equals(sceneName))
				{
					continue;
				}
				CMSTrigger[] components = collider.gameObject.GetComponents<CMSTrigger>();
				for (int j = 0; j < components.Length; j++)
				{
					if (components[j] != null)
					{
						components[j].OnTriggerEnter(bodyCollider);
						components[j].OnTriggerEnter(headCollider);
					}
				}
				CMSLoadingZone[] components2 = collider.gameObject.GetComponents<CMSLoadingZone>();
				for (int k = 0; k < components2.Length; k++)
				{
					if (components2[k] != null)
					{
						components2[k].OnTriggerEnter(bodyCollider);
					}
				}
				CMSZoneShaderSettingsTrigger[] components3 = collider.gameObject.GetComponents<CMSZoneShaderSettingsTrigger>();
				for (int l = 0; l < components3.Length; l++)
				{
					if (components3[l] != null)
					{
						components3[l].OnTriggerEnter(bodyCollider);
					}
				}
				HoverboardAreaTrigger[] components4 = collider.gameObject.GetComponents<HoverboardAreaTrigger>();
				for (int m = 0; m < components4.Length; m++)
				{
					if (components4[m] != null)
					{
						components4[m].OnTriggerEnter(headCollider);
					}
				}
				WaterVolume[] components5 = collider.gameObject.GetComponents<WaterVolume>();
				for (int n = 0; n < components5.Length; n++)
				{
					if (components5[n] != null)
					{
						components5[n].OnTriggerEnter(bodyCollider);
						components5[n].OnTriggerEnter(headCollider);
					}
				}
			}
		}

		public static void SetDefaultZoneShaderSettings(ZoneShaderSettings defaultCustomMapShaderSettings, CMSZoneShaderSettings.CMSZoneShaderProperties defaultZoneShaderProperties)
		{
			if (hasInstance)
			{
				instance.customMapDefaultZoneShaderSettings.CopySettings(defaultCustomMapShaderSettings, rerunAwake: true);
				loadedCustomMapDefaultZoneShaderSettings = defaultCustomMapShaderSettings;
				customMapDefaultZoneShaderProperties = defaultZoneShaderProperties;
				customMapDefaultZoneShaderSettingsInitialized = true;
			}
		}

		private static void ProcessZoneShaderSettings(string loadedSceneName)
		{
			if (hasInstance && customMapDefaultZoneShaderSettingsInitialized && customMapDefaultZoneShaderProperties.isInitialized)
			{
				for (int i = 0; i < allCustomMapZoneShaderSettings.Count; i++)
				{
					if (allCustomMapZoneShaderSettings[i].IsNotNull() && allCustomMapZoneShaderSettings[i] != loadedCustomMapDefaultZoneShaderSettings && allCustomMapZoneShaderSettings[i].gameObject.scene.name.Equals(loadedSceneName))
					{
						allCustomMapZoneShaderSettings[i].ReplaceDefaultValues(customMapDefaultZoneShaderProperties, rerunAwake: true);
					}
				}
			}
			else
			{
				if (!hasInstance || !instance.virtualStumpZoneShaderSettings.IsNotNull())
				{
					return;
				}
				for (int j = 0; j < allCustomMapZoneShaderSettings.Count; j++)
				{
					if (allCustomMapZoneShaderSettings[j].IsNotNull() && allCustomMapZoneShaderSettings[j].gameObject.scene.name.Equals(loadedSceneName))
					{
						allCustomMapZoneShaderSettings[j].ReplaceDefaultValues(instance.virtualStumpZoneShaderSettings, rerunAwake: true);
					}
				}
			}
		}

		public static void AddZoneShaderSettings(ZoneShaderSettings zoneShaderSettings)
		{
			allCustomMapZoneShaderSettings.AddIfNew(zoneShaderSettings);
		}

		public static void ActivateDefaultZoneShaderSettings()
		{
			if (hasInstance && customMapDefaultZoneShaderSettingsInitialized)
			{
				instance.customMapDefaultZoneShaderSettings.BecomeActiveInstance(force: true);
			}
			else if (hasInstance)
			{
				instance.virtualStumpZoneShaderSettings.BecomeActiveInstance(force: true);
			}
		}

		public static void ReturnToVirtualStump()
		{
			if (hasInstance && GorillaComputer.instance.IsPlayerInVirtualStump() && instance.returnToVirtualStumpTeleportLocation.IsNotNull())
			{
				GTPlayer gTPlayer = GTPlayer.Instance;
				if (gTPlayer != null)
				{
					CustomMapLoader.ResetToInitialZone(OnSceneLoaded, OnSceneUnloaded);
					gTPlayer.TeleportTo(instance.returnToVirtualStumpTeleportLocation, matchDestinationRotation: true, maintainVelocity: false);
				}
			}
		}

		public static bool WantsHoldingHandsDisabled()
		{
			if (GorillaComputer.instance.IsPlayerInVirtualStump())
			{
				if (!CustomMapLoader.IsMapLoaded())
				{
					return true;
				}
				if (CustomMapLoader.LoadedMapWantsHoldingHandsDisabled())
				{
					return true;
				}
			}
			return false;
		}
	}
	public class CustomMapModeSelector : GameModeSelectorButtonLayout
	{
		[SerializeField]
		private TMP_Text roomHostText;

		[SerializeField]
		private GameObject roomHostDescriptionText;

		[SerializeField]
		private string notInRoomHostString = "-NOT IN ROOM-";

		[SerializeField]
		private string roomHostLabel = "ROOM HOST: ";

		private static List<GameModeType> gamemodes = new List<GameModeType> { GameModeType.Casual };

		private static GameModeType defaultGamemodeForLoadedMap = GameModeType.Casual;

		private static List<CustomMapModeSelector> instances = new List<CustomMapModeSelector>();

		private static string reusableString = "";

		private void Awake()
		{
			instances.AddIfNew(this);
		}

		public void OnEnable()
		{
			if (GorillaComputer.instance != null)
			{
				SetupButtons();
				GorillaComputer.instance.SetGameModeWithoutButton(defaultGamemodeForLoadedMap.ToString());
			}
			RoomSystem.JoinedRoomEvent += new Action(OnJoinedRoom);
			NetworkSystem.Instance.OnMasterClientSwitchedEvent += new Action<NetPlayer>(OnRoomHostSwitched);
			NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(OnDisconnected);
			roomHostDescriptionText.SetActive(value: false);
			roomHostText.gameObject.SetActive(value: false);
			if (NetworkSystem.Instance.InRoom && NetworkSystem.Instance.SessionIsPrivate)
			{
				OnRoomHostSwitched(NetworkSystem.Instance.MasterClient);
			}
		}

		public void OnDisable()
		{
			RoomSystem.JoinedRoomEvent -= new Action(OnJoinedRoom);
			NetworkSystem.Instance.OnMasterClientSwitchedEvent -= new Action<NetPlayer>(OnRoomHostSwitched);
			NetworkSystem.Instance.OnReturnedToSinglePlayer -= new Action(OnDisconnected);
		}

		private void OnJoinedRoom()
		{
			OnRoomHostSwitched(NetworkSystem.Instance.MasterClient);
		}

		private void OnRoomHostSwitched(NetPlayer newRoomHost)
		{
			if (!NetworkSystem.Instance.InRoom || !NetworkSystem.Instance.SessionIsPrivate)
			{
				return;
			}
			reusableString = notInRoomHostString;
			if (!newRoomHost.IsNull)
			{
				roomHostDescriptionText.SetActive(value: true);
				reusableString = newRoomHost.DefaultName;
				if (GorillaComputer.instance.NametagsEnabled && KIDManager.HasPermissionToUseFeature(EKIDFeatures.Custom_Nametags))
				{
					RigContainer playerRig;
					if (newRoomHost.IsLocal)
					{
						reusableString = newRoomHost.NickName;
					}
					else if (VRRigCache.Instance.TryGetVrrig(newRoomHost, out playerRig))
					{
						reusableString = playerRig.Rig.playerNameVisible;
					}
				}
			}
			roomHostText.text = roomHostLabel + reusableString;
			roomHostText.gameObject.SetActive(value: true);
		}

		private void OnDisconnected()
		{
			roomHostText.gameObject.SetActive(value: false);
			roomHostDescriptionText.SetActive(value: false);
		}

		public static void ResetButtons()
		{
			gamemodes = new List<GameModeType> { GameModeType.Casual };
			defaultGamemodeForLoadedMap = GameModeType.Casual;
			foreach (CustomMapModeSelector instance in instances)
			{
				instance.SetupButtons();
			}
			GorillaComputer.instance.SetGameModeWithoutButton(defaultGamemodeForLoadedMap.ToString());
		}

		public static void SetAvailableGameModes(int[] availableModes, int defaultMode)
		{
			gamemodes.Clear();
			gamemodes.Add(GameModeType.Casual);
			if (availableModes != null)
			{
				foreach (int item in availableModes)
				{
					gamemodes.Add((GameModeType)item);
				}
			}
			defaultGamemodeForLoadedMap = (GameModeType)defaultMode;
			foreach (CustomMapModeSelector instance in instances)
			{
				instance.SetupButtons();
			}
			GorillaComputer.instance.SetGameModeWithoutButton(defaultGamemodeForLoadedMap.ToString());
		}

		protected override async void SetupButtons()
		{
			if (superToggleButton != null)
			{
				superToggleButton.transform.parent.gameObject.SetActive(value: false);
			}
			int count = 0;
			while (GorillaComputer.instance == null)
			{
				await Task.Delay(100);
			}
			bool flag = GorillaTagger.Instance.offlineVRRig.zoneEntity.currentZone != zone;
			foreach (GameModeType gamemode in gamemodes)
			{
				if (count == currentButtons.Count)
				{
					currentButtons.Add(UnityEngine.Object.Instantiate(pf_button, base.transform));
				}
				ModeSelectButton modeSelectButton = currentButtons[count];
				modeSelectButton.transform.localPosition = new UnityEngine.Vector3((float)count * -0.15f, 0f, 0f);
				modeSelectButton.transform.localRotation = UnityEngine.Quaternion.Euler(0f, 0f, -90f);
				modeSelectButton.WarningScreen = warningScreen;
				modeSelectButton.SetInfo(gamemode.ToString(), GorillaGameModes.GameMode.GameModeZoneMapping.GetModeName(gamemode), GorillaGameModes.GameMode.GameModeZoneMapping.IsNew(gamemode), GorillaGameModes.GameMode.GameModeZoneMapping.GetCountdown(gamemode));
				modeSelectButton.gameObject.SetActive(value: true);
				count++;
				flag |= GorillaComputer.instance.currentGameMode.Value.ToUpper() == gamemode.ToString().ToUpper();
			}
			for (int i = count; i < currentButtons.Count; i++)
			{
				currentButtons[i].gameObject.SetActive(value: false);
			}
		}

		public static void RefreshHostName()
		{
			foreach (CustomMapModeSelector instance in instances)
			{
				instance.OnRoomHostSwitched(NetworkSystem.Instance.MasterClient);
			}
		}
	}
	public class VirtualStumpModeSelectButton : ModeSelectButton
	{
		public override void ButtonActivationWithHand(bool isLeftHand)
		{
			if (warningScreen.ShouldShowWarning)
			{
				warningScreen.Show();
			}
			else
			{
				GorillaComputer.instance.SetGameModeWithoutButton(gameMode);
			}
			if (GorillaComputer.instance.IsPlayerInVirtualStump() && RoomSystem.JoinedRoom && NetworkSystem.Instance.LocalPlayer.IsMasterClient && NetworkSystem.Instance.SessionIsPrivate)
			{
				if (GTExt.IsNull(GorillaGameModes.GameMode.ActiveGameMode))
				{
					GorillaGameModes.GameMode.ChangeGameMode(gameMode);
				}
				else if (GorillaGameModes.GameMode.ActiveGameMode.GameType().ToString().ToLower() != gameMode.ToLower())
				{
					GorillaGameModes.GameMode.ChangeGameMode(gameMode);
				}
			}
		}
	}
	public class VirtualStumpReturnWatch : MonoBehaviour
	{
		[SerializeField]
		private HeldButton returnButton;

		[SerializeField]
		private TMP_Text buttonText;

		[SerializeField]
		private TMP_Text countdownText;

		private static VirtualStumpReturnWatchProps currentCustomMapProps;

		private float startPressingButtonTime = -1f;

		private bool currentlyBeingPressed;

		private Coroutine updateCountdownCoroutine;

		private void Start()
		{
			if (returnButton != null)
			{
				returnButton.onStartPressingButton.AddListener(OnStartedPressingButton);
				returnButton.onStopPressingButton.AddListener(OnStoppedPressingButton);
				returnButton.onPressButton.AddListener(OnButtonPressed);
			}
		}

		private void OnDestroy()
		{
			if (returnButton != null)
			{
				returnButton.onStartPressingButton.RemoveListener(OnStartedPressingButton);
				returnButton.onStopPressingButton.RemoveListener(OnStoppedPressingButton);
				returnButton.onPressButton.RemoveListener(OnButtonPressed);
			}
		}

		public static void SetWatchProperties(VirtualStumpReturnWatchProps props)
		{
			currentCustomMapProps = props;
			currentCustomMapProps.holdDuration = Mathf.Clamp(currentCustomMapProps.holdDuration, 0.5f, 5f);
			currentCustomMapProps.holdDuration_Infection = Mathf.Clamp(currentCustomMapProps.holdDuration_Infection, 0.5f, 5f);
			currentCustomMapProps.holdDuration_Custom = Mathf.Clamp(currentCustomMapProps.holdDuration_Custom, 0.5f, 5f);
		}

		private float GetCurrentHoldDuration()
		{
			if (GTExt.IsNull(GorillaGameManager.instance))
			{
				return currentCustomMapProps.holdDuration;
			}
			switch (GorillaGameManager.instance.GameType())
			{
			case GameModeType.Infection:
				if (currentCustomMapProps.infectionOverride)
				{
					return currentCustomMapProps.holdDuration_Infection;
				}
				return currentCustomMapProps.holdDuration;
			case GameModeType.Custom:
				if (currentCustomMapProps.customModeOverride)
				{
					return currentCustomMapProps.holdDuration_Custom;
				}
				return currentCustomMapProps.holdDuration;
			default:
				return currentCustomMapProps.holdDuration;
			}
		}

		private void OnStartedPressingButton()
		{
			startPressingButtonTime = Time.time;
			currentlyBeingPressed = true;
			returnButton.pressDuration = GetCurrentHoldDuration();
			ShowCountdownText();
			updateCountdownCoroutine = StartCoroutine(UpdateCountdownText());
		}

		private void OnStoppedPressingButton()
		{
			currentlyBeingPressed = false;
			HideCountdownText();
			if (updateCountdownCoroutine != null)
			{
				StopCoroutine(updateCountdownCoroutine);
				updateCountdownCoroutine = null;
			}
		}

		private void OnButtonPressed()
		{
			currentlyBeingPressed = false;
			if (!ZoneManagement.IsInZone(GTZone.customMaps) || CustomMapManager.IsLocalPlayerInVirtualStump())
			{
				return;
			}
			bool flag = currentCustomMapProps.shouldTagPlayer;
			bool flag2 = currentCustomMapProps.shouldKickPlayer;
			if (GorillaGameManager.instance.IsNotNull())
			{
				switch (GorillaGameManager.instance.GameType())
				{
				case GameModeType.Infection:
					if (currentCustomMapProps.infectionOverride)
					{
						flag = currentCustomMapProps.shouldTagPlayer_Infection;
						flag2 = currentCustomMapProps.shouldKickPlayer_Infection;
					}
					break;
				case GameModeType.Custom:
					if (currentCustomMapProps.customModeOverride)
					{
						flag = currentCustomMapProps.shouldTagPlayer_CustomMode;
						flag2 = currentCustomMapProps.shouldKickPlayer_CustomMode;
					}
					break;
				}
			}
			if (flag2 && NetworkSystem.Instance.InRoom && !NetworkSystem.Instance.SessionIsPrivate)
			{
				NetworkSystem.Instance.ReturnToSinglePlayer();
			}
			else if (flag)
			{
				GorillaGameModes.GameMode.ReportHit();
			}
			CustomMapManager.ReturnToVirtualStump();
		}

		private void ShowCountdownText()
		{
			if (!GTExt.IsNull(countdownText))
			{
				int num = 1 + Mathf.FloorToInt(GetCurrentHoldDuration());
				countdownText.text = num.ToString();
				countdownText.gameObject.SetActive(value: true);
				if (buttonText.IsNotNull())
				{
					buttonText.gameObject.SetActive(value: false);
				}
			}
		}

		private void HideCountdownText()
		{
			if (!GTExt.IsNull(countdownText))
			{
				countdownText.text = "";
				countdownText.gameObject.SetActive(value: false);
				if (buttonText.IsNotNull())
				{
					buttonText.gameObject.SetActive(value: true);
				}
			}
		}

		private IEnumerator UpdateCountdownText()
		{
			while (currentlyBeingPressed && !GTExt.IsNull(countdownText))
			{
				float f = GetCurrentHoldDuration() - (Time.time - startPressingButtonTime);
				int num = 1 + Mathf.FloorToInt(f);
				countdownText.text = num.ToString();
				yield return null;
			}
		}
	}
