namespace GorillaTagScripts.UI
{
	public class GorillaKeyWrapper<TBinding> : MonoBehaviour where TBinding : Enum
	{
		public UnityEvent<TBinding> OnKeyPressed = new UnityEvent<TBinding>();

		public bool defineButtonsManually;

		public List<GorillaKeyButton<TBinding>> buttons = new List<GorillaKeyButton<TBinding>>();

		public void Start()
		{
			if (!defineButtonsManually)
			{
				FindMatchingButtons(base.gameObject);
			}
			else
			{
				if (buttons.Count <= 0)
				{
					return;
				}
				for (int num = buttons.Count - 1; num >= 0; num--)
				{
					if (GTExt.IsNull(buttons[num]))
					{
						buttons.RemoveAt(num);
					}
					else
					{
						buttons[num].OnKeyButtonPressed.AddListener(OnKeyButtonPressed);
					}
				}
			}
		}

		public void OnDestroy()
		{
			for (int i = 0; i < buttons.Count; i++)
			{
				if (buttons[i].IsNotNull())
				{
					buttons[i].OnKeyButtonPressed.RemoveListener(OnKeyButtonPressed);
				}
			}
		}

		public void FindMatchingButtons(GameObject obj)
		{
			if (GTExt.IsNull(obj))
			{
				return;
			}
			for (int i = 0; i < obj.transform.childCount; i++)
			{
				Transform child = obj.transform.GetChild(i);
				if (child.IsNotNull())
				{
					FindMatchingButtons(child.gameObject);
				}
			}
			GorillaKeyButton<TBinding> component = obj.GetComponent<GorillaKeyButton<TBinding>>();
			if (component.IsNotNull() && !buttons.Contains(component))
			{
				buttons.Add(component);
				component.OnKeyButtonPressed.AddListener(OnKeyButtonPressed);
			}
		}

		private void OnKeyButtonPressed(TBinding binding)
		{
			OnKeyPressed?.Invoke(binding);
		}
	}
}
namespace GorillaTagScripts.UI.ModIO
{
	public class CustomMapsRoomMapDisplay : MonoBehaviour
	{
		[SerializeField]
		private TMP_Text roomMapLabelText;

		[SerializeField]
		private TMP_Text roomMapNameText;

		[SerializeField]
		private TMP_Text roomMapStatusLabelText;

		[SerializeField]
		private TMP_Text roomMapStatusText;

		[SerializeField]
		private string noRoomMapString = "NONE";

		[SerializeField]
		private string notLoadedStatusString = "NOT LOADED";

		[SerializeField]
		private string loadingStatusString = "LOADING...";

		[SerializeField]
		private string readyToPlayStatusString = "READY!";

		[SerializeField]
		private string loadFailedStatusString = "LOAD FAILED";

		[SerializeField]
		private Color notLoadedStatusStringColor = Color.red;

		[SerializeField]
		private Color loadingStatusStringColor = Color.yellow;

		[SerializeField]
		private Color readyToPlayStatusStringColor = Color.green;

		[SerializeField]
		private Color loadFailedStatusStringColor = Color.red;

		public void Start()
		{
			roomMapNameText.text = noRoomMapString;
			roomMapStatusText.text = notLoadedStatusString;
			roomMapLabelText.gameObject.SetActive(value: true);
			roomMapNameText.gameObject.SetActive(value: true);
			roomMapStatusLabelText.gameObject.SetActive(value: false);
			roomMapStatusText.gameObject.SetActive(value: false);
			NetworkSystem.Instance.OnMultiplayerStarted += new Action(OnJoinedRoom);
			NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(OnDisconnectedFromRoom);
			CustomMapManager.OnRoomMapChanged.AddListener(OnRoomMapChanged);
			CustomMapManager.OnMapLoadStatusChanged.AddListener(OnMapLoadProgress);
			CustomMapManager.OnMapLoadComplete.AddListener(OnMapLoadComplete);
		}

		public void OnDestroy()
		{
			NetworkSystem.Instance.OnMultiplayerStarted -= new Action(OnJoinedRoom);
			NetworkSystem.Instance.OnReturnedToSinglePlayer -= new Action(OnDisconnectedFromRoom);
			CustomMapManager.OnRoomMapChanged.RemoveListener(OnRoomMapChanged);
		}

		private void OnJoinedRoom()
		{
			UpdateRoomMap();
		}

		private void OnDisconnectedFromRoom()
		{
			UpdateRoomMap();
		}

		private void OnRoomMapChanged(ModId roomMapModId)
		{
			UpdateRoomMap();
		}

		private async Task UpdateRoomMap()
		{
			ModId currentRoomMap = CustomMapManager.GetRoomMapId();
			if (currentRoomMap == ModId.Null)
			{
				roomMapNameText.text = noRoomMapString;
				roomMapStatusLabelText.gameObject.SetActive(value: false);
				roomMapStatusText.gameObject.SetActive(value: false);
				return;
			}
			var (error, mod) = await ModIOManager.GetMod(currentRoomMap);
			if ((bool)error)
			{
				roomMapNameText.text = $"FAILED TO GET MOD INFO.\n({error.Code})";
				return;
			}
			roomMapNameText.text = mod.Name;
			roomMapStatusLabelText.gameObject.SetActive(value: true);
			if (CustomMapLoader.IsMapLoaded(currentRoomMap))
			{
				roomMapStatusText.text = readyToPlayStatusString;
				roomMapStatusText.color = readyToPlayStatusStringColor;
			}
			else if (CustomMapManager.IsLoading(currentRoomMap._id))
			{
				roomMapStatusText.text = loadingStatusString;
				roomMapStatusText.color = loadingStatusStringColor;
			}
			else
			{
				roomMapStatusText.text = notLoadedStatusString;
				roomMapStatusText.color = notLoadedStatusStringColor;
			}
			roomMapStatusText.gameObject.SetActive(value: true);
		}

		private void OnMapLoadComplete(bool success)
		{
			if (success)
			{
				roomMapStatusText.text = readyToPlayStatusString;
				roomMapStatusText.color = readyToPlayStatusStringColor;
			}
			else
			{
				roomMapStatusText.text = loadFailedStatusString;
				roomMapStatusText.color = loadFailedStatusStringColor;
			}
		}

		private void OnMapLoadProgress(MapLoadStatus status, int progress, string message)
		{
			if ((uint)(status - 1) <= 1u)
			{
				roomMapStatusText.text = loadingStatusString;
				roomMapStatusText.color = loadingStatusStringColor;
			}
		}
	}
	public class VirtualStumpTeleportingHUD : MonoBehaviour
	{
		private const string VIRT_STUMP_HUD_ENTERING_KEY = "VIRT_STUMP_HUD_ENTERING";

		private const string VIRT_STUMP_HUD_LEAVING_KEY = "VIRT_STUMP_HUD_LEAVING";

		[SerializeField]
		private string enteringVirtualStumpString = "Now Entering the Virtual Stump";

		[SerializeField]
		private string leavingVirtualStumpString = "Now Leaving the Virtual Stump";

		[SerializeField]
		private TMP_Text teleportingStatusText;

		[SerializeField]
		private int maxNumProgressDots = 3;

		[SerializeField]
		private float textUpdateInterval = 0.5f;

		private float lastTextUpdateTime;

		private int numProgressDots;

		private bool isEnteringVirtualStump;

		public void Initialize(bool isEntering)
		{
			isEnteringVirtualStump = isEntering;
			if (isEntering)
			{
				if (!LocalisationManager.TryGetKeyForCurrentLocale("VIRT_STUMP_HUD_ENTERING", out var result, enteringVirtualStumpString))
				{
					UnityEngine.Debug.LogError("[LOCALIZATION::VIRT_STUMP_TELEPORT_HUD] Failed to retrieve key [VIRT_STUMP_HUD_ENTERING] for locale [" + LocalisationManager.CurrentLanguage.LocaleName + "]");
				}
				teleportingStatusText.text = result;
				teleportingStatusText.gameObject.SetActive(value: true);
			}
			else
			{
				if (!LocalisationManager.TryGetKeyForCurrentLocale("VIRT_STUMP_HUD_LEAVING", out var result2, leavingVirtualStumpString))
				{
					UnityEngine.Debug.LogError("[LOCALIZATION::VIRT_STUMP_TELEPORT_HUD] Failed to retrieve key [VIRT_STUMP_HUD_LEAVING] for locale [" + LocalisationManager.CurrentLanguage.LocaleName + "]");
				}
				teleportingStatusText.text = result2;
				teleportingStatusText.gameObject.SetActive(value: true);
			}
		}

		private void Update()
		{
			if (Time.time - lastTextUpdateTime > textUpdateInterval)
			{
				lastTextUpdateTime = Time.time;
				IncrementProgressDots();
				teleportingStatusText.text = (isEnteringVirtualStump ? enteringVirtualStumpString : leavingVirtualStumpString);
				for (int i = 0; i < numProgressDots; i++)
				{
					teleportingStatusText.text += ".";
				}
			}
		}

		private void IncrementProgressDots()
		{
			numProgressDots++;
			if (numProgressDots > maxNumProgressDots)
			{
				numProgressDots = 0;
			}
		}
	}
}
namespace GorillaTagScripts.Subscription
{
	public class FeatureTogglesScreen : MonoBehaviour, IGorillaSliceableSimple
	{
		[Serializable]
		public class Feature
		{
			public string DisplayName = string.Empty;

			public SubscriptionManager.SubscriptionFeatures Value;

			public UnityEvent OnPressed;

			public UnityEvent<bool> OnToggle;

			public string UnavailableMessage = "NOT AVAILABLE ON THIS DEVICE";
		}

		private const int TogglesPerPage = 3;

		[SerializeField]
		private Feature[] _features;

		[SerializeField]
		private SITouchscreenButtonContainer _nextButton;

		[SerializeField]
		private SITouchscreenButtonContainer _backButton;

		[SerializeField]
		private SITouchscreenButtonContainer _exitButton;

		[SerializeField]
		private FeatureToggleUI[] _featureToggleUi;

		private int _currentPage;

		private bool _dirty = true;

		private int NumPages
		{
			get
			{
				if (_features.Length % 3 != 0)
				{
					return _features.Length / 3 + 1;
				}
				return _features.Length / 3;
			}
		}

		private int LastPageIndex => System.Math.Max(0, NumPages - 1);

		private void Awake()
		{
			_nextButton.button.buttonPressed.AddListener(OnNextButtonPressed);
			_backButton.button.buttonPressed.AddListener(OnBackButtonPressed);
			_exitButton.button.buttonPressed.AddListener(OnExitButtonPressed);
			MarkDirty();
		}

		private void OnNextButtonPressed(SITouchscreenButton.SITouchscreenButtonType type, int data, int actorNr)
		{
			_currentPage++;
			if (_currentPage > LastPageIndex)
			{
				_currentPage = LastPageIndex;
			}
			MarkDirty();
		}

		private void OnBackButtonPressed(SITouchscreenButton.SITouchscreenButtonType type, int data, int actorNr)
		{
			_currentPage--;
			if (_currentPage < 0)
			{
				_currentPage = 0;
			}
			MarkDirty();
		}

		private void OnExitButtonPressed(SITouchscreenButton.SITouchscreenButtonType type, int data, int actorNr)
		{
		}

		public void SliceUpdate()
		{
			if (_dirty)
			{
				_backButton.gameObject.SetActive(_currentPage != 0);
				_nextButton.gameObject.SetActive(_currentPage != LastPageIndex);
				UpdateFeatureToggleUI();
				_dirty = false;
			}
		}

		private void OnEnable()
		{
			GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
			MarkDirty();
		}

		private void OnDisable()
		{
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
		}

		private void UpdateFeatureToggleUI()
		{
			for (int i = 0; i < _featureToggleUi.Length; i++)
			{
				FeatureToggleUI featureToggleUI = _featureToggleUi[i];
				int num = _currentPage * 3 + i;
				bool flag = num < _features.Length;
				featureToggleUI.gameObject.SetActive(flag);
				if (flag)
				{
					Feature feature = _features[num];
					featureToggleUI.AttachToFeature(feature);
				}
			}
		}

		public void MarkDirty()
		{
			_dirty = true;
		}
	}
	[RequireComponent(typeof(SITouchscreenButtonContainer))]
	public class FeatureToggleUI : MonoBehaviour
	{
		[SerializeField]
		private TextMeshPro _label;

		[SerializeField]
		private TextMeshPro _unavailable;

		private const float DEBOUNCE_TIME = 0.5f;

		private float _disableUntil = float.MinValue;

		public SITouchscreenButtonContainer ButtonContainer { get; private set; }

		public string LabelText
		{
			get
			{
				return _label.text;
			}
			set
			{
				_label.text = value;
			}
		}

		private void Awake()
		{
			ButtonContainer = base.gameObject.GetComponent<SITouchscreenButtonContainer>();
		}

		public void AttachToFeature(FeatureTogglesScreen.Feature feature)
		{
			ButtonContainer.button.buttonPressed.RemoveAllListeners();
			ButtonContainer.button.buttonToggled.RemoveAllListeners();
			LabelText = feature.DisplayName;
			bool state = SubscriptionManager.GetSubscriptionSettingBool(feature.Value);
			bool num = SubscriptionManager.IsSubscriptionFeatureAvailable(feature.Value);
			bool flag = true;
			if (num && flag)
			{
				ButtonContainer.button.buttonPressed.AddListener(delegate(SITouchscreenButton.SITouchscreenButtonType type, int data, int nr)
				{
					OnPressed(nr, feature);
				});
				ButtonContainer.button.buttonToggled.AddListener(delegate(SITouchscreenButton.SITouchscreenButtonType type, int data, int nr, bool state2)
				{
					OnToggled(nr, feature, state2);
				});
				_unavailable.gameObject.SetActive(value: false);
			}
			else
			{
				state = false;
				_unavailable.gameObject.SetActive(value: true);
				if (!flag)
				{
					_unavailable.text = "ENABLE PERMISSION IN QUEST SETTINGS";
				}
				else
				{
					_unavailable.text = "NOT AVAILABLE ON THIS DEVICE";
				}
			}
			ButtonContainer.button.SetToggleState(state);
			ButtonContainer.UpdateToggleVisual();
		}

		private void OnPressed(int actorNr, FeatureTogglesScreen.Feature feature)
		{
			if (!(Time.time < _disableUntil) && actorNr == NetworkSystem.Instance.LocalPlayer.ActorNumber)
			{
				_disableUntil = Time.time + 0.5f;
				feature.OnPressed.Invoke();
			}
		}

		private void OnToggled(int actorNr, FeatureTogglesScreen.Feature feature, bool state)
		{
			if (!(Time.time < _disableUntil) && actorNr == NetworkSystem.Instance.LocalPlayer.ActorNumber)
			{
				_disableUntil = Time.time + 0.5f;
				feature.OnToggle.Invoke(state);
				ButtonContainer.button.SetToggleState(state);
				ButtonContainer.UpdateToggleVisual();
			}
		}
	}
	public class HandScanner : ObservableBehavior, IClickable
	{
		[SerializeField]
		private float scanTime = 1f;

		public UnityEvent<NetPlayer> onHandScanStart;

		public UnityEvent<NetPlayer> onHandScanAbort;

		public UnityEvent<NetPlayer> onHandScanSuccess;

		public UnityEvent onHandScanInRange;

		public UnityEvent onHandScanOutOfRange;

		private VRRig scanningRig;

		private float scanStart;

		protected override void ObservableSliceUpdate()
		{
			if (!(scanningRig == null) && Time.time - scanStart > scanTime)
			{
				onHandScanSuccess?.Invoke(scanningRig.creator);
				scanningRig = null;
			}
		}

		protected override void OnBecameObservable()
		{
			onHandScanInRange?.Invoke();
		}

		protected override void OnLostObservable()
		{
			onHandScanOutOfRange?.Invoke();
		}

		private void OnTriggerEnter(Collider other)
		{
			SIScannableHand component = other.GetComponent<SIScannableHand>();
			if (!(component == null))
			{
				VRRig componentInParent = component.GetComponentInParent<VRRig>();
				if (componentInParent != null && componentInParent.isLocal)
				{
					scanningRig = componentInParent;
					scanStart = Time.time;
					onHandScanStart?.Invoke(scanningRig.creator);
				}
			}
		}

		private void OnTriggerExit(Collider other)
		{
			SIScannableHand component = other.GetComponent<SIScannableHand>();
			if (!(component == null))
			{
				VRRig componentInParent = component.GetComponentInParent<VRRig>();
				if (componentInParent != null && componentInParent == scanningRig && componentInParent.isLocal)
				{
					onHandScanAbort?.Invoke(scanningRig.creator);
					scanningRig = null;
				}
			}
		}

		public void Click(bool leftHand = false)
		{
			onHandScanStart?.Invoke(VRRig.LocalRig.creator);
			onHandScanSuccess?.Invoke(VRRig.LocalRig.creator);
		}
	}
	public class SubscriberExclusiveZone : MonoBehaviour, IGorillaSliceableSimple
	{
		[Header("Zones")]
		[Tooltip("Inner restricted zone - hard pushback")]
		[SerializeField]
		private GameObject restrictedZone;

		[Tooltip("Outer influence zone - gentle drift")]
		[SerializeField]
		private GameObject warningZone;

		[Header("Safe Exit Point")]
		[SerializeField]
		private Transform ejectionPoint;

		[Header("Tuning")]
		[SerializeField]
		private float driftSpeed = 3f;

		[SerializeField]
		private float shoveCooldown = 0.5f;

		[Header("Safety")]
		[SerializeField]
		private float safetyCheckRadius = 0.5f;

		[SerializeField]
		private LayerMask obstacleLayers;

		[Header("Door Visuals")]
		[SerializeField]
		private GameObject nonSubscribeDoorObject;

		[SerializeField]
		private GameObject subscriberDoorObject;

		public UnityEvent OnWarning;

		public UnityEvent OnEnterRestrictedZone;

		[Header("Debug")]
		[SerializeField]
		private bool showDebugInfo;

		private bool insideRestricted;

		private bool insideInfluence;

		private float lastShoveTime;

		private GameObject tempEjectionObject;

		private Collider restrictedZoneCollider;

		private Collider influenceZoneCollider;

		private bool bodyColliderWasDisabled;

		private List<VRRig> rigs = new List<VRRig>();

		private void Awake()
		{
			if (restrictedZone != null)
			{
				restrictedZoneCollider = restrictedZone.GetComponent<Collider>();
				if (restrictedZoneCollider != null && !restrictedZoneCollider.isTrigger)
				{
					UnityEngine.Debug.LogError("restrictedZone must be a trigger collider!", this);
					base.enabled = false;
					return;
				}
				SubscriberZoneTrigger subscriberZoneTrigger = restrictedZone.GetComponent<SubscriberZoneTrigger>();
				if (subscriberZoneTrigger == null)
				{
					subscriberZoneTrigger = restrictedZone.AddComponent<SubscriberZoneTrigger>();
				}
				subscriberZoneTrigger.parentZone = this;
				subscriberZoneTrigger.isRestrictedZone = true;
			}
			if (warningZone != null)
			{
				influenceZoneCollider = warningZone.GetComponent<Collider>();
				if (influenceZoneCollider != null && !influenceZoneCollider.isTrigger)
				{
					UnityEngine.Debug.LogError("influenceZone must be a trigger collider!", this);
					base.enabled = false;
					return;
				}
				SubscriberZoneTrigger subscriberZoneTrigger2 = warningZone.GetComponent<SubscriberZoneTrigger>();
				if (subscriberZoneTrigger2 == null)
				{
					subscriberZoneTrigger2 = warningZone.AddComponent<SubscriberZoneTrigger>();
				}
				subscriberZoneTrigger2.parentZone = this;
				subscriberZoneTrigger2.isRestrictedZone = false;
			}
			if (ejectionPoint == null)
			{
				UnityEngine.Debug.LogError("Assign an ejectionPoint!", this);
				base.enabled = false;
			}
			else
			{
				UpdateDoor();
			}
		}

		private void OnEnable()
		{
			if (!ApplicationQuittingState.IsQuitting)
			{
				GorillaSlicerSimpleManager.RegisterSliceable(this);
			}
		}

		private void OnDisable()
		{
			if (!ApplicationQuittingState.IsQuitting)
			{
				GorillaSlicerSimpleManager.UnregisterSliceable(this);
				ClearAllRigOverrides();
			}
		}

		private void Update()
		{
			if (!ApplicationQuittingState.IsQuitting)
			{
				UpdateDoor();
				if (!SubscriptionManager.IsLocalSubscribed())
				{
					HandleZoneBehavior();
				}
				else if (bodyColliderWasDisabled)
				{
					SetBodyCollider(GTPlayer.Instance, enabled: true);
					bodyColliderWasDisabled = false;
				}
			}
		}

		public void OnZoneEnter(bool isRestricted)
		{
			if (isRestricted)
			{
				insideRestricted = true;
				if (showDebugInfo)
				{
					UnityEngine.Debug.Log("[Zone] Entered restricted zone");
				}
			}
			else
			{
				insideInfluence = true;
				if (showDebugInfo)
				{
					UnityEngine.Debug.Log("[Zone] Entered warning zone");
				}
			}
		}

		public void OnZoneExit(bool isRestricted)
		{
			if (isRestricted)
			{
				insideRestricted = false;
				if (showDebugInfo)
				{
					UnityEngine.Debug.Log("[Zone] Exited restricted zone");
				}
			}
			else
			{
				insideInfluence = false;
				if (showDebugInfo)
				{
					UnityEngine.Debug.Log("[Zone] Exited warning zone");
				}
			}
		}

		private void HandleZoneBehavior()
		{
			GTPlayer instance = GTPlayer.Instance;
			if (instance == null)
			{
				return;
			}
			if (insideRestricted)
			{
				if (Time.time - lastShoveTime >= shoveCooldown)
				{
					lastShoveTime = Time.time;
					instance.TeleportTo(ejectionPoint.position, instance.transform.rotation, keepVelocity: true);
					OnEnterRestrictedZone?.Invoke();
				}
			}
			else if (insideInfluence)
			{
				DisplaceToward(instance, ejectionPoint, driftSpeed);
				OnWarning?.Invoke();
			}
		}

		private UnityEngine.Vector3 FindSafeEjectionPosition(UnityEngine.Vector3 playerPos)
		{
			if (restrictedZoneCollider == null)
			{
				return ejectionPoint.position;
			}
			Bounds bounds = restrictedZoneCollider.bounds;
			UnityEngine.Vector3 vector = bounds.ClosestPoint(playerPos);
			UnityEngine.Vector3 normalized = (vector - bounds.center).normalized;
			UnityEngine.Vector3 vector2 = vector + normalized * (safetyCheckRadius + 0.5f);
			float maxDistance = UnityEngine.Vector3.Distance(playerPos, vector2);
			if (Physics.SphereCast(playerPos + UnityEngine.Vector3.up * safetyCheckRadius, safetyCheckRadius, normalized, out var hitInfo, maxDistance, obstacleLayers))
			{
				vector2 = playerPos + normalized * Mathf.Max(0.1f, hitInfo.distance - safetyCheckRadius - 0.2f);
			}
			return vector2;
		}

		private void DisplaceToward(GTPlayer player, Transform target, float speed)
		{
			UnityEngine.Vector3 normalized = (target.position - player.transform.position).normalized;
			player.transform.position += normalized * speed * Time.deltaTime;
		}

		private void SetBodyCollider(GTPlayer player, bool enabled)
		{
			if (player != null && player.bodyCollider != null)
			{
				player.bodyCollider.enabled = enabled;
				bodyColliderWasDisabled = !enabled;
				if (showDebugInfo && player.bodyCollider.enabled != enabled)
				{
					UnityEngine.Debug.Log($"[Zone] Body collider: {enabled}");
				}
			}
		}

		private void UpdateDoor()
		{
			bool flag = SubscriptionManager.IsLocalSubscribed();
			if (nonSubscribeDoorObject.activeSelf == flag)
			{
				nonSubscribeDoorObject.SetActive(!flag);
			}
			if (subscriberDoorObject.activeSelf != flag)
			{
				subscriberDoorObject.SetActive(SubscriptionManager.IsLocalSubscribed());
			}
		}

		public void SliceUpdate()
		{
			VRRigCache.Instance.GetActiveRigs(rigs);
			if (restrictedZoneCollider == null)
			{
				return;
			}
			for (int i = 0; i < rigs.Count; i++)
			{
				if (!rigs[i].isOfflineVRRig && !SubscriptionManager.GetSubscriptionDetails(rigs[i]).active)
				{
					UnityEngine.Vector3 vector = restrictedZoneCollider.transform.InverseTransformPoint(rigs[i].syncPos);
					UnityEngine.Vector3 vector2 = ((BoxCollider)restrictedZoneCollider).size / 2f;
					UnityEngine.Vector3 center = ((BoxCollider)restrictedZoneCollider).center;
					if (vector.x < vector2.x + center.x && vector.x > 0f - vector2.x + center.x && vector.y < vector2.y + center.y && vector.y > 0f - vector2.y + center.y && vector.z < vector2.z + center.z && vector.z > 0f - vector2.z + center.z)
					{
						rigs[i].InOverrideSubscriptionZone = true;
						rigs[i].OverrideSubscriptionZoneLocation = ejectionPoint.position;
					}
					else
					{
						rigs[i].InOverrideSubscriptionZone = false;
						rigs[i].OverrideSubscriptionZoneLocation = UnityEngine.Vector3.zero;
					}
				}
			}
		}

		public void ClearAllRigOverrides()
		{
			VRRigCache.Instance.GetActiveRigs(rigs);
			for (int i = 0; i < rigs.Count; i++)
			{
				rigs[i].InOverrideSubscriptionZone = false;
				rigs[i].OverrideSubscriptionZoneLocation = UnityEngine.Vector3.zero;
			}
		}

		private void OnDestroy()
		{
			if (tempEjectionObject != null)
			{
				UnityEngine.Object.Destroy(tempEjectionObject);
			}
		}

		private void OnDrawGizmos()
		{
			if (restrictedZoneCollider != null)
			{
				Gizmos.color = new Color(1f, 0f, 0f, 0.3f);
				Gizmos.DrawCube(restrictedZoneCollider.bounds.center, restrictedZoneCollider.bounds.size);
			}
			if (influenceZoneCollider != null)
			{
				Gizmos.color = new Color(1f, 1f, 0f, 0.2f);
				Gizmos.DrawCube(influenceZoneCollider.bounds.center, influenceZoneCollider.bounds.size);
			}
			if (ejectionPoint != null)
			{
				Gizmos.color = Color.green;
				Gizmos.DrawWireSphere(ejectionPoint.position, 0.5f);
			}
		}
	}
	public class SubscriberZoneTrigger : MonoBehaviour
	{
