			SetTentacleColliders(enabled: true);
			moonBoss = GetComponentInParent<GREnemyBossMoon>();
			if (moonBoss != null && !moonBoss.squishVolumes.Contains(this))
			{
				moonBoss.squishVolumes.Add(this);
			}
		}

		public void SliceUpdate()
		{
			SetCollider(!overrideDisabled && base.transform.position.y < squishHeight && UnityEngine.Vector3.Angle(-base.transform.forward, UnityEngine.Quaternion.Euler(rotationOffset) * UnityEngine.Vector3.down) < facingDownDegrees);
		}

		public void SetCollider(bool colliderEnabled)
		{
			_collider.enabled = colliderEnabled;
		}

		private void OnTriggerEnter(Collider other)
		{
			if (other.gameObject.TryGetComponentInParent<GRPlayer>(out var component) && !(GRPlayer.GetLocal() != component) && _reenableCoroutine == null)
			{
				SetTentacleColliders(enabled: false);
				GTPlayer.Instance.DoLaunch(GetLaunchVector());
				moonBoss.HitPlayer(GRPlayer.GetLocal());
				_reenableCoroutine = StartCoroutine(ReenableCoroutine());
				moonBoss.SetSquishVolumeState(squishEnabled: false);
			}
		}

		private void SetTentacleColliders(bool enabled)
		{
			Collider[] collidersToDisable = _collidersToDisable;
			for (int i = 0; i < collidersToDisable.Length; i++)
			{
				collidersToDisable[i].enabled = enabled;
			}
		}

		private IEnumerator ReenableCoroutine()
		{
			yield return new WaitForSeconds(_reenableDelay);
			SetTentacleColliders(enabled: true);
			_reenableCoroutine = null;
			moonBoss.SetSquishVolumeState(squishEnabled: true);
		}

		private UnityEngine.Vector3 GetLaunchVector()
		{
			UnityEngine.Vector3 position = GRPlayer.GetLocal().transform.position;
			UnityEngine.Vector3 lhs = position - base.transform.position;
			UnityEngine.Vector3 vector = base.transform.position + base.transform.right * UnityEngine.Vector3.Dot(lhs, base.transform.right);
			UnityEngine.Vector3 normalized = (position - vector).normalized;
			UnityEngine.Vector3 vector2 = UnityEngine.Vector3.RotateTowards(new UnityEngine.Vector3(normalized.x, 0f, normalized.y).normalized, maxRadiansDelta: UnityEngine.Random.Range(_launchDeflectionDegrees / 2f, _launchDeflectionDegrees) * (MathF.PI / 180f), target: UnityEngine.Vector3.up, maxMagnitudeDelta: 0f);
			return _launchStrength * vector2.normalized;
		}
	}
}
namespace GorillaTagScripts.GhostReactor.SoakTasks
{
	public interface IGhostReactorSoakTask
	{
		bool Complete { get; }

		bool Update();

		void Reset();
	}
	public sealed class SoakTaskBreakable : IGhostReactorSoakTask
	{
		public const float TIME_BETWEEN_HITS = 0.1f;

		private readonly GRPlayer _grPlayer;

		private GameEntity _breakable;

		private float? _nextHitTime;

		public bool Complete { get; private set; }

		public SoakTaskBreakable(GRPlayer grPlayer)
		{
			_grPlayer = grPlayer;
		}

		public bool Update()
		{
			GameEntityManager managerForZone = GameEntityManager.GetManagerForZone(_grPlayer.gamePlayer.rig.zoneEntity.currentZone);
			if (managerForZone == null)
			{
				return false;
			}
			if (_breakable != null && _breakable.GetComponent<GRBreakable>().BrokenLocal)
			{
				UnityEngine.Debug.Log($"soak breakable {_breakable.id.index} is broken");
				_breakable = null;
				_nextHitTime = null;
				Complete = true;
			}
			else if (_breakable == null)
			{
				foreach (GameEntity item in managerForZone.GetGameEntities().ShuffleIntoCollection<List<GameEntity>, GameEntity>())
				{
					if (!(item == null) && !item.IsHeld())
					{
						GRBreakable component = item.gameObject.GetComponent<GRBreakable>();
						if ((object)component != null && !component.BrokenLocal)
						{
							_breakable = item;
							_nextHitTime = Time.time + 0.1f;
							break;
						}
					}
				}
			}
			else if (_breakable != null)
			{
				float? nextHitTime = _nextHitTime;
				if (nextHitTime.HasValue)
				{
					float valueOrDefault = nextHitTime.GetValueOrDefault();
					if (Time.time >= valueOrDefault)
					{
						UnityEngine.Debug.Log($"soak hit breakable {_breakable.id.index}");
						GameHitData hit = new GameHitData
						{
							hitEntityId = _breakable.id,
							hitByEntityId = _breakable.id,
							hitTypeId = 0,
							hitEntityPosition = UnityEngine.Vector3.zero,
							hitPosition = UnityEngine.Vector3.zero,
							hitImpulse = UnityEngine.Vector3.zero,
							hitAmount = 1
						};
						managerForZone.RequestHit(hit);
					}
				}
			}
			return true;
		}

		public void Reset()
		{
			_breakable = null;
			_nextHitTime = null;
			Complete = false;
		}
	}
	public sealed class SoakTaskDepositCollectibles : IGhostReactorSoakTask
	{
		public const float TIME_TO_HOLD_COLLECTIBLE = 0.1f;

		private readonly GRPlayer _grPlayer;

		private GRCurrencyDepositor _coreDepositor;

		private UnityEngine.Vector3? _seedExtractorTriggerLocation;

		private GameEntity _heldEntity;

		private float? _depositCollectibleTime;

		public bool Complete { get; private set; }

		public SoakTaskDepositCollectibles(GRPlayer grPlayer)
		{
			_grPlayer = grPlayer;
		}

		public bool Update()
		{
			if (_coreDepositor == null)
			{
				global::GhostReactor instance = global::GhostReactor.instance;
				if ((object)instance != null)
				{
					_coreDepositor = instance.currencyDepositor;
				}
				if (_coreDepositor == null)
				{
					return false;
				}
			}
			if (!_seedExtractorTriggerLocation.HasValue)
			{
				global::GhostReactor instance2 = global::GhostReactor.instance;
				if ((object)instance2 != null)
				{
					_seedExtractorTriggerLocation = instance2.seedExtractor.transform.Find("DepositorTrigger").position;
				}
				if (!_seedExtractorTriggerLocation.HasValue)
				{
					return false;
				}
			}
			GameEntityManager managerForZone = GameEntityManager.GetManagerForZone(_grPlayer.gamePlayer.rig.zoneEntity.currentZone);
			if (managerForZone == null)
			{
				return false;
			}
			if (_heldEntity == null || !_depositCollectibleTime.HasValue)
			{
				List<GameEntity> list = managerForZone.GetGameEntities().ShuffleIntoCollection<List<GameEntity>, GameEntity>();
				GameEntity gameEntity = null;
				foreach (GameEntity item in list)
				{
					if (!(item == null) && !item.IsHeld())
					{
						GRCollectible component = item.gameObject.GetComponent<GRCollectible>();
						if ((object)component != null && (component.type == ProgressionManager.CoreType.Core || component.type == ProgressionManager.CoreType.SuperCore || component.type == ProgressionManager.CoreType.ChaosSeed))
						{
							gameEntity = item;
							break;
						}
					}
				}
				if (gameEntity != null)
				{
					UnityEngine.Debug.Log($"Soak grabbing core {gameEntity.id.index}");
					managerForZone.RequestGrabEntity(gameEntity.id, isLeftHand: true, UnityEngine.Vector3.zero, UnityEngine.Quaternion.identity);
					_heldEntity = gameEntity;
					_depositCollectibleTime = Time.time + 0.1f;
				}
			}
			else if (_heldEntity != null)
			{
				float? depositCollectibleTime = _depositCollectibleTime;
				if (depositCollectibleTime.HasValue)
				{
					float valueOrDefault = depositCollectibleTime.GetValueOrDefault();
					if (Time.time >= valueOrDefault)
					{
						GRCollectible component2 = _heldEntity.GetComponent<GRCollectible>();
						if ((object)component2 == null)
						{
							return false;
						}
						switch (component2.type)
						{
						case ProgressionManager.CoreType.Core:
						case ProgressionManager.CoreType.SuperCore:
							UnityEngine.Debug.Log($"Soak depositing core {_heldEntity.id.index}");
							_heldEntity.gameObject.transform.position = _coreDepositor.gameObject.transform.position;
							break;
						case ProgressionManager.CoreType.ChaosSeed:
							UnityEngine.Debug.Log($"Soak depositing chaos seed {_heldEntity.id.index}");
							_heldEntity.gameObject.transform.position = _seedExtractorTriggerLocation.Value;
							break;
						}
						_heldEntity = null;
						_depositCollectibleTime = null;
						Complete = true;
					}
				}
			}
			return true;
		}

		public void Reset()
		{
			_heldEntity = null;
			_depositCollectibleTime = null;
			Complete = false;
		}
	}
	public sealed class SoakTaskGrabThrow : IGhostReactorSoakTask
	{
		public const float TIME_TO_HOLD_ENTITY = 0.1f;

		private readonly GRPlayer _grPlayer;

		private GameEntityId? _heldEntityId;

		private float? _dropEntityTime;

		public bool Complete { get; private set; }

		public SoakTaskGrabThrow(GRPlayer grPlayer)
		{
			_grPlayer = grPlayer;
		}

		public bool Update()
		{
			GameEntityManager managerForZone = GameEntityManager.GetManagerForZone(_grPlayer.gamePlayer.rig.zoneEntity.currentZone);
			if (managerForZone == null)
			{
				return false;
			}
			if (!_dropEntityTime.HasValue || !_heldEntityId.HasValue)
			{
				List<GameEntity> list = managerForZone.GetGameEntities().ShuffleIntoCollection<List<GameEntity>, GameEntity>();
				GameEntity gameEntity = null;
				foreach (GameEntity item in list)
				{
					if (!(item == null) && !item.IsHeld() && item.pickupable && !(item.gameObject.GetComponent<GameAgent>() != null))
					{
						gameEntity = item;
						break;
					}
				}
				if (gameEntity != null)
				{
					UnityEngine.Debug.Log($"Soak grabbing entity {gameEntity.id.index}");
					managerForZone.RequestGrabEntity(gameEntity.id, isLeftHand: true, UnityEngine.Vector3.zero, UnityEngine.Quaternion.identity);
					_heldEntityId = gameEntity.id;
					_dropEntityTime = Time.time + 0.1f;
				}
			}
			else if (_heldEntityId.HasValue)
			{
				float? dropEntityTime = _dropEntityTime;
				if (dropEntityTime.HasValue)
				{
					float valueOrDefault = dropEntityTime.GetValueOrDefault();
					if (Time.time >= valueOrDefault)
					{
						UnityEngine.Debug.Log($"Soak dropping entity {_heldEntityId.Value.index}");
						managerForZone.RequestThrowEntity(_heldEntityId.Value, isLeftHand: true, UnityEngine.Vector3.zero, UnityEngine.Vector3.zero, UnityEngine.Vector3.zero);
						_heldEntityId = null;
						_dropEntityTime = null;
						Complete = true;
					}
				}
			}
			return true;
		}

		public void Reset()
		{
			_heldEntityId = null;
			_dropEntityTime = null;
			Complete = false;
		}
	}
	public sealed class SoakTaskHitEnemy : IGhostReactorSoakTask
	{
		public const float TIME_BETWEEN_HITS = 0.1f;

		private readonly GRPlayer _grPlayer;

		private GameEntity _enemy;

		private float? _nextHitTime;

		public bool Complete { get; private set; }

		public SoakTaskHitEnemy(GRPlayer grPlayer)
		{
			_grPlayer = grPlayer;
		}

		public bool Update()
		{
			GameEntityManager managerForZone = GameEntityManager.GetManagerForZone(_grPlayer.gamePlayer.rig.zoneEntity.currentZone);
			if (managerForZone == null)
			{
				return false;
			}
			if (_enemy != null && !IsLivingEnemy(_enemy))
			{
				UnityEngine.Debug.Log($"soak enemy {_enemy.id.index} is dead");
				Complete = true;
				return true;
			}
			if (_enemy == null)
			{
				foreach (GameEntity item in managerForZone.GetGameEntities().ShuffleIntoCollection<List<GameEntity>, GameEntity>())
				{
					if (!(item == null) && !item.IsHeld() && !(item.GetComponent<GameAgent>() == null) && !(item.GetComponent<GameHittable>() == null) && IsEnemy(item))
					{
						_enemy = item;
						_nextHitTime = Time.time + 0.1f;
						break;
					}
				}
				return _enemy != null;
			}
			if (!_nextHitTime.HasValue)
			{
				throw new Exception("Invalid state in HitEnemySoakTask.");
			}
			if (Time.time < _nextHitTime.Value)
			{
				return true;
			}
			UnityEngine.Debug.Log($"soak hitting enemy {_enemy.id.index}");
			GameEntity randomTool = GetRandomTool();
			if ((object)randomTool == null)
			{
				UnityEngine.Debug.LogError("No club found for soak task hit enemy.");
				return false;
			}
			GameHitData hit = new GameHitData
			{
				hitEntityId = _enemy.id,
				hitByEntityId = randomTool.id,
				hitTypeId = 0,
				hitEntityPosition = UnityEngine.Vector3.zero,
				hitPosition = UnityEngine.Vector3.zero,
				hitImpulse = UnityEngine.Vector3.zero,
				hitAmount = 1
			};
			managerForZone.RequestHit(hit);
			_nextHitTime = Time.time + 0.1f;
			return true;
		}

		public void Reset()
		{
			_enemy = null;
			_nextHitTime = null;
			Complete = false;
		}

		private GameEntity GetRandomTool()
		{
			GameEntityManager managerForZone = GameEntityManager.GetManagerForZone(_grPlayer.gamePlayer.rig.zoneEntity.currentZone);
			if (managerForZone == null)
			{
				return null;
			}
			foreach (GameEntity item in managerForZone.GetGameEntities().ShuffleIntoCollection<List<GameEntity>, GameEntity>())
			{
				if (item == null)
				{
					continue;
				}
				GRTool component = item.GetComponent<GRTool>();
				if ((object)component != null)
				{
					GRTool.GRToolType toolType = component.toolType;
					if (toolType == GRTool.GRToolType.Club || toolType == GRTool.GRToolType.HockeyStick)
					{
						return item;
					}
				}
			}
			return null;
		}

		private static bool IsEnemy(GameEntity entity)
		{
			if (!(entity.GetComponent<GREnemyChaser>() != null) && !(entity.GetComponent<GREnemyPest>() != null) && !(entity.GetComponent<GREnemyRanged>() != null) && !(entity.GetComponent<GREnemySummoner>() != null))
			{
				return entity.GetComponent<GREnemyMonkeye>() != null;
			}
			return true;
		}

		private static bool IsLivingEnemy(GameEntity entity)
		{
			if (IsEnemy(entity))
			{
				GREnemyChaser component = entity.GetComponent<GREnemyChaser>();
				if ((object)component == null || component.hp <= 0)
				{
					GREnemyPest component2 = entity.GetComponent<GREnemyPest>();
					if ((object)component2 == null || component2.hp <= 0)
					{
						GREnemyRanged component3 = entity.GetComponent<GREnemyRanged>();
						if ((object)component3 == null || component3.hp <= 0)
						{
							GREnemySummoner component4 = entity.GetComponent<GREnemySummoner>();
							if ((object)component4 == null || component4.hp <= 0)
							{
								GREnemyMonkeye component5 = entity.GetComponent<GREnemyMonkeye>();
								if ((object)component5 != null)
								{
									return component5.hp > 0;
								}
								return false;
							}
						}
					}
				}
				return true;
			}
			return false;
		}
	}
}
namespace GorillaTagScripts.Builder
{
	public class BuilderAnimateOnTap : BuilderPieceTappable
	{
