	public class BuilderConveyorManager : MonoBehaviour
	{
		[BurstCompile]
		public struct EvaluateSplineJob : IJobParallelForTransform
		{
			public NativeSpline conveyorSpline0;

			public NativeSpline conveyorSpline1;

			public NativeSpline conveyorSpline2;

			public NativeSpline conveyorSpline3;

			[Unity.Collections.ReadOnly]
			public NativeArray<UnityEngine.Quaternion> conveyorRotations;

			[Unity.Collections.ReadOnly]
			public NativeList<int> conveyorIndices;

			[Unity.Collections.ReadOnly]
			public NativeList<float> splineTimes;

			[Unity.Collections.ReadOnly]
			public NativeList<UnityEngine.Vector3> shelfOffsets;

			public NativeSpline GetSplineAt(int index)
			{
				return index switch
				{
					0 => conveyorSpline0, 
					1 => conveyorSpline1, 
					2 => conveyorSpline2, 
					3 => conveyorSpline3, 
					_ => conveyorSpline0, 
				};
			}

			public void SetSplineAt(int index, NativeSpline s)
			{
				switch (index)
				{
				case 0:
					conveyorSpline0 = s;
					break;
				case 1:
					conveyorSpline1 = s;
					break;
				case 2:
					conveyorSpline2 = s;
					break;
				case 3:
					conveyorSpline3 = s;
					break;
				}
			}

			public void Execute(int index, TransformAccess transform)
			{
				float splineT = splineTimes[index];
				UnityEngine.Vector3 vector = shelfOffsets[index];
				int index2 = conveyorIndices[index];
				NativeSpline splineAt = GetSplineAt(index2);
				UnityEngine.Quaternion quaternion2 = conveyorRotations[index2];
				float curveT;
				UnityEngine.Vector3 position = (UnityEngine.Vector3)CurveUtility.EvaluatePosition(splineAt.GetCurve(splineAt.SplineToCurveT(splineT, out curveT)), curveT) + quaternion2 * vector;
				transform.position = position;
			}
		}

		private NativeArray<NativeSpline> conveyorSplines;

		private NativeArray<UnityEngine.Quaternion> conveyorRotations;

		private NativeList<int> conveyorIndices;

		private NativeList<float> jobSplineTimes;

		private NativeList<UnityEngine.Vector3> jobShelfOffsets;

		private TransformAccessArray pieceTransforms;

		private BuilderTable table;

		private bool isSetup;

		private int maxItemCount;

		private int shelfSlice;

		public static BuilderConveyorManager instance { get; private set; }

		private void Awake()
		{
			if (instance != null && instance != this)
			{
				UnityEngine.Object.Destroy(this);
			}
			if (instance == null)
			{
				instance = this;
			}
		}

		public void UpdateManager()
		{
			foreach (BuilderConveyor conveyor in table.conveyors)
			{
				conveyor.UpdateConveyor();
			}
			bool flag = false;
			bool flag2 = pieceTransforms.length >= pieceTransforms.capacity - 5;
			for (int num = jobSplineTimes.Length - 1; num >= 0; num--)
			{
				BuilderConveyor builderConveyor = table.conveyors[conveyorIndices[num]];
				float num2 = Time.deltaTime * builderConveyor.GetFrameMovement();
				float num3 = jobSplineTimes[num] + num2;
				jobSplineTimes[num] = Mathf.Clamp(num3, 0f, 1f);
				if (PhotonNetwork.IsMasterClient && (!flag || flag2) && (double)num3 > 0.999)
				{
					builderConveyor.RemovePieceFromConveyor(pieceTransforms[num]);
					RemovePieceFromJobAtIndex(num);
					flag = true;
				}
			}
			for (int i = shelfSlice; i < table.conveyors.Count; i += BuilderTable.SHELF_SLICE_BUCKETS)
			{
				table.conveyors[i].UpdateShelfSliced();
			}
			shelfSlice = (shelfSlice + 1) % BuilderTable.SHELF_SLICE_BUCKETS;
		}

		public void Setup(BuilderTable mytable)
		{
			if (!isSetup)
			{
				table = mytable;
				conveyorSplines = new NativeArray<NativeSpline>(table.conveyors.Count, Unity.Collections.Allocator.Persistent);
				conveyorRotations = new NativeArray<UnityEngine.Quaternion>(table.conveyors.Count, Unity.Collections.Allocator.Persistent);
				int num = 0;
				for (int i = 0; i < table.conveyors.Count; i++)
				{
					conveyorSplines[i] = table.conveyors[i].nativeSpline;
					conveyorRotations[i] = table.conveyors[i].GetSpawnTransform().rotation;
					num += table.conveyors[i].GetMaxItemsOnConveyor();
				}
				maxItemCount = num;
				conveyorIndices = new NativeList<int>(maxItemCount, Unity.Collections.Allocator.Persistent);
				jobSplineTimes = new NativeList<float>(maxItemCount, Unity.Collections.Allocator.Persistent);
				jobShelfOffsets = new NativeList<UnityEngine.Vector3>(maxItemCount, Unity.Collections.Allocator.Persistent);
				pieceTransforms = new TransformAccessArray(maxItemCount, 3);
				isSetup = true;
			}
		}

		public float GetSplineProgressForPiece(BuilderPiece piece)
		{
			for (int i = 0; i < pieceTransforms.length; i++)
			{
				if (pieceTransforms[i] == piece.transform)
				{
					return jobSplineTimes[i];
				}
			}
			return 1f;
		}

		public int GetPieceCreateTimestamp(BuilderPiece piece)
		{
			for (int i = 0; i < pieceTransforms.length; i++)
			{
				if (pieceTransforms[i] == piece.transform)
				{
					BuilderConveyor builderConveyor = table.conveyors[conveyorIndices[i]];
					int num = Mathf.RoundToInt(jobSplineTimes[i] / builderConveyor.GetFrameMovement() * 1000f);
					return PhotonNetwork.ServerTimestamp - num;
				}
			}
			return PhotonNetwork.ServerTimestamp - 5000;
		}

		public void OnClearTable()
		{
			if (!isSetup)
			{
				return;
			}
			foreach (BuilderConveyor conveyor in table.conveyors)
			{
				conveyor.OnClearTable();
			}
			for (int num = pieceTransforms.length - 1; num >= 0; num--)
			{
				pieceTransforms.RemoveAtSwapBack(num);
			}
			jobSplineTimes.Clear();
			jobShelfOffsets.Clear();
			conveyorIndices.Clear();
		}

		private void OnDestroy()
		{
			conveyorSplines.Dispose();
			conveyorRotations.Dispose();
			conveyorIndices.Dispose();
			jobSplineTimes.Dispose();
			jobShelfOffsets.Dispose();
			pieceTransforms.Dispose();
		}

		public JobHandle ConstructJobHandle()
		{
			EvaluateSplineJob jobData = new EvaluateSplineJob
			{
				conveyorRotations = conveyorRotations,
				conveyorIndices = conveyorIndices,
				shelfOffsets = jobShelfOffsets,
				splineTimes = jobSplineTimes
			};
			for (int i = 0; i < conveyorSplines.Length; i++)
			{
				jobData.SetSplineAt(i, conveyorSplines[i]);
			}
			return jobData.Schedule(pieceTransforms);
		}

		public void AddPieceToJob(BuilderPiece piece, float splineTime, int conveyorID)
		{
			if (pieceTransforms.length >= pieceTransforms.capacity)
			{
				UnityEngine.Debug.LogError("Too many pieces on conveyor!");
			}
			pieceTransforms.Add(piece.transform);
			conveyorIndices.Add(in conveyorID);
			jobShelfOffsets.Add(in piece.desiredShelfOffset);
			jobSplineTimes.Add(in splineTime);
		}

		public void RemovePieceFromJobAtIndex(int index)
		{
			BuilderRenderer.RemoveAt(pieceTransforms, index);
			jobShelfOffsets.RemoveAt(index);
			jobSplineTimes.RemoveAt(index);
			conveyorIndices.RemoveAt(index);
		}

		public void RemovePieceFromJob(BuilderPiece piece)
		{
			for (int i = 0; i < pieceTransforms.length; i++)
			{
				if (pieceTransforms[i] == piece.transform)
				{
					BuilderRenderer.RemoveAt(pieceTransforms, i);
					jobShelfOffsets.RemoveAt(i);
					jobSplineTimes.RemoveAt(i);
					conveyorIndices.RemoveAt(i);
					break;
				}
			}
		}
	}
	public class BuilderMovingPart : MonoBehaviour
	{
		public enum BuilderMovingPartType
		{
			Translation,
			Rotation
		}

		public BuilderPiece myPiece;

		public BuilderAttachGridPlane[] myGridPlanes;

		[SerializeField]
		private BuilderMovingPartType moveType;

		[SerializeField]
		private float startPercentage = 0.5f;

		[SerializeField]
		private float velocity;

		[SerializeField]
		private bool reverseDirOnCycle = true;

		[SerializeField]
		private bool reverseDir;

		[SerializeField]
		private float cycleDelay = 0.25f;

		[SerializeField]
		protected Transform startXf;

		[SerializeField]
		protected Transform endXf;

		public static int NUM_PAUSE_NODES = 32;

		private AnimationCurve lerpAlpha;

		public bool isMoving;

		private UnityEngine.Quaternion initLocalRotation = UnityEngine.Quaternion.identity;

		private UnityEngine.Vector3 initLocalPos = UnityEngine.Vector3.zero;

		private float cycleDuration;

		private float distance;

		private float currT;

		private float percent;

		private bool currForward;

		private float dtSinceServerUpdate;

		private int lastServerTimeStamp;

		private float rotateStartAmt;

		private float rotateAmt;

		private uint startPercentageCycleOffset;

		private void Awake()
		{
			BuilderAttachGridPlane[] array = myGridPlanes;
			foreach (BuilderAttachGridPlane obj in array)
			{
				obj.movesOnPlace = true;
				obj.movingPart = this;
			}
			initLocalPos = base.transform.localPosition;
			initLocalRotation = base.transform.localRotation;
		}

		private long NetworkTimeMs()
		{
			if (PhotonNetwork.InRoom)
			{
				return (uint)(PhotonNetwork.ServerTimestamp - myPiece.activatedTimeStamp + (int)startPercentageCycleOffset + int.MinValue);
			}
			return (long)(Time.time * 1000f);
		}

		private long CycleLengthMs()
		{
			return (long)(cycleDuration * 1000f);
		}

		public double PlatformTime()
		{
			long num = NetworkTimeMs();
			long num2 = CycleLengthMs();
			return (double)(num - num / num2 * num2) / 1000.0;
		}

		public int CycleCount()
		{
			return (int)(NetworkTimeMs() / CycleLengthMs());
		}

		public float CycleCompletionPercent()
		{
			return Mathf.Clamp((float)(PlatformTime() / (double)cycleDuration), 0f, 1f);
		}

		public bool IsEvenCycle()
		{
			return CycleCount() % 2 == 0;
		}

		public void ActivateAtNode(byte node, int timestamp)
		{
			float num = (int)node;
			bool flag = node > NUM_PAUSE_NODES;
			if (flag)
			{
				num -= (float)NUM_PAUSE_NODES;
			}
			num /= (float)NUM_PAUSE_NODES;
			num = Mathf.Clamp(num, 0f, 1f);
			if (num >= startPercentage)
			{
				int num2 = (int)((num - startPercentage) * (float)CycleLengthMs());
				int num3 = timestamp - num2;
				if (flag)
				{
					num3 -= (int)CycleLengthMs();
				}
				myPiece.activatedTimeStamp = num3;
			}
			else
			{
				int num4 = (int)((num + 2f - startPercentage) * (float)CycleLengthMs());
				if (flag)
				{
					num4 -= (int)CycleLengthMs();
				}
				myPiece.activatedTimeStamp = timestamp - num4;
			}
			SetMoving(isMoving: true);
		}

		public int GetTimeOffsetMS()
		{
			int num = PhotonNetwork.ServerTimestamp - myPiece.activatedTimeStamp;
			uint num2 = (uint)(CycleLengthMs() * 2);
			return (int)((uint)num % num2);
		}

		public byte GetNearestNode()
		{
			int num = Mathf.RoundToInt(currT * (float)NUM_PAUSE_NODES);
			if (!IsEvenCycle())
			{
				num += NUM_PAUSE_NODES;
			}
			return (byte)num;
		}

		public byte GetStartNode()
		{
			return (byte)Mathf.RoundToInt(startPercentage * (float)NUM_PAUSE_NODES);
		}

		public void PauseMovement(byte node)
		{
			SetMoving(isMoving: false);
			bool flag = node > NUM_PAUSE_NODES;
			float num = (int)node;
			if (flag)
			{
				num -= (float)NUM_PAUSE_NODES;
			}
			num /= (float)NUM_PAUSE_NODES;
			num = Mathf.Clamp(num, 0f, 1f);
			if (reverseDirOnCycle)
			{
				num = (flag ? (1f - num) : num);
			}
			if (reverseDir)
			{
				num = 1f - num;
			}
			switch (moveType)
			{
			case BuilderMovingPartType.Translation:
				base.transform.localPosition = UpdatePointToPoint(num);
				break;
			case BuilderMovingPartType.Rotation:
				UpdateRotation(num);
				break;
			}
		}

		public void SetMoving(bool isMoving)
		{
			this.isMoving = isMoving;
			BuilderAttachGridPlane[] array = myGridPlanes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].isMoving = isMoving;
			}
			if (!isMoving)
			{
				ResetMovingGrid();
			}
		}

		public void InitMovingGrid()
		{
			if (moveType == BuilderMovingPartType.Translation)
			{
				distance = UnityEngine.Vector3.Distance(endXf.position, startXf.position);
				float num = distance / (velocity * myPiece.GetScale());
				cycleDuration = num + cycleDelay;
				float num2 = cycleDelay / cycleDuration;
				UnityEngine.Vector2 vector = new UnityEngine.Vector2(num2 / 2f, 0f);
				UnityEngine.Vector2 vector2 = new UnityEngine.Vector2(1f - num2 / 2f, 1f);
				float num3 = (vector2.y - vector.y) / (vector2.x - vector.x);
				lerpAlpha = new AnimationCurve(new Keyframe(num2 / 2f, 0f, 0f, num3), new Keyframe(1f - num2 / 2f, 1f, num3, 0f));
			}
			else
			{
				cycleDuration = 1f / velocity;
			}
			currT = startPercentage;
			uint num4 = (uint)(cycleDuration * 1000f);
			uint num5 = 2147483648u % num4;
			uint num6 = (uint)(startPercentage * (float)num4);
			if (num6 >= num5)
			{
				startPercentageCycleOffset = num6 - num5;
			}
			else
			{
				startPercentageCycleOffset = num6 + num4 + num4 - num5;
			}
		}

		public void UpdateMovingGrid()
		{
			Progress();
			switch (moveType)
			{
			case BuilderMovingPartType.Translation:
				base.transform.localPosition = UpdatePointToPoint(percent);
				break;
			case BuilderMovingPartType.Rotation:
				UpdateRotation(percent);
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}

		private UnityEngine.Vector3 UpdatePointToPoint(float perc)
		{
			float t = lerpAlpha.Evaluate(perc);
			return UnityEngine.Vector3.Lerp(startXf.localPosition, endXf.localPosition, t);
		}

		private void UpdateRotation(float perc)
		{
			UnityEngine.Quaternion localRotation = UnityEngine.Quaternion.AngleAxis(perc * 360f, UnityEngine.Vector3.up);
			base.transform.localRotation = localRotation;
		}

		private void ResetMovingGrid()
		{
			base.transform.SetLocalPositionAndRotation(initLocalPos, initLocalRotation);
		}

		private void Progress()
		{
			currT = CycleCompletionPercent();
			currForward = IsEvenCycle();
			percent = currT;
			if (reverseDirOnCycle)
			{
				percent = (currForward ? currT : (1f - currT));
			}
			if (reverseDir)
			{
				percent = 1f - percent;
			}
		}

		public bool IsAnchoredToTable()
		{
			BuilderAttachGridPlane[] array = myGridPlanes;
			foreach (BuilderAttachGridPlane builderAttachGridPlane in array)
			{
				if (builderAttachGridPlane.attachIndex == builderAttachGridPlane.piece.attachIndex)
				{
					return true;
				}
			}
			return false;
		}

		public void OnPieceDestroy()
		{
			ResetMovingGrid();
		}
	}
	public class BuilderMovingSnapPiece : MonoBehaviour, IBuilderPieceComponent, IBuilderPieceFunctional
	{
		public List<BuilderMovingPart> MovingParts;

		public BuilderPiece myPiece;

		public const int MAX_MOVING_CHILDREN = 5;

		[SerializeField]
		private GameObject startMovingFX;

		[SerializeField]
		private GameObject stopMovingFX;

		private bool activated;

		private bool moving;

		private const byte MOVING_STATE = 0;

		private byte currentPauseNode;

		private void Awake()
		{
			myPiece = GetComponent<BuilderPiece>();
			if (myPiece == null)
			{
				UnityEngine.Debug.LogWarning("Missing BuilderPiece component " + base.gameObject.name);
			}
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				movingPart.myPiece = myPiece;
			}
		}

		public int GetTimeOffset()
		{
			if (myPiece.state != BuilderPiece.State.AttachedAndPlaced)
			{
				return 0;
			}
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				if (!movingPart.IsAnchoredToTable())
				{
					return movingPart.GetTimeOffsetMS();
				}
			}
			return 0;
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
		}

		public void OnPieceDestroy()
		{
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				movingPart.OnPieceDestroy();
			}
		}

		public void OnPiecePlacementDeserialized()
		{
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				movingPart.InitMovingGrid();
				movingPart.SetMoving(isMoving: false);
				if (myPiece.functionalPieceState == 0 && !movingPart.IsAnchoredToTable())
				{
					currentPauseNode = movingPart.GetStartNode();
				}
			}
			moving = false;
			if (!activated)
			{
				BuilderTable table = myPiece.GetTable();
				table.RegisterFunctionalPiece(this);
				table.RegisterFunctionalPieceFixedUpdate(this);
				activated = true;
			}
			OnStateChanged(myPiece.functionalPieceState, NetworkSystem.Instance.MasterClient, myPiece.activatedTimeStamp);
		}

		public void OnPieceActivate()
		{
			BuilderTable table = myPiece.GetTable();
			if (table.GetTableState() != BuilderTable.TableState.Ready && table.GetTableState() != BuilderTable.TableState.ExecuteQueuedCommands)
			{
				return;
			}
			if (!activated)
			{
				table.RegisterFunctionalPiece(this);
				table.RegisterFunctionalPieceFixedUpdate(this);
				activated = true;
			}
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				movingPart.InitMovingGrid();
				if (movingPart.IsAnchoredToTable())
				{
					continue;
				}
				int num = 0;
				BuilderAttachGridPlane[] myGridPlanes = movingPart.myGridPlanes;
				foreach (BuilderAttachGridPlane builderAttachGridPlane in myGridPlanes)
				{
					num += builderAttachGridPlane.GetChildCount();
				}
				if (num <= 5)
				{
					currentPauseNode = movingPart.GetStartNode();
					if (myPiece.functionalPieceState > 0 && myPiece.functionalPieceState < BuilderMovingPart.NUM_PAUSE_NODES * 2 + 1)
					{
						currentPauseNode = (byte)(myPiece.functionalPieceState - 1);
					}
					myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.MasterClient, myPiece.activatedTimeStamp);
				}
				else
				{
					currentPauseNode = movingPart.GetStartNode();
					if (myPiece.functionalPieceState > 0 && myPiece.functionalPieceState < BuilderMovingPart.NUM_PAUSE_NODES * 2 + 1)
					{
						currentPauseNode = (byte)(myPiece.functionalPieceState - 1);
					}
					myPiece.SetFunctionalPieceState((byte)(currentPauseNode + 1), NetworkSystem.Instance.MasterClient, myPiece.activatedTimeStamp);
				}
			}
		}

		public void OnPieceDeactivate()
		{
			BuilderTable table = myPiece.GetTable();
			table.UnregisterFunctionalPiece(this);
			table.UnregisterFunctionalPieceFixedUpdate(this);
			myPiece.functionalPieceState = 0;
			moving = false;
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				movingPart.SetMoving(isMoving: false);
			}
			activated = false;
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!IsStateValid(newState) || myPiece.state != BuilderPiece.State.AttachedAndPlaced || !activated)
			{
				return;
			}
			if (newState == 0 && !moving)
			{
				moving = true;
				if (startMovingFX != null)
				{
					ObjectPools.instance.Instantiate(startMovingFX, base.transform.position);
				}
				{
					foreach (BuilderMovingPart movingPart in MovingParts)
					{
						if (!movingPart.IsAnchoredToTable())
						{
							movingPart.ActivateAtNode(currentPauseNode, timeStamp);
							currentPauseNode = movingPart.GetStartNode();
						}
					}
					return;
				}
			}
			if (moving && stopMovingFX != null)
			{
				ObjectPools.instance.Instantiate(stopMovingFX, base.transform.position);
			}
			moving = false;
			currentPauseNode = (byte)(newState - 1);
			foreach (BuilderMovingPart movingPart2 in MovingParts)
			{
				if (!movingPart2.IsAnchoredToTable())
				{
					movingPart2.PauseMovement(currentPauseNode);
				}
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
		}

		public bool IsStateValid(byte state)
		{
			return state <= BuilderMovingPart.NUM_PAUSE_NODES * 2 + 1;
		}

		public void FunctionalPieceUpdate()
		{
			UpdateMaster();
		}

		public void FunctionalPieceFixedUpdate()
		{
			if (!moving)
			{
				return;
			}
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				if (!movingPart.IsAnchoredToTable())
				{
					movingPart.UpdateMovingGrid();
				}
			}
		}

		private void UpdateMaster()
		{
			if (!NetworkSystem.Instance.IsMasterClient)
			{
				return;
			}
			BuilderTable table = myPiece.GetTable();
			foreach (BuilderMovingPart movingPart in MovingParts)
			{
				if (!movingPart.IsAnchoredToTable())
				{
					int num = 0;
					BuilderAttachGridPlane[] myGridPlanes = movingPart.myGridPlanes;
					foreach (BuilderAttachGridPlane builderAttachGridPlane in myGridPlanes)
					{
						num += builderAttachGridPlane.GetChildCount();
					}
					bool num2 = num <= 5;
					if (num2 && !moving)
					{
						table.builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 0, PhotonNetwork.MasterClient, NetworkSystem.Instance.ServerTimestamp);
					}
					if (!num2 && moving)
					{
						byte state = (byte)(movingPart.GetNearestNode() + 1);
						table.builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, state, PhotonNetwork.MasterClient, NetworkSystem.Instance.ServerTimestamp);
					}
				}
			}
		}
	}
	public class BuilderParticleSpawner : MonoBehaviour
	{
		[SerializeField]
		private BuilderPiece myPiece;

		public GameObject prefab;

		public float cooldown = 0.1f;

		private float lastSpawnTime;

		[SerializeField]
		private BuilderSmallMonkeTrigger spawnTrigger;

		[SerializeField]
		private bool spawnOnEnter = true;

		[SerializeField]
		private bool spawnOnExit;

		[SerializeField]
		private Transform spawnLocation;

		private void Start()
		{
			spawnTrigger.onTriggerFirstEntered += OnEnter;
			spawnTrigger.onTriggerLastExited += OnExit;
		}

		private void OnDestroy()
		{
			if (spawnTrigger != null)
			{
				spawnTrigger.onTriggerFirstEntered -= OnEnter;
				spawnTrigger.onTriggerLastExited -= OnExit;
			}
		}

		public void TrySpawning()
		{
			if (Time.time > lastSpawnTime + cooldown)
			{
