				TrySpawning();
			}
		}

		private void OnExit()
		{
			if (spawnOnExit)
			{
				TrySpawning();
			}
		}
	}
	public class BuilderPieceBallista : MonoBehaviour, IBuilderPieceComponent, IBuilderPieceFunctional
	{
		private enum BallistaState
		{
			Idle,
			Loading,
			WaitingForTrigger,
			PlayerInTrigger,
			PrepareForLaunch,
			PrepareForLaunchLocal,
			Launching,
			LaunchingLocal,
			Count
		}

		[SerializeField]
		private BuilderPiece myPiece;

		[SerializeField]
		private List<Collider> triggers;

		[SerializeField]
		private List<Collider> disableWhileLaunching;

		[Tooltip("Trigger to start the launch if not autoLaunch")]
		[SerializeField]
		private BuilderSmallHandTrigger handTrigger;

		[Tooltip("Should the player launch without a hand trigger press")]
		[SerializeField]
		private bool autoLaunch;

		[SerializeField]
		private float autoLaunchDelay = 0.75f;

		private double enteredTriggerTime;

		public Animator animator;

		public Transform launchStart;

		public Transform launchEnd;

		public Transform launchBone;

		[SerializeField]
		private SoundBankPlayer loadSFX;

		[SerializeField]
		private SoundBankPlayer launchSFX;

		[SerializeField]
		private SoundBankPlayer cockSFX;

		[SerializeField]
		private ParticleSystem launchParticles;

		private bool hasLaunchParticles;

		public float reloadDelay = 1f;

		public float loadTime = 1.933f;

		public float slipOverrideDuration = 0.1f;

		private double launchedTime;

		public float playerMagnetismStrength = 3f;

		[Tooltip("Speed will be scaled by piece scale")]
		public float launchSpeed = 20f;

		[Range(0f, 1f)]
		public float pitch;

		private bool debugDrawTrajectoryOnLaunch;

		private int loadTriggerHash = Animator.StringToHash("Load");

		private int fireTriggerHash = Animator.StringToHash("Fire");

		private int pitchParamHash = Animator.StringToHash("Pitch");

		private int idleStateHash = Animator.StringToHash("Idle");

		private int loadStateHash = Animator.StringToHash("Load");

		private int fireStateHash = Animator.StringToHash("Fire");

		private bool playerInTrigger;

		private VRRig playerRigInTrigger;

		private bool playerLaunched;

		private float playerReadyToFireDist = 1.6667f;

		private float prepareForLaunchDistance = 2.5f;

		private UnityEngine.Vector3 launchDirection;

		private float launchRampDistance;

		private float playerPullInRate;

		private float appliedAnimatorPitch;

		private bool launchBigMonkes;

		private UnityEngine.Vector3 playerBodyOffsetFromHead = new UnityEngine.Vector3(0f, -0.4f, -0.15f);

		private double loadCompleteTime;

		private BallistaState ballistaState;

		private const int predictionLineSamples = 240;

		private UnityEngine.Vector3[] predictionLinePoints = new UnityEngine.Vector3[240];

		private void Awake()
		{
			animator.SetFloat(pitchParamHash, pitch);
			appliedAnimatorPitch = pitch;
			launchDirection = launchEnd.position - launchStart.position;
			launchRampDistance = launchDirection.magnitude;
			launchDirection /= launchRampDistance;
			playerPullInRate = Mathf.Exp(playerMagnetismStrength);
			if (handTrigger != null)
			{
				handTrigger.TriggeredEvent.AddListener(OnHandTriggerPressed);
			}
			hasLaunchParticles = launchParticles != null;
		}

		private void OnDestroy()
		{
			if (handTrigger != null)
			{
				handTrigger.TriggeredEvent.RemoveListener(OnHandTriggerPressed);
			}
		}

		private void OnHandTriggerPressed()
		{
			if (!autoLaunch && ballistaState == BallistaState.PlayerInTrigger)
			{
				myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 4);
			}
		}

		private void UpdateStateMaster()
		{
			if (!NetworkSystem.Instance.InRoom || !NetworkSystem.Instance.IsMasterClient)
			{
				return;
			}
			AnimatorStateInfo currentAnimatorStateInfo = animator.GetCurrentAnimatorStateInfo(0);
			switch (ballistaState)
			{
			case BallistaState.Idle:
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				break;
			case BallistaState.Loading:
				if (currentAnimatorStateInfo.shortNameHash == loadStateHash && (double)Time.time > loadCompleteTime)
				{
					if (playerInTrigger && playerRigInTrigger != null && (launchBigMonkes || (double)playerRigInTrigger.scaleFactor < 0.99))
					{
						myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 3, playerRigInTrigger.Creator.GetPlayerRef(), NetworkSystem.Instance.ServerTimestamp);
						break;
					}
					playerInTrigger = false;
					playerRigInTrigger = null;
					ballistaState = BallistaState.WaitingForTrigger;
				}
				break;
			case BallistaState.WaitingForTrigger:
				if (!playerInTrigger || playerRigInTrigger == null || (!launchBigMonkes && playerRigInTrigger.scaleFactor >= 0.99f))
				{
					playerInTrigger = false;
					playerRigInTrigger = null;
				}
				else if (playerInTrigger)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 3, playerRigInTrigger.Creator.GetPlayerRef(), NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			case BallistaState.PlayerInTrigger:
				if (!playerInTrigger || playerRigInTrigger == null || (!launchBigMonkes && playerRigInTrigger.scaleFactor >= 0.99f))
				{
					playerInTrigger = false;
					playerRigInTrigger = null;
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 2, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else if (autoLaunch && (double)Time.time > enteredTriggerTime + (double)autoLaunchDelay)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 4, playerRigInTrigger.Creator.GetPlayerRef(), NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			case BallistaState.PrepareForLaunch:
			case BallistaState.PrepareForLaunchLocal:
			{
				if (!playerInTrigger || playerRigInTrigger == null || (!launchBigMonkes && playerRigInTrigger.scaleFactor >= 0.99f))
				{
					playerInTrigger = false;
					playerRigInTrigger = null;
					ResetFlags();
					myPiece.functionalPieceState = 0;
					ballistaState = BallistaState.Idle;
					break;
				}
				UnityEngine.Vector3 playerBodyCenterPosition = GetPlayerBodyCenterPosition(playerRigInTrigger.transform, playerRigInTrigger.scaleFactor);
				UnityEngine.Vector3 vector = UnityEngine.Vector3.Dot(playerBodyCenterPosition - launchStart.position, launchDirection) * launchDirection + launchStart.position;
				UnityEngine.Vector3 b = playerBodyCenterPosition - vector;
				if (UnityEngine.Vector3.Lerp(UnityEngine.Vector3.zero, b, Mathf.Exp((0f - playerPullInRate) * Time.deltaTime)).sqrMagnitude < playerReadyToFireDist * myPiece.GetScale() * playerReadyToFireDist * myPiece.GetScale())
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 6, playerRigInTrigger.Creator.GetPlayerRef(), NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			}
			case BallistaState.Launching:
			case BallistaState.LaunchingLocal:
				if (currentAnimatorStateInfo.shortNameHash == idleStateHash)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			}
		}

		private void ResetFlags()
		{
			playerLaunched = false;
			loadCompleteTime = double.MaxValue;
		}

		private void UpdatePlayerPosition()
		{
			if (ballistaState != BallistaState.PrepareForLaunchLocal && ballistaState != BallistaState.LaunchingLocal)
			{
				return;
			}
			float deltaTime = Time.deltaTime;
			GTPlayer instance = GTPlayer.Instance;
			UnityEngine.Vector3 playerBodyCenterPosition = GetPlayerBodyCenterPosition(instance.headCollider.transform, instance.scale);
			UnityEngine.Vector3 lhs = playerBodyCenterPosition - launchStart.position;
			switch (ballistaState)
			{
			case BallistaState.PrepareForLaunchLocal:
			{
				UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Dot(lhs, launchDirection) * launchDirection + launchStart.position;
				UnityEngine.Vector3 vector3 = playerBodyCenterPosition - vector2;
				UnityEngine.Vector3 vector4 = UnityEngine.Vector3.Lerp(UnityEngine.Vector3.zero, vector3, Mathf.Exp((0f - playerPullInRate) * deltaTime));
				instance.transform.position = instance.transform.position + (vector4 - vector3);
				instance.SetPlayerVelocity(UnityEngine.Vector3.zero);
				instance.SetMaximumSlipThisFrame();
				break;
			}
			case BallistaState.LaunchingLocal:
				if (!playerLaunched)
				{
					float num = UnityEngine.Vector3.Dot(launchBone.position - launchStart.position, launchDirection) / launchRampDistance;
					float b = UnityEngine.Vector3.Dot(lhs, launchDirection) / launchRampDistance;
					float num2 = 0.25f * myPiece.GetScale() / launchRampDistance;
					float num3 = Mathf.Max(num + num2, b);
					float num4 = num3 * launchRampDistance;
					UnityEngine.Vector3 vector = launchDirection * num4 + launchStart.position;
					_ = instance.transform.position + (vector - playerBodyCenterPosition);
					instance.transform.position = instance.transform.position + (vector - playerBodyCenterPosition);
					instance.SetPlayerVelocity(UnityEngine.Vector3.zero);
					instance.SetMaximumSlipThisFrame();
					if (num3 >= 1f)
					{
						playerLaunched = true;
						launchedTime = Time.time;
						instance.SetPlayerVelocity(launchSpeed * myPiece.GetScale() * launchDirection);
						instance.SetMaximumSlipThisFrame();
					}
				}
				else if ((double)Time.time < launchedTime + (double)slipOverrideDuration)
				{
					instance.SetMaximumSlipThisFrame();
				}
				break;
			}
		}

		private UnityEngine.Vector3 GetPlayerBodyCenterPosition(Transform headTransform, float playerScale)
		{
			return headTransform.position + UnityEngine.Quaternion.Euler(0f, headTransform.rotation.eulerAngles.y, 0f) * new UnityEngine.Vector3(0f, 0f, playerBodyOffsetFromHead.z * playerScale) + UnityEngine.Vector3.down * (playerBodyOffsetFromHead.y * playerScale);
		}

		private void OnTriggerEnter(Collider other)
		{
			if (playerRigInTrigger != null || other.GetComponent<CapsuleCollider>() == null || other.attachedRigidbody == null)
			{
				return;
			}
			VRRig vRRig = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
			if (vRRig == null)
			{
				if (!(GTPlayer.Instance.bodyCollider == other))
				{
					return;
				}
				vRRig = GorillaTagger.Instance.offlineVRRig;
			}
			if (launchBigMonkes || !((double)vRRig.scaleFactor > 0.99))
			{
				playerRigInTrigger = vRRig;
				playerInTrigger = true;
			}
		}

		private void OnTriggerExit(Collider other)
		{
			if (playerRigInTrigger == null || !playerInTrigger || other.GetComponent<CapsuleCollider>() == null || other.attachedRigidbody == null)
			{
				return;
			}
			VRRig vRRig = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
			if (vRRig == null)
			{
				if (!(GTPlayer.Instance.bodyCollider == other))
				{
					return;
				}
				vRRig = GorillaTagger.Instance.offlineVRRig;
			}
			if (playerRigInTrigger.Equals(vRRig))
			{
				playerInTrigger = false;
				playerRigInTrigger = null;
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			if (!myPiece.GetTable().isTableMutable)
			{
				launchBigMonkes = true;
			}
			ballistaState = BallistaState.Idle;
			playerInTrigger = false;
			playerRigInTrigger = null;
			playerLaunched = false;
		}

		public void OnPieceDestroy()
		{
			myPiece.functionalPieceState = 0;
			ballistaState = BallistaState.Idle;
		}

		public void OnPiecePlacementDeserialized()
		{
			launchDirection = launchEnd.position - launchStart.position;
			launchRampDistance = launchDirection.magnitude;
			launchDirection /= launchRampDistance;
		}

		public void OnPieceActivate()
		{
			foreach (Collider trigger in triggers)
			{
				trigger.enabled = true;
			}
			animator.SetFloat(pitchParamHash, pitch);
			appliedAnimatorPitch = pitch;
			launchDirection = launchEnd.position - launchStart.position;
			launchRampDistance = launchDirection.magnitude;
			launchDirection /= launchRampDistance;
			myPiece.GetTable().RegisterFunctionalPiece(this);
		}

		public void OnPieceDeactivate()
		{
			foreach (Collider trigger in triggers)
			{
				trigger.enabled = false;
			}
			if (hasLaunchParticles)
			{
				launchParticles.Stop();
				launchParticles.Clear();
			}
			myPiece.functionalPieceState = 0;
			ballistaState = BallistaState.Idle;
			playerInTrigger = false;
			playerRigInTrigger = null;
			ResetFlags();
			myPiece.GetTable().UnregisterFunctionalPiece(this);
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!NetworkSystem.Instance.IsMasterClient || !IsStateValid(newState) || instigator == null || (BallistaState)newState == ballistaState)
			{
				return;
			}
			if (newState == 4)
			{
				if (ballistaState == BallistaState.PlayerInTrigger && playerInTrigger && playerRigInTrigger != null)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 4, playerRigInTrigger.Creator.GetPlayerRef(), timeStamp);
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("BuilderPiece Ballista unexpected state request for " + newState);
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!IsStateValid(newState))
			{
				return;
			}
			BallistaState ballistaState = (BallistaState)newState;
			if (ballistaState == this.ballistaState)
			{
				return;
			}
			switch ((BallistaState)newState)
			{
			case BallistaState.Idle:
				ResetFlags();
				break;
			case BallistaState.Loading:
				ResetFlags();
				foreach (Collider item in disableWhileLaunching)
				{
					item.enabled = true;
				}
				if (this.ballistaState == BallistaState.Launching || this.ballistaState == BallistaState.LaunchingLocal)
				{
					loadCompleteTime = Time.time + reloadDelay;
					if (loadSFX != null)
					{
						loadSFX.Play();
					}
				}
				else
				{
					loadCompleteTime = Time.time + loadTime;
				}
				animator.SetTrigger(loadTriggerHash);
				break;
			case BallistaState.PlayerInTrigger:
				enteredTriggerTime = Time.time;
				if (autoLaunch && cockSFX != null)
				{
					cockSFX.Play();
				}
				break;
			case BallistaState.PrepareForLaunch:
			{
				playerLaunched = false;
				if (!autoLaunch && cockSFX != null)
				{
					cockSFX.Play();
				}
				if (!instigator.IsLocal)
				{
					break;
				}
				GTPlayer instance = GTPlayer.Instance;
				if (!(UnityEngine.Vector3.Distance(GetPlayerBodyCenterPosition(instance.headCollider.transform, instance.scale), launchStart.position) <= prepareForLaunchDistance * myPiece.GetScale()) || (!launchBigMonkes && !((double)GorillaTagger.Instance.offlineVRRig.scaleFactor < 0.99)))
				{
					break;
				}
				ballistaState = BallistaState.PrepareForLaunchLocal;
				foreach (Collider item2 in disableWhileLaunching)
				{
					item2.enabled = false;
				}
				break;
			}
			case BallistaState.Launching:
				playerLaunched = false;
				animator.SetTrigger(fireTriggerHash);
				if (launchSFX != null)
				{
					launchSFX.Play();
				}
				if (hasLaunchParticles)
				{
					launchParticles.Play();
				}
				if (debugDrawTrajectoryOnLaunch)
				{
					StartCoroutine(DebugDrawTrajectory(8f));
				}
				if (instigator.IsLocal && this.ballistaState == BallistaState.PrepareForLaunchLocal)
				{
					ballistaState = BallistaState.LaunchingLocal;
					GorillaTagger.Instance.StartVibration(forLeftController: true, GorillaTagger.Instance.tapHapticStrength * 2f, GorillaTagger.Instance.tapHapticDuration * 4f);
					GorillaTagger.Instance.StartVibration(forLeftController: false, GorillaTagger.Instance.tapHapticStrength * 2f, GorillaTagger.Instance.tapHapticDuration * 4f);
				}
				break;
			}
			this.ballistaState = ballistaState;
		}

		public bool IsStateValid(byte state)
		{
			return state < 8;
		}

		public void FunctionalPieceUpdate()
		{
			if (!(myPiece == null) && myPiece.state == BuilderPiece.State.AttachedAndPlaced)
			{
				if (NetworkSystem.Instance.IsMasterClient)
				{
					UpdateStateMaster();
				}
				UpdatePlayerPosition();
			}
		}

		private void UpdatePredictionLine()
		{
			float num = 1f / 30f;
			UnityEngine.Vector3 position = launchEnd.position;
			UnityEngine.Vector3 vector = (launchEnd.position - launchStart.position).normalized * launchSpeed;
			for (int i = 0; i < 240; i++)
			{
				predictionLinePoints[i] = position;
				position += vector * num;
				vector += UnityEngine.Vector3.down * 9.8f * num;
			}
		}

		private IEnumerator DebugDrawTrajectory(float duration)
		{
			UpdatePredictionLine();
			float startTime = Time.time;
			while (Time.time < startTime + duration)
			{
				DebugUtil.DrawLine(launchStart.position, launchEnd.position, Color.yellow);
				DebugUtil.DrawLines(predictionLinePoints, Color.yellow);
				yield return null;
			}
		}
	}
	public class BuilderPieceDoor : MonoBehaviour, IBuilderPieceComponent, IBuilderPieceFunctional
	{
		public enum DoorState
		{
			Closed,
			Closing,
			Open,
			Opening,
			HeldOpen
		}

		[SerializeField]
		private BuilderPiece myPiece;

		[SerializeField]
		private UnityEngine.Vector3 rotateAxis = UnityEngine.Vector3.up;

		[Tooltip("True if the door stays open until the button is triggered again")]
		[SerializeField]
		private bool IsToggled;

		[Tooltip("True if the door opens when players enter the Keep Open Trigger")]
		[SerializeField]
		private bool isAutomatic;

		[SerializeField]
		private Transform doorTransform;

		[SerializeField]
		private Collider[] triggerVolumes;

		[SerializeField]
		private BuilderSmallHandTrigger[] doorButtonTriggers;

		[SerializeField]
		private BuilderSmallMonkeTrigger[] doorHoldTriggers;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private SoundBankPlayer openSound;

		[SerializeField]
		private SoundBankPlayer closeSound;

		[SerializeField]
		private float doorOpenSpeed = 1f;

		[SerializeField]
		private float doorCloseSpeed = 1f;

		[SerializeField]
		[Range(1.5f, 10f)]
		private float timeUntilDoorCloses = 3f;

		[Header("Double Door Settings")]
		[SerializeField]
		private bool isDoubleDoor;

		[SerializeField]
		private UnityEngine.Vector3 rotateAxisB = UnityEngine.Vector3.down;

		[SerializeField]
		private Transform doorTransformB;

		[SerializeField]
		private LineRenderer[] lineRenderers;

		private DoorState currentState;

		private float tLastOpened;

		private BoingKit.FloatSpring doorSpring;

		private bool peopleInHoldOpenVolume;

		private double CheckHoldTriggersTime;

		private float checkHoldTriggersDelay = 3f;

		private void Awake()
		{
			BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
			foreach (BuilderSmallMonkeTrigger obj in array)
			{
				obj.onTriggerFirstEntered += OnHoldTriggerEntered;
				obj.onTriggerLastExited += OnHoldTriggerExited;
			}
			BuilderSmallHandTrigger[] array2 = doorButtonTriggers;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].TriggeredEvent.AddListener(OnDoorButtonTriggered);
			}
		}

		private void OnDestroy()
		{
			BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
			foreach (BuilderSmallMonkeTrigger obj in array)
			{
				obj.onTriggerFirstEntered -= OnHoldTriggerEntered;
				obj.onTriggerLastExited -= OnHoldTriggerExited;
			}
			BuilderSmallHandTrigger[] array2 = doorButtonTriggers;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].TriggeredEvent.RemoveListener(OnDoorButtonTriggered);
			}
		}

		private void SetDoorState(DoorState value)
		{
			bool num = currentState == DoorState.Closed || (currentState == DoorState.Open && IsToggled);
			bool flag = value switch
			{
				DoorState.Open => IsToggled, 
				DoorState.Closed => true, 
				_ => false, 
			};
			currentState = value;
			if (num != flag)
			{
				if (flag)
				{
					myPiece.GetTable().UnregisterFunctionalPiece(this);
				}
				else
				{
					myPiece.GetTable().RegisterFunctionalPiece(this);
				}
			}
		}

		private void UpdateDoorStateMaster()
		{
			switch (currentState)
			{
			case DoorState.Closing:
				if (doorSpring.Value < 1f)
				{
					doorSpring.Reset();
					doorTransform.localRotation = UnityEngine.Quaternion.identity;
					if (isDoubleDoor && doorTransformB != null)
					{
						doorTransformB.localRotation = UnityEngine.Quaternion.identity;
					}
					SetDoorState(DoorState.Closed);
				}
				break;
			case DoorState.Open:
			{
				if (IsToggled || !(Time.time - tLastOpened > timeUntilDoorCloses))
				{
					break;
				}
				peopleInHoldOpenVolume = false;
				BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
				foreach (BuilderSmallMonkeTrigger obj2 in array)
				{
					obj2.ValidateOverlappingColliders();
					if (obj2.overlapCount > 0)
					{
						peopleInHoldOpenVolume = true;
						break;
					}
				}
				if (peopleInHoldOpenVolume)
				{
					CheckHoldTriggersTime = Time.time + checkHoldTriggersDelay;
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 4, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			}
			case DoorState.Opening:
				if (doorSpring.Value > 89f)
				{
					SetDoorState(DoorState.Open);
				}
				break;
			case DoorState.HeldOpen:
			{
				if (IsToggled || !((double)Time.time > CheckHoldTriggersTime))
				{
					break;
				}
				BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
				foreach (BuilderSmallMonkeTrigger obj in array)
				{
					obj.ValidateOverlappingColliders();
					if (obj.overlapCount > 0)
					{
						peopleInHoldOpenVolume = true;
						break;
					}
				}
				if (peopleInHoldOpenVolume)
				{
					CheckHoldTriggersTime = Time.time + checkHoldTriggersDelay;
				}
				else
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			}
			}
		}

		private void UpdateDoorState()
		{
			switch (currentState)
			{
			case DoorState.Opening:
				if (doorSpring.Value > 89f)
				{
					SetDoorState(DoorState.Open);
				}
				break;
			case DoorState.Closing:
				if (doorSpring.Value < 1f)
				{
					doorSpring.Reset();
					doorTransform.localRotation = UnityEngine.Quaternion.identity;
					if (isDoubleDoor && doorTransformB != null)
					{
						doorTransformB.localRotation = UnityEngine.Quaternion.identity;
					}
					SetDoorState(DoorState.Closed);
				}
				break;
			}
		}

		private void CloseDoor()
		{
			switch (currentState)
			{
			case DoorState.Open:
			case DoorState.HeldOpen:
				closeSound.Play();
				SetDoorState(DoorState.Closing);
				break;
			default:
				throw new ArgumentOutOfRangeException();
			case DoorState.Closed:
			case DoorState.Closing:
			case DoorState.Opening:
				break;
			}
		}

		private void OpenDoor()
		{
			switch (currentState)
			{
			case DoorState.Closed:
				tLastOpened = Time.time;
				openSound.Play();
				SetDoorState(DoorState.Opening);
				break;
			default:
				throw new ArgumentOutOfRangeException();
			case DoorState.Closing:
			case DoorState.Open:
			case DoorState.Opening:
			case DoorState.HeldOpen:
				break;
			}
		}

		private void UpdateDoorAnimation()
		{
			DoorState doorState = currentState;
			if ((uint)doorState > 1u && (uint)(doorState - 2) <= 2u)
			{
				doorSpring.TrackDampingRatio(90f, MathF.PI * doorOpenSpeed, 1f, Time.deltaTime);
				doorTransform.localRotation = UnityEngine.Quaternion.Euler(rotateAxis * doorSpring.Value);
				if (isDoubleDoor && doorTransformB != null)
				{
					doorTransformB.localRotation = UnityEngine.Quaternion.Euler(rotateAxisB * doorSpring.Value);
				}
			}
			else
			{
				doorSpring.TrackDampingRatio(0f, MathF.PI * doorCloseSpeed, 1f, Time.deltaTime);
				doorTransform.localRotation = UnityEngine.Quaternion.Euler(rotateAxis * doorSpring.Value);
				if (isDoubleDoor && doorTransformB != null)
				{
					doorTransformB.localRotation = UnityEngine.Quaternion.Euler(rotateAxisB * doorSpring.Value);
				}
			}
		}

		private void OnDoorButtonTriggered()
		{
			switch (currentState)
			{
			case DoorState.Closed:
				if (NetworkSystem.Instance.IsMasterClient)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 3, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else
				{
					myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 3);
				}
				break;
			case DoorState.Open:
				if (IsToggled)
				{
					if (NetworkSystem.Instance.IsMasterClient)
					{
						myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
					}
					else
					{
						myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 1);
					}
				}
				break;
			}
		}

		private void OnHoldTriggerEntered()
		{
			peopleInHoldOpenVolume = true;
			if (!NetworkSystem.Instance.IsMasterClient)
			{
				return;
			}
			switch (currentState)
			{
			case DoorState.Closed:
				if (isAutomatic)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 3, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			case DoorState.Closing:
				if (!IsToggled)
				{
					openSound.Play();
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 4, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			}
		}

		private void OnHoldTriggerExited()
		{
			peopleInHoldOpenVolume = false;
			BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
			foreach (BuilderSmallMonkeTrigger obj in array)
			{
				obj.ValidateOverlappingColliders();
				if (obj.overlapCount > 0)
				{
					peopleInHoldOpenVolume = true;
					break;
				}
			}
			if (NetworkSystem.Instance.IsMasterClient && currentState == DoorState.HeldOpen && !peopleInHoldOpenVolume)
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			tLastOpened = 0f;
			SetDoorState(DoorState.Closed);
			doorSpring.Reset();
			doorTransform.localRotation = UnityEngine.Quaternion.identity;
			if (isDoubleDoor && doorTransformB != null)
			{
				doorTransformB.localRotation = UnityEngine.Quaternion.identity;
			}
			Collider[] array = triggerVolumes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].enabled = false;
			}
			if (lineRenderers != null)
			{
				LineRenderer[] array2 = lineRenderers;
				for (int i = 0; i < array2.Length; i++)
				{
					array2[i].widthMultiplier = myPiece.GetScale();
				}
			}
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			Collider[] array = triggerVolumes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].enabled = true;
			}
		}

		public void OnPieceDeactivate()
		{
			Collider[] array = triggerVolumes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].enabled = false;
			}
			myPiece.functionalPieceState = 0;
			SetDoorState(DoorState.Closed);
			doorSpring.Reset();
			doorTransform.localRotation = UnityEngine.Quaternion.identity;
			if (isDoubleDoor && doorTransformB != null)
			{
				doorTransformB.localRotation = UnityEngine.Quaternion.identity;
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (NetworkSystem.Instance.IsMasterClient && IsStateValid(newState) && instigator != null && currentState != (DoorState)newState)
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, newState, instigator.GetPlayerRef(), timeStamp);
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!IsStateValid(newState))
			{
				return;
			}
			switch (newState)
			{
			case 3:
				if (currentState == DoorState.Closed)
				{
					OpenDoor();
				}
				break;
			case 4:
				if (currentState == DoorState.Closing)
				{
					openSound.Play();
				}
				break;
			case 1:
				if (currentState == DoorState.Open || currentState == DoorState.HeldOpen)
				{
					CloseDoor();
				}
				break;
			}
			SetDoorState((DoorState)newState);
		}

		public bool IsStateValid(byte state)
		{
			return state < 5;
		}

		public void FunctionalPieceUpdate()
		{
			if (myPiece != null && myPiece.state == BuilderPiece.State.AttachedAndPlaced)
			{
				if (!NetworkSystem.Instance.InRoom && currentState != DoorState.Closed)
				{
					CloseDoor();
				}
				else if (NetworkSystem.Instance.IsMasterClient)
				{
					UpdateDoorStateMaster();
				}
				else
				{
					UpdateDoorState();
				}
				UpdateDoorAnimation();
			}
		}
	}
	public class BuilderPieceDoorSwinging : MonoBehaviour, IBuilderPieceComponent, IBuilderPieceFunctional
	{
		private enum SwingingDoorState
		{
			Closed,
			ClosingOut,
			OpenOut,
			OpeningOut,
			HeldOpenOut,
			ClosingIn,
			OpenIn,
			OpeningIn,
			HeldOpenIn
		}

		[SerializeField]
		private BuilderPiece myPiece;

		[SerializeField]
		private UnityEngine.Vector3 rotateAxis = UnityEngine.Vector3.up;

		[SerializeField]
		private Transform doorTransform;

		[SerializeField]
		private Collider[] triggerVolumes;

		[SerializeField]
		private BuilderSmallMonkeTrigger[] doorHoldTriggers;

		[SerializeField]
		private BuilderSmallHandTrigger frontTrigger;

		[SerializeField]
		private BuilderSmallHandTrigger backTrigger;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private SoundBankPlayer openSound;

		[SerializeField]
		private SoundBankPlayer closeSound;

		[SerializeField]
		private float doorOpenSpeed = 1f;

		[SerializeField]
		private float doorCloseSpeed = 1f;

		[SerializeField]
		[Range(1.5f, 10f)]
		private float timeUntilDoorCloses = 3f;

		[SerializeField]
		private float doorClosedVelocityMag = 30f;

		[SerializeField]
		private float dampingRatio = 0.5f;

		[Header("Double Door Settings")]
		[SerializeField]
		private bool isDoubleDoor;

		[SerializeField]
		private UnityEngine.Vector3 rotateAxisB = UnityEngine.Vector3.down;

		[SerializeField]
		private Transform doorTransformB;

		private SwingingDoorState currentState;

		private float tLastOpened;

		private BoingKit.FloatSpring doorSpring;

		private bool peopleInHoldOpenVolume;

		private double checkHoldTriggersTime;

		private float checkHoldTriggersDelay = 3f;

		private int pushDirection = 1;

		private void Awake()
		{
			BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
			foreach (BuilderSmallMonkeTrigger obj in array)
			{
				obj.onTriggerFirstEntered += OnHoldTriggerEntered;
				obj.onTriggerLastExited += OnHoldTriggerExited;
			}
			frontTrigger.TriggeredEvent.AddListener(OnFrontTriggerEntered);
			backTrigger.TriggeredEvent.AddListener(OnBackTriggerEntered);
		}

		private void OnDestroy()
		{
			BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
			foreach (BuilderSmallMonkeTrigger obj in array)
			{
				obj.onTriggerFirstEntered -= OnHoldTriggerEntered;
				obj.onTriggerLastExited -= OnHoldTriggerExited;
			}
			frontTrigger.TriggeredEvent.RemoveListener(OnFrontTriggerEntered);
			backTrigger.TriggeredEvent.RemoveListener(OnBackTriggerEntered);
		}

		private void OnFrontTriggerEntered()
		{
			if (currentState == SwingingDoorState.Closed)
			{
				if (NetworkSystem.Instance.IsMasterClient)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 7, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else
				{
					myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 7);
				}
			}
		}

		private void OnBackTriggerEntered()
		{
			if (currentState == SwingingDoorState.Closed)
			{
				if (NetworkSystem.Instance.IsMasterClient)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 3, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else
				{
					myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 3);
				}
			}
		}

		private void OnHoldTriggerEntered()
		{
			peopleInHoldOpenVolume = true;
			if (NetworkSystem.Instance.IsMasterClient)
			{
				switch (currentState)
				{
				case SwingingDoorState.ClosingOut:
					openSound.Play();
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 4, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
					break;
				case SwingingDoorState.ClosingIn:
					openSound.Play();
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 8, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
					break;
				}
			}
		}

		private void OnHoldTriggerExited()
		{
			peopleInHoldOpenVolume = false;
			BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
			foreach (BuilderSmallMonkeTrigger obj in array)
			{
				obj.ValidateOverlappingColliders();
				if (obj.overlapCount > 0)
				{
					peopleInHoldOpenVolume = true;
					break;
				}
			}
			if (NetworkSystem.Instance.IsMasterClient)
			{
				if (currentState == SwingingDoorState.HeldOpenIn && !peopleInHoldOpenVolume)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 5, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else if (currentState == SwingingDoorState.HeldOpenOut && !peopleInHoldOpenVolume)
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
			}
		}

		private void SetDoorState(SwingingDoorState value)
		{
			bool num = currentState == SwingingDoorState.Closed;
			bool flag = value == SwingingDoorState.Closed;
			currentState = value;
			if (currentState == SwingingDoorState.Closed)
			{
				frontTrigger.enabled = true;
				backTrigger.enabled = true;
			}
			else
			{
				frontTrigger.enabled = false;
				backTrigger.enabled = false;
			}
			if (num != flag)
			{
				if (flag)
				{
					myPiece.GetTable().UnregisterFunctionalPiece(this);
				}
				else
				{
					myPiece.GetTable().RegisterFunctionalPiece(this);
				}
			}
		}

		private void UpdateDoorStateMaster()
		{
			switch (currentState)
			{
			case SwingingDoorState.ClosingOut:
			case SwingingDoorState.ClosingIn:
				if (Mathf.Abs(doorSpring.Value) < 1f && Mathf.Abs(doorSpring.Velocity) < doorClosedVelocityMag)
				{
					SetDoorState(SwingingDoorState.Closed);
				}
				break;
			case SwingingDoorState.OpenOut:
			case SwingingDoorState.OpenIn:
			{
				if (!(Time.time - tLastOpened > timeUntilDoorCloses))
				{
					break;
				}
				peopleInHoldOpenVolume = false;
				BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
				foreach (BuilderSmallMonkeTrigger obj2 in array)
				{
					obj2.ValidateOverlappingColliders();
					if (obj2.overlapCount > 0)
					{
						peopleInHoldOpenVolume = true;
						break;
					}
				}
				if (peopleInHoldOpenVolume)
				{
					SwingingDoorState swingingDoorState2 = ((currentState == SwingingDoorState.OpenIn) ? SwingingDoorState.HeldOpenIn : SwingingDoorState.HeldOpenOut);
					checkHoldTriggersTime = Time.time + checkHoldTriggersDelay;
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, (byte)swingingDoorState2, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				else
				{
					SwingingDoorState swingingDoorState3 = ((currentState != SwingingDoorState.OpenIn) ? SwingingDoorState.ClosingOut : SwingingDoorState.ClosingIn);
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, (byte)swingingDoorState3, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
				break;
			}
			case SwingingDoorState.OpeningIn:
				if (Mathf.Abs(doorSpring.Value) > 89f)
				{
					SetDoorState(SwingingDoorState.OpenIn);
				}
				break;
			case SwingingDoorState.OpeningOut:
				if (Mathf.Abs(doorSpring.Value) > 89f)
				{
					SetDoorState(SwingingDoorState.OpenOut);
				}
				break;
			case SwingingDoorState.HeldOpenOut:
			case SwingingDoorState.HeldOpenIn:
			{
				if (!((double)Time.time > checkHoldTriggersTime))
				{
					break;
				}
				BuilderSmallMonkeTrigger[] array = doorHoldTriggers;
				foreach (BuilderSmallMonkeTrigger obj in array)
				{
					obj.ValidateOverlappingColliders();
					if (obj.overlapCount > 0)
					{
						peopleInHoldOpenVolume = true;
						break;
					}
				}
				if (peopleInHoldOpenVolume)
				{
					checkHoldTriggersTime = Time.time + checkHoldTriggersDelay;
					break;
				}
				SwingingDoorState swingingDoorState = ((currentState != SwingingDoorState.HeldOpenIn) ? SwingingDoorState.ClosingOut : SwingingDoorState.ClosingIn);
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, (byte)swingingDoorState, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				break;
			}
			}
		}

		private void UpdateDoorState()
		{
			switch (currentState)
			{
			case SwingingDoorState.OpeningIn:
				if (Mathf.Abs(doorSpring.Value) > 89f)
				{
					SetDoorState(SwingingDoorState.OpenIn);
				}
				break;
			case SwingingDoorState.OpeningOut:
				if (Mathf.Abs(doorSpring.Value) > 89f)
				{
					SetDoorState(SwingingDoorState.OpenOut);
				}
				break;
			case SwingingDoorState.ClosingOut:
			case SwingingDoorState.ClosingIn:
				if (Mathf.Abs(doorSpring.Value) < 1f && Mathf.Abs(doorSpring.Velocity) < doorClosedVelocityMag)
				{
					SetDoorState(SwingingDoorState.Closed);
				}
				break;
			case SwingingDoorState.OpenOut:
			case SwingingDoorState.HeldOpenOut:
			case SwingingDoorState.OpenIn:
				break;
			}
		}

		private void CloseDoor()
		{
			switch (currentState)
			{
			case SwingingDoorState.OpenIn:
			case SwingingDoorState.HeldOpenIn:
				closeSound.Play();
				SetDoorState(SwingingDoorState.ClosingIn);
				break;
			case SwingingDoorState.OpenOut:
			case SwingingDoorState.HeldOpenOut:
				closeSound.Play();
				SetDoorState(SwingingDoorState.ClosingOut);
				break;
			case SwingingDoorState.OpeningOut:
			case SwingingDoorState.ClosingIn:
			case SwingingDoorState.OpeningIn:
				break;
			}
		}

		private void OpenDoor(bool openIn)
		{
			if (currentState == SwingingDoorState.Closed)
			{
				tLastOpened = Time.time;
				openSound.Play();
				SetDoorState(openIn ? SwingingDoorState.OpeningIn : SwingingDoorState.OpeningOut);
			}
		}

		private void UpdateDoorAnimation()
		{
			switch (currentState)
			{
			case SwingingDoorState.OpenIn:
			case SwingingDoorState.OpeningIn:
			case SwingingDoorState.HeldOpenIn:
				doorSpring.TrackDampingRatio(90f, MathF.PI * doorOpenSpeed, 1f, Time.deltaTime);
				doorTransform.localRotation = UnityEngine.Quaternion.Euler(rotateAxis * doorSpring.Value);
				if (isDoubleDoor && doorTransformB != null)
				{
					doorTransformB.localRotation = UnityEngine.Quaternion.Euler(rotateAxisB * doorSpring.Value);
				}
				break;
			case SwingingDoorState.OpenOut:
			case SwingingDoorState.OpeningOut:
			case SwingingDoorState.HeldOpenOut:
				doorSpring.TrackDampingRatio(-90f, MathF.PI * doorOpenSpeed, 1f, Time.deltaTime);
				doorTransform.localRotation = UnityEngine.Quaternion.Euler(rotateAxis * doorSpring.Value);
				if (isDoubleDoor && doorTransformB != null)
				{
					doorTransformB.localRotation = UnityEngine.Quaternion.Euler(rotateAxisB * doorSpring.Value);
				}
				break;
			default:
				doorSpring.TrackDampingRatio(0f, MathF.PI * doorCloseSpeed, dampingRatio, Time.deltaTime);
				doorTransform.localRotation = UnityEngine.Quaternion.Euler(rotateAxis * doorSpring.Value);
				if (isDoubleDoor && doorTransformB != null)
				{
					doorTransformB.localRotation = UnityEngine.Quaternion.Euler(rotateAxisB * doorSpring.Value);
				}
				break;
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			tLastOpened = 0f;
			SetDoorState(SwingingDoorState.Closed);
			doorSpring.Reset();
			Collider[] array = triggerVolumes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].enabled = false;
			}
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			Collider[] array = triggerVolumes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].enabled = true;
			}
		}

		public void OnPieceDeactivate()
		{
			Collider[] array = triggerVolumes;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].enabled = false;
			}
			myPiece.functionalPieceState = 0;
			SetDoorState(SwingingDoorState.Closed);
			doorSpring.Reset();
			doorTransform.localRotation = UnityEngine.Quaternion.Euler(rotateAxis * doorSpring.Value);
			if (isDoubleDoor && doorTransformB != null)
			{
				doorTransformB.localRotation = UnityEngine.Quaternion.Euler(rotateAxisB * doorSpring.Value);
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!IsStateValid(newState))
			{
				return;
			}
			switch (newState)
			{
			case 7:
				if (currentState == SwingingDoorState.Closed)
				{
					OpenDoor(openIn: true);
				}
				break;
			case 3:
				if (currentState == SwingingDoorState.Closed)
				{
					OpenDoor(openIn: false);
				}
				break;
			case 8:
				if (currentState == SwingingDoorState.ClosingIn)
				{
					openSound.Play();
				}
				break;
			case 4:
				if (currentState == SwingingDoorState.ClosingOut)
				{
					openSound.Play();
				}
				break;
			case 5:
				if (currentState == SwingingDoorState.OpenIn || currentState == SwingingDoorState.HeldOpenIn)
				{
					CloseDoor();
				}
				break;
			case 1:
				if (currentState == SwingingDoorState.OpenOut || currentState == SwingingDoorState.HeldOpenOut)
				{
					CloseDoor();
				}
				break;
			}
			SetDoorState((SwingingDoorState)newState);
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (NetworkSystem.Instance.IsMasterClient && IsStateValid(newState) && instigator != null && (newState == 7 || newState == 3) && currentState == SwingingDoorState.Closed)
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, newState, instigator.GetPlayerRef(), timeStamp);
			}
		}

		public bool IsStateValid(byte state)
		{
			return state <= 8;
		}

		public void FunctionalPieceUpdate()
		{
			if (myPiece != null && myPiece.state == BuilderPiece.State.AttachedAndPlaced)
			{
				if (!NetworkSystem.Instance.InRoom && currentState != SwingingDoorState.Closed)
				{
					CloseDoor();
				}
				else if (NetworkSystem.Instance.IsMasterClient)
				{
					UpdateDoorStateMaster();
				}
				else
				{
					UpdateDoorState();
				}
				UpdateDoorAnimation();
			}
		}
	}
