	public class BuilderPieceParticleEmitter : MonoBehaviour, IBuilderPieceComponent
	{
		[SerializeField]
		private BuilderPiece myPiece;

		[SerializeField]
		private List<ParticleSystem> particles;

		private bool inBuilderZone;

		private bool isPieceActive;

		private void OnZoneChanged()
		{
			inBuilderZone = ZoneManagement.instance.IsZoneActive(myPiece.GetTable().tableZone);
			if (inBuilderZone && isPieceActive)
			{
				StartParticles();
			}
			else if (!inBuilderZone)
			{
				StopParticles();
			}
		}

		private void StopParticles()
		{
			foreach (ParticleSystem particle in particles)
			{
				if (particle.isPlaying)
				{
					particle.Stop();
					particle.Clear();
				}
			}
		}

		private void StartParticles()
		{
			foreach (ParticleSystem particle in particles)
			{
				if (!particle.isPlaying)
				{
					particle.Play();
				}
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			StopParticles();
			ZoneManagement instance = ZoneManagement.instance;
			instance.onZoneChanged = (Action)Delegate.Combine(instance.onZoneChanged, new Action(OnZoneChanged));
			OnZoneChanged();
		}

		public void OnPieceDestroy()
		{
			ZoneManagement instance = ZoneManagement.instance;
			instance.onZoneChanged = (Action)Delegate.Remove(instance.onZoneChanged, new Action(OnZoneChanged));
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			isPieceActive = true;
			if (inBuilderZone)
			{
				StartParticles();
			}
		}

		public void OnPieceDeactivate()
		{
			isPieceActive = false;
			StopParticles();
		}
	}
	[RequireComponent(typeof(Collider))]
	[RequireComponent(typeof(GorillaSurfaceOverride))]
	public class BuilderPieceTappable : MonoBehaviour, IBuilderPieceComponent, IBuilderPieceFunctional, IBuilderTappable
	{
		private enum FunctionalState
		{
			Idle,
			Tap
		}

		[SerializeField]
		protected BuilderPiece myPiece;

		[SerializeField]
		protected float tapCooldown = 0.5f;

		private bool isPieceActive;

		private float lastTapTime;

		private FunctionalState currentState;

		[Tooltip("Called on all clients when this collider is tapped by anyone")]
		[SerializeField]
		protected UnityEvent OnTapped;

		public virtual bool CanTap()
		{
			if (isPieceActive)
			{
				return Time.time > lastTapTime + tapCooldown;
			}
			return false;
		}

		public void OnTapLocal(float tapStrength)
		{
			if (NetworkSystem.Instance.InRoom && CanTap())
			{
				myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 1);
			}
		}

		public virtual void OnTapReplicated()
		{
			OnTapped?.Invoke();
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			currentState = FunctionalState.Idle;
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			isPieceActive = true;
		}

		public void OnPieceDeactivate()
		{
			isPieceActive = false;
			if (currentState == FunctionalState.Tap)
			{
				myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				myPiece.GetTable().UnregisterFunctionalPiece(this);
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (IsStateValid(newState))
			{
				if (newState == 1 && currentState != FunctionalState.Tap)
				{
					lastTapTime = Time.time;
					OnTapReplicated();
					myPiece.GetTable().RegisterFunctionalPiece(this);
				}
				currentState = (FunctionalState)newState;
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (NetworkSystem.Instance.IsMasterClient && IsStateValid(newState) && instigator != null && newState == 1 && CanTap())
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, newState, instigator.GetPlayerRef(), timeStamp);
			}
		}

		public bool IsStateValid(byte state)
		{
			return state <= 1;
		}

		public void FunctionalPieceUpdate()
		{
			if (lastTapTime + tapCooldown < Time.time)
			{
				myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				myPiece.GetTable().UnregisterFunctionalPiece(this);
			}
		}
	}
	public class BuilderPieceTimer : MonoBehaviour, IBuilderPieceComponent, ITickSystemTick
	{
		[SerializeField]
		private BuilderPiece myPiece;

		[SerializeField]
		private bool isStart;

		[SerializeField]
		private bool isBoth;

		[SerializeField]
		private BuilderSmallHandTrigger buttonTrigger;

		[SerializeField]
		private SoundBankPlayer activateSoundBank;

		[SerializeField]
		private SoundBankPlayer stopSoundBank;

		[SerializeField]
		private float debounceTime = 0.5f;

		private float lastTriggeredTime;

		private double latestTime = 3.4028234663852886E+38;

		[SerializeField]
		private TMP_Text displayText;

		public bool TickRunning { get; set; }

		private void Awake()
		{
			buttonTrigger.TriggeredEvent.AddListener(OnButtonPressed);
		}

		private void OnDestroy()
		{
			if (buttonTrigger != null)
			{
				buttonTrigger.TriggeredEvent.RemoveListener(OnButtonPressed);
			}
		}

		private void OnButtonPressed()
		{
			if (myPiece.state == BuilderPiece.State.AttachedAndPlaced && Time.time > lastTriggeredTime + debounceTime)
			{
				lastTriggeredTime = Time.time;
				if (!isStart && stopSoundBank != null)
				{
					stopSoundBank.Play();
				}
				else if (activateSoundBank != null)
				{
					activateSoundBank.Play();
				}
				if (isBoth && isStart && displayText != null)
				{
					displayText.text = "TIME: 00:00:0";
				}
				PlayerTimerManager.instance.RequestTimerToggle(isStart);
			}
		}

		private void OnTimerStopped(int actorNum, int timeDelta)
		{
			if (isStart && !isBoth)
			{
				return;
			}
			double num = (uint)timeDelta;
			latestTime = num / 1000.0;
			if (latestTime > 3599.989990234375)
			{
				latestTime = 3599.989990234375;
			}
			displayText.text = "TIME: " + TimeSpan.FromSeconds(latestTime).ToString("mm\\:ss\\:ff");
			if (isBoth && actorNum == NetworkSystem.Instance.LocalPlayer.ActorNumber)
			{
				isStart = true;
				if (TickRunning)
				{
					TickSystem<object>.RemoveTickCallback(this);
				}
			}
		}

		private void OnLocalTimerStarted()
		{
			if (isBoth)
			{
				isStart = false;
			}
			if (myPiece.state == BuilderPiece.State.AttachedAndPlaced && !TickRunning)
			{
				TickSystem<object>.AddTickCallback(this);
			}
		}

		private void OnZoneChanged()
		{
			bool active = ZoneManagement.instance.IsZoneActive(myPiece.GetTable().tableZone);
			if (displayText != null)
			{
				displayText.gameObject.SetActive(active);
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			latestTime = double.MaxValue;
			if (displayText != null)
			{
				ZoneManagement instance = ZoneManagement.instance;
				instance.onZoneChanged = (Action)Delegate.Combine(instance.onZoneChanged, new Action(OnZoneChanged));
				OnZoneChanged();
				displayText.text = "TIME: __:__:_";
			}
		}

		public void OnPieceDestroy()
		{
			if (displayText != null)
			{
				ZoneManagement instance = ZoneManagement.instance;
				instance.onZoneChanged = (Action)Delegate.Remove(instance.onZoneChanged, new Action(OnZoneChanged));
			}
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			lastTriggeredTime = 0f;
			PlayerTimerManager.instance.OnTimerStopped.AddListener(OnTimerStopped);
			PlayerTimerManager.instance.OnLocalTimerStarted.AddListener(OnLocalTimerStarted);
			if (isBoth)
			{
				isStart = !PlayerTimerManager.instance.IsLocalTimerStarted();
				if (!isStart && displayText != null)
				{
					displayText.text = "TIME: __:__:_";
				}
			}
			if (PlayerTimerManager.instance.IsLocalTimerStarted() && !TickRunning)
			{
				TickSystem<object>.AddTickCallback(this);
			}
		}

		public void OnPieceDeactivate()
		{
			if (PlayerTimerManager.instance != null)
			{
				PlayerTimerManager.instance.OnTimerStopped.RemoveListener(OnTimerStopped);
				PlayerTimerManager.instance.OnLocalTimerStarted.RemoveListener(OnLocalTimerStarted);
			}
			if (TickRunning)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
			if (displayText != null)
			{
				displayText.text = "TIME: --:--:-";
			}
		}

		public void Tick()
		{
			if (displayText != null)
			{
				float timeForPlayer = PlayerTimerManager.instance.GetTimeForPlayer(NetworkSystem.Instance.LocalPlayer.ActorNumber);
				timeForPlayer = Mathf.Clamp(timeForPlayer, 0f, 3599.99f);
				displayText.text = "TIME: " + TimeSpan.FromSeconds(timeForPlayer).ToString("mm\\:ss\\:f");
			}
		}
	}
	public class BuilderPieceToggle : MonoBehaviour, IBuilderPieceFunctional, IBuilderPieceComponent, IBuilderTappable
	{
		[Serializable]
		private enum ToggleType
		{
			OnTap,
			OnTriggerEnter
		}

		private enum ToggleStates
		{
			Off,
			On
		}

		[SerializeField]
		protected BuilderPiece myPiece;

		[SerializeField]
		private ToggleType toggleType;

		public bool onlySmallMonkeTaps;

		[SerializeField]
		private BuilderSmallHandTrigger[] handTriggers;

		[SerializeField]
		private BuilderSmallMonkeTrigger[] bodyTriggers;

		[SerializeField]
		protected UnityEvent ToggledOn;

		[SerializeField]
		protected UnityEvent ToggledOff;

		private List<Collider> colliders = new List<Collider>(5);

		private ToggleStates toggleState;

		private void Awake()
		{
			colliders.Clear();
			if (toggleType != ToggleType.OnTriggerEnter)
			{
				return;
			}
			BuilderSmallHandTrigger[] array = handTriggers;
			foreach (BuilderSmallHandTrigger obj in array)
			{
				obj.TriggeredEvent.AddListener(OnHandTriggerEntered);
				Collider component = obj.GetComponent<Collider>();
				if (component != null)
				{
					colliders.Add(component);
				}
			}
			BuilderSmallMonkeTrigger[] array2 = bodyTriggers;
			foreach (BuilderSmallMonkeTrigger obj2 in array2)
			{
				obj2.onPlayerEnteredTrigger += OnBodyTriggerEntered;
				Collider component2 = obj2.GetComponent<Collider>();
				if (component2 != null)
				{
					colliders.Add(component2);
				}
			}
		}

		private void OnDestroy()
		{
			BuilderSmallHandTrigger[] array = handTriggers;
			foreach (BuilderSmallHandTrigger builderSmallHandTrigger in array)
			{
				if (!(builderSmallHandTrigger == null))
				{
					builderSmallHandTrigger.TriggeredEvent.RemoveListener(OnHandTriggerEntered);
				}
			}
			BuilderSmallMonkeTrigger[] array2 = bodyTriggers;
			foreach (BuilderSmallMonkeTrigger builderSmallMonkeTrigger in array2)
			{
				if (!(builderSmallMonkeTrigger == null))
				{
					builderSmallMonkeTrigger.onPlayerEnteredTrigger -= OnBodyTriggerEntered;
				}
			}
		}

		private bool CanTap()
		{
			if (onlySmallMonkeTaps && myPiece.GetTable().isTableMutable && (double)VRRigCache.Instance.localRig.Rig.scaleFactor > 0.99)
			{
				return false;
			}
			if (toggleType == ToggleType.OnTap)
			{
				return myPiece.state == BuilderPiece.State.AttachedAndPlaced;
			}
			return false;
		}

		public void OnTapLocal(float tapStrength)
		{
			if (!CanTap())
			{
				UnityEngine.Debug.Log("BuilderPieceToggle Can't Tap");
				return;
			}
			UnityEngine.Debug.Log("Tap Local");
			ToggleStateRequest();
		}

		private bool CanTrigger()
		{
			if (toggleType == ToggleType.OnTriggerEnter)
			{
				return myPiece.state == BuilderPiece.State.AttachedAndPlaced;
			}
			return false;
		}

		private void OnHandTriggerEntered()
		{
			if (CanTrigger())
			{
				ToggleStateRequest();
			}
			else
			{
				UnityEngine.Debug.Log("BuilderPieceToggle Can't Trigger");
			}
		}

		private void OnBodyTriggerEntered(int playerNumber)
		{
			if (!NetworkSystem.Instance.IsMasterClient)
			{
				return;
			}
			NetPlayer player = NetworkSystem.Instance.GetPlayer(playerNumber);
			if (player != null)
			{
				if (CanTrigger())
				{
					ToggleStateMaster(player.GetPlayerRef());
				}
				else
				{
					UnityEngine.Debug.Log("BuilderPieceToggle Can't Trigger");
				}
			}
		}

		private void ToggleStateRequest()
		{
			if (NetworkSystem.Instance.InRoom)
			{
				ToggleStates toggleStates = ((toggleState == ToggleStates.Off) ? ToggleStates.On : ToggleStates.Off);
				UnityEngine.Debug.Log("BuilderPieceToggle" + $" Requesting state {toggleStates}");
				myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, (byte)toggleStates);
			}
		}

		private void ToggleStateMaster(Player instigator)
		{
			ToggleStates toggleStates = ((toggleState == ToggleStates.Off) ? ToggleStates.On : ToggleStates.Off);
			UnityEngine.Debug.Log("BuilderPieceToggle" + $" Set Master state {toggleStates}");
			myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, (byte)toggleStates, instigator, NetworkSystem.Instance.ServerTimestamp);
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!IsStateValid(newState))
			{
				UnityEngine.Debug.Log("BuilderPieceToggle State Invalid");
				return;
			}
			UnityEngine.Debug.Log("BuilderPieceToggle" + $" State Changed {newState}");
			if ((ToggleStates)newState != toggleState)
			{
				if (newState == 1)
				{
					UnityEngine.Debug.Log("BuilderPieceToggle Toggled On");
					ToggledOn?.Invoke();
				}
				else
				{
					UnityEngine.Debug.Log("BuilderPieceToggle Toggled Off");
					ToggledOff.Invoke();
				}
			}
			toggleState = (ToggleStates)newState;
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (!NetworkSystem.Instance.IsMasterClient)
			{
				return;
			}
			if (!IsStateValid(newState) || instigator == null)
			{
				UnityEngine.Debug.Log("BuilderPieceToggle State Invalid or Player Null");
				return;
			}
			UnityEngine.Debug.Log("BuilderPieceToggle" + $" State Request {newState}");
			if (newState != (byte)toggleState)
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, newState, instigator.GetPlayerRef(), timeStamp);
			}
			else
			{
				UnityEngine.Debug.Log("BuilderPieceToggle Same State");
			}
		}

		public bool IsStateValid(byte state)
		{
			UnityEngine.Debug.Log($"Is State Valid? {state}");
			return state <= 1;
		}

		public void FunctionalPieceUpdate()
		{
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			foreach (Collider collider in colliders)
			{
				collider.enabled = true;
			}
		}

		public void OnPieceDeactivate()
		{
			myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
			foreach (Collider collider in colliders)
			{
				collider.enabled = false;
			}
		}
	}
	public class BuilderProjectile : MonoBehaviour
	{
		public delegate void ProjectileImpactEvent(BuilderProjectile projectile, UnityEngine.Vector3 impactPos, NetPlayer hitPlayer);

		public BuilderProjectileLauncher projectileSource;

		[Tooltip("Rotates to point along the Y axis after spawn.")]
		public GameObject surfaceImpactEffectPrefab;

		[Tooltip("Distance from the surface that the particle should spawn.")]
		private float impactEffectOffset;

		public float lifeTime = 20f;

		public bool faceDirectionOfTravel = true;

		private bool particleLaunched;

		private float timeCreated;

		private Rigidbody projectileRigidbody;

		public int projectileId;

		private float initialScale;

		private UnityEngine.Vector3 previousPosition;

		[HideInInspector]
		public SlingshotProjectile.AOEKnockbackConfig? aoeKnockbackConfig;

		[HideInInspector]
		public float? impactSoundVolumeOverride;

		[HideInInspector]
		public float? impactSoundPitchOverride;

		[HideInInspector]
		public float impactEffectScaleMultiplier = 1f;

		[HideInInspector]
		public float gravityMultiplier = 1f;

		private ConstantForce forceComponent;

		public UnityEngine.Vector3 launchPosition { get; private set; }

		public event ProjectileImpactEvent OnImpact;

		public void Launch(UnityEngine.Vector3 position, UnityEngine.Vector3 velocity, BuilderProjectileLauncher sourceObject, int projectileCount, float scale, int timeStamp)
		{
			particleLaunched = true;
			timeCreated = Time.time;
			projectileSource = sourceObject;
			float num = (float)(uint)(NetworkSystem.Instance.ServerTimestamp - timeStamp) / 1000f;
			if (num >= lifeTime)
			{
				Deactivate();
				return;
			}
			timeCreated -= num;
			UnityEngine.Vector3 vector = UnityEngine.Vector3.ProjectOnPlane(velocity, UnityEngine.Vector3.up);
			float f = MathF.PI / 180f * UnityEngine.Vector3.Angle(vector, velocity);
			float num2 = projectileRigidbody.mass * gravityMultiplier * ((scale < 1f) ? scale : 1f) * 9.8f;
			UnityEngine.Vector3 vector2 = num * Mathf.Cos(f) * vector;
			float num3 = velocity.z * num * Mathf.Sin(f) - 0.5f * num2 * num * num;
			launchPosition = position + vector2 + num3 * UnityEngine.Vector3.down;
			Transform obj = base.transform;
			obj.position = position;
			obj.localScale = UnityEngine.Vector3.one * scale;
			GetComponent<Collider>().contactOffset = 0.01f * scale;
			RigidbodyWaterInteraction component = GetComponent<RigidbodyWaterInteraction>();
			if (component != null)
			{
				component.objectRadiusForWaterCollision = 0.02f * scale;
			}
			projectileRigidbody.useGravity = false;
			UnityEngine.Vector3 vector3 = projectileRigidbody.mass * gravityMultiplier * ((scale < 1f) ? scale : 1f) * Physics.gravity;
			forceComponent.force = vector3;
			projectileRigidbody.linearVelocity = velocity + num * vector3;
			projectileId = projectileCount;
			projectileRigidbody.position = position;
			projectileSource.RegisterProjectile(this);
		}

		protected void Awake()
		{
			projectileRigidbody = GetComponent<Rigidbody>();
			forceComponent = GetComponent<ConstantForce>();
			initialScale = base.transform.localScale.x;
		}

		public void Deactivate()
		{
			base.transform.localScale = UnityEngine.Vector3.one * initialScale;
			projectileRigidbody.useGravity = true;
			forceComponent.force = UnityEngine.Vector3.zero;
			this.OnImpact = null;
			aoeKnockbackConfig = null;
			impactSoundVolumeOverride = null;
			impactSoundPitchOverride = null;
			impactEffectScaleMultiplier = 1f;
			gravityMultiplier = 1f;
			ObjectPools.instance.Destroy(base.gameObject);
		}

		private void SpawnImpactEffect(GameObject prefab, UnityEngine.Vector3 position, UnityEngine.Vector3 normal)
		{
			UnityEngine.Vector3 position2 = position + normal * impactEffectOffset;
			GameObject obj = ObjectPools.instance.Instantiate(prefab, position2);
			UnityEngine.Vector3 localScale = base.transform.localScale;
			obj.transform.localScale = localScale * impactEffectScaleMultiplier;
			obj.transform.up = normal;
			SurfaceImpactFX component = obj.GetComponent<SurfaceImpactFX>();
			if (component != null)
			{
				component.SetScale(localScale.x * impactEffectScaleMultiplier);
			}
			SoundBankPlayer component2 = obj.GetComponent<SoundBankPlayer>();
			if (component2 != null && !component2.playOnEnable)
			{
				component2.Play(impactSoundVolumeOverride, impactSoundPitchOverride);
			}
		}

		public void ApplyHitKnockback(UnityEngine.Vector3 hitNormal)
		{
			if (aoeKnockbackConfig.HasValue && aoeKnockbackConfig.Value.applyAOEKnockback)
			{
				UnityEngine.Vector3 vector = UnityEngine.Vector3.ProjectOnPlane(hitNormal, UnityEngine.Vector3.up);
				vector.Normalize();
				UnityEngine.Vector3 direction = 0.75f * vector + 0.25f * UnityEngine.Vector3.up;
				direction.Normalize();
				GTPlayer instance = GTPlayer.Instance;
				instance.ApplyKnockback(direction, aoeKnockbackConfig.Value.knockbackVelocity, instance.scale < 0.9f);
			}
		}

		private void OnEnable()
		{
			timeCreated = 0f;
			particleLaunched = false;
		}

		protected void OnDisable()
		{
			particleLaunched = false;
			if (projectileSource != null)
			{
				projectileSource.UnRegisterProjectile(this);
			}
			projectileSource = null;
		}

		public void UpdateProjectile()
		{
			if (particleLaunched)
			{
				if (Time.time > timeCreated + lifeTime)
				{
					Deactivate();
				}
				if (faceDirectionOfTravel)
				{
					Transform transform = base.transform;
					UnityEngine.Vector3 position = transform.position;
					UnityEngine.Vector3 forward = position - previousPosition;
					transform.rotation = ((forward.sqrMagnitude > 0f) ? UnityEngine.Quaternion.LookRotation(forward) : transform.rotation);
					previousPosition = position;
				}
			}
		}

		private void OnCollisionEnter(UnityEngine.Collision other)
		{
			if (!particleLaunched)
			{
				return;
			}
			BuilderPieceCollider component = other.transform.GetComponent<BuilderPieceCollider>();
			if (!(component != null) || !component.piece.gameObject.Equals(projectileSource.gameObject))
			{
				ContactPoint contact = other.GetContact(0);
				if (other.collider.gameObject.IsOnLayer(UnityLayer.GorillaBodyCollider))
				{
					ApplyHitKnockback(-1f * contact.normal);
				}
				SpawnImpactEffect(surfaceImpactEffectPrefab, contact.point, contact.normal);
				this.OnImpact?.Invoke(this, contact.point, null);
				Deactivate();
			}
		}

		protected void OnCollisionStay(UnityEngine.Collision other)
		{
			if (!particleLaunched)
			{
				return;
			}
			BuilderPieceCollider component = other.transform.GetComponent<BuilderPieceCollider>();
			if (!(component != null) || !component.piece.gameObject.Equals(projectileSource.gameObject))
			{
				ContactPoint contact = other.GetContact(0);
				if (other.collider.gameObject.IsOnLayer(UnityLayer.GorillaBodyCollider))
				{
					ApplyHitKnockback(-1f * contact.normal);
				}
				SpawnImpactEffect(surfaceImpactEffectPrefab, contact.point, contact.normal);
				this.OnImpact?.Invoke(this, contact.point, null);
				Deactivate();
			}
		}

		protected void OnTriggerEnter(Collider other)
		{
			if (particleLaunched && NetworkSystem.Instance.InRoom && !(GorillaGameManager.instance == null) && other.gameObject.IsOnLayer(UnityLayer.GorillaTagCollider))
			{
				NetPlayer netPlayer = other.GetComponentInParent<VRRig>()?.creator;
				if (netPlayer != null && !netPlayer.IsLocal)
				{
					SpawnImpactEffect(surfaceImpactEffectPrefab, base.transform.position, UnityEngine.Vector3.up);
					Deactivate();
				}
			}
		}
	}
	public class BuilderProjectileLauncher : MonoBehaviour, IBuilderPieceFunctional, IBuilderPieceComponent
	{
		private enum FunctionalState
		{
			Idle,
			Fire
		}

		private List<BuilderProjectile> launchedProjectiles = new List<BuilderProjectile>();

		[SerializeField]
		protected BuilderPiece myPiece;

		[SerializeField]
		protected float fireCooldown = 2f;

		[Tooltip("launch in Y direction")]
		[SerializeField]
		private Transform launchPosition;

		[SerializeField]
		private float launchVelocity;

		[SerializeField]
		private AudioSource launchSound;

		[SerializeField]
		protected GameObject projectilePrefab;

		protected float projectileScale = 0.06f;

		[SerializeField]
		protected float gravityMultiplier = 1f;

		public SlingshotProjectile.AOEKnockbackConfig knockbackConfig;

		private float lastFireTime;

		private FunctionalState currentState;

		private Dictionary<int, BuilderProjectile> allProjectiles = new Dictionary<int, BuilderProjectile>();

		private void LaunchProjectile(int timeStamp)
		{
			if (!(Time.time > lastFireTime + fireCooldown))
			{
				return;
			}
			lastFireTime = Time.time;
			int hash = PoolUtils.GameObjHashCode(projectilePrefab);
			try
			{
				GameObject obj = ObjectPools.instance.Instantiate(hash);
				projectileScale = myPiece.GetScale();
				obj.transform.localScale = UnityEngine.Vector3.one * projectileScale;
				BuilderProjectile component = obj.GetComponent<BuilderProjectile>();
				int num = HashCode.Combine(myPiece.pieceId, timeStamp);
				if (allProjectiles.ContainsKey(num))
				{
					allProjectiles.Remove(num);
				}
				allProjectiles.Add(num, component);
				SlingshotProjectile.AOEKnockbackConfig value = new SlingshotProjectile.AOEKnockbackConfig
				{
					aeoOuterRadius = knockbackConfig.aeoOuterRadius * projectileScale,
					aeoInnerRadius = knockbackConfig.aeoInnerRadius * projectileScale,
					applyAOEKnockback = knockbackConfig.applyAOEKnockback,
					impactVelocityThreshold = knockbackConfig.impactVelocityThreshold * projectileScale,
					knockbackVelocity = knockbackConfig.knockbackVelocity * projectileScale,
					playerProximityEffect = knockbackConfig.playerProximityEffect
				};
				component.aoeKnockbackConfig = value;
				component.gravityMultiplier = gravityMultiplier;
				component.Launch(launchPosition.position, launchVelocity * projectileScale * launchPosition.up, this, num, projectileScale, timeStamp);
				if (launchSound != null && launchSound.clip != null)
				{
					launchSound.Play();
				}
			}
			catch (Exception value2)
			{
				Console.WriteLine(value2);
				throw;
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (IsStateValid(newState) && (FunctionalState)newState != currentState)
			{
				currentState = (FunctionalState)newState;
				if (newState == 1)
				{
					LaunchProjectile(timeStamp);
					myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				}
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
		}

		public bool IsStateValid(byte state)
		{
			return state <= 1;
		}

		public void FunctionalPieceUpdate()
		{
			for (int num = launchedProjectiles.Count - 1; num >= 0; num--)
			{
				launchedProjectiles[num].UpdateProjectile();
			}
			if (PhotonNetwork.IsMasterClient && lastFireTime + fireCooldown < Time.time)
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, PhotonNetwork.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			myPiece.GetTable().RegisterFunctionalPiece(this);
		}

		public void OnPieceDeactivate()
		{
			myPiece.GetTable().UnregisterFunctionalPiece(this);
			for (int num = launchedProjectiles.Count - 1; num >= 0; num--)
			{
				launchedProjectiles[num].Deactivate();
			}
		}

		public void RegisterProjectile(BuilderProjectile projectile)
		{
			launchedProjectiles.Add(projectile);
		}

		public void UnRegisterProjectile(BuilderProjectile projectile)
		{
			launchedProjectiles.Remove(projectile);
			allProjectiles.Remove(projectile.projectileId);
		}
	}
	public class BuilderProjectileTarget : MonoBehaviour, IBuilderPieceFunctional
	{
		[SerializeField]
		private BuilderPiece myPiece;

		[SerializeField]
		private SlingshotProjectileHitNotifier hitNotifier;

		[SerializeField]
		protected float hitCooldown = 2f;

		[Tooltip("Optional Sounds to play on hit")]
		[SerializeField]
		protected SoundBankPlayer hitSoundbank;

		[Tooltip("Optional Sounds to play on hit")]
		[SerializeField]
		protected Animation hitAnimation;

		[SerializeField]
		protected List<Collider> colliders;

		[SerializeField]
		private TMP_Text scoreText;

		private double lastHitTime;

		private int hitCount;

		private const byte MAX_SCORE = 10;

		private const byte HIT = 11;

		private void Awake()
		{
			hitNotifier.OnProjectileHit += OnProjectileHit;
			foreach (Collider collider in colliders)
			{
				collider.contactOffset = 0.0001f;
			}
		}

		private void OnDestroy()
		{
			hitNotifier.OnProjectileHit -= OnProjectileHit;
		}

		private void OnDisable()
		{
			hitCount = 0;
			if (scoreText != null)
			{
				scoreText.text = hitCount.ToString("D2");
			}
		}

		private void OnProjectileHit(SlingshotProjectile projectile, UnityEngine.Collision collision)
		{
			if (myPiece.state == BuilderPiece.State.AttachedAndPlaced && projectile.projectileOwner != null && projectile.projectileOwner == NetworkSystem.Instance.LocalPlayer && lastHitTime + (double)hitCooldown < (double)Time.time)
			{
				myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 11);
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (instigator != null && IsStateValid(newState) && newState != 11)
			{
				lastHitTime = Time.time;
				hitCount = Mathf.Clamp(newState, 0, 10);
				PlayHitEffects();
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (NetworkSystem.Instance.IsMasterClient && IsStateValid(newState) && instigator != null && newState == 11)
			{
				hitCount++;
				hitCount %= 11;
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, (byte)hitCount, instigator.GetPlayerRef(), timeStamp);
			}
		}

		public bool IsStateValid(byte state)
		{
			return state <= 11;
		}

		private void PlayHitEffects()
		{
			if (hitSoundbank != null)
			{
				hitSoundbank.Play();
			}
			if (hitAnimation != null && hitAnimation.clip != null)
			{
				hitAnimation.Play();
			}
			if (scoreText != null)
			{
				scoreText.text = hitCount.ToString("D2");
			}
		}

		public void FunctionalPieceUpdate()
		{
		}

		public float GetInteractionDistace()
		{
			return 20f;
		}
	}
	public class BuilderReplicatedTriggerEnter : MonoBehaviour, IBuilderPieceComponent, IBuilderPieceFunctional
	{
		private enum FunctionalState
		{
			Idle,
			TriggerEntered
		}

		[SerializeField]
		protected BuilderPiece myPiece;

		[Tooltip("How long in seconds to wait between trigger events")]
		[SerializeField]
		protected float triggerCooldown = 0.5f;

		[SerializeField]
		private BuilderSmallHandTrigger[] handTriggers;

		[SerializeField]
		private BuilderSmallMonkeTrigger[] bodyTriggers;

		[Tooltip("Optional Animation to play when triggered")]
		[SerializeField]
		private Animation animationOnTrigger;

		[Tooltip("Optional Sound to play when triggered")]
		[SerializeField]
		private SoundBankPlayer activateSoundBank;

		[Tooltip("Knockback the triggering player?")]
		[SerializeField]
		private bool knockbackOnTriggerEnter;

		[SerializeField]
		private float knockbackVelocity;

		[Tooltip("uses Forward of the transform provided")]
		[SerializeField]
		private Transform knockbackDirection;

		private List<Collider> colliders = new List<Collider>(5);

		private bool isPieceActive;

		private float lastTriggerTime;

		private FunctionalState currentState;

		public UnityEvent OnTriggered;

		private void Awake()
		{
			colliders.Clear();
			BuilderSmallHandTrigger[] array = handTriggers;
			foreach (BuilderSmallHandTrigger obj in array)
			{
				obj.TriggeredEvent.AddListener(OnHandTriggerEntered);
				Collider component = obj.GetComponent<Collider>();
				if (component != null)
				{
					colliders.Add(component);
				}
			}
			BuilderSmallMonkeTrigger[] array2 = bodyTriggers;
			foreach (BuilderSmallMonkeTrigger obj2 in array2)
			{
				obj2.onPlayerEnteredTrigger += OnBodyTriggerEntered;
				Collider component2 = obj2.GetComponent<Collider>();
				if (component2 != null)
				{
					colliders.Add(component2);
				}
			}
		}

		private void OnDestroy()
		{
			BuilderSmallHandTrigger[] array = handTriggers;
			for (int i = 0; i < array.Length; i++)
			{
				array[i].TriggeredEvent.RemoveListener(OnHandTriggerEntered);
			}
			BuilderSmallMonkeTrigger[] array2 = bodyTriggers;
			for (int i = 0; i < array2.Length; i++)
			{
				array2[i].onPlayerEnteredTrigger -= OnBodyTriggerEntered;
			}
		}

		private void PlayTriggerEffects(NetPlayer target)
		{
			OnTriggered?.Invoke();
			if (animationOnTrigger != null && animationOnTrigger.clip != null)
			{
				animationOnTrigger.Rewind();
				animationOnTrigger.Play();
			}
			if (activateSoundBank != null)
			{
				activateSoundBank.Play();
			}
			if (!target.IsLocal)
			{
				return;
			}
			VRRig rig = VRRigCache.Instance.localRig.Rig;
			if (rig != null)
			{
				float num = 1.5f * rig.scaleFactor;
				if (!((rig.transform.position - base.transform.position).sqrMagnitude > num * num))
				{
					GTPlayer.Instance.SetMaximumSlipThisFrame();
					GTPlayer.Instance.ApplyKnockback(knockbackDirection.forward, knockbackVelocity * rig.scaleFactor);
					GorillaTagger.Instance.StartVibration(forLeftController: true, GorillaTagger.Instance.tapHapticStrength / 2f, Time.fixedDeltaTime);
					GorillaTagger.Instance.StartVibration(forLeftController: false, GorillaTagger.Instance.tapHapticStrength / 2f, Time.fixedDeltaTime);
				}
			}
		}

		private void OnHandTriggerEntered()
		{
			if (CanTrigger())
			{
				myPiece.GetTable().builderNetworking.RequestFunctionalPieceStateChange(myPiece.pieceId, 1);
			}
		}

		private void OnBodyTriggerEntered(int playerNumber)
		{
			if (NetworkSystem.Instance.IsMasterClient)
			{
				NetPlayer player = NetworkSystem.Instance.GetPlayer(playerNumber);
				if (player != null && CanTrigger())
				{
					myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, 1, player.GetPlayerRef(), NetworkSystem.Instance.ServerTimestamp);
				}
			}
		}

		private bool CanTrigger()
		{
			if (isPieceActive && currentState == FunctionalState.Idle)
			{
				return Time.time > lastTriggerTime + triggerCooldown;
			}
			return false;
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			currentState = FunctionalState.Idle;
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
			isPieceActive = true;
			foreach (Collider collider in colliders)
			{
				collider.enabled = true;
			}
		}

		public void OnPieceDeactivate()
		{
			isPieceActive = false;
			if (currentState == FunctionalState.TriggerEntered)
			{
				myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				myPiece.GetTable().UnregisterFunctionalPiece(this);
			}
			foreach (Collider collider in colliders)
			{
				collider.enabled = false;
			}
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (IsStateValid(newState))
			{
				if (newState == 1 && currentState != FunctionalState.TriggerEntered)
				{
					lastTriggerTime = Time.time;
					myPiece.GetTable().RegisterFunctionalPiece(this);
					PlayTriggerEffects(instigator);
				}
				currentState = (FunctionalState)newState;
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (NetworkSystem.Instance.IsMasterClient && IsStateValid(newState) && instigator != null && newState == 1 && CanTrigger())
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, newState, instigator.GetPlayerRef(), timeStamp);
			}
		}

		public bool IsStateValid(byte state)
		{
			return state <= 1;
		}

		public void FunctionalPieceUpdate()
		{
			if (lastTriggerTime + triggerCooldown < Time.time)
			{
				myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				myPiece.GetTable().UnregisterFunctionalPiece(this);
			}
		}
	}
	public class BuilderScaleAudioRadius : MonoBehaviour
	{
		[Tooltip("Scale particles on enable using lossy scale")]
		[SerializeField]
		private bool useLossyScaleOnEnable;

		[Tooltip("Play sound after scaling")]
		[SerializeField]
		private bool autoPlay;

		[SerializeField]
		private AudioSource audioSource;

		[FormerlySerializedAs("soundBankToPlay")]
		[SerializeField]
		private SoundBankPlayer autoPlaySoundBank;

		private float minDist;

		private float maxDist = 1f;

		private AnimationCurve customCurve;

		private AnimationCurve scaledCurve = new AnimationCurve();

		private float scale = 1f;

		private bool shouldRevert;

		private bool setScaleNextFrame;

		private int enableFrame;

		private void OnEnable()
		{
			if (useLossyScaleOnEnable)
			{
				setScaleNextFrame = true;
				enableFrame = Time.frameCount;
			}
		}

		private void OnDisable()
		{
			if (useLossyScaleOnEnable)
			{
				RevertScale();
			}
		}

		private void LateUpdate()
		{
			if (setScaleNextFrame && Time.frameCount > enableFrame)
			{
				if (useLossyScaleOnEnable)
				{
					SetScale(base.transform.lossyScale.x);
				}
				setScaleNextFrame = false;
			}
		}

		private void PlaySound()
		{
			if (autoPlaySoundBank != null)
			{
				autoPlaySoundBank.Play();
			}
			else if (audioSource.clip != null)
			{
				audioSource.Play();
			}
		}

		public void SetScale(float inScale)
		{
			if (Mathf.Approximately(inScale, scale))
			{
				if (autoPlay)
				{
					PlaySound();
				}
				return;
			}
			scale = inScale;
			RevertScale();
			if (Mathf.Approximately(scale, 1f))
			{
				if (autoPlay)
				{
					PlaySound();
				}
				return;
			}
			switch (audioSource.rolloffMode)
			{
			case AudioRolloffMode.Logarithmic:
			case AudioRolloffMode.Linear:
				minDist = audioSource.minDistance;
				maxDist = audioSource.maxDistance;
				audioSource.maxDistance *= scale;
				audioSource.minDistance *= scale;
				break;
			case AudioRolloffMode.Custom:
				maxDist = audioSource.maxDistance;
				audioSource.maxDistance *= scale;
				break;
			}
			if (autoPlay)
			{
				PlaySound();
			}
			shouldRevert = true;
		}

		public void RevertScale()
		{
			if (shouldRevert)
			{
				switch (audioSource.rolloffMode)
				{
				case AudioRolloffMode.Logarithmic:
				case AudioRolloffMode.Linear:
					audioSource.minDistance = minDist;
					audioSource.maxDistance = maxDist;
					break;
				case AudioRolloffMode.Custom:
					audioSource.maxDistance = maxDist;
					break;
				}
				scale = 1f;
				shouldRevert = false;
			}
		}
	}
	public class BuilderScaleParticles : MonoBehaviour
	{
		private float scale = 1f;

		[Tooltip("Scale particles on enable using lossy scale")]
		[SerializeField]
		private bool useLossyScale;

		[Tooltip("Play particles after scaling")]
		[SerializeField]
		private bool autoPlay;

		[SerializeField]
		private ParticleSystem system;

		[SerializeField]
		private bool scaleShape;

		[SerializeField]
		private bool scaleVelocityLifetime;

		[SerializeField]
		private bool scaleVelocityLimitLifetime;

		[SerializeField]
		private bool scaleForceOverLife;

		private float gravityMod = 1f;

		private ParticleSystem.MinMaxCurve speedCurveCache;

		private ParticleSystem.MinMaxCurve sizeCurveCache;

		private ParticleSystem.MinMaxCurve sizeCurveXCache;

		private ParticleSystem.MinMaxCurve sizeCurveYCache;

		private ParticleSystem.MinMaxCurve sizeCurveZCache;

		private ParticleSystem.MinMaxCurve forceX;

		private ParticleSystem.MinMaxCurve forceY;

		private ParticleSystem.MinMaxCurve forceZ;

		private UnityEngine.Vector3 shapeScale = UnityEngine.Vector3.one;

		private ParticleSystem.MinMaxCurve lifetimeVelocityX;

		private ParticleSystem.MinMaxCurve lifetimeVelocityY;

		private ParticleSystem.MinMaxCurve lifetimeVelocityZ;

		private float limitMultiplier = 1f;

		private bool shouldRevert;

		private bool setScaleNextFrame;

		private int enableFrame;

		private void OnEnable()
		{
			if (useLossyScale)
			{
				setScaleNextFrame = true;
				enableFrame = Time.frameCount;
			}
		}

		private void LateUpdate()
		{
			if (setScaleNextFrame && Time.frameCount > enableFrame)
			{
				if (useLossyScale)
				{
					SetScale(base.transform.lossyScale.x);
				}
				setScaleNextFrame = false;
			}
		}

		private void OnDisable()
		{
			if (useLossyScale)
			{
				RevertScale();
			}
		}

		public void SetScale(float inScale)
		{
			bool isPlaying = system.isPlaying;
			if (isPlaying)
			{
				system.Stop();
				system.Clear();
			}
			if (Mathf.Approximately(inScale, scale))
			{
				if (autoPlay || isPlaying)
				{
					system.Play(withChildren: true);
				}
				return;
			}
			scale = inScale;
			RevertScale();
			if (Mathf.Approximately(scale, 1f))
			{
				if (autoPlay || isPlaying)
				{
					system.Play(withChildren: true);
				}
				return;
			}
			ParticleSystem.MainModule main = system.main;
			gravityMod = main.gravityModifierMultiplier;
			main.gravityModifierMultiplier = gravityMod * scale;
			if (main.startSize3D)
			{
				ParticleSystem.MinMaxCurve curve = main.startSizeX;
				sizeCurveXCache = main.startSizeX;
				ScaleCurve(ref curve, scale);
				main.startSizeX = curve;
				ParticleSystem.MinMaxCurve curve2 = main.startSizeY;
				sizeCurveYCache = main.startSizeY;
				ScaleCurve(ref curve2, scale);
				main.startSizeY = curve2;
				ParticleSystem.MinMaxCurve curve3 = main.startSizeZ;
				sizeCurveZCache = main.startSizeZ;
				ScaleCurve(ref curve3, scale);
				main.startSizeZ = curve3;
			}
			else
			{
				ParticleSystem.MinMaxCurve curve4 = main.startSize;
				sizeCurveCache = main.startSize;
				ScaleCurve(ref curve4, scale);
				main.startSize = curve4;
			}
			ParticleSystem.MinMaxCurve curve5 = main.startSpeed;
			speedCurveCache = main.startSpeed;
			ScaleCurve(ref curve5, scale);
			main.startSpeed = curve5;
			if (scaleShape)
			{
				ParticleSystem.ShapeModule shape = system.shape;
				shapeScale = shape.scale;
				shape.scale = shapeScale * scale;
			}
			if (scaleVelocityLifetime)
			{
				ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = system.velocityOverLifetime;
				lifetimeVelocityX = velocityOverLifetime.x;
				lifetimeVelocityY = velocityOverLifetime.y;
				lifetimeVelocityZ = velocityOverLifetime.z;
				ParticleSystem.MinMaxCurve curve6 = velocityOverLifetime.x;
				ScaleCurve(ref curve6, scale);
				velocityOverLifetime.x = curve6;
				curve6 = velocityOverLifetime.y;
				ScaleCurve(ref curve6, scale);
				velocityOverLifetime.y = curve6;
				curve6 = velocityOverLifetime.z;
				ScaleCurve(ref curve6, scale);
				velocityOverLifetime.z = curve6;
			}
			if (scaleVelocityLimitLifetime)
			{
				ParticleSystem.LimitVelocityOverLifetimeModule limitVelocityOverLifetime = system.limitVelocityOverLifetime;
				limitMultiplier = limitVelocityOverLifetime.limitMultiplier;
				limitVelocityOverLifetime.limitMultiplier = limitMultiplier * scale;
			}
			if (scaleForceOverLife)
			{
				ParticleSystem.ForceOverLifetimeModule forceOverLifetime = system.forceOverLifetime;
				forceX = forceOverLifetime.x;
				forceY = forceOverLifetime.y;
				forceZ = forceOverLifetime.z;
				ParticleSystem.MinMaxCurve curve7 = forceOverLifetime.x;
				ScaleCurve(ref curve7, scale);
				forceOverLifetime.x = curve7;
				curve7 = forceOverLifetime.y;
				ScaleCurve(ref curve7, scale);
				forceOverLifetime.y = curve7;
				curve7 = forceOverLifetime.z;
				ScaleCurve(ref curve7, scale);
				forceOverLifetime.z = curve7;
			}
			if (autoPlay || isPlaying)
			{
				system.Play(withChildren: true);
			}
			shouldRevert = true;
		}

		private void ScaleCurve(ref ParticleSystem.MinMaxCurve curve, float scale)
		{
			switch (curve.mode)
			{
			case ParticleSystemCurveMode.Constant:
				curve.constant *= scale;
				break;
			case ParticleSystemCurveMode.Curve:
			case ParticleSystemCurveMode.TwoCurves:
				curve.curveMultiplier *= scale;
				break;
			case ParticleSystemCurveMode.TwoConstants:
				curve.constantMin *= scale;
				curve.constantMax *= scale;
				break;
			}
		}

		public void RevertScale()
		{
			if (shouldRevert)
			{
				ParticleSystem.MainModule main = system.main;
				main.gravityModifierMultiplier = gravityMod;
				main.startSpeed = speedCurveCache;
				if (main.startSize3D)
				{
					main.startSizeX = sizeCurveXCache;
					main.startSizeY = sizeCurveYCache;
					main.startSizeZ = sizeCurveZCache;
				}
				else
				{
					main.startSize = sizeCurveCache;
				}
				if (scaleShape)
				{
					ParticleSystem.ShapeModule shape = system.shape;
					shape.scale = shapeScale;
				}
				if (scaleVelocityLifetime)
				{
					ParticleSystem.VelocityOverLifetimeModule velocityOverLifetime = system.velocityOverLifetime;
					velocityOverLifetime.x = lifetimeVelocityX;
					velocityOverLifetime.y = lifetimeVelocityY;
					velocityOverLifetime.z = lifetimeVelocityZ;
				}
				if (scaleVelocityLimitLifetime)
				{
					ParticleSystem.LimitVelocityOverLifetimeModule limitVelocityOverLifetime = system.limitVelocityOverLifetime;
					limitVelocityOverLifetime.limitMultiplier = limitMultiplier;
				}
				if (scaleForceOverLife)
				{
					ParticleSystem.ForceOverLifetimeModule forceOverLifetime = system.forceOverLifetime;
					forceOverLifetime.x = forceX;
					forceOverLifetime.y = forceY;
					forceOverLifetime.z = forceZ;
				}
				scale = 1f;
				shouldRevert = false;
			}
		}
	}
