		{
			if (cowboyHitSound != null)
			{
				cowboyHitSound.Play();
			}
			if (cowboyHitAnimation != null && cowboyHitAnimation.clip != null)
			{
				cowboyHitAnimation.Play();
			}
		}

		private void WheelHitEffects()
		{
			if (wheelHitSound != null)
			{
				wheelHitSound.Play();
			}
			if (wheelHitAnimation != null && wheelHitAnimation.clip != null)
			{
				wheelHitAnimation.Play();
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			currentState = FunctionalState.Idle;
			cowboyInitLocalPos = cowboyTransform.transform.localPosition;
			cowboyInitLocalRotation = cowboyTransform.transform.localRotation;
			wheelInitLocalRot = wheelTransform.transform.localRotation;
			distance = UnityEngine.Vector3.Distance(cowboyStart.position, cowboyEnd.position);
			cowboyCycleDuration = distance / (cowboyVelocity * myPiece.GetScale());
			wheelCycleDuration = 1f / wheelVelocity;
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
			if (!activated && myPiece.state == BuilderPiece.State.AttachedAndPlaced)
			{
				myPiece.GetTable().RegisterFunctionalPieceFixedUpdate(this);
				activated = true;
			}
		}

		public void OnPieceActivate()
		{
			cowboyTransform.SetLocalPositionAndRotation(cowboyInitLocalPos, cowboyInitLocalRotation);
			wheelTransform.SetLocalPositionAndRotation(wheelTransform.localPosition, wheelInitLocalRot);
			if (!activated)
			{
				myPiece.GetTable().RegisterFunctionalPieceFixedUpdate(this);
				activated = true;
			}
		}

		public void OnPieceDeactivate()
		{
			if (currentState != FunctionalState.Idle)
			{
				myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				myPiece.GetTable().UnregisterFunctionalPiece(this);
			}
			if (activated)
			{
				myPiece.GetTable().UnregisterFunctionalPieceFixedUpdate(this);
				activated = false;
			}
			cowboyTransform.SetLocalPositionAndRotation(cowboyInitLocalPos, cowboyInitLocalRotation);
			wheelTransform.SetLocalPositionAndRotation(wheelTransform.localPosition, wheelInitLocalRot);
		}

		public void OnStateChanged(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (instigator != null && IsStateValid(newState))
			{
				if (newState == 1 && currentState == FunctionalState.Idle)
				{
					lastHitTime = Time.time;
					WheelHitEffects();
					myPiece.GetTable().RegisterFunctionalPiece(this);
				}
				else if (newState == 2 && currentState == FunctionalState.Idle)
				{
					lastHitTime = Time.time;
					CowboyHitEffects();
					myPiece.GetTable().RegisterFunctionalPiece(this);
				}
				currentState = (FunctionalState)newState;
			}
		}

		public void OnStateRequest(byte newState, NetPlayer instigator, int timeStamp)
		{
			if (NetworkSystem.Instance.IsMasterClient && IsStateValid(newState) && instigator != null && lastHitTime + (double)hitCooldown < (double)Time.time)
			{
				myPiece.GetTable().builderNetworking.FunctionalPieceStateChangeMaster(myPiece.pieceId, newState, instigator.GetPlayerRef(), timeStamp);
			}
		}

		public bool IsStateValid(byte state)
		{
			return state <= 2;
		}

		public void FunctionalPieceUpdate()
		{
			if (lastHitTime + (double)hitCooldown < (double)Time.time)
			{
				myPiece.SetFunctionalPieceState(0, NetworkSystem.Instance.LocalPlayer, NetworkSystem.Instance.ServerTimestamp);
				myPiece.GetTable().UnregisterFunctionalPiece(this);
			}
		}

		public void FunctionalPieceFixedUpdate()
		{
			if (myPiece.state == BuilderPiece.State.AttachedAndPlaced)
			{
				currT = CowboyCycleCompletionPercent();
				currForward = IsEvenCycle();
				float time = (currForward ? currT : (1f - currT));
				float num = WheelCycleCompletionPercent();
				float t = cowboyCurve.Evaluate(time);
				cowboyTransform.localPosition = UnityEngine.Vector3.Lerp(cowboyStart.localPosition, cowboyEnd.localPosition, t);
				UnityEngine.Quaternion localRotation = UnityEngine.Quaternion.AngleAxis(num * 360f, UnityEngine.Vector3.right);
				wheelTransform.localRotation = localRotation;
			}
		}

		private long NetworkTimeMs()
		{
			if (PhotonNetwork.InRoom)
			{
				return (uint)(PhotonNetwork.ServerTimestamp + int.MinValue);
			}
			return (long)(Time.time * 1000f);
		}

		private long CowboyCycleLengthMs()
		{
			return (long)(cowboyCycleDuration * 1000f);
		}

		private long WheelCycleLengthMs()
		{
			return (long)(wheelCycleDuration * 1000f);
		}

		public double CowboyPlatformTime()
		{
			long num = NetworkTimeMs();
			long num2 = CowboyCycleLengthMs();
			return (double)(num - num / num2 * num2) / 1000.0;
		}

		public double WheelPlatformTime()
		{
			long num = NetworkTimeMs();
			long num2 = WheelCycleLengthMs();
			return (double)(num - num / num2 * num2) / 1000.0;
		}

		public int CowboyCycleCount()
		{
			return (int)(NetworkTimeMs() / CowboyCycleLengthMs());
		}

		public float CowboyCycleCompletionPercent()
		{
			return Mathf.Clamp((float)(CowboyPlatformTime() / (double)cowboyCycleDuration), 0f, 1f);
		}

		public float WheelCycleCompletionPercent()
		{
			return Mathf.Clamp((float)(WheelPlatformTime() / (double)wheelCycleDuration), 0f, 1f);
		}

		public bool IsEvenCycle()
		{
			return CowboyCycleCount() % 2 == 0;
		}
	}
	public class BuilderSmallHandTrigger : MonoBehaviour
	{
		[Tooltip("Optional timeline to play to animate the thing getting activated, play sound, particles, etc...")]
		public PlayableDirector timeline;

		[Tooltip("Optional animation to play")]
		public Animation animation;

		private int lastTriggeredFrame = -1;

		public bool onlySmallHands;

		[SerializeField]
		protected bool requireMinimumVelocity;

		[SerializeField]
		protected float minimumVelocityMagnitude = 0.1f;

		private bool hasCheckedZone;

		private bool ignoreScale;

		internal UnityEvent TriggeredEvent = new UnityEvent();

		[SerializeField]
		private BuilderPiece myPiece;

		public bool TriggeredThisFrame => lastTriggeredFrame == Time.frameCount;

		private void OnTriggerEnter(Collider other)
		{
			if (!base.enabled)
			{
				return;
			}
			GorillaTriggerColliderHandIndicator componentInParent = other.GetComponentInParent<GorillaTriggerColliderHandIndicator>();
			if (componentInParent == null)
			{
				return;
			}
			if (!hasCheckedZone)
			{
				if (BuilderTable.TryGetBuilderTableForZone(VRRigCache.Instance.localRig.Rig.zoneEntity.currentZone, out var table))
				{
					ignoreScale = !table.isTableMutable;
				}
				hasCheckedZone = true;
			}
			if (onlySmallHands && !ignoreScale && (double)VRRigCache.Instance.localRig.Rig.scaleFactor > 0.99)
			{
				return;
			}
			if (requireMinimumVelocity)
			{
				float num = minimumVelocityMagnitude * GorillaTagger.Instance.offlineVRRig.scaleFactor;
				if (GTPlayer.Instance.GetHandVelocityTracker(componentInParent.isLeftHand).GetAverageVelocity(worldSpace: true, 0.1f).sqrMagnitude < num * num)
				{
					return;
				}
			}
			GorillaTagger.Instance.StartVibration(componentInParent.isLeftHand, GorillaTagger.Instance.tapHapticStrength, GorillaTagger.Instance.tapHapticDuration * 1.5f);
			lastTriggeredFrame = Time.frameCount;
			TriggeredEvent?.Invoke();
			if (timeline != null && (timeline.time == 0.0 || timeline.time >= timeline.duration))
			{
				timeline.Play();
			}
			if (animation != null && animation.clip != null)
			{
				animation.Play();
			}
		}
	}
	public class BuilderSmallMonkeTrigger : MonoBehaviour
	{
		private int lastTriggeredFrame = -1;

		private List<Collider> overlappingColliders = new List<Collider>(20);

		private bool hasCheckedZone;

		private bool ignoreScale;

		public int overlapCount => overlappingColliders.Count;

		public bool TriggeredThisFrame => lastTriggeredFrame == Time.frameCount;

		public event Action<int> onPlayerEnteredTrigger;

		public event Action onTriggerFirstEntered;

		public event Action onTriggerLastExited;

		public void ValidateOverlappingColliders()
		{
			for (int num = overlappingColliders.Count - 1; num >= 0; num--)
			{
				if (overlappingColliders[num] == null || !overlappingColliders[num].gameObject.activeInHierarchy || !overlappingColliders[num].enabled)
				{
					overlappingColliders.RemoveAt(num);
				}
				else
				{
					VRRig vRRig = overlappingColliders[num].attachedRigidbody.gameObject.GetComponent<VRRig>();
					if (vRRig == null)
					{
						if (GTPlayer.Instance.bodyCollider == overlappingColliders[num] || GTPlayer.Instance.headCollider == overlappingColliders[num])
						{
							vRRig = GorillaTagger.Instance.offlineVRRig;
						}
						else
						{
							overlappingColliders.RemoveAt(num);
						}
					}
					if (!ignoreScale && vRRig != null && (double)vRRig.scaleFactor > 0.99)
					{
						overlappingColliders.RemoveAt(num);
					}
				}
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			if (other.attachedRigidbody == null)
			{
				return;
			}
			VRRig vRRig = other.attachedRigidbody.gameObject.GetComponent<VRRig>();
			if (vRRig == null)
			{
				if (!(GTPlayer.Instance.bodyCollider == other) && !(GTPlayer.Instance.headCollider == other))
				{
					return;
				}
				vRRig = GorillaTagger.Instance.offlineVRRig;
			}
			if (!hasCheckedZone)
			{
				if (BuilderTable.TryGetBuilderTableForZone(vRRig.zoneEntity.currentZone, out var table))
				{
					ignoreScale = !table.isTableMutable;
				}
				hasCheckedZone = true;
			}
			if (ignoreScale || !((double)vRRig.scaleFactor > 0.99))
			{
				if (vRRig != null)
				{
					this.onPlayerEnteredTrigger?.Invoke(vRRig.OwningNetPlayer.ActorNumber);
				}
				bool num = overlappingColliders.Count == 0;
				if (!overlappingColliders.Contains(other))
				{
					overlappingColliders.Add(other);
				}
				lastTriggeredFrame = Time.frameCount;
				if (num)
				{
					this.onTriggerFirstEntered?.Invoke();
				}
			}
		}

		private void OnTriggerExit(Collider other)
		{
			if (overlappingColliders.Remove(other) && overlappingColliders.Count == 0)
			{
				this.onTriggerLastExited?.Invoke();
			}
		}
	}
	public class BuilderSpeedBooster : MonoBehaviour
	{
		[SerializeField]
		public bool scaleWithSize = true;

		[SerializeField]
		private float accel;

		[SerializeField]
		private float maxDepth = -1f;

		[SerializeField]
		private float maxSpeed;

		[SerializeField]
		private bool disableGrip;

		[SerializeField]
		private bool dampenLateralVelocity = true;

		[SerializeField]
		private float dampenXVelPerc;

		[SerializeField]
		private float dampenZVelPerc;

		[SerializeField]
		private bool applyPullToCenterAcceleration = true;

		[SerializeField]
		private float pullToCenterAccel;

		[SerializeField]
		private float pullToCenterMaxSpeed;

		[SerializeField]
		private float pullTOCenterMinDistance = 0.1f;

		[SerializeField]
		private float addedWorldUpVelocity = 10f;

		[SerializeField]
		private float maxBoostDuration = 2f;

		private bool boosting;

		private double enterTime;

		private Collider volume;

		public AudioClip exitClip;

		public AudioSource audioSource;

		public MeshRenderer windRenderer;

		private UnityEngine.Vector3 enterPos;

		private bool positiveForce = true;

		private bool ignoreMonkeScale;

		private bool hasCheckedZone;

		private void Awake()
		{
			volume = GetComponent<Collider>();
			windRenderer.enabled = false;
			boosting = false;
		}

		private void LateUpdate()
		{
			if ((bool)audioSource && audioSource != null && !audioSource.isPlaying && audioSource.enabled)
			{
				audioSource.enabled = false;
			}
		}

		private bool TriggerFilter(Collider other, out Rigidbody rb, out Transform xf)
		{
			rb = null;
			xf = null;
			if (other.gameObject == GorillaTagger.Instance.headCollider.gameObject)
			{
				rb = GorillaTagger.Instance.GetComponent<Rigidbody>();
				xf = GorillaTagger.Instance.headCollider.GetComponent<Transform>();
			}
			if (rb != null)
			{
				return xf != null;
			}
			return false;
		}

		private void CheckTableZone()
		{
			if (!hasCheckedZone)
			{
				if (BuilderTable.TryGetBuilderTableForZone(GorillaTagger.Instance.offlineVRRig.zoneEntity.currentZone, out var table))
				{
					ignoreMonkeScale = !table.isTableMutable;
				}
				hasCheckedZone = true;
			}
		}

		public void OnTriggerEnter(Collider other)
		{
			Rigidbody rb = null;
			Transform xf = null;
			if (!TriggerFilter(other, out rb, out xf))
			{
				return;
			}
			CheckTableZone();
			if (ignoreMonkeScale || !((double)GorillaTagger.Instance.offlineVRRig.scaleFactor > 0.99))
			{
				positiveForce = UnityEngine.Vector3.Dot(base.transform.up, rb.linearVelocity) > 0f;
				if (positiveForce)
				{
					windRenderer.transform.localRotation = UnityEngine.Quaternion.Euler(0f, 0f, -90f);
				}
				else
				{
					windRenderer.transform.localRotation = UnityEngine.Quaternion.Euler(0f, 180f, -90f);
				}
				windRenderer.enabled = true;
				enterPos = xf.position;
				if (!boosting)
				{
					boosting = true;
					enterTime = Time.timeAsDouble;
				}
			}
		}

		public void OnTriggerExit(Collider other)
		{
			Rigidbody rb = null;
			Transform xf = null;
			if (!TriggerFilter(other, out rb, out xf))
			{
				return;
			}
			windRenderer.enabled = false;
			CheckTableZone();
			if (ignoreMonkeScale || !((double)GorillaTagger.Instance.offlineVRRig.scaleFactor > 0.99))
			{
				if (boosting && (bool)audioSource)
				{
					audioSource.enabled = true;
					audioSource.Stop();
					audioSource.GTPlayOneShot(exitClip);
				}
				boosting = false;
			}
		}

		public void OnTriggerStay(Collider other)
		{
			if (!boosting)
			{
				return;
			}
			Rigidbody rb = null;
			Transform xf = null;
			if (!TriggerFilter(other, out rb, out xf))
			{
				return;
			}
			if (!ignoreMonkeScale && (double)GorillaTagger.Instance.offlineVRRig.scaleFactor > 0.99)
			{
				OnTriggerExit(other);
				return;
			}
			if (Time.timeAsDouble > enterTime + (double)maxBoostDuration)
			{
				OnTriggerExit(other);
				return;
			}
			if (disableGrip)
			{
				GTPlayer.Instance.SetMaximumSlipThisFrame();
			}
			SizeManager sizeManager = null;
			if (scaleWithSize)
			{
				sizeManager = rb.GetComponent<SizeManager>();
			}
			UnityEngine.Vector3 linearVelocity = rb.linearVelocity;
			if (scaleWithSize && (bool)sizeManager)
			{
				linearVelocity /= sizeManager.currentScale;
			}
			UnityEngine.Vector3 vector = UnityEngine.Vector3.Dot(xf.position - base.transform.position, base.transform.up) * base.transform.up;
			UnityEngine.Vector3 vector2 = base.transform.position + vector - xf.position;
			float num = vector2.magnitude + 0.0001f;
			UnityEngine.Vector3 vector3 = vector2 / num;
			float num2 = UnityEngine.Vector3.Dot(linearVelocity, vector3);
			float num3 = accel;
			if (maxDepth > -1f)
			{
				float num4 = UnityEngine.Vector3.Dot(xf.position - enterPos, vector3);
				float num5 = maxDepth - num4;
				float b = 0f;
				if (num5 > 0.0001f)
				{
					b = num2 * num2 / num5;
				}
				num3 = Mathf.Max(accel, b);
			}
			float deltaTime = Time.deltaTime;
			UnityEngine.Vector3 vector4 = base.transform.up * num3 * deltaTime;
			if (!positiveForce)
			{
				vector4 *= -1f;
			}
			linearVelocity += vector4;
			if ((double)UnityEngine.Vector3.Dot(vector4, UnityEngine.Vector3.down) <= 0.1)
			{
				linearVelocity += UnityEngine.Vector3.up * addedWorldUpVelocity * deltaTime;
			}
			UnityEngine.Vector3 vector5 = Mathf.Min(UnityEngine.Vector3.Dot(linearVelocity, base.transform.up), maxSpeed) * base.transform.up;
			UnityEngine.Vector3 vector6 = UnityEngine.Vector3.Dot(linearVelocity, base.transform.right) * base.transform.right;
			UnityEngine.Vector3 vector7 = UnityEngine.Vector3.Dot(linearVelocity, base.transform.forward) * base.transform.forward;
			float num6 = 1f;
			float num7 = 1f;
			if (dampenLateralVelocity)
			{
				num6 = 1f - dampenXVelPerc * 0.01f * deltaTime;
				num7 = 1f - dampenZVelPerc * 0.01f * deltaTime;
			}
			linearVelocity = vector5 + num6 * vector6 + num7 * vector7;
			if (applyPullToCenterAcceleration && pullToCenterAccel > 0f && pullToCenterMaxSpeed > 0f)
			{
				linearVelocity -= num2 * vector3;
				if (num > pullTOCenterMinDistance)
				{
					num2 += pullToCenterAccel * deltaTime;
					float b2 = Mathf.Min(pullToCenterMaxSpeed, num / deltaTime);
					num2 = Mathf.Min(num2, b2);
				}
				else
				{
					num2 = 0f;
				}
				linearVelocity += num2 * vector3;
				if (linearVelocity.magnitude > 0.0001f)
				{
					UnityEngine.Vector3 vector8 = UnityEngine.Vector3.Cross(base.transform.up, vector3);
					float magnitude = vector8.magnitude;
					if (magnitude > 0.0001f)
					{
						vector8 /= magnitude;
						num2 = UnityEngine.Vector3.Dot(linearVelocity, vector8);
						linearVelocity -= num2 * vector8;
						num2 -= pullToCenterAccel * deltaTime;
						num2 = Mathf.Max(0f, num2);
						linearVelocity += num2 * vector8;
					}
				}
			}
			if (scaleWithSize && (bool)sizeManager)
			{
				linearVelocity *= sizeManager.currentScale;
			}
			rb.linearVelocity = linearVelocity;
		}

		public void OnDrawGizmosSelected()
		{
			GetComponents<Collider>();
			Gizmos.color = Color.magenta;
			Gizmos.matrix = base.transform.localToWorldMatrix;
			Gizmos.DrawWireCube(UnityEngine.Vector3.zero, new UnityEngine.Vector3(pullTOCenterMinDistance / base.transform.lossyScale.x, 1f, pullTOCenterMinDistance / base.transform.lossyScale.z));
		}
	}
	public class BuilderTrafficLight : MonoBehaviour, IBuilderPieceComponent
	{
		private enum LightState
		{
			Red,
			Yellow,
			Green,
			Off
		}

		[SerializeField]
		private BuilderPiece piece;

		[SerializeField]
		private MeshRenderer redLight;

		[SerializeField]
		private MeshRenderer yellowLight;

		[SerializeField]
		private MeshRenderer greenLight;

		[SerializeField]
		private float cycleDuration = 10f;

		[SerializeField]
		private float startPercentageOffset = 0.5f;

		[SerializeField]
		private Color redOn = Color.red;

		[SerializeField]
		private Color redOff = Color.gray;

		[SerializeField]
		private Color yellowOn = Color.yellow;

		[SerializeField]
		private Color yellowOff = Color.gray;

		[SerializeField]
		private Color greenOn = Color.green;

		[SerializeField]
		private Color greenOff = Color.gray;

		private MaterialPropertyBlock materialProps;

		[SerializeField]
		private AnimationCurve stateCurve;

		private LightState lightState = LightState.Off;

		private void Start()
		{
			materialProps = new MaterialPropertyBlock();
		}

		private void SetState(LightState state)
		{
			lightState = state;
			if (materialProps == null)
			{
				materialProps = new MaterialPropertyBlock();
			}
			Color value = yellowOff;
			Color value2 = redOff;
			Color value3 = greenOff;
			switch (state)
			{
			case LightState.Red:
				value2 = redOn;
				break;
			case LightState.Yellow:
				value = yellowOn;
				break;
			case LightState.Green:
				value3 = greenOn;
				break;
			}
			redLight.GetPropertyBlock(materialProps);
			materialProps.SetColor(ShaderProps._BaseColor, value2);
			redLight.SetPropertyBlock(materialProps);
			materialProps.SetColor(ShaderProps._BaseColor, value);
			yellowLight.SetPropertyBlock(materialProps);
			materialProps.SetColor(ShaderProps._BaseColor, value3);
			greenLight.SetPropertyBlock(materialProps);
		}

		private void Update()
		{
			if (!(piece == null) && piece.state != BuilderPiece.State.AttachedAndPlaced)
			{
				return;
			}
			float num = Time.time;
			if (PhotonNetwork.InRoom)
			{
				uint num2 = (num2 = (uint)PhotonNetwork.ServerTimestamp);
				if (piece != null)
				{
					num2 = (uint)(PhotonNetwork.ServerTimestamp - piece.activatedTimeStamp);
				}
				num = (float)num2 / 1000f;
			}
			float num3 = num % cycleDuration / cycleDuration;
			num3 = (num3 + startPercentageOffset) % 1f;
			int num4 = (int)stateCurve.Evaluate(num3);
			if (num4 != (int)lightState)
			{
				SetState((LightState)num4);
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			SetState(LightState.Off);
		}

		public void OnPieceDestroy()
		{
		}

		public void OnPiecePlacementDeserialized()
		{
		}

		public void OnPieceActivate()
		{
		}

		public void OnPieceDeactivate()
		{
			SetState(LightState.Off);
		}
	}
	public class KnockbackTrigger : MonoBehaviour
	{
		[SerializeField]
		private BoxCollider triggerVolume;

		[SerializeField]
		private float knockbackVelocity;

		[SerializeField]
		private UnityEngine.Vector3 localAxis;

		[SerializeField]
