			{
				value.publishTime = time.ToBinary();
				localPublishData[slotID] = value;
				return;
			}
			LocalPublishInfo value2 = new LocalPublishInfo
			{
				mapID = null,
				publishTime = time.ToBinary()
			};
			localPublishData.Add(slotID, value2);
