					bool success = !text.IsNullOrEmpty() && IsMapIDValid(text);
					callback?.Invoke(success, data.userdataMetadataKey, text, request.responseCode);
				}
				catch (Exception ex)
				{
					GTDev.LogError("SharedBlocksManager PostPublishMapRequest " + ex.Message);
