					publishRequestInProgress = false;
					RequestPublishMap(data.userdataMetadataKey);
				}
				else
				{
					postPublishMapRetryCount = 0;
					callback?.Invoke(success: false, data.userdataMetadataKey, string.Empty, request.responseCode);
