		private bool hasInitialized;

		private static StringBuilder sb = new StringBuilder();

		private VRRig driverRig;

		private static List<VRRig> tempRigs = new List<VRRig>(16);

		private int playersInRoom;

		public SharedBlocksManager.SharedBlocksMap SelectedMap => selectedMap;

		public bool IsTerminalLocked => isTerminalLocked;

		private int playersInLobby => lobbyTrigger.playerIDsCurrentlyTouching.Count;

		public bool IsDriver => localState.driverID == NetworkSystem.Instance.LocalPlayer.ActorNumber;

		public int GetDriverID => localState.driverID;

		public BuilderTable GetTable()
		{
			return linkedTable;
		}

		public static string MapIDToDisplayedString(string mapID)
		{
			if (mapID.IsNullOrEmpty())
			{
				return "____-____";
			}
			int num = 4;
			sb.Clear();
			if (mapID.Length > num)
			{
				sb.Append(mapID.Substring(0, num));
				sb.Append("-");
				sb.Append(mapID.Substring(num));
				int repeatCount = 9 - sb.Length;
				sb.Append('_', repeatCount);
			}
			else
			{
				sb.Append(mapID.Substring(0));
				int repeatCount2 = num - sb.Length;
				sb.Append('_', repeatCount2);
				sb.Append("-____");
			}
			return sb.ToString();
		}

		public void Init(BuilderTable table)
		{
			if (!hasInitialized)
			{
				localState = new SharedBlocksTerminalState
				{
					state = TerminalState.NoStatus,
					driverID = -2
				};
				GameEvents.OnSharedBlocksKeyboardButtonPressedEvent.AddListener(PressButton);
				terminalControlButton.onPressButton.AddListener(OnTerminalControlPressed);
				SetTerminalState(TerminalState.NoStatus);
				RefreshActiveScreen();
				linkedTable = table;
				table.linkedTerminal = this;
				linkedTable.OnMapLoaded.AddListener(OnSharedBlocksMapLoaded);
				linkedTable.OnMapLoadFailed.AddListener(OnSharedBlocksMapLoadFailed);
				linkedTable.OnMapCleared.AddListener(OnSharedBlocksMapLoadStart);
				NetworkSystem.Instance.OnMultiplayerStarted += new Action(OnJoinedRoom);
				NetworkSystem.Instance.OnReturnedToSinglePlayer += new Action(OnReturnedToSinglePlayer);
				hasInitialized = true;
			}
		}

		private void Start()
		{
			if (!hasInitialized && BuilderTable.TryGetBuilderTableForZone(tableZone, out var table))
			{
				Init(table);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Could not find builder table for zone " + tableZone);
			}
		}

		private void LateUpdate()
		{
			if (localState.driverID != -2 && !(GorillaComputer.instance == null) && useNametags != GorillaComputer.instance.NametagsEnabled)
			{
				useNametags = GorillaComputer.instance.NametagsEnabled;
				RefreshDriverNickname();
			}
		}

		private void OnDestroy()
		{
			GameEvents.OnSharedBlocksKeyboardButtonPressedEvent.RemoveListener(PressButton);
			if (terminalControlButton != null)
			{
				terminalControlButton.onPressButton.RemoveListener(OnTerminalControlPressed);
			}
			if (NetworkSystem.Instance != null)
			{
				NetworkSystem.Instance.OnMultiplayerStarted -= new Action(OnJoinedRoom);
				NetworkSystem.Instance.OnReturnedToSinglePlayer -= new Action(OnReturnedToSinglePlayer);
			}
			if (linkedTable != null)
			{
				linkedTable.OnMapLoaded.RemoveListener(OnSharedBlocksMapLoaded);
				linkedTable.OnMapLoadFailed.RemoveListener(OnSharedBlocksMapLoadFailed);
				linkedTable.OnMapCleared.RemoveListener(OnSharedBlocksMapLoadStart);
			}
		}

		private void RefreshActiveScreen()
		{
			if (localState.driverID == -2)
			{
				if (currentScreen != noDriverScreen)
				{
					if (currentScreen != null)
					{
						currentScreen.Hide();
					}
					currentScreen = noDriverScreen;
					currentScreen.Show();
				}
				statusMessageText.gameObject.SetActive(value: false);
			}
			else if (currentScreen != searchScreen)
			{
				if (currentScreen != null)
				{
					currentScreen.Hide();
				}
				currentScreen = searchScreen;
				currentScreen.Show();
			}
		}

		private void SetTerminalState(TerminalState state)
		{
			localState.state = state;
			string result = "";
			string text = "";
			if (localState.driverID != -2)
			{
				switch (state)
				{
				case TerminalState.NoStatus:
					statusMessageText.gameObject.SetActive(value: false);
					break;
				case TerminalState.Searching:
					text = "SEARCHING...";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_SEARCH", out result, text))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_STATUS_SEARCH]");
					}
					SetStatusText(result);
					break;
				case TerminalState.Found:
					text = "MAP FOUND. PRESS 'ENTER' TO LOAD";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_MAP_FOUND", out result, text))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_STATUS_MAP_FOUND]");
					}
					SetStatusText(result);
					break;
				case TerminalState.NotFound:
					text = "MAP NOT FOUND";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_MAP_NOT_FOUND", out result, text))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_STATUS_MAP_NOT_FOUND]");
					}
					SetStatusText(result);
					break;
				case TerminalState.Loading:
					text = "LOADING...";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_LOADING", out result, text))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_STATUS_LOADING]");
					}
					SetStatusText(result);
					break;
				case TerminalState.LoadSuccess:
					text = "LOAD SUCCESS";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_LOAD_SUCCESS", out result, text))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_STATUS_LOAD_SUCCESS]");
					}
					SetStatusText(result);
					break;
				case TerminalState.LoadFail:
					text = "LOAD FAILED";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_LOAD_FAILED", out result, text))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_STATUS_LOAD_FAILED]");
					}
					SetStatusText(result);
					break;
				}
			}
			else
			{
				statusMessageText.gameObject.SetActive(value: false);
			}
		}

		public void SelectMapIDAndOpenInfo(string mapID)
		{
			if (!awaitingWebRequest)
			{
				selectedMap = null;
				awaitingWebRequest = true;
				requestedMapID = mapID;
				SetTerminalState(TerminalState.Searching);
				SharedBlocksManager.instance.RequestMapDataFromID(mapID, OnPlayerMapRequestComplete);
			}
		}

		private void OnPlayerMapRequestComplete(SharedBlocksManager.SharedBlocksMap response)
		{
			if (!awaitingWebRequest)
			{
				return;
			}
			awaitingWebRequest = false;
			requestedMapID = null;
			if (IsDriver)
			{
				if (response == null || response.MapID == null)
				{
					SetTerminalState(TerminalState.NotFound);
					return;
				}
				selectedMap = response;
				SetTerminalState(TerminalState.Found);
			}
		}

		private bool CanChangeMapState(bool load, out string disallowedReason)
		{
			disallowedReason = "";
			if (NetworkSystem.Instance.InRoom)
			{
				RefreshLobbyCount();
				if (!AreAllPlayersInLobby())
				{
					disallowedReason = "ALL PLAYERS IN THE ROOM MUST BE INSIDE THE LOBBY BEFORE " + (load ? "" : "UN") + "LOADING A MAP.";
					string text = (load ? "SHARE_BLOCKS_TERMINAL_STATUS_DISALLOWED_LOBBY_LOAD" : "SHARE_BLOCKS_TERMINAL_STATUS_DISALLOWED_LOBBY_UNLOAD");
					if (!LocalisationManager.TryGetKeyForCurrentLocale(text, out var result, disallowedReason))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [" + text + "]");
					}
					disallowedReason = result;
					return false;
				}
				return true;
			}
			disallowedReason = "MUST BE IN A ROOM BEFORE  " + (load ? "" : "UN") + "LOADING A MAP.";
			string text2 = (load ? "SHARE_BLOCKS_TERMINAL_STATUS_DISALLOWED_ROOM_LOAD" : "SHARE_BLOCKS_TERMINAL_STATUS_DISALLOWED_ROOM_UNLOAD");
			if (!LocalisationManager.TryGetKeyForCurrentLocale(text2, out var result2, disallowedReason))
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [" + text2 + "]");
			}
			disallowedReason = result2;
			return false;
		}

		public void SetStatusText(string text)
		{
			statusMessageText.text = text;
			statusMessageText.gameObject.SetActive(value: true);
		}

		private bool IsLocalPlayerInLobby()
		{
			if (!base.isActiveAndEnabled)
			{
				return false;
			}
			if (!lobbyTrigger.playerIDsCurrentlyTouching.Contains(VRRig.LocalRig.creator.UserId))
			{
				return false;
			}
			return true;
		}

		public bool AreAllPlayersInLobby()
		{
			if (!base.isActiveAndEnabled)
			{
				return false;
			}
			return playersInLobby == playersInRoom;
		}

		public string GetLobbyText()
		{
			string defaultResult = "PLAYERS IN ROOM {0}\nPLAYERS IN LOBBY {1}";
			if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_SEARCH_LOBBY_TEXT_FORMAT", out var result, defaultResult))
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for MONKE BLOCKS SCAN KIOSK localization [SHARE_BLOCKS_TERMINAL_SEARCH_LOBBY_TEXT_FORMAT]");
			}
			return string.Format(result, playersInRoom, playersInLobby);
		}

		public void RefreshLobbyCount()
		{
			if (NetworkSystem.Instance != null && NetworkSystem.Instance.InRoom)
			{
				playersInRoom = NetworkSystem.Instance.RoomPlayerCount;
			}
			else
			{
				playersInRoom = 0;
			}
		}

		public void PressButton(SharedBlocksKeyboardBindings buttonPressed)
		{
			if (!IsDriver)
			{
				if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_NOT_CONTROLLER", out var result, "NOT TERMINAL CONTROLLER"))
				{
					UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for SHARE MY BLOCKS TERMINAL localization [SHARE_BLOCKS_TERMINAL_STATUS_NOT_CONTROLLER]");
				}
				SetStatusText(result);
			}
			else
			{
				if (localState.state == TerminalState.Searching || localState.state == TerminalState.Loading)
				{
					return;
				}
				switch (buttonPressed)
				{
				case SharedBlocksKeyboardBindings.up:
					OnUpButtonPressed();
					return;
				case SharedBlocksKeyboardBindings.down:
					OnDownButtonPressed();
					return;
				case SharedBlocksKeyboardBindings.delete:
					OnDeleteButtonPressed();
					return;
				case SharedBlocksKeyboardBindings.enter:
					OnSelectButtonPressed();
					return;
				case SharedBlocksKeyboardBindings.zero:
				case SharedBlocksKeyboardBindings.one:
				case SharedBlocksKeyboardBindings.two:
				case SharedBlocksKeyboardBindings.three:
				case SharedBlocksKeyboardBindings.four:
				case SharedBlocksKeyboardBindings.five:
				case SharedBlocksKeyboardBindings.six:
				case SharedBlocksKeyboardBindings.seven:
				case SharedBlocksKeyboardBindings.eight:
				case SharedBlocksKeyboardBindings.nine:
					OnNumberPressed((int)buttonPressed);
					return;
				}
				if (buttonPressed >= SharedBlocksKeyboardBindings.A && buttonPressed <= SharedBlocksKeyboardBindings.Z)
				{
					OnLetterPressed(buttonPressed.ToString());
				}
			}
		}

		private void OnUpButtonPressed()
		{
			if (currentScreen != null)
			{
				currentScreen.OnUpPressed();
			}
		}

		private void OnDownButtonPressed()
		{
			if (currentScreen != null)
			{
				currentScreen.OnDownPressed();
			}
		}

		private void OnSelectButtonPressed()
		{
			if (localState.state == TerminalState.Found)
			{
				OnLoadMapPressed();
			}
			else if (currentScreen != null)
			{
				currentScreen.OnSelectPressed();
			}
		}

		private void OnDeleteButtonPressed()
		{
			if (localState.state != TerminalState.Loading && localState.state != TerminalState.Searching)
			{
				SetTerminalState(TerminalState.NoStatus);
			}
			if (currentScreen != null)
			{
				currentScreen.OnDeletePressed();
			}
		}

		private void OnBackButtonPressed()
		{
		}

		private void OnNumberPressed(int number)
		{
			if (currentScreen != null)
			{
				currentScreen.OnNumberPressed(number);
			}
		}

		private void OnLetterPressed(string letter)
		{
			if (currentScreen != null)
			{
				currentScreen.OnLetterPressed(letter);
			}
		}

		private void OnTerminalControlPressed()
		{
			if (isTerminalLocked)
			{
				if (IsDriver)
				{
					if (NetworkSystem.Instance.InRoom)
					{
						linkedTable.builderNetworking.RequestBlocksTerminalControl(locked: false);
					}
					else
					{
						SetTerminalDriver(-2);
					}
				}
			}
			else if (NetworkSystem.Instance.InRoom)
			{
				linkedTable.builderNetworking.RequestBlocksTerminalControl(locked: true);
			}
			else
			{
				SetTerminalDriver(NetworkSystem.Instance.LocalPlayer.ActorNumber);
			}
		}

		public void OnLoadMapPressed()
		{
			string disallowedReason;
			if (!IsDriver)
			{
				if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_NOT_CONTROLLER", out var result, "NOT TERMINAL CONTROLLER"))
				{
					UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for SHARE MY BLOCKS TERMINAL localization [SHARE_BLOCKS_TERMINAL_STATUS_NOT_CONTROLLER]");
				}
				SetStatusText(result);
			}
			else if (currentScreen == null || selectedMap == null)
			{
				if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_NO_SELECTION", out var result2, "NO MAP SELECTED"))
				{
					UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for SHARE MY BLOCKS TERMINAL localization [SHARE_BLOCKS_TERMINAL_STATUS_NO_SELECTION]");
				}
				SetStatusText(result2);
			}
			else if (awaitingWebRequest || isLoadingMap)
			{
				if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_IN_PROGRESS", out var _, "BLOCKS LOAD ALREADY IN PROGRESS"))
				{
					UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for SHARE MY BLOCKS TERMINAL localization [SHARE_BLOCKS_TERMINAL_STATUS_IN_PROGRESS]");
				}
				SetStatusText("BLOCKS LOAD ALREADY IN PROGRESS");
			}
			else if (!CanChangeMapState(load: true, out disallowedReason))
			{
				SetStatusText(disallowedReason);
			}
			else
			{
				if (!(linkedTable != null))
				{
					return;
				}
				if (Time.time > lastLoadTime + loadMapCooldown)
				{
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_LOADING", out var _, "LOADING BLOCKS ..."))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for SHARE MY BLOCKS TERMINAL localization [SHARE_BLOCKS_TERMINAL_STATUS_LOADING]");
					}
					SetStatusText("LOADING BLOCKS ...");
					isLoadingMap = true;
					lastLoadTime = Time.time;
					linkedTable.LoadSharedMap(selectedMap);
				}
				else
				{
					int num = Mathf.RoundToInt(lastLoadTime + loadMapCooldown - Time.time);
					string defaultResult = $"PLEASE WAIT {num} SECONDS BEFORE LOADING ANOTHER MAP";
					if (!LocalisationManager.TryGetKeyForCurrentLocale("SHARE_BLOCKS_TERMINAL_STATUS_WAIT", out var result5, defaultResult))
					{
						UnityEngine.Debug.LogError("[LOCALIZATION::BUILDER_SCAN_KIOSK] Failed to get key for SHARE MY BLOCKS TERMINAL localization [SHARE_BLOCKS_TERMINAL_STATUS_LOADING]");
					}
					result5 = result5.Replace("{time}", num.ToString());
					SetStatusText(result5);
				}
			}
		}

		public bool IsPlayerDriver(Player player)
		{
			return player.ActorNumber == localState.driverID;
		}

		public bool ValidateTerminalControlRequest(bool locked, int playerNumber)
		{
			if (locked && playerNumber == -2)
			{
				return false;
			}
			if (localState.driverID == -2)
			{
				return locked;
			}
			return localState.driverID == playerNumber;
		}

		private void OnDriverNameChanged()
		{
			RefreshDriverNickname();
		}

		public void SetTerminalDriver(int playerNum)
		{
			if (playerNum != -2)
			{
				if (localState.driverID != -2 && localState.driverID != playerNum)
				{
					GTDev.LogWarning($"Shared BlocksTerminal SetTerminalDriver cannot set {playerNum} as driver while {localState.driverID} is driver");
					return;
				}
				localState.driverID = playerNum;
				NetPlayer netPlayerByID = NetworkSystem.Instance.GetNetPlayerByID(playerNum);
				if (netPlayerByID != null && VRRigCache.Instance.TryGetVrrig(netPlayerByID, out var playerRig))
				{
					driverRig = playerRig.Rig;
					driverRig.OnPlayerNameVisibleChanged += OnDriverNameChanged;
				}
				isTerminalLocked = true;
				UpdateTerminalButton();
				RefreshActiveScreen();
				searchScreen.SetInputTextEnabled(IsDriver);
				if (IsDriver && awaitingWebRequest)
				{
					SetTerminalState(TerminalState.Searching);
					searchScreen.SetMapCode(requestedMapID);
				}
				else if (isLoadingMap)
				{
					SetTerminalState(TerminalState.Loading);
					searchScreen.SetMapCode(linkedTable.GetPendingMap());
				}
				else
				{
					SetTerminalState(TerminalState.NoStatus);
				}
			}
			else
			{
				if (driverRig != null)
				{
					driverRig.OnPlayerNameVisibleChanged -= OnDriverNameChanged;
					driverRig = null;
				}
				localState.driverID = -2;
				isTerminalLocked = false;
				UpdateTerminalButton();
				SetTerminalState(TerminalState.NoStatus);
				RefreshActiveScreen();
			}
			RefreshDriverNickname();
		}

		private void RefreshDriverNickname()
		{
			StringVariable stringVariable = _currentDriverLoc.StringReference["playerName"] as StringVariable;
			if (localState.driverID == -2)
			{
				currentDriverLabel.gameObject.SetActive(value: false);
				stringVariable.Value = "";
				currentDriverText.text = "";
				currentDriverText.gameObject.SetActive(value: false);
				return;
			}
			bool flag = KIDManager.HasPermissionToUseFeature(EKIDFeatures.Custom_Nametags);
			if (NetworkSystem.Instance.InRoom)
			{
				NetPlayer player = NetworkSystem.Instance.GetPlayer(localState.driverID);
				if (player != null && useNametags && flag)
				{
					RigContainer playerRig;
					if (player.IsLocal)
					{
						stringVariable.Value = player.NickName;
						currentDriverText.text = player.NickName;
					}
					else if (VRRigCache.Instance.TryGetVrrig(player, out playerRig))
					{
						stringVariable.Value = playerRig.Rig.playerNameVisible;
						currentDriverText.text = playerRig.Rig.playerNameVisible;
					}
					else
					{
						stringVariable.Value = player.DefaultName;
						currentDriverText.text = player.DefaultName;
					}
				}
				else
				{
					stringVariable.Value = "";
					currentDriverText.text = "";
				}
			}
			else
			{
				stringVariable.Value = ((useNametags && flag) ? NetworkSystem.Instance.LocalPlayer.NickName : NetworkSystem.Instance.LocalPlayer.DefaultName);
				currentDriverText.text = ((useNametags && flag) ? NetworkSystem.Instance.LocalPlayer.NickName : NetworkSystem.Instance.LocalPlayer.DefaultName);
			}
			currentDriverLabel.gameObject.SetActive(value: true);
		}

		public bool ValidateLoadMapRequest(string mapID, int playerNum)
		{
			if (playerNum != localState.driverID)
			{
				return false;
			}
			if (!AreAllPlayersInLobby())
			{
				return false;
			}
			return SharedBlocksManager.IsMapIDValid(mapID);
		}

		private void OnJoinedRoom()
		{
			cachedLocalPlayerID = NetworkSystem.Instance.LocalPlayer.ActorNumber;
			ResetTerminalControl();
		}

		private void OnReturnedToSinglePlayer()
		{
			if (localState.driverID != cachedLocalPlayerID)
			{
				ResetTerminalControl();
			}
			else
			{
				localState.driverID = NetworkSystem.Instance.LocalPlayer.ActorNumber;
			}
			cachedLocalPlayerID = -1;
		}

		public void ResetTerminalControl()
		{
			localState.driverID = -2;
			isTerminalLocked = false;
			selectedMap = null;
			SetTerminalState(TerminalState.NoStatus);
			RefreshActiveScreen();
			UpdateTerminalButton();
		}

		private void UpdateTerminalButton()
		{
			terminalControlButton.isOn = isTerminalLocked;
			terminalControlButton.UpdateColor();
		}

		private void OnSharedBlocksMapLoaded(string mapID)
		{
			if (!IsDriver)
			{
				searchScreen.SetMapCode(mapID);
			}
			if (SharedBlocksManager.IsMapIDValid(mapID))
			{
				SetTerminalState(TerminalState.LoadSuccess);
			}
			else if (localState.state != TerminalState.LoadFail)
			{
				SetTerminalState(TerminalState.LoadFail);
			}
			isLoadingMap = false;
		}

		private void OnSharedBlocksMapLoadFailed(string message)
		{
			SetTerminalState(TerminalState.LoadFail);
			SetStatusText(message);
			isLoadingMap = false;
		}

		private void OnSharedBlocksMapLoadStart()
		{
			if (!(linkedTable == null) && !IsDriver)
			{
				searchScreen.SetMapCode(linkedTable.GetPendingMap());
				SetTerminalState(TerminalState.Loading);
				isLoadingMap = true;
				lastLoadTime = Time.time;
			}
		}
	}
	public class SharedBlocksVotingStation : MonoBehaviour
	{
		public const int VOTING_STATUS_INDEX_SUCCESS = 0;

		public const int VOTING_STATUS_INDEX_NOT_LOGGED_IN = 1;

		public const int VOTING_STATUS_INDEX_EMPTY = 2;

		private const int MAP_DISPLAY_INDEX_NONE = 0;

		private const int MAP_DISPLAY_INDEX_NAMED_MAP = 1;

		[SerializeField]
		private TMP_Text screenText;

		[SerializeField]
		private TMP_Text statusText;

		[SerializeField]
		private GorillaPressableButton upVoteButton;

		[SerializeField]
		private GorillaPressableButton downVoteButton;

		[SerializeField]
		private GTZone tableZone = GTZone.monkeBlocksShared;

		[SerializeField]
		private Material buttonDefaultMaterial;

		[SerializeField]
		private Material buttonDisabledMaterial;

		[Header("Localization Setup")]
		[SerializeField]
		private LocalizedText _statusLocText;

		[SerializeField]
		private LocalizedText _screenLocText;

		private BuilderTable table;

		private string loadedMapID = string.Empty;

		private bool voteInProgress;

		private bool waitingToClearStatus;

		private float clearStatusTime;

		private float clearStatusDelay = 2f;

		private IntVariable _statusIndexVar;

		private IntVariable _mapDisplayIndexVar;

		private StringVariable _mapNameVar;

		private List<MeshRenderer> meshes = new List<MeshRenderer>(12);

		private void Start()
		{
			SetupLocalization();
			if (BuilderTable.TryGetBuilderTableForZone(tableZone, out var builderTable))
			{
				table = builderTable;
				table.OnMapLoaded.AddListener(OnLoadedMapChanged);
				table.OnMapCleared.AddListener(OnMapCleared);
				OnLoadedMapChanged(table.GetCurrentMapID());
			}
			else
			{
				GTDev.LogWarning("No Builder Table found for Voting Station");
			}
			GetComponentsInChildren(includeInactive: false, meshes);
			upVoteButton.onPressButton.AddListener(OnUpVotePressed);
			downVoteButton.onPressButton.AddListener(OnDownVotePressed);
			ZoneManagement instance = ZoneManagement.instance;
			instance.onZoneChanged = (Action)Delegate.Combine(instance.onZoneChanged, new Action(OnZoneChanged));
			OnZoneChanged();
		}

		private void OnDestroy()
		{
			upVoteButton.onPressButton.RemoveListener(OnUpVotePressed);
			downVoteButton.onPressButton.RemoveListener(OnDownVotePressed);
			if (table != null)
			{
				table.OnMapLoaded.RemoveListener(OnLoadedMapChanged);
				table.OnMapCleared.RemoveListener(OnMapCleared);
			}
			if (ZoneManagement.instance != null)
			{
				ZoneManagement instance = ZoneManagement.instance;
				instance.onZoneChanged = (Action)Delegate.Remove(instance.onZoneChanged, new Action(OnZoneChanged));
			}
		}

		private void SetupLocalization()
		{
			if (_statusLocText == null)
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::SHARED_BLOCKS_VOTING_STATION] Trying to set up Localization, but [_statusLocText] is NULL");
				return;
			}
			if (_screenLocText == null)
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::SHARED_BLOCKS_VOTING_STATION] Trying to set up Localization, but [_screenLocText] is NULL");
				return;
			}
			string text = "voting-status-index";
			string text2 = "map-name-index";
			string text3 = "map-name";
			_statusIndexVar = _statusLocText.StringReference[text] as IntVariable;
			_mapDisplayIndexVar = _screenLocText.StringReference[text2] as IntVariable;
			_mapNameVar = _screenLocText.StringReference[text3] as StringVariable;
			if (_statusIndexVar == null)
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::SHARED_BLOCKS_VOTING_STATION] Failed to find [IntVariable] with var-name [" + text + "]");
			}
			if (_mapDisplayIndexVar == null)
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::SHARED_BLOCKS_VOTING_STATION] Failed to find [IntVariable] with var-name [" + text2 + "]");
			}
			if (_mapNameVar == null)
			{
				UnityEngine.Debug.LogError("[LOCALIZATION::SHARED_BLOCKS_VOTING_STATION] Failed to find [StringVariable] with var-name [" + text3 + "]");
			}
		}

		private void OnZoneChanged()
		{
			bool flag = ZoneManagement.instance.IsZoneActive(tableZone);
			foreach (MeshRenderer mesh in meshes)
			{
				mesh.enabled = flag;
			}
		}

		private void OnUpVotePressed()
		{
			if (!voteInProgress)
			{
				voteInProgress = true;
				_statusIndexVar.Value = 2;
				statusText.gameObject.SetActive(value: false);
				if (SharedBlocksManager.IsMapIDValid(loadedMapID) && upVoteButton.enabled)
				{
					SharedBlocksManager.instance.RequestVote(loadedMapID, up: true, OnVoteResponse);
					upVoteButton.buttonRenderer.material = upVoteButton.pressedMaterial;
					downVoteButton.buttonRenderer.material = buttonDefaultMaterial;
					upVoteButton.enabled = false;
					downVoteButton.enabled = true;
				}
			}
		}

		private void OnDownVotePressed()
		{
			if (!voteInProgress)
			{
				voteInProgress = true;
				_statusIndexVar.Value = 2;
				statusText.gameObject.SetActive(value: false);
				if (SharedBlocksManager.IsMapIDValid(loadedMapID) && downVoteButton.enabled)
				{
					SharedBlocksManager.instance.RequestVote(loadedMapID, up: false, OnVoteResponse);
					upVoteButton.buttonRenderer.material = buttonDefaultMaterial;
					downVoteButton.buttonRenderer.material = downVoteButton.pressedMaterial;
					upVoteButton.enabled = true;
					downVoteButton.enabled = false;
				}
			}
		}

		private void OnVoteResponse(bool success, string message)
		{
			voteInProgress = false;
			if (success)
			{
				_statusIndexVar.Value = 0;
				statusText.gameObject.SetActive(value: true);
			}
			else
			{
				if (int.TryParse(message, out var result))
				{
					_statusIndexVar.Value = result;
				}
				else
				{
					statusText.text = message;
					UnityEngine.Debug.Log("[LOCALIZATION::SHARED_BLOCKS_VOTING_STATION] WARNING: Passing in a non-int value for the [message]. This will not be localized!");
				}
				statusText.gameObject.SetActive(value: true);
				if (!loadedMapID.IsNullOrEmpty())
				{
					upVoteButton.buttonRenderer.material = buttonDefaultMaterial;
					downVoteButton.buttonRenderer.material = buttonDefaultMaterial;
					upVoteButton.enabled = true;
					downVoteButton.enabled = true;
				}
			}
			clearStatusTime = Time.time + clearStatusDelay;
			waitingToClearStatus = true;
		}

		private void LateUpdate()
		{
			if (waitingToClearStatus && Time.time > clearStatusTime)
			{
				waitingToClearStatus = false;
				_statusIndexVar.Value = 2;
				statusText.gameObject.SetActive(value: false);
			}
		}

		private void OnLoadedMapChanged(string mapID)
		{
			loadedMapID = mapID;
			statusText.gameObject.SetActive(value: false);
			UpdateScreen();
		}

		private void OnMapCleared()
		{
			loadedMapID = null;
			statusText.gameObject.SetActive(value: false);
			UpdateScreen();
		}

		private void UpdateScreen()
		{
			if (!loadedMapID.IsNullOrEmpty() && SharedBlocksManager.IsMapIDValid(loadedMapID))
			{
				_mapDisplayIndexVar.Value = 1;
				_mapNameVar.Value = SharedBlocksTerminal.MapIDToDisplayedString(loadedMapID);
				upVoteButton.enabled = true;
				downVoteButton.enabled = true;
				upVoteButton.buttonRenderer.material = buttonDefaultMaterial;
				downVoteButton.buttonRenderer.material = buttonDefaultMaterial;
			}
			else
			{
				_mapDisplayIndexVar.Value = 0;
				upVoteButton.enabled = false;
				downVoteButton.enabled = false;
				upVoteButton.buttonRenderer.material = buttonDisabledMaterial;
				downVoteButton.buttonRenderer.material = buttonDisabledMaterial;
			}
		}
	}
}
namespace GorillaTagScripts.AI
{
	public class AIEntity : MonoBehaviour
	{
		public GameObject waypointsContainer;

		public Transform circleCenter;

		public float circleRadius;

		public float angularSpeed;

		public float patrolSpeed;

		public float fleeSpeed;

		public NavMeshAgent navMeshAgent;

		public Animator animator;

		public float fleeRang;

		public float fleeSpeedMult;

		public float minChaseRange;

		public float attackDistance;

		public float navMeshSampleRange = 5f;

		internal readonly List<Transform> waypoints = new List<Transform>();

		internal float defaultSpeed;

		public Transform followTarget;

		public NetPlayer targetPlayer;

		public bool targetIsOnNavMesh;

		protected void Awake()
		{
			navMeshAgent = base.gameObject.GetComponent<NavMeshAgent>();
			animator = base.gameObject.GetComponent<Animator>();
			if (waypointsContainer != null)
			{
				Transform[] componentsInChildren = waypointsContainer.GetComponentsInChildren<Transform>();
				foreach (Transform item in componentsInChildren)
				{
					waypoints.Add(item);
				}
			}
		}

		protected void ChooseRandomTarget()
		{
			int num = -1;
			int randomTarget = UnityEngine.Random.Range(0, VRRigCache.ActiveRigs.Count);
			num = VRRigCache.ActiveRigContainers.FindIndex((RigContainer x) => x.Rig.creator != null && x.Rig.creator == VRRigCache.ActiveRigContainers[randomTarget].Rig.creator);
			if (num == -1)
			{
				num = UnityEngine.Random.Range(0, VRRigCache.ActiveRigs.Count);
			}
			if (num < VRRigCache.ActiveRigContainers.Count)
			{
				targetPlayer = VRRigCache.ActiveRigContainers[num].Rig.creator;
				followTarget = VRRigCache.ActiveRigContainers[num].Rig.head.rigTarget;
				targetIsOnNavMesh = NavMesh.SamplePosition(followTarget.position, out var _, navMeshSampleRange, 1);
			}
			else
			{
				targetPlayer = null;
				followTarget = null;
			}
		}

		protected void ChooseClosestTarget()
		{
			VRRig vRRig = null;
			float num = float.MaxValue;
			foreach (RigContainer activeRigContainer in VRRigCache.ActiveRigContainers)
			{
				VRRig rig = activeRigContainer.Rig;
				if (rig.head != null && !GTExt.IsNull(rig.head.rigTarget))
				{
					float sqrMagnitude = (base.transform.position - rig.head.rigTarget.transform.position).sqrMagnitude;
					if (sqrMagnitude < minChaseRange * minChaseRange && sqrMagnitude < num)
					{
						num = sqrMagnitude;
						vRRig = rig;
					}
				}
			}
			if (vRRig.IsNotNull())
			{
				targetPlayer = vRRig.creator;
				followTarget = vRRig.head.rigTarget;
				targetIsOnNavMesh = NavMesh.SamplePosition(followTarget.position, out var _, navMeshSampleRange, 1);
			}
			else
			{
				targetPlayer = null;
				followTarget = null;
			}
		}
	}
	public interface IState
	{
		void Tick();

		void OnEnter();

		void OnExit();
	}
	public class StateMachine
	{
		private class Transition
		{
			public Func<bool> Condition { get; }

			public IState To { get; }

			public Transition(IState to, Func<bool> condition)
			{
				To = to;
				Condition = condition;
			}
		}

		private IState _currentState;

		private Dictionary<Type, List<Transition>> _transitions = new Dictionary<Type, List<Transition>>();

		private List<Transition> _currentTransitions = new List<Transition>();

		private List<Transition> _anyTransitions = new List<Transition>();

		private static List<Transition> EmptyTransitions = new List<Transition>(0);

		public void Tick()
		{
			Transition transition = GetTransition();
			if (transition != null)
			{
				SetState(transition.To);
			}
			_currentState?.Tick();
		}

		public void SetState(IState state)
		{
			if (state != _currentState)
			{
				_currentState?.OnExit();
				_currentState = state;
				_transitions.TryGetValue(_currentState.GetType(), out _currentTransitions);
				if (_currentTransitions == null)
				{
					_currentTransitions = EmptyTransitions;
				}
				_currentState.OnEnter();
			}
		}

		public IState GetState()
		{
			return _currentState;
		}

		public void AddTransition(IState from, IState to, Func<bool> predicate)
		{
			if (!_transitions.TryGetValue(from.GetType(), out var value))
			{
				value = new List<Transition>();
				_transitions[from.GetType()] = value;
			}
			value.Add(new Transition(to, predicate));
		}

		public void AddAnyTransition(IState state, Func<bool> predicate)
		{
			_anyTransitions.Add(new Transition(state, predicate));
		}

		private Transition GetTransition()
		{
			foreach (Transition anyTransition in _anyTransitions)
			{
				if (anyTransition.Condition())
				{
					return anyTransition;
				}
			}
			foreach (Transition currentTransition in _currentTransitions)
			{
				if (currentTransition.Condition())
				{
					return currentTransition;
				}
			}
			return null;
		}
	}
}
namespace GorillaTagScripts.AI.States
{
	public class Chase_State : IState
	{
		private AIEntity entity;

		private NavMeshAgent agent;

		public bool chaseOver;

		public Transform FollowTarget { get; set; }

		public Chase_State(AIEntity entity)
		{
			this.entity = entity;
			agent = this.entity.navMeshAgent;
		}

		public void Tick()
		{
			agent.SetDestination(FollowTarget.position);
			if (agent.remainingDistance < entity.attackDistance)
			{
				chaseOver = true;
			}
		}

		public void OnEnter()
		{
			chaseOver = false;
			UnityEngine.Debug.Log("Current State: " + typeof(Chase_State));
		}

		public void OnExit()
		{
			chaseOver = true;
		}
	}
	public class CircularPatrol_State : IState
	{
		private AIEntity entity;

		private float angle;

		public CircularPatrol_State(AIEntity entity)
		{
			this.entity = entity;
		}

		public void Tick()
		{
			UnityEngine.Vector3 position = entity.circleCenter.position;
			float x = position.x + Mathf.Cos(angle) * entity.angularSpeed;
			float y = position.y;
			float z = position.z + Mathf.Sin(angle) * entity.angularSpeed;
			entity.transform.position = new UnityEngine.Vector3(x, y, z);
			angle += entity.angularSpeed * Time.deltaTime;
		}

		public void OnEnter()
		{
		}

		public void OnExit()
		{
		}
	}
	public class Patrol_State : IState
	{
		private AIEntity entity;

		private NavMeshAgent agent;

		public Patrol_State(AIEntity entity)
		{
			this.entity = entity;
			agent = this.entity.navMeshAgent;
		}

		public void Tick()
		{
			if (agent.remainingDistance <= agent.stoppingDistance)
			{
				UnityEngine.Vector3 position = entity.waypoints[UnityEngine.Random.Range(0, entity.waypoints.Count - 1)].transform.position;
				agent.SetDestination(position);
			}
		}

		public void OnEnter()
		{
			UnityEngine.Debug.Log("Current State: " + typeof(Patrol_State));
			if (entity.waypoints.Count > 0)
			{
				agent.SetDestination(entity.waypoints[0].transform.position);
			}
		}

		public void OnExit()
		{
		}
	}
}
namespace GorillaTagScripts.AI.Entities
{
	public class TestShark : AIEntity
	{
		public float nextTimeToChasePlayer = 30f;

		private float chasingTimer;

		private bool shouldChase;

		private StateMachine _stateMachine;

		private CircularPatrol_State circularPatrol;

		private Patrol_State patrol;

		private Chase_State chase;

		private new void Awake()
		{
			base.Awake();
			chasingTimer = 0f;
			_stateMachine = new StateMachine();
			circularPatrol = new CircularPatrol_State(this);
			patrol = new Patrol_State(this);
			chase = new Chase_State(this);
			_stateMachine.AddTransition(patrol, chase, ShouldChase());
			_stateMachine.AddTransition(chase, patrol, ShouldPatrol());
			_stateMachine.SetState(patrol);
			Func<bool> ShouldChase()
			{
				return () => shouldChase && PhotonNetwork.InRoom;
			}
			Func<bool> ShouldPatrol()
			{
				return () => chase.chaseOver;
			}
		}

		private void Update()
		{
			_stateMachine.Tick();
			shouldChase = false;
			chasingTimer += Time.deltaTime;
			if (chasingTimer >= nextTimeToChasePlayer)
			{
				ChooseClosestTarget();
				if (followTarget != null)
				{
					chase.FollowTarget = followTarget;
					shouldChase = true;
				}
				chasingTimer = 0f;
			}
		}
	}
}
