	public class EvolvingCosmeticKiosk : MonoBehaviour
	{
		private record CosmeticData
		{
			public EvolvingCosmetic EvolvingCosmetic;

			public string PlayfabId;
		}

		[SerializeField]
		private EvolvingCosmeticKioskButtonSet[] _buttonSets;

		private readonly List<CosmeticData> _cosmetics = new List<CosmeticData>();

		private int _cosmeticIdx;

		public bool Initialized { get; private set; }

		public VRRig VRRig => VRRig.LocalRig;

		public bool CosmeticsListBuilding { get; private set; }

		private void Awake()
		{
			EvolvingCosmeticKioskButtonSet[] buttonSets = _buttonSets;
			for (int i = 0; i < buttonSets.Length; i++)
			{
				buttonSets[i].RegisterKiosk(this);
			}
			Initialized = true;
		}

		private async Task BuildCosmeticsList()
		{
			_cosmetics.Clear();
			UpdateButtonSets();
			CosmeticsListBuilding = true;
			while (CosmeticsController.instance == null || !CosmeticsController.instance.v2_isCosmeticPlayFabCatalogDataLoaded || !CosmeticsV2Spawner_Dirty.isPrepared)
			{
				await Task.Yield();
			}
			CosmeticItemRegistry registry = VRRig.cosmeticsObjectRegistry;
			HashSet<string> loadedCosmetics = new HashSet<string>();
			CosmeticsController.CosmeticItem[] items = CosmeticsController.instance.currentWornSet.items;
			for (int i = 0; i < items.Length; i++)
			{
				CosmeticsController.CosmeticItem item = items[i];
				if (string.IsNullOrEmpty(item.itemName) || item.itemName == "null")
				{
					continue;
				}
				await Task.Yield();
				CosmeticItemInstance cosmeticItemInstance;
				try
				{
					UnityEngine.Debug.Log("Fetching cosmetic " + item.itemName);
					cosmeticItemInstance = registry.Cosmetic(item.itemName);
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
					continue;
				}
				if (cosmeticItemInstance == null)
				{
					continue;
				}
				foreach (GameObject @object in cosmeticItemInstance.objects)
				{
					EvolvingCosmetic component = @object.GetComponent<EvolvingCosmetic>();
					if ((object)component != null && loadedCosmetics.Add(item.itemName))
					{
						_cosmetics.Add(new CosmeticData
						{
							EvolvingCosmetic = component,
							PlayfabId = item.itemName
						});
					}
				}
			}
			UnityEngine.Debug.Log($"EvolvingCosmetics loaded ({_cosmetics.Count} found).");
			CosmeticsListBuilding = false;
			ResetButtonSets();
			UpdateButtonSets();
		}

		private void ResetButtonSets()
		{
			_cosmeticIdx = 0;
			EvolvingCosmeticKioskButtonSet[] buttonSets = _buttonSets;
			for (int i = 0; i < buttonSets.Length; i++)
			{
				buttonSets[i].Reset();
			}
		}

		private void UpdateButtonSets()
		{
			for (int i = 0; i < _buttonSets.Length; i++)
			{
				int num = _cosmeticIdx + i;
				if (num >= _cosmetics.Count)
				{
					_buttonSets[i].Reset();
					continue;
				}
				CosmeticData cosmeticData = _cosmetics[num];
				_buttonSets[i].SetCosmetic(cosmeticData.PlayfabId, cosmeticData.EvolvingCosmetic);
			}
		}

		public async void OnHandScanned(NetPlayer player)
		{
			if (player.IsLocal)
			{
				await BuildCosmeticsList();
			}
		}

		public void ScrollForward()
		{
			Scroll(1);
		}

		public void ScrollBackward()
		{
			Scroll(-1);
		}

		private void Scroll(int direction)
		{
			_cosmeticIdx = System.Math.Clamp(_cosmeticIdx + direction, 0, _cosmetics.Count - 1);
			UpdateButtonSets();
		}
	}
	public class EvolvingCosmeticKioskButtonSet : MonoBehaviour
	{
		[SerializeField]
		private DynamicCosmeticStand _cosmeticStand;

		[SerializeField]
		private GorillaPressableButton _plusButton;

		[SerializeField]
		private GorillaPressableButton _minusButton;

		private EvolvingCosmeticKiosk _kiosk;

		private EvolvingCosmetic _cosmetic;

		private string _playfabId;

		public void RegisterKiosk(EvolvingCosmeticKiosk kiosk)
		{
			if (_kiosk != null)
			{
				throw new Exception("Attempted to double-register EvolvingCosmeticKiosk to a button.");
			}
			_kiosk = kiosk;
		}

		public void Reset()
		{
			_cosmeticStand.ClearCosmetics();
			_playfabId = null;
			_cosmetic = null;
		}

		public void SetCosmetic(string playfabId, EvolvingCosmetic evolvingCosmetic)
		{
			_cosmeticStand.SpawnItemOntoStand(playfabId);
			_playfabId = playfabId;
			_cosmetic = evolvingCosmetic;
		}

		public void GoForward()
		{
			if (!(_cosmetic == null) && _cosmetic.CanGoForward())
			{
				_cosmetic.GoForward();
				RefreshOnPlayer();
			}
		}

		public void GoBackward()
		{
			if (!(_cosmetic == null) && _cosmetic.CanGoBack())
			{
				_cosmetic.GoBack();
				RefreshOnPlayer();
			}
		}

		private void RefreshOnPlayer()
		{
			if (_kiosk == null || _playfabId == null || _cosmetic == null)
			{
				return;
			}
			bool flag = false;
			CosmeticsController.CosmeticItem[] items = CosmeticsController.instance.currentWornSet.items;
			for (int i = 0; i < items.Length; i++)
			{
				if (items[i].itemName != _playfabId)
				{
					continue;
				}
				CosmeticItemInstance cosmeticItemInstance = _kiosk.VRRig.cosmeticsObjectRegistry.Cosmetic(_playfabId);
				if (cosmeticItemInstance == null)
				{
					continue;
				}
				foreach (GameObject @object in cosmeticItemInstance.objects)
				{
					EvolvingCosmetic component = @object.GetComponent<EvolvingCosmetic>();
					if ((object)component != null)
					{
						component.MatchStage(_cosmetic);
						EvolvingCosmeticSaveData.Instance.SelectedIndices[component.PlayfabId] = component.SelectedObjectIndex;
						flag = true;
					}
				}
			}
			if (flag)
			{
				PlayerPrefs.SetString("EvolvingCosmeticSaveData", EvolvingCosmeticSaveData.Instance.Write());
			}
		}
	}
	public class FittingRoom : MonoBehaviour
	{
		public FittingRoomButton[] fittingRoomButtons;

		public GameObject consoleMesh;

		private int iterator;

		public bool addOnEnable;

		public void InitializeForCustomMap(bool useCustomConsoleMesh = true)
		{
			consoleMesh?.SetActive(!useCustomConsoleMesh);
			CosmeticsController.instance.AddFittingRoom(this);
		}

		private void OnEnable()
		{
			if (addOnEnable)
			{
				CosmeticsController.instance.AddFittingRoom(this);
			}
		}

		private void OnDisable()
		{
			if (addOnEnable)
			{
				CosmeticsController.instance.RemoveFittingRoom(this);
			}
		}

		public void UpdateFromCart(List<CosmeticsController.CosmeticItem> currentCart, CosmeticsController.CosmeticSet tryOnSet)
		{
			for (iterator = 0; iterator < fittingRoomButtons.Length; iterator++)
			{
				if (iterator < currentCart.Count)
				{
					bool isInTryOnSet = CosmeticsController.instance.AnyMatch(tryOnSet, currentCart[iterator]) || (!CosmeticsController.instance.tryOnCollectableItem.isNullItem && currentCart[iterator].itemName == CosmeticsController.instance.tryOnCollectableItem.itemName);
					fittingRoomButtons[iterator].SetItem(currentCart[iterator], isInTryOnSet);
				}
				else
				{
					fittingRoomButtons[iterator].ClearItem();
				}
			}
		}
	}
	public class ItemCheckout : MonoBehaviour
	{
		public CheckoutCartButton[] checkoutCartButtons;

		public PurchaseItemButton leftPurchaseButton;

		public PurchaseItemButton rightPurchaseButton;

		[HideInInspector]
		public Text purchaseText;

		public TMP_Text purchaseTextTMP;

		public HeadModel checkoutHeadModel;

		public Collider checkoutTryOnArea;

		public GameObject checkoutCounterMesh;

		public GameObject purchaseScreenMesh;

		private Scene originalScene;

		private int iterator;

		public bool addOnEnable;

		private void OnEnable()
		{
			if (addOnEnable)
			{
				CosmeticsController.instance.AddItemCheckout(this);
			}
		}

		private void OnDisable()
		{
			if (addOnEnable)
			{
				CosmeticsController.instance.RemoveItemCheckout(this);
			}
		}

		public void InitializeForCustomMap(CompositeTriggerEvents customMapTryOnArea, Scene customMapScene, bool useCustomCounterMesh = true)
		{
			checkoutCounterMesh?.SetActive(!useCustomCounterMesh);
			purchaseScreenMesh?.SetActive(useCustomCounterMesh);
			originalScene = customMapScene;
			customMapTryOnArea.AddCollider(checkoutTryOnArea);
			CosmeticsController.instance.AddItemCheckout(this);
		}

		public void RemoveFromCustomMap(CompositeTriggerEvents customMapTryOnArea)
		{
			if (!GTExt.IsNull(customMapTryOnArea))
			{
				customMapTryOnArea.RemoveCollider(checkoutTryOnArea);
			}
		}

		public void UpdateFromCart(List<CosmeticsController.CosmeticItem> currentCart, CosmeticsController.CosmeticItem itemToBuy)
		{
			for (iterator = 0; iterator < checkoutCartButtons.Length; iterator++)
			{
				if (iterator < currentCart.Count)
				{
					bool isCurrentItemToBuy = currentCart[iterator].itemName == itemToBuy.itemName;
					checkoutCartButtons[iterator].SetItem(currentCart[iterator], isCurrentItemToBuy);
				}
				else
				{
					checkoutCartButtons[iterator].ClearItem();
				}
			}
		}

		public void UpdatePurchaseText(string newText, string leftPurchaseButtonText, string rightPurchaseButtonText, bool leftButtonOn, bool rightButtonOn)
		{
			if (purchaseText.IsNotNull())
			{
				purchaseText.text = newText;
			}
			if (purchaseTextTMP.IsNotNull())
			{
				purchaseTextTMP.text = newText;
			}
			if (!leftPurchaseButtonText.IsNullOrEmpty())
			{
				leftPurchaseButton.SetText(leftPurchaseButtonText);
				leftPurchaseButton.buttonRenderer.material = (leftButtonOn ? leftPurchaseButton.pressedMaterial : leftPurchaseButton.unpressedMaterial);
			}
			if (!rightPurchaseButtonText.IsNullOrEmpty())
			{
				rightPurchaseButton.SetText(rightPurchaseButtonText);
				rightPurchaseButton.buttonRenderer.material = (rightButtonOn ? rightPurchaseButton.pressedMaterial : rightPurchaseButton.unpressedMaterial);
			}
		}

		public bool IsFromScene(Scene unloadingScene)
		{
			return unloadingScene == originalScene;
		}
	}
