	public class CosmeticCollectionDisplay : MonoBehaviour
	{
		private static readonly Dictionary<(int, string), CosmeticCollectionDisplay> Registered = new Dictionary<(int, string), CosmeticCollectionDisplay>();

		private bool isCycling;

		private bool isVisible = true;

		private int activeIndex;

		private int registeredRigID;

		private string registeredParentID;

		private readonly List<GameObject> spawnedAnchors = new List<GameObject>();

		private readonly List<AsyncOperationHandle<GameObject>> loadOps = new List<AsyncOperationHandle<GameObject>>();

		private readonly List<CosmeticsController.CosmeticItem> placedCollectables = new List<CosmeticsController.CosmeticItem>();

		public string ParentPlayFabID { get; private set; }

		public int ActiveIndex => activeIndex;

		public int Count => spawnedAnchors.Count;

		public CosmeticsController.CosmeticItem? ActiveCollectable
		{
			get
			{
				if (placedCollectables.Count <= 0)
				{
					return null;
				}
				return placedCollectables[activeIndex];
			}
		}

		public static void Register(int rigID, string parentID, CosmeticCollectionDisplay display)
		{
			display.registeredRigID = rigID;
			display.registeredParentID = parentID;
			display.ParentPlayFabID = parentID;
			Registered[(rigID, parentID)] = display;
		}

		public static CosmeticCollectionDisplay FindForRig(int rigID, string parentID)
		{
			Registered.TryGetValue((rigID, parentID), out var value);
			return value;
		}

		public static void GetDisplaysForRig(int rigID, List<CosmeticCollectionDisplay> result)
		{
			result.Clear();
			foreach (KeyValuePair<(int, string), CosmeticCollectionDisplay> item in Registered)
			{
				if (item.Key.Item1 == rigID)
				{
					result.Add(item.Value);
				}
			}
		}

		public CosmeticsController.CosmeticItem? GetCollectableAt(int index)
		{
			if (index < 0 || index >= placedCollectables.Count)
			{
				return null;
			}
			return placedCollectables[index];
		}

		public bool ContentMatches(IReadOnlyList<CosmeticsController.CosmeticItem> items)
		{
			if (placedCollectables.Count != items.Count)
			{
				return false;
			}
			for (int i = 0; i < placedCollectables.Count; i++)
			{
				if (placedCollectables[i].itemName != items[i].itemName)
				{
					return false;
				}
			}
			return true;
		}

		public void Populate(IReadOnlyList<CosmeticsController.CosmeticItem> ownedCollectables, CosmeticInfoV2 parentInfo, Transform rootXform)
		{
			ClearSpawnedAnchors();
			placedCollectables.Clear();
			isCycling = parentInfo.collectionIsCycling;
			bool collectionUsesIndexTargeting = parentInfo.collectionUsesIndexTargeting;
			if (isCycling)
			{
				CosmeticCollectionSlotDefinition cosmeticCollectionSlotDefinition = parentInfo.collectionSlots[0];
				UnityEngine.Vector3 localScale = cosmeticCollectionSlotDefinition.offset.scale;
				if (Mathf.Abs(localScale.x) < 0.001f || Mathf.Abs(localScale.y) < 0.001f || Mathf.Abs(localScale.z) < 0.001f)
				{
					localScale = UnityEngine.Vector3.one;
				}
				for (int i = 0; i < ownedCollectables.Count; i++)
				{
					GameObject gameObject = new GameObject($"CollectionSlot_{i}");
					gameObject.transform.SetParent(rootXform, worldPositionStays: false);
					gameObject.transform.localPosition = cosmeticCollectionSlotDefinition.offset.pos;
					gameObject.transform.localRotation = cosmeticCollectionSlotDefinition.offset.rot;
					gameObject.transform.localScale = localScale;
					spawnedAnchors.Add(gameObject);
					placedCollectables.Add(ownedCollectables[i]);
					InstantiateIntoAnchor(ownedCollectables[i], gameObject.transform);
				}
			}
			else
			{
				int num = 0;
				for (int j = 0; j < parentInfo.collectionSlots.Length; j++)
				{
					CosmeticCollectionSlotDefinition cosmeticCollectionSlotDefinition2 = parentInfo.collectionSlots[j];
					CosmeticsController.CosmeticItem? cosmeticItem = null;
					if (collectionUsesIndexTargeting)
					{
						for (int k = 0; k < ownedCollectables.Count; k++)
						{
							if (ownedCollectables[k].collectionTargetSlotIndex == j)
							{
								cosmeticItem = ownedCollectables[k];
								break;
							}
						}
					}
					else if (num < ownedCollectables.Count)
					{
						cosmeticItem = ownedCollectables[num++];
					}
					if (cosmeticItem.HasValue)
					{
						UnityEngine.Vector3 localScale2 = cosmeticCollectionSlotDefinition2.offset.scale;
						if (Mathf.Abs(localScale2.x) < 0.001f || Mathf.Abs(localScale2.y) < 0.001f || Mathf.Abs(localScale2.z) < 0.001f)
						{
							localScale2 = UnityEngine.Vector3.one;
						}
						GameObject gameObject2 = new GameObject($"CollectionSlot_{j}");
						gameObject2.transform.SetParent(rootXform, worldPositionStays: false);
						gameObject2.transform.localPosition = cosmeticCollectionSlotDefinition2.offset.pos;
						gameObject2.transform.localRotation = cosmeticCollectionSlotDefinition2.offset.rot;
						gameObject2.transform.localScale = localScale2;
						spawnedAnchors.Add(gameObject2);
						placedCollectables.Add(cosmeticItem.Value);
						InstantiateIntoAnchor(cosmeticItem.Value, gameObject2.transform);
					}
				}
			}
			activeIndex = 0;
			ApplyCyclingVisibility();
		}

		public void SetActiveIndex(int index)
		{
			if (spawnedAnchors.Count != 0)
			{
				activeIndex = Mathf.Clamp(index, 0, spawnedAnchors.Count - 1);
				RefreshAnchorVisibility();
			}
		}

		public void CycleActive(int direction)
		{
			if (isCycling && spawnedAnchors.Count != 0)
			{
				activeIndex = (activeIndex + direction + spawnedAnchors.Count) % spawnedAnchors.Count;
				RefreshAnchorVisibility();
			}
		}

		public void SetVisible(bool visible)
		{
			isVisible = visible;
			RefreshAnchorVisibility();
		}

		private void InstantiateIntoAnchor(CosmeticsController.CosmeticItem collectable, Transform anchor)
		{
			if (!CosmeticsController.instance.TryGetCosmeticInfoV2(collectable.itemName, out var cosmeticInfo))
			{
				return;
			}
			CosmeticPart[] array = (cosmeticInfo.hasStoreParts ? cosmeticInfo.storeParts : cosmeticInfo.functionalParts);
			if (array == null || array.Length == 0)
			{
				return;
			}
			GTAssetRef<GameObject> prefabAssetRef = array[0].prefabAssetRef;
			if (prefabAssetRef == null || !prefabAssetRef.RuntimeKeyIsValid())
			{
				return;
			}
			UnityEngine.Vector3 attachScale = UnityEngine.Vector3.one;
			CosmeticPart[] functionalParts = cosmeticInfo.functionalParts;
			if (functionalParts != null && functionalParts.Length != 0)
			{
				CosmeticAttachInfo[] attachAnchors = functionalParts[0].attachAnchors;
				if (attachAnchors != null && attachAnchors.Length != 0)
				{
					UnityEngine.Vector3 scale = attachAnchors[0].offset.scale;
					if (Mathf.Abs(scale.x) >= 0.001f && Mathf.Abs(scale.y) >= 0.001f && Mathf.Abs(scale.z) >= 0.001f)
					{
						attachScale = scale;
					}
				}
			}
			AsyncOperationHandle<GameObject> item = prefabAssetRef.InstantiateAsync(anchor);
			loadOps.Add(item);
			item.Completed += delegate(AsyncOperationHandle<GameObject> handle)
			{
				if (handle.Status == AsyncOperationStatus.Succeeded)
				{
					if (anchor == null || handle.Result == null)
					{
						Addressables.ReleaseInstance(handle);
					}
					else
					{
						handle.Result.transform.localPosition = UnityEngine.Vector3.zero;
						handle.Result.transform.localRotation = UnityEngine.Quaternion.identity;
						handle.Result.transform.localScale = attachScale;
					}
				}
			};
		}

		private void ApplyCyclingVisibility()
		{
			RefreshAnchorVisibility();
		}

		private void RefreshAnchorVisibility()
		{
			for (int i = 0; i < spawnedAnchors.Count; i++)
			{
				if (spawnedAnchors[i] != null)
				{
					bool active = isVisible && (!isCycling || i == activeIndex);
					spawnedAnchors[i].SetActive(active);
				}
			}
		}

		private void ClearSpawnedAnchors()
		{
			for (int i = 0; i < loadOps.Count; i++)
			{
				if (loadOps[i].IsValid())
				{
					Addressables.ReleaseInstance(loadOps[i]);
				}
			}
			loadOps.Clear();
			for (int j = 0; j < spawnedAnchors.Count; j++)
			{
				if (spawnedAnchors[j] != null)
				{
					UnityEngine.Object.Destroy(spawnedAnchors[j]);
				}
			}
			spawnedAnchors.Clear();
			placedCollectables.Clear();
		}

		private void OnDisable()
		{
			Registered.Remove((registeredRigID, registeredParentID));
		}

		private void OnEnable()
		{
			if (!string.IsNullOrEmpty(registeredParentID))
			{
				Registered[(registeredRigID, registeredParentID)] = this;
			}
		}

		private void OnDestroy()
		{
			Registered.Remove((registeredRigID, registeredParentID));
			ClearSpawnedAnchors();
		}
	}
	public class CosmeticItemRegistry
	{
		private Dictionary<string, CosmeticItemInstance> _nameToCosmeticMap = new Dictionary<string, CosmeticItemInstance>();

		private HashSet<GameObject> initializedCosmetics = new HashSet<GameObject>();

		private GameObject _nullItem;

		private VRRig rig;

		public VRRig Rig => rig;

		public void RefreshRig()
		{
			rig.RefreshCosmetics();
		}

		public CosmeticItemRegistry(VRRig _rig)
		{
			rig = _rig;
		}

		public void InitializeCosmetic(GameObject cosmeticGObj, bool isOverride)
		{
			if (initializedCosmetics.Contains(cosmeticGObj))
			{
				return;
			}
			initializedCosmetics.Add(cosmeticGObj);
			if (!isOverride)
			{
				foreach (GameObject overrideCosmetic in rig.overrideCosmetics)
				{
					if (cosmeticGObj.name == overrideCosmetic.name)
					{
						cosmeticGObj.name = "OVERRIDDEN";
						return;
					}
				}
			}
			CosmeticItemInstance cosmeticItemInstance = null;
			string text = cosmeticGObj.name.Replace("LEFT.", "").Replace("RIGHT.", "").TrimEnd();
			if (_nameToCosmeticMap.ContainsKey(text))
			{
				cosmeticItemInstance = _nameToCosmeticMap[text];
			}
			else
			{
				cosmeticItemInstance = new CosmeticItemInstance();
				CosmeticSO cosmeticSOFromDisplayName = CosmeticsController.instance.GetCosmeticSOFromDisplayName(text);
				cosmeticItemInstance.clippingOffsets = ((cosmeticSOFromDisplayName != null) ? cosmeticSOFromDisplayName.info.anchorAntiIntersectOffsets : CosmeticsController.instance.defaultClipOffsets);
				cosmeticItemInstance.isHoldableItem = cosmeticSOFromDisplayName != null && cosmeticSOFromDisplayName.info.hasHoldableParts;
				_nameToCosmeticMap.Add(text, cosmeticItemInstance);
			}
			HoldableObject component = cosmeticGObj.GetComponent<HoldableObject>();
			bool flag = cosmeticGObj.name.Contains("LEFT.");
			bool flag2 = cosmeticGObj.name.Contains("RIGHT.");
			if (cosmeticItemInstance.isHoldableItem && component != null)
			{
				if (component is SnowballThrowable || component is TransferrableObject)
				{
					cosmeticItemInstance.holdableObjects.Add(cosmeticGObj);
				}
				else if (flag)
				{
					cosmeticItemInstance.leftObjects.Add(cosmeticGObj);
				}
				else if (flag2)
				{
					cosmeticItemInstance.rightObjects.Add(cosmeticGObj);
				}
				else
				{
					cosmeticItemInstance.objects.Add(cosmeticGObj);
				}
			}
			else if (flag)
			{
				cosmeticItemInstance.leftObjects.Add(cosmeticGObj);
			}
			else if (flag2)
			{
				cosmeticItemInstance.rightObjects.Add(cosmeticGObj);
			}
			else
			{
				cosmeticItemInstance.objects.Add(cosmeticGObj);
			}
			cosmeticItemInstance.dbgname = text;
			Renderer[] componentsInChildren = cosmeticGObj.GetComponentsInChildren<Renderer>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				if (componentsInChildren[i].enabled)
				{
					cosmeticItemInstance.allRenderers.Add(componentsInChildren[i]);
				}
			}
			ParticleSystem[] componentsInChildren2 = cosmeticGObj.GetComponentsInChildren<ParticleSystem>();
			for (int j = 0; j < componentsInChildren2.Length; j++)
			{
				if (componentsInChildren2[j].emission.enabled)
				{
					cosmeticItemInstance.allParticles.Add(componentsInChildren2[j]);
				}
			}
		}

		public CosmeticItemInstance Cosmetic(string itemName)
		{
			if (string.IsNullOrEmpty(itemName) || itemName == "NOTHING")
			{
				return null;
			}
			if (!_nameToCosmeticMap.TryGetValue(itemName, out var value))
			{
				CosmeticsV2Spawner_Dirty.ProcessLoadOpInfos(rig, itemName, this);
				return null;
			}
			return value;
		}
	}
	public class CosmeticItemInstance
	{
		public List<GameObject> leftObjects = new List<GameObject>();

		public List<GameObject> rightObjects = new List<GameObject>();

		public List<GameObject> objects = new List<GameObject>();

		public List<GameObject> holdableObjects = new List<GameObject>();

		public List<Renderer> allRenderers = new List<Renderer>();

		public List<ParticleSystem> allParticles = new List<ParticleSystem>();

		public CosmeticAnchorAntiIntersectOffsets clippingOffsets;

		public bool isHoldableItem;

		public string dbgname;

		private BodyDockPositions _bodyDockPositions;

		private VRRigAnchorOverrides _anchorOverrides;

		private CosmeticsController.CosmeticSlots _activeSlot;

		public CosmeticsController.CosmeticSlots ActiveSlot => _activeSlot;

		private void EnableItem(GameObject obj, bool enable)
		{
			try
			{
				obj.SetActive(enable);
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"Exception while enabling cosmetic: {arg}");
			}
		}

		private void ApplyClippingOffsets(bool itemEnabled)
		{
			if (!(_bodyDockPositions == null) && _anchorOverrides != null)
			{
				if (clippingOffsets.nameTag.enabled)
				{
					_anchorOverrides.UpdateNameTagOffset(itemEnabled ? clippingOffsets.nameTag.offset : XformOffset.Identity, itemEnabled, _activeSlot);
				}
				if (clippingOffsets.leftArm.enabled)
				{
					_anchorOverrides.ApplyAntiClippingOffsets(TransferrableObject.PositionState.OnLeftArm, clippingOffsets.leftArm.offset, itemEnabled, _bodyDockPositions.leftArmTransform);
				}
				if (clippingOffsets.rightArm.enabled)
				{
					_anchorOverrides.ApplyAntiClippingOffsets(TransferrableObject.PositionState.OnRightArm, clippingOffsets.rightArm.offset, itemEnabled, _bodyDockPositions.rightArmTransform);
				}
				if (clippingOffsets.chest.enabled)
				{
					_anchorOverrides.ApplyAntiClippingOffsets(TransferrableObject.PositionState.OnChest, clippingOffsets.chest.offset, itemEnabled, _anchorOverrides.chestDefaultTransform);
				}
				if (clippingOffsets.huntComputer.enabled)
				{
					_anchorOverrides.UpdateHuntWatchOffset(clippingOffsets.huntComputer.offset, itemEnabled);
				}
				if (clippingOffsets.badge.enabled)
				{
					_anchorOverrides.UpdateBadgeOffset(itemEnabled ? clippingOffsets.badge.offset : XformOffset.Identity, itemEnabled, _activeSlot);
				}
				if (clippingOffsets.builderWatch.enabled)
				{
					_anchorOverrides.UpdateBuilderWatchOffset(clippingOffsets.builderWatch.offset, itemEnabled);
				}
				if (clippingOffsets.friendshipBraceletLeft.enabled)
				{
					_anchorOverrides.UpdateFriendshipBraceletOffset(clippingOffsets.friendshipBraceletLeft.offset, left: true, itemEnabled);
				}
				if (clippingOffsets.friendshipBraceletRight.enabled)
				{
					_anchorOverrides.UpdateFriendshipBraceletOffset(clippingOffsets.friendshipBraceletRight.offset, left: false, itemEnabled);
				}
			}
		}

		public void DisableItem(CosmeticsController.CosmeticSlots cosmeticSlot)
		{
			bool flag = CosmeticsController.CosmeticSet.IsSlotLeftHanded(cosmeticSlot);
			bool flag2 = CosmeticsController.CosmeticSet.IsSlotRightHanded(cosmeticSlot);
			foreach (GameObject @object in objects)
			{
				EnableItem(@object, enable: false);
			}
			if (flag)
			{
				foreach (GameObject leftObject in leftObjects)
				{
					EnableItem(leftObject, enable: false);
				}
			}
			if (flag2)
			{
				foreach (GameObject rightObject in rightObjects)
				{
					EnableItem(rightObject, enable: false);
				}
			}
			ApplyClippingOffsets(itemEnabled: false);
		}

		public void EnableItem(CosmeticsController.CosmeticSlots cosmeticSlot, VRRig rig)
		{
			bool flag = CosmeticsController.CosmeticSet.IsSlotLeftHanded(cosmeticSlot);
			bool flag2 = CosmeticsController.CosmeticSet.IsSlotRightHanded(cosmeticSlot);
			_activeSlot = cosmeticSlot;
			if (rig != null && _anchorOverrides == null)
			{
				_anchorOverrides = rig.gameObject.GetComponent<VRRigAnchorOverrides>();
				_bodyDockPositions = rig.GetComponent<BodyDockPositions>();
			}
			foreach (GameObject @object in objects)
			{
				EnableItem(@object, enable: true);
				if (cosmeticSlot != CosmeticsController.CosmeticSlots.Badge)
				{
					continue;
				}
				if (objects.Count > 1)
				{
					if (GTHardCodedBones.TryGetFirstBoneInParents(@object.transform, out var eBone, out var _) && eBone == GTHardCodedBones.EBone.body)
					{
						_anchorOverrides.CurrentBadgeTransform = @object.transform;
					}
				}
				else
				{
					_anchorOverrides.CurrentBadgeTransform = @object.transform;
				}
			}
			if (flag)
			{
				foreach (GameObject leftObject in leftObjects)
				{
					EnableItem(leftObject, enable: true);
				}
			}
			if (flag2)
			{
				foreach (GameObject rightObject in rightObjects)
				{
					EnableItem(rightObject, enable: true);
				}
			}
			ApplyClippingOffsets(itemEnabled: true);
		}

		public void ToggleRenderers(bool enabled)
		{
			for (int i = 0; i < allRenderers.Count; i++)
			{
				allRenderers[i].enabled = enabled;
			}
		}

		public void ToggleParticles(bool enabled)
		{
			for (int i = 0; i < allParticles.Count; i++)
			{
				ParticleSystem.EmissionModule emission = allParticles[i].emission;
				emission.enabled = enabled;
			}
		}
	}
