		public void PressWardrobeFunctionButton(string function)
		{
			switch (function)
			{
			case "left":
				cosmeticsPages[wardrobeType]--;
				if (cosmeticsPages[wardrobeType] < 0)
				{
					cosmeticsPages[wardrobeType] = (itemLists[wardrobeType].Count - 1) / 3;
				}
				break;
			case "right":
				cosmeticsPages[wardrobeType]++;
				if (cosmeticsPages[wardrobeType] > (itemLists[wardrobeType].Count - 1) / 3)
				{
					cosmeticsPages[wardrobeType] = 0;
				}
				break;
			case "hat":
				if (wardrobeType == 0)
				{
					return;
				}
				wardrobeType = 0;
				break;
			case "face":
				if (wardrobeType == 1)
				{
					return;
				}
				wardrobeType = 1;
				break;
			case "badge":
				if (wardrobeType == 2)
				{
					return;
				}
				wardrobeType = 2;
				break;
			case "hand":
				if (wardrobeType == 3)
				{
					return;
				}
				wardrobeType = 3;
				break;
			case "fur":
				if (wardrobeType == 4)
				{
					return;
				}
				wardrobeType = 4;
				break;
			case "outfit":
				if (wardrobeType == 5)
				{
					return;
				}
				wardrobeType = 5;
				break;
			case "arms":
				if (wardrobeType == 6)
				{
					return;
				}
				wardrobeType = 6;
				break;
			case "back":
				if (wardrobeType == 7)
				{
					return;
				}
				wardrobeType = 7;
				break;
			case "chest":
				if (wardrobeType == 8)
				{
					return;
				}
				wardrobeType = 8;
