	public static class GorillaKeyboardBindingExtensions
	{
		public static bool FromNumberBindingToInt(this GorillaKeyboardBindings binding, out int result)
		{
			result = -1;
			switch (binding)
			{
			case GorillaKeyboardBindings.zero:
				result = 0;
				break;
			case GorillaKeyboardBindings.one:
				result = 1;
				break;
			case GorillaKeyboardBindings.two:
				result = 2;
				break;
			case GorillaKeyboardBindings.three:
				result = 3;
				break;
			case GorillaKeyboardBindings.four:
				result = 4;
				break;
			case GorillaKeyboardBindings.five:
				result = 5;
				break;
			case GorillaKeyboardBindings.six:
				result = 6;
				break;
			case GorillaKeyboardBindings.seven:
				result = 7;
				break;
			case GorillaKeyboardBindings.eight:
				result = 8;
				break;
			case GorillaKeyboardBindings.nine:
				result = 9;
				break;
			default:
				return false;
			}
			return true;
		}
	}
	[Serializable]
	public class GorillaText
	{
		private string failureText;

		public string currentText;

		private string originalText = string.Empty;

		private StringBuilder stringBuilder = new StringBuilder();

		private bool modified;

		private bool failedState;

		private Material[] originalMaterials;

		private Material failureMaterial;

		internal Material[] currentMaterials;

		private UnityEvent<string> updateTextCallback;

		private UnityEvent<Material[]> updateMaterialCallback;

		public void Initialize(Material[] originalMaterials, Material failureMaterial, UnityEvent<string> callback = null, UnityEvent<Material[]> materialCallback = null)
		{
			this.failureMaterial = failureMaterial;
			this.originalMaterials = originalMaterials;
			currentMaterials = originalMaterials;
			UnityEngine.Debug.Log("Original text = " + originalText);
			updateTextCallback = callback;
			updateMaterialCallback = materialCallback;
			GorillaTextManager.RegisterText(this);
		}

		public void InvokeIfUpdated()
		{
			if (modified)
			{
				modified = false;
				string text = stringBuilder.ToString();
				if (currentText != text)
				{
					currentText = text;
					updateTextCallback?.Invoke(currentText);
				}
			}
		}

		public void EnableFailedState(string failText)
		{
			failedState = true;
			failureText = failText;
			updateTextCallback?.Invoke(failText);
			originalText = currentText;
			currentText = failText;
			currentMaterials = (Material[])originalMaterials.Clone();
			currentMaterials[0] = failureMaterial;
			updateMaterialCallback?.Invoke(currentMaterials);
		}

		public void DisableFailedState()
		{
			failedState = false;
			updateTextCallback?.Invoke(originalText);
			failureText = "";
			currentText = originalText;
			currentMaterials = originalMaterials;
			updateMaterialCallback?.Invoke(currentMaterials);
		}

		public void Append(string str)
		{
			modified = true;
			stringBuilder.Append(str);
		}

		public void Set(string str)
		{
			modified = true;
			stringBuilder.Clear();
			stringBuilder.Append(str);
		}
	}
	public class GorillaTextManager : MonoBehaviourPostTick
	{
		public static GorillaTextManager instance;

		public List<GorillaText> gorillaTexts = new List<GorillaText>();

		public static void RegisterText(GorillaText text)
		{
			if (instance == null)
			{
				CreateManager();
			}
			if (!instance.gorillaTexts.Contains(text))
			{
				instance.gorillaTexts.Add(text);
			}
		}

		private void Awake()
		{
			if (instance != null)
			{
				UnityEngine.Object.Destroy(base.gameObject);
			}
			else
			{
				instance = this;
			}
		}

		public override void PostTick()
		{
			for (int i = 0; i < gorillaTexts.Count; i++)
			{
				gorillaTexts[i].InvokeIfUpdated();
			}
		}

		public static void CreateManager()
		{
			GorillaTextManager gorillaTextManager = new GameObject("GorillaTextManager").AddComponent<GorillaTextManager>();
			gorillaTextManager.gorillaTexts = new List<GorillaText>();
			instance = gorillaTextManager;
			if (UnityEngine.Application.isPlaying)
			{
				UnityEngine.Object.DontDestroyOnLoad(gorillaTextManager);
			}
		}
	}
