			DeactiveOriginalGameObjects,
			DoNothing
		}

		private int MAX_VERTICES_FOR_16BITS_MESH = 50000;

		private UnityEngine.Vector3 originalPosition = UnityEngine.Vector3.zero;

		private UnityEngine.Vector3 originalEulerAngles = UnityEngine.Vector3.zero;

		private UnityEngine.Vector3 originalScale = UnityEngine.Vector3.zero;

		private List<OriginalGameObjectWithMesh> originalGameObjectsWithMeshToRestore = new List<OriginalGameObjectWithMesh>();

		private bool targetMeshesMerged;

		[HideInInspector]
