		{
			_isActive = active;
			_visuals.SetActive(active);
		}

		public void SetRecordingState(bool isRecording)
		{
			if (_isActive)
			{
				_propertyBlock.SetInt(IS_RECORDING, isRecording ? 1 : 0);
				_bodyRenderer.SetPropertyBlock(_propertyBlock);
			}
		}
	}
