				{
					return false;
				}
				if (BallTrajectoryY != other.BallTrajectoryY)
				{
					return false;
				}
				if (!BallSpeed.Approx(other.BallSpeed))
				{
					return false;
				}
				if (ScoreLeft != other.ScoreLeft)
				{
					return false;
				}
				if (ScoreRight != other.ScoreRight)
				{
