		public void TeleportTo(UnityEngine.Vector3 position, UnityEngine.Quaternion rotation, bool keepVelocity = false, bool center = false)
		{
			if (center)
			{
				UnityEngine.Vector3 position2 = base.transform.position;
				UnityEngine.Vector3 vector = mainCamera.transform.position - position2;
				position -= vector;
			}
			ClearHandHolds();
			if (playerRigidBody != null)
			{
				playerRigidBody.isKinematic = true;
				playerRigidBody.position = position;
				playerRigidBody.rotation = rotation;
				playerRigidBody.isKinematic = false;
			}
			playerRigidBody.position = position;
			playerRigidBody.rotation = rotation;
			base.transform.position = position;
			base.transform.rotation = rotation;
			lastHeadPosition = headCollider.transform.position;
			lastPosition = position;
			lastOpenHeadPosition = headCollider.transform.position;
			leftHand.OnTeleport();
			rightHand.OnTeleport();
			for (int i = 0; i < 12; i++)
			{
				if (stiltStates[i].isActive)
				{
					stiltStates[i].OnTeleport();
				}
			}
			if (!keepVelocity)
			{
				playerRigidBody.linearVelocity = UnityEngine.Vector3.zero;
			}
			bodyCollider.transform.position = PositionWithOffset(headCollider.transform, bodyOffset) + bodyOffsetVector;
			bodyCollider.transform.eulerAngles = new UnityEngine.Vector3(0f, headCollider.transform.eulerAngles.y, 0f);
			Physics.SyncTransforms();
			GorillaTagger.Instance.offlineVRRig.transform.position = position;
			GorillaTagger.Instance.offlineVRRig.leftHandLink.BreakLink();
			GorillaTagger.Instance.offlineVRRig.rightHandLink.BreakLink();
			ForceRigidBodySync();
		}

		public void TeleportTo(Transform destination, bool matchDestinationRotation = true, bool maintainVelocity = true)
		{
			UnityEngine.Vector3 position = base.transform.position;
			UnityEngine.Vector3 vector = mainCamera.transform.position - position;
			UnityEngine.Vector3 position2 = destination.position - vector;
			float num = destination.rotation.eulerAngles.y - mainCamera.transform.rotation.eulerAngles.y;
			UnityEngine.Vector3 playerVelocity = currentVelocity;
			if (!maintainVelocity)
			{
				SetPlayerVelocity(UnityEngine.Vector3.zero);
			}
			else if (matchDestinationRotation)
			{
				playerVelocity = UnityEngine.Quaternion.AngleAxis(num, base.transform.up) * currentVelocity;
				SetPlayerVelocity(playerVelocity);
			}
			if (matchDestinationRotation)
			{
				Turn(num);
			}
			TeleportTo(position2, base.transform.rotation);
			if (maintainVelocity)
			{
				SetPlayerVelocity(playerVelocity);
			}
			ForceRigidBodySync();
		}

		public void AddForce(UnityEngine.Vector3 force, ForceMode mode)
		{
			if (mode == ForceMode.VelocityChange)
			{
				playerRigidBody.AddForce(force * playerRigidBody.mass, ForceMode.Impulse);
			}
			else
			{
				playerRigidBody.AddForce(force, mode);
			}
		}

		public void SetPlayerVelocity(UnityEngine.Vector3 newVelocity)
		{
			for (int i = 0; i < velocityHistory.Length; i++)
			{
				velocityHistory[i] = newVelocity;
			}
			playerRigidBody.AddForce(newVelocity - playerRigidBody.linearVelocity, ForceMode.VelocityChange);
		}

		public void SetGravityOverride(UnityEngine.Object caller, Action<GTPlayer> gravityFunction)
		{
			gravityOverrides[caller] = gravityFunction;
		}

		public void UnsetGravityOverride(UnityEngine.Object caller)
		{
			gravityOverrides.Remove(caller);
		}

		private void ApplyGravityOverrides()
		{
			foreach (KeyValuePair<UnityEngine.Object, Action<GTPlayer>> gravityOverride in gravityOverrides)
			{
				gravityOverride.Value(this);
			}
		}

		public void ApplyKnockback(UnityEngine.Vector3 direction, float speed, bool forceOffTheGround = false)
		{
			if (forceOffTheGround)
			{
				if (leftHand.wasColliding || rightHand.wasColliding)
				{
					leftHand.wasColliding = false;
					rightHand.wasColliding = false;
					playerRigidBody.transform.position += minimumRaycastDistance * scale * UnityEngine.Vector3.up;
				}
				didAJump = true;
				SetMaximumSlipThisFrame();
			}
			if (speed > 0.01f)
			{
				float num = UnityEngine.Vector3.Dot(averagedVelocity, direction);
				float num2 = Mathf.InverseLerp(1.5f, 0.5f, num / speed);
				UnityEngine.Vector3 vector = averagedVelocity + direction * speed * num2;
				playerRigidBody.linearVelocity = vector;
				for (int i = 0; i < velocityHistory.Length; i++)
				{
					velocityHistory[i] = vector;
				}
			}
		}

		public void ApplyClampedKnockback(UnityEngine.Vector3 direction, float speed, float boostMultiplier, bool forceOffTheGround = false)
		{
			if (forceOffTheGround)
			{
				if (leftHand.wasColliding || rightHand.wasColliding)
				{
					leftHand.wasColliding = false;
					rightHand.wasColliding = false;
					playerRigidBody.transform.position += minimumRaycastDistance * scale * UnityEngine.Vector3.up;
				}
				didAJump = true;
				SetMaximumSlipThisFrame();
			}
			if (!(speed > 0.01f))
			{
				return;
			}
			float num = UnityEngine.Vector3.Dot(playerRigidBody.linearVelocity, direction.normalized);
			if (!(num >= speed))
			{
				float num2 = Mathf.Clamp(speed - num, 0f, speed * boostMultiplier);
				UnityEngine.Vector3 vector = playerRigidBody.linearVelocity + direction.normalized * num2;
				playerRigidBody.linearVelocity = vector;
				for (int i = 0; i < velocityHistory.Length; i++)
				{
					velocityHistory[i] = vector;
				}
			}
		}

