		}

		private void BodyCollider()
		{
			if (MaxSphereSizeForNoOverlap(bodyInitialRadius * scale, PositionWithOffset(headCollider.transform, bodyOffset), ignoreOneWay: false, out bodyMaxRadius))
			{
				if (scale > 0f)
				{
