				headOverlappingWaterVolumes.Remove(volume);
			}
			else if (playerCollider == bodyCollider)
			{
				bodyOverlappingWaterVolumes.Remove(volume);
			}
		}

		private bool GetSwimmingVelocityForHand(UnityEngine.Vector3 startingHandPosition, UnityEngine.Vector3 endingHandPosition, UnityEngine.Vector3 palmForwardDirection, float dt, ref WaterVolume contactingWaterVolume, ref WaterVolume.SurfaceQuery waterSurface, out UnityEngine.Vector3 swimmingVelocityChange)
		{
			contactingWaterVolume = null;
			bufferCount = Physics.OverlapSphereNonAlloc(endingHandPosition, minimumRaycastDistance, overlapColliders, waterLayer.value, QueryTriggerInteraction.Collide);
			if (bufferCount > 0)
			{
				float num = float.MinValue;
				for (int i = 0; i < bufferCount; i++)
				{
					WaterVolume component = overlapColliders[i].GetComponent<WaterVolume>();
					if (component != null && component.GetSurfaceQueryForPoint(endingHandPosition, out var result))
					{
						float num2 = UnityEngine.Vector3.Dot(result.surfacePoint, GTPlayerTransform.PhysicsUp);
						if (num2 > num)
						{
							num = num2;
							contactingWaterVolume = component;
							waterSurface = result;
						}
					}
				}
			}
			if (forcedUnderwater || contactingWaterVolume != null)
			{
				UnityEngine.Vector3 vector = endingHandPosition - startingHandPosition;
				UnityEngine.Vector3 vector2 = UnityEngine.Vector3.zero;
				UnityEngine.Vector3 vector3 = playerRigidBody.transform.position - lastRigidbodyPosition;
				if (turnedThisFrame)
				{
					UnityEngine.Vector3 vector4 = startingHandPosition - headCollider.transform.position;
					vector2 = UnityEngine.Quaternion.AngleAxis(degreesTurnedThisFrame, GTPlayerTransform.PhysicsUp) * vector4 - vector4;
				}
				float num3 = UnityEngine.Vector3.Dot(vector - vector2 - vector3, palmForwardDirection);
				float num4 = 0f;
				if (num3 > 0f)
				{
					float num5 = -1f;
					float num6 = -1f;
					if (!forcedUnderwater)
					{
						UnityEngine.Plane surfacePlane = waterSurface.surfacePlane;
						num5 = (forcedUnderwater ? (-1f) : surfacePlane.GetDistanceToPoint(startingHandPosition));
						num6 = (forcedUnderwater ? (-1f) : surfacePlane.GetDistanceToPoint(endingHandPosition));
					}
					if (num5 <= 0f && num6 <= 0f)
					{
						num4 = 1f;
					}
					else if (num5 > 0f && num6 <= 0f)
					{
						num4 = (0f - num6) / (num5 - num6);
					}
					else if (num5 <= 0f && num6 > 0f)
					{
						num4 = (0f - num5) / (num6 - num5);
					}
					if (num4 > Mathf.Epsilon)
					{
						float resistance = liquidPropertiesList[(int)((!forcedUnderwater) ? contactingWaterVolume.LiquidType : LiquidType.Water)].resistance;
						swimmingVelocityChange = -palmForwardDirection * num3 * 2f * resistance * num4;
						UnityEngine.Vector3 forward = mainCamera.transform.forward;
						if (UnityEngine.Vector3.Dot(forward, GTPlayerTransform.PhysicsDown) > 0f)
						{
							UnityEngine.Vector3 vector5 = UnityEngine.Vector3.ProjectOnPlane(forward, GTPlayerTransform.PhysicsUp);
							float magnitude = vector5.magnitude;
							vector5 /= magnitude;
							float num7 = UnityEngine.Vector3.Dot(swimmingVelocityChange, vector5);
							if (num7 > 0f)
							{
								UnityEngine.Vector3 vector6 = vector5 * num7;
								float num8 = UnityEngine.Vector3.Dot(forward, GTPlayerTransform.PhysicsUp);
								swimmingVelocityChange = swimmingVelocityChange - vector6 + vector6 * magnitude + GTPlayerTransform.PhysicsUp * num8 * num7;
							}
						}
						return true;
					}
				}
			}
			swimmingVelocityChange = UnityEngine.Vector3.zero;
			return false;
		}

		private bool CheckWaterSurfaceJump(UnityEngine.Vector3 startingHandPosition, UnityEngine.Vector3 endingHandPosition, UnityEngine.Vector3 palmForwardDirection, UnityEngine.Vector3 handAvgVelocity, PlayerSwimmingParameters parameters, WaterVolume contactingWaterVolume, WaterVolume.SurfaceQuery waterSurface, out UnityEngine.Vector3 jumpVelocity)
		{
			if (contactingWaterVolume != null)
			{
				UnityEngine.Plane surfacePlane = waterSurface.surfacePlane;
				bool flag = handAvgVelocity.sqrMagnitude > parameters.waterSurfaceJumpHandSpeedThreshold * parameters.waterSurfaceJumpHandSpeedThreshold;
				if (surfacePlane.GetSide(startingHandPosition) && !surfacePlane.GetSide(endingHandPosition) && flag)
				{
					float value = UnityEngine.Vector3.Dot(palmForwardDirection, -waterSurface.surfaceNormal);
					float value2 = UnityEngine.Vector3.Dot(handAvgVelocity.normalized, -waterSurface.surfaceNormal);
					float num = parameters.waterSurfaceJumpPalmFacingCurve.Evaluate(Mathf.Clamp(value, 0.01f, 0.99f));
					float num2 = parameters.waterSurfaceJumpHandVelocityFacingCurve.Evaluate(Mathf.Clamp(value2, 0.01f, 0.99f));
					jumpVelocity = -handAvgVelocity * parameters.waterSurfaceJumpAmount * num * num2;
					return true;
				}
			}
			jumpVelocity = UnityEngine.Vector3.zero;
			return false;
		}

		private bool TryNormalize(UnityEngine.Vector3 input, out UnityEngine.Vector3 normalized, out float magnitude, float eps = 0.0001f)
		{
			magnitude = input.magnitude;
			if (magnitude > eps)
			{
				normalized = input / magnitude;
				return true;
			}
			normalized = UnityEngine.Vector3.zero;
			return false;
		}

		private bool TryNormalizeDown(UnityEngine.Vector3 input, out UnityEngine.Vector3 normalized, out float magnitude, float eps = 0.0001f)
		{
			magnitude = input.magnitude;
			if (magnitude > 1f)
			{
				normalized = input / magnitude;
				return true;
			}
			if (magnitude >= eps)
			{
				normalized = input;
				return true;
			}
			normalized = UnityEngine.Vector3.zero;
			return false;
		}

		private float FreezeTagSlidePercentage()
		{
			if (materialData[currentMaterialIndex].overrideSlidePercent && materialData[currentMaterialIndex].slidePercent > freezeTagHandSlidePercent)
			{
				return materialData[currentMaterialIndex].slidePercent;
			}
			return freezeTagHandSlidePercent;
		}

		private void OnCollisionStay(UnityEngine.Collision collision)
		{
			bodyCollisionContactsCount = collision.GetContacts(bodyCollisionContacts);
			float num = -1f;
			for (int i = 0; i < bodyCollisionContactsCount; i++)
			{
				float num2 = UnityEngine.Vector3.Dot(bodyCollisionContacts[i].normal, UnityEngine.Vector3.up);
				if (num2 > num)
				{
					bodyGroundContact = bodyCollisionContacts[i];
					num = num2;
				}
			}
			_ = -1f;
			float num3 = 0.5f;
			if (num > num3)
			{
				bodyGroundContactTime = Time.time;
				Collider otherCollider = bodyGroundContact.otherCollider;
				bodyGroundIsSlippery = otherCollider != null && otherCollider.sharedMaterial != null && otherCollider.sharedMaterial.staticFriction <= 0.0001f && otherCollider.sharedMaterial.dynamicFriction <= 0.0001f;
			}
		}

