		internal void ClearHandHolds()
		{
			leftHand.isHolding = false;
			rightHand.isHolding = false;
			wasHoldingHandhold = false;
			activeHandHold = default(HandHoldState);
			secondaryHandHold = default(HandHoldState);
			OnChangeActiveHandhold();
		}

		internal void AddHandHold(Transform objectHeld, UnityEngine.Vector3 localPositionHeld, GorillaGrabber grabber, bool forLeftHand, bool rotatePlayerWhenHeld, out UnityEngine.Vector3 grabbedVelocity)
		{
			if (!leftHand.isHolding && !rightHand.isHolding)
			{
				grabbedVelocity = -bodyCollider.attachedRigidbody.linearVelocity;
				playerRigidBody.AddForce(grabbedVelocity, ForceMode.VelocityChange);
			}
			else
			{
				grabbedVelocity = UnityEngine.Vector3.zero;
			}
			secondaryHandHold = activeHandHold;
			_ = grabber.transform.position;
			activeHandHold = new HandHoldState
			{
				grabber = grabber,
				objectHeld = objectHeld,
				localPositionHeld = localPositionHeld,
				localRotationalOffset = grabber.transform.rotation.eulerAngles.y - objectHeld.rotation.eulerAngles.y,
				applyRotation = rotatePlayerWhenHeld
			};
			if (forLeftHand)
			{
				leftHand.isHolding = true;
			}
			else
			{
				rightHand.isHolding = true;
			}
			OnChangeActiveHandhold();
		}

		internal void RemoveHandHold(GorillaGrabber grabber, bool forLeftHand)
		{
			_ = activeHandHold.objectHeld == grabber;
			if (activeHandHold.grabber == grabber)
			{
				activeHandHold = secondaryHandHold;
			}
			secondaryHandHold = default(HandHoldState);
			if (forLeftHand)
			{
				leftHand.isHolding = false;
			}
			else
			{
				rightHand.isHolding = false;
			}
			OnChangeActiveHandhold();
		}

		private void OnChangeActiveHandhold()
		{
			if (activeHandHold.objectHeld != null)
			{
				if (activeHandHold.objectHeld.TryGetComponent<PhotonView>(out var component))
				{
					VRRig.AttachLocalPlayerToPhotonView(component, activeHandHold.grabber.XrNode, activeHandHold.localPositionHeld, averagedVelocity);
					return;
				}
				if (activeHandHold.objectHeld.TryGetComponent<PhotonViewXSceneRef>(out var component2))
				{
					PhotonView photonView = component2.photonView;
					if ((object)photonView != null)
					{
						VRRig.AttachLocalPlayerToPhotonView(photonView, activeHandHold.grabber.XrNode, activeHandHold.localPositionHeld, averagedVelocity);
						return;
					}
				}
				if (activeHandHold.objectHeld.TryGetComponent<BuilderPieceHandHold>(out var component3) && component3.IsHandHoldMoving())
				{
					isHandHoldMoving = true;
					lastHandHoldRotation = component3.transform.rotation;
					movingHandHoldReleaseVelocity = playerRigidBody.linearVelocity;
				}
				else
				{
					isHandHoldMoving = false;
					lastHandHoldRotation = UnityEngine.Quaternion.identity;
					movingHandHoldReleaseVelocity = UnityEngine.Vector3.zero;
				}
			}
			VRRig.DetachLocalPlayerFromPhotonView();
		}

		private void FixedUpdate_HandHolds(float timeDelta)
		{
			if (activeHandHold.objectHeld == null)
			{
				if (wasHoldingHandhold)
				{
					playerRigidBody.linearVelocity = UnityEngine.Vector3.ClampMagnitude(secondLastPreHandholdVelocity, 5.5f * scale);
				}
				wasHoldingHandhold = false;
				return;
			}
			UnityEngine.Vector3 vector = activeHandHold.objectHeld.TransformPoint(activeHandHold.localPositionHeld);
			UnityEngine.Vector3 position = activeHandHold.grabber.transform.position;
			secondLastPreHandholdVelocity = lastPreHandholdVelocity;
			lastPreHandholdVelocity = playerRigidBody.linearVelocity;
			wasHoldingHandhold = true;
			if (isHandHoldMoving)
			{
				lastPreHandholdVelocity = movingHandHoldReleaseVelocity;
				playerRigidBody.linearVelocity = UnityEngine.Vector3.zero;
				UnityEngine.Vector3 vector2 = vector - position;
				playerRigidBody.transform.position += vector2;
				movingHandHoldReleaseVelocity = vector2 / timeDelta;
				UnityEngine.Quaternion rotationDelta = activeHandHold.objectHeld.rotation * UnityEngine.Quaternion.Inverse(lastHandHoldRotation);
				RotateWithSurface(rotationDelta, vector);
				lastHandHoldRotation = activeHandHold.objectHeld.rotation;
			}
			else
			{
				playerRigidBody.linearVelocity = (vector - position) / timeDelta;
				if (activeHandHold.applyRotation)
				{
					turnParent.transform.RotateAround(vector, base.transform.up, activeHandHold.localRotationalOffset - (activeHandHold.grabber.transform.rotation.eulerAngles.y - activeHandHold.objectHeld.rotation.eulerAngles.y));
				}
			}
		}
	}
	public class GTPlayerTransform : MonkeGravityController
	{
		private static UnityEngine.Vector3 k_rotationPosOffsetChange = UnityEngine.Vector3.zero;

		private static Transform k_transform;

		private static Rigidbody k_rigidBody;

		private static Transform k_bodyTransform;

		private static GTPlayer k_playerInstance;

		private static int k_rotationOverrideFrameTime;

		[SerializeField]
		private Transform m_gtPlayerBodyTransform;

		[SerializeField]
		private GTPlayer m_gtPlayerInstance;

		public static UnityEngine.Vector3 Up { get; private set; } = UnityEngine.Vector3.up;

		public static UnityEngine.Vector3 PhysicsUp { get; private set; } = UnityEngine.Vector3.up;

		public static UnityEngine.Vector3 Down { get; private set; } = UnityEngine.Vector3.down;

		public static UnityEngine.Vector3 PhysicsDown { get; private set; } = UnityEngine.Vector3.down;

		public static UnityEngine.Vector3 Forward { get; private set; } = UnityEngine.Vector3.forward;

		public static UnityEngine.Vector3 Right { get; private set; } = UnityEngine.Vector3.right;

		public static UnityEngine.Quaternion BodyRotation => k_bodyTransform.rotation;

		public static bool UseNetRotation => true;

		public static bool IgnoreGravityRotation { get; set; } = false;

		public static bool IgnoreGravityForce { get; set; } = false;

		public static UnityEngine.Vector3 RotationPosOffsetChange => k_rotationPosOffsetChange;

		public static GTPlayerTransform Instance { get; private set; }

		public override float Scale => VRRig.LocalRig.scaleFactor;

		public static void RotateToUp(in UnityEngine.Vector3 targetUp)
		{
			if (targetUp == Up)
			{
				Instance.ClearRotationRecovery();
			}
			else
			{
				RotateFromToDirection(Up, in targetUp);
			}
		}

		public static void RotateToForward(in UnityEngine.Vector3 targetForward)
		{
			if (!(targetForward == Forward))
			{
				RotateFromToDirection(Forward, in targetForward);
			}
		}

		public static void RotateFromToDirection(in UnityEngine.Vector3 currentDir, in UnityEngine.Vector3 targetDir)
		{
			UnityEngine.Quaternion currentRotation = k_transform.rotation;
			SetRotation(UnityEngine.Quaternion.FromToRotation(currentDir, targetDir) * currentRotation, in currentRotation);
		}

		public static void RotateBy(in UnityEngine.Quaternion rotation)
		{
			UnityEngine.Quaternion currentRotation = k_transform.rotation;
			SetRotation(currentRotation * rotation, in currentRotation);
		}

		public static void SetRotation(in UnityEngine.Quaternion targetRotation)
		{
			SetRotation(in targetRotation, k_transform.rotation);
		}

		private static void SetRotation(in UnityEngine.Quaternion newRotation, in UnityEngine.Quaternion currentRotation)
		{
			ref readonly GTPlayer.HandState leftHandRef = ref k_playerInstance.LeftHandRef;
			ref readonly GTPlayer.HandState rightHandRef = ref k_playerInstance.RightHandRef;
			UnityEngine.Vector3 pivotPoint = k_transform.position;
			UnityEngine.Quaternion rotation = newRotation * UnityEngine.Quaternion.Inverse(currentRotation);
			UnityEngine.Vector3 rotatedDifference = GetRotatedDifference(in pivotPoint, k_bodyTransform.position, in rotation);
			if (leftHandRef.wasColliding || leftHandRef.wasSliding)
			{
				UnityEngine.Vector3 rotatedDifference2 = GetRotatedDifference(in pivotPoint, in leftHandRef.lastPosition, in rotation);
				if (UnityEngine.Vector3.Dot(UnityEngine.Vector3.Normalize(rotatedDifference2), leftHandRef.lastHitInfo.normal) <= 0f)
				{
					rotatedDifference -= rotatedDifference2;
				}
			}
			if (rightHandRef.wasColliding || rightHandRef.wasSliding)
			{
				UnityEngine.Vector3 rotatedDifference3 = GetRotatedDifference(in pivotPoint, in rightHandRef.lastPosition, in rotation);
				if (UnityEngine.Vector3.Dot(UnityEngine.Vector3.Normalize(rotatedDifference3), rightHandRef.lastHitInfo.normal) <= 0f)
				{
					rotatedDifference -= rotatedDifference3;
				}
			}
			k_rotationPosOffsetChange -= rotatedDifference;
			k_rigidBody.position = pivotPoint - rotatedDifference;
			k_rigidBody.rotation = newRotation;
			Up = newRotation * UnityEngine.Vector3.up;
			Down = Up * -1f;
			Forward = newRotation * UnityEngine.Vector3.forward;
			Right = newRotation * UnityEngine.Vector3.right;
		}

		private static UnityEngine.Vector3 GetRotatedDifference(in UnityEngine.Vector3 pivotPoint, in UnityEngine.Vector3 worldPoint, in UnityEngine.Quaternion rotation)
		{
			UnityEngine.Vector3 vector = worldPoint - pivotPoint;
			return rotation * vector - vector;
		}

		public static void ApplyRotationOverride(in UnityEngine.Quaternion rotation, int frameTime)
		{
			SetRotation(in rotation);
			k_rotationOverrideFrameTime = frameTime;
		}

		public static void ResetRotationPositionOffset()
		{
			k_rotationPosOffsetChange = UnityEngine.Vector3.zero;
		}

		public static void EnableNetworkRotations()
		{
		}

		public static void DisableNetworkRotations()
		{
		}

		protected override void Awake()
		{
			base.Awake();
			if (!base.Register)
			{
				UnityEngine.Debug.LogError("GTPlayerTransform: failed to load required references", base.gameObject);
			}
			Instance = this;
			k_transform = m_targetTransform;
			k_rigidBody = m_targetRigidBody;
			k_bodyTransform = m_gtPlayerBodyTransform;
			k_playerInstance = m_gtPlayerInstance;
			Up = k_transform.up;
			Forward = k_transform.forward;
			Right = k_transform.right;
			Down = Up * -1f;
			m_globalGravityIntent = false;
		}

		public override void ApplyGravityUpRotation(in UnityEngine.Vector3 upDir, float speed)
		{
			if (IgnoreGravityRotation || k_rotationOverrideFrameTime >= Time.frameCount - 1)
			{
				return;
			}
			if (base.InstantRotation)
			{
				RotateToUp(in upDir);
				return;
			}
			float num = UnityEngine.Vector3.Angle(Up, upDir);
			UnityEngine.Vector3 targetUp;
			if (num * (MathF.PI / 180f) <= speed)
			{
				targetUp = upDir;
			}
			else
			{
				UnityEngine.Vector3 target = upDir;
				if (Mathf.Approximately(num, 180f))
				{
					switch (m_preferredRotationDirection)
					{
					case RotationDirection.Left:
						target = k_bodyTransform.right * -1f;
						break;
					case RotationDirection.Right:
						target = k_bodyTransform.right;
						break;
					case RotationDirection.Forward:
						target = k_bodyTransform.forward;
						break;
					case RotationDirection.Backward:
						target = k_bodyTransform.forward * -1f;
						break;
					}
				}
				targetUp = UnityEngine.Vector3.RotateTowards(Up, target, speed, 0f);
			}
			RotateToUp(in targetUp);
		}

		public override void ApplyGravityForce(in UnityEngine.Vector3 force, ForceMode forceType = ForceMode.Acceleration)
		{
			if (!IgnoreGravityForce && !k_playerInstance.isClimbing && k_playerInstance.GravityOverrideCount <= 0)
			{
				base.ApplyGravityForce(force * k_playerInstance.scale, forceType);
			}
		}

		public override UnityEngine.Vector3 GetWorldPoint()
		{
			return k_bodyTransform.position;
		}

		public override void CallBack()
		{
			base.CallBack();
			PhysicsUp = base.GravityUp;
			PhysicsDown = base.GravityDown;
			if (base.GravityZonesCount <= 0 && Up != PhysicsUp)
			{
				ApplyGravityUpRotation(PhysicsUp, MonkeGravityManager.DefaultGravityInfo.rotationSpeed * Time.fixedDeltaTime);
			}
		}
	}
	public sealed class Playspace : MonoBehaviour
	{
		[SerializeField]
		private GameObject _localGorillaHead;

		[SerializeField]
		private float _sphereRadius;

		private float _sqrSphereRadius;

		[SerializeField]
		private float _defaultChaseSpeed;

		[SerializeField]
		private float _snapToThreshold;

		private float _sqrSnapToThreshold;

		[SerializeField]
		private GTPlayer m_gtPlayer;

		[SerializeField]
		private XROrigin m_xrOrigin;

		private Transform m_xrBody;

		private void Awake()
		{
			_sqrSphereRadius = _sphereRadius * _sphereRadius;
			_sqrSnapToThreshold = _snapToThreshold * _snapToThreshold;
		}

		private void Start()
		{
		}

		private void Update()
		{
			UnityEngine.Vector3 vector = _localGorillaHead.transform.position - base.transform.position;
			float sqrMagnitude = vector.sqrMagnitude;
			if (GTPlayer.Instance.enableHoverMode || GTPlayer.Instance.isClimbing || vector.sqrMagnitude > _sqrSnapToThreshold)
			{
				base.transform.position = _localGorillaHead.transform.position;
				return;
			}
			UnityEngine.Vector3 normalized = vector.normalized;
			vector = GetChaseSpeed() * Time.deltaTime * normalized;
			base.transform.position = ((vector.sqrMagnitude > sqrMagnitude) ? _localGorillaHead.transform.position : (base.transform.position + vector));
			if ((_localGorillaHead.transform.position - base.transform.position).sqrMagnitude > _sqrSphereRadius)
			{
				_localGorillaHead.transform.position = base.transform.position + _sphereRadius * normalized;
			}
		}

		private float GetChaseSpeed()
		{
			return _defaultChaseSpeed;
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.DrawWireSphere(base.transform.position, _sphereRadius);
		}
	}
