	[RequireComponent(typeof(Rigidbody))]
	public class RigidbodyWaterInteraction : MonoBehaviour
	{
		public bool applyDamping = true;

		public bool applyBuoyancyForce = true;

		public bool applyAngularDrag = true;

		public bool applyWaterCurrents = true;

		public bool applySurfaceTorque = true;

		public float underWaterDampingHalfLife = 0.25f;

		public float waterSurfaceDampingHalfLife = 1f;

		public float underWaterBuoyancyFactor = 0.5f;

		public float angularDrag = 0.5f;

		public float surfaceTorqueAmount = 0.5f;

		public bool enablePreciseWaterCollision;

		public float objectRadiusForWaterCollision = 0.25f;

		[Range(0f, 1f)]
		public float buoyancyEquilibrium = 0.8f;

		private Rigidbody rb;

		private List<WaterVolume> overlappingWaterVolumes = new List<WaterVolume>();

		private List<WaterCurrent> activeWaterCurrents = new List<WaterCurrent>(16);

		private float baseAngularDrag = 0.05f;

		protected void Awake()
		{
			rb = GetComponent<Rigidbody>();
			baseAngularDrag = rb.angularDamping;
			RigidbodyWaterInteractionManager.RegisterRBWI(this);
		}

		protected void OnEnable()
		{
			overlappingWaterVolumes.Clear();
			RigidbodyWaterInteractionManager.RegisterRBWI(this);
		}

		protected void OnDisable()
		{
			overlappingWaterVolumes.Clear();
			RigidbodyWaterInteractionManager.UnregisterRBWI(this);
		}

		private void OnDestroy()
		{
			RigidbodyWaterInteractionManager.UnregisterRBWI(this);
		}

		public void InvokeFixedUpdate()
		{
			if (rb.isKinematic)
			{
				return;
			}
			bool flag = overlappingWaterVolumes.Count > 0;
			WaterVolume.SurfaceQuery surfaceQuery = default(WaterVolume.SurfaceQuery);
			float num = float.MinValue;
			if (flag && enablePreciseWaterCollision)
			{
				UnityEngine.Vector3 vector = base.transform.position + GTPlayerTransform.PhysicsDown * 2f * objectRadiusForWaterCollision * buoyancyEquilibrium;
				bool flag2 = false;
				activeWaterCurrents.Clear();
				for (int i = 0; i < overlappingWaterVolumes.Count; i++)
				{
					if (overlappingWaterVolumes[i].GetSurfaceQueryForPoint(vector, out var result))
					{
						float num2 = UnityEngine.Vector3.Dot(result.surfacePoint - vector, result.surfaceNormal);
						if (num2 > num)
						{
							num = num2;
							surfaceQuery = result;
							flag2 = true;
						}
						WaterCurrent current = overlappingWaterVolumes[i].Current;
						if (applyWaterCurrents && current != null && num2 > 0f && !activeWaterCurrents.Contains(current))
						{
							activeWaterCurrents.Add(current);
						}
					}
				}
				if (flag2)
				{
					bool num3 = num > (0f - (1f - buoyancyEquilibrium)) * 2f * objectRadiusForWaterCollision;
					float num4 = (enablePreciseWaterCollision ? objectRadiusForWaterCollision : 0f);
					UnityEngine.Vector3 vector2 = surfaceQuery.surfacePoint - surfaceQuery.surfaceNormal * surfaceQuery.maxDepth;
					bool flag3 = UnityEngine.Vector3.Dot(base.transform.position + surfaceQuery.surfaceNormal * num4 - vector2, surfaceQuery.surfaceNormal) > 0f;
					flag = num3 && flag3;
				}
				else
				{
					flag = false;
				}
			}
			if (flag)
			{
				float fixedDeltaTime = Time.fixedDeltaTime;
				UnityEngine.Vector3 vector3 = rb.linearVelocity;
				UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
				if (applyWaterCurrents)
				{
					UnityEngine.Vector3 zero2 = UnityEngine.Vector3.zero;
					for (int j = 0; j < activeWaterCurrents.Count; j++)
					{
						if (activeWaterCurrents[j].GetCurrentAtPoint(startingVelocity: vector3 + zero, worldPoint: base.transform.position, dt: fixedDeltaTime, currentVelocity: out var currentVelocity, velocityChange: out var velocityChange))
						{
							zero2 += currentVelocity;
							zero += velocityChange;
						}
					}
					if (enablePreciseWaterCollision)
					{
						UnityEngine.Vector3 position = (surfaceQuery.surfacePoint + (base.transform.position + GTPlayerTransform.PhysicsDown * objectRadiusForWaterCollision)) * 0.5f;
						rb.AddForceAtPosition(zero * rb.mass, position, ForceMode.Impulse);
					}
					else
					{
						vector3 += zero;
					}
				}
				if (applyBuoyancyForce)
				{
					UnityEngine.Vector3 zero3 = UnityEngine.Vector3.zero;
					if (enablePreciseWaterCollision)
					{
						float b = 2f * objectRadiusForWaterCollision * buoyancyEquilibrium;
						float num5 = Mathf.InverseLerp(0f, b, num);
						zero3 = GTPlayerTransform.PhysicsUp * Physics.gravity.magnitude * underWaterBuoyancyFactor * num5 * fixedDeltaTime;
					}
					else
					{
						zero3 = GTPlayerTransform.PhysicsUp * Physics.gravity.magnitude * underWaterBuoyancyFactor * fixedDeltaTime;
					}
					if (zero.sqrMagnitude > 0.001f)
					{
						float magnitude = zero.magnitude;
						UnityEngine.Vector3 vector4 = zero / magnitude;
						float num6 = UnityEngine.Vector3.Dot(zero3, vector4);
						if (num6 < 0f)
						{
							zero3 -= num6 * vector4;
						}
					}
					vector3 += zero3;
				}
				float magnitude2 = vector3.magnitude;
				if (magnitude2 > 0.001f && applyDamping)
				{
					UnityEngine.Vector3 vector5 = vector3 / magnitude2;
					float num7 = Spring.DamperDecayExact(magnitude2, underWaterDampingHalfLife, fixedDeltaTime);
					if (enablePreciseWaterCollision)
					{
						float a = Spring.DamperDecayExact(magnitude2, waterSurfaceDampingHalfLife, fixedDeltaTime);
						float t = Mathf.Clamp((0f - UnityEngine.Vector3.Dot(base.transform.position - surfaceQuery.surfacePoint, surfaceQuery.surfaceNormal)) / objectRadiusForWaterCollision, -1f, 1f) * 0.5f + 0.5f;
						vector3 = Mathf.Lerp(a, num7, t) * vector5;
					}
					else
					{
						vector3 = num7 * vector5;
					}
				}
				if (applySurfaceTorque && enablePreciseWaterCollision)
				{
					float num8 = UnityEngine.Vector3.Dot(base.transform.position - surfaceQuery.surfacePoint, surfaceQuery.surfaceNormal);
					if (num8 < objectRadiusForWaterCollision && num8 > 0f)
					{
						UnityEngine.Vector3 rhs = vector3 - UnityEngine.Vector3.Dot(vector3, surfaceQuery.surfaceNormal) * surfaceQuery.surfaceNormal;
						UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(surfaceQuery.surfaceNormal, rhs).normalized;
						float num9 = UnityEngine.Vector3.Dot(rb.angularVelocity, normalized);
						float num10 = rhs.magnitude / objectRadiusForWaterCollision - num9;
						if (num10 > 0f)
						{
							rb.AddTorque(surfaceTorqueAmount * num10 * normalized, ForceMode.Acceleration);
						}
					}
				}
				rb.linearVelocity = vector3;
				rb.angularDamping = angularDrag;
			}
			else
			{
				rb.angularDamping = baseAngularDrag;
			}
		}

		protected void OnTriggerEnter(Collider other)
		{
			WaterVolume component = other.GetComponent<WaterVolume>();
			if (component != null && !overlappingWaterVolumes.Contains(component))
			{
				overlappingWaterVolumes.Add(component);
			}
		}

		protected void OnTriggerExit(Collider other)
		{
			WaterVolume component = other.GetComponent<WaterVolume>();
			if (component != null && overlappingWaterVolumes.Contains(component))
			{
				overlappingWaterVolumes.Remove(component);
			}
		}
	}
	public class RigidbodyWaterInteractionManager : MonoBehaviour
	{
		public static RigidbodyWaterInteractionManager instance;

		[OnEnterPlay_Set(false)]
		public static bool hasInstance = false;

		public static List<RigidbodyWaterInteraction> allrBWI = new List<RigidbodyWaterInteraction>();

		protected void Awake()
		{
			if (hasInstance && instance != this)
			{
				UnityEngine.Object.Destroy(this);
			}
			else
			{
				SetInstance(this);
			}
		}

		public static void CreateManager()
		{
			SetInstance(new GameObject("RigidbodyWaterInteractionManager").AddComponent<RigidbodyWaterInteractionManager>());
		}

		private static void SetInstance(RigidbodyWaterInteractionManager manager)
		{
			instance = manager;
			hasInstance = true;
			if (UnityEngine.Application.isPlaying)
			{
				UnityEngine.Object.DontDestroyOnLoad(manager);
			}
		}

		public static void RegisterRBWI(RigidbodyWaterInteraction rbWI)
		{
			if (!hasInstance)
			{
				CreateManager();
			}
			if (!allrBWI.Contains(rbWI))
			{
				allrBWI.Add(rbWI);
			}
		}

		public static void UnregisterRBWI(RigidbodyWaterInteraction rbWI)
		{
			if (!hasInstance)
			{
				CreateManager();
			}
			if (allrBWI.Contains(rbWI))
			{
				allrBWI.Remove(rbWI);
			}
		}

		public void FixedUpdate()
		{
			for (int i = 0; i < allrBWI.Count; i++)
			{
				allrBWI[i].InvokeFixedUpdate();
			}
		}
	}
	[ExecuteAlways]
	public class UnderwaterCameraEffect : MonoBehaviour
	{
		private enum CameraOverlapWaterState
		{
			Uninitialized,
			OutOfWater,
			PartiallySubmerged,
			FullySubmerged
		}

		private const float edgeBuffer = 0.04f;

		[SerializeField]
		private Camera targetCamera;

		[SerializeField]
		private MeshRenderer planeRenderer;

		[SerializeField]
		private UnderwaterParticleEffects underwaterParticleEffect;

		[SerializeField]
		private float distanceFromCamera = 0.02f;

		[SerializeField]
		[DebugOption]
		private bool debugDraw;

		private float cachedAspectRatio = 1f;

		private float cachedFov = 90f;

		private readonly UnityEngine.Vector3[] frustumPlaneCornersLocal = new UnityEngine.Vector3[4];

		private UnityEngine.Vector2 frustumPlaneExtents;

		private GTPlayer player;

		private WaterVolume.SurfaceQuery waterSurface;

		private const string kShaderKeyword_GlobalCameraTouchingWater = "_GLOBAL_CAMERA_TOUCHING_WATER";

		private const string kShaderKeyword_GlobalCameraFullyUnderwater = "_GLOBAL_CAMERA_FULLY_UNDERWATER";

		private int shaderParam_GlobalCameraOverlapWaterSurfacePlane = Shader.PropertyToID("_GlobalCameraOverlapWaterSurfacePlane");

		private bool hasTargetCamera;

		[DebugReadout]
		private CameraOverlapWaterState cameraOverlapWaterState;

		private void SetOffScreenPosition()
		{
			base.transform.localScale = new UnityEngine.Vector3(2f * (frustumPlaneExtents.x + 0.04f), 0f, 1f);
			base.transform.localPosition = new UnityEngine.Vector3(0f, 0f - (frustumPlaneExtents.y + 0.04f), distanceFromCamera);
		}

		private void SetFullScreenPosition()
		{
			base.transform.localScale = new UnityEngine.Vector3(2f * (frustumPlaneExtents.x + 0.04f), 2f * (frustumPlaneExtents.y + 0.04f), 1f);
			base.transform.localPosition = new UnityEngine.Vector3(0f, 0f, distanceFromCamera);
		}

		private void OnEnable()
		{
			if (targetCamera == null)
			{
				targetCamera = Camera.main;
			}
			hasTargetCamera = targetCamera != null;
			InitializeShaderProperties();
		}

		private void Start()
		{
			player = GTPlayer.Instance;
			cachedAspectRatio = targetCamera.aspect;
			cachedFov = targetCamera.fieldOfView;
			CalculateFrustumPlaneBounds(cachedFov, cachedAspectRatio);
			SetOffScreenPosition();
		}

		private void LateUpdate()
		{
			if (!hasTargetCamera || !player)
			{
				return;
			}
			if (player.HeadOverlappingWaterVolumes.Count < 1)
			{
				SetCameraOverlapState(CameraOverlapWaterState.OutOfWater);
				if (planeRenderer.enabled)
				{
					planeRenderer.enabled = false;
					SetOffScreenPosition();
				}
				if (underwaterParticleEffect != null && underwaterParticleEffect.gameObject.activeInHierarchy)
				{
					underwaterParticleEffect.UpdateParticleEffect(waterSurfaceDetected: false, ref waterSurface);
				}
				return;
			}
			if (targetCamera.aspect != cachedAspectRatio || targetCamera.fieldOfView != cachedFov)
			{
				cachedAspectRatio = targetCamera.aspect;
				cachedFov = targetCamera.fieldOfView;
				CalculateFrustumPlaneBounds(cachedFov, cachedAspectRatio);
			}
			bool flag = false;
			float num = float.MinValue;
			UnityEngine.Vector3 position = targetCamera.transform.position;
			for (int i = 0; i < player.HeadOverlappingWaterVolumes.Count; i++)
			{
				if (player.HeadOverlappingWaterVolumes[i].GetSurfaceQueryForPoint(position, out var result))
				{
					float num2 = UnityEngine.Vector3.Dot(result.surfacePoint - position, result.surfaceNormal);
					if (num2 > num)
					{
						flag = true;
						num = num2;
						waterSurface = result;
					}
				}
			}
			if (flag)
			{
				UnityEngine.Vector3 inPoint = targetCamera.transform.InverseTransformPoint(waterSurface.surfacePoint);
				UnityEngine.Vector3 inNormal = targetCamera.transform.InverseTransformDirection(waterSurface.surfaceNormal);
				UnityEngine.Plane p = new UnityEngine.Plane(inNormal, inPoint);
				UnityEngine.Plane p2 = new UnityEngine.Plane(UnityEngine.Vector3.forward, 0f - distanceFromCamera);
				if (IntersectPlanes(p2, p, out var point, out var direction))
				{
					UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(direction, UnityEngine.Vector3.forward).normalized;
					float num3 = UnityEngine.Vector3.Dot(new UnityEngine.Vector3(point.x, point.y, 0f), normalized);
					if (num3 > frustumPlaneExtents.y + 0.04f)
					{
						SetFullScreenPosition();
						SetCameraOverlapState(CameraOverlapWaterState.FullySubmerged);
					}
					else if (num3 < 0f - (frustumPlaneExtents.y + 0.04f))
					{
						SetOffScreenPosition();
						SetCameraOverlapState(CameraOverlapWaterState.OutOfWater);
					}
					else
					{
						float num4 = num3;
						num4 += GetFrustumCoverageDistance(-normalized) + 0.04f;
						float num5 = GetFrustumCoverageDistance(direction) + 0.04f;
						num5 += GetFrustumCoverageDistance(-direction) + 0.04f;
						base.transform.localScale = new UnityEngine.Vector3(num5, num4, 1f);
						base.transform.localPosition = normalized * (num3 - num4 * 0.5f) + new UnityEngine.Vector3(0f, 0f, distanceFromCamera);
						float angle = UnityEngine.Vector3.SignedAngle(UnityEngine.Vector3.up, normalized, UnityEngine.Vector3.forward);
						base.transform.localRotation = UnityEngine.Quaternion.AngleAxis(angle, UnityEngine.Vector3.forward);
						SetCameraOverlapState(CameraOverlapWaterState.PartiallySubmerged);
					}
					if (debugDraw)
					{
						UnityEngine.Vector3 vector = targetCamera.transform.TransformPoint(point);
						UnityEngine.Vector3 vector2 = targetCamera.transform.TransformDirection(direction);
						DebugUtil.DrawLine(vector - 2f * frustumPlaneExtents.x * vector2, vector + 2f * frustumPlaneExtents.x * vector2, Color.white, depthTest: false);
					}
				}
				else if (new UnityEngine.Plane(waterSurface.surfaceNormal, waterSurface.surfacePoint).GetSide(targetCamera.transform.position))
				{
					SetFullScreenPosition();
					SetCameraOverlapState(CameraOverlapWaterState.FullySubmerged);
				}
				else
				{
					SetOffScreenPosition();
					SetCameraOverlapState(CameraOverlapWaterState.OutOfWater);
				}
			}
			else
			{
				SetOffScreenPosition();
				SetCameraOverlapState(CameraOverlapWaterState.OutOfWater);
			}
			if (underwaterParticleEffect != null && underwaterParticleEffect.gameObject.activeInHierarchy)
			{
				underwaterParticleEffect.UpdateParticleEffect(flag, ref waterSurface);
			}
		}

		[DebugOption]
		private void InitializeShaderProperties()
		{
			Shader.DisableKeyword("_GLOBAL_CAMERA_TOUCHING_WATER");
			Shader.DisableKeyword("_GLOBAL_CAMERA_FULLY_UNDERWATER");
			float w = 0f - UnityEngine.Vector3.Dot(waterSurface.surfaceNormal, waterSurface.surfacePoint);
			Shader.SetGlobalVector(shaderParam_GlobalCameraOverlapWaterSurfacePlane, new UnityEngine.Vector4(waterSurface.surfaceNormal.x, waterSurface.surfaceNormal.y, waterSurface.surfaceNormal.z, w));
		}

		private void SetCameraOverlapState(CameraOverlapWaterState state)
		{
			if (state != cameraOverlapWaterState || state == CameraOverlapWaterState.Uninitialized)
			{
				cameraOverlapWaterState = state;
				switch (cameraOverlapWaterState)
				{
				case CameraOverlapWaterState.Uninitialized:
				case CameraOverlapWaterState.OutOfWater:
					Shader.DisableKeyword("_GLOBAL_CAMERA_TOUCHING_WATER");
					Shader.DisableKeyword("_GLOBAL_CAMERA_FULLY_UNDERWATER");
					break;
				case CameraOverlapWaterState.PartiallySubmerged:
					Shader.EnableKeyword("_GLOBAL_CAMERA_TOUCHING_WATER");
					Shader.DisableKeyword("_GLOBAL_CAMERA_FULLY_UNDERWATER");
					break;
				case CameraOverlapWaterState.FullySubmerged:
					Shader.EnableKeyword("_GLOBAL_CAMERA_TOUCHING_WATER");
					Shader.EnableKeyword("_GLOBAL_CAMERA_FULLY_UNDERWATER");
					break;
				}
			}
			if (cameraOverlapWaterState == CameraOverlapWaterState.PartiallySubmerged)
			{
				UnityEngine.Plane plane = new UnityEngine.Plane(waterSurface.surfaceNormal, waterSurface.surfacePoint);
				Shader.SetGlobalVector(shaderParam_GlobalCameraOverlapWaterSurfacePlane, new UnityEngine.Vector4(plane.normal.x, plane.normal.y, plane.normal.z, plane.distance));
			}
		}

		private void CalculateFrustumPlaneBounds(float fieldOfView, float aspectRatio)
		{
			float num = Mathf.Tan(MathF.PI / 180f * fieldOfView * 0.5f) * distanceFromCamera;
			float num2 = aspectRatio * num + 0.04f;
			float num3 = 1f / aspectRatio * num + 0.04f;
			frustumPlaneExtents = new UnityEngine.Vector2(num2, num3);
			frustumPlaneCornersLocal[0] = new UnityEngine.Vector3(0f - num2, 0f - num3, distanceFromCamera);
			frustumPlaneCornersLocal[1] = new UnityEngine.Vector3(0f - num2, num3, distanceFromCamera);
			frustumPlaneCornersLocal[2] = new UnityEngine.Vector3(num2, num3, distanceFromCamera);
			frustumPlaneCornersLocal[3] = new UnityEngine.Vector3(num2, 0f - num3, distanceFromCamera);
		}

		private bool IntersectPlanes(UnityEngine.Plane p1, UnityEngine.Plane p2, out UnityEngine.Vector3 point, out UnityEngine.Vector3 direction)
		{
			direction = UnityEngine.Vector3.Cross(p1.normal, p2.normal);
			float num = UnityEngine.Vector3.Dot(direction, direction);
			if (num < Mathf.Epsilon)
			{
				point = UnityEngine.Vector3.zero;
				return false;
			}
			point = UnityEngine.Vector3.Cross(direction, p1.distance * p2.normal - p2.distance * p1.normal) / num;
			return true;
		}

		private float GetFrustumCoverageDistance(UnityEngine.Vector3 localDirection)
		{
			float num = float.MinValue;
			for (int i = 0; i < frustumPlaneCornersLocal.Length; i++)
			{
				float num2 = UnityEngine.Vector3.Dot(frustumPlaneCornersLocal[i], localDirection);
				if (num2 > num)
				{
					num = num2;
				}
			}
			return num;
		}
	}
	public class UnderwaterParticleEffects : MonoBehaviour
	{
		public ParticleSystem underwaterFloaterParticles;

		public ParticleSystem underwaterBubbleParticles;

		public Camera playerCamera;

		public UnityEngine.Vector3 floaterParticleBoxExtents = UnityEngine.Vector3.one;

		public UnityEngine.Vector3 floaterParticleBaseOffset = UnityEngine.Vector3.forward;

		public AnimationCurve floaterSpeedVsOffsetDist = AnimationCurve.Linear(0f, 0f, 1f, 1f);

		public UnityEngine.Vector2 floaterSpeedVsOffsetDistMinMax = new UnityEngine.Vector2(0f, 1f);

		private bool debugDraw;

		public void UpdateParticleEffect(bool waterSurfaceDetected, ref WaterVolume.SurfaceQuery waterSurface)
		{
			GTPlayer instance = GTPlayer.Instance;
			UnityEngine.Plane plane = new UnityEngine.Plane(waterSurface.surfaceNormal, waterSurface.surfacePoint);
			if (waterSurfaceDetected && plane.GetDistanceToPoint(instance.headCollider.transform.position) < instance.headCollider.radius)
			{
				underwaterFloaterParticles.gameObject.SetActive(value: true);
				UnityEngine.Vector3 averagedVelocity = instance.AveragedVelocity;
				float magnitude = averagedVelocity.magnitude;
				UnityEngine.Vector3 vector = ((magnitude > 0.001f) ? (averagedVelocity / magnitude) : playerCamera.transform.forward);
				float num = floaterSpeedVsOffsetDist.Evaluate(Mathf.Clamp(magnitude, floaterSpeedVsOffsetDistMinMax.x, floaterSpeedVsOffsetDistMinMax.y));
				UnityEngine.Quaternion rotation = playerCamera.transform.rotation;
				UnityEngine.Vector3 vector2 = playerCamera.transform.position + playerCamera.transform.rotation * floaterParticleBaseOffset + vector * num;
				UnityEngine.Vector3 vector3 = vector2 + rotation * new UnityEngine.Vector3(0f, floaterParticleBoxExtents.y, 0f - floaterParticleBoxExtents.z);
				UnityEngine.Vector3 vector4 = vector2 + rotation * new UnityEngine.Vector3(0f, floaterParticleBoxExtents.y, floaterParticleBoxExtents.z);
				float num2 = floaterParticleBoxExtents.z * 2f;
				float num3 = plane.GetDistanceToPoint(vector3);
				float num4 = plane.GetDistanceToPoint(vector4);
				UnityEngine.Quaternion quaternion2 = rotation;
				UnityEngine.Vector3 vector5 = vector2;
				if (num3 > 0f || num4 > 0f)
				{
					if (vector3.y < vector4.y)
					{
						if (num3 > 0f)
						{
							vector3 -= plane.normal * num3;
							num3 = 0f;
						}
						UnityEngine.Vector3 rhs = (new UnityEngine.Vector3(vector4.x, vector3.y, vector4.z) - vector3).normalized * num2;
						UnityEngine.Vector3 axis = UnityEngine.Vector3.Cross(vector4 - vector3, rhs);
						quaternion2 = UnityEngine.Quaternion.AngleAxis((Mathf.Asin((vector4.y - vector3.y) / num2) - Mathf.Asin((0f - num3) / num2)) * 57.29578f, axis) * playerCamera.transform.rotation;
						vector5 = vector3 + quaternion2 * new UnityEngine.Vector3(0f, 0f - floaterParticleBoxExtents.y, floaterParticleBoxExtents.z);
					}
					else
					{
						if (num4 > 0f)
						{
							vector4 -= plane.normal * num4;
							num4 = 0f;
						}
						UnityEngine.Vector3 rhs2 = (new UnityEngine.Vector3(vector3.x, vector4.y, vector3.z) - vector4).normalized * num2;
						UnityEngine.Vector3 axis2 = UnityEngine.Vector3.Cross(vector3 - vector4, rhs2);
						quaternion2 = UnityEngine.Quaternion.AngleAxis((Mathf.Asin((vector3.y - vector4.y) / num2) - Mathf.Asin((0f - num4) / num2)) * 57.29578f, axis2) * playerCamera.transform.rotation;
						vector5 = vector4 + quaternion2 * new UnityEngine.Vector3(0f, 0f - floaterParticleBoxExtents.y, 0f - floaterParticleBoxExtents.z);
					}
				}
				if (IsValid(vector5))
				{
					underwaterFloaterParticles.transform.rotation = quaternion2;
					underwaterFloaterParticles.transform.position = vector5;
				}
				else
				{
					underwaterFloaterParticles.gameObject.SetActive(value: false);
				}
				if (debugDraw)
				{
					vector3 = vector2 + rotation * new UnityEngine.Vector3(0f, floaterParticleBoxExtents.y, 0f - floaterParticleBoxExtents.z);
					vector4 = vector2 + rotation * new UnityEngine.Vector3(0f, floaterParticleBoxExtents.y, floaterParticleBoxExtents.z);
					DebugUtil.DrawSphere(vector3, 0.1f, 12, 12, Color.red, depthTest: false, DebugUtil.Style.SolidColor);
					DebugUtil.DrawSphere(vector4, 0.1f, 12, 12, Color.red, depthTest: false, DebugUtil.Style.SolidColor);
					DebugUtil.DrawLine(vector3, vector4, Color.red, depthTest: false);
					vector3 = vector5 + quaternion2 * new UnityEngine.Vector3(0f, floaterParticleBoxExtents.y, 0f - floaterParticleBoxExtents.z);
					vector4 = vector5 + quaternion2 * new UnityEngine.Vector3(0f, floaterParticleBoxExtents.y, floaterParticleBoxExtents.z);
					DebugUtil.DrawSphere(vector3, 0.1f, 12, 12, Color.green, depthTest: false, DebugUtil.Style.SolidColor);
					DebugUtil.DrawSphere(vector4, 0.1f, 12, 12, Color.green, depthTest: false, DebugUtil.Style.SolidColor);
					DebugUtil.DrawLine(vector3, vector4, Color.green, depthTest: false);
				}
			}
			else
			{
				underwaterFloaterParticles.gameObject.SetActive(value: false);
			}
		}

		private bool IsValid(UnityEngine.Vector3 vector)
		{
			if (!float.IsNaN(vector.x) && !float.IsNaN(vector.y))
			{
				return !float.IsNaN(vector.z);
			}
			return false;
		}
	}
	public class WaterCurrent : MonoBehaviour
	{
		[SerializeField]
		private List<CatmullRomSpline> splines = new List<CatmullRomSpline>();

		[SerializeField]
		private float fullEffectDistance = 1f;

		[SerializeField]
		private float fadeDistance = 0.5f;

		[SerializeField]
		private float currentSpeed = 1f;

		[SerializeField]
		private float currentAccel = 10f;

		[SerializeField]
		private float velocityAnticipationAdjustment = 0.05f;

		[SerializeField]
		private float inwardCurrentFullEffectRadius = 1f;

		[SerializeField]
		private float inwardCurrentNoEffectRadius = 0.25f;

		[SerializeField]
		private float inwardCurrentSpeed = 1f;

		[SerializeField]
		private float inwardCurrentAccel = 10f;

		[SerializeField]
		private float dampingHalfLife = 0.25f;

		[SerializeField]
		private bool debugDrawCurrentQueries;

		private UnityEngine.Vector3 debugCurrentVelocity = UnityEngine.Vector3.zero;

		private UnityEngine.Vector3 debugSplinePoint = UnityEngine.Vector3.zero;

		public float Speed => currentSpeed;

		public float Accel => currentAccel;

		public float InwardSpeed => inwardCurrentSpeed;

		public float InwardAccel => inwardCurrentAccel;

		public bool GetCurrentAtPoint(UnityEngine.Vector3 worldPoint, UnityEngine.Vector3 startingVelocity, float dt, out UnityEngine.Vector3 currentVelocity, out UnityEngine.Vector3 velocityChange)
		{
			float num = (fullEffectDistance + fadeDistance) * (fullEffectDistance + fadeDistance);
			bool result = false;
			velocityChange = UnityEngine.Vector3.zero;
			currentVelocity = UnityEngine.Vector3.zero;
			float num2 = 0.0001f;
			float magnitude = startingVelocity.magnitude;
			if (magnitude > num2)
			{
				UnityEngine.Vector3 vector = startingVelocity / magnitude;
				float num3 = Spring.DamperDecayExact(magnitude, dampingHalfLife, dt);
				UnityEngine.Vector3 vector2 = vector * num3;
				velocityChange += vector2 - startingVelocity;
			}
			for (int i = 0; i < splines.Count; i++)
			{
				CatmullRomSpline catmullRomSpline = splines[i];
				UnityEngine.Vector3 linePoint;
				float closestEvaluationOnSpline = catmullRomSpline.GetClosestEvaluationOnSpline(worldPoint, out linePoint);
				UnityEngine.Vector3 vector3 = catmullRomSpline.Evaluate(closestEvaluationOnSpline);
				UnityEngine.Vector3 vector4 = vector3 - worldPoint;
				if (!(vector4.sqrMagnitude < num))
				{
					continue;
				}
				result = true;
				float magnitude2 = vector4.magnitude;
				float num4 = ((magnitude2 > fullEffectDistance) ? (1f - Mathf.Clamp01((magnitude2 - fullEffectDistance) / fadeDistance)) : 1f);
				float t = Mathf.Clamp01(closestEvaluationOnSpline + velocityAnticipationAdjustment);
				UnityEngine.Vector3 forwardTangent = catmullRomSpline.GetForwardTangent(t);
				if (currentSpeed > num2 && UnityEngine.Vector3.Dot(startingVelocity, forwardTangent) < num4 * currentSpeed)
				{
					velocityChange += forwardTangent * (currentAccel * dt);
				}
				else if (currentSpeed < num2 && UnityEngine.Vector3.Dot(startingVelocity, forwardTangent) > num4 * currentSpeed)
				{
					velocityChange -= forwardTangent * (currentAccel * dt);
				}
				currentVelocity += forwardTangent * num4 * currentSpeed;
				float num5 = Mathf.InverseLerp(inwardCurrentNoEffectRadius, inwardCurrentFullEffectRadius, magnitude2);
				if (num5 > num2)
				{
					linePoint = UnityEngine.Vector3.ProjectOnPlane(vector4, forwardTangent);
					UnityEngine.Vector3 normalized = linePoint.normalized;
					if (inwardCurrentSpeed > num2 && UnityEngine.Vector3.Dot(startingVelocity, normalized) < num5 * inwardCurrentSpeed)
					{
						velocityChange += normalized * (InwardAccel * dt);
					}
					else if (inwardCurrentSpeed < num2 && UnityEngine.Vector3.Dot(startingVelocity, normalized) > num5 * inwardCurrentSpeed)
					{
						velocityChange -= normalized * (InwardAccel * dt);
					}
				}
				debugSplinePoint = vector3;
			}
			debugCurrentVelocity = velocityChange.normalized;
			return result;
		}

		private void Update()
		{
			if (debugDrawCurrentQueries)
			{
				DebugUtil.DrawSphere(debugSplinePoint, 0.15f, 12, 12, Color.green, depthTest: false);
				DebugUtil.DrawArrow(debugSplinePoint, debugSplinePoint + debugCurrentVelocity, 0.1f, 0.1f, 12, 0.1f, Color.yellow, depthTest: false);
			}
		}

		private void OnDrawGizmosSelected()
		{
			int num = 16;
			for (int i = 0; i < splines.Count; i++)
			{
				CatmullRomSpline catmullRomSpline = splines[i];
				UnityEngine.Vector3 vector = catmullRomSpline.Evaluate(0f);
				for (int j = 1; j <= num; j++)
				{
					float t = (float)j / (float)num;
					UnityEngine.Vector3 vector2 = catmullRomSpline.Evaluate(t);
					_ = vector2 - vector;
					UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(catmullRomSpline.GetForwardTangent(t), UnityEngine.Vector3.up);
					Gizmos.color = new Color(0f, 0.5f, 0.75f);
					DrawGizmoCircle(vector2, rotation, fullEffectDistance);
					Gizmos.color = new Color(0f, 0.25f, 0.5f);
					DrawGizmoCircle(vector2, rotation, fullEffectDistance + fadeDistance);
				}
			}
		}

		private void DrawGizmoCircle(UnityEngine.Vector3 center, UnityEngine.Quaternion rotation, float radius)
		{
			UnityEngine.Vector3 vector = UnityEngine.Vector3.right * radius;
			int num = 16;
			for (int i = 1; i <= num; i++)
			{
				float f = (float)i / (float)num * 2f * MathF.PI;
				UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(Mathf.Cos(f), Mathf.Sin(f), 0f) * radius;
				Gizmos.DrawLine(center + rotation * vector, center + rotation * vector2);
				vector = vector2;
			}
		}
	}
	public struct WaterOverlappingCollider
	{
		public bool playBigSplash;

		public bool playDripEffect;

		public bool overrideBoundingRadius;

		public float boundingRadiusOverride;

		public float scaleMultiplier;

		public Collider collider;

		public GorillaVelocityTracker velocityTracker;

		public WaterVolume.SurfaceQuery lastSurfaceQuery;

		public NetworkView photonViewForRPC;

		public bool surfaceDetected;

		public bool inWater;

		public bool inVolume;

		public float lastBoundingRadius;

		public UnityEngine.Vector3 lastRipplePosition;

		public float lastRippleScale;

		public float lastRippleTime;

		public float lastInWaterTime;

		public float nextDripTime;

		public void PlayRippleEffect(GameObject rippleEffectPrefab, UnityEngine.Vector3 surfacePoint, UnityEngine.Vector3 surfaceNormal, float defaultRippleScale, float currentTime, WaterVolume volume)
		{
			lastRipplePosition = GetClosestPositionOnSurface(surfacePoint, surfaceNormal);
			lastBoundingRadius = GetBoundingRadiusOnSurface(surfaceNormal);
			lastRippleScale = defaultRippleScale * lastBoundingRadius * 2f * scaleMultiplier;
			lastRippleTime = currentTime;
			ObjectPools.instance.Instantiate(rippleEffectPrefab, lastRipplePosition, UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.up, lastSurfaceQuery.surfaceNormal) * UnityEngine.Quaternion.AngleAxis(-90f, UnityEngine.Vector3.right), lastRippleScale).GetComponent<WaterRippleEffect>().PlayEffect(volume);
		}

		public void PlaySplashEffect(GameObject splashEffectPrefab, UnityEngine.Vector3 splashPosition, float splashScale, bool bigSplash, bool enteringWater, WaterVolume volume)
		{
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.up, lastSurfaceQuery.surfaceNormal) * UnityEngine.Quaternion.AngleAxis(-90f, UnityEngine.Vector3.right);
			ObjectPools.instance.Instantiate(splashEffectPrefab, splashPosition, quaternion2, splashScale * scaleMultiplier).GetComponent<WaterSplashEffect>().PlayEffect(bigSplash, enteringWater, scaleMultiplier, volume);
			if (!(photonViewForRPC != null))
			{
				return;
			}
			float time = Time.time;
			int num = -1;
			float num2 = time + 10f;
			for (int i = 0; i < WaterVolume.splashRPCSendTimes.Length; i++)
			{
				if (WaterVolume.splashRPCSendTimes[i] < num2)
				{
					num2 = WaterVolume.splashRPCSendTimes[i];
					num = i;
				}
			}
			if (time - 0.5f > num2)
			{
				WaterVolume.splashRPCSendTimes[num] = time;
				photonViewForRPC.SendRPC("RPC_PlaySplashEffect", RpcTarget.Others, splashPosition, quaternion2, splashScale * scaleMultiplier, lastBoundingRadius, bigSplash, enteringWater);
			}
		}

		public void PlayDripEffect(GameObject rippleEffectPrefab, UnityEngine.Vector3 surfacePoint, UnityEngine.Vector3 surfaceNormal, float dripScale)
		{
			UnityEngine.Vector3 closestPositionOnSurface = GetClosestPositionOnSurface(surfacePoint, surfaceNormal);
			float num = (overrideBoundingRadius ? boundingRadiusOverride : lastBoundingRadius);
			UnityEngine.Vector3 vector = UnityEngine.Vector3.ProjectOnPlane(UnityEngine.Random.onUnitSphere * num * 0.5f, surfaceNormal);
			ObjectPools.instance.Instantiate(rippleEffectPrefab, closestPositionOnSurface + vector, UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.up, lastSurfaceQuery.surfaceNormal) * UnityEngine.Quaternion.AngleAxis(-90f, UnityEngine.Vector3.right), dripScale * scaleMultiplier);
		}

		public UnityEngine.Vector3 GetClosestPositionOnSurface(UnityEngine.Vector3 surfacePoint, UnityEngine.Vector3 surfaceNormal)
		{
			return UnityEngine.Vector3.ProjectOnPlane(collider.transform.position - surfacePoint, surfaceNormal) + surfacePoint;
		}

		private float GetBoundingRadiusOnSurface(UnityEngine.Vector3 surfaceNormal)
		{
			if (overrideBoundingRadius)
			{
				lastBoundingRadius = boundingRadiusOverride;
				return boundingRadiusOverride;
			}
			UnityEngine.Vector3 extents = collider.bounds.extents;
			UnityEngine.Vector3 vector = UnityEngine.Vector3.ProjectOnPlane(collider.transform.right * extents.x, surfaceNormal);
			UnityEngine.Vector3 vector2 = UnityEngine.Vector3.ProjectOnPlane(collider.transform.up * extents.y, surfaceNormal);
			UnityEngine.Vector3 vector3 = UnityEngine.Vector3.ProjectOnPlane(collider.transform.forward * extents.z, surfaceNormal);
			float sqrMagnitude = vector.sqrMagnitude;
			float sqrMagnitude2 = vector2.sqrMagnitude;
			float sqrMagnitude3 = vector3.sqrMagnitude;
			if (sqrMagnitude >= sqrMagnitude2 && sqrMagnitude >= sqrMagnitude3)
			{
				return vector.magnitude;
			}
			if (sqrMagnitude2 >= sqrMagnitude && sqrMagnitude2 >= sqrMagnitude3)
			{
				return vector2.magnitude;
			}
			return vector3.magnitude;
		}
	}
