		public bool GetSurfaceQueryForPoint(UnityEngine.Vector3 point, out SurfaceQuery result, bool debugDraw = false)
		{
			result = default(SurfaceQuery);
			if (!isStationary)
			{
				float num = float.MinValue;
				float num2 = float.MaxValue;
				for (int i = 0; i < volumeColliders.Count; i++)
				{
					float y = volumeColliders[i].bounds.max.y;
					float y2 = volumeColliders[i].bounds.min.y;
					if (y > num)
					{
						num = y;
					}
					if (y2 < num2)
					{
						num2 = y2;
					}
				}
				volumeMaxHeight = num;
				volumeMinHeight = num2;
			}
			UnityEngine.Vector3 vector = ((surfacePlane != null) ? surfacePlane.up : UnityEngine.Vector3.up);
			UnityEngine.Vector3 rhs = new UnityEngine.Vector3(Mathf.Abs(vector.x), Mathf.Abs(vector.y), Mathf.Abs(vector.z));
			float num3 = float.MinValue;
			float num4 = float.MaxValue;
			for (int j = 0; j < volumeColliders.Count; j++)
			{
				Bounds bounds = volumeColliders[j].bounds;
				float num5 = UnityEngine.Vector3.Dot(bounds.center, vector);
				float num6 = UnityEngine.Vector3.Dot(bounds.extents, rhs);
				float num7 = num5 + num6;
				float num8 = num5 - num6;
				if (num7 > num3)
				{
					num3 = num7;
				}
				if (num8 < num4)
				{
					num4 = num8;
				}
			}
			float num9 = UnityEngine.Vector3.Dot(point, vector);
			Ray ray = new Ray(point + vector * (num3 - num9), -vector);
			Ray ray2 = new Ray(point + vector * (num4 - num9), vector);
			float num10 = num3 - num4;
			float num11 = float.MinValue;
			float num12 = float.MaxValue;
			bool flag = false;
			bool flag2 = false;
			float num13 = 0f;
			for (int k = 0; k < surfaceColliders.Count; k++)
			{
				bool flag3 = surfaceColliders[k].enabled;
				surfaceColliders[k].enabled = true;
				if (surfaceColliders[k].Raycast(ray, out var hitInfo, num10))
				{
					float num14 = UnityEngine.Vector3.Dot(hitInfo.point, vector);
					if (num14 > num11 && HitOutsideSurfaceOfMesh(ray.direction, surfaceColliders[k], hitInfo))
					{
						num11 = num14;
						flag = true;
						result.surfacePoint = hitInfo.point;
						result.surfaceNormal = hitInfo.normal;
					}
				}
				if (surfaceColliders[k].Raycast(ray2, out var hitInfo2, num10))
				{
					float num15 = UnityEngine.Vector3.Dot(hitInfo2.point, vector);
					if (num15 < num12 && HitOutsideSurfaceOfMesh(ray2.direction, surfaceColliders[k], hitInfo2))
					{
						num12 = num15;
						flag2 = true;
						num13 = num15;
					}
				}
				surfaceColliders[k].enabled = flag3;
			}
			if (!flag && surfacePlane != null)
			{
				flag = true;
				result.surfacePoint = point - UnityEngine.Vector3.Dot(point - surfacePlane.position, surfacePlane.up) * surfacePlane.up;
				result.surfaceNormal = surfacePlane.up;
			}
			if (flag && flag2)
			{
				result.maxDepth = UnityEngine.Vector3.Dot(result.surfacePoint, vector) - num13;
			}
			else if (flag)
			{
				result.maxDepth = UnityEngine.Vector3.Dot(result.surfacePoint, vector) - num4;
			}
			else
			{
				result.maxDepth = num3 - num4;
			}
			if (debugDraw)
			{
				if (flag)
				{
					DebugUtil.DrawLine(ray.origin, ray.origin + ray.direction * num10, Color.green, depthTest: false);
					DebugUtil.DrawSphere(result.surfacePoint, 0.001f, 12, 12, Color.green, depthTest: false, DebugUtil.Style.SolidColor);
				}
				else
				{
					DebugUtil.DrawLine(ray.origin, ray.origin + ray.direction * num10, Color.red, depthTest: false);
				}
				if (flag2)
				{
					DebugUtil.DrawLine(ray2.origin, ray2.origin + ray2.direction * num10, Color.yellow, depthTest: false);
					DebugUtil.DrawSphere(result.surfacePoint + vector * (num13 - UnityEngine.Vector3.Dot(result.surfacePoint, vector)), 0.001f, 12, 12, Color.yellow, depthTest: false, DebugUtil.Style.SolidColor);
				}
			}
			return flag;
		}

		private bool HitOutsideSurfaceOfMesh(UnityEngine.Vector3 castDir, MeshCollider meshCollider, RaycastHit hit)
		{
			if (!meshTrianglesDict.TryGetValue(meshCollider.sharedMesh, out sharedMeshTris))
			{
				sharedMeshTris = (int[])meshCollider.sharedMesh.triangles.Clone();
				meshTrianglesDict.Add(meshCollider.sharedMesh, sharedMeshTris);
			}
			if (!meshVertsDict.TryGetValue(meshCollider.sharedMesh, out sharedMeshVerts))
			{
				sharedMeshVerts = (UnityEngine.Vector3[])meshCollider.sharedMesh.vertices.Clone();
				meshVertsDict.Add(meshCollider.sharedMesh, sharedMeshVerts);
			}
			UnityEngine.Vector3 vector = sharedMeshVerts[sharedMeshTris[hit.triangleIndex * 3]];
			UnityEngine.Vector3 vector2 = sharedMeshVerts[sharedMeshTris[hit.triangleIndex * 3 + 1]];
			UnityEngine.Vector3 vector3 = sharedMeshVerts[sharedMeshTris[hit.triangleIndex * 3 + 2]];
			UnityEngine.Vector3 vector4 = meshCollider.transform.TransformDirection(UnityEngine.Vector3.Cross(vector2 - vector, vector3 - vector).normalized);
			bool flag = UnityEngine.Vector3.Dot(castDir, vector4) < 0f;
			if (debugDrawSurfaceCast)
			{
				Color color = (flag ? Color.blue : Color.red);
				DebugUtil.DrawLine(hit.point, hit.point + vector4 * 0.3f, color, depthTest: false);
			}
			return flag;
		}

		private void DebugDrawMeshColliderHitTriangle(RaycastHit hit)
		{
			MeshCollider meshCollider = hit.collider as MeshCollider;
			if (meshCollider != null)
			{
				Mesh sharedMesh = meshCollider.sharedMesh;
				int[] triangles = sharedMesh.triangles;
				UnityEngine.Vector3[] vertices = sharedMesh.vertices;
				UnityEngine.Vector3 vector = meshCollider.gameObject.transform.TransformPoint(vertices[triangles[hit.triangleIndex * 3]]);
				UnityEngine.Vector3 vector2 = meshCollider.gameObject.transform.TransformPoint(vertices[triangles[hit.triangleIndex * 3 + 1]]);
				UnityEngine.Vector3 vector3 = meshCollider.gameObject.transform.TransformPoint(vertices[triangles[hit.triangleIndex * 3 + 2]]);
				UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(vector2 - vector, vector3 - vector).normalized;
				float num = 0.2f;
				DebugUtil.DrawLine(vector, vector + normalized * num, Color.blue, depthTest: false);
				DebugUtil.DrawLine(vector2, vector2 + normalized * num, Color.blue, depthTest: false);
				DebugUtil.DrawLine(vector3, vector3 + normalized * num, Color.blue, depthTest: false);
				DebugUtil.DrawLine(vector, vector2, Color.blue, depthTest: false);
				DebugUtil.DrawLine(vector, vector3, Color.blue, depthTest: false);
				DebugUtil.DrawLine(vector2, vector3, Color.blue, depthTest: false);
			}
		}

		public bool RaycastWater(UnityEngine.Vector3 origin, UnityEngine.Vector3 direction, out RaycastHit hit, float distance, int layerMask)
		{
			if (triggerCollider != null)
			{
				return Physics.Raycast(new Ray(origin, direction), out hit, distance, layerMask, QueryTriggerInteraction.Collide);
			}
			hit = default(RaycastHit);
			return false;
		}

		public bool CheckColliderInVolume(Collider collider, out bool inWater, out bool surfaceDetected)
		{
			for (int i = 0; i < persistentColliders.Count; i++)
			{
				if (persistentColliders[i].collider == collider)
				{
					inWater = persistentColliders[i].inWater;
					surfaceDetected = persistentColliders[i].surfaceDetected;
					return true;
				}
			}
			inWater = false;
			surfaceDetected = false;
			return false;
		}

		protected override void Awake()
		{
			base.Awake();
			RefreshColliders();
		}

		private void OnEnable()
		{
			TickSystem<object>.AddTickCallback(this);
		}

		public void RefreshColliders()
		{
			triggerCollider = GetComponent<Collider>();
			if (volumeColliders == null || volumeColliders.Count < 1)
			{
				volumeColliders = new List<Collider>();
				volumeColliders.Add(base.gameObject.GetComponent<Collider>());
			}
			float num = float.MinValue;
			float num2 = float.MaxValue;
			for (int i = 0; i < volumeColliders.Count; i++)
			{
				float y = volumeColliders[i].bounds.max.y;
				float y2 = volumeColliders[i].bounds.min.y;
				if (y > num)
				{
					num = y;
				}
				if (y2 < num2)
				{
					num2 = y2;
				}
			}
			volumeMaxHeight = num;
			volumeMinHeight = num2;
		}

		private void OnDisable()
		{
			if (!ApplicationQuittingState.IsQuitting)
			{
				for (int i = 0; i < persistentColliders.Count; i++)
				{
					WaterOverlappingCollider value = persistentColliders[i];
					value.inVolume = false;
					value.playDripEffect = false;
					this.ColliderExitedVolume?.Invoke(this, value.collider);
					persistentColliders[i] = value;
				}
				RemoveCollidersOutsideVolume(Time.time);
				TickSystem<object>.RemoveTickCallback(this);
			}
		}

		public void Tick()
		{
			if (persistentColliders.Count < 1)
			{
				return;
			}
			float time = Time.time;
			RemoveCollidersOutsideVolume(time);
			if (!CanPlayerSwim())
			{
				return;
			}
			for (int i = 0; i < persistentColliders.Count; i++)
			{
				WaterOverlappingCollider persistentCollider = persistentColliders[i];
				bool inWater = persistentCollider.inWater;
				if (persistentCollider.inVolume)
				{
					CheckColliderAgainstWater(ref persistentCollider, time);
				}
				else
				{
					persistentCollider.inWater = false;
				}
				TryRegisterOwnershipOfCollider(persistentCollider.collider, persistentCollider.inWater, persistentCollider.surfaceDetected);
				if (persistentCollider.inWater && !inWater)
				{
					OnWaterSurfaceEnter(ref persistentCollider);
				}
				else if (!persistentCollider.inWater && inWater)
				{
					OnWaterSurfaceExit(ref persistentCollider, time);
				}
				if (HasOwnershipOfCollider(persistentCollider.collider) && persistentCollider.surfaceDetected)
				{
					if (!persistentCollider.inWater)
					{
						ColliderOutOfWaterUpdate(ref persistentCollider, time);
					}
					else
					{
						ColliderInWaterUpdate(ref persistentCollider, time);
					}
				}
				persistentColliders[i] = persistentCollider;
			}
		}

		private void RemoveCollidersOutsideVolume(float currentTime)
		{
			if (ApplicationQuittingState.IsQuitting)
			{
				return;
			}
			for (int num = persistentColliders.Count - 1; num >= 0; num--)
			{
				WaterOverlappingCollider waterOverlappingCollider = persistentColliders[num];
				if (waterOverlappingCollider.collider == null || !waterOverlappingCollider.collider.gameObject.activeInHierarchy || (!waterOverlappingCollider.inVolume && (!waterOverlappingCollider.playDripEffect || currentTime - waterOverlappingCollider.lastInWaterTime > waterParams.postExitDripDuration)) || !CanPlayerSwim())
				{
					UnregisterOwnershipOfCollider(waterOverlappingCollider.collider);
					GTPlayer instance = GTPlayer.Instance;
					if (waterOverlappingCollider.collider == instance.headCollider || waterOverlappingCollider.collider == instance.bodyCollider)
					{
						instance.OnExitWaterVolume(waterOverlappingCollider.collider, this);
					}
					persistentColliders.RemoveAt(num);
				}
			}
		}

		private void CheckColliderAgainstWater(ref WaterOverlappingCollider persistentCollider, float currentTime)
		{
			UnityEngine.Vector3 position = persistentCollider.collider.transform.position;
			bool flag = true;
			if (persistentCollider.surfaceDetected && persistentCollider.scaleMultiplier > 0.99f && isStationary)
			{
				flag = (position - UnityEngine.Vector3.Dot(position - persistentCollider.lastSurfaceQuery.surfacePoint, persistentCollider.lastSurfaceQuery.surfaceNormal) * persistentCollider.lastSurfaceQuery.surfaceNormal - persistentCollider.lastSurfaceQuery.surfacePoint).sqrMagnitude > waterParams.recomputeSurfaceForColliderDist * waterParams.recomputeSurfaceForColliderDist;
			}
			if (flag)
			{
				if (GetSurfaceQueryForPoint(position, out var result, debugDrawSurfaceCast))
				{
					persistentCollider.surfaceDetected = true;
					persistentCollider.lastSurfaceQuery = result;
				}
				else
				{
					persistentCollider.surfaceDetected = false;
					persistentCollider.lastSurfaceQuery = default(SurfaceQuery);
				}
			}
			if (persistentCollider.surfaceDetected)
			{
				UnityEngine.Vector3 obj = ((persistentCollider.collider is MeshCollider) ? persistentCollider.collider.ClosestPointOnBounds(position + UnityEngine.Vector3.down * 10f) : persistentCollider.collider.ClosestPoint(position + UnityEngine.Vector3.down * 10f));
				bool flag2 = obj.y < persistentCollider.lastSurfaceQuery.surfacePoint.y;
				UnityEngine.Vector3 obj2 = ((persistentCollider.collider is MeshCollider) ? persistentCollider.collider.ClosestPointOnBounds(position + UnityEngine.Vector3.up * 10f) : persistentCollider.collider.ClosestPoint(position + UnityEngine.Vector3.up * 10f));
				bool flag3 = obj2.y > persistentCollider.lastSurfaceQuery.surfacePoint.y - persistentCollider.lastSurfaceQuery.maxDepth;
				persistentCollider.inWater = flag2 && flag3;
			}
			else
			{
				persistentCollider.inWater = false;
			}
			if (persistentCollider.inWater)
			{
				persistentCollider.lastInWaterTime = currentTime;
			}
		}

		private UnityEngine.Vector3 GetColliderVelocity(ref WaterOverlappingCollider persistentCollider)
		{
			GTPlayer instance = GTPlayer.Instance;
			UnityEngine.Vector3 result = UnityEngine.Vector3.one * (waterParams.splashSpeedRequirement + 0.1f);
			if (persistentCollider.velocityTracker != null)
			{
				result = persistentCollider.velocityTracker.GetAverageVelocity(worldSpace: true, 0.1f);
			}
			else if (persistentCollider.collider == instance.headCollider || persistentCollider.collider == instance.bodyCollider)
			{
				result = instance.AveragedVelocity;
			}
			else if (persistentCollider.collider.attachedRigidbody != null && !persistentCollider.collider.attachedRigidbody.isKinematic)
			{
				result = persistentCollider.collider.attachedRigidbody.linearVelocity;
			}
			return result;
		}

		private void OnWaterSurfaceEnter(ref WaterOverlappingCollider persistentCollider)
		{
			this.ColliderEnteredWater?.Invoke(this, persistentCollider.collider);
			GTPlayer instance = GTPlayer.Instance;
			if (persistentCollider.collider == instance.headCollider || persistentCollider.collider == instance.bodyCollider)
			{
				instance.OnEnterWaterVolume(persistentCollider.collider, this);
			}
			if (HasOwnershipOfCollider(persistentCollider.collider))
			{
				UnityEngine.Vector3 colliderVelocity = GetColliderVelocity(ref persistentCollider);
				bool flag = UnityEngine.Vector3.Dot(colliderVelocity, -persistentCollider.lastSurfaceQuery.surfaceNormal) > waterParams.splashSpeedRequirement * persistentCollider.scaleMultiplier;
				bool flag2 = UnityEngine.Vector3.Dot(colliderVelocity, -persistentCollider.lastSurfaceQuery.surfaceNormal) > waterParams.bigSplashSpeedRequirement * persistentCollider.scaleMultiplier;
				persistentCollider.PlayRippleEffect(waterParams.rippleEffect, persistentCollider.lastSurfaceQuery.surfacePoint, persistentCollider.lastSurfaceQuery.surfaceNormal, waterParams.rippleEffectScale, Time.time, this);
				if (waterParams.playSplashEffect && flag && (flag2 || !persistentCollider.playBigSplash))
				{
					persistentCollider.PlaySplashEffect(waterParams.splashEffect, persistentCollider.lastRipplePosition, waterParams.splashEffectScale, persistentCollider.playBigSplash && flag2, enteringWater: true, this);
				}
			}
		}

		private void OnWaterSurfaceExit(ref WaterOverlappingCollider persistentCollider, float currentTime)
		{
			this.ColliderExitedWater?.Invoke(this, persistentCollider.collider);
			persistentCollider.nextDripTime = currentTime + waterParams.perDripTimeDelay + UnityEngine.Random.Range((0f - waterParams.perDripTimeRandRange) * 0.5f, waterParams.perDripTimeRandRange * 0.5f);
			GTPlayer instance = GTPlayer.Instance;
			if (persistentCollider.collider == instance.headCollider || persistentCollider.collider == instance.bodyCollider)
			{
				instance.OnExitWaterVolume(persistentCollider.collider, this);
			}
			if (HasOwnershipOfCollider(persistentCollider.collider))
			{
				float num = UnityEngine.Vector3.Dot(GetColliderVelocity(ref persistentCollider), persistentCollider.lastSurfaceQuery.surfaceNormal);
				bool flag = num > waterParams.splashSpeedRequirement * persistentCollider.scaleMultiplier;
				bool flag2 = num > waterParams.bigSplashSpeedRequirement * persistentCollider.scaleMultiplier;
				persistentCollider.PlayRippleEffect(waterParams.rippleEffect, persistentCollider.lastSurfaceQuery.surfacePoint, persistentCollider.lastSurfaceQuery.surfaceNormal, waterParams.rippleEffectScale, Time.time, this);
				if (waterParams.playSplashEffect && flag && (flag2 || !persistentCollider.playBigSplash))
				{
					persistentCollider.PlaySplashEffect(waterParams.splashEffect, persistentCollider.lastRipplePosition, waterParams.splashEffectScale, persistentCollider.playBigSplash && flag2, enteringWater: false, this);
				}
			}
		}

		private void ColliderOutOfWaterUpdate(ref WaterOverlappingCollider persistentCollider, float currentTime)
		{
			if (currentTime < persistentCollider.lastInWaterTime + waterParams.postExitDripDuration && currentTime > persistentCollider.nextDripTime && persistentCollider.playDripEffect)
			{
				persistentCollider.nextDripTime = currentTime + waterParams.perDripTimeDelay + UnityEngine.Random.Range((0f - waterParams.perDripTimeRandRange) * 0.5f, waterParams.perDripTimeRandRange * 0.5f);
				float dripScale = waterParams.rippleEffectScale * 2f * (waterParams.perDripDefaultRadius + UnityEngine.Random.Range((0f - waterParams.perDripRadiusRandRange) * 0.5f, waterParams.perDripRadiusRandRange * 0.5f));
				persistentCollider.PlayDripEffect(waterParams.rippleEffect, persistentCollider.lastSurfaceQuery.surfacePoint, persistentCollider.lastSurfaceQuery.surfaceNormal, dripScale);
			}
		}

		private void ColliderInWaterUpdate(ref WaterOverlappingCollider persistentCollider, float currentTime)
		{
			UnityEngine.Vector3 vector = UnityEngine.Vector3.ProjectOnPlane(persistentCollider.collider.transform.position - persistentCollider.lastSurfaceQuery.surfacePoint, persistentCollider.lastSurfaceQuery.surfaceNormal) + persistentCollider.lastSurfaceQuery.surfacePoint;
			bool flag = false;
			if ((!persistentCollider.overrideBoundingRadius) ? ((persistentCollider.collider.ClosestPointOnBounds(vector) - vector).sqrMagnitude < 0.001f) : ((persistentCollider.collider.transform.position - vector).sqrMagnitude < persistentCollider.boundingRadiusOverride * persistentCollider.boundingRadiusOverride))
			{
				float num = Mathf.Max(waterParams.minDistanceBetweenRipples, waterParams.defaultDistanceBetweenRipples * (persistentCollider.lastRippleScale / waterParams.rippleEffectScale));
				bool num2 = (persistentCollider.lastRipplePosition - vector).sqrMagnitude > num * num;
				bool flag2 = currentTime - persistentCollider.lastRippleTime > waterParams.minTimeBetweenRipples;
				if (num2 || flag2)
				{
					persistentCollider.PlayRippleEffect(waterParams.rippleEffect, persistentCollider.lastSurfaceQuery.surfacePoint, persistentCollider.lastSurfaceQuery.surfaceNormal, waterParams.rippleEffectScale, currentTime, this);
				}
			}
			else
			{
				persistentCollider.lastRippleTime = currentTime;
			}
		}

		private void TryRegisterOwnershipOfCollider(Collider collider, bool isInWater, bool isSurfaceDetected)
		{
			if (sharedColliderRegistry.TryGetValue(collider, out var value))
			{
				if (value != this)
				{
					value.CheckColliderInVolume(collider, out var inWater, out var surfaceDetected);
					if ((isSurfaceDetected && !surfaceDetected) || (isInWater && !inWater))
					{
						sharedColliderRegistry.Remove(collider);
						sharedColliderRegistry.Add(collider, this);
					}
				}
			}
			else
			{
				sharedColliderRegistry.Add(collider, this);
			}
		}

		private void UnregisterOwnershipOfCollider(Collider collider)
		{
			if (sharedColliderRegistry.ContainsKey(collider))
			{
				sharedColliderRegistry.Remove(collider);
			}
		}

		private bool HasOwnershipOfCollider(Collider collider)
		{
			if (sharedColliderRegistry.TryGetValue(collider, out var value))
			{
				return value == this;
			}
			return false;
		}

		protected virtual bool CanPlayerSwim()
		{
			if (isMonkeblock && PlayerVRRig != null)
			{
				if (PlayerVRRig.scaleFactor < 0.5f)
				{
					return true;
				}
				if (BuilderTable.TryGetBuilderTableForZone(PlayerVRRig.zoneEntity.currentZone, out var table))
				{
					return !table.isTableMutable;
				}
			}
			return true;
		}

		public void OnTriggerEnter(Collider other)
		{
			if (!CanPlayerSwim())
			{
				return;
			}
			GorillaTriggerColliderHandIndicator component = other.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (other.isTrigger && component == null)
			{
				return;
			}
			this.ColliderEnteredVolume?.Invoke(this, other);
			for (int i = 0; i < persistentColliders.Count; i++)
			{
				if (persistentColliders[i].collider == other)
				{
					WaterOverlappingCollider value = persistentColliders[i];
					value.inVolume = true;
					persistentColliders[i] = value;
					return;
				}
			}
			WaterOverlappingCollider item = new WaterOverlappingCollider
			{
				collider = other
			};
			item.inVolume = true;
			item.lastInWaterTime = Time.time - waterParams.postExitDripDuration - 10f;
			WaterSplashOverride component2 = other.GetComponent<WaterSplashOverride>();
			if (component2 != null)
			{
				if (component2.suppressWaterEffects)
				{
					return;
				}
				item.playBigSplash = component2.playBigSplash;
				item.playDripEffect = component2.playDrippingEffect;
				item.overrideBoundingRadius = component2.overrideBoundingRadius;
				item.boundingRadiusOverride = component2.boundingRadiusOverride;
				item.scaleMultiplier = (component2.scaleByPlayersScale ? GTPlayer.Instance.scale : 1f);
			}
			else
			{
				if (other.GetComponent<BuilderPieceCollider>() != null)
				{
					return;
				}
				item.playDripEffect = true;
				item.overrideBoundingRadius = false;
				item.scaleMultiplier = 1f;
				item.playBigSplash = false;
			}
			GTPlayer instance = GTPlayer.Instance;
			if (component != null)
			{
				item.velocityTracker = instance.GetHandVelocityTracker(component.isLeftHand);
				item.scaleMultiplier = instance.scale;
			}
			else
			{
				item.velocityTracker = other.GetComponent<GorillaVelocityTracker>();
			}
			if (PlayerVRRig != null && waterParams.sendSplashEffectRPCs && (component != null || item.collider == instance.headCollider || item.collider == instance.bodyCollider))
			{
				item.photonViewForRPC = PlayerVRRig.netView;
			}
			persistentColliders.Add(item);
		}

		private void OnTriggerExit(Collider other)
		{
			if (!CanPlayerSwim())
			{
				return;
			}
			GorillaTriggerColliderHandIndicator component = other.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (other.isTrigger && component == null)
			{
				return;
			}
			this.ColliderExitedVolume?.Invoke(this, other);
			for (int i = 0; i < persistentColliders.Count; i++)
			{
				if (persistentColliders[i].collider == other)
				{
					WaterOverlappingCollider value = persistentColliders[i];
					value.inVolume = false;
					persistentColliders[i] = value;
				}
			}
		}

		public void SetPropertiesFromPlaceholder(WaterVolumeProperties properties, List<Collider> waterVolumeColliders, WaterParameters parameters)
		{
			surfacePlane = properties.surfacePlane;
			surfaceColliders = properties.surfaceColliders;
			volumeColliders = waterVolumeColliders;
			liquidType = (GTPlayer.LiquidType)System.Math.Clamp((int)(properties.liquidType - 1), 0, 1);
			waterParams = parameters;
		}
	}
}
namespace GorillaLocomotion.Gameplay
{
	public class CustomRopeNode : MonoBehaviour
	{
		public UnityEngine.Vector3 previousPos;
	}
	public class CustomRopeSimulation : MonoBehaviour
	{
		private List<Transform> nodes = new List<Transform>();

		[SerializeField]
		private GameObject ropeNodePrefab;

		[SerializeField]
		private int nodeCount = 10;

		[SerializeField]
		private float nodeDistance = 0.4f;

		[SerializeField]
		private UnityEngine.Vector3 gravity = new UnityEngine.Vector3(0f, -9.81f, 0f);

		private NativeArray<BurstRopeNode> burstNodes;

		private void Start()
		{
			UnityEngine.Vector3 position = base.transform.position;
			for (int i = 0; i < nodeCount; i++)
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(ropeNodePrefab);
				gameObject.transform.parent = base.transform;
				gameObject.transform.position = position;
				nodes.Add(gameObject.transform);
				position.y -= nodeDistance;
			}
			nodes[nodes.Count - 1].GetComponentInChildren<Renderer>().enabled = false;
			burstNodes = new NativeArray<BurstRopeNode>(nodes.Count, Unity.Collections.Allocator.Persistent);
		}

		private void OnDestroy()
		{
			burstNodes.Dispose();
		}

		private void Update()
		{
			new SolveRopeJob
			{
				fixedDeltaTime = Time.deltaTime,
				gravity = gravity,
				nodes = burstNodes,
				nodeDistance = nodeDistance,
				rootPos = base.transform.position
			}.Run();
			for (int i = 0; i < burstNodes.Length; i++)
			{
				nodes[i].position = burstNodes[i].curPos;
				if (i > 0)
				{
					UnityEngine.Vector3 vector = burstNodes[i - 1].curPos - burstNodes[i].curPos;
					nodes[i].up = -vector;
				}
			}
		}
	}
	public struct BurstRopeNode
	{
		public UnityEngine.Vector3 lastPos;

		public UnityEngine.Vector3 curPos;
	}
	[BurstCompile]
	public struct SolveRopeJob : IJob
	{
		[Unity.Collections.ReadOnly]
		public float fixedDeltaTime;

		[WriteOnly]
		public NativeArray<BurstRopeNode> nodes;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Vector3 gravity;

		[Unity.Collections.ReadOnly]
		public UnityEngine.Vector3 rootPos;

		[Unity.Collections.ReadOnly]
		public float nodeDistance;

		public void Execute()
		{
			Simulate();
			for (int i = 0; i < 20; i++)
			{
				ApplyConstraint();
			}
		}

		private void Simulate()
		{
			for (int i = 0; i < nodes.Length; i++)
			{
				BurstRopeNode value = nodes[i];
				UnityEngine.Vector3 vector = value.curPos - value.lastPos;
				value.lastPos = value.curPos;
				UnityEngine.Vector3 curPos = value.curPos + vector;
				curPos += gravity * fixedDeltaTime;
				value.curPos = curPos;
				nodes[i] = value;
			}
		}

		private void ApplyConstraint()
		{
			BurstRopeNode value = nodes[0];
			value.curPos = rootPos;
			nodes[0] = value;
			for (int i = 0; i < nodes.Length - 1; i++)
			{
				BurstRopeNode value2 = nodes[i];
				BurstRopeNode value3 = nodes[i + 1];
				float magnitude = (value2.curPos - value3.curPos).magnitude;
				float num = Mathf.Abs(magnitude - nodeDistance);
				UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
				if (magnitude > nodeDistance)
				{
					vector = (value2.curPos - value3.curPos).normalized;
				}
				else if (magnitude < nodeDistance)
				{
					vector = (value3.curPos - value2.curPos).normalized;
				}
				UnityEngine.Vector3 vector2 = vector * num;
				value2.curPos -= vector2 * 0.5f;
				value3.curPos += vector2 * 0.5f;
				nodes[i] = value2;
				nodes[i + 1] = value3;
			}
		}
	}
	public class GorillaRopeSegment : MonoBehaviour
	{
		public GorillaRopeSwing swing;

		public int boneIndex;
	}
	public class GorillaRopeSwing : MonoBehaviour, IBuilderPieceComponent
	{
		public int ropeId;

		public string staticId;

		public bool useStaticId;

		protected float ropeBitGenOffset = 1f;

		[SerializeField]
		protected GameObject prefabRopeBit;

		[SerializeField]
		private bool supportMovingAtRuntime;

		public Transform[] nodes = Array.Empty<Transform>();

		private Dictionary<int, int> remotePlayers = new Dictionary<int, int>();

		[NonSerialized]
		public float lastGrabTime;

		[SerializeField]
		private AudioSource ropeCreakSFX;

		public GorillaVelocityTracker velocityTracker;

		private bool localPlayerOn;

		private int localPlayerBoneIndex;

		private XRNode localPlayerXRNode;

		private const float MAX_VELOCITY_FOR_IDLE = 0.5f;

		private const float TIME_FOR_IDLE = 2f;

		private float potentialIdleTimer;

		[SerializeField]
		protected int ropeLength = 8;

		[SerializeField]
		private GorillaRopeSwingSettings settings;

		private bool hasMonkeBlockParent;

		private BuilderPiece monkeBlockParent;

		[NonSerialized]
		public int ropeDataStartIndex;

		[NonSerialized]
		public int ropeDataIndexOffset;

		[SerializeField]
		private LayerMask wallLayerMask;

		private RaycastHit[] nodeHits = new RaycastHit[1];

		private float scaleFactor = 1f;

		private bool started;

		private int lastNodeCheckIndex = 2;

		public bool isIdle { get; private set; }

		public bool isFullyIdle { get; private set; }

		public bool SupportsMovingAtRuntime => supportMovingAtRuntime;

		public bool hasPlayers
		{
			get
			{
				if (!localPlayerOn)
				{
					return remotePlayers.Count > 0;
				}
				return true;
			}
		}

		private void EdRecalculateId()
		{
			CalculateId(force: true);
		}

		protected virtual void Awake()
		{
			base.transform.rotation = UnityEngine.Quaternion.identity;
			scaleFactor = (base.transform.lossyScale.x + base.transform.lossyScale.y + base.transform.lossyScale.z) / 3f;
			SetIsIdle(idle: true);
		}

		protected virtual void Start()
		{
			if (!useStaticId)
			{
				CalculateId();
			}
			RopeSwingManager.Register(this);
			started = true;
		}

		private void OnDestroy()
		{
			if (RopeSwingManager.instance != null)
			{
				RopeSwingManager.Unregister(this);
			}
		}

		protected virtual void OnEnable()
		{
			base.transform.rotation = UnityEngine.Quaternion.identity;
			scaleFactor = (base.transform.lossyScale.x + base.transform.lossyScale.y + base.transform.lossyScale.z) / 3f;
			SetIsIdle(idle: true, resetPos: true);
			VectorizedCustomRopeSimulation.Register(this);
			GorillaRopeSwingUpdateManager.RegisterRopeSwing(this);
		}

		private void OnDisable()
		{
			if (!isIdle)
			{
				SetIsIdle(idle: true, resetPos: true);
			}
			VectorizedCustomRopeSimulation.Unregister(this);
			GorillaRopeSwingUpdateManager.UnregisterRopeSwing(this);
		}

		internal void CalculateId(bool force = false)
		{
			Transform transform = base.transform;
			int staticHash = TransformUtils.GetScenePath(transform).GetStaticHash();
			int staticHash2 = GetType().Name.GetStaticHash();
			int num = StaticHash.Compute(staticHash, staticHash2);
			if (useStaticId)
			{
				if (string.IsNullOrEmpty(staticId) || force)
				{
					UnityEngine.Vector3 position = transform.position;
					int i = StaticHash.Compute(position.x, position.y, position.z);
					int instanceID = transform.GetInstanceID();
					int num2 = StaticHash.Compute(num, i, instanceID);
					staticId = $"#ID_{num2:X8}";
				}
				ropeId = staticId.GetStaticHash();
			}
			else
			{
				ropeId = (UnityEngine.Application.isPlaying ? num : 0);
			}
		}

		public void InvokeUpdate()
		{
			if (isIdle)
			{
				isFullyIdle = true;
			}
			if (!isIdle)
			{
				int num = -1;
				if (localPlayerOn)
				{
					num = localPlayerBoneIndex;
				}
				else if (remotePlayers.Count > 0)
				{
					num = Enumerable.First(remotePlayers).Value;
				}
				if (num >= 0 && VectorizedCustomRopeSimulation.instance.GetNodeVelocity(this, num).magnitude > 2f && !ropeCreakSFX.isPlaying && Mathf.RoundToInt(Time.time) % 5 == 0)
				{
					ropeCreakSFX.GTPlay();
				}
				if (localPlayerOn)
				{
					float num2 = MathUtils.Linear(velocityTracker.GetLatestVelocity(worldSpace: true).magnitude / scaleFactor, 0f, 10f, -0.07f, 0.5f);
					if (num2 > 0f)
					{
						GorillaTagger.Instance.DoVibration(localPlayerXRNode, num2, Time.deltaTime);
					}
				}
				Transform bone = GetBone(lastNodeCheckIndex);
				UnityEngine.Vector3 nodeVelocity = VectorizedCustomRopeSimulation.instance.GetNodeVelocity(this, lastNodeCheckIndex);
				if (Physics.SphereCastNonAlloc(bone.position, 0.2f * scaleFactor, nodeVelocity.normalized, nodeHits, 0.4f * scaleFactor, wallLayerMask, QueryTriggerInteraction.Ignore) > 0)
				{
					SetVelocity(lastNodeCheckIndex, UnityEngine.Vector3.zero, wholeRope: false, default(PhotonMessageInfoWrapped));
				}
				if (!(nodeVelocity.magnitude > 0.35f))
				{
					potentialIdleTimer += Time.deltaTime;
				}
				else
				{
					potentialIdleTimer = 0f;
				}
				if (potentialIdleTimer >= 2f)
				{
					SetIsIdle(idle: true);
					potentialIdleTimer = 0f;
				}
				lastNodeCheckIndex++;
				if (lastNodeCheckIndex > nodes.Length)
				{
					lastNodeCheckIndex = 2;
				}
			}
			if (hasMonkeBlockParent && supportMovingAtRuntime)
			{
				base.transform.rotation = UnityEngine.Quaternion.Euler(0f, base.transform.parent.rotation.eulerAngles.y, 0f);
			}
		}

		private void SetIsIdle(bool idle, bool resetPos = false)
		{
			isIdle = idle;
			ropeCreakSFX.gameObject.SetActive(!idle);
			if (idle)
			{
				ToggleVelocityTracker(enable: false);
				if (resetPos)
				{
					UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
					for (int i = 0; i < nodes.Length; i++)
					{
						nodes[i].transform.localRotation = UnityEngine.Quaternion.identity;
						nodes[i].transform.localPosition = zero;
						zero += new UnityEngine.Vector3(0f, 0f - ropeBitGenOffset, 0f);
					}
				}
			}
			else
			{
				isFullyIdle = false;
			}
		}

		public Transform GetBone(int index)
		{
			if (index >= nodes.Length)
			{
				return nodes.Last();
			}
			return nodes[index];
		}

		public int GetBoneIndex(Transform r)
		{
			for (int i = 0; i < nodes.Length; i++)
			{
				if (nodes[i] == r)
				{
					return i;
				}
			}
			return nodes.Length - 1;
		}

		public void AttachLocalPlayer(XRNode xrNode, Transform grabbedBone, UnityEngine.Vector3 offset, UnityEngine.Vector3 velocity)
		{
			int num = (localPlayerBoneIndex = GetBoneIndex(grabbedBone));
			velocity /= scaleFactor;
			velocity *= settings.inheritVelocityMultiplier;
			if (GorillaTagger.hasInstance && (bool)GorillaTagger.Instance.offlineVRRig)
			{
				GorillaTagger.Instance.offlineVRRig.grabbedRopeIndex = ropeId;
				GorillaTagger.Instance.offlineVRRig.grabbedRopeBoneIndex = num;
				GorillaTagger.Instance.offlineVRRig.grabbedRopeIsLeft = xrNode == XRNode.LeftHand;
				GorillaTagger.Instance.offlineVRRig.grabbedRopeOffset = offset;
				GorillaTagger.Instance.offlineVRRig.grabbedRopeIsPhotonView = false;
			}
			RefreshAllBonesMass();
			List<UnityEngine.Vector3> list = new List<UnityEngine.Vector3>();
			if (remotePlayers.Count <= 0)
			{
				Transform[] array = nodes;
				foreach (Transform transform in array)
				{
					list.Add(transform.position);
				}
			}
			velocity.y = 0f;
			if (Time.time - lastGrabTime > 1f && (remotePlayers.Count == 0 || velocity.magnitude > 2.5f))
			{
				RopeSwingManager.instance.SendSetVelocity_RPC(ropeId, num, velocity, wholeRope: true);
			}
			lastGrabTime = Time.time;
			ropeCreakSFX.transform.parent = GetBone(System.Math.Max(0, num - 3)).transform;
			ropeCreakSFX.transform.localPosition = UnityEngine.Vector3.zero;
			localPlayerOn = true;
			localPlayerXRNode = xrNode;
			ToggleVelocityTracker(enable: true, num, offset);
		}

		public void DetachLocalPlayer()
		{
			if (GorillaTagger.hasInstance && (bool)GorillaTagger.Instance.offlineVRRig)
			{
				GorillaTagger.Instance.offlineVRRig.grabbedRopeIndex = -1;
			}
			localPlayerOn = false;
			localPlayerBoneIndex = 0;
			RefreshAllBonesMass();
		}

		private void ToggleVelocityTracker(bool enable, int boneIndex = 0, UnityEngine.Vector3 offset = default(UnityEngine.Vector3))
		{
			if (enable)
			{
				velocityTracker.transform.SetParent(GetBone(boneIndex));
				velocityTracker.transform.localPosition = offset;
				velocityTracker.ResetState();
			}
			velocityTracker.gameObject.SetActive(enable);
			if (enable)
			{
				velocityTracker.Tick();
			}
		}

		private void RefreshAllBonesMass()
		{
			int num = 0;
			foreach (KeyValuePair<int, int> remotePlayer in remotePlayers)
			{
				if (remotePlayer.Value > num)
				{
					num = remotePlayer.Value;
				}
			}
			if (localPlayerBoneIndex > num)
			{
				num = localPlayerBoneIndex;
			}
			VectorizedCustomRopeSimulation.instance.SetMassForPlayers(this, hasPlayers, num);
		}

		public bool AttachRemotePlayer(int playerId, int boneIndex, Transform offsetTransform, UnityEngine.Vector3 offset)
		{
			Transform bone = GetBone(boneIndex);
			if (bone == null)
			{
				return false;
			}
			offsetTransform.SetParent(bone.transform);
			offsetTransform.localPosition = offset;
			offsetTransform.localRotation = UnityEngine.Quaternion.identity;
			if (remotePlayers.ContainsKey(playerId))
			{
				UnityEngine.Debug.LogError("already on the list!");
				return false;
			}
			remotePlayers.Add(playerId, boneIndex);
			RefreshAllBonesMass();
			return true;
		}

		public void DetachRemotePlayer(int playerId)
		{
			remotePlayers.Remove(playerId);
			RefreshAllBonesMass();
		}

		public void SetVelocity(int boneIndex, UnityEngine.Vector3 velocity, bool wholeRope, PhotonMessageInfoWrapped info)
		{
			if (!base.isActiveAndEnabled || !velocity.IsValid(10000f))
			{
				return;
			}
			velocity.x = Mathf.Clamp(velocity.x, -100f, 100f);
			velocity.y = Mathf.Clamp(velocity.y, -100f, 100f);
			velocity.z = Mathf.Clamp(velocity.z, -100f, 100f);
			boneIndex = Mathf.Clamp(boneIndex, 0, nodes.Length);
			Transform bone = GetBone(boneIndex);
			if (!bone)
			{
				return;
			}
			if (info.Sender != null && !info.Sender.IsLocal)
			{
				VRRig vRRig = GorillaGameManager.StaticFindRigForPlayer(info.Sender);
				if (!vRRig || UnityEngine.Vector3.Distance(bone.position, vRRig.transform.position) > 5f)
				{
					return;
				}
			}
			SetIsIdle(idle: false);
			if ((bool)bone)
			{
				VectorizedCustomRopeSimulation.instance.SetVelocity(this, velocity, wholeRope, boneIndex);
			}
		}

		public void OnPieceCreate(int pieceType, int pieceId)
		{
			monkeBlockParent = GetComponentInParent<BuilderPiece>();
			hasMonkeBlockParent = monkeBlockParent != null;
			int num = StaticHash.Compute(pieceType, pieceId);
			staticId = $"#ID_{num:X8}";
			ropeId = staticId.GetStaticHash();
			if (started && !RopeSwingManager.instance.TryGetRope(ropeId, out var _))
			{
				RopeSwingManager.Register(this);
			}
		}

		public void OnPieceDestroy()
		{
			RopeSwingManager.Unregister(this);
		}

		public void OnPiecePlacementDeserialized()
		{
			VectorizedCustomRopeSimulation.Unregister(this);
			base.transform.rotation = UnityEngine.Quaternion.identity;
			scaleFactor = (base.transform.lossyScale.x + base.transform.lossyScale.y + base.transform.lossyScale.z) / 3f;
			SetIsIdle(idle: true, resetPos: true);
			VectorizedCustomRopeSimulation.Register(this);
			if (monkeBlockParent != null)
			{
				supportMovingAtRuntime = IsAttachedToMovingPiece();
			}
		}

		public void OnPieceActivate()
		{
			if (monkeBlockParent != null)
			{
				supportMovingAtRuntime = IsAttachedToMovingPiece();
			}
		}

		private bool IsAttachedToMovingPiece()
		{
			if (monkeBlockParent.attachIndex >= 0 && monkeBlockParent.attachIndex < monkeBlockParent.gridPlanes.Count)
			{
				return monkeBlockParent.gridPlanes[monkeBlockParent.attachIndex].GetMovingParentGrid() != null;
			}
			return false;
		}

		public void OnPieceDeactivate()
		{
			supportMovingAtRuntime = false;
		}
	}
	public class GorillaRopeSwingUpdateManager : MonoBehaviour
	{
		public static GorillaRopeSwingUpdateManager instance;

		public static bool hasInstance = false;

		public static List<GorillaRopeSwing> allGorillaRopeSwings = new List<GorillaRopeSwing>();

		protected void Awake()
		{
			if (hasInstance && instance != null && instance != this)
			{
				UnityEngine.Object.Destroy(this);
			}
			else
			{
				SetInstance(this);
			}
		}

		public static void CreateManager()
		{
			SetInstance(new GameObject("GorillaRopeSwingUpdateManager").AddComponent<GorillaRopeSwingUpdateManager>());
		}

		private static void SetInstance(GorillaRopeSwingUpdateManager manager)
		{
			instance = manager;
			hasInstance = true;
			if (UnityEngine.Application.isPlaying)
			{
				UnityEngine.Object.DontDestroyOnLoad(manager);
			}
		}

		public static void RegisterRopeSwing(GorillaRopeSwing ropeSwing)
		{
			if (!hasInstance)
			{
				CreateManager();
			}
			if (!allGorillaRopeSwings.Contains(ropeSwing))
			{
				allGorillaRopeSwings.Add(ropeSwing);
			}
		}

		public static void UnregisterRopeSwing(GorillaRopeSwing ropeSwing)
		{
			if (!hasInstance)
			{
				CreateManager();
			}
			if (allGorillaRopeSwings.Contains(ropeSwing))
			{
				allGorillaRopeSwings.Remove(ropeSwing);
			}
		}

		public void Update()
		{
			for (int i = 0; i < allGorillaRopeSwings.Count; i++)
			{
				allGorillaRopeSwings[i].InvokeUpdate();
			}
		}
	}
	[CreateAssetMenu(fileName = "GorillaRopeSwingSettings", menuName = "ScriptableObjects/GorillaRopeSwingSettings", order = 0)]
	public class GorillaRopeSwingSettings : ScriptableObject
	{
		public float inheritVelocityMultiplier = 1f;

		public float frictionWhenNotHeld = 0.25f;
	}
	public class GorillaZipline : MonoBehaviour
	{
		[SerializeField]
		protected Transform segmentsRoot;

		[SerializeField]
		protected GameObject segmentPrefab;

		[SerializeField]
		protected GorillaClimbable slideHelper;

		[SerializeField]
		private AudioSource audioSlide;

		protected BezierSpline spline;

		[SerializeField]
		private Transform climbOffsetHelper;

		[SerializeField]
		private GorillaZiplineSettings settings;

		[SerializeField]
		protected float ziplineDistance = 15f;

		[SerializeField]
		protected float segmentDistance = 0.9f;

		private GorillaHandClimber currentClimber;

		private float currentT;

		private const float inheritVelocityRechargeRate = 0.2f;

		private const float inheritVelocityValueOnRelease = 0.55f;

		private float currentInheritVelocityMulti = 1f;

		public float currentSpeed { get; private set; }

		protected void FindTFromDistance(ref float t, float distance, int steps = 1000)
		{
			float num = distance / (float)steps;
			UnityEngine.Vector3 b = spline.GetPointLocal(t);
			float num2 = 0f;
			for (int i = 0; i < 1000; i++)
			{
				t += num;
				if (!(t >= 1f) && !(t <= 0f))
				{
					UnityEngine.Vector3 pointLocal = spline.GetPointLocal(t);
					num2 += UnityEngine.Vector3.Distance(pointLocal, b);
					if (!(num2 >= Mathf.Abs(distance)))
					{
						b = pointLocal;
						continue;
					}
					break;
				}
				break;
			}
		}

		private float FindSlideHelperSpot(UnityEngine.Vector3 grabPoint)
		{
			int i = 0;
			int num = 200;
			float num2 = 0.001f;
			float num3 = 1f / (float)num;
			float3 y = base.transform.InverseTransformPoint(grabPoint);
			float result = 0f;
			float num4 = float.PositiveInfinity;
			for (; i < num; i++)
			{
				float num5 = math.distancesq(spline.GetPointLocal(num2), y);
				if (num5 < num4)
				{
					num4 = num5;
					result = num2;
				}
				num2 += num3;
			}
			return result;
		}

		protected virtual void Start()
		{
			spline = GetComponent<BezierSpline>();
			GorillaClimbable gorillaClimbable = slideHelper;
			gorillaClimbable.onBeforeClimb = (Action<GorillaHandClimber, GorillaClimbableRef>)Delegate.Combine(gorillaClimbable.onBeforeClimb, new Action<GorillaHandClimber, GorillaClimbableRef>(OnBeforeClimb));
		}

		private void OnDestroy()
		{
			GorillaClimbable gorillaClimbable = slideHelper;
			gorillaClimbable.onBeforeClimb = (Action<GorillaHandClimber, GorillaClimbableRef>)Delegate.Remove(gorillaClimbable.onBeforeClimb, new Action<GorillaHandClimber, GorillaClimbableRef>(OnBeforeClimb));
		}

		public UnityEngine.Vector3 GetCurrentDirection()
		{
			return spline.GetDirection(currentT);
		}

		protected virtual void OnBeforeClimb(GorillaHandClimber hand, GorillaClimbableRef climbRef)
		{
			bool num = currentClimber == null;
			currentClimber = hand;
			if ((bool)climbRef)
			{
				climbOffsetHelper.SetParent(climbRef.transform);
				climbOffsetHelper.position = hand.transform.position;
				climbOffsetHelper.localPosition = new UnityEngine.Vector3(0f, 0f, climbOffsetHelper.localPosition.z);
			}
			currentT = FindSlideHelperSpot(climbOffsetHelper.position);
			slideHelper.transform.localPosition = spline.GetPointLocal(currentT);
			if (num)
			{
				UnityEngine.Vector3 averagedVelocity = GTPlayer.Instance.AveragedVelocity;
				float num2 = UnityEngine.Vector3.Dot(averagedVelocity.normalized, spline.GetDirection(currentT));
				currentSpeed = averagedVelocity.magnitude * num2 * currentInheritVelocityMulti;
			}
		}

		private void Update()
		{
			if ((bool)currentClimber)
			{
				float num = 0f;
				UnityEngine.Vector3 direction = spline.GetDirection(currentT);
				num = Physics.gravity.y * direction.y * settings.gravityMulti;
				currentSpeed = Mathf.MoveTowards(currentSpeed, settings.maxSpeed, num * Time.deltaTime);
				float num2 = MathUtils.Linear(currentSpeed, 0f, settings.maxFrictionSpeed, settings.friction, settings.maxFriction);
				currentSpeed = Mathf.MoveTowards(currentSpeed, 0f, num2 * Time.deltaTime);
				currentSpeed = Mathf.Min(currentSpeed, settings.maxSpeed);
				currentSpeed = Mathf.Max(currentSpeed, 0f - settings.maxSpeed);
				float value = Mathf.Abs(currentSpeed);
				FindTFromDistance(ref currentT, currentSpeed * Time.deltaTime);
				slideHelper.transform.localPosition = spline.GetPointLocal(currentT);
				if (!audioSlide.gameObject.activeSelf)
				{
					audioSlide.gameObject.SetActive(value: true);
				}
				audioSlide.volume = MathUtils.Linear(value, 0f, settings.maxSpeed, settings.minSlideVolume, settings.maxSlideVolume);
				audioSlide.pitch = MathUtils.Linear(value, 0f, settings.maxSpeed, settings.minSlidePitch, settings.maxSlidePitch);
				if (!audioSlide.isPlaying)
				{
					audioSlide.GTPlay();
				}
				float num3 = MathUtils.Linear(value, 0f, settings.maxSpeed, -0.1f, 0.75f);
				if (num3 > 0f)
				{
					GorillaTagger.Instance.DoVibration(currentClimber.xrNode, num3, Time.deltaTime);
				}
				if (!spline.Loop)
				{
					if (currentT >= 1f || currentT <= 0f)
					{
						currentClimber.ForceStopClimbing(startingNewClimb: false, doDontReclimb: true);
					}
				}
				else if (currentT >= 1f)
				{
					currentT = 0f;
				}
				else if (currentT <= 0f)
				{
					currentT = 1f;
				}
				if (!slideHelper.isBeingClimbed)
				{
					Stop();
				}
			}
			if (currentInheritVelocityMulti < 1f)
			{
				currentInheritVelocityMulti += Time.deltaTime * 0.2f;
				currentInheritVelocityMulti = Mathf.Min(currentInheritVelocityMulti, 1f);
			}
		}

		private void Stop()
		{
			currentClimber = null;
			audioSlide.GTStop();
			audioSlide.gameObject.SetActive(value: false);
			currentInheritVelocityMulti = 0.55f;
			currentSpeed = 0f;
		}
	}
	public class GorillaZiplineSegment : MonoBehaviour
	{
		public float startT;
	}
	[CreateAssetMenu(fileName = "GorillaZiplineSettings", menuName = "ScriptableObjects/GorillaZiplineSettings", order = 0)]
	public class GorillaZiplineSettings : ScriptableObject
	{
		public float minSlidePitch = 0.5f;

		public float maxSlidePitch = 1f;

		public float minSlideVolume;

		public float maxSlideVolume = 0.2f;

		public float maxSpeed = 10f;

		public float gravityMulti = 1.1f;

