					throw new InvalidOperationException("Error when accessing TraverseSpline.Data. Networked properties can only be accessed when Spawned() has been called.");
				}
				return *(float*)((byte*)((NetworkBehaviour)this).Ptr + 0);
			}
			set
			{
				if (((NetworkBehaviour)this).Ptr == null)
				{
					throw new InvalidOperationException("Error when accessing TraverseSpline.Data. Networked properties can only be accessed when Spawned() has been called.");
				}
				*(float*)((byte*)((NetworkBehaviour)this).Ptr + 0) = value;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			progress = SplineProgressOffet % 1f;
		}

		protected virtual void FixedUpdate()
		{
			if (!base.IsMine && progressLerpStartTime + 1f > Time.time)
			{
				progress = Mathf.Lerp(progressLerpStart, progressLerpEnd, (Time.time - progressLerpStartTime) / 1f);
			}
			else
			{
				if (isHeldByLocalPlayer)
				{
					currentSpeedMultiplier = Mathf.MoveTowards(currentSpeedMultiplier, speedMultiplierWhileHeld, acceleration * Time.deltaTime);
				}
				else
				{
					currentSpeedMultiplier = Mathf.MoveTowards(currentSpeedMultiplier, 1f, deceleration * Time.deltaTime);
				}
				if (goingForward)
				{
					progress += Time.deltaTime * currentSpeedMultiplier / duration;
					if (progress > 1f)
					{
						if (mode == SplineWalkerMode.Once)
						{
							progress = 1f;
						}
						else if (mode == SplineWalkerMode.Loop)
						{
							progress %= 1f;
						}
						else
						{
							progress = 2f - progress;
							goingForward = false;
						}
					}
				}
				else
				{
					progress -= Time.deltaTime * currentSpeedMultiplier / duration;
					if (progress < 0f)
					{
						progress = 0f - progress;
						goingForward = true;
					}
				}
			}
			UnityEngine.Vector3 point = spline.GetPoint(progress, constantVelocity);
			base.transform.position = point;
			if (lookForward)
			{
				base.transform.LookAt(base.transform.position + spline.GetDirection(progress, constantVelocity));
			}
		}

		public override void WriteDataFusion()
		{
			Data = progress + currentSpeedMultiplier * 1f / duration;
		}

		public override void ReadDataFusion()
		{
			progressLerpEnd = Data;
			ReadDataShared();
		}

		protected override void WriteDataPUN(PhotonStream stream, PhotonMessageInfo info)
		{
			stream.SendNext(progress + currentSpeedMultiplier * 1f / duration);
		}

		protected override void ReadDataPUN(PhotonStream stream, PhotonMessageInfo info)
		{
			progressLerpEnd = (float)stream.ReceiveNext();
			ReadDataShared();
		}

		private void ReadDataShared()
		{
			if (float.IsNaN(progressLerpEnd) || float.IsInfinity(progressLerpEnd))
			{
				progressLerpEnd = 1f;
			}
			else
			{
				progressLerpEnd = Mathf.Abs(progressLerpEnd);
				if (progressLerpEnd > 1f)
				{
					progressLerpEnd = (float)((double)progressLerpEnd % 1.0);
				}
			}
			progressLerpStart = ((Mathf.Abs(progressLerpEnd - progress) > Mathf.Abs(progressLerpEnd - (progress - 1f))) ? (progress - 1f) : progress);
			progressLerpStartTime = Time.time;
		}

		protected float GetProgress()
		{
			return progress;
		}

		public float GetCurrentSpeed()
		{
			return currentSpeedMultiplier;
		}

		[WeaverGenerated]
		public override void CopyBackingFieldsToState(bool P_0)
		{
			base.CopyBackingFieldsToState(P_0);
			Data = _Data;
		}

		[WeaverGenerated]
		public override void CopyStateToBackingFields()
		{
			base.CopyStateToBackingFields();
			_Data = Data;
		}
	}
	public class VectorizedCustomRopeSimulation : MonoBehaviour
	{
		public static VectorizedCustomRopeSimulation instance;

		public const int MAX_NODE_COUNT = 32;

		public const float MAX_ROPE_SPEED = 15f;

		private List<Transform> nodes = new List<Transform>();

		[SerializeField]
		private float nodeDistance = 1f;

		[SerializeField]
		private int applyConstraintIterations = 20;

		[SerializeField]
		private int finalPassIterations = 1;

		[SerializeField]
		private float gravity = -0.15f;

		private VectorizedBurstRopeData burstData;

		private float lastDelta = 0.02f;

		private List<GorillaRopeSwing> ropes = new List<GorillaRopeSwing>();

		private static List<GorillaRopeSwing> registerQueue = new List<GorillaRopeSwing>();

		private static List<GorillaRopeSwing> deregisterQueue = new List<GorillaRopeSwing>();

		private void Awake()
		{
			instance = this;
		}

		public static void Register(GorillaRopeSwing rope)
		{
			registerQueue.Add(rope);
		}

		public static void Unregister(GorillaRopeSwing rope)
		{
			deregisterQueue.Add(rope);
		}

		private void RegenerateData()
		{
			Dispose();
			foreach (GorillaRopeSwing item in registerQueue)
			{
				ropes.Add(item);
			}
			foreach (GorillaRopeSwing item2 in deregisterQueue)
			{
				ropes.Remove(item2);
			}
			registerQueue.Clear();
			deregisterQueue.Clear();
			int i;
			for (i = ropes.Count; i % 4 != 0; i++)
			{
			}
			int num = i * 32 / 4;
			burstData = new VectorizedBurstRopeData
			{
				posX = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent),
				posY = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent),
				posZ = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent),
				validNodes = new NativeArray<int4>(num, Unity.Collections.Allocator.Persistent),
				lastPosX = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent),
				lastPosY = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent),
				lastPosZ = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent),
				ropeRoots = new NativeArray<float3>(i, Unity.Collections.Allocator.Persistent),
				nodeMass = new NativeArray<float4>(num, Unity.Collections.Allocator.Persistent)
			};
			for (int j = 0; j < ropes.Count; j += 4)
			{
				for (int k = 0; k < 4 && ropes.Count > j + k; k++)
				{
					ropes[j + k].ropeDataStartIndex = 32 * j / 4;
					ropes[j + k].ropeDataIndexOffset = k;
				}
			}
			int num2 = 0;
			for (int l = 0; l < num; l++)
			{
				float4 value = burstData.posX[l];
				float4 value2 = burstData.posY[l];
				float4 value3 = burstData.posZ[l];
				int4 value4 = burstData.validNodes[l];
				for (int m = 0; m < 4; m++)
				{
					int num3 = num2 * 4 + m;
					int num4 = l - num2 * 32;
					if (ropes.Count > num3 && ropes[num3].nodes.Length > num4)
					{
						UnityEngine.Vector3 localPosition = ropes[num3].nodes[num4].localPosition;
						value[m] = localPosition.x;
						value2[m] = localPosition.y;
						value3[m] = localPosition.z;
						value4[m] = 1;
					}
					else
					{
						value[m] = 0f;
						value2[m] = 0f;
						value3[m] = 0f;
						value4[m] = 0;
					}
				}
				if (l > 0 && (l + 1) % 32 == 0)
				{
					num2++;
				}
				burstData.posX[l] = value;
				burstData.posY[l] = value2;
				burstData.posZ[l] = value3;
				burstData.lastPosX[l] = value;
				burstData.lastPosY[l] = value2;
				burstData.lastPosZ[l] = value3;
				burstData.validNodes[l] = value4;
				burstData.nodeMass[l] = math.float4(1f, 1f, 1f, 1f);
			}
			for (int n = 0; n < ropes.Count; n++)
			{
				burstData.ropeRoots[n] = float3.zero;
			}
		}

		private void Dispose()
		{
			if (burstData.posX.IsCreated)
			{
				burstData.posX.Dispose();
				burstData.posY.Dispose();
				burstData.posZ.Dispose();
				burstData.validNodes.Dispose();
				burstData.lastPosX.Dispose();
				burstData.lastPosY.Dispose();
				burstData.lastPosZ.Dispose();
				burstData.ropeRoots.Dispose();
				burstData.nodeMass.Dispose();
			}
		}

		private void OnDestroy()
		{
			Dispose();
		}

		public void SetRopePos(GorillaRopeSwing ropeTarget, UnityEngine.Vector3[] positions, bool setCurPos, bool setLastPos, int onlySetIndex = -1)
		{
			if (!ropes.Contains(ropeTarget))
			{
				return;
			}
			int ropeDataIndexOffset = ropeTarget.ropeDataIndexOffset;
			for (int i = 0; i < positions.Length; i++)
			{
				if (onlySetIndex < 0 || i == onlySetIndex)
				{
					int index = ropeTarget.ropeDataStartIndex + i;
					if (setCurPos)
					{
						float4 value = burstData.posX[index];
						float4 value2 = burstData.posY[index];
						float4 value3 = burstData.posZ[index];
						value[ropeDataIndexOffset] = positions[i].x;
						value2[ropeDataIndexOffset] = positions[i].y;
						value3[ropeDataIndexOffset] = positions[i].z;
						burstData.posX[index] = value;
						burstData.posY[index] = value2;
						burstData.posZ[index] = value3;
					}
					if (setLastPos)
					{
						float4 value4 = burstData.lastPosX[index];
						float4 value5 = burstData.lastPosY[index];
						float4 value6 = burstData.lastPosZ[index];
						value4[ropeDataIndexOffset] = positions[i].x;
						value5[ropeDataIndexOffset] = positions[i].y;
						value6[ropeDataIndexOffset] = positions[i].z;
						burstData.lastPosX[index] = value4;
						burstData.lastPosY[index] = value5;
						burstData.lastPosZ[index] = value6;
					}
				}
			}
		}

		public void SetVelocity(GorillaRopeSwing ropeTarget, UnityEngine.Vector3 velocity, bool wholeRope, int boneIndex = 1)
		{
			List<UnityEngine.Vector3> list = new List<UnityEngine.Vector3>();
			float maxLength = math.min(velocity.magnitude, 15f);
			int ropeDataStartIndex = ropeTarget.ropeDataStartIndex;
			int ropeDataIndexOffset = ropeTarget.ropeDataIndexOffset;
			if (ropeTarget.SupportsMovingAtRuntime)
			{
				velocity = UnityEngine.Quaternion.Inverse(ropeTarget.transform.rotation) * velocity;
			}
			for (int i = 0; i < ropeTarget.nodes.Length; i++)
			{
				UnityEngine.Vector3 item = new UnityEngine.Vector3(burstData.lastPosX[ropeDataStartIndex + i][ropeDataIndexOffset], burstData.lastPosY[ropeDataStartIndex + i][ropeDataIndexOffset], burstData.lastPosZ[ropeDataStartIndex + i][ropeDataIndexOffset]);
				if ((wholeRope || boneIndex == i) && boneIndex > 0)
				{
					UnityEngine.Vector3 vector = velocity / boneIndex * i;
					vector = UnityEngine.Vector3.ClampMagnitude(vector, maxLength);
					list.Add(item += vector * lastDelta);
				}
				else
				{
					list.Add(item);
				}
			}
			int onlySetIndex = -1;
			if (!wholeRope && boneIndex > 0)
			{
				onlySetIndex = boneIndex;
			}
			SetRopePos(ropeTarget, list.ToArray(), setCurPos: true, setLastPos: false, onlySetIndex);
		}

		public UnityEngine.Vector3 GetNodeVelocity(GorillaRopeSwing ropeTarget, int nodeIndex)
		{
			int index = ropeTarget.ropeDataStartIndex + nodeIndex;
			int ropeDataIndexOffset = ropeTarget.ropeDataIndexOffset;
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(burstData.posX[index][ropeDataIndexOffset], burstData.posY[index][ropeDataIndexOffset], burstData.posZ[index][ropeDataIndexOffset]);
			UnityEngine.Vector3 vector2 = new UnityEngine.Vector3(burstData.lastPosX[index][ropeDataIndexOffset], burstData.lastPosY[index][ropeDataIndexOffset], burstData.lastPosZ[index][ropeDataIndexOffset]);
			UnityEngine.Vector3 vector3 = (vector - vector2) / lastDelta;
			if (ropeTarget.SupportsMovingAtRuntime)
			{
				vector3 = ropeTarget.transform.rotation * vector3;
			}
			return vector3;
		}

		public void SetMassForPlayers(GorillaRopeSwing ropeTarget, bool hasPlayers, int furthestBoneIndex = 0)
		{
			if (!ropes.Contains(ropeTarget))
			{
				return;
			}
			int ropeDataIndexOffset = ropeTarget.ropeDataIndexOffset;
			for (int i = 0; i < 32; i++)
			{
				int index = ropeTarget.ropeDataStartIndex + i;
				float4 value = burstData.nodeMass[index];
				if (hasPlayers && i == furthestBoneIndex + 1)
				{
					value[ropeDataIndexOffset] = 0.1f;
				}
				else
				{
					value[ropeDataIndexOffset] = 1f;
				}
				burstData.nodeMass[index] = value;
			}
		}

		private void Update()
		{
			if (registerQueue.Count > 0 || deregisterQueue.Count > 0)
			{
				RegenerateData();
			}
			if (ropes.Count <= 0)
			{
				return;
			}
			float deltaTime = math.min(Time.deltaTime, 0.05f);
			VectorizedSolveRopeJob jobData = new VectorizedSolveRopeJob
			{
				applyConstraintIterations = applyConstraintIterations,
				finalPassIterations = finalPassIterations,
				lastDeltaTime = lastDelta,
				deltaTime = deltaTime,
				gravity = gravity,
				data = burstData,
				nodeDistance = nodeDistance,
				ropeCount = ropes.Count
			};
			jobData.Schedule().Complete();
			for (int i = 0; i < ropes.Count; i++)
			{
				GorillaRopeSwing gorillaRopeSwing = ropes[i];
				if (gorillaRopeSwing.isIdle && gorillaRopeSwing.isFullyIdle)
				{
					continue;
				}
				int ropeDataIndexOffset = gorillaRopeSwing.ropeDataIndexOffset;
				for (int j = 0; j < gorillaRopeSwing.nodes.Length; j++)
				{
					int index = gorillaRopeSwing.ropeDataStartIndex + j;
					gorillaRopeSwing.nodes[j].localPosition = new UnityEngine.Vector3(jobData.data.posX[index][ropeDataIndexOffset], jobData.data.posY[index][ropeDataIndexOffset], jobData.data.posZ[index][ropeDataIndexOffset]);
				}
				if (gorillaRopeSwing.SupportsMovingAtRuntime)
				{
					for (int k = 0; k < gorillaRopeSwing.nodes.Length - 1; k++)
					{
						Transform transform = gorillaRopeSwing.nodes[k];
						_ = gorillaRopeSwing.ropeDataStartIndex;
						transform.up = gorillaRopeSwing.transform.rotation * -(gorillaRopeSwing.nodes[k + 1].localPosition - transform.localPosition);
					}
				}
				else
				{
					for (int l = 0; l < gorillaRopeSwing.nodes.Length - 1; l++)
					{
						Transform transform2 = gorillaRopeSwing.nodes[l];
						_ = gorillaRopeSwing.ropeDataStartIndex;
						transform2.up = -(gorillaRopeSwing.nodes[l + 1].localPosition - transform2.localPosition);
					}
				}
			}
			lastDelta = deltaTime;
		}
	}
	public struct VectorizedBurstRopeData
	{
		public NativeArray<float4> posX;

		public NativeArray<float4> posY;

		public NativeArray<float4> posZ;

		public NativeArray<int4> validNodes;

		public NativeArray<float4> lastPosX;

		public NativeArray<float4> lastPosY;

		public NativeArray<float4> lastPosZ;

		public NativeArray<float3> ropeRoots;

		public NativeArray<float4> nodeMass;
	}
	[BurstCompile(FloatPrecision.Low, FloatMode.Fast)]
	public struct VectorizedSolveRopeJob : IJob
	{
		[Unity.Collections.ReadOnly]
		public int applyConstraintIterations;

		[Unity.Collections.ReadOnly]
		public int finalPassIterations;

		[Unity.Collections.ReadOnly]
		public float deltaTime;

		[Unity.Collections.ReadOnly]
		public float lastDeltaTime;

		[Unity.Collections.ReadOnly]
		public int ropeCount;

		public VectorizedBurstRopeData data;

		[Unity.Collections.ReadOnly]
		public float gravity;

		[Unity.Collections.ReadOnly]
		public float nodeDistance;

		public void Execute()
		{
			Simulate();
			for (int i = 0; i < applyConstraintIterations; i++)
			{
				ApplyConstraint();
			}
			for (int j = 0; j < finalPassIterations; j++)
			{
				FinalPass();
			}
		}

		private void Simulate()
		{
			for (int i = 0; i < data.posX.Length; i++)
			{
				float4 float5 = (data.posX[i] - data.lastPosX[i]) / lastDeltaTime;
				float4 float6 = (data.posY[i] - data.lastPosY[i]) / lastDeltaTime;
				float4 float7 = (data.posZ[i] - data.lastPosZ[i]) / lastDeltaTime;
				data.lastPosX[i] = data.posX[i];
				data.lastPosY[i] = data.posY[i];
				data.lastPosZ[i] = data.posZ[i];
				float4 float8 = data.lastPosX[i] + float5 * deltaTime * 0.996f;
				float4 float9 = data.lastPosY[i] + float6 * deltaTime;
				float4 float10 = data.lastPosZ[i] + float7 * deltaTime * 0.996f;
				float9 += gravity * deltaTime;
				data.posX[i] = float8 * data.validNodes[i];
				data.posY[i] = float9 * data.validNodes[i];
				data.posZ[i] = float10 * data.validNodes[i];
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static void dot4(ref float4 ax, ref float4 ay, ref float4 az, ref float4 bx, ref float4 by, ref float4 bz, ref float4 output)
		{
			output = ax * bx + ay * by + az * bz;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static void length4(ref float4 xVals, ref float4 yVals, ref float4 zVals, ref float4 output)
		{
			float4 output2 = float4.zero;
			dot4(ref xVals, ref yVals, ref zVals, ref xVals, ref yVals, ref zVals, ref output2);
			output2 = math.abs(output2);
			output = math.sqrt(output2);
		}

		private void ConstrainRoots()
		{
			int num = 0;
			for (int i = 0; i < data.posX.Length; i += 32)
			{
				for (int j = 0; j < 4; j++)
				{
					float4 value = data.posX[i];
					float4 value2 = data.posY[i];
					float4 value3 = data.posZ[i];
					value[j] = data.ropeRoots[num].x;
					value2[j] = data.ropeRoots[num].y;
					value3[j] = data.ropeRoots[num].z;
					data.posX[i] = value;
					data.posY[i] = value2;
					data.posZ[i] = value3;
					num++;
				}
			}
		}

		private void ApplyConstraint()
		{
			ConstrainRoots();
			float4 float5 = math.int4(-1, -1, -1, -1);
			for (int i = 0; i < ropeCount; i += 4)
			{
				for (int j = 0; j < 31; j++)
				{
					int num = i / 4 * 32 + j;
					float4 float6 = data.validNodes[num];
					float4 float7 = data.validNodes[num + 1];
					if (!(math.lengthsq(float7) < 0.1f))
					{
						float4 output = float4.zero;
						float4 xVals = data.posX[num] - data.posX[num + 1];
						float4 yVals = data.posY[num] - data.posY[num + 1];
						float4 zVals = data.posZ[num] - data.posZ[num + 1];
						length4(ref xVals, ref yVals, ref zVals, ref output);
						float4 float8 = math.abs(output - nodeDistance);
						float4 obj = math.sign(output - nodeDistance);
						output += float6 - float5;
						output += 0.01f;
						float4 float9 = xVals / output;
						float4 float10 = yVals / output;
						float4 float11 = zVals / output;
						float4 float12 = obj * float9 * float8;
						float4 float13 = obj * float10 * float8;
						float4 float14 = obj * float11 * float8;
						float4 float15 = data.nodeMass[num] / (data.nodeMass[num] + data.nodeMass[num + 1]);
						float4 float16 = data.nodeMass[num + 1] / (data.nodeMass[num] + data.nodeMass[num + 1]);
						data.posX[num] -= float12 * float7 * float15;
						data.posY[num] -= float13 * float7 * float15;
						data.posZ[num] -= float14 * float7 * float15;
						data.posX[num + 1] += float12 * float7 * float16;
						data.posY[num + 1] += float13 * float7 * float16;
						data.posZ[num + 1] += float14 * float7 * float16;
					}
				}
			}
		}

		private void FinalPass()
		{
			ConstrainRoots();
			float4 float5 = math.int4(-1, -1, -1, -1);
			for (int i = 0; i < ropeCount; i += 4)
			{
				for (int j = 0; j < 31; j++)
				{
					int num = i / 4 * 32 + j;
					_ = (float4)data.validNodes[num];
					float4 float6 = data.validNodes[num + 1];
					float4 output = float4.zero;
					float4 xVals = data.posX[num] - data.posX[num + 1];
					float4 yVals = data.posY[num] - data.posY[num + 1];
					float4 zVals = data.posZ[num] - data.posZ[num + 1];
					length4(ref xVals, ref yVals, ref zVals, ref output);
					float4 float7 = math.abs(output - nodeDistance);
					float4 obj = math.sign(output - nodeDistance);
					output += data.validNodes[num] - float5;
					output += 0.01f;
					float4 float8 = xVals / output;
					float4 float9 = yVals / output;
					float4 float10 = zVals / output;
					float4 float11 = obj * float8 * float7;
					float4 float12 = obj * float9 * float7;
					float4 float13 = obj * float10 * float7;
					data.posX[num + 1] += float11 * float6;
					data.posY[num + 1] += float12 * float6;
					data.posZ[num + 1] += float13 * float6;
				}
			}
		}
	}
