	public class GorillaClimbable : MonoBehaviour
	{
		public bool snapX;

		public bool snapY;

		public bool snapZ;

		public float maxDistanceSnap = 0.05f;

		public AudioClip clip;

		public AudioClip clipOnFullRelease;

