	public class GorillaHandClimber : MonoBehaviour
	{
		[SerializeField]
		private GTPlayer player;

		[SerializeField]
		private EquipmentInteractor equipmentInteractor;

		private List<GorillaClimbable> potentialClimbables = new List<GorillaClimbable>();

		[Header("Non-hand input should have the component disabled")]
		public XRNode xrNode = XRNode.LeftHand;

		[NonSerialized]
		public bool isClimbing;

		[NonSerialized]
		public bool queuedToBecomeValidToGrabAgain;

		[NonSerialized]
		public GorillaClimbable dontReclimbLast;

		[NonSerialized]
		public UnityEngine.Vector3 lastAutoReleasePos = UnityEngine.Vector3.zero;

		public GorillaGrabber grabber;

		public Transform handRoot;

		private const float DIST_FOR_CLEAR_RELEASE = 0.35f;

		private const float DIST_FOR_GRAB = 0.15f;

		private Collider col;

		private bool canRelease = true;

		public bool isClimbingOrGrabbing
		{
			get
			{
				if (!isClimbing)
				{
					return grabber.isGrabbing;
				}
				return true;
			}
		}

		private void Awake()
		{
			col = GetComponent<Collider>();
			grabber = GetComponent<GorillaGrabber>();
		}

		public void CheckHandClimber()
		{
			for (int num = potentialClimbables.Count - 1; num >= 0; num--)
			{
				GorillaClimbable gorillaClimbable = potentialClimbables[num];
				if (gorillaClimbable == null || !gorillaClimbable.isActiveAndEnabled)
				{
					potentialClimbables.RemoveAt(num);
				}
				else if (gorillaClimbable.climbOnlyWhileSmall && !ZoneManagement.IsInZone(GTZone.monkeBlocksShared) && player.scale > 0.99f)
				{
					potentialClimbables.RemoveAt(num);
				}
			}
			bool grab = ControllerInputPoller.GetGrab(xrNode);
			bool grabRelease = ControllerInputPoller.GetGrabRelease(xrNode);
			if (!isClimbing)
			{
				if (queuedToBecomeValidToGrabAgain && UnityEngine.Vector3.Distance(lastAutoReleasePos, handRoot.localPosition) >= 0.35f)
				{
					queuedToBecomeValidToGrabAgain = false;
				}
				if (grabRelease)
				{
					queuedToBecomeValidToGrabAgain = false;
					dontReclimbLast = null;
				}
				GorillaClimbable closestClimbable = GetClosestClimbable();
				if (!queuedToBecomeValidToGrabAgain && (bool)closestClimbable && grab && CanInitiateClimb() && closestClimbable != dontReclimbLast)
				{
					if (closestClimbable is GorillaClimbableRef gorillaClimbableRef)
					{
						player.BeginClimbing(gorillaClimbableRef.climb, this, gorillaClimbableRef);
					}
					else
					{
						player.BeginClimbing(closestClimbable, this);
					}
				}
			}
			else if (grabRelease && canRelease)
			{
				player.EndClimbing(this, startingNewClimb: false);
			}
			grabber.CheckGrabber(CanInitiateClimb() && grab);
		}

		private bool CanInitiateClimb()
		{
			if (!isClimbing && !equipmentInteractor.GetIsHolding(xrNode) && !equipmentInteractor.builderPieceInteractor.GetIsHolding(xrNode) && !equipmentInteractor.IsGrabDisabled(xrNode) && !GamePlayerLocal.IsHandHolding(xrNode))
			{
				return !player.inOverlay;
			}
			return false;
		}

		public void SetCanRelease(bool canRelease)
		{
			this.canRelease = canRelease;
		}

		public GorillaClimbable GetClosestClimbable()
		{
			if (potentialClimbables.Count == 0)
			{
				return null;
			}
			if (potentialClimbables.Count == 1)
			{
				return potentialClimbables[0];
			}
			UnityEngine.Vector3 position = base.transform.position;
			Bounds bounds = col.bounds;
			float num = 0.15f;
			GorillaClimbable result = null;
			foreach (GorillaClimbable potentialClimbable in potentialClimbables)
			{
				float num2 = float.MaxValue;
				if ((bool)potentialClimbable.colliderCache)
				{
					if (!bounds.Intersects(potentialClimbable.colliderCache.bounds))
					{
						continue;
					}
					UnityEngine.Vector3 b = potentialClimbable.colliderCache.ClosestPoint(position);
					num2 = UnityEngine.Vector3.Distance(position, b);
				}
				else
				{
					num2 = UnityEngine.Vector3.Distance(position, potentialClimbable.transform.position);
				}
				if (num2 < num)
				{
					result = potentialClimbable;
					num = num2;
				}
			}
			return result;
		}

		private void OnTriggerEnter(Collider other)
		{
			GorillaClimbableRef component2;
			if (other.TryGetComponent<GorillaClimbable>(out var component))
			{
				potentialClimbables.Add(component);
			}
			else if (other.TryGetComponent<GorillaClimbableRef>(out component2))
			{
				potentialClimbables.Add(component2);
			}
		}

		private void OnTriggerExit(Collider other)
		{
			GorillaClimbableRef component2;
			if (other.TryGetComponent<GorillaClimbable>(out var component))
			{
				potentialClimbables.Remove(component);
			}
			else if (other.TryGetComponent<GorillaClimbableRef>(out component2))
			{
				potentialClimbables.Remove(component2);
			}
		}

		public void ForceStopClimbing(bool startingNewClimb = false, bool doDontReclimb = false)
		{
			player.EndClimbing(this, startingNewClimb, doDontReclimb);
		}
	}
	public class GorillaVelocityTracker : MonoBehaviour, ITickSystemTick
	{
		public class VelocityDataPoint
		{
			public UnityEngine.Vector3 delta;

			public float time = -1f;
		}

		[SerializeField]
		private int maxDataPoints = 20;

		[SerializeField]
		private Transform relativeTo;

		[Tooltip("Use in Editor to trigger events when above or higher than a desired latest velocity.")]
		[SerializeField]
		private bool useVelocityEvents;

		[SerializeField]
		private float latestVelocityThreshold;

		public UnityEvent OnLatestBelowThreshold;

		public UnityEvent OnLatestAboveThreshold;

		[SerializeField]
		private bool useWorldSpaceForEvents;

		private bool wasAboveThreshold;

		private int currentDataPointIndex;

		private VelocityDataPoint[] localSpaceData;

		private VelocityDataPoint[] worldSpaceData;

		private Transform trans;

		private UnityEngine.Vector3 lastWorldSpacePos;

		private UnityEngine.Vector3 lastLocalSpacePos;

		private bool isRelativeTo;

		private int lastTickedFrame = -1;

		public bool TickRunning { get; set; }

		public void ResetState()
		{
			trans = base.transform;
			localSpaceData = new VelocityDataPoint[maxDataPoints];
			PopulateArray(localSpaceData);
			worldSpaceData = new VelocityDataPoint[maxDataPoints];
			PopulateArray(worldSpaceData);
			isRelativeTo = relativeTo != null;
			lastLocalSpacePos = GetPosition(worldSpace: false);
			lastWorldSpacePos = GetPosition(worldSpace: true);
			wasAboveThreshold = false;
			void PopulateArray(VelocityDataPoint[] array)
			{
				for (int i = 0; i < maxDataPoints; i++)
				{
					array[i] = new VelocityDataPoint();
				}
			}
		}

		private void Awake()
		{
			ResetState();
		}

		private void OnEnable()
		{
			TickSystem<object>.AddTickCallback(this);
		}

		private void OnDisable()
		{
			ResetState();
			TickSystem<object>.RemoveTickCallback(this);
		}

		public void SetRelativeTo(Transform tf)
		{
			relativeTo = tf;
			isRelativeTo = tf != null;
		}

		private UnityEngine.Vector3 GetPosition(bool worldSpace)
		{
			if (worldSpace)
			{
				return trans.position;
			}
			if (isRelativeTo)
			{
				return relativeTo.InverseTransformPoint(trans.position);
			}
			return trans.localPosition;
		}

		public void Tick()
		{
			if (Time.frameCount > lastTickedFrame)
			{
				UnityEngine.Vector3 position = GetPosition(worldSpace: false);
				UnityEngine.Vector3 position2 = GetPosition(worldSpace: true);
				VelocityDataPoint velocityDataPoint = localSpaceData[currentDataPointIndex];
				velocityDataPoint.delta = (position - lastLocalSpacePos) / Time.deltaTime;
				velocityDataPoint.time = Time.time;
				localSpaceData[currentDataPointIndex] = velocityDataPoint;
				VelocityDataPoint velocityDataPoint2 = worldSpaceData[currentDataPointIndex];
				velocityDataPoint2.delta = (position2 - lastWorldSpacePos) / Time.deltaTime;
				velocityDataPoint2.time = Time.time;
				worldSpaceData[currentDataPointIndex] = velocityDataPoint2;
				lastLocalSpacePos = position;
				lastWorldSpacePos = position2;
				currentDataPointIndex++;
				if (currentDataPointIndex >= maxDataPoints)
				{
					currentDataPointIndex = 0;
				}
				if (useVelocityEvents)
				{
					GetLatestVelocity(useWorldSpaceForEvents);
				}
				lastTickedFrame = Time.frameCount;
			}
		}

		private void AddToQueue(ref List<VelocityDataPoint> dataPoints, VelocityDataPoint newData)
		{
			dataPoints.Add(newData);
			if (dataPoints.Count >= maxDataPoints)
			{
				dataPoints.RemoveAt(0);
			}
		}

		public UnityEngine.Vector3 GetAverageVelocity(bool worldSpace = false, float maxTimeFromPast = 0.15f, bool doMagnitudeCheck = false)
		{
			float num = maxTimeFromPast / 2f;
			VelocityDataPoint[] array = ((!worldSpace) ? localSpaceData : worldSpaceData);
			if (array.Length <= 1)
			{
				return UnityEngine.Vector3.zero;
			}
			UnityEngine.Vector3 total = UnityEngine.Vector3.zero;
			float totalMag = 0f;
			int added = 0;
			float num2 = Time.time - maxTimeFromPast;
			float num3 = Time.time - num;
			int i = 0;
			int num4 = currentDataPointIndex;
			for (; i < maxDataPoints; i++)
			{
				VelocityDataPoint velocityDataPoint = array[num4];
				if (doMagnitudeCheck && added > 1 && velocityDataPoint.time >= num3)
				{
					if (velocityDataPoint.delta.magnitude >= totalMag / (float)added)
					{
						AddPoint(velocityDataPoint);
					}
				}
				else if (velocityDataPoint.time >= num2)
				{
					AddPoint(velocityDataPoint);
				}
				num4++;
				if (num4 >= maxDataPoints)
				{
					num4 = 0;
				}
			}
			if (added > 0)
			{
				return total / added;
			}
			return UnityEngine.Vector3.zero;
			void AddPoint(VelocityDataPoint point)
			{
				total += point.delta;
				totalMag += point.delta.magnitude;
				added++;
			}
		}

		public UnityEngine.Vector3 GetLatestVelocity(bool worldSpace = false)
		{
			VelocityDataPoint[] array = ((!worldSpace) ? localSpaceData : worldSpaceData);
			if (array[currentDataPointIndex].delta.magnitude >= latestVelocityThreshold && !wasAboveThreshold)
			{
				OnLatestAboveThreshold?.Invoke();
				wasAboveThreshold = true;
			}
			else if (array[currentDataPointIndex].delta.magnitude < latestVelocityThreshold && wasAboveThreshold)
			{
				OnLatestBelowThreshold?.Invoke();
				wasAboveThreshold = false;
			}
			return array[currentDataPointIndex].delta;
		}

		public float GetAverageSpeedChangeMagnitudeInDirection(UnityEngine.Vector3 dir, bool worldSpace = false, float maxTimeFromPast = 0.05f)
		{
			VelocityDataPoint[] array = ((!worldSpace) ? localSpaceData : worldSpaceData);
			if (array.Length <= 1)
			{
				return 0f;
			}
			float num = 0f;
			int num2 = 0;
			float num3 = Time.time - maxTimeFromPast;
			bool flag = false;
			UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].time >= num3)
				{
					if (!flag)
					{
						vector = array[i].delta;
						flag = true;
					}
					else
					{
						num += Mathf.Abs(UnityEngine.Vector3.Dot(array[i].delta - vector, dir));
						num2++;
					}
				}
			}
			if (num2 <= 0)
			{
				return 0f;
			}
			return num / (float)num2;
		}
	}
