		public static void CopyStringKeepDelimiterAtEnd(this HashSet<string> hash, string str, char delimiter)
		{
			if (string.IsNullOrEmpty(str))
			{
				return;
			}
			int i = 0;
			int num = 0;
			for (int length = str.Length; i < length; i++)
			{
				if (str[i] == delimiter)
				{
					hash.Add(str.Substring(num, i - num));
					num = i + 1;
				}
			}
		}

