		{
			List<TVal> list2 = new List<TVal>(list);
			TCol result = new TCol();
			int num = list2.Count;
			while (num > 1)
			{
				num--;
				int num2 = UnityEngine.Random.Range(0, num);
				List<TVal> list3 = list2;
				int index = num;
				List<TVal> list4 = list2;
				int index2 = num2;
				TVal val = list2[num2];
				TVal val2 = list2[num];
				TVal val3 = (list3[index] = val);
				val3 = (list4[index2] = val2);
