		public static UnityEngine.Vector3 GetAngularVelocity(UnityEngine.Quaternion oldRotation, UnityEngine.Quaternion newRotation)
		{
			UnityEngine.Quaternion quaternion2 = newRotation * UnityEngine.Quaternion.Inverse(oldRotation);
			if (Mathf.Abs(quaternion2.w) > 0.9995117f)
			{
				return UnityEngine.Vector3.zero;
			}
			float num2;
			if (quaternion2.w < 0f)
			{
				float num = Mathf.Acos(0f - quaternion2.w);
				num2 = -2f * num / (Mathf.Sin(num) * Time.deltaTime);
			}
			else
			{
				float num3 = Mathf.Acos(quaternion2.w);
				num2 = 2f * num3 / (Mathf.Sin(num3) * Time.deltaTime);
			}
			UnityEngine.Vector3 result = new UnityEngine.Vector3(quaternion2.x * num2, quaternion2.y * num2, quaternion2.z * num2);
			if (float.IsNaN(result.z))
			{
				return UnityEngine.Vector3.zero;
			}
			return result;
		}

		public static float FastInvSqrt(float z)
		{
			if (z == 0f)
			{
				return 0f;
			}
			FloatIntUnion floatIntUnion = default(FloatIntUnion);
			floatIntUnion.tmp = 0;
			float num = 0.5f * z;
			floatIntUnion.f = z;
			floatIntUnion.tmp = 1597463174 - (floatIntUnion.tmp >> 1);
			floatIntUnion.f *= 1.5f - num * floatIntUnion.f * floatIntUnion.f;
			return floatIntUnion.f * z;
		}

		public static float Dot2(in UnityEngine.Vector3 v)
		{
			return UnityEngine.Vector3.Dot(v, v);
		}

		public static UnityEngine.Vector4 RaycastToCappedCone(in UnityEngine.Vector3 rayOrigin, in UnityEngine.Vector3 rayDirection, in UnityEngine.Vector3 coneTip, in UnityEngine.Vector3 coneBase, in float coneTipRadius, in float coneBaseRadius)
		{
			UnityEngine.Vector3 vector = coneBase - coneTip;
			UnityEngine.Vector3 vector2 = rayOrigin - coneTip;
			UnityEngine.Vector3 vector3 = rayOrigin - coneBase;
			float num = UnityEngine.Vector3.Dot(vector, vector);
			float num2 = UnityEngine.Vector3.Dot(vector2, vector);
			float num3 = UnityEngine.Vector3.Dot(vector3, vector);
			float num4 = UnityEngine.Vector3.Dot(rayDirection, vector);
			if ((double)num2 < 0.0)
			{
				if (Dot2(vector2 * num4 - rayDirection * num2) < coneTipRadius * coneTipRadius * num4 * num4)
				{
					UnityEngine.Vector3 vector4 = -vector * FastInvSqrt(num);
					return new UnityEngine.Vector4((0f - num2) / num4, vector4.x, vector4.y, vector4.z);
				}
			}
			else if ((double)num3 > 0.0 && Dot2(vector3 * num4 - rayDirection * num3) < coneBaseRadius * coneBaseRadius * num4 * num4)
			{
				UnityEngine.Vector3 vector5 = vector * FastInvSqrt(num);
				return new UnityEngine.Vector4((0f - num3) / num4, vector5.x, vector5.y, vector5.z);
			}
			float num5 = UnityEngine.Vector3.Dot(rayDirection, vector2);
			float num6 = UnityEngine.Vector3.Dot(vector2, vector2);
			float num7 = coneTipRadius - coneBaseRadius;
			float num8 = num + num7 * num7;
			float num9 = num * num - num4 * num4 * num8;
			float num10 = num * num * num5 - num2 * num4 * num8 + num * coneTipRadius * (num7 * num4 * 1f);
			float num11 = num * num * num6 - num2 * num2 * num8 + num * coneTipRadius * (num7 * num2 * 2f - num * coneTipRadius);
			float num12 = num10 * num10 - num9 * num11;
			if ((double)num12 < 0.0)
			{
				return -UnityEngine.Vector4.one;
			}
			float num13 = (0f - num10 - Mathf.Sqrt(num12)) / num9;
			float num14 = num2 + num13 * num4;
			if ((double)num14 > 0.0 && num14 < num)
			{
				UnityEngine.Vector3 normalized = (num * (num * (vector2 + num13 * rayDirection) + num7 * vector * coneTipRadius) - vector * num8 * num14).normalized;
				return new UnityEngine.Vector4(num13, normalized.x, normalized.y, normalized.z);
			}
			return -UnityEngine.Vector4.one;
		}

		public static void LineSegClosestPoints(UnityEngine.Vector3 a, UnityEngine.Vector3 u, UnityEngine.Vector3 b, UnityEngine.Vector3 v, out UnityEngine.Vector3 lineAPoint, out UnityEngine.Vector3 lineBPoint)
		{
			lineAPoint = a;
			lineBPoint = b;
			UnityEngine.Vector3 lhs = b - a;
			float num = UnityEngine.Vector3.Dot(lhs, u);
			float num2 = UnityEngine.Vector3.Dot(lhs, v);
			float num3 = UnityEngine.Vector3.Dot(u, u);
			float num4 = UnityEngine.Vector3.Dot(u, v);
			float num5 = UnityEngine.Vector3.Dot(v, v);
			float num6 = num3 * num5 - num4 * num4;
			if (!((double)Mathf.Abs(num6) < 0.001))
			{
				float value = (num * num5 - num2 * num4) / num6;
				float value2 = (num * num4 - num2 * num3) / num6;
				value = Mathf.Clamp(value, 0f, 1f);
				float value3 = (Mathf.Clamp(value2, 0f, 1f) * num4 + num) / num3;
				float value4 = (value * num4 - num2) / num5;
				value3 = Mathf.Clamp(value3, 0f, 1f);
				value4 = Mathf.Clamp(value4, 0f, 1f);
				lineAPoint = a + value3 * u;
				lineBPoint = b + value4 * v;
			}
		}
