		public static UnityEngine.Vector3 Scale(this UnityEngine.Matrix4x4 m)
		{
			UnityEngine.Vector3 result = new UnityEngine.Vector3(m.GetColumn(0).magnitude, m.GetColumn(1).magnitude, m.GetColumn(2).magnitude);
			if (UnityEngine.Vector3.Cross(m.GetColumn(0), m.GetColumn(1)).normalized != (UnityEngine.Vector3)m.GetColumn(2).normalized)
			{
				result.x *= -1f;
			}
			return result;
		}

