		public static void DecomposeWithXFlip(this in UnityEngine.Matrix4x4 matrix, out UnityEngine.Vector3 transformation, out UnityEngine.Quaternion rotation, out UnityEngine.Vector3 scale)
		{
			UnityEngine.Matrix4x4 matrix2 = matrix;
			bool flag = matrix2.ValidTRS();
			transformation = matrix2.Position();
			rotation = (flag ? UnityEngine.Quaternion.LookRotation(matrix2.GetColumnNoCopy(2), matrix2.GetColumnNoCopy(1)) : UnityEngine.Quaternion.identity);
			scale = (flag ? matrix.lossyScale : UnityEngine.Vector3.zero);
		}

