				1 => new UnityEngine.Vector4(matrix.m01, matrix.m11, matrix.m21, matrix.m31), 
				2 => new UnityEngine.Vector4(matrix.m02, matrix.m12, matrix.m22, matrix.m32), 
				3 => new UnityEngine.Vector4(matrix.m03, matrix.m13, matrix.m23, matrix.m33), 
				_ => throw new IndexOutOfRangeException("Invalid column index!"), 
			};
		}

