		public static bool IsShorterThan(this UnityEngine.Vector2 v, float len)
		{
			return v.sqrMagnitude < len * len;
		}

		public static bool IsShorterThan(this UnityEngine.Vector2 v, UnityEngine.Vector2 v2)
		{
			return v.sqrMagnitude < v2.sqrMagnitude;
		}

