		public static UnityEngine.Vector3 Normalize(this UnityEngine.Vector3 value, out float existingMagnitude)
		{
			existingMagnitude = UnityEngine.Vector3.Magnitude(value);
			if (existingMagnitude > 1E-05f)
			{
				return value / existingMagnitude;
			}
			return UnityEngine.Vector3.zero;
		}

		public static UnityEngine.Vector3 GetClosestPoint(this Ray ray, UnityEngine.Vector3 target)
		{
			float num = UnityEngine.Vector3.Dot(target - ray.origin, ray.direction);
			return ray.origin + ray.direction * num;
		}

		public static float GetClosestDistSqr(this Ray ray, UnityEngine.Vector3 target)
		{
			return (ray.GetClosestPoint(target) - target).sqrMagnitude;
		}

		public static float GetClosestDistance(this Ray ray, UnityEngine.Vector3 target)
		{
			return (ray.GetClosestPoint(target) - target).magnitude;
		}

		public static UnityEngine.Vector3 ProjectToPlane(this Ray ray, UnityEngine.Vector3 planeOrigin, UnityEngine.Vector3 planeNormalMustBeLength1)
		{
			UnityEngine.Vector3 rhs = planeOrigin - ray.origin;
			float num = UnityEngine.Vector3.Dot(planeNormalMustBeLength1, rhs);
			float num2 = UnityEngine.Vector3.Dot(planeNormalMustBeLength1, ray.direction);
			return ray.origin + ray.direction * num / num2;
		}

		public static UnityEngine.Vector3 ProjectToLine(this Ray ray, UnityEngine.Vector3 lineStart, UnityEngine.Vector3 lineEnd)
		{
			UnityEngine.Vector3 normalized = (lineEnd - lineStart).normalized;
			UnityEngine.Vector3 normalized2 = UnityEngine.Vector3.Cross(UnityEngine.Vector3.Cross(ray.direction, normalized), normalized).normalized;
			return ray.ProjectToPlane(lineStart, normalized2);
		}

		public static bool IsNull(this UnityEngine.Object mono)
		{
			if ((object)mono != null)
			{
				return !mono;
			}
			return true;
		}

		public static bool IsNotNull(this UnityEngine.Object mono)
		{
			return !mono.IsNull();
		}

		public static UnityEngine.Vector3 Clamp(this UnityEngine.Vector3 value, UnityEngine.Vector3 min, UnityEngine.Vector3 max)
		{
			value.ClampThis(min, max);
			return value;
		}

		public static void ClampThis(this ref UnityEngine.Vector3 value, UnityEngine.Vector3 min, UnityEngine.Vector3 max)
		{
			value.x = Mathf.Clamp(value.x, min.x, max.x);
			value.y = Mathf.Clamp(value.y, min.y, max.y);
			value.z = Mathf.Clamp(value.z, min.z, max.z);
		}

		public static string GetPath(this Transform transform)
		{
			string text = transform.name;
			while ((bool)transform.parent)
			{
