		public static T GetComponentByPath<T>(this GameObject root, string path) where T : UnityEngine.Component
		{
			string[] array = path.Split(new string[1] { "/->/" }, StringSplitOptions.None);
			if (array.Length < 2)
			{
				return null;
			}
			string[] array2 = array[0].Split(new string[1] { "/" }, StringSplitOptions.RemoveEmptyEntries);
			Transform transform = root.transform;
			for (int i = 1; i < array2.Length; i++)
			{
				string n = array2[i];
				transform = transform.Find(n);
				if (transform == null)
				{
					return null;
				}
			}
			Type type = Type.GetType(array[1].Split('#')[0]);
			if (type == null)
			{
				return null;
			}
			UnityEngine.Component component = transform.GetComponent(type);
			if (component == null)
			{
				return null;
			}
			return component as T;
		}

