		public static bool TryFindByExactPath([System.Diagnostics.CodeAnalysis.NotNull] string path, out Transform result, FindObjectsInactive findObjectsInactive = FindObjectsInactive.Include)
		{
			if (string.IsNullOrEmpty(path))
			{
				throw new Exception("TryFindByExactPath: Provided path cannot be null or empty.");
			}
			if (findObjectsInactive == FindObjectsInactive.Exclude)
			{
				if (path[0] != '/')
				{
					path = "/" + path;
				}
				GameObject gameObject = GameObject.Find(path);
				if ((bool)gameObject)
				{
					result = gameObject.transform;
					return true;
				}
				result = null;
				return false;
			}
			for (int i = 0; i < SceneManager.sceneCount; i++)
			{
				Scene sceneAt = SceneManager.GetSceneAt(i);
				if (sceneAt.isLoaded && sceneAt.TryFindByExactPath(path, out result))
				{
					return true;
				}
			}
			result = null;
			return false;
		}

