		private static void _FindComponentsByExactPath<T>(Transform current, string[] splitPath, int index, List<T> components) where T : UnityEngine.Component
		{
			if (current.name != splitPath[index])
			{
				return;
			}
			if (index == splitPath.Length - 1)
			{
				T component = current.GetComponent<T>();
				if ((bool)component)
				{
					components.Add(component);
				}
				return;
			}
			foreach (Transform item in current)
			{
				_FindComponentsByExactPath(item, splitPath, index + 1, components);
			}
		}

