		public static void _FindComponentsByPath<T>(Transform current, string[] pathPartsRegex, List<T> components, bool caseSensitive) where T : UnityEngine.Component
		{
			List<Transform> value;
			using (UnityEngine.Pool.CollectionPool<List<Transform>, Transform>.Get(out value))
			{
				value.EnsureCapacity(64);
				if (_TryFindAllByPath(current, pathPartsRegex, 0, value, caseSensitive))
				{
					for (int i = 0; i < value.Count; i++)
					{
						T[] components2 = value[i].GetComponents<T>();
						components.AddRange(components2);
					}
				}
			}
		}

		private static bool _TryFindAllByPath(Transform current, IReadOnlyList<string> pathPartsRegex, int index, List<Transform> results, bool caseSensitive, bool isAtSceneLevel = false)
		{
			bool flag = false;
			if (isAtSceneLevel)
			{
				switch (pathPartsRegex[index])
				{
				case "..":
				case "..**":
				case "**..":
					return false;
				}
				for (int i = 0; i < SceneManager.sceneCount; i++)
				{
					Scene sceneAt = SceneManager.GetSceneAt(i);
					if (sceneAt.isLoaded)
					{
						GameObject[] rootGameObjects = sceneAt.GetRootGameObjects();
						foreach (GameObject gameObject in rootGameObjects)
						{
							flag |= _TryFindAllByPath(gameObject.transform, pathPartsRegex, index, results, caseSensitive);
						}
					}
				}
			}
			switch (pathPartsRegex[index])
			{
			case ".":
				if (index == pathPartsRegex.Count - 1)
				{
					results.Add(current);
					return true;
				}
				flag |= _TryFindAllByPath(current, pathPartsRegex, index + 1, results, caseSensitive);
				break;
			case "..":
				if ((bool)current.parent)
				{
					if (index == pathPartsRegex.Count - 1)
					{
						results.Add(current.parent);
						return true;
					}
					flag |= _TryFindAllByPath(current.parent, pathPartsRegex, index + 1, results, caseSensitive);
				}
				break;
			case "**":
			{
				Transform result;
				if (index == pathPartsRegex.Count - 1)
				{
					for (int k = 0; k < current.childCount; k++)
					{
						results.Add(current.GetChild(k));
						flag = true;
					}
				}
				else if (_TryBreadthFirstSearchNames(current, pathPartsRegex[index + 1], out result, caseSensitive))
				{
					if (index + 2 == pathPartsRegex.Count)
					{
						results.Add(result);
						return true;
					}
					flag |= _TryFindAllByPath(result, pathPartsRegex, index + 2, results, caseSensitive);
				}
				break;
			}
			case "..**":
			case "**..":
			{
				int l;
				for (l = index + 1; l < pathPartsRegex.Count; l++)
				{
					string text = pathPartsRegex[l];
					if (!(text == "..**") && !(text == "**.."))
					{
						break;
					}
				}
				if (l == pathPartsRegex.Count)
				{
					results.Add(current.root);
					return true;
				}
				Transform transform = current;
				while ((bool)transform)
				{
					flag |= _TryFindAllByPath(transform, pathPartsRegex, index + 1, results, caseSensitive);
					transform = transform.parent;
				}
				break;
			}
			default:
				if (!Regex.IsMatch(current.name, pathPartsRegex[index], (!caseSensitive) ? RegexOptions.IgnoreCase : RegexOptions.None))
				{
					break;
				}
				if (index == pathPartsRegex.Count - 1)
				{
					results.Add(current);
					return true;
				}
				foreach (Transform item in current)
				{
					flag |= _TryFindAllByPath(item, pathPartsRegex, index + 1, results, caseSensitive);
				}
				break;
			}
			return flag;
		}

		public static string[] _GlobPathToPathPartsRegex(string path)
		{
			string[] array = path.Split('/', StringSplitOptions.RemoveEmptyEntries);
			int num = 0;
			for (int i = 0; i < array.Length; i++)
			{
				if (i > 0)
				{
					switch (array[i])
					{
					case "**":
					case "..**":
					case "**..":
						switch (array[i - 1])
						{
						case "**":
						case "..**":
						case "**..":
							num++;
							break;
						}
						break;
					}
				}
				array[i - num] = array[i];
			}
			if (num > 0)
			{
				Array.Resize(ref array, array.Length - num);
			}
			for (int j = 0; j < array.Length; j++)
			{
				array[j] = _GlobPathPartToRegex(array[j]);
			}
			return array;
		}

		private static string _GlobPathPartToRegex(string pattern)
		{
			switch (pattern)
			{
			default:
				if (!pattern.StartsWith("^"))
				{
					return "^" + Regex.Escape(pattern).Replace("\\*", ".*") + "$";
				}
				goto case ".";
			case ".":
			case "..":
			case "**":
			case "..**":
			case "**..":
				return pattern;
			}
		}
	}
	public static class GTTryFindByExactPath
	{
		public static bool WithSiblingIndexAndTypeName<T>(string path, out T out_component) where T : UnityEngine.Component
		{
			out_component = null;
			if (string.IsNullOrEmpty(path))
			{
				return false;
			}
			int num = path.IndexOf("/->/", StringComparison.Ordinal);
			if (num < 0)
			{
				return WithSiblingIndex<T>(path, out out_component);
			}
			string xformPath = path.Substring(0, num);
			string text = path.Substring(num + 4);
			int result = -1;
			int num2 = text.IndexOf('#');
			string text2;
			if (num2 >= 0)
			{
				text2 = text.Substring(0, num2);
				if (!int.TryParse(text.Substring(num2 + 1), out result))
				{
					result = -1;
				}
			}
			else
			{
				text2 = text;
			}
			if (!XformWithSiblingIndex(xformPath, out var finalXform))
			{
				return false;
			}
			Type type = typeof(T);
			if (!string.Equals(type.Name, text2, StringComparison.Ordinal))
			{
				Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
				Type type2 = null;
				Assembly[] array = assemblies;
				for (int i = 0; i < array.Length; i++)
				{
					type2 = array[i].GetType(text2);
					if (type2 != null && typeof(UnityEngine.Component).IsAssignableFrom(type2))
					{
						type = type2;
						break;
					}
				}
				if (type2 == null)
				{
					out_component = finalXform.GetComponent<T>();
					return out_component != null;
				}
			}
			UnityEngine.Component[] components = finalXform.GetComponents(type);
			T val = null;
			if (components.Length != 0)
			{
				if (result < 0)
				{
					val = components[0] as T;
				}
				else
				{
					if (result >= components.Length)
					{
						return false;
					}
					val = components[result] as T;
				}
			}
			out_component = val;
			return out_component != null;
		}

		private static bool WithSiblingIndex<T>(string xformPath, out T component) where T : UnityEngine.Component
		{
			component = null;
			if (XformWithSiblingIndex(xformPath, out var finalXform))
			{
				component = finalXform.GetComponent<T>();
				return component != null;
			}
			return false;
		}

		public static bool XformWithSiblingIndex(string xformPath, out Transform finalXform)
		{
			finalXform = null;
			if (string.IsNullOrEmpty(xformPath))
			{
				return false;
			}
			string[] array = xformPath.Split('/', StringSplitOptions.RemoveEmptyEntries);
			if (array.Length == 0)
			{
				return false;
			}
			Transform transform = null;
			for (int i = 0; i < array.Length; i++)
			{
				string text = array[i];
				int num = text.IndexOf('|');
				if (num < 0)
				{
					return false;
				}
				string s = text.Substring(0, num);
				string b = text.Substring(num + 1);
				if (!int.TryParse(s, out var result))
				{
					return false;
				}
				if (i == 0)
				{
					Transform transform2 = null;
					for (int j = 0; j < SceneManager.sceneCount; j++)
					{
						if (!(transform2 == null))
						{
							break;
						}
						Scene sceneAt = SceneManager.GetSceneAt(j);
						if (!sceneAt.IsValid() || !sceneAt.isLoaded)
						{
							continue;
						}
						GameObject[] rootGameObjects = sceneAt.GetRootGameObjects();
						if (result >= 0 && result < rootGameObjects.Length)
						{
							Transform transform3 = rootGameObjects[result].transform;
							if (string.Equals(transform3.name, b, StringComparison.Ordinal))
							{
								transform2 = transform3;
							}
						}
					}
					if (transform2 == null)
					{
						return false;
					}
					transform = transform2;
				}
				else
				{
					if (result < 0 || result >= transform.childCount)
					{
						return false;
					}
					Transform child = transform.GetChild(result);
					if (!string.Equals(child.name, b, StringComparison.Ordinal))
					{
						return false;
					}
					transform = child;
				}
			}
			finalXform = transform;
			return finalXform != null;
		}
	}
