				}
			}
			if (_events != null)
			{
				_events.Activate.reliable = true;
				_events.Deactivate.reliable = true;
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnSpawnReplicated);
				_events.Deactivate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnTriggerEffectReplicated);
			}
			if (ObjectPools.instance == null || !ObjectPools.instance.initialized)
			{
				return;
			}
			if (surfaceEffectHash != 0)
			{
				_pool = ObjectPools.instance.GetPoolByHash(surfaceEffectHash);
				if (_pool != null)
				{
					foundPool = true;
				}
				else
				{
					GTDev.LogError("CosmeticParticleSurfaceEffect " + base.gameObject.name + " no Object pool found for surface effect prefab. Has it been added to Global Object Pools?");
				}
			}
			spawnCallLimiter.Reset();
			destroyCallLimiter.Reset();
			lastHitTime = float.MinValue;
		}

		private void OnDisable()
		{
			StopParticles();
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnSpawnReplicated);
				_events.Deactivate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnTriggerEffectReplicated);
				_events.Dispose();
				_events = null;
			}
			surfaceEffectNum.Clear();
			foreach (SeedPacketTriggerHandler surfaceEffect in surfaceEffects)
			{
				if (!(surfaceEffect == null))
				{
					surfaceEffect.onTriggerEntered.RemoveListener(OnTriggerEffectLocal);
				}
			}
			surfaceEffects.Clear();
		}

		private void OnDestroy()
		{
			surfaceEffectNum.Clear();
			surfaceEffects.Clear();
		}

		public void StartParticles()
		{
			if (!isSpawning)
			{
				isSpawning = true;
				particleStartedTime = Time.time;
				if (!particles.isPlaying)
				{
					particles.Play();
				}
			}
			if (!TickRunning)
			{
				TickSystem<object>.AddTickCallback(this);
			}
		}

		public void StopParticles()
		{
			if (TickRunning)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
			isSpawning = false;
			particleStartedTime = float.MinValue;
			lastHitTime = float.MinValue;
			if (particles.isPlaying)
			{
				particles.Stop();
			}
		}

		public void Tick()
		{
			if (transferrableObject == null || !transferrableObject.InHand())
			{
				StopParticles();
			}
			else if (isSpawning && stopAfterSeconds > 0f && Time.time >= particleStartedTime + stopAfterSeconds)
			{
				StopParticles();
			}
			else
			{
				if (!isLocal || !isSpawning || !(Time.time > placeEffectCooldown + lastHitTime))
				{
					return;
				}
				int num = Physics.RaycastNonAlloc(rayCastOrigin.position, useWorldDirection ? worldDirection : rayCastOrigin.forward, hits, rayCastDistance, rayCastLayerMask, QueryTriggerInteraction.Ignore);
				if (num <= 0)
				{
					return;
				}
				int num2 = 0;
				float distance = hits[num2].distance;
				for (int i = 1; i < num; i++)
				{
					if (hits[i].distance < distance)
					{
						num2 = i;
						distance = hits[i].distance;
					}
				}
				hitPoint = hits[num2];
				lastHitTime = Time.time;
				Invoke("SpawnEffect", distance * placeEffectDelayMultiplier);
			}
		}

		private void SpawnEffect()
		{
			if (isLocal)
			{
				long num = BitPackUtils.PackWorldPosForNetwork(hitPoint.point);
				long num2 = BitPackUtils.PackWorldPosForNetwork(hitPoint.normal);
				int num3 = currentEffect;
				currentEffect++;
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					_events.Activate.RaiseOthers(num, num2, num3);
				}
				SpawnLocal(hitPoint.point, hitPoint.normal, num3);
			}
		}

		private void OnSpawnReplicated(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (!this || sender != target || owner == null || info.senderID != owner.ActorNumber)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnSpawnReplicated");
			if (!spawnCallLimiter.CheckCallTime(Time.time) || args.Length != 3 || !(args[0] is long) || !(args[1] is long) || !(args[2] is int))
			{
				return;
			}
			UnityEngine.Vector3 v = BitPackUtils.UnpackWorldPosFromNetwork((long)args[0]);
			UnityEngine.Vector3 v2 = BitPackUtils.UnpackWorldPosFromNetwork((long)args[1]);
			if (v.IsValid(10000f) && v2.IsValid(10000f) && !(UnityEngine.Vector3.Distance(rayCastOrigin.position, v) > rayCastDistance + 2f))
			{
				v2.Normalize();
				if (v2 == UnityEngine.Vector3.zero)
				{
					v2 = UnityEngine.Vector3.up;
				}
				int identifier = (int)args[2];
				SpawnLocal(v, v2, identifier);
			}
		}

		private void SpawnLocal(UnityEngine.Vector3 position, UnityEngine.Vector3 up, int identifier)
		{
			if (surfaceEffectHash != 0 && !foundPool)
			{
				_pool = ObjectPools.instance.GetPoolByHash(surfaceEffectHash);
				if (_pool == null)
				{
					return;
				}
				foundPool = true;
			}
			if (!foundPool || _pool.GetInactiveCount() <= 0)
			{
				return;
			}
			ClearOldObjects();
			GameObject obj = _pool.Instantiate();
			obj.transform.position = position;
			obj.transform.up = up;
			if (obj.TryGetComponent<SeedPacketTriggerHandler>(out var component))
			{
				int num = surfaceEffects.IndexOf(component);
				if (num >= 0)
				{
					surfaceEffectNum[num] = identifier;
				}
				else
				{
					surfaceEffectNum.Add(identifier);
					surfaceEffects.Add(component);
				}
				component.onTriggerEntered.AddListener(OnTriggerEffectLocal);
			}
		}

		private void ClearOldObjects()
		{
			for (int num = surfaceEffects.Count - 1; num >= 0; num--)
			{
				if (surfaceEffects[num] == null)
				{
					surfaceEffects.RemoveAt(num);
					surfaceEffectNum.RemoveAt(num);
				}
				else if (!surfaceEffects[num].gameObject.activeSelf)
				{
					surfaceEffects[num].onTriggerEntered.RemoveListener(OnTriggerEffectLocal);
					surfaceEffects.RemoveAt(num);
					surfaceEffectNum.RemoveAt(num);
				}
			}
		}

		private void OnTriggerEffectLocal(SeedPacketTriggerHandler seedPacketTriggerHandlerTriggerHandlerEvent)
		{
			int num = surfaceEffects.IndexOf(seedPacketTriggerHandlerTriggerHandlerEvent);
			if (num >= 0 && num < surfaceEffectNum.Count)
			{
				int num2 = surfaceEffectNum[num];
				if (PhotonNetwork.InRoom && _events != null && _events.Deactivate != null)
				{
					_events.Deactivate.RaiseOthers(num2);
				}
				surfaceEffects.RemoveAt(num);
				surfaceEffectNum.RemoveAt(num);
			}
		}

		private void OnTriggerEffectReplicated(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender != target)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnTriggerEffectReplicated");
			if (!destroyCallLimiter.CheckCallTime(Time.time) || args.Length != 1 || !(args[0] is int))
			{
				return;
			}
			ClearOldObjects();
			int item = (int)args[0];
			int num = surfaceEffectNum.IndexOf(item);
			if (num >= 0 && num < surfaceEffects.Count)
			{
				SeedPacketTriggerHandler seedPacketTriggerHandler = surfaceEffects[num];
				if (seedPacketTriggerHandler != null)
				{
					seedPacketTriggerHandler.ToggleEffects();
					seedPacketTriggerHandler.onTriggerEntered.RemoveListener(OnTriggerEffectLocal);
				}
				surfaceEffects.RemoveAt(num);
				surfaceEffectNum.RemoveAt(num);
			}
		}
	}
	public class CosmeticFlickReactor : MonoBehaviour
	{
		private enum AxisMode
		{
			X,
			Y,
			Z,
			CustomForward
		}

		[Header("Axis")]
		[Tooltip("Which single axis/direction to use for flick detection.\n- X/Y/Z use the axes defined by the Space settings below (Local vs World).\n- CustomForward uses axisReference.forward (ignores Space).")]
		[SerializeField]
		private AxisMode axisMode = AxisMode.Z;

		[Tooltip("Used only when AxisMode = CustomForward. The forward/back of this transform defines the direction.")]
		[SerializeField]
		private Transform axisReference;

		[Header("Space")]
		[Tooltip("If enabled, X/Y/Z use world axes, otherwise local axes.\nUse Local for movement relative to the object's facing.\nUse World for absolute directions independent of rotation.")]
		[SerializeField]
		private bool useWorldAxes;

		[Tooltip("Optional transform to define a custom world frame for X/Y/Z.\nIf assigned and Space is World, this transform's Right/Up/Forward act as the world axes.\nIf not assigned, Unity's global axes are used.")]
		[SerializeField]
		private Transform worldSpace;

		[Header("Velocity Source")]
		[Tooltip("Primary velocity tracker.")]
		[SerializeField]
		private SimpleSpeedTracker speedTracker;

		[Tooltip("Fallback velocity source if speedTracker is missing.")]
		[SerializeField]
		private Rigidbody rb;

		[Header("Thresholds")]
		[Tooltip("Minimum absolute signed speed along the chosen axis required to consider a object movement (m/s).")]
		[SerializeField]
		private float minSpeedThreshold = 2f;

		[Tooltip("Optional upper bound for mapping flick strength to 0-1.\nSet <= 0 to disable onFlickStrength.")]
		[SerializeField]
		private float maxSpeedThreshold;

		[Tooltip("How much back-and-forth reversal is required to register a flick.\nExample: 2.5 means => +1.3 then -1.2 within the window (|1.3| + |1.2| = 2.5).")]
		[SerializeField]
		private float directionChangeRequired = 2f;

		[Header("Timing")]
		[Tooltip("Max time allowed between the initial peak and its reversal (seconds).")]
		[SerializeField]
		private float flickWindowSeconds = 0.2f;

		[Tooltip("Buffer time after a successful flick during which no new flicks are allowed (seconds).")]
		[SerializeField]
		private float retriggerBufferSeconds = 0.15f;

		[Header("Events")]
		public UnityEvent OnFlickShared;

		public UnityEvent OnFlickLocal;

		public UnityEvent<float> onFlickStrength;

		private UnityEngine.Vector3 lastPosition;

		private bool hasLastPosition;

		private float lastPeakSpeed;

		private float lastPeakTime = -999f;

		private int lastPeakSign;

		private float blockUntilTime;

		private VRRig rig;

		private bool isLocal;

		private void Reset()
		{
			if (speedTracker == null)
			{
				speedTracker = GetComponent<SimpleSpeedTracker>();
			}
			if (rb == null)
			{
				rb = GetComponent<Rigidbody>();
			}
		}

		private void Awake()
		{
			rig = GetComponentInParent<VRRig>();
			if (rig == null && base.gameObject.GetComponentInParent<GTPlayer>() != null)
			{
				rig = GorillaTagger.Instance.offlineVRRig;
			}
			isLocal = rig != null && rig.isLocal;
			ResetState();
			blockUntilTime = 0f;
			hasLastPosition = false;
		}

		private void Update()
		{
			UnityEngine.Vector3 axis = ResolveAxisDirection();
			if (axis.sqrMagnitude < 0.5f)
			{
				return;
			}
			float signedSpeedAlong = GetSignedSpeedAlong(axis);
			if (Mathf.Abs(signedSpeedAlong) >= minSpeedThreshold)
			{
				int num = ((signedSpeedAlong > 0f) ? 1 : (-1));
				if (num == lastPeakSign && !(Mathf.Abs(signedSpeedAlong) > Mathf.Abs(lastPeakSpeed)))
				{
					return;
				}
				if (lastPeakSign != 0 && num == -lastPeakSign)
				{
					float num2 = Time.time - lastPeakTime;
					float num3 = Mathf.Abs(lastPeakSpeed) + Mathf.Abs(signedSpeedAlong);
					bool flag = num2 <= flickWindowSeconds;
					bool flag2 = num3 >= directionChangeRequired;
					bool flag3 = Time.time >= blockUntilTime;
					if (flag && flag2 && flag3)
					{
						FireEvents(Mathf.Abs(signedSpeedAlong));
						blockUntilTime = Time.time + retriggerBufferSeconds;
						ResetState();
					}
					else
					{
						lastPeakSign = num;
						lastPeakSpeed = signedSpeedAlong;
						lastPeakTime = Time.time;
					}
				}
				else
				{
					lastPeakSign = num;
					lastPeakSpeed = signedSpeedAlong;
					lastPeakTime = Time.time;
				}
			}
			else if (Time.time - lastPeakTime > flickWindowSeconds)
			{
				ResetState();
			}
		}

		private UnityEngine.Vector3 ResolveAxisDirection()
		{
			switch (axisMode)
			{
			case AxisMode.X:
				if (!useWorldAxes)
				{
					return base.transform.right;
				}
				if (!(worldSpace != null))
				{
					return UnityEngine.Vector3.right;
				}
				return worldSpace.right;
			case AxisMode.Y:
				if (!useWorldAxes)
				{
					return base.transform.up;
				}
				if (!(worldSpace != null))
				{
					return UnityEngine.Vector3.up;
				}
				return worldSpace.up;
			case AxisMode.Z:
				if (!useWorldAxes)
				{
					return base.transform.forward;
				}
				if (!(worldSpace != null))
				{
					return UnityEngine.Vector3.forward;
				}
				return worldSpace.forward;
			case AxisMode.CustomForward:
				if (!(axisReference != null))
				{
					return UnityEngine.Vector3.zero;
				}
				return axisReference.forward;
			default:
				return UnityEngine.Vector3.zero;
			}
		}

		private float GetSignedSpeedAlong(UnityEngine.Vector3 axis)
		{
			UnityEngine.Vector3 lhs;
			if (speedTracker != null)
			{
				lhs = speedTracker.GetWorldVelocity();
			}
			else if (rb != null)
			{
				lhs = rb.linearVelocity;
			}
			else
			{
				if (!hasLastPosition)
				{
					lastPosition = base.transform.position;
					hasLastPosition = true;
					return 0f;
				}
				UnityEngine.Vector3 vector = base.transform.position - lastPosition;
				float num = ((Time.deltaTime > Mathf.Epsilon) ? (1f / Time.deltaTime) : 0f);
				lhs = vector * num;
				lastPosition = base.transform.position;
			}
			return UnityEngine.Vector3.Dot(lhs, axis.normalized);
		}

		private void FireEvents(float currentAbsSpeed)
		{
			if (isLocal)
			{
				OnFlickLocal?.Invoke();
			}
			OnFlickShared?.Invoke();
			if (maxSpeedThreshold > 0f)
			{
				float value = Mathf.InverseLerp(minSpeedThreshold, maxSpeedThreshold, currentAbsSpeed);
				onFlickStrength?.Invoke(Mathf.Clamp01(value));
			}
		}

		private void ResetState()
		{
			lastPeakSign = 0;
			lastPeakSpeed = 0f;
			lastPeakTime = -9999f;
		}
	}
	public class CosmeticsLocalHandReactor : MonoBehaviour
	{
		[SerializeField]
		private float hapticStrength = 0.2f;

		[SerializeField]
		private float hapticDuration = 0.2f;

		[Tooltip("The distance threshold (in meters) for triggering the interaction.\nIf the hand enters this range, onTrigger is fired.")]
		public float proximityThreshold = 0.15f;

		[Tooltip("Minimum time (in seconds) between consecutive triggers.\n")]
		[SerializeField]
		private float cooldownTime = 0.5f;

		public UnityEvent<bool> onTrigger;

		private VRRig ownerRig;

		private bool ownerIsLocal;

		private float lastTriggerTime = float.MinValue;

		private readonly Collider[] colliders = new Collider[1];

		private LayerMask handLayer = 1024;

		protected void Awake()
		{
			ownerRig = GetComponentInParent<VRRig>();
			if (ownerRig == null)
			{
				GorillaTagger componentInParent = GetComponentInParent<GorillaTagger>();
				if (componentInParent != null)
				{
					ownerRig = componentInParent.offlineVRRig;
					ownerIsLocal = ownerRig != null;
				}
			}
			if (ownerRig == null)
			{
				UnityEngine.Debug.LogError("TriggerToggler: Disabling cannot find VRRig.");
				base.enabled = false;
			}
		}

		protected void LateUpdate()
		{
			if (!ownerIsLocal || Time.time < lastTriggerTime + cooldownTime)
			{
				return;
			}
			Transform transform = base.transform;
			if (Physics.OverlapSphereNonAlloc(base.transform.position, proximityThreshold * transform.lossyScale.x, colliders, handLayer) > 0)
			{
				GorillaTriggerColliderHandIndicator component = colliders[0].GetComponent<GorillaTriggerColliderHandIndicator>();
				if (component != null)
				{
					GorillaTagger.Instance.StartVibration(component.isLeftHand, hapticStrength, hapticDuration);
					onTrigger?.Invoke(component.isLeftHand);
					lastTriggerTime = Time.time;
				}
			}
		}
	}
	public class CountDrivenEvents : MonoBehaviour
	{
		[Serializable]
		public class CountTrigger
		{
			[Tooltip("The count value that triggers this event")]
			public int triggerCount;

			[Tooltip("Events to invoke when count reaches this value")]
			public UnityEvent onCountReached;

			public UnityEvent onCountReachedShared;

			[Tooltip("Should this trigger fire every time the count passes through this value, or only once?")]
			public bool triggerOnce;

			[NonSerialized]
			public bool hasTriggered;
		}

		[Header("Network")]
		[SerializeField]
		private bool syncAllEvents;

		[Header("General Settings")]
		[Tooltip("If true, triggers will be evaluated once on enable using the initial count.")]
		[SerializeField]
		private bool evaluateOnEnable;

		[Tooltip("If enabled, the counter value will loop between 0 and the highest triggerCount.")]
		[SerializeField]
		private bool wrapCount;

		[Header("Count Triggers")]
		[SerializeField]
		private List<CountTrigger> triggers = new List<CountTrigger>();

		[Header("Local and Networked Events")]
		public UnityEvent<int> onCountChanged;

		public UnityEvent<int> onCountChangedShared;

		public UnityEvent<int> onCountIncreased;

		public UnityEvent<int> onCountIncreasedShared;

		public UnityEvent<int> onCountDecreased;

		public UnityEvent<int> onCountDecreasedShared;

		public UnityEvent onCountResetToZero;

		public UnityEvent onCountResetToZeroShared;

		public UnityEvent onReachedMaxTrigger;

		public UnityEvent onReachedMaxTriggerShared;

		[Header("Debug - Counter Settings")]
		[SerializeField]
		private int currentCount;

		private RubberDuckEvents _events;

		private VRRig myRig;

		private CallLimiter callLimiter = new CallLimiter(10, 1f);

		public int CurrentCount => currentCount;

		private void OnEnable()
		{
			if (myRig == null)
			{
				myRig = GetComponentInParent<VRRig>();
			}
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			}
			NetPlayer netPlayer = ((myRig != null) ? (myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : NetworkSystem.Instance.LocalPlayer);
			if (netPlayer != null)
			{
				_events.Init(netPlayer);
			}
			if (_events != null)
			{
				_events.Activate.reliable = true;
				_events.Deactivate.reliable = true;
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnCountChanged_SharedEvent);
				_events.Deactivate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnCountReached_SharedEvent);
			}
			if (evaluateOnEnable)
			{
				CheckTriggers(currentCount, currentCount);
			}
		}

		private void OnDisable()
		{
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnCountChanged_SharedEvent);
				_events.Deactivate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnCountReached_SharedEvent);
				_events.Dispose();
				_events = null;
			}
		}

		private void OnValidate()
		{
			if (triggers == null)
			{
				return;
			}
			for (int i = 0; i < triggers.Count; i++)
			{
				if (triggers[i].triggerCount < 0)
				{
					triggers[i].triggerCount = 0;
				}
			}
		}

		public void Increment()
		{
			SetCount(currentCount + 1);
		}

		public void Decrement()
		{
			SetCount(currentCount - 1);
		}

		public void SetCount(int newCount)
		{
			if (myRig != null && !myRig.isLocal)
			{
				return;
			}
			int num = currentCount;
			if (wrapCount)
			{
				int highestTriggerCount = GetHighestTriggerCount();
				if (highestTriggerCount > 0)
				{
					int num2 = highestTriggerCount + 1;
					newCount = (newCount % num2 + num2) % num2;
				}
				else if (newCount < 0)
				{
					newCount = 0;
				}
			}
			else if (newCount < 0)
			{
				newCount = 0;
			}
			if (newCount != num)
			{
				bool flag = false;
				currentCount = newCount;
				onCountChanged?.Invoke(currentCount);
				onCountChangedShared?.Invoke(currentCount);
				if (currentCount > num)
				{
					onCountIncreased?.Invoke(currentCount);
					onCountIncreasedShared?.Invoke(currentCount);
					flag = true;
				}
				else if (currentCount < num)
				{
					onCountDecreased?.Invoke(currentCount);
					onCountDecreasedShared?.Invoke(currentCount);
				}
				CheckTriggers(num, currentCount);
				if (currentCount == 0)
				{
					onCountResetToZero?.Invoke();
					onCountResetToZeroShared?.Invoke();
				}
				int highestTriggerCount2 = GetHighestTriggerCount();
				if (highestTriggerCount2 > 0 && currentCount == highestTriggerCount2)
				{
					onReachedMaxTrigger?.Invoke();
					onReachedMaxTriggerShared?.Invoke();
				}
				if (syncAllEvents && PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					object[] args = new object[2] { flag, currentCount };
					_events.Activate.RaiseOthers(args);
				}
			}
		}

		[Tooltip("Resets all 'triggerOnce' flags, allowing one-time triggers to fire again.\n\nUse this when restarting a sequence, resetting an object,\nor testing trigger behavior multiple times in play mode.")]
		public void ResetTriggers()
		{
			for (int i = 0; i < triggers.Count; i++)
			{
				triggers[i].hasTriggered = false;
			}
		}

		private int GetHighestTriggerCount()
		{
			int num = 0;
			for (int i = 0; i < triggers.Count; i++)
			{
				if (triggers[i].triggerCount > num)
				{
					num = triggers[i].triggerCount;
				}
			}
			return num;
		}

		private void CheckTriggers(int oldCount, int newCount)
		{
			if (myRig != null && !myRig.isLocal)
			{
				return;
			}
			for (int i = 0; i < triggers.Count; i++)
			{
				CountTrigger countTrigger = triggers[i];
				if (countTrigger.triggerOnce && countTrigger.hasTriggered)
				{
					continue;
				}
				bool flag = false;
				if (wrapCount)
				{
					if (newCount == countTrigger.triggerCount)
					{
						flag = true;
					}
				}
				else if (oldCount < countTrigger.triggerCount && newCount >= countTrigger.triggerCount)
				{
					flag = true;
				}
				else if (oldCount > countTrigger.triggerCount && newCount <= countTrigger.triggerCount)
				{
					flag = true;
				}
				else if (oldCount == newCount && newCount == countTrigger.triggerCount)
				{
					flag = true;
				}
				if (flag)
				{
					countTrigger.onCountReached?.Invoke();
					countTrigger.onCountReachedShared?.Invoke();
					if (syncAllEvents && PhotonNetwork.InRoom && _events != null && _events.Deactivate != null)
					{
						object[] args = new object[1] { i };
						_events.Deactivate.RaiseOthers(args);
					}
					if (countTrigger.triggerOnce)
					{
						countTrigger.hasTriggered = true;
					}
				}
			}
		}

		private void OnCountChanged_SharedEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender != target || info.senderID != myRig.creator.ActorNumber)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnCountChanged_SharedEvent");
			if (callLimiter.CheckCallTime(Time.time) && args.Length == 2 && args[0] is bool flag && args[1] is int num)
			{
				onCountChangedShared?.Invoke(num);
				if (flag)
				{
					onCountIncreasedShared?.Invoke(num);
				}
				else
				{
					onCountDecreasedShared?.Invoke(num);
				}
				int highestTriggerCount = GetHighestTriggerCount();
				if (num == 0)
				{
					onCountResetToZeroShared?.Invoke();
				}
				else if (highestTriggerCount > 0 && num == highestTriggerCount)
				{
					onReachedMaxTriggerShared?.Invoke();
				}
			}
		}

		private void OnCountReached_SharedEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender == target && info.senderID == myRig.creator.ActorNumber)
			{
				MonkeAgent.IncrementRPCCall(info, "OnCountReached_SharedEvent");
				if (callLimiter.CheckCallTime(Time.time) && args.Length == 1 && args[0] is int num && num >= 0 && num < triggers.Count)
				{
					triggers[num].onCountReachedShared?.Invoke();
				}
			}
		}
	}
	public class CreatorCodeTerminal : MonoBehaviour, ICreatorCodeProvider, IBuildValidation
	{
		private string termId;

		[SerializeField]
		private TMP_Text creatorCodeField;

		[SerializeField]
		private TMP_Text creatorCodeTitle;

		[SerializeField]
		private NexusGroupId[] nexusGroups;

		public NexusGroupId[] NexusGroups => nexusGroups;

		public string TerminalId => termId;

		GameObject ICreatorCodeProvider.GameObject => base.gameObject;

		public void Awake()
		{
			termId = string.Empty;
			for (int i = 0; i < nexusGroups.Length; i++)
			{
				termId += nexusGroups[i].Code;
			}
			HookupToCreatorCodes();
		}

		private void OnDestroy()
		{
			UnhookFromCreatorCodes();
		}

		public void HookupToCreatorCodes()
		{
			CreatorCodes.InitializedEvent += OnCreatorCodesInitialized;
			CreatorCodes.OnCreatorCodeChangedEvent += OnCreatorCodeChanged;
			CreatorCodes.OnCreatorCodeFailureEvent += OnCreatorCodeFailure;
			if (CreatorCodes.Intialized)
			{
				OnCreatorCodesInitialized();
			}
			CosmeticsController.PushTerminalMessage = (Action<string, string>)Delegate.Combine(CosmeticsController.PushTerminalMessage, new Action<string, string>(OnTerminalMessage));
		}

		private async void OnTerminalMessage(string termId, string msg)
		{
			if (!(termId != this.termId))
			{
				creatorCodeTitle.text = msg;
				while (UnityEngine.Application.isPlaying && (VRRig.LocalRig.transform.position - base.transform.position).sqrMagnitude < 4f)
				{
					await Task.Yield();
				}
				creatorCodeTitle.text = "CREATOR CODE: VALID";
			}
		}

		public void UnhookFromCreatorCodes()
		{
			CreatorCodes.InitializedEvent -= OnCreatorCodesInitialized;
			CreatorCodes.OnCreatorCodeChangedEvent -= OnCreatorCodeChanged;
			CreatorCodes.OnCreatorCodeFailureEvent -= OnCreatorCodeFailure;
			CosmeticsController.PushTerminalMessage = (Action<string, string>)Delegate.Remove(CosmeticsController.PushTerminalMessage, new Action<string, string>(OnTerminalMessage));
		}

		private void OnCreatorCodesInitialized()
		{
			OnCreatorCodeChanged(termId);
		}

		public void OnCreatorCodeChanged(string id)
		{
			if (!(id != termId))
			{
				creatorCodeField.text = CreatorCodes.getCurrentCreatorCode(termId);
				string text = "CREATOR CODE:";
				switch (CreatorCodes.getCurrentCreatorCodeStatus(termId))
				{
				case CreatorCodes.CreatorCodeStatus.Valid:
					text += " VALID";
					break;
				case CreatorCodes.CreatorCodeStatus.Validating:
					text += " VALIDATING";
					break;
				}
				creatorCodeTitle.text = text;
			}
		}

		public void CreatorCodeInput(string character)
		{
			CreatorCodes.AppendKey(termId, character);
		}

		public void CreatorCodeDelete()
		{
			CreatorCodes.DeleteCharacter(termId);
		}

		public void OnCreatorCodeValid(string id, string s, NexusGroupId ngid)
		{
			if (!(id != termId))
			{
				creatorCodeTitle.text = "CREATOR CODE: VALID";
			}
		}

		public void OnCreatorCodeValidating(string id)
		{
			if (!(id != termId))
			{
				creatorCodeTitle.text = "CREATOR CODE: VALIDATING";
			}
		}

		public void CreatorCodeInvalid(string id)
		{
			if (!(id != termId))
			{
				creatorCodeTitle.text = "CREATOR CODE: INVALID";
			}
		}

		public void OnCreatorCodeFailure(string id)
		{
			if (!(id != termId))
			{
				creatorCodeTitle.text = "CREATOR CODE: INVALID";
			}
		}

		bool IBuildValidation.BuildValidationCheck()
		{
			if (nexusGroups.Length == 0)
			{
				UnityEngine.Debug.LogError("You have to set at least one nexus group in " + base.name + " or things will not work!");
				return false;
			}
			return true;
		}

		public void GetCreatorCode(out string code, out NexusGroupId[] groups)
		{
			code = CreatorCodes.getCurrentCreatorCode(termId);
			groups = nexusGroups;
		}
	}
	public interface ICreatorCodeProvider
	{
		GameObject GameObject { get; }

		string TerminalId { get; }

		void GetCreatorCode(out string code, out NexusGroupId[] groups);
	}
}
