		private static bool _TryAddComponentsToGroup<T>(StaticLodGroup lodGroup, ref GroupInfo ref_groupInfo, ref T[] ref_components, Predicate<T> includeIf, _GetBoundsDelegate<T> getBounds) where T : UnityEngine.Component
		{
			List<T> componentsInChildrenUntil = lodGroup.GetComponentsInChildrenUntil<T, StaticLodGroup, StaticLodGroupExcluder>(includeInactive: true, stopAtRoot: false);
			for (int num = componentsInChildrenUntil.Count - 1; num >= 0; num--)
			{
				if (!includeIf(componentsInChildrenUntil[num]))
				{
					componentsInChildrenUntil.RemoveAt(num);
				}
			}
			if (componentsInChildrenUntil.Count == 0)
			{
				if (ref_components == null)
				{
					ref_components = Array.Empty<T>();
				}
				return false;
			}
			T[] obj = ref_components;
			int num2 = ((obj != null) ? obj.Length : 0);
			if (num2 == 0)
			{
				ref_components = componentsInChildrenUntil.ToArray();
			}
			else
			{
				Array.Resize(ref ref_components, num2 + componentsInChildrenUntil.Count);
				for (int i = num2; i < ref_components.Length; i++)
				{
					ref_components[i] = componentsInChildrenUntil[i - num2];
				}
			}
			if (Mathf.Approximately(ref_groupInfo.radiusSq, 0f))
			{
				ref_groupInfo.bounds = getBounds(ref_components[0]);
			}
			for (int j = num2; j < ref_components.Length; j++)
			{
				ref_groupInfo.bounds.Encapsulate(getBounds(ref_components[j]));
			}
			ref_groupInfo.center = ref_groupInfo.bounds.center;
			ref_groupInfo.radiusSq = ref_groupInfo.bounds.extents.sqrMagnitude;
			return true;
		}

		[Conditional("UNITY_EDITOR")]
		private static void _EdAddPathsToGroup<T>(T[] components, ref string[] ref_edDebugPaths) where T : UnityEngine.Component
		{
		}

		public static void SetEnabled(int index, bool enable)
		{
			if (!ApplicationQuittingState.IsQuitting && groupInfos != null && index >= 0 && index < groupInfos.Count)
			{
				GroupInfo value = groupInfos[index];
				value.componentEnabled = enable;
				groupInfos[index] = value;
			}
		}

		public void SliceUpdate()
		{
			if (!hasMainCamera)
			{
				return;
			}
			UnityEngine.Vector3 position = mainCamera.transform.position;
			for (int i = 0; i < groupInfos.Count; i++)
			{
				GroupInfo value = groupInfos[i];
				if (!value.isLoaded || !value.componentEnabled)
				{
					continue;
				}
				float num = Mathf.Max(0f, (value.center - position).sqrMagnitude - value.radiusSq);
				float num2 = (value.uiEnabled ? 0.010000001f : 0f);
				bool flag = num < value.uiEnableDistanceSq + num2;
				if (flag != value.uiEnabled)
				{
					for (int j = 0; j < value.uiGraphics.Length; j++)
					{
						Graphic graphic = value.uiGraphics[j];
						if (!(graphic == null))
						{
							graphic.enabled = flag;
						}
					}
					for (int k = 0; k < value.renderers.Length; k++)
					{
						Renderer renderer = value.renderers[k];
						if (!(renderer == null))
						{
							renderer.enabled = flag;
						}
					}
				}
				value.uiEnabled = flag;
				num2 = (value.collidersEnabled ? 0.010000001f : 0f);
				bool flag2 = num < value.collisionEnableDistanceSq + num2;
				if (flag2 != value.collidersEnabled)
				{
					for (int l = 0; l < value.interactableColliders.Length; l++)
					{
						if (!(value.interactableColliders[l] == null))
						{
							value.interactableColliders[l].enabled = flag2;
						}
					}
				}
				value.collidersEnabled = flag2;
				groupInfos[i] = value;
			}
		}
	}
	[ExecuteAlways]
	public class TextureTransitioner : MonoBehaviour, IResettableItem
	{
		public enum DirectionRetentionMode
		{
			None,
			IncreaseOnly,
			DecreaseOnly
		}

		public bool editorPreview;

		[Tooltip("The component that will drive the texture transitions.")]
		public MonoBehaviour dynamicFloatComponent;

		[Tooltip("Set these values so that after remap 0 is the first texture in the textures list and 1 is the last.")]
		public GorillaMath.RemapFloatInfo remapInfo;

		public DirectionRetentionMode directionRetentionMode;

		public string texTransitionShaderParamName = "_TexTransition";

		public string tex1ShaderParamName = "_MainTex";

		public string tex2ShaderParamName = "_Tex2";

		public Texture[] textures;

		public Renderer[] renderers;

		[NonSerialized]
		public IDynamicFloat iDynamicFloat;

		[NonSerialized]
		public int texTransitionShaderParam;

		[NonSerialized]
		public int tex1ShaderParam;

		[NonSerialized]
		public int tex2ShaderParam;

		[NonSerialized]
		[DebugReadout]
		public float normalizedValue;

		[NonSerialized]
		[DebugReadout]
		public int transitionPercent;

		[NonSerialized]
		[DebugReadout]
		public int tex1Index;

		[NonSerialized]
		[DebugReadout]
		public int tex2Index;

		protected void Awake()
		{
			if (UnityEngine.Application.isPlaying || editorPreview)
			{
				TextureTransitionerManager.EnsureInstanceIsAvailable();
			}
			RefreshShaderParams();
			iDynamicFloat = (IDynamicFloat)dynamicFloatComponent;
			ResetToDefaultState();
		}

		protected void OnEnable()
		{
			TextureTransitionerManager.Register(this);
			if (UnityEngine.Application.isPlaying && !remapInfo.IsValid())
			{
				UnityEngine.Debug.LogError("Bad min/max values for remapRanges: " + this.GetComponentPath(), this);
				base.enabled = false;
			}
			if (UnityEngine.Application.isPlaying && textures.Length == 0)
			{
				UnityEngine.Debug.LogError("Textures array is empty: " + this.GetComponentPath(), this);
				base.enabled = false;
			}
			if (UnityEngine.Application.isPlaying && iDynamicFloat == null)
			{
				if (dynamicFloatComponent == null)
				{
					UnityEngine.Debug.LogError("dynamicFloatComponent cannot be null: " + this.GetComponentPath(), this);
				}
				iDynamicFloat = (IDynamicFloat)dynamicFloatComponent;
				if (iDynamicFloat == null)
				{
					UnityEngine.Debug.LogError("Component assigned to dynamicFloatComponent does not implement IDynamicFloat: " + this.GetComponentPath(), this);
					base.enabled = false;
				}
			}
		}

		protected void OnDisable()
		{
			TextureTransitionerManager.Unregister(this);
		}

		private void RefreshShaderParams()
		{
			texTransitionShaderParam = Shader.PropertyToID(texTransitionShaderParamName);
			tex1ShaderParam = Shader.PropertyToID(tex1ShaderParamName);
			tex2ShaderParam = Shader.PropertyToID(tex2ShaderParamName);
		}

		public void ResetToDefaultState()
		{
			normalizedValue = 0f;
			transitionPercent = 0;
			tex1Index = 0;
			tex2Index = 0;
		}
	}
	[ExecuteAlways]
	public class TextureTransitionerManager : MonoBehaviour
	{
		public static readonly List<TextureTransitioner> components = new List<TextureTransitioner>(256);

		private MaterialPropertyBlock matPropBlock;

		public static TextureTransitionerManager instance { get; private set; }

		protected void Awake()
		{
			if (instance != null)
			{
				UnityEngine.Object.Destroy(base.gameObject);
				return;
			}
			instance = this;
			if (UnityEngine.Application.isPlaying)
			{
				UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
			}
			matPropBlock = new MaterialPropertyBlock();
		}

		protected void LateUpdate()
		{
			foreach (TextureTransitioner component in components)
			{
				int num = component.textures.Length;
				float num2 = Mathf.Clamp01(component.remapInfo.Remap(component.iDynamicFloat.floatValue));
				switch (component.directionRetentionMode)
				{
				case TextureTransitioner.DirectionRetentionMode.IncreaseOnly:
					num2 = Mathf.Max(num2, component.normalizedValue);
					break;
				case TextureTransitioner.DirectionRetentionMode.DecreaseOnly:
					num2 = Mathf.Min(num2, component.normalizedValue);
					break;
				}
				float num3 = num2 * (float)(num - 1);
				float num4 = num3 % 1f;
				int num5 = (int)(num4 * 1000f);
				int num6 = (int)num3;
				int num7 = Mathf.Min(num - 1, num6 + 1);
				if (num5 != component.transitionPercent || num6 != component.tex1Index || num7 != component.tex2Index)
				{
					matPropBlock.SetFloat(component.texTransitionShaderParam, num4);
					matPropBlock.SetTexture(component.tex1ShaderParam, component.textures[num6]);
					matPropBlock.SetTexture(component.tex2ShaderParam, component.textures[num7]);
					Renderer[] renderers = component.renderers;
					for (int i = 0; i < renderers.Length; i++)
					{
						renderers[i].SetPropertyBlock(matPropBlock);
					}
					component.normalizedValue = num2;
					component.transitionPercent = num5;
					component.tex1Index = num6;
					component.tex2Index = num7;
				}
			}
		}

		public static void EnsureInstanceIsAvailable()
		{
			if (!(instance != null))
			{
				GameObject obj = new GameObject();
				instance = obj.AddComponent<TextureTransitionerManager>();
				obj.name = "TextureTransitionerManager (Singleton)";
			}
		}

		public static void Register(TextureTransitioner component)
		{
			components.Add(component);
		}

		public static void Unregister(TextureTransitioner component)
		{
			components.Remove(component);
		}
	}
