	[Serializable]
	public class CoolDownHelper
	{
		public float coolDown;

		[NonSerialized]
		public float checkTime;

		public CoolDownHelper()
		{
			coolDown = 1f;
			checkTime = 0f;
		}

		public CoolDownHelper(float cd)
		{
			coolDown = cd;
			checkTime = 0f;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool CheckCooldown()
		{
			float unscaledTime = Time.unscaledTime;
			if (unscaledTime < checkTime)
			{
				return false;
			}
			OnCheckPass();
			checkTime = unscaledTime + coolDown;
			return true;
		}

		public virtual void Start()
		{
			checkTime = Time.unscaledTime + coolDown;
		}

		public virtual void Stop()
		{
			checkTime = float.MaxValue;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public virtual void OnCheckPass()
		{
		}
	}
	public class RigidbodyHighlighter : MonoBehaviour
	{
		[CanBeNull]
		public static RigidbodyHighlighter Instance;

		[SerializeField]
		private float _inGameDuration = 10f;

		[SerializeField]
		private LineRenderer _lineRenderer;

		[SerializeField]
		private float _lineWidth = 0.01f;

		[SerializeField]
		private UnityEngine.Vector3 _tracerOffset = 0.5f * UnityEngine.Vector3.down;

		private readonly List<Rigidbody> _rigidbodies = new List<Rigidbody>();

		private string ButtonText
		{
			get
			{
				if (!Active)
				{
					return "Highlight Rigidbodies";
				}
				return "Unhighlight Rigidbodies";
			}
		}

		public bool Active { get; set; }

		private void Awake()
		{
			UnityEngine.Object.Destroy(base.gameObject);
			if (Instance != null && Instance != this)
			{
				UnityEngine.Object.Destroy(base.gameObject);
			}
			Instance = this;
			_lineRenderer.startWidth = _lineWidth;
			_lineRenderer.endWidth = _lineWidth;
		}

		private void Update()
		{
			if (!Active)
			{
				_lineRenderer.positionCount = 0;
				return;
			}
			_rigidbodies.Clear();
			_rigidbodies.AddAll(GetAwakeRigidbodies());
			DrawTracers();
			foreach (Rigidbody rigidbody in _rigidbodies)
			{
				DrawBox(rigidbody.transform, Color.red, 0.1f);
			}
		}

		private static List<Rigidbody> GetAwakeRigidbodies()
		{
			List<Rigidbody> list = new List<Rigidbody>();
			UnityEngine.Object[] array = UnityEngine.Object.FindObjectsByType(typeof(Rigidbody), FindObjectsSortMode.None);
			for (int i = 0; i < array.Length; i++)
			{
				if (!(array[i] is Rigidbody rigidbody))
				{
					throw new Exception("Non-rigidbody found by FindObjectsByType.");
				}
				if (!rigidbody.IsSleeping())
				{
					list.Add(rigidbody);
				}
			}
			return list;
		}

		private void HighlightActiveRigidbodies()
		{
			Active = !Active;
		}

		private void GetRigidbodyNames()
		{
			List<Rigidbody> list = ((_rigidbodies.Count > 0) ? _rigidbodies : GetAwakeRigidbodies());
			for (int i = 0; i < list.Count; i++)
			{
				UnityEngine.Debug.Log($"Rigidbody {i} of {list.Count}: {list[i].name}");
			}
		}

		private void OnDrawGizmos()
		{
			if (!Active)
			{
				return;
			}
			Gizmos.color = Color.red;
			foreach (Rigidbody rigidbody in _rigidbodies)
			{
				Gizmos.DrawWireCube(rigidbody.transform.position, UnityEngine.Vector3.one);
			}
		}

		private static void DrawBox(Transform tx, Color color, float duration)
		{
			UnityEngine.Matrix4x4 matrix4x = default(UnityEngine.Matrix4x4);
			matrix4x.SetTRS(tx.position, tx.rotation, tx.lossyScale);
			UnityEngine.Vector3 vector = matrix4x.MultiplyPoint(new UnityEngine.Vector3(-0.5f, -0.5f, -0.5f));
			UnityEngine.Vector3 vector2 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(-0.5f, -0.5f, 0.5f));
			UnityEngine.Vector3 vector3 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(-0.5f, 0.5f, -0.5f));
			UnityEngine.Vector3 vector4 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(-0.5f, 0.5f, 0.5f));
			UnityEngine.Vector3 vector5 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(0.5f, -0.5f, -0.5f));
			UnityEngine.Vector3 vector6 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(0.5f, -0.5f, 0.5f));
			UnityEngine.Vector3 vector7 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(0.5f, 0.5f, -0.5f));
			UnityEngine.Vector3 vector8 = matrix4x.MultiplyPoint(new UnityEngine.Vector3(0.5f, 0.5f, 0.5f));
			UnityEngine.Debug.DrawLine(vector, vector2, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector2, vector4, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector4, vector3, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector3, vector, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector8, vector7, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector7, vector5, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector5, vector6, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector6, vector8, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector, vector5, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector2, vector6, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector3, vector7, color, duration, depthTest: false);
			UnityEngine.Debug.DrawLine(vector4, vector8, color, duration, depthTest: false);
		}

		private void DrawTracers()
		{
			UnityEngine.Vector3[] array = new UnityEngine.Vector3[_rigidbodies.Count * 2 + 1];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = ((i % 2 == 0) ? (Camera.main.transform.position + _tracerOffset) : _rigidbodies[i / 2].transform.position);
			}
			_lineRenderer.positionCount = array.Length;
			_lineRenderer.SetPositions(array);
		}
	}
