	{
		protected ListProcessorAbstract()
		{
			m_itemProcessorDelegate = ProcessItem;
		}

		protected ListProcessorAbstract(int capacity)
			: base(capacity, (InAction<T>)null)
		{
			m_itemProcessorDelegate = ProcessItem;
		}

		protected abstract void ProcessItem(in T item);
	}
	public interface ObjectPoolEvents
	{
		void OnTaken();

		void OnReturned();
	}
	public class ObjectPool<T> where T : ObjectPoolEvents, new()
	{
		private Stack<T> pool;

		public int maxInstances = 500;

		protected ObjectPool()
		{
		}

		public ObjectPool(int amount)
			: this(amount, amount)
		{
		}

		public ObjectPool(int initialAmount, int maxAmount)
		{
			InitializePool(initialAmount, maxAmount);
		}

		protected void InitializePool(int initialAmount, int maxAmount)
		{
			maxInstances = maxAmount;
			pool = new Stack<T>(initialAmount);
			for (int i = 0; i < initialAmount; i++)
			{
				pool.Push(CreateInstance());
			}
		}

		public T Take()
		{
			T result = ((pool.Count >= 1) ? pool.Pop() : CreateInstance());
			result.OnTaken();
			return result;
		}

		public void Return(T instance)
		{
			instance.OnReturned();
			if (pool.Count != maxInstances)
			{
				pool.Push(instance);
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public virtual T CreateInstance()
		{
			return new T();
		}
	}
	public delegate void InAction<T>(in T obj);
	public delegate void InAction<T1, T2>(in T1 obj1, in T2 obj2);
	public delegate void InAction<T1, T2, T3>(in T1 obj1, in T2 obj2, in T3 obj3);
	public delegate void InAction<T1, T2, T3, T4>(in T1 obj1, in T2 obj2, in T3 obj3, in T4 obj4);
}
namespace GorillaTag.Gravity
{
	public enum GravityZoneScaleFilter
	{
		Anyone,
		SmallOnly,
		NotSmall
	}
	public class BasicGravityZone : MonoBehaviour, ICallbackUnique, ICallBack
	{
		[Header("Gravity Settings")]
		[Tooltip("negative number pulls, positive number expels")]
		public float gravityStrength = -9.81f;

		[Tooltip("Filter which players are affected based on scale. Small = scale < 1")]
		[SerializeField]
		private GravityZoneScaleFilter scaleFilter;

		[Header("Rotation Settings")]
		[Tooltip("If enabled, rotates the target away from gravity direction to be upside down")]
		[SerializeField]
		protected bool invertRotationDirection;

		[SerializeField]
		protected bool rotateTarget = true;

		[SerializeField]
		protected float rotationSpeed = 10f;

		protected UnityEngine.Vector3 m_gravityDirection;

		protected ListProcessor<MonkeGravityController> m_gravityTargets = new ListProcessor<MonkeGravityController>(5);

		private Dictionary<MonkeGravityController, GravityInfo> m_targetGravityInfos = new Dictionary<MonkeGravityController, GravityInfo>(5);

		private IReadOnlyList<MonkeGravityController> GravityTargets => m_gravityTargets.GetReadonlyList();

		bool ICallbackUnique.Registered { get; set; }

		protected virtual void Awake()
		{
			m_gravityDirection = base.gameObject.transform.up;
			invertRotationDirection = (gravityStrength > 0f && !invertRotationDirection) || (gravityStrength <= 0f && invertRotationDirection);
		}

		protected virtual void OnEnable()
		{
			m_gravityTargets.ItemProcessor = ProcessGravityTargets;
		}

		protected virtual void OnDisable()
		{
			m_gravityTargets.ItemProcessor = ProcessRemoveTargets;
			m_gravityTargets.ProcessList();
			m_gravityTargets.Clear();
			m_targetGravityInfos.Clear();
			MonkeGravityManager.RemoveGravityCallback(this);
		}

		public virtual void CallBack()
		{
			m_gravityTargets.ProcessList();
		}

		private void ProcessRemoveTargets(in MonkeGravityController target)
		{
			target.OnLeftGravityZone(this);
		}

		private void ProcessGravityTargets(in MonkeGravityController targetController)
		{
			if (!PassesScaleFilter(targetController))
			{
				OnTargetFilteredOut(targetController);
			}
			GravityInfo value = default(GravityInfo);
			UnityEngine.Vector3 offsetFromGravity = GetGravityVectorAtPoint(targetController.GetWorldPoint(), in targetController);
			UnityEngine.Vector3 gravityDirection = (value.gravityUpDirection = offsetFromGravity.normalized);
			value.rotationDirection = GetRotationDirection(in gravityDirection);
			value.gravityStrength = GetGravityStrength(in offsetFromGravity);
			value.rotationSpeed = GetRotationSpeed(in offsetFromGravity);
			value.rotate = GetRotationIntent(in offsetFromGravity);
			m_targetGravityInfos[targetController] = value;
			if (value.gravityStrength != 0f)
			{
				targetController.ApplyGravityForce(gravityDirection * value.gravityStrength);
			}
		}

		protected virtual UnityEngine.Vector3 GetGravityVectorAtPoint(in UnityEngine.Vector3 worldPosition, in MonkeGravityController controller)
		{
			return m_gravityDirection;
		}

		protected virtual float GetGravityStrength(in UnityEngine.Vector3 offsetFromGravity)
		{
			return gravityStrength;
		}

		protected virtual bool GetRotationIntent(in UnityEngine.Vector3 offsetFromGravity)
		{
			return rotateTarget;
		}

		protected virtual UnityEngine.Vector3 GetRotationDirection(in UnityEngine.Vector3 gravityDirection)
		{
			if (invertRotationDirection)
			{
				return -gravityDirection;
			}
			return gravityDirection;
		}

		protected virtual float GetRotationSpeed(in UnityEngine.Vector3 offsetFromGravity)
		{
			return rotationSpeed;
		}

		public bool GetGravityInfo(MonkeGravityController target, out GravityInfo info)
		{
			return m_targetGravityInfos.TryGetValue(target, out info);
		}

		public void RemoveTarget(MonkeGravityController target)
		{
			if (target.Register && m_gravityTargets.Remove(in target))
			{
				m_targetGravityInfos.Remove(target);
				target.OnLeftGravityZone(this);
				OnTargetExited(target);
				if (m_gravityTargets.Count < 1)
				{
					MonkeGravityManager.RemoveGravityCallback(this);
				}
			}
		}

		public void AddTarget(MonkeGravityController target)
		{
			if (target.Register && !m_gravityTargets.Contains(in target))
			{
				m_gravityTargets.Add(in target);
				target.OnEnteredGravityZone(this);
				MonkeGravityManager.AddGravityCallback(this);
			}
		}

		protected virtual void OnTargetExited(MonkeGravityController target)
		{
		}

		protected virtual void OnTargetFilteredOut(MonkeGravityController target)
		{
		}

		private bool PassesScaleFilter(MonkeGravityController target)
		{
			if (scaleFilter == GravityZoneScaleFilter.Anyone)
			{
				return true;
			}
			bool flag = target.Scale < 1f;
			if (scaleFilter != GravityZoneScaleFilter.SmallOnly)
			{
				return !flag;
			}
			return flag;
		}

		private void OnTriggerEnter(Collider other)
		{
			(bool, MonkeGravityController) monkeGravityController = MonkeGravityManager.GetMonkeGravityController(other);
			if (monkeGravityController.Item1)
			{
				AddTarget(monkeGravityController.Item2);
			}
		}

		private void OnTriggerExit(Collider other)
		{
			(bool, MonkeGravityController) monkeGravityController = MonkeGravityManager.GetMonkeGravityController(other);
			if (monkeGravityController.Item1)
			{
				RemoveTarget(monkeGravityController.Item2);
			}
		}
	}
	public class ChangingBasicGravityZone : BasicGravityZone
	{
		[Header("Change Value To Trigger Gravity Strength Change At Set Value (false to true and true to false both work, but value must change the frame you want it changed)")]
		public bool ExternalTriggerSetGravityStrength;

		public float ExternalSetGravityStrength;

		private bool lastExternalTriggerSetMatched = true;

		private bool lastValueWhenSet;

		private bool m_strengthDirty;

		private float m_targetGravityStrength;

		private float m_lerpToGravitySpeed;

		private bool m_directionDity;

		private UnityEngine.Vector3 m_targetGravityDirection;

		private float m_lerpToDirectionSpeed;

		[SerializeField]
		private float m_changeStrengthTime;

		[SerializeField]
		private float m_changeDirectionTime;

		private ICallbackUnique m_thisCallbackUnique;

		protected override void Awake()
		{
			base.Awake();
			m_thisCallbackUnique = this;
			m_strengthDirty = false;
			m_directionDity = false;
		}

		protected override void OnDisable()
		{
			base.OnDisable();
			if (m_strengthDirty)
			{
				m_strengthDirty = false;
				gravityStrength = m_targetGravityStrength;
			}
			if (m_directionDity)
			{
				m_directionDity = false;
				m_gravityDirection = m_targetGravityDirection;
			}
		}

		public void Update()
		{
			if (lastValueWhenSet != ExternalTriggerSetGravityStrength)
			{
				if (!lastExternalTriggerSetMatched)
				{
					SetGravityStrength(ExternalSetGravityStrength);
					lastValueWhenSet = ExternalTriggerSetGravityStrength;
					lastExternalTriggerSetMatched = true;
				}
				else
				{
					ExternalTriggerSetGravityStrength = lastValueWhenSet;
					lastExternalTriggerSetMatched = false;
				}
			}
			else
			{
				lastExternalTriggerSetMatched = true;
			}
		}

		public void SetGravityStrength(float strength)
		{
			SetGravityStrength(strength, m_changeStrengthTime);
		}

		public void SetGravityDirection(UnityEngine.Vector3 dir)
		{
			SetGravityDirection(dir, m_changeDirectionTime);
		}

		public void SetGravityStrength(float strength, float time)
		{
			m_targetGravityStrength = strength;
			if (time == 0f || !m_thisCallbackUnique.Registered)
			{
				gravityStrength = m_targetGravityStrength;
				m_strengthDirty = false;
			}
			else
			{
				m_lerpToGravitySpeed = (strength - gravityStrength) / time;
				m_strengthDirty = true;
			}
		}

		public void SetGravityDirection(UnityEngine.Vector3 direction, float time)
		{
			m_targetGravityDirection = direction.normalized;
			if (time == 0f || !m_thisCallbackUnique.Registered)
			{
				m_gravityDirection = m_targetGravityDirection;
				m_directionDity = false;
			}
			else
			{
				float num = UnityEngine.Vector3.Angle(m_gravityDirection, direction) * (MathF.PI / 180f);
				m_lerpToDirectionSpeed = num / time;
				m_directionDity = true;
			}
		}

		public void SetRotationIntent(bool rotate)
		{
			rotateTarget = rotate;
		}

		public override void CallBack()
		{
			if (m_strengthDirty)
			{
				gravityStrength = Mathf.MoveTowards(gravityStrength, m_targetGravityStrength, m_lerpToGravitySpeed * Time.fixedDeltaTime);
				if (Mathf.Approximately(gravityStrength, m_targetGravityStrength))
				{
					m_strengthDirty = false;
				}
			}
			if (m_directionDity)
			{
				m_gravityDirection = UnityEngine.Vector3.RotateTowards(m_gravityDirection, m_targetGravityDirection, m_lerpToDirectionSpeed * Time.fixedDeltaTime, 0f);
				if (m_gravityDirection == m_targetGravityDirection)
				{
					m_directionDity = false;
				}
			}
			base.CallBack();
		}
	}
	public class ConsensusGravityZone : BasicGravityZone
	{
		private Collider zoneCollider;

		private float currentRot;

		private float idealRot;

		private float rotSpeed;

		[SerializeField]
		private float weightForce;

		[SerializeField]
		private float centeringForce;

		[SerializeField]
		private float drag;

		[SerializeField]
		private float rotMin = -45f;

		[SerializeField]
		private float rotMax = 45f;

		protected override void Awake()
		{
			base.Awake();
			zoneCollider = GetComponent<Collider>();
		}

		protected override UnityEngine.Vector3 GetGravityVectorAtPoint(in UnityEngine.Vector3 worldPosition, in MonkeGravityController controller)
		{
			return base.transform.TransformVector(new UnityEngine.Vector3(Mathf.Sin(currentRot * (MathF.PI / 180f)), Mathf.Cos(currentRot * (MathF.PI / 180f)), 0f));
		}

		private void FixedUpdate()
		{
			UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
			int num = 0;
			foreach (RigContainer activeRigContainer in VRRigCache.ActiveRigContainers)
			{
				UnityEngine.Vector3 position = activeRigContainer.Rig.transform.position;
				if (zoneCollider.bounds.Contains(position))
				{
					zero += position;
					num++;
				}
			}
			if (num > 0)
			{
				UnityEngine.Vector3 position2 = zero / num;
				UnityEngine.Vector3 vector = base.transform.InverseTransformPoint(position2);
				idealRot = Mathf.Atan2(vector.x, vector.y) * 57.29578f;
			}
			float num2 = (idealRot - currentRot) * weightForce - currentRot * centeringForce;
			rotSpeed += num2 * Time.fixedDeltaTime;
			rotSpeed *= drag;
			currentRot += rotSpeed * Time.fixedDeltaTime;
			if (currentRot < rotMin)
			{
				rotSpeed = 0f;
				currentRot = rotMin;
			}
			else if (currentRot > rotMax)
			{
				rotSpeed = 0f;
				currentRot = rotMax;
			}
		}

		protected override bool GetRotationIntent(in UnityEngine.Vector3 offsetFromGravity)
		{
			return true;
		}
	}
	public class CubicPlanetZone : PlanetZone
	{
		[Header("box constraint for where gravity center can be")]
		[SerializeField]
		protected UnityEngine.Vector3 constraints;

		[SerializeField]
		protected UnityEngine.Vector3 minConstraints;

		[SerializeField]
		protected UnityEngine.Vector3 maxConstraints;

		protected UnityEngine.Quaternion inverseRotation;

		private void UpdateConstraint()
		{
			float num = Mathf.Abs(constraints.x * 0.5f);
			float num2 = Mathf.Abs(constraints.y * 0.5f);
			float num3 = Mathf.Abs(constraints.z * 0.5f);
			minConstraints.x = num * -1f;
			minConstraints.y = num2 * -1f;
			minConstraints.z = num3 * -1f;
			maxConstraints.x = num;
			maxConstraints.y = num2;
			maxConstraints.z = num3;
		}

		protected override void Awake()
		{
			base.Awake();
			inverseRotation = UnityEngine.Quaternion.Inverse(base.transform.rotation);
			UpdateConstraint();
		}

		protected override UnityEngine.Vector3 GetGravityVectorAtPoint(in UnityEngine.Vector3 worldPosition, in MonkeGravityController controller)
		{
			return worldPosition - GetPointOnBounds(in worldPosition);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public UnityEngine.Vector3 GetPointOnBounds(in UnityEngine.Vector3 point)
		{
			Transform transform = base.transform;
			UnityEngine.Vector3 position = transform.position;
			UnityEngine.Vector3 vec = inverseRotation * (point - position);
			float x = vec.x;
			float y = vec.y;
			float z = vec.z;
			if (x <= maxConstraints.x && x >= minConstraints.x && y <= maxConstraints.y && y >= minConstraints.y && z <= maxConstraints.z && z >= minConstraints.z)
			{
				UnityEngine.Vector3 vec2 = new UnityEngine.Vector3((x > 0f) ? maxConstraints.x : minConstraints.x, (y > 0f) ? maxConstraints.y : minConstraints.y, (z > 0f) ? maxConstraints.z : minConstraints.z);
				float num = Mathf.Abs(vec2.x - x);
				float num2 = Mathf.Abs(vec2.y - y);
				float num3 = Mathf.Abs(vec2.z - z);
				UnityEngine.Vector3 mulitplier = new UnityEngine.Vector3((num <= num2 && num <= num3) ? 1f : 0f, (num2 <= num && num2 <= num3) ? 1f : 0f, (num3 <= num && num3 <= num2) ? 1f : 0f);
				UnityEngine.Vector3 vector = vec.MultiplyBy(in mulitplier);
				UnityEngine.Vector3 vector2 = vec2.MultiplyBy(in mulitplier);
				float magnitude = vector.magnitude;
				float magnitude2 = vector2.magnitude;
				float num4 = 1f / magnitude2;
				float num5 = magnitude * num4;
				num5 *= 0.99f;
				return position + transform.rotation * vec.Clamp(minConstraints * num5, maxConstraints * num5);
			}
			return position + transform.rotation * vec.Clamp(minConstraints, maxConstraints);
		}
	}
	public enum RotationDirection
	{
		None,
		Forward,
		Backward,
		Left,
		Right
	}
	public class MonkeGravityController : MonoBehaviour, ICallbackUnique, ICallBack
	{
		[SerializeField]
		private Collider m_activatorCollider;

		[SerializeField]
		protected Rigidbody m_targetRigidBody;

		[SerializeField]
		protected Transform m_targetTransform;

		[SerializeField]
		private bool m_instantRotation;

		[SerializeField]
		private bool m_useRotation;

		[SerializeField]
		private bool m_overrideForceMode;

		[SerializeField]
		private ForceMode m_forceModeOverride;

		[SerializeField]
		private BasicGravityZone m_alwaysInZone;

		[Tooltip("The direction we wish to rotate if the target is 180 degrees off.")]
		[SerializeField]
		protected RotationDirection m_preferredRotationDirection = RotationDirection.Right;

		private bool m_register;

		private readonly List<BasicGravityZone> m_gravityZones = new List<BasicGravityZone>(3);

		private bool m_needsRotationRecovery;

		protected bool m_globalGravityIntent;

		public Collider ActivatorCollider => m_activatorCollider;

		public Rigidbody TargetRigidBody => m_targetRigidBody;

		public Transform TargetTransform => m_targetTransform;

		public virtual float Scale => TargetTransform.localScale.x;

		protected bool InstantRotation => m_instantRotation;

		protected bool OverrideForceMode => m_overrideForceMode;

		public RotationDirection PreferredRotationDirection
		{
			get
			{
				return m_preferredRotationDirection;
			}
			set
			{
				m_preferredRotationDirection = value;
			}
		}

		public bool Register => m_register;

		public UnityEngine.Vector3 GravityUp { get; private set; } = UnityEngine.Vector3.up;

		public UnityEngine.Vector3 GravityDown { get; private set; } = UnityEngine.Vector3.down;

		public float GravityMultiplier { get; set; } = 1f;

		public UnityEngine.Vector3 PersonalGravityDirection { get; set; } = UnityEngine.Vector3.up;

		public int GravityZonesCount => m_gravityZones.Count;

		bool ICallbackUnique.Registered { get; set; }

		public void SetPersonalGravityDirection(UnityEngine.Vector3 direction)
		{
			PersonalGravityDirection = direction.normalized;
		}

		public void SetPersonalGravityDirection(Transform reference)
		{
			PersonalGravityDirection = reference.up;
		}

		protected virtual void Awake()
		{
			if (GTExt.IsNull(m_targetRigidBody))
			{
				m_targetRigidBody = GetComponent<Rigidbody>();
			}
			if (GTExt.IsNull(m_targetTransform))
			{
				m_targetTransform = base.transform;
			}
			if (m_alwaysInZone != null)
			{
				m_alwaysInZone.AddTarget(this);
			}
			else if (GTExt.IsNull(m_activatorCollider))
			{
				m_activatorCollider = GetComponent<Collider>();
				if (GTExt.IsNull(m_activatorCollider))
				{
					return;
				}
			}
			if (!GTExt.IsNull(m_targetRigidBody))
			{
				m_register = true;
				m_globalGravityIntent = m_targetRigidBody.useGravity;
			}
		}

		protected virtual void OnEnable()
		{
			if (m_register)
			{
				MonkeGravityManager.AddMonkeGravityController(this);
			}
		}

		protected virtual void OnDisable()
		{
			if (m_register)
			{
				m_targetRigidBody.useGravity = m_globalGravityIntent;
				MonkeGravityManager.RemoveMonkeGravityController(this);
				for (int num = m_gravityZones.Count - 1; num > -1; num--)
				{
					BasicGravityZone basicGravityZone = m_gravityZones[num];
					basicGravityZone.RemoveTarget(this);
					OnLeftGravityZone(basicGravityZone);
				}
			}
		}

		public virtual void CallBack()
		{
			if (m_gravityZones.Count < 1 || !m_gravityZones[m_gravityZones.Count - 1].GetGravityInfo(this, out var info))
			{
				info = MonkeGravityManager.DefaultGravityInfo;
			}
			GravityUp = info.gravityUpDirection;
			GravityDown = -GravityUp;
			if (m_gravityZones.Count < 1)
			{
				ApplyGravityForce(Physics.gravity);
			}
			if ((info.rotate || m_needsRotationRecovery) && m_useRotation)
			{
				ApplyGravityUpRotation(in info.rotationDirection, info.rotationSpeed * Time.fixedDeltaTime);
			}
		}

		public virtual UnityEngine.Vector3 GetWorldPoint()
		{
			return m_targetTransform.position;
		}

		public virtual void OnEnteredGravityZone(BasicGravityZone zone)
		{
			if (!m_gravityZones.Contains(zone))
			{
				m_gravityZones.Add(zone);
			}
			if (m_targetRigidBody.useGravity)
			{
				m_targetRigidBody.useGravity = false;
			}
		}

		public virtual void OnLeftGravityZone(BasicGravityZone zone)
		{
			m_gravityZones.Remove(zone);
			if (m_gravityZones.Count < 1)
			{
				m_targetRigidBody.useGravity = m_globalGravityIntent;
				m_needsRotationRecovery = true;
			}
		}

		public virtual void ApplyGravityForce(in UnityEngine.Vector3 force, ForceMode forceType = ForceMode.Acceleration)
		{
			if (!m_targetRigidBody.isKinematic)
			{
				m_targetRigidBody.AddForce(force * GravityMultiplier, m_overrideForceMode ? m_forceModeOverride : forceType);
			}
		}

		public void ClearRotationRecovery()
		{
			m_needsRotationRecovery = false;
		}

		public virtual void ApplyGravityUpRotation(in UnityEngine.Vector3 upDir, float speed)
		{
			UnityEngine.Vector3 up = m_targetTransform.up;
			UnityEngine.Vector3 toDirection;
			if (!m_instantRotation)
			{
				UnityEngine.Vector3 vector = upDir;
				if (vector == up * -1f)
				{
					switch (m_preferredRotationDirection)
					{
					case RotationDirection.Left:
						vector = m_targetTransform.right * -1f;
						break;
					case RotationDirection.Right:
						vector = m_targetTransform.right;
						break;
					case RotationDirection.Forward:
						vector = m_targetTransform.forward;
						break;
					case RotationDirection.Backward:
						vector = m_targetTransform.forward * -1f;
						break;
					}
				}
				toDirection = UnityEngine.Vector3.RotateTowards(up, vector, speed, 0f);
			}
			else
			{
				toDirection = upDir;
			}
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.FromToRotation(up, toDirection);
			m_targetRigidBody.MoveRotation(quaternion2 * m_targetTransform.rotation);
			if (quaternion2 == UnityEngine.Quaternion.identity)
			{
				m_needsRotationRecovery = false;
			}
		}
	}
	[Serializable]
	public struct GravityInfo
	{
		public UnityEngine.Vector3 gravityUpDirection;

		public UnityEngine.Vector3 rotationDirection;

		public float rotationSpeed;

		public float gravityStrength;

		public bool rotate;
	}
	public class MonkeGravityManager : MonoBehaviour
	{
		[SerializeField]
		private float defaultRotationSpeed = 10f;

		[SerializeField]
		private float defaultGravityStrength = -9.3f;

		private static readonly CallbackContainerUnique<BasicGravityZone> k_zones = new CallbackContainerUnique<BasicGravityZone>(5);

		private static readonly Dictionary<Collider, MonkeGravityController> k_allowedColliders = new Dictionary<Collider, MonkeGravityController>(10);

		private static readonly CallbackContainerUnique<MonkeGravityController> k_controllers = new CallbackContainerUnique<MonkeGravityController>(10);

		private static GravityInfo k_defaultGravityInfo = new GravityInfo
		{
			gravityUpDirection = UnityEngine.Vector3.up,
			rotationDirection = UnityEngine.Vector3.up,
			rotationSpeed = 10f,
			gravityStrength = -9.3f,
			rotate = false
		};

		public static GravityInfo DefaultGravityInfo => k_defaultGravityInfo;

		private void Awake()
		{
			k_defaultGravityInfo.rotationDirection = (k_defaultGravityInfo.gravityUpDirection = -Physics.gravity.normalized);
			k_defaultGravityInfo.rotationSpeed = defaultRotationSpeed;
			k_defaultGravityInfo.gravityStrength = defaultGravityStrength;
		}

		private void FixedUpdate()
		{
			k_zones.RunCallbacks();
			k_controllers.RunCallbacks();
		}

		public static void AddMonkeGravityController(MonkeGravityController gravity)
		{
			Collider activatorCollider = gravity.ActivatorCollider;
			k_allowedColliders.TryAdd(activatorCollider, gravity);
			k_controllers.Add(in gravity);
		}

		public static void RemoveMonkeGravityController(MonkeGravityController gravity)
		{
			k_allowedColliders.Remove(gravity.ActivatorCollider);
			k_controllers.Remove(in gravity);
		}

		public static (bool found, MonkeGravityController target) GetMonkeGravityController(Collider collider)
		{
			MonkeGravityController value;
			return (found: k_allowedColliders.TryGetValue(collider, out value), target: value);
		}

		public static void AddGravityCallback(BasicGravityZone zone)
		{
			k_zones.Add(in zone);
		}

		public static void RemoveGravityCallback(BasicGravityZone zone)
		{
			k_zones.Remove(in zone);
		}
	}
