	public class PlanetZone : BasicGravityZone
	{
		[Tooltip("how close to the center of the zone to enable rotating the player")]
		[SerializeField]
		protected float rotationDistance;

		[Tooltip("if enabled, always rotates the player")]
		[SerializeField]
		protected bool alwaysRotate = true;

		private float sqrDistance;

		protected override void Awake()
		{
			base.Awake();
			sqrDistance = rotationDistance * rotationDistance;
		}

		protected override UnityEngine.Vector3 GetGravityVectorAtPoint(in UnityEngine.Vector3 worldPosition, in MonkeGravityController controller)
		{
			return worldPosition - base.transform.position;
		}

		protected override bool GetRotationIntent(in UnityEngine.Vector3 offsetFromGravity)
		{
			if (!alwaysRotate)
			{
				if (rotateTarget)
				{
					return offsetFromGravity.sqrMagnitude < sqrDistance;
				}
				return false;
			}
			return true;
		}
	}
	public class SplinePlanetZone : PlanetZone
	{
		[SerializeField]
		private CatmullRomSpline spline;

		protected override UnityEngine.Vector3 GetGravityVectorAtPoint(in UnityEngine.Vector3 worldPosition, in MonkeGravityController controller)
		{
			UnityEngine.Vector3 linePoint;
			float closestEvaluationOnSpline = spline.GetClosestEvaluationOnSpline(worldPosition, out linePoint);
			UnityEngine.Vector3 vector = spline.Evaluate(closestEvaluationOnSpline);
			return worldPosition - vector;
		}
	}
	public class TorusZone : BasicGravityZone
	{
		[Tooltip("Major radius of the torus (distance from torus center to the centerline of the tube). Torus axis is transform.up.")]
		[SerializeField]
		protected float majorRadius = 5f;

		[Tooltip("how close to the central ring of the torus to enable rotating the player")]
		[SerializeField]
		protected float rotationDistance;

		[Tooltip("if enabled, always rotates the player")]
		[SerializeField]
		protected bool alwaysRotate = true;

		private float sqrDistance;

		protected override void Awake()
		{
			base.Awake();
			sqrDistance = rotationDistance * rotationDistance;
		}

		protected override UnityEngine.Vector3 GetGravityVectorAtPoint(in UnityEngine.Vector3 worldPosition, in MonkeGravityController controller)
		{
			UnityEngine.Vector3 up = base.transform.up;
			UnityEngine.Vector3 vector = worldPosition - base.transform.position;
			UnityEngine.Vector3 vector2 = vector - up * UnityEngine.Vector3.Dot(vector, up);
			float sqrMagnitude = vector2.sqrMagnitude;
			UnityEngine.Vector3 vector4;
			if (sqrMagnitude < 1E-10f)
			{
				UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(up, UnityEngine.Vector3.right);
				if (vector3.sqrMagnitude < 1E-10f)
				{
					vector3 = UnityEngine.Vector3.Cross(up, UnityEngine.Vector3.forward);
				}
				vector4 = base.transform.position + vector3.normalized * majorRadius;
			}
			else
			{
				vector4 = base.transform.position + vector2 * (majorRadius / Mathf.Sqrt(sqrMagnitude));
			}
			return worldPosition - vector4;
		}

		protected override bool GetRotationIntent(in UnityEngine.Vector3 offsetFromGravity)
		{
			if (!alwaysRotate)
			{
				if (rotateTarget)
				{
					return offsetFromGravity.sqrMagnitude < sqrDistance;
				}
				return false;
			}
			return true;
		}
	}
