			_reactionsRemaining = 0;
			for (int i = 0; i < _statusEffectReactions.Length; i++)
			{
				_reactionsRemaining += _statusEffectReactions[i].gameObjectStates.Length;
			}
			_currentMatIndexStartTime = 0.0;
