	public class ShakeReaction : MonoBehaviour, ITickSystemPost
	{
		[SerializeField]
		private Transform shakeXform;

		[SerializeField]
		private float velocityThreshold = 5f;

		[SerializeField]
		private SoundBankPlayer shakeSoundBankPlayer;

		[SerializeField]
		private float shakeSoundCooldown = 1f;

		[SerializeField]
		private AudioSource loopSoundAudioSource;

		[SerializeField]
		private float loopSoundBaseVolume = 1f;

		[SerializeField]
		private float loopSoundSustainDuration = 1f;

		[SerializeField]
		private float loopSoundFadeInDuration = 1f;

		[SerializeField]
		private AnimationCurve loopSoundFadeInCurve;

		[SerializeField]
		private float loopSoundFadeOutDuration = 1f;

		[SerializeField]
		private AnimationCurve loopSoundFadeOutCurve;

		[SerializeField]
		private ParticleSystem particles;

		[SerializeField]
		private AnimationCurve emissionCurve;

		[SerializeField]
		private float particleDuration = 5f;

		private const int sampleHistorySize = 256;

		private float[] sampleHistoryTime;

		private UnityEngine.Vector3[] sampleHistoryPos;

		private UnityEngine.Vector3[] sampleHistoryVel;

		private int currentIndex;

		private float lastShakeSoundTime = float.MinValue;

		private float lastShakeTime = float.MinValue;

		private float maxEmissionRate;

		private bool hasLoopSound;

		private bool hasShakeSound;

		private bool hasParticleSystem;

		[DebugReadout]
		private float poopVelocity;

		private float loopSoundTotalDuration => loopSoundFadeInDuration + loopSoundSustainDuration + loopSoundFadeOutDuration;

		bool ITickSystemPost.PostTickRunning { get; set; }

		protected void Awake()
		{
			sampleHistoryPos = new UnityEngine.Vector3[256];
			sampleHistoryTime = new float[256];
			sampleHistoryVel = new UnityEngine.Vector3[256];
			if (particles != null)
			{
				maxEmissionRate = particles.emission.rateOverTime.constant;
			}
			UnityEngine.Application.quitting += HandleApplicationQuitting;
		}

		protected void OnEnable()
		{
			float unscaledTime = Time.unscaledTime;
			UnityEngine.Vector3 position = shakeXform.position;
			for (int i = 0; i < 256; i++)
			{
				sampleHistoryTime[i] = unscaledTime;
				sampleHistoryPos[i] = position;
				sampleHistoryVel[i] = UnityEngine.Vector3.zero;
			}
			if (loopSoundAudioSource != null)
			{
				loopSoundAudioSource.loop = true;
				loopSoundAudioSource.GTPlay();
			}
			hasLoopSound = loopSoundAudioSource != null;
			hasShakeSound = shakeSoundBankPlayer != null;
			hasParticleSystem = particles != null;
			TickSystem<object>.AddPostTickCallback(this);
		}

		protected void OnDisable()
		{
			if (loopSoundAudioSource != null)
			{
				loopSoundAudioSource.GTStop();
			}
			TickSystem<object>.RemovePostTickCallback(this);
		}

		private void HandleApplicationQuitting()
		{
			TickSystem<object>.RemovePostTickCallback(this);
		}

		void ITickSystemPost.PostTick()
		{
			float unscaledTime = Time.unscaledTime;
			UnityEngine.Vector3 position = shakeXform.position;
			int num = (currentIndex - 1 + 256) % 256;
			currentIndex = (currentIndex + 1) % 256;
			sampleHistoryTime[currentIndex] = unscaledTime;
			float num2 = unscaledTime - sampleHistoryTime[num];
			sampleHistoryPos[currentIndex] = position;
			if (num2 > 0f)
			{
				UnityEngine.Vector3 vector = position - sampleHistoryPos[num];
				sampleHistoryVel[currentIndex] = vector / num2;
			}
			else
			{
				sampleHistoryVel[currentIndex] = UnityEngine.Vector3.zero;
			}
			float sqrMagnitude = (sampleHistoryVel[num] - sampleHistoryVel[currentIndex]).sqrMagnitude;
			poopVelocity = Mathf.Round(Mathf.Sqrt(sqrMagnitude) * 1000f) / 1000f;
			float num3 = shakeXform.lossyScale.x * velocityThreshold * velocityThreshold;
			if (sqrMagnitude >= num3)
			{
				lastShakeTime = unscaledTime;
			}
			float num4 = unscaledTime - lastShakeTime;
			float time = Mathf.Clamp01(num4 / particleDuration);
			if (hasParticleSystem)
			{
				ParticleSystem.EmissionModule emission = particles.emission;
				emission.rateOverTime = emissionCurve.Evaluate(time) * maxEmissionRate;
			}
			if (hasShakeSound && lastShakeTime - lastShakeSoundTime > shakeSoundCooldown)
			{
				shakeSoundBankPlayer.Play();
				lastShakeSoundTime = unscaledTime;
			}
			if (hasLoopSound)
			{
				if (num4 < loopSoundFadeInDuration)
				{
					loopSoundAudioSource.volume = loopSoundBaseVolume * loopSoundFadeInCurve.Evaluate(Mathf.Clamp01(num4 / loopSoundFadeInDuration));
				}
				else if (num4 < loopSoundFadeInDuration + loopSoundSustainDuration)
				{
					loopSoundAudioSource.volume = loopSoundBaseVolume;
				}
				else
				{
					loopSoundAudioSource.volume = loopSoundBaseVolume * loopSoundFadeOutCurve.Evaluate(Mathf.Clamp01((num4 - loopSoundFadeInDuration - loopSoundSustainDuration) / loopSoundFadeOutDuration));
				}
			}
		}
	}
	public class SpawnWorldEffects : MonoBehaviour
	{
		private enum TransformAxis
		{
			Forward,
			Back,
			Right,
			Left,
			Up,
			Down
		}

		[Tooltip("The defaults are numbers for the flamethrower hair dryer.")]
		private readonly float _maxParticleHitReactionRate = 2f;

		[Tooltip("Must be in the global object pool and have a tag.")]
		[SerializeField]
		private GameObject _prefabToSpawn;

		[Tooltip("When enabled, a short raycast is fired from the spawn position to find the exact surface normal. The spawned object's Up vector will be aligned to that normal instead of world Up.")]
		[SerializeField]
		private bool _useNormalOrientation;

		[SerializeField]
		private float _normalRaycastDistance = 0.3f;

		[SerializeField]
		private LayerMask _normalRaycastLayers = 134218241;

		[Header("Raycast Direction Override")]
		[Tooltip("Optional. When assigned, the raycast used for normal-orientation will shoot along this transform's forward axis instead of along the incoming hit normal.")]
		[SerializeField]
		private Transform _raycastDirectionSource;

		[Tooltip("If true, uses -forward instead of forward from Raycast Direction Source.")]
		[SerializeField]
		private bool _raycastDirectionUseNegativeForward;

		[Header("Forward Orientation")]
		[Tooltip("Optional. When assigned, the spawned object's forward vector will be aligned to the chosen axis of this transform, projected onto the spawn surface.")]
		[SerializeField]
		private Transform _forwardOrientationSource;

		[Tooltip("Which local axis of the Forward Orientation Source to use as the spawned object's forward.")]
		[SerializeField]
		private TransformAxis _forwardSourceAxis;

		private bool _hasPrefabToSpawn;

		private bool _isPrefabInPool;

		private double _lastCollisionTime;

		private SinglePool _pool;

		protected void OnEnable()
		{
			if (GorillaComputer.instance == null)
			{
				UnityEngine.Debug.LogError("SpawnWorldEffects: Disabling because GorillaComputer not found! Hierarchy path: " + base.transform.GetPath(), this);
				base.enabled = false;
				return;
			}
			if (_prefabToSpawn != null && !_isPrefabInPool)
			{
				if (_prefabToSpawn.CompareTag("Untagged"))
				{
					UnityEngine.Debug.LogError("SpawnWorldEffects: Disabling because Spawn Prefab has no tag! Hierarchy path: " + base.transform.GetPath(), this);
					base.enabled = false;
					return;
				}
				_isPrefabInPool = ObjectPools.instance.DoesPoolExist(_prefabToSpawn);
				if (!_isPrefabInPool)
				{
					UnityEngine.Debug.LogError("SpawnWorldEffects: Disabling because Spawn Prefab not in pool! Hierarchy path: " + base.transform.GetPath(), this);
					base.enabled = false;
					return;
				}
				_pool = ObjectPools.instance.GetPoolByObjectType(_prefabToSpawn);
			}
			_hasPrefabToSpawn = _prefabToSpawn != null && _isPrefabInPool;
		}

		public void RequestSpawn(UnityEngine.Vector3 worldPosition)
		{
			RequestSpawn(worldPosition, UnityEngine.Vector3.up);
		}

		public void RequestSpawn(UnityEngine.Vector3 worldPosition, UnityEngine.Vector3 normal)
		{
			if (_maxParticleHitReactionRate < 1E-05f || !FireManager.hasInstance)
			{
				return;
			}
			double num = GTTime.TimeAsDouble();
			if ((float)(num - _lastCollisionTime) < 1f / _maxParticleHitReactionRate)
			{
				return;
			}
			if (_hasPrefabToSpawn && _isPrefabInPool && _pool.GetInactiveCount() > 0)
			{
				UnityEngine.Vector3 vector = normal;
				if (_useNormalOrientation)
				{
					vector = GetSurfaceNormal(worldPosition, normal);
				}
				UnityEngine.Quaternion? rotationOverride = null;
				if (_forwardOrientationSource != null)
				{
					UnityEngine.Vector3 vector2 = UnityEngine.Vector3.ProjectOnPlane(GetAxisVector(_forwardOrientationSource, _forwardSourceAxis), vector);
					if (vector2.sqrMagnitude < 0.0001f)
					{
						vector2 = UnityEngine.Vector3.ProjectOnPlane((Mathf.Abs(vector.y) < 0.99f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.right, vector);
					}
					rotationOverride = UnityEngine.Quaternion.LookRotation(vector2.normalized, vector);
				}
				FireManager.SpawnFire(_pool, worldPosition, vector, base.transform.lossyScale.x, rotationOverride);
			}
			_lastCollisionTime = num;
		}

		private static UnityEngine.Vector3 GetAxisVector(Transform source, TransformAxis axis)
		{
			return axis switch
			{
				TransformAxis.Forward => source.forward, 
				TransformAxis.Back => -source.forward, 
				TransformAxis.Right => source.right, 
				TransformAxis.Left => -source.right, 
				TransformAxis.Up => source.up, 
				TransformAxis.Down => -source.up, 
				_ => source.forward, 
			};
		}

		private UnityEngine.Vector3 GetSurfaceNormal(UnityEngine.Vector3 worldPosition, UnityEngine.Vector3 hitNormal)
		{
			UnityEngine.Vector3 vector2;
			if (_raycastDirectionSource != null)
			{
				UnityEngine.Vector3 vector = _raycastDirectionSource.forward;
				if (_raycastDirectionUseNegativeForward)
				{
					vector = -vector;
				}
				vector2 = ((vector.sqrMagnitude > 1E-06f) ? vector.normalized : UnityEngine.Vector3.down);
			}
			else
			{
				vector2 = -((hitNormal.sqrMagnitude > 1E-06f) ? hitNormal.normalized : UnityEngine.Vector3.up);
			}
			UnityEngine.Vector3 origin = worldPosition + -vector2 * 0.05f;
			UnityEngine.Vector3 direction = vector2;
			if (Physics.Raycast(origin, direction, out var hitInfo, _normalRaycastDistance + 0.05f, _normalRaycastLayers, QueryTriggerInteraction.Ignore))
			{
				return hitInfo.normal;
			}
			return hitNormal;
		}
	}
}
