		{
			Bounds bounds = mesh.bounds;
			float num = Mathf.Max(bounds.size.x, Mathf.Max(bounds.size.y, bounds.size.z));
			if (!(num > 0f))
			{
				return 0f;
			}
			return 1f / num;
		}

