				else if (bones[i].parent == null)
				{
					UnityEngine.Debug.LogError($"unexpected and unhandled scenario -- skinned mesh bone at index {i} has no parent in " + "component: \"" + skinnedMeshRenderer.GetComponentPath() + "\"", skinnedMeshRenderer);
				}
