	public static class CosmeticExclusionZoneRegistry
	{
		private static readonly HashSet<VRRig> restrictedRigs = new HashSet<VRRig>();

		public static void Enter(VRRig rig)
		{
			if (rig != null)
			{
				restrictedRigs.Add(rig);
			}
		}

		public static void Exit(VRRig rig)
		{
			if (rig != null)
			{
				restrictedRigs.Remove(rig);
			}
		}

		public static bool IsRestricted(VRRig rig)
		{
			if (rig != null)
			{
				return restrictedRigs.Contains(rig);
			}
			return false;
		}

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
		private static void Reset()
		{
			restrictedRigs.Clear();
		}
	}
	public static class CosmeticExclusionZoneRegistryUtility
	{
		private static readonly List<Collider> exclusionZones = new List<Collider>();

		public static void RegisterZone(Collider zone)
		{
			if (zone != null && !exclusionZones.Contains(zone))
			{
				exclusionZones.Add(zone);
			}
		}

		public static void UnregisterZone(Collider zone)
		{
			exclusionZones.Remove(zone);
		}

		public static bool IsPositionRestricted(UnityEngine.Vector3 worldPos)
		{
			for (int i = 0; i < exclusionZones.Count; i++)
			{
				Collider collider = exclusionZones[i];
				if (collider != null && collider.bounds.Contains(worldPos))
				{
					return true;
				}
			}
			return false;
		}
	}
