namespace GorillaTag.Audio
{
	internal static class GTAudioOneShot
	{
		private struct DelayedPlayData
		{
			public AudioClip sound;

			public Transform xform;

			public UnityEngine.Vector3 pos;

			public float volume;

			public float pitch;
		}

		private class DelayedPlayListener : IDelayedExecListener
		{
			public void OnDelayedAction(int contextId)
			{
				if ((uint)contextId < (uint)_delayedHighWater)
				{
					ref DelayedPlayData reference = ref _delayedData[contextId];
					if (reference.sound != null)
					{
						UnityEngine.Vector3 position = ((reference.xform != null) ? reference.xform.TransformPoint(reference.pos) : reference.pos);
						Play(reference.sound, position, reference.volume, reference.pitch);
					}
					reference = default(DelayedPlayData);
					_delayedFreeNext[contextId] = _delayedFreeHead;
					_delayedFreeHead = contextId;
				}
			}
		}

		[OnEnterPlay_SetNull]
		internal static AudioSource audioSource;

		[OnEnterPlay_SetNull]
		internal static AnimationCurve defaultCurve;

		private const int k_initialDelayedCount = 32;

		[OnEnterPlay_Set(0)]
		private static int _delayedHighWater;

		[OnEnterPlay_Set(-1)]
		private static int _delayedFreeHead = -1;

		[OnEnterPlay_SetNew]
		private static DelayedPlayData[] _delayedData = new DelayedPlayData[32];

		[OnEnterPlay_SetNew]
		private static int[] _delayedFreeNext = new int[32];

		[OnEnterPlay_SetNew]
		private static readonly DelayedPlayListener _delayedListener = new DelayedPlayListener();

		[field: OnEnterPlay_Set(false)]
		internal static bool isInitialized { get; private set; }

		[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
		private static void Initialize()
		{
			if (!isInitialized)
			{
				AudioSource audioSource = Resources.Load<AudioSource>("AudioSourceSingleton_Prefab");
				if (audioSource == null)
				{
					UnityEngine.Debug.LogError("GTAudioOneShot: Failed to load AudioSourceSingleton_Prefab from resources!!!");
					return;
				}
				GTAudioOneShot.audioSource = UnityEngine.Object.Instantiate(audioSource);
				defaultCurve = GTAudioOneShot.audioSource.GetCustomCurve(AudioSourceCurveType.CustomRolloff);
				UnityEngine.Object.DontDestroyOnLoad(GTAudioOneShot.audioSource);
				isInitialized = true;
			}
		}

		internal static void Play(AudioClip clip, UnityEngine.Vector3 position, float volume = 1f, float pitch = 1f)
		{
			if (!ApplicationQuittingState.IsQuitting && isInitialized)
			{
				audioSource.pitch = pitch;
				audioSource.transform.position = position;
				audioSource.GTPlayOneShot(clip, volume);
			}
		}

		internal static void Play(AudioClip clip, UnityEngine.Vector3 position, AnimationCurve curve, float volume = 1f, float pitch = 1f)
		{
			if (!ApplicationQuittingState.IsQuitting && isInitialized)
			{
				audioSource.SetCustomCurve(AudioSourceCurveType.CustomRolloff, curve);
				Play(clip, position, volume, pitch);
				audioSource.SetCustomCurve(AudioSourceCurveType.CustomRolloff, defaultCurve);
			}
		}

		internal static int PlayDelayed(AudioClip sound, UnityEngine.Vector3 pos, float delay, float volume = 1f, float pitch = 1f)
		{
			return PlayDelayed(sound, null, pos, delay, volume, pitch);
		}

		internal static int PlayDelayed(AudioClip sound, Transform xform, UnityEngine.Vector3 pos, float delay, float volume = 1f, float pitch = 1f)
		{
			if (ApplicationQuittingState.IsQuitting || !isInitialized)
			{
				return -1;
			}
			int num;
			if (_delayedFreeHead >= 0)
			{
				num = _delayedFreeHead;
				_delayedFreeHead = _delayedFreeNext[num];
			}
			else
			{
				if (_delayedHighWater >= _delayedData.Length)
				{
					int newSize = _delayedData.Length * 2;
					Array.Resize(ref _delayedData, newSize);
					Array.Resize(ref _delayedFreeNext, newSize);
				}
				num = _delayedHighWater++;
			}
			_delayedData[num] = new DelayedPlayData
			{
				sound = sound,
				xform = xform,
				pos = pos,
				volume = volume,
				pitch = pitch
			};
			GTDelayedExec.Add(_delayedListener, delay, num);
			return num;
		}

		internal static void CancelDelayed(int idx)
		{
			if ((uint)idx < (uint)_delayedHighWater)
			{
				_delayedData[idx].sound = null;
			}
		}

		internal static void UpdateDelayed(int idx, Transform xform)
		{
			if ((uint)idx < (uint)_delayedHighWater)
			{
				ref DelayedPlayData reference = ref _delayedData[idx];
				if (!(reference.sound == null))
				{
					reference.xform = xform;
				}
			}
		}

		internal static void UpdateDelayed(int idx, UnityEngine.Vector3 pos)
		{
			if ((uint)idx < (uint)_delayedHighWater)
			{
				ref DelayedPlayData reference = ref _delayedData[idx];
				if (!(reference.sound == null))
				{
					reference.pos = pos;
				}
			}
		}

		internal static void UpdateDelayed(int idx, Transform xform, UnityEngine.Vector3 pos)
		{
			if ((uint)idx < (uint)_delayedHighWater)
			{
				ref DelayedPlayData reference = ref _delayedData[idx];
				if (!(reference.sound == null))
				{
					reference.xform = xform;
					reference.pos = pos;
				}
			}
		}
	}
	public class PlanarSound : MonoBehaviour
	{
		private Transform cameraXform;

		private bool hasCamera;

		[SerializeField]
		private bool limitDistance;

		[SerializeField]
		private float maxDistance = 1f;

		protected void OnEnable()
		{
			if (Camera.main != null)
			{
				cameraXform = Camera.main.transform;
				hasCamera = true;
			}
		}

		protected void LateUpdate()
		{
			if (hasCamera)
			{
				Transform obj = base.transform;
				UnityEngine.Vector3 localPosition = obj.parent.InverseTransformPoint(cameraXform.position);
				localPosition.y = 0f;
				if (limitDistance && localPosition.sqrMagnitude > maxDistance * maxDistance)
				{
					localPosition = localPosition.normalized * maxDistance;
				}
				obj.localPosition = localPosition;
			}
		}
	}
	[RequireComponent(typeof(Recorder))]
	public class VoiceToLoudness : MonoBehaviour
	{
		[NonSerialized]
		public float Loudness;

		private Recorder _recorder;

		private bool _photonVoiceCreated;

		private float _checkVoice;

		protected void Awake()
		{
			_recorder = GetComponent<Recorder>();
		}

		protected void PhotonVoiceCreated(PhotonVoiceCreatedParams photonVoiceCreatedParams)
		{
			CreateProcessVoiceData(photonVoiceCreatedParams.Voice);
		}

		private void CreateProcessVoiceData(LocalVoice voice)
		{
			if (voice is LocalVoiceAudioFloat localVoiceAudioFloat)
			{
				_photonVoiceCreated = true;
				localVoiceAudioFloat.AddPostProcessor(new ProcessVoiceDataToLoudness(this));
			}
		}

		private void Update()
		{
			if (!_photonVoiceCreated && _recorder != null && _recorder.Voice != null)
			{
				CreateProcessVoiceData(_recorder.Voice);
			}
		}
	}
	internal class ProcessVoiceDataToLoudness : IProcessor<float>, IDisposable
	{
		private VoiceToLoudness _voiceToLoudness;

		public ProcessVoiceDataToLoudness(VoiceToLoudness voiceToLoudness)
		{
			_voiceToLoudness = voiceToLoudness;
		}

		public float[] Process(float[] buf)
		{
			float num = 0f;
			for (int i = 0; i < buf.Length; i++)
			{
				num += Mathf.Abs(buf[i]);
			}
			_voiceToLoudness.Loudness = num / (float)buf.Length;
			return buf;
		}

		public void Dispose()
		{
		}
	}
	public class DuplicateAudioSource : MonoBehaviour
	{
		public AudioSource TargetAudioSource;

		[SerializeField]
		private AudioSource _audioSource;

		[SerializeField]
		private bool _isDuplicating;

		public void SetTargetAudioSource(AudioSource target)
		{
			TargetAudioSource = target;
			StartDuplicating();
		}

		[ContextMenu("Start Duplicating")]
		public void StartDuplicating()
		{
			_isDuplicating = true;
			_audioSource.loop = TargetAudioSource.loop;
			_audioSource.clip = TargetAudioSource.clip;
			if (TargetAudioSource.isPlaying)
			{
				_audioSource.Play();
			}
		}

		[ContextMenu("Stop Duplicating")]
		public void StopDuplicating()
		{
			_isDuplicating = false;
			_audioSource.Stop();
		}

		public void LateUpdate()
		{
			if (_isDuplicating)
			{
				if (TargetAudioSource.isPlaying && !_audioSource.isPlaying)
				{
					_audioSource.Play();
				}
				else if (!TargetAudioSource.isPlaying && _audioSource.isPlaying)
				{
					_audioSource.Stop();
				}
			}
		}
	}
	public class GTMicWrapper : MicWrapper
	{
		private bool _allowPitchAdjustment;

		private float _pitchAdjustment = 1f;

		private bool _allowVolumeAdjustment;

		private float _volumeAdjustment = 1f;

		private static readonly int MaxFrameLength = 16000;

		private readonly float[] InFifo = new float[MaxFrameLength];

		private readonly float[] OutFifo = new float[MaxFrameLength];

		private readonly float[] FfTworksp = new float[2 * MaxFrameLength];

		private readonly float[] LastPhase = new float[MaxFrameLength / 2 + 1];

		private readonly float[] SumPhase = new float[MaxFrameLength / 2 + 1];

		private readonly float[] OutputAccum = new float[2 * MaxFrameLength];

		private readonly float[] AnaFreq = new float[MaxFrameLength];

		private readonly float[] AnaMagn = new float[MaxFrameLength];

		private readonly float[] SynFreq = new float[MaxFrameLength];

		private readonly float[] SynMagn = new float[MaxFrameLength];

		private long _gRover;

		public GTMicWrapper(string device, int suggestedFrequency, bool allowPitchAdjustment, float pitchAdjustment, bool allowVolumeAdjustment, float volumeAdjustment, Photon.Voice.ILogger logger)
			: base(device, suggestedFrequency, logger)
		{
			UpdatePitchAdjustment(allowPitchAdjustment, pitchAdjustment);
			UpdateVolumeAdjustment(allowVolumeAdjustment, volumeAdjustment);
		}

		public void UpdateWrapper(bool allowPitchAdjustment, float pitchAdjustment, bool allowVolumeAdjustment, float volumeAdjustment)
		{
			UpdatePitchAdjustment(allowPitchAdjustment, pitchAdjustment);
			UpdateVolumeAdjustment(allowVolumeAdjustment, volumeAdjustment);
		}

		public void UpdatePitchAdjustment(bool allow, float pitchAdjustment)
		{
			_allowPitchAdjustment = allow;
			_pitchAdjustment = pitchAdjustment;
		}

		public void UpdateVolumeAdjustment(bool allow, float volumeAdjustment)
		{
			_allowVolumeAdjustment = allow;
			_volumeAdjustment = volumeAdjustment;
		}

		public override bool Read(float[] buffer)
		{
			if (base.Error != null)
			{
				return false;
			}
			int position = UnityMicrophone.GetPosition(device);
			if (position < micPrevPos)
			{
				micLoopCnt++;
			}
			micPrevPos = position;
			int num = micLoopCnt * mic.samples + position;
			if (mic.channels == 0)
			{
				base.Error = "Number of channels is 0 in Read()";
				logger.LogError("[PV] MicWrapper: " + base.Error);
				return false;
			}
			int num2 = buffer.Length / mic.channels;
			int num3 = readAbsPos + num2;
			if (num3 < num)
			{
				mic.GetData(buffer, readAbsPos % mic.samples);
				readAbsPos = num3;
				float num4 = Mathf.Clamp(_pitchAdjustment, 0.5f, 2f);
				if (_allowPitchAdjustment && !Mathf.Approximately(num4, 1f))
				{
					PitchShift(num4, num2, base.SamplingRate, buffer);
				}
				if (_allowVolumeAdjustment && !Mathf.Approximately(_volumeAdjustment, 1f))
				{
					for (int i = 0; i < buffer.Length; i++)
					{
						buffer[i] = Mathf.Clamp(buffer[i] * _volumeAdjustment, float.MinValue, float.MaxValue);
					}
				}
				return true;
			}
			return false;
		}

		private void PitchShift(float pitchShift, long numSampsToProcess, float sampleRate, float[] indata)
		{
			PitchShift(pitchShift, numSampsToProcess, 2048L, 10L, sampleRate, indata);
		}

		public void PitchShift(float pitchShift, long numSampsToProcess, long fftFrameSize, long osamp, float sampleRate, float[] indata)
		{
			long num = fftFrameSize / 2;
			long num2 = fftFrameSize / osamp;
			double num3 = (double)sampleRate / (double)fftFrameSize;
			double num4 = System.Math.PI * 2.0 * (double)num2 / (double)fftFrameSize;
			long num5 = fftFrameSize - num2;
			if (_gRover == 0L)
			{
				_gRover = num5;
			}
			for (long num6 = 0L; num6 < numSampsToProcess; num6++)
			{
				InFifo[_gRover] = indata[num6];
				indata[num6] = OutFifo[_gRover - num5];
				_gRover++;
				if (_gRover < fftFrameSize)
				{
					continue;
				}
				_gRover = num5;
				for (long num7 = 0L; num7 < fftFrameSize; num7++)
				{
					double num8 = -0.5 * System.Math.Cos(System.Math.PI * 2.0 * (double)num7 / (double)fftFrameSize) + 0.5;
					FfTworksp[2 * num7] = (float)((double)InFifo[num7] * num8);
					FfTworksp[2 * num7 + 1] = 0f;
				}
				ShortTimeFourierTransform(FfTworksp, fftFrameSize, -1L);
				for (long num7 = 0L; num7 <= num; num7++)
				{
					double num9 = FfTworksp[2 * num7];
					double num10 = FfTworksp[2 * num7 + 1];
					double num11 = 2.0 * System.Math.Sqrt(num9 * num9 + num10 * num10);
					double num12 = System.Math.Atan2(num10, num9);
					double num13 = num12 - (double)LastPhase[num7];
					LastPhase[num7] = (float)num12;
					num13 -= (double)num7 * num4;
					long num14 = (long)(num13 / System.Math.PI);
					num14 = ((num14 < 0) ? (num14 - (num14 & 1)) : (num14 + (num14 & 1)));
					num13 -= System.Math.PI * (double)num14;
					num13 = (double)osamp * num13 / (System.Math.PI * 2.0);
					num13 = (double)num7 * num3 + num13 * num3;
					AnaMagn[num7] = (float)num11;
					AnaFreq[num7] = (float)num13;
				}
				for (int i = 0; i < fftFrameSize; i++)
				{
					SynMagn[i] = 0f;
					SynFreq[i] = 0f;
				}
				for (long num7 = 0L; num7 <= num; num7++)
				{
					long num15 = (long)((float)num7 * pitchShift);
					if (num15 <= num)
					{
						SynMagn[num15] += AnaMagn[num7];
						SynFreq[num15] = AnaFreq[num7] * pitchShift;
					}
				}
				for (long num7 = 0L; num7 <= num; num7++)
				{
					double num11 = SynMagn[num7];
					double num13 = SynFreq[num7];
					num13 -= (double)num7 * num3;
					num13 /= num3;
					num13 = System.Math.PI * 2.0 * num13 / (double)osamp;
					num13 += (double)num7 * num4;
					SumPhase[num7] += (float)num13;
					double num12 = SumPhase[num7];
					FfTworksp[2 * num7] = (float)(num11 * System.Math.Cos(num12));
					FfTworksp[2 * num7 + 1] = (float)(num11 * System.Math.Sin(num12));
				}
				for (long num7 = fftFrameSize + 2; num7 < 2 * fftFrameSize; num7++)
				{
					FfTworksp[num7] = 0f;
				}
				ShortTimeFourierTransform(FfTworksp, fftFrameSize, 1L);
				for (long num7 = 0L; num7 < fftFrameSize; num7++)
				{
					double num8 = -0.5 * System.Math.Cos(System.Math.PI * 2.0 * (double)num7 / (double)fftFrameSize) + 0.5;
					OutputAccum[num7] += (float)(2.0 * num8 * (double)FfTworksp[2 * num7] / (double)(num * osamp));
				}
				for (long num7 = 0L; num7 < num2; num7++)
				{
					OutFifo[num7] = OutputAccum[num7];
				}
				for (long num7 = 0L; num7 < fftFrameSize; num7++)
				{
					OutputAccum[num7] = OutputAccum[num7 + num2];
				}
				for (long num7 = 0L; num7 < num5; num7++)
				{
					InFifo[num7] = InFifo[num7 + num2];
				}
			}
		}

		public void ShortTimeFourierTransform(float[] fftBuffer, long fftFrameSize, long sign)
		{
			for (long num = 2L; num < 2 * fftFrameSize - 2; num += 2)
			{
				long num2 = 2L;
				long num3 = 0L;
				while (num2 < 2 * fftFrameSize)
				{
					if ((num & num2) != 0L)
					{
						num3++;
					}
					num3 <<= 1;
					num2 <<= 1;
				}
				if (num < num3)
				{
					float num4 = fftBuffer[num];
					fftBuffer[num] = fftBuffer[num3];
					fftBuffer[num3] = num4;
					num4 = fftBuffer[num + 1];
					fftBuffer[num + 1] = fftBuffer[num3 + 1];
					fftBuffer[num3 + 1] = num4;
				}
			}
			long num5 = (long)(System.Math.Log(fftFrameSize) / System.Math.Log(2.0) + 0.5);
			long num6 = 0L;
			long num7 = 2L;
			for (; num6 < num5; num6++)
			{
				num7 <<= 1;
				long num8 = num7 >> 1;
				float num9 = 1f;
				float num10 = 0f;
				float num11 = MathF.PI / (float)(num8 >> 1);
				float num12 = (float)System.Math.Cos(num11);
				float num13 = (float)((double)sign * System.Math.Sin(num11));
				for (long num3 = 0L; num3 < num8; num3 += 2)
				{
					float num14;
					for (long num = num3; num < 2 * fftFrameSize; num += num7)
					{
						num14 = fftBuffer[num + num8] * num9 - fftBuffer[num + num8 + 1] * num10;
						float num15 = fftBuffer[num + num8] * num10 + fftBuffer[num + num8 + 1] * num9;
						fftBuffer[num + num8] = fftBuffer[num] - num14;
						fftBuffer[num + num8 + 1] = fftBuffer[num + 1] - num15;
						fftBuffer[num] += num14;
						fftBuffer[num + 1] += num15;
					}
					num14 = num9 * num12 - num10 * num13;
					num10 = num9 * num13 + num10 * num12;
					num9 = num14;
				}
			}
		}
	}
	public class GTRecorder : Recorder, ITickSystemPost
	{
		public bool AllowPitchAdjustment;

		public float PitchAdjustment = 1f;

		public bool AllowVolumeAdjustment;

		public float VolumeAdjustment = 1f;

		public float DebugEchoLength = 5f;

		private GTMicWrapper _micWrapper;

		private Coroutine _testEchoCoroutine;

		public bool PostTickRunning { get; set; }

		private void OnEnable()
		{
			TickSystem<object>.AddPostTickCallback(this);
		}

		private void OnDisable()
		{
			TickSystem<object>.RemovePostTickCallback(this);
		}

		protected override MicWrapper CreateMicWrapper(string micDev, int samplingRateInt, VoiceLogger logger)
		{
			_micWrapper = new GTMicWrapper(micDev, samplingRateInt, AllowPitchAdjustment, PitchAdjustment, AllowVolumeAdjustment, VolumeAdjustment, logger);
			return _micWrapper;
		}

		private IEnumerator DoTestEcho()
		{
			base.DebugEchoMode = true;
			yield return new WaitForSeconds(DebugEchoLength);
			base.DebugEchoMode = false;
			yield return null;
			_testEchoCoroutine = null;
		}

		public void PostTick()
		{
			if (_micWrapper != null)
			{
				_micWrapper.UpdateWrapper(AllowPitchAdjustment, PitchAdjustment, AllowVolumeAdjustment, VolumeAdjustment);
			}
		}
	}
	public class GTSpeaker : Speaker
	{
		[FormerlySerializedAs("UseExternalAudioSources")]
		public bool BroadcastExternal;

		[SerializeField]
		private AudioSource[] _externalAudioSources;

		private List<IAudioOut<float>> _externalAudioOutputs;

		private int _frequency;

		private int _channels;

		private int _frameSamplesPerChannel;

		private bool _initializedExternalAudioSources;

		private bool _audioOutputStarted;

		public void Start()
		{
			LoudSpeakerNetwork componentInChildren = base.transform.root.GetComponentInChildren<LoudSpeakerNetwork>();
			if (componentInChildren != null)
			{
				AddExternalAudioSources(componentInChildren.SpeakerSources);
			}
		}

		public void AddExternalAudioSources(AudioSource[] audioSources)
		{
			if (!_initializedExternalAudioSources)
			{
				_externalAudioSources = audioSources;
				InitializeExternalAudioSources();
				if (_audioOutputStarted)
				{
					ExternalAudioOutputStart(_frequency, _channels, _frameSamplesPerChannel);
				}
			}
		}

		protected override void Initialize()
		{
			if (base.IsInitialized)
			{
				if (base.Logger.IsWarningEnabled)
				{
					base.Logger.LogWarning("Already initialized.");
				}
			}
			else
			{
				base.Initialize();
			}
		}

		private void InitializeExternalAudioSources()
		{
			_initializedExternalAudioSources = true;
			_externalAudioOutputs = new List<IAudioOut<float>>();
			AudioOutDelayControl.PlayDelayConfig pdc = new AudioOutDelayControl.PlayDelayConfig
			{
				Low = playbackDelaySettings.MinDelaySoft,
				High = playbackDelaySettings.MaxDelaySoft,
				Max = playbackDelaySettings.MaxDelayHard
			};
			AudioSource[] externalAudioSources = _externalAudioSources;
			foreach (AudioSource source in externalAudioSources)
			{
				_externalAudioOutputs.Add(GetAudioOutFactoryFromSource(source, pdc)());
			}
		}

		private Func<IAudioOut<float>> GetAudioOutFactoryFromSource(AudioSource source, AudioOutDelayControl.PlayDelayConfig pdc)
		{
			return () => new UnityAudioOut(source, pdc, base.Logger, string.Empty, base.Logger.IsDebugEnabled);
		}

		protected override void OnAudioFrame(FrameOut<float> frame)
		{
			base.OnAudioFrame(frame);
			if (!BroadcastExternal)
			{
				return;
			}
			foreach (IAudioOut<float> externalAudioOutput in _externalAudioOutputs)
			{
				externalAudioOutput.Push(frame.Buf);
				if (frame.EndOfStream)
				{
					externalAudioOutput.Flush();
				}
			}
		}

		protected override void AudioOutputStart(int frequency, int channels, int frameSamplesPerChannel)
		{
			_audioOutputStarted = true;
			_frequency = frequency;
			_channels = channels;
			_frameSamplesPerChannel = frameSamplesPerChannel;
			base.AudioOutputStart(frequency, channels, frameSamplesPerChannel);
			ExternalAudioOutputStart(frequency, channels, frameSamplesPerChannel);
		}

		private void ExternalAudioOutputStart(int frequency, int channels, int frameSamplesPerChannel)
		{
			if (_externalAudioOutputs == null)
			{
				return;
			}
			foreach (IAudioOut<float> externalAudioOutput in _externalAudioOutputs)
			{
				if (!externalAudioOutput.IsPlaying)
				{
					externalAudioOutput.Start(frequency, channels, frameSamplesPerChannel);
					externalAudioOutput.ToggleAudioSource(toggle: false);
				}
			}
		}

		protected override void AudioOutputStop()
		{
			_audioOutputStarted = false;
			if (_externalAudioOutputs != null)
			{
				foreach (IAudioOut<float> externalAudioOutput in _externalAudioOutputs)
				{
					externalAudioOutput.Stop();
				}
			}
			base.AudioOutputStop();
		}

		protected override void AudioOutputService()
		{
			base.AudioOutputService();
			if (_externalAudioOutputs == null)
			{
				return;
			}
			foreach (IAudioOut<float> externalAudioOutput in _externalAudioOutputs)
			{
				if (!externalAudioOutput.IsPlaying)
				{
					externalAudioOutput.Service();
				}
			}
		}

		public void ToggleAudioSource(bool toggle)
		{
			if (_externalAudioOutputs == null)
			{
				return;
			}
			foreach (IAudioOut<float> externalAudioOutput in _externalAudioOutputs)
			{
				externalAudioOutput.ToggleAudioSource(toggle);
			}
		}
	}
	public class LoudSpeakerActivator : MonoBehaviour
	{
		public float PitchAdjustment = 1f;

		public float VolumeAdjustment = 2.5f;

		public bool IsBroadcasting;

		[SerializeField]
		private LoudSpeakerNetwork _network;

		[SerializeField]
		private GTRecorder _recorder;

		private bool _isLocal;

		private VRRig _nonlocalRig;

		private void Awake()
		{
			_isLocal = IsParentedToLocalRig();
			if (!_isLocal)
			{
				_nonlocalRig = base.transform.root.GetComponent<VRRig>();
			}
		}

		private bool IsParentedToLocalRig()
		{
			if (VRRigCache.Instance.localRig == null)
			{
				return false;
			}
			Transform parent = base.transform.parent;
			while (parent != null)
			{
				if (parent == VRRigCache.Instance.localRig.transform)
				{
					return true;
				}
				parent = parent.parent;
			}
			return false;
		}

		public void SetRecorder(GTRecorder recorder)
		{
			_recorder = recorder;
		}

		public void StartLocalBroadcast()
		{
			if (!_isLocal)
			{
				if (_network != null && _nonlocalRig != null)
				{
					_network.StartBroadcastSpeakerOutput(_nonlocalRig);
				}
			}
			else if (!IsBroadcasting)
			{
				if (_recorder == null && NetworkSystem.Instance.LocalRecorder != null)
				{
					SetRecorder((GTRecorder)NetworkSystem.Instance.LocalRecorder);
				}
				if (_recorder != null && _network != null)
				{
					IsBroadcasting = true;
					_recorder.AllowPitchAdjustment = true;
					_recorder.PitchAdjustment = PitchAdjustment;
					_recorder.AllowVolumeAdjustment = true;
					_recorder.VolumeAdjustment = VolumeAdjustment;
					_network.StartBroadcastSpeakerOutput(VRRigCache.Instance.localRig.Rig);
				}
			}
		}

		public void StopLocalBroadcast()
		{
			if (!_isLocal)
			{
				if (_network != null && _nonlocalRig != null)
				{
					_network.StopBroadcastSpeakerOutput(_nonlocalRig);
				}
			}
			else if (IsBroadcasting)
			{
				if (_recorder == null && NetworkSystem.Instance.LocalRecorder != null)
				{
					SetRecorder((GTRecorder)NetworkSystem.Instance.LocalRecorder);
				}
				if (_recorder != null && _network != null)
				{
					IsBroadcasting = false;
					_recorder.AllowPitchAdjustment = false;
					_recorder.PitchAdjustment = 1f;
					_recorder.AllowVolumeAdjustment = false;
					_recorder.VolumeAdjustment = 1f;
					_network.StopBroadcastSpeakerOutput(VRRigCache.Instance.localRig.Rig);
				}
			}
		}
	}
	public class LoudSpeakerNetwork : MonoBehaviour
	{
		[SerializeField]
		private AudioSource[] _speakerSources;

		[SerializeField]
		private List<Speaker> _currentSpeakers;

		[SerializeField]
		private int _currentSpeakerActor = -1;

		public bool ReparentLocalSpeaker = true;

		private RigContainer _rigContainer;

		private GTRecorder _localRecorder;

		public AudioSource[] SpeakerSources => _speakerSources;

		private void Awake()
		{
			if (_speakerSources == null || _speakerSources.Length == 0)
			{
				_speakerSources = base.transform.GetComponentsInChildren<AudioSource>();
			}
			_currentSpeakers = new List<Speaker>();
		}

		private void Start()
		{
			if (GetParentRigContainer(out var rigContainer) && rigContainer.Voice != null)
			{
				GTSpeaker gTSpeaker = (GTSpeaker)rigContainer.Voice.SpeakerInUse;
				if (gTSpeaker != null)
				{
					gTSpeaker.AddExternalAudioSources(_speakerSources);
				}
			}
		}

		private bool GetParentRigContainer(out RigContainer rigContainer)
		{
			if (_rigContainer == null)
			{
				_rigContainer = base.transform.GetComponentInParent<RigContainer>();
			}
			rigContainer = _rigContainer;
			return rigContainer != null;
		}

		private void OnEnable()
		{
			if (GetParentRigContainer(out var rigContainer))
			{
				rigContainer.AddLoudSpeakerNetwork(this);
			}
		}

		private void OnDisable()
		{
			if (GetParentRigContainer(out var rigContainer))
			{
				rigContainer.RemoveLoudSpeakerNetwork(this);
			}
		}

		public void AddSpeaker(Speaker speaker)
		{
			if (!_currentSpeakers.Contains(speaker))
			{
				_currentSpeakers.Add(speaker);
			}
		}

		public void RemoveSpeaker(Speaker speaker)
		{
			_currentSpeakers.Remove(speaker);
		}

		public void StartBroadcastSpeakerOutput(VRRig player)
		{
			GorillaTagger.Instance.rigSerializer.BroadcastLoudSpeakerNetwork(toggleBroadcast: true, player.OwningNetPlayer.ActorNumber);
		}

		public void BroadcastLoudSpeakerNetwork(int actorNumber, bool isLocal = false)
		{
			if (isLocal)
			{
				if (_localRecorder == null)
				{
					_localRecorder = (GTRecorder)NetworkSystem.Instance.LocalRecorder;
				}
				if (_localRecorder != null)
				{
					_localRecorder.DebugEchoMode = true;
					if (ReparentLocalSpeaker)
					{
						Transform obj = _rigContainer.Voice.SpeakerInUse.transform;
						obj.transform.SetParent(base.transform, worldPositionStays: false);
						obj.localPosition = UnityEngine.Vector3.zero;
					}
				}
				return;
			}
			using (List<Speaker>.Enumerator enumerator = _currentSpeakers.GetEnumerator())
			{
				if (enumerator.MoveNext())
				{
					GTSpeaker obj2 = (GTSpeaker)enumerator.Current;
					obj2.ToggleAudioSource(toggle: true);
					obj2.BroadcastExternal = true;
					if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(actorNumber), out var playerRig))
					{
						Transform obj3 = playerRig.Voice.SpeakerInUse.transform;
						obj3.SetParent(base.transform, worldPositionStays: false);
						obj3.localPosition = UnityEngine.Vector3.zero;
					}
				}
			}
			_currentSpeakerActor = actorNumber;
		}

		public void StopBroadcastSpeakerOutput(VRRig player)
		{
			GorillaTagger.Instance.rigSerializer.BroadcastLoudSpeakerNetwork(toggleBroadcast: false, player.OwningNetPlayer.ActorNumber);
		}

		public void StopBroadcastLoudSpeakerNetwork(int actorNumber, bool isLocal = false)
		{
			if (isLocal)
			{
				if (_localRecorder == null)
				{
					_localRecorder = (GTRecorder)NetworkSystem.Instance.LocalRecorder;
				}
				if (_localRecorder != null)
				{
					_localRecorder.DebugEchoMode = false;
					if (ReparentLocalSpeaker && GetParentRigContainer(out var rigContainer))
					{
						Transform obj = rigContainer.Voice.SpeakerInUse.transform;
						obj.SetParent(rigContainer.SpeakerHead, worldPositionStays: false);
						obj.localPosition = UnityEngine.Vector3.zero;
					}
				}
			}
			else
			{
				if (actorNumber != _currentSpeakerActor)
				{
					return;
				}
				using (List<Speaker>.Enumerator enumerator = _currentSpeakers.GetEnumerator())
				{
					if (enumerator.MoveNext())
					{
						GTSpeaker obj2 = (GTSpeaker)enumerator.Current;
						obj2.ToggleAudioSource(toggle: false);
						obj2.BroadcastExternal = false;
						if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(actorNumber), out var playerRig))
						{
							Transform obj3 = playerRig.Voice.SpeakerInUse.transform;
							obj3.SetParent(playerRig.SpeakerHead, worldPositionStays: false);
							obj3.localPosition = UnityEngine.Vector3.zero;
						}
					}
				}
				_currentSpeakerActor = -1;
			}
		}
	}
	public class LoudSpeakerTrigger : MonoBehaviour
	{
		public float PitchAdjustment = 1f;

		[SerializeField]
		private LoudSpeakerNetwork _network;

		[SerializeField]
		private GTRecorder _recorder;

		public void SetRecorder(GTRecorder recorder)
		{
			_recorder = recorder;
		}

		public void OnPlayerEnter(VRRig player)
		{
			if (_recorder != null && _network != null)
			{
				_recorder.AllowPitchAdjustment = true;
				_recorder.PitchAdjustment = PitchAdjustment;
				_network.StartBroadcastSpeakerOutput(player);
			}
		}

		public void OnPlayerExit(VRRig player)
		{
			if (_recorder != null && _network != null)
			{
				_recorder.AllowPitchAdjustment = false;
				_recorder.PitchAdjustment = 1f;
				_network.StopBroadcastSpeakerOutput(player);
			}
		}
	}
	public class LoudSpeakerVolume : MonoBehaviour
	{
		[SerializeField]
		private LoudSpeakerTrigger _trigger;

		public void OnTriggerEnter(Collider other)
		{
			if (!other.CompareTag("GorillaPlayer"))
			{
				return;
			}
			VRRig component = other.attachedRigidbody.GetComponent<VRRig>();
			if (component != null && component.creator != null)
			{
				if (component.creator.UserId == NetworkSystem.Instance.LocalPlayer.UserId)
				{
					_trigger.OnPlayerEnter(component);
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("LoudSpeakerNetworkVolume :: OnTriggerEnter no colliding rig found!");
			}
		}

		public void OnTriggerExit(Collider other)
		{
			VRRig component = other.attachedRigidbody.GetComponent<VRRig>();
			if (component != null && component.creator != null)
			{
				if (component.creator.UserId == NetworkSystem.Instance.LocalPlayer.UserId)
				{
					_trigger.OnPlayerExit(component);
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("LoudSpeakerNetworkVolume :: OnTriggerExit no colliding rig found!");
			}
		}
	}
	public class PlayerSpeakerSwapper : MonoBehaviour
	{
		[SerializeField]
		private UnityEngine.Behaviour _lowPassFilter;

		private void OnEnable()
		{
			NetworkSystem.Instance.OnPlayerJoined += new Action<NetPlayer>(OnPlayerCountChanged);
			NetworkSystem.Instance.OnPlayerLeft += new Action<NetPlayer>(OnPlayerCountChanged);
			OnPlayerCountChanged(null);
		}

		private void OnDisable()
		{
			NetworkSystem.Instance.OnPlayerJoined -= new Action<NetPlayer>(OnPlayerCountChanged);
			NetworkSystem.Instance.OnPlayerLeft -= new Action<NetPlayer>(OnPlayerCountChanged);
		}

		private void OnPlayerCountChanged(NetPlayer _)
		{
			int num = NetworkSystem.Instance.AllNetPlayers.Length;
			_lowPassFilter.enabled = num >= 10;
		}
	}
