namespace GorillaTag.Cosmetics
{
	[ExecuteAlways]
	public class ScubaWatchWearable : MonoBehaviour
	{
		public bool onLeftHand;

		[Tooltip("The transform that will be rotated to indicate the current depth.")]
		public Transform dialNeedle;

		[Tooltip("If your rotation is not zeroed out then click the Auto button to use the current rotation as 0.")]
		public UnityEngine.Quaternion initialDialRotation;

		[Tooltip("The range of depth values that the dial will rotate between.")]
		public UnityEngine.Vector2 depthRange = new UnityEngine.Vector2(0f, 20f);

		[Tooltip("The range of rotation values that the dial will rotate between.")]
		public UnityEngine.Vector2 dialRotationRange = new UnityEngine.Vector2(0f, 360f);

		[Tooltip("The axis that the dial will rotate around.")]
		public UnityEngine.Vector3 dialRotationAxis = UnityEngine.Vector3.right;

		[Tooltip("The current depth of the player.")]
		[DebugOption]
		private float currentDepth;

		protected void Update()
		{
			GTPlayer instance = GTPlayer.Instance;
			if (onLeftHand)
			{
				if (instance.LeftHandWaterVolume != null)
				{
					currentDepth = Mathf.Max(0f - instance.LeftHandWaterSurface.surfacePlane.GetDistanceToPoint(instance.LastLeftHandPosition), 0f);
				}
				else
				{
					currentDepth = 0f;
				}
			}
			else if (instance.RightHandWaterVolume != null)
			{
				currentDepth = Mathf.Max(0f - instance.RightHandWaterSurface.surfacePlane.GetDistanceToPoint(instance.LastRightHandPosition), 0f);
			}
			else
			{
				currentDepth = 0f;
			}
			float t = (currentDepth - depthRange.x) / (depthRange.y - depthRange.x);
			float angle = Mathf.Lerp(dialRotationRange.x, dialRotationRange.y, t);
			dialNeedle.localRotation = initialDialRotation * UnityEngine.Quaternion.AngleAxis(angle, dialRotationAxis);
		}
	}
	public class CompassNeedleRotator : MonoBehaviour
	{
		private const float smoothTime = 0.005f;

		private float currentVelocity;

		protected void OnEnable()
		{
			currentVelocity = 0f;
			base.transform.localRotation = UnityEngine.Quaternion.identity;
		}

		protected void LateUpdate()
		{
			Transform obj = base.transform;
			UnityEngine.Vector3 forward = obj.forward;
			forward.y = 0f;
			forward.Normalize();
			obj.Rotate(angle: Mathf.SmoothDamp(UnityEngine.Vector3.SignedAngle(forward, UnityEngine.Vector3.forward, UnityEngine.Vector3.up), 0f, ref currentVelocity, 0.005f), axis: obj.up, relativeTo: Space.World);
		}
	}
	public class DiceHoldable : TransferrableObject
	{
		[SerializeField]
		private DicePhysics dicePhysics;

		private RubberDuckEvents _events;

		internal override void OnEnable()
		{
			base.OnEnable();
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnDiceEvent);
			}
		}

		internal override void OnDisable()
		{
			base.OnDisable();
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnDiceEvent);
				UnityEngine.Object.Destroy(_events);
				_events = null;
			}
		}

		private void OnDiceEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			MonkeAgent.IncrementRPCCall(info, "OnDiceEvent");
			if (sender == target && info.senderID == ownerRig.creator.ActorNumber)
			{
				if ((bool)args[0])
				{
					UnityEngine.Vector3 v = base.transform.position;
					UnityEngine.Vector3 v2 = base.transform.forward;
					v.SetValueSafe((UnityEngine.Vector3)args[1]);
					v2.SetValueSafe((UnityEngine.Vector3)args[2]);
					float playerScale = ((float)args[3]).ClampSafe(0.01f, 1f);
					int landingSide = Mathf.Clamp((int)args[4], 1, 20);
					double finite = ((double)args[5]).GetFinite();
					ThrowDiceLocal(v, v2, playerScale, landingSide, finite);
				}
				else
				{
					dicePhysics.EndThrow();
				}
			}
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			if (dicePhysics.enabled)
			{
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					object[] args = new object[1] { false };
					_events.Activate.RaiseOthers(args);
				}
				base.transform.position = dicePhysics.transform.position;
				base.transform.rotation = dicePhysics.transform.rotation;
				dicePhysics.EndThrow();
				if (grabbingHand == EquipmentInteractor.instance.leftHand && currentState == PositionState.OnLeftArm)
				{
					canAutoGrabLeft = false;
					interpState = InterpolateState.None;
					currentState = PositionState.InLeftHand;
				}
				else if (grabbingHand == EquipmentInteractor.instance.rightHand && currentState == PositionState.OnRightArm)
				{
					canAutoGrabRight = false;
					interpState = InterpolateState.None;
					currentState = PositionState.InLeftHand;
				}
			}
			base.OnGrab(pointGrabbed, grabbingHand);
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			if (zoneReleased == null)
			{
				UnityEngine.Vector3 position = base.transform.position;
				bool isLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
				UnityEngine.Vector3 averageVelocity = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeftHand).GetAverageVelocity(worldSpace: true);
				int randomSide = dicePhysics.GetRandomSide();
				double num = (PhotonNetwork.InRoom ? PhotonNetwork.Time : (-1.0));
				float scale = GTPlayer.Instance.scale;
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					object[] args = new object[6] { true, position, averageVelocity, scale, randomSide, num };
					_events.Activate.RaiseOthers(args);
				}
				ThrowDiceLocal(position, averageVelocity, scale, randomSide, num);
			}
			return true;
		}

		private void ThrowDiceLocal(UnityEngine.Vector3 startPosition, UnityEngine.Vector3 throwVelocity, float playerScale, int landingSide, double startTime)
		{
			dicePhysics.StartThrow(this, startPosition, throwVelocity, playerScale, landingSide, startTime);
		}
	}
