			UnityEngine.Quaternion.AngleAxis(72f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(38.833332f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(36f, -UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, -UnityEngine.Vector3.forward) * UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(216f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(0f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(180f, -UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, -UnityEngine.Vector3.forward) * UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(324f, -UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, -UnityEngine.Vector3.forward) * UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(144f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(108f, -UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(38.833332f, -UnityEngine.Vector3.forward) * UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(72f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(288f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(77.66666f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(0f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(38.833332f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(252f, -UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(38.833332f, -UnityEngine.Vector3.forward) * UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(216f, UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(38.833332f, UnityEngine.Vector3.forward) * -UnityEngine.Vector3.up,
			UnityEngine.Quaternion.AngleAxis(36f, -UnityEngine.Vector3.up) * UnityEngine.Quaternion.AngleAxis(38.833332f, -UnityEngine.Vector3.forward) * UnityEngine.Vector3.up
		};

		private UnityEngine.Vector3[] d6SideDirections = new UnityEngine.Vector3[6]
		{
			new UnityEngine.Vector3(0f, -1f, 0f),
			new UnityEngine.Vector3(-1f, 0f, 0f),
			new UnityEngine.Vector3(0f, 0f, -1f),
			new UnityEngine.Vector3(0f, 0f, 1f),
			new UnityEngine.Vector3(1f, 0f, 0f),
			new UnityEngine.Vector3(0f, 1f, 0f)
		};

		public int GetRandomSide()
		{
			if (diceType != DiceType.D6)
			{
				_ = 1;
				if (forceLandingSide)
				{
					return Mathf.Clamp(forcedLandingSide, 1, 20);
				}
				if (CheckCosmeticRollOverride(out var rollSide))
				{
					return Mathf.Clamp(rollSide, 1, 20);
				}
				return UnityEngine.Random.Range(1, 21);
			}
			if (forceLandingSide)
			{
				return Mathf.Clamp(forcedLandingSide, 1, 6);
			}
			if (CheckCosmeticRollOverride(out var rollSide2))
			{
				return Mathf.Clamp(rollSide2, 1, 6);
			}
			return UnityEngine.Random.Range(1, 7);
		}

		public UnityEngine.Vector3 GetSideDirection(int side)
		{
			if (diceType != DiceType.D6)
			{
				_ = 1;
				int num = Mathf.Clamp(side - 1, 0, 19);
				return d20SideDirections[num];
			}
			int num2 = Mathf.Clamp(side - 1, 0, 5);
			return d6SideDirections[num2];
		}

		public void StartThrow(DiceHoldable holdable, UnityEngine.Vector3 startPosition, UnityEngine.Vector3 velocity, float playerScale, int side, double startTime)
		{
			holdableParent = holdable;
			base.transform.parent = null;
			base.transform.position = startPosition;
			base.transform.localScale = UnityEngine.Vector3.one * playerScale;
			rb.isKinematic = false;
			rb.useGravity = true;
			rb.linearVelocity = velocity;
			if (!allowPickupFromGround && interactionPoint != null)
			{
				interactionPoint.enabled = false;
			}
			throwStartTime = ((startTime > 0.0) ? startTime : ((double)Time.time));
			throwSettledTime = -1.0;
			scale = playerScale;
			landingSide = Mathf.Clamp(side, 1, 20);
			prevVelocity = UnityEngine.Vector3.zero;
			velocity = UnityEngine.Vector3.zero;
			base.enabled = true;
		}

		public void EndThrow()
		{
			rb.isKinematic = true;
			rb.linearVelocity = UnityEngine.Vector3.zero;
			if (holdableParent != null)
			{
				base.transform.parent = holdableParent.transform;
			}
			base.transform.localPosition = UnityEngine.Vector3.zero;
			base.transform.localRotation = UnityEngine.Quaternion.identity;
			base.transform.localScale = UnityEngine.Vector3.one;
			scale = 1f;
			throwStartTime = -1.0;
			if (interactionPoint != null)
			{
				interactionPoint.enabled = true;
			}
			onRollFinished.Invoke();
			base.enabled = false;
		}

		private void FixedUpdate()
		{
			double num = (PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time));
			float num2 = (float)(num - throwStartTime);
			if (Physics.Raycast(base.transform.position, UnityEngine.Vector3.down, out var hitInfo, 0.1f * scale, surfaceLayers.value, QueryTriggerInteraction.Ignore))
			{
				UnityEngine.Vector3 normal = hitInfo.normal;
				UnityEngine.Vector3 sideDirection = GetSideDirection(landingSide);
				UnityEngine.Vector3 vector = base.transform.rotation * sideDirection;
				UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(vector, normal).normalized;
				float num3 = UnityEngine.Vector3.SignedAngle(vector, normal, normalized);
				float num4 = Mathf.Sign(num3) * angleDeltaVsStrengthCurve.Evaluate(Mathf.Clamp01(Mathf.Abs(num3) / 180f));
				float num5 = landingTimeVsStrengthCurve.Evaluate(Mathf.Clamp01(num2 / landingTime));
				float magnitude = rb.linearVelocity.magnitude;
				float num6 = Mathf.Clamp01(1f - Mathf.Min(magnitude, 1f));
				float num7 = Mathf.Max(num5, num6);
				UnityEngine.Vector3 torque = strength * (num7 * num4 * normalized) - damping * rb.angularVelocity;
				rb.AddTorque(torque, ForceMode.Acceleration);
				if (!rb.isKinematic && magnitude < 0.01f && num3 < 2f)
				{
					rb.isKinematic = true;
					throwSettledTime = num;
					InvokeLandingEffects(landingSide);
				}
				else if (!rb.isKinematic && num2 > landingTime)
				{
					rb.isKinematic = true;
					throwSettledTime = num;
					base.transform.rotation = UnityEngine.Quaternion.FromToRotation(vector, normal) * base.transform.rotation;
					InvokeLandingEffects(landingSide);
				}
			}
			if (num2 > landingTime + postLandingTime || (rb.isKinematic && (float)(num - throwSettledTime) > postLandingTime))
			{
				EndThrow();
			}
			prevVelocity = velocity;
			velocity = rb.linearVelocity;
		}

		private void OnCollisionEnter(UnityEngine.Collision collision)
		{
			float magnitude = collision.impulse.magnitude;
			if (magnitude > 0.001f)
			{
				UnityEngine.Vector3 vector = UnityEngine.Vector3.Reflect(prevVelocity, collision.impulse / magnitude);
				rb.linearVelocity = vector * bounceAmplification;
			}
		}

		private void InvokeLandingEffects(int side)
		{
			if (diceType != DiceType.D6)
			{
				_ = 1;
				switch (side)
				{
				case 20:
					onBestRoll.Invoke();
					break;
				case 1:
					onWorstRoll.Invoke();
					break;
				}
			}
			else
			{
				switch (side)
				{
				case 6:
					onBestRoll.Invoke();
					break;
				case 1:
					onWorstRoll.Invoke();
					break;
				}
			}
		}

		private bool CheckCosmeticRollOverride(out int rollSide)
		{
			if (cosmeticRollOverrides.Length != 0)
			{
				if (cachedLocalRig == null)
				{
					if (PhotonNetwork.InRoom && VRRigCache.Instance.TryGetVrrig(PhotonNetwork.LocalPlayer, out var playerRig) && playerRig.Rig != null)
					{
						cachedLocalRig = playerRig.Rig;
					}
					else
					{
						cachedLocalRig = GorillaTagger.Instance.offlineVRRig;
					}
				}
				if (cachedLocalRig != null)
				{
					int num = -1;
					for (int i = 0; i < cosmeticRollOverrides.Length; i++)
					{
						if (cosmeticRollOverrides[i].cosmeticName != null && cachedLocalRig.cosmeticSet != null && cachedLocalRig.cosmeticSet.HasItem(cosmeticRollOverrides[i].cosmeticName) && (!cosmeticRollOverrides[i].requireHolding || (EquipmentInteractor.instance.leftHandHeldEquipment != null && EquipmentInteractor.instance.leftHandHeldEquipment.name == cosmeticRollOverrides[i].cosmeticName) || (EquipmentInteractor.instance.rightHandHeldEquipment != null && EquipmentInteractor.instance.rightHandHeldEquipment.name == cosmeticRollOverrides[i].cosmeticName)) && cosmeticRollOverrides[i].landingSide > num)
						{
							num = cosmeticRollOverrides[i].landingSide;
						}
					}
					if (num > 0)
					{
						rollSide = num;
						return true;
					}
				}
			}
			rollSide = 0;
			return false;
		}
	}
	public class RCBlimp : RCVehicle
	{
		[SerializeField]
		private float maxAscendSpeed = 6f;

		[SerializeField]
		private float ascendAccelTime = 3f;

		[SerializeField]
		private float gravityCompensation = 0.9f;

		[SerializeField]
		private float crashedGravityCompensation = 0.5f;

		[SerializeField]
		private float maxTurnRate = 90f;

		[SerializeField]
		private float turnAccelTime = 0.75f;

		[SerializeField]
		private float maxHorizontalSpeed = 6f;

		[SerializeField]
		private float horizontalAccelTime = 2f;

		[SerializeField]
		private float maxHorizontalTiltAngle = 45f;

		[SerializeField]
		private float horizontalTiltTime = 2f;

		[SerializeField]
		private UnityEngine.Vector2 motorSoundVolumeMinMax = new UnityEngine.Vector2(0.1f, 0.8f);

		[SerializeField]
		private float deflateSoundVolume = 0.1f;

		[SerializeField]
		private Collider crashCollider;

		[SerializeField]
		private Transform leftPropeller;

		[SerializeField]
		private Transform rightPropeller;

		[SerializeField]
		private SkinnedMeshRenderer blimpMesh;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private AudioClip motorSound;

		[SerializeField]
		private AudioClip deflateSound;

		private float turnRate;

		private float turnAngle;

		private float tiltAngle;

		private float ascendAccel;

		private float turnAccel;

		private float tiltAccel;

		private float horizontalAccel;

		private float leftPropellerAngle;

		private float rightPropellerAngle;

		private float leftPropellerSpinRate;

		private float rightPropellerSpinRate;

		private float blimpDeflateBlendWeight;

		private float deflateRate = Mathf.Exp(1f);

		private const float propellerIdleAcc = 1f;

		private const float propellerIdleSpinRate = 0.6f;

		private const float propellerMaxAcc = 6.6666665f;

		private const float propellerMaxSpinRate = 5f;

		private float motorVolumeRampTime = 1f;

		private float motorLevel;

		protected override void AuthorityBeginDocked()
		{
			base.AuthorityBeginDocked();
			turnRate = 0f;
			turnAngle = UnityEngine.Vector3.SignedAngle(UnityEngine.Vector3.forward, UnityEngine.Vector3.ProjectOnPlane(base.transform.forward, UnityEngine.Vector3.up), UnityEngine.Vector3.up);
			motorLevel = 0f;
			if (connectedRemote == null)
			{
				base.gameObject.SetActive(value: false);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			ascendAccel = maxAscendSpeed / ascendAccelTime;
			turnAccel = maxTurnRate / turnAccelTime;
			horizontalAccel = maxHorizontalSpeed / horizontalAccelTime;
			tiltAccel = maxHorizontalTiltAngle / horizontalTiltTime;
		}

		protected override void OnDisable()
		{
			base.OnDisable();
			audioSource.GTStop();
		}

		protected override void AuthorityUpdate(float dt)
		{
			base.AuthorityUpdate(dt);
			motorLevel = 0f;
			if (localState == State.Mobilized)
			{
				motorLevel = Mathf.Max(Mathf.Max(Mathf.Abs(activeInput.joystick.y), Mathf.Abs(activeInput.joystick.x)), activeInput.trigger);
			}
			if (networkSync != null)
			{
				networkSync.syncedState.dataA = (byte)Mathf.Clamp(Mathf.FloorToInt(motorLevel * 255f), 0, 255);
			}
		}

		protected override void RemoteUpdate(float dt)
		{
			base.RemoteUpdate(dt);
			if (localState == State.Mobilized && networkSync != null)
			{
				motorLevel = Mathf.Clamp01((float)(int)networkSync.syncedState.dataA / 255f);
			}
		}

		protected override void SharedUpdate(float dt)
		{
			base.SharedUpdate(dt);
			switch (localState)
			{
			case State.Crashed:
				if (localStatePrev != State.Crashed)
				{
					audioSource.GTStop();
					audioSource.clip = null;
					audioSource.loop = false;
					audioSource.volume = deflateSoundVolume;
					if (deflateSound != null)
					{
						audioSource.GTPlayOneShot(deflateSound);
					}
					leftPropellerSpinRate = 0f;
					rightPropellerSpinRate = 0f;
					leftPropellerAngle = 0f;
					rightPropellerAngle = 0f;
					leftPropeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(0f, 0f, -90f));
					rightPropeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(0f, 0f, 90f));
					crashCollider.enabled = true;
				}
				blimpDeflateBlendWeight = Mathf.Lerp(1f, blimpDeflateBlendWeight, Mathf.Exp((0f - deflateRate) * dt));
				blimpMesh.SetBlendShapeWeight(0, blimpDeflateBlendWeight * 100f);
				break;
			case State.DockedLeft:
			case State.DockedRight:
				if (localStatePrev != State.DockedLeft && localStatePrev != State.DockedRight)
				{
					audioSource.GTStop();
					blimpDeflateBlendWeight = 0f;
					blimpMesh.SetBlendShapeWeight(0, 0f);
					crashCollider.enabled = false;
				}
				leftPropellerSpinRate = Mathf.MoveTowards(leftPropellerSpinRate, 0.6f, 6.6666665f * dt);
				rightPropellerSpinRate = Mathf.MoveTowards(rightPropellerSpinRate, 0.6f, 6.6666665f * dt);
				leftPropellerAngle += leftPropellerSpinRate * 360f * dt;
				rightPropellerAngle += rightPropellerSpinRate * 360f * dt;
				leftPropeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(leftPropellerAngle, 0f, -90f));
				rightPropeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(rightPropellerAngle, 0f, 90f));
				break;
			case State.Mobilized:
			{
				if (localStatePrev != State.Mobilized)
				{
					audioSource.loop = true;
					audioSource.clip = motorSound;
					audioSource.volume = 0f;
					audioSource.GTPlay();
					blimpDeflateBlendWeight = 0f;
					blimpMesh.SetBlendShapeWeight(0, 0f);
					crashCollider.enabled = false;
				}
				float target = Mathf.Lerp(motorSoundVolumeMinMax.x, motorSoundVolumeMinMax.y, motorLevel);
				audioSource.volume = Mathf.MoveTowards(audioSource.volume, target, motorSoundVolumeMinMax.y / motorVolumeRampTime * dt);
				blimpDeflateBlendWeight = 0f;
				float num = activeInput.joystick.y * 5f;
				float num2 = activeInput.joystick.x * 5f;
				float target2 = Mathf.Clamp(num2 + num + 0.6f, -5f, 5f);
				float target3 = Mathf.Clamp(0f - num2 + num + 0.6f, -5f, 5f);
				leftPropellerSpinRate = Mathf.MoveTowards(leftPropellerSpinRate, target2, 6.6666665f * dt);
				rightPropellerSpinRate = Mathf.MoveTowards(rightPropellerSpinRate, target3, 6.6666665f * dt);
				leftPropellerAngle += leftPropellerSpinRate * 360f * dt;
				rightPropellerAngle += rightPropellerSpinRate * 360f * dt;
				leftPropeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(leftPropellerAngle, 0f, -90f));
				rightPropeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(rightPropellerAngle, 0f, 90f));
				break;
			}
			case State.Disabled:
				break;
			}
		}

		private void FixedUpdate()
		{
			if (!base.HasLocalAuthority)
			{
				return;
			}
			float fixedDeltaTime = Time.fixedDeltaTime;
			float x = base.transform.lossyScale.x;
			if (localState == State.Mobilized)
			{
				float num = maxAscendSpeed * x;
				float num2 = maxHorizontalSpeed * x;
				float num3 = ascendAccel * x;
				UnityEngine.Vector3 linearVelocity = rb.linearVelocity;
				UnityEngine.Vector3 normalized = new UnityEngine.Vector3(base.transform.forward.x, 0f, base.transform.forward.z).normalized;
				turnAngle = UnityEngine.Vector3.SignedAngle(UnityEngine.Vector3.forward, normalized, UnityEngine.Vector3.up);
				tiltAngle = UnityEngine.Vector3.SignedAngle(normalized, base.transform.forward, base.transform.right);
				float target = activeInput.joystick.x * maxTurnRate;
				turnRate = Mathf.MoveTowards(turnRate, target, turnAccel * fixedDeltaTime);
				turnAngle += turnRate * fixedDeltaTime;
				float value = UnityEngine.Vector3.Dot(normalized, linearVelocity);
				float t = Mathf.InverseLerp(0f - num2, num2, value);
				float target2 = Mathf.Lerp(0f - maxHorizontalTiltAngle, maxHorizontalTiltAngle, t);
				tiltAngle = Mathf.MoveTowards(tiltAngle, target2, tiltAccel * fixedDeltaTime);
				base.transform.rotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(tiltAngle, turnAngle, 0f));
				UnityEngine.Vector3 vector = new UnityEngine.Vector3(linearVelocity.x, 0f, linearVelocity.z);
				UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Lerp(normalized * activeInput.joystick.y * num2, vector, Mathf.Exp((0f - horizontalAccelTime) * fixedDeltaTime));
				rb.AddForce((vector2 - vector) * rb.mass, ForceMode.Impulse);
				float num4 = activeInput.trigger * num;
				if (num4 > 0.01f && linearVelocity.y < num4)
				{
					rb.AddForce(UnityEngine.Vector3.up * num3 * rb.mass, ForceMode.Force);
				}
				if (rb.useGravity)
				{
					RCVehicle.AddScaledGravityCompensationForce(rb, x, gravityCompensation);
				}
			}
			else if (localState == State.Crashed && rb.useGravity)
			{
				RCVehicle.AddScaledGravityCompensationForce(rb, x, crashedGravityCompensation);
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			bool flag = other.gameObject.IsOnLayer(UnityLayer.GorillaThrowable);
			bool flag2 = other.gameObject.IsOnLayer(UnityLayer.GorillaHand);
			if (!other.isTrigger && base.HasLocalAuthority && localState == State.Mobilized)
			{
				AuthorityBeginCrash();
			}
			else
			{
				if (!(flag || flag2) || localState != State.Mobilized)
				{
					return;
				}
				UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
				if (flag2)
				{
					GorillaHandClimber component = other.gameObject.GetComponent<GorillaHandClimber>();
					if (component != null)
					{
						vector = GTPlayer.Instance.GetHandVelocityTracker(component.xrNode == XRNode.LeftHand).GetAverageVelocity(worldSpace: true);
					}
				}
				else if (other.attachedRigidbody != null)
				{
					vector = other.attachedRigidbody.linearVelocity;
				}
				if (flag || vector.sqrMagnitude > 0.01f)
				{
					if (base.HasLocalAuthority)
					{
						AuthorityApplyImpact(vector, flag);
					}
					else if (networkSync != null)
					{
						networkSync.photonView.RPC("HitRCVehicleRPC", RpcTarget.Others, vector, flag);
					}
				}
			}
		}
	}
	public class RCCosmeticNetworkSync : MonoBehaviourPun, IPunObservable, IPunInstantiateMagicCallback
	{
		public struct SyncedState
		{
			public byte state;

			public UnityEngine.Vector3 position;

			public UnityEngine.Quaternion rotation;

			public byte dataA;

			public byte dataB;

			public byte dataC;
		}

		public SyncedState syncedState;

		private RCRemoteHoldable rcRemote;

		public void OnPhotonInstantiate(PhotonMessageInfo info)
		{
			if (info.Sender == null)
			{
				DestroyThis();
				return;
			}
			if (info.Sender != base.photonView.Owner || base.photonView.IsRoomView)
			{
				MonkeAgent.instance.SendReport("spoofed rc instantiate", info.Sender.UserId, info.Sender.NickName);
				DestroyThis();
				return;
			}
			object[] instantiationData = info.photonView.InstantiationData;
			if (instantiationData == null || instantiationData.Length < 1 || !(instantiationData[0] is int num))
			{
				DestroyThis();
				return;
			}
			if (VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender.ActorNumber), out var playerRig) && num > -1 && num < playerRig.Rig.myBodyDockPositions.allObjects.Length)
			{
				rcRemote = playerRig.Rig.myBodyDockPositions.allObjects[num] as RCRemoteHoldable;
				if (rcRemote != null)
				{
					rcRemote.networkSync = this;
					rcRemote.WakeUpRemoteVehicle();
				}
			}
			if (rcRemote == null)
			{
				DestroyThis();
			}
		}

		public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
		{
			if (info.Sender != base.photonView.Owner)
			{
				return;
			}
			if (stream.IsWriting)
			{
				stream.SendNext(syncedState.state);
				stream.SendNext(syncedState.position);
				stream.SendNext((int)BitPackUtils.PackRotation(syncedState.rotation));
				stream.SendNext(syncedState.dataA);
				stream.SendNext(syncedState.dataB);
				stream.SendNext(syncedState.dataC);
			}
			else if (stream.IsReading)
			{
				byte state = syncedState.state;
				syncedState.state = (byte)stream.ReceiveNext();
				syncedState.position.SetValueSafe((UnityEngine.Vector3)stream.ReceiveNext());
				syncedState.rotation.SetValueSafe(BitPackUtils.UnpackRotation((uint)(int)stream.ReceiveNext()));
				syncedState.dataA = (byte)stream.ReceiveNext();
				syncedState.dataB = (byte)stream.ReceiveNext();
				syncedState.dataC = (byte)stream.ReceiveNext();
				if (state != syncedState.state && rcRemote != null && rcRemote.Vehicle != null && !rcRemote.Vehicle.enabled)
				{
					rcRemote.WakeUpRemoteVehicle();
				}
			}
		}

		[PunRPC]
		public void HitRCVehicleRPC(UnityEngine.Vector3 hitVelocity, bool isProjectile, PhotonMessageInfo info)
		{
			MonkeAgent.IncrementRPCCall(info, "HitRCVehicleRPC");
			if (!hitVelocity.IsValid(10000f))
			{
				MonkeAgent.instance.SendReport("nan rc hit", info.Sender.UserId, info.Sender.NickName);
			}
			else if (rcRemote != null && rcRemote.Vehicle != null)
			{
				rcRemote.Vehicle.AuthorityApplyImpact(hitVelocity, isProjectile);
			}
		}

		private void DestroyThis()
		{
			if (base.photonView.IsMine)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
			else
			{
				base.gameObject.SetActive(value: false);
			}
		}
	}
	public class RCDragon : RCVehicle
	{
		[SerializeField]
		private float maxAscendSpeed = 6f;

		[SerializeField]
		private float ascendAccelTime = 3f;

		[SerializeField]
		private float ascendWhileFlyingAccelBoost;

		[SerializeField]
		private float gravityCompensation = 0.9f;

		[SerializeField]
		private float crashedGravityCompensation = 0.5f;

		[SerializeField]
		private float maxTurnRate = 90f;

		[SerializeField]
		private float turnAccelTime = 0.75f;

		[SerializeField]
		private float maxHorizontalSpeed = 6f;

		[SerializeField]
		private float horizontalAccelTime = 2f;

		[SerializeField]
		private float maxHorizontalTiltAngle = 45f;

		[SerializeField]
		private float horizontalTiltTime = 2f;

		[SerializeField]
		private UnityEngine.Vector2 motorSoundVolumeMinMax = new UnityEngine.Vector2(0.1f, 0.8f);

		[SerializeField]
		private float crashSoundVolume = 0.1f;

		[SerializeField]
		private float breathFireVolume = 0.5f;

		[SerializeField]
		private float wingFlapVolume = 0.1f;

		[SerializeField]
		private Animation animation;

		[SerializeField]
		private string wingFlapAnimName;

		[SerializeField]
		private float wingFlapAnimSpeed = 1f;

		[SerializeField]
		private string dockedAnimName;

		[SerializeField]
		private string idleAnimName;

		[SerializeField]
		private string crashAnimName;

		[SerializeField]
		private float crashAnimSpeed = 1f;

		[SerializeField]
		private string mouthClosedAnimName;

		[SerializeField]
		private string mouthBreathFireAnimName;

		private bool shouldFlap;

		private bool isFlapping;

		private float nextFlapEventAnimTime;

		[SerializeField]
		private float flapAnimEventTime = 0.25f;

		[SerializeField]
		private GameObject fireBreath;

		[SerializeField]
		private float fireBreathDuration;

		private float fireBreathTimeRemaining;

		[SerializeField]
		private Collider crashCollider;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private List<AudioClip> breathFireSound;

		[SerializeField]
		private List<AudioClip> wingFlapSound;

		[SerializeField]
		private AudioClip crashSound;

		private float turnRate;

		private float turnAngle;

		private float tiltAngle;

		private float ascendAccel;

		private float turnAccel;

		private float tiltAccel;

		private float horizontalAccel;

		private float motorVolumeRampTime = 1f;

		private float motorLevel;

		protected override void AuthorityBeginDocked()
		{
			base.AuthorityBeginDocked();
			turnRate = 0f;
			turnAngle = UnityEngine.Vector3.SignedAngle(UnityEngine.Vector3.forward, UnityEngine.Vector3.ProjectOnPlane(base.transform.forward, UnityEngine.Vector3.up), UnityEngine.Vector3.up);
			motorLevel = 0f;
			if (connectedRemote == null)
			{
				base.gameObject.SetActive(value: false);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			ascendAccel = maxAscendSpeed / ascendAccelTime;
			turnAccel = maxTurnRate / turnAccelTime;
			horizontalAccel = maxHorizontalSpeed / horizontalAccelTime;
			tiltAccel = maxHorizontalTiltAngle / horizontalTiltTime;
			shouldFlap = false;
			isFlapping = false;
			StopBreathFire();
			if (animation != null)
			{
				animation[wingFlapAnimName].speed = wingFlapAnimSpeed;
				animation[crashAnimName].speed = crashAnimSpeed;
				animation[mouthClosedAnimName].layer = 1;
				animation[mouthBreathFireAnimName].layer = 1;
			}
			nextFlapEventAnimTime = flapAnimEventTime;
		}

		protected override void OnDisable()
		{
			base.OnDisable();
			audioSource.GTStop();
		}

		public void StartBreathFire()
		{
			if (!string.IsNullOrEmpty(mouthBreathFireAnimName))
			{
				animation.CrossFade(mouthBreathFireAnimName, 0.1f);
			}
			if (fireBreath != null)
			{
				fireBreath.SetActive(value: true);
			}
			PlayRandomSound(breathFireSound, breathFireVolume);
			fireBreathTimeRemaining = fireBreathDuration;
		}

		public void StopBreathFire()
		{
			if (!string.IsNullOrEmpty(mouthClosedAnimName))
			{
				animation.CrossFade(mouthClosedAnimName, 0.1f);
			}
			if (fireBreath != null)
			{
				fireBreath.SetActive(value: false);
			}
			fireBreathTimeRemaining = -1f;
		}

		public bool IsBreathingFire()
		{
			return fireBreathTimeRemaining >= 0f;
		}

		private void PlayRandomSound(List<AudioClip> clips, float volume)
		{
			if (clips != null && clips.Count != 0)
			{
				PlaySound(clips[UnityEngine.Random.Range(0, clips.Count)], volume);
			}
		}

		private void PlaySound(AudioClip clip, float volume)
		{
			if (!(audioSource == null) && !(clip == null))
			{
				audioSource.GTStop();
				audioSource.clip = null;
				audioSource.loop = false;
				audioSource.volume = volume;
				audioSource.GTPlayOneShot(clip);
			}
		}

		protected override void AuthorityUpdate(float dt)
		{
			base.AuthorityUpdate(dt);
			motorLevel = 0f;
			if (localState == State.Mobilized)
			{
				motorLevel = Mathf.Max(Mathf.Max(Mathf.Abs(activeInput.joystick.y), Mathf.Abs(activeInput.joystick.x)), activeInput.trigger);
				if (!IsBreathingFire() && activeInput.buttons > 0)
				{
					StartBreathFire();
				}
			}
			if (networkSync != null)
			{
				networkSync.syncedState.dataA = (byte)Mathf.Clamp(Mathf.FloorToInt(motorLevel * 255f), 0, 255);
				networkSync.syncedState.dataB = activeInput.buttons;
				networkSync.syncedState.dataC = (byte)(shouldFlap ? 1u : 0u);
			}
		}

		protected override void RemoteUpdate(float dt)
		{
			base.RemoteUpdate(dt);
			if (localState == State.Mobilized && networkSync != null)
			{
				motorLevel = Mathf.Clamp01((float)(int)networkSync.syncedState.dataA / 255f);
				if (!IsBreathingFire() && networkSync.syncedState.dataB > 0)
				{
					StartBreathFire();
				}
				shouldFlap = networkSync.syncedState.dataC > 0;
			}
		}

		protected override void SharedUpdate(float dt)
		{
			base.SharedUpdate(dt);
			switch (localState)
			{
			case State.Crashed:
				if (localStatePrev != State.Crashed)
				{
					PlaySound(crashSound, crashSoundVolume);
					if (crashCollider != null)
					{
						crashCollider.enabled = true;
					}
					if (animation != null)
					{
						animation.CrossFade(crashAnimName, 0.05f);
					}
					if (IsBreathingFire())
					{
						StopBreathFire();
					}
				}
				break;
			case State.DockedLeft:
			case State.DockedRight:
				if (localStatePrev != State.DockedLeft && localStatePrev != State.DockedRight)
				{
					audioSource.GTStop();
					if (crashCollider != null)
					{
						crashCollider.enabled = false;
					}
					if (animation != null)
					{
						animation.Play(dockedAnimName);
					}
					if (IsBreathingFire())
					{
						StopBreathFire();
					}
				}
				break;
			case State.Mobilized:
			{
				if (localStatePrev != State.Mobilized && crashCollider != null)
				{
					crashCollider.enabled = false;
				}
				if (animation != null)
				{
					if (!isFlapping && shouldFlap)
					{
						animation.CrossFade(wingFlapAnimName, 0.1f);
						nextFlapEventAnimTime = flapAnimEventTime;
					}
					else if (isFlapping && !shouldFlap)
					{
						animation.CrossFade(idleAnimName, 0.15f);
					}
					isFlapping = shouldFlap;
					if (isFlapping && !IsBreathingFire())
					{
						AnimationState animationState = animation[wingFlapAnimName];
						if (animationState.normalizedTime * animationState.length > nextFlapEventAnimTime)
						{
							PlayRandomSound(wingFlapSound, wingFlapVolume);
							nextFlapEventAnimTime = (Mathf.Floor(animationState.normalizedTime) + 1f) * animationState.length + flapAnimEventTime;
						}
					}
				}
				GTTime.TimeAsDouble();
				if (IsBreathingFire())
				{
					fireBreathTimeRemaining -= dt;
					if (fireBreathTimeRemaining <= 0f)
					{
						StopBreathFire();
					}
				}
				float target = Mathf.Lerp(motorSoundVolumeMinMax.x, motorSoundVolumeMinMax.y, motorLevel);
				audioSource.volume = Mathf.MoveTowards(audioSource.volume, target, motorSoundVolumeMinMax.y / motorVolumeRampTime * dt);
				break;
			}
			case State.Disabled:
				break;
			}
		}

		private void FixedUpdate()
		{
			if (!base.HasLocalAuthority)
			{
				return;
			}
			float x = base.transform.lossyScale.x;
			float fixedDeltaTime = Time.fixedDeltaTime;
			shouldFlap = false;
			if (localState == State.Mobilized)
			{
				float num = maxAscendSpeed * x;
				float num2 = maxHorizontalSpeed * x;
				float num3 = ascendAccel * x;
				float num4 = ascendWhileFlyingAccelBoost * x;
				float num5 = 0.5f * x;
				float num6 = 45f;
				UnityEngine.Vector3 linearVelocity = rb.linearVelocity;
				UnityEngine.Vector3 normalized = new UnityEngine.Vector3(base.transform.forward.x, 0f, base.transform.forward.z).normalized;
				turnAngle = UnityEngine.Vector3.SignedAngle(UnityEngine.Vector3.forward, normalized, UnityEngine.Vector3.up);
				tiltAngle = UnityEngine.Vector3.SignedAngle(normalized, base.transform.forward, base.transform.right);
				float target = activeInput.joystick.x * maxTurnRate;
				turnRate = Mathf.MoveTowards(turnRate, target, turnAccel * fixedDeltaTime);
				turnAngle += turnRate * fixedDeltaTime;
				float num7 = UnityEngine.Vector3.Dot(normalized, linearVelocity);
				float t = Mathf.InverseLerp(0f - num2, num2, num7);
				float target2 = Mathf.Lerp(0f - maxHorizontalTiltAngle, maxHorizontalTiltAngle, t);
				tiltAngle = Mathf.MoveTowards(tiltAngle, target2, tiltAccel * fixedDeltaTime);
				base.transform.rotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(tiltAngle, turnAngle, 0f));
				UnityEngine.Vector3 vector = new UnityEngine.Vector3(linearVelocity.x, 0f, linearVelocity.z);
				UnityEngine.Vector3 vector2 = UnityEngine.Vector3.Lerp(normalized * activeInput.joystick.y * num2, vector, Mathf.Exp((0f - horizontalAccelTime) * fixedDeltaTime));
				rb.AddForce((vector2 - vector) * rb.mass, ForceMode.Impulse);
				float num8 = activeInput.trigger * num;
				if (num8 > 0.01f && linearVelocity.y < num8)
				{
					rb.AddForce(UnityEngine.Vector3.up * num3 * rb.mass, ForceMode.Force);
				}
				bool flag = Mathf.Abs(num7) > num5;
				bool flag2 = Mathf.Abs(turnRate) > num6;
				if (flag || flag2)
				{
					rb.AddForce(UnityEngine.Vector3.up * num4 * rb.mass, ForceMode.Force);
				}
				shouldFlap = num8 > 0.01f || flag || flag2;
				if (rb.useGravity)
				{
					RCVehicle.AddScaledGravityCompensationForce(rb, x, gravityCompensation);
				}
			}
			else if (localState == State.Crashed && rb.useGravity)
			{
				RCVehicle.AddScaledGravityCompensationForce(rb, x, crashedGravityCompensation);
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			bool flag = other.gameObject.IsOnLayer(UnityLayer.GorillaThrowable);
			bool flag2 = other.gameObject.IsOnLayer(UnityLayer.GorillaHand);
			if (!other.isTrigger && base.HasLocalAuthority && localState == State.Mobilized)
			{
				AuthorityBeginCrash();
			}
			else
			{
				if (!(flag || flag2) || localState != State.Mobilized)
				{
					return;
				}
				UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
				if (flag2)
				{
					GorillaHandClimber component = other.gameObject.GetComponent<GorillaHandClimber>();
					if (component != null)
					{
						vector = GTPlayer.Instance.GetHandVelocityTracker(component.xrNode == XRNode.LeftHand).GetAverageVelocity(worldSpace: true);
					}
				}
				else if (other.attachedRigidbody != null)
				{
					vector = other.attachedRigidbody.linearVelocity;
				}
				if (flag || vector.sqrMagnitude > 0.01f)
				{
					if (base.HasLocalAuthority)
					{
						AuthorityApplyImpact(vector, flag);
					}
					else if (networkSync != null)
					{
						networkSync.photonView.RPC("HitRCVehicleRPC", RpcTarget.Others, vector, flag);
					}
				}
			}
		}
	}
	public class RCHelicopter : RCVehicle
	{
		[SerializeField]
		private float maxAscendSpeed = 6f;

		[SerializeField]
		private float ascendAccelTime = 3f;

		[SerializeField]
		private float gravityCompensation = 0.5f;

		[SerializeField]
		private float maxTurnRate = 90f;

		[SerializeField]
		private float turnAccelTime = 0.75f;

		[SerializeField]
		private float maxHorizontalSpeed = 6f;

		[SerializeField]
		private float horizontalAccelTime = 2f;

		[SerializeField]
		private float maxHorizontalTiltAngle = 45f;

		[SerializeField]
		private UnityEngine.Vector2 mainPropellerSpinRateRange = new UnityEngine.Vector2(3f, 15f);

		[SerializeField]
		private float backPropellerSpinRate = 5f;

		[SerializeField]
		private Transform verticalPropeller;

		[SerializeField]
		private Transform turnPropeller;

		private UnityEngine.Quaternion verticalPropellerBaseRotation;

		private UnityEngine.Quaternion turnPropellerBaseRotation;

		private float turnRate;

		private float ascendAccel;

		private float turnAccel;

		private float horizontalAccel;

		protected override void AuthorityBeginDocked()
		{
			base.AuthorityBeginDocked();
			turnRate = 0f;
			verticalPropeller.localRotation = verticalPropellerBaseRotation;
			turnPropeller.localRotation = turnPropellerBaseRotation;
			if (connectedRemote == null)
			{
				base.gameObject.SetActive(value: false);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			verticalPropellerBaseRotation = verticalPropeller.localRotation;
			turnPropellerBaseRotation = turnPropeller.localRotation;
			ascendAccel = maxAscendSpeed / ascendAccelTime;
			turnAccel = maxTurnRate / turnAccelTime;
			horizontalAccel = maxHorizontalSpeed / horizontalAccelTime;
		}

		protected override void SharedUpdate(float dt)
		{
			if (localState == State.Mobilized)
			{
				float num = Mathf.Lerp(mainPropellerSpinRateRange.x, mainPropellerSpinRateRange.y, activeInput.trigger);
				verticalPropeller.Rotate(new UnityEngine.Vector3(0f, num * dt, 0f), Space.Self);
				turnPropeller.Rotate(new UnityEngine.Vector3(activeInput.joystick.x * backPropellerSpinRate * dt, 0f, 0f), Space.Self);
			}
		}

		private void FixedUpdate()
		{
			if (base.HasLocalAuthority && localState == State.Mobilized)
			{
				float fixedDeltaTime = Time.fixedDeltaTime;
				UnityEngine.Vector3 linearVelocity = rb.linearVelocity;
				_ = linearVelocity.magnitude;
				float target = activeInput.joystick.x * maxTurnRate;
				turnRate = Mathf.MoveTowards(turnRate, target, turnAccel * fixedDeltaTime);
				float num = activeInput.joystick.y * maxHorizontalSpeed;
				float x = Mathf.Sign(activeInput.joystick.y) * Mathf.Lerp(0f, maxHorizontalTiltAngle, Mathf.Abs(activeInput.joystick.y));
				base.transform.rotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(x, turnAccel, 0f));
				float num2 = Mathf.Abs(num);
				UnityEngine.Vector3 normalized = UnityEngine.Vector3.ProjectOnPlane(base.transform.forward, UnityEngine.Vector3.up).normalized;
				float num3 = UnityEngine.Vector3.Dot(normalized, linearVelocity);
				if (num2 > 0.01f && ((num > 0f && num > num3) || (num < 0f && num < num3)))
				{
					rb.AddForce(normalized * Mathf.Sign(num) * horizontalAccel * fixedDeltaTime * rb.mass, ForceMode.Force);
				}
				float num4 = activeInput.trigger * maxAscendSpeed;
				if (num4 > 0.01f && linearVelocity.y < num4)
				{
					rb.AddForce(UnityEngine.Vector3.up * ascendAccel * rb.mass, ForceMode.Force);
				}
				if (rb.useGravity)
				{
					rb.AddForce(-Physics.gravity * gravityCompensation * rb.mass, ForceMode.Force);
				}
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			if (!other.isTrigger && base.HasLocalAuthority && localState == State.Mobilized)
			{
				AuthorityBeginCrash();
			}
		}
	}
