		[SerializeField]
		private Transform rightAileronUpper;

		[SerializeField]
		private Transform rightAileronLower;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private AudioClip motorSound;

		[SerializeField]
		private AudioClip crashSound;

		[SerializeField]
		private UnityEngine.Vector2 motorSoundVolumeMinMax = new UnityEngine.Vector2(0.02f, 0.1f);

		[SerializeField]
		private float crashSoundVolume = 0.12f;

		private float motorVolumeRampTime = 1f;

		private float propellerAngle;

		private float propellerSpinRate;

		private const float propellerIdleAcc = 1f;

		private const float propellerIdleSpinRate = 0.6f;

		private const float propellerMaxAcc = 6.6666665f;

		private const float propellerMaxSpinRate = 5f;

		public float initialSpeed = 3f;

		private float pitch;

		private float pitchVel;

		private UnityEngine.Vector2 pitchAccelMinMax;

		private float roll;

		private float rollVel;

		private float rollAccel;

		private float thrustAccel;

		private float motorLevel;

		private float leftAileronLevel;

		private float rightAileronLevel;

		private UnityEngine.Vector2 aileronAngularRange = new UnityEngine.Vector2(-30f, 45f);

		private float aileronAngularAcc = 120f;

		private float leftAileronAngle;

		private float rightAileronAngle;

		protected override void Awake()
		{
			base.Awake();
			pitchAccelMinMax.x = pitchVelocityTargetMinMax.x / pitchVelocityRampTimeMinMax.x;
			pitchAccelMinMax.y = pitchVelocityTargetMinMax.y / pitchVelocityRampTimeMinMax.y;
			rollAccel = rollVelocityTarget / rollVelocityRampTime;
			thrustAccel = thrustVelocityTarget / thrustAccelTime;
		}

		protected override void AuthorityBeginMobilization()
		{
			base.AuthorityBeginMobilization();
			float x = base.transform.lossyScale.x;
			rb.linearVelocity = base.transform.forward * initialSpeed * x;
		}

		protected override void AuthorityUpdate(float dt)
		{
			base.AuthorityUpdate(dt);
			motorLevel = 0f;
			if (localState == State.Mobilized)
			{
				motorLevel = activeInput.trigger;
			}
			leftAileronLevel = 0f;
			rightAileronLevel = 0f;
			float magnitude = activeInput.joystick.magnitude;
			if (magnitude > 0.01f)
			{
				float num = Mathf.Abs(activeInput.joystick.x) / magnitude;
				float num2 = Mathf.Abs(activeInput.joystick.y) / magnitude;
				leftAileronLevel = Mathf.Clamp(num * activeInput.joystick.x + num2 * (0f - activeInput.joystick.y), -1f, 1f);
				rightAileronLevel = Mathf.Clamp(num * activeInput.joystick.x + num2 * activeInput.joystick.y, -1f, 1f);
			}
			if (networkSync != null)
			{
				networkSync.syncedState.dataA = (byte)Mathf.Clamp(Mathf.FloorToInt(motorLevel * 255f), 0, 255);
				networkSync.syncedState.dataB = (byte)Mathf.Clamp(Mathf.FloorToInt(leftAileronLevel * 126f), -126, 126);
				networkSync.syncedState.dataC = (byte)Mathf.Clamp(Mathf.FloorToInt(rightAileronLevel * 126f), -126, 126);
			}
		}

		protected override void RemoteUpdate(float dt)
		{
			base.RemoteUpdate(dt);
			if (networkSync != null)
			{
				motorLevel = Mathf.Clamp01((float)(int)networkSync.syncedState.dataA / 255f);
				leftAileronLevel = Mathf.Clamp((float)(int)networkSync.syncedState.dataB / 126f, -1f, 1f);
				rightAileronLevel = Mathf.Clamp((float)(int)networkSync.syncedState.dataC / 126f, -1f, 1f);
			}
		}

		protected override void SharedUpdate(float dt)
		{
			base.SharedUpdate(dt);
			switch (localState)
			{
			case State.Crashed:
				if (localStatePrev != State.Crashed)
				{
					audioSource.GTStop();
					audioSource.clip = null;
					audioSource.loop = false;
					audioSource.volume = crashSoundVolume;
					if (crashSound != null)
					{
						audioSource.GTPlayOneShot(crashSound);
					}
				}
				propellerSpinRate = Mathf.MoveTowards(propellerSpinRate, 0f, 13.333333f * dt);
				propellerAngle += propellerSpinRate * 360f * dt;
				propeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(0f, 0f, propellerAngle));
				break;
			case State.DockedLeft:
			case State.DockedRight:
				propellerSpinRate = Mathf.MoveTowards(propellerSpinRate, 0.6f, 6.6666665f * dt);
				propellerAngle += propellerSpinRate * 360f * dt;
				propeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(0f, 0f, propellerAngle));
				break;
			case State.Mobilized:
			{
				if (localStatePrev != State.Mobilized)
				{
					audioSource.loop = true;
					audioSource.clip = motorSound;
					audioSource.volume = 0f;
					audioSource.GTPlay();
				}
				float target = Mathf.Lerp(motorSoundVolumeMinMax.x, motorSoundVolumeMinMax.y, motorLevel);
				audioSource.volume = Mathf.MoveTowards(audioSource.volume, target, motorSoundVolumeMinMax.y / motorVolumeRampTime * dt);
				propellerSpinRate = Mathf.MoveTowards(propellerSpinRate, 5f, 6.6666665f * dt);
				propellerAngle += propellerSpinRate * 360f * dt;
				propeller.transform.localRotation = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(0f, 0f, propellerAngle));
				break;
			}
			}
			float target2 = Mathf.Lerp(aileronAngularRange.x, aileronAngularRange.y, Mathf.InverseLerp(-1f, 1f, leftAileronLevel));
			float target3 = Mathf.Lerp(aileronAngularRange.x, aileronAngularRange.y, Mathf.InverseLerp(-1f, 1f, rightAileronLevel));
			leftAileronAngle = Mathf.MoveTowards(leftAileronAngle, target2, aileronAngularAcc * Time.deltaTime);
			rightAileronAngle = Mathf.MoveTowards(rightAileronAngle, target3, aileronAngularAcc * Time.deltaTime);
			UnityEngine.Quaternion localRotation = UnityEngine.Quaternion.Euler(0f, -90f, 90f + leftAileronAngle);
			UnityEngine.Quaternion localRotation2 = UnityEngine.Quaternion.Euler(0f, 90f, -90f + rightAileronAngle);
			leftAileronLower.localRotation = localRotation;
			leftAileronUpper.localRotation = localRotation;
			rightAileronLower.localRotation = localRotation2;
			rightAileronUpper.localRotation = localRotation2;
		}

		private void FixedUpdate()
		{
			if (base.HasLocalAuthority && localState == State.Mobilized)
			{
				float x = base.transform.lossyScale.x;
				float num = thrustVelocityTarget * x;
				float num2 = thrustAccel * x;
				float fixedDeltaTime = Time.fixedDeltaTime;
				pitch = NormalizeAngle180(pitch);
				roll = NormalizeAngle180(roll);
				float num3 = pitch;
				float num4 = roll;
				if (activeInput.joystick.y >= 0f)
				{
					float target = activeInput.joystick.y * pitchVelocityTargetMinMax.y;
					pitchVel = Mathf.MoveTowards(pitchVel, target, pitchAccelMinMax.y * fixedDeltaTime);
					pitch += pitchVel * fixedDeltaTime;
				}
				else
				{
					float target2 = (0f - activeInput.joystick.y) * pitchVelocityTargetMinMax.x;
					pitchVel = Mathf.MoveTowards(pitchVel, target2, pitchAccelMinMax.x * fixedDeltaTime);
					pitch += pitchVel * fixedDeltaTime;
				}
				float target3 = (0f - activeInput.joystick.x) * rollVelocityTarget;
				rollVel = Mathf.MoveTowards(rollVel, target3, rollAccel * fixedDeltaTime);
				roll += rollVel * fixedDeltaTime;
				UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Euler(new UnityEngine.Vector3(pitch - num3, 0f, roll - num4));
				base.transform.rotation = base.transform.rotation * quaternion2;
				rb.angularVelocity = UnityEngine.Vector3.zero;
				UnityEngine.Vector3 linearVelocity = rb.linearVelocity;
				float magnitude = linearVelocity.magnitude;
				float num5 = Mathf.Max(UnityEngine.Vector3.Dot(base.transform.forward, linearVelocity), 0f);
				float num6 = activeInput.trigger * num;
				float num7 = 0.1f * x;
				if (num6 > num7 && num6 > num5)
				{
					float num8 = Mathf.MoveTowards(num5, num6, num2 * fixedDeltaTime);
					rb.AddForce(base.transform.forward * (num8 - num5) * rb.mass, ForceMode.Impulse);
				}
				float b = 0.01f * x;
				float time = UnityEngine.Vector3.Dot(linearVelocity / Mathf.Max(magnitude, b), base.transform.forward);
				float num9 = liftVsAttackCurve.Evaluate(time);
				float num10 = Mathf.Lerp(liftVsSpeedOutput.x, liftVsSpeedOutput.y, Mathf.InverseLerp(liftVsSpeedInput.x, liftVsSpeedInput.y, magnitude / x));
				float num11 = num9 * num10;
				UnityEngine.Vector3 vector = UnityEngine.Vector3.RotateTowards(linearVelocity, base.transform.forward * magnitude, pitchVelocityFollowRateAngle * (MathF.PI / 180f) * fixedDeltaTime, pitchVelocityFollowRateMagnitude * fixedDeltaTime) - linearVelocity;
				rb.AddForce(vector * num11 * rb.mass, ForceMode.Impulse);
				float time2 = UnityEngine.Vector3.Dot(linearVelocity.normalized, base.transform.up);
				float num12 = dragVsAttackCurve.Evaluate(time2);
				rb.AddForce(-linearVelocity * maxDrag * num12 * rb.mass, ForceMode.Force);
				if (rb.useGravity)
				{
					float gravityCompensation = Mathf.Lerp(gravityCompensationRange.x, gravityCompensationRange.y, Mathf.InverseLerp(0f, num, num5 / x));
					RCVehicle.AddScaledGravityCompensationForce(rb, x, gravityCompensation);
				}
			}
		}

		private void OnCollisionEnter(UnityEngine.Collision collision)
		{
			if (base.HasLocalAuthority && localState == State.Mobilized)
			{
				for (int i = 0; i < collision.contactCount; i++)
				{
					ContactPoint contact = collision.GetContact(i);
					if (!nonCrashColliders.Contains(contact.thisCollider))
					{
						AuthorityBeginCrash();
					}
				}
				return;
			}
			bool flag = collision.collider.gameObject.IsOnLayer(UnityLayer.GorillaThrowable);
			bool flag2 = collision.collider.gameObject.IsOnLayer(UnityLayer.GorillaHand);
			if (!(flag || flag2) || localState != State.Mobilized)
			{
				return;
			}
			UnityEngine.Vector3 vector = UnityEngine.Vector3.zero;
			if (flag2)
			{
				GorillaHandClimber component = collision.collider.gameObject.GetComponent<GorillaHandClimber>();
				if (component != null)
				{
					vector = GTPlayer.Instance.GetHandVelocityTracker(component.xrNode == XRNode.LeftHand).GetAverageVelocity(worldSpace: true);
				}
			}
			else if (collision.rigidbody != null)
			{
				vector = collision.rigidbody.linearVelocity;
			}
			if (flag || vector.sqrMagnitude > 0.01f)
			{
				if (base.HasLocalAuthority)
				{
					AuthorityApplyImpact(vector, flag);
				}
				else if (networkSync != null)
				{
					networkSync.photonView.RPC("HitRCVehicleRPC", RpcTarget.Others, vector, flag);
				}
			}
		}
	}
	public class RCRemoteHoldable : TransferrableObject, ISnapTurnOverride
	{
		public struct RCInput
		{
			public UnityEngine.Vector2 joystick;

			public float trigger;

			public byte buttons;
		}

		[SerializeField]
		private Transform joystickTransform;

		[SerializeField]
		private Transform triggerTransform;

		[SerializeField]
		private Transform buttonTransform;

		private RCVehicle targetVehicle;

		private float joystickLeanDegrees = 30f;

		private float triggerPullDegrees = 40f;

		private float buttonPressDepth = 0.005f;

		private UnityEngine.Quaternion initialJoystickRotation;

		private UnityEngine.Quaternion initialTriggerRotation;

		private UnityEngine.Quaternion initialButtonRotation;

		private UnityEngine.Vector3 initialButtonPosition;

		private bool currentlyHeld;

		private XRNode xrNode;

		private RCInput currentInput;

		[HideInInspector]
		public RCCosmeticNetworkSync networkSync;

		private string networkSyncPrefabName = "RCCosmeticNetworkSync";

		private RubberDuckEvents _events;

		private object[] emptyArgs = new object[0];

		public XRNode XRNode => xrNode;

		public RCVehicle Vehicle => targetVehicle;

		public bool TurnOverrideActive()
		{
			if (base.gameObject.activeSelf && currentlyHeld)
			{
				return xrNode == XRNode.RightHand;
			}
			return false;
		}

		protected override void Awake()
		{
			base.Awake();
			initialJoystickRotation = joystickTransform.localRotation;
			initialTriggerRotation = triggerTransform.localRotation;
			if (buttonTransform != null)
			{
				initialButtonRotation = buttonTransform.localRotation;
				initialButtonPosition = buttonTransform.localPosition;
			}
		}

		internal override void OnEnable()
		{
			base.OnEnable();
			if (!_TryFindRemoteVehicle())
			{
				base.gameObject.SetActive(value: false);
				return;
			}
			if (_events.IsNotNull() || base.gameObject.TryGetComponent<RubberDuckEvents>(out _events))
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
				}
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnStartConnectionEvent);
			}
			WakeUpRemoteVehicle();
		}

		internal override void OnDisable()
		{
			base.OnDisable();
			GorillaSnapTurn gorillaSnapTurn = ((GorillaTagger.Instance != null) ? GorillaTagger.Instance.GetComponent<GorillaSnapTurn>() : null);
			if (gorillaSnapTurn != null)
			{
				gorillaSnapTurn.UnsetTurningOverride(this);
			}
			if (networkSync != null && networkSync.photonView.IsMine)
			{
				PhotonNetwork.Destroy(networkSync.gameObject);
				networkSync = null;
			}
			if (_events.IsNotNull())
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnStartConnectionEvent);
				_events.Dispose();
				_events = null;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			GorillaSnapTurn gorillaSnapTurn = ((GorillaTagger.Instance != null) ? GorillaTagger.Instance.GetComponent<GorillaSnapTurn>() : null);
			if (gorillaSnapTurn != null)
			{
				gorillaSnapTurn.UnsetTurningOverride(this);
			}
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			base.OnGrab(pointGrabbed, grabbingHand);
			if (PhotonNetwork.InRoom && networkSync != null && networkSync.photonView.Owner == null)
			{
				PhotonNetwork.Destroy(networkSync.gameObject);
				networkSync = null;
			}
			if (networkSync == null && PhotonNetwork.InRoom)
			{
				object[] data = new object[1] { myIndex };
				GameObject gameObject = PhotonNetwork.Instantiate(networkSyncPrefabName, UnityEngine.Vector3.zero, UnityEngine.Quaternion.identity, 0, data);
				networkSync = ((gameObject != null) ? gameObject.GetComponent<RCCosmeticNetworkSync>() : null);
			}
			currentlyHeld = true;
			bool flag = grabbingHand == EquipmentInteractor.instance.rightHand;
			xrNode = (flag ? XRNode.RightHand : XRNode.LeftHand);
			GorillaSnapTurn component = GorillaTagger.Instance.GetComponent<GorillaSnapTurn>();
			if (flag)
			{
				component.SetTurningOverride(this);
			}
			else
			{
				component.UnsetTurningOverride(this);
			}
			if (targetVehicle != null)
			{
				targetVehicle.StartConnection(this, networkSync);
			}
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(emptyArgs);
			}
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			currentlyHeld = false;
			currentInput = default(RCInput);
			if (targetVehicle != null)
			{
				targetVehicle.EndConnection();
			}
			joystickTransform.localRotation = initialJoystickRotation;
			triggerTransform.localRotation = initialTriggerRotation;
			GorillaTagger.Instance.GetComponent<GorillaSnapTurn>().UnsetTurningOverride(this);
			return true;
		}

		private void Update()
		{
			if (currentlyHeld)
			{
				currentInput.joystick = ControllerInputPoller.Primary2DAxis(xrNode);
				currentInput.trigger = ControllerInputPoller.TriggerFloat(xrNode);
				currentInput.buttons = (byte)(ControllerInputPoller.PrimaryButtonPress(xrNode) ? 1u : 0u);
				if (targetVehicle != null)
				{
					targetVehicle.ApplyRemoteControlInput(currentInput);
				}
				joystickTransform.localRotation = initialJoystickRotation * UnityEngine.Quaternion.Euler(joystickLeanDegrees * currentInput.joystick.y, 0f, (0f - joystickLeanDegrees) * currentInput.joystick.x);
				triggerTransform.localRotation = initialTriggerRotation * UnityEngine.Quaternion.Euler(triggerPullDegrees * currentInput.trigger, 0f, 0f);
				if (buttonTransform != null)
				{
					buttonTransform.localPosition = initialButtonPosition + initialButtonRotation * new UnityEngine.Vector3(0f, 0f, (0f - buttonPressDepth) * (float)((currentInput.buttons > 0) ? 1 : 0));
				}
			}
		}

		public void OnStartConnectionEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender == target && info.senderID == ownerRig.creator.ActorNumber)
			{
				WakeUpRemoteVehicle();
			}
		}

		public void WakeUpRemoteVehicle()
		{
			if (networkSync != null && targetVehicle.IsNotNull() && !targetVehicle.HasLocalAuthority)
			{
				targetVehicle.WakeUpRemote(networkSync);
			}
		}

		private bool _TryFindRemoteVehicle()
		{
			if (targetVehicle != null)
			{
				return true;
			}
			VRRig componentInParent = GetComponentInParent<VRRig>(includeInactive: true);
			if (GTExt.IsNull(componentInParent))
			{
				UnityEngine.Debug.LogError("RCRemoteHoldable: unable to find parent vrrig");
				return false;
			}
			CosmeticItemInstance cosmeticItemInstance = componentInParent.cosmeticsObjectRegistry.Cosmetic(base.name);
			if (cosmeticItemInstance == null)
			{
				return false;
			}
			int instanceID = base.gameObject.GetInstanceID();
			if (_TryFindRemoteVehicle_InCosmeticInstanceArray(instanceID, cosmeticItemInstance.objects))
			{
				return true;
			}
			if (_TryFindRemoteVehicle_InCosmeticInstanceArray(instanceID, cosmeticItemInstance.leftObjects))
			{
				return true;
			}
			if (_TryFindRemoteVehicle_InCosmeticInstanceArray(instanceID, cosmeticItemInstance.rightObjects))
			{
				return true;
			}
			return false;
		}

		private bool _TryFindRemoteVehicle_InCosmeticInstanceArray(int thisGobjInstId, List<GameObject> gameObjects)
		{
			foreach (GameObject gameObject in gameObjects)
			{
				if (gameObject.GetInstanceID() != thisGobjInstId)
				{
					targetVehicle = gameObject.GetComponentInChildren<RCVehicle>(includeInactive: true);
					if ((object)targetVehicle != null)
					{
						return true;
					}
				}
			}
			return false;
		}
	}
	public class RCVehicle : MonoBehaviour, ISpawnable
	{
		protected enum State
		{
			Disabled,
			DockedLeft,
			DockedRight,
			Mobilized,
			Crashed
		}

		[SerializeField]
		private Transform leftDockParent;

		[SerializeField]
		private Transform rightDockParent;

		[SerializeField]
		private float maxRange = 100f;

		[SerializeField]
		private float maxDisconnectionTime = 10f;

		[SerializeField]
		private float crashRespawnDelay = 3f;

		[SerializeField]
		private bool crashOnHit;

		[SerializeField]
		private float crashOnHitSpeedThreshold = 5f;

		[SerializeField]
		[Range(0f, 1f)]
		private float hitVelocityTransfer = 0.5f;

		[SerializeField]
		[Range(0f, 1f)]
		private float projectileVelocityTransfer = 0.1f;

		[SerializeField]
		private float hitMaxHitSpeed = 4f;

		[SerializeField]
		[Range(0f, 1f)]
		private float joystickDeadzone = 0.1f;

		[Header("RCVehicle - Shared Event")]
		public UnityEvent OnHitImpact;

		protected State localState;

		protected State localStatePrev;

		protected float stateStartTime;

		protected RCRemoteHoldable connectedRemote;

		protected RCCosmeticNetworkSync networkSync;

		protected bool hasNetworkSync;

		protected RCRemoteHoldable.RCInput activeInput;

		protected Rigidbody rb;

		private bool waitingForTriggerRelease;

		private float disconnectionTime;

		private bool useLeftDock;

		private BoneOffset dockLeftOffset = new BoneOffset(GTHardCodedBones.EBone.forearm_L, new UnityEngine.Vector3(-0.062f, 0.283f, -0.136f), new UnityEngine.Vector3(275f, 0f, 25f));

		private BoneOffset dockRightOffset = new BoneOffset(GTHardCodedBones.EBone.forearm_R, new UnityEngine.Vector3(0.069f, 0.265f, -0.128f), new UnityEngine.Vector3(275f, 0f, 335f));

		private float networkSyncFollowRateExp = 2f;

		private Transform[] _vrRigBones;

		public bool HasLocalAuthority
		{
			get
			{
				if (PhotonNetwork.InRoom)
				{
					if (networkSync != null)
					{
						return networkSync.photonView.IsMine;
					}
					return false;
				}
				return true;
			}
		}

		bool ISpawnable.IsSpawned { get; set; }

		ECosmeticSelectSide ISpawnable.CosmeticSelectedSide { get; set; }

		public virtual void WakeUpRemote(RCCosmeticNetworkSync sync)
		{
			networkSync = sync;
			hasNetworkSync = sync != null;
			if (!HasLocalAuthority && (!base.enabled || !base.gameObject.activeSelf))
			{
				localStatePrev = State.Disabled;
				base.enabled = true;
				base.gameObject.SetActive(value: true);
				RemoteUpdate(Time.deltaTime);
			}
		}

		public virtual void StartConnection(RCRemoteHoldable remote, RCCosmeticNetworkSync sync)
		{
			connectedRemote = remote;
			networkSync = sync;
			hasNetworkSync = sync != null;
			base.enabled = true;
			base.gameObject.SetActive(value: true);
			useLeftDock = remote.XRNode == XRNode.LeftHand;
			if (HasLocalAuthority && localState != State.Mobilized)
			{
				AuthorityBeginDocked();
			}
		}

		public virtual void EndConnection()
		{
			connectedRemote = null;
			activeInput = default(RCRemoteHoldable.RCInput);
			disconnectionTime = Time.time;
		}

		protected virtual void ResetToSpawnPosition()
		{
			if (rb == null)
			{
				rb = GetComponent<Rigidbody>();
			}
			if (rb != null)
			{
				rb.isKinematic = true;
			}
			base.transform.parent = (useLeftDock ? leftDockParent : rightDockParent);
			base.transform.SetLocalPositionAndRotation(useLeftDock ? dockLeftOffset.pos : dockRightOffset.pos, useLeftDock ? dockLeftOffset.rot : dockRightOffset.rot);
			base.transform.localScale = (useLeftDock ? dockLeftOffset.scale : dockRightOffset.scale);
		}

		protected virtual void AuthorityBeginDocked()
		{
			localState = (useLeftDock ? State.DockedLeft : State.DockedRight);
			if (networkSync != null)
			{
				networkSync.syncedState.state = (byte)localState;
			}
			stateStartTime = Time.time;
			waitingForTriggerRelease = true;
			ResetToSpawnPosition();
			if (connectedRemote == null)
			{
				SetDisabledState();
			}
		}

		protected virtual void AuthorityBeginMobilization()
		{
			localState = State.Mobilized;
			if (networkSync != null)
			{
				networkSync.syncedState.state = (byte)localState;
			}
			stateStartTime = Time.time;
			base.transform.parent = null;
			rb.isKinematic = false;
		}

		protected virtual void AuthorityBeginCrash()
		{
			localState = State.Crashed;
			if (networkSync != null)
			{
				networkSync.syncedState.state = (byte)localState;
			}
			stateStartTime = Time.time;
		}

		protected virtual void SetDisabledState()
		{
			localState = State.Disabled;
			if (networkSync != null)
			{
				networkSync.syncedState.state = (byte)localState;
			}
			ResetToSpawnPosition();
			base.enabled = false;
			base.gameObject.SetActive(value: false);
		}

		protected virtual void Awake()
		{
			rb = GetComponent<Rigidbody>();
		}

		protected virtual void OnEnable()
		{
		}

		void ISpawnable.OnSpawn(VRRig rig)
		{
			if ((object)rig == null)
			{
				GTDev.LogError("RCVehicle: Could not find VRRig in parents. If you are trying to make this a world item rather than a cosmetic then you'll have to refactor how it teleports back to the arms.", this);
				return;
			}
			if (!GTHardCodedBones.TryGetBoneXforms(rig, out _vrRigBones, out var outErrorMsg))
			{
				UnityEngine.Debug.LogError("RCVehicle: " + outErrorMsg, this);
				return;
			}
			if (leftDockParent == null && !GTHardCodedBones.TryGetBoneXform(_vrRigBones, dockLeftOffset.bone, out leftDockParent))
			{
				GTDev.LogError("RCVehicle: Could not find left dock transform.", this);
			}
			if (rightDockParent == null && !GTHardCodedBones.TryGetBoneXform(_vrRigBones, dockRightOffset.bone, out rightDockParent))
			{
				GTDev.LogError("RCVehicle: Could not find right dock transform.", this);
			}
		}

		void ISpawnable.OnDespawn()
		{
		}

		protected virtual void OnDisable()
		{
			localState = State.Disabled;
			localStatePrev = State.Disabled;
		}

		public void ApplyRemoteControlInput(RCRemoteHoldable.RCInput rcInput)
		{
			activeInput.joystick.y = Mathf.Sign(rcInput.joystick.y) * Mathf.Lerp(0f, 1f, Mathf.InverseLerp(joystickDeadzone, 1f, Mathf.Abs(rcInput.joystick.y)));
			activeInput.joystick.x = Mathf.Sign(rcInput.joystick.x) * Mathf.Lerp(0f, 1f, Mathf.InverseLerp(joystickDeadzone, 1f, Mathf.Abs(rcInput.joystick.x)));
			activeInput.trigger = Mathf.Clamp(rcInput.trigger, -1f, 1f);
			activeInput.buttons = rcInput.buttons;
		}

		private void Update()
		{
			float deltaTime = Time.deltaTime;
			if (HasLocalAuthority)
			{
				AuthorityUpdate(deltaTime);
			}
			else
			{
				RemoteUpdate(deltaTime);
			}
			SharedUpdate(deltaTime);
			localStatePrev = localState;
		}

		protected virtual void AuthorityUpdate(float dt)
		{
			switch (localState)
			{
			case State.Mobilized:
			{
				if (networkSync != null)
				{
					networkSync.syncedState.position = base.transform.position;
					networkSync.syncedState.rotation = base.transform.rotation;
				}
				bool num = (base.transform.position - leftDockParent.position).sqrMagnitude > maxRange * maxRange;
				bool flag = connectedRemote == null && Time.time - disconnectionTime > maxDisconnectionTime;
				if (num || flag)
				{
					AuthorityBeginCrash();
				}
				return;
			}
			case State.Crashed:
				if (Time.time > stateStartTime + crashRespawnDelay)
				{
					AuthorityBeginDocked();
				}
				return;
			}
			if (localState != localStatePrev)
			{
				ResetToSpawnPosition();
			}
			if (connectedRemote == null)
			{
				SetDisabledState();
				return;
			}
			if (waitingForTriggerRelease && activeInput.trigger < 0.25f)
			{
				waitingForTriggerRelease = false;
			}
			if (!waitingForTriggerRelease && activeInput.trigger > 0.25f)
			{
				AuthorityBeginMobilization();
			}
		}

		protected virtual void RemoteUpdate(float dt)
		{
			if (networkSync == null)
			{
				SetDisabledState();
				return;
			}
			localState = (State)networkSync.syncedState.state;
			switch (localState)
			{
			default:
				if (localStatePrev != State.DockedLeft)
				{
					useLeftDock = true;
					ResetToSpawnPosition();
				}
				break;
			case State.DockedRight:
				if (localStatePrev != State.DockedRight)
				{
					useLeftDock = false;
					ResetToSpawnPosition();
				}
				break;
			case State.Mobilized:
				if (localStatePrev != State.Mobilized)
				{
					rb.isKinematic = true;
					base.transform.parent = null;
				}
				base.transform.position = UnityEngine.Vector3.Lerp(networkSync.syncedState.position, base.transform.position, Mathf.Exp((0f - networkSyncFollowRateExp) * dt));
				base.transform.rotation = UnityEngine.Quaternion.Slerp(networkSync.syncedState.rotation, base.transform.rotation, Mathf.Exp((0f - networkSyncFollowRateExp) * dt));
				break;
			case State.Crashed:
				if (localStatePrev != State.Crashed)
				{
					rb.isKinematic = false;
					base.transform.parent = null;
					if (localStatePrev != State.Mobilized)
					{
						base.transform.position = networkSync.syncedState.position;
						base.transform.rotation = networkSync.syncedState.rotation;
					}
				}
				break;
			case State.Disabled:
				SetDisabledState();
				break;
			}
		}

		protected virtual void SharedUpdate(float dt)
		{
		}

		public virtual void AuthorityApplyImpact(UnityEngine.Vector3 hitVelocity, bool isProjectile)
		{
			if (HasLocalAuthority && localState == State.Mobilized)
			{
				float num = (isProjectile ? projectileVelocityTransfer : hitVelocityTransfer);
				rb.AddForce(UnityEngine.Vector3.ClampMagnitude(hitVelocity * num, hitMaxHitSpeed) * rb.mass, ForceMode.Impulse);
				if (isProjectile || (crashOnHit && hitVelocity.sqrMagnitude > crashOnHitSpeedThreshold * crashOnHitSpeedThreshold))
				{
					AuthorityBeginCrash();
				}
			}
			OnHitImpact?.Invoke();
		}

		protected float NormalizeAngle180(float angle)
		{
			angle = (angle + 180f) % 360f;
			if (angle < 0f)
			{
				angle += 360f;
			}
			return angle - 180f;
		}

		protected static void AddScaledGravityCompensationForce(Rigidbody rb, float scaleFactor, float gravityCompensation)
		{
			UnityEngine.Vector3 gravity = Physics.gravity;
			UnityEngine.Vector3 vector = -gravity * gravityCompensation;
			UnityEngine.Vector3 vector2 = gravity + vector;
			UnityEngine.Vector3 vector3 = vector2 * scaleFactor - vector2;
			rb.AddForce((vector + vector3) * rb.mass, ForceMode.Force);
		}
	}
