		private void PlaySfxByDistance(KeyValuePair<EFFECTTYPE, CosmeticEffect> effect, UnityEngine.Vector3 position)
		{
			if (!effect.Value.IsGameModeAllowed())
			{
				return;
			}
			effect.Value.EffectStartedTime = Time.time;
			IReadOnlyList<VRRig> readOnlyList2;
			if (!PhotonNetwork.InRoom)
			{
				IReadOnlyList<VRRig> readOnlyList = new VRRig[1] { GorillaTagger.Instance.offlineVRRig };
				readOnlyList2 = readOnlyList;
			}
			else
			{
				readOnlyList2 = VRRigCache.ActiveRigs;
			}
			foreach (VRRig item in readOnlyList2)
			{
				if (ShouldAffectRig(item, effect.Value.target) && (item.transform.position - position).IsShorterThan(effect.Value.effectDistanceRadius))
				{
					if (item == myRig)
					{
						effect.Value.EffectDuration = effect.Value.effectDurationOwner;
					}
					item.PlayCosmeticEffectSFX(effect);
				}
			}
		}

		private void PlayVFXForRig(KeyValuePair<EFFECTTYPE, CosmeticEffect> effect, VRRig vrRig)
		{
			if (effect.Value.IsGameModeAllowed() && ShouldAffectRig(vrRig, effect.Value.target))
			{
				effect.Value.EffectStartedTime = Time.time;
				if (vrRig == myRig)
				{
					effect.Value.EffectDuration = effect.Value.effectDurationOwner;
				}
				vrRig.SpawnVFXEffect(effect);
			}
		}

		private void PlayVFXByDistance(KeyValuePair<EFFECTTYPE, CosmeticEffect> effect, UnityEngine.Vector3 position)
		{
			if (!effect.Value.IsGameModeAllowed())
			{
				return;
			}
			effect.Value.EffectStartedTime = Time.time;
			IReadOnlyList<VRRig> readOnlyList2;
			if (!PhotonNetwork.InRoom)
			{
				IReadOnlyList<VRRig> readOnlyList = new VRRig[1] { GorillaTagger.Instance.offlineVRRig };
				readOnlyList2 = readOnlyList;
			}
			else
			{
				readOnlyList2 = VRRigCache.ActiveRigs;
			}
			foreach (VRRig item in readOnlyList2)
			{
				if (ShouldAffectRig(item, effect.Value.target) && (item.transform.position - position).IsShorterThan(effect.Value.effectDistanceRadius))
				{
					if (item == myRig)
					{
						effect.Value.EffectDuration = effect.Value.effectDurationOwner;
					}
					item.SpawnVFXEffect(effect);
				}
			}
		}

		public void OnSpawn(VRRig rig)
		{
			myRig = rig;
		}

		public void OnDespawn()
		{
		}
	}
	public class DreidelHoldable : TransferrableObject
	{
		[SerializeField]
		private Dreidel dreidelAnimation;

		private RubberDuckEvents _events;

		internal override void OnEnable()
		{
			base.OnEnable();
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((base.myRig != null) ? (base.myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : null));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
				}
			}
			if (_events != null)
			{
				_events.Activate.reliable = true;
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnDreidelSpin);
			}
		}

		internal override void OnDisable()
		{
			base.OnDisable();
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnDreidelSpin);
				_events.Dispose();
				_events = null;
			}
		}

		private void OnDreidelSpin(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			MonkeAgent.IncrementRPCCall(info, "OnDreidelSpin");
			if (sender == target && info.senderID == ownerRig.creator.ActorNumber)
			{
				UnityEngine.Vector3 v = (UnityEngine.Vector3)args[0];
				UnityEngine.Vector3 v2 = (UnityEngine.Vector3)args[1];
				float num = (float)args[2];
				double num2 = (double)args[6];
				if (v.IsValid(10000f) && v2.IsValid(10000f) && float.IsFinite(num) && double.IsFinite(num2))
				{
					bool counterClockwise = (bool)args[3];
					Dreidel.Side side = (Dreidel.Side)args[4];
					Dreidel.Variation variation = (Dreidel.Variation)args[5];
					StartSpinLocal(v, v2, num, counterClockwise, side, variation, num2);
				}
			}
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			base.OnGrab(pointGrabbed, grabbingHand);
			if (dreidelAnimation != null)
			{
				dreidelAnimation.TryCheckForSurfaces();
			}
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			if (dreidelAnimation != null)
			{
				dreidelAnimation.TrySetIdle();
			}
			return true;
		}

		public override void OnActivate()
		{
			base.OnActivate();
			if (dreidelAnimation != null && dreidelAnimation.TryGetSpinStartData(out var surfacePoint, out var surfaceNormal, out var randomDuration, out var randomSide, out var randomVariation, out var startTime))
			{
				bool flag = currentState == PositionState.InLeftHand;
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					object[] args = new object[7]
					{
						surfacePoint,
						surfaceNormal,
						randomDuration,
						flag,
						(int)randomSide,
						(int)randomVariation,
						startTime
					};
					_events.Activate.RaiseAll(args);
				}
				else
				{
					StartSpinLocal(surfacePoint, surfaceNormal, randomDuration, flag, randomSide, randomVariation, startTime);
				}
			}
		}

		private void StartSpinLocal(UnityEngine.Vector3 surfacePoint, UnityEngine.Vector3 surfaceNormal, float duration, bool counterClockwise, Dreidel.Side side, Dreidel.Variation variation, double startTime)
		{
			if (dreidelAnimation != null)
			{
				dreidelAnimation.SetSpinStartData(surfacePoint, surfaceNormal, duration, counterClockwise, side, variation, startTime);
				dreidelAnimation.Spin();
			}
		}

		public void DebugSpinDreidel()
		{
			Transform transform = GTPlayer.Instance.headCollider.transform;
			UnityEngine.Vector3 origin = transform.position + transform.forward * 0.5f;
			float maxDistance = 2f;
			if (Physics.Raycast(origin, UnityEngine.Vector3.down, out var hitInfo, maxDistance, GTPlayer.Instance.locomotionEnabledLayers.value, QueryTriggerInteraction.Ignore))
			{
				UnityEngine.Vector3 point = hitInfo.point;
				UnityEngine.Vector3 normal = hitInfo.normal;
				float num = UnityEngine.Random.Range(7f, 10f);
				Dreidel.Side side = (Dreidel.Side)UnityEngine.Random.Range(0, 4);
				Dreidel.Variation variation = (Dreidel.Variation)UnityEngine.Random.Range(0, 5);
				bool flag = currentState == PositionState.InLeftHand;
				double num2 = (PhotonNetwork.InRoom ? PhotonNetwork.Time : (-1.0));
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					object[] args = new object[7]
					{
						point,
						normal,
						num,
						flag,
						(int)side,
						(int)variation,
						num2
					};
					_events.Activate.RaiseAll(args);
				}
				else
				{
					StartSpinLocal(point, normal, num, flag, side, variation, num2);
				}
			}
		}
	}
	public class MedusaEyeLantern : MonoBehaviour
	{
		[Serializable]
		public class EyeState
		{
			public State eyeState;

			public AnimationCurve hapticStrength;

			public UnityEvent onEnterState;

			public UnityEvent onExitState;
		}

		public enum State
		{
			SLOSHING,
			DORMANT,
			TRACKING,
			WARMUP,
			PRIMING,
			PETRIFICATION,
			COOLDOWN,
			RESET
		}

		[SerializeField]
		private DistanceCheckerCosmetic distanceChecker;

		[SerializeField]
		private TransferrableObject transferableParent;

		[SerializeField]
		private GorillaVelocityTracker velocityTracker;

		[SerializeField]
		private Transform rotatingObjectTransform;

		[Space]
		[Header("Rotation Settings")]
		[SerializeField]
		private float maxRotationAngle = 50f;

		[SerializeField]
		private float sloshVelocityThreshold = 1f;

		[SerializeField]
		private float rotationSmoothing = 10f;

		[SerializeField]
		private float rotationSpeedMultiplier = 5f;

		[Space]
		[Header("Target Tracking Settings")]
		[SerializeField]
		private float lookAtEyeAngleThreshold = 90f;

		[SerializeField]
		private float targetHeadAngleThreshold = 5f;

		[SerializeField]
		private float lookAtTargetSpeed = 5f;

		[SerializeField]
		private float warmUpProgressTime = 3f;

		[SerializeField]
		private float resetCooldown = 5f;

		[SerializeField]
		private float faceDistanceOffset = 0.2f;

		[SerializeField]
		private float petrificationDuration = 0.2f;

		[Space]
		[Header("Eye State Settings")]
		public EyeState[] allStates = new EyeState[0];

		public UnityEvent<VRRig> OnPetrification;

		private UnityEngine.Quaternion initialRotation;

		private UnityEngine.Quaternion targetRotation;

		private State currentState;

		private State lastState;

		private float petrificationStarted = float.PositiveInfinity;

		private float warmupCounter;

		private Dictionary<State, EyeState> allStatesDict = new Dictionary<State, EyeState>();

		private VRRig targetRig;

		private float resetTargetTimer = 1f;

		private float resetTargetTime = float.PositiveInfinity;

		private void Awake()
		{
			EyeState[] array = allStates;
			foreach (EyeState eyeState in array)
			{
				allStatesDict.Add(eyeState.eyeState, eyeState);
			}
		}

		private void OnDestroy()
		{
			allStatesDict.Clear();
		}

		private void Start()
		{
			if (rotatingObjectTransform == null)
			{
				rotatingObjectTransform = base.transform;
			}
			initialRotation = rotatingObjectTransform.localRotation;
			SwitchState(State.DORMANT);
		}

		private void Update()
		{
			if (!transferableParent.InHand() && currentState != State.DORMANT)
			{
				SwitchState(State.DORMANT);
			}
			if (!transferableParent.InHand())
			{
				return;
			}
			UpdateState();
			if (!(velocityTracker == null) && !(rotatingObjectTransform == null))
			{
				UnityEngine.Vector3 averageVelocity = velocityTracker.GetAverageVelocity(worldSpace: true);
				UnityEngine.Vector3 vector = new UnityEngine.Vector3(averageVelocity.x, 0f, averageVelocity.z);
				float magnitude = vector.magnitude;
				UnityEngine.Vector3 normalized = vector.normalized;
				float x = Mathf.Clamp(0f - normalized.z, -1f, 1f) * maxRotationAngle * (magnitude * rotationSpeedMultiplier);
				float z = Mathf.Clamp(normalized.x, -1f, 1f) * maxRotationAngle * (magnitude * rotationSpeedMultiplier);
				targetRotation = initialRotation * UnityEngine.Quaternion.Euler(x, 0f, z);
				if (magnitude > sloshVelocityThreshold)
				{
					SwitchState(State.SLOSHING);
				}
				if ((double)magnitude < 0.01)
				{
					targetRotation = initialRotation;
				}
				if (!EyeIsLockedOn())
				{
					rotatingObjectTransform.localRotation = UnityEngine.Quaternion.Slerp(rotatingObjectTransform.localRotation, targetRotation, Time.deltaTime * rotationSmoothing);
				}
			}
		}

		public void HandleOnNoOneInRange()
		{
			SwitchState(State.RESET);
			resetTargetTime = Time.time;
			rotatingObjectTransform.localRotation = initialRotation;
		}

		public void HandleOnNewPlayerDetected(VRRig target, float distance)
		{
			targetRig = target;
			if (currentState != State.SLOSHING)
			{
				SwitchState(State.TRACKING);
			}
		}

		private void Sloshing()
		{
			UnityEngine.Vector3 averageVelocity = velocityTracker.GetAverageVelocity(worldSpace: true);
			if ((double)new UnityEngine.Vector3(averageVelocity.x, 0f, averageVelocity.z).magnitude < 0.01)
			{
				SwitchState(State.DORMANT);
			}
		}

		private void FaceTarget()
		{
			if (targetRig == null || rotatingObjectTransform == null)
			{
				return;
			}
			UnityEngine.Vector3 normalized = (targetRig.tagSound.transform.position - rotatingObjectTransform.position).normalized;
			UnityEngine.Vector3 normalized2 = new UnityEngine.Vector3(normalized.x, 0f, normalized.z).normalized;
			UnityEngine.Debug.DrawRay(rotatingObjectTransform.position, rotatingObjectTransform.forward * 0.3f, Color.blue);
			UnityEngine.Debug.DrawRay(rotatingObjectTransform.position, normalized2 * 0.3f, Color.green);
			if (normalized2.sqrMagnitude > 0.001f)
			{
				float num = Mathf.Acos(Mathf.Clamp(UnityEngine.Vector3.Dot(rotatingObjectTransform.forward.normalized, normalized2), -1f, 1f)) * 57.29578f;
				if (180f - num < targetHeadAngleThreshold && currentState == State.TRACKING)
				{
					SwitchState(State.WARMUP);
					return;
				}
				UnityEngine.Quaternion to = UnityEngine.Quaternion.LookRotation(-normalized2, UnityEngine.Vector3.up);
				rotatingObjectTransform.rotation = UnityEngine.Quaternion.RotateTowards(rotatingObjectTransform.rotation, to, lookAtTargetSpeed * Time.deltaTime);
			}
		}

		private bool IsTargetLookingAtEye()
		{
			if (targetRig == null || rotatingObjectTransform == null)
			{
				return false;
			}
			Transform transform = targetRig.tagSound.transform;
			UnityEngine.Vector3 normalized = (rotatingObjectTransform.position - rotatingObjectTransform.forward * faceDistanceOffset - transform.position).normalized;
			float num = Mathf.Acos(Mathf.Clamp(UnityEngine.Vector3.Dot(transform.up.normalized, normalized), -1f, 1f)) * 57.29578f;
			UnityEngine.Debug.DrawRay(transform.position, transform.up * 0.3f, Color.magenta);
			UnityEngine.Debug.DrawRay(transform.position, normalized * 0.3f, Color.yellow);
			return num < lookAtEyeAngleThreshold;
		}

		private void UpdateState()
		{
			switch (currentState)
			{
			case State.RESET:
				if (Time.time - resetTargetTime > resetTargetTimer)
				{
					resetTargetTime = float.PositiveInfinity;
					SwitchState(State.DORMANT);
				}
				break;
			case State.SLOSHING:
				Sloshing();
				break;
			case State.DORMANT:
				warmupCounter = 0f;
				petrificationStarted = float.PositiveInfinity;
				if (targetRig != null && (targetRig.transform.position - base.transform.position).IsShorterThan(distanceChecker.distanceThreshold))
				{
					SwitchState(State.TRACKING);
				}
				break;
			case State.TRACKING:
				FaceTarget();
				break;
			case State.WARMUP:
				warmupCounter += Time.deltaTime;
				FaceTarget();
				if (warmupCounter > warmUpProgressTime)
				{
					SwitchState(State.PRIMING);
					warmupCounter = 0f;
				}
				break;
			case State.PRIMING:
				FaceTarget();
				if (IsTargetLookingAtEye())
				{
					OnPetrification?.Invoke(targetRig);
					SwitchState(State.PETRIFICATION);
					petrificationStarted = Time.time;
				}
				break;
			case State.PETRIFICATION:
				if (Time.time - petrificationStarted > petrificationDuration)
				{
					SwitchState(State.COOLDOWN);
				}
				break;
			case State.COOLDOWN:
				if (Time.time - petrificationStarted > resetCooldown)
				{
					SwitchState(State.DORMANT);
					petrificationStarted = float.PositiveInfinity;
				}
				break;
			}
			PlayHaptic(currentState);
		}

		private void SwitchState(State newState)
		{
			lastState = currentState;
			currentState = newState;
			if (lastState != currentState && allStatesDict.TryGetValue(newState, out var value))
			{
				value.onEnterState?.Invoke();
			}
			if (lastState != currentState && allStatesDict.TryGetValue(lastState, out var value2))
			{
				value2.onExitState?.Invoke();
			}
		}

		private void PlayHaptic(State state)
		{
			if (!transferableParent.IsMyItem())
			{
				return;
			}
			allStatesDict.TryGetValue(state, out var value);
			if (currentState == State.WARMUP)
			{
				float time = Mathf.Clamp01(warmupCounter / warmUpProgressTime);
				if (value != null && value.hapticStrength != null)
				{
					float amplitude = value.hapticStrength.Evaluate(time);
					bool forLeftController = transferableParent.InLeftHand();
					GorillaTagger.Instance.StartVibration(forLeftController, amplitude, Time.deltaTime);
				}
			}
			else if (value != null && value.hapticStrength != null)
			{
				float amplitude2 = value.hapticStrength.Evaluate(0.5f);
				bool forLeftController2 = transferableParent.InLeftHand();
				GorillaTagger.Instance.StartVibration(forLeftController2, amplitude2, Time.deltaTime);
			}
		}

		private bool EyeIsLockedOn()
		{
			if (currentState == State.TRACKING || currentState == State.WARMUP || currentState == State.PRIMING)
			{
				return true;
			}
			return false;
		}
	}
	public class PickupableCosmetic : PickupableVariant
	{
		[SerializeField]
		private InteractionPoint interactionPoint;

		[SerializeField]
		private Rigidbody rb;

		[SerializeField]
		private Transform raycastOrigin;

		[Tooltip("Allow player to grab the placed object")]
		[SerializeField]
		private bool allowPickupFromGround = true;

		[SerializeField]
		private float autoPickupAfterSeconds;

		[SerializeField]
		private float autoPickupDistance;

		[Tooltip("Amount to offset the placed object from the hit position in the hit normal direction")]
		[SerializeField]
		private float placementOffset;

		[Tooltip("Prevent sticking if the hit surface normal is not within 40 degrees of world up")]
		[SerializeField]
		private bool dontStickToWall;

		[Tooltip("Layers to raycast against for placement")]
		[SerializeField]
		private LayerMask floorLayerMask = 134218241;

		[Tooltip("The distance to check if the banner is close to the floor (from a raycast check).")]
		public float RaycastCheckDist = 0.2f;

		[Tooltip("How many checks should we attempt for a raycast.")]
		public int RaycastChecksMax = 12;

		[FormerlySerializedAs("OnPickup")]
		[Space]
		public UnityEvent OnPickupShared;

		[FormerlySerializedAs("OnPlaced")]
		public UnityEvent OnPlacedShared;

		[SerializeField]
		private bool isBreakable;

		[Tooltip("Particle system played OnBrokenShared")]
		[SerializeField]
		private ParticleSystem breakEffect;

		[Tooltip("Renderers disabled OnBrokenShared and enabled OnPickupShared")]
		[SerializeField]
		private Renderer[] hideOnBreak = new Renderer[0];

		[Tooltip("Time after BreakPlaceable to reset item")]
		[SerializeField]
		private float respawnDelay = 0.5f;

		[FormerlySerializedAs("OnBroken")]
		[Space]
		public UnityEvent OnBrokenShared;

		private static int breakableBitmask = 32;

		private bool placedOnFloor;

		private float placedOnFloorTime = -1f;

		private bool broken;

		private float brokenTime = -1f;

		private VRRig cachedLocalRig;

		private HoldableObject holdableParent;

		private TransferrableObject transferrableParent;

		private RigOwnedPhysicsBody rigOwnedPhysicsBody;

		private double throwSettledTime = -1.0;

		private int landingSide;

		private float scale;

		private Collider bodyCollider;

		[Tooltip("How many directions to test per physics tick (spreads work across frames).")]
		[SerializeField]
		[Min(1f)]
		private int raysPerStep = 3;

		[Tooltip("Run a raycast step only every N physics ticks (1 = every FixedUpdate).")]
		[SerializeField]
		[Min(1f)]
		private int stepEveryNFrames = 2;

		[Tooltip("Small skin so rays start just outside our own collider volume.")]
		[SerializeField]
		[Range(0.005f, 0.1f)]
		private float selfSkinOffset = 0.02f;

		[SerializeField]
		private bool debugPlacementRays;

		private int currentRayIndex;

		private int frameCounter;

		private static readonly Dictionary<int, UnityEngine.Vector3[]> directionCache = new Dictionary<int, UnityEngine.Vector3[]>();

		private static readonly UnityEngine.Vector3[] tmpEmpty = Array.Empty<UnityEngine.Vector3>();

		private void Awake()
		{
			rigOwnedPhysicsBody = GetComponent<RigOwnedPhysicsBody>();
			bodyCollider = GetComponent<Collider>();
		}

		private void Start()
		{
			base.enabled = false;
		}

		private void OnEnable()
		{
			if (rigOwnedPhysicsBody != null)
			{
				rigOwnedPhysicsBody.enabled = true;
			}
		}

		private void OnDisable()
		{
			if (rigOwnedPhysicsBody != null)
			{
				rigOwnedPhysicsBody.enabled = false;
			}
		}

		protected internal override void Pickup(bool isAutoPickup = false)
		{
			if (!isAutoPickup)
			{
				OnPickupShared?.Invoke();
			}
			rb.linearVelocity = UnityEngine.Vector3.zero;
			rb.isKinematic = true;
			if (holdableParent != null)
			{
				base.transform.parent = holdableParent.transform;
			}
			base.transform.localPosition = UnityEngine.Vector3.zero;
			base.transform.localRotation = UnityEngine.Quaternion.identity;
			base.transform.localScale = UnityEngine.Vector3.one;
			scale = 1f;
			placedOnFloorTime = -1f;
			placedOnFloor = false;
			broken = false;
			brokenTime = -1f;
			if (isBreakable && transferrableParent != null && transferrableParent.IsLocalObject())
			{
				int itemState = (int)transferrableParent.itemState;
				itemState &= ~breakableBitmask;
				transferrableParent.itemState = (TransferrableObject.ItemStates)itemState;
				if (breakEffect != null && breakEffect.isPlaying)
				{
					breakEffect.Stop();
				}
			}
			ShowRenderers(visible: true);
			if (interactionPoint != null)
			{
				interactionPoint.enabled = true;
			}
			base.enabled = false;
		}

		protected internal override void DelayedPickup()
		{
			DelayedPickup_Internal();
		}

		private async void DelayedPickup_Internal()
		{
			await Awaitable.WaitForSecondsAsync(1f);
			Pickup();
		}

		protected internal override void Release(HoldableObject holdable, UnityEngine.Vector3 startPosition, UnityEngine.Vector3 velocity, float playerScale)
		{
			holdableParent = holdable;
			base.transform.parent = null;
			base.transform.position = startPosition;
			base.transform.localScale = UnityEngine.Vector3.one * playerScale;
			rb.isKinematic = false;
			rb.useGravity = true;
			rb.linearVelocity = velocity;
			rb.detectCollisions = true;
			if (!allowPickupFromGround && interactionPoint != null)
			{
				interactionPoint.enabled = false;
			}
			scale = playerScale;
			base.enabled = true;
			transferrableParent = holdableParent as TransferrableObject;
			currentRayIndex = 0;
			frameCounter = 0;
		}

		private void FixedUpdate()
		{
			if (isBreakable && broken)
			{
				if (Time.time > respawnDelay + brokenTime)
				{
					Pickup();
				}
				return;
			}
			if (isBreakable && placedOnFloor)
			{
				bool flag = ((uint)transferrableParent.itemState & (uint)breakableBitmask) != 0;
				if (flag != broken && flag)
				{
					OnBreakReplicated();
				}
			}
			if (autoPickupAfterSeconds > 0f && placedOnFloor && Time.time - placedOnFloorTime > autoPickupAfterSeconds)
			{
				Pickup(isAutoPickup: true);
				ThrowablePickupableCosmetic throwablePickupableCosmetic = transferrableParent as ThrowablePickupableCosmetic;
				if ((bool)throwablePickupableCosmetic)
				{
					throwablePickupableCosmetic.OnReturnToDockPositionShared?.Invoke();
				}
			}
			if (autoPickupDistance > 0f && transferrableParent != null && (transferrableParent.ownerRig.transform.position - base.transform.position).IsLongerThan(autoPickupDistance))
			{
				Pickup();
			}
			if (placedOnFloor || !base.enabled)
			{
				return;
			}
			frameCounter++;
			if (frameCounter % stepEveryNFrames != 0)
			{
				return;
			}
			float maxDistance = RaycastCheckDist * scale;
			int value = floorLayerMask.value;
			UnityEngine.Vector3[] cachedDirections = GetCachedDirections(RaycastChecksMax);
			int num = 0;
			while (num < raysPerStep && currentRayIndex < cachedDirections.Length)
			{
				UnityEngine.Vector3 vector = cachedDirections[currentRayIndex];
				currentRayIndex++;
				num++;
				if (Physics.Raycast(GetSafeRayOrigin(raycastOrigin.position, vector), vector, out var hitInfo, maxDistance, value, QueryTriggerInteraction.Ignore) && (!dontStickToWall || !(UnityEngine.Vector3.Angle(hitInfo.normal, UnityEngine.Vector3.up) >= 40f)))
				{
					SettleBanner(hitInfo);
					OnPlacedShared?.Invoke();
					placedOnFloor = true;
					placedOnFloorTime = Time.time;
					break;
				}
			}
			if (currentRayIndex >= cachedDirections.Length)
			{
				currentRayIndex = 0;
			}
		}

		private void SettleBanner(RaycastHit hitInfo)
		{
			rb.isKinematic = true;
			rb.useGravity = false;
			rb.detectCollisions = false;
			UnityEngine.Vector3 normal = hitInfo.normal;
			base.transform.position = hitInfo.point + normal * placementOffset;
			UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.ProjectOnPlane(base.transform.forward, normal).normalized, normal);
			base.transform.rotation = rotation;
		}

		private UnityEngine.Vector3 GetFibonacciSphereDirection(int index, int total)
		{
			float f = Mathf.Acos(1f - 2f * ((float)index + 0.5f) / (float)total);
			float f2 = MathF.PI * (1f + Mathf.Sqrt(5f)) * ((float)index + 0.5f);
			float x = Mathf.Sin(f) * Mathf.Cos(f2);
			float y = Mathf.Sin(f) * Mathf.Sin(f2);
			float z = Mathf.Cos(f);
			return new UnityEngine.Vector3(x, y, z).normalized;
		}

		private UnityEngine.Vector3[] GetCachedDirections(int count)
		{
			if (count <= 0)
			{
				return tmpEmpty;
			}
			if (directionCache.TryGetValue(count, out var value))
			{
				return value;
			}
			value = new UnityEngine.Vector3[count];
			for (int i = 0; i < count; i++)
			{
				value[i] = GetFibonacciSphereDirection(i, count);
			}
			directionCache[count] = value;
			return value;
		}

		private UnityEngine.Vector3 GetSafeRayOrigin(UnityEngine.Vector3 rawOrigin, UnityEngine.Vector3 dir)
		{
			float num = selfSkinOffset;
			if (bodyCollider != null)
			{
				float magnitude = bodyCollider.bounds.extents.magnitude;
				num = Mathf.Max(selfSkinOffset, magnitude * 0.05f);
			}
			return rawOrigin - dir.normalized * num;
		}

		public void BreakPlaceable()
		{
			if (isBreakable && placedOnFloor)
			{
				if (transferrableParent != null && transferrableParent.IsLocalObject())
				{
					int itemState = (int)transferrableParent.itemState;
					itemState |= breakableBitmask;
					transferrableParent.itemState = (TransferrableObject.ItemStates)itemState;
				}
				else
				{
					GTDev.LogError("PickupableCosmetic " + base.gameObject.name + " has no TransferrableObject parent. Break effects cannot be replicated");
				}
			}
		}

		private void OnBreakReplicated()
		{
			PlayBreakEffects();
		}

		protected virtual void PlayBreakEffects()
		{
			if (!isBreakable || !placedOnFloor || broken)
			{
				return;
			}
			broken = true;
			brokenTime = Time.time;
			if (breakEffect != null)
			{
				if (breakEffect.isPlaying)
				{
					breakEffect.Stop();
				}
				breakEffect.Play();
			}
			if (interactionPoint != null)
			{
				interactionPoint.enabled = false;
			}
			ShowRenderers(visible: false);
			OnBrokenShared?.Invoke();
		}

		protected virtual void ShowRenderers(bool visible)
		{
			if (hideOnBreak.IsNullOrEmpty())
			{
				return;
			}
			for (int i = 0; i < hideOnBreak.Length; i++)
			{
				Renderer renderer = hideOnBreak[i];
				if (!(renderer == null))
				{
					renderer.forceRenderingOff = !visible;
				}
			}
		}
	}
