	public class ProximityLookAt : MonoBehaviour, IGorillaSliceableSimple
	{
		public enum LocalAxis
		{
			Forward,
			Back,
			Right,
			Left,
			Up,
			Down
		}

		[Header("Settings")]
		[SerializeField]
		private Transform[] lookTransforms;

		[Tooltip("The local axis that points 'forward' on this transform.")]
		[SerializeField]
		private LocalAxis localForward = LocalAxis.Down;

		[SerializeField]
		private float lookRadius = 0.5f;

		[Tooltip("The cone angle in degrees used to detect nearby players.Only players within this angle of the forward direction are considered as targets.")]
		[SerializeField]
		private float targetSearchAngleDegrees = 60f;

		[Tooltip("How far in degrees the transform can physically rotate from its rest position.Should be less than or equal to targetSearchAngleDegrees")]
		[SerializeField]
		private float lookAtAngleDegreeMax = 45f;

		[SerializeField]
		private float rotSpeed = 180f;

		[Tooltip("Seconds to hold the current target before switching to a new one")]
		[SerializeField]
		private float targetSwitchCooldown = 0.5f;

		[Tooltip("Whether the cosmetic owner can be considered as a look target.")]
		[SerializeField]
		private bool includeOwner;

		[Header("Pivot Clamping (Optional)")]
		[Tooltip("Assign a pivot transform to constrain rotation relative to it. Leave empty to skip clamping.")]
		[SerializeField]
		private Transform pivotConstraint;

		[SerializeField]
		private float minPivotY = -1f;

		[SerializeField]
		private float maxPivotY = 1f;

		private TransferrableObject transferableParent;

		private VRRig ownerRig;

		private Transform lookTarget;

		private UnityEngine.Vector3 normalizedLocalForward;

		private float cosAngle;

		private float sqrRadius;

		private float lastTargetSwitchTime = float.NegativeInfinity;

		private void OnEnable()
		{
			GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
			if (transferableParent != null)
			{
				ownerRig = transferableParent.ownerRig;
			}
			if (ownerRig == null)
			{
				ownerRig = GetComponentInParent<VRRig>();
			}
			if (ownerRig == null)
			{
				ownerRig = GorillaTagger.Instance.offlineVRRig;
			}
			CacheSettings();
		}

		private void OnDisable()
		{
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
			lookTarget = null;
			lastTargetSwitchTime = float.NegativeInfinity;
		}

		private void OnValidate()
		{
			CacheSettings();
		}

		private void CacheSettings()
		{
			normalizedLocalForward = LocalAxisToVector(localForward);
			cosAngle = Mathf.Cos(targetSearchAngleDegrees * (MathF.PI / 180f));
			sqrRadius = lookRadius * lookRadius;
		}

		private static UnityEngine.Vector3 LocalAxisToVector(LocalAxis axis)
		{
			return axis switch
			{
				LocalAxis.Forward => UnityEngine.Vector3.forward, 
				LocalAxis.Back => UnityEngine.Vector3.back, 
				LocalAxis.Right => UnityEngine.Vector3.right, 
				LocalAxis.Left => UnityEngine.Vector3.left, 
				LocalAxis.Up => UnityEngine.Vector3.up, 
				LocalAxis.Down => UnityEngine.Vector3.down, 
				_ => UnityEngine.Vector3.forward, 
			};
		}

		public void SliceUpdate()
		{
			Transform transform = FindTarget();
			if (!(transform == lookTarget) && !(Time.time - lastTargetSwitchTime < targetSwitchCooldown))
			{
				lookTarget = transform;
				lastTargetSwitchTime = Time.time;
			}
		}

		private void LateUpdate()
		{
			if (lookTransforms == null)
			{
				return;
			}
			UnityEngine.Vector3 vector = base.transform.TransformDirection(normalizedLocalForward);
			for (int i = 0; i < lookTransforms.Length; i++)
			{
				Transform transform = lookTransforms[i];
				if (!(transform == null))
				{
					UnityEngine.Vector3 target = ((lookTarget != null) ? (lookTarget.position - transform.position).normalized : vector);
					target = UnityEngine.Vector3.RotateTowards(vector, target, lookAtAngleDegreeMax * (MathF.PI / 180f), 0f);
					if (pivotConstraint != null)
					{
						UnityEngine.Vector3 vector2 = pivotConstraint.InverseTransformDirection(target);
						vector2.y = Mathf.Clamp(vector2.y, minPivotY, maxPivotY);
						target = pivotConstraint.TransformDirection(vector2.normalized);
					}
					UnityEngine.Vector3 forward = UnityEngine.Vector3.RotateTowards(transform.rotation * UnityEngine.Vector3.forward, target, rotSpeed * (MathF.PI / 180f) * Time.deltaTime, 0f);
					transform.rotation = ((pivotConstraint != null) ? UnityEngine.Quaternion.LookRotation(forward, pivotConstraint.up) : UnityEngine.Quaternion.LookRotation(forward));
				}
			}
		}

		private Transform FindTarget()
		{
			if (!PhotonNetwork.InRoom)
			{
				return GorillaTagger.Instance.offlineVRRig.tagSound.transform;
			}
			UnityEngine.Vector3 lhs = base.transform.TransformDirection(normalizedLocalForward);
			float num = float.NegativeInfinity;
			Transform result = null;
			foreach (VRRig activeRig in VRRigCache.ActiveRigs)
			{
				if (!includeOwner && activeRig == ownerRig)
				{
					continue;
				}
				UnityEngine.Vector3 vector = activeRig.tagSound.transform.position - base.transform.position;
				if (!(vector.sqrMagnitude > sqrRadius))
				{
					UnityEngine.Vector3 normalized = vector.normalized;
					float num2 = UnityEngine.Vector3.Dot(lhs, normalized);
					if (!(num2 < cosAngle) && num2 > num)
					{
						num = num2;
						result = activeRig.tagSound.transform;
					}
				}
			}
			return result;
		}
	}
	[RequireComponent(typeof(TransferrableObject))]
	public class SeedPacketHoldable : MonoBehaviour
	{
		[SerializeField]
		private float cooldown;

		[SerializeField]
		private ParticleSystem particles;

		[SerializeField]
		private float pouringAngle;

		[SerializeField]
		private float pouringRaycastDistance = 5f;

		[SerializeField]
		private LayerMask raycastLayerMask;

		[SerializeField]
		private float placeEffectDelayMultiplier = 10f;

		[SerializeField]
		private GameObject flowerEffectPrefab;

		private List<SeedPacketTriggerHandler> pooledObjects = new List<SeedPacketTriggerHandler>();

		private CallLimiter callLimiter = new CallLimiter(10, 3f);

		private int flowerEffectHash;

		private UnityEngine.Vector3 hitPoint;

		private TransferrableObject transferrableObject;

		private bool isPouring = true;

		private float pouringStartedTime;

		private RubberDuckEvents _events;

		private void Awake()
		{
			transferrableObject = GetComponent<TransferrableObject>();
			flowerEffectHash = PoolUtils.GameObjHashCode(flowerEffectPrefab);
		}

		private void OnEnable()
		{
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((transferrableObject.myOnlineRig != null) ? transferrableObject.myOnlineRig.creator : ((transferrableObject.myRig != null) ? (transferrableObject.myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : null));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(SyncTriggerEffect);
			}
		}

		private void OnDisable()
		{
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(SyncTriggerEffect);
				_events.Dispose();
				_events = null;
			}
		}

		private void OnDestroy()
		{
			pooledObjects.Clear();
		}

		private void Update()
		{
			if (!transferrableObject.InHand())
			{
				return;
			}
			if (!isPouring && UnityEngine.Vector3.Angle(base.transform.up, UnityEngine.Vector3.down) <= pouringAngle)
			{
				StartPouring();
				if (Physics.Raycast(base.transform.position, UnityEngine.Vector3.down, out var hitInfo, pouringRaycastDistance, raycastLayerMask))
				{
					hitPoint = hitInfo.point;
					Invoke("SpawnEffect", hitInfo.distance * placeEffectDelayMultiplier);
				}
			}
			if (isPouring && Time.time - pouringStartedTime >= cooldown)
			{
				isPouring = false;
			}
		}

		private void StartPouring()
		{
			if ((bool)particles)
			{
				particles.Play();
			}
			isPouring = true;
			pouringStartedTime = Time.time;
		}

		private void SpawnEffect()
		{
			GameObject obj = ObjectPools.instance.Instantiate(flowerEffectHash);
			obj.transform.position = hitPoint;
			if (obj.TryGetComponent<SeedPacketTriggerHandler>(out var component))
			{
				pooledObjects.Add(component);
				component.onTriggerEntered.AddListener(SyncTriggerEffectForOthers);
			}
		}

		private void SyncTriggerEffectForOthers(SeedPacketTriggerHandler seedPacketTriggerHandlerTriggerHandlerEvent)
		{
			int num = pooledObjects.IndexOf(seedPacketTriggerHandlerTriggerHandlerEvent);
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(num);
			}
		}

		private void SyncTriggerEffect(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender != target || args.Length != 1)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "SyncTriggerEffect");
			if (callLimiter.CheckCallTime(Time.time))
			{
				int num = (int)args[0];
				if (num >= 0 || num < pooledObjects.Count)
				{
					pooledObjects[num].ToggleEffects();
				}
			}
		}
	}
	public class SquirtingFlowerBadgeCosmetic : MonoBehaviour, ISpawnable, IFingerFlexListener
	{
		[SerializeField]
		private ParticleSystem particlesToPlay;

		[SerializeField]
