		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private float coolDownTimer = 2f;

		[SerializeField]
		private bool leftHand;

		private float triggeredTime;

		private bool restartTimer;

		private bool buttonReleased = true;

		public VRRig MyRig { get; private set; }

		public bool IsSpawned { get; set; }

		public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

		public void OnSpawn(VRRig rig)
		{
			MyRig = rig;
		}

		public void OnDespawn()
		{
		}

		private void Update()
		{
			if (!restartTimer && Time.time - triggeredTime >= coolDownTimer)
			{
				restartTimer = true;
			}
		}

		private void OnPlayEffectLocal()
		{
			if (particlesToPlay != null)
			{
				particlesToPlay.Play();
			}
			if (objectToEnable != null)
			{
				objectToEnable.SetActive(value: true);
			}
			if (audioSource != null && audioToPlay != null)
			{
				audioSource.GTPlayOneShot(audioToPlay);
			}
			restartTimer = false;
			triggeredTime = Time.time;
		}

		public void OnButtonPressed(bool isLeftHand, float value)
		{
			if (FingerFlexValidation(isLeftHand) && restartTimer && buttonReleased)
			{
				OnPlayEffectLocal();
				buttonReleased = false;
			}
		}

		public void OnButtonReleased(bool isLeftHand, float value)
		{
			if (FingerFlexValidation(isLeftHand))
			{
				buttonReleased = true;
			}
		}

		public void OnButtonPressStayed(bool isLeftHand, float value)
		{
		}

		public bool FingerFlexValidation(bool isLeftHand)
		{
			if (leftHand && !isLeftHand)
			{
				return false;
			}
			if (!leftHand && isLeftHand)
			{
				return false;
			}
			return true;
		}
	}
	public class StickObjectToPlayer : MonoBehaviour, ITickSystemTick
	{
		private enum SpawnLocation
		{
			Head,
			RightHand,
			LeftHand
		}

		[Header("Shared Settings")]
		[Tooltip("Must be in the global object pool and have a tag.")]
		[SerializeField]
		private GameObject objectToSpawn;

		[Tooltip("Optional: how many objects can be active at once")]
		[SerializeField]
		private int maxActiveStickies = 1;

		[SerializeField]
		private SpawnLocation spawnLocation;

		[SerializeField]
		private float stickRadius = 0.5f;

		[SerializeField]
		private bool alignToHitNormal = true;

		[SerializeField]
		private Rigidbody spawnerRigidbody;

		[SerializeField]
		private string parentTag = "GorillaHead";

		[SerializeField]
		private float cooldown;

		[Header("Third Person View")]
		[Tooltip("If you are only interested in the FPV, don't check this box so that others don't see it.")]
		[SerializeField]
		private bool thirdPersonView = true;

		[SerializeField]
		private UnityEngine.Vector3 positionOffset = new UnityEngine.Vector3(0f, 0.02f, 0.17f);

		[Tooltip("Local rotation to apply to the spawned object (Euler angles, degrees)")]
		[SerializeField]
		private UnityEngine.Vector3 localEulerAngles = UnityEngine.Vector3.zero;

		[Header("First Person View")]
		[SerializeField]
		private bool firstPersonView;

		[SerializeField]
		private UnityEngine.Vector3 FPVOffset = new UnityEngine.Vector3(0f, 0.02f, 0.17f);

		[Tooltip("Local rotation to apply to the spawned object (Euler angles, degrees)")]
		[SerializeField]
		private UnityEngine.Vector3 FPVlocalEulerAngles = UnityEngine.Vector3.zero;

		[Header("Events")]
		public UnityEvent OnStickShared;

		private GameObject stickyObject;

		private float lastSpawnedTime;

		private bool canSpawn = true;

		private NetPlayer ownerPlayer;

		public bool TickRunning { get; set; }

		public void Tick()
		{
			if (!canSpawn && Time.time - lastSpawnedTime >= cooldown)
			{
				canSpawn = true;
			}
		}

		private void OnEnable()
		{
			TickSystem<object>.AddTickCallback(this);
			canSpawn = true;
		}

		private void OnDisable()
		{
			TickSystem<object>.RemoveTickCallback(this);
		}

		public void SetOwner(NetPlayer player)
		{
			ownerPlayer = player;
		}

		private Transform MakeOrGetStickyContainer(Transform parent)
		{
			Transform transform = parent;
			Transform[] componentsInChildren = parent.GetComponentsInChildren<Transform>(includeInactive: true);
			foreach (Transform transform2 in componentsInChildren)
			{
				if (!firstPersonView && transform2.CompareTag(parentTag))
				{
					transform = transform2;
					break;
				}
			}
			string n = "StickyObjects_" + objectToSpawn.name;
			Transform transform3 = transform.Find(n);
			if (transform3 != null)
			{
				return transform3;
			}
			GameObject obj = new GameObject(n);
			obj.transform.SetParent(transform, worldPositionStays: false);
			return obj.transform;
		}

		public void Stick(bool leftHand, Collider other)
		{
			if (!canSpawn || other == null || !base.enabled)
			{
				return;
			}
			VRRig componentInParent = other.GetComponentInParent<VRRig>();
			if (!componentInParent || (ownerPlayer != null && componentInParent.creator == ownerPlayer))
			{
				return;
			}
			UnityEngine.Vector3 vector = ((spawnerRigidbody != null) ? spawnerRigidbody.linearVelocity : UnityEngine.Vector3.zero);
			UnityEngine.Vector3 vector2 = Time.fixedDeltaTime * 2f * vector;
			UnityEngine.Vector3 vector3 = vector2.normalized;
			if (vector3 == UnityEngine.Vector3.zero)
			{
				vector3 = base.transform.forward;
				vector2 = vector3 * 0.01f;
			}
			UnityEngine.Vector3 vector4 = base.transform.position - vector2;
			UnityEngine.Vector3 vector5;
			if (alignToHitNormal)
			{
				float magnitude = vector2.magnitude;
				vector5 = ((!other.Raycast(new Ray(vector4, vector3), out var hitInfo, 2f * magnitude)) ? other.ClosestPoint(vector4) : hitInfo.point);
			}
			else
			{
				vector5 = other.ClosestPoint(vector4);
			}
			UnityEngine.Vector3 vector6 = GetSpawnPosition(spawnLocation, componentInParent).TransformPoint(positionOffset);
			if (!((vector5 - vector6).magnitude <= stickRadius * componentInParent.scaleFactor))
			{
				return;
			}
			if (NetworkSystem.Instance.LocalPlayer == componentInParent.creator)
			{
				if (firstPersonView && spawnLocation == SpawnLocation.Head)
				{
					StickFirstPersonView();
				}
			}
			else
			{
				if (!thirdPersonView)
				{
					return;
				}
				Transform parent = MakeOrGetStickyContainer(componentInParent.transform);
				StickTo(parent, vector6, localEulerAngles);
			}
			OnStickShared?.Invoke();
		}

		private void StickFirstPersonView()
		{
			Transform cosmeticsHeadTarget = GTPlayer.Instance.CosmeticsHeadTarget;
			UnityEngine.Vector3 position = cosmeticsHeadTarget.TransformPoint(FPVOffset);
			Transform parent = MakeOrGetStickyContainer(cosmeticsHeadTarget);
			StickTo(parent, position, FPVlocalEulerAngles);
		}

		private void StickTo(Transform parent, UnityEngine.Vector3 position, UnityEngine.Vector3 eulerAngle)
		{
			int num = 0;
			for (int i = 0; i < parent.childCount; i++)
			{
				if (parent.GetChild(i).gameObject.activeInHierarchy)
				{
					num++;
				}
			}
			if (num < maxActiveStickies)
			{
				stickyObject = ObjectPools.instance.Instantiate(objectToSpawn);
				if (!(stickyObject == null))
				{
					stickyObject.transform.SetParent(parent, worldPositionStays: false);
					stickyObject.transform.position = position;
					stickyObject.transform.localEulerAngles = eulerAngle;
					lastSpawnedTime = Time.time;
					canSpawn = false;
				}
			}
		}

		private Transform GetSpawnPosition(SpawnLocation spawnType, VRRig hitRig)
		{
			return spawnType switch
			{
				SpawnLocation.Head => hitRig.head.rigTarget.transform, 
				SpawnLocation.LeftHand => hitRig.leftHand.rigTarget.transform, 
				SpawnLocation.RightHand => hitRig.rightHand.rigTarget.transform, 
				_ => null, 
			};
		}

		public void Debug_StickToLocalPlayer()
		{
			UnityEngine.Vector3 position = GetSpawnPosition(spawnLocation, VRRig.LocalRig).TransformPoint(positionOffset);
			StickTo(VRRig.LocalRig.transform, position, localEulerAngles);
		}

		public void Debug_StickToLocalPlayerFPV()
		{
			StickFirstPersonView();
		}
	}
	public class ThrowableHoldableCosmetic : TransferrableObject
	{
		[Tooltip("Projectile prefab from the global object pool that gets spawned when this object is thrown")]
		[FormerlySerializedAs("firecrackerProjectilePrefab")]
		[SerializeField]
		private GameObject projectilePrefab;

		[Tooltip(" A second projectile prefab that will be spawned if UseAlternativeProjectile is called")]
		[SerializeField]
		private GameObject alternativeProjectilePrefab;

		[Tooltip("Objects on the body that should be hidden when the projectile is spawned")]
		[SerializeField]
		private GameObject disableWhenThrown;

		private CallLimiter firecrackerCallLimiter = new CallLimiter(10, 3f);

		[SerializeField]
		private float respawnCooldown = 1f;

		private CosmeticEffectsOnPlayers playersEffect;

		private int projectileHash;

		private int alternativeProjectileHash;

		private int currentProjectileHash;

		private bool forceBackToDock;

		private WaitForSeconds respawnWait;

		private RubberDuckEvents _events;

		internal override void OnEnable()
		{
			base.OnEnable();
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnThrowEvent);
			}
			forceBackToDock = false;
		}

		protected override void Awake()
		{
			base.Awake();
			projectileHash = PoolUtils.GameObjHashCode(projectilePrefab);
			if (alternativeProjectilePrefab != null)
			{
				alternativeProjectileHash = PoolUtils.GameObjHashCode(alternativeProjectilePrefab);
			}
			currentProjectileHash = projectileHash;
			playersEffect = GetComponentInChildren<CosmeticEffectsOnPlayers>();
			respawnWait = new WaitForSeconds(respawnCooldown);
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			if (disableWhenThrown.gameObject.activeSelf)
			{
				base.OnGrab(pointGrabbed, grabbingHand);
			}
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			if (VRRigCache.Instance.localRig.Rig != ownerRig)
			{
				return false;
			}
			UnityEngine.Vector3 position = base.transform.position;
			UnityEngine.Quaternion rotation = base.transform.rotation;
			bool isLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
			UnityEngine.Vector3 averageVelocity = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeftHand).GetAverageVelocity(worldSpace: true);
			float scale = GTPlayer.Instance.scale;
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(position, rotation, averageVelocity, scale);
			}
			OnThrowLocal(position, rotation, averageVelocity, ownerRig);
			return true;
		}

		internal override void OnDisable()
		{
			base.OnDisable();
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnThrowEvent);
				_events.Dispose();
				_events = null;
			}
		}

		public void UseAlternativeProjectile()
		{
			if (alternativeProjectilePrefab != null)
			{
				currentProjectileHash = alternativeProjectileHash;
			}
		}

		public void ForceBackToDock()
		{
			forceBackToDock = true;
		}

		private IEnumerator ReEnableAfterDelay(GameObject obj)
		{
			yield return respawnWait;
			obj.SetActive(value: true);
		}

		private void OnThrowEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender != target || args.Length != 4 || info.senderID != ownerRig.creator.ActorNumber)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnThrowEvent");
			if (firecrackerCallLimiter.CheckCallTime(Time.time) && args[0] is UnityEngine.Vector3 v && args[1] is UnityEngine.Quaternion q && args[2] is UnityEngine.Vector3 inVel && args[3] is float value)
			{
				UnityEngine.Vector3 velocity = targetRig.ClampVelocityRelativeToPlayerSafe(inVel, 40f);
				value.ClampSafe(0.01f, 1f);
				if (q.IsValid() && v.IsValid(10000f) && targetRig.IsPositionInRange(v, 4f))
				{
					OnThrowLocal(v, q, velocity, ownerRig);
				}
			}
		}

		private void OnThrowLocal(UnityEngine.Vector3 startPos, UnityEngine.Quaternion rotation, UnityEngine.Vector3 velocity, VRRig ownerRig)
		{
			disableWhenThrown.SetActive(value: false);
			if (forceBackToDock)
			{
				forceBackToDock = false;
				StartCoroutine(ReEnableAfterDelay(disableWhenThrown));
				return;
			}
			IProjectile component = ObjectPools.instance.Instantiate(currentProjectileHash).GetComponent<IProjectile>();
			if (component is FirecrackerProjectile firecrackerProjectile)
			{
				if (networkedStateEvents != SyncOptions.None)
				{
					int state = (int)(itemState & (ItemStates)(-65));
					firecrackerProjectile.SetTransferrableState(networkedStateEvents, state);
				}
				firecrackerProjectile.OnDetonationComplete.AddListener(HitComplete);
				firecrackerProjectile.OnDetonationStart.AddListener(HitStart);
			}
			else if (component is FartBagThrowable fartBagThrowable)
			{
				fartBagThrowable.OnDeflated += HitComplete;
				fartBagThrowable.ParentTransferable = this;
			}
			component.Launch(startPos, rotation, velocity, 1f, ownerRig);
			currentProjectileHash = projectileHash;
		}

		private void HitStart(FirecrackerProjectile firecracker, UnityEngine.Vector3 contactPos)
		{
			if (!(firecracker == null) && !(playersEffect == null))
			{
				playersEffect.ApplyAllEffectsByDistance(contactPos);
			}
		}

		private void HitComplete(IProjectile projectile)
		{
			if (projectile == null)
			{
				return;
			}
			if (IsLocalObject() && networkedStateEvents != SyncOptions.None && resetOnDocked)
			{
				switch (networkedStateEvents)
				{
				case SyncOptions.Bool:
					ResetStateBools();
					break;
				case SyncOptions.Int:
					SetItemStateInt(0);
					break;
				}
			}
			if (projectile is FirecrackerProjectile firecrackerProjectile)
			{
				firecrackerProjectile.OnDetonationStart.RemoveListener(HitStart);
				firecrackerProjectile.OnDetonationComplete.RemoveListener(HitComplete);
				ObjectPools.instance.Destroy(firecrackerProjectile.gameObject);
			}
			else if (projectile is FartBagThrowable fartBagThrowable)
			{
				fartBagThrowable.OnDeflated -= HitComplete;
				ObjectPools.instance.Destroy(fartBagThrowable.gameObject);
			}
			StartCoroutine(ReEnableAfterDelay(disableWhenThrown));
		}
	}
	public class ThrowablePickupableCosmetic : TransferrableObject
	{
		[Tooltip("Child object with the PickupableCosmetic script")]
		[SerializeField]
		private PickupableVariant pickupableVariant;

		[Tooltip("cosmetics released at a greater distance from the dock than the threshold will be placed in world instead of returning to the dock")]
		[SerializeField]
		private float returnToDockDistanceThreshold = 0.7f;

		[FormerlySerializedAs("OnReturnToDockPosition")]
		[Space]
		public UnityEvent OnReturnToDockPositionLocal;

		public UnityEvent OnReturnToDockPositionShared;

		[FormerlySerializedAs("OnGrabFromDockPosition")]
		public UnityEvent OnGrabLocal;

		private RubberDuckEvents _events;

		private TransferrableObject transferrableObject;

		private bool isLocal;

		private NetPlayer owner;

		private CallLimiter callLimiterRelease = new CallLimiter(10, 2f);

		private CallLimiter callLimiterReturn = new CallLimiter(10, 2f);

		private new void Awake()
		{
			transferrableObject = GetComponent<TransferrableObject>();
		}

		internal override void OnEnable()
		{
			base.OnEnable();
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				owner = ((transferrableObject.myOnlineRig != null) ? transferrableObject.myOnlineRig.creator : ((transferrableObject.myRig != null) ? (transferrableObject.myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : null));
				if (owner != null)
				{
					_events.Init(owner);
					isLocal = owner.IsLocal;
				}
			}
			if (_events != null)
			{
				_events.Activate.reliable = true;
				_events.Deactivate.reliable = true;
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnReleaseEvent);
				_events.Deactivate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnReturnToDockEvent);
			}
		}

		internal override void OnDisable()
		{
			base.OnDisable();
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnReleaseEvent);
				_events.Deactivate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnReturnToDockEvent);
				_events.Dispose();
				_events = null;
			}
			if (pickupableVariant != null && pickupableVariant.enabled)
			{
				pickupableVariant.DelayedPickup();
			}
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			if (VRRigCache.Instance.localRig.Rig != ownerRig)
			{
				return;
			}
			if (pickupableVariant.enabled)
			{
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					_events.Activate.RaiseOthers(false);
				}
				base.transform.position = pickupableVariant.transform.position;
				base.transform.rotation = pickupableVariant.transform.rotation;
				pickupableVariant.Pickup();
				if (grabbingHand == EquipmentInteractor.instance.leftHand && currentState == PositionState.OnLeftArm)
				{
					canAutoGrabLeft = false;
					interpState = InterpolateState.None;
					currentState = PositionState.InRightHand;
				}
				else if (grabbingHand == EquipmentInteractor.instance.rightHand && currentState == PositionState.OnRightArm)
				{
					canAutoGrabRight = false;
					interpState = InterpolateState.None;
					currentState = PositionState.InLeftHand;
				}
			}
			OnGrabLocal?.Invoke();
			base.OnGrab(pointGrabbed, grabbingHand);
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			if (!(VRRigCache.Instance.localRig.Rig == ownerRig))
			{
				return false;
			}
			UnityEngine.Vector3 position = base.transform.position;
			bool isLeftHand = releasingHand == EquipmentInteractor.instance.leftHand;
			UnityEngine.Vector3 averageVelocity = GTPlayer.Instance.GetInteractPointVelocityTracker(isLeftHand).GetAverageVelocity(worldSpace: true);
			float scale = GTPlayer.Instance.scale;
			bool flag = DistanceToDock() > returnToDockDistanceThreshold;
			if (PhotonNetwork.InRoom && _events != null)
			{
				if (flag && _events.Activate != null)
				{
					_events.Activate.RaiseOthers(true, position, averageVelocity, scale);
					OnReleaseEventLocal(position, averageVelocity, scale);
				}
				else if (!flag && _events.Deactivate != null)
				{
					_events.Deactivate.RaiseAll();
					OnReturnToDockPositionLocal?.Invoke();
				}
			}
			else if (flag)
			{
				OnReleaseEventLocal(position, averageVelocity, scale);
			}
			else
			{
				OnReturnToDockPositionLocal?.Invoke();
				OnReturnToDockPositionShared?.Invoke();
			}
			return true;
		}

		private void OnReleaseEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender != target || info.senderID != ownerRig.creator.ActorNumber)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnReleaseEvent");
			if (!callLimiterRelease.CheckCallTime(Time.time))
			{
				return;
			}
			object obj = args[0];
			if (!(obj is bool))
			{
				return;
			}
			if ((bool)obj)
			{
				if (args[1] is UnityEngine.Vector3 newVal && args[2] is UnityEngine.Vector3 inVel && args[3] is float value)
				{
					UnityEngine.Vector3 v = base.transform.position;
					UnityEngine.Vector3 forward = base.transform.forward;
					v.SetValueSafe(in newVal);
					if (ownerRig.IsPositionInRange(v, 20f))
					{
						forward = ownerRig.ClampVelocityRelativeToPlayerSafe(inVel, 50f);
						float playerScale = value.ClampSafe(0.01f, 1f);
						OnReleaseEventLocal(v, forward, playerScale);
					}
				}
			}
			else
			{
				pickupableVariant.Pickup();
			}
		}

		private void OnReturnToDockEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender == target && info.senderID == ownerRig.creator.ActorNumber)
			{
				MonkeAgent.IncrementRPCCall(info, "OnReturnToDockEvent");
				if (callLimiterReturn.CheckCallTime(Time.time))
				{
					OnReturnToDockPositionShared?.Invoke();
				}
			}
		}

		private void OnReleaseEventLocal(UnityEngine.Vector3 startPosition, UnityEngine.Vector3 releaseVelocity, float playerScale)
		{
			pickupableVariant.Release(this, startPosition, releaseVelocity, playerScale);
		}

		private float DistanceToDock()
		{
			float result = 0f;
			if (currentState == PositionState.OnRightShoulder)
			{
				result = UnityEngine.Vector3.Distance(ownerRig.myBodyDockPositions.rightBackTransform.position, base.transform.position);
			}
			else if (currentState == PositionState.OnLeftShoulder)
			{
				result = UnityEngine.Vector3.Distance(ownerRig.myBodyDockPositions.leftBackTransform.position, base.transform.position);
			}
			else if (currentState == PositionState.OnRightArm)
			{
				result = UnityEngine.Vector3.Distance(ownerRig.myBodyDockPositions.rightArmTransform.position, base.transform.position);
			}
			else if (currentState == PositionState.OnLeftArm)
			{
				result = UnityEngine.Vector3.Distance(ownerRig.myBodyDockPositions.leftArmTransform.position, base.transform.position);
			}
			else if (currentState == PositionState.OnChest)
			{
				result = UnityEngine.Vector3.Distance(ownerRig.myBodyDockPositions.chestTransform.position, base.transform.position);
			}
			return result;
		}
	}
	public class TrashcanCosmetic : MonoBehaviour
	{
		public float minScoringDistance = 2f;

		public UnityEvent OnScored;

		public void OnBasket(bool isLeftHand, Collider other)
		{
			if (other.TryGetComponent<SlingshotProjectile>(out var component) && component.GetDistanceTraveled() >= minScoringDistance)
			{
				OnScored?.Invoke();
				component.DestroyAfterRelease();
			}
		}
	}
	public class DrillFX : MonoBehaviour
	{
		[SerializeField]
		private ParticleSystem fx;

		[SerializeField]
		private AnimationCurve fxEmissionCurve;

		[SerializeField]
		private float fxMinRadiusScale = 0.01f;

		[Tooltip("Right click menu has custom menu items. Anything starting with \"- \" is custom.")]
		[SerializeField]
		private AudioSource loopAudio;

		[SerializeField]
		private AnimationCurve loopAudioVolumeCurve;

		[Tooltip("Higher value makes it reach the target volume faster.")]
		[SerializeField]
		private float loopAudioVolumeTransitionSpeed = 3f;

		[FormerlySerializedAs("layerMask")]
		[Tooltip("The collision layers the line cast should intersect with")]
		[SerializeField]
		private LayerMask lineCastLayerMask;

		[Tooltip("The position in local space that the line cast starts.")]
		[SerializeField]
		private UnityEngine.Vector3 lineCastStart = UnityEngine.Vector3.zero;

		[Tooltip("The position in local space that the line cast ends.")]
		[SerializeField]
		private UnityEngine.Vector3 lineCastEnd = UnityEngine.Vector3.forward;

		private static bool appIsQuitting;

		private static bool appIsQuittingHandlerIsSubscribed;

		private float maxDepth;

		private bool hasFX;

		private ParticleSystem.EmissionModule fxEmissionModule;

		private float fxEmissionMaxRate;

		private ParticleSystem.ShapeModule fxShapeModule;

		private float fxShapeMaxRadius;

		private bool hasAudio;

		private float audioMaxVolume;

		protected void Awake()
		{
			if (!appIsQuittingHandlerIsSubscribed)
			{
				appIsQuittingHandlerIsSubscribed = true;
				UnityEngine.Application.quitting += HandleApplicationQuitting;
			}
			hasFX = fx != null;
			if (hasFX)
			{
				fxEmissionModule = fx.emission;
				fxEmissionMaxRate = fxEmissionModule.rateOverTimeMultiplier;
				fxShapeModule = fx.shape;
				fxShapeMaxRadius = fxShapeModule.radius;
			}
			hasAudio = loopAudio != null;
			if (hasAudio)
			{
				audioMaxVolume = loopAudio.volume;
				loopAudio.volume = 0f;
				loopAudio.loop = true;
				loopAudio.GTPlay();
			}
		}

		protected void OnEnable()
		{
			if (!appIsQuitting)
			{
				if (hasFX)
				{
					fxEmissionModule.rateOverTimeMultiplier = 0f;
				}
				if (hasAudio)
				{
					loopAudio.volume = 0f;
					loopAudio.loop = true;
					loopAudio.GTPlay();
				}
				ValidateLineCastPositions();
			}
		}

		protected void OnDisable()
		{
			if (!appIsQuitting)
			{
				if (hasFX)
				{
					fxEmissionModule.rateOverTimeMultiplier = 0f;
				}
				if (hasAudio)
				{
					loopAudio.volume = 0f;
					loopAudio.GTStop();
				}
			}
		}

		protected void LateUpdate()
		{
			if (!appIsQuitting)
			{
				Transform transform = base.transform;
				RaycastHit hitInfo;
				UnityEngine.Vector3 position = (Physics.Linecast(transform.TransformPoint(lineCastStart), transform.TransformPoint(lineCastEnd), out hitInfo, lineCastLayerMask, QueryTriggerInteraction.Ignore) ? hitInfo.point : lineCastEnd);
				UnityEngine.Vector3 vector = transform.InverseTransformPoint(position);
				float num = Mathf.Clamp01(UnityEngine.Vector3.Distance(lineCastStart, vector) / maxDepth);
				if (hasFX)
				{
					fxEmissionModule.rateOverTimeMultiplier = fxEmissionMaxRate * fxEmissionCurve.Evaluate(num);
					fxShapeModule.position = vector;
					fxShapeModule.radius = Mathf.Lerp(fxShapeMaxRadius, fxMinRadiusScale * fxShapeMaxRadius, num);
				}
				if (hasAudio)
				{
					loopAudio.volume = Mathf.MoveTowards(loopAudio.volume, audioMaxVolume * loopAudioVolumeCurve.Evaluate(num), loopAudioVolumeTransitionSpeed * Time.deltaTime);
				}
			}
		}

		private static void HandleApplicationQuitting()
		{
			appIsQuitting = true;
		}

		private bool ValidateLineCastPositions()
		{
			maxDepth = UnityEngine.Vector3.Distance(lineCastStart, lineCastEnd);
			if (maxDepth > float.Epsilon)
			{
				return true;
			}
			if (UnityEngine.Application.isPlaying)
			{
				UnityEngine.Debug.Log("DrillFX: lineCastStart and End are too close together. Disabling component.", this);
				base.enabled = false;
			}
			return false;
		}
	}
	public class EdibleWearable : MonoBehaviour
	{
		[Serializable]
		public struct EdibleStateInfo
		{
			[Tooltip("Will be activated when this stage is reached.")]
			public GameObject gameObject;

			[Tooltip("Will be played when this stage is reached.")]
			public AudioClip sound;
		}

		[Tooltip("Check when using non cosmetic edible items like honeycomb")]
		public bool isNonRespawnable;

		[Tooltip("Eating sounds are played through this AudioSource using PlayOneShot.")]
		public AudioSource audioSource;

		[Tooltip("Volume each bite should play at.")]
		public float volume = 0.08f;

		[Tooltip("The slot this cosmetic resides.")]
		public VRRig.WearablePackedStateSlots wearablePackedStateSlot = VRRig.WearablePackedStateSlots.LeftHand;

		[Tooltip("Time between bites.")]
		public float biteCooldown = 1f;

		[Tooltip("How long it takes to pop back to the uneaten state after being fully eaten.")]
		public float respawnTime = 7f;

		[Tooltip("Distance from mouth to item required to trigger a bite.")]
		public float biteDistance = 0.5f;

		[Tooltip("Offset from Gorilla's head to mouth.")]
		public UnityEngine.Vector3 gorillaHeadMouthOffset = new UnityEngine.Vector3(0f, 0.0208f, 0.171f);

		[Tooltip("Offset from edible's transform to the bite point.")]
		public UnityEngine.Vector3 edibleBiteOffset = new UnityEngine.Vector3(0f, 0f, 0f);

		public EdibleStateInfo[] edibleStateInfos;

		private VRRig ownerRig;

		private bool isLocal;

		private bool isHandSlot;

		private bool isLeftHand;

		private GTBitOps.BitWriteInfo stateBitsWriteInfo;

		private int edibleState;

		private int previousEdibleState;

		private float lastEatTime;

		private float lastFullyEatenTime;

		private bool wasInBiteZoneLastFrame;

		protected void Awake()
		{
			edibleState = 0;
			previousEdibleState = 0;
			ownerRig = GetComponentInParent<VRRig>();
			isLocal = ownerRig != null && ownerRig.isOfflineVRRig;
			isHandSlot = wearablePackedStateSlot == VRRig.WearablePackedStateSlots.LeftHand || wearablePackedStateSlot == VRRig.WearablePackedStateSlots.RightHand;
			isLeftHand = wearablePackedStateSlot == VRRig.WearablePackedStateSlots.LeftHand;
			stateBitsWriteInfo = VRRig.WearablePackedStatesBitWriteInfos[(int)wearablePackedStateSlot];
		}

		protected void OnEnable()
		{
			if (ownerRig == null)
			{
				UnityEngine.Debug.LogError("EdibleWearable \"" + base.transform.GetPath() + "\": Deactivating because ownerRig is null.", this);
				base.gameObject.SetActive(value: false);
				return;
			}
			for (int i = 0; i < edibleStateInfos.Length; i++)
			{
				edibleStateInfos[i].gameObject.SetActive(i == edibleState);
			}
		}

		protected virtual void LateUpdate()
		{
			if (isLocal)
			{
				LateUpdateLocal();
			}
			else
			{
				LateUpdateReplicated();
			}
			LateUpdateShared();
		}

		protected virtual void LateUpdateLocal()
		{
			if (edibleState == edibleStateInfos.Length - 1)
			{
				if (!isNonRespawnable && Time.time > lastFullyEatenTime + respawnTime)
				{
					edibleState = 0;
					previousEdibleState = 0;
					OnEdibleHoldableStateChange();
				}
				if (isNonRespawnable && Time.time > lastFullyEatenTime)
				{
					edibleState = 0;
					previousEdibleState = 0;
					OnEdibleHoldableStateChange();
					GorillaGameManager.instance.FindPlayerVRRig(NetworkSystem.Instance.LocalPlayer).netView.SendRPC("EnableNonCosmeticHandItemRPC", RpcTarget.All, false, isLeftHand);
				}
			}
			else if (Time.time > lastEatTime + biteCooldown)
			{
				UnityEngine.Vector3 vector = base.transform.TransformPoint(edibleBiteOffset);
				bool flag = false;
				float num = biteDistance * biteDistance;
				if (!GorillaParent.hasInstance)
				{
					return;
				}
				if ((GorillaTagger.Instance.offlineVRRig.head.rigTarget.transform.TransformPoint(gorillaHeadMouthOffset) - vector).sqrMagnitude < num)
				{
					flag = true;
				}
				foreach (RigContainer activeRigContainer in VRRigCache.ActiveRigContainers)
				{
					VRRig rig = activeRigContainer.Rig;
					if (!flag)
					{
						if (rig.head == null || GTExt.IsNull(rig.head.rigTarget))
						{
							break;
						}
						if ((rig.head.rigTarget.transform.TransformPoint(gorillaHeadMouthOffset) - vector).sqrMagnitude < num)
						{
							flag = true;
						}
					}
				}
				if (flag && !wasInBiteZoneLastFrame && edibleState < edibleStateInfos.Length)
				{
					edibleState++;
					lastEatTime = Time.time;
					lastFullyEatenTime = Time.time;
				}
				wasInBiteZoneLastFrame = flag;
			}
			ownerRig.WearablePackedStates = GTBitOps.WriteBits(ownerRig.WearablePackedStates, stateBitsWriteInfo, edibleState);
		}

		protected virtual void LateUpdateReplicated()
		{
			edibleState = GTBitOps.ReadBits(ownerRig.WearablePackedStates, stateBitsWriteInfo.index, stateBitsWriteInfo.valueMask);
		}

		protected virtual void LateUpdateShared()
		{
			int num = edibleState;
			if (num != previousEdibleState)
			{
				OnEdibleHoldableStateChange();
			}
			previousEdibleState = num;
		}

		protected virtual void OnEdibleHoldableStateChange()
		{
			if (previousEdibleState >= 0 && previousEdibleState < edibleStateInfos.Length)
			{
				edibleStateInfos[previousEdibleState].gameObject.SetActive(value: false);
			}
			if (edibleState >= 0 && edibleState < edibleStateInfos.Length)
			{
				edibleStateInfos[edibleState].gameObject.SetActive(value: true);
			}
			if (edibleState > 0 && edibleState < edibleStateInfos.Length && audioSource != null)
			{
				audioSource.GTPlayOneShot(edibleStateInfos[edibleState].sound, volume);
			}
			if (edibleState == edibleStateInfos.Length && audioSource != null)
			{
				audioSource.GTPlayOneShot(edibleStateInfos[edibleState - 1].sound, volume);
			}
			float amplitude = GorillaTagger.Instance.tapHapticStrength / 4f;
			float fixedDeltaTime = Time.fixedDeltaTime;
			if (isLocal && isHandSlot)
			{
				GorillaTagger.Instance.StartVibration(isLeftHand, amplitude, fixedDeltaTime);
			}
		}
	}
	public class HeadlessHead : HoldableObject
	{
		[Tooltip("The slot this cosmetic resides.")]
		public VRRig.WearablePackedStateSlots wearablePackedStateSlot = VRRig.WearablePackedStateSlots.Face;

		[SerializeField]
		private UnityEngine.Vector3 offsetFromLeftHand = new UnityEngine.Vector3(0f, 0.0208f, 0.171f);

		[SerializeField]
		private UnityEngine.Vector3 offsetFromRightHand = new UnityEngine.Vector3(0f, 0.0208f, 0.171f);

		[SerializeField]
		private UnityEngine.Quaternion rotationFromLeftHand = UnityEngine.Quaternion.Euler(14.063973f, 52.56744f, 10.067408f);

		[SerializeField]
		private UnityEngine.Quaternion rotationFromRightHand = UnityEngine.Quaternion.Euler(14.063973f, 52.56744f, 10.067408f);

		private UnityEngine.Vector3 baseLocalPosition;

		private VRRig ownerRig;

		private bool isLocal;

		private bool isHeld;

		private bool isHeldLeftHand;

		private GTBitOps.BitWriteInfo stateBitsWriteInfo;

		[SerializeField]
		private MeshRenderer firstPersonRenderer;

		[SerializeField]
		private float firstPersonHiddenRadius;

		[SerializeField]
		private Transform firstPersonHideCenter;

		[SerializeField]
		private Transform holdAnchorPoint;

		private bool hasFirstPersonRenderer;

		private UnityEngine.Vector3 blendingFromPosition;

		private UnityEngine.Quaternion blendingFromRotation;

		private float blendFraction;

		private bool wasHeld;

		private bool wasHeldLeftHand;

		[SerializeField]
		private float blendDuration = 0.3f;

		protected void Awake()
		{
			ownerRig = GetComponentInParent<VRRig>();
			if (ownerRig == null)
			{
				ownerRig = GorillaTagger.Instance.offlineVRRig;
			}
			isLocal = ownerRig.isOfflineVRRig;
			stateBitsWriteInfo = VRRig.WearablePackedStatesBitWriteInfos[(int)wearablePackedStateSlot];
			baseLocalPosition = base.transform.localPosition;
			hasFirstPersonRenderer = firstPersonRenderer != null;
		}

		protected void OnEnable()
		{
			if (ownerRig == null)
			{
				UnityEngine.Debug.LogError("HeadlessHead \"" + base.transform.GetPath() + "\": Deactivating because ownerRig is null.", this);
				base.gameObject.SetActive(value: false);
			}
			else
			{
				ownerRig.bodyRenderer.SetCosmeticBodyType(GorillaBodyType.NoHead);
			}
		}

		private void OnDisable()
		{
			ownerRig.bodyRenderer.SetCosmeticBodyType(GorillaBodyType.Default);
		}

		protected virtual void LateUpdate()
		{
			if (isLocal)
			{
				LateUpdateLocal();
			}
			else
			{
				LateUpdateReplicated();
			}
			LateUpdateShared();
		}

		protected virtual void LateUpdateLocal()
		{
			ownerRig.WearablePackedStates = GTBitOps.WriteBits(ownerRig.WearablePackedStates, stateBitsWriteInfo, (isHeld ? 1 : 0) + (isHeldLeftHand ? 2 : 0));
		}

		protected virtual void LateUpdateReplicated()
		{
			int num = GTBitOps.ReadBits(ownerRig.WearablePackedStates, stateBitsWriteInfo.index, stateBitsWriteInfo.valueMask);
			isHeld = num != 0;
			isHeldLeftHand = (num & 2) != 0;
		}

		protected virtual void LateUpdateShared()
		{
			if (isHeld != wasHeld || isHeldLeftHand != wasHeldLeftHand)
			{
				blendingFromPosition = base.transform.position;
				blendingFromRotation = base.transform.rotation;
				blendFraction = 0f;
			}
			UnityEngine.Quaternion quaternion2;
			UnityEngine.Vector3 vector;
			if (isHeldLeftHand)
			{
				quaternion2 = ownerRig.leftHandTransform.rotation * rotationFromLeftHand;
				vector = ownerRig.leftHandTransform.TransformPoint(offsetFromLeftHand) - quaternion2 * holdAnchorPoint.transform.localPosition;
			}
			else if (isHeld)
			{
				quaternion2 = ownerRig.rightHandTransform.rotation * rotationFromRightHand;
				vector = ownerRig.rightHandTransform.TransformPoint(offsetFromRightHand) - quaternion2 * holdAnchorPoint.transform.localPosition;
			}
			else
			{
				quaternion2 = base.transform.parent.rotation;
				vector = base.transform.parent.TransformPoint(baseLocalPosition);
			}
			if (blendFraction < 1f)
			{
				blendFraction += Time.deltaTime / blendDuration;
				quaternion2 = UnityEngine.Quaternion.Lerp(blendingFromRotation, quaternion2, blendFraction);
				vector = UnityEngine.Vector3.Lerp(blendingFromPosition, vector, blendFraction);
			}
			base.transform.rotation = quaternion2;
			base.transform.position = vector;
			if (hasFirstPersonRenderer)
			{
				float x = base.transform.lossyScale.x;
				firstPersonRenderer.enabled = (firstPersonHideCenter.transform.position - GTPlayer.Instance.headCollider.transform.position).IsLongerThan(firstPersonHiddenRadius * x);
			}
			wasHeld = isHeld;
			wasHeldLeftHand = isHeldLeftHand;
		}

		public override void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
		{
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			isHeld = true;
			isHeldLeftHand = grabbingHand == EquipmentInteractor.instance.leftHand;
			EquipmentInteractor.instance.UpdateHandEquipment(this, isHeldLeftHand);
		}

		public override void DropItemCleanup()
		{
			isHeld = false;
			isHeldLeftHand = false;
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (EquipmentInteractor.instance.rightHandHeldEquipment == this && releasingHand != EquipmentInteractor.instance.rightHand)
			{
				return false;
			}
			if (EquipmentInteractor.instance.leftHandHeldEquipment == this && releasingHand != EquipmentInteractor.instance.leftHand)
			{
				return false;
			}
			EquipmentInteractor.instance.UpdateHandEquipment(null, isHeldLeftHand);
			isHeld = false;
			isHeldLeftHand = false;
			return true;
		}
	}
	public class NetworkedWearable : MonoBehaviour, ISpawnable, ITickSystemTick
	{
		[Tooltip("Whether the wearable state is toggled on by default.")]
		[SerializeField]
		private bool startTrue;

		[Tooltip("This is to determine what bit to change in VRRig.WearablesPackedStates.")]
		[SerializeField]
		private CosmeticsController.CosmeticCategory assignedSlot;

		[FormerlySerializedAs("IsTwoHanded")]
		[SerializeField]
		private bool isTwoHanded;

		private const string listenInfo = "listenForChangesLocal should be false in most cases";

		private const string listenDetails = "listenForChangesLocal should be false in most cases\nIf you have a first person part and a local rig part that both need to react to a state change\ncall the Toggle/Set functions to change the state from one prefab and check \nlistenForChangesLocal on the other prefab ";

		[SerializeField]
		private bool listenForChangesLocal;

		private VRRig.WearablePackedStateSlots wearableSlot;

		private VRRig.WearablePackedStateSlots leftSlot = VRRig.WearablePackedStateSlots.LeftHand;

		private VRRig.WearablePackedStateSlots rightSlot = VRRig.WearablePackedStateSlots.RightHand;

		private VRRig myRig;

		private bool isLocal;

		private bool value;

		private bool leftHandValue;

		private bool rightHandValue;

		[SerializeField]
		protected UnityEvent OnWearableStateTrue;

		[SerializeField]
		protected UnityEvent OnWearableStateFalse;

		[SerializeField]
		protected UnityEvent OnLeftWearableStateTrue;

		[SerializeField]
		protected UnityEvent OnLeftWearableStateFalse;

		[SerializeField]
		protected UnityEvent OnRightWearableStateTrue;

		[SerializeField]
		protected UnityEvent OnRightWearableStateFalse;

		public bool IsSpawned { get; set; }

		public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

		public bool TickRunning { get; set; }

		private void Awake()
		{
			if (assignedSlot != CosmeticsController.CosmeticCategory.Paw)
			{
				isTwoHanded = false;
			}
			wearableSlot = CosmeticCategoryToWearableSlot(assignedSlot, isLeft: true);
			leftSlot = CosmeticCategoryToWearableSlot(assignedSlot, isLeft: true);
			rightSlot = CosmeticCategoryToWearableSlot(assignedSlot, isLeft: false);
		}

		private void OnEnable()
		{
			if (IsSpawned)
			{
				if (isLocal && !listenForChangesLocal)
				{
					SetWearableStateBool(startTrue);
				}
				else if (!TickRunning)
				{
					TickSystem<object>.AddTickCallback(this);
				}
			}
		}

		public void ToggleWearableStateBool()
		{
			if (isLocal && IsSpawned && IsCategoryValid(assignedSlot) && !(myRig == null))
			{
				if (listenForChangesLocal)
				{
					GTDev.LogError("NetworkedWearable with listenForChangesLocal calling ToggleWearableStateBool on object " + base.gameObject.name + ".You should not change state from a listener");
				}
				else if (assignedSlot == CosmeticsController.CosmeticCategory.Paw && isTwoHanded)
				{
					GTDev.LogWarning("NetworkedWearable calling ToggleWearableStateBool on two handed object " + base.gameObject.name + ". please use ToggleLeftWearableStateBool or ToggleRightWearableStateBool instead");
					ToggleLeftWearableStateBool();
				}
				else
				{
					value = !value;
					myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, (int)wearableSlot, value);
					OnWearableStateChanged();
				}
			}
		}

		public void SetWearableStateBool(bool newState)
		{
			if (isLocal && IsSpawned && IsCategoryValid(assignedSlot) && !(myRig == null))
			{
				if (listenForChangesLocal)
				{
					GTDev.LogError("NetworkedWearable with listenForChangesLocal calling SetWearableStateBool on object " + base.gameObject.name + ".You should not change state from a listener");
				}
				else if (assignedSlot == CosmeticsController.CosmeticCategory.Paw && isTwoHanded)
				{
					GTDev.LogWarning("NetworkedWearable calling SetWearableStateBool on two handed object " + base.gameObject.name + ". please use SetLeftWearableStateBool or SetRightWearableStateBool instead");
					SetLeftWearableStateBool(newState);
				}
				else if (value != newState)
				{
					value = newState;
					myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, (int)wearableSlot, value);
					OnWearableStateChanged();
				}
			}
		}

		public void ToggleLeftWearableStateBool()
		{
			if (isLocal && IsSpawned && IsCategoryValid(assignedSlot) && !(myRig == null))
			{
				if (listenForChangesLocal)
				{
					GTDev.LogError("NetworkedWearable with listenForChangesLocal calling ToggleLeftWearableStateBool on object " + base.gameObject.name + ".You should not change state from a listener");
				}
				else if (assignedSlot != CosmeticsController.CosmeticCategory.Paw || !isTwoHanded)
				{
					GTDev.LogWarning("NetworkedWearable calling ToggleLeftWearableStateBool on one handed object " + base.gameObject.name + ". Please use ToggleWearableStateBool instead");
					ToggleWearableStateBool();
				}
				else
				{
					leftHandValue = !leftHandValue;
					myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, (int)leftSlot, leftHandValue);
					OnLeftStateChanged();
				}
			}
		}

		public void ToggleRightWearableStateBool()
		{
			if (isLocal && IsSpawned && IsCategoryValid(assignedSlot) && !(myRig == null))
			{
				if (listenForChangesLocal)
				{
					GTDev.LogError("NetworkedWearable with listenForChangesLocal calling ToggleRightWearableStateBool on object " + base.gameObject.name + ".You should not change state from a listener");
				}
				else if (assignedSlot != CosmeticsController.CosmeticCategory.Paw || !isTwoHanded)
				{
					GTDev.LogWarning("NetworkedWearable calling ToggleRightWearableStateBool on one handed object " + base.gameObject.name + ". Please use ToggleWearableStateBool instead");
					ToggleWearableStateBool();
				}
				else
				{
					rightHandValue = !rightHandValue;
					myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, (int)rightSlot, rightHandValue);
					OnRightStateChanged();
				}
			}
		}

		public void SetLeftWearableStateBool(bool newState)
		{
			if (isLocal && IsSpawned && IsCategoryValid(assignedSlot) && !(myRig == null))
			{
				if (listenForChangesLocal)
				{
					GTDev.LogError("NetworkedWearable with listenForChangesLocal calling SetLeftWearableStateBool on object " + base.gameObject.name + ".You should not change state from a listener");
				}
				else if (assignedSlot != CosmeticsController.CosmeticCategory.Paw || !isTwoHanded)
				{
					GTDev.LogWarning("NetworkedWearable calling SetLeftWearableStateBool on one handed object " + base.gameObject.name + ". Please use SetWearableStateBool instead");
					SetWearableStateBool(newState);
				}
				else if (leftHandValue != newState)
				{
					leftHandValue = newState;
					myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, (int)leftSlot, leftHandValue);
					OnLeftStateChanged();
				}
			}
		}

		public void SetRightWearableStateBool(bool newState)
		{
			if (isLocal && IsSpawned && IsCategoryValid(assignedSlot) && !(myRig == null))
			{
				if (listenForChangesLocal)
				{
					GTDev.LogError("NetworkedWearable with listenForChangesLocal calling SetRightWearableStateBool on object " + base.gameObject.name + ".You should not change state from a listener");
				}
				else if (assignedSlot != CosmeticsController.CosmeticCategory.Paw || !isTwoHanded)
				{
					GTDev.LogWarning("NetworkedWearable calling SetRightWearableStateBool on one handed object " + base.gameObject.name + ". Please use SetWearableStateBool instead");
					SetWearableStateBool(newState);
				}
				else if (rightHandValue != newState)
				{
					rightHandValue = newState;
					myRig.WearablePackedStates = GTBitOps.WriteBit(myRig.WearablePackedStates, (int)rightSlot, rightHandValue);
					OnRightStateChanged();
				}
			}
		}

		public void OnDisable()
		{
			if (isLocal && !listenForChangesLocal)
			{
				SetWearableStateBool(newState: false);
			}
			else if (TickRunning)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
		}

		private void OnWearableStateChanged()
		{
			if (value)
			{
				OnWearableStateTrue?.Invoke();
			}
			else
			{
				OnWearableStateFalse?.Invoke();
			}
		}

		private void OnLeftStateChanged()
		{
			if (leftHandValue)
			{
				OnLeftWearableStateTrue?.Invoke();
			}
			else
			{
				OnLeftWearableStateFalse?.Invoke();
			}
		}

		private void OnRightStateChanged()
		{
			if (rightHandValue)
			{
				OnRightWearableStateTrue?.Invoke();
			}
			else
			{
				OnRightWearableStateFalse?.Invoke();
			}
		}

		public void OnSpawn(VRRig rig)
		{
			if (assignedSlot == CosmeticsController.CosmeticCategory.Paw && CosmeticSelectedSide == ECosmeticSelectSide.Both)
			{
				GTDev.LogWarning($"NetworkedWearable: Cosmetic {base.gameObject.name} with category {assignedSlot} has select side Both, assuming left side!");
			}
			if (!IsCategoryValid(assignedSlot))
			{
				GTDev.LogError($"NetworkedWearable: Cosmetic {base.gameObject.name} spawned with invalid category {assignedSlot}!");
			}
			myRig = rig;
			isLocal = rig.isLocal;
			wearableSlot = CosmeticCategoryToWearableSlot(assignedSlot, CosmeticSelectedSide != ECosmeticSelectSide.Right);
		}

		public void OnDespawn()
		{
		}

		public void Tick()
		{
			if ((isLocal && !listenForChangesLocal) || !IsSpawned)
			{
				return;
			}
			if (assignedSlot == CosmeticsController.CosmeticCategory.Paw && isTwoHanded)
			{
				bool flag = GTBitOps.ReadBit(myRig.WearablePackedStates, (int)leftSlot);
				if (leftHandValue != flag)
				{
					leftHandValue = flag;
					OnLeftStateChanged();
				}
				flag = GTBitOps.ReadBit(myRig.WearablePackedStates, (int)rightSlot);
				if (rightHandValue != flag)
				{
					rightHandValue = flag;
					OnRightStateChanged();
				}
			}
			else
			{
				bool flag2 = GTBitOps.ReadBit(myRig.WearablePackedStates, (int)wearableSlot);
				if (value != flag2)
				{
					value = flag2;
					OnWearableStateChanged();
				}
			}
		}

		public static bool IsCategoryValid(CosmeticsController.CosmeticCategory category)
		{
			switch (category)
			{
			case CosmeticsController.CosmeticCategory.Hat:
			case CosmeticsController.CosmeticCategory.Badge:
			case CosmeticsController.CosmeticCategory.Face:
			case CosmeticsController.CosmeticCategory.Paw:
			case CosmeticsController.CosmeticCategory.Fur:
			case CosmeticsController.CosmeticCategory.Shirt:
			case CosmeticsController.CosmeticCategory.Pants:
				return true;
			default:
				return false;
			}
		}

		private VRRig.WearablePackedStateSlots CosmeticCategoryToWearableSlot(CosmeticsController.CosmeticCategory category, bool isLeft)
		{
			switch (category)
			{
			case CosmeticsController.CosmeticCategory.Hat:
				return VRRig.WearablePackedStateSlots.Hat;
			case CosmeticsController.CosmeticCategory.Badge:
				return VRRig.WearablePackedStateSlots.Badge;
			case CosmeticsController.CosmeticCategory.Face:
				return VRRig.WearablePackedStateSlots.Face;
			case CosmeticsController.CosmeticCategory.Paw:
				if (!isLeft)
				{
					return VRRig.WearablePackedStateSlots.RightHand;
				}
				return VRRig.WearablePackedStateSlots.LeftHand;
			case CosmeticsController.CosmeticCategory.Fur:
				return VRRig.WearablePackedStateSlots.Fur;
			case CosmeticsController.CosmeticCategory.Shirt:
				return VRRig.WearablePackedStateSlots.Shirt;
			case CosmeticsController.CosmeticCategory.Pants:
				return VRRig.WearablePackedStateSlots.Pants1;
			default:
				GTDev.LogWarning($"NetworkedWearable: {category} item cannot set wearable state");
				return VRRig.WearablePackedStateSlots.Hat;
			}
		}
	}
	public class BackpackGrabbableCosmetic : HoldableObject
	{
		[GorillaSoundLookup]
		public int materialIndex;

		[SerializeField]
		private bool useCapacity = true;

		[SerializeField]
		private float coolDownTimer = 2f;

		[SerializeField]
		private int maxCapacity;

		[SerializeField]
		private int startItemsCount;

		[Space]
		public UnityEvent OnReachedMaxCapacity;

		public UnityEvent OnFullyEmptied;

		public UnityEvent OnRefilled;

		private int currentItemsCount;

		private bool canGrab;

		private float lastGrabTime;

		private void Awake()
		{
			currentItemsCount = startItemsCount;
			canGrab = true;
		}

		public override void OnHover(InteractionPoint pointHovered, GameObject hoveringHand)
		{
		}

		public override void DropItemCleanup()
		{
		}

		public void Update()
		{
			if (!canGrab && Time.time - lastGrabTime >= coolDownTimer)
			{
				canGrab = true;
			}
		}

		public override void OnGrab(InteractionPoint pointGrabbed, GameObject grabbingHand)
		{
			if (IsEmpty())
			{
				UnityEngine.Debug.LogWarning("Can't remove item, Backpack is empty, need to refill.");
			}
			else if (canGrab)
			{
				lastGrabTime = Time.time;
				canGrab = false;
				((grabbingHand == EquipmentInteractor.instance.leftHand) ? SnowballMaker.leftHandInstance : SnowballMaker.rightHandInstance).TryCreateSnowball(materialIndex, out var _);
				RemoveItem();
			}
		}

		public void AddItem()
		{
			if (useCapacity)
			{
				if (maxCapacity <= currentItemsCount)
				{
					UnityEngine.Debug.LogWarning("Can't add item, backpack is at full capacity.");
					return;
				}
				currentItemsCount++;
				UpdateState();
			}
		}

		public void RemoveItem()
		{
			if (useCapacity)
			{
				if (currentItemsCount < 0)
				{
					UnityEngine.Debug.LogWarning("Can't remove item, Backpack is empty.");
					return;
				}
				currentItemsCount--;
				UpdateState();
			}
		}

		public void RefillBackpack()
		{
			if (useCapacity && currentItemsCount != startItemsCount)
			{
				currentItemsCount = startItemsCount;
				UpdateState();
			}
		}

		public void EmptyBackpack()
		{
			if (useCapacity && currentItemsCount != 0)
			{
				currentItemsCount = 0;
				UpdateState();
			}
		}

		public bool IsFull()
		{
			if (!useCapacity || maxCapacity == currentItemsCount)
			{
				return true;
			}
			return false;
		}

		public bool IsEmpty()
		{
			if (useCapacity && currentItemsCount == 0)
			{
				return true;
			}
			return false;
		}

		private void UpdateState()
		{
			if (useCapacity)
			{
				if (currentItemsCount == maxCapacity)
				{
					OnReachedMaxCapacity?.Invoke();
				}
				else if (currentItemsCount == 0)
				{
					OnFullyEmptied?.Invoke();
				}
				else if (currentItemsCount == startItemsCount)
				{
					OnRefilled?.Invoke();
				}
			}
		}
	}
	public class ChargeableCosmeticEffects : MonoBehaviour, ITickSystemTick
	{
		[SerializeField]
		private float maxChargeSeconds = 1f;

		[SerializeField]
		private float chargeGainSpeed = 1f;

		[SerializeField]
		private float chargeLossSpeed = 1f;

		[Tooltip("This will remap the internal charge output to whatever you set. The remapped value will be output by 'whileCharging' and the 'continuousProperties' (keep in mind that the remapped value will then be used as an INPUT for the curves on each ContinuousProperty).\n\nIt should start at (0,0) and end at (1,1).\n\nDisabled if there are no ContinuousProperties and no whileCharging event callbacks.")]
		[SerializeField]
		private AnimationCurve masterChargeRemapCurve = AnimationCurves.Linear;

		[SerializeField]
		private bool isCharging;

		[SerializeField]
		private ContinuousPropertyArray continuousProperties;

		[SerializeField]
		private UnityEvent<float> whileCharging;

		[SerializeField]
		private UnityEvent onMaxCharge;

		[SerializeField]
		private UnityEvent onNoCharge;

		private float chargeTime;

		private float inverseMaxChargeSeconds;

		private bool hasFractionalsCached;

		public bool TickRunning { get; set; }

		private bool HasFractionals()
		{
			if (continuousProperties.Count <= 0)
			{
				return whileCharging.GetPersistentEventCount() > 0;
			}
			return true;
		}

		private void Awake()
		{
			inverseMaxChargeSeconds = 1f / maxChargeSeconds;
			hasFractionalsCached = HasFractionals();
		}

		public void SetMaxChargeSeconds(float s)
		{
			maxChargeSeconds = s;
			inverseMaxChargeSeconds = 1f / maxChargeSeconds;
			SetChargeTime(chargeTime);
		}

		public void SetChargeState(bool state)
		{
			if (isCharging != state)
			{
				TickSystem<object>.AddTickCallback(this);
				isCharging = state;
			}
		}

		public void StartCharging()
		{
			SetChargeState(state: true);
		}

		public void StopCharging()
		{
			SetChargeState(state: false);
		}

		public void ToggleCharging()
		{
			SetChargeState(!isCharging);
		}

		public void SetChargeTime(float t)
		{
			if (t >= maxChargeSeconds)
			{
				if (chargeTime < maxChargeSeconds)
				{
					RunMaxCharge();
				}
				return;
			}
			if (t <= 0f)
			{
				if (chargeTime > 0f)
				{
					RunNoCharge();
				}
				return;
			}
			TickSystem<object>.AddTickCallback(this);
			chargeTime = t;
			if (hasFractionalsCached)
			{
				RunChargeFrac();
			}
		}

		public void SetChargeFrac(float f)
		{
			SetChargeTime(f * maxChargeSeconds);
		}

		public void EmptyCharge()
		{
			SetChargeTime(0f);
		}

		public void FillCharge()
		{
			SetChargeTime(maxChargeSeconds);
		}

		public void EmptyAndStop()
		{
			isCharging = false;
			EmptyCharge();
		}

		public void FillAndStop()
		{
			StopCharging();
			FillCharge();
		}

		public void EmptyAndStart()
		{
			StartCharging();
			EmptyCharge();
		}

		public void FillAndStart()
		{
			isCharging = true;
			FillCharge();
		}

		private void OnEnable()
		{
			if ((chargeTime <= 0f && isCharging) || (chargeTime >= maxChargeSeconds && !isCharging) || (chargeTime > 0f && chargeTime < maxChargeSeconds))
			{
				TickSystem<object>.AddTickCallback(this);
			}
		}

		private void OnDisable()
		{
			TickSystem<object>.RemoveTickCallback(this);
		}

		private void RunMaxCharge()
		{
			if (isCharging)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
			else
			{
				TickSystem<object>.AddTickCallback(this);
			}
			chargeTime = maxChargeSeconds;
			onMaxCharge?.Invoke();
			whileCharging?.Invoke(1f);
			continuousProperties.ApplyAll(1f);
		}

		private void RunNoCharge()
		{
			if (!isCharging)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
			else
			{
				TickSystem<object>.AddTickCallback(this);
			}
			chargeTime = 0f;
			onNoCharge?.Invoke();
			whileCharging?.Invoke(0f);
			continuousProperties.ApplyAll(0f);
		}

		private void RunChargeFrac()
		{
			float num = masterChargeRemapCurve.Evaluate(chargeTime * inverseMaxChargeSeconds);
			whileCharging?.Invoke(num);
			continuousProperties.ApplyAll(num);
		}

		public void Tick()
		{
			if (isCharging && chargeTime < maxChargeSeconds)
			{
				chargeTime += Time.deltaTime * chargeGainSpeed;
				if (chargeTime >= maxChargeSeconds)
				{
					RunMaxCharge();
				}
				else if (hasFractionalsCached)
				{
					RunChargeFrac();
				}
			}
			else if (!isCharging && chargeTime > 0f)
			{
				chargeTime -= Time.deltaTime * chargeLossSpeed;
				if (chargeTime <= 0f)
				{
					RunNoCharge();
				}
				else if (hasFractionalsCached)
				{
					RunChargeFrac();
				}
			}
		}
	}
	public class ChickenSword : MonoBehaviour
	{
		private enum SwordState
		{
			Ready,
			Deflated
		}

		[SerializeField]
		private float rechargeCooldown;

		[SerializeField]
		private GorillaVelocityTracker velocityTracker;

		[SerializeField]
		private float hitVelocityThreshold;

		[SerializeField]
		private TransferrableObject transferrableObject;

		[SerializeField]
		private CosmeticSwapper cosmeticSwapper;

		[Space]
		[Space]
		public UnityEvent OnDeflatedShared;

		public UnityEvent<bool> OnDeflatedLocal;

		public UnityEvent OnRechargedShared;

		public UnityEvent<bool> OnRechargedLocal;

		public UnityEvent<VRRig> OnHitTargetShared;

		public UnityEvent<bool> OnHitTargetLocal;

		public UnityEvent<VRRig> OnReachedLastTransformationStepShared;

		private float lastHitTime;

		private SwordState currentState;

		private bool hitReceievd;

		private RubberDuckEvents _events;

		private CallLimiter callLimiter = new CallLimiter(10, 2f);

		private void Awake()
		{
			lastHitTime = float.PositiveInfinity;
			SwitchState(SwordState.Ready);
		}

		internal void OnEnable()
		{
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((transferrableObject.myOnlineRig != null) ? transferrableObject.myOnlineRig.creator : ((!(transferrableObject.myRig != null)) ? null : ((transferrableObject.myRig.creator != null) ? transferrableObject.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to get a reference to the Photon Player needed to hook up the cosmetic event");
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnReachedLastTransformationStep);
			}
		}

		private void OnDisable()
		{
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnReachedLastTransformationStep);
				_events.Dispose();
				_events = null;
			}
		}

		private void Update()
		{
			switch (currentState)
			{
			case SwordState.Ready:
				if (hitReceievd)
				{
					hitReceievd = false;
					lastHitTime = Time.time;
					SwitchState(SwordState.Deflated);
					OnDeflatedShared?.Invoke();
					if ((bool)transferrableObject && transferrableObject.IsMyItem())
					{
						OnDeflatedLocal?.Invoke(transferrableObject.InLeftHand());
					}
				}
				break;
			case SwordState.Deflated:
				if (Time.time - lastHitTime > rechargeCooldown)
				{
					lastHitTime = float.PositiveInfinity;
					SwitchState(SwordState.Ready);
					OnRechargedShared?.Invoke();
					if ((bool)transferrableObject && transferrableObject.IsMyItem())
					{
						OnRechargedLocal?.Invoke(transferrableObject.InLeftHand());
					}
				}
				break;
			}
		}

		public void OnHitTargetSync(VRRig playerRig)
		{
			if (velocityTracker == null)
			{
				return;
			}
			UnityEngine.Vector3 averageVelocity = velocityTracker.GetAverageVelocity(worldSpace: true);
			if (currentState == SwordState.Ready && averageVelocity.magnitude > hitVelocityThreshold)
			{
				hitReceievd = true;
				OnHitTargetShared?.Invoke(playerRig);
				if ((bool)transferrableObject && transferrableObject.IsMyItem())
				{
					bool arg = transferrableObject.InLeftHand();
					OnHitTargetLocal?.Invoke(arg);
				}
				if (cosmeticSwapper != null && playerRig == GorillaTagger.Instance.offlineVRRig && cosmeticSwapper.GetCurrentStepIndex(playerRig) >= cosmeticSwapper.GetNumberOfSteps() && PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					_events.Activate.RaiseAll();
				}
			}
		}

		private void OnReachedLastTransformationStep(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender == target)
			{
				MonkeAgent.IncrementRPCCall(info, "OnReachedLastTransformationStep");
				if (callLimiter.CheckCallTime(Time.time) && VRRigCache.Instance.TryGetVrrig(NetworkSystem.Instance.GetPlayer(info.Sender.ActorNumber), out var playerRig) && playerRig.Rig.IsPositionInRange(base.transform.position, 6f))
				{
					OnReachedLastTransformationStepShared?.Invoke(playerRig.Rig);
				}
			}
		}

		private void SwitchState(SwordState newState)
		{
			currentState = newState;
		}
	}
	public class CloserCosmetic : MonoBehaviour, ITickSystemTick
	{
		private enum State
		{
			Closing,
			Opening,
			None
		}

		[SerializeField]
		private GameObject sideA;

		[SerializeField]
		private GameObject sideB;

		[SerializeField]
		private UnityEngine.Vector3 maxRotationA;

		[SerializeField]
		private UnityEngine.Vector3 maxRotationB;

		[SerializeField]
		private bool useFingerFlexValueAsStrength;

		private UnityEngine.Quaternion localRotA;

		private UnityEngine.Quaternion localRotB;

		private State currentState;

		private float fingerValue;

		public bool TickRunning { get; set; }

		private void OnEnable()
		{
			TickSystem<object>.AddCallbackTarget(this);
			localRotA = sideA.transform.localRotation;
			localRotB = sideB.transform.localRotation;
			fingerValue = 0f;
			UpdateState(State.Opening);
		}

		private void OnDisable()
		{
			TickSystem<object>.RemoveCallbackTarget(this);
		}

		public void Tick()
		{
			switch (currentState)
			{
			case State.Closing:
				Closing();
				break;
			case State.Opening:
				Opening();
				break;
			case State.None:
				break;
			}
		}

		public void Close(bool leftHand, float fingerFlexValue)
		{
			UpdateState(State.Closing);
			fingerValue = fingerFlexValue;
		}

		public void Open(bool leftHand, float fingerFlexValue)
		{
			UpdateState(State.Opening);
			fingerValue = fingerFlexValue;
		}

		private void Closing()
		{
			float t = (useFingerFlexValueAsStrength ? Mathf.Clamp01(fingerValue) : 1f);
			UnityEngine.Quaternion b = UnityEngine.Quaternion.Euler(maxRotationB);
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Slerp(localRotB, b, t);
			sideB.transform.localRotation = quaternion2;
			UnityEngine.Quaternion b2 = UnityEngine.Quaternion.Euler(maxRotationA);
			UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.Slerp(localRotA, b2, t);
			sideA.transform.localRotation = quaternion3;
			if (UnityEngine.Quaternion.Angle(sideB.transform.localRotation, quaternion2) < 0.1f && UnityEngine.Quaternion.Angle(sideA.transform.localRotation, quaternion3) < 0.1f)
			{
				UpdateState(State.None);
			}
		}

		private void Opening()
		{
			float t = (useFingerFlexValueAsStrength ? Mathf.Clamp01(fingerValue) : 1f);
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Slerp(sideB.transform.localRotation, localRotB, t);
			sideB.transform.localRotation = quaternion2;
			UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.Slerp(sideA.transform.localRotation, localRotA, t);
			sideA.transform.localRotation = quaternion3;
			if (UnityEngine.Quaternion.Angle(sideB.transform.localRotation, quaternion2) < 0.1f && UnityEngine.Quaternion.Angle(sideA.transform.localRotation, quaternion3) < 0.1f)
			{
				UpdateState(State.None);
			}
		}

		private void UpdateState(State newState)
		{
			currentState = newState;
		}
	}
