				}
			}
			return "Invalid target\n\n" + ListValidCasts();
		}

		public string ListValidCasts()
		{
			return "Valid targets: " + string.Join(", ", castData.Select((CastData x) => x.target));
		}
	}
	public class ContinuousPropertyTimeline : MonoBehaviour, ITickSystemTick, ISpawnable
	{
		private enum TimelineEndBehavior
		{
			Stop,
			Loop,
			PingPong
		}

		[Flags]
		private enum TimelineEvent
		{
			OnReachedEnd = 1,
			OnReachedBeginning = 2,
			OnEnable = 4,
			OnDisable = 8
		}

		[SerializeField]
		private float durationSeconds = 1f;

		[SerializeField]
		private float backwardDuration = 1f;

		[Tooltip("If true, the the timeline can move at a different speed when playing backwards.")]
		[SerializeField]
		private bool separateBackwardDuration;

		[Tooltip("When this object is enabled for the first time, should it immediately start playing from the beginning?")]
		[SerializeField]
		private bool startPlaying;

		[Tooltip("Determine what happens when the timeline reaches the end (or beginning while playing backwards).")]
		[SerializeField]
		private TimelineEndBehavior endBehavior;

		[SerializeField]
		private ContinuousPropertyArray continuousProperties;

		[SerializeField]
		private FlagEvents<TimelineEvent> events;

		private float time;

		private float inverseDuration;

		private float backwardDeltaMult;

		private bool IsForward = true;

		private bool IsPlaying;

		private VRRig myRig;

		private bool IsBackward
		{
			get
			{
				return !IsForward;
			}
			set
			{
				IsForward = !value;
			}
		}

		private bool IsPaused
		{
			get
			{
				return !IsPlaying;
			}
			set
			{
				IsPlaying = !value;
			}
		}

		public bool TickRunning { get; set; }

		public bool IsSpawned { get; set; }

		public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

		public void TimelinePlay()
		{
			IsPlaying = true;
			TickSystem<object>.AddTickCallback(this);
		}

		public void TimelinePause()
		{
			IsPaused = true;
			TickSystem<object>.RemoveTickCallback(this);
		}

		public void TimelineToggleDirection()
		{
			IsForward = !IsForward;
		}

		public void TimelineTogglePlay()
		{
			if (IsPlaying)
			{
				TimelinePause();
			}
			else
			{
				TimelinePlay();
			}
		}

		public void TimelinePlayForward()
		{
			IsForward = true;
			TimelinePlay();
		}

		public void TimelinePlayBackward()
		{
			IsBackward = true;
			TimelinePlay();
		}

		public void TimelinePlayFromBeginning()
		{
			time = 0f;
			TimelinePlayForward();
			OnReachedBeginning();
		}

		public void TimelinePlayFromEnd()
		{
			time = durationSeconds;
			TimelinePlayBackward();
			OnReachedEnd();
		}

		public void TimelineScrubToTime(float t)
		{
			if (t <= 0f)
			{
				time = 0f;
				OnReachedBeginning();
			}
			else if (t >= durationSeconds)
			{
				time = durationSeconds;
				OnReachedEnd();
			}
			else
			{
				time = t;
			}
		}

		public void TimelineScrubToFraction(float f)
		{
			TimelineScrubToTime(f * durationSeconds);
		}

		public void TimelineSetDuration(float d)
		{
			durationSeconds = d;
			inverseDuration = 1f / durationSeconds;
			backwardDeltaMult = durationSeconds / backwardDuration;
		}

		public void TimelineSetBackwardDuration(float d)
		{
			separateBackwardDuration = true;
			backwardDuration = d;
			backwardDeltaMult = durationSeconds / backwardDuration;
		}

		private void Awake()
		{
			IsPlaying = startPlaying;
		}

		private void OnEnable()
		{
			if (myRig == null)
			{
				myRig = GetComponentInParent<VRRig>();
			}
			inverseDuration = 1f / durationSeconds;
			backwardDeltaMult = durationSeconds / backwardDuration;
			events.InvokeAll(TimelineEvent.OnEnable, myRig != null && myRig.isLocal);
			if (IsPlaying)
			{
				TickSystem<object>.AddTickCallback(this);
			}
		}

		private void OnDisable()
		{
			events.InvokeAll(TimelineEvent.OnDisable, myRig != null && myRig.isLocal);
			TickSystem<object>.RemoveTickCallback(this);
		}

		private void OnReachedEnd()
		{
			if (IsForward)
			{
				switch (endBehavior)
				{
				case TimelineEndBehavior.Stop:
					TimelinePause();
					time = durationSeconds;
					break;
				case TimelineEndBehavior.Loop:
					TimelinePlayFromBeginning();
					break;
				case TimelineEndBehavior.PingPong:
					IsBackward = true;
					time = durationSeconds;
					break;
				}
			}
			continuousProperties.cachedRigIsLocal = myRig != null && myRig.isLocal;
			continuousProperties.ApplyAll(1f);
			events.InvokeAll(TimelineEvent.OnReachedEnd, myRig != null && myRig.isLocal);
		}

		private void OnReachedBeginning()
		{
			if (IsBackward)
			{
				switch (endBehavior)
				{
				case TimelineEndBehavior.Stop:
					TimelinePause();
					time = 0f;
					break;
				case TimelineEndBehavior.Loop:
					TimelinePlayFromEnd();
					break;
				case TimelineEndBehavior.PingPong:
					IsForward = true;
					time = 0f;
					break;
				}
			}
			continuousProperties.cachedRigIsLocal = myRig != null && myRig.isLocal;
			continuousProperties.ApplyAll(0f);
			events.InvokeAll(TimelineEvent.OnReachedBeginning, myRig != null && myRig.isLocal);
		}

		private void InBetween()
		{
			float f = time * inverseDuration;
			continuousProperties.cachedRigIsLocal = myRig != null && myRig.isLocal;
			continuousProperties.ApplyAll(f);
		}

		public void Tick()
		{
			if (IsForward)
			{
				time += Time.deltaTime;
				if (time >= durationSeconds)
				{
					OnReachedEnd();
				}
				else
				{
					InBetween();
				}
			}
			else
			{
				time -= Time.deltaTime * backwardDeltaMult;
				if (time <= 0f)
				{
					OnReachedBeginning();
				}
				else
				{
					InBetween();
				}
			}
		}

		public void OnSpawn(VRRig rig)
		{
			myRig = rig;
		}

		public void OnDespawn()
		{
		}
	}
	public class ControllerButtonEvent : MonoBehaviour, ISpawnable
	{
		private enum ButtonType
		{
			trigger,
			primary,
			secondary,
			grip
		}

		[SerializeField]
		private float gripValue = 0.75f;

		[SerializeField]
		private float gripReleaseValue = 0.01f;

		[SerializeField]
		private float triggerValue = 0.75f;

		[SerializeField]
		private float triggerReleaseValue = 0.01f;

		[SerializeField]
		private ButtonType buttonType;

		[Tooltip("How many frames should pass to trigger a press stayed button")]
		[SerializeField]
		private int frameInterval = 20;

		public UnityEvent<bool, float> onButtonPressed;

		public UnityEvent<bool, float> onButtonReleased;

		public UnityEvent<bool, float> onButtonPressStayed;

		private float triggerLastValue;

		private float gripLastValue;

		private bool primaryLastValue;

		private bool secondaryLastValue;

		private int frameCounter;

		private bool inLeftHand;

		private VRRig myRig;

		public bool IsSpawned { get; set; }

		public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

		public void OnSpawn(VRRig rig)
		{
			myRig = rig;
		}

		public void OnDespawn()
		{
		}

		private bool IsMyItem()
		{
			if (myRig != null)
			{
				return myRig.isOfflineVRRig;
			}
			return false;
		}

		private void Awake()
		{
			triggerLastValue = 0f;
			gripLastValue = 0f;
			primaryLastValue = false;
			secondaryLastValue = false;
			frameCounter = 0;
		}

		public void LateUpdate()
		{
			if (!IsMyItem())
			{
				return;
			}
			XRNode node = (inLeftHand ? XRNode.LeftHand : XRNode.RightHand);
			switch (buttonType)
			{
			case ButtonType.trigger:
			{
				float num2 = ControllerInputPoller.TriggerFloat(node);
				if (num2 > triggerValue)
				{
					frameCounter++;
				}
				if (num2 > triggerValue && triggerLastValue < triggerValue)
				{
					onButtonPressed?.Invoke(inLeftHand, num2);
				}
				else if (num2 <= triggerReleaseValue && triggerLastValue > triggerReleaseValue)
				{
					onButtonReleased?.Invoke(inLeftHand, num2);
					frameCounter = 0;
				}
				else if (num2 > triggerValue && triggerLastValue >= triggerValue && frameCounter % frameInterval == 0)
				{
					onButtonPressStayed?.Invoke(inLeftHand, num2);
					frameCounter = 0;
				}
				triggerLastValue = num2;
				break;
			}
			case ButtonType.primary:
			{
				bool flag2 = ControllerInputPoller.PrimaryButtonPress(node);
				if (flag2)
				{
					frameCounter++;
				}
				if (flag2 && !primaryLastValue)
				{
					onButtonPressed?.Invoke(inLeftHand, 1f);
				}
				else if (!flag2 && primaryLastValue)
				{
					onButtonReleased?.Invoke(inLeftHand, 0f);
					frameCounter = 0;
				}
				else if (flag2 && primaryLastValue && frameCounter % frameInterval == 0)
				{
					onButtonPressStayed?.Invoke(inLeftHand, 1f);
					frameCounter = 0;
				}
				primaryLastValue = flag2;
				break;
			}
			case ButtonType.secondary:
			{
				bool flag = ControllerInputPoller.SecondaryButtonPress(node);
				if (flag)
				{
					frameCounter++;
				}
				if (flag && !secondaryLastValue)
				{
					onButtonPressed?.Invoke(inLeftHand, 1f);
				}
				else if (!flag && secondaryLastValue)
				{
					onButtonReleased?.Invoke(inLeftHand, 0f);
					frameCounter = 0;
				}
				else if (flag && secondaryLastValue && frameCounter % frameInterval == 0)
				{
					onButtonPressStayed?.Invoke(inLeftHand, 1f);
					frameCounter = 0;
				}
				secondaryLastValue = flag;
				break;
			}
			case ButtonType.grip:
			{
				float num = ControllerInputPoller.GripFloat(node);
				if (num > gripValue)
				{
					frameCounter++;
				}
				if (num > gripValue && gripLastValue < gripValue)
				{
					onButtonPressed?.Invoke(inLeftHand, num);
				}
				else if (num <= gripReleaseValue && gripLastValue > gripReleaseValue)
				{
					onButtonReleased?.Invoke(inLeftHand, num);
					frameCounter = 0;
				}
				else if (num > gripValue && gripLastValue >= gripValue && frameCounter % frameInterval == 0)
				{
					onButtonPressStayed?.Invoke(inLeftHand, num);
					frameCounter = 0;
				}
				gripLastValue = num;
				break;
			}
			}
		}
	}
	public class CosmeticsProximityReactor : MonoBehaviour, ISpawnable
	{
		public enum ItemKind
		{
			Cosmetic,
			GorillaBody
		}

		[Flags]
		public enum GorillaBodyPart
		{
			None = 0,
			HandLeft = 1,
			HandRight = 2,
			Mouth = 4
		}

		public enum InteractionMode
		{
			CosmeticToCosmetic,
			CosmeticToEnvironment,
			GorillaBodyToCosmetic
		}

		public enum TargetType
		{
			Owner,
			Others,
			All
		}

		[Serializable]
		public class InteractionSetting
		{
			[Tooltip("Determines what type of interaction this block handles.\n CosmeticToCosmetic: triggers when two cosmetics with matching keys are nearby.\n CosmeticToEnvironment: broadcasts keys that EnvironmentProximityReactor objects listen for. Use this to mark a cosmetic as a trigger for scene objects.\n GorillaBodyToCosmetic: triggers when a Gorilla body part (hand, head, etc.) is near this cosmetic.")]
			public InteractionMode mode;

			[Tooltip("Keys this block broadcasts. Other cosmetics or environment objects whose Key list or Listener list contain a matching key can react to this block.")]
			public List<string> interactionKeys = new List<string>();

			[Tooltip("If the other side is broadcasting any of these keys, this block will not fire, even if another key matches.")]
			public List<string> ignoreKeys = new List<string>();

			[Tooltip("Keys this block silently listens for. When the other side broadcasts one of these keys, this block fires. Listener keys are never broadcast outward, so two Listener-only objects will never trigger each other.")]
			public List<string> listenerKeys = new List<string>();

			[Tooltip("Specifies which Gorilla body parts (e.g., Hands, Head) can trigger this interaction.\nUse this when the Mode is set to GorillaBodyToCosmetic.")]
			public GorillaBodyPart gorillaBodyMask;

			[Tooltip("The distance threshold (in meters) for triggering the interaction.\nIf another object enters this range, the OnBelow and WhileBelow events are fired.")]
			public float proximityThreshold = 0.15f;

			[Tooltip("Minimum time (in seconds) between consecutive triggers for this interaction block.\nPrevents rapid re-triggering when objects remain within proximity.")]
			[SerializeField]
			private float cooldownTime = 0.5f;

			[Tooltip("Who is allowed to trigger this block (if gorilla body part is selected).\n Owner: only this cosmetic's own rig/body can trigger this.\n Others: only other players' rigs/bodies can trigger this.\n All: anyone can trigger.\n\nNote: everyone will still be able to see the result when it triggers.")]
			public TargetType targetType = TargetType.All;

			public UnityEvent<UnityEngine.Vector3> onBelowLocal;

			public UnityEvent<UnityEngine.Vector3> onBelowShared;

			public UnityEvent<UnityEngine.Vector3> whileBelowLocal;

			public UnityEvent<UnityEngine.Vector3> whileBelowShared;

			public UnityEvent onAboveLocal;

			public UnityEvent onAboveShared;

			[NonSerialized]
			public bool wasBelow;

			[NonSerialized]
			public bool isMatched;

			[NonSerialized]
			public float lastEffectTime = -9999f;

			public bool IsCosmeticToCosmetic()
			{
				return mode == InteractionMode.CosmeticToCosmetic;
			}

			public bool IsCosmeticToEnvironment()
			{
				return mode == InteractionMode.CosmeticToEnvironment;
			}

			public bool IsGorillaBodyToCosmetic()
			{
				return mode == InteractionMode.GorillaBodyToCosmetic;
			}

			public bool AcceptsGorillaBodyPart(GorillaBodyPart kind)
			{
				if (mode != InteractionMode.GorillaBodyToCosmetic)
				{
					return false;
				}
				return (gorillaBodyMask & kind) != 0;
			}

			public bool CanTriggerFrom(InteractionSetting other)
			{
				if (mode != InteractionMode.CosmeticToCosmetic || other == null || other.mode != InteractionMode.CosmeticToCosmetic)
				{
					return false;
				}
				if (other.interactionKeys == null || other.interactionKeys.Count == 0)
				{
					return false;
				}
				if (ignoreKeys != null && ignoreKeys.Count > 0)
				{
					foreach (string interactionKey in other.interactionKeys)
					{
						if (!string.IsNullOrEmpty(interactionKey) && ignoreKeys.Contains(interactionKey))
						{
							return false;
						}
					}
				}
				foreach (string interactionKey2 in other.interactionKeys)
				{
					if (!string.IsNullOrEmpty(interactionKey2))
					{
						if (interactionKeys != null && interactionKeys.Contains(interactionKey2))
						{
							return true;
						}
						if (listenerKeys != null && listenerKeys.Contains(interactionKey2))
						{
							return true;
						}
					}
				}
				return false;
			}

			public bool CanPlay(float now)
			{
				return now - lastEffectTime >= cooldownTime;
			}

			public void FireBelow(VRRig rig, UnityEngine.Vector3 contact, float now)
			{
				if (!wasBelow && CanPlay(now))
				{
					if (rig != null && rig.isLocal)
					{
						onBelowLocal?.Invoke(contact);
					}
					onBelowShared?.Invoke(contact);
					wasBelow = true;
					lastEffectTime = now;
				}
			}

			public void FireWhile(VRRig rig, UnityEngine.Vector3 contact)
			{
				if (rig != null && rig.isLocal)
				{
					whileBelowLocal?.Invoke(contact);
				}
				whileBelowShared?.Invoke(contact);
			}

			public void FireAbove(VRRig rig)
			{
				if (wasBelow)
				{
					if (rig != null && rig.isLocal)
					{
						onAboveLocal?.Invoke();
					}
					onAboveShared?.Invoke();
					wasBelow = false;
					isMatched = false;
				}
			}

			public bool AllowsRig(VRRig myRig, VRRig otherRig)
			{
				if (myRig == null || otherRig == null)
				{
					return true;
				}
				return targetType switch
				{
					TargetType.Owner => (object)myRig == otherRig, 
					TargetType.Others => (object)myRig != otherRig, 
					_ => true, 
				};
			}
		}

		[Tooltip("Is this object a Cosmetic or a gorilla body part like hand? (gorilla body slot is reserved for Gorilla Player Networked)")]
		public ItemKind itemKind;

		[FormerlySerializedAs("sourceKinds")]
		public GorillaBodyPart gorillaBodyParts;

		public List<InteractionSetting> blocks = new List<InteractionSetting>();

		[Tooltip("If enabled, this cosmetic ignores other instances that share the same PlayFabID.")]
		public bool ignoreSameCosmeticInstances;

		public string PlayFabID = "";

		[Tooltip("If collider is not assigned, we will use the position of this object to find the distance between two cosmetic/body part")]
		public Collider collider;

		private RubberDuckEvents _events;

		public bool IsMatched { get; set; }

		private VRRig MyRig { get; set; }

		public bool IsSpawned { get; set; }

		public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

		public bool IsBelow
		{
			get
			{
				foreach (InteractionSetting block in blocks)
				{
					if (block.wasBelow)
					{
						return true;
					}
				}
				return false;
			}
		}

		public VRRig GetOwnerRig()
		{
			return MyRig;
		}

		public void OnSpawn(VRRig rig)
		{
			if (MyRig == null)
			{
				MyRig = rig;
			}
		}

		public void OnDespawn()
		{
		}

		private void Start()
		{
			IsMatched = false;
			if (CosmeticsProximityReactorManager.Instance != null)
			{
				CosmeticsProximityReactorManager.Instance.Register(this);
			}
		}

		private void OnEnable()
		{
			if (MyRig == null)
			{
				MyRig = GetComponentInParent<VRRig>();
			}
			if (CosmeticsProximityReactorManager.Instance != null)
			{
				CosmeticsProximityReactorManager.Instance.Register(this);
			}
		}

		private void OnDisable()
		{
			if ((bool)CosmeticsProximityReactorManager.Instance)
			{
				CosmeticsProximityReactorManager.Instance.Unregister(this);
			}
		}

		public IReadOnlyList<string> GetTypes()
		{
			List<string> sharedKeysCache = CosmeticsProximityReactorManager.SharedKeysCache;
			sharedKeysCache.Clear();
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode != InteractionMode.CosmeticToCosmetic)
				{
					continue;
				}
				if (block.interactionKeys != null)
				{
					foreach (string interactionKey in block.interactionKeys)
					{
						if (!string.IsNullOrEmpty(interactionKey) && !sharedKeysCache.Contains(interactionKey))
						{
							sharedKeysCache.Add(interactionKey);
						}
					}
				}
				if (block.listenerKeys == null)
				{
					continue;
				}
				foreach (string listenerKey in block.listenerKeys)
				{
					if (!string.IsNullOrEmpty(listenerKey) && !sharedKeysCache.Contains(listenerKey))
					{
						sharedKeysCache.Add(listenerKey);
					}
				}
			}
			return sharedKeysCache;
		}

		public bool IsGorillaBody()
		{
			return itemKind == ItemKind.GorillaBody;
		}

		public bool IsCosmeticItem()
		{
			return itemKind == ItemKind.Cosmetic;
		}

		public bool AcceptsAnySource()
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.gorillaBodyMask != GorillaBodyPart.None)
				{
					return true;
				}
			}
			return false;
		}

		public bool AcceptsThisSource(GorillaBodyPart kind)
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.AcceptsGorillaBodyPart(kind))
				{
					return true;
				}
			}
			return false;
		}

		public float GetCosmeticPairThresholdWith(CosmeticsProximityReactor other, out bool any)
		{
			any = false;
			float num = float.MaxValue;
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode != InteractionMode.CosmeticToCosmetic || !block.AllowsRig(MyRig, other.MyRig))
				{
					continue;
				}
				foreach (InteractionSetting block2 in other.blocks)
				{
					if (block2.mode == InteractionMode.CosmeticToCosmetic && block2.AllowsRig(other.MyRig, MyRig) && block.CanTriggerFrom(block2))
					{
						any = true;
						if (block.proximityThreshold < num)
						{
							num = block.proximityThreshold;
						}
					}
				}
			}
			return num;
		}

		public float GetSourceThresholdFor(CosmeticsProximityReactor gorillaBody, out bool any)
		{
			any = false;
			float num = float.MaxValue;
			GorillaBodyPart kind = gorillaBody.gorillaBodyParts;
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.AcceptsGorillaBodyPart(kind) && block.AllowsRig(MyRig, gorillaBody.MyRig))
				{
					any = true;
					if (block.proximityThreshold < num)
					{
						num = block.proximityThreshold;
					}
				}
			}
			return num;
		}

		public void OnCosmeticBelowWith(CosmeticsProximityReactor other, UnityEngine.Vector3 contact)
		{
			float time = Time.time;
			bool flag = false;
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode != InteractionMode.CosmeticToCosmetic || !block.AllowsRig(MyRig, other.MyRig))
				{
					continue;
				}
				bool flag2 = false;
				foreach (InteractionSetting block2 in other.blocks)
				{
					if (block2.mode == InteractionMode.CosmeticToCosmetic && block2.AllowsRig(other.MyRig, MyRig) && block.CanTriggerFrom(block2))
					{
						flag2 = true;
						break;
					}
				}
				if (flag2)
				{
					block.FireBelow(MyRig, contact, time);
					if (block.wasBelow)
					{
						block.isMatched = true;
						flag = true;
					}
				}
			}
			if (flag)
			{
				IsMatched = true;
			}
		}

		public void WhileCosmeticBelowWith(CosmeticsProximityReactor other, UnityEngine.Vector3 contact)
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode != InteractionMode.CosmeticToCosmetic || !block.isMatched || !block.AllowsRig(MyRig, other.MyRig))
				{
					continue;
				}
				bool flag = false;
				foreach (InteractionSetting block2 in other.blocks)
				{
					if (block2.mode == InteractionMode.CosmeticToCosmetic && block2.AllowsRig(other.MyRig, MyRig) && block.CanTriggerFrom(block2))
					{
						flag = true;
						break;
					}
				}
				if (flag)
				{
					block.FireWhile(MyRig, contact);
				}
			}
		}

		public void OnCosmeticAboveAll()
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.CosmeticToCosmetic && block.isMatched)
				{
					block.FireAbove(MyRig);
				}
			}
			RefreshAggregateMatched();
		}

		public void OnSourceBelow(UnityEngine.Vector3 contact, GorillaBodyPart kind, VRRig sourceRig)
		{
			float time = Time.time;
			bool flag = false;
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.AcceptsGorillaBodyPart(kind) && block.AllowsRig(MyRig, sourceRig))
				{
					block.FireBelow(MyRig, contact, time);
					if (block.wasBelow)
					{
						block.isMatched = true;
						flag = true;
					}
				}
			}
			if (flag)
			{
				RefreshAggregateMatched();
			}
		}

		public void WhileSourceBelow(UnityEngine.Vector3 contact, GorillaBodyPart kind, VRRig sourceRig)
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.AcceptsGorillaBodyPart(kind) && block.isMatched && block.AllowsRig(MyRig, sourceRig))
				{
					block.FireWhile(MyRig, contact);
				}
			}
		}

		public void OnSourceAboveAll()
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.isMatched)
				{
					block.FireAbove(MyRig);
				}
			}
			RefreshAggregateMatched();
		}

		public bool HasAnyCosmeticMatch()
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.CosmeticToCosmetic && block.isMatched)
				{
					return true;
				}
			}
			return false;
		}

		private bool HasAnyGorillaBodyPartMatch()
		{
			foreach (InteractionSetting block in blocks)
			{
				if (block.mode == InteractionMode.GorillaBodyToCosmetic && block.isMatched)
				{
					return true;
				}
			}
			return false;
		}

		public void RefreshAggregateMatched()
		{
			IsMatched = HasAnyCosmeticMatch() || HasAnyGorillaBodyPartMatch();
		}
	}
	public class CosmeticsProximityReactorManager : MonoBehaviour, IGorillaSliceableSimple
	{
		private static CosmeticsProximityReactorManager _instance;

		private readonly List<CosmeticsProximityReactor> cosmetics = new List<CosmeticsProximityReactor>();

		private readonly List<CosmeticsProximityReactor> gorillaBodyPart = new List<CosmeticsProximityReactor>();

		private readonly Dictionary<string, List<CosmeticsProximityReactor>> byType = new Dictionary<string, List<CosmeticsProximityReactor>>(StringComparer.Ordinal);

		private readonly Dictionary<CosmeticsProximityReactor, int> matchedFrame = new Dictionary<CosmeticsProximityReactor, int>();

		private readonly List<string> typeKeysCache = new List<string>();

		private bool typeKeysDirty;

		private int groupCursor;

		internal static readonly List<string> SharedKeysCache = new List<string>();

		public static CosmeticsProximityReactorManager Instance => _instance;

		public IReadOnlyList<CosmeticsProximityReactor> Cosmetics => cosmetics;

		public static event Action<CosmeticsProximityReactor> OnCosmeticRegistered;

		private void Awake()
		{
			if (_instance != null && _instance != this)
			{
				UnityEngine.Object.Destroy(base.gameObject);
			}
			else
			{
				_instance = this;
			}
		}

		public void OnEnable()
		{
			GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
		}

		public void OnDisable()
		{
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
			if (_instance == this)
			{
				_instance = null;
			}
		}

		public void Register(CosmeticsProximityReactor cosmetic)
		{
			if (cosmetic == null)
			{
				return;
			}
			if (cosmetic.IsGorillaBody())
			{
				if (!gorillaBodyPart.Contains(cosmetic))
				{
					gorillaBodyPart.Add(cosmetic);
				}
				return;
			}
			if (!cosmetics.Contains(cosmetic))
			{
				cosmetics.Add(cosmetic);
				CosmeticsProximityReactorManager.OnCosmeticRegistered?.Invoke(cosmetic);
			}
			IReadOnlyList<string> types = cosmetic.GetTypes();
			for (int i = 0; i < types.Count; i++)
			{
				string text = types[i];
				if (!string.IsNullOrEmpty(text))
				{
					if (!byType.TryGetValue(text, out var value))
					{
						value = new List<CosmeticsProximityReactor>();
						byType[text] = value;
					}
					if (!value.Contains(cosmetic))
					{
						value.Add(cosmetic);
						typeKeysDirty = true;
					}
				}
			}
		}

		public void Unregister(CosmeticsProximityReactor cosmetic)
		{
			if (cosmetic == null)
			{
				return;
			}
			cosmetics.Remove(cosmetic);
			gorillaBodyPart.Remove(cosmetic);
			matchedFrame.Remove(cosmetic);
			foreach (KeyValuePair<string, List<CosmeticsProximityReactor>> item in byType)
			{
				if (item.Value.Remove(cosmetic))
				{
					typeKeysDirty = true;
				}
			}
		}

		public void SliceUpdate()
		{
			if (cosmetics.Count == 0)
			{
				return;
			}
			if (AnyGroupHasTwo())
			{
				if (typeKeysDirty)
				{
					RebuildTypeKeysCache();
				}
				if (typeKeysCache.Count > 0)
				{
					for (int i = 0; i < typeKeysCache.Count; i++)
					{
						string key = typeKeysCache[i];
						if (byType.TryGetValue(key, out var value) && value != null && value.Count > 0)
						{
							ProcessOneGroup(value);
						}
					}
				}
			}
			if (gorillaBodyPart.Count > 0)
			{
				for (int j = 0; j < cosmetics.Count; j++)
				{
					CosmeticsProximityReactor cosmeticsProximityReactor = cosmetics[j];
					if (cosmeticsProximityReactor == null)
					{
						continue;
					}
					if (!cosmeticsProximityReactor.AcceptsAnySource())
					{
						cosmeticsProximityReactor.OnSourceAboveAll();
						continue;
					}
					bool flag = false;
					UnityEngine.Vector3 contact = default(UnityEngine.Vector3);
					for (int k = 0; k < gorillaBodyPart.Count; k++)
					{
						CosmeticsProximityReactor cosmeticsProximityReactor2 = gorillaBodyPart[k];
						if (!(cosmeticsProximityReactor2 == null) && cosmeticsProximityReactor.AcceptsThisSource(cosmeticsProximityReactor2.gorillaBodyParts))
						{
							bool any;
							float sourceThresholdFor = cosmeticsProximityReactor.GetSourceThresholdFor(cosmeticsProximityReactor2, out any);
							if (any && AreCollidersWithinThreshold(cosmeticsProximityReactor2, cosmeticsProximityReactor, sourceThresholdFor, out var contactPoint))
							{
								cosmeticsProximityReactor.OnSourceBelow(contactPoint, cosmeticsProximityReactor2.gorillaBodyParts, cosmeticsProximityReactor2.GetComponentInParent<VRRig>());
								contact = contactPoint;
								flag = true;
							}
						}
					}
					if (flag)
					{
						cosmeticsProximityReactor.WhileSourceBelow(contact, CosmeticsProximityReactor.GorillaBodyPart.HandLeft | CosmeticsProximityReactor.GorillaBodyPart.HandRight | CosmeticsProximityReactor.GorillaBodyPart.Mouth, (gorillaBodyPart[0] != null) ? gorillaBodyPart[0].GetComponentInParent<VRRig>() : null);
					}
					else
					{
						cosmeticsProximityReactor.OnSourceAboveAll();
					}
				}
			}
			if (typeKeysDirty)
			{
				RebuildTypeKeysCache();
			}
			for (int l = 0; l < typeKeysCache.Count; l++)
			{
				string key2 = typeKeysCache[l];
				if (byType.TryGetValue(key2, out var value2) && value2 != null && value2.Count > 0)
				{
					BreakTheBoundForGroup(value2);
				}
			}
		}

		private void ProcessOneGroup(List<CosmeticsProximityReactor> group)
		{
			if (!CheckProximity(group))
			{
				BreakTheBoundForGroup(group);
			}
		}

		private bool CheckProximity(List<CosmeticsProximityReactor> group)
		{
			bool result = false;
			for (int i = 0; i < group.Count; i++)
			{
				CosmeticsProximityReactor cosmeticsProximityReactor = group[i];
				if (cosmeticsProximityReactor == null)
				{
					continue;
				}
				for (int j = i + 1; j < group.Count; j++)
				{
					CosmeticsProximityReactor cosmeticsProximityReactor2 = group[j];
					if (cosmeticsProximityReactor2 == null || ShouldSkipSameIdPair(cosmeticsProximityReactor, cosmeticsProximityReactor2))
					{
						continue;
					}
					bool any;
					float cosmeticPairThresholdWith = cosmeticsProximityReactor.GetCosmeticPairThresholdWith(cosmeticsProximityReactor2, out any);
					bool any2;
					float cosmeticPairThresholdWith2 = cosmeticsProximityReactor2.GetCosmeticPairThresholdWith(cosmeticsProximityReactor, out any2);
					if (!(any || any2))
					{
						continue;
					}
					float num = float.MaxValue;
					if (any && cosmeticPairThresholdWith < num)
					{
						num = cosmeticPairThresholdWith;
					}
					if (any2 && cosmeticPairThresholdWith2 < num)
					{
						num = cosmeticPairThresholdWith2;
					}
					if (AreCollidersWithinThreshold(cosmeticsProximityReactor, cosmeticsProximityReactor2, num, out var contactPoint))
					{
						cosmeticsProximityReactor.OnCosmeticBelowWith(cosmeticsProximityReactor2, contactPoint);
						cosmeticsProximityReactor2.OnCosmeticBelowWith(cosmeticsProximityReactor, contactPoint);
						if (cosmeticsProximityReactor.IsBelow)
						{
							cosmeticsProximityReactor.RefreshAggregateMatched();
							matchedFrame[cosmeticsProximityReactor] = Time.frameCount;
							result = true;
						}
						if (cosmeticsProximityReactor2.IsBelow)
						{
							cosmeticsProximityReactor2.RefreshAggregateMatched();
							matchedFrame[cosmeticsProximityReactor2] = Time.frameCount;
							result = true;
						}
					}
				}
			}
			return result;
		}

		private void BreakTheBoundForGroup(List<CosmeticsProximityReactor> group)
		{
			for (int i = 0; i < group.Count; i++)
			{
				CosmeticsProximityReactor cosmeticsProximityReactor = group[i];
				if (!(cosmeticsProximityReactor == null) && cosmeticsProximityReactor.HasAnyCosmeticMatch() && (!matchedFrame.TryGetValue(cosmeticsProximityReactor, out var value) || value != Time.frameCount))
				{
					if (TryFindAnyCosmeticPartner(cosmeticsProximityReactor, out var partner, out var contact))
					{
						cosmeticsProximityReactor.WhileCosmeticBelowWith(partner, contact);
						partner.WhileCosmeticBelowWith(cosmeticsProximityReactor, contact);
					}
					else
					{
						cosmeticsProximityReactor.OnCosmeticAboveAll();
					}
				}
			}
		}

		private bool TryFindAnyCosmeticPartner(CosmeticsProximityReactor a, out CosmeticsProximityReactor partner, out UnityEngine.Vector3 contact)
		{
			partner = null;
			contact = default(UnityEngine.Vector3);
			IReadOnlyList<string> types = a.GetTypes();
			for (int i = 0; i < types.Count; i++)
			{
				string text = types[i];
				if (string.IsNullOrEmpty(text) || !byType.TryGetValue(text, out var value) || value == null)
				{
					continue;
				}
				for (int j = 0; j < value.Count; j++)
				{
					CosmeticsProximityReactor cosmeticsProximityReactor = value[j];
					if (cosmeticsProximityReactor == null || cosmeticsProximityReactor == a || ShouldSkipSameIdPair(a, cosmeticsProximityReactor))
					{
						continue;
					}
					bool any;
					float cosmeticPairThresholdWith = a.GetCosmeticPairThresholdWith(cosmeticsProximityReactor, out any);
					if (any)
					{
						float threshold = cosmeticPairThresholdWith;
						if (AreCollidersWithinThreshold(a, cosmeticsProximityReactor, threshold, out var contactPoint))
						{
							partner = cosmeticsProximityReactor;
							contact = contactPoint;
							return true;
						}
					}
				}
			}
			return false;
		}

		private static bool ShouldSkipSameIdPair(CosmeticsProximityReactor a, CosmeticsProximityReactor b)
		{
			if (!a.ignoreSameCosmeticInstances && !b.ignoreSameCosmeticInstances)
			{
				return false;
			}
			if (string.IsNullOrEmpty(a.PlayFabID) || string.IsNullOrEmpty(b.PlayFabID))
			{
				return false;
			}
			return string.Equals(a.PlayFabID, b.PlayFabID, StringComparison.Ordinal);
		}

		private static bool AreCollidersWithinThreshold(CosmeticsProximityReactor a, CosmeticsProximityReactor b, float threshold, out UnityEngine.Vector3 contactPoint)
		{
			UnityEngine.Vector3 vector = ((b.collider == null) ? b.transform.position : b.collider.ClosestPoint(a.transform.position));
			UnityEngine.Vector3 vector2 = ((a.collider == null) ? a.transform.position : a.collider.ClosestPoint(vector));
			contactPoint = (vector2 + vector) * 0.5f;
			return UnityEngine.Vector3.Distance(vector2, vector) <= threshold;
		}

		private bool AnyGroupHasTwo()
		{
			foreach (KeyValuePair<string, List<CosmeticsProximityReactor>> item in byType)
			{
				List<CosmeticsProximityReactor> value = item.Value;
				if (value != null && value.Count >= 2)
				{
					return true;
				}
			}
			return false;
		}

		private void RebuildTypeKeysCache()
		{
			typeKeysCache.Clear();
			foreach (KeyValuePair<string, List<CosmeticsProximityReactor>> item in byType)
			{
				List<CosmeticsProximityReactor> value = item.Value;
				if (value != null && value.Count > 0)
				{
					typeKeysCache.Add(item.Key);
				}
			}
			typeKeysDirty = false;
			if (groupCursor >= typeKeysCache.Count)
			{
				groupCursor = 0;
			}
		}
	}
	public class CosmeticSwapper : MonoBehaviour, ITickSystemTick
	{
		private enum SwapMode
		{
			AllAtOnce,
			StepByStep,
			Random
		}

		private struct CosmeticState
		{
			public string cosmeticId;

			public CosmeticsController.CosmeticItem replacedItem;

			public CosmeticsController.CosmeticSlots slot;

			public bool isLeftHand;
		}

		[SerializeField]
		private List<string> cosmeticIDs = new List<string>();

		[SerializeField]
		private SwapMode swapMode = SwapMode.StepByStep;

		[Tooltip("Optional. When assigned, TriggerSwap sources the cosmetic ID from the cycle controller's active sub-item instead of the cosmeticIDs list. Use SwapMode.Random to call CycleRandom() automatically on each hit before reading the active sub-item.")]
		[SerializeField]
		private SubCosmeticCycleController cycleController;

		[SerializeField]
		private float stepTimeout = 10f;

		[Tooltip("Hold final step as long as the swapper is being called within the timeframe")]
		[SerializeField]
		private bool holdFinalStep = true;

		[SerializeField]
		private UnityEvent<VRRig> OnSwappingSequenceCompleted;

		[SerializeField]
		private List<GameModeType> gameModeExclusion = new List<GameModeType>();

		private CosmeticsController controller;

		private Stack<CosmeticState> newSwappedCosmetics = new Stack<CosmeticState>();

		private float lastCosmeticSwapTime = float.PositiveInfinity;

		private bool isAtFinalCosmeticStep;

		private int CosmeticStepIndex => newSwappedCosmetics.Count;

		public bool TickRunning { get; set; }

		private void Awake()
		{
			controller = CosmeticsController.instance;
		}

		private void OnEnable()
		{
			TickSystem<object>.AddTickCallback(this);
			PlayerCosmeticsSystem.UnlockTemporaryCosmeticsGlobal(cosmeticIDs);
		}

		private void OnDisable()
		{
			PlayerCosmeticsSystem.LockTemporaryCosmeticsGlobal(cosmeticIDs);
			TickSystem<object>.RemoveTickCallback(this);
		}

		public void SwapInCosmetic(VRRig vrRig)
		{
			TriggerSwap(vrRig);
		}

		private SwapMode GetCurrentMode()
		{
			return swapMode;
		}

		private bool ShouldHoldFinalStep()
		{
			return holdFinalStep;
		}

		public int GetCurrentStepIndex(VRRig rig)
		{
			if (rig == null)
			{
				return 0;
			}
			return CosmeticStepIndex;
		}

		public int GetNumberOfSteps()
		{
			if (cycleController != null)
			{
				return cycleController.Count;
			}
			return cosmeticIDs.Count;
		}

		private void TriggerSwap(VRRig rig)
		{
			if ((GorillaGameManager.instance != null && gameModeExclusion.Contains(GorillaGameManager.instance.GameType())) || rig == null || controller == null || rig != GorillaTagger.Instance.offlineVRRig)
			{
				return;
			}
			if (cycleController != null)
			{
				if (swapMode == SwapMode.Random)
				{
					cycleController.CycleRandom();
				}
				string appliedCosmeticID = cycleController.GetAppliedCosmeticID();
				if (!string.IsNullOrEmpty(appliedCosmeticID))
				{
					CosmeticState? cosmeticState = SwapInCosmeticWithReturn(appliedCosmeticID, rig);
					if (cosmeticState.HasValue)
					{
						AddNewSwappedCosmetic(cosmeticState.Value);
					}
				}
			}
			else
			{
				if (cosmeticIDs.Count == 0)
				{
					return;
				}
				if (swapMode == SwapMode.Random)
				{
					string nameOrId = cosmeticIDs[UnityEngine.Random.Range(0, cosmeticIDs.Count)];
					CosmeticState? cosmeticState2 = SwapInCosmeticWithReturn(nameOrId, rig);
					if (cosmeticState2.HasValue)
					{
						AddNewSwappedCosmetic(cosmeticState2.Value);
					}
					return;
				}
				if (swapMode == SwapMode.AllAtOnce)
				{
					foreach (string cosmeticID in cosmeticIDs)
					{
						CosmeticState? cosmeticState3 = SwapInCosmeticWithReturn(cosmeticID, rig);
						if (cosmeticState3.HasValue)
						{
							AddNewSwappedCosmetic(cosmeticState3.Value);
						}
					}
					return;
				}
				int cosmeticStepIndex = CosmeticStepIndex;
				if (cosmeticStepIndex < 0 || cosmeticStepIndex >= cosmeticIDs.Count)
				{
					return;
				}
				string nameOrId2 = cosmeticIDs[cosmeticStepIndex];
				CosmeticState? cosmeticState4 = SwapInCosmeticWithReturn(nameOrId2, rig);
				if (!cosmeticState4.HasValue)
				{
					return;
				}
				AddNewSwappedCosmetic(cosmeticState4.Value);
				if (cosmeticStepIndex == cosmeticIDs.Count - 1)
				{
					if (holdFinalStep)
					{
						MarkFinalCosmeticStep();
					}
					if (OnSwappingSequenceCompleted != null)
					{
						OnSwappingSequenceCompleted.Invoke(rig);
					}
				}
				else
				{
					UnmarkFinalCosmeticStep();
				}
			}
		}

		private CosmeticState? SwapInCosmeticWithReturn(string nameOrId, VRRig rig)
		{
			if (controller == null)
			{
				return null;
			}
			CosmeticsController.CosmeticItem cosmeticItem = FindItem(nameOrId);
			if (cosmeticItem.isNullItem)
			{
				UnityEngine.Debug.LogWarning("Cosmetic not found: " + nameOrId);
				return null;
			}
			bool isLeftHand;
			CosmeticsController.CosmeticSlots cosmeticSlot = GetCosmeticSlot(cosmeticItem, out isLeftHand);
			if (cosmeticSlot == CosmeticsController.CosmeticSlots.Count)
			{
				UnityEngine.Debug.LogWarning("Could not determine slot for: " + cosmeticItem.displayName);
				return null;
			}
			CosmeticsController.CosmeticItem replacedItem = controller.currentWornSet.items[(int)cosmeticSlot];
			if (!replacedItem.isNullItem && replacedItem.itemName == cosmeticItem.itemName)
			{
				return null;
			}
			controller.ApplyCosmeticItemToSet(controller.tempUnlockedSet, cosmeticItem, isLeftHand, applyToPlayerPrefs: false);
			controller.UpdateWornCosmetics(sync: true);
			return new CosmeticState
			{
				cosmeticId = nameOrId,
				replacedItem = replacedItem,
				slot = cosmeticSlot,
				isLeftHand = isLeftHand
			};
		}

		private void RestorePreviousCosmetic(CosmeticState state)
		{
			if (controller == null)
			{
				return;
			}
			CosmeticsController.CosmeticItem cosmeticItem = FindItem(state.cosmeticId);
			if (!cosmeticItem.isNullItem)
			{
				controller.RemoveCosmeticItemFromSet(controller.tempUnlockedSet, cosmeticItem.displayName, applyToPlayerPrefs: false);
				if (!state.replacedItem.isNullItem)
				{
					controller.ApplyCosmeticItemToSet(controller.tempUnlockedSet, state.replacedItem, state.isLeftHand, applyToPlayerPrefs: false);
				}
				controller.UpdateWornCosmetics(sync: true);
			}
		}

		private CosmeticsController.CosmeticItem FindItem(string nameOrId)
		{
			if (controller.allCosmeticsDict.TryGetValue(nameOrId, out var value))
			{
				return value;
			}
			if (controller.allCosmeticsItemIDsfromDisplayNamesDict.TryGetValue(nameOrId, out var value2))
			{
				return controller.GetItemFromDict(value2);
			}
			return controller.nullItem;
		}

		private CosmeticsController.CosmeticSlots GetCosmeticSlot(CosmeticsController.CosmeticItem item, out bool isLeftHand)
		{
			isLeftHand = false;
			if (item.isHoldable)
			{
				CosmeticsController.CosmeticSet currentWornSet = controller.currentWornSet;
				CosmeticsController.CosmeticItem cosmeticItem = currentWornSet.items[7];
				CosmeticsController.CosmeticItem cosmeticItem2 = currentWornSet.items[8];
				if (cosmeticItem.isNullItem || (!cosmeticItem2.isNullItem && item.itemName == cosmeticItem.itemName))
				{
					isLeftHand = true;
				}
				if (!isLeftHand)
				{
					return CosmeticsController.CosmeticSlots.HandRight;
				}
				return CosmeticsController.CosmeticSlots.HandLeft;
			}
			return CosmeticsController.CategoryToNonTransferrableSlot(item.itemCategory);
		}

		public void Tick()
		{
			if (newSwappedCosmetics.Count <= 0)
			{
				return;
			}
			if (GetCurrentMode() == SwapMode.StepByStep)
			{
				if (isAtFinalCosmeticStep && ShouldHoldFinalStep())
				{
					if (Time.time - lastCosmeticSwapTime <= stepTimeout)
					{
						return;
					}
					isAtFinalCosmeticStep = false;
				}
				if (Time.time - lastCosmeticSwapTime > stepTimeout)
				{
					while (newSwappedCosmetics.Count > 0)
					{
						CosmeticState state = newSwappedCosmetics.Pop();
						RestorePreviousCosmetic(state);
					}
					isAtFinalCosmeticStep = false;
					lastCosmeticSwapTime = float.PositiveInfinity;
				}
			}
			else if (GetCurrentMode() == SwapMode.AllAtOnce && Time.time - lastCosmeticSwapTime > stepTimeout)
			{
				while (newSwappedCosmetics.Count > 0)
				{
					CosmeticState state2 = newSwappedCosmetics.Pop();
					RestorePreviousCosmetic(state2);
				}
				lastCosmeticSwapTime = float.PositiveInfinity;
				isAtFinalCosmeticStep = false;
			}
		}

		private void AddNewSwappedCosmetic(CosmeticState state)
		{
			newSwappedCosmetics.Push(state);
			lastCosmeticSwapTime = Time.time;
		}

		private void MarkFinalCosmeticStep()
		{
			isAtFinalCosmeticStep = true;
			lastCosmeticSwapTime = Time.time;
		}

		private void UnmarkFinalCosmeticStep()
		{
			isAtFinalCosmeticStep = false;
		}
	}
	public class DistanceCheckerCosmetic : MonoBehaviour, ISpawnable, IGorillaSliceableSimple
	{
		private enum State
		{
			AboveThreshold,
			BelowThreshold,
			None
		}

		private enum DistanceCondition
		{
			None,
			Owner,
			Others,
			Everyone
		}

		[SerializeField]
		private Transform distanceFrom;

		[SerializeField]
		private DistanceCondition distanceTo;

		[Tooltip("Receive events when above or below this distance")]
		public float distanceThreshold;

		public UnityEvent onOneIsBelowThreshold;

		public UnityEvent onAllAreAboveThreshold;

		public UnityEvent<VRRig, float> onClosestPlayerBelowThresholdChanged;

		private VRRig myRig;

		private State currentState;

		private UnityEngine.Vector3 closestDistance;

		private VRRig currentClosestPlayer;

		private VRRig ownerRig;

		private TransferrableObject transferableObject;

		public bool IsSpawned { get; set; }

		public ECosmeticSelectSide CosmeticSelectedSide { get; set; }

		public void OnSpawn(VRRig rig)
		{
			myRig = rig;
		}

		public void OnDespawn()
		{
		}

		private void OnEnable()
		{
			currentState = State.None;
			transferableObject = GetComponentInParent<TransferrableObject>();
			if (transferableObject != null)
			{
				ownerRig = transferableObject.ownerRig;
			}
			else
			{
				ownerRig = GetComponentInParent<VRRig>();
			}
			if (ownerRig == null)
			{
				ownerRig = GorillaTagger.Instance.offlineVRRig;
			}
			ResetClosestPlayer();
			GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
		}

		private void OnDisable()
		{
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.Update);
		}

		public void SliceUpdate()
		{
			UpdateDistance();
		}

		private bool IsBelowThreshold(UnityEngine.Vector3 distance)
		{
			if (distance.IsShorterThan(distanceThreshold))
			{
				return true;
			}
			return false;
		}

		private bool IsAboveThreshold(UnityEngine.Vector3 distance)
		{
			if (distance.IsLongerThan(distanceThreshold))
			{
				return true;
			}
			return false;
		}

		private void UpdateClosestPlayer(bool others = false)
		{
			if (!PhotonNetwork.InRoom)
			{
				ResetClosestPlayer();
				return;
			}
			VRRig vRRig = currentClosestPlayer;
			closestDistance = UnityEngine.Vector3.positiveInfinity;
			currentClosestPlayer = null;
			foreach (VRRig activeRig in VRRigCache.ActiveRigs)
			{
				if (!others || !(ownerRig != null) || !(activeRig == ownerRig))
				{
					UnityEngine.Vector3 distance = activeRig.transform.position - distanceFrom.position;
					if (IsBelowThreshold(distance) && distance.sqrMagnitude < closestDistance.sqrMagnitude)
					{
						closestDistance = distance;
						currentClosestPlayer = activeRig;
					}
				}
			}
			if (currentClosestPlayer != null && currentClosestPlayer != vRRig)
			{
				onClosestPlayerBelowThresholdChanged?.Invoke(currentClosestPlayer, closestDistance.magnitude);
			}
		}

		private void ResetClosestPlayer()
		{
			closestDistance = UnityEngine.Vector3.positiveInfinity;
			currentClosestPlayer = null;
		}

		private void UpdateDistance()
		{
			bool flag = true;
			switch (distanceTo)
			{
			case DistanceCondition.Everyone:
				UpdateClosestPlayer();
				if (!PhotonNetwork.InRoom)
				{
					break;
				}
				foreach (VRRig activeRig in VRRigCache.ActiveRigs)
				{
					UnityEngine.Vector3 distance2 = activeRig.transform.position - distanceFrom.position;
					if (IsBelowThreshold(distance2))
					{
						UpdateState(State.BelowThreshold);
						flag = false;
					}
				}
				if (flag)
				{
					UpdateState(State.AboveThreshold);
				}
				break;
			case DistanceCondition.Others:
				UpdateClosestPlayer(others: true);
				if (!PhotonNetwork.InRoom)
				{
					break;
				}
				foreach (VRRig activeRig2 in VRRigCache.ActiveRigs)
				{
					if (!(ownerRig != null) || !(activeRig2 == ownerRig))
					{
						UnityEngine.Vector3 distance3 = activeRig2.transform.position - distanceFrom.position;
						if (IsBelowThreshold(distance3))
						{
							UpdateState(State.BelowThreshold);
							flag = false;
						}
					}
				}
				if (flag)
				{
					UpdateState(State.AboveThreshold);
				}
				break;
			case DistanceCondition.Owner:
			{
				UnityEngine.Vector3 distance = myRig.transform.position - distanceFrom.position;
				if (IsBelowThreshold(distance))
				{
					UpdateState(State.BelowThreshold);
				}
				else if (IsAboveThreshold(distance))
				{
					UpdateState(State.AboveThreshold);
				}
				break;
			}
			}
		}

		private void UpdateState(State newState)
		{
			if (currentState != newState)
			{
				currentState = newState;
				if (currentState == State.AboveThreshold)
				{
					onAllAreAboveThreshold?.Invoke();
				}
				else if (currentState == State.BelowThreshold)
				{
					onOneIsBelowThreshold?.Invoke();
				}
			}
		}
	}
