		private UnityEngine.Vector3 surfacePlaneNormal;

		private CjLib.FloatSpring tiltFrontBackSpring;

		private CjLib.FloatSpring tiltLeftRightSpring;

		private CjLib.FloatSpring spinSpeedSpring;

		private CjLib.Vector3Spring groundPointSpring;

		private UnityEngine.Vector2[] landingTiltValues = new UnityEngine.Vector2[4]
		{
			new UnityEngine.Vector2(1f, -1f),
			new UnityEngine.Vector2(1f, 0f),
			new UnityEngine.Vector2(-1f, 1f),
			new UnityEngine.Vector2(-1f, 0f)
		};

		private UnityEngine.Vector2 landingTiltLeadingTarget = UnityEngine.Vector2.zero;

		private UnityEngine.Vector2 landingTiltTarget = UnityEngine.Vector2.zero;

		[Header("Debug Params")]
		[SerializeField]
