		public bool TrySetIdle()
		{
			if (state == State.Idle || state == State.FindingSurface || state == State.Fallen)
			{
				StartIdle();
				return true;
			}
			return false;
		}

		public bool TryCheckForSurfaces()
		{
			if (state == State.Idle || state == State.FindingSurface)
			{
				StartFindingSurfaces();
				return true;
			}
			return false;
		}

		public void Spin()
		{
			StartSpin();
		}

		public bool TryGetSpinStartData(out UnityEngine.Vector3 surfacePoint, out UnityEngine.Vector3 surfaceNormal, out float randomDuration, out Side randomSide, out Variation randomVariation, out double startTime)
		{
			if (canStartSpin)
			{
				surfacePoint = surfacePlanePoint;
				surfaceNormal = surfacePlaneNormal;
				randomDuration = UnityEngine.Random.Range(spinTimeRange.x, spinTimeRange.y);
				randomSide = (Side)UnityEngine.Random.Range(0, 4);
				randomVariation = (Variation)UnityEngine.Random.Range(0, 5);
				startTime = (PhotonNetwork.InRoom ? PhotonNetwork.Time : (-1.0));
				return true;
			}
			surfacePoint = UnityEngine.Vector3.zero;
			surfaceNormal = UnityEngine.Vector3.zero;
			randomDuration = 0f;
			randomSide = Side.Shin;
			randomVariation = Variation.Tumble;
			startTime = -1.0;
			return false;
		}

		public void SetSpinStartData(UnityEngine.Vector3 surfacePoint, UnityEngine.Vector3 surfaceNormal, float duration, bool counterClockwise, Side side, Variation variation, double startTime)
		{
			surfacePlanePoint = surfacePoint;
			surfacePlaneNormal = surfaceNormal;
			spinTime = duration;
			spinStartTime = startTime;
			spinCounterClockwise = counterClockwise;
			landingSide = side;
			landingVariation = variation;
		}

		private void LateUpdate()
		{
			float deltaTime = Time.deltaTime;
			double num = (PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time));
			canStartSpin = false;
			switch (state)
			{
			default:
				base.transform.localPosition = UnityEngine.Vector3.zero;
				base.transform.localRotation = UnityEngine.Quaternion.identity;
				spinTransform.localRotation = UnityEngine.Quaternion.identity;
				spinTransform.localPosition = UnityEngine.Vector3.zero;
				break;
			case State.FindingSurface:
			{
				float num12 = ((GTPlayer.Instance != null) ? GTPlayer.Instance.scale : 1f);
				UnityEngine.Vector3 down = UnityEngine.Vector3.down;
				UnityEngine.Vector3 origin = base.transform.parent.position - down * 2f * surfaceCheckDistance * num12;
				float maxDistance = (3f * surfaceCheckDistance + (0f - bottomPointOffset.y)) * num12;
				if (Physics.Raycast(origin, down, out var hitInfo, maxDistance, surfaceLayers.value, QueryTriggerInteraction.Ignore) && UnityEngine.Vector3.Dot(hitInfo.normal, UnityEngine.Vector3.up) > surfaceUprightThreshold && UnityEngine.Vector3.Dot(hitInfo.normal, spinTransform.up) > surfaceDreidelAngleThreshold)
				{
					canStartSpin = true;
					surfacePlanePoint = hitInfo.point;
					surfacePlaneNormal = hitInfo.normal;
					AlignToSurfacePlane();
					groundPointSpring.Reset(GetGroundContactPoint(), UnityEngine.Vector3.zero);
					UpdateSpinTransform();
				}
				else
				{
					canStartSpin = false;
					base.transform.localPosition = UnityEngine.Vector3.zero;
					base.transform.localRotation = UnityEngine.Quaternion.identity;
					spinTransform.localRotation = UnityEngine.Quaternion.identity;
					spinTransform.localPosition = UnityEngine.Vector3.zero;
				}
				break;
			}
			case State.Spinning:
			{
				float num7 = Mathf.Clamp01((float)(num - stateStartTime) / spinTime);
				spinSpeed = Mathf.Lerp(spinSpeedStart, spinSpeedEnd, num7);
				float num8 = (spinCounterClockwise ? (-1f) : 1f);
				spinAngle += num8 * spinSpeed * 360f * deltaTime;
				float num9 = tiltWobble;
				float num10 = Mathf.Sin(spinWobbleFrequency * 2f * MathF.PI * (float)(num - stateStartTime));
				float t = 0.5f * num10 + 0.5f;
				tiltWobble = Mathf.Lerp(spinWobbleAmplitudeEndMin * num7, spinWobbleAmplitude * num7, t);
				if (landingTiltTarget.y == 0f)
				{
					if (landingVariation == Variation.Tumble || landingVariation == Variation.Smooth)
					{
						tiltFrontBack = Mathf.Sign(landingTiltTarget.x) * tiltWobble;
					}
					else
					{
						tiltFrontBack = Mathf.Sign(landingTiltLeadingTarget.x) * tiltWobble;
					}
				}
				else if (landingVariation == Variation.Tumble || landingVariation == Variation.Smooth)
				{
					tiltLeftRight = Mathf.Sign(landingTiltTarget.y) * tiltWobble;
				}
				else
				{
					tiltLeftRight = Mathf.Sign(landingTiltLeadingTarget.y) * tiltWobble;
				}
				float num11 = Mathf.Lerp(pathStartTurnRate, pathEndTurnRate, num7) + num10 * pathTurnRateSinOffset;
				if (spinCounterClockwise)
				{
					pathDir = UnityEngine.Vector3.ProjectOnPlane(UnityEngine.Quaternion.AngleAxis((0f - num11) * deltaTime, UnityEngine.Vector3.up) * pathDir, UnityEngine.Vector3.up);
					pathDir.Normalize();
				}
				else
				{
					pathDir = UnityEngine.Vector3.ProjectOnPlane(UnityEngine.Quaternion.AngleAxis((0f - num11) * deltaTime, UnityEngine.Vector3.up) * pathDir, UnityEngine.Vector3.up);
					pathDir.Normalize();
				}
				pathOffset += pathDir * pathMoveSpeed * deltaTime;
				AlignToSurfacePlane();
				UpdateSpinTransform();
				if (num7 - Mathf.Epsilon >= 1f && tiltWobble > 0.9f * spinWobbleAmplitude && num9 < tiltWobble)
				{
					StartFall();
				}
				break;
			}
			case State.Falling:
			{
				float num2 = fallTimeTumble;
				Variation variation = landingVariation;
				if ((uint)variation <= 1u || (uint)(variation - 2) > 2u)
				{
					spinSpeed = Mathf.MoveTowards(spinSpeed, 0f, spinSpeedStopRate * deltaTime);
					float num3 = (spinCounterClockwise ? (-1f) : 1f);
					spinAngle += num3 * spinSpeed * 360f * deltaTime;
					float angularFrequency = ((landingVariation == Variation.Smooth) ? smoothFallFrequency : tumbleFallFrontBackFrequency);
					float dampingRatio = ((landingVariation == Variation.Smooth) ? smoothFallDampingRatio : tumbleFallFrontBackDampingRatio);
					float angularFrequency2 = ((landingVariation == Variation.Smooth) ? smoothFallFrequency : tumbleFallFrequency);
					float dampingRatio2 = ((landingVariation == Variation.Smooth) ? smoothFallDampingRatio : tumbleFallDampingRatio);
					tiltFrontBack = tiltFrontBackSpring.TrackDampingRatio(landingTiltTarget.x, angularFrequency, dampingRatio, deltaTime);
					tiltLeftRight = tiltLeftRightSpring.TrackDampingRatio(landingTiltTarget.y, angularFrequency2, dampingRatio2, deltaTime);
				}
				else
				{
					bool flag = landingVariation != Variation.Bounce;
					bool flag2 = landingVariation == Variation.FalseSlowTurn;
					float num4 = (flag ? slowTurnSwitchTime : bounceFallSwitchTime);
					if (flag)
					{
						num2 = fallTimeSlowTurn;
					}
					if (num - stateStartTime < (double)num4)
					{
						tiltFrontBack = tiltFrontBackSpring.TrackDampingRatio(landingTiltLeadingTarget.x, tumbleFallFrontBackFrequency, tumbleFallFrontBackDampingRatio, deltaTime);
						tiltLeftRight = tiltLeftRightSpring.TrackDampingRatio(landingTiltLeadingTarget.y, tumbleFallFrequency, tumbleFallDampingRatio, deltaTime);
					}
					else
					{
						tiltFrontBack = tiltFrontBackSpring.TrackDampingRatio(landingTiltTarget.x, tumbleFallFrontBackFrequency, tumbleFallFrontBackDampingRatio, deltaTime);
						if (flag2)
						{
							if (!falseTargetReached && Mathf.Abs(landingTiltTarget.y - tiltLeftRight) > 0.49f)
							{
								tiltLeftRight = tiltLeftRightSpring.TrackDampingRatio(landingTiltTarget.y, slowTurnFrequency, slowTurnDampingRatio, deltaTime);
							}
							else
							{
								falseTargetReached = true;
								tiltLeftRight = tiltLeftRightSpring.TrackDampingRatio(landingTiltLeadingTarget.y, tumbleFallFrequency, tumbleFallDampingRatio, deltaTime);
							}
						}
						else if (flag && Mathf.Abs(landingTiltTarget.y - tiltLeftRight) > 0.45f)
						{
							tiltLeftRight = tiltLeftRightSpring.TrackDampingRatio(landingTiltTarget.y, slowTurnFrequency, slowTurnDampingRatio, deltaTime);
						}
						else
						{
							tiltLeftRight = tiltLeftRightSpring.TrackDampingRatio(landingTiltTarget.y, tumbleFallFrequency, tumbleFallDampingRatio, deltaTime);
						}
					}
					spinSpeed = Mathf.MoveTowards(spinSpeed, 0f, spinSpeedStopRate * deltaTime);
					float num5 = (spinCounterClockwise ? (-1f) : 1f);
					spinAngle += num5 * spinSpeed * 360f * deltaTime;
				}
				AlignToSurfacePlane();
				UpdateSpinTransform();
				float num6 = (float)(num - stateStartTime);
				if (!(num6 > num2))
				{
					break;
				}
				if (!hasLanded)
				{
					hasLanded = true;
					if (landingSide == Side.Gimel)
					{
						gimelConfetti.transform.position = spinTransform.position + UnityEngine.Vector3.up * confettiHeight;
						gimelConfetti.gameObject.SetActive(value: true);
						audioSource.GTPlayOneShot(gimelConfettiSound);
					}
				}
				if (num6 > num2 + respawnTimeAfterLanding)
				{
					StartIdle();
				}
				break;
			}
			case State.Fallen:
				break;
			}
		}

		private void StartIdle()
		{
			state = State.Idle;
			stateStartTime = (PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time));
			canStartSpin = false;
			spinAngle = 0f;
			base.transform.localPosition = UnityEngine.Vector3.zero;
			base.transform.localRotation = UnityEngine.Quaternion.identity;
			spinTransform.localRotation = UnityEngine.Quaternion.identity;
			spinTransform.localPosition = UnityEngine.Vector3.zero;
			tiltFrontBack = 0f;
			tiltLeftRight = 0f;
			pathOffset = UnityEngine.Vector3.zero;
			pathDir = UnityEngine.Vector3.forward;
			gimelConfetti.gameObject.SetActive(value: false);
			groundPointSpring.Reset(GetGroundContactPoint(), UnityEngine.Vector3.zero);
			UpdateSpinTransform();
		}

		private void StartFindingSurfaces()
		{
			state = State.FindingSurface;
			stateStartTime = (PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time));
			canStartSpin = false;
			spinAngle = 0f;
			base.transform.localPosition = UnityEngine.Vector3.zero;
			base.transform.localRotation = UnityEngine.Quaternion.identity;
			spinTransform.localRotation = UnityEngine.Quaternion.identity;
			spinTransform.localPosition = UnityEngine.Vector3.zero;
			tiltFrontBack = 0f;
			tiltLeftRight = 0f;
			pathOffset = UnityEngine.Vector3.zero;
			pathDir = UnityEngine.Vector3.forward;
			gimelConfetti.gameObject.SetActive(value: false);
			groundPointSpring.Reset(GetGroundContactPoint(), UnityEngine.Vector3.zero);
			UpdateSpinTransform();
		}

		private void StartSpin()
		{
			state = State.Spinning;
			stateStartTime = ((spinStartTime > 0.0) ? spinStartTime : ((double)Time.time));
			canStartSpin = false;
			spinSpeed = spinSpeedStart;
			tiltWobble = 0f;
			audioSource.loop = true;
			audioSource.clip = spinLoopAudio;
			audioSource.GTPlay();
			gimelConfetti.gameObject.SetActive(value: false);
			AlignToSurfacePlane();
			groundPointSpring.Reset(GetGroundContactPoint(), UnityEngine.Vector3.zero);
			UpdateSpinTransform();
			pathOffset = UnityEngine.Vector3.zero;
			pathDir = UnityEngine.Vector3.forward;
		}

		private void StartFall()
		{
			state = State.Falling;
			stateStartTime = (PhotonNetwork.InRoom ? PhotonNetwork.Time : ((double)Time.time));
			canStartSpin = false;
			falseTargetReached = false;
			hasLanded = false;
			if (landingVariation == Variation.FalseSlowTurn)
			{
				if (spinCounterClockwise)
				{
					GetTiltVectorsForSideWithPrev(landingSide, out landingTiltLeadingTarget, out landingTiltTarget);
				}
				else
				{
					GetTiltVectorsForSideWithNext(landingSide, out landingTiltLeadingTarget, out landingTiltTarget);
				}
			}
			else if (spinCounterClockwise)
			{
				GetTiltVectorsForSideWithNext(landingSide, out landingTiltTarget, out landingTiltLeadingTarget);
			}
			else
			{
				GetTiltVectorsForSideWithPrev(landingSide, out landingTiltTarget, out landingTiltLeadingTarget);
			}
			spinSpeedSpring.Reset(spinSpeed, 0f);
			tiltFrontBackSpring.Reset(tiltFrontBack, 0f);
			tiltLeftRightSpring.Reset(tiltLeftRight, 0f);
			groundPointSpring.Reset(GetGroundContactPoint(), UnityEngine.Vector3.zero);
			audioSource.loop = false;
			audioSource.GTPlayOneShot(fallSound);
			gimelConfetti.gameObject.SetActive(value: false);
		}

		private UnityEngine.Vector3 GetGroundContactPoint()
		{
			UnityEngine.Vector3 position = spinTransform.position;
			dreidelCollider.enabled = true;
			UnityEngine.Vector3 vector = dreidelCollider.ClosestPoint(position - base.transform.up);
			dreidelCollider.enabled = false;
			float num = UnityEngine.Vector3.Dot(vector - position, spinTransform.up);
			if (num > 0f)
			{
				vector -= num * spinTransform.up;
			}
			return spinTransform.InverseTransformPoint(vector);
		}

		private void GetTiltVectorsForSideWithPrev(Side side, out UnityEngine.Vector2 sideTilt, out UnityEngine.Vector2 prevSideTilt)
		{
			int num = (int)((side <= Side.Shin) ? Side.Nun : (side - 1));
			if (side == Side.Hey || side == Side.Nun)
			{
				sideTilt = landingTiltValues[(int)side];
				prevSideTilt = landingTiltValues[num];
				prevSideTilt.x = sideTilt.x;
			}
			else
			{
				prevSideTilt = landingTiltValues[num];
				sideTilt = landingTiltValues[(int)side];
				sideTilt.x = prevSideTilt.x;
			}
		}

		private void GetTiltVectorsForSideWithNext(Side side, out UnityEngine.Vector2 sideTilt, out UnityEngine.Vector2 nextSideTilt)
		{
			int num = (int)(side + 1) % 4;
			if (side == Side.Hey || side == Side.Nun)
			{
				sideTilt = landingTiltValues[(int)side];
				nextSideTilt = landingTiltValues[num];
				nextSideTilt.x = sideTilt.x;
			}
			else
			{
				nextSideTilt = landingTiltValues[num];
				sideTilt = landingTiltValues[(int)side];
				sideTilt.x = nextSideTilt.x;
			}
		}

		private void AlignToSurfacePlane()
		{
			UnityEngine.Vector3 forward = UnityEngine.Vector3.forward;
			if (UnityEngine.Vector3.Dot(UnityEngine.Vector3.up, surfacePlaneNormal) < 0.9999f)
			{
				UnityEngine.Vector3 axis = UnityEngine.Vector3.Cross(surfacePlaneNormal, UnityEngine.Vector3.up);
				forward = UnityEngine.Quaternion.AngleAxis(90f, axis) * surfacePlaneNormal;
			}
			UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(forward, surfacePlaneNormal);
			base.transform.position = surfacePlanePoint;
			base.transform.rotation = rotation;
		}

		private void UpdateSpinTransform()
		{
			UnityEngine.Vector3 position = spinTransform.position;
			UnityEngine.Vector3 groundContactPoint = GetGroundContactPoint();
			UnityEngine.Vector3 position2 = groundPointSpring.TrackDampingRatio(groundContactPoint, groundTrackingFrequency, groundTrackingDampingRatio, Time.deltaTime);
			UnityEngine.Vector3 vector = spinTransform.TransformPoint(position2);
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.AngleAxis(90f * tiltLeftRight, UnityEngine.Vector3.forward) * UnityEngine.Quaternion.AngleAxis(90f * tiltFrontBack, UnityEngine.Vector3.right);
			spinAxis = base.transform.InverseTransformDirection(base.transform.up);
			UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.AngleAxis(spinAngle, spinAxis);
			spinTransform.localRotation = quaternion3 * quaternion2;
			UnityEngine.Vector3 vector2 = base.transform.InverseTransformVector(UnityEngine.Vector3.Dot(position - vector, base.transform.up) * base.transform.up);
			spinTransform.localPosition = vector2 + pathOffset;
			spinTransform.TransformPoint(bottomPointOffset);
		}
	}
	public class EnvironmentProximityReactor : MonoBehaviour
	{
		[Serializable]
		public class InteractionBlock
		{
			[Tooltip("Keys this block broadcasts. Cosmetics whose Key List or Listener List contains a matching key can trigger this block.")]
			public List<string> interactionKeys = new List<string>();

			[Tooltip("If the cosmetic broadcasts any of these keys this block will not fire, even if another key matches.")]
			public List<string> ignoreKeys = new List<string>();

			[Tooltip("React when a cosmetic broadcasts one of these keys. Listener keys are never broadcast outward, so two Listener-only objects will never trigger each other.")]
			public List<string> listenerKeys = new List<string>();

			[Tooltip("Distance (m) at which a cosmetic triggers this block.")]
			public float proximityThreshold = 0.3f;

			[Tooltip("Minimum seconds between consecutive OnBelow triggers for this block.")]
			[SerializeField]
			private float cooldownTime = 0.5f;

			[Tooltip("Fires immediately on the client whose cosmetic crossed below the threshold. Local-only")]
			public UnityEvent<UnityEngine.Vector3> onBelowLocal;

			[Tooltip("Fires on aLL clients when any player's cosmetic crosses below the threshold.")]
			public UnityEvent<UnityEngine.Vector3> onBelowShared;

			[Tooltip("Fires every frame on the triggering client while the cosmetic remains below the threshold. Local-only")]
			public UnityEvent<UnityEngine.Vector3> whileBelowLocal;

			[Tooltip("Fires every frame on ALL clients while any player's cosmetic remains below the threshold.")]
			public UnityEvent<UnityEngine.Vector3> whileBelowShared;

			[Tooltip("Fires on the triggering client when the cosmetic goes back above the threshold.")]
			public UnityEvent onAboveLocal;

			[Tooltip("Fires on aLL clients when the cosmetic goes back above the threshold.")]
			public UnityEvent onAboveShared;

			[NonSerialized]
			public bool wasBelow;

			[NonSerialized]
			public bool wasSharedBelow;

			[NonSerialized]
			public float lastTriggerTime = -9999f;

			public bool CanTriggerFrom(CosmeticsProximityReactor cosmetic)
			{
				foreach (CosmeticsProximityReactor.InteractionSetting block in cosmetic.blocks)
				{
					if ((block.mode != CosmeticsProximityReactor.InteractionMode.CosmeticToCosmetic && block.mode != CosmeticsProximityReactor.InteractionMode.CosmeticToEnvironment) || block.interactionKeys == null || block.interactionKeys.Count == 0)
					{
						continue;
					}
					if (ignoreKeys != null && ignoreKeys.Count > 0)
					{
						bool flag = false;
						foreach (string interactionKey in block.interactionKeys)
						{
							if (!string.IsNullOrEmpty(interactionKey) && ignoreKeys.Contains(interactionKey))
							{
								flag = true;
								break;
							}
						}
						if (flag)
						{
							continue;
						}
					}
					foreach (string interactionKey2 in block.interactionKeys)
					{
						if (!string.IsNullOrEmpty(interactionKey2))
						{
							if (interactionKeys != null && interactionKeys.Contains(interactionKey2))
							{
								return true;
							}
							if (listenerKeys != null && listenerKeys.Contains(interactionKey2))
							{
								return true;
							}
						}
					}
				}
				return false;
			}

			public bool CanPlay(float now)
			{
				return now - lastTriggerTime >= cooldownTime;
			}
		}

		public List<InteractionBlock> blocks = new List<InteractionBlock>();

		[Tooltip("Optional collider for precise proximity measurement. If unassigned, the transform position is used.")]
		public Collider proximityCollider;

		public int reactorId;

		public string staticId;

		[Tooltip("Leave off for most objects- the ID is computed automatically from the hierarchy path, type name, and world position, so no manual setup is needed.\n\nEnable only if this object is expected to move or be renamed in the editor after the ID has already been referenced elsewhere When enabled, the ID is pinned to the Static ID string above so it stays stable across repositions. Hit Recalculate once to generate it, then leave it alone.")]
		public bool useStaticId;

		private void OnEnable()
		{
			if (!useStaticId)
			{
				CalculateId();
			}
			EnvironmentProximityReactorManager.Register(this);
		}

		private void OnDisable()
		{
			EnvironmentProximityReactorManager.Unregister(this);
			ResetBlockState();
		}

		private void Update()
		{
			if (CosmeticsProximityReactorManager.Instance == null)
			{
				return;
			}
			IReadOnlyList<CosmeticsProximityReactor> cosmetics = CosmeticsProximityReactorManager.Instance.Cosmetics;
			float time = Time.time;
			for (int i = 0; i < blocks.Count; i++)
			{
				InteractionBlock interactionBlock = blocks[i];
				bool flag = false;
				UnityEngine.Vector3 arg = base.transform.position;
				for (int j = 0; j < cosmetics.Count; j++)
				{
					CosmeticsProximityReactor cosmeticsProximityReactor = cosmetics[j];
					if (!(cosmeticsProximityReactor == null))
					{
						VRRig ownerRig = cosmeticsProximityReactor.GetOwnerRig();
						if (!(ownerRig == null) && ownerRig.isLocal && interactionBlock.CanTriggerFrom(cosmeticsProximityReactor) && AreWithinThreshold(cosmeticsProximityReactor, interactionBlock.proximityThreshold, out var contactPoint))
						{
							flag = true;
							arg = contactPoint;
							break;
						}
					}
				}
				if (flag)
				{
					if (!interactionBlock.wasBelow && interactionBlock.CanPlay(time))
					{
						interactionBlock.wasBelow = true;
						interactionBlock.wasSharedBelow = true;
						interactionBlock.lastTriggerTime = time;
						interactionBlock.onBelowLocal?.Invoke(arg);
						interactionBlock.onBelowShared?.Invoke(arg);
						EnvironmentProximityReactorManager.Instance?.BroadcastProximityState(reactorId, i, isBelow: true);
					}
					else if (interactionBlock.wasBelow)
					{
						interactionBlock.whileBelowLocal?.Invoke(arg);
						interactionBlock.whileBelowShared?.Invoke(arg);
						if (!interactionBlock.wasSharedBelow)
						{
							interactionBlock.wasSharedBelow = true;
							interactionBlock.onBelowShared?.Invoke(arg);
							EnvironmentProximityReactorManager.Instance?.BroadcastProximityState(reactorId, i, isBelow: true);
						}
					}
				}
				else if (interactionBlock.wasBelow)
				{
					interactionBlock.wasBelow = false;
					interactionBlock.wasSharedBelow = false;
					interactionBlock.onAboveLocal?.Invoke();
					interactionBlock.onAboveShared?.Invoke();
					EnvironmentProximityReactorManager.Instance?.BroadcastProximityState(reactorId, i, isBelow: false);
				}
				if (interactionBlock.wasSharedBelow && !interactionBlock.wasBelow)
				{
					interactionBlock.whileBelowShared?.Invoke(base.transform.position);
				}
			}
		}

		public void SyncStateTo(NetPlayer newPlayer, EnvironmentProximityReactorManager manager)
		{
			for (int i = 0; i < blocks.Count; i++)
			{
				if (blocks[i].wasBelow)
				{
					manager.BroadcastProximityStateTo(newPlayer, reactorId, i, isBelow: true);
				}
			}
		}

		public void ApplySharedProximity(int blockIndex, bool isBelow)
		{
			if (blockIndex >= 0 && blockIndex < blocks.Count)
			{
				InteractionBlock interactionBlock = blocks[blockIndex];
				if (isBelow)
				{
					interactionBlock.wasSharedBelow = true;
					interactionBlock.onBelowShared?.Invoke(base.transform.position);
				}
				else
				{
					interactionBlock.wasSharedBelow = false;
					interactionBlock.onAboveShared?.Invoke();
				}
			}
		}

		private bool AreWithinThreshold(CosmeticsProximityReactor cosmetic, float threshold, out UnityEngine.Vector3 contactPoint)
		{
			UnityEngine.Vector3 vector = ((cosmetic.collider == null) ? cosmetic.transform.position : cosmetic.collider.ClosestPoint(base.transform.position));
			UnityEngine.Vector3 vector2 = ((proximityCollider == null) ? base.transform.position : proximityCollider.ClosestPoint(vector));
			contactPoint = (vector + vector2) * 0.5f;
			return UnityEngine.Vector3.Distance(vector, vector2) <= threshold;
		}

		private void CalculateId(bool force = false)
		{
			Transform transform = base.transform;
			int hashCode = TransformUtils.ComputePathHash(transform).ToId128().GetHashCode();
			int staticHash = GetType().Name.GetStaticHash();
			int hashCode2 = transform.position.QuantizedId128().GetHashCode();
			int num = StaticHash.Compute(hashCode, staticHash, hashCode2);
			if (useStaticId)
			{
				if (string.IsNullOrEmpty(staticId) || force)
				{
					int instanceID = transform.GetInstanceID();
					int num2 = StaticHash.Compute(num, instanceID);
					staticId = $"#ID_{num2:X8}";
				}
				reactorId = staticId.GetStaticHash();
			}
			else
			{
				reactorId = (UnityEngine.Application.isPlaying ? num : 0);
			}
		}

		private void ResetBlockState()
		{
			foreach (InteractionBlock block in blocks)
			{
				block.wasBelow = false;
				block.wasSharedBelow = false;
				block.lastTriggerTime = -9999f;
			}
		}

		private void EdRecalculateId()
		{
			CalculateId(force: true);
		}
	}
	public class EnvironmentProximityReactorManager : NetworkSceneObject
	{
		private struct PendingProximityEvent
		{
			public int reactorId;

			public int blockIndex;

			public bool isBelow;

			public PhotonMessageInfoWrapped info;

			public float receivedTime;
		}

		private static EnvironmentProximityReactorManager instance;

		[SerializeField]
		private List<EnvironmentProximityReactor> reactors = new List<EnvironmentProximityReactor>();

		private readonly HashSet<int> idSet = new HashSet<int>();

		private readonly Dictionary<int, List<PendingProximityEvent>> pendingEvents = new Dictionary<int, List<PendingProximityEvent>>();

		private float distanceBuffer = 3f;

		private const float cosmeticSyncTimeout = 10f;

		private static readonly HashSet<EnvironmentProximityReactor> registry = new HashSet<EnvironmentProximityReactor>();

		public static EnvironmentProximityReactorManager Instance => instance;

		private void Awake()
		{
			if (instance != null && instance != this)
			{
				GTDev.LogWarning("[EnvironmentProximityReactorManager] Duplicate instance of the Environment Reactor Manager, destroying.");
				UnityEngine.Object.Destroy(this);
				return;
			}
			instance = this;
			foreach (EnvironmentProximityReactor item in registry)
			{
				if (item != null)
				{
					RegisterInstance(item);
				}
			}
			registry.Clear();
			RoomSystem.PlayerJoinedEvent += new Action<NetPlayer>(OnPlayerJoined);
			RoomSystem.PlayerLeftEvent += new Action<NetPlayer>(OnPlayerLeft);
			RoomSystem.LeftRoomEvent += new Action(OnLeftRoom);
			CosmeticsProximityReactorManager.OnCosmeticRegistered += OnCosmeticRegistered;
		}

		private void OnDestroy()
		{
			NetworkBehaviourUtils.InternalOnDestroy(this);
			if (instance == this)
			{
				instance = null;
			}
			if (NetworkSystem.Instance != null)
			{
				RoomSystem.PlayerJoinedEvent -= new Action<NetPlayer>(OnPlayerJoined);
				RoomSystem.PlayerLeftEvent -= new Action<NetPlayer>(OnPlayerLeft);
				RoomSystem.LeftRoomEvent -= new Action(OnLeftRoom);
			}
			CosmeticsProximityReactorManager.OnCosmeticRegistered -= OnCosmeticRegistered;
		}

		private void OnPlayerLeft(NetPlayer player)
		{
			pendingEvents.Remove(player.ActorNumber);
		}

		private void OnLeftRoom()
		{
			pendingEvents.Clear();
		}

		private void OnPlayerJoined(NetPlayer newPlayer)
		{
			if (newPlayer.IsLocal || !NetworkSystem.Instance.InRoom)
			{
				return;
			}
			for (int i = 0; i < reactors.Count; i++)
			{
				if (reactors[i] != null)
				{
					reactors[i].SyncStateTo(newPlayer, this);
				}
			}
		}

		public void BroadcastProximityStateTo(NetPlayer target, int reactorId, int blockIndex, bool isBelow)
		{
			if (NetworkSystem.Instance.InRoom)
			{
				photonView.RPC("ProximityStateRPC", ((PunNetPlayer)target).PlayerRef, reactorId, blockIndex, isBelow);
			}
		}

		private bool CheckPlayerRateLimit(NetPlayer sender)
		{
			if (!VRRigCache.Instance.TryGetVrrig(sender, out var playerRig))
			{
				return false;
			}
			return playerRig.Rig.fxSettings.callSettings[24].CallLimitSettings.CheckCallTime(Time.unscaledTime);
		}

		private bool SenderHasValidCosmetic(int reactorId, int blockIndex, PhotonMessageInfoWrapped info)
		{
			if (CosmeticsProximityReactorManager.Instance == null)
			{
				return false;
			}
			EnvironmentProximityReactor environmentProximityReactor = null;
			for (int i = 0; i < reactors.Count; i++)
			{
				if (reactors[i] != null && reactors[i].reactorId == reactorId)
				{
					environmentProximityReactor = reactors[i];
					break;
				}
			}
			if (environmentProximityReactor == null || blockIndex >= environmentProximityReactor.blocks.Count)
			{
				return false;
			}
			EnvironmentProximityReactor.InteractionBlock interactionBlock = environmentProximityReactor.blocks[blockIndex];
			IReadOnlyList<CosmeticsProximityReactor> cosmetics = CosmeticsProximityReactorManager.Instance.Cosmetics;
			for (int j = 0; j < cosmetics.Count; j++)
			{
				CosmeticsProximityReactor cosmeticsProximityReactor = cosmetics[j];
				if (!(cosmeticsProximityReactor == null))
				{
					VRRig ownerRig = cosmeticsProximityReactor.GetOwnerRig();
					if (!(ownerRig == null) && ownerRig.Creator == info.Sender && interactionBlock.CanTriggerFrom(cosmeticsProximityReactor))
					{
						return true;
					}
				}
			}
			return false;
		}

		private bool SenderIsInRange(int reactorId, int blockIndex, PhotonMessageInfoWrapped info)
		{
			if (!VRRigCache.Instance.TryGetVrrig(info.Sender, out var playerRig))
			{
				return false;
			}
			EnvironmentProximityReactor environmentProximityReactor = null;
			for (int i = 0; i < reactors.Count; i++)
			{
				if (reactors[i] != null && reactors[i].reactorId == reactorId)
				{
					environmentProximityReactor = reactors[i];
					break;
				}
			}
			if (environmentProximityReactor == null || blockIndex >= environmentProximityReactor.blocks.Count)
			{
				return false;
			}
			float range = environmentProximityReactor.blocks[blockIndex].proximityThreshold + distanceBuffer;
			return playerRig.Rig.IsPositionInRange(environmentProximityReactor.transform.position, range);
		}

		private void OnCosmeticRegistered(CosmeticsProximityReactor cosmetic)
		{
			VRRig ownerRig = cosmetic.GetOwnerRig();
			if (ownerRig == null || ownerRig.Creator == null)
			{
				return;
			}
			int actorNumber = ownerRig.Creator.ActorNumber;
			if (!pendingEvents.TryGetValue(actorNumber, out var value))
			{
				return;
			}
			float unscaledTime = Time.unscaledTime;
			for (int num = value.Count - 1; num >= 0; num--)
			{
				PendingProximityEvent pendingProximityEvent = value[num];
				if (unscaledTime - pendingProximityEvent.receivedTime > 10f)
				{
					value.RemoveAt(num);
				}
				else if (SenderHasValidCosmetic(pendingProximityEvent.reactorId, pendingProximityEvent.blockIndex, pendingProximityEvent.info))
				{
					if (!SenderIsInRange(pendingProximityEvent.reactorId, pendingProximityEvent.blockIndex, pendingProximityEvent.info))
					{
						value.RemoveAt(num);
					}
					else
					{
						ApplyProximityEventToReactor(pendingProximityEvent.reactorId, pendingProximityEvent.blockIndex, pendingProximityEvent.isBelow);
						value.RemoveAt(num);
					}
				}
			}
			if (value.Count == 0)
			{
				pendingEvents.Remove(actorNumber);
			}
		}

		private void Update()
		{
			if (pendingEvents.Count == 0)
			{
				return;
			}
			float unscaledTime = Time.unscaledTime;
			foreach (KeyValuePair<int, List<PendingProximityEvent>> pendingEvent in pendingEvents)
			{
				List<PendingProximityEvent> value = pendingEvent.Value;
				for (int num = value.Count - 1; num >= 0; num--)
				{
					if (unscaledTime - value[num].receivedTime > 10f)
					{
						value.RemoveAt(num);
					}
				}
			}
			foreach (KeyValuePair<int, List<PendingProximityEvent>> pendingEvent2 in pendingEvents)
			{
				if (pendingEvent2.Value.Count == 0)
				{
					pendingEvents.Remove(pendingEvent2.Key);
					break;
				}
			}
		}

		private void TryCacheProximityEvent(int reactorId, int blockIndex, bool isBelow, PhotonMessageInfoWrapped info)
		{
			int actorNumber = info.Sender.ActorNumber;
			if (!pendingEvents.TryGetValue(actorNumber, out var value))
			{
				value = new List<PendingProximityEvent>();
				pendingEvents[actorNumber] = value;
			}
			else if (value.Exists((PendingProximityEvent e) => e.reactorId == reactorId))
			{
				return;
			}
			value.Add(new PendingProximityEvent
			{
				reactorId = reactorId,
				blockIndex = blockIndex,
				isBelow = isBelow,
				info = info,
				receivedTime = Time.unscaledTime
			});
		}

		private void ApplyProximityEventToReactor(int reactorId, int blockIndex, bool isBelow)
		{
			for (int i = 0; i < reactors.Count; i++)
			{
				EnvironmentProximityReactor environmentProximityReactor = reactors[i];
				if (!(environmentProximityReactor == null) && environmentProximityReactor.reactorId == reactorId)
				{
					environmentProximityReactor.ApplySharedProximity(blockIndex, isBelow);
					break;
				}
			}
		}

		private void RegisterInstance(EnvironmentProximityReactor reactor)
		{
			if (!(reactor == null) && idSet.Add(reactor.reactorId))
			{
				reactors.Add(reactor);
			}
		}

		private void UnregisterInstance(EnvironmentProximityReactor reactor)
		{
			if (!(reactor == null) && idSet.Remove(reactor.reactorId))
			{
				reactors.Remove(reactor);
			}
		}

		public static void Register(EnvironmentProximityReactor reactor)
		{
			if (instance != null)
			{
				instance.RegisterInstance(reactor);
			}
			else
			{
				registry.Add(reactor);
			}
		}

		public static void Unregister(EnvironmentProximityReactor reactor)
		{
			if (instance != null)
			{
				instance.UnregisterInstance(reactor);
			}
			else
			{
				registry.Remove(reactor);
			}
		}

		public void BroadcastProximityState(int reactorId, int blockIndex, bool isBelow)
		{
			if (NetworkSystem.Instance.InRoom)
			{
				photonView.RPC("ProximityStateRPC", RpcTarget.Others, reactorId, blockIndex, isBelow);
			}
		}

		[PunRPC]
		public void ProximityStateRPC(int reactorId, int blockIndex, bool isBelow, PhotonMessageInfo info)
		{
			ApplyProximityStateShared(reactorId, blockIndex, isBelow, new PhotonMessageInfoWrapped(info));
		}

		[Rpc]
