		}

		public void CompleteManualStage()
		{
			if (!activeStage.HasDuration)
			{
				ForceNextStage();
			}
		}

		public void ForceNextStage()
		{
			totalElapsedTime = totalTimeOfPreviousStages + activeStage.Duration;
			HandleStages();
		}

		private void SendElapsedTime(NetPlayer player)
		{
