			totalTimeOfPreviousStages = num;
			totalElapsedTime = num + Mathf.Epsilon;
			nextEventIndex = 0;
			nextEvent = activeStage.GetEventOrNull(0);
			if (activeStage.HasDuration)
			{
				TickSystem<object>.AddTickCallback(this);
			}
			else
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
			int num2 = 0;
			for (EvolutionStage.EventAtTime eventOrNull = activeStage.GetEventOrNull(num2); eventOrNull != null; eventOrNull = activeStage.GetEventOrNull(num2))
			{
				eventOrNull.onTimeReached?.Invoke();
				num2++;
			}
			HandleStages();
		}

		private void RestartStageInternal()
		{
			SetStage(activeStageIndex);
		}

		public void IncrementStage()
		{
			SetStage(activeStageIndex + 1);
		}

		public void DecrementStage()
		{
			SetStage(activeStageIndex - 1);
		}

		public void JumpToFirstStage()
		{
			SetStage(0);
		}

		public void JumpToLastStage()
		{
			if (stages != null && stages.Length != 0)
			{
				SetStage(stages.Length - 1);
			}
		}

		public void RestartCurrentStage()
		{
			RestartStageInternal();
		}

		public void JumpToStageIndex(int index)
		{
			SetStage(index);
		}
	}
	public class FartBagThrowable : MonoBehaviour, IProjectile
	{
		[SerializeField]
		private GameObject deflationEffect;

		[SerializeField]
		private float destroyWhenDeflateDelay = 3f;

		[SerializeField]
		private float forceDestroyAfterSec = 10f;

		[SerializeField]
		private float placementOffset = 0.2f;

		[SerializeField]
		private UpdateBlendShapeCosmetic updateBlendShapeCosmetic;

		[SerializeField]
		private LayerMask floorLayerMask;

		[SerializeField]
		private LayerMask handLayerMask;

		[SerializeField]
		private Rigidbody rigidbody;

		private bool placedOnFloor;

		private float placedOnFloorTime;

		private float timeCreated;

		private bool deflated;

		private UnityEngine.Vector3 handContactPoint;

		private UnityEngine.Vector3 handNormalVector;

		private CallLimiter callLimiter = new CallLimiter(10, 2f);

		private RubberDuckEvents _events;

		public TransferrableObject ParentTransferable { get; set; }

		public event Action<IProjectile> OnDeflated;

		private void OnEnable()
		{
			placedOnFloor = false;
			deflated = false;
			handContactPoint = UnityEngine.Vector3.negativeInfinity;
			handNormalVector = UnityEngine.Vector3.zero;
			timeCreated = float.PositiveInfinity;
			placedOnFloorTime = float.PositiveInfinity;
			if ((bool)updateBlendShapeCosmetic)
			{
				updateBlendShapeCosmetic.ResetBlend();
			}
		}

		private void Update()
		{
			if (Time.time - timeCreated > forceDestroyAfterSec)
			{
				DeflateLocal();
			}
		}

		public void Launch(UnityEngine.Vector3 startPosition, UnityEngine.Quaternion startRotation, UnityEngine.Vector3 velocity, float chargeFrac, VRRig ownerRig, int progress)
		{
			base.transform.position = startPosition;
			base.transform.rotation = startRotation;
			base.transform.localScale = UnityEngine.Vector3.one * ownerRig.scaleFactor;
			rigidbody.linearVelocity = velocity;
			timeCreated = Time.time;
			InitialPhotonEvent();
		}

		private void InitialPhotonEvent()
		{
			_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
			if ((bool)ParentTransferable)
			{
				NetPlayer netPlayer = ((ParentTransferable.myOnlineRig != null) ? ParentTransferable.myOnlineRig.creator : ((ParentTransferable.myRig != null) ? (ParentTransferable.myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : null));
				if (_events != null && netPlayer != null)
				{
					_events.Init(netPlayer);
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(DeflateEvent);
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			if ((handLayerMask.value & (1 << other.gameObject.layer)) != 0 && placedOnFloor)
			{
				handContactPoint = other.ClosestPoint(base.transform.position);
				handNormalVector = (handContactPoint - base.transform.position).normalized;
				if (Time.time - placedOnFloorTime > 0.3f)
				{
					Deflate();
				}
			}
		}

		private void OnCollisionEnter(UnityEngine.Collision other)
		{
			if ((floorLayerMask.value & (1 << other.gameObject.layer)) != 0)
			{
				placedOnFloor = true;
				placedOnFloorTime = Time.time;
				UnityEngine.Vector3 normal = other.contacts[0].normal;
				base.transform.position = other.contacts[0].point + normal * placementOffset;
				UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.ProjectOnPlane(base.transform.forward, normal).normalized, normal);
				base.transform.rotation = rotation;
			}
		}

		private void Deflate()
		{
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(handContactPoint, handNormalVector);
			}
			DeflateLocal();
		}

		private void DeflateEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender == target && args.Length == 2)
			{
				MonkeAgent.IncrementRPCCall(info, "DeflateEvent");
				if (callLimiter.CheckCallTime(Time.time) && args[0] is UnityEngine.Vector3 v && args[1] is UnityEngine.Vector3 v2 && v2.IsValid(10000f) && v.IsValid(10000f) && ParentTransferable.targetRig.IsPositionInRange(v, 4f))
				{
					handNormalVector = v2;
					handContactPoint = v;
					DeflateLocal();
				}
			}
		}

		private void DeflateLocal()
		{
			if (!deflated)
			{
				GameObject obj = ObjectPools.instance.Instantiate(deflationEffect, handContactPoint);
				obj.transform.up = handNormalVector;
				obj.transform.position = base.transform.position;
				SoundBankPlayer componentInChildren = obj.GetComponentInChildren<SoundBankPlayer>();
				if ((bool)componentInChildren.soundBank)
				{
					componentInChildren.Play();
				}
				placedOnFloor = false;
				timeCreated = float.PositiveInfinity;
				if ((bool)updateBlendShapeCosmetic)
				{
					updateBlendShapeCosmetic.FullyBlend();
				}
				deflated = true;
				Invoke("DisableObject", destroyWhenDeflateDelay);
			}
		}

		private void DisableObject()
		{
			this.OnDeflated?.Invoke(this);
			deflated = false;
		}

		private void OnDestroy()
		{
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(DeflateEvent);
				_events.Dispose();
				_events = null;
			}
		}
	}
	public class FingerFlexEvent : MonoBehaviourTick
	{
		[Serializable]
		public class Listener
		{
			public EventType eventType;

			public UnityEvent<bool, float> listenerComponent;

			public float fingerFlexValue = 0.75f;

			public float fingerReleaseValue = 0.01f;

			[Tooltip("How many frames should pass to fire a finger flex stayed event")]
			public int frameInterval = 20;

			[Tooltip("This event will be fired for everyone in the room (synced) by default unless you uncheck this box so that it will be fired only for the local player.")]
			public bool syncForEveryoneInRoom = true;

			[Tooltip("Fire these events only when the item is held in hand, only works if there is a transferable component somewhere on the object or its parent.")]
			public bool fireOnlyWhileHeld = true;

			[Tooltip("Whether to check the left hand or the right hand, only works if \"ignoreTransferable\" is true.")]
			public bool checkLeftHand;

			internal int frameCounter;

			internal float fingerRightLastValue;

			internal float fingerLeftLastValue;
		}

		public enum EventType
		{
			OnFingerFlexed,
			OnFingerReleased,
			OnFingerFlexStayed
		}

		private enum FingerType
		{
			Thumb,
			Index,
			Middle,
			IndexAndMiddleMin
		}

		[SerializeField]
		public bool ignoreTransferable;

		[SerializeField]
		private FingerType fingerType = FingerType.Index;

		public Listener[] eventListeners = new Listener[0];

		private VRRig _rig;

		private TransferrableObject parentTransferable;

		private IHeldItem myHeldItem;

		private void Awake()
		{
			_rig = GetComponentInParent<VRRig>();
			parentTransferable = GetComponentInParent<TransferrableObject>();
			myHeldItem = GetComponentInParent<IHeldItem>();
		}

		private bool IsMyItem()
		{
			if (_rig != null)
			{
				return _rig.isOfflineVRRig;
			}
			return false;
		}

		public override void Tick()
		{
			for (int i = 0; i < eventListeners.Length; i++)
			{
				Listener listener = eventListeners[i];
				FireEvents(listener);
			}
		}

		private void FireEvents(Listener listener)
		{
			if (!listener.syncForEveryoneInRoom && !IsMyItem())
			{
				return;
			}
			bool flag = parentTransferable != null || myHeldItem != null;
			bool flag2 = ((parentTransferable != null) ? parentTransferable.InHand() : (myHeldItem?.InHand() ?? true));
			if (!ignoreTransferable && listener.fireOnlyWhileHeld && flag && !flag2 && listener.eventType == EventType.OnFingerReleased)
			{
				if (listener.fingerRightLastValue > listener.fingerReleaseValue)
				{
					listener.listenerComponent?.Invoke(arg0: false, 0f);
					listener.fingerRightLastValue = 0f;
				}
				if (listener.fingerLeftLastValue > listener.fingerReleaseValue)
				{
					listener.listenerComponent?.Invoke(arg0: true, 0f);
					listener.fingerLeftLastValue = 0f;
				}
			}
			if (!(!ignoreTransferable && flag) || !listener.fireOnlyWhileHeld || flag2)
			{
				switch (fingerType)
				{
				case FingerType.Index:
				{
					float calcT5 = _rig.leftIndex.calcT;
					float calcT6 = _rig.rightIndex.calcT;
					FireEvents(listener, calcT5, calcT6);
					break;
				}
				case FingerType.Middle:
				{
					float calcT3 = _rig.leftMiddle.calcT;
					float calcT4 = _rig.rightMiddle.calcT;
					FireEvents(listener, calcT3, calcT4);
					break;
				}
				case FingerType.Thumb:
				{
					float calcT = _rig.leftThumb.calcT;
					float calcT2 = _rig.rightThumb.calcT;
					FireEvents(listener, calcT, calcT2);
					break;
				}
				case FingerType.IndexAndMiddleMin:
				{
					float leftFinger = Mathf.Min(_rig.leftIndex.calcT, _rig.leftMiddle.calcT);
					float rightFinger = Mathf.Min(_rig.rightIndex.calcT, _rig.rightMiddle.calcT);
					FireEvents(listener, leftFinger, rightFinger);
					break;
				}
				}
			}
		}

		private void FireEvents(Listener listener, float leftFinger, float rightFinger)
		{
			bool flag = parentTransferable != null || myHeldItem != null;
			if ((ignoreTransferable && listener.checkLeftHand) || (!ignoreTransferable && flag && FingerFlexValidation(isLeftHand: true)))
			{
				CheckFingerValue(listener, leftFinger, isLeft: true, ref listener.fingerLeftLastValue);
				return;
			}
			if ((ignoreTransferable && !listener.checkLeftHand) || (!ignoreTransferable && flag && FingerFlexValidation(isLeftHand: false)))
			{
				CheckFingerValue(listener, rightFinger, isLeft: false, ref listener.fingerRightLastValue);
				return;
			}
			CheckFingerValue(listener, leftFinger, isLeft: true, ref listener.fingerLeftLastValue);
			CheckFingerValue(listener, rightFinger, isLeft: false, ref listener.fingerRightLastValue);
		}

		private void CheckFingerValue(Listener listener, float fingerValue, bool isLeft, ref float lastValue)
		{
			if (fingerValue > listener.fingerFlexValue)
			{
				listener.frameCounter++;
			}
			switch (listener.eventType)
			{
			case EventType.OnFingerFlexed:
				if (fingerValue > listener.fingerFlexValue && lastValue < listener.fingerFlexValue)
				{
					listener.listenerComponent?.Invoke(isLeft, fingerValue);
				}
				break;
			case EventType.OnFingerReleased:
				if (fingerValue <= listener.fingerReleaseValue && lastValue > listener.fingerReleaseValue)
				{
					listener.listenerComponent?.Invoke(isLeft, fingerValue);
					listener.frameCounter = 0;
				}
				break;
			case EventType.OnFingerFlexStayed:
				if (fingerValue > listener.fingerFlexValue && lastValue >= listener.fingerFlexValue && listener.frameCounter % listener.frameInterval == 0)
				{
					listener.listenerComponent?.Invoke(isLeft, fingerValue);
					listener.frameCounter = 0;
				}
				break;
			}
			lastValue = fingerValue;
		}

		private bool FingerFlexValidation(bool isLeftHand)
		{
			bool flag = ((parentTransferable != null) ? parentTransferable.InLeftHand() : (myHeldItem?.InLeftHand() ?? false));
			if (flag && !isLeftHand)
			{
				return false;
			}
			if (!flag && isLeftHand)
			{
				return false;
			}
			return true;
		}
	}
	public class FingerFlexEvent2 : MonoBehaviour, ITickSystemTick
	{
		[Serializable]
		public class FlexEvent
		{
			public enum TriggerType
			{
				OnFlex = 0,
				OnRelease = 2
			}

			public enum FingerType
			{
				Thumb,
				Index,
				Middle,
				IndexAndMiddle,
				IndexOrMiddle
			}

			public enum HandType
			{
				HeldItemHand,
				EquippedSide,
				LeftHand,
				RightHand
			}

			private enum RangeState
			{
				Below,
				Within,
				Above
			}

			public TriggerType triggerType;

			public bool tryLink = true;

			[HideInInspector]
			public int linkIndex = -1;

			[Space]
			public FingerType fingerType = FingerType.Index;

			[Space]
			public HandType handType;

			private const string ADVANCED = "Advanced Properties";

			[Tooltip("When this is checked, all players in the room will fire the event. Otherwise, only the local player will fire it. You should usually leave this on, unless you're using it for something local like controller haptics.")]
			public bool networked = true;

			[Range(0.01f, 0.75f)]
			public float flexThreshold = 0.75f;

			[Range(0.01f, 1f)]
			public float releaseThreshold = 0.01f;

			public ContinuousPropertyArray continuousProperties;

			public UnityEvent<bool, float> unityEvent;

			[NonSerialized]
			public bool wasHeld;

			[NonSerialized]
			public bool marginError;

			private RangeState currentState;

			private RangeState lastState;

			private float lastThresholdTime = -100000f;

			public bool IsFlexTrigger => triggerType == TriggerType.OnFlex;

			public bool IsReleaseTrigger => triggerType == TriggerType.OnRelease;

			public bool RequiresHeldItem
			{
				get
				{
					HandType handType = this.handType;
					return handType == HandType.HeldItemHand || handType == HandType.EquippedSide;
				}
			}

			public bool HasValidLink => linkIndex >= 0;

			public bool IsLinked
			{
				get
				{
					if (tryLink)
					{
						return linkIndex >= 0;
					}
					return false;
				}
			}

			private bool ShowMainProperties
			{
				get
				{
					if (IsLinked)
					{
						return IsFlexTrigger;
					}
					return true;
				}
			}

			private bool ShowFlexThreshold => ShowMainProperties;

			private bool ShowReleaseThreshold
			{
				get
				{
					if (!IsLinked || IsReleaseTrigger)
					{
						return !IsFlexTrigger;
					}
					return false;
				}
			}

			public void ProcessState(bool leftHand, float flexValue)
			{
				currentState = ((!(flexValue < releaseThreshold)) ? ((!(flexValue >= flexThreshold)) ? RangeState.Within : RangeState.Above) : RangeState.Below);
				if (ShowMainProperties && currentState != lastState && continuousProperties != null && continuousProperties.Count > 0)
				{
					float f = Mathf.InverseLerp(releaseThreshold, flexThreshold, flexValue);
					continuousProperties.ApplyAll(f);
				}
				if (currentState == RangeState.Above && lastState == RangeState.Below)
				{
					lastThresholdTime = Time.time;
					lastState = RangeState.Above;
					if (IsFlexTrigger)
					{
						unityEvent?.Invoke(leftHand, flexValue);
					}
				}
				else if (currentState == RangeState.Below && lastState == RangeState.Above)
				{
					lastThresholdTime = Time.time;
					lastState = RangeState.Below;
					if (IsReleaseTrigger)
					{
						unityEvent?.Invoke(leftHand, flexValue);
					}
				}
			}
		}

		public FlexEvent[] list;

		private VRRig myRig;

		private TransferrableObject myTransferrable;

		private IHeldItem myHeldItem;

		public bool TickRunning { get; set; }

		private bool TryLinkToNextEvent(int index)
		{
			if (index < list.Length - 1)
			{
				if (list[index].IsFlexTrigger && list[index + 1].IsReleaseTrigger)
				{
					list[index].linkIndex = index + 1;
					list[index + 1].linkIndex = index;
					return true;
				}
				list[index + 1].linkIndex = -1;
			}
			list[index].linkIndex = -1;
			return false;
		}

		private void Awake()
		{
			myRig = GetComponentInParent<VRRig>();
			myTransferrable = GetComponentInParent<TransferrableObject>();
			myHeldItem = GetComponentInParent<IHeldItem>();
			for (int i = 0; i < list.Length; i++)
			{
				FlexEvent flexEvent = list[i];
				if (GTExt.IsNull(myTransferrable) && flexEvent.RequiresHeldItem)
				{
					myTransferrable = GetComponentInParent<TransferrableObject>();
				}
				if (flexEvent.tryLink && TryLinkToNextEvent(i))
				{
					FlexEvent flexEvent2 = list[i + 1];
					flexEvent.releaseThreshold = flexEvent2.releaseThreshold;
					flexEvent2.flexThreshold = flexEvent.flexThreshold;
					flexEvent2.fingerType = flexEvent.fingerType;
					flexEvent2.handType = flexEvent.handType;
					flexEvent2.networked = flexEvent.networked;
					i++;
				}
			}
		}

		private void CalcFlex(bool disable)
		{
			float num2 = default(float);
			for (int i = 0; i < list.Length; i++)
			{
				FlexEvent flexEvent = list[i];
				if ((!flexEvent.networked && !myRig.isOfflineVRRig) || (flexEvent.RequiresHeldItem && GTExt.IsNull(myTransferrable) && myHeldItem == null) || (flexEvent.handType == FlexEvent.HandType.EquippedSide && GTExt.IsNull(myTransferrable)))
				{
					continue;
				}
				bool flag = false;
				bool flag2 = false;
				bool flag3 = false;
				switch (flexEvent.handType)
				{
				case FlexEvent.HandType.LeftHand:
					flag = true;
					break;
				case FlexEvent.HandType.RightHand:
					flag2 = true;
					break;
				case FlexEvent.HandType.HeldItemHand:
					if (!GTExt.IsNull(myTransferrable))
					{
						flag = myTransferrable.currentState == TransferrableObject.PositionState.InLeftHand;
						flag2 = myTransferrable.currentState == TransferrableObject.PositionState.InRightHand;
						flag3 = flag || flag2;
					}
					else if (myHeldItem != null)
					{
						flag = myHeldItem.InLeftHand();
						flag2 = !flag && myHeldItem.InHand();
						flag3 = flag || flag2;
					}
					break;
				case FlexEvent.HandType.EquippedSide:
					flag = (myTransferrable.storedZone & (BodyDockPositions.DropPositions.LeftArm | BodyDockPositions.DropPositions.LeftBack)) != 0;
					flag2 = (myTransferrable.storedZone & (BodyDockPositions.DropPositions.RightArm | BodyDockPositions.DropPositions.RightBack)) != 0;
					break;
				}
				if ((flag && flag2) || (!flag && !flag2 && !flexEvent.wasHeld))
				{
					continue;
				}
				float num;
				if (disable || (flexEvent.wasHeld && !flag3))
				{
					num = 0f;
				}
				else
				{
					FlexEvent.FingerType fingerType = flexEvent.fingerType;
					switch (fingerType)
					{
					case FlexEvent.FingerType.Thumb:
						num2 = (flag ? myRig.leftThumb.calcT : myRig.rightThumb.calcT);
						break;
					case FlexEvent.FingerType.Index:
						num2 = (flag ? myRig.leftIndex.calcT : myRig.rightIndex.calcT);
						break;
					case FlexEvent.FingerType.Middle:
						num2 = (flag ? myRig.leftMiddle.calcT : myRig.rightMiddle.calcT);
						break;
					case FlexEvent.FingerType.IndexAndMiddle:
						num2 = (flag ? Mathf.Min(myRig.leftIndex.calcT, myRig.leftMiddle.calcT) : Mathf.Min(myRig.rightIndex.calcT, myRig.rightMiddle.calcT));
						break;
					case FlexEvent.FingerType.IndexOrMiddle:
						num2 = (flag ? Mathf.Max(myRig.leftIndex.calcT, myRig.leftMiddle.calcT) : Mathf.Max(myRig.rightIndex.calcT, myRig.rightMiddle.calcT));
						break;
					default:
						global::<PrivateImplementationDetails>.ThrowSwitchExpressionException(fingerType);
						break;
					}
					num = num2;
				}
				float flexValue = num;
				flexEvent.ProcessState(flag, flexValue);
				flexEvent.wasHeld = flag3 && !disable;
				if (flexEvent.IsLinked)
				{
					FlexEvent obj = list[i + 1];
					obj.ProcessState(flag, flexValue);
					obj.wasHeld = flag3;
					i++;
				}
			}
		}

		public void OnEnable()
		{
			TickSystem<object>.AddTickCallback(this);
		}

		public void OnDisable()
		{
			TickSystem<object>.RemoveTickCallback(this);
			CalcFlex(disable: true);
		}

		public void Tick()
		{
			CalcFlex(disable: false);
		}
	}
	public class GlowBugsInJar : MonoBehaviour
	{
		[SerializeField]
		private TransferrableObject transferrableObject;

		[Space]
		[Tooltip("Time interval - every X seconds update the glow value")]
		[SerializeField]
		private float glowUpdateInterval = 2f;

		[Tooltip("step increment - increase the glow value one step for N amount")]
		[SerializeField]
		private float glowIncreaseStepAmount = 0.1f;

		[Tooltip("step decrement - decrease the glow value one step for N amount")]
		[SerializeField]
		private float glowDecreaseStepAmount = 0.2f;

		[Space]
		[SerializeField]
		private string shaderProperty = "_EmissionColor";

		[SerializeField]
		private Renderer[] renderers;

		private bool shakeStarted = true;

		private static int EmissionColor;

		private float currentGlowAmount;

		private float shakeTimer;

		private RubberDuckEvents _events;

		private CallLimiter callLimiter = new CallLimiter(10, 2f);

		private void OnEnable()
		{
			shakeStarted = false;
			UpdateGlow(0f);
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((transferrableObject.myOnlineRig != null) ? transferrableObject.myOnlineRig.creator : ((transferrableObject.myRig != null) ? (transferrableObject.myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : null));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnShakeEvent);
			}
		}

		private void OnDisable()
		{
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnShakeEvent);
				_events.Dispose();
				_events = null;
			}
		}

		private void OnShakeEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender != target)
			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnShakeEvent");
			if (!callLimiter.CheckCallTime(Time.time) || args == null || args.Length != 1)
			{
				return;
			}
			object obj = args[0];
			if (obj is bool)
			{
				if ((bool)obj)
				{
					ShakeStartLocal();
				}
				else
				{
					ShakeEndLocal();
				}
			}
		}

		public void HandleOnShakeStart()
		{
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(true);
			}
			ShakeStartLocal();
		}

		private void ShakeStartLocal()
		{
			currentGlowAmount = 0f;
			shakeStarted = true;
			shakeTimer = 0f;
		}

		public void HandleOnShakeEnd()
		{
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(false);
			}
			ShakeEndLocal();
		}

		private void ShakeEndLocal()
		{
			shakeStarted = false;
			shakeTimer = 0f;
		}

		public void Update()
		{
			if (shakeStarted)
			{
				shakeTimer += 1f;
				if (shakeTimer >= glowUpdateInterval && currentGlowAmount < 1f)
				{
					currentGlowAmount += glowIncreaseStepAmount;
					UpdateGlow(currentGlowAmount);
					shakeTimer = 0f;
				}
			}
			else
			{
				shakeTimer += 1f;
				if (shakeTimer >= glowUpdateInterval && currentGlowAmount > 0f)
				{
					currentGlowAmount -= glowDecreaseStepAmount;
					UpdateGlow(currentGlowAmount);
					shakeTimer = 0f;
				}
			}
		}

		private void UpdateGlow(float value)
		{
			if (renderers.Length != 0)
			{
				for (int i = 0; i < renderers.Length; i++)
				{
					Material material = renderers[i].material;
					Color color = material.GetColor(shaderProperty);
					color.a = value;
					material.SetColor(shaderProperty, color);
					material.EnableKeyword("_EMISSION");
				}
			}
		}
	}
	public class HandControlledCosmetic : MonoBehaviour, ITickSystemTick
	{
		public enum RotationControl
		{
			Angle,
			Translation
		}

		[SerializeField]
		private HandControlledSettingsSO activeSettings;

		[SerializeField]
		private HandControlledSettingsSO inactiveSettings;

		[SerializeField]
		private UnityEngine.Vector3 handPositionOffset;

		[SerializeField]
		private UnityEngine.Quaternion rightHandRotation;

		[SerializeField]
		private UnityEngine.Quaternion leftHandRotation;

		private UnityEngine.Quaternion handRotationOffset;

		[SerializeField]
		private BezierCurve controlIndicatorCurve;

		[SerializeField]
		private Transform debugRelativePositionTransform1;

		[SerializeField]
		private Transform debugRelativePositionTransform2;

		private VRRig myRig;

		private Transform controllingHand;

		private UnityEngine.Vector3 startHandRelativePosition;

		private UnityEngine.Vector3 lowAngleLimits;

		private UnityEngine.Vector3 highAngleLimits;

		private UnityEngine.Vector3 localEuler;

		private UnityEngine.Quaternion startHandInverseRotation;

		private UnityEngine.Quaternion initialRotation;

		private bool isActive;

		public bool TickRunning { get; set; }

		public void Awake()
		{
			myRig = GetComponentInParent<VRRig>();
			initialRotation = base.transform.localRotation;
			base.enabled = false;
			if (debugRelativePositionTransform1 != null)
			{
				UnityEngine.Object.Destroy(debugRelativePositionTransform1.gameObject);
			}
			if (debugRelativePositionTransform2 != null)
			{
				UnityEngine.Object.Destroy(debugRelativePositionTransform2.gameObject);
			}
		}

		private void SetControlIndicatorPoints()
		{
			if (myRig.isOfflineVRRig && controllingHand != null && controlIndicatorCurve != null && controlIndicatorCurve.points != null)
			{
				controlIndicatorCurve.points[0] = controllingHand.position;
				controlIndicatorCurve.points[1] = controlIndicatorCurve.points[0] + myRig.scaleFactor * controllingHand.up;
				controlIndicatorCurve.points[2] = base.transform.position;
			}
		}

		private UnityEngine.Vector3 GetRelativeHandPosition()
		{
			return controllingHand.TransformPoint(handPositionOffset) - myRig.bodyTransform.position;
		}

		public void StartControl(bool leftHand, float flexValue)
		{
			if (base.enabled && base.gameObject.activeInHierarchy)
			{
				lowAngleLimits = activeSettings.angleLimits;
				highAngleLimits = 360f * UnityEngine.Vector3.one - lowAngleLimits;
				handRotationOffset = (leftHand ? leftHandRotation : rightHandRotation);
				controllingHand = (leftHand ? myRig.leftHand.rigTarget.transform : myRig.rightHand.rigTarget.transform);
				startHandRelativePosition = GetRelativeHandPosition();
				startHandInverseRotation = UnityEngine.Quaternion.Inverse(controllingHand.rotation * handRotationOffset);
				isActive = true;
				SetControlIndicatorPoints();
				TickSystem<object>.AddTickCallback(this);
			}
		}

		public void StopControl()
		{
			localEuler = base.transform.localRotation.eulerAngles;
			isActive = false;
			SetControlIndicatorPoints();
		}

		public void OnEnable()
		{
		}

		public void OnDisable()
		{
			base.transform.localRotation = initialRotation;
			StopControl();
			TickSystem<object>.RemoveTickCallback(this);
		}

		private float ReverseClampDegrees(float value, float low, float high)
		{
			value = Mathf.Repeat(value, 360f);
			if (value <= low || value >= high)
			{
				return value;
			}
			if (!(value < 180f))
			{
				return high;
			}
			return low;
		}

		public void Tick()
		{
			if (isActive)
			{
				switch (activeSettings.rotationControl)
				{
				case RotationControl.Angle:
				{
					UnityEngine.Quaternion quaternion2 = controllingHand.rotation * handRotationOffset;
					UnityEngine.Quaternion quaternion3 = startHandInverseRotation * quaternion2;
					localEuler += activeSettings.inputSensitivity * quaternion3.eulerAngles;
					float t = 1f - Mathf.Exp((0f - activeSettings.inputDecaySpeed) * Time.deltaTime);
					startHandInverseRotation = UnityEngine.Quaternion.Slerp(startHandInverseRotation, UnityEngine.Quaternion.Inverse(quaternion2), t);
					break;
				}
				case RotationControl.Translation:
				{
					UnityEngine.Vector3 relativeHandPosition = GetRelativeHandPosition();
					float num = UnityEngine.Vector3.SignedAngle(to: new UnityEngine.Vector3(relativeHandPosition.x, 0f, relativeHandPosition.z), from: new UnityEngine.Vector3(startHandRelativePosition.x, 0f, startHandRelativePosition.z), axis: UnityEngine.Vector3.up);
					float num2 = 50f * (startHandRelativePosition.y - relativeHandPosition.y) / myRig.scaleFactor;
					float time = UnityEngine.Vector3.Distance(startHandRelativePosition, relativeHandPosition) / myRig.scaleFactor;
					localEuler += Time.deltaTime * new UnityEngine.Vector3(activeSettings.verticalSensitivity.Evaluate(time) * num2, activeSettings.horizontalSensitivity.Evaluate(time) * num, 0f);
					startHandRelativePosition = UnityEngine.Vector3.MoveTowards(startHandRelativePosition, relativeHandPosition, Time.deltaTime * activeSettings.inputDecayCurve.Evaluate(time));
					break;
				}
				}
				for (int i = 0; i < 3; i++)
				{
					localEuler[i] = ReverseClampDegrees(localEuler[i], lowAngleLimits[i], highAngleLimits[i]);
				}
				base.transform.localRotation = UnityEngine.Quaternion.Slerp(base.transform.localRotation, UnityEngine.Quaternion.Euler(localEuler), 1f - Mathf.Exp((0f - activeSettings.rotationSpeed) * Time.deltaTime));
			}
			else
			{
				UnityEngine.Quaternion localRotation = UnityEngine.Quaternion.Slerp(base.transform.localRotation, initialRotation, 1f - Mathf.Exp((0f - inactiveSettings.rotationSpeed) * Time.deltaTime));
				base.transform.localRotation = localRotation;
				localEuler = localRotation.eulerAngles;
			}
		}
	}
	public class HandControlledSettingsSO : ScriptableObject
	{
		private const string SENS_TT = "The difference between the current input and cached input is magnified by this number.";

		public HandControlledCosmetic.RotationControl rotationControl;

		[Tooltip("The difference between the current input and cached input is magnified by this number.")]
		public float inputSensitivity = 2f;

		[Tooltip("The difference between the current input and cached input is magnified by this number.")]
		public AnimationCurve verticalSensitivity = AnimationCurve.Constant(0f, 1f, 2f);

		[Tooltip("The difference between the current input and cached input is magnified by this number.")]
		public AnimationCurve horizontalSensitivity = AnimationCurve.Constant(0f, 1f, 2f);

		[Tooltip("How quickly the cached input approaches the current input. A high value will function more like a mouse, while a low value will function more like a joystick.")]
