			{
				return;
			}
			MonkeAgent.IncrementRPCCall(info, "OnShake");
			if (!callLimiter.CheckCallTime(Time.time) || args.Length != 1)
			{
				return;
			}
			object obj = args[0];
			if (obj is bool)
			{
				if ((bool)obj)
				{
					ShakeStartShared?.Invoke();
				}
				else
				{
					ShakeEndShared?.Invoke();
				}
			}
		}

		public void OnSpawn(VRRig rig)
		{
			myRig = rig;
		}

		public void OnDespawn()
		{
		}
	}
	public class SmoothScaleModifierCosmetic : MonoBehaviour
	{
		private enum State
		{
			None,
			Reset,
			Scaling,
			Scaled
		}

		[Tooltip("The GameObject to scale up or down. This should reference the cosmetic mesh or object you want to visually modify.")]
		[SerializeField]
		private GameObject objectPrefab;

		[Tooltip("The target scale applied when scaling is triggered.")]
		[SerializeField]
		private UnityEngine.Vector3 targetScale = new UnityEngine.Vector3(2f, 2f, 2f);

		[Tooltip("Speed at which the object scales toward its target or initial size")]
		[SerializeField]
		private float speed = 2f;

		[Tooltip("Invoked once when the object reaches the target scale.")]
		public UnityEvent onScaled;

		[Tooltip("Invoked once when the object returns to its initial scale.")]
		public UnityEvent onReset;

		private State currentState;

		private UnityEngine.Vector3 initialScale;

		private void Awake()
		{
			initialScale = objectPrefab.transform.localScale;
		}

		private void OnEnable()
		{
			UpdateState(State.Reset);
		}

		private void Update()
		{
			switch (currentState)
			{
			case State.Reset:
				SmoothScale(objectPrefab.transform.localScale, initialScale);
				if (UnityEngine.Vector3.Distance(objectPrefab.transform.localScale, initialScale) < 0.01f)
				{
					objectPrefab.transform.localScale = initialScale;
					if (onReset != null)
					{
						onReset.Invoke();
					}
					UpdateState(State.None);
				}
				break;
			case State.Scaling:
				SmoothScale(objectPrefab.transform.localScale, targetScale);
				if (UnityEngine.Vector3.Distance(objectPrefab.transform.localScale, targetScale) < 0.01f)
				{
					objectPrefab.transform.localScale = targetScale;
					if (onScaled != null)
					{
						onScaled.Invoke();
					}
					UpdateState(State.Scaled);
				}
				break;
			case State.None:
			case State.Scaled:
				break;
			}
		}

		private void SmoothScale(UnityEngine.Vector3 initial, UnityEngine.Vector3 target)
		{
			objectPrefab.transform.localScale = UnityEngine.Vector3.MoveTowards(initial, target, speed * Time.deltaTime);
		}

		private void UpdateState(State newState)
		{
			currentState = newState;
		}

		public void TriggerScale()
		{
			if (currentState != State.Scaled)
			{
				UpdateState(State.Scaling);
			}
		}

		public void TriggerReset()
		{
			if (currentState != State.Reset)
			{
				UpdateState(State.Reset);
			}
		}
	}
	public class SnakeInCanHoldable : TransferrableObject
	{
		[SerializeField]
		private float jumpSpeed;

		[SerializeField]
		private Transform stretchedPoint;

		[SerializeField]
		private Transform compressedPoint;

		[SerializeField]
		private GameObject topRigObject;

		[SerializeField]
		private GameObject disableObjectBeforeTrigger;

		private CallLimiter snakeInCanCallLimiter = new CallLimiter(10, 2f);

		private UnityEngine.Vector3 topRigPosition;

		private UnityEngine.Vector3 originalTopRigPosition;

		private RubberDuckEvents _events;

		protected override void Awake()
		{
			base.Awake();
			topRigPosition = topRigObject.transform.position;
		}

		internal override void OnEnable()
		{
			base.OnEnable();
			disableObjectBeforeTrigger.SetActive(value: false);
			if (compressedPoint != null)
			{
				topRigObject.transform.position = compressedPoint.position;
			}
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((base.myOnlineRig != null) ? base.myOnlineRig.creator : ((!(base.myRig != null)) ? null : ((base.myRig.creator != null) ? base.myRig.creator : NetworkSystem.Instance.LocalPlayer)));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnEnableObject);
			}
		}

		internal override void OnDisable()
		{
			base.OnDisable();
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnEnableObject);
				_events.Dispose();
				_events = null;
			}
		}

		public override bool OnRelease(DropZone zoneReleased, GameObject releasingHand)
		{
			if (!base.OnRelease(zoneReleased, releasingHand))
			{
				return false;
			}
			if (VRRigCache.Instance.localRig.Rig != ownerRig)
			{
				return false;
			}
			if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
			{
				_events.Activate.RaiseOthers(false);
			}
			EnableObjectLocal(enable: false);
			return true;
		}

		private void OnEnableObject(int sender, int target, object[] arg, PhotonMessageInfoWrapped info)
		{
			if (info.senderID == ownerRig.creator.ActorNumber && arg.Length == 1 && arg[0] is bool && sender == target)
			{
				MonkeAgent.IncrementRPCCall(info, "OnEnableObject");
				if (snakeInCanCallLimiter.CheckCallTime(Time.time))
				{
					bool enable = (bool)arg[0];
					EnableObjectLocal(enable);
				}
			}
		}

		private void EnableObjectLocal(bool enable)
		{
			disableObjectBeforeTrigger.SetActive(enable);
			if (enable)
			{
				if (stretchedPoint != null)
				{
					StartCoroutine(SmoothTransition());
				}
				else
				{
					topRigObject.transform.position = topRigPosition;
				}
			}
			else if (compressedPoint != null)
			{
				topRigObject.transform.position = compressedPoint.position;
			}
		}

		private IEnumerator SmoothTransition()
		{
			while (UnityEngine.Vector3.Distance(topRigObject.transform.position, stretchedPoint.position) > 0.01f)
			{
				topRigObject.transform.position = UnityEngine.Vector3.MoveTowards(topRigObject.transform.position, stretchedPoint.position, jumpSpeed * Time.deltaTime);
				yield return null;
			}
			topRigObject.transform.position = stretchedPoint.position;
		}

		public void OnButtonPressed()
		{
			EnableObjectLocal(enable: true);
		}
	}
