	public class UpdateBlendShapeCosmetic : MonoBehaviour
	{
		[Tooltip("The SkinnedMeshRenderer whose BlendShape weight will be updated. This must reference a mesh that has BlendShapes defined in its import settings.")]
		[SerializeField]
		private SkinnedMeshRenderer skinnedMeshRenderer;

		[Tooltip("Maximum blend shape weight applied when fully blended. Usually 100 for standard Unity BlendShapes.")]
		public float maxBlendShapeWeight = 100f;

		[Tooltip("Index of the BlendShape to control. You can find this index in the SkinnedMeshRenderer inspector under 'BlendShapes'.")]
		[SerializeField]
		private int blendShapeIndex;

		[Tooltip("Speed at which the BlendShape transitions toward its target weight. Higher values make blending more responsive, lower values make it smoother.")]
		[SerializeField]
		private float blendSpeed = 10f;

		[Tooltip("Initial BlendShape weight set when the component awakens. Useful for setting a default deformation state.")]
		[SerializeField]
		private float blendStartWeight;

		[Tooltip("If enabled, inverts the incoming blend value (e.g. 0  1, 0.2  0.8). Useful when an input should drive the opposite direction of deformation.")]
		[SerializeField]
		private bool invertPassedBlend;

		private float targetWeight;

		private float currentWeight;

		private void Awake()
		{
			targetWeight = blendStartWeight;
			currentWeight = 0f;
		}

		private void Update()
		{
			currentWeight = Mathf.Lerp(currentWeight, targetWeight, Time.deltaTime * blendSpeed);
			skinnedMeshRenderer.SetBlendShapeWeight(blendShapeIndex, currentWeight);
		}

		public void SetBlendValue(bool leftHand, float value)
		{
			targetWeight = Mathf.Clamp01(invertPassedBlend ? (1f - value) : value) * maxBlendShapeWeight;
		}

		public void SetBlendValue(float value)
		{
			targetWeight = Mathf.Clamp01(invertPassedBlend ? (1f - value) : value) * maxBlendShapeWeight;
		}

		public void FullyBlend()
		{
			targetWeight = maxBlendShapeWeight;
		}

		public void ResetBlend()
		{
			targetWeight = 0f;
		}

		public float GetBlendValue()
		{
			return skinnedMeshRenderer.GetBlendShapeWeight(blendShapeIndex);
		}
	}
	public class VelocityBasedAudioTriggerCosmetic : MonoBehaviour
	{
		[SerializeField]
		private GorillaVelocityTracker velocityTracker;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private AudioClip audioClip;

		[SerializeField]
		private SoundBankPlayer soundBank;

		[Tooltip(" Minimum velocity to trigger audio")]
		[SerializeField]
		private float minVelocityThreshold = 0.5f;

		[SerializeField]
		private float maxVelocity = 2f;

		[SerializeField]
		private float minOutputVolume;

		[SerializeField]
		private float maxOutputVolume = 1f;

		private void Awake()
		{
			if (audioClip != null)
			{
				audioSource.clip = audioClip;
			}
			if (soundBank != null && audioSource != null)
			{
				soundBank.audioSource = audioSource;
			}
		}

		private void Update()
		{
			UnityEngine.Vector3 averageVelocity = velocityTracker.GetAverageVelocity(worldSpace: true);
			if (averageVelocity.magnitude < minVelocityThreshold)
			{
				return;
			}
			float t = Mathf.InverseLerp(minVelocityThreshold, maxVelocity, averageVelocity.magnitude);
			float num = Mathf.Lerp(minOutputVolume, maxOutputVolume, t);
			audioSource.volume = num;
			if (audioSource != null && !audioSource.isPlaying && audioClip != null)
			{
				audioSource.clip = audioClip;
				if (audioSource.isActiveAndEnabled)
				{
					audioSource.GTPlay();
				}
			}
			else if (soundBank != null && soundBank.soundBank != null && !soundBank.isPlaying)
			{
				soundBank.Play(num);
			}
		}
	}
	[RequireComponent(typeof(TransferrableObject))]
	public class VenusFlyTrapHoldable : MonoBehaviour, ITickSystemTick
	{
		private enum VenusState
		{
			Closed,
			Open,
			Closing,
			Opening
		}

		[SerializeField]
		private GameObject lipA;

		[SerializeField]
		private GameObject lipB;

		[SerializeField]
		private UnityEngine.Vector3 targetRotationA;

		[SerializeField]
		private UnityEngine.Vector3 targetRotationB;

		[SerializeField]
		private float closedDuration = 3f;

		[SerializeField]
		private float speed = 2f;

		[SerializeField]
		private UnityLayer layers;

		[SerializeField]
		private TriggerEventNotifier triggerEventNotifier;

		[SerializeField]
		private float hapticStrength = 0.5f;

		[SerializeField]
		private float hapticDuration = 0.1f;

		[SerializeField]
		private GameObject bug;

		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private AudioClip closingAudio;

		[SerializeField]
		private AudioClip openingAudio;

		[SerializeField]
		private AudioClip flyLoopingAudio;

		private CallLimiter callLimiter = new CallLimiter(10, 2f);

		private float closedStartedTime;

		private VenusState state;

		private UnityEngine.Quaternion localRotA;

		private UnityEngine.Quaternion localRotB;

		private RubberDuckEvents _events;

		private TransferrableObject transferrableObject;

		public bool TickRunning { get; set; }

		private void Awake()
		{
			transferrableObject = GetComponent<TransferrableObject>();
		}

		private void OnEnable()
		{
			TickSystem<object>.AddCallbackTarget(this);
			triggerEventNotifier.TriggerEnterEvent += TriggerEntered;
			state = VenusState.Open;
			localRotA = lipA.transform.localRotation;
			localRotB = lipB.transform.localRotation;
			if (_events == null)
			{
				_events = base.gameObject.GetOrAddComponent<RubberDuckEvents>();
				NetPlayer netPlayer = ((transferrableObject.myOnlineRig != null) ? transferrableObject.myOnlineRig.creator : ((transferrableObject.myRig != null) ? (transferrableObject.myRig.creator ?? NetworkSystem.Instance.LocalPlayer) : null));
				if (netPlayer != null)
				{
					_events.Init(netPlayer);
				}
			}
			if (_events != null)
			{
				_events.Activate += new Action<int, int, object[], PhotonMessageInfoWrapped>(OnTriggerEvent);
			}
		}

		private void OnDisable()
		{
			TickSystem<object>.RemoveCallbackTarget(this);
			triggerEventNotifier.TriggerEnterEvent -= TriggerEntered;
			if (_events != null)
			{
				_events.Activate -= new Action<int, int, object[], PhotonMessageInfoWrapped>(OnTriggerEvent);
				_events.Dispose();
				_events = null;
			}
		}

		public void Tick()
		{
			if (transferrableObject.InHand() && (bool)audioSource && !audioSource.isPlaying && flyLoopingAudio != null)
			{
				audioSource.clip = flyLoopingAudio;
				audioSource.GTPlay();
			}
			if (!transferrableObject.InHand() && (bool)audioSource && audioSource.isPlaying)
			{
				audioSource.GTStop();
			}
			if (state == VenusState.Open)
			{
				return;
			}
			if (state == VenusState.Closed && Time.time - closedStartedTime >= closedDuration)
			{
				UpdateState(VenusState.Opening);
				if ((bool)audioSource && openingAudio != null)
				{
					audioSource.GTPlayOneShot(openingAudio);
				}
			}
			if (state == VenusState.Closing)
			{
				SmoothRotation(isClosing: true);
			}
			else if (state == VenusState.Opening)
			{
				SmoothRotation(isClosing: false);
			}
		}

		private void SmoothRotation(bool isClosing)
		{
			if (isClosing)
			{
				UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.Euler(targetRotationB);
				lipB.transform.localRotation = UnityEngine.Quaternion.Lerp(lipB.transform.localRotation, quaternion2, Time.deltaTime * speed);
				UnityEngine.Quaternion quaternion3 = UnityEngine.Quaternion.Euler(targetRotationA);
				lipA.transform.localRotation = UnityEngine.Quaternion.Lerp(lipA.transform.localRotation, quaternion3, Time.deltaTime * speed);
				if (UnityEngine.Quaternion.Angle(lipB.transform.localRotation, quaternion2) < 1f && UnityEngine.Quaternion.Angle(lipA.transform.localRotation, quaternion3) < 1f)
				{
					lipB.transform.localRotation = quaternion2;
					lipA.transform.localRotation = quaternion3;
					UpdateState(VenusState.Closed);
				}
			}
			else
			{
				lipB.transform.localRotation = UnityEngine.Quaternion.Lerp(lipB.transform.localRotation, localRotB, Time.deltaTime * speed / 2f);
				lipA.transform.localRotation = UnityEngine.Quaternion.Lerp(lipA.transform.localRotation, localRotA, Time.deltaTime * speed / 2f);
				if (UnityEngine.Quaternion.Angle(lipB.transform.localRotation, localRotB) < 1f && UnityEngine.Quaternion.Angle(lipA.transform.localRotation, localRotA) < 1f)
				{
					lipB.transform.localRotation = localRotB;
					lipA.transform.localRotation = localRotA;
					UpdateState(VenusState.Open);
				}
			}
		}

		private void UpdateState(VenusState newState)
		{
			state = newState;
			if (state == VenusState.Closed)
			{
				closedStartedTime = Time.time;
			}
		}

		private void TriggerEntered(TriggerEventNotifier notifier, Collider other)
		{
			if (state == VenusState.Open && other.gameObject.IsOnLayer(layers))
			{
				if (PhotonNetwork.InRoom && _events != null && _events.Activate != null)
				{
					_events.Activate.RaiseOthers();
				}
				OnTriggerLocal();
				GorillaTriggerColliderHandIndicator componentInChildren = other.GetComponentInChildren<GorillaTriggerColliderHandIndicator>();
				if (!(componentInChildren == null))
				{
					GorillaTagger.Instance.StartVibration(componentInChildren.isLeftHand, hapticStrength, hapticDuration);
				}
			}
		}

		private void OnTriggerEvent(int sender, int target, object[] args, PhotonMessageInfoWrapped info)
		{
			if (sender == target)
			{
				MonkeAgent.IncrementRPCCall(info, "OnTriggerEvent");
				if (callLimiter.CheckCallTime(Time.time))
				{
					OnTriggerLocal();
				}
			}
		}

		private void OnTriggerLocal()
		{
			UpdateState(VenusState.Closing);
			if ((bool)audioSource && closingAudio != null)
			{
				audioSource.GTPlayOneShot(closingAudio);
			}
		}
	}
	public enum TalkingCosmeticType
	{
		RobotSkull,
		CreepyDoll,
		MicrophoneGNN,
		MicrophoneGC,
