	}
	[RequireComponent(typeof(LoudSpeakerActivator))]
	public class VoiceBroadcastCosmetic : MonoBehaviour, IGorillaSliceableSimple
	{
		public TalkingCosmeticType talkingCosmeticType;

		[Tooltip("How loud the Gorilla voice should be before detecting as talking.")]
		[SerializeField]
		public float minVolume = 0.1f;

		[Tooltip("How long the initial speaking section needs to last to trigger the talking animation.")]
		[SerializeField]
		public float minSpeakingTime = 0.15f;

		[SerializeField]
		private Animation simpleAnimation;

		[SerializeField]
		private string talkAnimationTriggerName;

		private int talkAnimationTrigger;

		private const string EVENTS = "Events";

		[SerializeField]
		private UnityEvent onStartListening;

		[SerializeField]
		private UnityEvent onStartSpeaking;

		[SerializeField]
		private UnityEvent onStopSpeaking;

		[SerializeField]
		private UnityEvent onStopListening;

		private float speakingTime;

		private bool isListening;

		private bool isSpeaking;

		private VoiceBroadcastCosmeticWearable wearable;

		private LoudSpeakerActivator loudSpeaker;

		private GorillaSpeakerLoudness gsl;

		private Animator animator;

		private float lastSliceUpdateTime;

		private void Awake()
		{
			loudSpeaker = GetComponent<LoudSpeakerActivator>();
			animator = GetComponent<Animator>();
			talkAnimationTrigger = Animator.StringToHash(talkAnimationTriggerName);
			gsl = GetComponentInParent<GorillaSpeakerLoudness>();
		}

		public void SetWearable(VoiceBroadcastCosmeticWearable wearable)
		{
			this.wearable = wearable;
		}

		private void StartBroadcast()
		{
			loudSpeaker.StartLocalBroadcast();
			onStartListening?.Invoke();
			onStartListening?.Invoke();
			wearable.OnCosmeticStartListening();
			lastSliceUpdateTime = Time.time;
			GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
		}

		private void StopBroadcast()
		{
			loudSpeaker.StopLocalBroadcast();
			onStopListening?.Invoke();
			wearable.OnCosmeticStopListening();
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
		}

		public void OnEnable()
		{
			isListening = false;
			speakingTime = 0f;
		}

		public void OnDisable()
		{
			isListening = false;
			speakingTime = 0f;
			StopBroadcast();
		}

		public void SetListenState(bool listening)
		{
			if (isListening != listening && base.enabled && base.gameObject.activeInHierarchy)
			{
				isListening = listening;
				speakingTime = 0f;
				if (listening)
				{
					StartBroadcast();
				}
				else
				{
					StopBroadcast();
				}
			}
		}

		public void SliceUpdate()
		{
			float num = Time.time - lastSliceUpdateTime;
			lastSliceUpdateTime = Time.time;
			if (gsl != null && gsl.IsSpeaking && gsl.LoudnessNormalized >= minVolume)
			{
				speakingTime += num;
				if (speakingTime >= minSpeakingTime)
				{
					if (animator != null)
					{
						animator.SetTrigger(talkAnimationTrigger);
					}
					if (simpleAnimation != null && !simpleAnimation.isPlaying)
					{
						simpleAnimation.Play();
					}
					if (!isSpeaking)
					{
						onStartSpeaking?.Invoke();
						isSpeaking = true;
					}
				}
			}
			else
			{
				speakingTime = 0f;
				if (isSpeaking)
				{
					onStopSpeaking?.Invoke();
					isSpeaking = false;
				}
			}
		}

		private void ResetToFirstFrame()
		{
			simpleAnimation.Rewind();
			simpleAnimation.Play();
			simpleAnimation.Sample();
			simpleAnimation.Stop();
		}
	}
	public class VoiceBroadcastCosmeticWearable : MonoBehaviour, IGorillaSliceableSimple
	{
		public TalkingCosmeticType talkingCosmeticType;

		[SerializeField]
		private bool headDistanceActivation = true;

		[SerializeField]
		private float headDistance = 0.4f;

		[SerializeField]
		private float toggleCooldown = 0.5f;

		private bool toggleState;

		private float lastToggleTime;

		[SerializeField]
		private UnityEvent onStartListening;

		[SerializeField]
		private UnityEvent onStopListening;

		private List<VoiceBroadcastCosmetic> voiceBroadcasters;

		private Collider playerHeadCollider;

		private void Start()
		{
			VoiceBroadcastCosmetic[] componentsInChildren = GetComponentInParent<VRRig>().GetComponentsInChildren<VoiceBroadcastCosmetic>(includeInactive: true);
			voiceBroadcasters = new List<VoiceBroadcastCosmetic>();
			VoiceBroadcastCosmetic[] array = componentsInChildren;
			foreach (VoiceBroadcastCosmetic voiceBroadcastCosmetic in array)
			{
				if (voiceBroadcastCosmetic.talkingCosmeticType == talkingCosmeticType)
				{
					voiceBroadcasters.Add(voiceBroadcastCosmetic);
					voiceBroadcastCosmetic.SetWearable(this);
				}
			}
		}

		public void OnEnable()
		{
			if (playerHeadCollider == null)
			{
				playerHeadCollider = GetComponentInParent<VRRig>()?.rigContainer.HeadCollider;
			}
			if (headDistanceActivation && playerHeadCollider != null)
			{
				GorillaSlicerSimpleManager.RegisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
			}
		}

		public void OnDisable()
		{
			GorillaSlicerSimpleManager.UnregisterSliceable(this, GorillaSlicerSimpleManager.UpdateStep.LateUpdate);
		}

		public void SliceUpdate()
		{
			if (!(Time.time - lastToggleTime >= toggleCooldown))
			{
				return;
			}
			bool flag = (base.transform.position - playerHeadCollider.transform.position).sqrMagnitude <= headDistance * headDistance;
			if (flag != toggleState)
			{
				toggleState = flag;
				lastToggleTime = Time.time;
				if (flag)
				{
					onStartListening?.Invoke();
				}
				else
				{
					onStopListening?.Invoke();
				}
				for (int i = 0; i < voiceBroadcasters.Count; i++)
				{
					voiceBroadcasters[i].SetListenState(flag);
				}
			}
		}

		public void OnCosmeticStartListening()
		{
			if (!headDistanceActivation)
			{
				onStartListening?.Invoke();
			}
		}

		public void OnCosmeticStopListening()
		{
			if (!headDistanceActivation)
			{
				onStopListening?.Invoke();
			}
		}
	}
	public class WormInApple : MonoBehaviour
