	[RequireComponent(typeof(Collider))]
	public class CosmeticSwipeReactor : MonoBehaviour, ITickSystemTick
	{
		public enum Axis
		{
			X,
			Y,
			Z
		}

		[SerializeField]
		private Axis localSwipeAxis = Axis.Y;

		private UnityEngine.Vector3 swipeDir = UnityEngine.Vector3.up;

		[Tooltip("Distance hand can move perpindicular to the swipe without cancelling the gesture")]
		[SerializeField]
		private float lateralMovementTolerance = 0.1f;

		[Tooltip("How far the hand has to move along the axis to count as a swipe\nThis distance must be contained within the trigger area")]
		[SerializeField]
		private float swipeDistance = 0.3f;

		[SerializeField]
		private float minimumVelocity = 0.1f;

		[SerializeField]
		private float maximumVelocity = 3f;

		[Tooltip("Delay after completing a swipe before starting the next")]
		[SerializeField]
		private float swipeCooldown = 0.25f;

		[SerializeField]
		private bool resetCooldownOnTriggerExit = true;

		[Tooltip("Amplitude of haptics from normalized swiped distance")]
		[SerializeField]
		private AnimationCurve swipeHaptics = AnimationCurve.EaseInOut(0f, 0.02f, 1f, 0.5f);

		public UnityEvent<bool> OnSwipe;

		public UnityEvent<bool> OnReverseSwipe;

		private VRRig _rig;

		private Collider col;

		private bool isLocal;

		private bool handInTriggerR;

		private bool handInTriggerL;

		private GorillaTriggerColliderHandIndicator handIndicatorR;

		private GorillaTriggerColliderHandIndicator handIndicatorL;

		private UnityEngine.Vector3 startPosR;

		private UnityEngine.Vector3 startPosL;

		private UnityEngine.Vector3 lastFramePosR;

		private UnityEngine.Vector3 lastFramePosL;

		private float distanceR;

		private float distanceL;

		private bool swipingUpL;

		private bool swipingUpR;

		private double cooldownEndL = double.MinValue;

		private double cooldownEndR = double.MinValue;

		private bool isCoolingDownL;

		private bool isCoolingDownR;

		public bool TickRunning { get; set; }

		private void Awake()
		{
			_rig = GetComponentInParent<VRRig>();
			if (_rig == null && base.gameObject.GetComponentInParent<GTPlayer>() != null)
			{
				_rig = GorillaTagger.Instance.offlineVRRig;
			}
			isLocal = _rig != null && _rig.isLocal;
			col = GetComponent<Collider>();
			switch (localSwipeAxis)
			{
			case Axis.X:
				swipeDir = UnityEngine.Vector3.right;
				break;
			case Axis.Y:
				swipeDir = UnityEngine.Vector3.up;
				break;
			case Axis.Z:
				swipeDir = UnityEngine.Vector3.forward;
				break;
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			if (!isLocal || !base.enabled)
			{
				return;
			}
			GorillaTriggerColliderHandIndicator component = other.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (component != null)
			{
				if (component.isLeftHand)
				{
					handIndicatorL = component;
					UnityEngine.Vector3 pos = base.transform.InverseTransformPoint(component.transform.position);
					ResetProgress(left: true, pos);
					handInTriggerL = true;
				}
				else
				{
					handIndicatorR = component;
					UnityEngine.Vector3 pos2 = base.transform.InverseTransformPoint(component.transform.position);
					ResetProgress(left: false, pos2);
					handInTriggerR = true;
				}
			}
			if ((handInTriggerL || handInTriggerR) && !TickRunning)
			{
				TickSystem<object>.AddTickCallback(this);
			}
		}

		private void OnTriggerExit(Collider other)
		{
			if (!isLocal || !base.enabled)
			{
				return;
			}
			GorillaTriggerColliderHandIndicator component = other.GetComponent<GorillaTriggerColliderHandIndicator>();
			if (component != null)
			{
				if (component.isLeftHand)
				{
					handInTriggerL = false;
					if (resetCooldownOnTriggerExit)
					{
						isCoolingDownL = false;
						cooldownEndL = double.MinValue;
					}
				}
				else
				{
					handInTriggerR = false;
					if (resetCooldownOnTriggerExit)
					{
						isCoolingDownR = false;
						cooldownEndR = double.MinValue;
					}
				}
			}
			if (!handInTriggerL && !handInTriggerR && TickRunning)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
		}

		public void Tick()
		{
			if (handInTriggerL)
			{
				ProcessHandMovement(handIndicatorL, startPosL, ref lastFramePosL, ref swipingUpL, ref distanceL, ref isCoolingDownL, ref cooldownEndL);
			}
			if (handInTriggerR)
			{
				ProcessHandMovement(handIndicatorR, startPosR, ref lastFramePosR, ref swipingUpR, ref distanceR, ref isCoolingDownR, ref cooldownEndR);
			}
			if (!handInTriggerL && !handInTriggerR && TickRunning)
			{
				TickSystem<object>.RemoveTickCallback(this);
			}
		}

		private void ResetProgress(bool left, UnityEngine.Vector3 pos)
		{
			if (left)
			{
				startPosL = pos;
				lastFramePosL = startPosL;
				distanceL = 0f;
			}
			else
			{
				startPosR = pos;
				lastFramePosR = startPosR;
				distanceR = 0f;
			}
		}

		private void ProcessHandMovement(GorillaTriggerColliderHandIndicator hand, UnityEngine.Vector3 start, ref UnityEngine.Vector3 last, ref bool swipingUp, ref float dist, ref bool isCoolingDown, ref double cooldownEndTime)
		{
			if (isCoolingDown)
			{
				if (!(Time.timeAsDouble < cooldownEndTime))
				{
					isCoolingDown = false;
					cooldownEndTime = double.MinValue;
					ResetProgress(hand.isLeftHand, base.transform.InverseTransformPoint(hand.transform.position));
				}
				return;
			}
			UnityEngine.Vector3 vector = base.transform.InverseTransformPoint(hand.transform.position);
			float num = Mathf.Abs(GetAxisComponent(hand.currentVelocity));
			if (num < minimumVelocity * _rig.scaleFactor || num > maximumVelocity * _rig.scaleFactor)
			{
				ResetProgress(hand.isLeftHand, vector);
				return;
			}
			float num2 = GetAxisComponent(vector) - GetAxisComponent(last);
			if (num2 >= 0f && !swipingUp)
			{
				swipingUp = true;
				ResetProgress(hand.isLeftHand, vector);
				return;
			}
			if ((num2 < 0f) & swipingUp)
			{
				swipingUp = false;
				ResetProgress(hand.isLeftHand, vector);
				return;
			}
			if ((GetLateralMovement(start) - GetLateralMovement(vector)).sqrMagnitude > lateralMovementTolerance * lateralMovementTolerance)
			{
				ResetProgress(hand.isLeftHand, vector);
				return;
			}
			last = vector;
			dist += Mathf.Abs(num2);
			GorillaTagger.Instance.StartVibration(hand.isLeftHand, swipeHaptics.Evaluate(dist / swipeDistance), Time.deltaTime);
			if (dist >= swipeDistance)
			{
				if (swipingUp)
				{
					OnSwipe?.Invoke(hand.isLeftHand);
					cooldownEndTime = Time.timeAsDouble + (double)swipeCooldown;
					isCoolingDown = true;
				}
				else
				{
					OnReverseSwipe?.Invoke(hand.isLeftHand);
					cooldownEndTime = Time.timeAsDouble + (double)swipeCooldown;
					isCoolingDown = true;
				}
				ResetProgress(hand.isLeftHand, vector);
			}
		}

		private float GetAxisComponent(UnityEngine.Vector3 vec)
		{
			return localSwipeAxis switch
			{
				Axis.X => vec.x, 
				Axis.Y => vec.y, 
				_ => vec.z, 
			};
		}

		private UnityEngine.Vector2 GetLateralMovement(UnityEngine.Vector3 vec)
		{
			return localSwipeAxis switch
			{
				Axis.X => new UnityEngine.Vector2(vec.y, vec.z), 
				Axis.Y => new UnityEngine.Vector2(vec.x, vec.z), 
				_ => new UnityEngine.Vector2(vec.x, vec.y), 
			};
		}
	}
	public class SimpleTransformAnimatorCosmetic : MonoBehaviour, ITickSystemTick
	{
		public enum animatedPropertyChoices
		{
			Position,
			Rotation,
			PositionAndRotation
		}

		public enum animModes
		{
			stepToTargetPos,
			animateBounce,
			animateOneshot
		}

		private animModes animMode;

		[Tooltip("Shapes how the transform will interpolate over the course of the animation.")]
		public AnimationCurve InterpolationCurve = AnimationCurve.Linear(0f, 0f, 1f, 1f);

		[SerializeField]
		[Tooltip("The object that will animate (blend) between the poses.")]
		private Transform targetTransform;

		[SerializeField]
		[Tooltip("Start pose (blend value 0).")]
		private Transform poseA;

		[SerializeField]
		[Tooltip("End pose (blend value 1).")]
		private Transform poseB;

		[FormerlySerializedAs("transitionTime")]
		[SerializeField]
		[Tooltip("Total time (in seconds) to animate fully between poses.")]
		private float animationDuration = 1f;

		[SerializeField]
		[Tooltip("Controls what aspect of the transform is affected by the blend.")]
		private animatedPropertyChoices animatedProperties = animatedPropertyChoices.PositionAndRotation;

		private bool loopAnim;

		private float posBlendCurrent;

		private float posBlendTarget;

		private bool isAnimating;

		public bool TickRunning { get; set; }

		private void DebugToggle()
		{
			Toggle();
		}

		private void DebugA()
		{
			TogglePoseA();
		}

		private void DebugB()
		{
			TogglePoseB();
		}

		private void OnEnable()
		{
			posBlendCurrent = posBlendTarget;
			UpdateTransform();
		}

		private void OnDisable()
		{
			if (TickRunning)
			{
				TickSystem<object>.RemoveCallbackTarget(this);
				TickRunning = false;
			}
		}

		private void CheckAnimationNeeded()
		{
			bool flag = false;
			bool flag2 = Mathf.Approximately(posBlendCurrent, posBlendTarget);
			switch (animMode)
			{
			case animModes.stepToTargetPos:
				flag = !flag2;
				break;
			case animModes.animateOneshot:
				flag = loopAnim || !flag2;
				break;
			}
			if (flag && !TickRunning)
			{
				TickSystem<object>.AddCallbackTarget(this);
				TickRunning = true;
				isAnimating = true;
			}
			else if (!flag && TickRunning)
			{
				TickSystem<object>.RemoveCallbackTarget(this);
				TickRunning = false;
				isAnimating = false;
			}
		}

		public void Tick()
		{
			float num = 1f / animationDuration;
			posBlendCurrent = Mathf.MoveTowards(posBlendCurrent, posBlendTarget, Time.deltaTime * num);
			switch (animMode)
			{
			}
			UpdateTransform();
			CheckAnimationNeeded();
		}

		private void UpdateTransform()
		{
			UnityEngine.Vector3 position = targetTransform.position;
			UnityEngine.Quaternion rotation = targetTransform.rotation;
			float t = InterpolationCurve.Evaluate(posBlendCurrent);
			if (animatedProperties == animatedPropertyChoices.Position || animatedProperties == animatedPropertyChoices.PositionAndRotation)
			{
				position = UnityEngine.Vector3.Lerp(poseA.position, poseB.position, t);
			}
			if (animatedProperties == animatedPropertyChoices.Rotation || animatedProperties == animatedPropertyChoices.PositionAndRotation)
			{
				rotation = UnityEngine.Quaternion.Slerp(poseA.rotation, poseB.rotation, t);
			}
			targetTransform.SetPositionAndRotation(position, rotation);
		}

		public void Toggle()
		{
			animMode = animModes.stepToTargetPos;
			posBlendTarget = ((posBlendTarget < 0.5f) ? 1f : 0f);
			CheckAnimationNeeded();
		}

		public void TogglePoseA()
		{
			animMode = animModes.stepToTargetPos;
			posBlendTarget = 0f;
			CheckAnimationNeeded();
		}

		public void TogglePoseB()
		{
			animMode = animModes.stepToTargetPos;
			posBlendTarget = 1f;
			CheckAnimationNeeded();
		}

		public void playAnimationOneshot()
		{
			animMode = animModes.animateOneshot;
			posBlendCurrent = 0f;
			posBlendTarget = 1f;
			CheckAnimationNeeded();
		}

		private void DebugPlayAnimationOneShot()
		{
			playAnimationOneshot();
		}
	}
}
namespace GorillaTag.Cosmetics.Summer
{
	public class Projectile : MonoBehaviour, IProjectile
	{
		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private GameObject impactEffect;

		[SerializeField]
		private AudioClip launchAudio;

		[SerializeField]
		private LayerMask collisionLayerMasks;

		[SerializeField]
		private List<string> collisionTags = new List<string>();

		[SerializeField]
		private bool destroyOnCollisionEnter;

		[SerializeField]
		private float destroyDelay = 1f;

		[Tooltip("Distance from the surface that the particle should spawn.")]
		[SerializeField]
		private float impactEffectOffset = 0.1f;

		[SerializeField]
		private SpawnWorldEffects spawnWorldEffects;

		private ConstantForce forceComponent;

		public UnityEvent<float> onLaunchShared;

		public UnityEvent onImpactShared;

		private bool impactEffectSpawned;

		private Rigidbody rigidbody;

		protected void Awake()
		{
			rigidbody = GetComponent<Rigidbody>();
			impactEffectSpawned = false;
			forceComponent = GetComponent<ConstantForce>();
		}

		protected void OnEnable()
		{
		}

		public void Launch(UnityEngine.Vector3 startPosition, UnityEngine.Quaternion startRotation, UnityEngine.Vector3 velocity, float chargeFrac, VRRig ownerRig, int progressStep)
		{
			Transform obj = base.transform;
			obj.SetPositionAndRotation(startPosition, startRotation);
			obj.localScale = UnityEngine.Vector3.one * ownerRig.scaleFactor;
			if (rigidbody != null)
			{
				rigidbody.isKinematic = false;
				rigidbody.position = startPosition;
				rigidbody.rotation = startRotation;
				rigidbody.linearVelocity = velocity;
			}
			if ((bool)audioSource && (bool)launchAudio)
			{
				audioSource.GTPlayOneShot(launchAudio);
			}
			onLaunchShared?.Invoke(chargeFrac);
		}

		private bool IsTagValid(GameObject obj)
		{
			return collisionTags.Contains(obj.tag);
		}

		private void HandleImpact(GameObject hitObject, UnityEngine.Vector3 hitPosition, UnityEngine.Vector3 hitNormal)
		{
			if (impactEffectSpawned || (collisionTags.Count > 0 && !IsTagValid(hitObject)) || ((1 << hitObject.layer) & (int)collisionLayerMasks) == 0)
			{
				return;
			}
			SpawnImpactEffect(impactEffect, hitPosition, hitNormal);
			if (impactEffect != null)
			{
				SoundBankPlayer component = impactEffect.GetComponent<SoundBankPlayer>();
				if (component != null && !component.playOnEnable)
				{
					component.Play();
				}
			}
			impactEffectSpawned = true;
			if (destroyOnCollisionEnter)
			{
				if (destroyDelay > 0f)
				{
					Invoke("DestroyProjectile", destroyDelay);
				}
				else
				{
					DestroyProjectile();
				}
			}
		}

		private void GetColliderHitInfo(Collider other, out UnityEngine.Vector3 position, out UnityEngine.Vector3 normal)
		{
			UnityEngine.Vector3 vector = Time.fixedDeltaTime * 2f * rigidbody.linearVelocity;
			UnityEngine.Vector3 origin = base.transform.position - vector;
			float magnitude = vector.magnitude;
			other.Raycast(new Ray(origin, vector / magnitude), out var hitInfo, 2f * magnitude);
			position = hitInfo.point;
			normal = hitInfo.normal;
		}

		private void OnCollisionEnter(UnityEngine.Collision other)
		{
			ContactPoint contact = other.GetContact(0);
			HandleImpact(other.gameObject, contact.point, contact.normal);
		}

		private void OnCollisionStay(UnityEngine.Collision other)
		{
			ContactPoint contact = other.GetContact(0);
			HandleImpact(other.gameObject, contact.point, contact.normal);
		}

		private void OnTriggerEnter(Collider other)
		{
			GetColliderHitInfo(other, out var position, out var normal);
			HandleImpact(other.gameObject, position, normal);
		}

		private void OnTriggerStay(Collider other)
		{
			Transform transform = base.transform;
			HandleImpact(other.gameObject, transform.position, -transform.forward);
		}

		private void SpawnImpactEffect(GameObject prefab, UnityEngine.Vector3 position, UnityEngine.Vector3 normal)
		{
			if (prefab != null)
			{
				UnityEngine.Vector3 position2 = position + normal * impactEffectOffset;
				GameObject obj = ObjectPools.instance.Instantiate(prefab, position2);
				obj.transform.up = normal;
				obj.transform.position = position2;
			}
			onImpactShared.Invoke();
			if (spawnWorldEffects != null)
			{
				spawnWorldEffects.RequestSpawn(position, normal);
			}
		}

		private void DestroyProjectile()
		{
			impactEffectSpawned = false;
			if ((bool)forceComponent)
			{
				forceComponent.enabled = false;
			}
			if (ObjectPools.instance.DoesPoolExist(base.gameObject))
			{
				ObjectPools.instance.Destroy(base.gameObject);
			}
			else
			{
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}
	}
}
namespace FastSurfaceNets
{
	public class SurfaceNetsBuffer
	{
		public readonly List<float3> Positions = new List<float3>();

		public readonly List<float3> Normals = new List<float3>();

		public readonly List<int> Indices = new List<int>();

		internal readonly List<int3> SurfacePoints = new List<int3>();

		internal readonly List<int> SurfaceStrides = new List<int>();

		internal int[] StrideToIndex = Array.Empty<int>();

		public const int NullVertex = int.MaxValue;

		internal void Reset(int arraySize)
		{
			Positions.Clear();
			Normals.Clear();
			Indices.Clear();
			SurfacePoints.Clear();
			SurfaceStrides.Clear();
			if (StrideToIndex.Length < arraySize)
			{
				Array.Resize(ref StrideToIndex, arraySize);
			}
			for (int i = 0; i < arraySize; i++)
			{
				StrideToIndex[i] = int.MaxValue;
			}
		}
	}
	public static class SurfaceNets
	{
		private static readonly int3[] CubeCorners = new int3[8]
		{
			new int3(0, 0, 0),
			new int3(1, 0, 0),
			new int3(0, 1, 0),
			new int3(1, 1, 0),
			new int3(0, 0, 1),
			new int3(1, 0, 1),
			new int3(0, 1, 1),
			new int3(1, 1, 1)
		};

		private static readonly float3[] CornerVectors = new float3[8]
		{
			new float3(0f, 0f, 0f),
			new float3(1f, 0f, 0f),
			new float3(0f, 1f, 0f),
			new float3(1f, 1f, 0f),
			new float3(0f, 0f, 1f),
			new float3(1f, 0f, 1f),
			new float3(0f, 1f, 1f),
			new float3(1f, 1f, 1f)
		};

		private static readonly int2[] CubeEdges = new int2[12]
		{
			new int2(0, 1),
			new int2(0, 2),
			new int2(0, 4),
			new int2(1, 3),
			new int2(1, 5),
			new int2(2, 3),
			new int2(2, 6),
			new int2(3, 7),
			new int2(4, 5),
			new int2(4, 6),
			new int2(5, 7),
			new int2(6, 7)
		};

		public static void Generate(float[] sdf, int3 shape, int3 min, int3 max, SurfaceNetsBuffer output)
		{
			if (sdf == null)
			{
				throw new ArgumentNullException("sdf");
			}
			int num = shape.x * shape.y * shape.z;
			if (sdf.Length < num)
			{
				throw new ArgumentException("SDF array is smaller than shape.", "sdf");
			}
			output.Reset(num);
			int num2 = 1;
			int x = shape.x;
			int num3 = shape.x * shape.y;
			for (int i = min.z; i < max.z; i++)
			{
				for (int j = min.y; j < max.y; j++)
				{
					int num4 = i * num3 + j * x + min.x;
					int num5 = min.x;
					while (num5 < max.x)
					{
						if (EstimateSurfaceInCube(sdf, shape, new int3(num5, j, i), num4, num2, x, num3, output, out var centroid))
						{
							int count = output.Positions.Count;
							output.StrideToIndex[num4] = count;
							output.SurfacePoints.Add(new int3(num5, j, i));
							output.SurfaceStrides.Add(num4);
							output.Positions.Add(new float3(num5, j, i) + centroid);
						}
						num5++;
						num4++;
					}
				}
			}
			MakeAllQuads(sdf, shape, min, max, num2, x, num3, output);
			AccumulateNormals(output);
		}

		private static bool EstimateSurfaceInCube(float[] sdf, int3 shape, int3 voxel, int cubeMinStride, int strideX, int strideY, int strideZ, SurfaceNetsBuffer output, out float3 centroid)
		{
			float[] array = new float[8];
			int num = 0;
			for (int i = 0; i < 8; i++)
			{
				int3 int5 = CubeCorners[i];
				int num2 = cubeMinStride + int5.x * strideX + int5.y * strideY + int5.z * strideZ;
				if ((array[i] = sdf[num2]) < 0f)
				{
					num++;
				}
			}
			if (num == 0 || num == 8)
			{
				centroid = default(float3);
				return false;
			}
			float3 zero = float3.zero;
			int num3 = 0;
			int2[] cubeEdges = CubeEdges;
			for (int j = 0; j < cubeEdges.Length; j++)
			{
				int2 int6 = cubeEdges[j];
				float num4 = array[int6.x];
				float num5 = array[int6.y];
				if (num4 < 0f != num5 < 0f)
				{
					num3++;
					zero += EdgeIntersection(int6.x, int6.y, num4, num5);
				}
			}
			centroid = zero / num3;
			output.Normals.Add(float3.zero);
			return true;
		}

		private static float3 EdgeIntersection(int c1, int c2, float v1, float v2)
		{
			float num = v1 / (v1 - v2);
			return CornerVectors[c1] * (1f - num) + CornerVectors[c2] * num;
		}

		private static float3 CentralDifferenceGradient(float[] sdf, int3 shape, int3 v, int sx, int sy, int sz)
		{
			int num = math.max(v.x - 1, 0);
			int num2 = math.min(v.x + 1, shape.x - 1);
			int num3 = math.max(v.y - 1, 0);
			int num4 = math.min(v.y + 1, shape.y - 1);
			int num5 = math.max(v.z - 1, 0);
			int num6 = math.min(v.z + 1, shape.z - 1);
			float x = sdf[num2 + v.y * sy + v.z * sz] - sdf[num + v.y * sy + v.z * sz];
			float y = sdf[v.x + num4 * sy + v.z * sz] - sdf[v.x + num3 * sy + v.z * sz];
			float z = sdf[v.x + v.y * sy + num6 * sz] - sdf[v.x + v.y * sy + num5 * sz];
			return new float3(x, y, z);
		}

		private static void MakeAllQuads(float[] sdf, int3 shape, int3 min, int3 max, int sx, int sy, int sz, SurfaceNetsBuffer outBuf)
		{
			for (int i = 0; i < outBuf.SurfacePoints.Count; i++)
			{
				int3 int5 = outBuf.SurfacePoints[i];
				int num = outBuf.SurfaceStrides[i];
				if (int5.y != min.y && int5.z != min.z && int5.x != max.x - 1)
				{
					MaybeQuad(sdf, outBuf, num, num + sx, sy, sz);
				}
				if (int5.x != min.x && int5.z != min.z && int5.y != max.y - 1)
				{
					MaybeQuad(sdf, outBuf, num, num + sy, sz, sx);
				}
				if (int5.x != min.x && int5.y != min.y && int5.z != max.z - 1)
				{
					MaybeQuad(sdf, outBuf, num, num + sz, sx, sy);
				}
			}
		}

		private static void MaybeQuad(float[] sdf, SurfaceNetsBuffer b, int p1, int p2, int strideB, int strideC)
		{
			float num = sdf[p1];
			float num2 = sdf[p2];
			bool flag = num < 0f && num2 >= 0f;
			if (!flag && (!(num2 < 0f) || !(num >= 0f)))
			{
				return;
			}
			int num3 = b.StrideToIndex[p1];
			int num4 = b.StrideToIndex[p1 - strideB];
			int num5 = b.StrideToIndex[p1 - strideC];
			int num6 = b.StrideToIndex[p1 - strideB - strideC];
			if ((num3 | num4 | num5 | num6) == int.MaxValue)
			{
				return;
			}
			float3 obj = b.Positions[num3];
			float3 float5 = b.Positions[num4];
			float3 float6 = b.Positions[num5];
			float3 float7 = b.Positions[num6];
			if (math.lengthsq(obj - float7) < math.lengthsq(float5 - float6))
			{
				if (flag)
				{
					b.Indices.AddRange(new int[6] { num3, num6, num4, num3, num5, num6 });
				}
				else
				{
					b.Indices.AddRange(new int[6] { num3, num4, num6, num3, num6, num5 });
				}
			}
			else if (flag)
			{
				b.Indices.AddRange(new int[6] { num4, num5, num6, num4, num3, num5 });
			}
			else
			{
				b.Indices.AddRange(new int[6] { num4, num6, num5, num4, num5, num3 });
			}
		}

		private static void AccumulateNormals(SurfaceNetsBuffer b)
		{
			for (int i = 0; i < b.Indices.Count; i += 3)
			{
				int index = b.Indices[i];
				int index2 = b.Indices[i + 1];
				int index3 = b.Indices[i + 2];
				float3 float5 = b.Positions[index];
				float3 obj = b.Positions[index2];
				float3 float6 = math.cross(y: b.Positions[index3] - float5, x: obj - float5);
				b.Normals[index] += float6;
				b.Normals[index2] += float6;
				b.Normals[index3] += float6;
			}
		}
	}
	[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
	public class SurfaceNetsChunk : MonoBehaviour
	{
		public int3 Id;

		public GenerationParameters parameters;

		public const int ChunkSize = 32;

		public bool autoGenerate = true;

		private const int Pad = 1;

		private int3 chunkPosition;

		private NativeArray<byte> sdf;

		private int3 min;

		private int3 max;

		private int3 shape;

		private Mesh mesh;

		private void Awake()
		{
			if (autoGenerate)
			{
				BuildChunk();
			}
		}

		private void OnDestroy()
		{
			if (sdf.IsCreated)
			{
				sdf.Dispose();
				sdf = default(NativeArray<byte>);
			}
		}

		public async void BuildChunk()
		{
			chunkPosition = Id * 32;
			shape = new int3(34);
			int num = shape.x * shape.y * shape.z;
			if (sdf.IsCreated)
			{
				sdf.Dispose();
				sdf = default(NativeArray<byte>);
			}
			sdf = new NativeArray<byte>(num, Unity.Collections.Allocator.Persistent);
			FillChunk();
			Voxels.SurfaceNetsBuffer buffer = new Voxels.SurfaceNetsBuffer(32768, 65536, num);
			min = new int3(0);
			max = shape - 1;
			JobHandle handle = Voxels.SurfaceNets.Generate(sdf, shape, min, max, buffer);
			while (!handle.IsCompleted)
			{
				await UniTask.Yield();
			}
			handle.Complete();
			UnityEngine.Debug.Log($"{base.name} generated {buffer.Vertices.Length} vertices, {buffer.Normals.Length} normals, {buffer.Triangles.Length / 3}({buffer.Triangles.Length}) triangles.", this);
			if (buffer.Triangles.Length != 0)
			{
				if (parameters.customNormals)
				{
					MeshUtilities.MeshData meshData = MeshUtilities.SplitByAngle(buffer.Vertices.AsArray(), buffer.Triangles.AsArray(), parameters.normalThreshold, parameters.areaWeightedNormals);
					ref NativeList<float3> vertices = ref buffer.Vertices;
					ref NativeList<float3> vertices2 = ref meshData.Vertices;
					NativeList<float3> vertices3 = meshData.Vertices;
					NativeList<float3> vertices4 = buffer.Vertices;
					vertices = vertices3;
					vertices2 = vertices4;
					vertices = ref buffer.Normals;
					ref NativeList<float3> normals = ref meshData.Normals;
					vertices4 = meshData.Normals;
					vertices3 = buffer.Normals;
					vertices = vertices4;
					normals = vertices3;
					ref NativeList<int> triangles = ref buffer.Triangles;
					ref NativeList<int> triangles2 = ref meshData.Triangles;
					NativeList<int> triangles3 = meshData.Triangles;
					NativeList<int> triangles4 = buffer.Triangles;
					triangles = triangles3;
					triangles2 = triangles4;
					meshData.Dispose();
				}
				mesh = new Mesh
				{
					indexFormat = ((buffer.Vertices.Length > 65535) ? IndexFormat.UInt32 : IndexFormat.UInt16)
				};
				mesh.SetVertices(buffer.Vertices.AsArray());
				mesh.SetTriangles(buffer.Triangles.AsArray().ToArray(), 0, calculateBounds: false);
				if (parameters.recalculateNormals)
				{
					mesh.RecalculateNormals();
				}
				else
				{
					mesh.SetNormals(buffer.Normals.AsArray());
				}
				mesh.RecalculateBounds();
				buffer.Dispose();
				GetComponent<MeshFilter>().sharedMesh = mesh;
				base.gameObject.GetOrAddComponent<MeshCollider>().sharedMesh = mesh;
			}
		}

		private void FillChunk()
		{
			if (parameters.generateShape)
			{
				int x = shape.x;
				int num = shape.x * shape.y;
				int3 int5 = parameters.shapeMin - chunkPosition + min;
				int3 int6 = parameters.shapeMax - chunkPosition + min;
				for (int i = 0; i < shape.z; i++)
				{
					for (int j = 0; j < shape.y; j++)
					{
						int num2 = i * num + j * x;
						for (int k = 0; k < shape.x; k++)
						{
							float value;
							if (parameters.generateShape)
							{
								value = ((k >= int5.x && k <= int6.x && j >= int5.y && j <= int6.y && i >= int5.z && i <= int6.z) ? 1f : (-1f));
							}
							else
							{
								float3 float5 = (chunkPosition + new int3(k, j, i)).ToFloat3();
								value = noise.snoise(float5 * parameters.noiseScale) - float5.y / parameters.heightScale;
							}
							sdf[num2 + k] = value.ToByte();
						}
					}
				}
			}
			else
			{
				IJobParallelForExtensions.Schedule(new FillChunkJob
				{
					sdf = sdf,
					shape = shape,
					chunkPosition = chunkPosition,
					shapeMin = parameters.shapeMin,
					shapeMax = parameters.shapeMax,
					noiseScale = parameters.noiseScale,
					heightScale = parameters.heightScale,
					min = min,
					max = max,
					strideY = shape.x,
					strideZ = shape.x * shape.y
				}, shape.x * shape.y * shape.z, 64).Complete();
			}
		}

		private void OnDrawGizmosSelected()
		{
			if ((bool)mesh && mesh.vertexCount >= 3)
			{
				Gizmos.color = Color.green;
				int vertexCount = mesh.vertexCount;
				UnityEngine.Vector3[] vertices = mesh.vertices;
				UnityEngine.Vector3[] normals = mesh.normals;
				for (int i = 0; i < vertexCount; i++)
				{
					Gizmos.DrawLine(base.transform.position + vertices[i], base.transform.position + vertices[i] + normals[i] * 0.25f);
				}
			}
		}
	}
	internal struct FillChunkJob : IJobParallelFor
	{
		[WriteOnly]
		public NativeArray<byte> sdf;

		[Unity.Collections.ReadOnly]
		public int3 shape;

		[Unity.Collections.ReadOnly]
		public int3 chunkPosition;

		[Unity.Collections.ReadOnly]
		public int3 shapeMin;

		[Unity.Collections.ReadOnly]
		public int3 shapeMax;

		[Unity.Collections.ReadOnly]
		public float noiseScale;

		[Unity.Collections.ReadOnly]
		public float heightScale;

		[Unity.Collections.ReadOnly]
		public int3 min;

		[Unity.Collections.ReadOnly]
		public int3 max;

		[Unity.Collections.ReadOnly]
		public int strideY;

		[Unity.Collections.ReadOnly]
		public int strideZ;

		public void Execute(int index)
		{
			int z = index / strideZ;
			int y = index % strideZ / strideY;
			int x = index % strideY;
			float3 float5 = (chunkPosition + new int3(x, y, z)).ToFloat3();
			float value = noise.snoise(float5 * noiseScale) - float5.y / heightScale;
			sdf[index] = value.ToByte();
		}
	}
	[Serializable]
	public class GenerationParameters
	{
		public bool recalculateNormals;

		public bool customNormals = true;

		public bool useBurst = true;

		public float normalThreshold = 60f;

		public bool areaWeightedNormals = true;

		public bool generateShape = true;

		public int3 shapeMin = new int3(1);

		public int3 shapeMax = new int3(15);

		public float noiseScale = 0.01f;

		public float baseHeight = 10f;

		public float heightScale = 5f;
	}
	public class SurfaceNetsWorld : MonoBehaviour
	{
		public SurfaceNetsChunk chunkPrefab;

		public int3 radius;

		public GenerationParameters parameters;

		private void Awake()
		{
			Generate();
		}

		private void Generate()
		{
			DestroyChildren();
			for (int i = -radius.x; i <= radius.x; i++)
			{
				for (int j = -radius.y; j <= radius.y; j++)
				{
					for (int k = -radius.z; k <= radius.z; k++)
					{
						int3 int5 = new int3(i, j, k);
						SurfaceNetsChunk surfaceNetsChunk = UnityEngine.Object.Instantiate(chunkPrefab, base.transform);
						surfaceNetsChunk.Id = int5;
						surfaceNetsChunk.parameters = parameters;
						surfaceNetsChunk.name = $"SurfaceNetsChunk_{int5.x}_{int5.y}_{int5.z}";
						surfaceNetsChunk.transform.localPosition = int5.ToFloat3() * 32f;
						surfaceNetsChunk.BuildChunk();
					}
				}
			}
		}

		private void DestroyChildren()
		{
			for (int num = base.transform.childCount - 1; num >= 0; num--)
			{
				Transform child = base.transform.GetChild(num);
				if (child != null)
				{
					JamUtil.Destroy(child.gameObject);
				}
			}
		}
	}
}
namespace Voxels
{
	public enum ChunkState
	{
		UNINITIALIZED,
		Created,
		VoxelDataGenerated,
		MeshDataGenerated,
		MeshCreated,
		CollisionBaked,
		MeshAssigned
	}
	[Serializable]
	public class Chunk : IDisposable
	{
		public VoxelWorld World;

		public int3 Id;

		public int3 Size;

		public int3 Dimensions;

		public int VoxelCount;

		public NativeArray<byte> Density;

		public NativeArray<byte> Material;

		public NativeArray<MeshVertexData> VertexData;

		public NativeArray<ushort> TriangleData;

		public object GenericMeshData;

		public bool IsDataGenerated;

		public bool IsDataChanged;

		public bool IsMeshGenerated;

		public bool IsMeshCreated;

		public bool IsCollisionBaked;

		public bool IsMeshAssigned;

		public bool IsDirty = true;

		public int VertexCount;

		public Mesh Mesh;

		public ChunkComponent Component { get; private set; }

		public GameObject GameObject { get; private set; }

		public MeshFilter MeshFilter { get; private set; }

		public MeshRenderer MeshRenderer { get; private set; }

		public MeshCollider MeshCollider { get; private set; }

		public static int3 DefaultSize { get; set; } = 32;

		public static int Pad { get; set; } = 1;

		public ChunkState State
		{
			get
			{
				if (!IsDataGenerated)
				{
					return ChunkState.Created;
				}
				if (!IsMeshGenerated)
				{
					return ChunkState.VoxelDataGenerated;
				}
				if (!IsMeshCreated)
				{
					return ChunkState.MeshDataGenerated;
				}
				if (!IsCollisionBaked)
				{
					return ChunkState.MeshCreated;
				}
				if (!IsMeshAssigned)
				{
					return ChunkState.CollisionBaked;
				}
				return ChunkState.MeshAssigned;
			}
		}

		public Chunk(ChunkDTO dto)
		{
			Id = dto.Id;
			Size = dto.Size;
			Dimensions = dto.Dimensions;
			VoxelCount = Dimensions.x * Dimensions.y * Dimensions.z;
			Density = dto.Density;
			Material = dto.Material;
			VertexData = default(NativeArray<MeshVertexData>);
			TriangleData = default(NativeArray<ushort>);
			GenericMeshData = null;
		}

		public Chunk(int3 id, int3 size, int padding = -1)
		{
			if (padding < 0)
			{
				padding = Pad;
			}
			Id = id;
			Size = size;
			Dimensions = size + padding;
			VoxelCount = Dimensions.x * Dimensions.y * Dimensions.z;
			Density = default(NativeArray<byte>);
			Material = default(NativeArray<byte>);
			VertexData = default(NativeArray<MeshVertexData>);
			TriangleData = default(NativeArray<ushort>);
			GenericMeshData = null;
		}

		public void SetFrom(ChunkDTO dto)
		{
			Id = dto.Id;
			Size = dto.Size;
			Dimensions = dto.Dimensions;
			VoxelCount = Dimensions.x * Dimensions.y * Dimensions.z;
			Dispose();
			Density = dto.Density;
			Material = dto.Material;
			IsDataGenerated = true;
			IsDataChanged = true;
			IsMeshGenerated = false;
			IsMeshCreated = false;
			IsCollisionBaked = false;
			IsMeshAssigned = false;
			IsDirty = true;
			VertexCount = 0;
			Mesh = null;
		}

		public void UpdateFrom(ChunkDTO dto)
		{
			Id = dto.Id;
			Size = dto.Size;
			Dimensions = dto.Dimensions;
			VoxelCount = Dimensions.x * Dimensions.y * Dimensions.z;
			DisposeAllExceptComponent();
			Density = dto.Density;
			Material = dto.Material;
			IsDataGenerated = true;
			IsDataChanged = true;
			IsMeshGenerated = false;
			IsMeshCreated = false;
			IsCollisionBaked = false;
			IsMeshAssigned = false;
			IsDirty = true;
			VertexCount = 0;
			Mesh = null;
		}

		public void Clear()
		{
			DisposeMeshData();
			IsDataGenerated = false;
			IsDataChanged = false;
			IsMeshGenerated = false;
			IsMeshCreated = false;
			IsCollisionBaked = false;
			IsMeshAssigned = false;
			IsDirty = true;
			VertexCount = 0;
			Mesh = null;
		}

		public void SetComponent(ChunkComponent chunkComponent)
		{
			Component = chunkComponent;
			if ((bool)chunkComponent)
			{
				GameObject = chunkComponent.gameObject;
				MeshFilter = chunkComponent.meshFilter;
				MeshRenderer = chunkComponent.meshRenderer;
				MeshCollider = chunkComponent.meshCollider;
				Component.name = GetChunkName(Id);
				Component.World = World;
			}
			else
			{
				GameObject = null;
				MeshFilter = null;
				MeshRenderer = null;
				MeshCollider = null;
			}
		}

		public void Dispose()
		{
			if (Density.IsCreated)
			{
				Density.Dispose();
				Density = default(NativeArray<byte>);
			}
			if (Material.IsCreated)
			{
				Material.Dispose();
				Material = default(NativeArray<byte>);
			}
			DisposeMeshData();
			if ((bool)Component)
			{
				UnityEngine.Object.Destroy(Component.gameObject);
			}
		}

		public void DisposeAllExceptComponent()
		{
			if (Density.IsCreated)
			{
				Density.Dispose();
				Density = default(NativeArray<byte>);
			}
			if (Material.IsCreated)
			{
				Material.Dispose();
				Material = default(NativeArray<byte>);
			}
			DisposeMeshData();
		}

		public void AllocateVertexData(int length)
		{
			if (VertexData.IsCreated)
			{
				if (VertexData.Length == length)
				{
					return;
				}
				NativeArrayPool<MeshVertexData>.Return(VertexData);
				VertexData = default(NativeArray<MeshVertexData>);
			}
			VertexData = NativeArrayPool<MeshVertexData>.Get(length);
		}

		public void AllocateTriangleData(int length)
		{
			if (TriangleData.IsCreated)
			{
				if (TriangleData.Length == length)
				{
					return;
				}
				NativeArrayPool<ushort>.Return(TriangleData);
				TriangleData = default(NativeArray<ushort>);
			}
			TriangleData = NativeArrayPool<ushort>.Get(length);
		}

		public void DisposeMeshData()
		{
			if (VertexData.IsCreated)
			{
				NativeArrayPool<MeshVertexData>.Return(VertexData);
				VertexData = default(NativeArray<MeshVertexData>);
			}
			if (TriangleData.IsCreated)
			{
				NativeArrayPool<ushort>.Return(TriangleData);
				TriangleData = default(NativeArray<ushort>);
			}
			if (GenericMeshData is IDisposable disposable)
			{
				disposable.Dispose();
				GenericMeshData = null;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int3 GetLocalPosition(int3 voxelPosition)
		{
			return voxelPosition - Id * Size;
		}

		public override string ToString()
		{
			return string.Format("Chunk ({0}, {1}, {2}) [{3}{4}{5}{6}{7}{8}]", Id.x, Id.y, Id.z, IsDataGenerated ? "D" : "_", IsDataChanged ? "C" : "_", IsMeshGenerated ? "G" : "_", IsMeshCreated ? "M" : "_", IsCollisionBaked ? "B" : "_", IsMeshAssigned ? "A" : "_");
		}

		public static string GetChunkName(int3 id)
		{
			return $"Chunk_{id.x}_{id.y}_{id.z}";
		}
	}
	[RequireComponent(typeof(MeshFilter))]
	[RequireComponent(typeof(MeshRenderer))]
	[RequireComponent(typeof(MeshCollider))]
	public class ChunkComponent : MonoBehaviour
	{
		public MeshFilter meshFilter;

		public MeshRenderer meshRenderer;

		public MeshCollider meshCollider;

		public VoxelWorld World { get; set; }

		private void Reset()
		{
			meshFilter = GetComponent<MeshFilter>();
			meshRenderer = GetComponent<MeshRenderer>();
			meshCollider = GetComponent<MeshCollider>();
		}
