	public struct ChunkDTO
	{
		public int WorldId;

		public int3 Id;

		public int3 Size;

		public int3 Dimensions;

		public NativeArray<byte> Density;

		public NativeArray<byte> Material;

		public bool IsValid
		{
			get
			{
				if (!Size.Equals(int3.zero) && Density.IsCreated)
				{
					return Material.IsCreated;
				}
				return false;
			}
		}

		public ChunkDTO(Chunk chunk)
		{
			WorldId = chunk.World.Id;
			Id = chunk.Id;
			Size = chunk.Size;
			Dimensions = chunk.Dimensions;
			Density = chunk.Density;
			Material = chunk.Material;
		}
	}
	public static class ChunkIO
	{
		public const uint MAGIC = 1448040524u;

		public const int VERSION = 5;

		private static readonly string Root = System.IO.Path.Combine(UnityEngine.Application.persistentDataPath, "WorldSaves");

		public static string PathFor(int3 id)
		{
			return System.IO.Path.Combine(Root, $"{id.x}_{id.y}_{id.z}.vox");
		}

		public static void SaveChunk(ChunkDTO dto)
		{
			string text = PathFor(dto.Id);
			UnityEngine.Debug.Log($"Saving chunk {dto.Id} to {text}");
			Save(text, in dto);
		}

		public static bool TryLoadChunk(int3 id, out ChunkDTO dto)
		{
			string arg = PathFor(id);
			if (!File.Exists(PathFor(id)))
			{
				dto = default(ChunkDTO);
				return false;
			}
			dto = Load(PathFor(id));
			if (dto.IsValid)
			{
				UnityEngine.Debug.Log($"Loaded chunk {id} from {arg}");
			}
			else
			{
				UnityEngine.Debug.Log($"Chunk {id} at {arg} magic or version mismatch.");
			}
			return dto.IsValid;
		}

		public static void Save(string path, in ChunkDTO chunk)
		{
			if (!Directory.Exists(Root))
			{
				Directory.CreateDirectory(Root);
			}
			using FileStream output = new FileStream(path, FileMode.Create, FileAccess.Write, FileShare.None, 4096, useAsync: false);
			using BinaryWriter bw = new BinaryWriter(output);
			WriteChunk(bw, in chunk);
		}

		public static byte[] SerializeChunk(in ChunkDTO chunk)
		{
			using MemoryStream memoryStream = new MemoryStream(4096);
			using BinaryWriter binaryWriter = new BinaryWriter(memoryStream);
			WriteChunk(binaryWriter, in chunk);
			binaryWriter.Flush();
			return memoryStream.ToArray();
		}

		private static void WriteChunk(BinaryWriter bw, in ChunkDTO chunk)
		{
			bw.Write(1448040524u);
			bw.Write(5);
			bw.Write(chunk.WorldId);
			bw.Write(chunk.Id.x);
			bw.Write(chunk.Id.y);
			bw.Write(chunk.Id.z);
			bw.Write(chunk.Size.x);
			bw.Write(chunk.Size.y);
			bw.Write(chunk.Size.z);
			bw.Write(chunk.Dimensions.x);
			bw.Write(chunk.Dimensions.y);
			bw.Write(chunk.Dimensions.z);
			WriteNativeArray(bw, chunk.Density);
			WriteNativeArray(bw, chunk.Material);
		}

		public static ChunkDTO Load(string path, Unity.Collections.Allocator alloc = Unity.Collections.Allocator.Persistent)
		{
			using FileStream input = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 4096, useAsync: false);
			using BinaryReader br = new BinaryReader(input);
			return ReadChunk(br, alloc);
		}

		public static bool TryDeserializeChunk(in byte[] data, out ChunkDTO dto)
		{
			dto = DeserializeChunk(in data);
			return dto.IsValid;
		}

		public static ChunkDTO DeserializeChunk(in byte[] data, Unity.Collections.Allocator alloc = Unity.Collections.Allocator.Persistent)
		{
			using MemoryStream input = new MemoryStream(data);
			using BinaryReader br = new BinaryReader(input);
			return ReadChunk(br);
		}

		private static ChunkDTO ReadChunk(BinaryReader br, Unity.Collections.Allocator alloc = Unity.Collections.Allocator.Persistent)
		{
			uint num = br.ReadUInt32();
			int num2 = br.ReadInt32();
			if (num != 1448040524 || num2 != 5)
			{
				return default(ChunkDTO);
			}
			int worldId = br.ReadInt32();
			int3 id = new int3(br.ReadInt32(), br.ReadInt32(), br.ReadInt32());
			int3 size = new int3(br.ReadInt32(), br.ReadInt32(), br.ReadInt32());
			int3 dimensions = new int3(br.ReadInt32(), br.ReadInt32(), br.ReadInt32());
			NativeArray<byte> density = ReadNativeArray(br, alloc);
			NativeArray<byte> material = ReadNativeArray(br, alloc);
			return new ChunkDTO
			{
				WorldId = worldId,
				Id = id,
				Size = size,
				Dimensions = dimensions,
				Density = density,
				Material = material
			};
		}

		private static void WriteNativeArray(BinaryWriter bw, NativeArray<byte> src)
		{
			byte[] array = LZ4Pickler.Pickle(src.ToArray());
			bw.Write(array.Length);
			bw.Write(array);
		}

		private static NativeArray<byte> ReadNativeArray(BinaryReader br, Unity.Collections.Allocator alloc = Unity.Collections.Allocator.Persistent)
		{
			int count = br.ReadInt32();
			byte[] array = LZ4Pickler.Unpickle(br.ReadBytes(count));
			int length = array.Length;
			NativeArray<byte> nativeArray = new NativeArray<byte>(length, alloc);
			NativeArray<byte>.Copy(array, nativeArray, length);
			return nativeArray;
		}

		public static void DeleteWorld()
		{
			if (Directory.Exists(Root))
			{
				Directory.Delete(Root, recursive: true);
			}
			UnityEngine.Debug.Log("All chunks deleted.");
		}
	}
	public class ChunkTaskSet
	{
		public delegate ChunkTask ChunkTaskDelegate(Chunk chunk, GenerationParameters parameters);

		public List<Chunk> Chunks;

		public GenerationParameters Parameters;

		public Queue<(ChunkTaskDelegate task, Action<Chunk> callback)> Tasks;

		public ChunkTask Current;

		public Action<Chunk> Callback;

		public Chunk Chunk => Chunks[0];

		public bool HasChunks
		{
			get
			{
				if (Chunks == null || Chunks.Count == 0)
				{
					return false;
				}
				foreach (Chunk chunk in Chunks)
				{
					if (chunk == null)
					{
						return false;
					}
				}
				return true;
			}
		}

		public bool IsEmpty
		{
			get
			{
				if (!Current.IsCreated && Callback == null)
				{
					return Tasks.Count == 0;
				}
				return false;
			}
		}

		public ChunkTaskSet(GenerationParameters parameters)
		{
			Chunks = new List<Chunk>();
			Parameters = parameters;
			Tasks = new Queue<(ChunkTaskDelegate, Action<Chunk>)>();
		}

		public ChunkTaskSet(Chunk chunk, GenerationParameters parameters, params (ChunkTaskDelegate task, Action<Chunk> callback)[] tasks)
		{
			Chunks = new List<Chunk> { chunk };
			Parameters = parameters;
			Tasks = new Queue<(ChunkTaskDelegate, Action<Chunk>)>(tasks);
		}

		public ChunkTaskSet(IList<Chunk> chunks, GenerationParameters parameters, params (ChunkTaskDelegate task, Action<Chunk> callback)[] tasks)
		{
			Chunks = new List<Chunk>(chunks);
			Parameters = parameters;
			Tasks = new Queue<(ChunkTaskDelegate, Action<Chunk>)>(tasks);
		}

		public void AddTask(ChunkTaskDelegate task, Action<Chunk> callback = null)
		{
			Tasks.Enqueue((task, callback));
		}

		public void Start()
		{
			if (Current.IsCreated || Callback != null)
			{
				throw new InvalidOperationException("Cannot start a ChunkTaskSet that is already running.");
			}
			StartNext();
			UpdateDirty();
		}

		public void Complete()
		{
			CompleteCurrent();
			while (StartNext())
			{
				CompleteCurrent();
			}
			UpdateDirty();
		}

		public bool CompleteIfReady()
		{
			if (CompleteCurrentIfReady())
			{
				if (Tasks.Count == 0)
				{
					UpdateDirty();
					return true;
				}
				StartNext();
			}
			UpdateDirty();
			return false;
		}

		private bool CompleteCurrentIfReady()
		{
			if (Current.IsCompleted)
			{
				CompleteCurrent();
				return true;
			}
			return false;
		}

		private void CompleteCurrent()
		{
			Current.Complete();
			foreach (Chunk chunk in Chunks)
			{
				Callback?.Invoke(chunk);
			}
			Current = default(ChunkTask);
			Callback = null;
		}

		private bool StartNext()
		{
			if (Tasks.Count == 0)
			{
				return false;
			}
			(ChunkTaskDelegate, Action<Chunk>) task = Tasks.Dequeue();
			(Current, Callback) = CreateTask(task);
			if (Current.IsCompleted)
			{
				CompleteCurrent();
				return StartNext();
			}
			return true;
		}

		private void UpdateDirty()
		{
			if (Current.IsCreated || Callback != null || Tasks.Count > 0)
			{
				foreach (Chunk chunk in Chunks)
				{
					chunk.IsDirty = false;
				}
				return;
			}
			foreach (Chunk chunk2 in Chunks)
			{
				chunk2.IsDirty = chunk2.State < ChunkState.MeshAssigned;
			}
		}

		private (ChunkTask, Action<Chunk>) CreateTask((ChunkTaskDelegate task, Action<Chunk> callback) task)
		{
			return CreateTask(task.task, task.callback);
		}

		private (ChunkTask, Action<Chunk>) CreateTask(ChunkTaskDelegate task, Action<Chunk> callback = null)
		{
			if (Chunks.Count == 1)
			{
				return (task?.Invoke(Chunks[0], Parameters) ?? default(ChunkTask), callback);
			}
			NativeArray<JobHandle> jobs = new NativeArray<JobHandle>(Chunks.Count, Unity.Collections.Allocator.Temp);
			for (int i = 0; i < Chunks.Count; i++)
			{
				jobs[i] = task?.Invoke(Chunks[i], Parameters).Handle ?? default(JobHandle);
			}
			JobHandle handle = JobHandle.CombineDependencies(jobs);
			jobs.Dispose();
			return (new ChunkTask(Chunks[0], handle), callback);
		}
	}
	public struct ChunkTask
	{
		public Chunk Chunk;

		public JobHandle Handle;

		private Action _onJobComplete;

		public bool IsCreated => !Handle.Equals(default(JobHandle));

		public bool IsCompleted => Handle.IsCompleted;

		public bool CompleteIfReady()
		{
			if (Handle.IsCompleted)
			{
				Complete();
				return true;
			}
			return false;
		}

		public void Complete()
		{
			Handle.Complete();
			_onJobComplete?.Invoke();
			_onJobComplete = null;
		}

		public ChunkTask(Chunk chunk, JobHandle handle, Action onComplete = null)
		{
			Chunk = chunk;
			Handle = handle;
			_onJobComplete = onComplete;
		}

		public static ChunkTask CreateVoxelDataJob(Chunk chunk, GenerationParameters parameters)
		{
			if (!chunk.Density.IsCreated)
			{
				chunk.Density = new NativeArray<byte>(chunk.VoxelCount, Unity.Collections.Allocator.Persistent);
			}
			if (!chunk.Material.IsCreated)
			{
				chunk.Material = new NativeArray<byte>(chunk.VoxelCount, Unity.Collections.Allocator.Persistent);
			}
			JobHandle handle = IJobParallelForExtensions.Schedule(new GenerateVoxelDataJob
			{
				chunkPosition = chunk.Id,
				chunkSize = chunk.Size.x,
				dimension = chunk.Dimensions.x,
				noiseScale = parameters.NoiseScale,
				groundLevel = parameters.GroundLevel,
				heightCompensation = parameters.HeightCompensation,
				octaves = parameters.Octaves,
				persistence = parameters.Persistence,
				heightScale = parameters.HeightScale,
				seed = parameters.Seed,
				voxels = chunk.Density,
				materials = chunk.Material
			}, chunk.VoxelCount, 64);
			Action onComplete = delegate
			{
				chunk.IsDataGenerated = true;
				chunk.IsMeshGenerated = false;
				chunk.IsDirty = true;
			};
			return new ChunkTask(chunk, handle, onComplete);
		}

		public static ChunkTask CreateMeshDataJob(Chunk chunk, GenerationParameters parameters)
		{
			NativeCounter triangleCounter = new NativeCounter(Unity.Collections.Allocator.TempJob);
			Action onComplete = null;
			JobHandle handle = parameters.MeshGenerationMode switch
			{
				MeshGenerationMode.MarchingCubes => CreateMarchingCubesMeshJob(), 
				MeshGenerationMode.SurfaceNets => CreateSurfaceNetsMeshJob(), 
				_ => throw new ArgumentOutOfRangeException(), 
			};
			return new ChunkTask(chunk, handle, onComplete);
			JobHandle CreateMarchingCubesMeshJob()
			{
				int length = math.min(chunk.VoxelCount * 15, 65535);
				chunk.AllocateVertexData(length);
				chunk.AllocateTriangleData(length);
				onComplete = delegate
				{
					chunk.IsMeshGenerated = true;
					chunk.IsCollisionBaked = false;
					chunk.IsDirty = true;
					chunk.VertexCount = triangleCounter.Count * 3;
					triangleCounter.Dispose();
				};
				return new MarchingCubesMeshingJob
				{
					voxels = chunk.Density,
					materials = chunk.Material,
					vertexData = chunk.VertexData,
					triangleData = chunk.TriangleData,
					triangleCounter = triangleCounter,
					chunkSize = chunk.Size.x,
					isoLevel = parameters.IsoLevel.ToByte()
				}.Schedule();
			}
			JobHandle CreateSurfaceNetsMeshJob()
			{
				SurfaceNetsBuffer surfaceNetsBuffer = new SurfaceNetsBuffer(32768, 65536, chunk.VoxelCount);
				chunk.GenericMeshData = surfaceNetsBuffer;
				onComplete = delegate
				{
				};
				return new SurfaceNetsJob
				{
					sdf = chunk.Density,
					material = chunk.Material,
					shape = chunk.Dimensions,
					min = 0,
					max = chunk.Dimensions - 1,
					buffer = surfaceNetsBuffer,
					isoLevel = parameters.IsoLevel.ToByte()
				}.Schedule();
			}
		}

		public static ChunkTask CreateSurfaceNetsPostProcessingJob(Chunk chunk, GenerationParameters parameters)
		{
			if (!(chunk.GenericMeshData is SurfaceNetsBuffer surfaceNetsBuffer))
			{
				throw new InvalidOperationException($"{chunk} GenericMeshData is not a SurfaceNetsBuffer.");
			}
			if (surfaceNetsBuffer.Triangles.Length < 3)
			{
				chunk.IsMeshGenerated = true;
				chunk.IsCollisionBaked = false;
				chunk.IsDirty = true;
				chunk.VertexCount = 0;
				return default(ChunkTask);
			}
			NativeCounter triangleCounter = new NativeCounter(Unity.Collections.Allocator.TempJob);
			int length = math.min(chunk.VoxelCount * 15, 65535);
			if (!chunk.VertexData.IsCreated)
			{
				chunk.VertexData = new NativeArray<MeshVertexData>(length, Unity.Collections.Allocator.Persistent);
			}
			if (!chunk.TriangleData.IsCreated)
			{
				chunk.TriangleData = new NativeArray<ushort>(length, Unity.Collections.Allocator.Persistent);
			}
			MeshUtilities.VoxelMeshData voxelMeshData = MeshUtilities.SplitByAngle(surfaceNetsBuffer.Vertices.AsArray(), surfaceNetsBuffer.Materials.AsArray(), surfaceNetsBuffer.Triangles.AsArray(), parameters.NormalThreshold, parameters.AreaWeightedNormals);
			ref NativeList<float3> vertices = ref surfaceNetsBuffer.Vertices;
			ref NativeList<float3> vertices2 = ref voxelMeshData.Vertices;
			NativeList<float3> vertices3 = voxelMeshData.Vertices;
			NativeList<float3> vertices4 = surfaceNetsBuffer.Vertices;
			vertices = vertices3;
			vertices2 = vertices4;
			ref NativeList<byte> materials = ref surfaceNetsBuffer.Materials;
			ref NativeList<byte> materials2 = ref voxelMeshData.Materials;
			NativeList<byte> materials3 = voxelMeshData.Materials;
			NativeList<byte> materials4 = surfaceNetsBuffer.Materials;
			materials = materials3;
			materials2 = materials4;
			vertices = ref surfaceNetsBuffer.Normals;
			ref NativeList<float3> normals = ref voxelMeshData.Normals;
			vertices4 = voxelMeshData.Normals;
			vertices3 = surfaceNetsBuffer.Normals;
			vertices = vertices4;
			normals = vertices3;
			ref NativeList<int> triangles = ref surfaceNetsBuffer.Triangles;
			ref NativeList<int> triangles2 = ref voxelMeshData.Triangles;
			NativeList<int> triangles3 = voxelMeshData.Triangles;
			NativeList<int> triangles4 = surfaceNetsBuffer.Triangles;
			triangles = triangles3;
			triangles2 = triangles4;
			chunk.GenericMeshData = surfaceNetsBuffer;
			voxelMeshData.Dispose();
			JobHandle handle = new AssembleVertexDataJob
			{
				vertexData = chunk.VertexData,
				triangleData = chunk.TriangleData,
				triangleCounter = triangleCounter,
				srcVerts = surfaceNetsBuffer.Vertices.AsArray(),
				srcMats = surfaceNetsBuffer.Materials.AsArray(),
				srcNorm = surfaceNetsBuffer.Normals.AsArray(),
				srcTris = surfaceNetsBuffer.Triangles.AsArray()
			}.Schedule();
			Action onComplete = delegate
			{
				chunk.IsMeshGenerated = true;
				chunk.IsCollisionBaked = false;
				chunk.IsDirty = true;
				chunk.VertexCount = triangleCounter.Count * 3;
				triangleCounter.Dispose();
			};
			return new ChunkTask(chunk, handle, onComplete);
		}

		public static ChunkTask CreateCollisionJob(Chunk chunk, GenerationParameters parameters = default(GenerationParameters))
		{
			if (chunk.Mesh == null)
			{
				chunk.IsCollisionBaked = true;
				chunk.IsDirty = true;
				return default(ChunkTask);
			}
			JobHandle handle = new CollisionJob
			{
				MeshId = chunk.Mesh.GetEntityId()
			}.Schedule();
			Action onJobComplete = delegate
			{
				chunk.IsCollisionBaked = true;
				chunk.IsDirty = true;
			};
			return new ChunkTask
			{
				Handle = handle,
				_onJobComplete = onJobComplete,
				Chunk = chunk
			};
		}
	}
	[BurstCompile]
	public struct CollisionJob : IJob
	{
		public const MeshColliderCookingOptions CookingOptions = MeshColliderCookingOptions.CookForFasterSimulation | MeshColliderCookingOptions.EnableMeshCleaning | MeshColliderCookingOptions.WeldColocatedVertices | MeshColliderCookingOptions.UseFastMidphase;

		public EntityId MeshId;

		public void Execute()
		{
			Physics.BakeMesh(MeshId, convex: false, MeshColliderCookingOptions.CookForFasterSimulation | MeshColliderCookingOptions.EnableMeshCleaning | MeshColliderCookingOptions.WeldColocatedVertices | MeshColliderCookingOptions.UseFastMidphase);
		}
	}
	[BurstCompile]
	public struct GenerateVoxelDataJob : IJobParallelFor
	{
		public int3 chunkPosition;

		public int chunkSize;

		public int dimension;

		public float noiseScale;

		public float groundLevel;

		public float heightScale;

		public float heightCompensation;

		public int octaves;

		public float persistence;

		public int seed;

		[WriteOnly]
		public NativeArray<byte> voxels;

		[WriteOnly]
		public NativeArray<byte> materials;

		public void Execute(int index)
		{
			int num = index % dimension;
			int num2 = index / dimension % dimension;
			int num3 = index / (dimension * dimension);
			float3 float5 = new float3(chunkPosition.x * chunkSize + num, chunkPosition.y * chunkSize + num2, chunkPosition.z * chunkSize + num3);
			float3 float6 = new float3((float)seed * 1.7f, (float)seed * 2.3f, (float)seed * 3.1f);
			float3 float7 = float5 + float6;
			float num4 = noise.snoise((new float3(float5.x, 0f, float5.z) + float6) * noiseScale) + (groundLevel - float5.y) / heightScale;
			num4 = math.clamp(num4 * heightCompensation, -1f, 1f);
			float num5 = noiseScale;
			float num6 = 1f;
			for (int i = 0; i < octaves; i++)
			{
				num5 *= 2f;
				num6 *= persistence;
				num4 += noise.snoise(float7 * num5) * num6;
			}
			if (noise.snoise(float7 * 0.05f) > 0.6f && num4 >= 0f)
			{
				materials[index] = 1;
			}
			voxels[index] = num4.ToByte();
		}
	}
