	[BurstCompile]
	public struct MarchingCubesMeshingJob : IJob
	{
		[Unity.Collections.ReadOnly]
		public NativeArray<byte> voxels;

		[Unity.Collections.ReadOnly]
		public NativeArray<byte> materials;

		[Unity.Collections.ReadOnly]
		public int chunkSize;

		[Unity.Collections.ReadOnly]
		public byte isoLevel;

		public NativeCounter triangleCounter;

		[NativeDisableParallelForRestriction]
		[WriteOnly]
		public NativeArray<MeshVertexData> vertexData;

		[NativeDisableParallelForRestriction]
		[WriteOnly]
		public NativeArray<ushort> triangleData;

		private int dimension;

		public void Execute()
		{
			dimension = chunkSize + 1;
			for (int i = 0; i < chunkSize; i++)
			{
				for (int j = 0; j < chunkSize; j++)
				{
					for (int k = 0; k < chunkSize; k++)
					{
						ProcessCube(i, j, k);
					}
				}
			}
		}

		private void ProcessCube(int x, int y, int z)
		{
			int3 int5 = new int3(x, y, z);
			GetMaterialValue(int5);
			NativeArray<byte> nativeArray = new NativeArray<byte>(8, Unity.Collections.Allocator.Temp);
			for (int i = 0; i < 8; i++)
			{
				int3 pos = new int3(x, y, z) + (int3)MarchingCubesLookup.CornerOffsets[i];
				nativeArray[i] = GetVoxelValue(pos);
			}
			int num = 0;
			for (int j = 0; j < 8; j++)
			{
				if (nativeArray[j] < isoLevel)
				{
					num |= 1 << j;
				}
			}
			if (num == 0 || num == 255)
			{
				nativeArray.Dispose();
				return;
			}
			NativeArray<float3> nativeArray2 = new NativeArray<float3>(12, Unity.Collections.Allocator.Temp);
			NativeArray<float> nativeArray3 = new NativeArray<float>(12, Unity.Collections.Allocator.Temp);
			for (int k = 0; k < 12; k++)
			{
				if ((MarchingCubesLookup.EdgeTable[num] & (1 << k)) != 0)
				{
					int2 int6 = MarchingCubesLookup.EdgeVertices[k];
					float3 start = new float3(x, y, z) + MarchingCubesLookup.CornerOffsets[int6.x];
					float3 end = new float3(x, y, z) + MarchingCubesLookup.CornerOffsets[int6.y];
					float t = (float)(isoLevel - nativeArray[int6.x]) / (float)(nativeArray[int6.y] - nativeArray[int6.x]);
					nativeArray2[k] = math.lerp(start, end, t);
					byte materialValue = GetMaterialValue((int5 + MarchingCubesLookup.CornerOffsets[int6.x]).ToInt3());
					byte materialValue2 = GetMaterialValue((int5 + MarchingCubesLookup.CornerOffsets[int6.y]).ToInt3());
					int num2 = math.max((int)materialValue, (int)materialValue2);
					nativeArray3[k] = num2;
				}
			}
			for (int l = 0; l < 16 && MarchingCubesLookup.TriTable[num * 16 + l] != -1; l += 3)
			{
				float3 float5 = nativeArray2[MarchingCubesLookup.TriTable[num * 16 + l]];
				float3 float6 = nativeArray2[MarchingCubesLookup.TriTable[num * 16 + l + 1]];
				float3 float7 = nativeArray2[MarchingCubesLookup.TriTable[num * 16 + l + 2]];
				float x2 = nativeArray3[MarchingCubesLookup.TriTable[num * 16 + l]];
				float y2 = nativeArray3[MarchingCubesLookup.TriTable[num * 16 + l + 1]];
				float z2 = nativeArray3[MarchingCubesLookup.TriTable[num * 16 + l + 2]];
				float4 float8 = new float4(x2, y2, z2, 0f);
				if (!float5.Equals(float6) && !float5.Equals(float7) && !float6.Equals(float7))
				{
					float3 float9 = math.normalize(math.cross(float6 - float5, float7 - float5));
					float3 xyz = math.normalize(math.cross((math.abs(float9.y) < 0.999f) ? new float3(0f, 1f, 0f) : new float3(1f, 0f, 0f), float9));
					float4 tangent = new float4(xyz, 1f);
					int num3 = triangleCounter.Increment() * 3;
					vertexData[num3] = new MeshVertexData(float5, float9, tangent, float8, new float4(1f, 0f, 0f, 0f));
					triangleData[num3] = (ushort)num3;
					vertexData[num3 + 1] = new MeshVertexData(float6, float9, tangent, float8, new float4(0f, 1f, 0f, 0f));
					triangleData[num3 + 1] = (ushort)(num3 + 1);
					vertexData[num3 + 2] = new MeshVertexData(float7, float9, tangent, float8, new float4(0f, 0f, 1f, 0f));
					triangleData[num3 + 2] = (ushort)(num3 + 2);
				}
			}
			nativeArray.Dispose();
			nativeArray2.Dispose();
			nativeArray3.Dispose();
		}

		private byte GetMaterialValue(int3 pos)
		{
			return materials[pos.x + dimension * (pos.y + pos.z * dimension)];
		}

		private byte GetVoxelValue(int3 pos)
		{
			if (pos.x < 0 || pos.y < 0 || pos.z < 0 || pos.x > chunkSize || pos.y > chunkSize || pos.z > chunkSize)
			{
				return 0;
			}
			int index = pos.x + dimension * (pos.y + pos.z * dimension);
			return voxels[index];
		}
	}
	public struct MeshVertexData(float3 position, float3 normal, float4 tangent, float4 materials, float4 blend)
	{
		public float3 position = position;

		public float3 normal = normal;

		public float4 tangent = tangent;

		public float4 materials = materials;

		public float4 blend = blend;

		public static readonly VertexAttributeDescriptor[] VertexBufferMemoryLayout = new VertexAttributeDescriptor[5]
		{
			new VertexAttributeDescriptor(VertexAttribute.Position, VertexAttributeFormat.Float32, 3, 0),
			new VertexAttributeDescriptor(VertexAttribute.Normal),
			new VertexAttributeDescriptor(VertexAttribute.Tangent, VertexAttributeFormat.Float32, 4),
			new VertexAttributeDescriptor(VertexAttribute.TexCoord1, VertexAttributeFormat.Float32, 4),
			new VertexAttributeDescriptor(VertexAttribute.TexCoord2, VertexAttributeFormat.Float32, 4)
		};

		public override string ToString()
		{
			return $"({position:F2} x {normal:F2})";
		}
	}
	public struct NativeCounter : IDisposable
	{
		private readonly Unity.Collections.Allocator _allocator;

		[NativeDisableUnsafePtrRestriction]
		private unsafe readonly int* _counter;

		public unsafe int Count
		{
			get
			{
				return *_counter;
			}
			set
			{
				*_counter = value;
			}
		}

		public unsafe NativeCounter(Unity.Collections.Allocator allocator)
		{
			_allocator = allocator;
			_counter = (int*)UnsafeUtility.Malloc(4L, 4, _allocator);
			Count = 0;
		}

		public unsafe int Increment()
		{
			return Interlocked.Increment(ref *_counter) - 1;
		}

		public unsafe void Dispose()
		{
			UnsafeUtility.Free(_counter, _allocator);
		}
	}
	[BurstCompile]
	public struct SortChunksJob : IJob
	{
		private struct SortKey(ulong val) : IComparable<SortKey>
		{
			public ulong value = val;

			public int CompareTo(SortKey other)
			{
				return value.CompareTo(other.value);
			}
		}

		[Unity.Collections.ReadOnly]
		public NativeHashSet<int3> ChunkSet;

		[Unity.Collections.ReadOnly]
		public int3 TargetPos;

		public NativeList<int3> SortedChunks;

		public void Execute()
		{
			int count = ChunkSet.Count;
			SortedChunks.ResizeUninitialized(count);
			NativeArray<int3> nativeArray = new NativeArray<int3>(count, Unity.Collections.Allocator.Temp);
			int num = 0;
			foreach (int3 item in ChunkSet)
			{
				nativeArray[num++] = item;
			}
			NativeArray<SortKey> array = new NativeArray<SortKey>(count, Unity.Collections.Allocator.Temp);
			for (int i = 0; i < count; i++)
			{
				uint num2 = (uint)math.distancesq(nativeArray[i], TargetPos);
				array[i] = new SortKey(((ulong)num2 << 32) | (uint)i);
			}
			array.Sort();
			for (int j = 0; j < count; j++)
			{
				int index = (int)(array[j].value & 0xFFFFFFFFu);
				SortedChunks[j] = nativeArray[index];
			}
			array.Dispose();
			nativeArray.Dispose();
		}
	}
	public class StayOutsideOfGeo : MonoBehaviour
	{
		[SerializeField]
		private Transform _target;

		[SerializeField]
		private UnityEngine.Vector3 _targetOffset = UnityEngine.Vector3.zero;

		[SerializeField]
		private float _threshold = 0.4f;

		[SerializeField]
		private bool _pauseOnPenetration = true;

		[SerializeField]
		private Collider _disableOnMove;

		private VoxelWorld _voxelWorld;

		private List<int3> _positionHistory = new List<int3>();

		private int _maxHistorySize = 10;

		private int _historyIndex;

		private float _maxDensity;

		private float _minDensity;

		private void Reset()
		{
			_target = base.transform;
		}

		private void Start()
		{
			if ((object)_target == null)
			{
				_target = base.transform;
			}
			_voxelWorld = VoxelWorld.GetFor(base.gameObject);
			if (_voxelWorld == null)
			{
				UnityEngine.Debug.LogError("VoxelWorld not found in the scene. Please ensure there is a VoxelWorld component present.");
				base.enabled = false;
			}
		}

		private void Update()
		{
			int3 voxelForWorldPosition = _voxelWorld.GetVoxelForWorldPosition(_target.position + _targetOffset);
			if (TestPosition(voxelForWorldPosition).match)
			{
				AddPositionToHistory(voxelForWorldPosition);
				return;
			}
			if (ResolvePenetration(voxelForWorldPosition))
			{
				UnityEngine.Debug.Log($"Successfully resolved penetration for {_target.name} at position {voxelForWorldPosition}", this);
				return;
			}
			for (int i = 10; i < 100; i += 10)
			{
				for (int j = 0; j < 10; j++)
				{
					int x = voxelForWorldPosition.x + UnityEngine.Random.Range(-i, i);
					int y = voxelForWorldPosition.y + UnityEngine.Random.Range(-i, i);
					int z = voxelForWorldPosition.z + UnityEngine.Random.Range(-i, i);
					int3 int5 = new int3(x, y, z);
					if (IsOutsideGeo(int5))
					{
						UnityEngine.Debug.Log($"Found valid random position {int5} outside geo for {_target.name}", this);
						SetPosition(_voxelWorld.GetWorldPosition(int5));
						return;
					}
				}
			}
		}

		private bool ResolvePenetration(int3 pos)
		{
			UnityEngine.Debug.LogWarning($"{base.name} inside geo in {_voxelWorld.GetChunkForLocalPosition(pos)} [{_target.position.RoundToInt()}={_voxelWorld.GetVoxelForWorldPosition(_target.position)}->{_maxDensity:F2}]", this);
			for (int i = 0; i < _positionHistory.Count; i++)
			{
				int3 int5 = PopMostRecentPosition();
				if (!int5.Equals(int3.zero))
				{
					(bool, int3) tuple = TestPosition(int5, useThreshold: false);
					if (tuple.Item1)
					{
						UnityEngine.Debug.Log($"Found valid position {tuple.Item2} near recent position {int5} at index {i}");
						SetPosition(_voxelWorld.GetWorldPosition(tuple.Item2));
						return true;
					}
				}
			}
			return false;
		}

		private void SetPosition(UnityEngine.Vector3 worldPosition)
		{
			UnityEngine.Debug.Log($"Moving {_target} from {_target.position} to {worldPosition}", this);
			UnityEngine.Debug.DrawLine(_target.position, worldPosition, Color.red, 5f);
			if ((bool)_disableOnMove)
			{
				_disableOnMove.enabled = false;
			}
			_target.position = worldPosition;
			if ((bool)_disableOnMove)
			{
				_disableOnMove.enabled = true;
			}
		}

		private (bool match, int3 position) TestPosition(int3 position, bool useThreshold = true)
		{
			float a = _voxelWorld.GetDensityAt(position, 0).ToFloat();
			_maxDensity = Mathf.Max(a, float.MinValue);
			_minDensity = Mathf.Min(a, float.MaxValue);
			float num = (useThreshold ? _threshold : 0f);
			if (_voxelWorld.GetDensityAt(position, 0).ToFloat() < num)
			{
				for (int i = position.x - 1; i <= position.x + 1; i++)
				{
					for (int j = position.y - 1; j <= position.y + 1; j++)
					{
						for (int k = position.z - 1; k <= position.z + 1; k++)
						{
							a = _voxelWorld.GetDensityAt(new int3(i, j, k), 0).ToFloat();
							_maxDensity = Mathf.Max(a, _maxDensity);
							_minDensity = Mathf.Min(a, _minDensity);
							if (a < 0f)
							{
								return (match: true, position: new int3(i, j, k));
							}
						}
					}
				}
			}
			return (match: false, position: position);
		}

		private bool IsOutsideGeo(int3 position)
		{
			return _voxelWorld.GetDensityAt(position, 0).ToFloat() < 0f;
		}

		private void AddPositionToHistory(int3 position)
		{
			if (!_positionHistory.Contains(position))
			{
				if (_positionHistory.Count >= _maxHistorySize)
				{
					_positionHistory[_historyIndex] = position;
				}
				else
				{
					_positionHistory.Add(position);
				}
				_historyIndex = (_historyIndex + 1) % _maxHistorySize;
			}
		}

		private int3 GetMostRecentPosition()
		{
			if (_positionHistory.Count == 0)
			{
				return int3.zero;
			}
			return _positionHistory[(_historyIndex - 1 + _positionHistory.Count) % _positionHistory.Count];
		}

		private int3 PopMostRecentPosition()
		{
			if (_positionHistory.Count == 0)
			{
				return int3.zero;
			}
			_historyIndex = (_historyIndex - 1 + _maxHistorySize) % _maxHistorySize;
			return _positionHistory[_historyIndex];
		}
	}
