		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private static int3 Sort3(int a, int b, int c)
		{
			if (a > b)
			{
				int num = a;
				a = b;
				b = num;
			}
			if (b > c)
			{
				int num2 = b;
				b = c;
				c = num2;
			}
			if (a > b)
			{
				int num3 = a;
				a = b;
				b = num3;
			}
			return new int3(a, b, c);
		}

		private static int4 MakeMatSet(byte m0, byte m1, byte m2)
		{
