		Bits3 = 3,
		Bits4 = 4,
		Bits5 = 5,
		Bits6 = 6,
		Bits7 = 7,
		Bits8 = 8,
		Bits9 = 9,
		Bits10 = 10,
		Bits12 = 12,
		Bits14 = 14,
