	[Serializable]
	public class LiteFloatCrusher : LiteCrusher<float>
	{
		[SerializeField]
		protected float min;

		[SerializeField]
		protected float max;

		[SerializeField]
		public LiteFloatCompressType compressType = LiteFloatCompressType.Half16;

		[SerializeField]
		private bool accurateCenter = true;

		[SerializeField]
		private float encoder;

		[SerializeField]
		private float decoder;

		[SerializeField]
		private ulong maxCVal;

		public LiteFloatCrusher()
		{
			compressType = LiteFloatCompressType.Half16;
			min = 0f;
			max = 1f;
			accurateCenter = true;
			Recalculate(compressType, min, max, accurateCenter, ref bits, ref encoder, ref decoder, ref maxCVal);
		}

		public LiteFloatCrusher(LiteFloatCompressType compressType, float min, float max, bool accurateCenter)
		{
			this.compressType = compressType;
			this.min = min;
			this.max = max;
			this.accurateCenter = accurateCenter;
			Recalculate(compressType, min, max, accurateCenter, ref bits, ref encoder, ref decoder, ref maxCVal);
		}

		public static void Recalculate(LiteFloatCompressType compressType, float min, float max, bool accurateCenter, ref int bits, ref float encoder, ref float decoder, ref ulong maxCVal)
		{
			bits = (int)compressType;
			float num = max - min;
			ulong num2 = (ulong)((bits == 64) ? (-1) : ((1L << bits) - 1));
			if (accurateCenter && num2 != 0L)
			{
				num2--;
			}
			encoder = ((num == 0f) ? 0f : ((float)num2 / num));
			decoder = ((num2 == 0L) ? 0f : (num / (float)num2));
			maxCVal = num2;
		}

		public override ulong Encode(float val)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return HalfUtilities.Pack(val);
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return ((emotitron.Compression.Utilities.ByteConverter)val).uint32;
			}
			float num = (val - min) * encoder + 0.5f;
			if (num < 0f)
			{
				return 0uL;
			}
			ulong num2 = (ulong)num;
			if (num2 <= maxCVal)
			{
				return num2;
			}
			return maxCVal;
		}

		public override float Decode(uint cval)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return HalfUtilities.Unpack((ushort)cval);
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return ((emotitron.Compression.Utilities.ByteConverter)cval).float32;
			}
			if (cval == 0)
			{
				return min;
			}
			if (cval == maxCVal)
			{
				return max;
			}
			return (float)cval * decoder + min;
		}

		public override ulong WriteValue(float val, byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				ulong num = HalfUtilities.Pack(val);
				buffer.Write(num, ref bitposition, 16);
				return num;
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				ulong num2 = ((emotitron.Compression.Utilities.ByteConverter)val).uint32;
				buffer.Write(num2, ref bitposition, 32);
				return num2;
			}
			ulong num3 = Encode(val);
			buffer.Write(num3, ref bitposition, (int)compressType);
			return num3;
		}

		public override void WriteCValue(uint cval, byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				buffer.Write(cval, ref bitposition, 16);
			}
			else if (compressType == LiteFloatCompressType.Full32)
			{
				buffer.Write(cval, ref bitposition, 32);
			}
			else
			{
				buffer.Write(cval, ref bitposition, (int)compressType);
			}
		}

		public override float ReadValue(byte[] buffer, ref int bitposition)
		{
			if (compressType == LiteFloatCompressType.Half16)
			{
				return HalfUtilities.Unpack((ushort)buffer.Read(ref bitposition, 16));
			}
			if (compressType == LiteFloatCompressType.Full32)
			{
				return ((emotitron.Compression.Utilities.ByteConverter)(uint)buffer.Read(ref bitposition, 32)).float32;
			}
			uint val = (uint)buffer.Read(ref bitposition, (int)compressType);
			return Decode(val);
		}

		public override string ToString()
		{
			return GetType().Name + " " + compressType.ToString() + " mn: " + min + " mx: " + max + " e: " + encoder + " d: " + decoder;
		}
	}
	public enum LiteIntCompressType
	{
		PackSigned,
		PackUnsigned,
		Range
	}
	[Serializable]
	public class LiteIntCrusher : LiteCrusher<int>
	{
		[SerializeField]
		public LiteIntCompressType compressType;

		[SerializeField]
		protected int min;

		[SerializeField]
		protected int max;

		[SerializeField]
		private int smallest;

		[SerializeField]
		private int biggest;

		public LiteIntCrusher()
		{
			compressType = LiteIntCompressType.PackSigned;
			min = -128;
			max = 127;
			if (compressType == LiteIntCompressType.Range)
			{
				Recalculate(min, max, ref smallest, ref biggest, ref bits);
			}
		}

		public LiteIntCrusher(LiteIntCompressType comType = LiteIntCompressType.PackSigned, int min = -128, int max = 127)
		{
			compressType = comType;
			this.min = min;
			this.max = max;
			if (compressType == LiteIntCompressType.Range)
			{
				Recalculate(min, max, ref smallest, ref biggest, ref bits);
			}
		}

		public override ulong WriteValue(int val, byte[] buffer, ref int bitposition)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackUnsigned:
				buffer.WritePackedBytes((uint)val, ref bitposition, 32);
				return (uint)val;
			case LiteIntCompressType.PackSigned:
			{
				uint num2 = (uint)((val << 1) ^ (val >> 31));
				buffer.WritePackedBytes(num2, ref bitposition, 32);
				return num2;
			}
			case LiteIntCompressType.Range:
			{
				ulong num = Encode(val);
				buffer.Write(num, ref bitposition, bits);
				return num;
			}
			default:
				return 0uL;
			}
		}

		public override void WriteCValue(uint cval, byte[] buffer, ref int bitposition)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackUnsigned:
				buffer.WritePackedBytes(cval, ref bitposition, 32);
				break;
			case LiteIntCompressType.PackSigned:
				buffer.WritePackedBytes(cval, ref bitposition, 32);
				break;
			case LiteIntCompressType.Range:
				buffer.Write(cval, ref bitposition, bits);
				break;
			}
		}

		public override int ReadValue(byte[] buffer, ref int bitposition)
		{
			switch (compressType)
			{
			case LiteIntCompressType.PackUnsigned:
				return (int)buffer.ReadPackedBytes(ref bitposition, 32);
			case LiteIntCompressType.PackSigned:
				return buffer.ReadSignedPackedBytes(ref bitposition, 32);
			case LiteIntCompressType.Range:
			{
				uint val = (uint)buffer.Read(ref bitposition, bits);
				return Decode(val);
			}
			default:
				return 0;
			}
		}

		public override ulong Encode(int value)
		{
			value = ((value > biggest) ? biggest : ((value < smallest) ? smallest : value));
			return (ulong)(value - smallest);
		}

		public override int Decode(uint cvalue)
		{
			return (int)(cvalue + smallest);
		}

		public static void Recalculate(int min, int max, ref int smallest, ref int biggest, ref int bits)
		{
			if (min < max)
			{
				smallest = min;
				biggest = max;
			}
			else
			{
				smallest = max;
				biggest = min;
			}
			int maxvalue = biggest - smallest;
			bits = LiteCrusher.GetBitsForMaxValue((uint)maxvalue);
		}

		public override string ToString()
		{
			return GetType().Name + " " + compressType.ToString() + " mn: " + min + " mx: " + max + " sm: " + smallest;
		}
	}
	public static class ZigZagExt
	{
		public static ulong ZigZag(this long s)
		{
			return (ulong)((s << 1) ^ (s >> 63));
		}

		public static long UnZigZag(this ulong u)
		{
			return (long)((u >> 1) ^ (0L - (u & 1)));
		}

		public static uint ZigZag(this int s)
		{
			return (uint)((s << 1) ^ (s >> 31));
		}

		public static int UnZigZag(this uint u)
		{
			return (int)((u >> 1) ^ (int)(0 - (u & 1)));
		}

		public static ushort ZigZag(this short s)
		{
			return (ushort)((s << 1) ^ (s >> 15));
		}

		public static short UnZigZag(this ushort u)
		{
			return (short)((u >> 1) ^ -(short)(u & 1));
		}

		public static byte ZigZag(this sbyte s)
		{
			return (byte)((s << 1) ^ (s >> 7));
		}

		public static sbyte UnZigZag(this byte u)
		{
			return (sbyte)((u >> 1) ^ -(sbyte)(u & 1));
		}
	}
