	public static class HalfUtilities
	{
		[StructLayout(LayoutKind.Explicit)]
		private struct FloatToUint
		{
			[FieldOffset(0)]
			public uint uintValue;

			[FieldOffset(0)]
			public float floatValue;
		}

		private static readonly uint[] HalfToFloatMantissaTable;

		private static readonly uint[] HalfToFloatExponentTable;

		private static readonly uint[] HalfToFloatOffsetTable;

		private static readonly ushort[] FloatToHalfBaseTable;

		private static readonly byte[] FloatToHalfShiftTable;

		static HalfUtilities()
		{
			HalfToFloatMantissaTable = new uint[2048];
			HalfToFloatExponentTable = new uint[64];
			HalfToFloatOffsetTable = new uint[64];
			FloatToHalfBaseTable = new ushort[512];
			FloatToHalfShiftTable = new byte[512];
			HalfToFloatMantissaTable[0] = 0u;
			for (int i = 1; i < 1024; i++)
			{
				uint num = (uint)(i << 13);
				uint num2 = 0u;
				while ((num & 0x800000) == 0)
				{
					num2 -= 8388608;
					num <<= 1;
				}
				num &= 0xFF7FFFFFu;
				num2 += 947912704;
				HalfToFloatMantissaTable[i] = num | num2;
			}
			for (int i = 1024; i < 2048; i++)
			{
				HalfToFloatMantissaTable[i] = (uint)(939524096 + (i - 1024 << 13));
			}
			HalfToFloatExponentTable[0] = 0u;
			for (int i = 1; i < 63; i++)
			{
				if (i < 31)
				{
					HalfToFloatExponentTable[i] = (uint)(i << 23);
				}
				else
				{
					HalfToFloatExponentTable[i] = (uint)(int.MinValue + (i - 32 << 23));
				}
			}
			HalfToFloatExponentTable[31] = 1199570944u;
			HalfToFloatExponentTable[32] = 2147483648u;
			HalfToFloatExponentTable[63] = 3347054592u;
			HalfToFloatOffsetTable[0] = 0u;
			for (int i = 1; i < 64; i++)
			{
				HalfToFloatOffsetTable[i] = 1024u;
			}
			HalfToFloatOffsetTable[32] = 0u;
			for (int i = 0; i < 256; i++)
			{
				int num3 = i - 127;
				if (num3 < -24)
				{
					FloatToHalfBaseTable[i | 0] = 0;
					FloatToHalfBaseTable[i | 0x100] = 32768;
					FloatToHalfShiftTable[i | 0] = 24;
					FloatToHalfShiftTable[i | 0x100] = 24;
				}
				else if (num3 < -14)
				{
					FloatToHalfBaseTable[i | 0] = (ushort)(1024 >> -num3 - 14);
					FloatToHalfBaseTable[i | 0x100] = (ushort)((1024 >> -num3 - 14) | 0x8000);
					FloatToHalfShiftTable[i | 0] = (byte)(-num3 - 1);
					FloatToHalfShiftTable[i | 0x100] = (byte)(-num3 - 1);
				}
				else if (num3 <= 15)
				{
					FloatToHalfBaseTable[i | 0] = (ushort)(num3 + 15 << 10);
					FloatToHalfBaseTable[i | 0x100] = (ushort)((num3 + 15 << 10) | 0x8000);
					FloatToHalfShiftTable[i | 0] = 13;
					FloatToHalfShiftTable[i | 0x100] = 13;
				}
				else if (num3 < 128)
				{
					FloatToHalfBaseTable[i | 0] = 31744;
					FloatToHalfBaseTable[i | 0x100] = 64512;
					FloatToHalfShiftTable[i | 0] = 24;
					FloatToHalfShiftTable[i | 0x100] = 24;
				}
				else
				{
					FloatToHalfBaseTable[i | 0] = 31744;
					FloatToHalfBaseTable[i | 0x100] = 64512;
					FloatToHalfShiftTable[i | 0] = 13;
					FloatToHalfShiftTable[i | 0x100] = 13;
				}
			}
		}

		public static float Unpack(ushort value)
		{
			FloatToUint floatToUint = new FloatToUint
			{
				uintValue = HalfToFloatMantissaTable[(int)HalfToFloatOffsetTable[value >> 10] + (value & 0x3FF)] + HalfToFloatExponentTable[value >> 10]
			};
			return floatToUint.floatValue;
		}

		public static ushort Pack(float value)
		{
			FloatToUint floatToUint = new FloatToUint
			{
				floatValue = value
			};
			return (ushort)(FloatToHalfBaseTable[(floatToUint.uintValue >> 23) & 0x1FF] + ((floatToUint.uintValue & 0x7FFFFF) >> (int)FloatToHalfShiftTable[(floatToUint.uintValue >> 23) & 0x1FF]));
		}
	}
}
namespace emotitron.CompressionTests
{
	public class BenchmarkTests : MonoBehaviour
	{
		public const int BYTE_CNT = 128;

		public const int LOOP = 1000000;

		public static byte[] buffer = new byte[4800];

		public static uint[] ibuffer = new uint[128];

		public static ulong[] ubuffer = new ulong[128];

		public static ulong[] ubuffer2 = new ulong[128];

		private void Start()
		{
			TestWriterIntegrity();
			ArrayCopy();
			ArrayCopySafe();
		}

		public static void TestWriterIntegrity()
		{
			int bitposition = 1;
			int bitposition2 = 1;
			ubuffer.Write(ulong.MaxValue, ref bitposition, 64);
			if (ubuffer.Read(ref bitposition2, 64) != ulong.MaxValue)
			{
				UnityEngine.Debug.Log("Error writing with maxulong");
			}
			for (int i = 0; i < 3000; i++)
			{
				bitposition = UnityEngine.Random.Range(0, 200);
				bitposition2 = bitposition;
				int num = bitposition;
				int num2 = UnityEngine.Random.Range(1, 64);
				int num3 = UnityEngine.Random.Range(-(1 << num2 - 1), (1 << num2 - 1) - 1);
				ubuffer.WriteSigned(num3, ref bitposition, num2);
				ubuffer.WriteSigned(num3, ref bitposition, num2);
				ubuffer.WriteSigned(num3, ref bitposition, num2);
				if (ubuffer.ReadSigned(ref bitposition2, num2) != num3)
				{
					UnityEngine.Debug.Log("Error writing " + num3 + " to pos " + num + " with size " + num2);
				}
				if (ubuffer.ReadSigned(ref bitposition2, num2) != num3)
				{
					UnityEngine.Debug.Log("Error writing " + num3 + " to pos " + num + " with size " + num2);
				}
				if (ubuffer.ReadSigned(ref bitposition2, num2) != num3)
				{
					UnityEngine.Debug.Log("Error writing " + num3 + " to pos " + num + " with size " + num2);
				}
				ulong num4 = (ulong)UnityEngine.Random.Range(0f, (ulong)((1L << num2) - 1));
				ubuffer.Write(num4, ref bitposition, num2);
				ubuffer.Write(num4, ref bitposition, num2);
				ubuffer.Write(num4, ref bitposition, num2);
				if (ubuffer.Read(ref bitposition2, num2) != num4)
				{
					UnityEngine.Debug.Log("Error writing " + num4 + " to pos " + num + " with size " + num2);
				}
				if (ubuffer.Read(ref bitposition2, num2) != num4)
				{
					UnityEngine.Debug.Log("Error writing " + num4 + " to pos " + num + " with size " + num2);
				}
				if (ubuffer.Read(ref bitposition2, num2) != num4)
				{
					UnityEngine.Debug.Log("Error writing " + num4 + " to pos " + num + " with size " + num2);
				}
			}
			UnityEngine.Debug.Log("Integrity check complete.");
		}

		private static void TestLog2()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (uint num = 0u; num <= uint.MaxValue; num += 3000)
			{
				num.UsedBitCount();
				num.UsedBitCount();
				num.UsedBitCount();
				num.UsedBitCount();
				num.UsedBitCount();
				if ((uint)(-1 - (int)num) < 4000u)
				{
					break;
				}
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Log2 nifty: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}

		private static void ArrayCopy()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (int i = 0; i < 1000000; i++)
			{
				int targetPos = 0;
				ubuffer.ReadOutUnsafe(0, buffer, ref targetPos, 960);
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Array Copy Unsafe: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}

		private static void ArrayCopySafe()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (int i = 0; i < 1000000; i++)
			{
				int bitposition = 0;
				ubuffer.ReadOutSafe(0, buffer, ref bitposition, 960);
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Array Copy Safe: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}

		public static void ByteForByteWrite()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (int i = 0; i < 1000000; i++)
			{
				BasicWriter.Reset();
				for (int j = 0; j < 128; j++)
				{
					BasicWriter.BasicWrite(buffer, byte.MaxValue);
				}
				BasicWriter.Reset();
				for (int k = 0; k < 128; k++)
				{
					BasicWriter.BasicRead(buffer);
				}
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Byte For Byte: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}

		public static void BitpackBytesEven()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (int i = 0; i < 1000000; i++)
			{
				int bitposition = 0;
				for (int j = 0; j < 128; j++)
				{
					buffer.Write(255uL, ref bitposition, 8);
				}
				bitposition = 0;
				for (int k = 0; k < 127; k++)
				{
					buffer.Read(ref bitposition, 8);
				}
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Even Bitpack byte: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}

		public static void BitpackBytesToULongUneven()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (int i = 0; i < 1000000; i++)
			{
				int bitposition = 0;
				ubuffer.Write(1uL, ref bitposition, 1);
				for (int j = 0; j < 127; j++)
				{
					ubuffer.Write(255uL, ref bitposition, 33);
				}
				bitposition = 0;
				ubuffer.Read(ref bitposition, 1);
				for (int k = 0; k < 127; k++)
				{
					ubuffer.Read(ref bitposition, 33);
				}
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Uneven Bitpack ulong[]: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}

		public static void BitpackBytesUnEven()
		{
			Stopwatch stopwatch = Stopwatch.StartNew();
			for (int i = 0; i < 1000000; i++)
			{
				int bitposition = 0;
				buffer.Write(1uL, ref bitposition, 1);
				for (int j = 0; j < 127; j++)
				{
					buffer.Write(255uL, ref bitposition, 8);
				}
				bitposition = 0;
				buffer.Read(ref bitposition, 1);
				for (int k = 0; k < 127; k++)
				{
					buffer.Read(ref bitposition, 8);
				}
			}
			stopwatch.Stop();
			UnityEngine.Debug.Log("Uneven Bitpack byte: time=" + stopwatch.ElapsedMilliseconds + " ms");
		}
	}
	public class BasicWriter
	{
		public static int pos;

		public static void Reset()
		{
			pos = 0;
		}

		public static byte[] BasicWrite(byte[] buffer, byte value)
		{
			buffer[pos] = value;
			pos++;
			return buffer;
		}

		public static byte BasicRead(byte[] buffer)
		{
			byte result = buffer[pos];
			pos++;
			return result;
		}
	}
