		public static void DrawArc(UnityEngine.Vector3 center, UnityEngine.Vector3 from, UnityEngine.Vector3 normal, float angle, float radius, int numSegments, Color color, bool depthTest = true)
		{
			if (numSegments > 0)
			{
				from.Normalize();
				from *= radius;
				UnityEngine.Vector3[] array = new UnityEngine.Vector3[numSegments + 1];
				array[0] = center + from;
				float num = 1f / (float)numSegments;
				UnityEngine.Quaternion quaternion2 = QuaternionUtil.AxisAngle(normal, angle * num);
				UnityEngine.Vector3 vector = quaternion2 * from;
				for (int i = 1; i <= numSegments; i++)
				{
					array[i] = center + vector;
					vector = quaternion2 * vector;
				}
				DrawLineStrip(array, color, depthTest);
			}
		}

		public static void DrawLocator(UnityEngine.Vector3 position, UnityEngine.Vector3 right, UnityEngine.Vector3 up, UnityEngine.Vector3 forward, Color rightColor, Color upColor, Color forwardColor, float size = 0.5f)
		{
			DrawLine(position, position + right * size, rightColor);
			DrawLine(position, position + up * size, upColor);
			DrawLine(position, position + forward * size, forwardColor);
		}

		public static void DrawLocator(UnityEngine.Vector3 position, UnityEngine.Vector3 right, UnityEngine.Vector3 up, UnityEngine.Vector3 forward, float size = 0.5f)
		{
