		}

		public static void DrawLocator(UnityEngine.Vector3 position, UnityEngine.Quaternion rotation, Color rightColor, Color upColor, Color forwardColor, float size = 0.5f)
		{
			UnityEngine.Vector3 right = rotation * UnityEngine.Vector3.right;
			UnityEngine.Vector3 up = rotation * UnityEngine.Vector3.up;
			UnityEngine.Vector3 forward = rotation * UnityEngine.Vector3.forward;
			DrawLocator(position, right, up, forward, rightColor, upColor, forwardColor, size);
		}

