			if (!(dimensions.x < MathUtil.Epsilon) && !(dimensions.y < MathUtil.Epsilon) && !(dimensions.z < MathUtil.Epsilon))
			{
				Mesh mesh = null;
				switch (style)
				{
				case Style.Wireframe:
					mesh = PrimitiveMeshFactory.BoxWireframe();
					break;
				case Style.SolidColor:
