		public static void DrawCylinder(UnityEngine.Vector3 point0, UnityEngine.Vector3 point1, float radius, int numSegments, Color color, bool depthTest = true, Style style = Style.Wireframe)
		{
			UnityEngine.Vector3 vector = point1 - point0;
			float magnitude = vector.magnitude;
			if (!(magnitude < MathUtil.Epsilon))
			{
				vector.Normalize();
				UnityEngine.Vector3 center = 0.5f * (point0 + point1);
				UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.Normalize(UnityEngine.Vector3.Cross((Mathf.Abs(UnityEngine.Vector3.Dot(vector.normalized, UnityEngine.Vector3.up)) < 0.5f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.forward, vector)), vector);
				DrawCylinder(center, rotation, magnitude, radius, numSegments, color, depthTest, style);
			}
		}

