		public static void DrawSphereTripleCircles(UnityEngine.Vector3 center, UnityEngine.Quaternion rotation, float radius, int numSegments, Color color, bool depthTest = true, Style style = Style.Wireframe)
		{
			UnityEngine.Vector3 normal = rotation * UnityEngine.Vector3.right;
			UnityEngine.Vector3 normal2 = rotation * UnityEngine.Vector3.up;
			UnityEngine.Vector3 normal3 = rotation * UnityEngine.Vector3.forward;
			DrawCircle(center, normal, radius, numSegments, color, depthTest, style);
			DrawCircle(center, normal2, radius, numSegments, color, depthTest, style);
			DrawCircle(center, normal3, radius, numSegments, color, depthTest, style);
		}

