				UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.Normalize(UnityEngine.Vector3.Cross((Mathf.Abs(UnityEngine.Vector3.Dot(vector, UnityEngine.Vector3.up)) < 0.5f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.forward, vector)), vector);
