		public static void DrawArrow(UnityEngine.Vector3 from, UnityEngine.Vector3 to, float coneRadius, float coneHeight, int numSegments, float stemThickness, Color color, bool depthTest = true, Style style = Style.Wireframe)
		{
			UnityEngine.Vector3 vector = to - from;
			float magnitude = vector.magnitude;
			if (magnitude < MathUtil.Epsilon)
			{
				return;
			}
			vector.Normalize();
			UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.Normalize(UnityEngine.Vector3.Cross((Mathf.Abs(UnityEngine.Vector3.Dot(vector, UnityEngine.Vector3.up)) < 0.5f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.forward, vector)), vector);
			DrawCone(to - coneHeight * vector, rotation, coneHeight, coneRadius, numSegments, color, depthTest, style);
			if (stemThickness <= 0f)
			{
				if (style == Style.Wireframe)
				{
					to -= coneHeight * vector;
				}
				DrawLine(from, to, color, depthTest);
			}
			else if (coneHeight < magnitude)
			{
				to -= coneHeight * vector;
				DrawCylinder(from, to, 0.5f * stemThickness, numSegments, color, depthTest, style);
			}
		}

		public static void DrawArrow(UnityEngine.Vector3 from, UnityEngine.Vector3 to, float size, Color color, bool depthTest = true, Style style = Style.Wireframe)
		{
			DrawArrow(from, to, 0.5f * size, size, 8, 0f, color, depthTest, style);
		}
	}
	public class GizmosUtil
	{
		public enum Style
		{
			Wireframe,
			FlatShaded,
			SmoothShaded
		}

		public static void DrawLine(UnityEngine.Vector3 v0, UnityEngine.Vector3 v1, Color color)
		{
			Gizmos.color = color;
			Gizmos.DrawLine(v0, v1);
		}

		public static void DrawLines(UnityEngine.Vector3[] aVert, Color color)
		{
			Gizmos.color = color;
			for (int i = 0; i < aVert.Length; i += 2)
			{
				Gizmos.DrawLine(aVert[i], aVert[i + 1]);
			}
		}

		public static void DrawLineStrip(UnityEngine.Vector3[] aVert, Color color)
		{
			Gizmos.color = color;
			for (int i = 0; i < aVert.Length; i++)
			{
				Gizmos.DrawLine(aVert[i], aVert[i + 1]);
			}
		}

		public static void DrawBox(UnityEngine.Vector3 center, UnityEngine.Quaternion rotation, UnityEngine.Vector3 dimensions, Color color, Style style = Style.FlatShaded)
		{
			if (dimensions.x < MathUtil.Epsilon || dimensions.y < MathUtil.Epsilon || dimensions.z < MathUtil.Epsilon)
			{
				return;
			}
			Mesh mesh = null;
			switch (style)
			{
