		public static void DrawCapsule(UnityEngine.Vector3 center, UnityEngine.Quaternion rotation, float height, float radius, int latSegmentsPerCap, int longSegmentsPerCap, Color color, Style style = Style.SmoothShaded)
		{
			if (height < MathUtil.Epsilon || radius < MathUtil.Epsilon)
			{
				return;
			}
			Mesh mesh = null;
			Mesh mesh2 = null;
			switch (style)
			{
			case Style.Wireframe:
				mesh = PrimitiveMeshFactory.CapsuleWireframe(latSegmentsPerCap, longSegmentsPerCap, caps: true, topCapOnly: true, sides: false);
				mesh2 = PrimitiveMeshFactory.CapsuleWireframe(latSegmentsPerCap, longSegmentsPerCap, caps: false);
				break;
			case Style.FlatShaded:
				mesh = PrimitiveMeshFactory.CapsuleFlatShaded(latSegmentsPerCap, longSegmentsPerCap, caps: true, topCapOnly: true, sides: false);
				mesh2 = PrimitiveMeshFactory.CapsuleFlatShaded(latSegmentsPerCap, longSegmentsPerCap, caps: false);
				break;
			case Style.SmoothShaded:
				mesh = PrimitiveMeshFactory.CapsuleSmoothShaded(latSegmentsPerCap, longSegmentsPerCap, caps: true, topCapOnly: true, sides: false);
				mesh2 = PrimitiveMeshFactory.CapsuleSmoothShaded(latSegmentsPerCap, longSegmentsPerCap, caps: false);
				break;
			}
			if (!(mesh == null) && !(mesh2 == null))
			{
				UnityEngine.Vector3 vector = rotation * UnityEngine.Vector3.up;
				UnityEngine.Vector3 vector2 = 0.5f * (height - radius) * vector;
				UnityEngine.Vector3 position = center + vector2;
				UnityEngine.Vector3 position2 = center - vector2;
				UnityEngine.Quaternion rotation2 = UnityEngine.Quaternion.AngleAxis(180f, vector) * rotation;
				Gizmos.color = color;
				if (style == Style.Wireframe)
				{
					Gizmos.DrawWireMesh(mesh, position, rotation, new UnityEngine.Vector3(radius, radius, radius));
					Gizmos.DrawWireMesh(mesh, position2, rotation2, new UnityEngine.Vector3(0f - radius, 0f - radius, radius));
					Gizmos.DrawWireMesh(mesh2, center, rotation, new UnityEngine.Vector3(radius, height, radius));
				}
				else
				{
					Gizmos.DrawMesh(mesh, position, rotation, new UnityEngine.Vector3(radius, radius, radius));
					Gizmos.DrawMesh(mesh, position2, rotation2, new UnityEngine.Vector3(0f - radius, 0f - radius, radius));
					Gizmos.DrawMesh(mesh2, center, rotation, new UnityEngine.Vector3(radius, height, radius));
				}
			}
		}

