			float magnitude = vector.magnitude;
			if (!(magnitude < MathUtil.Epsilon))
			{
				vector.Normalize();
				UnityEngine.Vector3 center = 0.5f * (point0 + point1);
				UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.Normalize(UnityEngine.Vector3.Cross((UnityEngine.Vector3.Dot(vector.normalized, UnityEngine.Vector3.up) < 0.5f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.forward, vector)), vector);
				DrawCapsule(center, rotation, magnitude, radius, latSegmentsPerCap, longSegmentsPerCap, color, style);
			}
		}

		public static void DrawCone(UnityEngine.Vector3 baseCenter, UnityEngine.Quaternion rotation, float height, float radius, int numSegments, Color color, Style style = Style.FlatShaded)
		{
			if (height < MathUtil.Epsilon || radius < MathUtil.Epsilon)
			{
				return;
			}
			Mesh mesh = null;
			switch (style)
			{
			case Style.Wireframe:
				mesh = PrimitiveMeshFactory.ConeWireframe(numSegments);
				break;
			case Style.FlatShaded:
				mesh = PrimitiveMeshFactory.ConeFlatShaded(numSegments);
				break;
			case Style.SmoothShaded:
				mesh = PrimitiveMeshFactory.ConeSmoothShaded(numSegments);
				break;
			}
			if (!(mesh == null))
			{
				Gizmos.color = color;
				if (style == Style.Wireframe)
				{
					Gizmos.DrawWireMesh(mesh, baseCenter, rotation, new UnityEngine.Vector3(radius, height, radius));
				}
				else
				{
					Gizmos.DrawMesh(mesh, baseCenter, rotation, new UnityEngine.Vector3(radius, height, radius));
				}
			}
		}

		public static void DrawCone(UnityEngine.Vector3 baseCenter, UnityEngine.Vector3 top, float radius, int numSegments, Color color, Style style = Style.FlatShaded)
		{
			UnityEngine.Vector3 vector = top - baseCenter;
			float magnitude = vector.magnitude;
			if (!(magnitude < MathUtil.Epsilon))
			{
				vector.Normalize();
				UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.Normalize(UnityEngine.Vector3.Cross((UnityEngine.Vector3.Dot(vector, UnityEngine.Vector3.up) < 0.5f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.forward, vector)), vector);
				DrawCone(baseCenter, rotation, magnitude, radius, numSegments, color, style);
			}
		}

		public static void DrawArrow(UnityEngine.Vector3 from, UnityEngine.Vector3 to, float coneRadius, float coneHeight, int numSegments, float stemThickness, Color color, Style style = Style.FlatShaded)
		{
			UnityEngine.Vector3 vector = to - from;
			float magnitude = vector.magnitude;
			if (magnitude < MathUtil.Epsilon)
			{
				return;
			}
			vector.Normalize();
			UnityEngine.Quaternion rotation = UnityEngine.Quaternion.LookRotation(UnityEngine.Vector3.Normalize(UnityEngine.Vector3.Cross((UnityEngine.Vector3.Dot(vector, UnityEngine.Vector3.up) < 0.5f) ? UnityEngine.Vector3.up : UnityEngine.Vector3.forward, vector)), vector);
			DrawCone(to - coneHeight * vector, rotation, coneHeight, coneRadius, numSegments, color, style);
			if (stemThickness <= 0f)
			{
				if (style != Style.Wireframe)
				{
					to -= coneHeight * vector;
				}
				DrawLine(from, to, color);
			}
			else if (coneHeight < magnitude)
			{
				to -= coneHeight * vector;
				DrawCylinder(from, to, 0.5f * stemThickness, numSegments, color, style);
			}
		}

		public static void DrawArrow(UnityEngine.Vector3 from, UnityEngine.Vector3 to, float size, Color color, Style style = Style.FlatShaded)
		{
			DrawArrow(from, to, 0.5f * size, size, 8, 0f, color, style);
		}
	}
