			{
				VelocityVec = QuaternionUtil.ToVector4(UnityEngine.Quaternion.identity);
				return QuaternionUtil.FromVector4(ValueVec);
			}
			UnityEngine.Vector4 vector = QuaternionUtil.ToVector4(targetValue);
			if (UnityEngine.Vector4.Dot(ValueVec, vector) < 0f)
			{
				vector = -vector;
			}
			UnityEngine.Vector4 vector2 = vector - ValueVec;
			float num = 1f + 2f * deltaTime * dampingRatio * angularFrequency;
			float num2 = angularFrequency * angularFrequency;
			float num3 = deltaTime * num2;
			float num4 = deltaTime * num3;
			float num5 = 1f / (num + num4);
			UnityEngine.Vector4 vector3 = num * ValueVec + deltaTime * VelocityVec + num4 * vector;
			UnityEngine.Vector4 vector4 = VelocityVec + num3 * vector2;
			VelocityVec = vector4 * num5;
			ValueVec = vector3 * num5;
			if (VelocityVec.magnitude < MathUtil.Epsilon && vector2.magnitude < MathUtil.Epsilon)
			{
				VelocityVec = QuaternionUtil.ToVector4(UnityEngine.Quaternion.identity);
