	public class QuaternionUtil
	{
		public enum SterpMode
		{
			Nlerp,
			Slerp
		}

		public static float Magnitude(UnityEngine.Quaternion q)
		{
			return Mathf.Sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w);
		}

		public static float MagnitudeSqr(UnityEngine.Quaternion q)
		{
			return q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w;
		}

		public static UnityEngine.Quaternion Normalize(UnityEngine.Quaternion q)
		{
			float num = 1f / Magnitude(q);
			return new UnityEngine.Quaternion(num * q.x, num * q.y, num * q.z, num * q.w);
		}

		public static UnityEngine.Quaternion AngularVector(UnityEngine.Vector3 v)
		{
			float magnitude = v.magnitude;
			if (magnitude < MathUtil.Epsilon)
			{
				return UnityEngine.Quaternion.identity;
			}
			v /= magnitude;
			float f = 0.5f * magnitude;
			float num = Mathf.Sin(f);
			float w = Mathf.Cos(f);
			return new UnityEngine.Quaternion(num * v.x, num * v.y, num * v.z, w);
		}

		public static UnityEngine.Quaternion AxisAngle(UnityEngine.Vector3 axis, float angle)
		{
			float f = 0.5f * angle;
			float num = Mathf.Sin(f);
			float w = Mathf.Cos(f);
			return new UnityEngine.Quaternion(num * axis.x, num * axis.y, num * axis.z, w);
		}

		public static UnityEngine.Vector3 GetAxis(UnityEngine.Quaternion q)
		{
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(q.x, q.y, q.z);
			float magnitude = vector.magnitude;
			if (magnitude < MathUtil.Epsilon)
			{
				return UnityEngine.Vector3.left;
			}
			return vector / magnitude;
		}

		public static float GetAngle(UnityEngine.Quaternion q)
		{
			return 2f * Mathf.Acos(Mathf.Clamp(q.w, -1f, 1f));
		}

		public static UnityEngine.Quaternion Pow(UnityEngine.Quaternion q, float exp)
		{
			UnityEngine.Vector3 axis = GetAxis(q);
			float angle = GetAngle(q);
			return AxisAngle(axis, angle * exp);
		}

		public static UnityEngine.Quaternion Integrate(UnityEngine.Quaternion q, UnityEngine.Quaternion v, float dt)
		{
			return Pow(v, dt) * q;
		}

		public static UnityEngine.Quaternion Integrate(UnityEngine.Quaternion q, UnityEngine.Vector3 omega, float dt)
		{
			dt *= 0.5f;
			return Normalize(new UnityEngine.Quaternion(omega.x * dt, omega.y * dt, omega.z * dt, 1f) * q);
		}

		public static UnityEngine.Vector4 ToVector4(UnityEngine.Quaternion q)
		{
			return new UnityEngine.Vector4(q.x, q.y, q.z, q.w);
		}

		public static UnityEngine.Quaternion FromVector4(UnityEngine.Vector4 v, bool normalize = true)
		{
			if (normalize)
			{
				float sqrMagnitude = v.sqrMagnitude;
				if (sqrMagnitude < MathUtil.Epsilon)
				{
					return UnityEngine.Quaternion.identity;
				}
				v /= Mathf.Sqrt(sqrMagnitude);
			}
			return new UnityEngine.Quaternion(v.x, v.y, v.z, v.w);
		}

		public static void DecomposeSwingTwist(UnityEngine.Quaternion q, UnityEngine.Vector3 twistAxis, out UnityEngine.Quaternion swing, out UnityEngine.Quaternion twist)
		{
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(q.x, q.y, q.z);
			if (vector.sqrMagnitude < MathUtil.Epsilon)
			{
				UnityEngine.Vector3 vector2 = q * twistAxis;
				UnityEngine.Vector3 axis = UnityEngine.Vector3.Cross(twistAxis, vector2);
				if (axis.sqrMagnitude > MathUtil.Epsilon)
				{
					float angle = UnityEngine.Vector3.Angle(twistAxis, vector2);
					swing = UnityEngine.Quaternion.AngleAxis(angle, axis);
				}
				else
				{
					swing = UnityEngine.Quaternion.identity;
				}
				twist = UnityEngine.Quaternion.AngleAxis(180f, twistAxis);
			}
			else
			{
				UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Project(vector, twistAxis);
				twist = new UnityEngine.Quaternion(vector3.x, vector3.y, vector3.z, q.w);
				twist = Normalize(twist);
				swing = q * UnityEngine.Quaternion.Inverse(twist);
			}
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float t, SterpMode mode = SterpMode.Slerp)
		{
			UnityEngine.Quaternion swing;
			UnityEngine.Quaternion twist;
			return Sterp(a, b, twistAxis, t, out swing, out twist, mode);
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float t, out UnityEngine.Quaternion swing, out UnityEngine.Quaternion twist, SterpMode mode = SterpMode.Slerp)
		{
			return Sterp(a, b, twistAxis, t, t, out swing, out twist, mode);
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float tSwing, float tTwist, SterpMode mode = SterpMode.Slerp)
		{
			UnityEngine.Quaternion swing;
			UnityEngine.Quaternion twist;
			return Sterp(a, b, twistAxis, tSwing, tTwist, out swing, out twist, mode);
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float tSwing, float tTwist, out UnityEngine.Quaternion swing, out UnityEngine.Quaternion twist, SterpMode mode)
		{
			DecomposeSwingTwist(b * UnityEngine.Quaternion.Inverse(a), twistAxis, out var swing2, out var twist2);
			if (mode == SterpMode.Nlerp || mode != SterpMode.Slerp)
			{
				swing = UnityEngine.Quaternion.Lerp(UnityEngine.Quaternion.identity, swing2, tSwing);
				twist = UnityEngine.Quaternion.Lerp(UnityEngine.Quaternion.identity, twist2, tTwist);
			}
			else
			{
				swing = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.identity, swing2, tSwing);
				twist = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.identity, twist2, tTwist);
			}
			return twist * swing;
		}
	}
	public class VectorUtil
	{
		public static UnityEngine.Vector3 Rotate2D(UnityEngine.Vector3 v, float deg)
		{
			UnityEngine.Vector3 result = v;
			float num = Mathf.Cos(MathUtil.Deg2Rad * deg);
			float num2 = Mathf.Sin(MathUtil.Deg2Rad * deg);
			result.x = num * v.x - num2 * v.y;
			result.y = num2 * v.x + num * v.y;
			return result;
		}

		public static UnityEngine.Vector3 NormalizeSafe(UnityEngine.Vector3 v, UnityEngine.Vector3 fallback)
		{
			if (!(v.sqrMagnitude > MathUtil.Epsilon))
			{
				return fallback;
			}
			return v.normalized;
		}

		public static UnityEngine.Vector3 FindOrthogonal(UnityEngine.Vector3 v)
		{
			if (Mathf.Abs(v.x) >= MathUtil.Sqrt3Inv)
			{
				return UnityEngine.Vector3.Normalize(new UnityEngine.Vector3(v.y, 0f - v.x, 0f));
			}
			return UnityEngine.Vector3.Normalize(new UnityEngine.Vector3(0f, v.z, 0f - v.y));
		}

		public static void FormOrthogonalBasis(UnityEngine.Vector3 v, out UnityEngine.Vector3 a, out UnityEngine.Vector3 b)
		{
			a = FindOrthogonal(v);
			b = UnityEngine.Vector3.Cross(a, v);
		}

		public static UnityEngine.Vector3 Integrate(UnityEngine.Vector3 x, UnityEngine.Vector3 v, float dt)
		{
			return x + v * dt;
		}

		public static UnityEngine.Vector3 Slerp(UnityEngine.Vector3 a, UnityEngine.Vector3 b, float t)
		{
			float num = UnityEngine.Vector3.Dot(a, b);
			if (num > 0.99999f)
			{
				return UnityEngine.Vector3.Lerp(a, b, t);
			}
			if (num < -0.99999f)
			{
				UnityEngine.Vector3 axis = FindOrthogonal(a);
				return UnityEngine.Quaternion.AngleAxis(180f * t, axis) * a;
			}
			float num2 = MathUtil.AcosSafe(num);
			return (Mathf.Sin((1f - t) * num2) * a + Mathf.Sin(t * num2) * b) / Mathf.Sin(num2);
		}

		public static UnityEngine.Vector3 CatmullRom(UnityEngine.Vector3 p0, UnityEngine.Vector3 p1, UnityEngine.Vector3 p2, UnityEngine.Vector3 p3, float t)
		{
			float num = t * t;
			return 0.5f * (2f * p1 + (-p0 + p2) * t + (2f * p0 - 5f * p1 + 4f * p2 - p3) * num + (-p0 + 3f * p1 - 3f * p2 + p3) * num * t);
		}
	}
}
namespace UnityChan
{
	public class AutoBlink : MonoBehaviour
	{
		private enum Status
		{
			Close,
			HalfClose,
			Open
		}

		public bool isActive = true;

		public SkinnedMeshRenderer ref_SMR_EYE_DEF;

		public SkinnedMeshRenderer ref_SMR_EL_DEF;

		public float ratio_Close = 85f;

		public float ratio_HalfClose = 20f;

		[HideInInspector]
		public float ratio_Open;

		private bool timerStarted;

		private bool isBlink;

		public float timeBlink = 0.4f;

		private float timeRemining;

		public float threshold = 0.3f;

		public float interval = 3f;

		private Status eyeStatus;

		private void Awake()
		{
		}

		private void Start()
		{
			ResetTimer();
			StartCoroutine("RandomChange");
		}

		private void ResetTimer()
		{
			timeRemining = timeBlink;
			timerStarted = false;
		}

		private void Update()
		{
			if (!timerStarted)
			{
				eyeStatus = Status.Close;
				timerStarted = true;
			}
			if (timerStarted)
			{
				timeRemining -= Time.deltaTime;
				if (timeRemining <= 0f)
				{
					eyeStatus = Status.Open;
					ResetTimer();
				}
				else if (timeRemining <= timeBlink * 0.3f)
				{
					eyeStatus = Status.HalfClose;
				}
			}
		}

		private void LateUpdate()
		{
			if (isActive && isBlink)
			{
				switch (eyeStatus)
				{
				case Status.Close:
					SetCloseEyes();
					break;
				case Status.HalfClose:
					SetHalfCloseEyes();
					break;
				case Status.Open:
					SetOpenEyes();
					isBlink = false;
					break;
				}
			}
		}

		private void SetCloseEyes()
		{
			ref_SMR_EYE_DEF.SetBlendShapeWeight(6, ratio_Close);
			ref_SMR_EL_DEF.SetBlendShapeWeight(6, ratio_Close);
		}

		private void SetHalfCloseEyes()
		{
			ref_SMR_EYE_DEF.SetBlendShapeWeight(6, ratio_HalfClose);
			ref_SMR_EL_DEF.SetBlendShapeWeight(6, ratio_HalfClose);
		}

		private void SetOpenEyes()
		{
			ref_SMR_EYE_DEF.SetBlendShapeWeight(6, ratio_Open);
			ref_SMR_EL_DEF.SetBlendShapeWeight(6, ratio_Open);
		}

		private IEnumerator RandomChange()
		{
			while (true)
			{
				float num = UnityEngine.Random.Range(0f, 1f);
				if (!isBlink && num > threshold)
				{
					isBlink = true;
				}
				yield return new WaitForSeconds(interval);
			}
		}
	}
	public class IdleChanger : MonoBehaviour
	{
		private AnimatorStateInfo currentState;

		private AnimatorStateInfo previousState;

		public bool _random;

		public float _threshold = 0.5f;

		public float _interval = 10f;

		public bool isGUI = true;

		public Animator UnityChanA;

		public Animator UnityChanB;

		private Keyboard kb;

		private void Start()
		{
			currentState = UnityChanA.GetCurrentAnimatorStateInfo(0);
			previousState = currentState;
			StartCoroutine("RandomChange");
			kb = Keyboard.current;
		}

		private void Update()
		{
			if (kb.upArrowKey.wasPressedThisFrame || kb.spaceKey.wasPressedThisFrame)
			{
				UnityChanA.SetBool("Next", value: true);
				UnityChanB.SetBool("Next", value: true);
			}
			if (kb.downArrowKey.wasPressedThisFrame)
			{
				UnityChanA.SetBool("Back", value: true);
				UnityChanB.SetBool("Back", value: true);
			}
			if (UnityChanA.GetBool("Next"))
			{
				currentState = UnityChanA.GetCurrentAnimatorStateInfo(0);
				if (previousState.fullPathHash != currentState.fullPathHash)
				{
					UnityChanA.SetBool("Next", value: false);
					UnityChanB.SetBool("Next", value: false);
					previousState = currentState;
				}
			}
			if (UnityChanA.GetBool("Back"))
			{
				currentState = UnityChanA.GetCurrentAnimatorStateInfo(0);
				if (previousState.fullPathHash != currentState.fullPathHash)
				{
					UnityChanA.SetBool("Back", value: false);
					UnityChanB.SetBool("Back", value: false);
					previousState = currentState;
				}
			}
		}

		private void OnGUI()
		{
			if (isGUI)
			{
				GUI.Box(new Rect(Screen.width - 110, 10f, 100f, 90f), "Change Motion");
				if (GUI.Button(new Rect(Screen.width - 100, 40f, 80f, 20f), "Next"))
				{
					UnityChanA.SetBool("Next", value: true);
					UnityChanB.SetBool("Next", value: true);
				}
				if (GUI.Button(new Rect(Screen.width - 100, 70f, 80f, 20f), "Back"))
				{
					UnityChanA.SetBool("Back", value: true);
					UnityChanB.SetBool("Back", value: true);
				}
			}
		}

		private IEnumerator RandomChange()
		{
			while (true)
			{
				if (_random)
				{
					float num = UnityEngine.Random.Range(0f, 1f);
					if (num < _threshold)
					{
						UnityChanA.SetBool("Back", value: true);
						UnityChanB.SetBool("Back", value: true);
					}
					else if (num >= _threshold)
					{
						UnityChanA.SetBool("Next", value: true);
						UnityChanB.SetBool("Next", value: true);
					}
				}
				yield return new WaitForSeconds(_interval);
			}
		}
	}
}
namespace BoingKit
{
	public class UFOController : MonoBehaviour
	{
		public float LinearThrust = 3f;

		public float MaxLinearSpeed = 2.5f;

		public float LinearDrag = 4f;

		public float Tilt = 15f;

		public float AngularThrust = 30f;

		public float MaxAngularSpeed = 30f;

		public float AngularDrag = 30f;

		[Range(0f, 1f)]
		public float Hover = 1f;

		public Transform Eyes;

		public float BlinkInterval = 5f;

		private float m_blinkTimer;

		private bool m_lastBlinkWasDouble;

		private UnityEngine.Vector3 m_eyeInitScale;

		private UnityEngine.Vector3 m_eyeInitPositionLs;

		private Vector3Spring m_eyeScaleSpring;

		private Vector3Spring m_eyePositionLsSpring;

		public Transform Motor;

		public float MotorBaseAngularSpeed = 10f;

		public float MotorMaxAngularSpeed = 10f;

		public ParticleSystem BubbleEmitter;

		public float BubbleBaseEmissionRate = 10f;

		public float BubbleMaxEmissionRate = 10f;

		private UnityEngine.Vector3 m_linearVelocity;

		private float m_angularVelocity;

		private float m_yawAngle;

		private UnityEngine.Vector3 m_hoverCenter;

		private float m_hoverPhase;

		private float m_motorAngle;

		private void Start()
		{
			m_linearVelocity = UnityEngine.Vector3.zero;
			m_angularVelocity = 0f;
			m_yawAngle = base.transform.rotation.eulerAngles.y * MathUtil.Deg2Rad;
			m_hoverCenter = base.transform.position;
			m_hoverPhase = 0f;
			m_motorAngle = 0f;
			if (Eyes != null)
			{
				m_eyeInitScale = Eyes.localScale;
				m_eyeInitPositionLs = Eyes.localPosition;
				m_blinkTimer = BlinkInterval + UnityEngine.Random.Range(1f, 2f);
				m_lastBlinkWasDouble = false;
				m_eyeScaleSpring.Reset(m_eyeInitScale);
				m_eyePositionLsSpring.Reset(m_eyeInitPositionLs);
			}
		}

		private void OnEnable()
		{
			Start();
		}

		private void FixedUpdate()
		{
			float fixedDeltaTime = Time.fixedDeltaTime;
			UnityEngine.Vector3 zero = UnityEngine.Vector3.zero;
			if (Input.GetKey(KeyCode.W))
			{
				zero += UnityEngine.Vector3.forward;
			}
			if (Input.GetKey(KeyCode.S))
			{
				zero += UnityEngine.Vector3.back;
			}
			if (Input.GetKey(KeyCode.A))
			{
				zero += UnityEngine.Vector3.left;
			}
			if (Input.GetKey(KeyCode.D))
			{
				zero += UnityEngine.Vector3.right;
			}
			if (Input.GetKey(KeyCode.R))
			{
				zero += UnityEngine.Vector3.up;
			}
			if (Input.GetKey(KeyCode.F))
			{
				zero += UnityEngine.Vector3.down;
			}
			if (zero.sqrMagnitude > MathUtil.Epsilon)
			{
				zero = zero.normalized * LinearThrust;
				m_linearVelocity += zero * fixedDeltaTime;
				m_linearVelocity = VectorUtil.ClampLength(m_linearVelocity, 0f, MaxLinearSpeed);
			}
			else
			{
				m_linearVelocity = VectorUtil.ClampLength(m_linearVelocity, 0f, Mathf.Max(0f, m_linearVelocity.magnitude - LinearDrag * fixedDeltaTime));
			}
			float magnitude = m_linearVelocity.magnitude;
			float t = magnitude * MathUtil.InvSafe(MaxLinearSpeed);
			UnityEngine.Quaternion quaternion2 = UnityEngine.Quaternion.identity;
			float num = 1f;
			float num2 = 0f;
			if (magnitude > MathUtil.Epsilon)
			{
				UnityEngine.Vector3 linearVelocity = m_linearVelocity;
				linearVelocity.y = 0f;
				num = ((m_linearVelocity.magnitude > 0.01f) ? (1f - Mathf.Clamp01(Mathf.Abs(m_linearVelocity.y) / m_linearVelocity.magnitude)) : 0f);
				num2 = Mathf.Min(1f, magnitude / Mathf.Max(MathUtil.Epsilon, MaxLinearSpeed)) * num;
				UnityEngine.Vector3 normalized = UnityEngine.Vector3.Cross(UnityEngine.Vector3.up, linearVelocity).normalized;
				float angle = Tilt * MathUtil.Deg2Rad * num2;
				quaternion2 = QuaternionUtil.AxisAngle(normalized, angle);
			}
			float num3 = 0f;
			if (Input.GetKey(KeyCode.Q))
			{
				num3 -= 1f;
			}
			if (Input.GetKey(KeyCode.E))
			{
				num3 += 1f;
			}
			bool key = Input.GetKey(KeyCode.LeftControl);
			if (Mathf.Abs(num3) > MathUtil.Epsilon)
			{
				float num4 = MaxAngularSpeed * (key ? 2.5f : 1f);
				num3 *= AngularThrust * MathUtil.Deg2Rad;
				m_angularVelocity += num3 * fixedDeltaTime;
				m_angularVelocity = Mathf.Clamp(m_angularVelocity, (0f - num4) * MathUtil.Deg2Rad, num4 * MathUtil.Deg2Rad);
			}
			else
			{
				m_angularVelocity -= Mathf.Sign(m_angularVelocity) * Mathf.Min(Mathf.Abs(m_angularVelocity), AngularDrag * MathUtil.Deg2Rad * fixedDeltaTime);
			}
			m_yawAngle += m_angularVelocity * fixedDeltaTime;
			UnityEngine.Quaternion quaternion3 = QuaternionUtil.AxisAngle(UnityEngine.Vector3.up, m_yawAngle);
			m_hoverCenter += m_linearVelocity * fixedDeltaTime;
			m_hoverPhase += Time.deltaTime;
			UnityEngine.Vector3 vector = 0.05f * Mathf.Sin(1.37f * m_hoverPhase) * UnityEngine.Vector3.right + 0.05f * Mathf.Sin(1.93f * m_hoverPhase + 1.234f) * UnityEngine.Vector3.forward + 0.04f * Mathf.Sin(0.97f * m_hoverPhase + 4.321f) * UnityEngine.Vector3.up;
			vector *= Hover;
			UnityEngine.Quaternion quaternion4 = UnityEngine.Quaternion.FromToRotation(UnityEngine.Vector3.up, vector + UnityEngine.Vector3.up);
			base.transform.position = m_hoverCenter + vector;
			base.transform.rotation = quaternion2 * quaternion3 * quaternion4;
			if (Motor != null)
			{
				float num5 = Mathf.Lerp(MotorBaseAngularSpeed, MotorMaxAngularSpeed, num2);
				m_motorAngle += num5 * MathUtil.Deg2Rad * fixedDeltaTime;
				Motor.localRotation = QuaternionUtil.AxisAngle(UnityEngine.Vector3.up, m_motorAngle - m_yawAngle);
			}
			if (BubbleEmitter != null)
			{
				ParticleSystem.EmissionModule emission = BubbleEmitter.emission;
				emission.rateOverTime = Mathf.Lerp(BubbleBaseEmissionRate, BubbleMaxEmissionRate, t);
			}
			if (Eyes != null)
			{
				m_blinkTimer -= fixedDeltaTime;
				if (m_blinkTimer <= 0f)
				{
					bool flag = !m_lastBlinkWasDouble && UnityEngine.Random.Range(0f, 1f) > 0.75f;
					m_blinkTimer = (flag ? 0.2f : (BlinkInterval + UnityEngine.Random.Range(1f, 2f)));
					m_lastBlinkWasDouble = flag;
					m_eyeScaleSpring.Value.y = 0f;
					m_eyePositionLsSpring.Value.y -= 0.025f;
				}
				Eyes.localScale = m_eyeScaleSpring.TrackDampingRatio(m_eyeInitScale, 30f, 0.8f, fixedDeltaTime);
				Eyes.localPosition = m_eyePositionLsSpring.TrackDampingRatio(m_eyeInitPositionLs, 30f, 0.8f, fixedDeltaTime);
			}
		}
	}
	public class BoingBase : MonoBehaviour
	{
		[SerializeField]
		private Version m_currentVersion;

		[SerializeField]
		private Version m_previousVersion;

		[SerializeField]
		private Version m_initialVersion = BoingKit.Version;

		public Version CurrentVersion => m_currentVersion;

		public Version PreviousVersion => m_previousVersion;

		public Version InitialVersion => m_initialVersion;

		protected virtual void OnUpgrade(Version oldVersion, Version newVersion)
		{
			m_previousVersion = m_currentVersion;
			if (m_currentVersion.Revision < 33)
			{
				m_initialVersion = Version.Invalid;
				m_previousVersion = Version.Invalid;
			}
			m_currentVersion = newVersion;
		}
	}
	public class BoingBehavior : BoingBase
	{
		public BoingManager.UpdateMode UpdateMode = BoingManager.UpdateMode.LateUpdate;

		public bool TwoDDistanceCheck;

		public bool TwoDPositionInfluence;

		public bool TwoDRotationInfluence;

		public bool EnablePositionEffect = true;

		public bool EnableRotationEffect = true;

		public bool EnableScaleEffect;

		public bool GlobalReactionUpVector;

		public BoingManager.TranslationLockSpace TranslationLockSpace;

		public bool LockTranslationX;

		public bool LockTranslationY;

		public bool LockTranslationZ;

		public BoingWork.Params Params;

		public SharedBoingParams SharedParams;

		internal bool PositionSpringDirty;

		internal bool RotationSpringDirty;

		internal bool ScaleSpringDirty;

		internal bool CachedTransformValid;

		internal UnityEngine.Vector3 CachedPositionLs;

		internal UnityEngine.Vector3 CachedPositionWs;

		internal UnityEngine.Vector3 RenderPositionWs;

		internal UnityEngine.Quaternion CachedRotationLs;

		internal UnityEngine.Quaternion CachedRotationWs;

		internal UnityEngine.Quaternion RenderRotationWs;

		internal UnityEngine.Vector3 CachedScaleLs;

		internal UnityEngine.Vector3 RenderScaleLs;

		internal bool InitRebooted;

		public Vector3Spring PositionSpring
		{
			get
			{
				return Params.Instance.PositionSpring;
			}
			set
			{
				Params.Instance.PositionSpring = value;
				PositionSpringDirty = true;
			}
		}

		public QuaternionSpring RotationSpring
		{
			get
			{
				return Params.Instance.RotationSpring;
			}
			set
			{
				Params.Instance.RotationSpring = value;
				RotationSpringDirty = true;
			}
		}

		public Vector3Spring ScaleSpring
		{
			get
			{
				return Params.Instance.ScaleSpring;
			}
			set
			{
				Params.Instance.ScaleSpring = value;
				ScaleSpringDirty = true;
			}
		}

		public BoingBehavior()
		{
			Params.Init();
		}

		public virtual void Reboot()
		{
			Params.Instance.PositionSpring.Reset(base.transform.position);
			Params.Instance.RotationSpring.Reset(base.transform.rotation);
			Params.Instance.ScaleSpring.Reset(base.transform.localScale);
			CachedPositionLs = base.transform.localPosition;
			CachedRotationLs = base.transform.localRotation;
			CachedPositionWs = base.transform.position;
			CachedRotationWs = base.transform.rotation;
			CachedScaleLs = base.transform.localScale;
			CachedTransformValid = true;
		}

		public virtual void OnEnable()
		{
			CachedTransformValid = false;
			InitRebooted = false;
			Register();
		}

		public void Start()
		{
			InitRebooted = false;
		}

		public virtual void OnDisable()
		{
			Unregister();
		}

		protected virtual void Register()
		{
			BoingManager.Register(this);
		}

		protected virtual void Unregister()
		{
			BoingManager.Unregister(this);
		}

		public void UpdateFlags()
		{
			Params.Bits.SetBit(0, TwoDDistanceCheck);
			Params.Bits.SetBit(1, TwoDPositionInfluence);
			Params.Bits.SetBit(2, TwoDRotationInfluence);
			Params.Bits.SetBit(3, EnablePositionEffect);
			Params.Bits.SetBit(4, EnableRotationEffect);
			Params.Bits.SetBit(5, EnableScaleEffect);
			Params.Bits.SetBit(6, GlobalReactionUpVector);
			Params.Bits.SetBit(9, UpdateMode == BoingManager.UpdateMode.FixedUpdate);
			Params.Bits.SetBit(10, UpdateMode == BoingManager.UpdateMode.EarlyUpdate);
			Params.Bits.SetBit(11, UpdateMode == BoingManager.UpdateMode.LateUpdate);
		}

		public virtual void PrepareExecute()
		{
			PrepareExecute(accumulateEffectors: false);
		}

		protected void PrepareExecute(bool accumulateEffectors)
		{
			if (SharedParams != null)
			{
				BoingWork.Params.Copy(ref SharedParams.Params, ref Params);
			}
			UpdateFlags();
			Params.InstanceID = GetInstanceID();
			Params.Instance.PrepareExecute(ref Params, CachedPositionWs, CachedRotationWs, base.transform.localScale, accumulateEffectors);
		}

		public void Execute(float dt)
		{
			Params.Execute(dt);
		}

		public void PullResults()
		{
			PullResults(ref Params);
		}

		public void GatherOutput(ref BoingWork.Output o)
		{
			if (BoingManager.UseAsynchronousJobs)
			{
				if (PositionSpringDirty)
				{
					PositionSpringDirty = false;
				}
				else
				{
					Params.Instance.PositionSpring = o.PositionSpring;
				}
				if (RotationSpringDirty)
				{
					RotationSpringDirty = false;
				}
				else
				{
					Params.Instance.RotationSpring = o.RotationSpring;
				}
				if (ScaleSpringDirty)
				{
					ScaleSpringDirty = false;
				}
				else
				{
					Params.Instance.ScaleSpring = o.ScaleSpring;
				}
			}
			else
			{
				Params.Instance.PositionSpring = o.PositionSpring;
				Params.Instance.RotationSpring = o.RotationSpring;
				Params.Instance.ScaleSpring = o.ScaleSpring;
			}
		}

		private void PullResults(ref BoingWork.Params p)
		{
			CachedPositionLs = base.transform.localPosition;
			CachedPositionWs = base.transform.position;
			RenderPositionWs = BoingWork.ComputeTranslationalResults(base.transform, base.transform.position, p.Instance.PositionSpring.Value, this);
			base.transform.position = RenderPositionWs;
			CachedRotationLs = base.transform.localRotation;
			CachedRotationWs = base.transform.rotation;
			RenderRotationWs = p.Instance.RotationSpring.ValueQuat;
			base.transform.rotation = RenderRotationWs;
			CachedScaleLs = base.transform.localScale;
			RenderScaleLs = p.Instance.ScaleSpring.Value;
			base.transform.localScale = RenderScaleLs;
			CachedTransformValid = true;
		}

		public virtual void Restore()
		{
			if (!CachedTransformValid)
			{
				return;
			}
			if (UnityEngine.Application.isEditor)
			{
				if ((base.transform.position - RenderPositionWs).sqrMagnitude < 0.0001f)
				{
					base.transform.localPosition = CachedPositionLs;
				}
				if (QuaternionUtil.GetAngle(base.transform.rotation * UnityEngine.Quaternion.Inverse(RenderRotationWs)) < 0.01f)
				{
					base.transform.localRotation = CachedRotationLs;
				}
				if ((base.transform.localScale - RenderScaleLs).sqrMagnitude < 0.0001f)
				{
					base.transform.localScale = CachedScaleLs;
				}
			}
			else
			{
				base.transform.localPosition = CachedPositionLs;
				base.transform.localRotation = CachedRotationLs;
				base.transform.localScale = CachedScaleLs;
			}
		}
	}
	public class BoingBoneCollider : MonoBehaviour
	{
		public enum Type
		{
			Sphere,
			Capsule,
			Box
		}

		public Type Shape;

		public float Radius = 0.1f;

		public float Height = 0.25f;

		public UnityEngine.Vector3 Dimensions = new UnityEngine.Vector3(0.1f, 0.1f, 0.1f);

		public Bounds Bounds
		{
			get
			{
				switch (Shape)
				{
				case Type.Sphere:
				{
					float num2 = VectorUtil.MinComponent(base.transform.localScale);
					return new Bounds(base.transform.position, 2f * num2 * Radius * UnityEngine.Vector3.one);
				}
				case Type.Capsule:
				{
					float num = VectorUtil.MinComponent(base.transform.localScale);
					return new Bounds(base.transform.position, 2f * num * Radius * UnityEngine.Vector3.one + Height * VectorUtil.ComponentWiseAbs(base.transform.rotation * UnityEngine.Vector3.up));
				}
				case Type.Box:
					return new Bounds(base.transform.position, VectorUtil.ComponentWiseMult(base.transform.localScale, VectorUtil.ComponentWiseAbs(base.transform.rotation * Dimensions)));
				default:
					return default(Bounds);
				}
			}
		}

		public bool Collide(UnityEngine.Vector3 boneCenter, float boneRadius, out UnityEngine.Vector3 push)
		{
			switch (Shape)
			{
			case Type.Sphere:
			{
				float num2 = VectorUtil.MinComponent(base.transform.localScale);
				return Collision.SphereSphere(boneCenter, boneRadius, base.transform.position, num2 * Radius, out push);
			}
			case Type.Capsule:
			{
				float num = VectorUtil.MinComponent(base.transform.localScale);
				UnityEngine.Vector3 headB = base.transform.TransformPoint(0.5f * Height * UnityEngine.Vector3.up);
				UnityEngine.Vector3 tailB = base.transform.TransformPoint(0.5f * Height * UnityEngine.Vector3.down);
				return Collision.SphereCapsule(boneCenter, boneRadius, headB, tailB, num * Radius, out push);
			}
			case Type.Box:
			{
				UnityEngine.Vector3 centerOffsetA = base.transform.InverseTransformPoint(boneCenter);
				UnityEngine.Vector3 halfExtentB = 0.5f * VectorUtil.ComponentWiseMult(base.transform.localScale, Dimensions);
				if (!Collision.SphereBox(centerOffsetA, boneRadius, halfExtentB, out push))
				{
					return false;
				}
				push = base.transform.TransformVector(push);
				return true;
			}
			default:
				push = UnityEngine.Vector3.zero;
				return false;
			}
		}

		public void OnValidate()
		{
			Radius = Mathf.Max(0f, Radius);
			Dimensions.x = Mathf.Max(0f, Dimensions.x);
			Dimensions.y = Mathf.Max(0f, Dimensions.y);
			Dimensions.z = Mathf.Max(0f, Dimensions.z);
		}

		public void OnDrawGizmos()
		{
			DrawGizmos();
		}

		public void DrawGizmos()
		{
			switch (Shape)
			{
			case Type.Sphere:
			{
				float radius = VectorUtil.MinComponent(base.transform.localScale) * Radius;
				Gizmos.matrix = UnityEngine.Matrix4x4.TRS(base.transform.position, base.transform.rotation, UnityEngine.Vector3.one);
				if (Shape == Type.Sphere)
				{
					Gizmos.color = new Color(1f, 1f, 1f, 0.5f);
					Gizmos.DrawSphere(UnityEngine.Vector3.zero, radius);
				}
				Gizmos.color = Color.white;
				Gizmos.DrawWireSphere(UnityEngine.Vector3.zero, radius);
				Gizmos.matrix = UnityEngine.Matrix4x4.identity;
				break;
			}
			case Type.Capsule:
			{
				float num = VectorUtil.MinComponent(base.transform.localScale);
				float num2 = num * Radius;
				float num3 = 0.5f * num * Height;
				Gizmos.matrix = UnityEngine.Matrix4x4.TRS(base.transform.position, base.transform.rotation, UnityEngine.Vector3.one);
				if (Shape == Type.Capsule)
				{
					Gizmos.color = new Color(1f, 1f, 1f, 0.5f);
					Gizmos.DrawSphere(num3 * UnityEngine.Vector3.up, num2);
					Gizmos.DrawSphere(num3 * UnityEngine.Vector3.down, num2);
				}
				Gizmos.color = Color.white;
				Gizmos.DrawWireSphere(num3 * UnityEngine.Vector3.up, num2);
				Gizmos.DrawWireSphere(num3 * UnityEngine.Vector3.down, num2);
				for (int i = 0; i < 4; i++)
				{
					float f = (float)i * MathUtil.HalfPi;
					UnityEngine.Vector3 vector = new UnityEngine.Vector3(num2 * Mathf.Cos(f), 0f, num2 * Mathf.Sin(f));
					Gizmos.DrawLine(vector + num3 * UnityEngine.Vector3.up, vector + num3 * UnityEngine.Vector3.down);
				}
				Gizmos.matrix = UnityEngine.Matrix4x4.identity;
				break;
			}
			case Type.Box:
			{
				UnityEngine.Vector3 size = VectorUtil.ComponentWiseMult(base.transform.localScale, Dimensions);
				Gizmos.matrix = base.transform.localToWorldMatrix;
				if (Shape == Type.Box)
				{
					Gizmos.color = new Color(1f, 1f, 1f, 0.5f);
					Gizmos.DrawCube(UnityEngine.Vector3.zero, size);
				}
				Gizmos.color = Color.white;
				Gizmos.DrawWireCube(UnityEngine.Vector3.zero, size);
				Gizmos.matrix = UnityEngine.Matrix4x4.identity;
				break;
			}
			}
		}
	}
