					if (updatedScale)
					{
						updatedScale = false;
						localScale = Transform.localScale;
					}
					return localScale;
				}
			}

			private void CheckResetFlags()
			{
				if (Transform.hasChanged)
				{
					updatedPos = (updatedRot = (updatedScale = true));
