				}
			}

			internal void UpdateBounds()
			{
				Bounds = new Bounds(Instance.PositionSpring.Value, 2f * CollisionRadius * UnityEngine.Vector3.one);
			}

			internal Bone(Transform transform, int iParent, float lengthFromRoot)
			{
