	public struct Aabb
	{
		public UnityEngine.Vector3 Min;

		public UnityEngine.Vector3 Max;

		public float MinX
		{
			get
			{
				return Min.x;
			}
			set
			{
				Min.x = value;
			}
		}

		public float MinY
		{
			get
			{
				return Min.y;
			}
			set
			{
				Min.y = value;
			}
		}

		public float MinZ
		{
			get
			{
				return Min.z;
			}
			set
			{
				Min.z = value;
			}
		}

		public float MaxX
		{
			get
			{
				return Max.x;
			}
			set
			{
				Max.x = value;
			}
		}

		public float MaxY
		{
			get
			{
				return Max.y;
			}
			set
			{
				Max.y = value;
			}
		}

		public float MaxZ
		{
			get
			{
				return Max.z;
			}
			set
			{
				Max.z = value;
			}
		}

		public UnityEngine.Vector3 Center => 0.5f * (Min + Max);

		public UnityEngine.Vector3 Size
		{
			get
			{
				UnityEngine.Vector3 result = Max - Min;
				result.x = Mathf.Max(0f, result.x);
				result.y = Mathf.Max(0f, result.y);
				result.z = Mathf.Max(0f, result.z);
				return result;
			}
		}

		public static Aabb Empty => new Aabb(new UnityEngine.Vector3(float.MaxValue, float.MaxValue, float.MaxValue), new UnityEngine.Vector3(float.MinValue, float.MinValue, float.MinValue));

		public static Aabb FromPoint(UnityEngine.Vector3 p)
		{
			Aabb empty = Empty;
			empty.Include(p);
			return empty;
		}

		public static Aabb FromPoints(UnityEngine.Vector3 a, UnityEngine.Vector3 b)
		{
			Aabb empty = Empty;
			empty.Include(a);
			empty.Include(b);
			return empty;
		}

		public Aabb(UnityEngine.Vector3 min, UnityEngine.Vector3 max)
		{
			Min = min;
			Max = max;
		}

		public void Include(UnityEngine.Vector3 p)
		{
			MinX = Mathf.Min(MinX, p.x);
			MinY = Mathf.Min(MinY, p.y);
			MinZ = Mathf.Min(MinZ, p.z);
			MaxX = Mathf.Max(MaxX, p.x);
			MaxY = Mathf.Max(MaxY, p.y);
			MaxZ = Mathf.Max(MaxZ, p.z);
		}

		public bool Contains(UnityEngine.Vector3 p)
		{
			if (MinX <= p.x && MinY <= p.y && MinZ <= p.z && MaxX >= p.x && MaxY >= p.y)
			{
				return MaxZ >= p.z;
			}
			return false;
		}

		public bool ContainsX(UnityEngine.Vector3 p)
		{
			if (MinX <= p.x)
			{
				return MaxX >= p.x;
			}
			return false;
		}

		public bool ContainsY(UnityEngine.Vector3 p)
		{
			if (MinY <= p.y)
			{
				return MaxY >= p.y;
			}
			return false;
		}

		public bool ContainsZ(UnityEngine.Vector3 p)
		{
			if (MinZ <= p.z)
			{
				return MaxZ >= p.z;
			}
			return false;
		}

		public bool Intersects(Aabb rhs)
		{
			if (MinX <= rhs.MaxX && MinY <= rhs.MaxY && MinZ <= rhs.MaxZ && MaxX >= rhs.MinX && MaxY >= rhs.MinY)
			{
				return MaxZ >= rhs.MinZ;
			}
			return false;
		}

		public bool Intersects(ref BoingEffector.Params effector)
		{
			if (!effector.Bits.IsBitSet(0))
			{
				return Intersects(FromPoint(effector.CurrPosition).Expand(effector.Radius));
			}
			return Intersects(FromPoints(effector.PrevPosition, effector.CurrPosition).Expand(effector.Radius));
		}

		public Aabb Expand(float amount)
		{
			MinX -= amount;
			MinY -= amount;
			MinZ -= amount;
			MaxX += amount;
			MaxY += amount;
			MaxZ += amount;
			return this;
		}
	}
	[Serializable]
	public struct Bits32
	{
		[SerializeField]
		private int m_bits;

		public int IntValue => m_bits;

		public Bits32(int bits = 0)
		{
			m_bits = bits;
		}

		public void Clear()
		{
			m_bits = 0;
		}

		public void SetBit(int index, bool value)
		{
			if (value)
			{
				m_bits |= 1 << index;
			}
			else
			{
				m_bits &= ~(1 << index);
			}
		}

		public bool IsBitSet(int index)
		{
			return (m_bits & (1 << index)) != 0;
		}
	}
	public struct BitArray
	{
		private int[] m_aBlock;

		public int[] Blocks => m_aBlock;

		private static int GetBlockIndex(int index)
		{
			return index / 4;
		}

		private static int GetSubIndex(int index)
		{
			return index % 4;
		}

		private static void SetBit(int index, bool value, int[] blocks)
		{
			int blockIndex = GetBlockIndex(index);
			int subIndex = GetSubIndex(index);
			if (value)
			{
				blocks[blockIndex] |= 1 << subIndex;
			}
			else
			{
				blocks[blockIndex] &= ~(1 << subIndex);
			}
		}

		private static bool IsBitSet(int index, int[] blocks)
		{
			return (blocks[GetBlockIndex(index)] & (1 << GetSubIndex(index))) != 0;
		}

		public BitArray(int capacity)
		{
			int num = (capacity + 4 - 1) / 4;
			m_aBlock = new int[num];
			Clear();
		}

		public void Resize(int capacity)
		{
			int num = (capacity + 4 - 1) / 4;
			if (num > m_aBlock.Length)
			{
				int[] array = new int[num];
				int i = 0;
				for (int num2 = m_aBlock.Length; i < num2; i++)
				{
					array[i] = m_aBlock[i];
				}
				m_aBlock = array;
			}
		}

		public void Clear()
		{
			SetAllBits(value: false);
		}

		public void SetAllBits(bool value)
		{
			int num = ((!value) ? 1 : (-1));
			int i = 0;
			for (int num2 = m_aBlock.Length; i < num2; i++)
			{
				m_aBlock[i] = num;
			}
		}

		public void SetBit(int index, bool value)
		{
			SetBit(index, value, m_aBlock);
		}

		public bool IsBitSet(int index)
		{
			return IsBitSet(index, m_aBlock);
		}
	}
	public class Collision
	{
		public static bool SphereSphere(UnityEngine.Vector3 centerA, float radiusA, UnityEngine.Vector3 centerB, float radiusB, out UnityEngine.Vector3 push)
		{
			push = UnityEngine.Vector3.zero;
			UnityEngine.Vector3 vector = centerA - centerB;
			float sqrMagnitude = vector.sqrMagnitude;
			float num = radiusA + radiusB;
			if (sqrMagnitude >= num * num)
			{
				return false;
			}
			float num2 = Mathf.Sqrt(sqrMagnitude);
			push = VectorUtil.NormalizeSafe(vector, UnityEngine.Vector3.zero) * (num - num2);
			return true;
		}

		public static bool SphereSphereInverse(UnityEngine.Vector3 centerA, float radiusA, UnityEngine.Vector3 centerB, float radiusB, out UnityEngine.Vector3 push)
		{
			push = UnityEngine.Vector3.zero;
			UnityEngine.Vector3 vector = centerB - centerA;
			float sqrMagnitude = vector.sqrMagnitude;
			float num = radiusB - radiusA;
			if (sqrMagnitude <= num * num)
			{
				return false;
			}
			float num2 = Mathf.Sqrt(sqrMagnitude);
			push = VectorUtil.NormalizeSafe(vector, UnityEngine.Vector3.zero) * (num2 - num);
			return true;
		}

		public static bool SphereCapsule(UnityEngine.Vector3 centerA, float radiusA, UnityEngine.Vector3 headB, UnityEngine.Vector3 tailB, float radiusB, out UnityEngine.Vector3 push)
		{
			push = UnityEngine.Vector3.zero;
			UnityEngine.Vector3 vector = tailB - headB;
			float sqrMagnitude = vector.sqrMagnitude;
			if (sqrMagnitude < MathUtil.Epsilon)
			{
				return SphereSphereInverse(centerA, radiusA, 0.5f * (headB + tailB), radiusB, out push);
			}
			float num = 1f / Mathf.Sqrt(sqrMagnitude);
			UnityEngine.Vector3 rhs = vector * num;
			float t = Mathf.Clamp01(UnityEngine.Vector3.Dot(centerA - headB, rhs) * num);
			UnityEngine.Vector3 centerB = UnityEngine.Vector3.Lerp(headB, tailB, t);
			return SphereSphere(centerA, radiusA, centerB, radiusB, out push);
		}

		public static bool SphereCapsuleInverse(UnityEngine.Vector3 centerA, float radiusA, UnityEngine.Vector3 headB, UnityEngine.Vector3 tailB, float radiusB, out UnityEngine.Vector3 push)
		{
			push = UnityEngine.Vector3.zero;
			UnityEngine.Vector3 vector = tailB - headB;
			float sqrMagnitude = vector.sqrMagnitude;
			if (sqrMagnitude < MathUtil.Epsilon)
			{
				return SphereSphereInverse(centerA, radiusA, 0.5f * (headB + tailB), radiusB, out push);
			}
			float num = 1f / Mathf.Sqrt(sqrMagnitude);
			UnityEngine.Vector3 rhs = vector * num;
			float t = Mathf.Clamp01(UnityEngine.Vector3.Dot(centerA - headB, rhs) * num);
			UnityEngine.Vector3 centerB = UnityEngine.Vector3.Lerp(headB, tailB, t);
			return SphereSphereInverse(centerA, radiusA, centerB, radiusB, out push);
		}

		public static bool SphereBox(UnityEngine.Vector3 centerOffsetA, float radiusA, UnityEngine.Vector3 halfExtentB, out UnityEngine.Vector3 push)
		{
			push = UnityEngine.Vector3.zero;
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(Mathf.Clamp(centerOffsetA.x, 0f - halfExtentB.x, halfExtentB.x), Mathf.Clamp(centerOffsetA.y, 0f - halfExtentB.y, halfExtentB.y), Mathf.Clamp(centerOffsetA.z, 0f - halfExtentB.z, halfExtentB.z));
			UnityEngine.Vector3 vector2 = centerOffsetA - vector;
			float sqrMagnitude = vector2.sqrMagnitude;
			if (sqrMagnitude > radiusA * radiusA)
			{
				return false;
			}
			switch (((!(centerOffsetA.x < 0f - halfExtentB.x) && !(centerOffsetA.x > halfExtentB.x)) ? 1 : 0) + ((!(centerOffsetA.y < 0f - halfExtentB.y) && !(centerOffsetA.y > halfExtentB.y)) ? 1 : 0) + ((!(centerOffsetA.z < 0f - halfExtentB.z) && !(centerOffsetA.z > halfExtentB.z)) ? 1 : 0))
			{
			case 0:
			case 1:
			case 2:
				push = VectorUtil.NormalizeSafe(vector2, UnityEngine.Vector3.right) * (radiusA - Mathf.Sqrt(sqrMagnitude));
				break;
			case 3:
			{
				UnityEngine.Vector3 vector3 = new UnityEngine.Vector3(halfExtentB.x - Mathf.Abs(centerOffsetA.x) + radiusA, halfExtentB.y - Mathf.Abs(centerOffsetA.y) + radiusA, halfExtentB.z - Mathf.Abs(centerOffsetA.z) + radiusA);
				if (vector3.x < vector3.y)
				{
					if (vector3.x < vector3.z)
					{
						push = new UnityEngine.Vector3(Mathf.Sign(centerOffsetA.x) * vector3.x, 0f, 0f);
					}
					else
					{
						push = new UnityEngine.Vector3(0f, 0f, Mathf.Sign(centerOffsetA.z) * vector3.z);
					}
				}
				else if (vector3.y < vector3.z)
				{
					push = new UnityEngine.Vector3(0f, Mathf.Sign(centerOffsetA.y) * vector3.y, 0f);
				}
				else
				{
					push = new UnityEngine.Vector3(0f, 0f, Mathf.Sign(centerOffsetA.z) * vector3.z);
				}
				break;
			}
			}
			return true;
		}

		public static bool SphereBoxInverse(UnityEngine.Vector3 centerOffsetA, float radiusA, UnityEngine.Vector3 halfExtentB, out UnityEngine.Vector3 push)
		{
			push = UnityEngine.Vector3.zero;
			return false;
		}
	}
