	public class MathUtil
	{
		public static readonly float Pi = MathF.PI;

		public static readonly float TwoPi = MathF.PI * 2f;

		public static readonly float HalfPi = MathF.PI / 2f;

		public static readonly float QuaterPi = MathF.PI / 4f;

		public static readonly float SixthPi = MathF.PI / 6f;

		public static readonly float Sqrt2 = Mathf.Sqrt(2f);

		public static readonly float Sqrt2Inv = 1f / Mathf.Sqrt(2f);

		public static readonly float Sqrt3 = Mathf.Sqrt(3f);

		public static readonly float Sqrt3Inv = 1f / Mathf.Sqrt(3f);

		public static readonly float Epsilon = 1E-06f;

		public static readonly float Rad2Deg = 180f / MathF.PI;

		public static readonly float Deg2Rad = MathF.PI / 180f;

		public static float AsinSafe(float x)
		{
			return Mathf.Asin(Mathf.Clamp(x, -1f, 1f));
		}

		public static float AcosSafe(float x)
		{
			return Mathf.Acos(Mathf.Clamp(x, -1f, 1f));
		}

		public static float InvSafe(float x)
		{
			return 1f / Mathf.Max(Epsilon, x);
		}

		public static float PointLineDist(UnityEngine.Vector2 point, UnityEngine.Vector2 linePos, UnityEngine.Vector2 lineDir)
		{
			UnityEngine.Vector2 vector = point - linePos;
			return (vector - UnityEngine.Vector2.Dot(vector, lineDir) * lineDir).magnitude;
		}

		public static float PointSegmentDist(UnityEngine.Vector2 point, UnityEngine.Vector2 segmentPosA, UnityEngine.Vector2 segmentPosB)
		{
			UnityEngine.Vector2 vector = segmentPosB - segmentPosA;
			float num = 1f / vector.magnitude;
			UnityEngine.Vector2 rhs = vector * num;
			float value = UnityEngine.Vector2.Dot(point - segmentPosA, rhs) * num;
			return (segmentPosA + Mathf.Clamp(value, 0f, 1f) * vector - point).magnitude;
		}

		public static float Seek(float current, float target, float maxDelta)
		{
			float f = target - current;
			f = Mathf.Sign(f) * Mathf.Min(maxDelta, Mathf.Abs(f));
			return current + f;
		}

		public static UnityEngine.Vector2 Seek(UnityEngine.Vector2 current, UnityEngine.Vector2 target, float maxDelta)
		{
			UnityEngine.Vector2 vector = target - current;
			float magnitude = vector.magnitude;
			if (magnitude < Epsilon)
			{
				return target;
			}
			vector = Mathf.Min(maxDelta, magnitude) * vector.normalized;
			return current + vector;
		}

		public static float Remainder(float a, float b)
		{
			return a - a / b * b;
		}

		public static int Remainder(int a, int b)
		{
			return a - a / b * b;
		}

		public static float Modulo(float a, float b)
		{
			return Mathf.Repeat(a, b);
		}

		public static int Modulo(int a, int b)
		{
			int num = a % b;
			if (num < 0)
			{
				return num + b;
			}
			return num;
		}
	}
	public class QuaternionUtil
	{
		public enum SterpMode
		{
			Nlerp,
			Slerp
		}

		public static float Magnitude(UnityEngine.Quaternion q)
		{
			return Mathf.Sqrt(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w);
		}

		public static float MagnitudeSqr(UnityEngine.Quaternion q)
		{
			return q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w;
		}

		public static UnityEngine.Quaternion Normalize(UnityEngine.Quaternion q)
		{
			float num = 1f / Magnitude(q);
			return new UnityEngine.Quaternion(num * q.x, num * q.y, num * q.z, num * q.w);
		}

		public static UnityEngine.Quaternion AxisAngle(UnityEngine.Vector3 axis, float angle)
		{
			float f = 0.5f * angle;
			float num = Mathf.Sin(f);
			float w = Mathf.Cos(f);
			return new UnityEngine.Quaternion(num * axis.x, num * axis.y, num * axis.z, w);
		}

		public static UnityEngine.Vector3 GetAxis(UnityEngine.Quaternion q)
		{
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(q.x, q.y, q.z);
			float magnitude = vector.magnitude;
			if (magnitude < MathUtil.Epsilon)
			{
				return UnityEngine.Vector3.left;
			}
			return vector / magnitude;
		}

		public static float GetAngle(UnityEngine.Quaternion q)
		{
			return 2f * Mathf.Acos(Mathf.Clamp(q.w, -1f, 1f));
		}

		public static UnityEngine.Quaternion FromAngularVector(UnityEngine.Vector3 v)
		{
			float magnitude = v.magnitude;
			if (magnitude < MathUtil.Epsilon)
			{
				return UnityEngine.Quaternion.identity;
			}
			v /= magnitude;
			float f = 0.5f * magnitude;
			float num = Mathf.Sin(f);
			float w = Mathf.Cos(f);
			return new UnityEngine.Quaternion(num * v.x, num * v.y, num * v.z, w);
		}

		public static UnityEngine.Vector3 ToAngularVector(UnityEngine.Quaternion q)
		{
			UnityEngine.Vector3 axis = GetAxis(q);
			return GetAngle(q) * axis;
		}

		public static UnityEngine.Quaternion Pow(UnityEngine.Quaternion q, float exp)
		{
			UnityEngine.Vector3 axis = GetAxis(q);
			float angle = GetAngle(q) * exp;
			return AxisAngle(axis, angle);
		}

		public static UnityEngine.Quaternion Integrate(UnityEngine.Quaternion q, UnityEngine.Quaternion v, float dt)
		{
			return Pow(v, dt) * q;
		}

		public static UnityEngine.Quaternion Integrate(UnityEngine.Quaternion q, UnityEngine.Vector3 omega, float dt)
		{
			omega *= 0.5f;
			UnityEngine.Quaternion quaternion2 = new UnityEngine.Quaternion(omega.x, omega.y, omega.z, 0f) * q;
			return Normalize(new UnityEngine.Quaternion(q.x + quaternion2.x * dt, q.y + quaternion2.y * dt, q.z + quaternion2.z * dt, q.w + quaternion2.w * dt));
		}

		public static UnityEngine.Vector4 ToVector4(UnityEngine.Quaternion q)
		{
			return new UnityEngine.Vector4(q.x, q.y, q.z, q.w);
		}

		public static UnityEngine.Quaternion FromVector4(UnityEngine.Vector4 v, bool normalize = true)
		{
			if (normalize)
			{
				float sqrMagnitude = v.sqrMagnitude;
				if (sqrMagnitude < MathUtil.Epsilon)
				{
					return UnityEngine.Quaternion.identity;
				}
				v /= Mathf.Sqrt(sqrMagnitude);
			}
			return new UnityEngine.Quaternion(v.x, v.y, v.z, v.w);
		}

		public static void DecomposeSwingTwist(UnityEngine.Quaternion q, UnityEngine.Vector3 twistAxis, out UnityEngine.Quaternion swing, out UnityEngine.Quaternion twist)
		{
			UnityEngine.Vector3 vector = new UnityEngine.Vector3(q.x, q.y, q.z);
			if (vector.sqrMagnitude < MathUtil.Epsilon)
			{
				UnityEngine.Vector3 vector2 = q * twistAxis;
				UnityEngine.Vector3 axis = UnityEngine.Vector3.Cross(twistAxis, vector2);
				if (axis.sqrMagnitude > MathUtil.Epsilon)
				{
					float angle = UnityEngine.Vector3.Angle(twistAxis, vector2);
					swing = UnityEngine.Quaternion.AngleAxis(angle, axis);
				}
				else
				{
					swing = UnityEngine.Quaternion.identity;
				}
				twist = UnityEngine.Quaternion.AngleAxis(180f, twistAxis);
			}
			else
			{
				UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Project(vector, twistAxis);
				twist = new UnityEngine.Quaternion(vector3.x, vector3.y, vector3.z, q.w);
				twist = Normalize(twist);
				swing = q * UnityEngine.Quaternion.Inverse(twist);
			}
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float t, SterpMode mode = SterpMode.Slerp)
		{
			UnityEngine.Quaternion swing;
			UnityEngine.Quaternion twist;
			return Sterp(a, b, twistAxis, t, out swing, out twist, mode);
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float t, out UnityEngine.Quaternion swing, out UnityEngine.Quaternion twist, SterpMode mode = SterpMode.Slerp)
		{
			return Sterp(a, b, twistAxis, t, t, out swing, out twist, mode);
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float tSwing, float tTwist, SterpMode mode = SterpMode.Slerp)
		{
			UnityEngine.Quaternion swing;
			UnityEngine.Quaternion twist;
			return Sterp(a, b, twistAxis, tSwing, tTwist, out swing, out twist, mode);
		}

		public static UnityEngine.Quaternion Sterp(UnityEngine.Quaternion a, UnityEngine.Quaternion b, UnityEngine.Vector3 twistAxis, float tSwing, float tTwist, out UnityEngine.Quaternion swing, out UnityEngine.Quaternion twist, SterpMode mode)
		{
			DecomposeSwingTwist(b * UnityEngine.Quaternion.Inverse(a), twistAxis, out var swing2, out var twist2);
			if (mode == SterpMode.Nlerp || mode != SterpMode.Slerp)
			{
				swing = UnityEngine.Quaternion.Lerp(UnityEngine.Quaternion.identity, swing2, tSwing);
				twist = UnityEngine.Quaternion.Lerp(UnityEngine.Quaternion.identity, twist2, tTwist);
			}
			else
			{
				swing = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.identity, swing2, tSwing);
				twist = UnityEngine.Quaternion.Slerp(UnityEngine.Quaternion.identity, twist2, tTwist);
			}
			return twist * swing;
		}
	}
	public struct FloatSpring
	{
		public static readonly int Stride = 8;

		public float Value;

		public float Velocity;

		public void Reset()
		{
			Value = 0f;
			Velocity = 0f;
		}

		public void Reset(float initValue)
		{
			Value = initValue;
			Velocity = 0f;
		}

		public void Reset(float initValue, float initVelocity)
		{
			Value = initValue;
			Velocity = initVelocity;
		}

		public float TrackDampingRatio(float targetValue, float angularFrequency, float dampingRatio, float deltaTime)
		{
			if (angularFrequency < MathUtil.Epsilon)
			{
				Velocity = 0f;
				return Value;
			}
			float num = targetValue - Value;
			float num2 = 1f + 2f * deltaTime * dampingRatio * angularFrequency;
			float num3 = angularFrequency * angularFrequency;
			float num4 = deltaTime * num3;
			float num5 = deltaTime * num4;
			float num6 = 1f / (num2 + num5);
			float num7 = num2 * Value + deltaTime * Velocity + num5 * targetValue;
			float num8 = Velocity + num4 * num;
			Velocity = num8 * num6;
			Value = num7 * num6;
			if (Mathf.Abs(Velocity) < MathUtil.Epsilon && Mathf.Abs(num) < MathUtil.Epsilon)
			{
				Velocity = 0f;
				Value = targetValue;
			}
			return Value;
		}

		public float TrackHalfLife(float targetValue, float frequencyHz, float halfLife, float deltaTime)
		{
			if (halfLife < MathUtil.Epsilon)
			{
				Velocity = 0f;
				Value = targetValue;
				return Value;
			}
			float num = frequencyHz * MathUtil.TwoPi;
			float dampingRatio = 0.6931472f / (num * halfLife);
			return TrackDampingRatio(targetValue, num, dampingRatio, deltaTime);
		}

		public float TrackExponential(float targetValue, float halfLife, float deltaTime)
		{
			if (halfLife < MathUtil.Epsilon)
			{
				Velocity = 0f;
				Value = targetValue;
				return Value;
			}
			float angularFrequency = 0.6931472f / halfLife;
			float dampingRatio = 1f;
			return TrackDampingRatio(targetValue, angularFrequency, dampingRatio, deltaTime);
		}
	}
