		public static UnityEngine.Vector3 Rotate2D(UnityEngine.Vector3 v, float angle)
		{
			UnityEngine.Vector3 result = v;
			float num = Mathf.Cos(angle);
			float num2 = Mathf.Sin(angle);
			result.x = num * v.x - num2 * v.y;
			result.y = num2 * v.x + num * v.y;
			return result;
		}

		public static UnityEngine.Vector4 NormalizeSafe(UnityEngine.Vector4 v, UnityEngine.Vector4 fallback)
		{
			if (!(v.sqrMagnitude > MathUtil.Epsilon))
			{
