		public static UnityEngine.Vector3 ClampBend(UnityEngine.Vector3 vector, UnityEngine.Vector3 reference, float maxBendAngle)
		{
			float sqrMagnitude = vector.sqrMagnitude;
			if (sqrMagnitude < MathUtil.Epsilon)
			{
				return vector;
			}
			float sqrMagnitude2 = reference.sqrMagnitude;
			if (sqrMagnitude2 < MathUtil.Epsilon)
			{
				return vector;
			}
			UnityEngine.Vector3 rhs = vector / Mathf.Sqrt(sqrMagnitude);
			UnityEngine.Vector3 vector2 = reference / Mathf.Sqrt(sqrMagnitude2);
			UnityEngine.Vector3 vector3 = UnityEngine.Vector3.Cross(vector2, rhs);
			float value = UnityEngine.Vector3.Dot(vector2, rhs);
			UnityEngine.Vector3 axis = ((vector3.sqrMagnitude > MathUtil.Epsilon) ? vector3.normalized : FindOrthogonal(vector2));
			if (Mathf.Acos(Mathf.Clamp01(value)) <= maxBendAngle)
			{
				return vector;
			}
			return QuaternionUtil.AxisAngle(axis, maxBendAngle) * reference * (Mathf.Sqrt(sqrMagnitude) / Mathf.Sqrt(sqrMagnitude2));
		}
